INSERT INTO texts VALUES(483,'Teleporte Paralelo',replace(replace('Ofereça como Tributo 1 monstro Psíquico com um Nível; Invoque por Invocação-Especial 1 monstro Psíquico de Nível 7 ou menos do seu Deck ou Deck Adicional e, depois, se o Nível original do monstro oferecido como Tributo for diferente daquele do monstro Invocado por Invocação-Especial no campo, você perde PV igual à diferença x 1000. \r\nVocê não pode Invocar por Invocação-Especial no turno em que ativar este card, exceto monstros Psíquico. \r\nVocê só pode ativar 1 "Teleporte Paralelo" por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2511,'Cucológio Labrinto',replace(replace('(Efeito Rápido): você pode descartar este card; neste turno, você pode ativar 1 Card de Armadilha Normal que foi Baixado neste turno, se você controlar um monstro "Labrinto". \r\nSe um ou mais cards forem enviados da sua mão para o Cemitério para ativar um Card de Armadilha Normal seu ou um card ou efeito "Labrinto" seu, exceto "Cucológio Labrinto", enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode adicionar este card à sua mão ou Invocá-lo por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Cucológio Labrinto" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Adicionar este card à mão ou Invocá-lo por Invocação Especial','Ativar aplicando o efeito de "Cucológio Labrinto".','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10000,'Dragão dos Dez Mil',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial ao oferecer como Tributo monstros que você controla cujo ATK & DEF combinados seja 10.000 ou mais. \r\nSe Invocado desta forma, o ATK/DEF deste card se tornam 10.000.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27551,'Inversão de Limite',replace(replace('Escolha 1 monstro com 1000 ou menos de ATK no seu Cemitério; Invoque-o por Invocação-Especial em Posição de Ataque. \r\nSe o alvo for colocado em Posição de Defesa, destrua ele e este card. \r\nQuando este card deixar o campo, destrua o alvo. \r\nQuando o alvo for destruído, destrua este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32864,'O 13º Túmulo','Um zumbi que apareceu repentinamente do lote nº 13 – um túmulo vazio.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35699,'ESPIRÃO Dormente',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao banir 3 cards "ESPIRÃO" do seu Cemitério, e não pode ser Invocado por Invocação-Especial de nenhuma outra forma. \r\nUma vez por turno, durante o turno de qualquer duelista: você pode escolher 1 card "ESPIRÃO" que você controla e até 2 cards que seu oponente controla; destrua-os. \r\nSe este card no campo for destruído em batalha ou por um efeito de card e enviado para o Cemitério: destrua tantos cards que você controla quanto possível e, se isso acontecer, Invoque por Invocação-Especial 1 "Super Agente ESPIRÃO" de sua mão, Deck ou Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39015,'Sentinela de Ataque',replace(replace('Você pode oferecer este card como Tributo; Invoque por Invocação-Especial 1 monstro da sua mão ou do Deck que especificamente liste "Ativar Modo de Ataque" em seu texto, exceto "Sentinela de Ataque" e, além disso, você não pode Invocar monstros por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto Monstros Sincro. \r\nVocê pode escolher 1 monstro com a face para cima que você controla; revele 1 Monstro Sincro no seu Deck Adicional e, se isso acontecer, até o final deste turno, o Tipo e Atributo do monstro alvo se tornam o mesmo que o do monstro revelado. \r\nVocê só pode usar cada efeito de "Sentinela de Ataque" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Alterar Tipo/Atributo','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41546,'D/D Sábio Thomas',replace(replace('Escala de Pêndulo = 6\r\n[ Efeito de Pêndulo ]\r\nDurante sua Fase Principal: você pode adicionar 1 Monstro Pêndulo "D/D" com a face para cima do seu Deck Adicional à sua mão. \r\nVocê só pode usar este efeito de "D/D Sábio Thomas" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nVocê pode escolher 1 card "D/D" na sua Zona de Pêndulo; destrua esse card e, se isso acontecer, Invoque por Invocação-Especial do seu Deck 1 monstro "D/D/D" de Nível 8 em Posição de Defesa, mas pelo resto deste turno, seus efeitos (se houver) são negados e, além disso, qualquer dano de batalha que seu oponente sofrer é diminuído pela metade. \r\nVocê só pode usar este efeito de "D/D Sábio Thomas" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41777,'Aprimoramento-Gema','Ofereça como Tributo 1 monstro "Cavaleiro-Gema" e, depois, escolha 1 monstro "Cavaleiro-Gema" no seu Cemitério; Invoque o alvo por Invocação-Especial do Cemitério.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43227,'Magnum, o Lançador Secundário',replace(replace('1 monstro Invocado por Invocação-Especial do Deck Adicional + 1 monstro na mão	\r\nVocê pode escolher 1 Magia "Polimerização" ou Magia "Fusão" no seu Cemitério; coloque esse card no fundo do Deck e, depois, compre 1 card. \r\nQuando outro card, ou seus efeitos, for ativado (Efeito Rápido): você pode banir 1 Magia "Polimerização" ou Magia "Fusão" do seu Cemitério e, depois, escolha 1 card no campo; destrua-o. \r\nVocê só pode usar cada efeito de "Magnum, o Lançador Secundário" uma vez por turno.','\r',char(13)),'\n',char(10)),'Reciclar e comprar','Banir e destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44818,'Cavalestrela Orbitael',replace(replace('(Efeito Rápido): você pode escolher 1 monstro de LUZ que você controla; ofereça-o como Tributo e, se isso acontecer, Baixe 1 Magia/Armadilha "Cavalestrela" diretamente do seu Deck. \r\nSe um monstro Dragão de LUZ de Nível 7 com a face para cima que você controla for devolvido para a mão, enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Cavalestrela Orbitael" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50755,'Círculo do Mago','Quando um monstro Mago declarar um ataque: cada duelista Invoca por Invocação-Especial 1 monstro Mago com 2000 ou menos de ATK do seu Deck em Posição de Ataque.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56889,'Duelo Entre Dimensões',replace(replace('Escolha 1 monstro "Mecanismo Antigo" que você controla; bana-o. \r\nDurante a próxima Fase de Apoio, devolva esse monstro banido para o campo e, se isso acontecer, até o final desse turno, o ATK dele se torna o dobro do seu ATK original. \r\nSe 1 ou mais "Golem do Mecanismo Antigo" ou "Golem do Mecanismo Antigo - Murro Definitivo" que você controla seriam destruídos em batalha ou por um efeito de card, em vez disso, você pode banir este card do seu Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59080,'Magia Mágica - Trovão do Julgamento',replace(replace('(Este card deve ser sempre considerado como um card "Magistus" e "Endymion".)	\r\nEnvie para o Cemitério 1 outro card "Magistus" com a face para cima que você controla, ou remova 2 Marcadores de Magia do seu campo e, depois, ative 1 desses efeitos (mas você só pode usar cada efeito de "Magia Mágica - Trovão do Julgamento" uma vez por turno);\r\n● Invoque por Invocação-Especial 1 monstro Mago da sua mão, do Deck Adicional com a face para cima ou do Cemitério.\r\n● Bana 1 outro card no campo.','\r',char(13)),'\n',char(10)),'Ativar','Remova Marcadores de Magia para ativar','Enviar 1 card para o Cemitério para ativar','Invocação Especial','Banir','','','','','','','','','','','');
INSERT INTO texts VALUES(62121,'Castelo das Ilusões Sombrias',replace(replace('VIRE: Aumenta o ATK e DEF de todos os monstros do Tipo Zumbi em 200 pontos. \r\nEnquanto este card permanecer no Campo com a face para cima, o ATK e DEF dos monstros do Tipo Zumbi continuam a aumentar em 200 pontos durante cada uma das suas Standby Phases. \r\nEste efeito continua até ao 4º turno após o card ter sido Activado.','\r',char(13)),'\n',char(10)),'Virar','Aumentar ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64865,'Codificar Mago Ciberso',replace(replace('Você pode Invocar por Invocação-Ritual este card com "Cinet Ritual".\r\nSe um Monstro Link que você controla seria usado como Matéria Link para um monstro Ciberso, este card na sua mão também pode ser usado como matéria.\r\nSe este card for enviado da sua mão ou campo para o Cemitério: você pode ativar este efeito; você não pode Invocar por Invocação-Especial pelo resto deste turno, exceto monstros Ciberso, também envie 1 monstro Ciberso do seu Deck para o Cemitério, ou, se este card for Invocado por Invocação-Ritual, ao invés disso, você pode Invocar por Invocação-Especial aquele monstro.\r\nVocê só pode usar cada um dos efeitos de "Codificar Mago Ciberso" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Enviar para o Cemitério','Enviado para o Cemitério após ser Invocado por Invocação Ritual','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64866,'Codificar Mago Ciberso',replace(replace('Você pode Invocar por Invocação-Ritual este card com "Cinet Ritual".\r\nSe um Monstro Link que você controla seria usado como Matéria Link para um monstro Ciberso, este card na sua mão também pode ser usado como matéria.\r\nSe este card for enviado da sua mão ou campo para o Cemitério: você pode ativar este efeito; você não pode Invocar por Invocação-Especial pelo resto deste turno, exceto monstros Ciberso, também envie 1 monstro Ciberso do seu Deck para o Cemitério, ou, se este card for Invocado por Invocação-Ritual, ao invés disso, você pode Invocar por Invocação-Especial aquele monstro.\r\nVocê só pode usar cada um dos efeitos de "Codificar Mago Ciberso" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Enviar para o Cemitério','Enviado para o Cemitério após ser Invocado por Invocação Ritual','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96540,'Baixo Tempo',replace(replace('Ofereça como Tributo 1 monstro com a face para cima; Invoque por Invocação-Especial do seu Deck, 1 monstro com o mesmo Tipo e Atributo originais que o monstro oferecido como Tributo tinha no campo, mas 1 Nível menor. \r\nVocê só pode ativar 1 "Baixo Tempo" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98905,'Espéctro Críptico','Se um ou mais Monstros Xyz "Críptico(a)" que você controla que tiverem Matéria Xyz forem destruídos em batalha ou por um efeito de card do oponente e enviados para o seu Cemitério: escolha 1 desses monstros; Invoque-o por Invocação-Especial e, se isso acontecer, Invoque por Invocação-Especial 1 Monstro Xyz do seu Deck Adicional com o mesmo nome que esse Monstro Xyz.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(102380,'Golem de Lava',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro deve ser Invocado por Invocação-Especial (da sua mão) no campo do seu oponente ao oferecer como Tributo 2 monstros que ele controla. \r\nVocê não pode Invocar por Invocação-Normal/Baixar no turno em que Invocar este card por Invocação-Especial. \r\nUma vez por turno, durante sua Fase de Apoio: sofra 1000 de dano.','\r',char(13)),'\n',char(10)),'Invocação Especial','Receba 1000 pontos de dano','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(109401,'Soldado da Dimensão das Trevas',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nVocê pode banir 1 card da sua mão e, depois, escolha 1 dos seus monstros de TREVAS banidos; Invoque esse monstro por Invocação-Especial com a face para cima ou com a face para baixo, em Posição de Defesa. \r\nDurante a Fase Final: cause 100 de dano ao seu oponente para cada card Baixado no campo. \r\nVocê só pode usar cada efeito de "Soldado da Dimensão das Trevas" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(111280,'Magia Negra Expandida',replace(replace('Aplique esses efeitos em sequência, de acordo com o número de "Mago Negro" e/ou "Pequena Maga Negra" no campo e nos Cemitérios.\r\n● 1+: 1 monstro Mago de TREVAS no campo ganha 1000 de ATK até o final deste turno.\r\n● 2+: Neste turno, seu oponente não pode ativar cards e efeitos em resposta à ativação dos seus Cards ou efeitos de Magia/Armadilha e, além disso, Magias/Armadilhas que você controla não podem ser destruídas pelos efeitos de card do seu oponente.\r\n● 3+: Até o final deste turno, monstros Mago de TREVAS que você controla atualmente não são afetados pelos efeitos de card do seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(114932,'Despedaçador Sísmico','Duas vezes por turno, você pode enviar 1 Card de Magia Contínua ou Armadilha Contínua com a face para cima que você controla para o Cemitério para causar 500 de dano ao seu oponente.','Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(122520,'Camarartista Pupilo do Céu',replace(replace('Durante o turno de qualquer duelista: você pode devolver 1 monstro "Camarartista" de Nível 5 ou mais que você controla para a mão; Invoque este card por Invocação-Especial da sua mão. \r\nVocê só pode usar este efeito de "Camarartista Pupilo do Céu" uma vez por turno. \r\nSe este card batalhar um monstro do oponente, esse monstro tem seus efeitos negados até o final da Etapa de Dano. \r\nAntes do cálculo de dano, se este card atacou um monstro do oponente enquanto você controlava outro monstro "Camarartista": você pode destruir esse monstro do oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(123709,'Senhor da Lança Laval',replace(replace('Você pode Invocar este card por Invocação-Normal sem oferecer Tributos. \r\nSe isso acontecer, durante a Fase Final: envie-o para o Cemitério. \r\nQuando este card no campo for destruído e enviado para o Cemitério: você pode escolher 1 de seus monstros de FOGO banidos; adicione o alvo à sua mão.','\r',char(13)),'\n',char(10)),'Invocação Normal sem Tributo','Envie este card para o Cemitério','Adicionar à mão','','','','','','','','','','','','','');
INSERT INTO texts VALUES(126218,'Dado Caveira',replace(replace('Lance um dado de seis faces. \r\nAté o final deste turno, todos os monstros que seu oponente controla atualmente perdem ATK/DEF igual ao resultado x 100.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(128454,'Camarartista Molaganso',replace(replace('Você pode banir este card do seu Cemitério e, depois, escolher 2 cards entre seus Monstros Pêndulo e/ou cards "Mago" e "Camarartista" nas suas Zonas de Pêndulo; devolva os dois para a mão. \r\nVocê só pode usar este efeito de "Camarartista Molaganso" uma vez por turno.','\r',char(13)),'\n',char(10)),'Retornar para a mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(131182,'Virada Milagrosa',replace(replace('Se você controlar "Virada Milagrosa", você não pode Invocar este card. \r\nSeu oponente não pode selecionar outro monstro com a face para cima como alvo de um ataque. \r\nSe este card for destruído em batalha, Invoque-o por Invocação-Especial no lado do campo do seu oponente no final da Fase de Batalha. \r\nSe este card for destruído pelo efeito de um Card de Magia ou Armadilha, destrua 1 monstro que seu oponente controla.','\r',char(13)),'\n',char(10)),'Invocação Especial','Destrua 1 monstro(s) que seu oponente controla','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(132308,'Princesa Rikka',replace(replace('Durante sua Fase Principal: você pode Invocar este card por Invocação-Especial da sua mão, mas enquanto ele estiver com a face para cima na Zona de Monstros, você não pode Invocar monstros por Invocação-Especial, exceto monstros Planta. \r\nQuando seu oponente ativar um efeito de monstro, enquanto você controlar um monstro "Rikka" (Efeito Rápido): você pode embaralhar no Deck este card da sua mão ou do Cemitério e oferecer como Tributo 1 monstro Planta; negue esse efeito. \r\nVocê só pode usar cada efeito de "Princesa Rikka" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(135598,'Rato de Chaves','Quando este card for destruído em batalha e enviado ao Cemitério, você pode adicionar 1 monstro do Tipo Besta de Nível 3 ou menos do seu Deck para a sua mão.','Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(146746,'Articulador Furioso de Duas Cabeças',replace(replace('2 monstros Máquina	\r\nNão pode ser usado como Matéria Link. \r\nVocê só pode usar 1 dos seguintes efeitos de "Articulador Furioso de Duas Cabeças" por turno e apenas uma vez por turno.\r\n● Durante a Fase Principal (Efeito Rápido): você pode enviar 1 monstro da sua mão ou do campo para o Cemitério e, depois, escolher 1 monstro Máquina de Nível 10 no seu Cemitério; Invoque-o por Invocação-Especial em Posição de Defesa, mas negue seus efeitos.\r\n● Se este card estiver no seu Cemitério: você pode enviar 1 card da sua mão ou do campo para o Cemitério; Invoque este card por Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(164710,'Travessuras dos Gnomos',replace(replace('Neste turno, reduza em 1 os Níveis de todos os monstros nas mãos de cada duelista (mesmo depois que eles forem Invocados/Baixados). \r\nVocê pode banir este card do Cemitério; neste turno, reduza em 1 os Níveis de todos os monstros nas mãos de cada duelista (mesmo depois que eles forem Invocados/Baixados).','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(168917,'Hepta Vylon',replace(replace('Uma vez por turno: Você pode escolher 1 Card de Monstro "Vylon" que você controla que é um Card de Equipamento; Invoque o alvo por Invocação-Especial com a face para cima em Posição de Defesa. \r\nBana-o quando ele deixar o campo.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(176392,'Protótipo de Koa''ki Meiru',replace(replace('Se um ou mais monstros "Koa''ki Meiru" com a face para cima no campo seriam destruídos durante a Fase Final, em vez disso, você pode destruir este card. \r\nQuando um ou mais monstros "Koa''ki Meiru" com a face para cima no campo forem destruídos durante a Fase Final, você pode Invocar por Invocação-Especial 1 "Ficha de Koa''ki Meiru" (Tipo Rocha/TERRA/Nível 4/ATK 1800/DEF 1800).','\r',char(13)),'\n',char(10)),'Usar o efeito de "Protótipo de Koa''ki Meiru" em vez de ser destruído?','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(176393,'Ficha de Koa''ki Meiru','Invocado por Especial com o efeito "Protótipo de Koa''ki Meiru".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(191749,'Relâmpago de Heroísmo!!',replace(replace('Bana "H - Coração Ardente", "E - Chamada de Emergência", "R - Justiça Honrada" e "O - Sobrealma" do seu Cemitério; Invoque por Invocação-Especial 1 Monstro Normal "HERÓI do Elemento" do seu Deck. \r\nTodos os Monstros Normais "HERÓI do Elemento" que você controla atualmente podem atacar seu oponente diretamente neste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(197042,'Returnia Exoirmã',replace(replace('Se todos os monstros que você controla forem monstros "Exoirmã" (mín. 1): pague 800 PV e, depois, escolha 1 card que seu oponente controla ou no Cemitério dele; bana-o e, depois, você pode aplicar 1 dos seguintes efeitos.\r\n● Imediatamente depois que este efeito resolver, Invoque por Invocação-Xyz 1 Monstro Xyz "Exoirmã" usando monstros que você controla.\r\n● Se você Invocou por Invocação-Xyz neste turno, bana 1 card que seu oponente controla.	\r\nVocê só pode ativar 1 "Returnia Exoirmã" por turno.','\r',char(13)),'\n',char(10)),'Invocação Xyz','Banir 1 card','Não fazer nada','','','','','','','','','','','','','');
INSERT INTO texts VALUES(209710,'Palhaço Meneio',replace(replace('Se você controlar pelo menos 2 outros monstros Ciberso e não tiver cards na sua mão: você pode pagar 1000 PV; compre 1 card. \r\nVocê só pode usar este efeito de "Palhaço Meneio" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(212652,'Armadilha do Escorpião Venenoso','Quando um monstro do oponente declarar um ataque: destrua aquele monstro, então cause 300 de dano em seu oponente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(213326,'E - Chamada de Emergência','Adicione 1 monstro "HERÓI do Elemento" do seu Deck à sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(218704,'Fenrir',replace(replace('Este card não pode ser Invocado, por Invocação-Normal, ou Baixado. \r\nEste card só pode ser Invocado por Invocação-Especial removendo de jogo 2 monstro da ÁGUA no seu Cemitério. \r\nSe este card destrói um monstro do seu adversário como resultado de uma batalha, salte a próxima Draw Phase do seu adversário.','\r',char(13)),'\n',char(10)),'Pular a Fase de Compra','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(220414,'Camarartista Virasoldado',replace(replace('No começo da sua Fase de Batalha: você pode colocar 1 marcador neste card (máx. 2). \r\nEste card ganha o seguinte efeito, de acordo com o número de marcadores nele.\r\n● 1: Uma vez por turno, quando um monstro do oponente declarar um ataque: você pode negar esse ataque.\r\n● 2: Você pode oferecer este card como Tributo; bana todos os monstros no campo até a 2ª Fase Final do seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(242146,'Balista de Destruição de Defesas','Se um monstro equipado com este card atacar um monstro em Posição de Defesa com a face para baixo, aumente o ATK do monstro equipado em 1500 pontos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(255998,'Guerreiro Rápido',replace(replace('Durante sua Fase Principal 1, você pode ativar o efeito deste card. \r\nSe isso acontecer, ele pode atacar seu oponente diretamente neste turno. \r\nOutros monstros não podem atacar durante o turno em que você ativar este efeito.','\r',char(13)),'\n',char(10)),'Ataque direto','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(259314,'Manopla Inzektor',replace(replace('Escolha 1 monstro "Inzektor" com a face para cima que você controla; equipe este card ao alvo. \r\nEle ganha 1000 de DEF e não pode ser destruído pelos efeitos de card do seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(263926,'Bonzo Solitário',replace(replace('Não pode ser Invocado por Invocação-Normal ou Especial se você controlar um monstro. \r\nVocê pode Invocar este card por Invocação-Especial (da sua mão) em Posição de Ataque. \r\nSe outro(s) monstro(s) for(em) \r\nInvocado(s) no seu campo enquanto você controlar este monstro: destrua este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(269012,'Colina do Criador Aprisionado',replace(replace('Monstros de Nível 10 ou mais no campo não podem ser escolhidos como alvo ou destruídos por efeitos de card. \r\nSe um monstro de Nível 10 ou mais destruir um monstro em batalha e enviá-lo para o Cemitério: o duelista que controlava o monstro destruído sofre 1000 de dano. \r\nQuando este card no campo for destruído por um efeito de card e enviado para o Cemitério: você pode adicionar 1 monstro DIVINO do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Receba 1000 pontos de dano','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(269510,'Prisão de Fogo',replace(replace('Todos os monstros Dragão no campo ganham 300 de DEF. \r\nSe qualquer Monstro Link estiver no campo, nenhum duelista pode Invocar por Invocação-Link um Monstro Link com um Valor Link menor que o maior Valor Link no campo. \r\nMonstros, exceto Monstros Link, não podem atacar. \r\nAplique os seguintes efeitos enquanto 2 ou mais Monstros Link Ciberso estiverem no campo.\r\n● Negue os efeitos ativados de monstros Ciberso.\r\n● Monstros Ciberso não podem atacar, não podem ser escolhidos como alvo de ataques e não podem ser escolhidos como alvo de efeitos de card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(276357,'Salvação Shinobird',replace(replace('Se um ou mais monstros Espírito com a face para cima que você controla forem devolvidos para a sua mão enquanto este card estiver com a face para cima no campo (exceto durante a Etapa de Dano): você pode escolher 1 card que seu oponente controla; destrua-o. \r\nQuando um monstro do oponente declarar um ataque: você pode banir 1 monstro Espírito do seu Cemitério; negue o ataque e, depois, encerre a Fase de Batalha. \r\nVocê só pode usar cada efeito de "Salvação Shinobird" uma vez por turno.','\r',char(13)),'\n',char(10)),'Destruir 1 card','Negar o ataque','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(282886,'Sirena Abisnariz',replace(replace('Quando este card destruir um monstro do oponente em batalha e enviá-lo para o Cemitério: você pode descartar 1 monstro de ÁGUA para o Cemitério; Invoque por Invocação-Especial 1 monstro "Sirena" do seu Deck com a face para cima em Posição de Defesa. \r\nVocê só pode usar o efeito de "Sirena Abisnariz" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(284224,'Dois Avatares - Mitsu-Jaku Edificado',replace(replace('"Pés dos Dois Avatares - Kokoku" + 2 monstros "Dois Avatares"	\r\nNa primeira vez que cada Monstro de Fusão "Dois Avatares" que você controla seria destruído em batalha a cada turno, ele não é destruído. \r\nUma vez por turno, durante sua Fase Principal: você pode devolver todas as Magias e Armadilhas que seu oponente controla para a mão. \r\nQuando um efeito de monstro for ativado no campo do seu oponente enquanto você controlar 2 ou mais Monstros de Fusão (Efeito Rápido): você pode destruir esse monstro. \r\nVocê só pode usar este efeito de "Dois Avatares - Mitsu-Jaku Edificado" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(286392,'Guerreiro Jato',replace(replace('"Jato Sincron" + 1 ou mais monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro: você pode escolher 1 card que seu oponente controla; devolva-o para a mão. \r\nSe este card estiver no seu Cemitério: você pode oferecer como Tributo 1 monstro de Nível 2 ou menos; Invoque este card por Invocação-Especial em Posição de Defesa, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar cada efeito de "Guerreiro Jato" uma vez por turno.','\r',char(13)),'\n',char(10)),'Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(291414,'Dragão das Vontades Convergentes',replace(replace('Não pode ser usado como Matéria Sincro, exceto para a Invocação-Sincro de um monstro "Majestoso". \r\nO nome deste card se torna "Dragão Majestoso" enquanto estiver no campo ou no Cemitério. \r\nQuando você comprar este card: você pode revelá-lo; Invoque-o por Invocação-Especial da sua mão e, depois, se você controlar um Monstro Sincro Dragão de Nível 8 ou mais, você pode Invocar por Invocação-Especial 1 monstro Dragão de Nível 1 do seu Deck. \r\nVocê só pode Invocar um ou mais "Dragão das Vontades Convergentes" por Invocação-Especial uma vez por turno.','\r',char(13)),'\n',char(10)),'','Invocar por Invocação Especial 1 monstro Dragão de Nível 1 do seu Deck?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(293542,'T.G. Lobo de Guerra',replace(replace('Quando um ou mais monstros de Nível 4 ou menos forem Invocados por Invocação-Especial (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão. \r\nUma vez por turno, durante a Fase Final, se este card estiver no Cemitério porque foi destruído no campo e enviado para lá neste turno: você pode adicionar 1 monstro "T.G." do seu Deck à sua mão, exceto "T.G. Lobo de Guerra".','\r',char(13)),'\n',char(10)),'Invocação Especial','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(295517,'Um Oceano Lendário',replace(replace('(Este card deve ser sempre considerado como "Umi".)	\r\nTodos os monstros de ÁGUA no campo ganham 200 de ATK/DEF. \r\nReduza em 1 o Nível de todos os monstros de ÁGUA na mão e no campo dos dois duelistas.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(296499,'Instruções da Tribo',replace(replace('Ative este card ao declarar 1 Tipo de Monstro. \r\nOs monstros desse Tipo não podem declarar ataques. \r\nUma vez por turno, durante sua Fase de Apoio, ofereça 1 monstro como Tributo ou destrua este card.','\r',char(13)),'\n',char(10)),'Oferecer 1 monstro como Tributo para manter "Instruções da Tribo"?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(298846,'Trapestrela Colchica',replace(replace('1 monstro "Trapestrela" que não seja Link	\r\nVocê só pode Invocar um ou mais "Trapestrela Colchica" por Invocação-Especial uma vez por turno. \r\nQuando um monstro for destruído em batalha envolvendo um monstro "Trapestrela" seu, enquanto este card estiver no seu Cemitério: você pode banir este card e, depois, escolha esse monstro destruído; cause dano ao seu oponente igual ao ATK desse monstro. \r\nVocê só pode usar este efeito de "Trapestrela Colchica" uma vez por turno.','\r',char(13)),'\n',char(10)),'Efeito de dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(303660,'Amplificador',replace(replace('Só pode ser equipado a "Jinzo". \r\nA ativação e o efeito deste card não podem ser negados. \r\nO efeito do monstro equipado "Os Cards de Armadilha, bem como seus efeitos no campo, não podem ser ativados. Negue todos os efeitos de Armadilha no campo." se torna "Seu oponente não pode ativar Cards de Armadilha, bem como seus efeitos no campo. Negue todos os efeitos de Armadilha que seu oponente controla." Quando este card deixar o campo, destrua o monstro equipado.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(313513,'Mecanismo de Magia',replace(replace('Envie 3 cards "Mecanismo Antigo" que você controla para o Cemitério. \r\nVocê pode Invocar por Invocação-Especial até 1 "Golem do Mecanismo Antigo" da sua mão e 1 do seu Deck, ignorando as condições de Invocação. \r\nDepois, destrua todos os monstros que você controla, exceto "Golem do Mecanismo Antigo". \r\nVocê não pode Invocar por Invocação-Normal ou Baixar até o final do seu próximo turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(324483,'Espadachim das Chamas Definitivo',replace(replace('"Espadachim das Chamas" + "Dragão das Chamas Lutador"	\r\nVocê pode escolher 1 monstro que seu oponente controla; destrua-o e, se isso acontecer, cause 500 de dano ao seu oponente. \r\nEste é um Efeito Rápido se este card estiver equipado com um Card de Equipamento. \r\nNo começo da Etapa de Dano, se este card batalhar: você pode dobrar o ATK deste card até o final deste turno mas, se isso acontecer, destrua-o durante a Fase Final deste turno. \r\nVocê só pode usar cada efeito de "Espadachim das Chamas Definitivo" uma vez por turno.','\r',char(13)),'\n',char(10)),'Destruir um monstro do oponente','Dobrar ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(327051,'Vritra Magistus',replace(replace('Escolha 1 monstro "Magistus" de Nível 4 ou menos no seu Cemitério; Invoque-o por Invocação-Especial. \r\nSe um ou mais cards "Magistus" na sua Zona de Magias & Armadilhas seriam destruídos por um efeito de card do seu oponente, em vez disso, você pode banir este card do seu Cemitério. \r\nVocê só pode usar cada efeito de "Vritra Magistus" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(336369,'Esquil Gusto','Quando este card for destruído por um efeito de card e enviado para o Cemitério: Você pode Invocar por Invocação-Especial 1 monstro "Gusto" de Nível 5 ou mais do seu Deck.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(336601,'Gardna Lunar',replace(replace('Se seu oponente controlar 2 ou mais monstros, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Gardna Lunar" por Invocação-Especial uma vez por turno desta forma. \r\nSe este card for Invocado por Invocação-Normal ou Especial e seu oponente controlar um monstro: você pode escolher 1 monstro de LUZ de Nível 4 no seu Cemitério, exceto "Gardna Lunar"; adicione-o à sua mão. \r\nVocê só pode usar este efeito de "Gardna Lunar" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(340002,'Camarartista Martelefante',replace(replace('Se você controlar 2 ou mais cards "Camarartista", você pode Invocar este card por Invocação-Normal sem oferecer Tributo. \r\nNão pode atacar a não ser que você controle outro card "Camarartista". \r\nQuando este card declarar um ataque: você pode devolver para a mão todos os Cards de Magia e Armadilha que seu oponente controla.','\r',char(13)),'\n',char(10)),'Invocação Normal sem Tributo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(342673,'Mago Negro, o Mago da Magia Negra',replace(replace('O nome deste card se torna "Mago Negro" enquanto estiver no campo. \r\nVocê só pode usar cada um dos seguintes efeitos de "Mago Negro, o Mago da Magia Negra" uma vez por turno. \r\nSe "Sarcófago Brilhante" estiver no campo: você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe este card for destruído por um efeito de card e um monstro de Nível 5 ou mais estiver no campo: você pode Invocar este card por Invocação-Especial e, depois, você pode Baixar 1 Magia/Armadilha do seu Deck que mencione "Mago Negro".','\r',char(13)),'\n',char(10)),'Invocação Especial','Invocação Especial','Colocar uma Magia/Armadilha?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(359563,'Hordeum Maligno Pesadelo',replace(replace('2 monstros de TREVAS de Nível 4	\r\nQuando seu oponente Invocar um ou mais monstros por Invocação-Especial (exceto durante a Etapa de Dano): você pode desassociar 1 matéria deste card; coloque os monstros Invocados por Invocação-Especial com a face para baixo em Posição de Defesa.','\r',char(13)),'\n',char(10)),'Mudar para Posição de Defesa com a face para baixo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(365213,'Chegar em Luz',replace(replace('Quando este card for ativado: coloque 1 monstro Dragão de Nível 1 da sua mão ou do Deck no topo do Deck. \r\nNenhum duelista pode devolver "Dragão da Poeira Estelar", ou um Monstro Sincro que o mencione, do campo para o Deck Adicional. \r\nSe um ou mais Monstros Sincro forem Invocados por Invocação-Especial (exceto durante a Etapa de Dano): você pode aplicar 1 desses efeitos, mas você não pode aplicar esse mesmo efeito de "Chegar em Luz" novamente neste turno.\r\n● Compre 1 card.\r\n● Invoque por Invocação-Especial 1 Regulador da sua mão.','\r',char(13)),'\n',char(10)),'Aplicar 1 efeito','Compre 1 card(s)','Invoque por Invocação Especial 1 Regulador(es) da sua mão','','','','','','','','','','','','','');
INSERT INTO texts VALUES(368382,'Dinonévoa Bráquio',replace(replace('Escala de Pêndulo = 6\r\n[ Efeito de Pêndulo ]\r\nUma vez, enquanto este card estiver na sua Zona de Pêndulo, você pode negar um efeito de card ativado que escolhe como alvo outro(s) card(s) "Dinonévoa" que você controla e, depois, destrua este card.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe você não controlar "Dinonévoa Bráquio" na sua Zona de Monstros e seu oponente controlar um monstro que tenha o maior ATK no campo (mesmo em um empate), você pode Invocar este card por Invocação-Especial (da sua mão).','\r',char(13)),'\n',char(10)),'Usar o efeito de "Dinonévoa Bráquio"?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(373085,'Hinista Inflamada',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode enviar cards do topo do Deck do seu oponente para o Cemitério, igual ao número de cards que ele controla. \r\nSe este card for Invocado por Invocação-Especial: você pode enviar cards do topo do seu Deck para o Cemitério, igual ao número de cards que seu oponente controla. \r\nVocê só pode usar este efeito de "Hinista Inflamada" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(387282,'Irmã Gagaga',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode adicionar 1 Card de Magia/Armadilha "Gagaga" do seu Deck à sua mão. \r\nVocê pode escolher 1 outro monstro "Gagaga" que você controla; até o final deste turno, os Níveis desse monstro e deste card se tornam igual aos Níveis combinados dos dois. \r\nVocê só pode usar este efeito de "Irmã Gagaga" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Alterar Nível','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(402416,'Obliterar!!! Chamas',replace(replace('Um monstro de Nível 10 ou mais no campo com "Exodia" em seu nome original ganha esses efeitos.\r\n● Você pode pagar metade dos seus PV; destrua tantos cards nas Zonas de Magias & Armadilhas quanto possível e, depois, equipe 5 monstros "O Proibido" da sua mão e/ou do Deck a este card como Magias de Equipamento que concedem a ele 2000 de ATK cada e, além disso, você não pode ativar outros efeitos de cards pelo resto deste turno.\r\n● Se este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente.','\r',char(13)),'\n',char(10)),'O efeito de "Obliterar!!! Chamas" está sendo aplicado.','Destruir Magias/Armadilhas no campo e, depois, equipar monstros "O Proibido"','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(402568,'Wattgirafa',replace(replace('Este card pode atacar diretamente. \r\nSe este card causar dano de batalha ao seu oponente em um ataque direto: seu oponente não pode ativar cards ou efeitos até o final deste turno.','\r',char(13)),'\n',char(10)),'Seu oponente não pode ativar cards ou efeitos','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(403847,'A Força A.','Todos os monstros do Tipo Guerreiro que você controla ganham 200 de ATK para cada monstro do Tipo Guerreiro ou Mago que você controla.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(410904,'Despertar dos Possuídos - Rasenryu',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão ou do Deck) ao enviar para o Cemitério 1 monstro Mago com a face para cima que você controla e 1 monstro de VENTO de Nível 4 ou menos com a face para cima que você controla. \r\nVocê só pode usar cada um dos seguintes efeitos de "Despertar dos Possuídos - Rasenryu" uma vez por turno. \r\nQuando este card for Invocado por Invocação-Especial por seu efeito: você pode devolver 1 card que seu oponente controla para a mão. \r\nSe este card for enviado do campo para o Cemitério: você pode adicionar 1 card "Arte Espiritual do Vento" ou 1 Magia/Armadilha "Possuído(a)" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(423585,'Monge Invocador',replace(replace('Enquanto este card estiver com a face para cima no campo, ele não pode ser oferecido como Tributo. \r\nSe este card for Invocado por Invocação-Normal ou Virar: coloque este card em Posição de Defesa. \r\nUma vez por turno: você pode descartar 1 Magia; Invoque por Invocação-Especial 1 monstro de Nível 4 do seu Deck, mas esse monstro não pode atacar neste turno.','\r',char(13)),'\n',char(10)),'Mudar para Posição de Defesa','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(423705,'Gearfried, o Cavaleiro de Ferro',replace(replace('Se qualquer duelista equipar um ou mais Cards de Equipamento a este card: destrua esse(s) \r\nCard(s) de Equipamento.','\r',char(13)),'\n',char(10)),'Destruir Cards de Equipamento','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(423706,'Gearfried, o Cavaleiro de Ferro',replace(replace('Se qualquer duelista equipar um ou mais Cards de Equipamento a este card: destrua esse(s) \r\nCard(s) de Equipamento.','\r',char(13)),'\n',char(10)),'Destruir Cards de Equipamento','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(425934,'Goblin da Ganância','Enquanto este card permanecer no Campo com a face para cima, nenhum jogador pode activar um efeito que é activado descartando da sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(433377,'Blitzclique - Líder Escalonado',replace(replace('Se um ou mais cards forem destruídos por um efeito de card "Blitzclique" seu (exceto durante a Etapa de Dano): você pode escolher 1 monstro Trovão no seu Cemitério; adicione-o à sua mão. \r\nDurante sua Fase Principal: você pode Invocar por Invocação-Especial 1 monstro Trovão da sua mão e, depois, destrua este card. \r\nSe um ou mais cards forem destruídos por um efeito de card "Blitzclique" seu, enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode adicionar este card à sua mão. \r\nVocê só pode usar cada efeito de "Blitzclique - Líder Escalonado" uma vez por turno.','\r',char(13)),'\n',char(10)),'Efeito de recuperação','Invocação Especial','Retornar para a mão','','','','','','','','','','','','','');
INSERT INTO texts VALUES(440556,'Tubarão Bahamut',replace(replace('2 monstros de ÁGUA de Nível 4	\r\nUma vez por turno: você pode desassociar 1 matéria deste card; Invoque por Invocação-Especial 1 Monstro Xyz de ÁGUA de Classe 3 ou menos do seu Deck Adicional. \r\nEste card não pode atacar pelo resto deste turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(458748,'O Livro da Lei',replace(replace('Ofereça como Tributo 1 monstro "Invokado(a)"; Invoque por Invocação-Especial 1 monstro "Invokado(a)" do seu Deck Adicional com um Atributo original diferente que o desse monstro. \r\n(Isso é considerado uma Invocação-Fusão.) \r\nVocê só pode ativar 1 "O Livro da Lei" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(464362,'Tigre Peladura',replace(replace('"Diabrete de Lâminas Afiadas" + 1 ou mais monstros "Fofanimal"	\r\nQuando este card for Invocado por Invocação-Fusão: você pode escolher cards no campo, até o número de Matérias de Fusão usados para a sua Invocação-fusão; destrua-os. \r\nTodos os monstros "Peladura" que você controla ganham 300 de ATK para cada monstro "Fofanimal" e monstro "Peladura" que você controla. \r\nVocê só pode controlar 1 "Tigre Peladura".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(473469,'Queda de Neve',replace(replace('Você pode ativar este card quando 1 ou mais dos seus Cards de Armadilha forem destruídos e enviados do campo para o Cemitério por um efeito de card que seu oponente controla. \r\nDestrua 1 Card de Magia ou Armadilha no campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(487395,'Espírito da Água','Este antigo espírito da água assombra os monólitos glaciais da Antártica. Ele tem o poder de se infiltrar nos poros de qualquer substância e resfriá-la até os ossos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(494922,'Samurai Superpesado Senhor da Guerra Susanowo',replace(replace('1 Regulador do Tipo Máquina + 1 ou mais monstros "Samurai Superpesados" não-Reguladores	\r\nEste card pode atacar enquanto estiver com a face para cima em Posição de Defesa. \r\nSe isso acontecer, aplique a DEF dele no cálculo de dano. \r\nUma vez por turno, durante o turno de qualquer duelista, se você não tiver Cards de Magia/Armadilha no seu Cemitério: você pode escolher 1 Card de Magia/Armadilha no Cemitério do seu oponente; Baixe-o no seu lado do campo, mas bana-o quando ele deixar o campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(525110,'Prisiomate-Cereja',replace(replace('Quando este card for destruído em batalha e enviado ao Cemitério, você pode Invocar por Invocação-Especial até 2 monstros "Prisiomate" do seu Deck. \r\nEles não podem ser usados como Monstros-Matéria Sincro neste turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Invocar outro monstro por Invocação Especial?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(545781,'Mahaama, o Dragão Fada',replace(replace('Durante o turno do seu oponente, quando qualquer duelista sofrer dano de batalha: você pode Invocar este card por Invocação-Especial da sua mão e, depois, aplique 1 desses efeitos.\r\n● Ganhe PV igual a esse dano de batalha.\r\n● Cause dano ao seu oponente igual a esse dano de batalha.','\r',char(13)),'\n',char(10)),'Ganhar PV','Causar dano','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(549481,'Rato Prevenido','Esta criatura é protegida por uma rigída camada de pêlos e é excelente ao defender-se.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(561300,'Víbora Venenosa',replace(replace('Você pode revelar este card na sua mão; Invoque-o por Invocação-Especial, ou se seu oponente não controlar nenhum monstro, em vez disso, Invoque-o por Invocação-Especial no campo dele em Posição de Defesa. \r\nUma vez por turno, durante sua Fase de Apoio: sofra 500 de dano. \r\nSe este card for banido, ou enviado para o Cemitério por um efeito de card: você pode escolher 1 Magia/Armadilha Baixada que seu oponente controla; destrua-a. \r\nSeu oponente não pode ativar esse card em resposta à ativação deste efeito. \r\nVocê só pode usar este efeito de "Víbora Venenosa" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Efeito de dano','Efeito de destruição','','','','','','','','','','','','','');
INSERT INTO texts VALUES(564541,'Dragão Totem',replace(replace('Pode ser considerado como 2 Tributos para a Invocação-Tributo de um monstro Dragão. \r\nUma vez por turno, durante sua Fase de Apoio, se este card estiver no seu Cemitério e todos os monstros no seu Cemitério forem Dragão: você pode Invocar este card por Invocação-Especial em Posição de Ataque, mas bana-o quando ele deixar o campo. \r\nVocê não pode controlar nenhum monstro para ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(572850,'Lagrimentiara Scheiren',replace(replace('Durante sua Fase Principal: você pode Invocar este card por Invocação-Especial da sua mão e, se isso acontecer, envie 1 monstro da sua mão para o Cemitério e, depois, envie os 3 cards do topo do seu Deck para o Cemitério. \r\nSe este card for enviado para o Cemitério por um efeito de card (exceto durante a Etapa de Dano): você pode Invocar por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional, ao colocar as Matérias de Fusão mencionadas nele da sua mão, do campo e/ou do Cemitério, incluindo este card do seu Cemitério, no fundo do Deck em qualquer ordem. \r\nVocê só pode usar cada efeito de "Lagrimentiara Scheiren" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(575512,'Circuito PSÍ-Armação',replace(replace('Se um ou mais monstros "PSÍ-Armação" forem Invocados por Invocação-Especial no seu lado do campo (exceto durante a Etapa de Dano), você pode: imediatamente depois que este efeito resolver, Invoque 1 Monstro Sincro por Invocação-Sincro, usando apenas monstros "PSÍ-Armação" que você controla. \r\nNo começo da Etapa de Dano, se um monstro "PSÍ-Armação" que você controla batalhar um monstro do oponente: você pode descartar 1 monstro "PSÍ-Armação"; até o final deste turno, seu monstro que está batalhando ganha ATK igual ao ATK do monstro descartado.','\r',char(13)),'\n',char(10)),'Faça uma Invocação Sincro usando seus monstros "Circuito PSÍ-Armação" como Matéria','Aumentar ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(581014,'Daigusto Emeral',replace(replace('2 monstros de Nível 4	\r\nUma vez por turno: você pode desassociar 1 matéria deste card e, depois, ative 1 desses efeitos;\r\n● Escolha 3 monstros no seu Cemitério; embaralhe os 3 no Deck e, depois, compre 1 card.\r\n● Escolha 1 Monstro que não seja de Efeito no seu Cemitério; Invoque o alvo por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Ativar 1 efeito','Reciclar e comprar','Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(595626,'Ankuriboh',replace(replace('Quando um monstro do oponente declarar um ataque: Você pode descartar este card e, então, escolher 1 monstro no Cemitério, exceto este card; Invoque-o por Invocação-Especial para o seu campo, mas envie-o para o Cemitério durante a Fase Final. \r\nSe este card for destruído por batalha ou efeito de card e enviado para o Cemitério: Você pode adicionar 1 "Reviver Monstro" do seu Deck ou Cemitério à sua mão durante a Fase Final deste turno. \r\nVocê só pode usar cada efeito de "Ankuriboh" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar um monstro por Invocação Especial','Adicionar "Card de Magia "Reviver Monstro"" à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(596051,'Presa de Serpente','Diminua em 500 a DEF de 1 monstro selecionado durante o turno em que este card for ativado.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(598988,'Dragão Arco-Íris Pernicioso',replace(replace('Este card não pode ser Invocado por Invocação-Normal ou Baixado. \r\nEste card não pode ser Invocado por Invocação-Especial, exceto ao remover de jogo 1 "Dragão Arco-Íris" da sua mão ou Deck. \r\nSó pode haver 1 monstro "Pernicioso(a)" com a face para cima no campo. \r\nOutros monstros que você controla não podem declarar um ataque. \r\nSe não houver nenhum Card de Magia de Campo com a face para cima no campo, destrua este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(601193,'Virgil, a Estrela de Pedra do Abismo Ardente',replace(replace('1 Regulador + 1 ou mais monstros não-Reguladores	\r\nVocê só pode controlar 1 "Virgil, a Estrela de Pedra do Abismo Ardente". \r\nUma vez por turno: você pode descartar 1 card "Abismo Ardente" e, depois, escolher 1 card que seu oponente controla ou no Cemitério dele; embaralhe-o no Deck. \r\nSe este card no campo for destruído em batalha ou por um efeito de card e enviado para o Cemitério: você pode comprar 1 card. \r\nVocê só pode usar este efeito de "Virgil, a Estrela de Pedra do Abismo Ardente" uma vez por turno.','\r',char(13)),'\n',char(10)),'Retornar ao Deck','Comprar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(612115,'Besta Gladiadora Retiari',replace(replace('Quando este card for Invocado por Invocação-Especial pelo efeito de um monstro "Besta Gladiadora": você pode escolher 1 card no Cemitério do seu oponente; bana-o. \r\nNo final da Fase de Batalha, se este card batalhou: você pode embaralhá-lo no Deck; Invoque por Invocação-Especial 1 monstro "Besta Gladiadora" do seu Deck, exceto "Besta Gladiadora Retiari".','\r',char(13)),'\n',char(10)),'Banir','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(613013,'Tubarão Veiss',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode oferecer como Tributo 1 monstro Peixe; Invoque por Invocação-Especial 1 monstro Peixe "Tubarão" do seu Deck e, além disso, você não pode Invocar por Invocação-Especial pelo resto deste turno, exceto monstros de ÁGUA. \r\nVocê só pode usar este efeito de "Tubarão Veiss" uma vez por turno. \r\nUm Monstro Xyz "Dragonete Tubarão" que tenha este card como matéria ganha este efeito.\r\n● Uma vez por turno, quando um Card de Magia/Armadilha ou seus efeitos forem ativados (Efeito Rápido): você pode desassociar 2 matérias deste card; negue esse efeito e, se isso acontecer, destrua esse card.','\r',char(13)),'\n',char(10)),'Invocação Especial','Negar a ativação de um efeito de Magia/Armadilha (Tubarão Veiss)','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(613496,'Afinação Excessiva',replace(replace('Se você controlar um Regulador: Invoque por Invocação-Especial 1 Regulador da sua mão, do Deck ou do Cemitério e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno depois que este card resolver, exceto Monstros Sincro. \r\nVocê só pode ativar 1 "Afinação Excessiva" por turno.','\r',char(13)),'\n',char(10)),'Ativar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(637216,'Expresso Monstro',replace(replace('Você pode escolher 1 monstro com a face para cima que você controla; envie 1 monstro do seu Deck Adicional para o Cemitério com o mesmo Tipo original que o desse monstro com a face para cima, mas pelo resto deste turno, você não pode Invocar monstros por Invocação-Especial, exceto monstros com o mesmo Tipo original que o do monstro enviado para o Cemitério por este efeito. \r\nVocê só pode usar este efeito de "Expresso Monstro" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(645087,'Dispositivo Ciberso',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode escolher 1 monstro de Nível 2 ou menos no seu Cemitério; Invoque-o por Invocação-Especial em Posição de Defesa, mas seus efeitos são negados. \r\nSe este card for enviado do campo para o Cemitério: você pode Invocar por Invocação-Especial 1 "Ficha de Dispositivo" (Ciberso/LUZ/Nível 2/ATK 0/DEF 0). \r\nVocê só pode usar este efeito de "Dispositivo Ciberso" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invoque por Invocação Especial um monstro do Cemitério','Invoque por Invocação Especial 1 Ficha','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(645088,'Ficha de Dispositivo','Invocada por Invocação-Especial com o efeito "Dispositivo Ciberso".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(645794,'Majespectro Rã - Ogama',replace(replace('Escala de Pêndulo = 5\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nQuando este card for Invocado por Invocação-Normal ou Especial: você pode Baixar 1 Card de Magia/Armadilha "Majespectro" diretamente do seu Deck, mas ele não pode ser ativado neste turno. \r\nVocê só pode usar este efeito de "Majespectro Rã - Ogama" uma vez por turno. \r\nEnquanto este card estiver na sua Zona de Monstros, seu oponente não pode escolhê-lo como alvo de efeitos de card e, além disso, ele não pode ser destruído pelos efeitos de card do seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(652362,'Amonite Alienígena','Quando este card for Invocado por Invocação-Normal: você pode escolher 1 monstro "Alienígena" de Nível 4 ou menos no seu Cemitério; Invoque-o por Invocação-Especial, mas destrua-o durante a Fase Final.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(653675,'Elevação Sincro',replace(replace('Escolha qualquer número de Monstros Sincro Dragão de Nível 7 ou 8 no seu Cemitério; Invoque-os por Invocação-Especial em Posição de Defesa, mas o Nível deles se torna 1 e seus efeitos são negados e, além disso, você não pode Invocar monstros por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto Monstros Sincro. \r\nQuando um Monstro Sincro que você controla for destruído em batalha: você pode banir este card do seu Cemitério; Invoque por Invocação-Especial 1 "Dragão Carmesim" do seu Deck Adicional. \r\nVocê só pode usar cada efeito de "Elevação Sincro" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(674561,'Erupção Negra','Escolha 1 monstro de TREVAS com 1500 ou menos de ATK no seu Cemitério; adicione o alvo à sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(675319,'Sinal Zodíaco',replace(replace('Todos os monstros "Zoodíaco(a)" que você controla ganham 300 de ATK e DEF. \r\nMonstros que seu oponente controla não podem escolher monstros do Tipo Besta-Guerreira com a face para cima que você controla como alvo de ataques, exceto o monstro do Tipo Besta-Guerreira que você controla com o maior ATK (em caso de empate, qualquer um). \r\nUma vez por turno, se um ou mais monstros "Zoodíaco(a)" que você controla seriam destruídos por um efeito de card, você pode destruir 1 monstro na sua mão ou no campo, em vez de 1 monstro "Zoodíaco(a)".','\r',char(13)),'\n',char(10)),'Usar o efeito de "Sinal Zodíaco" para destruir outro monstro em vez disso?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(691925,'Recarga Solar','Descarte 1 monstro "Luminoso(a)"; compre 2 cards e, depois, envie os 2 cards do topo do seu Deck para o Cemitério.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(698785,'Dragão da Trovoada Final',replace(replace('2 Monstros Normais de Nível 8	\r\nUma vez por turno: você pode desassociar 1 Matéria Xyz deste card; destrua todos os outros monstros no campo.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(703897,'Crescendo Orcust',replace(replace('Quando um Card de Magia/Armadilha ou efeito de monstro for ativado enquanto você controlar um Monstro Link "Orcust": negue a ativação e, se isso acontecer, bana esse card. \r\nVocê pode banir este card do seu Cemitério; adicione 1 monstro Máquina de TREVAS do seu Deck ou banimento à sua mão. \r\nVocê não pode Invocar por Invocação-Especial no turno em que ativar este efeito, exceto monstros Máquina de TREVAS. \r\nVocê só pode usar 1 efeito de "Crescendo Orcust" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(706925,'Atirador Atlante',replace(replace('Quando este card causar dano de batalha ao seu oponente: você pode Invocar por Invocação-Especial 1 monstro Serpente Marinha "Atlante" de Nível 4 ou menos do seu Deck, exceto "Atirador Atlante". \r\nSe este card for enviado para o Cemitério para ativar um efeito de um monstro de ÁGUA: escolha 1 card Baixado que seu oponente controla; destrua o alvo.','\r',char(13)),'\n',char(10)),'Invocação Especial','Destruir 1 card Baixado','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(712559,'Aldeia Amazoness',replace(replace('Todos os monstros "Amazoness" ganham 200 de ATK. \r\nUma vez por turno, quando um monstro "Amazoness" for destruído em batalha ou por um efeito de card e enviado para o Cemitério: você pode Invocar por Invocação-Especial 1 monstro "Amazoness" do seu Deck com um Nível igual ou menor que o monstro "Amazoness" no Cemitério.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(720147,'Mordida do Chefe Generaidor',replace(replace('Ofereça como Tributo qualquer número de monstros "Generaidor" e, depois, escolha 1 Monstro Xyz com a face para cima que você controla; associe a ele exatamente esse número de monstros "Generaidor" da sua mão, do campo e/ou do Cemitério, exceto os monstros oferecidos como Tributo para ativar este efeito. \r\nVocê só pode ativar 1 "Mordida do Chefe Generaidor" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(732302,'Templo de Crânios','Um templo misterioso de crânios e ossos que atrai inimigos confiantes.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(734741,'Rubic, Malebranche do Abismo Ardente',replace(replace('Se você controlar um monstro que não seja um monstro "Abismo Ardente", destrua este card. \r\nNão pode ser usado como Matéria Sincro, exceto para a Invocação-Sincro de um Monstro Sincro "Abismo Ardente". \r\nSe você não controlar Cards de Magia/Armadilha: você pode Invocar este card por Invocação-Especial da sua mão. \r\nVocê só pode usar este efeito de "Rubic, Malebranche do Abismo Ardente" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(739444,'Vorticular Tamborgão',replace(replace('3 monstros Dragão de TREVAS	\r\nSe este card for Invocado por Invocação-Especial: você pode comprar 1 card. \r\nVocê só pode usar este efeito de "Vorticular Tamborgão" uma vez por turno. \r\nSe este efeito resolver, as Zonas de Monstros não utilizadas para as quais este card apontar não podem ser usadas pelo resto deste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(744887,'Utgarda, Chefe Generaidor da Desilusão',replace(replace('Você só pode controlar 1 "Utgarda, Chefe Generaidor da Desilusão". \r\n(Efeito Rápido): você pode oferecer como Tributo 2 monstros "Generaidor" e/ou monstros Rocha e, depois, escolha 1 card no campo; bana-o. \r\nVocê só pode usar este efeito de "Utgarda, Chefe Generaidor da Desilusão" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(756652,'Doron','Este monstro se divide em dois e ataca de lados opostos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(759393,'Hiita, a Encantadora do Fogo','VIRE: Escolha 1 monstro de FOGO que seu oponente controla; tome o controle desse monstro enquanto este card estiver com a face para cima no campo.','Tome o controle de 1 monstro de FOGO que seu oponente controla','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(759394,'Hiita, a Encantadora do Fogo','VIRE: Escolha 1 monstro de FOGO que seu oponente controla; tome o controle desse monstro enquanto este card estiver com a face para cima no campo.','Tome o controle de 1 monstro de FOGO que seu oponente controla','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(759395,'Hiita, a Encantadora do Fogo','VIRE: Escolha 1 monstro de FOGO que seu oponente controla; tome o controle desse monstro enquanto este card estiver com a face para cima no campo.','Tome o controle de 1 monstro de FOGO que seu oponente controla','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(770365,'Imperatriz da Profecia',replace(replace('2 monstros de Nível 5 do Tipo Mago	\r\nEste card ganha 300 de ATK para cada Matéria Xyz associada a um monstro que você controla. \r\nUma vez por turno: você pode desassociar 1 Matéria Xyz deste card; embaralhe seu Deck e, depois, escave os 5 cards do topo do seu Deck, destrua monstros no campo até o número de cards "Livro de Magia" escavados e, além disso, depois, coloque os cards escavados no topo do Deck em qualquer ordem.','\r',char(13)),'\n',char(10)),'Revelar o Deck','Destruir um monstro no campo?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(786906,'Hora Fatídica','Escolha 1 monstro que não pode ser Invocado por Invocação-Normal/Baixado em qualquer Cemitério; Invoque-o por Invocação-Especial.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(799183,'Escudo do Super Soldado',replace(replace('Quando um Card de Magia/Armadilha ou efeito de monstro for ativado que escolha como alvo um ou mais monstros no campo, enquanto você controlar um monstro "Soldado do Lustro Negro" (ou "Soldado do Brilho Negro - Enviado do Princípio"): negue a ativação e, se isso acontecer, destrua esse card. \r\nSe este card estiver no seu Cemitério: você pode remover 1 Marcador de Magia do seu lado do campo; Baixe este card, mas bana-o quando ele deixar o campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(811734,'D/D/D Alteração do Pacto',replace(replace('Quando um monstro do oponente declarar um ataque: ative 1 desses efeitos;\r\n● Bana 1 monstro "D/D/D" do seu Cemitério e, se isso acontecer, o monstro atacante perde ATK igual ao ATK do monstro banido.\r\n● Adicione 1 Monstro Pêndulo "D/D" de Nível 4 ou menos do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Banir 1 monstro','Procurar no Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(816427,'Dama de Neo Flamvell',replace(replace('(Efeito Rápido): você pode enviar 1 monstro de FOGO da sua mão para o Cemitério e, depois, escolher 1 card no Cemitério do seu oponente; bana esse card. \r\nSe um card for banido do Cemitério do seu oponente, enquanto você controlar este monstro (exceto durante a Etapa de Dano): você pode enviar 1 monstro de FOGO com 200 ou menos de DEF do seu Deck para o Cemitério, exceto "Dama de Neo Flamvell". \r\nVocê só pode usar cada efeito de "Dama de Neo Flamvell" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(821049,'Visas Amritara',replace(replace('1+ Reguladores + 1 monstro de LUZ	\r\nO nome deste card se torna "Visas Starfrost" enquanto estiver no campo. \r\nVocê só pode usar cada um dos seguintes efeitos de "Visas Amritara" uma vez por turno. \r\nSe este card for Invocado por Invocação-Sincro: você pode adicionar 1 Magia/Armadilha que mencione "Visas Starfrost" do seu Deck à sua mão. \r\nDurante sua Fase Principal: você pode destruir 1 monstro que você controla e, além disso, todos os Monstros Sincro que você controla ganham 800 de ATK neste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(844056,'Flechas Vermelhas',replace(replace('Escolha até 2 monstros com a face para cima na(s) \r\nZona(s) de Monstros Adicional(is); bana-o(s) até a Fase Final. \r\nVocê só pode ativar 1 "Flechas Vermelhas" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(847217,'Espada de Orichalcos do Selamento',replace(replace('Os efeitos do monstro equipado são negados.\r\nSe você tiver um card na sua Zona de Campo: você pode escolher 1 Monstro de Efeito que controla; aquele Monstro de Efeito ganha este efeito até o final do turno do seu oponente. \r\nVocê só pode usar este efeito de "Espada de Orichalcos do Selamento" uma vez por turno.\r\n● Uma vez por turno (Efeito Rápido): você pode enviar 1 card da sua mão para o Cemitério, então escolha 1 card com a face para cima no campo; destrua aquele alvo.','\r',char(13)),'\n',char(10)),'Ganhar um efeito','O efeito de "Espada de Orichalcos do Selamento" está sendo aplicado.','Efeito de destruição (Espada de Orichalcos do Selamento)','','','','','','','','','','','','','');
INSERT INTO texts VALUES(847915,'Muralha de Números',replace(replace('Ative apenas se você controlar um monstro "Número". \r\nOs monstros "Número" no campo não podem ser destruídos por efeitos de cards e não podem ser destruídos em batalha, exceto contra outros monstros "Número". \r\nQuando um monstro "Número" que você controla for destruído, destrua este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(856784,'Compra Predestinada',replace(replace('Se você tiver menos PV que seu oponente e seu oponente controlar um monstro com o maior ATK no campo (mesmo em um empate): revele 3 cards com nomes diferentes do seu Deck, coloque-os no topo do seu Deck em ordem aleatória e, depois, compre 1 card. \r\nPelo resto deste turno depois que este card resolver, você não pode Baixar Magias/Armadilhas e, além disso, você só pode ativar mais um card ou efeito. \r\nVocê só pode ativar 1 "Compra Predestinada" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(863795,'Invocador das Galáxias',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 monstro "Fóton" ou "Galáxia" no seu Cemitério, exceto "Invocador das Galáxias"; Invoque-o por Invocação-Especial em Posição de Defesa. \r\nVocê pode escolher 1 outro monstro de LUZ que você controla; ele se torna de Nível 4 até o final deste turno. \r\nVocê só pode usar cada efeito de "Invocador das Galáxias" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(875572,'Crowley, o Magistus Talentoso',replace(replace('Se este card com a face para cima for usado como Matéria de Fusão, seu nome pode ser considerado como "Aleister, Aquele que Invoka". \r\nVocê só pode usar cada um dos seguintes efeitos de "Crowley, o Magistus Talentoso" uma vez por turno. \r\nSe este card for adicionado à sua mão, exceto ao comprá-lo: você pode Invocá-lo por Invocação-Especial. \r\nSe este card for Invocado por Invocação-Normal ou Especial (exceto durante a Etapa de Dano): você pode Invocar por Invocação-Fusão 1 Monstro de Fusão "Magistus" ou "Invokado(a)" do seu Deck Adicional, usando monstros da sua mão ou do campo.','\r',char(13)),'\n',char(10)),'Invocação Especial','Invocação Fusão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(876330,'Arma Mystletainn Dragunidade',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) ao enviar 1 monstro "Dragunidade" com a face para cima que você controla para o Cemitério. \r\nQuando este card for Invocado por Invocação-Normal ou Especial da mão: você pode escolher 1 monstro "Dragunidade" Dragão no seu Cemitério; equipe o alvo a este card.','\r',char(13)),'\n',char(10)),'Equipar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(879958,'Armadura da Porta Paralela',replace(replace('Escolha 1 Monstro Link que você controla; equipe-o com este card. \r\nSeu oponente não pode escolher o monstro equipado como alvo de efeitos de card e, além disso, ele não pode ser destruído em batalha. \r\nVocê pode banir este card e 2 Monstros Link do seu Cemitério e, depois, escolher 1 Monstro Link que você controla; ele pode realizar um segundo ataque durante cada Fase de Batalha neste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(885016,'Multi-Universo',replace(replace('Ative apenas se você não controlar um card com a face para cima na sua Zona do Campo. \r\nVocê pode escolher 1 Magia de Campo que estiver banida ou em qualquer Cemitério; destrua este card e, se isso acontecer, coloque o card alvo com a face para cima na sua Zona do Campo. \r\nVocê só pode usar este efeito de "Multi-Universo" uma vez por turno. \r\nSe um ou mais cards na Zona do Campo seriam destruídos por um efeito de card, em vez disso, você pode banir este card do seu Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(897409,'Centena das Galáxias',replace(replace('Quando este card for ativado: você pode enviar 1 card "Fóton" ou "Galáxia" do seu Deck para o Cemitério. \r\nSe "Dragão de Fóton de Olhos das Galáxias" for Invocado por Invocação-Especial no seu campo (exceto durante a Etapa de Dano): você pode olhar o Deck Adicional do seu oponente e, depois, você pode aplicar 1 desses efeitos.\r\n● Bana 1 monstro de lá.\r\n● Invoque por Invocação-Especial no seu campo 1 monstro "Número" de lá.	\r\nVocê só pode usar este efeito de "Centena das Galáxias" uma vez por turno. \r\nVocê só pode ativar 1 "Centena das Galáxias" por turno.','\r',char(13)),'\n',char(10)),'Enviar 1 card do seu Deck para o Cemitério?','Banir','Invocação Especial','Não fazer nada','','','','','','','','','','','','');
INSERT INTO texts VALUES(899287,'Glife, o Pássaro Fantasma',replace(replace('Você pode descartar este card; adicione 1 "Castelo Dourado de Stromberg" do seu Deck à sua mão. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 card na Zona de Magias & Armadilhas do seu oponente; destrua-o. \r\nVocê só pode usar este efeito de "Glife, o Pássaro Fantasma" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(900787,'Cavaleiro Dragunidade - Gae Bulg',replace(replace('1 Regulador Dragão + 1+ monstros Besta Alada não-Reguladores	\r\nUma vez por batalha, se este card batalhar, durante a Etapa de Dano (Efeito Rápido): você pode banir 1 monstro Besta Alada do seu Cemitério; até o final deste turno, este card ganha o ATK original desse monstro.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(904185,'Pouso Vertical',replace(replace('Ofereça como Tributo qualquer número de monstros de VENTO, exceto Fichas; Invoque por Invocação-Especial um mesmo número de "Fichas de Besta Fantasma Mecha" (Tipo Máquina/VENTO/Nível 3/ATK 0/DEF 0). \r\nVocê só pode ativar 1 "Pouso Vertical" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(904186,'Ficha de Besta Fantasma Mecha','Invocado por Especial com o efeito de um monstro "Besta Fantasma Mecha" ou um card relacionado.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(911883,'Dai Inesperado','Se você não controlar nenhum monstro: Invoque por Invocação-Especial 1 Monstro Normal de Nível 4 ou menos do Deck.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(917796,'Gagagatag',replace(replace('Até sua próxima Fase de Apoio, todos os monstros "Gagaga" que você controla atualmente ganham 500 de ATK para cada monstro "Gagaga" que você controla atualmente. \r\nVocê só pode ativar 1 "Gagagatag" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(923596,'Engrenagiarmadura',replace(replace('Uma vez por turno: você pode colocar este card com a face para baixo em Posição de Defesa. \r\nQuando este card for virado com a face para cima: você pode adicionar 1 monstro "Engrenagi" do seu Deck à sua mão, exceto "Engrenagiarmadura".','\r',char(13)),'\n',char(10)),'Mudar para Posição de Defesa com a face para baixo','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(938717,'Cabo de Inicialização - Dínamo de Comando',replace(replace('Você pode escolher até 2 monstros Máquina "Dispositivo" com nomes diferentes que você controla ou no seu Cemitério; Invoque este card por Invocação-Especial da sua mão e, depois, equipe os alvos a este card (independente do Tipo deles). \r\nVocê só pode usar este efeito de "Cabo de Inicialização - Dínamo de Comando" uma vez por turno. \r\nGanha 1000 de ATK para cada monstro equipado a este card por este efeito.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(952523,'Armadilhatrix Cularia',replace(replace('2 monstros Inseto e/ou Planta	\r\nEste card Invocado por Invocação-Link não é afetado por efeitos de Armadilha. \r\nVocê só pode usar cada um dos seguintes efeitos de "Armadilhatrix Cularia" uma vez por turno. \r\nDepois que você ativar um Card de Armadilha Normal "Buraco", você pode Baixá-lo em vez de enviá-lo para o Cemitério. \r\nDurante sua Fase Final: você pode escolher 1 monstro "Armadilhatrix" no seu Cemitério; Invoque-o por Invocação-Especial em Posição de Defesa.','\r',char(13)),'\n',char(10)),'','Baixá-la em vez de enviá-la ao Cemitério?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(967928,'Jogo Penalty',replace(replace('Quando o seu adversário tem 4 cards na sua mão, escolha e active 1 dos seguintes efeitos:\r\n● O seu adversário não pode comprar durante a sua própria próxima Draw Phase.\r\n● O seu adversário não pode activar qualquer Card de Magia e/ou Armadilha durante este turno.','\r',char(13)),'\n',char(10)),'Seu oponente não pode comprar durante a próxima Fase de Compra','Seu oponente não pode ativar Cards de Magia/Armadilha neste turno','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(975299,'B.E.F. Zelos',replace(replace('Quando este card for ativado: você pode adicionar 1 "Corrida para o Chefe" do seu Deck à sua mão. \r\nMonstros "B.E.S." que você controla ganham 500 de ATK/DEF, seu oponente não pode escolhê-los como alvos de efeitos de card e, além disso, eles não podem ser destruídos pelos efeitos de card do seu oponente. \r\nUma vez por turno: você pode Invocar por Invocação-Especial 1 monstro "B.E.S." da sua mão. \r\nSe um ou mais monstros "B.E.S." forem Invocados por Invocação-Normal ou Especial no seu campo: coloque 1 marcador nele(s).','\r',char(13)),'\n',char(10)),'Adicionar "Corrida para o Chefe" à sua mão?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(980973,'Dragão Armado LV3','Durante sua Fase de Apoio: você pode enviar este card para o Cemitério; Invoque por Invocação-Especial 1 "Dragão Armado LV5" da sua mão ou do Deck.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(980974,'Dragão Armado LV3','Durante sua Fase de Apoio: você pode enviar este card para o Cemitério; Invoque por Invocação-Especial 1 "Dragão Armado LV5" da sua mão ou do Deck.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(981540,'Semi-invencível','Escolha 1 monstro no campo; neste turno, esse monstro não pode ser destruído em batalha e, além disso, qualquer dano de batalha que você sofra de ataques envolvendo esse monstro são diminuídos pela metade.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(983995,'Ricochete',replace(replace('Quando seu oponente ativar um Card de Magia, Card de Armadilha ou efeito de monstro que devolva um ou mais cards do campo à mão: Negue esse efeito e, se isso acontecer, envie 1 card da mão do oponente (aleatoriamente) ou do lado do campo dele ao Cemitério. \r\nQuando este card Baixado for destruído por um efeito de card do oponente e enviado ao Cemitério: Compre 1 card.','\r',char(13)),'\n',char(10)),'Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(984114,'Expressoroide','Quando este card for Invocado: você pode escolher 2 monstros "roide" no seu Cemitério, exceto "Expressoroide"; adicione os alvos à sua mão.','Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(987311,'D/D/D Alexandre, o Rei dos Vendavais',replace(replace('1 Regulador "D/D" + 1 ou mais monstros não-Reguladores	\r\nSe um ou mais outros monstros "D/D" forem Invocados por Invocação-Normal ou Especial no seu campo, enquanto você controlar este card com a face para cima (exceto durante a Etapa de Dano): você pode escolher 1 monstro "D/D" de Nível 4 ou menos no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê só pode usar este efeito de "D/D/D Alexandre, o Rei dos Vendavais" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1003028,'Cachorrinho Mergulhador',replace(replace('Se seu oponente controlar um monstro e todos os monstros com a face para cima que você controla (mín. 1) forem de Nível 4, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Cachorrinho Mergulhador" por Invocação-Especial uma vez por turno desta forma. \r\nEste card não pode ser usado como uma Matéria Xyz para uma Invocação-Xyz, exceto para a Invocação-Xyz de um monstro do Tipo Guerreiro.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1003840,'Sucatação Luz Estrelada',replace(replace('Você pode oferecer como Tributo 1 monstro Regulador; Invoque por Invocação-Especial 1 monstro "Sincron" do seu Deck com um Nível diferente que o monstro oferecido como Tributo tinha no campo. \r\nDurante o turno do seu oponente, se você Invocar por Invocação-Especial um Monstro Sincro do seu Deck Adicional: escolha 1 card no campo; embaralhe-o no Deck. \r\nVocê só pode usar cada efeito de "Sucatação Luz Estrelada" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1005587,'Buraco Armadilha do Vácuo','Quando seu oponente Invocar um ou mais monstros com 2000 ou mais de ATK por Invocação-Especial: negue os efeitos de 1 desses monstros com 2000 ou mais de ATK e, se isso acontecer, destrua-o.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1006081,'Mudar Sucata',replace(replace('Você só pode usar o seguinte efeito de "Mudar Sucata" uma vez por turno. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 monstro "Sucata" no campo e, depois, ativar 1 desses efeitos;\r\n● Aumente o Nível dele em 1.\r\n● Reduza o Nível dele em 1.','\r',char(13)),'\n',char(10)),'Alterar Nível','Aumentar o Nível em 1','Reduzir o Nível em 1','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1033312,'Decisão Dolorosa',replace(replace('Envie 1 Monstro Normal de Nível 4 ou menos do seu Deck para o Cemitério e, se isso acontecer, adicione 1 monstro com o mesmo nome do seu Deck à sua mão. \r\nVocê só pode ativar 1 "Decisão Dolorosa" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1035143,'Eskuriboh',replace(replace('Quando um ou mais monstros Demônio e/ou um ou mais Monstros de Fusão que você controla forem escolhidos como alvo de um ataque, ou um card ou efeito for ativado que escolha-os como alvo (Efeito Rápido): você pode descartar este card e, depois, escolha 1 desses monstros; até o final deste turno, ele não pode ser destruído em batalha ou por efeitos de card e, além disso, seus efeitos ativados na Zona de Monstros não podem ser negados. \r\nSe este card for enviado da mão para o Cemitério por um efeito de card: você pode adicionar 1 "Polimerização" do seu Deck ou Cemitério à sua mão. \r\nVocê só pode usar cada efeito de "Eskuriboh" uma vez por turno.','\r',char(13)),'\n',char(10)),'Proteção','Adicionar à mão','O efeito de "Eskuriboh" está sendo aplicado.','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1036974,'Infortúnio',replace(replace('Selecione 1 monstro com a face para cima que seu oponente controla. \r\nCause dano ao oponente igual à metade do ATK original desse monstro. \r\nSeus monstros não podem atacar neste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1041278,'Expulsão do Marcado',replace(replace('Ofereça como Tributo 1 Monstro de Fusão e, depois, escolha 2 Monstros que não sejam de Fusão que estiverem banidos e/ou em qualquer Cemitério; Invoque os dois monstros por Invocação-Especial, 1 em cada campo. \r\nSe você ofereceu como Tributo um Monstro de Fusão que mencione "Caído de Arbaz" como matéria para ativar este card, em vez disso, você pode Invocar os dois monstros por Invocação-Especial no seu campo, em Posição de Defesa. \r\nVocê só pode ativar 1 "Expulsão do Marcado" por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial 2 monstros no seu campo em Posição de Defesa?','Escolha o monstro a ser Invocado por Invocação Especial no seu campo','Escolha o monstro a ser Invocado por Invocação Especial no campo do seu oponente','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1045143,'Engrenagiano Mk-II','Quando este card for Invocado por Invocação-Normal ou Virar: você pode Invocar por Invocação-Especial 1 monstro "Engrenagi" da sua mão ou Cemitério em Posição de Defesa.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1047075,'Espadachim das Chamas Lutador',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 Magia/Armadilha que mencione "Espadachim das Chamas" do seu Deck à sua mão. \r\nSe este card for enviado para o Cemitério: você pode enviar 1 "Espadachim das Chamas", ou 1 monstro que o mencione, do seu Deck ou Deck Adicional para o Cemitério, exceto "Espadachim das Chamas Lutador". \r\nVocê só pode usar cada efeito de "Espadachim das Chamas Lutador" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Enviar para o Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1050186,'Cavaleirostélite Unukalhai',replace(replace('Se este card for Invocado: você pode enviar 1 card "Cavaleirost" do seu Deck para o Cemitério, exceto "Cavaleirostélite Unukalhai". \r\nVocê só pode usar este efeito de "Cavaleirostélite Unukalhai" uma vez por turno.','\r',char(13)),'\n',char(10)),'Enviar para o Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1050355,'Espelho Onírico do Terror',replace(replace('Durante a Fase Final: você pode banir este card; ative 1 "Espelho Onírico da Alegria" da sua mão ou do Deck. \r\nVocê só pode usar este efeito de "Espelho Onírico do Terror" uma vez por turno. \r\nSempre que seu oponente Invocar um ou mais monstros por Invocação-Especial, cause 300 de dano ao seu oponente. \r\nEste efeito só se aplica enquanto você controlar um monstro "Espelho Onírico" de TREVAS.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1050684,'Pátio de Restolhos','Adicione 1 Regulador "Restolhos" do seu Deck à sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1061200,'F.A. Cidade do Grande Prêmio',replace(replace('Aumente em 2 o Nível de todos os monstros "F.A." no campo durante a Fase Principal e a Fase de Batalha. \r\nSeu oponente não pode escolher monstros "F.A." que você controla como alvo de efeitos de card. \r\nSe este card com a face para cima no campo for destruído por um efeito de card: você pode adicionar 1 card "F.A." do seu Deck à sua mão, exceto "F.A. Cidade do Grande Prêmio". \r\nVocê só pode usar este efeito de "F.A. Cidade do Grande Prêmio" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1073952,'Plantador Mágico','Envie 1 Armadilha Contínua com a face para cima que você controla para o Cemitério; compre 2 cards.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1082946,'Pirorrelógio do Destino',replace(replace('Avance a contagem de turnos em 1 turno. \r\nO turno em que este card foi ativado continua normalmente.','\r',char(13)),'\n',char(10)),'Escolha o card para avançar a contagem de turnos','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1102515,'Mímico Negro LV3','Se este card for destruído em batalha e enviado para o Cemitério: compre 1 card, mas se este card foi Invocado por Invocação-Especial pelo efeito de "Mímico Negro LV1", em vez disso, compre 2 cards.','Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1118137,'Poder do Guardião',replace(replace('Se um ataque for declarado envolvendo o monstro equipado: coloque 1 Marcador de Magia neste card. \r\nO monstro equipado ganha 500 de ATK/DEF para cada Marcador de Magia neste card. \r\nSe o monstro equipado seria destruído em batalha ou por um efeito de card, em vez disso, você pode remover 1 Marcador de Magia do seu campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1122030,'Vandalismo de Artmage -Ataque-',replace(replace('Quando este card for ativado: você pode adicionar 1 "Medius, o Puro" do seu Deck à sua mão. \r\nVocê pode escolher 1 monstro com a face para cima que você controla; se esse monstro com a face para cima seria usado como Matéria de Fusão neste turno, ele pode ser considerado como um monstro "Artmage". \r\nVocê só pode usar este efeito de "Vandalismo de Artmage -Ataque-" uma vez por turno. \r\nSe "Artmage, Academia Acrópole de Artes Arcanas" que você controla seria destruído por um efeito de card, em vez disso, você pode enviar este card que você controla para o Cemitério. \r\nVocê só pode ativar 1 "Vandalismo de Artmage -Ataque-" por turno.','\r',char(13)),'\n',char(10)),'Considerar como um monstro "Artmage"','Adicionar aquele monstro à mão?','O efeito de "Vandalismo de Artmage -Ataque-" está sendo aplicado.','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1127737,'Sargaço, o Campo de Batalha D.D.',replace(replace('Sempre que um monstro for Invocado por Invocação-Xyz: o duelista que realizar a Invocação sofre 500 de dano. \r\nDurante a Fase Final de cada duelista, o duelista do turno sofre 500 de dano se ele controlar um Monstro Xyz com a face para cima.','\r',char(13)),'\n',char(10)),'Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1142880,'Dragão Cibernético Nachster',replace(replace('O nome deste card se torna "Dragão Cibernético" enquanto estiver no campo ou no Cemitério. \r\nVocê pode descartar 1 outro monstro; Invoque este card por Invocação-Especial da sua mão. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 monstro Máquina com 2100 de ATK ou DEF no seu Cemitério; Invoque-o por Invocação-Especial e, além disso, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros Máquina. \r\nVocê só pode usar cada efeito de "Dragão Cibernético Nachster" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1149109,'Restrição do Deck',replace(replace('Nenhum duelista pode adicionar cards do Deck à sua mão exceto comprando-os. \r\nMonstros não podem ser Invocados por Invocação-Especial do Deck Principal. \r\nDestrua este card durante sua 2ª Fase de Apoio depois da ativação.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1151281,'Fosfogeleira, o Behemoth Subterror',replace(replace('VIRE: Você pode enviar 1 card do seu Deck para o Cemitério. \r\nVocê só pode usar este efeito de "Fosfogeleira, o Behemoth Subterror" uma vez por turno.\r\nQuando um monstro com a face para cima que você controla for virado com a face para baixo, se você não controlar nenhum monstro com a face para cima: você pode Invocar este card por Invocação-Especial da sua mão em Posição de Defesa. \r\nUma vez por turno: você pode colocar este card com a face para baixo em Posição de Defesa.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1154611,'Paleozoico Leanchoilia',replace(replace('Escolha 1 card banido; devolva-o para o Cemitério. \r\nUma vez por Corrente, quando um Card de Armadilha for ativado enquanto este card estiver no seu Cemitério: você pode Invocar este card por Invocação-Especial como um Monstro Normal (Aqua/ÁGUA/Nível 2/ATK 1200/DEF 0).	\r\n(Este card NÃO é considerado como uma Armadilha.) \r\nSe Invocado desta forma, este card não é afetado por efeitos de monstro e, além disso, bana-o quando ele deixar o campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1157683,'Invasão Cibersombria',replace(replace('Uma vez por turno: você pode ativar 1 desses efeitos;\r\n● Escolha 1 Monstro de Efeito "Cibersombrio(a)" que você controla; equipe 1 monstro Dragão ou Máquina de qualquer Cemitério a ele como uma Magia de Equipamento que concede a ele 1000 de ATK.\r\n● Envie para o Cemitério 1 Card de Equipamento que você controla equipado a um monstro Máquina; destrua 1 card que seu oponente controla.	\r\nVocê só pode usar cada efeito de "Invasão Cibersombria" uma vez por turno.','\r',char(13)),'\n',char(10)),'Equipar','Destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1164211,'Escudo da Dinastia do Milênio',replace(replace('Não pode ser destruído por efeitos de Magia/Armadilha. \r\nVocê só pode usar cada um dos seguintes efeitos de "Escudo da Dinastia do Milênio" uma vez por turno. \r\nSe este card estiver na sua mão: você pode colocá-lo na sua Zona de Magias & Armadilhas como uma Magia Contínua com a face para cima. \r\nEnquanto este card for uma Magia Contínua: você pode pagar 2000 PV ou revelar 1 "Ankh do Milênio" na sua mão; Invoque este card por Invocação-Especial e, depois, você pode adicionar 1 "Ankh do Milênio" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Colocá-la como Card de Magia','Invocação Especial','Revelar "Ankh do Milênio"?','Adicionar "Ankh do Milênio" à sua mão?','','','','','','','','','','','','');
INSERT INTO texts VALUES(1174075,'Mu Beta Fafnir Drytron',replace(replace('2+ monstros de Nível 1	\r\nQuando você Invocar por Invocação-Ritual, você pode desassociar uma ou mais matérias deste card como monstros requeridos para a Invocação-Ritual. \r\nVocê só pode usar cada um dos seguintes efeitos de "Mu Beta Fafnir Drytron" uma vez por turno. \r\nSe este card for Invocado por Invocação-Xyz: você pode enviar 1 card "Drytron" do seu Deck para o Cemitério. \r\nQuando seu oponente ativar um Card de Magia/Armadilha, enquanto você controlar um Monstro de Ritual Máquina (Efeito Rápido): você pode desassociar 1 matéria deste card; negue a ativação e, se isso acontecer, destrua esse card.','\r',char(13)),'\n',char(10)),'Enviar para o Cemitério','Negar e destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1184620,'Kojikocy','Um caçador de homens com braços poderosos, capazes de esmagar grandes rochas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1186447,'Feiticeiro do Horóscopo, o Mago Observador das Estrelas',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nVocê só pode usar o Efeito de Pêndulo de "Feiticeiro do Horóscopo, o Mago Observador das Estrelas" uma vez por turno.\r\nQuando um Card de Magia ou efeito ativado do seu oponente resolve, se você controlar um Monstro Pêndulo "Mago" ou um monstro "Olhos Anômalos", você pode negar aquele efeito, então destrua este card.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nVocê pode descartar 1 outro Monstro Pêndulo "Mago", "Camarartista" ou "Olhos Anômalos"; Invoque por Invocação-Especial este card da sua mão.\r\nSe este card for Invocado por Invocação-Especial: você pode adicionar 1 Monstro Pêndulo com 2500 de ATK do seu Deck à sua mão.\r\nVocê pode escolher 1 Card de Monstro Pêndulo que você controla; destrua-o, então você pode adicionar 1 Monstro Pêndulo com a face para cima do seu Deck Adiciona à sua mão.\r\nVocê só pode usar cada um dos efeitos de "Feiticeiro do Horóscopo, o Mago Observador das Estrelas" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Efeito de busca','Efeito de destruição','Adicionar à mão?','Aplicar o efeito de "Feiticeiro do Horóscopo, o Mago Observador das Estrelas" para negar?','','','','','','','','','','','');
INSERT INTO texts VALUES(1186448,'Feiticeiro do Horóscopo, o Mago Observador das Estrelas',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nVocê só pode usar o Efeito de Pêndulo de "Feiticeiro do Horóscopo, o Mago Observador das Estrelas" uma vez por turno.\r\nQuando um Card de Magia ou efeito ativado do seu oponente resolve, se você controlar um Monstro Pêndulo "Mago" ou um monstro "Olhos Anômalos", você pode negar aquele efeito, então destrua este card.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nVocê pode descartar 1 outro Monstro Pêndulo "Mago", "Camarartista" ou "Olhos Anômalos"; Invoque por Invocação-Especial este card da sua mão.\r\nSe este card for Invocado por Invocação-Especial: você pode adicionar 1 Monstro Pêndulo com 2500 de ATK do seu Deck à sua mão.\r\nVocê pode escolher 1 Card de Monstro Pêndulo que você controla; destrua-o, então você pode adicionar 1 Monstro Pêndulo com a face para cima do seu Deck Adiciona à sua mão.\r\nVocê só pode usar cada um dos efeitos de "Feiticeiro do Horóscopo, o Mago Observador das Estrelas" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Efeito de busca','Efeito de destruição','Adicionar à mão?','Aplicar o efeito de "Feiticeiro do Horóscopo, o Mago Observador das Estrelas" para negar?','','','','','','','','','','','');
INSERT INTO texts VALUES(1187243,'Vento de Cauda de Gusto',replace(replace('Só pode ser equipado a um monstro "Gusto". \r\nO monstro equipado não pode ser destruído pelos efeitos de card do seu oponente. \r\nVocê só pode usar cada um dos seguintes efeitos de "Vento de Cauda de Gusto" uma vez por turno. \r\nVocê pode banir este card do seu Cemitério e descartar 1 monstro de VENTO; adicione 1 Magia/Armadilha "Gusto" do seu Deck à sua mão. \r\nVocê pode ativar este efeito de acordo com o Nível/Classe do monstro equipado;\r\n● 4 ou menos: Invoque por Invocação-Especial 1 monstro "Gusto" do seu Deck com um Tipo diferente que o do monstro equipado.\r\n● 5 ou mais: Invoque por Invocação-Especial 1 Regulador de Nível 1 do seu Deck.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1197847,'Onda Fantasma Espiral',replace(replace('Só pode ser equipado a um Monstro Normal. \r\nNa primeira vez que o monstro equipado seria destruído em batalha neste turno, ele não é destruído. \r\nNo final da Fase de Batalha, se o monstro equipado batalhar: você pode Invocar por Invocação-Especial 1 "Dragão Fantasma Espiral" de sua mão, Deck ou Cemitério, e equipe-o com este card e, depois, seu oponente descarta 1 card, se ele tiver algum. \r\nVocê só pode usar este efeito de "Onda Fantasma Espiral" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1200843,'Espelho de Yata',replace(replace('Só pode ser equipado a um monstro Espírito. \r\nO monstro equipado não precisa ter seu efeito que o devolve à mão ativado. \r\nSe ele seria destruído em batalha, em vez disso, destrua este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1218214,'Dharma Cúbico',replace(replace('Você não sofre dano de batalha dos ataques envolvendo seus monstros "Cúbico(a)". \r\nVocê só pode usar cada um dos seguintes efeitos de "Dharma Cúbico" uma vez por turno, durante sua Fase Principal:\r\n● Você pode enviar 1 card "Cúbico(a)" da sua mão para o Cemitério e, se isso acontecer, compre 1 card.\r\n● Você pode banir este card do seu Cemitério e, depois, escolha 1 monstro "Cúbico(a)" no seu Cemitério; adicione-o à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1224927,'Catástrofe Malevolente','Quando um monstro do oponente declarar um ataque: destrua todos os Cards de Magia e Armadilha no campo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1225009,'Arianna, a Serva de Labrinto',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 card "Labrinto" do seu Deck à sua mão, exceto "Arianna, a Serva de Labrinto". \r\nSe um ou mais outros monstros deixarem o campo pelo efeito de uma Armadilha Normal sua (exceto durante a Etapa de Dano): você pode comprar 1 card e, depois, você pode aplicar este efeito.\r\n● Da sua mão, Invoque 1 monstro Demônio por Invocação-Especial ou Baixe 1 Magia/Armadilha.	\r\nVocê só pode usar 1 efeito de "Arianna, a Serva de Labrinto" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Comprar','Invocar por Invocação Especial da mão','Baixar da mão','Não fazer nada','','','','','','','','','','','');
INSERT INTO texts VALUES(1248895,'Cadeia da Destruição','Quando um ou mais monstros com 2000 ou menos de ATK forem Invocados: escolha 1 deles; destrua todos os cards com esse nome na mão e no Deck Principal do seu controlador.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1249315,'Arauto da Luz Pura',replace(replace('2 monstros de Nível 2	\r\nVocê pode desassociar 1 matéria deste card e, depois, escolha 1 monstro no seu Cemitério; adicione-o à sua mão e, depois, embaralhe 1 card da sua mão no Deck. \r\nVocê só pode usar o efeito de "Arauto da Luz Pura" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1259814,'Arco-Irevolução RGB','Uma vez por turno: você pode escolher 1 monstro com a face para cima no campo; seu Tipo se torna Máquina e, além disso, ele ganha os Atributos LUZ/TREVAS/TERRA/ÁGUA/FOGO/VENTO (mesmo que este card deixe o campo).','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1259915,'Trovão das Bestas Sagradas',replace(replace('Durante sua Fase Principal: você pode colocar 2 "Trovão das Bestas Sagradas" da sua mão, do Deck e/ou do Cemitério, com a face para cima no seu campo e, depois, você pode revelar 1 monstro "Bestas Sagradas" de Nível 10 na sua mão e, depois, coloque 1 "Paraíso Caído das Bestas Sagradas" do seu Deck, com a face para cima na sua Zona do Campo. \r\nDurante a Fase Final do seu oponente, se este card estiver no seu Cemitério: você pode adicionar este card à sua mão. \r\nVocê só pode usar cada efeito de "Trovão das Bestas Sagradas" uma vez por turno.','\r',char(13)),'\n',char(10)),'Efeito de colocar','Retornar para a mão','Mostrar ao seu oponente?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1264319,'Fusão Cavaleiro-Gema',replace(replace('Invoque por Invocação-Fusão 1 Monstro de Fusão "Cavaleiro-Gema" do seu Deck Adicional, usando monstros da sua mão ou do campo. \r\nSe este card estiver no seu Cemitério: você pode banir 1 monstro "Cavaleiro-Gema" do seu Cemitério; adicione este card à sua mão.','\r',char(13)),'\n',char(10)),'Invocação Fusão','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1264320,'Fusão Cavaleiro-Gema',replace(replace('Invoque por Invocação-Fusão 1 Monstro de Fusão "Cavaleiro-Gema" do seu Deck Adicional, usando monstros da sua mão ou do campo. \r\nSe este card estiver no seu Cemitério: você pode banir 1 monstro "Cavaleiro-Gema" do seu Cemitério; adicione este card à sua mão.','\r',char(13)),'\n',char(10)),'Invocação Fusão','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1269512,'Lanceiro do Raio Utópico de Armadura Completa',replace(replace('3 monstros de Nível 4	\r\nUma vez por turno, você também pode Invocar por Invocação-Xyz "Lanceiro do Raio Utópico de Armadura Completa" ao descartar 1 Magia/Armadilha e usar 1 Monstro Xyz de Classe 4 ou menos que você controla. \r\n(Transfira as matérias dele para este card.) \r\nMonstros que seu oponente controla perdem 500 de ATK. \r\nNo começo da Fase de Batalha: você pode negar os efeitos de todos os monstros em Posição de Ataque que seu oponente controla atualmente. \r\nQuando este card atacante destruir um monstro do oponente em batalha: você pode desassociar 1 matéria deste card; ele pode realizar um segundo ataque em seguida.','\r',char(13)),'\n',char(10)),'Invocá-lo por Invocação Xyz usando um Monstro Xyz de Classe 4 ou inferior que você controla?','','Negar os efeitos dos monstros em Posição de Ataque que seu oponente controla','Desassociar Matéria Xyz para atacar novamente','','','','','','','','','','','','');
INSERT INTO texts VALUES(1274455,'Soartrooper de Kozmo',replace(replace('Durante o turno de qualquer duelista: você pode banir este card; Invoque por Invocação-Especial 1 monstro "Kozmo" de Nível 4 ou mais da sua mão. \r\nVocê só pode usar este efeito de "Soartrooper de Kozmo" uma vez por turno. \r\nUma vez por turno: você pode pagar 1000 PV e, depois, escolher 1 monstro "Kozmo" do Tipo Psíquico no seu Cemitério; Invoque-o por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Invoque por Invocação Especial 1 monstro "Kozmo" da sua mão','Invoque por Invocação Especial 1 monstro "Kozmo" do seu Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1278431,'Estrutura do Mecanismo Antigo',replace(replace('Você pode descartar 1 card; adicione 1 "Golem do Mecanismo Antigo" ou 1 Magia/Armadilha que o mencione, do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Estrutura do Mecanismo Antigo" uma vez por turno. \r\nSe este card atacar, seu oponente não pode ativar Cards de Magia/Armadilha até o final da Etapa de Dano. \r\nSe este card com a face para cima sob o controle do seu dono deixar o campo devido a um efeito de card do oponente: você pode Invocar por Invocação-Especial até 3 "Golem do Mecanismo Antigo" e/ou "Golem do Mecanismo Antigo - Murro Definitivo" da sua mão, ignorando suas condições de Invocação.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1280391,'Advento de Atlantis',replace(replace('O nome deste card se torna "Umi" enquanto está na Zona de Magia & Armadilha.\r\nVocê só pode usar cada um dos seguintes efeitos de "Advento de Atlantis" uma vez por turno.\r\nDurante a sua Fase Principal: você pode colocar 1 "Atlantis, a Cidade do Dragão" ou "Umi" do seu Deck na sua Zona de Campo com a face para cima.\r\nSe este card for enviado para o Cemitério: você pode adicionar 1 monstro Serpente Marinha de Nível 7 do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Efeito de colocar','Efeito de busca','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1281505,'Tetra Vylon',replace(replace('Se este card for enviado da Zona dos Cards de Monstro para o Cemitério: você pode pagar 500 Pontos de Vida e, depois, escolher 1 monstro com a face para cima que você controla; equipe este card ao alvo. \r\nSe o monstro equipado seria destruído, em vez disso, você pode destruir este Card de Equipamento.','\r',char(13)),'\n',char(10)),'Equipar como Card de Equipamento','Usar o efeito de "Tetra Vylon" em vez de ser destruído?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1287123,'Falcão de Matéria Prima','Quando o efeito de um Monstro de Efeito para destruir um ou mais Cards de Magia ou Armadilha no campo for ativado, você pode enviar 1 card da sua mão ao Cemitério para negar sua ativação e destruir o card.','Negar a ativação e destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1295111,'Salamagrande Santuário',replace(replace('Se você Invocar um Monstro Link "Salamagrande" por Invocação-Link, você pode usar 1 Monstro Link "Salamagrande" que você controla com seu mesmo nome como toda a matéria. \r\nDurante o cálculo de dano, se um monstro seu batalhar: você pode pagar 1000 PV e, depois, escolher 1 Monstro Link que você controla; faça com que o ATK dele se torne 0 e, se isso acontecer, ganhe PV igual ao seu ATK original. \r\nVocê só pode usar cada efeito de "Salamagrande Santuário" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Link usando como Matéria apenas um monstro com o mesmo nome','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1295442,'Gelojade Aegirocassis da Criação',replace(replace('Enquanto este card estiver equipado a um monstro, o monstro equipado ganha 400 de ATK/DEF para cada monstro banido. \r\nVocê só pode usar 1 dos seguintes efeitos de "Gelojade Aegirocassis da Criação" por turno e apenas uma vez por turno. \r\nSe este card estiver na sua mão ou no Cemitério (exceto durante a Etapa de Dano) (Efeito Rápido): você pode escolher 1 monstro "Gelojade" que você controla; equipe este card a esse monstro que você controla. \r\nEnquanto este card estiver equipado a um monstro: você pode Invocar este card por Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1315120,'T.G. Golpeador',replace(replace('Se somente seu oponente controlar um monstro, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nUma vez por turno, durante a Fase Final, se este card estiver no Cemitério porque foi destruído no campo e enviado para lá neste turno: você pode adicionar 1 monstro "T.G." do seu Deck à sua mão, exceto "T.G. Golpeador".','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1322368,'Hélice Dupla ESPIRÃO',replace(replace('2 monstros "ESPIRÃO"	\r\nO nome deste card se torna "Super Agente ESPIRÃO" enquanto estiver no campo ou no Cemitério. \r\nVocê pode declarar 1 tipo de card (Monstro, Magia ou Armadilha); revele o card do topo do Deck do seu oponente e, se isso acontecer e o tipo dele corresponder ao tipo declarado, pegue 1 monstro "ESPIRÃO" do seu Deck ou do Cemitério e adicione-o à sua mão ou Invoque-o por Invocação-Especial em uma zona sua para a qual este card apontar. \r\nVocê só pode usar este efeito de "Hélice Dupla ESPIRÃO" uma vez por turno.','\r',char(13)),'\n',char(10)),'Declarar um tipo de card','Invocação Especial?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1329620,'Lagrimentiara Crimar',replace(replace('Quando um Card de Magia/Armadilha, ou efeito de monstro, for ativado, enquanto você controlar um monstro "Lagrimentiara" ou "Visas Starfrost": negue a ativação e, se isso acontecer, embaralhe esse card no Deck e, depois, envie 1 monstro da sua mão para o Cemitério. \r\nSe este card for enviado para o Cemitério por um efeito de card: você pode escolher 1 dos seus monstros "Lagrimentiara" banidos; adicione-o à sua mão. \r\nVocê só pode usar 1 efeito de "Lagrimentiara Crimar" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1340142,'Varar, a Concórdia Vaalmônica',replace(replace('2 monstros, incluindo um Monstro Link "Vaalmônica"	\r\nNão é afetado por efeitos de card, exceto cards "Vaalmônica", enquanto você tiver 6 ou mais Marcadores de Ressonância no seu campo. \r\nGanha 1 ataque adicional durante cada Fase de Batalha, para cada monstro "Vaalmônica" de Nível 4 que você controla. \r\nUma vez por turno, quando seu oponente Invocaria um ou mais monstros por Invocação-Especial, se você tiver 3+ Marcadores de Ressonância no seu campo (Efeito Rápido): você pode negar a Invocação-Especial e, se isso acontecer, destrua esse(s) monstro(s) e, depois, remova 3 Marcadores de Ressonância do seu campo.','\r',char(13)),'\n',char(10)),'Não afetado','Ataques múltiplos','Negar a Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1344018,'Tempo Pêndulografo',replace(replace('Seu oponente não pode escolher monstros do Tipo Mago que você controla como alvo de Cards ou efeitos de Armadilha. \r\nVocê só pode usar o seguinte efeito de "Tempo Pêndulografo" uma vez por turno. \r\nVocê pode escolher 1 Card de Monstro Pêndulo "Mago" nas suas Zonas de Monstro ou Zonas de Pêndulo e 1 card que seu oponente controla; destrua-os. \r\nDepois, se este efeito não destruiu 2 cards, você pode enviar 1 card no campo para o Cemitério.','\r',char(13)),'\n',char(10)),'Destruir 1 card','Enviar 1 card no campo para o Cemitério?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1347977,'Guarda Misterioso','VIRE: Escolha 1 monstro com a face para cima no campo e, se você controlar um monstro Guerreiro, você pode escolher 1 monstro adicional com a face para cima no campo; coloque o primeiro alvo no topo do Deck e, depois, devolva o alvo adicional (se houver) para a mão se você ainda controlar um monstro Guerreiro.','Retornar ao Deck','Escolher 1 monstro com a face para cima adicional no campo para devolver para a mão?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1353770,'Valhala, o Salão dos Caídos',replace(replace('Uma vez por turno: você pode Invocar por Invocação-Especial 1 monstro Fada da sua mão. \r\nVocê não pode controlar nenhum monstro para ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1357146,'Roninrãnin',replace(replace('Não pode ser usado como Matéria Sincro. \r\nO nome deste card se torna "Sapo Des" enquanto estiver no campo. \r\nSe este card estiver no seu Cemitério: você pode banir 1 monstro "Sapo" do seu Cemitério; Invoque este card por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1362589,'Esmagador de Fóton','Se este card atacar, ele é colocado em Posição de Defesa no final da Etapa de Dano.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1371589,'Coala Vampírico','Se este card causar dano de batalha ao seu oponente ao batalhar um monstro: ganhe PV igual ao dano de batalha causado.','Ganhar PV','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1372887,'Carona',replace(replace('Pelo resto deste turno, sempre que um ou mais cards forem adicionados do Deck Principal ou Cemitério para a mão do seu oponente, exceto ao comprá-los, você imediatamente compra 1 card. \r\nVocê só pode ativar 1 "Carona" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1409474,'Esfynge da Chama Nebulosa',replace(replace('Seu oponente não pode escolher este card como alvo de efeitos de card. \r\nVocê pode declarar 1 tipo de card (Monstro, Magia ou Armadilha); envie o card do topo do seu Deck para o Cemitério e, depois, se o card for do tipo declarado, você pode Invocar por Invocação-Especial 1 monstro de FOGO da sua mão ou Cemitério. \r\nVocê só pode usar este efeito de "Esfynge da Chama Nebulosa" uma vez por turno.','\r',char(13)),'\n',char(10)),'Declarar um tipo de card','Invocar por Invocação Especial 1 monstro de FOGO da sua mão ou do Cemitério?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1410324,'Trapestrela Cônita',replace(replace('Se você controlar um Monstro de Fusão ou Link "Trapestrela": você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe este card for enviado para o Cemitério como matéria para um Monstro Link "Trapestrela": você pode adicionar 1 "Fusão Trapestrela" ou "Difusão Trapestrela" do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "Trapestrela Cônita" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Adicionar à sua mão uma card de Fusão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1412158,'Super Roboyarou',replace(replace('"Roboyarou" + "Robodama"	\r\nVocê pode Invocar "Super Robodama" por Invocação-Especial ao devolver este card do campo para o Deck Adicional. \r\nVocê não pode usar este efeito durante o mesmo turno em que este monstro foi Invocado por Invocação-Especial. \r\nAlém disso, aumente o ATK deste monstro em 1000 pontos durante a Etapa de Dano, quando este monstro batalhar com um monstro.','\r',char(13)),'\n',char(10)),'Aumentar ATK','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1426714,'Número 48: Lich Sombrio',replace(replace('2 monstros de Nível 3	\r\nUma vez por turno, durante o turno do seu oponente: você pode desassociar 1 Matéria Xyz deste card; Invoque por Invocação-Especial 1 "Ficha de Aparição" (Tipo Demônio/TREVAS/Nível 1/ATK 500/DEF 500). \r\n(Este é um Efeito Rápido.) \r\nEnquanto você controlar uma "Ficha de Aparição", seu oponente não pode escolher atacar este card. \r\nEste card ganha 500 de ATK para cada "Ficha de Aparição" que você controla.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1426715,'Ficha de Aparição','Invocado por Especial com o efeito "Número 48: Lich Sombrio".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1434352,'Necromante do Caos','O ATK deste card é igual ao número de Cards de Monstro no seu Cemitério x 300.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1435851,'Tesouro do Dragão','Um monstro do Tipo Dragão equipado com este card aumenta o seu ATK e DEF em 300 pontos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1463589,'Experimento Final Anti-GMX',replace(replace('Ative apenas se você controlar um monstro "GMX". \r\nUma vez por turno, quando seu oponente ativar um efeito de monstro no campo (exceto durante a Etapa de Dano): você pode escavar os 5 cards do topo do seu Deck e, depois, se você escavou um ou mais cards "GMX", negue esse efeito ativado e, além disso, coloque todos os cards escavados no topo ou no fundo do Deck em qualquer ordem.','\r',char(13)),'\n',char(10)),'Escavar cards','Colocar no topo do Deck','Colocar no fundo do Deck','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1474910,'Abelha Soldado','Você pode oferecer como Tributo este card e 1 monstro Inseto com a face para cima, exceto "Abelha Soldado"; compre 2 cards.','Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1475311,'Fascinação das Trevas','Compre 2 cards e, depois, bana 1 monstro de TREVAS da sua mão ou, se você não tiver nenhum na sua mão, envie toda a sua mão para o Cemitério.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1482001,'Clara & Rushka, o Ventrilodueto',replace(replace('1 monstro Invocado por Invocação-Normal/Baixado	\r\nNão pode ser Invocado por Invocação-Link exceto durante a Fase Principal 2.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1487805,'Fatiador Cósmico Zer''oll',replace(replace('2+ monstros Réptil	\r\nMonstros que seu oponente controla com Marcadores-A são colocados em Posição de Defesa e, além disso, nenhum duelista pode ativar seus efeitos. \r\nVocê só pode usar cada um dos seguintes efeitos de "Fatiador Cósmico Zer''oll" uma vez por turno. \r\nSe este card for Invocado por Invocação-Link: você pode adicionar 1 card do seu Deck à sua mão que tenha um efeito que coloque um ou mais Marcadores-A. \r\nVocê pode remover 2 Marcadores-A de qualquer parte do campo; imediatamente depois que este efeito resolver, Invoque por Invocação-Normal 1 monstro Réptil.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1490690,'Protetor Canópico',replace(replace('Uma vez por Corrente, quando seu oponente ativar um card ou efeito: você pode Invocar por Invocação-Especial 1 monstro "Horus" da sua mão ou do Cemitério, mas pelo resto deste turno, você não pode Invocar por Invocação-Especial monstros com o mesmo nome original pelo efeito de "Protetor Canópico". \r\nSe este card for enviado da mão ou do campo para o Cemitério: você pode Baixar este card, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar este efeito de "Protetor Canópico" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1498130,'Kagemusha dos Seis Samurai','Durante o turno de qualquer duelista, quando exatamente 1 monstro "Seis Samurai" com a face para cima for alvo de um Card de Armadilha, Card de Magia ou efeito de card do qual este card poderia ter sido alvo: você pode ativar este efeito; em vez disso, o alvo da Magia/Armadilha/efeito se torna este card no campo com a face para cima.','Alterar alvo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1498449,'Faimena Caudraco',replace(replace('Durante a Fase Principal (Efeito Rápido): você pode descartar este card; Invoque por Invocação-Fusão 1 monstro Dragão ou Mago do seu Deck Adicional, usando monstros da sua mão ou do campo. \r\nSe este card for enviado para o Cemitério como matéria para uma Invocação-Fusão: você pode Baixar 1 Magia/Armadilha "Caudraco" do seu Deck. \r\nVocê só pode usar cada efeito de "Faimena Caudraco" uma vez por turno.','\r',char(13)),'\n',char(10)),'Efeito de Fusão','Baixar Magia/Armadilha','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1508649,'Altergeist Héxstia',replace(replace('2 monstros "Altergeist"	\r\nGanha ATK igual ao ATK original de cada monstro "Altergeist" para o qual ele apontar. \r\nQuando um Card de Magia/Armadilha ou seus efeitos forem ativados (Efeito Rápido): você pode oferecer como Tributo 1 monstro "Altergeist" para o qual este card apontar; negue a ativação e, se isso acontecer, destrua esse card. \r\nSe este card for enviado do campo para o Cemitério: você pode adicionar 1 card "Altergeist" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Altergeist Héxstia" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1516510,'Dragão Pêndulo de Olhos Rúnicos',replace(replace('"Dragão Pêndulo de Olhos Anômalos" + 1 monstro do Tipo Mago	\r\nSe este card foi Invocado por Invocação-Fusão usando um ou mais monstros Invocados por Invocação-Pêndulo no campo como Matéria de Fusão, ele não pode ser afetado por efeitos de card do seu oponente neste turno. \r\nAplique o efeito apropriado, dependendo do Nível original do monstro usado como Matéria de Fusão que não tenha sido "Dragão Pêndulo de Olhos Anômalos".\r\n● Nível 4 ou menos: Este card pode realizar até 2 ataques contra monstros durante cada Fase de Batalha.\r\n● Nível 5 ou mais: Este card pode realizar até 3 ataques contra monstros durante cada Fase de Batalha.','\r',char(13)),'\n',char(10)),'Pode atacar até 2 monstros','Pode atacar até 3 monstros','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1525329,'O Caçador com Sete Armas',replace(replace('Quando este card for Invocado por Invocação-Normal, declare 1 Tipo de monstro. \r\nQuando batalhar com esse Tipo de monstro, aumente o ATK deste card em 1000 pontos durante o cálculo de dano.','\r',char(13)),'\n',char(10)),'Declarar um Tipo de monstro','Aumentar ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1527418,'Wiz, a Sábia de Peluguel',replace(replace('Se este card for Invocado por Invocação-Especial: você pode ganhar 500 PV para cada monstro "de Peluguel" que você controla com um nome diferente, exceto "Wiz, a Sábia de Peluguel". \r\nQuando seu oponente ativar um Card ou efeito de Magia/Armadilha (Efeito Rápido): você pode descartar 1 card "de Peluguel"; negue a ativação. \r\nVocê só pode usar cada efeito de "Wiz, a Sábia de Peluguel" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1528054,'Coelho Chapelhueta',replace(replace('2 Monstros de Efeito	\r\nSe este card batalhar um monstro, nenhum dos dois pode ser destruído nessa batalha. \r\nVocê só pode usar cada um dos seguintes efeitos de "Coelho Chapelhueta" uma vez por turno. \r\nSe este card for Invocado por Invocação-Link: você pode Baixar 1 Armadilha Contínua do seu Deck com um efeito que Invoque a si mesma por Invocação-Especial como um monstro e, além disso, este card não pode ser usado como Matéria Link neste turno. \r\nSe um card na Zona de Magias & Armadilhas for Invocado por Invocação-Especial na Zona de Monstros (exceto durante a Etapa de Dano): você pode escolher 1 Magia/Armadilha que seu oponente controla; destrua-a.','\r',char(13)),'\n',char(10)),'Baixar 1 Card de Armadilha Contínua','Destruir Cards de Magia/Armadilha','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1533292,'Magma Genex-R','Quando este card for Invocado por Invocação-Normal: você pode adicionar 1 monstro "Genex-R" de Nível 2 do seu Deck à sua mão.','Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1539051,'Presente do Espaço','Compre 1 card para cada nome diferente dentre os monstros "Neoespacial" que você controla.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1546123,'Dragão Final Cibernético',replace(replace('"Dragão Cibernético" + "Dragão Cibernético" + "Dragão Cibernético"	\r\nA Invocação-Fusão deste card só pode ser feita com as Matérias de Fusão acima. \r\nSe este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1546124,'Dragão Final Cibernético',replace(replace('"Dragão Cibernético" + "Dragão Cibernético" + "Dragão Cibernético"	\r\nA Invocação-Fusão deste card só pode ser feita com as Matérias de Fusão acima. \r\nSe este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1557341,'Rosa, Guerreira da Vingança','Quando este card causar dano de batalha ao seu oponente: cause 300 de dano ao seu oponente.','Receba 300 pontos de dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1557499,'Arco e Flecha de Prata','Um monstro do Tipo Fada equipado com este card aumenta o seu ATK e DEF em 300 pontos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1561110,'ABC - Dragão Banimento',replace(replace('"Núcleo de Assalto A" + "Dragonete do Banimento B" + "Wivern de Compressão C"	\r\nPrimeiro deve ser Invocado por Invocação-Especial (do seu Deck Adicional) ao banir os cards acima que você controla e/ou do seu Cemitério. \r\n(Você não usa "Polimerização".) \r\nUma vez por turno (Efeito Rápido): você pode descartar 1 card e, depois, escolha 1 card no campo; bana-o. \r\nDurante o turno do seu oponente (Efeito Rápido): você pode oferecer este card como Tributo e, depois, escolha 3 dos seus monstros União Máquina de LUZ banidos com nomes diferentes; Invoque-os por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Descarte 1 card; bana 1 card no campo','Ofereça este card como Tributo; Invoque por Invocação Especial seus monstros União banidos','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1566817,'Saque do Cupido',replace(replace('Não é afetado pelos efeitos ativados de monstros, exceto de monstros cujo Nível seja igual ou menor que o deste card. \r\nVocê pode banir até 3 cards do seu Cemitério; até o final deste turno, aumente o Nível deste card por esse número. \r\nVocê só pode usar este efeito de "Saque do Cupido" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1571945,'Ninja Branco','VIRE: Escolha 1 monstro em Posição de Defesa no campo; destrua o alvo.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1580833,'Dinonévoa Estegossaur',replace(replace('Escala de Pêndulo = 3\r\n[ Efeito de Pêndulo ]\r\nSe outro(s) card(s) "Dinonévoa" que você controla seria(m) destruído(s) em batalha ou por um efeito de card do oponente, em vez disso, você pode destruir este card.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe outro Monstro Pêndulo que você controla batalhar um monstro do oponente, depois do cálculo de dano: você pode destruir esses monstros.','\r',char(13)),'\n',char(10)),'Usar o efeito de "Dinonévoa Estegossaur" em vez de ser destruído?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1586457,'Cruzador Deep-Space IX','Você pode Invocar este card por Invocação-Especial (da sua mão) ao enviar 1 outro monstro do Tipo Máquina da sua mão para o Cemitério.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1595137,'Daneen, o Evoluído',replace(replace('"Daneen, o Dino Retornado" + 1 monstro Dinossauro	\r\nSe este card for Invocado por Invocação-Especial: você pode adicionar 1 card "GMX" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Daneen, o Evoluído" uma vez por turno. \r\nSe você escavar um ou mais cards devido a um efeito de card "GMX": você pode ativar o seguinte efeito, de acordo com onde este card estava na ativação (mas você só pode usar cada efeito de "Daneen, o Evoluído" uma vez por turno);\r\n● Campo: Ganhe 1500 PV.\r\n● Cemitério: Invoque este card por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Ativar o efeito','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1596508,'Arma Fortaleza Dimensional','Cards não podem ser enviados do Deck para o Cemitério.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1607603,'Duplo Dai',replace(replace('Ative 1 desses efeitos;\r\n● Se você não controlar nenhum monstro: Invoque por Invocação-Especial do seu Deck 1 monstro Guerreiro de Nível 4.\r\n● Escolha 1 monstro Guerreiro que você controla; Invoque por Invocação-Especial 1 monstro Guerreiro de TERRA com um Nível igual ou menor do seu Deck ou Cemitério.	\r\nVocê só pode ativar 1 "Duplo Dai" por turno.','\r',char(13)),'\n',char(10)),'Invoque por Invocação Especial 1 monstro Guerreiro de Nível 4 do seu Deck','Escolha 1 monstro Guerreiro que você controla; Invoque por Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1621413,'Dragão Xyz do Réquiem Negro',replace(replace('3 monstros de Nível 5	\r\nSe este card tiver "Dragão Xyz da Rebelião Negra" como matéria, ele ganha esses efeitos.\r\n● Uma vez por turno: você pode desassociar 1 matéria deste card e, depois, escolha 1 monstro com a face para cima que seu oponente controla; mude o ATK dele para 0 e, se isso acontecer, este card ganha ATK igual ao ATK original desse monstro.\r\n● Quando seu oponente ativar um efeito de monstro (Efeito Rápido): você pode desassociar 1 matéria deste card; negue a ativação e, se isso acontecer, destrua esse card e, depois, você pode Invocar por Invocação-Especial 1 Monstro Xyz do seu Cemitério.','\r',char(13)),'\n',char(10)),'Alterar ATK/DEF','Negar o efeito','Escolher um monstro para Invocá-lo por Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1637760,'Grande Corneta Celestial','Durante a Fase Principal do seu oponente, quando ele Invocaria um ou mais monstros por Invocação-Especial: negue a Invocação e, se isso acontecer, destrua esse monstro e, depois, seu oponente compra 1 card e, depois, termine a Fase Principal.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1639384,'Felgrand, o Divino Cavaleiro Dragão',replace(replace('2 monstros de Nível 8	\r\nUma vez por turno, durante o turno de qualquer duelista: você pode desassociar 1 Matéria Xyz deste card e, depois, escolher 1 monstro com a face para cima no campo; neste turno, seus efeitos são negados, mas ele não pode ser afetado por outros efeitos de card.','\r',char(13)),'\n',char(10)),'Não afetado','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1641882,'Fusionista','"Pequeno Anjo" + "Ovelha Mística nº 2"','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1644289,'Segmento Vylon',replace(replace('Equipe apenas em um monstro "Vylon". \r\nEle não pode ser escolhido como alvo pelos efeitos de monstro ou efeitos de Armadilha do oponente. \r\nSe este card com a face para cima no campo for enviado ao Cemitério: Você pode adicionar 1 Card de Magia "Vylon" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1662004,'Irmandade do Punho de Fogo - Espírito',replace(replace('Não pode ser usado como Matéria Sincro, exceto para a Invocação-Sincro de um monstro Besta-Guerreira. \r\nQuando este card for Invocado por Invocação-Normal: você pode escolher 1 monstro de FOGO de Nível 3 com 200 ou menos de DEF no seu Cemitério; Invoque o alvo por Invocação-Especial em Posição de Defesa e, se isso acontecer, os monstros que você controla não podem atacar pelo resto deste turno, exceto monstros Besta-Guerreira. \r\nVocê só pode usar este efeito de "Irmandade do Punho de Fogo - Espírito" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1665819,'Replicard NAD',replace(replace('Você pode banir 1 outro monstro de Nível 7 ou mais da sua mão; Invoque este card por Invocação-Especial da sua mão. \r\nVocê pode escolher 1 monstro com a face para cima que você controla; Invoque por Invocação-Especial 1 monstro do seu Deck com um nome diferente que tenha 2 ou mais dos mesmos Nível, ATK e/ou DEF, mas ele não pode ativar seus efeitos neste turno. \r\nVocê só pode usar cada efeito de "Replicard NAD" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar este card por Invocação Especial','Invocar por Invocação Especial do Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1669772,'Purificação de Magia','Descarte 1 card; destrua todas as Magias Contínuas com a face para cima no campo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1683982,'Rancor da Víbora',replace(replace('Monstros não-Réptil que você controla não podem atacar e, além disso, você não pode ativar seus efeitos. \r\nVocê só pode usar cada um dos seguintes efeitos de "Rancor da Víbora" uma vez por turno. \r\nSe um ou mais monstros Réptil com a face para cima que você controla forem destruídos em batalha ou enviados para o Cemitério: você pode Invocar por Invocação-Especial 1 monstro Réptil de Nível 4 ou menos do seu Deck. \r\nSe este card for destruído na Zona de Magias & Armadilhas: você pode devolver todos os seus monstros Réptil banidos para o seu Cemitério.','\r',char(13)),'\n',char(10)),'','Invocar por Invocação Especial do Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1686814,'Tzolkin Ultimaya',replace(replace('(O Nível original deste card deve ser sempre considerado como 12.)	\r\nNão pode ser Invocado por Invocação-Sincro. \r\nDeve ser Invocado por Invocação-Especial (do seu Deck Adicional) ao enviar 2 monstros de Nível 5 ou mais que você controla com o mesmo Nível para o Cemitério (1 Regulador e 1 não-Regulador). \r\nUma vez por turno, quando uma ou mais Magias/Armadilhas forem Baixadas no seu campo (exceto durante a Etapa de Dano): você pode Invocar por Invocação-Especial do seu Deck Adicional 1 Monstro Sincro "Ferramenteiro" ou 1 Monstro Sincro Dragão de Nível 7 ou 8. \r\nEnquanto você controlar outro Monstro Sincro, monstros não podem escolher este card como alvo de ataques e, além disso, nenhum duelista pode escolhê-lo como alvo de efeitos de card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1688285,'Armadilhatrix Pinguicula',replace(replace('2 monstros de Nível 4	\r\nEnquanto este card tiver matéria, ele não é afetado por efeitos de Armadilha e pelos efeitos ativados de outros monstros com o mesmo Tipo que as matérias deste card. \r\nVocê só pode usar cada um dos seguintes efeitos de "Armadilhatrix Pinguicula" uma vez por turno. \r\nVocê pode desassociar 1 matéria deste card; adicione 1 monstro "Armadilhatrix" do seu Deck à sua mão. \r\nSe um ou mais monstros dos quais seu oponente seja dono forem enviados para o Cemitério, ou banidos, por um efeito de card (exceto durante a Etapa de Dano): você pode associar 1 desses monstros a este card como matéria.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1689516,'A Grande Marcha dos Animais','Até o final deste turno, todos os monstros Besta com a face para cima que você controla ganham 200 de ATK para cada monstro Besta que você controla.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1697104,'PSÍ-Armação Equipamento Epsilon',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial por um efeito de card e não pode ser Invocado por Invocação-Especial de nenhuma outra forma. \r\nDurante o turno de qualquer duelista, quando seu oponente ativar um Card de Armadilha enquanto você não controlar nenhum monstro: você pode Invocar por Invocação-Especial tanto este card da sua mão quanto 1 "PSÍ-Armação Condutor" da sua mão, Deck ou Cemitério e, se isso acontecer, negue a ativação e, se isso também acontecer, destrua esse Card de Armadilha. \r\nDurante a Fase Final, bana os monstros com a face para cima Invocados por Invocação-Especial por este efeito.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1710476,'Dragão Final Cibernético Pernicioso',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao banir 1 "Dragão Final Cibernético" do seu Deck Adicional. \r\nSó pode haver 1 monstro "Pernicioso(a)" no campo. \r\nOutros monstros que você controla não podem declarar um ataque. \r\nSe não houver Magias de Campo com a face para cima no campo, destrua este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1710647,'Yoa, a Divindade da Praga Asutra',replace(replace('Você pode Invocar por Invocação-Especial este card (da sua mão) revelando 1 card com a face para baixo que você controla e o retornando para a mão/Deck Adicional. \r\nVocê só pode Invocar por Invocação-Especial "Yoa, a Divindade da Praga Asutra" uma vez por turno dessa forma.\r\nVocê só pode usar cada um dos seguintes efeitos de "Yoa, a Divindade da Praga Asutra" uma vez por turno.\r\nDurante sua Fase Principal: você pode Baixar 1 Magia/Armadilha "Asutra" do seu Deck.\r\nDurante o turno do seu oponente (Efeito Rápido): você pode escolher 1 monstro com a face para cima no campo; aumente ou reduza seu Nível em 1.','\r',char(13)),'\n',char(10)),'','Baixar','Alterar Nível','Aumentar o Nível','Reduzir o Nível','','','','','','','','','','','');
INSERT INTO texts VALUES(1712616,'Voar & Picar dos Bezoudados',replace(replace('Quando seu oponente ativar um efeito de monstro, enquanto você controlar um monstro "Bezoudado": negue a ativação e, se isso acontecer, destrua-o. \r\nDurante sua Fase Final, se este card estiver no seu Cemitério e você controlar um monstro Inseto com 3000 ou mais de ATK: você pode banir 1 monstro Inseto do seu Cemitério; Baixe este card. \r\nVocê só pode usar 1 efeito de "Voar & Picar dos Bezoudados" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1735088,'Zenmainutenção de Corda',replace(replace('2 monstros "de Corda"	\r\nSe este card for destruído e enviado para o Cemitério: você pode escolher 1 Monstro Xyz "de Corda" que você controla; associe este card a ele como matéria. \r\nVocê só pode usar cada um dos seguintes efeitos de "Zenmainutenção de Corda" uma vez por turno.\r\n● Se este card for Invocado por Invocação-Link: você pode adicionar 1 card "de Corda" do seu Deck à sua mão.\r\n● Você pode banir, com a face para baixo, 1 monstro "de Corda" com a face para cima que você controla; Invoque por Invocação-Especial 1 monstro do seu Deck com o mesmo nome que esse card tinha no campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1759808,'Retrato Demoníaco',replace(replace('Escolha 1 monstro com a face para cima que seu oponente controla; Invoque por Invocação-Especial 1 monstro com esse nome do seu Deck ou Deck Adicional, mas embaralhe-o no Deck durante a Fase Final do próximo turno e, além disso, você não pode Invocar monstros por Invocação-Especial do Deck ou Deck Adicional pelo resto deste turno depois que este card resolver. \r\nVocê só pode ativar 1 "Retrato Demoníaco" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1761063,'Nekogal N°1','Uma fada-gatinha. Ao contrário do que sua beleza sugere, ela ataca os inimigos com suas garras.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1764972,'Dragão Imperador da Condenação/Modo de Ataque',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial com "Ativar Modo de Ataque". \r\nSe este card for Invocado por Invocação-Especial: escolha 1 ou mais monstros Zumbi nos Cemitérios; Invoque esses alvos por Invocação-Especial, mas seus efeitos são negados e, além disso, destrua-os durante a Fase Final deste turno. \r\nQuando este card no campo for destruído: você pode escolher 1 "Dragão Imperador da Condenação" no seu Cemitério; Invoque o alvo por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Invocação Especial','Invocar "Dragão Imperador da Condenação" por Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1769875,'Quimera, o Rei Besta Fantasma',replace(replace('1 monstro Besta + 1 monstro Demônio	\r\n(Este card não é considerado como um card "Fantasma".)	\r\nO nome deste card se torna "Quimera, a Besta Mística Voadora" enquanto estiver no campo ou no Cemitério. \r\nVocê só pode usar cada um dos seguintes efeitos de "Quimera, o Rei Besta Fantasma" uma vez por turno. \r\nSe este card for Invocado por Invocação-Fusão: você pode ativar este efeito; durante a Fase Final deste turno, envie para o Cemitério 1 card aleatório da mão do seu oponente. \r\nDurante o turno do seu oponente (Efeito Rápido): você pode banir este card do seu Cemitério e, depois, escolha 1 monstro Besta, Demônio ou Ilusão no seu Cemitério; Invoque-o por Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1781310,'Fuh-Rin-Ka-Zan',replace(replace('Quando houverem um ou mais monstros de ÁGUA, FOGO, TERRA e VENTO no campo com a face para cima: aplique um dos seguintes efeitos.\r\n● Destrua todos os monstros que seu oponente controla.\r\n● Destrua todos os Cards de Magia e Armadilha que seu oponente controla.\r\n● Descarte 2 cards aleatórios da mão do seu oponente.\r\n● Compre 2 cards.','\r',char(13)),'\n',char(10)),'Destrua todos os monstros que seu oponente controla','Destrua todos os Cards de Magia/Armadilha que seu oponente controla','Seu oponente descarta 2 card(s) aleatoriamente','Compre 2 card(s)','','','','','','','','','','','','');
INSERT INTO texts VALUES(1784619,'Uraby','Rápido como o vento, este dinossauro dilacera os inimigos com suas garras afiadas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1784686,'O Olho de Timaeus',replace(replace('(Este card também deve ser sempre considerado como "Dragão Lendário Timaeus".)	\r\nEscolha 1 monstro "Mago(a) Negro(a)" que você controla; Invoque por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional que mencione esse monstro no campo como matéria, usando-o como a Matéria de Fusão. \r\nVocê só pode ativar 1 "O Olho de Timaeus" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1799464,'Transcigarra',replace(replace('Se este card for Invocado por Invocação-Especial: você pode Invocar por Invocação-Especial 1 "Ficha de Muda" (Inseto/TERRA/Nível 3/ATK 0/DEF 0). \r\nEnquanto a Ficha Invocada por Invocação-Especial por este efeito estiver no campo, você não pode Invocar monstros do Deck Adicional por Invocação-Especial, exceto monstros Inseto. \r\nVocê só pode usar este efeito de "Transcigarra" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1799465,'Ficha de Muda','Invocada por Invocação-Especial com o efeito "Transcigarra". Enquanto esta Ficha estiver no campo, o jogador que fez sua Invocação-Especial não pode fazer a Invocação-Especial de monstros do Deck Adicional, exceto monstros do Tipo Inseto.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1801154,'Campo Centrífugo','Quando um monstro de Fusão é destruído pelo efeito de um card e enviado para o Cemitério, escolha 1 dos Monstros-Matéria para a Fusão escritos no texto desse Monstro de Fusão do seu Cemitério e Invoque-o, por Invocação-Especial, no seu Campo.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1802450,'Cerimônia de Selamento de Mokuton','Uma vez por turno: você pode oferecer como Tributo 1 monstro de TERRA com a face para cima e, depois, escolha até 2 cards no Cemitério do oponente; bana os alvos.','Usar o efeito de "Cerimônia de Selamento de Mokuton" agora?','Banir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1804528,'Caixão Negro',replace(replace('Quando este card Baixado é destruído e enviado para o Cemitério, o seu adversário escolhe e executa 1 dos seguintes efeitos:\r\n● Descartar 1 card da sua mão aleatoriamente.\r\n● Escolhe 1 monstro no seu Campo e destrói-o.','\r',char(13)),'\n',char(10)),'Escolher um efeito','Descarte 1 card(s) aleatoriamente da sua mão','Destrua 1 monstro que você controla','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1825445,'União Super Quantal - Magnaformação',replace(replace('Seu oponente não pode escolher cards "Super Quant" no campo como alvo de efeitos de card durante sua Fase Principal 1. \r\nVocê pode escolher 1 Monstro Xyz "Super Quant" que você controla; associe 1 outro monstro com a face para cima que você controla a ele como matéria. \r\nVocê só pode usar este efeito de "União Super Quantal - Magnaformação" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1826676,'Cavaleiro Brinquedo',replace(replace('Não pode ser Invocado por Invocação-Especial do Deck. \r\nSe seu oponente controlar mais monstros que você, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nQuando este card for Invocado por Invocação-Normal ou Especial: você pode Invocar por Invocação-Especial 1 "Cavaleiro Brinquedo" da sua mão.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1828513,'Sombra dos Seis Samurai - Shien',replace(replace('2 monstros "Seis Samurai" de Nível 4	\r\nUma vez por turno (Efeito Rápido): você pode desassociar 1 matéria deste card e, depois, escolher 1 monstro "Seis Samurai" que você controla com menos de 2000 de ATK; até o final deste turno, o ATK original dele se torna 2000.','\r',char(13)),'\n',char(10)),'Alterar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1833916,'Desafiante Heroico - Mil Lâminas',replace(replace('Uma vez por turno, se este card estiver em Posição de Ataque: você pode descartar 1 card "Heroico(a)"; Invoque por Invocação-Especial 1 monstro "Heroico(a)" do seu Deck e, se isso acontecer, coloque este card em Posição de Defesa e, além disso, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros "Heroico(a)". \r\nQuando você sofrer dano enquanto este card estiver no seu Cemitério: você pode Invocar este card por Invocação-Especial em Posição de Ataque. \r\nVocê só pode usar este efeito de "Desafiante Heroico - Mil Lâminas" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1834107,'Wattsfera','Quando um monstro Trovão que você controla causar dano de batalha ao seu oponente: ganhe PV igual ao dano que ele sofreu.','Ganhar PV','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1834753,'Teletransporte Overdrive',replace(replace('Este card não pode ser Invocado por Invocação-Especial. \r\nVocê pode pagar 2000 PV para Invocar por Invocação-Especial 2 monstros do Tipo Psíquico de Nível 3 do seu Deck. \r\nEste efeito só pode ser usado uma vez enquanto este card estiver com a face para cima no campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1845204,'Fusão Instantânea',replace(replace('Pague 1000 PV; Invoque por Invocação-Especial 1 Monstro de Fusão de Nível 5 ou menos do seu Deck Adicional, mas ele não pode atacar e, além disso, ele é destruído durante a Fase Final. \r\n(Isso é considerado uma Invocação-Fusão.) \r\nVocê só pode ativar 1 "Fusão Instantânea" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1855886,'Cicatriz do Vendorror',replace(replace('Se este card for enviado para o Cemitério: você pode adicionar 1 Magia/Armadilha "Vendorror" do seu Deck à mão. \r\nSe um ou mais monstros no campo forem oferecidos como Tributo, enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode banir 1 outro monstro Zumbi do seu Cemitério; Invoque este card por Invocação-Especial e, se isso acontecer, enquanto ele estiver com a face para cima na Zona de Monstros, você não pode Invocar monstros por Invocação-Especial, exceto monstros "Vendorror". \r\nVocê só pode usar cada efeito de "Cicatriz do Vendorror" uma vez por turno.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1855932,'Bujintei Kagutsuchi',replace(replace('2 monstros do Tipo Besta-Guerreira de Nível 4	\r\nQuando este card for Invocado por Invocação-Xyz: envie os 5 cards do topo do seu Deck para o Cemitério (ou todo o seu Deck, se tiver menos de 5) e, além disso, este card ganha 100 de ATK para cada card "Bujin" enviado para o Cemitério por este efeito. \r\nSe um ou mais monstros "Bujin" do Tipo Besta-Guerreira que você controla seriam destruídos em batalha ou por efeitos de card, você pode desassociar 1 Matéria Xyz deste card em vez de destruir 1 desses monstros. \r\nVocê só pode controlar 1 "Bujintei Kagutsuchi".','\r',char(13)),'\n',char(10)),'Aumentar ATK','Usar o efeito de "Bujintei Kagutsuchi" em vez de ser destruído?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1861629,'Decodificar Transmissor',replace(replace('2+ Monstros de Efeito	\r\nGanha 500 de ATK para cada monstro para o qual ele apontar. \r\nQuando seu oponente ativar um card ou efeito que escolha como alvo um ou mais cards que você controla (Efeito Rápido): você pode oferecer como Tributo 1 monstro para o qual este card apontar; negue a ativação e, se isso acontecer, destrua esse card.','\r',char(13)),'\n',char(10)),'Negar a ativação e destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1861630,'Decodificar Transmissor',replace(replace('2+ Monstros de Efeito	\r\nGanha 500 de ATK para cada monstro para o qual ele apontar. \r\nQuando seu oponente ativar um card ou efeito que escolha como alvo um ou mais cards que você controla (Efeito Rápido): você pode oferecer como Tributo 1 monstro para o qual este card apontar; negue a ativação e, se isso acontecer, destrua esse card.','\r',char(13)),'\n',char(10)),'Negar a ativação e destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1861631,'Decodificar Transmissor',replace(replace('2+ Monstros de Efeito	\r\nGanha 500 de ATK para cada monstro para o qual ele apontar. \r\nQuando seu oponente ativar um card ou efeito que escolha como alvo um ou mais cards que você controla (Efeito Rápido): você pode oferecer como Tributo 1 monstro para o qual este card apontar; negue a ativação e, se isso acontecer, destrua esse card.','\r',char(13)),'\n',char(10)),'Negar a ativação e destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1872843,'Morfeu, o Cavaleiro Branco do Espelho Onírico',replace(replace('Se este card for Invocado por Invocação-Especial pelo efeito de um monstro "Espelho Onírico": você pode ativar este efeito; este card não pode ser destruído em batalha ou por efeitos de card neste turno. \r\nDurante a Fase Principal ou de Batalha, se "Espelho Onírico do Terror" estiver em uma Zona do Campo (Efeito Rápido): você pode oferecer este card como Tributo; Invoque por Invocação-Especial 1 "Morfeu, o Cavaleiro Negro do Espelho Onírico" do seu Deck. \r\nVocê só pode usar cada efeito de "Morfeu, o Cavaleiro Branco do Espelho Onírico" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1876841,'Escanem Morfotrônico',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro deve ser Invocado por Invocação-Especial (da sua mão) ao banir 1 monstro "Morfotrônico(a)" da sua mão.\r\n● Posição de Ataque: Uma vez por turno, durante sua Fase Principal: você pode adicionar 1 Magia/Armadilha "Morfotrônico(a)" do seu Deck à sua mão e, depois, coloque 1 card da sua mão no topo do Deck.\r\n● Posição de Defesa: Uma vez por turno, durante sua Fase Principal: você pode adicionar 1 monstro "Morfotrônico(a)" de Nível 4 ou menos do seu Cemitério à sua mão e, depois, coloque 1 card da sua mão no topo do Deck.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1896112,'Explosão de Dimensões',replace(replace('Devolva 1 Monstro de Fusão com a face para cima que você controla para o Deck Adicional. \r\nAmbos os duelistas escolhem até 2 dos seus monstros que estiverem removidos de jogo e os Invocam por Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1906812,'Mecanorde, o Dragão do Projétil de Ferro',replace(replace('"Caído de Arbaz" + 1 Monstro de Efeito Invocado por Invocação-Especial neste turno	\r\nDurante sua Fase Principal: você pode mover este card que você controla para outra das suas Zonas de Monstros Principais e, depois, você pode destruir todos os outros cards com a face para cima na coluna deste card. \r\nDurante a Fase Final, se este card estiver no Cemitério porque foi enviado para lá neste turno: você pode adicionar à sua mão, ou Invocar por Invocação-Especial, 1 monstro "Springans" ou 1 "Caído de Arbaz" do seu Deck. \r\nVocê só pode usar cada efeito de "Mecanorde, o Dragão do Projétil de Ferro" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Destruir todos os outros cards com a face para cima na coluna deste card?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1918087,'Oficial Menor Goblin',replace(replace('Você só pode ativar este card quando os PV do seu oponente forem 3000 ou menos. \r\nCause 500 de dano ao seu oponente durante cada uma das Fases de Apoio dele.','\r',char(13)),'\n',char(10)),'Cause 500 de dano ao seu oponente','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1929294,'Cetro de Chave','Os inimigos ficarão todos derretidos ao ver a fofura desta fada.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1942635,'Espólios do Chefe Generaidor',replace(replace('Enquanto você controlar uma Ficha, os monstros do seu oponente não podem escolher Monstros de Efeito "Generaidor" como alvo de ataques. \r\nSe um Monstro de Efeito "Generaidor" for destruído em batalha: seu oponente compra 1 card. \r\nVocê só pode usar este efeito de "Espólios do Chefe Generaidor" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1945387,'Mestre Nova, o HERÓI do Elemento',replace(replace('1 monstro "HERÓI do Elemento" + 1 monstro de FOGO	\r\nDeve ser Invocado por Invocação-Fusão. \r\nSe este card destruir um monstro do oponente em batalha: compre 1 card.','\r',char(13)),'\n',char(10)),'Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1948619,'Condutor Maravilha, o HERÓI Xtra',replace(replace('2 monstros "HERÓI"	\r\nSe um monstro "HERÓI" for Invocado por Invocação-Normal ou Especial em uma zona sua para a qual este card apontar: escolha 1 Magia "Polimerização", 1 Magia "Fusão" ou 1 Magia Rápida "Mudar" no seu Cemitério; Baixe o alvo. \r\nVocê só pode ativar este efeito de "Condutor Maravilha, o HERÓI Xtra" uma vez por turno. \r\nSe este card for destruído em batalha e enviado para o Cemitério, ou se este card em sua posse for destruído por um efeito de card do oponente e enviado para o seu Cemitério: Invoque por Invocação-Especial 1 monstro "HERÓI" da sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1953925,'Engenheiro do Mecanismo Antigo',replace(replace('Negue quaisquer efeitos de Armadilha que escolham este card como alvo e, se isso acontecer, destrua o Card de Armadilha em questão. \r\nSe este card atacar, seu oponente não pode ativar quaisquer Cards de Magia/Armadilha até o final da Etapa de Dano. \r\nNo final da Etapa de Dano, se este card atacou: escolha 1 Magia/Armadilha que seu oponente controla; destrua o alvo.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1965724,'Ira de Mokey Mokey','Se um monstro Fada com a face para cima que você controla for destruído enquanto você controlar um "Mokey Mokey", até o final deste turno, o ATK de cada "Mokey Mokey" que você controla se torna 3000.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1966438,'Alma Desacorrentada Abominável',replace(replace('Você só pode Invocar um ou mais "Alma Desacorrentada Abominável" por Invocação-Especial uma vez por turno. \r\nSe um ou mais cards que você controla forem destruídos em batalha ou por um efeito de card: você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe este card for Invocado por Invocação-Especial: você pode descartar 1 card; destrua 1 card no campo. \r\nUma vez por turno, durante a Fase Final, se este card estiver no Cemitério porque foi destruído no campo e enviado para lá neste turno: você pode Invocar este card por Invocação-Especial, mas coloque-o no fundo do Deck quando ele deixar o campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1969506,'Marionete Ritual',replace(replace('Se os Pontos de Vida do seu oponente estiverem pelo menos 2000 acima dos seus: você pode escolher 2 monstros "Engenhoca Marionete" de Nível 8 no seu Cemitério; Invoque os alvos por Invocação-Especial. \r\nVocê só pode ativar 1 "Marionete Ritual" por turno. \r\nVocê não pode conduzir sua Fase de Batalha no turno em que ativar este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1980574,'Esquadrão dos Orelhas de Pé',replace(replace('Durante a Fase Principal do seu oponente (Efeito Rápido): você pode escolher 1 monstro com a face para cima que você controla; Invoque este card por Invocação-Especial da sua mão e, se isso acontecer, imediatamente depois que este efeito resolver, Invoque por Invocação-Sincro 1 Monstro Sincro usando apenas este card que você controla e o alvo. \r\nVocê só pode usar este efeito de "Esquadrão dos Orelhas de Pé" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1984618,'Servo Nadir',replace(replace('Envie 1 monstro do seu Deck Adicional para o Cemitério e, depois, adicione do seu Deck ou Cemitério à sua mão, 1 monstro "Dogmatika" ou "Caído de Arbaz" que tenha um ATK igual ou menor que o desse monstro enviado no Cemitério, e, além disso, pelo resto deste turno depois que este card resolver, você não pode Invocar por Invocação-Especial do Deck Adicional. \r\nVocê só pode ativar 1 "Servo Nadir" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1992816,'Número 9: Esfera de Dyson',replace(replace('2 monstros de Nível 9	\r\nDurante sua Fase Principal 1, se seu oponente controlar um monstro com ATK maior que o deste card: você pode desassociar 1 matéria deste card; este card pode atacar diretamente neste turno. \r\nUma vez por Etapa de Batalha, se este card com matéria for atacado (Efeito Rápido): você pode negar esse ataque. \r\nQuando este card for escolhido como alvo de um ataque enquanto não tiver matéria: você pode escolher 2 monstros no seu Cemitério; associe esses monstros a este card como matéria.','\r',char(13)),'\n',char(10)),'Negar o ataque','Associar material','Ataque direto','','','','','','','','','','','','','');
INSERT INTO texts VALUES(1995985,'Espadachim Silencioso LV3',replace(replace('Negue os efeitos de Magia do seu oponente que escolham este card como alvo. \r\nDurante sua Fase de Apoio: você pode enviar este card com a face para cima para o Cemitério; Invoque por Invocação-Especial 1 "Espadachim Silencioso LV5" da sua mão ou Deck. \r\nVocê não pode ativar este efeito no turno em que este card for Invocado ou virado com a face para cima.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2006591,'Despertar dos Despojos do Pecado',replace(replace('Se seu oponente controlar 3 ou mais monstros e você controlar um monstro Ilusão de Nível 5 ou mais: escolha até 3 cards que seu oponente controla; devolva-os para a mão. \r\nSe você controlar um monstro Ilusão de Nível 5 ou mais e este card estiver no seu Cemitério: você pode Baixar este card, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar 1 efeito de "Despertar dos Despojos do Pecado" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Retornar para a mão','Baixar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2009101,'Asanegra - Ventoa, o Furacão',replace(replace('Se você controlar um monstro "Asanegra" que não seja "Asanegra - Ventoa, o Furacão", você pode Invocar este card por Invocação-Especial (da sua mão). \r\nUma vez por turno: você pode escolher 1 monstro com a face para cima que seu oponente controla; o ATK/DEF do alvo se tornam metade do ATK/DEF atuais.','\r',char(13)),'\n',char(10)),'Reduzir ATK/DEF pela metade','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2047519,'Soldados Escondidos','Quando o oponente Invocar um monstro por Invocação-Normal ou Invocação-Virar: Invoque por Invocação-Especial 1 monstro de TREVAS de Nível 4 ou menos da sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2055403,'Buraco Armadilha Espaço-Tempo','Quando seu oponente Invocar um ou mais monstros por Invocação-Especial da mão ou do Deck Adicional: embaralhe esse(s) monstro(s) no Deck e, depois, você perde 1000 PV para cada monstro devolvido.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2061963,'Número 104: Mascarado',replace(replace('3 monstros de Nível 4	\r\nDurante a Fase de Batalha, quando seu oponente ativar um efeito de monstro (Efeito Rápido): você pode desassociar 1 matéria deste card; negue a ativação e, se isso acontecer, cause 800 de dano ao seu oponente. \r\nUma vez por turno, durante sua Fase Principal: você pode enviar o card do topo do Deck do seu oponente para o Cemitério.','\r',char(13)),'\n',char(10)),'Negar o efeito','Enviar do Deck para o Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2067935,'Besta Gladiadora Lanista',replace(replace('Quando este card for Invocado por Invocação-Especial pelo efeito de um monstro "Besta Gladiadora": Escolha 1 monstro "Besta Gladiadora" no seu Cemitério; bana o alvo, e o nome deste card se torna o nome do alvo até a Fase Final. \r\nNo final da Fase de Batalha, se este card atacou ou foi atacado: Você pode embaralhá-lo no Deck; Invoque por Invocação-Especial 1 monstro "Besta Gladiadora" do seu Deck, exceto "Besta Gladiadora Lanista".','\r',char(13)),'\n',char(10)),'Banir','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2084239,'Pântano','Todos os monstros do Tipo Aqua/ÁGUA/Nível 2 ou menos ganham 1200 de ATK.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2088870,'Lombriga da Vitória',replace(replace('VIRE: Destrua todos os monstros com a face para cima no campo, exceto monstros "Lombriga" do Tipo Réptil. \r\nEste card ganha 500 de ATK para cada monstro "Lombriga" do Tipo Réptil no seu Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2089016,'Cronomalia Foguete de Tushpa',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode enviar 1 monstro "Cronomalia" do seu Deck ou Deck Adicional para o Cemitério e, depois, escolha 1 monstro com a face para cima no campo; até o final deste turno, ele perde ATK igual ao Nível/Classe do monstro enviado para o Cemitério x 200. \r\nUm Monstro Xyz "Número" que foi Invocado usando este card no campo como matéria ganha este efeito.\r\n● Este card pode realizar até 2 ataques contra monstros durante cada Fase de Batalha.	\r\nVocê só pode usar cada efeito de "Cronomalia Foguete de Tushpa" uma vez por turno.','\r',char(13)),'\n',char(10)),'','O efeito de "Cronomalia Foguete de Tushpa" está sendo aplicado.','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2091298,'Constelar Praesepe',replace(replace('2 monstros "Constelar" de Nível 4	\r\nUma vez por turno, durante a Etapa de Dano do turno de qualquer duelista, quando um monstro "Constelar" que você controla atacar ou for atacado: você pode desassociar 1 Matéria Xyz deste card; até o final da Fase Final, esse monstro ganha 1000 de ATK.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2095764,'Bixi, Água de Yang Zing',replace(replace('Quando este card que você controla for destruído em batalha ou por um efeito de card e enviado para o seu Cemitério: você pode Invocar por Invocação-Especial 1 monstro "Yang Zing" do seu Deck em Posição de Ataque, exceto "Bixi, Água de Yang Zing". \r\nVocê só pode usar este efeito de "Bixi, Água de Yang Zing" uma vez por turno. \r\nUma vez por turno, durante a Fase Principal ou a Fase de Batalha do seu oponente, você pode: imediatamente depois que este efeito resolver, Invoque por Invocação-Sincro 1 Monstro Sincro, usando apenas monstros "Yang Zing" que você controla (este é um Efeito Rápido). \r\nUm Monstro Sincro que usou este card como uma Matéria Sincro não é afetado por efeitos de Armadilha.','\r',char(13)),'\n',char(10)),'Invocação Especial','O efeito de "Bixi, Água de Yang Zing" está sendo aplicado.','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2099841,'Mundo Sorridente','Até o final deste turno, todos os monstros com a face para cima atualmente no campo ganham 100 de ATK para cada monstro atualmente no campo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2102065,'Brinegir',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 monstro de ÁGUA no seu Cemitério; até o final deste turno, este card ganha ATK igual ao ATK desse monstro. \r\nSe este card for enviado para o Cemitério: você pode escolher 1 monstro de ÁGUA que você controla; ele ganha 1000 de ATK até o final deste turno. \r\nVocê só pode usar cada efeito de "Brinegir" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2106266,'Gaia Galopante',replace(replace('Seu oponente não pode ativar cards ou efeitos durante a Fase de Batalha enquanto "Gaia, o Matador de Dragões" estiver na sua Zona de Monstros. \r\nVocê pode ativar 1 dos seguintes efeitos.\r\n● Você pode revelar 1 monstro "Gaia, o Cavaleiro Impetuoso" da sua mão; adicione 1 monstro Dragão de Nível 5 do seu Deck à sua mão.\r\n● Você pode revelar 1 monstro Dragão de Nível 5 na sua mão; adicione 1 monstro "Gaia, o Cavaleiro Impetuoso" do seu Deck à sua mão.	\r\nVocê só pode usar este efeito de "Gaia Galopante" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão 1 monstro Dragão de Nível 5','Adicionar 1 monstro "Gaia, o Cavaleiro Impetuoso" à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2111707,'XY - Dragão Canhão',replace(replace('"Cabeça de Canhão X" + "Cabeça de Dragão Y"	\r\nPrimeiro deve ser Invocado por Invocação-Especial (do seu Deck Adicional) ao banir os cards acima que você controla. \r\n(Você não usa "Polimerização".) \r\nNão pode ser Invocado por Invocação-Especial do Cemitério. \r\nVocê pode descartar 1 card e, depois, escolha 1 Magia/Armadilha com a face para cima que seu oponente controla; destrua o alvo.','\r',char(13)),'\n',char(10)),'Destruir Magias/Armadilhas','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2116237,'Loka Samsara',replace(replace('Bana 1 "Visas Starfrost" com a face para cima da sua Zona de Monstros (até a Fase Final); Invoque por Invocação-Especial 1 monstro "Heart" com 3000 de ATK do seu Deck Adicional, ignorando suas condições de Invocação, mas ele só pode ativar seus efeitos uma vez enquanto estiver com a face para cima no campo e, além disso, bana-o com a face para baixo durante a Fase Final. \r\nSe seu oponente Invocar um ou mais monstros por Invocação-Especial do Deck Adicional, enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode adicionar este card à sua mão. \r\nVocê só pode usar cada efeito de "Loka Samsara" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Retornar ao campo os monstros banidos quando ativado','Banir com a face para baixo o monstro Invocado por Invocação Especial','','','','','','','','','','','','');
INSERT INTO texts VALUES(2118022,'Hyosube','Este anfíbio tem um ataque forte, mas deixa muito a desejar quanto às suas defesas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2122975,'Recuperação de Armadilha',replace(replace('Descarte 1 card e ative este card em corrente a um Card de Armadilha que você ativou. \r\nQuando esse Card de Armadilha for enviado para o Cemitério, devolva-o para a mão do seu dono.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2129638,'Dragão Gêmeo da Explosão de Olhos Azuis',replace(replace('"Dragão Branco de Olhos Azuis" + "Dragão Branco de Olhos Azuis"	\r\nDeve ser Invocado por Invocação-Fusão, ou por Invocação-Especial ao enviar os monstros acima que você controla para o Cemitério. \r\nNão pode ser destruído em batalha. \r\nPode realizar até 2 ataques contra monstros durante cada Fase de Batalha. \r\nNo final da Etapa de Dano, quando este card atacar um monstro do oponente, mas o monstro do oponente não for destruído na batalha: você pode banir o monstro do oponente.','\r',char(13)),'\n',char(10)),'Banir um monstro do oponente','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2130625,'Curador Harmonioso',replace(replace('Você só pode ativar este card quando sofrer dano. \r\nAumente seus PV em 1000. \r\nAlém disso, aumente seus PV em 500 para cada card "Curador Harmonioso" no seu Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2133971,'Controlador da União',replace(replace('1 monstro Máquina de LUZ + "Cabeça Yare-Y" ou "Tanque Zilhão-Z"	\r\nPrimeiro deve ser Invocado por Invocação-Especial (do seu Deck Adicional) ao banir os cards acima que você controla. \r\nSe este card for Invocado por Invocação-Especial do Deck Adicional: você pode adicionar 1 Magia/Armadilha do seu Deck à sua mão que mencione "monstro União" em seu texto. \r\nVocê só pode usar este efeito de "Controlador da União" uma vez por turno. \r\nUma vez por turno, durante sua Fase Principal: você pode Invocar por Invocação-Especial 1 monstro Normal ou União Máquina de LUZ da sua mão.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2134346,'Sacerdote Asura',replace(replace('Não pode ser Invocado por Invocação-Especial. \r\nDurante a Fase Final do turno em que este card for Invocado por Invocação-Normal ou virado com a face para cima: devolva-o para a mão. \r\nPode atacar todos os monstros que seu oponente controla uma vez cada.','\r',char(13)),'\n',char(10)),'Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2137678,'Exército Senhormek de Granel',replace(replace('Ganha 100 de ATK para cada monstro "Senhormek" no campo, exceto este card. \r\nQuando este card for Invocado por Invocação-Normal: você pode escolher 1 monstro com a face para cima que seu oponente controla; até o final deste turno, diminua o ATK do alvo pela metade.','\r',char(13)),'\n',char(10)),'Reduzir ATK pela metade','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2139640,'Amabie','No começo da sua Fase Principal 1: você pode revelar este card na sua mão; cada duelista ganha 300 PV.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2144946,'F.A. Grande Prêmio Off-Road',replace(replace('Aumente em 2 os Níveis de todos os monstros "F.A." no campo, apenas durante a Fase Principal. \r\nVocê só pode usar cada um dos seguintes efeitos de "F.A. Grande Prêmio Off-Road" uma vez por turno.\r\n● Quando um monstro "F.A." que você controla for destruído em batalha: você pode descartar 1 card aleatório da mão do seu oponente.\r\n● Se este card com a face para cima no campo for destruído por um efeito de card: você pode adicionar 1 card "F.A." do seu Deck à sua mão, exceto "F.A. Grande Prêmio Off-Road".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2148918,'Habilidade Ninjitsu da Névoa Oxidante',replace(replace('Quando um ou mais monstros forem Invocados por Invocação-Especial no campo do seu oponente, se você controlar um monstro "Ninja": diminua pela metade o ATK atual desse(s) monstro(s) \r\nInvocado(s) por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Alterar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2158562,'Bailarina Cibernética','Se este card for Invocado por Invocação-Tributo: destrua todas as Magias com a face para cima no campo.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2191144,'Papilloperativo Noturno',replace(replace('3 monstros de Nível 4	\r\nUma vez por turno: você pode desassociar 1 Matéria Xyz deste card; este card ganha 300 de ATK para cada Matéria Xyz associada a um monstro no campo.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2196767,'Duelista Lendário',replace(replace('Uma vez por turno, você pode lançar uma moeda 3 vezes e aplicar o efeito apropriado:\r\n● 3 Caras: Destrua todos os monstros que seu oponente controla.\r\n● 2 Caras: Descarte 1 card aleatório da mão do seu oponente.\r\n● 1 Cara: Destrua 1 card que você controla.\r\n● 3 Coroas: Descarte toda a sua mão.','\r',char(13)),'\n',char(10)),'Jogar uma moeda','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2203790,'Sabre-XX Hyunlei',replace(replace('1 Regulador + 1+ monstros "Sabre-X" não-Reguladores	\r\nQuando este card for Invocado por Invocação-Sincro: você pode escolher até 3 Magias/Armadilhas no campo; destrua-as.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2204038,'Valquíria-Brunhilde',replace(replace('Não é afetado pelos efeitos de Magia do seu oponente. \r\nGanha 500 de ATK para cada monstro que seu oponente controla. \r\nQuando um monstro do oponente declarar um ataque: você pode fazer com que este card perca exatamente 1000 de DEF e, se isso acontecer, seus monstros "Valquíria-" não podem ser destruídos em batalha neste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2204140,'Livro da Vida','Escolha 1 monstro Zumbi no seu Cemitério e 1 monstro no Cemitério do seu oponente; Invoque por Invocação-Especial o primeiro alvo e, além disso, bana o segundo alvo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2220237,'Gardna Seguro',replace(replace('1 Monstro Link Ciberso	\r\nDepois que este card for Invocado por Invocação-Especial, você não sofre dano de efeito pelo resto deste turno. \r\nUma vez por turno, se você sofreria dano de batalha ou de efeito, você não sofre dano. \r\nNão pode ser usado como Matéria Link. \r\nVocê só pode controlar 1 "Gardna Seguro".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2250266,'Grampeadoren Morfotrônico',replace(replace('● Enquanto estiver em Posição de Ataque: Seu oponente não pode selecionar outro monstro que você controla como alvo de um ataque.	\r\nSe este card for destruído em batalha, o monstro que destruiu este card perde 300 de ATK.\r\n● Enquanto estiver em Posição de Defesa: Este card não pode ser destruído em batalha.	\r\nSe este card for atacado, depois do cálculo de dano, selecione 1 monstro com a face para cima em Posição de Ataque que seu oponente controla. \r\nMude-o para Posição de Defesa e este card para Posição de Ataque.','\r',char(13)),'\n',char(10)),'Reduzir ATK','Mudar para Posição de Ataque','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2254222,'Velocidaroide Asas Sincron',replace(replace('Escala de Pêndulo = 4\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno: você pode destruir este card e 1 Card de Monstro Pêndulo de VENTO de Nível 2 na sua Zona de Pêndulo e, se isso acontecer, Invoque por Invocação-Especial 1 "Dragão Sincro de Asas Transparentes" do seu Deck Adicional (isso é considerado uma Invocação-Sincro) e, além disso, pelo resto deste turno, cards nas suas Zonas de Pêndulo não podem ser destruídos por efeitos de card e você não pode Invocar por Invocação-Especial, exceto monstros de VENTO.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe este card for adicionado ao seu Deck Adicional com a face para cima e você controlar 2 ou mais Tipos diferentes de Monstros Sincro de VENTO: você pode enviar 1 Magia/Armadilha "Velocidaroide" do seu Deck para o Cemitério. \r\nVocê só pode usar este efeito de "Velocidaroide Asas Sincron" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Enviar para o Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2263869,'Assassina Definitiva',replace(replace('Seu oponente não pode ativar efeitos de monstro em resposta à ativação deste card. \r\nEnvie 1 monstro do seu Deck Adicional para o Cemitério e, depois, escolha 1 monstro que seu oponente controla com o mesmo tipo de card (Fusão, Sincro, Xyz, Pêndulo ou Link); embaralhe-o no Deck.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2263870,'Assassina Definitiva',replace(replace('Seu oponente não pode ativar efeitos de monstro em resposta à ativação deste card. \r\nEnvie 1 monstro do seu Deck Adicional para o Cemitério e, depois, escolha 1 monstro que seu oponente controla com o mesmo tipo de card (Fusão, Sincro, Xyz, Pêndulo ou Link); embaralhe-o no Deck.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2266498,'Reunião Vendorror',replace(replace('Revele 1 Monstro de Ritual "Vendorror" na sua mão, Invoque por Invocação-Especial qualquer número dos seus monstros "Vendorror" banidos com nomes diferentes, com a face para baixo em Posição de Defesa, cuja soma dos Níveis seja exatamente igual ao Nível do Monstro de Ritual revelado, ofereça como Tributo todos esses monstros com a face para baixo em Posição de Defesa e, depois, Invoque por Invocação-Ritual esse Monstro de Ritual da sua mão. \r\nVocê deve ser capaz de Invocar por Invocação-Ritual para ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2273734,'Cavaleirostélite Altair',replace(replace('Se este card for Invocado: você pode escolher 1 monstro "Cavaleirost" no seu Cemitério, exceto "Cavaleirostélite Altair"; Invoque esse monstro por Invocação-Especial em Posição de Defesa e, além disso, os monstros que você controla não podem atacar pelo resto deste turno, exceto monstros "Cavaleirost". \r\nVocê só pode usar este efeito de "Cavaleirostélite Altair" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2287848,'Revolução Vendorror',replace(replace('Descarte 1 card e, depois, escolha 1 monstro "Vendorror" e 1 Magia de Ritual no seu Cemitério; Invoque esse monstro por Invocação-Especial em Posição de Defesa e, se isso acontecer, adicione essa Magia de Ritual à sua mão. \r\nVocê pode banir este card do seu Cemitério e, depois, escolher 5 dos seus monstros Zumbi banidos; embaralhe-os no seu Deck e, depois, compre 1 card. \r\nVocê só pode usar cada efeito de "Revolução Vendorror" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2295440,'Um por Um','Envie 1 monstro da sua mão para o Cemitério; Invoque por Invocação-Especial 1 monstro de Nível 1 da sua mão ou do Deck.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2295441,'Um por Um','Envie 1 monstro da sua mão para o Cemitério; Invoque por Invocação-Especial 1 monstro de Nível 1 da sua mão ou do Deck.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2295831,'Símbolo da Amizade',replace(replace('Para ativar este card, você deve comprá-lo durante sua compra normal na sua Fase de Compra, enquanto seu oponente controlar 3 ou mais monstros e você não controlar nenhum card, revelá-lo e mantê-lo revelado até a Fase Principal 1. \r\nDurante sua Fase Principal 1 nesse mesmo turno: você pode ativar este card da sua mão; revele 1 card do seu Deck e adicione-o à sua mão.','\r',char(13)),'\n',char(10)),'Manter "Símbolo da Amizade" revelado?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2311090,'Cenoura Spright',replace(replace('Se você controlar um monstro de Nível/Link 2, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Cenoura Spright" por Invocação-Especial uma vez por turno desta forma. \r\nQuando seu oponente ativar um Card de Magia/Armadilha ou seus efeitos (Efeito Rápido): você pode oferecer como Tributo 1 outro monstro de Nível/Classe/Link 2; negue esse efeito e, depois, se você ofereceu como Tributo um monstro de Classe/Link 2 para ativar este efeito, você pode destruir esse card. \r\nVocê só pode usar este efeito de "Cenoura Spright" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Destruir essa card?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2311603,'Overdrive','Um veículo blindado todo-o-terreno, armado com uma metrelhadora de artilharia pesada.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2314238,'Ataque da Magia Negra','Se você controlar "Mago Negro": destrua todas as Magias e Armadilhas que seu oponente controla.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2316186,'Princesa Curran',replace(replace('Este card não pode ser Invocado por Invocação-Normal ou Baixado. \r\nEste card não pode ser Invocado por Invocação-Especial, exceto com "Julgamento das Princesas". \r\nDurante sua Fase de Apoio, cause 600 de dano aos PV do oponente para cada monstro que ele controla.','\r',char(13)),'\n',char(10)),'Causar dano aos PV','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2322421,'Guerreiro da Estrada',replace(replace('"Sincron da Estrada" + 2 ou mais monstros não-Reguladores	\r\nUma vez por turno: você pode Invocar por Invocação-Especial 1 monstro do Tipo Guerreiro ou Máquina de Nível 2 ou menos do seu Deck.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2326738,'Des Lacooda',replace(replace('Uma vez por turno: você pode colocar este card com a face para baixo em Posição de Defesa. \r\nSe este card for Invocado por Invocação-Virar: compre 1 card.','\r',char(13)),'\n',char(10)),'Mudar para Posição de Defesa com a face para baixo','Comprar 1 card','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2333365,'Tyr dos Campeões Nórdicos',replace(replace('Os monstros do seu oponente não podem escolher monstros "Nórdic" como alvo de ataques, exceto "Tyr dos Campeões Nórdicos". \r\nSe não houver nenhum outro monstro "Nórdic" no campo, destrua este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2333466,'Gandora-G, o Dragão da Destruição',replace(replace('Ganha 300 de ATK para cada card banido. \r\nVocê só pode usar cada um dos seguintes efeitos de "Gandora-G, o Dragão da Destruição" uma vez por turno. \r\nSe você controlar "Sarcófago Brilhante": você pode Invocar este card por Invocação-Especial da sua mão. \r\nVocê pode pagar metade dos seus PV; destrua tantos outros cards no campo quanto possível e, se isso acontecer, bana-os e, depois, Invoque por Invocação-Especial do seu Deck 1 monstro de Nível 7 ou menos que mencione "Sarcófago Brilhante" e aumente o Nível dele pelo número de cards destruídos por este efeito.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial da mão','Destruir 1 card','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2339825,'T.G. Encerrar',replace(replace('Quando um Card de Magia/Armadilha, ou efeito de monstro, for ativado enquanto você controlar um monstro Máquina "T.G.": negue a ativação e, se isso acontecer, destrua esse card. \r\nSe um ou mais Monstros Sincro forem banidos enquanto este card estiver no seu Cemitério: você pode Baixar este card, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar 1 efeito de "T.G. Encerrar" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2344618,'Mascarada Luzlunar',replace(replace('Durante sua Fase Principal, se este card foi ativado neste turno: você pode enviar 1 monstro "Luzlunar" do seu Deck para o Cemitério. \r\nSe você Invocar um monstro "Luzlunar" por Invocação-Fusão: você pode adicionar 1 "Polimerização" do seu Cemitério ou banimento à sua mão e, depois, você pode descartar 1 card e, se isso acontecer, uma vez, se você Invocar um monstro "Luzlunar" por Invocação-Fusão neste turno, você também pode banir monstros do seu Cemitério como matéria. \r\nVocê só pode usar cada efeito de "Mascarada Luzlunar" uma vez por turno.','\r',char(13)),'\n',char(10)),'Enviar para o Cemitério','Adicionar à mão','Descartar 1 card?','O efeito de "Mascarada Luzlunar" está sendo aplicado.','','','','','','','','','','','','');
INSERT INTO texts VALUES(2347477,'Micro Codificador',replace(replace('Se um monstro Ciberso que você controla seria usado como Matéria Link para um monstro "Codificar Transmissor", este card na sua mão também pode ser usado como matéria. \r\nSe este card for enviado da mão ou do campo para o Cemitério como matéria para a Invocação-Link de um monstro "Codificar Transmissor": você pode adicionar 1 Magia/Armadilha "Cinet" do seu Deck à sua mão, ou, se este card no campo foi usado como matéria, em vez disso, você pode adicionar 1 monstro Ciberso de Nível 4. \r\nVocê só pode usar cada efeito de "Micro Codificador" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Enviar do campo para o Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2347656,'Fascinante Labrinto do Castelo Prateado',replace(replace('Seu oponente não pode ativar efeitos de monstro em resposta à ativação dos seus Cards de Armadilha Normal. \r\nVocê só pode usar cada um dos seguintes efeitos de "Fascinante Labrinto do Castelo Prateado" uma vez por turno. \r\nVocê pode escolher 1 Armadilha Normal no seu Cemitério; Baixe-a no seu campo, mas ela não pode ser ativada a não ser que você controle um monstro Demônio. \r\nSe um ou mais outros monstros deixarem o campo pelo efeito de uma Armadilha Normal sua (exceto durante a Etapa de Dano): você pode destruir 1 card na mão do seu oponente (aleatório) ou no campo dele.','\r',char(13)),'\n',char(10)),'','Escolha 1 card na mão ou no campo do seu oponente para destruir','O efeito de "Fascinante Labrinto do Castelo Prateado" está sendo aplicado.','Escolha aleatoriamente 1 card na mão do seu oponente para destruir','Escolha 1 card que o seu oponente controla para destruir','','','','','','','','','','','');
INSERT INTO texts VALUES(2347657,'Fascinante Labrinto do Castelo Prateado',replace(replace('Seu oponente não pode ativar efeitos de monstro em resposta à ativação dos seus Cards de Armadilha Normal. \r\nVocê só pode usar cada um dos seguintes efeitos de "Fascinante Labrinto do Castelo Prateado" uma vez por turno. \r\nVocê pode escolher 1 Armadilha Normal no seu Cemitério; Baixe-a no seu campo, mas ela não pode ser ativada a não ser que você controle um monstro Demônio. \r\nSe um ou mais outros monstros deixarem o campo pelo efeito de uma Armadilha Normal sua (exceto durante a Etapa de Dano): você pode destruir 1 card na mão do seu oponente (aleatório) ou no campo dele.','\r',char(13)),'\n',char(10)),'','Escolha 1 card na mão ou no campo do seu oponente para destruir','O efeito de "Fascinante Labrinto do Castelo Prateado" está sendo aplicado.','Escolha aleatoriamente 1 card na mão do seu oponente para destruir','Escolha 1 card que o seu oponente controla para destruir','','','','','','','','','','','');
INSERT INTO texts VALUES(2347658,'Fascinante Labrinto do Castelo Prateado',replace(replace('Seu oponente não pode ativar efeitos de monstro em resposta à ativação dos seus Cards de Armadilha Normal. \r\nVocê só pode usar cada um dos seguintes efeitos de "Fascinante Labrinto do Castelo Prateado" uma vez por turno. \r\nVocê pode escolher 1 Armadilha Normal no seu Cemitério; Baixe-a no seu campo, mas ela não pode ser ativada a não ser que você controle um monstro Demônio. \r\nSe um ou mais outros monstros deixarem o campo pelo efeito de uma Armadilha Normal sua (exceto durante a Etapa de Dano): você pode destruir 1 card na mão do seu oponente (aleatório) ou no campo dele.','\r',char(13)),'\n',char(10)),'','Escolha 1 card na mão ou no campo do seu oponente para destruir','O efeito de "Fascinante Labrinto do Castelo Prateado" está sendo aplicado.','Escolha aleatoriamente 1 card na mão do seu oponente para destruir','Escolha 1 card que o seu oponente controla para destruir','','','','','','','','','','','');
INSERT INTO texts VALUES(2356994,'Grandioso Nariz Comprido',replace(replace('Este card não pode ser Invocado por Invocação-Especial. \r\nEste card é devolvido para a mão do seu dono durante a End Phase do turno em que é Invocado, por Invocação-Normal, ou é virado com a face para cima. \r\nSe este card inflige dano de batalha aos Life Points do seu adversário, ele salta a Battle Phase do seu próximo turno.','\r',char(13)),'\n',char(10)),'Retornar à mão','Pular a Battle Phase','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2359348,'Área de Pêndulo','Se todos os monstros que você controla forem Monstros Pêndulo (mín. 1): escolha 2 cards nas suas Zonas de Pêndulo; destrua os dois cards e, se isso acontecer, nenhum duelista pode Invocar por Invocação-Especial pelo resto deste turno, exceto por Invocação-Pêndulo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2362787,'Luz da Redenção','Pague 800 Pontos de Vida e, depois, escolha 1 dos seus monstros de LUZ banidos; adicione o alvo à sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2364438,'Retorno dos Mayakashi',replace(replace('Pegue 1 card "Mayakashi" do seu Deck, exceto "Retorno dos Mayakashi" e adicione-o à sua mão ou envie-o para o Cemitério. \r\nVocê só pode ativar 1 "Retorno dos Mayakashi" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2368215,'Ator do Abismo - Hiperdiretor',replace(replace('1 Monstro Pêndulo "Ator do Abismo"	\r\nVocê pode escolher 1 card na sua Zona de Pêndulo; Invoque-o por Invocação-Especial e, depois, coloque 1 Monstro Pêndulo "Ator do Abismo" com um nome diferente, do seu Deck ou com a face para cima no Deck Adicional, em uma Zona de Pêndulo sua e, além disso, você não pode Invocar monstros por Invocação-Normal ou Especial pelo resto deste turno, exceto monstros "Ator do Abismo". \r\nVocê só pode usar este efeito de "Ator do Abismo - Hiperdiretor" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2370081,'Concha de Aço','Um monstro de ÁGUA equipado com este card tem seu ATK aumentado em 400 pontos e sua DEF reduzida em 200 pontos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2371506,'Reflexo Xyz','Quando um Card de Magia, Card de Armadilha ou efeito de monstro for ativado e escolher como alvo um ou mais Monstros Xyz com a face para cima no campo: negue a ativação e, se isso acontecer, destrua-o e, depois, cause 800 de dano ao seu oponente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2372506,'Cartolas Mágicas do Caos',replace(replace('Quando seu oponente ativar um efeito de monstro, ou um Card de Magia/Armadilha Normal: selecione 3 Magias/Armadilhas com nomes diferentes do seu Deck e 1 monstro na sua Zona de Monstros Principal que mencione "Ritual da Luz e das Trevas". \r\nInvoque as Magias/Armadilhas por Invocação-Especial como Monstros Normais (Mago/TREVAS/Nível 8/ATK 0/DEF 0) com a face para baixo em Posição de Defesa (seus nomes se tornam "Cartolas Mágicas do Caos" mesmo enquanto estiverem com a face para baixo), Baixe o monstro selecionado se ele estiver com a face para cima e embaralhe-os no campo. \r\nEntão, o efeito ativado do seu oponente se torna "Destrua 1 monstro que seu oponente controla com a face para baixo em Posição de Defesa".','\r',char(13)),'\n',char(10)),'Ativar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2376209,'Paleozoico Eldonia',replace(replace('Escolha 1 monstro com a face para cima no campo; ele ganha 500 de ATK/DEF até o final deste turno. \r\nUma vez por Corrente, quando um Card de Armadilha for ativado enquanto este card estiver no seu Cemitério: você pode Invocar este card por Invocação-Especial como um Monstro Normal (Aqua/ÁGUA/Nível 2/ATK 1200/DEF 0).	\r\n(Este card NÃO é considerado como uma Armadilha.) \r\nSe Invocado desta forma, este card não é afetado por efeitos de monstro e, além disso, bana-o quando ele deixar o campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2377034,'Ouriço de Neoflamvell',replace(replace('Se este card for destruído em batalha: escolha 1 card no Cemitério do seu oponente; bana-o. \r\nSe este card no campo for destruído por um efeito de card: escolha 1 monstro de FOGO com 200 ou menos de DEF no seu Cemitério, exceto "Ouriço de Neoflamvell"; adicione o alvo à sua mão.','\r',char(13)),'\n',char(10)),'Banir','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2390019,'Ojamassimilação',replace(replace('Revele 1 Monstro de Fusão Máquina de LUZ do seu Deck Adicional e bana qualquer número de monstros "Ojama" da sua mão, com a face para cima no seu campo e/ou do seu Cemitério; Invoque por Invocação-Especial, da sua mão, do Deck e/ou do Cemitério, Matérias de Fusão com nomes diferentes cujos nomes estejam especificamente listados no card que você revelou, igual ao número de monstros banidos para ativar este efeito. \r\nVocê pode banir este card do seu Cemitério e, depois, escolher 3 dos seus monstros "Ojama" banidos; embaralhe-os no Deck e, depois, compre 1 card.','\r',char(13)),'\n',char(10)),'Continuar selecionando monstros para banir?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2396042,'Cavalaria de Aço de Dinon',replace(replace('Escala de Pêndulo = 5\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nNo começo da Etapa de Dano, se este card batalhar um Monstro Pêndulo: o ATK e DEF deste card se tornam metade do seu ATK e DEF atuais até o final da Etapa de Dano.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2403771,'Dragão Ferramenteiro',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nUma vez por turno: você pode revelar 3 Magias de Equipamento do seu Deck e, depois, seu oponente adiciona aleatoriamente 1 dessas à sua mão e embaralhe os outros cards no Deck. \r\nSe este card seria destruído enquanto equipado com uma ou mais Magias de Equipamento, em vez disso, você pode enviar 1 desses cards para o Cemitério.','\r',char(13)),'\n',char(10)),'Escolha 1 Card de Equipamento para adicionar à sua mão','Usar o efeito de "Dragão Ferramenteiro" em vez de ser destruído?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2405631,'Guoglim, a Lança dos Ghoti',replace(replace('1 Regulador Peixe + 1+ monstros não-Reguladores	\r\nNo começo da Etapa de Dano, se este card batalhar um monstro do oponente: você pode banir o monstro do oponente. \r\nDurante a Fase de Apoio do seu oponente: você pode banir este card e, depois, se os monstros usados como matéria para a Invocação-Sincro deste card estiverem todos no seu Cemitério, você pode Invocar todos eles por Invocação-Especial, mas bana-os quando eles deixarem o campo. \r\nVocê só pode usar cada efeito de "Guoglim, a Lança dos Ghoti" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Invocar por Invocação Especial o monstro Matéria Sincro?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2407147,'Criada do Vulcão Laval','Quando este card for enviado para o Cemitério, se você tiver um monstro "Laval" no seu Cemitério que não seja "Criada do Vulcão Laval": você pode enviar 1 monstro "Laval" do seu Deck para o seu Cemitério.','Enviar para o Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2407234,'Número 69: Símbolo Heráldico',replace(replace('3 monstros de Nível 4	\r\nSe este card for Invocado por Invocação-Especial: negue os efeitos de todos os outros Monstros Xyz atualmente no campo. \r\nVocê pode escolher 1 outro Monstro Xyz com a face para cima no campo; até a Fase Final, o nome deste card se torna o nome original desse monstro e, além disso, substitua este efeito pelos efeitos originais desse monstro. \r\nVocê só pode usar este efeito de "Número 69: Símbolo Heráldico" uma vez por turno.','\r',char(13)),'\n',char(10)),'Negar o efeito','Obter o efeito','Terminar o efeito copiado','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2411269,'Dragão Agave',replace(replace('2+ monstros, exceto Fichas	\r\nSe este card for Invocado por Invocação-Link: você pode aplicar esses efeitos em sequência, dependendo dos Tipos de monstros nos Cemitérios (ignore os que não se aplicam). \r\nVocê só pode usar este efeito de "Dragão Agave" uma vez por turno.\r\n● Cause 100 de dano ao seu oponente para cada Dragão.\r\n● Este card ganha 200 de ATK para cada Dinossauro.\r\n● Todos os monstros que seu oponente controla atualmente perdem 300 de ATK para cada Serpente Marinha.\r\n● Você ganha 400 PV para cada Wyrm.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2414168,'Resistor de Interrupção',replace(replace('Quando você sofrer dano de batalha: você pode Invocar este card por Invocação-Especial da sua mão e, se isso acontecer, ele ganha ATK igual ao dano que você sofreu. \r\nUma vez por turno, durante o cálculo de dano, quando outro monstro em Posição de Defesa que você controla for atacado por um monstro do oponente (Efeito Rápido): você pode ativar este efeito; durante este cálculo de dano, a DEF do seu monstro que foi atacado se torna igual à DEF deste card e, além disso, ele não pode ser destruído nessa batalha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2419596,'Número 101: ARK Honra Silenciosa - Asilo da Alma',replace(replace('2 monstros de Nível 4	\r\nVocê pode desassociar 1 matéria deste card, então ative 1 desses efeitos;\r\n● Escolha 1 monstro de Nível 4 no seu Cemitério, exceto a matéria desassociada, e adicione 1 monstro de Nível 4 com o mesmo Tipo e Atributo, mas com nome diferente, do seu Deck à sua mão.\r\n● Escolha 1 monstro que seu oponente controla; associe-o neste card.	\r\nVocê só pode usar este efeito de "Número 101: ARK Honra Silenciosa - Asilo da Alma" uma vez por turno.\r\nSe este card seria destruido, em vez disso você pode desassociar 1 matéria deste card.','\r',char(13)),'\n',char(10)),'Ativar','Adicionar à mão','Como Matéria Xyz','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2419597,'Número 101: ARK Honra Silenciosa - Asilo da Alma',replace(replace('2 monstros de Nível 4	\r\nVocê pode desassociar 1 matéria deste card, então ative 1 desses efeitos;\r\n● Escolha 1 monstro de Nível 4 no seu Cemitério, exceto a matéria desassociada, e adicione 1 monstro de Nível 4 com o mesmo Tipo e Atributo, mas com nome diferente, do seu Deck à sua mão.\r\n● Escolha 1 monstro que seu oponente controla; associe-o neste card.	\r\nVocê só pode usar este efeito de "Número 101: ARK Honra Silenciosa - Asilo da Alma" uma vez por turno.\r\nSe este card seria destruido, em vez disso você pode desassociar 1 matéria deste card.','\r',char(13)),'\n',char(10)),'Ativar','Adicionar à mão','Como Matéria Xyz','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2420921,'Shire, o Espírito Luminoso',replace(replace('Este card ganha 300 de ATK para cada monstro "Luminoso(a)" com um nome diferente no seu Cemitério. \r\nDurante cada uma das suas Fases Finais: envie os 2 cards do topo do seu Deck para o Cemitério.','\r',char(13)),'\n',char(10)),'Envie 2 cards do seu Deck para o Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2434862,'Ascensão Cúbica',replace(replace('Quando um monstro do oponente declarar um ataque: Invoque por Invocação-Especial 1 "Vijam, a Semente Cúbica" do seu Deck e, se isso acontecer, mude o alvo do ataque para ele e realize o cálculo de dano. \r\nSe os PV do seu oponente forem pelo menos 2000 a mais que os seus: você pode banir este card do seu Cemitério; Invoque por Invocação-Especial 1 "Vijam, a Semente Cúbica" da sua mão, do Deck ou do Cemitério e, depois, se apenas seu oponente controlava um monstro quando este efeito foi ativado, você pode Invocar por Invocação-Especial até 2 outros "Vijam, a Semente Cúbica". \r\nVocê só pode usar este efeito de "Ascensão Cúbica" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial e mudar o alvo do ataque','Invocação Especial','Invocar outro monstro por Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2460565,'Capitão Saqueador',replace(replace('Monstros que seu oponente controla não podem escolher monstros Guerreiro como alvo de ataque, exceto este. \r\nQuando este card for Invocado por Invocação-Normal: você pode Invocar por Invocação-Especial 1 monstro de Nível 4 ou menos da sua mão.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2461031,'Joaninha Inzektor',replace(replace('Uma vez por turno: você pode equipar 1 monstro "Inzektor" da sua mão ou do Cemitério a este card. \r\nEnquanto este card estiver equipado a um monstro, o Nível desse monstro aumenta em 2 e, além disso, ele ganha ATK/DEF igual ao ATK/DEF deste card. \r\nEnquanto este card estiver equipado a um monstro: você pode enviar este Card de Equipamento para o Cemitério e, depois, escolha 1 monstro com a face para cima que você controla; aumente o Nível do alvo em 1 ou 2.','\r',char(13)),'\n',char(10)),'Equipar','Aumentar o Nível','Aumentar em 1 Nível','Aumentar em 2 Níveis','','','','','','','','','','','','');
INSERT INTO texts VALUES(2463794,'Réquiem do Criademônio',replace(replace('1 monstro Demônio de LUZ	\r\nVocê só pode Invocar um ou mais "Réquiem do Criademônio" por Invocação-Especial uma vez por turno. \r\nDurante a Fase Principal (Efeito Rápido): você pode oferecer este card como Tributo; Invoque por Invocação-Especial 1 monstro "Criademônio" da sua mão ou do Deck. \r\nVocê pode escolher 1 monstro Demônio de LUZ que não seja Link que você controla; equipe este card do seu campo ou Cemitério a esse monstro que você controla como uma Magia de Equipamento que concede a ele 600 de ATK. \r\nVocê só pode usar este efeito de "Réquiem do Criademônio" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Efeito de Equipamento','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2468169,'Meisei, Mestre dos Selos','Uma das poucas pessoas que tem um bom controle sobre Talismãs. A sua história é um mistério.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2483611,'Omotics da Água','Transforma a água que transborda de uma jarra em dragões atacantes.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2501624,'Pequena Maga Negra, a Aprendiz de Mago',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) ao descartar 1 card e, se isso acontecer, o nome deste card se torna "Pequena Maga Negra". \r\nVocê só pode Invocar "Pequena Maga Negra, a Aprendiz de Mago" por Invocação-Especial uma vez por turno desta forma. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 "Sarcófago Brilhante" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Pequena Maga Negra, a Aprendiz de Mago" uma vez por turno. \r\nGanha 300 de ATK para cada monstro que mencione "Sarcófago Brilhante" nos Cemitérios.','\r',char(13)),'\n',char(10)),'Invocação Especial','Adicionar à mão','Aumentar ATK','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2504891,'Cavaleiro Caveira','"Sabedoria Corrompida" + "Cérebro Ancião"','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2507443,'Luz Prima',replace(replace('Ative 1 desses efeitos;\r\n● Ofereça como Tributo 1 monstro Guerreiro de TERRA e, se isso acontecer, Invoque por Invocação-Especial 1 monstro Guerreiro de LUZ da sua mão ou do Deck.\r\n● Durante a Fase Principal: imediatamente depois que este efeito resolver, Invoque por Invocação-Normal 1 monstro Guerreiro da sua mão.	\r\nDurante sua Fase Principal: você pode banir este card do seu Cemitério; adicione 1 monstro "Ciber" Guerreiro ou Fada do seu Deck à sua mão. \r\nVocê só pode usar 1 efeito de "Luz Prima" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar','Adicionar à mão','Oferecer como Tributo e Invocar por Invocação Especial','Invocação Normal','','','','','','','','','','','','');
INSERT INTO texts VALUES(2511717,'Seis Samurai Lendários - Kageki',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode Invocar por Invocação-Especial 1 monstro "Seis Samurai" de Nível 4 ou menos da sua mão. \r\nEnquanto você controlar um monstro "Seis Samurai" com um nome diferente, este card ganha 1500 de ATK.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2519690,'Galopante Celeste Gaia, o Matador de Dragões',replace(replace('1 monstro "Gaia, o Cavaleiro Impetuoso" ou "Gaia, o Cavaleiro do Vento Negro" + 1 monstro do Tipo Dragão	\r\nO nome deste card se torna "Gaia, o Matador de Dragões" enquanto ele estiver no campo. \r\nSe este card for Invocado por Invocação-Especial: você pode adicionar 1 "Ataque da Lança em Espiral" do seu Deck ou Cemitério à sua mão. \r\nQuando este card declarar um ataque contra um monstro do oponente: você pode mudar a posição de batalha desse monstro do oponente.','\r',char(13)),'\n',char(10)),'Adicione 1 card "Ataque da Lança em Espiral" à sua mão','Mudar a posição de batalha de um monstro do oponente','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2521011,'Irmandade do Punho de Fogo - Andorinha',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) ao enviar 3 Cards de Magia/Armadilha "Formação de Fogo" com a face para cima que você controla para o Cemitério. \r\nQuando este card for Invocado por Invocação-Normal ou Especial: você pode Baixar 1 Card de Armadilha "Formação de Fogo" diretamente do seu Deck. \r\nVocê só pode usar este efeito de "Irmandade do Punho de Fogo - Andorinha" uma vez por turno. \r\nOs monstros do Tipo Besta-Guerreira com a face para cima que você controla não podem ser alvo dos efeitos de card do seu oponente.','\r',char(13)),'\n',char(10)),'Baixar','Comprar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2525268,'Defensor, o Cavaleiro Mágico',replace(replace('Se este card for Invocado por Invocação-Normal: coloque 1 Marcador de Magia sobre ele (máx. 1). \r\nUma vez por turno, se um ou mais monstros Mago no campo seriam destruídos, em vez disso, você pode remover 1 Marcador de Magia do seu campo para cada um desses monstros.','\r',char(13)),'\n',char(10)),'Colocar Marcadores de Magia','Usar o efeito de "Defensor, o Cavaleiro Mágico" em vez de ser destruído?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2526224,'Avatar Altíssimo do Rei de Fogo Kirin',replace(replace('Durante a Fase Principal, se este card estiver na sua mão (Efeito Rápido): você pode destruir 1 outro monstro de FOGO na sua mão ou no campo com a face para cima e, se isso acontecer, Invoque este card por Invocação-Especial. \r\nSe este card for destruído e enviado para o Cemitério: você pode Invocar por Invocação-Especial 1 monstro "Rei(s) de Fogo" da sua mão ou do Cemitério, exceto "Avatar Altíssimo do Rei de Fogo Kirin" e, depois, você pode destruir 1 card no campo. \r\nVocê só pode usar cada efeito de "Avatar Altíssimo do Rei de Fogo Kirin" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Destruir 1 card no campo?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2530830,'Dragão da Lâmina Críptico de Olhos das Galáxias',replace(replace('3 monstros de Nível 9	\r\nVocê também pode Invocar este card por Invocação-Xyz usando um Monstro Xyz "Olhos das Galáxias" de Classe 8 que você controla como matéria. \r\n(Transfira as matérias dele para este card.) \r\nNão pode ser usado como matéria para uma Invocação-Xyz. \r\nUma vez por turno: você pode desassociar 1 matéria deste card e, depois, escolha 1 card no campo; destrua-o. \r\nSe este card Invocado por Invocação-Xyz que você controla, for destruído em batalha com um monstro atacante do oponente, ou destruído por um efeito de card do oponente, e enviado para o seu Cemitério: você pode escolher 1 "Dragão Críptico de Olhos das Galáxias" no seu Cemitério; Invoque-o por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Xyz usando o Monstro Xyz "Olhos das Galáxias" como matéria?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2542230,'Casulo Vermelho',replace(replace('Escolha 1 Monstro Sincro do Tipo Dragão que você controla; equipe este card no alvo. \r\nEnquanto ele estiver batalhando um monstro do oponente, até o final da Etapa de Dano, negue os efeitos de todos os monstros com a face para cima que seu oponente controla. \r\nDurante a Fase Final, se este card estiver no Cemitério porque foi enviado para lá neste turno: você pode escolher 1 "Dragão Vermelho Arquidemônio" no seu Cemitério; Invoque-o por Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2547033,'Rocha Assombrada Altergeist',replace(replace('Se este card foi Baixado pelo efeito de um card "Altergeist", você pode ativá-lo no turno em que foi Baixado. \r\nQuando este card for ativado: envie 1 monstro "Altergeist" da sua mão para o Cemitério. \r\nQuando seu oponente ativar um Card de Armadilha (exceto durante a Etapa de Dano): você pode enviar 1 monstro "Altergeist" da sua mão para o Cemitério; negue esse efeito e, se isso acontecer, destrua esse card. \r\nVocê só pode usar cada efeito de "Rocha Assombrada Altergeist" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Ativar aplicando o efeito de "Altergeist".','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2561846,'Célula de Corrupção "A"','Coloque 1 Marcador-A em 1 monstro com a face para cima no lado do campo do oponente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2563463,'Ginete de Grifo Errante',replace(replace('Durante a Fase Principal, se você não controlar nenhum monstro, ou controlar uma "Ficha de Aventura" (Efeito Rápido): você pode Invocar este card por Invocação-Especial da sua mão. \r\nQuando um card ou efeito for ativado enquanto você controlar uma "Ficha de Aventura" (Efeito Rápido): você pode embaralhar este card no Deck e, se isso acontecer, negue a ativação e, se isso acontecer, destrua esse card. \r\nVocê só pode usar cada efeito de "Ginete de Grifo Errante" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2572890,'Tempestade Majespectro','Quando um ou mais monstros seriam Invocados por Invocação-Especial ou um efeito de monstro for ativado: ofereça como Tributo 1 monstro Mago de VENTO; negue a Invocação ou ativação e, se isso acontecer, destrua esse card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2584136,'Choquetopus',replace(replace('Quando este card for destruído em uma batalha com um monstro do oponente e enviado para o Cemitério: você pode equipar este card ao monstro do oponente. \r\nO ATK desse monstro se torna 0 e, além disso, ele não pode mudar sua posição de batalha.','\r',char(13)),'\n',char(10)),'Equipar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2602411,'Notável Espada da Destruição do Mago',replace(replace('Você pode escolher 1 "Blader Notável" que você controla; equipe este monstro da sua mão ou do seu lado do campo no alvo. \r\nEnquanto este card estiver equipado a um monstro, os monstros no Cemitério do seu oponente não podem ativar seus efeitos. \r\nVocê pode enviar este Card de Equipamento para o Cemitério e, depois, escolher 1 monstro "Espada da Destruição" no seu Cemitério, exceto "Notável Espada da Destruição do Mago"; adicione-o à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2606417,'Carixa da Reversão',replace(replace('Uma vez por turno, durante a Fase de Apoio: role um dado e coloque marcadores neste card igual ao resultado (máx. 6).\r\nUma vez por batalha, se um monstro do oponente ataca, durante o cálculo de dano, OU quando um efeito de monstro é ativado no campo do seu oponente: você pode remover 1 marcador deste card, então escolha 1 daqueles monstros; jogue uma moeda. \r\nSe você acertar, você pode Invocar por Invocação-Especial 1 monstro que mencione "Mago do Tempo Sombrio" do seu Deck, e se fizer, até o final deste turno, altere o ATK do monstro escolhido para 0, seus efeitos também são negados.','\r',char(13)),'\n',char(10)),'Colocar um marcador','Jogar uma moeda','Selecione o número de marcadores a colocar','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2609443,'Cronomalia Vimana',replace(replace('2 monstros de Nível 5	\r\nUma vez por turno (Efeito Rápido): você pode escolher 1 monstro com a face para cima no campo e 1 Monstro Xyz ou monstro "Cronomalia" no seu Cemitério; esse monstro no campo ganha metade do ATK desse monstro no Cemitério (até o final deste turno) e, depois, associe esse monstro do Cemitério a este card como matéria. \r\nUma vez por turno, quando seu oponente ativar um efeito de monstro (Efeito Rápido): você pode desassociar 2 matérias deste card; negue a ativação.','\r',char(13)),'\n',char(10)),'Aumentar ATK e repor Matérias','Negar a ativação de um monstro do oponente','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2618045,'Encarregado de Fóton',replace(replace('Uma vez por turno: você pode fazer com que o ATK deste card se torne o dobro do seu ATK original, até sua próxima Fase de Apoio. \r\nEste card não pode atacar no turno em que você ativar este efeito.','\r',char(13)),'\n',char(10)),'Alterar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2618725,'Selandea, o Sócio da GMX',replace(replace('Você pode revelar este card na sua mão; Invoque por Invocação-Especial 1 monstro "GMX" ou 1 monstro Dinossauro da sua mão e, além disso, você só pode atacar diretamente com monstros "GMX" pelo resto deste turno. \r\nSe este card for Invocado por Invocação-Especial por um efeito de monstro: você pode Invocar por Invocação-Especial 1 monstro "GMX" ou Dinossauro de Nível 4 ou menos da sua mão, do Cemitério ou do banimento em Posição de Defesa. \r\nVocê só pode usar cada efeito de "Selandea, o Sócio da GMX" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial da mão','Invocar por Invocação Especial da mão, do Cemitério ou dos banimento','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2619149,'Besta Gladiadora Samnite',replace(replace('Quando este card, que foi Invocado por Invocação-Especial pelo efeito de um monstro "Besta Gladiadora", destruir um monstro do oponente em batalha e enviá-lo para o Cemitério: você pode adicionar 1 card "Besta Gladiadora" do seu Deck à sua mão. \r\nNo final da Fase de Batalha, se este card batalhou: você pode embaralhá-lo no Deck; Invoque por Invocação-Especial 1 monstro "Besta Gladiadora" do seu Deck, exceto "Besta Gladiadora Samnite".','\r',char(13)),'\n',char(10)),'Procurar no Deck','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2625939,'Código Carretel',replace(replace('Quando um monstro do oponente declarar um ataque direto, enquanto você tiver 3 ou mais monstros Ciberso no seu Cemitério: negue o ataque e, depois, você pode Invocar por Invocação-Especial até 3 "Fichas de Carretel" (Ciberso/LUZ/Nível 1/ATK 0/DEF 0) em Posição de Defesa. \r\nEssas Fichas não podem ser oferecidas como Tributo para uma Invocação-Tributo.','\r',char(13)),'\n',char(10)),'Invocar uma Ficha por Invocação Especial?','Escolha a quantidade de Fichas a Invocar por Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2625940,'Ficha de Carretel','Invocada por Invocação-Especial com o efeito "Código Carretel". Esta Ficha não pode ser oferecida como Tributo para uma Invocação-Tributo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2645637,'Yuki-Onna, a Mayakashi do Zero Absoluto',replace(replace('2+ monstros Zumbi	\r\nVocê só pode controlar 1 "Yuki-Onna, a Mayakashi do Zero Absoluto". \r\nNegue quaisquer efeitos ativados dos monstros banidos do seu oponente. \r\nSe um monstro for Invocado por Invocação-Especial do Cemitério, ou um efeito de monstro for ativado no Cemitério (exceto durante a Etapa de Dano): você pode escolher 1 outro monstro com a face para cima no campo; mude o ATK dele para 0 e, se isso acontecer, negue seus efeitos. \r\nVocê pode usar este efeito de "Yuki-Onna, a Mayakashi do Zero Absoluto" até duas vezes por turno.','\r',char(13)),'\n',char(10)),'ATK torna-se 0','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2648201,'ZW - Armadura Sleipnir',replace(replace('Você pode escolher 1 monstro "Utopia" que você controla; equipe este monstro da sua mão ou do seu lado do campo ao alvo. \r\nEle ganha 1000 de ATK. \r\nQuando este card que você controla for enviado para o seu Cemitério porque o monstro equipado foi destruído por um card do seu oponente (em batalha ou por um efeito de card): você pode escolher 1 monstro "Utopia" no seu Cemitério; Invoque o alvo por Invocação-Especial. \r\nVocê só pode controlar 1 "ZW - Armadura Sleipnir".','\r',char(13)),'\n',char(10)),'Equipar','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2656842,'Buggy Batedor Bezoudado',replace(replace('Você não pode Invocar monstros por Invocação-Especial, exceto monstros Inseto. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode Invocar por Invocação-Especial 1 "Buggy Batedor Bezoudado" da sua mão, do Deck ou do Cemitério. \r\nVocê só pode usar este efeito de "Buggy Batedor Bezoudado" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2665273,'Jormungandr, Chefe Generaidor da Eternidade',replace(replace('2+ monstros de Nível 9	\r\nVocê só pode controlar 1 "Jormungandr, Chefe Generaidor da Eternidade". \r\nO ATK/DEF originais deste card se tornam 1000 x seu número de matérias. \r\n(Efeito Rápido): você pode desassociar 1 matéria deste card; cada duelista compra 1 card e, depois, cada duelista que comprou associa 1 card da mão ou do campo dele a este card. \r\nVocê só pode usar este efeito de "Jormungandr, Chefe Generaidor da Eternidade" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2671330,'Hiper Cabeça de Martelo','No final da Etapa de Dano, se um monstro do oponente que batalhou este card não for destruído: devolva esse monstro do oponente para a mão.','Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2674965,'Argostars - Estádio da Casa',replace(replace('Uma vez por turno: você pode pagar 1000 PV; adicione 1 card "Argostars" do seu Cemitério ou banimento à sua mão. \r\nSempre que uma Armadilha Contínua na Zona de Magias & Armadilhas for Invocada por Invocação-Especial no seu campo, cause 500 de dano ao seu oponente. \r\nUma vez por Corrente, se uma Armadilha Contínua ativar seu efeito na sua Zona de Monstros, enquanto você tiver um monstro "Argostars" banido: você pode escolher 1 card com a face para cima que seu oponente controla; negue seus efeitos até o final deste turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Negar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2694423,'Verme Medusa',replace(replace('Você pode virar este card para Posição de Defesa com a face para baixo uma vez por turno durante a sua Main Phase. \r\nQuando este card é Invocado, por Invocação-Virar, com sucesso, destrua 1 monstro no Campo do seu adversário.','\r',char(13)),'\n',char(10)),'Mudar para Posição de Defesa com a face para baixo','Destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2725599,'ÁS-Resgate Árbitro',replace(replace('2+ monstros de FOGO	\r\nVocê só pode Invocar um ou mais "ÁS-Resgate Árbitro" por Invocação-Especial uma vez por turno. \r\nSe este card for Invocado por Invocação-Link: você pode adicionar 1 "ÁS-Resgate Hidrante" ou "QG ÁS-Resgate" do seu Deck ou Cemitério à sua mão. \r\nSe você ativar um Card de Magia Rápida "ÁS-Resgate" ou um Card de Armadilha Normal "ÁS-Resgate" (exceto durante a Etapa de Dano): você pode escolher 1 card que seu oponente controla; destrua-o. \r\nVocê só pode usar este efeito de "ÁS-Resgate Árbitro" duas vezes por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2729285,'Fofanimal Gato',replace(replace('Se este card for enviado para o Cemitério como uma Matéria de Fusão para uma Invocação-Fusão: você pode escolher 1 "Polimerização" no seu Cemitério; adicione-o à sua mão. \r\nVocê só pode usar este efeito de "Fofanimal Gato" uma vez por turno.','\r',char(13)),'\n',char(10)),'Procurar no Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2729965,'Tornado Espacial',replace(replace('Retorne até 2 cards no campo para a mão, então cada jogar coloca cards das suas mãos no fundo do Deck em qualquer ordem igual ao número de cards retornado de suas mãos.\r\nVocê só pode ativar 1 "Tornado Espacial" por turno.','\r',char(13)),'\n',char(10)),'Ativar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2732323,'Dragão Chamariz','Se este card for escolhido como alvo de um ataque: escolha 1 monstro Dragão de Nível 7 ou mais no seu Cemitério; Invoque-o por Invocação-Especial e, se isso acontecer, mude o alvo do ataque para ele e realize o cálculo de dano.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2743001,'Cristron Fênix',replace(replace('1 Monstro Sincro Regulador + 1+ Monstros Sincro não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro: você pode banir todas as Magias e Armadilhas que seu oponente controla e no Cemitério dele. \r\nSe este card Invocado por Invocação-Sincro for destruído em batalha ou por um efeito de card: você pode escolher 1 outro monstro no seu Cemitério; Invoque-o por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Banir Magias/Armadilhas no campo e no Cemitério','Invocar por Invocação Especial do Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2752099,'Xamã das Rosas',replace(replace('Você pode oferecer este card como Tributo; compre 1 card. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 monstro Planta no seu Cemitério; adicione-o à sua mão e, depois, se você adicionou um monstro Planta cujo Nível original seja 7 ou mais, você pode enviar 1 monstro Planta do seu Deck para o Cemitério. \r\nVocê só pode usar 1 efeito de "Xamã das Rosas" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Enviar novamente 1 monstro Planta do seu Deck para o Cemitério?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2759860,'Impacto Alicercinza',replace(replace('Você pode escolher 1 outro card "Alicercinza" que você controla e 1 card que seu oponente controla; destrua-os. \r\nDurante sua Fase Final: você pode adicionar 1 card "Alicercinza" do seu Deck à sua mão. \r\nVocê só pode usar 1 efeito de "Impacto Alicercinza" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Destruir 1 card','Adicione 1 card "Alicercinza" do seu Deck à sua mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2766877,'Fênix Daigusto',replace(replace('2 monstros de Nível 2	\r\nUma vez por turno: Você pode desassociar 1 Matéria Xyz deste card para escolher 1 monstro de VENTO com a face para cima que você controla; neste turno, ele pode atacar duas vezes durante cada Fase de Batalha.','\r',char(13)),'\n',char(10)),'Atacar duas vezes','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2772236,'Wattquimera',replace(replace('1 Regulador "Watt" + 1+ monstros Trovão não-Reguladores	\r\nEste card pode atacar diretamente. \r\nSe este card causar dano de batalha ao seu oponente em um ataque direto: coloque 1 card aleatório da mão do seu oponente no topo do Deck dele.','\r',char(13)),'\n',char(10)),'Retornar ao Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2772337,'Princesa Prometeica, a Doadora de Chamas',replace(replace('2+ Monstros de Efeito	\r\nVocê não pode Invocar por Invocação-Especial, exceto monstros de FOGO. \r\nVocê só pode usar cada um dos seguintes efeitos de "Princesa Prometeica, a Doadora de Chamas" uma vez por turno. \r\nDurante sua Fase Principal: você pode Invocar por Invocação-Especial 1 monstro de FOGO do seu Cemitério. \r\nSe um ou mais monstros forem Invocados por Invocação-Especial no campo do seu oponente, enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode escolher 1 monstro de FOGO que você controla e 1 monstro que seu oponente controla; destrua-os e, se isso acontecer, Invoque este card por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Ressuscitar','Destruir 1 monstro','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2772338,'Princesa Prometeica, a Doadora de Chamas',replace(replace('2+ Monstros de Efeito	\r\nVocê não pode Invocar por Invocação-Especial, exceto monstros de FOGO. \r\nVocê só pode usar cada um dos seguintes efeitos de "Princesa Prometeica, a Doadora de Chamas" uma vez por turno. \r\nDurante sua Fase Principal: você pode Invocar por Invocação-Especial 1 monstro de FOGO do seu Cemitério. \r\nSe um ou mais monstros forem Invocados por Invocação-Especial no campo do seu oponente, enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode escolher 1 monstro de FOGO que você controla e 1 monstro que seu oponente controla; destrua-os e, se isso acontecer, Invoque este card por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Ressuscitar','Destruir 1 monstro','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2779999,'Muralha de Espinhos','Quando um monstro do Tipo Planta que você controla for escolhido como alvo de um ataque: destrua todos os monstros em Posição de Ataque que seu oponente controla.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2783661,'Majestade com Azul nos Olhos',replace(replace('Envie 1 monstro "Olhos Azuis" da sua mão ou do Deck para o Cemitério e, depois, escolha 1 monstro com a face para cima no campo; ele não pode atacar enquanto estiver com a face para cima no campo. \r\nVocê só pode ativar 1 "Majestade com Azul nos Olhos" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2792265,'Servo do Catabolismo','Este monstro pode atacar os PV do oponente diretamente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2801664,'Guerreiros Antigos - Destemido Zhang De',replace(replace('Ganha 300 de ATK para cada monstro que seu oponente controla, apenas durante o seu turno. \r\nVocê só pode usar cada um dos seguintes efeitos de "Guerreiros Antigos - Destemido Zhang De" uma vez por turno.\r\n● Se você controlar 2 ou mais monstros "Guerreiros Antigos": você pode Invocar este card por Invocação-Especial da sua mão.\r\n● Se seu oponente controlar mais monstros que você: você pode ativar este efeito; este card pode realizar até 2 ataques contra monstros durante cada Fase de Batalha neste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2810642,'PSÍ-Armação Equipamento Beta',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial por um efeito de card e não pode ser Invocado por Invocação-Especial de nenhuma outra forma. \r\nQuando um monstro do oponente declarar um ataque enquanto você não controlar nenhum monstro: você pode Invocar por Invocação-Especial tanto este card da sua mão quanto 1 "PSÍ-Armação Condutor" da sua mão, Deck ou Cemitério e, se isso acontecer, destrua o monstro atacante e, depois, encerre a Fase de Batalha. \r\nDurante a Fase Final, bana os monstros com a face para cima Invocados por Invocação-Especial por este efeito.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2815176,'Zebufera, a Pagã Consagração Vaalmônica',replace(replace('1 Monstro de Efeito	\r\nNão pode ser Invocado por Invocação-Link a não ser que você tenha 3 ou mais Marcadores de Ressonância em um ou mais Cards de Monstro Demônio na sua Zona de Pêndulo. \r\nVocê só pode Invocar "Zebufera, a Pagã Consagração Vaalmônica" por Invocação-Especial uma vez por turno. \r\nSe um ou mais cards que você controla seriam destruídos em batalha ou por um efeito de card, em vez disso, você pode remover 3 Marcadores de Ressonância da sua Zona de Pêndulo. \r\nUma vez por turno do oponente (Efeito Rápido): você pode escolher 1 das suas Magias/Armadilhas Normais "Vaalmônica" que estiverem banidas ou no seu Cemitério; aplique o efeito de ativação desse card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2819435,'Pacifis, a Cidade Fantasma',replace(replace('(O nome deste card deve ser sempre considerado como "Umi".)	\r\nVocê não pode Invocar Monstros de Efeito por Invocação-Normal ou Especial no turno em que ativar quaisquer dos efeitos deste card (mesmo que este card deixe o campo). \r\nUma vez por turno, se você Invocar por Invocação-Normal ou Especial exatamente 1 Monstro Normal (e nenhum outro card): adicione 1 card "Fantasma Espiral" do seu Deck à sua mão. \r\nSe seu oponente ativar um card ou efeito (exceto durante a Etapa de Dano) e você não controlar nenhuma Ficha: você pode Invocar por Invocação-Especial 1 "Ficha de Fantasma Espiral" (Tipo Wyrm/ÁGUA/Nível 8/ATK 2000/DEF 2000).','\r',char(13)),'\n',char(10)),'Procurar no Deck','Ficha','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2819436,'Ficha de Fantasma Espiral','Invocada por Invocação-Especial com o efeito "Pacifis, a Cidade Fantasma".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2830619,'Víbora Flamejante','Uma cobra cuspidora de fogo cuja velocidade a torna um alvo difícil.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2830693,'Kuriboh Arco-Íris',replace(replace('Você só pode usar cada efeito de "Kuriboh Arco-Íris" uma vez por turno.\r\n● Quando um monstro do oponente declarar um ataque: você pode escolher esse monstro atacante; equipe este card da sua mão nesse monstro.	\r\nEle não pode atacar.\r\n● Quando um monstro do oponente declarar um ataque direto enquanto este card estiver no seu Cemitério: você pode Invocar este card por Invocação-Especial, mas bana-o quando ele deixar o campo.','\r',char(13)),'\n',char(10)),'Equipar','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2833249,'D. Tribo','Todos os monstros no seu Campo são tratados como sendo do Tipo Dragão até ao final do turno.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2834264,'Chifre de Armadura Bezoudado',replace(replace('2 monstros Inseto	\r\nVocê não pode Invocar monstros por Invocação-Especial, exceto monstros Inseto. \r\nVocê só pode usar cada um dos seguintes efeitos de "Chifre de Armadura Bezoudado" uma vez por turno. \r\nDurante sua Fase Principal, você pode: imediatamente depois que este efeito resolver, Invoque por Invocação-Normal 1 monstro Inseto. \r\nSe este card estiver no seu Cemitério: você pode banir 3 outros monstros Inseto do seu Cemitério; Invoque este card por Invocação-Especial, mas bana-o quando ele deixar o campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2843014,'Rolim Ágil',replace(replace('Quando este card for destruído em batalha e enviado ao Cemitério, envie 1 monstro do Tipo Peixe do seu Deck ao Cemitério. \r\nDepois, você pode Invocar por Invocação-Especial 1 "Rolim Ágil" do seu Deck.','\r',char(13)),'\n',char(10)),'Enviar para o Cemitério','Invocar "Rolim Ágil" por Invocação Especial?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2851070,'Fronteira de Reflexão',replace(replace('Antes do cálculo de dano, se este card estiver sendo atacado por um monstro do oponente e estava em Posição de Ataque no começo da Etapa de Dano: cause dano ao seu oponente igual ao ATK do monstro atacante. \r\nSe isso acontecer, depois do cálculo de dano: destrua este card.','\r',char(13)),'\n',char(10)),'Causar dano','Autodestruir-se','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2857636,'Cavaleira do Pesadelo Fênix',replace(replace('2 monstros com nomes diferentes	\r\nSe este card for Invocado por Invocação-Link: você pode descartar 1 card e, depois, escolha 1 Magia/Armadilha que seu oponente controla; destrua-a e, depois, se este card estava co-linkado quando este efeito foi ativado, você pode comprar 1 card. \r\nVocê só pode usar este efeito de "Cavaleira do Pesadelo Fênix" uma vez por turno. \r\nMonstros co-linkados que você controla não podem ser destruídos em batalha.','\r',char(13)),'\n',char(10)),'','Comprar 1 card?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2863439,'Reflexo Demoníaco nº 2','Uma pássaro-besta que invoca reforços usando um espelho de mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2881864,'Naglfar, Chefe Generaidor do Fogo',replace(replace('Você só pode controlar 1 "Naglfar, Chefe Generaidor do Fogo". \r\nSe um ou mais cards que você controla seriam destruídos em batalha ou por um efeito de card, em vez disso, você pode destruir 1 monstro "Generaidor" ou 1 monstro Besta-Guerreira que você controla. \r\nVocê só pode usar este efeito de "Naglfar, Chefe Generaidor do Fogo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2896663,'ZW - Alabarda Dragônica',replace(replace('2 monstros de Nível 5	\r\nNão pode atacar diretamente. \r\nUma vez por turno: você pode desassociar 1 matéria deste card; adicione 1 Magia/Armadilha "Zexal" do seu Deck à sua mão. \r\nVocê pode escolher 1 monstro "Utopia" que você controla; equipe este card que você controla a ele. \r\nEle ganha 3000 de ATK. \r\nQuando o monstro equipado destruir um monstro em batalha: você pode Invocar por Invocação-Especial no seu campo qualquer número de Cards de Monstro "ZW -" equipados a ele.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Considerar como Card de Equipamento','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2903036,'Boneca Tributo',replace(replace('Ofereça 1 monstro como Tributo; Invoque por Invocação-Especial 1 monstro de Nível 7 da sua mão que possa ser Invocado por Invocação-Normal/Baixado. \r\nEle não pode atacar neste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2906250,'Constritora','Cobra sorrateira com um corpo espesso que prende monstros inimigos e os sufoca até a morte.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2906939,'Asutrashen Trichiliocosmo',replace(replace('Você pode escolher qualquer número de cards com a face para baixo que você controla; adicione cards "Asutra" do seu Deck à sua mão com nomes diferentes de cada, exceto Magias de Campo, igual ao número daqueles cards escolhidos que ainda estão com a face para baixo, então envie aqueles cards com a face para baixo para o Cemitério.\r\nSe um ou mais cards se tornam Baixados no campo, enquanto você controla um monstro "Asutra" e um card com a face para baixo: você pode escolher 1 card no campo; retorne-o para a mão.\r\nVocê só pode usar cada um dos efeitos de "Asutrashen Trichiliocosmo" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Retornar para a mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2924048,'Depósito de Dinheiro Karakuri',replace(replace('Ative apenas se você controlar um monstro "Karakuri" com a face para cima em Posição de Defesa. \r\nNegue a ativação de um Card de Magia/Armadilha do oponente e destrua-o.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2926176,'Maldição da Realeza','Anule a ativação de um Card Magia ou de Armadilha que inclua um efeito que destrua 1 Card de Magia ou de Armadilha e destrua-o.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2930675,'Chave do Legado Mundial',replace(replace('Quando este card for ativado: você pode escolher 1 dos seus monstros "Mekk-Cavaleiro" ou cards "Legado Mundial" banidos; adicione-o à sua mão. \r\nNegue quaisquer efeitos de Armadilha do oponente que ativem na mesma coluna que um monstro "Mekk-Cavaleiro" que você controla.','\r',char(13)),'\n',char(10)),'Adicionar o card banido à sua mão?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2932235,'Terror Umbral Mil',replace(replace('(Efeito Rápido): você pode enviar este card da sua mão ou campo para o Cemitério; coloque 1 "Barian do Sétimo" da sua mão ou Deck com a face para cima na sua Zona de Campo, você também não pode Invocar por Invocação-Especial do seu Deck Adicional até o final do seu próximo turno, exceto Monstros Xyz.\r\nSe um ou mais monstros são Invocados por Invocação-Especial enquanto este card está no seu Cemitério: você pode Invocar por Invocação-Especial este card, você não recebe dano dos efeitos dos seus cards pelo resto deste turno.\r\nVocê só pode usar cada um dos efeitos de "Terror Umbral Mil" uma vez por turno.','\r',char(13)),'\n',char(10)),'Colocar na Zona do Campo','Invocação Especial','O efeito de "Terror Umbral Mil" está sendo aplicado.','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2948263,'Golem Gogogo - Forma Dourada',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nVocê deve Invocá-lo por Invocação-Especial (da sua mão) ao oferecer como Tributo 1 monstro "Gogogo" e não pode Invocá-lo por Invocação-Especial de nenhuma outra forma. \r\nO ATK deste card se torna o dobro do ATK original do monstro oferecido como Tributo. \r\nQualquer dano de batalha que seu oponente sofrer de ataques envolvendo este card são diminuídos pela metade. \r\nUma vez por turno, durante o turno de qualquer duelista, quando um efeito de monstro for ativado no lado do campo do seu oponente: este card perde exatamente 1500 de ATK e, se isso acontecer, negue esse efeito.','\r',char(13)),'\n',char(10)),'Negar o efeito','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2956282,'Barkion de Naturia',replace(replace('1 Regulador de TERRA + 1+ monstros não-Reguladores de TERRA	\r\nQuando um Card de Armadilha for ativado (Efeito Rápido): você pode banir 2 cards do seu Cemitério; negue a ativação e, se isso acontecer, destrua esse card. \r\nEste card deve estar com a face para cima no campo para ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Negue a ativação de um Card de Armadilha e a destrua','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2957055,'Dragão Maléfico com Cefaloide','Um dragão de duas cabeças com um par de mandíbulas capaz de despedaçar um inimigo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2964201,'Ryu-Ran','Um pequeno e maligno dragão abrigado num ovo aparentemente inofensivo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2971090,'Órion, Rei das Batalhas','Ninguém sobreviveu para contar as histórias deste poderoso guerreiro-fada.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2971446,'Papo de Vendedor',replace(replace('Se seu oponente adicionar um ou mais cards do Deck à mão dele, exceto ao comprá-los, devido a um efeito de card dele: revele 1 card do seu Deck e adicione-o à sua mão, mas você não pode ativar cards, ou os efeitos de cards, com esse nome pelo resto deste turno. \r\nVocê só pode ativar 1 "Papo de Vendedor" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2978414,'Número 46: Dragluon',replace(replace('2 monstros de Nível 8 do Tipo Dragão	\r\nUma vez por turno, se você não controlar outros monstros: você pode desassociar 1 Matéria Xyz deste card e, depois, ativar 1 desses efeitos.\r\n● Invoque por Invocação-Especial 1 monstro do Tipo Dragão da sua mão.\r\n● Escolha 1 monstro do Tipo Dragão que seu oponente controla; tome o controle do alvo.\r\n● Monstros do Tipo Dragão que seu oponente controla não podem ativar seus efeitos até o final do turno do seu oponente.','\r',char(13)),'\n',char(10)),'Invoque por Invocação Especial 1 monstro Dragão da sua mão','Tome o controle de 1 monstro Dragão que seu oponente controla','Monstros Dragão que seu oponente controla não podem ativar seus efeitos','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2980764,'Luz Consagrada',replace(replace('Nenhum duelista pode Invocar monstros de TREVAS por Invocação-Normal ou Especial nem declarar um ataque com um monstro de TREVAS. \r\nEste card não pode ser destruído em uma batalha com um monstro de TREVAS e, além disso, você não sofre dano de batalha dessa batalha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2986553,'Cavaleiro da Rosa do Crepúsculo',replace(replace('Monstros que seu oponente controla não podem escolher monstros Planta como alvo de ataques. \r\nQuando este card for Invocado por Invocação-Normal: você pode Invocar por Invocação-Especial 1 monstro Planta de Nível 4 ou menos da sua mão.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2992036,'Senhormek Astro, o Erradicador',replace(replace('Escolha 3 monstros "Senhormek" com nomes diferentes no seu Cemitério; adicione-os à sua mão, OU Invoque-os por Invocação-Especial, ignorando suas condições de Invocação. \r\nAté o final do seu próximo turno depois que este card for ativado, você não pode Invocar monstros por Invocação-Especial, exceto monstros Máquina. \r\nSe você controlar um monstro "Senhormek Astro": você pode banir este card do seu Cemitério; destrua 1 Monstro Sincro que seu oponente controla e, se isso acontecer, cause dano ao seu oponente igual ao ATK original dele. \r\nVocê só pode usar cada efeito de "Senhormek Astro, o Erradicador" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2992467,'Estalido & Eco',replace(replace('Não pode ser usado como matéria para uma Invocação-Fusão, Sincro ou Xyz. \r\nNão pode ser oferecido como Tributo enquanto estiver com a face para cima na Zona de Monstros. \r\nSe este card for enviado para o Cemitério como matéria para uma Invocação-Link: Invoque este card por Invocação-Especial em Posição de Defesa, no campo do oponente do duelista que Invocou por Invocação-Link. \r\nVocê só pode usar este efeito de "Estalido & Eco" duas vezes por turno. \r\nEnquanto este card, que foi Invocado por seu efeito, estiver na Zona de Monstros, você deve manter sua mão revelada.','\r',char(13)),'\n',char(10)),'','Mantenha sua mão revelada','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(2994495,'Onda Fuhma','Escolha 1 monstro com a face para cima no campo; destrua 1 monstro no campo com o mesmo Atributo, mas com um nome diferente que o desse monstro.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3019642,'Enquilha Cibersombria',replace(replace('Se este card for Invocado por Invocação-Normal: escolha 1 monstro Dragão de Nível 3 ou menos no seu Cemitério; equipe esse monstro Dragão a este card. \r\nGanha ATK igual ao ATK original do monstro equipado a ele por este efeito. \r\nSe este card destruir um monstro do oponente em batalha: cause 300 de dano ao seu oponente. \r\nSe este card seria destruído em batalha, em vez disso, destrua esse monstro equipado a ele.','\r',char(13)),'\n',char(10)),'Equipar','Causar dano','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3026686,'Valquíria-Dritte',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 card "Valquíria-" do seu Deck à sua mão, exceto "Valquíria-Dritte". \r\nVocê só pode usar este efeito de "Valquíria-Dritte" uma vez por turno. \r\nGanha 200 de ATK para cada um dos monstros banidos do seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3027001,'Armadilha Falsa',replace(replace('Você pode Activar o efeito deste card quando o seu adversário usar um Card de Magia, Armadilha ou Monstro de Efeito que destrua um ou mais Cards de Armadilha no seu Campo. \r\nAo invés disso, destrua este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3030892,'Macaco de Laboratório','Quando este card for destruído em batalha e enviado para o Cemitério, você pode Invocar por Invocação-Especial 1 monstro "Besta Gladiadora" de Nível 4 ou menos do seu Deck.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3040496,'Governante do Caos, o Dragão Mágico Caótico',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro: você pode escavar os 5 cards do topo do seu Deck e, se isso acontecer, você pode adicionar à sua mão 1 monstro de LUZ ou de TREVAS escavado e, além disso, envie os cards restantes para o Cemitério. \r\nVocê pode banir 1 monstro de LUZ e 1 de TREVAS da sua mão e/ou do Cemitério, exceto este card; Invoque este card por Invocação-Especial do seu Cemitério, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar cada efeito de "Governante do Caos, o Dragão Mágico Caótico" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Escolher 1 card para adicionar à mão?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3048768,'Angello Vaalmônica',replace(replace('Escala de Pêndulo = 3\r\n[ Efeito de Pêndulo ]\r\nSempre que você ganhar PV enquanto você controlar um Card de Monstro Demônio na sua outra Zona de Pêndulo, coloque 1 Marcador de Ressonância neste card. \r\nUma vez por turno, quando um monstro do oponente declarar um ataque, você pode: imediatamente depois que este efeito resolver, Invocar por Invocação-Link 1 Monstro Link "Vaalmônica".\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe este card estiver na sua mão: você pode descartar 1 outro card; pegue 1 "Dimonno Vaalmônica" do seu Deck e coloque este card e esse card nas suas Zonas de Pêndulo. \r\nDurante sua Fase Principal, se este card foi Invocado por Invocação-Normal ou Especial neste turno: você pode banir 1 Magia/Armadilha Normal "Vaalmônica" do seu Cemitério; aplique qualquer efeito nesse card que inclua ganhar PV. \r\nVocê só pode usar cada efeito de "Angello Vaalmônica" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Coloque esta carta e "Dimonno Vaalmônica" do seu Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3055018,'Obsidim, a Cidade Cinzenta',replace(replace('Monstros com a face para cima Invocados por Invocação-Especial que seu oponente controla se tornam Piro apenas durante o seu turno. \r\nVocê só pode usar cada um dos seguintes efeitos de "Obsidim, a Cidade Cinzenta" uma vez por turno. \r\nDurante sua Fase Final: você pode escolher 1 "Obsidim, a Cidade Cinzenta" no seu Cemitério; coloque-o no fundo do seu Deck e, depois, compre 1 card. \r\nSe este card na Zona do Campo for destruído ou banido: você pode Invocar por Invocação-Especial 1 monstro "Cinzento(a)" do seu Deck.','\r',char(13)),'\n',char(10)),'','Reciclar e comprar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3055837,'Armadilha do Apagador de Tabuleiros','Quando um efeito que inflija dano aos Life Points for activado (exceto dano de batalha), anule o dano aos seus Life Points e o seu adversário escolhe 1 card da sua própria mão e descarta-o.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3056267,'Invasor do Trono',replace(replace('VIRE: Selecione 1 monstro no lado do campo do seu oponente e troque o controle dele com o deste card. \r\nEste efeito não pode ser ativado durante a Fase de Batalha.','\r',char(13)),'\n',char(10)),'Trocar o controle','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3064425,'Canhão Samurai Superpesado Estrondo de Almas',replace(replace('(Este card deve ser sempre considerado como um card "Samurai Superpesado Alma".)	\r\nVocê pode escolher 1 monstro "Samurai Superpesado" que você controla; equipe este monstro da sua mão ou do campo ao alvo. \r\nEle ganha 1000 de DEF. \r\nDurante a Fase de Batalha, quando seu oponente ativar um card ou efeito enquanto você controlar um monstro "Samurai Superpesado" em Posição de Defesa (Efeito Rápido): você pode banir este card do seu Cemitério; negue a ativação e, se isso acontecer, destrua-o e, depois, destrua tantos monstros no campo quanto possível (mín. 1) e, se isso acontecer, os dois duelistas sofrem 1000 de dano.','\r',char(13)),'\n',char(10)),'Equipar a um monstro "Samurai Superpesado"','Negar e destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3064783,'Terror Umbral Brilhante',replace(replace('Se você Invocar por Invocação-Especial um ou mais monstros "Terror Umbral" e/ou "Mascarado": você pode Invocar por Invocação-Especial este card da sua mão, e se fizer, compre 1 card, então se você comprou um monstro "Terror Umbral", você pode Invoca-lo por Invocação-Especial.\r\nPode ser considerado como 2 matérias para a Invocação-Xyz de um Monstro Xyz "Número" que precise de 3 ou mais matérias.\r\nVocê só pode usar cada um dos efeitos de','\r',char(13)),'\n',char(10)),'Invocação Especial','Invocação Especial?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3070049,'Dragão da Neve','Quando este card for destruído em batalha ou por um efeito de card e enviado ao Cemitério: Coloque 1 Marcador de Gelo em cada monstro com a face para cima no campo.','Colocar um marcador','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3072077,'Zumbi Recorrente',replace(replace('Durante sua Fase de Apoio: você pode pagar 500 Pontos de Vida; adicione este card do seu Cemitério à sua mão. \r\nVocê não pode ter cards em sua mão para ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3072808,'Asanegra - Hillen, o Vento-Tengu',replace(replace('Se você sofrer 2000 ou mais de dano de batalha de um ataque direto de um monstro do seu oponente enquanto este card estiver no seu Cemitério: escolha 1 monstro "Asanegra" de Nível 3 ou menos no seu Cemitério; Invoque por Invocação-Especial tanto esse monstro quanto este card do Cemitério, mas negue seus efeitos. \r\nVocê só pode usar este efeito de "Asanegra - Hillen, o Vento-Tengu" uma vez por Duelo.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3078380,'Timaeus, o Dragão Unido',replace(replace('Você pode enviar para o Cemitério 1 monstro Mago ou 1 Magia/Armadilha que mencione "Mago Negro", da sua mão ou do campo com a face para cima; Invoque este card por Invocação-Especial da sua mão. \r\nDurante sua Fase Principal: você pode Invocar por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional, usando monstros da sua mão ou do campo como matéria, incluindo um monstro Mago. \r\nVocê só pode usar cada efeito de "Timaeus, o Dragão Unido" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3078576,'Yata-Garasu',replace(replace('Não pode ser Invocado por Invocação-Especial. \r\nDurante a Fase Final do turno em que este card foi Invocado por Invocação-Normal ou virado com a face para cima: devolva-o para a mão. \r\nSe este card causar dano de batalha ao seu oponente: pule a Fase de Compra do próximo turno dele.','\r',char(13)),'\n',char(10)),'Retornar para a mão','Pule sua próxima Fase de Compra','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3084730,'Armadura Bioinseto',replace(replace('Se este card estiver na sua mão ou no Cemitério e você não controlar "Armadura Bioinseto": você pode escolher 1 monstro Inseto que você controla; equipe este card a ele, mas bana-o quando ele deixar o campo e, além disso, bana este Card de Equipamento quando ele deixar o campo. \r\nVocê só pode usar este efeito de "Armadura Bioinseto" uma vez por turno. \r\nO monstro equipado ganha 1500 de ATK/2000 de DEF apenas durante a Fase de Batalha e Fase Principal 2.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3096468,'Tatsunecro',replace(replace('Se este monstro Invocado por Invocação-Normal/Baixado seria usado como Matéria Sincro, 1 monstro na sua mão pode ser usado como 1 das outras matérias. \r\nSe você fizer isso, todas as matérias para essa Invocação são banidas em vez de serem enviadas para o Cemitério. \r\nVocê não pode Invocar monstros por Invocação-Especial, exceto monstros Zumbi.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3103067,'Armadura Condutora de Ataque',replace(replace('Quando um monstro declarar um ataque: ative 1 desses efeitos;\r\n● Destrua o monstro atacante.\r\n● Escolha 1 monstro em qualquer campo, exceto o monstro atacante; mude o alvo do ataque para ele e realize o cálculo de dano.	\r\nVocê só pode ativar 1 "Armadura Condutora de Ataque" por turno.','\r',char(13)),'\n',char(10)),'Destruir o monstro atacante','Alterar o alvo do ataque','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3105404,'Faísca Brilhante',replace(replace('Se um ou mais monstros "Cavaleiro-Gema" com a face para cima que você controla forem destruídos por um ataque ou efeito de card do seu oponente: escolha 1 desses monstros destruídos; cause dano ao seu oponente igual ao ATK original dele. \r\nSe este card estiver no seu Cemitério: você pode enviar 1 card "Cavaleiro-Gema" da sua mão para o Cemitério; adicione este card à sua mão. \r\nVocê só pode ativar 1 "Faísca Brilhante" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3111207,'Dragão Láppis',replace(replace('Se este card for adicionado do Deck à sua mão: você pode revelar este card; Invoque-o por Invocação-Especial. \r\nSe este card for adicionado do seu Cemitério à sua mão por um efeito de card: você pode revelar este card; Invoque este card por Invocação-Especial, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar 1 efeito de "Dragão Láppis" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3113667,'Ginetes de Metal Pesado',replace(replace('Na primeira vez que cada monstro Máquina de TREVAS que você controla seria destruído em batalha a cada turno, ele não é destruído e se você sofreu dano de batalha da batalha, ele ganha esse valor de ATK depois do cálculo de dano e mantém o ganho de ATK enquanto este card estiver no campo. \r\nUma vez por turno, se um monstro que você controla que originalmente era uma Máquina de TREVAS destruir um ou mais cards no campo em batalha ou por um efeito de card: você pode Invocar por Invocação-Especial 1 monstro Máquina de TREVAS da sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3113836,'Cavaleiro-Gema Serafinita',replace(replace('1 monstro "Cavaleiro-Gema" + 1 monstro de LUZ	\r\nPrimeiro deve ser Invocado por Invocação-Fusão com as Matérias de Fusão acima. \r\nDurante sua Fase Principal, você pode Invocar por Invocação-Normal/Baixar 1 monstro em adição à sua Invocação-Normal/Baixar padrão. \r\n(Você só pode se aproveitar deste efeito uma vez por turno.)','\r',char(13)),'\n',char(10)),'Invocar pelo efeito de "Cavaleiro-Gema Serafinita"','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3117804,'Samurai Superpesado Grande Benkei',replace(replace('Quando este card for Invocado por Invocação-Normal ou Especial: você pode mudar a posição de batalha dele. \r\nMonstros "Samurai Superpesado" que você controla podem atacar enquanto estiverem com a face para cima em Posição de Defesa. \r\nSe o fizerem, use a DEF deles para o cálculo de dano.','\r',char(13)),'\n',char(10)),'Mudar a posição de batalha','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3121655,'Tomadragão Sucata',replace(replace('Se você controlar um Monstro Sincro, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Tomadragão Sucata" por Invocação-Especial uma vez por turno desta forma. \r\nQuando um Monstro Sincro que você controla declarar um ataque: você pode banir este card do seu Cemitério; esse monstro que você controla ganha 800 de ATK até o final deste turno. \r\nVocê só pode usar este efeito de "Tomadragão Sucata" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3129133,'Delta do Convite',replace(replace('Quando este card for ativado: você pode enviar 1 monstro Zumbi de Nível 5 ou mais do seu Deck para o Cemitério. \r\nVocê só pode usar cada um dos seguintes efeitos de "Delta do Convite" uma vez por turno. \r\nSe um monstro Zumbi estiver no campo: você pode Invocar por Invocação-Especial 1 "Ficha de Delta" (Zumbi/TREVAS/Nível 5/ATK 0/DEF 0). \r\nSe um ou mais monstros forem adicionados do Cemitério à mão, enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode adicionar este card à sua mão. \r\nVocê só pode ativar 1 "Delta do Convite" por turno.','\r',char(13)),'\n',char(10)),'Ativar','Invocação Especial','Adicionar à mão','Enviar o card para o Cemitério?','','','','','','','','','','','','');
INSERT INTO texts VALUES(3129134,'Ficha de Delta','Invocado por Especial com o efeito "Delta do Convite".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3129527,'Bode Expiatório Dormindo',replace(replace('Invoque por Invocação-Especial até 4 "Ficha de Bode Expiatório" (Besta/TERRA/Nível 1/ATK 0/DEF 0) em Posição de Defesa, então se seu oponente controla um monstro, você pode Invocar por Invocação-Especial 1 "Guerreiro Pantera Veloz" do seu Deck, também pelo resto deste turno, estas Fichas não pode ser oferecidas como Tributo para uma Invocação-Tributo, você também não pode Invocar por Invocação-Especial do seu Deck Adicional, exceto Monstros Fusão.\r\nSe um ou mais cards que você controla menciona "Mago do Tempo Sombrio" seria destruído por batalha ou efeito, em vez disso você pode destruir 1 das suas Fichas Invocadas.','\r',char(13)),'\n',char(10)),'Ativar','Selecione o número de Invocações Especiais','Invocar {CARD} por Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3129528,'Ficha de Bode Expiatório',replace(replace('Invocado por Invocação-Especial por efeito de "Bode Expiatório Dormindo".\r\nSe um card que você controla que menciona "Mago do Tempo Sombrio" em seu texto seria destruído por batalha ou efeito, em vez disso você pode destruir este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3129529,'Ficha de Bode Expiatório',replace(replace('Invocado por Invocação-Especial por efeito de "Bode Expiatório Dormindo".\r\nSe um card que você controla que menciona "Mago do Tempo Sombrio" em seu texto seria destruído por batalha ou efeito, em vez disso você pode destruir este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3129530,'Ficha de Bode Expiatório',replace(replace('Invocado por Invocação-Especial por efeito de "Bode Expiatório Dormindo".\r\nSe um card que você controla que menciona "Mago do Tempo Sombrio" em seu texto seria destruído por batalha ou efeito, em vez disso você pode destruir este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3129531,'Ficha de Bode Expiatório',replace(replace('Invocado por Invocação-Especial por efeito de "Bode Expiatório Dormindo".\r\nSe um card que você controla que menciona "Mago do Tempo Sombrio" em seu texto seria destruído por batalha ou efeito, em vez disso você pode destruir este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3129635,'Maldição Tiki',replace(replace('Invoque este card por Invocação-Especial como um Monstro de Efeito (Tipo Rocha/TREVAS/Nível 4/ATK 1800/DEF 1000).	\r\n(Este card ainda é considerado um Card de Armadilha.) \r\nEnquanto este card for um Monstro de Efeito, se outro Card de Armadilha que seja um monstro batalhar um monstro do oponente, depois do cálculo de dano: destrua esse monstro do oponente.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3134241,'Kamakiri Voador #2','Um louva-a-deus voador que se alimenta principalmente de insetos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3134857,'Orcustrino',replace(replace('2+ Monstros de Efeito, incluindo um monstro "Orcust"	\r\nEste card linkado não pode ser destruído em batalha ou por efeitos de card. \r\nVocê pode escolher 3 dos seus monstros Máquina banidos; embaralhe-os no Deck e, se isso acontecer, o ATK/DEF de quaisquer monstros linkados que seu oponente controla atualmente se torna 0 e, além disso, seus efeitos são negados. \r\nVocê só pode usar este efeito de "Orcustrino" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3136426,'Limite de Nível- Área B','Coloque em Posição de Defesa todos os monstros de Nível 4 ou mais com a face para cima.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3137279,'Ixeep, o Presságio dos Ghoti',replace(replace('Se um ou mais monstros Peixe forem banidos (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão. \r\nDurante a Fase de Apoio do próximo turno depois que este card foi banido: você pode escolher 1 das suas Armadilhas "Ghoti" que estiverem banidas ou no seu Cemitério; Baixe o alvo. \r\nVocê só pode usar cada efeito de "Ixeep, o Presságio dos Ghoti" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3146695,'Reator Psíquico',replace(replace('Se você controlar um monstro do Tipo Psíquico: pelo resto do turno, aplique este efeito a todos os monstros do Tipo Psíquico que você controla atualmente. \r\nQuando um monstro do Tipo Psíquico que você controla batalhar um monstro do oponente, depois do cálculo de dano: bana esse monstro do Tipo Psíquico e, além disso, bana esse monstro do oponente.','\r',char(13)),'\n',char(10)),'Banir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3149401,'Dragão Definitivo de Orgulho e Alma',replace(replace('3 monstros com 2500 de ATK/DEF originais	\r\nEnquanto você controlar este card Invocado por Invocação-Fusão, seu oponente não pode escolhê-lo como alvo de efeitos de card e, além disso, ele não pode ser destruído pelos efeitos de card do seu oponente. \r\nEnquanto você tiver 25 ou mais cards no seu Cemitério, este card Invocado por Invocação-Fusão ganha 4500 de ATK/DEF. \r\nUma vez por turno, se seu oponente tiver 25 ou mais cards no Cemitério dele: você pode destruir todos os cards que seu oponente controla.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3149764,'Máscara de Tutan','Quando um Card de Magia/Armadilha que escolha como alvo exatamente 1 monstro Zumbi no campo (e nenhum outro card) for ativado: negue a ativação e, se isso acontecer, destrua-o.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3160805,'Trocar a Noite pelo Dia',replace(replace('Você só pode usar 1 efeito de "Trocar a Noite pelo Dia" por turno e apenas uma vez por turno. \r\nVocê pode ativar 1 desses efeitos;\r\n● Envie 1 monstro de LUZ do Tipo Guerreiro da sua mão para o Cemitério e, depois, adicione 1 monstro de TREVAS do Tipo Guerreiro do seu Deck à sua mão, que tenha o mesmo Nível que o monstro enviado da sua mão.\r\n● Envie 1 monstro de TREVAS do Tipo Guerreiro da sua mão para o Cemitério e, depois, adicione 1 monstro de LUZ do Tipo Guerreiro do seu Deck à sua mão, que tenha o mesmo Nível que o monstro enviado da sua mão.','\r',char(13)),'\n',char(10)),'Ativar o efeito','Usar o efeito de "Trocar a Noite pelo Dia" agora?','Enviar 1 monstro de LUZ para o Cemitério e adicione 1 monstro de TREVAS à sua mão','Enviar 1 monstro de TREVAS para o Cemitério e adicione 1 monstro de LUZ à sua mão','','','','','','','','','','','','');
INSERT INTO texts VALUES(3167439,'Punição do Mundo Negro',replace(replace('Quando um ou mais monstros seriam Invocados por Invocação-Normal ou Especial: você pode negar a Invocação e, se isso acontecer, destrua esse(s) monstro(s) e, depois, descarte 1 monstro Demônio. \r\nSe um ou mais monstros "Mundo Negro" que você controla seriam destruídos em batalha ou por um efeito de card do oponente, em vez disso, você pode banir este card do seu Cemitério. \r\nVocê só pode usar cada efeito de "Punição do Mundo Negro" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3167573,'Rei Marionete',replace(replace('Quando o oponente adicionar Cards de Monstro à mão dele, exceto ao comprar, você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe isso acontecer, destrua-o durante a Fase Final do seu próximo turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3170832,'Takuhee','Este pássaro é amplamente conhecido como um arauto da condenação.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3171055,'Cadeia de Dissipação','Quando um Card de Magia/Armadilha for ativado: destrua todos os cards no Deck do seu controlador que tenham o mesmo nome que o card ativado.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3204467,'Lombriga Sólida',replace(replace('Este card ganha 100 de DEF para cada monstro "Lombriga" do Tipo Réptil no seu Cemitério. \r\nSe seu oponente sofrer Dano de Batalha ao atacar este card, no final da Etapa de Dano selecione 1 Card de Magia ou Armadilha que seu oponente controla e destrua-o.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3211439,'Apócrifo Proibido','Declare 1 tipo de card de monstro (Fusão, Sincro ou Xyz); se 2 ou mais monstros do tipo declarado estiverem no campo, faça com que cada duelista envie todos os monstros desse tipo do seu campo para o Cemitério.','Fusão','Sincro','Xyz','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3233859,'Rodador Psíquico',replace(replace('Se você controlar um monstro de Nível 3 que não seja "Rodador Psíquico", você pode Invocar este card por Invocação-Especial (da sua mão) em Posição de Defesa. \r\nVocê só pode Invocar "Rodador Psíquico" por Invocação-Especial uma vez por turno desta forma. \r\nSe este card for enviado para o Cemitério como Matéria Sincro: você pode escolher 1 monstro no campo com ATK menor que o do Monstro Sincro que usou este card como matéria; destrua-o. \r\nVocê só pode usar este efeito de "Rodador Psíquico" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3244563,'Lança Escudo','Escolha 1 monstro com a face para cima no campo; ele ganha 400 de ATK/DEF até o final deste turno.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3248469,'Abelha Aspirante!',replace(replace('Durante a Fase Final: você pode enviar este card da sua mão ou do campo para o Cemitério; escave cards do topo do seu Deck, igual ao número de Zonas de Magias & Armadilhas não utilizadas do seu oponente, e você pode Baixar 1 Armadilha escavada no seu campo (mas envie-a para o Cemitério durante a próxima Fase Final) e, além disso, coloque o resto no fundo do Deck em qualquer ordem. \r\nVocê só pode usar este efeito de "Abelha Aspirante!" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Baixar 1 Card de Armadilha?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3259760,'Enfeitiçado','Todos os monstros com a face para cima que seu oponente controla atualmente não podem ser oferecidos como Tributo ou usados como matéria para uma Invocação-Fusão, Sincro, Xyz ou Link até o final deste turno.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3280747,'Sexto Sentido',replace(replace('Declare 2 números de 1 a 6 e, depois, seu oponente lança um dado de seis faces e se o resultado for um dos números que você declarou, você compra esse número de cards. \r\nCaso contrário, envie um número de cards do topo do seu Deck para o Cemitério igual ao resultado.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3283679,'Evoltil Lagosucho',replace(replace('Quando este card for Invocado por Invocação-Normal: Você pode enviar 1 monstro "Evolssauro" do seu Deck ao Cemitério. \r\nQuando este card for virado com a face para cima: Você pode Invocar por Invocação-Especial 1 monstro "Evoltil" do seu Deck.','\r',char(13)),'\n',char(10)),'Enviar para o Cemitério','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3285551,'Ritual de Aramesir',replace(replace('Se você não controlar nenhuma "Ficha de Aventura": Invoque por Invocação-Especial 1 "Ficha de Aventura" (Fada/TERRA/Nível 4/ATK 2000/DEF 2000) e, depois, se você não controlar "Aventura Fatídica", você pode colocar 1 "Aventura Fatídica" do seu Deck com a face para cima na sua Zona de Magias & Armadilhas. \r\nVocê não pode ativar os efeitos de monstros no campo no turno em que ativar este card, exceto os de monstros Invocados por Invocação-Especial. \r\nVocê só pode ativar 1 "Ritual de Aramesir" por turno.','\r',char(13)),'\n',char(10)),'Colocar "Aventura Fatídica" do seu Deck?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3285552,'Ficha de Aventura','Invocado por Especial com o efeito "Ritual de Aramesir".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3287359,'Mágico Mosquete Mentor Caspar',replace(replace('2 monstros, incluindo um monstro Demônio de LUZ	\r\nDurante o turno de qualquer duelista, você pode ativar Cards de Magia/Armadilha "Mágico(a) Mosquete" da sua mão. \r\nSe este card for Invocado por Invocação-Link: você pode pegar 2 cards "Mágico(a) Mosquete" da sua mão e/ou do Deck, incluindo um monstro, Invocar por Invocação-Especial 1 monstro daí no seu campo e Baixar o outro no campo do seu oponente. \r\nVocê só pode usar este efeito de "Mágico Mosquete Mentor Caspar" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar','Ativar aplicando o efeito de "Mágico Mosquete Mentor Caspar".','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3289027,'Parl, Eremita do Mundo Negro',replace(replace('Se este card for descartado para o Cemitério por um efeito de card: você pode escolher 1 monstro "Mundo Negro" no seu Cemitério, exceto "Parl, Eremita do Mundo Negro"; Invoque-o por Invocação-Especial em qualquer campo e, depois, se este card foi descartado da sua mão para o seu Cemitério por um efeito de card do oponente, você pode Invocar por Invocação-Especial, em qualquer campo, 1 dos seus monstros Demônio que estiverem banidos, ou na sua mão ou no Cemitério. \r\nVocê só pode usar este efeito de "Parl, Eremita do Mundo Negro" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Invocar 1 monstro adicional por Invocação Especial?','Invocar por Invocação Especial para o seu Campo','Invocar por Invocação Especial para o Campo do seu oponente','','','','','','','','','','','','');
INSERT INTO texts VALUES(3292267,'Dragão Celeste Hierático Suserano de Heliópolis',replace(replace('2 monstros de Nível 8	\r\nUma vez por turno, quando seu oponente ativar um card ou efeito que escolha como alvo um ou mais cards no seu campo, seu Cemitério e/ou seus cards banidos (Efeito Rápido): você pode desassociar 1 matéria deste card; negue a ativação e, se isso acontecer, destrua esse card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3294539,'Dragão da Lâmina Carmesim',replace(replace('1 Regulador "Ressonador" + 1+ não-Reguladores	\r\n(Este card deve ser sempre considerado como "Laminador Carmesim".)	\r\nSe este card for Invocado por Invocação-Sincro: você pode pegar 1 monstro de Nível 8 ou mais que não possa ser Invocado por Invocação-Normal/Baixado do seu Deck ou Cemitério e adicione-o à sua mão ou Invoque-o por Invocação-Especial, mas negue seus efeitos. \r\nVocê só pode usar este efeito de "Dragão da Lâmina Carmesim" uma vez por turno. \r\nNo começo da Etapa de Dano, se este card batalhar um monstro de Nível 5 ou mais: você pode destruir esse monstro.','\r',char(13)),'\n',char(10)),'Efeito de busca','Efeito de destruição','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3298689,'Lançar Magia de Aumento de Classe de Os Cavaleiros Fantasmas',replace(replace('Durante a Fase Principal: escolha 1 Monstro Xyz de TREVAS que você controla sem matéria; Invoque por Invocação-Especial do seu Deck Adicional, 1 Monstro Xyz de TREVAS de 1 Classe maior que a do monstro que você controla, usando-o como matéria e, se isso acontecer, associe este card a ele como uma matéria adicional. \r\n(Isso é considerado uma Invocação-Xyz. Transfira as matérias dele para o monstro Invocado.) \r\nDurante sua Fase Principal: você pode banir este card do seu Cemitério e, depois, escolha 1 Monstro Xyz de TREVAS que você controla; associe 1 monstro "Os Cavaleiros Fantasmas" da sua mão a esse monstro como matéria.','\r',char(13)),'\n',char(10)),'Invocação Especial','Matéria Xyz','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3300267,'Dragão Hierático de Su',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) ao oferecer como Tributo 1 monstro "Hierático". \r\nUma vez por turno: você pode oferecer como Tributo 1 outro monstro "Hierático" da sua mão ou do campo e, depois, escolha 1 Magia/Armadilha que seu oponente controla; destrua o alvo. \r\nSe este card for oferecido como Tributo: Invoque por Invocação-Especial 1 Monstro Normal Dragão da sua mão, do Deck ou do Cemitério, e torne seu ATK/DEF 0.','\r',char(13)),'\n',char(10)),'Destruir','Invocação Especial','Forma de Invocação: Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3322931,'Wolfrayet do Vento Estelar',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nVocê só pode controlar 1 "Wolfrayet do Vento Estelar". \r\nGanha 300 de ATK sempre que o efeito de outro monstro for ativado enquanto o ATK deste card for menor que 4000. \r\nUma vez por turno, se o ATK deste card for 4000 ou mais (Efeito Rápido): você pode embaralhar no Deck tanto este card como todos os monstros que seu oponente controla.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3355732,'Gelojade Kosmochlor',replace(replace('Se um card com a face para cima estiver em uma Zona do Campo, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Gelojade Kosmochlor" por Invocação-Especial uma vez por turno desta forma. \r\nEnquanto "Berço Enion, Cenote de Gelojade" estiver no campo, monstros que seu oponente controla só podem ativar seus efeitos no turno em que forem Invocados. \r\nSe um monstro "Gelojade" seu batalhar um monstro do oponente, esse monstro do oponente perde 1000 de ATK apenas durante esse cálculo de dano.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3356494,'Dragão Explosolar de Olhos das Galáxias',replace(replace('2 monstros de LUZ, incluindo um monstro com 2000 ou mais de ATK	\r\nSe este card for Invocado por Invocação-Link: você pode escolher 1 monstro "Fóton" ou "Galáxia" no seu Cemitério; adicione-o à sua mão. \r\nDurante a Fase Principal do seu oponente (Efeito Rápido): você pode descartar 1 card "Fóton" e 1 card "Galáxia", OU descartar 1 "Dragão de Fóton de Olhos das Galáxias" e, depois, escolher 1 monstro Invocado por Invocação-Especial que seu oponente controla; destrua-o. \r\nVocê só pode usar cada efeito de "Dragão Explosolar de Olhos das Galáxias" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Descartar "Neo Dragão de Fóton de Olhos das Galáxias"?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3361010,'Kitsuni Kitsunebi',replace(replace('Todos os monstros com a face para cima no campo se tornam de FOGO. \r\nSe seu oponente tiver um monstro de FOGO no campo dele ou no Cemitério dele, enquanto este card estiver no seu Cemitério: você pode Invocar este card por Invocação-Especial. \r\nVocê só pode usar este efeito de "Kitsuni Kitsunebi" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3366982,'Dragão Espada do Jacaré',replace(replace('"Dragão Filhote" + "Espada do Jacaré"	\r\nEste card pode atacar diretamente seu oponente se os únicos monstros com a face para cima que ele controla forem de TERRA, ÁGUA ou FOGO.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3370104,'Fênix Cibernética',replace(replace('Enquanto este card estiver em Posição de Ataque, negue quaisquer efeitos de Magia/Armadilha que escolham como alvo 1 monstro Máquina que você controla (e nenhum outro card). \r\nQuando este card for destruído em batalha e enviado para o Cemitério: você pode comprar 1 card.','\r',char(13)),'\n',char(10)),'Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3376703,'Força Arcana V - O Hierofante',replace(replace('Você pode descartar este card; neste turno, seu oponente não pode ativar cards ou efeitos quando um ou mais monstros "Força Arcana" forem Invocados no seu campo. \r\nSe este card for Invocado: lance uma moeda.\r\n● Cara: Invoque por Invocação-Especial 1 monstro "Força Arcana" de Nível 4 ou menos do seu Deck com um nome diferente que o dos monstros que você controla e no seu Cemitério.\r\n● Coroa: Invoque por Invocação-Especial 1 monstro "Força Arcana" do seu Deck no campo do seu oponente.','\r',char(13)),'\n',char(10)),'Seu oponente não pode ativar efeitos','Invocar por Invocação Especial do Deck','Com a face para cima','Com a face para baixo','','','','','','','','','','','','');
INSERT INTO texts VALUES(3381441,'Sacerdotisa do Coveiro',replace(replace('Enquanto não houver Magias de Campo com a face para cima, o campo é considerado como "Necro-Vale". \r\nTodos os monstros "do Coveiro" no campo ganham 200 de ATK/DEF.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3395226,'Mozarta, a Maestra Melodiosa',replace(replace('Uma vez por turno: você pode Invocar por Invocação-Especial 1 monstro de LUZ do Tipo Fada da sua mão. \r\nVocê não pode Invocar outros monstros por Invocação-Especial no turno em que ativar este efeito, exceto por monstros de LUZ.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3405259,'Wivern de Compressão C',replace(replace('Uma vez por turno, você pode: escolher 1 monstro Máquina de LUZ que você controla; equipe este card no alvo, OU: desequipe este card e Invoque-o por Invocação-Especial. \r\nUm monstro equipado com este card não é afetado pelos efeitos de Armadilha do seu oponente e, além disso, se o monstro equipado seria destruído em batalha ou por um efeito de card, em vez disso, destrua este card. \r\nSe este card for enviado do campo para o Cemitério: você pode Invocar por Invocação-Especial 1 monstro União da sua mão.','\r',char(13)),'\n',char(10)),'Equipar','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3410461,'Alba-Lenatus, o Dragão do Abismo',replace(replace('"Caído de Arbaz" + 1+ monstros Dragão	\r\nNão pode ser usado como Matéria de Fusão. \r\nDeve ser Invocado por Invocação-Fusão ou por Invocação-Especial ao enviar os cards acima de quaisquer Zonas de Monstros para o Cemitério. \r\nPode atacar monstros um número de vezes a cada Fase de Batalha, até o número de matérias usadas para ele. \r\nUma vez por turno, durante a Fase Final, se este card estiver no Cemitério porque foi enviado para lá neste turno: você pode adicionar 1 Magia Normal "Polimerização" ou Magia Normal "Fusão" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3422200,'Cristron Sulfefnir',replace(replace('Se este card estiver na sua mão ou no Cemitério: você pode descartar 1 card "Cristron", exceto "Cristron Sulfefnir"; Invoque este card por Invocação-Especial em Posição de Defesa e, depois, destrua 1 card que você controla. \r\nSe este card no campo for destruído em batalha ou por um efeito de card: você pode Invocar por Invocação-Especial 1 monstro "Cristron" do seu Deck em Posição de Defesa. \r\nVocê só pode usar cada efeito de "Cristron Sulfefnir" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3428069,'Blader Notável, o Mestre da Espada da Destruição',replace(replace('O nome deste card se torna "Blader Notável" enquanto estiver no campo ou no Cemitério. \r\nSe um ou mais monstros que seu oponente controla forem destruídos em batalha ou por um efeito de card e enviados para o Cemitério: você pode escolher 1 desses monstros destruídos; equipe-o neste card. \r\nUma vez por turno: você pode enviar para o Cemitério 1 Card de Monstro que você controla equipado a este card; destrua todos os monstros que seu oponente controla com o mesmo Tipo que o desse monstro enviado para o Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3429238,'Guerreiro Broca',replace(replace('"Broca Sincron" + 1+ monstros não-Reguladores	\r\nUma vez por turno, durante sua Fase Principal 1: você pode diminuir pela metade o ATK deste card e, se isso acontecer, ele pode atacar diretamente seu oponente neste turno. \r\nUma vez por turno: você pode descartar 1 card e, se isso acontecer, bana este card. \r\nDurante sua próxima Fase de Apoio: Invoque por Invocação-Especial este card banido por este efeito e, depois, adicione 1 monstro do seu Cemitério à sua mão.','\r',char(13)),'\n',char(10)),'O ATK se torna metade','Banir este card','Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3431737,'Besta de Ataque','Você pode descartar este card para o Cemitério; adicione 1 "Ativar Modo de Ataque" do seu Deck à sua mão.','Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3434362,'Mamute Ferrugem',replace(replace('Se este card estiver na sua mão: você pode banir Monstros Link Máquina do seu Deck Adicional cuja soma dos Valores Link seja exatamente igual a 5; Invoque este card por Invocação-Especial. \r\nVocê pode escolher 1 card que você controla e 1 card que seu oponente controla; devolva-os para a mão. \r\nEste é um Efeito Rápido se este card estiver linkado a um Monstro Link Máquina de Link-3 ou mais. \r\nVocê só pode usar cada efeito de "Mamute Ferrugem" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Retornar para a mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3441553,'Destruidor Cintilante das Feras Sagradas',replace(replace('Ative 1 desses efeitos;\r\n● Quando seu oponente ativar um card ou efeito em resposta a ativação dos efeitos dos seus monstros "Bestas Sagradas": negue aquele efeito do oponente.\r\n● Revele 1 monstro de Nível 10 "Besta Sagrada" na sua mão; descarte 1 card, e se fizer, adicione 1 "Portão da Ilusão" do seu Deck à sua mão.\r\n● Embaralhe 3 Armadilhas "Besta Sagrada" do seu Cemitério e/ou banimento no Deck, então escolha 1 card que seu oponente controla; destrua-o.	\r\nVocê só pode ativar 1 "Destruidor Cintilante das Feras Sagradas" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar','Negar o efeito','Efeito de busca','Efeito de destruição','','','','','','','','','','','','');
INSERT INTO texts VALUES(3461403,'O Bushi Imortal Lamenta o Corpo Mortal',replace(replace('Todos os monstros no seu Cemitério se tornam monstros Guerreiro. \r\nUma vez por turno, durante a Fase Final: você pode destruir todos os monstros que você controla.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3486020,'Yoko, a Mayakashi Elegante',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nVocê só pode controlar 1 "Yoko, a Mayakashi Elegante". \r\nVocê só pode usar cada um desses efeitos de "Yoko, a Mayakashi Elegante" uma vez por turno.\r\n● Se um Monstro Sincro em sua posse, cujo Nível original seja 11, for destruído em batalha ou por um efeito de card do oponente enquanto este card estiver no Cemitério: você pode banir 1 outro monstro Zumbi no seu Cemitério e, se isso acontecer, Invoque este card por Invocação-Especial.\r\n● Se este card for Invocado por Invocação-Especial do Cemitério: você pode destruir 1 monstro que seu oponente controla.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3492538,'Armadura Inseto com Canhão Laser',replace(replace('Só pode ser equipado a um monstro Inseto. \r\nEle ganha 700 de ATK.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3493058,'Furadadão',replace(replace('Lance um dado de seis faces e aplique o resultado.\r\n● 2, 3 ou 4: Destrua 1 Magia/Armadilha no campo.\r\n● 5: Destrua 2 Magia/Armadilha no campo.\r\n● 1 ou 6: Você sofre 1000 de dano.','\r',char(13)),'\n',char(10)),'Role um dado','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3493978,'Dom Tartaruga','Quando este card for Invocado por Invocação-Normal ou Virar, você pode Invocar por Invocação-Especial qualquer número de "Dom Tartaruga" da sua mão.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3496543,'Despojos do Pecado da Floresta Branca',replace(replace('Se você controlar um monstro Demônio, Ilusão ou Mago: ative 1 desses efeitos;\r\n● Invoque por Invocação-Especial 1 monstro Demônio, Ilusão ou Mago da sua mão.\r\n● Invoque por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional, usando monstros da sua mão ou do campo.	\r\nSe este card for enviado para o Cemitério para ativar um efeito de monstro: você pode Baixar este card.\r\nVocê só pode usar cada efeito de "Despojos do Pecado da Floresta Branca" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar o efeito','Baixar','Invocar por Invocação Especial da mão','Invocação Fusão','','','','','','','','','','','','');
INSERT INTO texts VALUES(3507053,'Utensilhor Secadragonete',replace(replace('1 monstro "Utensilhor"	\r\nNão pode ser usado como Matéria Link no turno em que for Invocado por Invocação-Link. \r\nEste card linkado ganha 1000 de ATK. \r\nUma vez por turno, durante sua Fase de Batalha, se este card estiver co-linkado (exceto durante a Etapa de Dano): você pode trocar a posição de 2 monstros "Utensilhor" nas suas Zonas de Monstros Principais, incluindo este card e, se isso acontecer, o outro monstro pode realizar um segundo ataque durante cada Fase de Batalha neste turno. \r\nUma vez por turno, quando este card que não estiver co-linkado for escolhido como alvo de um ataque: você pode negar o ataque.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3510565,'Pássaro Camuflado',replace(replace('Uma vez por turno: você pode colocar este card com a face para baixo em Posição de Defesa. \r\nQuando este card for Invocado por Invocação-Virar: cause 1000 de dano ao seu oponente.','\r',char(13)),'\n',char(10)),'Mudar para Posição de Defesa com a face para baixo','Cause 1000 de dano ao seu oponente','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3519195,'Ataque Maligno',replace(replace('Descarte 1 card; pegue 1 monstro "HERÓI Maligno" de Nível 4 ou menos do seu Deck e adicione-o à sua mão ou Invoque-o por Invocação-Especial e, além disso, pelo resto deste turno depois que este card resolver, você não pode Invocar por Invocação-Especial do Deck Adicional, exceto monstros "HERÓI". \r\nSe este card estiver no seu Cemitério, exceto no turno em que foi enviado para lá: você pode banir este card do seu Cemitério; adicione 1 "Fusão Negra" do seu Cemitério à sua mão. \r\nVocê só pode usar cada efeito de "Ataque Maligno" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Recuperar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3534077,'Soldado Técnico Uivo de Lobo',replace(replace('Você pode escolher 1 monstro Besta-Guerreira de FOGO de Nível 4 no seu Cemitério; Invoque-o por Invocação-Especial em Posição de Defesa, mas negue seus efeitos. \r\nVocê só pode usar este efeito de "Soldado Técnico Uivo de Lobo" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3536537,'Hordeum Maligno Zahak','Se este card com a face para cima que você controla for destruído por um card do seu oponente (seja em batalha ou por um efeito de card) e enviado para o seu Cemitério: escolha 1 monstro de Nível 5 ou mais no campo Invocado por Invocação-Especial; destrua o alvo.','Destruir um monstro','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3544583,'Ovaidoso, a Essência da Vaidade','2 Monstros Normais','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3549275,'Jarro de Dados',replace(replace('VIRE: Os dois duelistas lançam um dado de 6 faces. \r\nO duelista que obtiver o menor resultado sofre dano igual ao resultado do oponente x 500. \r\nContudo, se o vencedor obteve um 6, o perdedor sofre 6000 de dano. \r\nEm caso de empate, os dois duelistas lançam novamente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3557275,'Poerio Branco','O mais orgulhoso de todos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3560069,'Latência',replace(replace('Se este card for adicionado do seu Cemitério à sua mão por um efeito de card: você pode Invocá-lo por Invocação-Especial da sua mão. \r\nSe este card Invocado desta forma for enviado para o Cemitério como Matéria Link: você pode comprar 1 card. \r\nVocê só pode usar cada efeito de "Latência" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3567660,'Volta Link',replace(replace('Escolha 1 Monstro Link que você controla na Zona de Monstros Adicional; mova esse monstro que você controla para uma Zona de Monstros Principal sua para a qual ele apontar e, depois, você pode enviar para o Cemitério cards do topo do seu Deck igual ao seu Valor Link. \r\nVocê só pode ativar 1 "Volta Link" por turno.','\r',char(13)),'\n',char(10)),'Mover para outra Zona','Escolha 1 card para mover','Enviar 1 card do seu Deck para o Cemitério?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3573512,'Espadachim de Landstar','Um amador com uma espada, este anjo guerreiro conta com os seus poderes misteriosos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3574681,'Regra de Ouro',replace(replace('(Este card deve ser sempre considerado como um card "Cristalino(a)".)	\r\nColoque 2 monstros "Fera Cristalina" do seu Deck com a face para cima na sua Zona de Magias & Armadilhas como Magias Contínuas e, depois, Invoque por Invocação-Especial 1 monstro "Fera Cristalina" da sua mão ou do Cemitério com um nome diferente que o desses cards e, se isso acontecer, equipe-o com este card. \r\nQuando este card deixar o campo, destrua esse monstro. \r\nVocê só pode ativar 1 "Regra de Ouro" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3576031,'Potencial Cristólico',replace(replace('Todos os monstros "Cristron" que você controla ganham 300 de ATK e DEF. \r\nUma vez por turno, durante a Fase Final: você pode comprar cards igual ao número de Monstros Sincro "Cristron" que você Invocou por Invocação-Sincro neste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3580032,'Merlin',replace(replace('Você só pode usar cada efeito de "Merlin" uma vez por turno.\r\n● Você pode oferecer este card como Tributo; Invoque por Invocação-Especial 1 monstro "Nobre Cavaleiro" do seu Deck.	\r\nVocê não pode Invocar monstros por Invocação-Especial no turno em que ativar este efeito, exceto monstros "Nobre Cavaleiro".\r\n● (Efeito Rápido): você pode banir este card do seu Cemitério; imediatamente depois que este efeito resolver, Invoque por Invocação-Sincro 1 Monstro Sincro "Nobre Cavaleiro" usando monstros que você controla.\r\n● (Efeito Rápido): você pode banir este card do seu Cemitério; imediatamente depois que este efeito resolver, Invoque por Invocação-Xyz 1 Monstro Xyz "Nobre Cavaleiro" usando monstros que você controla.','\r',char(13)),'\n',char(10)),'Invoque por Invocação Sincro 1 Monstro Sincro "Nobre Cavaleiro"','Invoque por Invocação Xyz 1 Monstro Xyz "Nobre Cavaleiro"','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3594985,'Draco Majespectro - Ryu',replace(replace('Escala de Pêndulo = 5\r\n[ Efeito de Pêndulo ]\r\nSe você tiver um card "Majespectro" ou "Dracossassino" na sua outra Zona de Pêndulo: você pode adicionar 1 card "Majespectro" do seu Deck à sua mão e, depois, você pode destruir 1 card na sua Zona de Pêndulo. \r\nVocê só pode usar este efeito de "Draco Majespectro - Ryu" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\n2 monstros de Nível 4	\r\nSe você puder Invocar por Invocação-Pêndulo de Nível 4, você pode Invocar este card com a face para cima do seu Deck Adicional por Invocação-Pêndulo. \r\nSe um ou mais monstros forem oferecidos como Tributo enquanto este card estiver no campo (exceto durante a Etapa de Dano): você pode desassociar 1 matéria deste card; Invoque por Invocação-Especial 1 monstro Mago de VENTO de Nível 6 ou menos do seu Deck. \r\nVocê só pode usar este efeito de "Draco Majespectro - Ryu" até duas vezes por turno. \r\nSe este card na Zona de Monstros for destruído em batalha ou por um efeito de card, ou oferecido como Tributo: você pode colocar este card na sua Zona de Pêndulo.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Invocar por Invocação Especial do Deck','Colocar na Zona de Pêndulo','Destruir 1 card na sua Zona de Pêndulo?','','','','','','','','','','','','');
INSERT INTO texts VALUES(3598351,'HERÓI Maligno Bolha Tóxica',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão), mas você não pode Invocar por Invocação-Especial pelo resto deste turno, exceto monstros "HERÓI". \r\nVocê só pode Invocar "HERÓI Maligno Bolha Tóxica" por Invocação-Especial uma vez por turno desta forma. \r\nSe este card for Invocado por Invocação-Especial e você controlar um Monstro de Fusão que deve ser Invocado por Invocação-Especial com "Fusão Negra": você pode comprar 2 cards. \r\nVocê só pode usar este efeito de "HERÓI Maligno Bolha Tóxica" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Comprar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3603242,'Triturador','Uma vez por turno: você pode enviar 1 monstro do Tipo Máquina da sua mão para o Cemitério e, depois, escolher 1 monstro que seu oponente controla com um Nível menor ou igual ao do monstro que foi enviado para o Cemitério; destrua o alvo.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3606209,'Aquele que Caça Almas','Esta perigosa criatura usa uma espada devoradora de almas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3606728,'Garota Gagaga',replace(replace('Você pode escolher 1 "Mago Gagaga" que você controla; o Nível deste card se torna o Nível atual desse monstro. \r\nUm Monstro Xyz que foi Invocado usando apenas este card e outros monstros "Gagaga" como matérias ganha este efeito.\r\n● Quando for Invocado por Invocação-Xyz: você pode escolher 1 monstro que seu oponente controla que foi Invocado por Invocação-Especial; o ATK dele se torna 0.','\r',char(13)),'\n',char(10)),'Alterar Nível','O ATK se torna 0','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3606729,'Garota Gagaga',replace(replace('Você pode escolher 1 "Mago Gagaga" que você controla; o Nível deste card se torna o Nível atual desse monstro. \r\nUm Monstro Xyz que foi Invocado usando apenas este card e outros monstros "Gagaga" como matérias ganha este efeito.\r\n● Quando for Invocado por Invocação-Xyz: você pode escolher 1 monstro que seu oponente controla que foi Invocado por Invocação-Especial; o ATK dele se torna 0.','\r',char(13)),'\n',char(10)),'Alterar Nível','O ATK se torna 0','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3611830,'Endymion, o Poderoso Mestre da Magia',replace(replace('Escala de Pêndulo = 8\r\n[ Efeito de Pêndulo ]\r\nVocê pode remover 6 Marcadores de Magia do seu campo; Invoque este card por Invocação-Especial da Zona de Pêndulo e, depois, conte o número de cards que você controla que podem ter Marcadores de Magia, destrua até esse número de cards no campo e, se isso acontecer, coloque Marcadores de Magia neste card igual ao número de cards destruídos. \r\nVocê só pode usar este efeito de "Endymion, o Poderoso Mestre da Magia" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nUma vez por turno, quando um Card ou efeito de Magia/Armadilha for ativado (Efeito Rápido): você pode devolver para a mão 1 card que você controla com um Marcador de Magia e, se isso acontecer, negue a ativação e, se isso acontecer, destrua-o. \r\nDepois, você pode colocar neste card o mesmo número de Marcadores de Magia que o card devolvido tinha. \r\nEnquanto este card tiver um Marcador de Magia, seu oponente não pode escolher este card como alvo de efeitos de card e, além disso, ele não pode ser destruído pelos efeitos de card do seu oponente. \r\nQuando este card com um Marcador de Magia for destruído em batalha: você pode adicionar 1 Magia Normal do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'','','Colocar um Marcador de Magia?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3627449,'Guardião Caveira',replace(replace('Este monstro só pode ser Invocado por Invocação-Ritual com o Card de Magia de Ritual "Oração de Novox". \r\nVocê também deve oferecer como Tributo monstros do campo ou da sua mão cuja soma dos Níveis seja igual a 7 ou mais.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3629090,'Ciber Anja Idaten',replace(replace('Você pode Invocar este card por Invocação-Ritual com "Ritual Máquina de Anjo". \r\nSe este card for Invocado por Invocação-Ritual: você pode adicionar 1 Magia de Ritual do seu Deck ou Cemitério à sua mão. \r\nSe este card for oferecido como Tributo: você pode fazer com que todos os Monstros de Ritual que você controla ganhem 1000 de ATK/DEF.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3635138,'Emissários das Trevas',replace(replace('Se você sofrer dando de batalha ou efeito: você pode Invocar por Invocação-Especial este card da sua mão, e se fizer, ganhe 2000 PV, então você pode aplicar 1 desses efeitos.\r\n● Invoque por Invocação-Especial 1 "Emissários das Trevas" da sua mão, Deck ou Cemitério.\r\n● Destrua até 2 monstros em Posição de Ataque que seu oponente controle.	\r\nDurante a Fase Final, se este card foi Invocado por Invocação-Especial neste turno: você pode escolher 1 Armadilha no seu Cemitério; Baixe-a.\r\nVocê só pode usar cada um dos efeitos de "Emissários das Trevas" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Baixar uma Armadilha','Invocação Especial','Efeito de destruição','Não fazer nada','','','','','','','','','','','');
INSERT INTO texts VALUES(3635139,'Emissários das Trevas',replace(replace('Se você sofrer dando de batalha ou efeito: você pode Invocar por Invocação-Especial este card da sua mão, e se fizer, ganhe 2000 PV, então você pode aplicar 1 desses efeitos.\r\n● Invoque por Invocação-Especial 1 "Emissários das Trevas" da sua mão, Deck ou Cemitério.\r\n● Destrua até 2 monstros em Posição de Ataque que seu oponente controle.	\r\nDurante a Fase Final, se este card foi Invocado por Invocação-Especial neste turno: você pode escolher 1 Armadilha no seu Cemitério; Baixe-a.\r\nVocê só pode usar cada um dos efeitos de "Emissários das Trevas" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Baixar uma Armadilha','Invocação Especial','Efeito de destruição','Não fazer nada','','','','','','','','','','','');
INSERT INTO texts VALUES(3642509,'Grande Tornado, o HERÓI do Elemento',replace(replace('1 monstro "HERÓI do Elemento" + 1 monstro de VENTO	\r\nDeve ser Invocado por Invocação-Fusão e não pode ser Invocado por Invocação-Especial de nenhuma outra forma. \r\nSe este card for Invocado por Invocação-Fusão: diminua pela metade o ATK e a DEF de todos os monstros com a face para cima que seu oponente controla atualmente.','\r',char(13)),'\n',char(10)),'Alterar ATK/DEF','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3643300,'O Pescador Lendário','Enquanto "Umi" estiver no campo, este card não é afetado por efeitos de Magia e não pode ser escolhido como alvo de ataques, mas isso não impede que seu oponente ataque você diretamente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3648368,'Examinador, Aliado da Justiça',replace(replace('Uma vez por turno: você pode descartar 1 card e, depois, escolha 1 monstro com a face para baixo em Posição de Defesa que seu oponente controla; coloque o alvo com a face para cima em Posição de Ataque. \r\n(Efeitos de monstros de Virar não são ativados.)','\r',char(13)),'\n',char(10)),'Mudar a posição de batalha','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3657444,'Cibervale',replace(replace('Você pode ativar 1 desses efeitos.\r\n● Quando este card for escolhido como alvo de um ataque: você pode banir este card; compre 1 card e, depois, encerre a Fase de Batalha.\r\n● Você pode escolher 1 monstro com a face para cima que você controla e este card; bana os dois alvos e, depois, compre 2 cards.\r\n● Você pode escolher 1 card no seu Cemitério; bana tanto este card quanto 1 card da sua mão e, depois, coloque o alvo no topo do Deck.','\r',char(13)),'\n',char(10)),'Banir este card, compre 1 card e termine a Fase de Batalha','Banir outros monstros e este card, compre 2 cartas','Banir cards da sua mão e este card, depois recupere cards do Cemitério','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3659803,'Fusão Sobrecarregada','Invoque por Invocação-Fusão 1 Monstro de Fusão Máquina de TREVAS do seu Deck Adicional, ao banir as Matérias de Fusão mencionadas nele do seu campo ou Cemitério.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3679218,'Cavaleira do Pesadelo Sereia',replace(replace('1 monstro "Cavaleiro(a) do Pesadelo", exceto "Cavaleira do Pesadelo Sereia"	\r\nSe este card for Invocado por Invocação-Link: você pode descartar 1 card; Invoque por Invocação-Especial 1 monstro "Cavaleiro(a) do Pesadelo" do seu Deck e, depois, se este card estava co-linkado quando este efeito foi ativado, você pode comprar 1 card. \r\nVocê só pode usar este efeito de "Cavaleira do Pesadelo Sereia" uma vez por turno. \r\nMonstros no campo perdem 1000 ATK/DEF, a não ser que eles estejam co-linkados.','\r',char(13)),'\n',char(10)),'','Comprar 1 card?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3682106,'Armadilha Dupla','Destrua 1 card com a face para cima no Campo que tem o efeito que anula efeitos de Cards de Armadilha.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3685372,'CXyz Engenhoca Marionete Maquinix Fanatix',replace(replace('3 monstros de Nível 9	\r\nSe este card for Invocado por Invocação-Especial: você pode adicionar 1 Armadilha "Marionete" do seu Deck à sua mão. \r\nVocê pode desassociar 1 matéria deste card; Invoque por Invocação-Especial 1 monstro de qualquer Cemitério no campo do seu oponente em Posição de Defesa. \r\nSe um ou mais monstros forem Invocados por Invocação-Especial no campo do seu oponente (exceto durante a Etapa de Dano): você pode escolher 1 deles; destrua-o e, se isso acontecer, cause dano ao seu oponente igual à metade do ATK original dele. \r\nVocê só pode usar cada efeito de "CXyz Engenhoca Marionete Maquinix Fanatix" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Invoque por Invocação Especial 1 monstro de qualquer Cemitério para o campo do seu oponente','Causar dano','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3693034,'Pousada Capital Karakuri',replace(replace('Escolha 1 monstro "Karakuri" que você controla e 1 Monstro de Efeito que seu oponente controla; mude a posição de batalha do seu monstro e, se isso acontecer, negue os efeitos desse monstro do oponente até o final deste turno. \r\nSe você controlar um ou mais monstros "Karakuri": você pode banir este card do seu Cemitério e, depois, escolha 1 monstro com a face para cima no campo; mude a posição de batalha desse monstro. \r\nVocê só pode ativar 1 "Pousada Capital Karakuri" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3701074,'Cura das Trevas','Quando seu oponente Invocar um ou mais monstros, ele ganha PV igual a metade do ATK de 1 dos monstros Invocados de sua escolha.','Ganhar PV','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3715284,'Condutor do Exército Senhormek Obbligato',replace(replace('Durante sua Fase Principal: você pode ativar este efeito; destrua este card e, se isso acontecer, Invoque por Invocação-Especial 2 monstros "Exército Senhormek" do seu Deck em Posição de Defesa, exceto "Condutor do Exército Senhormek Obbligato" e, além disso, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros Máquina. \r\nSe este card for enviado para o Cemitério: você pode ativar este efeito; durante a Fase Final deste turno, você pode causar 100 de dano ao seu oponente para cada monstro "Senhormek" que você controla. \r\nVocê só pode usar cada efeito de "Condutor do Exército Senhormek Obbligato" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3717252,'Besta Sombraneco',replace(replace('VIRE: Você pode comprar 2 cards e, depois, descarte 1 card.\r\nSe este card for enviado para o Cemitério por um efeito de card: você pode comprar 1 card. \r\nVocê só pode usar 1 efeito de "Besta Sombraneco" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Compre 2 card(s)','Compre 1 card(s)','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3723262,'Mago @Ignister',replace(replace('Se você controlar um monstro Ciberso que foi Invocado por Invocação-Especial do Deck Adicional: você pode escolher 1 monstro Ciberso de TREVAS no seu Cemitério; Invoque por Invocação-Especial tanto este card na sua mão quanto esse monstro em, Posição de Defesa, e, além disso, você não pode Invocar por Invocação-Especial pelo resto deste turno, exceto monstros Ciberso. \r\nVocê pode banir este card do seu campo ou Cemitério e, depois, escolha 1 monstro que seu oponente controla; mude sua posição de batalha. \r\nVocê só pode usar cada efeito de "Mago @Ignister" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Mudar a posição de batalha','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3732747,'Elemento da Água','Um espírito marinho que produz neblina para atrapalhar a visão do inimigo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3734202,'Árvore Sagrada de Naturia',replace(replace('Se este card for enviado para o Cemitério: adicione 1 card "Naturia" do seu Deck à sua mão, exceto "Árvore Sagrada de Naturia". \r\nVocê só pode usar 1 dos seguintes efeitos de "Árvore Sagrada de Naturia" por turno e apenas uma vez por turno.\r\n● Você pode oferecer como Tributo 1 monstro Inseto de TERRA; Invoque por Invocação-Especial 1 monstro Planta de TERRA de Nível 4 ou menos do seu Deck.\r\n● Você pode oferecer como Tributo 1 monstro Planta de TERRA; Invoque por Invocação-Especial 1 monstro Inseto de TERRA de Nível 4 ou menos do seu Deck.','\r',char(13)),'\n',char(10)),'Invoque por Invocação Especial 1 monstro Planta de TERRA','Invoque por Invocação Especial 1 monstro Inseto de TERRA','Procurar no Deck','Usar o efeito?','','','','','','','','','','','','');
INSERT INTO texts VALUES(3739500,'Governante do Fim do Mundo',replace(replace('Você pode Invocar este card por Invocação-Ritual com um card "Fim do Mundo". \r\nO nome deste card se torna "Demise, o Rei do Armagedom" enquanto estiver na mão ou no campo. \r\nVocê só pode usar cada um dos seguintes efeitos de "Governante do Fim do Mundo" uma vez por turno. \r\nVocê pode revelar este card na sua mão, pagar 2000 PV e, depois, banir 1 Magia de Ritual do seu Deck; aplique o efeito de ativação desse card que Invoca um monstro por Invocação-Ritual. \r\nVocê pode pagar 2000 PV; destrua todos os outros cards no campo e, depois, este card ganha 2900 de ATK.','\r',char(13)),'\n',char(10)),'Copiar Ritual','Efeito de destruição','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3743515,'Sabressauro Agitado',replace(replace('2 monstros de Nível 4	\r\nVocê pode desassociar 1 matéria deste card; destrua 1 monstro Dinossauro na sua mão ou no campo com a face para cima e, depois, você pode mudar a posição de batalha de 1 monstro no campo. \r\nNo começo da Etapa de Dano, se outro monstro Dinossauro seu batalhar: você pode destruir este card e, se isso acontecer, esse monstro Dinossauro ganha 2000 de ATK até o final da Fase de Batalha. \r\nVocê só pode usar cada efeito de "Sabressauro Agitado" uma vez por turno.','\r',char(13)),'\n',char(10)),'Destruir','Destruir e aumentar ATK','Mudar a posição de batalha?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3752422,'Siniveleiro Camarartista',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno: você pode aumentar em 1 os Níveis de todos os monstros Invocados por Invocação-Pêndulo que você controla atualmente (mesmo que este card deixe o campo).\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nUma vez por turno: você pode declarar um Nível de 1 a 5 e, depois, escolher 1 outro monstro "Camarartista" que você controla; até o final deste turno, reduza o Nível deste card pelo Nível declarado e, se isso acontecer, aumente o Nível do outro monstro pelo mesmo valor.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3758046,'D/D/D César, o Rei das Ondas',replace(replace('2 monstros do Tipo Demônio de Nível 4	\r\nDurante o turno de qualquer duelista: você pode desassociar 1 Matéria Xyz deste card; no final da Fase de Batalha, Invoque por Invocação-Especial do seu Cemitério tantos monstros destruídos neste turno quanto possível, mas durante a próxima Fase de Apoio, sofra 1000 de dano para cada monstro Invocado por Invocação-Especial por este efeito. \r\nSe este card for enviado do campo para o Cemitério: você pode adicionar 1 card "Pacto Obscuro" do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "D/D/D César, o Rei das Ondas" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invoque por Invocação Especial o monstro destruído neste turno no final da Fase de Batalha','Procurar no Deck','Receber dano','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3773196,'Avião de Reconhecimento de D. D.',replace(replace('Durante a Fase Final, se este card atualmente estiver banido e foi banido neste turno: Invoque-o por Invocação-Especial com a face para cima em Posição de Ataque. \r\nEste efeito só pode ser ativado uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3775068,'Indiora Volt Mortal, o Imperador Cúbico',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao enviar 3 monstros "Cúbico(a)" que você controla para o Cemitério e não pode ser Invocado por Invocação-Especial de nenhuma outra forma. \r\nSe Invocado desta forma, este card ganha 2400 de ATK. \r\nSe este card for Invocado por Invocação-Especial da mão: cause 800 de dano ao seu oponente. \r\nSe este card em sua posse for enviado para o seu Cemitério por um card do seu oponente (em batalha ou por um efeito de card): você pode escolher até 3 monstros "Cúbico(a)" no seu Cemitério; Invoque-os por Invocação-Especial e, depois, você pode adicionar 1 card "Cúbico(a)" do seu Deck ou Cemitério à sua mão.','\r',char(13)),'\n',char(10)),'Dano de efeito','Invoque por Invocação Especial 1 monstro do Cemitério','Adicionar à sua mão 1 card "Cúbico(a)"?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3779493,'Administrador do Fim da Noite',replace(replace('"Feiticeiro do Fim da Noite" + 1+ monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Especial, ou se um ou mais outros monstros Mago forem Invocados por Invocação-Especial no seu campo: você pode escolher 1 card no Cemitério do seu oponente; bana-o. \r\nSe este card for destruído em batalha, ou se este card na Zona de Monstros do seu dono for destruído por um efeito de card do oponente: você pode escolher 1 monstro Mago de Nível 4 ou menos no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê só pode usar este efeito de "Administrador do Fim da Noite" uma vez por turno.','\r',char(13)),'\n',char(10)),'Banir cards do Cemitério do seu oponente','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3779662,'Besta Gladiadora Andabata',replace(replace('"Besta Gladiadora Augustus" + 2 monstros "Besta Gladiadora"	\r\nPrimeiro deve ser Invocado por Invocação-Especial (do seu Deck Adicional) ao embaralhar os cards acima que você controla no Deck. \r\n(Você não usa "Polimerização".) \r\nSe Invocado desta forma: você pode Invocar por Invocação-Especial 1 Monstro de Fusão "Besta Gladiadora" de Nível 7 ou menos do seu Deck Adicional, ignorando suas condições de Invocação. \r\nNo final da Fase de Batalha, se este card batalhar: você pode devolvê-lo ao Deck Adicional; Invoque por Invocação-Especial 2 monstros "Besta Gladiadora" do seu Deck.','\r',char(13)),'\n',char(10)),'','Invocação Especial','Escolha "Besta Gladiadora"','Escolha 1 monstro "Besta Gladiadora"','','','','','','','','','','','','');
INSERT INTO texts VALUES(3784434,'Rinoceronte Arrasador',replace(replace('Uma vez por turno, este card pode ser movido para uma Zona de Cards de Monstro adjacente (horizontal) não ocupada. \r\nSe este card atacar o monstro na mesma coluna, este card ganha 500 de ATK durante a Etapa de Dano.','\r',char(13)),'\n',char(10)),'Mover para outra Zona','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3790062,'Número 65: Djinn Notável',replace(replace('2 monstros de TREVAS de Nível 2	\r\nQuando seu oponente ativar um efeito de monstro (Efeito Rápido): você pode desassociar 2 matérias deste card; negue a ativação e, se isso acontecer, cause 500 de dano ao seu oponente.','\r',char(13)),'\n',char(10)),'Negue a ativação e cause dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3792766,'Trapestrela Explofiendium',replace(replace('2+ monstros "Trapestrela"	\r\nQuando este card declarar um ataque enquanto estiver apontando para um monstro "Trapestrela": você pode escolher seus cards "Trapestrela" banidos, até o número de Monstros Link que seu oponente controla; adicione-os à sua mão e, se isso acontecer, até o final deste turno, este card ganha 1000 de ATK para cada card adicionado.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3797883,'Caça-Níquel','Dizem que a habilidade desta máquina varia de acordo com os seus resultados.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3806388,'Núcleo Feito de Caos',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial por um efeito de card. \r\nSe este card com a face para cima deixaria o campo, em vez disso, bana-o. \r\nVocê só pode usar cada um dos seguintes efeitos de "Núcleo Feito de Caos" uma vez por turno. \r\nVocê pode banir 1 monstro de TREVAS da sua mão ou do Cemitério; Invoque este card por Invocação-Especial da sua mão e, além disso, você não pode Invocar monstros por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto Monstros Sincro de LUZ ou de TREVAS. \r\nSe este card for Invocado por Invocação-Especial: você pode escolher 1 dos seus "Concha do Caos" banidos; Invoque-o por Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3810071,'Monge Lutador','Dano de combate que o controlador deste card receba de um combate que envolva este card torna-se 0.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3814632,'Palácio Celeste Gangaridai',replace(replace('2 monstros de Nível 10	\r\nVocê pode desassociar 1 matéria deste card e, depois, escolha 1 card que seu oponente controla; destrua o alvo e, se isso acontecer, cause 1000 de dano ao seu oponente. \r\nVocê só pode usar o efeito de "Palácio Celeste Gangaridai" uma vez por turno. \r\nNão pode atacar no turno em que você ativar este efeito.','\r',char(13)),'\n',char(10)),'Destrua e cause dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3819470,'Sete Ferramentas do Bandido','Quando um Card de Armadilha for ativado: pague 1000 PV; negue a ativação e, se isso acontecer, destrua-o.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3825890,'Visionário do Coveiro',replace(replace('Você pode Invocar este card por Invocação-Tributo ao oferecer como Tributo 1 monstro "do Coveiro". \r\nEste card ganha 200 de ATK para cada monstro "do Coveiro" no seu Cemitério. \r\nSe este card com a face para cima seria destruído, em vez disso, você pode descartar 1 monstro "do Coveiro".','\r',char(13)),'\n',char(10)),'Invoque por Tributo usando um monstro cujo nome contém "Coveiro"','Usar o efeito de substituição de destruição de "Visionário do Coveiro"?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3828844,'Strenna, a Rainha Rikka',replace(replace('2 monstros de Nível 4	\r\nVocê pode desassociar 1 matéria deste card e, depois, escolha 1 monstro Planta ou card "Rikka" no seu Cemitério; adicione-o à sua mão. \r\nSe este card com Matéria Xyz for oferecido como Tributo: você pode Invocar por Invocação-Especial 1 Monstro Xyz Planta de Classe 5 ou mais do seu Deck Adicional ou Cemitério e, depois, você pode associar este card a ele como matéria. \r\nVocê só pode usar cada efeito de "Strenna, a Rainha Rikka" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Sobrepor este card como Matéria Xyz?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3837261,'Guerreiro Dragônico',replace(replace('Você pode descartar 1 card; Invoque por Invocação-Especial 1 monstro Dragão de Nível 4 ou menos da sua mão ou do Deck, exceto "Guerreiro Dragônico", mas negue seus efeitos. \r\nVocê só pode usar este efeito de "Guerreiro Dragônico" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3841104,'Destratificação Dino Stratiae',replace(replace('2 monstros, incluidno um monstro Dinossauro	\r\nSe este card for Invocado por Invocação-Link: você pode fazer este card ganhar ATK igual a metado do ATK total original dos monstros Dinossauros usados como sua matéria.\r\nDurante sua Fase Principal: você pode Invocar por Invocação-Fusão 1 Monstro Fusão Dinossauro do seu Deck Adicional, banindo suas matérias do seu campo e/ou Cemitério, você também não pode Invocar por Invocação-Especial do seu Deck Adicional pelo resto desse turno, exceto monstros Dinossauro. \r\nVocê só pode usar este efeito de "Destratificação Dino Stratiae" uma vez por turno.','\r',char(13)),'\n',char(10)),'Aumentar ATK','Invocação Fusão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3841833,'Fofanimal Urso',replace(replace('Você pode enviar este card da sua mão para o Cemitério; baixe 1 "Vendedor de Brinquedos" diretamente do seu Deck na sua Zona de Magias & Armadilhas. \r\nVocê pode oferecer este card como Tributo e, depois, escolher 1 "Polimerização" no seu Cemitério; adicione-o à sua mão. \r\nVocê só pode usar 1 efeito de "Fofanimal Urso" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Procurar no Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3846170,'Soldado Karakuri mod. 236 "Nisamu"',replace(replace('Este card deve atacar, se possível. \r\nQuando este card com a face para cima em Posição de Ataque for selecionado como alvo de um ataque, mude-o para Posição de Defesa. \r\nQuando este card for destruído em batalha e enviado ao Cemitério, você pode Invocar por Invocação-Especial 1 monstro "Karakuri" de Nível 4 ou menos do seu Deck com a face para cima em Posição de Ataque.','\r',char(13)),'\n',char(10)),'Mudar para Posição de Defesa','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3859859,'Camarartista Pequena Maga do Céu',replace(replace('Se você controlar uma Magia Contínua: você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe este card for Invocado por Invocação-Especial da mão: você pode enviar 1 monstro Mago de LUZ de Nível 4 ou menos do seu Deck para o Cemitério. \r\nSe este card com a face para cima deixar o campo: você pode escolher 1 Magia/Armadilha no campo; destrua-o. \r\nVocê só pode usar cada efeito de "Camarartista Pequena Maga do Céu" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3868277,'TGX3-DX2','Escolha 3 monstros "T.G." no seu Cemitério; embaralhe os 3 no seu Deck e, depois, compre 2 cards.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3875465,'Mundo Eletrolírico Utensilhor',replace(replace('Quando este card for ativado: você pode adicionar 1 card "Utensilhor" do seu Deck à sua mão, exceto uma Magia de Campo. \r\nUma vez por turno, se você Invocar por Invocação-Link um ou mais Monstros Link "Utensilhor": você pode adicionar 1 monstro "Utensilhor" do seu Cemitério à sua mão. \r\nUma vez por turno, quando um monstro declarar um ataque: você pode mover 1 monstro "Utensilhor" que você controla para outra das suas Zonas de Monstros Principais. \r\nVocê só pode ativar 1 "Mundo Eletrolírico Utensilhor" por turno.','\r',char(13)),'\n',char(10)),'Adicionar "Utensilhor" do seu Deck à sua mão?','','','Escolha 1 monstro para mover','','','','','','','','','','','','');
INSERT INTO texts VALUES(3891471,'Afinação Psíquica',replace(replace('Escolha 1 monstro do Tipo Psíquico no seu Cemitério e Invoque-o por Invocação-Especial em Posição de Ataque. \r\nEle é considerado como um monstro Regulador. \r\nQuando este card for removido do campo, destrua esse monstro. \r\nQuando esse monstro for removido do campo, destrua este card. \r\nQuando este card for enviado para o Cemitério, sofra dano igual ao Nível desse monstro x 400.','\r',char(13)),'\n',char(10)),'Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3897065,'Super Veicroide - União Furtiva',replace(replace('"Caminharoide" + "Expressoroide" + "Perfuroide" + "Furtivoroide"	\r\nUma vez por turno: você pode escolher 1 monstro não-Máquina com a face para cima no campo; equipe o alvo a este card. \r\nEnquanto estiver equipado com um monstro por este efeito, este card pode atacar todos os monstros que seu oponente controla, uma vez cada. \r\nSe este card atacar, seu ATK original é diminuído pela metade. \r\nSe este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante.','\r',char(13)),'\n',char(10)),'Equipar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3900605,'Jarra da Absorção',replace(replace('VIRE: Destrua todas as Magias/Armadilhas Baixadas no campo e, depois, cada duelista compra 1 card para cada card que ele controlava que foi destruído por este efeito. \r\nVocê não pode Baixar nenhum card neste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3909436,'Senhor da Batalha Vendorror',replace(replace('Você pode Invocar este card por Invocação-Ritual com qualquer Magia de Ritual "Vendorror". \r\nVocê pode banir 1 card "Vendorror" do seu Cemitério e declarar 1 tipo de card (Monstro, Magia ou Armadilha); pelo resto deste turno, seu oponente não pode ativar cards ou efeitos desse tipo. \r\nSe este card Invocado por Invocação-Ritual for enviado para o Cemitério: você pode adicionar 1 Monstro de Ritual do seu Deck à sua mão e, se isso acontecer, envie 1 monstro "Vendorror" do seu Deck para o Cemitério. \r\nVocê só pode usar cada efeito de "Senhor da Batalha Vendorror" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3912064,'O Saltitante Mercúrio',replace(replace('Quando este card for Invocado por Invocação-Tributo: você pode colocar todos os monstros no campo com a face para cima em Posição de Ataque. \r\nVocê pode oferecer 3 monstros como Tributo para Invocar este card por Invocação-Tributo (mas não para Baixar). \r\nSe Invocado desta forma, enquanto este card estiver no campo, todos os monstros que seu oponente controla perdem ATK igual aos seus próprios ATK originais. \r\nEste card pode realizar um segundo ataque durante cada Fase de Batalha.','\r',char(13)),'\n',char(10)),'Ofereça 3 monstros como Tributo para Invocar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3918345,'Limo Mágico Refletor',replace(replace('Este card é considerado como um Monstro Normal enquanto estiver com a face para cima no campo ou no Cemitério. \r\nEnquanto este card for um Monstro Normal no campo, você pode Invocá-lo por Invocação-Normal para fazer com que ele se torne um Monstro de Efeito com este efeito.\r\n● Seu oponente sofre qualquer dano de batalha que você teria sofrido das batalhas envolvendo este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3954901,'Dragão Felgrand',replace(replace('Não pode ser Invocado por Invocação-Especial, exceto do Cemitério, e apenas se ele foi enviado para lá do campo. \r\nSe este card for Invocado por Invocação-Especial: escolha 1 monstro no seu Cemitério; este card ganha ATK igual ao Nível desse monstro x 200.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3957130,'Dragão Tricallibre',replace(replace('2+ monstros Dragão de TREVAS, incluindo um monstro "Foguette"	\r\nSe este card for Invocado por Invocação-Link: você pode adicionar 1 "Gatilho Rápido", "Interconector Pesado" ou "Interconector Duplo" do seu Deck à sua mão. \r\nVocê pode escolher 1 card com a face para cima que você controla e 1 monstro Dragão de TREVAS no seu Cemitério; destrua esse card no campo e, se isso acontecer, adicione o outro monstro do seu Cemitério à sua mão. \r\nVocê só pode usar cada efeito de "Dragão Tricallibre" uma vez por turno.','\r',char(13)),'\n',char(10)),'Efeito de busca','Efeito de recuperação','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3966653,'Flor Cardian Javerveta',replace(replace('1 Regulador + 2 monstros não-Reguladores	\r\nSe um monstro "Flor Cardian" que você controla atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente. \r\nUma vez por turno: você pode banir 1 monstro "Flor Cardian" do seu Cemitério; até o final do próximo turno do seu oponente, seu oponente não pode ativar efeitos de cards no Cemitério e, além disso, ele não pode Invocar monstros por Invocação-Especial do Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3972721,'Grado Ganancioso',replace(replace('Só pode ser ativado se você destruiu um Monstro Sincro com a face para cima que seu oponente controla neste turno, seja em batalha ou por um efeito de card. \r\nCompre 2 cards.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3985011,'Berloque da Sorte','Essa criatura pode parecer magra e fraca, mas é protegida por uma força mística.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3987233,'Missis Radiante',replace(replace('2 monstros de TERRA	\r\nTodos os monstros de TERRA no campo ganham 500 de ATK e DEF e, além disso, todos os monstros de VENTO no campo perdem 400 de ATK e DEF. \r\nSe este card for destruído em batalha ou por um efeito de card: você pode escolher 1 monstro de TERRA no seu Cemitério; adicione-o à sua mão. \r\nVocê só pode usar este efeito de "Missis Radiante" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(3989465,'Ignis Lavalval',replace(replace('2 monstros de Nível 3	\r\nSe este card atacar ou for atacado, durante a Etapa de Dano (no turno de qualquer duelista): uma vez por batalha, você pode desassociar 1 Matéria Xyz deste card; este card ganha 500 de ATK ate o final deste turno.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4008212,'Romper o Destino',replace(replace('Escolha 1 monstro "HERÓI do Destino" de Nível 8 ou mais ou 1 "Dragoon do Destino Final" que você controla; destrua-o e, se isso acontecer, seu oponente pula sua próxima Fase Principal 1. \r\nVocê pode banir este card do seu Cemitério; adicione 1 Magia/Armadilha do seu Deck à sua mão que liste especificamente um nome de card de monstro "HERÓI do Destino" ou "Dragoon do Destino Final" em seu texto, exceto "Romper o Destino". \r\nVocê só pode usar 1 efeito de "Romper o Destino" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4017398,'Confiança Zexal',replace(replace('Escolha 1 monstro "Utopia", "ZW -" ou "ZS -" no seu Cemitério; adicione-o à sua mão ou Invoque-o por Invocação-Especial. \r\nSe os PV do seu oponente forem pelo menos 2000 a mais que os seus, exceto no turno em que este card foi enviado para o Cemitério: você pode banir este card do seu Cemitério e, depois, escolha 1 Magia/Armadilha "Zexal" no seu Cemitério, exceto "Confiança Zexal"; adicione-o à sua mão. \r\nVocê só pode usar cada efeito de "Confiança Zexal" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4019153,'Número 4: Portão Numeron Catvari',replace(replace('3 monstros de Nível 1	\r\nNão pode ser destruído em batalha. \r\nNo final da Etapa de Dano, se este card batalhou um monstro do oponente: você pode desassociar 1 matéria deste card; até o final deste turno, dobre o ATK de todos os monstros "Numeron" que você controla atualmente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4022819,'Dragão Hierático de Eset',replace(replace('Você pode Invocar este card por Invocação-Normal sem oferecer Tributo, mas seu ATK original se torna 1000. \r\nUma vez por turno: você pode escolher 1 Monstro Normal Dragão com a face para cima no campo; até a Fase Final, o Nível de todos os monstros "Hierático" com a face para cima atualmente no campo se tona o Nível desse monstro. \r\nQuando este card for oferecido como Tributo: Invoque por Invocação-Especial 1 Monstro Normal Dragão da sua mão, do Deck ou do Cemitério e torne seu ATK/DEF 0.','\r',char(13)),'\n',char(10)),'Invocação Normal sem Tributo','Alterar Nível','Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4026187,'Contadora de Cauda de Fadas',replace(replace('1 monstro "Cauda de Fadas" de LUZ + 1 monstro Mago	\r\nMonstros "Cauda de Fadas" que você controla não podem ser destruídos em batalha. \r\nVocê só pode usar cada um dos seguintes efeitos de "Contadora de Cauda de Fadas" uma vez por turno. \r\nSe este card for Invocado por Invocação-Fusão usando "Príncipe das Fadas" como matéria: você pode destruir tantos cards que seu oponente controla quanto possível e, se isso acontecer, cause 500 de dano ao seu oponente para cada card destruído. \r\nQuando seu oponente ativar um card ou efeito (Efeito Rápido): você pode banir 1 card "Cauda de Fadas" da sua mão ou do Cemitério; negue a ativação e, se isso acontecer, destrua esse card.','\r',char(13)),'\n',char(10)),'Efeito de destruição','Negar a ativação','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4031928,'Mudança de Opinião','Escolha 1 monstro que seu oponente controla; tome o controle dele até a Fase Final.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4035199,'Borboletal','Uma gravata borboleta com poderes horríveis, ataca um oponente controlando os outros.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4041838,'Mestre Ninja Sasuke','No começo da Etapa de Dano, se este card atacar um monstro com a face para cima em Posição de Defesa: destrua esse monstro.','Destruir um monstro em Posição de Defesa com a face para cima','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4042268,'Tartaruga Ilha','Uma tartaruga enorme muitas vezes confundida com uma ilha.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4055337,'Cavaleira do Pesadelo Orcust',replace(replace('Não pode ser destruído em batalha com um Monstro Link. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 monstro com a face para cima no campo; pelo resto deste turno, você não pode Invocar por Invocação-Especial, exceto monstros de TREVAS e, além disso, envie 1 monstro Máquina de TREVAS do seu Deck para o Cemitério, exceto "Cavaleira do Pesadelo Orcust" e, se isso acontecer, até o final deste turno, o monstro alvo ganha ATK igual ao Nível do monstro enviado para o Cemitério x 100. \r\nVocê só pode usar este efeito de "Cavaleira do Pesadelo Orcust" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4058065,'Hordeum Maligno Salamandra','Até duas vezes por turno: você pode banir 1 monstro do seu Cemitério; este card ganha 300 de ATK até o final do turno do seu oponente.','Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4059313,'Canhão de Explosão',replace(replace('(Este card deve ser sempre considerado como um card "Acelerador de Explosão".)	\r\nUm "O Dragão Alado de Rá" que você controla ganha os seguintes efeitos até o final deste turno. \r\nA ativação e efeito deste card não podem ser negados.\r\n● Este card não é afetado pelos efeitos de card do seu oponente.\r\n● Quando um ataque for declarado envolvendo este card: você pode oferecer como Tributo qualquer número de outros monstros que não declararam um ataque neste turno; até o final deste turno, este card ganha ATK igual ao ATK original combinado desses monstros oferecidos como Tributo.\r\n● Depois do cálculo de dano, se este card atacou: você pode enviar para o Cemitério todos os monstros que seu oponente controla.','\r',char(13)),'\n',char(10)),'O efeito de "Canhão de Explosão" está sendo aplicado.','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4063756,'Medicurius o Patrono do Poder das Ilusões',replace(replace('2+ monstros, incluindo um Monstro Fusão, Sincro, Xyz ou Link	\r\nGanha estes efeitos baseado no número de monstros para qual aponta.\r\n● 1+: Uma vez por turno: você pode negar os efeitos de todos os monstros com a face para cima que seu oponente atualmente controla, também até o final deste turno, os ATKs deles são reduzidos.\r\n● 2+: Não é afetado pelos efeitos ativados do seu oponente.\r\n● 3: Uma vez por turno do oponente (Efeito Rápido): você pode banir este card, também bana todos os cards que seu oponente controla.','\r',char(13)),'\n',char(10)),'Negar o efeito','Efeito de banimento','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4064256,'Mundo Zumbi',replace(replace('Todos os monstros no campo e nos Cemitérios se tornam monstros Zumbi. \r\nNenhum duelista pode Invocar monstros por Invocação-Tributo, exceto monstros Zumbi.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4064925,'Avanço do Mecanismo Antigo',replace(replace('Quando este card for ativado: adicione 1 Magia/Armadilha "Mecanismo Antigo" do seu Deck à sua mão, exceto "Avanço do Mecanismo Antigo". \r\nUma vez por turno: você pode oferecer 1 monstro como Tributo; compre 1 card e aplique este efeito pelo resto deste turno (mesmo que este card deixe o campo).\r\n● Você pode Invocar por Invocação-Normal "Golem do Mecanismo Antigo", ou monstros de Nível 5 ou mais que o mencionem, sem oferecer Tributo.	\r\nVocê não pode Baixar cards no turno em que ativar este card. \r\nVocê só pode ativar 1 "Avanço do Mecanismo Antigo" por turno.','\r',char(13)),'\n',char(10)),'Tribute 1 monstro e compre 1 carta','','Invocar pelo efeito de "Avanço do Mecanismo Antigo"','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4068622,'Asanegra - Aurora, as Luzes do Norte',replace(replace('Não pode ser Invocado por Invocação-Especial/Baixado. \r\nVocê deve Invocá-lo por Invocação-Especial (da sua mão) ao banir 2 monstros com a face para cima que você controla (1 Regulador "Asanegra" e 1 não-Regulador) e não pode Invocá-lo por Invocação-Especial de nenhuma outra forma. \r\nUma vez por turno: você pode banir 1 Monstro Sincro "Asanegra" do seu Deck Adicional; até a Fase Final, o nome e o ATK original deste card se tornam o desse monstro e substitua este efeito pelos efeitos originais desse monstro.','\r',char(13)),'\n',char(10)),'Obter um efeito de monstro','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4072687,'Resultado Inaceitável','Se você controlar um monstro Mago: Invoque por Invocação-Especial 1 monstro "Fada Fortuna" da sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4079728,'Vamos Nessa, Springans!',replace(replace('2+ monstros "Springans" de Nível 4	\r\nSe este card for Invocado por Invocação-Xyz ou enviado para o Cemitério: você pode Invocar por Invocação-Especial 1 "Springans Capitão Sargas" do seu Deck ou Cemitério. \r\nVocê pode desassociar 2 matérias deste card; adicione à sua mão ou Invoque por Invocação-Especial 1 dos seguintes monstros do seu Deck.\r\n● Monstro "Springans"\r\n● Monstro "Therion"\r\n● "Caído de Arbaz" ou 1 monstro que o mencione\r\nVocê só pode usar 1 efeito de "Vamos Nessa, Springans!" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Efeito de busca','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4081094,'O Segundo Sarcófago','Este card só pode ser colocado no campo pelo efeito de "O Primeiro Sarcófago".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4081665,'Camaramágico Lançador Perna de Pau',replace(replace('Se não houver monstros no campo, você pode Invocar este card por Invocação-Especial (da sua mão), mas você não pode Invocar por Invocação-Normal/Baixar pelo resto deste turno. \r\nDurante o turno de qualquer duelista, quando um card ou efeito for ativado que causaria dano ao seu oponente, enquanto você tiver outro monstro "Camaramágico" no seu Cemitério: você pode banir este card do seu Cemitério; cause 2000 de dano ao seu oponente. \r\nVocê só pode usar este efeito de "Camaramágico Lançador Perna de Pau" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4081825,'Infinidade do Caos','Coloque com a face para cima em Posição de Ataque tantos monstros que estão em Posição de Defesa no campo quanto possível e, depois, Invoque por Invocação-Especial 1 monstro "Senhormek" do seu Deck ou Cemitério, mas seus efeitos são negados e, além disso, ele é destruído durante a Fase Final.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4103668,'Tengu, o Mayakashi Alado',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nVocê só pode controlar 1 "Tengu, o Mayakashi Alado". \r\nVocê só pode usar cada um desses efeitos de "Tengu, o Mayakashi Alado" uma vez por turno.\r\n● Se um Monstro Sincro em sua posse, cujo Nível original seja 9, for destruído em batalha ou por um efeito de card do oponente enquanto este card estiver no Cemitério: você pode banir 1 outro monstro Zumbi no seu Cemitério e, se isso acontecer, Invoque este card por Invocação-Especial.\r\n● Se este card for Invocado por Invocação-Especial do Cemitério: você pode destruir 1 Magia/Armadilha que seu oponente controla.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4130270,'Caçadora G.B.','Cards no campo não podem ser devolvidos para o Deck.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4141820,'Djinn, o Prognosticador de Rituais',replace(replace('Quando você Invocar um monstro por Invocação-Ritual, você pode banir este card do seu Cemitério como 1 dos monstros necessários para a Invocação-Ritual. \r\nSe você Invocar por Invocação-Ritual usando este card, se esse monstro Invocado por Invocação-Ritual causar dano de batalha ao seu oponente, ele descarta 1 card.','\r',char(13)),'\n',char(10)),'O efeito de "Djinn, o Prognosticador de Rituais" está sendo aplicado.','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4145852,'Carneríete Zoodíaco',replace(replace('Se este card for destruído em batalha ou por um efeito de card: você pode escolher 1 monstro "Zoodíaco(a)" no seu Cemitério, exceto "Carneríete Zoodíaco"; Invoque-o por Invocação-Especial. \r\nUm Monstro Xyz cujo Tipo original seja Besta-Guerreira e que tenha este card como matéria ganha este efeito.\r\n● Quando seu oponente ativar um Card ou efeito de Armadilha que escolha este card como alvo (Efeito Rápido): você pode desassociar 1 matéria deste card; negue a ativação.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial 1 monstro "Zoodíaco(a)" do seu Cemitério','Negar a ativação de um efeito de Armadilha (Carneríete Zoodíaco)','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4145915,'Engenhoca Marionete Cavaleiro Demoníaco',replace(replace('Se este card estiver na sua mão: você pode escolher 1 monstro "Engenhoca Marionete" no seu Cemitério ou 1 monstro no Cemitério do seu oponente; Invoque-o por Invocação-Especial no campo do seu dono em Posição de Defesa, mas seus efeitos são negados e, depois, Invoque este card por Invocação-Especial. \r\nSe este card for enviado para o Cemitério, exceto da mão: você pode adicioná-lo à sua mão. \r\nVocê só pode usar cada efeito de "Engenhoca Marionete Cavaleiro Demoníaco" uma vez por turno e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional no turno em que ativar qualquer um dos efeitos deste card, exceto monstros "Engenhoca Marionete".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4148264,'Esquadrão Negro Brilhante "B"','Onde quer que haja sombras, você encontrará o Esquadrão "B"! Sua habilidade oculta de voo permite que ele confronte os gigantes de igual para igual!','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4149689,'Leque Goblin',replace(replace('Quando um monstro de Nível 2 ou menos for Invocado por Invocação-Virar, destrua-o. \r\nOs efeitos dele não serão ativados nesse momento.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4160316,'Laços de Centur-Ião',replace(replace('Coloque 1 monstro "Centur-Ião" da sua mão ou do Cemitério na sua Zona de Magias & Armadilhas como uma Armadilha Contínua com a face para cima. \r\nSe um ou mais Monstros Sincro "Centur-Ião" forem Invocados por Invocação-Especial no seu campo, enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode banir este card e, depois, escolha 1 monstro "Centur-Ião" no seu Cemitério; coloque-o na sua Zona de Magias & Armadilhas como uma Armadilha Contínua com a face para cima. \r\nVocê só pode usar cada efeito de "Laços de Centur-Ião" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4162088,'Dragão Ciberlaser',replace(replace('Este card não pode ser Invocado por Invocação-Normal ou Baixado. \r\nEste card não pode ser Invocado por Invocação-Especial, exceto com "Unidade de Geração de Fótons". \r\nUma vez por turno, você pode destruir 1 monstro com ATK ou DEF igual ou maior que o ATK deste card.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4167084,'O Primeiro Senhor Obscuro',replace(replace('3 monstros Fada de TREVAS	\r\nSeu oponente não pode escolher monstros Fada que você controla como alvo de efeitos de card. \r\nVocê só pode usar 1 dos seguintes efeitos de "O Primeiro Senhor Obscuro" por turno e apenas uma vez por turno. \r\nSe este card for Invocado por Invocação-Fusão usando "Senhor Obscuro Estrela da Manhã" como matéria: você pode destruir todos os cards que seu oponente controla. \r\nDurante a Fase Principal (Efeito Rápido): você pode pagar 1000 PV; Invoque por Invocação-Especial 1 monstro Fada da sua mão ou do Cemitério em Posição de Defesa.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4168871,'Cards por Penas Negras',replace(replace('Bana 1 monstro "Asanegra" da sua mão; compre 2 cards. \r\nVocê não pode Invocar por Invocação-Especial durante o turno em que ativar este card. \r\nVocê só pode ativar 1 "Cards por Penas Negras" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4178474,'Fratura Raigeki','Descarte 1 card e, depois, escolha 1 card no campo; destrua-o.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4179255,'Dragão Pixie Antigo',replace(replace('1 Regulador + 1 ou mais monstros não-Reguladores	\r\nDespois de resolver um Card de Magia de Campo que foi ativado durante o seu turno: compre 1 card. \r\nVocê só pode usar este efeito de "Dragão Pixie Antigo" uma vez por turno. \r\nUma vez por turno: você pode escolher 1 monstro com a face para cima em Posição de Ataque no campo; destrua o alvo. \r\nDeve haver um Card de Magia de Campo com a face para cima no campo para que você possa ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Comprar','Destruir um monstro','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4179849,'Rainha das Folhas de Outono','Rainha da Floresta Esmeralda e esposa do Rei Espiritual, ela vive cercada de folhas bem avermelhadas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4192696,'Eco, Espírito Místico da Floresta','Quando você sofrer dano de um efeito de card do oponente (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão e, se isso acontecer, cause dano ao seu oponente igual ao dano que você sofreu e, além disso, os dois duelistas não sofrem mais dano de efeito neste turno.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4206964,'Buraco Armadilha','Quando seu oponente Invocar por Invocação-Normal ou Virar um monstro com 1000 ou mais de ATK: escolha o monstro; destrua o alvo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4215180,'Piruli☆Nhamy',replace(replace('Se você controlar um monstro de Link-1 ou um Monstro Sincro de Nível 2, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Piruli☆Nhamy" por Invocação-Especial uma vez por turno desta forma. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 card no Cemitério do seu oponente; embaralhe-o no Deck, ou, se este card foi Invocado por Invocação-Especial pelo efeito de um Monstro Sincro, em vez disso, você pode banir esse card. \r\nVocê só pode usar este efeito de "Piruli☆Nhamy" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Retornar ao Deck','Banir em vez disso?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4215636,'Santuário do Vale das Névoas',replace(replace('Uma vez por turno, quando um ou mais monstros de VENTO forem destruídos por um efeito de card e enviados para o Cemitério (exceto durante a Etapa de Dano): você pode Invocar por Invocação-Especial 1 monstro de VENTO de Nível 3 ou menos da sua mão ou Deck. \r\nSeus efeitos são negados.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4227096,'Captura Equivocada','Até o final do seu próximo turno depois que este card resolver, nenhum duelista pode adicionar cards do seu Deck à sua mão, exceto ao comprá-los.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4230620,'Estação-Psi',replace(replace('Quando um monstro do Tipo Psíquico for Invocado por Invocação-Normal: você pode pagar 500 PV; aumente o Nível dele em 1 e o ATK dele em 300. \r\n(Isso permanece mesmo que este card deixe o campo.)','\r',char(13)),'\n',char(10)),'Aumentar Nível e ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4239451,'Rãmbalhota Camarartista',replace(replace('Escala de Pêndulo = 3\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno: você pode escolher 1 monstro com a face para cima no campo; troque o ATK e DEF atuais dele até o final deste turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nUma vez por turno, durante sua Fase de Batalha (exceto durante a Etapa de Dano): você pode escolher 1 monstro que você controla; mude a posição de batalha dele e, se isso acontecer, troque o ATK e DEF atuais dele até o final deste turno.','\r',char(13)),'\n',char(10)),'Trocar ATK e DEF','Trocar ATK e DEF','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4252828,'Sereia Arqueira',replace(replace('Uma vez por turno: Você pode escolher 1 monstro de Nível 3 ou menos com a face para cima que você controla; equipe o alvo a este card. \r\n(Você só pode equipar 1 monstro de cada vez a este card com este efeito.) \r\nEnquanto estiver equipado com um monstro por este efeito, este card ganha 800 de ATK. \r\nSe este card seria destruído, em vez disso, você pode destruir o monstro equipado a ele com este efeito.','\r',char(13)),'\n',char(10)),'Equipar','Usar o efeito de "Sereia Arqueira" em vez de ser destruído?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4253484,'Besta Gladiadora Hoplomus',replace(replace('Se este card for Invocado por Invocação-Especial pelo efeito de um monstro "Besta Gladiadora", sua DEF original se torna 2400. \r\nNo final da Fase de Batalha, se este card atacou ou foi atacado: Você pode embaralhá-lo no Deck; Invoque por Invocação-Especial 1 monstro "Besta Gladiadora" do seu Deck, exceto "Besta Gladiadora Hoplomus".','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4259068,'Economia de Spells','Você não tem de pagar nenhuns Life Points para activar um Card de Magia.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4266839,'Kiseitai',replace(replace('Quando um monstro do seu oponente atacar este card com a face para baixo em Posição Defesa, este card se torna um Card de Magia de Equipamento equipado ao monstro atacante (nenhum cálculo de dano é conduzido). \r\nDurante cada uma das Fases de Apoio do seu oponente, aumente seus PV pela metade do ATK do monstro equipado com este card.','\r',char(13)),'\n',char(10)),'Tornar-se um Card de Equipamento','Ganhar PV','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4271596,'Rei da Cidade Cinzenta',replace(replace('Se "Obsidim, a Cidade Cinzenta" estiver na Zona do Campo, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Rei da Cidade Cinzenta" por Invocação-Especial uma vez por turno desta forma. \r\nDurante sua Fase Principal: você pode Invocar por Invocação-Especial 1 monstro "Cinzento(a)" da sua mão, exceto "Rei da Cidade Cinzenta" ou, em vez disso, se seu oponente controlar um monstro com 2800 ou mais de ATK, você pode Invocá-lo por Invocação-Especial do seu Deck. \r\nVocê só pode usar este efeito de "Rei da Cidade Cinzenta" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4280258,'Apollousa, o Arco da Deusa',replace(replace('2+ monstros com nomes diferentes, exceto Fichas	\r\nVocê só pode controlar 1 "Apollousa, o Arco da Deusa". \r\nO ATK original deste card se torna 800 x o número de Matérias Link usadas para a sua Invocação-Link. \r\nUma vez por Corrente, quando seu oponente ativar um efeito de monstro (Efeito Rápido): você pode fazer com que este card perca exatamente 800 de ATK e, se isso acontecer, negue a ativação.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4280259,'Apollousa, o Arco da Deusa',replace(replace('2+ monstros com nomes diferentes, exceto Fichas	\r\nVocê só pode controlar 1 "Apollousa, o Arco da Deusa". \r\nO ATK original deste card se torna 800 x o número de Matérias Link usadas para a sua Invocação-Link. \r\nUma vez por Corrente, quando seu oponente ativar um efeito de monstro (Efeito Rápido): você pode fazer com que este card perca exatamente 800 de ATK e, se isso acontecer, negue a ativação.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4290468,'Rosa Esplêndida',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nUma vez por turno: você pode banir 1 monstro Planta do seu Cemitério e, depois, escolha 1 monstro com a face para cima que seu oponente controla; até o final deste turno, diminua pela metade o ATK do alvo. \r\nDurante a Fase de Batalha, se este card atacou: você pode banir 1 monstro Planta do seu Cemitério; até o final deste turno, diminua pela metade o ATK deste card e, se isso acontecer, este card pode realizar um segundo ataque durante esta Fase de Batalha.','\r',char(13)),'\n',char(10)),'Reduzir ATK','Fazer outro ataque','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4333086,'Estilo Shiranui do Corte da Andorinha',replace(replace('Ofereça como Tributo 1 monstro do Tipo Zumbi e, depois, escolha 2 cards no campo; destrua-os e, depois, bana 1 monstro "Shiranui" do seu Deck. \r\nVocê só pode ativar 1 "Estilo Shiranui do Corte da Andorinha" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4334811,'Reciclador de Restolhos',replace(replace('Quando este card for Invocado por Invocação-Normal ou Especial: você pode enviar 1 monstro Máquina do seu Deck para o Cemitério. \r\nUma vez por turno: você pode embaralhar no Deck 2 monstros Máquina de TERRA de Nível 4 do seu Cemitério; compre 1 card.','\r',char(13)),'\n',char(10)),'Escolha 1 monstro Máquina para enviar para o Cemitério','Comprar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4335427,'Sofia, Deusa do Renascimento',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao banir 1 Monstro de Fusão, Ritual, Sincro e Xyz com a face para cima de qualquer parte do campo. \r\nA Invocação-Especial deste card não pode ser negada. \r\nSe este card for Invocado por Invocação-Especial: bana todos os outros cards das mãos, dos campos e dos Cemitérios dos dois duelistas. \r\nNenhum duelista pode ativar cards ou efeitos em resposta à ativação deste efeito.','\r',char(13)),'\n',char(10)),'Banir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4335645,'Newdoria','Se este card for destruído em batalha e enviado para o Cemitério: escolha 1 monstro no campo; destrua o alvo.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4341721,'Hallo-Ween!','Adicione 1 "Hallo, o Espírito das Travessuras" ou "Ween, o Espírito das Gostosuras" do seu Deck ou Cemitério à sua mão.','Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4357063,'Cronomalia Cidade Babilônia','Uma vez por turno: você pode banir 1 monstro "Cronomalia" do seu Cemitério e, depois, escolher 1 monstro "Cronomalia" no seu Cemitério com o mesmo Nível que o monstro banido; Invoque-o por Invocação-Especial.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4367330,'Coexplosão Zoodíaco',replace(replace('Se este card for destruído em batalha ou por um efeito de card: você pode escolher 1 card "Zoodíaco(a)" no seu Cemitério, exceto "Coexplosão Zoodíaco"; adicione-o à sua mão. \r\nUm Monstro Xyz cujo Tipo original seja Besta-Guerreira e que tenha este card como Matéria Xyz ganha este efeito.\r\n● Durante o turno de qualquer duelista, quando seu oponente ativar um Card ou efeito de Magia que escolha este card como alvo: você pode desassociar 1 Matéria Xyz deste card; negue a ativação.','\r',char(13)),'\n',char(10)),'Adicionar à sua mão 1 card "Zoodíaco(a)" do seu Cemitério','Negar a ativação de um efeito de Magia (Coexplosão Zoodíaco)','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4376658,'Espírito-Possuído - Hiita',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão ou do Deck) ao enviar para o Cemitério 1 "Hiita, a Encantadora do Fogo" com a face para cima e 1 monstro de FOGO com a face para cima que você controla. \r\nSe este card Invocado por Invocação-Especial por seu efeito atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4376659,'Espírito-Possuído - Hiita',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão ou do Deck) ao enviar para o Cemitério 1 "Hiita, a Encantadora do Fogo" com a face para cima e 1 monstro de FOGO com a face para cima que você controla. \r\nSe este card Invocado por Invocação-Especial por seu efeito atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4388680,'Assassino Revendorror',replace(replace('Você pode Invocar este card por Invocação-Ritual com qualquer Magia de Ritual "Vendorror". \r\nUma vez por batalha, se este card batalhar um monstro do oponente, durante o cálculo de dano (Efeito Rápido): você pode banir 1 monstro Zumbi do seu Cemitério; este card ganha 300 de ATK. \r\nSe este card Invocado por Invocação-Ritual for enviado para o Cemitério: você pode adicionar 1 Magia de Ritual do seu Deck à sua mão e, se isso acontecer, envie 1 monstro "Vendorror" do seu Deck para o Cemitério. \r\nVocê só pode usar este efeito de "Assassino Revendorror" uma vez por turno.','\r',char(13)),'\n',char(10)),'Aumentar ATK','Procurar no Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4392470,'Leão Mago','Um mago com um manto preto, que na verdade é um leão falante disfarçado.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4398189,'Bruxa da Floresta Branca',replace(replace('Quando este card for ativado: você pode adicionar 1 monstro "Floresta Branca" do seu Deck à sua mão, mas você não pode Invocar monstros de TREVAS por Invocação-Especial do Deck Adicional pelo resto deste turno. \r\nNa primeira vez que cada monstro "Floresta Branca" que você controla seria destruído em batalha a cada turno, ele não é destruído. \r\nVocê pode escolher 1 monstro "Floresta Branca" que você controla; ele é considerado como um Regulador neste turno. \r\nVocê só pode usar este efeito de "Bruxa da Floresta Branca" uma vez por turno. \r\nVocê só pode ativar 1 "Bruxa da Floresta Branca" por turno.','\r',char(13)),'\n',char(10)),'Ativar','','Tornar-se um Regulador','Adicionar 1 carta do seu Deck à sua mão?','','','','','','','','','','','','');
INSERT INTO texts VALUES(4404099,'O Dragão que Habita as Profundezas',replace(replace('Coloque 1 Marcador de Oceano neste card durante a Fase de Apoio de cada duelista. \r\nQuando este card for removido do campo, todos os monstros do Tipo Peixe e do Tipo Serpente Marinha que você controla ganham 200 de ATK para cada Marcador de Oceano neste card até a Fase Final.','\r',char(13)),'\n',char(10)),'Colocar um marcador','Aumentar ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4408198,'Armento Exoirmã',replace(replace('Pague 800 PV e, depois, escolha 1 monstro "Exoirmã" que você controla; Invoque por Invocação-Especial 1 Monstro Xyz "Exoirmã" do seu Deck Adicional com um nome diferente que o dos cards que você controla, usando o alvo como matéria. \r\n(Isso é considerado uma Invocação-Xyz. Transfira as matérias dele para o monstro Invocado.) \r\nVocê só pode ativar 1 "Armento Exoirmã" por turno. \r\nVocê só pode ativar este card durante o turno do seu oponente, a não ser que seu oponente controle um monstro Invocado por Invocação-Especial do Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4417407,'Besta Fantasma Mecha Falcão Negro',replace(replace('Quando este card declarar um ataque: Invoque por Invocação-Especial 1 "Ficha de Besta Fantasma Mecha" (Tipo Máquina/VENTO/Nível 3/ATK 0/DEF 0). \r\nO Nível deste card aumenta em um valor igual à soma dos Níveis de todas as "Fichas de Besta Fantasma Mecha" que você controla. \r\nEnquanto você controlar uma Ficha, este card não pode ser destruído em batalha ou por efeitos de card. \r\nUma vez por turno, durante o turno de qualquer duelista: você pode oferecer 1 Ficha como Tributo e, depois, escolher 1 monstro que seu oponente controla; coloque o alvo em Posição de Defesa com a face para cima.','\r',char(13)),'\n',char(10)),'Invocar uma Ficha por Invocação Especial','Mudar a posição de batalha','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4417408,'Ficha de Besta Fantasma Mecha','Invocado por Especial com o efeito de um monstro "Besta Fantasma Mecha" ou um card relacionado.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4423206,'Sabre-X-M, Aquele que Invoka',replace(replace('2 monstros de Nível 3	\r\nUma vez por turno: você pode desassociar 1 matéria deste card; Invoque por Invocação-Especial 1 monstro de TERRA Guerreiro ou Besta-Guerreira de Nível 4 do seu Deck, em Posição de Defesa, mas destrua-o durante a Fase Final.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4433488,'Cinet Cascata','Se você Invocar um Monstro Link por Invocação-Link: você pode escolher 1 monstro no seu Cemitério usado como sua matéria; Invoque-o por Invocação-Especial.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4440873,'Jogar Tudo Fora','Quando seu oponente adicionar um ou mais cards do Deck dele à mão dele, incluindo ao comprar: ele deve descartar 1 desses cards.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4446672,'Explosivo do Mecanismo Antigo','Escolha 1 monstro "Mecanismo Antigo" que você controla; destrua-o e, se isso acontecer, cause dano ao oponente igual à metade do ATK original dele.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4450854,'Mudança de Qlima',replace(replace('Adicione até 3 Cards de Monstro Pêndulo "Qli" com a face para cima do seu Deck Adicional à sua mão. \r\nVocê só pode ativar 1 "Mudança de Qlima" por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4466015,'Queimada da Peçonha',replace(replace('Escolha 1 monstro com um ou mais Marcadores de Veneno. \r\nRemova todos os Marcadores de Veneno desse card e cause 700 de dano ao seu oponente para cada Marcador de Veneno removido.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4472318,'Dragão Bayerock',replace(replace('Se um ou mais monstros que você controla ou na sua mão forem destruídos em batalha ou por um efeito de card: você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe este card em posse do seu dono for destruído por um card do oponente: você pode escolher 1 outro monstro Dinossauro e/ou 1 monstro Rocha no seu Cemitério; Invoque-os por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Dragão Bayerock" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4474060,'APARATO ESPIRÃO - Drone',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode olhar os 3 cards do topo do Deck do seu oponente e, se isso acontecer, coloque-os no topo do Deck dele em qualquer ordem. \r\n(Efeito Rápido): você pode oferecer este card como Tributo e, depois, escolha 1 monstro "ESPIRÃO" que você controla; ele ganha 500 de ATK para cada card que seu oponente controla. \r\nVocê pode banir este card e 1 card "ESPIRÃO" do seu Cemitério e, depois, escolha 1 "Super Agente ESPIRÃO" no seu Cemitério; adicione-o à sua mão.','\r',char(13)),'\n',char(10)),'Olhe os 3 cards do topo do Deck do seu oponente','Aumentar ATK','Recuperar do Cemitério','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4478086,'Espartoi Clock',replace(replace('2 monstros Ciberso	\r\nSe este card for Invocado por Invocação-Link: você pode adicionar 1 "Cinet Fusão" do seu Deck à sua mão. \r\nSe um ou mais monstros forem Invocados por Invocação-Especial em uma ou mais zonas para as quais este card apontar (exceto durante a Etapa de Dano): você pode escolher 1 monstro Ciberso de Nível 4 ou menos no seu Cemitério; Invoque-o por Invocação-Especial, mas negue seus efeitos e, além disso, você não pode Invocar monstros por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto Monstros de Fusão. \r\nVocê só pode usar cada efeito de "Espartoi Clock" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4483598,'Duplex Totalmente Ativo',replace(replace('Monstros linkados que você controla podem realizar até 2 ataques contra monstros durante cada Fase de Batalha. \r\nVocê só pode usar cada um dos seguintes efeitos de "Duplex Totalmente Ativo" uma vez por turno. \r\nVocê pode banir 2 Monstros Link do seu Cemitério; Invoque este card por Invocação-Especial da sua mão. \r\nSe este card for enviado para o Cemitério: você pode escolher 1 monstro Ciberso que você controla; ele ganha 1000 de ATK.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4483989,'Preparar para Contra-Atacar',replace(replace('Cada vez que seu adversário declarar um ataque num monstro em Posição de Defesa com a face para cima, lance uma moeda e escolha Cara ou Coroa. \r\nSe ganhar, mude o monstro que foi designado como alvo da Posição de Defesa com a face para cima para a Posição de Ataque. \r\nSe perder, o controlador deste card recebe dano igual a diferença entre o ATK do monstro atacante e a DEF do monstro atacado.','\r',char(13)),'\n',char(10)),'Escolher cara ou coroa','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4538826,'Imperador do Caos, o Dragão do Armagedom',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nVocê pode pagar 1000 PV e, depois, escolha 1 dos seus monstros Dragão banidos; destrua este card e, se isso acontecer, adicione esse monstro à sua mão. \r\nVocê só pode usar este efeito de "Imperador do Caos, o Dragão do Armagedom" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nNão pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão ou do Deck Adicional) ao banir 1 monstro de LUZ e 1 de TREVAS do seu Cemitério. \r\nVocê só pode Invocar "Imperador do Caos, o Dragão do Armagedom" por Invocação-Especial uma vez por turno desta forma. \r\nUma vez por turno: você pode pagar metade dos seus PV; envie tantos cards que você controla quanto possível para o Cemitério, exceto da Zona de Monstros Adicional e, se isso acontecer, envie cards que seu oponente controla para o Cemitério, até o número dos seus cards enviados para o Cemitério e, depois, cause 300 de dano ao seu oponente para cada card enviado para o Cemitério dele pelo efeito deste card. \r\nSe este card com a face para cima Invocado por Invocação-Especial deixar o campo, devolva-o para o fundo do Deck.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4542651,'Escudo do Brilho Amarelo','Aumente em 300 a DEF de todos os monstros no seu campo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4545683,'Senhormek Imperador Granel',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial por seu próprio efeito. \r\nQuando um monstro com a face para cima que você controla for destruído por um efeito de card e enviado para o Cemitério (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão. \r\nUma vez por turno: você pode escolher 1 Monstro Sincro que seu oponente controla; equipe o alvo a este card. \r\nGanha ATK/DEF igual à metade dos seus PV e ATK igual ao ATK combinado dos monstros equipados a ele por este efeito. \r\nVocê pode escolher 1 desses monstros equipados; Invoque o alvo por Invocação-Especial no seu campo em Posição de Defesa.','\r',char(13)),'\n',char(10)),'Invocação Especial','Equipar um Monstro Sincro','Invocar por Invocação Especial o monstro equipado','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4545854,'Território Xyz',replace(replace('Quando um Monstro Xyz batalhar com outro monstro, esse Monstro Xyz ganha 200 de ATK & DEF x a sua Classe, apenas durante o cálculo de dano. \r\nSe este card com a face para cima no campo seria destruído por um efeito de card, em vez disso, você pode desassociar 1 Matéria Xyz de um monstro que você controla.','\r',char(13)),'\n',char(10)),'Usar o efeito de "Território Xyz" em vez de ser destruído?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4549095,'Boxeador Obstinado de Contra-ataque',replace(replace('Durante a Etapa de Dano do turno de qualquer duelista, quando um monstro "Boxeador Obstinado" que você controla estiver atacando ou for atacado: você pode banir este card da sua mão ou Cemitério; esse monstro ganha 1000 de ATK até o final deste turno. \r\nVocê só pode usar o efeito de "Boxeador Obstinado de Contra-ataque" uma vez por turno.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4550066,'Cervoconstrutor','Quando este card destruir um monstro do oponente em batalha: você pode escolher 1 monstro Ciberso com 1500 ou menos de ATK no seu Cemitério; Invoque-o por Invocação-Especial.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4575541,'Aqui Existem Dragões',replace(replace('Invoque por Invocação-Especial 1 monstro "Dragão Soberano" da sua mão, do Cemitério ou do banimento e, depois, imediatamente depois que este efeito resolver, você pode Invocar por Invocação-Xyz 1 Monstro Xyz "Dragão Soberano" usando apenas monstros "Dragão Soberano" que você controla. \r\nDurante sua Fase Principal: você pode banir este card do seu Cemitério e, depois, escolha qualquer número dos seus monstros "Dragão Soberano" banidos com Atributos diferentes; devolva-os para o Cemitério. \r\nVocê só pode usar 1 efeito de "Aqui Existem Dragões" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Efeito de recuperação','Invocação Xyz?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4582942,'Ritmo Seguido de Vaalmônica',replace(replace('Aplique 1 desses efeitos. \r\nVocê deve controlar um Card de Monstro "Vaalmônica" para ativar e resolver este efeito. \r\nSe você controlar um Monstro Link "Vaalmônica", você pode aplicar os dois efeitos em sequência.\r\n● Ganhe 500 PV e, depois, você pode destruir 1 Magia/Armadilha no campo.\r\n● Sofra 500 de dano e, depois, você pode devolver 1 monstro do campo para a mão.	\r\nVocê só pode ativar 1 "Ritmo Seguido de Vaalmônica" por turno.','\r',char(13)),'\n',char(10)),'','Ganhe 500 PV','Receba 500 de dano','Aplicar ambos','Destruir 1 Card de Magia/Armadilha no campo?','Retornar à mão 1 monstro no campo?','','','','','','','','','','');
INSERT INTO texts VALUES(4587638,'O Rugido da Terra',replace(replace('Se um monstro do Tipo Besta que você controla atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente. \r\nSe você causar dano de batalha ao seu oponente com este efeito: escolha 1 monstro com a face para cima que seu oponente controla; o alvo perde 500 de ATK e DEF. \r\n(Isso permanece mesmo que este card deixe o campo.)','\r',char(13)),'\n',char(10)),'Reduzir ATK/DEF','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4591250,'Imperatriz Amazoness',replace(replace('"Rainha Amazoness" + 1 monstro "Amazoness"	\r\nOutros cards "Amazoness" que você controla não podem ser destruídos em batalha ou por efeitos de card. \r\nSe um monstro "Amazoness" seu atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente. \r\nSe este card com a face para cima Invocado por Invocação-Fusão for destruído em batalha ou deixar o campo devido a um efeito de card do oponente enquanto for controlado por seu dono: você pode Invocar por Invocação-Especial 1 "Rainha Amazoness" da sua mão, do Deck ou do Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4599182,'Esse Pestinha de uma Figa',replace(replace('(Este card deve ser sempre considerado como um card "Inférnico(a)".)	\r\nInvoque por Invocação-Especial 1 dos seus monstros "Inférnico(a)" que estiverem banidos, ou na sua mão ou no Cemitério. \r\nSe um ou mais monstros "Inférnico(a)" com a face para cima que você controla forem destruídos em batalha, ou deixarem o campo devido a um efeito de card do oponente, enquanto este card estiver no seu Cemitério: você pode Baixar este card. \r\nVocê só pode usar cada efeito de "Esse Pestinha de uma Figa" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4606229,'Última Esperança dos Números',replace(replace('(Este card deve ser sempre considerado como um card "Olhos das Galáxias".)	\r\nPague metade dos seus PV e, depois, escolha 2 monstros no seu Cemitério; Invoque os dois por Invocação-Especial, mas negue seus efeitos e, depois, imediatamente depois que este efeito resolver, Invoque por Invocação-Xyz 1 Monstro Xyz "Número" usando apenas esses 2 monstros e, além disso, pelo resto deste turno depois que este card resolver, você só pode Invocar por Invocação-Especial do Deck Adicional mais uma vez. \r\nVocê só pode ativar 1 "Última Esperança dos Números" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4611269,'Jacaré Leão','Enquanto você controlar outro monstro Réptil, se um monstro Réptil que você controla atacar um monstro em Posição de Defesa, cause dano de batalha perfurante.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4611341,'Força-S Mistify',replace(replace('2+ monstros, incluindo um monstro "Força-S"	\r\nEnquanto seu oponente controlar um monstro na coluna deste card, ele não pode escolher este card como alvo de efeitos de card, nem Invocar por Invocação-Especial com um efeito de monstro ativado. \r\n(Efeito Rápido): você pode escolher 1 monstro no campo; mova-o para outra Zona de Monstros Principal no campo do seu controlador. \r\nVocê só pode usar este efeito de "Força-S Mistify" uma vez por turno.','\r',char(13)),'\n',char(10)),'Mover','Escolha o monstro a mover','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4614116,'Energia das Trevas','Um monstro do Tipo Demônio, equipado com este card, aumenta o seu ATK e DEF em 300 pontos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4628897,'Magnum Imperion, o Robô de Batalha Supercondutor',replace(replace('"Valkyrion, o Guerreiro Imã" + "Berserkion, o Guerreiro Imã Temporal"	\r\nDeve ser Invocado por Invocação-Fusão com as Matérias de Fusão acima e não pode ser Invocado por Invocação-Especial de nenhuma outra forma. \r\nUma vez por turno, durante o turno de qualquer duelista, quando seu oponente ativar um Card de Magia/Armadilha ou efeito de monstro: você pode negar a ativação e, se isso acontecer, destrua esse card. \r\nSe este card com a face para cima sob o controle do seu dono deixar o campo devido ao efeito de um card do oponente: você pode Invocar por Invocação-Especial tanto 1 "Valkyrion, o Guerreiro Imã" e 1 "Berserkion, o Guerreiro Imã Temporal" da sua mão e/ou Deck, ignorando suas condições de Invocação.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4632019,'Yamatako Orochi',replace(replace('Este card no campo pode ser considerado como um monstro de Nível 8 quando usado para uma Invocação-Sincro. \r\nUm Monstro Sincro que usou este card como matéria ganha este efeito de acordo com seu Nível original.\r\n● 8 ou menos: Ganha 800 de ATK/DEF.\r\n● 9 ou mais: Se este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante.','\r',char(13)),'\n',char(10)),'O efeito de "Yamatako Orochi" está sendo aplicado.','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4638410,'Temperamento do Tirano',replace(replace('Ofereça como Tributo 1 monstro para ativar este card. \r\nTodos os monstros com a face para cima no campo que você possui não são afetados por outros Cards de Armadilha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4647954,'ZS - Sábio Ascenso',replace(replace('Se você não controlar nenhum card, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nUm Monstro Xyz "Utopia" que foi Invocado usando este card no campo como matéria ganha este efeito.\r\n● Se este card for Invocado por Invocação-Xyz: você pode adicionar 1 Magia Normal "Magia de Aumento de Classe" do seu Deck à sua mão.	\r\nVocê só pode usar este efeito de "ZS - Sábio Ascenso" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Adicionar uma Magia de Aumento de Classe à mão (ZS - Sábio Ascenso)','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4663194,'Prisão da Torre do Relógio da Cidade – Cidade Sombria',replace(replace('Toda vez que você Invoca por Invocação-Especial um ou mais monstros "HERÓI do Destino" de Nível 8 ou maior: todos os monstros Guerreiro que você atualmente controla ganham 300 de ATK.\r\nVocê só pode usar cada um dos seguintes efeitos de "Prisão da Torre do Relógio da Cidade – Cidade Sombria" uma vez por turno.\r\nSe este card for ativado neste turno: você pode adicionar 1 monstro "HERÓI do Destino" ou 1 card que menciona o nome de um monstro "HERÓI do Destino", do seu Deck à sua mão.\r\nSe este card for destruído: você pode Invocar por Invocação-Especial 1 monstro "HERÓI do Destino" do seu Deck (isso é considerado como uma Invocação-Especial com "Prisão da Torre do Relógio").','\r',char(13)),'\n',char(10)),'Adicionar à mão','Aumentar ATK','Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4682617,'Agradecimento Final do Ator do Abismo',replace(replace('Se um Card de Magia "Script do Abismo" ou seus efeitos forem ativados neste turno: adicione Monstros Pêndulo "Ator do Abismo" com a face para cima do seu Deck Adicional à sua mão, até o número de Magias "Script do Abismo" no seu Cemitério. \r\nDepois, você pode Invocar por Invocação-Especial Monstros Pêndulo "Ator do Abismo" da sua mão com nomes diferentes, até o número de monstros adicionados à mão por este efeito. \r\nVocê não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto Monstros Pêndulo "Ator do Abismo". \r\nVocê só pode ativar 1 "Agradecimento Final do Ator do Abismo" por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4688231,'Metalmorfose Mitralium',replace(replace('1 monstro "Metalmorfose" + 1 Monstro Pêndulo	\r\nVocê pode escolher 2 cards "Metalmorfose" no seu Cemitério e 1 card no campo; embaralhe os alvos do seu Cemitério no Deck e, se isso acontecer, devolva para a mão o alvo no campo. \r\nVocê só pode usar este efeito de "Metalmorfose Mitralium" uma vez por turno. \r\nSe este card for enviado do campo para o Cemitério: você pode Invocar por Invocação-Especial 1 Monstro Pêndulo "Metalmorfose" do seu Cemitério ou do Deck Adicional com a face para cima.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4694209,'Vigia Card',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: coloque 1 Marcador de Vigia nele. \r\nEste card ganha 300 de ATK para cada Marcador de Vigia nele. \r\nUma vez por turno: você pode escolher 1 outro card com a face para cima que você controla; remova 1 Marcador de Vigia deste card e, se isso acontecer, coloque 1 Marcador de Vigia sobre o alvo (se esse card seria destruído em qualquer momento, em vez disso, remova 1 Marcador de Vigia dele).','\r',char(13)),'\n',char(10)),'Colocar um marcador','Mover marcadores','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4709881,'Auram, o Espadachim do Cálice Mundial',replace(replace('2 monstros "Cálice Mundial"	\r\nGanha 300 de ATK para cada monstro "Legado Mundial" com um nome diferente no seu Cemitério. \r\nVocê pode oferecer como Tributo 1 monstro "Cálice Mundial" para o qual este card apontar e, depois, escolher 1 outro monstro no seu Cemitério; Invoque-o por Invocação-Especial em uma zona sua para a qual este card apontar. \r\nVocê só pode usar este efeito de "Auram, o Espadachim do Cálice Mundial" uma vez por turno. \r\nSe este card for enviado do campo para o Cemitério: você pode Invocar por Invocação-Especial 1 monstro "Cálice Mundial" da sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4722253,'Gearfried Raio-de-Luz',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nVocê deve Invocá-lo por Invocação-Especial (da sua mão) ao ter 5 ou mais monstros de LUZ com nomes diferentes no seu Cemitério e não pode Invocá-lo por Invocação-Especial de nenhuma outra forma. \r\nUma vez por turno, durante o turno de qualquer duelista, quando um Card de Magia/Armadilha for ativado: você pode banir 1 monstro do Tipo Guerreiro do seu Cemitério; negue a ativação e, se isso acontecer, destrua-o. \r\nTodos os monstros com a face para cima que você controla devem ser do Tipo Guerreiro para que você possa ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4729591,'Utensilhor Kappalança',replace(replace('1 monstro "Utensilhor"	\r\nNão pode ser usado como Matéria Link no turno em que for Invocado por Invocação-Link. \r\nVocê pode oferecer este card co-linkado como Tributo; Invoque por Invocação-Especial 1 Monstro Link "Utensilhor" do seu Cemitério, exceto "Utensilhor Kappalança". \r\nVocê pode oferecer este card que não estiver co-linkado como Tributo; Invoque por Invocação-Especial 1 monstro "Utensilhor" de Nível 4 ou menos do seu Cemitério. \r\nVocê só pode usar cada efeito de "Utensilhor Kappalança" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4731783,'A Bao A Qu, a Sombra Sem Luz',replace(replace('2+ monstros, incluindo um monstro Demônio	\r\nDurante a Fase Principal (Efeito Rápido): você pode descartar 1 card e, depois, ative 1 desses efeitos;\r\n● Destrua 1 card no campo.\r\n● Bana este card (até a Fase Final) e, se isso acontecer, Invoque por Invocação-Especial 1 monstro de LUZ ou de TREVAS do seu Cemitério.	\r\nDurante sua Fase de Apoio: você pode comprar cards igual ao número de Tipos de Monstro diferentes no seu Cemitério e, depois, coloque cards da sua mão no fundo do Deck em qualquer ordem, igual ao número de cards que você comprou. \r\nVocê só pode usar cada efeito de "A Bao A Qu, a Sombra Sem Luz" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar o efeito','Comprar','Destruir','Banir e Invocar por Invocação Especial','','','','','','','','','','','','');
INSERT INTO texts VALUES(4731784,'A Bao A Qu, a Sombra Sem Luz',replace(replace('2+ monstros, incluindo um monstro Demônio	\r\nDurante a Fase Principal (Efeito Rápido): você pode descartar 1 card e, depois, ative 1 desses efeitos;\r\n● Destrua 1 card no campo.\r\n● Bana este card (até a Fase Final) e, se isso acontecer, Invoque por Invocação-Especial 1 monstro de LUZ ou de TREVAS do seu Cemitério.	\r\nDurante sua Fase de Apoio: você pode comprar cards igual ao número de Tipos de Monstro diferentes no seu Cemitério e, depois, coloque cards da sua mão no fundo do Deck em qualquer ordem, igual ao número de cards que você comprou. \r\nVocê só pode usar cada efeito de "A Bao A Qu, a Sombra Sem Luz" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar o efeito','Comprar','Destruir','Banir e Invocar por Invocação Especial','','','','','','','','','','','','');
INSERT INTO texts VALUES(4732017,'Zumbi Fundido','Quando este card é Invocado por Invocação-Especial do Cemitério: compre 1 card.','Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4740489,'Campo de Junção de Ímãs',replace(replace('Se você controlar um monstro Rocha de TERRA de Nível 4 ou menos: você pode escolher 1 monstro "Guerreiro Ímã" de Nível 4 ou menos no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê só pode usar este efeito de "Campo de Junção de Ímãs" uma vez por turno. \r\nUma vez por turno, no final da Etapa de Dano, quando um monstro Rocha de TERRA que você controla batalhou um monstro do oponente, mas o monstro do oponente não foi destruído pela batalha: você pode devolver esse monstro do oponente para a mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4754691,'Bugroth Anfíbio MK-11',replace(replace('Enquanto "Umi" não estiver no campo, este card ganha 700 de ATK e, além disso, ele não pode atacar diretamente. \r\nEnquanto "Umi" estiver no campo: você pode escolher 1 monstro que não seja de ÁGUA com a face para cima no campo; destrua-o. \r\nVocê só pode usar este efeito de "Bugroth Anfíbio MK-11" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4756629,'Hordeum Maligno Kerykeion',replace(replace('Você só pode usar cada efeito de "Hordeum Maligno Kerykeion" uma vez por turno. \r\nEnquanto este card estiver no Cemitério, se ele foi enviado para lá neste turno, você pode Invocar por Invocação-Normal 1 monstro "Hordeum" oferecendo 1 Tributo a menos que o normalmente exigido.\r\nVocê pode banir 1 monstro "Hordeum" do seu Cemitério e, depois, escolher 1 monstro "Hordeum" em seu Cemitério; adicione o alvo à sua mão e, além disso, este card ganha o seguinte efeito.\r\n● Neste turno: você pode ativar este efeito; Invoque por Invocação-Normal 1 monstro "Hordeum".','\r',char(13)),'\n',char(10)),'Adicione à sua mão 1 monstro no seu Cemitério cujo nome contenha "Hordeum"','Invoque 1 monstro cujo nome contenha "Hordeum"','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4779091,'Yubel - Encarnação do Terror',replace(replace('Não pode ser Invocado por Invocação-Normal ou Baixado. \r\nDeve ser Invocado por Invocação-Especial por "Yubel". \r\nNão pode ser destruído em batalha. \r\nVocê não sofre dano de batalha das batalhas envolvendo este card. \r\nAntes do cálculo de dano, se este card com a face para cima em Posição de Ataque for escolhido como alvo de um ataque: cause dano ao seu oponente igual ao ATK desse monstro atacante. \r\nUma vez por turno, durante sua Fase Final: destrua todos os outros monstros no campo. \r\nQuando este card com a face para cima deixar o campo: você pode Invocar por Invocação-Especial 1 "Yubel - O Pesadelo Supremo" da sua mão, do Deck ou do Cemitério.','\r',char(13)),'\n',char(10)),'Causar dano','Destruir','Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4779823,'Miguel, o Arquiluminoso',replace(replace('1 Regulador + 1 ou mais monstros de LUZ não-Reguladores	\r\nUma vez por turno: você pode pagar 1000 PV e, depois, escolher 1 card no campo; bana o alvo. \r\nQuando este card for destruído: você pode escolher qualquer número de outros monstros "Luminoso(a)" (exceto "Gearfried Raio Luminoso") no seu Cemitério; embaralhe-os no Deck e, se isso acontecer, você ganha 300 PV para cada card devolvido. \r\nUma vez por turno, durante sua Fase Final: envie os 3 cards do topo do seu Deck para o Cemitério.','\r',char(13)),'\n',char(10)),'Banir','Retornar ao Deck','Enviar para o Cemitério','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4786063,'Armadura Samurai Superpesado Alma Ígnea',replace(replace('Você pode escolher 1 monstro "Samurai Superpesado" que você controla; equipe este monstro, da sua mão ou do seu lado do campo, ao alvo. \r\nO Nível dele se torna 5. \r\nDurante o turno de qualquer duelista: você pode descartar este card e, depois, escolher 1 monstro "Samurai Superpesado" em Posição de Defesa que você controla; até o final deste turno, ele perde 800 de DEF, mas não pode ser destruído em batalha nem por efeitos de card.','\r',char(13)),'\n',char(10)),'Equipar','Não pode ser destruído','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4796100,'Quimera, a Besta Mística Voadora',replace(replace('"Gazelle, o Rei das Bestas Místicas" + "Berfomet"	\r\n(Este card deve ser sempre considerado como um card "Besta Fantasma".)	\r\nQuando este card for destruído: você pode escolher 1 "Berfomet" ou 1 "Gazelle, o Rei das Bestas Místicas" no seu Cemitério; Invoque o alvo por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4807253,'Camaramágico Come Chamas',replace(replace('Durante o turno de qualquer duelista, quando um card ou efeito que causaria dano a você for ativado: você pode ativar este efeito; você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros "Camaramágico" e, além disso, Invoque este card por Invocação-Especial da sua mão e, se isso acontecer, transforme em 0 esse dano de efeito a você. \r\nSe Invocado desta forma, bana-o quando ele deixar o campo. \r\nSe este card for Invocado por Invocação-Normal ou Especial: cada duelista sofre 500 de dano.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4810585,'Saga dos Guerreiros Antigos - Defesa de Changban',replace(replace('Se um monstro "Guerreiros Antigos" seu batalhar, seu oponente não pode ativar nenhum Card de Magia/Armadilha até o final da Etapa de Dano. \r\nVocê só pode usar 1 dos seguintes efeitos de "Saga dos Guerreiros Antigos - Defesa de Changban" por turno e apenas uma vez por turno.\r\n● No começo da Fase de Batalha do seu oponente: você pode enviar este card com a face para cima da sua Zona de Magias & Armadilhas para o Cemitério; os monstros que seu oponente controla não podem escolher monstros "Guerreiros Antigos" como alvo de ataques neste turno.\r\n● Quando um monstro do oponente declarar um ataque: você pode banir este card do seu Cemitério; Invoque por Invocação-Especial 1 monstro "Guerreiros Antigos" do seu Deck.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4810828,'Sauravis, o Antigo e Ascenso',replace(replace('Você pode Invocar este card por Invocação-Ritual com "Benção dos Duendes". \r\nQuando seu oponente ativar um card ou efeito que escolha como alvo um monstro que você controla (Efeito Rápido): você pode descartar este card; negue a ativação. \r\nQuando seu oponente Invocaria um ou mais monstros por Invocação-Especial (Efeito Rápido): você pode devolver este card para a mão; negue a Invocação-Especial e, se isso acontecer, bana esse(s) monstro(s).','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4820694,'Tormenta Constelar',replace(replace('Durante sua Fase Final: você pode escolher 2 monstros Xyz "Constelar" que você controla que tiverem Matérias Xyz; desassocie todas as Matérias Xyz dos dois Monstros Xyz e, se isso acontecer, diminua pela metade os PV do seu oponente. \r\nVocê só pode usar este efeito de "Tormenta Constelar" uma vez por Duelo. \r\nUma vez por turno, durante sua Fase de Apoio: você pode escolher 1 Monstro Xyz "Constelar" que você controla e 1 monstro "Constelar" no seu Cemitério; associe esse monstro do Cemitério a esse Monstro Xyz como uma Matéria Xyz.','\r',char(13)),'\n',char(10)),'Alterar LP','Associar Matéria Xyz','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4825390,'Livro Razão de Ichiroku','Escolha até 2 monstros que seu oponente controla; bana-os até a Fase Final e, depois, seu oponente ganha 1000 PV para cada monstro que deixou o campo por este efeito.','','Escolha o monstro para retornar ao campo','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4836680,'Vidente Camarartista de Olhos Anômalos',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nVocê pode escolher 1 card "Camarartista" ou "Olhos Anômalos" no seu Cemitério; adicione-o à sua mão e, depois, destrua este card. \r\nVocê só pode usar este efeito de "Vidente Camarartista de Olhos Anômalos" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nDurante sua Fase Principal, se você controlar este card Invocado por Invocação-Pêndulo: você pode ativar o seguinte efeito, de acordo com sua posição de batalha;\r\n● Posição de Ataque: Você pode banir este card e, depois, escolha 1 monstro "Camarartista" ou "Olhos Anômalos" no seu Cemitério; Invoque-o por Invocação-Especial.\r\n● Posição de Defesa: Pegue 1 Monstro Pêndulo "Camarartista" ou "Olhos Anômalos" do seu Deck e adicione-o ao seu Deck Adicional com a face para cima ou envie-o para o Cemitério.	\r\nVocê só pode usar este efeito de "Vidente Camarartista de Olhos Anômalos" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar ao Deck Adicional','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4837861,'Senhormek Astro Dragão Triskelion',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro deve ser Invocado por Invocação-Especial (da sua mão) ao banir 3 monstros "Senhormek" com nomes diferentes do seu Cemitério. \r\nUma vez por turno, quando este card declarar um ataque: você pode olhar o Deck Adicional do seu oponente e equipar 1 monstro dali a este card. \r\nEste card ganha ATK igual ao ATK combinado desses monstros equipados. \r\nEnquanto estiver equipado com um Monstro Sincro, este card pode realizar até 3 ataques contra monstros durante cada Fase de Batalha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4841383,'Florescer Ragnaraika',replace(replace('Monstros Inseto, Planta e Réptil no campo ganham 300 de ATK/DEF e, além disso, todos os outros monstros no campo perdem 300 de ATK/DEF. \r\nDurante sua Fase Principal: você pode ativar 1 desses efeitos;\r\n● Adicione 1 monstro "Ragnaraika" do seu Deck à sua mão e, depois, descarte 1 card.\r\n● Invoque por Invocação-Especial 1 dos seus monstros "Ragnaraika" da sua mão, do Cemitério ou do banimento, em Posição de Defesa.	\r\nVocê só pode usar este efeito de "Florescer Ragnaraika" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Ativar o efeito','Adicionar à mão 1 monstro "Ragnaraika"','Invocar por Invocação Especial 1 monstro "Ragnaraika"','','','','','','','','','','','','');
INSERT INTO texts VALUES(4848423,'Médico Musculoso','Se um duelista sofreria dano de uma batalha envolvendo este card, em vez disso, ele ganha esse tanto de PV.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4849037,'Performance da Espada','Você pode Invocar este card por Invocação-Ritual com "Dança do Começo".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4857085,'Óculos Ômega',replace(replace('Só pode ser equipado a um monstro que você controla. \r\nUma vez por turno, você pode olhar 1 card aleatório na mão do seu oponente. \r\nO monstro equipado não pode atacar no turno em que você ativar este efeito.','\r',char(13)),'\n',char(10)),'Revelar sua mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4861205,'Chamado da Múmia',replace(replace('Uma vez por turno: você pode Invocar por Invocação-Especial 1 monstro Zumbi da sua mão. \r\nVocê não pode controlar nenhum monstro para ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4869446,'Judgment of the Desert','As posições de batalha dos monstros com a face para cima, que foram virados para cima depois da activação deste card, não podem ser mudadas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4881365,'Dragão Cavaleiro Espada do Jacaré',replace(replace('Pode atacar diretamente.\r\nSe este card está na sua mão: você pode revelar 1 outro card na sua mão que mencione "Mago do Tempo Sombrio"; Invoque este card por Invocação-Especial.\r\nSe este card é Invocado por Invocação-Normal ou Especial: você pode adicionar até 2 Magias/Armadilhas com nomes diferentes de cada uma que mencione "Mago do Tempo Sombrio" do seu Deck à sua mão, então descarte 1 card.\r\nVocê só pode usar cada um dos efeitos de "Dragão Cavaleiro Espada do Jacaré" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4891376,'Zalen, o Dragão Acorrentado',replace(replace('1 Regulador + 1+ Monstros Sincro	\r\nSe este card que você controla seria usado como Matéria Sincro, você pode considerá-lo como um não-Regulador. \r\nQuando um card ou efeito for ativado em resposta à ativação de outro card ou efeito (Efeito Rápido): você pode ativar 1 desses efeitos;\r\n● Negue o primeiro efeito e, se isso acontecer, destrua esse card.\r\n● Negue o segundo efeito e, se isso acontecer, destrua esse card.	\r\nVocê só pode usar este efeito de "Zalen, o Dragão Acorrentado" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Negar o efeito','Negar o efeito de corrente','Negar o efeito ao qual foi vinculado na corrente','','','','','','','','','','','','');
INSERT INTO texts VALUES(4896788,'Espírito do Pote da Ganância','Enquanto este card estiver no campo com a face para cima em Posição de Ataque, se um duelista ativar "Pote da Ganância", ele pode comprar mais 1 card.','Usar o efeito de "Espírito do Pote da Ganância" para comprar 1 card?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4904633,'Núcleo Sombraneco',replace(replace('Invoque este card por Invocação-Especial como um Monstro de Efeito (Mago/TREVAS/Nível 9/ATK 1450/DEF 1950).	\r\n(Este card ainda é considerado uma Armadilha.) \r\nSe Invocado desta forma, você pode substituir este monstro por 1 Matéria de Fusão que liste um Atributo, em um Card de Monstro de Fusão "Sombraneco". \r\nSe este card for enviado para o Cemitério por um efeito de card: você pode escolher 1 Magia/Armadilha "Sombraneco" no seu Cemitério, exceto "Núcleo Sombraneco"; adicione-a à sua mão.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4904812,'Undina Genex','Quando este card for Invocado por Invocação-Normal: você pode enviar 1 monstro de ÁGUA do seu Deck para o Cemitério; adicione 1 "Controlador Genex" do seu Deck à sua mão.','Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4906301,'Necro Gardna','Durante o turno do seu oponente: você pode banir este card do seu Cemitério; negue o próximo ataque, neste turno, de um monstro que seu oponente controla (este é um Efeito Rápido).','Negar 1 ataque','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4909946,'Desfile de Chefes',replace(replace('Quando este card for ativado: adicione 1 monstro "B.E.S." do seu Deck à sua mão. \r\nUma vez por turno, durante sua Fase Principal: você pode destruir 1 monstro na sua mão ou no campo e, se isso acontecer, Invoque por Invocação-Especial 1 monstro Máquina de LUZ com 1200 de ATK e 1000 ou menos de DEF do seu Deck em qualquer campo. \r\nVocê pode banir este card do seu Cemitério; coloque 1 "Corrida para o Chefe" do seu Deck ou Cemitério, com a face para cima no seu campo. \r\nVocê só pode ativar 1 "Desfile de Chefes" por turno.','\r',char(13)),'\n',char(10)),'Ativar','Invocação Especial','Colocar','Invocar por Invocação Especial no campo do oponente?','','','','','','','','','','','','');
INSERT INTO texts VALUES(4914353,'Isolador Espacial',replace(replace('2 monstros	\r\nMonstros para os quais este card apontar perdem 800 de ATK/DEF. \r\nQuando um Monstro Link Ciberso for Invocado por Invocação-Link no seu campo, enquanto este card estiver no Cemitério, exceto no turno em que este card foi enviado para o Cemitério: você pode Invocar este card por Invocação-Especial em uma zona sua para a qual esse monstro apontar, mas ele não pode ser usado como Matéria Link e, além disso, bana-o quando ele deixar o campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4918855,'Vampiro Voivode',replace(replace('Se este card for Invocado por Invocação-Normal: você pode escolher até 2 monstros no Cemitério do seu oponente; Invoque esses monstros por Invocação-Especial no seu campo em Posição de Defesa, mas seus efeitos são negados. \r\nQuando um efeito de monstro for ativado, enquanto um ou mais monstros com o seu mesmo nome estiverem no(s) \r\nCemitério(s) (Efeito Rápido): você pode negar a ativação. \r\nSe um ou mais monstros forem Invocados por Invocação-Especial do Cemitério do seu oponente: você pode oferecer 2 monstros como Tributo; Invoque este card por Invocação-Especial do seu Cemitério. \r\nVocê só pode usar cada efeito de "Vampiro Voivode" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Negar a ativação','Invocar este card por Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4920010,'Almas dos Esquecidos','Um espírito perverso, criado pelas hediondas almas daqueles que pereceram em combate. Cresce através do assimilar das almas dos seus inimigos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4923662,'Explosão do Caos','Quando um monstro do seu oponente declarar um ataque: ofereça 1 monstro como Tributo e, depois, escolha o monstro atacante; destrua o alvo e, depois, cause 1000 de dano ao seu oponente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4928565,'Lagrimentiara Kashtira',replace(replace('Durante a Fase Principal (Efeito Rápido): você pode Invocar este card por Invocação-Especial da sua mão e, se isso acontecer, bana 1 card "Kashtira" ou "Lagrimentiara" da sua mão ou do Cemitério. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode enviar para o Cemitério os 3 cards do topo do Deck de qualquer duelista. \r\nSe este card for enviado para o Cemitério por um efeito de card: você pode enviar os 2 cards do topo do seu Deck para o Cemitério. \r\nVocê só pode usar cada efeito de "Lagrimentiara Kashtira" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Envie para o Cemitério os 3 cards do topo do seu Deck','Envie para o Cemitério os 3 cards do topo do Deck do seu oponente','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4929256,'Mebius, o Monarca Frio como o Gelo','Quando este card for Invocado por Invocação-Tributo: você pode escolher até 2 Magias/Armadilhas no campo; destrua os alvos.','Destruir até 2 Cards de Magia/Armadilha no campo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4931121,'Vírus de Força Total','Ofereça como Tributo 1 monstro de TREVAS com 2000 ou mais de DEF; olhe a mão do seu oponente, todos os monstros que ele controla e todos os cards que ele comprar até o final do 3º turno dele depois que este card resolver e destrua todos esses monstros com 1500 ou menos de DEF.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4931562,'Guerreiro da Montanha','Um forte guerreiro que pode se mover facilmente até nos piores terrenos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4939890,'Ouriço Sombraneco',replace(replace('VIRE: Você pode adicionar 1 Magia/Armadilha "Sombraneco" do seu Deck à sua mão.\r\nSe este card for enviado para o Cemitério por um efeito de card: você pode adicionar 1 monstro "Sombraneco" do seu Deck à sua mão, exceto "Ouriço Sombraneco". \r\nVocê só pode usar 1 efeito de "Ouriço Sombraneco" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão uma Magia/Armadilha','Adicionar à mão um monstro','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4941482,'Aranha Informante','Quando este card for enviado do campo para o Cemitério por um efeito de card, tome o controle de 1 monstro em Posição de Defesa que seu oponente controla.','Tomar controle','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4965193,'Chasma, Dragão Soberano das Auroras',replace(replace('2 monstros Dragão de Nível 7	\r\n(Efeito Rápido): você pode enviar 1 monstro "Dragão Soberano" de Nível 7 do seu Deck para o Cemitério e desassociar 1 matéria deste card; este efeito se torna o efeito desse monstro enviado que descarta a si mesmo para ativar. \r\nSe este card for destruído em batalha, ou se este card em posse do seu dono for destruído por um efeito de card do oponente: você pode Invocar por Invocação-Especial 1 monstro "Dragão Soberano" de Nível 7 do seu Cemitério ou banimento. \r\nVocê só pode usar cada efeito de "Chasma, Dragão Soberano das Auroras" uma vez por turno.','\r',char(13)),'\n',char(10)),'Copiar efeito','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4991081,'Dragão de Estimação da Harpia - Terrível Rajada de Fogo',replace(replace('Monstros não podem escolher monstros "Harpia" de Nível 6 ou menos como alvo de ataques. \r\nVocê só pode usar cada um dos seguintes efeitos de "Dragão de Estimação da Harpia - Terrível Rajada de Fogo" uma vez por turno. \r\nSe você controlar um monstro de VENTO de Nível 6 ou menos: você pode Invocar este card por Invocação-Especial da sua mão em Posição de Defesa. \r\nSe este card for enviado do campo para o Cemitério: você pode enviar 1 monstro de VENTO Besta Alada do seu Deck para o Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4993187,'W:P Baile Elegante',replace(replace('2+ Monstros de Efeito	\r\nQuando seu oponente ativar um efeito de monstro no campo ou Cemitério (Efeito Rápido): você pode banir, até a Fase Final, este card que foi Invocado por Invocação-Especial neste turno; negue o efeito e, se isso acontecer, bana-o. \r\nDurante a Fase Principal do seu oponente, você pode (Efeito Rápido): imediatamente depois que este efeito resolver, Invoque 1 Monstro Link por Invocação-Link e, se este card que você controla seria usado como matéria para essa Invocação-Link, você também pode usar 1 monstro de Link-2 ou menos que seu oponente controla. \r\nNenhum duelista pode ativar os efeitos de Monstros Link em resposta à ativação deste efeito. \r\nVocê só pode usar cada efeito de "W:P Baile Elegante" uma vez por turno.','\r',char(13)),'\n',char(10)),'Negar','Invocação Link','Banir até a Fase Final','','','','','','','','','','','','','');
INSERT INTO texts VALUES(4997565,'Número 3: Rei Cigarra',replace(replace('2 monstros de Nível 3	\r\nSe a posição de batalha deste card for mudada: você pode Invocar por Invocação-Especial 1 monstro Inseto da sua mão ou do Cemitério em Posição de Defesa. \r\nQuando um monstro no campo ativar seu efeito: você pode desassociar 1 matéria deste card e, depois, escolha esse monstro; negue seus efeitos e, depois, faça com que 1 monstro Inseto no campo ganhe 500 de DEF ou mude sua posição de batalha. \r\nVocê só pode usar cada efeito de "Número 3: Rei Cigarra" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Aumentar DEF','Alterar posição de batalha','','','','','','','','','','','','');
INSERT INTO texts VALUES(4998619,'Gundil Notável, o Behemoth Cúbico',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao enviar 3 monstros "Cúbico(a)" que você controla para o Cemitério e não pode ser Invocado por Invocação-Especial de nenhuma outra forma. \r\nSe Invocado desta forma, este card ganha 3000 de ATK. \r\nEste card pode realizar um segundo e terceiro ataque durante cada Fase de Batalha. \r\nSe este card em sua posse for enviado para o seu Cemitério por um card do seu oponente (em batalha ou por um efeito de card): você pode escolher até 3 monstros "Cúbico(a)" no seu Cemitério; Invoque-os por Invocação-Especial e, depois, você pode adicionar 1 card "Cúbico(a)" do seu Deck ou Cemitério à sua mão.','\r',char(13)),'\n',char(10)),'Adicionar à sua mão 1 card "Cúbico(a)"?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5008836,'Exodia, o Defensor Lendário',replace(replace('Não pode ser Invocado por Invocação-Especial. \r\nVocê pode oferecer 5 monstros como Tributo para Invocar este card por Invocação-Tributo (mas não para Baixar). \r\nO ATK/DEF deste card se tornam a soma dos respectivos ATK/DEF originais dos monstros oferecidos como Tributo. \r\nSe este card Invocado desta forma destruir um monstro Demônio de TREVAS do qual seu oponente seja dono, você vence o Duelo no final da Etapa de Dano.','\r',char(13)),'\n',char(10)),'Oferecer como Tributo 5 monstros para Invocar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5010422,'Princesa da Premonição Astromorrigan','VIRE: Durante a Fase Final deste turno, destrua tantos monstros em Posição de Defesa que seu oponente controla quanto possível e, se isso acontecer, cause 500 de dano ao seu oponente para cada monstro destruído.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5014629,'Porta-aviões Submersível Aero Tubarão',replace(replace('2 monstros de Nível 3	\r\nUma vez por turno: você pode desassociar 1 Matéria Xyz deste card; cause 100 de dano ao seu oponente para cada um dos seus monstros banidos.','\r',char(13)),'\n',char(10)),'Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5026221,'Onda Novastelar','Uma vez por turno, durante sua Fase Principal ou a Fase de Batalha do seu oponente: você pode Invocar por Invocação-Especial 1 monstro "Cavaleirost" da sua mão.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5037726,'Hijiri - Artista da Luz Espiritual','Ofereça como Tributo 1 monstro de LUZ para escolher 1 monstro banido; seu oponente pode revelar 1 Card de Armadilha da mão dele para negar o efeito deste card, caso contrário, você pode Invocar esse monstro por Invocação-Especial.','Revelar 1 Card de Armadilha ao seu oponente?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5041348,'Draco Enfurecido dos Tenyi',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nQuando seu oponente ativar um efeito de monstro (Efeito Rápido): você pode banir esse monstro. \r\nSe este card atacante destruir um Monstro de Efeito em batalha e enviá-lo para o Cemitério: este card ganha ATK igual ao ATK original do monstro destruído e, além disso, ele pode realizar um segundo ataque contra um monstro durante esta Fase de Batalha. \r\nVocê só pode usar cada efeito de "Draco Enfurecido dos Tenyi" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5043010,'Dragão Firewall',replace(replace('2+ monstros	\r\nUma vez enquanto estiver com a face para cima no campo (Efeito Rápido): você pode escolher monstros no campo e/ou no Cemitério até o número de monstros co-linkados a este card; devolva-os para a mão. \r\nSe um monstro para o qual este card apontar for destruído em batalha ou enviado para o Cemitério: você pode Invocar por Invocação-Especial 1 monstro Ciberso da sua mão. \r\nVocê só pode usar cada efeito de "Dragão Firewall" uma vez por turno.','\r',char(13)),'\n',char(10)),'Retornar à mão do dono','Invocação Especial','Efeito já ativado','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5043011,'Dragão Firewall',replace(replace('2+ monstros	\r\nUma vez enquanto estiver com a face para cima no campo (Efeito Rápido): você pode escolher monstros no campo e/ou no Cemitério até o número de monstros co-linkados a este card; devolva-os para a mão. \r\nSe um monstro para o qual este card apontar for destruído em batalha ou enviado para o Cemitério: você pode Invocar por Invocação-Especial 1 monstro Ciberso da sua mão. \r\nVocê só pode usar cada efeito de "Dragão Firewall" uma vez por turno.','\r',char(13)),'\n',char(10)),'Retornar à mão do dono','Invocação Especial','Efeito já ativado','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5043012,'Dragão Firewall',replace(replace('2+ monstros	\r\nUma vez enquanto estiver com a face para cima no campo (Efeito Rápido): você pode escolher monstros no campo e/ou no Cemitério até o número de monstros co-linkados a este card; devolva-os para a mão. \r\nSe um monstro para o qual este card apontar for destruído em batalha ou enviado para o Cemitério: você pode Invocar por Invocação-Especial 1 monstro Ciberso da sua mão. \r\nVocê só pode usar cada efeito de "Dragão Firewall" uma vez por turno.','\r',char(13)),'\n',char(10)),'Retornar à mão do dono','Invocação Especial','Efeito já ativado','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5043013,'Dragão Firewall',replace(replace('2+ monstros	\r\nUma vez enquanto estiver com a face para cima no campo (Efeito Rápido): você pode escolher monstros no campo e/ou no Cemitério até o número de monstros co-linkados a este card; devolva-os para a mão. \r\nSe um monstro para o qual este card apontar for destruído em batalha ou enviado para o Cemitério: você pode Invocar por Invocação-Especial 1 monstro Ciberso da sua mão. \r\nVocê só pode usar cada efeito de "Dragão Firewall" uma vez por turno.','\r',char(13)),'\n',char(10)),'Retornar à mão do dono','Invocação Especial','Efeito já ativado','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5050644,'Jardim do Aromági',replace(replace('Uma vez por turno, se você controlar um monstro "Aromági": você pode ganhar 500 PV e, além disso, todos os monstros que você controla ganham 500 de ATK e DEF até o final do próximo turno do seu oponente (mesmo que este card deixe o campo). \r\nSe um monstro "Aromági" com a face para cima que você controla for destruído em batalha ou por um efeito de card e enviado para o Cemitério: ganhe 1000 PV.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5052212,'Batalha Regulada',replace(replace('Remova de jogo 1 monstro Regulador do seu Cemitério. \r\nO monstro alvo com a face para cima que você controla ganha ATK igual ao ATK do monstro removido.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5053103,'Touro Guerreiro','Um monstro com tremendo poder que destrói seus inimigos com um único golpe do seu machado.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5063379,'Flaviano - Coliseu da Besta Gladiadora',replace(replace('Você pode descartar 1 card; adicione 1 monstro "Besta Gladiadora" do seu Deck à sua mão. \r\nQuando um monstro do oponente declarar um ataque: você pode Invocar por Invocação-Especial 1 monstro "Besta Gladiadora" do seu Deck, e ele não pode ser destruído em batalha. \r\nDurante a Fase Final, se um monstro "Besta Gladiadora" foi Invocado por Invocação-Especial do seu Deck neste turno: você pode Baixar 1 Armadilha "Gladiador" do seu Deck. \r\nVocê só pode usar cada efeito de "Flaviano - Coliseu da Besta Gladiadora" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Invocar por Invocação Especial do Deck','Baixar do Deck','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5067884,'Dinonévoa Espino',replace(replace('Escala de Pêndulo = 3\r\n[ Efeito de Pêndulo ]\r\nSe um ou mais outros cards "Dinonévoa" que você controla seriam destruídos em batalha ou por um efeito de card do oponente, em vez disso, você pode destruir este card.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nVocê pode oferecer como Tributo 1 outro monstro "Dinonévoa" e, depois, ativar 1 desses efeitos;\r\n● Este card pode atacar diretamente seu oponente neste turno.\r\n● Este card pode realizar um segundo ataque durante cada Fase de Batalha neste turno.','\r',char(13)),'\n',char(10)),'Usar o efeito de "Dinonévoa Espino" como substituição de destruição?','Ataque direto','Ataques múltiplos','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5068132,'Cigarra dos Sonhos',replace(replace('Se você controlar um monstro Inseto em Posição de Ataque, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Cigarra dos Sonhos" por Invocação-Especial uma vez por turno desta forma. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 monstro no campo; mude sua posição de batalha. \r\nVocê só pode usar este efeito de "Cigarra dos Sonhos" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5087128,'Dragão Projefoguette',replace(replace('Quando um efeito de um Monstro Link for ativado que escolha como alvo este card com a face para cima no campo (Efeito Rápido): você pode destruir este card e, depois, destrua 1 monstro na coluna em que este card estava e, se isso acontecer, destrua quaisquer monstros nas zonas adjacentes a esse card. \r\nDurante a Fase Final, se este card estiver no Cemitério porque foi destruído no campo, em batalha ou por um efeito de card e enviado para lá neste turno: você pode Invocar por Invocação-Especial 1 monstro "Foguette" do seu Deck, exceto "Dragão Projefoguette". \r\nVocê só pode usar cada efeito de "Dragão Projefoguette" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5088741,'Codificar Ignição',replace(replace('2 monstros de Nível 4	\r\nSe este card for Invocado por Invocação-Xyz: você pode adicionar 1 Monstro de Ritual Ciberso do seu Deck à sua mão. \r\nVocê pode desassociar 1 matéria deste card; Invoque por Invocação-Ritual 1 Monstro de Ritual da sua mão, ao oferecer como Tributo monstros da sua mão ou do campo cuja soma dos Níveis seja igual ou exceda seu Nível. \r\nSe este card for enviado para o Cemitério como Matéria Link: você pode adicionar 1 Armadilha "I.A." do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "Codificar Ignição" uma vez por turno.','\r',char(13)),'\n',char(10)),'Efeito de busca','Invocação Ritual','Adicionar à mão','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5109321,'Plataforma de Aterrissagem R.B.',replace(replace('Invoque por Invocação-Especial 1 monstro "R.B." do seu Deck/Deck Adicional com um nome diferente que o dos cards que você controla. \r\nSe um ou mais monstros "R.B." que você controla seriam destruídos em batalha ou por um efeito de card, em vez disso, você pode banir este card do seu Cemitério. \r\nVocê não pode Invocar por Invocação-Especial do Deck Adicional no turno em que ativar este card, exceto monstros Máquina com 1500 ou menos de ATK original.','\r',char(13)),'\n',char(10)),'Invocação Especial','Substituição de destruição','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5121528,'B.E.S. Derringer Core',replace(replace('Você pode revelar 1 outro monstro "B.E.S." na sua mão; Invoque este card por Invocação-Especial da sua mão e, depois, coloque 3 marcadores neste card. \r\nDurante a Fase Principal (Efeito Rápido): você pode remover 1 marcador deste card e ativar 1 desses efeitos;\r\n● Adicione 1 "Corrida para o Chefe" ou 1 Magia/Armadilha que o mencione, do seu Deck à sua mão.\r\n● Invoque por Invocação-Especial 1 monstro "B.E.S." de Nível 9 ou menos do seu Cemitério.	\r\nVocê só pode usar cada efeito de "B.E.S. Derringer Core" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Escolher um efeito','Efeito de busca','Invocação Especial','','','','','','','','','','','','');
INSERT INTO texts VALUES(5125629,'Mudança de Paradigma Perniciosa',replace(replace('Você pode ativar este card da sua mão pagando metade dos seus PV. \r\nAdicione a sua mão, ou coloque com a face para cima na sua Zona de Campo, 1 "Mundo Pernicioso" do seu Deck ou Cemitério, então Invoque por Invocação-Especial 1 monstro "Pernicioso(a)" do seu Deck ou Deck Adicional em Posição de Defesa, ignorando suas condições de invocação, então se seu oponente controlar um monstro com 2500 de ATK ou maior, todos os monstros com a face para cima que ele controla perdem 2500 de ATK até o final desse turno. \r\nVocê só pode ativar 1 "Mudança de Paradigma Perniciosa" por turno.','\r',char(13)),'\n',char(10)),'Ativar','Colocar com a face para cima','Ativar aplicando o efeito de "Mudança de Paradigma Perniciosa".','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5126490,'Neos Sábio',replace(replace('Não pode ser Invocado por Invocação-Normal ou Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao enviar 1 "Neos, o HERÓI do Elemento" com a face para cima e 1 "Yubel" com a face para cima que você controla para o Cemitério. \r\nNão pode ser destruído por efeitos de card. \r\nNo final da Etapa de Dano, se este card batalhou um monstro do oponente: cause dano ao seu oponente igual ao ATK desse monstro do oponente e, além disso, você ganha PV igual à DEF desse monstro do oponente.','\r',char(13)),'\n',char(10)),'Ganhar PV e causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5128859,'Neos Marino, o HERÓI do Elemento',replace(replace('"Neos, o HERÓI do Elemento" + "Golfinho Marinho Neoespacial"	\r\nPrimeiro deve ser Invocado por Invocação-Especial (do seu Deck Adicional) ao embaralhar os cards acima que você controla no Deck. \r\n(Você não usa "Polimerização".) \r\nUma vez por turno: Você pode destruir 1 card aleatório na mão do seu oponente.','\r',char(13)),'\n',char(10)),'Descartar da mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5130393,'Caçador do Milênio',replace(replace('Quando você sofrer 1000 ou mais de dano de batalha ou de efeito: você pode Invocar este card por Invocação-Especial da sua mão. \r\nVocê pode escolher 1 monstro no Cemitério do seu oponente, exceto um monstro com ATK ?; seu oponente pode selecionar 1 monstro do Deck dele, exceto um monstro com ATK ?. \r\nSe ele decidir não fazê-lo, ou se o monstro alvo tiver um ATK maior que o do monstro selecionado, Invoque o monstro alvo por Invocação-Especial no seu campo e, se isso acontecer, embaralhe o monstro selecionado de volta no Deck. \r\nCaso contrário, seu oponente adiciona o monstro selecionado à mão. \r\nVocê só pode usar cada efeito de "Caçador do Milênio" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Escolher 1 monstro do seu Deck?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5133471,'Ciclone das Galáxias',replace(replace('Escolha 1 Magia/Armadilha Baixada no campo; destrua-a. \r\nDurante sua Fase Principal, exceto no turno em que este card foi enviado para o Cemitério: você pode banir este card do seu Cemitério e, depois, escolha 1 Magia/Armadilha com a face para cima no campo; destrua-a. \r\nVocê só pode usar este efeito de "Ciclone das Galáxias" uma vez por turno.','\r',char(13)),'\n',char(10)),'Destruir uma Magia/Armadilha Baixada','Destruir uma Magia/Armadilha com a face para cima','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5141117,'A Espadalma Dragão do Abismo',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial pelo efeito de um monstro Wyrm. \r\nSe um monstro for banido por um efeito de card (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial do Cemitério (se ele estava lá quando o monstro foi banido) ou da mão (mesmo se ele não estava), mas bana-o quando ele deixar o campo. \r\nSe este card for Invocado por Invocação-Especial: você pode escolher 1 card na Zona do Campo e 1 monstro que seu oponente controla ou no Cemitério dele; bana-os. \r\nVocê só pode usar cada efeito de "A Espadalma Dragão do Abismo" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar este card por Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5148778,'Dragão Alado de Peçonha Insaciável',replace(replace('Escala de Pêndulo = 10\r\n[ Efeito de Pêndulo ]\r\nSempre que um ou mais monstros forem Invocados por Invocação-Especial no campo do seu oponente, coloque 1 Marcador de Predador nele e, se ele for de Nível 2 ou mais, ele se torna de Nível 1 enquanto tiver um Marcador de Predador.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\n1 Monstro de Fusão + 1 monstro "Asas Transparentes"	\r\nUma vez por turno, se seu oponente Invocar por Invocação-Especial um ou mais monstros com a face para cima (exceto durante a Etapa de Dano): você pode escolher 1 deles; este card ganha ATK igual ao ATK desse monstro e, se isso acontecer, os efeitos desse monstro são negados. \r\nEssas mudanças duram até o final deste turno. \r\nUma vez por turno, quando outro card ou seus efeitos forem ativados no campo (Efeito Rápido): você pode destruir 1 card no campo. \r\nSe este card na Zona de Monstros for destruído: você pode colocar este card na sua Zona de Pêndulo.','\r',char(13)),'\n',char(10)),'','Negar e aumentar ATK','Efeito de destruição','Colocar na Zona de Pêndulo','','','','','','','','','','','','');
INSERT INTO texts VALUES(5153769,'Vendaval Majespectro','Escolha 1 card "Majespectro" nas suas Zonas de Pêndulo; Invoque-o por Invocação-Especial.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5168381,'Falha Medonha do Arquidemônio','Se você controlar um monstro Demônio: escolha 1 card no campo; destrua-o e, depois, você pode enviar 1 monstro Demônio do seu Deck para o Cemitério.','Enviar para o Cemitério 1 monstro Demônio do seu Deck?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5177985,'Shiranui Mestre da Espada',replace(replace('Se este card estiver no seu Cemitério e você controlar 2 ou mais monstros "Shiranui" com nomes diferentes: você pode Invocar este card por Invocação-Especial, mas bana-o quando ele deixar o campo. \r\nSe este card for banido: você pode escolher 1 monstro Zumbi que você controla; ele ganha 600 de ATK até o final deste turno. \r\nVocê só pode usar cada efeito de "Shiranui Mestre da Espada" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5182107,'Samurai Superpesado Segurança',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode adicionar à sua mão 1 Monstro Pêndulo Máquina com a face para cima do seu Deck Adicional. \r\nSe você não tiver Magias/Armadilhas no seu Cemitério: você pode oferecer este card como Tributo; Invoque por Invocação-Especial 1 monstro Máquina de TERRA com 1500 ou menos de ATK da sua mão ou do Cemitério, exceto "Samurai Superpesado Segurança". \r\nVocê só pode usar cada efeito de "Samurai Superpesado Segurança" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5183693,'Amuleto da Ambição',replace(replace('Só pode ser equipado a um Monstro Normal. \r\nSe ele batalhar um monstro de maior Nível, o monstro equipado ganha 500 de ATK x a diferença entre os Níveis, apenas durante o cálculo de dano. \r\nQuando este card for enviado para o Cemitério: você pode colocá-lo no topo do seu Deck.','\r',char(13)),'\n',char(10)),'Colocar no topo do Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5186893,'Dragão Zumbi de Olhos Vermelhos',replace(replace('Você pode Invocar este card por Invocação-Tributo em Posição de Ataque ao oferecer como Tributo 1 monstro Zumbi. \r\nQuando este card destruir um monstro Zumbi em batalha e enviá-lo para o Cemitério: você pode Invocar esse monstro Zumbi por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Ofereça como jTributo 1 monstro Zumbi para Invocar','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5205146,'Rolo Compressor Infinisteira',replace(replace('Se um monstro Máquina de TERRA for oferecido como Tributo ou banido com a face para cima: você pode Invocar este card por Invocação-Especial do Cemitério (se ele estava lá quando o monstro foi oferecido como Tributo ou banido) ou da mão (mesmo se ele não estava), mas bana-o quando ele deixar o campo. \r\nVocê só pode usar este efeito de "Rolo Compressor Infinisteira" uma vez por turno. \r\nUm Monstro Xyz cujo Tipo original for Máquina e que tenha este card como matéria ganha este efeito.\r\n● Monstros com a face para cima que seu oponente controla são colocados em Posição de Defesa e, além disso, eles perdem 1000 de DEF.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5206415,'Senhordragão do Trovão',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro deve ser Invocado por Invocação-Especial (da sua mão) ao banir 1 monstro Trovão de Nível 8 ou menos da sua mão ou do campo com a face para cima, durante o turno em que o efeito de um monstro Trovão foi ativado na mão. \r\nUma vez por turno do oponente (Efeito Rápido): você pode banir 2 cards do seu Cemitério, incluindo um monstro Trovão e, depois, escolha 1 monstro Trovão que você controla; seu oponente não pode escolhê-lo como alvo de efeitos de card neste turno. \r\nUma vez por turno, durante sua Fase Final: você pode enviar 1 card "Dragão do Trovão" do seu Deck para o Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5208118,'Resolva seu Pêndulo',replace(replace('Uma vez por turno, durante a Fase de Apoio: coloque 1 Marcador T neste card. \r\nUma vez por turno: você pode escolher 1 Monstro Pêndulo na sua Zona de Monstros Principal; para cada Marcador T neste card, mova esse Monstro Pêndulo para uma Zona de Monstros adjacente (horizontal), 1 movimento por vez. \r\nDepois, quando você terminar de movê-los, destrua todos os Monstros de Fusão ou Xyz que seu oponente controla na mesma coluna (final), com um Nível/Classe igual ou menor que a Escala de Pêndulo desse monstro e, se isso acontecer, cause dano ao seu oponente igual ao ATK combinado que eles tinham no campo.','\r',char(13)),'\n',char(10)),'','Escolha o monstro a mover','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5220687,'Mega Hamster Super-Ágil','VIRE: Você pode Invocar por Invocação-Especial 1 monstro Besta de Nível 3 ou menos do seu Deck com a face para baixo em Posição de Defesa.','Invocação Especial','Invocar por Invocação Especial 1 monstro Besta de Nível 3 ou menor?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5230799,'Mágico Mosqueteiro Kidbrave',replace(replace('Durante o turno de qualquer duelista, você pode ativar Cards de Magia/Armadilha "Mágico(a) Mosquete" da sua mão. \r\nSe um Card de Magia/Armadilha for ativado na coluna deste card: você pode descartar 1 card "Mágico(a) Mosquete"; compre 2 cards. \r\nVocê só pode usar este efeito de "Mágico Mosqueteiro Kidbrave" uma vez por turno.','\r',char(13)),'\n',char(10)),'Descartar e comprar','Ativar aplicando o efeito de "Mágico Mosqueteiro Kidbrave".','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5237827,'Vylon Ohm','Se este card for Invocado por Invocação-Normal: escolha 1 Card de Magia de Equipamento no seu Cemitério; bana o alvo e, se isso acontecer, adicione-o à sua mão durante sua próxima Fase de Apoio.','Banir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5244497,'Cameraclope',replace(replace('Se este card atacar um monstro com a face para cima no campo, no começo da Etapa de Dano: destrua esse monstro. \r\nA DEF dele deve ser maior que o ATK deste card para que você possa ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5253985,'Cruzar Almas',replace(replace('Durante a Fase Principal: imediatamente depois que este efeito resolver, Invoque por Invocação-Tributo 1 monstro Besta Divina. \r\nAo fazê-lo, você pode oferecer como Tributo um ou mais monstros que seu oponente controla, mesmo que você não os controle, mas se você Invocar por Invocação-Tributo desta forma, aplique este efeito.\r\n● Até o final do próximo turno depois que este card resolver, você só pode ativar 1 card ou efeito por turno, sem contar os efeitos de monstros Besta Divina.	\r\nVocê só pode ativar 1 "Cruzar Almas" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5255013,'Caminho de Zefra',replace(replace('Ative este card apenas se você tiver 2 cards "Zefra" nas suas Zonas de Pêndulo, com Escalas de Pêndulo ativas de 1 e 7. \r\nSe este card for ativado: embaralhe todos os monstros que você controla no Deck, exceto monstros "Zefra". \r\nNenhum duelista pode Invocar monstros por Invocação-Especial, exceto da mão ou do Deck Adicional. \r\nEnquanto você tiver um ou mais cards nas suas Zonas de Pêndulo, este card não pode ser escolhido como alvo por efeitos de card. \r\nDestrua este card se um ou mais cards nas suas Zonas de Pêndulo forem destruídos.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5257687,'Mandíbulas da Morte Negra',replace(replace('VIRE: Ganhe controle de 1 monstro no Campo do seu adversário até ao fim deste turno. \r\nQuando o monstro controlado ataca, ele pode atacar diretamente os Life Points do seu adversário.','\r',char(13)),'\n',char(10)),'Tomar controle','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5259518,'Predaplanta Heliamforrinco',replace(replace('Se seu oponente controlar um monstro com um Marcador de Predador: você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe este card em posse do seu dono for destruído por um card do seu oponente: você pode escolher 1 monstro Dragão de TREVAS ou 1 monstro Planta de TREVAS no seu Cemitério, exceto "Predaplanta Heliamforrinco"; Invoque-o por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Predaplanta Heliamforrinco" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5265750,'Marinheiro Caveira','Um barco pirata que surge da neblina e afunda quaisquer embarcações navegando pelo mar.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5267507,'Imortal Terrestre Vermelho Nova',replace(replace('Só pode haver 1 monstro "Imortal Terrestre" no campo. \r\nDurante a Fase Principal (Efeito Rápido): você pode banir este card da sua mão ou do Cemitério; envie 1 monstro "Imortal Terrestre" ou "Dragão Vermelho Arquidemônio" da sua mão ou da Zona de Monstros com a face para cima para o Cemitério e, depois, você pode aplicar 1 desses efeitos.\r\n● Invoque por Invocação-Especial 1 monstro "Terrestre" do seu Deck ou Deck Adicional.\r\n● Invoque por Invocação-Especial 1 "Dragão Vermelho Nova" do seu Deck Adicional. \r\n(Isso é considerado uma Invocação-Sincro.)\r\nVocê só pode usar este efeito de "Imortal Terrestre Vermelho Nova" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Invocação Especial?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5284653,'Hordeum Maligno Oblívio-fátuo','Se este card batalhar um monstro, depois do cálculo de dano: negue os efeitos desse monstro (incluindo no Cemitério).','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5285665,'Neo-Homem-Bolha, o HERÓI do Elemento',replace(replace('Este card não pode ser Invocado por Invocação-Normal ou Baixado. \r\nEste card não pode ser Invocado por Invocação-Especial, exceto ao enviar um "Homem Bolha, o HERÓI do Elemento" que você controla e um "Metamorfose" da sua mão ao Cemitério. \r\nO nome deste card é considerado como "Homem Bolha, o HERÓI do Elemento" enquanto ele estiver com a face para cima no campo. \r\nDestrua um monstro do oponente que batalhar com este card no final da Etapa de Dano.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5288597,'Transmodificar',replace(replace('Envie 1 monstro com a face para cima que você controla para o Cemitério; Invoque por Invocação-Especial do seu Deck, 1 monstro com o mesmo Tipo e Atributo que esse monstro no Cemitério, mas de 1 Nível maior. \r\nVocê só pode ativar 1 "Transmodificar" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5291803,'Cronomalia Guardião Tula',replace(replace('Se houver um Card de Magia de Campo com a face para cima no campo, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode controlar 1 "Cronomalia Guardião Tula".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5298175,'Fada Fortuna Swee',replace(replace('Quando você comprar este card: você pode revelá-lo; Invoque-o por Invocação-Especial da sua mão. \r\nSe este card for Invocado por Invocação-Especial da mão: você pode escolher 1 outro monstro com a face para cima no campo; bana-o até a Fase de Apoio do seu próximo turno. \r\nVocê só pode usar cada efeito de "Fada Fortuna Swee" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5309481,'Rei Ha Des Renascido',replace(replace('"Zumbi Espalha-praga" + 1+ monstros Zumbi não-Reguladores	\r\nNegue os efeitos de Monstros de Efeito destruídos em batalha com monstros Zumbi que você controla.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5318639,'Tufão Espacial Místico','Escolha 1 Magia/Armadilha no campo; destrua o alvo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5318640,'Tufão Espacial Místico','Escolha 1 Magia/Armadilha no campo; destrua o alvo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5325155,'Tsukahagi, o Mayakashi Venenoso',replace(replace('Você só pode controlar 1 "Tsukahagi, o Mayakashi Venenoso". \r\nSe um ou mais monstros "Mayakashi" em sua posse, exceto "Tsukahagi, o Mayakashi Venenoso", forem destruídos em batalha ou por um efeito de card do oponente, enquanto este card estiver no Cemitério: você pode Invocar este card por Invocação-Especial. \r\nVocê não pode Invocar monstros por Invocação-Especial do Deck Adicional no turno em que ativar este efeito, exceto monstros "Mayakashi".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5325424,'Dragaocarnação','Escolha 1 de seus monstros do Tipo Dragão banidos; adicione o alvo à sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5329790,'Gardna Protocolo',replace(replace('2 monstros Ciberso	\r\nOs monstros do seu oponente não podem escolher monstros para os quais este card apontar como alvo de ataques. \r\nNa primeira vez que este card seria destruído em batalha a cada turno, ele não é destruído e você não sofre dano de batalha dessa batalha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5338223,'Evo-Força',replace(replace('Ofereça como Tributo 1 monstro "Evoltil"; Invoque por Invocação-Especial 1 monstro "Evolssauro" do seu Deck. \r\n(Isso é considerado como uma Invocação-Especial pelo efeito de um monstro "Evoltil".)','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5352328,'Exoirmã Sofia',replace(replace('Se você controlar outro monstro "Exoirmã": você pode comprar 1 card e, depois, se você controlar "Exoirmã Irene", você ganha 800 PV. \r\nSe seu oponente mover um ou mais cards para fora de qualquer Cemitério (exceto durante a Etapa de Dano): você pode Invocar por Invocação-Especial do seu Deck Adicional, 1 Monstro Xyz "Exoirmã" usando este card com a face para cima que você controla como matéria. \r\n(Isso é considerado uma Invocação-Xyz.) \r\nVocê só pode usar cada efeito de "Exoirmã Sofia" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Invocação Xyz','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5361647,'Boxeador Obstinado Queixo de Vidro',replace(replace('Se este card for escolhido como alvo de um ataque: destrua este card. \r\nQuando este card for enviado para o Cemitério por um efeito de card: você pode escolher 1 monstro "Boxeador Obstinado" no seu Cemitério, exceto "Boxeador Obstinado Queixo de Vidro"; adicione-o à sua mão.','\r',char(13)),'\n',char(10)),'Destruir','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5361816,'Nobre Cavaleiro Pellinore',replace(replace('Você pode escolher 1 Magia de Equipamento "Armas Nobres" equipada a este card e 1 monstro com a face para cima que seu oponente controla; destrua-os e, depois, compre 1 card e, além disso, este card não pode atacar pelo resto deste turno. \r\nVocê só pode usar este efeito de "Nobre Cavaleiro Pellinore" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5368615,'Giroide a Vapor','"Giroide" + "Vaporoide"','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5370235,'Quimera Cibersombria',replace(replace('Você pode descartar 1 Magia/Armadilha; adicione 1 "Vínculo de Poder" do seu Deck à sua mão, você só pode usar monstros Dragão ou Máquina "Ciber" como Matéria de Fusão neste turno e, além disso, uma vez quando você Invocar por Invocação-Fusão neste turno, você também pode banir um ou mais monstros do seu Cemitério como matéria. \r\nSe este card for enviado para o Cemitério: você pode enviar 1 monstro "Cibersombrio(a)" do seu Deck para o Cemitério, com um nome diferente que o dos cards no seu Cemitério. \r\nVocê só pode usar cada efeito de "Quimera Cibersombria" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5371656,'Espada do Come Alma',replace(replace('Este card pode apenas equipar um Monstro Normal de Nível 3 ou menos no seu Campo. \r\nQuando você activar este card, ofereça como Tributo todos os Montros Normais (exceto Fichas) no seu Campo, exceto o monstro equipado. \r\nAumente o ATK do monstro equipado em 1000 pontos por cada Monstro Normal que você ofereceu como Tributo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5373478,'Dragão Cibernético Zwei',replace(replace('O nome deste card se torna "Dragão Cibernético" enquanto estiver no Cemitério. \r\nUma vez por turno: você pode revelar 1 Magia na sua mão; o nome deste card se torna "Dragão Cibernético" até a Fase Final. \r\nSe este card atacar um monstro do oponente, ele ganha 300 de ATK apenas durante a Etapa de Dano.','\r',char(13)),'\n',char(10)),'Considere o nome deste card como "Dragão Cibernético"','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5376159,'Reino Vermelho',replace(replace('Se você controlar um Monstro Sincro de Nível 8 ou mais: bana todos os monstros no campo, exceto o(s) monstro(s) de maior Nível e, além disso, até o final deste turno, os monstros com a face para cima restantes no campo não são afetados por outros efeitos de card, exceto seus próprios. \r\nSe um Monstro Sincro Dragão de TREVAS for Invocado por Invocação-Sincro no seu campo enquanto este card estiver no seu Cemitério: você pode adicionar este card à sua mão. \r\nVocê só pode usar este efeito de "Reino Vermelho" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5380979,'Boas-vindas a Labrinto',replace(replace('Invoque por Invocação-Especial 1 monstro "Labrinto" do seu Deck e, além disso, até o final do próximo turno depois que este card resolver, você não pode Invocar por Invocação-Especial do Deck ou Deck Adicional, exceto monstros Demônio. \r\nSe um monstro deixar o campo pelo efeito de uma Armadilha Normal sua, enquanto este card estiver no seu Cemitério, exceto no turno em que foi enviado para lá: você pode Baixar este card. \r\nVocê só pode usar cada efeito de "Boas-vindas a Labrinto" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5388481,'Soldado do Fogo Negro #1','Um especialista em explosivos de uma força especial de elite.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5399521,'Guerreiro Sinfônico Miccro',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nA não ser que você tenha um card "Guerreiro Sinfónico" na sua outra Zona de Pêndulo, a Escala de Pêndulo deste card se torna 4. \r\nUma vez por turno, durante sua Fase Final: você pode escolher 1 dos seus monstros "Guerreiro Sinfónico" banidos; adicione-o à sua mão.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nVocê pode Invocar este card por Invocação-Especial (da sua mão) ao remover 3 Marcadores Sinfônicos do seu campo. \r\nDepois que você Invocar este card por Invocação-Normal ou Especial, você pode Invocar por Invocação-Normal 1 monstro durante sua Fase Principal neste turno, em adição à sua Invocação-Normal/Baixar (padrão). \r\n(Você só pode se aproveitar deste efeito uma vez por turno.)','\r',char(13)),'\n',char(10)),'Invocar pelo efeito de "Guerreiro Sinfônico Miccro"','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5402805,'Enfurecido dos Tenyi','2+ monstros, incluindo um Monstro Link','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5405694,'Soldado do Lustro Negro','Você pode Invocar este card por Invocação-Ritual com "Ritual do Lustro Negro".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5405695,'Soldado do Lustro Negro','O mais poderoso dos guerreiros, cujas habilidades se igualam às do Dragão Branco de Olhos Azuis.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5405696,'Soldado do Lustro Negro','Você pode Invocar este card por Invocação-Ritual com "Ritual do Lustro Negro".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5414777,'Mundo dos Espíritos',replace(replace('Quando este card for ativado: você pode adicionar 1 monstro que mencione "Dragão Fada Antigo" do seu Deck à sua mão. \r\nVocê só pode ativar os seguintes efeitos enquanto você controlar um Monstro Sincro Dragão de LUZ de Nível 7 ou mais. \r\nSempre que um ou mais monstros forem Invocados por Invocação-Especial em Posição de Ataque: coloque-o em Posição de Defesa. \r\nUma vez por turno, durante a Fase Final: destrua todos os monstros em Posição de Ataque no campo do duelista do turno. \r\nVocê só pode ativar 1 "Mundo dos Espíritos" por turno.','\r',char(13)),'\n',char(10)),'Ativar','Mudar para Posição de Defesa','Destruir','Adicionar este card à mão?','','','','','','','','','','','','');
INSERT INTO texts VALUES(5431722,'Chama Caudraco',replace(replace('Escolha 1 Magia com a face para cima no campo; negue seus efeitos (até o final deste turno) e, depois, você pode colocar 1 card "Caudraco" do seu Cemitério ou banimento no fundo do Deck, exceto "Chama Caudraco" e, depois, compre 1 card. \r\nVocê só pode ativar 1 "Chama Caudraco" por turno.','\r',char(13)),'\n',char(10)),'','Recuperar e comprar 1 card?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5434080,'Cavaleiro Sem Cabeça','O espírito assombrado de um cavaleiro falsamente acusado que vaga em busca da verdade e da justiça.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5438492,'Guerreira das Terras Ermas','Quando este card for destruído em batalha e enviado para o Cemitério: você pode Invocar por Invocação-Especial 1 monstro Guerreiro de TERRA com 1500 ou menos de ATK do seu Deck, em Posição de Ataque.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5439384,'Nascimento da Chama Proeminente',replace(replace('Escolha 2 monstros de FOGO (1 Regulador e 1 não-Regulador) com 200 de DEF no seu Cemitério; bana os dois monstros e, se isso acontecer, Invoque por Invocação-Especial 1 Monstro Sincro de FOGO do seu Deck Adicional cujo Nível seja igual à soma dos Níveis desses monstros. \r\nVocê só pode ativar 1 "Nascimento da Chama Proeminente" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5464695,'Inpachi em Chamas','Um espírito de madeira perverso, agora a arder em chamas. O seu ataque de fogo é poderoso, mas em breve ele não será nada a não ser cinzas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5466615,'Confronto Miutante',replace(replace('Quando você ativar este card: você pode escolher 1 Monstro de Efeito que seu oponente controla; bana 1 monstro "Miutante" do seu Cemitério e, se isso acontecer, negue os efeitos dele até o final deste turno (mesmo que este card deixe o campo). \r\nQuando um monstro "Miutante" seu de Nível 8 ou mais destruir um monstro do oponente em batalha: você pode comprar 1 card. \r\nVocê só pode usar este efeito de "Confronto Miutante" uma vez por turno. \r\nVocê só pode ativar 1 "Confronto Miutante" por turno.','\r',char(13)),'\n',char(10)),'Negar o efeito de um monstro do oponente?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5479217,'Impacto Jurrac','Se você controlar um monstro Dinossauro com 2500 de ATK ou mais: destrua todos os cards no campo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5489987,'Flor Cardian de Cerejeira com Cortina',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro deve ser Invocado por Invocação-Especial por seu próprio efeito. \r\nVocê pode revelar este card na sua mão; compre 1 card e, se isso acontecer, mostre-o e, depois, Invoque este card por Invocação-Especial se o card comprado for um monstro "Flor Cardian". \r\nCaso contrário, envie-o e este card para o Cemitério. \r\nDurante a Etapa de Dano de qualquer duelista, quando seu monstro "Flor Cardian" batalhar um monstro do oponente: você pode descartar este card; seu monstro que está batalhando ganha 1000 de ATK até o final deste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5494820,'Laser Cyclon',replace(replace('Este card pode apenas equipar "Gradius". \r\nAumente o ATK do "Gradius" equipado em 300 pontos. \r\nQuando o "Gradius" ataca com um ATK superior a DEF do monstro que esteja em Posição de Defesa, inflija a diferença aos Life Points do seu adversário como dano de batalha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5498296,'Scarr, Batedor do Mundo Negro','Se este card for destruído em batalha e enviado para o Cemitério: adicione 1 monstro "Mundo Negro" de Nível 4 ou menos do seu Deck à sua mão.','Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5506791,'Gato Majespectro - Nekomata',replace(replace('Escala de Pêndulo = 2\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nQuando este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 card "Majespectro" do seu Deck à sua mão durante a Fase Final deste turno. \r\nVocê só pode usar este efeito de "Gato Majespectro - Nekomata" uma vez por turno. \r\nNão pode ser escolhido como alvo ou destruído por efeitos de card do seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5519829,'Conselheira Lily','Quando este card for enviado ao Cemitério para uma Invocação-Sincro, você pode pagar 500 PV para fazer com que esse Monstro Sincro ganhe 1000 de ATK até a Fase Final.','Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5524387,'Marincesa Pedra Marmoreada',replace(replace('2+ monstros de ÁGUA	\r\nVocê pode escolher 1 card "Marincesa" no seu Cemitério, exceto "Marincesa Pedra Marmoreada"; adicione-o à sua mão. \r\nVocê só pode usar este efeito de "Marincesa Pedra Marmoreada" uma vez por turno. \r\nQuando um monstro do oponente declarar um ataque: você pode enviar 1 monstro "Marincesa" da sua mão para o Cemitério; nessa batalha, monstros não podem ser destruídos em batalha e, além disso, você não sofre dano de batalha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5530780,'Exoirmã Gibrine',replace(replace('2 monstros de Nível 4	\r\nNão pode ser destruído pelos efeitos ativados de monstros Invocados por Invocação-Especial do Cemitério. \r\nVocê só pode usar cada um dos seguintes efeitos de "Exoirmã Gibrine" uma vez por turno. \r\nSe você controlar este card que foi Invocado por Invocação-Xyz neste turno usando um monstro "Exoirmã" como matéria (Efeito Rápido): você pode escolher 1 Monstro de Efeito que seu oponente controla; negue seus efeitos até o final deste turno. \r\nVocê pode desassociar 1 matéria deste card; pelo resto deste turno, todos os Monstros Xyz que você controla ganham 800 de ATK.','\r',char(13)),'\n',char(10)),'Negar os efeitos de um monstro do oponente','Aumentar ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5554990,'Wattberyx','Se este card causar dano de batalha ao seu oponente em um ataque direto: descarte 1 card aleatório da mão de seu oponente.','Descartar 1 card','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5556499,'Fortaleza Autômata',replace(replace('Você pode descartar um ou mais monstros Máquina cuja soma dos Níveis seja igual a 8 ou mais e, depois, Invoque este card por Invocação-Especial (da sua mão ou do Cemitério). \r\nSe este card for destruído em batalha e enviado para o Cemitério: escolha 1 card que seu oponente controla; destrua o alvo. \r\nAntes de resolver um efeito de monstro do oponente que escolha como alvo este card com a face para cima, olhe a mão do seu oponente e descarte 1 card da mão dele.','\r',char(13)),'\n',char(10)),'Destrua 1 card que seu oponente controla','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5556668,'Troca','Os dois duelistas revelam suas mãos e adicionam à sua própria mão 1 card da mão do outro.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5559570,'Orgulho de Junho de Elfnota',replace(replace('1 Regulador + 1 monstro Mago não-Regulador	\r\nEnquanto este card estiver na Zona de Monstros Principal central, nenhum duelista pode declarar ataques, exceto com monstros em suas Zonas de Monstros Principais centrais. \r\nDurante a Fase Principal, se este card estiver na Zona de Monstros Principal central (Efeito Rápido): você pode devolver este card para o Deck Adicional e, se isso acontecer, Invoque por Invocação-Especial até 1 monstro "Elfnota" cada da sua mão, do Deck e do Cemitério. \r\nVocê só pode usar este efeito de "Orgulho de Junho de Elfnota" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5560911,'Destrudo, o Frisson do Dragão Perdido',replace(replace('Se este card estiver na sua mão ou no Cemitério: você pode pagar metade dos seus PV e, depois, escolher 1 monstro que você controla de Nível 6 ou menos; Invoque este card por Invocação-Especial e, se isso acontecer, o Nível deste card é reduzido pelo Nível do monstro alvo e, além disso, coloque este card no fundo do Deck se ele deixar o campo. \r\nVocê só pode usar este efeito de "Destrudo, o Frisson do Dragão Perdido" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5562461,'Ilusão Sombria','Quando um Card de Magia/Armadilha ou efeito de monstro, for ativado que escolha como alvo um monstro de TREVAS no campo: negue a ativação e, se isso acontecer, destrua esse card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5574510,'Shateki',replace(replace('Você pode descartar 1 card e, depois, escolha 1 monstro que seu oponente controla com um Nível; lance um dado de seis faces e aplique este efeito de acordo com o resultado.\r\n● Maior que o seu Nível: Destrua esse monstro e, depois, você pode adicionar 1 monstro com o mesmo Nível original do seu Deck à sua mão e, além disso, você não pode ativar o efeito de "Shateki" pelo resto deste turno.\r\n● Igual ou menor que o seu Nível: Reduza o Nível desse monstro em 1 (mesmo que este card deixe o campo).','\r',char(13)),'\n',char(10)),'','Adicionar aquele monstro à mão?','Neste turno, você não pode ativar o primeiro efeito de "Shateki"','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5577149,'Cadete Guarda de Batalha',replace(replace('Todos os monstros "Guarda de Batalha" que você controla ganham 500 de ATK. \r\nVocê só pode usar cada um dos seguintes efeitos de "Cadete Guarda de Batalha" uma vez por turno. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 "Banquete Selvagem NV5" do seu Deck à sua mão. \r\nVocê pode oferecer este card como Tributo; Invoque por Invocação-Especial 1 monstro Guerreiro de Nível 8 da sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5577649,'Batida de Restolhos',replace(replace('Ative apenas quando um monstro "Restolhos" que você controla for destruído e enviado para o Cemitério. \r\nDestrua todos os Cards de Magia/Armadilha com a face para cima no campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5592689,'Lótus de Samsara',replace(replace('Durante sua Fase Final, se você não controlar nenhum Card de Magia ou Armadilha, você pode Invocar este card por Invocação-Especial do seu Cemitério com a face para cima em Posição de Ataque. \r\nO controlador deste card sofre 1000 de dano durante cada uma de suas Fases de Apoio.','\r',char(13)),'\n',char(10)),'Invocação Especial','Causar dano','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5600127,'Dragonete-Lombriga Humanoide','"Dragonete-Lombriga" + "Limo Humanoide"','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5605529,'Chelta Vaalmônica',replace(replace('Aplique 1 desses efeitos. \r\nA não ser que você tenha um card "Vaalmônica" na sua Zona de Pêndulo, seu oponente seleciona o efeito.\r\n● Ganhe 500 PV e, depois, você pode colocar 1 card da sua mão no fundo do Deck e, depois, compre 2 cards.\r\n● Sofra 500 de dano e, depois, você pode adicionar 1 Magia/Armadilha "Vaalmônica" do seu Deck à sua mão, exceto "Chelta Vaalmônica".	\r\nVocê só pode ativar 1 "Chelta Vaalmônica" por turno.','\r',char(13)),'\n',char(10)),'','Ganhe 500 PV','Receba 500 de dano','Embaralhar sua mão no Deck e depois comprar 1 card?','Adicionar 1 carta do seu Deck à sua mão?','','','','','','','','','','','');
INSERT INTO texts VALUES(5606466,'Buraco Armadilha de uma D.D.','Quando seu oponente Baixar exatamente 1 monstro (e nenhum outro card): escolha esse monstro Baixado e 1 monstro que você controla; destrua os alvos e, se isso acontecer, bana-os.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5609226,'Barreira Reguladora',replace(replace('Escolha 1 monstro Regulador com a face para cima que você controla. \r\nEsse monstro não pode ser destruído em batalha ou por efeitos de card até a Fase Final do próximo turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5611760,'Ponte Arco-Íris da Salvação',replace(replace('Se houver 2 ou mais Tipos de Monstro diferentes dentre os monstros de Nível 10 ou mais no campo: embaralhe no Deck todos os cards, exceto este, das mãos, dos campos e dos Cemitérios dos dois duelistas e, depois, cada duelista compra 5 cards. \r\nVocê pode banir este card do seu Cemitério; adicione 1 monstro "Fera Cristalina" e 1 Magia de Campo do seu Deck à sua mão. \r\nVocê só pode aplicar cada efeito de "Ponte Arco-Íris da Salvação" uma vez por Duelo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5614808,'Baleia de Aura Branca',replace(replace('1 Regulador de ÁGUA + 1+ monstros não-Reguladores de ÁGUA	\r\nQuando este card for Invocado por Invocação-Sincro: você pode destruir todos os monstros em Posição de Ataque do seu oponente. \r\nEste card pode realizar até 2 ataques contra monstros durante cada Fase de Batalha. \r\nSe este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante. \r\nSe este card em sua posse for destruído por um card do oponente e enviado para o seu Cemitério: você pode banir 1 outro monstro de ÁGUA do seu Cemitério; Invoque este card por Invocação-Especial como um Regulador.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5616412,'Murro da Destruição',replace(replace('Quando o ATK de um monstro atacante no Campo do seu adversário é menor que a DEF do monstro atacado no seu Campo, em Posição de Defesa, destrua o monstro atacante. \r\nO Cálculo do Dano é aplicado normalmente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5628232,'Pinguim Voador','Um pinguim muito raro que voa com orelhas em forma de asas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5640330,'Necromante Hannibal',replace(replace('Se este card for Invocado por Invocação-Normal: coloque 1 Marcador de Magia nele (máx. 1). \r\nVocê pode remover 1 Marcador de Magia deste card e, depois, escolha 1 Armadilha com a face para cima no campo; destrua o alvo.','\r',char(13)),'\n',char(10)),'Colocar um marcador','Destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5641251,'F.A. Empate Apertado',replace(replace('Quando um monstro do oponente declarar um ataque direto: você pode Invocar por Invocação-Especial 1 monstro "F.A." do seu Deck. \r\nVocê só pode usar este efeito de "F.A. Empate Apertado" uma vez por turno. \r\nUma vez por batalha, se um monstro "F.A." seu batalhar um monstro do oponente, antes do cálculo de dano: você pode fazer com que os dois duelistas lancem um dado de seis faces. \r\nSe o seu resultado for maior, até o final deste turno, aumente em 4 o Nível do seu monstro que está batalhando (mesmo que este card deixe o campo). \r\nSe o seu resultado for menor, destrua seu monstro que está batalhando. \r\nEm caso de empate, os dois duelistas lançam novamente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5645210,'Vênus Esplêndida',replace(replace('Todos os monstros não-Fada perdem 500 de ATK/DEF. \r\nA ativação e os efeitos de Cards de Magia/Armadilha ativados no seu campo não podem ser negados.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5650082,'Força do Espelho Tempestuosa','Quando um monstro do oponente declarar um ataque: devolva todos os monstros em Posição de Ataque do seu oponente para a mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5672432,'Renascimento do Camarartista','Se um ou mais monstros que você controla forem destruídos em batalha ou por um efeito de card: Invoque por Invocação-Especial 1 monstro "Camarartista" da sua mão ou Cemitério.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5697558,'A Cidade Oculta',replace(replace('Quando este card for ativado: você pode adicionar 1 monstro "Subterror" do seu Deck à sua mão. \r\nUma vez por turno: você pode colocar 1 monstro "Subterror" com a face para baixo e em Posição de Defesa que você controla, com a face para cima em Posição de Ataque ou de Defesa. \r\nUma vez por turno, quando um monstro do oponente declarar um ataque: você pode colocar 1 monstro "Subterror" com a face para baixo e em Posição de Defesa que você controla, com a face para cima em Posição de Ataque ou de Defesa e, depois, você pode negar o ataque. \r\nVocê só pode ativar 1 "A Cidade Oculta" por turno.','\r',char(13)),'\n',char(10)),'Adicionar à sua mão 1 monstro "Subterror"?','Mudar a posição de batalha','Negar o ataque?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5703682,'Thousand Energy',replace(replace('Aumente o ATK e DEF original de todos os Monstros Normais de Nível 2 no seu Campo com a face para cima em 1000 pontos. \r\nDestrúa todos os Monstros Normais de Nível 2 no seu Campo durante a End Phase.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5728014,'Um Rival Aparece!',replace(replace('Escolha 1 monstro no Campo do seu adversário com a face para cima. \r\nInvoque, por Invocação-Especial, da sua mão, 1 monstro do mesmo Nível do monstro escolhido.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5758500,'Libertar Almas','Escolha até 5 cards em quaisquer Cemitérios; bana-os.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5763020,'Ídolo Chorão','Você pode banir 1 Regulador do seu Cemitério; Invoque este card por Invocação-Especial da sua mão.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5772618,'Alta-Velocidaroide Pipagonete',replace(replace('1 Máquina Regulador de VENTO + 1+ monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro: você pode ativar 1 desses efeitos;\r\n● Destrua todos os outros cards no campo.\r\n● Negue os efeitos de todos os cards com a face para cima que seu oponente controla atualmente.	\r\nSe este card em sua posse for enviado para o seu Cemitério por um card do oponente: você pode adicionar 1 monstro "Velocidaroide" do seu Deck à sua mão.\r\nVocê só pode usar cada efeito de "Alta-Velocidaroide Pipagonete" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar o efeito escolhido','Destrua todos os cards no campo exceto esta carta','Negue os efeitos de todos os cards com a face para cima que seu oponente controla','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5779502,'Oprimido',replace(replace('Durante o seu turno, negue os efeitos de todos os monstros com a face para cima que seu oponente controla. \r\nDurante o turno do seu oponente, negue os efeitos de todos os monstros com a face para cima que você controla.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5780210,'Ressonador da Criação','Se você controlar um Monstro Sincro de Nível 8 ou mais, você pode Invocar este card por Invocação-Especial (da sua mão).','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5786513,'Silenciar Turno',replace(replace('Escolha 1 monstro com a face para cima que você controla; aumente o Nível dele em 3 e, além disso, se você ativou este card em resposta à ativação de um efeito de monstro do seu oponente, enquanto você controlar "Sarcófago Brilhante" e um monstro que o mencione, negue esse efeito do oponente. \r\nDurante o cálculo de dano, se um monstro seu que mencione "Sarcófago Brilhante" batalhar: você pode banir este card do seu Cemitério; encerre a Fase de Batalha. \r\nVocê só pode ativar 1 "Silenciar Turno" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5795882,'Domínio do Vampiro',replace(replace('Uma vez por turno: você pode pagar 500 PV; durante sua Fase Principal deste turno, você pode Invocar por Invocação-Normal 1 monstro "Vampiro(a)" em adição à sua Invocação-Normal/Baixar (padrão). \r\n(Mesmo que este card deixe o campo. Você só pode se aproveitar deste efeito uma vez por turno.) \r\nSempre que um monstro "Vampiro(a)" seu causar dano de batalha ao seu oponente: ganhe esse mesmo valor de PV.','\r',char(13)),'\n',char(10)),'','','Invocar pelo efeito de "Domínio do Vampiro"','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5795980,'Ataque dos Monarcas',replace(replace('Você pode oferecer como Tributo 1 monstro com a face para cima de Nível 5 ou mais Invocado por Invocação-Normal/Baixado e, depois, escolher 1 card com a face para cima no campo; negue seus os efeitos e, depois, compre 1 card. \r\n(Os efeitos permanecem negados até o final deste turno). \r\nDurante sua Fase Principal, se este card estiver no seu Cemitério: você pode banir este card e, depois, declarar 1 Atributo; até o final deste turno, todos os monstros com a face para cima atualmente no campo se tornam desse Atributo.','\r',char(13)),'\n',char(10)),'Negar o efeito','Alterar Atributo','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5800323,'Poplar da Floresta Branca',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Especial: você pode escolher 2 monstros "Floresta Branca" no seu Cemitério; coloque-os com a face para cima nas Zonas de Magias & Armadilhas dos seus donos como Magias Contínuas. \r\nDurante a Fase Principal do seu oponente, você pode (Efeito Rápido): imediatamente depois que este efeito resolver, Invoque por Invocação-Sincro usando este card que você controla. \r\nVocê só pode usar cada efeito de "Poplar da Floresta Branca" uma vez por turno.','\r',char(13)),'\n',char(10)),'Colocar na Zona de Magias/Armadilhas','Invocação Sincro','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5817857,'Golungulado de Koa''ki Meiru',replace(replace('Durante cada uma das suas Fases Finais, destrua este card a não ser que você envie 1 "Núcleo de Ferro de Koa''ki Meiru" da sua mão para o Cemitério ou revele 1 monstro do Tipo Zumbi na sua mão. \r\nSe um monstro "Koa''ki Meiru" que você controla seria destruído em batalha ou por um efeito de card, em vez disso, você pode remover de jogo 1 monstro "Koa''ki Meiru" no seu Cemitério.','\r',char(13)),'\n',char(10)),'Escolha 1 "Núcleo de Ferro de Koa''ki Meiru" para enviar para o Cemitério','Revele 1 monstro Zumbi ao seu oponente','Destruir "Golungulado de Koa''ki Meiru"','Usar o efeito de "Golungulado de Koa''ki Meiru" em vez de ser destruído?','','','','','','','','','','','','');
INSERT INTO texts VALUES(5818294,'Bujingi Tartaruga','Durante o turno de qualquer duelista, quando um card ou efeito que escolher como alvo um monstro "Bujin" que você controla for ativado (exceto durante a Etapa de Dano): você pode banir este card do seu Cemitério; negue o efeito.','Negar o efeito','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5818798,'Gazelle, o Rei das Bestas Místicas',replace(replace('Este monstro se move tão depressa, que aos olhos mortais parece uma ilusão.	\r\n\r\n(Este card deve ser sempre considerado como um card "Besta Fantasma".)','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5821478,'Dragão Bomba Topológica',replace(replace('2+ Monstros de Efeito	\r\nSe outro monstro for Invocado por Invocação-Especial em uma zona para a qual um Monstro Link apontar, enquanto este monstro estiver no campo: destrua todos os monstros nas Zonas de Monstros Principais e, além disso, seus outros monstros não podem atacar pelo resto deste turno. \r\nDepois do cálculo de dano, se este card atacou um monstro do oponente: cause dano ao seu oponente igual ao ATK original desse monstro do oponente.','\r',char(13)),'\n',char(10)),'Destrua todos os monstros na Zona de Monstros Principal','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5829717,'Mago Negro, o Cavaleiro da Magia do Dragão',replace(replace('"Mago Negro" + 1 monstro Dragão ou Guerreiro de Nível 7 ou mais	\r\nSe um monstro seu atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente. \r\nUma vez por turno, quando um monstro seu destruir um monstro do oponente em batalha: você pode causar dano ao seu oponente igual ao ATK original do monstro destruído. \r\nSe este card for destruído: você pode Invocar por Invocação-Especial tanto 1 "Mago Negro" quanto 1 "Gaia, o Matador de Dragões" da sua mão, do Deck, do Deck Adicional e/ou do Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5832914,'Maleta Toon','Quando seu oponente Invocar um ou mais monstros enquanto você controlar um monstro Toon: embaralhe esse(s) monstro(s) no Deck.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5833312,'Academia de Duelos',replace(replace('Este card ganha esses efeitos de acordo com os Tipos de Monstros no campo.\r\n● Guerreiro, Besta ou Piro: Uma vez por turno, se você ativar um Card de Armadilha (exceto durante a Etapa de Dano): você pode escolher 1 card que seu oponente controla; destrua-o.\r\n● Dinossauro, Serpente Marinha ou Trovão: Uma vez por turno, se você ativar um Card de Magia (exceto durante a Etapa de Dano): você pode causar 1000 de dano ao seu oponente.\r\n● Máquina, Fada ou Demônio: Uma vez por turno, se você ativar um efeito de monstro (exceto durante a Etapa de Dano): você pode escolher 1 monstro com a face para cima que você controla; ele ganha 1000 de ATK (mesmo que este card deixe o campo).','\r',char(13)),'\n',char(10)),'Se uma Armadilha for ativada: destrua 1 card','Se uma Magia for ativada: cause 1000 de dano','Se um efeito de monstro for ativado: aumentar ATK','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5833929,'Melffy Godmommy',replace(replace('3+ monstros Besta de Nível 2	\r\nUma vez por turno, você também pode Invocar "Melffy Godmommy" por Invocação-Xyz ao usar "Melffy Mommy" que você controla (transfira as matérias dele). \r\nSe este card for Invocado por Invocação-Especial: você pode adicionar 1 Magia/Armadilha "Melffy" do seu Deck ou Cemitério à sua mão. \r\nGanha ATK igual ao ATK e DEF combinados dos monstros "Melffy" associados a ele. \r\nVocê pode desassociar 5 matérias deste card; devolva todos os cards que seu oponente controla para a mão.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Xyz usando {CARD} como matéria?','Adicionar à mão','Retornar para a mão','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5846183,'Utensilhor Carbuntor',replace(replace('Durante o cálculo de dano, se um monstro "Utensilhor" que você controla batalhar um monstro do oponente (Efeito Rápido): você pode descartar este card; nessa batalha, esse monstro que você controla não pode ser destruído e, além disso, você não sofre dano de batalha. \r\nSe um ou mais monstros "Utensilhor" que você controla seriam destruídos por um efeito de card, em vez disso, você pode banir este card do seu campo ou Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5848934,'Feiticeira Psíquica Serena',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro: você pode pagar 1000 PV; Baixe 1 Magia Normal ou Rápida "Teleporte" do seu Deck, Cemitério ou banimento. \r\nSe este card Invocado por Invocação-Sincro for enviado para o Cemitério: você pode escolher 1 card que seu oponente controla, ou escolher 2 se você controlar um monstro Psíquico (de Fusão ou Sincro); devolva esse(s) card(s) para a mão. \r\nVocê só pode usar cada efeito de "Feiticeira Psíquica Serena" uma vez por turno.','\r',char(13)),'\n',char(10)),'Baixar','Retornar para a mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5851097,'O Vazio da Vaidade',replace(replace('Nenhum duelista pode Invocar monstros por Invocação-Especial. \r\nSe um card for enviado do Deck ou do campo para o seu Cemitério: destrua este card.','\r',char(13)),'\n',char(10)),'Destruir este card','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5852388,'Xeno Meteossauro',replace(replace('Se um ou mais cards forem destruídos em batalha ou por um efeito de card: você pode Invocar este card por Invocação-Especial da sua mão. \r\nDurante sua Fase Principal: você pode destruir 1 monstro Dinossauro na sua mão ou no campo e, depois, Invoque por Invocação-Especial 1 Monstro Normal Dinossauro da sua mão ou do Deck e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto monstros Dragão, Dinossauro, Serpente Marinha ou Wyrm. \r\nVocê só pode usar cada efeito de "Xeno Meteossauro" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invoque este card por Invocação Especial da sua mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5861892,'Força Arcana EX - O Senhor da Luz',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao enviar 3 monstros que você controla para o Cemitério e não pode ser Invocado por Invocação-Especial de nenhuma outra forma. \r\nQuando este card for Invocado por Invocação-Especial: jogue uma moeda e ganhe o efeito apropriado.\r\n● Cara: Quando este card destruir um monstro do oponente em batalha e enviá-lo para o Cemitério: você pode escolher 1 card em seu Cemitério; adicione o alvo para a sua mão.\r\n● Coroa: Durante o turno de qualquer duelista, quando um Card de Magia/Armadilha ou um efeito de monstro que escolher este card como algo for ativado: este card perde exatamente 1000 de ATK e você nega a ativação e, se isso acontecer, destrua o Card de Magia/Armadilha ou o monstro que ativou o efeito.','\r',char(13)),'\n',char(10)),'Jogar uma moeda','Recuperar','Negar e destruir','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5901497,'Sósia da Rainha','Este monstro pode atacar diretamente os Life Points do seu adversário.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5908650,'Shopina, a Maestra Melodiosa',replace(replace('Uma vez por turno: você pode escolher 1 monstro Fada de LUZ no seu Cemitério; adicione-o à sua mão. \r\nVocê não pode ativar os efeitos de monstros que não sejam de LUZ durante o turno em que ativar este efeito.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5914184,'Revanche em Dobro',replace(replace('Ative apenas quando você sofrer 1000 ou mais de dano de um efeito de card do oponente: Coloque 1 Marcador de Revanche neste card para cada 1000 de dano que você sofreu. \r\nDurante a Fase Final do próximo turno do oponente: Destrua este card e, se isso acontecer, cause 2000 de dano ao seu oponente para cada Marcador de Revanche neste card.','\r',char(13)),'\n',char(10)),'Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5914858,'Junora, o Patrono do Poder da Afinação',replace(replace('1 Regulador + 2 não-Reguladores	\r\nPara a Invocação-Sincro deste card, você pode considerar 1 monstro na sua Zona de Monstros Principal central como um Regulador. \r\nSe este card for Invocado por Invocação-Sincro: você pode negar os efeitos de todos os cards com a face para cima que seu oponente controla. \r\n(Efeito Rápido): você pode ativar este efeito; monstros que seu oponente controla na mesma coluna que um ou mais monstros "Elfnota" que você controla não podem ser usados como matéria para uma Invocação-Fusão, Sincro, Xyz ou Link, até o final deste turno. \r\nVocê só pode usar este efeito de "Junora, o Patrono do Poder da Afinação" uma vez por turno.','\r',char(13)),'\n',char(10)),'Negar o efeito','Não pode ser usado como matéria','O efeito de "Junora, o Patrono do Poder da Afinação" está sendo aplicado.','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5915629,'Dom da Ganância','Seu oponente compra 2 cards.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5916510,'Cavaleiro Estrelado',replace(replace('2 monstros de Nível 4	\r\nVocê pode desassociar 1 matéria deste card; Invoque por Invocação-Especial 1 monstro de LUZ da sua mão. \r\nSe este card estiver no seu Cemitério, exceto no turno em que foi enviado para lá: você pode escolher 1 monstro Fada de LUZ de Nível 4 que você controla; Invoque este card por Invocação-Especial e, se isso acontecer, associe esse monstro a este card como matéria. \r\nVocê só pode usar cada efeito de "Cavaleiro Estrelado" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5929801,'Ataqueraptor - Lanius Indistinto',replace(replace('Se você controlar um monstro "Ataqueraptor" que não seja "Ataqueraptor - Lanius Indistinto": você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe este card for enviado para o Cemitério: você pode adicionar 1 "Ataqueraptor - Lanius Indistinto" do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "Ataqueraptor - Lanius Indistinto" uma vez por turno. \r\nVocê não pode Invocar monstros por Invocação-Especial no turno em que ativar qualquer um dos efeitos deste card, exceto monstros "Ataqueraptor".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5941982,'Alternativa Espantagarra',replace(replace('Ofereça como Tributo 3 monstros "Espantagarra"; pelo resto deste turno, seu oponente só pode Invocar monstros por Invocação-Especial em Posição de Defesa. \r\nDurante o seu turno: você pode banir este card do seu Cemitério; cause 100 de dano ao seu oponente para cada monstro em Posição de Defesa no campo. \r\nVocê só pode usar este efeito de "Alternativa Espantagarra" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5969957,'Recarregador Foguette',replace(replace('Se um ou mais monstros de TREVAS que você controla que foram Invocados por Invocação-Especial do Deck Adicional forem destruídos em batalha ou por um efeito de card: você pode enviar este card da sua mão ou do campo para o Cemitério e, depois, escolha 1 desses monstros destruídos; Invoque por Invocação-Especial 1 monstro de TREVAS do seu Cemitério com um nome original diferente que o do monstro alvo. \r\nVocê só pode usar este efeito de "Recarregador Foguette" uma vez por turno. \r\nEnquanto você controlar um monstro de TREVAS Invocado por Invocação-Especial do Deck Adicional, os monstros do seu oponente não podem escolher este card como alvo de ataques.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5972394,'Mimicargila',replace(replace('Se seu oponente controlar um monstro: escolha 1 monstro de Nível 2 ou menos em Posição de Defesa que você controla; Invoque por Invocação-Especial do seu Deck, em Posição de Defesa, 1 monstro com o mesmo nome que esse monstro no campo, mas bana-o quando ele deixar o campo. \r\nVocê só pode ativar 1 "Mimicargila" por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5973663,'A Árvore do Mundo',replace(replace('Sempre que um ou mais monstros do Tipo Planta com a face para cima no campo forem destruídos, coloque 1 Marcador de Flor neste card. \r\nVocê pode remover qualquer número de Marcadores de Flor deste card para ativar esses efeitos.\r\n● 1 Marcador: Escolha 1 monstro do Tipo Planta no campo; o alvo ganha 400 de ATK e DEF até o final deste turno. \r\n(Este ganho de ATK permanece mesmo que este card deixe o campo.)\r\n● 2 Marcadores: Escolha 1 card no campo; destrua o alvo.\r\n● 3 Marcadores: Escolha 1 monstro do Tipo Planta no seu Cemitério; Invoque o alvo por Invocação-Especial.','\r',char(13)),'\n',char(10)),'1: aumentar ATK/DEF','2: destrua 1 card','3: Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5975022,'Besta Gladiadora Murmillo',replace(replace('Se este card for Invocado por Invocação-Especial pelo efeito de um monstro "Besta Gladiadora": escolha 1 monstro com a face para cima; destrua o alvo. \r\nNo final da Fase de Batalha, se este card batalhou: você pode embaralhá-lo no Deck; Invoque por Invocação-Especial 1 monstro "Besta Gladiadora" do seu Deck, exceto "Besta Gladiadora Murmillo".','\r',char(13)),'\n',char(10)),'Destruir','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5990062,'Enigma da Inversão',replace(replace('Envie todos os cards da sua mão e do seu Campo para o Cemitério. \r\nAdivinhe o Tipo de Card (Monstro, Magia ou Armadilha) no topo do seu Deck. \r\nSe adivinhou, troque os seus Life Points atuais com os Life Points atuais do seu adversário.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5993144,'Cauri da Andorinha',replace(replace('Ofereça como Tributo 1 monstro Besta Alada na sua mão ou no campo com a face para cima; adicione 1 monstro Besta Alada do seu Deck à sua mão que tenha o mesmo Nível que tinha o monstro oferecido como Tributo. \r\nVocê só pode ativar 1 "Cauri da Andorinha" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(5997110,'D/D Pesquisador de Marcas',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno, se você Invocar por Invocação-Pêndulo um ou mais monstros "D/D/D": você pode escolher 3 monstros que seu oponente controla com o mesmo Tipo ou Atributo um do outro; ofereça como Tributo 2 desses 3 monstros com a face para cima e, se isso acontecer, o terceiro ganha ATK/DEF igual à soma do ATK/DEF que os monstros oferecidos como Tributo tinham no campo.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nVocê pode descartar 1 outro monstro "D/D"; Invoque este card por Invocação-Especial da sua mão. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 monstro "D/D" com 0 de ATK ou DEF do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "D/D Pesquisador de Marcas" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ofereça como Tributo 1 monstro','Invocação Especial','Efeito de busca','Escolha o(s) monstro(s) que permanecerá(ão) no campo','','','','','','','','','','','','');
INSERT INTO texts VALUES(5998840,'Sabre-XX Cavaleiro Boggart',replace(replace('Não pode ser usado como Matéria Sincro, exceto para a Invocação-Sincro de um monstro "Sabre-X". \r\nQuando este card for Invocado por Invocação-Normal: você pode Invocar por Invocação-Especial 1 monstro "Sabre-X" de Nível 4 ou menos da sua mão.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6004133,'Prova de Roupas do Ator do Abismo',replace(replace('No começo da sua Fase Principal 1: adicione 1 card "Ator do Abismo" e 1 Magia "Script do Abismo" do seu Deck à sua mão. \r\nPelo resto deste turno depois que este card resolver, você não pode Invocar monstros por Invocação-Pêndulo, exceto monstros "Ator do Abismo".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6007213,'Uria, o Senhor das Chamas Cortantes',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao enviar 3 Armadilhas com a face para cima que você controla para o Cemitério. \r\nGanha 1000 de ATK para cada Armadilha Contínua no seu Cemitério. \r\nUma vez por turno: você pode escolher 1 Magia/Armadilha Baixada que seu oponente controla; destrua o alvo. \r\nNenhum duelista pode ativar Cards de Magia/Armadilha em resposta à ativação deste efeito.','\r',char(13)),'\n',char(10)),'Destruir Magias/Armadilhas','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6007214,'Uria, o Senhor das Chamas Cortantes',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao enviar 3 Armadilhas com a face para cima que você controla para o Cemitério. \r\nGanha 1000 de ATK para cada Armadilha Contínua no seu Cemitério. \r\nUma vez por turno: você pode escolher 1 Magia/Armadilha Baixada que seu oponente controla; destrua o alvo. \r\nNenhum duelista pode ativar Cards de Magia/Armadilha em resposta à ativação deste efeito.','\r',char(13)),'\n',char(10)),'Destruir Magias/Armadilhas','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6021033,'Dragão Imperador da Condenação',replace(replace('"Zumbi Espalha-praga" + 1+ monstros Zumbi não-Reguladores	\r\nQuando este card for Invocado por Invocação-Especial: você pode escolher 1 monstro Zumbi no Cemitério do seu oponente; Invoque o alvo por Invocação-Especial no seu campo em Posição de Ataque, mas destrua-o quando este card deixar o campo.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6022371,'Aglomerado Dragão de Água',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial com o efeito de uma Magia/Armadilha "Ligação". \r\nSe este card for Invocado por Invocação-Especial: você pode ativar este efeito; Monstros de Efeito que seu oponente controla atualmente não podem ativar seus efeitos pelo resto deste turno e, além disso, mude o ATK deles para 0 até o final deste turno. \r\n(Efeito Rápido): você pode oferecer este card como Tributo; Invoque por Invocação-Especial 2 "Dragão de Água" da sua mão e/ou do Deck em Posição de Defesa, ignorando suas condições de Invocação.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6039967,'Fraulein Vampira',replace(replace('Quando um monstro declarar um ataque: você pode Invocar este card por Invocação-Especial da sua mão em Posição de Defesa. \r\nVocê só pode usar este efeito de "Fraulein Vampira" uma vez por turno. \r\nUma vez por batalha, se um monstro Zumbi seu batalhar um monstro do oponente, durante esse cálculo de dano (Efeito Rápido): você pode pagar PV em múltiplos de 100 (máx. 3000); seu monstro que está batalhando ganha esse valor de ATK/DEF apenas durante esse cálculo de dano. \r\nNo final da Fase de Batalha, se este card destruiu quaisquer monstros em batalha: você pode Invocá-los por Invocação-Especial dos Cemitérios no seu campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6043161,'Perfurador R.B. Ga10',replace(replace('Se você não controlar nenhum monstro com a face para cima, ou os únicos monstros com a face para cima que você controla forem monstros "R.B.", você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Perfurador R.B. Ga10" por Invocação-Especial uma vez por turno desta forma. \r\nDurante a Fase Principal, se este card estiver linkado a um Monstro Link "R.B." (Efeito Rápido): você pode pagar 500 PV e, depois, escolha 1 monstro que seu oponente controla; destrua tanto esse monstro quanto este card. \r\nVocê só pode usar este efeito de "Perfurador R.B. Ga10" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6061630,'Modelo Exemplar de Mago',replace(replace('Sempre que um Card de Magia for ativado, coloque 2 Marcadores de Magia neste card quando essa Magia resolver. \r\nUma vez por turno: você pode remover qualquer número de Marcadores de Magia deste card; Invoque por Invocação-Especial 1 monstro Mago da sua mão ou do Cemitério cujo Nível seja igual ao número de Marcadores de Magia que você removeu.','\r',char(13)),'\n',char(10)),'Invocação Especial','Escolha a quantidade de Marcadores de Magia a remover','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6071005,'Fazticeira Marka',replace(replace('Você pode oferecer este card como Tributo da sua mão ou campo; adicione 1 Magia de Campo "Fazticeira" ou Magia Contínua do seu Deck à sua mão.\r\nSe um ou mais monstros "Fazticeira" que você controla deixa o campo por um efeito do oponente, enquanto este card está no seu Cemitério: você pode Invocar por Invocação-Especial este card (mas bana-o quando deixar o campo), e se fizer, ofereça 1 monstro que seu oponente controla como Tributo.\r\nVocê só pode usar cada efeito de "Fazticeira Marka" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6075533,'Terror de Trishula',replace(replace('Aplique esses efeitos, em sequência, dependendo do número de Monstros Sincro "Barreira de Gelo" que você controla com nomes diferentes;\r\n● 1+: Bana 1 card que seu oponente controla.\r\n● 2+: Bana 1 card do Cemitério do seu oponente.\r\n● 3+: Bana 1 card aleatório da mão do seu oponente.	\r\nQuando seu oponente ativar um card ou efeito que escolha como alvo um ou mais Monstros Sincro "Barreira de Gelo" que você controla: você pode banir este card do seu Cemitério; negue o efeito.\r\nVocê só pode usar cada efeito de "Terror de Trishula" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6075801,'Paladino de Felgrand',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode equipar a este card 1 monstro Dragão de Nível 7 ou 8 da sua mão ou do Deck. \r\nEste card não é afetado por outros efeitos de monstro enquanto estiver equipado com um Card de Equipamento. \r\nVocê pode oferecer como Tributo 1 monstro e este card e, depois, escolha 1 monstro Dragão de Nível 7 ou 8 no seu Cemitério; Invoque-o por Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6077601,'Fusão Peladura',replace(replace('Invoque por Invocação-Fusão 1 Monstro de Fusão "Peladura" do seu Deck Adicional, ao banir as Matérias de Fusão listadas nele do seu campo ou Cemitério. \r\nVocê só pode ativar 1 "Fusão Peladura" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6083904,'Diabrocken, o Espectro Sinistro',replace(replace('Se este card estiver na sua mão (Efeito Rápido): você pode banir 1 monstro de FOGO do seu campo com a face para cima ou Cemitério; Invoque este card por Invocação-Especial. \r\nSe este card for Invocado por Invocação-Especial: você pode escolher 1 card com a face para cima no campo; negue seus efeitos até o final deste turno. \r\nSe este card for enviado para o Cemitério como Matéria Link: você pode Baixar 1 Magia Rápida ou Armadilha Normal do seu Cemitério que foi enviada para lá neste turno. \r\nVocê só pode usar cada efeito de "Diabrocken, o Espectro Sinistro" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Negar','Baixar','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6089145,'Parede Translúcida',replace(replace('Se "Mundo Translúcido" estiver no campo: você pode adicionar 1 monstro que mencione "Mundo Translúcido" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Parede Translúcida" uma vez por turno. \r\nMonstros que mencionem "Mundo Translúcido" não podem ser destruídos em batalha e, além disso, você não sofre dano de batalha dessa batalha. \r\nEnquanto você controlar um monstro de Nível 7 ou mais que mencione "Mundo Translúcido", seu oponente recebe todos os efeitos de "Mundo Translúcido", independentemente dos Atributos dos monstros que ele controla.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6103114,'Cobra Bicuda','Este monstro envolve-se em torno do oponente e bica com seu grande bico.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6103294,'Emissário do Oasis',replace(replace('Enquanto um Monstro Normal de Nível 3 ou menos permanecer no seu Campo com a face para cima, o seu adversário não pode escolher este card como alvo de um ataque. \r\nEnquanto este card permanecer no seu Campo com a face para cima, qualquer dano de batalha causado ao controlador deste card num combate envolvendo um Monstro Normal de Nível 3 ou menos, torna-se 0.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6104968,'Verme Bubônico',replace(replace('VIRE: Você pode Invocar por Invocação-Especial 1 "Verme Bubônico" do seu Deck com a face para baixo em Posição de Defesa. \r\nDepois, embaralhe seu Deck.','\r',char(13)),'\n',char(10)),'Invocação Especial','Invocar por Invocação Especial 1 "Verme Bubônico" em Posição de Defesa com a face para baixo?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6112401,'Um com a Espada',replace(replace('Ative enquanto o único monstro que você controlar for 1 monstro "Sabre-X" com a face para cima. \r\nEquipe este card a esse monstro. \r\nEle ganha 800 de ATK. \r\nSe ele destruir um monstro do oponente em batalha, compre 1 card.','\r',char(13)),'\n',char(10)),'Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6116731,'Praga de Centopeias',replace(replace('Se este card for virado com a face para cima: você pode escolher 1 outro monstro no campo; coloque-o com a face para cima em Posição de Ataque ou com a face para baixo em Posição de Defesa. \r\nVocê só pode usar este efeito de "Praga de Centopeias" uma vez por turno. \r\nUma vez por turno, durante sua Fase Principal: você pode colocar este card com a face para baixo em Posição de Defesa.','\r',char(13)),'\n',char(10)),'Mude a posição de batalha de outro monstro','Mude a posição de batalha deste card','Mudar aquele monstro para Posição de Defesa com a face para baixo?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6128460,'Cozinheiro Inumano',replace(replace('O nome deste card se torna "Servo Caveira" enquanto estiver no Cemitério. \r\nSe um ou mais monstros Zumbi de Nível 3 ou menos que você controla seriam destruídos em batalha ou por um efeito de card, em vez disso, você pode descartar este card. \r\nSe este card for enviado para o Cemitério: você pode adicionar 2 monstros com nomes diferentes do seu Deck à sua mão, exceto "Cozinheiro Inumano", que sejam "Servo Caveira" ou que o mencionem e, depois, descarte 1 card. \r\nVocê só pode usar este efeito de "Cozinheiro Inumano" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6133894,'Debilmazera',replace(replace('Este monstro não poder ser Invocado a não ser por Invocação-Especial, oferecendo 1 "Guerreiro de Zera" no seu Campo com a face para cima como Tributo, enquanto "Pandemônio" está no Campo. \r\nSe "Pandemônio" está no seu Campo, quando você Invocar este card, por Invocação-Especial, com sucesso, o seu adversário descarta 3 cards aleatóriamente da sua própria mão. \r\nEste efeito não é aplicado a não ser que "Pandemónio" esteja no seu Campo.','\r',char(13)),'\n',char(10)),'Descartar da mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6137095,'Pane',replace(replace('Pague 500 PV. \r\nNegue a ativação de um Card de Armadilha e o devolva à sua posição original.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6142213,'Turbofoguete',replace(replace('Enquanto estiver atacando, este card não pode ser destruído em batalha. \r\nSe este card atacar, depois do cálculo de dano, cause dano igual à metade do ATK do alvo do ataque ao seu oponente.','\r',char(13)),'\n',char(10)),'Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6142488,'Fofanimal Rato',replace(replace('Durante sua Fase Principal: você pode Invocar por Invocação-Especial até 2 cópias de "Fofanimal Rato" do seu Deck. \r\nEste efeito só pode ser usado uma vez enquanto este card estiver com a face para cima no campo. \r\nVocê não pode Invocar monstros por Invocação-Especial do seu Deck Adicional no turno em que ativar este efeito, exceto monstros "Peladura".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6148016,'Engrenagigrenagi',replace(replace('Invoque por Invocação-Especial 2 monstros "Engrenagiano" do seu Deck e aumente o Nível deles em 1. \r\nVocê só pode ativar 1 "Engrenagigrenagi" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6150044,'Cavaleiro Coringa Arcano',replace(replace('"O Cavaleiro da Rainha" + "O Cavaleiro do Valete" + "O Cavaleiro do Rei"	\r\nA Invocação-Fusão deste card só pode ser realizada com as matérias acima. \r\nUma vez por turno, quando um Card de Magia/Armadilha ou efeito de monstro for ativado que escolha como alvo este card com a face para cima no campo (Efeito Rápido): você pode descartar o mesmo tipo de card (Monstro, Magia ou Armadilha); negue o efeito.','\r',char(13)),'\n',char(10)),'Negar o efeito','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6150045,'Cavaleiro Coringa Arcano',replace(replace('"O Cavaleiro da Rainha" + "O Cavaleiro do Valete" + "O Cavaleiro do Rei"	\r\nA Invocação-Fusão deste card só pode ser realizada com as matérias acima. \r\nUma vez por turno, quando um Card de Magia/Armadilha ou efeito de monstro for ativado que escolha como alvo este card com a face para cima no campo (Efeito Rápido): você pode descartar o mesmo tipo de card (Monstro, Magia ou Armadilha); negue o efeito.','\r',char(13)),'\n',char(10)),'Negar o efeito','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6153210,'Caudraco Ketu',replace(replace('Adicione 1 monstro "Caudraco" do seu Deck à sua mão e, depois, se seu oponente controlar um monstro, você pode Invocar por Invocação-Fusão 1 monstro Dragão ou Mago do seu Deck Adicional, usando monstros da sua mão ou do campo. \r\nVocê só pode ativar 1 "Caudraco Ketu" por turno.','\r',char(13)),'\n',char(10)),'','Realizar uma Invocação Fusão?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6165656,'Número C88: Engenhoca Marionete Desastre de Leão',replace(replace('4 monstros de Nível 9	\r\nDeve ser Invocado por Invocação-Especial com uma Magia "Magia de Aumento de Classe" que escolha como alvo "Número 88: Engenhoca Marionete de Leão". \r\nNenhum duelista pode escolher este card no campo como alvo de efeitos de card. \r\nUma vez por turno: você pode desassociar 1 matéria deste card; cause 1000 de dano ao seu oponente. \r\nDurante sua Fase Final, se os PV do seu oponente forem 2000 ou menos e este card não tiver matérias, você vence o Duelo.','\r',char(13)),'\n',char(10)),'Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6172122,'Fusão dos Olhos Vermelhos',replace(replace('Invoque por Invocação-Fusão do seu Deck Adicional 1 Monstro de Fusão que liste um monstro "Olhos Vermelhos" como matéria, usando monstros da sua mão, do Deck ou do campo como Matéria de Fusão e, se isso acontecer, seu nome se torna "Dragão Negro de Olhos Vermelhos". \r\nVocê não pode Invocar outros monstros por Invocação-Normal ou Especial no turno em que ativar este card. \r\nVocê só pode ativar 1 "Fusão dos Olhos Vermelhos" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6178850,'Espírito Lutador',replace(replace('O monstro equipado ganha 300 de ATK para cada monstro que seu oponente controla. \r\nSe ele seria destruído em batalha, em vez disso, você pode destruir este card.','\r',char(13)),'\n',char(10)),'Usar o efeito de "Espírito Lutador" em vez de ser destruído?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6180710,'Tubarão dos Sonhos',replace(replace('Na primeira vez que este card seria destruído em batalha a cada turno, ele não é destruído. \r\nVocê só pode usar cada um dos seguintes efeitos de "Tubarão dos Sonhos" uma vez por turno. \r\nSe você não controlar nenhum monstro, ou se todos os monstros que você controlar forem de ÁGUA: você pode Invocar este card por Invocação-Especial da sua mão. \r\nQuando um card ou efeito que causaria dano a você for ativado, enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial e, se isso acontecer, transforme em 0 esse dano de efeito a você. \r\nSe Invocado desta forma, ele perde 1000 de DEF e, além disso, bana-o quando ele deixar o campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6182103,'Último Miutante',replace(replace('3 monstros "Miutante" de Nível 8 ou mais	\r\nQuando um card ou efeito for ativado (Efeito Rápido): você pode banir 1 card "Miutante" da sua mão, do Cemitério ou do campo com a face para cima do mesmo tipo (Monstro, Magia ou Armadilha); negue a ativação e, se isso acontecer, bana esse card. \r\nSe este card Invocado por Invocação-Fusão que você controla for destruído por um card do oponente: você pode adicionar até 3 dos seus cards "Miutante" banidos (até 1 de cada dentre Monstro, Magia e Armadilha) à sua mão. \r\nVocê só pode usar cada efeito de "Último Miutante" uma vez por turno.','\r',char(13)),'\n',char(10)),'Negar a ativação e banir','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6186304,'D - Força',replace(replace('Quando este card for ativado: você pode adicionar 1 "HERÓI do Destino - Plasma" do seu Deck ou Cemitério à sua mão. \r\nEnquanto você controlar "HERÓI do Destino - Plasma", aplique os seguinte efeitos.\r\n● Você não pode comprar durante a Fase de Compra.\r\n● Seu oponente não pode escolher cards que você controla como alvo de efeitos de card.\r\n● Cada "HERÓI do Destino - Plasma" que você controla ganha 100 de ATK para cada monstro nos Cemitérios, não pode ser destruído pelos efeitos de card do seu oponente e, além disso, pode realizar um segundo ataque durante cada Fase de Batalha.','\r',char(13)),'\n',char(10)),'Adicionar 1 "HERÓI do Destino - Plasma" do seu Deck ou Cemitério à sua mão?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6195332,'Excavaleirostelar Constelar Ptolomeu Ω7',replace(replace('3 monstros de Nível 7	\r\nUma vez por turno, durante sua Fase Principal 2, você também pode Invocar por Invocação-Xyz "Excavaleirostelar Constelar Ptolomeu Ω7" ao usar 1 Monstro Xyz "Cavaleirost" ou "Constelar" que você controla (transfira as matérias dele). \r\nEnquanto você tiver 7 ou mais monstros "Cavaleirost" com nomes diferentes no seu Cemitério e/ou banimento, este card ganha 2700 de ATK/DEF e, além disso, ele não é afetado pelos efeitos ativados do seu oponente. \r\nUma vez por turno (Efeito Rápido): você pode desassociar qualquer número de matérias deste card e, depois, escolha esse número de monstros que seu oponente controla; embaralhe-os no Deck.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Xyz usando um Monstro Xyz "Cavaleirostelar" ou "Constelar" como matéria?','Efeito de retornar ao Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6203182,'Dois Sapos com uma Ferroada Só',replace(replace('Ative este card ao escolher 1 monstro no Cemitério do seu oponente; Invoque-o por Invocação-Especial no campo do seu oponente, mas negue seus efeitos e, além disso, equipe-o com este card. \r\nQuando este card deixar o campo, destrua esse monstro. \r\nO monstro equipado não pode atacar ou ser escolhido como alvo de um ataque. \r\nSe este card for enviado para o Cemitério porque o monstro equipado foi usado como matéria para uma Invocação-Fusão, Sincro, Xyz ou Link: você pode tomar o controle desse monstro Invocado. \r\nVocê só pode ativar 1 "Dois Sapos com uma Ferroada Só" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6205579,'Fusão Parasita',replace(replace('Este card pode ser usado como um substituto para qualquer 1 Matéria de Fusão cujo nome esteja listado especificamente no Card de Monstro de Fusão, mas a(s) outra(s) \r\nMatéria(s) de Fusão deve(m) estar correta(s). \r\nNão pode ser usado como Matéria de Fusão de outra forma. \r\nSe este card for Invocado por Invocação-Especial (exceto durante a Etapa de Dano): você pode Invocar por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional, usando monstros que você controla como Matérias de Fusão, incluindo este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6214163,'Fisgada Dupla',replace(replace('Ative ao descartar 1 card e, depois, escolha até 2 monstros no seu Cemitério; Invoque-os por Invocação-Especial. \r\nQuando qualquer um desses monstros deixar o campo, destrua este card. \r\nQuando este card deixar o campo, destrua esse(s) monstro(s). \r\nVocê só pode ativar 1 "Fisgada Dupla" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6214884,'Brron, Rei Insano do Mundo Negro','Quando este card causar dano de batalha ao seu oponente: você pode descartar 1 card.','Escolha 1 card na sua mão para descartá-la para o Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6218704,'Dragão Arcray de Olhos Anômalos',replace(replace('Escala de Pêndulo = 13\r\n[ Efeito de Pêndulo ]\r\nSe você tiver 2 cards nas suas Zonas de Pêndulo: você pode Invocar este card por Invocação-Especial e, depois, você pode aplicar este efeito.\r\n● Embaralhe 1 card da sua Zona de Pêndulo no Deck e, depois, se ele foi adicionado ao seu Deck Adicional, você pode Invocá-lo por Invocação-Especial, ignorando suas condições de Invocação.	\r\nVocê só pode usar este efeito de "Dragão Arcray de Olhos Anômalos" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\n4 monstros Dragão (1 de Fusão, 1 Sincro, 1 Xyz e 1 Pêndulo)	\r\n(Este card deve ser sempre considerado como "Rei Supremo Z-ARC".)	\r\nEste card com a face para baixo no Deck Adicional primeiro deve ser Invocado por Invocação-Fusão, ou por Invocação-Especial ao oferecer como Tributo 1 "Rei Supremo Z-ARC" de TREVAS de Nível 12. \r\nSe este card for Invocado por Invocação-Especial do Deck Adicional: você pode colocar na sua Zona de Pêndulo 1 Monstro Pêndulo do seu Deck. \r\nSe este card na Zona de Monstros for destruído: você pode colocar este card na sua Zona de Pêndulo.','\r',char(13)),'\n',char(10)),'','Embaralhar no Deck 1 card na sua Zona de Pêndulo?','Invocar aquele monstro por Invocação Especial ignorando suas condições de Invocação?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6218705,'Dragão Arcray de Olhos Anômalos',replace(replace('Escala de Pêndulo = 13\r\n[ Efeito de Pêndulo ]\r\nSe você tiver 2 cards nas suas Zonas de Pêndulo: você pode Invocar este card por Invocação-Especial e, depois, você pode aplicar este efeito.\r\n● Embaralhe 1 card da sua Zona de Pêndulo no Deck e, depois, se ele foi adicionado ao seu Deck Adicional, você pode Invocá-lo por Invocação-Especial, ignorando suas condições de Invocação.	\r\nVocê só pode usar este efeito de "Dragão Arcray de Olhos Anômalos" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\n4 monstros Dragão (1 de Fusão, 1 Sincro, 1 Xyz e 1 Pêndulo)	\r\n(Este card deve ser sempre considerado como "Rei Supremo Z-ARC".)	\r\nEste card com a face para baixo no Deck Adicional primeiro deve ser Invocado por Invocação-Fusão, ou por Invocação-Especial ao oferecer como Tributo 1 "Rei Supremo Z-ARC" de TREVAS de Nível 12. \r\nSe este card for Invocado por Invocação-Especial do Deck Adicional: você pode colocar na sua Zona de Pêndulo 1 Monstro Pêndulo do seu Deck. \r\nSe este card na Zona de Monstros for destruído: você pode colocar este card na sua Zona de Pêndulo.','\r',char(13)),'\n',char(10)),'','Embaralhar no Deck 1 card na sua Zona de Pêndulo?','Invocar aquele monstro por Invocação Especial ignorando suas condições de Invocação?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6247535,'Dragão eXcarga Callibregado',replace(replace('2 monstros Dragão de TREVAS de Nível 4	\r\nNenhum duelista pode escolher este card Invocado por Invocação-Xyz como alvo de efeitos de monstro, exceto seu próprio. \r\nUma vez por turno: você pode desassociar 1 matéria deste card e, depois, escolher 1 monstro com a face para cima no campo; ele perde 600 de ATK/DEF e, depois, você pode Invocar por Invocação-Especial 1 monstro "Callibre" do seu Cemitério, mas bana-o durante a Fase Final e, além disso, você não pode Invocar outros monstros por Invocação-Especial ou atacar diretamente pelo resto deste turno.','\r',char(13)),'\n',char(10)),'','Invocação Especial?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6256844,'Turbo Genex-R','Quando este card for Invocado por Invocação-Normal: você pode adicionar 1 monstro "Genex" de Nível 1 do seu Deck à sua mão.','Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6260554,'Loop e Giro','Quando um Card de Magia, Card de Armadilha ou efeito de monstro for ativado: ofereça como Tributo todas as "Fichas de Besta Fantasma Mecha" que você controla; negue a ativação e, se isso acontecer, destrua-o.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6260560,'Laevateinn, a Lâmina Ardente',replace(replace('2 monstros de FOGO	\r\nDurante a Fase Principal (Efeito Rápido): você pode oferecer como Tributo 1 outro monstro de FOGO e, depois, escolha 1 monstro de FOGO no seu Cemitério com o mesmo Tipo original, mas um Nível original menor que o desse monstro; Invoque-o por Invocação-Especial em Posição de Defesa. \r\nSe um ou mais cards com a face para baixo na sua Zona de Magias & Armadilhas seriam destruídos por um efeito de card do oponente, em vez disso, você pode banir este card que você controla. \r\nVocê só pode usar cada efeito de "Laevateinn, a Lâmina Ardente" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6276588,'Ninja Karakuri mod. 919 "Kuick"',replace(replace('Este card deve atacar se possível. \r\nQuando este card com a face para cima for escolhido como alvo de um ataque, mude sua posição de batalha. \r\nQuando este card destruir um monstro do oponente em batalha e enviá-lo para o Cemitério, selecione 1 monstro "Karakuri" de Nível 4 ou menos no seu Cemitério e Invoque-o por Invocação-Especial com a face para cima em Posição de Defesa.','\r',char(13)),'\n',char(10)),'Alterar posição de batalha','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6278008,'Ciclo do Dragão Estrelado',replace(replace('Escolha 1 Monstro de Fusão, Sincro, Xyz ou Link no campo; devolva esse monstro com a face para cima para o Deck Adicional e, depois, de acordo com seu tipo de card, você pode Invocar por Invocação-Especial no seu campo 1 monstro apropriado de qualquer Cemitério.\r\n● Fusão: Monstro com o mesmo Atributo.\r\n● Sincro: Monstro com um Nível menor.\r\n● Xyz: Monstro com o mesmo Nível que sua Classe.\r\n● Link: Monstro com o mesmo Tipo.	\r\nVocê só pode ativar 1 "Ciclo do Dragão Estrelado" por turno.','\r',char(13)),'\n',char(10)),'','Invocação Especial?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6283472,'Amórfago do Orgulho',replace(replace('Escala de Pêndulo = 3\r\n[ Efeito de Pêndulo ]\r\nEnquanto você controlar um monstro "Amórfago", nenhum duelista sofre qualquer dano de efeito. \r\nUma vez por turno, durante sua Fase de Apoio, ofereça 1 monstro como Tributo ou destrua este card.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe este card for Invocado por Invocação-Pêndulo ou virado com a face para cima, nenhum duelista pode Invocar monstros do Deck Adicional por Invocação-Especial enquanto este card estiver no campo com a face para cima, exceto monstros "Amórfago".','\r',char(13)),'\n',char(10)),'Oferecer como Tributo 1 monstro que você controla?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6284176,'Kanzashi, a Rainha Rikka',replace(replace('2 monstros de Nível 6	\r\nSe um ou mais monstros forem oferecidos como Tributo (exceto durante a Etapa de Dano): você pode desassociar 1 matéria deste card e, depois, escolha 1 monstro em qualquer Cemitério; Invoque-o por Invocação-Especial, mas negue seus efeitos e, além disso, ele se torna um monstro Planta. \r\nSe um ou mais monstros Planta que você controla seriam destruídos por um efeito de card, em vez disso, você pode oferecer como Tributo 1 monstro Planta da sua mão ou do campo. \r\nVocê só pode usar cada efeito de "Kanzashi, a Rainha Rikka" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6285791,'Besta de Vermes Maléfica','Este card é devolvido para a sua mão no final do seu turno.','Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6297941,'Ladrão','Um rato esperto. Ele virá até você com sua enorme garra esquerda.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6309986,'Crepúsculo de Cinco Estrelas',replace(replace('Se o único monstro que você controla for 1 monstro de Nível 5: ofereça esse monstro como Tributo; Invoque por Invocação-Especial 5 monstros (1 "Kuribah", 1 "Kuribee", 1 "Kuriboo", 1 "Kuribeh" e 1 "Kuriboh") da sua mão, do Deck e/ou do Cemitério, mas eles não podem ser oferecidos como Tributo para uma Invocação-Tributo. \r\nVocê só pode ativar 1 "Crepúsculo de Cinco Estrelas" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6311717,'Fada Fortuna Hikari',replace(replace('Quando você comprar este card: você pode revelá-lo; Invoque-o por Invocação-Especial da sua mão. \r\nSe este card for Invocado por Invocação-Especial da mão: você pode escolher 1 monstro que você controla; envie-o para o Cemitério e, se isso acontecer, Invoque por Invocação-Especial do seu Deck 1 monstro Mago de Nível 1. \r\nVocê só pode usar cada efeito de "Fada Fortuna Hikari" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6320631,'Penedo Koa''ki Meiru','Quando este card for destruído em batalha e enviado ao Cemitério, você pode adicionar 1 "Núcleo de Ferro de Koa''ki Meiru" ou 1 monstro "Koa''ki Meiru" de Nível 4 ou menos do seu Deck à sua mão.','Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6325660,'Centelha Dominus',replace(replace('Durante o turno no qual seu oponente tenha ativado um efeito de monstro na mão ou no Cemitério, você pode ativar este card da sua mão. \r\nEscolha 1 monstro que seu oponente controla; bana-o e, depois, se você não tiver Armadilhas no seu Cemitério, seu oponente pode Invocar por Invocação-Especial 1 monstro da mão dele. \r\nSe você ativou este card da sua mão, você não pode ativar os efeitos de monstros de TERRA, ÁGUA, FOGO e VENTO pelo resto deste Duelo. \r\nVocê só pode ativar 1 "Centelha Dominus" por turno.','\r',char(13)),'\n',char(10)),'Banir','Ativar da mão aplicando o efeito de "Centelha Dominus"','Invocação Especial?','O efeito de "Centelha Dominus" está sendo aplicado.','','','','','','','','','','','','');
INSERT INTO texts VALUES(6327734,'Hu-Li, a Joia Mikanko',replace(replace('Se este card não estiver equipado com um Card de Equipamento, você não sofre dano das batalhas envolvendo este card. \r\nSe este card estiver equipado com um Card de Equipamento, ele não pode ser destruído em batalha e seu oponente sofre qualquer dano de batalha que você sofreria das batalhas envolvendo este card. \r\nEnquanto você controlar um Card de Equipamento, seu oponente não pode escolher cards "Mikanko" que você controla como alvo de efeitos de card. \r\nSe qualquer duelista equipar um ou mais Cards de Equipamento a este card: você pode adicionar 1 Armadilha "Mikanko" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Hu-Li, a Joia Mikanko" uma vez por turno.','\r',char(13)),'\n',char(10)),'Procurar no Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6327735,'Hu-Li, a Joia Mikanko',replace(replace('Se este card não estiver equipado com um Card de Equipamento, você não sofre dano das batalhas envolvendo este card. \r\nSe este card estiver equipado com um Card de Equipamento, ele não pode ser destruído em batalha e seu oponente sofre qualquer dano de batalha que você sofreria das batalhas envolvendo este card. \r\nEnquanto você controlar um Card de Equipamento, seu oponente não pode escolher cards "Mikanko" que você controla como alvo de efeitos de card. \r\nSe qualquer duelista equipar um ou mais Cards de Equipamento a este card: você pode adicionar 1 Armadilha "Mikanko" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Hu-Li, a Joia Mikanko" uma vez por turno.','\r',char(13)),'\n',char(10)),'Procurar no Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6330307,'DZW - Quimera Revestida',replace(replace('Você pode escolher 1 monstro "Número C39" que você controla; equipe este monstro da sua mão ou do seu lado do campo ao alvo. \r\nO monstro equipado não pode ser destruído em batalha. \r\nNo final da Etapa de Dano, quando o monstro equipado atacar um monstro do oponente, mas o monstro do oponente não for destruído em batalha: você pode transformar o ATK do monstro do oponente em 0 (mesmo depois que este card deixar o campo ou que o monstro não possa mais ser afetado por efeitos de card) e, se isso acontecer, o monstro equipado pode realizar um segundo ataque em seguida contra o mesmo monstro.','\r',char(13)),'\n',char(10)),'Equipar','Ataques múltiplos','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6337436,'Mago do Fogo Rápido','Cause 400 de dano ao seu oponente sempre que você ativar um Card de Magia Normal.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6343408,'Escavação Milagrosa','Se pelo menos 5 dos seus monstros estiverem banidos: escolha 3 deles; devolva-os para o Cemitério.','Escolha o card a ser devolvido ao Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6351147,'Reverter Transação',replace(replace('Pague metade dos seus PV e, depois, escolha 1 Armadilha Normal no Cemitério do seu oponente, exceto "Reverter Transação"; este efeito se torna o efeito de ativação desse card. \r\nVocê pode banir este card do seu Cemitério e pagar metade dos seus PV e, depois, escolha 1 Armadilha Normal no seu Cemitério, exceto "Reverter Transação"; este efeito se torna o efeito de ativação desse card. \r\nVocê só pode usar 1 efeito de "Reverter Transação" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6351548,'Cavaleiro da Alvorada',replace(replace('Se este card for enviado do campo para o Cemitério: você pode enviar 1 monstro de LUZ do seu Deck para o Cemitério. \r\nSe este card for enviado do seu Deck para o Cemitério: escolha 1 monstro de LUZ no seu Cemitério; coloque o alvo no topo do seu Deck. \r\nVocê só pode usar 1 efeito de "Cavaleiro da Alvorada" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Enviar para o Cemitério','Retornar ao Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6353603,'Irmandade do Punho de Fogo - Urso',replace(replace('Uma vez por turno, quando este card causar dano de batalha ao seu oponente: você pode Baixar 1 Magia "Formação de Fogo" diretamente do seu Deck. \r\nUma vez por turno: você pode enviar 1 Magia/Armadilha "Formação de Fogo" com a face para cima que você controla para o Cemitério e, depois, escolha 1 monstro no campo; destrua o alvo.','\r',char(13)),'\n',char(10)),'Baixar','Destruir um monstro','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6355563,'Cabeça Yare-Y',replace(replace('Se este card for Invocado por Invocação-Especial: você pode equipar 1 monstro Máquina de LUZ de Nível 4 da sua mão ou do Cemitério a este card como uma Magia de Equipamento e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto monstros de LUZ. \r\nUma vez por turno, você pode: escolher 1 monstro Máquina que você controla; equipe este card no alvo, OU: desequipe este card e Invoque-o por Invocação-Especial. \r\nSe o monstro equipado seria destruído em batalha ou por um efeito de card, em vez disso, destrua este card.','\r',char(13)),'\n',char(10)),'Efeito de Equipamento','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6357341,'Os Seis Shinobi','Se você controlar 6 monstros "Seis Samurai" com Atributos diferentes: pule o próximo turno do seu oponente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6361316,'DESPERTAÇA! Kuro',replace(replace('VIRE: Você pode escolher 1 outro monstro com a face para cima no campo; coloque-o com a face para baixo em Posição de Defesa.\r\nVocê pode revelar este card na sua mão; adicione 1 monstro de Virar de VENTO do seu Deck à sua mão, exceto "DESPERTAÇA! Kuro" e, depois, descarte 1 card. \r\n(Efeito Rápido): você pode escolher 1 monstro com a face para baixo em Posição de Defesa no campo; coloque-o com a face para cima em Posição de Defesa. \r\nVocê só pode usar cada efeito de "DESPERTAÇA! Kuro" uma vez por turno.','\r',char(13)),'\n',char(10)),'Efeito de busca','Baixar','Posição de batalha','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6367785,'Eldeen','A bengala deste monstro é a fonte de muitos feitiços poderosos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6368038,'Gaia, o Cavaleiro Impetuoso','Um cavaleiro com um cavalo que galopa mais rápido que o vento. Sua carga em batalha é de uma força avassaladora.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6368039,'Gaia, o Cavaleiro Impetuoso','Um cavaleiro com um cavalo que galopa mais rápido que o vento. Sua carga em batalha é de uma força avassaladora.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6368040,'Gaia, o Cavaleiro Impetuoso','Um cavaleiro com um cavalo que galopa mais rápido que o vento. Sua carga em batalha é de uma força avassaladora.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6374519,'Show Especial da Diversão','Quando seu oponente ativar um card ou efeito que escolha como alvo um ou mais monstros "Diversão" que você controla: escolha 1 desses monstros "Diversão" que você controla; devolva-o para a mão e, depois, você pode Invocar por Invocação-Especial 1 monstro "Diversão" da sua mão.','','Invocação Especial?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6387204,'Número C6: Cronomalia Atlande do Caos',replace(replace('3 monstros de Nível 7	\r\nSe você ativar qualquer um desses efeitos, seu oponente não sofre mais dano neste turno. \r\nUma vez por turno: você pode escolher 1 monstro que seu oponente controla; equipe o alvo a este card como um Card de Magia de Equipamento cujo efeito faz com que este monstro ganhe 1000 de ATK. \r\nSe este card tiver "Número 6: Cronomalia Atlande" como uma Matéria Xyz, ele ganha este efeito.\r\n● Você pode desassociar 3 Matérias Xyz deste card e enviar para o Cemitério todos os monstros "Número" equipados pelo efeito deste card (mín. 1); o total de Pontos de Vida do seu oponente se torna 100.','\r',char(13)),'\n',char(10)),'Equipar','PV se tornam 100','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6390406,'Emblema do Dragão Destruidor','Adicione 1 "Blader Notável" do seu Deck ou Cemitério à sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6400512,'Cibercomandante',replace(replace('(Este card não é considerado como um card "Ciber".)	\r\nUma força impressionante equipada com disparadores de mísseis e bazucas.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6417578,'Fusão do El Sombraneco',replace(replace('Invoque por Invocação-Fusão 1 Monstro de Fusão "Sombraneco" do seu Deck Adicional, usando monstros da sua mão ou do campo. \r\nVocê só pode ativar 1 "Fusão do El Sombraneco" por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6430659,'Correio Infectado',replace(replace('Uma vez por turno: você pode escolher 1 monstro de Nível 4 ou menos que você controla; ele pode atacar diretamente seu oponente neste turno. \r\nEnvie-o para o Cemitério no final da Fase de Batalha.','\r',char(13)),'\n',char(10)),'Ataque direto','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6438003,'Guerreiros Antigos - Enganador Jia Wen',replace(replace('Você pode escolher 1 Magia/Armadilha Contínua que você controla; envie-a para o Cemitério e, se isso acontecer, até o final deste turno, diminua pela metade o ATK de 2 monstros com a face para cima no campo. \r\nSe um ou mais cards que seu oponente controla forem destruídos em batalha ou por um efeito de card: você pode escolher 1 card "Guerreiros Antigos" no seu Cemitério, exceto "Guerreiros Antigos - Enganador Jia Wen"; adicione-o à sua mão. \r\nVocê só pode usar cada efeito de "Guerreiros Antigos - Enganador Jia Wen" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Recuperar do Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6442944,'Serpente-marinha de Kaiser',replace(replace('Se seu oponente controlar um monstro e você não controlar nenhum monstro, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Serpente-marinha de Kaiser" por Invocação-Especial uma vez por turno desta forma. \r\nQuando Invocado desta forma: você pode Invocar por Invocação-Especial 1 monstro Serpente Marinha de Nível 8 da sua mão ou do Cemitério, mas seu ATK/DEF se tornam 0. \r\nSe este card for Invocado por Invocação-Especial, o Nível dele se torna 4 e seu ATK original se torna 0.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6459419,'Xamanismo de Amazoness','Destrua todos os monstros "Amazoness" que você controla e, depois, você pode Invocar por Invocação-Especial monstros "Amazoness" de Nível 4 ou menos do seu Cemitério com a face para cima em Posição de Defesa, até o número de monstros destruídos por este efeito.','Invocação Especial?','Invocação Especial?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6471156,'Atuação das Marionetes',replace(replace('Você pode banir 1 monstro "Engenhoca Marionete" do seu Cemitério; até o final deste turno, todos os monstros que você controla atualmente se tornam do Nível desse monstro banido (mesmo que este card deixe o campo). \r\nSe um ou mais monstros "Engenhoca Marionete" com a face para cima que você controla forem destruídos em batalha ou por um efeito de card do oponente e enviados para o Cemitério: você pode escolher 1 dos seus monstros "Engenhoca Marionete" banidos; Invoque-o por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Atuação das Marionetes" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6480253,'Wroughtweiller','Se este card for destruído em batalha e enviado para o Cemitério: escolha 1 card "HERÓI do Elemento" e 1 "Polimerização" no seu Cemitério; adicione-os à sua mão.','Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6483224,'Raio, o Dragão da Meia-Lua',replace(replace('Se seu oponente controlar um Monstro Xyz com a face para cima, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nSe isso acontecer, o Nível deste card se torna 8.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6494106,'Derrota do Olho Maligno',replace(replace('Se você controlar um monstro "Olho Maligno": escolha 1 monstro no campo, ou, em vez disso, até 2, se "Olho Maligno de Selene" estiver na sua Zona de Magias & Armadilhas; devolva-os para a mão. \r\nVocê só pode ativar 1 "Derrota do Olho Maligno" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6498706,'Implantar Fusão',replace(replace('Revele 1 Monstro de Fusão no seu Deck Adicional e Invoque por Invocação-Especial, da sua mão ou do Deck, 1 das Matérias de Fusão cujo nome seja mencionado nesse monstro e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional, exceto Monstros de Fusão, no turno em que ativar este card. \r\nVocê só pode ativar 1 "Implantar Fusão" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6498707,'Implantar Fusão',replace(replace('Revele 1 Monstro de Fusão no seu Deck Adicional e Invoque por Invocação-Especial, da sua mão ou do Deck, 1 das Matérias de Fusão cujo nome seja mencionado nesse monstro e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional, exceto Monstros de Fusão, no turno em que ativar este card. \r\nVocê só pode ativar 1 "Implantar Fusão" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6500778,'Destilador do Caos',replace(replace('Enquanto este card estiver com a face para cima no campo, qualquer card enviado para o seu Cemitério, em vez disso, é banido. \r\nVocê pode ativar 1 desses efeitos;\r\n● Adicione 1 "Macrocosmo", ou 1 card que o mencione, do seu Deck à sua mão, exceto "Destilador do Caos".\r\n● Se "Macrocosmo" estiver no campo: bana este card com a face para cima da Zona de Magias & Armadilhas; adicione 1 monstro de LUZ com ATK ? do seu Deck à sua mão.	\r\nVocê só pode usar este efeito de "Destilador do Caos" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicione à sua mão "Macrocosmo" ou um card que o mencione','Adicionar à mão um monstro','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6511113,'Armadilhatrix Rafflesia',replace(replace('2 monstros de Nível 4	\r\nNão é afetado por efeitos de Armadilha enquanto tiver matéria. \r\nMonstros "Armadilhatrix" que você controla, exceto "Armadilhatrix Rafflesia", não podem ser destruídos em batalha ou por efeitos de card. \r\nSeu oponente não pode escolher monstros "Armadilhatrix" que você controla como alvo de efeitos de card, exceto "Armadilhatrix Rafflesia". \r\nUma vez por turno (Efeito Rápido): você pode desassociar 1 matéria deste card e enviar 1 Armadilha Normal "Buraco" que cumpra seus requisitos de ativação do seu Deck para o Cemitério; este efeito se torna o efeito desse Card de Armadilha quando esse card for ativado.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6540606,'Aoi - Arte Espiritual da Água','Ofereça 1 monstro de ÁGUA como Tributo; olhe a mão do seu oponente e, depois, envie 1 card da mão dele para o Cemitério.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6544078,'Izanagi',replace(replace('Você pode Invocar este card por Invocação-Especial da sua mão ao remover de jogo 1 monstro Espírito da sua mão. \r\nMonstros Espírito que você controla não precisam ter seus efeitos que os devolvem à mão ativados.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6547248,'Cara Nova da Companhia de Palhaços',replace(replace('Durante a Fase de Apoio: você pode embaralhar no Deck 3 cards "Companhia de Palhaços" do seu Cemitério e/ou banimento e, depois, compre 1 card. \r\nSe você Invocar um monstro por Invocação-Tributo: você pode escolher outras Magias/Armadilhas no campo até o número de monstros oferecidos como Tributo para sua Invocação-Tributo; destrua-as. \r\nSe este card for enviado para o Cemitério, exceto do campo: você pode colocá-lo com a face para cima no seu campo. \r\nVocê só pode usar cada efeito de "Cara Nova da Companhia de Palhaços" uma vez por turno.','\r',char(13)),'\n',char(10)),'Reciclar e comprar','Efeito de destruição','Colocar','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6552938,'Ataqueraptor - Leme Strix',replace(replace('Se este card for Invocado por Invocação-Especial da mão pelo efeito de um card "Ataqueraptor" ou Invocado por Invocação-Normal: você pode causar 600 de dano ao seu oponente. \r\nQuando um monstro do oponente declarar um ataque que escolha este card como alvo: você pode Invocar por Invocação-Especial até 2 monstros "Ataqueraptor" da sua mão e, se isso acontecer, os monstros que seu oponente controla não podem escolher atacar esses monstros neste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6552971,'Encontro I.A.',replace(replace('Revele 1 monstro Ciberso com 2300 de ATK na sua mão ou no Deck Adicional e adicione 1 monstro "@Ignister" com o mesmo Atributo do seu Deck à sua mão. \r\nDurante a Fase Final deste turno, sofra 2300 de dano se você não Invocou por Invocação-Especial o monstro revelado, ou um monstro com o mesmo nome, depois de resolver este efeito. \r\nVocê não pode ativar efeitos de monstro pelo resto deste turno depois que este card resolver, exceto monstros Ciberso. \r\nVocê só pode ativar 1 "Encontro I.A." por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6556178,'Regenerar Callibre',replace(replace('Ative este card ao escolher 1 monstro "Foguette" no seu Cemitério; Invoque-o por Invocação-Especial e equipe-o com este card, mas bana-o quando este card deixar o campo. \r\nSe este card for enviado para o Cemitério devido ao monstro equipado ser destruído: você pode comprar 1 card. \r\nVocê só pode usar cada efeito de "Regenerar Callibre" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6556909,'Alma de Olhos Vermelhos',replace(replace('O nome deste card se torna "Dragão Negro de Olhos Vermelhos" enquanto estiver no campo ou no Cemitério. \r\nSe seu oponente Invocar um ou mais monstros por Invocação-Especial (exceto durante a Etapa de Dano): você pode enviar este card da sua mão ou do campo para o Cemitério; Invoque por Invocação-Especial 1 monstro "Olhos Vermelhos" da sua mão ou do Deck, exceto "Alma de Olhos Vermelhos". \r\nVocê só pode usar este efeito de "Alma de Olhos Vermelhos" uma vez por turno. \r\n(Efeito Rápido): você pode escolher 1 "Dragão Negro de Olhos Vermelhos" que você controla; cause dano ao seu oponente igual ao ATK original desse monstro. \r\nVocê só pode usar este efeito de "Alma de Olhos Vermelhos" uma vez por Duelo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6560411,'Dragão da Rosa Espinhosa',replace(replace('1 Regulador Planta + 1+ monstros não-Reguladores	\r\nSempre que seu oponente ativar um efeito de monstro, cause 600 de dano ao seu oponente e, se isso acontecer, todos os monstros que seu oponente controla atualmente perdem 600 de ATK. \r\nVocê só pode usar cada um dos seguintes efeitos de "Dragão da Rosa Espinhosa" uma vez por turno. \r\nDurante a Fase Principal (Efeito Rápido): você pode oferecer este card como Tributo; Invoque por Invocação-Especial 1 "Dragão da Rosa Negra" do seu Deck Adicional (isso é considerado uma Invocação-Sincro). \r\nVocê pode banir este card do seu Cemitério; Invoque por Invocação-Especial 1 Regulador Planta de Nível 4 ou menos do seu Cemitério.','\r',char(13)),'\n',char(10)),'','Invocação Especial','Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6568731,'Fera Glacial Narval Iceberg',replace(replace('1 Regulador + 1+ monstros de ÁGUA não-Reguladores	\r\nSempre que outro(s) monstro(s) que você controla for(em) destruído(s) por um ataque ou efeito de card do seu oponente: cause 600 de dano ao seu oponente. \r\nDurante a Fase de Batalha, quando seu oponente ativar um card ou efeito enquanto você controlar outro monstro (Efeito Rápido): você pode negar esse efeito e, se isso acontecer, destrua esse card. \r\nVocê só pode usar este efeito de "Fera Glacial Narval Iceberg" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6579928,'Seis Samurai Secretos - Kizaru',replace(replace('Quando este card for Invocado por Invocação-Especial: você pode adicionar do seu Deck à sua mão, 1 monstro "Seis Samurai" com um Atributo diferente do que o dos monstros que você controla. \r\nSe exatamente 1 monstro "Seis Samurai" que você controla (e nenhum outro card) seria destruído por um efeito de card, em vez disso, você pode banir este card do seu Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6588580,'Termogenex',replace(replace('"Controlador Genex" + 1 ou mais monstros de FOGO não-Reguladores	\r\nEste card ganha 200 de ATK para cada monstro de FOGO no seu Cemitério. \r\nSe este card destruir um monstro do oponente em batalha, cause dano 200 de dano ao seu oponente para cada monstro "Genex" no seu cemitério.','\r',char(13)),'\n',char(10)),'Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6589707,'Terror na Cidade Oculta',replace(replace('Seu oponente não pode escolher monstros com a face para baixo em Posição de Defesa que você controla como alvo de efeitos de card. \r\nMonstros que você controla que foram virados com a face para cima enquanto este card estava com a face para cima no campo ganham 1500 de ATK/DEF. \r\nSe este card na Zona de Magias & Armadilhas do seu dono for destruído por um efeito de card do oponente: você pode escolher 1 monstro no seu Cemitério; Invoque-o por Invocação-Especial com a face para baixo em Posição de Defesa.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6595475,'Onomatopar',replace(replace('Você só pode ativar 1 "Onomatopar" por turno. \r\nEnvie 1 card da sua mão para o Cemitério; adicione até 2 desses monstros do seu Deck à sua mão (você não pode adicionar 2 da mesma categoria).\r\n● 1 monstro "Zubaba"\r\n● 1 monstro "Gagaga"\r\n● 1 monstro "Gogogo"\r\n● 1 monstro "Dododo"','\r',char(13)),'\n',char(10)),'Continuar escolhendo monstros para adicionar à mão?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6602300,'Fênix das Chamas, a Ave do Bombardeio Flamejante',replace(replace('1 monstro do Tipo Máquina + 1 monstro do Tipo Piro	\r\nUma vez por turno, durante sua Fase Principal: Você pode causar 300 de dano ao seu oponente para cada card no campo. \r\nEste card não pode atacar durante o turno em que você ativar este efeito.','\r',char(13)),'\n',char(10)),'Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6609736,'Nota Cervo Noh-P.U.N.K.',replace(replace('Você pode revelar 1 outro monstro "P.U.N.K." na sua mão; Invoque por Invocação-Especial o monstro revelado ou este card e envie o outro para o Cemitério. \r\nSe este card for enviado do campo para o seu Cemitério: você pode escolher 1 monstro "P.U.N.K." no seu Cemitério, exceto um monstro de Nível 5; Invoque-o por Invocação-Especial, mas você não pode Invocar "Nota Cervo Noh-P.U.N.K." por Invocação-Especial pelo resto deste turno. \r\nVocê só pode usar cada efeito de "Nota Cervo Noh-P.U.N.K." uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6614221,'Rei Neblina',replace(replace('Você pode oferecer 1 monstro, ou nenhum monstro, como Tributo para Invocar este card por Invocação-Normal (mas não para Baixar). \r\nO ATK deste card se torna a soma do ATK original dos monstros oferecidos como Tributo. \r\nNenhum duelista pode oferecer cards como Tributo.','\r',char(13)),'\n',char(10)),'Invocar com 1 Tributo','Invocar sem oferecer Tributo','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6616912,'Gabrion, o Senhor do Tempo',replace(replace('Não pode ser Invocado por Invocação-Especial do Deck. \r\nSe você não controlar nenhum monstro, você pode Invocar este card por Invocação-Normal sem oferecer Tributo. \r\nNão pode ser destruído em batalha ou por efeitos de card. \r\nVocê não sofre dano de batalha dos ataques envolvendo este card. \r\nNo final da Fase de Batalha, se este card batalhou: embaralhe tantos cards quanto possível que seu oponente controla no(s) \r\nDeck(s) e, depois, ele compra cards igual ao número embaralhado no Deck Principal dele. \r\nUma vez por turno, durante sua Fase de Apoio: embaralhe este card no Deck.','\r',char(13)),'\n',char(10)),'Invocação Normal sem Tributo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6622715,'Encodificar Transmissor',replace(replace('2+ monstros Ciberso	\r\nUma vez por turno, antes do cálculo de dano, se um monstro seu para o qual este card apontar batalhar um monstro do oponente com um ATK maior que o seu próprio: você pode ativar este efeito; nessa batalha, seu monstro não pode ser destruído em batalha e você não sofre dano de batalha. \r\nDepois do cálculo de dano, faça com que este card ou 1 monstro para o qual este card apontar ganhe ATK igual ao ATK desse monstro do oponente na batalha, até o final deste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6625096,'Princesa Atraentum',replace(replace('Quando este card for Invocado por Invocação-Normal ou Especial: você pode banir este card; Invoque por Invocação-Especial 1 monstro Peixe de Nível 4 ou menos do seu Deck, exceto "Princesa Atraentum". \r\nVocê só pode usar este efeito de "Princesa Atraentum" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6628343,'Cavaleiro Principiante',replace(replace('Um monstro "Soldado do Lustro Negro" Invocado por Invocação-Ritual usando este card ganha esses efeitos. \r\nVocê só pode usar este efeito de "Cavaleiro Principiante" uma vez por turno.\r\n● Uma vez por turno: você pode escolher 1 monstro que seu oponente controla; bana-o.\r\n● Quando este card destruir um monstro do oponente em batalha e enviá-lo para o Cemitério: você pode ativar este efeito; este card pode realizar um segundo ataque em seguida.	\r\nSe este card for banido do Cemitério: você pode adicionar 1 Card de Magia de Ritual do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Cavaleiro Principiante" uma vez por turno.','\r',char(13)),'\n',char(10)),'Banir 1 monstro que seu oponente controla (Cavaleiro Principiante)','Pode atacar mais 1 vez (Cavaleiro Principiante)','O efeito de "Cavaleiro Principiante" está sendo aplicado.','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6631034,'Gelidossauro','O metabolismo desse monstro permite que ele suporte longos períodos de frio, acumulando poder para se tornar uma criatura de gelo sólido! Nada pode suportar essas temperaturas, especialmente as vítimas dessa torrente glacial.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6636319,'Evil★Gêmea Ki-sikil Negociante',replace(replace('1 monstro "Ki-sikil"	\r\nVocê só pode Invocar "Evil★Gêmea Ki-sikil Negociante" por Invocação-Link uma vez por turno. \r\nVocê pode enviar 1 monstro "Lil-la" do seu Deck ou Deck Adicional para o Cemitério; aplique este efeito neste turno.\r\n● Sempre que seu oponente ativar um card ou efeito em resposta à ativação de um efeito de monstro "Ki-sikil" ou "Lil-la" seu, compre 1 card quando esse card/efeito resolver.	\r\nVocê só pode usar este efeito de "Evil★Gêmea Ki-sikil Negociante" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar o efeito','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6637331,'Bistial Druiswurm',replace(replace('Você pode escolher 1 monstro de LUZ ou de TREVAS em qualquer Cemitério; bana-o e, se isso acontecer, Invoque este card por Invocação-Especial da sua mão. \r\nEste é um Efeito Rápido se seu oponente controlar um monstro. \r\nSe este card for enviado do campo para o Cemitério: você pode escolher 1 monstro Invocado por Invocação-Especial que seu oponente controla; envie-o para o Cemitério. \r\nVocê só pode usar cada efeito de "Bistial Druiswurm" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6659193,'Camaramágico Alto Mago Trapezista',replace(replace('2 monstros Mago de Nível 5	\r\nNão pode ser destruído em batalha ou por efeitos de card enquanto tiver matéria. \r\nSeu oponente sofre qualquer dano de efeito que você teria sofrido, um número de vezes a cada turno até o número de matérias associadas a este card. \r\nSe este card tiver "Camaramágico Mago Trapezista" como matéria, ele ganha este efeito.\r\n● Você pode desassociar 1 matéria deste card; este card pode realizar até 3 ataques durante cada Fase de Batalha neste turno.','\r',char(13)),'\n',char(10)),'3 ataques','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6691855,'Escudo com Corrente e Cravos',replace(replace('Escolha 1 monstro com a face para cima no campo; equipe este card no alvo. \r\nEle ganha 500 de ATK. \r\nSe o monstro equipado batalhar enquanto estiver em Posição de Defesa, ele ganha DEF igual ao seu ATK apenas durante o cálculo de dano.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6696168,'Festibalão',replace(replace('Se este card batalhar um monstro, nenhum dos dois pode ser destruído nessa batalha. \r\nSempre que um monstro declarar um ataque, este card ganha 1000 de ATK. \r\nDurante sua Fase Principal: você pode fazer com que este card perca exatamente 5000 de ATK e, se isso acontecer, destrua todos os outros cards no campo. \r\nVocê só pode usar este efeito de "Festibalão" uma vez por turno.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6713443,'Formação de Fogo Suprema - Seito','Bana 7 Cards de Magia/Armadilha "Formação de Fogo" do seu Cemitério; Invoque por Invocação-Especial quantos monstros "Punho de Fogo" forem possíveis do seu Cemitério e, depois, você pode Baixar Cards de Magia/Armadilha "Formação de Fogo" diretamente do seu Deck, exceto "Formação de Fogo Suprema - Seito", até o número de monstros Invocados por Invocação-Especial por este efeito.','Baixar no seu campo 1 Magia/Armadilha cujo nome inclua "Formação de Fogo"?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6728559,'Arquinêmeses Protos',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro deve ser Invocado por Invocação-Especial (da sua mão) ao banir 3 monstros com Atributos diferentes do seu Cemitério e/ou do campo com a face para cima. \r\nNão pode ser destruído por efeitos de card. \r\nVocê pode declarar 1 Atributo de monstro no campo; destrua todos os monstros no campo com esse Atributo e, além disso, até o final do próximo turno, nenhum duelista pode Invocar monstros com esse Atributo por Invocação-Especial. \r\nVocê só pode usar este efeito de "Arquinêmeses Protos" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6733059,'Covil das Caveiras',replace(replace('Remova de jogo um número qualquer de monstros do seu Cemitério. \r\nDestrói 1 monstro no Campo com a face para cima, cujo Nível seja igual ao número de monstros que você removeu de jogo.','\r',char(13)),'\n',char(10)),'Usar o efeito de "Covil das Caveiras" agora?','Destruir','Escolha a quantidade de monstros a banir','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6740720,'Seiyaryu','Um dragão místico que queima os indignos com suas chamas místicas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6763530,'Banimento Marcado',replace(replace('Escolha 1 monstro "Despia" ou 1 Monstro de Fusão de Nível 8 ou mais no seu Cemitério; Invoque-o por Invocação-Especial e, depois, você pode aplicar este efeito.\r\n● Invoque por Invocação-Fusão 1 Monstro de Fusão de Nível 8 ou mais do seu Deck Adicional, ao banir Matérias de Fusão mencionadas nele de qualquer campo.	\r\nVocê só pode ativar 1 "Banimento Marcado" por turno.','\r',char(13)),'\n',char(10)),'Invocação Fusão?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6764709,'F.A. Dragster Negro',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro deve ser Invocado por Invocação-Especial (da sua mão) ao ter um monstro "F.A." de Nível 7 ou mais no campo, mas nenhum "F.A. Dragster Negro" na sua Zona de Monstros. \r\nGanha ATK igual ao seu Nível x 300. \r\nSempre que um Card ou efeito de Magia/Armadilha "F.A." for ativado: você pode aumentar em 1 o Nível deste card. \r\nUma vez por turno: você pode escolher 1 card no campo; reduza em 3 o Nível deste card e, se isso acontecer, destrua o alvo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6766208,'D/D/D Alexandre, o Alto Rei dos Vendavais',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nSe 3 ou mais monstros "D/D/D" estiverem no campo, este card ganha 3000 de ATK. \r\nSe outro(s) monstro(s) "D/D" for(em) \r\nInvocado(s) por Invocação-Normal ou Especial no seu campo enquanto este monstro estiver no campo (exceto durante a Etapa de Dano): você pode escolher 1 monstro "D/D" no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê só pode usar este efeito de "D/D/D Alexandre, o Alto Rei dos Vendavais" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6767771,'Lagrimentiara Estridente',replace(replace('Se um ou mais monstros forem Invocados por Invocação-Normal ou Especial e você controlar um monstro "Lagrimentiara" ou "Visas Starfrost" (exceto durante a Etapa de Dano): você pode enviar os 3 cards do topo do seu Deck para o Cemitério e, além disso, pelo resto deste turno, todos os monstros que seu oponente controla perdem 500 de ATK. \r\nSe este card for enviado para o Cemitério por um efeito de card: você pode adicionar 1 Armadilha "Lagrimentiara" do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "Lagrimentiara Estridente" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6772168,'Oceanus, o Invokado',replace(replace('1 monstro "Aleister" + 1 monstro de TREVAS ou de ÁGUA	\r\nEnquanto este card estiver na Zona de Monstros Principal, os monstros do seu oponente não podem escolher monstros como alvo de ataques, exceto este. \r\nEnquanto este card estiver na Zona de Monstros Adicional, qualquer monstro enviado para o Cemitério do seu oponente, em vez disso, é banido. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 Monstro de Fusão que você controla; ele pode atacar diretamente neste turno. \r\nVocê só pode usar este efeito de "Oceanus, o Invokado" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Ataque direto','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6783559,'Formiga da Autodestruição',replace(replace('VIRE: Cada duelista sofre 1000 de dano.\r\nSe este card for destruído em batalha ou por um efeito de card e enviado para o Cemitério: cause 1000 de dano ao seu oponente. \r\nVocê só pode usar cada efeito de "Formiga da Autodestruição" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6795211,'Teletransporte','Uma vez por turno, se seu oponente controlar um monstro e você não controlar nenhum monstro, você pode pagar 800 PV para Invocar por Invocação-Especial 1 monstro do Tipo Psíquico da sua mão.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6798031,'Cruzamento Ryzeal',replace(replace('Você não pode Invocar por Invocação-Xyz monstros com o mesmo nome de um card que você controla. \r\nVocê pode escolher 2 cards "Ryzeal" no seu Cemitério, exceto "Cruzamento Ryzeal"; coloque-os no fundo do Deck em qualquer ordem e, depois, compre 1 card. \r\nVocê só pode usar este efeito de "Cruzamento Ryzeal" uma vez por turno. \r\nUma vez por turno, quando um efeito de monstro ativado pelo seu oponente resolver, você pode desassociar 1 matéria de um Monstro Xyz "Ryzeal" que você controla e, se isso acontecer, negue o efeito.','\r',char(13)),'\n',char(10)),'','Reciclar e comprar','Negar','Aplicar o efeito de "Cruzamento Ryzeal" para negar?','Efeito de negar monstro já usado','','','','','','','','','','','');
INSERT INTO texts VALUES(6799227,'Meio Contra-ataque','Durante o cálculo de dano, se um monstro que você controla estiver sendo atacado: escolha esse monstro que você controla; o alvo ganha ATK igual à metade do ATK original do monstro atacante, até o final deste turno.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6812770,'Camaramágico Enganador dos Copos',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nVocê pode escolher 1 Monstro Xyz "Camaramágico" que você controla; associe este card a ele como matéria. \r\nSe um ou mais cards forem adicionados ao seu Deck Adicional (exceto durante a Etapa de Dano): você pode adicionar 1 Monstro Pêndulo "Camaramágico" com a face para cima do seu Deck Adicional à sua mão. \r\nVocê só pode usar cada efeito de "Camaramágico Enganador dos Copos" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe este card estiver na sua mão: você pode escolher 1 Monstro Xyz no campo; desassocie 1 matéria dele e, se isso acontecer, Invoque este card por Invocação-Especial e, depois, faça com que 1 Monstro Xyz no campo perca 600 de ATK. \r\nSe este card for desassociado de um Monstro Xyz e enviado para o Cemitério para ativar o efeito desse monstro: você pode escolher 2 Monstros Xyz que você controla; associe 1 matéria de 1 desses monstros ao outro. \r\nVocê só pode usar cada efeito de "Camaramágico Enganador dos Copos" uma vez por turno.','\r',char(13)),'\n',char(10)),'Tornar-se Matéria Xyz','Retornar ao Deck Adicional','Invocação Especial','Transferir Matérias Xyz','Escolha o monstro que perderá Matéria Xyz','','','','','','','','','','','');
INSERT INTO texts VALUES(6821579,'Impulsionador R.B. VALCan',replace(replace('2 monstros Máquina	\r\nSe este card for Invocado por Invocação-Link: você pode adicionar 1 Magia "R.B." do seu Deck à sua mão. \r\nSe este card estiver na Zona de Monstros Adicional: você pode Invocar por Invocação-Especial 1 monstro "R.B." da sua mão ou do Cemitério em Posição de Defesa e, depois, você pode mover este card que você controla para outra das suas Zonas de Monstros Principais e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto monstros Máquina com 1500 ou menos de ATK. \r\nVocê só pode usar cada efeito de "Impulsionador R.B. VALCan" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Invocação Especial','Mover?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6830480,'Ninja do Crepúsculo Kagen',replace(replace('Escala de Pêndulo = 10\r\n[ Efeito de Pêndulo ]\r\nVocê não pode Invocar monstros por Invocação-Pêndulo, exceto monstros "Ninja". \r\nEste efeito não pode ser negado. \r\nUma vez por turno, quando um monstro "Ninja" seu declarar um ataque: você pode fazer com que esse monstro ganhe 1000 de ATK até o final da Etapa de Dano (mesmo que este card deixe o campo).\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nVocê pode oferecer este card como Tributo e, depois, escolha 1 monstro "Ninja" que você controla; ele ganha 800 de ATK até o final deste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6836211,'O Grande Pinguim-imperador','Você pode oferecer este card como Tributo; Invoque por Invocação-Especial até 2 monstros "Pinguim" do seu Deck, exceto "O Grande Pinguim-imperador".','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6840573,'Barox','"Panda Frenético" + "Ryu-Kishin"','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6849042,'Dinobesta Super Antiga',replace(replace('Você pode Invocar este card por Invocação-Tributo com a face para cima em Posição de Ataque ao oferecer como Tributo 1 monstro Dinossauro. \r\nQuando um ou mais monstros Dinossauro forem Invocados por Invocação-Especial do seu Cemitério enquanto este monstro estiver no campo (exceto durante a Etapa de Dano): você pode comprar 1 card.','\r',char(13)),'\n',char(10)),'Invocar por Tributo oferecendo 1 monstro Dinossauro como Tributo','Comprar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6850209,'Um Acordo com o Senhor das Trevas',replace(replace('(Este card é tratado como um card "Arquidemônio".)	\r\nSe um monstro de Nível 8 ou mais sob o seu controle foi enviado para o Cemitério neste turno: Invoque por Invocação-Especial 1 "Dragão Furioso" da sua mão ou Deck.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6853254,'Retorno dos Senhores Dragão',replace(replace('Escolha 1 monstro Dragão de Nível 7 ou 8 no seu Cemitério; Invoque-o por Invocação-Especial. \r\nSe um ou mais monstros Dragão que você controla seriam destruídos em batalha ou por um efeito de card, em vez disso, você pode banir este card do seu Cemitério.','\r',char(13)),'\n',char(10)),'Usar o efeito de "Retorno dos Senhores Dragão" em vez de ser destruído?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6855503,'Masquerade, o Dragão Ardente',replace(replace('1 monstro "Despia" + 1 monstro de LUZ ou de TREVAS	\r\nEnquanto você controlar este card Invocado por Invocação-Fusão, seu oponente deve pagar 600 PV para ativar cards ou efeitos. \r\nSe seu oponente controlar um Monstro de Ritual, Fusão, Sincro, Xyz ou Link, enquanto este card estiver no seu Cemitério (Efeito Rápido): você pode Invocar este card por Invocação-Especial, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar este efeito de "Masquerade, o Dragão Ardente" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6859683,'Probabilidade de Sucesso 0%','Envie 2 Monstros de Fusão aleatórios do Deck Adicional do oponente ao Cemitério.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6890729,'Ligação - DHO',replace(replace('Embaralhe 1 "Duoterion", 1 "Hydrogeddon" e 1 "Oxygeddon" da sua mão e/ou do Cemitério no Deck; Invoque por Invocação-Especial 1 "Aglomerado Dragão de Água" da sua mão ou do Cemitério. \r\nVocê pode banir este card do seu Cemitério; adicione 1 "Dragão de Água" ou "Aglomerado Dragão de Água" do seu Deck ou do Cemitério à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6901008,'Rei Fantasma Hidreto','Se você usar este card que você controla como Matéria Sincro, você pode considerá-lo como um não-Regulador.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6903857,'Rompedor do Poder',replace(replace('Se este card em sua posse for destruído por um ataque ou efeito de card do seu oponente e enviado para o seu Cemitério: escolha 1 Card de Magia/Armadilha com a face para cima que seu oponente controla; destrua o alvo. \r\nSe este card atacar, ele é colocado em Posição de Defesa no final da Etapa de Dano.','\r',char(13)),'\n',char(10)),'Destruir','Mudar para Posição de Defesa','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6906306,'Rubissafirus, a Joia de Adamante',replace(replace('2+ monstros de Nível 9	\r\nSe este card com a face para cima seria destruído, em vez disso, você pode desassociar 1 matéria deste card. \r\nGanha os seguintes efeitos, de acordo com os Atributos de suas matérias associadas.\r\n● FOGO: Quando este card declarar um ataque contra um monstro de maior ATK: até o final da Etapa de Dano, você pode fazer com que o ATK deste card se torne o dobro do seu ATK atual.\r\n● ÁGUA: Uma vez por turno do oponente (Efeito Rápido): você pode escolher 1 card que você controla; neste turno, negue qualquer card ou efeito ativado por seu oponente que escolheu esse card como alvo.','\r',char(13)),'\n',char(10)),'Dobrar ATK','Escolha como alvo seu próprio card','O efeito de "Rubissafirus, a Joia de Adamante" está sendo aplicado.','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6908161,'Bobinas de Corrente Ragnaraika',replace(replace('2+ monstros, incluindo um monstro Inseto, Planta ou Réptil	\r\nSe seu oponente ativar um efeito de monstro (exceto durante a Etapa de Dano): você pode ativar este efeito; nenhum duelista pode ativar os efeitos de monstros na mão neste turno. \r\nSe este card estiver no seu Cemitério: você pode escolher 1 monstro Inseto, Planta ou Réptil que você controla; coloque-o no fundo do Deck e, se isso acontecer, Invoque este card por Invocação-Especial e, além disso, você não pode Invocar por Invocação-Especial pelo resto deste turno, exceto monstros Inseto, Planta ou Réptil. \r\nVocê só pode usar cada efeito de "Bobinas de Corrente Ragnaraika" uma vez por turno.','\r',char(13)),'\n',char(10)),'Efeito de bloqueio','Invocar-se por Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6909330,'Portão da Restrição da Alma',replace(replace('Para ativar este card, você não pode controlar nenhum monstro e uma ou mais Magias/Armadilhas Baixadas que você controla devem ter sido destruídas por um efeito de card neste turno. \r\nDurante a Fase Principal, se exatamente 1 monstro com ATK menor que seus PV for Invocado e você tiver "Z-ONE" no seu Cemitério: destrua esse monstro e, se isso acontecer, sofra 800 de dano e, depois, cause 800 de dano ao seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6917479,'Barão Vermelho Vampiro',replace(replace('Uma vez por turno: você pode pagar 1000 PV e, depois, escolher 1 monstro que seu oponente controla e 1 outro monstro "Vampiro(a)" que você controla; troque o controle desses monstros. \r\nNo final da Fase de Batalha, se este card destruiu quaisquer monstros em batalha: você pode Invocá-los por Invocação-Especial dos Cemitérios no seu campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6924874,'Bebê Dragão de Estimação da Harpia',replace(replace('Ganha efeitos de acordo com o número de monstros "Harpia" que você controla, exceto "Bebê Dragão de Estimação da Harpia".\r\n● 1+: Seu oponente não pode escolher monstros "Harpia" que você controla como alvo de ataques, exceto "Bebê Dragão de Estimação da Harpia".\r\n● 2+: Dobre o ATK/DEF originais deste card.\r\n● 3+: Uma vez por turno: você pode escolher 1 card que seu oponente controla; destrua o alvo.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6930746,'Dragão Limite Schwarzschild','Se seu oponente controlar um monstro com ATK 2000 ou mais, você pode Invocar este card por Invocação-Especial (da sua mão).','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6958551,'Sombra Toon',replace(replace('Se você controlar "Mundo Toon": escolha 1 monstro com a face para cima que seu oponente controla; cause dano ao seu oponente igual ao ATK desse monstro com a face para cima. \r\nVocê só pode ativar 1 "Sombra Toon" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6958567,'Celebração das Fazticeiras',replace(replace('Ative 1 desses efeitos;\r\n● Destrua 1 monstro "Fazticeira" que você controla e 1 card que seu oponente controla.\r\n● Invoque por Invocação-Fusão 1 monstro "Fazticeira" do seu Deck Adicional, ao embaralhar monstros Magos do seu Cemitério e/ou banimento no Deck.	\r\nDurante a sua Fase Final, se este card estiver no seu Cemitério e você controla um monstro "Fazticeira": você pode adicionar este card à sua mão.\r\nVocê só pode usar 1 dos efeitos de "Celebração das Fazticeiras" e somente uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar','Adicionar à mão','Efeito de destruição','Invocação Fusão','','','','','','','','','','','','');
INSERT INTO texts VALUES(6967870,'Escorpião das Trevas - Cliff, o Eliminador de Armadilhas',replace(replace('Quando este card causar dano de batalha ao seu oponente: você pode ativar 1 desses efeitos.\r\n● Escolha 1 Magia/Armadilha no campo; destrua o alvo.\r\n● Envie os 2 cards do topo do Deck dele para o Cemitério.','\r',char(13)),'\n',char(10)),'Ativar 1 efeito','Destrua 1 Card de Magia ou Armadilha no campo.','Envie as 2 cards do topo do Deck do seu oponente para o Cemitério.','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6979239,'Duende da Floresta','Envie 1 Card de Equipamento equipado neste monstro para o Cemitério para infligir 500 pontos de dano aos Life Points do seu adversário.','Causar dano aos PV','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6983839,'Dragão Tornado',replace(replace('2 monstros de Nível 4	\r\nUma vez por turno (Efeito Rápido): você pode desassociar 1 matéria deste card e, depois, escolha 1 Magia/Armadilha no campo; destrua-a.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6990577,'Dragão-Guarda Andrake',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial por um efeito de card. \r\nSe este card for Invocado por Invocação-Especial da mão ou do Deck: até o final do próximo turno, você pode dobrar o ATK/DEF originais deste card. \r\nSe este card for Invocado por Invocação-Especial do Cemitério, ou se este card banido for Invocado por Invocação-Especial: você pode escolher 1 monstro que seu oponente controla; destrua-o. \r\nVocê só pode usar cada efeito de "Dragão-Guarda Andrake" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(6992184,'Bis do Pêndulo',replace(replace('Durante a Fase Principal do seu oponente: você pode descartar 1 card; imediatamente depois que este efeito resolver, Invoque por Invocação-Pêndulo um ou mais Monstros Pêndulo e, além disso, pelo resto deste turno depois que este card resolver, cards nas suas Zonas de Pêndulo não podem ativar seus efeitos e não podem ser destruídos pelos seus efeitos de card e, além disso, embaralhe-os no Deck durante a Fase Final. \r\nVocê só pode ativar 1 "Bis do Pêndulo" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7019529,'Soldados Insectos do Céu','O ATK deste card aumenta em 1000 pontos durante o Damage Step, sempre que atacar um monstro do VENTO.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7020743,'Criança Birrenta',replace(replace('2 monstros de Nível 1	\r\nUma vez por Corrente, se a ativação de um card ou efeito for negada (exceto durante a Etapa de Dano): você pode associar até 1 card de cada do seu Cemitério e do Cemitério do seu oponente a este card como matéria. \r\nEste card ganha efeitos de acordo com o número de matérias associadas a ele.\r\n● 1+: Ganha 700 de ATK/DEF para cada matéria associada a ele.\r\n● 4+: Não pode ser destruído em batalha ou por efeitos de card.\r\n● 8+: (Efeito Rápido): você pode desassociar 4 matérias deste card; destrua todos os cards no campo.','\r',char(13)),'\n',char(10)),'Associar Matéria Xyz','Destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7021574,'Kuriboo',replace(replace('(Este card deve ser sempre considerado como um card "Kuriboh".)	\r\nQuando um monstro do oponente declarar um ataque: você pode descartar este card; adicione 1 monstro "Kuriboh" do seu Deck à sua mão, exceto "Kuriboo". \r\nUma vez por turno (Efeito Rápido): você pode descartar 1 Armadilha e, depois, escolha 1 monstro com a face para cima que seu oponente controla; ele perde 1500 de ATK até o final deste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7025445,'Gigante Poderoso',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) ao enviar 1 monstro de Nível 4 ou menos da sua mão para o Cemitério. \r\nSe isso acontecer, reduza o Nível deste card pelo Nível desse monstro. \r\nSe este card atacar ou for atacado, até o final da Etapa de Dano, qualquer efeito de dano que você sofrer se torna 0.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7030340,'Fábrica de 100 Máquinas',replace(replace('Remova de jogo todos os monstros "Morfotrônico(a)" do seu Cemitério. \r\nO monstro do Tipo Máquina com a face para cima escolhido que você controla ganha 200 de ATK para cada card removido até a Fase Final.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7044562,'Card da Alma',replace(replace('Olhe o seu Deck e, se isso acontecer, você pode adicionar 1 monstro do seu Deck à sua mão, cuja soma do ATK e DEF seja igual aos seus PV. \r\nVocê só pode ativar 1 "Card da Alma" por turno.','\r',char(13)),'\n',char(10)),'Escolher um monstro para adicionar à mão?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7076131,'Próxima Perda',replace(replace('Selecione 1 monstro com a face para cima que você controla. \r\nEnvie 1 card do seu Deck ao Cemitério com o mesmo nome que o do card selecionado.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7080743,'Trem Expresso de Vagões Robustos',replace(replace('Um Monstro Xyz que foi Invocado usando este card no campo como matéria ganha este efeito.\r\n● Se ele for Invocado por Invocação-Xyz: ele ganha 800 de ATK.','\r',char(13)),'\n',char(10)),'Aumentar ATK (Trem Expresso de Vagões Robustos)','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7084129,'Bastão do Mago',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode adicionar 1 Magia/Armadilha do seu Deck à sua mão, que mencione "Mago Negro". \r\nDurante o turno do seu oponente, se você ativar um Card de Magia/Armadilha ou seus efeitos enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode oferecer como Tributo 1 monstro Mago; adicione este card à sua mão. \r\nVocê só pode usar cada efeito de "Bastão do Mago" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Adicione este card do Cemitério à sua mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7089711,'Hane-Hane','VIRE: Devolva para a mão do seu dono 1 Card de Monstro no Campo à sua escolha.','Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7092142,'Renascimento Torrencial',replace(replace('Quando um monstro de ÁGUA com a face para cima que você controla for destruído em batalha ou por um efeito de card e enviado para o Cemitério: Invoque por Invocação-Especial o monstro destruído e enviado do campo para o seu Cemitério nesse momento e, depois, cause 500 de dano ao seu oponente para cada um desses monstros Invocados por Invocação-Especial. \r\nVocê só pode ativar 1 "Renascimento Torrencial" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7093411,'Fera Cristalina Pégaso Safira',replace(replace('Quando este card for Invocado: você pode colocar 1 monstro "Fera Cristalina" da sua mão, do Deck ou do Cemitério, com a face para cima na sua Zona de Magias & Armadilhas como uma Magia Contínua. \r\nSe este card com a face para cima for destruído em uma Zona de Monstros, em vez de enviá-lo para o Cemitério, você pode colocá-lo com a face para cima na sua Zona de Magias & Armadilhas como uma Magia Contínua.','\r',char(13)),'\n',char(10)),'Colocar na Zona de Magias & Armadilhas quando for destruído','Colocar na Zona de Magias & Armadilhas','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7102732,'Golem da Fúria Translúcido',replace(replace('Você não é afetado pelos efeitos de "Mundo Translúcido". \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode ativar este efeito; neste turno, seus monstros que mencionem "Mundo Translúcido" podem atacar diretamente. \r\nVocê só pode usar este efeito de "Golem da Fúria Translúcido" uma vez por turno. \r\nQuando este card causar dano de batalha ao seu oponente: você pode causar 300 de dano ao seu oponente para cada card na mão dele.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7127502,'Pêndulo Lector, o Dracosuserano',replace(replace('Escala de Pêndulo = 5\r\n[ Efeito de Pêndulo ]\r\nNegue os efeitos de Monstros Pêndulo com a face para cima enquanto seu oponente os controlar.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nNo começo da Etapa de Dano, se este card batalhar um Monstro Pêndulo: destrua tanto esse monstro como este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7133305,'Água da Vida',replace(replace('Se você não controlar nenhum monstro: escolha 1 monstro no seu Cemitério; Invoque o alvo por Invocação-Especial em Posição de Ataque e, além disso, pelo resto deste turno depois que este card resolver, você não pode ativar efeitos de monstro, exceto os efeitos desse monstro Invocado por Invocação-Especial no campo. \r\nVocê só pode ativar 1 "Água da Vida" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7142724,'Berço Enion, Cenote de Gelojade',replace(replace('Quando este card for ativado: você pode adicionar à sua mão 1 dos seus monstros "Gelojade" que estiverem banidos ou no seu Cemitério. \r\nUma vez por turno, se um ou mais monstros forem Invocados por Invocação-Normal ou Especial (exceto durante a Etapa de Dano): você pode escolher 1 monstro de ÁGUA que você controla; até o final deste turno, esse monstro, assim como quaisquer monstros com a face para cima que seu oponente controla atualmente, perdem ATK igual ao ATK original do monstro alvo. \r\nVocê só pode ativar 1 "Berço Enion, Cenote de Gelojade" por turno.','\r',char(13)),'\n',char(10)),'Adicionar um monstro "Gelojade" à sua mão?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7150545,'Tubarão Serra Circular',replace(replace('Você pode escolher 1 monstro de ÁGUA que você controla; Invoque por Invocação-Especial do seu Deck, em Posição de Defesa, 1 monstro Peixe com o mesmo Nível que o desse monstro, mas com um nome diferente e, se isso acontecer, ele não pode ativar seus efeitos neste turno e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto Monstros Xyz. \r\nVocê só pode usar este efeito de "Tubarão Serra Circular" uma vez por turno. \r\nSe este card for usado para a Invocação-Xyz de um monstro de ÁGUA, ele pode ser considerado como um monstro de Nível 3 ou 5.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7152333,'Terror Umbral Carniça','Uma vez por turno: você pode fazer com que o ATK deste card se torne 0 e, se isso acontecer, Invoque por Invocação-Especial 1 monstro "Terror Umbral" com 0 de ATK da sua mão.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7153114,'Barreira de Campo',replace(replace('Magias de Campo no campo não podem ser destruídas. \r\nNenhum duelista pode ativar um novo Card de Magia de Campo. \r\nVocê só pode controlar 1 "Barreira de Campo".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7161742,'Predaplanta Cordyceps','Durante sua Fase de Apoio: você pode banir este card do seu Cemitério e, depois, escolher 2 monstros "Predaplanta" de Nível 4 ou menos no seu Cemitério; Invoque-os por Invocação-Especial e, além disso, pelo resto deste turno, você não pode Invocar monstros por Invocação-Especial, exceto Monstros de Fusão, nem pode Invocar quaisquer monstros por Invocação-Normal/Baixar.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7165085,'Boneca de Isca',replace(replace('Escolha 1 card virado para baixo na Zona de Magias e Armadilhas; revele esse alvo, force sua ativação se for um Card de Armadilha, depois negue seu efeito se o momento da ativação estiver incorreto, e, se fizer isso, destrua-o. \r\n(Se não for um Card de Armadilha, devolva-o virado para baixo.) \r\nQuando este card for resolvido, embaralhe-o no Deck em vez de enviá-lo para o Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7166709,'Sacrifício com Cordas de Aço',replace(replace('Se este card estiver na sua mão ou no Cemitério: você pode revelar 1 monstro de Nível 5 ou mais na sua mão e, depois, ative 1 desses efeitos (mas você só pode usar cada efeito de "Sacrifício com Cordas de Aço" uma vez por turno); durante a Fase Final deste turno, perca 1000 PV se você não Invocou por Invocação-Normal o monstro revelado, ou um monstro com o mesmo nome original, depois de ativar este efeito.\r\n● Invoque este card por Invocação-Especial da sua mão.\r\n● Adicione este card do seu Cemitério à sua mão.\r\n● Bana este card do seu Cemitério e, se isso acontecer, adicione 1 monstro de Nível 5 ou mais do seu Cemitério à sua mão.','\r',char(13)),'\n',char(10)),'Ativar','Invocação Especial','Adicionar à mão','Banir este card','','','','','','','','','','','','');
INSERT INTO texts VALUES(7171149,'Golem do Mecanismo Antigo Toon',replace(replace('Não pode atacar no turno em que for Invocado. \r\nEnquanto você controlar "Mundo Toon" e seu oponente não controlar nenhum monstro Toon, este card pode atacar diretamente seu oponente. \r\nSe este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente. \r\nSe este card atacar, seu oponente não pode ativar quaisquer Magias/Armadilhas até o final da Etapa de Dano.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7180418,'Armadura Exe',replace(replace('Este card não pode atacar no mesmo turno em que é Invocado, por Invocação-Normal, Invocação-Virar, ou Invocação-Especial. \r\nDurante cada uma das suas e das Standby Phases do seu adversário, remova 1 Contador Mágico no seu Campo. \r\nSe você não o fizer, destrúa este card.','\r',char(13)),'\n',char(10)),'Remover 1 Marcador de Magia?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7183277,'Aurkus, o Druida Luminoso',replace(replace('Nenhum duelista pode escolher monstros "Luminoso(a)" (em qualquer lugar) como alvo de efeitos de card. \r\nDurante cada uma das suas Fases Finais: envie os 2 cards do topo do seu Deck para o Cemitério.','\r',char(13)),'\n',char(10)),'Envie 2 cards do seu Deck para o Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7194917,'Número 52: Rei Caranguejo Diamante',replace(replace('2 monstros de Nível 4	\r\nUma vez por turno: você pode desassociar 1 Matéria Xyz deste card; transforme a DEF deste card em 0 e, se isso acontecer, transforme o ATK dele em 3000. \r\nEssas mudanças duram até o final deste turno. \r\nSe este card atacar, ele é colocado em Posição de Defesa no final da Fase de Batalha. \r\nSe este card for atacado, coloque-o em Posição de Ataque no final da Etapa de Dano se ele não tinha nenhuma Matéria Xyz. \r\nVocê só pode controlar 1 "Número 52: Rei Caranguejo Diamante".','\r',char(13)),'\n',char(10)),'Alterar ATK/DEF','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7198399,'Pequena Maga Chocolate',replace(replace('Uma vez por turno: você pode descartar 1 monstro Mago; compre 1 card. \r\nUma vez por turno, se este card for escolhido como alvo de um ataque: você pode escolher 1 monstro Mago no seu Cemitério, exceto "Pequena Maga Chocolate"; Invoque-o por Invocação-Especial e, depois, mude o alvo do ataque para ele e, se isso acontecer, o ATK do monstro atacante se torna metade do seu ATK atual.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7200041,'Disparador Metálico',replace(replace('Quando este card for Invocado por Invocação-Normal, coloque 2 marcadores nele. \r\nEste card ganha 800 de ATK para cada um desses marcadores nele. \r\nSe este card seria destruído por um efeito de card, em vez disso, remova 1 dos marcadores deste card.','\r',char(13)),'\n',char(10)),'Colocar um marcador','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7206349,'Vernasílfide em Pleno Florescer',replace(replace('Todos os monstros que você controla ganham 1000 de ATK enquanto você controlar 5 ou mais monstros de TERRA. \r\nVocê só pode usar cada um dos seguintes efeitos de "Vernasílfide em Pleno Florescer" uma vez por turno. \r\nVocê pode banir 1 "Vernasílfide e os Botões de Flor" da sua mão ou do Cemitério; Invoque por Invocação-Especial 1 "Vera, a Deusa Vernasílfide" do seu Deck. \r\nSe um ou mais monstros "Vernasílfide" forem Invocados por Invocação-Especial do seu Cemitério (exceto durante a Etapa de Dano): você pode escolher 1 monstro no campo ou em qualquer Cemitério; devolva-o para a mão.','\r',char(13)),'\n',char(10)),'','Retornar um monstro para a mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7225792,'Larvas Mon','Um passo adiante na cadeia evolutiva, muito mais poderosa que Larvas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7236721,'Des-presar Espantagarra',replace(replace('Seu oponente não pode escolher Monstros Link "Espantagarra" ou "Visas Starfrost" que você controla como alvo de efeitos de card e, além disso, eles não podem ser destruídos pelos efeitos de card do seu oponente. \r\nBana qualquer monstro destruído em batalha com um Monstro Link "Espantagarra" ou "Visas Starfrost" que você controla. \r\nVocê pode banir 1 Monstro Link "Espantagarra" do seu campo ou do Cemitério e, depois, escolha 1 card que seu oponente controla; destrua-o. \r\nVocê só pode usar este efeito de "Des-presar Espantagarra" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7241272,'Maldição do Fogo do Dragão',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 Magia de Campo no campo; destrua-a. \r\nUma vez por turno: você pode Invocar por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional, usando monstros que você controla como Matérias de Fusão, incluindo este card.','\r',char(13)),'\n',char(10)),'Destruir um Card de Magia de Campo','Invocação Fusão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7243511,'Coalo-Coala',replace(replace('"Coala Marinho" + "Lontra de Árvore"	\r\nVocê pode enviar 1 monstro do Tipo Besta da sua mão ao Cemitério para escolher 1 monstro que seu oponente controla; destrua-o.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7264861,'Besta Inférnica','Se este card atacar enquanto você não tiver cards na sua mão, seu oponente não pode ativar quaisquer Cards de Magia ou Armadilha até depois da Etapa de Dano.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7268133,'Camarartista Espadachim Vívido',replace(replace('Quando seu oponente ganhar PV (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão e, se isso acontecer, o ATK deste card se torna igual aos PV que seu oponente ganhou. \r\nVocê pode oferecer este card como Tributo e, depois, escolher 1 monstro com a face para cima que você controla; ele ganha 1000 de ATK até o final deste turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Aumentar ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7279373,'Ator do Abismo - Pequena Estrela Cintilante',replace(replace('Escala de Pêndulo = 9\r\n[ Efeito de Pêndulo ]\r\nVocê não pode Invocar monstros por Invocação-Pêndulo, exceto monstros "Ator do Abismo". \r\nEste efeito não pode ser negado. \r\nUma vez por turno: você pode escolher 1 monstro "Ator do Abismo" que você controla; neste turno, ele pode realizar até 3 ataques contra monstros durante cada Fase de Batalha e, além disso, outros monstros que você controla não podem atacar pelo resto deste turno (mesmo que este card deixe o campo).\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nNão pode ser destruído em batalha durante o seu turno. \r\nEste card pode realizar até 3 ataques contra monstros durante cada Fase de Batalha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7291576,'Seis Samurai Secretos - Genba',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode escolher 1 dos seus monstros "Seis Samurai" banidos; adicione-o à sua mão. \r\nSe exatamente 1 monstro "Seis Samurai" que você controla (e nenhum outro card) seria destruído por um efeito de card, em vez disso, você pode banir este card do seu Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7293697,'Mundo Toon, o Mundo Perfeito',replace(replace('O nome deste card se torna "Mundo Toon" enquanto está na Zona de Campo.\r\nUma vez por turno: você pode adicionar 1 card "Toon", ou 1 card que menciona o noem de um card "Toon", do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Mundo Toon, o Mundo Perfeito" três vez por turno.\r\nAntes de resolver a ativação de outro card ou efeito, você pode banir 1 monstro Toon que você controla imediatamente após resolver aquele card/efeito, você também não pode banir monstros com o mesmo nome original com este efeito de "Mundo Toon, o Mundo Perfeito" pelo resto desse turno.','\r',char(13)),'\n',char(10)),'','Adicionar à mão','','Banir o monstro?','','','','','','','','','','','','');
INSERT INTO texts VALUES(7304544,'Abacaxi de Naturia',replace(replace('Todos os monstros com a face para cima que você controla se tornam monstros Planta. \r\nUma vez por turno, durante sua Fase de Apoio, se você não controlar um "Abacaxi de Naturia" com a face para cima e não tiver monstros no seu Cemitério, exceto monstros Planta ou Besta: você pode Invocar este card por Invocação-Especial do seu Cemitério. \r\nVocê não pode controlar nenhuma Magia ou Armadilha para ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7305060,'Amórfago da Avareza',replace(replace('Escala de Pêndulo = 3\r\n[ Efeito de Pêndulo ]\r\nEnquanto você controlar um monstro "Amórfago", nenhum duelista pode ativar Cards de Armadilha ou seus efeitos, exceto cards "Amórfago(a)". \r\nUma vez por turno, durante sua Fase de Apoio, ofereça 1 monstro como Tributo ou destrua este card.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe este card for Invocado por Invocação-Pêndulo ou virado com a face para cima, nenhum duelista pode Invocar monstros do Deck Adicional por Invocação-Especial enquanto este card estiver no campo com a face para cima, exceto monstros "Amórfago".','\r',char(13)),'\n',char(10)),'Oferecer como Tributo 1 monstro que você controla?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7320132,'Relíquia Nórdica Hlidskjalf',replace(replace('Invoque por Invocação-Especial 1 monstro "Nórdic" do seu Deck, mas você não pode Invocar monstros por Invocação-Especial do Deck Adicional, exceto monstros "Aesir", enquanto esse monstro estiver com a face para cima no campo. \r\nVocê pode banir este card do seu Cemitério; adicione 1 monstro "Nórdic" do seu Deck à sua mão e, depois, embaralhe no Deck 1 card da sua mão. \r\nVocê só pode usar 1 efeito de "Relíquia Nórdica Hlidskjalf" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Procurar no Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7336745,'Dinomorfia Intacta',replace(replace('Quando um efeito de monstro for ativado, enquanto você controlar um card "Dinomorfia": pague metade dos seus PV; negue a ativação e, se isso acontecer, destrua esse monstro e, além disso, sempre que você sofrer dano de batalha neste turno, o dano sofrido se torna metade dos seus PV daquele momento. \r\nDurante o cálculo de dano, enquanto seus PV forem 2000 ou menos, se você sofreria dano de batalha: você pode banir este card do seu Cemitério; você não sofre dano de batalha dessa batalha. \r\nVocê só pode ativar 1 "Dinomorfia Intacta" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7337976,'Apocalipse do Vácuo',replace(replace('Você pode descartar 1 card; envie 1 monstro Demônio do seu Deck para o Cemitério. \r\nVocê pode enviar este card com a face para cima da sua Zona de Magias & Armadilhas para o Cemitério; envie monstros "Infernoide" com nomes diferentes da sua mão e/ou do Deck para o Cemitério, até o número de monstros que seu oponente controla que foram Invocados por Invocação-Especial do Deck Adicional. \r\nVocê só pode usar 1 efeito de "Apocalipse do Vácuo" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Descarte 1 card','Envie este card para o Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7359741,'Caçador Mecânico','Um caçador que persegue incansavelmente seu alvo por ordem do Rei Máquina.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7369217,'Parasita - Lunático Metalizante',replace(replace('Uma vez por turno, durante a sua Main Phase, você pode equipar este card a um monstro no seu Campo com a face para cima como um Card de Magia de Equipamento, OU separar o Equipamento e Invocar, por Invocação-Especial, este card em Posição de Ataque com a face para cima. \r\nQuando este card é equipado pelo efeito deste card, esse monstro não é afetado pelo efeito de Cards de Magia controlados pelo seu adversário. \r\n(1 monstro pode ser equipado apenas por 1 Monstro de Union de cada vez. Se o monstro equipado com este card é destruído como resultado de um combate, em vez disso destrúa este card.)','\r',char(13)),'\n',char(10)),'Equipar','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7373632,'Evolução Divina',replace(replace('A ativação e o efeito deste card não podem ser negados. \r\nSelecione 1 monstro que você controla cujo Tipo original seja Besta Divina ou cujo nome original seja "O Perverso Avatar", "A Perversa Raiz do Medo" ou "O Perverso Apagador", exceto um ou mais monstros já afetados por "Evolução Divina", e ele ganha 1000 de ATK/DEF, a ativação dos seus efeitos e seus efeitos ativados não podem ser negados e, além disso, ele ganha o seguinte efeito.\r\n● Quando este card declarar um ataque: você pode fazer com que seu oponente envie 1 monstro que ele controla para o Cemitério (ele seleciona).','\r',char(13)),'\n',char(10)),'O efeito de "Evolução Divina" está sendo aplicado.','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7375867,'Mululu Caudraco',replace(replace('Durante a Fase Principal (Efeito Rápido): você pode Invocar por Invocação-Fusão 1 Monstro de Fusão "Caudraco" do seu Deck Adicional, usando monstros da sua mão ou do campo e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto Monstros de Fusão. \r\nSe este card for enviado para o Cemitério como matéria para uma Invocação-Fusão: você pode Baixar 1 Magia/Armadilha "Caudraco" do seu Deck e, depois, você pode negar os efeitos de 1 monstro com a face para cima que seu oponente controla. \r\nVocê só pode usar cada efeito de "Mululu Caudraco" uma vez por turno.','\r',char(13)),'\n',char(10)),'Efeito de Fusão','Baixar Magia/Armadilha','Negar um monstro?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7382007,'Gouki Ogro Sheik',replace(replace('2 monstros "Gouki"	\r\nSe um ou mais monstros "Gouki" forem adicionados do Deck à sua mão, exceto ao comprá-lo (exceto durante a Etapa de Dano): você pode Invocar por Invocação-Especial qualquer número de monstros "Gouki" com Níveis diferentes da sua mão, mas, para cada um, enquanto ele permanecer com a face para cima na sua Zona de Monstros, você não pode Invocar por Invocação-Especial, exceto monstros "Gouki". \r\nDurante sua Fase Principal: você pode Invocar por Invocação-Fusão 1 Monstro de Fusão "Gouki" do seu Deck Adicional, usando monstros da sua mão ou do campo. \r\nVocê só pode usar cada efeito de "Gouki Ogro Sheik" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Efeito de Fusão','Invocado por Invocação Especial pelo efeito de "Gouki Ogro Sheik"','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7391448,'Guardião Goyo',replace(replace('1 Regulador de TERRA + 1+ monstros não-Reguladores	\r\nQuando este card destruir um monstro do oponente em batalha e enviá-lo para o Cemitério: você pode Invocar esse monstro por Invocação-Especial no seu campo em Posição de Defesa.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7392745,'Mascaosso','VIRE: Invoque por Invocação-Especial 3 "Fichas de Mascaosso Jr." (Tipo Zumbi/TERRA/Nível 1/ATK 100/DEF 300) no campo do seu oponente em Posição de Defesa.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7392746,'Ficha de Mascaosso Jr.','Invocado por Especial com o efeito "Mascaosso".','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7394770,'Fusão Brilhante',replace(replace('Quando este card for ativado: Invoque por Invocação-Fusão 1 Monstro de Fusão "Cavaleiro-Gema" do seu Deck Adicional, usando monstros do seu Deck como Matéria de Fusão, mas mude o ATK/DEF dele para 0. \r\nSe este card deixar o campo, destrua esse monstro. \r\nUma vez por turno: você pode descartar 1 Magia; até o final do turno do seu oponente, o monstro Invocado por Invocação-Especial pelo efeito deste card ganha ATK/DEF iguais ao seu ATK/DEF originais. \r\nVocê só pode ativar 1 "Fusão Brilhante" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7403341,'Cinet Conflito',replace(replace('Quando um Card de Magia/Armadilha, ou efeito de monstro, for ativado enquanto você controlar um monstro "Codificar Transmissor": negue a ativação e, se isso acontecer, bana esse card e, se isso acontecer, até o final do próximo turno, seu oponente não pode ativar cards, ou efeitos de card, com o mesmo nome original que o desse card que foi banido. \r\nVocê só pode ativar 1 "Cinet Conflito" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7405310,'Portão Extra',replace(replace('Declare um Nível entre 1 e 12; seu oponente bane 1 monstro desse Nível do Deck Adicional dele. \r\nSe seu oponente não tiver um monstro desse Nível no Deck Adicional dele, você descarta 1 card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7407724,'Érica, a Fada Rikka',replace(replace('Quando um ataque for declarado envolvendo outro monstro Planta que você controla: você pode oferecer este card como Tributo da sua mão ou do campo com a face para cima; esse monstro que você controla ganha 1000 de ATK/DEF até o final deste turno. \r\nSe um ou mais monstros Planta que você controla forem oferecidos como Tributo, enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial em Posição de Defesa, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar cada efeito de "Érica, a Fada Rikka" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7409792,'Dinatério',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Dinatério" por Invocação-Especial uma vez por turno desta forma. \r\nQuando Invocado desta forma: seu oponente pode escolher 1 monstro de Nível 4 no Cemitério de qualquer duelista; ele Invoca o alvo por Invocação-Especial no lado do campo dele.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial no campo do seu oponente','Invocação Especial?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7436169,'Trivicarma',replace(replace('Escolha 1 "Visas Starfrost" na sua Zona de Monstros e 1 Monstro de Efeito que seu oponente controla; negue os efeitos de monstro do oponente e, se isso acontecer, seu monstro alvo ganha ATK igual à metade do ATK ou DEF original desse monstro (o que for maior). \r\nVocê pode banir este card do seu Cemitério; adicione 1 Magia/Armadilha que mencione "Visas Starfrost" do seu Deck à sua mão, exceto "Trivicarma". \r\nVocê só pode usar 1 efeito de "Trivicarma" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7443908,'Hayate, a Estrela Terrena',replace(replace('Se somente seu oponente controlar um monstro, ou se você controlar um monstro de LUZ, você pode Invocar este card por Invocação-Normal sem oferecer Tributo. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode Invocar por Invocação-Especial 1 monstro Guerreiro de LUZ de Nível 5 da sua mão. \r\nVocê só pode usar este efeito de "Hayate, a Estrela Terrena" uma vez por turno. \r\nUma vez por turno, quando um monstro Guerreiro seu for escolhido como alvo de um ataque: você pode fazer com que este card perca exatamente 500 de ATK e, se isso acontecer, negue o ataque.','\r',char(13)),'\n',char(10)),'Invocação Normal sem Tributo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7445307,'Dual Assembwurm',replace(replace('Se este card estiver na sua mão ou no Cemitério: você pode banir 2 outros monstros Ciberso da sua mão e/ou com a face para cima no seu campo; Invoque este card por Invocação-Especial, mas seu ATK é diminuído pela metade. \r\nVocê só pode usar este efeito de "Dual Assembwurm" uma vez por turno. \r\nUma vez por turno: você pode banir 1 card da sua mão; bana 1 monstro no campo com ATK menor ou igual que o deste card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7452945,'Armas Nobres do Destino',replace(replace('Você só pode controlar 1 "Armas Nobres do Destino". \r\nSó pode ser equipado em um monstro do Tipo Guerreiro. \r\nUma vez por turno, o monstro equipado não pode ser destruído em batalha ou por efeitos de card. \r\nSe este card no campo com a face para cima for destruído e enviado para o Cemitério: você pode escolher 1 monstro "Nobre Cavaleiro" do Tipo Guerreiro que você controla; equipe este card no alvo. \r\nVocê só pode usar este efeito de "Armas Nobres do Destino" uma vez por turno.','\r',char(13)),'\n',char(10)),'Equipar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7459013,'Zure, Cavaleiro do Mundo Negro','O nome deste ilustre cavaleiro é conhecido por todos os residentes do Mundo Negro. Ele nunca oprime os homens do povo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7459919,'Asanegra - Zonda, o Crepúsculo',replace(replace('Você não pode Invocar monstros por Invocação-Especial do Deck Adicional, exceto Monstros Sincro. \r\nVocê só pode usar 1 dos seguintes efeitos de "Asanegra - Zonda, o Crepúsculo" por turno e apenas uma vez por turno. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 monstro no campo; devolva-o para a mão. \r\nVocê pode banir este card do seu Cemitério; Invoque por Invocação-Especial 1 monstro "Asanegra" de Nível 5 ou mais da sua mão ou do Deck e, depois, sofra dano igual ao seu ATK.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7473735,'Fusão Sincro Harmônica',replace(replace('Envie 1 Regulador e 1 não-Regulador do seu campo com a face para cima para o Cemitério; Invoque por Invocação-Especial os dois monstros a seguir do seu Deck Adicional.\r\n● 1 Monstro Sincro que poderia ser Invocado por Invocação-Sincro usando apenas esses 2 monstros no Cemitério como matéria.\r\n● 1 Monstro de Fusão que poderia ser Invocado por Invocação-Fusão usando apenas esses 2 monstros no Cemitério como matéria.	\r\nVocê não pode Invocar por Invocação-Especial do Deck Adicional no turno em que ativar este card, exceto Monstros de Fusão ou Sincro. \r\nVocê só pode ativar 1 "Fusão Sincro Harmônica" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7477101,'Táquion do Sétimo',replace(replace('Revele 1 Monstro Xyz "Número" no seu Deck Adicional com um número entre "101" e "107" em seu nome; adicione 1 monstro do seu Deck à sua mão com o mesmo Tipo ou Atributo que o desse monstro, e o mesmo Nível que a Classe desse monstro e, depois, coloque 1 card da sua mão no topo do Deck e, além disso, pelo resto deste turno depois que este card resolver, você não pode Invocar por Invocação-Especial do Deck Adicional, exceto Monstros Xyz. \r\nVocê só pode ativar 1 "Táquion do Sétimo" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7478431,'Girassol de Naturia','Quando um efeito de monstro do seu oponente for ativado (Efeito Rápido): você pode oferecer como Tributo 1 monstro "Naturia" e este card; negue a ativação e, se isso acontecer, destrua esse card.','Negue a ativação do efeito de um Monstro de Efeito e destrua-o','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7480763,'Artefato Dagda',replace(replace('2 monstros com nomes diferentes	\r\nQuando um efeito de outro card no campo for ativado (Efeito Rápido): você pode Baixar 1 monstro "Artefato" da sua mão ou do Deck em uma Zona de Magias & Armadilhas sua como uma Magia, mas destrua-o durante a próxima Fase Final do seu oponente. \r\nDurante o turno do seu oponente, se este card Invocado por Invocação-Link for destruído: você pode Invocar por Invocação-Especial 1 monstro "Artefato" do seu Cemitério em Posição de Defesa. \r\nVocê só pode usar cada efeito de "Artefato Dagda" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7489323,'Milus Radiante','Enquanto este card permanecer no Campo com a face para a cima, aumente o ATK de todos os monstros da TERRA em 500 pontos e diminua o ATK de todos os monstros do VENTO em 400 pontos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7496001,'Pilhagem Springans',replace(replace('Se um Monstro Xyz com a face para cima que você controla deixar o campo devido a um efeito de card: você pode escolher 1 Monstro de Efeito que seu oponente controla; neste turno, nenhum duelista pode ativar os efeitos desse Monstro de Efeito no campo. \r\nVocê pode enviar este card com a face para cima para o Cemitério; ative 1 "Grande Mar de Areia - Gold Golgonda" diretamente do seu Deck ou Cemitério. \r\nVocê só pode usar cada efeito de "Pilhagem Springans" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Escolha o monstro que não poderá ativar efeitos','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7500772,'Tubarão Águia',replace(replace('Se seu oponente controlar 2 ou mais monstros, você pode Invocar este card por Invocação-Normal sem oferecer Tributo. \r\nSe você controlar "Tubarão Pantera", você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode controlar 1 "Tubarão Águia".','\r',char(13)),'\n',char(10)),'Invocar sem oferecer Tributo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7511613,'Dose Dupla de Ryzeal',replace(replace('2+ monstros de Nível 4	\r\nPara cada matéria que este card tiver, os monstros que você controla ganham 100 de ATK e os monstros que seu oponente controla perdem 100 de ATK. \r\nVocê só pode usar cada um dos seguintes efeitos de "Dose Dupla de Ryzeal" uma vez por turno. \r\nSe este card for Invocado por Invocação-Especial: você pode associar 1 monstro "Ryzeal" do seu Cemitério a este card como matéria. \r\nDurante sua Fase Principal: você pode desassociar 2 matérias de um ou mais monstros que você controla e, se isso acontecer, adicione 2 cards "Ryzeal" com nomes diferentes do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Associar Matéria Xyz','Efeito de busca','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7512044,'Junte a sua Mente',replace(replace('Adicione 1 card "Junte a sua Mente" do seu Deck à sua mão. \r\nEm seguida, embaralhe o seu Deck. \r\nVocê pode usar apenas 1 "Junte a sua Mente" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7526150,'Gargóleo','Um gigante de ferro que surge de uma fenda dimensional.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7540107,'Gouki Corajoso',replace(replace('Este card em Posição de Defesa não pode ser destruído em batalha. \r\nVocê só pode usar cada um dos seguintes efeitos de "Gouki Corajoso" uma vez por turno.\r\n● Durante sua Fase Principal: você pode fazer com que todos os monstros "Gouki" que você controla ganhem 200 de ATK.\r\n● Se este card for enviado do campo para o Cemitério: você pode adicionar 1 card "Gouki" do seu Deck à sua mão, exceto "Gouki Corajoso".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7541475,'Dragão Kabuki',replace(replace('Uma vez por turno, antes do cálculo de dano, se seu monstro atacou um monstro do oponente: você pode mudar a posição de batalha desse monstro que seu oponente controla. \r\nUma vez por turno, antes do cálculo de dano, se um monstro do oponente atacou um monstro seu: você pode mudar a posição de batalha desse monstro que você controla.','\r',char(13)),'\n',char(10)),'Alterar posição de batalha','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7548747,'Teurgia Magistus',replace(replace('Escolha 1 monstro "Magistus" que você controla; equipe-o com 1 monstro "Magistus", exceto um monstro de Nível 4, do seu Deck Adicional, Cemitério ou do campo com a face para cima. \r\nSe você tiver pelo menos 1 de cada dentre Monstros "Magistus" de Fusão, Sincro, Xyz e Link no seu Cemitério, em vez disso, você pode equipá-lo com 1 Monstro não-"Magistus" de Fusão, Sincro, Xyz ou Link do seu Deck Adicional. \r\nVocê só pode ativar "Teurgia Magistus" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7562372,'Olho Megassônico','Feito de metal misterioso, este monstro é uma máquina apocalíptica vinda dos confins do universo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7563579,'Camaramágico Plushfogo',replace(replace('Escala de Pêndulo = 5\r\n[ Efeito de Pêndulo ]\r\nSe um ou mais monstros "Camaramágico" com a face para cima que você controla forem destruídos em batalha ou por um efeito de card: você pode Invocar este card por Invocação-Especial e, depois, sofra 500 de dano. \r\nVocê só pode usar este efeito de "Camaramágico Plushfogo" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe este card no campo for destruído em batalha ou por um efeito de card: você pode Invocar por Invocação-Especial 1 monstro "Camaramágico" da sua mão ou do Deck, exceto "Camaramágico Plushfogo". \r\nVocê só pode usar este efeito de "Camaramágico Plushfogo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7565547,'Poder Acumulado',replace(replace('Escolha 1 monstro com a face para cima no campo; equipe-o com todos os Cards de Equipamento no campo. \r\nSe qualquer um desses Cards de Equipamento agora estiver equipado a um alvo incorreto, destrua esse Card de Equipamento.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7572887,'D.D. Lady Guerreira','Depois do cálculo de dano, quando este card batalhar um monstro do oponente: você pode banir esse monstro e, além disso, bana este card.','Banir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7573135,'Besta Gladiadora Augustus',replace(replace('Quando este card for Invocado por Invocação-Especial pelo efeito de um monstro "Besta Gladiadora": você pode Invocar por Invocação-Especial 1 monstro "Besta Gladiadora" da sua mão em Posição de Defesa. \r\nEmbaralhe-o no Deck durante a Fase Final. \r\nNo final da Fase de Batalha, se este card atacou ou foi atacado: você pode embaralhá-lo no Deck; Invoque por Invocação-Especial 1 monstro "Besta Gladiadora" do seu Deck, exceto "Besta Gladiadora Augustus".','\r',char(13)),'\n',char(10)),'Invocação Especial','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7574904,'Arsenal Miutante',replace(replace('Não pode ser Invocado por Invocação-Especial, exceto com o efeito de um card "Miutante". \r\nSeu oponente não pode escolher este card como alvo de efeitos de Armadilha. \r\nVocê só pode usar cada um dos seguintes efeitos de "Arsenal Miutante" uma vez por turno. \r\nQuando seu oponente ativar um efeito de monstro (Efeito Rápido): você pode banir 1 card da sua mão ou do campo e, depois, escolha 1 monstro no campo; bana-o. \r\nSe este card em posse do seu dono for destruído por um card do oponente: você pode escolher 1 das suas Magias "Miutante" banidas; adicione-a à sua mão.','\r',char(13)),'\n',char(10)),'Banir um monstro','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7576264,'Besta Fantasma Chifre-Selvagem','Se este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7582066,'Pesadelo Psíquico',replace(replace('1 Regulador + 1 ou mais monstros do Tipo Psíquico não-Reguladores	\r\nUma vez por turno, durante sua Fase Principal, você pode pegar 1 card aleatório na mão de seu oponente e declarar que tipo de card é (Monstro, Magia ou Armadilha). \r\nSe você declarar corretamente, este card ganha 1000 de ATK até a Fase Final do seu oponente.','\r',char(13)),'\n',char(10)),'Adivinhar um card na mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7593748,'Engenhoca Marionete Boneco Gigante',replace(replace('2 monstros "Engenhoca Marionete" de Nível 4	\r\nVocê pode desassociar 2 matérias deste card e, depois, escolha até 2 monstros que seu oponente controla; ganhe o controle deles até a Fase Final e, além disso, pelo resto deste turno, você não pode Invocar monstros por Invocação-Especial, exceto monstros "Engenhoca Marionete", nem declarar ataques, exceto com Monstros Xyz. \r\nVocê pode oferecer este card como Tributo; todos os monstros que você controla atualmente se tornam de Nível 8 até o final deste turno. \r\nVocê só pode usar cada efeito de "Engenhoca Marionete Boneco Gigante" uma vez por turno.','\r',char(13)),'\n',char(10)),'Tomar controle','Alterar o Nível','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7594154,'Donzelas-Bonecas Enganadoras de Zenna',replace(replace('2+ Monstros de Efeito	\r\nVocê também pode usar 1 monstro na sua mão como matéria para Invocar este card por Invocação-Link. \r\nVocê só pode usar cada um dos seguintes efeitos de "Donzelas-Bonecas Enganadoras de Zenna" uma vez por turno. \r\nSe este card for Invocado por Invocação-Link: você pode enviar 1 monstro do seu Deck para o Cemitério, ou, se todas as matérias usadas para sua Invocação-Link forem monstros que você controlava, em vez disso, você pode enviar 1 monstro do seu Deck Adicional. \r\nDurante sua próxima Fase de Apoio depois que este card foi enviado do campo para o Cemitério: você pode adicionar 1 monstro do seu Cemitério à sua mão.','\r',char(13)),'\n',char(10)),'Enviar para o Cemitério','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7602800,'Redemoinho da Pena Negra',replace(replace('Uma vez por turno, se você Invocar por Invocação-Especial um Monstro Sincro de TREVAS do Deck Adicional (exceto durante a Etapa de Dano): você pode escolher 1 dos seus monstros "Asanegra" ou "Dragão de Asas Negras" que estiverem banidos ou no seu Cemitério com menos ATK que esse monstro Invocado por Invocação-Especial; Invoque-o por Invocação-Especial. \r\nUma vez por turno, se um monstro de TREVAS que você controla seria destruído em batalha ou por um efeito de card, em vez disso, você pode remover 1 Marcador de Pena Negra do seu campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7602840,'UFOroide','Quando este card for destruído em batalha e enviado para o Cemitério: você pode Invocar por Invocação-Especial 1 monstro Máquina com 1500 ou menos de ATK do seu Deck com a face para cima em Posição de Ataque.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7608148,'Lanterna Vívida',replace(replace('Escolha 1 card que você controla; devolva-o para a mão. \r\nSe este card estiver no seu Cemitério: você pode escolher 1 card com a face para cima que você controla; Baixe este card (mas bana-o quando ele deixar o campo) e, se isso acontecer, devolva esse card com a face para cima para a mão, mas pelo resto deste turno, você não pode ativar cards, ou os efeitos de cards, com o mesmo nome que esse card tinha uma vez que ele voltou para a mão. \r\nVocê só pode usar 1 efeito de "Lanterna Vívida" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7610394,'Reemergência do Olho Maligno',replace(replace('Invoque por Invocação-Especial 1 "Ficha de Familiar do Olho Maligno" (Demônio/TREVAS/Nível 1/ATK 400/DEF 400), ou, se "Olho Maligno de Selene" estiver na sua Zona de Magias & Armadilhas, em vez disso, você pode Invocar 2 por Invocação-Especial e, além disso, pelo resto deste turno depois que este card resolver, você não pode Invocar monstros por Invocação-Especial, exceto monstros Demônio. \r\nVocê pode banir este card do seu Cemitério; seu oponente não pode escolher Magias/Armadilhas "Olho Maligno" que você controla como alvo de efeitos de card neste turno. \r\nVocê só pode usar cada efeito de "Reemergência do Olho Maligno" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Invocar 2 monstros por Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7610395,'Ficha de Familiar do Olho Maligno','Invocada por Invocação-Especial com o efeito "Reemergência do Olho Maligno".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7614732,'Polimerização Maior',replace(replace('Invoque por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional, usando 3 ou mais monstros da sua mão ou do campo como Matéria de Fusão e, se isso acontecer, ele ganha esses efeitos.\r\n● Este card não pode ser destruído por efeitos de card.\r\n● Se este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Fusão com o efeito de "Polimerização Maior"','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7617062,'Museu Fantardil',replace(replace('Os monstros que você controla, exceto monstros "Fantardil", não podem atacar. \r\nMonstros não podem atacar monstros com a face para baixo em Posição de Defesa, mas podem atacar diretamente se todos os monstros controlados pelo oponente estiverem com a face para baixo em Posição de Defesa. \r\nNo final da Etapa de Dano, coloque com a face para baixo em Posição de Defesa quaisquer monstros que causaram dano de batalha a um duelista durante esta batalha.','\r',char(13)),'\n',char(10)),'Mudar para Posição de Defesa com a face para baixo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7617253,'Caminho Arco-Íris','Quando um monstro do oponente declarar um ataque: envie 1 card "Fera Cristalina" da sua Zona de Magias & Armadilhas para o Cemitério e, depois, escolha o monstro atacante; negue o ataque e, depois, você pode adicionar 1 "Dragão Arco-Íris" ou "Dragão Negro Arco-Íris" do seu Deck à sua mão.','Adicionar 1 card "Cristalino/a Definitivo/a" à sua mão?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7622360,'Arquidemônio Matador',replace(replace('Você pode Invocar este card por Invocação-Ritual com "Ritual do Matador". \r\nSe este card for Invocado por Invocação-Ritual: você pode adicionar 2 cards "Arquidemônio" do seu Deck à sua mão, exceto "Arquidemônio Matador" e, além disso, este card não pode atacar pelo resto deste turno. \r\nVocê só pode usar este efeito de "Arquidemônio Matador" uma vez por turno. \r\nNão pode ser destruído em batalha e, além disso, você não sofre dano de batalha das batalhas envolvendo este card. \r\nDepois do cálculo de dano, se este card batalhou um monstro: destrua esse monstro e, se isso acontecer, cause 1000 de dano ao seu oponente.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7623640,'Cerúli, Guru do Mundo Negro',replace(replace('Se este card for descartado para o Cemitério por um efeito de card: Invoque este card por Invocação-Especial no campo do seu oponente em Posição de Defesa. \r\nSe este card for Invocado por Invocação-Especial pelo efeito de um card "Mundo Negro": seu oponente descarta 1 card.','\r',char(13)),'\n',char(10)),'Invocação Especial','Seu oponente descarta 1 card','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7625614,'Armadura Rara como Ouro','Enquanto você controlar o monstro equipado com este card, o seu adversário não pode atacar outros monstros exceto o monstro equipado.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7628844,'Número C32: Dragonete Tubarão LeVeiss',replace(replace('4 monstros de Nível 5	\r\nVocê também pode Invocar este card por Invocação-Xyz ao descartar 1 Magia e usar um Monstro Xyz "Dragonete Tubarão" de Classe 4 que você controla como matéria. \r\n(Transfira as matérias dele para este card.) \r\nUma vez por turno (Efeito Rápido): você pode desassociar 1 matéria deste card e, depois, escolha 1 Monstro de Efeito que seu oponente controla; negue seus efeitos e, se isso acontecer, seu ATK/DEF se tornam 0. \r\nEste card pode realizar um segundo ataque durante cada Fase de Batalha e, além disso, se ele atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Xyz usando o Monstro Xyz "Dragonete Tubarão" como matéria?','Negar o efeito','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7631534,'Pés dos Dois Avatares - Un-Gyo com Armadura',replace(replace('2 monstros "Dois Avatares"	\r\nSe um ou mais Monstros de Fusão "Dois Avatares" que você controla seriam destruídos por um efeito de card, em vez disso, você pode destruir 1 monstro "Dois Avatares" que você controla. \r\nDurante a Fase Principal, se você controlar um Monstro de Fusão "Dois Avatares" que foi Invocado por Invocação-Fusão usando um Monstro de Efeito como matéria (Efeito Rápido): você pode escolher 1 monstro com a face para cima Invocado por Invocação-Especial do Deck Adicional; negue os efeitos dele até o final deste turno. \r\nVocê só pode usar este efeito de "Pés dos Dois Avatares - Un-Gyo com Armadura" uma vez por turno.','\r',char(13)),'\n',char(10)),'Negar o efeito','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7634581,'Orichalcos Shunoros',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro deve ser Invocado por Invocação-Especial por seu próprio efeito. \r\nNo final da Etapa de Dano, se um Monstro Normal seu for destruído em batalha: você pode Invocar este card por Invocação-Especial da sua mão. \r\nGanha 1000 de ATK para cada monstro que seu oponente controla. \r\nMonstros Normais de Nível 4 com a face para cima no campo não podem ser destruídos por efeitos de card.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7653207,'Jato d''Água','Escolha 1 monstro do Tipo Peixe, Serpente Marinha ou Aqua com a face para cima que você controla; ele ganha 1000 de ATK.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7656689,'Genni, a Empregada de Endymion',replace(replace('(Este card deve ser sempre considerado como um card "Fazticeira".)	\r\nSe você controlar um monstro Mago e este card estiver na sua mão: você pode Invocar este card por Invocação-Especial. \r\nDurante a Fase Principal (Efeito Rápido): você pode escolher 1 monstro Mago que você controla; bana-o e, se isso acontecer, Invoque por Invocação-Especial 1 monstro "Fazticeira" do seu Deck, exceto "Genni, a Empregada de Endymion". \r\nVocê só pode usar cada efeito de "Genni, a Empregada de Endymion" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Banir e Invocar por Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7670542,'Bioplanta','Um monstro criado num grave acidente em um laboratório subterrâneo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7672244,'Espião Shien','Escolha 1 monstro com a face para cima que você controla; conceda o controle dele ao seu oponente até a Fase Final deste turno.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7700132,'Lombriga Nobre','VIRE: Se este card for virado com a face para cima pelo ataque de um monstro do oponente, cause dano igual à metade do ATK do monstro atacante.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7714344,'Camarartista Uni',replace(replace('Uma vez por turno, durante sua Fase Principal, se este card foi Invocado por Invocação-Normal ou Especial neste turno: você pode Invocar por Invocação-Especial 1 monstro "Camarartista" de Nível 3 ou menos da sua mão em Posição de Ataque. \r\nDurante o turno do seu oponente (Efeito Rápido): você pode banir 1 monstro "Camarartista", exceto "Camarartista Uni", e este card do seu Cemitério; na próxima vez que você sofreria dano de batalha neste turno, você não sofre.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7721912,'Detentor da Lança do Nobre Cavaleiro',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 monstro de Nível 8 ou menos que você controla; o nome dele se torna "Fleur Sincron" e, além disso, até a Fase Final, ele é considerado como um Regulador. \r\nVocê pode oferecer este card como Tributo; adicione 1 Magia de Equipamento do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "Detentor da Lança do Nobre Cavaleiro" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7733560,'Michion, o Senhor do Tempo',replace(replace('Não pode ser Invocado por Invocação-Especial do Deck. \r\nSe você não controlar nenhum monstro, você pode Invocar este card por Invocação-Normal sem oferecer Tributo. \r\nNão pode ser destruído em batalha ou por efeitos de card. \r\nVocê não sofre dano de batalha dos ataques envolvendo este card. \r\nNo final da Fase de Batalha, se este card batalhou: diminua pela metade os PV do seu oponente. \r\nUma vez por turno, durante sua Fase de Apoio: embaralhe este card no Deck.','\r',char(13)),'\n',char(10)),'Invocação Normal sem Tributo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7736719,'Patrulheiro Vortex',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode embaralhar no Deck 2 cards da sua mão e, depois, comprar 2 cards. \r\nSe este card for destruído: compre 1 card.','\r',char(13)),'\n',char(10)),'Embaralhar e comprar','Comprar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7778726,'Hip Hoshiningen',replace(replace('2 monstros de LUZ	\r\nTodos os monstros de LUZ no campo ganham 500 de ATK/DEF e, além disso, todos os monstros de TREVAS no campo perdem 400 de ATK/DEF. \r\nSe este card for destruído em batalha ou por um efeito de card: você pode escolher 1 monstro de LUZ no seu Cemitério; adicione-o à sua mão. \r\nVocê só pode usar este efeito de "Hip Hoshiningen" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7782069,'Gouki, O Ogro Tirano',replace(replace('1 Monstro Link "Gouki" + 1 monstro Guerreiro, Dinossauro ou Ciberso	\r\nSe este card batalhar, seu oponente não pode ativar cards ou efeitos até o final da Etapa de Dano. \r\nSe este card for Invocado por Invocação-Fusão: você pode escolher cards no campo até à soma dos Valores Link dos monstros "Gouki" usados como matéria para este card (se você usou um monstro de Link-3 ou mais, nenhum duelista pode ativar esses cards alvo ou seus efeitos em resposta à ativação deste efeito); destrua-os. \r\nVocê só pode usar este efeito de "Gouki, O Ogro Tirano" uma vez por turno.','\r',char(13)),'\n',char(10)),'Destruir','Não pode ativar efeitos','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7799906,'Camarartista Feiticeiro Sorridente',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nSe um ou mais monstros que você controla cujo ATK atual seja maior que seu ATK original forem destruídos em batalha ou por um efeito de card: você pode Invocar este card por Invocação-Especial da sua Zona de Pêndulo. \r\nVocê só pode usar este efeito de "Camarartista Feiticeiro Sorridente" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 Magia/Armadilha "Sorridente" do seu Deck à sua mão. \r\nSe todos os monstros que você controlar forem monstros "Camarartista" ou "Olhos Anômalos", ou Monstros Pêndulo "Mago", e o ATK atual deste card for maior que seu ATK original: você pode comprar cards igual ao número de monstros que você controla cujo ATK atual seja maior que seu ATK original e, além disso, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno. \r\nVocê só pode usar cada efeito de "Camarartista Feiticeiro Sorridente" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7802006,'Planta Mágica Mandrágona','VIRE: Coloque 1 Marcador de Magia em cada card com a face para cima no campo sobre o qual você possa colocar um Marcador de Magia.','Colocar um marcador','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7805147,'Dragões Soldados','Uma vez por turno, quando seu oponente ativar um card ou efeito (Efeito Rápido): você pode Invocar por Invocação-Especial 1 monstro Dragão de Nível 2 ou menos do seu Deck.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7805359,'Niwatori','Engole os inimigos por inteiro e usa suas essências como energia.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7811875,'Colapso da Gravidade','Quando seu oponente Invocaria um ou mais monstros: envie 1 Monstro Sincro com a face para cima que você controla para o Cemitério; negue a Invocação e, se isso acontecer, destrua esse monstro e seu oponente não pode Invocar um monstro até o final deste turno.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7817703,'Motor Morfotrônico',replace(replace('Só pode ser equipado a um monstro "Morfotrônico(a)" de Nível 3. \r\nSeu ATK se torna o dobro do seu ATK original. \r\nDurante sua segunda Fase de Apoio, depois da ativação deste card, destrua este card e sofra dano igual ao ATK original do monstro equipado.','\r',char(13)),'\n',char(10)),'Destruir este card','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7841112,'Dragão Majestoso Estelar',replace(replace('"Dragão Majestoso" + "Dragão da Poeira Estelar" + 1 monstro não-Regulador	\r\nDurante o turno de qualquer duelista, quando seu oponente ativar um card ou efeito: você pode oferecer este card como Tributo; negue a ativação e, se isso acontecer, destrua todos os cards que seu oponente controla. \r\nUma vez por turno: você pode escolher 1 monstro com a face para cima que seu oponente controla; negue os efeitos dele até o final deste turno e, uma vez por turno, você pode ativar 1 dos efeitos dele como se fosse um efeito deste card. \r\nDurante a Fase Final: escolha 1 "Dragão da Poeira Estelar" no seu Cemitério; devolva este card do campo para o Deck Adicional e, depois, Invoque o alvo por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Negue a ativação e depois destrua todos os cards que seu oponente controla','Negar efeitos','Retornar ao Deck Adicional','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7841921,'Gaia, o Cavaleiro Impetuoso em Carga',replace(replace('Você pode Invocar este card por Invocação-Normal sem oferecer Tributo. \r\nSe este card for Invocado por Invocação-Normal sem oferecer Tributo, seu ATK original se torna 1900. \r\nSe este card for oferecido como Tributo: você pode adicionar 1 monstro "Soldado do Lustro Negro" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Gaia, o Cavaleiro Impetuoso em Carga" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Normal sem Tributo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7845138,'Decomposição Interminável',replace(replace('Se você tiver 2000 PV ou menos, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nSe este card for Invocado por Invocação-Normal ou Especial: o ATK deste card se torna metade dos PV do oponente.','\r',char(13)),'\n',char(10)),'Alterar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7850740,'Slidegolfin Xyz',replace(replace('Se um Monstro Xyz for Invocado por Invocação-Especial no seu campo (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe um ou mais Monstros Xyz forem Invocados por Invocação-Especial no seu campo enquanto este card estiver no seu Cemitério, exceto no turno em que este card foi enviado para o seu Cemitério (e exceto durante a Etapa de Dano): você pode escolher 1 desses Monstros Xyz; associe este card a ele como matéria. \r\nVocê só pode usar cada efeito de "Slidegolfin Xyz" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7852509,'Loop da Destruição',replace(replace('O nome deste card se torna "Anel da Destruição" enquanto estiver no campo. \r\nUma vez por turno, se um ou mais monstros no campo forem destruídos por um efeito de card (exceto durante a Etapa de Dano): você pode escolher 1 monstro no campo; destrua-o e, se isso acontecer, cada duelista sofre 500 de dano.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7852510,'Loop da Destruição',replace(replace('O nome deste card se torna "Anel da Destruição" enquanto estiver no campo. \r\nUma vez por turno, se um ou mais monstros no campo forem destruídos por um efeito de card (exceto durante a Etapa de Dano): você pode escolher 1 monstro no campo; destrua-o e, se isso acontecer, cada duelista sofre 500 de dano.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7852878,'Três Mil Agulhas','No final da Etapa de Dano, se este card em Posição de Defesa foi atacado por um monstro cujo ATK é menor que a DEF deste card: Destrua o monstro atacante.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7864030,'Samurai Superpesado Tocha Explosiva',replace(replace('Quando um monstro do oponente declarar um ataque enquanto você não tiver nenhum Card de Magia/Armadilha no seu Cemitério: você pode enviar este card da sua mão para o Cemitério e, depois, escolher 1 monstro "Samurai Superpesado" que você controla; mude o alvo do ataque para ele e realize o cálculo de dano. \r\nUma vez por turno, quando um monstro do oponente declarar um ataque: você pode mudar o alvo do ataque para este card e realizar o cálculo de dano. \r\nNão pode ser destruído em batalha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7868571,'Metalmorfose Pratássaro',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno: você pode escolher 1 outro card com a face para cima que você controla; destrua-o e, se isso acontecer, Baixe 1 Magia/Armadilha "Metalmorfose" diretamente do seu Deck.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nUma soldada ruidosa em um jato prateado veloz. Não se pode rastreá-la, não se pode vê-la, é impossível escapar de seu laser super veloz.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7889323,'Confronto da Tri-Brigada',replace(replace('Se um monstro Besta, Besta-Guerreira ou Besta Alada for Invocado por Invocação-Especial no seu campo (exceto durante a Etapa de Dano): você pode escolher 1 dos seus monstros "Tri-Brigada" banidos; adicione-o à sua mão. \r\nDepois do cálculo de dano, se um monstro "Tri-Brigada" seu batalhou um monstro do oponente: você pode devolver o monstro do oponente para a mão. \r\nVocê só pode usar cada efeito de "Confronto da Tri-Brigada" uma vez por turno.','\r',char(13)),'\n',char(10)),'Recuperar monstros banidos','Retornar um monstro do oponente para a mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7892180,'Kappa Psíquico','Um anfíbio com um gigantesco número de poderes que o protegem de ataques inimigos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7894706,'As Bestas Sagradas Caóticas Fantasmas',replace(replace('3 monstros de Nível 10 que não podem ser Invocados por Invocação-Normal/Baixados	\r\nDeve ser Invocado por Invocação-Fusão, ou por Invocação-Especial (do seu Deck Adicional) ao enviar os cards acima que você controla para o Cemitério. \r\nVocê só pode Invocar "As Bestas Sagradas Caóticas Fantasmas" por Invocação-Especial uma vez por turno desta forma, não importa o método que usar. \r\nNas primeiras duas vezes que este card no campo seria destruído por um efeito de card a cada turno, ele não é destruído. \r\nUma vez por Corrente, até três vezes por turno (Efeito Rápido): você pode escolher 1 monstro com a face para cima que seu oponente controla; negue seus efeitos (até o final deste turno) e, depois, você pode ganhar PV igual à metade do ATK desse monstro.','\r',char(13)),'\n',char(10)),'Negar o efeito','Ganhar PV?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7894707,'As Bestas Sagradas Caóticas Fantasmas',replace(replace('3 monstros de Nível 10 que não podem ser Invocados por Invocação-Normal/Baixados	\r\nDeve ser Invocado por Invocação-Fusão, ou por Invocação-Especial (do seu Deck Adicional) ao enviar os cards acima que você controla para o Cemitério. \r\nVocê só pode Invocar "As Bestas Sagradas Caóticas Fantasmas" por Invocação-Especial uma vez por turno desta forma, não importa o método que usar. \r\nNas primeiras duas vezes que este card no campo seria destruído por um efeito de card a cada turno, ele não é destruído. \r\nUma vez por Corrente, até três vezes por turno (Efeito Rápido): você pode escolher 1 monstro com a face para cima que seu oponente controla; negue seus efeitos (até o final deste turno) e, depois, você pode ganhar PV igual à metade do ATK desse monstro.','\r',char(13)),'\n',char(10)),'Negar o efeito','Ganhar PV?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7902349,'Braço Esquerdo de "O Proibido"','Um braço esquerdo, proibido e selado por magia. Qualquer um que romper este selo obterá poder infinito.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7903368,'Caveira de Cristal',replace(replace('Se este card for Invocado: sofra 1000 de dano e, depois, coloque este card em Posição de Defesa. \r\nDurante a Fase Final, se você não sofreu dano de efeito neste turno: você pode adicionar à sua mão ou Invocar por Invocação-Especial 1 monstro Rocha com 0 de ATK do seu Deck. \r\nVocê só pode usar este efeito de "Caveira de Cristal" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7913375,'Artilharia Tartaruga Catapulta',replace(replace('Você pode oferecer 1 monstro como Tributo; Invoque por Invocação-Especial 1 monstro "Gaia, o Cavaleiro Impetuoso", ou 1 monstro Dragão de Nível 5, da sua mão ou do Deck. \r\nVocê só pode usar este efeito de "Artilharia Tartaruga Catapulta" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7914843,'Traça Eletromagnética',replace(replace('VIRE: Escolha 1 monstro do Tipo Máquina que seu oponente controla; tome o controle do alvo até sua próxima Fase Final.\r\nSe este card for destruído em batalha: o monstro que o destruiu perde 500 de ATK e DEF.','\r',char(13)),'\n',char(10)),'Tomar controle','Reduzir ATK/DEF','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7917970,'Vento Divino da Dragunidade',replace(replace('Durante sua Fase Principal: você pode aplicar 1 desses efeitos, ou se "Ravina de Dragões" estiver no seu Cemitério, você pode aplicar quaisquer deles, em sequência;\r\n● Adicione 1 monstro Dragão ou Besta Alada do seu Cemitério à sua mão.\r\n● Invoque por Invocação-Especial 1 monstro "Dragunidade" da sua mão e, depois, você pode equipar 1 monstro Dragão "Dragunidade" do seu Deck a ele como uma Magia de Equipamento.	\r\nVocê só pode usar este efeito de "Vento Divino da Dragunidade" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar','Adicionar este card à mão?','Invocação Especial?','Equipar um monstro?','','','','','','','','','','','','');
INSERT INTO texts VALUES(7922915,'Navegação do Mago',replace(replace('Invoque por Invocação-Especial 1 "Mago Negro" da sua mão e, depois, Invoque por Invocação-Especial 1 monstro Mago de TREVAS de Nível 7 ou menos do seu Deck. \r\nSe você controlar "Mago Negro", exceto no turno em que este card foi enviado para o Cemitério: você pode banir este card do seu Cemitério e, depois, escolha 1 Magia/Armadilha com a face para cima que seu oponente controla; negue seus efeitos até o final deste turno.','\r',char(13)),'\n',char(10)),'Negar o efeito','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7925734,'Maçã Link',replace(replace('Você pode revelar este card na sua mão; bana (com a face para cima) 1 card aleatório com a face para baixo do seu Deck Adicional e, depois, Invoque este card por Invocação-Especial se o card banido era um Monstro Link. \r\nCaso contrário, descarte este card e, se isso acontecer, compre 1 card. \r\nVocê só pode usar este efeito de "Maçã Link" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7930346,'Deusa Origami',replace(replace('Uma vez por turno, durante sua Fase Principal: você pode lançar uma moeda até que o resultado seja coroa e, se isso acontecer, compre 1 card para cada 2 caras. \r\nSempre que um efeito de lançar moeda resolver enquanto este monstro estiver no campo: dobre o ATK deste card para cada cara deste efeito.','\r',char(13)),'\n',char(10)),'','Dobrar ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7934362,'Camaramágico Dançarina de Fogo',replace(replace('Escala de Pêndulo = 6\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno: você pode escolher 1 monstro "Camaramágico" que você controla; se ele atacar um monstro em Posição de Defesa neste turno, cause dano de batalha perfurante ao seu oponente.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 monstro "Camaramágico" do seu Deck à sua mão, exceto "Camaramágico Dançarina de Fogo". \r\nVocê só pode usar este efeito de "Camaramágico Dançarina de Fogo" uma vez por turno. \r\nSe este card no campo for destruído em batalha ou por um efeito de card: você pode escolher 1 monstro com a face para cima no campo; ele perde 500 de ATK.','\r',char(13)),'\n',char(10)),'Conceder dano perfurante','Efeito de busca','Reduzir ATK','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7935043,'Égide do Dragão Senhor do Oceano','Até a Fase Final, monstros de ÁGUA de Nível 3 ou menos com a face para cima que você controla não podem ser destruídos em batalha ou por efeitos de card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7953868,'Oni de Sangue Azul',replace(replace('Quando este card for Invocado por Invocação-Normal ou Invocação-Virar: Ele é colocado em Posição de Defesa. \r\nUma vez por turno: Você pode desassociar 1 Matéria Xyz que você controla para escolher 1 monstro do Tipo Zumbi de Nível 4 no seu Cemitério; Invoque o alvo por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Mudar para Posição de Defesa','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7969770,'Transefamiliar','Uma vez por turno: você pode escolher 1 monstro que você controla; mova o alvo para outra das suas Zonas de Monstros Principais.','','Escolha a zona para a qual mover','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7984540,'Dafne de Solaravalon',replace(replace('2 monstros Planta	\r\nEste card não pode ser escolhido como alvo de ataques, mas isso não impede seu oponente de atacar você diretamente. \r\nVocê pode oferecer 1 monstro como Tributo e, depois, escolha 2 Monstros Link Planta no seu Cemitério, exceto "Dafne de Solaravalon"; devolva-os para o Deck Adicional. \r\nVocê só pode usar este efeito de "Dafne de Solaravalon" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Escolha o card a ser devolvido ao Deck Adicional','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7986397,'Evolução Revendorror',replace(replace('Este card pode ser usado para Invocar por Invocação-Ritual qualquer Monstro de Ritual "Vendorror" da sua mão ou do Cemitério. \r\nVocê também deve oferecer como Tributo monstros da sua mão ou do campo, e/ou enviar 1 monstro "Vendorror" do seu Deck para o Cemitério, cuja soma dos Níveis seja igual ao Nível do Monstro de Ritual que você Invocou por Invocação-Ritual. \r\nO monstro Invocado por Invocação-Ritual é destruído durante a Fase Final do próximo turno. \r\nVocê só pode ativar 1 "Evolução Revendorror" por turno.','\r',char(13)),'\n',char(10)),'Enviar 1 monstro "Vendorror" do seu Deck para o Cemitério?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(7987191,'Dragão do Motim Callibregado',replace(replace('Você pode Invocar este card por Invocação-Ritual com "Interconector Pesado". \r\nQuando seu oponente Invocar um ou mais monstros por Invocação-Especial (Efeito Rápido): você pode negar a Invocação-Especial e, se isso acontecer, destrua esse(s) monstro(s) e, depois, destrua este card ou 1 monstro "Foguette" que você controla. \r\nSe este card estiver no seu Cemitério: você pode escolher 1 monstro "Callibre" ou "Foguette" no seu Cemitério; destrua 1 card que você controla ou na sua mão e, se isso acontecer, adicione o alvo à sua mão. \r\nVocê só pode usar cada efeito de "Dragão do Motim Callibregado" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8025950,'Caixa Dispositivo',replace(replace('(Este card deve ser sempre considerado como um card "Morfotrônico(a)".)	\r\nQuando este card for ativado: coloque 3 Marcadores de Morfo nele. \r\nUma vez por turno, durante sua Fase Principal: você pode remover 1 Marcador de Morfo do seu campo e, se isso acontecer, Invoque por Invocação-Especial 1 "Ficha de Caixa Dispositivo" (Máquina/TERRA/Nível 1/ATK 0/DEF 0). \r\nEnquanto essa Ficha estiver na Zona de Monstros, o duelista que a Invocou não pode Invocar monstros por Invocação-Especial do Deck Adicional, exceto Monstros Sincro. \r\nVocê só pode ativar 1 "Caixa Dispositivo" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8025951,'Ficha de Caixa Dispositivo','Invocado por Especial com o efeito "Caixa Dispositivo".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8034697,'Marioneta Mágica',replace(replace('Sempre que um Card de Magia for ativado, coloque 1 Marcador de Magia neste card quando esse Card de Magia resolver. \r\nGanha 200 de ATK para cada Marcador de Magia nele. \r\nVocê pode remover 2 Marcadores de Magia deste card e, depois, escolha 1 monstro no campo; destrua-o.','\r',char(13)),'\n',char(10)),'Colocar Marcadores de Magia','Destruir 1 monstro','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8038143,'Transmigração Táquion',replace(replace('Se você controlar um monstro "Olhos das Galáxias": ative como um Elo de Corrente 2 ou mais; negue as ativações dos Cards de Magia/Armadilha e dos efeitos de monstro do seu oponente ativados antes deste card nesta Corrente e, se isso acontecer, embaralhe no Deck os cards negados que estiverem no campo. \r\nSe você controlar um monstro "Dragão de Táquion de Olhos das Galáxias", você pode ativar este card da sua mão.','\r',char(13)),'\n',char(10)),'Ativar aplicando o efeito de "Transmigração Táquion".','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8039562,'Alfanje Dragunidade',replace(replace('Você pode banir este card da sua mão ou do Cemitério e, depois, escolha 1 monstro "Dragunidade" que você controla; equipe 1 monstro Dragão "Dragunidade" do seu Deck ou Cemitério a ele como uma Magia de Equipamento. \r\nEnquanto este card estiver equipado a um monstro "Dragunidade": você pode enviar este card para o Cemitério e, depois, escolha 1 card com a face para cima que seu oponente controla; bana-o. \r\nVocê só pode usar cada efeito de "Alfanje Dragunidade" uma vez por turno.','\r',char(13)),'\n',char(10)),'Efeito de Equipamento','Efeito de banimento','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8041569,'Senhora do Lago Laval','Se este card estiver no seu Cemitério e você tiver 3 ou mais monstros "Laval" com nomes diferentes no seu Cemitério: Você pode banir este card e 1 outro monstro "Laval" do seu Cemitério para escolher 1 card Baixado que seu oponente controla; destrua o alvo.','Destrua 1 card Baixado que seu oponente controla','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8057630,'Reforço do Núcleo',replace(replace('Selecione e Invoque por Invocação-Especial 1 monstro "Koa''ki Meiru" do seu Cemitério em Posição de Ataque. \r\nQuando esse monstro for destruído durante sua Fase Final, o controlador deste card sofre dano igual ao ATK desse monstro. \r\nQuando este card for removido do campo, destrua esse monstro. \r\nQuando esse monstro for destruído, destrua este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8058240,'Corrente de Conexão','As algemas místicas desta corrente podem roubar o poder dos inimigos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8062132,'Vennominaga, a Divindade das Serpentes Venenosas',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial com "Ascenção da Divindade Serpente" ou por seu próprio efeito. \r\nGanha 500 de ATK para cada monstro Réptil no seu Cemitério. \r\nNenhum duelista pode escolher este card como alvo de efeitos de card e, além disso, ele não é afetado por outros cards e seus efeitos. \r\nQuando este card for destruído em batalha e enviado para o Cemitério: você pode banir 1 outro monstro Réptil do seu Cemitério; Invoque este card por Invocação-Especial. \r\nQuando este card causar dano de batalha ao seu oponente: coloque 1 Marcador de Hiperveneno neste card. \r\nQuando o 3° Marcador de Hiperveneno for colocado neste card, você vence o Duelo.','\r',char(13)),'\n',char(10)),'Invocação Especial','Colocar um marcador','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8078366,'Esquadrão de Ataque Atlante','Ganha 800 de ATK enquanto você controlar um monstro Peixe, Serpente Marinha ou Aqua que não seja este card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8080257,'Dançaespada das Chamas',replace(replace('Se um ou mais monstros forem Invocados por Invocação-Especial: Invoque por Invocação-Especial 1 Monstro de Fusão de Nível 7 ou menos do seu Deck Adicional que seja "Espadachim das Chamas" ou que o mencione e, depois, você pode colocar 1 monstro com a face para cima no campo com a face para baixo em Posição de Defesa. \r\nDurante a Fase de Batalha do seu oponente: você pode banir este card do seu Cemitério e oferecer como Tributo 1 monstro com a face para baixo em Posição de Defesa; Invoque por Invocação-Especial 1 "Espadachim das Chamas", ou 1 monstro que o mencione, do seu Deck ou Deck Adicional. \r\nVocê só pode usar este efeito de "Dançaespada das Chamas" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invoque por Invocação Especial do Deck Adicional','Invoque por Invocação Especial 1 monstro do seu Deck/Deck Adicional','Mudar um monstro para Posição de Defesa com a face para baixo?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8083925,'Tela da Live☆Gêmea',replace(replace('Descarte 1 card; Invoque por Invocação-Especial 1 monstro "Ki-sikil" ou 1 monstro "Lil-la" do seu Deck e, além disso, pelo resto deste turno depois que este card resolver, você não pode Invocar monstros do Deck Adicional por Invocação-Especial, exceto monstros "Evil★Gêmea". \r\nVocê só pode ativar 1 "Tela da Live☆Gêmea" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8085950,'Dragão em Chamas',replace(replace('Se seu oponente controlar 2 ou mais monstros e este card estiver na sua mão: você pode Invocar este card por Invocação-Especial. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode descartar 1 Magia; destrua todas as Magias e Armadilhas no campo. \r\nVocê só pode usar cada efeito de "Dragão em Chamas" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8091563,'Super Robô de Defesa Leão',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode Invocar por Invocação-Especial 1 monstro "Super Robô de Defesa" ou "Orbital 7" da sua mão. \r\nUma vez por turno, quando exatamente 1 monstro "Super Robô de Defesa" ou "Orbital 7" (e nenhum outro card) for adicionado do seu Cemitério à sua mão (exceto durante a Etapa de Dano): você pode Invocá-lo por Invocação-Especial da sua mão.','\r',char(13)),'\n',char(10)),'Invocação Especial','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8102334,'Bloqueador de Portões',replace(replace('Negue os efeitos das Magias de Campo do seu oponente. \r\nSeu oponente não pode colocar marcadores em cards no campo. \r\nSeu oponente não pode escolher outros monstros que você controla como alvo de efeitos de card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8124921,'Perna Direita de "O Proibido"','Uma perna direita, proibida e selada por magia. Qualquer um que romper este selo obterá poder infinito.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8129306,'Prímula, a Fada Rikka',replace(replace('Se um monstro que você controla for oferecido como Tributo (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão em Posição de Defesa. \r\nVocê pode escolher até 2 monstros Planta que você controla; aumente o Nível dele(s) em 2 até o final deste turno. \r\nVocê só pode usar cada efeito de "Prímula, a Fada Rikka" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8131171,'Serpente Sinistra',replace(replace('Durante sua Fase de Apoio, se este card estiver no seu Cemitério: você pode devolvê-lo à sua mão e, além disso, bana 1 "Serpente Sinistra" do seu Cemitério durante a próxima Fase Final do seu oponente. \r\nVocê só pode usar este efeito de "Serpente Sinistra" uma vez por turno.','\r',char(13)),'\n',char(10)),'Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8148322,'Fusão Predaprimitiva',replace(replace('Se um ou mais monstros "Predaplanta" estiverem no campo: Invoque por Invocação-Fusão 1 Monstro de Fusão de TREVAS do seu Deck Adicional, usando monstros de qualquer campo como matéria, incluindo 2 ou mais monstros de TREVAS que você controla. \r\nVocê só pode ativar 1 "Fusão Predaprimitiva" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8152834,'Tarai',replace(replace('Se este card estiver na sua mão: você pode escolher 1 monstro com a face para cima na Zona de Monstros Principal que ativou seu efeito no campo neste turno; destrua-o e, se isso acontecer, Invoque este card por Invocação-Especial na zona em que esse monstro estava. \r\nVocê só pode usar este efeito de "Tarai" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8165596,'Número 90: Senhor de Fóton de Olhos das Galáxias',replace(replace('2 monstros de Nível 8	\r\nSe este card tiver um card "Fóton" como matéria, ele não pode ser destruído por efeitos de card. \r\nVocê só pode usar cada um dos seguintes efeitos de "Número 90: Senhor de Fóton de Olhos das Galáxias" uma vez por turno.\r\n● Quando um monstro do oponente ativar seu efeito (Efeito Rápido): você pode desassociar 1 matéria deste card; negue o efeito desse monstro e, se a matéria desassociada foi um card "Galáxia", destrua esse card.\r\n● Durante o turno do seu oponente (Efeito Rápido): você pode buscar 1 card "Fóton" ou "Galáxia" do seu Deck e adicioná-lo à sua mão ou associá-lo a este card como matéria.','\r',char(13)),'\n',char(10)),'Negar o efeito','Procurar no Deck ou associar Matéria Xyz','Sobrepor como Matéria Xyz','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8170654,'Kra-Milho Gigante',replace(replace('Quando um monstro do oponente declarar um ataque: você pode Invocar este card por Invocação-Especial da sua mão em Posição de Defesa e, se isso acontecer, mude o alvo do ataque para este card e realize o cálculo de dano. \r\nVocê pode escolher 1 monstro Planta que você controla, exceto "Kra-Milho Gigante"; o ATK desse monstro e o deste card se tornam o ATK original combinado dos dois monstros. \r\nVocê só pode usar cada efeito de "Kra-Milho Gigante" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Alterar ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8173184,'Controlador Genex Reparado',replace(replace('1 monstro "Genex" de Nível 4 ou menos	\r\nVocê só pode Invocar um ou mais "Controlador Genex Reparado" por Invocação-Especial uma vez por turno. \r\nSe este card for Invocado por Invocação-Link: você pode adicionar 1 monstro "Genex" do seu Cemitério à sua mão. \r\nUma vez por Corrente, se um ou mais monstros "Genex" forem adicionados à sua mão, exceto ao comprá-los, você pode (exceto durante a Etapa de Dano): imediatamente depois que este efeito resolver, Invocar por Invocação-Normal 1 monstro "Genex" e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto Invocar por Invocação-Sincro usando um Regulador "Genex" como matéria.','\r',char(13)),'\n',char(10)),'Adicionar do Cemitério à mão','Invocar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8175346,'Draco Poki','Quando este card for Invocado por Invocação-Normal: Você pode adicionar 1 "Draco Poki" do seu Deck à sua mão.','Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8192327,'Fosfofúria, o Senhor Elemental',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao ter exatamente 5 monstros de LUZ no seu Cemitério. \r\nQuando este card for Invocado por Invocação-Especial: você pode destruir todos os monstros que seu oponente controla. \r\nVocê só pode usar este efeito de "Fosfofúria, o Senhor Elemental" uma vez por turno. \r\nSe este card com a face para cima deixar o campo, pule a Fase de Batalha do seu próximo turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8198620,'Dragão Draconecro Alma-Infernal',replace(replace('2 monstros Zumbi	\r\nPrimeiro deve ser Invocado por Invocação-Fusão. \r\nMonstros não podem ser destruídos em batalha com este card. \r\nNo final da Etapa de Dano, se este card batalhou um monstro: mude o ATK desse monstro para 0 e, além disso, se esse monstro ainda estiver com a face para cima no campo, Invoque por Invocação-Especial 1 "Ficha de Alma Negra" (Zumbi/TREVAS/Nível ?/ATK ?/DEF 0) com o mesmo Nível/ATK que o Nível/ATK originais desse monstro. \r\nVocê só pode controlar 1 "Dragão Draconecro Alma-Infernal".','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8198621,'Ficha de Alma Negra','Invocado por Especial com o efeito "Dragão Draconecro Alma-Infernal".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8198712,'Fim do Mundo',replace(replace('Este card é usado para a Invocação-Ritual de "Ruína, a Rainha do Esquecimento" ou "Demise, o Rei do Armagedom". \r\nVocê também deve oferecer como Tributo monstros da sua mão ou do campo cuja soma dos Níveis seja exatamente igual ao Nível do Monstro de Ritual que você Invocar por Invocação-Ritual.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8200556,'Miutante ST-46',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 Magia/Armadilha "Miutante" do seu Deck à sua mão. \r\nVocê pode oferecer este card como Tributo e, depois, bana 1 card da sua mão ou do campo com a face para cima; Invoque por Invocação-Especial 1 monstro da sua mão ou do Deck, de acordo com o card banido.\r\n● Monstro: "Besta Miutante"\r\n● Magia: "Névoa Miutante"\r\n● Armadilha: "Arsenal Miutante"\r\nVocê só pode usar cada efeito de "Miutante ST-46" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8201910,'Menino Estrela','Enquanto este card permanecer no Campo com a face para a cima, aumente o ATK de todos os monstros da ÁGUA em 500 pontos e diminua o ATK de todos os monstros do FOGO em 400 pontos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8226374,'Engenhoca Marionete Humpty Dumpty',replace(replace('Quando este card for Invocado por Invocação-Normal ou Especial: você pode Invocar por Invocação-Especial 1 monstro "Engenhoca Marionete" da sua mão. \r\nVocê só pode usar este efeito de "Engenhoca Marionete Humpty Dumpty" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8233522,'Aliado da Justiça Leitor de Ciclos','(Efeito Rápido): você pode descartar este card para o Cemitério e, depois, escolha até 2 monstros de LUZ no Cemitério do seu oponente; bana os alvos.','Banir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8240199,'Sábio com Azul nos Olhos',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode adicionar 1 Regulador de LUZ de Nível 1 do seu Deck à sua mão, exceto "Sábio com Azul nos Olhos". \r\nVocê pode descartar este card e, depois, escolha 1 Monstro de Efeito que você controla; envie-o para o Cemitério e, se isso acontecer, Invoque por Invocação-Especial 1 monstro "Olhos Azuis" do seu Deck. \r\nVocê só pode usar este efeito de "Sábio com Azul nos Olhos" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8243121,'Lirilusc - Penas Fantasma',replace(replace('Escolha 1 monstro "Lirilusc" que você controla; o ATK de todos os monstros que seu oponente controla atualmente se torna o ATK atual desse monstro e, além disso, o Nível/Classe deles se torna 1. \r\nQuando um monstro do oponente declarar um ataque contra um monstro "Lirilusc" seu: você pode banir este card do seu Cemitério; até o final deste turno, o ATK do seu monstro se torna o ATK desse monstro do oponente. \r\nVocê só pode usar cada efeito de "Lirilusc - Penas Fantasma" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8251996,'Furacão Delta Ojama!!','Se você controlar "Ojama Verde", "Ojama Amarelo" e "Ojama Negro": destrua todos os cards que seu oponente controla.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8252010,'Sabre-X Gottoms',replace(replace('1 Regulador + 1+ monstros de TERRA	\r\nSe este card for Invocado por Invocação-Sincro: você pode adicionar 1 Magia/Armadilha "Sabre" ou "Gottoms" do seu Deck à sua mão. \r\nQuando este card causar dano de batalha ao seu oponente: você pode descartar 1 card aleatório da mão dele. \r\nQuando um monstro "Sabre-X" seu for escolhido como alvo de um ataque enquanto este card estiver no seu Cemitério: você pode Invocar este card por Invocação-Especial e, depois, mude o alvo do ataque para este card. \r\nVocê só pode usar cada efeito de "Sabre-X Gottoms" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Descarte 1 card','Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8264361,'Dharc, o Encantador das Trevas, Sombrio',replace(replace('2 monstros, incluindo um monstro de TREVAS	\r\n(Este card deve ser sempre considerado como um card "Espírito-Possuído".)	\r\nVocê pode escolher 1 monstro de TREVAS no Cemitério do seu oponente; Invoque-o por Invocação-Especial em uma zona sua para a qual este card apontar. \r\nSe este card Invocado por Invocação-Link for destruído em batalha, ou for destruído por um efeito de card do oponente enquanto estiver na Zona de Monstros do seu dono: você pode adicionar 1 monstro de TREVAS com 1500 ou menos de DEF do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "Dharc, o Encantador das Trevas, Sombrio" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8267140,'Ciclone Cósmico','Pague 1000 PV e, depois, escolha 1 Magia/Armadilha no campo; bana-a.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8275702,'Promessa Cristalina','Escolha 1 card "Fera Cristalina" na sua Zona de Magias & Armadilhas; Invoque o alvo por Invocação-Especial.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8279188,'Amuleto das Profundezas',replace(replace('Quando um monstro do seu oponente declarar um ataque, você pode descartar 1 card para negar o ataque. \r\nDestrua este card durante a 3ª Fase Final do oponente depois da ativação.','\r',char(13)),'\n',char(10)),'Usar o efeito de "Amuleto das Profundezas" agora?','Negar o ataque','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8284390,'Velocidaroide Avião Elástico',replace(replace('Se um monstro for Invocado por Invocação-Especial no seu campo (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão e, além disso, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros de VENTO. \r\nVocê só pode usar este efeito de "Velocidaroide Avião Elástico" uma vez por turno. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 monstro com a face para cima no campo; ele perde 600 de ATK até o final deste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8310162,'Dragão do Paradoxo Pernicioso',replace(replace('"Mecanismo do Paralelo Pernicioso" + 1 monstro "Pernicioso(a)" não-Regulador	\r\nQuando este card for Invocado por Invocação-Sincro, você pode selecionar 1 Monstro Sincro no Cemitério de qualquer duelista e Invocá-lo por Invocação-Especial. \r\nSó pode haver 1 "Dragão do Paradoxo Pernicioso" com a face para cima no campo. \r\nSe "Mundo Pernicioso" não estiver com a face para cima no campo, destrua este card.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8315896,'Candelado, a Besta Fantasma da Luz',replace(replace('Ganha 1000 de ATK/DEF para cada card na sua mão.\r\nVocê só pode usar cada um dos seguintes efeitos de "Candelado, a Besta Fantasma da Luz" uma vez por turno.\r\nVocê pode descartar 2 outros cards; Invoque por Invocação-Especial este card da sua mão, então você pode adicionar 1 card do seu Deck à sua mão que tenha um efeito de jogar moeda.\r\nQuando um card ou efeito é ativado que inclui um efeito que adiciona um ou mais cards do Deck à mão (Efeito Rápido): você pode negar aquele efeito.','\r',char(13)),'\n',char(10)),'Invocação Especial','Negar','Adicionar à mão?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8316565,'Contragolpe Jolt','Durante a Fase de Batalha, quando um Card de Magia/Armadilha ou efeito de monstro for ativado enquanto você controlar um monstro "Boxeador Obstinado": negue a ativação e, se isso acontecer, destrua esse card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8316661,'Miztoji Mitológico','Você pode enviar este card da sua mão para o Cemitério e, depois, escolha 1 monstro "Mitológico(a)" não-Regulador que você controla; esse monstro é considerado como um Regulador enquanto estiver com a face para cima no campo.','Escolha 1 monstro para usar como Regulador','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8321183,'Retorno da Besta Espiritual','Bana 1 monstro "Besta Espiritual" da sua mão e, depois, escolha 1 dos seus monstros "Besta Espiritual" que estejam banidos ou no seu Cemitério; Invoque-o por Invocação-Especial.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8323633,'Manto e Adaga',replace(replace('Declare 1 nome de Card de Monstro. \r\nSe seu oponente Invocar por Invocação-Normal, Invocação-Especial ou virar esse(s) monstro(s) com a face para cima, remova de jogo esse(s) monstro(s) e este card de jogo.','\r',char(13)),'\n',char(10)),'Banir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8324284,'Escudo Espiritual',replace(replace('Uma vez por batalha, quando um monstro do oponente declarar um ataque: você pode banir 1 monstro Demônio ou Zumbi do seu Cemitério; negue o ataque. \r\nUma vez por turno, quando seu oponente ativar um card ou efeito que destruiria um ou mais cards: você pode banir 1 monstro Demônio ou Zumbi do seu Cemitério; negue a ativação. \r\nUma vez por turno, durante a Fase Final, se você não controlar um monstro Demônio ou Zumbi: envie este card para o Cemitério.','\r',char(13)),'\n',char(10)),'Negar o ataque','Negar a ativação','Enviar para o Cemitério','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8327462,'Pássaro Crânio','"Takuhee" + "Templo de Crânios"','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8339504,'Substituição Xyz',replace(replace('Ofereça 1 Monstro Xyz como Tributo; Invoque por Invocação-Especial do seu Deck Adicional, 1 monstro com o mesmo Tipo, Atributo e Classe que o monstro oferecido como Tributo tinha no campo, mas de nome diferente, e, se isso acontecer, associe este card a ele como uma Matéria Xyz. \r\nDurante a Fase Final, envie-o para o Cemitério. \r\nVocê só pode ativar 1 "Substituição Xyz" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8353769,'Comedor de Ar','Um monstro que se alimenta de oxigênio, sufocando quem está por perto.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8372133,'Familiar Vermelho',replace(replace('Você pode oferecer como Tributo 1 monstro Demônio e, depois, escolha 1 Monstro Sincro Dragão de TREVAS no seu Cemitério; Invoque-o por Invocação-Especial em Posição de Defesa, mas negue seus efeitos. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 Monstro Sincro Dragão de TREVAS que você controla e declare um Nível de 1 a 8; esse monstro se torna desse Nível até o final deste turno. \r\nVocê só pode usar cada efeito de "Familiar Vermelho" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Escolha o Nível a ser alterado','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8379983,'Leoa Dourada Luzlunar',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 monstro "Luzlunar" do seu Deck à sua mão, exceto "Leoa Dourada Luzlunar" e, depois, descarte 1 card. \r\nSe um ou mais monstros "Luzlunar" forem enviados para o seu Cemitério, enquanto este card estiver na sua Zona de Monstros, mesmo durante a Etapa de Dano: você pode escolher 1 deles; adicione-o à sua mão. \r\nVocê só pode usar cada efeito de "Leoa Dourada Luzlunar" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Recuperar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8384771,'Camarartista Gomaovelha',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno, quando um ataque for declarado envolvendo um monstro que você controla e um monstro do oponente: você pode ativar este efeito; esse monstro que você controla não pode ser destruído nessa batalha.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nUma vez por turno, quando um ataque for declarado envolvendo um monstro que você controla e um monstro do oponente: você pode ativar este efeito; esse monstro que você controla não pode ser destruído nessa batalha.','\r',char(13)),'\n',char(10)),'Não será destruído naquela batalha','Não será destruído naquela batalha','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8387138,'Número 27: Couraçado Couranoide',replace(replace('2+ monstros de Nível 4	\r\nNo final da Fase de Batalha, se este card destruiu um monstro do oponente em batalha: você pode Invocar por Invocação-Especial do seu Deck Adicional, 1 Monstro Xyz Máquina de Classe 10 ou mais ao usar este card com a face para cima que você controla como matéria. \r\n(Isso é considerado uma Invocação-Xyz. Transfira as matérias dele para o monstro Invocado.) \r\nVocê só pode usar este efeito de "Número 27: Couraçado Couranoide" uma vez por turno. \r\nSe este card com a face para cima no campo seria destruído em batalha ou por um efeito de card, em vez disso, você pode desassociar 1 matéria deste card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8396952,'Força Arcana I - O Mago',replace(replace('Se este card for Invocado: lance uma moeda.\r\n● Cara: Sempre que um Card de Magia for ativado, até o final desse turno, o ATK deste card se torna o dobro do seu ATK original quando esse card resolver.\r\n● Coroa: Sempre que um Card de Magia for ativado, seu oponente ganha 500 PV quando esse card resolver.','\r',char(13)),'\n',char(10)),'Jogar uma moeda','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8400623,'Dragão Maligno Ananta',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial ao banir todos os monstros Réptil que você controla e no seu Cemitério. \r\nO ATK/DEF deste card se tornam o número de monstros banidos para a sua Invocação-Especial x 600. \r\nUma vez por turno, durante sua Fase Final: escolha 1 card no campo; destrua o alvo.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8414337,'Tempestade de Pó de Gusto','Seu oponente não pode ativar cards ou efeitos quando os monstros "Gusto" que você controla declararem seus ataques neste turno.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8428836,'Ritual do Submundo de Premonição',replace(replace('Este card é usado para a Invocação-Ritual de qualquer Monstro de Ritual "Princesa da Premonição" da sua mão ou do Cemitério com a face para cima em Posição de Ataque ou com a face para baixo em Posição de Defesa. \r\nVocê também deve oferecer como Tributo monstros da sua mão ou do campo, cuja soma dos Níveis seja igual ou exceda o Nível do Monstro de Ritual que você Invocar por Invocação-Ritual. \r\nDurante a Fase de Apoio, se você controlar um Monstro de Ritual "Princesa da Premonição": você pode banir este card do seu Cemitério; Invoque por Invocação-Especial 1 monstro "Princesa da Premonição" que não seja de Ritual do seu Deck com a face para baixo em Posição de Defesa.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8437145,'Vidente do Vácuo',replace(replace('Escolha 1 monstro "Infernoide" que você controla; o alvo não é afetado pelos efeitos de card do oponente neste turno. \r\nSe um ou mais monstros "Infernoide" que você controla seriam destruídos por um efeito de card, você pode banir este card do seu Cemitério em vez de destruir 1 desses monstros.','\r',char(13)),'\n',char(10)),'Banir "Vidente do Vácuo" do seu Cemitério em vez disso?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8445808,'Donzela Apaixonada',replace(replace('Monstros que seu oponente controla que podem atacar devem atacar este card. \r\nNão pode ser destruído em batalha. \r\nNo final da Etapa de Dano, se este card batalhou um monstro do oponente: você pode ativar 1 desses efeitos;\r\n● Coloque 1 Marcador de Donzela em 1 monstro com a face para cima que seu oponente controla.\r\n● Tome o controle de 1 monstro que seu oponente controla com um Marcador de Donzela.','\r',char(13)),'\n',char(10)),'','','Ativar','Colocar um marcador','Tome o controle','','','','','','','','','','','');
INSERT INTO texts VALUES(8454126,'Condutora de Nephthys',replace(replace('Você pode Invocar este card por Invocação-Ritual com "Renascimento de Nephthys". \r\nSe este card for Invocado por Invocação-Ritual: você pode Invocar por Invocação-Especial 1 Monstro de Ritual "Nephthys" da sua mão ou do Deck, exceto "Condutora de Nephthys" (isso é considerado uma Invocação-Ritual). \r\nSe este card for oferecido como Tributo ou destruído por um efeito de card "Nephthys": você pode ativar este efeito; durante a próxima Fase de Apoio, destrua até 3 cards "Nephthys", exceto Monstros de Ritual, 1 de cada da sua mão, do Deck e do campo. \r\nVocê só pode usar cada efeito de "Condutora de Nephthys" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8463720,'D/D/D Beowulf, o Rei Matador de Dragões',replace(replace('1 monstro "D/D/D" + 1 Monstro "D/D"	\r\nSe um monstro "D/D" que você controla atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente. \r\nUma vez por turno, durante sua Fase de Apoio: você pode destruir todos os cards nas Zonas de Magia & Armadilha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8471389,'Lobo Giga-Tech','Um lobo de ferro com presas afiadas como lâminas, capazes de penetrar qualquer armadura.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8483333,'Mantícora Mosaico',replace(replace('Durante a Fase de Apoio do seu próximo turno depois que você Invocar este card por Invocação-Tributo com a face para cima no campo: Invoque por Invocação-Especial, do Cemitério, tantos monstros quanto possível que foram usados para essa Invocação-Tributo. \r\nEles não podem declarar um ataque e seus efeitos são negados.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8487449,'Bobo da Corte Confeitado',replace(replace('Você só pode controlar 1 "Bobo da Corte Confeitado". \r\nVocê pode Invocar este card por Invocação-Especial (da sua mão) em Posição de Ataque. \r\nSe Invocado desta forma, durante a próxima Fase Final do seu oponente: escolha 1 monstro com a face para cima que seu oponente controla; devolva tanto o alvo como este card com a face para cima para a mão.','\r',char(13)),'\n',char(10)),'Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8491308,'Força Celeste - Ás - Hayate',replace(replace('1 monstro "Força Celeste - Ás" que não seja de VENTO	\r\nVocê só pode Invocar um ou mais "Força Celeste - Ás - Hayate" por Invocação-Especial uma vez por turno. \r\nPode atacar diretamente. \r\nDepois do cálculo de dano, se este card batalhou: você pode enviar 1 card "Força Celeste" do seu Deck para o Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8491309,'Força Celeste - Ás - Hayate',replace(replace('1 monstro "Força Celeste - Ás" que não seja de VENTO	\r\nVocê só pode Invocar um ou mais "Força Celeste - Ás - Hayate" por Invocação-Especial uma vez por turno. \r\nPode atacar diretamente. \r\nDepois do cálculo de dano, se este card batalhou: você pode enviar 1 card "Força Celeste" do seu Deck para o Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8491961,'Lirilusc - Recital Estorninho',replace(replace('2+ monstros de Nível 1	\r\nSe este card for Invocado por Invocação-Xyz: você pode escolher 1 monstro com a face para cima no campo; ele ganha 300 de ATK/DEF para cada matéria associada a este card. \r\nUma vez por turno: você pode desassociar 1 matéria deste card; adicione 1 monstro Besta Alada de Nível 1 do seu Deck à sua mão. \r\nTodo dano de batalha que você sofrer de batalhas envolvendo este card Invocado por Invocação-Xyz também é causado ao seu oponente.','\r',char(13)),'\n',char(10)),'Aumentar ATK','Procurar no Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8495780,'Artesão do Mar Profundo',replace(replace('Se este card for adicionado do Deck ou Cemitério à sua mão pelo efeito de um monstro de ÁGUA: você pode revelar este card; olhe a mão do seu oponente. \r\nSe este card for Invocado por Invocação-Especial: você pode enviar o card do topo do seu Deck para o Cemitério e, depois, escolha 1 monstro de ÁGUA de Nível 4 ou menos no seu Cemitério, exceto "Artesão do Mar Profundo"; Invoque-o por Invocação-Especial, mas negue seus efeitos. \r\nVocê só pode usar cada efeito de "Artesão do Mar Profundo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8505920,'Grupo Guardião do Portão',replace(replace('"Sanga do Trovão" + "Kazejin" + "Suijin"	\r\nDeve ser Invocado por Invocação-Especial (do seu Deck Adicional) ao banir os cards acima da sua mão, do campo e/ou do Cemitério. \r\nQuando seu oponente ativar um card ou efeito que escolha um ou mais cards que você controla como alvo (Efeito Rápido): você pode negar esse efeito e, se isso acontecer, destrua esse card. \r\nVocê só pode usar este efeito de "Grupo Guardião do Portão" três vezes por turno. \r\nSe este card com a face para cima Invocado por Invocação-Especial sob o controle do seu dono deixar o campo devido a um card do oponente: você pode Invocar por Invocação-Especial 1 monstro "Guardião do Portão" de Nível 11 ou menos do seu Deck ou Deck Adicional, ignorando suas condições de Invocação.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8508055,'Chu-Suke, O Lutador Rato','Um rato impetuoso, viajando o mundo para tornar-se o lutador mais forte no mundo dos ratos. Tem cuidado para não lhe tocares ou queimas-te.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8512558,'Onomatopeia Utópica',replace(replace('(Este card deve ser sempre considerado como um card "Zubaba", "Gagaga", "Gogogo" e "Dododo".)	\r\nDurante sua Fase Principal: você pode Invocar por Invocação-Especial um ou mais monstros até 1 de cada dentre "Zubaba", "Gagaga", "Gogogo" e/ou "Dododo" da sua mão em Posição de Defesa, exceto "Onomatopeia Utópica", e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto Monstros Xyz. \r\nVocê só pode usar este efeito de "Onomatopeia Utópica" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8522996,'O Primeiro Monarca',replace(replace('Invoque este card por Invocação-Especial como um Monstro de Efeito (Demônio/TREVAS/Nível 6/ATK 1000/DEF 2400).	\r\n(Este card também é considerado uma Armadilha.) \r\nSe Invocado desta forma: você pode descartar 1 card e, depois, declare 1 Atributo; este card se torna desse Atributo e pode ser considerado como 2 Tributos para a Invocação-Tributo de um monstro com o mesmo Atributo que este card. \r\nSe este card foi Invocado desta forma, você não pode Invocar monstros por Invocação-Especial, exceto monstros com o Atributo deste card.','\r',char(13)),'\n',char(10)),'Alterar o Atributo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8529136,'Punho de Restolhos',replace(replace('Escolha 1 "Guerreiro Sucata" que você controla; se ele batalhar um monstro do oponente neste turno enquanto você o controlar, aplique esses efeitos.\r\n● Seu oponente não pode ativar cards ou efeitos até o final da Etapa de Dano.\r\n● Se ele atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente.\r\n● Dobre qualquer dano de batalha que seu oponente sofrer.\r\n● Ele não pode ser destruído em batalha.\r\n● No final da Etapa de Dano, destrua o monstro do oponente que o batalhou.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8540986,'Veidos, o Dragão da Escuridão Sem Fim',replace(replace('"Veidos, o Dragão de Erupção da Extinção" + 2+ monstros Piro de Nível 9 ou menos	\r\nNão pode ser destruído por efeitos de card e, além disso, seu oponente não pode escolhê-lo como alvo de efeitos de monstro. \r\nSe este card for Invocado por Invocação-Fusão: você pode destruir todas as Magias e Armadilhas que seu oponente controla. \r\nQuando seu oponente ativar um card ou efeito no campo (Efeito Rápido): você pode enviar 1 card "Cinzento(a)" com a face para cima que você controla para o Cemitério; destrua esse card. \r\nVocê só pode usar este efeito de "Veidos, o Dragão da Escuridão Sem Fim" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Destruir um Card de Magia/Armadilha','Destrua o card que ativou seu efeito','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8559524,'Comandar Ressonador',replace(replace('Descarte 1 monstro "Ressonador"; adicione 1 monstro Demônio de Nível 4 ou menos do seu Deck à sua mão. \r\nVocê só pode ativar 1 "Comandar Ressonador" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8559793,'Ataqueraptor - Ninho',replace(replace('Se você controlar 2 ou mais monstros "Ataqueraptor": você pode adicionar 1 monstro "Ataqueraptor" do seu Deck ou Cemitério à sua mão. \r\nVocê só pode usar este efeito de "Ataqueraptor - Ninho" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8561192,'Leo, o Protetor da Árvore Sagrada',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nSeu oponente não pode escolher este card como alvo de efeitos de card, exceto durante sua Fase Principal 2.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8567955,'Senhor Balanceamento',replace(replace('Uma vez por turno: você pode pagar 1000 PV; durante sua Fase Principal deste turno, você pode Invocar por Invocação-Normal 1 monstro Ciberso, em adição à sua Invocação-Normal/Baixar padrão. \r\n(Você só pode se aproveitar deste efeito uma vez por turno.) \r\nSe este card for banido: você pode Invocar por Invocação-Especial 1 monstro de Nível 4 ou menos da sua mão. \r\nVocê só pode usar este efeito de "Senhor Balanceamento" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Invocar pelo efeito de "Senhor Balanceamento"','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8571567,'Asanegra - Shamal, a Tempestade de Areia',replace(replace('Você pode enviar este card da sua mão ou do campo para o Cemitério; coloque 1 "Redemoinho da Pena Negra" do seu Deck na sua Zona de Magias & Armadilhas com a face para cima. \r\nSe um ou mais Monstros Sincro "Asanegra" ou "Dragão de Asas Negras" for Invocado por Invocação-Especial no seu campo, enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode banir este card e, depois, escolha 1 monstro "Asanegra" no seu Cemitério; adicione-o à sua mão e, depois, sofra 700 de dano. \r\nVocê só pode usar cada efeito de "Asanegra - Shamal, a Tempestade de Areia" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8576764,'Reptilfinho Glutão Greethys',replace(replace('Você pode escolher 1 monstro Peixe, Serpente Marinha ou Aqua no seu Cemitério com um Nível igual ou menor que o número de cards na mão do seu oponente; Invoque-o por Invocação-Especial, mas ele não pode ativar seus efeitos neste turno. \r\nVocê só pode usar este efeito de "Reptilfinho Glutão Greethys" uma vez por turno. \r\nSe este card for enviado para o Cemitério como Matéria Sincro: você pode fazer com que o Monstro Sincro que usou este card como matéria ganhe 200 de ATK/DEF para cada card atualmente na mão do seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8581705,'Rainha Infernal Arquidemônio',replace(replace('Uma vez por turno, durante sua Fase de Apoio, você deve pagar 500 PV (isso não é opcional), ou este card é destruído. \r\nQuando estiver resolvendo um efeito de card do oponente que escolha este card como alvo, lance um dado de seis faces e negue esse efeito se o resultado for um 2 ou 5 e, se isso acontecer, destrua esse card. \r\nUma vez por turno, durante a Fase de Apoio: escolha 1 monstro "Arquidemônio" no campo; ele ganha 1000 de ATK até o final deste turno.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8593259,'Guardião Clay, o HERÓI do Elemento',replace(replace('1 monstro "HERÓI do Elemento" + 1 monstro Guerreiro	\r\nOutros monstros "HERÓI do Elemento" que você controla não podem ser destruídos por batalha ou efeitos.\r\nSe este card for Invocado por Invocação-Especial: você pode Invocar por Invocação-Especial 1 monstro "HERÓI do Elemento" do seu Deck, então se seu oponente controla um card, você pode causar 400 de dano nele para cada, você também não pode Invocar por Invocação-Especial do seu Deck Adicional pelo resto do turno, exceto monstros "HERÓI". \r\nVocê só pode usar este efeito de "Guardião Clay, o HERÓI do Elemento" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Causar dano?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8594079,'Braquis Jurrac','Enquanto outro monstro "Jurrac" com a face para cima estiver no campo, este card não pode ser destruído em batalha.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8602351,'Equidna Reptiliana',replace(replace('2 monstros, incluindo um monstro Réptil	\r\nSe este card for Invocado por Invocação-Link: você pode escolher 1 monstro com a face para cima que seu oponente controla; mude o ATK dele para 0. \r\nDurante sua Fase Principal, se seu oponente controlar um ou mais monstros com ATK 0: você pode adicionar monstros Réptil com nomes diferentes do seu Deck à sua mão, até o número de monstros que seu oponente controla com ATK 0 e, além disso, você não pode Invocar monstros por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto monstros Réptil. \r\nVocê só pode usar cada efeito de "Equidna Reptiliana" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8608979,'Super Time Força Camarada Unida!',replace(replace('Escolha 1 monstro com a face para cima no campo; Invoque por Invocação-Especial 1 monstro da sua mão ou do Cemitério, com o mesmo Tipo original que o desse monstro, mas com um nome original diferente. \r\nSe este card na Zona de Magias & Armadilhas do seu dono for destruído por um efeito de card do oponente: você pode Baixar 1 "Super Time Força Camarada Unida!" diretamente do seu Deck na sua Zona de Magias & Armadilhas.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8611007,'Dragun Lavalval',replace(replace('1 Regulador + 1+ monstros de FOGO não-Reguladores	\r\nUma vez por turno, durante sua Fase Principal: você pode adicionar 1 monstro "Laval" do seu Deck à sua mão e, depois, envie 1 monstro "Laval" da sua mão para o Cemitério.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8617563,'Ataqueraptor - Corajoso Strix',replace(replace('2 monstros de Nível 5	\r\nUm Monstro Xyz "Ataqueraptor" que tenha este card como matéria ganha este efeito.\r\n● Este card ganha ATK igual à sua Classe x 100.	\r\nVocê só pode usar 1 dos seguintes efeitos de "Ataqueraptor - Corajoso Strix" por turno e apenas uma vez por turno. \r\nVocê pode desassociar 1 matéria deste card; Baixe 1 Magia/Armadilha "Ataqueraptor" do seu Deck. \r\nSe este card tiver um monstro Besta Alada como matéria: você pode desassociar 1 matéria deste card; adicione 1 Magia "Magia de Aumento de Classe" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Baixar','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8628798,'Dinamite D.D.','Inflija 300 pontos de dano aos Life Points do seu adversário por cada card que o seu adversário removeu de jogo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8632967,'Evo-Carma','Quando um ou mais monstros forem Invocados por Invocação-Especial pelo efeito de um monstro "Evoltil" que você controla, seu oponente não pode ativar cards ou efeitos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8633261,'Combustão Interna de Ryzeal',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) ao enviar 1 card da sua mão ou do campo para o Cemitério. \r\nSe Invocado desta forma, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto Monstros Xyz de Classe 4. \r\nVocê só pode Invocar "Combustão Interna de Ryzeal" por Invocação-Especial uma vez por turno desta forma. \r\nSe este card for Invocado por Invocação-Normal: você pode Invocar por Invocação-Especial 1 monstro "Ryzeal" do seu Deck, exceto "Combustão Interna de Ryzeal". \r\nVocê só pode usar este efeito de "Combustão Interna de Ryzeal" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Invocar por Invocação Especial do Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8634636,'Gato Preto com Cauda Branca','VIRE: Devolva 2 Cards de Monstro no Campo do seu adversário e 1 Card de Monstro no seu Campo para a mão dos seus donos.','Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8643186,'D/D Recrutas',replace(replace('Se seu oponente controlar mais monstros que você: escolha qualquer número de monstros "D/D" e/ou cards "Pacto Obscuro" no seu Cemitério até essa diferença; adicione esses cards à sua mão. \r\nVocê só pode ativar 1 "D/D Recrutas" por turno.','\r',char(13)),'\n',char(10)),'Recuperar cards','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8649148,'Varredor das Profundezas','Você pode oferecer este card como Tributo e, depois, escolher 1 Card de Magia/Armadilha no campo; destrua o alvo.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8653757,'Tempo Estático de Fóton',replace(replace('Pegue 1 Magia/Armadilha Contínua "Fóton" ou "Galáxia" do seu Deck e adicione-a à sua mão ou coloque-a com a face para cima no seu campo. \r\nSe este card Baixado sob o controle do seu dono for destruído por um efeito de card do seu oponente durante o turno do seu oponente e você controlar "Dragão de Fóton de Olhos das Galáxias" ou um Monstro Xyz que o tenha como matéria: você pode ativar este efeito; essa se torna a Fase Final deste turno.','\r',char(13)),'\n',char(10)),'','Colocar com a face para cima','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8660395,'Ninaruru, a Deusa de Vidro Magistus',replace(replace('2 monstros Mago de Nível 4	\r\nEnquanto este card for um Card de Equipamento, o monstro equipado pode realizar até 2 ataques contra monstros durante cada Fase de Batalha. \r\nVocê só pode usar cada um dos seguintes efeitos de "Ninaruru, a Deusa de Vidro Magistus" uma vez por turno. \r\nVocê pode desassociar 1 matéria deste card e, depois, escolha 1 monstro Mago de Nível 4 ou mais no seu Cemitério; adicione-o à sua mão. \r\nEnquanto este card estiver equipado a um monstro: você pode escolher 1 card "Magistus" na sua Zona de Magias & Armadilhas e 1 Magia/Armadilha que seu oponente controla; destrua-os.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8662794,'Rompe-código Dia Zero',replace(replace('Todos os Monstros Link que estiverem apontando para este card perdem 1000 de ATK, exceto Monstros Link "Rompe-código". \r\nSe um ou mais Monstros Link "Rompe-código" no campo forem destruídos em batalha ou por um efeito de card, enquanto este card estiver no campo: destrua este card. \r\nSe este card for destruído em batalha ou por um efeito de card: você pode adicionar 1 "Rompe-código Dia Zero" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8687195,'Duende do Sonho','Quando atacado por um monstro do oponente, selecione 1 outro dos seus Cards de Monstro e declare-o como alvo do ataque e, depois, calcule o dano.','Substituição de batalha','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8690387,'Servente Terrestre Geo Gremlin',replace(replace('1 Regulador de TREVAS + 1+ monstros não-Reguladores	\r\nDurante a Fase Principal (Efeito Rápido): você pode escolher 1 monstro com a face para cima que seu oponente controla; seu oponente seleciona 1 desses efeitos para que você aplique.\r\n● Destrua esse monstro.\r\n● Ganhe PV igual ao ATK desse monstro.	\r\nDurante a Fase de Batalha (Efeito Rápido): você pode Invocar por Invocação-Fusão 1 Monstro de Fusão "Terrestre" do seu Deck Adicional, ao banir suas matérias da sua mão, do campo e/ou do Cemitério. \r\nVocê só pode usar cada efeito de "Servente Terrestre Geo Gremlin" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Destruir aquele monstro','Seu oponente ganha PV igual ao ATK daquele monstro','','','','','','','','','','','','');
INSERT INTO texts VALUES(8692301,'Cavaleiro-Gema Zircônia','1 monstro "Cavaleiro-Gema" + 1 monstro Rocha','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8696773,'Hidra da Chama Nebulosa',replace(replace('Seu oponente não pode escolher este card como alvo de efeitos de card. \r\nVocê não pode Invocar monstros por Invocação-Especial, exceto monstros de FOGO. \r\nUm Monstro Xyz que foi Invocado usando este card como uma Matéria Xyz ganha este efeito.\r\n● Quando Invocado por Invocação-Xyz: você pode escolher 1 monstro "Chama Nebulosa" no seu Cemitério; associe o alvo a este card como uma Matéria Xyz.','\r',char(13)),'\n',char(10)),'Associar Matéria','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8698851,'Resposta-D','Quando um monstro "HERÓI do Destino" com a face para cima que você controla for escolhido como alvo de um ataque: destrua o monstro atacante.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8700633,'Agressiva Besta Destemida',replace(replace('Durante a Fase Principal, se seu oponente Invocou 3 ou mais monstros por Invocação-Especial neste turno (Efeito Rápido): você pode Invocar este card por Invocação-Especial da sua mão ou do Cemitério. \r\nVocê só pode usar este efeito de "Agressiva Besta Destemida" uma vez por turno. \r\nEnquanto você não controlar nenhum outro monstro, este card em Posição de Ataque não pode ser destruído em batalha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8706701,'Espelho Vermelho',replace(replace('Quando um monstro do oponente declarar um ataque: você pode enviar este card da sua mão para o Cemitério e, depois, escolher 1 monstro de FOGO do Tipo Demônio no seu Cemitério, exceto "Espelho Vermelho"; adicione-o à sua mão. \r\nSe você Invocar por Invocação-Sincro enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano ou no turno em que este card foi enviado para o Cemitério): você pode adicionar este card à sua mão. \r\nVocê só pode usar cada efeito de "Espelho Vermelho" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8715625,'Bokoichi, o Vagão Assustador','Um vagão de mercadorias que é exclusivamente para Dekoichi. Pode transportar qualquer coisa, mas a maioria da carga chega partida.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8719957,'Abis-Escamas do Kraken',replace(replace('Só pode ser equipado a um monstro "Sirena". \r\nEle ganha 400 de ATK. \r\nQuando um efeito de monstro que foi ativado no campo do seu oponente resolver, negue esse efeito e, depois, envie este card para o Cemitério.','\r',char(13)),'\n',char(10)),'Negar o efeito','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8728498,'Donner, a Adaga de Peluguel',replace(replace('2 monstros com Tipos diferentes	\r\nVocê pode escolher 1 monstro "de Peluguel" que você controla e 1 monstro que seu oponente controla; destrua-os. \r\nVocê pode oferecer 1 monstro como Tributo; Invoque por Invocação-Especial 1 monstro "de Peluguel" da sua mão ou do Cemitério com um nome original diferente que o do monstro oferecido como Tributo e, depois, se você ofereceu como Tributo um Monstro Link para ativar este efeito, você pode Invocar por Invocação-Especial mais 1 desses monstros. \r\nVocê só pode usar 1 efeito de "Donner, a Adaga de Peluguel" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Destruir ambos os monstros','Invocação Especial','Escolher outro monstro para Invocar por Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8730435,'Escudo de Batalha Arquidemônio da Besta Gladiadora',replace(replace('Só pode ser equipado a um monstro "Besta Gladiadora". \r\nSe o monstro equipado seria destruído, em vez disso, destrua este card. \r\nQuando este card for enviado para o Cemitério porque o monstro equipado que você controla foi embaralhado no seu Deck: devolva este card para a sua mão.','\r',char(13)),'\n',char(10)),'Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8736823,'Hime do Mundo Virtual - Nyannyan',replace(replace('Se um ou mais monstros de Nível 3 forem Invocados por Invocação-Normal ou Especial no seu campo enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial como um Regulador, mas bana-o quando ele deixar o campo e, além disso, pelo resto deste turno, você só pode Invocar por Invocação-Especial monstros de Nível/Classe 3 ou mais. \r\nSe este card for banido: você pode escolher 1 dos seus outros cards banidos; embaralhe-o no Deck. \r\nVocê só pode usar cada efeito de "Hime do Mundo Virtual - Nyannyan" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8763963,'Beelzeus dos Dragões Diabólicos',replace(replace('1 Regulador de TREVAS + 2+ monstros não-Reguladores	\r\nNão pode ser destruído em batalha ou por efeitos de card. \r\nOutros monstros que você controla não podem atacar. \r\nUma vez por turno: você pode escolher 1 monstro que seu oponente controla; qualquer dano de batalha que seu oponente sofrer de ataques envolvendo este card neste turno é diminuído pela metade e, além disso, mude o ATK desse monstro do oponente para 0 e, se isso acontecer, ganhe PV igual ao ATK original dele.','\r',char(13)),'\n',char(10)),'Absorver ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8775395,'Olho Maligno Liberado',replace(replace('Envie 1 monstro "Olho Maligno" e 1 Magia/Armadilha "Olho Maligno" do seu Deck para o Cemitério; adicione 1 Magia de Equipamento "Olho Maligno" do seu Deck à sua mão, mas pelo resto deste turno, sempre que você ativar um card ou efeito que não seja "Olho Maligno", você perde 500 PV. \r\nSe você Invocar por Invocação-Link um Monstro Link "Olho Maligno": você pode banir este card do seu Cemitério; equipe 1 Magia de Equipamento "Olho Maligno" do seu Cemitério a 1 Monstro Link "Olho Maligno" que você controla. \r\nVocê só pode usar cada efeito de "Olho Maligno Liberado" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8778267,'Fusão de Penetração',replace(replace('Se um ou mais monstros foram destruídos em batalha neste turno: Invoque por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional, usando monstros da sua mão ou do campo e, se isso acontecer, ele ganha este efeito.\r\n● (Efeito Rápido): você pode oferecer este card como Tributo e, depois, escolha 1 monstro com a face para cima que você controla; ele ganha 500 de ATK.	\r\nVocê só pode ativar 1 "Fusão de Penetração" por turno.','\r',char(13)),'\n',char(10)),'Ativar','O efeito de "Fusão de Penetração" está sendo aplicado.','Aumentar ATK (Fusão de Penetração)','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8783685,'Ampulheta da Vida','Esta criatura concede poder em vez de encurtar a vida.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8785161,'Ataqueraptor - Abutre Selvagem','Durante sua Fase Principal, se este card foi Invocado por Invocação-Normal ou Especial neste turno: você pode oferecer este card como Tributo; Invoque por Invocação-Especial 2 monstros "Ataqueraptor" da sua mão e/ou Cemitério cuja soma dos Níveis seja igual a 6.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8794055,'As Profundezas Mais Distantes e Mais Profundas',replace(replace('Enquanto você controlar um Monstro Sincro Peixe, este card não pode ser destruído, ou banido, por efeitos de card. \r\nVocê só pode usar cada um dos seguintes efeitos de "As Profundezas Mais Distantes e Mais Profundas" uma vez por turno. \r\nVocê pode banir 1 monstro Peixe da sua mão ou do Cemitério; adicione 1 monstro "Ghoti" do seu Deck à sua mão. \r\nSe um ou mais monstros Peixe forem Invocados por Invocação-Normal ou Especial no seu campo, enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode escolher 1 monstro Peixe que você controla; bana-o e, se isso acontecer, adicione este card à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8794435,'Maju Garzett','O ATK deste card torna-se igual ao combinado do ATK original dos 2 monstros que foram oferecidos como Tributo para a Invocação-Tributo deste card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8802510,'PSÍ-Armação Senhor Lambda',replace(replace('2 monstros, exceto Fichas	\r\nVocê pode ativar os efeitos de monstros "PSÍ-Armação Equipamento" na sua mão mesmo enquanto controlar um ou mais monstros. \r\nSe um monstro Psíquico com a face para cima que você controla for banido com a face para cima enquanto você controlar este monstro (exceto durante a Etapa de Dano): você pode ativar este efeito; durante a Fase Final deste turno, adicione 1 card "PSÍ-Armação" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "PSÍ-Armação Senhor Lambda" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8805651,'Megálito Phuloch',replace(replace('Você pode Invocar este card por Invocação-Ritual com um card "Megálito". \r\nVocê não pode ativar os seguintes efeitos de "Megálito Phuloch" na mesma Corrente. \r\nSe este card for Invocado por Invocação-Ritual: você pode adicionar 1 card "Megálito" do seu Cemitério à sua mão. \r\nDurante a Fase Principal (Efeito Rápido): você pode ativar este efeito; Invoque por Invocação-Ritual 1 Monstro de Ritual "Megálito" do seu Cemitério, exceto "Megálito Phuloch", ao oferecer como Tributo monstros da sua mão ou do campo, incluindo este card no seu campo, cuja soma dos Níveis seja igual ou exceda seu Nível. \r\nVocê só pode usar este efeito de "Megálito Phuloch" uma vez por turno.','\r',char(13)),'\n',char(10)),'Recuperar','Invocação Ritual','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8806072,'Lutador de Combo','Se uma Corrente (de Elo 2 ou mais) foi iniciada na sua Fase Principal 1, este card pode atacar duas vezes durante a Fase de Batalha neste turno.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8809344,'Entidade Exterior Nyarla',replace(replace('2 monstros de Nível 4	\r\nQuando este card for Invocado por Invocação-Xyz: você pode descartar qualquer número de cards; aumente a Classe deste card pelo número de cards descartados. \r\nUma vez por turno, enquanto este card tiver Matérias Xyz: você pode escolher 1 monstro no seu Cemitério; desassocie todas as matérias deste card e, se isso acontecer, associe o alvo a este card como matéria. \r\nQuando um monstro for associado por este efeito, o Tipo e Atributo deste card se tornam o mesmo Tipo e Atributo originais desse monstro.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8814959,'Hordeum Maligno Mandrágora','Se seu oponente controlar mais monstros que você, você pode Invocar este card por Invocação-Especial (da sua mão).','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8820526,'Camarartista Quebra-Barro',replace(replace('Se este card Invocado por Invocação-Tributo batalhar um monstro do oponente, durante o cálculo de dano: você pode fazer com que, até o final deste turno, esse monstro do oponente perca 500 de ATK para cada Monstro Pêndulo com a face para cima atualmente no seu Deck Adicional. \r\nQuando você Invocar 2 ou mais monstros por Invocação-Pêndulo ao mesmo tempo enquanto este card estiver no seu Cemitério: você pode adicionar este card do Cemitério à sua mão. \r\nVocê só pode usar cada efeito de "Camarartista Quebra-Barro" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8822710,'Portal Cósmico, Aliado da Justiça','Se seu oponente controlar 2 ou mais monstros, incluindo um monstro de LUZ, você pode Invocar este card por Invocação-Especial (da sua mão).','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8836329,'Dragão Furioso da Tempestade - Beaufort IX',replace(replace('Você pode Invocar este card por Invocação-Ritual com "Sopro da Aclamação". \r\nQuando um monstro do oponente declarar um ataque direto: você pode descartar este card; negue o ataque e, se isso acontecer, negue os efeitos desse monstro. \r\n(Efeito Rápido): você pode escolher 1 monstro com a face para cima que seu oponente controla; devolva tanto esse monstro quanto este card para a mão. \r\nVocê só pode usar cada efeito de "Dragão Furioso da Tempestade - Beaufort IX" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8837932,'Mandala Cúbico',replace(replace('Se você controlar um monstro "Cúbico(a)": ative este card ao escolher qualquer número de monstros que estiverem no Cemitério do seu oponente porque foram destruídos e enviados para lá neste turno; Invoque-os por Invocação-Especial no campo do seu oponente, mas o ATK deles se torna 0 e eles têm 1 Marcador Cúbico sobre eles. \r\n(Monstros com um Marcador Cúbico não podem atacar e, além disso, negue seus efeitos.) \r\nEnquanto seu oponente controlar qualquer um dos monstros Invocados por este efeito, negue quaisquer efeitos de monstro ativados por seu oponente. \r\nQuando o último desses monstros deixar o campo, destrua este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8841431,'Centur-Ião Primera Primus',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nNão pode ser destruído em batalha, a não ser que tenha sido Invocado por Invocação-Especial do Deck Adicional. \r\nVocê só pode usar cada um dos seguintes efeitos de "Centur-Ião Primera Primus" uma vez por turno. \r\nSe este card for Invocado por Invocação-Sincro: você pode adicionar 1 card "Emblemado" do seu Deck ou Cemitério à sua mão e, depois, você pode destruir 2 cards (1 em cada campo). \r\nSe um ou mais cards "Centur-Ião" com a face para cima que você controla deixarem o campo por um efeito de card do oponente, enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Invocação Especial','Destruir o card?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8842266,'Poção do Homem Velho',replace(replace('Ative 1 desses efeitos;\r\n● Ganhe 1200 PV.\r\n● Cause 800 de dano ao seu oponente.','\r',char(13)),'\n',char(10)),'Ganhe 1200 PV','Cause 800 de dano ao seu oponente','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8843569,'Dádiva da Asa',replace(replace('Se todos os monstros que você controla forem monstros Besta Alada e você controlar pelo menos 2 monstros com nomes originais diferentes: pague 600 PV; compre 2 cards. \r\nVocê só pode ativar 1 "Dádiva da Asa" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8852158,'Wendikuruhu Reesombraneco',replace(replace('1 monstro "Sombraneco" + 1 monstro de VENTO	\r\nPrimeiro deve ser Invocado por Invocação-Fusão. \r\n(Efeito Rápido): você pode colocar qualquer número de monstros que estiverem com a face para baixo no campo, com a face para cima em Posição de Defesa e, depois, você pode contar o número de monstros de Virar entre eles e colocar até esse número de monstros com a face para cima no campo (exceto aqueles monstros que foram virados), com a face para baixo em Posição de Defesa. \r\nVocê só pode usar este efeito de "Wendikuruhu Reesombraneco" uma vez por turno. \r\nSe este card for enviado para o Cemitério: você pode escolher 1 card "Sombraneco" no seu Cemitério; adicione-o à sua mão.','\r',char(13)),'\n',char(10)),'Mudar para Posição de Defesa com a face para cima','Adicionar à mão','Mudar um monstro para Posição de Defesa com a face para baixo?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8868767,'Dadieta',replace(replace('Lance um dado de seis faces. \r\nAplique este efeito, dependendo de quem é o turno.\r\n● Durante o seu turno: bana cards do seu Cemitério igual ao resultado.	\r\nDepois, se o resultado foi 1, envie 6 cards do topo do seu Deck para o Cemitério.\r\n● Durante o turno do seu oponente: envie para o Cemitério cards do topo do seu Deck igual ao resultado.	\r\nDepois, se o resultado foi 6, bana 1 card do seu Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8873112,'Artefato Chakram',replace(replace('Você pode Baixar este card da sua mão para a sua Zona de Magias & Armadilhas como um Card de Magia. \r\nDurante o turno do seu oponente, se este card Baixado na Zona de Magias & Armadilhas for destruído e enviado para o seu Cemitério: Invoque-o por Invocação-Especial. \r\nDurante o turno de qualquer duelista, quando um card ou efeito que destruiria um ou mais Cards de Magia/Armadilha que você controla for ativado, enquanto este card estiver na sua mão: você pode devolver 1 Card Baixado de Magia/Armadilha que você controla para a mão; Invoque este card por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Invocação Especial','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8875971,'Patrulheiro Serafim Estelar','Quando este card for Invocado por Invocação-Normal: você pode Invocar por Invocação-Especial 1 monstro "Serafim Estelar" da sua mão.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8903700,'Djinn, o Libertador de Rituais',replace(replace('Quando você Invocar um monstro por Invocação-Ritual, você pode banir este card do seu Cemitério como 1 dos monstros necessários para a Invocação-Ritual. \r\nSe um duelista Invocar por Invocação-Ritual usando este card, o outro duelista não pode Invocar por Invocação-Especial enquanto esse monstro Invocado por Invocação-Ritual estiver com a face para cima no campo.','\r',char(13)),'\n',char(10)),'O efeito de "Djinn, o Libertador de Rituais" está sendo aplicado.','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8910240,'Papillon Rosa',replace(replace('Durante sua Fase Principal, você pode Invocar por Invocação-Tributo 1 monstro de Nível 7 ou mais em Posição de Ataque em adição à sua Invocação-Normal/Baixar (padrão). \r\n(Você só pode se aproveitar deste efeito uma vez por turno.) \r\nEnquanto você controlar outro monstro Inseto, este card pode atacar diretamente.','\r',char(13)),'\n',char(10)),'Invocação por Tributo pelo efeito de "Papillon Rosa"','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8910971,'Senhor Gaia, o Cavaleiro Impetuoso',replace(replace('Se seu oponente controlar um monstro e você não controlar nenhum monstro, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nUma vez por turno, se um ou mais monstros com ATK maior que este card forem Invocados por Invocação-Especial no lado do campo do seu oponente (exceto durante a Etapa de Dano): você pode fazer com que este card ganhe 700 de ATK até o final deste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8915275,'Caixa Maligna',replace(replace('Este card é considerado um monstro Toon enquanto "Mundo Toon" está no campo.\r\nSe você controla "Mundo Toon": você pode Invocar por Invocação-Especial este card da sua mão, então você pode adicionar à sua mão, ou Baixar, 1 Armadilha "Toon" do seu Deck. \r\nVocê só pode usar este efeito de "Caixa Maligna" uma vez por turno.\r\nUma vez por turno (Efeito Rápido): você pode escolher 1 card em qualquer Cemitério; coloque-o no fundo do Deck.','\r',char(13)),'\n',char(10)),'Invocação Especial','Recuperar do Cemitério','Escolher um Card de Armadilha?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8944575,'O Drdek','Um olho bípede com garras letais que raramente erram seus alvos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8949584,'Um Herói Vive','Se você não controlar nenhum monstro com a face para cima: pague metade dos seus PV; Invoque por Invocação-Especial 1 monstro "HERÓI do Elemento" de Nível 4 ou menos do seu Deck.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8951260,'Respeitar Jogada','Durante seus respectivos turnos, cada duelista deve mostrar sua mão ao seu oponente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8953369,'Sobreposição Kashtira',replace(replace('Escolha 1 monstro no campo; bana 1 monstro com 1500 de ATK/2100 de DEF da sua mão, do seu Cemitério ou com a face para cima em qualquer campo e, se isso acontecer, o monstro alvo ganha 1500 de ATK. \r\nSe este card for banido e você controlar um monstro "Kashtira": você pode escolher 1 Monstro de Efeito que seu oponente controla; negue seus efeitos até o final deste turno. \r\nVocê só pode usar cada efeito de "Sobreposição Kashtira" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8955148,'Ritual da Condenação Tornassol',replace(replace('Este card é usado para a Invocação-Ritual de "Espadachim da Condenação Tornassol". \r\nVocê também deve oferecer como Tributo monstros da sua mão ou do campo, cuja soma dos Níveis seja igual a 8 ou mais. \r\nSe este card estiver no Cemitério: você pode escolher 1 "Espadachim da Condenação Tornassol" no seu Cemitério; embaralhe no Deck tanto ele quanto este card do Cemitério e, depois, compre 1 card. \r\nVocê só pode usar este efeito de "Ritual da Condenação Tornassol" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8963089,'Heosvarog, o Amanhecer Mecânico',replace(replace('2 monstros Máquina de LUZ	\r\nSe este card for Invocado por Invocação-Fusão: você pode ativar este efeito; durante a Fase de Apoio do próximo turno, adicione 1 card do seu Cemitério à sua mão, com um efeito que Invoque um ou mais monstros por Invocação-Fusão. \r\nQuando seu oponente ativar um Card de Magia/Armadilha ou seus efeitos (Efeito Rápido): você pode banir 1 monstro Máquina de LUZ com a face para cima que você controla ou 2 monstros Máquina de LUZ do seu Cemitério; negue a ativação. \r\nVocê só pode usar cada efeito de "Heosvarog, o Amanhecer Mecânico" uma vez por turno.','\r',char(13)),'\n',char(10)),'Recuperar cards relacionados à Fusão','Negar a ativação','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8964854,'Ataque Combinatório',replace(replace('Durante a Battle Phase, você pode usar este efeito em 1 monstro que tenha atacado este turno e esteja equipado com um Monstro de Union. \r\nSepare o equipamento de Union do monstro equipado e você pode atacar com o monstro mais uma vez este turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8967776,'Sephylon, o Senhor do Tempo Definitivo',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao ter 10 ou mais monstros no seu Cemitério. \r\nUma vez por turno: você pode Invocar por Invocação-Especial 1 monstro Fada de Nível 8 ou mais da sua mão ou do Cemitério, mas seus efeitos são negados e, além disso, seu ATK de torna 4000.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8972398,'Omni Dragão Brotaur',replace(replace('Se um monstro que você controla for destruído em batalha ou por um efeito de card do oponente: você pode Invocar este card por Invocação-Especial do Cemitério (se ele estava lá quando o monstro foi destruído) ou da mão (mesmo se ele não estava), mas bana-o quando ele deixar o campo. \r\nSe este card for Invocado por Invocação-Especial: você pode escolher 1 monstro com a face para cima no campo; descarte 1 card e, se isso acontecer, adicione 1 monstro do seu Deck à sua mão, com o mesmo Tipo e Atributo que o do alvo, mas com um nome diferente. \r\nVocê só pode usar cada efeito de "Omni Dragão Brotaur" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar este card por Invocação Especial','Procurar no Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(8978197,'Real Senhor dos Dragões',replace(replace('O nome deste card se torna "Senhor dos Dragões" enquanto ele estiver no campo. \r\nQuando este card for Invocado por Invocação-Normal: você pode descartar 1 Magia/Armadilha; adicione 1 "A Flauta para Invocação de Dragões", "A Melodia do Despertar do Dragão" ou "Rapsódia da Ressuscitação do Dragão" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9000988,'Camarartista Dragão Moeda',replace(replace('Escala de Pêndulo = 5\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno: você pode escolher 1 monstro do Tipo Dragão que você controla que foi Invocado por Invocação-Especial do Deck Adicional; neste turno, se esse monstro que você controla batalhar um monstro do oponente, bana o monstro do oponente depois do cálculo de dano (mesmo que este card deixe o campo).\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nOutros monstros do Tipo Dragão que você controla ganham 500 de ATK e, além disso, eles não podem ser destruídos por efeitos de card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9012916,'Dragão de Asas Negras',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nSe você sofreria dano de um efeito de card, em vez disso, coloque 1 Marcador de Pena Negra neste card. \r\nEste card perde 700 de ATK para cada Marcador de Pena Negra nele. \r\nUma vez por turno: você pode remover todos os Marcadores de Pena Negra deste card e, depois, escolha 1 monstro com a face para cima que seu oponente controla; o alvo perde 700 de ATK para cada Marcador de Pena Negra removido e, se isso acontecer, cause dano ao seu oponente igual ao ATK reduzido por este efeito.','\r',char(13)),'\n',char(10)),'Reduzir ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9012917,'Dragão de Asas Negras',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nSe você sofreria dano de um efeito de card, em vez disso, coloque 1 Marcador de Pena Negra neste card. \r\nEste card perde 700 de ATK para cada Marcador de Pena Negra nele. \r\nUma vez por turno: você pode remover todos os Marcadores de Pena Negra deste card e, depois, escolha 1 monstro com a face para cima que seu oponente controla; o alvo perde 700 de ATK para cada Marcador de Pena Negra removido e, se isso acontecer, cause dano ao seu oponente igual ao ATK reduzido por este efeito.','\r',char(13)),'\n',char(10)),'Reduzir ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9024198,'D/D/D Gilgamesh, o Rei do Abismo',replace(replace('2 monstros "D/D"	\r\nSe este card for Invocado por Invocação-Especial: você pode ativar este efeito; você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros "D/D" e, além disso, coloque 2 Monstros Pêndulo "D/D" com nomes diferentes do seu Deck nas suas Zonas de Pêndulo e, se isso acontecer, sofra 1000 de dano. \r\nSe este card Invocado por Invocação-Link for destruído em batalha com um monstro atacante do oponente, ou por um efeito de card do oponente enquanto estiver na Zona de Monstros do seu dono: você pode Invocar por Invocação-Especial 1 monstro "D/D" do seu Deck Adicional ou Cemitério em Posição de Defesa. \r\nVocê só pode usar cada efeito de "D/D/D Gilgamesh, o Rei do Abismo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9024367,'Dragão das Galáxias',replace(replace('Este card não pode atacar diretamente e só pode atacar monstros do Tipo Dragão. \r\nSe este card batalhar um monstro do Tipo Dragão, este card ganha 1000 de ATK, apenas durante a Etapa de Dano e, além disso, esse monstro tem seus efeitos negados durante esta Fase de Batalha enquanto este card permanecer com a face para cima no campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9028399,'Calcífico Crostado Cataclísmico',replace(replace('Se um ou mais monstros de TERRA com a face para cima que você controla forem destruídos em batalha ou por um efeito de card do oponente: você pode Invocar este card por Invocação-Especial da sua mão e, depois, você pode enviar 1 monstro do seu Deck para o Cemitério. \r\nVocê só pode usar este efeito de "Calcífico Crostado Cataclísmico" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invoque este card por Invocação Especial da sua mão','Enviar um monstro do seu Deck para o Cemitério?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9030160,'Pacto Obscuro com a Escuridão Eterna',replace(replace('Enquanto você tiver 2 cards "D/D" nas suas Zonas de Pêndulo, seu oponente não pode escolher monstros no campo como alvo de efeitos de Magia/Armadilha, oferecê-los como Tributo para uma Invocação-Tributo, nem usá-los como Matérias para uma Invocação-Fusão, Sincro ou Xyz. \r\nUma vez por turno, durante sua Fase de Apoio: sofra 1000 de dano.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9032529,'Lágrima Graciosa','Adicione 1 card da sua mão à mão do seu oponente e, depois, ganha 2000 PV.','Escolha o(s) card(s) na sua mão para entregar ao seu oponente','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9047460,'Asanegra - Vapor, o Manto',replace(replace('Se este card com a face para cima deixar o campo: Invoque por Invocação-Especial 1 "Ficha de Fumaça" (Aqua/VENTO/Nível 1/ATK 100/DEF 100). \r\nSe este card estiver no seu Cemitério: você pode oferecer 1 monstro como Tributo; Invoque este card por Invocação-Especial do Cemitério. \r\nVocê só pode usar este efeito de "Asanegra - Vapor, o Manto" uma vez por Duelo. \r\nSe este card Invocado desta forma for usado como Matéria Sincro, todas as outras Matéria Sincro devem ser monstros "Asanegra".','\r',char(13)),'\n',char(10)),'Invocação Especial','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9047461,'Ficha de Fumaça','Invocado por Especial com o efeito "Asanegra - Vapor, o Manto".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9053187,'Gagagigo, o Ressurgido','3 monstros de Nível 4','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9056100,'General Grunard da Barreira de Gelo',replace(replace('Durante sua Fase Principal, você pode Invocar por Invocação-Normal 1 monstro "Barreira de Gelo" em adição à sua Invocação-Normal/Baixar (padrão). \r\n(Você só pode se aproveitar deste efeito uma vez por turno.)','\r',char(13)),'\n',char(10)),'Invocar pelo efeito de "General Grunard da Barreira de Gelo"','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9059700,'Barreira Inférnica','Quando seu oponente ativar um Card de Magia/Armadilha, ou efeito de monstro, enquanto você controlar um monstro "Inférnico(a)" com a face para cima em Posição de Ataque e não tiver cards na sua mão: negue a ativação e, se isso acontecer, destrua esse card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9061682,'Andwraith Mitológico',replace(replace('1 Regulador "Mitológico(a)" + 1+ monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Especial: seu oponente pode descartar 1 card para negar este efeito, caso contrário, você pode comprar 2 cards e, depois, descarte 1 card. \r\nSe um ou mais monstros forem enviados da mão do seu oponente para o Cemitério (exceto durante a Etapa de Dano): você pode escolher 1 desses monstros; Invoque-o por Invocação-Especial no seu campo, mas negue seus efeitos. \r\nVocê só pode usar cada efeito de "Andwraith Mitológico" uma vez por turno.','\r',char(13)),'\n',char(10)),'Compre e depois descarte 1 card','Descartar 1 card para negar o efeito de "Andwraith Mitológico"?','Invocar por Invocação Especial o monstro do seu oponente','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9064354,'Fábrica Negra de Mais Produção',replace(replace('Você pode enviar 1 monstro da sua mão ou do campo para o Cemitério; compre 1 card. \r\nVocê só pode usar este efeito de "Fábrica Negra de Mais Produção" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9069157,'Dragãoroide',replace(replace('Uma vez por turno, se este card estiver no seu Cemitério: até o final deste turno, você pode fazer com que este card se torne um monstro Dragão enquanto estiver no Cemitério. \r\nVocê pode descartar este card e, depois, ative 1 desses efeitos;\r\n● Adicione 1 monstro "roide" que não seja de VENTO do seu Deck à sua mão.\r\n● Neste turno, a ativação dos seus cards e efeitos que incluam um efeito que Invoque por Invocação-Fusão um Monstro de Fusão não pode ser negada e, além disso, seu oponente não pode ativar cards ou efeitos quando um monstro for Invocado por Invocação-Fusão desta forma.	\r\nVocê só pode usar este efeito de "Dragãoroide" uma vez por turno.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Resistência à Fusão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9070454,'Aura Utópica Draco',replace(replace('Quando seu oponente ativar um efeito de monstro no campo: negue a ativação e, se isso acontecer, destrua esse card e, depois, você pode aplicar o seguinte efeito.\r\n● Bana 1 monstro da sua mão e, se isso acontecer, Invoque por Invocação-Especial no seu campo o monstro que foi destruído e enviado para o Cemitério por este efeito, mas negue seus efeitos.	\r\nVocê só pode ativar 1 "Aura Utópica Draco" por turno.','\r',char(13)),'\n',char(10)),'Invocar aquele monstro por Invocação Especial?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9074847,'Grande Motim','Se um ou mais monstros que você controla forem devolvidos à sua mão por um efeito de card do oponente: devolva para a mão tantos monstros no campo quanto possível e, depois, cada duelista Invoca monstros por Invocação-Especial da mão dele, com a face para baixo em Posição de Defesa, igual ao número de Cards de Monstros que foram devolvidos à mão dele.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9076207,'Ninja Armado',replace(replace('VIRE: Destrói 1 Card de Magia no Campo. \r\nSe o alvo deste card está com a face para baixo, vire a face para cima. \r\nSe for um Card de Magia é destruído. \r\nSe não, coloque-o novamente com a face para baixo. \r\nO card virado não é Activado.','\r',char(13)),'\n',char(10)),'Destruir um Card de Magia','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9091064,'Alma Aniquiladora Jiaolong',replace(replace('Se você revelar um ou mais cards na sua mão para ativar um card ou efeito "Alma Aniquiladora" (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão. \r\n(Efeito Rápido): você pode ativar 1 desses efeitos ao revelar um ou mais monstros na sua mão com o(s) \r\nAtributo(s) listado(s);\r\n● FOGO: Mude a posição de batalha de 1 monstro no campo.\r\n● 2 FOGO: Adicione 1 card "Alma Aniquiladora" do seu Deck à sua mão, exceto "Alma Aniquiladora Jiaolong".	\r\nVocê só pode usar cada efeito de "Alma Aniquiladora Jiaolong" uma vez por turno e não pode ativar mais que 1 na mesma Corrente.','\r',char(13)),'\n',char(10)),'Invoque este card por Invocação Especial da sua mão','Revele 1 monstro de FOGO','Revele 2 monstros de FOGO','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9097866,'Cruzadora Debug',replace(replace('Se você controlar 2 ou mais Monstros Link: você pode Invocar este card por Invocação-Especial da sua mão. \r\nDurante o cálculo de dano, se um Monstro Link seu batalhar um Monstro Link do oponente (Efeito Rápido): você pode banir este card do seu Cemitério e, depois, escolher 1 Monstro Link no seu Cemitério; seu monstro que está batalhando não pode ser destruído nessa batalha e, além disso, até o final deste turno, ele ganha ATK igual ao ATK do alvo. \r\nVocê só pode usar cada efeito de "Cruzadora Debug" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Aumentar ATK e evitar destruição em batalha','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9102835,'Fusão Salamandra',replace(replace('Só pode ser equipado a um monstro Guerreiro de FOGO. \r\nEle ganha 700 de ATK. \r\nSe o monstro equipado seria destruído em batalha ou por um efeito de card, em vez disso, você pode destruir este card. \r\nEnquanto este card estiver equipado a um Monstro de Fusão que você controla: você pode enviar este card e o monstro equipado para o Cemitério e, se isso acontecer, Invoque por Invocação-Especial 1 "Espadachim das Chamas", ou 1 Monstro de Fusão que o mencione, do seu Deck Adicional. \r\n(Isso é considerado uma Invocação-Fusão.) \r\nVocê só pode usar este efeito de "Fusão Salamandra" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Invoque por Fusão "Espadachim das Chamas" ou um Monstro Fusão que mencione o nome daquele card','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9106362,'Camarartista Gongato',replace(replace('Escala de Pêndulo = 2\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno, quando um monstro do oponente declarar um ataque direto: você pode ativar este efeito; você não sofre dano de batalha dessa batalha (mesmo que este card deixe o campo).\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nUma vez por turno, quando um ataque for declarado envolvendo um monstro que você controla e um monstro do oponente: você pode ativar este efeito; você não sofre dano de batalha dessa batalha.','\r',char(13)),'\n',char(10)),'O dano de batalha se torna 0','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9107531,'Destruidor Electro',replace(replace('Se você Invocar por Invocação-Normal ou Especial um ou mais monstros de FOGO (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão e, depois, você pode enviar 1 monstro Piro de Nível 8 do seu Deck para o Cemitério. \r\nVocê só pode usar este efeito de "Destruidor Electro" uma vez por turno. \r\nUma vez por turno, se um Card de Magia for ativado (exceto durante a Etapa de Dano): você pode fazer com que todos os monstros de FOGO que você controla atualmente ganhem 300 de ATK.','\r',char(13)),'\n',char(10)),'Enviar do seu Deck para o Cemitério?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9109991,'Asanegra - Fane, o Corrente de Aço',replace(replace('Este card pode atacar diretamente seu oponente. \r\nSe este card causar dano de batalha ao seu oponente em um ataque direto: escolha 1 monstro em Posição de Ataque que seu oponente controla; coloque o alvo em Posição de Defesa.','\r',char(13)),'\n',char(10)),'Mudar para Posição de Defesa','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9113513,'Ostinato',replace(replace('Se você não controlar nenhum monstro: Invoque por Invocação-Fusão 1 Monstro de Fusão "Melodiosa(o)" do seu Deck Adicional, usando 2 monstros da sua mão e/ou do Deck como matéria. \r\nDurante a Fase Final deste turno, destrua o monstro Invocado por Invocação-Fusão por este efeito e, se isso acontecer, se todas as matérias que foram usadas para sua Invocação-Fusão estiverem no seu Cemitério, você pode Invocar todas elas por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial o monstro Matéria de Fusão?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9126351,'Sapo de Troca',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) ao descartar 1 outro monstro de ÁGUA. \r\nQuando este card for Invocado: você pode enviar 1 monstro Aqua de ÁGUA de Nível 2 ou menos do seu Deck ou campo com a face para cima para o Cemitério. \r\nUma vez por turno: você pode devolver 1 monstro que você controla para a mão; você pode Invocar por Invocação-Normal 1 monstro "Sapo" durante sua Fase Principal neste turno, exceto "Sapo de Troca", em adição à sua Invocação-Normal/Baixar (padrão). \r\n(Você só pode se aproveitar deste efeito uma vez por turno.)','\r',char(13)),'\n',char(10)),'Invocar pelo efeito de "Sapo de Troca"','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9145181,'Selamento de Ritual','Destrua 1 Monstro de Ritual com a face para cima no campo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9156135,'Mago Aprendiz',replace(replace('Se este card for Invocado: escolha 1 card com a face para cima no campo sobre o qual você possa colocar um Marcador de Magia; coloque 1 Marcador de Magia no alvo. \r\nQuando este card for destruído em batalha: você pode Invocar por Invocação-Especial 1 monstro Mago de Nível 2 ou menos do seu Deck, com a face para baixo em Posição de Defesa.','\r',char(13)),'\n',char(10)),'Colocar Marcadores de Magia','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9159938,'Cinzento das Trevas','Totalmente cinzenta, esta besta raramente foi vista por olhos mortais.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9161357,'Número 6: Cronomalia Atlande',replace(replace('2 monstros de Nível 6	\r\nQuando este card for Invocado por Invocação Xyz: você pode escolher 1 monstro "Número" em seu Cemitério; equipe o alvo neste card. \r\nEste card ganha ATK igual à metade do ATK do monstro equipado. \r\nUma vez por turno: você pode desassociar 1 Matéria Xyz deste card e, depois, enviar o monstro equipado por este efeito para o Cemitério; reduza pela metade os Pontos de Vida do seu oponente. \r\nVocê não pode conduzir sua Fase de Batalha no turno em que ativar este efeito.','\r',char(13)),'\n',char(10)),'Equipar','Reduzir os PV pela metade','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9175957,'Alvo na Mira, Springans!',replace(replace('Quando você ativar este card, você também pode desassociar até 3 matérias dos monstros que você controla; adicione 1 monstro "Springans" do seu Deck à sua mão e, depois, se você desassociou qualquer matéria na ativação, você pode Invocar por Invocação-Especial esse mesmo número de monstros "Springans" da sua mão ou do Cemitério. \r\nDurante sua Fase Principal, se este card estiver no seu Cemitério: você pode escolher 1 Monstro Xyz no campo; desassocie 1 matéria dele e, se isso acontecer, adicione este card à sua mão. \r\nVocê só pode usar 1 efeito de "Alvo na Mira, Springans!" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Desassociar Matéria Xyz para ativar?','Invocar por Invocação Especial um monstro "Springans"?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9190563,'RAM Nuvler',replace(replace('Você pode oferecer 1 monstro como Tributo e, depois, escolher 1 monstro Ciberso no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê só pode usar este efeito de "RAM Nuvler" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9197735,'Estátua do Dragão','Um guerreiro de pedra com coração de dragão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9201964,'Fortuna-D','Quando seu oponente declarar um ataque direto: Bana 1 monstro "HERÓI do Destino" do seu Cemitério; encerre a Fase de Batalha.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9205573,'Evil★Gêmea Ki-sikil',replace(replace('2 monstros, incluindo um monstro "Ki-sikil"	\r\nSe este card for Invocado por Invocação-Especial e você controlar um monstro "Lil-la": você pode comprar 1 card. \r\nDurante a Fase Principal, se você não controlar um monstro "Lil-la" (Efeito Rápido): você pode Invocar por Invocação-Especial 1 monstro "Lil-la" do seu Cemitério e, além disso, você não pode Invocar monstros por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto monstros Demônio. \r\nVocê só pode usar cada efeito de "Evil★Gêmea Ki-sikil" uma vez por turno.','\r',char(13)),'\n',char(10)),'Comprar','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9205574,'Evil★Gêmea Ki-sikil',replace(replace('2 monstros, incluindo um monstro "Ki-sikil"	\r\nSe este card for Invocado por Invocação-Especial e você controlar um monstro "Lil-la": você pode comprar 1 card. \r\nDurante a Fase Principal, se você não controlar um monstro "Lil-la" (Efeito Rápido): você pode Invocar por Invocação-Especial 1 monstro "Lil-la" do seu Cemitério e, além disso, você não pode Invocar monstros por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto monstros Demônio. \r\nVocê só pode usar cada efeito de "Evil★Gêmea Ki-sikil" uma vez por turno.','\r',char(13)),'\n',char(10)),'Comprar','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9212051,'MISSÃO ESPIRÃO - Resgate',replace(replace('Destrua este card durante sua 3ª Fase Final depois da ativação. \r\nUma vez por turno: você pode escolher 1 monstro "ESPIRÃO" no seu Cemitério; adicione-o à sua mão. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 monstro "ESPIRÃO" no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê só pode controlar 1 "MISSÃO ESPIRÃO - Resgate".','\r',char(13)),'\n',char(10)),'Ativar, mas não resolver o efeito','Ativar e resolver o efeito','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9213491,'Garota Psíquica Serena',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode banir 1 card da sua mão e, se isso acontecer, Invoque por Invocação-Especial 1 monstro Psíquico de Nível 4 ou menos do seu Deck, exceto "Garota Psíquica Serena" e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto monstros Psíquico. \r\nVocê pode escolher monstros com a face para cima no campo até o número de monstros Psíquico que você controla; aumente o Nível deles em 1 até o final deste turno. \r\nVocê só pode usar cada efeito de "Garota Psíquica Serena" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Aumentar o Nível','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9236985,'Foto-espelho Gishki',replace(replace('Este card pode ser usado para a Invocação-Ritual de qualquer Monstro de Ritual "Gishki". \r\nVocê também deve pagar um número de Pontos de Vida igual ao Nível do monstro Invocado por Invocação-Ritual x 500 (quando este card resolver).','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9238125,'Vernasílfide das Montanhas Descongeladas',replace(replace('Você pode descartar este card e 1 monstro ou card "Vernasílfide"; compre 1 card e, depois, você pode Invocar por Invocação-Especial 1 monstro de TERRA do seu Cemitério e, além disso, você não pode ativar efeitos de monstros que não sejam de TERRA pelo resto deste turno. \r\nVocê pode escolher 1 monstro "Vernasílfide" que você controla; ele pode realizar um segundo ataque durante cada Fase de Batalha neste turno. \r\nVocê só pode usar cada efeito de "Vernasílfide das Montanhas Descongeladas" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial do Cemitério?','O efeito de "Vernasílfide das Montanhas Descongeladas" está sendo aplicado.','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9251497,'Kingyo Sukui',replace(replace('Você pode escolher 1 monstro no Cemitério do seu oponente; escave o card do topo do seu Deck e, se for um monstro com o mesmo Atributo que o do alvo, adicione-o à sua mão e, se isso acontecer, embaralhe o alvo no Deck. \r\nCaso contrário, envie o card escavado para o Cemitério e, além disso, destrua este card. \r\nVocê só pode usar este efeito de "Kingyo Sukui" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9260791,'Dragão de Bruma de Olhos das Galáxias',replace(replace('Você pode oferecer este card como Tributo; Invoque por Invocação-Especial 1 monstro "Olhos das Galáxias" da sua mão ou Cemitério, exceto "Dragão de Bruma de Olhos das Galáxias". \r\nVocê só pode usar este efeito de "Dragão de Bruma de Olhos das Galáxias" uma vez por turno. \r\nSe este card estiver no Cemitério: você pode escolher 1 Monstro Xyz "Olhos das Galáxias" que você controla; associe este card a ele como uma Matéria Xyz. \r\nVocê só pode usar este efeito de "Dragão de Bruma de Olhos das Galáxias" uma vez por Duelo.','\r',char(13)),'\n',char(10)),'Invocação Especial','Associar Matéria','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9264485,'Servo de Horus','Enquanto este card permanecer no seu Campo com a face para cima, o seu adversário não pode designar "Horus, o Dragão da Chama Negra (de qualquer LV)" como alvo do efeito de nenhum Card de Magia, Armadilha ou de Monstro.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9267769,'Granada de Atordoamento',replace(replace('Ative apenas depois do cálculo de dano quando um monstro que seu oponente controla realizar um ataque direto. \r\nEsta se torna a Fase Final deste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9272381,'Cavaleirostelar Constelar Diamante',replace(replace('3+ monstros de LUZ de Nível 5	\r\nDurante sua Fase Principal 2, você também pode Invocar este card por Invocação-Xyz usando um Monstro Xyz "Cavaleirost" que você controla como matéria, exceto "Cavaleirostelar Constelar Diamante". \r\n(Transfira as matérias dele para este card.) \r\nEnquanto este card tiver matéria, nenhum duelista pode enviar cards do Deck para o Cemitério, e qualquer card que for devolvido do Cemitério para a mão, em vez disso, é banido. \r\nQuando o efeito de um monstro de TREVAS do oponente for ativado (Efeito Rápido): você pode desassociar 1 matéria deste card; negue a ativação e, se isso acontecer, destrua-o.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Xyz usando um Monstro Xyz "Cavaleirostelar" como matéria?','Negar e destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9275482,'UFOLuz',replace(replace('Seu oponente não pode escolher este card no campo como alvo de efeitos de card, exceto durante a Fase de Batalha. \r\nSe este card batalhar um monstro, nenhum dos dois pode ser destruído nessa batalha. \r\nDurante a Fase Final: você pode comprar 1 card e, depois, você deve banir qualquer número de cards da sua mão (mín. 1) e, se isso acontecer, este card ganha 500 de ATK para cada um. \r\nVocê só pode usar este efeito de "UFOLuz" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9283801,'A Revolta dos Monarcas',replace(replace('Descarte 1 card; revele 3 monstros do seu Deck, com 2400 ou mais de ATK e 1000 de DEF, e/ou 800 de ATK/1000 de DEF, seu oponente seleciona 1 para que você adicione à sua mão, e você envia o resto para o Cemitério e, além disso, pelo resto deste turno depois que este card resolver, você não pode Invocar por Invocação-Especial do Deck Adicional. \r\nVocê pode banir este card do seu Cemitério; Invoque por Invocação-Especial 1 monstro com 800 de ATK/1000 de DEF da sua mão. \r\nVocê só pode usar cada efeito de "A Revolta dos Monarcas" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9284723,'Jiboia da Peçonha',replace(replace('Uma vez por turno, você pode colocar 2 Marcadores de Veneno sobre 1 monstro que seu oponente controla. \r\nSe você ativar este efeito, este card não pode atacar durante este turno.','\r',char(13)),'\n',char(10)),'Colocar um marcador','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9287078,'Renovação Negra','Quando seu oponente Invocar um ou mais monstros por Invocação-Normal ou Especial: escolha 1 desses monstros e 1 monstro Mago que você controla; envie os dois monstros para o Cemitério e, depois, você pode Invocar por Invocação-Especial 1 monstro Mago de TREVAS do seu Deck ou Cemitério.','Invocar por Invocação Especial 1 monstro de TREVAS de Tipo Mago do seu Deck ou Cemitério?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9293977,'Dragão de Metal','"Ogre de Aço da Gruta nº 1" + "Dragão Inferior"','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9298235,'Fofanimal Garça','Quando um ou mais monstros "Fofanimal" com a face para cima que você controla forem destruídos por um ataque ou efeito de card do seu oponente e enviados para o seu Cemitério: escolha 1 desses monstros destruídos; adicione-o à sua mão e, se isso acontecer, compre 1 card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9322133,'Laser Apagador Psíquico',replace(replace('Envie 1 monstro que seu oponente controla que foi Invocado por Invocação-Especial do Deck Adicional para o Cemitério e, depois, seu oponente ganha PV igual ao ATK ou DEF original desse monstro (o que for maior). \r\nVocê só pode ativar 1 "Laser Apagador Psíquico" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9327502,'Voltica, o HERÓI do Elemento','Quando este card causar dano de batalha ao seu oponente: você pode escolher 1 dos seus monstros "HERÓI do Elemento" banidos; Invoque o alvo por Invocação-Especial.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9334391,'Vínculo Cristalino',replace(replace('Adicione 1 monstro "Fera Cristalina" do seu Deck à sua mão e coloque 1 monstro "Fera Cristalina" com um nome diferente do seu Deck, com a face para cima na sua Zona de Magias & Armadilhas como uma Magia Contínua. \r\nVocê só pode ativar 1 "Vínculo Cristalino" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9336190,'Os Cavaleiros Fantasmas das Garras de Névoas',replace(replace('Escolha 1 dos seus monstros "Os Cavaleiros Fantasmas" banidos; adicione-o à sua mão. \r\nQuando um monstro do oponente declarar um ataque direto enquanto este card estiver no seu Cemitério: você pode escolher 1 monstro "Os Cavaleiros Fantasmas" de Nível 4 ou menos no seu Cemitério; Invoque esse monstro por Invocação-Especial e, se isso acontecer, Invoque este card por Invocação-Especial como um Monstro Normal como mesmo Nível original que o desse monstro (Guerreiro/TREVAS/ATK 0/DEF 0).	\r\n(Este card NÃO é considerado como uma Armadilha.) \r\nSe Invocado desta forma, bana este card quando ele deixar o campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9341993,'Ajuda do Adamancipador','Ofereça como Tributo qualquer número de monstros "Adamancipador" e, depois, escolha como alvo cards no campo igual a esse número +1; destrua-os.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9342162,'Cagna, Malebranche do Abismo Ardente',replace(replace('Se você controlar um monstro que não seja um monstro "Abismo Ardente", destrua este card. \r\nVocê só pode usar 1 desses efeitos de "Cagna, Malebranche do Abismo Ardente" por turno e apenas uma vez por turno.\r\n● Se você não controlar nenhum Card de Magia/Armadilha: você pode Invocar este card por Invocação-Especial da sua mão.\r\n● Se este card for enviado para o Cemitério: você pode enviar 1 Card de Magia/Armadilha "Abismo Ardente" do seu Deck para o Cemitério.','\r',char(13)),'\n',char(10)),'Invocação Especial','Enviar para o Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9348522,'Castelo nas Nuvens',replace(replace('1 Regulador + 1+ não-Reguladores	\r\nQuando este card for Invocado por Invocação-Sincro: você pode escolher 1 monstro de Nível 9 no seu Cemitério; Invoque o alvo por Invocação-Especial. \r\nMonstros de Nível 8 ou menos não podem atacar no turno em que forem Invocados por Invocação-Normal ou Especial.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9349094,'Besta Árvore Sagrada, Hyperyton',replace(replace('2 monstros de Nível 9	\r\nDurante o seu turno, quando você ativar um card ou efeito (Efeito Rápido): você pode escolher 1 card do mesmo tipo (Monstro, Magia ou Armadilha) no seu Cemitério; associe ele a este card como matéria. \r\nDurante o turno do seu oponente, quando um card ou efeito for ativado (Efeito Rápido): você pode desassociar 1 matéria do mesmo tipo (Monstro, Magia ou Armadilha) que o deste card e, se isso acontecer, negue a ativação e, se isso acontecer, destrua esse card. \r\nVocê só pode usar cada efeito de "Besta Árvore Sagrada, Hyperyton" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9350312,'Vernasílfide das Colinas Florescentes',replace(replace('Monstros "Vernasílfide" que você controla não podem ser destruídos por efeitos de card. \r\nVocê pode descartar este card e 1 monstro ou card "Vernasílfide"; adicione 1 card "Vernasílfide" do seu Deck à sua mão, exceto "Vernasílfide das Colinas Florescentes" e, depois, você pode Invocar por Invocação-Especial 1 monstro de TERRA do seu Cemitério e, além disso, você não pode ativar efeitos de monstros que não sejam de TERRA pelo resto deste turno. \r\nVocê só pode usar este efeito de "Vernasílfide das Colinas Florescentes" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial do Cemitério?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9354555,'Véu de Fóton',replace(replace('Embaralhe 3 monstros de LUZ da sua mão no Deck e, depois, adicione de 1 a 3 monstros de LUZ de Nível 4 ou menos do seu Deck à sua mão. \r\nSe você adicionar 2 ou mais monstros, eles precisam ter o mesmo nome.','\r',char(13)),'\n',char(10)),'Adicionar outro card à mão?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9365703,'Guerreiro Veloz','Uma vez por Etapa de Batalha, se este card foi Invocado por Invocação-Normal neste turno (exceto durante a Etapa de Dano): até o final da Fase de Batalha, você pode fazer com que o seu ATK se torne o dobro do seu ATK original.','Alterar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9373534,'Fuhma Shuriken',replace(replace('Só pode ser equipado a um monstro "Ninja". \r\nGanha 700 de ATK. \r\nQuando este card for enviado do campo para o Cemitério: cause 700 de dano ao seu oponente.','\r',char(13)),'\n',char(10)),'Cause 700 de dano ao seu oponente','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9391354,'Dragão da Gravidade Esmagadora','Você pode enviar 1 Card de Magia Contínua com a face para cima que você controla ao Cemitério e, depois, escolher 1 monstro que seu oponente controla; destrua o alvo.','Destruir um monstro','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9396662,'Mago do Espelho da Barreira de Gelo',replace(replace('Você pode oferecer como Tributo 1 outro Monstro de Efeito; Invoque por Invocação-Especial até 3 "Ficha de Barreira de Gelo" (Aqua/ÁGUA/Nível 1/ATK 0/DEF 0) e, se isso acontecer, aumente o Nível deste card por esse número e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto Monstros Sincro de ÁGUA. \r\nSe este card for enviado para o Cemitério: você pode adicionar à sua mão 1 dos seus cards "Barreira de Gelo" que estiverem banidos ou no seu Deck, exceto "Mago do Espelho da Barreira de Gelo". \r\nVocê só pode usar cada efeito de "Mago do Espelho da Barreira de Gelo" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar uma Ficha por Invocação Especial','Adicionar à mão','Escolha a quantidade de Fichas para Invocar por Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9396663,'Ficha de Barreira de Gelo','Invocado por Especial com o efeito "Oradora da Barreira de Gelo".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9400127,'Flogos, o Infinito Ogdoádico',replace(replace('Se este card for enviado do campo para o Cemitério ou Invocado por Invocação-Especial do Cemitério: você pode escolher 1 monstro com a face para cima que seu oponente controla e 1 monstro no Cemitério dele com um ATK igual ou maior que o do alvo; Invoque por Invocação-Especial no campo dele esse monstro do Cemitério e, se isso acontecer, envie o outro monstro que ele controla para o Cemitério. \r\nSe este card estiver no seu Cemitério: você pode enviar 1 card da sua mão para o Cemitério; adicione este card à sua mão. \r\nVocê só pode usar cada efeito de "Flogos, o Infinito Ogdoádico" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9402966,'Samurai Superpesado Bola de Batalha',replace(replace('Se todos os monstros que você controla forem monstros "Samurai Superpesado" e você não tiver Cards de Magia/Armadilha no seu Cemitério: você pode escolher 1 monstro com a face para cima que seu oponente controla e que tenha Nível; envie tanto a ele como a este card do campo para o Cemitério e, depois, Invoque por Invocação-Especial do seu Deck Adicional 1 Monstro Sincro "Samurai Superpesado" cujo Nível seja igual à soma dos Níveis originais desses 2 monstros no Cemitério. \r\n(Esta Invocação-Especial é considerada uma Invocação-Sincro.) \r\nVocê só pode usar este efeito de "Samurai Superpesado Bola de Batalha" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9409625,'Máquina Vazia',replace(replace('Na primeira vez que este card com a face para cima no campo seria destruído por um efeito de card do oponente, ele não é destruído. \r\nUma vez por turno, você pode ativar 1 desses efeitos.\r\n● Descarte 1 monstro de Nível 10; compre 1 card.\r\n● Se este for o único card na sua Zona de Magias & Armadilhas: escolha 1 monstro "Senhor do Tempo" no seu Cemitério; embaralhe-o no Deck e, depois, você pode Baixar 1 "Máquina Infinita" diretamente da sua mão ou do seu Deck.','\r',char(13)),'\n',char(10)),'Comprar','Recuperar do Cemitério','Baixar "Máquina Infinita"?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9411399,'HERÓI do Destino - Malicioso','Você pode banir este card do seu Cemitério; Invoque por Invocação-Especial 1 "HERÓI do Destino - Malicioso" do seu Deck.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9416697,'Eanoc, o Sentinela dos Ghoti',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 dos seus monstros Peixe de Nível 4 ou menos banidos; Invoque-o por Invocação-Especial em Posição de Defesa, mas negue seus efeitos. \r\nVocê pode banir 1 monstro Peixe da sua mão ou do campo com a face para cima; adicione 1 Armadilha "Ghoti" do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "Eanoc, o Sentinela dos Ghoti" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9418365,'Bujin Hirume',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nVocê primeiro deve Invocá-lo por Invocação-Especial (da sua mão) ao banir 1 monstro "Bujin" do seu Cemitério, exceto "Bujin Hirume". \r\nSe este card, que foi Invocado desta forma, for destruído por um card do seu oponente (em batalha ou por um efeito de card) e enviado do seu lado do campo para o seu Cemitério e os dois duelistas tiverem uma mão: você pode descartar 1 card e, depois, seu oponente descarta 1 card. \r\nVocê só pode controlar 1 "Bujin Hirume".','\r',char(13)),'\n',char(10)),'Descarte 1 card','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9418534,'Jinzo - Regressado',replace(replace('Este card pode atacar diretamente. \r\nQuando este card for enviado para o Cemitério: você pode escolher 1 "Jinzo" no seu Cemitério; Invoque-o por Invocação-Especial, mas destrua-o durante sua Fase Final.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9430387,'Nuvem LaLa Li-oon','Uma criatura de nuvem elétrica. A sua chuva ácida a torna muito perigosa.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9433350,'Dragão Branco de Olhos Azuis Pernicioso',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro deve ser Invocado por Invocação-Especial (da sua mão) ao banir 1 "Dragão Branco de Olhos Azuis" do seu Deck. \r\nSó pode haver 1 monstro "Pernicioso(a)" no campo. \r\nOutros monstros que você controla não podem declarar um ataque. \r\nSe não houver Magias de Campo com a face para cima no campo, destrua este card.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9453320,'Abistrite, o Espírito Atlante',replace(replace('2+ monstros de ÁGUA de Nível 7	\r\nMonstros de ÁGUA que você controla ganham 300 de ATK/DEF para cada matéria associada a este card. \r\nVocê só pode usar cada um dos seguintes efeitos de "Abistrite, o Espírito Atlante" uma vez por turno. \r\nSe este card for Invocado por Invocação-Xyz: você pode escolher 1 monstro Peixe, Serpente Marinha ou Aqua de Nível 7 ou menos no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê pode desassociar 1 matéria deste card; Baixe 1 Armadilha "Abis-" do seu Deck.','\r',char(13)),'\n',char(10)),'Invocação Especial','Baixar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9464441,'Ressurgido Adamancipador - Dragita',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nDurante sua Fase Principal: você pode escavar os 5 cards do topo do seu Deck e, se isso acontecer, você pode devolver cards que seu oponente controla para a mão, até o número de monstros Rocha escavados e, além disso, coloque os cards escavados no fundo do seu Deck em qualquer ordem. \r\nQuando seu oponente ativar um Card de Magia/Armadilha ou seus efeitos, enquanto um monstro de ÁGUA estiver no seu Cemitério (Efeito Rápido): você pode negar a ativação e, se isso acontecer, destrua-o. \r\nVocê só pode usar cada efeito de "Ressurgido Adamancipador - Dragita" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Retornar um card à mão?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9482987,'Endymion, o Magistus da Maestria',replace(replace('Você pode escolher 1 monstro "Magistus" que você controla; equipe-o com 1 monstro "Magistus" do seu Deck Adicional. \r\nVocê pode escolher 1 Magia com a face para cima que você controla; destrua-a e, se isso acontecer, compre 1 card e, depois, coloque 1 card da sua mão no fundo do Deck. \r\nVocê só pode usar cada efeito de "Endymion, o Magistus da Maestria" uma vez por turno.','\r',char(13)),'\n',char(10)),'Equipe 1 monstro "Magistus" do seu Deck Adicional','Compre 1 card e depois coloque 1 card da sua mão no fundo do Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9485511,'U.A. Goleiro',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) ao devolver 1 monstro "U.A." que você controla para a mão, exceto "U.A. Goleiro". \r\nVocê só pode Invocar "U.A. Goleiro" por Invocação-Especial uma vez por turno desta forma. \r\nUma vez por turno, durante o turno do seu oponente: você pode escolher 1 monstro "U.A." que você controla; uma vez durante este turno, ele não pode ser destruído em batalha ou por efeitos de card (este é um Efeito Rápido).','\r',char(13)),'\n',char(10)),'Não pode ser destruído','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9486959,'Varredor de Almas Onibimaru',replace(replace('2+ monstros de Nível 2	\r\nVocê pode desassociar 1 matéria deste card e, depois, escolha 1 monstro que seu oponente controla; bana-o até a Fase Final do seu oponente. \r\nSe este card sob o controle do seu dono for destruído por um card do oponente: você pode escolher monstros banidos, até o número de matérias que este card tinha; embaralhe-os no Deck. \r\nVocê só pode usar cada efeito de "Varredor de Almas Onibimaru" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9491461,'Cavaleiro Ganbara Gagaga',replace(replace('Você pode revelar 1 monstro "Gagaga" no seu Deck Adicional; Invoque este card por Invocação-Especial da sua mão e, depois, você pode aplicar 1 desses efeitos.\r\n● Invoque por Invocação-Especial 1 monstro "Gagaga" da sua mão.\r\n● Mude a posição de batalha de 1 monstro no campo.	\r\nSe este card for desassociado de um Monstro Xyz para ativar o efeito desse monstro: você pode adicionar 1 monstro "Gogogo" do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "Cavaleiro Ganbara Gagaga" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Adicionar à mão','Invocação Especial','Alterar posição de batalha','Não resolver o efeito','','','','','','','','','','','');
INSERT INTO texts VALUES(9505425,'Crowley, o Magistus dos Grimórios',replace(replace('Você pode enviar para o Cemitério 1 monstro Mago da sua mão ou do campo com a face para cima; Invoque este card por Invocação-Especial da sua mão. \r\nVocê pode declarar 1 Atributo; este card se torna desse Atributo até o final deste turno. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 monstro "Magistus" que você controla; equipe-o com 1 monstro "Magistus" do seu Cemitério, exceto um monstro de Nível 4. \r\nVocê só pode usar cada efeito de "Crowley, o Magistus dos Grimórios" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9523599,'Renovador de Pilhas',replace(replace('Se este card for usado como matéria para uma Invocação-Link: você pode escolher 1 outro monstro Ciberso de Nível 4 ou menos no seu Cemitério, que foi usado como matéria para essa Invocação-Link; Invoque-o por Invocação-Especial em Posição de Defesa. \r\nVocê só pode usar este efeito de "Renovador de Pilhas" uma vez por Duelo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9540040,'Tartaruga de Rochedos','Uma tartaruga de pedra que é quase indestrutível.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9547962,'Circuito de Euler',replace(replace('Os monstros do seu oponente não podem atacar se você controlar 3 ou mais monstros "Tindângulo". \r\nUma vez por turno, durante sua Fase de Apoio: você pode escolher 1 monstro "Tindângulo" que você controla; conceda o controle dele ao seu oponente. \r\nVocê pode banir este card do seu Cemitério e descartar 1 card "Tindângulo"; adicione 1 "Circuito de Euler" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Circuito de Euler" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9551692,'Mestre de Ham',replace(replace('2 monstros Besta	\r\nSe este card for Invocado por Invocação-Fusão ou virado com a face para cima: você pode Invocar por Invocação-Especial 1 monstro de Virar da sua mão ou do Deck, com a face para baixo em Posição de Defesa. \r\nSe este card estiver no seu Cemitério: você pode banir 2 monstros de Virar do seu campo com a face para cima e/ou Cemitério; Invoque este card por Invocação-Especial com a face para baixo em Posição de Defesa, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar cada efeito de "Mestre de Ham" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9553721,'Local de Poder Shinobird',replace(replace('Monstros Espírito que você controla ganham 500 de ATK e DEF. \r\nSe um ou mais monstros de VENTO com a face para cima que você controla forem devolvidos à sua mão (exceto durante a Etapa de Dano): você pode adicionar 1 monstro Espírito ou Card de Magia de Ritual do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Local de Poder Shinobird" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9560338,'Ceifador da Profecia',replace(replace('Quando este card for Invocado por Invocação-Normal ou Especial: você pode ativar este efeito; aplique o máximo de efeitos possíveis, de acordo com o número de Cards de Magia "Livro de Magia" com nomes diferentes em seu Cemitério. \r\nVocê só pode usar o efeito de "Ceifador da Profecia" uma vez por turno.\r\n● 3 ou mais: Este card ganha 600 de ATK.\r\n● 4 ou mais: Adicione 1 Card de Magia "Livro de Magia" do seu Deck à sua mão.\r\n● 5 ou mais: Invoque por Invocação-Especial 1 monstro de TREVAS do Tipo Mago de Nível 5 ou mais do seu Deck.','\r',char(13)),'\n',char(10)),'Vários efeitos','Aumentar ATK','Procurar no Deck','Invocação Especial','','','','','','','','','','','','');
INSERT INTO texts VALUES(9567495,'Portão do Dragão',replace(replace('2 monstros de Nível 6	\r\nUma vez por turno, você também pode Invocar "Portão do Dragão" por Invocação-Xyz ao usar 1 Monstro Xyz de Classe 3 ou menos que você controla (transfira as matérias dele). \r\nNão pode ser usado como matéria para uma Invocação-Xyz no turno em que foi Invocado por Invocação-Xyz. \r\nUma vez por turno: você pode ativar este efeito; pelo resto deste turno, este card pode atacar todos os monstros que seu oponente controla, uma vez cada e, além disso, desassocie qualquer número de matérias deste card e, se isso acontecer, ele ganha 1000 de ATK para cada tipo de card (Monstro, Magia ou Armadilha) desassociado e, se isso acontecer, quaisquer monstros que seu oponente controla atualmente perdem esse tanto de ATK.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Xyz usando um Monstro Xyz como matéria?','Ativar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9576193,'Máquina Monstro','Escolha 1 monstro com a face para cima que você controla e 1 monstro em seu Cemitério com o mesmo Nível; bana o alvo do Cemitério, depois, compre 1 card e revele-o, e então, se o card que você comprou for um monstro do mesmo Nível que o monstro no campo, Invoque-o por Invocação-Especial.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9581215,'Buraco de Corrente',replace(replace('Quando seu oponente ativar um efeito de monstro em resposta à ativação de um card ou efeito: negue esse efeito do oponente e, depois, seu oponente pode banir 1 card da mão ou do Deck dele com o mesmo nome original que o card negado. \r\nSe ele não o fizer, você pode banir 1 card aleatório da mão dele.','\r',char(13)),'\n',char(10)),'Banir um card com o mesmo nome?','Banir um card da mão do seu oponente?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9583383,'Imperador Gagaga',replace(replace('Não pode atacar a não ser que você controle outro monstro "Gagaga". \r\nUma vez por turno: você pode banir 1 monstro do seu Cemitério que tenha um Nível; os Níveis de todos os monstros "Gagaga" que você controla atualmente se tornam o Nível desse monstro. \r\nNão pode ser usado como uma Matéria Sincro.','\r',char(13)),'\n',char(10)),'Alterar Nível','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9591819,'Fuga Gagaga',replace(replace('Quando seu oponente ativar um efeito de monstro, enquanto você controlar um monstro "Gagaga": negue a ativação e, depois, você pode descartar 1 card e, se isso acontecer, Invoque por Invocação-Especial 1 monstro "Gagaga" do seu Deck. \r\nVocê pode banir este card do seu Cemitério; coloque tantos monstros "Gagaga" que você controla quanto possível em Posição de Defesa e, se isso acontecer, pelo resto deste turno, monstros "Gagaga" que você controla não podem ser destruídos em batalha ou por efeitos de card. \r\nVocê só pode usar cada efeito de "Fuga Gagaga" uma vez por turno.','\r',char(13)),'\n',char(10)),'Negar a ativação','Mudar a posição de batalha','Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9596126,'Feiticeiro do Caos',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro deve ser Invocado por Invocação-Especial (da sua mão) ao banir 1 monstro de LUZ e 1 de TREVAS do seu Cemitério. \r\nUma vez por turno: você pode escolher 1 monstro com a face para cima no campo; bana o alvo. \r\nEste card não pode atacar no turno em que você ativar este efeito.','\r',char(13)),'\n',char(10)),'Invocação Especial','Banir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9597987,'Tenchi Kaimei',replace(replace('(Este card deve ser sempre considerado como um card "Ninjitsu".)	\r\nQuando um monstro "Ninja" que você controla causar dano de batalha ao seu oponente: você pode escolher 1 card que seu oponente controla; destrua-o. \r\nSe este card com a face para cima na Zona do Campo do seu dono deixou o campo devido a um efeito do oponente, e agora estiver no Cemitério ou banido: você pode escolher qualquer número de monstros "Ninja" com nomes diferentes no seu Cemitério; Invoque-os por Invocação-Especial com a face para baixo em Posição de Defesa.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9603252,'Fazticeira Vice-Madame',replace(replace('1 monstro "Fazticeira" + 1 monstro Mago	\r\nQuando um Card de Magia ou seus efeitos, ou o efeito de um monstro Mago que não seja de Fusão, for ativado (Efeito Rápido): você pode ativar 1 desses efeitos (mas você só pode usar cada efeito de "Fazticeira Vice-Madame" uma vez por turno).\r\n● Destrua 1 card no campo.\r\n● Invoque por Invocação-Especial 1 monstro "Fazticeira" de Nível 6 ou menos da sua mão ou do Deck.\r\n● Adicione 1 Magia/Armadilha "Fazticeira" do seu Cemitério à sua mão.','\r',char(13)),'\n',char(10)),'Destrua 1 card no campo','Invocar por Invocação Especial da sua mão/Deck','Adicionar do Cemitério à mão','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9603253,'Fazticeira Vice-Madame',replace(replace('1 monstro "Fazticeira" + 1 monstro Mago	\r\nQuando um Card de Magia ou seus efeitos, ou o efeito de um monstro Mago que não seja de Fusão, for ativado (Efeito Rápido): você pode ativar 1 desses efeitos (mas você só pode usar cada efeito de "Fazticeira Vice-Madame" uma vez por turno).\r\n● Destrua 1 card no campo.\r\n● Invoque por Invocação-Especial 1 monstro "Fazticeira" de Nível 6 ou menos da sua mão ou do Deck.\r\n● Adicione 1 Magia/Armadilha "Fazticeira" do seu Cemitério à sua mão.','\r',char(13)),'\n',char(10)),'Destrua 1 card no campo','Invocar por Invocação Especial da sua mão/Deck','Adicionar do Cemitério à mão','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9603356,'Arquidemônio Cavaleiro das Trevas',replace(replace('Uma vez por turno, durante sua Fase de Apoio, você deve pagar 900 PV (isso não é opcional), ou este card é destruído. \r\nQuando estiver resolvendo um efeito de card do oponente que escolha este card como alvo, lance um dado de seis faces e negue esse efeito se o resultado for um 3 e, se isso acontecer, destrua esse card. \r\nQualquer dano de batalha que este card causar ao seu oponente é diminuído pela metade.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9608555,'Salamagrande Dragão de Chamas',replace(replace('2 monstros de Nível 4	\r\nSe este card seria destruído em batalha ou por um efeito de card, em vez disso, desassocie 1 matéria dele. \r\nDurante a Fase de Batalha, se este card não tiver matérias (Efeito Rápido): você pode Invocar por Invocação-Especial do seu Deck Adicional, 1 Monstro Xyz "Salamagrande" usando este card com a face para cima que você controla como matéria. \r\n(Isso é considerado uma Invocação-Xyz. Transfira as matérias dele para o monstro Invocado.) \r\nVocê só pode usar este efeito de "Salamagrande Dragão de Chamas" uma vez por turno. \r\nSe este card for Invocado por Invocação-Xyz usando "Salamagrande Dragão de Chamas" como matéria: você pode destruir 1 monstro que seu oponente controla.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9617996,'Crusadia Regulex',replace(replace('2 Monstros de Efeito, incluindo um monstro "Crusadia"	\r\nGanha ATK igual ao ATK original combinado de todos os monstros para os quais este card apontar. \r\nOs monstros para os quais este card apontar não podem atacar. \r\nSe um ou mais Monstros de Efeito forem Invocados por Invocação-Especial em uma ou mais zonas para as quais este card apontar (exceto durante a Etapa de Dano): você pode adicionar 1 Magia/Armadilha "Crusadia" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Crusadia Regulex" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9622164,'D.O.D. - Reencarnação de Outra Dimensão',replace(replace('Descarte 1 card e, depois, escolha 1 dos seus monstros banidos; Invoque-o por Invocação-Especial em Posição de Ataque e equipe-o com este card. \r\nQuando este card deixar o campo, destrua esse monstro.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9627299,'Ichiki Sayori-Hime',replace(replace('Não pode ser Invocado por Invocação-Especial. \r\nUma vez por turno, durante a Fase Final, se este card foi Invocado por Invocação-Normal ou virado com a face para cima neste turno: devolva este card para a mão. \r\nVocê só pode usar cada um dos seguintes efeitos de "Ichiki Sayori-Hime" uma vez por turno. \r\nSe você controlar um monstro com 800 de ATK ou DEF e este card estiver na sua mão: imediatamente depois que este efeito resolver, você pode Invocar este card por Invocação-Normal. \r\nSe este card for Invocado por Invocação-Normal: você pode adicionar 1 monstro de LUZ ou de TREVAS de Nível 4 com 800 de ATK ou DEF do seu Deck à sua mão, exceto "Ichiki Sayori-Hime".','\r',char(13)),'\n',char(10)),'','Invocar','Adicionar à mão','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9627468,'Enorme Colmeia Hegemon - Zexstagger',replace(replace('Ganha 300 de ATK para cada monstro Inseto no campo, exceto este card. \r\nVocê só pode usar cada um dos seguintes efeitos de "Enorme Colmeia Hegemon - Zexstagger" uma vez por turno. \r\nSe um ou mais monstros Inseto forem Invocados por Invocação-Especial (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão. \r\nDurante a Fase Final: ative este efeito; cada duelista pode Invocar por Invocação-Especial 1 monstro Inseto da sua mão ou Cemitério, mas negue seus efeitos.','\r',char(13)),'\n',char(10)),'Invoque este card por Invocação Especial da sua mão','','Invocar por Invocação Especial 1 monstro Inseto?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9628664,'Íris, a Mãe Terra',replace(replace('Depois que um Elo de Corrente 3 ou mais for resolvido, compre 1 card. \r\nVocê não pode ativar este efeito se vários cards/efeitos com o mesmo nome já foram ativados na Corrente.','\r',char(13)),'\n',char(10)),'Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9633505,'Guardião Kay''est',replace(replace('Este card pode ser Invocado, por Invocação-Normal, Invocação-Virar, ou Invocação-Especial apenas quando "Bastão do Silêncio - Kay''est" estiver no seu Campo. \r\nEste card não é afetado por qualquer Card de Magia e não pode ser designado como alvo de um ataque pelos monstros do seu adversário.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9634146,'Guerreiro do Sinal',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nUma vez por turno, durante a Fase de Apoio: coloque 1 Marcador de Sinal em cada card com a face para cima na Zona do Campo e, além disso, coloque 1 neste card. \r\nEste card com um ou mais Marcadores de Sinal não pode ser destruído em batalha ou pelos efeitos de card do seu oponente. \r\nUma vez por turno: você pode remover 4, 7 ou 10 Marcadores de Sinal de qualquer parte do campo; aplique este efeito dependendo do número de Marcadores de Sinal removidos.\r\n● 4: Cause 800 de dano ao seu oponente.\r\n● 7: Compre 1 card.\r\n● 10: Destrua 1 card no campo.','\r',char(13)),'\n',char(10)),'Colocar um marcador','4: Cause 800 de dano ao seu oponente.','7: Compre 1 card.','10: Destrua 1 card no campo.','','','','','','','','','','','','');
INSERT INTO texts VALUES(9637706,'Des Wombato','Você não sofre dano de efeito.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9653271,'Ataque Kaminari','"Ocubeam" + "Mega Esfera de Trovão"','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9659580,'Carma Cúbico',replace(replace('Quando este card for ativado: você pode escolher 1 monstro "Cúbico(a)" que você controla, exceto "Vijam, a Semente Cúbica"; envie qualquer número de "Vijam, a Semente Cúbica" da sua mão e/ou Deck para o Cemitério e, depois, esse monstro ganha 800 de ATK para cada um (mesmo que este card deixe o campo). \r\nDurante o turno do seu oponente, se "Vijam, a Semente Cúbica" for Invocado por Invocação-Especial pelo efeito de um monstro "Cúbico(a)": envie este card para o Cemitério e, se isso acontecer, diminua pela metade os PV do seu oponente. \r\nVocê pode banir este card do seu Cemitério; adicione 1 monstro "Cúbico(a)" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Ativar escolhendo um monstro "Cúbico(a)" como alvo?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9666558,'Dragão Golem','Seu oponente não pode escolher monstros do Tipo Dragão com a face para cima como alvo de ataques, exceto este.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9674034,'Freixo Olho de Cobra',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 monstro de FOGO de Nível 1 do seu Deck à sua mão. \r\nVocê pode enviar 2 cards com a face para cima que você controla para o Cemitério, incluindo este card; Invoque por Invocação-Especial 1 monstro "Olho de Cobra" da sua mão ou do Deck, exceto "Freixo Olho de Cobra". \r\nVocê só pode usar cada efeito de "Freixo Olho de Cobra" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9677699,'Sapatinhos de Cristal',replace(replace('Se este card estiver equipado a um monstro Fada, ele ganha 1000 de ATK. \r\nSe este card estiver equipado a um monstro que não seja Fada, ele não pode atacar e, além disso, ele perde 1000 de ATK. \r\nSe este card for enviado para o Cemitério porque o monstro equipado foi destruído: você pode escolher 1 "Prinzessinha" que você controla; equipe este card no alvo. \r\nVocê só pode usar este efeito de "Sapatinhos de Cristal" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9709452,'Chamas de Gaia, a Força do Sol',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nSe este card atacante destruir um monstro do oponente em batalha: ele pode realizar um segundo ataque em seguida. \r\nUma vez por turno, no final da Fase de Batalha: você pode escolher monstros de FOGO no seu Cemitério até o número de monstros que este card destruiu em batalha neste turno; adicione-os à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9715126,'Ordem de Inicialização - Força do Mecanismo','Quando um monstro de qualquer duelista declarar um ataque e todos os monstros que você controla forem monstros Máquina com a face para cima (mín. 1): destrua monstros em Posição de Ataque que seu oponente controla, até o número de monstros Máquina que você controla.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9718968,'Matador de Fóton','Se houver um Monstro Xyz com a face para cima no campo, você pode Invocar este card por Invocação-Especial (da sua mão) com a face para cima em Posição de Defesa.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9720537,'Selo do Dono','Devolva o controle de todos os monstros no campo para seus donos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9726840,'Força Celeste - Mobilizar - Conexão!','Se você não controlar nenhum monstro na sua Zona de Monstros Principal: você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno depois que este card resolver, exceto monstros "Força Celeste - Ás" e, além disso, envie 1 outro card que você controla para o Cemitério e, se isso acontecer, Invoque por Invocação-Especial na Zona de Monstros Adicional, 1 monstro "Força Celeste - Ás" do seu Deck Adicional e, se você tiver pelo menos 1 monstro "Força Celeste - Ás" de LUZ e 1 de TREVAS no seu campo e/ou no seu Cemitério, o monstro Invocado ganha 1000 de ATK.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9742784,'Jato Sincron',replace(replace('Se este card for enviado para o Cemitério como Matéria Sincro: você pode adicionar 1 monstro "Sucata" do seu Deck à sua mão. \r\nSe este card estiver no seu Cemitério: você pode enviar 1 card da sua mão para o Cemitério; Invoque este card por Invocação-Especial, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar 1 efeito de "Jato Sincron" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Procurar no Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9744376,'Boa Gestão Caseira dos Goblins','Compre o número de "Boa Gestão Caseira dos Goblins" no seu Cemitério + 1 card do seu Deck, escolha 1 card da sua mão e devolva-o para o fundo do seu Deck.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9748752,'Caius, o Monarca das Sombras','Se este card for Invocado por Invocação-Tributo: escolha 1 card no campo; bana o alvo e, se isso acontecer, cause 1000 de dano ao seu oponente se for um monstro de TREVAS.','Banir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9753964,'Abrasador Dragão Vermelho Arquidemônio do Abismo',replace(replace('1 Regulador + 1 Monstro Sincro Dragão não-Regulador de TREVAS	\r\n(Efeito Rápido): você pode escolher 1 card com a face para cima que seu oponente controla; negue seus efeitos até o final deste turno. \r\nQuando este card causar dano de batalha ao seu oponente: você pode escolher 1 Regulador no seu Cemitério; Invoque-o por Invocação-Especial em Posição de Defesa. \r\nVocê só pode usar cada efeito de "Abrasador Dragão Vermelho Arquidemônio do Abismo" uma vez por turno.','\r',char(13)),'\n',char(10)),'Negar o efeito','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9763474,'Lagartose Abatido',replace(replace('2 monstros com nomes diferentes	\r\nVocê pode banir 1 monstro do seu campo com a face para cima ou Cemitério com 2000 ou menos de ATK e, depois, escolha 1 monstro com a face para cima no campo; faça com que o ATK dele se torne igual ao ATK original do monstro banido para ativar este efeito (até o final deste turno) e, depois, se você baniu um monstro que era originalmente um Réptil, compre 1 card. \r\nVocê só pode usar este efeito de "Lagartose Abatido" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9765723,'Pacto Obscuro com a Bruxa',replace(replace('Você pode enviar 1 card "D/D" ou "Pacto Obscuro" da sua mão para o Cemitério e, depois, escolher 1 card no campo; destrua-o. \r\nVocê só pode usar este efeito de "Pacto Obscuro com a Bruxa" uma vez por turno. \r\nTodos os monstros do Tipo Demônio que você controla ganham 1000 de ATK, apenas durante o turno do seu oponente. \r\nUma vez por turno, durante sua Fase de Apoio: sofra 1000 de dano.','\r',char(13)),'\n',char(10)),'Destruir 1 card','Receber dano','Usar o efeito?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9780364,'Doma de Gladiador',replace(replace('Se um monstro "Besta Gladiadora" com a face para cima estiver no campo, ative 1 desses efeitos:\r\n● Selecione 1 monstro com a face para cima que seu oponente controla e mude sua posição de batalha.\r\n● Selecione 1 monstro "Besta Gladiadora" com a face para cima que seu oponente controla e tome o controle dele até a Fase Final.','\r',char(13)),'\n',char(10)),'Alterar posição de batalha','Tome o controle','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9785661,'Azamina Sol Erysichthon',replace(replace('1 monstro Ilusão + 1 monstro Demônio	\r\nSe este card for Invocado por Invocação-Fusão: você pode escolher 1 card no campo; envie-o para o Cemitério. \r\nDurante a Fase de Apoio: você pode escolher 1 card "Azamina" ou "Despojos do Pecado" no seu Cemitério; adicione-o à sua mão. \r\nVocê só pode usar cada efeito de "Azamina Sol Erysichthon" uma vez por turno.','\r',char(13)),'\n',char(10)),'Enviar para o Cemitério','Retornar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9786492,'Ritual do Dragão Branco',replace(replace('Este card é usado para a Invocação-Ritual de "Paladino do Dragão Branco". \r\nVocê também deve oferecer como Tributo monstros da sua mão ou do campo cuja soma dos Níveis seja igual ou maior que 4.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9791914,'Sentinela de Prata',replace(replace('Você pode Baixar este card da sua mão na sua Zona de Cards de Magia & Armadilha como um Card de Magia. \r\nDurante a Fase Final do turno em que este card Baixado na sua Zona de Cards de Magia & Armadilha foi destruído por um efeito de card do oponente e enviado ao Cemitério: Escolha 1 card que seu oponente controla (se possível); Invoque este card por Invocação-Especial do Cemitério e, se isso acontecer, destrua o alvo (se houver).','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9794980,'Cavaleira do Pesadelo Encarnação Idlee',replace(replace('Monstros de Nível 9 que você controla não podem ser destruído por efeitos de card. \r\nVocê só pode usar cada um dos seguintes efeitos de "Cavaleira do Pesadelo Encarnação Idlee" uma vez por turno.\r\n● Se a soma dos Valores Link dos monstros no campo for 8 ou mais (Efeito Rápido): você pode Invocar este card por Invocação-Especial da sua mão.\r\n● Se este card for Invocado por Invocação-Especial, enquanto seu oponente controlar mais Monstros Link que você: você pode enviar para o Cemitério todos os Monstros Link no campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9798352,'Prufinesse, o Caçador Tático',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode banir 1 Armadilha do seu Deck; aumente em 1 o Nível deste card. \r\nVocê pode escolher 1 Armadilha em qualquer Cemitério; bana-a e, se isso acontecer, aumente em 1 o Nível deste card. \r\nSe este card em posse do seu dono for destruído por um card do oponente: você pode Baixar 1 das suas Armadilhas Normais banidas. \r\nVocê só pode usar cada efeito de "Prufinesse, o Caçador Tático" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9817927,'Panda Gyaku-Gire',replace(replace('O ATK deste card aumenta em 500 pontos por cada monstro no Campo do seu adversário. \r\nQuando este card ataca com um ATK superior ao DEF do monstro em Posição de Defesa, inflija a diferença como dano de batalha aos Life Points do seu adversário.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9822220,'Senhor da Prisão Celestial',replace(replace('Durante sua Fase Principal: você pode ativar este efeito; este card na sua mão se torna revelado até o final do turno do seu oponente. \r\nEnquanto este card estiver revelado por este efeito, cards Baixados no campo não podem ser destruídos por efeitos de card. \r\nSe um Card de Magia/Armadilha Baixado for ativado (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão e, depois, se você ativou este efeito enquanto este card estava revelado, você pode revelar e Baixar 1 Magia/Armadilha do seu Deck, mas bana-a durante a Fase Final do próximo turno. \r\nVocê só pode usar 1 efeito de "Senhor da Prisão Celestial" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','Invoque este card por Invocação Especial da sua mão','Baixar 1 Card de Magia/Armadilha do seu Deck?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9831539,'Portal de Tannhauser','Escolha 2 monstros do mesmo Tipo que você controla com ATK 1000 ou menos; os Níveis dos dois monstros se tornam iguais aos Níveis combinados desses 2 monstros.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9837195,'Musto, Oráculo de Gusto','Uma vez por turno: Você pode escolher 1 monstro "Gusto" no seu Cemitério e 1 monstro com a face para cima no campo; embaralhe o primeiro alvo no Deck e, se isso acontecer, negue os efeitos do segundo alvo até a Fase Final.','Negar efeitos','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9839115,'Vagnawa, o Dragão Devorador de Luas',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro: você pode ativar este efeito; este card ganha 300 de ATK para cada Nível que tinham os não-Reguladores usados e, depois, cause 300 de dano ao seu oponente para cada Nível que tinha o Regulador usado. \r\nO aumento de ATK dura até o final do próximo turno. \r\nVocê só pode usar este efeito de "Vagnawa, o Dragão Devorador de Luas" uma vez por turno.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9839945,'Lyna, a Encantadora da Luz, Lustrosa',replace(replace('2 monstros, incluindo um monstro de LUZ	\r\n(Este card deve ser sempre considerado como um card "Espírito-Possuído".)	\r\nVocê pode escolher 1 monstro de LUZ no Cemitério do seu oponente; Invoque-o por Invocação-Especial em uma zona sua para a qual este card apontar. \r\nSe este card Invocado por Invocação-Link for destruído em batalha, ou for destruído por um efeito de card do oponente enquanto estiver na Zona de Monstros do seu dono: você pode adicionar 1 monstro de LUZ com 1500 ou menos de DEF do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "Lyna, a Encantadora da Luz, Lustrosa" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9845733,'Emblema do Despertar',replace(replace('Este card é usado para a Invocação-Ritual de "Chulainn, o Desperto". \r\nVocê também deve oferecer como Tributo monstros da sua mão ou campo cuja soma dos Níveis seja igual a 4 ou mais.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9848939,'Arqueiro da Floresta',replace(replace('Este card não pode ser Invocado por Invocação-Normal ou Baixado. \r\nEste card não pode ser Invocado por Invocação-Especial, exceto ao ter 2 ou mais Monstros Normais no seu Cemitério. \r\nVocê pode oferecer este card como Tributo para adicionar 1 monstro Gêmeos do seu Deck para a sua mão.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9852718,'Libertar-se','Durante a Fase de Batalha do seu oponente: envie 1 Magia da sua mão para o Cemitério; encerre a Fase de Batalha e, depois, os monstros com a face para cima atualmente no campo têm seus efeitos negados até o final deste turno.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9861795,'Toupeirinha',replace(replace('Quando este card no campo for destruído e enviado para o Cemitério: você pode Invocá-lo por Invocação-Especial do seu Cemitério com a face para cima em Posição de Defesa. \r\nVocê só pode usar o efeito de "Toupeirinha" uma vez por Duelo.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9888196,'Armadura Decisiva, Aliado da Justiça',replace(replace('1 Regulador + 2+ monstros não-Reguladores	\r\nUma vez por turno, se seu oponente controlar um monstro de LUZ: você pode ativar 1 desses efeitos.\r\n● Escolha 1 card Baixado que seu oponente controla; destrua o alvo.\r\n● Envie 1 card da sua mão para o Cemitério; destrua todas as Magias e Armadilhas que seu oponente controla.\r\n● Envie toda a sua mão para o Cemitério; olhe a mão do seu oponente e envie todos os monstros de LUZ na mão dele para o Cemitério e, depois, cause dano ao seu oponente igual ao ATK total desses monstros enviados para o Cemitério.','\r',char(13)),'\n',char(10)),'Destrua 1 card Baixado no campo do seu oponente','Destrua todos os Cards de Magia/Armadilha no campo do seu oponente','Envie para o Cemitério todos os monstros de LUZ na mão do seu oponente','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9897998,'Condor Gusto','Quando este card destruir um monstro do oponente em batalha e enviá-lo ao Cemitério: Você pode Invocar por Invocação-Especial 1 monstro de VENTO do Tipo Psíquico com 1500 ou menos de DEF do seu Deck.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9910360,'Sapo D.3.S.',replace(replace('"Sapo Des" + "Sapo Des" + "Sapo Des"	\r\nA Invocação-Fusão deste card só pode ser conduzida com os Monstros-Matéria de Fusão acima. \r\nEste card ganha 500 de ATK para cada "Sapo Arbóreo" no seu Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9925982,'Vingança da Asa Negra','Quando um monstro Besta Alada que você controla for destruído em batalha e enviado para o Cemitério: Invoque por Invocação-Especial 2 "Fichas Asanegra - Crista Negra" (Besta Alada/TREVAS/Nível 2/ATK 0/DEF 800).','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9925983,'Ficha Asanegra - Crista Negra','Invocado por Especial com o efeito "Vingança da Asa Negra".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9929398,'Asanegra - Gofu, a Sombra Oscilante',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro deve ser Invocado por Invocação-Especial (da sua mão) enquanto você não controlar nenhum monstro. \r\nQuando este card for Invocado por Invocação-Especial da mão: você pode Invocar por Invocação-Especial 2 "Fichas de Sombra Oscilante" (Tipo Besta Alada/TREVAS/Nível 1/ATK 0/DEF 0), mas elas não podem ser oferecidos como Tributo ou usadas como Matérias Sincro. \r\nVocê pode banir este card e 1 ou mais não-Reguladores com a face para cima que você controla e, depois, escolher 1 Monstro Sincro "Asanegra" no seu Cemitério cujo Nível seja igual à soma dos Níveis que os monstros banidos tinham no campo; Invoque-o por Invocação-Especial e, se isso acontecer, ele é considerado como um Regulador.','\r',char(13)),'\n',char(10)),'Invocar uma Ficha por Invocação Especial','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9929399,'Ficha de Sombra Oscilante','Invocada por Invocação-Especial com o efeito "Asanegra - Gofu, a Sombra Oscilante".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9940036,'Agregator Mereológico',replace(replace('2+ monstros de Nível 9	\r\nSe este card for Invocado por Invocação-Xyz: você pode enviar 1 monstro do seu Deck Adicional para o Cemitério. \r\nVocê pode escolher monstros no seu Cemitério, até o número de matérias que este card tiver; desassocie matérias deste card igual ao número desses alvos no Cemitério e, se isso acontecer, associe esses alvos a este card. \r\nSe este card for enviado para o Cemitério: você pode escolher 1 card com a face para cima no campo; negue seus efeitos até o final deste turno. \r\nVocê só pode usar cada efeito de "Agregator Mereológico" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9952083,'Corrente de Invocação',replace(replace('Ative como um Elo de Corrente 3 ou mais: você pode conduzir até 3 Invocações-Normal/Baixar neste turno, não apenas 1. \r\nVocê não pode ativar este card se múltiplos cards com o mesmo nome, ou o efeito desses cards, já estiverem ativados nessa Corrente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9978697,'Sabre-X Pellina',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode enviá-lo para o Cemitério; Invoque por Invocação-Especial 2 monstros "Sabre-X" do seu Deck, exceto "Sabre-X Pellina", mas destrua-os durante a Fase Final. \r\nSe este card for enviado para o Cemitério como Matéria Sincro para um monstro "Sabre-X": você pode aplicar 1 desses efeitos.\r\n● Esse monstro pode realizar um segundo ataque durante cada Fase de Batalha.\r\n● Esse monstro pode atacar diretamente.	\r\nVocê só pode usar cada efeito de "Sabre-X Pellina" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Conceder um efeito','Atacar duas vezes','Ataque direto','Pode atacar 2 vezes','Pode atacar diretamente','','','','','','','','','','');
INSERT INTO texts VALUES(9989792,'Fortaleza Triâmide',replace(replace('Todos os monstros do Tipo Rocha no campo ganham 500 de DEF. \r\nMonstros "Triâmide" no campo não podem ser destruídos por efeitos de card. \r\nSe este card com a face para cima na Zona do Campo for enviado para o Cemitério: você pode escolher 1 monstro "Triâmide" no seu Cemitério; adicione-o à sua mão. \r\nVocê só pode usar este efeito de "Fortaleza Triâmide" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9995766,'Costume Imperial',replace(replace('Armadilhas Contínuas com a face para cima não podem ser destruídas em batalha ou por um efeito de card, exceto "Costume Imperial". \r\nVocê só pode controlar 1 "Costume Imperial".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(9999961,'Fúria da Besta','Todos os monstros que você controla ganham 200 de ATK para cada um dos seus monstros do Tipo Besta e do Tipo Besta Alada removidos de jogo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10000000,'Obelisco, o Atormentador',replace(replace('Requer 3 Tributos para ser Invocado por Invocação-Normal (não pode ser Baixado Normalmente). \r\nA Invocação-Normal deste card não pode ser negada. \r\nQuando Invocado por Invocação-Normal, cards e efeitos não podem ser ativados. \r\nNenhum duelista pode escolher este card como alvo de efeitos de card. \r\nUma vez por turno, durante a Fase Final, se este card foi Invocado por Invocação-Especial: envie-o para o Cemitério. \r\nVocê pode oferecer 2 monstros como Tributo; destrua todos os monstros que seu oponente controla. \r\nEste card não pode declarar um ataque no turno em que este efeito for ativado.','\r',char(13)),'\n',char(10)),'Enviar para o Cemitério','Destrua todos os monstros do seu oponente','Ofereça 3 monstros como Tributo para Invocar','','','','','','','','','','','','','');
