INSERT INTO texts VALUES(10000010,'O Dragão Alado de Rá',replace(replace('Não pode ser Invocado por Invocação-Especial. \r\nRequer 3 Tributos para ser Invocado por Invocação-Normal (não pode ser Baixado Normalmente). \r\nA Invocação-Normal deste card não pode ser negada. \r\nQuando Invocado por Invocação-Normal, outros cards e efeitos não podem ser ativados. \r\nQuando este card for Invocado por Invocação-Normal: você pode pagar PV até restarem apenas 100; este card ganha ATK/DEF igual aos PV pagos. \r\nVocê pode pagar 1000 PV e, depois, escolha 1 monstro no campo; destrua o alvo.','\r',char(13)),'\n',char(10)),'Aumentar ATK/DEF','Destruir','Ofereça 3 monstros como Tributo para Invocar','','','','','','','','','','','','','');
