INSERT INTO texts VALUES(10000022,'Slifer, o Dragão Celeste',replace(replace('Requer 3 Tributos para ser Invocado por Invocação-Normal (não pode ser Baixado Normalmente). \r\nA Invocação-Normal deste card não pode ser negada. \r\nQuando Invocado por Invocação-Normal, cards e efeitos não podem ser ativados. \r\nUma vez por turno, durante a Fase Final, se este card foi Invocado por Invocação-Especial: envie-o para o Cemitério. \r\nGanha 1000 de ATK/DEF para cada card na sua mão. \r\nSe um ou mais monstros forem Invocados por Invocação-Normal ou Especial no campo do seu oponente em Posição de Ataque: esses monstros perdem 2000 de ATK e, depois, se algum deles tiver o ATK reduzido a 0 como resultado, destrua-o.','\r',char(13)),'\n',char(10)),'Enviar para o Cemitério','Reduzir ATK','Ofereça 3 monstros como Tributo para Invocar','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10000023,'Slifer, o Dragão Celeste',replace(replace('Requer 3 Tributos para ser Invocado por Invocação-Normal (não pode ser Baixado Normalmente). \r\nA Invocação-Normal deste card não pode ser negada. \r\nQuando Invocado por Invocação-Normal, cards e efeitos não podem ser ativados. \r\nUma vez por turno, durante a Fase Final, se este card foi Invocado por Invocação-Especial: envie-o para o Cemitério. \r\nGanha 1000 de ATK/DEF para cada card na sua mão. \r\nSe um ou mais monstros forem Invocados por Invocação-Normal ou Especial no campo do seu oponente em Posição de Ataque: esses monstros perdem 2000 de ATK e, depois, se algum deles tiver o ATK reduzido a 0 como resultado, destrua-o.','\r',char(13)),'\n',char(10)),'Enviar para o Cemitério','Reduzir ATK','Ofereça 3 monstros como Tributo para Invocar','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10000024,'Slifer, o Dragão Celeste',replace(replace('Requer 3 Tributos para ser Invocado por Invocação-Normal (não pode ser Baixado Normalmente). \r\nA Invocação-Normal deste card não pode ser negada. \r\nQuando Invocado por Invocação-Normal, cards e efeitos não podem ser ativados. \r\nUma vez por turno, durante a Fase Final, se este card foi Invocado por Invocação-Especial: envie-o para o Cemitério. \r\nGanha 1000 de ATK/DEF para cada card na sua mão. \r\nSe um ou mais monstros forem Invocados por Invocação-Normal ou Especial no campo do seu oponente em Posição de Ataque: esses monstros perdem 2000 de ATK e, depois, se algum deles tiver o ATK reduzido a 0 como resultado, destrua-o.','\r',char(13)),'\n',char(10)),'Enviar para o Cemitério','Reduzir ATK','Ofereça 3 monstros como Tributo para Invocar','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10000025,'Slifer, o Dragão Celeste',replace(replace('Requer 3 Tributos para ser Invocado por Invocação-Normal (não pode ser Baixado Normalmente). \r\nA Invocação-Normal deste card não pode ser negada. \r\nQuando Invocado por Invocação-Normal, cards e efeitos não podem ser ativados. \r\nUma vez por turno, durante a Fase Final, se este card foi Invocado por Invocação-Especial: envie-o para o Cemitério. \r\nGanha 1000 de ATK/DEF para cada card na sua mão. \r\nSe um ou mais monstros forem Invocados por Invocação-Normal ou Especial no campo do seu oponente em Posição de Ataque: esses monstros perdem 2000 de ATK e, depois, se algum deles tiver o ATK reduzido a 0 como resultado, destrua-o.','\r',char(13)),'\n',char(10)),'Enviar para o Cemitério','Reduzir ATK','Ofereça 3 monstros como Tributo para Invocar','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10000030,'Magi Magi ☆ Maga Gal',replace(replace('2 monstros do Tipo Mago de Nível 6	\r\nUma vez por turno: Você pode desanexar 1 Material Xyz deste card e banir 1 card da sua mão; ative 1 destes efeitos.\r\n● Escolha 1 monstro que seu oponente controla; tome o controle dele até a Fase Final.\r\n● Escolha 1 monstro no Cemitério do seu oponente; Invoque-o por Invocação-Especial para o seu lado do campo.','\r',char(13)),'\n',char(10)),'Ativar 1 efeito','Ganhe o controle de 1 monstro no campo do seu oponente','Invoque por Invocação Especial 1 monstro do Cemitério do seu oponente','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10000040,'Holactie, a Criadora da Luz',replace(replace('Não pode ser Invocado Normalmente/Colocado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao Tributar 3 monstros cujos nomes originais sejam "Slifer, o Dragão Celeste", "Obelisco, o Atormentador" e "O Dragão Alado de Rá", e não pode ser Invocado por outros meios. \r\nA Invocação-Especial deste card não pode ser negada. \r\nO jogador que Invocar este card por Invocação-Especial vence o Duelo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10000080,'O Dragão Alado de Rá - Modo Esfera',replace(replace('Não pode ser Invocado por Invocação-Especial. \r\nRequer 3 Tributos de qualquer lado do campo para ser Invocado por Invocação-Normal do lado do campo em questão (não pode ser Baixado Normalmente) e, depois, mude o controle para o dono deste card durante a Fase Final do próximo turno. \r\nNão pode atacar. \r\nSeu oponente não pode escolher este card como alvo de ataques ou efeitos de card. \r\nVocê pode oferecer este card como Tributo; Invoque por Invocação-Especial 1 "O Dragão Alado de Rá" da sua mão ou do Deck, ignorando suas condições de Invocação e, se isso acontecer, o ATK/DEF dele se tornam 4000.','\r',char(13)),'\n',char(10)),'Invocar no seu campo','Invocar no campo do seu oponente','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10000090,'Dragão Alado de Rá - Fênix',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial por seu próprio efeito. \r\nSe "O Dragão Alado de Rá" for enviado do campo para o seu Cemitério enquanto este card estiver no seu Cemitério: Invoque este card por Invocação-Especial. \r\nCards e efeitos não podem ser ativados em resposta à ativação deste efeito. \r\nNão é afetado por outros efeitos de card. \r\nVocê pode pagar 1000 PV; envie 1 monstro do campo para o Cemitério. \r\nUma vez por turno, durante a Fase Final: envie este card para o Cemitério e, se isso acontecer, Invoque por Invocação-Especial 1 "O Dragão Alado de Rá - Modo Esfera" da sua mão, do Deck ou do Cemitério, ignorando suas condições de Invocação.','\r',char(13)),'\n',char(10)),'Invocar este card por Invocação Especial','Envie para o Cemitério 1 monstro no campo','Invoque por Invocação Especial 1 "O Dragão Alado de Rá - Modo Esfera"','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10002346,'Gachi Gachi Gantetsu',replace(replace('2 monstros de Nível 2	\r\nSe este card com a face para cima seria destruído, em vez disso, você pode desassociar 1 Matéria Xyz deste card. \r\nMonstros com a face para cima que você controla ganham 200 de ATK e DEF para cada Matéria Xyz associada a este card.','\r',char(13)),'\n',char(10)),'Usar o efeito de "Gachi Gachi Gantetsu" em vez de ser destruído?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10004783,'Libertação Cristalina',replace(replace('Só pode ser equipado a um monstro "Fera Cristalina". \r\nEle ganha 800 de ATK. \r\nQuando este card for enviado do campo para o Cemitério: você pode colocar 1 monstro "Fera Cristalina" do seu Deck com a face para cima na sua Zona de Magias & Armadilhas como uma Magia Contínua.','\r',char(13)),'\n',char(10)),'Coloque "Fera Cristalina" na sua Zona de Magia e Armadilha','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10012614,'Estandarte da Coragem','Apenas durante sua Fase de Batalha, todos os monstros que você controla ganham 200 de ATK.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10019086,'Bucephalus II, Armas da Tri-Brigada',replace(replace('3+ monstros Besta, Besta-Guerreira e/ou Besta Alada	\r\nNão pode ser Invocado por Invocação-Especial do Deck Adicional a não ser que você tenha 3 ou mais Magias/Armadilhas "Tri-Brigada" no seu Cemitério. \r\nSeu oponente não pode ativar cards ou efeitos quando você Invocar um ou mais monstros por Invocação-Especial. \r\nQuando um monstro declarar um ataque: você pode banir este card e, além disso, bana todos os cards que seu oponente controla. \r\nSe este card for enviado para o Cemitério: você pode enviar 1 monstro Besta, Besta-Guerreira ou Besta Alada do seu Deck Adicional para o Cemitério. \r\nVocê só pode usar este efeito de "Bucephalus II, Armas da Tri-Brigada" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10024317,'Parametalmorfose Melcaster',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno: você pode escolher 1 outro card com a face para cima que você controla; destrua-o e, se isso acontecer, Baixe 1 Magia/Armadilha "Metalmorfose" diretamente do seu Deck.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe este card no campo for destruído em batalha ou por um efeito de card: você pode adicionar 1 Monstro Pêndulo "Metalmorfose" com a face para cima do seu Deck Adicional à sua mão, exceto "Parametalmorfose Melcaster", mas você não pode ativá-lo, ou cards com o mesmo nome, para colocá-lo nas Zonas de Pêndulo, pelo resto deste turno, exceto por efeitos de card. \r\nVocê só pode usar este efeito de "Parametalmorfose Melcaster" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10026986,'Rei Lombriga',replace(replace('Este card pode ser Invocado por Invocação-Tributo com a face para cima em Posição de Ataque ao oferecer como Tributo 1 monstro "Lombriga" do Tipo Réptil. \r\nVocê pode oferecer como Tributo 1 monstro "Lombriga" do Tipo Réptil para selecionar 1 card que seu oponente controla e destruí-lo.','\r',char(13)),'\n',char(10)),'Ofereça 1 monstro como Tributo para Invocar por Tributo','Destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10028593,'Tengu Renascido','Se este card com a face para cima deixar o campo: Invoque por Invocação-Especial 1 "Tengu Renascido" do seu Deck.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10032958,'Dragão Divino - Excelion',replace(replace('Quando este card for Invocado por Invocação-Normal, ele ganha 1 dos efeitos a seguir para cada "Dragão Divino - Excelion" no seu Cemitério quando este efeito resolver (você escolhe). \r\nEstes efeitos não são cumulativos.\r\n● Este card ganha 1000 de ATK.\r\n● Se este card destruir um monstro do oponente em batalha, ele pode atacar mais uma vez, em sequência.\r\n● Quando este card destruir um monstro em batalha e enviá-lo ao Cemitério, cause dano ao oponente igual ao ATK do monstro destruído.','\r',char(13)),'\n',char(10)),'Ganhar um efeito','Aumentar ATK em 1000','Se você destruir um monstro do seu oponente em batalha, você pode realizar 1 ataque adicional','Quando um monstro for destruído em batalha e enviado para o Cemitério, cause dano ao seu oponente igual ao ATK daquele monstro','','','','','','','','','','','','');
INSERT INTO texts VALUES(10035717,'Mudança de Arma','Uma vez durante cada uma das suas Fases de Apoio: você pode pagar 700 PV e, depois, escolha 1 monstro Guerreiro ou Máquina que você controla; até o final do próximo turno do seu oponente, troque o ATK atual pela DEF atual do alvo, e vice-versa.','Trocar ATK e DEF','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10040267,'Máquina Fóssil Buggy Caveira',replace(replace('1 monstro Rocha no seu Cemitério + 1 monstro de Nível 4 ou menos	\r\nPrimeiro deve ser Invocado por Invocação-Especial com "Fusão Fóssil". \r\nQuando este card destruir um monstro do oponente em batalha: você pode causar 600 de dano ao seu oponente. \r\nVocê pode banir este card do seu Cemitério; adicione 1 monstro do seu Deck à sua mão que mencione "Fusão Fóssil". \r\nVocê só pode usar este efeito de "Máquina Fóssil Buggy Caveira" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10045474,'Impermanência Infinita',replace(replace('Escolha 1 monstro com a face para cima que seu oponente controla; negue seus efeitos (até o final deste turno) e, depois, se este card estava Baixado antes da ativação e estiver no campo na resolução, pelo resto deste turno, todos os outros efeitos de Magia/Armadilha nesta coluna são negados. \r\nSe você não controlar nenhum card, você pode ativar este card da sua mão.','\r',char(13)),'\n',char(10)),'Ativar aplicando o efeito de "Impermanência Infinita".','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10045475,'Impermanência Infinita',replace(replace('Escolha 1 monstro com a face para cima que seu oponente controla; negue seus efeitos (até o final deste turno) e, depois, se este card estava Baixado antes da ativação e estiver no campo na resolução, pelo resto deste turno, todos os outros efeitos de Magia/Armadilha nesta coluna são negados. \r\nSe você não controlar nenhum card, você pode ativar este card da sua mão.','\r',char(13)),'\n',char(10)),'Ativar aplicando o efeito de "Impermanência Infinita".','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10060427,'Senhor da Torre Koa''ki Meiru',replace(replace('Durante cada uma das suas Fases Finais, destrua este card a não ser que você envie 1 "Núcleo de Ferro de Koa''ki Meiru" da sua mão ao Cemitério ou revele 1 monstro do Tipo Guerreiro na sua mão. \r\nVocê pode Invocar este card por Invocação-Tributo ao oferecer como Tributo 1 monstro "Koa''ki Meiru". \r\nQuando este card for Invocado por Invocação-Normal, você pode remover de jogo 1 card "Koa''ki Meiru" no seu Cemitério para destruir até 2 cards que seu oponente controla.','\r',char(13)),'\n',char(10)),'Escolha 1 "Núcleo de Ferro de Koa''ki Meiru" para enviar para o Cemitério','Revele 1 monstro Guerreiro ao seu oponente','Destruir "Senhor da Torre Koa''ki Meiru"','Ofereça 1 monstro "Koa''ki Meiru" como Tributo para Invocar por Tributo','Destruir','','','','','','','','','','','');
INSERT INTO texts VALUES(10065487,'Perda do Marcado',replace(replace('Escolha 1 monstro que seu oponente controla que foi Invocado por Invocação-Especial do Deck Adicional e 1 Monstro de Fusão que você controla; embaralhe-os no(s) \r\nDeck(s) e, além disso, durante a Fase Final deste turno, cada duelista pode Invocar por Invocação-Especial 1 Monstro de Fusão que mencione "Caído de Arbaz" como matéria do seu próprio Deck Adicional. \r\nVocê só pode ativar 1 "Perda do Marcado" por turno.','\r',char(13)),'\n',char(10)),'Retornar ao Deck','Invocar por Invocação Especial um Monstro Fusão que usou "Caído de Arbaz" como Matéria de Fusão?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10069180,'Estatuto Pára-Magias',replace(replace('Você pode ativar este card apenas quando o seu adversário ativa um Card de Magia Contínua. \r\nAnule a ativação e o efeito do card e destrua-o.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10071151,'Lyla, a Bruxa Crepúsculo Luminosa',replace(replace('Uma vez por turno, quando um Card ou efeito de Magia/Armadilha for ativado (Efeito Rápido): você pode banir 1 monstro "Luminoso(a)" da sua mão ou do Cemitério e, depois, escolher 1 Magia/Armadilha com a face para cima no campo; destrua-a. \r\nUma vez por turno, se o efeito de outro monstro "Luminoso(a)" seu for ativado: envie os 3 cards do topo do seu Deck para o Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10071456,'Protetora do Trono','Enquanto o rei está ausente, esta rainha protege seu trono com uma defesa vigorosa.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10080320,'Mundo Jurássico','Todos os monstros do Tipo Dinossauro ganham 300 de ATK e DEF.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10086952,'Invocação Rápida',replace(replace('Imediatamente após ativar este efeito, Invoque por Invocação-Normal/Baixe 1 monstros. \r\nQuando você o faz dessa forma, se seu oponente controla um monstro, você pode Invocar por Invocação-Normal um monstro de Nível 5 ou maior sem Tributo.\r\nDurante sua Fase Principal, se este card está no seu Cemitério, exceto no turno que foi enviado para lá: você pode bani-lo; adicione 1 monstro de Nível 5 ou maior do seu Deck ou Cemitério à sua mão que possa ser Invocado por Invocação-Normal/Baixado, então imediatamente após a ativação desse efeito, Invoque-o por Invocação-Tributo. \r\nVocê só pode usar este efeito de "Invocação Rápida" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar','Adicionar à mão','Aplicar o efeito de "Invocação Rápida" para Invocar sem oferecer Tributo?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10097168,'Dragão Tigre','Quando este card for Invocado por Invocação-Tributo pelo Tributo de um monstro Dragão: você pode escolher até 2 cards Baixados na Zona de Magias & Armadilhas do seu oponente; destrua os alvos.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10110717,'Mecalebre',replace(replace('Quando este card for virado com a face para cima, selecione 1 card no campo e cause 500 de dano ao seu controlador. \r\nQuando este card for destruído em batalha e enviado ao Cemitério, você pode Invocar por Invocação-Especial 1 "Mecalebre" do seu Deck com a face para baixo em Posição de Defesa.','\r',char(13)),'\n',char(10)),'Invocação Especial','Causar dano','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10113611,'Wattum',replace(replace('Este card pode atacar diretamente. \r\nVocê só pode usar cada um dos seguintes efeitos de "Wattum" uma vez por turno. \r\nNo final da Etapa de Dano, se um monstro seu causar dano de batalha ao seu oponente: você pode Invocar este card por Invocação-Especial da sua mão. \r\nQuando este card causar dano de batalha ao seu oponente em um ataque direto: você pode oferecer como Tributo este card no campo e 1 ou mais monstros não-Reguladores da sua mão e/ou do campo com a face para cima e Invocar por Invocação-Especial 1 Monstro Sincro "Watt" do seu Deck Adicional cujo Nível seja igual à soma dos Níveis desses monstros oferecidos como Tributo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10117149,'Robô-secretário 005',replace(replace('Escala de Pêndulo = 10\r\n[ Efeito de Pêndulo ]\r\nVocê não pode Invocar monstros por Invocação-Pêndulo, exceto monstros "Robô-secretário". \r\nEste efeito não pode ser negado.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 Card de Magia/Armadilha no campo; destrua-o. \r\nEste card ganha 500 de ATK para cada monstro "Robô-secretário" com a face para cima no seu Deck Adicional. \r\nSe este card na sua Zona de Pêndulo for destruído: você pode escolher 1 monstro "Robô-secretário" no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê só pode usar este efeito de "Robô-secretário 005" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10118318,'Verdade Reforçada',replace(replace('Invoque por Invocação-Especial 1 monstro Guerreiro de Nível 2 ou menos do seu Deck. \r\nVocê não pode conduzir sua Fase de Batalha no turno em que ativar este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10125011,'Cavaleirostrelas Constelares',replace(replace('Quando este card for ativado: você pode Invocar por Invocação-Especial 1 monstro "Cavaleirost" ou "Constelar" da sua mão ou do Cemitério. \r\nVocê pode escolher 1 Monstro Xyz "Cavaleirost" ou "Constelar" que você controla; Invoque por Invocação-Especial do seu Deck Adicional, 1 Monstro Xyz "Cavaleirost" ou "Constelar" com uma Classe diferente, usando esse Monstro Xyz que você controla como matéria (isso é considerado uma Invocação-Xyz, transfira as matérias dele). \r\nVocê só pode usar este efeito de "Cavaleirostrelas Constelares" uma vez por turno. \r\nVocê só pode ativar 1 "Cavaleirostrelas Constelares" por turno.','\r',char(13)),'\n',char(10)),'Escolher um monstro para Invocá-lo por Invocação Especial?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10131855,'Lavagem Cerebral do Mundo Negro','Quando seu oponente ativar um efeito de monstro, se você tiver 3 ou mais cards na sua mão (exceto durante a Etapa de Dano): você pode escolher 1 monstro "Mundo Negro" no campo; devolva-o para a mão e, se isso acontecer, o efeito ativado se torna "Seu oponente descarta 1 card aleatório".','Ativar, mas não resolver o efeito','Altere o efeito do seu oponente','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10132124,'Tartalada',replace(replace('Quando um ou mais monstros do Tipo Peixe, Serpente Marinha ou Aqua com a face para cima que você controla forem banidos: Você pode Invocar este card por Invocação-Especial da sua mão ou Cemitério. \r\n(Os monstros banidos devem ser do Tipo Peixe, Serpente Marinha ou Aqua mesmo depois de serem banidos.)','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10136446,'Senhor Obscuro Estrela da Noite',replace(replace('2 monstros Fada de TREVAS de Nível 6 ou mais	\r\nSeu oponente não pode escolher este card como alvo de efeitos de card. \r\nVocê só pode usar cada um dos seguintes efeitos de "Senhor Obscuro Estrela da Noite" uma vez por turno. \r\nSe este card for Invocado por Invocação-Fusão: você pode Baixar 1 Magia "Senhor(a) Obscuro(a)" e 1 Armadilha "Senhor(a) Obscuro(a)" do seu Deck. \r\n(Efeito Rápido): você pode pagar 1000 PV e, depois, escolha 1 Magia/Armadilha "Senhor(a) Obscuro(a)" no seu Cemitério; aplique o efeito de ativação desse card e, depois, embaralhe-o no Deck.','\r',char(13)),'\n',char(10)),'Baixar','Copiar efeito','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10140443,'Salamagrande Grifo Explosivo',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nVocê pode escolher 1 monstro de FOGO de Nível 7 ou menos no seu Cemitério; Invoque-o por Invocação-Especial e, se isso acontecer, reduza o Nível deste card pelo Nível original desse monstro e, além disso, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros de FOGO. \r\nSe este card for Invocado por Invocação-Sincro usando "Salamagrande Grifo Explosivo" como matéria: você pode ativar este efeito; durante a próxima Fase de Apoio, Invoque por Invocação-Especial 1 monstro do seu Cemitério. \r\nVocê só pode usar cada efeito de "Salamagrande Grifo Explosivo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10158145,'Cavaleira do Pesadelo Corruptora Iblee',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode escolher 1 Monstro Link no seu Cemitério; Invoque-o por Invocação-Especial no seu campo de forma que ele aponte para este card, mas mude o ATK dele para 0 e, além disso, negue seus efeitos. \r\nVocê não pode Invocar monstros por Invocação-Especial, exceto Monstros Link. \r\nSe este card sob o controle do seu dono for enviado para o Cemitério: você pode Invocar este card por Invocação-Especial no campo do seu oponente em Posição de Defesa. \r\nVocê só pode usar este efeito de "Cavaleira do Pesadelo Corruptora Iblee" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10163855,'Cavaleiro Concha',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode colocar este card em Posição de Defesa e, se isso acontecer, cause 500 de dano ao seu oponente. \r\nSe este card for destruído em batalha ou enviado para o Cemitério por um efeito de card: você pode adicionar 1 monstro Rocha de Nível 8 do seu Deck à sua mão ou, se "Fusão Fóssil" estiver no seu Cemitério, em vez disso, você pode Invocá-lo por Invocação-Especial. \r\nPelo resto deste turno, você não pode ativar cards, ou os efeitos de cards, com o mesmo nome que o desse card. \r\nVocê só pode usar este efeito de "Cavaleiro Concha" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10178757,'Oráculo Genex-R',replace(replace('Não pode ser usado como Matéria Sincro, exceto para a Invocação-Sincro de um monstro "Genex". \r\nSe este card for adicionado do seu Deck à sua mão pelo efeito de um monstro "Genex": você pode Invocar este card por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10182251,'Lirilusc - Canário de Berilo',replace(replace('Se este card estiver na sua mão: você pode escolher 1 monstro "Lirilusc" no seu Cemitério; Invoque tanto este card como esse monstro por Invocação-Especial e, além disso, você não pode Invocar monstros por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto Monstros Xyz. \r\nVocê só pode usar este efeito de "Lirilusc - Canário de Berilo" uma vez por turno. \r\nUm Monstro Xyz de VENTO que foi Invocado usando este card no campo como matéria ganha este efeito.\r\n● Este card ganha 200 de ATK e, além disso, seu controle não pode ser trocado.','\r',char(13)),'\n',char(10)),'','O efeito de "Lirilusc - Canário de Berilo" está sendo aplicado.','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10186633,'Embaralhar EN',replace(replace('Embaralhe no Deck 1 monstro "HERÓI do Elemento" ou "Neoespacial" que você controla e, se isso acontecer, Invoque por Invocação-Especial 1 monstro "HERÓI do Elemento" ou "Neoespacial" com um nome diferente do seu Deck. \r\nVocê pode banir este card do seu Cemitério; embaralhe do seu Cemitério no Deck, ou 1 monstro "HERÓI do Elemento" e 1 monstro "Neoespacial", OU 1 "Neos, o HERÓI do Elemento" e, depois, compre 1 card. \r\nVocê só pode usar cada efeito de "Embaralhar EN" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10189126,'Feiticeiro Mascarado','Quando este card inflige dano de batalha ao seu adversário, compre 1 card do seu Deck.','Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10194329,'Ataqueraptor - Abutre Vingador','Se você sofrer dano: você pode Invocar este card por Invocação-Especial da sua mão e, além disso, você não pode Invocar monstros do Deck Adicional por Invocação-Especial pelo resto deste turno, exceto monstros "Ataqueraptor".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10202894,'Pássaro da Crista Vermelha','Este monstro mergulha dos céus e ataca com uma chuva de facas guardadas em suas asas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10204849,'Fleuret de Fleur',replace(replace('Ative este card ao escolher 1 monstro de Nível 2 ou menos no seu Cemitério; Invoque-o por Invocação-Especial, mas negue seus efeitos e, além disso, equipe-o com este card. \r\nQuando este card equipado por este efeito deixar o campo, destrua esse monstro. \r\nO monstro equipado ganha 700 de ATK. \r\nSe este card for enviado da Zona de Magias & Armadilhas para o Cemitério: você pode equipar este card a 1 Monstro Sincro que você controla. \r\nVocê só pode usar este efeito de "Fleuret de Fleur" uma vez por turno. \r\nVocê só pode ativar 1 "Fleuret de Fleur" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10209545,'Comandante Decaído',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode Invocar por Invocação-Especial 1 "Tigre Zumbi" da sua mão. \r\nSe este card causar dano de batalha ao seu oponente em um ataque direto: descarte 1 card aleatório da mão dele.','\r',char(13)),'\n',char(10)),'Invocação Especial','Descartar da mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10218411,'Fusão Dupla','Pague 500 PV; Invoque por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional, usando monstros da sua mão ou do campo e, depois, você pode Invocar por Invocação-Fusão mais 1 Monstro de Fusão do seu Deck Adicional, usando monstros da sua mão ou do campo.','Ativar','Continuar a Invocação Fusão?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10236520,'Goe-Goe, o Ninja Galanteador',replace(replace('Quando este card causar Dano de Batalha ao seu oponente: Seu oponente deve descartar 2 cards aleatórios. \r\nSeu oponente deve ter pelo menos 5 cards na mão dele para você ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Descartar da mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10239627,'Abdutor Mágico',replace(replace('Escala de Pêndulo = 3\r\n[ Efeito de Pêndulo ]\r\nSempre que um Card de Magia for ativado, coloque 1 Marcador de Magia neste card quando essa Magia resolver. \r\nUma vez por turno: você pode remover 3 Marcadores de Magia deste card; adicione 1 Monstro Pêndulo do seu Deck à sua mão.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSempre que um Card de Magia for ativado, coloque 1 Marcador de Magia neste card quando essa Magia resolver. \r\nGanha 100 de ATK para cada Marcador de Magia sobre ele. \r\nUma vez por turno: você pode remover 3 Marcadores de Magia deste card; adicione 1 monstro Mago de Nível 1 do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10248192,'Hieróglifo Litografado',replace(replace('Pague 1000 Life Points. \r\nDurante o Duelo atual, o limite da sua mão na sua End Phase torna-se 7 cards.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10248389,'Ciberpatinadora',replace(replace('"Ciber Etoile" + "Skater de Lâmina"	\r\nA Invocação-Fusão deste card só pode ser feita com as Matérias de Fusão acima. \r\nEste card ganha o seguinte efeito, de acordo com o número de monstros que seu oponente controla.\r\n● 1: Não pode ser destruído em batalha.\r\n● 2: O ATK deste card é dobrado.\r\n● 3: Os efeitos de card ativados do seu oponente são negados.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10262698,'A Estátua da Ilha de Páscoa','Um monumento de pedra da Ilha da Páscoa que dispara raios laser dos seus lábios esculpidos na rocha.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10266279,'Junoldo, o Patrono do Poder Espírito Sombrio',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nSe um ou mais monstros "Patrono(a) do Poder" ou "Elfnota" forem Invocados por Invocação-Especial no seu campo, enquanto este card estiver na sua Zona de Pêndulo (exceto durante a Etapa de Dano): você pode destruir este card e, se isso acontecer, compre 2 cards e, depois, descarte 1 card. \r\nVocê só pode usar este efeito de "Junoldo, o Patrono do Poder Espírito Sombrio" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\n(Este card deve ser sempre considerado como um card "Elfnota".)	\r\nVocê pode banir os 3 cards do topo do seu Deck, com a face para baixo; destrua este card e, se isso acontecer, Invoque por Invocação-Especial 1 "Junora, o Patrono do Poder da Afinação" do seu Deck Adicional (isso é considerado uma Invocação-Sincro). \r\nSe este card for adicionado ao seu Deck Adicional com a face para cima: você pode adicionar 1 card "Patrono(a) do Poder" ou "Elfnota" do seu Deck Adicional com a face para cima ou Cemitério à sua mão, exceto "Junoldo, o Patrono do Poder Espírito Sombrio". \r\nVocê só pode usar cada efeito de "Junoldo, o Patrono do Poder Espírito Sombrio" uma vez por turno.','\r',char(13)),'\n',char(10)),'Comprar','Invocação Especial','Efeito de busca','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10275411,'Vingança Xyz',replace(replace('Se seu oponente controlar um Monstro Xyz com a face para cima que tenha alguma Matéria Xyz: escolha 1 Monstro Xyz em seu Cemitério; Invoque-o por Invocação-Especial e, depois, desassocie 1 Matéria Xyz de um monstro que seu oponente controla e associe-a a esse monstro como uma Matéria Xyz. \r\nVocê só pode ativar 1 "Vingança Xyz" por turno.','\r',char(13)),'\n',char(10)),'Escolha a(s) Matéria(s) a transferir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10282757,'Planckton',replace(replace('Aplique esses efeitos até o final deste turno.\r\n● Monstros Xyz de Classe 3 ou menos ganham 500 de ATK e DEF.\r\n● Monstros Xyz de Classe 4 ou mais não podem atacar.','\r',char(13)),'\n',char(10)),'Monstros Xyz de Classe 3 ou menos ganham 500 ATK/DEF','Monstros Xyz de Classe 4 ou mais não podem atacar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10286023,'Cristal Adamancipador - Dragita',replace(replace('Se este card for Invocado por Invocação-Especial pelo efeito de um card "Adamancipador": você pode comprar 1 card. \r\nSe este card estiver no seu Cemitério: você pode escolher 1 Monstro Sincro de ÁGUA que você controla ou no seu Cemitério; devolva-o para o Deck Adicional e, se isso acontecer, coloque este card no topo do Deck. \r\nVocê só pode usar cada efeito de "Cristal Adamancipador - Dragita" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10300821,'Número C79: Boxeador Obstinado General Kaiser',replace(replace('3 monstros de Nível 5	\r\nGanha 200 de ATK para cada matéria associada a ele. \r\nUma vez por turno, quando seu oponente Invocaria um ou mais monstros por Invocação-Especial (Efeito Rápido): você pode desassociar 2 matérias deste card e, se isso acontecer, negue a Invocação e, se isso acontecer, destrua esse(s) monstro(s). \r\nSe este card tiver "Número 79: Boxeador Obstinado Kaiser Nova" como matéria, ele ganha este efeito.\r\n● Uma vez por turno, quando um ataque for declarado envolvendo um monstro "Boxeador Obstinado" seu e um monstro do oponente: você pode enviar para o Cemitério 1 monstro "Boxeador Obstinado" da sua mão ou do Deck e, se isso acontecer, associe esse monstro do oponente a este card como matéria.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10307853,'Jardim das Pedrastalis',replace(replace('Enquanto você controlar 5 cards na sua Zona de Magias & Armadilhas, qualquer dano de batalha que um duelista sofrer é diminuído pela metade e, além disso, uma vez por turno, você pode ativar 1 Card de Armadilha Contínua no turno em que foi Baixado. \r\nDurante a Fase de Apoio: você pode revelar 5 Armadilhas Contínuas do seu Deck com nomes diferentes, seu oponente elege 1 aleatoriamente para que você Baixe e embaralhe o resto no Deck. \r\nVocê só pode usar este efeito de "Jardim das Pedrastalis" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar aplicando o efeito de {CARD}.','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10312660,'Você está em Perigo!',replace(replace('Revele 3 monstros "Perigo!" com nomes diferentes do seu Deck, seu oponente elege 1 aleatoriamente para que você Invoque por Invocação-Especial e você embaralha o resto no Deck. \r\nDurante a Fase Final, destrua esse monstro Invocado por Invocação-Especial. \r\nVocê só pode ativar 1 "Você está em Perigo!" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10315429,'Yaiba Robo','Uma máquina cúbica equipada com lâminas afiadas para fazer pedacinhos do oponente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10321588,'Unicórnio da Luz do Sol',replace(replace('Uma vez por turno: você pode escavar o card do topo do seu Deck e, se for um Card de Magia de Equipamento, adicione-o à sua mão. \r\nCaso contrário, coloque-o no fundo do seu Deck.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10333641,'Samurai Superpesado Furtivo',replace(replace('Se você não tiver Magias/Armadilhas no seu Cemitério, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Samurai Superpesado Furtivo" por Invocação-Especial uma vez por turno desta forma. \r\nSe você não tiver Magias/Armadilhas no seu Cemitério (Efeito Rápido): você pode oferecer este card como Tributo e, depois, escolha 1 Magia/Armadilha no Cemitério do seu oponente; Baixe-a no seu campo, mas bana-a quando ela deixar o campo. \r\nVocê só pode usar este efeito de "Samurai Superpesado Furtivo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10352095,'Pergaminho do Feitiço','Ative este card ao declarar 1 Atributo; o monstro equipado se torna desse Atributo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10365322,'Besta da Ignição Vulcanhão',replace(replace('1 monstro do Tipo Máquina + 1 monstro do Tipo Piro	\r\nQuando este card for Invocado por Invocação-Fusão: você pode escolher 1 monstro que seu oponente controla; destrua o alvo e também destrua este card e, depois, se os dois monstros foram destruídos, cause dano ao seu oponente igual ao ATK do monstro no Cemitério que foi escolhido como alvo deste efeito.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10375182,'Cavaleiro Comando',replace(replace('Todos os monstros Guerreiro que você controla ganham 400 de ATK. \r\nSe você controlar outro monstro, os monstros que seu oponente controla não podem escolher este card como alvo de ataques.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10383554,'Leão Peladura',replace(replace('"Diabrete de Serras Afiadas" + 1 monstro "Fofanimal"	\r\nDeve ser Invocado por Invocação-Fusão. \r\nVocê pode escolher 1 monstro com a face para cima que seu oponente controla; destrua-o e, se isso acontecer, cause dano ao seu oponente igual ao ATK original do monstro destruído. \r\nVocê só pode usar este efeito de "Leão Peladura" uma vez por turno. \r\nEste card não pode atacar diretamente durante o turno em que você ativar este efeito.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10383555,'Leão Peladura',replace(replace('"Diabrete de Serras Afiadas" + 1 monstro "Fofanimal"	\r\nDeve ser Invocado por Invocação-Fusão. \r\nVocê pode escolher 1 monstro com a face para cima que seu oponente controla; destrua-o e, se isso acontecer, cause dano ao seu oponente igual ao ATK original do monstro destruído. \r\nVocê só pode usar este efeito de "Leão Peladura" uma vez por turno. \r\nEste card não pode atacar diretamente durante o turno em que você ativar este efeito.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10389142,'Número 42: Tomahawk das Galáxias',replace(replace('2 monstros de Nível 7	\r\nUma vez por turno: você pode desassociar 2 Matérias Xyz deste card; Invoque por Invocação-Especial tantas "Fichas de Águia de Batalha" (Tipo Máquina/VENTO/Nível 6/ATK 2000/DEF 0) quanto possível, destrua-as durante a Fase Final deste turno e, além disso, seu oponente não sofre dano de batalha neste turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10389143,'Ficha de Águia de Batalha','Invocado por Especial com o efeito "Número 42: Tomahawk das Galáxias". Destrua esta Ficha durante a Fase Final do turno em que é Invocado por Especial.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10389794,'Rosquinhas da Perdição','VIRE: Destrua todos os monstros com a face para cima no campo com um ATK ou DEF original de 0.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10406322,'Alsei, o Alto Protetor Silvestre',replace(replace('2 monstros de Nível 8	\r\nUma vez por turno: você pode declarar 1 nome de card; escave o card do topo do seu Deck e, se ele for o card declarado, adicione-o à sua mão. \r\nCaso contrário, envie-o para o Cemitério. \r\nSe um ou mais cards forem enviados do seu Deck para o Cemitério por um efeito de card (exceto durante a Etapa de Dano): você pode desassociar 1 matéria deste card e, depois, escolha 1 card no campo; coloque o alvo no topo ou no fundo do Deck. \r\nVocê só pode usar este efeito de "Alsei, o Alto Protetor Silvestre" uma vez por turno.','\r',char(13)),'\n',char(10)),'Declare o nome de um card','Retornar ao Deck','Coloque no topo do Deck','Coloque no fundo do Deck','','','','','','','','','','','','');
INSERT INTO texts VALUES(10424147,'Nave Mech Super Quantal Magnaportador',replace(replace('Descarte 1 card e, depois, escolha 1 monstro "Super Quantum" que você controla; Invoque por Invocação-Especial do Deck Adicional, 1 Monstro Xyz "Besta Mech Super Quantal" com o mesmo Atributo que esse monstro que você controla, usando-o como matéria. \r\n(Isso é considerado uma Invocação-Xyz.) \r\nVocê pode enviar este card da Zona do Campo para o Cemitério e, depois, escolher 3 Monstros Xyz "Besta Mech Super Quantal" com nomes diferentes que você controla e/ou no seu Cemitério; Invoque por Invocação-Especial 1 "Rei Mech Super Quantal Grande Magnus" do seu Deck Adicional e, se isso acontecer, associe a ele como matéria os monstros alvo e suas matérias.','\r',char(13)),'\n',char(10)),'Descarte 1 card','Enviar para o Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10426067,'Senhor Obscuro Djehuty',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode Invocar por Invocação-Especial 1 monstro "Senhor(a) Obscuro(a)" do seu Deck em Posição de Defesa, exceto "Senhor Obscuro Djehuty" e, além disso, você não pode Invocar por Invocação-Especial pelo resto deste turno, exceto monstros Fada. \r\nSe você controlar um Monstro de Fusão Fada de TREVAS: você pode banir este card do seu Cemitério e, depois, escolha 1 card "Senhor(a) Obscuro(a)" ou Magia Rápida "Proibido(a)" no seu Cemitério; adicione-o à sua mão. \r\nVocê só pode usar cada efeito de "Senhor Obscuro Djehuty" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10441498,'Vennu, o Pássaro Brilhante da Divindade',replace(replace('Você pode Invocar este card por Invocação-Ritual com "Grito Primário". \r\nUma vez por turno: você pode revelar 1 monstro da sua mão e, depois, escolher 1 monstro com a face para cima no campo; até o final deste turno, o Nível do alvo se torna igual ao Nível que o monstro revelado tinha. \r\nUma vez por turno, se outro monstro for oferecido como Tributo da sua mão ou do campo (exceto durante a Etapa de Dano): você pode escolher 1 monstro no seu Cemitério; adicione-o à sua mão.','\r',char(13)),'\n',char(10)),'Alterar Nível','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10443957,'Dragão Cibernético do Infinito',replace(replace('3 monstros Máquina de LUZ de Nível 6	\r\nUma vez por turno, você também pode Invocar "Dragão Cibernético do Infinito" por Invocação-Xyz ao usar "Dragão Cibernético Nova" que você controla como matéria. \r\n(Transfira as matérias dele para este card.) \r\nGanha 200 de ATK para cada matéria associada a ele. \r\nUma vez por turno: você pode escolher 1 monstro com a face para cima em Posição de Ataque no campo; associe-o a este card como matéria. \r\nUma vez por turno, quando um card ou efeito for ativado (Efeito Rápido): você pode desassociar 1 matéria deste card; negue a ativação e, se isso acontecer, destrua-o.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Xyz usando "Dragão Cibernético Nova" como matéria?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10443958,'Dragão Cibernético do Infinito',replace(replace('3 monstros Máquina de LUZ de Nível 6	\r\nUma vez por turno, você também pode Invocar "Dragão Cibernético do Infinito" por Invocação-Xyz ao usar "Dragão Cibernético Nova" que você controla como matéria. \r\n(Transfira as matérias dele para este card.) \r\nGanha 200 de ATK para cada matéria associada a ele. \r\nUma vez por turno: você pode escolher 1 monstro com a face para cima em Posição de Ataque no campo; associe-o a este card como matéria. \r\nUma vez por turno, quando um card ou efeito for ativado (Efeito Rápido): você pode desassociar 1 matéria deste card; negue a ativação e, se isso acontecer, destrua-o.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Xyz usando "Dragão Cibernético Nova" como matéria?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10449150,'Espaçoroide',replace(replace('Quando este card for alvo de um ataque: Você pode banir este card. \r\nSe ele for banido por este efeito, Invoque-o por Invocação-Especial durante a sua próxima Fase de Preparação. \r\nQuando ele for Invocado por Invocação-Especial por este efeito: Cause 1000 pontos de dano ao seu oponente.','\r',char(13)),'\n',char(10)),'Banir','Invocação Especial','Causar dano aos PV','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10456559,'T.A.D.P.O.L.E.',replace(replace('Quando este card no seu Campo é destruído como resultado de uma batalha e enviado para o seu Cemitério, você pode adicionar qualquer número de "T.A.D.P.O.L.E."(s) do seu Deck para a sua mão. \r\nEm seguida, embaralhe o seu Deck.','\r',char(13)),'\n',char(10)),'Adicione "T.A.D.P.O.L.E." à sua mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10474647,'Leopresivo',replace(replace('Se este for o único card na sua mão: você pode Invocar este card por Invocação-Especial. \r\nSe isso acontecer: o ATK deste card se torna 2500 até o final do turno do seu oponente. \r\nSe este card batalhar um monstro do oponente, você sofre qualquer dano de batalha que seu oponente teria sofrido dessa batalha. \r\nSe você sofrer dano de batalhas envolvendo este card: o ATK deste card se torna 0 e, depois, se seus PV forem 2000 ou menos, o ATK deste card se torna 5000.','\r',char(13)),'\n',char(10)),'Invocação Especial','Altere o ATK','Seu ATK se torna 5000','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10476868,'Rocha Revólver','Portando um par de metralhadoras, este monstro é imparável.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10485110,'Dragão Senhor do Oceano- Neo-Daedalus',replace(replace('Este card não pode ser Invocado, por Invocação-Normal, ou Baixado. \r\nEste card não pode ser Invocado, por Invocação-Especial, exepto oferecendo como Tributo 1 "Levia-Dragão - Daedalus" no seu Campo. \r\nEnvie "Umi" no seu Campo para o Cemitério para enviar para o Cemitério todos os cards na mão de ambos os jogadores e no Campo exceto este card.','\r',char(13)),'\n',char(10)),'Enviar para o Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10489311,'Medalha do Herói',replace(replace('Quando este card Baixado for destruído e enviado para o Cemitério por um efeito de card do oponente, embaralhe este card no Deck do seu dono. \r\nDepois, compre 1 card.','\r',char(13)),'\n',char(10)),'Retornar para o Deck e depois compre 1 card','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10493654,'Contato I.A.',replace(replace('Se "I.A.Terra Ignister" estiver na sua Zona do Campo: revele 1 "I.A.Terra Ignister" na sua mão; coloque-o no fundo do Deck e, se isso acontecer, compre 3 cards. \r\nVocê só pode ativar 1 "Contato I.A." por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10497636,'Caverguerra Meteoragon',replace(replace('Não pode ser destruído por efeitos de card do oponente. \r\nQuando um ataque for declarado envolvendo este card e um monstro do oponente: você pode negar os efeitos desse monstro do oponente neste turno, assim como os efeitos ativados e efeitos no campo de monstros com o seu mesmo nome original. \r\nUma vez por turno, durante uma Fase de Batalha na qual um monstro Guerreiro de TERRA seu batalhar (Efeito Rápido): você pode fazer com que todos os monstros "Caverguerra" que você controla atualmente ganhem 200 de ATK até o final do turno do seu oponente e, além disso, este card pode realizar até 2 ataques contra monstros durante cada Fase de Batalha neste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10505300,'Andorinha Devagarzinha',replace(replace('Se 2 ou mais monstros com o mesmo Nível estiverem no campo, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Andorinha Devagarzinha" por Invocação-Especial uma vez por turno desta forma. \r\nVocê pode oferecer este card como Tributo; compre 2 cards em vez de 1 em sua compra normal durante sua próxima Fase de Compra.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10509340,'Besta do Mecanismo Antigo',replace(replace('Não pode ser Invocado por Invocação-Especial. \r\nSe este card atacar, seu oponente não pode ativar quaisquer Cards de Magia/Armadilha até o final da Etapa de Dano. \r\nNegue os efeitos de um monstro do oponente destruído em batalha com este card (incluindo no Cemitério).','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10515412,'Dragão da Tempestade de Luz',replace(replace('1 Regulador + 1+ não-Reguladores	\r\nSe este card for Invocado por Invocação-Especial: você pode escolher Magias/Armadilhas no campo até o número de Monstros Normais no seu Cemitério +1; destrua-os. \r\nSe este card for destruído em batalha ou por um efeito de card: você pode escolher 1 Magia/Armadilha no seu Cemitério; Baixe-a, mas ela não pode ser ativada a não ser que você controle um Monstro Normal. \r\nVocê só pode usar cada efeito de "Dragão da Tempestade de Luz" uma vez por turno.','\r',char(13)),'\n',char(10)),'Destruir','Baixar','O efeito de "Dragão da Tempestade de Luz" está sendo aplicado.','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10526791,'Fio Selvagem, o HERÓI do Elemento',replace(replace('"Coração Selvagem, o HERÓI do Elemento" + "Lâmina Afiada, o HERÓI do Elemento"	\r\nDeve ser Invocado por Invocação-Fusão e não pode ser Invocado por Invocação-Especial de nenhuma outra forma. \r\nEste card pode atacar todos os monstros que seu oponente controla (um ataque em cada monstro por Fase de Batalha).','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10529441,'Buraco Armadilha dos Tolos','Quando um efeito de monstro for ativado no campo do seu oponente, durante um turno em que seu oponente tiver Invocado por Invocação-Especial: destrua o monstro que ativou seu efeito e, depois, se seu oponente controlar um ou mais cards em suas Zonas de Monstros e/ou Zonas de Magias & Armadilhas adjacentes, destrua-os.','Ativar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10530913,'Sabiquoia Silvestre',replace(replace('Quando um monstro "Silvestre" for enviado para o Cemitério (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão. \r\nUma vez por turno: você pode escavar o card do topo do seu Deck e, se ele for um monstro do Tipo Planta, envie-o para o Cemitério. \r\nCaso contrário, coloque-o no fundo do seu Deck. \r\nSe este card for escavado do Deck e enviado para o Cemitério por um efeito de card: você pode escolher 1 Card de Magia/Armadilha "Silvestre" no seu Cemitério; adicione-o à sua mão.','\r',char(13)),'\n',char(10)),'Invocação Especial','Escave cards do seu Deck','Adicionar à mão','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10532969,'Tubarão Megalodon Hiper-Ancião','Quando este card causar dano de batalha ao seu oponente: você pode escolher 1 monstro que seu oponente controla; destrua o alvo.','Destruir um monstro','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10537981,'Retorno de Alma',replace(replace('Ative apenas durante a Fase Final. \r\nVocê pode devolver até 3 monstros destruídos neste turno do Cemitério para os Decks de seus donos.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10538007,'Leogun','Um monstro enorme com uma juba parecida com a do Rei das Bestas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10547580,'Balista do Mecanismo Antigo',replace(replace('2 monstros Máquina de TERRA	\r\nSe este card for Invocado por Invocação-Link: você pode adicionar 1 monstro "Mecanismo Antigo" ou 1 "Vila Mecânica" do seu Deck à sua mão. \r\nVocê pode escolher 1 Magia/Armadilha que você controla e 1 monstro com a face para cima que seu oponente controla; destrua esse card que você controla e, se isso acontecer, mude o ATK/DEF desse monstro do oponente para 0 até o final do turno. \r\nVocê só pode usar cada efeito de "Balista do Mecanismo Antigo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10552026,'Gouki, Ogro Vilão',replace(replace('2 monstros "Gouki"	\r\nUma vez por turno, quando um monstro para o qual este card apontar ativar seu efeito (Efeito Rápido): você pode negar a ativação e, se isso acontecer, destrua-o e, depois, você pode Invocar por Invocação-Especial 1 monstro "Gouki" do seu Cemitério, exceto "Gouki, Ogro Vilão".','\r',char(13)),'\n',char(10)),'','Invocar um monstro "Gouki" por Invocação Especial?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10560119,'Doutor Peixeborgue',replace(replace('Se este card estiver no seu Cemitério e todos os monstros que você controla forem monstros "Peixeborgue" (mín. 1): você pode Invocar este card por Invocação-Especial e, se isso acontecer, bana-o quando ele deixar o campo. \r\nVocê só pode usar este efeito de "Doutor Peixeborgue" uma vez por turno. \r\nSe você controlar um monstro que não seja um monstro "Peixeborgue", destrua este card.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10584050,'Explosão Springans!',replace(replace('Se você controlar um monstro "Springans": selecione 1 Zona de Monstros Principal do oponente; se um monstro estiver com a face para cima nessa zona, durante este turno, ele não pode atacar diretamente e, além disso, seus efeitos são negados. \r\nSe nenhum monstro estiver nessa zona, ela não pode ser usada neste turno. \r\nSe você controlar um Monstro de Fusão que liste "Caído de Arbaz" como matéria, em vez disso você pode selecionar 2 zonas. \r\nVocê só pode ativar 1 "Explosão Springans!" por turno.','\r',char(13)),'\n',char(10)),'Escolher mais 1 zona?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10591919,'Microscópion Morfotrônico',replace(replace('● Enquanto estiver em Posição de Ataque: Uma vez por turno, você pode Invocar por Invocação-Especial 1 monstro "Morfotrônico(a)" de Nível 4 da sua mão.	\r\nDestrua-o durante a Fase Final.\r\n● Enquanto estiver em Posição de Defesa: Enquanto este card estiver com a face para cima em Posição de Defesa, ele é de Nível 4.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10598400,'Zarigun','Uma lagosta letal com garras extremamente perigosas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10602628,'Asanegra - Boretempestade, o Vento Perverso',replace(replace('1 Regulador de TREVAS + 1+ monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro: você pode enviar 1 monstro "Asanegra" do seu Deck para o Cemitério e, se isso acontecer, o Nível deste card se torna o mesmo que o desse monstro. \r\nQuando este card destruir um monstro em batalha e enviá-lo para o Cemitério: você pode banir 1 monstro "Asanegra" do seu Cemitério ou do campo com a face para cima, exceto o monstro destruído; Invoque o monstro destruído por Invocação-Especial no seu campo em Posição de Defesa. \r\nVocê só pode usar cada efeito de "Asanegra - Boretempestade, o Vento Perverso" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10604644,'Therion "Rei" Regulus',replace(replace('Você só pode usar cada um dos seguintes efeitos de "Therion "Rei" Regulus" uma vez por turno.\r\n● Você pode escolher 1 monstro "Therion" ou 1 monstro Máquina no seu Cemitério; Invoque este card por Invocação-Especial da sua mão e, se isso acontecer, equipe esse monstro a este card.\r\n● Quando seu oponente ativar um card ou efeito (Efeito Rápido): você pode enviar 1 Card de Monstro "Therion" da sua mão ou do campo com a face para cima para o Cemitério; negue o efeito.	\r\nUm monstro "Therion" equipado com este card ganha 700 de ATK e, além disso, ele pode ativar o 2º efeito listado acima como se fosse "Therion "Rei" Regulus".','\r',char(13)),'\n',char(10)),'','Negue o efeito de (Therion "Rei" Regulus) do seu oponente','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10612222,'Espada Agulha dos Yosenjus',replace(replace('Se você não controlar nenhum monstro: revele até 2 monstros "Yosenju" com nomes diferentes na sua mão e, depois, escolha o mesmo número de cards com a face para cima que seu oponente controla; devolva-os para a mão. \r\nVocê só pode ativar 1 "Espada Agulha dos Yosenjus" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10613952,'Nobre Cavaleiro Sagrado do Rei Artorigus',replace(replace('2 monstros "Nobre Cavaleiro" de Nível 5	\r\nQuando este card for Invocado por Invocação-Xyz: você pode escolher até 3 Cards de Magia de Equipamento "Armas Nobres" com nomes diferentes no seu Cemitério; equipe os alvos a este card. \r\nUma vez por turno: você pode desassociar 1 Matéria Xyz deste card e, depois, escolher 1 outro monstro no campo; destrua o alvo. \r\nSe este card for enviado do campo para o Cemitério: você pode escolher 1 monstro "Nobre Cavaleiro" de Nível 4 ou mais no seu Cemitério; Invoque o alvo por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Equipar','Destruir','Invocação Especial','Continuar selecionando uma Magia de Equipamento cujo nome contenha "Armas Nobres" para equipar?','','','','','','','','','','','','');
INSERT INTO texts VALUES(10632284,'Elefante Mimese',replace(replace('Invoque este card por Invocação-Especial como um Monstro de Efeito (Besta/TERRA/Nível 2/ATK 0/DEF 2000).	\r\n(Este card ainda é considerado uma Armadilha.) \r\nSe este card estiver na Zona de Monstros (Efeito Rápido): você pode declarar 1 Tipo e 1 Atributo e, depois, escolha 1 monstro com a face para cima no campo; até o final deste turno, ele se torna desse Tipo e Atributo. \r\nVocê só pode usar este efeito de "Elefante Mimese" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10642488,'Vic Viper T301',replace(replace('Quando um ataque for declarado envolvendo um monstro seu com a face para cima e um monstro do oponente: você pode Invocar este card por Invocação-Especial da sua mão ou do Cemitério, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar este efeito de "Vic Viper T301" uma vez por turno. \r\nOutros monstros Máquina de LUZ que você controla ganham 1200 de ATK.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10651797,'Giro da Andorinha','Negue a ativação do efeito de um Monstro de Efeito que é ativado quando um monstro for Invocado por Invocação-Especial (incluindo ele mesmo) e destrua-o.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10666000,'Número 1: Rei Zumbido Infeccioso',replace(replace('2+ monstros de Nível 8	\r\nUma vez por turno, durante sua Fase de Apoio: você pode associar 1 card do Cemitério do seu oponente a este card como matéria. \r\nVocê só pode usar cada um dos seguintes efeitos de "Número 1: Rei Zumbido Infeccioso" uma vez por turno. \r\nSe este card for Invocado por Invocação-Xyz: você pode olhar o Deck Adicional do seu oponente e enviar 1 card dali para o Cemitério. \r\nVocê pode desassociar 1 matéria deste card e, depois, escolha 1 card que seu oponente controla; destrua-o e, depois, se você destruiu um monstro com a face para cima, cause dano ao seu oponente igual à metade do ATK que ele tinha no campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10667321,'Leis Antigas','Invoque por Invocação-Especial 1 Monstro Normal de Nível 5 ou mais da sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10669138,'Dragão Link de Cinco Cabeças',replace(replace('5 monstros	\r\nDeve ser Invocado por Invocação-Link. \r\nSe este card for Invocado por Invocação-Link usando os Atributos TREVAS, TERRA, ÁGUA, FOGO e VENTO: você pode destruir todos os cards que seu oponente controla. \r\nNão pode ser destruído em batalha com um monstro de TREVAS, TERRA, ÁGUA, FOGO ou VENTO. \r\nNão é afetado por outros efeitos de cards. \r\nUma vez por turno, durante a Fase Final do seu oponente: você deve banir, com a face para baixo, 5 cards do seu Cemitério (isso não é opcional) ou enviar este card para o Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10673071,'Virakam, o Espírito Divino do Artifício',replace(replace('Se você tiver um monstro "Aleister" no seu campo ou Cemitério: você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe este card for Invocado por Invocação-Especial: você pode Baixar 1 "Invokação", ou 1 Magia que o mencione, do seu Deck. \r\nQuando seu oponente ativar um card ou efeito em resposta à ativação de um efeito de um Monstro de Fusão seu (Efeito Rápido): você pode banir este card que você controla e, se isso acontecer, negue esse efeito do oponente e, se isso acontecer, bana-o. \r\nVocê só pode usar cada efeito de "Virakam, o Espírito Divino do Artifício" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Efeito de Baixar','Negar o efeito','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10678778,'Aegaion, o Castrum Marítimo',replace(replace('2 monstros de Nível 8	\r\nDurante o turno de qualquer duelista: você pode banir, com a face para cima, 1 monstro aleatório com a face para baixo do Deck Adicional do seu oponente e, se isso acontecer, o ATK deste card se torna igual ao do monstro banido. \r\nDurante o turno de qualquer duelista: você pode desassociar 1 Matéria Xyz deste card e, depois, escolher 1 dos Monstros Fusão, Sincro ou Xyz banidos do seu oponente; devolva-o para o Deck Adicional e, se isso acontecer, destrua 1 monstro que seu oponente controla desse mesmo tipo de card de monstro (Fusão, Sincro ou Xyz). \r\nVocê só pode usar cada efeito de "Aegaion, o Castrum Marítimo" uma vez por turno.','\r',char(13)),'\n',char(10)),'Banir','Destruir um monstro','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10691144,'Espelho da Barreira de Gelo',replace(replace('Durante este turno, sempre que um ou mais cards forem banidos da sua mão, do campo e/ou do Cemitério pela ativação de um efeito de monstro do seu oponente, aplique os seguintes efeitos, de acordo com de onde os cards foram banidos.\r\n● Mão: Bana até 2 cards aleatórios da mão do seu oponente.\r\n● Campo: Bana até 2 cards que seu oponente controla.\r\n● Cemitério: Bana até 2 cards no Cemitério do seu oponente.','\r',char(13)),'\n',char(10)),'Banir cards da mão do seu oponente?','Banir cards que seu oponente controla?','Banir cards do Cemitério do seu oponente?','Banir aleatoriamente 1 card da mão do seu oponente','Banir aleatoriamente 2 cards da mão do seu oponente','','','','','','','','','','','');
INSERT INTO texts VALUES(10698416,'Ranvier Krawler',replace(replace('VIRE: Você pode escolher até 2 monstros "Krawler" no seu Cemitério; adicione-os à sua mão.\r\nSe este card com a face para cima sob o controle do seu dono deixar o campo devido a um efeito de card do oponente: você pode Invocar por Invocação-Especial 2 monstros "Krawler" com nomes diferentes do seu Deck em Posição de Defesa com a face para baixo, exceto "Ranvier Krawler". \r\nVocê só pode usar cada efeito de "Ranvier Krawler" uma vez por turno.','\r',char(13)),'\n',char(10)),'Recuperar do Cemitério','Invoque 2 monstros por Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10705656,'Garoto Widget',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode Invocar por Invocação-Especial 1 monstro Ciberso da sua mão em Posição de Defesa. \r\nVocê só pode usar este efeito de "Garoto Widget" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10712320,'Estigma Vylon','Uma vez por turno, durante o turno de qualquer duelista: Você pode escolher 1 Card de Equipamento "Vylon" com a face para cima que você controla e 1 monstro com a face para cima apropriado; equipe o primeiro alvo ao segundo alvo.','Transfira o Card de Equipamento','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10719350,'Formação de Fogo - Tensu',replace(replace('Durante sua Fase Principal, você pode Invocar por Invocação-Normal 1 monstro Besta-Guerreira em adição à sua Invocação-Normal/Baixar padrão. \r\n(Você só pode se aproveitar deste efeito uma vez por turno.) \r\nTodos os monstros Besta-Guerreira que você controla ganham 100 de ATK.','\r',char(13)),'\n',char(10)),'Invoque usando o efeito de "Formação de Fogo - Tensu"','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10723472,'Alma Ardente',replace(replace('Se você controlar um Monstro Sincro de Nível 8 ou mais: adicione 1 card do seu Cemitério à sua mão, exceto "Alma Ardente" e, depois, imediatamente depois que este efeito resolver, Invoque por Invocação-Sincro usando monstros que você controla como matéria. \r\nPelo resto deste turno depois que este card resolver, seu oponente não pode escolher Monstros Sincro no campo como alvo de efeitos de card. \r\nVocê só pode ativar 1 "Alma Ardente" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10731333,'Minitauro Camarartista de Olhos Anômalos',replace(replace('Escala de Pêndulo = 6\r\n[ Efeito de Pêndulo ]\r\nSe um monstro "Camarartista" ou "Olhos Anômalos" seu atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nDurante o cálculo de dano, se um Monstro Pêndulo seu atacar um monstro do oponente: você pode fazer com que esse monstro do oponente perca 100 de ATK para cada card "Camarartista" e "Olhos Anômalos" que você controla, apenas durante o cálculo de dano.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10732060,'Alta-Velocidaroide Planador #2',replace(replace('1 Regulador Máquina de VENTO + 1+ monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro: você pode escolher 1 Monstro Sincro não-Regulador de VENTO de Nível 7 ou menos no seu Cemitério; Invoque-o por Invocação-Especial. \r\nSe seu oponente Invocar um ou mais monstros por Invocação-Especial, e você controlar um monstro "Asas Transparentes" (exceto durante a Etapa de Dano): você pode banir este card do seu Cemitério; aumente o Nível de todos os monstros que seu oponente controla em 5. \r\nVocê só pode usar cada efeito de "Alta-Velocidaroide Planador #2" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Aumentar o Nível','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10736540,'Dama do Lago',replace(replace('Não pode ser usado como uma Matéria Sincro, exceto para a Invocação-Sincro de um monstro do Tipo Guerreiro. \r\nSe este card for usado para uma Invocação-Sincro, bana-o. \r\nQuando este card for Invocado por Invocação-Normal: você pode escolher 1 Monstro Normal "Nobre Cavaleiro" no seu Cemitério; Invoque o alvo por Invocação-Especial. \r\nSe este card estiver no seu Cemitério: você pode escolher 1 monstro "Nobre Cavaleiro" de Nível 5 que você controla; reduza o Nível dele em 1 e, se isso acontecer, Invoque este card por Invocação-Especial do Cemitério.','\r',char(13)),'\n',char(10)),'Invoque por Invocação Especial do Cemitério','Invocar este card por Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10753491,'Querubroto Silvestre',replace(replace('Quando este card for Invocado por Invocação-Especial: você pode selecionar um número entre 1 ou 2 e, depois, escavar esse número de cards do topo do seu Deck, enviar quaisquer monstros escavados do Tipo Planta para o Cemitério e, além disso, colocar os outros cards no fundo do seu Deck em qualquer ordem. \r\nSe este card for escavado do Deck e enviado para o Cemitério por um efeito de card: você pode Invocar por Invocação-Especial 1 monstro do Tipo Planta de Nível 1 do seu Deck. \r\nVocê só pode usar este efeito de "Querubroto Silvestre" uma vez por turno.','\r',char(13)),'\n',char(10)),'Escave cards do seu Deck','Escolha a quantidade de cards a escavar','Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10755153,'Guardião Ceal',replace(replace('Este card pode ser Invocado, por Invocação-Normal, Invocação-Virar, ou Invocação-Especial apenas quando "Arco Lança Estrelas - Ceal" estiver no seu Campo. \r\nEnvie um Card de Magia de Equipamento equipado a este card no seu Campo para o Cemitério para destruir 1 monstro no Campo do seu adversário.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10755984,'Eguls Daigusto',replace(replace('1 Regulador + 1 ou mais monstros "Gusto" não-Reguladores	\r\nUma vez por turno, durante a Fase Final: Você pode banir 1 monstro de VENTO do seu Cemitério para escolher 1 card com a face para baixo que seu oponente controla; destrua esse alvo.','\r',char(13)),'\n',char(10)),'Destrua 1 card com a face para baixo no campo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10759529,'Guarda Criança','Quando um monstro do seu oponente declarar um ataque: Ofereça como Tributo 1 "Herói Criança"; negue o ataque e, depois, adicione 1 monstro "HERÓI do Elemento" do seu Deck à sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10774240,'Guardião Caveira, o Protetor da Voz Sem Voz',replace(replace('Você pode Invocar este card por Invocação-Ritual com "Orações da Voz Sem Voz". \r\nGanha 2050 de ATK enquanto você tiver "Lo, as Orações da Voz Sem Voz" no seu campo ou no seu Cemitério. \r\nVocê só pode usar cada um dos seguintes efeitos de "Guardião Caveira, o Protetor da Voz Sem Voz" uma vez por turno. \r\nSe este card for Invocado por Invocação-Ritual: você pode adicionar 1 monstro "Voz Sem Voz", ou 1 Monstro de Ritual (Guerreiro ou Dragão), do seu Deck à sua mão. \r\nQuando seu oponente ativar um card ou efeito enquanto você controlar "Lo, as Orações da Voz Sem Voz" (Efeito Rápido): você pode negar a ativação e, se isso acontecer, destrua esse card.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Negar a ativação','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10780049,'Compartir de Purrely!?',replace(replace('Escolha 1 Monstro Xyz "Purrely" que você controla; Invoque por Invocação-Especial do seu Deck 1 monstro "Purrely" de Nível 1, mas negue seus efeitos e, depois, Invoque por Invocação-Especial do seu Deck Adicional, 1 Monstro Xyz "Purrely" com a mesma Classe, mas um Atributo diferente que o do monstro alvo, usando esse monstro Invocado por Invocação-Especial como matéria. \r\n(Isso é considerado uma Invocação-Xyz.) \r\nDepois, você pode associar 1 card do seu Deck a esse monstro Invocado por Invocação-Xyz, com o mesmo nome que uma Magia Rápida "Purrely" associada ao monstro alvo.','\r',char(13)),'\n',char(10)),'','Usar o card com o mesmo nome de uma Matéria Xyz como Matéria Xyz?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10789972,'Chulainn, o Desperto',replace(replace('Este card só pode ser Invocado por Invocação-Ritual com o Card de Magia de Ritual "Emblema do Despertar". \r\nUma vez por turno, você pode remover de jogo 1 Monstro Normal no seu Cemitério. \r\nEste card ganha ATK igual ao ATK desse Monstro Normal, até a Fase de Apoio do seu próximo turno.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10793085,'Rugido da Tri-Brigada',replace(replace('Se você controlar um Monstro Link: envie 1 card "Tri-Brigada" do seu Deck ou Deck Adicional para o Cemitério e, depois, escolha 1 Monstro de Efeito no campo; aplique o seguinte efeito de acordo com o tipo de card enviado para o Cemitério.\r\n● Monstro: Mude o ATK do monstro alvo para 0 até o final deste turno.\r\n● Magia: Negue os efeitos desse monstro até o final deste turno.\r\n● Armadilha: Devolva esse monstro para a mão.	\r\nVocê só pode ativar 1 "Rugido da Tri-Brigada" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10796448,'Ás★Espadas Especulação',replace(replace('1 monstro com 2500 ou mais de ATK + 1 monstro com a face para baixo em Posição de Defesa com 2500 ou menos de DEF	\r\nVocê só pode Invocar um ou mais "Ás★Espadas Especulação" por Invocação-Especial uma vez por turno. \r\nVocê pode oferecer como Tributo 1 monstro em Posição de Ataque e 1 monstro com a face para baixo em Posição de Defesa; Invoque este card por Invocação-Especial do seu Cemitério. \r\nEste card ganha o seguinte efeito de acordo com sua posição de batalha.\r\n● Posição de Ataque: Ganha ATK igual ao maior ATK original dentre os monstros que seu oponente controla (em caso de empate, você seleciona).\r\n● Posição de Defesa: Não pode ser destruído em batalha ou por efeitos de card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10802915,'Guia de Excursão do Submundo','Quando este card for Invocado por Invocação-Normal: você pode Invocar por Invocação-Especial 1 monstro Demônio de Nível 3 da sua mão ou do Deck, mas negue seus efeitos e, além disso, ele não pode ser usado como Matéria Sincro.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10802916,'Guia de Excursão do Submundo','Quando este card for Invocado por Invocação-Normal: você pode Invocar por Invocação-Especial 1 monstro Demônio de Nível 3 da sua mão ou do Deck, mas negue seus efeitos e, além disso, ele não pode ser usado como Matéria Sincro.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10802917,'Guia de Excursão do Submundo','Quando este card for Invocado por Invocação-Normal: você pode Invocar por Invocação-Especial 1 monstro Demônio de Nível 3 da sua mão ou do Deck, mas negue seus efeitos e, além disso, ele não pode ser usado como Matéria Sincro.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10802918,'Guia de Excursão do Submundo','Quando este card for Invocado por Invocação-Normal: você pode Invocar por Invocação-Especial 1 monstro Demônio de Nível 3 da sua mão ou do Deck, mas negue seus efeitos e, além disso, ele não pode ser usado como Matéria Sincro.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10804018,'Saffira, o Dragão Divino da Voz Sem Voz',replace(replace('Você pode Invocar este card por Invocação-Ritual com "Bênção da Voz Sem Voz". \r\nSe este card for Invocado por Invocação-Ritual enquanto você tiver "Lo, as Orações da Voz Sem Voz" no seu campo ou no seu Cemitério: você pode comprar 2 cards e, depois, descartar 1 card. \r\nQuando um ataque for declarado envolvendo um Monstro de Ritual de LUZ (Guerreiro ou Dragão): você pode descartar 1 card aleatório da mão do seu oponente. \r\nDurante a Fase Final do seu oponente: você pode adicionar 1 monstro de LUZ do seu Cemitério à sua mão. \r\nVocê só pode usar cada efeito de "Saffira, o Dragão Divino da Voz Sem Voz" uma vez por turno.','\r',char(13)),'\n',char(10)),'Compre e depois descarte 1 card','Descarte aleatoriamente 1 card da mão do seu oponente','Adicione 1 monstro de LUZ do seu Cemitério à sua mão','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10805153,'Colaboração Fazticeira',replace(replace('Escolha 1 monstro "Fazticeira" que você controla; ele pode realizar um segundo ataque durante cada Fase de Batalha neste turno e, além disso, se ele atacou neste turno, seu oponente não pode ativar Cards de Magia/Armadilha até o final da Etapa de Dano. \r\nDurante sua Fase Final, se você controlar um monstro "Fazticeira", enquanto este card estiver no seu Cemitério: você pode adicionar este card à sua mão. \r\nVocê só pode usar 1 efeito de "Colaboração Fazticeira" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10807219,'Abelha Novata!',replace(replace('Se você tiver um monstro com 0 de ATK/DEF no seu Cemitério, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Abelha Novata!" por Invocação-Especial uma vez por turno desta forma. \r\nSe este card for Invocado por Invocação-Especial da mão: você pode aplicar esses efeitos em sequência.\r\n● Adicione 1 monstro Inseto de LUZ do seu Cemitério à sua mão, exceto "Abelha Novata!".\r\n● Coloque 1 das suas Armadilhas que estiverem banidas ou no seu Cemitério no topo ou no fundo do Deck.	\r\nVocê só pode usar este efeito de "Abelha Novata!" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Ativar o efeito','Adicionar aquele monstro à mão?','Retornar a Armadilha para o Deck?','Topo do Deck','Fundo do Deck','','','','','','','','','','');
INSERT INTO texts VALUES(10808715,'Corvo do Crepúsculo, o HERÓI Mascarado',replace(replace('Se este card estiver na sua mão: você pode banir 1 monstro "HERÓI" do seu Cemitério; Invoque este card por Invocação-Especial. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 monstro "HERÓI Mascarado" do seu Deck ou Cemitério à sua mão, exceto "Corvo do Crepúsculo, o HERÓI Mascarado". \r\nVocê só pode usar cada efeito de "Corvo do Crepúsculo, o HERÓI Mascarado" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10809984,'Grande Ladrão Fantasma','Se este card causar dano de batalha ao seu oponente: declare 1 nome de card; olhe a mão do seu oponente e, se isso acontecer, descarte todos os cards com esse nome na mão dele.','Declarar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10813327,'Despertar o Dragão','Se este card Baixado sob o controle do seu dono deixou o campo devido a um efeito do oponente e agora estiver no Cemitério ou banido: você pode Invocar por Invocação-Especial 1 monstro do seu Deck ou Deck Adicional.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10817524,'Primeiro dos Dragões',replace(replace('2 Monstros Normais	\r\nDeve ser Invocado por Invocação-Fusão e não pode ser Invocado por Invocação-Especial de nenhuma outra forma. \r\nVocê só pode controlar 1 "Primeiro dos Dragões". \r\nEste card não pode ser destruído em batalha, exceto ao batalhar um Monstro Normal e ele não é afetado pelos efeitos de outros monstros.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10833828,'Pacto Obscuro Ilegítimo com o Rei do Pântano',replace(replace('Uma vez por turno: você pode Invocar por Invocação-Especial 1 monstro "D/D/D" da sua mão em Posição de Defesa, mas seus efeitos são negados. \r\nUma vez por turno: você pode Invocar por Invocação-Fusão 1 Monstro de Fusão do Tipo Demônio do seu Deck Adicional, usando monstros da sua mão ou do campo como Matérias de Fusão, incluindo um monstro Invocado por Invocação-Especial por este card com o efeito acima. \r\nUma vez por turno, durante sua Fase de Apoio: sofra 2000 de dano.','\r',char(13)),'\n',char(10)),'Invocação Especial','Invocação Fusão','Dano de efeito','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10851853,'Dinoflor',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial por seu próprio efeito. \r\nVocê só pode usar cada um dos seguintes efeitos de "Dinoflor" uma vez por turno. \r\nSe você ativar um Card de Armadilha ou seus efeitos, ou se seu oponente ativar um Card de Magia ou seus efeitos: você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe este card for enviado para o Cemitério: você pode escolher 3 Magias/Armadilhas banidas; coloque-as no fundo dos Decks apropriados em qualquer ordem e, depois, compre 1 card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10852583,'Invasor Yajiro',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial em uma zona que não seja a Zona de Monstros Principal central, destrua este card. \r\nUma vez por turno: você pode mover este card para uma Zona de Monstros Principal não utilizada adjacente. \r\nSempre que exatamente 1 monstro for Invocado por Invocação-Normal ou Especial, no campo do seu oponente: mova este card para uma Zona de Monstros Principal adjacente mais próxima a desse monstro do oponente e, depois, destrua todos os outros cards na coluna deste card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10859908,'Holográ','Esta máquina gera ilusões que deixam um inimigo vulnerável a ataques.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10860121,'Bujingi Pavo',replace(replace('Quando um monstro "Bujin" do Tipo Besta-Guerreira que você controla for destruído em batalha e enviado para o Cemitério: você pode enviar este card da sua mão para o Cemitério; Invoque por Invocação-Especial 1 monstro "Bujin" do seu Deck. \r\nVocê só pode usar o efeito de "Bujingi Pavo" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10875327,'Imortal Terrestre Aslla piscu',replace(replace('Só pode haver 1 monstro "Imortal Terrestre" no campo. \r\nSe não houver Magias de Campo com a face para cima no campo, destrua este card. \r\nOs monstros do seu oponente não podem escolher este card como alvo de ataques. \r\nEste card pode atacar diretamente. \r\nSe este card com a face para cima deixar o campo, exceto por seu próprio efeito: destrua tantos monstros com a face para cima que seu oponente controla quanto possível e, se isso acontecer, cause 800 de dano ao seu oponente para cada monstro destruído.','\r',char(13)),'\n',char(10)),'Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10877309,'Ladrão do Tempo Desencadeado',replace(replace('Invoque por Invocação-Especial 1 monstro "Ladrão do Tempo" da sua mão. \r\nDurante sua Fase Principal: você pode banir este card do seu Cemitério e, depois, escolha 1 Monstro Xyz "Ladrão do Tempo" que você controla; associe 3 cards "Ladrão do Tempo" com tipos diferentes (1 Monstro, 1 Magia e 1 Armadilha) do seu Cemitério a esse monstro como matéria. \r\nVocê só pode usar 1 efeito de "Ladrão do Tempo Desencadeado" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10920352,'Vapor, o HERÓI Mascarado',replace(replace('Deve ser Invocado por Invocação-Especial com "Mudar a Máscara". 	\r\nNão pode ser destruído por efeitos de card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10925955,'Contato com o Aqua-espelhado',replace(replace('Se você controlar um monstro de ÁGUA: ative 1 desses efeitos ou, se você controlar um Monstro de Ritual de ÁGUA, você pode ativar esses dois efeitos, em sequência;\r\n● Olhe todos os cards Baixados na Zona de Magias & Armadilhas do seu oponente.\r\n● Olhe os 2 cards do topo do Deck de qualquer duelista e, depois, coloque-os no topo do Deck em qualquer ordem.','\r',char(13)),'\n',char(10)),'Verifique os cards Baixados na Zona de Magia & Armadilhas do seu oponente','Olhe os 2 cards do topo do Deck','Use ambos os efeitos','Verifique o seu Deck','Verifique o Deck do seu oponente','','','','','','','','','','','');
INSERT INTO texts VALUES(10928224,'Bebê Tigre Amazoness',replace(replace('O nome deste card se torna "Tigre Amazoness" enquanto ele estiver no campo ou no Cemitério. \r\nSe um monstro "Amazoness" for Invocado por Invocação-Normal ou Especial no seu campo enquanto este card estiver na sua mão ou no Cemitério: você pode Invocar este card por Invocação-Especial. \r\nVocê só pode usar este efeito de "Bebê Tigre Amazoness" uma vez por turno. \r\nGanha 100 de ATK para cada card "Amazoness" no seu Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10938846,'Ponte Arco-Íris do Coração',replace(replace('Durante sua Fase Principal, você pode Invocar por Invocação-Normal 1 monstro "Fera Cristalina", em adição à sua Invocação-Normal/Baixar (padrão). \r\n(Você só pode se aproveitar deste efeito uma vez por turno.) \r\nVocê só pode usar cada um dos seguintes efeitos de "Ponte Arco-Íris do Coração" uma vez por turno. \r\nDurante sua Fase Principal: você pode destruir 1 card "Fera Cristalina" que você controla ou na sua mão e, se isso acontecer, adicione 1 Magia/Armadilha "Cristalino(a)" do seu Deck à sua mão. \r\nSe um ou mais cards "Fera Cristalina" forem colocados na sua Zona de Magias & Armadilhas, mesmo durante a Etapa de Dano: você pode escolher 1 card que seu oponente controla; devolva tanto esse card quanto este card para a mão.','\r',char(13)),'\n',char(10)),'Invocar pelo efeito de "Ponte Arco-Íris do Coração"','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10949074,'Stratios, do Multiverso','Este deus da guerra do outro mundo pisou inúmeros campos de batalha sob os seus pés blindados. Se quer a glória dele, venha buscá-la!','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10960419,'Martelo da Magia do Tempo',replace(replace('Deve ser Invocado por Invocação-Especial com "A Garra de Hermos", usando um monstro Mago. 	\r\nSe este card for Invocado por Invocação-Especial: escolha 1 outro monstro com a face para cima no campo; equipe este card a ele. \r\nNo começo da Etapa de Dano, se ele batalhou um monstro do oponente: você pode lançar um dado de seis lados e banir esse monstro do oponente até a Fase de Apoio do turno N depois da ativação deste efeito (N = o resultado do dado).','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10963799,'Estátua Barreira da Torrente','Nenhum duelista pode Invocar monstros por Invocação-Especial, exceto monstros de ÁGUA.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10966439,'Marshmao☆Nhamy',replace(replace('Se você não controlar nenhum monstro, ou todos os monstros que você controla forem monstros Besta de LUZ: você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 Magia/Armadilha "Nhamy" do seu Cemitério à sua mão, ou, se este card foi Invocado por Invocação-Especial pelo efeito de um Monstro Sincro, em vez disso, você pode colocar 1 Magia de Campo "Nhamy" ou 1 Magia/Armadilha Contínua "Nhamy" do seu Deck ou banimento, com a face para cima no seu campo. \r\nVocê só pode usar cada efeito de "Marshmao☆Nhamy" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Efeito de recuperação','Colocar o Card Contínuo/Campo?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10971759,'Emergência Inseto',replace(replace('Escolha 2 monstros do Tipo Inseto de Nível 3 no seu Cemitério; Invoque-os por Invocação-Especial, mas seus efeitos são negados. \r\nVocê pode banir este card e 1 Monstro Xyz do seu Cemitério; até o final deste turno, os Níveis de todos os monstros do Tipo Inseto de Nível 3 que você controla atualmente se tornam iguais à Classe do monstro banido e, além disso, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros do Tipo Inseto. \r\nVocê só pode ativar 1 "Emergência Inseto" por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Alterar Nível','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10979723,'Tigre Amazoness',replace(replace('Você só pode controlar 1 "Tigre Amazoness". \r\nGanha 400 de ATK para cada monstro "Amazoness" que você controla. \r\nOs monstros do seu oponente não podem atacar monstros "Amazoness", exceto este.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10992251,'Gradius','Um piloto de jato de alta performance com cápsulas de energia para capacidades de ataque variáveis.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11012154,'Dragão-Guarda Justícia','O destino do Mundo depende dos Dragão-Guardas, nascidos do Legado Mundial.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11012887,'Guaiba Jurrac','Se este card destruir um monstro do oponente em batalha: você pode Invocar por Invocação-Especial 1 monstro "Jurrac" com 1700 ou menos de ATK do seu Deck, mas ele não pode declarar um ataque neste turno.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11020863,'Cortador da Sequência Real',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial com "Sequência Real". \r\nSe você tiver todos dentre "O Cavaleiro da Rainha", "O Cavaleiro do Rei" e "O Cavaleiro do Valete" no seu Cemitério: você pode enviar 5 monstros, com Níveis diferentes dentre 1, 2, 3, 4 e 5, da sua mão e/ou do Deck para o Cemitério e, se isso acontecer, destrua todos os cards que seu oponente controla. \r\nQuando este card for destruído em batalha: você pode escolher até 3 monstros Guerreiro de LUZ no seu Cemitério; Invoque-os por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Cortador da Sequência Real" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11021521,'Rei Neko Mane','Durante o turno do seu oponente, quando este card em sua posse for enviado para o seu Cemitério por um efeito de card do oponente: essa se torna a Fase Final deste turno.','Encerre o turno','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11024707,'Felino Virador',replace(replace('Se este card for enviado da mão ou do Deck para o Cemitério: você pode Invocá-lo por Invocação-Especial com a face para baixo em Posição de Defesa. \r\nDepois que este card foi virado com a face para cima, se um ou mais monstros forem enviados da mão e/ou do Deck para o seu Cemitério, enquanto este card estiver na Zona de Monstros: você pode escolher 1 deles; Invoque-o por Invocação-Especial com a face para baixo em Posição de Defesa. \r\nVocê só pode usar cada efeito de "Felino Virador" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11035075,'Shichi-Go-San',replace(replace('Invoque por Invocação-Especial 1 monstro de Nível/Classe 1 de qualquer Cemitério no seu campo e, se isso acontecer, equipe este card a ele. \r\nUma vez por turno, durante a Fase Final: aumente o Nível/Classe do monstro equipado em 1. \r\nAplique os seguintes efeitos de acordo com o Nível/Classe do monstro equipado.\r\n● 3+: Ele ganha ATK igual ao seu ATK original.\r\n● 5+: Ele não é afetado pelos efeitos ativados do seu oponente.	\r\nUma vez por turno, durante sua Fase de Apoio, se o Nível/Classe do monstro equipado for 7 ou mais: envie todos os cards no campo para o Cemitério.','\r',char(13)),'\n',char(10)),'Ativar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11039171,'Lobo Peladura',replace(replace('"Diabrete de Lâminas Afiadas" + 1 ou mais monstros "Fofanimal"	\r\nDeve ser Invocado por Invocação-Fusão com as Matérias de Fusão acima e não pode ser Invocado por Invocação-Especial de nenhuma outra forma. \r\nEste card pode atacar um número de vezes a cada Fase de Batalha, até o número de Matérias de Fusão usadas para sua Invocação-Fusão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11047543,'Zona de Sensações Psíquicas','Selecione 2 dos seus monstros removidos de jogo (1 Regulador do Tipo Psíquico e 1 não-Regulador do Tipo Psíquico), devolva-os para o Cemitério e Invoque por Invocação-Especial 1 Monstro Sincro do Tipo Psíquico do seu Deck Adicional com a face para cima em Posição de Defesa cujo Nível seja igual à soma dos Níveis dos monstros devolvidos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11050415,'Super Hipo Carnaval',replace(replace('Invoque por Invocação-Especial 1 "Hip Hipo Camarartista" da sua mão, Deck ou Cemitério e, depois, você pode Invocar por Invocação-Especial tantas "Fichas Hipo" (Tipo Besta/TERRA/Nível 1/ATK 0/DEF 0) quanto possível, mas elas não podem ser oferecidas como Tributo, e os monstros que seu oponente controla não podem escolher monstros como alvo de ataques pelo resto deste turno, exceto "Fichas Hipo". \r\nVocê não pode Invocar monstros por Invocação-Especial do Deck Adicional enquanto uma "Ficha Hipo" estiver em uma Zona de Monstros.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial o máximo possível de "Ficha Hipo"?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11050416,'Ficha Hipo',replace(replace('Invocado por Especial com o efeito "Hipo Carnaval" ou um card relacionado. \r\nEsta Ficha não pode ser oferecida como Tributo. \r\nVocê não pode Invocar monstros por Especial do Deck Adicional enquanto uma "Ficha Hipo" está em uma Zona de Monstros.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11050417,'Ficha Hipo',replace(replace('Invocado por Especial com o efeito "Hipo Carnaval" ou um card relacionado. \r\nEsta Ficha não pode ser oferecida como Tributo. \r\nVocê não pode Invocar monstros por Especial do Deck Adicional enquanto uma "Ficha Hipo" está em uma Zona de Monstros.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11050418,'Ficha Hipo',replace(replace('Invocado por Especial com o efeito "Hipo Carnaval" ou um card relacionado. \r\nEsta Ficha não pode ser oferecida como Tributo. \r\nVocê não pode Invocar monstros por Especial do Deck Adicional enquanto uma "Ficha Hipo" está em uma Zona de Monstros.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11050419,'Ficha Hipo',replace(replace('Invocado por Especial com o efeito "Hipo Carnaval" ou um card relacionado. \r\nEsta Ficha não pode ser oferecida como Tributo. \r\nVocê não pode Invocar monstros por Especial do Deck Adicional enquanto uma "Ficha Hipo" está em uma Zona de Monstros.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11052544,'Corte de Sabre','Destrua cards com a face para cima no campo igual ao número de monstros "Sabre-X" em Posição de Ataque que você controla.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11066358,'Serpente das Galáxias','Suas esperanças e sonhos serão renovados se você vislumbrar esta rara criatura durante o crepúsculo, pairando sobre o Mar das Estrelas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11067666,'Mago de Asas Brancas',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno, quando um card ou efeito ativado resolver que escolheu como alvo um monstro de TREVAS do Tipo Mago que você controla, negue o efeito e, depois, destrua este card.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\n(Este card deve ser sempre considerado como um card "Dragão Sincro".)	\r\nSe este card Invocado por Invocação-Pêndulo for usado para uma Invocação-Sincro, bana-o.','\r',char(13)),'\n',char(10)),'Usar o efeito de "Mago de Asas Brancas"?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11069680,'Conversor Sucata',replace(replace('Você pode descartar este card e 1 Regulador; adicione 1 monstro "Sincron" do seu Deck à sua mão. \r\nSe este card for enviado para o Cemitério como Matéria Sincro: você pode escolher 1 Regulador no seu Cemitério; Invoque-o por Invocação-Especial em Posição de Defesa, mas ele não pode ativar seus efeitos neste turno. \r\nVocê só pode usar cada efeito de "Conversor Sucata" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11074235,'Dragão de Mana Zirnitron',replace(replace('Se uma Magia/Armadilha que você controla deixar o campo devido a um efeito do oponente e agora estiver no Cemitério ou banida (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial do seu Cemitério (se ele estava lá quando essa Magia/Armadilha deixou o campo) ou da mão (mesmo se ele não estava) e, depois, você pode Baixar na sua Zona de Magias & Armadilhas, 1 Magia/Armadilha que estiver banida ou no seu Cemitério. \r\nVocê só pode usar este efeito de "Dragão de Mana Zirnitron" uma vez por turno. \r\nSe Invocado desta forma, bana este card quando ele deixar o campo.','\r',char(13)),'\n',char(10)),'','Baixar a Magia/Armadilha?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11082056,'A Presa de Critias',replace(replace('(Este card deve ser sempre considerado como "Dragão Lendário Critias".)	\r\nEnvie 1 Armadilha, que esteja listada em um Monstro de Fusão que só pode ser Invocado por Invocação-Especial com "A Presa de Critias", da sua mão ou do campo para o Cemitério (se esse card estiver Baixado, revele-o) e, depois, Invoque esse Monstro de Fusão por Invocação-Especial do seu Deck Adicional. \r\nVocê só pode ativar 1 "A Presa de Critias" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11091375,'Dragão do Brilho','Um lindo dragão coberto com safiras. Ele não gosta de lutar, mas tem um poder de ataque incrível.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11102908,'Castelo de Névoa de Shien','Quando um monstro "Seis Samurai" for atacado, o monstro atacante perde 500 de ATK apenas durante o cálculo de dano.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11109820,'Universo Xyz','Escolha 2 Monstros Xyz com a face para cima no campo; envie os dois monstros para o Cemitério e, depois, Invoque por Invocação-Especial 1 Monstro Xyz do seu Deck Adicional, exceto um monstro "Número", cuja Classe seja igual a, ou 1 menor que, a Classe original combinada desses 2 Monstros Xyz e, se isso acontecer, associe este card a ele como matéria e, além disso, pelo resto deste turno depois que este card resolver, seu oponente não sofre dano.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11110218,'Terrores da Raiz Inferior',replace(replace('Escolha até 5 cards no Cemitério do seu oponente e o mesmo número de cards banidos do seu oponente; bana os alvos do Cemitério dele e, se isso acontecer, devolva esses alvos banidos para o Cemitério. \r\nVocê só pode ativar 1 "Terrores da Raiz Inferior" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11110587,'Esse Jardim Parece Mais Verde','Se você tiver mais cards no seu Deck que seu oponente: envie cards do topo do seu Deck para o Cemitério até que você tenha o mesmo número de cards no seu Deck que seu oponente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11125718,'Dragonute Lanceiro','Caso este card ataque um monstro em Posição de Defesa, cause dano de batalha perfurante ao oponente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11132674,'Gigantesco "Campeão" Sargas',replace(replace('2+ monstros de Nível 8	\r\nUma vez por turno, você também pode Invocar "Gigantesco "Campeão" Sargas" por Invocação-Xyz ao usar 1 Monstro Xyz "Springans" que você controla. \r\n(Transfira as matérias dele para este card.) \r\nEnquanto este card tiver matéria: você pode adicionar 1 card "Springans" ou "Therion" do seu Deck à sua mão. \r\nSe uma matéria for desassociada de um ou mais monstros no campo (exceto durante a Etapa de Dano): você pode escolher 1 card no campo; destrua-o ou devolva-o para a mão. \r\nVocê só pode usar cada efeito de "Gigantesco "Campeão" Sargas" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Xyz usando o Monstro Xyz "Springans" como matéria?','','Destrua 1 card no campo, ou devolva-o para a mão do dono','Destruir','Retornar para a mão','','','','','','','','','','','');
INSERT INTO texts VALUES(11136371,'Contra Gema',replace(replace('Envie para o Cemitério todos os cards na sua Zona de Magias & Armadilhas. \r\nColoque tantos monstros "Fera Cristalina" quanto possível do seu Cemitério, com a face para cima na sua Zona de Magias & Armadilhas como Magias Contínuas. \r\nDurante a Fase Final deste turno, destrua todos os cards "Fera Cristalina" que você controla.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11155484,'Milagre Cristalino',replace(replace('Quando um Card de Magia/Armadilha, ou efeito de monstro, for ativado: destrua 1 card "Fera Cristalina" que você controla e, se isso acontecer, negue a ativação e, se isso acontecer, destrua esse card. \r\nSe um ou mais cards "Fera Cristalina" forem colocados na sua Zona de Magias & Armadilhas enquanto este card estiver no seu Cemitério, mesmo durante a Etapa de Dano: você pode banir este card; coloque 1 monstro "Fera Cristalina" da sua mão, do Deck ou do Cemitério, com a face para cima na sua Zona de Magias & Armadilhas como uma Magia Contínua. \r\nVocê só pode usar este efeito de "Milagre Cristalino" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11159464,'Lombriga Esperança',replace(replace('VIRE: Quando este card for virado com a face para cima por um ataque de monstro do oponente, compre 1 card.\r\nQuando este card for enviado do campo para o Cemitério, envie 1 card da sua mão ao Cemitério.','\r',char(13)),'\n',char(10)),'Enviar 1 card da sua mão para o Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11161666,'Sanaki, a Devota de Mikanko',replace(replace('Você pode escolher 1 card "Mikanko" que você controla; devolva-o para a mão. \r\nSe um Card de Equipamento se tornar equipado a este card: você pode Invocar por Invocação-Especial 1 monstro "Mikanko" não-Ilusão do seu Deck e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto monstros "Mikanko". \r\nSe este card for enviado para o Cemitério: você pode escolher 1 monstro com a face para cima no campo; equipe este card a ele como uma Magia de Equipamento. \r\nVocê só pode usar cada efeito de "Sanaki, a Devota de Mikanko" uma vez por turno.','\r',char(13)),'\n',char(10)),'Retornar para a mão','Invocação Especial','Equipar','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11163040,'Arquivo Kaiju',replace(replace('Sempre que um ou mais monstros "Kaiju" forem Invocados por Invocação-Especial da mão e/ou do Cemitério, coloque 1 Marcador Kaiju sobre este card (máx. 5). \r\nUma vez por turno: você pode escolher 1 monstro "Kaiju" no campo; destrua esse monstro e, depois, Invoque por Invocação-Especial do seu Deck, no campo do controlador dele, 1 monstro "Kaiju" com um nome original diferente. \r\nVocê pode enviar este card com 3 ou mais Marcadores Kaiju para o Cemitério; adicione 1 Magia/Armadilha "Kaiju" do seu Deck à sua mão, exceto "Arquivo Kaiju".','\r',char(13)),'\n',char(10)),'Invocação Especial','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11167052,'Treinamento Elemental',replace(replace('Seu oponente não pode escolher "Palácio do Senhor Elemental" que você controla como alvo de efeitos de card e, além disso, ele não pode ser destruído por efeitos de card. \r\nUma vez por turno: você pode oferecer 1 monstro como Tributo; Invoque por Invocação-Especial 1 monstro "Sabrelemento" do seu Deck com um Atributo original diferente que o desse monstro. \r\nVocê pode enviar este card com a face para cima do campo para o Cemitério; descarte toda a sua mão e, depois, adicione monstros "Senhor Elemental" do seu Cemitério à sua mão, igual ao número de cards descartados.','\r',char(13)),'\n',char(10)),'Invocação Especial','Recuperar do Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11193246,'Dança da Reencarnação Luzlunar',replace(replace('Se um ou mais monstros que você controla forem destruídos em batalha ou por um efeito de card: adicione até 2 monstros "Luzlunar" do seu Deck à sua mão. \r\nVocê só pode ativar 1 "Dança da Reencarnação Luzlunar" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11212437,'Draluvice, a Fortaleza do Dragão Diabólico','O destino final da caçadora que continuou a espalhar a mácula do dragão. Agora ela se tornou a fonte da praga, uma fortaleza de pensamentos sombrios e perversos e, ironicamente, agora é alvo da vingança de outros. Ela não tem como saber que a equipe de ataque à sua frente é formada pelos sobreviventes de uma vila que no passado foi dizimada por um dragão...','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11221418,'Bujincidente',replace(replace('Escolha 1 Monstro Xyz "Bujin" que você controla; bana-o e, se isso acontecer, devolva todos os monstros do campo para a mão. \r\nAté sua 2ª Fase Final depois da ativação, nenhum duelista pode Invocar monstros nem sofrer dano (mas pode Baixar de forma Normal). \r\nDurante sua 2ª Fase Final depois da ativação: escolha 1 monstro "Bujin" no seu Cemitério; Invoque por Invocação-Especial o monstro banido por este efeito e, se isso acontecer, associe o alvo a ele como uma Matéria Xyz.','\r',char(13)),'\n',char(10)),'Remova a restrição de Invocação','Invoque por Invocação Especial um monstro banido pelo efeito deste card','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11224103,'Horus, o Dragão da Chama Negra LV6',replace(replace('Este card não é afetado por efeitos de Magia. \r\nDurante a Fase Final, se este card destruiu um monstro em batalha neste turno: você pode enviar este card com a face para cima para o Cemitério; Invoque por Invocação-Especial 1 "Horus, o Dragão da Chama Negra LV8" da sua mão ou Deck.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11224934,'Espaço Reforçado','Cada Monstro Xyz com a face para cima que você controla ganha 300 de ATK para cada Matéria Xyz associada a ele até a Fase Final.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11228035,'Alma Xyz',replace(replace('Escolha 1 Monstro Xyz no Cemitério de qualquer duelista; todos os monstros que você controla atualmente ganham ATK igual à sua Classe x 200 e, depois, você pode embaralhá-lo no Deck Adicional. \r\nEste aumento de ATK dura até a Fase Final.','\r',char(13)),'\n',char(10)),'Retornar o monstro selecionado para o Deck Adicional?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11232355,'Destructotron',replace(replace('Você pode pagar 1000 PV e, depois, escolha 1 Magia/Armadilha Baixada que seu oponente controla; destrua o alvo. \r\nUma vez por turno, durante a Fase Final: destrua este card. \r\nEste card deve ser o único monstro Psíquico que você controla para ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Destruir um Card de Magia/Armadilha','Autodestruir-se','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11234702,'T.G. Serpente Hélice',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 monstro "T.G." de Nível 4 ou menos no seu Cemitério, exceto "T.G. Serpente Hélice"; Invoque esse monstro por Invocação-Especial, mas seus efeitos são negados. \r\nVocê pode banir este card do seu Cemitério e, depois, escolher 1 monstro "T.G." que você controla; até o final deste turno, aumente ou reduza o Nível dele em 1. \r\nVocê só pode usar cada efeito de "T.G. Serpente Hélice" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Aumentar o Nível em 1','Reduzir o Nível em 1','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11248645,'Alteza Arquidemônio',replace(replace('Se este card for Invocado por Invocação-Normal: você pode banir 1 card "Arquidemônio" do seu Cemitério; adicione 2 cards "Arquidemônio" do seu Deck à sua mão, exceto "Alteza Arquidemônio" e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto monstros "Arquidemônio". \r\nQuando um Monstro de Ritual seu for destruído em batalha enquanto este card estiver no seu Cemitério: você pode Invocar este card por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Alteza Arquidemônio" uma vez por turno.','\r',char(13)),'\n',char(10)),'Efeito de busca','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11250655,'Imperador da Terra e do Mar','Um monstro reptiliano que lança fogo em todas as direções.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11260714,'Senhor Obscuro da Vaidade','Quando este card for Invocado por Invocação-Especial do Cemitério: você pode escolher 1 monstro do Tipo Fada no seu Cemitério, exceto "Senhor Obscuro da Vaidade"; Invoque o alvo por Invocação-Especial.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11264180,'TGX1-HL','Escolha 1 monstro "T.G." que você controla; seu ATK/DEF se tornam metade do seu ATK/DEF atuais e, se isso acontecer, destrua 1 outra Magia/Armadilha no campo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11270236,'Elísio, o Invokado',replace(replace('1 monstro "Invokado(a)" + 1 monstro Invocado por Invocação-Especial do Deck Adicional	\r\nPrimeiro deve ser Invocado por Invocação-Fusão com as Matérias de Fusão acima. \r\nEnquanto estiver com a face para cima no campo, este card também é de Atributo TREVAS, TERRA, ÁGUA, FOGO e VENTO. \r\nUma vez por turno (Efeito Rápido): você pode escolher 1 monstro "Invokado(a)" que você controla ou no seu Cemitério; bana-o e todos os monstros que seu oponente controla com o mesmo Atributo que esse monstro.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11287364,'Cavaleiro de Ação Rápida','Se este card for enviado ao Cemitério para uma Invocação-Sincro: Escolha 1 monstro com a face para cima que seu oponente controla; o alvo perde 500 de ATK.','Reduzir ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11302671,'Analista Adamancipador',replace(replace('Se somente seu oponente controlar um monstro: você pode Invocar este card por Invocação-Especial da sua mão. \r\nDurante sua Fase Principal: você pode escavar os 5 cards do topo do seu Deck e, se isso acontecer, você pode Invocar por Invocação-Especial 1 monstro Rocha não-Regulador escavado de Nível 4 ou menos e, além disso, coloque o resto no fundo do seu Deck em qualquer ordem. \r\nVocê só pode usar cada efeito de "Analista Adamancipador" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Invocar por Invocação Especial o monstro?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11317977,'Ovelha Negra Luzlunar',replace(replace('Você pode descartar este card e, depois, ative 1 desses efeitos;\r\n● Adicione 1 monstro "Luzlunar" do seu Cemitério à sua mão, exceto "Ovelha Negra Luzlunar".\r\n● Adicione 1 "Polimerização" do seu Deck à sua mão.	\r\nSe este card for enviado para o Cemitério como matéria para uma Invocação-Fusão: você pode adicionar à sua mão, 1 Monstro Pêndulo "Luzlunar" com a face para cima do seu Deck Adicional ou 1 monstro "Luzlunar" do seu Cemitério, exceto "Ovelha Negra Luzlunar".','\r',char(13)),'\n',char(10)),'Recuperar do Cemitério','Procurar no Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11321089,'Guardião Quimera',replace(replace('3 monstros com nomes diferentes	\r\nPrimeiro deve ser Invocado por Invocação-Fusão usando apenas Matérias de Fusão da sua mão e do campo, com pelo menos 1 monstro de cada. \r\nSe este card for Invocado por Invocação-Fusão por um Card de Magia ou seus efeitos: você pode comprar cards igual ao número de cards usados como matéria da mão e, se isso acontecer, destrua cards que seu oponente controla igual ao número de cards usados como matéria do campo. \r\nVocê só pode usar este efeito de "Guardião Quimera" uma vez por turno. \r\nEnquanto "Polimerização" estiver no seu Cemitério, seu oponente não pode escolher este card como alvo de efeitos de card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11321183,'Lâmina Sombria','Dizem que ele é um guerreiro manipulador de dragões do mundo sombrio. O seu ataque é tremendo, usando as suas grandes espadas com poder malicioso.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11324436,'Serpente Elétrica','Quando este card for descartado da sua mão para o Cemitério pelo efeito de um card controlado por seu oponente, compre 2 cards do seu Deck.','Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11327848,'Diplomem de Mestrado',replace(replace('Se este card for Invocado por Invocação-Tributo: você pode escolher 1 monstro no seu Cemitério e 1 monstro com a face para cima que seu oponente controla; equipe o monstro do seu Cemitério a esse monstro do oponente. \r\nEnquanto estiver equipado por este efeito, o monstro equipado perde ATK igual ao ATK desse monstro equipado a ele. \r\nSeu oponente não pode ativar os efeitos de monstros que ele controla que estiverem equipados com Cards de Equipamento nas suas Zonas de Magias & Armadilhas.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11335209,'Duamutefe, a Bênção de Horus',replace(replace('Se você controlar "Sarcófago do Rei", você pode Invocar este card por Invocação-Especial (do seu Cemitério). \r\nVocê só pode Invocar "Duamutefe, a Bênção de Horus" por Invocação-Especial uma vez por turno desta forma. \r\nGanha 1200 de ATK/DEF para cada monstro "Horus" que você controla. \r\nSe um ou mais outros cards que você controla deixarem o campo por um efeito de card do oponente, enquanto este card estiver na sua Zona de Monstros (exceto durante a Etapa de Dano): você pode comprar cards igual ao número de monstros com nomes diferentes na sua Zona de Monstros Principal. \r\nVocê só pode usar este efeito de "Duamutefe, a Bênção de Horus" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11366199,'Simorgh, o Negro',replace(replace('Enquanto estiver com a face para cima no campo, este card também é de Atributo VENTO. \r\nSe este card estiver na sua mão: você pode banir 1 monstro de TREVAS e 1 de VENTO do seu Cemitério; Invoque este card por Invocação-Especial. \r\nSe este card estiver no seu Cemitério: você pode banir 1 monstro de TREVAS e 1 de VENTO da sua mão; Invoque este card por Invocação-Especial. \r\nSeu oponente não pode Baixar cards.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11373345,'Comprovação de Impotência',replace(replace('Ative apenas enquanto você controlar um monstro de Nível 7 ou mais com a face para cima. \r\nDestrua todos os monstros de Nível 5 ou menos com a face para cima que seu oponente controla. \r\nMonstros que você controla não podem atacar neste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11375683,'Trindade Tindângulo',replace(replace('VIRE: Você pode Invocar por Invocação-Especial 1 "Base Gardna Tindângulo" do seu Deck.\r\nSe este card foi virado com a face para cima, seus monstros "Tindângulo" não podem ser destruídos em batalha. \r\nSe este card for enviado para o Cemitério como Matéria Link para a Invocação-Link de um monstro "Tindângulo": você pode adicionar 1 "Fim de Gergonne" do seu Deck à sua mão e, se isso acontecer, envie 1 Magia/Armadilha do seu Deck para o Cemitério. \r\nVocê só pode usar este efeito de "Trindade Tindângulo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11384280,'Soldado Canhão','Ofereça 1 monstro no seu Campo como Tributo para infligir 500 pontos de dano aos Life Points do seu adversário.','Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11390349,'Mosca-da-Fruta de Naturia',replace(replace('Todos os monstros que seu oponente controla perdem 300 de ATK/DEF para cada monstro "Naturia" que você controla. \r\nUma vez por turno: você pode escolher 1 monstro que seu oponente controla com 0 de DEF; tome o controle do alvo até a Fase Final.','\r',char(13)),'\n',char(10)),'Tomar controle','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11398059,'Rei dos Diabretes Selvagens',replace(replace('2 monstros de Nível 4	\r\nUma vez por turno: você pode desassociar 1 matéria deste card; adicione 1 monstro Réptil do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11398951,'Ritual Absoluto Máquina de Anjo',replace(replace('Este card pode ser usado para a Invocação-Ritual de qualquer Monstro de Ritual "Ciber Anjo(a)". \r\nVocê também deve oferecer como Tributo monstros da sua mão ou do campo e/ou embaralhar no Deck monstros do Tipo Fada ou Guerreiro do seu Cemitério, cuja soma dos Níveis seja exatamente igual ao Nível do Monstro de Ritual que você Invocou por Invocação-Ritual.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11411223,'Número 10: Illumicavaleiro',replace(replace('3 monstros de Nível 4	\r\nUma vez por turno: você pode desassociar 1 Matéria Xyz deste card; envie 1 card da sua mão para o Cemitério e, se isso acontecer, compre 1 card.','\r',char(13)),'\n',char(10)),'Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11426487,'Corcel Branco dos Cavaleiros Florais',replace(replace('Se você controlar um monstro de Nível 2 ou menos, você pode Invocar este card por Invocação-Especial (da sua mão) em Posição de Defesa. \r\nVocê só pode Invocar "Corcel Branco dos Cavaleiros Florais" por Invocação-Especial uma vez por turno desta forma. \r\nQuando um monstro do oponente declarar um ataque: você pode banir este card do seu Cemitério e, depois, escolha 1 card que você controla; negue o ataque e, se isso acontecer, destrua o card alvo. \r\nVocê só pode usar este efeito de "Corcel Branco dos Cavaleiros Florais" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11429811,'Ponto de Aviso','Quando um ou mais monstros forem Invocados: neste turno, esse(s) monstro(s) com a face para cima não pode(m) atacar, seus efeitos são negados e, além disso, ele(s) não pode(m) ser usado(s) como matéria para uma Invocação-Fusão, Sincro, Xyz ou Link.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11434258,'Grilhões de Saryuja',replace(replace('Escolha 1 Monstro Link que seu oponente controla ou no Cemitério dele; compre cards igual ao Valor Link dele e, depois, se você tiver 2 ou mais cards na sua mão, coloque 2 cards da sua mão no fundo do seu Deck em qualquer ordem. \r\nVocê só pode ativar 1 "Grilhões de Saryuja" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11439455,'Gata Azul Luzlunar',replace(replace('Se este card for Invocado por Invocação-Especial: você pode escolher 1 monstro "Luzlunar" que você controla, exceto "Gata Azul Luzlunar"; até o final deste turno, seu ATK se torna o dobro do seu ATK original. \r\nVocê só pode usar este efeito de "Gata Azul Luzlunar" uma vez por turno. \r\nSe este card no campo for destruído em batalha ou por um efeito de card: você pode Invocar por Invocação-Especial 1 monstro "Luzlunar" do seu Deck.','\r',char(13)),'\n',char(10)),'Dobre o ATK dele','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11441009,'FEBRE P.U.N.K. JAM!',replace(replace('2 monstros de Nível 8	\r\nUma vez por turno, você também pode Invocar por Invocação-Xyz "FEBRE P.U.N.K. JAM!" ao usar um Monstro de Fusão ou Sincro "P.U.N.K." que você controla. \r\nVocê pode pagar 600 PV e, depois, desassocie 1 matéria deste card; compre 1 card. \r\nQuando outro efeito de monstro for ativado e você tiver um monstro Psíquico de Nível 3 no seu Cemitério (Efeito Rápido): você pode desassociar 1 matéria deste card; negue a ativação e, se isso acontecer, destrua esse monstro. \r\nVocê só pode usar cada efeito de "FEBRE P.U.N.K. JAM!" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Xyz sobrepondo um monstro de Fusão/Sincro "P.U.N.K."?','Comprar','Negar a ativação','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11443677,'Dragão Tirano de Olhos Azuis',replace(replace('"Dragão Branco de Olhos Azuis" + 1 monstro Dragão	\r\nPrimeiro deve ser Invocado por Invocação-Fusão, ou por Invocação-Especial do seu Deck Adicional ao oferecer como Tributo 1 "Dragão Branco de Olhos Azuis" equipado com um Monstro de Fusão. \r\nNão é afetado por Cards de Armadilha ou seus efeitos. \r\nPode atacar todos os monstros que seu oponente controla, uma vez cada. \r\nUma vez por turno, no final da Etapa de Dano, se este card batalhou: você pode escolher 1 Armadilha no seu Cemitério; Baixe-a.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11448373,'Protetor do Cemitério','Qualquer monstro destruído em batalha é embaralhado no Deck em vez de ser enviado para o Cemitério.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11449436,'Aqua Madoor Glacial',replace(replace('No começo da Etapa de Dano, se um Monstro Normal seu batalhar um monstro do oponente: você pode revelar este card na sua mão; descarte 1 card e, se isso acontecer, seu monstro não pode ser destruído nessa batalha. \r\nNo começo da Etapa de Dano, se este card batalhar um monstro do oponente: você pode revelar 1 Monstro Normal na sua mão; descarte 1 card e, se isso acontecer, destrua o monstro do oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11458071,'Flagelo dos Céus Enrise',replace(replace('Este card não pode ser Invocado por Invocação-Normal ou Baixado. \r\nEste card não pode ser Invocado por Invocação-Especial exceto ao remover de jogo 3 monstros de LUZ do Tipo Fada e 1 monstro de TREVAS do Tipo Demônio no seu Cemitério. \r\nUma vez por turno, você pode remover de jogo 1 monstro com a face para cima no campo. \r\nSe você ativar este efeito, este card não pode atacar durante este turno.','\r',char(13)),'\n',char(10)),'Banir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11460577,'Ciber Etoile','Se este card atacar diretamente, ele ganha 500 de ATK apenas durante a Etapa de Dano.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11464648,'Rextremende do Criademônio',replace(replace('1 Monstro de Fusão "Criademônio" + 1 Monstro de Fusão ou Link	\r\nNão é afetado por efeitos de card, exceto cards "Criademônio", enquanto estiver equipado com uma Magia de Equipamento "Criademônio". \r\nVocê só pode usar cada um dos seguintes efeitos de "Rextremende do Criademônio" uma vez por turno. \r\nSe este card for Invocado por Invocação-Fusão: você pode descartar 1 card; envie 1 monstro Demônio de LUZ do seu Deck ou Deck Adicional para o Cemitério. \r\nSe este card for enviado para o Cemitério: você pode escolher 1 outro card "Criademônio" no seu Cemitério ou banimento; adicione-o à sua mão.','\r',char(13)),'\n',char(10)),'Enviar para o Cemitério','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11471117,'Laser de Luz',replace(replace('Só pode ser equipado a um monstro de LUZ do Tipo Guerreiro. \r\nRemova de jogo qualquer monstro que batalhar com ele no final do Etapa de Dano.','\r',char(13)),'\n',char(10)),'Banir o alvo de batalha','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11475049,'Artefato Aquilescudo',replace(replace('Você pode Baixar este card da sua mão na sua Zona de Magias & Armadilhas como um Card de Magia. \r\nDurante o turno do seu oponente, se este card Baixado na Zona de Magias & Armadilhas for destruído e enviado para o seu Cemitério: Invoque-o por Invocação-Especial. \r\nSe este card for Invocado por Invocação-Especial durante o turno do seu oponente: seu oponente não pode atacar monstros "Artefato" que você controla pelo resto deste turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Restrição de ataque','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11481610,'Camarartista Surpresildo',replace(replace('Envie até 3 cards da sua mão para o Cemitério; compre esse número de cards e, depois, você pode Invocar por Invocação-Especial até esse mesmo número de monstros da sua mão, com nomes diferentes, que sejam monstros "Camarartista", Monstros Pêndulo "Mago" e/ou monstros "Olhos Anômalos", cada um com um Nível entre as Escalas de Pêndulo dos 2 cards nas suas Zonas de Pêndulo. \r\nSe você não Invocar por Invocação-Especial por este efeito, você perde 1000 PV para cada card na sua mão. \r\nVocê só pode ativar 1 "Camarartista Surpresildo" por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial da sua mão?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11489642,'Triângulo O',replace(replace('Se você controlar "Caveira de Cristal", "Pilar de Ashoka" e "Pedra de Cabrera": destrua todos os cards no campo e, além disso, pelo resto deste turno, seu oponente sofre qualquer dano de efeito que você teria sofrido, em vez de você. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 de cada de "Caveira de Cristal", "Pilar de Ashoka" e "Pedra de Cabrera" no seu Cemitério; embaralhe-os no Deck e, depois, compre 3 cards. \r\nVocê só pode usar 1 efeito de "Triângulo O" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Destruir todos os cards no Campo','Reciclar e comprar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11493868,'Fortíssimo',replace(replace('Uma vez por turno: você pode escolher 1 monstro "Melodiosa" que você controla; ele ganha 800 de ATK até sua próxima Fase de Apoio (mesmo que este card deixe o campo). \r\nVocê pode enviar este card para o Cemitério; Invoque por Invocação-Fusão 1 Monstro de Fusão "Melodiosa" do seu Deck Adicional, usando monstros que você controla como Matérias de Fusão.','\r',char(13)),'\n',char(10)),'Aumentar ATK','Invocação Fusão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11496832,'Principug',replace(replace('Você pode escolher 1 monstro que você controla com "Guardião" em seu nome original, que não possa ser Invocado por Invocação-Normal/Baixado; ele pode realizar um segundo ataque durante cada Fase de Batalha neste turno. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 monstro "Guardião" no seu Cemitério que não possa ser Invocado por Invocação-Normal/Baixado e ative 1 desses efeitos;\r\n● Adicione-o à sua mão.\r\n● Adicione do seu Cemitério à sua mão, 1 outro card que seja mencionado nesse monstro.	\r\nVocê só pode usar cada efeito de "Principug" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Adicione o monstro alvo à sua mão','Adicione à sua mão 1 outro card mencionado no monstro alvo do seu Cemitério','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11501629,'Chutar Fogo',replace(replace('Uma vez por turno, quando um ou mais monstros de FOGO com a face para cima que você controla forem destruídos por um efeito de card, coloque 1 marcador neste card para cada monstro de FOGO destruído. \r\nDurante a Fase de Apoio de qualquer duelista: você pode enviar este card para o Cemitério; cause 1000 de dano ao seu oponente para cada marcador neste card.','\r',char(13)),'\n',char(10)),'Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11502550,'Herói Elementar, Neos do Ar',replace(replace('"Elemental Hero Neos" + "Neo-Spacian Air Hummingbird"	\r\nEsta card somente pode ser Special Summoned do seu Extra Deck por retornar as cards citadas do seu lado do campo ao Deck ao Deck (Você não utiliza "Polymerization"). \r\nEnquanto os seus LPs estiverem menores que os LPs do seu oponente, esta card ganha ATK igual àquela diferença. \r\nEsta card retorna ao Extra Deck durante a End Phase.','\r',char(13)),'\n',char(10)),'Retornar ao Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11508758,'Mestre Mental Mutante',replace(replace('Quando este card declarar um ataque, você pode tomar o controle de 1 monstro com a face para cima em Posição de Ataque controlado pelo seu oponente e atacar com ele em vez deste monstro. \r\nEle não pode atacar diretamente seu oponente. \r\nDevolva-o ao seu oponente no fim da Fase de Batalha.','\r',char(13)),'\n',char(10)),'Tomar controle','Escolha um alvo de ataque','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11510448,'Tigremorteiro Zoodíaco',replace(replace('3 monstros de Nível 4	\r\nUma vez por turno, você também pode Invocar "Tigremorteiro Zoodíaco" por Invocação-Xyz ao usar 1 monstro "Zoodíaco(a)" que você controla com um nome diferente como Matéria Xyz. \r\n(Se você usou um Monstro Xyz, quaisquer Matérias Xyz associadas a ele também se tornam Matérias Xyz neste card.) \r\nEste card ganha ATK e DEF igual ao ATK e DEF de todos os monstros "Zoodíaco(a)" associados a ele como Matérias. \r\nUma vez por turno: você pode desassociar 1 Matéria Xyz deste card e, depois, escolher 1 Monstro Xyz que você controla e 1 monstro "Zoodíaco(a)" no seu Cemitério; associe esse monstro "Zoodíaco(a)" a esse Monstro Xyz como Matéria Xyz.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Xyz sobrepondo um monstro "Zoodíaco(a)"?','Associar Matéria Xyz','Escolha 1 Monstro Xyz','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11516241,'Gouki, O Ogro Potente',replace(replace('2+ monstros Guerreiro	\r\nGanha ATK igual ao Valor Link combinado de todos os outros Monstros Link que você controla x 200. \r\nEste card Invocado por Invocação-Link não é afetado por outros efeitos de cards. \r\nVocê pode oferecer como Tributo 1 Monstro Link "Gouki" e, depois, escolha cards no campo até seu Valor Link; destrua-os. \r\nVocê só pode usar este efeito de "Gouki, O Ogro Potente" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11522479,'Boxeador Obstinado de Gancho',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 monstro "Boxeador Obstinado" ou 1 Armadilha de Resposta "Contra" do seu Deck à sua mão, exceto "Boxeador Obstinado de Gancho". \r\nSe este card for enviado para o Cemitério por um efeito de card: você pode ativar 1 desses efeitos;\r\n● Invoque por Invocação-Especial 1 monstro "Boxeador Obstinado" do seu Cemitério, exceto "Boxeador Obstinado de Gancho".\r\n● Baixe 1 Armadilha de Resposta "Contra" do seu Cemitério no seu campo.	\r\nVocê só pode usar 1 efeito de "Boxeador Obstinado de Gancho" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','Invoque um monstro por Invocação Especial do Cemitério','Baixar 1 Armadilha de Resposta do Cemitério','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11522979,'Número C69: Símbolo Heráldico do Horror',replace(replace('4 monstros de Nível 5	\r\nQuando um monstro do oponente declarar um ataque: você pode destruir todos os cards que seu oponente controla. \r\nSe este card tiver "Número 69: Símbolo Heráldico" como uma Matéria Xyz, ele ganha este efeito.\r\n● Uma vez por turno: você pode desassociar 1 Matéria Xyz deste card e, depois, escolher 1 Monstro Xyz com a face para cima que seu oponente controla; este card ganha ATK igual ao ATK original desse monstro com a face para cima e, se ganhar ATK desta forma, o nome deste card se tornam o mesmo que o desse monstro e ele ganha o efeito original desse monstro.	\r\nEsses efeitos duram até a Fase Final.','\r',char(13)),'\n',char(10)),'Destruir','Obter o efeito','Terminar o efeito copiado','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11548522,'Cão Marron Fantástico','Quando este card for enviado para o seu Cemitério: embaralhe-o no seu Deck.','Retornar ao Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11549357,'Gama, o Guerreiro Ímã','Alfa, Beta e Gama se juntam em um para formar um monstro poderoso.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11556339,'Montarias Besta Espiritual','Se você controlar um monstro "Besta Espiritual": destrua monstros no campo até o número de monstros "Besta Espiritual" que você controlar atualmente.','Destruir um monstro','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11587414,'O Verdadeiro Deus Sol',replace(replace('Quando este card for ativado: adicione 1 "O Dragão Alado de Rá" ou 1 card que o mencione do seu Deck à sua mão, exceto "O Verdadeiro Deus Sol". \r\nMonstros, exceto "O Dragão Alado de Rá", não podem atacar no turno em que forem Invocados por Invocação-Especial. \r\nUma vez por turno, durante sua Fase Principal: você pode enviar para o Cemitério este card do campo, ou 1 "Dragão Alado de Rá - Fênix" do seu Deck e, depois, envie 1 "O Dragão Alado de Rá" da sua Zona de Monstros para o Cemitério. \r\nVocê só pode ativar 1 "O Verdadeiro Deus Sol" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11590299,'Dora Dora',replace(replace('Se este card for Invocado por Invocação-Normal: você pode adicionar 1 monstro Dragão de FOGO de Nível 4 ou menos do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Dora Dora" uma vez por turno. \r\nUma vez por turno, durante sua Fase Principal: você pode escavar o card do topo do seu Deck e, se for um monstro Dragão de FOGO, envie-o para o Cemitério e, se isso acontecer, este card ganha 1000 de ATK para cada "Dora Dora" que você controla. \r\nCaso contrário, coloque o card escavado no fundo do seu Deck.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Revele o card do topo do Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11593137,'Buraco Armadilha Caótico','Quando um ou mais monstros de LUZ ou de TREVAS seriam Invocados: pague 2000 PV; negue a Invocação dos monstros de LUZ e de TREVAS e, se isso acontecer, bana-o.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11596936,'Poder Avassalador',replace(replace('Revele 1 "Núcleo de Ferro de Koa''ki Meiru" na sua mão. \r\nDestrua todos os Cards de Magia e Armadilha com a face para baixo que seu oponente controla.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11609969,'D/D Kepler, o Erudito',replace(replace('Escala de Pêndulo = 10\r\n[ Efeito de Pêndulo ]\r\nVocê não pode Invocar monstros por Invocação-Pêndulo, exceto monstros "D/D". \r\nEste efeito não pode ser negado. \r\nUma vez por turno, durante sua Fase de Apoio: reduza a Escala de Pêndulo deste card por 2 (mín. 1) e, depois, destrua todos os monstros que você controla com um Nível igual ou maior que a Escala de Pêndulo deste card, exceto monstros "D/D".\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode ativar 1 desses efeitos. \r\nVocê só pode usar este efeito de "D/D Kepler, o Erudito" uma vez por turno.\r\n● Escolha 1 outro card "D/D" que você controla; devolva-o para a mão.\r\n● Adicione 1 card "Pacto Obscuro" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Retornar para a sua mão 1 card "D/D" que você controla','Adicione 1 card "Pacto Obscuro" do seu Deck à sua mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11613567,'Asanegra - Elphin, o Corvo',replace(replace('Se você controlar um monstro "Asanegra", você pode Invocar este card por Invocação-Normal sem oferecer Tributo. \r\nQuando este card for Invocado por Invocação-Normal: você pode escolher 1 monstro que seu oponente controla; mude a posição de batalha do alvo.','\r',char(13)),'\n',char(10)),'Invocação Normal sem Tributo','Mudar a posição de batalha','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11637481,'U.A. Líbero Cortador',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) ao devolver 1 monstro "U.A." que você controla para a mão, exceto "U.A. Líbero Cortador". \r\nVocê só pode Invocar "U.A. Líbero Cortador" por Invocação-Especial uma vez por turno desta forma. \r\nDurante a Fase Principal do seu oponente (Efeito Rápido): você pode embaralhar no Deck 1 monstro "U.A." de Nível 5 ou mais da sua mão e, se isso acontecer, Invoque por Invocação-Especial 1 monstro "U.A." do seu Deck com um nome diferente e, depois, devolva este card para a mão. \r\nVocê só pode usar este efeito de "U.A. Líbero Cortador" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11642993,'Classificação Mundial Força-S',replace(replace('Se um monstro "Força-S" que você controla baniria um ou mais cards da sua mão para ativar seu efeito, em vez disso, você pode enviar 1 card "Força-S" do seu Deck para o Cemitério, exceto "Classificação Mundial Força-S". \r\nSe um ou mais outros cards forem banidos (exceto durante a Etapa de Dano): você pode escolher 1 card no campo ou Cemitério do seu oponente; bana-o e, depois, você pode mover 1 monstro "Força-S" que você controla para outra das suas Zonas de Monstros Principais. \r\nVocê só pode usar cada efeito de "Classificação Mundial Força-S" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Banir','Mover para outra zona?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11646785,'Besta Mech Super Quantal Aeroboros',replace(replace('2 monstros de Nível 4	\r\nNão pode atacar a não ser que tenha Matéria Xyz. \r\nUma vez por turno: você pode desassociar 1 Matéria Xyz deste card e, depois, escolher 1 outro monstro com a face para cima no campo; coloque-o com a face para baixo em Posição de Defesa. \r\nSe este card tiver "Camada Verde Super Quantum" como Matéria Xyz, este efeito pode ser ativado durante o turno de qualquer duelista. \r\nUma vez por turno: você pode associar 1 monstro "Super Quantum" da sua mão ou do campo a este card como uma Matéria Xyz.','\r',char(13)),'\n',char(10)),'Posição de Defesa com a face para baixo','Matéria Xyz','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11654067,'Ejeção de Fogo',replace(replace('Envie 1 monstro Piro do seu Deck para o Cemitério e, depois, se você enviar um monstro "Vulcânico(a)" para o Cemitério, você pode aplicar 1 desses efeitos.\r\n● Cause dano ao seu oponente igual ao seu Nível x 100.\r\n● Invoque por Invocação-Especial 1 "Ficha de Bomba" (Piro/FOGO/Nível 1/ATK 1000/DEF 1000) no campo do seu oponente.	\r\nSempre que 1 for destruído, seu controlador sofre 500 de dano.\r\nVocê só pode ativar 1 "Ejeção de Fogo" por turno.','\r',char(13)),'\n',char(10)),'Cause dano ao seu oponente','Invocar uma Ficha por Invocação Especial','Não fazer nada','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11654068,'Ficha de Bomba','Invocado por Especial com o efeito "Soldado Vulcânico" ou um card relacionado. Quando destruída, o controlador sofre 500 de dano.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11662742,'Gellenduo',replace(replace('Não pode ser destruído em batalha. \r\nSe você sofrer qualquer dano: destrua este card com a face para cima. \r\nEste card pode ser considerado como 2 Tributos para a Invocação-Tributo de um monstro Fada de LUZ.','\r',char(13)),'\n',char(10)),'Autodestruir-se','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11674673,'Bruxa Ciberso',replace(replace('2 monstros Ciberso	\r\nSe um monstro for Invocado por Invocação-Especial em uma zona para a qual este card apontar (exceto durante a Etapa de Dano): você pode banir 1 Magia do seu Cemitério; adicione 1 Monstro de Ritual Ciberso e 1 "Cinet Ritual" do seu Deck à sua mão. \r\nDurante sua Fase Principal, se este efeito foi ativado neste turno: você pode escolher 1 monstro Ciberso de Nível 4 ou menos no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Bruxa Ciberso" uma vez por turno.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Invoque por Invocação Especial do Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11677278,'Armadura Mimicarniçal',replace(replace('VIRE: Se for a Fase Principal: aplique esses efeitos em sequência.\r\n● Neste turno, monstros "Mimicarniçal" não podem ser destruídos em batalha.\r\n● Conceda o controle deste card ao seu oponente.	\r\nDurante sua Fase Principal: você pode Invocar este card por Invocação-Especial da sua mão no campo do seu oponente com a face para baixo em Posição de Defesa ou, se seu oponente controlar um monstro, você pode Invocar este card por Invocação-Especial com a face para cima no seu campo. \r\nVocê só pode usar cada efeito de "Armadura Mimicarniçal" uma vez por turno.','\r',char(13)),'\n',char(10)),'Efeito de Virar','Invocação Especial','Invocar por Invocação Especial para o seu Campo','Invocar por Invocação Especial para o Campo do seu oponente','','','','','','','','','','','','');
INSERT INTO texts VALUES(11678191,'Alma Protetora Ailin',replace(replace('Uma vez por turno, durante a sua Main Phase, você pode equipar este card a "Guerreiro Indomável Lei Lei" como um Card de Equipamento, OU separar o Equipamento e Invocar, por Invocação-Especial, este card em Posição de Ataque com a face para cima. \r\nQuando este card é equipado pelo efeito deste card, você pode mudar a posição de batalha do monstro equipado uma vez por turno durante a sua Main Phase. \r\n(1 monstro pode ser equipado apenas por 1 Monstro de Union de cada vez. Se o monstro equipado com este card é destruído como resultado de um combate, em vez disso destrua este card.)','\r',char(13)),'\n',char(10)),'Equipar','Desequipar e Invocar por Invocação Especial (Posição de Ataque com a face para cima)','Altere a posição de batalha do monstro equipado','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11682713,'Lâmina Defensora Silvestre',replace(replace('Quando este card destruir um monstro do oponente em batalha e enviá-lo para o Cemitério: você pode escavar o card do topo do seu Deck e, se ele for um monstro do Tipo Planta, envie-o para o Cemitério. \r\nCaso contrário, coloque-o no fundo do seu Deck. \r\nSe este card for escavado do Deck e enviado para o Cemitério por um efeito de card: você pode adicionar este card do seu Cemitério para a sua mão.','\r',char(13)),'\n',char(10)),'Escave cards do seu Deck','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11685347,'Asmodaico Explosivo','Se quaisquer Cards de Magia ou Armadilha estiverem em Corrente, cause 500 de dano ao seu oponente.','Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11688916,'Solfacorde Primoa',replace(replace('Escala de Pêndulo = 0\r\n[ Efeito de Pêndulo ]\r\nQuando você Invocar por Invocação-Pêndulo: você pode escolher 1 card "Solfacorde" na sua Zona de Pêndulo; devolva-o para a mão.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nEnquanto você tiver cards "Solfacorde" nas suas duas Zonas de Pêndulo (1 com Escala de Pêndulo ímpar e 1 par), os efeitos ativados dos seus cards "Solfacorde" não podem ser negados. \r\nVocê só pode usar cada um dos seguintes efeitos de "Solfacorde Primoa" uma vez por turno. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 card "Solfacorde" do seu Deck à sua mão, exceto "Solfacorde Primoa". \r\nSe você Invocar um monstro "Solfacorde" por Invocação-Link: você pode adicionar 1 card "Solfacorde" do seu Deck Adicional com a face para cima ou Cemitério à sua mão.','\r',char(13)),'\n',char(10)),'Retornar para a mão','Efeito de busca','Efeito de recuperação','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11699941,'Óleo Gama Karakuri',replace(replace('Ative este card ao escolher 1 monstro "Karakuri" no seu Cemitério; Invoque-o por Invocação-Especial e equipe-o com este card. \r\nUma vez por turno, se a posição de batalha de um ou mais monstros "Karakuri" com a face para cima que você controla for mudada: o monstro equipado ganha 500 de ATK/DEF (mesmo que este card não esteja mais equipado). \r\nVocê só pode ativar 1 "Óleo Gama Karakuri" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11705261,'Mudança de Tática Xyz',replace(replace('Quando um monstro "Utopia" for Invocado por Invocação-Xyz no seu campo: você pode pagar 500 PV; compre 1 card. \r\nVocê só pode controlar 1 "Mudança de Tática Xyz".','\r',char(13)),'\n',char(10)),'Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11711438,'Saga dos Guerreiros Antigos - Três Visitas',replace(replace('Durante sua Fase Principal, se você Invocar por Invocação-Normal ou Especial um ou mais monstros "Guerreiros Antigos": você pode escolher 1 desses monstros; adicione 1 monstro "Guerreiros Antigos" com um nome diferente do seu Deck à sua mão. \r\nSe este card for enviado da Zona de Magias & Armadilhas para o Cemitério: você pode Invocar por Invocação-Especial 1 monstro "Guerreiros Antigos" da sua mão. \r\nVocê só pode usar cada efeito de "Saga dos Guerreiros Antigos - Três Visitas" uma vez por turno. \r\nEnvie este card para o Cemitério durante sua 2ª Fase de Apoio depois da ativação.','\r',char(13)),'\n',char(10)),'','Procurar no Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11714098,'Tartaruga-Branca de 30.000 Anos','Uma enorme tartaruga que existe há mais de 30.000 anos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11722335,'Lombriga Xex',replace(replace('Quando este card for Invocado por Invocação-Normal, você pode enviar 1 monstro "Lombriga" do Tipo Réptil do seu Deck para o Cemitério. \r\nSe você controlar um "Lombriga Yagan" com a face para cima, este card não pode ser destruído em batalha.','\r',char(13)),'\n',char(10)),'Enviar para o Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11738489,'A Chegada Ciberso @Ignister',replace(replace('3+ monstros com Atributos diferentes	\r\nVocê só pode controlar 1 "A Chegada Ciberso @Ignister". \r\nO ATK original deste card se torna 1000 x o número de Matérias Link usadas para sua Invocação-Link. \r\nNão é afetado por outros efeitos de cards. \r\nUma vez por turno: você pode escolher 1 outro monstro no campo; destrua-o e, se isso acontecer, Invoque por Invocação-Especial 1 "Ficha @Ignister" (Ciberso/TREVAS/Nível 1/ATK 0/DEF 0) em uma zona sua para a qual este card apontar.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11738490,'Ficha @Ignister','Invocado por Especial com o efeito "A Chegada Ciberso @Ignister" ou um card relacionado.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11741041,'Garrafa Raigeki',replace(replace('Sempre que um monstro que você controla declarar um ataque, coloque 1 Marcador de Trovão neste card. \r\nVocê pode enviar este card com 4 ou mais Marcadores de Trovão para o Cemitério; destrua todos os monstros que seu oponente controla.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11743119,'Montador Union',replace(replace('Você pode pegar num Monstro de Union que é actualmente um monstro no Campo do seu adversário, e equipá-lo a este card. \r\nEste monstro pode apenas ser equipado por 1 Monstro de Union de cada vez. \r\nO Monstro de Union que está equipado a este card não pode ser devolvido a monstro usando o seu próprio efeito.','\r',char(13)),'\n',char(10)),'Equipar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11747708,'Esporo',replace(replace('Se este card estiver no seu Cemitério: você pode banir 1 outro monstro Planta do seu Cemitério; Invoque este card por Invocação-Especial e, se isso acontecer, aumente o seu Nível pelo Nível do monstro banido. \r\nVocê só pode usar este efeito de "Esporo" uma vez por Duelo.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11755663,'Dinolutador Marcial Anga',replace(replace('Durante o cálculo de dano, quando um monstro "Dinolutador" seu batalhar um monstro de ATK igual ou maior (Efeito Rápido): você pode enviar este card da sua mão para o Cemitério; seu monstro que está batalhando não pode ser destruído nessa batalha e, além disso, encerre a Fase de Batalha depois da Etapa de Dano. \r\nUma vez por turno, durante a Fase Final, se este card estiver no Cemitério porque foi enviado para lá para ativar este efeito neste turno e seu oponente controlar mais monstros que você: você pode Invocar este card por Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11759079,'Pés dos Dois Avatares - Kokoku',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 Armadilha "Dois Avatares" do seu Deck à sua mão. \r\nDurante o turno do seu oponente, se um ou mais monstros "Dois Avatares" com a face para cima que você controla, exceto "Pés dos Dois Avatares - Kokoku", forem destruídos em batalha ou por um efeito de card: você pode Invocar este card por Invocação-Especial da sua mão e, depois, você pode aplicar este efeito.\r\n● Destrua 1 monstro "Dois Avatares" que você controla e, se isso acontecer, Invoque por Invocação-Especial 1 Monstro de Fusão "Dois Avatares" do seu Deck Adicional.	\r\nVocê só pode usar cada efeito de "Pés dos Dois Avatares - Kokoku" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial da mão','Adicione 1 Armadilha "Dois Avatares" à sua mão','Destruir o monstro e Invocar um Monstro Fusão por Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11760174,'Samurai Sasuke nº 2',replace(replace('Uma vez por turno, durante a sua Main Phase, você pode pagar 800 Life Points. \r\nSe o fizer, Cards de Magia e Armadilha não podem ser activados até à End Phase.','\r',char(13)),'\n',char(10)),'Restrição de ativação','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11761845,'Besta de Talwar',replace(replace('Apenas os mestres espadachim entre os monstros do Tipo Demônio podem brandir a Talwar.	\r\n\r\n(Este card deve ser sempre considerado como um card "Arquidemônio".)','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11765832,'Garura, Asas da Vida Ressonante',replace(replace('2 monstros com o mesmo Tipo e Atributo, mas com nomes diferentes	\r\nQualquer dano de batalha que seu oponente sofrer das batalhas envolvendo este card é dobrado. \r\nSe este card for enviado para o Cemitério: você pode comprar 1 card. \r\nVocê só pode usar este efeito de "Garura, Asas da Vida Ressonante" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11790356,'Dragão Notável',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nTodos os monstros que seu oponente controla se tornam Dragão. \r\nUma vez por turno, se você não controlar um monstro "Blader Notável": você pode escolher 1 "Blader Notável" no seu Cemitério; Invoque-o por Invocação-Especial. \r\nUma vez por turno do oponente (Efeito Rápido): você pode escolher 1 monstro "Blader Notável" que você controla; equipe-o com 1 monstro "Espada da Destruição" do seu Cemitério.','\r',char(13)),'\n',char(10)),'Invocação Especial','Equipar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11793047,'Ovo de Górgona','Dizem que os impressionantes olhos do Ovo de Górgona refletem o destino de seus inimigos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11801343,'Coletor de Lixo',replace(replace('Você pode escolher 1 outro monstro Ciberso que você controla que começou o Duelo no Deck Principal; devolva-o para a mão e, se isso acontecer, Invoque por Invocação-Especial do seu Deck 1 monstro Ciberso com o mesmo Nível, mas com um nome diferente. \r\nVocê só pode usar este efeito de "Coletor de Lixo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11802691,'A Epopeia Contínua de Charles',replace(replace('Revele 1 Magia de Equipamento "Armas Nobres" na sua mão e, se isso acontecer, Invoque por Invocação-Especial 1 monstro "Infernobre Cavaleiro" da sua mão ou do Deck e, depois, equipe o card revelado a esse monstro ou envie-o para o Cemitério. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 "Infernobre Cavaleiro Imperador Charles" que você controla; equipe 1 monstro "Nobre Cavaleiro" da sua mão ou do Deck a esse monstro como uma Magia de Equipamento que concede a ele 500 de ATK. \r\nVocê só pode usar cada efeito de "A Epopeia Contínua de Charles" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Equipar a aquele monstro','Enviar para o Cemitério','','','','','','','','','','','','');
INSERT INTO texts VALUES(11808215,'Masmorra de Dados',replace(replace('Quando este card for ativado: você pode adicionar 1 "Dado Dimensional" do seu Deck à sua mão. \r\nNo começo da Fase de Batalha: você pode ativar este efeito; cada duelista lança um dado de seis faces e, até o final deste turno, aplica o resultado a todos os monstros que ele controla.\r\n● 1: Perde 1000 de ATK.\r\n● 2: Ganha 1000 de ATK.\r\n● 3: Perde 500 de ATK.\r\n● 4: Ganha 500 de ATK.\r\n● 5: Diminui seu ATK pela metade.\r\n● 6: Dobra seu ATK.','\r',char(13)),'\n',char(10)),'Adicionar 1 "Dado Dimensional" do seu Deck à sua mão?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11813722,'Cortiça de Cortiz',replace(replace('Só pode ser ativado se você controlar um monstro "Naturia" com a face para cima. \r\nSeu oponente não pode ativar Cards de Armadilha neste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11813953,'Grande Angus','Uma besta muito violenta, está sempre furioso. As pessoas dizem que nunca o viram em silêncio.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11819473,'Leitura Arcana',replace(replace('Lance uma moeda e aplique este efeito. \r\nSe "Barreira de Luz" estiver na sua Zona do Campo, em vez disso, você pode selecionar o efeito.\r\n● Cara: Adicione 1 card do seu Deck à sua mão que tenha um efeito de lançar moedas, exceto "Leitura Arcana".\r\n● Coroa: Seu oponente adiciona 1 card do Deck dele à mão dele.	\r\nVocê pode banir este card do seu Cemitério; imediatamente depois que este efeito resolver, Invoque por Invocação-Normal 1 monstro "Força Arcana".\r\nVocê só pode usar cada efeito de "Leitura Arcana" uma vez por turno.','\r',char(13)),'\n',char(10)),'Jogar uma moeda','Invocar','Cara: Adicione 1 card com um efeito de lançar moeda do seu Deck à sua mão','Coroa: Seu oponente adiciona 1 card do Deck dele à mão dele','','','','','','','','','','','','');
INSERT INTO texts VALUES(11819616,'Tytannial, Princesa das Camélias','Quando um card ou efeito for ativado que escolha como alvo um ou mais cards no campo (Efeito Rápido): você pode oferecer como Tributo 1 monstro Planta com a face para cima; negue a ativação e, se isso acontecer, destrua-o.','Negar a ativação e destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11825276,'Meizen, o Ninja de Batalha',replace(replace('2 monstros "Ninja" com Tipos diferentes	\r\nPrimeiro deve ser Invocado por Invocação-Fusão, ou por Invocação-Especial do seu Deck Adicional ao oferecer como Tributo os cards acima que você controla. \r\nSeus monstros "Ninja" podem atacar diretamente. \r\nEnquanto você controlar um monstro com a face para baixo em Posição de Defesa, os monstros do seu oponente não podem escolher este card como alvo de ataques. \r\nQuando seu oponente ativar um card ou efeito (Efeito Rápido): você pode Invocar por Invocação-Especial 1 monstro "Ninja" do seu Deck com a face para cima ou com a face para baixo em Posição de Defesa. \r\nVocê só pode usar este efeito de "Meizen, o Ninja de Batalha" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11827244,'Fusão Magicalizada',replace(replace('Invoque por Invocação-Fusão 1 Monstro de Fusão Mago do seu Deck Adicional, ao banir suas matérias do seu campo ou Cemitério. \r\nVocê só pode ativar 1 "Fusão Magicalizada" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11830996,'Folha Antiga','Se você tiver 9000 PV ou mais, você pode pagar 2000 PV para comprar 2 cards.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11834972,'Disparador Laval','Quando este card for Invocado por Invocação-Normal, se você tiver um monstro "Laval" no seu Cemitério que não seja "Disparador Laval": Você pode escolher um número de 1 a 5 e, depois, enviar essa quantidade de cards do topo do seu Deck ao Cemitério; este card ganha 200 de ATK para cada monstro "Laval" enviado ao Cemitério para ativar este efeito.','Aumentar ATK','Escolha a quantidade de cards para enviar ao Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11845050,'Tubarão de Mão-Direita',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode adicionar 1 "Tubarão de Mão-Esquerda" do seu Deck à sua mão. \r\nSe este card estiver no seu Cemitério e você não controlar nenhum monstro: você pode Invocar este card por Invocação-Especial, mas bana-o quando ele deixar o campo. \r\nUm Monstro Xyz que foi Invocado usando apenas monstros de ÁGUA como matéria, incluindo este card no campo, ganha este efeito.\r\n● Este card não pode ser destruído em batalha.	\r\nVocê só pode usar cada efeito de "Tubarão de Mão-Direita" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','O efeito de "Tubarão de Mão-Direita" está sendo aplicado.','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11851647,'Saraivada do Cupido',replace(replace('Você pode selecionar um número de 1 a 3 e, depois, enviar esse número de cards do topo do seu Deck para o Cemitério; até o final deste turno, aumente o Nível deste card pelo número de cards enviados para o Cemitério desta forma. \r\nSe este card que você controla for destruído por um card do oponente e enviado para o seu Cemitério: você ganha 1500 PV. \r\nVocê só pode usar cada efeito de "Saraivada do Cupido" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Escolha a quantidade de cards para enviar ao Cemitério','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11852093,'D/D/D Alfredo, o Rei Sábio Divino',replace(replace('2 monstros "D/D"	\r\nDurante sua Fase Principal: você pode Invocar por Invocação-Fusão 1 Monstro de Fusão "D/D/D" do seu Deck Adicional, ao embaralhar no Deck suas matérias da sua mão, do campo e/ou do banimento. \r\nSe este card for banido: você pode escolher Magias/Armadilhas Contínuas "Pacto Obscuro" no seu Cemitério e/ou banimento, até o número de monstros "D/D/D" que você controla; coloque-os com a face para cima no seu campo. \r\nVocê só pode usar cada efeito de "D/D/D Alfredo, o Rei Sábio Divino" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Fusão','Colocar com a face para cima','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11868731,'Magileine Magidoce',replace(replace('Se este card em sua posse for destruído por um card do oponente e enviado para o seu Cemitério: embaralhe este card no Deck. \r\nQuando este card for Invocado por Invocação-Normal ou Virar: você pode adicionar 1 monstro "Magidoce" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Retornar ao Deck','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11868825,'Remédio Secreto dos Goblins','Aumente os Life Points do jogador à sua escolha em 600 pontos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11876803,'Tigresa Escarlate Luzlunar',replace(replace('Se você ativar um efeito de monstro "Luzlunar" (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão e, depois, se você ativou este efeito durante o turno em que seu oponente ativou um card ou efeito, você pode adicionar 1 "Polimerização" do seu Deck ou Cemitério à sua mão. \r\nSe este card for enviado para o Cemitério por um efeito de card: você pode Invocar por Invocação-Especial 1 monstro "Luzlunar" do seu Deck Adicional com a face para cima ou Cemitério, exceto um monstro de Nível 5, mas ele não pode ativar seus efeitos. \r\nVocê só pode usar cada efeito de "Tigresa Escarlate Luzlunar" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Invocação Especial','Adicionar "Polimerização" à sua mão?','Invocado por Invocação Especial pelo efeito de "Tigre Carmesin Luzlunar"','','','','','','','','','','','','');
INSERT INTO texts VALUES(11877465,'Evigishki Mente Augus',replace(replace('Você pode Invocar este card por Invocação-Ritual com qualquer Magia de Ritual "Gishki". \r\nSe este card for Invocado por Invocação-Ritual: escolha até 5 cards em quaisquer Cemitérios; embaralhe esses alvos no(s) \r\nDeck(s).','\r',char(13)),'\n',char(10)),'Retornar ao Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11881272,'Herói Favorito',replace(replace('Só pode ser equipado a um monstro "HERÓI" de Nível 5 ou mais. \r\nSe você controlar um card na sua Zona do Campo, o monstro equipado ganha ATK igual à sua DEF original e, além disso, seu oponente não pode escolhê-lo como alvo de efeitos de card. \r\nNo começo da Fase de Batalha: você pode ativar 1 Magia de Campo diretamente da sua mão ou do Deck. \r\nVocê só pode usar este efeito de "Herói Favorito" uma vez por turno. \r\nQuando o monstro equipado atacar e destruir um monstro do oponente em batalha: você pode enviar este card para o Cemitério; o monstro atacante pode realizar um segundo ataque em seguida.','\r',char(13)),'\n',char(10)),'','','Escolha a Magia de Campo para ativar','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11895663,'Emi Blitzclique',replace(replace('Se este card for adicionado à sua mão, exceto ao comprá-lo: você pode revelar este card e, depois, escolha 1 card no campo; destrua-o e, se isso acontecer, Invoque por Invocação-Especial 1 monstro Trovão da sua mão e, além disso, pelo resto deste turno, você não pode Invocar Monstros de Efeito por Invocação-Especial, exceto da mão. \r\nSe um ou mais outros cards forem destruídos por um efeito de card, enquanto este card estiver na Zona de Monstros (exceto durante a Etapa de Dano): você pode adicionar 1 Armadilha "Blitzclique" do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "Emi Blitzclique" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Efeito de busca','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11901678,'Dragão Caveira Negro',replace(replace('"Caveira Invocada" + "Dragão Negro de Olhos Vermelhos"	\r\n\r\n(Este card deve ser sempre considerado como um card "Arquidemônio".)','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11908584,'Despertar do Núcleo Dragão-Guarda',replace(replace('Você pode enviar 1 Monstro de Efeito da sua mão para o Cemitério; Invoque por Invocação-Especial 1 Monstro Normal Dragão de Nível 4 ou menos da sua mão, do Deck ou do Cemitério, em Posição de Defesa. \r\nVocê só pode usar este efeito de "Despertar do Núcleo Dragão-Guarda" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11911336,'Livro de Magia do Círculo Maior',replace(replace('Adicione 4 monstros "Encantador(a)" com Atributos diferentes do seu Deck, Cemitério e/ou banimento à sua mão e, depois, embaralhe 2 cards da sua mão no Deck. \r\nVocê pode banir este card do seu Cemitério; Invoque por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional, usando monstros "Encantador(a)" ou "Espírito-Possuído" da sua mão ou do campo e, além disso, seu oponente não pode ativar cards ou efeitos quando um monstro for Invocado por Invocação-Fusão desta forma. \r\nVocê só pode usar cada efeito de "Livro de Magia do Círculo Maior" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar','Invocação Fusão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11913700,'Neo Espaço Instantâneo',replace(replace('Só pode ser equipado a um Monstro de Fusão que liste "Neos, o HERÓI do Elemento" como matéria. \r\nEle não precisa ativar seu efeito de embaralhar-se no Deck Adicional durante a Fase Final. \r\nSe o monstro equipado deixar o campo: você pode Invocar por Invocação-Especial 1 "Neos, o HERÓI do Elemento" da sua mão, do Deck ou do Cemitério.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11925569,'Instinto de Caça','Quando um ou mais monstros forem Invocados por Invocação-Especial no campo do seu oponente (exceto durante a Etapa de Dano): Invoque por Invocação-Especial 1 monstro Dinossauro da sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11954712,'Presavoadora',replace(replace('Se este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante. \r\nSe este card causou dano de batalha ao seu oponente, no final da Fase de Batalha: bana este card até sua próxima Fase de Apoio.','\r',char(13)),'\n',char(10)),'Banir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11958188,'Gralha Bujingi','Quando um monstro "Bujin" que você controla for destruído em batalha com um monstro do oponente e enviado para o seu Cemitério: você pode enviar este card da sua mão para o Cemitério; destrua o monstro do oponente.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11961740,'Cápsula de uma Dimensão Diferente',replace(replace('Bana 1 card do seu Deck com a face para baixo. \r\nDepois da ativação deste card, ele permanece no campo. \r\nDestrua este card durante sua 2ª Fase de Apoio depois de ativar este card e, se isso acontecer, adicione o card banido à mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11962031,'Salamagrande de Fogo',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 monstro "Salamagrande" de Nível 4 ou menos do seu Deck à sua mão, exceto "Salamagrande de Fogo" e, além disso, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros de FOGO. \r\nNo começo da Etapa de Dano, se um monstro Ciberso que você controla batalhar: você pode banir este card do seu Cemitério; destrua esse monstro que você controla. \r\nVocê só pode usar cada efeito de "Salamagrande de Fogo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11969228,'Cavaleiro Dragunidade - Romulus',replace(replace('2 monstros Dragão e/ou Besta Alada, exceto Fichas	\r\nSe este card for Invocado por Invocação-Link: você pode adicionar 1 Magia/Armadilha "Dragunidade" ou 1 "Ravina de Dragões" do seu Deck à sua mão. \r\nSe um ou mais monstros Dragão forem Invocados por Invocação-Especial do Deck Adicional em uma zona para a qual este card apontar (exceto durante a Etapa de Dano): você pode Invocar por Invocação-Especial 1 monstro Dragão ou Besta Alada da sua mão em Posição de Defesa, mas pelo resto deste turno, seus efeitos (se houver) são negados e ele não pode ser usado como Matéria Link. \r\nVocê só pode usar cada efeito de "Cavaleiro Dragunidade - Romulus" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11975962,'Selo Hierático do Banimento','Ofereça como Tributo 1 monstro "Hierático" e, depois, escolha 1 card que seu oponente controla; bana o alvo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11987744,'Cão Nin-Ken','Um cão Ninja que dominou as técnicas do Ninjutsu extremo. Através do treino árduo, aprendeu a técnica de transformação num ser humano.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12014404,'Cowboy Gagaga',replace(replace('2 monstros de Nível 4	\r\nUma vez por turno: você pode desassociar 1 Matéria Xyz deste card; aplique este efeito, dependendo da posição de batalha atual deste card.\r\n● Posição de Ataque: Apenas durante a Etapa de Dano, se este card atacar um monstro do oponente neste turno, ele ganha 1000 de ATK e, além disso, o monstro do oponente perde 500 de ATK.\r\n● Posição de Defesa: Cause 800 de dano ao seu oponente.','\r',char(13)),'\n',char(10)),'Alterar ATK','Causar dano','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12015000,'Dragão Fóssil Skullgar',replace(replace('1 monstro Rocha + 1 monstro de Nível 4 ou menos no Cemitério do seu oponente	\r\nPrimeiro deve ser Invocado por Invocação-Especial com "Fusão Fóssil". \r\nSe este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante. \r\nVocê pode banir este card do seu Cemitério; adicione 1 "Fusão Fóssil" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Dragão Fóssil Skullgar" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12018201,'Grande Senhor Lavalval',replace(replace('1 Regulador + 1+ monstros de FOGO não-Reguladores	\r\nQuando seu oponente ativar um efeito de um monstro no campo ou na mão dele (Efeito Rápido): você pode destruir esse monstro e, se isso acontecer, cause 1000 de dano ao seu oponente. \r\nSe este card Invocado por Invocação-Sincro sob o controle do seu dono for destruído por um card do oponente: você pode Invocar por Invocação-Especial em Posição de Defesa até 3 monstros de FOGO que não sejam Sincro com 200 de DEF do seu Cemitério, mas negue seus efeitos. \r\nVocê só pode usar cada efeito de "Grande Senhor Lavalval" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12021072,'Brincadeira de Criança',replace(replace('Sempre que seu oponente Invocar um ou mais monstros, ganhe 300 PV. \r\nSeus monstros não podem ser destruídos em batalha enquanto você tiver 10.000 ou mais PV.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12023931,'Dragão Dínamo',replace(replace('2 monstros "Foguette"	\r\nUma vez por turno: você pode escolher 1 outro monstro com a face para cima no campo; ele ganha 500 de ATK/DEF. \r\nSeu oponente não pode ativar cards ou efeitos em resposta à ativação deste efeito. \r\nSe este card Invocado por Invocação-Link for destruído em batalha ou por um efeito de card e enviado para o Cemitério: você pode escolher 1 outro monstro Dragão no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê só pode usar este efeito de "Dragão Dínamo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12057781,'Goblin Falso','Um Goblin que se dedica ao domínio perfeito da arte de escrever o "Falso". Ele foca todo o seu coração e mente no pincel de escrita.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12058741,'Bétula Olho de Cobra',replace(replace('Se você controlar um monstro de FOGO, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Bétula Olho de Cobra" por Invocação-Especial uma vez por turno desta forma. \r\nDurante o turno do seu oponente (Efeito Rápido): você pode enviar 2 cards com a face para cima que você controla para o Cemitério, incluindo este card; Invoque por Invocação-Especial 1 monstro "Olho de Cobra" da sua mão ou do Deck, exceto "Bétula Olho de Cobra". \r\nVocê só pode usar este efeito de "Bétula Olho de Cobra" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12061457,'Tesoura das Almas',replace(replace('Se um ou mais monstros no campo forem destruídos em batalha ou por um efeito de card e enviados para o Cemitério, enquanto este card estiver no seu Cemitério: você pode Invocar este card por Invocação-Especial, mas bana-o quando ele deixar o campo. \r\nSe este card for Invocado por Invocação-Especial do Cemitério: você pode escolher 1 monstro que seu oponente controla; destrua-o. \r\nVocê só pode usar cada efeito de "Tesoura das Almas" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12067160,'Górgona de Zilofthonia',replace(replace('2+ Monstros de Efeito	\r\nVocê não pode Invocar/Baixar monstros em uma ou mais zonas para as quais este card apontar. \r\nMonstros para os quais este card apontar não podem atacar e, além disso, seus efeitos ativados são negados. \r\nGanha ATK igual à soma do ATK original dos monstros para os quais este card apontar. \r\nNão pode ser destruído em batalha ou por efeitos de monstro, enquanto este card não apontar para nenhum monstro.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12071500,'Chamado Negro',replace(replace('Invoque por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional, que deve ser Invocado por Invocação-Especial com "Fusão Negra", ao banir as Matérias de Fusão mencionadas nele da sua mão e/ou do Cemitério. \r\n(Isso é considerado uma Invocação-Fusão com "Fusão Negra".)','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12076263,'Cachorro de Corda',replace(replace('Durante sua Fase Principal: Você pode aumentar o Nível deste card em 2 e o ATK em 600 até a Fase Final. \r\nEste efeito só pode ser usado uma vez, enquanto este card estiver com a face para cima no campo.','\r',char(13)),'\n',char(10)),'Aumentar Nível e ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12079734,'Delta Tri',replace(replace('Se este card destruir um monstro do oponente em batalha: ative 1 desses efeitos.\r\n● Escolha 1 monstro União apropriado no seu Cemitério; equipe o alvo a este card.\r\n● Escolha 1 monstro Máquina de LUZ com a face para cima que você controla; embaralhe o alvo no Deck e, depois, compre 1 card.','\r',char(13)),'\n',char(10)),'Escolher um efeito','Equipe um Monstro União a este card','Retornar ao Deck e comprar 1 card','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12081875,'Dragão do Trovão Mechtempestade Trovão',replace(replace('2+ monstros Trovão	\r\nDurante sua Fase Principal, se você controlar este card Invocado por Invocação-Link: você pode escolher 1 dos seus monstros "Dragão do Trovão" que estiver banido ou no seu Cemitério; aplique o efeito desse monstro que ativa ao descartar a si mesmo e, depois, coloque esse monstro no topo ou no fundo do seu Deck. \r\nVocê só pode usar este efeito de "Dragão do Trovão Mechtempestade Trovão" uma vez por turno. \r\nSe um ou mais monstros Trovão que você controla seriam destruídos em batalha ou por um efeito de card, em vez disso, você pode banir 3 cards do seu Cemitério.','\r',char(13)),'\n',char(10)),'','Colocar no topo do Deck','Retornar ao fundo do Deck','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12097275,'Gouki Abraço de Urso',replace(replace('Se este card for Invocado por Invocação-Especial pelo efeito de um card "Gouki", ou for Invocado por Invocação-Normal: você pode escolher 1 monstro com a face para cima que seu oponente controla; até o final deste turno, o ATK dele se torna metade do seu ATK original. \r\nSe este card for enviado do campo para o Cemitério: você pode adicionar 1 card "Gouki" do seu Deck à sua mão, exceto "Gouki Abraço de Urso". \r\nVocê só pode usar cada efeito de "Gouki Abraço de Urso" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12117532,'Machado Despedaçado',replace(replace('Ative este card ao escolher 1 monstro com a face para cima no campo. \r\nDurante cada uma das suas Fases de Apoio: ele perde 500 de ATK. \r\nQuando o alvo for destruído, destrua este card.','\r',char(13)),'\n',char(10)),'Reduzir ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12143771,'Pessoas Correndo às Voltas','Embora sofram sempre em silêncio, eles juram inevitavelmente revoltarem-se.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12146024,'Escargot Relâmpago','Depois de imobilizar um oponente cuspindo uma gosma pegajosa, este monstro se aproxima para atacar.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12148078,'Velocidaroide Roda',replace(replace('Descarte 1 card; lance um dado de seis faces e, depois, Invoque por Invocação-Especial, da sua mão e/ou do Deck, 1 ou 2 monstros "Velocidaroide" cuja soma dos Níveis seja igual ao resultado, mas negue seus efeitos. \r\nSe você não Invocar por Invocação-Especial, você perde PV igual ao resultado x 500. \r\nVocê só pode ativar 1 "Velocidaroide Roda" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12152769,'Goblin Pedinte','Se este card causar dano de batalha ao seu oponente: ele pode dar a você 1 card da mão dele para negar este efeito, caso contrário, você adiciona 1 card "Goblin" do seu Deck à sua mão.','Transfira um card da mão','Dar um card da sua mão ao seu oponente?','Escolha o card para dar ao seu oponente','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12157563,'Arte Ritual Proibida',replace(replace('Invoque por Invocação-Ritual 1 Monstro de Ritual do seu Cemitério ao banir monstros do seu Cemitério cuja soma dos Níveis seja igual ao Nível do Monstro de Ritual, mas destrua-o durante a Fase Final. \r\nVocê pode banir este card do seu Cemitério; uma vez neste turno, quando você Invocar por Invocação-Ritual, você também pode usar um ou mais Monstros de Ritual no seu Cemitério como um ou mais Tributos para a Invocação-Ritual, ao bani-los. \r\nVocê só pode usar cada efeito de "Arte Ritual Proibida" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar','Use Matérias de Ritual do Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12160911,'Estátua Elefante de Desastre','Se este card for enviado da sua mão para o seu Cemitério por um efeito de card do oponente: cause 2000 de dano ao seu oponente.','Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12163590,'Dragãozela Dacârama',replace(replace('Monstros de Fusão Dragão que você controla não podem ser destruídos pelos efeitos de card do seu oponente. \r\nVocê só pode usar cada um dos seguintes efeitos de "Dragãozela Dacârama" uma vez por turno. \r\nVocê pode descartar este card; Invoque por Invocação-Especial 1 monstro "Dragãozela" do seu Cemitério ou banimento, exceto "Dragãozela Dacârama". \r\nNo final da Fase de Batalha: você pode devolver este card para a mão e, se isso acontecer, Invoque por Invocação-Especial 1 monstro "Dragãozela" de Nível 4 ou menos da sua mão.','\r',char(13)),'\n',char(10)),'Invocação Especial','Retornar para a mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12171659,'Zeradias, o Arauto dos Céus',replace(replace('Você pode descartar este card para o Cemitério; adicione 1 "O Santuário no Céu" do seu Deck à sua mão. \r\nSe "O Santuário no Céu" não estiver no campo, destrua este card.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12172567,'Roquesa Mental',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nVocê pode escolher 1 monstro com a face para cima que seu oponente controla; troque o controle desse monstro e deste card. \r\nSe este card Invocado por Invocação-Sincro for enviado para o Cemitério: você pode escolher 1 monstro com a face para cima em cada campo; troque o controle desses monstros. \r\nVocê só pode usar cada efeito de "Roquesa Mental" uma vez por turno.','\r',char(13)),'\n',char(10)),'Trocar o controle','Trocar o controle','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12174035,'Canhão de Hidropressão',replace(replace('Só pode ser equipado a um monstro de ÁGUA de Nível 3 ou menos. \r\nSe ele destruir um monstro do oponente em batalha, envie 1 card aleatório na mão do seu oponente para o Cemitério.','\r',char(13)),'\n',char(10)),'Enviar para o Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12181376,'Faísca do Êxtase Triangular','Até o final deste turno, o ATK de todos os "Irmãs de Lady Harpia" atualmente no campo se torna 2700, seu oponente não pode ativar quaisquer Cards de Armadilha e, além disso, negue todos os efeitos de Armadilha do seu oponente no campo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12183332,'Embaralhamento',replace(replace('Pague 300 Life Points para embaralhar o seu Deck ou o Deck do seu adversário. \r\nVocê pode usar este efeito durante o seu turno, uma vez por turno.','\r',char(13)),'\n',char(10)),'Embaralhar','Embaralhar o seu Deck','Embaralhar o Deck do oponente','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12196873,'Dragão Chamariz Metafis',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nQuando um monstro seu for escolhido como alvo de um ataque: você pode escolher 1 dos seus monstros "Metafis" que estiver banido ou no seu Cemitério; bana este card e, se isso acontecer, Invoque esse monstro por Invocação-Especial em Posição de Ataque. \r\nVocê só pode usar este efeito de "Dragão Chamariz Metafis" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nQuando um monstro seu for escolhido como alvo de um ataque: você pode escolher 1 dos seus monstros "Metafis" que estiver banido ou no seu Cemitério; bana este card e, se isso acontecer, Invoque esse monstro por Invocação-Especial em Posição de Ataque. \r\nDurante a Fase de Apoio do próximo turno depois que este card foi banido: você pode Invocar este card banido por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Dragão Chamariz Metafis" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12197223,'Shiina, Tempestades Gêmeas do Trovão Celestial',replace(replace('Na primeira vez que este card seria destruído em batalha a cada turno, ele não é destruído. \r\nQuando seu oponente ativar um card ou efeito, enquanto você controlar um monstro de VENTO (Efeito Rápido): você pode Invocar este card por Invocação-Especial da sua mão e, depois, aplique o seguinte efeito de acordo com o que foi ativado.\r\n● Monstro: Devolva para a mão todos os monstros com a face para cima no campo, exceto "Shiina, Tempestades Gêmeas do Trovão Celestial".\r\n● Magia/Armadilha: Devolva para a mão todas as Magias/Armadilhas no campo.	\r\nVocê só pode usar este efeito de "Shiina, Tempestades Gêmeas do Trovão Celestial" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12197543,'Comandante das Espadas',replace(replace('Quando seu oponente comprar pela compra normal na Fase de Compra dele: ele revela o(s) card(s) que ele comprou e, depois, se algum for um Card de Magia/Armadilha, você aplica 1 desses efeitos.\r\n● Descarte todos os cards que ele comprou.\r\n● Destrua 1 Card de Magia/Armadilha que ele controla.','\r',char(13)),'\n',char(10)),'Descarte o(s) card(s) comprado(s).','Destrua 1 Magia/Armadilha que seu oponente controla.','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12206212,'Irmãs de Lady Harpia',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro deve ser Invocado por Invocação-Especial com "Egotista Elegante".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12210097,'Limite Sagrado de Mitsurugi',replace(replace('Seu oponente não pode escolher Monstros de Ritual "Mitsurugi" que você controla como alvo de efeitos de monstros que foram Invocados por Invocação-Especial do Deck Adicional. \r\nVocê pode escolher 4 cards "Mitsurugi" no seu Cemitério, exceto "Limite Sagrado de Mitsurugi"; embaralhe-os no Deck e, depois, se seu oponente controlar um monstro, faça com que ele ofereça como Tributo 1 monstro que ele controla (ele seleciona). \r\nVocê só pode usar este efeito de "Limite Sagrado de Mitsurugi" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Retornar ao Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12213463,'Dragão da Rosa Branca',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode Invocar por Invocação-Especial 1 monstro "Dragão da Rosa" da sua mão ou do Cemitério, exceto "Dragão da Rosa Branca". \r\nVocê só pode usar cada um desses efeitos de "Dragão da Rosa Branca" uma vez por turno.\r\n● Se você controlar um Regulador Dragão ou Regulador Planta: você pode Invocar este card por Invocação-Especial da sua mão.\r\n● Se este card for enviado para o Cemitério como Matéria Sincro: você pode enviar 1 monstro Planta de Nível 4 ou mais do seu Deck para o Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12215894,'Base Robô-secretário',replace(replace('Todos os monstros "Robô-secretário" no campo ganham 500 de ATK e DEF. \r\nUma vez por turno: você pode revelar qualquer número de cards "Robô-secretário" da sua mão e embaralhá-los no Deck e, depois, comprar o mesmo número de cards. \r\nVocê pode banir 9 cards "Robô-secretário" com nomes diferentes do seu campo e/ou Cemitério, exceto "Base Robô-secretário"; embaralhe no Deck todos os cards da mão, campo e Cemitério do seu oponente.','\r',char(13)),'\n',char(10)),'Comprar','Retornar os cards do oponente ao Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12216615,'Escudo de Koa''ki Meiru',replace(replace('Só pode ser ativado quando um monstro do oponente declarar um ataque se você tiver 2 ou mais "Núcleo de Ferro de Koa''ki Meiru" no seu Cemitério. \r\nDestrua todos os monstros com a face para cima em Posição de Ataque que seu oponente controla.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12219047,'Os Cavaleiros Fantasmas da Lança Amaldiçoada',replace(replace('2 monstros de Nível 2	\r\nVocê pode desassociar 1 matéria deste card e, depois, escolher 1 monstro com a face para cima que seu oponente controla; até o final deste turno, mude o ATK dele para 0 e, além disso, negue seus efeitos. \r\nEste é um Efeito Rápido se este card tiver um card "Os Cavaleiros Fantasmas" como matéria. \r\nVocê só pode usar este efeito de "Os Cavaleiros Fantasmas da Lança Amaldiçoada" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12235475,'Ashenveil Mitológico','Uma vez por batalha, se este card batalhar, durante o cálculo de dano (Efeito Rápido): você pode enviar 1 card da sua mão para o Cemitério; este card ganha 600 de ATK apenas durante esse cálculo de dano.','Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12247206,'Invocação Precipitada do Inferno','Quando exatamente 1 monstro com 1500 ou menos de ATK for Invocado por Invocação-Especial no seu campo enquanto seu oponente controlar um monstro com a face para cima: Invoque por Invocação-Especial tantos monstros quanto possível com o mesmo nome que o monstro oferecido como Tributo, da sua mão, do seu Deck e do seu Cemitério, em Posição de Ataque e, além disso, seu oponente Invoca por Invocação-Especial tantos monstros quanto possível com o mesmo nome que 1 dos seus monstros com a face para cima, da mão, do Deck e do Cemitério dele.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12253117,'Supressão Mundial',replace(replace('Você pode ativar este card quando um Card de Magia de Campo for ativado. \r\nNegue os efeitos de todos os Cards de Magia de Campo durante o turno em que este card for ativado.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12255007,'Vagaluxe Camarartista',replace(replace('Escala de Pêndulo = 5\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno, quando um monstro do oponente declarar um ataque: você pode oferecer como Tributo 1 monstro "Camarartista"; negue o ataque e, depois, encerre a Fase de Batalha.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe um monstro "Camarartista" ou "Olhos Anômalos" que você controla atacar, seu oponente não pode ativar nenhum Card de Magia/Armadilha até o final da Etapa de Dano.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12262393,'Delta, o Guerreiro Ímã',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode enviar 1 monstro "Guerreiro Ímã" de Nível 4 ou menos do seu Deck para o Cemitério. \r\nSe este card for enviado para o Cemitério: você pode banir 3 monstros "Guerreiro Ímã" de Nível 4 ou menos do seu Cemitério, exceto "Delta, o Guerreiro Ímã"; Invoque por Invocação-Especial 1 "Valkyrion, o Guerreiro Ímã" da sua mão ou do Deck, ignorando suas condições de Invocação. \r\nVocê só pode usar cada efeito de "Delta, o Guerreiro Ímã" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12266229,'Ilusão do Caos',replace(replace('Você pode Invocar este card por Invocação-Ritual com "Forma do Caos". \r\nVocê pode revelar este card na sua mão; adicione 1 "Mago Negro" ou 1 Monstro que não seja de Ritual que o mencione, do seu Deck à sua mão e, depois, coloque 1 card da sua mão no topo do Deck. \r\nQuando seu oponente ativar um efeito de monstro (Efeito Rápido): você pode devolver este card para a mão e, se isso acontecer, Invoque por Invocação-Especial 1 "Mago Negro" do seu Cemitério e, se isso acontecer, negue esse efeito ativado. \r\nVocê só pode usar cada efeito de "Ilusão do Caos" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12275533,'Trifortalezatops',replace(replace('Durante o turno de qualquer duelista, se seu oponente Invocou 3 ou mais monstros neste turno: você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe Invocado desta forma, ele não é afetado por outros efeitos de cards, mas perde 500 de DEF durante a Fase de Apoio de cada duelista.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12289247,'Feiticeiro Cronógrafo',replace(replace('Escala de Pêndulo = 8\r\n[ Efeito de Pêndulo ]\r\nDurante sua Fase Principal: você pode destruir este card e, se isso acontecer, pegue 1 "Mago Observador do Tempo" da sua mão ou do Deck e coloque-o na sua Zona de Pêndulo ou Invoque-o por Invocação-Especial. \r\nVocê só pode usar este efeito de "Feiticeiro Cronógrafo" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe um ou mais cards que você controla forem destruídos em batalha ou por um efeito de card: você pode Invocar este card por Invocação-Especial da sua mão e, depois, você pode Invocar por Invocação-Especial 1 monstro da sua mão. \r\nVocê pode banir este card que você controla, mais 4 monstros da sua mão, do campo e/ou do Cemitério (1 de cada com "Dragão Pêndulo", "Dragão Xyz", "Dragão Sincro" e "Dragão Fusão" em seus nomes); Invoque por Invocação-Especial 1 "Rei Supremo Z-ARC" do seu Deck Adicional. \r\n(Esta é considerada uma Invocação-Fusão.)','\r',char(13)),'\n',char(10)),'Destruir este card','Colocar na Zona de Pêndulo','Invocação Especial','Invoque este card por Invocação Especial da sua mão','Invocar por Invocação Especial um monstro da sua mão?','Invoque "Rei Supremo Z-ARC" por Invocação Fusão','Escolha 1 "Mago Observador do Tempo"','','','','','','','','','');
INSERT INTO texts VALUES(12292422,'Inspeção de Espécime',replace(replace('Revele 1 "Fusão Fóssil" na sua mão; envie 1 monstro da sua mão para o Cemitério e, se isso acontecer, declare um Tipo e um Nível e, depois, seu oponente olha sua própria mão e Deck e envia, de um deles, 1 monstro do Tipo e Nível declarados para o Cemitério (se possível). \r\nVocê só pode ativar 1 "Inspeção de Espécime" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12296376,'Wattpicapau',replace(replace('Este card pode realizar um segundo ataque durante cada Fase de Batalha. \r\nQualquer monstro que batalhar com este card não pode mudar sua posição de batalha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12298909,'Dragão de Matéria Primitiva',replace(replace('Qualquer efeito que causaria dano a um duelista, em vez disso, aumenta os Pontos de Vida dele no mesmo valor. \r\nDurante o turno de qualquer duelista, quando um card ou efeito que destruiria um ou mais monstros no campo for ativado: você pode enviar 1 card da sua mão para o Cemitério; negue a ativação e, se isso acontecer, destrua-o.','\r',char(13)),'\n',char(10)),'Negar a ativação de um efeito que destrói um monstro no campo e destruí-lo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12299841,'Soldado de Corda',replace(replace('Durante sua Fase Principal: Você pode aumentar o Nível deste card em 1 e o ATK em 400 até a Fase Final. \r\nEste efeito só pode ser usado uma vez, enquanto este card estiver com a face para cima no campo.','\r',char(13)),'\n',char(10)),'Aumentar Nível e ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12307878,'Purgatrio, o Invokado',replace(replace('"Aleister, Aquele que Invoka" + 1 monstro de FOGO	\r\nGanha 200 de ATK para cada card que seu oponente controla. \r\nPode atacar todos os monstros que seu oponente controla, uma vez cada. \r\nSe este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12324546,'Lendário Corcel de Ébano',replace(replace('Só pode ser equipado a um monstro "Seis Samurai". \r\nEle ganha 200 de ATK e DEF. \r\nSe ele seria destruído, em vez disso, destrua este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12332865,'Thron, o Anjo Disciplinado',replace(replace('Se um ou mais monstros que originalmente eram Fada de TERRA forem enviados da sua mão ou do campo para o Cemitério (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão. \r\nVocê só pode usar este efeito de "Thron, o Anjo Disciplinado" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12338068,'Maju Garzett Lendário',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao oferecer como Tributo todos os monstros que você controla. \r\nO ATK deste card se torna o ATK original combinado dos monstros oferecidos como Tributo. \r\nSe este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12369277,'Camada Azul Super Quantum',replace(replace('Quando este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 card "Super Quant" do seu Deck à sua mão, exceto "Camada Azul Super Quantum". \r\nSe este card for enviado para o Cemitério: você pode escolher até 3 cards "Super Quant" no seu Cemitério; embaralhe-os no Deck. \r\nVocê só pode usar cada efeito de "Camada Azul Super Quantum" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Retornar ao Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12375297,'Patrono do Poder de Elfnota',replace(replace('Você não pode Invocar por Invocação-Especial do Deck Adicional, exceto Monstros Sincro. \r\nVocê só pode usar cada um dos seguintes efeitos de "Patrono do Poder de Elfnota" uma vez por turno. \r\nDurante a Fase Principal (Efeito Rápido): você pode escolher 1 monstro na sua Zona de Monstros Principal central; aumente seu Nível em 3 (até o final deste turno) e, depois, imediatamente depois que este efeito resolver, você pode Invocar por Invocação-Sincro 1 Monstro Sincro "Elfnota" ou 1 "Junora, o Patrono do Poder da Afinação". \r\nSe este card for enviado para o Cemitério como Matéria Sincro: você pode adicionar 1 card "Elfnota" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Alterar o Nível','Adicionar à mão','Invocação Sincro?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12381100,'Suprema Magia Mestre dos Dragões',replace(replace('"Dragão Definitivo de Olhos Azuis" ou 3 monstros "Olhos Azuis" + 1 Monstro de Ritual "Caos" ou "Soldado do Lustro Negro"	\r\nDeve ser Invocado por Invocação-Fusão. \r\nQuando seu oponente ativar um card ou efeito (Efeito Rápido): você pode negar a ativação e, se isso acontecer, destrua esse card. \r\nVocê só pode usar este efeito de "Suprema Magia Mestre dos Dragões" em resposta a cada tipo de card (Monstro, Magia ou Armadilha) uma vez por turno. \r\nSe este card com a face para cima sob o controle do seu dono deixar o campo devido a um card do oponente: você pode Invocar por Invocação-Especial 1 monstro "Olhos Azuis" ou 1 Monstro de Ritual "Caos" ou "Soldado do Lustro Negro" do seu Deck Adicional ou Cemitério.','\r',char(13)),'\n',char(10)),'','Negar um monstro do oponente','Invoque por Invocação Especial um monstro "Olhos Azuis" ou um Monstro Ritual "Caos"','Você já ativou o efeito de "Suprema Magia Mestre dos Dragões" em resposta a um Monstro','Você já ativou o efeito de "Suprema Magia Mestre dos Dragões" em resposta a uma Magia','Você já ativou o efeito de "Suprema Magia Mestre dos Dragões" em resposta a uma Armadilha','','','','','','','','','','');
INSERT INTO texts VALUES(12381101,'Suprema Magia Mestre dos Dragões',replace(replace('"Dragão Definitivo de Olhos Azuis" ou 3 monstros "Olhos Azuis" + 1 Monstro de Ritual "Caos" ou "Soldado do Lustro Negro"	\r\nDeve ser Invocado por Invocação-Fusão. \r\nQuando seu oponente ativar um card ou efeito (Efeito Rápido): você pode negar a ativação e, se isso acontecer, destrua esse card. \r\nVocê só pode usar este efeito de "Suprema Magia Mestre dos Dragões" em resposta a cada tipo de card (Monstro, Magia ou Armadilha) uma vez por turno. \r\nSe este card com a face para cima sob o controle do seu dono deixar o campo devido a um card do oponente: você pode Invocar por Invocação-Especial 1 monstro "Olhos Azuis" ou 1 Monstro de Ritual "Caos" ou "Soldado do Lustro Negro" do seu Deck Adicional ou Cemitério.','\r',char(13)),'\n',char(10)),'','Negar um monstro do oponente','Invoque por Invocação Especial um monstro "Olhos Azuis" ou um Monstro Ritual "Caos"','Você já ativou o efeito de "Suprema Magia Mestre dos Dragões" em resposta a um Monstro','Você já ativou o efeito de "Suprema Magia Mestre dos Dragões" em resposta a uma Magia','Você já ativou o efeito de "Suprema Magia Mestre dos Dragões" em resposta a uma Armadilha','','','','','','','','','','');
INSERT INTO texts VALUES(12385638,'Choro de Kozmo',replace(replace('Monstros destruídos em batalha com monstros "Kozmo" que você controla são embaralhados no Deck em vez de irem para o Cemitério. \r\nVocê pode banir este card do seu Cemitério; na primeira vez que você sofreria dano de batalha de uma batalha envolvendo um monstro "Kozmo" que você controla neste turno, em vez disso, você ganha esse tanto de PV.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12397569,'Domínio Divino Baatistina',replace(replace('Durante sua Fase Principal: você pode enviar 1 monstro "Tistina" do seu Deck para o seu Cemitério e, depois, se seu oponente controlar 3 ou mais cards com a face para cima, você pode Invocar por Invocação-Especial 1 "Deus de Cristal Tistina" da sua mão ou do Deck. \r\nVocê só pode usar este efeito de "Domínio Divino Baatistina" uma vez por turno. \r\nSe este card na sua Zona do Campo for destruído por um efeito de card do seu oponente: você pode Invocar por Invocação-Especial 1 monstro "Tistina" do seu Deck ou Cemitério.','\r',char(13)),'\n',char(10)),'','','Invocar por Invocação Especial 1 "Deus de Cristal Tistina"?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12398280,'Freya, o Espírito da Vitória',replace(replace('Enquanto você controlar um monstro do Tipo Fada que não seja "Freya, o Espírito da Vitória", os monstros do seu oponente não podem escolher este card como alvo de ataques. \r\nTodos os monstros do Tipo Fada que você controla ganham 400 de ATK e DEF.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12408276,'Dama Obscura de Kozmoll',replace(replace('(Efeito Rápido): você pode banir este card; Invoque por Invocação-Especial 1 monstro "Kozmo" de Nível 6 ou mais da sua mão. \r\nVocê só pode usar este efeito de "Dama Obscura de Kozmoll" uma vez por turno. \r\nUma vez por turno, quando um efeito de outro monstro for ativado (Efeito Rápido): você pode pagar 1000 PV; negue a ativação e, se isso acontecer, destrua esse monstro.','\r',char(13)),'\n',char(10)),'Invoque por Invocação Especial 1 monstro "Kozmo" da sua mão','Negar a ativação e destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12421694,'Força Celeste - Ás - Kaina',replace(replace('1 monstro "Força Celeste - Ás" que não seja de TERRA	\r\nSe este card for Invocado por Invocação-Especial: você pode escolher 1 monstro com a face para cima que seu oponente controla; ele não pode atacar até o final do turno do seu oponente. \r\nSempre que você ativar um Card de Magia "Força Celeste" ou seus efeitos, ganhe 100 PV imediatamente depois que o card ou efeito resolver. \r\nVocê só pode Invocar um ou mais "Força Celeste - Ás - Kaina" por Invocação-Especial uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12423762,'Gardna Gagaga',replace(replace('Quando um monstro do oponente declarar um ataque direto: você pode Invocar este card por Invocação-Especial da sua mão. \r\nQuando este card for alvo de um ataque: você pode descartar 1 card; este card não pode ser destruído nessa batalha.','\r',char(13)),'\n',char(10)),'Invocação Especial','Não pode ser destruído em batalha','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12435193,'Draco Koa''ki Meiru',replace(replace('Durante cada uma das suas Fases Finais, destrua este card a não ser que você envie 1 "Núcleo de Ferro de Koa''ki Meiru" da sua mão para o Cemitério ou revele 1 monstro Dragão na sua mão. \r\nNenhum duelista pode Invocar por Invocação-Especial monstros de LUZ ou de TREVAS.','\r',char(13)),'\n',char(10)),'Escolha 1 "Núcleo de Ferro de Koa''ki Meiru" para enviar para o Cemitério','Revelar ao oponente 1 monstro Dragão','Destruir "Draco Koa''ki Meiru"','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12436646,'Aquacobra','Este monstro hipnotiza um adversário com a bola na sua cauda e o arrasta para uma ruína aquática.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12444060,'Santuário dos Artefatos',replace(replace('Invoque por Invocação-Especial 1 monstro "Artefato" do seu Deck. \r\nSe este card em posse do seu dono for destruído por um card do oponente: você pode escolher 1 card no campo; destrua o alvo. \r\nVocê só pode ativar 1 "Santuário dos Artefatos" por turno. \r\nVocê não pode conduzir sua Fase de Batalha no turno em que ativar este card.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12450071,'Mago F Proxy',replace(replace('2 Monstros de Efeito	\r\nDurante sua Fase Principal: você pode Invocar por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional, usando monstros do seu campo como Matéria de Fusão. \r\nSe um ou mais Monstros de Fusão forem Invocados por Invocação-Fusão em uma ou mais zonas para as quais este card apontar: você pode Invocar por Invocação-Especial 1 monstro com 1000 ou menos de ATK da sua mão. \r\nVocê só pode usar cada efeito de "Mago F Proxy" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12451640,'Observador da Linha de Frente',replace(replace('Durante a Fase Final, se este card foi Invocado por Invocação-Normal neste turno: você pode adicionar 1 Monstro Pêndulo de TERRA do seu Deck à sua mão. \r\nSe este card foi Invocado por Invocação-Normal, durante a Fase Final do próximo turno do duelista que a Invocou: você pode oferecer este card como Tributo; adicione 1 monstro de TERRA do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12467005,'Cruzador de Engajamento',replace(replace('Se este card for enviado para o Cemitério: você pode ativar 1 desses efeitos.\r\n● Escolha 1 monstro com a face para cima que seu oponente controla; coloque o alvo com a face para baixo em Posição de Defesa.\r\n● Escolha 1 Magia/Armadilha com a face para cima que seu oponente controla; devolva o alvo para a mão.	\r\nNeste turno, seu oponente não pode ativar cards com o mesmo nome que o card devolvido para a mão por este efeito.','\r',char(13)),'\n',char(10)),'Ativar o efeito escolhido','Mudar um monstro para Posição de Defesa com a face para baixo','Retornar uma Magia/Armadilha para a mão','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12469386,'Rosa do Renascimento','Se um ou mais monstros Planta de Nível 5 ou mais com a face para cima que você controla forem destruídos enquanto este card estiver no Cemitério: você pode Invocar este card por Invocação-Especial do Cemitério.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12470447,'Maldição do Demônio',replace(replace('Mude as posições de batalha de todos os monstros em Posição de Ataque no campo para Posição de Defesa e vice-versa. \r\nEssas posições não podem ser mudadas durante o turno em que este card for ativado, exceto pelo efeito de um Card de Magia, Armadilha ou Monstro de Efeito. \r\nVocê só pode ativar este card durante sua Fase de Apoio.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12472242,'Leghul','Este monstro pode atacar diretamente os Life Points do seu adversário.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12482652,'Ojama Verde','Ele é um dos membros do Trio Ojama. Dizem que ele sempre encontra uma forma de se intrometer quando não é convidado. Dizem também que quando os três se juntam, algo acontece.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12493482,'Bruxa Obscura Dunames','Mesmo quando todas as chances estão contra esta corajosa fada, ele seguirá lutando sem nunca recuar.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12496261,'Cavaleiro Dragunidade - Luin',replace(replace('1 Regulador "Dragunidade" + 1+ monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Especial: você pode escolher 1 monstro "Dragunidade" no seu Cemitério; equipe-o neste card. \r\nSe este card for enviado para o Cemitério: você pode escolher 1 monstro "Dragunidade" que você controla; equipe este card no alvo. \r\nEle ganha 1000 de ATK/DEF. \r\nVocê só pode usar cada efeito de "Cavaleiro Dragunidade - Luin" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12500059,'Anja do Amanhecer Kambi',replace(replace('Se você não controlar nenhum monstro, ou todos os monstros que você controla forem monstros Fada: você pode Invocar este card por Invocação-Especial da sua mão. \r\nVocê pode oferecer como Tributo qualquer número de monstros Fada, incluindo este card; Invoque por Invocação-Especial 1 monstro Fada do seu Deck cujo Nível seja igual à soma dos Níveis que esses monstros tinham no campo. \r\nVocê não pode Invocar por Invocação-Especial no turno em que ativar este efeito, exceto monstros Fada. \r\nVocê só pode usar cada efeito de "Anja do Amanhecer Kambi" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar este card por Invocação Especial','Invocar por Invocação Especial do Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12501230,'Roda de Combate',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nNa primeira vez que este card seria destruído por um efeito de card do oponente a cada turno, ele não é destruído. \r\nUma vez por turno, durante a Fase de Batalha do seu oponente (Efeito Rápido): você pode descartar 1 card; este card ganha ATK igual à metade da soma do ATK de todos os outros monstros que você controla atualmente e, depois, coloque 1 marcador neste card e, além disso, pelo resto deste turno, os monstros do seu oponente não podem escolher monstros como alvo de ataques, exceto este. \r\nSe este card com um marcador for destruído em batalha: destrua todos os monstros que você controla.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12503902,'Metalmorph Raro',replace(replace('(Este card deve ser sempre considerado como um card "Metalmorfe".)	\r\nAtive este card ao escolher 1 monstro Máquina no campo; enquanto este card estiver com a face para cima no campo, esse monstro Máquina ganha 500 de ATK e, além disso, negue o primeiro efeito de Magia que escolher esse monstro como alvo. \r\nQuando esse monstro deixar o campo, destrua este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12508268,'Motivação Futura',replace(replace('Escolha 1 Monstro Xyz "Futuro Utópico" que você controla; aplique o(s) seguinte(s) efeito(s) a esse monstro que você controla pelo resto deste turno.\r\n● Ele pode atacar todos os monstros que seu oponente controla uma vez cada.\r\n● Se ele batalhar um monstro do oponente, os efeitos desse monstro são negados apenas durante a Etapa de Dano.\r\n● Sempre que ele destruir um monstro do oponente em batalha, cause dano ao seu oponente igual ao ATK original do monstro destruído.	\r\nVocê só pode ativar 1 "Motivação Futura" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12510878,'Neo-Parshath, o Paladino dos Céus',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) ao oferecer como Tributo 1 "Cavaleiro Celeste Parshath". \r\nSe este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante. \r\nSe este card causar dano de batalha ao seu oponente: compre 1 card. \r\nEnquanto "O Santuário no Céu" estiver no campo e seus PV forem maiores que os do seu oponente, este card ganha ATK/DEF igual à diferença de PV.','\r',char(13)),'\n',char(10)),'Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12524259,'Reativação Não Autorizada',replace(replace('Escolha 1 monstro Máquina que você controla; equipe 1 monstro União Máquina apropriado da sua mão ou do Deck a esse monstro, mas o monstro União que você equipou não pode ser Invocado por Invocação-Especial neste turno. \r\nVocê só pode ativar 1 "Reativação Não Autorizada" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12525049,'Guerreiro Sinfônico Guitaarra',replace(replace('Escala de Pêndulo = 7\r\n[ Efeito de Pêndulo ]\r\nVocê pode descartar 1 card; Invoque por Invocação-Especial 1 monstro "Guerreiro Sinfónico" do seu Deck, exceto "Guerreiro Sinfônico Guitaarra". \r\nVocê só pode usar este efeito de "Guerreiro Sinfônico Guitaarra" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nQuando este card for Invocado por Invocação-Normal: você pode escolher 1 monstro "Guerreiro Sinfónico" no seu Cemitério; Invoque-o por Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12527118,'Cassimolar',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode escolher 1 monstro com a face para cima que seu oponente controla; ele ganha ATK igual ao seu ATK original e, além disso, durante a Fase Final do próximo turno, destrua esse monstro com a face para cima e, se isso acontecer, seu oponente sofre dano igual à metade do seu ATK original. \r\nNo começo da Fase de Batalha do seu oponente: você pode oferecer como Tributo este card Invocado por Invocação-Normal/Baixado; os monstros do seu oponente não podem atacar diretamente pelo resto deste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12533811,'Tiragon Bebê',replace(replace('3 monstros de Nível 1	\r\nDurante sua Fase Principal 1: você pode desassociar 1 Matéria Xyz deste card e, depois, escolher 1 monstro de Nível 1 que você controla; ele pode atacar diretamente seu oponente.','\r',char(13)),'\n',char(10)),'Ataque direto','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12538374,'Sapo Arbóreo',replace(replace('Uma vez por turno, durante sua Fase de Apoio, se este card estiver no seu Cemitério e você não controlar "Sapo Arbóreo": você pode Invocar este card por Invocação-Especial. \r\nVocê não pode controlar Magias/Armadilhas para ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12541409,'Supressão Inférnica',replace(replace('Se você não tiver cards na sua mão, você pode ativar este card no turno em que foi Baixado. \r\nQuando seu oponente ativar um efeito de monstro enquanto você controlar um monstro "Inférnico(a)": negue o efeito e, depois, você pode causar dano ao seu oponente igual ao Nível do monstro que ativou o efeito x 100. \r\nVocê só pode ativar 1 "Supressão Inférnica" por turno.','\r',char(13)),'\n',char(10)),'','Causar dano?','Ativar aplicando o efeito de "Supressão Inférnica".','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12571621,'Xiezhi do Mundo Virtual - Jiji',replace(replace('Se este card estiver na sua mão: você pode escolher 1 card "Mundo Virtual" que você controla; envie 1 card "Mundo Virtual" de um tipo diferente (Monstro, Magia, Armadilha) do seu Deck para o Cemitério e, se isso acontecer, Invoque este card por Invocação-Especial e, depois, durante a Fase Final deste turno, você pode adicionar 1 monstro "Mundo Virtual" do seu Cemitério à sua mão, exceto "Xiezhi do Mundo Virtual - Jiji". \r\nPelo resto deste turno, você só pode Invocar por Invocação-Especial monstros de Nível/Classe 3 ou mais. \r\nVocê só pode usar este efeito de "Xiezhi do Mundo Virtual - Jiji" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial da mão','Adicionar um monstro do Cemitério à sua mão?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12580477,'Raigeki','Destrua todos os monstros que seu oponente controla.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12580478,'Raigeki','Destrua todos os monstros que seu oponente controla.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12580479,'Raigeki','Destrua todos os monstros que seu oponente controla.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12600382,'Exodia Necross',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial com "Contrato com Exodia". \r\nNão pode ser destruído em batalha ou por efeitos de Magia/Armadilha. \r\nUma vez por turno, durante sua Fase de Apoio: este card ganha 500 de ATK. \r\nDestrua este card a não ser que todos esses 5 cards estejam no seu Cemitério, "Exodia, "O Proibido"", "Braço Direito de "O Proibido"", "Braço Esquerdo de "O Proibido"", "Perna Direita de "O Proibido"" e "Perna Esquerda de "O Proibido"".','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12607053,'Waboku',replace(replace('Você não sofre dano de batalha neste turno. \r\nSeus monstros não podem ser destruídos em batalha neste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12612470,'Procissão da Jarra de Chá',replace(replace('Monstros com a face para baixo em Posição de Defesa na coluna deste card não podem mudar suas posições de batalha e, além disso, nenhum duelista pode ativar os cards Baixados nas Zonas de Magias & Armadilhas na coluna deste card. \r\nVocê só pode usar cada um dos seguintes efeitos de "Procissão da Jarra de Chá" uma vez por turno. \r\nDurante sua Fase Principal: você pode mover este card para uma Zona de Monstros Principal adjacente não-utilizada. \r\nSe este card na Zona de Monstros se mover para outra Zona de Monstros: coloque todos os outros monstros na coluna atual deste card com a face para baixo em Posição de Defesa.','\r',char(13)),'\n',char(10)),'Mover','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12615446,'Inseto Digital Escaradiador',replace(replace('2 ou mais monstros de LUZ do Tipo Inseto de Nível 3	\r\nUma vez por turno, durante o turno de qualquer duelista: você pode desassociar 2 Matérias Xyz deste card e, depois, escolher 1 monstro que seu oponente controla; mude a posição de batalha dele e, se isso acontecer, ele tem seus efeitos negados até o final deste turno. \r\nUma vez por turno, quando este card destruir um monstro do oponente em batalha e enviá-lo para o Cemitério: você pode associar esse monstro destruído a este card como uma Matéria Xyz.','\r',char(13)),'\n',char(10)),'Negar o efeito','Associar material','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12624008,'Espírito Radiante','Quando este card for destruído em batalha e enviado para o Cemitério, destrua todos os monstros com a face para baixo e os que não sejam de LUZ.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12632096,'Neo Dragão Críptico de Olhos das Galáxias',replace(replace('3 monstros de Nível 9	\r\nSe este card tiver um card "Críptico(a)" como Matéria Xyz, ele ganha este efeito.\r\n● Uma vez por turno: você pode desassociar até 3 Matérias Xyz deste card; monstros que você controla não podem atacar diretamente seu oponente pelo resto deste turno, exceto este card e, além disso, para cada Matéria desassociada, até a Fase Final, tome o controle de 1 monstro com a face para cima do oponente, mas enquanto este efeito for aplicado, eles têm seus efeitos negados, o ATK deles se torna 4500 e, além disso, o nome deles se torna "Neo Dragão Críptico de Olhos das Galáxias".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12644061,'Trevas Avançadas',replace(replace('Todos os monstros "Fera Cristalina" no campo e no Cemitério se tornam de TREVAS. \r\nSe um monstro "Cristalino(a) Definitivo(a)" atacar, negue os efeitos do alvo do ataque durante essa Fase de Batalha. \r\nDurante o cálculo de dano, se um monstro "Fera Cristalina" que você controla batalhar e você sofreria dano: você pode enviar 1 monstro "Fera Cristalina" do seu Deck para o Cemitério; você não sofre dano de batalha dessa batalha.','\r',char(13)),'\n',char(10)),'O dano de batalha se torna 0','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12652643,'Golem do Mecanismo Antigo Definitivo',replace(replace('"Golem do Mecanismo Antigo" + 2 monstros "Mecanismo Antigo"	\r\nDeve ser Invocado por Invocação-Fusão. \r\nSe este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante. \r\nSe este card atacar, seu oponente não pode ativar Cards de Magia/Armadilha até o final da Etapa de Dano. \r\nSe este card for destruído: você pode escolher 1 "Golem do Mecanismo Antigo" no seu Cemitério; Invoque-o por Invocação-Especial, ignorando suas condições de Invocação.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12670770,'Rede Cibernética',replace(replace('Destrua este card durante sua 3ª Fase de Apoio depois da ativação. \r\nUma vez por turno, se "Dragão Cibernético" estiver no campo: você pode banir 1 monstro Máquina de LUZ do seu Deck. \r\nSe este card for enviado do campo para o Cemitério: Invoque por Invocação-Especial tantos dos seus monstros Máquina de LUZ banidos quanto possível e, se isso acontecer, destrua todas as Magias e Armadilhas que você controla. \r\nMonstros que foram Invocados por Invocação-Especial por este efeito não podem ativar seus efeitos. \r\nVocê não pode conduzir sua Fase de Batalha no turno em que ativar este efeito.','\r',char(13)),'\n',char(10)),'Usar o efeito de "Rede Cibernética" agora?','Usar o efeito','Banir 1 monstro Máquina de LUZ do seu Deck','Invoque por Invocação Especial um monstro banido','Contagem de turnos','','','','','','','','','','','');
INSERT INTO texts VALUES(12678601,'Dholes Tindângulo',replace(replace('VIRE: Você pode enviar 1 Magia/Armadilha do seu Deck para o Cemitério.\r\nSe este card for enviado da mão ou do Deck para o Cemitério: você pode escolher 1 monstro "Tindângulo" no seu Cemitério, exceto "Dholes Tindângulo"; Invoque-o por Invocação-Especial com a face para baixo em Posição de Defesa. \r\nVocê só pode usar cada um dos efeitos anteriores de "Dholes Tindângulo" uma vez por turno. \r\nUm Monstro Link "Tindângulo" que usou este card como matéria pode realizar 3 ataques durante cada Fase de Batalha.','\r',char(13)),'\n',char(10)),'','','Usar "Dholes Tindângulo" como Matéria Link','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12678870,'Besta Espiritual Ulti-Pettlefinho',replace(replace('1 monstro "Domador da Besta Espiritual" + 1 monstro "Avatar da Besta Espiritual"	\r\nVocê deve Invocá-lo por Invocação-Especial (do seu Deck Adicional) ao banir os cards acima que você controla e não pode Invocá-lo por Invocação-Especial de nenhuma outra forma. \r\n(Você não usa "Polimerização".) \r\nEste card não pode ser destruído por efeitos de card. \r\nDurante o turno de qualquer duelista: você pode devolver este card que você controla para o Deck Adicional e, depois, escolher 2 dos seus monstros banidos (1 monstro "Domador da Besta Espiritual" e 1 monstro "Avatar da Besta Espiritual"); Invoque-os por Invocação-Especial em Posição de Defesa.','\r',char(13)),'\n',char(10)),'Invoque por Invocação Especial 1 monstro "Domador da Besta Espiritual" e 1 monstro "Avatar da Besta Espiritual"','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12682213,'Trovão de Ferro','Quando um Card de Magia/Armadilha ou efeito de monstro for ativado no campo: pague metade dos seus PV; negue a ativação e, se isso acontecer, destrua esse card e, depois, destrua quaisquer outros cards na mesma coluna em que estava o card destruído, que estejam em uma das Zonas de Monstros ou Zonas de Magias & Armadilhas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12686296,'Força Arcana EX - O Senhor do Caos',replace(replace('3 monstros "Força Arcana" com nomes diferentes	\r\nDeve ser Invocado por Invocação-Especial (do seu Deck Adicional) ao enviar os cards acima de qualquer campo para o Cemitério. \r\nSe este card for Invocado por Invocação-Especial: lance uma moeda.\r\n● Cara: Invoque por Invocação-Especial 1 monstro "Força Arcana" de Nível 10 da sua mão ou do Deck, ignorando suas condições de Invocação.\r\n● Coroa: Adicione 1 card do seu Deck à sua mão que tenha um efeito de lançar moeda.	\r\nEnquanto "Barreira de Luz" estiver na Zona do Campo, seu oponente não pode ativar os efeitos de monstros no campo.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial da mão/Deck','Adicionar à mão','Não é possível ativar efeitos de monstros','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12694768,'Abaki','Quando este card for destruído em batalha e enviado para o Cemitério, cada duelista sofre 500 de dano.','Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12697630,'Artefato Beagalltach',replace(replace('Você pode Baixar este card da sua mão na sua Zona de Magias & Armadilhas como um Card de Magia. \r\nDurante o turno do seu oponente, se este card Baixado na Zona de Magias & Armadilhas for destruído e enviado para o seu Cemitério: Invoque-o por Invocação-Especial. \r\nSe este card for Invocado por Invocação-Especial durante o turno do seu oponente: destrua até 2 cards Baixados que você controla (mín. 1). \r\nVocê só pode usar este efeito de "Artefato Beagalltach" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12735388,'Véu do Arco-Íris','Se o monstro equipado batalhar com um monstro do oponente, enquanto esse monstro estiver no campo, seus efeitos são negados apenas durante a Fase de Batalha.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12743620,'Afinar Uni-Canção',replace(replace('Escolha 1 Regulador em qualquer Cemitério e 1 monstro com a face para cima no campo; bana esse Regulador no Cemitério e, depois, até o final deste turno, o Nível do monstro alvo no campo se torna o Nível do Regulador banido e, além disso, ele é considerado como um Regulador. \r\nVocê só pode ativar 1 "Afinar Uni-Canção" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12744567,'Número C101: OBSCURO da Honra Silenciosa',replace(replace('3 monstros de Nível 5	\r\nUma vez por turno: você pode escolher 1 monstro Invocado por Invocação-Especial que seu oponente controla; associe-o a este card como matéria. \r\nQuando este card for destruído e enviado para o Cemitério enquanto tiver matérias: você pode Invocar este card por Invocação-Especial do seu Cemitério e, depois, ganhe PV igual ao ATK original deste card. "Número 101: ARCA da Honra Silenciosa" deve estar no seu Cemitério para ativar e resolver este efeito. \r\nSe este card for Invocado por Invocação-Especial desta forma, ele não pode atacar pelo resto deste turno.','\r',char(13)),'\n',char(10)),'Associar como matéria','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12755462,'Unidade Escavadora Goblin',replace(replace('Quando este card for Invocado por Invocação-Normal, Cards de Armadilha não podem ser ativados. \r\nAlém disso, Cards de Armadilha "Buraco Armadilha" não podem ser ativados quando um monstro for Invocado, exceto "Buraco Armadilha das Trevas".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12760674,'Mordschlag',replace(replace('Só pode ser equipado a um monstro Invocado por Invocação-Normal/Baixado que você controla. \r\nEle não é afetado pelos efeitos ativados dos monstros Invocados por Invocação-Especial do seu oponente. \r\nDurante o cálculo de dano, se o monstro equipado batalhar um monstro Invocado por Invocação-Especial do oponente: esse monstro do oponente perde ATK/DEF igual ao ATK original do monstro equipado, apenas durante o cálculo de dano.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12766474,'Duque Penumbra, o Senhor das Sombras Sinistro',replace(replace('Você pode oferecer como Tributo qualquer número de monstros de TREVAS; Invoque este card por Invocação-Especial da sua mão e, se isso acontecer, ele ganha 500 de ATK para cada monstro que você ofereceu como Tributo. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 monstro de TREVAS de Nível 5 ou mais no seu Cemitério; adicione-o à sua mão. \r\nVocê só pode usar cada efeito de "Duque Penumbra, o Senhor das Sombras Sinistro" uma vez por turno. \r\nVocê não pode Invocar monstros por Invocação-Especial no turno em que ativar qualquer um dos efeitos deste card, exceto monstros de TREVAS.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12800564,'Master da Paz, o Verdadeiro Dracosuserano',replace(replace('Requer 3 Tributos para ser Invocado por Invocação-Normal (não pode ser Baixado Normalmente). \r\nPara Invocar este card por Invocação-Tributo com a face para cima, você pode oferecer como Tributo Magias/Armadilhas Contínuas que você controla, assim como monstros. \r\nVocê só pode usar cada um dos seguintes efeitos de "Master da Paz, o Verdadeiro Dracosuserano" uma vez por turno. \r\nQuando seu oponente ativar um efeito de monstro na mão ou no campo dele e você controlar este card Invocado por Invocação-Tributo (Efeito Rápido): você pode negar a ativação e, se isso acontecer, destrua esse monstro. \r\nSe este card Invocado por Invocação-Tributo for destruído em batalha, ou for destruído por um efeito de card do oponente enquanto estiver na Zona de Monstros do seu dono: você pode ativar este efeito; seu oponente pula a próxima Fase Principal dele.','\r',char(13)),'\n',char(10)),'Oferecer uma Magia/Armadilha como Tributo?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12800777,'Garuda, o Espírito do Vento',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro deve ser Invocado por Invocação-Especial (da sua mão) ao banir 1 monstro de VENTO do seu Cemitério. \r\nUma vez por turno, durante a Fase Final do seu oponente: você pode escolher 1 monstro com a face para cima que seu oponente controla; mude a posição de batalha do alvo.','\r',char(13)),'\n',char(10)),'Mudar a posição de batalha','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12801833,'Jardim Armadilhatrip',replace(replace('Durante sua Fase Principal, você pode Invocar por Invocação-Normal 1 monstro "Armadilhatrix", em adição à sua Invocação-Normal/Baixar (padrão). \r\n(Você só pode se aproveitar deste efeito uma vez por turno.) \r\nNa primeira vez que cada monstro Inseto ou Planta que você controla seria destruído em batalha a cada turno, ele não é destruído. \r\nVocê pode banir 1 monstro que você controla; Invoque por Invocação-Especial 1 monstro "Armadilhatrix" da sua mão ou do Cemitério. \r\nVocê só pode usar este efeito de "Jardim Armadilhatrip" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar pelo efeito de "Jardim Armadilhatrip"','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12804701,'Cura Aromági',replace(replace('Ganhe 1000 PV para cada monstro "Aromági" que você controla com um nome diferente. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 monstro "Aromági" no seu Cemitério; Invoque-o por Invocação-Especial (mas bana-o quando ele deixar o campo) e, depois, ganhe 500 PV. \r\nVocê só pode usar 1 efeito de "Cura Aromági" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12817939,'Lucius das Trevas LV6',replace(replace('Se este card foi Invocado por Invocação-Especial pelo efeito de "Lucius das Trevas LV4", negue os efeitos dos monstros do seu oponente destruídos em batalha com este card. \r\nUma vez por turno, durante a Fase de Apoio do seu próximo turno depois que este card negar o efeito de um monstro do seu oponente por este efeito: você pode enviar este card para o Cemitério; Invoque por Invocação-Especial 1 "Lucius das Trevas LV8" da sua mão ou do Deck.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12822541,'D/D Lilith',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode ativar 1 desses efeitos. \r\nVocê só pode usar este efeito de "D/D Lilith" uma vez por turno.\r\n● Escolha 1 monstro "D/D" no seu Cemitério; adicione-o à sua mão.\r\n● Adicione 1 Monstro Pêndulo "D/D" com a face para cima do seu Deck Adicional à sua mão.','\r',char(13)),'\n',char(10)),'Adicione à sua mão 1 monstro "D/D" do seu Cemitério','Adicione à sua mão 1 Monstro Pêndulo "D/D" no seu Deck Adicional','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12829151,'Kanan, a Patroa da Espada','Uma guerreira armada com espada e escudo. Ela flutua com suavidade e estoqueia com intensidade.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12836042,'Força Em Falta',replace(replace('Se você não controlar nenhum outro monstro: Você pode oferecer este card como Tributo para escolher 1 monstro que seu oponente controla; tome o controle do alvo até a Fase Final. \r\nVocê não pode Invocar por Invocação-Especial ou conduzir sua Fase de Batalha durante o turno em que você ativar este efeito.','\r',char(13)),'\n',char(10)),'Tomar controle','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12863633,'Maldição do Círculo','Escolha 1 monstro que seu oponente controla; seu oponente não pode oferecê-lo como Tributo ou usá-lo como um Monstro-Matéria Sincro.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12877076,'Despertar dos Definitivos Cristalinos',replace(replace('Revele 1 monstro "Cristalino(a) Definitivo(a)" na sua mão e, depois, ative 1 desses efeitos. \r\nSe você controlar um monstro "Cristalino(a) Definitivo(a)", em vez disso, você pode ativar 1 ou 2 desses efeitos em sequência (e não precisa revelar um monstro).\r\n● Pegue 1 card "Ponte Arco-Íris" ou 1 "Refração Arco-Íris" do seu Deck e adicione-o à sua mão ou envie-o para o Cemitério.\r\n● Invoque por Invocação-Especial 1 Card de Monstro "Fera Cristalina" da sua mão, do Deck, do Cemitério ou da sua Zona de Magias & Armadilhas.	\r\nVocê só pode ativar 1 "Despertar dos Definitivos Cristalinos" por turno.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Invocação Especial','Escolher ambos os jogadores','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12883044,'Dançarino Flamejante','Este monstro se move enquanto gira sua corda incandescente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12888461,'Aspiscardume',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode Invocar por Invocação-Especial 1 monstro Peixe de Nível 6 ou menos da sua mão em Posição de Defesa, mas bana-o quando ele deixar o campo. \r\nSe este card for banido: você pode Invocar este card por Invocação-Especial em Posição de Defesa. \r\nVocê só pode usar este efeito de "Aspiscardume" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial da mão','Invocar este card por Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12890860,'Divindade da Negação Dotan',replace(replace('1 monstro de LUZ + 2 monstros, exceto no campo ou no Cemitério	\r\nEste card Invocado por Invocação-Fusão não pode ser destruído em batalha. \r\nEnquanto nenhum monstro no seu campo ou Cemitério compartilhar um nome original com qualquer monstro no campo ou Cemitério do seu oponente, os monstros que você controla não podem ser destruídos por efeitos de card. \r\nVocê pode enviar, da sua mão, do Deck ou do Deck Adicional, para o Cemitério, 1 monstro com o mesmo nome original que o de um monstro no campo ou Cemitério do seu oponente e, depois, escolha 1 monstro no campo ou Cemitério dele; bana-o.','\r',char(13)),'\n',char(10)),'','','Banir','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12908094,'Mago Gagaga – Magia Gagaga',replace(replace('Se este card está na sua mão: você pode Invocar por Invocação-Especial este card e 1 outro monstro "Zubaba", "Gagaga", "Gogogo", ou "Dododo" da sua mão ou Cemitério, exceto "Mago Gagaga – Magia Gagaga", e se fizer, imediatamente após resolver esse efeito, Invoque por Invocação-Xyz 1 monstro "Zubaba", "Gagaga", "Gogogo", "Dododo", "Gênio", "Campeão Heroico", "Número", "ZW -", ou "ZS -" usando apenas aqueles 2 monstros. \r\nQuando fizer, considere o Nível de 1 desses monstros igual ao do outro monstro. \r\nVocê só pode usar este efeito de "Mago Gagaga – Magia Gagaga" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12908095,'Mago Gagaga – Magia Gagaga',replace(replace('Se este card está na sua mão: você pode Invocar por Invocação-Especial este card e 1 outro monstro "Zubaba", "Gagaga", "Gogogo", ou "Dododo" da sua mão ou Cemitério, exceto "Mago Gagaga – Magia Gagaga", e se fizer, imediatamente após resolver esse efeito, Invoque por Invocação-Xyz 1 monstro "Zubaba", "Gagaga", "Gogogo", "Dododo", "Gênio", "Campeão Heroico", "Número", "ZW -", ou "ZS -" usando apenas aqueles 2 monstros. \r\nQuando fizer, considere o Nível de 1 desses monstros igual ao do outro monstro. \r\nVocê só pode usar este efeito de "Mago Gagaga – Magia Gagaga" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12923641,'Espadas da Luz Oculta',replace(replace('Destrua este card durante sua 2ª Fase de Apoio depois da ativação. \r\nQuando este card for ativado: se seu oponente controlar um monstro com a face para cima, vire todos os monstros que ele controla com a face para baixo em Posição de Defesa. \r\nOs monstros que seu oponente controla não podem mudar suas posições de batalha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12927849,'SZW - Espada Fenrir',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode escolher 1 monstro "ZW -" que você controla que seja um Card de Equipamento; Invoque o alvo por Invocação-Especial em Posição de Defesa. \r\nVocê pode escolher 1 monstro "Utopia" que você controla; equipe este card da sua mão ao alvo. \r\nQuando o monstro equipado destruir um monstro do oponente em batalha e enviá-lo para o Cemitério: você pode escolher 1 monstro "ZW -" no seu Cemitério; adicione o alvo à sua mão.','\r',char(13)),'\n',char(10)),'Invocação Especial','Equipar','Adicionar à mão','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12930501,'Regeneração da Magia Negra',replace(replace('Quando um monstro do oponente declarar um ataque: escolha 1 Magia no Cemitério do seu oponente; Baixe-a no seu campo. \r\nVocê pode banir este card do seu Cemitério e envie 1 "Reviver Monstro" da sua mão ou Baixado no seu campo para o Cemitério; Invoque por Invocação-Especial 1 "O Dragão Alado de Rá" do seu Cemitério ignorando suas condições de Invocação e, depois, você pode enviar 1 monstro que seu oponente controla para o Cemitério e, além disso, envie esse monstro Invocado por Invocação-Especial para o Cemitério durante a Fase Final.','\r',char(13)),'\n',char(10)),'','','Enviar um monstro do oponente para o Cemitério?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12931061,'U.A. Hiperestádio',replace(replace('(Este card deve ser sempre considerado como um card "F.A.")	\r\nQuando este card for ativado: você pode adicionar 1 monstro "U.A." ou "F.A." do seu Deck à sua mão, OU adicionar 1 "U.A. Estádio" do seu Cemitério à sua mão. \r\nVocê pode revelar 1 Magia de Campo na sua mão e pagar 1000 PV; você pode Invocar por Invocação-Normal 1 monstro "U.A." ou "F.A." durante sua Fase Principal deste turno, em adição à sua Invocação-Normal/Baixar padrão. \r\n(Você só pode se aproveitar deste efeito uma vez por turno.) \r\nVocê só pode ativar 1 "U.A. Hiperestádio" por turno.','\r',char(13)),'\n',char(10)),'Adicionar este card à mão?','','Invocar pelo efeito de "U.A. Hiperestádio"','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12940613,'Lição Magidoce','Escolha 1 monstro "Magidoce" no seu Cemitério; embaralhe o alvo no seu Deck e, se isso acontecer, todos os monstros "Magidoce" que você controla atualmente ganham 800 de ATK e DEF e, depois, você pode embaralhar 1 outro monstro do seu Cemitério no Deck.','Retornar 1 monstro do Cemitério ao Deck?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12948099,'Entidade Antiga Cthugua',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro: você pode devolver para o Deck Adicional todos os Monstros Xyz de Classe 4 no campo. \r\nSe você Invocar por Invocação-Fusão usando este card como Matéria de Fusão: compre 1 card. \r\nUm Monstro Xyz que foi Invocado usando este card no campo como Matéria Xyz ganha este efeito.\r\n● Se for Invocado por Invocação-Xyz: compre 1 card.','\r',char(13)),'\n',char(10)),'Retornar ao Deck Adicional do seu dono','Compre 1 card(s)','Compre 1 card (Entidade Antiga Cthugua)','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12950294,'Dragão da Explosão de Velocidade',replace(replace('Quando você sofrer dano de efeito (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão e, depois, causar dano ao seu oponente igual ao dano que você sofreu e, se isso acontecer, você ganha PV igual à metade do dano que você causou. \r\nQuando este card for Invocado por Invocação-Tributo: você pode adicionar 2 monstros "Foguette" com nomes diferentes do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "Dragão da Explosão de Velocidade" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12953226,'Núvia, a Perversa',replace(replace('Se este monstro for Invocado por Invocação-Normal, destrua este card. \r\nSe o seu oponente controlar qualquer monstro, reduza o ATK deste card em 200 pontos para cada monstro no lado do campo do oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12954226,'Círculo das Fadas',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nDurante sua Fase Principal, você pode Invocar por Invocação-Normal 1 monstro Inseto ou Planta em adição à sua Invocação-Normal/Baixar (padrão). \r\n(Você só pode se aproveitar deste efeito uma vez por turno.) \r\nQuando um monstro for destruído em batalha envolvendo um monstro Inseto ou Planta seu, e enviado para o Cemitério: você pode escolher 1 desses monstros destruídos; cause dano ao seu oponente igual à metade do ATK dele e, depois, ganhe PV igual ao dano causado ao seu oponente. \r\nVocê só pode usar este efeito de "Círculo das Fadas" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar pelo efeito de "Círculo das Fadas"','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12958919,'Fantasma Destruidor Celeste',replace(replace('Quando este card for Invocado por Invocação-Normal ou Virar: você pode Invocar por Invocação-Especial qualquer número de "Ficha de Destruidor Celeste" (Demônio/TREVAS/Nível 4/ATK 500/DEF 500), até o número de monstros que você controla. \r\nUma vez por turno, durante sua Fase de Apoio: você pode causar 300 de dano ao seu oponente para cada monstro "Destruidor Celeste" que você controla. \r\nMonstros "Destruidor Celeste" que você controla não podem declarar um ataque durante o turno em que você ativar este efeito.','\r',char(13)),'\n',char(10)),'Invocação Especial','Causar dano','Invocar outra Ficha por Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12958920,'Ficha de Destruidor Celeste','Invocado por Especial com o efeito "Fantasma Destruidor Celeste".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12965761,'Des Dendle',replace(replace('Uma vez por turno, durante a sua Main Phase, você pode equipar este card a "Orchis Vampírica" como um Card de Magia de Equipamento, OU separar o Equipamento e Invocar, por Invocação-Especial, este card em Posição de Ataque com a face para cima. \r\nQuando este card é equipado pelo efeito deste card, cada vez que o monstro equipado destrói um monstro como resultado de um combate, Invoque, por Invocação-Especial, 1 "Ficha de Planta Perversa" (Tipo Planta/TERRA/Nível 1/ATK 800/DEF 800). \r\n(1 monstro pode ser equipado apenas por 1 Monstro de Union de cada vez. Se o monstro equipado com este card é destruído como resultado de um combate, em vez disso destrúa este card.)','\r',char(13)),'\n',char(10)),'Equipar','Invocação Especial','Invocar uma Ficha por Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12965762,'Ficha de Planta Perversa','Invocado por Especial com o efeito "Des Dendle".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12975671,'Primeiro Pinguim',replace(replace('Se você não controlar nenhum monstro com a face para cima, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nSe Invocado desta forma, considere este card como um Regulador. \r\nVocê pode descartar 1 card e, depois, revele 1 Monstro Sincro de ÁGUA no seu Deck Adicional; adicione 1 monstro de ÁGUA do seu Deck à sua mão com o mesmo Tipo, mas 1 Nível menor que o do monstro revelado e, depois, você pode colocar este card com a face para baixo em Posição de Defesa e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto monstros de ÁGUA. \r\nVocê só pode usar este efeito de "Primeiro Pinguim" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Efeito de busca','Mudar para Posição de Defesa com a face para baixo?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12977245,'Fifinellag Altergeist','Monstros que seu oponente controla não podem escolher monstros "Altergeist" que você controla como alvo de ataques, exceto "Fifinellag Altergeist" e, além disso, seu oponente não pode escolher monstros "Altergeist" que você controla como alvo de efeitos de card, exceto "Fifinellag Altergeist".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12980373,'Mil-Folhas Magidoce',replace(replace('Quando este card que você controla for destruído por um card do oponente (seja em batalha ou por um efeito de card) e enviado ao seu Cemitério: Embaralhe este card no seu Deck. \r\nQuando este card for Invocado por Invocação-Normal: Você pode Invocar por Invocação-Especial 1 monstro "Magidoce" da sua mão.','\r',char(13)),'\n',char(10)),'Retornar ao Deck','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12986778,'Dádiva do Senhormek Imperador',replace(replace('Se os únicos monstros com a face para cima no campo forem 2 monstros "Senhormek": compre 2 cards. \r\nVocê não pode conduzir sua Fase de Batalha no turno em que ativar este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12986807,'Laval, o Maior',replace(replace('1 Regulador + 1 ou mais monstros de FOGO não-Reguladores	\r\nQuando este card for Invocado por Invocação-Sincro: Envie 1 card da sua mão para o Cemitério. \r\nSe este card seria destruído por um efeito de card, em vez disso, você pode banir 1 monstro "Laval" do seu Cemitério.','\r',char(13)),'\n',char(10)),'Enviar 1 card da sua mão para o Cemitério','Banir 1 monstro no seu Cemitério cujo nome inclua "Laval" em vez de ser destruído?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12989604,'Despertar do Legado Mundial',replace(replace('Imediatamente depois que este efeito resolver, Invoque por Invocação-Link 1 Monstro Link usando um ou mais monstros que você controla como matéria. \r\nVocê só pode ativar 1 "Despertar do Legado Mundial" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13002461,'Força da Profecia','Uma vez por turno: Você pode embaralhar 1 Card de Magia "Livro de Magia" do seu Cemitério no seu Deck para escolher 1 monstro do Tipo Mago com a face para cima no campo; aumente o Nível dele em 1 e o ATK dele em 500.','Aumentar Nível e ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13014905,'Agnimal Vela',replace(replace('Se este card for adicionado à sua mão, exceto ao comprá-lo: você pode Invocar este card por Invocação-Especial. \r\nVocê só pode usar este efeito de "Agnimal Vela" uma vez por turno. \r\nUma vez por Corrente, até três vezes por turno, se um monstro for enviado para o seu Cemitério (exceto durante a Etapa de Dano): você pode aumentar ou diminuir o Nível deste card em 1.','\r',char(13)),'\n',char(10)),'Invocação Especial','Alterar Nível','Aumentar o Nível','Reduzir o Nível','','','','','','','','','','','','');
INSERT INTO texts VALUES(13021682,'Estrelasucata Sincron',replace(replace('Para uma Invocação-Sincro, você pode substituir este card por qualquer 1 Regulador "Sincron".\r\nVocê só pode usar cada um dos seguintes efeitos de "Estrelasucata Sincron" uma vez por turno.\r\nSe este card está na sua mão: você pode escolher 1 monstro Nível 2 ou menor no seu Cemitério; Invoque por Invocação-Especial este card, e se fizer, Invoque por Invocação-Especial aquele monstro, mas seus efeitos são negados, você também não pode fazer Invocação-Especial do Deck Adicional pelo resto deste turno, exceto de Monstros Sincro.\r\nVocê pode banir este card do seu Cemitério; "Guerreiro Sucata" que você controla não pode ser destruído por efeitos de cards do seu oponente neste turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Não pode ser destruído','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13021683,'Estrelasucata Sincron',replace(replace('Para uma Invocação-Sincro, você pode substituir este card por qualquer 1 Regulador "Sincron".\r\nVocê só pode usar cada um dos seguintes efeitos de "Estrelasucata Sincron" uma vez por turno.\r\nSe este card está na sua mão: você pode escolher 1 monstro Nível 2 ou menor no seu Cemitério; Invoque por Invocação-Especial este card, e se fizer, Invoque por Invocação-Especial aquele monstro, mas seus efeitos são negados, você também não pode fazer Invocação-Especial do Deck Adicional pelo resto deste turno, exceto de Monstros Sincro.\r\nVocê pode banir este card do seu Cemitério; "Guerreiro Sucata" que você controla não pode ser destruído por efeitos de cards do seu oponente neste turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Não pode ser destruído','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13023431,'Chevreuil, o Batedor Caçador da Floresta Profunda',replace(replace('1 monstro Guerreiro de TERRA de Nível 5 ou mais + 1 monstro Guerreiro de TERRA	\r\nNão é afetado pelos efeitos ativados do seu oponente, apenas durante a Fase Principal. \r\nOs monstros do seu oponente que podem atacar devem atacar o monstro que você controla com o maior ATK (em caso de empate, ele seleciona). \r\nQuando outro monstro Guerreiro de TERRA que você controla destruir um monstro do oponente em batalha: você pode Invocar por Invocação-Especial 1 monstro Guerreiro de TERRA do seu Cemitério ou banimento. \r\nVocê só pode usar este efeito de "Chevreuil, o Batedor Caçador da Floresta Profunda" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13026402,'Equipa-A: Unidade de Desativação de Armadilhas',replace(replace('Este efeito também pode ser usado durante o turno do seu adversário. \r\nQuando o seu adversário activa um Card de Armadilha, ofereça este card com a face para cima como Tributo para anular a activação do Card de Armadilha e destruí-lo.','\r',char(13)),'\n',char(10)),'Negar a ativação de uma Armadilha e destruí-la','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13030280,'CXyz Lenda de Arthur, Herói dos Quadrinhos',replace(replace('3 monstros de Nível 5	\r\nUma vez por turno, este card não pode ser destruído em batalha. \r\nSe este card tiver "Rei Arthur, Herói dos Quadrinhos" como uma Matéria Xyz, ele ganha este efeito.\r\n● Quando este card destruir um monstro em batalha e enviá-lo para o Cemitério: você pode desassociar 1 Matéria Xyz deste card; bana o monstro destruído e, se isso acontecer, cause dano ao seu oponente igual ao ATK original dele.','\r',char(13)),'\n',char(10)),'Banir e causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13032689,'Unidade Xyz',replace(replace('Só pode ser equipado a um Monstro Xyz com a face para cima. \r\nEle ganha ATK igual à sua Classe x 200. \r\nSe o monstro equipado que você controla fosse desassociar uma de suas matérias para ativar um de seus efeitos: você pode desassociar este card como se ele fosse 1 dessas matérias.','\r',char(13)),'\n',char(10)),'Usar o efeito de "Unidade Xyz"?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13035077,'Diagrama Dragônico',replace(replace('Todos os monstros "Verdadeiro(a) Draco" e "Verdadeiro Rei" no campo ganham 300 de ATK/DEF. \r\nNa primeira vez que cada monstro "Verdadeiro(a) Draco" ou "Verdadeiro Rei" Invocado por Invocação-Tributo seria destruído em batalha a cada turno, ele não é destruído. \r\nUma vez por turno: você pode destruir 1 outro card que você controla ou na sua mão e, se isso acontecer, adicione 1 card "Verdadeiro(a) Draco" ou "Verdadeiro Rei" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13039848,'Soldado de Pedra Gigante','Um guerreiro gigante feito de pedra. Um soco desta criatura faz com que a terra estremeça.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13046291,'Evoltil Megachirella',replace(replace('Você pode oferecer como Tributo 1 monstro Réptil e, depois, descarte 1 card; Invoque por Invocação-Especial 1 monstro Dinossauro de FOGO de Nível 6 ou menos do seu Deck. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 Monstro Xyz Dragão sem matéria que você controla; associe até 2 monstros Réptil e/ou Dinossauro com nomes diferentes da sua mão e/ou do Cemitério a esse monstro como matéria. \r\nVocê só pode usar cada efeito de "Evoltil Megachirella" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13048472,'Pré-preparação de Ritos',replace(replace('Adicione 1 Magia de Ritual do seu Deck à sua mão e adicione 1 Monstro de Ritual do seu Deck ou Cemitério à sua mão cujo nome seja mencionado nessa Magia de Ritual. \r\nVocê só pode ativar 1 "Pré-preparação de Ritos" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13048473,'Pré-preparação de Ritos',replace(replace('Adicione 1 Magia de Ritual do seu Deck à sua mão e adicione 1 Monstro de Ritual do seu Deck ou Cemitério à sua mão cujo nome seja mencionado nessa Magia de Ritual. \r\nVocê só pode ativar 1 "Pré-preparação de Ritos" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13069066,'Dragão de Cauda Assassina','Este gigante Jurássico tem a espinha coberta de lâminas similares a espadas e uma cauda capaz de esmagar crâneos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13070280,'Jogo da Tistina',replace(replace('Invoque por Invocação-Especial 1 monstro "Tistina" da sua mão ou do Cemitério em Posição de Defesa, mas devolva-o para a mão durante a Fase Final. \r\nVocê só pode ativar 1 "Jogo da Tistina" por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13073850,'Qliphort Furtivo',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nVocê não pode Invocar monstros por Invocação-Especial, exceto monstros "Qli". \r\nEste efeito não pode ser negado. \r\nTodos os monstros "Qli" que você controla ganham 300 de ATK.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nVocê pode Invocar este card por Invocação-Normal sem oferecer Tributo. \r\nSe este card for Invocado por Invocação-Normal sem oferecer Tributo, ou se for Invocado por Invocação-Especial, o Nível dele se torna 4 e o ATK original dele se torna 1800. \r\nSe este card for Invocado por Invocação-Normal/Baixado, ele não é afetado por efeitos ativados de monstros cujo Nível/Classe original seja menor que o Nível atual deste card. \r\nQuando este card for Invocado por Invocação-Tributo pelo Tributo de um ou mais monstros "Qli": você pode escolher 1 card no campo; devolva-o para a mão. \r\nSeu oponente não pode ativar cards ou efeitos em resposta à ativação deste efeito.','\r',char(13)),'\n',char(10)),'Invocação Normal sem Tributo','Retornar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13076804,'Arquidemônio do Caos',replace(replace('1 Regulador de LUZ + 1+ monstros não-Reguladores de TREVAS	\r\nSe quaisquer cards foram banidos neste turno, este card ganha 2000 de ATK. \r\nEste card pode atacar todos os monstros que seu oponente controla, uma vez cada e, além disso, bana quaisquer monstros destruídos em batalha com este card. \r\nSe este card sob o controle do seu dono deixar o campo devido a um card do oponente: você pode Invocar por Invocação-Especial 1 Monstro Sincro "Caos" do seu Deck Adicional, exceto "Arquidemônio do Caos". \r\nVocê só pode usar este efeito de "Arquidemônio do Caos" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13090893,'Varredor da Rede',replace(replace('Se uma Magia de Campo com a face para cima estiver em qualquer Zona do Campo: você pode Invocar este card por Invocação-Especial da sua mão. \r\nVocê pode banir este card no seu Cemitério e 1 Monstro Link que você controla; destrua 1 card que seu oponente controla. \r\nVocê só pode usar cada efeito de "Varredor da Rede" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13093792,'HERÓI do Destino - Homem Diamante',replace(replace('Uma vez por turno: você pode escavar o card do topo do seu Deck e se for uma Magia Normal, envie-a para o Cemitério, caso contrário, coloque-o no fundo do seu Deck. \r\nDurante a Fase Principal do seu próximo turno, você pode ativar o efeito dessa Magia no seu Cemitério (mesmo que você não controle mais este card com a face para cima).','\r',char(13)),'\n',char(10)),'Ativar o efeito de um Card de Magia','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13108445,'Cavaleiro-Gema Água-Marinha',replace(replace('"Cavaleiro-Gema Safira" + 1 monstro "Cavaleiro-Gema"	\r\nPrimeiro deve ser Invocado por Invocação-Fusão com as Matérias de Fusão acima. \r\nSe este card atacar, ele é colocado em Posição de Defesa no final da Fase de Batalha. \r\nSe este card for enviado do campo para o Cemitério: escolha 1 card que seu oponente controla; devolva o alvo para a mão.','\r',char(13)),'\n',char(10)),'Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13117073,'Bloqueador Barricadaborg',replace(replace('2 monstros com nomes diferentes	\r\nSe este card for Invocado por Invocação-Link: você pode descartar 1 card; durante a Fase Final deste turno, adicione 1 Magia Contínua ou de Campo do seu Cemitério à sua mão. \r\nVocê só pode usar este efeito de "Bloqueador Barricadaborg" uma vez por turno. \r\nMagias com a face para cima que você controla não podem ser destruídas pelos efeitos de card do seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13140300,'Selo Hierático do Suserano do Dragão do Sol','Uma relíquia Hierática misteriosa gravada. Pensavam que se tratava de uma simples pedra, mas ela na verdade foi infundida com o poder de um dragão que brandia o poder do sol. Eras se passaram e o poder da relíquia cresceu e cresceu até que finalmente brilhou como o próprio sol.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13143275,'Dragão-Guarda Pisty',replace(replace('1 monstro Dragão de Nível 4 ou menos	\r\nVocê não pode Invocar monstros por Invocação-Especial, exceto monstros Dragão. \r\nDurante sua Fase Principal: você pode escolher 1 dos seus monstros Dragão que estiver banido ou no seu Cemitério; Invoque-o por Invocação-Especial em uma zona sua para a qual 2 ou mais Monstros Link apontarem. \r\nVocê só pode usar este efeito de "Dragão-Guarda Pisty" uma vez por turno. \r\nVocê só pode Invocar um ou mais "Dragão-Guarda Pisty" por Invocação-Especial uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13166204,'Gagagataque','Quando um ou mais monstros "Gagaga" que você controla forem escolhidos como alvo pelo efeito de um monstro do oponente: negue o efeito desse monstro do oponente e, se isso acontecer, destrua-o e, depois, cause dano ao seu oponente igual ao ATK ou DEF do monstro destruído no Cemitério (o que for maior).','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13166648,'Rasante do Dragão Duplo',replace(replace('Quando um Monstro Xyz do oponente declarar um ataque direto: Invoque por Invocação-Especial 1 Monstro Xyz de LUZ do Tipo Dragão do seu Deck Adicional em Posição de Ataque e, depois, o monstro atacante, em vez de um ataque direto, ataca esse monstro e você prossegue para o cálculo de dano. \r\nO ATK desse monstro se torna igual ao ataque do monstro atacante e, além disso, seus efeitos são negados. \r\nVocê só pode ativar 1 "Rasante do Dragão Duplo" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13171876,'Dragãozela Lavadeira',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode enviar os 3 cards do topo do seu Deck para o Cemitério. \r\nNo começo da Fase de Batalha: você pode devolver este card para a mão e, se isso acontecer, Invoque por Invocação-Especial 1 monstro "Dragãozela" de Nível 7 da sua mão ou do Cemitério. \r\nVocê só pode usar cada efeito de "Dragãozela Lavadeira" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13171877,'Dragãozela Lavadeira',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode enviar os 3 cards do topo do seu Deck para o Cemitério. \r\nNo começo da Fase de Batalha: você pode devolver este card para a mão e, se isso acontecer, Invoque por Invocação-Especial 1 monstro "Dragãozela" de Nível 7 da sua mão ou do Cemitério. \r\nVocê só pode usar cada efeito de "Dragãozela Lavadeira" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13173832,'Salamagrande Lobi',replace(replace('Um monstro que foi Invocado por Invocação-Link usando este card como matéria não pode ser destruído em batalha ou por efeitos de card pelo resto desse turno. \r\nVocê só pode usar 1 dos seguintes efeitos de "Salamagrande Lobi" por turno e apenas uma vez por turno.\r\n● Se este card for Invocado por Invocação-Especial do Cemitério: você pode escolher 1 monstro de FOGO no seu Cemitério; adicione-o à sua mão.\r\n● Se este card for adicionado do seu Cemitério à sua mão por um efeito: você pode revelar este card e, depois, escolher 1 monstro de FOGO no seu Cemitério; adicione-o à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13179234,'Guerras Vaylantz - O Local do Começo',replace(replace('Adicione 1 Magia de Campo "Vaylantz" do seu Deck à sua mão e, depois, você pode aplicar o seguinte efeito.\r\n● Destrua 1 Card de Monstro Pêndulo que você controla e, se isso acontecer, adicione 1 "Troca de Senet" do seu Deck à sua mão.	\r\nSe este card estiver no seu Cemitério, exceto no turno em que foi enviado para lá: você pode banir este card; coloque 1 Monstro Pêndulo "Vaylantz" com a face para cima do seu Deck Adicional na sua Zona de Pêndulo. \r\nVocê só pode usar cada efeito de "Guerras Vaylantz - O Local do Começo" uma vez por turno.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Colocar um card de Pêndulo','Destruir um Card de Pêndulo e adicionar "Troca de Senet" à sua mão?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13179332,'Carvão Inpachi','Um perverso espírito de madeira que se extinguiu. O churrasco na brasa com esse carvão é tão incrível que todos dizem que não tem preço.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13183454,'Princesa Gélida Zereort',replace(replace('2 monstros do Tipo Besta Alada de Nível 5	\r\nVocê pode desassociar 1 Matéria Xyz deste card e, depois, escolher 1 monstro com a face para cima que seu oponente controla; o ATK dele se torna 0.','\r',char(13)),'\n',char(10)),'O ATK se torna 0','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13193642,'Planta das Trevas','Esta flor mutante extrai seu poder da poluição e das forças das trevas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13203964,'Dragão Perfectron Hidradrive',replace(replace('1+ Monstros Link	\r\nSe este card for Invocado por Invocação-Link, OU, se ele batalhar, no final da Etapa de Dano: destrua quantos monstros seu oponente controlar forem possíveis, então cause 300 de dano a ele para cada Monstro Link no seu Cemitério.\r\nEnquanto estiver com a face para cima no campo, este card também é de Atributo LUZ, ÁGUA, FOGO e VENTO.\r\nNão é afetado por efeitos ativados de monstros que compartilham um Atributo com este card.\r\nSe este card seria destruído por batalha ou efeito, ao invés disso você pode fazer com que ele perca exatamente 1000 de ATK.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13204145,'Criador Mimicarniçal',replace(replace('Revele 2 monstros de Virar com nomes diferentes do seu Deck, seu oponente elege 1 deles aleatoriamente para que você Invoque por Invocação-Especial no campo dele com a face para baixo em Posição de Defesa e você adiciona o outro à sua mão e, depois, você pode Invocar por Invocação-Especial 1 monstro "Mimicarniçal" da sua mão. \r\nSe seu oponente Invocar um ou mais monstros por Invocação-Especial (exceto durante a Etapa de Dano): você pode banir este card do seu Cemitério e, depois, escolha 1 monstro com a face para baixo que seu oponente controla; coloque-o com a face para cima em Posição de Ataque ou de Defesa. \r\nVocê só pode usar 1 efeito de "Criador Mimicarniçal" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Mudar a posição de batalha','Invocar por Invocação Especial da sua mão?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13210191,'Tempestade','Destrua tantas Magias/Armadilhas que você controla quanto possível e, depois, destrua tantas Magias/Armadilhas que seu oponente controla quanto possível, até o número de cards destruído por este efeito.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13215230,'Palhaço dos Sonhos','Se este card em Posição de Ataque for colocado com a face para cima em Posição de Defesa: escolha 1 monstro que seu oponente controla; destrua o alvo.','Destrua 1 monstro que seu oponente controla','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13220032,'Carregador Vylon','Todos os monstros de LUZ com a face para cima que você controla ganham 300 de ATK para cada Card de Equipamento equipado a este card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13224603,'Bugiganga Yata, a Vanguarda Brilhante',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) ao oferecer como Tributo 1 monstro Invocado por Invocação-Normal. \r\nVocê só pode usar cada um dos seguintes efeitos de "Bugiganga Yata, a Vanguarda Brilhante" uma vez por turno.\r\n● Durante sua Fase Principal, se este card foi Invocado por Invocação-Normal ou Especial neste turno, você pode: imediatamente depois que este efeito resolver, Invoque 1 monstro por Invocação-Normal.	\r\nSe isso acontecer, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros com o mesmo Tipo original que o desse monstro.\r\n● Se este card Invocado por Invocação-Especial por seu próprio efeito for oferecido como Tributo: ganhe 2050 PV.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13234975,'Aterrissagem Bezoudado',replace(replace('Invoque por Invocação-Fusão 1 Monstro de Fusão Inseto do seu Deck Adicional, usando monstros da sua mão ou do campo como Matéria de Fusão. \r\nSe este card estiver no seu Cemitério, exceto no turno em que foi enviado para lá: você pode banir 2 monstros Inseto do seu Cemitério; adicione este card à sua mão. \r\nVocê só pode usar este efeito de "Aterrissagem Bezoudado" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Fusão','Adicionar este card à sua mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13235258,'Escamas Corrosivas',replace(replace('Escolha 1 monstro Inseto que você controla; equipe este card a ele. \r\nEnquanto você controlar o monstro equipado, os monstros do seu oponente não podem atacar monstros Inseto, exceto o monstro equipado. \r\nEnquanto este card estiver equipado a um monstro, sempre que seu oponente Invocar um ou mais monstros por Invocação-Normal ou Especial, OU ativar um card ou efeito, coloque 1 Marcador de Escama em cada monstro com a face para cima que ele controla. \r\nCada monstro que seu oponente controla perde 100 de ATK/DEF para cada Marcador de Escama que tiver.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13241004,'Fofanimal Pinguim',replace(replace('Durante sua Fase Principal: você pode Invocar por Invocação-Especial 1 monstro "Fofanimal" da sua mão, exceto "Fofanimal Pinguim". \r\nEste efeito só pode ser usado uma vez enquanto este card estiver com a face para cima no campo. \r\nSe este card for enviado para o Cemitério como uma Matéria de Fusão para uma Invocação-Fusão de um Monstro de Fusão "Peladura": você pode comprar 2 cards e, depois, descartar 1 card. \r\nVocê só pode usar este efeito de "Fofanimal Pinguim" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13243124,'Homem-Alado das Chamas, o HERÓI Favorito',replace(replace('2 monstros com o mesmo Tipo, mas Atributos diferentes	\r\n(Este card deve ser sempre considerado como um card "HERÓI do Elemento".)	\r\nQuando um ataque for declarado envolvendo este card e um monstro com 2200 ou mais de ATK: você pode fazer com que este card ganhe 1000 de ATK e, depois, você pode Invocar por Invocação-Especial 1 monstro de Nível 4 ou menos da sua mão em Posição de Defesa. \r\nSe um ou mais monstros foram destruídos em batalha neste turno (Efeito Rápido): você pode Invocar por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional, usando monstros da sua mão ou do campo. \r\nVocê só pode usar cada efeito de "Homem-Alado das Chamas, o HERÓI Favorito" uma vez por turno.','\r',char(13)),'\n',char(10)),'Aumentar ATK','Invocação Fusão','Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13243125,'Homem-Alado das Chamas, o HERÓI Favorito',replace(replace('2 monstros com o mesmo Tipo, mas Atributos diferentes	\r\n(Este card deve ser sempre considerado como um card "HERÓI do Elemento".)	\r\nQuando um ataque for declarado envolvendo este card e um monstro com 2200 ou mais de ATK: você pode fazer com que este card ganhe 1000 de ATK e, depois, você pode Invocar por Invocação-Especial 1 monstro de Nível 4 ou menos da sua mão em Posição de Defesa. \r\nSe um ou mais monstros foram destruídos em batalha neste turno (Efeito Rápido): você pode Invocar por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional, usando monstros da sua mão ou do campo. \r\nVocê só pode usar cada efeito de "Homem-Alado das Chamas, o HERÓI Favorito" uma vez por turno.','\r',char(13)),'\n',char(10)),'Aumentar ATK','Invocação Fusão','Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13247801,'Perímetro de Defesa Autômato',replace(replace('Enquanto você controlar um monstro Máquina de Nível 7 ou mais, os monstros do seu oponente não podem escolher monstros Máquina de Nível 6 ou menos que você controla como alvo de ataques e, além disso, seu oponente não pode escolhê-los como alvo de efeitos de card. \r\nSe um ou mais monstros Máquina com a face para cima que você controla forem destruídos em batalha ou por um efeito de card: você pode escolher 1 monstro Máquina no seu Cemitério; adicione-o à sua mão. \r\nVocê só pode usar este efeito de "Perímetro de Defesa Autômato" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13250922,'Formigantitamanduá',replace(replace('Este card não pode ser Invocado por Invocação-Normal ou Baixado. \r\nEste card não pode ser Invocado por Invocação-Especial, exceto enviando 2 Cards de Magia ou Armadilha que você controla ao Cemitério. \r\nVocê pode destruir 1 Card de Magia ou Armadiilha que seu oponente controla. \r\nSe você ativar este efeito, este card não pode atacar durante este turno.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13256226,'Espírito de Neos, o HERÓI do Elemento',replace(replace('Quando um monstro do oponente declarar um ataque: você pode Invocar este card por Invocação-Especial da sua mão em Posição de Defesa e, se isso acontecer, ele não pode ser destruído em batalha. \r\nSe este card for Invocado por Invocação-Especial: você pode adicionar do seu Deck à sua mão 1 "Polimerização" ou 1 Magia/Armadilha que mencione um nome de card de monstro "HERÓI do Elemento". \r\nDurante sua Fase Principal: você pode embaralhar este card no Deck e, se isso acontecer, Invoque por Invocação-Especial 1 Monstro Normal "HERÓI do Elemento" do seu Deck. \r\nVocê só pode usar cada efeito de "Espírito de Neos, o HERÓI do Elemento" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13258285,'Sharakusai Ukiyoe-P.U.N.K.',replace(replace('Você pode pagar 600 PV; Invoque por Invocação-Fusão 1 Monstro de Fusão "P.U.N.K." do seu Deck Adicional, usando monstros da sua mão ou do campo como matéria. \r\nDurante o turno do seu oponente (Efeito Rápido): você pode pagar 600 PV; imediatamente depois que este efeito resolver, Invoque por Invocação-Sincro 1 Monstro Sincro "P.U.N.K." usando monstros que você controla como matéria. \r\nVocê só pode usar cada efeito de "Sharakusai Ukiyoe-P.U.N.K." uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13289758,'Fluxo Gaia, a Força Graciosa',replace(replace('2+ monstros de Nível 6	\r\nUma vez por turno, você também pode Invocar "Fluxo Gaia, a Força Graciosa" por Invocação-Xyz ao usar 1 Monstro Xyz de Classe 5 ou 7 que você controla (transfira as matérias dele para este card). \r\nNão pode ser usado como matéria para uma Invocação-Xyz no turno em que foi Invocado por Invocação-Xyz. \r\nNão pode atacar diretamente. \r\nGanha ATK igual aos Níveis/Classes combinados de suas matérias associadas x 200. \r\nNo final da Etapa de Dano, se este card batalhou: desassocie 1 matéria deste card.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Xyz usando um Monstro Xyz de Classe 5 ou 7 como matéria?','Desassociar Matéria Xyz','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13291886,'Duque Dominador Vaylantz',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nSe "Mundo Vaylantz - Konig Wissen" estiver em uma Zona do Campo ou se você controlar um monstro "Vaylantz" de FOGO: você pode Invocar este card por Invocação-Especial na sua Zona de Monstros Principal em sua mesma coluna. \r\nVocê só pode usar este efeito de "Duque Dominador Vaylantz" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nVocê pode escolher 1 card Baixado na Zona de Magias & Armadilhas; esse card Baixado não pode ser ativado neste turno (mesmo que este card deixe o campo). \r\nSe este card na Zona de Monstros se mover para outra Zona de Monstros: você pode escolher 1 monstro com a face para cima na Zona de Monstros Principal do seu oponente; tome o controle desse monstro com a face para cima, mas ele não pode declarar um ataque nem ativar seus efeitos e, além disso, ele é considerado como um monstro "Vaylantz". \r\nVocê só pode usar cada efeito de "Duque Dominador Vaylantz" uma vez por turno.','\r',char(13)),'\n',char(10)),'Escolha o card cuja ativação será proibida','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13293158,'HERÓI Maligno Ciclone Selvagem',replace(replace('"Aviário, o HERÓI do Elemento" + "Coração Selvagem, o HERÓI do Elemento"	\r\nDeve ser Invocado por Invocação-Especial com "Fusão Negra". \r\nSe este card atacar, seu oponente não pode ativar nenhum Card de Magia/Armadilha até o final da Etapa de Dano. \r\nSe este card causar dano de batalha ao seu oponente: destrua todas as Magias/Armadilhas Baixadas que seu oponente controla.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13298352,'Yaguramaru, o Ninja de Armadura',replace(replace('2 monstros "Ninja" com Tipos diferentes	\r\nPrimeiro deve ser Invocado por Invocação-Fusão, ou Invocado por Invocação-Especial do seu Deck Adicional ao oferecer como Tributo os cards acima. \r\nSe este card for Invocado por Invocação-Especial ou virado com a face para cima: você pode banir 1 outro card "Ninja" ou "Ninjitsu" da sua mão, do Cemitério ou do campo com a face para cima e, depois, escolha 1 card no campo; bana-o. \r\nVocê só pode usar este efeito de "Yaguramaru, o Ninja de Armadura" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13301895,'Paraíso Caído',replace(replace('Seu oponente não pode escolher "Uria, o Senhor das Chamas Cortantes", "Hamon, o Senhor do Trovão Impactante", "Raviel, o Senhor dos Fantasmas" ou "Armityle, o Fantasma do Caos" nas suas Zonas de Monstros como alvos de efeitos de card e, além disso, esses monstros não podem ser destruídos pelos efeitos de card do seu oponente enquanto você os controlar. \r\nSe você controlar "Uria, o Senhor das Chamas Cortantes", "Hamon, o Senhor do Trovão Impactante", "Raviel, o Senhor dos Fantasmas" ou "Armityle, o Fantasma do Caos" na sua Zona de Monstros: você pode comprar 2 cards. \r\nVocê só pode usar este efeito de "Paraíso Caído" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13302026,'Rainha Borboleta Danaus',replace(replace('Se você controlar este card Invocado por Invocação-Normal/Baixado (Efeito Rápido): você pode escolher até 3 monstros Inseto de Nível 4 ou menos no seu Cemitério; mude o ATK deste card para 0 e, se isso acontecer, Invoque esses monstros por Invocação-Especial, mas seus efeitos são negados. \r\nVocê só pode usar este efeito de "Rainha Borboleta Danaus" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13313278,'Boxeador Obstinado de Máscara','Quando você sofre dano de batalha: você pode Invocar este card por Invocação-Especial da sua mão e, se isso acontecer, ganhe Pontos de Vida igual ao dano que você sofreu.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13314457,'Macrotrema das Profundezas','Quando este card for enviado do campo para o Cemitério, todos os monstros de ÁGUA com a face para cima que você controla ganham 500 de ATK até o final deste turno.','Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13316346,'Soldado de Inicialização - Dínamo de Horror','Enquanto você controlar um monstro "Dispositivo", este card ganha 2000 de ATK.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13317419,'Mão Foguete',replace(replace('Escolha 1 monstro em Posição de Ataque que você controla com 800 ou mais de ATK; equipe este card no alvo. \r\nEle ganha 800 de ATK. \r\nVocê pode enviar este card equipado para o Cemitério e, depois, escolher 1 card com a face para cima no campo; destrua-o e, depois, mude para 0 o ATK do monstro ao qual este card estava equipado e, além disso, sua posição de batalha não pode ser mudada. \r\nVocê só pode usar 1 efeito de "Mão Foguete" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13331639,'Rei Supremo Z-ARC',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nMonstros de Fusão, Sincro e Xyz que seu oponente controla não podem ativar seus efeitos. \r\nUma vez por turno, quando um ou mais cards forem adicionados do Deck Principal à mão do seu oponente (exceto durante a Fase de Compra ou Etapa de Dano): você pode destruir esse(s) card(s).\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\n4 monstros Dragão (1 de Fusão, 1 Sincro, 1 Xyz e 1 Pêndulo)	\r\nDeve ser Invocado por Invocação-Fusão. \r\nSe este card for Invocado por Invocação-Especial: destrua todos os cards que seu oponente controla. \r\nNão pode ser destruído pelos efeitos de card do seu oponente. \r\nSeu oponente não pode escolher este card como alvo de efeitos de card. \r\nQuando este card destruir um monstro do oponente em batalha: você pode Invocar por Invocação-Especial 1 monstro "Rei Supremo Dragão" do seu Deck ou Deck Adicional. \r\nSe este card na Zona de Monstros for destruído em batalha ou por um efeito de card: você pode colocar este card na sua Zona de Pêndulo.','\r',char(13)),'\n',char(10)),'Destruir o card adicionado à mão','Destruir todos os cards que seu oponente controla','Invoque por Invocação Especial 1 monstro "Rei Supremo Dragão" do seu Deck ou Deck Adicional','Colocar este card na sua Zona de Pêndulo','','','','','','','','','','','','');
INSERT INTO texts VALUES(13331640,'Rei Supremo Z-ARC',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nMonstros de Fusão, Sincro e Xyz que seu oponente controla não podem ativar seus efeitos. \r\nUma vez por turno, quando um ou mais cards forem adicionados do Deck Principal à mão do seu oponente (exceto durante a Fase de Compra ou Etapa de Dano): você pode destruir esse(s) card(s).\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\n4 monstros Dragão (1 de Fusão, 1 Sincro, 1 Xyz e 1 Pêndulo)	\r\nDeve ser Invocado por Invocação-Fusão. \r\nSe este card for Invocado por Invocação-Especial: destrua todos os cards que seu oponente controla. \r\nNão pode ser destruído pelos efeitos de card do seu oponente. \r\nSeu oponente não pode escolher este card como alvo de efeitos de card. \r\nQuando este card destruir um monstro do oponente em batalha: você pode Invocar por Invocação-Especial 1 monstro "Rei Supremo Dragão" do seu Deck ou Deck Adicional. \r\nSe este card na Zona de Monstros for destruído em batalha ou por um efeito de card: você pode colocar este card na sua Zona de Pêndulo.','\r',char(13)),'\n',char(10)),'Destruir o card adicionado à mão','Destruir todos os cards que seu oponente controla','Invoque por Invocação Especial 1 monstro "Rei Supremo Dragão" do seu Deck ou Deck Adicional','Colocar este card na sua Zona de Pêndulo','','','','','','','','','','','','');
INSERT INTO texts VALUES(13332685,'Ame no Habakiri no Mitsurugi',replace(replace('Você pode Invocar este card por Invocação-Ritual com "Ritual de Mitsurugi". \r\nMonstros que seu oponente controla perdem 800 de ATK. \r\nVocê pode revelar este card na sua mão; Invoque por Invocação-Especial 1 monstro "Mitsurugi" do seu Deck e, depois, ofereça como Tributo 1 monstro que você controla. \r\nVocê só pode usar este efeito de "Ame no Habakiri no Mitsurugi" uma vez por Duelo. \r\nSe este card for oferecido como Tributo: você pode adicionar 1 card "Mitsurugi" do seu Deck à sua mão, exceto "Ame no Habakiri no Mitsurugi" e, depois, você pode Invocar este card por Invocação-Especial. \r\nVocê só pode usar este efeito de "Ame no Habakiri no Mitsurugi" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial e depois Oferecer como Tributo','','Adicionar à mão','Invocação Especial?','','','','','','','','','','','','');
INSERT INTO texts VALUES(13361027,'Lança Negra Dragunidade','Uma vez por turno: você pode oferecer como Tributo 1 monstro Dragão "Dragunidade" e, depois, escolha 1 monstro Besta Alada de Nível 4 ou menos no seu Cemitério; Invoque o alvo por Invocação-Especial.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13364097,'Portão do Mundo Virtual - Chuche',replace(replace('Você pode escolher 1 card com a face para cima no campo; embaralhe 2 dos seus cards "Mundo Virtual" banidos com nomes diferentes um do outro no Deck e, depois, destrua esse card. \r\nDurante sua Fase Principal: você pode banir este card do seu Cemitério e, depois, escolha 1 monstro "Mundo Virtual" que você controla; até o final deste turno, aumente ou diminua o Nível/Classe dele em 3. \r\nVocê só pode usar cada efeito de "Portão do Mundo Virtual - Chuche" uma vez por turno.','\r',char(13)),'\n',char(10)),'Destruir','Alterar Nível/Classe','Aumentar','Reduzir','','','','','','','','','','','','');
INSERT INTO texts VALUES(13379114,'Fervor do Arquidemônio',replace(replace('Se você controlar um Monstro de Ritual "Arquidemônio" na Zona de Monstros Adicional: você pode escolher 1 card com a face para cima que seu oponente controla; negue seus efeitos até o final deste turno. \r\nSe este card for banido da mão ou do campo: você pode adicionar 1 card "Arquidemônio" do seu Deck à sua mão, exceto "Fervor do Arquidemônio". \r\nVocê só pode usar cada efeito de "Fervor do Arquidemônio" uma vez por turno.','\r',char(13)),'\n',char(10)),'Negar o efeito','Efeito de busca','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13382806,'Vinha de Prata Senri',replace(replace('Você pode oferecer este card como Tributo e, depois, escolha 1 monstro de Nível 2 no seu Cemitério, exceto "Vinha de Prata Senri"; Invoque-o por Invocação-Especial e, depois, você pode Invocar por Invocação-Especial 1 monstro de Nível 2 da sua mão com um Atributo diferente que o do monstro Invocado por Invocação-Especial por este efeito. \r\nVocê só pode usar este efeito de "Vinha de Prata Senri" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial um monstro de Nível 2 da sua mão?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13386407,'Voraz Vendorror',replace(replace('Invoque por Invocação-Especial 1 monstro "Vendorror" da sua mão, do Deck ou do Cemitério com a face para baixo em Posição de Defesa, exceto "Carniceiro Vendorror" e, depois, aplique o seguinte efeito.\r\n● Invoque por Invocação-Ritual qualquer 1 Monstro de Ritual "Vendorror" da sua mão ou do Cemitério ao oferecer como Tributo monstros que você controla, incluindo o monstro Invocado por Invocação-Especial por este card, cuja soma dos Níveis seja igual ou exceda o Nível do Monstro de Ritual.	\r\nVocê só pode ativar 1 "Voraz Vendorror" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13386503,'Cavaleiro Fantasma de Jackal','Quando este card destruir um monstro do oponente em batalha e enviá-lo para o Cemitério: você pode escolher esse monstro destruído no Cemitério do seu oponente; Invoque o alvo por Invocação-Especial no seu campo em Posição de Defesa.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13391185,'Nobre Cavaleiro Gwalchavad',replace(replace('Este card é considerado como um Monstro Normal enquanto estiver no campo com a face para cima. \r\nEnquanto estiver equipado com um Card de Magia de Equipamento "Armas Nobres", este card se torna um Monstro de Efeito com este efeito.\r\n● Você pode escolher 1 monstro "Nobre Cavaleiro" em seu Cemitério; adicione-o à sua mão e, se isso acontecer, destrua 1 Card de Magia de Equipamento "Armas Nobres" que você controla.	\r\nVocê só pode usar este efeito de "Nobre Cavaleiro Gwalchavad" uma vez por turno.','\r',char(13)),'\n',char(10)),'Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13408726,'Necroz de Metaltron',replace(replace('Escala de Pêndulo = 5\r\n[ Efeito de Pêndulo ]\r\nSe um ou mais cards "Necroz" seus forem banidos com a face para cima (exceto durante a Etapa de Dano): você pode escolher 1 Magia/Armadilha no campo; bana-a. \r\nVocê só pode usar este efeito de "Necroz de Metaltron" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nVocê pode Invocar este card por Invocação-Ritual com qualquer Magia de Ritual "Necroz". \r\nDeve ser Invocado por Invocação-Ritual, usando monstros, e você não pode usar monstros de Nível 9. \r\nDurante a Fase Principal (Efeito Rápido): você pode escolher 1 monstro com a face para cima que seu oponente controla; bana este card (até a Fase Final) e, se isso acontecer, bana esse monstro. \r\nVocê só pode usar este efeito de "Necroz de Metaltron" uma vez por turno. \r\nQualquer monstro destruído em batalha com um monstro "Necroz" seu é banido.','\r',char(13)),'\n',char(10)),'Banir uma Magia/Armadilha','Banir 1 monstro','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13409151,'Tapir do Deserto',replace(replace('VIRE: Vire 1 monstro no Campo com a face para cima para a Posição de Defesa com a face para baixo. \r\nVocê não pode escolher "Tapir do Deserto".','\r',char(13)),'\n',char(10)),'Mudar para Posição de Defesa com a face para baixo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13429800,'O Grande Branco','Um tubarão branco gigante com dentes afiados como lâminas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13438207,'Bombardeio do Florescimento','Quando um monstro do Tipo Planta que você controla destruir um monstro do oponente em batalha e enviá-lo para o Cemitério: cause dano ao seu oponente igual ao ATK do monstro destruído no Cemitério.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13452889,'Arquidemônio Vetor Assustador',replace(replace('2+ monstros Ciberso	\r\nQuando este card destruir um monstro do oponente em batalha e enviá-lo para o Cemitério: você pode oferecer como Tributo 1 monstro para o qual este card apontar; Invoque esse monstro destruído por Invocação-Especial em qualquer zona para a qual este card apontar. \r\nSe você Invocar por Invocação-Especial no campo do seu oponente devido a este efeito, este card pode realizar um segundo ataque durante esta Fase de Batalha (embora seu oponente ganhe o controle desse monstro Invocado por Invocação-Especial).','\r',char(13)),'\n',char(10)),'','Invocar por Invocação Especial para o seu campo?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13455674,'Cristron Quariongandrax',replace(replace('2+ Reguladores + 1 monstro não-Regulador	\r\nSe este card for Invocado por Invocação-Sincro: você pode escolher monstros que seu oponente controla e/ou no Cemitério dele, até o número de matérias usadas para a Invocação-Sincro deste card; bana-os. \r\nSe este card Invocado por Invocação-Sincro for destruído em batalha ou por um efeito de card: você pode escolher 1 monstro banido, exceto este card; Invoque-o por Invocação-Especial no seu campo.','\r',char(13)),'\n',char(10)),'Banir um monstro do oponente','Invoque por Invocação Especial um monstro banido','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13455953,'Dverg do Alfar Nórdico',replace(replace('Depois que você Invocar este card por Invocação-Normal, você pode Invocar por Invocação-Normal 1 monstro "Nórdic" durante sua Fase Principal neste turno, em adição à sua Invocação-Normal/Baixar (padrão). \r\n(Você só pode se aproveitar deste efeito uma vez por turno.) \r\nSe este card com a face para cima no campo for enviado para o Cemitério: escolha 1 card "Relíquia Nórdica" no seu Cemitério; adicione o alvo à sua mão.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Invocar pelo efeito de "Dverg do Alfar Nórdico"','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13474291,'Nuviano - Dragão da Tempestade',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro deve ser Invocado por Invocação-Especial (da sua mão) ao banir 1 monstro "Nuviano" do seu Cemitério. \r\nNão pode ser destruído em batalha. \r\nSe este card estiver com a face para cima em Posição de Defesa, destrua-o. \r\nUma vez por turno: você pode escolher 1 monstro com a face para cima no campo; coloque 1 Marcador de Névoa no alvo.','\r',char(13)),'\n',char(10)),'Colocar um marcador','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13478040,'Roinoz',replace(replace('Cada vez que seu oponente Invocar um ou mais monstros por Invocação-Especial, coloque 1 Marcador de Noz neste card. \r\nVocê pode remover 1 Marcador de Noz deste card para escolher 1 monstro que seu oponente controla; destrua o alvo.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13482075,'Quimera Vendorror',replace(replace('Você pode Invocar este card por Invocação-Ritual com qualquer Magia de Ritual "Vendorror". \r\nQuando um card ou efeito for ativado que destruiria um card no campo (Efeito Rápido): você pode banir 1 monstro Zumbi do seu Cemitério; negue a ativação e, se isso acontecer, destrua esse card. \r\nSe este card for oferecido como Tributo, ou banido, para uma Invocação-Ritual: todos os monstros que seu oponente controla perdem 500 de ATK/DEF. \r\nVocê só pode usar cada efeito de "Quimera Vendorror" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13482262,'Diabretiço de Tanatose',replace(replace('Quando este card for ativado: você pode revelar 1 monstro "Diabretiço" da sua mão e Invocar por Invocação-Especial do seu Deck 2 monstros com o nome desse monstro e, depois, embaralhar o monstro revelado no Deck. \r\nUma vez por turno, se um Monstro de Ritual for Invocado por Invocação-Especial no seu campo (exceto durante a Etapa de Dano): você pode escolher 1 card no campo; destrua-o. \r\nVocê só pode ativar 1 "Diabretiço de Tanatose" por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13486638,'Garra Cavaleiros Fantasmas do Ataqueraptor',replace(replace('Quando um efeito de monstro for ativado: desassocie 1 matéria de um Monstro Xyz de TREVAS seu; negue a ativação e, se isso acontecer, destrua esse card e, depois, se a matéria desassociada era um card "Os Cavaleiros Fantasmas", "Ataqueraptor" ou "Dragão Xyz", 1 Monstro Xyz "Ataqueraptor" que você controla ganha ATK igual ao ATK original desse monstro destruído. \r\nVocê só pode ativar 1 "Garra Cavaleiros Fantasmas do Ataqueraptor" por turno.','\r',char(13)),'\n',char(10)),'Escolha o card da qual você vai desassociar a Matéria Xyz','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13492423,'Imperador de Fóton','Quando este card for Invocado por Invocação-Normal ou Invocação-Virar: Você pode Invocar por Invocação-Especial 1 "Imperador de Fóton" da sua mão ou Deck.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13504844,'Chamada Emergencial de Gottoms','Se um monstro "Sabre-X" estiver no campo: escolha 2 monstros "Sabre-X" em quaisquer Cemitérios; Invoque os dois por Invocação-Especial no seu campo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13510157,'Cão da Tistina',replace(replace('Se este card estiver na sua mão ou no Cemitério e você controlar um monstro "Tistina" de LUZ: você pode Invocar este card por Invocação-Especial. \r\nVocê só pode usar este efeito de "Cão da Tistina" uma vez por turno. \r\nMonstros "Tistina" que você controla podem atacar diretamente enquanto seu oponente controlar um monstro com a face para baixo em Posição de Defesa.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13513663,'Castelo de Almas de Dragão',replace(replace('Uma vez por turno: você pode banir 1 monstro Dragão do seu Cemitério e, depois, escolher 1 monstro que você controla; ele ganha 700 de ATK até o final deste turno (mesmo que este card deixe o campo). \r\nQuando este card com a face para cima no campo for enviado para o Cemitério: você pode escolher 1 dos seus monstros Dragão banidos; Invoque o alvo por Invocação-Especial. \r\nVocê só pode controlar 1 "Castelo de Almas de Dragão".','\r',char(13)),'\n',char(10)),'Aumentar ATK','Invocação Especial','Usar o efeito de "Castelo de Almas de Dragão" agora?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13518809,'Ruína, a Rainha Suprema do Esquecimento',replace(replace('Você pode Invocar este card por Invocação-Ritual com "Ciclo do Mundo". \r\nO nome deste card se torna "Ruína, a Rainha do Esquecimento" enquanto estiver na mão ou no campo. \r\nEnquanto este card Invocado por Invocação-Ritual estiver no campo, os Monstros de Ritual que você controla não podem ser destruídos por efeitos de card. \r\nSe todos os monstros usados para a Invocação-Ritual deste card eram Monstros de Ritual, ele pode realizar um segundo ataque durante cada Fase de Batalha. \r\nSe este card destruir um monstro do oponente em batalha: você pode causar dano ao seu oponente igual ao ATK original desse monstro destruído.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13521194,'Patrulha de Rua de Estígia',replace(replace('Se este card destruir um monstro em batalha e enviá-lo para o Cemitério: cause dano ao seu oponente igual ao Nível original desse monstro no Cemitério x 100. \r\nVocê pode banir este card do seu Cemitério; Invoque por Invocação-Especial 1 monstro Demônio com 2000 ou menos de ATK da sua mão.','\r',char(13)),'\n',char(10)),'Causar dano','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13522325,'Espírito das Chamas',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro deve ser Invocado por Invocação-Especial (da sua mão) ao banir 1 monstro de FOGO do seu Cemitério. \r\nGanha 300 de ATK apenas durante sua Fase de Batalha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13529466,'Caliga, o Invokado',replace(replace('"Aleister, Aquele que Invoka" + 1 monstro de TREVAS	\r\nCada duelista só pode tentar ativar 1 efeito de monstro por turno. \r\nCada duelista só pode atacar com 1 monstro durante cada Fase de Batalha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13532663,'Golem Pateta',replace(replace('VIRE: O seu adversário escolhe 1 monstro que ele controla. \r\nTroque o controle do monstro escolhido e deste card.','\r',char(13)),'\n',char(10)),'Trocar o controle','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13533678,'Jato Spright',replace(replace('Se você controlar um monstro de Nível/Classe 2, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Jato Spright" por Invocação-Especial uma vez por turno desta forma. \r\nSe este card for Invocado por Invocação-Especial: você pode adicionar 1 Magia/Armadilha "Spright" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Jato Spright" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13536606,'Hidra V-LAN',replace(replace('2+ monstros, exceto Fichas	\r\nGanha 300 de ATK para cada monstro co-linkado a este card. \r\nVocê pode escolher 1 monstro de Link-3 ou menos co-linkado a este card; ofereça-o como Tributo e, se isso acontecer, Invoque por Invocação-Especial "Ficha de V-LAN" (Ciberso/LUZ/Nível 1/ATK 0/DEF 0) igual ao Valor Link do monstro oferecido como Tributo e, além disso, você não pode Invocar monstros por Invocação-Especial com o mesmo Valor Link que o desse monstro alvo pelo resto deste turno. \r\nVocê só pode usar este efeito de "Hidra V-LAN" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13536607,'Ficha de V-LAN','Invocado por Especial com o efeito "Hidra V-LAN".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13556444,'Miragem da Poeira Estelar',replace(replace('Se você controlar um Monstro Sincro Dragão de Nível 8 ou mais: Invoque por Invocação-Especial tantos monstros quanto possível do seu Cemitério que foram destruídos e enviados para o seu Cemitério em batalha ou por um efeito de card do oponente neste turno. \r\nVocê só pode ativar 1 "Miragem da Poeira Estelar" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13567610,'Carnot, a Máquina Eterna',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro deve ser Invocado por Invocação-Especial (da sua mão ou do Cemitério) durante um Duelo no qual seu oponente tenha ativado um efeito de monstro na mão ou no Cemitério dele. \r\nVocê só pode Invocar "Carnot, a Máquina Eterna" por Invocação-Especial uma vez por turno. \r\nUma vez por turno, se seu oponente ativar um efeito de monstro (exceto durante a Etapa de Dano): você pode fazer com que este card ganhe 1000 de ATK. \r\nSe este card for enviado para o Cemitério, exceto da mão ou do Deck: embaralhe este card no Deck.','\r',char(13)),'\n',char(10)),'Aumentar ATK','Retornar ao Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13574687,'Canhão Turbo',replace(replace('"Turbofoguete" + 1 ou mais monstros não-Reguladores	\r\nUma vez por turno, você pode destruir 1 monstro com a face para cima no campo e causar dano ao seu controlador igual à metade do ATK dele.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13582837,'Gerador de Aleatoriedade Inférnico',replace(replace('Uma vez por turno, enquanto você não tiver cards na sua mão, você pode comprar 1 card e revelá-lo. \r\nPara um Card de Monstro comprado com este efeito, cause dano ao seu oponente igual ao Nível desse monstro x 200. \r\nPara um Card de Magia ou Armadilha, você sofre 500 de dano.','\r',char(13)),'\n',char(10)),'Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13597785,'Lucina de Elfnota',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) em sua Zona de Monstros Principal central. \r\nVocê só pode Invocar "Lucina de Elfnota" por Invocação-Especial uma vez por turno desta forma. \r\nVocê só pode usar cada um dos seguintes efeitos de "Lucina de Elfnota" uma vez por turno. \r\nDurante sua Fase Principal: você pode adicionar 1 monstro "Elfnota" do seu Deck à sua mão, exceto "Lucina de Elfnota". \r\nDurante o turno do seu oponente (Efeito Rápido): você pode trocar as localizações deste card na sua Zona de Monstros Principal e o monstro na sua Zona de Monstros Principal central e, depois, você pode devolver 1 monstro de Nível 6 ou menos que seu oponente controla para a mão.','\r',char(13)),'\n',char(10)),'Adicionar à mão um monstro','Trocar posições','Retornar o monstro para a mão?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13599884,'Escorpião de Aço','Um monstro que não seja do Tipo Máquina, que esteja atacando "Escorpião de Aço" é destruído na End Phase do 2º turno do seu adversário depois do turno do ataque.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13604200,'Pedra da Magia','Se você controlar um "Pequena Maga Negra" com a face para cima: Invoque por Invocação-Especial 1 "Mago Negro" da sua mão ou do Deck.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13611090,'Estrondo Majespectro','Escolha 1 monstro "Majespectro" que você controla; até o final deste turno, o ATK e DEF dele se tornam o dobro do seu ATK e DEF atuais e, além disso, qualquer dano de batalha que ele causar ao seu oponente é diminuído pela metade.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13626450,'Dispersão Maldosa','Descarte 1 card; destrua todas as Armadilhas Contínuas com a face para cima no campo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13629812,'Arte Ninjitsu do Sigilo das Sombras',replace(replace('Ative este card ao oferecer como Tributo 1 monstro "Ninja" e, depois, escolha 1 monstro que seu oponente controla; bana o alvo. \r\nEnquanto esse monstro estiver banido, a Zona de Cards de Monstro dele não pode ser usada. \r\nQuando este card com a face para cima deixar o campo: devolva o card banido por este efeito à mesma Zona de Cards de Monstro, na mesma posição de batalha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13647631,'Trem de Carga Pesada Grundaste',replace(replace('Se um ou mais monstros Máquina de TERRA forem Invocados por Invocação-Normal ou Especial no seu campo (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão, mas seu ATK/DEF originais são diminuídos pela metade. \r\nVocê só pode usar este efeito de "Trem de Carga Pesada Grundaste" uma vez por turno. \r\nSe este card for desassociado de um Monstro Xyz e enviado para o Cemitério para ativar um efeito desse monstro: você pode escolher 1 card que seu oponente controla; destrua-o.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial da mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13650422,'HERÓI Maligno Ouro Ardente',replace(replace('Você pode descartar este card; adicione 1 "Fusão Negra", ou 1 card que o mencione, do seu Deck à sua mão, exceto "HERÓI Maligno Ouro Ardente". \r\nVocê só pode usar este efeito de "HERÓI Maligno Ouro Ardente" uma vez por turno. \r\nNão pode atacar a não ser que você controle um Monstro de Fusão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13662809,'Script do Abismo - Ascensão do Rei do Abismo',replace(replace('Escolha cards com a face para cima no campo, até o número de monstros "Ator do Abismo" em Posição de Ataque com nomes diferentes que você controla; destrua-os. \r\nSe você controlar um monstro "Ator do Abismo" de Nível 7 ou mais, seu oponente não pode ativar cards ou efeitos em resposta à ativação deste card. \r\nSe este card Baixado sob o controle do seu dono for destruído por um efeito de card do oponente e você tiver um Monstro Pêndulo "Ator do Abismo" com a face para cima no seu Deck Adicional: você pode adicionar até 2 cards "Ator do Abismo" e/ou Magias "Script do Abismo" com nomes diferentes do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13676474,'Grande Ancião Tiki','Um monstro mascarado que se utiliza das mais fatais maldições.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13683298,'Lobo Celeste da Trovoada',replace(replace('Se este card for Invocado por Invocação-Especial do Cemitério: você pode destruir todos os monstros com a face para cima que seu oponente controla. \r\nVocê não pode conduzir sua Fase de Batalha no turno em que ativar este efeito.','\r',char(13)),'\n',char(10)),'Destruir um monstro','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13685271,'Tratado de Nomenclatura Uniforme',replace(replace('Se você controlar 2 ou mais monstros com a face para cima com o mesmo nome, exceto Fichas: Aplique este efeito, dependendo de quantos você controla.\r\n● Exatamente 2: Destrua 1 Card de Magia/Armadilha que seu oponente controla.\r\n● Exatamente 3: Destrua todos os Cards de Magia/Armadilha que seu oponente controla.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13694209,'Dogmatika Ashiyan',replace(replace('Se um ou mais Monstros de Fusão, Sincro, Xyz ou Link forem enviados para o Cemitério (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe este card for Invocado por Invocação-Especial da mão: você pode escolher 1 card "Dogmatika" no seu Cemitério, exceto "Dogmatika Ashiyan"; adicione-o à sua mão. \r\nQuando um monstro do oponente declarar um ataque: você pode fazer com que todos os monstros "Dogmatika" que você controla atualmente ganhem 500 de ATK. \r\nVocê só pode usar cada efeito de "Dogmatika Ashiyan" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13708425,'Ressonador das Chamas','Um Monstro Sincro que usou este card como Matéria Sincro ganha 300 de ATK.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13708888,'HERÓI Maligno Senhor Neos',replace(replace('"Neos, o HERÓI do Elemento" (ou 1 Monstro de Fusão que o mencione) + 1 Monstro de Efeito no campo	\r\nDeve ser Invocado por Invocação-Especial com "Fusão Negra". \r\nNão pode ser destruído em batalha ou por efeitos de card. \r\nSe este card for Invocado por Invocação-Especial, ou se um ou mais monstros forem enviados para o Cemitério do seu oponente enquanto este card estiver no campo: você pode escolher 1 monstro com a face para cima que seu oponente controla; tome o controle dele. \r\nVocê só pode usar este efeito de "HERÓI Maligno Senhor Neos" uma vez por turno.','\r',char(13)),'\n',char(10)),'Tomar controle','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13722870,'Cavaleiro da Chama Negra',replace(replace('"Mago Negro" + "Espadachim das Chamas"	\r\nO dano ao controlador deste card de um combate em que este monstro esteja envolvido torna-se 0. \r\nQuando este card for destruído como resultado de um combate e enviado para o Cemitério, Invoque, por Invocação-Especial, 1 "Cavaleiro Miragem" da sua mão ou Deck.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13723605,'Baú de Tesouros, Devorador de Homens','Este monstro disfarçado de baú de tesouros e conhecido por atacar os aventureiros descuidados.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13735899,'Mysterion, a Coroa do Dragão',replace(replace('1 monstro Mago + 1 monstro Dragão	\r\nNão pode ser usado como Matéria de Fusão. \r\nPerde 100 de ATK para cada um dos seus cards banidos. \r\nSe um monstro usar seus efeitos ativados para Invocar a si mesmo, ou um ou mais monstros com seu mesmo Tipo original, por Invocação-Especial (exceto durante a Etapa de Dano): você pode escolher 1 desses monstros Invocados por Invocação-Especial; bana esse monstro e, além disso, bana todos os monstros do campo com o mesmo Tipo original. \r\nVocê só pode usar este efeito de "Mysterion, a Coroa do Dragão" uma vez por turno.','\r',char(13)),'\n',char(10)),'Banir 1 monstro','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13744068,'Arquidemônio Enfurecido',replace(replace('Você pode escolher até 2 monstros com a face para cima que você controla, incluindo um monstro Demônio; Invoque este card por Invocação-Especial da sua mão e, se isso acontecer, destrua esses monstros. \r\nVocê só pode usar este efeito de "Arquidemônio Enfurecido" uma vez por turno. \r\nQuando um ou mais monstros forem destruídos pelo efeito deste card: você pode escolher monstros com a face para cima que seu oponente controla igual ao número destruído; até o final do seu próximo turno, este card ganha ATK igual ao ATK original combinado deles.','\r',char(13)),'\n',char(10)),'Invocar este card por Invocação Especial','Aumentar ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13756293,'Rei Dragoon',replace(replace('"Senhor dos Dragões" + "Ragnarok, Dragão Sagrado"	\r\nSeu oponente não pode escolher monstros Dragão como alvo de efeitos de card. \r\nUma vez por turno: você pode Invocar por Invocação-Especial 1 monstro Dragão da sua mão.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13758665,'Mão Esquerda do Mago','Negue o efeito do primeiro Card ou efeito de Armadilha do seu oponente que resolver a cada turno enquanto você controlar um monstro Mago e, se isso acontecer, destrua esse card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13760677,'P.O. Captor',replace(replace('Escala de Pêndulo = 5\r\n[ Efeito de Pêndulo ]\r\nQuando você Invocar por Invocação-Pêndulo um ou mais monstros do Tipo Zumbi: você pode ativar este efeito; ele não pode ser destruído em batalha ou por efeitos de card neste turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe este card destruir um monstro em batalha: você pode escolher 1 Monstro Pêndulo no seu Cemitério; adicione-o à sua mão.','\r',char(13)),'\n',char(10)),'Não pode ser destruído em batalha ou por efeitos','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13761956,'Bebê de Flamvell','Você pode enviar este card da sua mão para o Cemitério e, depois, escolha 1 monstro de FOGO que você controla; o alvo ganha 400 de ATK.','Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13764602,'Perfeita Sinc - A-Un',replace(replace('Quando este card for ativado: você pode adicionar 1 monstro "Dois Avatares" do seu Deck à sua mão. \r\nSe você controlar um Monstro de Efeito "Dois Avatares": você pode Invocar por Invocação-Especial 1 "Ficha do Espírito dos Dois Avatares" (Guerreiro/LUZ/Nível 2/ATK 0/DEF 0) e, além disso, você não pode Invocar monstros por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto Monstros de Fusão. \r\nVocê só pode usar este efeito de "Perfeita Sinc - A-Un" uma vez por turno. \r\nVocê só pode ativar 1 "Perfeita Sinc - A-Un" por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão?','Invocar uma Ficha por Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13764603,'Ficha do Espírito dos Dois Avatares','Invocado por Especial com o efeito "Convite dos Dois Avatares" ou um card relacionado.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13764881,'Ressonador da Corrente','Quando este card for Invocado por Invocação-Normal enquanto um Monstro Sincro estiver no campo: você pode Invocar por Invocação-Especial 1 monstro "Ressonador" do seu Deck, exceto "Ressonador da Corrente".','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13803864,'Rei Mokey Mokey',replace(replace('"Mokey Mokey" + "Mokey Mokey" + "Mokey Mokey"	\r\nQuando este card é removido do Campo, você pode Invocar, por Invocação-Especial, tantos "Mokey Mokey" quanto possível, do seu Cemitério.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13821299,'Devorador de Armadilhas',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao enviar para o Cemitério 1 Armadilha com a face para cima que seu oponente controla.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13836592,'Behemoth, o Rei de Cem Batalhas',replace(replace('Você pode Invocar este card por Invocação-Tributo ao oferecer 1 monstro como Tributo. \r\nEste card não é afetado pelos efeitos ativados de monstros Invocados por Invocação-Especial se ele foi Invocado por Invocação-Normal/Baixado. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 monstro Besta, Besta-Guerreira ou Besta Alada no seu Cemitério; adicione-o à sua mão e, se isso acontecer, este card perde 700 de ATK. \r\nUma vez por turno, durante sua Fase Final: você pode fazer com que este card ganhe 700 de ATK.','\r',char(13)),'\n',char(10)),'Oferecer 1 monstro como Tributo para uma Invocação Tributo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13839120,'Dispositivo Amarelo','Quando este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 "Dispositivo Verde" do seu Deck à sua mão.','Adicione 1 "Dispositivo Verde" à sua mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13846680,'Imponência da Tempestade de Fogo','Quando este card for destruído em batalha e enviado para o Cemitério, destrua todos os monstros com a face para baixo e os que não sejam de FOGO.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13851202,'Cavaleirostélite Rigel',replace(replace('Se este card for Invocado: você pode escolher 1 monstro "Cavaleirost" no campo; ele ganha 500 de ATK, mas envie-o para o Cemitério durante a Fase Final. \r\nVocê só pode usar este efeito de "Cavaleirostélite Rigel" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13857930,'Musgo Cintilante Neoespacial',replace(replace('O nome deste card também é considerado como "Musgo Brilhante Neoespacial". 	\r\nEste card não pode ser Invocado por Invocação-Especial, exceto com "NEX". \r\nQuando este card atacar ou for atacado, compre 1 card. \r\nRevele este card e, baseado no seu tipo, aplique o efeito apropriado:\r\n● Monstro: Encerre a Fase de Batalha.\r\n● Magia: Você pode mudar o ataque deste card para um ataque direto.\r\n● Armadilha: Este monstro muda para Posição de Defesa.','\r',char(13)),'\n',char(10)),'Revelar a mão','Declarar um ataque direto?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13890468,'Avatar da Besta Espiritual Pettlefinho',replace(replace('Uma vez por turno: você pode banir 1 card "Besta Espiritual" da sua mão e, depois, escolher 1 card que seu oponente controla; devolva-o para a mão. \r\nVocê só pode Invocar "Avatar(es) da Besta Espiritual Pettlefinho" por Invocação-Especial uma vez por turno.','\r',char(13)),'\n',char(10)),'Retornar para a mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13893596,'Exodius, o Último Senhor Proibido',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nVocê deve Invocá-lo por Invocação-Especial (da sua mão) ao embaralhar todos os monstros do seu Cemitério no Deck e não pode Invocá-lo por Invocação-Especial de nenhuma outra forma. \r\nQuando este card declarar um ataque: envie 1 monstro da sua mão ou do Deck para o Cemitério. \r\nEste card ganha 1000 de ATK para cada Monstro Normal no seu Cemitério. \r\nSe este card com a face para cima deixaria o campo, em vez disso, bana-o. \r\nSe houver 5 cards "O Proibido" diferentes no seu Cemitério que foram enviados para lá pelo efeito deste card, você vence o Duelo.','\r',char(13)),'\n',char(10)),'Enviar um monstro para o Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13903402,'Mardel, Chefe Generaidora da Luz',replace(replace('Você só pode controlar 1 "Mardel, Chefe Generaidora da Luz". \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 card "Generaidor" ou 1 monstro Planta do seu Deck à sua mão, exceto "Mardel, Chefe Generaidora da Luz". \r\nVocê só pode usar este efeito de "Mardel, Chefe Generaidora da Luz" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13923256,'Guerreiros Antigos - Excêntrico Lu Jing',replace(replace('Você pode escolher 1 Magia/Armadilha Contínua que você controla; envie-a para o Cemitério e, se isso acontecer, adicione 1 Magia/Armadilha "Guerreiros Antigos" com um nome diferente do seu Cemitério à sua mão. \r\nSe outro efeito de um monstro "Guerreiros Antigos" seu for ativado (exceto durante a Etapa de Dano): você pode escolher 1 Magia/Armadilha que seu oponente controla; destrua-a. \r\nVocê só pode usar cada efeito de "Guerreiros Antigos - Excêntrico Lu Jing" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Destruir Magias/Armadilhas','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13927359,'Ataqueraptor - Brilhantes Gloriosos',replace(replace('Se você controlar um monstro "Ataqueraptor": escolha 1 monstro com a face para cima que seu oponente controla ou, se você controlar um Monstro Xyz "Ataqueraptor", você pode escolher 1 card com a face para cima que seu oponente controla; negue os efeitos desse card até o final deste turno. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 dos seus monstros "Ataqueraptor" que estiverem banidos ou no seu Cemitério; adicione-o à sua mão. \r\nVocê só pode usar 1 efeito de "Ataqueraptor - Brilhantes Gloriosos" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13935001,'Dança da Serenata Luzlunar',replace(replace('Quando um ou mais Monstros de Fusão forem Invocados por Invocação-Fusão no seu campo (exceto durante a Etapa de Dano): você pode escolher 1 desses monstros; aplique esses efeitos em sequência.\r\n● Invoque por Invocação-Especial 1 "Ficha Luzlunar" (Besta-Guerreira/TREVAS/Nível 4/ATK 2000/DEF 2000) no campo do seu oponente.\r\n● O alvo ganha 500 de ATK para cada monstro que seu oponente controla (mesmo que este card deixe o campo).	\r\nDurante sua Fase Principal: você pode banir este card do seu Cemitério; envie 1 card da sua mão para o Cemitério e, se isso acontecer, Invoque por Invocação-Especial 1 monstro "Luzlunar" do seu Deck. \r\nVocê só pode usar este efeito de "Dança da Serenata Luzlunar" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13935002,'Ficha Luzlunar','Invocada por Invocação-Especial com o efeito "Dança da Serenata Luzlunar".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13944422,'Granadora',replace(replace('Quando este card for Invocado por Invocação-Normal, Virar ou Especial, aumente seus PV em 1000. \r\nQuando este card for destruído e enviado para o Cemitério, você sofre 2000 de dano.','\r',char(13)),'\n',char(10)),'Ganhar 1000 PV','Causar 2000 de dano','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13945283,'Barreira Ilusória','Se este card for atacado por um monstro, depois do cálculo de dano: devolva esse monstro para a mão.','Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13955608,'Bastião, a Fortaleza Móvel',replace(replace('Invoque este card por Invocação-Especial em Posição de Defesa como um Monstro de Efeito (Máquina/TERRA/Nível 4/ATK 0/DEF 2000).	\r\n(Este card também é considerado uma Armadilha.) \r\nEnquanto você controlar um "Dispositivo Verde", "Dispositivo Vermelho" e "Dispositivo Amarelo", este card ganha 3000 de ATK.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13959634,'Moulingeleira, o Senhor Elemental',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao ter exatamente 5 monstros de ÁGUA no seu Cemitério. \r\nSe este card for Invocado por Invocação-Especial: descarte 2 cards aleatórios da mão do seu oponente (ou toda a mão dele, se ele tiver menos de 2). \r\nVocê só pode usar este efeito de "Moulingeleira, o Senhor Elemental" uma vez por turno. \r\nSe este card com a face para cima deixar o campo, pule a Fase de Batalha do seu próximo turno.','\r',char(13)),'\n',char(10)),'Descartar da mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13965201,'Fantasma Encontra Garota - Uma História Shiranui',replace(replace('Se seu oponente controlar um monstro: descarte 1 monstro Zumbi; Invoque por Invocação-Especial do seu Deck ou do Cemitério, 1 monstro "Shiranui" com um nome diferente do monstro descartado e, além disso, pelo resto deste turno depois que este card resolver, você não pode Invocar monstros por Invocação-Especial, exceto monstros Zumbi. \r\nVocê só pode ativar 1 "Fantasma Encontra Garota - Uma História Shiranui" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13972452,'Temporal Majespectro','Ofereça como Tributo 1 monstro de VENTO do Tipo Mago e, depois, escolha 1 monstro que seu oponente controla; embaralhe-o no Deck.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13974207,'Denko Sekka',replace(replace('Não pode ser Invocado por Invocação-Especial. \r\nEnquanto você não controlar Magias/Armadilhas Baixadas, nenhum duelista pode Baixar Magias/Armadilhas nem ativar Cards de Magia/Armadilha que estiverem Baixados no campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13995824,'Bicórnio Voltaico',replace(replace('1 Regulador do Tipo Besta + 1 ou mais monstros não-Reguladores	\r\nSe este card for destruído por um card do oponente (seja em batalha ou por um efeito de card), ambos os duelistas enviam os 7 cards do topo dos seus Deck para o Cemitério.','\r',char(13)),'\n',char(10)),'Enviar do Deck para o Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13997673,'Compressão do Núcleo',replace(replace('Revele 1 "Núcleo de Ferro de Koa''ki Meiru" na sua mão e descarte 1 monstro "Koa''ki Meiru" para ativar este card. \r\nCompre 2 cards.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14001430,'Castelo Magidoce',replace(replace('Quando este card for ativado: embaralhe no Deck todos os monstros "Magidoce" no seu Cemitério. \r\nTodos os monstros "Magidoce" no campo ganham 500 de ATK/DEF. \r\nSe um ou mais monstros no seu Cemitério seriam devolvidos para o Deck pelo efeito de um monstro "Magidoce", em vez disso, você pode adicioná-lo à sua mão.','\r',char(13)),'\n',char(10)),'Usar o efeito de "Castelo Magidoce"?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14005031,'Ritual da Dança da Lua',replace(replace('Ative este card ao escolher 1 Monstro Xyz de VENTO que você controla que não tenha Matérias Xyz. \r\nEnquanto esse monstro estiver no campo, negue os efeitos de todos os monstros com a face para cima no campo. \r\nQuando esse monstro deixar o campo, destrua este card. \r\nDurante a Fase Final do turno em que este card foi ativado: associe este card a esse monstro como uma Matéria Xyz.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14015067,'O Ancião da Floresta Profunda','Esta criatura adota a forma de uma cabra branca que vive na floresta mas, na realidade, é um Ancião da Floresta.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14017402,'Cavaleiro Dragão Draco-Equestre',replace(replace('1 Monstro Sincro Dragão + 1 monstro Guerreiro	\r\nPrimeiro deve ser Invocado por Invocação-Fusão. \r\nUma vez por turno: você pode escolher 1 Monstro Sincro Dragão no Cemitério; bana o alvo e, se isso acontecer, até a Fase Final, o nome deste card se torna o nome desse monstro e troque este efeito pelos efeitos originais desse monstro. \r\nEnquanto este card estiver em Posição de Ataque, seu oponente sofre todo dano de efeito que você teria sofrido dos efeitos dos cards dele, em vez de você.','\r',char(13)),'\n',char(10)),'Obter o efeito de um Monstro Sincro Dragão','Terminar o efeito copiado','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14025912,'Equação Mechamática',replace(replace('Escolha 1 monstro "Mechamático(a)" no seu Cemitério; Invoque-o por Invocação-Especial e, se isso acontecer, ele ganha 1000 de ATK até o final deste turno. \r\nVocê só pode ativar 1 "Equação Mechamática" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14037717,'Espírito dos Livros','Um espírito sábio que vive nos livros, acumulando conhecimento para derrotar seus inimigos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14047624,'Senhor do Julgamento Laval','Uma vez por turno: Faça o banimento de 1 monstro "Laval" do Cemitério para causar 1.000 de dano ao oponente. "Senhor do Julgamento Laval" não pode declarar um ataque no turno em que esse efeito for ativado.','Cause 1000 de dano ao seu oponente','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14055212,'Enterro Sereno',replace(replace('Envie 1 monstro do seu Deck para o Cemitério, mas pelo resto deste turno, você não pode ativar cards, ou os efeitos de cards, com o mesmo nome que o monstro enviado tinha no Cemitério. \r\nVocê só pode ativar 1 "Enterro Sereno" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14057297,'Destruição Múltipla',replace(replace('Se os dois duelistas tiverem 3 ou mais cards em suas mãos: cada duelista coloca sua mão no fundo do Deck em qualquer ordem e, além disso, você perde PV igual ao número total de cards devolvidos ao Deck por este efeito x 300 (mín. 1) e, depois, cada duelista compra 5 cards. \r\nVocê só pode ativar 1 "Destruição Múltipla" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14087893,'Livro da Lua','Escolha 1 monstro com a face para cima no campo; coloque o alvo com a face para baixo em Posição de Defesa.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14088859,'Fusão Neos',replace(replace('Envie da sua mão, do Deck ou do campo para o Cemitério, as Matérias de Fusão mencionadas em um Monstro de Fusão que mencione exatamente 2 monstros como matéria, incluindo "Neos, o HERÓI do Elemento" e, depois, Invoque por Invocação-Especial esse Monstro de Fusão do seu Deck Adicional, ignorando suas condições de Invocação. \r\nVocê não pode Invocar por Invocação-Especial pelo resto deste turno depois que este card resolver. \r\nSe um ou mais Monstros de Fusão que você controla que mencionem "Neos, o HERÓI do Elemento" como matéria seriam destruídos em batalha ou por um efeito de card, ou embaralhados no Deck Adicional por seu próprio efeito, em vez disso, você pode banir este card do seu Cemitério.','\r',char(13)),'\n',char(10)),'','Banir "Fusão Neos" em vez disso?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14089428,'Trovão Azul T-45',replace(replace('Se este card destruir um monstro do oponente em batalha: Invoque por Invocação-Especial 1 "Ficha de Opção Trovejante" (Tipo Máquina/LUZ/Nível 4/ATK 1500/DEF 1500). \r\nEsta Ficha não pode ser oferecida como Tributo para uma Invocação-Tributo.','\r',char(13)),'\n',char(10)),'Invocar uma Ficha por Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14089429,'Ficha de Opção Trovejante','Invocado por Especial com o efeito "Trovão Azul T-45". Esta Ficha não pode ser oferecida como Tributo para uma Invocação-Tributo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14094090,'Ritual do Super Soldado',replace(replace('Este card pode ser usado para a Invocação-Ritual de qualquer Monstro de Ritual "Soldado do Lustro Negro". \r\nVocê também deve oferecer como Tributo monstros da sua mão ou do campo cuja soma dos Níveis seja exatamente igual a 8. \r\nDurante sua Fase Principal, exceto no turno em que este card foi enviado para o Cemitério: você pode banir este card, 1 monstro de LUZ e 1 monstro de TREVAS do seu Cemitério; Invoque por Invocação-Especial 1 Monstro de Ritual "Soldado do Lustro Negro" da sua mão, ignorando suas condições de Invocação. \r\nVocê só pode usar este efeito de "Ritual do Super Soldado" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14105623,'Dragão Pêndulo Arc de Olhos Anômalos',replace(replace('Escala de Pêndulo = 8\r\n[ Efeito de Pêndulo ]\r\nSe um ou mais cards "Olhos Anômalos" com a face para cima que você controla forem destruídos em batalha ou por um efeito de card: você pode Invocar por Invocação-Especial 1 monstro "Olhos Anômalos" da sua mão, do Deck ou do Cemitério. Você só pode usar este efeito de "Dragão Pêndulo Arc de Olhos Anômalos" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nCriado a partir de milagres, esse dragão lindo e corajoso tem olhos brilhantes que refletem um arco desenhado nos céus.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14108995,'Vernasílfide Corola',replace(replace('Todos os monstros de TERRA que você controla também são considerados como monstros "Vernasílfide". \r\nUma vez por turno, se você descartaria um ou mais monstros "Vernasílfide" e 1 card para ativar o efeito desse monstro "Vernasílfide" na sua mão, em vez disso, você pode descartar apenas esse(s) monstro(s) "Vernasílfide".','\r',char(13)),'\n',char(10)),'Aplicar o efeito de "Vernasílfide Corola"?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14124483,'Neos Honesto, o HERÓI do Elemento',replace(replace('(Efeito Rápido): você pode descartar este card e, depois, escolha 1 monstro "HERÓI" no campo; ele ganha 2500 de ATK até o final deste turno. \r\n(Efeito Rápido): você pode descartar 1 monstro "HERÓI"; até o final deste turno, este card ganha ATK igual ao ATK do monstro descartado. \r\nVocê só pode usar cada efeito de "Neos Honesto, o HERÓI do Elemento" uma vez por turno.','\r',char(13)),'\n',char(10)),'Aumentar o ATK dos monstros "HERÓI"','Descarte 1 card para aumentar o ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14141448,'Grande Moth',replace(replace('Este card não pode ser invocado por Invocação-Normal ou Baixado. \r\nEste card só pode ser Invocado por Invocação-Especial oferecendo "Pequeno Moth" como Tributo no seu 4º turno depois do turno em que "Pequeno Moth" foi equipado com "Casulo de Evolução".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14146794,'Donyoribo @Ignister',replace(replace('Durante o cálculo de dano, se um monstro "@Ignister" seu for atacado (Efeito Rápido): você pode descartar este card; você não sofre dano de batalha dessa batalha. \r\nQuando um efeito de monstro "@Ignister", ou um card ou efeito de Magia/Armadilha "I.A.", for ativado que cause dano ao seu oponente, mesmo durante a Etapa de Dano (Efeito Rápido): você pode banir este card do seu Cemitério; dobre esse dano causado ao seu oponente. \r\nVocê só pode usar cada efeito de "Donyoribo @Ignister" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14148099,'B.E.S. Núcleo Grande',replace(replace('Se este card for Invocado por Invocação-Normal: coloque 3 marcadores sobre ele. \r\nNão pode ser destruído em batalha. \r\nNo final da Etapa de Dano, se este card batalhou: remova 1 marcador deste card. \r\nSe você não puder, destrua-o.','\r',char(13)),'\n',char(10)),'Colocar um marcador','Remover um marcador','Destruir','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14152693,'Pássaro Esmeralda Luzlunar',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode enviar 1 card "Luzlunar" da sua mão para o Cemitério e, se isso acontecer, compre 1 card. \r\nSe este card for enviado para o Cemitério por um efeito de card: você pode escolher 1 dos seus monstros "Luzlunar" de Nível 4 ou menos que estiver banido ou no seu Cemitério, exceto "Pássaro Esmeralda Luzlunar"; Invoque-o por Invocação-Especial em Posição de Defesa, mas negue seus efeitos. \r\nVocê só pode usar cada efeito de "Pássaro Esmeralda Luzlunar" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14152862,'Norito, o Líder Moral',replace(replace('2 monstros Mago de Nível 6	\r\nUma vez por turno, quando seu oponente ativar um Card de Magia/Armadilha (Efeito Rápido): você pode desassociar 1 matéria deste card; negue a ativação e, se isso acontecer, destrua-a.','\r',char(13)),'\n',char(10)),'Negar a ativação e destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14154221,'Evo-Preço','Uma vez por turno, se um monstro for Invocado por Invocação-Especial pelo efeito de um monstro "Evoltil" (exceto durante a Etapa de Dano): Você pode escolher 1 card no campo; destrua o alvo.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14166715,'Recette de Viande (Receita de Carne)',replace(replace('Este card pode ser usado para a Invocação-Ritual de qualquer Monstro de Ritual "Nouvelles". \r\nVocê também deve oferecer como Tributo monstros da sua mão ou do campo cuja soma dos Níveis seja igual ou exceda o Nível do Monstro de Ritual que você Invocar por Invocação-Ritual. \r\nDepois, se você Invocou por Invocação-Ritual "Confiras de Nouvelles", você pode aplicar o seguinte efeito.\r\n● Coloque em Posição de Ataque todos os monstros em Posição de Defesa que seu oponente controla atualmente.','\r',char(13)),'\n',char(10)),'Mudar todos os monstros do oponente para Posição de Ataque?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14169843,'Aromágico Louro',replace(replace('Se seus PV forem maiores que os do seu oponente: você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe você ganhar PV: escolha 1 monstro Planta não-Regulador no campo; ele é considerado como um Regulador neste turno. \r\nSe este card for enviado para o Cemitério: você pode ganhar 500 PV. \r\nVocê só pode usar cada efeito de "Aromágico Louro" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14181608,'Homem Cogumelo','Encontrada em regiões úmidas, esta criatura ataca inimigos com uma chuva letal de esporos venenosos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14198496,'Flautista Místico',replace(replace('Você pode oferecer este card como Tributo para comprar e revelar 1 card. \r\nSe esse card for um Card de Monstro de Nível 1, compre mais 1 card. \r\nO efeito de "Flautista Místico" só pode ser ativado uma vez por turno.','\r',char(13)),'\n',char(10)),'Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14212201,'Sombra Vampiro',replace(replace('Não pode ser usado como matéria para uma Invocação-Xyz, exceto a Invocação-Xyz de um monstro de TREVAS. \r\nQuando este card for Invocado por Invocação-Normal: você pode Invocar por Invocação-Especial 1 monstro "Vampiro(a)" de TREVAS da sua mão ou do Deck, exceto "Sombra Vampiro", mas os monstros que você controla não podem atacar pelo resto deste turno, exceto esse monstro Invocado por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14214060,'Trance, o Espadachim Mágico','Uma mago peculiar com habilidades consideráveis. Supostamente, ele acabou de retornar de uma viagem para o espaço sideral.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14220547,'Marcado na Dogmatika Central',replace(replace('Se você Invocar por Invocação-Especial 1 Monstro de Ritual (e nenhum outro card) usando um Card de Magia ou seus efeitos (exceto durante a Etapa de Dano): você pode olhar o Deck Adicional de qualquer duelista e enviar 1 monstro de lá para o Cemitério. \r\nSe você Invocar por Invocação-Especial 1 Monstro de Fusão (e nenhum outro card) usando um Card de Magia ou seus efeitos (exceto durante a Etapa de Dano): você pode escolher esse monstro; pelo resto deste turno, ele ganha ATK igual ao seu ATK original e, além disso, ele só pode atacar monstros em Posição de Ataque que seu oponente controla. \r\nVocê só pode usar cada efeito de "Marcado na Dogmatika Central" uma vez por turno.','\r',char(13)),'\n',char(10)),'Enviar do Deck Adicional para o Cemitério','Ver o seu Deck Adicional','Ver o Deck Adicional do oponente','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14225239,'Marítimo, o HERÓI do Elemento',replace(replace('"Homem Bolha, o HERÓI do Elemento" + "Aviário, o HERÓI do Elemento"	\r\nDeve ser Invocado por Invocação-Fusão. \r\nEnquanto você tiver cards Baixados na sua Zona de Magias & Armadilhas, este card pode atacar seu oponente diretamente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14235211,'Ginete dos Ventos Tempestuosos',replace(replace('Você pode escolher 1 Monstro Normal Dragão que você controla; equipe este monstro da sua mão ou do campo no alvo. \r\nSe um monstro equipado com este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente. \r\nSe um monstro equipado com este card seria destruído, em vez disso, destrua este card.','\r',char(13)),'\n',char(10)),'Equipar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14255590,'Ascensão da Malícia',replace(replace('Uma vez por turno, durante a Fase de Apoio do oponente: Envie 1 card do topo do Deck dele ao Cemitério para cada "Ascensão da Malícia" no seu Cemitério. \r\nEste card deve estar com a face para cima no campo para ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Enviar do Deck para o Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14258627,'Placa Gaia, Gigante da Terra',replace(replace('Você pode Invocar este card por Invocação-Especial ao remover de jogo 2 monstros do Tipo Rocha do seu Cemitério. \r\nDurante sua Fase de Apoio, remova de jogo 1 monstro do Tipo Rocha do seu Cemitério ou envie este card para o Cemitério. \r\nReduza pela metade o ATK e DEF de qualquer monstro que batalhar com este card.','\r',char(13)),'\n',char(10)),'Banir 1 monstro Rocha do Cemitério?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14261867,'Escorpião de Oito Garras',replace(replace('Uma vez por turno, você pode virar este card com a face para baixo em Posição de Defesa. \r\nQuando este card atacar um monstro do oponente com a face para baixo em Posição de Defesa, o ATK deste card se torna 2400 apenas durante o cálculo de dano.','\r',char(13)),'\n',char(10)),'Mudar para Posição de Defesa com a face para baixo','Alterar ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14283055,'Concours de Cuisine (Confronto Culinário)',replace(replace('Selecione 1 Monstro Pêndulo "Nouvelles" e 1 Monstro Pêndulo "Patissciel" da sua mão, do Deck e/ou do Deck Adicional e Invoque os dois monstros por Invocação-Especial, 1 em cada campo e, além disso, neste turno, você não pode usar monstros como matéria para uma Invocação-Fusão, Sincro, Xyz ou Link, exceto monstros "Nouvelles" e "Patissciel". \r\nDurante sua Fase Principal: você pode banir este card do seu Cemitério e, depois, escolha 1 monstro com a face para cima no campo; ele ganha 200 de ATK para cada card "Receita" nos Cemitérios. \r\nVocê só pode usar cada efeito de "Concours de Cuisine (Confronto Culinário)" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Escolha o monstro a Invocar por Invocação Especial para o seu campo','Escolha o monstro a Invocar por Invocação Especial para o campo do oponente','','','','','','','','','','','','');
INSERT INTO texts VALUES(14289852,'Zona de Catapulta','Uma vez por turno, se um monstro que você controla seria destruído em batalha, em vez disso, você pode enviar 1 monstro do Tipo Rocha do seu Deck ao Cemitério.','Usar o efeito de "Zona de Catapulta" em vez de ser destruído?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14291024,'Opção de Gradius',replace(replace('Este card não pode ser Invocado, por Invocação-Normal, ou Baixado. \r\nEste card só pode ser Invocado por Invocação-Especial escolhendo 1 "Gradius" no seu Campo. \r\nO ATK e DEF deste monstro tornam-se igual ao ATK e DEF do "Gradius" escolhido. \r\nSe o "Gradius" escolhido é removido do Campo, destrua este card.','\r',char(13)),'\n',char(10)),'Escolha 1 "Gradius"','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14301396,'Campeão Heroico - Excalibur Magnum',replace(replace('2 monstros Guerreiro de Nível 4	\r\nSe este card batalhar um monstro do oponente, durante o cálculo de dano: você pode desassociar 2 matérias deste card; dobre o ATK deste card apenas durante o cálculo de dano. \r\nUma vez por turno, durante a Fase Principal (Efeito Rápido): você pode escolher 1 outro monstro com a face para cima que você controla; equipe este card que você controla a ele como uma Magia de Equipamento que concede a ele 2000 de ATK/DEF. \r\nVocê pode banir este card do seu Cemitério; embaralhe no Deck 3 monstros Guerreiro do seu Cemitério.','\r',char(13)),'\n',char(10)),'Dobre o ATK dele','Considerar como Card de Equipamento','Retornar ao Deck','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14306092,'César Tubarão',replace(replace('3 ou mais (máx. 5) monstros de Nível 3	\r\nUma vez por turno: você pode desassociar 1 Matéria Xyz deste card; coloque 1 Marcador de Tubarão sobre este card. \r\nSe este card atacar ou for atacado, ele ganha 1000 de ATK para cada Marcador de Tubarão sobre ele, apenas durante a Etapa de Dano.','\r',char(13)),'\n',char(10)),'Colocar um marcador','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14307929,'Diabell, a Rainha da Floresta Branca',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro usando um Monstro Sincro Regulador: você pode escolher 1 Magia/Armadilha no seu Cemitério; adicione-a à sua mão. \r\nQuando seu oponente ativar um card ou efeito (Efeito Rápido): você pode enviar 1 Magia/Armadilha da sua mão ou do campo para o Cemitério; Invoque por Invocação-Especial 1 Monstro Sincro Regulador de Nível 7 ou menos do seu Deck Adicional, Cemitério ou banimento. \r\nVocê só pode usar cada efeito de "Diabell, a Rainha da Floresta Branca" uma vez por turno.','\r',char(13)),'\n',char(10)),'Recuperar uma Magia/Armadilha do Cemitério','Invoque por Invocação Especial um Regulador Sincro','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14309486,'Sobrecarga Koa''ki Meiru',replace(replace('Durante cada uma das suas Fases Finais, destrua este card a não ser que você envie 1 "Núcleo de Ferro de Koa''ki Meiru" da sua mão para o Cemitério ou revele 1 monstro Rocha da sua mão. \r\nQuando seu oponente Invocaria um ou mais monstros (Efeito Rápido): você pode oferecer este card como Tributo; negue a Invocação e, se isso acontecer, destrua esse(s) monstro(s).','\r',char(13)),'\n',char(10)),'Escolha 1 "Núcleo de Ferro de Koa''ki Meiru" para enviar para o Cemitério','Revelar ao oponente 1 monstro Rocha','Destruir "Sobrecarga Koa''ki Meiru"','Negar a Invocação e destruir','Negar a Invocação-Virar e destruir','Negar a Invocação Especial e destruir','','','','','','','','','','');
INSERT INTO texts VALUES(14315573,'Negativação de Ataque','Quando um monstro do oponente declarar um ataque: escolha o monstro atacante; negue o ataque e, depois, encerre a Fase de Batalha.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14318794,'Máquina de Absorção Vital','Durante a sua Fase de Apoio, ganhe PV igual à metade do total dos PV que você pagou durante seu último turno.','Ganhar PV','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14342283,'Estouro de Fichas','Todos as Fichas em Posição de Ataque ganham 1000 de ATK e, além disso, elas não podem ser destruídas em batalha.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14344682,'Barão da Espada Samurai',replace(replace('Uma vez por turno, você pode selecionar 1 monstro em Posição de Defesa que seu oponente controla. \r\nMude-o para Posição de Ataque com a face para cima.','\r',char(13)),'\n',char(10)),'Mudar a posição de batalha','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14357527,'Netuno Poderoso Bezoudado Pesado',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro deve ser Invocado por Invocação-Especial (da sua mão) ao embaralhar 3 dos seus monstros Inseto banidos no Deck Principal. \r\nDurante a Fase Principal, se este card sob o controle do seu dono for destruído ou banido por um efeito de card do oponente: você pode Invocar este card por Invocação-Especial. \r\nVocê só pode usar este efeito de "Netuno Poderoso Bezoudado Pesado" uma vez por turno. \r\nUma vez por turno, durante a Fase Final: você pode escolher 1 outro monstro Inseto que você controla; ele ganha 1000 de ATK.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14365823,'Trapestrela Divaridis',replace(replace('2 monstros "Trapestrela" de Nível 3 ou menos	\r\nVocê só pode controlar 1 "Trapestrela Divaridis". \r\nSe este card for Invocado por Invocação-Especial: você pode causar 200 de dano ao seu oponente. \r\nSe seu oponente Invocar um ou mais monstros por Invocação-Normal ou Especial: cause 200 de dano ao seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14386013,'Maestria do Espírito Negro',replace(replace('Descarte 1 card; adicione 1 "Tábua do Destino" ou 1 monstro Demônio de Nível 8 do seu Deck ou Cemitério à sua mão. \r\nVocê pode banir este card do seu Cemitério, exceto no turno em que este card foi enviado para o Cemitério; coloque qualquer número de cards "Tábua do Destino" e/ou "Mensagem do Espírito" com nomes diferentes da sua mão ou do Cemitério, no fundo do Deck em qualquer ordem e, depois, compre o mesmo número de cards. \r\nVocê só pode usar cada efeito de "Maestria do Espírito Negro" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Reciclar e comprar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14391625,'Visas Samsara',replace(replace('O nome deste card se torna "Visas Starfrost" enquanto estiver no campo ou no Cemitério. \r\nVocê pode escolher qualquer número dos seus monstros "Visas" que estiverem banidos, no seu Cemitério e/ou no seu campo; embaralhe esses monstros "Visas" no Deck e, se isso acontecer, Invoque este card por Invocação-Especial da sua mão e, se isso acontecer, ele ganha 400 de ATK para cada monstro que você embaralhou com um nome original diferente. \r\nVocê só pode usar este efeito de "Visas Samsara" uma vez por turno. \r\nSe este card que você controla seria usado como Matéria Sincro, você pode considerá-lo como um não-Regulador.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14391626,'Visas Samsara',replace(replace('O nome deste card se torna "Visas Starfrost" enquanto estiver no campo ou no Cemitério. \r\nVocê pode escolher qualquer número dos seus monstros "Visas" que estiverem banidos, no seu Cemitério e/ou no seu campo; embaralhe esses monstros "Visas" no Deck e, se isso acontecer, Invoque este card por Invocação-Especial da sua mão e, se isso acontecer, ele ganha 400 de ATK para cada monstro que você embaralhou com um nome original diferente. \r\nVocê só pode usar este efeito de "Visas Samsara" uma vez por turno. \r\nSe este card que você controla seria usado como Matéria Sincro, você pode considerá-lo como um não-Regulador.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14391920,'Temporal do Inferno',replace(replace('Quando você sofrer 3000 de Dano de Batalha ou mais em 1 ataque, você pode ativar este card. \r\nRemova de jogo todos os monstros do Deck e do Cemitério de cada duelista.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14393464,'Indução Mechamática',replace(replace('Todos os monstros Ciberso que você controla ganham 500 de ATK. \r\nSe você controlar um monstro "Mechamático(a)": você pode enviar este card com a face para cima do campo para o Cemitério e, depois, escolha 1 card que seu oponente controla; destrua-o. \r\nVocê só pode usar este efeito de "Indução Mechamática" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14418464,'Barão Destruidor Vaylantz',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nDurante sua Fase Principal: você pode Invocar este card por Invocação-Especial na sua Zona de Monstros Principal em sua mesma coluna e, além disso, você não pode Invocar por Invocação-Especial monstros que não sejam "Vaylantz" pelo resto deste turno, exceto do Deck Adicional. \r\nVocê só pode usar este efeito de "Barão Destruidor Vaylantz" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe você controlar este card Invocado por Invocação-Especial: você pode escolher 1 outro monstro "Vaylantz" na sua Zona de Monstros Principal; mova esse monstro que você controla para uma Zona de Monstros adjacente (horizontal). \r\nSe este card na Zona de Monstros se mover para outra Zona de Monstros: você pode escolher 1 card na Zona de Pêndulo de qualquer duelista; coloque-o com a face para cima em sua Zona de Magias & Armadilhas adjacente como uma Magia Contínua. \r\nVocê só pode usar cada efeito de "Barão Destruidor Vaylantz" uma vez por turno.','\r',char(13)),'\n',char(10)),'Escolha o monstro a mover','Escolha o card a mover','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14425515,'Pistoleiro Inférnico da Perdição',replace(replace('Durante sua Fase Principal: você pode Invocar 1 monstro Demônio da sua mão por Invocação-Especial.\r\nSe você não tiver cards na sua mão (Efeito Rápido): você pode banir este card do seu Cemitério; seu oponente escolhe 1 dos seguintes efeitos para você ativar.\r\n● Revele o card do topo do seu Deck, e se for um monstro, seu oponente recebe qualquer efeito de dano que você receberia neste turno.	\r\nDo contrário, você recebe 4000 de dano.\r\n● Você não recebe dano de efeito neste turno.	\r\nVocê só pode usar cada um dos efeitos de "Pistoleiro Inférnico da Perdição" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Ativar','Revelar o Deck','Não sofre dano de efeito','','','','','','','','','','','','');
INSERT INTO texts VALUES(14430063,'Interceptador Arquidemônio','Enquanto você controlar este card com a face para cima em Posição de Ataque, quando um monstro do oponente declarar um ataque, cause 500 de dano ao seu oponente.','Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14442329,'JJ "Kewl Tune"',replace(replace('Você pode Invocar 1 Regulador por Invocação-Normal durante sua Fase Principal a cada turno, em adição à sua Invocação-Normal/Baixar (padrão) (você só pode se aproveitar deste efeito uma vez por turno). \r\nCada "Kewl Tune Guerra de Volume" que você controla ganha 3300 de ATK enquanto seu oponente tiver um Regulador no campo ou Cemitério dele. \r\nVocê pode oferecer 1 Regulador como Tributo; adicione à sua mão ou Invoque por Invocação-Especial, 1 monstro "Kewl Tune" do seu Deck e, além disso, você não pode Invocar por Invocação-Especial pelo resto deste turno, exceto Reguladores. \r\nVocê só pode usar este efeito de "JJ "Kewl Tune"" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar pelo efeito de "JJ "Kewl Tune""','Efeito de busca','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14457896,'Parasita Paranoico',replace(replace('(Efeito Rápido): você pode escolher 1 monstro com a face para cima no campo; equipe este card da sua mão ao alvo. \r\nO monstro equipado se torna um monstro Inseto, ele não pode atacar monstros Inseto e, além disso, seus efeitos que ativarem ao escolher um ou mais monstros Inseto como alvo são negados. \r\nVocê só pode usar este efeito de "Parasita Paranoico" uma vez por turno. \r\nSe este Card de Equipamento for enviado para o Cemitério: você pode Invocar por Invocação-Especial 1 monstro Inseto de Nível 7 ou mais da sua mão, ignorando suas condições de Invocação.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14462257,'Rainha do Gelo',replace(replace('Não pode ser Invocado por Invocação-Especial do Cemitério. \r\nQuando este card com a face para cima que você controla for destruído e enviado para o seu Cemitério: Você pode escolher 1 Magia no seu Cemitério; adicione o alvo à sua mão. \r\nVocê deve ter 3 ou mais monstros do Tipo Mago no seu Cemitério para ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Adicione 1 Magia do seu Cemitério à sua mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14463695,'Predapodar',replace(replace('Ative este card ao escolher 1 monstro "Predaplanta" no seu Cemitério; Invoque-o por Invocação-Especial e equipe-o com este card. \r\nQuando este card deixar o campo, destrua esse monstro.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14464864,'Gleipnir, as Penas de Fenrir','Adicione 1 monstro "Nórdic" do seu Deck à sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14466224,'A Atmosfera',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro você deve Invocá-lo por Invocação-Especial (da sua mão) ao banir 2 monstros que você controla e 1 monstro no seu Cemitério. \r\nUma vez por turno: você pode escolher 1 monstro com a face para cima que seu oponente controla; equipe o alvo a este card. \r\n(Você só pode equipar 1 monstro de cada vez a este card com este efeito.) \r\nEste card ganha ATK e DEF igual ao ATK e DEF do monstro equipado.','\r',char(13)),'\n',char(10)),'Equipar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14469229,'Defensor Cristalino',replace(replace('Escala de Pêndulo = 2\r\n[ Efeito de Pêndulo ]\r\nA cada turno, na primeira vez que um ou mais monstros "Cristalino(a) Definitivo(a)" e/ou um ou mais cards "Fera Cristalina" que você controla seriam destruídos por um efeito de card nesse turno, eles não são destruídos.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe um monstro "Fera Cristalina" que você controla batalhar um monstro do oponente, durante o cálculo de dano (Efeito Rápido): você pode oferecer este card como Tributo da sua mão ou do campo com a face para cima; o ATK/DEF do seu monstro que estiver batalhando se torna o dobro do seu ATK/DEF originais, apenas durante esse cálculo de dano, mas ele é destruído no final desta Etapa de Dano.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14470845,'Dupla Ojama',replace(replace('Invoque por Invocação-Especial 2 "Fichas de Ojama" (Besta/LUZ/Nível 2/ATK 0/DEF 1000) no campo do seu oponente em Posição de Defesa. \r\nEssas Fichas não podem ser oferecidas como Tributo para uma Invocação-Tributo e sempre que 1 for destruída, seu controlador sofre 300 de dano. \r\nDurante o turno de qualquer duelista, exceto no turno em que este card foi enviado para o Cemitério: você pode banir este card do seu Cemitério; Invoque por Invocação-Especial 2 monstros "Ojama" com nomes diferentes do seu Deck.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14470846,'Ficha de Ojama','Invocado por Especial com o efeito "Dupla Ojama". Esta Ficha não pode ser oferecida como Tributo para uma Invocação-Tributo. Quando destruída, o controlador sofre 300 de dano.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14470847,'Ficha de Ojama','Invocado por Especial com o efeito "Dupla Ojama". Esta Ficha não pode ser oferecida como Tributo para uma Invocação-Tributo. Quando destruída, o controlador sofre 300 de dano.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14472500,'Gokipon','Quando este card for destruído em batalha e enviado para o Cemitério: você pode adicionar 1 monstro Inseto com 1500 ou menos de ATK do seu Deck à sua mão.','Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14478717,'Prevenção Livromante',replace(replace('Se você controlar um monstro "Livromante": você pode escolher 1 monstro com a face para cima que seu oponente controla; neste turno, esse monstro com a face para cima não pode ser usado como matéria para uma Invocação-Fusão, Sincro, Xyz ou Link. \r\nVocê só pode usar este efeito de "Prevenção Livromante" uma vez por turno. \r\nUma vez por turno, durante a Fase Final, se você não controlar nenhum Monstro de Ritual "Livromante": envie este card para o Cemitério.','\r',char(13)),'\n',char(10)),'Não pode ser usado como matéria','O efeito de "Prevenção Livromante" está sendo aplicado.','Envie este card para o Cemitério','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14504454,'Alícia, a Dama da Lamentação',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode escolher 1 monstro "Dama da Lamentação" no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê só pode usar cada um dos seguintes efeitos de "Alícia, a Dama da Lamentação" uma vez por turno. \r\nVocê pode banir 1 Armadilha da sua mão ou do Cemitério; Invoque este card por Invocação-Especial da sua mão. \r\nSe este card for oferecido como Tributo, ou se este card em posse do seu dono for destruído por um card do oponente: você pode adicionar 1 monstro Demônio cujo ATK & DEF combinados seja igual a 2000 do seu Deck à sua mão, exceto "Alícia, a Dama da Lamentação".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14505685,'Conversor Ciberso',replace(replace('Se todos os monstros que você controla forem monstros Ciberso (mín. 1), você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Conversor Ciberso" por Invocação-Especial uma vez por turno desta forma. \r\nQuando este card for Invocado por Invocação-Normal: você pode escolher 1 monstro com a face para cima que você controla; ele se torna um monstro Ciberso até o final deste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14506878,'Canhão Móvel DUCKER','VIRE: Escolha 1 monstro de Nível 4 no seu Cemitério; adicione o alvo à sua mão.','Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14507213,'Matéria Sincro',replace(replace('Escolha 1 monstro com a face para cima que seu oponente controla; você pode usar esse monstro como Matéria Sincro neste turno, como se você o controlasse. \r\nVocê não pode conduzir sua Fase de Batalha no turno em que ativar este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14509651,'Necrofear Amaldiçoado',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial por um efeito de card. \r\nVocê pode escolher 3 dos seus monstros Demônios banidos; Invoque este card por Invocação-Especial da sua mão e, se isso acontecer, embaralhe esses monstros banidos no Deck. \r\nDurante a Fase Final, se este card estiver no Cemitério porque foi destruído na sua Zona de Monstros por um card do oponente e enviado para lá neste turno: Invoque este card por Invocação-Especial do seu Cemitério e, depois, você pode destruir cards que seu oponente controla, até o número de Magias/Armadilhas com a face para cima que você controla com nomes diferentes. \r\nVocê só pode usar cada efeito de "Necrofear Amaldiçoado" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Destruir 1 card que seu oponente controla?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14512825,'Carruagem de Abóbora',replace(replace('"Prinzessinha" que você controla pode atacar diretamente. \r\nSeu oponente não pode escolher "Castelo Dourado de Stromberg" que você controla como alvo de efeitos de card e, além disso, ele não pode ser destruído por efeitos de card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14513016,'Domador da Besta Espiritual Ancião',replace(replace('Depois de Invocar este card por Invocação-Normal, você pode Invocar por Invocação-Normal 1 monstro "Besta Espiritual" durante sua Fase Principal neste turno, em adição à sua Invocação-Normal/Baixar (padrão). \r\n(Você só pode se aproveitar deste efeito uma vez por turno.) \r\nVocê só pode Invocar um ou mais "Domador da Besta Espiritual Ancião" por Invocação-Especial uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar pelo efeito de "Domador da Besta Espiritual Ancião"','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14513273,'Mago do Rei Supremo Portal',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\n"Rei Supremo Z-ARC" que você controla não pode ser banido pelos efeitos de card do seu oponente. \r\nDurante sua Fase Principal: você pode destruir este card e, se isso acontecer, coloque 1 Monstro Pêndulo "Rei Supremo Portal" da sua mão ou do Deck na sua Zona de Pêndulo, exceto "Mago do Rei Supremo Portal". \r\nVocê só pode usar este efeito de "Mago do Rei Supremo Portal" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe você tiver um card "Rei Supremo Portal" na sua Zona de Pêndulo, exceto "Mago do Rei Supremo Portal": você pode enviar para o Cemitério 1 monstro "Dragão Pêndulo", "Dragão Xyz", "Dragão Sincro" ou "Dragão Fusão" da sua mão ou do Deck Adicional e, se isso acontecer, Invoque este card por Invocação-Especial da sua mão. \r\nSe este card for Invocado por Invocação-Especial: você pode adicionar 1 card que mencione "Rei Supremo Z-ARC" do seu Deck à sua mão, exceto um monstro Mago. \r\nVocê só pode usar cada efeito de "Mago do Rei Supremo Portal" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invoque este card por Invocação Especial da sua mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14517422,'Contato do Senhor Obscuro',replace(replace('Invoque por Invocação-Especial 1 monstro "Senhor(a) Obscuro(a)" do seu Cemitério em Posição de Defesa. \r\nVocê só pode ativar 1 "Contato do Senhor Obscuro" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14529511,'Mementomictlan Tecuhtlica - Rei da Criação',replace(replace('3 monstros "Memento"	\r\nVocê pode banir este card do seu Cemitério; adicione 1 "Mementomictlan" do seu Deck à sua mão. \r\nVocê não pode ativar os seguintes efeitos de "Mementomictlan Tecuhtlica - Rei da Criação" na mesma Corrente. \r\nSe este card for Invocado por Invocação-Fusão: você pode enviar 3 cards "Memento" do seu Deck e/ou Deck Adicional para o Cemitério. \r\n(Efeito Rápido): você pode escolher um mesmo número de monstros "Memento" que você controla e cards que seu oponente controla; destrua-os. \r\nVocê só pode usar cada efeito de "Mementomictlan Tecuhtlica - Rei da Criação" uma vez por turno.','\r',char(13)),'\n',char(10)),'Enviar para o Cemitério','Destruir cards no campo','Procurar no Deck','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14531242,'Opticlope','Um gigante com um só olho que serve o "Governante Sombrio Ha Des". Ele empala os seus inimigos com um chifre afiado, partindo-os em pedaços.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14532163,'Tempestade de Relâmpagos',replace(replace('Se você não controlar nenhum card com a face para cima: ative 1 desses efeitos;\r\n● Destrua todos os monstros em Posição de Ataque que seu oponente controla.\r\n● Destrua todas as Magias e Armadilhas que seu oponente controla.	\r\nVocê só pode ativar 1 "Tempestade de Relâmpagos" por turno.','\r',char(13)),'\n',char(10)),'Destrua todos os monstros em Posição de Ataque que seu oponente controla','Destrua todos os Cards de Magia/Armadilha que seu oponente controla','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14532164,'Tempestade de Relâmpagos',replace(replace('Se você não controlar nenhum card com a face para cima: ative 1 desses efeitos;\r\n● Destrua todos os monstros em Posição de Ataque que seu oponente controla.\r\n● Destrua todas as Magias e Armadilhas que seu oponente controla.	\r\nVocê só pode ativar 1 "Tempestade de Relâmpagos" por turno.','\r',char(13)),'\n',char(10)),'Destrua todos os monstros em Posição de Ataque que seu oponente controla','Destrua todos os Cards de Magia/Armadilha que seu oponente controla','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14536035,'Grepher Negro',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) ao descartar 1 monstro de TREVAS de Nível 5 ou mais. \r\nUma vez por turno: você pode descartar 1 monstro de TREVAS; envie 1 monstro de TREVAS do seu Deck para o Cemitério.','\r',char(13)),'\n',char(10)),'Invocação Especial','Enviar para o Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14541657,'Ninja do Crepúsculo Shingetsu',replace(replace('Monstros que seu oponente controla não podem escolher monstros "Ninja" com a face para cima como alvo de ataques, exceto este. \r\nSeu oponente não pode escolher monstros "Ninja" com a face para cima como alvo de efeitos de card, exceto este. \r\nSe este card for destruído em batalha e enviado para o Cemitério, ou se este card em sua posse for destruído por um efeito de card do seu oponente e enviado para o seu Cemitério: você pode adicionar 1 monstro "Ninja" do seu Deck à sua mão, exceto "Ninja do Crepúsculo Shingetsu". \r\nVocê só pode usar este efeito de "Ninja do Crepúsculo Shingetsu" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14550855,'Inferno Inférnico','Descarte até 2 cards e envie o mesmo número de cards "Inférnico(a)" do seu Deck para o Cemitério.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14553285,'Mago Arcanita/Modo de Ataque',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial com "Ativar Modo de Ataque". \r\nSe este card for Invocado por Invocação-Especial: coloque 2 Marcadores de Magia sobre ele. \r\nGanha 1000 de ATK para cada Marcador de Magia sobre ele. \r\nVocê pode remover 2 Marcadores de Magia deste card; destrua todos os cards que seu oponente controla. \r\nQuando este card no campo for destruído: você pode escolher 1 "Mago Arcanita" no seu Cemitério; Invoque o alvo por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Colocar Marcadores de Magia','Destruir','Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14554127,'Paz Tiki',replace(replace('Invoque este card por Invocação-Especial como um Monstro de Efeito (Rocha/TERRA/Nível 4/ATK 1800/DEF 1800) com o seguinte efeito (este card ainda é considerado uma Armadilha).\r\n● (Efeito Rápido): você pode pagar 800 PV; Invoque por Invocação-Especial 1 Armadilha Contínua, exceto "Paz Tiki", do seu Cemitério ou banimento como um Monstro Normal (Rocha/TERRA/Nível 4/ATK 1000/DEF 1000) e seu nome se torna "Paz Tiki" (mesmo enquanto estiver com a face para baixo) (esse card NÃO é considerado como uma Armadilha).	\r\nVocê só pode usar este efeito de "Paz Tiki" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14556954,'Baleia VIP',replace(replace('Você pode oferecer como Tributo monstros adicionais quando Invocar este card por Invocação-Tributo com a face para cima. \r\nSe este card for Invocado por Invocação-Tributo: você pode colocar Marcadores VIP neste card igual ao número de monstros oferecidos como Tributo para sua Invocação-Tributo. \r\nQuando seu oponente ativar um card ou efeito (Efeito Rápido): você pode remover 1 Marcador VIP deste card; lance uma moeda e escolha cara ou coroa. \r\nSe você ganhar, negue o efeito. \r\nSe você perder, o ATK original deste card é diminuído pela metade até o final deste turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Tributo ao oferecer qualquer número de monstros como Tributo','Colocar um marcador','Jogar uma moeda','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14558127,'Florescer de Cinzas & Primavera Feliz',replace(replace('Quando um card ou efeito for ativado que inclua qualquer um desses efeitos (Efeito Rápido): você pode descartar este card; negue o efeito.\r\n● Adicionar um card do Deck à mão.\r\n● Invocar por Invocação-Especial do Deck.\r\n● Enviar um card do Deck para o Cemitério.	\r\nVocê só pode usar este efeito de "Florescer de Cinzas & Primavera Feliz" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14558128,'Florescer de Cinzas & Primavera Feliz',replace(replace('Quando um card ou efeito for ativado que inclua qualquer um desses efeitos (Efeito Rápido): você pode descartar este card; negue o efeito.\r\n● Adicionar um card do Deck à mão.\r\n● Invocar por Invocação-Especial do Deck.\r\n● Enviar um card do Deck para o Cemitério.	\r\nVocê só pode usar este efeito de "Florescer de Cinzas & Primavera Feliz" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14558129,'Florescer de Cinzas & Primavera Feliz',replace(replace('Quando um card ou efeito for ativado que inclua qualquer um desses efeitos (Efeito Rápido): você pode descartar este card; negue o efeito.\r\n● Adicionar um card do Deck à mão.\r\n● Invocar por Invocação-Especial do Deck.\r\n● Enviar um card do Deck para o Cemitério.	\r\nVocê só pode usar este efeito de "Florescer de Cinzas & Primavera Feliz" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14568951,'Ninja do Dragão Azul','Uma vez por turno (Efeito Rápido): você pode descartar 1 monstro "Ninja" e 1 card "Ninjitsu" e, depois, escolha 1 monstro com a face para cima que seu oponente controla; neste turno, ele não pode atacar e, além disso, seus efeitos são negados.','Negar o efeito','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14575467,'Zumbino',replace(replace('Os dois estão tão próximos\r\nEles morrem e voltam à vida\r\nInseparáveis','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14577226,'Ventobruxa - Sino do Inverno',replace(replace('1 Regulador + 1+ monstros de VENTO não-Reguladores	\r\nVocê pode escolher 1 monstro "Ventobruxa" no seu Cemitério; cause dano ao seu oponente igual ao Nível do alvo x 200. \r\nDurante a Fase de Batalha (Efeito Rápido): você pode escolher 1 monstro "Ventobruxa" que você controla; Invoque por Invocação-Especial 1 monstro da sua mão com um Nível menor ou igual que o desse monstro, mas ele não pode atacar neste turno. \r\nVocê só pode usar cada efeito de "Ventobruxa - Sino do Inverno" uma vez por turno.','\r',char(13)),'\n',char(10)),'Causar dano','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14602126,'Importação Xyz',replace(replace('Escolha 1 Monstro Xyz que você controla e 1 monstro que seu oponente controla com ATK igual ou menor que o dele; associe esse monstro do oponente ao seu monstro como matéria. \r\nVocê só pode ativar 1 "Importação Xyz" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14604710,'Monstruosidade do Legado Mundial',replace(replace('Ative 1 desses efeitos.\r\n● Invoque por Invocação-Especial 1 monstro de Nível 9 da sua mão.\r\n● Escolha 1 monstro de Nível 9 que você controla; Invoque por Invocação-Especial do seu Deck, 2 monstros de Nível 9 cada um com um Tipo e Atributo originais diferentes que o desse monstro com a face para cima escolhido como alvo, e com nomes diferentes um do outro, mas esses 2 monstros não podem atacar e, além disso, destrua-os durante a Fase Final.	\r\nVocê só pode ativar 1 "Monstruosidade do Legado Mundial" por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial da mão','Invocar por Invocação Especial do Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14613029,'Mistura Morfotrônica',replace(replace('Se você controlar 2 ou mais monstros "Morfotrônico(a)" com a face para cima, escolha 2 cards que seu oponente controla. \r\nDestrua 1 card da escolha do seu oponente dentre esses 2.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14618326,'Ninja Carmesim',replace(replace('VIRE: Escolha 1 Card de Armadilha no campo; destrua o alvo. \r\n(Se o alvo estiver Baixado, revele-o e destrua-o se for um Card de Armadiilha. Caso contrário, devolva-o à sua posição original.)','\r',char(13)),'\n',char(10)),'Destruir uma Armadilha','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14624296,'Samurai Superpesado Alma com Chifres',replace(replace('Você pode escolher 1 monstro "Samurai Superpesado" que você controla; equipe este monstro, da sua mão ou do seu lado do campo, no alvo. \r\nEle pode realizar um segundo ataque durante cada Fase de Batalha. \r\nEnquanto este card estiver equipado a um monstro pelo efeito deste card: você pode Invocar este card por Invocação-Especial. \r\nVocê só pode usar este efeito de "Samurai Superpesado Alma com Chifres" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14625090,'Bem-vindas Dragãozelas',replace(replace('Todos os monstros que você controla ganham 100 de ATK/DEF para cada monstro "Dragãozela" que você controla. \r\nSe você controlar 2 ou mais monstros "Dragãozela": você pode escolher 1 card "Dragãozela" no seu Cemitério, exceto "Bem-vindas Dragãozelas"; adicione-o à sua mão. \r\nVocê só pode usar este efeito de "Bem-vindas Dragãozelas" uma vez por turno. \r\nSe este card for enviado para o Cemitério: seu oponente não pode escolher monstros "Dragãozela" que você controla como alvo de efeitos de card neste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14644902,'Invocador de Ilusões','VIRE: Ofereça 1 outro monstro como Tributo e, se isso acontecer, Invoque por Invocação-Especial 1 Monstro de Fusão do seu Deck Adicional, mas destrua-o durante a Fase Final deste turno.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14677495,'Tanngnjostr das Bestas Nórdicas',replace(replace('Quando um monstro que você controla for destruído em batalha e enviado para o Cemitério: você pode Invocar este card por Invocação-Especial da sua mão. \r\nUma vez por turno, quando este card em Posição de Defesa no campo for colocado com a face para cima em Posição de Ataque: você pode Invocar por Invocação-Especial 1 monstro "Besta(s) Nórdica(s)" do seu Deck em Posição de Defesa, exceto "Tanngnjostr das Bestas Nórdicas".','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial da mão','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14702066,'Soldado Canhão, MK-2','Você pode oferecer como Tributo 2 monstros para causar 1500 de dano ao seu oponente.','Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14708569,'Arlownay','Um monstro delicado que mora em uma flor. Ela espalha pólen venenoso pelo ar.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14729426,'Invasor Interplanetário "A"','Ganhe o controle de um monstro que atacar este card com a face para cima em Posição de Ataque no final da Fase de Batalha.','Tome o controle','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14730606,'Grilhões de Hera',replace(replace('Todos os monstros com a face para cima que seu oponente controla se tornam monstros do Tipo Planta apenas durante o seu turno. \r\nSe este card que você controla com a face para cima for destruído e enviado para o seu Cemitério por um efeito de card do oponente: compre 1 card.','\r',char(13)),'\n',char(10)),'Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14731897,'Unidade',replace(replace('Selecione 1 monstro no seu lado do campo. \r\nA DEF do monstro selecionado se torna igual à DEF original combinada de todos os monstros com a face para cima no seu lado do campo até o fim deste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14732294,'Senhor dos Cavaleiros Brancos',replace(replace('You can only use this card name''s ① effect once per turn.\r\nVocê pode banir 3 monstros do seu Cemitério; Invoque por Invocação-Especial este card da sua mão, então você pode aplicar 1 desses efeitos.\r\n● Invoque por Invocação-Especial 1 monstro "Cavaleiro Branco" ou "Noite Branca" da sua mão ou Deck.\r\n● Adicione 1 "Véu Branco" do seu Deck à mão.	\r\nQuando um ataque é declarado envolvendo este card e um monstro do oponente: altere o ATK do monstro do oponente para 0.\r\nSe este card for destruído pelo seu opoente: cause 1000 de dano e ele.','\r',char(13)),'\n',char(10)),'Invocação Especial','ATK torna-se 0','Causar dano','Não resolver o efeito','Invocação Especial','Adicionar à mão','','','','','','','','','','');
INSERT INTO texts VALUES(14733538,'Confronto Draco',replace(replace('Revele 1 Monstro Pêndulo "Dracossassino" e 1 Monstro Pêndulo "Dracosuserano" do seu Deck, seu oponente elege 1 deles aleatoriamente para que você coloque na sua Zona de Pêndulo ou Invoque por Invocação-Especial (você seleciona) e você adiciona o outro card com a face para cima ao seu Deck Adicional. \r\nVocê só pode ativar 1 "Confronto Draco" por turno.','\r',char(13)),'\n',char(10)),'Colocar na Zona de Pêndulo?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14735698,'Espelho Necroz',replace(replace('Pode ser usado para Invocar por Invocação-Ritual qualquer Monstro de Ritual "Necroz". \r\nOfereça como Tributo monstros da sua mão ou do campo, e/ou bana monstros "Necroz" do seu Cemitério e, depois, Invoque por Invocação-Ritual 1 Monstro de Ritual "Necroz" da sua mão cujo Nível seja igual à soma dos Níveis desses monstros. \r\nVocê só pode usar este efeito de "Espelho Necroz" uma vez por turno. \r\nSe você não controlar nenhum monstro: você pode banir este card e 1 monstro "Necroz" do seu Cemitério; adicione 1 Magia "Necroz" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14745409,'Armas Nobres - Gallatin',replace(replace('Você só pode controlar 1 "Armas Nobres - Gallatin". \r\nSó pode ser equipado a um monstro do Tipo Guerreiro. \r\nEle ganha 1000 de ATK. \r\nDurante cada uma das suas Fases de Apoio, ele perde 200 de ATK. \r\nSe este card no campo com a face para cima for destruído e enviado para o Cemitério: você pode escolher 1 monstro "Nobre Cavaleiro" do Tipo Guerreiro que você controla; equipe este card ao alvo. \r\nVocê só pode usar este efeito de "Armas Nobres - Gallatin" uma vez por turno.','\r',char(13)),'\n',char(10)),'Equipar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14756848,'Samurai Superpesado Ladrão',replace(replace('Se você não tiver nenhum Card de Magia/Armadilha no seu Cemitério, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nDepois que este card foi Invocado por Invocação-Especial desta forma, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros "Samurai Superpesado". \r\nVocê pode oferecer este card como Tributo e, depois, ativar 1 desses efeitos;\r\n● Destrua 1 card na Zona de Magias & Armadilhas do seu oponente e, depois, você pode Baixar o Card de Magia/Armadilha destruído no seu lado do campo.\r\n● Destrua 1 card na Zona de Pêndulo do seu oponente e, depois, você pode colocar o card destruído na sua Zona de Pêndulo.','\r',char(13)),'\n',char(10)),'●','Destrua 1 card na Zona de Magia e Armadilha do seu oponente','Destrua 1 card na Zona de Pêndulo do seu oponente','Baixar no seu campo esse Card de Magia/Armadilha destruída?','Colocar na sua Zona de Pêndulo esse card destruída?','','','','','','','','','','','');
INSERT INTO texts VALUES(14759024,'Constelar Zubeneschamali','Quando este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 monstro "Constelar" do seu Deck para a sua mão.','Procurar no Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14761450,'Escudeiro Pinguim',replace(replace('Não pode ser usado como Matéria Sincro, exceto para a Invocação-Sincro de um monstro de ÁGUA. \r\nSe um monstro for Baixado no seu campo (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão e, depois, você pode reduzir o Nível dele em 1 ou 2. \r\nVocê pode escolher 1 monstro com a face para baixo em Posição de Defesa que você controla; coloque-o com a face para cima em Posição de Defesa e, se isso acontecer, seus efeitos são negados a não ser que seja um monstro "Pinguim". \r\nVocê só pode usar cada efeito de "Escudeiro Pinguim" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','Reduzir o Nível em 1','Reduzir em 2 Níveis','Não fazer nada','','','','','','','','','','','');
INSERT INTO texts VALUES(14763299,'Solista, a Cantora Melodiosa',replace(replace('Se seu oponente controlar um monstro e você não controlar nenhum monstro, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nQuando este card for destruído em batalha e enviado para o Cemitério: você pode Invocar por Invocação-Especial 1 monstro "Melodiosa" do seu Deck, exceto "Solista, a Cantora Melodiosa".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14771222,'Cavaleiro do Litoral','Uma vez por turno, se a posição de batalha deste card com a face para cima no campo for mudada: envie 1 monstro de ÁGUA do seu Deck para o Cemitério.','Enviar do Deck para o Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14772491,'Alma Comum',replace(replace('Selecione 1 monstro com a face para cima no campo para ativar este card. \r\nInvoque por Invocação-Especial 1 monstro "Neoespacial" da sua mão para o mesmo lado do campo do monstro selecionado. \r\nO monstro selecionado ganha ATK igual ao ATK do monstro Invocado por Invocação-Especial por este efeito. \r\nQuando este card for removido do campo, devolva à mão o monstro Invocado por Invocação-Especial pelo efeito deste card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14778250,'O Enganador','Você pode Invocar este card por Invocação-Especial (da sua mão) ao descartar 1 card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14785765,'Asanegra - Zéfiro, a Elite',replace(replace('Se este card estiver no seu Cemitério: você pode devolver 1 card com a face para cima que você controla para a mão; Invoque este card por Invocação-Especial e, se isso acontecer, sofra 400 de dano. \r\nVocê só pode usar este efeito de "Asanegra - Zéfiro, a Elite" uma vez por Duelo.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14799437,'Infernoide Onuncu',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão ou do Cemitério) ao banir 3 monstros "Infernoide" da sua mão ou do Cemitério enquanto a soma dos Níveis e Classes de todos os Monstros de Efeito que você controla for 8 ou menos. \r\nQuando este card for Invocado por Invocação-Especial: você pode destruir todos os outros monstros no campo. \r\nUma vez por turno, quando um Card de Magia/Armadilha ou seus efeitos forem ativados (Efeito Rápido): você pode oferecer 1 monstro como Tributo; negue a ativação e, se isso acontecer, bana esse card.','\r',char(13)),'\n',char(10)),'Destruir um monstro','Negue a ativação de um Card de Magia/Armadilha e bana-a','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14812471,'Salamagrande Lincegueira',replace(replace('1 monstro Ciberso de Nível 4 ou menos	\r\nSe este card for Invocado por Invocação-Link: você pode adicionar 1 "Salamagrande Santuário" do seu Deck à sua mão. \r\nSe um ou mais cards "Salamagrande" que você controla seriam destruídos em batalha ou por um efeito de card, em vez disso, você pode banir este card do seu Cemitério. \r\nVocê só pode usar cada efeito de "Salamagrande Lincegueira" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14812659,'Risebell, a Estrela Psíquica','Uma vez por turno, durante o turno de qualquer duelista: você pode escolher 1 monstro com a face para cima no campo; aumente seu Nível em 1.','Aumentar em 1 Nível','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14816688,'Renascimento Embaralhado',replace(replace('Se você não controlar nenhum monstro: escolha 1 monstro no seu Cemitério; Invoque-o por Invocação-Especial, mas ele tem seus efeitos negados e, além disso, bana-o durante a Fase Final. \r\nVocê pode banir este card do seu Cemitério e, depois, escolher 1 card que você controla; embaralhe-o no Deck e, depois, compre 1 card e, além disso, durante a Fase Final deste turno, bana 1 card da sua mão. \r\nVocê só pode usar este efeito de "Renascimento Embaralhado" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Retornar ao Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14816857,'Nervall da Tri-Brigada',replace(replace('Você pode banir qualquer número de monstros Besta, Besta-Guerreira e/ou Besta Alada no seu Cemitério; Invoque por Invocação-Especial 1 Monstro Link Besta, Besta-Guerreira ou Besta Alada do seu Deck Adicional, com um Valor Link igual ao número de banidos e, além disso, você só pode usar monstros Besta, Besta-Guerreira e Besta Alada como Matéria Link pelo resto deste turno. \r\nSe este card for enviado para o Cemitério: você pode adicionar 1 monstro "Tri-Brigada" do seu Deck à sua mão, exceto "Nervall da Tri-Brigada". \r\nVocê só pode usar cada efeito de "Nervall da Tri-Brigada" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14821890,'Apagão Espadalma',replace(replace('Escolha 1 monstro Wyrm que você controla e 2 cards que seu oponente controla; destrua-os. \r\nSe este card for banido: você pode Invocar por Invocação-Especial 1 "Ficha de Espadalma" (Wyrm/Regulador/ÁGUA/Nível 4/ATK 0/DEF 0). \r\nEnquanto essa Ficha estiver na Zona de Monstros, o duelista que a Invocou não pode Invocar monstros do Deck Adicional por Invocação-Especial, exceto Monstros Sincro. \r\nVocê só pode usar cada efeito de "Apagão Espadalma" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14821891,'Ficha de Espadalma','Invocado por Especial com o efeito de um card "Espadalma".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14824019,'Mago do Livro de Magia da Profecia','Se este card for Invocado por Invocação-Normal ou virado com a face para cima: adicione 1 Magia "Livro de Magia" do seu Deck à sua mão.','Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14839621,'Boompolim!!',replace(replace('Ative este card ao selecionar 1 Zona de Monstros não utilizada. \r\nSe um Monstro de Efeito for Invocado por Invocação-Especial nessa zona: devolva para a mão tanto esse monstro nessa zona quanto este card.','\r',char(13)),'\n',char(10)),'Retornar 2 cards à mão','Escolha uma Zona de Monstros Principal em qualquer campo','Escolha a Zona de Monstros Extra esquerda','Escolha a Zona de Monstros Extra direita','','','','','','','','','','','','');
INSERT INTO texts VALUES(14851496,'Alforreca','Uma medusa semi-transparente, quase invisível, que vagueia pelo mar.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14878871,'Gato de Socorro',replace(replace('Você pode enviar este card para o Cemitério; Invoque por Invocação-Especial 2 monstros Besta de Nível 3 ou menos do seu Deck, mas seus efeitos são negados e, além disso, eles são destruídos durante a Fase Final. \r\nVocê só pode usar este efeito de "Gato de Socorro" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14878872,'Gato de Socorro',replace(replace('Você pode enviar este card para o Cemitério; Invoque por Invocação-Especial 2 monstros Besta de Nível 3 ou menos do seu Deck, mas seus efeitos são negados e, além disso, eles são destruídos durante a Fase Final. \r\nVocê só pode usar este efeito de "Gato de Socorro" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14882493,'Gaia, o Cavaleiro Polar',replace(replace('Você só pode usar cada efeito de "Gaia, o Cavaleiro Polar" uma vez por turno.\r\n● Você pode oferecer 1 outro monstro de TREVAS como Tributo; adicione 1 monstro de LUZ do Tipo Guerreiro de Nível 4 do seu Deck à sua mão e, depois, envie 1 card da sua mão para o Cemitério.\r\n● Você pode banir 1 monstro de LUZ do seu Cemitério e, depois, escolher 1 monstro que você controla; ele ganha 500 de ATK até o final do turno do seu oponente.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Aumentar ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14883228,'Tufão',replace(replace('Escolha 1 Magia/Armadilha com a face para cima no campo; destrua-a. \r\nSe seu oponente controlar 2 ou mais Magias/Armadilhas e você não controlar nenhuma Magia/Armadilha, você pode ativar este card da sua mão.','\r',char(13)),'\n',char(10)),'Ativar aplicando o efeito de "Tufão".','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14886190,'Cidade do Mundo Virtual - Kauwloon',replace(replace('Coloque 1 card "Portão do Mundo Virtual" do seu Deck com a face para cima na sua Zona de Magias & Armadilhas e, depois, você pode aplicar quaisquer dos seguinte efeitos em sequência, de acordo com o número de cards "Portão do Mundo Virtual" que você controla.\r\n● 2+: Todos os monstros "Mundo Virtual" que você controla ganham 200 de ATK neste turno.\r\n● 3+: Envie os 3 cards do topo do seu Deck para o Cemitério.\r\n● 4: Invoque por Invocação-Especial até 4 monstros "Mundo Virtual" com nomes diferentes do seu Deck Adicional.	\r\nVocê só pode ativar 1 "Cidade do Mundo Virtual - Kauwloon" por turno.','\r',char(13)),'\n',char(10)),'Baixar do Deck','Aumentar o ATK daquele monstro?','Enviar 1 card do seu Deck para o Cemitério?','Invocar por Invocação Especial do Deck Adicional?','','','','','','','','','','','','');
INSERT INTO texts VALUES(14886469,'Corredor Vermelho',replace(replace('Quando este card for Invocado por Invocação-Normal ou Especial enquanto você não controlar nenhum outro monstro: você pode Invocar por Invocação-Especial 1 Regulador Demônio de Nível 3 ou menos da sua mão ou do Cemitério. \r\nVocê só pode usar este efeito de "Corredor Vermelho" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14898066,'Ginete Vorse','Esta perversa Besta-Guerreira faz todo tipo de coisas terríveis inimagináveis e adora fazê-las! O seu machado carrega as marcas das suas incontáveis vítimas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14898067,'Ginete Vorse','Esta perversa Besta-Guerreira faz todo tipo de coisas terríveis inimagináveis e adora fazê-las! O seu machado carrega as marcas das suas incontáveis vítimas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14920218,'Mago do Dragão Tolo',replace(replace('Escala de Pêndulo = 2\r\n[ Efeito de Pêndulo ]\r\nSe você tiver um card "Mago" na sua outra Zona de Pêndulo: você pode adicionar 1 Monstro Pêndulo "Mago" ou "Olhos Anômalos" com a face para cima do seu Deck Adicional à sua mão, exceto "Mago do Dragão Tolo". \r\nVocê só pode usar este efeito de "Mago do Dragão Tolo" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 Monstro Pêndulo "Mago" ou monstro "Olhos Anômalos" no seu Cemitério, exceto "Mago do Dragão Tolo"; adicione-o à sua mão. \r\nVocê só pode usar este efeito de "Mago do Dragão Tolo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14934922,'Fúria Salamagrande',replace(replace('Ative 1 desses efeitos;\r\n● Envie 1 monstro "Salamagrande" da sua mão ou do campo com a face para cima para o Cemitério e, depois, escolha 1 card no campo; destrua-o.\r\n● Escolha 1 Monstro Link "Salamagrande" que você controla que foi Invocado por Invocação-Link usando um monstro com seu mesmo nome como matéria; destrua cards que seu oponente controla, até o Valor Link desse monstro.	\r\nVocê só pode ativar 1 "Fúria Salamagrande" por turno.','\r',char(13)),'\n',char(10)),'Destruir 1 card','Destrua um número de cards igual ao número de Marcadores de Link','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14936691,'Lombriga Erokin',replace(replace('Este card não pode ser Invocado por Invocação-Especial. \r\nUma vez por turno, selecione 1 monstro "Lombriga" do Tipo Réptil com a face para cima no campo e coloque-o com a face para baixo em Posição de Defesa.','\r',char(13)),'\n',char(10)),'Mudar a posição de batalha','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14943837,'Dragão do Escombro',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode escolher 1 monstro com 500 ou menos de ATK no seu Cemitério; Invoque o alvo por Invocação-Especial em Posição de Ataque, mas negue seus efeitos. \r\nNão pode ser usado como Matéria Sincro, exceto para a Invocação-Sincro de um monstro Dragão. \r\nA(s) outra(s) \r\nMatéria(s) \r\nSincro não pode(m) ser de Nível 4.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14957440,'Otoshidamashi',replace(replace('Enquanto você controlar um monstro que não seja um Regulador, os monstros do seu oponente não podem escolher este card como alvo de ataques. \r\nSe um ou mais monstros forem enviados do campo para o Cemitério do seu oponente: coloque 1 Marcador de Otoshidamashi neste card e, depois, Invoque por Invocação-Especial "Ficha de Otoshidamashi" (Besta/TERRA/Nível 1/ATK ?/DEF ?) até o número de Marcadores de Otoshidamashi neste card. \r\nQuando Invocadas, o Nível de cada Ficha aumenta pelo número de Marcadores de Otoshidamashi neste card e, além disso, o ATK/DEF de cada Ficha são iguais ao seu Nível quando Invocada x 500. \r\nVocê só pode usar este efeito de "Otoshidamashi" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Invocar outro monstro por Invocação Especial?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14957441,'Ficha de Otoshidamashi','Invocado por Especial com o efeito "Otoshidamashi".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14959144,'Cavaleiro Brilhante Ursatron Definitivo Alfa',replace(replace('(Este card deve ser sempre considerado como um card "Ursártico(a)" e "Drytron".)	\r\nNão pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial por um efeito de card. \r\nSe você controlar um monstro "Ursártico(a)" ou "Drytron", exceto "Cavaleiro Brilhante Ursatron Definitivo Alfa": você pode Invocar este card por Invocação-Especial da sua mão e, depois, você pode adicionar 1 Magia/Armadilha "Ursártico(a)" ou "Drytron" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Cavaleiro Brilhante Ursatron Definitivo Alfa" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Adicionar à sua mão um Card de Magia/Armadilha do seu Deck?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14965712,'Multiplicação Kuriboh!',replace(replace('Quando um monstro do oponente declara ataque, ou seu oponente ativa um efeito de monstro (Efeito Rápido): você pode Invocar por Invocação-Especial este card da sua mão. \r\nVocê só pode usar este efeito de "Multiplicação Kuriboh!" uma vez por turno.\r\nUma vez por turno, se um monstro do oponente atacar, durante o calculo de dano, OU, quando seu oponente ativar um efeito de monstro no campo (Efeito Rápido): você pode adicionar à sua mão, ou Invocar por Invocação-Especial, 1 monstro "Mago Negro" ou 1 monstro com 300 ATK/200 DEF do seu Deck ou Cemitério, então você pode alterar o ATK do monstro do oponente para 0.','\r',char(13)),'\n',char(10)),'Invocação Especial','Efeito de busca','Alterar o ATK para 0?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14965713,'Multiplicação Kuriboh!',replace(replace('Quando um monstro do oponente declara ataque, ou seu oponente ativa um efeito de monstro (Efeito Rápido): você pode Invocar por Invocação-Especial este card da sua mão. \r\nVocê só pode usar este efeito de "Multiplicação Kuriboh!" uma vez por turno.\r\nUma vez por turno, se um monstro do oponente atacar, durante o calculo de dano, OU, quando seu oponente ativar um efeito de monstro no campo (Efeito Rápido): você pode adicionar à sua mão, ou Invocar por Invocação-Especial, 1 monstro "Mago Negro" ou 1 monstro com 300 ATK/200 DEF do seu Deck ou Cemitério, então você pode alterar o ATK do monstro do oponente para 0.','\r',char(13)),'\n',char(10)),'Invocação Especial','Efeito de busca','Alterar o ATK para 0?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14970113,'Martelokong Zoodíaco',replace(replace('3 ou mais monstros de Nível 4	\r\nUma vez por turno, você também pode Invocar por Invocação-Xyz "Martelokong Zoodíaco" ao usar 1 monstro "Zoodíaco(a)" que você controla com um nome diferente como Matéria Xyz. \r\n(Se você usou um Monstro Xyz, quaisquer Matérias Xyz associadas a ele também se tornam Matérias Xyz neste card.) \r\nEste card ganha ATK e DEF igual ao ATK e DEF de todos os monstros "Zoodíaco(a)" associados a ele como Matéria. \r\nEnquanto este card tiver Matérias Xyz, seu oponente não pode escolher monstros "Zoodíaco(a)" com a face para cima no campo como alvo de efeitos de card, exceto este. \r\nUma vez por turno, durante a Fase Final: desassocie 1 Matéria Xyz deste card.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Xyz sobrepondo um monstro "Zoodíaco(a)"?','Desassociar 1 matéria(s) deste card','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14972952,'Ereditare Vaalmônica',replace(replace('Quando um Card de Magia/Armadilha, ou efeito de monstro, for ativado enquanto você controlar um Monstro Link "Vaalmônica": negue a ativação e, se isso acontecer, destrua esse card. \r\nVocê pode banir este card do seu Cemitério; embaralhe no Deck cards "Vaalmônica" do seu Deck Adicional com a face para cima, Cemitério e/ou banimento, exceto "Ereditare Vaalmônica", até o número de Marcadores de Ressonância no seu campo e, depois, você pode comprar 1 card para cada 3 cards embaralhados. \r\nVocê só pode usar 1 efeito de "Ereditare Vaalmônica" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Negar a ativação e destruir','Recuperar','Comprar 1 card?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14977074,'Garoozis','Uma besta guerreiro com cabeça de dragão que brande um machado.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14983497,'Bebê Roca do Vale das Névoas','Quando este card for enviado da mão para o Cemitério: você pode Invocá-lo por Invocação-Especial.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14989021,'Simorgh, o Pássaro da Divindade',replace(replace('Este card não pode ser Invocado por Invocação-Especial. \r\nSe você Invocar este card por Invocação-Tributo, todos os Tributos devem ser de VENTO. \r\nCada duelista sofre 1000 de dano durante cada uma de suas Fases Finais, enquanto este card permanecer com a face para cima no campo. \r\nEste dano é reduzido em 500 para cada Card de Magia/Armadilha que o duelista controla.','\r',char(13)),'\n',char(10)),'Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15001619,'Rainha Marionete',replace(replace('Quando seu oponente adicionar um ou mais monstros do Deck Principal à mão dele, exceto ao comprá-los (e exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode Invocar por Invocação-Especial 1 monstro Guerreiro de TERRA de Nível 7 da sua mão ou do Cemitério e, se você Invocou "Rei Marionete" por Invocação-Especial por este efeito, todos os monstros Guerreiro de TERRA que você controla atualmente ganham 1000 de ATK até o final do próximo turno. \r\nVocê só pode usar este efeito de "Rainha Marionete" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15001940,'Foie Glasya de Nouvelles',replace(replace('Você pode Invocar este card por Invocação-Ritual com um card "Receita". \r\nSe este card for Invocado por Invocação-Especial: você pode escolher até 3 cards em quaisquer Cemitérios; embaralhe-os no Deck. \r\nQuando um card ou efeito for ativado que escolha um monstro no campo como alvo, ou quando um monstro for alvo de um ataque (Efeito Rápido): você pode oferecer como Tributo 1 monstro "Nouvelles" que você controla e 1 monstro em Posição de Ataque em qualquer campo e, se isso acontecer, Invoque por Invocação-Especial 1 Monstro de Ritual "Nouvelles" de Nível 5 ou 6 da sua mão ou do Deck. \r\nVocê só pode usar cada efeito de "Foie Glasya de Nouvelles" uma vez por turno.','\r',char(13)),'\n',char(10)),'Retornar cards do Cemitério para o Deck','Invocar por Invocação Especial da sua mão/Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15005145,'Centur-Ião Primera',replace(replace('Enquanto este card for uma Armadilha Contínua, monstros "Centur-Ião" de Nível 5 ou mais que você controla não podem ser destruídos por efeitos de card. \r\nVocê só pode usar cada um dos seguintes efeitos de "Centur-Ião Primera" uma vez por turno. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 card "Centur-Ião" do seu Deck à sua mão, exceto "Centur-Ião Primera" e, além disso, você não pode Invocar "Centur-Ião Primera" por Invocação-Especial pelo resto deste turno. \r\nDurante a Fase Principal, se este card for uma Armadilha Contínua: você pode Invocar este card por Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15013468,'Androesfinge',replace(replace('Você pode pagar 500 PV para Invocar este card por Invocação-Especial quando "Pirâmide de Luz" estiver no campo. \r\nEste card não pode atacar durante o turno em que foi Invocado por Invocação-Normal ou Invocação-Especial. \r\nEste card não pode ser Invocado por Invocação-Especial do Cemitério. \r\nSe este card destruir um monstro em Posição de Defesa como resultado de uma batalha, cause dano aos PV do oponente igual à metade do ATK do monstro destruído.','\r',char(13)),'\n',char(10)),'Causar dano aos PV','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15023985,'Ogre de Pedra da Gruta','Um gigante formado por rochas monstruosas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15025844,'Elfa Mística','Uma elfa delicada com pouco poder de ataque, mas com uma incrível defesa proveniente de poderes místicos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15028680,'HTS Psihemuth',replace(replace('1 Regulador + 1 ou mais monstros não-Reguladores	\r\nDepois do cálculo de dano, quando este card batalhar um monstro do oponente: você pode banir esse monstro e, além disso, banir este card.','\r',char(13)),'\n',char(10)),'Banir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15033525,'O Ardente Marte',replace(replace('Enquanto este card estiver na sua mão ou no Cemitério: você pode banir 3 outros monstros do seu Cemitério; Invoque este card por Invocação-Especial e, além disso, você não pode Invocar outros monstros por Invocação-Especial pelo resto deste turno. \r\nDurante sua Fase Principal 1: você pode enviar todos os outros monstros que você controla para o Cemitério; cause 500 de dano ao seu oponente para cada monstro enviado para o Cemitério. \r\nVocê só pode usar este efeito de "O Ardente Marte" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15042735,'Tornaço','Um tornado que arrasa as terras áridas com ventos cortantes.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15052462,'Cristal Violeta',replace(replace('Só pode ser equipado a um monstro Zumbi. \r\nEle ganha 300 de ATK/DEF.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15066114,'Dragão Segmentado',replace(replace('Você pode Invocar este card por Invocação-Normal/Baixar sem oferecer Tributo, mas seu ATK/DEF originais são diminuídos pela metade. \r\nUma vez por turno, se este card Invocado por Invocação-Normal/Baixado estiver no campo (Efeito Rápido): você pode destruir este card com a face para cima e, se isso acontecer, destrua todos os monstros nas Zonas de Monstros Principais com ATK menor ou igual ao ATK que este card tinha no campo.','\r',char(13)),'\n',char(10)),'Invocação Normal sem Tributo','Destruir um monstro','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15079028,'Alma do Mundo - Carbono',replace(replace('Você pode oferecer como Tributo este card Invocado por Invocação-Normal/Baixado; adicione 1 monstro Fada de TERRA do seu Deck à sua mão, exceto "Alma do Mundo - Carbono". \r\nSe um ou mais monstros Fada com a face para cima que você controla forem enviados para o Cemitério, enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode colocar este card no topo do seu Deck. \r\nVocê só pode usar 1 efeito de "Alma do Mundo - Carbono" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15083304,'Zona de Perigo!',replace(replace('Compre 3 cards e, depois, descarte 2 cards incluindo pelo menos 1 card "Perigo!", ou, se você não tiver cards "Perigo!" na sua mão, mostre toda a sua mão e embaralhe-a no Deck. \r\nVocê só pode ativar 1 "Zona de Perigo!" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15083728,'Casa da Fita Adesiva','Se a DEF de um monstro Invocado pelo seu oponente (exceto Invocação-Especial) for de 500 ou menos, o monstro é destruído.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15090429,'Prodígio do Remoinho de Vento','Este card pode ser considerado como 2 Tributos para a Invocação-Tributo de um monstro de VENTO.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15092394,'Ataqueraptor - Falcão Estranho',replace(replace('2 monstros de Nível 5	\r\nSe este card tiver um Monstro Xyz como Matéria Xyz, ele ganha este efeito.\r\n● Uma vez por turno: você pode desassociar 1 Matéria Xyz deste card e, depois, escolher 1 monstro que seu oponente controla; destrua-o e, se isso acontecer, cause dano ao seu oponente igual ao ATK original do monstro destruído do oponente.	\r\nSe este card em sua posse for destruído por um card do seu oponente (em batalha ou por um efeito de card) e enviado para o seu Cemitério: você pode escolher 1 Monstro Xyz "Ataqueraptor" no seu Cemitério, exceto "Ataqueraptor - Falcão Estranho"; Invoque-o por Invocação-Especial e, se isso acontecer, associe este card a ele como Matéria Xyz.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15094540,'Grande Crise Motoqueiro Goblin',replace(replace('Você pode escolher 1 monstro "Goblin" que você controla e 1 monstro que seu oponente controla, ou escolher 1 monstro "Goblin" no seu Cemitério e 1 monstro no Cemitério do seu oponente; bana os dois monstros. \r\nVocê pode enviar este card com a face para cima da Zona de Magias & Armadilhas para o Cemitério e, depois, escolha 5 dos seus monstros "Goblin" banidos com nomes diferentes; Invoque-os por Invocação-Especial. \r\nVocê só pode usar 1 efeito de "Grande Crise Motoqueiro Goblin" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Banir','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15103313,'Automumificação','Selecione 1 monstro que você controla e envie-o para o Cemitério.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15123983,'O Ham Estrela',replace(replace('1 Regulador + 1+ não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro: você pode descartar 1 card; Invoque por Invocação-Especial 1 monstro do seu Cemitério que foi usado como matéria para a Invocação-Sincro deste card e, se isso acontecer, ele é considerado como um Regulador. \r\nSe este card estiver no seu Cemitério: você pode descartar 2 cards; Invoque este card por Invocação-Especial, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar cada efeito de "O Ham Estrela" uma vez por turno.','\r',char(13)),'\n',char(10)),'Matérias de Invocação Especial','Invocar este card por Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15130912,'Saion, o Arqueiro Vaylantz',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nDurante sua Fase Principal: você pode Invocar este card por Invocação-Especial na sua Zona de Monstros Principal em sua mesma coluna e, além disso, você não pode Invocar por Invocação-Especial monstros que não sejam "Vaylantz" pelo resto deste turno, exceto do Deck Adicional. \r\nVocê só pode usar este efeito de "Saion, o Arqueiro Vaylantz" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe você controlar este card Invocado por Invocação-Especial: você pode escolher 1 Monstro de Efeito no campo; lance uma moeda e se o resultado for cara, negue seus efeitos, ou se o resultado for coroa, diminua seu ATK pela metade. \r\nSe este card na Zona de Monstros se mover para outra Zona de Monstros: você pode escolher 1 card no campo; lance uma moeda e se o resultado for cara, destrua-o, ou se o resultado for coroa, devolva-o para a mão. \r\nVocê só pode usar cada efeito de "Saion, o Arqueiro Vaylantz" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15141103,'Regulador Sombrio Catastrogue',replace(replace('Você pode revelar este card na sua mão; imediatamente após ativar este efeito, Invoque por Invocação-Normal 1 monstro "Regulador Sombrio". \r\nVocê só pode usar este efeito de "Regulador Sombrio Catastrogue" uma vez por turno.\r\nUma vez por turno, se você controla este card Invocado por Invocação-Normal/Baixado: você pode oferecer como Tributo este card com a face para cima e 1 não-Regulador com a face para cima com Nível menor, e se fizer, Invoque por Invocação-Especial 1 Monstro Sincro do seu Deck Adicional com Nível igual a diferença entre os Níveis daqueles monstros (isso é considerado uma Invocação-Sincro), então você pode destruir 1 card que seu oponente controla.','\r',char(13)),'\n',char(10)),'Invocação Normal','Invocação Sincro','Destruir o card?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15146890,'Mago do Pulso do Dragão',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno, se você tiver um card "Mago" na sua outra Zona de Pêndulo: você pode descartar 1 Monstro Pêndulo e, depois, escolher 1 monstro com a face para cima no campo; destrua-o.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nEste jovem mago tem o dom de ver as linhas naturais de energia que cruzam a terra, que seu povo chama de Pulso do Dragão. Sua exuberância e perícia lhe conferem muito prestígio com seu mentor, O "Mago do Fosso do Dragão".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15150365,'Chapéu Mágico Branco','Quando este card inflige dano de batalha ao seu adversário, o seu adversário descarta 1 card da sua mão aleatoriamente.','Descartar 1 card','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15150371,'Espelho Arquidemônio','Um espelho perverso que hipnotiza os inimigos, desviando seus ataques dos alvos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15155568,'Brilho da Espada da Destruição',replace(replace('Se você controlar um Monstro de Fusão que liste "Blader Notável" como Matéria: bana todos os monstros que seu oponente controla. \r\nQuando um card ou efeito for ativado que escolher como alvo um ou mais monstros "Blader Notável" que você controla (exceto durante a Etapa de Dano): você pode banir este card do seu Cemitério; negue esse efeito e, se isso acontecer, destrua esse card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15169262,'Sprite da Floresta Laval','Quando este card for enviado do campo para o Cemitério: Todos os monstros "Laval" com a face para cima que você controla atualmente ganham 200 de ATK para cada monstro "Laval" no seu Cemitério até a Fase Final.','Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15171722,'Evolssauro Lios',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode Baixar 1 "Ponte Evolucionária" ou "Evo-Singularidade" diretamente do seu Deck. \r\nDurante sua Fase Principal, se você controlar este card que foi Invocado por Invocação-Normal, ou Invocado por Invocação-Especial pelo efeito de um monstro de FOGO: você pode enviar para o Cemitério 1 monstro Réptil ou Dinossauro de FOGO do seu Deck e, depois, você pode fazer com que 2 monstros no campo se tornem do mesmo Tipo e Nível que esse monstro enviado para o Cemitério. \r\nVocê só pode usar cada efeito de "Evolssauro Lios" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Alterar o Tipo e o Nível de 2 monstros?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15173384,'Mago Ilusionista Sem Rosto',replace(replace('Se "Renunciado" ou um ou mais Monstros de Fusão "Restrição do" com a face para cima que você controla forem destruídos em batalha ou por um efeito de card: você pode Invocar este card por Invocação-Especial do Cemitério (se ele estava lá quando esse monstro foi destruído) ou da mão (mesmo se ele não estava). \r\nSe este card for enviado do campo para o Cemitério: você pode escolher 1 "Renunciado" ou Monstro de Fusão "Restrição do" no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Mago Ilusionista Sem Rosto" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15175429,'Reator de Magia・CÉU','Uma vez por turno, quando seu oponente ativar um Card de Magia, você pode destruir o Card de Magia e causar 800 de dano ao seu oponente.','Destrua e cause dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15177750,'Ventos Abençoados',replace(replace('Você pode ativar 1 dos seguintes efeitos;\r\n● Envie 1 monstro Planta da sua mão ou do campo com a face para cima para o Cemitério; ganhe 500 PV.\r\n● Escolha 1 monstro Planta no seu Cemitério; embaralhe-o no Deck e, depois, ganhe 500 PV.\r\n● Pague 1000 PV; Invoque por Invocação-Especial 1 monstro "Aromági" do seu Cemitério.	\r\nVocê só pode usar este efeito de "Ventos Abençoados" uma vez por turno.','\r',char(13)),'\n',char(10)),'Enviar para o Cemitério para ganhar PV','Retornar ao Deck para ganhar PV','Pagar PV para Invocar por Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15180041,'Espadachim Silencioso',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao oferecer como Tributo 1 monstro Guerreiro. \r\nUma vez por turno, durante a Fase de Apoio: este card ganha 500 de ATK. \r\nUma vez por turno, quando um Card de Magia for ativado (Efeito Rápido): você pode negar a ativação. \r\nSe este card for destruído em batalha, ou se este card sob o controle do seu dono for destruído por um efeito de card do oponente: você pode Invocar por Invocação-Especial 1 monstro "Espadachim Silencioso" da sua mão ou do Deck, exceto "Espadachim Silencioso", ignorando suas condições de Invocação.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15185344,'Swickelavee, o Brilhantemente Coroado da Cavalaria Pesada',replace(replace('2 monstros de Nível 3	\r\nUma vez por turno, você também pode Invocar por Invocação-Xyz "Swickelavee, o Brilhantemente Coroado da Cavalaria Pesada" usando 1 monstro Besta que você controla com 2000 ou menos ATK (transfira suas matérias). \r\nNão pode ser usado como matéria para uma Invocação-Xyz.\r\nSe este card destruir um monstro por batalha: Coloque 1 Marcador de Coroa nele, então aplique este efeito baseado no número de Marcadores de Coroa nele.\r\n● 1: Este card ganha 400 de ATK.\r\n● 2: Este card ganha 600 de ATK.\r\n● 3: Retorne este card para o Deck Adicional, e se fizer, compre 3 cards.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Xyz usando um monstro Besta como matéria?','Colocar um marcador','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15187079,'Imortal Terrestre Uru',replace(replace('Só pode haver 1 monstro "Imortal Terrestre" no campo. \r\nSe não houver Magias de Campo com a face para cima no campo, destrua este card. \r\nOs monstros do seu oponente não podem escolher este card como alvo de ataques. \r\nEste card pode atacar diretamente seu oponente. \r\nUma vez por turno: você pode oferecer como Tributo 1 outro monstro e, depois, escolha 1 monstro com a face para cima que seu oponente controla; até a Fase Final, tome o controle do alvo.','\r',char(13)),'\n',char(10)),'Tomar controle','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15198996,'Ninja Verde',replace(replace('Se um ou mais monstros forem Invocados por Invocação-Especial com a face para cima no seu campo (exceto durante a Etapa de Dano): você pode escolher 1 deles; Invoque este card por Invocação-Especial da sua mão e, se isso acontecer, coloque esse monstro com a face para baixo em Posição de Defesa. \r\nSe este card for enviado da mão ou do campo para o Cemitério: você pode escolher 1 monstro no campo; coloque-o com a face para cima em Posição de Ataque ou com a face para baixo em Posição de Defesa. \r\nVocê só pode usar cada efeito de "Ninja Verde" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15216188,'Motor do Tempo',replace(replace('(Este card deve ser sempre considerado como um card "Metalmorfe".)	\r\nSe um ou mais monstros que você controla forem destruídos em batalha ou por um efeito de card do oponente: escolha 1 desses monstros; Invoque-o por Invocação-Especial e, depois, se você Invocou por Invocação-Especial um monstro Máquina de Nível 5 ou mais por este efeito e tiver uma Armadilha "Metalmorfe" no seu campo ou Cemitério, exceto este card no campo, você pode aplicar este efeito.\r\n● Destrua tantos monstros que seu oponente controla quanto possível e, depois, você pode causar dano ao seu oponente, igual ao ATK original desse monstro Invocado por Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','Destruir aquele monstro?','Causar dano?','','','','','','','','','','','','');
INSERT INTO texts VALUES(15232745,'Número 1: Portão Numeron Ekam',replace(replace('3 monstros de Nível 1	\r\nNão pode ser destruído em batalha. \r\nNo final da Etapa de Dano, se este card batalhou um monstro do oponente: você pode desassociar 1 matéria deste card; até o final deste turno, dobre o ATK de todos os monstros "Numeron" que você controla atualmente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15237615,'Juíza Imperatriz','"Sósia da Rainha" + "Hibikime"','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15240238,'Pássaro da Névoa Clausolas',replace(replace('1 Regulador + 1 ou mais monstros não-Reguladores	\r\nUma vez por turno: você pode escolher 1 monstro com a face para cima que seu oponente controla; seu ATK se torna 0 e, se isso acontecer, seus efeitos são negados. \r\nEssas mudanças duram até o final do turno.','\r',char(13)),'\n',char(10)),'Negar o efeito','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15248594,'Geomechamático Magma',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nQuando este card destruir um monstro em batalha: você pode escolher até 2 cards que seu oponente controla; destrua-os. \r\nSe este card for destruído em batalha, ou se este card em posse do seu dono for destruído por um efeito de card do oponente: você pode adicionar 1 Magia/Armadilha "Mechamático(a)" do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "Geomechamático Magma" uma vez por turno.','\r',char(13)),'\n',char(10)),'Destruir 1 card','Procurar no Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15248873,'Pop-Up',replace(replace('Se seu oponente controlar um card na Zona de Campo dele e você não controlar nenhum: ative 1 Card de Magia de Campo do seu Deck. \r\nVocê só pode ativar 1 "Pop-Up" por turno.','\r',char(13)),'\n',char(10)),'Escolha uma Magia de Campo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15256925,'Rajada do Cetro do Caos',replace(replace('Se você controlar um monstro do Tipo Mago de Nível 8 ou mais: bana 1 card com a face para baixo no campo. \r\nSe este card na Zona de Magias & Armadilhas do seu dono for destruído por um efeito de card do oponente: você pode Invocar por Invocação-Especial 1 "Mago do Caos das Trevas" ou "Mago Negro do Caos" do seu Deck, ignorando suas condições de Invocação.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15259703,'Mundo Toon','Ative este card ao pagar 1000 PV.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15259704,'Mundo Toon','Ative este card ao pagar 1000 PV.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15270885,'Força de Ataque dos Goblin Toon',replace(replace('Não pode atacar no turno em que for Invocado. \r\nSe "Mundo Toon", no campo, for destruído, destrua este card. \r\nEnquanto você controlar "Mundo Toon" e seu oponente não controlar nenhum monstro Toon, este card pode atacar diretamente seu oponente. \r\nSe este card atacar, ele é colocado em Posição de Defesa no final da Fase de Batalha e sua posição de batalha não pode ser mudada até o final da Fase Final do seu próximo turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15286412,'Relíquia Nórdica Gungnir','Bana 1 monstro "Aesir" ou "Nórdic" que você controla e, depois, escolha 1 card no campo; destrua-o e, além disso, durante sua 2ª Fase Final depois da ativação, devolva para o campo, com a face para cima e em Posição de Ataque, o monstro que você baniu para ativar este card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15291624,'Colosso Dragão do Trovão',replace(replace('"Dragão do Trovão" + 1 monstro Trovão	\r\nDeve ser Invocado por Invocação-Fusão ou por Invocação-Especial durante o turno em que um efeito de um monstro Trovão foi ativado na mão, ao oferecer como Tributo 1 Monstro de Efeito Trovão que não seja de Fusão (e nesse caso, você não usa "Polimerização"). \r\nCards não podem ser adicionados do Deck Principal à mão do seu oponente exceto ao serem comprados. \r\nSe este card seria destruído em batalha ou por um efeito de card, em vez disso, você pode banir 1 monstro Trovão do seu Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15294090,'Miragem do Destino','Quando um monstro "HERÓI do Destino" que você controla for destruído e enviado ao Cemitério por um efeito de card do oponente: Invoque por Invocação-Especial no seu lado do campo todos os monstros "HERÓI do Destino" que foram destruídos e enviados para qualquer Cemitério neste turno.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15303296,'Ryu-Kishin','Uma criatura mestre nas ilusões. Parece uma estátua inofensiva até ao momento em que ataca.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15305240,'Captura da Criatura',replace(replace('Cada duelista concede ao seu oponente o controle de 1 dos seus monstros (o controlador seleciona). \r\nVocê deve selecionar um Monstro Normal com a face para cima.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15306543,'Alinhamento Estelar Sobre o Santuário',replace(replace('Uma vez por turno: você pode Invocar por Invocação-Ritual 1 Monstro de Ritual de VENTO do seu Deck, ao oferecer como Tributo monstros Espírito e/ou uma ou mais "Ficha de Shinobird" do seu campo, cuja soma dos Níveis seja igual ou exceda o Nível do Monstro de Ritual. \r\nDuas vezes por turno, se um ou mais monstros de VENTO com a face para cima que você controla forem devolvidos para a sua mão (exceto durante a Etapa de Dano): você pode ativar 1 desses efeitos;\r\n● Adicione à sua mão 1 dos seus monstros Espírito ou Magias de Ritual que estiverem banidos ou no seu Cemitério.\r\n● Baixe 1 "Alinhamento Estelar pela Via Láctea" diretamente do seu Deck.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15308295,'Ator do Abismo - Alívio Cômico',replace(replace('Escala de Pêndulo = 8\r\n[ Efeito de Pêndulo ]\r\nVocê pode escolher 1 Monstro Pêndulo "Ator do Abismo" que você controla e 1 monstro que seu oponente controla; troque o controle dos dois monstros e, depois, destrua este card. \r\nVocê só pode usar este efeito de "Ator do Abismo - Alívio Cômico" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nVocê não sofre dano de batalha dos ataques que envolvem este card. \r\nUma vez por turno, durante sua Fase de Apoio: conceda o controle deste card ao seu oponente. \r\nUma vez por turno, se o controle deste card com a face para cima mudar: ative este efeito; o dono deste card pode destruir 1 Magia "Script do Abismo" Baixada na sua própria Zona de Magias & Armadilhas.','\r',char(13)),'\n',char(10)),'','','','Destruir o Card de Magia "Script do Abismo"?','','','','','','','','','','','','');
INSERT INTO texts VALUES(15310033,'Sincron Desconhecido',replace(replace('Se somente seu oponente controlar um monstro, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Sincron Desconhecido" por Invocação-Especial uma vez por Duelo desta forma.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15313433,'Refletor Inférnico',replace(replace('Só pode ser ativado ao descartar todos os cards na sua mão quando um monstro "Inférnico(a)" que você controla for destruído em batalha e enviado ao Cemitério. \r\nSelecione e Invoque esse monstro por Invocação-Especial do seu Cemitério, e cause 1000 de dano ao seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15317640,'Núcleo Coberto B.E.S.',replace(replace('Se este card for Invocado por Invocação-Normal: coloque 2 marcadores nele. \r\nNão pode ser destruído em batalha. \r\nNo final da Etapa de Dano, se este card batalhou: se este card não tiver marcadores, destrua-o, caso contrário, lance uma moeda e escolha cara ou coroa e, se você perder, remova 1 marcador deste card.','\r',char(13)),'\n',char(10)),'Colocar um marcador','Jogar uma moeda','Destruir','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15327215,'Segredo Lendário dos Seis Samurai',replace(replace('Quando você Invocar um ou mais monstros "Seis Samurai Secretos" por Invocação-Normal ou Especial (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão. \r\nVocê só pode usar este efeito de "Segredo Lendário dos Seis Samurai" uma vez por turno. \r\nUma vez por turno: você pode banir 1 monstro "Seis Samurai" de Nível 4 ou menos do seu Cemitério; até o final deste turno, o Atributo, o Nível e o ATK/DEF deste card se tornam o mesmo que o desse monstro banido.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15335853,'Besta Fantasma Mecha Falcão de Cimitarra',replace(replace('Este card não pode atacar diretamente seu oponente. \r\nSe você tiver um monstro no seu Cemitério que não seja um monstro "Besta Fantasma Mecha", este card não pode atacar. \r\nO Nível deste card aumenta em um número igual à soma dos Níveis de todas as "Fichas de Besta Fantasma Mecha" que você controla. \r\nEnquanto você controlar uma Ficha, este card não pode ser destruído em batalha ou por efeitos de card. \r\nUma vez por turno: você pode oferecer 1 Ficha como Tributo e, depois, escolher 1 card no Cemitério de qualquer duelista; bana o alvo.','\r',char(13)),'\n',char(10)),'Banir 1 card','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15341821,'Dente-de-leão',replace(replace('Se este card for enviado para o Cemitério: Invoque por Invocação-Especial 2 "Ficha de Felpa" (Planta/VENTO/Nível 1/ATK 0/DEF 0) em Posição de Defesa. \r\nEssas Fichas não podem ser oferecidas como Tributo para uma Invocação-Tributo durante o turno em que forem Invocadas por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Invocar uma Ficha por Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15341822,'Ficha de Felpa',replace(replace('Invocado por Invocação-Especial com o efeito "Dente-de-leão". \r\nEsta Ficha não pode ser oferecida como Tributo em Invocação-Tributo no turno da sua Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15341823,'Ficha de Felpa',replace(replace('Invocado por Invocação-Especial com o efeito "Dente-de-leão". \r\nEsta Ficha não pode ser oferecida como Tributo em Invocação-Tributo no turno da sua Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15367030,'Gokibore','Uma barata grande e redonda que ataca os inimigos rolando por cima deles.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15381252,'Alma Enfurecida',replace(replace('Quando um monstro que você controla causar 1500 ou menos de dano ao seu oponente em um ataque direto: descarte toda a sua mão (mín. 1); escave o card do topo do seu Deck e, se for um Card de Monstro, envie-o para o Cemitério e, se isso acontecer, cause 500 de dano ao seu oponente e, depois, repita este efeito até 7 outras vezes ou até você escavar um Card que não seja de Monstro. \r\nSe um Card que não seja de Monstro for escavado, coloque-o no topo do seu Deck. \r\nVocê só pode ativar 1 "Alma Enfurecida" por turno.','\r',char(13)),'\n',char(10)),'Continuar a usar o efeito de "Alma Enfurecida"?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15381421,'Superestelar Seyfert',replace(replace('Você pode enviar qualquer número de monstros Dragão da sua mão e/ou do campo com a face para cima para o Cemitério; adicione 1 monstro Dragão do seu Deck à sua mão, cujo Nível seja igual à soma dos Níveis originais desses monstros enviados para o Cemitério. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 monstro Dragão de LUZ ou de TREVAS de Nível 8 no seu Cemitério; adicione-o à sua mão. \r\nVocê só pode usar cada efeito de "Superestelar Seyfert" uma vez por turno.','\r',char(13)),'\n',char(10)),'Escolha o Nível do monstro a ser adicionado à sua mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15383415,'Enxame de Escaravelhos',replace(replace('Uma vez por turno: você pode colocar este card com a face para baixo em Posição de Defesa. \r\nSe este card for Invocado por Invocação-Virar: escolha 1 monstro que seu oponente controla; destrua o alvo.','\r',char(13)),'\n',char(10)),'Mudar para Posição de Defesa com a face para baixo','Destrua 1 monstro que seu oponente controla','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15388353,'Restaurante Nouvelles "À Table"',replace(replace('Quando este card for ativado: você pode adicionar 1 card "Receita" do seu Deck ou Cemitério à sua mão. \r\nUma vez por turno: você pode colocar 1 Monstro de Ritual da sua mão no fundo do Deck; compre 1 card. \r\nUma vez por turno, durante sua Fase Final: você pode escolher 2 cards no seu Cemitério, incluindo um card "Receita"; coloque-os no fundo do seu Deck em qualquer ordem e, depois, compre 1 card. \r\nVocê só pode ativar 1 "Restaurante Nouvelles "À Table"" por turno.','\r',char(13)),'\n',char(10)),'Adicionar 1 card "Receita" à sua mão?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15394083,'Tanngrisnir das Bestas Nórdicas','Se este card for destruído em batalha e enviado para o Cemitério: Invoque por Invocação-Especial 2 "Fichas de Besta Nórdica" (Besta/TERRA/Nível 3/ATK 0/DEF 0).','Invocar uma Ficha por Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15394084,'Ficha de Besta Nórdica','Invocado por Especial com o efeito "Tanngrisnir das Bestas Nórdicas".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15397015,'Inspetor Prancha',replace(replace('Não pode ser Invocado por Invocação-Normal ou Especial se você controlar um monstro. \r\nNenhum duelista pode ativar efeitos de monstro a não ser que o número de efeitos de monstro que esse duelista tenha ativado previamente no turno em questão seja menor que o número de tipos de card de monstro atualmente no campo (Ritual, Fusão, Sincro, Xyz, Pêndulo e Link). \r\n(Se a ativação de um efeito foi negada, ela ainda conta para o número total do turno. Conte apenas os efeitos que foram ativados enquanto este monstro estava com a face para cima no campo.)','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15401633,'Kagemusha da Chama Azul','Servindo de substituto para o Senhor da Chama Azul, ele é um mestre espadachim que empunha uma bela espada.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15415552,'Mortilux Heruvur',replace(replace('2+ monstros de Nível 8	\r\nSe um ou mais monstros forem enviados para o Cemitério do seu oponente (exceto durante a Etapa de Dano): você pode escolher 1 deles; associe-o a este card. \r\nVocê só pode usar este efeito de "Mortilux Heruvur" uma vez por turno. \r\nEste card ganha efeitos de acordo com o número de matérias associadas a ele.\r\n● 2+: Não pode ser destruído em batalha ou por efeitos de card.\r\n● 3+: Seu oponente não pode escolher cards nos Cemitérios como alvo de efeitos de card.\r\n● 4+: Você pode desassociar 3 matérias deste card; envie 1 monstro no campo para o Cemitério.','\r',char(13)),'\n',char(10)),'Associar Matéria Xyz','Enviar para o Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15419596,'Pássaro Fantasma da Fascinação',replace(replace('Este card ganha um efeito de acordo com sua Zona de Monstros Principal em que estiver.\r\n● Mais à Esquerda: Ganha 1000 de ATK/DEF.\r\n● Mais à Direita: Pode realizar até 2 ataques contra monstros durante cada Fase de Batalha.\r\n● Centro: Seu oponente não pode escolher este card como alvo de efeitos de card e, além disso, ele não pode ser destruído pelos efeitos de card do seu oponente.\r\n● Outras: Monstros nesta coluna não podem ativar seus efeitos.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15443125,'Precursor Spright',replace(replace('Invoque por Invocação-Especial 1 monstro "Spright" do seu Deck, mas perca PV igual ao seu ATK original e, além disso, pelo resto deste turno depois que este card resolver, você não pode Invocar por Invocação-Especial, exceto monstros de Nível/Classe/Link 2. \r\nVocê só pode ativar 1 "Precursor Spright" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15447747,'Plano dos Travesso-Guris',replace(replace('Durante a Fase Principal: você pode ativar este efeito; imediatamente depois que este efeito resolver, Invoque por Invocação-Link 1 Monstro Link "Travesso-Guris" usando monstros "Travesso-Guris" que você controla como matéria. \r\nQuando um monstro do oponente declarar um ataque: você pode banir este card do seu Cemitério; embaralhe no Deck qualquer número de cards "Travesso-Guris" do seu Cemitério e, se isso acontecer, até o final deste turno, esse monstro atacante perde 100 de ATK para cada card embaralhado. \r\nVocê só pode usar cada efeito de "Plano dos Travesso-Guris" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15449853,'O Sacrário de Parshath',replace(replace('O nome deste card se torna "O Santuário no Céu" enquanto ele estiver no campo ou no Cemitério. \r\nMonstros Fada no campo ganham 300 de ATK/DEF. \r\nMagias/Armadilhas Baixadas não podem ser destruídas por efeitos de card e, além disso, nenhum duelista pode escolhê-las como alvo de efeitos de card. \r\nUma vez por turno: você pode escolher um total de 3 monstros Fada e/ou Armadilhas de Resposta com nomes diferentes no seu Cemitério; coloque-os no topo do seu Deck em qualquer ordem.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15452043,'Peixe-espada Camarartista',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: todos os monstros que seu oponente controla atualmente perdem 600 de ATK e DEF. \r\nSe você Invocar um ou mais monstros por Invocação-Especial enquanto controlar este card: todos os monstros que seu oponente controla atualmente perdem 600 de ATK e DEF.','\r',char(13)),'\n',char(10)),'Alterar ATK/DEF','Alterar ATK/DEF','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15458892,'Avião Espacial de Espionagem',replace(replace('Se seu oponente controlar um Monstro Xyz com a face para cima, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nQuando este card for Invocado por Invocação-Especial da mão: escolha 1 Card de Magia/Armadilha que seu oponente controla; devolva o alvo para a mão.','\r',char(13)),'\n',char(10)),'Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15462014,'Gigantes Vazios',replace(replace('Ative este card somente se os dois duelistas controlarem um monstro que foi Invocado por Invocação-Especial do Deck Adicional. \r\nNegue os efeitos dos monstros com a face para cima Invocados por Invocação-Especial do Deck Adicional. \r\nSe um ou mais monstros forem destruídos em uma batalha envolvendo 2 monstros que foram Invocados por Invocação-Especial do Deck Adicional: envie este card para o Cemitério e, além disso, o(s) duelista(s) que controlava(m) o(s) monstro(s) destruído(s) sofre(m) 1000 de dano.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15464375,'Adularia da Lua de Junho',replace(replace('Se você controlar um card com a face para cima na sua Zona de Magias & Armadilhas, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Adularia da Lua de Junho" por Invocação-Especial uma vez por turno desta forma. \r\nGanha 600 de ATK/DEF para cada Magia/Armadilha com a face para cima no campo. \r\nVocê pode enviar para o Cemitério 2 cards com a face para cima da sua Zona de Magias & Armadilhas; envie 1 monstro de Nível 4 ou menos do seu Deck para o Cemitério. \r\nVocê só pode usar este efeito de "Adularia da Lua de Junho" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15471265,'Esmagamento Furioso','Bana 1 monstro do seu Cemitério e, depois, escolha 1 "Kuriboh Alado" que você controla; até o final deste turno, o ATK/DEF do alvo se tornam iguais ao ATK/DEF do monstro banido.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15475415,'Cão Alienígena',replace(replace('Quando você Invocar por Invocação-Normal um monstro "Alienígena", você pode Invocar este card por Invocação-Especial da sua mão. \r\nAo fazê-lo, coloque 2 Marcadores-A nos monstros com a face para cima que seu oponente controla.','\r',char(13)),'\n',char(10)),'Invocação Especial','Colocar "Marcador-A"','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15480588,'Lagarto Encouraçado','Um lagarto com uma couraça muito resistente e uma mordida feroz.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15495787,'Samurai Superpesado de Defesa Preventiva',replace(replace('Não pode ser Invocado por Invocação-Normal ou Virar se você tiver algum Card de Magia/Armadilha no seu Cemitério. \r\nQuando você sofrer dano de batalha, se você não tiver nenhum Card de Magia/Armadilha no seu Cemitério e este card estiver na sua mão: você pode Invocar este card por Invocação-Especial e, se isso acontecer, ele não pode ser destruído em batalha ou por efeitos de card neste turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15502037,'Gama, o Guerreiro Ímã Temporal',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode Invocar por Invocação-Especial 1 monstro "Guerreiro Ímã" de Nível 4 ou menos da sua mão, exceto "Gama, o Guerreiro Ímã Temporal". \r\nVocê só pode usar este efeito de "Gama, o Guerreiro Ímã Temporal" uma vez por turno. \r\nDurante o turno do seu oponente (Efeito Rápido): você pode oferecer este card como Tributo; Invoque por Invocação-Especial 1 monstro "Guerreiro Ímã" de Nível 4 do seu Deck.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15507080,'Sectário dos Segredos','Este feiticeiro adora a escuridão e é servido por uma mão sinistra que arrasta os seus inimigos para o esquecimento.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15510988,'Criança do Trovão','Este monstro armazena eletricidade dentro do seu corpo e pode liberá-la de modo catastrófico.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15520842,'Mão de Fóton',replace(replace('Se você controlar um monstro "Fóton" ou "Galáxia": pague 1000 PV e, depois, escolha 1 monstro que seu oponente controla; tome o controle dele. \r\nSe você não controlar "Dragão de Fóton de Olhos das Galáxias" na ativação, você só pode escolher um Monstro Xyz. \r\nVocê só pode ativar 1 "Mão de Fóton" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15521027,'Smartfon Morfotrônico',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro você deve Invocá-lo por Invocação-Especial (da sua mão) ao banir 1 monstro "Morfotrônico(a)" do seu Cemitério.\r\n● Enquanto estiver em Posição de Ataque: Uma vez por turno: você pode lançar um dado de 6 faces, escavar esse número de cards do topo do seu Deck e adicionar 1 card "Morfotrônico(a)" escavado para a sua mão e, além disso, embaralhe o resto dos cards de volta no Deck.\r\n● Enquanto estiver em Posição de Defesa: Uma vez por turno: você pode lançar um dado de 6 faces, olhar esse número de cards do topo do seu Deck e, depois, colocá-los ou no topo ou no fundo do Deck, em qualquer ordem.','\r',char(13)),'\n',char(10)),'Invocação Especial','Revelar o Deck','Verificar a ordem do Deck','Colocar no topo do Deck','Colocar no fundo do Deck','','','','','','','','','','','');
INSERT INTO texts VALUES(15543940,'Fusão Dino Tirano',replace(replace('Invoque por Invocação-Fusão 1 monstro "Dinolutador" do seu Deck Adicional, usando monstros que você controla como Matéria de Fusão. \r\nSe isso acontecer, na primeira vez que esse monstro com a face para cima no campo seria destruído em batalha ou por um efeito de card, ele não é destruído.','\r',char(13)),'\n',char(10)),'','Invocar "Dinolutador" por Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15545291,'Granmarg, a Mega Monarca',replace(replace('Você pode Invocar este card por Invocação-Tributo ao oferecer 1 monstro Invocado por Invocação-Tributo. \r\nQuando este card for Invocado por Invocação-Tributo: escolha até 2 cards Baixados no campo; destrua os alvos. \r\nSe este card foi Invocado por Invocação Tributo pela oferenda de um monstro de TERRA, adicione este efeito adicional.\r\n● Além disso, depois compre 1 card.','\r',char(13)),'\n',char(10)),'Ofereça 1 monstro Invocado por Invocação Tributo como Tributo para uma Invocação Tributo','Destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15552258,'Metade ou Nada',replace(replace('Durante a Fase de Batalha do seu oponente (exceto durante a Etapa de Dano): seu oponente seleciona 1 desses efeitos.\r\n● Até o final da Fase de Batalha, diminua pela metade o ATK de todos os monstros que ele controla atualmente.\r\n● Encerre a Fase de Batalha.','\r',char(13)),'\n',char(10)),'O ATK se torna metade','Terminar a Fase de Batalha','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15555120,'Renivelamento de Alta-Velocidade','Bana 1 monstro "Velocidaroide" do seu Cemitério e, depois, escolha 1 Monstro Sincro que você controla; até o final deste turno, mude o Nível dele para o Nível do monstro banido e ele ganha ATK igual ao Nível desse monstro x 500.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15561463,'Lançador de Manoplas',replace(replace('2 monstros de Nível 6	\r\nVocê pode desassociar 1 Matéria Xyz deste card e, depois, escolher 1 monstro que seu oponente controla; destrua-o.','\r',char(13)),'\n',char(10)),'Destruir um monstro','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15574615,'D.D. Jato de Ferro',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro você deve Invocá-lo por Invocação-Especial (da sua mão) ao enviar 1 "D.D. Andorinha Estelar Esper", "Besta-Guerreira Puma", "Besta Fênix Gairuda" e "Martelo de Ferro, o Gigante" da sua mão e/ou com a face para cima no seu lado do campo para o Cemitério. \r\nVocê pode oferecer este card como Tributo para escolher 1 "D.D. Andorinha Estelar Esper", "Besta-Guerreira Puma", "Besta Fênix Gairuda" e "Martelo de Ferro, o Gigante" em seu Cemitério; Invoque os alvos por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15576074,'Motor do Ressonador','Escolha 2 monstros "Ressonador" no seu Cemitério; adicione 1 monstro de Nível 4 do seu Deck à sua mão e, se isso acontecer, devolva os alvos para o Deck.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15582767,'Oscilação do Eco',replace(replace('Você pode escolher 1 card na sua Zona de Pêndulo; destrua-o e, depois, compre 1 card. \r\nVocê só pode usar este efeito de "Oscilação do Eco" uma vez por turno.','\r',char(13)),'\n',char(10)),'Usar agora o efeito deste card?','Destrua 1 card na sua Zona de Pêndulo e depois compre 1 card do seu Deck.','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15590355,'Realização Livromante',replace(replace('Você pode revelar 1 Monstro de Ritual "Livromante" na sua mão: Invoque por Invocação-Especial 1 "Ficha de Fogo" (Ciberso/FOGO/ATK 0/DEF 0) com o mesmo Nível que o do monstro revelado. \r\nEnquanto você controlar essa Ficha, você não pode Invocar monstros por Invocação-Especial, exceto monstros "Livromante". \r\nVocê só pode usar este efeito de "Realização Livromante" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15590356,'Ficha de Fogo','Invocado por Especial com o efeito "Realização Livromante".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15595052,'Discípulo da Magia Proibida',replace(replace('Quando este card for Invocado, declare diferentes Atributos de Cards de Monstro iguais ao número de cards "Discípulo da Magia Proibida" no seu Cemitério. \r\nSe este card atacar um monstro com um Atributo declarado, destrua o monstro com este efeito de card sem aplicar o cálculo de dano.','\r',char(13)),'\n',char(10)),'Declarar um Atributo','Destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15605085,'Solar Genex',replace(replace('Você pode Invocar este card por Invocação-Normal ao oferecer como Tributo 1 monstro "Genex". \r\nCause 500 de dano ao seu oponente sempre que um monstro "Genex" com a face para cima que você controla for enviado ao Cemitério.','\r',char(13)),'\n',char(10)),'Invocação Tributo ao oferecer 1 monstro cujo nome inclui "Genex" como Tributo','Causar dano','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15609017,'Surpresa Eletrizante','Bana até 2 monstros "Velocidaroide" do seu Cemitério e, depois, escolha o mesmo número de cards no campo; destrua-os.','Banir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15610297,'Vijam, a Semente Cúbica',replace(replace('Não pode ser destruído em batalha. \r\nNo final da Etapa de Dano, se este card batalhar um monstro do oponente: você pode colocar este card com a face para cima na sua Zona de Magias & Armadilhas como um Card de Magia Contínua e, se isso acontecer, coloque 1 Marcador Cúbico nesse monstro do oponente. \r\n(Monstros com um Marcador Cúbico não podem atacar e, além disso, negue seus efeitos.) \r\nSe este card for considerado como um Card de Magia Contínua por este efeito, durante sua Fase Principal: você pode Invocar este card por Invocação-Especial da sua Zona de Magias & Armadilhas.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15613529,'Elfa Mística - Relâmpago Branco',replace(replace('Quando um monstro que seu oponente controla ativar seu efeito, enquanto você controlar um Monstro Normal de Nível 5 ou mais (Efeito Rápido): você pode Invocar este card por Invocação-Especial da sua mão e, se isso acontecer, negue o efeito. \r\nDurante a Fase de Batalha do seu oponente (Efeito Rápido): você pode escolher 1 Monstro Normal em qualquer Cemitério; Invoque-o por Invocação-Especial no seu campo e, se isso acontecer, todos os monstros que seu oponente controla devem atacar esse monstro neste turno, se possível, enquanto você o controlar. \r\nVocê só pode usar cada efeito de "Elfa Mística - Relâmpago Branco" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15627227,'Dragão Superexplosivo',replace(replace('2 monstros "Foguette"	\r\nVocê pode escolher 1 outro Monstro Link que você controla; Invoque por Invocação-Especial 1 monstro "Foguette" da sua mão em uma zona sua para a qual o alvo apontar, mas o monstro Invocado por este efeito não pode ser usado como Matéria Link e, além disso, destrua-o durante a Fase Final. \r\nVocê só pode usar este efeito de "Dragão Superexplosivo" uma vez por turno. \r\nQuando este card for destruído em batalha e enviado para o Cemitério: você pode escolher 1 monstro "Foguette" no seu Cemitério; adicione-o à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15629801,'Valsa de Batalha',replace(replace('Escolha 1 Monstro Sincro que você controla; Invoque por Invocação-Especial 1 "Ficha de Valsa" com o mesmo Tipo, Atributo, Nível, ATK e DEF atuais desse monstro. \r\nNenhum duelista sofre qualquer dano de batalha dos ataques envolvendo essa Ficha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15629802,'Ficha de Valsa','Invocado por Especial com o efeito "Valsa de Batalha". Nenhum duelista sofre qualquer dano de batalha de ataques que envolvem esta Ficha.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15635751,'Camelot, Reino dos Nobre Cavaleiros e Armas Nobres',replace(replace('Uma vez por turno, se um ou mais cards "Nobre Cavaleiro" que você controla seriam destruídos em batalha ou por um efeito de card, em vez disso, você pode destruir 1 Card de Equipamento que você controla. \r\nDurante sua Fase Principal: você pode banir este card (até a próxima Fase de Apoio) e, se isso acontecer, coloque 1 "Nobre Cavaleiros da Távola Redonda" da sua mão, do Deck ou do Cemitério, com a face para cima na sua Zona do Campo e, depois, você pode Invocar por Invocação-Especial 1 monstro "Artorigus", ou adicione à sua mão 1 card "Armas Nobres", do seu Deck ou Cemitério.\r\nVocê só pode usar este efeito de "Camelot, Reino dos Nobre Cavaleiros e Armas Nobres" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Invocar por Invocação Especial ou adicionar à sua mão?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15653824,'Cavaleiro Caveira nº 2',replace(replace('Se você Invocar por Invocação-Tributo um monstro do Tipo Demônio oferecendo este card como um Tributo, Invoque por Invocação-Especial 1 "Cavaleiro Caveira nº 2" do seu Deck. \r\nEm seguida, embaralhe o seu Deck.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15658249,'Lombriga Barses','Quando este card for Invocado por Invocação-Normal: Escolha 1 monstro em Posição de Defesa; coloque o alvo com a face para cima em Posição de Ataque.','Mudar a posição de batalha','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15661378,'Trishula, o Dragão do Aprisionamento Gélido',replace(replace('3 monstros com nomes diferentes	\r\nPrimeiro deve ser Invocado por Invocação-Fusão seja usando apenas monstros na sua mão e/ou no campo ou Invocando-o por Invocação-Especial (do seu Deck Adicional) ao banir os cards acima que você controla. \r\nSe este card foi Invocado por Invocação-Especial usando apenas monstros que eram originalmente monstros Dragão: você pode revelar e banir 3 cards (1 do seu Deck, 1 do topo do Deck do seu oponente e 1 do Deck Adicional dele). \r\nVocê só pode usar este efeito de "Trishula, o Dragão do Aprisionamento Gélido" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15665977,'Kewl Tune RS',replace(replace('"Kewl Tune Reco" + 1+ Reguladores	\r\nGanha 300 de ATK para cada Regulador nos Cemitérios. \r\nOs Níveis dos monstros que seu oponente controla com 1700 ou menos de ATK original aumentam em 1. \r\nDurante a Fase Principal (Efeito Rápido): você pode banir 1 Regulador do seu Cemitério e, depois, escolha 1 card com a face para cima que seu oponente controla; negue seus efeitos até o final deste turno. \r\nVocê só pode usar este efeito de "Kewl Tune RS" uma vez por turno.','\r',char(13)),'\n',char(10)),'Negar o efeito','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15667446,'Latinum, Exarca do Mundo Negro','Se este card for descartado para o Cemitério por um efeito de card: se ele foi descartado da sua mão para o seu Cemitério por um efeito de card do oponente, escolha 1 monstro Demônio no campo; Invoque este card por Invocação-Especial e, depois, o alvo (se houver) ganha 500 de ATK.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15684835,'Explosão Maligna',replace(replace('Ative apenas quando um monstro for Invocado por Invocação-Especial para o lado do campo do seu oponente. \r\nEquipe este card a esse monstro. \r\nEle ganha 500 de ATK. \r\nDurante cada uma das Fases de Apoio do seu oponente, cause 500 de dano ao seu oponente.','\r',char(13)),'\n',char(10)),'Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15693423,'Confronto Justo',replace(replace('No final da Fase de Batalha, se seu oponente controlar mais cards que você: você pode fazer com que seu oponente bana cards do campo dele, com a face para baixo, até que ele controle o mesmo número de cards que você. \r\nSe você não controlar nenhum card, você pode ativar este card da sua mão.','\r',char(13)),'\n',char(10)),'Ativar aplicando o efeito de "Confronto Justo".','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15710054,'Axônio Krawler',replace(replace('VIRE: Você pode escolher 1 Magia/Armadilha no campo; destrua-o.\r\nSe este card com a face para cima sob o controle do seu dono deixar o campo devido a um efeito de card do oponente: você pode Invocar por Invocação-Especial 2 monstros "Krawler" com nomes diferentes do seu Deck em Posição de Defesa com a face para baixo, exceto "Axônio Krawler". \r\nVocê só pode usar cada efeito de "Axônio Krawler" uma vez por turno.','\r',char(13)),'\n',char(10)),'Destruir Magias/Armadilhas','Invoque 2 monstros por Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15717011,'A Luz - Fusão Selada por Feitiço',replace(replace('Você pode substituir este card por qualquer 1 Monstro-Matéria de Fusão, mas o(s) outro(s) \r\nMonstro(s)-Matéria de Fusão deve(m) estar correto(s). \r\nVocê pode oferecer como Tributo Monstros-Matéria de Fusão no campo, incluindo este card com a face para cima; Invoque por Invocação-Especial 1 Monstro de Fusão de LUZ correspondente do seu Deck Adicional.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15721123,'Confrontar a "B"',replace(replace('Quando seu oponente Invocar um ou mais monstros do Deck Adicional por Invocação-Especial (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe isso acontecer, este card não é afetado por efeitos de monstro que escolham este card como alvo.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15721392,'Apelo Alfancall Super Quantal',replace(replace('Se um monstro "Super Quant" que você controla for destruído em batalha: Invoque por Invocação-Especial 1 Monstro Xyz "Besta Mech Super Quantal" do seu Deck Adicional e, depois, você pode Invocar por Invocação-Especial 1 monstro "Super Quantum" da sua mão, do Deck ou do Cemitério, que esteja especificamente listado no texto desse Monstro Xyz, mas negue seus efeitos. \r\nVocê só pode ativar 1 "Apelo Alfancall Super Quantal" por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial o(s) monstro(s) indicado(s)?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15725501,'Makourai, o Relâmpago',replace(replace('(Este card é sempre considerado como um card "Arquidemônio".)	\r\nEscolha 1 monstro "Arquidemônio" que você controla; ele ganha 600 de ATK, então você pode destruir todos os monstros que seu oponente controla com ATK original menor que o ATK daquele monstro.\r\nDurante sua Fase Principal: você pode banir este card do seu Cemitério, então escolha 1 monstro Demônio de Nível 6 com 2500 de ATK no seu Cemitério; adicione-o à sua mão.\r\nVocê só pode usar cada um dos efeitos de "Makourai, o Relâmpago" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar','Recuperar','Destruir aquele monstro?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15734813,'Alma do Tigre','A alma de um tigre que dizem devorar almas humanas. É uma alma conhecida com a qual você não gostaria de se encontrar num beco escuro.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15735108,'Card de Magia "Troca de Almas"',replace(replace('Imediatamente depois que este efeito resolver, Invoque 1 monstro por Invocação-Tributo (e você pode oferecer como Tributo monstros que seu oponente controla mesmo que você não os controle), mas ele não pode ser oferecido como Tributo neste turno. \r\nSe este card for enviado do campo para o Cemitério: seu oponente pode aplicar o efeito anterior deste card. \r\nVocê só pode ativar 1 "Card de Magia "Troca de Almas"" por turno.','\r',char(13)),'\n',char(10)),'','','Usar o efeito de "Card de Magia "Troca de Almas""?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15744417,'Orgoth, o Implacável',replace(replace('Uma vez por turno, durante sua Fase Principal: você pode lançar um dado de seis faces 3 vezes e este card ganha ATK/DEF igual ao total x 100 (até o final do turno do seu oponente) e, depois, se 2 dos resultados foram o mesmo, aplique o efeito apropriado. \r\nSe todos os 3 foram o mesmo, aplique todos esses efeitos.\r\n● 1 ou 2: Até o final do turno do seu oponente, este card não pode ser destruído em batalha ou por efeitos de card.\r\n● 3 ou 4: Compre 2 cards.\r\n● 5 ou 6: Este card pode atacar diretamente neste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15746348,'Eria, a Canalizadora da Água',replace(replace('(Este card deve ser sempre considerado como um card "Encantador(a)".)	\r\nVocê pode descartar este card e 1 outro monstro de ÁGUA; adicione 1 monstro de ÁGUA do seu Deck à sua mão com um Nível igual ou maior que o do outro monstro descartado e, além disso, você não pode ativar os efeitos de monstros que não sejam de ÁGUA pelo resto deste turno. \r\nQuando um monstro de ÁGUA seu for destruído em batalha: você pode Invocar este card por Invocação-Especial da sua mão. \r\nVocê só pode usar cada efeito de "Eria, a Canalizadora da Água" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15754711,'Despedida Dragãozela',replace(replace('Escolha 1 monstro "Dragãozela" que você controla; Invoque por Invocação-Especial 1 monstro "Dragãozela" com um nome diferente da sua mão, em Posição de Defesa e, se isso acontecer, devolva o monstro alvo para a mão. \r\nO monstro Invocado por Invocação-Especial não pode ser destruído em batalha ou por um efeito de card até o final do próximo turno. \r\nVocê só pode ativar 1 "Despedida Dragãozela" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15758127,'Quinta Carga Ursártica',replace(replace('Uma vez por turno: você pode pagar 700 PV e, depois, ative 1 dos seguinte efeitos;\r\n● Adicione 1 monstro "Ursártico(a)" do seu Cemitério à sua mão.\r\n● Ofereça como Tributo 2 monstros "Ursártico(a)" (mesmo se estiverem com a face para baixo) e, se isso acontecer, Invoque por Invocação-Especial do seu Deck Adicional, 1 monstro "Ursártico(a)" com um Nível igual à diferença em Níveis desses monstros, ignorando suas condições de Invocação.	\r\nQuando um Monstro Sincro "Ursártico(a)" seu for destruído por um ataque do oponente: você pode ativar este efeito; seu oponente deve embaralhar cards no Deck até que o número total de cards no campo, na mão e no Cemitério dele seja 7.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15767889,'Cavaleiro Day Grepher',replace(replace('Este card é considerado um Monstro Normal enquanto estiver com a face para cima no campo ou no Cemitério. \r\nEnquanto este card for um Monstro Normal no campo, você pode Invocá-lo por Invocação-Normal para fazer com que ele se torne um Monstro de Efeito com este efeito.\r\n● Durante sua Fase Final: você pode escolher 1 Card de Magia de Equipamento no seu Cemitério; adicione o alvo à sua mão.	\r\nVocê só pode usar este efeito de "Cavaleiro Day Grepher" uma vez por turno.','\r',char(13)),'\n',char(10)),'Recuperar uma Magia de Equipamento','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15771991,'Guardião Limo',replace(replace('Se você sofrer dano de batalha ou de efeito: você pode Invocar este card por Invocação-Especial da sua mão. \r\nDurante o cálculo de dano, se este card batalhar um monstro do oponente (Efeito Rápido): você pode fazer com que este card ganhe DEF igual ao ATK desse monstro do oponente apenas durante esse cálculo de dano. \r\nSe este card for enviado da mão ou do campo para o Cemitério: você pode adicionar 1 Magia/Armadilha do seu Deck à sua mão que mencione "O Dragão Alado de Rá". \r\nVocê só pode usar cada efeito de "Guardião Limo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15778492,'Jogador de Jogos GG',replace(replace('2 monstros Máquina de Nível 4	\r\nSe este card for Invocado por Invocação-Especial: você pode colocar todos os monstros que seu oponente controla em Posição de Ataque. \r\nSe seu oponente tiver um monstro no campo ou Cemitério dele: você pode desassociar 1 matéria deste card; envie para o Cemitério 1 monstro Máquina do seu Deck/Deck Adicional e, depois, você pode aplicar este efeito.\r\n● Selecione 1 Monstro Xyz Máquina no seu Cemitério e o nome deste card se torna o nome desse monstro até a Fase Final.	\r\nVocê só pode usar este efeito de "Jogador de Jogos GG" uma vez por turno.','\r',char(13)),'\n',char(10)),'Mudar para Posição de Ataque','Enviar para o Cemitério','Alterar o nome deste card?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15792576,'Flagelo dos Céus Cidhels',replace(replace('Não pode ser Invocado por Invocação-Especial. \r\nSe este card for Invocado por Invocação-Tributo pelo Tributo de um dos seguintes monstros no campo: você pode aplicar esse efeito.\r\n● Fada de LUZ: Adicione 1 monstro Fada de LUZ ou 1 Demônio de TREVAS do seu Deck à sua mão.\r\n● Demônio de TREVAS: Envie 1 monstro Fada de LUZ e/ou 1 Demônio de TREVAS do seu Deck para o Cemitério.','\r',char(13)),'\n',char(10)),'','Procurar no Deck','Enviar para o Cemitério','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15800838,'Aperto Mental','Declare 1 nome de card; se esse card estiver na mão do seu oponente, ele deve descartar todas as cópias dele, caso contrário, você descarta 1 card aleatório.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15808381,'Achichi @Ignister',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 monstro "@Ignister" de Nível 4 ou menos do seu Deck à sua mão, exceto "Achichi @Ignister". \r\nNo começo da Etapa de Dano, quando um monstro Ciberso seu batalhar: você pode banir este card do seu Cemitério; destrua esse monstro que você controla. \r\nVocê só pode usar cada efeito de "Achichi @Ignister" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15820147,'Monstartaruga','Protegida por uma carcaça de espinhos, esta tartaruga tem temperamento difícil.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15839054,'Fusionista Sincro','Se este card for enviado ao Cemitério como um Monstro-Matéria Sincro, você pode adicionar 1 Card de Magia do seu Deck para a sua mão com "Polimerização" ou "Fusão" no nome do card, exceto "Difusão em Movimento de Onda".','Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15844566,'Podercodificar Transmissor',replace(replace('3 monstros	\r\nUma vez por turno: você pode escolher 1 monstro com a face para cima no campo; até o final deste turno, negue os efeitos do alvo. \r\nUma vez por turno, se este card batalhar um monstro do oponente, durante o cálculo de dano (Efeito Rápido): você pode oferecer como Tributo 1 monstro para o qual este card apontar; o ATK deste card se torna o dobro do seu ATK original apenas durante esse cálculo de dano.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15845914,'Magos de Laços e Unidade',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao ter 25 ou mais cards no seu Cemitério. \r\nEnquanto seu oponente tiver 25 ou mais cards no Cemitério dele, este card ganha 2500 de ATK/DEF.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15848542,'Dragãozela Tervesen',replace(replace('Não pode ser destruído por efeitos de card enquanto você controlar um Monstro de Fusão. \r\nVocê só pode usar cada um dos seguintes efeitos de "Dragãozela Tervesen" uma vez por turno.\r\n● Você pode descartar este card e, depois, escolha 1 monstro com a face para cima no campo; neste turno, os duelistas não podem ativar os efeitos do alvo no campo.\r\n● No final da Fase de Batalha: você pode devolver este card para a mão e, se isso acontecer, Invoque por Invocação-Especial 1 monstro "Dragãozela" de Nível 3 da sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15854426,'Vendo Divino do Vale das Névoas','Uma vez por turno, se um monstro de VENTO que você controla for devolvido para a mão (exceto durante a Etapa de Dano): você pode Invocar por Invocação-Especial 1 monstro de VENTO de Nível 4 ou menos do seu Deck.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15862758,'Número iC1000: Numerounius Numerounia',replace(replace('5 monstros de Nível 13	\r\nSe este card for Invocado por Invocação-Especial pelo efeito de "Número C1000: Numerounius", ele ganha 100.000 de ATK/DEF apenas durante o turno do seu oponente e, além disso, aplique os seguintes efeitos desde o começo do próximo turno depois que este card foi Invocado por Invocação-Especial.\r\n● Os monstros que seu oponente controla devem atacar este card, se possível.\r\n● No final do turno do seu oponente, se este card não batalhou, você vence o Duelo.	\r\nQuando um monstro do oponente declarar um ataque: você pode desassociar 1 matéria deste card; negue o ataque e, se isso acontecer, ganhe PV igual ao ATK desse monstro.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15866454,'Espiritualismo',replace(replace('Devolva 1 Card de Magia ou Armadilha no Campo do seu adversário para a sua respectiva mão. \r\nA ativação e efeito deste card não podem ser anulados.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15871676,'Constelar Aldebaran','Quando este card for Invocado por Invocação-Normal: você pode Invocar por Invocação-Especial 1 monstro "Constelar" de Nível 3 da sua mão.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15893860,'Criador de Homens de Neve','Quando este card for Invocado: Você pode criar um número de Marcadores de Gelo igual ao número de monstros de ÁGUA que você controla, coloque-os em um ou mais monstros com a face para cima que seu oponente controla e, depois, se você colocou 3 ou mais Marcadores de Gelo por este efeito, você pode destruir 1 card que seu oponente controla.','Colocar um marcador','Escolha o monstro no qual colocar um Marcador de Gelo','Destruir 1 card que seu oponente controla?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15894048,'Ultimate Tyranno',replace(replace('Este card pode atacar todos os monstros que seu oponente controla, uma vez cada. \r\nDurante sua Fase de Batalha, se você controlar um "Ultimate Tyranno" que possa atacar, monstros que não sejam "Ultimate Tyranno" não podem atacar.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15914410,'Angenheiro Mechipado',replace(replace('2 monstros de Nível 3	\r\nUma vez por turno, durante o turno de qualquer duelista: você pode desassociar 1 Matéria Xyz deste card e, depois, escolher 1 monstro com a face para cima em Posição de Ataque que você controla; coloque-o com a face para cima em Posição de Defesa e, se isso acontecer, ele não pode ser destruído em batalha ou por efeitos de card neste turno.','\r',char(13)),'\n',char(10)),'Não pode ser destruído','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15935204,'Convocador de Tempestade',replace(replace('Você pode colocar os monstros do oponente que foram destruídos em batalha com outros monstros do Tipo Psíquico no topo do Deck de seu dono, em vez de enviá-los para o Cemitério. \r\nQuando este card for destruído por um efeito de card, o controlador deste card sofre dano igual ao ATK original dele.','\r',char(13)),'\n',char(10)),'Causar dano','Usar o efeito de "Convocador de Tempestade"?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15936370,'Caixa de Joias de Pandora',replace(replace('Escala de Pêndulo = 4\r\n[ Efeito de Pêndulo ]\r\nEnquanto você não tiver cards no seu Deck Adicional: você pode escolher 1 card na Zona de Pêndulo do seu oponente; destrua-o e, se isso acontecer, coloque este card na Zona de Pêndulo do seu oponente.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nEnquanto você não tiver cards no seu Deck Adicional, compre 2 cards em vez de 1 em sua compra normal durante sua Fase de Compra.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15939229,'D/D/D Kali Yuga, o Rei do Duplo Amanhecer',replace(replace('2 monstros "D/D" de Nível 8	\r\nDepois que este card for Invocado por Invocação-Xyz, pelo resto deste turno, outros cards e seus efeitos não podem ser ativados no campo e os efeitos de outros cards no campo são negados. \r\nUma vez por turno (Efeito Rápido): você pode desassociar 1 matéria deste card; destrua todas as Magias e Armadilhas no campo. \r\nVocê pode desassociar 1 matéria deste card e, depois, escolha 1 Magia/Armadilha "Pacto Obscuro" no seu Cemitério; Baixe o alvo.','\r',char(13)),'\n',char(10)),'Destrua todos os Cards de Magia/Armadilha no campo','Baixar um Card de Magia/Armadilha','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15939448,'Lombriga Escudo',replace(replace('Quando este card for Invocado, ele é colocado em Posição de Defesa. \r\nDepois, envie 1 card do topo do Deck do oponente ao Cemitério para cada monstro do Tipo Inseto com a face para cima que você controla.','\r',char(13)),'\n',char(10)),'Enviar do Deck para o Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15941690,'Cronomalia Ossos de Cristal',replace(replace('Se somente seu oponente controlar um monstro, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nQuando Invocado desta forma: você pode Invocar por Invocação-Especial 1 monstro "Cronomalia" da sua mão ou do Cemitério, exceto "Cronomalia Ossos de Cristal".','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15943341,'Cilindros Mágicos',replace(replace('Baixe 1 "Cilindro Mágico" diretamente do seu Deck ou Cemitério. \r\nSe Baixado do Deck, ele pode ser ativado neste turno. \r\nQuando você ativar "Cilindro Mágico": você pode banir este card do seu Cemitério; dobre esse dano causado ao seu oponente. \r\nVocê só pode usar este efeito de "Cilindros Mágicos" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Ativar aplicando o efeito de "Cilindros Mágicos".','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15947754,'Lobo Silencioso Calupo',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: equipe o card do topo do seu Deck a este card como uma Magia de Equipamento com a face para baixo que concede a ele 500 de ATK. \r\nDurante a Fase Final: seu oponente adivinha o tipo original (Monstro, Magia ou Armadilha) desse Card de Equipamento equipado pelo efeito deste card. \r\nSe ele acertar, envie este card para o Cemitério. \r\nSe ele errar, descarte 1 card aleatório da mão do seu oponente e, se isso acontecer, devolva este card para a mão. \r\nVocê só pode usar este efeito de "Lobo Silencioso Calupo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15951532,'Rainha Amazoness','Monstros "Amazoness" que você controla não podem ser destruídos em batalha.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15960641,'Dragão Miragem','Seu oponente não pode ativar Cards de Armadilha durante a Fase de Batalha.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15967552,'Pequena Rixa',replace(replace('Selecione 2 Zonas de Monstros Principais não utilizadas na mesma coluna; Invoque por Invocação-Especial 1 monstro de Nível 2 ou menos da sua mão ou do Deck com a face para cima em Posição de Ataque ou com a face para baixo em Posição de Defesa na sua Zona de Monstros Principal selecionada e, depois, seu oponente pode fazer o mesmo da mão ou do Deck dele a uma dele. \r\nVocê só pode ativar 1 "Pequena Rixa" por turno.','\r',char(13)),'\n',char(10)),'','Escolher um monstro para Invocá-lo por Invocação Especial?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15978426,'Camarartista Segurro',replace(replace('Quando este card for Invocado por Invocação-Normal ou Especial: você pode enviar 1 monstro "Camarartista" do seu Deck para o Cemitério, exceto "Camarartista Segurro". \r\nSe você tiver 2 cards nas suas Zonas de Pêndulo, em vez disso, você pode adicioná-lo à sua mão.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Adicionar à mão?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15981690,'Carboneddon',replace(replace('Se este card batalhar um monstro de FOGO, durante o cálculo de dano: este card ganha 1000 de ATK, apenas durante o cálculo de dano. \r\nVocê pode banir este card do seu Cemitério; Invoque por Invocação-Especial, da sua mão ou do Deck, 1 Monstro Normal Dragão de Nível 7 ou menos com a face para cima em Posição de Defesa. \r\nVocê só pode usar este efeito de "Carboneddon" uma vez por turno.','\r',char(13)),'\n',char(10)),'Aumentar ATK','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15982593,'Centur-Ião Legatia',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nSeus monstros com 2000 ou menos de ATK não podem ser destruídos em batalha. \r\nVocê só pode usar cada um dos seguintes efeitos de "Centur-Ião Legatia" uma vez por turno. \r\nSe este card for Invocado por Invocação-Especial: você pode comprar 1 card e, depois, você pode destruir o monstro que seu oponente controla com o maior ATK (em caso de empate, você seleciona). \r\nDurante a Fase Final: você pode colocar 1 monstro "Centur-Ião" que não seja Sincro da sua mão ou do Cemitério na sua Zona de Magias & Armadilhas como uma Armadilha Contínua com a face para cima.','\r',char(13)),'\n',char(10)),'','','Destruir o monstro do seu oponente com o maior ATK?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15983048,'Mafteal Magichave Maginífica',replace(replace('Não pode ser usado como matéria para uma Invocação-Sincro ou Xyz, exceto para a Invocação-Sincro ou Xyz de um monstro "Magichave". \r\nSe você controlar um monstro "Magichave": você pode revelar este card na sua mão; você pode Invocar por Invocação-Normal 1 monstro "Magichave" durante sua Fase Principal neste turno, em adição à sua Invocação-Normal/Baixar (padrão). \r\n(Você só pode se aproveitar deste efeito uma vez por turno.) \r\nQuando este card for Invocado por Invocação-Normal: você pode escolher 1 Monstro Normal de Nível 4 ou menos ou monstro "Magichave" de Nível 4 ou menos no seu Cemitério; Invoque-o por Invocação-Especial em Posição de Defesa. \r\nVocê só pode usar este efeito de "Mafteal Magichave Maginífica" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Invocar pelo efeito de "Mafteal Magichave Maginífica"','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15989522,'Gaia, o Cavaleiro Mágico do Dragão',replace(replace('1 monstro "Gaia, o Cavaleiro Impetuoso" + 1 monstro Dragão de Nível 5	\r\nO nome deste card se torna "Gaia, o Matador de Dragões" enquanto estiver no campo. \r\nVocê só pode usar cada um dos seguintes efeitos de "Gaia, o Cavaleiro Mágico do Dragão" uma vez por turno. \r\nDurante a Fase Principal (Efeito Rápido): você pode escolher 1 outro card no campo; este card perde exatamente 2600 de ATK e, se isso acontecer, destrua esse card. \r\nQuando este card destruir um monstro do oponente em batalha: você pode fazer com que este card ganhe 2600 de ATK.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16001119,'Batan Vermelha',replace(replace('Você pode escolher 1 monstro "Batan" que você controla; considere-o como um Regulador até o final do próximo turno. \r\nSe um monstro for Invocado por Invocação-Sincro enquanto você controlar este monstro: você pode Invocar por Invocação-Especial 1 monstro "Batan" da sua mão ou do Deck. \r\nVocê só pode usar cada efeito de "Batan Vermelha" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16003979,'Besta Gladiadora Sagittarii',replace(replace('Se este card for Invocado por Invocação-Especial pelo efeito de um monstro "Besta Gladiadora": você pode descartar 1 card "Besta Gladiadora"; compre 2 cards. \r\nNo final da Fase de Batalha, se este card batalhou: você pode embaralhar este card no Deck; Invoque por Invocação-Especial 1 monstro "Besta Gladiadora" do seu Deck, exceto "Besta Gladiadora Sagittarii".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16006416,'D/D/D Gengis, o Alto Rei das Chamas',replace(replace('1 monstro "D/D" de Nível 5 ou mais + 1 monstro "D/D"	\r\nSe outro(s) monstro(s) "D/D" for(em) \r\nInvocado(s) por Invocação-Normal ou Especial no seu campo enquanto você controlar este monstro (exceto durante a Etapa de Dano): você pode escolher 1 monstro "D/D" no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê só pode usar este efeito de "D/D/D Gengis, o Alto Rei das Chamas" uma vez por turno. \r\nUma vez a cada turno seu, quando um Card de Magia/Armadilha, ou seus efeitos, for ativado (Efeito Rápido): você pode negar a ativação.','\r',char(13)),'\n',char(10)),'Invocação Especial','Negar a ativação','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16008155,'Servo Reptiliano',replace(replace('Destrua este card se houver monstros com a face para cima no campo que não sejam este card. \r\nDestrua este card quando ele for escolhido como alvo do efeito de um Card de Magia ou Armadilha. \r\nNenhum duelista pode Invocar um monstro por Invocação-Normal enquanto este card estiver com a face para cima no campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16020923,'Pikari @Ignister',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 Magia/Armadilha "I.A." do seu Deck à sua mão. \r\nVocê pode escolher 1 monstro "@Ignister" que você controla; o Nível dele se torna 4 até o final deste turno. \r\nVocê só pode usar cada efeito de "Pikari @Ignister" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16021142,'Canon, a Diva Melodiosa',replace(replace('Se você controlar um monstro "Melodiosa(o)", você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Canon, a Diva Melodiosa" por Invocação-Especial uma vez por turno desta forma. \r\nUma vez por turno: você pode escolher 1 monstro "Melodiosa(o)" que você controla; mude a posição de batalha dele.','\r',char(13)),'\n',char(10)),'Invocação Especial','Alterar posição de batalha','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16024176,'Flor Cardian Pinho com Guindaste',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro deve ser Invocado por Invocação-Especial (da sua mão) ao oferecer como Tributo 1 monstro "Flor Cardian" de Nível 1, exceto "Flor Cardian Pinho com Guindaste". \r\nSe este card for Invocado por Invocação-Especial: compre 1 card e, se isso acontecer, mostre-o e, depois, você pode Invocá-lo por Invocação-Especial se ele for um monstro "Flor Cardian". \r\nCaso contrário, envie-o para o Cemitério. \r\nUma vez por turno, no final da Fase de Batalha, se este card batalhou: você pode comprar 1 card.','\r',char(13)),'\n',char(10)),'Compre 1 card e revele a ambos os jogadores','Invocação Especial?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16037007,'Número 74: Mestre das Lâminas',replace(replace('2 monstros de Nível 7	\r\nQuando um card ou efeito for ativado que escolha este card com a face para cima como alvo (Efeito Rápido): você pode desassociar 1 matéria deste card; negue a ativação e, se isso acontecer, destrua esse card e, depois, você pode destruir 1 card no campo.','\r',char(13)),'\n',char(10)),'Negar e destruir','Destruir 1 card no campo?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16051717,'Asanegra Agressor - Raikiri, o Banho de Chuva',replace(replace('1 Regulador + 1 ou mais monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro usando um monstro "Asanegra" como Matéria, ele é considerado como um monstro Regulador enquanto estiver com a face para cima no campo. \r\nUma vez por turno: você pode escolher cards que seu oponente controla, até o número de outros monstros "Asanegra" que você controla; destrua-os.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16066654,'Teste de Operação R.B.',replace(replace('Quando este card for ativado: você pode escolher 1 monstro "R.B." de Nível 3 ou mais no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê pode escolher qualquer número de monstros "R.B." que você controla; ganhe PV igual ao ATK original combinado deles e, se isso acontecer, devolva-os para a mão/o Deck Adicional e, depois, você pode Invocar por Invocação-Especial 1 monstro "R.B." da sua mão. \r\nVocê só pode usar este efeito de "Teste de Operação R.B." uma vez por turno. \r\nVocê só pode ativar 1 "Teste de Operação R.B." por turno.','\r',char(13)),'\n',char(10)),'','Ganhar PV','Escolher um card?','Invocar por Invocação Especial da sua mão?','','','','','','','','','','','','');
INSERT INTO texts VALUES(16067089,'Ascenção da Divindade Serpente','Quando um "Vennominon, o Rei das Serpentes Venenosas" com a face para cima que você controla for destruído, exceto em batalha: Invoque por Invocação-Especial 1 "Vennominaga, a Divindade das Serpentes Venenosas" da sua mão ou do Deck.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16110708,'Número S38: Titã da Galáxia',replace(replace('3 monstros de LUZ de Nível 9	\r\nVocê também pode Invocar este card por Invocação-Xyz ao usar "Número 38: Dragão Titã da Galáxia Arauto da Esperança" que você controla (transfira as matérias dele para este card). \r\nGanha 200 de ATK para cada matéria associada a ele. \r\nUma vez por turno: você pode escolher até 2 Magias/Armadilhas que seu oponente controla; associe-as a este card como matéria. \r\nNenhum duelista pode ativar esses cards ou seus efeitos em resposta à ativação deste efeito. \r\nVocê pode desassociar 1 matéria deste card; até o final deste turno, o ATK original deste card se torna 1500 e, além disso, ele pode atacar diretamente.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Xyz usando "Número 38: Dragão Titã da Galáxia Arauto da Esperança" como matéria?','Aumentar ATK','Como Matéria Xyz','Ataque direto','','','','','','','','','','','','');
INSERT INTO texts VALUES(16111820,'Jurrac Herra','Quando um monstro "Jurrac" em Posição de Defesa que você controla, exceto "Jurrac Herra", for destruído em batalha e enviado para o Cemitério: você pode Invocar este card por Invocação-Especial da sua mão ou do Cemitério.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16114248,'Par Cycroide',replace(replace('2 monstros Máquina com o mesmo nome	\r\nEste card pode atacar diretamente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16135253,'Agido',replace(replace('Quando este card é destruído como resultado de um combate e enviado para o Cemitério, lance um dado de seis lados. \r\nVocê pode Invocar, por Invocação-Especial, 1 monstro do Tipo Fada do seu Cemitério cujo Nível seja igual ao resultado. \r\nSe o resultado for 6, você pode Invocar, por Invocação-Especial, um monstro de Nível 6 ou mais.','\r',char(13)),'\n',char(10)),'Rolar um dado','Invocar por Invocação Especial um monstro Fada?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16146511,'Eveque Evocador',replace(replace('Este card é considerado como um Monstro Normal enquanto estiver com a face para cima no campo ou no Cemitério. \r\nEnquanto este card for um Monstro Normal no campo, você pode Invocá-lo por Invocação-Normal para fazer com que ele se torne um Monstro de Efeito com este efeito.\r\n● Se este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 monstro Guerreiro de FOGO ou 1 monstro Gêmeos no seu Cemitério, exceto "Eveque Evocador"; Invoque-o por Invocação-Especial.	\r\nVocê só pode usar este efeito de "Eveque Evocador" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16157341,'Pernalta Bujingi','Durante sua Fase Principal 1: você pode enviar este card da sua mão para o Cemitério e, depois, escolher 1 monstro "Bujin" que você controla; neste turno, se ele atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente.','Ganhar dano perfurante','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16165939,'Zona de Perigo Sobrenatural',replace(replace('Se um Monstro que não seja de Efeito for Invocado por Invocação-Especial com a face para cima (exceto durante a Etapa de Dano): você pode escolher 1 card que seu oponente controla; destrua-o. \r\nSe este card na Zona de Magias & Armadilhas do seu dono for destruído por um efeito de card do oponente: você pode Invocar por Invocação-Especial 1 Monstro que não seja de Efeito da sua mão, do Deck ou do Cemitério. \r\nVocê só pode usar cada efeito de "Zona de Perigo Sobrenatural" uma vez por turno.','\r',char(13)),'\n',char(10)),'Destruir um card do seu oponente','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16169772,'Contato Instantâneo',replace(replace('Pague 1000 PV; Invoque por Invocação-Especial 1 monstro "HERÓI do Elemento" ou "Neoespacial" de Nível 7 ou menos do seu Deck Adicional, ignorando suas condições de Invocação. \r\nEnquanto "Neos, o HERÓI do Elemento" não estiver nem no seu campo nem no seu Cemitério, o monstro Invocado não pode atacar, seus efeitos são negados e, além disso, ele é devolvido ao Deck Adicional durante a Fase Final. \r\nVocê só pode ativar 1 "Contato Instantâneo" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16172067,'Tirano Dragão Vermelho Arquidemônio',replace(replace('2 Reguladores + 1+ monstros não-Reguladores	\r\nDeve ser Invocado por Invocação-Sincro. \r\nDurante sua Fase Principal 1: você pode destruir todos os outros cards no campo e, além disso, pelo resto deste turno, outros monstros que você controla não podem atacar. \r\nDurante a Fase de Batalha, quando um Card de Magia/Armadilha for ativado (Efeito Rápido): você pode negar a ativação e, se isso acontecer, destrua esse card e, se isso acontecer, este card ganha 500 de ATK. \r\nVocê só pode usar cada efeito de "Tirano Dragão Vermelho Arquidemônio" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16178681,'Dragão Pêndulo de Olhos Anômalos',replace(replace('Escala de Pêndulo = 4\r\n[ Efeito de Pêndulo ]\r\nVocê pode reduzir a 0 o dano de batalha que você sofrer de um ataque envolvendo um Monstro Pêndulo que você controla. \r\nDurante sua Fase Final: você pode destruir este card e, se isso acontecer, adicione 1 Monstro Pêndulo com 1500 ou menos de ATK do seu Deck à sua mão. \r\nVocê só pode usar cada Efeito de Pêndulo de "Dragão Pêndulo de Olhos Anômalos" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe este card batalhar um monstro do oponente, qualquer dano de batalha que este card causar ao seu oponente é dobrado.','\r',char(13)),'\n',char(10)),'Alterar dano','Procurar no Deck','Fazer o dano de batalha ser 0?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16178682,'Dragão Pêndulo de Olhos Anômalos',replace(replace('Escala de Pêndulo = 4\r\n[ Efeito de Pêndulo ]\r\nVocê pode reduzir a 0 o dano de batalha que você sofrer de um ataque envolvendo um Monstro Pêndulo que você controla. \r\nDurante sua Fase Final: você pode destruir este card e, se isso acontecer, adicione 1 Monstro Pêndulo com 1500 ou menos de ATK do seu Deck à sua mão. \r\nVocê só pode usar cada Efeito de Pêndulo de "Dragão Pêndulo de Olhos Anômalos" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe este card batalhar um monstro do oponente, qualquer dano de batalha que este card causar ao seu oponente é dobrado.','\r',char(13)),'\n',char(10)),'Alterar dano','Procurar no Deck','Fazer o dano de batalha ser 0?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16178683,'Dragão Pêndulo de Olhos Anômalos',replace(replace('Escala de Pêndulo = 4\r\n[ Efeito de Pêndulo ]\r\nVocê pode reduzir a 0 o dano de batalha que você sofrer de um ataque envolvendo um Monstro Pêndulo que você controla. \r\nDurante sua Fase Final: você pode destruir este card e, se isso acontecer, adicione 1 Monstro Pêndulo com 1500 ou menos de ATK do seu Deck à sua mão. \r\nVocê só pode usar cada Efeito de Pêndulo de "Dragão Pêndulo de Olhos Anômalos" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe este card batalhar um monstro do oponente, qualquer dano de batalha que este card causar ao seu oponente é dobrado.','\r',char(13)),'\n',char(10)),'Alterar dano','Procurar no Deck','Fazer o dano de batalha ser 0?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16178684,'Dragão Pêndulo de Olhos Anômalos',replace(replace('Escala de Pêndulo = 4\r\n[ Efeito de Pêndulo ]\r\nVocê pode reduzir a 0 o dano de batalha que você sofrer de um ataque envolvendo um Monstro Pêndulo que você controla. \r\nDurante sua Fase Final: você pode destruir este card e, se isso acontecer, adicione 1 Monstro Pêndulo com 1500 ou menos de ATK do seu Deck à sua mão. \r\nVocê só pode usar cada Efeito de Pêndulo de "Dragão Pêndulo de Olhos Anômalos" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe este card batalhar um monstro do oponente, qualquer dano de batalha que este card causar ao seu oponente é dobrado.','\r',char(13)),'\n',char(10)),'Alterar dano','Procurar no Deck','Fazer o dano de batalha ser 0?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16188701,'Joaninha Debug',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 monstro Ciberso de Nível 3 ou menos do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Joaninha Debug" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16191953,'Mestre Gig','Uma vez por turno, você pode pagar 1000 PV para destruir monstros que seu oponente controla igual ao número de monstros do Tipo Psíquico com a face para cima que você controla.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16195942,'Dragão Xyz da Rebelião Negra',replace(replace('2 monstros de Nível 4	\r\nVocê pode desassociar 2 matérias deste card e, depois, escolha 1 monstro com a face para cima que seu oponente controla; o ATK dele se torna metade do seu ATK atual e, se isso acontecer, este card ganha esse valor de ATK perdido.','\r',char(13)),'\n',char(10)),'Alterar ATK/DEF','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16195943,'Dragão Xyz da Rebelião Negra',replace(replace('2 monstros de Nível 4	\r\nVocê pode desassociar 2 matérias deste card e, depois, escolha 1 monstro com a face para cima que seu oponente controla; o ATK dele se torna metade do seu ATK atual e, se isso acontecer, este card ganha esse valor de ATK perdido.','\r',char(13)),'\n',char(10)),'Alterar ATK/DEF','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16197610,'Nuviano - Turbulência',replace(replace('Não pode ser destruído em batalha. \r\nSe este card estiver com a face para cima em Posição de Defesa, destrua-o. \r\nSe este card for Invocado por Invocação-Normal: coloque 1 Marcador de Névoa nele para cada monstro "Nuviano" no campo. \r\nVocê pode remover 1 Marcador de Névoa deste card; Invoque por Invocação-Especial 1 "Nuviano - Bola de Fumaça" do seu Deck ou de qualquer Cemitério.','\r',char(13)),'\n',char(10)),'Colocar um marcador','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16209941,'Perigo! Chupa-cabra!',replace(replace('Você pode revelar este card na sua mão; seu oponente seleciona aleatoriamente 1 card de toda a sua mão e, depois, você descarta o card selecionado. \r\nDepois, se o card descartado não era "Perigo! Chupa-cabra!", Invoque por Invocação-Especial 1 "Perigo! Chupa-cabra!" da sua mão e, se isso acontecer, compre 1 card. \r\nSe este card for descartado: você pode escolher 1 monstro "Perigo!" no seu Cemitério, exceto "Perigo! Chupa-cabra!"; Invoque-o por Invocação-Especial. \r\nVocê só pode usar este efeito de "Perigo! Chupa-cabra!" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16222645,'Samurai Sasuke','No começo da Etapa de Dano, se este card atacar um monstro com a face para baixo em Posição de Defesa: destrua esse monstro com a face para baixo.','Destruir o monstro atacado em Posição de Defesa com a face para baixo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16223761,'Mão do Trovão',replace(replace('Se um ou mais monstros com a face para cima que você controla com 1600 de ATK ou DEF original forem destruídos em batalha ou por um efeito de card do oponente e enviados para o Cemitério, enquanto este card estiver na sua mão ou no Cemitério: você pode Invocar este card por Invocação-Especial (mas bana-o quando ele deixar o campo) e, se isso acontecer, destrua 1 card que seu oponente controla. \r\nVocê só pode usar este efeito de "Mão do Trovão" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16226786,'Assaltante Noturno',replace(replace('VIRE: Escolha 1 monstro que seu oponente controla; destrua o alvo.\r\nSe este card for enviado da mão para o Cemitério: escolha 1 monstro de Virar no seu Cemitério, exceto "Assaltante Noturno"; adicione o alvo à sua mão.','\r',char(13)),'\n',char(10)),'Destruir','Retornar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16227556,'Inspeção','Durante a Fase de Apoio do seu oponente, você pode selecionar aleatoriamente 1 card da mão do seu oponente e olhá-lo ao custo de 500 PV.','Ver a mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16227633,'Volta dos Ossos Mementotlan',replace(replace('Se um ou mais monstros "Memento" com a face para cima que você controla deixarem o campo devido a um card do oponente: Invoque por Invocação-Especial 1 "Mementoal Tecuhtlica - Criação Combinada" da sua mão ou do Deck, ignorando suas condições de Invocação. \r\nSe seu oponente mover um ou mais monstros "Memento" para fora do seu Cemitério, enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode banir este card; Invoque por Invocação-Especial tantos monstros "Memento" quanto possível com nomes diferentes da sua mão e/ou do Deck. \r\nVocê só pode usar cada efeito de "Volta dos Ossos Mementotlan" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16229315,'Dogra do Vendaval','Você pode pagar 3000 PV; envie 1 monstro do seu Deck Adicional para o Cemitério.','Enviar para o Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16237004,'Cavaleiro Xamã Xamanita',replace(replace('2+ monstros de Nível 3	\r\nSe este card for Invocado por Invocação-Xyz, ou se uma Armadilha da qual você é dono for banida: você pode escolher 1 das suas Armadilhas banidas; associe-a a este card. \r\nVocê pode desassociar qualquer número de matérias deste card e, depois, escolha 1 monstro de TREVAS no seu Cemitério ou banimento com um Nível igual ao número desassociado; Invoque-o por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Cavaleiro Xamã Xamanita" uma vez por turno.','\r',char(13)),'\n',char(10)),'Associar Matéria Xyz','Invocação Especial','Escolha a quantidade de Matérias Xyz a desassociar','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16238373,'Arsenal Psíquico',replace(replace('Escolha 1 monstro Psíquico que você controla e pague PV igual ao seu Nível x 200; adicione 1 monstro Máquina com o mesmo Atributo, mas de Nível maior, do seu Deck à sua mão. \r\nDurante sua Fase Principal, exceto no turno em que este card foi enviado para o Cemitério: você pode banir este card do seu Cemitério e, depois, escolha 1 de cada dentre seus monstros Psíquico e Máquina banidos; coloque 1 deles no fundo do Deck e, se isso acontecer, adicione o outro à sua mão. \r\nVocê só pode usar cada efeito de "Arsenal Psíquico" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Recuperar um card banido','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16240772,'Despojos do Pecado da Perdição - Rciela',replace(replace('Escolha 1 monstro Mago de Nível 7 ou mais que você controla; aplique os seguintes efeitos.\r\n● Enquanto estiver com a face para cima, esse monstro não é afetado por outros efeitos de monstro neste turno e é enviado para o Cemitério durante a Fase de Apoio do próximo turno.\r\n● Todos os monstros que seu oponente controla atualmente perdem ATK igual ao ATK do monstro alvo e, depois, se o ATK de qualquer um deles se tornar 0 por este efeito, destrua-o.	\r\nVocê só pode ativar 1 "Despojos do Pecado da Perdição - Rciela" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16241441,'Crisálida de Lagarta','Você pode oferecer este card como Tributo enquanto "Neo Espaço" estiver no campo para Invocar por Invocação-Especial 1 "Escaravelho de Chamas Neoespacial" da sua mão ou Deck.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16246527,'Rato Blindado','O couro deste rato monstro é tão grosso que resiste a espadadas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16246535,'Bruxo Psíquico Silencioso',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Especial: você pode escolher 1 monstro Psíquico de Nível 4 ou menos no seu Cemitério ou banimento; Invoque-o por Invocação-Especial e, depois, você pode aumentar seu Nível em 1 e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto monstros Psíquico. \r\nVocê só pode usar este efeito de "Bruxo Psíquico Silencioso" uma vez por turno. \r\nSe este card que você controla seria usado como Matéria Sincro, você pode considerá-lo como um não-Regulador.','\r',char(13)),'\n',char(10)),'Invocação Especial','Aumentar o Nível?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16255173,'O Grande Júpiter',replace(replace('Uma vez por turno: você pode descartar 2 cards e, depois, escolha 1 monstro com a face para cima que seu oponente controla; equipe esse monstro com a face para cima a este card. \r\nEste card ganha ATK igual ao ATK original combinado dos monstros equipados a ele por este efeito. \r\nUma vez por turno, durante a Fase Final: você pode escolher 1 Card de Monstro equipado a este card pelo efeito deste card; Invoque-o por Invocação-Especial no seu campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16255442,'Luz do Conhecimento','Descarte toda a sua mão e, depois, para cada card que você descartou para o Cemitério devido a este efeito, adicione 1 monstro de LUZ do seu Cemitério à sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16259549,'Número 49: Melovidente',replace(replace('2 monstros de Nível 3	\r\nNenhum duelista pode escolher este card no campo como alvo de efeitos de card. \r\nSe este card seria destruído em batalha ou por um efeito de card, em vez disso, você pode desassociar 1 matéria deste card. \r\nUma vez por turno, durante sua Fase de Apoio: ganhe 500 PV. \r\nSe este card for enviado do campo para o Cemitério: escolha 2 monstros de Nível 3 no seu Cemitério; embaralhe-os no Deck e, se isso acontecer, devolva este card do seu Cemitério para o Deck Adicional. \r\nVocê só pode usar este efeito de "Número 49: Melovidente" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ganhar PV','Retornar ao Deck','Usar o efeito de "Número 49: Melovidente" em vez de ser destruído?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16261341,'Sagrado Arquicavaleiro Celeste Parshath',replace(replace('Se você ativar um Card de Armadilha de Resposta, OU se você negar a ativação de um Card de Magia/Armadilha ou efeito de monstro (exceto durante a Etapa de Dano): você pode banir 2 outros monstros Fada da sua mão, do campo e/ou do Cemitério; Invoque este card por Invocação-Especial do Cemitério (se ele estava lá quando você ativou/negou) ou da mão (mesmo se ele não estava). \r\nSe este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante. \r\nQuando este card causar dano de batalha ao seu oponente: você pode adicionar 1 card "Parshath" ou 1 Armadilha de Resposta do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16268841,'Zolga','Se um monstro for Invocado por Invocação-Tributo tendo recebido este card como Tributo: ganhe 2000 PV.','Ganhar PV','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16269385,'Clube dos Travesso-Guris',replace(replace('Quando este card for ativado: você pode adicionar 1 monstro "Travesso-Guris" do seu Deck à sua mão. \r\nUma vez por turno, se você Invocar por Invocação-Fusão um Monstro de Fusão "Travesso-Guris" (exceto durante a Etapa de Dano): você pode fazer com que todos os monstros que você controla ganhem 500 de ATK (mesmo que este card deixe o campo). \r\nUma vez por turno, se você Invocar por Invocação-Link um Monstro Link "Travesso-Guris" (exceto durante a Etapa de Dano): você pode fazer com que todos os monstros que seu oponente controla percam 500 de ATK (mesmo que este card deixe o campo). \r\nVocê só pode ativar 1 "Clube dos Travesso-Guris" por turno.','\r',char(13)),'\n',char(10)),'Adicionar à sua mão 1 monstro "Travesso-Guris"?','Aumentar o ATK de todos os monstros que você controla','Diminua o ATK de todos os monstros do seu oponente','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16272453,'Habilidade Ninjitsu da Alquimia','Se você controlar um card "Ninjitsu": destrua tantos outros cards "Ninjitsu" que você controla quanto possível e, depois, compre 2 cards.','Destruir e comprar 1 card','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16278116,'Vínculo do Dragão',replace(replace('Ative este card ao escolher 1 monstro do Tipo Dragão que você controla com 2500 ou menos de ATK e DEF; nenhum duelista pode Invocar por Invocação-Especial monstros com ATK menor ou igual ao ATK original desse monstro. \r\nQuando esse monstro deixar o campo, destrua este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16279989,'Stein Fantardil',replace(replace('Não pode ser Invocado por Invocação-Normal, a não ser que você controle um monstro "Fantardil". \r\nUma vez por turno: você pode colocar este card com a face para baixo em Posição de Defesa. \r\nQuando este card causar dano de batalha ao seu oponente: você pode adicionar 1 Card de Magia/Armadilha "Fantardil" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Stein Fantardil" uma vez por turno.','\r',char(13)),'\n',char(10)),'Mudar para Posição de Defesa com a face para baixo','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16304628,'Gaia, o HERÓI do Elemento',replace(replace('1 monstro "HERÓI do Elemento" + 1 monstro de TERRA	\r\nDeve ser Invocado por Invocação-Fusão. \r\nSe este card for Invocado por Invocação-Fusão: escolha 1 monstro com a face para cima que seu oponente controla; até o final deste turno, seu ATK é diminuído pela metade e, se isso acontecer, este card ganha esse ATK perdido.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16306932,'Dragão da Revolução de Olhos Anômalos',replace(replace('Escala de Pêndulo = 12\r\n[ Efeito de Pêndulo ]\r\nVocê não pode Invocar monstros por Invocação-Pêndulo, exceto monstros Dragão. \r\nEste efeito não pode ser negado. \r\nVocê pode escolher 1 Monstro de Fusão, Sincro ou Xyz Dragão no seu Cemitério; destrua este card e, se isso acontecer, Invoque o alvo por Invocação-Especial.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nNão pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Pêndulo (da sua mão), ou ser Invocado por Invocação-Especial (da sua mão) ao oferecer 3 monstros Dragão como Tributo (1 de Fusão, 1 Sincro e 1 Xyz). \r\nVocê pode descartar este card e pagar 500 PV: adicione 1 Monstro Pêndulo Dragão de Nível 8 ou menos do seu Deck à sua mão. \r\nGanha ATK/DEF igual à metade dos PV do seu oponente. \r\nUma vez por turno: você pode pagar metade dos seus PV; embaralhe no Deck todos os outros cards do campo e dos Cemitérios.','\r',char(13)),'\n',char(10)),'Invoque por Invocação Especial 1 monstro do Cemitério','Procurar no Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16308000,'Autoridade Solene',replace(replace('Ative este card ao escolher 1 monstro "Aesir" que você controla; ele não pode ser escolhido como alvo de outros efeitos de card enquanto este card estiver no campo. \r\nEnvie este card para o Cemitério durante sua 2ª Fase de Apoio depois da ativação.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16310544,'Kagura Mikanko',replace(replace('Este card pode ser usado para a Invocação-Ritual de qualquer Monstro de Ritual "Mikanko". \r\nVocê também deve oferecer como Tributo monstros da sua mão ou do campo cuja soma dos Níveis seja igual ou exceda o Nível do Monstro de Ritual que você Invocar por Invocação-Ritual. \r\nDepois você pode aplicar o seguinte efeito.\r\n● Destrua cards que seu oponente controla até o número de Magias de Equipamento com nomes diferentes no seu Cemitério e, se isso acontecer, cause 1000 de dano ao seu oponente para cada card destruído.	\r\nVocê só pode ativar 1 "Kagura Mikanko" por turno.','\r',char(13)),'\n',char(10)),'Destruir 1 card que seu oponente controla?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16312943,'Fogo Livromante',replace(replace('Você pode revelar 1 Monstro de Ritual da sua mão: Invoque este card por Invocação-Especial da sua mão. \r\nSe este card for Invocado por Invocação-Especial: você pode adicionar 1 monstro "Livromante" do seu Deck à sua mão, exceto "Fogo Livromante". \r\nVocê só pode usar cada efeito de "Fogo Livromante" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16313112,'Salamagrande Águia Esmeralda',replace(replace('Você pode Invocar este card por Invocação-Ritual com "Ascensão da Salamagrande". \r\nQuando este card for Invocado por Invocação-Ritual usando "Salamagrande Águia Esmeralda" que você controla: você pode destruir todos os monstros Invocados por Invocação-Especial que seu oponente controla. \r\nUma vez por turno: você pode oferecer como Tributo 1 Monstro Link "Salamagrande"; neste turno, este card ganha este efeito.\r\n● No começo da Etapa de Dano, se este card batalhar um monstro do oponente: destrua esse monstro do oponente e, se isso acontecer, cause dano ao seu oponente igual ao ATK original desse monstro.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16317140,'Hiperchamas',replace(replace('Para Invocar "Uria, o Senhor das Chamas Cortantes" por Invocação-Especial usando seus próprios métodos, você também pode usar Armadilhas com a face para baixo que você controla. \r\nUma vez por batalha, quando um ataque for declarado envolvendo seu "Uria, o Senhor das Chamas Cortantes": você pode enviar 1 Armadilha da sua mão ou do Deck para o Cemitério; pelo resto deste turno, seu ATK/DEF se tornam o número de Armadilhas com a face para cima no campo e nos Cemitérios x 1000. \r\nUma vez por turno: você pode descartar 1 card; adicione à sua mão ou Invoque por Invocação-Especial, 1 "Uria, o Senhor das Chamas Cortantes", "Hamon, o Senhor do Trovão Impactante" ou "Raviel, o Senhor dos Fantasmas" do seu Cemitério, ignorando suas condições de Invocação.','\r',char(13)),'\n',char(10)),'Alterar ATK/DEF','Adicionar à mão ou Invocar por Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16327715,'Guerreiro Sucata Extremo',replace(replace('"Sucata Sincron" + 1+ monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro: você pode Invocar por Invocação-Especial tantos monstros de Nível 2 ou menos quanto possível do seu Cemitério, mas nenhum duelista pode ativar os efeitos desses monstros neste turno e, além disso, você só pode Invocar por Invocação-Especial mais uma vez neste turno. \r\nQuando este card destruir um monstro do oponente em batalha: você pode banir este card; Invoque por Invocação-Especial 1 Monstro Sincro "Sucata" do seu Deck Adicional (isso é considerado uma Invocação-Sincro). \r\nVocê só pode usar cada efeito de "Guerreiro Sucata Extremo" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial do Cemitério','Invoque por Invocação Especial do Deck Adicional','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16329071,'Globo Armadilha do Legado Mundial',replace(replace('Embaralhe no Deck, 5 cards "Legado Mundial" seus com nomes diferentes que estiverem banidos, na sua mão, no Cemitério e/ou com a face para cima no seu campo, exceto "Globo Armadilha do Legado Mundial" e, depois, compre 2 cards. \r\nVocê só pode ativar 1 "Globo Armadilha do Legado Mundial" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16353197,'Lagarto Salivador','Um réptil humanóide que suga o sangue de qualquer ser vivo que passa por perto dele.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16360142,'Mechamático Subtração',replace(replace('Você pode escolher 1 monstro com a face para cima no campo; você não pode Invocar monstros por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto monstros Ciberso e, além disso, Invoque este card por Invocação-Especial da sua mão (mas ele não pode atacar neste turno) e, se isso acontecer, o monstro alvo perde 1000 de ATK até o final deste turno. \r\nVocê só pode usar este efeito de "Mechamático Subtração" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16366810,'Poerio Amarelo',replace(replace('Não pode ser usado como Fusão, Sincro ou Matéria Xyz para uma Invocação. \r\nEnquanto este card estiver com a face para cima no campo, ele não pode ser oferecido como Tributo. \r\nQuando este card no campo for destruído: seu controlador escolhe 1 monstro no Cemitério dele; embaralhe o alvo no Deck. \r\nVocê só pode controlar 1 "Poerio Amarelo" com a face para cima.','\r',char(13)),'\n',char(10)),'Retornar ao Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16366944,'Mariposa Lunar','Quando este card for enviado do campo ao Cemitério: Você pode Invocar por Invocação-Especial 1 monstro "Borbolespiã" de Nível 4 ou menos do seu Deck.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16387555,'Kewl Tune Cue',replace(replace('Se este card no campo seria usado como Matéria Sincro, 1 Regulador na sua mão pode ser usado como 1 das outras matérias. \r\nVocê só pode usar cada um dos seguintes efeitos de "Kewl Tune Cue" uma vez por turno. \r\nSe este card for Invocado por Invocação-Normal: você pode Invocar por Invocação-Especial 1 Regulador da sua mão, do Deck ou do Cemitério, exceto "Kewl Tune Cue" e, além disso, pelo resto deste turno você não pode Invocar por Invocação-Especial, exceto Reguladores. \r\nSe este card for enviado para o Cemitério como Matéria Sincro: você pode escavar 2 cards do topo do Deck do seu oponente, banir 1 deles e colocar o outro no topo ou no fundo do Deck.','\r',char(13)),'\n',char(10)),'Invocação Especial','Efeito de banimento','Coloque no topo do Deck','Coloque no fundo do Deck','','','','','','','','','','','','');
INSERT INTO texts VALUES(16392422,'Feiticeiro Mascarado Toon',replace(replace('Não pode atacar no turno em que for Invocado. \r\nSe "Mundo Toon", no campo, for destruído, destrua este card. \r\nEnquanto você controlar "Mundo Toon" e seu oponente não controlar nenhum monstro Toon, este card pode atacar diretamente seu oponente. \r\nSe este card causar dano de batalha ao seu oponente: compre 1 card.','\r',char(13)),'\n',char(10)),'Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16404809,'Kuribandido','Durante a Fase Final, se este card foi Invocado por Invocação-Normal neste turno: você pode oferecer este card como Tributo; escave os 5 cards do topo do seu Deck, você pode adicionar 1 Magia/Armadilha escavada à sua mão e, além disso, envie os cards restantes para o Cemitério.','Escave cards do seu Deck','Adicionar 1 Card de Magia/Armadilha à sua mão?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16428514,'Guru Subterror',replace(replace('VIRE: Você pode adicionar 1 card "Subterror" do seu Deck à sua mão, exceto "Guru Subterror". \r\nVocê pode escolher 1 outro monstro com a face para cima no campo; coloque esse monstro, e também este card, com a face para baixo em Posição de Defesa. \r\nEste é um Efeito Rápido se você controlar outro card "Subterror". \r\nVocê só pode usar cada efeito de "Guru Subterror" uma vez por turno.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Mudar para Posição de Defesa com a face para baixo','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16430187,'O Guardião de Confiança','Aumente o DEF de 1 monstro à sua escolha em 700 pontos durante o turno em que este card é Activado.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16433136,'Dança de Purificação Mikanko',replace(replace('Só pode ser equipado a um monstro "Mikanko". \r\nO monstro equipado não pode ser destruído por efeitos de card. \r\nSe um ou mais monstros forem Invocados por Invocação-Especial no campo do seu oponente (exceto durante a Etapa de Dano): você pode escolher 1 monstro que você controla e 1 monstro que seu oponente controla; devolva-os para a mão. \r\nVocê só pode usar este efeito de "Dança de Purificação Mikanko" uma vez por turno.','\r',char(13)),'\n',char(10)),'Retornar ambos os monstros para a mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16435215,'Arrastado para a Cova','Os dois duelistas revelam suas mãos, cada um seleciona 1 card da mão do seu oponente e, depois, você descarta o card selecionado das mãos dos dois duelistas e, depois, os dois duelistas compram 1 card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16437822,'Míssil Flint',replace(replace('Destrua 1 monstro equipado com "Flint". \r\nVocê pode devolver este card para o seu Deck em vez de enviá-lo para o Cemitério depois que ele resolver.','\r',char(13)),'\n',char(10)),'Retornar ao Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16449363,'Sincron de Restolhos',replace(replace('Para uma Invocação-Sincro, você pode substituir este card por qualquer 1 Regulador "Sincron". \r\nVocê só pode usar cada um dos seguintes efeitos de "Sincron de Restolhos" uma vez por turno. \r\nSe você Invocar por Invocação-Sincro um monstro que mencione um Regulador "Sincron" como matéria, este card na sua mão também pode ser usado como matéria. \r\nSe um ou mais monstros que você controla (que mencionem "Guerreiro Sucata" ou que forem um Monstro Sincro com "Guerreiro(a)" em seu nome original) seriam destruídos em batalha ou por um efeito de card, em vez disso, você pode banir este card do seu campo ou Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16469012,'Tevá','Quando este card for Invocado por Invocação-Tributo com sucesso, seu oponente não poderá declarar um ataque durante seu próximo turno.','Restrição de ataque','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16471775,'Partida Ursártica',replace(replace('Descarte 1 card; adicione 2 monstros "Ursártico(a)" do seu Deck à sua mão. \r\nSe você fosse oferecer como Tributo um ou mais monstros para ativar um efeito de um monstro "Ursártico(a)", exceto no turno em que este card foi enviado para o Cemitério, em vez disso, você pode banir este card do seu Cemitério. \r\nVocê só pode usar cada efeito de "Partida Ursártica" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16474916,'Exoirmã Elis',replace(replace('Se você controlar um monstro "Exoirmã": você pode Invocar este card por Invocação-Especial da sua mão e, depois, se você controlar "Exoirmã Estrela", você ganha 800 PV. \r\nSe seu oponente mover um ou mais cards para fora de qualquer Cemitério (exceto durante a Etapa de Dano): você pode Invocar por Invocação-Especial do seu Deck Adicional, 1 Monstro Xyz "Exoirmã" usando este card com a face para cima que você controla como matéria. \r\n(Isso é considerado uma Invocação-Xyz.) \r\nVocê só pode usar cada efeito de "Exoirmã Elis" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Invocação Xyz','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16475472,'Demônio Menor',replace(replace('(Este card deve ser sempre considerado como um card "Arquidemônio".)	\r\nBana quaisquer monstros destruídos em batalha com este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16475473,'Demônio Menor',replace(replace('(Este card deve ser sempre considerado como um card "Arquidemônio".)	\r\nBana quaisquer monstros destruídos em batalha com este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16480084,'Evolssauro Pelta',replace(replace('Quando este card for Invocado por Invocação-Especial pelo efeito de um monstro "Evoltil": Ele ganha 500 de DEF. \r\nSe este card foi Invocado por Invocação-Especial pelo efeito de um monstro "Evoltil" e, depois, ele for destruído em batalha: Você pode adicionar 1 monstro "Evoltil" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16494704,'Advento do Olhos Anômalos',replace(replace('Este card pode ser usado para Invocar por Invocação-Ritual qualquer Monstro de Ritual Dragão da sua mão ou do Cemitério. \r\nVocê também deve oferecer como Tributo Monstros Pêndulo da sua mão ou do campo cuja soma dos Níveis seja igual ou maior que o Nível do Monstro de Ritual que você estiver Invocando por Invocação-Ritual. \r\nSe seu oponente controlar 2 ou mais monstros e você não controlar nenhum monstro, você também pode enviar monstros "Olhos-Anômalos" do seu Deck Adicional para o Cemitério. \r\nVocê só pode ativar 1 "Advento do Olhos Anômalos" por turno.','\r',char(13)),'\n',char(10)),'Usar o Deck Adicional em vez de oferecer Tributo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16507828,'Braquio-raidus','"Rei Rex de Duas Cabeças" + "Dragão Rastejante #2"','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16509007,'Kewl Tune Mix',replace(replace('Se este card no campo seria usado como Matéria Sincro, 1 Regulador na sua mão pode ser usado como 1 das outras matérias. \r\nVocê só pode usar cada um dos seguintes efeitos de "Kewl Tune Mix" uma vez por turno. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 monstro "Kewl Tune" do seu Deck ou Cemitério à sua mão, exceto um monstro de Nível 2. \r\nSe este card for enviado para o Cemitério como Matéria Sincro: você pode escolher 1 monstro que seu oponente controla; destrua-o.','\r',char(13)),'\n',char(10)),'Efeito de busca','Efeito de destruição','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16509093,'Protetor Real',replace(replace('Você pode virar este card para Posição de Defesa com a face para baixo uma vez por turno durante a sua Main Phase. \r\nQuando este card é virado com a face para cima, aumente o ATK e a DEF deste card em 300 pontos até ao fim do turno.','\r',char(13)),'\n',char(10)),'Mudar para Posição de Defesa com a face para baixo','Aumentar ATK/DEF','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16516630,'Asanegra - Boreas, o Afiado','Durante sua Fase Principal 1: você pode banir este card do Cemitério e, depois, escolha 1 monstro "Asanegra" que você controla; se esse monstro atacar neste turno, você não sofre dano de batalha desse ataque, ele não é destruído em batalha e, além disso, depois do cálculo de dano, destrua o monstro do oponente que ele batalhou.','Habilidade adicional','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16527176,'Dragonete-de-Leão de Naturia','1 Regulador de TERRA + 1+ monstros não-Reguladores de TERRA','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16528181,'Sarcófago do Rei',replace(replace('Monstros "Horus" que você controla não podem ser destruídos por efeitos de card que não os escolham como alvo. \r\nVocê pode enviar 1 card da sua mão para o Cemitério; envie 1 monstro "Horus" do seu Deck para o Cemitério. \r\nVocê só pode usar este efeito de "Sarcófago do Rei" até quatro vezes por turno. \r\nUma vez por turno, no começo da Etapa de Dano, se um monstro "Horus" seu batalhar um monstro do oponente: você pode enviar esse monstro do oponente para o Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16550875,'Espada Inzektor - Zektkaliber',replace(replace('Só pode ser equipado a um monstro "Inzektor". \r\nEle ganha 800 de ATK/DEF. \r\nSe este card com a face para cima no campo for enviado para o Cemitério: escolha 1 monstro "Inzektor" no seu Cemitério; adicione o alvo à sua mão.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16556849,'Freed, o Caminhante Corajoso','Uma vez por turno: você pode banir 2 monstros de LUZ do seu Cemitério para escolher 1 monstro com a face para cima no campo com um ATK maior que o deste card com a face para cima; destrua o alvo.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16587243,'Neo Inseto','Um enorme monstro com aparência de inseto que dizem ter vindo de outro planeta. Ele se reúne em enxames.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16589042,'Gaia, o Cavaleiro Impetuoso Célere','Se este for o único card na sua mão, você pode Invocar este card por Invocação-Normal sem oferecer Tributo.','Invocação Normal sem Tributo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16598965,'Vitral de Luz & Trevas',replace(replace('Aplique quaisquer dos seguinte efeitos em sequência, dependendo do(s) \r\nTipo(s) de Monstro(s) de Efeito que você controla.\r\n● Fada: Você pode comprar 3 cards e, depois, coloque 2 cards da sua mão no fundo do seu Deck em qualquer ordem.\r\n● Demônio: Você pode fazer com que seu oponente compre 1 card e, depois, descarte 1 card aleatório e, depois, se ele ainda tiver algum card na mão dele, ele descarta 1 card.	\r\nVocê só pode ativar 1 "Vitral de Luz & Trevas" por turno.','\r',char(13)),'\n',char(10)),'Aplicar 1 efeito','Comprar 1 card?','Fazer seu oponente descartar 1 card?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16605586,'HERÓI do Destino - Negador',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode pegar 1 dos seus monstros "HERÓI do Destino" do seu Deck, Cemitério ou que estiverem banidos, e colocá-lo no topo do seu Deck. \r\nVocê só pode usar este efeito de "HERÓI do Destino - Negador" uma vez por turno. \r\nSe você tiver um monstro "HERÓI do Destino" no seu campo ou no seu Cemitério, que não seja "HERÓI do Destino - Negador": você pode Invocar este card por Invocação-Especial do seu Cemitério. \r\nVocê só pode usar este efeito de "HERÓI do Destino - Negador" uma vez por Duelo.','\r',char(13)),'\n',char(10)),'','','Escolha o card a ser colocada no topo do Deck','Escolher do Deck o card a ser colocado no topo do Deck?','','','','','','','','','','','','');
INSERT INTO texts VALUES(16616620,'Contato','Envie os monstros "Crisálida" que você controla ao Cemitério e Invoque por Invocação-Especial 1 monstro da sua mão ou Deck cujo nome seja mencionado no texto de um desses cards.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16617334,'Camarartista Cabra de Chuva',replace(replace('Quando um card ou efeito for ativado que causaria dano a você (Efeito Rápido): você pode descartar este card; transforme em 0 esse dano de efeito a você. \r\nDurante a Fase Principal (Efeito Rápido): você pode descartar este card e, depois, escolha 1 card "Camarartista" ou "Olhos-Anômalos" que você controla; neste turno, ele não pode ser destruído em batalha ou por efeitos de card.','\r',char(13)),'\n',char(10)),'O dano se torna 0','Não pode ser destruído','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16625614,'Santuário das Trevas',replace(replace('Se um card "Mensagem do Espírito" seria colocado no seu campo com "Tábua do Destino", em vez disso, você pode Invocá-lo por Invocação-Especial como um Monstro Normal (Demônio/TREVAS/Nível 1/ATK 0/DEF 0) e, se isso acontecer, ele não é afetado por efeitos de card, exceto "Tábua do Destino", e não pode ser escolhido como alvo de ataques, mas isso não impede que seu oponente o ataque diretamente. \r\nQuando um monstro do oponente declarar um ataque: lance uma moeda e se o resultado for cara, negue o ataque e, se isso acontecer, cause dano ao seu oponente igual à metade do ATK atual desse monstro do oponente.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial como um Monstro Normal?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16632144,'Peixeiro Pegador','Quando este card causar dano de batalha ao seu oponente em um ataque direto: você pode escolher 1 monstro no seu Cemitério; Invoque-o por Invocação-Especial em Posição de Defesa.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16638212,'D.D. Duende',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) ao banir 1 monstro com a face para cima que você controla. \r\nSe você Invocar deste forma, durante sua próxima Fase de Apoio: devolva o monstro banido para o campo.','\r',char(13)),'\n',char(10)),'Retornar ao Campo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16643334,'Dragão Superestelar da Explosão de Fóton',replace(replace('2 monstros de Nível 4	\r\nSe este card for Invocado por Invocação-Xyz: você pode Invocar por Invocação-Especial 1 monstro "Fóton" da sua mão. \r\nEnquanto este monstro Invocado por Invocação-Xyz estiver no campo, seu oponente não pode escolher monstros que você controla com 2000 ou mais de ATK como alvo de efeitos de card e, além disso, eles não podem ser destruídos pelos efeitos de card do seu oponente. \r\nUma vez por turno do oponente (Efeito Rápido): você pode desassociar 1 matéria deste card e, depois, escolha 1 dos seus "Dragão de Fóton de Olhos das Galáxias" que estiver banido ou no seu Cemitério; Invoque-o por Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16674846,'Força Espiritual','Durante o turno do seu oponente, no cálculo de dano: faça com que o dano de batalha que você sofrer nesta batalha seja reduzido a 0 e, depois, você pode adicionar 1 monstro Regulador do Tipo Guerreiro com 1500 ou menos de DEF do seu Cemitério à sua mão.','Adicionar à sua mão 1 Regulador Guerreiro com 1500 ou menos de DEF do seu Cemitério?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16678947,'Maldição Psíquica','Quando um monstro do Tipo Psíquico que você controla for destruído em batalha com um monstro atacante do oponente e enviado para o Cemitério: escolha o monstro do oponente; destrua o alvo e, se isso acontecer, cause dano ao seu oponente igual ao Nível do monstro do Tipo Psíquico destruído x 300.','Destrua e cause dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16684346,'Cavalo Proxy',replace(replace('Se este card que você controla seria usado como Matéria Link para um monstro Ciberso, você também pode usar 1 monstro Ciberso na sua mão como matéria. \r\nDurante sua Fase Final: você pode banir este card do seu Cemitério e, depois, escolha 2 Monstros Link no seu Cemitério incluindo um Monstro Link Ciberso; devolva-os para o Deck Adicional. \r\nVocê só pode usar cada efeito de "Cavalo Proxy" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16691074,'Dragão Absoluto de Olhos Anômalos',replace(replace('2 monstros de Nível 7	\r\nQuando um monstro de qualquer duelista declarar um ataque: você pode desassociar 1 matéria deste card; negue o ataque e, depois, você pode Invocar por Invocação-Especial 1 monstro "Olhos Anômalos" da sua mão ou do Cemitério. \r\nSe este card Invocado por Invocação-Xyz for enviado para o Cemitério: você pode Invocar por Invocação-Especial 1 monstro "Olhos Anômalos" do seu Deck Adicional, exceto "Dragão Absoluto de Olhos Anômalos". \r\nVocê só pode usar cada efeito de "Dragão Absoluto de Olhos Anômalos" uma vez por turno.','\r',char(13)),'\n',char(10)),'Negar o ataque','Invoque por Invocação Especial do Deck Adicional','Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16693254,'Gishki Avance','Uma vez por turno: você pode escolher 1 monstro "Gishki" do seu Deck e colocá-lo no topo do seu Deck.','Colocar no topo do Deck','Escolha o card a ser colocado no topo do Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16693934,'Besta Quadogmatika',replace(replace('Escolha 1 monstro no seu Cemitério ou banimento; envie para o Cemitério, 1 monstro do seu Deck Adicional ou 1 monstro "Dogmatika" do seu Deck, com ATK igual ou maior que o do alvo e, se isso acontecer, Invoque o alvo por Invocação-Especial. \r\nAté o final do seu próximo turno depois que este card resolver, você não pode Invocar por Invocação-Especial do Deck Adicional. \r\nVocê só pode ativar 1 "Besta Quadogmatika" por turno.','\r',char(13)),'\n',char(10)),'Ativar','O efeito de "Besta Quadogmatika" está sendo aplicado.','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16699558,'Dragão Prateado de Olhos Índigo',replace(replace('2 monstros Dragão de Nível 8	\r\nNão pode atacar diretamente a não ser que este card tenha um Monstro Normal como matéria. \r\nVocê só pode usar cada um dos seguintes efeitos de "Dragão Prateado de Olhos Índigo" uma vez por turno. \r\nSe este card for Invocado por Invocação-Xyz: você pode negar os efeitos de todos os cards com a face para cima que seu oponente controla atualmente. \r\nVocê pode desassociar 1 matéria deste card e, depois, escolha 1 Monstro Normal no seu Cemitério ou banimento; Invoque-o por Invocação-Especial e, se isso acontecer, ele ganha 1000 de ATK.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16708652,'Pó de Ouro Karakuri',replace(replace('Ative apenas durante a Fase de Batalha. \r\nSelecione 2 monstros "Karakuri" com a face para cima em Posição de Ataque. \r\nMude 1 dos monstros selecionados para Posição de Defesa, e o outro ganha ATK igual ao ATK do monstro colocado em Posição de Defesa, até a Fase Final.','\r',char(13)),'\n',char(10)),'Escolha o monstro cuja Posição de Batalha será alterada','Escolha o monstro cujo ATK aumentará','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16719140,'Guerreiro Nêmesis Subterror',replace(replace('Durante o turno de qualquer duelista: você pode enviar 1 monstro "Subterror" do seu Deck para o Cemitério; ofereça este card como Tributo e pelo menos 1 outro monstro até que a soma dos Níveis originais oferecidos como Tributo seja igual ou exceda o Nível desse monstro "Subterror" no Cemitério e, se isso acontecer, Invoque esse monstro por Invocação-Especial com a face para baixo ou para cima em Posição de Defesa. \r\nSe um monstro "Behemoth Subterror" for virado com a face para cima enquanto este card estiver no seu Cemitério: você pode Invocar este card por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Guerreiro Nêmesis Subterror" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16719802,'Dragão da Estrela Brilhante','Quando este card for Invocado por Invocação-Normal: você pode escolher 1 outro monstro com a face para cima no campo; até o final deste turno, aumente o Nível do alvo em 2.','Aumentar o Nível','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16720314,'Poção Sorridente',replace(replace('Se seu oponente controlar um monstro cujo ATK atual seja maior que seu ATK original, enquanto você não controlar nenhum monstro: compre 2 cards. \r\nVocê só pode ativar 1 "Poção Sorridente" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16725505,'Velocidaroide Dado de Olhos Avermelhados','Quando este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 monstro "Velocidaroide" que você controla, exceto "Velocidaroide Dado de Olhos Avermelhados", e declarar um Nível de 1 a 6; ele se torna desse Nível até o final deste turno.','Alterar Nível','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16734927,'Fortificação Ectoplásmica',replace(replace('Ative 1 desses efeitos;\r\n● Se você não controlar nenhum monstro: adicione 1 monstro Zumbi de Nível 6 ou 1 "Chamado dos Esquecidos" do seu Deck à sua mão.\r\n● Monstros Zumbi que você controla ganham 400 de ATK e, depois, você pode comprar cards igual ao número de "Chamado dos Assombrados" que você controla.	\r\nVocê só pode ativar 1 "Fortificação Ectoplásmica" por turno.','\r',char(13)),'\n',char(10)),'Ativar','Adicionar à mão','Aumentar ATK','Comprar 1 card?','','','','','','','','','','','','');
INSERT INTO texts VALUES(16751086,'Lombriga Ardente','Se este card for destruído, envie os 3 cards do topo do Deck do oponente para o Cemitério.','Enviar do Deck para o Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16759958,'Aromági-serafim Angélica',replace(replace('Durante o turno de qualquer duelista: você pode descartar este card e, depois, escolher 1 monstro "Aromági" no seu Cemitério; ganhe PV igual ao ATK do alvo. \r\nEnquanto seus PV forem maiores que o do seu oponente, você controlar um monstro "Aromági" e este card estiver no seu Cemitério: você pode Invocar este card por Invocação-Especial, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar cada efeito de "Aromági-serafim Angélica" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16762927,'Servo do Coveiro','A não ser que seu oponente envie 1 card do topo do Deck dele para o Cemitério, ele não pode declarar um ataque.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16768387,'Grande Olho','VIRE: Veja os 5 cards do topo do seu Deck e, depois, coloque-os no topo do Deck em qualquer ordem.','Revelar o Deck','Escolha a quantidade de cards a revelar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16769305,'Hot Rod Turbo-Maculado GT19',replace(replace('VIRE: Você pode declarar um Nível de 1 a 9; este card se torna desse Nível até o final deste turno.\r\nDepois que este card tenha sido virado com a face para cima, durante qualquer Fase Principal (Efeito Rápido): você pode escolher 1 outro monstro com a face para cima em qualquer campo; imediatamente depois que este efeito resolver, Invoque por Invocação-Sincro 1 monstro usando apenas este card e o alvo. \r\nVocê só pode usar 1 efeito de "Hot Rod Turbo-Maculado GT19" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16780318,'Super All In!',replace(replace('Devolva 1 Monstro Sincro que você controla para o Deck Adicional e, se isso acontecer, Invoque por Invocação-Especial 4 monstros "Flor Cardian" do seu Cemitério e, depois, compre 1 card e mostre-o e, depois, se for um monstro "Flor Cardian", você pode Invocá-lo por Invocação-Especial ignorando suas condições de Invocação. \r\nCaso contrário, destrua tantos monstros que você controla quanto possível e, se você destruiu pelo menos 1, diminua seus PV pela metade. \r\nDurante a Fase Final, se este card estiver no Cemitério porque foi enviado para lá pelo efeito de um monstro "Flor Cardian" neste turno enquanto estava sob sua posse: você pode adicionar 1 Magia/Armadilha do seu Cemitério à sua mão.','\r',char(13)),'\n',char(10)),'Invocação Especial?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16796157,'Besta-Guerreira Puma','Você pode oferecer este card como Tributo; adicione 1 "D.D. Andorinha Estelar Esper" do seu Deck ou Cemitério para a sua mão.','Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16802689,'Flor Cardian Paulownia com Fênix',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro deve ser Invocado por Invocação-Especial (da sua mão) ao oferecer como Tributo 1 monstro "Flor Cardian" de Nível 12, exceto "Flor Cardian Paulownia com Fênix". \r\nSe este card for Invocado por Invocação-Especial: compre 1 card e, se isso acontecer, mostre-o e, depois, você pode Invocá-lo por Invocação-Especial se ele for um monstro "Flor Cardian". \r\nCaso contrário, envie-o para o Cemitério. \r\nUma vez por turno, quando este card causar dano de batalha ao seu oponente: você pode comprar 1 card.','\r',char(13)),'\n',char(10)),'Compre 1 card e revele a ambos os jogadores','Invocação Especial?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16825874,'Menino Excêntrico',replace(replace('Quando usar este card como um Monstro-Matéria Sincro, o outro Monstro-Matéria Sincro é 1 monstro na sua mão. \r\nO Monstro Sincro que usou este card como um Monstro-Matéria Sincro não pode ativar seus efeitos, seus efeitos são negados, e ele é removido de jogo quando for removido do campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16828633,'Genex Reserva','Uma vez por turno, se você controlar outro monstro "Genex", você pode fazer com que o nome deste card se torne "Controlador Genex" até a Fase Final.','Considerar como "Controlador Genex"','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16832845,'Obrigação Final','Se um ou mais monstros com um Nível original de 7 ou mais forem enviados do campo de cada duelista para o Cemitério neste turno: bana tantos monstros dos Cemitérios quanto possível e, depois, você pode Invocar por Invocação-Especial no seu campo o 1 monstro do Tipo Mago de maior Nível dentre esses monstros banidos (em caso de empate, você seleciona).','Invocar por Invocação Especial 1 monstro Mago para o seu Campo?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16849715,'Tela do Clima Trovejante',replace(replace('Monstros de Efeito "do Clima" nas suas Zonas de Monstros Principais da coluna deste card e das colunas adjacentes a ela ganham este efeito.\r\n● No começo da Etapa de Dano, se este card batalhar um monstro do oponente: você pode banir este card; devolva esse monstro do oponente para a mão.	\r\nVocê só pode controlar 1 "Tela do Clima Trovejante".','\r',char(13)),'\n',char(10)),'Retornar um monstro do seu oponente para a mão do dono dele (Tela do Clima Trovejante)','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16886617,'Vaskii Reptiliana',replace(replace('Este card não pode ser Invocado por Invocação-Normal ou Baixado. \r\nEste card não pode ser Invocado por Invocação-Especial, exceto ao oferecer como Tributo 2 monstros com a face para cima com 0 de ATK de qualquer lugar do campo. \r\nUma vez por turno, você pode selecionar e destruir 1 monstro com a face para cima que o seu oponente controla. \r\nSó pode haver 1 "Vaskii Reptiliana" com a face para cima no campo.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16889337,'Aratama',replace(replace('Não pode ser Invocado por Invocação-Especial. \r\nUma vez por turno, durante a Fase Final, se este card foi Invocado por Invocação-Normal ou virado com a face para cima neste turno: devolva este card para a mão. \r\nQuando este card for Invocado por Invocação-Normal ou virado com a face para cima: você pode adicionar 1 monstro Espírito do seu Deck à sua mão, exceto "Aratama".','\r',char(13)),'\n',char(10)),'Retornar à mão','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16893370,'Realidade dos Sonhos de Nemleria, Realizada',replace(replace('Ganha 100 de ATK para cada card com a face para baixo no seu Deck Adicional. \r\nVocê só pode usar cada um dos seguintes efeitos de "Realidade dos Sonhos de Nemleria, Realizada" uma vez por turno. \r\nSe este card estiver na sua mão: você pode escolher 1 monstro que você controla; coloque-o no fundo do Deck e, se isso acontecer, Invoque este card por Invocação-Especial. \r\nSe este card for Invocado por Invocação-Especial: você pode ativar 1 desses efeitos;\r\n● Adicione 1 "Nemleria Sonhadora" do seu Deck ao seu Deck Adicional com a face para cima.\r\n● Coloque 1 outro monstro com a face para cima no campo, com a face para baixo em Posição de Defesa.','\r',char(13)),'\n',char(10)),'','','Adicionar ao Deck Adicional','Mudar para Posição de Defesa com a face para baixo','','','','','','','','','','','','');
INSERT INTO texts VALUES(16898077,'Fortaleza Voadora FOGO DO CÉU',replace(replace('Este card não pode ser Invocado por Invocação-Normal ou Baixado. \r\nEste card não pode ser Invocado por Invocação-Especial, exceto com o efeito de "Reator de Invocação ・FOGO". \r\nUma vez por turno, você pode enviar 1 card da sua mão ao Cemitério para destruir 1 card que seu oponente controla. \r\nUma vez durante cada turno do seu oponente, você pode ativar 1 dos seguintes efeitos:\r\n● Quando seu oponente Invocar um monstro por Invocação-Normal ou Especial, destrua-o e cause 800 de dano ao seu oponente.\r\n● Quando seu oponente Baixar um card, destrua-o e cause 800 de dano ao seu oponente.','\r',char(13)),'\n',char(10)),'Destruir','Destruir um monstro','Destruir 1 card Baixado','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16899564,'Decapitadora Fatal','Uma criatura cruel que já decapitou diversos monstros inimigos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16906241,'Constelar Alrescha','Quando este card for Invocado por Invocação-Normal: você pode Invocar por Invocação-Especial 1 monstro "Constelar" da sua mão com a face para cima em Posição de Defesa.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16908882,'Número 104: Mascarado Vain',replace(replace('3 monstros de Nível 4	\r\nUma vez por turno: você pode desassociar 1 matéria deste card; adicione 1 Magia/Armadilha "Barian" do seu Deck à sua mão.\r\nUm monstro que foi Invocado por Invocação-Xyz usando este card no campo como matéria ganha este efeito.\r\n● Se é Invocado por Invocação-Xyz: ative este efeito; seu oponente pode banir 4 monstros com Atributos diferentes e 1 Magia da Deck dele.	\r\nSe ele não fizer, você bane os 10 cards do topo do Deck dele. \r\nVocê só pode usar este efeito de "Número 104: Mascarado Vain" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Banir','Efeito de banimento (Número 104: Mascarado Vain)','Banir 4 monstros e 1 Card de Magia?','','','','','','','','','','','','');
INSERT INTO texts VALUES(16909657,'Cila Reptiliana',replace(replace('Se este card destruir um monstro com 0 de ATK em batalha, você pode Invocar esse monstro por Invocação-Especial do Cemitério no seu lado do campo com a face para cima em Posição de Defesa. \r\nOs efeitos desse monstro são negados.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16922142,'Tufão Radiante Krosea',replace(replace('Não pode ser destruído em batalha ou por efeitos de card enquanto seu oponente não controlar nenhuma Magia/Armadilha. \r\nVocê só pode usar cada um dos seguintes efeitos de "Tufão Radiante Krosea" uma vez por turno. \r\nSe um Card de Magia Rápida for ativado (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 card "Tufão Radiante" (exceto "Tufão Radiante Krosea") e/ou 1 "Tufão Espacial Místico" do seu Deck e/ou Cemitério à sua mão e, além disso, você não pode Invocar por Invocação-Especial pelo resto deste turno, exceto monstros de VENTO.','\r',char(13)),'\n',char(10)),'Invocação Especial','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16923472,'Caçador de Corda',replace(replace('Você pode oferecer como Tributo 1 monstro "de Corda" com a face para cima, exceto "Caçador de Corda"; envie 1 card aleatório da mão do oponente ao Cemitério. \r\nEste efeito só pode ser usado uma vez, enquanto este card estiver com a face para cima no Campo.','\r',char(13)),'\n',char(10)),'Descartar da mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16926971,'Dragão Sabre Firewall',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro: você pode escolher 1 monstro Ciberso no seu Cemitério ou banimento; adicione-o à sua mão. \r\nVocê pode escolher 1 outro monstro Ciberso que você controla com um Nível; o Nível deste card se torna o desse monstro. \r\nSe este card for enviado para o Cemitério como Matéria Link: você pode adicionar 1 Magia "I.A." do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "Dragão Sabre Firewall" uma vez por turno.','\r',char(13)),'\n',char(10)),'Efeito de recuperação','Alterar o Nível','Adicionar à mão','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16938770,'Respingo Poseidon Xyz',replace(replace('Se você controlar um Monstro Xyz que tenha um Monstro Xyz como matéria: declare 1 Atributo de monstro no campo; destrua todos os monstros no campo com esse Atributo, exceto monstros equipados com uma Magia de Equipamento. \r\nVocê pode banir este card do seu Cemitério e desassociar 1 matéria de um monstro que você controla; Invoque por Invocação-Especial 1 monstro Peixe, Serpente Marinha ou Aqua do seu Cemitério em qualquer campo. \r\nVocê só pode usar 1 efeito de "Respingo Poseidon Xyz" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Destruir 1 monstro','Invocação Especial','Invocar por Invocação Especial no campo do oponente?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16940215,'Veio de Naturia','Quando seu oponente ativar um Card de Magia/Armadilha (Efeito Rápido): você pode oferecer como Tributo 1 monstro "Naturia" e este card; negue a ativação e, se isso acontecer, destrua esse card.','Negar a ativação de um Card de Magia/Armadilha e destruí-lo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16943770,'Besta Fantasma Mecha Aerosguim',replace(replace('Uma vez por turno: você pode banir 1 monstro "Besta Fantasma Mecha" do seu Cemitério, exceto "Besta Fantasma Mecha Aerosguim"; Invoque por Invocação-Especial 1 "Ficha de Besta Fantasma Mecha" (Tipo Máquina/VENTO/Nível 3/ATK 0/DEF 0). \r\nO Nível deste card aumenta em um valor igual à soma dos Níveis de todas as "Fichas de Besta Fantasma Mecha" que você controla. \r\nEnquanto você controlar uma Ficha, este card não pode ser destruído em batalha ou por efeitos de card.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16943771,'Ficha de Besta Fantasma Mecha','Invocado por Especial com o efeito de um monstro "Besta Fantasma Mecha" ou um card relacionado.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16946849,'Serafim Sintético','Sempre que um Card de Armadilha de Resposta for ativado, imediatamente depois que ele resolver, Invoque por Invocação-Especial 1 "Ficha de Serafim Sintético" (Fada/LUZ/Nível 1/ATK 300/DEF 300).','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16946850,'Ficha de Serafim Sintético','Invocado por Especial com o efeito "Serafim Sintético".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16947147,'Velocidaroide Menko','Quando um monstro do oponente declarar um ataque direto enquanto este card estiver na sua mão: você pode Invocar este card por Invocação-Especial em Posição de Ataque e, se isso acontecer, coloque todos os monstros com a face para cima que seu oponente controla em Posição de Defesa.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16955631,'Mimicarniçal Gigante',replace(replace('2 monstros de Nível 1	\r\nSeus monstros "Mimicarniçal" que não sejam Xyz podem atacar diretamente enquanto seu oponente controlar um monstro com a face para baixo. \r\nVocê só pode usar cada um dos seguintes efeitos de "Mimicarniçal Gigante" uma vez por turno. \r\nSe este card for Invocado por Invocação-Xyz: você pode adicionar 1 card "Mimicarniçal" do seu Deck à sua mão. \r\nVocê pode desassociar 1 matéria deste card e, depois, escolha cards com a face para cima no campo até o número de monstros com a face para baixo que seu oponente controla; destrua-os e, se isso acontecer, cause 1000 de dano ao seu oponente para cada card destruído.','\r',char(13)),'\n',char(10)),'','Adicionar à mão','Destruir','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16956455,'Chiron, o Mago','Uma vez por turno: você pode descartar 1 Magia e, depois, escolha 1 Magia/Armadilha que seu oponente controla; destrua o alvo.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16958382,'Dragão do Paradigma Pernicioso',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao banir 1 monstro "Pernicioso(a)" do seu Deck Adicional enquanto "Dragão do Paradigma Pernicioso" não estiver no campo. \r\nSe "Mundo Pernicioso" não estiver no campo, destrua este card. \r\nUma vez por turno: você pode enviar 1 card "Pernicioso(a)" do seu Deck para o Cemitério; devolva 1 dos seus Monstros Sincro banidos de Nível 8 para o Deck Adicional e, depois, você pode Invocar esse monstro por Invocação-Especial do Deck Adicional e, além disso, você só pode atacar com monstros "Pernicioso(a)" pelo resto deste turno.','\r',char(13)),'\n',char(10)),'','Invocação Especial?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16960120,'Dragãozela Cozinheira',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 monstro "Dragãozela" do seu Deck à sua mão, exceto "Dragãozela Cozinheira" e, depois, envie 1 monstro "Dragãozela" da sua mão para o Cemitério. \r\nNo começo da Fase de Batalha: você pode devolver este card para a mão e, se isso acontecer, Invoque por Invocação-Especial 1 monstro "Dragãozela" de Nível 8 da sua mão ou do Cemitério. \r\nVocê só pode usar cada efeito de "Dragãozela Cozinheira" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16960351,'Dragoascensão','Uma vez por turno: você pode oferecer como Tributo 1 monstro do Tipo Dragão que tenha Nível; Invoque por Invocação-Especial do seu Deck 1 monstro do Tipo Wyrm com o mesmo Nível que o Nível original do monstro oferecido como Tributo e, se isso acontecer, quaisquer monstros destruídos em batalha com esse monstro são embaralhados no Deck em vez de serem enviados para o Cemitério.','O efeito de "Dragoascensão" está sendo aplicado.','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16964437,'Horizonte Negro','Quando você sofrer dano de batalha ou de efeito: Invoque por Invocação-Especial 1 monstro de TREVAS do Tipo Mago do seu Deck com ATK menor ou igual ao dano que você sofreu.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16968936,'Treinador Tático dos Seis Samurai',replace(replace('Se você controlar um monstro "Seis Samurai" que não seja "Treinador Tático dos Seis Samurai", você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Treinador Tático dos Seis Samurai" por Invocação-Especial uma vez por turno desta forma. \r\nVocê só pode usar cada um dos seguintes efeitos de "Treinador Tático dos Seis Samurai" uma vez por turno. \r\nSe este card for enviado do campo para o Cemitério: você pode adicionar 1 card "Ataque dos Seis" do seu Deck ou Cemitério à sua mão. \r\nUm monstro "Seis Samurai" que foi Invocado por Invocação-Sincro usando este card ganha este efeito.\r\n● Monstros que seu oponente controla perdem 500 de ATK.','\r',char(13)),'\n',char(10)),'','Efeito de busca','','O efeito de "Treinador Tático dos Seis Samurai" está sendo aplicado.','','','','','','','','','','','','');
INSERT INTO texts VALUES(16970158,'Chamado do Túmulo','Quando seu oponente ativar "Reviver Monstro": negue o efeito desse "Reviver Monstro".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16972957,'Doma, O Anjo do Silêncio','Este anjo governa a morte e administra-a quando necessário.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16984449,'Borboleta Asas em Chamas',replace(replace('Este card é considerado um Monstro Normal enquanto estiver com a face para cima no campo ou no Cemitério. \r\nEnquanto este card for um Monstro Normal no campo, você pode Invocá-lo por Invocação-Normal para fazer com que ele se torne um Monstro de Efeito com este efeito.\r\n● Você pode oferecer este card como Tributo e, depois, escolher 1 monstro Gêmeos no seu Cemitério, exceto "Borboleta Asas em Chamas"; Invoque o alvo por Invocação-Especial e, se isso acontecer, ele se torna um Monstro de Efeito e ganha seus efeitos.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16990348,'Investida da Besta Gladiadora','Escolha cards com a face para cima no campo até o número de monstros "Besta Gladiadora" que você controla com nomes diferentes; destrua-os.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17000165,'Ressalto Reptiliano',replace(replace('Você pode escolher 1 monstro que você controla com 0 de ATK e 1 monstro Réptil de TREVAS no seu Cemitério; destrua esse monstro no campo e, se isso acontecer, Invoque por Invocação-Especial esse outro monstro do Cemitério. \r\nSe seu oponente ativar um efeito de monstro: você pode escolher 1 monstro que seu oponente controla com 0 de ATK; tome o controle dele e, depois, Invoque por Invocação-Especial 1 "Ficha de Reptiliano" (Réptil/TERRA/Nível 1/ATK 0/DEF 0) no campo do seu oponente. \r\nVocê só pode usar cada efeito de "Ressalto Reptiliano" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17000166,'Ficha de Reptiliano','Invocado por Especial com o efeito "Prole Reptiliana" ou um card relacionado.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17008760,'Materriator Ânulo',replace(replace('Desassocie 1 Matéria Xyz de um monstro que você controla e, depois, se a matéria desassociada foi enviada para o seu Cemitério, você pode Baixar esse card no seu campo. \r\nVocê só pode ativar 1 "Materriator Ânulo" por turno.','\r',char(13)),'\n',char(10)),'','Baixar esse card?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17016131,'Orgulho da Saquepatrollha',replace(replace('Se um monstro "Saquepatrollha" seu destruir um monstro do oponente em batalha: compre 1 card. \r\nSe você controlar um monstro "Saquepatrollha": você pode enviar este card com a face para cima do seu campo para o Cemitério e, depois, ative 1 desses efeitos;\r\n● Seu oponente compra 1 card e, depois, olhe a mão dele e envie 1 monstro dali para o Cemitério.\r\n● Olhe o Deck Adicional do seu oponente e envie 1 monstro dali para o Cemitério.	\r\nVocê só pode usar cada efeito de "Orgulho da Saquepatrollha" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Enviar 1 card da sua mão para o Cemitério','Enviar do Deck Adicional para o Cemitério','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17016362,'Camaramágico Mago Trapezista',replace(replace('2 monstros do Tipo Mago de Nível 4	\r\nVocê nunca sofre dano se o valor do dano for menor ou igual que o ATK deste card. \r\nUma vez por turno, durante a Fase Principal 1 de qualquer duelista: você pode desassociar 1 Matéria Xyz deste card e, depois, escolher 1 monstro com a face para cima em Posição de Ataque controlado pelo duelista do turno (que não seja este card); ele pode realizar um segundo ataque durante cada Fase de Batalha neste turno e, além disso, destrua-o no final da Fase de Batalha. \r\nSe este card for destruído em batalha e enviado para o Cemitério, ou se este card em sua posse for destruído por um efeito de card do oponente e enviado para o seu Cemitério: você pode Invocar por Invocação-Especial 1 monstro "Camaramágico" do Deck.','\r',char(13)),'\n',char(10)),'Ataques múltiplos','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17020474,'Asutraja Susanoo',replace(replace('1 Regulador + 1+ não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro: você pode banir qualquer número de Armadilhas do seu Cemitério; bana aquela quantia de cards no campo.\r\nDurante a Fase Final: você pode escolher até 2 monstros "Asutra" e/ou Armadilhas "Asutra" no seu Cemitério e/ou banimento; para cada um deles, adicione-o à sua mão ou Baixe-o, então se você escolheu 2 cards, retorne este card para o Deck Adicional.\r\nVocê só pode usar cada um dos efeitos de "Asutraja Susanoo" uma vez por turno.','\r',char(13)),'\n',char(10)),'Destruir','Recuperar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17021204,'Aranha Mãe','Se você tiver apenas monstros do Tipo Inseto no seu Cemitério, você pode enviar 2 monstros com a face para cima em Posição de Defesa que seu oponente controla ao Cemitério e Invocar este card por Invocação-Especial da sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17032740,'Neos Caos, o HERÓI do Elemento',replace(replace('"Neos, o HERÓI do Elemento" + "Pantera Negra Neoespacial" + "Musgo Brilhante Neoespacial"	\r\nPrimeiro deve ser Invocado por Invocação-Especial (do seu Deck Adicional) ao embaralhar os cards acima que você controla no Deck. \r\nUma vez por turno, durante a Fase Final: embaralhe este card no Deck Adicional e, se isso acontecer, Baixe todos os monstros com a face para cima no campo. \r\nUma vez por turno, durante sua Fase Principal 1: você pode lançar uma moeda 3 vezes.\r\n● 3 Caras: Destrua todos os monstros que seu oponente controla.\r\n● 2 Caras: Pelo resto deste turno, os efeitos de todos os monstros com a face para cima que seu oponente controla são negados.\r\n● 1 Cara: Devolva todos os monstros que você controla para a mão.','\r',char(13)),'\n',char(10)),'Retornar ao Deck','Jogar uma moeda','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17045014,'Evolssauro Diplo','Quando este card for Invocado por Invocação-Especial pelo efeito de um monstro "Evoltil": Escolha 1 Card de Magia/Armadilha que seu oponente controla; destrua o alvo.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17052477,'Tesouro Protegido',replace(replace('Ative este card ao descartar 5 cards; compre 2 cards. \r\nEnquanto este card estiver no campo, compre 2 cards em vez de 1 em sua compra normal durante sua Fase de Compra.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17063599,'Zéfiro Celeste - Miradora',replace(replace('A ativação e o efeito dos efeitos deste card não podem ser negados. \r\nSe seu oponente Invocar um ou mais monstros com 2000 ou mais de ATK por Invocação-Especial do Deck Adicional (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe este card for Invocado por Invocação-Especial da mão: você pode escolher 1 monstro com a face para cima do oponente que foi Invocado por Invocação-Especial do Deck Adicional; nenhum duelista pode ativar os efeitos desse monstro enquanto este monstro estiver com a face para cima no campo. \r\nVocê só pode usar cada efeito de "Zéfiro Celeste - Miradora" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17078030,'Muro de Luz Reveladora',replace(replace('Quando você activar este card, pague um número de Life Points múltiplo de 1000. \r\nNenhum dos monstros do seu adversário, com um ATK igual ou menor do que o número de Life Points que você pagou, pode atacar.','\r',char(13)),'\n',char(10)),'Escolha os Pontos de Vida a pagar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17080584,'Abisrena, o Espírito Atlante',replace(replace('(Este card deve ser sempre considerado como um card "Sirena".)	\r\nVocê pode oferecer este card como Tributo da sua mão e 1 monstro "Atlante" ou "Sirena" da sua mão ou do campo; pegue 1 monstro Peixe, Serpente Marinha ou Aqua de Nível 7 do seu Deck e adicione-o à sua mão ou Invoque-o por Invocação-Especial e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto monstros de ÁGUA. \r\nDurante o turno do seu oponente (Efeito Rápido): você pode banir este card do seu Cemitério e descartar 1 card para o Cemitério; compre 1 card. \r\nVocê só pode usar cada efeito de "Abisrena, o Espírito Atlante" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Comprar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17086528,'Mago Xiangsheng',replace(replace('Escala de Pêndulo = 8\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno: você pode escolher 1 Monstro Xyz com a face para cima que você controla e 1 monstro de Nível 5 ou mais que você controla; até o final deste turno, a Classe desse Monstro Xyz se torna igual ao Nível desse monstro de Nível 5 ou mais (mesmo que este card deixe o campo). \r\nEnquanto você controlar mais cards que o seu oponente, a Escala de Pêndulo deste card se torna 4.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSeu oponente não sofre dano de batalha de ataques envolvendo este card. \r\nUma vez por turno: você pode escolher 1 outro monstro com a face para cima que você controla; até o final deste turno, o ATK deste card se torna igual ao ATK atual desse monstro.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17092736,'Telescópio Antigo',replace(replace('Veja os 5 cards do topo do Deck do seu adversário. \r\nDevolva os cards para o Deck na mesma ordem.','\r',char(13)),'\n',char(10)),'Escolha a quantidade a ver','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17115745,'Yormungarde','Uma serpente extremamente longa que vive no mundo dos mitos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17129783,'Constelar Leonis',replace(replace('Durante sua Fase Principal, você pode Invocar por Invocação-Normal 1 monstro "Constelar" em adição à sua Invocação-Normal/Baixar padrão. \r\n(Você só pode se aproveitar deste efeito uma vez por turno.)','\r',char(13)),'\n',char(10)),'Invocar pelo efeito de "Constelar Leonis"','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17132130,'HERÓI do Destino - Dogma',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao oferecer como Tributo 3 monstros, incluindo pelo menos 1 monstro "HERÓI do Destino". \r\nUma vez por turno, se você ainda controlar este card com a face para cima durante a próxima Fase de Apoio do seu oponente depois que você Invocou por Invocação-Especial desta forma: diminua pela metade os PV do seu oponente.','\r',char(13)),'\n',char(10)),'Invocação Especial','Reduzir os PV pela metade','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17141718,'Flor Cardian Grama da Zebra',replace(replace('Enquanto você controlar um monstro "Flor Cardian" de Nível 7 ou menos: você pode Invocar este card por Invocação-Especial da sua mão e, além disso, você não pode Invocar monstros por Invocação-Normal ou Especial pelo resto deste turno, exceto monstros "Flor Cardian". \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode revelar qualquer número de monstros "Flor Cardian" na sua mão, embaralhe-os no Deck e, depois, compre o mesmo número de cards.','\r',char(13)),'\n',char(10)),'Invocação Especial','Retornar sua mão para o Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17151328,'Tempestades de Chamas Sobre Atlântida',replace(replace('Ative 1 desses efeitos;\r\n● Descarte 1 monstro de ÁGUA para o Cemitério e, depois, escolha 1 monstro com a face para cima que seu oponente controla; destrua-o.\r\n● Destrua 1 monstro de FOGO na sua mão e, depois, você pode comprar 1 card.	\r\nSe somente seu oponente controlar um monstro: você pode banir este card do seu Cemitério e, depois, escolha 1 monstro de ÁGUA ou de FOGO de Nível 7 ou 8 no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Tempestades de Chamas Sobre Atlântida" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar','Invocação Especial','Destruir 1 monstro com a face para cima que seu oponente controla','Destruir 1 monstro de FOGO na sua mão','Comprar 1 card?','','','','','','','','','','','');
INSERT INTO texts VALUES(17170970,'Urso Branco com Armadura',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial enquanto um Monstro Sincro estiver no campo: você pode escolher 1 Magia de Campo no seu Cemitério; adicione-a à sua mão. \r\nSe este card for destruído em batalha e enviado para o Cemitério, ou se este card em sua posse for destruído por um efeito de card do oponente e enviado para o seu Cemitério: você pode Invocar por Invocação-Especial 1 monstro Besta de Nível 4 ou menos do seu Deck ou Cemitério, exceto "Urso Branco com Armadura". \r\nVocê só pode usar cada efeito de "Urso Branco com Armadura" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17178486,'Equalizador de Vida',replace(replace('Ative apenas quando a diferença entre os PV de ambos os duelistas for de 8000 ou mais. \r\nOs PV de ambos os duelistas se tornam 3000.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17183908,'Caminho Yang Zing',replace(replace('Escolha 3 monstros "Yang Zing" no seu Cemitério; embaralhe os 3 no Deck e, depois, compre 2 cards. \r\nVocê só pode ativar 1 "Caminho Yang Zing" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17185260,'Martelo do Inferno','Quando este card destruir um monstro do oponente e enviá-lo ao Cemitério como resultado da batalha, você pode selecionar 1 monstro com a face para cima no lado do campo do oponente, vire-o com a face para baixo em Posição de Defesa.','Mudar para Posição de Defesa com a face para baixo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17188206,'Lâmina Lambda R.B.',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode enviar 1 card "R.B." do seu Deck para o Cemitério, exceto "Lâmina Lambda R.B.". \r\nDurante a Fase Principal do seu oponente, se este card estiver linkado a um Monstro Link "R.B." (Efeito Rápido): você pode pagar 1400 PV e, depois, escolha 1 monstro que seu oponente controla; destrua este card e, se isso acontecer, tome o controle desse monstro, mas destrua-o durante a Fase Final. \r\nVocê só pode usar cada efeito de "Lâmina Lambda R.B." uma vez por turno.','\r',char(13)),'\n',char(10)),'Enviar para o Cemitério','Controlar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17189532,'Rufião Fantasma','Se este card no campo for destruído e enviado ao Cemitério: Você pode adicionar 2 cards "Rufião" do seu Deck à sua mão.','Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17189677,'Chuva de Serpentes','Descarte 1 card; envie 4 monstros Réptil do seu Deck para o Cemitério.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17192817,'Beemote Derretido','Um gigante nascido do magma, ataca com um soco de magma.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17194258,'Recrutamento Fusão',replace(replace('Revele 1 Monstro de Fusão no seu Deck Adicional e adicione 1 das Matérias de Fusão cujo nome esteja especificamente listado nesse card do seu Deck ou Cemitério à sua mão e, se isso acontecer, pelo resto deste turno, depois que este card resolver, você não pode Invocar por Invocação-Normal/Baixar ou por Invocação-Especial monstros com o nome do monstro adicionado e, além disso, seus monstros com esse nome não podem ativar seus efeitos. \r\nVocê só pode ativar 1 "Recrutamento Fusão" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17197110,'Ventos Sobre a Barreira de Gelo',replace(replace('Ofereça como Tributo qualquer número de monstros "Barreira de Gelo"; Invoque por Invocação-Especial do seu Deck esse mesmo número de monstros "Barreira de Gelo" de Nível 4 ou menos com nomes diferentes uns dos outros. \r\nDurante sua Fase Principal, exceto no turno em que este card foi enviado para o Cemitério: você pode banir este card do seu Cemitério e, depois, escolha 1 dos seus monstros "Barreira de Gelo" que estiverem banidos ou no seu Cemitério; adicione-o à sua mão. \r\nVocê só pode usar cada efeito de "Ventos Sobre a Barreira de Gelo" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17201174,'Tubarão Martelo','Uma vez por turno: você pode reduzir o Nível deste card em 1 e, se isso acontecer, Invocar por Invocação-Especial 1 monstro de ÁGUA de Nível 3 ou menos da sua mão.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17201951,'Guerreiro Veloz Absoluto',replace(replace('Monstros que você controla que mencionem "Guerreiro Sucata" ou que forem um Monstro Sincro com "Guerreiro(a)" em seu nome original ganham 900 de ATK apenas durante sua Fase de Batalha. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 "Sucata Sincron" ou 1 Magia/Armadilha que mencione "Guerreiro Sucata" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Guerreiro Veloz Absoluto" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17209452,'Kewl Tune Botões',replace(replace('Se este card no campo seria usado como Matéria Sincro, 1 Regulador na sua mão pode ser usado como 1 das outras matérias. \r\nVocê só pode usar cada um dos seguintes efeitos de "Kewl Tune Botões" uma vez por turno. \r\nVocê pode revelar este card e 1 Regulador na sua mão; imediatamente depois que este efeito resolver, Invoque por Invocação-Normal 1 Regulador. \r\nSe este card for enviado para o Cemitério como Matéria Sincro: você pode ativar 1 desses efeitos;\r\n● Coloque 1 card do Cemitério do seu oponente no fundo do Deck dele.\r\n● Olhe a mão do seu oponente e, depois, você pode adicionar 1 Magia/Armadilha "Kewl Tune" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Invocar','Enviado para o Cemitério como Matéria Sincro','Retornar 1 card do Cemitério do seu oponente para o fundo do Deck','Revele a mão do seu oponente','Adicionar à sua mão um Card de Magia/Armadilha?','','','','','','','','','','','');
INSERT INTO texts VALUES(17214465,'Dama da Água','Enquanto não houver Magias de Campo com a face para cima, o campo é considerado como "Umi".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17217034,'Manobra Combinada - Engajar Zero!',replace(replace('2 monstros de LUZ e/ou de TREVAS	\r\n(Este card deve ser sempre considerado como um card "Força Celeste - Ás".)	\r\nVocê só pode Invocar um ou mais "Manobra Combinada - Engajar Zero!" por Invocação-Especial uma vez por turno. \r\nNão pode ser usado como Matéria Link. \r\nSe este card for Invocado por Invocação-Especial: você pode escolher 1 monstro no campo com 2500 ou mais de ATK; negue seus efeitos até o final deste turno. \r\nNo começo da Etapa de Dano, se este card atacar, enquanto você tiver "Força Celeste - Ás - Raye" e "Força Celeste - Ás - Roze" no seu Cemitério: você pode destruir todos os monstros que seu oponente controla.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17228908,'Mundo Perdido',replace(replace('Todos os monstros no campo perdem 500 de ATK/DEF, exceto monstros Dinossauro. \r\nUma vez por turno, se um monstro Dinossauro for Invocado por Invocação-Normal ou Especial (exceto durante a Etapa de Dano): você pode Invocar por Invocação-Especial 1 "Ficha de Jurraovo" (Dinossauro/TERRA/Nível 1/ATK 0/DEF 0) em Posição de Defesa no campo do seu oponente. \r\nEnquanto seu oponente controlar uma Ficha, ele não pode escolher monstros no campo como alvo de efeitos de card, exceto Fichas. \r\nUma vez por turno, se um ou mais Monstros Normais no campo seriam destruídos em batalha ou por um efeito de card, em vez disso, você pode destruir esse mesmo número de monstros Dinossauro na sua mão e/ou no Deck.','\r',char(13)),'\n',char(10)),'Invocar uma Ficha por Invocação Especial','Usar o efeito de "Mundo Perdido" em vez de ser destruído?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17228909,'Ficha de Jurraovo','Invocada por Invocação-Especial com o efeito "Mundo Perdido".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17236839,'Fusão Cintilante',replace(replace('Invoque por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional, usando monstros que você controla como Matéria de Fusão. \r\nDestrua-o durante a Fase Final.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17238333,'Mísero Fantasma do Sótão','Um monstro inofensivo encontrado espreitando em quase todos os sótãos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17241370,'Gishki Natalia',replace(replace('Não pode ser Invocado por Invocação-Especial. \r\nDurante a Fase Final do turno em que este card foi Invocado por Invocação-Normal ou virado com a face para cima: volte-o para a mão. \r\nQuando este card for Invocado por Invocação-Normal ou virado com a face para cima: você pode escolher 1 monstro "Gishki" em seu Cemitério; volte o alvo para o topo do Deck.','\r',char(13)),'\n',char(10)),'Retornar à mão','Retornar ao Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17241941,'Giclope Gigatrovão',replace(replace('Escala de Pêndulo = 5\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno: você pode escolher 1 Monstro Pêndulo que você controla e 1 monstro que seu oponente controla; mude suas posições de batalha.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe este card, Invocado por Invocação-Especial do Deck Adicional, for usado como Matéria Sincro, bana-o. \r\nSe este card for Invocado por Invocação-Normal: você pode mudar sua posição de batalha. \r\nVocê só pode usar cada um dos seguintes efeitos de "Giclope Gigatrovão" uma vez por turno. \r\nSe a posição de batalha deste card for mudada: você pode escolher 1 Magia/Armadilha com a face para cima no campo; destrua-a. \r\nSe este card for destruído na Zona de Pêndulo: você pode devolver 1 card da sua Zona de Pêndulo para a mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17242022,'Dragão Negro de Olhos Vermelhos Excedente',replace(replace('"Dragão Negro de Olhos Vermelhos" + 1 monstro que mencione "Mago do Tempo Sombrio"	\r\nDeve ser Invocado por Invocação-Fusão ou Invocação-Especial (do seu Deck Adicional) oferecendo como Tributo 1 monstro em qualquer campo com a face para cima durante o turno que um ou mais monstros forem destruídos pelo efeito de "Mago do Tempo Sombrio". \r\nVocê só pode Invocar por Invocação-Especial "Dragão Negro de Olhos Vermelhos Excedente" uma vez por turno essa forma, não importa qual método usar.\r\nSe este card for Invocado por Invocação-Especial: você pode Invocar por Invocação-Especial 1 monstro de Nível 8 ou menor da sua mão ou Cemitério.\r\nNão é afetado pelos efeitos ativados dos monstros e efeitos de Magias do seu oponente.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17242023,'Dragão Negro de Olhos Vermelhos Excedente',replace(replace('"Dragão Negro de Olhos Vermelhos" + 1 monstro que mencione "Mago do Tempo Sombrio"	\r\nDeve ser Invocado por Invocação-Fusão ou Invocação-Especial (do seu Deck Adicional) oferecendo como Tributo 1 monstro em qualquer campo com a face para cima durante o turno que um ou mais monstros forem destruídos pelo efeito de "Mago do Tempo Sombrio". \r\nVocê só pode Invocar por Invocação-Especial "Dragão Negro de Olhos Vermelhos Excedente" uma vez por turno essa forma, não importa qual método usar.\r\nSe este card for Invocado por Invocação-Especial: você pode Invocar por Invocação-Especial 1 monstro de Nível 8 ou menor da sua mão ou Cemitério.\r\nNão é afetado pelos efeitos ativados dos monstros e efeitos de Magias do seu oponente.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17243896,'Aranha de Chão','Uma vez por turno, se você controlar este monstro com a face para cima em Posição de Defesa quando seu oponente Invocar um ou mais monstros por Invocação-Normal ou Especial, você pode mudar esses monstros para Posição de Defesa.','Mudar para Posição de Defesa','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17255673,'Portão Celestial de Mikanko',replace(replace('Enquanto você controlar um monstro que estiver equipado com um Card de Equipamento, todos os monstros que seu oponente controla que podem atacar devem atacar monstros equipados com Cards de Equipamento. \r\nSe um monstro "Mikanko" seu batalhar, seu oponente não pode ativar cards ou efeitos até o final da Etapa de Dano. \r\nNo final da Etapa de Dano, se um monstro "Mikanko" seu atacou: você pode enviar 1 Card de Equipamento que você controla para o Cemitério; ele pode realizar outro ataque contra um monstro em seguida.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17257342,'Diana, o Espírito da Luz',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro deve ser Invocado por Invocação-Especial (da sua mão) ao banir 1 monstro de LUZ do seu Cemitério. \r\nUma vez por turno, durante a Fase Final do seu oponente: ganhe 1000 PV.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17259470,'Mestre Zumbi',replace(replace('Uma vez por turno: você pode enviar 1 monstro da sua mão para o Cemitério e, depois, escolha 1 monstro Zumbi de Nível 4 ou menos em qualquer Cemitério; Invoque o alvo por Invocação-Especial. \r\nEste monstro deve estar com a face para cima no campo para ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17264592,'U.A. Reboteador Rival',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) ao devolver 1 monstro "U.A." que você controla para a mão, exceto "U.A. Reboteador Rival". \r\nVocê só pode Invocar "U.A. Reboteador Rival" por Invocação-Especial uma vez por turno desta forma. \r\nSe este card for Invocado por Invocação-Especial durante o turno do seu oponente ou Invocado por Invocação-Normal: você pode Invocar por Invocação-Especial 1 monstro "U.A." da sua mão ou Cemitério, exceto "U.A. Reboteador Rival". \r\nVocê só pode usar este efeito de "U.A. Reboteador Rival" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17266660,'Arauto da Luz Laranja','Quando seu oponente ativar um efeito de monstro (Efeito Rápido): você pode enviar este card e 1 outro monstro Fada da sua mão para o Cemitério; negue a ativação e, se isso acontecer, destrua-o.','Negar a ativação do efeito de um Monstro de Efeito e destruí-lo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17269895,'Ressonância do Rei',replace(replace('Durante o turno no qual seu oponente tenha Invocado 10 ou mais monstros por Invocação-Especial, nenhum duelista pode ativar cards ou efeitos em resposta à ativação deste card. \r\nAplique os seguintes efeitos em sequência, de acordo com o número de monstros que seu oponente Invocou por Invocação-Especial neste turno.\r\n● 1+: Invoque por Invocação-Especial 1 Monstro Sincro de TREVAS do seu Cemitério ou banimento.\r\n● 3+: Até o final do seu próximo turno, cada "Dragão Vermelho Arquidemônio" na sua Zona de Monstros não é afetado pelos efeitos ativados do seu oponente.\r\n● 5+: Coloque todos os monstros do seu oponente com a face para baixo em Posição de Defesa.	\r\nVocê só pode ativar 1 "Ressonância do Rei" por turno.','\r',char(13)),'\n',char(10)),'Ativar','O efeito de "Ressonância do Rei" está sendo aplicado.','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17272964,'Mannadium Destemida',replace(replace('Se você controlar "Visas Starfrost" ou um monstro com 1500 de ATK/2100 de DEF, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Mannadium Destemida" por Invocação-Especial uma vez por turno desta forma. \r\nSe este card for destruído em batalha ou por um efeito de card: você pode Invocar por Invocação-Especial 1 "Mannadium Destemida" do seu Deck e, além disso, durante a Fase de Batalha neste turno, Monstros Sincro que você controla ganham 500 de ATK.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17285476,'Mosquito de Naturia',replace(replace('Enquanto você controlar outro(s) monstro(s) "Naturia" com a face para cima, seu oponente não pode selecionar este card como alvo de um ataque. \r\nSeu oponente sofre qualquer Dano de Batalha que você sofreria de batalhas envolvendo um monstro "Naturia" com a face para cima que você controla, exceto este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17286057,'Hélios Trismegisto',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) ao oferecer como Tributo 1 "Hélios Dismegisto". \r\nO ATK/DEF deste card se torna o número de monstros banidos x 300. \r\nDepois que este card atacar, se seu oponente controlar um monstro, este card pode realizar um segundo ataque em seguida. \r\nDurante a Fase Final, se este card estiver no Cemitério porque foi destruído em batalha e enviado para lá neste turno: você pode Invocar este card por Invocação-Especial e ele ganha 500 de ATK/DEF.','\r',char(13)),'\n',char(10)),'Invocação Especial','Continuar atacando','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17313545,'Golem Cérebro',replace(replace('Efeitos de monstros de LUZ com a face para cima são negados. \r\nSe este card destruir um monstro de LUZ em batalha, ele pode atacar mais uma vez em seguida.','\r',char(13)),'\n',char(10)),'Continuar atacando','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17315396,'Supay, a Andarilha do Crepúsculo',replace(replace('Você pode descartar 1 card; Invoque este card por Invocação-Especial da sua mão em Posição de Defesa e, depois, você pode Invocar por Invocação-Especial 1 "Supay" da sua mão ou do Deck. \r\nVocê não pode Invocar monstros por Invocação-Especial do Deck Adicional no turno em que ativar este efeito, exceto Monstros Sincro. \r\nVocê só pode usar este efeito de "Supay, a Andarilha do Crepúsculo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Invocar "Supay" por Invocação Especial?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17322533,'Pouso Certeiro',replace(replace('Se exatamente 1 monstro for Invocado por Invocação-Especial da mão para o seu campo (exceto durante a Etapa de Dano): você pode comprar 1 card. \r\nVocê só pode usar este efeito de "Pouso Certeiro" uma vez por turno. \r\nDurante sua Fase Final, se você não comprou um card devido a este efeito neste turno, envie este card para o Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17328157,'Velocidaroide Cavalo de Estacas',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode Invocar por Invocação-Especial 1 monstro "Velocidaroide" de Nível 4 ou menos da sua mão. \r\nDurante sua Fase Principal, exceto no turno em que este card foi enviado para o Cemitério: você pode banir este card do seu Cemitério; envie 1 monstro de VENTO do seu Deck para o Cemitério. \r\nVocê só pode usar este efeito de "Velocidaroide Cavalo de Estacas" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17330916,'Camarartista Maclado',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nA não ser que você tenha um card "Camarartista" na sua outra Zona de Pêndulo, a Escala de Pêndulo deste card se torna 4. \r\nDurante sua Fase Principal, se este card foi ativado neste turno: você pode adicionar 1 monstro "Camarartista" de Nível 4 ou menos do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Camarartista Maclado" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nVocê pode descartar este card; revele 1 monstro "Camarartista" ou "Olhos Anômalos" na sua mão e, se isso acontecer, pelo resto deste turno, reduza em 1 o Nível dos monstros na sua mão com esse nome (mesmo depois que eles forem Invocados/Baixados).','\r',char(13)),'\n',char(10)),'Reduzir o Nível','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17350692,'Yomagna, o Fantasma do Fogo',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro deve ser Invocado por Invocação-Especial (da sua mão) ao embaralhar 3 cards do mesmo tipo (Monstro, Magia ou Armadilha) do seu Cemitério no Deck/Deck Adicional. \r\nSe este card for Invocado por Invocação-Especial: você pode declarar 1 Tipo de Monstro; este card se torna desse Tipo até o final deste turno. \r\nDurante sua Fase Principal: você pode Invocar por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional, usando monstros em qualquer campo, incluindo este card. \r\nVocê só pode usar cada efeito de "Yomagna, o Fantasma do Fogo" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Alterar o Tipo','Efeito de Fusão','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17358176,'Lady da Fé','Aquieta as almas dos outros entoando uma mágica misteriosa.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17363041,'Crisálida de Colibri','Você pode oferecer este card como Tributo enquanto "Neo Espaço" estiver no campo para Invocar por Invocação-Especial 1 "Beija-flor do Ar Neoespacial" da sua mão ou Deck.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17375316,'Confiscar',replace(replace('Pague 1000 PV. \r\nOlhe a mão do seu oponente, selecione 1 card daí e descarte esse card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17377751,'Asanegra - Gram, a Estrela Brilhante',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nPrimeiro deve ser Invocado por Invocação-Sincro. \r\nQuando este card for Invocado por Invocação-Sincro: você pode Invocar por Invocação-Especial 1 monstro não-Regulador "Asanegra" de Nível 4 ou menos da sua mão, mas seus efeitos são negados.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17382973,'Guricoricó dos Travesso-Guris',replace(replace('2 monstros "Travesso-Guris"	\r\nSe este card for Invocado por Invocação-Link: você pode adicionar 1 Magia/Armadilha "Travesso-Guris" do seu Deck à sua mão. \r\nVocê pode oferecer este card como Tributo e, depois, escolha 2 cards "Travesso-Guris" com nomes diferentes no seu Cemitério, exceto Monstros Link; adicione-os à sua mão. \r\nVocê só pode usar cada efeito de "Guricoricó dos Travesso-Guris" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17390179,'Cavaleiro Brilhante',replace(replace('Escala de Pêndulo = 7\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nO poder do pêndulo irradia intensamente deste cavaleiro brilhante.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17393207,'Comandante do Coveiro','Você pode descartar este card para o Cemitério; adicione 1 "Necro-Vale" do seu Deck à sua mão.','Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17412721,'Entidade Anciã Norden',replace(replace('1 Monstro Sincro ou Xyz + 1 Monstro Sincro ou Xyz	\r\nQuando este card for Invocado por Invocação-Especial: você pode escolher 1 monstro de Nível 4 ou menos no seu Cemitério; Invoque-o por Invocação-Especial, mas seus efeitos são negados e, além disso, bana-o quando este card deixar o campo.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17415895,'Corte Vulcânico',replace(replace('Uma vez por turno, você pode causar 500 de dano ao seu oponente. \r\nSe você ativar este efeito, este card não pode atacar durante este turno.','\r',char(13)),'\n',char(10)),'Cause 500 de dano ao seu oponente','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17418744,'Santuário de Fóton',replace(replace('Invoque por Invocação-Especial 2 "Ficha de Fóton" (Trovão/LUZ/Nível 4/ATK 2000/DEF 0) em Posição de Defesa. \r\nEssas Fichas não podem atacar nem ser usadas como Matéria Sincro. \r\nVocê não pode Invocar outros monstros no turno em que ativar este card, exceto monstros de LUZ.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17418745,'Ficha de Fóton','Invocado por Especial com o efeito "Santuário de Fóton". Esta Ficha não pode atacar nem ser usada como Monstro-Matéria Sincro.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17427333,'C.E.M.','Ofereça como Tributo 1 monstro Máquina e, depois, escolha 1 card no campo para cada 1000 de ATK original do monstro oferecido como Tributo; destrua esses cards.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17441953,'Guaxinim Tartaruga','Um guaxinim astuto protegido por uma casca de tartaruga sólida, ataca com artimanha.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17444133,'Cavalo-marinho de Kaiser','Este card pode ser considerado como 2 Tributos para a Invocação-Tributo de um monstro de LUZ.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17449108,'O Nobre da Exterminação','Escolha 1 Magia/Armadilha com a face para baixo no campo; destrua o alvo e, se isso acontecer, bana-o e, depois, se era uma Armadilha, cada duelista revela seu Deck Principal e, depois, bane todos os cards dali com o nome desse card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17462320,'Elegia do Reino',replace(replace('Adicione 1 monstro "Veda" do seu Deck à sua mão. \r\nSe um ou mais Reguladores com a face para cima que você controla forem destruídos em batalha ou por um efeito de card enquanto "Visas Starfrost" estiver no campo e este card estiver no seu Cemitério: você pode banir este card e, depois, escolha 1 desses monstros destruídos; adicione-o à sua mão. \r\nVocê só pode usar este efeito de "Elegia do Reino" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17465972,'Asanegra - Austro, o Vento do Sul',replace(replace('Não pode ser Invocado por Invocação-Especial. \r\nQuando este card for Invocado por Invocação-Normal: você pode escolher 1 dos seus monstros "Asanegra" banidos de Nível 4 ou menos; Invoque-o por Invocação-Especial em Posição de Defesa. \r\nVocê pode banir este card do Cemitério para ativar 1 dos seguintes efeitos;\r\n● Coloque um ou mais Marcadores de Pena Negra em 1 "Dragão de Asas Negras" que você controla, igual ao número de cards que seu oponente controla.\r\n● Coloque 1 Marcador de Cunha em cada monstro com a face para cima que seu oponente controla que não tenha um.','\r',char(13)),'\n',char(10)),'','Colocar um marcador em "Dragão de Asas Negras"','Colocar marcadores em todos os monstros que seu oponente controla','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17469113,'Avida, a Reconstrutora de Mundos',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao ter pelo menos 8 ou mais Monstros Link com nomes diferentes no campo e/ou nos Cemitérios. \r\nVocê não pode Invocar outros monstros por Invocação-Especial no turno em que Invocar este card por Invocação-Especial. \r\nA Invocação-Especial deste card não pode ser negada. \r\nSe este card for Invocado por Invocação-Especial: embaralhe nos Decks todos os outros monstros que estiverem banidos, no campo e nos Cemitérios. \r\nNenhum duelista pode ativar cards ou efeitos em resposta à ativação deste efeito.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17473466,'Nervedo, o Patrono do Poder Besta Sombria',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nVocê pode negar um efeito de monstro ativado pelo seu oponente em resposta à ativação de um efeito de monstro "Patrono(a) do Poder" ou "Artmage" e, depois, destrua este card. \r\nVocê só pode usar este efeito de "Nervedo, o Patrono do Poder Besta Sombria" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\n(Este card deve ser sempre considerado como um card "Artmage".)	\r\nVocê pode banir os 3 cards do topo do seu Deck, com a face para baixo; destrua este card e, se isso acontecer, Invoque por Invocação-Especial 1 "Nerva, a Patrona do Poder da Criação" do seu Deck Adicional (isso é considerado uma Invocação-Fusão). \r\nSe este card for adicionado ao seu Deck Adicional com a face para cima: você pode Invocar por Invocação-Especial 1 monstro "Patrono(a) do Poder" ou "Artmage" do seu Deck ou Deck Adicional com a face para cima, exceto "Nervedo, o Patrono do Poder Besta Sombria". \r\nVocê só pode usar cada efeito de "Nervedo, o Patrono do Poder Besta Sombria" uma vez por turno.','\r',char(13)),'\n',char(10)),'Aplicar o efeito de "Nervedo, o Patrono do Poder Besta Sombria" para negar?','Invocação Especial','Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17475251,'Irmandade do Punho de Fogo - Falcão',replace(replace('Se este card, em posse do seu dono, for destruído por um card do oponente (seja em batalha ou por um efeito de card): você pode Baixar 1 Card de Magia "Formação de Fogo" diretamente do seu Deck. \r\nEnquanto você controlar um Card de Magia/Armadilha "Formação de Fogo", todos os monstros "Punho de Fogo" que você controla ganham 500 de ATK e DEF.','\r',char(13)),'\n',char(10)),'Baixar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17484499,'Troca de Espírito',replace(replace('Se os dois duelistas tiverem 15 ou mais cards nos seus Cemitérios: pague 1000 PV; cada duelista troca os cards no seu Cemitério com os cards no seu Deck e, depois, embaralha seu Deck. \r\nVocê só pode ativar 1 "Troca de Espírito" por Duelo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17490535,'Cérebro Alienígena','Se um monstro Réptil que você controla for destruído em batalha com um monstro atacante do oponente e enviado para o Cemitério: tome o controle do monstro do oponente e, se isso acontecer, ele se torna um Réptil.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17494901,'Gagagarrelâmpago','Se você controlar um monstro "Gagaga": escolha 1 card no campo; destrua o alvo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17502671,'General Inférnico','Se você não tiver cards na sua mão: você pode banir este card do seu Cemitério e, depois, escolha 2 monstros "Inférnico(a)" de Nível 3 ou menos no seu Cemitério; Invoque-os por Invocação-Especial do Cemitério, mas seus efeitos são negados.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17509503,'A Vingança do Normal',replace(replace('Invoque por Invocação-Especial monstros de Nível 4 ou menos da sua mão, até o número de monstros que seu oponente controla. \r\nVocê só pode ativar 1 "A Vingança do Normal" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17511156,'Palhaço de Madeira','Uma criatura com um sorriso malicioso e uma foice letal.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17521642,'Força Zero',replace(replace('Ative apenas quando um monstro com a face para cima que você controla for removido de jogo. \r\nO ATK de todos os monstros com a face para cima no campo se torna 0.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17530001,'Cubical','Uma vez por turno: você pode lançar um dado de seis faces e enquanto este monstro estiver com a face para cima no campo, nenhum duelista pode Invocar monstros por Invocação-Normal ou Especial com o mesmo Nível que o resultado.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17535588,'Estrela-do-Mar Encouraçada','Uma estrela-do-mar azulada com uma couraça capaz de repelir ataques.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17535764,'Gokiposte',replace(replace('Se este card for enviado para o Cemitério: você pode adicionar 1 monstro Inseto de Nível 4 do seu Deck à sua mão e, depois, se você adicionou um Monstro Normal, você pode Invocá-lo por Invocação-Especial e, depois, você pode destruir 1 monstro no campo com ATK igual ou maior que o desse monstro Invocado por Invocação-Especial. \r\nVocê só pode usar este efeito de "Gokiposte" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Invocação Especial?','Destruir o monstro?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17536995,'Mudança Heráldica','Quando um monstro do oponente declarar um ataque: Invoque por Invocação-Especial 1 monstro "Besta Heráldica" da sua mão e, depois, termine a Fase de Batalha.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17540705,'Camarartista Lançador de Ada-da-gas',replace(replace('Escala de Pêndulo = 2\r\n[ Efeito de Pêndulo ]\r\nDurante sua Fase Principal, se este card foi ativado neste turno: você pode escolher 1 monstro "Camarartista" no seu Cemitério; adicione-o à sua mão. \r\nVocê só pode usar este efeito de "Camarartista Lançador de Ada-da-gas" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nDurante sua Fase Principal, se este card foi Invocado por Invocação-Pêndulo neste turno: você pode enviar 1 monstro "Camarartista" da sua mão para o Cemitério; compre 1 card. \r\nVocê só pode usar este efeito de "Camarartista Lançador de Ada-da-gas" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17548456,'Meteoro Jurrac',replace(replace('1 Regulador "Jurrac" + 2+ monstros Dinossauro não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro: destrua todos os cards no campo e, depois, você pode Invocar por Invocação-Especial 1 Regulador do seu Cemitério.','\r',char(13)),'\n',char(10)),'Destruir e Invocar por Invocação Especial','Invocar um Regulador por Invocação Especial?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17548457,'Meteoro Jurrac',replace(replace('1 Regulador "Jurrac" + 2+ monstros Dinossauro não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro: destrua todos os cards no campo e, depois, você pode Invocar por Invocação-Especial 1 Regulador do seu Cemitério.','\r',char(13)),'\n',char(10)),'Destruir e Invocar por Invocação Especial','Invocar um Regulador por Invocação Especial?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17550376,'Defensor dos Sonhos de Nemleria - Oreiller',replace(replace('Se você tiver um Monstro Pêndulo com a face para cima no seu Deck Adicional, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Defensor dos Sonhos de Nemleria - Oreiller" por Invocação-Especial uma vez por turno desta forma. \r\nSe você tiver "Nemleria Sonhadora" com a face para cima no seu Deck Adicional (Efeito Rápido): você pode banir, com a face para baixo, 1 card com a face para baixo do seu Deck Adicional; até o final deste turno, este card ganha 500 de ATK para cada monstro que seu oponente controla atualmente. \r\nVocê só pode usar este efeito de "Defensor dos Sonhos de Nemleria - Oreiller" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17559367,'Mergulhador das Profundezas','No final da Fase de Batalha, se este card foi destruído em batalha e enviado para o Cemitério: Escolha 1 monstro do seu Deck e coloque-o no topo do seu Deck.','Adicionar à mão','Escolha o card de Monstro a ser colocado no topo do Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17573739,'Alector, Soberano dos Pássaros',replace(replace('Se seu oponente controlar 2 ou mais monstros com a face para cima com o mesmo Atributo, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nUma vez por turno: Você pode escolher 1 card com a face para cima no campo; os efeitos do alvo são negados durante este turno. \r\nSó pode haver 1 "Alector, Soberano dos Pássaros" com a face para cima no campo.','\r',char(13)),'\n',char(10)),'Negar o efeito','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17589298,'Espada dos Rituais Sombrios',replace(replace('Só pode ser equipado a um monstro de TREVAS. \r\nEle ganha 400 de ATK. \r\nQuando o monstro equipado for oferecido como Tributo e este card for enviado para o Cemitério, devolva este card à sua mão.','\r',char(13)),'\n',char(10)),'Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17597059,'Choque Byser','Se este card for Invocado: devolva todos os cards Baixados no campo para a mão.','Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17601919,'Princesa-Abóbora, a Princesa dos Fantasmas',replace(replace('Se este card com a face para cima for destruído em uma Zona de Monstros, você pode colocá-lo com a face para cima na sua Zona de Magias & Armadilhas como uma Magia Contínua, em vez de enviá-lo para o Cemitério. \r\nEnquanto este card for considerado como uma Magia Contínua por este efeito, durante cada Fase de Apoio: coloque 1 Marcador de Abóbora neste card. \r\nTodos os monstros que seu oponente controla perdem 100 de ATK/DEF para cada Marcador de Abóbora neste card.','\r',char(13)),'\n',char(10)),'Usar o efeito de "Princesa-Abóbora, a Princesa dos Fantasmas"?','Colocar um marcador','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17616743,'Despertar do Olho Maligno',replace(replace('Invoque por Invocação-Especial 1 monstro "Olho Maligno" da sua mão ou do Cemitério, ou, se "Olho Maligno de Selene" estiver na sua Zona de Magias & Armadilhas, em vez disso, você pode Invocar por Invocação-Especial 1 monstro "Olho Maligno" do seu Deck. \r\nVocê só pode ativar 1 "Despertar do Olho Maligno" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17621695,'Eneápolis',replace(replace('(Este card deve ser sempre considerado como um card "Eneanave".)	\r\nUma vez por turno, durante a Fase Final: remova todos os Marcadores de E.N. do seu campo e, se isso acontecer, seu oponente sofre 900 de dano para cada um. \r\nVocê só pode usar cada um dos seguintes efeitos de "Eneápolis" uma vez por turno. \r\nVocê pode escolher qualquer número de Cards de Monstro Pêndulo "Eneanave" que você controla; devolva-os para a mão. \r\nSe um ou mais Monstros Pêndulo "Eneanave" que você controla forem virados com a face para cima durante a Fase Principal: você pode selecionar 1 deles e devolvê-lo para a mão ou colocá-lo na sua Zona de Pêndulo.','\r',char(13)),'\n',char(10)),'Retornar à mão','Retornar à mão','Causar dano','Colocar na Zona de Pêndulo','Adicionar à mão','','','','','','','','','','','');
INSERT INTO texts VALUES(17626381,'Suprir o Pelotão','Uma vez por turno, se um ou mais monstros que você controla forem destruídos em batalha ou por um efeito de card: compre 1 card.','Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17639150,'Saqlifício',replace(replace('Só pode ser equipado a um monstro "Qli". \r\nEle ganha 300 de ATK e não pode ser destruído em batalha. \r\nO monstro equipado pode ser considerado como 2 Tributos para a Invocação-Tributo de um monstro "Qli". \r\nSe este card for enviado do campo para o Cemitério: você pode adicionar 1 monstro "Qli" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Procurar no Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17643265,'Tubarão Dobrado',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode reduzir em 1 os Níveis de todos os monstros do Tipo Peixe de Nível 4 que você controla. \r\nEste card pode realizar um segundo ataque durante cada Fase de Batalha.','\r',char(13)),'\n',char(10)),'Reduzir o Nível','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17649753,'Lombriga Rakuyeh',replace(replace('Este card só pode declarar um ataque durante o turno em que ele for virado com a face para cima. \r\nSe este card atacar, ele é colocado com a face para baixo em Posição de Defesa no final da Fase de Batalha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17653779,'Espelho de Mão do Anjo','Quando seu oponente ativar um Card de Magia que escolhe como alvo exatamente 1 monstro (e nenhum outro card) no campo: escolha outro card que seria um alvo apropriado; essa Magia agora escolhe o novo alvo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17655904,'Raio Explosivo de Destruição','Se você controlar "Dragão Branco de Olhos Azuis": destrua todos os monstros que seu oponente controla. "Dragão Branco de Olhos Azuis" que você controla não pode atacar no turno em que você ativar este card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17658803,'Dragão do Brilho nº 2','Este dragão se alimenta de esmeraldas. As pessoas são encantadas por este monstro, mesmo quando atacadas, e poucas vivem para falar de sua beleza.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17663375,'Wivern do Mecanismo Antigo',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 card "Mecanismo Antigo" do seu Deck à sua mão, exceto "Wivern do Mecanismo Antigo" e, além disso, você não pode Baixar cards pelo resto deste turno. \r\nVocê só pode usar este efeito de "Wivern do Mecanismo Antigo" uma vez por turno. \r\nSe este card atacar, seu oponente não pode ativar efeitos de monstro até o final da Etapa de Dano.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17679043,'Torpedo Pinguim',replace(replace('Este card pode atacar diretamente. \r\nQuando este card causar dano de batalha ao seu oponente: você pode escolher 1 monstro de Nível 6 ou menos que seu oponente controla; tome o controle dele até a Fase Final, mas seus efeitos são negados e, além disso, ele não pode declarar um ataque enquanto você o controlar. \r\nVocê só pode usar este efeito de "Torpedo Pinguim" uma vez por turno. \r\nNo final da Etapa de Dano, se este card atacou: destrua este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17688543,'O Túmulo Profundo','Escolha 1 monstro no Cemitério de qualquer duelista; durante sua próxima Fase de Apoio, Invoque-o por Invocação-Especial do Cemitério.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17691568,'Batuque Louco Gagaku-P.U.N.K.',replace(replace('Se seu oponente ativar um card ou efeito que escolha como alvo um ou mais monstros "P.U.N.K." seus: você pode escolher 1 card que seu oponente controla; destrua-o. \r\nVocê só pode usar este efeito de "Batuque Louco Gagaku-P.U.N.K." uma vez por turno. \r\nSe este card na Zona de Magias & Armadilhas do seu dono for destruído por um efeito de card do oponente: você pode ativar este efeito; neste turno, seu oponente não pode escolher monstros "P.U.N.K." que você controla como alvo de efeitos de card, e eles não podem ser destruídos pelos efeitos de card do seu oponente.','\r',char(13)),'\n',char(10)),'','','O efeito de "Batuque Louco Gagaku-P.U.N.K." está sendo aplicado.','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17706537,'Mamute Fóssil','Quando este card destruir um monstro do oponente em batalha e enviá-lo para o Cemitério, cause 400 de dano ao seu oponente.','Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17719582,'Peripécia de Artmage -Turbulência-',replace(replace('Escolha 1 monstro no Cemitério do seu oponente; devolva 1 monstro "Artmage" que você controla para a mão/Deck Adicional e, se isso acontecer, Invoque o alvo por Invocação-Especial no seu campo, mas negue seus efeitos. \r\nSe este card for enviado para o Cemitério para ativar o efeito de "Artmage, Academia Acrópole de Artes Arcanas": você pode adicionar 1 Magia "Artmage" do seu Cemitério ou banimento à sua mão. \r\nVocê só pode usar cada efeito de "Peripécia de Artmage -Turbulência-" uma vez por turno e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional no turno em que ativar qualquer um dos efeitos deste card, exceto Monstros de Fusão.','\r',char(13)),'\n',char(10)),'Invocação Especial','Recuperar 1 Card de Magia','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17720747,'Bruxa da Rosa Negra',replace(replace('Não pode ser Invocado por Invocação-Especial. \r\nSe este card for Invocado por Invocação-Normal e você não controlar nenhum outro card: compre 1 card e mostre-o e, depois, se não for um monstro, envie-o para o Cemitério e, além disso, destrua este card.','\r',char(13)),'\n',char(10)),'Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17722185,'Barreira de Invencibilidade','Uma vez por turno: você pode banir 1 Monstro de Ritual, de Fusão, Sincro, Xyz, Pêndulo ou Link com a face para cima que você controla; neste turno, os efeitos dos monstros com o mesmo tipo de card que o monstro banido (Ritual, Fusão, Sincro, Xyz, Pêndulo ou Link) são negados.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17725109,'Rugido dos Dragões de Olhos Azulados',replace(replace('Invoque por Invocação-Especial em Posição de Defesa, 1 monstro "Olhos Azuis" do seu Deck, Cemitério ou banimento (mas se você não controlar nenhum "Dragão Branco de Olhos Azuis", você só pode Invocar "Dragão Branco de Olhos Azuis" por Invocação-Especial com este efeito) e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto monstros Dragão. \r\nVocê pode banir este card do seu Cemitério; Invoque por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional, usando monstros da sua mão ou do campo, incluindo um monstro "Olhos Azuis". \r\nVocê só pode usar 1 efeito de "Rugido dos Dragões de Olhos Azulados" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Invocação Fusão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17732278,'Musgo Brilhante Neoespacial',replace(replace('Se este card atacar ou for atacado: seu oponente compra 1 card e o mostra e, depois, dependendo do tipo do card, aplique este efeito.\r\n● Monstro: Encerre a Fase de Batalha deste turno.\r\n● Magia: Se este card estiver atacando, em vez disso, você pode fazer com que seja um ataque direto.\r\n● Armadilha: Coloque este card em Posição de Defesa.','\r',char(13)),'\n',char(10)),'Comprar','Declarar um ataque direto?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17733394,'Despojos de Madeira','Um cadáver feito de madeira, reanimado pelos poderes das trevas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17739335,'Zerrziel, o Governante dos Seguidores do Olho Maligno',replace(replace('2+ monstros "Olho Maligno"	\r\nSe este card foi Invocado por Invocação-Link usando um monstro com 2600 ou mais de ATK como matéria, ele pode realizar um segundo ataque durante cada Fase de Batalha. \r\nSe este card estiver equipado com "Olho Maligno de Selene" (Efeito Rápido): você pode escolher 1 card que seu oponente controla; destrua-o. \r\nVocê só pode usar este efeito de "Zerrziel, o Governante dos Seguidores do Olho Maligno" uma vez por turno. \r\nUma vez por turno, durante a próxima Fase de Apoio depois que este efeito foi ativado: negue o efeito de 1 Monstro de Efeito para o qual este card apontar atualmente.','\r',char(13)),'\n',char(10)),'Destruir 1 card','Negar o efeito','Um monstro com 2600 ou mais de ATK como Matéria Link','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17745969,'Super Veicroide Base Móvel',replace(replace('1 Monstro de Fusão "roide" + 1 monstro "roide"	\r\nVocê pode escolher 1 monstro com a face para cima que seu oponente controla; Invoque por Invocação-Especial 1 monstro "roide" do seu Deck ou Deck Adicional com ATK menor ou igual que o desse monstro. \r\nVocê só pode usar este efeito de "Super Veicroide Base Móvel" uma vez por turno. \r\nUma vez por turno, durante a Fase Final: você pode escolher 1 monstro "roide" na sua Zona de Monstros Principal (que não seja este card); devolva esse monstro que você controla para a mão e, se isso acontecer, mova este card que você controla para a Zona de Monstros desse monstro.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17749468,'Azamina',replace(replace('"Rainha Azamina" + 1 Monstro de Fusão ou Sincro	\r\nPrimeiro deve ser Invocado por Invocação-Fusão, ou por Invocação-Especial (do seu Deck Adicional) ao oferecer como Tributo 1 "Santa Azamina" que você controla e 1 monstro com a face para cima que seu oponente controla. \r\nNão pode ser destruído por efeitos de card. \r\nSempre que seu oponente ativar um card ou efeito, todos os monstros que ele controla perdem 500 de ATK quando ele resolver. \r\nSeu oponente não pode ativar os efeitos de monstros com 0 de ATK.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17751597,'Retribuição do Marcado',replace(replace('Quando um Card de Magia/Armadilha, ou efeito de monstro, for ativado que inclua um efeito que Invoque um ou mais monstros por Invocação-Especial: devolva ao Deck Adicional, 1 Monstro de Fusão com a face para cima que você controla, ou 2 Monstros de Fusão no seu Cemitério, que mencionem "Caído de Arbaz" como matéria e, se isso acontecer, negue a ativação e, se isso acontecer, destrua esse card. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 Magia/Armadilha "Marcado" no seu Cemitério, exceto "Retribuição do Marcado"; adicione-o à sua mão. \r\nVocê só pode usar 1 efeito de "Retribuição do Marcado" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17760003,'Aliado Genex Tribraço',replace(replace('"Controlador Genex" + 1+ monstros não-Reguladores	\r\nUma vez por turno: você pode descartar 1 card e, depois, ative 1 desses efeitos, dependendo dos Atributos dos não-Reguladores usados para a Invocação-Sincro deste card;\r\n● VENTO: Envie 1 card aleatório da mão do seu oponente para o Cemitério.\r\n● ÁGUA: Escolha 1 Magia/Armadilha no campo; destrua-a.\r\n● TREVAS: Escolha 1 monstro de LUZ no campo; destrua o alvo e, se isso acontecer, compre 1 card.','\r',char(13)),'\n',char(10)),'Enviar para o Cemitério 1 card aleatório da mão do seu oponente','Destruir 1 Card de Magia/Armadilha no campo','Destruir 1 monstro de LUZ com a face para cima no campo','Um monstro de VENTO como Matéria Sincro','Um monstro de ÁGUA como Matéria Sincro','Um monstro de TREVAS como Matéria Sincro','','','','','','','','','','');
INSERT INTO texts VALUES(17775525,'Samurai Superpesado Rei do Trem a Vapor',replace(replace('1 Regulador "Samurai Superpesado" + 2+ monstros "Samurai Superpesado" não-Reguladores	\r\nEste card pode atacar enquanto estiver com a face para cima em Posição de Defesa. \r\nSe o fizer, use sua DEF para o cálculo de dano. \r\nUma vez por turno: você pode descartar até 2 cards e, depois, escolher o mesmo número de cards que seu oponente controla; destrua-os. \r\nUma vez por turno: você pode banir todas as Magias e Armadilhas nos Cemitérios e, se isso acontecer, cause 200 de dano ao seu oponente para cada card banido.','\r',char(13)),'\n',char(10)),'Destruir 1 card','Banir Cards de Magia/Armadilha','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17782288,'Problema de Anjoléquia',replace(replace('Uma vez por turno: você pode descartar 1 Magia/Armadilha; Invoque por Invocação-Especial 1 monstro "Anjoléquia" de Nível 2 do seu Deck Adicional e, se isso acontecer, coloque 1 monstro "Anjoléquia" do seu Deck Adicional na sua Zona de Magias & Armadilhas como uma Magia Contínua com a face para cima. \r\nSe um ou mais Cards de Monstro "Anjoléquia" com a face para cima que você controla forem destruídos em batalha ou por um efeito de card: você pode devolver 1 Card de Monstro "Anjoléquia", do qual você é dono, da sua Zona de Magias & Armadilhas para o Deck Adicional e, depois, você pode Invocá-lo por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Invocação Especial','Retornar ao Deck Adicional','Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17787975,'Esfinge Dimensional',replace(replace('Ative este card ao escolher 1 monstro com a face para cima em Posição de Ataque que você controla. \r\nUma vez por batalha, durante a Etapa de Batalha, se ele for atacado por um monstro do oponente com maior ATK: você pode causar dano ao seu oponente igual à diferença entre o ATK do monstro atacante e do monstro alvo. \r\nSe o monstro escolhido deixar o campo, destrua este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17810268,'Nuviano - Nuvem Ácida',replace(replace('Não pode ser destruído em batalha. \r\nSe este card estiver com a face para cima em Posição de Defesa, destrua-o. \r\nSe este card for Invocado por Invocação-Normal: coloque 1 Marcador de Névoa nele para cada monstro "Nuviano" no campo. \r\nVocê pode remover 2 Marcadores de Névoa deste card e, depois, escolha 1 Magia/Armadilha no campo; destrua o alvo.','\r',char(13)),'\n',char(10)),'Colocar um marcador','Destruir Magias/Armadilhas','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17814387,'Reforços','Escolha 1 monstro com a face para cima no campo; ele ganha 500 de ATK até o final deste turno.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17825378,'Predaplanta Triantis',replace(replace('Escala de Pêndulo = 8\r\n[ Efeito de Pêndulo ]\r\nEnquanto este card estiver na sua Zona de Pêndulo, se você Invocar por Invocação-Fusão um Monstro de Fusão de TREVAS, você também pode usar cards nas suas Zonas de Pêndulo como se fossem monstros no campo, como matéria para sua Invocação-Fusão.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe este card for enviado para o Cemitério ou adicionado ao seu Deck Adicional com a face para cima porque foi usado como Matéria de Fusão: você pode selecionar monstros no campo, até o número de monstros que você controla e colocar 1 Marcador de Predador em cada um e, se isso acontecer, quaisquer desses monstros que forem de Nível 2 ou mais se tornam de Nível 1 enquanto tiverem um Marcador de Predador.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17827173,'Brisawntarilho & Tucan',replace(replace('Se este card com a face para cima deixaria o campo, em vez disso, bana-o. \r\nVocê só pode usar cada um dos seguintes efeitos de "Brisawntarilho & Tucan" uma vez por turno e não pode Invocar por Invocação-Especial durante o turno em que ativar qualquer desses efeitos. \r\nSe este card for Invocado por Invocação-Normal: você pode escolher 1 dos seus cards "Brisawntarilho" banidos; adicione-o à sua mão e, depois, imediatamente depois que este efeito resolver, você pode Invocar 1 monstro Besta Alada por Invocação-Normal. \r\nSe um monstro Besta Alada for Invocado por Invocação-Normal no seu campo enquanto este card estiver banido: você pode adicionar este card à sua mão.','\r',char(13)),'\n',char(10)),'','Adicionar este card à sua mão','Invocar 1 monstro Besta Alada?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17832359,'Wonko, o Nobre Cavaleiro da Floresta',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 "Prólogo do Conto de Fadas: Amanhecer da Jornada" do seu Deck à sua mão, ou, se "Prólogo do Conto de Fadas: Amanhecer da Jornada" estiver no seu campo ou Cemitério, em vez disso, você pode comprar 1 card. \r\nVocê só pode usar este efeito de "Wonko, o Nobre Cavaleiro da Floresta" uma vez por turno. \r\nEnquanto um card estiver na Zona do Campo, os monstros do seu oponente não podem escolher monstros como alvo de ataques, exceto este. \r\nQuando este card for destruído em batalha: você pode fazer com que o monstro que o destruiu perca 500 de ATK.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','Reduzir ATK','Ao invés, Comprar 1 card?','','','','','','','','','','','','');
INSERT INTO texts VALUES(17841097,'Soldado Agulha','Se este card for usado como um Monstro-Matéria Sincro para um Monstro Sincro, durante a batalha entre esse Monstro Sincro e um monstro em Posição de Defesa cuja DEF seja menor que o ATK desse Monstro Sincro, cause a diferença como Dano de Batalha ao seu oponente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17841166,'Força de Ímã','Neste turno, todos os monstros no campo cujo Tipo original seja Máquina ou Rocha, não são afetados pelos efeitos de monstro do seu oponente (exceto seus próprios).','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17856505,'Pumpking, o Grande Rei Fantasma',replace(replace('2 monstros Zumbi de Nível 6	\r\nEnquanto você controlar "Chamado dos Assombrados", seu oponente não pode escolher monstros Zumbi que você controla como alvo de efeitos de monstro. \r\nVocê só pode usar cada um dos seguintes efeitos de "Pumpking, o Grande Rei Fantasma" uma vez por turno. \r\nSe este card for Invocado por Invocação-Especial: você pode adicionar 1 "Chamado dos Assombrados" ou 1 card que o mencione do seu Deck à sua mão. \r\nVocê pode desassociar 1 matéria deste card e, depois, escolha até 2 cards no campo; devolva-os para a mão.','\r',char(13)),'\n',char(10)),'','Adicionar à mão','Retornar para a mão','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17857780,'Camarartista Toupeira de Torcida',replace(replace('Escala de Pêndulo = 5\r\n[ Efeito de Pêndulo ]\r\nTodos os Monstros Pêndulo que você controla ganham 300 de ATK.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nVocê pode escolher 1 monstro cujo ATK atual seja diferente do seu ATK original; aplique o efeito apropriado. \r\nVocê só pode usar este efeito de "Camarartista Toupeira de Torcida" uma vez por turno.\r\n● Se o ATK atual desse monstro for maior que o ATK original dele, ele ganha 1000 de ATK.\r\n● Se o ATK atual desse monstro for menor que o ATK original dele, ele perde 1000 de ATK.','\r',char(13)),'\n',char(10)),'Alterar ATK/DEF','Alterar ATK/DEF','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17871506,'Dragão Meteoro do Impacto dos Olhos Vermelhos',replace(replace('Este card é considerado um Monstro Normal enquanto estiver com a face para cima no campo ou no Cemitério. \r\nEnquanto este card for um Monstro Normal no campo, você pode Invocá-lo por Invocação-Normal para fazer com que ele se torne um Monstro de Efeito com este efeito.\r\n● Outros monstros "Olhos Vermelhos" que você controla não podem ser destruídos em batalha ou por efeitos de card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17874674,'Selo da Perversidade',replace(replace('Uma vez por turno, durante a Fase de Apoio do seu oponente, selecione 1 card com a face para cima no campo. \r\nOs efeitos do card selecionado são negados durante esse turno. \r\nDurante cada uma das suas Fases de Apoio, pague 500 PV ou destrua este card.','\r',char(13)),'\n',char(10)),'Negar o efeito','Pagar 500 PV para manter "Selo da Perversidade"?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17881964,'Dragão do Fogo Negro','"Relva-Fogo" + "Pequeno Dragão"','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17885118,'Escala de Pêndulo',replace(replace('Se você tiver 2 cards nas suas Zonas de Pêndulo: aplique o seguinte efeito, de acordo com a diferença nas Escalas de Pêndulo.\r\n● 0: Destrua 2 Magias/Armadilhas no campo.\r\n● 1, 2 ou 3: Adicione 1 Monstro Pêndulo de Nível 2, 3 ou 4 do seu Deck à sua mão.\r\n● 4, 5 ou 6: Adicione 1 Monstro Pêndulo de Nível 5, 6 ou 7 do seu Deck à sua mão.\r\n● 7+: Devolva até 2 cards da(s) sua(s) \r\nZona(s) de Pêndulo para a mão e, depois, você pode Invocar por Invocação-Especial 1 Monstro Pêndulo da sua mão.\r\nVocê só pode ativar 1 "Escala de Pêndulo" por turno.','\r',char(13)),'\n',char(10)),'','Invocar por Invocação Especial 1 Monstro Pêndulo da sua mão?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17888577,'Rastreador Sônico',replace(replace('Este card é usado para a Invocação-Ritual de "Transpássaro Sônico". \r\nVocê também deve oferecer como Tributo monstros da sua mão ou do campo cuja soma dos Níveis seja igual a 4 ou mais. \r\nO Nível do monstro Invocado por Invocação-Especial por este efeito se torna a soma dos Níveis dos monstros usados para sua Invocação-Ritual. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 Monstro de Ritual que você controla; envie 1 Monstro de Ritual com o mesmo Tipo ou Atributo do seu Deck para o Cemitério. \r\nVocê só pode usar este efeito de "Rastreador Sônico" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17896384,'Barreira Arcana',replace(replace('Sempre que um ou mais monstros Mago com a face para cima no campo forem destruídos, coloque 1 Marcador de Magia neste card (máx. 4). \r\nVocê pode enviar este card e 1 monstro Mago com a face para cima que você controla para o Cemitério; compre 1 card para cada Marcador de Magia que estava neste card.','\r',char(13)),'\n',char(10)),'Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17932494,'Guerreiro Sônico','Se este card for enviado para o Cemitério: todos os monstros de Nível 2 ou menos que você controla atualmente ganham 500 de ATK.','Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17943271,'Goblin Mementotlan',replace(replace('Durante a Fase Principal, se você controlar "Mementoal Tecuhtlica - Criação Combinada" (Efeito Rápido): você pode descartar este card; pelo resto deste turno, seu oponente não pode escolher monstros "Memento" que você controla como alvo de efeitos de card. \r\nDurante sua Fase Principal: você pode destruir 1 monstro "Memento" que você controla e, se isso acontecer, envie até 2 cards "Memento" com nomes diferentes um do outro do seu Deck para o Cemitério, exceto "Goblin Mementotlan". \r\nVocê só pode usar cada efeito de "Goblin Mementotlan" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17946349,'Mechamático Diâmetro',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode escolher 1 monstro Ciberso de Nível 4 no seu Cemitério; Invoque-o por Invocação-Especial, mas ele não pode ativar seus efeitos. \r\nUm monstro "Mechamático" que foi Invocado por Invocação-Sincro ou Xyz usando este card no campo como matéria ganha o seguinte efeito.\r\n● Uma vez por turno, durante o turno em que este card foi Invocado por Invocação-Especial, quando seu oponente ativar um card ou efeito (Efeito Rápido): você pode negar o efeito.	\r\nVocê só pode usar cada efeito de "Mechamático Diâmetro" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Negue o efeito de (Mechamático Diâmetro) do seu oponente','O efeito de "Mechamático Diâmetro" está sendo aplicado.','Efeito já ativado','O efeito de "Mechamático Diâmetro" está sendo aplicado.','','','','','','','','','','','');
INSERT INTO texts VALUES(17947697,'Donzela de Branco',replace(replace('Você pode enviar este card da sua mão ou do campo para o Cemitério; coloque 1 "Luz Verdadeira" da sua mão, do Deck ou do Cemitério, com a face para cima na sua Zona de Magias & Armadilhas. \r\nSe você Invocar "Dragão Branco de Olhos Azuis" por Invocação-Especial enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial. \r\nQuando um card ou efeito for ativado que escolha este card no campo como alvo, ou quando este card for alvo de um ataque (Efeito Rápido): você pode Invocar por Invocação-Especial 1 "Dragão Branco de Olhos Azuis" ou 1 Regulador de LUZ de Nível 1 do seu Cemitério. \r\nVocê só pode usar cada efeito de "Donzela de Branco" uma vez por turno.','\r',char(13)),'\n',char(10)),'Colocar com a face para cima','Invocar este card por Invocação Especial','Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17948378,'Dino Jurrac','Uma vez durante a Fase Final de cada duelista, se este card destruiu um monstro do oponente em batalha neste turno, você pode oferecer como Tributo 1 monstro "Jurrac" para comprar 2 cards.','Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17954937,'Grande Purificação de Mitsurugi',replace(replace('Quando seu oponente ativar um card ou efeito: ofereça como Tributo 1 monstro Réptil de Nível 5 ou mais; negue esse efeito e, se isso acontecer, destrua esse card. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 monstro Réptil no seu Cemitério; Invoque-o por Invocação-Especial e, se isso acontecer, ofereça 1 outro monstro que você controla como Tributo. \r\nVocê só pode usar 1 efeito de "Grande Purificação de Mitsurugi" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Negar e destruir','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17955766,'Golfinho Aqua Neoespacial',replace(replace('Uma vez por turno: você pode descartar 1 card; olhe a mão do seu oponente e selecione 1 monstro. \r\nSe você controlar um monstro com ATK igual ou maior que o ATK do card selecionado, destrua o card selecionado e, se isso acontecer, cause 500 de dano ao seu oponente. \r\nCaso contrário, sofra 500 de dano.','\r',char(13)),'\n',char(10)),'Revelar a mão','Escolha 1 Card de Monstro','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17955767,'Golfinho Aqua Neoespacial',replace(replace('Uma vez por turno: você pode descartar 1 card; olhe a mão do seu oponente e selecione 1 monstro. \r\nSe você controlar um monstro com ATK igual ou maior que o ATK do card selecionado, destrua o card selecionado e, se isso acontecer, cause 500 de dano ao seu oponente. \r\nCaso contrário, sofra 500 de dano.','\r',char(13)),'\n',char(10)),'Revelar a mão','Escolha 1 Card de Monstro','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17956906,'Luz Final',replace(replace('Pague PV em múltiplos de 1000 e, depois, escolha 1 monstro "Valquíria-" no seu Cemitério com um nome diferente para cada 1000 PV pagos; Invoque-os por Invocação-Especial e, depois, seu oponente pode Invocar por Invocação-Especial monstros com 2000 ou menos de ATK do Cemitério dele, até o número de monstros que você Invocou por Invocação-Especial por este efeito. \r\nVocê só pode ativar 1 "Luz Final" por turno.','\r',char(13)),'\n',char(10)),'Escolha a quantidade de monstros a Invocar por Invocação Especial','Invocação Especial?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17968114,'Amazona dos Mares','Uma sereia que serve como arauto do Senhor dos Oceanos. Ela protege os domínios sagrados de Atlantis.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17979378,'D/D Cavaleiro Orgulhoso',replace(replace('Escala de Pêndulo = 6\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno: você pode pagar 500 PV e, depois, escolher 1 monstro com a face para cima que seu oponente controla; ele perde 500 de ATK (mesmo que este card deixe o campo). \r\nA não ser que você tenha um card "D/D" na sua outra Zona de Pêndulo, a Escala de Pêndulo deste card se torna 5.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nQuando este card for Invocado por Invocação-Normal: você pode adicionar 1 Monstro Pêndulo de TREVAS com a face para cima do seu Deck Adicional à sua mão.','\r',char(13)),'\n',char(10)),'Alterar ATK/DEF','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17985575,'Senhor dos Dragões','Nenhum duelista pode escolher monstros Dragão no campo como alvo de efeitos de card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17988746,'Cavaleiros Aparadores','Quando você sofrer dano de batalha de um monstro atacante do oponente: você pode Invocar este card por Invocação-Especial da sua mão e, depois, você pode Invocar por Invocação-Especial 1 monstro da sua mão com ATK menor ou igual que o dano que você sofreu.','Invoque este card por Invocação Especial da sua mão','Invocação Especial?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17994645,'Asanegra Agressor - Sayo, o que se Esconde na Chuva',replace(replace('1 Regulador + 1 monstro não-Regulador	\r\nSe este card for Invocado por Invocação-Sincro usando um monstro "Asanegra" como Matéria, ele é considerado como um Regulador enquanto estiver com a face para cima no campo. \r\nDuas vezes por turno, este card não pode ser destruído em batalha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18000338,'Re: EX','Se este card batalhar um monstro na Zona de Monstros Adicional, ele ganha 800 de ATK e DEF apenas durante a Etapa de Dano.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18013090,'Guerreiro Nitro',replace(replace('"Nitro Sincron" + 1 ou mais monstros não-Reguladores	\r\nUma vez durante cada um dos seus turnos, se você ativar um Card de Magia, apenas durante o cálculo de dano, este card ganha 1000 de ATK durante o próximo ataque neste turno envolvendo este card. \r\nSe este card atacante destruir um monstro do oponente em batalha, depois do cálculo de dano: você pode escolher 1 monstro com a face para cima em Posição de Defesa que seu oponente controla; coloque o alvo em Posição de Ataque e, depois, este card pode realizar um segundo ataque, em seguida, contra esse monstro.','\r',char(13)),'\n',char(10)),'Continuar atacando','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18027138,'Hipo Carnaval',replace(replace('Invoque por Invocação-Especial 3 "Fichas Hipo" (Tipo Besta/TERRA/Nível 1/ATK 0/DEF 0), mas elas não podem ser oferecidas como Tributo. \r\nVocê não pode Invocar monstros por Invocação-Especial do Deck Adicional enquanto uma "Ficha Hipo" estiver em uma Zona de Monstros. \r\nPelo resto deste turno, depois que este card resolver, os monstros que seu oponente controla não podem escolher monstros para atacar, exceto "Fichas Hipo".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18027139,'Ficha Hipo',replace(replace('Invocado por Especial com o efeito "Hipo Carnaval" ou um card relacionado. \r\nEsta Ficha não pode ser oferecida como Tributo. \r\nVocê não pode Invocar monstros por Especial do Deck Adicional enquanto uma "Ficha Hipo" está em uma Zona de Monstros.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18027140,'Ficha Hipo',replace(replace('Invocado por Especial com o efeito "Hipo Carnaval" ou um card relacionado. \r\nEsta Ficha não pode ser oferecida como Tributo. \r\nVocê não pode Invocar monstros por Especial do Deck Adicional enquanto uma "Ficha Hipo" está em uma Zona de Monstros.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18027141,'Ficha Hipo',replace(replace('Invocado por Especial com o efeito "Hipo Carnaval" ou um card relacionado. \r\nEsta Ficha não pode ser oferecida como Tributo. \r\nVocê não pode Invocar monstros por Especial do Deck Adicional enquanto uma "Ficha Hipo" está em uma Zona de Monstros.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18036057,'Cavaleiro Celeste Parshath',replace(replace('Se este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante. \r\nSe este card causar dano de batalha ao seu oponente: compre 1 card.','\r',char(13)),'\n',char(10)),'Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18046862,'Tábua do Luto',replace(replace('(Este card deve ser sempre considerado como um card "Wedju".)	\r\nO monstro equipado não pode atacar ou ser oferecido como Tributo e, além disso, seus efeitos são negados. \r\nUma vez por turno, se você controla o monstro equipado: você pode adicionar 1 card "Wedju" do seu Deck à sua mão, exceto "Tábua do Luto". \r\nSe este card for enviado para o Cemitério porque o monstro equipado foi destruído: você pode causar 500 de dano ao seu oponente. \r\nVocê só pode ativar 1 "Tábua do Luto" por turno.','\r',char(13)),'\n',char(10)),'','Adicionar à mão','Causar dano','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18060565,'Primus Pilus Dragunidade','Quando este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 monstro Besta Alada "Dragunidade" que você controla; equipe-o com 1 monstro Dragão "Dragunidade" de Nível 3 ou menos do seu Deck.','Equipar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18063928,'Peixe-dourado de Lata','Quando este card for Invocado por Invocação-Normal: você pode Invocar por Invocação-Especial 1 monstro de Nível 4 da sua mão.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18078153,'Exército dos Assombrados',replace(replace('Se você controlar "Chamado dos Assombrados" e este card estiver na sua mão ou no Cemitério: você pode Invocar este card por Invocação-Especial. \r\nSe este card for enviado para o Cemitério: você pode escolher 1 "Chamado dos Assombrados" no seu Cemitério; Baixe-o. \r\nVocê só pode usar cada efeito de "Exército dos Assombrados" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Baixar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18094166,'Faris, o HERÓI da Visão',replace(replace('Você pode descartar 1 outro monstro "HERÓI"; Invoque este card por Invocação-Especial da sua mão. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode colocar 1 monstro "HERÓI da Visão" do seu Deck, exceto "Faris, o HERÓI da Visão", na sua Zona de Magias & Armadilhas como uma Armadilha Contínua com a face para cima e, além disso, você não pode Invocar monstros por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto monstros "HERÓI". \r\nVocê só pode usar cada efeito de "Faris, o HERÓI da Visão" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18096222,'Amplificador de Gêmeos',replace(replace('Equipe este card a um monstro Gêmeos que você controla como um Card de Equipamento. \r\nEle ganha 700 de ATK. \r\nQuando este card for destruído enquanto equipado e enviado ao Cemitério, selecione 1 monstro Gêmeos com a face para cima e considere-o como um Monstro de Efeito.','\r',char(13)),'\n',char(10)),'Pode ser Invocado por Invocação Normal novamente','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18106132,'Monstro Boneca Urso-Urso',replace(replace('Mesmo que nós nos machuquemos, não tem problema.\r\nVovô Demetto pode remendar!','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18108166,'Misterioso Dragão Couraça','Uma misteriosa matéria viva que aparece de repente de uma dimensão diferente. Seu ataque paralisa os nervos do alvo e causa alucinações intensas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18114794,'Interromper Invocação','Durante a Fase Principal 1, se o duelista do turno conduzir com sucesso sua terceira Invocação de monstro(s) neste turno: a fase se torna a Fase Final.','Terminar o turno','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18138630,'Jarra Peladura',replace(replace('O nome deste card se torna "Vendedor de Brinquedos" enquanto ele estiver no campo ou no Cemitério. \r\nUma vez por turno: você pode descartar 1 card; compre 1 card e mostre-o e, depois, se for um monstro "Diabrete de", você pode destruir 1 card no campo, caso contrário, coloque 1 card da sua mão no topo ou no fundo do Deck. \r\nSe este card for enviado para o Cemitério: você pode escolher 1 monstro com a face para cima que seu oponente controla; diminua seu ATK pela metade até o final deste turno.','\r',char(13)),'\n',char(10)),'','','Destruir 1 card no campo?','Topo do Deck','Fundo do Deck','','','','','','','','','','','');
INSERT INTO texts VALUES(18144506,'Espanador de Penas da Harpia','Destrua todas as Magias e Armadilhas que seu oponente controla.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18144507,'Espanador de Penas da Harpia','Destrua todas as Magias e Armadilhas que seu oponente controla.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18144508,'Espanador de Penas da Harpia','Destrua todas as Magias e Armadilhas que seu oponente controla.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18158393,'Reenquadramento Mannadium',replace(replace('Quando um Card de Magia/Armadilha, ou efeito de monstro, for ativado enquanto você controlar um Monstro Sincro: negue a ativação e, depois, se você tiver "Visas Starfrost" ou um monstro com 1500 de ATK/2100 de DEF no seu campo ou no seu Cemitério, você pode destruir esse card negado. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha até 3 monstros "Mannadium" no seu Cemitério; embaralhe-os no Deck. \r\nVocê só pode usar cada efeito de "Reenquadramento Mannadium" uma vez por turno.','\r',char(13)),'\n',char(10)),'Destruir esse card negado?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18158397,'Desastre Natural','Cause 500 de dano ao seu oponente sempre que um ou mais cards que ele controla forem destruídos e enviados para o Cemitério pelo efeito de um monstro "Nuviano".','Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18161786,'Zona de Plasma Mística','Aumente em 500 o ATK de todos os monstros de TREVAS e diminua em 400 suas DEF.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18165869,'Lâmina Sombria Mementotlan',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode descartar 1 card "Memento" e, depois, escolha 1 Magia/Armadilha que seu oponente controla; destrua-a. \r\nDurante sua Fase Principal: você pode destruir 1 monstro "Memento" que você controla e, se isso acontecer, Invoque por Invocação-Especial 1 monstro "Memento" de Nível 3 ou menos do seu Deck. \r\nVocê só pode usar cada efeito de "Lâmina Sombria Mementotlan" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18168997,'Senhor Obscuro Nergal',replace(replace('Se um monstro Fada seu atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente. \r\n(Efeito Rápido): você pode pagar 1000 PV e, depois, escolha 1 Magia/Armadilha "Senhor(a) Obscuro(a)" no seu Cemitério; aplique o efeito do alvo e, depois, embaralhe o alvo no Deck. \r\nVocê só pode usar este efeito de "Senhor Obscuro Nergal" uma vez por turno. \r\nVocê só pode Invocar "Senhor Obscuro Nergal" por Invocação-Especial uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18175965,'Guardião Ceiforror',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial por seu próprio efeito. \r\nSe um "Guardião Eatos" for destruído em batalha ou por um efeito de card e enviado para o seu Cemitério: você pode Invocar este card por Invocação-Especial da sua mão. \r\nQuando este card for Invocado por Invocação-Especial: você pode equipar a este card 1 "Foice da Morte - Ceiforror" do seu Deck. \r\nVocê não pode Invocar monstros por Invocação-Normal ou Especial (mas pode Baixar de forma Normal). \r\nSe este card for enviado do campo para o Cemitério: envie 1 card da sua mão para o Cemitério e, se isso acontecer, Invoque este card por Invocação-Especial do Cemitério.','\r',char(13)),'\n',char(10)),'Invocação Especial','Equipar','Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18176525,'Mitsurugi no Mikoto, Saji',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial, ou se este card for oferecido como Tributo: você pode adicionar 1 Magia/Armadilha "Mitsurugi" do seu Deck à sua mão. \r\nSe um ou mais outros monstros Réptil que você controla seriam destruídos em batalha ou por um efeito de card, em vez disso, você pode oferecer este card como Tributo. \r\nVocê só pode usar cada efeito de "Mitsurugi no Mikoto, Saji" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Substituição de destruição','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18180762,'A Coisa Que se Esconde na Lama','Este monstro se derrete pelo subterrâneo para atacar inimigos por baixo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18189187,'Neiroy, o Discípulo do Espelho Onírico',replace(replace('Se um ou mais monstros "Espelho Onírico" estiverem no campo: você pode Invocar este card por Invocação-Especial da sua mão e, depois, você pode fazer com que este card se torne de TREVAS. \r\nSe este card for Invocado por Invocação-Especial pelo efeito de um monstro "Espelho Onírico": ative este efeito; se "Espelho Onírico da Alegria" estiver no campo, você pode devolver para a mão 1 Magia/Armadilha que seu oponente controla e, além disso, depois, se "Espelho Onírico do Terror" estiver no campo, compre 1 card e, depois, embaralhe 1 card da sua mão no Deck. \r\nVocê só pode usar cada efeito de "Neiroy, o Discípulo do Espelho Onírico" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Tornar este card de Atributo TREVAS?','Retornar para a mão 1 Card de Magia/Armadilha do seu oponente?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18190572,'Micro Raio','O DEF de 1 monstro no Campo com a face para cima, torna-se 0 até ao final da End Phase.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18205590,'Cavaleirostélite Ponte Celeste',replace(replace('Escolha 1 monstro "Cavaleirost" que você controla; Invoque por Invocação-Especial 1 monstro "Cavaleirost" com um nome diferente do seu Deck e, se isso acontecer, embaralhe o monstro alvo no Deck. \r\nEnquanto o monstro que foi Invocado por Invocação-Especial por este efeito estiver com a face para cima no campo, você não pode Invocar por Invocação-Especial, exceto monstros "Cavaleirost". \r\nVocê só pode ativar 1 "Cavaleirostélite Ponte Celeste" por turno.','\r',char(13)),'\n',char(10)),'O efeito de "Cavaleirostélite Ponte Celeste" está sendo aplicado.','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18210764,'Pêndulomucho',replace(replace('Escala de Pêndulo = 0\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno, durante sua Fase Principal, se este card foi ativado neste turno: Você pode escolher 1 dos seus Monstros Pêndulo, que estiver banido ou no seu Cemitério, exceto "Pêndulomucho"; adicione-o com a face para cima ao seu Deck Adicional.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode Invocar por Invocação-Especial 1 Monstro Pêndulo de Nível 1 com a face para cima do seu Deck Adicional, exceto "Pêndulomucho", mas bana-o quando ele deixar o campo.','\r',char(13)),'\n',char(10)),'Adicionar ao Deck Adicional','Escolha o card a ser adicionado ao seu Deck Adicional','Invocar por Invocação Especial 1 Monstro Pêndulo do Deck Adicional','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18214905,'Sabrelemento Lapauila',replace(replace('Uma vez por turno, quando um Card de Magia/Armadilha for ativado (Efeito Rápido): você pode enviar 1 monstro "Sabrelemento" da sua mão para o Cemitério; negue a ativação e, se isso acontecer, destrua-o. \r\nUma vez por turno, se este card estiver no Cemitério: você pode declarar 1 Atributo; este card no Cemitério se torna desse Atributo até o final deste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18235309,'Escalada dos Monarcas','Uma vez por turno, durante a Fase Principal ou a Fase de Batalha do seu oponente, você pode: imediatamente depois de resolver este efeito, Invocar 1 monstro por Invocação-Tributo.','Invocação Tributo','Ativar o efeito?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18235577,'Forasteiro Silencioso','Você pode enviar este card da sua mão ao Cemitério para reduzir o Nível de 1 monstro no campo em 1 até a Fase Final.','Reduzir o Nível','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18236002,'Lampanimados Travesso-Guris',replace(replace('Se este card for enviado para o Cemitério como matéria para a Invocação-Fusão ou Link de um monstro "Travesso-Guris": você pode causar 500 de dano ao seu oponente e, depois, você pode Invocar por Invocação-Especial 1 monstro "Travesso-Guris" da sua mão ou do Deck em Posição de Defesa, exceto "Lampanimados Travesso-Guris". \r\nVocê só pode usar este efeito de "Lampanimados Travesso-Guris" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18239909,'Proeminência Ignister, o Dracossassino Explosivo',replace(replace('1 Regulador + 1+ Monstros Pêndulo não-Reguladores	\r\nUma vez por turno: você pode escolher 1 Monstro Pêndulo no campo ou 1 card na Zona de Pêndulo; destrua-o e, se isso acontecer, embaralhe no Deck 1 card no campo. \r\nUma vez por turno: você pode Invocar por Invocação-Especial 1 monstro "Dracossassino" do seu Deck em Posição de Defesa, mas ele não pode ser usado como Matéria Sincro.','\r',char(13)),'\n',char(10)),'Retornar ao Deck','Invocação Especial','Não pode ser usado como Matéria Sincro','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18246479,'Jovem Touro Guerreiro','Um touro monstruoso muitas vezes encontrado na floresta, ele ataca os monstros inimigos com o seu par de chifres mortíferos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18249921,'Portão do Mundo Virtual - Xuanwu',replace(replace('Durante a Fase de Batalha, se você controlar outro card "Portão do Mundo Virtual": você pode escolher 1 monstro com a face para cima no campo; mude sua posição de batalha. \r\nDurante sua Fase Principal: você pode banir este card do seu Cemitério e, depois, escolha 1 monstro "Mundo Virtual" no seu Cemitério; Invoque-o por Invocação-Especial, mas negue seus efeitos e, depois, envie 1 card da sua mão para o Cemitério. \r\nVocê só pode usar cada efeito de "Portão do Mundo Virtual - Xuanwu" uma vez por turno. \r\nVocê só pode ativar 1 "Portão do Mundo Virtual - Xuanwu" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18252559,'Explosão Secreta',replace(replace('Cause 300 de dano ao seu oponente para cada card que ele controla. \r\nSe este card que você controla for destruído por um card do oponente e enviado para o seu Cemitério: cause 1000 de dano ao seu oponente.','\r',char(13)),'\n',char(10)),'Dano aos Pontos de Vida','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18271561,'Explosão Chtoniana','Quando um monstro com a face para cima que você controla for destruído e enviado para o Cemitério: destrua o 1 monstro com a face para cima no campo que tiver o menor ATK (em caso de empate, você escolhe) e, se isso acontecer, cause dano aos dois duelistas igual à metade do ATK desse monstro.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18282103,'Ganashia, o Mitológico',replace(replace('Se este card for descartado para o Cemitério: Invoque-o por Invocação-Especial. \r\nSe Invocado desta forma, ele ganha 200 de ATK, mas bana-o quando ele deixar o campo.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18294799,'Dragão Infinito Schwarzschild',replace(replace('Se você não controlar nenhum monstro, ou seu oponente controlar um monstro com 2000 ou mais de ATK: você pode Invocar este card por Invocação-Especial da sua mão e, se isso acontecer, Invoque por Invocação-Especial 1 monstro Dragão de Nível 8 de LUZ ou de TREVAS do seu Deck em Posição de Defesa, exceto "Dragão Infinito Schwarzschild", mas negue seus efeitos. \r\nVocê só pode usar este efeito de "Dragão Infinito Schwarzschild" uma vez por turno e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional no turno em que ativar este efeito, exceto Monstros Xyz Dragão.','\r',char(13)),'\n',char(10)),'Invocar este card por Invocação Especial e Invocar por Invocação Especial do Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18300894,'Mariposa Bomba de Seda',replace(replace('Se você tiver 2 ou mais monstros de VENTO no seu Cemitério e este card estiver na sua mão: você pode Invocar este card por Invocação-Especial e, se isso acontecer, embaralhe 1 monstro de VENTO do seu Cemitério no Deck. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode revelar o card do topo do Deck do seu oponente e aplicar o efeito apropriado de acordo com seu tipo de card.\r\n● Monstro: Coloque-o na Zona de Magias & Armadilhas do seu oponente como uma Magia Contínua com a face para cima.\r\n● Magia/Armadilha: Bana-a.	\r\nVocê só pode usar cada efeito de "Mariposa Bomba de Seda" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Revelar o Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18302224,'Inversão de Neos',replace(replace('Ative apenas quando um Monstro de Fusão "Neos" com a face para cima que você controla for destruído. \r\nInvoque por Invocação-Especial 1 "Neos, o HERÓI do Elemento" do seu Deck em Posição de Ataque. \r\nEle ganha 1000 de ATK e é destruído durante a Fase Final deste turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18313046,'Carpa Ascendente Ukiyoe-P.U.N.K.',replace(replace('2 monstros "P.U.N.K."	\r\nVocê pode oferecer como Tributo este card Invocado por Invocação-Fusão; Invoque por Invocação-Especial até 2 monstros "P.U.N.K." com nomes diferentes um do outro da sua mão e/ou do Deck, exceto monstros de Nível 8, em Posição de Defesa. \r\nSe você Invocou por Invocação-Sincro usando este card como matéria: você pode escolher 1 monstro "P.U.N.K." que você controla; ele pode realizar um segundo ataque durante cada Fase de Batalha neste turno. \r\nVocê só pode usar cada efeito de "Carpa Ascendente Ukiyoe-P.U.N.K." uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18318842,'Soldado do Abismo','Uma vez por turno: Você pode descartar 1 monstro de ÁGUA ao Cemitério para escolher 1 card no campo; devolva-o à mão.','Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18319762,'Reveladora da Barreira de Gelo',replace(replace('Enquanto você controlar outro monstro "Barreira de Gelo", seu oponente não pode Invocar por Invocação-Tributo. \r\nVocê só pode usar cada um dos seguintes efeitos de "Reveladora da Barreira de Gelo" uma vez por turno. \r\nVocê pode descartar 1 card; Invoque por Invocação-Especial 1 Regulador "Barreira de Gelo" do seu Deck e, além disso, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros de ÁGUA. \r\nSe você iria descartar ou enviar um ou mais cards da sua mão para o Cemitério para ativar o efeito de um monstro "Barreira de Gelo", você pode banir este card do seu Cemitério em vez de 1 desses cards.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18321034,'Hecamãos Mankibuel',replace(replace('Se este card batalhar um monstro, nenhum dos dois pode ser destruído nessa batalha. \r\nVocê só pode usar cada um dos seguintes efeitos de "Hecamãos Mankibuel" uma vez por turno. \r\nVocê pode revelar este card na sua mão; Invoque por Invocação-Fusão 1 Monstro de Fusão "Hecamãos" do seu Deck Adicional, usando monstros da sua mão ou do campo, incluindo este card na sua mão. \r\nSe um ou mais Monstros de Fusão Ilusão forem enviados para o seu Cemitério, enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode adicionar este card à sua mão.','\r',char(13)),'\n',char(10)),'Invocação Fusão','Retornar para a mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18322364,'Grande Baleia',replace(replace('Quando este card for Invocado por Invocação-Tributo: você pode oferecer este card como Tributo; Invoque por Invocação-Especial 3 monstros de ÁGUA de Nível 3 do seu Deck. \r\nSeus efeitos são negados.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18325492,'Giroide','Na primeira vez que este card seria destruído em batalha a cada turno, ele não é destruído.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18326736,'Cavaleirostrela Ptolemaeus',replace(replace('2+ monstros de Nível 4	\r\nUma vez por Corrente (Efeito Rápido): você pode desassociar 3 matérias deste card; Invoque por Invocação-Especial do seu Deck Adicional, 1 Monstro Xyz que seja 1 Classe maior que este card, exceto um monstro "Número", ao usar este card com a face para cima que você controla como matéria. \r\n(Isso é considerado uma Invocação-Xyz. Transfira as matérias dele para o monstro Invocado.) \r\nVocê pode desassociar 7 matérias deste card; pule o próximo turno do seu oponente. \r\nUma vez por turno, durante a Fase Final: você pode associar 1 card "Cavaleirostelar" do seu Deck Adicional a este card como matéria.','\r',char(13)),'\n',char(10)),'Invocação Especial','Pular o próximo turno do seu oponente','Associar como Matéria Xyz','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18372968,'Lagarto Navalha','Enquanto você controlar outro monstro do Tipo Réptil, se este card atacar um monstro com a face para baixo em Posição de Defesa, destrua o monstro imediatamente com o efeito deste card sem virá-lo com a face para cima ou aplicar o cálculo de dano.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18377261,'Ha-Re, a Espada Mikanko',replace(replace('Se este card não estiver equipado com um Card de Equipamento, você não sofre dano das batalhas envolvendo este card. \r\nSe este card estiver equipado com um Card de Equipamento, ele não pode ser destruído em batalha e seu oponente sofre qualquer dano de batalha que você teria sofrido das batalhas envolvendo este card. \r\nSe um Card de Equipamento se tornar equipado a este card: você pode adicionar 1 Magia de Equipamento "Mikanko" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Ha-Re, a Espada Mikanko" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18378582,'Archlord Zerato',replace(replace('Este monstro não poder ser Invocado a não ser por Invocação-Especial, oferecendo 1 "Guerreiro de Zera" no seu Campo com a face para cima como Tributo, enquanto "O Santuário no Céu" está no Campo. \r\nDescarte 1 Card de Monstro da LUZ da sua mão para o Cemitério, para destruir todos os monstros no Campo do seu adversário. \r\nEste efeito não é aplicado a não ser que "O Santuário no Céu" esteja no seu Campo.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18378992,'Seletor Pernicioso',replace(replace('Bana 2 cards "Pernicioso(a)" do seu Cemitério; adicione 2 cards "Pernicioso(a)" do seu Deck à sua mão, exceto "Seletor Pernicioso", com nomes diferentes uns dos outros e dos cards banidos. \r\nVocê só pode ativar 1 "Seletor Pernicioso" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18386170,'Dante, Peregrino do Abismo Ardente',replace(replace('3 monstros "Abismo Ardente" com nomes diferentes	\r\nDeve ser Invocado por Invocação-Fusão e não pode ser Invocado por Invocação-Especial de nenhuma outra forma. \r\nNão pode ser escolhido como alvo de efeitos de card do oponente. \r\nUma vez por turno, durante o turno de qualquer duelista: você pode enviar 1 card "Abismo Ardente" da sua mão para o Cemitério; compre 1 card. \r\nSe este card for destruído em batalha e enviado para o Cemitério, ou se este card que você controla for enviado para o seu Cemitério por um efeito de card do oponente: você pode enviar 1 card aleatório da mão do seu oponente para o Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18407024,'Wattbetta','Se este card causar dano de batalha ao seu oponente em um ataque direto: faça com que seu oponente descarte 1 card que ele selecionar.','Descartar 1 card','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18426196,'Nobre Cavaleiro Joan',replace(replace('Se este card atacar, ele perde 300 de ATK apenas durante a Etapa de Dano. \r\nSe este card em sua posse for destruído por um card do seu oponente e enviado para o seu Cemitério: você pode enviar 1 card da sua mão para o Cemitério e, depois, escolha 1 monstro Guerreiro de Nível 4 ou menos no seu Cemitério; adicione o alvo à sua mão.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18430390,'Rinoceronte Alado','Durante o turno de qualquer duelista, quando um Card de Armadilha for ativado (exceto durante a Etapa de Dano): você pode devolver este card com a face para cima do campo para a mão.','Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18438874,'Mente Maligna',replace(replace('Se você controlar um monstro Demônio: ative 1 desses efeitos, de acordo com o número de monstros no Cemitério do seu oponente;\r\n● 1+: Compre 1 card.\r\n● 4+: Adicione 1 monstro "HERÓI" ou 1 "Fusão Negra" do seu Deck à sua mão.\r\n● 10+: Adicione 1 Magia "Polimerização" ou 1 Magia "Fusão" do seu Deck à sua mão.	\r\nVocê só pode ativar 1 "Mente Maligna" por turno.','\r',char(13)),'\n',char(10)),'Compre 1 card(s)','Adicionar à mão 1 monstro "HERÓI" ou 1 card "Fusão Negra"','Adicionar à mão 1 Card de Magia "Polimerização"','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18444733,'Descarga do Dragão do Trovão',replace(replace('A ativação dos efeitos dos seus monstros Trovão não pode ser negada. \r\nUma vez por turno, se um ou mais monstros "Dragão do Trovão" forem Invocados por Invocação-Normal ou Especial no seu campo: você pode escolher 1 Magia/Armadilha no campo; bana 1 monstro Trovão do seu Deck e, se isso acontecer, destrua o alvo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18444902,'Cavaleiro Tatakawa','Se a ativação de um de seus Cards de Magia/Armadilha for negada por um efeito de card do seu oponente: você pode enviar este card da sua mão para o Cemitério; cause 1500 de dano ao seu oponente.','Causar dano aos PV','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18446701,'Gagagaescudo',replace(replace('Escolha 1 monstro Mago que você controla; equipe este card no alvo. \r\nDuas vezes por turno, ele não pode ser destruído em batalha ou por efeitos de card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18458255,'Torre de Sonhos da Princesa Nemleria',replace(replace('Você pode banir, com a face para baixo, 2 cards com a face para baixo do seu Deck Adicional; adicione 2 monstros Besta de Nível 10 com nomes diferentes do seu Deck à sua mão. \r\nVocê não pode Invocar monstros por Invocação-Especial do Deck Adicional no turno em que ativar este efeito, exceto Monstros Pêndulo. \r\nVocê só pode usar este efeito de "Torre de Sonhos da Princesa Nemleria" uma vez por turno. \r\nSe um ou mais monstros "Nemleria" que você controla seriam destruídos em batalha ou por um efeito de card do oponente, enquanto você tiver "Nemleria Sonhadora" com a face para cima no seu Deck Adicional, em vez disso, você pode banir, com a face para baixo, 1 card com a face para baixo do seu Deck Adicional.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18474999,'Diabretiço Livropedra',replace(replace('Você pode revelar 1 Magia de Ritual na sua mão; Invoque por Invocação-Especial tanto este card da sua mão quanto 1 monstro "Diabretiço" do seu Deck, exceto "Diabretiço Livropedra". \r\nSe este card for Invocado por Invocação-Especial do Deck: você pode escolher 1 Magia de Ritual no seu Cemitério; adicione-a à sua mão. \r\nVocê só pode usar 1 efeito de "Diabretiço Livropedra" por turno e apenas uma vez por turno. \r\nVocê não pode Invocar monstros por Invocação-Especial do Deck Adicional.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18478530,'Chama de Loge',replace(replace('Enquanto você controlar um monstro "Valquíria-", os monstros que seu oponente controla com 2000 ou menos de ATK não podem atacar. \r\nSe este card em sua posse for destruído por um efeito de card do oponente: você pode Invocar por Invocação-Especial 1 monstro "Valquíria-" de Nível 5 ou mais da sua mão ou do Deck.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18482473,'Lampejo H.E.R.O.!',replace(replace('Ative 1 desses efeitos;\r\n● Se um monstro "HERÓI do Elemento" seu atacar um monstro em Posição de Defesa neste turno, cause dano de batalha perfurante ao seu oponente.\r\n● Escolha cards que seu oponente controla, até o número de monstros "HERÓI do Elemento" que você controla; destrua esses cards.\r\n● Adicione à sua mão ou Invoque por Invocação-Especial 1 monstro "HERÓI do Elemento" do seu Cemitério.\r\n● Monstros "HERÓI do Elemento" podem atacar diretamente neste turno.	\r\nVocê só pode ativar 1 "Lampejo H.E.R.O.!" por turno.','\r',char(13)),'\n',char(10)),'Ativar','Dano perfurante','Destruir 1 card','Recuperar do Cemitério','Ataque direto','','','','','','','','','','','');
INSERT INTO texts VALUES(18482591,'Bruxo da Barreira de Gelo','Enquanto você controlar outro monstro "Barreira de Gelo", os dois duelistas devem Baixar Cards de Magia antes de ativá-los e não podem ativá-los até seu próximo turno.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18486927,'Dispositivo do Mecanismo Antigo',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode declarar 1 tipo de card (Monstro, Magia ou Armadilha); neste turno, se um monstro seu atacar, seu oponente não pode ativar Cards de Magia/Armadilha ou efeitos de monstro (o que foi declarado) até o final da Etapa de Dano. \r\nUma vez por turno: você pode declarar 1 nome de card de monstro "Dispositivo"; até a Fase Final, o nome deste card se torna esse nome.','\r',char(13)),'\n',char(10)),'Declarar um nome de monstro','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18489208,'Figo Amaldiçoado','Quando este card for destruído em batalha e enviado para o Cemitério: escolha 2 Cards de Magia/Armadilha Baixados no campo; enquanto este card estiver no Cemitério, esses cards Baixados não podem ser ativados.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18491580,'Dragão Negro Alternativo de Olhos Vermelhos',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro deve ser Invocado por Invocação-Especial (da sua mão) ao oferecer como Tributo 1 monstro "Olhos Vermelhos" da sua mão ou do campo. \r\nVocê só pode Invocar "Dragão Negro Alternativo de Olhos Vermelhos" por Invocação-Especial uma vez por turno desta forma. \r\nSe este card for destruído em batalha ou se este card em posse do seu dono for destruído por um efeito de card do oponente: você pode escolher 1 monstro "Olhos Vermelhos" de Nível 7 ou menos no seu Cemitério, exceto "Dragão Negro Alternativo de Olhos Vermelhos"; Invoque-o por Invocação-Especial e se ele era um "Dragão Negro de Olhos Vermelhos" que tenha sido Invocado por Invocação-Especial, seu ATK original se torna o dobro.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18494511,'Gelojade Ran Aegirine',replace(replace('O nome deste card se torna "Berço Enion, Cenote de Gelojade" enquanto estiver equipado com um Card de Equipamento. \r\nVocê pode descartar 1 outro card "Gelojade" ou monstro de ÁGUA; Invoque este card por Invocação-Especial da sua mão e, depois, você pode Invocar por Invocação-Especial 1 "Ficha Gelojade" (Aqua/ÁGUA/Nível 3/ATK 0/DEF 0). \r\nEnquanto essa Ficha estiver na Zona de Monstros, o duelista que a Invocou não pode Invocar por Invocação-Especial do Deck Adicional, exceto monstros de ÁGUA. \r\nVocê só pode usar este efeito de "Gelojade Ran Aegirine" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Invocar uma Ficha por Invocação Especial?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18494512,'Ficha Gelojade','Invocado por Especial com o efeito "Gelojade Ran Aegirine".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18511384,'Recuperação de Fusão','Escolha 1 "Polimerização" no seu Cemitério e 1 monstro no seu Cemitério que foi usado como matéria para uma Invocação-Fusão; adicione-os à sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18511599,'Solda Evolzar',replace(replace('2 monstros Dinossauro de Nível 6	\r\nNão pode ser destruído por efeitos de card enquanto tiver matéria. \r\nQuando seu oponente Invocar um ou mais monstros por Invocação-Especial (exceto durante a Etapa de Dano): você pode desassociar 1 matéria deste card; destrua esse(s) monstro(s).','\r',char(13)),'\n',char(10)),'Destruir um monstro','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18514525,'Fuga dos Travesso-Guris',replace(replace('2 monstros "Travesso-Guris"	\r\nSe este card for Invocado por Invocação-Fusão: você pode fazer com que este card perca 1000 de ATK neste turno e, além disso, ele pode atacar diretamente neste turno. \r\nVocê pode oferecer este card como Tributo e, depois, escolha 2 Monstros "Travesso-Guris" que não sejam de Fusão com nomes diferentes no seu Cemitério; Invoque-os por Invocação-Especial, mas eles não podem atacar neste turno. \r\nVocê só pode usar cada efeito de "Fuga dos Travesso-Guris" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18517177,'Explosão de Núcleo',replace(replace('Você só pode ativar o efeito deste card enquanto você controlar um monstro "Koa''ki Meiru" com a face para cima. \r\nUma vez por turno, durante sua Fase de Apoio, se seu oponente controlar mais monstros do que você, você pode destruir um número de cards que seu oponente controla para que seu oponente controle o mesmo número de cards que você controla de monstros.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18548966,'Desafiante Heroico - Chicote d''armas',replace(replace('Se você controlar 2 ou mais monstros Guerreiro: você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 Magia/Armadilha "Heroico(a)" do seu Deck à sua mão. \r\nSe este card estiver no seu Cemitério e seus PV forem 500 ou menos: você pode Invocar este card por Invocação-Especial, mas negue seus efeitos. \r\nVocê só pode usar cada efeito de "Desafiante Heroico - Chicote d''armas" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18551923,'Medusa, a Observadora do Olho Maligno',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode escolher 1 card "Olho Maligno" no seu Cemitério, exceto "Medusa, a Observadora do Olho Maligno"; adicione-o à sua mão. \r\nSe este card estiver equipado com "Olho Maligno de Selene" (Efeito Rápido): você pode escolher 1 monstro no Cemitério do seu oponente; bana-o. \r\nVocê só pode usar este efeito de "Medusa, a Observadora do Olho Maligno" uma vez por turno. \r\nUma vez por turno, durante a próxima Fase de Apoio depois que este efeito foi ativado: bana 1 card no seu Cemitério.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Banir 1 monstro do Cemitério do seu oponente','Banir 1 card do seu Cemitério','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18558867,'Caverguerra Bashileos',replace(replace('Durante uma Fase de Batalha na qual um monstro Guerreiro de TERRA seu batalhar (Efeito Rápido): você pode ativar este efeito; este card pode atacar diretamente neste turno e, além disso, todos os monstros "Caverguerra" que você controla atualmente ganham 200 de ATK até o final do turno do seu oponente. \r\nEnquanto este card estiver na sua mão ou no Cemitério, quando um monstro Guerreiro de TERRA seu for destruído em batalha: você pode Invocar este card por Invocação-Especial, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar cada efeito de "Caverguerra Bashileos" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18563744,'Corte da Espada Silenciosa',replace(replace('Escolha 1 monstro "Espadachim Silencioso" que você controla; esse monstro que você controla ganha 1500 de ATK e DEF e, se isso acontecer, até o final deste turno, ele não é afetado pelos efeitos de card do seu oponente. \r\nA ativação e efeito deste card não podem ser negados. \r\nVocê pode banir este card do seu Cemitério; adicione 1 monstro "Espadachim Silencioso" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Aumentar ATK/DEF','Procurar no Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18585765,'Voltestador',replace(replace('Se este card for Invocado por Invocação-Especial em uma zona para a qual um Monstro Link apontar: destrua todos os Monstros Link que apontarem para este card e, depois, destrua todos os outros monstros para os quais esses Monstros Link apontarem e siga as Flechas Link de todos esses monstros destruídos, destruindo tudo para o que eles apontarem e repita o processo até não haver mais nada que destruir.	\r\n(Este card não pode ser destruído por este efeito.) \r\nVocê só pode usar este efeito de "Voltestador" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18590133,'Goblin Rei',replace(replace('Enquanto você controlar outro monstro Demônio, monstros não podem atacar este card. \r\nO ATK/DEF deste card se tornam o número de outros monstros Demônio no campo x 1000.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18591904,'Destino Final',replace(replace('Descarte 5 cards da sua mão. \r\nDestrua todos os cards no campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18595008,'Predaplanta Lirilagarto',replace(replace('Se você controlar um monstro "Predaplanta" ou "Peçonha Insaciável" e este card estiver na sua mão: você pode Invocar este card por Invocação-Especial e, depois, você pode adicionar 1 "Polimerização" do seu Deck à sua mão. \r\nVocê pode escolher 1 monstro com a face para cima no campo; ele se torna de TREVAS até o final deste turno. \r\nSe este card for Invocado por Invocação-Especial do Cemitério: você pode comprar 1 card. \r\nVocê só pode usar cada efeito de "Predaplanta Lirilagarto" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Alterar o Atributo','Comprar','Adicionar à mão?','','','','','','','','','','','','');
INSERT INTO texts VALUES(18597560,'Revolução Cibernética',replace(replace('Ofereça como Tributo 1 "Dragão Cibernético"; Invoque por Invocação-Especial 1 Monstro de Fusão do seu Deck Adicional que liste um monstro "Dragão Cibernético" como matéria, mas ele não pode atacar diretamente e é destruído durante a Fase Final do próximo turno. \r\nVocê só pode ativar 1 "Revolução Cibernética" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18605135,'Barreira Tornado',replace(replace('Ative apenas se "Umi" estiver no campo. \r\nEnquanto "Umi" estiver no campo, você não sofre dano de batalha. \r\nSe "Umi" não estiver no campo, destrua este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18616294,'Gray Layer',replace(replace('Você pode oferecer este card como Tributo e, depois, revele 1 monstro Máquina na sua mão; adicione 1 monstro Máquina com um Atributo diferente do seu Deck à sua mão e, depois, se você adicionou um monstro com 1200 ou menos de ATK, você pode Invocar por Invocação-Especial 1 monstro Máquina da sua mão. \r\nSe um ou mais monstros em sua posse forem destruídos por um efeito de card, enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode banir este card; destrua 1 card no campo. \r\nVocê só pode usar cada efeito de "Gray Layer" uma vez por turno.','\r',char(13)),'\n',char(10)),'Efeito de busca','Efeito de destruição','Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18621798,'Avatar do Rei de Fogo Arvata',replace(replace('Quando um efeito de monstro for ativado enquanto este monstro estiver no campo (Efeito Rápido): você pode negar a ativação e, se isso acontecer, destrua 1 outro monstro de FOGO na sua mão ou no campo com a face para cima. \r\nSe este card for destruído e enviado para o Cemitério: você pode escolher 1 monstro Besta, Besta-Guerreira ou Besta Alada de FOGO no seu Cemitério, exceto "Avatar do Rei de Fogo Arvata"; Invoque-o por Invocação-Especial, mas negue seus efeitos e, além disso, destrua-o durante a Fase Final. \r\nVocê só pode usar cada efeito de "Avatar do Rei de Fogo Arvata" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18631392,'Ma''at',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nVocê deve Invocá-lo por Invocação-Especial (da sua mão) ao enviar 1 monstro de LUZ do Tipo Dragão e 1 monstro de LUZ do Tipo Fada que você controla para o Cemitério e não pode ser Invocado por Invocação-Especial de nenhuma outra forma. \r\nUma vez por turno: você pode declarar 3 nomes de card; escave os 3 cards do topo do seu Deck, adicione à sua mão qualquer um que você tenha nomeado e, além disso, envie os cards restantes para o Cemitério. \r\nO ATK e a DEF deste card se tornam iguais ao número de cards adicionados à sua mão por este efeito x 1000.','\r',char(13)),'\n',char(10)),'Declare o nome de um card','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18634367,'Tela Vermelha',replace(replace('Os monstros do seu oponente não podem declarar ataques. \r\nDurante cada uma das suas Fases Finais, você deve pagar 1000 PV (isso não é opcional) ou este card é destruído. \r\nVocê pode escolher 1 monstro Regulador de Nível 1 no seu Cemitério; destrua este card e, se isso acontecer, Invoque o alvo por Invocação-Especial. "Dragão Vermelho Arquidemônio" deve estar no campo para que você possa ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18654201,'Crio-Esfinge','Enquanto este card permanecer no seu Campo com a face para cima, quando um monstro é devolvido do Campo para a mão do seu dono, o dono do card devolvido escolhe e envia 1 card da sua mão para o Cemitério.','Enviar 1 card da sua mão para o Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18658572,'Circo Goblin','Uma vez por turno, durante sua Fase Final: revele o card do fundo do seu Deck e, depois, coloque-o no topo do Deck ou bana-o com a face para baixo.','Revelar o Deck','Banir com a face para baixo?','Banir com a face para baixo','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18666161,'Despiano Proskenion',replace(replace('1 monstro "Despia" + 1 monstro de LUZ + 1 monstro de TREVAS	\r\nDurante a Fase Principal (Efeito Rápido): você pode escolher 1 Monstro de Fusão, Sincro, Xyz ou Link no Cemitério do seu oponente; bana-o ou Invoque-o por Invocação-Especial no seu campo. \r\nQuando este card destruir um monstro do oponente em batalha: você pode causar dano ao seu oponente igual ao ATK ou DEF original desse monstro (o que for maior). \r\nVocê só pode usar cada efeito de "Despiano Proskenion" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18678554,'Ladrão do Tempo Volteador',replace(replace('Escolha 1 Monstro Xyz "Ladrão do Tempo" que você controla; associe 1 card "Ladrão do Tempo" da sua mão ou do Deck a ele como matéria. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 Monstro Xyz "Ladrão do Tempo" que você controla; associe 1 card do Cemitério do seu oponente a ele como matéria. \r\nVocê só pode usar 1 efeito de "Ladrão do Tempo Volteador" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Usar seu card como Matéria Xyz','Usar o card do seu oponente como Matéria Xyz','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18698739,'Ogro do Lixo',replace(replace('Você pode enviar este card da sua mão para o Cemitério; adicione 1 "Senhor do Lixo" do seu Deck à sua mão. \r\nVocê só pode usar o efeito de "Ogro do Lixo" uma vez por turno.','\r',char(13)),'\n',char(10)),'Procurar no Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18710707,'O Furioso Rei dos Mares','O Grande Rei dos Sete Mares é capaz de invocar um tsunami para afogar os inimigos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18711696,'Guerreiro Sônico de Assalto',replace(replace('Se você controlar "Guerreiro Sucata", "Ativar Modo de Ataque" ou um card que mencione qualquer um desses cards: você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 monstro "Sincron" ou 1 "Ativar Modo de Ataque" do seu Deck à sua mão. \r\nSe este card for enviado para o Cemitério como Matéria Sincro: pelo resto deste turno, você pode fazer com que todos os monstros que você controla ganhem 500 de ATK. \r\nVocê só pode usar cada efeito de "Guerreiro Sônico de Assalto" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Adicionar à mão','Aumentar ATK','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18712704,'Força Inférnica',replace(replace('Só pode ser ativado quando um monstro "Inférnico(a)" for selecionado como alvo de um ataque enquanto você não tiver cards na sua mão. \r\nDestrua o monstro atacante e Invoque por Invocação-Especial 1 monstro "Inférnico(a)" do seu Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18716735,'Rarometalmorfose Bismáquina',replace(replace('Escala de Pêndulo = 8\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno: você pode escolher 1 outro card com a face para cima que você controla; destrua-o e, se isso acontecer, Baixe 1 Magia/Armadilha "Metalmorfose" diretamente do seu Deck.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe este card no campo for destruído em batalha ou por um efeito de card: você pode adicionar 1 monstro "Metalmorfose" do seu Deck à sua mão durante a Fase Final deste turno. \r\nVocê só pode usar este efeito de "Rarometalmorfose Bismáquina" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18720257,'A Previsão do Clima',replace(replace('Quando este card for ativado: você pode colocar 1 Magia/Armadilha "do Clima" do seu Deck com a face para cima na sua Zona de Magias & Armadilhas. \r\nVocê só pode usar cada um dos seguintes efeitos de "A Previsão do Clima" uma vez por turno. \r\nSe você Invocar por Invocação-Link um Monstro Link "do Clima", você também pode usar cards "do Clima" com a face para cima na sua Zona de Magias & Armadilhas como monstros "do Clima" para sua Invocação-Link. \r\nDurante sua Fase Principal, você pode: imediatamente depois que este efeito resolver, Invoque por Invocação-Normal 1 monstro "do Clima" da sua mão. \r\nVocê só pode ativar 1 "A Previsão do Clima" por turno.','\r',char(13)),'\n',char(10)),'','Colocar 1 Card de Magia/Armadilha "do Clima"?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18724123,'Arqueiro Inférnico','Se você não tiver cards em sua mão, este card pode atacar diretamente seu oponente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18738846,'Urânia Astrazma',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) ao devolver 1 ou 2 monstros que você controla para a mão. \r\nVocê só pode Invocar "Urânia Astrazma" por Invocação-Especial uma vez por turno desta forma. \r\nVocê só pode usar cada um dos seguintes efeitos de "Urânia Astrazma" uma vez por turno. \r\nSe este card for Invocado por Invocação-Especial: você pode revelar qualquer número de monstros na sua mão com Níveis diferentes e, depois, escolha esse número de cards com a face para cima que seu oponente controla; negue seus efeitos. \r\nSe este card no campo for destruído por um efeito de card e enviado para o Cemitério: você pode adicionar este card à sua mão.','\r',char(13)),'\n',char(10)),'','Negar','Retornar para a mão','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18739764,'Poção de Destruição',replace(replace('Escolha 1 monstro que você controla. \r\nDestrua-o e ganhe PV igual ao seu ATK.','\r',char(13)),'\n',char(10)),'Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18743376,'Dragão Tirano Metafis',replace(replace('Se este card foi Invocado por Invocação-Especial pelo efeito de um monstro "Metafis", ele não pode ser afetado por efeitos de Armadilha e, além disso, se ele atacar um monstro, ele pode realizar um segundo ataque em seguida. \r\nSe este card for banido, durante a Fase de Apoio do próximo turno: você pode embaralhar este card banido no Deck; Invoque por Invocação-Especial 1 monstro "Metafis" da sua mão, mas bana-o durante a Fase Final do próximo turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18752707,'Ilusão da Estrela Mágica','Se seu oponente controlar um ou mais monstros e você controlar tantos monstros ou menos: até o final deste turno, os monstros que estiverem atualmente no campo ganham ATK igual ao Nível combinado de todos os monstros que o controlador dele controla atualmente x 100.','Alterar ATK/DEF','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18752938,'Semente do Engano','Invoque por Invocação-Especial 1 monstro do Tipo Planta de Nível 2 ou menos da sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18756904,'Presente de Grego','Envie para o Cemitério 1 Monstro que não seja de Efeito com a face para cima que você controla; compre 2 cards.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18760514,'Malhador Louco',replace(replace('O nome deste card se torna "Zumbi Espalha-praga" enquanto estiver no campo ou no Cemitério. \r\nSe este card estiver no seu Cemitério: você pode escolher 1 monstro de Nível 6 ou mais que você controla; reduza o Nível dele em 2 e, se isso acontecer, Invoque este card por Invocação-Especial e, além disso, o duelista que o Invocou não pode Invocar monstros por Invocação-Especial, exceto monstros Zumbi, enquanto este card estiver com a face para cima na Zona de Monstros. \r\nVocê só pode usar este efeito de "Malhador Louco" uma vez por turno.','\r',char(13)),'\n',char(10)),'Escolha o monstro cujo Nível será reduzido','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18789533,'Dotscaper',replace(replace('Se este card for enviado para o Cemitério: você pode Invocar este card por Invocação-Especial. \r\nSe este card for banido: você pode Invocar este card por Invocação-Especial. \r\nVocê só pode usar 1 efeito de "Dotscaper" por turno e apenas uma vez por turno. \r\nVocê só pode usar cada efeito de "Dotscaper" uma vez por Duelo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18795635,'Experimento Aplicado GMX nº 55',replace(replace('Escave cards do topo do seu Deck até que tenha escavado um monstro "GMX" e um monstro Dinossauro, perca 400 PV para cada card escavado e, depois, você pode Invocar por Invocação-Fusão 1 Monstro de Fusão "GMX" do seu Deck Adicional, usando quaisquer monstros escavados como matéria e, além disso, embaralhe o resto no Deck. \r\nVocê só pode ativar 1 "Experimento Aplicado GMX nº 55" por turno.','\r',char(13)),'\n',char(10)),'','Invocação Fusão?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18803791,'Ritual do Dragão Negro',replace(replace('Este card é usado para a Invocação-Ritual de "Paladino do Dragão Negro". \r\nVocê também deve oferecer como Tributo monstros da sua mão ou do campo cuja soma dos Níveis seja 4 ou mais. \r\nDurante sua Fase Principal, exceto no turno em que este card foi enviado para o Cemitério: você pode banir este card do seu Cemitério; adicione 1 Magia/Armadilha "Olhos Vermelhos" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18807108,'Círculo da Profecia',replace(replace('Ative este card ao escolher 1 monstro que seu oponente controla; ele não pode atacar ou mudar sua posição de batalha. \r\nQuando esse monstro for destruído, destrua este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18807109,'Círculo da Profecia',replace(replace('Ative este card ao escolher 1 monstro que seu oponente controla; ele não pode atacar ou mudar sua posição de batalha. \r\nQuando esse monstro for destruído, destrua este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18809562,'Porta do Contrato Mágico','Adicione 1 Card de Magia da sua mão à mão do seu oponente e, depois, adicione 1 monstro de TREVAS de Nível 7 ou 8 do seu Deck à sua mão.','Escolha o card para adicionar à mão do seu oponente','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18816758,'Onda de Infestação','Devolva 1 monstro "Hordeum Ferro" Invocado por Invocação-Tributo com a face para cima que você controla à mão para escolher 1 card que seu oponente controla; destrua esse alvo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18828179,'Peixe-Crânio',replace(replace('Você pode Invocar este card por Invocação-Especial ao oferecer como Tributo 1 "Guardador do Oceano". \r\nVocê pode descartar 1 monstro de ÁGUA para o Cemitério para destruir 1 card com a face para baixo.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18832779,'Navio Saquepatrollha Lys',replace(replace('2 monstros "Saquepatrollha"	\r\nDurante a Fase Principal (Efeito Rápido): você pode Invocar por Invocação-Especial 1 Card de Monstro "Saquepatrollha" da sua mão ou com a face para cima na Zona de Magias & Armadilhas. \r\nQuando seu oponente ativar um efeito de monstro (Efeito Rápido): você pode descartar 1 card "Saquepatrollha"; negue a ativação e, se isso acontecer, destrua-o e, depois, se este card estiver equipado com um card "Saquepatrollha", você pode adicionar 1 card "Saquepatrollha" do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "Navio Saquepatrollha Lys" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Negar a ativação','Adicionar "Saquepatrollha" do seu Deck à sua mão?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18837926,'Capitão Motivador','Quando este card for Invocado por Invocação-Normal: você pode escolher 1 monstro de Nível 4 ou menos no seu Cemitério; Invoque-o por Invocação-Especial em Posição de Defesa, mas ele tem seus efeitos negados.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18842395,'Invasor de Poder','Se seu oponente controlar 2 ou mais monstros, você pode Invocar este card por Invocação-Normal sem oferecer Tributo.','Invocação Normal sem Tributo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18843291,'Minerva, a Luminosa Ateniense',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nMonstros "Luminoso(a)" que você controla não podem ser banidos por efeitos de card. \r\nVocê só pode usar cada um dos seguintes efeitos de "Minerva, a Luminosa Ateniense" uma vez por turno. \r\nSe este card for Invocado por Invocação-Sincro: você pode enviar monstros "Luminoso(a)" com Tipos diferentes do seu Deck para o Cemitério, até o número de monstros "Luminoso(a)" usados como matéria para este card. \r\nVocê pode banir até 4 monstros "Luminoso(a)" do seu Cemitério; envie esse número de cards do topo do seu Deck para o Cemitério.','\r',char(13)),'\n',char(10)),'Enviar do Deck para o Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18847598,'Fera Cristalina Avançada Mamute Âmbar',replace(replace('Se "Trevas Avançadas" não estiver em uma Zona do Campo, envie este monstro para o Cemitério. \r\nUma vez por turno, quando seu oponente ativar um card ou efeito que escolha como alvo um ou mais dos seus cards "Fera Cristalina Avançada" ou "Trevas Avançadas" (Efeito Rápido): você pode negar a ativação. \r\nUma vez por turno, quando um monstro "Fera Cristalina Avançada" seu for escolhido como alvo de um ataque: você pode negar o ataque. \r\nSe este card com a face para cima for destruído em uma Zona de Monstros, em vez de enviá-lo para o Cemitério, você pode colocá-lo com a face para cima na sua Zona de Magias & Armadilhas como uma Magia Contínua.','\r',char(13)),'\n',char(10)),'Negar a ativação','Negar o ataque','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18859369,'Grepher Caótico',replace(replace('Enquanto estiver com a face para cima no campo, este card também é de Atributo TREVAS. \r\nVocê pode descartar 1 monstro de LUZ ou de TREVAS; envie do seu Deck para o Cemitério 1 monstro de LUZ ou de TREVAS com um Atributo diferente que o do monstro descartado, mas pelo resto deste turno, você não pode Invocar por Invocação-Especial monstros com o mesmo nome que o do enviado para o Cemitério por este efeito. \r\nVocê só pode usar este efeito de "Grepher Caótico" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18861006,'Pégaso Asas de Fogo Carmesim',replace(replace('Se seu oponente controlar mais monstros que você, você pode Invocar este card por Invocação-Especial (da sua mão) e, se isso acontecer, ele pode atacar diretamente neste turno. \r\nVocê só pode Invocar "Pégaso Asas de Fogo Carmesim" por Invocação-Especial uma vez por turno desta forma. \r\nQuando seu oponente ativar um efeito de monstro no campo (Efeito Rápido): você pode causar dano ao seu oponente igual ao número do Elo de Corrente deste efeito x 300 e, além disso, este card não pode ser destruído por efeitos ativados antes dele nesta Corrente. \r\nVocê só pode usar este efeito de "Pégaso Asas de Fogo Carmesim" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Causar dano','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18865703,'ZW - Escudo Supremo',replace(replace('Quando este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 de seus Monstros Xyz banidos; Invoque o alvo por Invocação-Especial com a face para cima em Posição de Defesa. \r\nVocê pode escolher 1 monstro "Utopia" que você controla; equipe este monstro no campo ao alvo. \r\nEle ganha 2000 de DEF. \r\nVocê só pode controlar 1 "ZW - Escudo Supremo" com a face para cima.','\r',char(13)),'\n',char(10)),'Equipar','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18890039,'Primeira Aparição Livromante',replace(replace('Quando este card for ativado: você pode adicionar 1 monstro "Livromante" do seu Deck à sua mão, com um nome diferente que o dos cards que você controla. \r\nDurante sua Fase Principal: você pode Invocar por Invocação-Ritual 1 Monstro de Ritual "Livromante" da sua mão, ao oferecer como Tributo monstros da sua mão ou do campo cuja soma dos Níveis seja igual ou exceda seu Nível. \r\nVocê só pode ativar 1 "Primeira Aparição Livromante" por turno.','\r',char(13)),'\n',char(10)),'Adicionar 1 monstro "Livromante" do seu Deck à sua mão?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18891691,'Rei das Máquinas Perfeitas','Aumente o ATK deste card em 500 pontos por cada monstro do Tipo Máquina no Campo exepto este card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18895832,'Desativamento do Sistema','Pague 1000 PV; bana todos os monstros do Tipo Máquina que seu oponente controla e em seu Cemitérios.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18897163,'D/D/D Armagedom Negro, o Super Rei do Fim',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno, se você tiver um card "D/D" na sua outra Zona de Pêndulo: você pode Invocar por Invocação-Especial 1 Monstro Xyz "D/D/D" do seu Deck Adicional, exceto "D/D/D Armagedom Negro, o Super Rei do Fim".\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\n2 monstros "D/D/D" de Nível 8	\r\nNão pode ser Invocado por Invocação-Pêndulo. \r\nQuando este card for Invocado por Invocação-Xyz: você pode associar 1 Monstro Pêndulo "D/D" com a face para cima do seu Deck Adicional a este card como matéria. \r\nMonstros Pêndulo que você controla não podem ser destruídos por efeitos de card. \r\nUma vez por turno: você pode desassociar 1 matéria deste card e, depois, escolha monstros que seu oponente controla, igual ao número de Monstros Pêndulo que você controla; destrua-os. \r\nSe este card na Zona de Monstros for destruído: você pode colocar este card na sua Zona de Pêndulo.','\r',char(13)),'\n',char(10)),'Invocar um Monstro Xyz "D/D/D" por Invocação Especial','Associar Matéria Xyz','Destrua 1 monstro do seu oponente','Colocar este card na sua Zona de Pêndulo','','','','','','','','','','','','');
INSERT INTO texts VALUES(18905769,'Guivre',replace(replace('Ganha 400 de ATK para cada monstro Dragão que você controla.\r\nQuando este card destrói um monstro por batalha: você pode Invocar por Invocação-Especial 1 "Ficha de Wyvern" (Dragão/LUZ/Nível 1/ATK 400/DEF 400).\r\nDurante a Fase de Batalha ou Fase Principal 2, você pode (Efeito Rápido): imediatamente após ativar esse efeito, realize uma Invocação-Tributo de 1 monstro Dragão com a face para cima. \r\nVocê só pode usar este efeito de "Guivre" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Invocação Especial','Invocação Tributo','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18905770,'Ficha de Wyvern','Invocado por Invocação-Especial pelo efeito de "Guivre".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18914778,'Limo Mutante','Um limo que pode se transformar e assumir a forma e o tamanho de qualquer monstro que ele escolha.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18937875,'Lança em Chamas','Um monstro de FOGO equipado com este card tem seu ATK aumentado em 400 pontos e sua DEF reduzida em 200 pontos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18940556,'Ultimate Tyranno Condutor',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro deve ser Invocado por Invocação-Especial (da sua mão) ao banir 2 monstros Dinossauro do seu Cemitério. \r\nUma vez por turno, durante a Fase Principal (Efeito Rápido): você pode destruir 1 monstro na sua mão ou no campo e, se isso acontecer, coloque todos os monstros com a face para cima que seu oponente controla, com a face para baixo em Posição de Defesa. \r\nEste card pode atacar todos os monstros que seu oponente controla, uma vez cada. \r\nNo começo da Etapa de Dano, se este card atacar um monstro em Posição de Defesa: você pode causar 1000 de dano ao seu oponente e, se isso acontecer, envie esse monstro em Posição de Defesa para o Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18940725,'Brisawntarilho & Tordina',replace(replace('Se este card com a face para cima deixaria o campo, em vez disso, bana-o. \r\nVocê só pode usar cada um dos seguintes efeitos de "Brisawntarilho & Tordina" uma vez por turno e não pode Invocar por Invocação-Especial durante o turno em que ativar qualquer desses efeitos. \r\nSe este card for Invocado por Invocação-Normal: você pode adicionar 1 monstro Besta Alada de Nível 4 ou menos do seu Deck à sua mão e, depois, imediatamente depois que este efeito resolver, você pode Invocar 1 monstro Besta Alada por Invocação-Normal. \r\nSe um monstro Besta Alada for Invocado por Invocação-Normal no seu campo enquanto este card estiver banido: você pode adicionar este card à sua mão.','\r',char(13)),'\n',char(10)),'','Adicionar este card à sua mão','Invocar 1 monstro Besta Alada?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18954366,'Necroquipamento Prismático',replace(replace('Escolha 1 monstro de Nível 4 ou menos no seu Cemitério; Invoque por Invocação-Especial 1 monstro da sua mão com um Nível igual ou menor que o do alvo e, depois, equipe o alvo a ele, mas pelo resto deste turno, você não pode ativar cards, ou os efeitos de cards, com o mesmo nome que o desse card equipado. \r\nEnquanto um monstro estiver equipado ao monstro Invocado por este efeito, ele ganha ATK igual à metade do ATK desse monstro equipado. \r\nVocê só pode ativar 1 "Necroquipamento Prismático" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18960169,'Unidade Goblin de Isca',replace(replace('Quando este card causar Dano de Batalha ao seu oponente, você pode comprar 1 card. \r\nSe este card atacar, ele é colocado em Posição de Defesa no final da Fase de Batalha. \r\nA posição de batalha deste card não pode ser alterada até o final do seu próximo turno, exceto com um efeito de card.','\r',char(13)),'\n',char(10)),'Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18963306,'Dragão Críptico de Olhos das Galáxias',replace(replace('2 monstros de Nível 8	\r\nUma vez por turno: você pode desassociar 1 matéria deste card e, depois, escolha 1 monstro com a face para cima que seu oponente controla; monstros que você controla não podem atacar diretamente seu oponente pelo resto deste turno, exceto este card e, além disso, tome o controle do monstro alvo até a Fase Final, mas enquanto este efeito for aplicado, ele tem seus efeitos negados, seu ATK se torna 3000 e, além disso, seu nome se torna "Dragão Críptico de Olhos das Galáxias".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18964575,'Espantalho Ligeiro','Quando um monstro do oponente declarar um ataque direto (Efeito Rápido): você pode descartar este card; negue o ataque e, depois, encerre a Fase de Batalha.','Negue o ataque e encerre a Battle Phase','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18967507,'Dragão Cibersombrioso',replace(replace('5 Monstros de Efeito "Cibersombrio(a)"	\r\nPrimeiro deve ser Invocado por Invocação-Fusão. \r\nSe este card for Invocado por Invocação-Especial: você pode equipar 1 monstro Dragão ou Máquina do seu Cemitério a este card. \r\nGanha ATK igual ao ATK original do monstro equipado a ele por este efeito. \r\nQuando seu oponente ativar um card ou efeito (Efeito Rápido): você pode enviar 1 Card de Equipamento que você controla para o Cemitério; negue a ativação e, se isso acontecer, destrua esse card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18969888,'Dragion Transcendente Sangenpai',replace(replace('1 Regulador Dragão + 1+ monstros Dragão não-Reguladores	\r\nTodos os monstros que seu oponente controla devem atacar, se possível. \r\nSeu oponente não pode ativar cards ou efeitos durante a Fase de Batalha. \r\nSe este card for Invocado por Invocação-Sincro: você pode colocar todos os monstros no campo em Posição de Ataque. \r\nSe 3 ou mais ataques foram declarados neste turno (Efeito Rápido): você pode Invocar este card por Invocação-Especial do seu Cemitério e, depois, você pode destruir 1 card no campo. \r\nVocê só pode usar este efeito de "Dragion Transcendente Sangenpai" uma vez por Duelo.','\r',char(13)),'\n',char(10)),'Mudar a posição de batalha','','Invocar por Invocação Especial do Cemitério','Destruir 1 card no campo?','Você já usou o terceiro efeito de "Dragion Transcendente Sangenpai"','','','','','','','','','','','');
INSERT INTO texts VALUES(18973184,'Ausência do Marcado',replace(replace('A ativação dos seus cards e efeitos que incluam um efeito que Invoque um Monstro de Fusão por Invocação-Fusão não pode ser negada e, além disso, seu oponente não pode ativar cards ou efeitos quando um monstro for Invocado por Invocação-Fusão desta forma. \r\nSe você Invocar um Monstro de Fusão por Invocação-Fusão: você pode adicionar 1 "Caído de Arbaz", ou 1 monstro que o mencione, do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Ausência do Marcado" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18988391,'Tributo de Amarilis',replace(replace('Durante sua Fase Principal: você pode banir este card do seu Cemitério; neste turno, você pode Invocar 1 monstro por Invocação-Normal oferecendo 1 Tributo a menos. \r\nVocê só pode usar o efeito de "Tributo de Amarilis" uma vez por turno.','\r',char(13)),'\n',char(10)),'Reduzir Tributos necessários','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18988396,'Corvo Milagroso',replace(replace('Escala de Pêndulo = 0\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno, durante sua Fase Principal: você pode Invocar este card por Invocação-Ritual, ao oferecer como Tributo monstros da sua mão ou do campo cuja soma dos Níveis seja igual ou exceda 1.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nVocê pode Invocar este card por Invocação-Ritual com "Corvo Milagroso". \r\nDeve ser Invocado por Invocação-Ritual. \r\nEste card Invocado por Invocação-Ritual não é afetado pelos efeitos ativados do seu oponente. \r\nSe você Invocar por Invocação-Ritual exatamente 1 Monstro de Ritual com um efeito de card que requer o uso de monstros, este card que você controla pode ser usado como todo o Tributo. \r\nSe este card for oferecido como Tributo para uma Invocação-Ritual: você pode adicionar 1 Monstro de Ritual do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Corvo Milagroso" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar este card por Invocação Especial','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18993198,'Criaquímica Oxi Ox',replace(replace('Este card é considerado um Monstro Normal enquanto estiver com a face para cima no campo ou no Cemitério. \r\nEnquanto este card for um Monstro Normal no campo, você pode Invocá-lo por Invocação-Normal para fazer com que ele se torne um Monstro de Efeito com este efeito.\r\n● Durante sua Fase Principal: você pode Invocar por Invocação-Especial 1 monstro Gêmeos da sua mão e, se isso acontecer, todos os monstros Gêmeos que você controla atualmente se tornam do Nível original desse monstro até o final deste turno.	\r\nVocê só pode usar este efeito de "Criaquímica Oxi Ox" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19000848,'Buio, a Luz do Alvorecer',replace(replace('Monstros nas suas Zonas de Monstros Principais mais à esquerda ou mais à direita não podem ser destruídos por efeitos de card. \r\nVocê só pode usar cada um dos seguintes efeitos de "Buio, a Luz do Alvorecer" uma vez por turno. \r\nSe este card estiver na sua mão: você pode escolher 1 Monstro de Efeito Demônio que você controla; negue seus efeitos e, se isso acontecer, Invoque este card por Invocação-Especial. \r\nSe este card for enviado para o Cemitério: você pode adicionar 1 "Motim no Céu" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'','Invocação Especial','Adicionar à mão','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19012345,'Gash, o Senhor do Pó','Quando este card causar dano de batalha ao seu oponente: aumente o Nível deste card em 1 (máx. 12).','Aumentar o Nível','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19019586,'Elefante-Gema',replace(replace('Durante sua Fase Principal: você pode devolver este card com a face para cima no campo para a mão. \r\nUma vez por batalha, durante o cálculo de dano, se este card batalhar (Efeito Rápido): você pode enviar 1 Monstro Normal da sua mão para o Cemitério; este card ganha 1000 de DEF apenas durante esse cálculo de dano.','\r',char(13)),'\n',char(10)),'Retornar à mão','Aumentar DEF em 1000','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19024706,'Contra-Ataque de Herói','Quando um monstro "HERÓI do Elemento" que você controla for destruído em batalha: seu oponente seleciona 1 card aleatório da sua mão e, depois, se for um monstro "HERÓI do Elemento", você destrói 1 monstro que seu oponente controla e, se isso acontecer, Invoque o monstro selecionado por Invocação-Especial.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19025379,'Mestre dos Vermelhos',replace(replace('Você pode Invocar este card por Invocação-Ritual com "Transmigração dos Olhos Vermelhos". \r\nUma vez por turno, quando um card ou efeito for ativado, exceto "Mestre dos Vermelhos" (Efeito Rápido): você pode escolher 1 monstro no campo; destrua-o. \r\nUma vez por turno, quando um card ou efeito for ativado, exceto "Mestre dos Vermelhos" (Efeito Rápido): você pode escolher 1 Magia/Armadilha no campo; destrua-a.','\r',char(13)),'\n',char(10)),'Destrua 1 monstro','Destrua 1 Card de Magia/Armadilha','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19027895,'Reviver Salamagrande',replace(replace('Escolha 1 monstro de FOGO no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 monstro "Salamagrande" que você controla e 1 monstro no seu Cemitério com o mesmo nome; embaralhe o monstro do Cemitério no Deck e, se isso acontecer, esse monstro que você controla ganha ATK igual ao seu ATK original até o final deste turno. \r\nVocê só pode usar cada efeito de "Reviver Salamagrande" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19028307,'Bárbaros Ür, o Rei Besta Máquina',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) ao banir 1 monstro do Tipo Máquina e 1 monstro do Tipo Besta-Guerreira da sua mão, campo e/ou Cemitério. \r\nSe este card atacar ou for atacado, seu oponente não sofre dano de batalha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19036557,'Sabrelemento Makani',replace(replace('Uma vez por turno: você pode enviar 1 monstro "Sabrelemento" da sua mão para o Cemitério; adicione 1 monstro "Sabrelemento" ou "Senhor Elemental" do seu Deck à sua mão, exceto "Sabrelemento Makani". \r\nUma vez por turno, se este card estiver no Cemitério: você pode declarar 1 Atributo; este card no Cemitério se torna desse Atributo até o final deste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19041767,'Invocador de Gêmeos',replace(replace('Uma vez por turno, durante a Fase Final do seu oponente: você pode pagar 500 PV; Invoque por Invocação-Normal/Baixe 1 monstro Gêmeos da sua mão ou Invoque por Invocação-Normal 1 monstro Gêmeos com a face para cima que você controla. \r\nNa primeira vez que este card seria destruído em batalha a cada turno, ele não é destruído.','\r',char(13)),'\n',char(10)),'Invocação Normal','Invocação Normal (com a face para cima)','Baixar (com a face para baixo)','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19048328,'Chaofeng, o Fantasma de Yang Zing',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nEnquanto este card Invocado por Invocação-Sincro estiver no campo, seu oponente não pode ativar efeitos de monstros com o(s) mesmo(s) \r\nAtributo(s) original(is) que o(s) monstro(s) "Yang Zing" usados para a Invocação-Sincro deste card. \r\nQuando este card Invocado por Invocação-Sincro for destruído em batalha ou por um efeito de card e enviado para o Cemitério: você pode adicionar 1 Regulador do seu Deck à sua mão. \r\nUma vez por turno, quando um ou mais monstros que seu oponente controla forem destruídos em batalha ou por um efeito de card: você pode Invocar por Invocação-Especial em Posição de Defesa, 1 monstro Wyrm do seu Deck, cujo Atributo original seja o mesmo que o Atributo original de 1 desses monstros destruídos no campo.','\r',char(13)),'\n',char(10)),'Reorganize o Deck e adicione à sua mão','Invocar 1 monstro por Invocação Especial do Deck','Use 1 monstro "Yang Zing" de TERRA como Matéria Sincro','Use 1 monstro "Yang Zing" de ÁGUA como Matéria Sincro','Use 1 monstro "Yang Zing" de FOGO como Matéria Sincro','Use 1 monstro "Yang Zing" de VENTO como Matéria Sincro','Use 1 monstro "Yang Zing" de LUZ como Matéria Sincro','Use 1 monstro "Yang Zing" de TREVAS como Matéria Sincro','Use 1 monstro "Yang Zing" DIVINO como Matéria Sincro','','','','','','','');
INSERT INTO texts VALUES(19050066,'Camarartista Barokuriboh',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno, no começo da Fase de Batalha: você pode adicionar 1 monstro com 300 de ATK/200 de DEF do seu Deck à sua mão e, depois, destrua este card.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nQuando um monstro seu for destruído em batalha: você pode Invocar este card por Invocação-Especial da sua mão. \r\nOs monstros do seu oponente não podem escolher monstros como alvo de ataques, exceto este. \r\nSe este card for atacado, coloque-o em Posição de Ataque no final da Etapa de Dano.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19059929,'Formação de Fogo - Gyokkou',replace(replace('Ative este card ao escolher 1 Magia/Armadilha Baixada que seu oponente controla. \r\nSeu oponente não pode ativar o card alvo em resposta à ativação deste card. \r\nEnquanto este card estiver com a face para cima no campo, esse card Baixado não pode ser ativado. \r\nTodos os monstros Besta-Guerreira que você controla ganham 100 de ATK.','\r',char(13)),'\n',char(10)),'Escolha 1 Card de Magia/Armadilha Baixada que seu oponente controla','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19066538,'Cobra do Mar Rugidora','"Lâmpada Mística" + "Hyosube"','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19086954,'Segundo Goblin',replace(replace('Uma vez por turno, durante a sua Main Phase, você pode equipar este card a "Orc Gigante" como um Card de Magia de Equipamento, OU separar o Equipamento e Invocar, por Invocação-Especial, este card em Posição de Ataque com a face para cima. \r\nQuando este card é equipado pelo efeito deste card, você pode mudar a posição de batalha do monstro equipado uma vez por turno durante a sua Main Phase. \r\n(1 monstro pode ser equipado apenas por 1 Monstro de Union de cada vez. Se o monstro equipado com este card é destruído como resultado de um combate, em vez disso destrúa este card.)','\r',char(13)),'\n',char(10)),'Equipar','Desequipar e Invocar por Invocação Especial (Posição de Ataque com a face para cima)','Altere a posição de batalha do monstro equipado','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19089195,'Ataque Furtivo do Mar',replace(replace('Quando este card for ativado: você pode ativar 1 "Umi" da sua mão ou do Cemitério. \r\nEnquanto "Umi" estiver no campo, este card com a face para cima ganha esses efeitos.\r\n● Uma vez por turno: você pode banir 1 monstro de ÁGUA que você controla até a Fase Final; neste turno, Magias/Armadilhas com a face para cima que você controla não podem ser destruídas pelos efeitos de card do seu oponente (mesmo que este card deixe o campo).\r\n● No começo da Etapa de Dano, se um monstro de ÁGUA seu cujo Nível original seja 5 ou mais batalhar um monstro do oponente: destrua o monstro do oponente.','\r',char(13)),'\n',char(10)),'Ativar "Umi"?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19093698,'Inumano Moissa',replace(replace('O nome deste card se torna "Servo Caveira" enquanto ele estiver no Cemitério. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 "Servo Caveira" ou 1 card que o mencione do seu Deck à sua mão, exceto "Inumano Moissa" e, além disso, você não pode Invocar por Invocação-Especial pelo resto deste turno, exceto monstros Zumbi. \r\nVocê só pode usar este efeito de "Inumano Moissa" uma vez por turno. \r\nDurante sua Fase Principal, você pode Invocar por Invocação-Normal 1 monstro Zumbi de Nível 4 ou menos em adição à sua Invocação-Normal/Baixar (padrão). \r\n(Você só pode se aproveitar deste efeito uma vez por turno.)','\r',char(13)),'\n',char(10)),'Adicionar à mão','Invocar pelo efeito de "Inumano Moissa"','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19096726,'Mercourier da Tri-Brigada',replace(replace('Quando seu oponente ativar um efeito de monstro, enquanto você controlar um Monstro de Fusão que mencione "Caído de Arbaz" como matéria (Efeito Rápido): você pode enviar para o Cemitério este card da sua mão ou do campo com a face para cima; negue o efeito. \r\nSe este card for banido: você pode adicionar do seu Deck à sua mão, 1 "Caído de Arbaz", ou 1 monstro que o mencione, exceto "Mercourier da Tri-Brigada". \r\nVocê só pode usar cada efeito de "Mercourier da Tri-Brigada" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19113101,'Interceptomate','Durante o turno do seu oponente: você pode banir este card do seu Cemitério; neste turno, qualquer dano de efeito que você sofrer se torna 0 (este é um Efeito Rápido).','Negar o efeito','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19139516,'Besta de Restolhos',replace(replace('Se este card com a face para cima em Posição de Defesa for escolhido como alvo de um ataque, no final da Fase de Batalha: destrua este card. \r\nSe este card for destruído pelo efeito de um card "Restolhos" e enviado para o Cemitério: você pode escolher 1 monstro "Restolhos" no seu Cemitério, exceto "Besta de Restolhos"; adicione o alvo à sua mão.','\r',char(13)),'\n',char(10)),'Destruir este card','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19144622,'Cauda de Fadas - Matchgiru',replace(replace('Se um monstro Mago com 1850 de ATK original estiver no campo: você pode Invocar este card por Invocação-Especial da sua mão ou do Cemitério e, além disso, você não pode Invocar por Invocação-Especial pelo resto deste turno, exceto monstros Mago. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 Magia/Armadilha "Cauda de Fadas" ou 1 "Conto de Fadas de Caudas" do seu Deck à sua mão. \r\nVocê pode pagar 500 PV; o nome de 1 Monstro de Efeito que seu oponente controla se torna "Príncipe das Fadas". \r\nVocê só pode usar cada efeito de "Cauda de Fadas - Matchgiru" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Efeito de busca','Alterar o nome do card','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19144623,'Príncipe das Fadas','Príncipe das Fadas','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19153590,'Dragão Armado Bate-estacas',replace(replace('Você pode enviar 1 outro monstro Dragão de VENTO ou 1 outro monstro Dragão de Nível 7 ou mais da sua mão para o Cemitério; Invoque este card por Invocação-Especial da sua mão. \r\nVocê pode enviar 1 monstro "Dragão Armado" da sua mão ou do Deck para o Cemitério, exceto "Dragão Armado Bate-estacas" e, depois, escolha 1 monstro com a face para cima que você controla; esse monstro alvo ganha ATK igual ao Nível do monstro enviado para o Cemitério x 300 até o final deste turno e, além disso, você só pode atacar com 1 monstro neste turno. \r\nVocê só pode usar cada efeito de "Dragão Armado Bate-estacas" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19153634,'Aristocrata da Escuridão','Você seleciona os alvos dos ataques do seu oponente.','Alterar o alvo do ataque?','Escolha o novo alvo do ataque','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19159413,'Remover Magia',replace(replace('Escolha 1 Magia com a face para cima ou 1 Magia/Armadilha Baixada no campo; destrua o alvo se for uma Magia. \r\n(Se o alvo estiver Baixado, revele-o.)','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19162134,'Manutenção de Duelo',replace(replace('Para cada duelista, na primeira vez que ele fizer cada uma das seguintes ações a cada turno ele compra 2 cards.\r\n● Invocar por Invocação-Especial 5 monstros com Níveis diferentes ao mesmo tempo.\r\n● Batalhar 5 vezes com 1 monstro que ele controla.\r\n● Ativar um card ou efeito como um Elo de Corrente 5 ou maior.\r\n● Lançar 1 dado de seis faces ou uma moeda, 5 vezes.\r\n● Sofrer dano que baixou seus PV a 500 ou menos.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19163116,'Cavaleiro-Gema Obsidiana','Se este card for enviado da mão para o seu Cemitério: você pode escolher 1 Monstro Normal de Nível 4 ou menos no seu Cemitério; Invoque o alvo por Invocação-Especial.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19181420,'Dragão Gêmeo Mementotlan',replace(replace('2 monstros "Memento"	\r\nQualquer monstro destruído em batalha com um dos seus monstros "Memento" é banido. \r\nVocê só pode usar cada um dos seguintes efeitos de "Dragão Gêmeo Mementotlan" uma vez por turno. \r\nSe este card for Invocado por Invocação-Fusão: você pode destruir 1 monstro "Memento" na sua mão ou no campo com a face para cima e, se isso acontecer, adicione até 2 monstros "Memento" com nomes diferentes do seu Deck à sua mão. \r\nSe este card Invocado por Invocação-Fusão for destruído: você pode Invocar por Invocação-Especial 1 monstro "Memento" de Nível 6 ou menos do seu Cemitério.','\r',char(13)),'\n',char(10)),'Destruir 1 monstro e adicionar à mão 1 monstro "Memento"','Invocar por Invocação Especial 1 monstro "Memento"','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19182751,'Genex Nêutron','Uma vez por turno, durante a Fase Final, se este card foi Invocado por Invocação-Normal neste turno: você pode adicionar 1 monstro Regulador do Tipo Máquina do seu Deck à sua mão.','Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19186123,'Liberar Visão',replace(replace('Escolha 1 Card de Monstro "HERÓI da Visão" na sua Zona de Magias & Armadilhas; Invoque-o por Invocação-Especial. \r\nDurante sua Fase Principal, exceto no turno em que este card foi enviado para o Cemitério: você pode banir este card do seu Cemitério e, depois, escolha 1 monstro "HERÓI da Visão" no seu Cemitério; adicione-o à sua mão.','\r',char(13)),'\n',char(10)),'Invocação Especial','Recuperar do Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19190082,'Valquíria-Carruagem',replace(replace('Uma vez por turno, você pode: escolha 1 monstro Fada que você controla; equipe este card no alvo, OU: desequipe este card e Invoque-o por Invocação-Especial. \r\nSe o monstro equipado seria destruído em batalha ou por um efeito de card, em vez disso, destrua este card. \r\nQuando o monstro equipado declarar um ataque: você pode fazer com que ele ganhe 500 de ATK. \r\n(Este ganho de ATK permanece mesmo que este card deixe o campo.)','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19204398,'Contemplador da Luz, Aliado da Justiça',replace(replace('1 Regulador + 1 ou mais monstros não-Reguladores	\r\nEste card ganha 200 de ATK para cada monstro de LUZ no Cemitério do oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19211362,'Estandarte Nêmeses',replace(replace('Você pode escolher 1 dos seus monstros banidos, exceto "Estandarte Nêmeses"; Invoque este card por Invocação-Especial da sua mão e, se isso acontecer, embaralhe o alvo no Deck. \r\nDurante sua Fase Principal: você pode adicionar 1 monstro "Nêmeses" do seu Deck à sua mão, exceto "Estandarte Nêmeses". \r\nVocê só pode usar cada efeito de "Estandarte Nêmeses" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19221310,'Dragão Sabre de Olhos Anômalos',replace(replace('Se este card estiver na sua mão: você pode oferecer como Tributo 1 monstro de LUZ; envie para o Cemitério 1 "Dragão de Olhos Anômalos" da sua mão, Deck ou do seu lado do campo e, se isso acontecer, Invoque este card por Invocação-Especial. \r\nQuando este card destruir um monstro em batalha e enviá-lo para o Cemitério: você pode destruir 1 monstro que seu oponente controla.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19222426,'Gigante do Trovão, o HERÓI do Elemento - Trovão Voltaico',replace(replace('2 monstros "HERÓI do Elemento" com Atributos diferentes	\r\nDeve ser Invocado por Invocação-Fusão. \r\nSe este card for Invocado por Invocação-Especial e seu oponente controlar mais cards que você: você pode destruir todos os outros cards no campo. \r\nVocê pode oferecer como Tributo este card que foi Invocado por Invocação-Fusão usando um ou mais Monstros Normais como matéria e, depois, escolha 1 monstro "HERÓI do Elemento" no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Gigante do Trovão, o HERÓI do Elemento - Trovão Voltaico" uma vez por turno.','\r',char(13)),'\n',char(10)),'Destruir','Invocação Especial','Invocação Fusão usando um Monstro Normal como matéria','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19230407,'Oferenda dos Condenados','Escolha 1 monstro com a face para cima no campo; destrua o alvo e, além disso, pule sua próxima Fase de Compra.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19230408,'Oferenda dos Condenados','Escolha 1 monstro com a face para cima no campo; destrua o alvo e, além disso, pule sua próxima Fase de Compra.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19252988,'Bloqueador de Armadilhas','Quando seu oponente ativar um Card de Armadilha durante a Fase de Batalha: negue a ativação e, se isso acontecer, destrua-o.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19254117,'Alcançar a Altura Integral',replace(replace('Escolha 1 monstro com a face para cima no campo; dobre sua DEF, mas sua DEF se torna 0 no final deste turno. \r\nVocê pode banir este card do seu Cemitério e, depois, escolher 1 monstro que você controla; os monstros do seu oponente não podem atacar pelo resto deste turno, exceto atacar esse monstro. \r\nVocê só pode ativar 1 "Alcançar a Altura Integral" por turno.','\r',char(13)),'\n',char(10)),'Dobre a DEF dele','Banir este card do seu Cemitério','A DEF dele se torna 0','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19261966,'El Sombraneco Anoyatyllis',replace(replace('1 monstro "Sombraneco" + 1 monstro de ÁGUA	\r\nPrimeiro deve ser Invocado por Invocação-Fusão. \r\nNenhum duelista pode Invocar monstros por Invocação-Especial da mão ou do Cemitério usando efeitos de Magia/Armadilha. \r\nSe este card for enviado para o Cemitério: você pode escolher 1 Magia/Armadilha "Sombraneco" no seu Cemitério; adicione-a à sua mão.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19271881,'O Mais Brilhante e Ardente Rei Marcado',replace(replace('Selecione 1 Monstro de Fusão que você controla que mencione "Caído de Arbaz" como matéria e, até o final deste turno, negue os efeitos de todos os outros cards com a face para cima atualmente no campo. \r\nDurante a Fase Final, se um ou mais Monstros de Fusão foram enviados para o seu Cemitério neste turno: você pode adicionar este card do Cemitério à sua mão. \r\nVocê só pode usar 1 efeito de "O Mais Brilhante e Ardente Rei Marcado" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19272658,'Bento Xyz',replace(replace('Se um ou mais monstros que seu oponente controla forem destruídos em batalha ou enviados para o Cemitério: você pode escolher 1 Monstro Xyz que você controla; associe 1 monstro do Cemitério do seu oponente a esse monstro como matéria. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 monstro no campo Invocado por Invocação-Especial do Deck Adicional; mude sua posição de batalha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19275188,'Gerações Caverguerra',replace(replace('Durante a Fase de Batalha, se seu oponente controlar mais monstros que você: Invoque por Invocação-Especial 1 monstro "Caverguerra" do seu Deck e se você ativou este card durante o turno do seu oponente, pelo resto deste turno enquanto você controlar esse monstro com a face para cima Invocado por Invocação-Especial, os monstros do seu oponente não podem atacar, exceto atacar esse monstro. \r\nVocê só pode ativar 1 "Gerações Caverguerra" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19280589,'Tellus, o Anjo Menor',replace(replace('Se este card for enviado da Zona de Monstros para o Cemitério: você pode Invocar por Invocação-Especial 1 "Ficha de Asa de Tellus" (Fada/LUZ/Nível 1/ATK 0/DEF 0). \r\nEnquanto você controlar uma "Ficha de Asa de Tellus": você pode banir este card do seu Cemitério e 1 Magia da sua mão; Invoque por Invocação-Especial 2 "Ficha de Asa de Tellus" e, além disso, você não pode Invocar por Invocação-Especial pelo resto deste turno, exceto da sua mão. \r\nVocê só pode usar cada efeito de "Tellus, o Anjo Menor" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19280590,'Ficha de Asa de Tellus','Invocado por Especial com o efeito "Tellus, o Anjo Menor".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19299793,'Rei Lótus Vermelho, Crime das Chamas',replace(replace('Durante a Fase Principal, se você controlar um Regulador Demônio, ou seu oponente controlar um monstro Invocado por Invocação-Especial (Efeito Rápido): você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe este card for Invocado por Invocação-Especial: você pode causar 400 de dano ao seu oponente para cada monstro de FOGO que você controla com nomes diferentes. \r\nSe este card for enviado para o Cemitério como Matéria Sincro: você pode enviar 1 Armadilha Normal do seu Deck para o Cemitério. \r\nVocê só pode usar cada efeito de "Rei Lótus Vermelho, Crime das Chamas" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19301729,'Inseto Digital Registrider',replace(replace('Não pode ser usado como Matéria Xyz para uma Invocação-Xyz, exceto a Invocação-Xyz de um monstro Inseto. \r\nQuando você Invocar por Invocação-Normal um monstro Inseto de Nível 3: você pode Invocar este card por Invocação-Especial da sua mão e, depois, você pode tornar de Nível 5 ou 7 tanto este card como esse monstro. \r\nSe este card for Invocado por Invocação-Especial da mão: você pode mudar a posição de batalha de 1 monstro Inseto que você controla. \r\nUm Monstro Xyz que foi Invocado usando este card no campo como matéria ganha este efeito.\r\n● Este card ganha 1000 de ATK/DEF.','\r',char(13)),'\n',char(10)),'','','Alterar o Nível?','O efeito de "Inseto Digital Registrider" está sendo aplicado.','','','','','','','','','','','','');
INSERT INTO texts VALUES(19302550,'D/D Newton, o Erudito',replace(replace('Escala de Pêndulo = 10\r\n[ Efeito de Pêndulo ]\r\nVocê não pode Invocar monstros por Invocação-Pêndulo, exceto monstros "D/D". \r\nEste efeito não pode ser negado. \r\nUma vez, enquanto este card estiver na sua Zona de Pêndulo, você pode negar um efeito de Armadilha ativado que causaria dano a você e, depois, destruir este card.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nVocê pode descartar este card e, depois, escolher 1 card "D/D" ou "Pacto Obscuro" no seu Cemitério, exceto "D/D Newton, o Erudito"; adicione-o à sua mão. \r\nVocê só pode usar este efeito de "D/D Newton, o Erudito" uma vez por turno.','\r',char(13)),'\n',char(10)),'Recuperar cards','Usar o efeito de "D/D Newton, o Erudito"?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19304410,'Springans Kitt da Tri-Brigada',replace(replace('Se você controlar um monstro "Tri-Brigada" ou "Springans", exceto "Springans Kitt da Tri-Brigada": você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe este card for enviado para o Cemitério: você pode Invocar por Invocação-Especial 1 dos seguintes monstros do seu Cemitério em Posição de Defesa, exceto "Springans Kitt da Tri-Brigada".\r\n● Monstro "Tri-Brigada"\r\n● Monstro "Springans"\r\n● "Caído de Arbaz" ou 1 monstro que o mencione\r\nVocê só pode usar cada efeito de "Springans Kitt da Tri-Brigada" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial da mão','Invocar por Invocação Especial do Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19307353,'Escultor de Espíritos',replace(replace('Você pode oferecer 1 monstro como Tributo; adicione 1 monstro do seu Deck à sua mão, cujo ATK/DEF originais combinados seja igual ao ATK/DEF originais combinados do monstro oferecido como Tributo. \r\nVocê só pode usar este efeito de "Escultor de Espíritos" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19310321,'Besta Heráldica Águia de Duas Cabeças',replace(replace('Você pode banir este card do seu Cemitério para escolher 1 Monstro Xyz com a face para cima que você controla sem Matérias Xyz e 2 monstros "Besta Heráldica" em seu Cemitério; associe esses monstros do Cemitério ao Monstro Xyz com a face para cima como Matérias Xyz. \r\nVocê só pode usar o efeito de "Besta Heráldica Águia de Duas Cabeças" uma vez por turno.','\r',char(13)),'\n',char(10)),'Reabastecer matérias','Escolha um Monstro Xyz sem matérias','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19312169,'Talismã de Selar Armadilhas',replace(replace('Ative este card apenas se você controlar "Meisei, Mestre dos Selos". \r\nOs Cards de Armadilha, bem como seus efeitos no campo, não podem ser ativados. \r\nNegue todos os efeitos de Armadilha no campo. \r\nSe você não controlar "Meisei, Mestre dos Selos", destrua este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19316241,'Dragonete de Guerra das Galáxias',replace(replace('Se um ou mais monstros de LUZ de Nível 4 forem Invocados por Invocação-Especial no seu campo (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão (se ele estava lá quando a Invocação resolveu) ou do Cemitério (mesmo se ele não estava), mas bana-o quando ele deixar o campo. \r\nVocê pode escolher 1 outro monstro de LUZ de Nível 4 que você controla; torne de Nível 8 tanto esse monstro quanto este card até o final deste turno. \r\nVocê só pode usar cada efeito de "Dragonete de Guerra das Galáxias" uma vez por turno e, além disso, você não pode Invocar por Invocação-Especial no turno em que ativar qualquer um dos efeitos deste card, exceto monstros de LUZ.','\r',char(13)),'\n',char(10)),'Invocação Especial','O Nível dele se torna 8','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19322865,'Prisioneiro Terrestre Andador da Linha',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 "Prisão Terrestre" ou "Fusão Sincro Harmônica" do seu Deck ou Cemitério à sua mão. \r\nSe você controlar um monstro "Terrestre" de Nível 6 ou mais: você pode banir este card do seu Cemitério e, depois, escolha 1 Monstro de Efeito que seu oponente controla que foi Invocado por Invocação-Especial do Deck Adicional; embaralhe esse Monstro de Efeito com a face para cima no Deck e, depois, seu oponente pode Invocar por Invocação-Especial 1 monstro com o mesmo nome do Deck Adicional dele. \r\nVocê só pode usar cada efeito de "Prisioneiro Terrestre Andador da Linha" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Invocar 1 monstro com o mesmo nome por Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19324993,'Opífice Infernal, o HERÓI Xtra',replace(replace('2 monstros "HERÓI"	\r\nSe este card for Invocado por Invocação-Link: você pode revelar 1 Monstro de Fusão "HERÓI" no seu Deck Adicional e, se isso acontecer, adicione até 2 das Matérias de Fusão mencionadas nesse card, com nomes diferentes, do seu Deck à sua mão. \r\nVocê não pode Invocar monstros por Invocação-Especial no turno em que ativar este efeito, exceto monstros "HERÓI". \r\nVocê só pode usar este efeito de "Opífice Infernal, o HERÓI Xtra" uma vez por turno. \r\nMonstros Demônio para os quais este card apontar ganham ATK/DEF igual ao seu próprio Nível x 100.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19326613,'Era uma Vez a Cauda de Fadas',replace(replace('Invoque por Invocação-Especial até 1 monstro "Cauda de Fadas" de LUZ cada da sua mão, do Cemitério e do banimento, com nomes diferentes e, além disso, você não pode Invocar por Invocação-Especial pelo resto deste turno, exceto monstros Mago. \r\nSe este card for banido, ou enviado para o Cemitério exceto do campo: você pode Baixar este card, mas ele não pode ser ativado a não ser que você controle um monstro "Cauda de Fadas". \r\nVocê só pode usar cada efeito de "Era uma Vez a Cauda de Fadas" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Baixar','O efeito de "Era uma Vez a Cauda de Fadas" está sendo aplicado.','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19327348,'Dharc, o Encantador das Trevas','VIRE: Escolha 1 monstro de TREVAS que seu oponente controla; tome o controle dele enquanto este card estiver com a face para cima no campo.','Ganhe o controle de 1 monstro de TREVAS que seu oponente controla','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19327349,'Dharc, o Encantador das Trevas','VIRE: Escolha 1 monstro de TREVAS que seu oponente controla; tome o controle dele enquanto este card estiver com a face para cima no campo.','Ganhe o controle de 1 monstro de TREVAS que seu oponente controla','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19333131,'Número 12: Ninja da Armadura de Sombras Carmesim',replace(replace('2 monstros de Nível 5	\r\nUma vez por turno, durante o turno de qualquer duelista: você pode desassociar 1 Matéria Xyz deste card; neste turno, monstros "Ninja" com a face para cima que você controla não podem ser destruídos em batalha ou por efeitos de card.','\r',char(13)),'\n',char(10)),'Não pode ser destruído','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19337371,'Sinal Histérico',replace(replace('Quando este card for ativado: adicione 1 "Egotista Elegante" do seu Deck ou Cemitério à sua mão. \r\nDurante a Fase Final, se este card estiver no Cemitério porque foi enviado para lá da mão ou do campo neste turno: adicione até 3 cards "Harpia" com nomes diferentes entre eles do seu Deck à sua mão. \r\nVocê só pode usar 1 efeito de "Sinal Histérico" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Continuar selecionando 1 card cujo nome contenha "Harpia" para adicionar à sua mão?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19338434,'Bifurcação Mimicarniçal',replace(replace('Escolha 1 monstro com a face para baixo que seu oponente controla; seu oponente seleciona 1 dos seguintes efeitos e você aplica esse efeito.\r\n● Coloque-o com a face para cima em Posição de Ataque ou de Defesa.\r\n● Envie-o para o Cemitério e, depois, seu dono compra 2 cards.	\r\nVocê pode banir este card do seu Cemitério; adicione 1 "Bifurcação Mimicarniçal" do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "Bifurcação Mimicarniçal" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar','Esse monstro se torna em Posição de Ataque com a face para cima ou Posição de Defesa com a face para cima','Envie aquele monstro para o Cemitério, depois o dono dele compra 2 cards','Adicionar à mão','','','','','','','','','','','','');
INSERT INTO texts VALUES(19353570,'Cavaleiro Kagemucha',replace(replace('Quando você Invocar um monstro de Nível 3 por Invocação-Normal: você pode Invocar este card por Invocação-Especial da sua mão. \r\nNão pode ser usado como Matéria Sincro.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19355597,'Dama Cavaleiro-Gema Diamante Brilhante',replace(replace('3 monstros "Cavaleiro-Gema"	\r\nPrimeiro deve ser Invocado por Invocação-Fusão com as Matérias de Fusão acima. \r\nVocê só pode Invocar um ou mais "Dama Cavaleiro-Gema Diamante Brilhante" por Invocação-Especial uma vez por turno. \r\nUma vez por turno: você pode enviar 1 monstro "Cavaleiro-Gema" com a face para cima que você controla para o Cemitério e, se isso acontecer, Invoque por Invocação-Especial 1 Monstro de Fusão "Cavaleiro-Gema" do seu Deck Adicional, ignorando suas condições de Invocação.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19357125,'Caçador das Trevas',replace(replace('O efeito deste card muda dependendo do número de monstros de TREVAS no seu Cemitério.\r\n● 1 ou menos: Este card perde 400 de ATK.\r\n● 2 a 4: Este card ganha 400 de ATK.\r\n● 5 ou mais: Você pode enviar este card ao Cemitério para destruir todos os monstros com a face para baixo que seu oponente controla.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19362568,'Refrão do Vento Gélido',replace(replace('Ative 1 dos seguintes efeitos.\r\n● Escolha 1 monstro "Ventobruxa" no seu Cemitério; Invoque-o por Invocação-Especial em Posição de Defesa.\r\n● Quando seu oponente ativar um card ou efeito em resposta à ativação de um efeito de um monstro "Ventobruxa" seu: negue esse efeito do oponente.	\r\nVocê só pode ativar 1 "Refrão do Vento Gélido" por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Negar o efeito','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19369609,'Lirilusc - Turdídeo Livre',replace(replace('2+ monstros de Nível 1	\r\nGanha 500 de ATK para cada matéria associada a ele. \r\nUma vez por turno: você pode desassociar 1 matéria deste card e, depois, escolha 1 Magia/Armadilha que seu oponente controla; embaralhe-a no Deck. \r\nNo começo da Etapa de Dano, se outro monstro que você controla batalhar: você pode desassociar qualquer número de matérias deste card; até o final deste turno, esse monstro que você controla ganha 300 de ATK para cada matéria desassociada.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19384334,'Destruição por Derretimento','Aumente em 500 o ATK de todos os monstros de FOGO e diminua em 400 suas DEF.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19394153,'Disparo de Pena','Escolha 1 "Aviário, o HERÓI do Elemento" que você controla com a face para cima; durante este turno, o alvo pode atacar um número de vezes igual ao número de monstros que você controla quando este card resolver, mas não pode atacar diretamente, e outros monstros que você controla não podem atacar durante este turno.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19403423,'Morganita Corta-Tempo',replace(replace('Pelo resto deste Duelo, aplique os seguintes efeitos.\r\n● Você não pode ativar efeitos de monstro na mão.\r\n● Compre 2 cards em vez de 1 em sua compra normal durante sua Fase de Compra.\r\n● Você pode conduzir 2 Invocações-Normal/Baixar por turno, não apenas 1.	\r\nVocê pode banir este card do seu Cemitério e, depois, descarte 1 "Morganita Corta-Tempo"; seu oponente não pode ativar efeitos de monstro quando você Invocar por Invocação-Normal neste turno.','\r',char(13)),'\n',char(10)),'Aplicar efeitos','Banir este card do seu Cemitério','O efeito de "Morganita Corta-Tempo" está sendo aplicado.','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19406822,'Kotodama',replace(replace('Se houver monstros com a face para cima com o mesmo nome no campo, destrua esses monstros. \r\n(Se um monstro com o mesmo nome que outro monstro que já estiver com a face para cima no campo for Invocado ou virado com a face para cima, o novo monstro com a face para cima é destruído. Se eles forem Invocados ou virados com a face para cima ao mesmo tempo, todos são destruídos).','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19420830,'Frial Criônico Cataclísmico',replace(replace('Se um ou mais monstros de VENTO com a face para cima que você controla forem destruídos em batalha ou por um efeito de card do oponente: você pode Invocar este card por Invocação-Especial da sua mão e, depois, você pode colocar no topo do Deck, 1 Magia/Armadilha do campo. \r\nVocê só pode usar este efeito de "Frial Criônico Cataclísmico" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar este card por Invocação Especial','Retornar 1 Card de Magia/Armadilha ao Deck?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19434243,'Poderoso Vice-Dragão',replace(replace('Um "Dragão Vermelho Arquidemônio" que foi Invocado por Invocação-Sincro usando este card como matéria não pode ser destruído em batalha. \r\nVocê só pode usar cada um dos seguintes efeitos de "Poderoso Vice-Dragão" uma vez por turno. \r\nSe você não controlar nenhum monstro, ou todos os monstros que você controla forem Monstros Sincro de TREVAS: você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe este card for Invocado por Invocação-Especial: você pode adicionar 1 monstro "Ressonador" do seu Deck à sua mão e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto Monstros Sincro de TREVAS.','\r',char(13)),'\n',char(10)),'Invocação Especial','Adicionar à mão','','O efeito de "Poderoso Vice-Dragão" está sendo aplicado.','','','','','','','','','','','','');
INSERT INTO texts VALUES(19438484,'Ilios, o Dragão do Sol Negro',replace(replace('Você pode revelar 3 monstros Dragão no seu Deck Adicional com 3000 ou mais ATK e nomes diferentes; Invoque por Invocação-Especial este card da sua mão.\r\nSe este card for enviado para o Cemitério: você pode escolher 1 Monstro Fusão, Sincro, Xyz ou Link Dragão que você controla; seu oponente não pode escolhe-lo com efeitos de cards neste turno. \r\nNenhum jogador pode ativar cards ou efeitos em resposta a ativação desse efeito.\r\nVocê só pode usar cada um dos efeitos de "Ilios, o Dragão do Sol Negro" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Conceder proteção','O efeito de {CARD} está sendo aplicado.','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19439119,'Krus Mitológica','Se este card for descartado para o Cemitério: escolha 1 outro monstro "Mitológico(a)" de Nível 4 ou menos no seu Cemitério; Invoque o alvo por Invocação-Especial.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19441018,'Força Industrial do Homem-Bateria',replace(replace('Este card não pode ser Invocado por Invocação-Normal ou Baixado. \r\nEste card não pode ser Invocado por Invocação-Especial, exceto ao remover de jogo 2 monstros "Homem-Bateria" do seu Cemitério. \r\nUma vez por turno, você pode remover de jogo 1 monstro do Tipo Trovão do seu Cemitério para destruir 1 monstro e 1 Card de Magia ou Armadilha no campo.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19451302,'Supressão da Serpente','Monstros com 0 de ATK com a face para cima em Posição de Ataque que seu oponente controla não podem ser destruídos em batalha com monstros "Reptiliano(a)".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19462747,'Asanegra - Decadência do Vento Enfermo',replace(replace('Uma vez por turno, durante a Fase Final, se este card estiver no Cemitério porque foi enviado para lá neste turno: sofra 1000 de dano. \r\nQuando este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 monstro "Asanegra" que você controla e, depois, ativar 1 desses efeitos;\r\n● Aumente o Nível dele em 1.\r\n● Diminua o Nível dele em 1.	\r\nVocê só pode usar este efeito de "Asanegra - Decadência do Vento Enfermo" uma vez por turno.','\r',char(13)),'\n',char(10)),'Alterar Nível','Aumentar o Nível','Reduzir o Nível','Receber dano','','','','','','','','','','','','');
INSERT INTO texts VALUES(19474136,'Mandragão',replace(replace('Escala de Pêndulo = 2\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nEsta mandrágora abriga a alma de um dragão triste. O som amaldiçoado de seus lamúrios causa medo e desespero.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19476824,'Ragnarok Metafis',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode banir os 3 cards do topo do seu Deck e, se isso acontecer, este card ganha 300 de ATK para cada card "Metafis" banido por este efeito. \r\nQuando este card causar dano de batalha ao seu oponente: você pode Invocar por Invocação-Especial 1 monstro "Metafis" de Nível 5 ou mais do seu Deck, mas bana-o durante a Fase Final do próximo turno. \r\nVocê só pode usar cada efeito de "Ragnarok Metafis" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19489718,'Mechamosquete Magichave - Batosmolidor',replace(replace('Você pode Invocar este card por Invocação-Ritual com "Maftea Magichave". \r\nSe este card for Invocado por Invocação-Ritual: você pode adicionar 1 card "Magichave" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Mechamosquete Magichave - Batosmolidor" uma vez por turno. \r\nUma vez por turno, quando um ataque for declarado envolvendo este card e um monstro do oponente que tiver o mesmo Atributo que um Monstro Normal ou um monstro "Magichave" no seu Cemitério: você pode colocar qualquer número de cards da sua mão no fundo do Deck e, se isso acontecer, negue os efeitos desse monstro do oponente até o final deste turno e, depois, compre o mesmo número de cards colocados no fundo do Deck.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19491080,'Chapéu da Companhia de Palhaços',replace(replace('Escala de Pêndulo = 7\r\n[ Efeito de Pêndulo ]\r\nVocê só pode usar o Efeito de Pêndulo de "Chapéu da Companhia de Palhaços" uma vez por turno.\r\nDurante a sua Fase Principal: você pode enviar 1 card "Companhia de Palhaços" do seu Deck para o seu Cemitério, exceto um Monstro Pêndulo, e se fizer, Invoque este card por Invocação-Especial, você também não pode ativar os efeitos de monstros Invocados por Invocação-Especial do Deck ou Deck Adicional até o final do próximo turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nMonstros que seu oponente controla perdem 1500 de DEF enquanto você controlar um monstro Invocado por Invocação-Tributo.\r\nSe este card for oferecido como Tributo: você pode ativar 1 destes efeitos (mas você só pode usar cada um destes efeitos de "Chapéu da Companhia de Palhaços" uma vez por turno);\r\n● Embaralhe todos os Monstros Pêndulo no campo e com a face para cima nos Decks Adicionais no Deck.\r\n● Invoque por Invocação-Especial 1 monstro não-Pêndulo "Companhia de Palhaços" do seu Deck ou Deck Adicional, ignorando suas condições de Invocação.','\r',char(13)),'\n',char(10)),'Invocação Especial','Escolher um efeito','Retornar ao Deck','Invocação Especial','','','','','','','','','','','','');
INSERT INTO texts VALUES(19501924,'Transferência Pêndulo',replace(replace('Escolha até 2 Monstros Pêndulo que você controla; coloque os alvos nas suas Zonas de Pêndulo. \r\nVocê só pode ativar 1 "Transferência Pêndulo" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19502505,'Paladino Silencioso',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode adicionar 1 "Espadachim Silencioso LV3" ou "Mago Silencioso LV4" do seu Deck à sua mão. \r\nDurante o turno de qualquer duelista, quando um Card de Magia for ativado que escolha como alvo exatamente 1 monstro que você controla (e nenhum outro card): você pode negar a ativação. \r\nEste efeito só pode ser usado uma vez enquanto este card estiver com a face para cima no campo. \r\nSe este card for destruído em batalha, ou se este card sob o controle do seu dono for destruído por um efeito de card do oponente: você pode escolher 1 monstro "LV" de LUZ no seu Cemitério; adicione-o à sua mão.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Negar a ativação','Recuperar do Cemitério','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19504025,'Reinício da Eneanave',replace(replace('Coloque 1 "Eneápolis" do seu Deck ou Cemitério, com a face para cima na sua Zona do Campo ou, em vez disso, se você controlar "Eneápolis", você pode negar os efeitos de cards com a face para cima que seu oponente controla, até o número de cards nas suas Zonas de Pêndulo. \r\nSe seu oponente ativar um card ou efeito, enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode banir este card; coloque os monstros "Eneanave" que você controla com a face para baixo em Posição de Defesa, até o número de cards nas suas Zonas de Pêndulo. \r\nVocê só pode ativar 1 "Reinício da Eneanave" por turno.','\r',char(13)),'\n',char(10)),'Ativar','Mudar para Posição de Defesa com a face para baixo','Negar os efeitos do card?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19505896,'Urtigas','Se este card com a face para cima seria destruído, em vez disso, você pode destruir 1 monstro do Tipo Planta com a face para cima que você controla.','Usar o efeito de "Urtigas" em vez de ser destruído?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19508728,'Escudo da Lua Espelhada',replace(replace('Se o monstro equipado batalhar um monstro do seu oponente, durante o cálculo de dano: o ATK/DEF do monstro equipado se tornam iguais ao ATK ou DEF (o que for maior) do monstro que estiver batalhando do oponente +100, apenas durante o cálculo de dano. \r\nSe este card com a face para cima for enviado do campo para o Cemitério: pague 500 PV; coloque este card no topo ou no fundo do seu Deck.','\r',char(13)),'\n',char(10)),'Topo do Deck','Fundo do Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19510093,'Samurai Superpesado Monge Grande Benkei',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nSe você controlar um monstro "Samurai Superpesado": você pode adicionar 1 monstro "Samurai Superpesado Alma" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Samurai Superpesado Monge Grande Benkei" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe você não tiver Magias/Armadilhas no seu Cemitério: você pode enviar para o Cemitério 1 "Samurai Superpesado Grande Benkei" da sua mão ou do Deck e, se isso acontecer, Invoque este card por Invocação-Especial da sua mão. \r\nSe este card for usado como Matéria Sincro e adicionado ao seu Deck Adicional com a face para cima: você pode colocar este card na sua Zona de Pêndulo. \r\nVocê só pode usar cada efeito de "Samurai Superpesado Monge Grande Benkei" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Invoque este card por Invocação Especial da sua mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19516687,'Agente Livromante',replace(replace('Você pode revelar 1 Monstro de Ritual na sua mão: Invoque este card por Invocação-Especial da sua mão. \r\nVocê pode escolher 1 card "Livromante" no seu Cemitério, exceto "Agente Livromante"; adicione-o à sua mão e, depois, se você adicionou uma Magia/Armadilha por este efeito, coloque 1 card da sua mão no fundo do Deck. \r\nVocê só pode usar cada efeito de "Agente Livromante" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19523799,'Ookazi','Inflija 800 pontos de dano aos Life Points do seu adversário.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19535693,'Ze Amin Noh-P.U.N.K.',replace(replace('Você pode pagar 600 PV; adicione 1 monstro "P.U.N.K." do seu Deck à sua mão, exceto "Ze Amin Noh-P.U.N.K.". \r\nSe este card for enviado para o Cemitério: você pode escolher 1 monstro "P.U.N.K." que você controla; ele ganha 600 de ATK. \r\nVocê só pode usar cada efeito de "Ze Amin Noh-P.U.N.K." uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19544412,'Apresentador de Boxe',replace(replace('(Este card deve ser sempre considerado como um card "Boxeadores Obstinados".)	\r\nInvoque por Invocação-Especial 1 monstro "Boxeador Obstinado" da sua mão e, depois, você pode destruir Magias/Armadilhas no campo, até o número de Monstros Xyz que você controla. \r\nVocê só pode ativar 1 "Apresentador de Boxe" por turno.','\r',char(13)),'\n',char(10)),'','Destruir 1 Card de Magia/Armadilha?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19578592,'Machado dos Tolos',replace(replace('O monstro equipado ganha 1000 de ATK e, além disso, seus efeitos são negados. \r\nUma vez por turno, durante sua Fase de Apoio: cause 500 de dano ao controlador do monstro equipado.','\r',char(13)),'\n',char(10)),'Receba 500 pontos de dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19580308,'D/D Lâmia',replace(replace('Se este card estiver na sua mão ou no Cemitério: você pode enviar para o Cemitério 1 card "D/D" ou "Pacto Obscuro" da sua mão ou do campo com a face para cima, exceto "D/D Lâmia"; Invoque este card por Invocação-Especial, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar este efeito de "D/D Lâmia" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19590644,'Prepuppercut',replace(replace('Quando um monstro que você controla for destruído em batalha: Invoque por Invocação-Especial 1 monstro da sua mão ou do Deck com ATK menor ou igual que o do monstro destruído, com a face para baixo em Posição de Defesa. \r\nVocê só pode ativar 1 "Prepuppercut" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19594506,'Exploradora do Neo Espaço','Você pode descartar este card para o Cemitério para adicionar 1 "Neo Espaço" do seu Deck ou Cemitério à sua mão.','Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19596712,'Abis-escamas de Cetus',replace(replace('Só pode equipar um monstro "Sirena". \r\nEle ganha 800 de ATK. \r\nQuando um efeito de Armadilha que foi ativado do lado do campo do seu oponente resolver, negue o efeito e, depois, envie este card para o Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19605133,'Joaninha de Naturia',replace(replace('Quando você Invocar um monstro "Naturia" por Invocação-Sincro: você pode Invocar este card por Invocação-Especial do seu Cemitério. \r\nDurante sua Fase Principal: você pode oferecer este card como Tributo e, depois, escolha 1 monstro "Naturia" que você controla; ele ganha 1000 de ATK até o final deste turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Aumentar ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19612721,'Lutador de Discos','Se este card atacar um monstro em Posição de Defesa, com um DEF de 2000 ou mais, destrúa o monstro com o efeito deste card, sem aplicar o cálculo de dano.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19613556,'Tempestade Pesada','Destrua todos os Cards de Magia e Armadilha no campo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19619755,'Mago Camarartista Cinco Arco-Íris',replace(replace('Escala de Pêndulo = 12\r\n[ Efeito de Pêndulo ]\r\nVocê não pode Invocar por Invocação-Pêndulo, exceto do Deck Adicional. \r\nEste efeito não pode ser negado. \r\nCada duelista aplica 1 desses efeitos de acordo com o número de cards Baixados em suas Zonas de Magias & Armadilhas.\r\n● 0: Todos os monstros que o duelista controla não podem atacar ou ativar seus efeitos.\r\n● 4 ou mais: O ATK de todos os monstros que o duelista controla se torna o dobro do seu próprio ATK original.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe qualquer duelista Baixar uma Magia/Armadilha no seu campo enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode colocar este card na sua Zona de Pêndulo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19636995,'Cavalo Apressado Lebre Vermelha',replace(replace('Se houver uma coluna sem cards, você pode Invocar este card por Invocação-Especial (da sua mão) em Posição de Ataque em uma zona sua nessa coluna. \r\nVocê só pode Invocar "Cavalo Apressado Lebre Vermelha" por Invocação-Especial uma vez por turno desta forma. \r\nSe outro card for colocado na coluna deste card: destrua este card. \r\nUma vez por turno: você pode diminuir o ATK original deste card pela metade pelo resto deste turno e, se isso acontecer, ele pode atacar diretamente neste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19642774,'Fleur Sincron','Se este card for enviado para o Cemitério como Matéria Sincro: você pode Invocar por Invocação-Especial 1 monstro de Nível 2 ou menos da sua mão.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19642889,'Mão Poderosa de Koa''ki Meiru',replace(replace('Durante cada uma das suas Fases Finais, destrua este card a não ser que você envie 1 "Núcleo de Ferro de Koa''ki Meiru" da sua mão para o Cemitério ou revele 1 Card de Armadilha Normal na sua mão. \r\nSe este card batalhar com um monstro de LUZ ou de TREVAS, quaisquer efeitos desse monstro que sejam ativados ou aplicados no campo são negados durante a Fase de Batalha, enquanto este card permanecer no campo.','\r',char(13)),'\n',char(10)),'Escolha 1 "Núcleo de Ferro de Koa''ki Meiru" para enviar para o Cemitério','Mostre ao seu oponente 1 Armadilha Normal','Destruir "Mão Poderosa de Koa''ki Meiru"','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19652159,'Senhor Dragão da Luz e das Trevas',replace(replace('1 monstro Dragão de LUZ de Nível 8 + 1 monstro Dragão de TREVAS de Nível 8	\r\nDeve ser Invocado por Invocação-Fusão. \r\nEnquanto estiver com a face para cima no campo, este card também é de Atributo TREVAS. \r\nUma vez por Corrente, se um Card de Magia/Armadilha, ou efeito de monstro, for ativado (Efeito Rápido): este card perde exatamente 1000 de ATK/DEF e, se isso acontecer, negue a ativação. \r\nSe este card em posse do seu dono for destruído por um card do oponente: você pode escolher 1 monstro Dragão no seu Cemitério; Invoque-o por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Considere o Atributo como TREVAS','Negar a ativação','Invocar por Invocação Especial do Cemitério','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19665973,'Desvanecer da Batalha',replace(replace('Quando um monstro do oponente declarar um ataque direto: você pode Invocar este card por Invocação-Especial da sua mão e, depois, encerre a Fase de Batalha. \r\nSe Invocado desta forma, bana-o quando ele deixar o campo.','\r',char(13)),'\n',char(10)),'Encerrar a Fase de Batalha','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19667590,'Gogogo Gigas',replace(replace('Enquanto este card estiver no seu Cemitério, se você Invocar por Invocação-Especial um ou mais monstros "Gogogo" (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial do seu Cemitério com a face para cima em Posição de Defesa. \r\nVocê não pode conduzir sua Fase de Batalha no turno em que ativar este efeito. \r\nVocê só pode usar o efeito de "Gogogo Gigas" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19671102,'Escada de Correspondências',replace(replace('Durante sua Fase Principal: você pode ativar este efeito; descarte 1 card "Tindângulo" e, se isso acontecer, aplique 1 dos seguintes efeitos.\r\n● Coloque 1 monstro com a face para baixo em Posição de Defesa que você controla, com a face para cima em Posição de Ataque.\r\n● Coloque 1 monstro com a face para cima em Posição de Ataque que você controla, com a face para baixo em Posição de Defesa.	\r\nNeste turno, você não pode descartar outro card com o mesmo nome para o efeito de "Escada de Correspondências" (mesmo que este card deixe o campo).','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19671433,'Imaginações Mannadium',replace(replace('Revele 1 monstro "Mannadium" ou "Visas Starfrost" na sua mão; compre 2 cards e, depois, coloque 1 card da sua mão no fundo do Deck. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 monstro que você controla com 1500 de ATK/2100 de DEF; considere-o como um Regulador até o final deste turno. \r\nVocê só pode usar cada efeito de "Imaginações Mannadium" uma vez por turno.','\r',char(13)),'\n',char(10)),'Comprar','Tornar-se um Regulador','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19673561,'Pergaminho Fazticeira',replace(replace('Uma vez por turno, quando um monstro Mago seu destruir um monstro em batalha: você pode comprar 1 card. \r\nVocê só pode usar 1 dos seguintes efeitos de "Pergaminho Fazticeira" por turno e apenas uma vez por turno.\r\n● Se um monstro "Fazticeira" que você controla seria descartado para ativar um efeito, em vez disso, você pode enviar este card do seu campo para o Cemitério.\r\n● Durante sua Fase Final, se você controlar um monstro "Fazticeira", enquanto este card estiver no seu Cemitério: você pode colocar este card com a face para cima na sua Zona de Magias & Armadilhas.','\r',char(13)),'\n',char(10)),'Comprar','Retornar ao Campo','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19680539,'Nobre Cavaleiro Gawayn','Se você controlar um Monstro Normal de LUZ, você pode Invocar este card por Invocação-Especial (da sua mão) em Posição de Defesa.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19684740,'Cavaleiro Fada Ingunar',replace(replace('3 monstros de Nível 6	\r\nUma vez por turno: você pode desassociar 2 Matérias Xyz deste card; devolva todos os outros cards no campo para a mão. \r\nSeu oponente não pode ativar cards ou efeitos em resposta à ativação deste efeito.','\r',char(13)),'\n',char(10)),'Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19688343,'Contra-ataque dos Boxeadores Obstinados',replace(replace('Quando seu oponente ativar um efeito de monstro: destrua 1 Monstro Xyz "Boxeador Obstinado" ou "Número" que você controla e, se isso acontecer, negue a ativação e, se isso acontecer, destrua esse monstro e, depois, você pode aplicar o seguinte efeito.\r\n● Invoque por Invocação-Especial 1 Monstro Xyz "Boxeador Obstinado" do seu Deck Adicional com um nome diferente que o do primeiro monstro e, se isso acontecer, associe este card a ele como matéria.	\r\nVocê só pode ativar 1 "Contra-ataque dos Boxeadores Obstinados" por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial do Deck Adicional?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19700943,'Robô Dododo',replace(replace('Não pode ser Invocado por Invocação-Normal (mas pode ser Baixado de forma Normal). \r\nSe este card atacar, ele não é afetado por outros efeitos de card até o final da Etapa de Dano.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19712214,'Anel de Bolhas Marincesa',replace(replace('Quando um monstro declarar um ataque: negue o ataque e, se isso acontecer, Invoque por Invocação-Especial 1 "Marincesa Coração de Cristal" do seu Deck Adicional ou Cemitério. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 monstro "Marincesa" de Link-2 ou mais que você controla; neste turno, em cada Fase de Batalha, ele pode atacar um número de vezes até seu Valor Link e, além disso, neste turno, seu oponente não sofre dano dos ataques que o envolvam. \r\nVocê só pode ativar 1 "Anel de Bolhas Marincesa" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19715246,'Jormungardr Cibernético',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial por um efeito de card. \r\nSe seu oponente controlar um monstro: você pode Invocar este card por Invocação-Especial da sua mão e, depois, pegue 1 "Dragão Cibernético" do seu Deck e Invoque-o por Invocação-Especial ou equipe-o a este card como uma Magia de Equipamento e, além disso, você não pode Invocar por Invocação-Especial pelo resto deste turno, exceto monstros Máquina. \r\nVocê pode devolver 1 "Dragão Cibernético" que você controla para a mão; adicione 1 "Polimerização" do seu Deck ou Cemitério à sua mão. \r\nVocê só pode usar cada efeito de "Jormungardr Cibernético" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Adicionar à mão','Equipar?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19733961,'Homem-Bateria C',replace(replace('Se todos os "Homem-Bateria C" no seu Campo estão em Posição de Ataque, aumente o ATK de todos os monstros do Tipo Máquina no seu Campo em 500 pontos por cada "Homem-Bateria C" no seu Campo. \r\nSe todos os "Homem-Bateria C" no seu Campo estão em Posição de Defesa, aumente a DEF de todos os monstros do Tipo Máquina no seu Campo em 500 pontos por cada "Homem-Bateria C" no seu Campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19737320,'Porteiro','Um mecanoide indestrutível criado com o único propósito de guardar os portões.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19739265,'Sol e Luna',replace(replace('Escolha 1 monstro que você controla e 1 monstro que seu oponente controla; aplique o seguinte efeito em cada monstro, dependendo de sua posição de batalha.\r\n● Face para cima: Coloque-o com a face para baixo em Posição de Defesa.\r\n● Face para baixo: Coloque-o com a face para cima em Posição de Defesa.	\r\nVocê só pode ativar 1 "Sol e Luna" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19740112,'Estátua Barreira da Seca','Nenhum duelista pode Invocar monstros por Invocação-Especial, exceto monstros de TERRA.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19743887,'VARbitro, o Juiz da Bola',replace(replace('Quando seu oponente ativar um efeito de monstro no campo dele que escolha como alvo um ou mais monstros que você controla, ou um monstro dele escolher um deles como alvo de um ataque (Efeito Rápido): você pode Invocar este card por Invocação-Especial da sua mão e, depois, você pode selecionar 1 desses monstros do oponente e revelar 1 card na sua mão e, depois, aplique o seguinte efeito a esse monstro de acordo com o tipo de card revelado.\r\n● Monstro: Coloque-o em Posição de Defesa.\r\n● Magia: Dobre seu ATK.\r\n● Armadilha: Bana-o.	\r\nVocê só pode usar este efeito de "VARbitro, o Juiz da Bola" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Mostrar sua mão ao seu oponente?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19747827,'Espada do Dragão Negro de Olhos Vermelhos',replace(replace('Deve ser Invocado por Invocação-Especial com "A Garra de Hermos", usando um monstro Dragão. 	\r\nSe este card for Invocado por Invocação-Especial: escolha 1 outro monstro com a face para cima no campo; equipe este card a ele. \r\nEle ganha 1000 de ATK e 500 de ATK/DEF para cada monstro Dragão no campo e nos Cemitérios.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19748583,'Gwenhwyfar, Rainha das Armas Nobres',replace(replace('Você pode escolher 1 monstro "Nobre Cavaleiro" que você controla; equipe este card da sua mão ou Cemitério no alvo. \r\nVocê só pode usar este efeito de "Gwenhwyfar, Rainha das Armas Nobres" uma vez por turno. \r\nO monstro equipado ganha 300 de ATK. \r\nAplique o efeito apropriado, de acordo com o Atributo do monstro equipado.\r\n● LUZ: Se o monstro equipado seria destruído por um efeito de card, em vez disso, você pode destruir este card.\r\n● TREVAS: Se o monstro equipado batalhar um monstro do oponente, no começo da Etapa de Dano: você pode destruir esse monstro e, depois, destruir este card.','\r',char(13)),'\n',char(10)),'Equipar','Usar o efeito de "Gwenhwyfar, Rainha das Armas Nobres" em vez de ser destruído?','Destruir','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19763315,'Um Relatório Infeliz','Seu oponente conduz a próxima Fase de Batalha dele duas vezes.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19771459,'Caverguerra Gactos',replace(replace('Se um monstro Guerreiro de TERRA for Invocado por Invocação-Normal no seu campo: você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe este card for enviado da sua Zona de Monstros para o seu Cemitério por um efeito de card do oponente: você pode Invocar por Invocação-Especial 1 monstro "Caverguerra" de Nível 5 ou mais da sua mão ou do Deck. \r\nVocê só pode usar este efeito de "Caverguerra Gactos" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19801646,'O Pescador Lendário II',replace(replace('O nome deste card se torna "O Pescador Lendário" enquanto estiver no campo ou no Cemitério. \r\nEnquanto "Umi" estiver no campo, este card não é afetado por outros efeitos de monstro. \r\nSe este card com a face para cima for destruído em batalha ou deixar o campo devido a um efeito de card do oponente enquanto seu dono o controlar: você pode adicionar 1 monstro de ÁGUA de Nível 7 do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19808608,'D/D Berfomet','Uma vez por turno: você pode escolher 1 monstro "D/D" que você controla que tenha um Nível, exceto "D/D Berfomet", e declarar um Nível de 1 a 8; ele se torna desse Nível até o final deste turno e, além disso, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros "D/D".','Declarar um Nível','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19814508,'U.A. Estádio',replace(replace('Se um monstro "U.A." for Invocado por Invocação-Normal no seu lado do campo: você pode adicionar 1 monstro "U.A." do seu Deck à sua mão. \r\nUma vez por turno, se um ou mais monstros "U.A." forem Invocados por Invocação-Especial no seu lado do campo: todos os monstros que você controla atualmente ganham 500 de ATK (mesmo que este card deixe o campo).','\r',char(13)),'\n',char(10)),'Procurar no Deck','Alterar ATK/DEF','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19827717,'Regresso dos Condenados',replace(replace('Descarte 1 Card de Monstro da sua mão para o Cemitério. \r\nNo fim deste turno, devolva à sua mão 1 monstro destruído e enviado ao seu Cemitério como resultado de uma batalha durante este turno.','\r',char(13)),'\n',char(10)),'Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19828680,'Contrato com o Vácuo','Se você tiver 3 ou mais outros cards na sua mão: descarte toda a sua mão e, depois, você pode Invocar por Invocação-Especial 1 monstro "Inférnico(a)" ou 1 Monstro Sincro Dragão de TREVAS de Nível 8 do seu Cemitério.','Invocação Especial?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19844995,'Filtro de Poder','Nenhum duelista pode Invocar por Invocação-Especial monstros com 1000 ou menos de ATK.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19847532,'Imperador da Chama Infernal',replace(replace('Não pode ser Invocado por Invocação-Especial. \r\nQuando este card for Invocado por Invocação-Tributo: você pode banir até 5 monstros de FOGO do seu Cemitério; destrua Magias/Armadilhas no campo igual ao número banido para ativar este efeito.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19870120,'Marcha dos Monarcas',replace(replace('Os monstros que você controla Invocados por Invocação-Tributo não podem ser destruídos por efeitos de card e, além disso, nenhum duelista pode escolhê-los como alvo de efeitos de card. \r\nVocê não pode Invocar por Invocação-Especial monstros do Deck Adicional.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19877898,'Inseto Supremo LV7','Se este card foi Invocado, por Invocação-Especial, pelo efeito de "Inseto Supremo LV5", enquanto este card permanecer no seu Campo com a face para cima, diminua o ATK e a DEF de todos os monstros do seu adversário em 700 pontos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19882096,'Espantagarra Belone',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) em uma Zona de Monstros Principal sua, adjacente a um monstro "Espantagarra" que você controla ou na coluna dele. \r\nVocê só pode Invocar "Espantagarra Belone" por Invocação-Especial uma vez por turno desta forma. \r\nSe um monstro "Espantagarra" seu na Zona de Monstros Adicional atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19885332,'Espelho Branco',replace(replace('Escolha 1 monstro Peixe de Nível 4 ou menos no seu Cemitério; Invoque-o por Invocação-Especial e, depois, você pode adicionar 1 monstro do seu Deck à sua mão com o mesmo nome original que o desse monstro Invocado por Invocação-Especial. \r\nVocê só pode ativar "Espelho Branco" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à sua mão 1 card com o mesmo nome do seu Deck?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19891131,'Ladrão do Tempo Regulador',replace(replace('Se você não controlar nenhum outro monstro: você pode oferecer este card como Tributo; Invoque por Invocação-Especial 2 monstros "Ladrão do Tempo" com nomes diferentes do seu Deck em Posição de Defesa, exceto "Ladrão do Tempo Regulador". \r\nQuando um Monstro Xyz que você controla for destruído em batalha, enquanto este card estiver no seu Cemitério: você pode Invocar este card por Invocação-Especial, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar cada efeito de "Ladrão do Tempo Regulador" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19891310,'Gigante XG Engrenagigrenagi',replace(replace('3 monstros de Nível 3	\r\nDurante a Etapa de Batalha de qualquer duelista, enquanto um ataque envolvendo um monstro seu do Tipo Máquina estiver acontecendo: você pode desassociar 1 Matéria Xyz deste card; negue os efeitos de todos os cards com a face para cima que seu oponente controla atualmente e, além disso, seu oponente não pode ativar cards ou efeitos. \r\nEsses efeitos duram até o final da Etapa de Dano. \r\nQuando este card com a face para cima deixar o campo: você pode escolher 1 outro card "Engrenagi" no seu Cemitério; adicione o alvo à sua mão.','\r',char(13)),'\n',char(10)),'Negar o efeito','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19899073,'Ame no Murakumo no Mitsurugi',replace(replace('Você pode Invocar este card por Invocação-Ritual com "Ritual de Mitsurugi". \r\nSe este card for Invocado por Invocação-Especial: você pode destruir todos os monstros que seu oponente controla. \r\nQuando seu oponente ativar um card ou efeito (Efeito Rápido): você pode ativar este efeito; seu oponente pode descartar 1 card, ou esse efeito é negado. \r\nSe este card for oferecido como Tributo: você pode adicionar 1 card "Mitsurugi" do seu Deck à sua mão, exceto "Ame no Murakumo no Mitsurugi" e, depois, você pode Invocar este card por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Ame no Murakumo no Mitsurugi" uma vez por turno.','\r',char(13)),'\n',char(10)),'Destruir','Negar','Adicionar à mão','Descartar 1 card?','Invocação Especial?','','','','','','','','','','','');
INSERT INTO texts VALUES(19932396,'Primeiro Passo para a Infestação','Devolva 1 monstro "Hordeum Ferro" Invocado por Invocação-Tributo com a face para cima que você controla para a mão; compre 1 card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19942835,'Renascimento Zumbi',replace(replace('Escolha 1 monstro Zumbi em qualquer Cemitério; bana 1 monstro com o mesmo nome do seu Deck ou Deck Adicional e, se isso acontecer, Invoque o monstro alvo por Invocação-Especial no seu campo. \r\nSe este card estiver no seu Cemitério: você pode embaralhar no Deck 1 dos seus monstros Zumbi banidos e, se isso acontecer, Baixe este card, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar 1 efeito de "Renascimento Zumbi" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19943114,'Cinet Regressão',replace(replace('Se você Invocar por Invocação-Especial um ou mais Monstros Link: escolha 1 card no campo; destrua-o e, depois, compre 1 card. \r\nVocê só pode ativar 1 "Cinet Regressão" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19951423,'Força-S Signify',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 monstro "Força-S" do seu Deck à sua mão, exceto "Força-S Signify" e, depois, se seu oponente controlar um monstro na coluna deste card, você pode comprar 1 card. \r\nSe seu oponente ativar um efeito de monstro na mesma coluna que a de um monstro que você controla (exceto durante a Etapa de Dano): você pode fazer com que todos os monstros "Força-S" que você controla ganhem 1000 de ATK. \r\nVocê só pode usar cada efeito de "Força-S Signify" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Aumentar ATK','Comprar 1 card?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19959563,'Dragão do Castigo',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao possuir 4 ou mais monstros "Luminoso(a)" com nomes diferentes banidos. \r\nUma vez por turno (Efeito Rápido): você pode pagar 1000 PV; embaralhe nos Decks, todos os cards dos Cemitérios e todos os cards banidos com a face para cima, exceto monstros "Luminoso(a)". \r\nUma vez por turno, se o efeito de um monstro "Luminoso(a)" seu for ativado: envie os 4 cards do topo do seu Deck para o Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19959742,'Molusco Gishki','Quando este card for enviado ao Cemitério por um efeito de card: Olhe os 3 cards no topo do seu Deck e, depois, devolva-os para o topo ou para o fundo do Deck, em qualquer ordem.','Verificar o Deck','Colocar no topo do Deck','Retornar ao fundo do Deck','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19963185,'Fera Cristalina Avançada Gata Ametista',replace(replace('Se "Trevas Avançadas" não estiver em uma Zona do Campo, envie este monstro para o Cemitério. \r\nSeus monstros "Fera Cristalina Avançada" podem atacar diretamente, mas quando o fazem usando este efeito, o dano de batalha causado ao seu oponente é diminuído pela metade. \r\nSe este card com a face para cima for destruído em uma Zona de Monstros, em vez de enviá-lo para o Cemitério, você pode colocá-lo com a face para cima na sua Zona de Magias & Armadilhas como uma Magia Contínua.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19974580,'Dragão da Corrente de Ferro',replace(replace('1 Regulador + 1+ não-Reguladores	\r\nDurante sua Fase Principal: você pode banir tantos monstros "Corrente de Ferro" quanto possível do seu Cemitério e, se isso acontecer, até o final deste turno, este card ganha 200 de ATK para cada monstro banido. \r\nSe este card causar dano de batalha ao seu oponente: envie os 3 cards do topo do Deck do seu oponente para o Cemitério.','\r',char(13)),'\n',char(10)),'Aumentar ATK','Envie os 3 cards do topo do Deck para o Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19974890,'Um Monte de Corpos de Bestas',replace(replace('Coloque em Posição de Defesa todos os monstros que não foram Invocados por Invocação-Normal ou Especial neste turno. \r\nPelo resto deste turno, um duelista que controlar um monstro em Posição de Defesa não pode declarar ataques com monstros que foram Invocados por Invocação-Normal ou Especial neste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19980975,'Ciclone de Poeira de Diamante','Escolha 1 monstro com 4 ou mais Marcadores de Névoa; destrua-o e, se isso acontecer, compre 1 card para cada 4 Marcadores de Névoa que estavam nele.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20001443,'Espadalma de Mo Ye',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode revelar 1 card "Espadalma" ou 1 monstro Wyrm na sua mão; Invoque por Invocação-Especial 1 "Ficha de Espadalma" (Wyrm/Regulador/ÁGUA/Nível 4/ATK 0/DEF 0). \r\nEnquanto essa Ficha estiver na Zona de Monstros, o duelista que a Invocou não pode Invocar do Deck Adicional por Invocação-Especial, exceto Monstros Sincro. \r\nSe este card for enviado para o Cemitério como Matéria Sincro: você pode comprar 1 card. \r\nVocê só pode usar cada efeito de "Espadalma de Mo Ye" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20001444,'Ficha de Espadalma','Invocado por Especial com o efeito de um card "Espadalma".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20003027,'Melffy Puppy',replace(replace('Se seu oponente Invocar um ou mais monstros por Invocação-Normal ou Especial (exceto durante a Etapa de Dano), ou se um monstro do oponente escolher este card como alvo de um ataque: você pode devolver este card para a mão e, depois, você pode Invocar por Invocação-Especial 1 monstro Besta de Nível 2 ou menos do seu Deck, exceto "Melffy Puppy". \r\nDurante sua Fase Final: você pode Invocar este card por Invocação-Especial da sua mão. \r\nVocê só pode usar cada efeito de "Melffy Puppy" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Invocar por Invocação Especial do Deck?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20003527,'Nuviano - Homem-Nimbo',replace(replace('Não pode ser destruído em batalha. \r\nSe este card estiver com a face para cima em Posição de Defesa, destrua-o. \r\nVocê pode oferecer como Tributo qualquer número de monstros de ÁGUA para a Invocação-Tributo deste card. \r\nSe este card for Invocado por Invocação-Tributo: coloque 1 Marcador de Névoa nele para cada monstro de ÁGUA que você ofereceu como Tributo. \r\nEste card ganha 500 de ATK para cada Marcador de Névoa no campo.','\r',char(13)),'\n',char(10)),'Invocação Tributo usando apenas monstros de ÁGUA','Colocar um marcador','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20007374,'Desejos Convergentes',replace(replace('Se você tiver 5 ou mais Monstros Sincro Dragão com nomes diferentes no seu Cemitério: Invoque por Invocação-Especial 1 "Dragão da Poeira Estelar" do seu Deck Adicional (isso é considerado uma Invocação-Sincro) e equipe-o com este card, mas bana-o durante a Fase Final. \r\nEsse monstro equipado ganha ATK igual ao ATK combinado de todos os Monstros Sincro Dragão no seu Cemitério. \r\nSempre que o monstro equipado destruir um monstro do oponente em batalha: você pode banir 1 Monstro Sincro Dragão do seu Cemitério; o monstro equipado pode atacar um monstro do oponente novamente em seguida.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20011655,'Besta de Talwar - O Cume da Espada',replace(replace('(Este card deve ser sempre considerado como um card "Arquidemônio".)	\r\nSe você não controlar nenhum monstro, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nNa primeira vez que este card seria destruído por um efeito de card do oponente a cada turno, ele não é destruído. \r\nNenhum duelista pode escolher outros monstros como alvo de Cards de Magia de Equipamento ou seus efeitos.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20032555,'Engenhoca Marionete Cabeça de Ovo',replace(replace('Você só pode usar o efeito de "Engenhoca Marionete Cabeça de Ovo" uma vez por turno. \r\nVocê pode descartar 1 monstro "Engenhoca Marionete" e, depois, ativar 1 desses efeitos;\r\n● Cause 800 de dano ao seu oponente.\r\n● O Nível deste card se torna 8 até a Fase Final.','\r',char(13)),'\n',char(10)),'Ativar o efeito escolhido','Cause 800 de dano ao seu oponente','O Nível deste card se torna 8 até a Fase Final','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20036055,'O Viajante e o Abismo Ardente',replace(replace('Escolha qualquer número de monstros "Abismo Ardente" no seu Cemitério que foram enviados para lá neste turno; Invoque-os por Invocação-Especial em Posição de Defesa. \r\nVocê só pode ativar 1 "O Viajante e o Abismo Ardente" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20049870,'Selande, o Pesquisador da GMX',replace(replace('Se este card for Invocado por Invocação-Normal: você pode Invocar por Invocação-Especial 1 monstro "GMX" não-Guerreiro ou 1 monstro Dinossauro de Nível 3 ou menos do seu Deck. \r\nSe este card for Invocado por Invocação-Especial por um efeito de monstro: você pode adicionar 1 Magia/Armadilha "GMX" do seu Deck à sua mão. \r\nSe um Monstro de Fusão Dinossauro estiver no campo: você pode embaralhar este card do campo no Deck e, se isso acontecer, negue os efeitos de 1 card com a face para cima no campo até o final deste turno. \r\nVocê só pode usar cada efeito de "Selande, o Pesquisador da GMX" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Efeito de busca','Negar o efeito','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20050865,'Cristron Citree',replace(replace('Durante a Fase Principal ou de Batalha do seu oponente (Efeito Rápido): você pode escolher 1 não-Regulador no seu Cemitério; Invoque-o por Invocação-Especial, mas seus efeitos são negados (se houver) e, depois, imediatamente depois que este efeito resolver, Invoque por Invocação-Sincro 1 Monstro Sincro Máquina usando apenas esse monstro e este card. \r\nEssas Matérias Sincro são banidas em vez de serem enviadas para o Cemitério. \r\nVocê só pode usar este efeito de "Cristron Citree" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20056760,'Alicercinza Limo',replace(replace('Se este card estiver na sua mão ou Cemitério: você pode escolher 2 cards "Alicercinza" que você controla; destrua-os e, se isso acontecer, Invoque este card por Invocação-Especial. \r\nVocê só pode usar este efeito de "Alicercinza Limo" uma vez por turno. \r\nQuando Invocado desta forma: você pode escolher 1 monstro "Alicercinza" no seu Cemitério; Invoque o alvo por Invocação-Especial em Posição de Defesa.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20057949,'Fortuna Herdada',replace(replace('Ative durante o turno em que um monstro "Senhora Fortuna" com a face para cima que você controla foi destruído. \r\nInvoque por Invocação-Especial até 2 monstros "Senhora Fortuna" da sua mão durante sua próxima Fase de Apoio.','\r',char(13)),'\n',char(10)),'Ativar o efeito de "Fortuna Herdada"?','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20060230,'Armadura Resistente','Uma armadura viva que ataca os inimigos com uma investida capaz de quebrar ossos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20065259,'Kagero, a Ninja Canhão',replace(replace('Se este card for Invocado por Invocação-Normal, Invocação-Especial ou virado com a face para cima: você pode Invocar por Invocação-Especial 1 monstro "Ninja" da sua mão ou do Cemitério com a face para baixo em Posição de Defesa, exceto "Kagero, a Ninja Canhão". \r\nQuando seu oponente ativar um card ou efeito que escolha exatamente 1 card "Ninja" ou exatamente 1 monstro com a face para baixo em Posição de Defesa que você controla, enquanto este card estiver no seu Cemitério (Efeito Rápido): você pode Invocar este card por Invocação-Especial com a face para baixo em Posição de Defesa e, se isso acontecer, devolva o card alvo para a mão. \r\nVocê só pode usar cada efeito de "Kagero, a Ninja Canhão" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20065322,'A Flauta para Invocação de Kuriboh','Pegue 1 "Kuriboh" ou 1 "Kuriboh Alado" do seu Deck e adicione-o à sua mão ou Invoque-o por Invocação-Especial.','Adicionar à mão','Invocar por Invocação Especial para o seu Campo','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20065549,'Area de Não Lançamento de Magias','Todos os monstros no Campo com a face para cima, exceto os Monstros de Efeito, não são afetados por qualquer Card de Magia, excluíndo este card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20071842,'Interconector Pesado',replace(replace('Este card é usado para a Invocação-Ritual de "Dragão do Motim Callibregado". \r\nVocê também deve oferecer monstros como Tributo da sua mão ou do campo, e/ou destruir monstros "Foguette" da sua mão ou do campo com a face para cima, cuja soma dos Níveis seja igual a 8 ou mais. \r\nO monstro Invocado por Invocação-Especial por este efeito não pode ser destruído em batalha com um monstro Invocado por Invocação-Especial do Deck Adicional e não é afetado pelos efeitos ativados de qualquer monstro Invocado por Invocação-Especial do Deck Adicional.','\r',char(13)),'\n',char(10)),'','Escolha o monstro a ser oferecido como tributo ou destruído','Destruir um monstro "Foguette"?','O efeito de "Interconector Pesado" está sendo aplicado.','','','','','','','','','','','','');
INSERT INTO texts VALUES(20073910,'Amaterasu',replace(replace('Não pode ser Invocado por Invocação-Normal ou Especial. \r\nDurante o turno de qualquer duelista, quando seu oponente ativar um card ou efeito que escolhe como alvo este monstro com a face para baixo: você pode colocar este card com a face para cima em Posição de Defesa; compre 1 card. \r\nSe este card for virado com a face para cima: bana todos os outros cards no campo. \r\nUma vez por turno, durante a Fase Final, se este card foi virado com a face para cima neste turno: devolva-o para a mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20087414,'Kuebiko',replace(replace('Invoque este card por Invocação-Especial como um Monstro de Efeito (Fada/TERRA/Nível 2/ATK 0/DEF 0) com o seguinte efeito (este card ainda é considerado uma Armadilha).\r\n● Uma vez por Corrente, quando seu oponente ativar um efeito de monstro no campo que escolha como alvo um ou mais cards que você controla (Efeito Rápido): você pode Baixar este card na sua Zona de Magias & Armadilhas e, se isso acontecer, negue esse efeito do oponente e, depois, se esse monstro tiver o maior ATK no campo do seu oponente, devolva-o para a mão.	\r\nVocê só pode ativar 1 "Kuebiko" por turno.','\r',char(13)),'\n',char(10)),'Negar o efeito','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20101223,'Fôlego da Luz','Destrua todos os monstros do Tipo Rocha com a face para cima no campo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20127343,'Substituto Aliado Genex',replace(replace('Uma vez por turno, você pode selecionar 1 monstro com a face para cima no campo e declarar 1 Atributo. \r\nO Atributo do monstro escolhido se torna o Atributo declarado até a Fase Final.','\r',char(13)),'\n',char(10)),'Alterar o Atributo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20129614,'Melffy Rabby','Rabby está novamente em seu tronco favorito, olhando seus amigos peludos pela floresta! Você também gosta de explorar? Ótimo! Então vamos encontrar mais amigos Melffy com Rabby!','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20137754,'Duza, o Receptáculo Cúbico Meteoro',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode enviar 1 card "Cúbico(a)" do seu Deck para o Cemitério. \r\nUma vez por turno, durante o turno de qualquer duelista, se um monstro foi enviado para o seu Cemitério neste turno enquanto este card estava com a face para cima no campo: você pode fazer com que este card ganhe, até o final deste turno, 200 de ATK para cada monstro com um nome diferente no seu Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20138923,'Prisma Antimágico','Quando seu oponente ativar um Card de Magia Rápida, selecione 1 card no campo e destrua-o.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20140382,'Sobrepujar',replace(replace('Só pode ser ativado enquanto você controlar um monstro de Nível 7 ou mais com a face para cima que foi Invocado por Invocação-Tributo. \r\nNegue a ativação de um Card de Armadilha ou o efeito de um Monstro de Efeito e destrua esse card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20145685,'Armadura Xyz Fortaleza',replace(replace('2 monstros de Nível 5	\r\nUma vez por turno, você também pode Invocar por Invocação-Xyz "Armadura Xyz Fortaleza" ao usar 1 Monstro Xyz de Classe 3 ou 4 que você controla. \r\n(Transfira as matérias dele para este card.) \r\nNão pode ser usado como matéria para uma Invocação-Xyz enquanto tiver matéria. \r\nUma vez por turno: você pode desassociar até 2 matérias deste card; adicione cards "Xyz de Armadura" com nomes diferentes do seu Deck à sua mão, igual ao número desassociado. \r\nSe um monstro equipado com este card batalhar um monstro, qualquer dano de batalha que ele causar ao seu oponente é dobrado.','\r',char(13)),'\n',char(10)),'Invoque Xyz sobrepondo-o em um Monstro Xyz de Classe 3 ou 4 que você controla','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20154092,'Cronomalia Trabuco Cabrera','Uma vez por turno: você pode oferecer como Tributo 1 outro monstro "Cronomalia" e, depois, escolher 1 monstro com a face para cima que seu oponente controla; o ATK dele se torna 0 até a Fase Final.','O ATK se torna 0','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20155904,'Katargalo Zoodíaco',replace(replace('Se este card for destruído em batalha ou por um efeito de card: você pode escolher 1 card "Zoodíaco(a)" no seu Cemitério, exceto "Katargalo Zoodíaco"; embaralhe-o no Deck. \r\nUm Monstro Xyz cujo Tipo original seja Besta-Guerreira e que tenha este card como Matéria Xyz ganha este efeito.\r\n● Durante o turno de qualquer duelista, quando seu oponente ativar um efeito de monstro que escolha este card como alvo: você pode desassociar 1 Matéria Xyz deste card; negue a ativação.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20174189,'Disparo de Bambu de Naturia','Enquanto você controlar este card com a face para cima que foi Invocado por Invocação-Tributo pelo Tributo de um monstro "Naturia", seu oponente não pode ativar Cards de Magia/Armadilha.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20188127,'Anjo da Fonte',replace(replace('Escolha 1 Card de Magia de Equipamento no seu Cemitério; adicione o alvo à sua mão. \r\nEsse Card de Magia de Equipamento não pode ser ativado neste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20191720,'Gouki Moonsault',replace(replace('Você pode revelar este card na sua mão e, depois, escolher 1 monstro "Gouki" que você controla, exceto "Gouki Moonsault"; Invoque este card por Invocação-Especial da sua mão e, se isso acontecer, devolva esse monstro para a mão. \r\nVocê pode escolher 1 Monstro Link "Gouki" no seu Cemitério; devolva-o para o Deck Adicional e, depois, você pode adicionar 1 monstro "Gouki" do seu Cemitério à sua mão. \r\nVocê só pode usar cada efeito de "Gouki Moonsault" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Adicionar 1 monstro "Gouki" do seu Cemitério à sua mão?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20193924,'Rainha Branca da Noite',replace(replace('Não pode ser Invocado por Invocação-Especial. \r\nUma vez por turno: você pode escolher 1 card Baixado; destrua o alvo.','\r',char(13)),'\n',char(10)),'Destrua 1 card Baixado no campo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20201255,'Retorno da Besta Gladiadora',replace(replace('Invoque por Invocação-Especial 1 monstro "Besta Gladiadora" da sua mão ou do Cemitério, com um Tipo diferente que o dos monstros que você controla. \r\nEle não pode ser destruído em batalha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20210570,'Regulus',replace(replace('Uma vez por turno, você pode selecionar 1 Card de Magia de Campo no seu Cemitério. \r\nDevolva-o para o Deck.','\r',char(13)),'\n',char(10)),'Retornar ao Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20212491,'Rua Purrely Andarilha',replace(replace('Seu oponente não pode escolher monstros "Purrely" que você controla como alvo de efeitos de card no turno em que eles forem Invocados por Invocação-Especial. \r\nUma vez por turno, se um ou mais Monstros Xyz "Purrely" com a face para cima que você controla deixarem o campo devido a um card do oponente: Invoque por Invocação-Especial do seu Deck ou Cemitério 1 monstro "Purrely" de Nível 1. \r\nUma vez por turno, durante a Fase Final: você pode escolher 1 Monstro Xyz "Purrely" no campo; associe 1 Magia Rápida "Purrely" do seu Deck ou Cemitério a esse monstro como matéria.','\r',char(13)),'\n',char(10)),'Invocação Especial','Associar Matéria Xyz','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20216608,'Tentativa Frustrada',replace(replace('Quando você comprar em sua compra normal na sua Fase de Compra: você pode revelar 1 desses cards; coloque-o no fundo do Deck e, se isso acontecer, compre 1 card. \r\nQuando você comprar como resultado de um efeito de card: você pode revelar 1 desses cards; envie este card para o Cemitério e, se isso acontecer, coloque esse card no fundo do Deck e, se isso acontecer, compre 1 card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20228463,'Sino Cerimonial','Os dois duelistas devem manter suas mãos reveladas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20240828,'Decoy',replace(replace('Um anjo da felicidade que desce sobre o monte sagrado. \r\nDizem que ele pousa junto com seu parceiro para realizar um ritual especial conhecido como o Primeiro Arremesso Ceremonial. \r\nDepois de encantar a todos com seu elegante casaco de pelos e sua aparência fofa, ele finaliza o ritual com um high five.\r\n\r\nO SHOWTIME, junto com seu parceiro, continuará....','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20246864,'Ventobruxa - Sino Congelante',replace(replace('Se todos os monstros que você controla forem monstros "Ventobruxa" (mín. 1): você pode Invocar este card por Invocação-Especial da sua mão. \r\nVocê só pode usar este efeito de "Ventobruxa - Sino Congelante" uma vez por turno. \r\nUma vez por turno, durante sua Fase Principal: você pode aumentar em 1 o Nível deste card. \r\nUm Monstro Sincro de VENTO que foi Invocado usando este card como Matéria Sincro não pode ser destruído em batalha.','\r',char(13)),'\n',char(10)),'','','O efeito de "Ventobruxa - Sino Congelante" está sendo aplicado.','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20248754,'Navio Saquepatrollha Moerk',replace(replace('2 monstros de Nível 4	\r\nVocê pode descartar 1 card "Saquepatrollha" e, depois, escolha 1 Monstro de Efeito que seu oponente controla; bana-o e, depois, você pode adicionar 1 Magia/Armadilha "Saquepatrollha" do seu Deck à sua mão. \r\nEste é um Efeito Rápido se este card estiver equipado com um card "Saquepatrollha". \r\nVocê só pode usar este efeito de "Navio Saquepatrollha Moerk" uma vez por turno. \r\nSe um ou mais cards "Saquepatrollha" que você controla seriam destruídos em batalha ou por um efeito de card, em vez disso, você pode desassociar 1 matéria deste card.','\r',char(13)),'\n',char(10)),'','Adicionar 1 Card de Magia/Armadilha "Saquepatrollha" do seu Deck à sua mão?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20264508,'Curto-Circuito do Trovão','Cause 400 de dano ao seu oponente para cada monstro que ele controla.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20265095,'Irmandade do Punho de Fogo - Pavão',replace(replace('2 monstros "Punho de Fogo"	\r\nEnquanto este card apontar para um monstro "Punho de Fogo", os monstros do seu oponente não podem escolher este card como alvo de ataques. \r\nQuando este card declarar um ataque: você pode enviar 1 Magia/Armadilha "Formação de Fogo" com a face para cima que você controla para o Cemitério e, depois, escolha 1 monstro que seu oponente controla; coloque esse monstro do oponente em uma zona para a qual este card apontar e tome o controle dele até a Fase Final, mas ele não pode declarar um ataque neste turno. \r\nVocê só pode usar este efeito de "Irmandade do Punho de Fogo - Pavão" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20277376,'Dragão Divino Apocralyph','Uma vez por turno: você pode descartar 1 card e, depois, escolher 1 monstro do Tipo Dragão no seu Cemitério; adicione o alvo à sua mão.','Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20277860,'Zumbi com Armadura','Este guerreiro brande cegamente uma lâmina letal, com uma força devastadora.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20281581,'Camarartista Carpesquilo',replace(replace('Escala de Pêndulo = 7\r\n[ Efeito de Pêndulo ]\r\nA não ser que você tenha um card na sua outra Zona de Pêndulo, destrua este card. \r\nEnquanto este card estiver na Zona de Pêndulo, qualquer dano de batalha que você sofrer é reduzido à metade.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nVIRE: Você pode escolher 1 card Baixado no campo; destrua-o. \r\nSe este card for Invocado por Invocação-Especial: você pode colocá-lo com a face para baixo em Posição de Defesa.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20285786,'Dois Passos para a Eternidade','Escolha 2 monstros no seu Cemitério; Invoque os dois por Invocação-Especial, mas negue seus efeitos (se houver) e, se isso acontecer, imediatamente depois que este efeito resolver, Invoque por Invocação-Xyz 1 Monstro Xyz "Utopia" ou "Utópico" de LUZ usando apenas esses 2 monstros.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20292186,'Artefato Foice',replace(replace('Você pode Baixar este card da sua mão na sua Zona de Magias & Armadilhas como uma Magia. \r\nDurante o turno do seu oponente, se este card Baixado na Zona de Magias & Armadilhas for destruído e enviado para o seu Cemitério: Invoque-o por Invocação-Especial. \r\nSe este card for Invocado por Invocação-Especial durante o turno do seu oponente: seu oponente não pode Invocar monstros por Invocação-Especial do Deck Adicional pelo resto deste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20295753,'Serpente da Espada Noturna',replace(replace('Se este card for enviado para o Cemitério por um efeito de card: você pode Invocar este card por Invocação-Especial, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar este efeito de "Serpente da Espada Noturna" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20315854,'Dragão Fada','Este lindo espírito de Dragão abriga uma força oculta.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20318029,'Matrizdragão do Trovão',replace(replace('(Efeito Rápido): você pode descartar este card e, depois, escolher 1 monstro Trovão que você controla; ele ganha 500 de ATK. \r\nSe este card for banido ou enviado do campo para o Cemitério: você pode adicionar 1 "Matrizdragão do Trovão" do seu Deck à sua mão. \r\nVocê só pode usar 1 efeito de "Matrizdragão do Trovão" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20343502,'Professora Magidoce Oculuflê',replace(replace('2 monstros "Magidoce" de Nível 4	\r\n(Efeito Rápido): você pode desassociar 1 matéria deste card e, depois, escolher 1 monstro "Magidoce" no campo; neste turno, esse monstro com a face para cima não é afetado por efeitos de monstro, exceto seu próprio. \r\nSe um card "Magidoce" for enviado para o seu Cemitério enquanto este card estiver no campo (exceto durante a Etapa de Dano): você pode embaralhar até 2 cards dos Cemitérios nos Decks. \r\nVocê só pode usar cada efeito de "Professora Magidoce Oculuflê" uma vez por turno.','\r',char(13)),'\n',char(10)),'Efeito de proteção','Recuperar do Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20345391,'Seal, o Estrategista de Peluguel',replace(replace('Durante sua Fase Principal: você pode Invocar por Invocação-Especial 1 monstro "de Peluguel" da sua mão, exceto "Seal, o Estrategista de Peluguel". \r\nSe um monstro "de Peluguel" for Invocado por Invocação-Especial no seu campo enquanto você controlar este monstro (exceto durante a Etapa de Dano): você pode escolher 1 monstro "de Peluguel" no seu Cemitério; adicione-o à sua mão. \r\nVocê só pode usar cada efeito de "Seal, o Estrategista de Peluguel" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20349913,'Caridade Galáctica',replace(replace('Se você controlar um Monstro Xyz "Galáxia": descarte 1 card; compre 2 cards e, além disso, se você ativou este card, qualquer dano que seu oponente sofrer pelo resto do turno é diminuído pela metade. \r\nVocê só pode ativar 1 "Caridade Galáctica" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20351153,'Hipnocórnio','Quando este card for Invocado por Invocação-Normal, se seu oponente controlar um monstro e você não controlar nenhum outro monstro: você pode escolher 1 Card de Magia/Armadilha Baixado no campo; destrua o alvo.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20357457,'Pilar do Futuro - Cyanos',replace(replace('(Este card deve ser sempre considerado como um card "Força Celeste".)	\r\nVocê pode descartar 1 Magia; Invoque este card por Invocação-Especial da sua mão. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode Invocar por Invocação-Especial 1 "Força Celeste - Ás - Roze" do seu Deck ou Cemitério e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto monstros Máquina. \r\nVocê pode banir este card do seu Cemitério; pegue 1 dos seus "Força Celeste - Ás - Roze" que estiver banido ou no seu Cemitério e adicione-o à sua mão ou Invoque-o por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Pilar do Futuro - Cyanos" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial da mão','Invocar por Invocação Especial do Deck/Cemitério','Adicionar à mão ou Invocar por Invocação Especial','Adicionar à mão','Invocação Especial','','','','','','','','','','','');
INSERT INTO texts VALUES(20358953,'Cruzador Tubarão','Se este card com a face para cima que você controla for destruído por um efeito de card do oponente, você pode Invocar por Invocação-Especial até 2 monstros de ÁGUA de Nível 4 ou menos do seu Deck.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20366274,'El Sombraneco Construtor',replace(replace('1 monstro "Sombraneco" + 1 monstro de LUZ	\r\nPrimeiro deve ser Invocado por Invocação-Fusão. \r\nSe este card for Invocado por Invocação-Especial: você pode enviar 1 card "Sombraneco" do seu Deck para o Cemitério. \r\nNo começo da Etapa de Dano, se este card batalhar um monstro Invocado por Invocação-Especial: destrua esse monstro. \r\nSe este card for enviado para o Cemitério: você pode escolher 1 Magia/Armadilha "Sombraneco" no seu Cemitério; adicione-a à sua mão.','\r',char(13)),'\n',char(10)),'Enviar para o Cemitério','Destruir','Adicionar à mão','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20366275,'El Sombraneco Construtor',replace(replace('1 monstro "Sombraneco" + 1 monstro de LUZ	\r\nPrimeiro deve ser Invocado por Invocação-Fusão. \r\nSe este card for Invocado por Invocação-Especial: você pode enviar 1 card "Sombraneco" do seu Deck para o Cemitério. \r\nNo começo da Etapa de Dano, se este card batalhar um monstro Invocado por Invocação-Especial: destrua esse monstro. \r\nSe este card for enviado para o Cemitério: você pode escolher 1 Magia/Armadilha "Sombraneco" no seu Cemitério; adicione-a à sua mão.','\r',char(13)),'\n',char(10)),'Enviar para o Cemitério','Destruir','Adicionar à mão','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20366276,'El Sombraneco Construtor',replace(replace('1 monstro "Sombraneco" + 1 monstro de LUZ	\r\nPrimeiro deve ser Invocado por Invocação-Fusão. \r\nSe este card for Invocado por Invocação-Especial: você pode enviar 1 card "Sombraneco" do seu Deck para o Cemitério. \r\nNo começo da Etapa de Dano, se este card batalhar um monstro Invocado por Invocação-Especial: destrua esse monstro. \r\nSe este card for enviado para o Cemitério: você pode escolher 1 Magia/Armadilha "Sombraneco" no seu Cemitério; adicione-a à sua mão.','\r',char(13)),'\n',char(10)),'Enviar para o Cemitério','Destruir','Adicionar à mão','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20368763,'Besta Fantasma Mecha Leosaqueador',replace(replace('Uma vez por tuno, quando um ou mais monstros que você controla forem oferecidos como Tributo para ativar um card ou um efeito que não seja deste card: Invoque por Invocação-Especial 1 "Ficha de Besta Fantasma Mecha" (Tipo Máquina/VENTO/Nível 3/ATK 0/DEF 0). \r\nO Nível deste card aumenta em um valor igual à soma dos Níveis de todas as "Fichas de Besta Fantasma Mecha" que você controla. \r\nEnquanto você controlar uma Ficha, este card não pode ser destruído em batalha ou por efeitos de card. \r\nUma vez por turno: você pode oferecer como Tributo 1 Ficha; Invoque por Invocação-Especial 1 monstro "Besta Fantasma Mecha" da sua mão.','\r',char(13)),'\n',char(10)),'Invocar uma Ficha por Invocação Especial','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20368764,'Ficha de Besta Fantasma Mecha','Invocado por Especial com o efeito de um monstro "Besta Fantasma Mecha" ou um card relacionado.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20374351,'Estelita Laval',replace(replace('1 Regulador + 1 ou mais monstros de FOGO não-Reguladores	\r\nQuando este card for Invocado por Invocação-Sincro: Envie 1 card da sua mão para o Cemitério. \r\nDurante o turno de qualquer duelista, quando este card for escolhido como alvo de um efeito de card: Você pode banir 1 monstro "Laval" do seu Cemitério; negue a ativação e, se isso acontecer, destrua o card escolhido.','\r',char(13)),'\n',char(10)),'Enviar 1 card da sua mão para o Cemitério','Negar a ativação e destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20374520,'Vai-te Embora, Tratante!','Se um monstro causar dano de batalha a um duelista: devolva esse monstro para a mão.','Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20394040,'Guarda de Batalha da Lava','Ganha 500 de ATK para cada "Guarda de Batalha do Pântano" que você controla.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20403123,'Camarartista Mago Prestidigitador',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) ao oferecer como Tributo 1 monstro "Camarartista", exceto um Monstro Pêndulo. \r\nUma vez por turno: você pode descartar 1 card e, depois, escolher 1 card com a face para cima no campo; destrua-o.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20409757,'Mago Observador do Tempo',replace(replace('Escala de Pêndulo = 8\r\n[ Efeito de Pêndulo ]\r\nVocê não pode controlar nenhum monstro para ativar este card. \r\nSe um Monstro Pêndulo que você controla batalhar, seu oponente não pode ativar Cards de Armadilha até o final da Etapa de Dano. \r\nA não ser que você tenha um card "Mago" ou um card "Olhos Anômalos" na sua outra Zona de Pêndulo, a Escala de Pêndulo deste card se torna 4.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nA cada turno, o(s) primeiro(s) card(s) nas suas Zonas de Pêndulo que seria(m) destruído(s) por um efeito de card do oponente, não é(são) destruído(s).','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20415050,'As Hecamãos Ocultas',replace(replace('Quando você ativar este card, você também pode enviar 1 outro card que você controla para o Cemitério; adicione 1 monstro "Hecamãos" do seu Deck à sua mão e, depois, se você enviou outro card para o Cemitério na ativação, você pode Baixar 1 Magia/Armadilha "Hecamãos" do seu Deck, exceto "As Hecamãos Ocultas". \r\nVocê pode banir este card do seu Cemitério; seu oponente compra 1 card e, depois, ele descarta 1 card. \r\nVocê só pode usar cada efeito de "As Hecamãos Ocultas" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Comprar','Enviar 1 card para o Cemitério para ativar?','Baixar?','','','','','','','','','','','','');
INSERT INTO texts VALUES(20417688,'Alinhamento Estelar pela Via Láctea',replace(replace('Revele 1 Monstro de Ritual na sua mão; adicione 1 Monstro de Ritual com o mesmo Nível, mas um nome diferente, do seu Deck à sua mão. \r\nVocê pode banir este card do seu Cemitério e enviar 1 Magia de Ritual da sua mão para o Cemitério; este efeito se torna o efeito desse card que Invoca um monstro por Invocação-Ritual quando o card for ativado. \r\nVocê só pode usar cada efeito de "Alinhamento Estelar pela Via Láctea" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20419926,'Executar Protocolos',replace(replace('Durante cada Fase de Batalha: você pode banir 1 Monstro Link de TREVAS do seu Cemitério e, depois, escolha 1 monstro "Callibre" que você controla; até o final deste turno, ele ganha ATK igual ao ATK do monstro banido para ativar este efeito. \r\nVocê só pode usar este efeito de "Executar Protocolos" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20424878,'Springans Rockey',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 "Grande Mar de Areia - Gold Golgonda" ou 1 monstro "Springans" no seu Cemitério, exceto "Springans Rockey"; adicione-o à sua mão. \r\nSe este card estiver na sua mão, no campo ou no Cemitério: você pode escolher 1 Monstro Xyz "Springans" que você controla; associe este card a ele como matéria. \r\nVocê só pode usar cada efeito de "Springans Rockey" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20426176,'Tesouro Saquepatrollha',replace(replace('Você pode declarar 1 Atributo e, depois, escolha 1 monstro com a face para cima que seu oponente controla; ele se torna desse Atributo até o final deste turno (mesmo que este card deixe o campo) e, depois, você pode pegar 1 monstro "Saquepatrollha" do seu Cemitério e, embaralhe-o no Deck ou Invoque-o por Invocação-Especial. \r\nVocê só pode usar este efeito de "Tesouro Saquepatrollha" uma vez por turno. \r\nUma vez por turno, durante a Fase Final, se você não controlar nenhum monstro "Saquepatrollha": envie este card para o Cemitério.','\r',char(13)),'\n',char(10)),'Alterar o Atributo','Envie este card para o Cemitério','Retornar o monstro ao Deck ou Invocá-lo por Invocação Especial?','Retornar ao Deck','','','','','','','','','','','','');
INSERT INTO texts VALUES(20426907,'Re-qliate',replace(replace('Se um monstro for Invocado por Invocação-Normal ou Virar e for um monstro de Nível 4 ou menos: negue seus efeitos até o final deste turno. \r\nSe um monstro (ou mais) for Invocado por Invocação-Especial e for um monstro de Nível 5 ou mais: negue seus afeitos até o final deste turno e, além disso, bana-o quando ele deixar o campo. \r\nSe não houver nenhum card "Qli" no campo, exceto "Re-qliate", envie este card para o Cemitério.','\r',char(13)),'\n',char(10)),'Usar o efeito agora?','Aplicar o efeito de "Re-qliate"','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20436034,'Anel do Magnetismo',replace(replace('Este card pode apenas equipar monstros do seu Campo. \r\nUm monstro equipado com este card diminui o seu ATK e DEF em 500 pontos. \r\nAlém disso, os monstros no Campo de seu adversário têm de atacar o monstro equipado com este card caso decidam atacar.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20438745,'Rei Pyron',replace(replace('Este card é considerado como um Monstro Normal enquanto estiver com a face para cima no campo ou no Cemitério. \r\nEnquanto este card estiver com a face para cima no campo, você pode Invocá-lo por Invocação-Normal para fazer com que ele seja considerado como um Monstro de Efeito com este efeito:\r\n● Uma vez por turno, você pode causar 1000 de dano ao seu oponente.','\r',char(13)),'\n',char(10)),'Receba 1000 pontos de dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20447641,'Fim Qlivido',replace(replace('Invoque este card por Invocação-Especial como um Monstro de Efeito (Tipo Máquina/TERRA/Nível 4/ATK 1800/DEF 1000).	\r\n(Este card NÃO é considerado como um Card de Armadilha.) \r\nDurante o turno em que este card foi Invocado desta forma, Cards de Magia/Armadilha "Qli" que você controla não podem ser destruídos por efeitos de card. \r\nSe Invocado desta forma, este card pode ser considerado como 3 Tributos para a Invocação-Tributo de um monstro "Apoqliphort".','\r',char(13)),'\n',char(10)),'Considere "Fim Qlivido" como 3 Tributos','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20448151,'Ensaio da Companhia de Palhaços',replace(replace('Ofereça como Tributo 1 monstro da sua mão ou do campo; adicione 1 "Companhia de Palhaços Biancaviso" e 1 Magia/Armadilha "Companhia de Palhaços", exceto "Ensaio da Companhia de Palhaços", do seu Deck à sua mão. \r\nVocê pode banir este card do seu Cemitério; Invoque por Invocação-Ritual 1 Monstro de Ritual "Companhia de Palhaços" da sua mão, ao oferecer como Tributo monstros da sua mão ou do campo cuja soma dos Níveis seja igual ou exceda seu Nível. \r\nVocê só pode usar cada efeito de "Ensaio da Companhia de Palhaços" uma vez por turno.','\r',char(13)),'\n',char(10)),'Efeito de busca','Invocação Ritual','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20450925,'Hanewata','(Efeito Rápido): você pode descartar este card; você não sofre dano de efeito neste turno.','O dano de efeito se torna 0','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20455229,'Defensor Firewall',replace(replace('Se este card for enviado para o Cemitério como matéria para a Invocação-Link de um monstro Ciberso: você pode Invocar por Invocação-Especial 1 monstro "Firewall" do seu Deck, exceto "Defensor Firewall". \r\nVocê não pode Invocar monstros por Invocação-Especial no turno em que ativar este efeito, exceto monstros Ciberso. \r\nSe um ou mais monstros "Firewall" que você controla seriam destruídos por um efeito de card, em vez disso, você pode banir este card do seu Cemitério. \r\nVocê só pode usar cada efeito de "Defensor Firewall" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20457551,'Armadura do Núcleo de Ferro',replace(replace('Só pode ser equipado a um monstro "Koa''ki Meiru". \r\nApenas durante o cálculo de dano, monstros que batalharem com o monstro equipado perdem ATK igual ao Nível do monstro equipado x 100. \r\nSe o monstro equipado seria destruído durante a Fase Final, em vez disso, você pode enviar este card para o Cemitério.','\r',char(13)),'\n',char(10)),'Usar o efeito de "Armadura do Núcleo de Ferro" em vez de ser destruído?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20470500,'Caçador Marinho Armado',replace(replace('Após o cálculo de dano, se este card batalhar com um Monstro de Efeito: Negue os efeitos daquele monstro (Incluindo no Cemitério). \r\nVocê deve controlar outro monstro de ÁGUA com a face para cima para ativar e resolver este efeito. \r\nSe este card seria destruído, em vez disso, você pode destruir 1 monstro de ÁGUA de Nível 3 ou menos com a face para cima que você controla.','\r',char(13)),'\n',char(10)),'Negar o efeito','Usar o efeito de "Caçador Marinho Armado" em vez de ser destruído?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20474741,'Guerreiro de Tridente','Quando este card for Invocado por Invocação-Normal: você pode Invocar por Invocação-Especial 1 monstro de Nível 3 da sua mão.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20501450,'Corrente de Concentração',replace(replace('Escolha 1 monstro com a face para cima que você controla; até o final deste turno, ele ganha ATK igual à sua DEF atual. \r\nOutros monstros que você controla não podem atacar durante o turno em que você ativar este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20508881,'Visão do Tufão Radiante',replace(replace('Se este card for destruído pelo efeito de "Tufão Espacial Místico": você pode Baixar este card. \r\nAtive 1 desses efeitos (mas você só pode usar cada um desses efeitos de "Visão do Tufão Radiante" uma vez por turno);\r\n● Compre 2 cards e, depois, se você tiver um card "Tufão Radiante" ou uma Magia Rápida na sua mão, descarte 1 deles, ou, se não tiver, descarte toda a sua mão.\r\n● Adicione 1 "Tufão Espacial Místico" do seu Deck ou Cemitério à sua mão.','\r',char(13)),'\n',char(10)),'Ativar','Baixar','Comprar','Buscar Tufão','','','','','','','','','','','','');
INSERT INTO texts VALUES(20513882,'Fuga Dolorosa','Ofereça 1 monstro como Tributo; adicione 1 monstro com o mesmo Tipo, Atributo e Nível originais, mas com um nome original diferente, do seu Deck ou Cemitério à sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20515672,'Força-S Perseguidor Noturno',replace(replace('1 monstro "Força-S" que não seja Link	\r\nCada um dos monstros do seu oponente na mesma coluna que um dos seus monstros "Força-S" não pode escolher os monstros em sua mesma coluna como alvo de ataques. \r\nDurante a Fase Principal (Efeito Rápido): você pode escolher 1 monstro "Força-S" que você controla; embaralhe-o no Deck e, depois, você pode Invocar por Invocação-Especial 1 dos seus monstros "Força-S" banidos. \r\nVocê só pode usar este efeito de "Força-S Perseguidor Noturno" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Invocar por Invocação Especial 1 dos seus monstros banidos?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20522190,'Força do Espelho Negro','Quando um monstro do oponente declarar um ataque: bana todos os monstros em Posição de Defesa que seu oponente controla.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20529766,'Dragão Voltech Supereletromagnético',replace(replace('Se você Invocar este card por Invocação-Tributo ao oferecer como Tributo 1 dos seguintes monstros, este card ganha o efeito apropriado:\r\n● Homem-Bateria D: Negue o efeito de um Card de Magia ou Armadilha que escolha este 1 card como alvo.\r\n● Homem-Bateria C: Durante uma batalha entre este card atacante e um monstro em Posição de Defesa com DEF menor que o ATK deste card, cause a diferença como Dano de Batalha ao oponente.\r\n● Homem-Bateria AA: Este card ganha 1000 de ATK.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20537097,'Mekk-Cavaleiro do Céu Azul',replace(replace('Se 2 ou mais cards estiverem na mesma coluna, você pode Invocar este card por Invocação-Especial (da sua mão) nessa coluna. \r\nVocê só pode Invocar "Mekk-Cavaleiro do Céu Azul" por Invocação-Especial uma vez por turno desta forma. \r\nSe este card for Invocado por Invocação-Normal ou Especial da mão: você pode adicionar monstros "Mekk-Cavaleiro" com nomes diferentes, exceto "Mekk-Cavaleiro do Céu Azul", do seu Deck à sua mão, igual ao número de cards do seu oponente na coluna deste card. \r\nVocê só pode usar este efeito de "Mekk-Cavaleiro do Céu Azul" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20541432,'Cetro de Chave nº 2','Este demônio desperta o pior nas pessoas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20546916,'Leão Botânico',replace(replace('Este card ganha 300 de ATK para cada monstro do Tipo Planta que você controla. \r\nO controle deste card com a face para cima no campo não pode ser trocado.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20560620,'Contagem de Bichos do Imperador Tanuki',replace(replace('Não pode ser oferecido como Tributo enquanto estiver com a face para cima na Zona de Monstros. \r\nEnquanto este card estiver na Zona de Monstros, quando você Invocar por Invocação-Ritual, você também pode enviar 1 monstro do seu Deck Adicional para o Cemitério como 1 dos monstros usados para a Invocação-Ritual. \r\nVocê só pode usar este efeito de "Contagem de Bichos do Imperador Tanuki" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20563387,'Número C80: Réquiem Enfurecido',replace(replace('3 monstros de Nível 5	\r\nVocê pode escolher 1 Monstro Xyz com a face para cima que você controla; equipe este monstro que você controla ao alvo. \r\nEle ganha 2000 de ATK. \r\nSe um monstro equipado com este card seria destruído, em vez disso, destrua este card. \r\nSe este card tiver "Número 80: Rapsódia Enfurecido" como uma Matéria Xyz, ele ganha este efeito.\r\n● Você pode desassociar 1 Matéria Xyz deste card e, depois, escolher 1 card no campo; bana o alvo.','\r',char(13)),'\n',char(10)),'Equipar a um Monstro Xyz que você controla como um Card de Equipamento','Escolha 1 card no Campo para banir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20568404,'Jurrac Stego',replace(replace('Durante sua Fase Principal: você pode destruir 1 card que você controla e, se isso acontecer, envie 1 monstro Dinossauro do seu Deck para o Cemitério e, depois, você pode Invocar por Invocação-Especial um ou mais monstros "Jurrac" da sua mão e/ou do Deck, exceto "Jurrac Stego", cuja soma dos Níveis seja igual ao Nível do monstro enviado, ignorando suas condições de Invocação e, além disso, pelo resto deste turno, você não pode Invocar por Invocação-Especial, exceto monstros Dinossauro. \r\nVocê só pode usar este efeito de "Jurrac Stego" uma vez por turno. \r\nQuando este card for destruído em batalha: você pode devolver 1 card com a face para cima no campo para a mão.','\r',char(13)),'\n',char(10)),'Destruir e enviar para o Cemitério','Retornar para a mão','Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20579538,'Princesbroto Silvestre',replace(replace('Você só pode ativar cada efeito de "Princesbroto Silvestre" uma vez por turno.\r\n● Você pode oferecer este card como Tributo; escave o card do topo do seu Deck, envie-o para o Cemitério e, depois, você pode colocar no topo do seu Deck 1 monstro "broto" do seu Cemitério.\r\n● Se este card for escavado do Deck e enviado para o Cemitério por um efeito de card: você pode declarar um Nível de 1 a 8; Invoque este card por Invocação-Especial do seu Cemitério e, se isso acontecer, ele se torna desse Nível.','\r',char(13)),'\n',char(10)),'Escave cards do seu Deck','Invocação Especial','Colocar 1 monstro "Broto" do seu Cemitério no topo do seu Deck?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20584712,'Valentão ESPIRÃO',replace(replace('O nome deste card se torna "Super Agente ESPIRÃO" enquanto ele estiver no campo ou no Cemitério. \r\nUma vez por turno: você pode declarar 1 tipo de card (Monstro, Magia ou Armadilha) e escolher 1 card que seu oponente controla; revele o card do topo do Deck do seu oponente e, se isso acontecer, destrua o card alvo se o card revelado for do tipo declarado.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20586572,'Dragão Explosivo',replace(replace('Se este card for destruído em batalha e enviado para o Cemitério: destrua o monstro que o destruiu. \r\nNenhum duelista sofre qualquer dano de batalha de ataques envolvendo este card atacante.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20590515,'Conquistador da Terra Dourada',replace(replace('Invoque este card por Invocação-Especial como um Monstro Normal (Zumbi/LUZ/Nível 5/ATK 500/DEF 1800) (este card ainda é considerado uma Armadilha) e, depois, se você controlar "Eldlich, o Senhor Dourado", você pode destruir 1 card com a face para cima no campo. \r\nDurante a Fase Final: você pode banir este card do seu Cemitério; Baixe 1 Magia/Armadilha "Eldlixir" diretamente do seu Deck. \r\nVocê só pode usar 1 efeito de "Conquistador da Terra Dourada" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Destruir o card selecionado?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20590784,'Nova Centelha de Poeira Estelar',replace(replace('Quando um monstro do oponente Invocado por Invocação-Especial declarar um ataque direto, se o ATK dele for maior ou igual que seus PV: negue o ataque e, se isso acontecer, compre 1 card e, depois, você pode Invocar por Invocação-Especial 1 monstro "Poeira Estelar" do seu Deck Adicional ou Cemitério. \r\nVocê só pode ativar 1 "Nova Centelha de Poeira Estelar" por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20612097,'Eldlixir do Sanguíneo Escarlate',replace(replace('Invoque por Invocação-Especial 1 monstro Zumbi do seu Deck ou do Cemitério, mas se você não controlar nenhum monstro "Eldlich", você só pode Invocar monstros "Eldlich" por Invocação-Especial com este efeito. \r\nPelo resto deste turno depois que este card resolver, você não pode Invocar monstros por Invocação-Especial, exceto monstros Zumbi. \r\nVocê pode banir este card do seu Cemitério; Baixe 1 Magia/Armadilha "Terra Dourada" diretamente do seu Deck. \r\nVocê só pode usar 1 efeito de "Eldlixir do Sanguíneo Escarlate" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20618081,'Salamagrande Falco',replace(replace('Se este card for enviado para o Cemitério: você pode escolher 1 Magia/Armadilha "Salamagrande" no seu Cemitério; Baixe o alvo no seu campo. \r\nSe este card estiver no seu Cemitério: você pode escolher 1 monstro "Salamagrande" que você controla, exceto "Salamagrande Falco"; devolva esse monstro para a mão e, se isso acontecer, Invoque este card por Invocação-Especial. \r\nVocê só pode usar 1 efeito de "Salamagrande Falco" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20618850,'Partícula Dourada Rúnika',replace(replace('Ative 1 desses efeitos, mas pule sua próxima Fase de Batalha depois da ativação;\r\n● Seu oponente compra 1 card e, depois, você bane os 4 cards do topo do Deck dele.\r\n● Invoque por Invocação-Especial 1 monstro "Rúnika(o)" do seu Deck Adicional na Zona de Monstros Adicional.	\r\nVocê só pode ativar 1 "Partícula Dourada Rúnika" por turno.','\r',char(13)),'\n',char(10)),'Seu oponente compra','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20624263,'Pavão','Um grande pavão que lança as suas penas num ataque letal.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20630765,'Karood, Feiticeiro da Pedra Mágica',replace(replace('Uma vez por turno, quando o efeito de outro Card de Monstro for ativado enquanto não houver Marcadores de Pedra Mágica neste card, coloque 1 Marcador de Pedra Mágica neste card (máx. 1). \r\nEste card ganha 300 de DEF para cada Marcador de Pedra Mágica nele. \r\nUma vez por turno, você pode remover 1 Marcador de Pedra Mágica do seu lado do campo para selecionar 1 card no Cemitério do seu oponente e remover este card de jogo.','\r',char(13)),'\n',char(10)),'Banir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20638610,'Renascimento do Dragão','Escolha 1 monstro Dragão que você controla; bana o alvo e, se isso acontecer, Invoque por Invocação-Especial 1 monstro Dragão da sua mão ou do Cemitério.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20644748,'Colapso Espacial',replace(replace('Você só pode ativar este card se tanto você quanto seu oponente tiverem 5 ou menos cards no campo. \r\nO número máximo de cards que cada duelista pode ter no campo é 5.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20654247,'Dragão do Caos de Olhos Azuis',replace(replace('Você pode Invocar este card por Invocação-Ritual com "Forma do Caos". \r\nDeve ser Invocado por Invocação-Ritual. \r\nSeu oponente não pode escolher este card como alvo de efeitos de card e, além disso, ele não pode ser destruído pelos efeitos de card do seu oponente. \r\nSe este card foi Invocado por Invocação-Ritual usando "Dragão Branco de Olhos Azuis", quando ele declarar um ataque: você pode mudar a posição de batalha de tantos monstros que seu oponente controla quanto possível e, se isso acontecer, o ATK/DEF desses monstros com a posição de batalha mudada se torna 0 e, além disso, neste turno, se este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20663556,'Batráquiostituto',replace(replace('Você pode oferecer 1 monstro como Tributo; Invoque por Invocação-Especial 1 monstro "Sapo" do seu Deck. \r\nMonstros "Sapo" não podem ser destruídos em batalha.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20665527,'Nave Enxame Anfíbia Ambuleia',replace(replace('2+ Monstros de Efeito	\r\nGanha 200 de ATK para cada Monstro Link nos Cemitérios. \r\nVocê só pode usar cada um dos seguintes efeitos de "Nave Enxame Anfíbia Ambuleia" uma vez por turno.\r\n● Se este card for destruído: você pode escolher 1 monstro de Link-3 ou menos em qualquer Cemitério; Invoque-o por Invocação-Especial.\r\n● Se um ou mais monstros de Link-3 ou menos no campo forem destruídos em batalha ou por um efeito de card enquanto este card estiver no seu Cemitério: você pode banir este card do seu Cemitério; destrua 1 card no campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20686759,'Motor Morfotrônico Enferrujado',replace(replace('Só pode ser equipado a um monstro "Morfotrônico(a)". \r\nSe o monstro equipado for destruído, cause dano a cada duelista igual ao ATK original dele.','\r',char(13)),'\n',char(10)),'Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20700531,'Peregrino da Barreira de Gelo','Não pode ser destruído em batalha com um monstro que tenha 1900 ou mais de ATK.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20714553,'Endymion, o Magistus Crescente',replace(replace('2 monstros, incluindo um monstro Mago de Nível 4	\r\nSe este card for Invocado por Invocação-Link: você pode escolher 1 monstro "Magistus" que você controla; equipe-o com 1 monstro Mago do seu Cemitério ou banimento como uma Magia de Equipamento. \r\nDurante a Fase Principal (Efeito Rápido): você pode escolher 1 Card de Monstro Mago na sua Zona de Magias & Armadilhas considerado como uma Magia de Equipamento; devolva-o para a mão. \r\nVocê só pode usar 1 efeito de "Endymion, o Magistus Crescente" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Efeito de Equipamento','Retornar para a mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20715411,'D/D/D Machinex, a Rainha do Fim Zero',replace(replace('Escala de Pêndulo = 0\r\n[ Efeito de Pêndulo ]\r\nDurante sua Fase Principal, se este card foi ativado neste turno: você pode colocar 1 Magia/Armadilha Contínua "Pacto Obscuro" do seu Deck com a face para cima no seu campo. \r\nVocê só pode usar este efeito de "D/D/D Machinex, a Rainha do Fim Zero" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe um ou mais cards "D/D/D" e/ou "Pacto Obscuro" com a face para cima que você controla, exceto "D/D/D Machinex, a Rainha do Fim Zero", forem destruídos enquanto este card estiver com a face para cima no seu Deck Adicional, mesmo durante a Etapa de Dano: você pode Invocar este card por Invocação-Especial e, depois, você pode destruir 1 card no campo. \r\nSe este card na Zona de Monstros for destruído: você pode colocar este card na sua Zona de Pêndulo. \r\nVocê só pode usar cada efeito de "D/D/D Machinex, a Rainha do Fim Zero" uma vez por turno.','\r',char(13)),'\n',char(10)),'Baixar um card "Pacto Obscuro"','Invocação Especial','Colocar na Zona de Pêndulo','Destruir?','','','','','','','','','','','','');
INSERT INTO texts VALUES(20720928,'Fator Metafis',replace(replace('A cada turno, 1 monstro "Metafis" de Nível 5 ou mais que você Invocar por Invocação-Normal pode ser Invocado sem Tributo, mas bana-o durante a Fase Final do próximo turno. \r\nSeu oponente não pode ativar cards ou efeitos em resposta à ativação dos efeitos dos seus monstros "Metafis".','\r',char(13)),'\n',char(10)),'Invocação Normal sem Tributo, pelo efeito de "Fator Metafis"','Invocar usando o efeito de "Fator Metafis"','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20721759,'Fenda Gélida','Quando exatamente 1 monstro que você controla for destruído e enviado para o Cemitério por um efeito de card do oponente: escolha 1 monstro que seu oponente controla; envie o alvo para o Cemitério e, se isso acontecer, cause dano ao seu oponente igual ao ATK original dela no Cemitério.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20721928,'Sparkman, o HERÓI do Elemento','Um HERÓI do Elemento e um guerreiro de luz que empunha proficientemente vários tipos de armamento. Sua Brilhante Onda de Relâmpagos corta o caminho dos vilões.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20721929,'Sparkman, o HERÓI do Elemento','Um HERÓI do Elemento e um guerreiro de luz que empunha proficientemente vários tipos de armamento. Sua Brilhante Onda de Relâmpagos corta o caminho dos vilões.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20721930,'Sparkman, o HERÓI do Elemento','Um HERÓI do Elemento e um guerreiro de luz que empunha proficientemente vários tipos de armamento. Sua Brilhante Onda de Relâmpagos corta o caminho dos vilões.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20726052,'Maliss ＜C＞ GWC-06',replace(replace('Você pode ativar este card no turno em que foi Baixado, ao banir 1 monstro "Maliss" com a face para cima que você controla. \r\nInvoque por Invocação-Especial 1 dos seus monstros "Maliss" que estiverem banidos ou no seu Cemitério e, depois, se você controlar um Monstro Link "Maliss", você pode ganhar PV igual ao ATK original desse monstro Invocado por Invocação-Especial. \r\nVocê só pode ativar 1 "Maliss ＜C＞ GWC-06" por turno.','\r',char(13)),'\n',char(10)),'','','Ativar aplicando o efeito de "Maliss ＜C＞ GWC-06".','Ganhar PV?','','','','','','','','','','','','');
INSERT INTO texts VALUES(20727787,'Desarmamento','Destrúa todos os Card de Equipamento no Campo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20735371,'Adeus Dano',replace(replace('Durante o cálculo de dano, se um monstro seu for atacado: seu monstro que estiver batalhando não pode ser destruído nessa batalha e, além disso, se você sofrer dano de batalha dessa batalha, seu oponente sofre dano de efeito igual ao dobro desse valor. \r\nVocê só pode aplicar este efeito de "Adeus Dano" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20745268,'Mágico Mosquete - Desperado',replace(replace('Se você controlar um monstro "Mágico(a) Mosquete": escolha 1 card com a face para cima no campo; destrua-o. \r\nVocê só pode ativar 1 "Mágico Mosquete - Desperado" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20747792,'Pequena Maga Baga',replace(replace('Se este card for Invocado por Invocação-Normal: você pode adicionar 1 monstro "Pequena Maga" do seu Deck à sua mão. \r\nUma vez por turno, durante o turno de qualquer duelista, quando seu oponente ativar um card ou efeito que escolha este card como alvo, ou escolha este card como alvo de um ataque: você pode mudar a posição de batalha deste card e, se isso acontecer, Invoque por Invocação-Especial 1 monstro "Pequena Maga" do seu Deck, exceto "Pequena Maga Baga".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20758643,'Graff, Malebranche do Abismo Ardente',replace(replace('Se você controlar um monstro que não seja um monstro "Abismo Ardente", destrua este card. \r\nVocê só pode usar 1 desses efeitos de "Graff, Malebranche do Abismo Ardente" por turno e apenas uma vez por turno.\r\n● Se você não controlar nenhuma Magia/Armadilha: você pode Invocar este card por Invocação-Especial da sua mão.\r\n● Se este card for enviado para o Cemitério: você pode Invocar por Invocação-Especial 1 monstro "Abismo Ardente" do seu Deck, exceto "Graff, Malebranche do Abismo Ardente".','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20765952,'Máscara da Dissipação',replace(replace('Selecione 1 Card de Magia com a face para cima no campo. \r\nO controlador do Card de Magia sofre 500 de dano durante cada uma de suas Fases de Apoio. \r\nQuando o card selecionado for removido do campo, destrua este card.','\r',char(13)),'\n',char(10)),'Causar dano aos PV','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20773176,'Zefraxa, Besta Flamejante de Necroz',replace(replace('Escala de Pêndulo = 7\r\n[ Efeito de Pêndulo ]\r\nVocê não pode Invocar monstros por Invocação-Pêndulo, exceto monstros "Necroz" e "Zefra". \r\nEste efeito não pode ser negado.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nEnquanto este card estiver na sua mão ou no Cemitério, se um ou mais cards "Necroz" ou "Zefra" com a face para cima, exceto "Zefraxa, Besta Flamejante de Necroz", forem destruídos em batalha ou por um efeito de card enquanto estiverem nas suas Zonas de Monstros ou Zonas de Pêndulo: você pode Invocar este card por Invocação-Especial. \r\nVocê só pode usar este efeito de "Zefraxa, Besta Flamejante de Necroz" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20781762,'Bombardeamento de Rocha','Envie 1 monstro Rocha do seu Deck para o Cemitério; cause 500 de dano ao seu oponente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20785975,'Número C103: Ragnafinito',replace(replace('3 monstros de Nível 5	\r\nUma vez por turno, durante o turno de qualquer duelista: você pode desassociar 1 Matéria Xyz deste card e, depois, escolher 1 monstro com a face para cima que seu oponente controla; cause dano ao seu oponente igual à diferença entre o ATK original e o ATK atual desse monstro e, se isso acontecer, bana-o. \r\nQuando este card for destruído e enviado para o Cemitério enquanto tiver uma Matéria Xyz: você pode Invocar este card por Invocação-Especial do seu Cemitério. "Número 103: Ragnazero" deve estar no seu Cemitério para que você possa ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Banir e causar dano','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20788863,'Dádiva Salamagrande',replace(replace('Você pode descartar 1 monstro "Salamagrande"; envie 1 monstro "Salamagrande" do seu Deck para o Cemitério e, depois, compre 1 card. \r\nSe você controlar um Monstro Link "Salamagrande" que foi Invocado por Invocação-Link usando um monstro com o mesmo nome como matéria: você pode descartar 1 monstro "Salamagrande"; compre 2 cards. \r\nVocê só pode usar 1 efeito de "Dádiva Salamagrande" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Enviar para o Cemitério e comprar 1 card','Compre 2 card(s)','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20797524,'Tricular','Quando este card for destruído em batalha e enviado ao Cemitério, você pode Invocar por Invocação-Especial 1 "Bicular" da sua mão ou Deck.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20799347,'Oto-Hime do Mundo Virtual - Toutou',replace(replace('Se você não controlar nenhum monstro ou se todos os monstros que você controla forem monstros Psíquico e/ou Wyrm, você pode Invocar este card por Invocação-Normal sem oferecer Tributo. \r\nSe este card estiver no seu Cemitério: você pode descartar 1 monstro Psíquico ou Wyrm; Invoque este card por Invocação-Especial como um Regulador, mas bana-o quando ele deixar o campo e, além disso, pelo resto deste turno, você só pode Invocar por Invocação-Especial monstros de Nível/Classe 3 ou mais. \r\nVocê só pode usar este efeito de "Oto-Hime do Mundo Virtual - Toutou" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Normal sem Tributo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20802187,'Conversor de Espírito',replace(replace('Uma vez por turno: você pode escolher 1 Monstro Xyz que você controla; associe 1 monstro de LUZ de Nível 4 que você controla a esse Monstro Xyz. \r\nSe este card for enviado do campo para o Cemitério: escolha 2 monstros Trovão de LUZ de Nível 4 com o mesmo nome no seu Cemitério; adicione os alvos à sua mão.','\r',char(13)),'\n',char(10)),'Reabastecer matérias','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20822520,'Biblioteca do Livro de Magia da Heliosfera',replace(replace('Se você tiver 5 ou mais Cards de Magia "Livro de Magia" no seu Cemitério: escave os 2 cards do topo do seu Deck, adicione à sua mão qualquer Card de Magia "Livro de Magia" escavado e, além disso, embaralhe os outros cards no Deck. \r\nVocê só pode ativar 1 "Biblioteca do Livro de Magia da Heliosfera" por turno. \r\nVocê não pode ativar Cards de Magia no turno em que ativar este card, exceto Cards de Magia "Livro de Magia".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20831168,'Soldado Lagarto','Um soldado bestial derivado dos dragões. É pequeno demais para um monstro do Tipo Dragão. Movendo-se muito rapidamente, este monstro é um excelente estrategista.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20838380,'Tubarão Adesivo',replace(replace('Quando um monstro do Tipo Peixe, Serpente Marinha ou Aqua for Invocado por Invocação-Normal ou Invocação-Especial no seu lado do campo: Você pode Invocar este card por Invocação-Especial da sua mão. \r\nEste card não pode ser usado como um Monstro-Matéria Sincro.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20848593,'Água de Gelo','Uma sereia muito agressiva que ataca os inimigos com espinhos que brotam do corpo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20849090,'Precursor de Kozmo',replace(replace('Não pode ser escolhido como alvo de um efeito de card do oponente. \r\nDurante sua Fase de Apoio: ganhe 1000 PV. \r\nSe este card for destruído em batalha ou por um efeito de card e enviado para o Cemitério: você pode banir este card do seu Cemitério; Invoque por Invocação-Especial 1 monstro "Kozmo" de Nível 6 ou menos do seu Deck.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20855340,'Evoltil Pleuro','Se este card que você controla for destruído e enviado ao seu Cemitério: Você pode Invocar por Invocação-Especial 1 monstro "Evolssauro" da sua mão.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20858318,'Combinação do Escorpião das Trevas',replace(replace('Você pode activar este card apenas quando você tem "Dom Zaloog", "Escorpião das Trevas - Cliff, o Eliminador de Armadilhas", "Escorpião das Trevas - Chick o Cobarde", "Escorpião das Trevas - Gorg o Forte", e "Escorpião das Trevas - Meanae o Espinho" no seu Campo com a face para cima. \r\nDurante este turno, qualquer um destes 5 cards pode atacar diretamente os Life Points do seu adversário. \r\nNesse caso, o dano de batalha infligido ao seu adversário por cada um desses cards torna-se 400 pontos.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20862918,'Raça Cruzada',replace(replace('Bana 2 monstros da sua mão e/ou com a face para cima no campo com o mesmo Tipo e Atributo originais, mas nomes diferentes; adicione 1 monstro com o mesmo Tipo e Atributo originais que os desses monstros, mas um nome diferente, do seu Deck à sua mão. \r\nVocê só pode ativar 1 "Raça Cruzada" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20871001,'Medicamento Azul','Ganhe 400 PV.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20899496,'Prisão do Dragão de Gelo',replace(replace('Escolha 1 monstro no Cemitério do seu oponente; Invoque-o por Invocação-Especial no seu campo, mas seus efeitos são negados e, depois, você pode banir 1 monstro do campo de cada duelista que tenham o mesmo Tipo um do outro. \r\nVocê só pode ativar 1 "Prisão do Dragão de Gelo" por turno.','\r',char(13)),'\n',char(10)),'Banir o monstro selecionado?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20904475,'Kairo Ryu-Ge Emva',replace(replace('Você pode descartar este card; adicione 1 "Reino Ryu-Ge - Espirais Marítimos" do seu Deck à sua mão. \r\nDurante sua Fase Principal, se 2 ou mais monstros foram enviados da mão e/ou do Deck para o Cemitério neste turno, exceto "Kairo Ryu-Ge Emva": você pode Invocar este card por Invocação-Especial do seu Cemitério. \r\nVocê pode colocar 1 "Reino Ryu-Ge - Espirais Marítimos" que você controla no fundo do Deck; bana toda a mão do seu oponente e, se isso acontecer, ele compra o mesmo número de cards. \r\nVocê só pode usar cada efeito de "Kairo Ryu-Ge Emva" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Invocar por Invocação Especial do Cemitério','Banir um card do seu oponente e comprar','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20920083,'Força Scrum',replace(replace('Enquanto você controlar 2 ou mais monstros com a face para cima em Posição de Defesa, seu oponente não pode escolher monstros em Posição de Defesa que você controla como alvos de efeitos de card e eles não podem ser destruídos pelos efeitos de card do seu oponente. \r\nSe este card seria destruído por um efeito de card, em vez disso, você pode destruir 1 card na sua Zona de Magias & Armadilhas.','\r',char(13)),'\n',char(10)),'Destruir outro card em vez disso?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20932152,'Sincron Gatilho-Rápido',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) ao enviar 1 monstro da sua mão para o Cemitério. \r\nPara uma Invocação-Sincro, você pode substituir este card por qualquer 1 Regulador "Sincron". \r\nNão pode ser usado como uma Matéria Sincro, exceto para a Invocação-Sincro de um monstro que mencione um Regulador "Sincron" como matéria.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20934683,'Devedoras de Azamina',replace(replace('Durante a Fase Principal: revele 1 Monstro de Fusão "Azamina" no seu Deck Adicional e, para cada 4 Níveis que ele tenha (arredondado para baixo), envie 1 card "Despojos do Pecado" da sua mão e/ou do campo para o Cemitério (se com a face para baixo, revele-o) e, depois, Invoque por Invocação-Especial esse monstro revelado. \r\n(Isso é considerado uma Invocação-Fusão.) \r\nDurante sua Fase Principal: você pode banir este card do seu Cemitério e, depois, escolha 1 monstro "Azamina" no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê só pode usar 1 efeito de "Devedoras de Azamina" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Invocar por Invocação Especial do Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20934852,'Marincesa Aqua Argonauta',replace(replace('2+ monstros de ÁGUA	\r\nEnquanto este card estiver na Zona de Monstros Adicional, os monstros do seu oponente não podem atacar nenhum monstro, exceto este. \r\nVocê só pode usar cada um dos seguintes efeitos de "Marincesa Aqua Argonauta" uma vez por turno. \r\nVocê pode escolher 1 monstro de ÁGUA que você controla e 1 card que seu oponente controla; devolva-os para a mão. \r\nDurante o turno do seu oponente, quando um Card de Magia/Armadilha ou seus efeitos forem ativados no campo (Efeito Rápido): você pode Invocar por Invocação-Especial 1 dos seus Cards de Monstro "Marincesa" equipados a este card e, se isso acontecer, negue esse efeito ativado.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20936251,'Tempestade Numeron','Se você controlar um monstro "Numerounius": destrua tantas Magias/Armadilhas que seu oponente controla quanto possível (mín. 1) e, se isso acontecer, cause 1000 de dano ao seu oponente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20938824,'Maliss ＜P＞ Lebre de Março',replace(replace('Seu oponente não pode escolher Monstros Link "Maliss" que apontarem para este card como alvo de efeitos de card. \r\nVocê só pode usar cada um dos seguintes efeitos de "Maliss ＜P＞ Lebre de Março" uma vez por turno. \r\nDurante a Fase Principal, se este card estiver na sua mão (Efeito Rápido): você pode banir 1 outro card "Maliss" da sua mão ou do Cemitério e, se isso acontecer, Invoque este card por Invocação-Especial. \r\nSe este card for banido: você pode pagar 300 PV e, depois, escolha 1 dos seus monstros "Maliss" banidos; adicione-o à sua mão.','\r',char(13)),'\n',char(10)),'Invocação Especial','','Adicionar à mão','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20939559,'Assassino das Sombras','Se os únicos cards na Zona dos Cards de Monstro do seu adversário são monstros em Posição de Defesa, este card pode atacar os Life Points do seu adversário diretamente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20951752,'Voltanis, o Adjudicador',replace(replace('Depois que 1 dos seus Cards de Armadilha de Resposta for ativado e resolvido, você pode oferecer como Tributo todos os monstros que você controla para Invocar este card por Invocação-Especial. \r\nSe este card for Invocado por Invocação-Especial dessa forma, você pode destruir cards controlados pelo oponente igual ao número de monstros do Tipo Fada oferecidos como Tributo.','\r',char(13)),'\n',char(10)),'Invocação Especial','Destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20960340,'Avatar de Kristal',replace(replace('Quando um monstro do oponente declarar um ataque direto, se o ATK dele for maior ou igual que os seus PV: Invoque este card por Invocação-Especial em Posição de Ataque como um Monstro de Efeito (Tipo Guerreiro/LUZ/Nível 4/ATK ?/DEF 0) com ATK igual aos seus PV e, depois, mude o alvo do ataque para este card.	\r\n(Este card ainda é considerado um Card de Armadilha.) \r\nSe este card Invocado desta forma for destruído em batalha, depois do cálculo de dano: cause dano ao seu oponente igual ao ATK dele.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20985997,'Círculo Detonador "A"','Destrua 1 monstro com a face para cima com um ou mais Marcadores-A e, depois, cause 1000 de dano a cada duelista.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20989253,'Rostos Familiares da Diversão',replace(replace('Escolha 1 monstro que seu oponente controla equipado com uma ou mais das suas Armadilhas "Atração"; equipe este card a ele. \r\nEnquanto este card estiver equipado a um monstro, tome o controle do monstro equipado. \r\nEnquanto você controlar o monstro equipado, ele ganha 500 de ATK, você não pode ativar seus efeitos e, além disso, ele é considerado como um monstro "Diversão". \r\nVocê só pode ativar 1 "Rostos Familiares da Diversão" por turno.','\r',char(13)),'\n',char(10)),'O efeito de "Rostos Familiares da Diversão" está sendo aplicado.','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20994205,'Números Eveil','Se seu oponente controlar um ou mais monstros Invocados por Invocação-Especial do Deck Adicional e você não: selecione 4 Monstros Xyz "Número" do seu Deck Adicional com Classes diferentes, mais um 5º Monstro Xyz "Número" cujo valor do "Número" em seu nome seja igual aos valores combinados dos "Número" dos outros 4 monstros, Invoque por Invocação-Especial esse 5º monstro "Número" (isso é considerado uma Invocação-Xyz) e associe os 4 monstros selecionados a ele como matéria, mas você não pode Invocar monstros por Invocação-Especial, exceto Monstros Xyz "Número", enquanto você controlar esse monstro com a face para cima.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21007444,'Técnica da Espada de Dois Fios',replace(replace('Escolha 2 monstros "Seis Samurai" no seu Cemitério; Invoque os alvos por Invocação-Especial em Posição de Ataque. \r\nDurante a Fase Final deste turno, destrua-os e, se isso acontecer, sofra dano igual ao ATK desses monstros destruídos.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21011044,'Dissidência Sombraneco',replace(replace('Durante a Fase Principal, você pode: Invocar por Invocação-Fusão 1 Monstro de Fusão "Sombraneco" do seu Deck Adicional, ao banir as Matérias de Fusão mencionadas nele do seu campo ou Cemitério, mas ele não pode atacar diretamente. \r\nDepois, você pode enviar para o Cemitério 1 monstro que seu oponente controla com o mesmo Atributo que o desse monstro Invocado por Invocação-Fusão. \r\nVocê só pode usar este efeito de "Dissidência Sombraneco" uma vez por turno.','\r',char(13)),'\n',char(10)),'Enviar um monstro do oponente para o Cemitério?','O efeito de "Dissidência Sombraneco" está sendo aplicado.','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21015833,'Cavaleiro Hayabusa','Este card pode realizar um segundo ataque durante cada Fase de Batalha.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21036656,'Cyclos, o Duende Circular',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode descartar 1 card; adicione 1 Regulador Inseto ou Planta do seu Deck à sua mão, exceto "Cyclos, o Duende Circular". \r\nSe um ou mais Monstros Sincro Inseto ou Planta forem Invocados por Invocação-Especial, enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar cada efeito de "Cyclos, o Duende Circular" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21044178,'Habitante do Abismo',replace(replace('2 monstros de Nível 4	\r\nEnquanto este card tiver uma matéria associada a ele que era originalmente de ÁGUA, todos os monstros de ÁGUA que você controla ganham 500 de ATK. \r\nUma vez por turno (Efeito Rápido): você pode desassociar 1 matéria deste card; seu oponente não pode ativar nenhum efeito de card no Cemitério dele neste turno.','\r',char(13)),'\n',char(10)),'Restrição de ativação','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21050476,'Argostars - Feroz Parthe',replace(replace('Ganha 700 de ATK/DEF para cada monstro "Argostars" com um nome diferente que você controla, exceto este card. \r\nVocê só pode usar cada um dos seguintes efeitos de "Argostars - Feroz Parthe" uma vez por turno. \r\n(Efeito Rápido): você pode revelar este card na sua mão; devolva 1 Armadilha Contínua "Argostars" que você controla para a mão e, se isso acontecer, Invoque este card por Invocação-Especial. \r\nVocê pode banir este card que você controla; Baixe 1 Armadilha Contínua da sua mão. \r\nEla pode ser ativada neste turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','Baixar','Ativar aplicando o efeito de "Argostars - Feroz Parthe".','','','','','','','','','','','','');
INSERT INTO texts VALUES(21051146,'Mago do Sangue',replace(replace('Sempre que um Card de Magia for ativado, coloque 1 Marcador de Magia neste card quando esse Card de Magia resolver. \r\nVocê pode remover qualquer número de Marcadores de Magia deste card e, depois, escolher 1 monstro com a face para cima no campo com ATK menor ou igual ao número de marcadores que você removeu x 700; destrua o alvo.','\r',char(13)),'\n',char(10)),'Destruir','Destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21051977,'Boloto','Durante sua Fase Principal: Você pode enviar 1 "Pinhoto" da sua mão ao Cemitério e Invocar por Invocação-Especial este card da sua mão.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21056275,'Reabelião Armada',replace(replace('Invoque por Invocação-Especial 1 monstro Inseto com 1000 ou menos de ATK da sua mão ou do Deck e, depois, se você Invocar por Invocação-Especial do Deck, envie 1 monstro que você controla para o Cemitério e, além disso, você não pode Invocar por Invocação-Especial pelo resto deste turno depois que este card resolver, exceto monstros Inseto. \r\nSe um ou mais Monstros Sincro Inseto com a face para cima que você controla forem destruídos em batalha ou por um efeito de card, enquanto este card estiver no seu Cemitério: você pode banir este card; adicione 1 "Invocação do Enxame" do seu Deck à sua mão. \r\nVocê só pode ativar 1 "Reabelião Armada" por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21057444,'Marincesa Primagarota',replace(replace('Você pode banir 1 monstro "Marincesa" do seu Cemitério; Invoque este card por Invocação-Especial da sua mão. \r\nSe este card for enviado para o Cemitério como matéria para a Invocação-Link de um monstro de ÁGUA: você pode enviar cards do topo do seu Deck para o Cemitério, igual ao número de monstros "Marincesa" que você controla e, depois, se um ou mais cards "Marincesa" foram enviados para o Cemitério por este efeito, cause 200 de dano ao seu oponente para cada card "Marincesa" enviado. \r\nVocê só pode usar cada efeito de "Marincesa Primagarota" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21065189,'Dragão eXcede Firewall',replace(replace('2+ monstros de Nível 4	\r\nEste card Invocado por Invocação-Xyz ganha 500 de ATK x a soma dos Valores Link dos Monstros Link linkados a este card. \r\nVocê pode desassociar 2 matérias deste card e, depois, escolher 1 Monstro Link Ciberso de Link-4 no seu Cemitério; Invoque-o por Invocação-Especial no seu campo de forma que ele aponte para este card e, além disso, você não pode Invocar outros monstros por Invocação-Especial ou atacar diretamente pelo resto deste turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21070956,'Altar para Tributos',replace(replace('Escolha 1 monstro no seu Campo e envie-o para o Cemitério. \r\nAumente os seus Life Points num valor igual ao ATK original do monstro.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21074344,'Arauto da Luz Verde','Quando seu oponente ativar um Card de Magia (Efeito Rápido): você pode enviar este card e 1 outro monstro Fada da sua mão para o Cemitério; negue a ativação e, se isso acontecer, destrua-o.','Negue a ativação do Card de Magia do seu oponente','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21076084,'Reencravação Trapestrela',replace(replace('Bana toda a mão do seu oponente e, se isso acontecer, ele compra o mesmo número de cards. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 monstro "Trapestrela" no seu Cemitério; Invoque-o por Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21082832,'Forma do Caos',replace(replace('Este card pode ser usado para a Invocação-Ritual de qualquer Monstro de Ritual "Caos" ou "Soldado do Lustro Negro". \r\nVocê também deve oferecer como Tributo monstros da sua mão ou do campo e/ou banir "Dragão Branco de Olhos Azuis" ou "Mago Negro" do seu Cemitério, cuja soma dos Níveis seja exatamente igual ao Nível do Monstro de Ritual "Caos" ou "Soldado do Lustro Negro" que você Invocar por Invocação-Ritual.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21088856,'Espião-Espicante',replace(replace('Se este card for Invocado por Invocação-Especial: olhe 1 card aleatório do Deck Adicional do seu oponente e se ele tiver 2000 ou mais de ATK, este card ganha 1000 de ATK. \r\nSe ele tiver 2000 ou menos de ATK, você ganha PV igual ao ATK desse monstro.','\r',char(13)),'\n',char(10)),'Verificar o Deck Adicional','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21105106,'Necroz de Sofia',replace(replace('Você pode Invocar este card por Invocação-Ritual com qualquer Magia de Ritual "Necroz". \r\nDeve ser Invocado por Invocação-Ritual, usando 3 monstros que você controla com Tipos diferentes. \r\nDurante a Fase Principal 1 (Efeito Rápido): você pode descartar este card e 1 Magia "Necroz"; seu oponente não pode Invocar por Invocação-Especial do Deck Adicional durante esta fase. \r\nQuando este card for Invocado por Invocação-Ritual: você pode banir todos os outros cards no campo e nos Cemitérios. \r\nVocê não pode Invocar outros monstros por Invocação-Normal/Baixar ou por Invocação-Especial no turno em que ativar este efeito.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21113684,'Mago Arcanita Supremo',replace(replace('1 Monstro Sincro do Tipo Mago + 1 monstro do Tipo Mago	\r\nEste monstro só pode ser Invocado por Invocação-Especial por Invocação-Fusão (do Deck Adicional). \r\nQuando este card for Invocado por Invocação-Fusão, coloque 2 Marcadores de Magia nele. \r\nEste card ganha 1000 de ATK para cada Marcador de Magia nele. \r\nUma vez por turno, você pode remover 1 Marcador de Magia do seu lado do campo para ativar 1 dos seguintes efeitos:\r\n● Selecione 1 card no campo e destrua-o.\r\n● Compre 1 card.','\r',char(13)),'\n',char(10)),'Colocar Marcadores de Magia','Destrua 1 card no campo','Compre 1 card(s)','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21123811,'Dragão da Chama Cósmica',replace(replace('1 Monstro Sincro Regulador + 2+ Monstros Sincro não-Reguladores	\r\nDeve ser Invocado por Invocação-Sincro. \r\n(Efeito Rápido): você pode banir este card até a Fase Final para ativar 1 desses efeitos;\r\n● Quando seu oponente ativar um card ou efeito: negue a ativação e, se isso acontecer, destrua esse card.\r\n● Quando seu oponente Invocaria um ou mais monstros: negue a Invocação e, se isso acontecer, destrua esse(s) monstro(s).\r\n● Quando um monstro do oponente declarar um ataque: negue o ataque e, depois, encerre a Fase de Batalha.','\r',char(13)),'\n',char(10)),'Negar a ativação e destruir','Negar a Invocação e destruir','Negar o ataque','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21140872,'Dragão Retalhador de Olhos Vermelhos',replace(replace('"Dragão Negro de Olhos Vermelhos" + 1 monstro Guerreiro	\r\nQuando um monstro "Olhos Vermelhos" declarar um ataque: você pode escolher 1 monstro Guerreiro no seu Cemitério; equipe-o a este card como uma Magia de Equipamento que concede 200 de ATK a este card. \r\nQuando um card ou efeito for ativado que escolha como alvo um card que você controla (Efeito Rápido): você pode enviar 1 Card de Equipamento que você controla para o Cemitério; negue a ativação e, se isso acontecer, destrua esse card. \r\nSe este card for destruído em batalha ou por um efeito de card: você pode Invocar por Invocação-Especial tantos monstros do seu Cemitério quanto possível que estavam equipados neste card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21142671,'Vermelho Nova',replace(replace('Se um Monstro Sincro Dragão de Nível 8 ou mais estiver no campo, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Vermelho Nova" por Invocação-Especial uma vez por turno desta forma. \r\nSe este card for enviado para o Cemitério para uma Invocação-Sincro que use 2 ou mais Reguladores como matéria: você pode Invocar por Invocação-Especial 1 monstro Demônio de FOGO do seu Deck em Posição de Defesa.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21143940,'Mudar a Máscara','Escolha 1 monstro "HERÓI" que você controla; envie-o para o Cemitério e, além disso, depois, se ele deixou o campo por este efeito, Invoque por Invocação-Especial do seu Deck Adicional, 1 monstro "HERÓI Mascarado" com o mesmo Atributo que o monstro enviado tinha quando estava no campo (o Atributo original dele, se ele estava com a face para baixo).','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21143941,'Mudar a Máscara','Escolha 1 monstro "HERÓI" que você controla; envie-o para o Cemitério e, além disso, depois, se ele deixou o campo por este efeito, Invoque por Invocação-Especial do seu Deck Adicional, 1 monstro "HERÓI Mascarado" com o mesmo Atributo que o monstro enviado tinha quando estava no campo (o Atributo original dele, se ele estava com a face para baixo).','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21147203,'Minimalien',replace(replace('Você pode banir 1 outro card da sua mão; Invoque este card por Invocação-Especial da sua mão. \r\nVocê pode banir 1 monstro de Nível 4 ou menos com a face para cima que você controla; Invoque por Invocação-Especial 1 monstro do seu Deck com o mesmo Tipo e Atributo originais que o monstro banido tinha no campo, mas 1 ou 2 Níveis menor que o Nível original dele. \r\nVocê só pode usar cada efeito de "Minimalien" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar este card por Invocação Especial','Invocar por Invocação Especial do Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21155323,'Golem de Óculos',replace(replace('Este card é considerado como um Monstro Normal enquanto estiver com a face para cima no campo ou no Cemitério. \r\nEnquanto este card estiver com a face para cima no campo, você pode Invocá-lo por Invocação-Normal para fazer com que ele seja considerado como um Monstro de Efeito com este efeito:\r\n● O ATK original deste card se torna 2100.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21159309,'Dragão Majestoso','Não pode ser usado como Matéria Sincro, exceto para a Invocação-Sincro de um monstro "Majestoso".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21175632,'Santa Joana','"A Donzela do Perdão" + "Senhora Obscura Maria"','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21179143,'Prole Reptiliana','Bana 1 monstro "Reptiliano(a)" do seu Cemitério; Invoque por Invocação-Especial 2 "Ficha de Reptiliano" (Réptil/TERRA/Nível 1/ATK 0/DEF 0).','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21179144,'Ficha de Reptiliano','Invocado por Especial com o efeito "Prole Reptiliana" ou um card relacionado.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21187631,'Dragvirion Altergeist',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nQuando um monstro do oponente Invocado por Invocação-Especial declarar um ataque: você pode devolver 1 monstro "Altergeist" que você controla para a mão; negue o ataque. \r\nSe este card for oferecido como Tributo e enviado para o Cemitério: você pode Invocar este card por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Dragvirion Altergeist" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21200905,'Aromági-serafim Jasmim',replace(replace('2 monstros Planta	\r\nSe seus PV forem maiores que os do seu oponente, este card e quaisquer monstros Planta para os quais ele apontar não podem ser destruídos em batalha. \r\nVocê pode oferecer como Tributo 1 monstro para o qual este card apontar; Invoque por Invocação-Especial 1 monstro Planta do seu Deck em Posição de Defesa. \r\nVocê só pode usar este efeito de "Aromági-serafim Jasmim" uma vez por turno. \r\nUma vez por turno, se você ganhar PV: adicione 1 monstro Planta do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21208154,'O Perverso Avatar',replace(replace('Não pode ser Invocado por Invocação-Especial. \r\nDeve ser Invocado por Invocação-Normal/Baixado ao oferecer 3 monstros como Tributo. \r\nSe este card for Invocado por Invocação-Normal: seu oponente não pode ativar Cards de Magia/Armadilha até o final do 2º turno dele depois da ativação deste efeito. \r\nO ATK/DEF deste card são iguais ao maior ATK no campo +100, exceto "O Perverso Avatar".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21219755,'Anel Destruidor','Destrua 1 monstro com a face para cima no seu campo para causar 1000 de dano aos PV dos dois duelistas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21223277,'Rei Artorigus, Nobre Cavaleiro',replace(replace('2 monstros "Nobre Cavaleiro" de Nível 4	\r\nQuando este card for Invocado por Invocação-Xyz: você pode escolher até 3 Cards de Magia de Equipamento "Armas Nobres" com nomes diferentes no seu Cemitério; equipe os alvos a este card. \r\nUma vez por turno: você pode desassociar 1 Matéria Xyz deste card; destrua qualquer número de Cards de Magia/Armadilha no campo, até o número de Cards de Magia de Equipamento "Armas Nobres" que você controla.','\r',char(13)),'\n',char(10)),'Equipar','Destruir Magias/Armadilhas','Escolher outro Card de Equipamento?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21225115,'Dragão Fóssil Skullgios',replace(replace('1 monstro Rocha + 1 monstro de Nível 7 ou mais no Cemitério do seu oponente	\r\nPrimeiro deve ser Invocado por Invocação-Especial com "Fusão Fóssil". \r\nAntes do cálculo de dano, se este card batalhar um monstro do oponente: você pode trocar o ATK e a DEF atuais desse monstro do oponente até o final da Etapa de Dano. \r\nSe este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante. \r\nSe este card Invocado por Invocação-Fusão batalhar um monstro do oponente, qualquer dano de batalha que ele causar ao seu oponente é dobrado.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21237481,'Esmagador Mágico de Tipo Zero','Descarte 1 Card de Magia da sua mão para causar 500 de dano ao seu oponente.','Causar dano','Usar o efeito de "Esmagador Mágico de Tipo Zero" agora?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21239280,'Rato de Ossos','Um rato que voltou como zumbi para se vingar dos gatos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21249921,'Cavaleiro Dragunidade - Vajrayana',replace(replace('1 Regulador Dragão + 1+ monstros Besta Alada não-Reguladores	\r\nQuando este card for Invocado por Invocação-Sincro: você pode escolher 1 monstro "Dragunidade" Dragão de Nível 3 ou menos no seu Cemitério; equipe o alvo a este card. \r\nUma vez por turno: você pode enviar 1 Card de Equipamento equipado a este card para o Cemitério; dobre o ATK deste card até a Fase Final.','\r',char(13)),'\n',char(10)),'Equipar','Alterar ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21250202,'Dragão Persona de Olhos Anômalos',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno, durante a Fase Final, se seu oponente ativou um card ou efeito neste turno que escolheu como alvo 1 Monstro Pêndulo "Olhos Anômalos" que você controlava (e nenhum outro card) enquanto este card estava na sua Zona de Pêndulo: Invoque este card por Invocação-Especial e, se isso acontecer, coloque 1 Monstro Pêndulo "Olhos Anômalos" com a face para cima do seu Deck Adicional na sua Zona de Pêndulo, exceto "Dragão Persona de Olhos Anômalos".\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nUma vez por turno (Efeito Rápido): você pode escolher 1 monstro com a face para cima no campo que foi Invocado por Invocação-Especial do Deck Adicional; até o final deste turno, ele tem seus efeitos negados.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21251800,'Lúcifer Portador da Luz','Eu sou o governante de toda a criação, sentado no trono supremo... que haja luz!','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21254443,'Marco Legado Mundial','Bana 1 monstro "Legado Mundial" da sua mão ou com a face para cima no seu campo e, depois, escolha 2 monstros no seu Cemitério; Invoque-os por Invocação-Especial, mas eles não podem atacar neste turno.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21263083,'Besta Pálida','Com a sua pele tingida por um branco azulado, é difícil suportar a aparência aterradora desta estranha criatura.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21281085,'Levilazebul Mitológico',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nUma vez por turno, durante a Fase Principal (Efeito Rápido): você pode oferecer como Tributo qualquer número de monstros "Mitológico(a)" e, se isso acontecer, tome o controle desse número de monstros com a face para cima que seu oponente controla, mas seus efeitos são negados. \r\nSe este card estiver no seu Cemitério: você pode escolher 1 outro card "Mitológico(a)" no seu Cemitério; devolva este card para o Deck Adicional e, se isso acontecer, adicione o alvo à sua mão. \r\nVocê só pode usar este efeito de "Levilazebul Mitológico" uma vez por turno.','\r',char(13)),'\n',char(10)),'Tome o controle','Recuperar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21291696,'Besta Eletrodo Cation',replace(replace('Se este card for Invocado por Invocação-Normal: você pode adicionar 1 "Besta Eletrodo Anion" do seu Deck ou Cemitério à sua mão e, depois, imediatamente depois que este efeito resolver, você pode Invocar por Invocação-Normal 1 monstro Trovão de Nível 4 ou menos e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto Monstros Xyz de LUZ. \r\nVocê pode escolher 1 outro monstro Trovão que você controla que tenha um Nível; o Nível deste card se torna o desse monstro até o final deste turno. \r\nVocê só pode usar cada efeito de "Besta Eletrodo Cation" uma vez por turno.','\r',char(13)),'\n',char(10)),'Buscar "Besta Eletrodo Anion" e Invocá-lo','Alterar o Nível','Invocação Normal?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21293424,'Naviushi Gunkan Porta-aviões Classe Shirauo',replace(replace('2 monstros de Nível 4	\r\nSe este card for Invocado por Invocação-Xyz: você pode aplicar esses efeitos, em sequência, de acordo com as matérias usadas. \r\nVocê só pode usar este efeito de "Naviushi Gunkan Porta-aviões Classe Shirauo" uma vez por turno.\r\n● "Shari do Naviushi Gunkan": Compre 1 card.\r\n● "Shirauo do Naviushi Gunkan": Adicione 1 Magia/Armadilha "Gunkan" do seu Deck à sua mão.	\r\nEnquanto um card com a face para cima estiver em uma Zona do Campo, monstros "Gunkan" que você controla que foram Invocados por Invocação-Especial do Deck Adicional não podem ser destruídos pelos efeitos de card do seu oponente e ganham ATK igual à sua DEF original.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21296383,'Unipássaro',replace(replace('Você pode remover de jogo este card e 1 monstro com a face para cima que você controla para selecionar 1 Monstro Sincro no seu Cemitério com um Nível menor ou igual aos Níveis originais combinados dos outros 2 monstros. \r\nInvoque por Invocação-Especial esse Monstro Sincro.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21296502,'Mago Negro Toon',replace(replace('Não pode atacar no turno em que for Invocado. \r\nEnquanto você controlar "Mundo Toon" e seu oponente não controlar nenhum monstro Toon, este card pode atacar diretamente seu oponente. \r\nUma vez por turno: você pode descartar 1 card "Toon" e, depois, ative 1 desses efeitos;\r\n● Invoque por Invocação-Especial 1 monstro Toon do seu Deck, exceto "Mago Negro Toon", ignorando suas condições de Invocação.\r\n● Adicione 1 Magia/Armadilha "Toon" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Invocação Especial','Procurar no Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21297224,'Fada Histérica','Ofereça como Tributo 2 monstros no seu lado do campo para aumentar seus PV em 1000 pontos.','Ganhar PV','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21313376,'Número 14: Sarama Gananciosa',replace(replace('2 monstros de Nível 5	\r\nSeu oponente sofre qualquer dano de efeito que você teria sofrido dos efeitos de card dele, em vez de você. \r\nQuando este card destruir um monstro do oponente em batalha e enviá-lo para o Cemitério: você pode desassociar 1 Matéria Xyz deste card; destrua todos os monstros no campo cujo ATK atual seja menor ou igual que o ATK original do monstro destruído no Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21323861,'Chuva Ácida','Destrua todos os monstros Máquina no campo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21340051,'Soldado Javali',replace(replace('Este card só pode ser Invocado por Invocação-Virar. \r\nSe Invocado por Invocação-Normal, este card é destruído. \r\nSe seu oponente tiver 1 ou mais monstros sob o controle dele, o ATK deste card é reduzido em 1000.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21347668,'Sonolenta Lembrança Purrely',replace(replace('O próximo dano de batalha ou de efeito que você sofrer neste turno se torna 0. \r\nVocê também pode imediatamente aplicar o seguinte efeito.\r\n● Descarte 1 card e, se isso acontecer, Invoque por Invocação-Especial do seu Deck 1 monstro "Purrely" de Nível 1.	\r\nUm Monstro Xyz "Purrely" que tenha este card como matéria ganha o seguinte efeito.\r\n● Uma vez por turno, durante a Fase de Apoio do seu oponente: você pode comprar 1 card.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial do Deck?','Compre 1 card (Sonolenta Lembrança Purrely)','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21347810,'Flor Arco-íris','Este monstro pode atacar diretamente os Life Points do seu adversário.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21350571,'Chifre da Besta Fantasma',replace(replace('Escolha 1 monstro Besta ou Besta-Guerreira que você controla; equipe este card no alvo. \r\nEle ganha 800 de ATK. \r\nSe o monstro equipado destruir um monstro do seu oponente em batalha e enviá-lo para o Cemitério: compre 1 card.','\r',char(13)),'\n',char(10)),'Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21351206,'Infernobre Cavaleiro Ogier',replace(replace('Enquanto este card for um Card de Equipamento, o monstro equipado não pode ser destruído por efeitos de card. \r\nVocê só pode usar cada um dos seguintes efeitos de "Infernobre Cavaleiro Ogier" uma vez por turno. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode enviar 1 card "Armas Nobres", ou 1 monstro Guerreiro de FOGO exceto "Infernobre Cavaleiro Ogier", do seu Deck para o Cemitério. \r\nSe este card estiver no seu Cemitério: você pode escolher 1 monstro Guerreiro que você controla; equipe este card a esse monstro que você controla.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21362970,'Ataque Bestial','Uma vez por turno, você pode descartar 1 card para Invocar por Invocação-Especial 1 "Moja" do seu Deck.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21364070,'Mayosenju Hitot',replace(replace('Escala de Pêndulo = 3\r\n[ Efeito de Pêndulo ]\r\nVocê pode escolher 1 card "Yosenju" na sua Zona de Pêndulo; pelo resto deste turno, sua Escala de Pêndulo se torna 11 e, além disso, você não pode Invocar monstros por Invocação-Especial, exceto monstros "Yosenju" (mesmo que este card deixe o campo). \r\nDurante sua Fase Final: devolva este card para a mão. \r\nVocê só pode usar cada Efeito de Pêndulo de "Mayosenju Hitot" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nNão pode ser Invocado por Invocação-Especial, exceto por Invocação-Pêndulo. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 card que seu oponente controla; devolva-o para a mão. \r\nSempre que um ou mais cards no campo forem devolvidos para a mão ou Deck Principal por um efeito de card seu, enquanto este card estiver no campo: todos os monstros "Yosenju" que você controla atualmente ganham 500 de ATK. \r\nUma vez por turno, durante a Fase Final, se este card foi Invocado por Invocação-Especial neste turno: devolva-o para a mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21368273,'Mannadium Trisukta',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro: você pode escolher 1 Regulador de Nível 2 no seu Cemitério; Invoque-o por Invocação-Especial, mas negue seus efeitos. \r\nVocê pode escolher qualquer número de Reguladores que você controla; mude o Nível deles para 2 e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto Monstros Sincro. \r\nVocê só pode usar cada efeito de "Mannadium Trisukta" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21368442,'Força-S Gravitino',replace(replace('Cada um dos monstros do seu oponente na mesma coluna que um dos seus monstros "Força-S" é banido quando deixar o campo. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 card "Força-S" do seu Deck à sua mão, exceto "Força-S Gravitino". \r\nVocê só pode usar este efeito de "Força-S Gravitino" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21377582,'Master da Paz, o Verdadeiro Dracoassassino Rei',replace(replace('Para Invocar este card por Invocação-Tributo com a face para cima, você pode oferecer como Tributo Magias/Armadilhas Contínuas que você controla, assim como monstros. \r\nNão é afetado pelos efeitos de cards com o mesmo tipo de card (Monstro, Magia e/ou Armadilha) que os tipos de card originais dos cards oferecidos como Tributo para sua Invocação-Tributo. \r\nUma vez por turno, se você controlar este monstro Invocado por Invocação-Tributo (Efeito Rápido): você pode banir 1 Magia/Armadilha Contínua do seu Cemitério e, depois, escolha 1 outro card no campo; destrua-o.','\r',char(13)),'\n',char(10)),'Invocação Tributo ao oferecer como Tributo um Card de Magia/Armadilha','Continuar selecionando Cards de Magia/Armadilha para oferecer como Tributo?','Destruir um card no Campo','Invocação Tributo ao oferecer como Tributo um Monstro','Invocação Tributo ao oferecer como Tributo um Card de Magia','Invocação Tributo ao oferecer como Tributo um Card de Armadilha','','','','','','','','','','');
INSERT INTO texts VALUES(21390858,'Dharc - Espírito-Possuído',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão ou Deck) ao enviar 1 "Dharc, o Encantador das Trevas" com a face para cima que você controla e 1 monstro de TREVAS com a face para cima que você controla ao Cemitério. \r\nQuando fizer isso: Você pode adicionar 1 monstro de LUZ do Tipo Mago de Nível 3 ou 4 do seu Deck à sua mão. \r\nSe este card foi Invocado por Invocação-Especial por este efeito e atacar um monstro em Posição de Defesa, cause Dano de Batalha perfurante ao seu oponente.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21414674,'Mão Proeminente','Se você controlar uma "Mão Mágica", "Mão de Fogo" ou "Mão de Gelo", você pode Invocar este card por Invocação-Especial (da sua mão).','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21417692,'Elfa Negra','Este card requer um custo de 1000 Life Points para atacar.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21419436,'Alma Desacorrentada - Abominador da Fúria',replace(replace('2+ monstros, incluindo um monstro Demônio	\r\nSe seu oponente Invocar por Invocação-Especial um ou mais monstros com a face para cima: você pode escolher 1 deles; destrói 1 monstro Demônio que você controla, e se fizer, negue os efeitos do monstro escolhido até o final deste turno.\r\nQuando um efeito de monstro é ativado no campo e você controla um Monstro Link "Desacorrentado(a)" de Link-4 ou maior (Efeito Rápido): você pode banir este card do seu Cemitério; destrua o monstro que ativou aquele efeito.\r\nVocê só pode usar cada efeito de "Alma Desacorrentada - Abominador da Fúria" uma vez por turno.','\r',char(13)),'\n',char(10)),'Negar','Destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21420702,'Tri-Acelerador de Explosão',replace(replace('Ative este card ao enviar 1 "Acelerador de Explosão" com a face para cima que você controla para o Cemitério. \r\nDurante sua Fase Principal: você pode escolher 1 monstro que seu oponente controla; envie 1 monstro Piro da sua mão para o Cemitério e, se isso acontecer, destrua o alvo e, se isso acontecer, cause 500 de dano ao seu oponente. \r\nSeus monstros não podem atacar no turno em que ativar este efeito.','\r',char(13)),'\n',char(10)),'Destruir 1 monstro que seu oponente controla','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21435914,'Dragão Dracocitos Alma-Infernal Corrompida',replace(replace('1 Regulador de TREVAS + 1 monstro não-Regulador do Tipo Dragão	\r\nNão pode ser destruído em batalha. \r\nQuando este card destruir um monstro do oponente em batalha e enviá-lo para o Cemitério: você pode ativar este efeito; este card pode realizar um segundo ataque em seguida contra um monstro do oponente. \r\nDurante sua Fase de Apoio: você pode escolher 1 monstro com a face para cima que seu oponente controla; o ATK dele se torna metade do ATK atual dele e, se isso acontecer, cause dano ao seu oponente igual ao valor de ATK perdido.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21438286,'Cajado do Desespero do Arquidemônio',replace(replace('Só pode ser equipado a um monstro que você controla. \r\nDurante sua Fase Principal: você pode fazer com que todos os monstros que seu oponente controla atualmente percam ATK igual à metade do ATK do monstro equipado até o final deste turno (mesmo que este card deixe o campo). \r\nSe este card for enviado para o Cemitério enquanto estiver equipado a um monstro: você pode pagar 1000 PV; devolva este card para a sua mão. \r\nVocê só pode usar cada efeito de "Cajado do Desespero do Arquidemônio" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21441617,'Orcust Esqueleto de Pratos',replace(replace('Você pode banir este card do seu Cemitério e, depois, escolha 1 monstro "Orcust" no seu Cemitério, exceto "Orcust Esqueleto de Pratos"; Invoque-o por Invocação-Especial e, além disso, você não pode Invocar por Invocação-Especial pelo resto deste turno, exceto monstros de TREVAS. \r\nVocê só pode usar este efeito de "Orcust Esqueleto de Pratos" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21452275,'Jarra do Aromági',replace(replace('Se este card estiver virado com a face para cima, este card não pode ser destruído em batalha enquanto estiver com a face para cima no campo. \r\nDurante a Fase Final de qualquer duelista, se este card estiver virado com a face para cima: você ganha 500 PV.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21454943,'Comandante Psíquico','Quando um monstro do Tipo Psíquico que você controla batalhar, durante a Etapa de Dano você pode pagar PV em múltiplos de 100 (máx. 500) para fazer com que o monstro que ele estiver batalhando perca essa quantidade de ATK e DEF até a Fase Final.','Reduzir ATK/DEF','Escolha os PV a pagar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21466326,'Explodir as Ruínas',replace(replace('Você só pode ativar este card se houver 30 ou mais cards no seu Cemitério. \r\nCause 3000 de dano ao seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21481146,'Força do Espelho Radiante','Quando um monstro do oponente declarar um ataque enquanto ele controlar 3 ou mais monstros em Posição de Ataque: destrua todos os monstros em Posição de Ataque que seu oponente controla.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21488686,'Rejuvenescimento Psíquico','Ganhe 1000 PV para cada monstro do Tipo Psíquico com a face para cima que você controla.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21495657,'Zefraxi, Tesouro de Yang Zing',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nVocê não pode Invocar monstros por Invocação-Pêndulo, exceto monstros "Yang Zing" e "Zefra". \r\nEste efeito não pode ser negado.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe este card for Invocado por Invocação-Pêndulo ou Invocado por Invocação-Especial do Deck Principal: você pode escolher 1 monstro "Yang Zing" ou "Zefra" que você controla, exceto "Zefraxi, Tesouro de Yang Zing"; esse monstro com a face para cima é considerado como um Regulador neste turno e, além disso, coloque este card no fundo do Deck quando ele deixar o campo. \r\nVocê só pode usar este efeito de "Zefraxi, Tesouro de Yang Zing" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21496848,'Evigishki Tetra Ogro',replace(replace('Você pode Invocar este card por Invocação-Ritual com qualquer Magia de Ritual "Gishki". \r\nUma vez por turno: você pode declarar 1 tipo de card (Monstro, Magia ou Armadilha); seu oponente pode descartar 1 card para negar este efeito, caso contrário, cada duelista envia 1 card do tipo declarado do Deck dele para o Cemitério.','\r',char(13)),'\n',char(10)),'Declarar um tipo de card e enviá-lo ao Cemitério','Card de Monstro','Card de Magia','Card de Armadilha','Descartar 1 card?','Declare um tipo de card','','','','','','','','','','');
INSERT INTO texts VALUES(21501505,'Cairngorgon, o Cavaleiro Antiluminescente',replace(replace('2 monstros de Nível 4	\r\nDurante o turno de qualquer duelista, quando outro card ou efeito for ativado que escolha como alvo exatamente 1 card no campo (e nenhum outro card): você pode desassociar 1 Matéria Xyz deste card e, depois, escolher como alvo outro card no campo que seria um alvo apropriado para esse card/efeito; esse card/efeito agora escolhem o novo alvo.','\r',char(13)),'\n',char(10)),'Alterar alvo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21501961,'Susto do Par de Ursos!!',replace(replace('Seu oponente pode revelar 1 "Susto do Par de Ursos!!" na mão ou no Deck dele e, se isso acontecer, cada duelista ganha 2000 PV. \r\nSe ele não o fizer, você destrói 1 monstro que seu oponente controla. \r\nSe este card for enviado do campo para o Cemitério: adicione este card à mão do seu oponente. \r\nVocê só pode usar este efeito de "Susto do Par de Ursos!!" uma vez por Duelo. \r\nVocê só pode ativar 1 "Susto do Par de Ursos!!" por turno.','\r',char(13)),'\n',char(10)),'Ativar','Adicionar à mão','Revelar?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21502796,'Ryko, Caçador Luminoso',replace(replace('VIRE: Aplique esses efeitos (simultaneamente).\r\n● Você pode destruir 1 card no campo.\r\n● Envie os 3 cards do topo do seu Deck para o Cemitério.','\r',char(13)),'\n',char(10)),'Destruir','Destruir 1 card?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21507589,'Troca de Peixes','Descarte 1 card para escolher 2 dos seus monstros do Tipo Peixe, Serpente Marinha ou Aqua banidos; adicione-os à sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21516908,'Alta-Velocidaroide Hagoita',replace(replace('1 Regulador + 1 ou mais monstros não-Reguladores	\r\n(Efeito Rápido): você pode oferecer este card como Tributo; até o final deste turno, aumente em 1 o Nível de todos os monstros atualmente no campo. \r\nSe este card estiver no seu Cemitério e você controlar um monstro Regulador "Velocidaroide": você pode Invocar este card por Invocação-Especial e, além disso, você não pode Invocar por Invocação-Especial pelo resto deste turno, exceto monstros de VENTO. \r\nVocê só pode usar este efeito de "Alta-Velocidaroide Hagoita" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21521304,'Número 39: Além da Utopia',replace(replace('2 monstros de Nível 6	\r\nSe este card for Invocado por Invocação-Xyz: o ATK de todos os monstros que seu oponente controla atualmente se torna 0. \r\nUma vez por turno (Efeito Rápido): você pode desassociar 1 matéria deste card e, depois, escolha 1 Monstro Xyz com a face para cima que você controla e 1 monstro "Utopia" no seu Cemitério; bana o primeiro alvo e, se isso acontecer, Invoque o segundo alvo por Invocação-Especial e, depois, ganhe 1250 PV.','\r',char(13)),'\n',char(10)),'ATK torna-se 0','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21522601,'Fazticeira Madame Verre',replace(replace('Durante o cálculo de dano, se um monstro Mago seu batalhar um monstro do oponente (Efeito Rápido): você pode revelar qualquer número de Magias com nomes diferentes na sua mão e, se isso acontecer, até o final deste turno, seu monstro que está batalhando ganha 1000 de ATK/DEF para cada card revelado. \r\n(Efeito Rápido): você pode descartar 1 Magia; até o final deste turno, negue os efeitos de todos os monstros com a face para cima que seu oponente controla atualmente. \r\nVocê só pode usar cada efeito de "Fazticeira Madame Verre" uma vez por turno.','\r',char(13)),'\n',char(10)),'Aumentar ATK','Negar o efeito','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21522602,'Fazticeira Madame Verre',replace(replace('Durante o cálculo de dano, se um monstro Mago seu batalhar um monstro do oponente (Efeito Rápido): você pode revelar qualquer número de Magias com nomes diferentes na sua mão e, se isso acontecer, até o final deste turno, seu monstro que está batalhando ganha 1000 de ATK/DEF para cada card revelado. \r\n(Efeito Rápido): você pode descartar 1 Magia; até o final deste turno, negue os efeitos de todos os monstros com a face para cima que seu oponente controla atualmente. \r\nVocê só pode usar cada efeito de "Fazticeira Madame Verre" uma vez por turno.','\r',char(13)),'\n',char(10)),'Aumentar ATK','Negar o efeito','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21522603,'Fazticeira Madame Verre',replace(replace('Durante o cálculo de dano, se um monstro Mago seu batalhar um monstro do oponente (Efeito Rápido): você pode revelar qualquer número de Magias com nomes diferentes na sua mão e, se isso acontecer, até o final deste turno, seu monstro que está batalhando ganha 1000 de ATK/DEF para cada card revelado. \r\n(Efeito Rápido): você pode descartar 1 Magia; até o final deste turno, negue os efeitos de todos os monstros com a face para cima que seu oponente controla atualmente. \r\nVocê só pode usar cada efeito de "Fazticeira Madame Verre" uma vez por turno.','\r',char(13)),'\n',char(10)),'Aumentar ATK','Negar o efeito','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21524779,'Matrovã','Uma vez por turno: Você pode Invocar por Invocação-Normal 1 monstro de LUZ do Tipo Trovão de Nível 4 da sua mão, exceto "Matrovã", como uma Invocação-Normal adicional.','Invocar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21546416,'Dragão Armado do Trovão LV5',replace(replace('O nome deste card se torna "Dragão Armado LV5" enquanto ele estiver no campo ou no Cemitério. \r\nVocê só pode usar cada um dos seguintes efeitos de "Dragão Armado do Trovão LV5" uma vez por turno. \r\nVocê pode enviar 1 monstro da sua mão para o Cemitério; envie este card do campo para o Cemitério e, se isso acontecer, Invoque por Invocação-Especial 1 monstro "Dragão Armado" de Nível 7 ou menos da sua mão ou do Deck. \r\nSe este card for enviado para o Cemitério para ativar o efeito de um monstro Dragão: você pode adicionar 1 monstro Dragão de VENTO de Nível 5 ou mais do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21558682,'Defensor da Geleia','Quando um monstro do oponente declarar um ataque contra um monstro que você controla: você pode escolher 1 "Geleia Renascida" que você controla; troque o alvo do ataque para esse alvo.','Alterar o alvo do ataque','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21565445,'Neptabismo, o Príncipe Atlante',replace(replace('Você pode enviar 1 monstro "Atlante" do seu Deck para o Cemitério, exceto "Neptabismo, o Príncipe Atlante"; adicione 1 card "Atlante" do seu Deck à sua mão, exceto "Neptabismo, o Príncipe Atlante". \r\nSe este card for enviado para o Cemitério para ativar o efeito de um monstro de ÁGUA: escolha 1 monstro "Atlante" no seu Cemitério, exceto "Neptabismo, o Príncipe Atlante"; Invoque-o por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Neptabismo, o Príncipe Atlante" uma vez por turno.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21570001,'Novo Mundo Translúcido',replace(replace('Escolha 1 monstro com a face para cima que você controla; destrua-o e, se isso acontecer, Invoque por Invocação-Especial 1 monstro do seu Deck em Posição de Defesa, com um Tipo e Atributo originais diferentes, cujo Nível seja menor que o Nível original desse monstro, mas negue seus efeitos. \r\nVocê só pode ativar 1 "Novo Mundo Translúcido" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21576077,'Eclipse Drytron',replace(replace('Escolha 1 monstro "Drytron" no seu Cemitério; adicione-o à sua mão. \r\nDurante sua Fase Principal, exceto no turno em que este card foi enviado para o Cemitério: você pode banir este card do seu Cemitério e, depois, escolha 1 monstro "Drytron" que você controla; ele ganha 2000 de ATK até o final do turno do seu oponente. \r\nVocê só pode usar cada efeito de "Eclipse Drytron" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21579049,'Recife do Círculo Branco',replace(replace('Escolha 1 monstro Peixe que você controla; destrua esse monstro Peixe e, se isso acontecer, adicione 1 monstro com o mesmo nome que ele tinha no campo do seu Deck à sua mão, ou, se você controlava um Monstro Sincro Peixe quando ativou este card, em vez disso, você pode Invocá-lo por Invocação-Especial. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 2 monstros Peixe com o mesmo nome no seu Cemitério; coloque 1 dos 2 no fundo do seu Deck e, se isso acontecer, Invoque o outro por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Recife do Círculo Branco" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21593977,'Makyura, o Destruidor',replace(replace('Se este card for enviado da Zona de Monstros para o Cemitério: você pode ativar 1 Card de Armadilha da sua mão neste turno. \r\nVocê só pode usar este efeito de "Makyura, o Destruidor" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar aplicando o efeito de "Makyura, o Destruidor".','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21597117,'Um Herói Aparece',replace(replace('Quando um monstro do oponente declarar um ataque: seu oponente seleciona 1 card aleatório da sua mão e, depois, se for um monstro que possa ser Invocado por Invocação-Especial, Invoque-o por Invocação-Especial. \r\nCaso contrário, envie-o para o Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21598948,'Caixa Fada',replace(replace('Quando um monstro do oponente declarar um ataque: lance uma moeda e escolha cara ou coroa. \r\nSe você ganhar, o ATK do monstro atacante se torna 0 até o final da Fase de Batalha. \r\nDurante cada uma das suas Fases de Apoio, pague 500 Pontos de Vida ou destrua este card.','\r',char(13)),'\n',char(10)),'Alterar ATK','Pagar 500 PV para manter "Caixa Fada"?','Cara','Coroa','Escolha Cara ou Coroa','','','','','','','','','','','');
INSERT INTO texts VALUES(21607304,'Voltelúrico, o Behemoth Subterror',replace(replace('VIRE: Você pode escolher 1 monstro Baixado que seu oponente controla; tome o controle dele até o final da sua próxima Fase Final. \r\nVocê só pode usar este efeito de "Voltelúrico, o Behemoth Subterror" uma vez por turno.\r\nQuando um monstro com a face para cima que você controla for virado com a face para baixo, se você não controlar nenhum monstro com a face para cima: você pode Invocar este card por Invocação-Especial da sua mão em Posição de Defesa. \r\nUma vez por turno: você pode colocar este card com a face para baixo em Posição de Defesa.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21615956,'Guarda Flamvell','Um guardião de Flamvell que comanda o fogo com sua força de vontade. Sua ardente barreira de magma protege suas tropas de invasores.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21620076,'Pintor da Dor',replace(replace('O nome deste card se torna "Zumbi Espalha-praga" enquanto estiver no campo. \r\nUma vez por turno: você pode escolher até 2 monstros Zumbi que você controla, exceto este card; eles se tornam de Nível 2 (até o final deste turno) e, se isso acontecer, eles não podem ser usados como Matéria Sincro, exceto para a Invocação-Sincro de um monstro Zumbi.','\r',char(13)),'\n',char(10)),'Alterar Nível','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21623008,'Força Celeste - Manobra - Explosão Vetorial','Se você não controlar nenhum monstro na sua Zona de Monstros Principal: cada duelista envia os 2 cards do topo do seu próprio Deck para o Cemitério (ou tantos quanto possível, se houver menos de 2) e, depois, se você enviou pelo menos 1 card para o Cemitério e tiver 3 ou mais Magias no seu Cemitério, você pode embaralhar no Deck todos os monstros do seu oponente nas Zonas de Monstros Adicionais.','Retornar para o Deck o monstro do seu oponente na Zona de Monstros Extra?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21636650,'Despertar do Milagre','Escolha 1 monstro que foi destruído em batalha e enviado para o seu Cemitério neste turno; Invoque-o por Invocação-Especial.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21637210,'Dragão Firewall Singularidade',replace(replace('3+ Monstros de Efeito	\r\n(Efeito Rápido): você pode escolher cards no campo e/ou Cemitério do seu oponente até o número de tipos de card diferentes (Ritual, Fusão, Sincro, Xyz) no seu campo e Cemitério; devolva-os para a mão e, além disso, este card ganha 500 de ATK para cada card devolvido. \r\nSe um monstro para o qual este card apontar for destruído em batalha ou enviado para o Cemitério: você pode escolher 1 monstro Ciberso no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Dragão Firewall Singularidade" uma vez por turno.','\r',char(13)),'\n',char(10)),'Retornar um card do seu oponente para a mão','Invocar por Invocação Especial um monstro Ciberso do Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21637211,'Dragão Firewall Singularidade',replace(replace('3+ Monstros de Efeito	\r\n(Efeito Rápido): você pode escolher cards no campo e/ou Cemitério do seu oponente até o número de tipos de card diferentes (Ritual, Fusão, Sincro, Xyz) no seu campo e Cemitério; devolva-os para a mão e, além disso, este card ganha 500 de ATK para cada card devolvido. \r\nSe um monstro para o qual este card apontar for destruído em batalha ou enviado para o Cemitério: você pode escolher 1 monstro Ciberso no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Dragão Firewall Singularidade" uma vez por turno.','\r',char(13)),'\n',char(10)),'Retornar um card do seu oponente para a mão','Invocar por Invocação Especial um monstro Ciberso do Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21637502,'Hecamãos Breus',replace(replace('Se este card batalhar um monstro, nenhum dos dois pode ser destruído nessa batalha. \r\nVocê só pode usar cada um dos seguintes efeitos de "Hecamãos Breus" uma vez por turno. \r\nSe um ou mais cards forem adicionados à mão do seu oponente (exceto durante a Fase de Compra ou Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão. \r\nDurante sua Fase Principal: você pode olhar 1 card aleatório na mão do seu oponente e, depois, se for um monstro, você pode Invocá-lo por Invocação-Especial no seu campo.','\r',char(13)),'\n',char(10)),'Invocação Especial','Invocação Especial','Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21639276,'Preparações Kashtira',replace(replace('Durante o turno de qualquer duelista: você pode Invocar por Invocação-Especial 1 dos seus monstros "Kashtira" que estiverem banidos ou na sua mão. \r\nSe seu oponente ativar um Card de Armadilha ou seus efeitos, você controlar um monstro "Kashtira" e este card já estiver com a face para cima na sua Zona de Magias & Armadilhas: você pode olhar a mão do seu oponente e, se isso acontecer, bana 1 card dali, com a face para baixo. \r\nVocê só pode usar cada efeito de "Preparações Kashtira" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Banir da mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21648584,'Ataqueraptor - Prontidão',replace(replace('Neste turno, monstros "Ataqueraptor" que você controla não podem ser destruídos em batalha. \r\nSe você tiver um monstro "Ataqueraptor" no seu Cemitério: você pode banir este card do seu Cemitério; você não sofre dano neste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21663205,'Mandante do Coveiro',replace(replace('Se este card for Invocado: você pode escolher 1 monstro "do Coveiro" de Nível 4 no seu Cemitério; Invoque-o por Invocação-Especial em Posição de Ataque ou com a face para baixo em Posição de Defesa. \r\nVocê só pode usar este efeito de "Mandante do Coveiro" uma vez por turno. \r\nEste efeito não é afetado por "Necro-Vale".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21672573,'Imperador Sem','Sempre que você Invocar um monstro por Invocação-Tributo, cada duelista pode selecionar 1 card do seu Cemitério e devolvê-lo para o topo do seu Deck.','Retornar ao Deck','Escolher 1 card no Cemitério para colocá-la no topo do Deck?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21677871,'Orgulho Dourado - Liguem os Motores!','Se seu oponente Invocar um ou mais monstros por Invocação-Normal ou Especial: escolha 1 desses monstros; revele 3 monstros "Orgulho Dourado" do seu Deck, seu oponente elege 1 deles aleatoriamente para que você Invoque por Invocação-Especial, embaralhe o resto no seu Deck e, depois, destrua o monstro alvo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21686473,'D/D/D Zero Laplace, o Rei do Destino',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nDurante sua Fase Principal: você pode adicionar 1 Monstro Pêndulo "D/D/D" com a face para cima do seu Deck Adicional à sua mão, exceto "D/D/D Zero Laplace, o Rei do Destino". \r\nVocê só pode usar este efeito de "D/D/D Zero Laplace, o Rei do Destino" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nVocê pode Invocar este card por Invocação-Especial (da sua mão) ao oferecer como Tributo 1 monstro "D/D/D". \r\nAntes do cálculo de dano, se este card batalhar um monstro do oponente: você pode ativar este efeito; até o final da Etapa de Dano, o ATK deste card se torna o dobro do ATK original desse monstro do oponente. \r\nSe este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante. \r\nNa primeira vez que este card seria destruído em batalha a cada turno, ele não é destruído, e você não sofre dano de batalha dessa batalha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21698716,'Fera Cristalina Águia Cobalto',replace(replace('Uma vez por turno: você pode escolher 1 card "Fera Cristalina" que você controla; coloque o alvo no topo do Deck. \r\nSe este card com a face para cima for destruído em uma Zona de Monstros, em vez de enviá-lo para o Cemitério, você pode colocá-lo com a face para cima na sua Zona de Magias & Armadilhas como uma Magia Contínua.','\r',char(13)),'\n',char(10)),'Colocar na Zona de Magias & Armadilhas quando for destruído','Retornar ao Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21702241,'Servo Vingativo','Quando o controle do monstro equipado mudar, cause dano igual ao ATK original dele ao seu novo controlador.','Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21715135,'Rede de Emergência da Academia Gagaga',replace(replace('Se seu oponente controlar um monstro e você não controlar nenhum: Invoque por Invocação-Especial 1 monstro "Gagaga" do seu Deck. \r\nDurante o turno em que ativar este card, você não pode Invocar outros monstros por Invocação-Especial, exceto Invocações-Xyz. \r\nVocê só pode ativar 1 "Rede de Emergência da Academia Gagaga" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21720439,'Movimento de Artmage -Pedigree-',replace(replace('Se seu oponente controlar mais monstros que você: Invoque por Invocação-Especial 1 monstro "Artmage" do seu Deck em Posição de Defesa, com um nome diferente que o dos cards que você controla. \r\nSe este card for enviado para o Cemitério para ativar o efeito de "Artmage, Academia Acrópole de Artes Arcanas": você pode adicionar 1 Armadilha "Artmage" do seu Cemitério ou banimento à sua mão. \r\nVocê só pode usar cada efeito de "Movimento de Artmage -Pedigree-" uma vez por turno e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional no turno em que ativar qualquer um dos efeitos deste card, exceto Monstros de Fusão.','\r',char(13)),'\n',char(10)),'Invocação Especial','Recuperar uma Armadilha','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21723081,'Hipercanhão XYZ',replace(replace('Você deve controlar "XYZ - Dragão Canhão", ou um Monstro de Fusão que liste "XYZ - Dragão Canhão" como matéria, para ativar o efeito deste card. \r\nO efeito deste card depende de quem é o turno.\r\n● Seu turno: Você pode escolher 1 dos seus monstros União banidos; coloque-o no fundo do seu Deck e, se isso acontecer, compre 1 card.\r\n● Turno do seu oponente: Você pode descartar qualquer número de cards e, depois, escolha o mesmo número de cards que seu oponente controla; destrua esses cards.	\r\nVocê só pode usar este efeito de "Hipercanhão XYZ" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21727231,'Therion "Ceifador" Fum',replace(replace('Você só pode usar cada um dos seguintes efeitos de "Therion "Ceifador" Fum" uma vez por turno.\r\n● Você pode escolher 1 monstro "Therion" ou 1 monstro Aqua no seu Cemitério; Invoque este card por Invocação-Especial da sua mão e, se isso acontecer, equipe esse monstro a este card.\r\n● Durante o turno do seu oponente (Efeito Rápido): você pode escolher 1 card "Therion" na sua Zona de Magias & Armadilhas e 1 card que seu oponente controla; devolva-os para a mão.	\r\nUm monstro "Therion" equipado com este card ganha 700 de ATK e, além disso, ele pode ativar o 2º efeito listado acima como se fosse "Therion "Ceifador" Fum".','\r',char(13)),'\n',char(10)),'','Retornar os 2 cards para a mão (Therion "Ceifador" Fum)','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21744288,'Fazticeira Schmietta',replace(replace('Durante a Fase Principal (Efeito Rápido): você pode oferecer este card como Tributo e, depois, descartar 1 Magia; Invoque por Invocação-Especial 1 monstro "Fazticeira" do seu Deck, exceto "Fazticeira Schmietta". \r\nVocê pode banir este card do seu Cemitério; envie 1 card "Fazticeira" do seu Deck para o Cemitério, exceto "Fazticeira Schmietta". \r\nVocê só pode usar cada efeito de "Fazticeira Schmietta" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Enviar para o Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21767650,'Sirena Abismanda',replace(replace('Você pode banir este card do seu Cemitério e, depois, ative 1 desses efeitos;\r\n● Aumente os Níveis de todos os monstros "Sirena" que você controla atualmente em 1.\r\n● Aumente os Níveis de todos os monstros "Sirena" que você controla atualmente em 2.','\r',char(13)),'\n',char(10)),'Aumentar o Nível','Aumentar todos os Níveis em 1','Aumentar todos os Níveis em 2','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21768554,'Hipnose em Massa',replace(replace('Ative apenas enquanto você controlar um monstro "Alienígena". \r\nEscolha e assuma o controle de até 3 monstros do seu oponente que tiverem um ou mais Marcadores-A neles. \r\nEste card é destruído durante a Fase Final do turno em que ele foi ativado.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21770260,'Máquina de Reprodução de Geleia',replace(replace('Uma vez por turno, durante sua Fase de Apoio: Invoque por Invocação-Especial 1 "Ficha de Limo" (Aqua/ÁGUA/Nível 1/ATK 500/DEF 500) em Posição de Ataque. \r\nVocê não pode Invocar monstros, exceto "Ficha de Limo" (mas pode Baixá-los).','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21770261,'Ficha de Limo','Invocado por Especial com o efeito "Máquina de Reprodução de Geleia" ou um card relacionado.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21770839,'Dragão Fantasmagórico de Olhos Anômalos',replace(replace('Escala de Pêndulo = 0\r\n[ Efeito de Pêndulo ]\r\nVocê pode descartar 1 card; adicione 1 Monstro Pêndulo Dragão com a face para cima do seu Deck Adicional à sua mão. \r\nVocê só pode usar este efeito de "Dragão Fantasmagórico de Olhos Anômalos" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe você tiver 2 cards nas suas Zonas de Pêndulo e um Monstro Pêndulo "Olhos Anômalos" com a face para cima no seu Deck Adicional: você pode Invocar este card por Invocação-Especial da sua mão. \r\nVocê não pode Invocar por Invocação-Pêndulo no turno em que ativar este efeito. \r\nDurante o cálculo de dano, se este card atacar um monstro do oponente: você pode fazer com que esse monstro do oponente perca 1000 de ATK para cada Monstro Pêndulo com a face para cima no seu Deck Adicional, apenas durante o cálculo de dano. \r\nVocê só pode usar cada efeito de "Dragão Fantasmagórico de Olhos Anômalos" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21772453,'Flor Cardian Bordo com Cervo',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro deve ser Invocado por Invocação-Especial (da sua mão) ao oferecer como Tributo 1 monstro "Flor Cardian", exceto "Flor Cardian Bordo com Cervo". \r\nSe este card for Invocado por Invocação-Especial: compre 1 card e, se isso acontecer, mostre-o e, depois, se for um monstro "Flor Cardian", você pode destruir 1 Card de Magia/Armadilha que seu oponente controla. \r\nCaso contrário, envie-o para o Cemitério.','\r',char(13)),'\n',char(10)),'Comprar','Destruir 1 Card de Magia/Armadilha que seu oponente controla?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21785144,'Gragonite, o Dragão Luminoso',replace(replace('Este card ganha 300 de ATK e DEF para cada monstro "Luminoso(a)" com um nome diferente no seu Cemitério. \r\nSe este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente. \r\nDurante cada uma das suas Fases Finais: envie os 3 cards do topo do seu Deck para o Cemitério.','\r',char(13)),'\n',char(10)),'Enviar 3 cards do seu Deck para o Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21790410,'Centopeia Inzektor',replace(replace('Uma vez por turno: você pode equipar 1 monstro "Inzektor" da sua mão ou do Cemitério a este card. \r\nSe um ou mais Cards de Equipamento forem enviados para o seu Cemitério enquanto estiverem equipados a este card (exceto durante a Etapa de Dano): você pode adicionar 1 card "Inzektor" do seu Deck à sua mão. \r\nEnquanto este card estiver equipado a um monstro, o Nível desse monstro aumenta em 3.','\r',char(13)),'\n',char(10)),'Equipar','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21817254,'Mega Esfera de Trovão','Ela rola pelo chão soltando raios de eletricidade para atacar seus inimigos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21830679,'Wivern Clock',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode diminuir o ATK deste card pela metade e, se isso acontecer, Invoque por Invocação-Especial 1 "Ficha de Clock" (Ciberso/VENTO/Nível 1/ATK 0/DEF 0). \r\nVocê só pode usar este efeito de "Wivern Clock" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21830680,'Ficha de Clock','Invocada por Invocação-Especial com o efeito "Wivern Clock".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21831848,'Gagagatração','Bana 3 monstros "Gagaga" do seu Cemitério; compre 2 cards.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21834870,'Punhos do Inigualável Tenyi',replace(replace('Quando um Card de Magia/Armadilha, ou efeito de monstro, for ativado enquanto você controlar um Monstro que não seja de Efeito com a face para cima: negue a ativação. \r\nSe este card Baixado que você controla for destruído por um efeito de card do seu oponente: você pode Invocar por Invocação-Especial 1 Monstro que não seja de Efeito do seu Deck Adicional.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21840375,'Livro de Magia Escondido',replace(replace('Você pode activar este card apenas durante o seu turno. \r\nEscolha 2 Cards de Magia do seu Cemitério e adicione-os ao seu Deck. \r\nEm seguida, embaralhe o seu Deck.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21843307,'Cavaleiro Cópia',replace(replace('Quando um monstro Guerreiro de Nível 4 ou menos for Invocado por Invocação-Normal no seu campo: Invoque este card por Invocação-Especial como um Monstro Normal com o mesmo nome e Nível que o do monstro Invocado por Invocação-Normal (Guerreiro/LUZ/ATK 0/DEF 0).	\r\n(Este card ainda é considerado uma Armadilha.)','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21844576,'Aviário, o HERÓI do Elemento','Um HERÓI do Elemento alado que vaga pelo céu e manipula o vento. O seu ataque característico, o Quebra-penas, derruba vilões com golpe vindo dos céus.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21844577,'Aviário, o HERÓI do Elemento','Um HERÓI do Elemento alado que vaga pelo céu e manipula o vento. O seu ataque característico, o Quebra-penas, derruba vilões com golpe vindo dos céus.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21846145,'Abdução',replace(replace('Escolha 1 monstro com a face para cima que seu oponente controla; bana 1 monstro do seu Deck ou Deck Adicional com o mesmo Tipo, Atributo e Nível/Classe/Valor Link originais e, se isso acontecer, tome o controle do monstro alvo e, se você baniu um monstro com o mesmo nome original, os efeitos desse monstro são negados. \r\nVocê só pode ativar 1 "Abdução" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21848500,'Maliss ＜Q＞ Criptocopas',replace(replace('3 monstros, incluindo um monstro "Maliss"	\r\n(Efeito Rápido): você pode escolher 1 dos seus cards "Maliss" banidos; embaralhe-o no Deck e, se isso acontecer, bana 1 card no campo (enquanto este card apontar para um monstro, este efeito e sua ativação não podem ser negados). \r\nSe este card for banido: você pode pagar 900 PV; Invoque-o por Invocação-Especial e dobre o seu ATK. \r\nVocê só pode usar cada efeito de "Maliss ＜Q＞ Criptocopas" uma vez por turno.','\r',char(13)),'\n',char(10)),'Recuperar e banir','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21858819,'Número XX: Infinito Negro Utópico',replace(replace('2+ monstros de Nível 10	\r\nQuando um monstro for destruído em batalha e enviado para o Cemitério: você pode desassociar 1 matéria deste card e, depois, escolher esse monstro; Invoque-o por Invocação-Especial no seu campo em Posição de Defesa. \r\nVocê pode escolher 1 outro monstro com a face para cima Invocado por Invocação-Especial que você controla; ganhe PV igual ao ATK original dele. \r\nVocê só pode usar cada efeito de "Número XX: Infinito Negro Utópico" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21861412,'Fluxo de Ochsenfeld',replace(replace('1 monstro de TERRA de Nível 5 ou mais + 1 monstro Rocha	\r\nSe este card for Invocado por Invocação-Fusão: você pode Invocar por Invocação-Especial 1 monstro Rocha da sua mão ou do Cemitério, exceto "Fluxo de Ochsenfeld". \r\n(Efeito Rápido): você pode escolher 1 monstro de TERRA que você controla e 1 card que seu oponente controla; devolva-os para a mão. \r\nVocê só pode usar cada efeito de "Fluxo de Ochsenfeld" uma vez por turno e não pode ativar mais que 1 na mesma Corrente.','\r',char(13)),'\n',char(10)),'Invocação Especial','Retornar para a mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21862633,'Perfurando a Escuridão',replace(replace('Se você Invocar por Invocação-Normal ou Especial um ou mais Monstros Normais que não sejam Ficha (exceto durante a Etapa de Dano): você pode comprar 1 card. \r\nQuando um ataque for declarado envolvendo um monstro do oponente e um monstro que você controla que seja um Monstro Normal de Nível 5 ou mais, ou que foi Invocado por Invocação-Ritual usando um Monstro Normal, ou que foi Invocado por Invocação-Fusão, Sincro ou Xyz usando um Monstro Normal como matéria: você pode fazer com que, até o final deste turno, esse monstro que você controla ganhe ATK igual ao ATK desse monstro do oponente. \r\nVocê só pode usar cada efeito de "Perfurando a Escuridão" uma vez por turno.','\r',char(13)),'\n',char(10)),'Compre 1 card(s)','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21879581,'Barreira Sincro',replace(replace('Ofereça como Tributo 1 Monstro Sincro que você controla. \r\nVocê não sofre qualquer dano até a Fase Final do próximo turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21887075,'Motor Interminável Sistema Argyro',replace(replace('Envie 1 card "Therion" do seu Deck para o Cemitério. \r\nSe este card estiver no seu Cemitério: você pode escolher 1 card "Therion" no seu Cemitério; se os dois ainda estiverem no seu Cemitério, adicione esse card ou este card à sua mão e, se isso acontecer, coloque o outro no fundo do seu Deck. \r\nVocê só pode usar 1 efeito de "Motor Interminável Sistema Argyro" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Enviar para o Cemitério','Recuperar do Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21887175,'Mekk-Cavaleiro Crusadia Avramax',replace(replace('2+ monstros Invocados por Invocação-Especial do Deck Adicional	\r\nEnquanto este card Invocado por Invocação-Link estiver no campo, seu oponente não pode escolher este card como alvo de efeitos de card e, além disso, os monstros dele não podem escolher monstros como alvo de ataques, exceto este. \r\nUma vez por batalha, durante o cálculo de dano, se este card batalhar um monstro Invocado por Invocação-Especial (Efeito Rápido): você pode fazer com que este card ganhe ATK igual ao ATK desse monstro do oponente, apenas durante esse cálculo de dano. \r\nSe este card Invocado por Invocação-Link que você controla for enviado para o seu Cemitério por um card do oponente: você pode embaralhar 1 card do campo no Deck.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21887176,'Mekk-Cavaleiro Crusadia Avramax',replace(replace('2+ monstros Invocados por Invocação-Especial do Deck Adicional	\r\nEnquanto este card Invocado por Invocação-Link estiver no campo, seu oponente não pode escolher este card como alvo de efeitos de card e, além disso, os monstros dele não podem escolher monstros como alvo de ataques, exceto este. \r\nUma vez por batalha, durante o cálculo de dano, se este card batalhar um monstro Invocado por Invocação-Especial (Efeito Rápido): você pode fazer com que este card ganhe ATK igual ao ATK desse monstro do oponente, apenas durante esse cálculo de dano. \r\nSe este card Invocado por Invocação-Link que você controla for enviado para o seu Cemitério por um card do oponente: você pode embaralhar 1 card do campo no Deck.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21887179,'Getsu Fuhma','Se este card batalhar um monstro Demônio ou Zumbi, destrua esse monstro no final da Etapa de Dano.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21888494,'O Escolhido',replace(replace('Selecione 1 Card de Monstro e 2 Cards que não sejam de Monstros da sua mão. \r\nSeu oponente seleciona aleatoriamente 1 card entre eles. \r\nSe for um Card de Monstro, ele é Invocado por Invocação-Especial e envia os 2 cards restantes ao Cemitério. \r\nCaso contrário, envie todos os cards ao Cemitério.','\r',char(13)),'\n',char(10)),'Escolha 1 Card de Monstro','Escolha 2 cards que não sejam Monstro','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21893603,'Lee, a Fada do Cálice Mundial',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 monstro "Cálice Mundial" do seu Deck à sua mão. \r\nSe este card estiver no seu Cemitério: você pode enviar 1 monstro da sua mão ou do campo para o Cemitério; adicione este card à sua mão. \r\nVocê só pode usar cada efeito de "Lee, a Fada do Cálice Mundial" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21900719,'Espadas Gémes da Luz que Pisca - Tryce',replace(replace('Envie 1 card da sua mão para o Cemitério para activar este card. \r\nUm monstro equipado com este card diminui o seu ATK em 500 pontos. \r\nUm monstro equipado com este card pode atacar duas vezes durante a mesma Battle Phase.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21903613,'Dançapione Silvestre',replace(replace('2 monstros Planta	\r\nSe este card for Invocado por Invocação-Link: você pode selecionar um número entre 1 e 3 e escavar esse número de cards do topo do seu Deck e, se isso acontecer, você pode Invocar por Invocação-Especial até 2 monstros Planta escavados, mas eles não podem ser usados como Matéria Link e, além disso, envie os cards restantes para o Cemitério. \r\nVocê pode escolher 1 monstro Planta no seu Cemitério que tenha um Nível; até o final deste turno, os Níveis dos monstros para os quais este card apontar se tornam o Nível desse monstro. \r\nVocê só pode usar cada efeito de "Dançapione Silvestre" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Escolha a quantidade de cards a revelar','Invocar por Invocação Especial um monstro Planta?','','','','','','','','','','','','');
INSERT INTO texts VALUES(21908319,'Botão de Auto-destruição de Kozaky','Inflija 1000 pontos de dano aos Life Points do jogador que destruiu este card Baixado.','Receba 1000 pontos de dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21915012,'Arremesso do Cupido',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro: aumente ou diminua o Nível deste card pelo Nível que o Regulador usado como matéria tinha no campo. \r\nEste card ganha ATK igual ao seu Nível x 400. \r\nSe este card Invocado por Invocação-Sincro for enviado para o Cemitério como Matéria Sincro: cause dano ao seu oponente igual ao novo Nível do monstro Invocado por Invocação-Sincro x 100 e, se isso acontecer, você pode adicionar 1 monstro de Nível 8 ou menos com 600 de DEF do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Arremesso do Cupido" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Aumentar o Nível','Reduzir o Nível','Adicionar 1 monstro do seu Deck à sua mão?','','','','','','','','','','','','');
INSERT INTO texts VALUES(21924381,'Avanço Heroico','Quando um monstro "Heroico(a)" que você controla for escolhido como alvo de um ataque: escolha outro monstro "Heroico(a)" de Nível 4 ou menos que você controla; dobre o seu ATK (até o final da Fase de Batalha) e, depois, mude o alvo do ataque para ele e realize o cálculo de dano, mas os monstros não podem ser destruídos por esta batalha.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21947653,'HERÓI Maligno Golem Relâmpago',replace(replace('"Sparkman, o HERÓI do Elemento" + "Clayman, o HERÓI do Elemento"	\r\nDeve ser Invocado por Invocação-Especial com "Fusão Negra". \r\nUma vez por turno: você pode escolher 1 monstro no campo; destrua o alvo.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21949879,'Gentrude Camarartista',replace(replace('Escala de Pêndulo = 8\r\n[ Efeito de Pêndulo ]\r\nSe "Damange Camarartista" estiver na sua outra Zona de Pêndulo e você não controlar nenhum monstro ou apenas Monstros Pêndulo: você pode adicionar 1 card "Olhos Anômalos" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Gentrude Camarartista" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe este card for destruído: você pode colocar 1 Monstro Pêndulo "Camarartista" do seu Deck na sua Zona de Pêndulo, exceto "Gentrude Camarartista". \r\nSe este card estiver com a face para cima no seu Deck Adicional: você pode descartar 1 Monstro Pêndulo; adicione este card à sua mão e, depois, você pode devolver 1 card "Camarartista" ou "Olhos Anômalos" da sua Zona de Pêndulo para a mão. \r\nVocê só pode usar 1 efeito de "Gentrude Camarartista" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','Retornar para a mão 1 card na sua Zona de Pêndulo?','','','','','','','','','','','','');
INSERT INTO texts VALUES(21954587,'Sirena Abismegalo',replace(replace('Você pode descartar 2 outros monstros de ÁGUA para o Cemitério; Invoque este card por Invocação-Especial da sua mão. \r\nQuando Invocado desta forma: você pode adicionar 1 Magia/Armadilha "Abis-" do seu Deck à sua mão. \r\nVocê pode oferecer como Tributo 1 outro monstro de ÁGUA em Posição de Ataque; este card pode realizar um segundo ataque durante cada Fase de Batalha neste turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Adicionar à mão','Atacar duas vezes','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21960890,'Necromante Negro',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode enviar 1 Monstro de Ritual Demônio ou Zumbi da sua mão ou do Deck para o Cemitério e, depois, você pode adicionar 1 Magia de Ritual do seu Deck à sua mão. \r\nSe este card for banido: você pode escolher 1 dos seus monstros Demônio ou Zumbi banidos de Nível 4 ou menos; Invoque-o por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Necromante Negro" uma vez por turno.','\r',char(13)),'\n',char(10)),'Enviar para o Cemitério','Invocação Especial','Adicionar à mão?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21970285,'Caçador de Chifre de Dragão',replace(replace('Escala de Pêndulo = 3\r\n[ Efeito de Pêndulo ]\r\nTodos os Monstros Normais ganham 200 de ATK. Você não sofre dano das batalhas que envolvem Monstros Normais que você controla.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nOs chifres eram necessários para preparar um remédio para a vila, que sofria com uma praga. Mas ela não sabia que os dragões queimariam e destruiriam a vila depois de retirados do seu lar.','\r',char(13)),'\n',char(10)),'Alterar ATK/DEF','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21977828,'Giga-Weevil Inzektor',replace(replace('Você pode escolher 1 monstro "Inzektor" com a face para cima que você controla; equipe este card da sua mão ao alvo. \r\nEnquanto este card estiver equipado a um monstro, a DEF original desse monstro se torna 2600. \r\nSe este card for enviado para o Cemitério enquanto estiver equipado a um monstro: você pode escolher 1 monstro "Inzektor" no seu Cemitério; Invoque o alvo por Invocação-Especial. \r\nEste efeito de "Giga-Weevil Inzektor" só pode ser usado uma vez por turno.','\r',char(13)),'\n',char(10)),'Equipar','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21984400,'Ataque da Besta Mágica',replace(replace('Remova Marcadores de Magia do seu campo para ativar 1 desses efeitos.\r\n● 2: Devolva para a mão 1 Monstro Pêndulo "Besta Mítica" que você controla.\r\n● 4: Invoque por Invocação-Especial do seu Deck Adicional 1 Monstro Pêndulo "Besta Mítica" com a face para cima e, depois, você pode colocar 2 Marcadores de Magia sobre ele.\r\n● 6: Invoque por Invocação-Especial do seu Deck Adicional 1 Monstro Pêndulo com a face para cima.	\r\nVocê só pode ativar 1 "Ataque da Besta Mágica" por turno.','\r',char(13)),'\n',char(10)),'Remover 2','Remover 4','Remover 6','Colocar um Marcador de Magia?','','','','','','','','','','','','');
INSERT INTO texts VALUES(21985407,'Chegada de Cavalestrela',replace(replace('Durante a Fase Principal: você pode ativar 1 desses efeitos;\r\n● Escolha 1 monstro Dragão de LUZ de Nível 7 que você controla; devolva-o para a mão.\r\n● Invoque por Invocação-Especial 1 monstro Dragão de LUZ de Nível 7 da sua mão.	\r\nVocê só pode usar este efeito de "Chegada de Cavalestrela" uma vez por turno.','\r',char(13)),'\n',char(10)),'Retornar para a mão','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21999001,'Ave de Rapina Gêmea Críptica',replace(replace('Se seu oponente controlar um monstro com a face para cima que foi Invocado por Invocação-Especial do Deck Adicional e você não controlar nenhum monstro, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê pode descartar 1 card; Invoque por Invocação-Especial 1 monstro "Críptico(a)" da sua mão ou do Deck e, além disso, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros "Críptico(a)". \r\nVocê só pode usar este efeito de "Ave de Rapina Gêmea Críptica" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22007085,'Fogueira de Cavalestrela',replace(replace('Adicione 1 monstro "Cavalestrela" ou 1 monstro Dragão de LUZ de Nível 7 do seu Deck à sua mão e, depois, se você não controlar nenhum monstro e seu oponente controlar um monstro de TREVAS, você pode Invocar por Invocação-Especial 1 monstro Dragão de LUZ de Nível 7 da sua mão. \r\nVocê só pode ativar 1 "Fogueira de Cavalestrela" por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22009013,'Mariposa Hordeum Ferro','Quando este card for Invocado por Invocação-Tributo ao oferecer como Tributo um monstro "Hordeum Ferro": Você pode pagar 1000 PV para escolher até 2 cards que seu oponente controla; devolva esses alvos para a mão.','Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22011689,'Predaplanta Moray Nepenthes',replace(replace('Este card ganha 200 de ATK para cada Marcador de Predador no campo. \r\nQuando este card destruir um monstro do oponente em batalha: você pode equipar esse monstro a este card. \r\nUma vez por turno: você pode escolher 1 Card de Monstro equipado a este card pelo efeito deste card; destrua-o e, se isso acontecer, ganhe PV igual ao ATK original dele.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22020907,'Sinal do Herói','Quando um monstro que você controla for destruído em batalha e enviado para o Cemitério: Invoque por Invocação-Especial 1 monstro "HERÓI do Elemento" de Nível 4 ou menos da sua mão ou do Deck.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22024279,'Revitalização Altergeist',replace(replace('Escolha 1 Monstro Link "Altergeist" no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê pode banir este card do seu Cemitério; imediatamente depois que este efeito resolver, Invoque por Invocação-Normal 1 monstro "Altergeist". \r\nVocê só pode usar 1 efeito de "Revitalização Altergeist" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22026707,'Cortina dos Obscuros','Erguida por um mago, dizem que essa cortina aprimora o poder das trevas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22046459,'Megamorph',replace(replace('Enquanto você tiver menos PV que seu oponente, o ATK do monstro equipado se torna o dobro do seu ATK original. \r\nEnquanto você tiver mais PV que seu oponente, o ATK do monstro equipado se torna metade do seu ATK original.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22047978,'Pausa na Batalha','Quando um monstro do oponente declarar um ataque: Seu oponente pode revelar 1 monstro na mão dele para negar o efeito deste card, caso contrário, destrua o monstro atacante e, depois, encerre a Fase de Batalha.','Revelar 1 monstro da sua mão para o seu oponente?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22056710,'Vampiro Gênesis',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao banir 1 "Senhor dos Vampiros" que você controla. \r\nUma vez por turno: você pode descartar 1 monstro Zumbi para o Cemitério e, depois, escolha 1 monstro Zumbi no seu Cemitério com um Nível menor que o do monstro Zumbi descartado; Invoque o alvo por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22061412,'O Iluminado, o HERÓI do Elemento',replace(replace('1 monstro "HERÓI do Elemento" + 1 monstro de LUZ	\r\nDeve ser Invocado por Invocação-Fusão e não pode ser Invocado por Invocação-Especial de nenhuma outra forma. \r\nEste card ganha 300 de ATK para cada um dos seus monstros "HERÓI do Elemento" banidos. \r\nQuando este card for enviado do campo ao Cemitério: Você pode escolher até 2 dos seus monstros "HERÓI do Elemento" banidos; adicione os alvos à sua mão.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22070401,'Dragão Dose Letal do Venimigo Faminto',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno, durante sua Fase Principal: você pode colocar 1 Marcador de Venimigo sobre cada monstro com a face para cima que seu oponente controla. \r\nTodos os monstros no campo, exceto monstros Dragão de TREVAS, perdem 200 de ATK para cada Marcador de Venimigo no campo.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\n3 Monstros Pêndulo de TREVAS	\r\nSempre que um ou mais cards forem enviados do campo para o Cemitério, coloque 1 Marcador de Venimigo neste card para cada card enviado. \r\nTodos os monstros no campo, exceto monstros Dragão de TREVAS, perdem 200 de ATK para cada Marcador de Venimigo no campo. \r\nUma vez por turno, durante sua Fase Principal: até o final deste turno, você pode negar os efeitos de todos os monstros com a face para cima que seu oponente controla atualmente. \r\nSe este card na Zona de Monstros for destruído em batalha ou por um efeito de card: você pode colocar este card na sua Zona de Pêndulo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22073844,'Dogmatika Nexus',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial por seu próprio efeito. \r\nVocê pode escolher 4 Monstros de Fusão, Sincro, Xyz e/ou Link nos Cemitérios; Invoque este card por Invocação-Especial da sua mão e, se isso acontecer, bana-os. \r\nNo começo da Etapa de Dano, se este card batalhar um monstro Invocado por Invocação-Especial: destrua todos os monstros em Posição de Ataque do seu oponente e, depois, cause 800 de dano ao seu oponente para cada Monstro de Fusão, Sincro, Xyz e Link destruído por este efeito.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22076135,'Sirena Abisturjão',replace(replace('Quando este card for Invocado por Invocação-Normal ou Especial: você pode descartar 1 monstro de ÁGUA para o Cemitério e, depois, escolha 1 monstro de ÁGUA de Nível 3 ou menos no seu Cemitério; adicione o alvo à sua mão. \r\nVocê só pode usar este efeito de "Sirena Abisturjão" uma vez por turno.','\r',char(13)),'\n',char(10)),'Recuperar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22082163,'Força de Vontade Amazoness',replace(replace('Ative este card ao escolher 1 monstro "Amazoness" no seu Cemitério; Invoque-o por Invocação-Especial em Posição de Ataque, mas ele não pode mudar sua posição de batalha e deve atacar, se possível. \r\nQuando este card deixar o campo, destrua esse monstro. \r\nQuando esse monstro for destruído, destrua este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22082432,'Perigos do Divino',replace(replace('Pague metade dos seus PV e, depois, ofereça 1 monstro como Tributo; Invoque por Invocação-Especial 1 "O Dragão Alado de Rá" da sua mão ou do banimento, ignorando suas condições de Invocação, e torne seu ATK/DEF 4000, mas ele não pode atacar e, além disso, durante a Fase Final do próximo turno, devolva-o para a mão. \r\nSe este card for enviado do campo para o Cemitério: selecione 1 "O Dragão Alado de Rá" na sua Zona de Monstros e envie todos os outros monstros no campo para o Cemitério. \r\nVocê só pode usar cada efeito de "Perigos do Divino" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22091345,'Camarartista Ponta-de-Águia','Uma vez por turno: você pode escolher 1 monstro com a face para cima que você controla; se ele atacar um monstro em Posição de Defesa neste turno, cause dano de batalha perfurante ao seu oponente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22091647,'Gearfried Fênix Imortal',replace(replace('Você pode banir 1 Magia de Equipamento do seu campo ou do Cemitério; Invoque este card por Invocação-Especial da sua mão. \r\nNo começo da Etapa de Dano, se este card atacar: você pode equipar 1 monstro com a face para cima no campo a este card (máx. 1) como uma Magia de Equipamento que concede 500 de ATK a este card. \r\nQuando um efeito de monstro for ativado (Efeito Rápido): você pode enviar 1 Card de Equipamento com a face para cima que você controla para o Cemitério; negue a ativação e, se isso acontecer, destrua-o. \r\nVocê só pode usar cada efeito de "Gearfried Fênix Imortal" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22093873,'Vento Divino, o HERÓI Mascarado',replace(replace('Deve ser Invocado por Invocação-Especial com "Mudar a Máscara" e não pode ser Invocado por Invocação-Especial de nenhuma outra forma. 	\r\nNão pode ser destruído em batalha. \r\nSeu oponente só pode atacar com 1 monstro durante cada Fase de Batalha. \r\nQuando este card destruir um monstro do oponente em batalha e enviá-lo para o Cemitério: você pode comprar 1 card.','\r',char(13)),'\n',char(10)),'Compre 1 card(s)','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22106558,'Mecânico Mecânico',replace(replace('Quando um ataque for declarado envolvendo outro monstro Máquina seu: você pode aumentar ou diminuir o Nível desse outro monstro que você controla em 1. \r\nVocê só pode usar cada um dos seguintes efeitos de "Mecânico Mecânico" uma vez por turno. \r\nSe um card estiver na Zona do Campo: você pode Invocar este card por Invocação-Especial da sua mão. \r\nVocê pode escolher 1 Magia/Armadilha com a face para cima que você controla; destrua-a e, se isso acontecer, adicione 1 monstro Máquina de VENTO com 0 de ATK do seu Deck à sua mão e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto monstros Máquina.','\r',char(13)),'\n',char(10)),'Alterar o Nível','Invocação Especial','Destruir e buscar','Aumentar o Nível','Reduzir o Nível','','','','','','','','','','','');
INSERT INTO texts VALUES(22110647,'Besta Fantasma Mecha Dracossack',replace(replace('2 monstros de Nível 7	\r\nUma vez por turno: você pode desassociar 1 matéria deste card; Invoque por Invocação-Especial 2 "Ficha de Besta Fantasma Mecha" (Máquina/VENTO/Nível 3/ATK 0/DEF 0). \r\nEnquanto você controlar uma Ficha, este card não pode ser destruído em batalha ou por efeitos de card. \r\nUma vez por turno: você pode oferecer como Tributo 1 monstro "Besta Fantasma Mecha" e, depois, escolha 1 card no campo; destrua o alvo. \r\nEste card não pode atacar durante o turno em que você ativar este efeito.','\r',char(13)),'\n',char(10)),'Invoque por Invocação Especial 2 "Ficha de Besta Fantasma Mecha" no seu Campo','Escolha 1 card no Campo para destruí-la','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22110648,'Ficha de Besta Fantasma Mecha','Invocado por Especial com o efeito de um monstro "Besta Fantasma Mecha" ou um card relacionado.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22123627,'Moreia da Ganância','Embaralhe 2 monstros de ÁGUA da sua mão no Deck e, depois, compre 3 cards.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22125101,'Além do Pêndulo',replace(replace('2 Monstros de Efeito, incluindo um Monstro Pêndulo	\r\nSe este card for Invocado por Invocação-Link na Zona de Monstros Adicional: você pode pagar 1200 PV; adicione 1 Monstro Pêndulo do seu Deck à sua mão, mas pelo resto deste turno, a não ser que você Invoque por Invocação-Pêndulo depois que este efeito resolver, você não pode ativar efeitos de monstro, e os efeitos de quaisquer cards nas suas Zonas de Pêndulo são negados. \r\nSe 2 monstros com Níveis originais diferentes forem Invocados por Invocação-Pêndulo ao mesmo tempo em zonas para as quais este card apontar: você pode escolher 2 cards no campo; destrua-os. \r\nVocê só pode usar este efeito de "Além do Pêndulo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22134079,'Emboscador do Coveiro',replace(replace('Quando este card for virado com a face para cima: você pode escolher 1 card no Cemitério do seu oponente; coloque o alvo no fundo do Deck dele. \r\nSe este card for enviado do campo para o Cemitério depois de ser virado com a face para cima: você pode escolher 1 card "Necro-Vale" no seu Cemitério; adicione o alvo à sua mão. \r\nEstes efeitos não são afetados por "Necro-Vale".','\r',char(13)),'\n',char(10)),'Retornar ao Deck','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22138839,'Predaplanta Banksiogro',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) ao oferecer como Tributo 1 monstro do oponente com um Marcador de Predador. \r\nSe este card for enviado do campo para o Cemitério: coloque 1 Marcador de Predador sobre cada monstro com a face para cima que seu oponente controla e, se isso acontecer, quaisquer desses monstros que sejam de Nível 2 ou mais se tornam de Nível 1 enquanto estiverem com um Marcador de Predador.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22147147,'Lâmina Ciclone',replace(replace('Equipe apenas em um monstro "HERÓI do Destino". \r\nNo final da Etapa de Dano, se o monstro equipado tiver atacado: Escolha 1 Card de Magia/Armadilha no campo; destrua esse alvo.','\r',char(13)),'\n',char(10)),'Destruir Magias/Armadilhas','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22159429,'Grinalda Mágica Trapestrela',replace(replace('Ative este card ao escolher 1 monstro "Trapestrela" no seu Cemitério; Invoque-o por Invocação-Especial e equipe-o com este card. \r\nQuando este card deixar o campo, destrua esse monstro. \r\nUma vez por turno, se o monstro equipado causar dano de batalha ou de efeito ao seu oponente: você pode Invocar por Invocação-Especial 1 monstro "Trapestrela" da sua mão. \r\nVocê só pode ativar 1 "Grinalda Mágica Trapestrela" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22160245,'HERÓI Maligno Asa do Inferno',replace(replace('"Aviário, o HERÓI do Elemento" + "Burstinatrix, o HERÓI do Elemento"	\r\nDeve ser Invocado por Invocação-Especial com "Fusão Negra". \r\nSe este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante. \r\nSe este card destruir um monstro em batalha e enviá-lo para o Cemitério: cause dano ao seu oponente igual ao ATK ou DEF original (o que for maior) desse monstro no Cemitério.','\r',char(13)),'\n',char(10)),'Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22171591,'Doutor Cranium','Quando este card for destruído em batalha e enviado para o Cemitério, você pode pagar 800 PV para adicionar 1 monstro do Tipo Psíquico do seu Deck à sua mão.','Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22174866,'Aromágico Cananga',replace(replace('Enquanto seus PV estiverem maiores que os do seu oponente, monstros com a face para cima que seu oponente controla perdem 500 de ATK e DEF. \r\nUma vez por turno, se você ganhar PV: escolha 1 Card de Magia/Armadilha que seu oponente controla; devolva-o para a mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22180094,'Força-S Rappa Chiyomaru',replace(replace('Cada um dos monstros do seu oponente na mesma coluna que um dos seus monstros "Força-S" só pode escolher esse monstro como alvo de ataques. \r\n(Efeito Rápido): você pode banir 1 card "Força-S" da sua mão; devolva este card para a mão e, se isso acontecer, Invoque por Invocação-Especial 1 monstro "Força-S" do seu Deck em Posição de Defesa, exceto "Força-S Rappa Chiyomaru". \r\nVocê só pode usar este efeito de "Força-S Rappa Chiyomaru" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22198672,'Castelo Link',replace(replace('Uma vez por turno: você pode escolher 1 Monstro Link no campo; mova-o para uma Zona de Monstros Principal para a qual ele apontar no campo do seu controlador. \r\nUma vez por turno: você pode trocar as posições de 2 Monstros Link nas suas Zonas de Monstros Principais ou de 2 Monstros Link nas Zonas de Monstros Principais do seu oponente.','\r',char(13)),'\n',char(10)),'Mover para outra Zona','Trocar posições','Escolha 1 monstro para mover','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22200403,'Hipnotirmãzar',replace(replace('Este card ganha efeitos de acordo com o número total de cards nas Zonas de Pêndulo dos dois duelistas.\r\n● 1 ou mais: Este card ganha 800 de ATK e DEF.\r\n● 2 ou mais: No começo da Etapa de Dano, se este card batalhar um monstro Invocado por Invocação-Pêndulo: destrua esse monstro.\r\n● 3 ou mais: Os monstros que o seu oponente controla devem atacar este card, se possível.\r\n● 4: Se este card destruir um monstro em batalha ou por um efeito dele mesmo: compre 1 card.','\r',char(13)),'\n',char(10)),'Destruir','Comprar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22201234,'Barreira Luminosa','Quando um monstro "Luminoso(a)" que você controla for escolhido como alvo de um ataque: você pode enviar os 2 cards do topo do seu Deck para o Cemitério e, depois, escolher o monstro atacante; negue o ataque.','Usar o efeito?','Negue o ataque de um monstro do seu oponente','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22205600,'Redemoinho de Correntes',replace(replace('Só pode ser ativado quando um card no campo for destruído por um efeito de card. \r\nSelecione 2 Cards de Magia/Armadilha no campo e destrua-os.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22211622,'Rei Supremo Portal Infinito',replace(replace('Escala de Pêndulo = 13\r\n[ Efeito de Pêndulo ]\r\nSe você controlar um monstro, você não pode Invocar por Invocação-Pêndulo. \r\nEste efeito não pode ser negado. \r\nUma vez por turno, se você controlar "Rei Supremo Z-ARC": você pode escolher 1 monstro com a face para cima que seu oponente controla; ganhe PV igual ao ATK dele.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nUma vez por turno: você pode escolher 1 outro card com a face para cima que você controla; destrua tanto ele quanto este card e, se isso acontecer, Invoque por Invocação-Especial 1 Monstro Pêndulo ou Xyz Dragão do seu Deck Adicional, mas seu ATK/DEF se tornam 0, seus efeitos são negados e, além disso, ele não pode ser usado como matéria para uma Invocação-Sincro ou Xyz. \r\nSe este card na Zona de Monstros for destruído em batalha ou por um efeito de card: você pode colocar este card na sua Zona de Pêndulo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22219822,'Trapestrela Mandrágora',replace(replace('Se este card for enviado da mão para o Cemitério: você pode Invocar este card por Invocação-Especial em Posição de Defesa, mas bana-o quando ele deixar o campo. \r\nSe este card for enviado para o Cemitério como Matéria Link para a Invocação-Link de um monstro "Trapestrela": você pode escolher 1 monstro para o qual um Monstro Link do oponente apontar; destrua-o. \r\nVocê só pode usar cada efeito de "Trapestrela Mandrágora" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Destruir um monstro','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22227683,'Robô-secretário 004',replace(replace('Se este card batalhar um monstro do oponente, durante o cálculo de dano (no turno de qualquer duelista): você pode ativar este efeito uma vez por batalha; seu oponente não sofre dano de batalha pelo resto deste turno e, além disso, envie 1 monstro "Robô-secretário" do seu Deck para o Cemitério, exceto "Robô-secretário 004" e, se isso acontecer, apenas durante o cálculo de dano, este card ganha ATK e DEF igual ao Nível do monstro enviado x 500. \r\nSe este card destruir um monstro do oponente em batalha: você pode Invocar por Invocação-Especial 2 monstros "Robô-secretário" de Níveis diferentes da sua mão e/ou Cemitério em Posição de Defesa.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22283204,'O Olhar de Timaeus',replace(replace('Escolha 1 "Mago Negro" ou "Pequena Maga Negra" no seu campo ou Cemitério; Invoque por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional que mencione esse monstro como matéria, ao embaralhá-lo no Deck como matéria (isso é considerado uma Invocação-Fusão com "O Olho de Timaeus"), mas bana-o durante a Fase Final do próximo turno. \r\nVocê só pode ativar 1 "O Olhar de Timaeus" por turno.','\r',char(13)),'\n',char(10)),'Ativar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22318971,'Familiar Monocórneo',replace(replace('Quando este card com a face para cima em Posição de Defesa for selecionado como alvo de um ataque, você pode remover de jogo 1 monstro que você controla diferente deste card para remover este card de jogo. \r\nO monstro atacante deve atacar. \r\nDurante sua próxima Fase de Apoio, se este card foi removido de jogo por este efeito, este card é devolvido para o campo.','\r',char(13)),'\n',char(10)),'Banir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22339232,'Pesadelo Inumano',replace(replace('O nome deste card se torna "Servo Caveira" enquanto estiver no Cemitério. \r\nVocê pode descartar este card e, depois, ative 1 dos seguintes efeitos.\r\n● Escolha 1 dos seus "Servo Caveira" ou "Pesadelo Inumano" banidos; devolva-o para o Cemitério.\r\n● Escolha 1 dos seus "A Dama Inumana" ou "Rei dos Servos Caveira" banidos; Invoque-o por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Retornar "Servo Caveira" ou "Pesadelo Inumano" para o Cemitério','Invocar por Invocação Especial "A Dama Inumana" ou "Rei dos Servos Caveira"','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22346472,'Ventos Turbulentos','Escolha 1 monstro com a face para cima que você controla; ele ganha 1000 de ATK e DEF até sua próxima Fase de Apoio.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22359980,'Parede Espelhada',replace(replace('Diminua pela metade o ATK dos monstros atacantes do seu oponente. \r\nUma vez por turno, durante sua Fase de Apoio, pague 2000 PV ou destrua este card.','\r',char(13)),'\n',char(10)),'Pagar 2000 PV para manter "Parede Espelhada"?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22371016,'Esmagador Desconhecido, Aliado da Justiça','Quando este card batalhar com um monstro de LUZ, remova esse monstro de jogo depois do cálculo de dano.','Banir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22373487,'Saiam!',replace(replace('Escolha 2 monstros que seu oponente controla que foram Invocados por Invocação-Especial do Deck Adicional; embaralhe-os no Deck. \r\nVocê só pode ativar 1 "Saiam!" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22377092,'Mania de Armadilha',replace(replace('Escolha 1 Magia/Armadilha que você controla; destrua-a e, se isso acontecer, Baixe 1 Armadilha Normal do seu Deck, exceto "Mania de Armadilha". \r\nEla pode ser ativada neste turno, enquanto você tiver 3 ou mais Armadilhas no seu Cemitério. \r\nVocê só pode ativar 1 "Mania de Armadilha" por turno.','\r',char(13)),'\n',char(10)),'Ativar','Ativar aplicando o efeito de "Mania de Armadilha".','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22377815,'Allesa Aquática',replace(replace('Este card é considerado como um Monstro Normal enquanto estiver com a face para cima no campo ou no Cemitério. \r\nEnquanto este card estiver com a face para cima no campo, você pode Invocá-lo por Invocação-Normal para fazer com que ele seja considerado como um Monstro de Efeito com este efeito:\r\n● Quando este card destruir um monstro do oponente em batalha e enviá-lo para o Cemitério, ele descarta 1 card aleatório.','\r',char(13)),'\n',char(10)),'Descartar da mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22382087,'Garum, o Vassalo da Tempestade',replace(replace('Você pode devolver para a mão 1 monstro que você controla Invocado por Invocação-Tributo; Invoque este card por Invocação-Especial da sua mão e, além disso, você não pode Invocar por Invocação-Especial monstros do Deck Adicional pelo resto deste turno. \r\nSe este card for oferecido como Tributo para uma Invocação-Tributo: você pode adicionar 1 monstro com 800 de ATK e 1000 de DEF do seu Deck à sua mão, exceto "Garum, o Vassalo da Tempestade". \r\nVocê só pode usar cada efeito de "Garum, o Vassalo da Tempestade" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22386234,'Paragão da Aurora',replace(replace('Nenhum duelista pode Invocar monstros por Invocação-Especial. \r\nQuando outro monstro for Invocado por Invocação-Normal no lado do campo de qualquer duelista, destrua este card.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22390469,'Orgulho Dourado - Estrela Leon',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nDurante a Fase Principal (Efeito Rápido): você pode escolher 1 monstro com a face para cima que seu oponente controla; este card ganha ATK igual ao ATK original do alvo e, depois, se você tiver menos PV que seu oponente, você pode destruir esse monstro. \r\nVocê só pode usar o efeito anterior de "Orgulho Dourado - Estrela Leon" uma vez por turno. \r\nUma vez por turno, durante a Fase Final, se o efeito anterior foi ativado neste turno: devolva este card para o Deck Adicional e, se isso acontecer, Invoque por Invocação-Especial 1 "Orgulho Dourado - Leon" do seu Deck ou Cemitério.','\r',char(13)),'\n',char(10)),'','','Destruir aquele monstro?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22398665,'Drytron Meteonis',replace(replace('Este card pode ser usado para Invocar por Invocação-Ritual qualquer Monstro de Ritual da sua mão ou do Cemitério. \r\nVocê também deve oferecer como Tributo monstros Máquina da sua mão ou do campo cujo ATK total seja igual ou exceda o ATK do Monstro de Ritual que você Invocou por Invocação-Ritual. \r\nSe este card estiver no seu Cemitério: você pode escolher 1 monstro "Drytron" que você controla; ele perde exatamente 1000 de ATK até o final do turno do seu oponente e, se isso acontecer, adicione este card à sua mão. \r\nVocê só pode usar este efeito de "Drytron Meteonis" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22404570,'Sombra do Patrono do Poder da Hora Final',replace(replace('Invoque por Invocação-Especial 1 monstro "Patrono(a) do Poder" da sua mão, do Deck Adicional com a face para cima ou do Cemitério e, depois, você pode aplicar esses efeitos em sequência, de acordo com o número de tipos de card diferentes (Fusão, Sincro ou Xyz) que você controla.\r\n● 1+: Bana (com a face para baixo) 3 cards do topo do Deck do seu oponente.\r\n● 2+: Bana (com a face para baixo) 1 card que seu oponente controla.\r\n● 3: Bana (com a face para baixo) 1 card aleatório da mão do seu oponente.	\r\nVocê só pode ativar 1 "Sombra do Patrono do Poder da Hora Final" por turno.','\r',char(13)),'\n',char(10)),'Ativar','Banir cards do Deck?','Banir um card no campo?','Banir 1 card da sua mão?','','','','','','','','','','','','');
INSERT INTO texts VALUES(22404675,'Mithra, o Vassalo do Trovão',replace(replace('Se este card estiver na sua mão: você pode ativar este efeito; você não pode Invocar por Invocação-Especial monstros do Deck Adicional pelo resto deste turno e, além disso, Invoque este card por Invocação-Especial e, se isso acontecer, Invoque por Invocação-Especial 1 "Ficha Vassalo" (Tipo Trovão/LUZ/Nível 1/ATK 800/DEF 1000) no campo do seu oponente em Posição de Defesa. \r\nSe este card for oferecido como Tributo para uma Invocação-Tributo: você pode ativar este efeito; você pode Invocar 1 monstro por Invocação-Tributo durante sua Fase Principal deste turno, em adição à sua Invocação-Normal/Baixar (padrão). \r\n(Você só pode se aproveitar deste efeito uma vez por turno.) \r\nVocê só pode usar cada efeito de "Mithra, o Vassalo do Trovão" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar pelo efeito de "Mithra, o Vassalo do Trovão"','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22404676,'Ficha Vassalo','Invocado por Especial com o efeito "Mithra, o Vassalo do Trovão".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22411609,'Soldado Vulcânico',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 card "Vulcânico(a)" do seu Deck à sua mão, exceto "Soldado Vulcânico". \r\nVocê pode descartar 1 card; Invoque por Invocação-Especial 1 "Ficha de Bomba" (Piro/FOGO/Nível 1/ATK 1000/DEF 1000) no campo do seu oponente. \r\nSempre que 1 for destruído, seu controlador sofre 500 de dano. \r\nVocê só pode usar cada efeito de "Soldado Vulcânico" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22411610,'Ficha de Bomba','Invocado por Especial com o efeito "Soldado Vulcânico" ou um card relacionado. Quando destruída, o controlador sofre 500 de dano.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22414174,'Credo Sincro',replace(replace('Se um Monstro Sincro estiver no campo: compre 1 card e, depois, se 3 ou mais Monstros Sincro estiverem no campo, você pode comprar mais 1 card. \r\nVocê só pode ativar 1 "Credo Sincro" por turno.','\r',char(13)),'\n',char(10)),'Comprar 1 card a mais?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22419772,'Guardião Fada','Ofereça este card com a face para cima como Tributo para devolver ao fundo do seu Deck 1 Card de Magia enviado ao seu Cemitério pelo oponente durante este turno.','Retornar ao Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22420202,'Drytron Delta Altais',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial com o efeito de um card "Drytron". \r\nVocê pode oferecer como Tributo 1 outro monstro "Drytron" ou 1 Monstro de Ritual, da sua mão ou do campo; Invoque este card por Invocação-Especial da sua mão ou do Cemitério em Posição de Defesa e, depois, você pode revelar 1 Monstro de Ritual ou 1 Magia de Ritual na sua mão e, se isso acontecer, compre 1 card. \r\nVocê não pode Invocar monstros por Invocação-Especial no turno em que ativar este efeito, exceto monstros que não podem ser Invocados por Invocação-Normal/Baixados. \r\nVocê só pode usar este efeito de "Drytron Delta Altais" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Comprar 1 card?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22423493,'Gênio Qliphort',replace(replace('2 monstros Máquina	\r\nEste card Invocado por Invocação-Link não é afetado por efeitos de Magia/Armadilha e pelos efeitos ativados de outros Monstros Link. \r\nUma vez por turno: você pode escolher 1 card com a face para cima no campo de cada duelista, exceto este card; os dois cards têm seus efeitos negados até o final deste turno. \r\nQuando 2 monstros forem Invocados por Invocação-Especial ao mesmo tempo em zonas para as quais este card apontar: você pode adicionar 1 monstro Máquina de Nível 5 ou mais do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22431243,'Pílula de Ultra Evolução','Ofereça como Tributo 1 monstro Réptil; Invoque por Invocação-Especial 1 monstro Dinossauro da sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22435424,'Drytron Nu II',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial por um efeito de card. \r\nSe um card "Drytron" estiver no campo: você pode Invocar este card por Invocação-Especial da sua mão ou do Cemitério, mas bana-o quando ele deixar o campo. \r\nSe este card for Invocado por Invocação-Especial: você pode adicionar 1 monstro "Drytron" do seu Deck à sua mão, exceto "Drytron Nu II". \r\nVocê só pode usar cada efeito de "Drytron Nu II" uma vez por turno e, além disso, você não pode Invocar por Invocação-Ritual no turno em que ativar qualquer um dos efeitos deste card, exceto monstros Máquina.','\r',char(13)),'\n',char(10)),'Invocação Especial','Procurar no Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22446869,'Sirena Abisteus',replace(replace('Você pode descartar 1 outro monstro de ÁGUA para o Cemitério; Invoque este card por Invocação-Especial da sua mão. \r\nQuando Invocado desta forma: você pode adicionar 1 monstro "Sirena" de Nível 4 ou menos do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Sirena Abisteus" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22454453,'Jarra da Generosidade','Coloque 1 card da sua mão no topo ou no fundo do Deck.','Topo do Deck','Fundo do Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22479888,'Ataque de Argila','Quando "Clayman, o HERÓI do Elemento" que você controla for alvo de um ataque (mesmo que esteja com a face para baixo, revele-o ao oponente nesse caso): Destrua o monstro atacante e esse "Clayman, o HERÓI do Elemento" e, depois, cause 800 de dano ao oponente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22493811,'Multiplicação de Formigas',replace(replace('Ofereça como Tributo 1 monstro Inseto; Invoque por Invocação-Especial 2 "Ficha de Formiga Soldado" (Inseto/TERRA/Nível 4/ATK 500/DEF 1200). \r\nEssas Fichas não podem ser oferecidas como Tributo para uma Invocação-Tributo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22493812,'Ficha de Formiga Soldado','Invocado por Especial com o efeito "Multiplicação de Formigas". Esta Ficha não pode ser oferecida como Tributo para uma Invocação-Tributo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22499034,'Ignis Hiperardor, o Verdadeiro Dracoguerreiro',replace(replace('Para Invocar este card por Invocação-Tributo com a face para cima, você pode oferecer como Tributo uma Magia/Armadilha Contínua que você controla, em vez de um monstro. \r\nUma vez por turno, quando seu oponente ativar um card ou efeito enquanto você controlar este monstro Invocado por Invocação-Tributo (Efeito Rápido): você pode pegar 1 Magia Contínua "Verdadeiro(a) Draco" ou "Verdadeiro Rei" do seu Deck e ativá-la ou adicioná-la à sua mão.','\r',char(13)),'\n',char(10)),'Invocação Tributo ao oferecer como Tributo um Card de Magia/Armadilha','Adicionar à mão ou ativar no seu Campo','Adicionar à mão?','Escolha o card que deseja adicionar à sua mão ou ativar no seu Campo','','','','','','','','','','','','');
INSERT INTO texts VALUES(22499463,'Cobra da Peçonha','Escamas duras cobrem todas as partes desta cobra gigantesca. Ela caça atirando grandes quantidades de veneno, mas devido ao seu grande tamanho, seu padrão de ataque é previsto facilmente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22501005,'Herança da Besta Espiritual',replace(replace('Monstros que seu oponente controla perdem 200 de ATK para cada Tipo diferente entre os monstros "Besta Espiritual" que você controla. \r\nVocê só pode usar cada um dos seguintes efeitos de "Herança da Besta Espiritual" uma vez por turno. \r\nVocê pode revelar 1 monstro "Besta Espiritual" da sua mão; adicione 1 monstro "Besta Espiritual" com um Tipo diferente do seu Deck à sua mão e, depois, descarte 1 card. \r\nSe 2 ou mais monstros forem Invocados por Invocação-Especial no seu campo ao mesmo tempo (exceto durante a Etapa de Dano): você pode escolher 1 monstro no campo; mude sua posição de batalha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22510667,'Gouki, O Ogro Sólido',replace(replace('2+ monstros "Gouki"	\r\nNão pode ser destruído em batalha ou por efeitos de card enquanto apontar para um monstro "Gouki". \r\nUma vez por turno (Efeito Rápido): você pode escolher 1 monstro "Gouki" na sua Zona de Monstros Principal, exceto "Gouki, O Ogro Sólido"; mova esse monstro que você controla para uma Zona de Monstros Principal para a qual este card apontar.','\r',char(13)),'\n',char(10)),'Escolha 1 monstro para mover','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22512237,'Cão de Caça Mecânico','Enquanto você não tiver cards na sua mão, seu oponente não pode ativar Cards de Magia.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22512406,'Ebisu, Ninja Mascarado','Uma vez por turno, se você controlar um monstro "Ninja" que não seja "Ebisu, Ninja Mascarado": você pode ativar este efeito; devolva Magias/Armadilhas que seu oponente controla para a mão, igual ao número de monstros "Ninja" que você controla e, além disso, cada um dos seus "Goe-Goe, o Ninja Galanteador" podem atacar diretamente neste turno.','Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22530212,'Mão Mágica',replace(replace('Quando seu oponente adicionar um ou mais cards do Deck dele para a mão dele, exceto ao comprá-los (exceto durante a Etapa de Dano): você pode enviar esse(s) card(s) para o Cemitério e, se isso acontecer, cause 800 de dano ao seu oponente. \r\nEste efeito só pode ser usado uma vez enquanto este card estiver com a face para cima no campo.','\r',char(13)),'\n',char(10)),'Enviar para o Cemitério e causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22537443,'Benção de Sebek','Se um monstro seu causar dano de batalha ao seu oponente em um ataque direto: ganhe o mesmo valor de PV.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22539270,'Lubrificante de Restolhos',replace(replace('Selecione 1 monstro "Restolhos" no seu Cemitério. \r\nInvoque por Invocação-Especial esse monstro do Cemitério. \r\nSeus efeitos são negados. \r\nQuando este card for removido do campo, destrua esse monstro. \r\nQuando esse monstro for removido do campo, destrua este card. \r\nVocê não pode conduzir sua Fase de Batalha no turno em que você ativar este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22555834,'Escadaria para um Reino Mitológico',replace(replace('Quando este card for ativado: você pode enviar 1 monstro "Mitológico(a)" do seu Deck para o Cemitério. \r\nVocê pode escolher 1 monstro "Mitológico(a)" no seu Cemitério; descarte 2 cards e, se isso acontecer, adicione esse monstro à sua mão. \r\nVocê só pode usar este efeito de "Escadaria para um Reino Mitológico" uma vez por turno. \r\nSe um monstro "Mitológico(a)" seu atacar um monstro do oponente e você tiver menos cards na sua mão que seu oponente, seu monstro ganha ATK igual à diferença em número de cards x 200, apenas durante o cálculo de dano. \r\nVocê só pode ativar 1 "Escadaria para um Reino Mitológico" por turno.','\r',char(13)),'\n',char(10)),'Enviar 1 monstro "Mitológico(a)" do seu Deck para o Cemitério?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22567609,'Momonga Ágil','Se este card for destruído em batalha e enviado para o Cemitério: ganhe 1000 PV e, depois, você pode Invocar por Invocação-Especial qualquer número de "Momonga Ágil" do seu Deck com a face para baixo em Posição de Defesa.','Ganhar PV','Invocação Especial?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22586618,'Simorgh das Trevas',replace(replace('Enquanto estiver com a face para cima no campo, este card também é do Atributo VENTO. \r\nVocê só pode usar cada um dos seguintes efeitos de "Simorgh das Trevas" uma vez por turno.\r\n● Se você Invocar um monstro de TREVAS ou de VENTO por Invocação-Tributo: você pode Invocar este card por Invocação-Especial do Cemitério (se ele estava lá quando o monstro foi Invocado por Invocação-Tributo) ou da mão (mesmo se ele não estava).\r\n● Quando um Card ou efeito de Magia/Armadilha for ativado (Efeito Rápido): você pode oferecer como Tributo 1 monstro Besta Alada de VENTO; negue a ativação e, se isso acontecer, destrua esse card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22587018,'Hydrogeddon','Quando este card destruir um monstro do oponente em batalha e enviá-lo para o Cemitério: você pode Invocar por Invocação-Especial 1 "Hydrogeddon" do seu Deck.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22589918,'Recarregar',replace(replace('Adicione a sua mão ao seu Deck e embaralhe-o. \r\nEm seguida, compre o mesmo número de cards que adicionou ao seu Deck.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22593417,'Dragão Gumblar Topológico',replace(replace('2+ Monstros de Efeito	\r\nSe outro monstro for Invocado por Invocação-Especial em uma zona para a qual um Monstro Link apontar, enquanto este monstro estiver no campo: descarte 1 ou 2 cards aleatórios e, depois, seu oponente descarta o mesmo número. \r\nDurante sua Fase Principal, se este card estiver Extra Linkado e seu oponente tiver pelo menos 1 card na mão dele: você pode fazer com que seu oponente descarte 1 ou 2 cards (o que for maior) e, depois, se ele não tiver mais cards na mão dele, cause 3000 de dano a ele. \r\nVocê só pode usar 1 efeito de "Dragão Gumblar Topológico" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22609617,'Mataza, o Surpreendente',replace(replace('Este card pode realizar um segundo ataque durante cada Fase de Batalha. \r\nO controle deste card com a face para cima no campo não pode ser trocado.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22610082,'A Máscara dos Remanescentes',replace(replace('Quando este card for ativado: embaralhe este card do campo no Deck. \r\nEnquanto este card estiver equipado a um monstro pelo efeito de "Demônio Mascarado Des Gardius", tome o controle desse monstro.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22617205,'Cavaleirostelar Zefraxciton',replace(replace('Escala de Pêndulo = 7\r\n[ Efeito de Pêndulo ]\r\nVocê não pode Invocar monstros por Invocação-Pêndulo, exceto monstros "Cavaleirost" e "Zefra". \r\nEste efeito não pode ser negado.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe este card for Invocado por Invocação-Normal, Virar ou Pêndulo: você pode escolher 1 outro card "Cavaleirost" ou "Zefra" nas suas Zonas de Monstro ou Zonas de Pêndulo e 1 card Baixado que seu oponente controla; destrua-os. \r\nVocê só pode usar este efeito de "Cavaleirostelar Zefraxciton" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22623509,'Verre, a Empregada de Endymion',replace(replace('(Este card deve ser sempre considerado como um card "Fazticeira".)	\r\nGanha 2300 de ATK enquanto você tiver "Regulus, o Príncipe de Endymion" no seu campo ou Cemitério. \r\nVocê só pode usar cada um dos seguintes efeitos de "Verre, a Empregada de Endymion" uma vez por turno. \r\nDurante sua Fase Principal, se um Card de Magia ou seus efeitos foram ativados neste turno: você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe este card for Invocado por Invocação-Especial: você pode adicionar 1 Magia/Armadilha "Fazticeira" ou 1 "Dimensão Mágica" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Invocação Especial','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22624373,'Lyla, a Feiticeira Luminosa',replace(replace('Você pode escolher 1 Magia/Armadilha que seu oponente controla; a posição de batalha deste card não pode ser mudada até o final do seu próximo turno e, além disso, mude este card que você controla com a face para cima em Posição de Ataque para com a face para cima em Posição de Defesa e, se isso acontecer, destrua o alvo. \r\nUma vez por turno, durante sua Fase Final: envie os 3 cards do topo do seu Deck para o Cemitério.','\r',char(13)),'\n',char(10)),'Destruir um Card de Magia/Armadilha','Enviar 3 cards do seu Deck para o Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22628574,'Pena Falsa',replace(replace('Envie 1 monstro "Asanegra" da sua mão para o Cemitério e escolha 1 Card de Armadilha Normal no Cemitério do seu oponente. \r\nO efeito deste card será o mesmo que o do Card de Armadilha Normal escolhido.','\r',char(13)),'\n',char(10)),'Escolha 1 Card de Armadilha Normal','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22634473,'Rivais Destinados',replace(replace('Se você controlar "Dragão Branco de Olhos Azuis" ou "Mago Negro": até o final deste turno, negue os efeitos de todos os monstros com a face para cima que seu oponente controla atualmente. \r\nVocê só pode ativar 1 "Rivais Destinados" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22638495,'Poder Dinoster, o Poderoso Dracossassino',replace(replace('1 Monstro Pêndulo "Dracossassino" + 1 Monstro Pêndulo	\r\nPrimeiro deve ser Invocado por Invocação-Especial (do seu Deck Adicional) ao oferecer como Tributo os cards acima que você controla. \r\nOs Cards de Monstro Pêndulo nas suas Zonas de Monstros e Zonas de Pêndulo não podem ser destruídos em batalha ou por efeitos de card do seu oponente. \r\nUma vez por turno: você pode Invocar por Invocação-Especial 1 Monstro Pêndulo "Dracossassino" da sua mão ou do Cemitério, mas ele não pode ser usado como uma Matéria de Fusão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22653490,'Chidori do Relâmpago',replace(replace('2 monstros de VENTO de Nível 4	\r\nSe este card for Invocado por Invocação-Xyz: escolha 1 card Baixado que seu oponente controla; devolva o alvo para o fundo do Deck. \r\nUma vez por turno: você pode desassociar 1 Matéria Xyz deste card para escolher 1 card com a face para cima que seu oponente controla; devolva o alvo para o topo do Deck.','\r',char(13)),'\n',char(10)),'Coloque no fundo do Deck','Coloque no topo do Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22657402,'Isolda, Belle do Submundo',replace(replace('Se você controlar "Tristan, Cavaleiro do Submundo", você pode Invocar este card por Invocação-Especial (da sua mão). \r\nNão pode ser Invocado por Invocação-Especial de nenhuma outra forma. \r\nVocê pode escolher até 2 monstros Zumbi que você controla e declarar um Nível de 5 a 8; eles se tornam desse Nível até o final deste turno e, além disso, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros Zumbi. \r\nVocê só pode usar este efeito de "Isolda, Belle do Submundo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22662014,'Delia, a Ajudante da Diversão',replace(replace('Você pode revelar 1 Armadilha "Atração" na sua mão; Invoque este card por Invocação-Especial da sua mão. \r\nVocê pode enviar para o Cemitério 1 Armadilha "Atração" da sua mão ou do campo com a face para cima; Baixe 1 Armadilha "Atração" diretamente do seu Deck na sua Zona de Magias & Armadilhas. \r\nVocê só pode usar cada efeito de "Delia, a Ajudante da Diversão" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22666164,'Comandante Covington','Você pode enviar 1 "Soldado Autômato", 1 "Franco-atirador Autômato" e 1 "Defensor Autômato" com a face para cima que você controla para o Cemitério; Invoque por Invocação-Especial 1 "Força Autômata" da sua mão ou do Deck.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22669793,'Eldlixir da Gloriosa Terra Dourada',replace(replace('Você pode pagar 800 PV e, depois, ative 1 desses efeitos;\r\n● Invoque este card por Invocação-Especial como um Monstro Normal (Zumbi/LUZ/Nível 10/ATK 1500/DEF 2800) (este card ainda é considerado uma Armadilha) e, depois, se você controlar "Eldlich, o Senhor Dourado", você pode devolver 1 monstro do campo para a mão.\r\n● Baixe 1 das suas Magias/Armadilhas "Terra Dourada" ou "Eldlixir" banidos.	\r\nVocê só pode usar este efeito de "Eldlixir da Gloriosa Terra Dourada" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar','Invocação Especial','Baixar','Retornar o monstro para a mão?','','','','','','','','','','','','');
INSERT INTO texts VALUES(22702055,'Umi','Todos os monstros Peixe, Serpente Marinha, Trovão e Aqua no campo ganham 200 de ATK/DEF e, além disso, todos os monstros Máquina e Piro no campo perdem 200 de ATK/DEF.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22712877,'Cogumelo Paralisante',replace(replace('Se um ou mais monstros que eram originalmente Trovão forem enviados da sua mão ou do campo para o Cemitério, mesmo durante a Etapa de Dano: você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe um efeito de um monstro Trovão for ativado na mão, enquanto este card estiver na Zona de Monstros (exceto durante a Etapa de Dano): você pode Invocar por Invocação-Especial 1 "Ficha Paralisante" (Trovão/TREVAS/Nível 1/ATK 0/DEF 0). \r\nVocê só pode usar cada efeito de "Cogumelo Paralisante" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Invocar uma Ficha por Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22712878,'Ficha Paralisante','Invocado por Especial com o efeito "Cogumelo Paralisante".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22723778,'Clorless, Rei do Caos do Mundo Negro',replace(replace('"Rei-Beaux, Suserano do Mundo Negro" + 2+ monstros Demônio	\r\nSe este card for Invocado por Invocação-Fusão: você pode destruir todos os cards que seu oponente controla. \r\nO ATK/DEF originais deste card se tornam o número de matérias usadas para sua Invocação x 1000. \r\nUma vez por turno (Efeito Rápido): você pode escolher 1 card com a face para cima que você controla; descarte 1 card e, além disso, seu oponente não pode escolher esse card com a face para cima como alvo de efeitos de card pelo resto deste turno.','\r',char(13)),'\n',char(10)),'Destruir todos os cards que seu oponente controla','Descarte 1 card da sua mão','O efeito de "Clorless, Rei do Caos do Mundo Negro" está sendo aplicado.','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22734799,'Invocador das Bestas Sagradas',replace(replace('Você pode revelar este card na sua mão; descarte 1 card e, se isso acontecer, Invoque por Invocação-Especial 1 monstro "Bestas Sagradas" da sua mão em Posição de Defesa, exceto um monstro de Nível 8. \r\nVocê pode descartar 1 card; Invoque por Invocação-Especial 1 monstro "Bestas Sagradas" da sua mão ou do Cemitério, em Posição de Defesa, exceto um monstro de Nível 8 ou o card descartado. \r\nVocê pode banir este card do seu Cemitério; Invoque por Invocação-Especial 1 monstro "Bestas Sagradas" do seu Cemitério em Posição de Defesa, exceto um monstro de Nível 8. \r\nVocê só pode usar cada efeito de "Invocador das Bestas Sagradas" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Invocação Especial','Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22747316,'Réplica',replace(replace('Quando seu oponente ativar um Card de Magia/Armadilha com o mesmo nome que um no seu Cemitério: Negue a ativação e, se isso acontecer, destrua esse card. \r\nDepois, você pode adicionar 1 card com esse nome do seu Cemitério à sua mão.','\r',char(13)),'\n',char(10)),'Adicionar à sua mão 1 card com o mesmo nome?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22748199,'O Deus Aprisionado no Gelo',replace(replace('Se 2 ou mais monstros de ÁGUA estiverem no campo: escolha 1 monstro com a face para cima que seu oponente controla; esse monstro com a face para cima não pode atacar e, além disso, seus efeitos são negados. \r\nSe um ou mais monstros de ÁGUA de Nível 5 ou mais forem Invocados por Invocação-Normal ou Especial no seu campo, enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode Baixar este card, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar este efeito de "O Deus Aprisionado no Gelo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22751868,'Castelo do Confronto Karakuri',replace(replace('Quando um monstro "Karakuri" com a face para cima que você controla selecionar um monstro com a face para cima do oponente como alvo de um ataque, você pode mudar a posição de batalha do alvo. \r\nQuando este card com a face para cima no campo for destruído e enviado ao Cemitério, você pode selecionar 1 monstro "Karakuri" de Nível 4 ou mais no seu Cemitério e Invocá-lo por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Mudar a posição de batalha','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22754505,'Golem de Fragmento Pequeno',replace(replace('Quando este card for Invocado, se você controlar um "Golem de Fragmento Grande", você pode Invocar por Invocação-Especial 1 "Golem de Fragmento Médio" do seu Deck. \r\nO efeito desse monstro é negado enquanto ele estiver com a face para cima no campo.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22765132,'Chamado do Camarartista',replace(replace('Quando um monstro do oponente declarar um ataque direto: escolha o monstro atacante; negue o ataque e, se isso acontecer, adicione até 2 monstros "Camarartista" do seu Deck à sua mão, cuja DEF total seja menor ou igual que o ATK do monstro alvo. \r\nAté o final do seu próximo turno depois que este card resolver, você não pode Invocar monstros por Invocação-Especial do Deck Adicional.','\r',char(13)),'\n',char(10)),'Adicione até 2 monstros "Camarartista" à sua mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22790789,'B.E.S. Núcleo de Cristal',replace(replace('Quando você Invoca, por Invocação-Normal, este card, ponha 3 contadores neste card. \r\nEste card não é destruído como resultado de um combate. \r\nSe este card combater, remova 1 contador deste card no final da Damage Step. \r\nSe este card combater sem contadores, destrua este card no final da Damage Step. \r\nUma vez por turno, durante a sua Main Phase, você pode mudar 1 monstro no Campo do seu adversário em Posição de Ataque com a face para cima para a Posição de Defesa com a face para cima.','\r',char(13)),'\n',char(10)),'Colocar um marcador','Remover um marcador','Destruir','Mudar a posição de batalha','','','','','','','','','','','','');
INSERT INTO texts VALUES(22790910,'Sábio da Sabedoria - Himmel',replace(replace('(Este card deve ser sempre considerado como um card "Força Celeste".)	\r\nVocê pode descartar 1 Magia; Invoque este card por Invocação-Especial da sua mão. \r\nQuando seu oponente ativar um card ou efeito que escolha um ou mais Monstros Link que você controla (Efeito Rápido): você pode banir 2 Magias do seu Cemitério; negue o efeito. \r\nSe este card for destruído em batalha ou por um efeito de card e enviado para o Cemitério: você pode escolher 1 das suas Magias "Força Celeste" banidas; adicione-a à sua mão. \r\nVocê só pode usar cada efeito de "Sábio da Sabedoria - Himmel" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22796548,'Juramento do Arquidemônio',replace(replace('Uma vez por turno: você pode pagar 500 PV e, depois, declare 1 nome de card; escave o card do topo do seu Deck e, se for o card declarado, adicione-o à sua mão. \r\nCaso contrário, envie-o para o Cemitério.','\r',char(13)),'\n',char(10)),'Declarar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22802010,'Obliteração Cega','Lance um dado de 6 faces duas vezes e destrua todos os monstros com a face para cima com Nível/Classe menor que a soma dos resultados.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22804410,'Dragão Branco de Olhos Profundos',replace(replace('Quando um ou mais monstros "Olhos Azuis" com a face para cima que você controla forem destruídos em batalha ou por um efeito de card do oponente e você tiver um monstro do Tipo Dragão no seu Cemitério: você pode Invocar este card por Invocação-Especial da sua mão e, se isso acontecer, cause 600 de dano ao seu oponente para cada monstro do Tipo Dragão com um nome diferente no seu Cemitério. \r\nSe este card for Invocado por Invocação-Normal ou Especial: escolha 1 monstro do Tipo Dragão no seu Cemitério; o ATK deste card se torna igual ao desse monstro. \r\nSe este card no campo for destruído por um efeito de card: destrua todos os monstros que seu oponente controla.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22804644,'Dragão do Vírus Mortal',replace(replace('Deve ser Invocado por Invocação-Especial com "A Presa de Critias", usando "Vírus Esmaga-Card". 	\r\nSe este card for Invocado por Invocação-Especial: olhe a mão do seu oponente, todos os monstros que ele controla e todos os cards que ele comprar até o final do 3º turno dele depois da ativação deste efeito e destrua todos os monstros com 1500 ou mais de ATK.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22812068,'Ninja da Armadura de Terra','Se seu oponente controlar um monstro e você não controlar nenhum monstro, você pode Invocar este card por Invocação-Especial (da sua mão).','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22812963,'Senhor Regênese',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao banir 1 monstro com a face para cima que você controla com 2500 de ATK e DEF originais. \r\nVocê só pode Invocar "Senhor Regênese" por Invocação-Especial uma vez por turno desta forma. \r\nSe este card for Invocado por Invocação-Especial: você pode Baixar 1 Magia/Armadilha "Regênese" do seu Deck. \r\nGanha 2500 de ATK apenas durante a Fase de Batalha. \r\nSe este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente.','\r',char(13)),'\n',char(10)),'','Baixar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22819092,'Sonar de Peixes',replace(replace('Adicione 1 monstro de Nível 7 ou menos do seu Deck à sua mão, que mencione "Umi", ou que seja um Monstro Normal de ÁGUA e, depois, se "Umi" estiver no campo, você pode Invocar por Invocação-Especial 1 Monstro Normal de ÁGUA do seu Deck. \r\nVocê só pode ativar 1 "Sonar de Peixes" por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial 1 Monstro Normal de ÁGUA do seu Deck?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22819093,'Sonar de Peixes',replace(replace('Adicione 1 monstro de Nível 7 ou menos do seu Deck à sua mão, que mencione "Umi", ou que seja um Monstro Normal de ÁGUA e, depois, se "Umi" estiver no campo, você pode Invocar por Invocação-Especial 1 Monstro Normal de ÁGUA do seu Deck. \r\nVocê só pode ativar 1 "Sonar de Peixes" por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial 1 Monstro Normal de ÁGUA do seu Deck?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22829942,'Usina de Reciclagem de Fusão',replace(replace('Uma vez por turno: você pode descartar 1 card; adicione 1 "Polimerização" do seu Deck ou Cemitério à sua mão. \r\nUma vez por turno, durante a Fase Final: você pode escolher 1 monstro no seu Cemitério que foi usado como Matéria de Fusão para uma Invocação-Fusão neste turno; adicione-o à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22835145,'Asanegra - Nevasca, o Norte Distante',replace(replace('Não pode ser Invocado por Invocação-Especial. \r\nQuando este card for Invocado por Invocação-Normal: você pode escolher 1 monstro "Asanegra" de Nível 4 ou menos no seu Cemitério; Invoque o alvo por Invocação-Especial em Posição de Defesa.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22837504,'Soldado do Vale das Névoas',replace(replace('No final da Etapa de Dano, se este card batalhou um monstro do oponente que não foi destruído: devolva esse monstro do oponente para a mão. \r\nVocê deve controlar este card com a face para cima para ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22842126,'Panteísmo dos Monarcas',replace(replace('Envie 1 Card de Magia/Armadilha "Monarca" da sua mão para o Cemitério; compre 2 cards. \r\nVocê pode banir este card do seu Cemitério; revele 3 Cards de Magia/Armadilha "Monarca" do seu Deck, seu oponente seleciona 1 para que você adicione à sua mão e você embaralha o resto de volta no seu Deck. \r\nVocê só pode usar este efeito de "Panteísmo dos Monarcas" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22842214,'Lanceiro Marinho',replace(replace('Você pode escolher qualquer número dos seus monstros do Tipo Peixe, Serpente Marinha e Aqua banidos; equipe-os a este card. \r\nEste efeito só pode ser usado uma vez, enquanto este card estiver com a face para cima no campo. \r\nSe este card com a face para cima no campo seria destruído, em vez disso, você pode destruir 1 desses cards. \r\nEste card ganha 1000 de ATK enquanto estiver equipado com um ou mais monstros por este efeito.','\r',char(13)),'\n',char(10)),'Equipar monstros','Usar o efeito de "Lanceiro Marinho" em vez de ser destruído?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22850702,'Anjo do Caos',replace(replace('1 Regulador + 1+ monstros não-Reguladores de LUZ ou de TREVAS	\r\nPara a Invocação-Sincro deste card, você pode considerar 1 monstro de LUZ ou de TREVAS que você controla como um Regulador. \r\nSe este card for Invocado por Invocação-Especial: você pode escolher 1 card no campo; bana-o. \r\nEste card ganha esses efeitos de acordo com os Atributos originais das matérias usadas para sua Invocação-Sincro.\r\n● LUZ: Monstros Sincro que você controla não são afetados por efeitos de monstro ativados pelo seu oponente.\r\n● TREVAS: Monstros que você controla não podem ser destruídos em batalha.','\r',char(13)),'\n',char(10)),'Usar um monstro de LUZ como Matéria Sincro','Usar um monstro de TREVAS como Matéria Sincro','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22850703,'Anjo do Caos',replace(replace('1 Regulador + 1+ monstros não-Reguladores de LUZ ou de TREVAS	\r\nPara a Invocação-Sincro deste card, você pode considerar 1 monstro de LUZ ou de TREVAS que você controla como um Regulador. \r\nSe este card for Invocado por Invocação-Especial: você pode escolher 1 card no campo; bana-o. \r\nEste card ganha esses efeitos de acordo com os Atributos originais das matérias usadas para sua Invocação-Sincro.\r\n● LUZ: Monstros Sincro que você controla não são afetados por efeitos de monstro ativados pelo seu oponente.\r\n● TREVAS: Monstros que você controla não podem ser destruídos em batalha.','\r',char(13)),'\n',char(10)),'Usar um monstro de LUZ como Matéria Sincro','Usar um monstro de TREVAS como Matéria Sincro','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22855882,'Espada do Demônio','Quem resistir à maldição desta lâmina ganhará poderes jamais vistos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22858242,'Zeman, o Rei Macaco',replace(replace('1 Regulador de TREVAS + 1 monstro do Tipo Besta não-Regulador	\r\nSe este card atacar, seu oponente não pode ativar quaisquer Cards de Magia ou Armadilha até o final da Etapa de Dano. \r\nQuando um monstro do oponente declarar um ataque, você pode selecionar esse monstro e enviar 1 monstro da sua mão ou do seu lado do campo ao Cemitério para negar o ataque.','\r',char(13)),'\n',char(10)),'Negar o ataque','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22862454,'Dragão Proxy',replace(replace('2 monstros	\r\nSe um ou mais cards que você controla seriam destruídos em batalha ou por um efeito de card, em vez disso, você pode destruir 1 dos seus monstros para o qual este card apontar.','\r',char(13)),'\n',char(10)),'Usar o efeito de "Dragão Proxy" em vez de ser destruído?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22865492,'Aprimorado, o HERÓI da Visão',replace(replace('Se você sofrer dano de batalha ou de efeito enquanto este card estiver no seu Cemitério: você pode colocar este card do seu Cemitério na sua Zona de Magias & Armadilhas como uma Armadilha Contínua com a face para cima. \r\nDurante a Fase Principal, se este card for considerado como uma Armadilha Contínua: você pode oferecer como Tributo 1 monstro "HERÓI"; Invoque este card por Invocação-Especial. \r\nSe este card for Invocado por Invocação-Especial da Zona de Magias & Armadilhas: você pode Invocar por Invocação-Especial 1 monstro "HERÓI da Visão" de Nível 4 ou menos do seu Deck. \r\nVocê só pode usar cada efeito de "Aprimorado, o HERÓI da Visão" uma vez por turno.','\r',char(13)),'\n',char(10)),'Baixar este card como um Card de Armadilha Contínua','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22866836,'Inversão do Sentido',replace(replace('Ative 1 desses efeitos.\r\n● Escolha 1 Monstro Xyz Máquina de TERRA que você controla em Posição de Ataque e 1 monstro que seu oponente controla; mude a posição de batalha do seu monstro e, se isso acontecer, destrua o monstro do oponente.\r\n● Escolha 1 Monstro Xyz Máquina de TERRA que você controla em Posição de Defesa e 1 Magia/Armadilha que seu oponente controla; mude a posição de batalha do seu monstro e, se isso acontecer, destrua a Magia/Armadilha do oponente.','\r',char(13)),'\n',char(10)),'Destruir um monstro do oponente','Destrua as Magias/Armadilhas do seu oponente','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22869904,'Essa Alquimia Louca!','Se um ou mais Cards de Magia com a face para cima na Zona dos Cards de Magia e Armadilha do seu oponente forem enviados para o Cemitério: você pode escolher 1 monstro com a face para cima no campo; destrua o alvo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22873798,'Hiena','Quando este card for destruído em batalha e enviado para o Cemitério: você pode Invocar por Invocação-Especial qualquer número de "Hienas" do seu Deck.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22888900,'Prisão Grisalha','Se você controlar um monstro com a face para cima que foi Invocado por Invocação-Tributo, Ritual ou Fusão: até o final do próximo turno do seu oponente, nenhum duelista pode Invocar por Invocação-Sincro ou Xyz, Monstros Sincro e Xyz não podem atacar e, além disso, seus efeitos são negados.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22900219,'Dinolutador Quimera T Wrextle',replace(replace('1 Monstro Link "Dinolutador" + 1 monstro "Dinolutador"	\r\nSe este card batalhar, seu oponente não pode ativar Cards de Magia/Armadilha até o final da Etapa de Dano. \r\nSe este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante. \r\nOs monstros do seu oponente não podem escolher monstros como alvo de ataques, exceto este. \r\nSe este card destruir um monstro em batalha: ele ganha 500 de ATK. \r\nSe este card for destruído por um efeito de card: destrua todos os monstros em Posição de Ataque do seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22900598,'Dominação do Vampiro',replace(replace('Se você não tiver nenhum card na sua Zona do Campo e todos os monstros com a face para cima que você controla forem monstros Zumbi (mín. 1): ative 1 "Reino Vampiro" diretamente do seu Deck e, depois, você pode Invocar por Invocação-Especial 1 monstro "Vampiro(a)" de TREVAS do seu Cemitério em Posição de Defesa. \r\nVocê só pode ativar 1 "Dominação do Vampiro" por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial do seu Cemitério, em Posição de Defesa com a face para cima, 1 monstro de TREVAS cujo nome contenha "Vampiro(a)"?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22908820,'Amanhecer, o HERÓI do Elemento',replace(replace('2 monstros "HERÓI" com Atributos diferentes	\r\nDeve ser Invocado por Invocação-Fusão. \r\nMonstros que você controla ganham 200 de ATK para cada Atributo diferente que você controla. \r\nVocê só pode usar cada um dos seguintes efeitos de "Amanhecer, o HERÓI do Elemento" uma vez por turno.\r\n● Se este card for Invocado por Invocação-Especial: você pode adicionar 1 "Fusão Miraculosa" do seu Deck à sua mão.\r\n● Quando um ataque for declarado envolvendo outro monstro "HERÓI" que você controla: você pode escolher 1 card no campo; destrua-o.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22910685,'Rei Fantasma Verde','Este jovem rei das florestas vive num mundo verde cheio de árvores e vida selvagem.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22912101,'Surto Blitzclique',replace(replace('Você pode revelar este card na sua mão e, depois, escolha 1 monstro no campo; destrua-o e, se isso acontecer, Invoque por Invocação-Especial 1 monstro Trovão da sua mão e, além disso, pelo resto deste turno, você não pode Invocar Monstros de Efeito por Invocação-Especial, exceto da mão. \r\nSe um ou mais outros cards forem destruídos por um efeito de card, enquanto este card estiver na Zona de Monstros (exceto durante a Etapa de Dano): você pode adicionar 1 monstro "Blitzclique" do seu Deck à sua mão, exceto "Surto Blitzclique". \r\nVocê só pode usar cada efeito de "Surto Blitzclique" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Efeito de busca','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22916281,'Escolhido pelo Cálice Mundial','Inspirado pelas lendas do Herói Mundial que ele ouvia quando criança, este cruzado acopla a sua armadura uma parte de cada Mekkstruosidade que destrói. Ele partiu em uma missão da Fada Lee para recuperar os Sete Legados Mundiais e salvar seu mundo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22916418,'Homem de Capa, o Ultra-Humano',replace(replace('Não pode ser oferecido como Tributo, ou destruído em batalha, enquanto estiver com a face para cima no campo. \r\nVocê só pode usar cada um dos seguintes efeitos de "Homem de Capa, o Ultra-Humano" uma vez por turno. \r\nSe seu oponente controlar um card com a face para cima do qual você é dono: você pode Invocar este card por Invocação-Especial da sua mão. \r\nDurante a Fase Final, se este card foi Invocado por Invocação-Normal ou Especial neste turno: você pode colocar este card no fundo do Deck e, depois, você pode devolver para a sua mão 1 card do qual você é dono com a face para cima no campo.','\r',char(13)),'\n',char(10)),'Invocação Especial','Retornar ao Deck','Retornar um card à mão?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22923081,'Breaker, o Guerreiro Mágico Negro',replace(replace('Se este card for Invocado por Invocação-Normal: coloque 2 Marcadores de Magia nele. \r\nSe este card for Invocado por Invocação-Pêndulo: coloque 3 Marcadores de Magia nele. \r\nGanha 400 de ATK para cada Marcador de Magia nele. \r\nVocê pode remover 1 Marcador de Magia deste card e, depois, escolha 1 Magia/Armadilha no campo; destrua-a. \r\nVocê só pode usar este efeito de "Breaker, o Guerreiro Mágico Negro" uma vez por turno.','\r',char(13)),'\n',char(10)),'Colocar Marcadores de Magia','Colocar Marcadores de Magia','Destrua 1 Card de Magia/Armadilha','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22933016,'Renascimento I.A.tivo',replace(replace('Escolha 1 monstro "@Ignister" no seu Cemitério; Invoque-o por Invocação-Especial e, além disso, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno depois que este card resolver, exceto monstros Ciberso. \r\nQuando um ataque for declarado envolvendo 2 monstros: você pode banir este card do seu Cemitério e 1 card da sua mão e, depois, escolha 1 das suas Magias/Armadilhas "I.A." que estiverem banidas ou no seu Cemitério, exceto "Renascimento I.A.tivo"; adicione esse card à sua mão. \r\nVocê só pode usar cada efeito de "Renascimento I.A.tivo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22938501,'Sábio Regênese',replace(replace('Se um monstro com 2500 de ATK ou DEF original estiver no campo, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Sábio Regênese" por Invocação-Especial uma vez por turno desta forma. \r\nVocê só pode usar cada um dos seguintes efeitos de "Sábio Regênese" uma vez por turno. \r\nQuando seu oponente ativar um card ou efeito (Efeito Rápido): você pode enviar para o Cemitério 1 outro card "Regênese" da sua mão ou do campo com a face para cima; negue a ativação e, se isso acontecer, destrua esse card. \r\nDurante a Fase Final do seu oponente, se este card estiver no Cemitério porque foi enviado para lá neste turno: você pode adicionar este card à sua mão.','\r',char(13)),'\n',char(10)),'','Negar','Recuperar','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22953211,'Caça Gatosino',replace(replace('3 monstros, incluindo uma Ficha	\r\nQuando este card destruir um monstro do oponente em batalha: você pode Invocar por Invocação-Especial 1 "Ficha Gatosino" (Máquina/VENTO/Nível 4/ATK 2000/DEF 2000) em Posição de Defesa.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22953212,'Ficha Gatosino','Invocada por Invocação-Especial com o efeito "Caça Gatosino".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22959079,'Buraco Dimensional',replace(replace('Selecione 1 monstro no seu campo e remova-o do Duelo até sua próxima Fase de Apoio. \r\nEnquanto o monstro estiver removido do Duelo, a Zona de Card de Monstro do monstro selecionado não pode ser usada.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22970795,'Senhor Inumano',replace(replace('O nome deste card se torna "Servo Caveira" enquanto estiver no Cemitério. \r\nVocê só pode usar cada um dos seguintes efeitos de "Senhor Inumano" uma vez por turno. \r\nSe você tiver "Servo Caveira" ou "Rei dos Servos Caveira" no seu Cemitério: você pode enviar este card da sua mão ou do campo para o Cemitério; envie cards do topo do seu Deck para o Cemitério, até o número de "Servo Caveira" e "Rei dos Servos Caveira" no seu Cemitério. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 "Servo Caveira" ou "Rei dos Servos Caveira" no seu Cemitério; Invoque-o por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Enviar do Deck para o Cemitério','Invocação Especial','Escolha a quantidade de cards a enviar para o Cemitério','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22984000,'Mercurium, o Mercúrio Vivo',replace(replace('2+ monstros de Nível 10	\r\nSe este card for Invocado por Invocação-Xyz: você pode associar 1 monstro do seu Deck a este card como matéria. \r\nVocê só pode usar este efeito de "Mercurium, o Mercúrio Vivo" uma vez por turno. \r\nEnquanto este card tiver matéria, seu oponente não pode ativar os efeitos de monstros no Cemitério dele com o mesmo Atributo que o de um monstro no seu Cemitério. \r\nUma vez por turno, durante a Fase Final: desassocie 1 matéria deste card ou sofra 3000 de dano.','\r',char(13)),'\n',char(10)),'Associar Matéria Xyz','Desassociar matéria ou sofrer dano','Desassociar Matéria Xyz?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22991179,'Descuido dos Insetos','Quando um monstro do seu oponente declarar um ataque: você pode banir 1 monstro Inseto do seu Cemitério; negue o ataque.','Negar o ataque','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22993208,'Investida dos Reis de Fogo',replace(replace('Se somente seu oponente controlar um monstro: Invoque por Invocação-Especial 1 monstro Besta, Besta-Guerreira ou Besta Alada de FOGO do seu Deck, mas seus efeitos são negados e, além disso, destrua-o durante a Fase Final. \r\nVocê só pode ativar 1 "Investida dos Reis de Fogo" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22996376,'Behemoth, o Rei de Todos os Animais',replace(replace('Você pode Invocar este card por Invocação-Normal/Baixar com 1 Tributo, mas seu ATK original se torna 2000. \r\nQuando este card for Invocado por Invocação-Tributo: você pode escolher monstros Besta no seu Cemitério igual ao número de monstros oferecidos como Tributo; devolva-os para a mão.','\r',char(13)),'\n',char(10)),'Oferecer 1 monstro como Tributo para uma Invocação Tributo','Retornar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23002292,'Reinicialização Vermelha',replace(replace('Quando seu oponente ativar um Card de Armadilha: negue a ativação e, se isso acontecer, Baixe esse card com a face para baixo e, depois, ele pode Baixar 1 outra Armadilha diretamente do Deck dele. \r\nPelo resto deste turno depois que este card resolver, seu oponente não pode ativar Cards de Armadilha. \r\nVocê pode ativar este card da sua mão ao pagar metade dos seus PV.','\r',char(13)),'\n',char(10)),'Baixar 1 Card de Armadilha do seu Deck?','Ativar aplicando o efeito de "Reinicialização Vermelha".','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23008320,'Chamado do Ressonador','Adicione 1 monstro "Ressonador" do seu Deck à sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23015896,'Avatar Altíssimo do Rei de Fogo Garunix',replace(replace('Uma vez por turno, durante a próxima Fase de Apoio depois que este card foi destruído por um efeito de card e enviado para o Cemitério: Invoque este card por Invocação-Especial do Cemitério. \r\nSe isso acontecer: destrua todos os outros monstros no campo. \r\nQuando este card for destruído em batalha e enviado para o Cemitério: você pode Invocar por Invocação-Especial 1 monstro "Rei(s) de Fogo" do seu Deck, exceto "Avatar Altíssimo do Rei de Fogo Garunix".','\r',char(13)),'\n',char(10)),'Invocação Especial','Destruir um monstro','Invocar por Invocação Especial do Deck','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23020408,'Servo da Alma',replace(replace('Coloque 1 card da sua mão, do Deck ou do Cemitério no topo do Deck, que seja "Mago Negro" ou que mencione "Mago Negro" ou "Pequena Maga Negra", exceto "Servo da Alma". \r\nDurante sua Fase Principal: você pode banir este card do seu Cemitério; compre cards igual ao número de monstros "Paládio", "Mago Negro" e/ou "Pequena Maga Negra" com nomes diferentes no campo e nos Cemitérios. \r\nVocê só pode usar este efeito de "Servo da Alma" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Escolha o(s) card(s) para colocar no topo do Deck','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23032273,'Luz de Megirus','Os feixes fatais dos olhos deste monstro levam a uma destruição sinistra.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23051413,'Lucano de Naturia',replace(replace('Uma vez por turno, durante a Etapa de Batalha ou Etapa de Dano do ataque deste card, quando seu oponente ativar um card ou efeito, você pode selecionar 1 monstro "Naturia" no seu Cemitério. \r\nInvoque esse monstro por Invocação-Especial do Cemitério.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23064604,'Erebus, o Monarca do Submundo',replace(replace('Você pode Invocar este card por Invocação-Tributo ao oferecer como Tributo 1 monstro Invocado por Invocação-Tributo. \r\nSe este card for Invocado por Invocação-Tributo: você pode enviar 2 Cards de Magia/Armadilha "Monarca" com nomes diferentes da sua mão e/ou Deck para o Cemitério e, se isso acontecer, embaralhe no Deck 1 card da mão (aleatório), Cemitério ou lado do campo do seu oponente. \r\nUma vez por turno, durante a Fase Principal de qualquer duelista, se este card estiver no seu Cemitério: você pode descartar 1 Card de Magia/Armadilha "Monarca" e, depois, escolher 1 monstro no seu Cemitério com 2400 ou mais de ATK e 1000 de DEF; adicione-o à sua mão.','\r',char(13)),'\n',char(10)),'Ofereça 1 monstro Invocado por Invocação Tributo como Tributo para uma Invocação Tributo','Envie 2 Magias/Armadilhas "Monarca" com nomes diferentes da sua mão e/ou Deck para o Cemitério e depois embaralhe no Deck 1 card da mão, do campo ou do Cemitério do seu oponente','Escolha 1 monstro no seu Cemitério com 2400 ou mais de ATK e 1000 de DEF; adicione-o à sua mão','Escolha 1 card na mão do seu oponente para devolvê-la ao Deck','Escolha 1 card que seu oponente controla para devolvê-la ao Deck','Escolha 1 card no Cemitério do seu oponente para devolvê-la ao Deck','','','','','','','','','','');
INSERT INTO texts VALUES(23068051,'Cachoeira de Almas de Dragão',replace(replace('Ative 1 desses efeitos;\r\n● Adicione 1 monstro Wyrm do seu Deck à sua mão.\r\n● Envie qualquer número de monstros Wyrm da sua mão e/ou com a face para cima no seu campo para o Cemitério; compre cards igual ao número de monstros que você enviou para o Cemitério +1.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Enviar para o Cemitério e comprar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23076639,'Gazelle, o Rei das Garras Místicas',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 monstro Demônio de Nível 5 ou 1 "Fusão Quimera" do seu Deck à sua mão. \r\nSe este card for enviado para o Cemitério como matéria para uma Invocação-Fusão: você pode adicionar 1 monstro Ilusão do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "Gazelle, o Rei das Garras Místicas" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23085002,'Número 68: Sanaphond, a Prisão Celeste',replace(replace('2 monstros de Nível 8	\r\nGanha 100 de ATK e DEF para cada monstro nos Cemitérios. \r\nUma vez por turno: você pode desassociar 1 matéria deste card; até o final do próximo turno do seu oponente, este card não pode ser destruído por efeitos de card e, além disso, nenhum duelista pode Invocar monstros por Invocação-Especial dos Cemitérios.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23087070,'Bruxa das Rosas','Este card pode ser considerado como 2 Tributos para a Invocação-Tributo de um monstro Planta.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23093373,'Selettrice Vaalmônica',replace(replace('Enquanto você controlar um monstro, exceto "Selettrice Vaalmônica", os monstros do seu oponente não podem escolher este card como alvo de ataques. \r\nVocê só pode usar cada um dos seguintes efeitos de "Selettrice Vaalmônica" uma vez por turno. \r\nSe este card for Invocado por Invocação-Normal ou Pêndulo: você pode adicionar 1 card "Vaalmônica" do seu Deck à sua mão, exceto "Selettrice Vaalmônica". \r\nSe este card for enviado para o Cemitério e você tiver 2 cards "Vaalmônica" nas suas Zonas de Pêndulo: você pode adicionar este card à sua mão.','\r',char(13)),'\n',char(10)),'Adicione à sua mão 1 card "Vaalmônica"','Adicionar este card à sua mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23093604,'Sabre-X Pashuul',replace(replace('Não pode ser destruído em batalha. \r\nUma vez por turno, durante a Fase de Apoio do seu oponente: você sofre 1000 de dano. \r\nEste card deve estar com a face para cima em Posição de Defesa para ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Receba 1000 de dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23099524,'Advento Faraônico',replace(replace('Ganha 300 de ATK para cada Armadilha Contínua no campo e nos Cemitérios. \r\nVocê só pode usar cada um dos seguintes efeitos de "Advento Faraônico" uma vez por turno. \r\nVocê pode oferecer 1 monstro como Tributo; Invoque este card por Invocação-Especial da sua mão. \r\nVocê pode oferecer como Tributo 1 monstro Fada, Demônio ou Réptil; adicione 1 Armadilha Contínua do seu Deck à sua mão e, além disso, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23115241,'Sabre-X Anu Piranha','Uma Guerreira Sabre-X, conhecida por seus ataques graciosos e decisões feitas a sangue frio na batalha. Ela tem ambições cruéis e causa temor no coração de seus inimigos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23116808,'Goka, o Piro da Malícia',replace(replace('Se você controlar um monstro de FOGO, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nAo fazê-lo: escolha 1 monstro de FOGO que você controla; destrua o alvo. \r\nDurante cada uma de suas Fases de Apoio: Invoque por Invocação-Especial 1 "Ficha de Bola de Fogo" (Tipo Piro/FOGO/Nível 1/ATK 100/DEF 100) em Posição de Defesa. \r\nVocê pode oferecer como Tributo 1 outro monstro de FOGO; este card ganha 500 de ATK até a Fase Final.','\r',char(13)),'\n',char(10)),'Destruir','Invocação Especial','Aumentar ATK','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23116809,'Ficha de Bola de Fogo','Invocado por Especial com o efeito "Goka, o Piro da Malícia" ou um card relacionado.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23118924,'Demônio do Elemento',replace(replace('Este monstro obtém o(s) seguinte(s) efeito(s) enquanto existir(em) monstro(s) com o seguinte Atributo no Campo.\r\n● TERRA: O efeito do Card de Monstro que este card destrúa como resultado de um combate é anulado.\r\n● VENTO: Se este card destruir um monstro como resultado de um combate, este card pode atacar mais uma vez logo em seguida.','\r',char(13)),'\n',char(10)),'Continuar atacando','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23122036,'Escudo da Intriga',replace(replace('Escolha 1 monstro com a face para cima que você controla; equipe este card ao alvo. \r\nUma vez por turno, enquanto o monstro equipado estiver em Posição de Ataque, ele não pode ser destruído em batalha. \r\nVocê não sofre dano de batalha de ataques que o envolvam.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23147658,'Soldado Desgastado',replace(replace('Se este card for destruído em batalha ou enviado para o Cemitério por um efeito de card: você pode adicionar 1 "Fusão Fóssil", ou 1 card que mencione "Fusão Fóssil", exceto "Soldado Desgastado", do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Soldado Desgastado" uma vez por turno. \r\nUma vez por turno, durante sua Fase Final: este card perde 600 de ATK.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23151193,'Diabellstar da Vingança',replace(replace('(Este card deve ser sempre considerado como um card "Despojos do Pecado".)	\r\nVocê pode banir 1 Magia e 1 Armadilha da sua mão e/ou do Cemitério; Invoque este card por Invocação-Especial da sua mão ou do Cemitério. \r\n(Efeito Rápido): você pode pagar metade dos seus PV e, depois, escolha 1 card que seu oponente controla; destrua-o e, depois, se outro Card de Monstro "Diabell" estiver no campo, você pode Invocar por Invocação-Especial 1 Monstro Sincro Regulador (Ilusão ou Mago) do seu Deck Adicional. \r\nVocê só pode usar cada efeito de "Diabellstar da Vingança" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Efeito de destruição','Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23153227,'Ascensão do Sétimo',replace(replace('Pegue 1 card do seu Deck (seja uma Magia/Armadilha "de Barian", uma Magia Rápida "Magia de Aumento de Classe" ou uma Magia/Armadilha "Sétimo", exceto "Ascensão do Sétimo") e adicione-o à sua mão ou coloque-o no topo do seu Deck. \r\nSe seu oponente controlar um monstro Invocado por Invocação-Especial do Deck Adicional: você pode banir este card do seu Cemitério e enviar 1 Magia "Magia de Aumento de Classe" da sua mão para o Cemitério; este efeito se torna o efeito dessa Magia quando esse card for ativado. \r\nVocê só pode usar cada efeito de "Ascensão do Sétimo" uma vez por turno.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Copiar uma Magia de Aumento de Classe','Colocar no topo do Deck','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23153228,'Ascensão do Sétimo',replace(replace('Pegue 1 card do seu Deck (seja uma Magia/Armadilha "de Barian", uma Magia Rápida "Magia de Aumento de Classe" ou uma Magia/Armadilha "Sétimo", exceto "Ascensão do Sétimo") e adicione-o à sua mão ou coloque-o no topo do seu Deck. \r\nSe seu oponente controlar um monstro Invocado por Invocação-Especial do Deck Adicional: você pode banir este card do seu Cemitério e enviar 1 Magia "Magia de Aumento de Classe" da sua mão para o Cemitério; este efeito se torna o efeito dessa Magia quando esse card for ativado. \r\nVocê só pode usar cada efeito de "Ascensão do Sétimo" uma vez por turno.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Copiar uma Magia de Aumento de Classe','Colocar no topo do Deck','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23160024,'Pessoa Amorfa',replace(replace('Todos os monstros "Amórfago" no campo ganham 300 de ATK/DEF. \r\nAté duas vezes por turno, se um ou mais monstros "Amórfago" que você controla forem oferecidos como Tributo, compre 1 card. \r\nVocê pode banir este card do seu Cemitério; ofereça como Tributo Monstros Pêndulo da sua mão ou do campo cuja soma dos Níveis seja exatamente igual a 8 e, depois, Invoque por Invocação-Ritual 1 "Pesar Amorfactor, o Dracosuserano da Imaginação" da sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23166823,'Domador da Besta Espiritual Zefrawendi',replace(replace('Escala de Pêndulo = 7\r\n[ Efeito de Pêndulo ]\r\nVocê não pode Invocar monstros por Invocação-Pêndulo, exceto monstros "Besta Espiritual" e "Zefra". \r\nEste efeito não pode ser negado.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nQuando este card for Invocado por Invocação-Normal ou Pêndulo: você pode adicionar 1 monstro "Zefra" com a face para cima do seu Deck Adicional à sua mão, exceto "Domador da Besta Espiritual Zefrawendi". \r\nVocê só pode Invocar um ou mais "Domador da Besta Espiritual Zefrawendi" por Invocação-Especial uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23168060,'Homem-Chave, o Guerreiro-Chave','Uma vez por turno, durante sua Fase Principal: Você pode tornar este card de Nível 3 até a Fase Final.','Alterar Nível','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23171610,'Remover Limites',replace(replace('Até o final deste turno, dobre o ATK de todos os monstros Máquina que você controla atualmente. \r\nDurante a Fase Final deste turno, destrua esses monstros.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23171611,'Remover Limites',replace(replace('Até o final deste turno, dobre o ATK de todos os monstros Máquina que você controla atualmente. \r\nDurante a Fase Final deste turno, destrua esses monstros.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23187256,'Número 93: Kaiser Utopia',replace(replace('2+ Monstros Xyz "Número", com a mesma Classe, que tiverem matéria	\r\nUma vez por turno: você pode Invocar por Invocação-Especial do seu Deck Adicional, monstros "Número" de Classe 9 ou menos com 3000 ou menos de ATK, que tenham Classes diferentes uns dos outros, até o número de matérias com nomes diferentes associadas a este card, mas seus efeitos são negados e, depois, desassocie 1 matéria deste card. \r\nPelo resto deste turno, a não ser que este efeito tenha sido negado, você não pode Invocar por Invocação-Especial e qualquer dano de batalha que seu oponente sofrer é diminuído pela metade. \r\nEnquanto você controlar outro Monstro Xyz "Número", este card não pode ser destruído em batalha ou por efeitos de card.','\r',char(13)),'\n',char(10)),'Invocação Especial','Invocar outro monstro por Invocação Especial?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23204029,'Caos, o HERÓI do Contraste',replace(replace('2 monstros "HERÓI Mascarado"	\r\n(Este card é tratado como um card "HERÓI do Elemento".)	\r\nDeve ser Invocado por Invocação-Fusão e não pode ser Invocado por Invocação-Especial de nenhuma outra forma. \r\nEnquanto estiver com a face para cima no campo, este card também é de Atributo LUZ. \r\nUma vez por turno, durante o turno de qualquer duelista: você pode escolher 1 card com a face para cima no campo; negue os efeitos do alvo até o final deste turno.','\r',char(13)),'\n',char(10)),'Negar o efeito','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23205979,'Ceifeiro de Espíritos',replace(replace('Não pode ser destruído em batalha. \r\nDepois de resolver um efeito de card que escolha como alvo este card com a face para cima, destrua este card. \r\nSe este card causar dano de batalha ao seu oponente em um ataque direto: descarte 1 card aleatório da mão dele.','\r',char(13)),'\n',char(10)),'Descartar 1 card','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23212990,'Ataque dos Seis - Devastação do Trovão',replace(replace('Remova 1 Marcador de Bushido do seu lado do campo para ativar 1 desses efeitos.\r\n● Escolha 1 monstro que seu oponente controla; destrua o alvo.\r\n● Escolha 1 card que seu oponente controla; devolva o alvo para a mão.','\r',char(13)),'\n',char(10)),'Destrua 1 monstro que seu oponente controla.','Retornar para a mão 1 card que seu oponente controla.','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23213239,'Perigo! Perturbação! Desordem!',replace(replace('Quando um monstro "Perigo!" seu for destruído em batalha com um monstro do oponente: você pode destruir esse monstro do oponente. \r\nVocê pode banir 3 Magias/Armadilhas "Perigo!" com nomes diferentes do seu Cemitério; destrua todos os cards no campo e, além disso, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros "Perigo!". \r\nVocê só pode usar este efeito de "Perigo! Perturbação! Desordem!" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23219323,'Guerreiro Sucata/Modo de Ataque',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial com "Ativar Modo de Ataque". \r\nGanha 1000 de ATK para cada monstro "/Modo de Ataque" que você controla e, além disso, se este card batalhar um monstro, qualquer dano de batalha que ele causar ao seu oponente é dobrado. \r\nNão é afetado pelos efeitos de monstros ativados do seu oponente. \r\nSe este card for destruído: você pode escolher 1 "Guerreiro Sucata" no seu Cemitério; devolva-o para o Deck Adicional e, depois, você pode Invocá-lo por Invocação-Especial (isso é considerado uma Invocação-Sincro).','\r',char(13)),'\n',char(10)),'Retornar ao Deck','Invocação Especial?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23220533,'Cavalestrela Rayel',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode adicionar 1 Magia/Armadilha "Cavalestrela" do seu Deck à sua mão. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 monstro "Cavalestrela" no seu Cemitério, exceto "Cavalestrela Rayel"; Invoque-o por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Cavalestrela Rayel" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23220863,'Cavalaria Mágica de Cxulub',replace(replace('Escala de Pêndulo = 3\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nEste card não é afetado por efeitos ativados de monstros, exceto Monstros Pêndulo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23232295,'Boxeador Obstinado de Canga',replace(replace('2 monstros "Boxeador Obstinado" de Nível 4	\r\nSe um ou mais monstros "Boxeador Obstinado" que você controla seriam destruídos em batalha ou por um efeito de card, você pode desassociar 1 matéria deste card em vez de destruir 1 desses monstros. \r\nSe uma ou mais matérias forem desassociadas deste card: este card ganha 800 de ATK.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23234094,'Evolssauro Elias','Quando este card for Invocado por Invocação-Especial pelo efeito de um monstro "Evoltil": Você pode Invocar por Invocação-Especial 1 monstro de FOGO do Tipo Dinossauro de Nível 6 ou menos da sua mão.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23249029,'Armas Nobres do Imitador Amaldiçoado',replace(replace('O monstro equipado ganha 200 de ATK/DEF para cada Magia de Equipamento no seu campo e Cemitério. \r\nEnquanto este card estiver equipado a um monstro Guerreiro: você pode ativar este efeito; você não pode Invocar por Invocação-Especial pelo resto deste turno, exceto monstros Guerreiro e, além disso, Invoque por Invocação-Especial do seu Deck 1 monstro Guerreiro com o mesmo Atributo e Nível que o do monstro equipado, mas um nome diferente e, se isso acontecer, equipe-o com este card e, depois, destrua o monstro ao qual este card estava equipado. \r\nVocê só pode usar este efeito de "Armas Nobres do Imitador Amaldiçoado" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23265313,'Reduzir Custos','Descarte 1 card; pelo resto deste turno, reduza em 2 o Nível de todos os monstros na sua mão (mesmo depois que eles forem Invocados).','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23265594,'Plataforma de Suporte de Mech''s Pesados',replace(replace('Uma vez por turno, você pode: escolher 1 monstro Máquina que você controla; equipe este card no alvo, OU: desequipe este card e Invoque-o por Invocação-Especial. \r\nUm monstro equipado com este card ganha 500 de ATK/DEF e, além disso, se o monstro equipado seria destruído em batalha ou por um efeito de card, em vez disso, destrua este card.','\r',char(13)),'\n',char(10)),'Equipar','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23269426,'Gesto Final',replace(replace('Escolha 1 monstro de Nível 3 com a face para cima que você controla; Invoque por Invocação-Especial 1 monstro com o mesmo nome desse monstro da sua mão ou Cemitério. \r\nSeus efeitos são negados. \r\nDurante a Fase Final deste turno, destrua o monstro com a face para cima que foi escolhido como alvo deste card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23270035,'Monstros Sortidos',replace(replace('Revele 1 Monstro Normal do seu Deck e 1 Monstro de Efeito do seu Deck com o mesmo Tipo, Atributo e Nível e, depois, seu oponente seleciona aleatoriamente 1 para que você adicione à sua mão e, além disso, você embaralha o outro no seu Deck. \r\nVocê só pode ativar 1 "Monstros Sortidos" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23274061,'Wattesquilo',replace(replace('Este card pode realizar um segundo ataque durante cada Fase de Batalha. \r\nDepois do cálculo de dano, se este card batalhou um monstro: negue os efeitos desse monstro (incluindo no Cemitério).','\r',char(13)),'\n',char(10)),'Negar efeitos','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23282832,'Descontrole',replace(replace('Pague 500 PV. \r\nInvoque por Invocação-Especial do Cemitério de ambos os duelistas tantos Monstros Normais quanto possível com 1000 ou menos de ATK que foram destruídos em batalha neste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23288411,'Mementoal Tecuhtlica - Criação Combinada',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão ou do Cemitério) ao embaralhar no Deck/Deck Adicional 5 outros monstros "Memento" com nomes diferentes da sua mão e/ou do Cemitério. \r\nEnquanto você não controlar nenhum outro monstro, este card pode atacar todos os monstros que seu oponente controla, uma vez cada. \r\nUma vez por turno, se seu oponente ativar um card ou efeito (exceto durante a Etapa de Dano): você pode Invocar por Invocação-Especial 1 monstro "Memento" da sua mão ou do Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23289281,'Homem Karate',replace(replace('Uma vez por turno, você pode dobrar o ATK original deste card. \r\nSe você usou este efeito, destrua este card durante a Fase Final.','\r',char(13)),'\n',char(10)),'Alterar ATK','Destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23296404,'Cavaleirardor Lanceiro',replace(replace('Enquanto este card estiver na sua mão: você pode escolher 3 cards "Cavaleirardor" que você controla; destrua-os e, se isso acontecer, Invoque este card por Invocação-Especial. \r\nUma vez por turno: você pode escolher 1 outro monstro "Cavaleirardor" que você controla; devolva-o para a mão e, se isso acontecer, coloque 1 Card de Magia/Armadilha que seu oponente controla no fundo do Deck.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23297235,'Cão de Fogo de Flamvell','Quando este card destruir um monstro do oponente em batalha e enviá-lo para o Cemitério: você pode Invocar por Invocação-Especial 1 monstro de FOGO com DEF 200 ou menos do seu Deck, exceto "Cão de Fogo de Flamvell".','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23299957,'Zona de Conexão Veicroide','Invoque por Invocação-Fusão 1 Monstro de Fusão "Veicroide" do seu Deck Adicional, usando monstros da sua mão ou do campo como Matéria de Fusão e, se isso acontecer, ele não pode ser destruído por efeitos de card e seus efeitos não podem ser negados.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23303072,'Dragão de Montagem',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nVocê deve Invocá-lo por Invocação-Especial (da sua mão) ao enviar 3 outros monstros da sua mão para o Cemitério e não pode ser Invocado por Invocação-Especial de nenhuma outra forma. \r\nO ATK deste card se torna o total dos Níveis originais dos monstros enviados x 300.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23309606,'Incinerador Infernal',replace(replace('Este card só pode ser Invocado por Invocação-Normal ou Baixado ao descartar todos os outros cards na sua mão e oferecendo como Tributo 1 card que você controla com 2000 de ATK ou mais. \r\nEste card ganha 200 de ATK para cada monstro controlado pelo seu oponente. \r\nEste card perde 500 de ATK para cada outro monstro que você controla.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23314220,'Livro de Magia do Conhecimento',replace(replace('Envie para o Cemitério 1 monstro Mago que você controla ou 1 outro card "Livro de Magia" da sua mão ou com a face para cima no campo, exceto "Livro de Magia do Conhecimento" e, se isso acontecer, compre 2 cards. \r\nVocê só pode ativar 1 "Livro de Magia do Conhecimento" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23323812,'Poder Telepático','Quando um monstro do Tipo Psíquico que você controla for destruído em batalha com um monstro atacante do oponente: escolha o monstro do oponente; destrua o alvo e, se isso acontecer, ganhe PV igual ao ATK que o monstro destruído tinha no campo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23327298,'Seleção Paralela',replace(replace('Só pode ser ativado quando um Monstro Sincro que você controla for destruído por um card do oponente (seja em batalha ou por um efeito de card) e enviado ao Cemitério. \r\nSelecione 1 dos seus Cards de Magia removidos de jogo e adicione-o à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23331400,'Link Streamer',replace(replace('Quando um ou mais monstros Ciberso forem Invocados por Invocação-Normal ou Especial no seu campo enquanto este monstro estiver no campo (exceto durante a Etapa de Dano): você pode Invocar por Invocação-Especial 1 "Ficha de Data" (Ciberso/LUZ/Nível 1/ATK 0/DEF 0). \r\nVocê só pode usar este efeito de "Link Streamer" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23331401,'Ficha de Data','Invocada por Invocação-Especial com o efeito "Link Streamer".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23338098,'Asanegra Agressor - Chidori, o Borrifo de Chuva',replace(replace('1 Regulador + 1 ou mais monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro usando um monstro "Asanegra" como Matéria, ele é considerado como um monstro Regulador enquanto estiver com a face para cima no campo. \r\nEste card ganha 300 de ATK para cada monstro "Asanegra" no seu Cemitério. \r\nQuando este card for destruído e enviado para o Cemitério: você pode escolher 1 Monstro Sincro do Tipo Besta Alada no seu Cemitério, exceto "Asanegra Agressor - Chidori, o Borrifo de Chuva"; Invoque-o por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23361526,'Alta-Velocidaroide Arma de Brinquedo',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro: você pode ativar 1 desses efeitos;\r\n● Adicione 1 Magia/Armadilha "Velocidaroide" do seu Deck à sua mão.\r\n● Se todas as matérias que foram usadas para a Invocação-Sincro deste card eram monstros "Velocidaroide" e estiverem no seu Cemitério, Invoque todas elas por Invocação-Especial.	\r\nVocê não pode Invocar por Invocação-Especial no turno em que ativar este efeito, exceto monstros de VENTO. \r\nVocê só pode usar este efeito de "Alta-Velocidaroide Arma de Brinquedo" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar o efeito escolhido','Procurar no Deck','Matérias de Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23377425,'Cabeça de Ponte Força-S',replace(replace('Quando este card for ativado: você pode adicionar 1 monstro "Força-S" do seu Deck à sua mão. \r\nQuando um monstro do oponente declarar um ataque contra um monstro "Força-S" seu na mesma coluna: você pode ativar este efeito; esse monstro que você controla não pode ser destruído nessa batalha. \r\nVocê só pode usar este efeito de "Cabeça de Ponte Força-S" uma vez por turno. \r\nVocê só pode ativar 1 "Cabeça de Ponte Força-S" por turno.','\r',char(13)),'\n',char(10)),'Adicionar à sua mão 1 monstro "Força-S" do seu Deck?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23377694,'Camarartista Concha do Caranguejo',replace(replace('Escala de Pêndulo = 2\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno, quando um monstro "Camarartista" que você controla for destruído em batalha: você pode escolher 1 card "Camarartista" ou "Olhos Anômalos" na sua Zona de Pêndulo; Invoque-o por Invocação-Especial.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nUma vez por turno: você pode escolher 1 Monstro Pêndulo que você controla; até o final deste turno, ele ganha 300 de ATK para cada monstro "Camarartista" que você controla atualmente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23379054,'Caronte Fantasma, o Barqueiro do Submundo',replace(replace('Se seu oponente controlar um monstro e você não controlar nenhum outro monstro: você pode escolher 1 Monstro de Fusão no seu Cemitério; bana tanto este card do campo quanto o alvo e, se isso acontecer, Invoque por Invocação-Especial 1 Monstro Sincro do Tipo Dragão do seu Deck Adicional cujo Nível seja igual à soma dos Níveis que esses 2 monstros tinham (o Nível original, se ele estava com a face para baixo). \r\nVocê só pode usar este efeito de "Caronte Fantasma, o Barqueiro do Submundo" uma vez por turno. \r\nVocê não pode Invocar monstros por Invocação-Especial no turno em que ativar este efeito, exceto monstros do Tipo Dragão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23384666,'Bugiganga Taniguku, o Intelecto Imóvel',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode pegar 1 monstro Máquina cujo ATK seja igual à sua própria DEF do seu Deck e colocá-lo no topo do seu Deck. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 monstro Máquina no seu Cemitério cujo ATK seja igual à sua própria DEF; Invoque-o por Invocação-Especial em Posição de Defesa. \r\nVocê só pode usar cada efeito de "Bugiganga Taniguku, o Intelecto Imóvel" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Escolha o card a ser colocada no topo do Deck','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23401839,'Senju das Mil Mãos','Quando este card for Invocado por Invocação-Normal ou Virar: você pode adicionar 1 Monstro de Ritual do seu Deck à sua mão.','Adicione à sua mão 1 Monstro Ritual','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23401840,'Senju das Mil Mãos','Quando este card for Invocado por Invocação-Normal ou Virar: você pode adicionar 1 Monstro de Ritual do seu Deck à sua mão.','Adicione à sua mão 1 Monstro Ritual','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23408872,'Batráquio Comerciante',replace(replace('Uma vez por turno, você pode oferecer como Tributo 1 monstro do Tipo Aqua para selecionar 1 monstro "Sapo" no seu Cemitério. \r\nInvoque por Invocação-Especial esse monstro do seu Cemitério.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23421244,'Zumbi Renascido','Enquanto você não tiver cards na sua mão e este card estiver em Posição de Ataque, ele não pode ser destruído em batalha.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23424603,'Terra Árida','Todos os monstros Dinossauro, Zumbi e Rocha no campo ganham 200 de ATK/DEF.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23431858,'Espírito Tenyi - Vishuda',replace(replace('Se você não controlar nenhum Monstro de Efeito: você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe você controlar um Monstro que não seja de Efeito com a face para cima: você pode banir este card da sua mão ou do Cemitério e, depois, escolha 1 card que seu oponente controla; devolva-o para a mão. \r\nVocê só pode usar cada efeito de "Espírito Tenyi - Vishuda" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Retornar um card do seu oponente para a mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23434538,'"C" Maxx',replace(replace('(Efeito Rápido): você pode enviar este card da sua mão para o Cemitério; neste turno, sempre que seu oponente Invocar um ou mais monstros por Invocação-Especial, imediatamente compre 1 card. \r\nVocê só pode usar este efeito de ""C" Maxx" uma vez por turno.','\r',char(13)),'\n',char(10)),'Compre 1 card quando seu oponente Invocar por Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23434539,'"C" Maxx',replace(replace('(Efeito Rápido): você pode enviar este card da sua mão para o Cemitério; neste turno, sempre que seu oponente Invocar um ou mais monstros por Invocação-Especial, imediatamente compre 1 card. \r\nVocê só pode usar este efeito de ""C" Maxx" uma vez por turno.','\r',char(13)),'\n',char(10)),'Compre 1 card quando seu oponente Invocar por Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23440062,'Renascimento Perverso',replace(replace('Ative este card ao pagar 800 PV e, depois, escolha 1 Monstro Sincro no seu Cemitério; Invoque-o por Invocação-Especial em Posição de Ataque. \r\nSeus efeitos são negados e, além disso, ele não pode declarar um ataque neste turno. \r\nQuando este card deixar o campo, destrua esse monstro. \r\nQuando esse monstro for destruído, destrua este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23440231,'Infernoide Devyaty',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão ou do Cemitério) ao banir 3 monstros "Infernoide" da sua mão ou do Cemitério enquanto a soma dos Níveis e das Classes de todos os Monstros de Efeito que você controla for 8 ou menos. \r\nQuando este card for Invocado por Invocação-Especial: você pode destruir todas as Magias e Armadilhas no campo, exceto cards "Vácuo". \r\nUma vez por turno, quando o efeito de outro monstro for ativado (Efeito Rápido): você pode oferecer 1 monstro como Tributo; negue a ativação e, se isso acontecer, bana-o.','\r',char(13)),'\n',char(10)),'Negar o efeito','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23442438,'Perseguição Sincro',replace(replace('Seu oponente não pode ativar cards ou efeitos em resposta às ativações dos efeitos dos seus Monstros Sincro com "Guerreiro(a)", "Sincron" ou "Poeira Estelar" em seus nomes originais. \r\nSe você Invocar por Invocação-Sincro um Monstro Sincro "Guerreiro(a)", "Sincron" ou "Poeira Estelar": você pode escolher 1 monstro no seu Cemitério usado como sua matéria; Invoque-o por Invocação-Especial em Posição de Defesa. \r\nVocê só pode usar este efeito de "Perseguição Sincro" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23446369,'Olho da Ilusão',replace(replace('Se você controlar um monstro Ilusão ou Mago: ative 1 desses efeitos;\r\n● Seus monstros Ilusão e Mago não podem ser destruídos em batalha neste turno.\r\n● Durante o turno do seu oponente: escolha 1 monstro com a face para cima que seu oponente controla; tome o controle dele até a Fase Final.\r\n● Quando um monstro do oponente declarar um ataque: escolha 1 monstro com a face para cima que seu oponente controla, exceto o monstro atacante; mude o alvo do ataque para ele e realize o cálculo de dano.','\r',char(13)),'\n',char(10)),'','Não pode ser destruído em batalha','Tome o controle','Alterar o alvo do ataque','','','','','','','','','','','','');
INSERT INTO texts VALUES(23454876,'CXyz Fada Negra Menina de Torcida',replace(replace('3 monstros de Nível 5	\r\nQuando este card for enviado do campo para o Cemitério: compre 1 card. \r\nSe este card tiver "Fada Menina de Torcida" como uma Matéria Xyz ele ganha este efeito.\r\n● Quando este card destruir um monstro do oponente em batalha e permanecer no campo: você pode desassociar 1 Matéria Xyz deste card; cause 400 de dano ao seu oponente para cada card em sua mão.','\r',char(13)),'\n',char(10)),'Comprar','Causar dano aos PV','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23459650,'Renascimento de Nephthys',replace(replace('Este card pode ser usado para a Invocação-Ritual de qualquer Monstro de Ritual "Nephthys". \r\nVocê também deve oferecer monstros como Tributo da sua mão ou do campo cuja soma dos Níveis seja igual ou exceda o Nível do Monstro de Ritual que você Invocar por Invocação-Ritual. \r\nDepois, se você ofereceu como Tributo "Devota de Nephthys" ou "Cerúlea Fênix Sagrada de Nephthys", você pode destruir 1 card no campo.','\r',char(13)),'\n',char(10)),'Destruir o card?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23469398,'Ginete Aéreo Autômato',replace(replace('Você pode descartar 1 outro monstro "Autômata(o)"; Invoque este card por Invocação-Especial da sua mão. \r\nDurante o turno do seu oponente (Efeito Rápido): você pode escolher 1 monstro Máquina que você controla; Invoque por Invocação-Especial do seu Deck, 1 monstro "Autômata(o)" com um nome diferente e um Nível igual ou menor que o desse monstro e, se isso acontecer, destrua o monstro alvo. \r\nVocê só pode usar cada efeito de "Ginete Aéreo Autômato" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23471572,'Livro de Leis de Salomão','Pule sua própria Fase de Apoio.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23499963,'Observação Springans',replace(replace('Adicione 1 "Grande Mar de Areia - Gold Golgonda" do seu Deck à sua mão. \r\nSe "Grande Mar de Areia - Gold Golgonda" estiver na sua Zona do Campo, em vez disso, você pode aplicar este efeito.\r\n● Adicione 1 monstro "Springans" do seu Deck à sua mão e, se isso acontecer, envie 1 monstro "Springans" do seu Deck para o Cemitério.	\r\nVocê só pode ativar 1 "Observação Springans" por turno.','\r',char(13)),'\n',char(10)),'Adicionar à sua mão 1 monstro "Springans"?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23512906,'Orgulho Dourado - Leon',replace(replace('Se você tiver menos PV que seu oponente: você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 monstro "Orgulho Dourado" que não seja Guerreiro no seu Cemitério; Invoque-o por Invocação-Especial em Posição de Defesa e, além disso, você não pode Invocar monstros por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto monstros "Orgulho Dourado". \r\nDurante a Fase Principal do seu oponente, você pode (Efeito Rápido): imediatamente depois que este efeito resolver, Invocar 1 Monstro Sincro por Invocação-Sincro, usando apenas monstros "Orgulho Dourado" que você controla. \r\nVocê só pode usar cada efeito de "Orgulho Dourado - Leon" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23516703,'Limitar Invocação','Nenhum duelista pode Invocar mais de duas vezes por turno.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23526128,'Descarga de Retorno Blitzclique',replace(replace('Monstros "Blitzclique" que você controla não podem ser destruídos pelos efeitos de card do seu oponente. \r\nVocê só pode usar cada um dos seguintes efeitos de "Descarga de Retorno Blitzclique" uma vez por turno. \r\nQuando seu oponente ativar um Card de Magia ou seus efeitos: você pode devolver 1 monstro "Blitzclique" que você controla para a mão; negue esse efeito e, se isso acontecer, destrua esse card. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 monstro "Blitzclique" no seu campo ou Cemitério; devolva-o para a mão.','\r',char(13)),'\n',char(10)),'','Negar o efeito','Recuperar um monstro','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23530726,'Força Cirúrgica - S.P.E.C.T.R.A.',replace(replace('2+ monstros, incluindo um Monstro Link	\r\n(Este card deve ser sempre considerado como um card "Força Celeste - Ás".)	\r\nPrimeiro deve ser Invocado por Invocação-Link. \r\nPerde 3000 de ATK enquanto você não tiver Magias no seu Cemitério. \r\nQuando seu oponente ativar um card ou efeito como Elo de Corrente 2 ou mais (Efeito Rápido): você pode banir 2 Magias da sua mão e/ou do Cemitério; negue o efeito e, depois, você pode destruir 1 card que seu oponente controla. \r\nVocê só pode usar este efeito de "Força Cirúrgica - S.P.E.C.T.R.A." uma vez por turno.','\r',char(13)),'\n',char(10)),'Negar o efeito','Destruir 1 card que seu oponente controla?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23535429,'Guardião da Fortaleza','Se um monstro em Posição de Defesa que você controla for atacado, você pode enviar este card da sua mão ao Cemitério durante a Etapa de Dano para fazer com que seu monstro atacado ganhe 1500 de DEF até a Fase Final.','Aumentar DEF','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23536866,'Tubarão Observador',replace(replace('Você pode banir este card do seu Cemitério e, depois, escolher 2 monstros de ÁGUA de Nível 5 no seu Cemitério, exceto "Tubarão Observador"; Invoque os dois monstros por Invocação-Especial, mas seus efeitos são negados. \r\nImediatamente depois de resolver este efeito, Invoque por Invocação-Xyz 1 Monstro Xyz de ÁGUA usando apenas esses 2 monstros. \r\nVocê só pode usar este efeito de "Tubarão Observador" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23545031,'Sirena Abissalácia',replace(replace('2 monstros Peixe, Serpente Marinha e/ou Aqua	\r\nMonstros para o qual este card apontar ganham 500 de ATK/DEF. \r\nVocê só pode usar cada um dos seguintes efeitos de "Sirena Abissalácia" uma vez por turno.\r\n● Durante o turno do seu oponente (Efeito Rápido): você pode enviar 1 card da sua mão para o Cemitério; adicione 1 monstro "Sirena" do seu Deck à sua mão.\r\n● Se este card em posse do seu dono for destruído por um ataque ou efeito de card do oponente: você pode enviar 1 monstro de ÁGUA do seu Deck para o Cemitério e, depois, escolher 1 monstro de ÁGUA no seu Cemitério; Invoque-o por Invocação-Especial em Posição de Defesa.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23557835,'Fusão de Dimensões','Pague 2000 PV; cada duelista Invoca por Invocação-Especial tantos dos seus monstros banidos quanto possível.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23558733,'Amarílis de Aglomerado Feníxico',replace(replace('Este card não pode ser Invocado por Invocação-Especial, exceto com seu próprio efeito ou com "Semente Feníxica". \r\nSe este card atacar, ele é destruído depois do cálculo de dano. \r\nSe este card que você controla for destruído e enviado para o Cemitério, cause 800 de dano ao seu oponente. \r\nDurante sua Fase Final, você pode remover de jogo 1 monstro Planta do seu Cemitério para Invocar este card por Invocação-Especial do seu Cemitério em Posição de Defesa.','\r',char(13)),'\n',char(10)),'Cause 800 de dano ao seu oponente','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23562407,'Armas Nobres - Caliburn',replace(replace('Você só pode controlar 1 "Armas Nobres - Caliburn". \r\nSó pode equipar um monstro do Tipo Guerreiro. \r\nEle ganha 500 de ATK. \r\nUma vez por turno: você ganha 500 PV. \r\nSe este card no campo com a face para cima for destruído e enviado para o Cemitério: você pode escolher 1 monstro "Nobre Cavaleiro" do Tipo Guerreiro que você controla; equipe este card no alvo. \r\nVocê só pode usar este efeito de "Armas Nobres - Caliburn" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ganhar PV','Equipar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23571046,'Ouriço Parafusado',replace(replace('Se este card estiver no seu Cemitério: você pode Invocar este card por Invocação-Especial, mas bana-o quando ele deixar o campo. \r\nVocê deve controlar um Regulador para ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23581825,'Magia de Aumento de Classe Força da Alma Cortante',replace(replace('Pague metade dos seus PV e, depois, escolha 1 Monstro Xyz "Ataqueraptor" no seu Cemitério; Invoque-o por Invocação-Especial e, depois, Invoque por Invocação-Especial do seu Deck Adicional, 1 Monstro Xyz que seja 2 Classes maior que esse monstro, usando-o como Matéria Xyz. \r\n(Esta Invocação-Especial é considerada uma Invocação-Xyz.)','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23587624,'Um Monstro Selvagem Aparece!',replace(replace('Se somente seu oponente controlar um monstro: Invoque por Invocação-Especial da sua mão, 1 monstro com um Nível original de 10 ou menos que não possa ser Invocado por Invocação-Normal/Baixado, ignorando suas condições de Invocação. \r\nEle não é afetado pelos efeitos dos seus cards, exceto por seus próprios efeitos e os deste card e, além disso, embaralhe-o no Deck durante a próxima Fase Final do seu oponente. \r\nPelo resto deste turno, você não pode Invocar por Invocação-Normal/Baixar nem Invocar monstros por Invocação-Especial e seu oponente não sofre dano.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23599634,'Pacto de Artmage -Despertar-',replace(replace('Invoque por Invocação-Especial 1 monstro "Artmage" ou 1 "Medius, o Puro" do seu Deck e, além disso, pelo resto deste turno, a ativação dos seus cards e efeitos que incluam um efeito que Invoque um Monstro de Fusão por Invocação-Fusão não pode ser negada e, além disso, seu oponente não pode ativar cards ou efeitos quando um monstro for Invocado por Invocação-Fusão desta forma. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 monstro "Artmage" que você controla; devolva esse monstro para a mão/Deck Adicional e, se isso acontecer, destrua 1 card que seu oponente controla. \r\nVocê só pode usar 1 efeito de "Pacto de Artmage -Despertar-" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar','Recuperar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23603403,'Ataqueraptor - Falcão Canhão Satélite',replace(replace('2 monstros Besta Alada de Nível 8	\r\nSe este card for Invocado por Invocação-Xyz ao usar um monstro "Ataqueraptor" como matéria: você pode destruir todas as Magias e Armadilhas que seu oponente controla. \r\nSeu oponente não pode ativar cards ou efeitos em resposta à ativação deste efeito. \r\n(Efeito Rápido): você pode desassociar 1 matéria deste card e, depois, escolha 1 monstro com a face para cima que seu oponente controla; ele perde 800 de ATK para cada monstro "Ataqueraptor" no seu Cemitério.','\r',char(13)),'\n',char(10)),'Destruir Magias/Armadilhas','Reduzir ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23611122,'Pântano do Trovão Repentino',replace(replace('Quando este card for ativado: você pode descartar 1 card e, se isso acontecer, Baixe 1 Armadilha Contínua do seu Deck ou Cemitério, com um efeito que Invoque a si mesma por Invocação-Especial como um monstro, exceto o card descartado. \r\nSe um ou mais cards que você controla forem destruídos em batalha ou por um efeito de card, e enviados para o Cemitério ou banidos com a face para cima: você pode escolher 1 deles; adicione 1 card com o mesmo nome do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Pântano do Trovão Repentino" uma vez por turno. \r\nVocê só pode ativar 1 "Pântano do Trovão Repentino" por turno.','\r',char(13)),'\n',char(10)),'Ativar','Descartar 1 card e Baixar 1 Armadilha?','Adicionar à mão','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23615409,'Barreira de Insetos','Monstros Inseto que seu oponente controla não podem declarar ataques.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23617756,'Fogo da Fúria de Exxod',replace(replace('(Este card deve ser sempre considerado como um card "Exodd" e "Obliterar!!!".)	\r\nSe você controlar um monstro "Exodia" de Nível 10 ou mais: destrua todos os cards que seu oponente controla. \r\nSe este card estiver no seu Cemitério, exceto no turno em que foi enviado para lá: você pode bani-lo e, depois, ative 1 desses efeitos;\r\n● Adicione 1 monstro "O Proibido" do seu Deck ou Cemitério à sua mão.\r\n● Embaralhe no Deck até 5 monstros "O Proibido" do seu Cemitério e/ou banimento.	\r\nVocê só pode usar cada efeito de "Fogo da Fúria de Exxod" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Adicionar à mão 1 monstro "O Proibido"','Recupere 1 monstro "O Proibido"','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23619206,'Simorgh, Pássaro da Calamidade',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode enviar 1 card "Simorgh" do seu Deck para o Cemitério, exceto "Simorgh, Pássaro da Calamidade". \r\nSe este card estiver no seu Cemitério e seu oponente não controlar nenhum card na Zona de Magias & Armadilhas dele: você pode Invocar este card por Invocação-Especial em Posição de Defesa, mas bana-o quando ele deixar o campo e, além disso, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros Besta Alada. \r\nVocê só pode usar cada efeito de "Simorgh, Pássaro da Calamidade" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23623653,'Domador Avatar da Besta Espiritual Lara',replace(replace('(Este card deve ser sempre considerado como um card "Domador da Besta Espiritual".)	\r\nVocê só pode Invocar um ou mais "Domador Avatar da Besta Espiritual Lara" por Invocação-Especial uma vez por turno. \r\nVocê pode descartar este card; imediatamente depois que este efeito resolver, Invoque por Invocação-Normal 1 monstro "Besta Espiritual" da sua mão. \r\nSe um ou mais cards "Besta Espiritual" que você controla seriam destruídos em batalha ou por um efeito de card, em vez disso, você pode banir este card do seu campo ou Cemitério. \r\nSe este card for banido: você pode Invocar por Invocação-Especial 1 monstro "Besta Espiritual" do seu Deck, exceto "Domador Avatar da Besta Espiritual Lara". \r\nVocê só pode usar cada efeito de "Domador Avatar da Besta Espiritual Lara" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar 1 monstro "Besta Espiritual"','Invocar por Invocação Especial do Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23626223,'Estátua do Padrão Angustiante',replace(replace('Invoque este card por Invocação-Especial como um Monstro de Efeito (Rocha/TERRA/Nível 7/ATK 0/DEF 2500) (este card ainda é considerado uma Armadilha). \r\nSe Invocado desta forma, seu oponente não pode escolher este card como alvo de efeitos de card enquanto outro Card de Armadilha que seja um monstro estiver na Zona de Monstros. \r\nSe um ou mais cards forem Invocados por Invocação-Especial da sua Zona de Magias & Armadilhas para a Zona de Monstros, enquanto você controlar este card Invocado desta forma (exceto durante a Etapa de Dano): você pode escolher 1 card no campo; destrua-o.','\r',char(13)),'\n',char(10)),'Destruir 1 card','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23635815,'Jerry, Homem Feijão','Jerry, um soldado feijão, acredita que é o mais forte guerreiro do mundo, mas as suas verdadeiras habilidades ainda não foram testadas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23639291,'Nuviano Devastador','Quando um ou mais monstros "Nuviano" que você controla forem destruídos por seu próprio efeito e enviados para o seu Cemitério: escolha 1 desses monstros; Invoque-o por Invocação-Especial em Posição de Ataque e, se isso acontecer, coloque 1 Marcador de Névoa nele e, além disso, ele não pode ser colocado em Posição de Defesa por efeitos de card.','O efeito de "Nuviano Devastador" está sendo aplicado.','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23649496,'Número 18: Patriarca Heráldico',replace(replace('2 monstros de Nível 4	\r\nUma vez por Corrente, se 2 ou mais monstros com o mesmo nome estiverem no campo (Efeito Rápido): você pode desassociar 1 matéria deste card; selecione 1 monstro entre esses com o mesmo nome e destrua todos os outros monstros com esse nome. \r\nSeu oponente não pode Invocar monstros com o mesmo nome que qualquer um dos monstros selecionados pelo efeito deste card. \r\nSe este card for enviado para o Cemitério: você pode enviar 2 monstros "Besta Heráldica" do seu Deck para o Cemitério.','\r',char(13)),'\n',char(10)),'Destruir','Enviar para o Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23656668,'Controlador da Gravidade',replace(replace('1 Monstro que não seja Link em uma Zona de Monstros Adicional	\r\nNão pode ser usado como Matéria Link no turno em que for Invocado por Invocação-Link. \r\nEste card na Zona de Monstros Adicional não pode ser destruído em batalha com um monstro na Zona de Monstros Principal. \r\nNo começo da Etapa de Dano, se este card batalhar um monstro do oponente na Zona de Monstros Adicional: você pode devolver tanto esse monstro do oponente quanto este card para o Deck.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23657016,'Dragão Tenpai Genroku',replace(replace('Se este card for adicionado à sua mão, exceto ao comprá-lo: você pode Invocar este card por Invocação-Especial como um Regulador e, depois, você pode aumentar seu Nível em 1. \r\n(Efeito Rápido): você pode oferecer este card como Tributo; Invoque por Invocação-Especial 1 monstro "Dragão Tenpai" do seu Deck, exceto "Dragão Tenpai Genroku" e, além disso, você não pode Invocar por Invocação-Especial pelo resto deste turno, exceto monstros Dragão. \r\nVocê só pode usar cada efeito de "Dragão Tenpai Genroku" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial e aumentar o Nível','Invocação Especial','Aumentar o Nível?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23659124,'Dragão Rei dos Mares','Protegido por uma carapaça dura, este mestre do mar ataca os seus inimigos com bolhas tóxicas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23672629,'Tubarão Lanceiro Destemido',replace(replace('2 monstros de Nível 5	\r\nVocê pode escolher 1 monstro que seu oponente controla; desassocie 1 matéria de um Monstro Xyz que você controla e, se isso acontecer, destrua esse monstro. \r\nEste é um Efeito Rápido se você controlar outro Monstro Xyz de ÁGUA. \r\nSe um ou mais outros Monstros Xyz de ÁGUA que você controla forem destruídos em batalha ou por um efeito de card enquanto você controlar este monstro: você pode colocar 1 Magia do seu Deck no topo do seu Deck. \r\nVocê só pode usar cada efeito de "Tubarão Lanceiro Destemido" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Escolha o(s) card(s) para colocar no topo do Deck','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23681456,'Magidocepalooza','Invoque por Invocação-Especial qualquer número de monstros "Magidoce" da sua mão, mas embaralhe-os no Deck durante a Fase Final.','O efeito de "Magidocepalooza" está sendo aplicado.','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23689428,'Golias Infinisteira',replace(replace('1 monstro "Infinisteira" que não seja Link	\r\nSe este card for enviado do campo para o Cemitério: você pode escolher 1 Monstro Xyz que você controla; associe este card a esse monstro como matéria. \r\nVocê só pode usar este efeito de "Golias Infinisteira" uma vez por turno. \r\nUm Monstro Xyz cujo Tipo original seja Máquina e que tenha este card como matéria ganha este efeito.\r\n● Este card não pode ser destruído por efeitos de card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23689697,'Mobius, o Mega Monarca',replace(replace('Você pode Invocar este card por Invocação-Tributo ao oferecer como Tributo 1 monstro Invocado por Invocação-Tributo. \r\nQuando este card for Invocado por Invocação-Tributo: você pode escolher até 3 Cards de Magia/Armadilha no campo; destrua os alvos. \r\nSe este card foi Invocado por Invocação-Tributo pelo Tributo de um monstro de ÁGUA, adicione este efeito adicional.\r\n● Seu oponente não pode ativar os cards escolhidos em resposta à ativação deste efeito.','\r',char(13)),'\n',char(10)),'Ofereça 1 monstro Invocado por Invocação Tributo para realizar uma Invocação Tributo','Destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23693634,'Lutador Colossal',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nGanha 100 de ATK para cada monstro Guerreiro nos Cemitérios. \r\nQuando este card for destruído em batalha e enviado para o Cemitério: você pode escolher 1 monstro Guerreiro em qualquer Cemitério; Invoque o alvo por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23701465,'Semente Primária','Se houver "Soldado do Lustro Negro - Enviado do Princípio" ou "Dragão Imperador do Caos - Enviado do Fim" no campo: escolha 2 dos seus cards banidos; adicione os dois alvos à sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23720856,'Zubababancho Gagagacasaco',replace(replace('Se você controlar um monstro "Zubaba" ou "Gagaga" exceto "Zubababancho Gagagacasaco", enquanto este card estiver na sua mão: você pode Invocar este card por Invocação-Especial. \r\nVocê pode escolher 1 monstro "Gogogo" ou "Dododo" no seu Cemitério; Invoque-o por Invocação-Especial e, além disso, você não pode Invocar monstros por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto Monstros Xyz. \r\nVocê só pode usar cada efeito de "Zubababancho Gagagacasaco" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23732205,'Dragão Pewrigoso',replace(replace('2 monstros Dragão de TREVAS	\r\nUma vez por turno, durante a Fase Final do seu oponente: você pode escolher 1 monstro em Posição de Ataque que seu oponente controla que não declarou um ataque neste turno; destrua-o e, se isso acontecer, cause dano ao seu oponente igual ao ATK original desse monstro. \r\nSe um ou mais monstros "Foguette" forem Invocados por Invocação-Especial no seu campo, enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar cada efeito de "Dragão Pewrigoso" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23738096,'Soldado de Abastecimento dos Insetos Indestrutíveis',replace(replace('Quando um efeito de um monstro Inseto for ativado (Efeito Rápido): você pode Invocar este card por Invocação-Especial da sua mão e, depois, se você ativou este efeito em resposta à ativação de um efeito do seu oponente, negue o efeito e, além disso, até o final do seu próximo turno depois que este efeito resolver, você não pode Invocar por Invocação-Especial do Deck Adicional, exceto monstros Inseto. \r\nDurante sua Fase Principal: você pode Invocar por Invocação-Fusão 1 Monstro de Fusão Inseto do seu Deck Adicional, usando monstros da sua mão ou do campo. \r\nVocê só pode usar cada efeito de "Soldado de Abastecimento dos Insetos Indestrutíveis" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Invocação Fusão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23740893,'Yosenju Kodam',replace(replace('Você pode oferecer este card como Tributo e, depois, escolher 1 "Campo de Treinamento Yosen" que você controla; coloque 3 Marcadores Yosen nele. \r\nVocê só pode usar este efeito de "Yosenju Kodam" uma vez por turno. \r\nVocê pode banir este card do seu Cemitério; você pode Invocar por Invocação-Normal 1 monstro "Yosenju" durante sua Fase Principal neste turno, em adição à sua Invocação-Normal/Baixar padrão. \r\n(Você só pode se aproveitar deste efeito uma vez por turno.)','\r',char(13)),'\n',char(10)),'Colocar um marcador','Invocar pelo efeito de "Yosenju Kodam"','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23746827,'Prisão de Gelo de Um Milhão de Séculos',replace(replace('Durante a Fase Principal, se um ou mais monstros que você controla deixarem o campo por um efeito de monstro do oponente, exceto ao serem destruídos: ative 1 desses efeitos;\r\n● Termine a Fase Principal.\r\n● Pule a Fase Principal 1 do próximo turno do seu oponente.	\r\nVocê só pode ativar 1 "Prisão de Gelo de Um Milhão de Séculos" por turno.','\r',char(13)),'\n',char(10)),'','Terminar esta Fase Principal','Pule a Main Phase 1 do próximo turno do seu oponente','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23756165,'Rainha Cativante LV5',replace(replace('Uma vez por turno, se você controlar este card que foi Invocado por Invocação-Especial pelo efeito de "Rainha Cativante LV3": você pode escolher 1 monstro de Nível 5 ou menos que seu oponente controla; equipe o alvo a este card como uma Magia de Equipamento (máx. 1). \r\nSe este card seria destruído em batalha, em vez disso, destrua esse monstro equipado a ele. \r\nDurante sua Fase de Apoio: você pode enviar este card equipado com um monstro pelo efeito deste card para o Cemitério; Invoque por Invocação-Especial 1 "Rainha Cativante LV7" da sua mão ou do Deck.','\r',char(13)),'\n',char(10)),'Equipar','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23770284,'Forte Dragão do Vento',replace(replace('Não pode ser destruído em batalha por um monstro que tenha o mesmo ATK. \r\nSe este card for Invocado por Invocação-Tributo pelo Tributo de um monstro do Tipo Dragão: ele ganha ATK igual à metade do ATK original do monstro oferecido como Tributo. \r\nSe este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23771716,'Peixe de 7 Cores','Um raro peixe arco-íris que nunca foi apanhado por homens mortais.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23776077,'Basiltrice da Chama Nebulosa',replace(replace('2 ou mais (máx. 5) monstros de FOGO de Nível 6	\r\nUma vez por turno: você pode desassociar 1 Matéria Xyz deste card para escolher 1 monstro que seu oponente controla ou no Cemitério dele; bana o alvo. \r\nEste card ganha efeitos de acordo com o número de Matérias Xyz associadas a ele.\r\n● 3 ou mais: Este card ganha 200 de ATK e DEF para cada Matéria Xyz associada a ele.\r\n● 4 ou mais: Este card não pode ser alvo de efeitos de card do seu oponente.\r\n● 5: Este card não pode ser destruído por efeitos de card.','\r',char(13)),'\n',char(10)),'Banir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23782705,'Franco-atirador Autômato','Monstros não podem atacar monstros "Autômata(o)", exceto "Franco-atirador Autômato".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23784496,'Script do Abismo - Cerimônia de Abertura',replace(replace('Ganhe 500 PV para cada monstro "Ator do Abismo" que você controla. \r\nSe este card Baixado sob o controle do seu dono for destruído por um efeito de card do oponente e você tiver um Monstro Pêndulo "Ator do Abismo" com a face para cima no seu Deck Adicional: você pode comprar até ter 5 cards na sua mão. \r\nVocê só pode usar cada efeito de "Script do Abismo - Cerimônia de Abertura" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23790299,'Memorygant Altergeist',replace(replace('2+ monstros "Altergeist"	\r\nDurante a Fase de Batalha (Efeito Rápido): você pode oferecer como Tributo 1 outro monstro; este card ganha ATK igual ao ATK desse monstro oferecido como Tributo no campo. \r\nQuando este card destruir um monstro em batalha: você pode destruir 1 monstro que seu oponente controla e, se isso acontecer, este card pode realizar um segundo ataque em seguida. \r\nSe este card seria destruído, em vez disso, você pode banir 1 monstro do seu Cemitério. \r\nVocê só pode usar cada efeito de "Memorygant Altergeist" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23792058,'Velocidaroide Hexadisco',replace(replace('Escala de Pêndulo = 6\r\n[ Efeito de Pêndulo ]\r\nVocê pode escolher 1 dos seus Monstros Sincro de VENTO que estiverem banidos ou no seu Cemitério; devolva-o para o Deck Adicional. \r\nVocê só pode usar este efeito de "Velocidaroide Hexadisco" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nOs dois duelistas sofrem qualquer dano de batalha dos ataques envolvendo este card. \r\nQualquer dano de batalha das batalhas envolvendo este card são diminuídos pela metade. \r\nSe este card for destruído na Zona de Pêndulo: você pode Invocar por Invocação-Especial com a face para cima 1 Monstro Pêndulo "Velocidaroide" do seu Deck Adicional.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23804920,'Besta Escorpião Divina de Serket',replace(replace('1 monstro "Serket" + 1 monstro com 2500 ou menos de ATK	\r\nSe este card for Invocado por Invocação-Especial, ou se este card batalhar um monstro do oponente no começo da Etapa de Dano: você pode escolher 1 monstro com a face para cima que seu oponente controla ou no Cemitério dele; bana-o e, se isso acontecer, este card ganha ATK igual à metade do ATK original do monstro banido. \r\nVocê só pode usar este efeito de "Besta Escorpião Divina de Serket" uma vez por turno. \r\nPode realizar um segundo ataque durante cada Fase de Batalha, enquanto um monstro de Nível 10 ou mais estiver banido.','\r',char(13)),'\n',char(10)),'Banir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23812568,'Espelho Adicional Nível 7','Se um ou mais monstros de Nível 7 forem Invocados por Invocação-Especial no seu campo: envie 2 "Espelho Adicional Nível 7" da sua mão e/ou do Deck para o Cemitério e, depois, escolha 1 desses monstros; Invoque por Invocação-Especial do seu Deck 2 monstros com o mesmo nome que do alvo e, depois, sofra dano igual ao ATK original combinado deles e, além disso, pelo resto deste turno depois que este card resolver, você só pode Invocar por Invocação-Especial do Deck Adicional uma vez.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23829452,'Patrono do Poder de Artmage',replace(replace('Você não pode Invocar por Invocação-Especial do Deck Adicional, exceto Monstros de Fusão. \r\nVocê só pode usar cada um dos seguintes efeitos de "Patrono do Poder de Artmage" uma vez por turno. \r\nDurante a Fase Principal (Efeito Rápido): você pode Invocar por Invocação-Fusão 1 Monstro de Fusão "Artmage" ou 1 "Nerva, a Patrona do Poder da Criação" do seu Deck Adicional, usando este card que você controla e monstros da sua mão ou do campo. \r\nSe este card for enviado da mão ou do campo para o Cemitério: você pode adicionar 1 Magia/Armadilha "Artmage" do seu Deck à sua mão, com um nome diferente que o dos cards no seu Cemitério.','\r',char(13)),'\n',char(10)),'Invocação Fusão','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23837054,'Chamado Ogdoádico',replace(replace('Invoque por Invocação-Especial 2 "Ficha de Ogdoádico" (Réptil/TREVAS/Nível 2/ATK 0/DEF 0), OU se você tiver 8 ou mais monstros "Ogdoádico(a)" com nomes diferentes no seu Cemitério, em vez disso, você pode aplicar este efeito.\r\n● Invoque por Invocação-Especial 2 monstros Réptil com nomes diferentes do seu Cemitério.	\r\nVocê só pode ativar 1 "Chamado Ogdoádico" por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial um monstro do seu Cemitério?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23837055,'Ficha de Ogdoádico','Invocado por Especial com o efeito "Chamado Ogdoádico".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23842445,'Unidade Nitro',replace(replace('Você pode equipar este card apenas a um monstro no Campo do seu adversário. \r\nQuando um monstro destrói o monstro equipado como resultado de um combate e o envia para o Cemitério, inflija dano aos Life Points do seu adversário igual ao ATK do monstro equipado.','\r',char(13)),'\n',char(10)),'Causar dano aos PV','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23846921,'Força Arcana XXI - O Mundo',replace(replace('Quando este card for Invocado: lance uma moeda.\r\n● Cara: Uma vez por turno, durante sua Fase Final: você pode enviar 2 monstros que você controla para o Cemitério; pule o próximo turno do seu oponente.\r\n● Coroa: Uma vez por turno, durante a Fase de Compra do seu oponente: adicione o card do topo do Cemitério dele à mão dele.','\r',char(13)),'\n',char(10)),'Jogar uma moeda','Pular o turno do seu oponente','Recuperar','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23848752,'Campeão Heroico - Jarngreipr',replace(replace('2 monstros Guerreiro de Nível 1	\r\nNa primeira vez que cada monstro Guerreiro que você controla seria destruído em batalha ou por um efeito de card a cada turno, ele não é destruído. \r\nVocê só pode usar cada um dos seguintes efeitos de "Campeão Heroico - Jarngreipr" uma vez por turno. \r\nVocê pode desassociar 2 matérias deste card e, depois, escolha 1 monstro Guerreiro de Nível/Classe 4 no seu Cemitério; Invoque-o por Invocação-Especial e, se isso acontecer, este card ganha ATK igual ao ATK original desse monstro. \r\nQuando um ataque for declarado envolvendo um monstro do seu oponente: você pode ganhar PV igual à metade do ATK dele.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23850421,'Wivern Jack',replace(replace('Você pode banir este card e 1 monstro Máquina com a face para cima que você controla e, depois, escolher 1 monstro de TREVAS no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê só pode usar este efeito de "Wivern Jack" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23851033,'Dragão da Gravidade de Olhos Anômalos',replace(replace('Você pode Invocar este card por Invocação-Ritual com "Advento do Olhos Anômalos". \r\nQuando este card for Invocado por Invocação-Especial: você pode devolver todas as Magias e Armadilhas que seu oponente controla para a mão. \r\nSeu oponente não pode ativar cards ou efeitos em resposta à ativação deste efeito. \r\nVocê só pode usar este efeito de "Dragão da Gravidade de Olhos Anômalos" uma vez por turno. \r\nSeu oponente deve pagar 500 PV para ativar efeitos de card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23856331,'Inferno das Bestas Sagradas - Uria, o Senhor das Chamas Cortantes',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial com o efeito de um card "Bestas Sagradas". \r\nVocê pode revelar este card na sua mão; adicione 1 Armadilha "Bestas Sagradas" do seu Deck à sua mão e, depois, descarte 1 card. \r\nVocê só pode usar este efeito de "Inferno das Bestas Sagradas - Uria, o Senhor das Chamas Cortantes" uma vez por turno. \r\nGanha 1000 de ATK/DEF para cada Armadilha nos Cemitérios. \r\nUma vez por turno (Efeito Rápido): você pode escolher 1 Magia/Armadilha no campo; destrua-a. \r\nNenhum duelista pode ativar cards ou efeitos em resposta à ativação deste efeito.','\r',char(13)),'\n',char(10)),'Efeito de busca','Efeito de destruição','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23857661,'Raposa Bujingi','Durante o turno de qualquer duelista: você pode banir este card do seu Cemitério e enviar 1 monstro "Bujin" da sua mão para o Cemitério; você não sofre dano neste turno.','O dano se torna 0','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23869735,'Escavação de Fósseis',replace(replace('Ative este card ao descartar 1 card e, depois, escolha 1 monstro do Tipo Dinossauro no seu Cemitério; Invoque o alvo por Invocação-Especial. \r\nNegue os efeitos desse monstro no campo. \r\nQuando este card deixar o campo, destrua esse monstro. \r\nQuando esse monstro for destruído, destrua este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23874409,'Shogun Karakuri mdl 00 "Burei"',replace(replace('1 Regulador + 1 ou mais monstros não-Reguladores do Tipo Máquina	\r\nQuando este card for Invocado por Invocação-Sincro: você pode Invocar por Invocação-Especial 1 monstro "Karakuri" do seu Deck. \r\nUma vez por turno: você pode escolher 1 monstro no campo; mude sua posição de batalha.','\r',char(13)),'\n',char(10)),'Invocação Especial','Mudar a posição de batalha','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23893227,'Núcleo de Dragão Cibernético',replace(replace('O nome deste card se torna "Dragão Cibernético" enquanto estiver no campo ou no Cemitério. \r\nSe este card for Invocado por Invocação-Normal: adicione 1 Magia/Armadilha "Ciber" do seu Deck à sua mão. \r\nSe somente seu oponente controlar um monstro: você pode banir este card do seu Cemitério; Invoque por Invocação-Especial 1 monstro "Dragão Cibernético" do seu Deck. \r\nVocê só pode usar 1 efeito de "Núcleo de Dragão Cibernético" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23898021,'Lilith, a Dama da Lamentação',replace(replace('Se este card for Invocado por Invocação-Normal, seu ATK original se torna 1000. \r\n(Efeito Rápido): você pode oferecer como Tributo 1 monstro de TREVAS; revele 3 Armadilhas Normais do seu Deck, seu oponente seleciona aleatoriamente 1 para você Baixar no seu campo, e você embaralha o resto de volta no seu Deck. \r\nVocê só pode usar este efeito de "Lilith, a Dama da Lamentação" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23899727,'Sirena Abislinda',replace(replace('Se este card no campo for destruído e enviado para o Cemitério: você pode Invocar por Invocação-Especial 1 monstro "Sirena" do seu Deck, exceto "Sirena Abislinda". \r\nVocê só pode usar este efeito de "Sirena Abislinda" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23912837,'Encarnação Sombraneco Resh',replace(replace('Escolha 1 monstro "Sombraneco" no seu Cemitério; Invoque-o por Invocação-Especial com a face para cima ou com a face para baixo em Posição de Defesa.\r\nVocê pode banir este card e 1 card "Sombraneco" do seu Cemitério e, depois, ative 1 desses efeitos;\r\n● Coloque 1 monstro com a face para baixo que você controla, com a face para cima em Posição de Defesa.\r\n● Coloque 1 monstro com a face para cima que você controla, com a face para baixo em Posição de Defesa.	\r\nVocê só pode usar 1 efeito de "Encarnação Sombraneco Resh" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Ativar o efeito escolhido','Mude 1 monstro com a face para baixo para Posição de Defesa com a face para cima','Mude 1 monstro com a face para cima para Posição de Defesa com a face para baixo','','','','','','','','','','','','');
INSERT INTO texts VALUES(23915499,'Papa-Bugs Y',replace(replace('Quando este card for Invocado por Invocação-Normal: Você pode Invocar por Invocação-Especial 1 "Papa-Bugs X" do seu Deck. \r\nVocê deve controlar um "Papa-Bugs Z" com a face para cima para ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23920796,'Cérbero Mimicarniçal',replace(replace('VIRE: Se for a Fase Principal: aplique esses efeitos em sequência.\r\n● Bana os 3 cards do topo do seu Deck e, depois, Invoque por Invocação-Especial 1 dos seus monstros banidos no campo do seu oponente em Posição de Defesa.\r\n● Conceda o controle deste card ao seu oponente.	\r\nDurante sua Fase Principal: você pode Invocar este card por Invocação-Especial da sua mão no campo do seu oponente com a face para baixo em Posição de Defesa. \r\nVocê só pode usar cada efeito de "Cérbero Mimicarniçal" uma vez por turno. \r\nSeu oponente não pode escolher Magias com a face para cima que você controla como alvo de efeitos de card.','\r',char(13)),'\n',char(10)),'Efeito de Virar','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23923758,'Cavaleiro a Vapor - Hamburk','Um dos cavaleiros, ele está equipado com a "Armadura BFS", feita de um aço denso cuidadosamente refinado na fábrica, e "Foil-Packer", um mecanismo especial que pode ser convertido em várias armas dependendo do estado de combate, graças à sua ligação com o altamente analítico "Coc-OS". Embora "Hamburk" esteja equipado com o conjunto usual de equipamentos, ele é incrivelmente popular devido ao seu estilo de combate ser extremamente calórico. Seu poder é ainda mais fortalecido pelas bênçãos da deusa "Madera".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23923759,'Cavaleiro a Vapor - Hamburk','Um dos cavaleiros, ele está equipado com a "Armadura BFS", feita de um aço denso cuidadosamente refinado na fábrica, e "Foil-Packer", um mecanismo especial que pode ser convertido em várias armas dependendo do estado de combate, graças à sua ligação com o altamente analítico "Coc-OS". Embora "Hamburk" esteja equipado com o conjunto usual de equipamentos, ele é incrivelmente popular devido ao seu estilo de combate ser extremamente calórico. Seu poder é ainda mais fortalecido pelas bênçãos da deusa "Madera".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23924608,'Tempestade Pesada de Pó',replace(replace('Escolha até 2 Magias/Armadilhas no campo; destrua-as. \r\nVocê não pode conduzir sua Fase de Batalha no turno em que ativar este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23927545,'Jurrac Protops','Ganha 100 de ATK para cada monstro que seu oponente controla.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23927567,'Uma Coruja de Sorte',replace(replace('VIRE: Escolha 1 Card de Magia de Campo do seu Deck e coloque-o no topo do seu Deck. \r\nSe "Necro-Vale" estiver no Campo com a face para cima, você pode adicionar o card escolhido à sua mão.','\r',char(13)),'\n',char(10)),'Colocar no topo do Deck','Escolha uma Magia de Campo','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23931679,'Dragão Senhor do Oceano - Kairyu-Shin',replace(replace('Enquanto "Umi" estiver no campo, cada duelista só pode controlar 1 monstro que não seja de ÁGUA com a face para cima. \r\n(Se um duelista controlar 2 ou mais, ele deve enviar algum(ns) para o Cemitério até controlar apenas 1.) Durante sua Fase Principal: você pode adicionar do seu Deck à sua mão 1 "Umi", 1 Magia/Armadilha "Kairyu-Shin" ou 1 Magia/Armadilha "Furtivo do Mar". \r\nVocê só pode usar este efeito de "Dragão Senhor do Oceano - Kairyu-Shin" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23935886,'Draco Mestres dos Tenyi',replace(replace('2+ monstros, incluindo um Monstro Link	\r\nNão pode ser destruído em batalha com um Monstro de Efeito. \r\nSe você não controlar nenhum outro Monstro de Efeito: você pode destruir Monstros de Efeito que seu oponente controla, até o número de Monstros que não sejam de Efeito que você controla e/ou no seu Cemitério. \r\nVocê só pode usar este efeito de "Draco Mestres dos Tenyi" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23950192,'Criomante da Barreira de Gelo','Enquanto você controlar outro monstro "Barreira de Gelo", os monstros de Nível 4 ou mais não podem declarar ataques.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23965033,'Augusta Amazoness',replace(replace('1 Monstro de Fusão "Amazoness" + 1 monstro "Amazoness"	\r\nSeu oponente não pode escolher outros cards "Amazoness" que você controla como alvo de efeitos de card e, além disso, esses cards não podem ser destruídos pelos efeitos de card do seu oponente. \r\nSe este card foi Invocado por Invocação-Fusão usando "Imperatriz Amazoness" ou "Rainha Amazoness" como matéria, ele pode realizar um segundo ataque durante cada Fase de Batalha. \r\nSe este card for Invocado por Invocação-Fusão: você pode Invocar por Invocação-Especial 1 monstro "Amazoness" do seu Deck. \r\nVocê só pode usar este efeito de "Augusta Amazoness" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Pode atacar 2 vezes','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23965037,'Benção de Doriado',replace(replace('Este card é usado para a Invocação-Ritual de "Doriado, Senhora dos Elementos". \r\nTambém deve oferecer como Tributo monstros cuja soma dos Níveis seja igual ou maior que 3, do Campo ou da sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23969415,'Pílula de Evolução Beta - Ultranscendente',replace(replace('Ofereça como Tributo 2 monstros da sua mão e/ou do campo, incluindo um monstro Dinossauro; Invoque por Invocação-Especial 1 monstro Dinossauro de Nível 5 ou mais do seu Deck ou Deck Adicional, com um ATK igual ou maior que o ATK total desses monstros oferecidos como Tributo e, além disso, pelo resto deste turno depois que este card resolver, você não pode Invocar por Invocação-Especial do Deck Adicional, exceto monstros Dragão, Dinossauro, Serpente Marinha ou Wyrm. \r\nVocê só pode ativar 1 "Pílula de Evolução Beta - Ultranscendente" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23971061,'Dragão Duplo Byte',replace(replace('2 Monstros Link	\r\nGanha ATK igual ao Valor Link combinado dos monstros usados para sua Invocação-Link x 300. \r\nNão é afetado por efeitos de monstro, exceto os efeitos de Monstros Link, e não pode ser destruído em batalha, exceto em batalha com um Monstro Link.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23979249,'Bujin Arasuda',replace(replace('Se um monstro "Bujin" no seu Cemitério ou com a face para cima no seu lado do campo for banido (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão com a face para cima em Posição de Defesa. \r\nUma vez por turno, durante a Fase Final, se um card "Bujin" foi adicionado do seu Deck à sua mão neste turno, exceto ao ser comprado, enquanto você controlava este card com a face para cima: você pode comprar 1 card e, depois, descartar 1 card. \r\nVocê só pode controlar 1 "Bujin Arasuda".','\r',char(13)),'\n',char(10)),'Invocação Especial','Comprar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23995346,'Dragão Definitivo de Olhos Azuis','"Dragão Branco de Olhos Azuis" + "Dragão Branco de Olhos Azuis" + "Dragão Branco de Olhos Azuis"','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23995347,'Dragão Definitivo de Olhos Azuis','"Dragão Branco de Olhos Azuis" + "Dragão Branco de Olhos Azuis" + "Dragão Branco de Olhos Azuis"','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23995348,'Dragão Definitivo de Olhos Azuis','"Dragão Branco de Olhos Azuis" + "Dragão Branco de Olhos Azuis" + "Dragão Branco de Olhos Azuis"','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23995349,'Dragão Definitivo de Olhos Azuis','"Dragão Branco de Olhos Azuis" + "Dragão Branco de Olhos Azuis" + "Dragão Branco de Olhos Azuis"','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23998625,'Número 53: Heart-eartH',replace(replace('3 monstros de Nível 5	\r\nUma vez por turno, quando este card for alvo de um ataque: até a Fase Final, ele ganha ATK igual ao ATK original do monstro atacante. \r\nSe este card, com a face para cima, no campo, seria destruído, em vez disso, você pode desassociar 1 Matéria Xyz deste card. \r\nQuando este card, no campo, for destruído por um efeito de card enquanto ele não tem Matérias Xyz: você pode Invocar por Invocação-Especial 1 "Número 92: Dragão Heart-eartH" do seu Deck Adicional e associar este card a ele, do Cemitério, como uma Matéria Xyz. \r\n(Esta Invocação-Especial é considerada uma Invocação-Xyz.)','\r',char(13)),'\n',char(10)),'Aumentar ATK','Invocação Especial','Usar o efeito de "Número 53: Heart-eartH" em vez de ser destruído?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24010609,'Força Celeste - Módulo Mecha - Multifunção',replace(replace('Uma vez por turno: você pode escolher 1 outro card que você controla; envie esse card para o Cemitério e, além disso, pelo resto deste turno, seu oponente não pode ativar cards ou efeitos em resposta à ativação dos seus Cards de Magia (mesmo que este card deixe o campo). \r\n(Você só pode se aproveitar do efeito anterior uma vez por turno.) \r\nUma vez por turno, durante a Fase Final: você pode Baixar Magias "Força Celeste" com nomes diferentes do seu Cemitério, até o número de Cards de Magia "Força Celeste" que você ativou neste turno enquanto este card estava com a face para cima no seu campo, mas bana-as quando elas deixarem o campo.','\r',char(13)),'\n',char(10)),'','','Continuar selecionando?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24019092,'Cavaleirardor Paladino',replace(replace('Escala de Pêndulo = 2\r\n[ Efeito de Pêndulo ]\r\nSe você tiver um card "Cavaleirardor" na sua outra Zona de Pêndulo: você pode destruir os dois cards nas suas Zonas de Pêndulo e, se isso acontecer, adicione 1 monstro de FOGO do Tipo Guerreiro do seu Deck ou Cemitério à sua mão.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nEste Cavaleirardor tem a reputação de um pensador com a cabeça tranquila. Mas a verdade é que suas emoções só demoram um pouco mais para esquentar.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24019261,'Auxílio Emergencial','Ative durante sua Fase Principal 2 para Invocar por Invocação-Especial 1 monstro de Nível 4 do seu Cemitério que foi destruído por um efeito de card e enviado para o Cemitério neste turno.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24025620,'Defensor de Escudo Duplo','Quando este card que você controla for destruído em batalha e enviado para o seu Cemitério, você pode reduzir pela metade o ATK atual de 1 monstro com a face para cima que seu oponente controla até a Fase Final.','Alterar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24027078,'Morgana, a Feiticeira de Avalon',replace(replace('Quando seu oponente ativar um card ou efeito, enquanto você controlar um monstro "Nobre Cavaleiro" e uma Magia de Equipamento "Armas Nobres" (Efeito Rápido): você pode enviar este card da sua mão para o Cemitério; destrua 1 Magia de Equipamento "Armas Nobres" que você controla e, se isso acontecer, negue a ativação. \r\nVocê só pode usar este efeito de "Morgana, a Feiticeira de Avalon" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24037702,'Marcha da Brigada das Trevas',replace(replace('Escolha 1 monstro "Luminoso(a)" no seu Cemitério que tenha um Nível; adicione-o à sua mão e, depois, bana um número de cards do topo do seu Deck igual ao Nível original desse monstro na sua mão. \r\nVocê só pode ativar 1 "Marcha da Brigada das Trevas" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24040093,'Grimro Mitológica','Se você controlar um monstro "Mitológico(a)": você pode enviar este card da sua mão para o Cemitério; adicione 1 monstro "Mitológico(a)" do seu Deck à sua mão, exceto "Grimro Mitológica".','Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24050692,'Nenúfar Ogdoádico',replace(replace('Envie 1 monstro Réptil do seu Deck para o Cemitério e, depois, se você tiver 5 ou mais monstros Réptil com nomes diferentes no seu Cemitério, você pode Invocar por Invocação-Especial 1 monstro Réptil do seu Cemitério. \r\nVocê só pode ativar 1 "Nenúfar Ogdoádico" por turno.','\r',char(13)),'\n',char(10)),'Escolher um monstro para Invocá-lo por Invocação Especial?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24056179,'Xadrez de Monstros Cápsula',replace(replace('Durante a Fase Principal: o jogador do turno pode escolher 1 monstro no Cemitério dele; ele coloca-o na Zona de Magia & Armadilha dele com a face para cima como uma Magia Contínua.\r\nDurante a Fase Final: o jogador do turno pode enviar 1 Card de Monstro com a face para cima que ele controla para o Cemitério; ele Invoca por Invocação-Especial 1 monstro do Deck dele com o mesmo Tipo e Atributo original, mas 1, 2 ou 3 Níveis originais acima.\r\nVocê só pode usar cada um dos efeitos de "Xadrez de Monstros Cápsula" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Colocar um monstro','Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24062258,'Seita Secreta Druida Dru',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode escolher 1 monstro de TREVAS de Nível 4 no seu Cemitério com ATK e/ou DEF 0, exceto "Seita Secreta Druida Dru"; Invoque o alvo por Invocação-Especial com a face para cima em Posição de Defesa. \r\nSeus efeitos são negados. \r\nVocê só pode usar o efeito de "Seita Secreta Druida Dru" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24068492,'Apenas Sobremesas','Cause 500 de dano ao seu oponente para cada monstro que ele controla.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24070330,'Guerreiro Sinfônico Rockks',replace(replace('Escala de Pêndulo = 10\r\n[ Efeito de Pêndulo ]\r\nDurante cada Fase de Apoio: você pode adicionar 1 Monstro Pêndulo com a face para cima do seu Deck Adicional à sua mão. \r\nVocê só pode usar este efeito de "Guerreiro Sinfônico Rockks" uma vez por turno. \r\nQuando um monstro do oponente declarar um ataque: você pode destruir tanto esse monstro como este card.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\n1 Regulador + 1+ monstros não-Reguladores	\r\nSe este card na Zona de Monstros for destruído em batalha ou por um efeito de card: você pode colocar este card na sua Zona de Pêndulo. \r\nVocê só pode usar cada um dos seguintes efeitos de "Guerreiro Sinfônico Rockks" uma vez por turno. \r\nSe este card for Invocado por Invocação-Especial: você pode adicionar 1 Monstro Pêndulo com a face para cima do seu Deck Adicional à sua mão. \r\nSe "Sinfo Amplificardor" estiver na sua Zona do Campo: você pode destruir 1 card no campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24073068,'Gouki Suprex',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode Invocar por Invocação-Especial 1 monstro "Gouki" da sua mão. \r\nSe este card for enviado do campo para o Cemitério: você pode adicionar 1 card "Gouki" do seu Deck à sua mão, exceto "Gouki Suprex". \r\nVocê só pode usar este efeito de "Gouki Suprex" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24079759,'Motoqueiro Goblin Dugg Atropelador',replace(replace('Se este card estiver na sua mão: você pode desassociar 1 Matéria Xyz de um monstro em qualquer campo e, se isso acontecer, Invoque este card por Invocação-Especial. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 Magia/Armadilha "Motoqueiro Goblin" do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "Motoqueiro Goblin Dugg Atropelador" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Procurar no Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24081957,'Despojos do Pecado da Subversão - Olho de Cobra',replace(replace('Escolha 1 monstro com a face para cima no campo; coloque-o com a face para cima na Zona de Magias & Armadilhas do seu dono como uma Magia Contínua. \r\nVocê só pode ativar 1 "Despojos do Pecado da Subversão - Olho de Cobra" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24082387,'Círculos nas Plantações',replace(replace('Envie qualquer número de monstros no seu lado do campo ao Cemitério para ativar este card. \r\nSelecione 1 monstro "Alienígena" do seu Deck com Nível igual à soma de Níveis dos monstros enviados ao Cemitério e Invoque-o por Invocação-Especial. \r\nSe você não encontrar um monstro para Invocar por Invocação-Especial, você sofre 2000 de dano.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24087580,'Mestra da Espada Prateada Amazoness',replace(replace('Escala de Pêndulo = 7\r\n[ Efeito de Pêndulo ]\r\nMonstros "Amazoness" que você controla ganham ATK igual ao seu próprio Nível x 100. \r\nQuando um ataque for declarado envolvendo um monstro "Amazoness" seu: você pode escolher 1 Magia/Armadilha "Amazoness" no seu Cemitério; adicione-a à sua mão. \r\nVocê só pode usar este efeito de "Mestra da Espada Prateada Amazoness" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe este card na Zona de Monstros for destruído em batalha ou por um efeito de card: você pode colocar este card na sua Zona de Pêndulo. \r\nSe um ou mais monstros "Amazoness" forem Invocados por Invocação-Especial no seu campo, enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode colocar este card na sua Zona de Pêndulo. \r\nVocê só pode usar cada efeito de "Mestra da Espada Prateada Amazoness" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24088928,'Caveira Arquidemônio do Caos',replace(replace('Se este card estiver na sua mão ou no Cemitério: você pode escolher 3 outros cards nos Cemitérios e/ou no banimento com a face para cima, incluindo um card que mencione "Ritual da Luz e das Trevas"; coloque-os no fundo do Deck em qualquer ordem e, se isso acontecer, Invoque este card por Invocação-Especial. \r\nSe este card for enviado para o Cemitério: você pode enviar 1 Magia de Ritual da sua mão ou do Deck para o Cemitério; adicione 1 Monstro de Ritual cujo nome seja mencionado nesse card, do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "Caveira Arquidemônio do Caos" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Efeito de busca','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24092792,'Elfnotas: Rapsódia da Loucura',replace(replace('Enquanto você controlar um monstro na sua Zona de Monstros Principal central, os monstros do seu oponente não podem atacar, exceto atacar esse monstro. \r\nVocê pode enviar 1 monstro da sua mão ou do campo para o Cemitério e, depois, escolha 1 monstro "Elfnota" no seu Cemitério com um Atributo original diferente; Invoque-o por Invocação-Especial e, depois, se você controlar um Monstro Sincro, até o final deste turno, você pode negar os efeitos de 1 card com a face para cima que seu oponente controla. \r\nVocê só pode usar este efeito de "Elfnotas: Rapsódia da Loucura" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Negar os efeitos desse card?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24094258,'Metalmorfose Pesado Eletrumite',replace(replace('2 Monstros Pêndulo	\r\nSe este card for Invocado por Invocação-Link: você pode adicionar 1 Monstro Pêndulo do seu Deck com a face para cima no seu Deck Adicional. \r\nUma vez por turno: você pode escolher 1 outro card com a face para cima que você controla; destrua-o e, depois, adicione à sua mão 1 Monstro Pêndulo com a face para cima no seu Deck Adicional. \r\nSe um ou mais cards nas suas Zonas de Pêndulo deixarem o campo: compre 1 card. \r\nVocê só pode usar este efeito de "Metalmorfose Pesado Eletrumite" uma vez por turno.','\r',char(13)),'\n',char(10)),'Coloque Monstros Pêndulo do seu Deck no seu Deck Adicional','Destrua e adicione à sua mão um Monstro Pêndulo do seu Deck Adicional','Comprar','Escolha o card para adicioná-la com a face para cima no Deck Adicional','','','','','','','','','','','','');
INSERT INTO texts VALUES(24094653,'Polimerização','Invoque por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional, usando monstros da sua mão ou do campo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24094654,'Polimerização','Invoque por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional, usando monstros da sua mão ou do campo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24094655,'Polimerização','Invoque por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional, usando monstros da sua mão ou do campo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24096228,'Magia Dupla','Descarte 1 Magia e, depois, escolha 1 Magia no Cemitério do seu oponente; coloque o alvo na zona apropriada no seu campo e, como parte da resolução deste efeito de card, siga seu texto do card como se você o tivesse usado.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24096499,'Valerigamo, Besta Mística da Floresta',replace(replace('Você pode descartar 1 card e, depois, escolha 1 monstro Besta de Nível 2 ou menos no seu Cemitério, exceto "Valerigamo, Besta Mística da Floresta"; Invoque-o por Invocação-Especial em Posição de Ataque ou com a face para baixo em Posição de Defesa. \r\nVocê só pode usar este efeito de "Valerigamo, Besta Mística da Floresta" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24101897,'Nekomusume Fantardil',replace(replace('Não pode ser Invocado por Invocação-Normal, a não ser que você controle um monstro "Fantardil". \r\nUma vez por turno: você pode colocar este card com a face para baixo em Posição de Defesa. \r\nQuando um ou mais monstros de Nível 4 ou mais forem Invocados por Invocação-Normal ou Especial: coloque esses monstros com a face para baixo em Posição de Defesa. \r\nDeve haver outro monstro "Fantardil" no campo para que você possa ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Mudar para Posição de Defesa com a face para baixo','Mudar para Posição de Defesa com a face para baixo','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24103628,'Mago Fantasma','Quando este card for destruído em batalha e enviado ao Cemitério: Você pode Invocar por Invocação-Especial 1 monstro "HERÓI" com 1000 ou menos de ATK do seu Deck com a face para cima em Posição de Defesa.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24104865,'Mãe Alienígena',replace(replace('Se este card destruir um monstro com um Marcador-A em batalha e enviá-lo ao Cemitério, Invoque o monstro destruído por Invocação-Especial no seu lado do campo no fim da Fase de Batalha. \r\nQuando este card for removido do campo, todos os monstros Invocados por Invocação-Especial pelo efeito deste card são destruídos.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24128274,'Guerreiro das Profundezas do Mar','Enquanto "Umi" estiver com a face para cima no campo, este card não é afetado por Cards de Magia.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24131534,'Cavaleirardor Escudeiro',replace(replace('Escala de Pêndulo = 7\r\n[ Efeito de Pêndulo ]\r\nSe você tiver um card "Cavaleirardor" na sua outra Zona de Pêndulo: você pode destruir os dois cards nas suas Zonas de Pêndulo e, se isso acontecer, adicione 1 monstro de FOGO do Tipo Guerreiro do seu Deck ou Cemitério à sua mão.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nA fria armadura de aço deste jovem escudeiro não pode esconder a mente aguçada e sagaz contida dentro dela.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24137081,'Mexilhão Broca',replace(replace('Este card pode atacar seu oponente diretamente. \r\nCada vez que este card causar Dano de Batalha ao seu oponente por um ataque direto: Este card ganha 1000 de ATK.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24140059,'Um Gato do Ill Omen','VIRE: Selecione 1 Armadilha do seu Deck e coloque-a no topo do seu Deck ou, se "Necro-Vale" estiver no campo, em vez disso, você pode adicionar essa Armadilha à sua mão.','Colocar no topo do Deck','Escolha 1 Card de Armadilha','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24150026,'Karakuri Muso mod. 818 "Haipa"',replace(replace('Este card deve atacar se possível. \r\nQuando este card com a face para cima em Posição de Ataque for escolhido como alvo de um ataque, mude-o para Posição de Defesa. \r\nSe este card atacar, coloque-o em Posição de Defesa no final da Fase de Batalha.','\r',char(13)),'\n',char(10)),'Mudar para Posição de Defesa','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24151924,'G Golem Dólmen Inválido',replace(replace('2+ monstros de TERRA	\r\nMonstros co-linkados que você controla não são afetados por efeitos de monstro ativados no campo do seu oponente. \r\nTodos os monstros que seu oponente controla que podem atacar devem atacar este card. \r\nUma vez por turno: você pode descartar 1 monstro Ciberso; compre 1 card. \r\nSe este card co-linkado for destruído: você pode negar os efeitos de todos os cards com a face para cima que seu oponente controla atualmente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24154052,'Prótron','Uma espécie antiga encontrada no espaço eletrônico. Ninguém sabe quanta informação ela contém.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24158464,'Jhrelth Tindângulo',replace(replace('VIRE: Você pode pegar 1 monstro de Virar do seu Deck, exceto "Jhrelth Tindângulo", e adicione-o à sua mão ou envie-o para o Cemitério.\r\nSe este card estiver na sua mão: você pode descartar 1 outro card; envie 1 card "Tindângulo" do seu Deck para o Cemitério, exceto "Jhrelth Tindângulo" e, se isso acontecer, Invoque este card por Invocação-Especial com a face para baixo em Posição de Defesa. \r\nVocê só pode usar cada efeito de "Jhrelth Tindângulo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24166324,'Drytron Meteaurora',replace(replace('Se um ou mais cards "Drytron" forem banidos (exceto durante a Etapa de Dano): você pode oferecer como Tributo 1 monstro "Drytron" e, depois, escolha até 2 dos seus cards "Drytron" banidos; adicione-os à sua mão. \r\nVocê pode revelar 1 "Drytron Meteonis" na sua mão; Invoque por Invocação-Ritual 1 Monstro de Ritual Máquina da sua mão ou do Cemitério, ao oferecer como Tributo monstros Máquina da sua mão ou do campo cujo ATK total seja igual ou exceda seu ATK. \r\nVocê só pode usar cada efeito de "Drytron Meteaurora" uma vez por turno.','\r',char(13)),'\n',char(10)),'Recuperar cards banidos','Ritual do Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24175232,'Cerúlea Fênix Sagrada de Nephthys',replace(replace('Você pode Invocar este card por Invocação-Ritual com "Renascimento de Nephthys". \r\nVocê só pode usar cada um dos seguintes efeitos de "Cerúlea Fênix Sagrada de Nephthys" uma vez por turno.\r\n● Durante sua Fase Principal: você pode destruir cards "Nephthys" na sua mão e/ou com a face para cima no campo e, depois, destrua um mesmo número de monstros que seu oponente controla.\r\n● Durante sua próxima Fase de Apoio depois que este card foi destruído em batalha ou por um efeito de card e enviado para o Cemitério: você pode Invocar este card por Invocação-Especial do Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24181936,'Festa Yaminabe',replace(replace('No começo da sua Fase de Batalha: você pode escolher 1 monstro com a face para cima que você controla; neste turno, seu oponente seleciona o(s) alvo(s) do(s) ataque(s) desse monstro e, além disso, se esse monstro que você controla batalhar um monstro do oponente, ele ganha ATK igual ao seu ATK original apenas durante o cálculo de dano. \r\nVocê só pode usar este efeito de "Festa Yaminabe" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24184846,'Boxeador Obstinado Coelho Pegador','Durante o turno de qualquer duelista: você pode banir este card da sua mão ou Cemitério e, depois, escolher 1 monstro "Boxeador Obstinado" que você controla; bana-o até sua próxima Fase de Apoio.','Banir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24194033,'Dorover','Este monstro feioso emite um gás altamente venenoso.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24203749,'O Maior Ladrão Cavalheiro do Mundo',replace(replace('Se você não controla monstros, você pode Invocar por Invocação-Tributo este card com a face para cima oferecendo como Tributo monstros da sua mãe e/ou campo do seu oponente.\r\nVocê só pode usar cada um dos seguintes efeitos de "O Maior Ladrão Cavalheiro do Mundo" uma vez por turno.\r\nQuando seu oponente ativar um efeito de card na mão, Cemitério ou banimento, enquanto você controla este card Invocado por Invocação-Normal/Baixado.\r\nDurante a Fase de Batalha (Efeito Rápido): você pode revelar sua mão inteira; altere todos os monstros que seu oponente controla para Posição de Defesa.','\r',char(13)),'\n',char(10)),'Invocar por Tributo oferecendo monstros da sua mão e do campo do seu oponente como Tributo','Negar o efeito','Posição de batalha','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24203750,'O Maior Ladrão Cavalheiro do Mundo',replace(replace('Se você não controla monstros, você pode Invocar por Invocação-Tributo este card com a face para cima oferecendo como Tributo monstros da sua mãe e/ou campo do seu oponente.\r\nVocê só pode usar cada um dos seguintes efeitos de "O Maior Ladrão Cavalheiro do Mundo" uma vez por turno.\r\nQuando seu oponente ativar um efeito de card na mão, Cemitério ou banimento, enquanto você controla este card Invocado por Invocação-Normal/Baixado.\r\nDurante a Fase de Batalha (Efeito Rápido): você pode revelar sua mão inteira; altere todos os monstros que seu oponente controla para Posição de Defesa.','\r',char(13)),'\n',char(10)),'Invocar por Tributo oferecendo monstros da sua mão e do campo do seu oponente como Tributo','Negar o efeito','Posição de batalha','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24207889,'Só Pode Haver Um',replace(replace('Cada duelista só pode controlar 1 monstro de cada Tipo. \r\nSe um duelista controlar 2 ou mais monstros do mesmo Tipo, ele deve enviar algum(ns) para o Cemitério até que não controle mais que 1 monstro desse Tipo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24212820,'Os Cavaleiros Fantasmas das Manoplas Negras',replace(replace('Envie 1 Magia/Armadilha "Cavaleiros Fantasmas" do seu Deck para o Cemitério. \r\nQuando um monstro do oponente declarar um ataque direto enquanto você não controlar nenhum card e este card estiver no seu Cemitério: Invoque este card por Invocação-Especial em Posição de Defesa como um Monstro de Efeito (Guerreiro/TREVAS/Nível 4/ATK 300/DEF 600), mas bana-o quando ele deixar o campo.	\r\n(Este card NÃO é considerado como uma Armadilha.) \r\nSe Invocado desta forma, este card ganha 300 de DEF para cada Magia/Armadilha "Cavaleiros Fantasmas" no seu Cemitério.','\r',char(13)),'\n',char(10)),'Invocar este card por Invocação Especial como um Monstro de Efeito','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24215921,'Horrível Serpeador do Túmulo',replace(replace('Se você controlar um monstro Demônio (Efeito Rápido): você pode Invocar este card por Invocação-Especial da sua mão e, depois, você pode destruir 1 "Yubel", ou 1 monstro que o mencione, na sua Zona de Monstros. \r\nVocê pode banir este card do seu Cemitério; Invoque por Invocação-Especial 1 monstro Demônio com 0 de ATK/DEF da sua mão ou do Cemitério, exceto "Horrível Serpeador do Túmulo". \r\nVocê só pode usar cada efeito de "Horrível Serpeador do Túmulo" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invoque este card por Invocação Especial','Invocar por Invocação Especial um monstro Demônio','Destruir aquele monstro?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24218047,'Dragão Desmascarado','Quando este card for destruído em batalha e enviado para o Cemitério: você pode Invocar por Invocação-Especial do seu Deck 1 monstro Wyrm com DEF 1500 ou menos.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24220368,'Dispersão Cavaleiro-Gema',replace(replace('Ative 1 desses efeitos (mas você só pode usar cada efeito de "Dispersão Cavaleiro-Gema" uma vez por turno);\r\n● Invoque por Invocação-Fusão 1 Monstro de Fusão "Cavaleiro-Gema" do seu Deck Adicional, usando monstros da sua mão ou do campo.	\r\nAté 2 monstros do seu Deck/Deck Adicional podem ser usados, se eles forem monstros "Cavaleiro-Gema" que não sejam Rocha e você tiver "Fusão Cavaleiro-Gema" no seu Cemitério.\r\n● Adicione 1 monstro "-Gema" do seu Deck ou banimento à sua mão e, além disso, qualquer dano de efeito que seu oponente sofrer durante a Fase Principal deste turno é diminuído pela metade.','\r',char(13)),'\n',char(10)),'Ativar','Invocação Fusão','Adicionar à mão','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24221739,'Protetor do Santuário','Enquanto este card permanecer no Campo com a face para cima, o seu adversário não pode comprar cards excepto durante as Draw Phases.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24221808,'Arquidemônio Mentalorde',replace(replace('1 monstro Regulador do Tipo Psíquico + 2 ou mais monstros do Tipo Psíquico não-Reguladores	\r\nUma vez por turno, você pode selecionar 1 monstro do Tipo Psíquico no seu Cemitério e removê-lo de jogo. \r\nQuando este card for enviado do campo para o Cemitério, Invoque por Invocação-Especial tantos monstros quanto possível que foram removidos de jogo por este efeito.','\r',char(13)),'\n',char(10)),'Banir','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24224830,'Chamado da Cova','Escolha 1 monstro no Cemitério do seu oponente; bana-o e, se isso acontecer, até o final do próximo turno, seus efeitos são negados, assim como os efeitos ativados e efeitos no campo de monstros com o mesmo nome original.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24224831,'Chamado da Cova','Escolha 1 monstro no Cemitério do seu oponente; bana-o e, se isso acontecer, até o final do próximo turno, seus efeitos são negados, assim como os efeitos ativados e efeitos no campo de monstros com o mesmo nome original.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24224832,'Chamado da Cova','Escolha 1 monstro no Cemitério do seu oponente; bana-o e, se isso acontecer, até o final do próximo turno, seus efeitos são negados, assim como os efeitos ativados e efeitos no campo de monstros com o mesmo nome original.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24226942,'Nephthys do Caos',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial por seu próprio efeito. \r\nSe um ou mais cards no campo forem destruídos por um efeito de card: você pode banir 1 monstro de LUZ e 1 de TREVAS do seu Cemitério, exceto "Nephthys do Caos"; Invoque este card por Invocação-Especial do Cemitério (se ele estava lá quando o card foi destruído) ou da mão (mesmo se ele não estava). \r\nVocê só pode usar este efeito de "Nephthys do Caos" uma vez por turno. \r\nSe este card for Invocado por Invocação-Especial: você pode escolher 1 card que seu oponente controla e 2 cards no Cemitério dele; bana-os.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24232799,'Armazenamentopoda',replace(replace('"Trifortalezatops" ou "Estegociber" + 1 monstro Máquina ou Dinossauro	\r\nNão pode ser destruído em batalha enquanto um monstro Invocado por Invocação-Especial do Cemitério estiver no campo. \r\nSe um ou mais monstros forem Invocados por Invocação-Especial da mão enquanto este monstro estiver no campo (exceto durante a Etapa de Dano): você pode escolher 1 card que você controla e 1 card que seu oponente controla; destrua-os. \r\nVocê só pode usar este efeito de "Armazenamentopoda" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24268052,'Compra Defensiva','Durante o turno do seu oponente, no cálculo de dano: Faça com que o Dano de Batalha que você sofrer desta batalha seja 0 e, se isso acontecer, compre 1 card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24269961,'Senhor da Alma Desacorrentada de Yama',replace(replace('2 monstros Demônio	\r\nSe este card for Invocado por Invocação-Especial: você pode adicionar 1 monstro "Desacorrentado(a)" do seu Deck ou Cemitério à sua mão. \r\nSe um ou mais cards que você controla forem destruídos em batalha ou por um efeito de card, enquanto este card estiver no seu Cemitério: você pode banir este card; Invoque por Invocação-Especial 1 monstro Demônio da sua mão ou do Cemitério e, depois, você pode destruir 1 card que você controla. \r\nVocê só pode usar cada efeito de "Senhor da Alma Desacorrentada de Yama" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Destruir 1 card que você controla?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24269962,'Senhor da Alma Desacorrentada de Yama',replace(replace('2 monstros Demônio	\r\nSe este card for Invocado por Invocação-Especial: você pode adicionar 1 monstro "Desacorrentado(a)" do seu Deck ou Cemitério à sua mão. \r\nSe um ou mais cards que você controla forem destruídos em batalha ou por um efeito de card, enquanto este card estiver no seu Cemitério: você pode banir este card; Invoque por Invocação-Especial 1 monstro Demônio da sua mão ou do Cemitério e, depois, você pode destruir 1 card que você controla. \r\nVocê só pode usar cada efeito de "Senhor da Alma Desacorrentada de Yama" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Destruir 1 card que você controla?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24285858,'Retorno do Gladiador','Escolha 3 cards "Besta Gladiadora" no seu Cemitério; embaralhe todos os 3 alvos no Deck e, depois, compre 1 card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24291651,'Cavaleiro Ganbara','Quando este card com a face para cima em Posição de Ataque for alvo de um ataque: você pode mudá-lo para a Posição de Defesa.','Mudar para Posição de Defesa','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24294108,'Terra em Chamas',replace(replace('Quando este card for ativado: se houver Cards de Magia de Campo no campo, destrua-os. \r\nDurante a Fase de Apoio de cada duelista: o duelista do turno sofre 500 de dano.','\r',char(13)),'\n',char(10)),'Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24299458,'Gota Proibida',replace(replace('Envie qualquer número de outros cards da sua mão e/ou do campo para o Cemitério; selecione esse número de Monstros de Efeito que seu oponente controla e, até o final deste turno, o ATK deles é diminuído pela metade e, além disso, seus efeitos são negados. \r\nEm resposta à ativação deste card, seu oponente não pode ativar cards, ou os efeitos de cards, com o mesmo tipo original (Monstro/Magia/Armadilha) que o dos cards enviados para o Cemitério para ativar este card. \r\nVocê só pode ativar 1 "Gota Proibida" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24311372,'Zoa','Um monstro cujo máximo potencial pode ser alcançado em conjunto com "Metalmorfo".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24311595,'Resgateroide',replace(replace('Quando um monstro "roide" que você controla for destruído em batalha e enviado para o Cemitério: você pode devolver esse monstro para a mão. \r\nVocê deve controlar este card com a face para cima no campo para ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24317029,'Espião do Coveiro','VIRE: Invoque por Invocação-Especial do seu Deck 1 monstro "do Coveiro" com 1500 ou menos de ATK.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24326617,'Escher, o Vassalo Glacial','Se seu oponente controlar 2 ou mais cards na Zona de Magias & Armadilhas dele, você pode Invocar este card por Invocação-Especial (da sua mão).','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24348204,'O Ladrão Fantasma Charmoso','Um ladrão charmoso com uma capa negra que encanta seus inimigos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24348804,'Perder 1 Turno',replace(replace('Ative apenas se você atualmente não controlar nenhum monstro Invocado por Invocação-Especial. \r\nEnquanto um monstro estiver com a face para cima no campo, negue seus efeitos durante o turno em que o monstro foi Invocado por Invocação-Especial. \r\nSe um ou mais Monstros de Efeito forem Invocados por Invocação-Especial em Posição de Ataque: coloque-o em Posição de Defesa.','\r',char(13)),'\n',char(10)),'Usar o efeito?','Ativar e aplicar o efeito','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24361622,'Selo Hierático das Esferas Celestes',replace(replace('2 monstros Dragão	\r\nUma vez por turno do oponente, se este card estiver na Zona de Monstros Adicional (Efeito Rápido): você pode oferecer como Tributo 1 monstro da sua mão ou do campo; devolva para a mão 1 card com a face para cima no campo. \r\nSe este card for oferecido como Tributo: Invoque por Invocação-Especial 1 monstro Dragão da sua mão ou do Deck e torne seu ATK/DEF 0. \r\nVocê só pode usar este efeito de "Selo Hierático das Esferas Celestes" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24362891,'Evo-Instante','Ofereça como Tributo 1 monstro do Tipo Réptil; Invoque por Invocação-Especial 1 monstro "Evolssauro" do seu Deck.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24382602,'Mausoléu de Branco',replace(replace('Durante sua Fase Principal, você pode Invocar por Invocação-Normal 1 Regulador de LUZ de Nível 1 em adição à sua Invocação-Normal/Baixar (padrão). \r\n(Você só pode se aproveitar deste efeito uma vez por turno.) \r\nUma vez por turno: você pode escolher 1 monstro com a face para cima que você controla; envie 1 Monstro Normal da sua mão ou do Deck para o Cemitério e, se isso acontecer, até o final deste turno, o monstro alvo ganha ATK/DEF igual ao Nível do monstro enviado para o Cemitério x 100 (mesmo que este card deixe o campo). \r\nVocê pode banir este card do seu Cemitério; adicione 1 "Raio Explosivo de Destruição" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Invocar pelo efeito de "Mausoléu de Branco"','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24384095,'Kujakujaku',replace(replace('Se este card no campo for oferecido como Tributo e enviado para o Cemitério: você pode adicionar 1 monstro de VENTO de Nível 4 ou menos do seu Deck ou Cemitério à sua mão, exceto "Kujakujaku". \r\nVocê só pode usar o efeito de "Kujakujaku" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24393683,'Especial do Dia do Naviushi Gunkan',replace(replace('(Quando você ativar este card, você também pode revelar 1 "Shari do Naviushi Gunkan" na sua mão.) \r\nRevele 3 monstros "Gunkan" do seu Deck, seu oponente seleciona 1 deles para que você adicione à sua mão e, além disso, embaralhe o resto no seu Deck. \r\nSe você revelou "Shari do Naviushi Gunkan" na sua mão na ativação, você pode selecionar o card para adicionar à sua mão em vez do seu oponente. \r\nSe este card estiver no seu Cemitério, exceto no turno em que ele foi enviado para lá: você pode banir este card e, depois, escolha 3 monstros "Gunkan" no seu Cemitério; embaralhe-os no Deck e, depois, compre 1 card.','\r',char(13)),'\n',char(10)),'Revelar "Shari do Naviushi Gunkan" na sua mão para ativar?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24413299,'O Repressor Plutão',replace(replace('Uma vez por turno: você pode declarar o nome de 1 card; olhe a mão do seu oponente e, depois, se ele tiver o card declarado na mão, aplique 1 dos seguintes efeitos.\r\n● Tome o controle de 1 monstro que seu oponente controla.\r\n● Destrua 1 Magia/Armadilha que seu oponente controla e, depois, você pode Baixar a Magia/Armadilha destruída no seu campo.','\r',char(13)),'\n',char(10)),'Declare o nome de um card','Tome o controle','Destruir um Card de Magia/Armadilha','Baixá-la no seu Campo?','','','','','','','','','','','','');
INSERT INTO texts VALUES(24419823,'Escavacampominado','Quando este card com a face para cima que você controla deixar o campo e ainda estiver sob a sua posse: você pode escolher 1 Card de Magia de Campo no seu Cemitério; adicione o alvo à sua mão.','Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24425055,'Armadilha Oculta E',replace(replace('Descarte 1 card; Baixe no seu campo 1 Card de Armadilha Contínua da sua mão ou Cemitério. \r\nEsse card Baixado pode ser ativado durante este turno.','\r',char(13)),'\n',char(10)),'','Ativar aplicando o efeito de "Armadilha Oculta E".','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24429467,'Bestamorfose Mítica',replace(replace('Sempre que um efeito de monstro do oponente for ativado, coloque 1 Marcador de Magia neste card quando esse efeito resolver. \r\nVocê pode enviar este card com 6 ou mais Marcadores de Magia para o Cemitério; adicione 1 Magia do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Bestamorfose Mítica" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24431911,'Tellusion, o Guerreiro Ímã',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (do seu Cemitério) ao banir 1 "Guerreiro Ímã Sigma Plus" e 1 "Guerreiro Ímã Sigma Minus" da sua mão, da Zona de Monstros com a face para cima e/ou do Cemitério. \r\nUma vez por turno, quando seu oponente ativar um card ou efeito (Efeito Rápido): você pode escolher 1 monstro que seu oponente controla; destrua-o, ou se você escolheu um monstro de TERRA, em vez disso, você pode tomar o controle dele. \r\nDurante o turno do seu oponente (Efeito Rápido): você pode oferecer este card como Tributo; Invoque por Invocação-Especial 2 dos seus monstros "Guerreiro Ímã Sigma" banidos.','\r',char(13)),'\n',char(10)),'Invocação Especial','Efeito de destruição','Invocação Especial','Tome o controle?','','','','','','','','','','','','');
INSERT INTO texts VALUES(24432029,'Ventilador Genex','Quando este card for Invocado por Invocação-Especial, você pode adicionar 1 monstro "Genex" de TREVAS do seu Deck à sua mão.','Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24433920,'Máquina do Pêndulo','Uma terrível máquina de tortura com uma grande lâmina em pêndulo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24433921,'Máquina do Pêndulo','Uma terrível máquina de tortura com uma grande lâmina em pêndulo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24434049,'Fofura Epurrely',replace(replace('2 monstros de Nível 2	\r\nUma vez por turno: você pode escolher até 2 Magias/Armadilhas nos Cemitérios; associe-as a este card como matéria. \r\nEste é um Efeito Rápido se este card tiver "Deliciosa Lembrança Purrely" como matéria. \r\nAté três vezes por turno, quando você ativar um Card de Magia Rápida "Purrely" (Efeito Rápido): você pode associar esse card no campo a este card como matéria e, depois, você pode banir 1 monstro no campo até a Fase Final.','\r',char(13)),'\n',char(10)),'Associar Matéria do Cemitério','Associar a Magia Rápida ativada a este card','Banir o monstro selecionado?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24435369,'Cavaleira Sereia','Enquanto "Umi" permanecer no Campo com a face para cima, este card pode atacar duas vezes durante a mesma Battle Phase.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24440742,'Truque do Chapelhueta',replace(replace('Invoque este card por Invocação-Especial como um Monstro de Efeito (Ilusão/TREVAS/Nível 4/ATK 1500/DEF 600) com os seguintes efeitos (este card ainda é considerado uma Armadilha).\r\n● Se este card for Invocado por Invocação-Especial: você pode escolher cards com a face para cima que seu oponente controla, até o número de monstros Ilusão que você controla; negue seus efeitos até o final deste turno.\r\n● Se este card batalhar um monstro, nenhum dos dois pode ser destruído nessa batalha.	\r\nVocê só pode ativar 1 "Truque do Chapelhueta" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24449083,'Tribunal de Justiça',replace(replace('Durante sua Fase Principal: você pode Invocar por Invocação-Especial 1 monstro Fada da sua mão. \r\nVocê deve controlar um monstro Fada de Nível 1 para ativar e resolver este efeito. \r\nVocê só pode usar este efeito de "Tribunal de Justiça" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24454387,'Zuttomozauro',replace(replace('Enquanto você controlar outro monstro Dinossauro, os monstros do seu oponente não podem escolher este card como alvo de ataques. \r\nVocê pode escolher 1 outro card que você controla; destrua-o. \r\nVocê só pode usar este efeito de "Zuttomozauro" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24461358,'Registros Destroçados de Ritos',replace(replace('Revele 1 Magia de Ritual da sua mão ou do Deck e, se isso acontecer, adicione 1 monstro do seu Deck à sua mão que mencione o nome dessa Magia. \r\nSe um ou mais Monstros de Ritual com a face para cima que você controla deixarem o campo devido a um efeito de card enquanto este card estiver no seu Cemitério e você não controlar nenhum monstro com a face para cima, que não sejam Monstros de Ritual (exceto durante a Etapa de Dano): você pode adicionar este card do seu Cemitério à sua mão. \r\nVocê só pode usar cada efeito de "Registros Destroçados de Ritos" uma vez por turno.','\r',char(13)),'\n',char(10)),'Efeito de busca','Retornar para a mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24484270,'Cavaleiro-Gema Quartzo Fantasma',replace(replace('2 monstros "-Gema"	\r\nSe este card for Invocado por Invocação-Link: você pode adicionar 1 card "Cavaleiro-Gema" do seu Deck à sua mão. \r\nVocê pode pagar 1000 PV; Invoque por Invocação-Fusão 1 Monstro de Fusão "Cavaleiro-Gema" do seu Deck Adicional, ao embaralhar suas matérias do seu Cemitério ou banimento no Deck, mas ele não pode atacar diretamente neste turno. \r\nVocê só pode usar cada efeito de "Cavaleiro-Gema Quartzo Fantasma" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24487411,'Deletador de Detonação',replace(replace('2+ monstros Ciberso	\r\nUma vez por turno, no começo da Etapa de Dano, quando este card batalhar um monstro com a face para cima que não seja um Monstro Link de Link-3 ou mais: você pode destruir esse monstro. \r\nUma vez por turno: você pode oferecer como Tributo 1 monstro para o qual este card apontar e, depois, escolher 1 monstro que seu oponente controla; destrua-o.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24506253,'Cronomalia Figuras de Acámbaro',replace(replace('Se um ou mais monstros "Cronomalia" que você controla seriam destruídos em batalha ou por um efeito de card do seu oponente, em vez disso, você pode descartar este card. \r\nSe este card estiver no seu Cemitério: você pode pagar 1000 PV; Invoque este card por Invocação-Especial, mas devolva-o para a mão durante a Fase Final. \r\nVocê não pode Invocar monstros por Invocação-Especial no turno em que ativar este efeito, exceto monstros "Cronomalia". \r\nVocê só pode usar este efeito de "Cronomalia Figuras de Acámbaro" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24508238,'D.D. Corvo','(Efeito Rápido): você pode descartar este card para o Cemitério e, depois, escolha 1 card no Cemitério do seu oponente; bana o alvo.','Banir 1 card do Cemitério do seu oponente','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24514503,'Cristal Congelalma',replace(replace('Não pode ser destruído por efeitos de card. \r\nVocê só pode usar cada um dos seguintes efeitos de "Cristal Congelalma" uma vez por turno. \r\nSe seu oponente controlar pelo menos 2 monstros a mais que você: você pode Invocar este card por Invocação-Especial da sua mão. \r\nVocê pode escolher 1 Monstro de Efeito que seu oponente controla; negue seus efeitos.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24521325,'Modelo-do-lodo',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) em uma zona sua para a qual um Monstro Link Ciberso apontar. \r\nVocê só pode Invocar "Modelo-do-lodo" por Invocação-Especial uma vez por turno desta forma. \r\nDurante sua Fase Principal: você pode banir 1 monstro Ciberso da sua mão ou do Cemitério e, se isso acontecer, o nome deste card pode ser considerado como o nome do monstro banido, se usado como Matéria Link neste turno. \r\nVocê só pode usar este efeito de "Modelo-do-lodo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Banir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24521754,'Cachinhos Dourados, a Paisagista de Batalha',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial em uma zona que não seja a Zona de Monstros Principal central, destrua este card. \r\nEste card ganha 3000 de ATK enquanto estiver na Zona de Monstros Principal central. \r\nUma vez por turno: você pode selecionar 1 das suas Zonas de Monstros Principais não utilizadas; mova este card da sua Zona de Monstros Principal para essa zona e, depois, destrua todos os outros cards na coluna da zona em que este card estava, na coluna da zona para a qual este card foi movido e em todas as colunas entre elas.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24530661,'Mestre Kyonshee','Um vagueante Kyonshee que procura um forte rival para derrotar. Diz-se que era conhecido como o mestre de todas as artes marciais.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24545464,'Defletor Sincro',replace(replace('Ative apenas quando um Monstro Sincro com a face para cima que você controla for selecionado como alvo de um ataque. \r\nNegue o ataque e destrua 1 monstro que seu oponente controla.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24550676,'Leoa Dançarina Luzlunar',replace(replace('"Pantera Dançarina Luzlunar" + 2 monstros "Luzlunar"	\r\nDeve ser Invocado por Invocação-Fusão com as Matérias de Fusão acima. \r\nSeu oponente não pode escolher este card como alvo de efeitos de card e, além disso, ele não pode ser destruído pelos efeitos de card do seu oponente. \r\nPode realizar um segundo ataque durante cada Fase de Batalha. \r\nUma vez por turno, no final da Etapa de Dano, se este card atacou um monstro: você pode destruir todos os monstros Invocados por Invocação-Especial que seu oponente controla.','\r',char(13)),'\n',char(10)),'Destrua todos os monstros Invocados por Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24557335,'Espírito Tenyi - Shthana',replace(replace('Se você não controlar nenhum Monstro de Efeito: você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe um ou mais Monstros que não sejam de Efeito com a face para cima que você controla forem destruídos em batalha ou por um efeito de card: você pode banir este card da sua mão ou do Cemitério e, depois, escolher 1 desses monstros destruídos; Invoque-o por Invocação-Especial e, depois, você pode destruir 1 monstro que seu oponente controla. \r\nVocê só pode usar cada efeito de "Espírito Tenyi - Shthana" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Destrua o monstro Invocado por Invocação Especial','Destruir o monstro do seu oponente?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24566654,'Fogo Carmesim','Quando seu oponente ativar um Card de Magia/Armadilha que causaria dano a você, enquanto você controlar um "Dragão Vermelho Arquidemônio": em vez disso, seu oponente sofre duas vezes o dano de efeito que você teria tomado.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24573625,'Robô-secretário 008',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nVocê não pode Invocar monstros por Invocação-Pêndulo, exceto monstros "Robô-secretário". \r\nEste efeito não pode ser negado.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nEste card ganha 500 de ATK para cada card "Robô-secretário" no seu Cemitério. \r\nSeu oponente não pode escolher cards "Robô-secretário" com a face para cima como alvo de efeitos de card, exceto este. \r\nEste card pode realizar até 2 ataques contra monstros durante cada Fase de Batalha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24590232,'Consonância do Rei',replace(replace('Quando um monstro do oponente declarar um ataque direto: negue o ataque e, depois, você pode aplicar o resto dos efeitos deste card. \r\nBana 1 monstro Regulador e qualquer número de monstros não-Reguladores do seu Cemitério, cuja soma dos Níveis seja igual a 8 ou menos e, se isso acontecer, Invoque por Invocação-Especial do seu Deck Adicional 1 Monstro Sincro cujo Nível seja igual à soma dos Níveis desses monstros banidos. \r\n(Esta Invocação-Especial é considerada uma Invocação-Sincro.)','\r',char(13)),'\n',char(10)),'Invocar um Monstro Sincro por Invocação Especial?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24610207,'Desenhar nas Estrelas',replace(replace('Se este card for usado para uma Invocação-Xyz, você pode considerá-lo como um monstro de Nível 5. \r\nUm Monstro Xyz que foi Invocado usando este card no campo como matéria ganha este efeito.\r\n● Se for Invocado por Invocação-Xyz: compre 1 card.','\r',char(13)),'\n',char(10)),'Compre 1 card (Desenhar nas Estrelas)','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24611934,'Ryu-Kishin Potencializado','Um gárgula melhorado pelos poderes das trevas. Garras bem afiadas o tornam um forte adversário.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24621460,'Karakuri Komachi mdl 224 "Ninishi"',replace(replace('Este card deve atacar se possível. \r\nSe este card com a face para cima for escolhido como alvo de um ataque: mude sua posição de batalha. \r\nDurante sua Fase Principal, você pode Invocar por Invocação-Normal 1 monstro "Karakuri" em adição à sua Invocação-Normal/Baixar (padrão). \r\n(Você só pode se aproveitar deste efeito uma vez por turno.)','\r',char(13)),'\n',char(10)),'Alterar posição de batalha','Invocar pelo efeito de "Karakuri Komachi mdl 224 "Ninishi""','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24623598,'Desaparecer','Remova do jogo 1 card do Cemitério do seu adversário.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24634594,'Diabolantis, o Louva-a-deus Ameaçador',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro: você pode enviar monstros Inseto e/ou Planta do seu Deck para o Cemitério até o número de não-Reguladores usados para sua Invocação-Sincro. \r\nSe você controlar este card Invocado por Invocação-Sincro: você pode escolher 1 monstro Inseto ou Planta que você controla; considere-o como um Regulador até o final deste turno. \r\nVocê só pode usar cada efeito de "Diabolantis, o Louva-a-deus Ameaçador" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24635329,'Keios Qadsombraneco',replace(replace('VIRE: Você pode Invocar por Invocação-Especial 1 monstro "Sombraneco" da sua mão com a face para cima ou com a face para baixo em Posição de Defesa.\r\nSe este card for enviado para o Cemitério por um efeito de card: você pode enviar 1 monstro "Sombraneco" da sua mão para o Cemitério e, se isso acontecer, pelo resto deste turno, todos os monstros que você controla ganham ATK/DEF igual ao Nível original desse monstro enviado para o Cemitério x 100. \r\nVocê só pode usar 1 efeito de "Keios Qadsombraneco" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24639891,'Shari do Naviushi Gunkan','Finalmente consegui visitar aquele porto especializado em Naviushis Gunkan que eu estava curioso há algum tempo! Os "Shari" premiums aqui estão limitados a 2000 Naviushis por ano e usam um arroz especial suave e envelhecido que concede um requinte extra não encontrado em outras partes. Os Naviushi Gunkan servidos tinham o equilíbrio perfeito de vinagre, nigiri, brilho e forma, demonstrando uma maestria requintada. O proprietário me disse, "No futuro estaremos introduzindo um vinagre avermelhado de sabor delicioso e cheiro adocicado ao estilo EDO-FRONT," algo que me criou expectativas. Contudo, fiquei decepcionado que os mares próximos eram algo ruidosos... portanto, darei 4 estrelas com a esperança de melhoras no futuro.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24643836,'Ojamagia','Se este card for enviado da mão ou do campo para o Cemitério: adicione 1 de cada de "Ojama Verde", "Ojama Amarelo" e "Ojama Negro" do seu Deck à sua mão.','Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24643913,'Liberador Eto',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão ou do Cemitério) ao pagar metade dos seus PV enquanto seu oponente tiver um Card de Monstro no campo ou Cemitério dele com um efeito que ative na mão ou na Zona de Monstros em resposta à ativação de um card ou efeito. \r\nVocê só pode Invocar "Liberador Eto" por Invocação-Especial uma vez por turno desta forma. \r\nA Invocação-Especial deste card não pode ser negada. \r\nEste card com a face para cima não pode ser usado como matéria para uma Invocação-Fusão, Sincro, Xyz ou Link e, além disso, apenas durante o seu turno, ele não é afetado por efeitos de monstro ativados no campo do seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24644634,'Carvalho Branco de Naturia','Quando seu oponente ativar um card ou efeito que escolha este card como alvo (Efeito Rápido): você pode enviar este card do campo para o Cemitério; Invoque por Invocação-Especial 2 monstros "Naturia" de Nível 4 ou menos do seu Deck, mas eles não podem declarar um ataque e, além disso, destrua-os durante sua Fase Final.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24649931,'Materialização',replace(replace('Escolha 1 Card de Monstro com a face para cima em qualquer Zona de Magias & Armadilhas e, depois, ative 1 desses efeitos;\r\n● Invoque-o por Invocação-Especial no campo do seu dono.\r\n● Devolva-o para a mão.\r\n● Destrua-o e, depois, você pode destruir 1 monstro no campo com um Nível igual ou menor.	\r\nVocê só pode ativar 1 "Materialização" por turno.','\r',char(13)),'\n',char(10)),'Invoque por Invocação Especial o card alvo para o campo do seu dono','Retornar o card alvo para a mão','Destruir o card selecionado','Destruir o monstro no campo?','','','','','','','','','','','','');
INSERT INTO texts VALUES(24658418,'Tirano das Galáxias',replace(replace('Quando um monstro "Galáxia" que você controla for escolhido como alvo de um ataque: você pode Invocar este card por Invocação-Especial da sua mão em Posição de Defesa. \r\nQuando Invocado desta forma, você pode: imediatamente depois de resolver este efeito, Invocar por Invocação-Xyz 1 Monstro Xyz "Galáxia", usando apenas monstros "Galáxia" que você controla.','\r',char(13)),'\n',char(10)),'Invocação Especial','Invocação Xyz','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24661486,'Bruxa do Frio',replace(replace('Você pode descartar 1 card para escolher 1 monstro com a face para cima no campo; coloque um Marcador de Gelo no alvo. \r\nEste card ganha 300 de ATK para cada Marcador de Gelo no campo.','\r',char(13)),'\n',char(10)),'Colocar um marcador','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24662957,'Golem Demoníaco','Escolha 1 monstro no campo com 2000 ou mais de ATK; bana-o (até a Fase Final do próximo turno) e, depois, se você ativou este card enquanto você controlava "Dragão Vermelho Arquidemônio" ou um Monstro Sincro que o mencione, você pode Baixar 1 "Corrente Demoníaca" diretamente do seu Deck ou Cemitério.','Baixar "Corrente Demoníaca"?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24668830,'Infecção de Germes','O ATK de um monstro que não seja do Tipo Máquina equipado com este card, é diminuído em 300 pontos a cada uma das Standby Phases do controlador deste card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24672164,'Prima Florescente, a Coral Melodiosa',replace(replace('1 monstro "Maestra Melodiosa" + 1 ou mais monstros "Melodiosa"	\r\nEste card ganha 300 de ATK para cada Matéria de Fusão usada para sua Invocação-Fusão. \r\nEste card pode realizar um segundo ataque durante cada Fase de Batalha. \r\nSe este card Invocado por Invocação-Fusão for enviado para o Cemitério: você pode escolher 1 monstro "Melodiosa" no seu Cemitério; adicione-o à sua mão.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Continuar selecionando Matérias de Fusão?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24673894,'Mudar o Destino',replace(replace('Quando um monstro do oponente declarar um ataque: escolha o monstro atacante; negue o ataque e, se isso acontecer, coloque-o em Posição de Defesa e ele não pode mudar sua posição de batalha enquanto estiver com a face para cima no campo. \r\nDepois, seu oponente escolhe 1 desses efeitos.\r\n● Você (o oponente do ativador deste card) ganha PV igual à metade do ATK do alvo.\r\n● Seu oponente (o ativador deste card) sofre dano igual à metade do ATK do alvo.','\r',char(13)),'\n',char(10)),'Recuperar PV','Causar dano ao seu oponente','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24689197,'Aromági-lilith Rosalina',replace(replace('(Efeito Rápido): você pode descartar este card e, depois, escolha 1 monstro "Aromági" que você controla; ganhe PV igual à metade do ATK dele. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode Invocar por Invocação-Especial 1 monstro "Aromági" não-Regulador do seu Deck e, além disso, você não pode Invocar por Invocação-Especial pelo resto deste turno, exceto monstros Planta. \r\nVocê só pode usar cada efeito de "Aromági-lilith Rosalina" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ganhar PV','Invocar por Invocação Especial do Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24694698,'Castanha de Naturia',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode enviar 1 monstro "Naturia" do seu Deck para o Cemitério. \r\nUma vez por turno: você pode escolher 2 monstros "Naturia" no seu Cemitério; embaralhe os dois alvos no Deck e, depois, compre 1 card.','\r',char(13)),'\n',char(10)),'Enviar para o Cemitério','Comprar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24696097,'Dragão da Explosão Estelar',replace(replace('1 Monstro Sincro Regulador + "Dragão da Poeira Estelar"	\r\nUma vez por turno: você pode escavar os 5 cards do topo do seu Deck, embaralhá-los de volta no Deck e, além disso, o número máximo de ataques deste card por Fase de Batalha neste turno é igual ao número de Reguladores escavados. \r\nUma vez por turno, quando um card ou efeito for ativado que destruiria um ou mais cards no campo (Efeito Rápido): você pode negar o efeito e, se isso acontecer, destrua-o. \r\nUma vez por turno, quando um monstro do oponente declarar um ataque: você pode escolher o monstro atacante; bana este card e, se isso acontecer, negue o ataque. \r\nUma vez por turno, durante a Fase Final, se este card foi banido por seu efeito neste turno: Invoque este card por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Ataques múltiplos','Negue o efeito de destruição e destrua-o','Negar o ataque','Invocação Especial','','','','','','','','','','','','');
INSERT INTO texts VALUES(24701066,'Surdi Rio Infinisteira',replace(replace('2 monstros de Nível 5	\r\nQuando este card destruir um monstro do oponente em batalha: você pode associar esse monstro a este card. \r\nVocê só pode usar cada um dos seguintes efeitos de "Surdi Rio Infinisteira" uma vez por turno. \r\nVocê pode desassociar 1 matéria deste card; pegue 1 monstro Máquina de TERRA do seu Deck e adicione-o à sua mão ou envie-o para o Cemitério. \r\nSe este card estiver no seu Cemitério: você pode oferecer 1 Monstro Link Máquina como Tributo; Invoque este card por Invocação-Especial em Posição de Defesa.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Matéria Xyz','Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24701235,'Nikitama',replace(replace('Não pode ser Invocado por Invocação-Especial. \r\nDurante a Fase Final do turno em que este card for Invocado por Invocação-Normal ou virado com a face para cima: devolva-o para a mão. \r\nDurante o turno em que este card foi Invocado por Invocação-Normal ou virado com a face para cima, você pode Invocar por Invocação-Normal 1 monstro Espírito em adição à sua Invocação-Normal/Baixar padrão. \r\n(Você só pode se aproveitar deste efeito uma vez por turno.) \r\nQuando este card for enviado para o Cemitério: compre 1 card. \r\nVocê deve controlar um monstro Espírito para ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Invocar pelo efeito de "Nikitama"','Comprar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24707869,'Futuro Brilhante','Escolha 2 de seus monstros do Tipo Psíquico banidos; devolva ambos os alvos para o Cemitério e compre 1 card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24721709,'Caminho Quimérico',replace(replace('Escolha 1 Monstro de Efeito Mago no seu Cemitério; adicione-o à sua mão. \r\nVocê só pode ativar 1 "Caminho Quimérico" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24725825,'Vírus Elétrico','Você pode descartar este card para o Cemitério e, depois, escolha 1 monstro Máquina ou Dragão que seu oponente controla; tome o controle do alvo até a Fase Final.','Tomar controle','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24731391,'Feiticeiro Ciberso',replace(replace('Você pode Invocar este card por Invocação-Ritual com "Cinet Ritual". \r\nQualquer dano que você sofrer é reduzido pela metade. \r\n(Você não pode reduzir o mesmo dano pela metade duas vezes desta forma.) \r\nEnquanto você controlar um Monstro Link, os monstros que seu oponente controla não podem escolher monstros que você controla como alvo de ataques, exceto este e, além disso, seu oponente não pode escolher monstros que você controla como alvo de efeitos de card, exceto este. \r\nSe este card batalhar um Monstro Link, ele ganha 1000 de ATK apenas durante o cálculo de dano. \r\nSe este card em sua posse for destruído por um efeito de card do oponente: você pode adicionar 1 monstro Ciberso do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24731453,'Trator de Neve Ultraveloz',replace(replace('Quando um monstro do seu oponente declarar um ataque direto, enquanto você controlar um ou mais cards na sua Zona de Magias & Armadilhas: você pode Invocar este card por Invocação-Especial da sua mão e, depois, destrua tantos cards na sua Zona de Magias & Armadilhas quanto possível e, se isso acontecer, cause 200 de dano ao seu oponente para cada card destruído. \r\nVocê não pode Invocar monstros por Invocação-Especial, exceto monstros Máquina.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24749710,'Embaralhamento Mental',replace(replace('Durante o turno de qualquer duelista: você pode adicionar 1 monstro que mencione "Ritual da Luz e das Trevas" do seu Deck à sua mão e, depois, descarte 1 card. \r\nVocê só pode usar este efeito de "Embaralhamento Mental" uma vez por turno. \r\nQuando seu oponente ativar um card ou efeito: você pode devolver 1 monstro de Nível 7 ou mais que você controla para a mão; Invoque por Invocação-Especial 1 monstro que mencione "Ritual da Luz e das Trevas" da sua mão, com um nome diferente que o do monstro devolvido, ignorando suas condições de Invocação. \r\nVocê não pode ativar esses efeitos de "Embaralhamento Mental" na mesma Corrente.','\r',char(13)),'\n',char(10)),'Efeito de busca','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24779554,'Rucia da Floresta Branca',replace(replace('Se você controlar um monstro "Floresta Branca": você pode Invocar este card por Invocação-Especial da sua mão. \r\nVocê pode enviar 1 Magia/Armadilha da sua mão ou do campo para o Cemitério; compre 1 card. \r\nSe este card estiver no seu Cemitério (Efeito Rápido): você pode escolher 1 Monstro Sincro "Floresta Branca" que você controla ou no seu Cemitério; devolva-o para o Deck Adicional e, se isso acontecer, Invoque este card por Invocação-Especial, mas negue seus efeitos. \r\nVocê só pode usar cada efeito de "Rucia da Floresta Branca" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Comprar','Invocar por Invocação Especial do Cemitério','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24793135,'Pergaminhos Sagrados da Lenda Bugiganga',replace(replace('Durante sua Fase Principal: você pode escavar os 3 cards do topo do seu Deck e, se isso acontecer, você pode adicionar à sua mão 1 monstro Máquina escavado cujo ATK seja igual à sua própria DEF e, além disso, bana os cards restantes com a face para baixo. \r\nVocê só pode usar este efeito de "Pergaminhos Sagrados da Lenda Bugiganga" uma vez por turno. \r\nSempre que um ou mais monstros Máquina, cujo ATK seja igual à sua própria DEF, forem Invocados por Invocação-Normal ou Especial, coloque 1 marcador neste card. \r\nEnquanto este card tiver 10 ou mais marcadores, nenhum duelista pode ativar os efeitos de monstros no campo cujo ATK não seja igual à sua própria DEF.','\r',char(13)),'\n',char(10)),'','Escolher 1 card para adicionar à mão?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24799107,'Dragãozela Sheou',replace(replace('1 monstro "Dragãozela" + 1 monstro Dragão de Nível 5 ou mais	\r\nDurante cada Fase de Apoio: você pode Invocar por Invocação-Especial 1 monstro "Dragãozela" de Nível 9 ou menos da sua mão ou do Cemitério. \r\nQuando seu oponente ativar um card ou efeito (Efeito Rápido): você pode negar a ativação e, se isso acontecer, destrua esse card e, além disso, depois, devolva este card para o Deck Adicional e, se isso acontecer, Invoque por Invocação-Especial 1 "Dragãozela Caseira" do seu Deck Adicional. \r\nVocê só pode usar cada efeito de "Dragãozela Sheou" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24838456,'O Chamado da Vaidade',replace(replace('Ative apenas como Elo de Corrente 4 ou mais. \r\nPague metade dos seus PV. \r\nNegue a ativação e efeitos de todos os outros cards na mesma Corrente e destrua-os.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24839398,'Aglutinador de Armadilhas',replace(replace('O monstro equipado ganha 400 de ATK para cada Armadilha no seu Cemitério. \r\nVocê só pode usar cada um dos seguintes efeitos de "Aglutinador de Armadilhas" uma vez por turno. \r\nDepois do cálculo de dano, se o monstro equipado destruiu um monstro do oponente em batalha ou causou dano de batalha ao seu oponente: você pode enviar este card para o Cemitério; Baixe 1 Armadilha do seu Cemitério. \r\nSe uma ou mais Armadilhas com a face para cima que você controla seriam destruídas por um efeito de card, em vez disso, você pode banir este card que você controla.','\r',char(13)),'\n',char(10)),'','Baixar um Card Armadilha do Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24842059,'Linguriboh',replace(replace('1 monstro Ciberso de Nível 4 ou menos	\r\nQuando seu oponente ativar um Card de Armadilha (Efeito Rápido): você pode oferecer este card como Tributo; negue o efeito desse card e, se isso acontecer, bana-o. \r\nSe este card estiver no seu Cemitério (Efeito Rápido): você pode oferecer como Tributo 1 monstro "@Ignister" que foi Invocado por Invocação-Especial do Deck Adicional; Invoque este card por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Linguriboh" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24845628,'Esfregão Encantado Poerio',replace(replace('Você só pode controlar 1 "Esfregão Encantado Poerio". \r\nO monstro equipado não pode ser oferecido como Tributo nem ser usado como Matéria Fusão, Sincro ou Xyz para uma Invocação. \r\nQuando este card que você controla for destruído por um efeito de card do oponente e enviado para o seu Cemitério: você pode adicionar 1 monstro "Poerio" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24857466,'Van''Dalgyon, o Senhor do Dragão Negro',replace(replace('Se você negar a ativação de um ou mais Cards de Magia/Armadilha do oponente ou de um ou mais efeitos de monstro do oponente, com um Card de Resposta (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe Invocado desta forma, ative esses efeitos e resolva-os em sequência, dependendo do(s) tipo(s) de card(s) negado(s) pela Armadilha de Resposta:\r\n● Magia: Cause 1500 de dano ao seu oponente.\r\n● Armadilha: Escolha 1 card que seu oponente controla; destrua o alvo.\r\n● Monstro: Escolha 1 monstro no seu Cemitério; Invoque-o por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Invocação Especial','Cause 1500 de dano ao seu oponente','Escolha 1 card que seu oponente controla para destruí-la','Escolha 1 monstro no seu Cemitério; Invoque-o por Invocação Especial','','','','','','','','','','','','');
INSERT INTO texts VALUES(24861088,'Cronomalia Disco de Nebra',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode adicionar 1 card "Cronomalia" do seu Deck à sua mão, exceto "Cronomalia Disco de Nebra". \r\nSe este card estiver no Cemitério e todos os monstros que você controla forem monstros "Cronomalia" (mín. 1): você pode Invocar este card por Invocação-Especial em Posição de Defesa. \r\nVocê não pode ativar cards ou efeitos durante o turno em que você ativar este efeito, exceto cards e efeitos "Cronomalia". \r\nVocê só pode usar 1 efeito de "Cronomalia Disco de Nebra" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24874630,'Santuário do Demônio',replace(replace('Invoque por Invocação-Especial 1 "Ficha de Demônio de Metal" (Demônio/TREVAS/Nível 1/ATK 0/DEF 0). \r\nEla não pode atacar. \r\nSeu oponente sofre qualquer dano de batalha que você teria sofrido das batalhas que a envolvem. \r\nUma vez por turno, durante sua Fase de Apoio, pague 1000 PV ou destrua essa Ficha.','\r',char(13)),'\n',char(10)),'Pagar 1000 PV para manter "Ficha de Demônio de Metal"?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24874631,'Ficha de Demônio de Metal','Invocado por Especial com o efeito "Santuário do Demônio". Esta Ficha não pode atacar. O oponente sofre qualquer dano de batalha que você teria sofrido em batalhas envolvendo esta Ficha. Durante cada uma das suas Fases de Apoio, pague 1000 Pontos de Vida ou destrua esta Ficha.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24878656,'Caixa de Brinquedos',replace(replace('Uma vez por turno, quando um monstro do oponente declarar um ataque: você pode enviar 1 card com a face para baixo que você controla para o Cemitério; destrua esse monstro do oponente. \r\nUma vez por turno: você pode ativar 1 desses efeitos;\r\n● Selecione até 2 monstros com "Brinquedo" em seus nomes originais da sua mão, do Deck, da Zona de Monstros com a face para cima e/ou do Cemitério, que possam Baixar a si mesmos da mão como uma Magia e Baixe-os na sua Zona de Magias & Armadilhas como Magias.\r\n● Destrua até 2 cards na sua Zona de Magias & Armadilhas.','\r',char(13)),'\n',char(10)),'Baixar um monstro','Destrua os cards na sua Zona de Magias & Armadilhas','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24882256,'Fênix de Fogo @Ignister',replace(replace('2+ monstros Ciberso	\r\nDurante o cálculo de dano, se este card atacar: você pode causar dano ao seu oponente igual ao ATK deste card e, se isso acontecer, seu oponente não sofre dano de batalha dessa batalha. \r\nSe este card for destruído por um efeito de card: você pode destruir 1 monstro que seu oponente controla. \r\nDurante a próxima Fase de Apoio depois que este card Invocado por Invocação-Link foi destruído e enviado para o Cemitério: você pode Invocar este card por Invocação-Especial do seu Cemitério. \r\nVocê só pode usar cada efeito de "Fênix de Fogo @Ignister" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24892828,'Retornado da Tistina',replace(replace('Se este card estiver na sua mão: você pode escolher 1 monstro "Tistina" que você controla, exceto "Retornado da Tistina"; Invoque este card por Invocação-Especial e, se isso acontecer, seu Nível se torna o Nível do monstro alvo. \r\nSe este card estiver no seu Cemitério: você pode escolher 1 Monstro Xyz Aqua que você controla; associe este card a ele como matéria. \r\nVocê só pode usar cada efeito de "Retornado da Tistina" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Como Matéria Xyz','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24903843,'Paleozoico Pikaia',replace(replace('Descarte 1 card "Paleozoico" e, depois, compre 2 cards. \r\nUma vez por Corrente, quando um Card de Armadilha for ativado enquanto este card estiver no seu Cemitério: Invoque este card por Invocação-Especial como um Monstro Normal (Tipo Aqua/ÁGUA/Nível 2/ATK 1200/DEF 0).	\r\n(Este card NÃO é considerado como um Card de Armadilha.) \r\nSe Invocado desta forma, este card não é afetado por efeitos de monstro e, além disso, bana-o quando ele deixar o campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24907044,'Ator do Abismo - Atriz Principal',replace(replace('Escala de Pêndulo = 2\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno, quando você sofrer dano de batalha de um monstro atacante do oponente: você pode ativar 1 desses efeitos;\r\n● Esse monstro do oponente perde ATK igual ao dano que você sofreu (mesmo que este card deixe o campo).\r\n● Adicione 1 Monstro Pêndulo "Ator do Abismo" com a face para cima do seu Deck Adicional à sua mão com ATK menor ou igual ao dano que você sofreu.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nUma vez por turno, quando o dano de batalha for causado: você pode escolher 1 monstro com a face para cima que seu oponente controla; ele perde ATK igual a esse dano de batalha. \r\nQuando este card for destruído em batalha, ou se este card na Zona de Monstros do seu dono for destruído por um efeito de card do oponente: você pode Baixar 1 Magia "Script do Abismo" diretamente do seu Deck.','\r',char(13)),'\n',char(10)),'Reduzir ATK','Adicione à sua mão um Monstro Pêndulo do seu Deck Adicional','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24915933,'Granguignol, o Dragão do Crepúsculo',replace(replace('"Ardente Cartesia, a Virtuosa" + 1 monstro de LUZ ou de TREVAS	\r\nSe este card for Invocado por Invocação-Fusão: você pode enviar para o Cemitério 1 monstro de LUZ ou de TREVAS de Nível 6 ou mais do seu Deck ou Deck Adicional. \r\nSe um monstro for Invocado por Invocação-Especial por um efeito de monstro ativado do seu oponente (exceto durante a Etapa de Dano): você pode banir este card do seu campo ou do Cemitério; Invoque por Invocação-Especial 1 monstro "Dogmatika" do seu Deck ou 1 monstro "Despia" do seu Deck Adicional. \r\nVocê só pode usar cada efeito de "Granguignol, o Dragão do Crepúsculo" uma vez por turno.','\r',char(13)),'\n',char(10)),'Enviar do Deck para o Cemitério','Invocar por Invocação Especial do Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24919805,'Automotora Brigona',replace(replace('Uma vez por turno: você pode causar 500 de dano ao seu oponente. \r\nVocê não pode conduzir sua Fase de Batalha no turno em que ativar este efeito. \r\nDurante a Fase Final, se este card estiver no Cemitério porque foi enviado para lá neste turno: você pode adicionar 1 monstro Máquina de TERRA de Nível 10 do seu Deck à sua mão. \r\nVocê só pode este efeito de "Automotora Brigona" uma vez por turno.','\r',char(13)),'\n',char(10)),'Causar dano aos PV','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24920410,'Supercorda',replace(replace('Escolha 1 monstro "de Corda" com a face para cima que você controla; o ATK e DEF dele são dobrados e ele é devolvido para a mão durante a Fase Final. \r\nVocê só pode ativar 1 "Supercorda" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24925387,'Condutora Adamancipador',replace(replace('Se este card está na sua mão: você pode colocar 1 outro card "Adamancipador" da sua mão no topo do Deck; Invoque este card por Invocação-Especial.\r\nDurante sua Fase Principal: você pode escavar os 5 cards do topo do seu Deck, e se fizer, você pode Invocar por Invocação-Especial 1 monstro Rocha de Nível 4 ou menor escavado, coloque também o resto no fundo do Deck em qualquer ordem.\r\nVocê só pode usar cada um dos efeitos de "Condutora Adamancipador" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Escavar o Deck','Invocar por Invocação Especial o monstro?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24940422,'Luz de Sekka',replace(replace('Se você não tiver nenhuma Magia/Armadilha no seu Cemitério: compre 2 cards e, além disso, pelo resto deste Duelo depois que você ativar este card, você não pode ativar Cards ou efeitos de Magia/Armadilha, exceto "Luz de Sekka". \r\nVocê pode banir este card do seu Cemitério; revele 1 monstro na sua mão, embaralhe-o no Deck e, depois, compre 1 card. \r\nVocê só pode usar cada efeito de "Luz de Sekka" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar','Retornar ao Deck e comprar 1 card','O efeito de "Luz de Sekka" está sendo aplicado.','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24943456,'T.G. Gladiador Poderoso',replace(replace('1 Regulador + 1 ou mais monstros "T.G." não-Reguladores	\r\nSe este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente. \r\nSe este card no campo for destruído: compre 1 card.','\r',char(13)),'\n',char(10)),'Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24996659,'Watt-Kiwi','Monstros "Watt" que você controla não podem ser destruídos em batalha enquanto eles estiverem atacando.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25005816,'Inspiração','Escolha 1 monstro com a face para cima que você controla; ele ganha 700 de ATK até o final deste turno.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25034083,'Iscaroide','Enquanto este card estiver com a face para cima no seu lado do campo, seu oponente não pode selecionar um monstro com a face para cima como alvo de um ataque, exceto "Iscaroide".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25050038,'Cura em Cadeia',replace(replace('Ganhe 500 PV. \r\nSe este card tiver sido ativado como Elo de Corrente 2 ou 3, adicione-o ao Deck e embaralhe. \r\nSe este card tiver sido ativado como Elo de Corrente 4 ou mais, devolva-o à mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25067275,'Espadas da Alvorada',replace(replace('Escolha 1 Card de Magia de Equipamento no seu Cemitério e 1 monstro apropriado no campo; equipe o Card de Magia de Equipamento a esse monstro. \r\nDestrua esse Card de Magia de Equipamento durante a Fase Final. \r\nSe você ativar este card, você não pode Invocar por Invocação-Especial pelo resto do turno. \r\nVocê só pode ativar 1 "Espadas da Alvorada" por turno.','\r',char(13)),'\n',char(10)),'Escolha um Card de Equipamento no Cemitério','Escolha o alvo a equipar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25072579,'Protótipo de Força Celeste - Ás - Amatsu',replace(replace('1 monstro "Força Celeste - Ás"	\r\nVocê só pode Invocar um ou mais "Protótipo de Força Celeste - Ás - Amatsu" por Invocação-Especial uma vez por turno. \r\nQuando um monstro que seu oponente controla com 2000 ou mais de ATK ativar seu efeito (Efeito Rápido): você pode fazer com que o efeito ativado se torne "Destrua 1 Monstro Link "Força Celeste - Ás" que seu oponente controla". \r\nQuando um ataque for declarado envolvendo este card e um monstro do oponente: você pode escolher 1 monstro "Força Celeste - Ás" que você controla e 1 card que seu oponente controla; destrua-os. \r\nVocê só pode usar cada efeito de "Protótipo de Força Celeste - Ás - Amatsu" uma vez por turno.','\r',char(13)),'\n',char(10)),'Efeito de alterar','Destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25090294,'Botão de Rosa','Ofereça como Tributo 1 "Knospe, o HERÓI do Elemento"; Invoque por Invocação-Especial 1 "Rosa Venenosa, o HERÓI do Elemento" da sua mão ou Deck.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25096909,'Canhões das Equações Simultâneas',replace(replace('Bana, do seu Deck Adicional, 1 Monstro de Fusão e 2 Monstros Xyz com a mesma Classe, cujos Níveis e Classes combinados sejam iguais ao número total de cards nas mãos dos dois duelistas e no campo e, depois, você pode aplicar este efeito.\r\n● Devolva 2 dos seus monstros banidos para o Deck Adicional (1 Xyz e 1 de Fusão) cujos Níveis e Classes combinados sejam iguais ao Nível ou à Classe de 1 monstro com a face para cima que seu oponente controla e, depois, bana todos os cards que ele controla.','\r',char(13)),'\n',char(10)),'','Recuperar um monstro e banir um card do seu oponente?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25109950,'O Pequeno Espadachim de Aile','Ofereça 1 monstro no seu Campo como Tributo para aumentar o ATK deste monstro em 700 pontos até ao final do turno.','Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25119460,'YZ - Dragão Tanque',replace(replace('"Cabeça de Dragão Y" + "Tanque Metálico Z"	\r\nPrimeiro deve ser Invocado por Invocação-Especial (do seu Deck Adicional) ao banir os cards acima que você controla. \r\n(Você não usa "Polimerização".) \r\nNão pode ser Invocado por Invocação-Especial do Cemitério. \r\nVocê pode descartar 1 card e, depois, escolha 1 monstro com a face para baixo que seu oponente controla; destrua o alvo.','\r',char(13)),'\n',char(10)),'Destruir um monstro','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25123082,'Livro de Magia do Poder',replace(replace('Escolha 1 monstro Mago que você controla; neste turno, ele ganha 1000 de ATK. \r\nE, se isso acontecer, sempre que ele destruír um monstro do oponente em batalha neste turno: você pode adicionar 1 Magia "Livro de Magia" do seu Deck à sua mão. \r\nVocê só pode ativar 1 "Livro de Magia do Poder" por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25123713,'Dyna, o Heroi de Peluguel',replace(replace('Se este card for Invocado por Invocação-Especial: você pode banir cards do Cemitério do seu oponente, até o numero de monstros "de Peluguel" que você controla com nomes diferentes. \r\nVocê só pode usar este efeito de "Dyna, o Heroi de Peluguel" uma vez por turno. \r\nMonstros que seu oponente controla não podem escolher monstros "de Peluguel" que você controla como alvo de ataques, exceto este.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25131968,'Ken, o Dragão Guerreiro',replace(replace('Uma vez por turno, no final da Fase de Batalha: devolva este card do campo para a mão. \r\nVocê só pode usar cada um dos seguintes efeitos de "Ken, o Dragão Guerreiro" uma vez por turno. \r\nDurante sua Fase Principal: você pode Invocar por Invocação-Especial 1 "Gen, o Tigre de Diamante" da sua mão ou do Deck no campo do seu oponente em Posição de Defesa. \r\nSe este card for Invocado por Invocação-Especial pelo efeito de "Gen, o Tigre de Diamante": seu oponente compra 2 cards e, depois, ele descarta 1 card.','\r',char(13)),'\n',char(10)),'Retornar para a mão','Invocar "Gen, o Tigre de Diamante" por Invocação Especial','Comprar e descartar','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25132288,'Dragão Final de Luz',replace(replace('1 Regulador + 1 ou mais monstros de LUZ não-Reguladores	\r\nNa declaração de ataque, se este card batalhar com outro monstro: Você pode fazer com que este card perca 500 de ATK and DEF (permanentemente), e o monstro com o qual este card está batalhando perde 1500 de ATK and DEF até a Fase Final.','\r',char(13)),'\n',char(10)),'Reduzir ATK/DEF','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25137581,'"B" Furtiva',replace(replace('Quando seu oponente Invocar um ou mais monstros por Invocação-Especial (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão com a face para baixo em Posição de Defesa e, se isso acontecer, durante a Fase Final deste turno, coloque-o com a face para cima em Posição de Defesa. \r\nVocê só pode usar este efeito de ""B" Furtiva" uma vez por turno. \r\nSe este card for virado com a face para cima durante a Fase Final: destrua todos os monstros no campo que foram Invocados por Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25140659,'Perigo! Equipe de Resposta',replace(replace('Escolha 1 monstro "Perigo!" que você controla e 1 monstro no campo; devolva-os para a mão. \r\nSe este card estiver no Cemitério: você pode descartar 1 monstro "Perigo!"; coloque este card no fundo do Deck e, depois, compre 1 card. \r\nVocê só pode usar cada efeito de "Perigo! Equipe de Resposta" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25148255,'Âncora Sucata',replace(replace('Para uma Invocação-Sincro, você pode substituir este card por qualquer 1 Regulador "Sincron". \r\nUma vez por turno: você pode descartar 1 card e, depois, escolha 1 monstro não-Regulador "Sucata" no seu Cemitério; Invoque o alvo por Invocação-Especial e, se isso acontecer, imediatamente depois que este efeito resolver, Invoque por Invocação-Sincro 1 Monstro Sincro que mencione um Regulador "Sincron" como matéria, usando apenas esse monstro e este card. \r\nEssas Matérias Sincro são banidas em vez de serem enviadas para o Cemitério.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25158975,'HERÓI do Destino – Dogma Morte',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão ou Cemitério) banindo 3 monstros Guereiros e/ou TREVAS do seu Cemitério. \r\nVocê só pode Invocar por Invocação-Especial "HERÓI do Destino – Dogma Morte" uma vez por turno dessa forma.\r\nSe for Invocado dessa forma: você pode ativar este efeito; cause 2000 de dano ao seu oponente durante a próxima Fase de Apoio.\r\nUma vez por turno, quando seu oponente ativar um card ou efeito (Efeito Rápido): você pode Invocar por Invocação-Fusão 1 monstro Guerreiro ou TREVAS do seu Deck Adicional, ao embaralhar suas matérias da sua mão, campo e/ou Cemitério no Deck.','\r',char(13)),'\n',char(10)),'','Causar dano','Invocação Fusão','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25163248,'Cronomalia Máquina Maia','Este card pode ser considerado como 2 Tributos para a Invocação-Tributo de um monstro do Tipo Máquina.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25163979,'Pesadelo do Legado Mundial',replace(replace('Você não sofre dano de batalha de ataques envolvendo seus monstros co-linkados. \r\nUma vez por turno: você pode ativar 1 desses efeitos;\r\n● Mova 1 monstro "Cavaleiro(a) do Pesadelo" que você controla para outra das suas Zonas de Monstros Principais.\r\n● Troque o local de 2 monstros "Cavaleiro(a) do Pesadelo" nas suas Zonas de Monstros Principais.','\r',char(13)),'\n',char(10)),'','Mover a posição','Trocar posições','Escolha 1 monstro para mover','','','','','','','','','','','','');
INSERT INTO texts VALUES(25165047,'Dragão do Fluxo de Vida',replace(replace('1 Regulador + "Dragão Ferramenteiro"	\r\nQuando este card for Invocado por Invocação-Sincro: você pode fazer com que seus PV se tornem 4000. \r\nVocê não sofre dano de efeito. \r\nSe este card com a face para cima no campo seria destruído, em vez disso, você pode banir 1 Card de Magia de Equipamento do seu Cemitério.','\r',char(13)),'\n',char(10)),'Seus PV se tornam 4000','Banir 1 Magia de Equipamento em vez de ser destruída?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25166510,'Salamagrande Bisão Brigão',replace(replace('Se você tiver 3 ou mais monstros "Salamagrande" no seu Cemitério: você pode Invocar este card por Invocação-Especial da sua mão em Posição de Defesa. \r\nVocê pode escolher Monstros Link de FOGO no seu Cemitério, até o número de cards com a face para cima que seu oponente controla; devolva-os para o Deck Adicional e, depois, você pode negar os efeitos de cards com a face para cima que seu oponente controla até o final deste turno, até o número de cards que você devolveu. \r\nVocê só pode usar cada efeito de "Salamagrande Bisão Brigão" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Negar o card selecionado?','Escolha 1 card para negar','','','','','','','','','','','','');
INSERT INTO texts VALUES(25171661,'Anão Inférnico','Enquanto você não tiver cards na sua mão, se um monstro que você controla atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25173686,'Sequência de Naipe','Se seu oponente controlar um card em cada uma das Zonas de Magias & Armadilhas dele: destrua todos os cards nas Zonas de Magias & Armadilhas dele.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25191307,'Ataqueraptor - Abutre Florescente',replace(replace('Se você não controlar nenhum monstro com a face para cima, que não sejam monstros Besta Alada: você pode Invocar por Invocação-Especial tanto este card quanto 1 monstro "Ataqueraptor" da sua mão. \r\nSe você não controlar nenhum monstro: você pode escolher 2 monstros "Ataqueraptor" de Nível 4 ou menos no seu Cemitério, incluindo este card; Invoque-os por Invocação-Especial em Posição de Defesa. \r\nVocê só pode usar 1 efeito de "Ataqueraptor - Abutre Florescente" por turno e apenas uma vez por turno e, além disso, você não pode Invocar monstros por Invocação-Especial no turno em que ativar qualquer um destes efeitos, exceto monstros de TREVAS.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25200959,'Integrador Ciberso',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro, você pode: Invocar por Invocação-Especial 1 Regulador Ciberso da sua mão ou do Cemitério em Posição de Defesa e, além disso, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros Ciberso. \r\nSe este card Invocado por Invocação-Sincro for enviado para o Cemitério: você pode comprar 1 card. \r\nVocê só pode usar cada efeito de "Integrador Ciberso" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25206027,'Dragão Interplanetariopurpuraespinhoso','Se um monstro que você controla for destruído em batalha ou por um efeito de card e enviado para o Cemitério: você pode Invocar este card por Invocação-Especial da sua mão.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25209168,'Troca de Desespero e Esperança',replace(replace('Se você controlar 3 ou mais monstros Fada de TERRA: envie tantos monstros do campo para o Cemitério quanto possível (mín. 1) e, depois, cada duelista pode Invocar monstros por Invocação-Especial do Cemitério do oponente dele para o campo dele, até o número de monstros enviados para o Cemitério do oponente dele por este efeito e, depois, se um monstro foi Invocado por Invocação-Especial por este efeito e "Troca de Espírito" estiver no seu Cemitério, você pode Baixar 1 Armadilha diretamente do seu Deck. \r\nEla pode ser ativada neste turno. \r\nVocê só pode ativar 1 "Troca de Desespero e Esperança" por turno.','\r',char(13)),'\n',char(10)),'','Invocar um monstro por Invocação Especial do Cemitério do seu oponente?','Baixar um Card Armadilha do seu Deck?','Ativar aplicando o efeito de "Troca de Desespero e Esperança".','','','','','','','','','','','','');
INSERT INTO texts VALUES(25218587,'Égide Luminosa',replace(replace('Escolha cards com a face para cima que seu oponente controla, até o número de monstros "Luminoso(a)" que você controla; negue os efeitos deles até o final deste turno. \r\nSe este card for enviado do Deck para o Cemitério: você pode Baixar este card. \r\nVocê só pode usar cada efeito de "Égide Luminosa" uma vez por turno.','\r',char(13)),'\n',char(10)),'Negar','Baixar no campo','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25221249,'Vespabatalha - Ninho',replace(replace('Quando um monstro "Vespabatalha" seu for escolhido como alvo de um ataque: Invoque por Invocação-Especial 1 monstro "Vespabatalha" da sua mão ou do Deck e, se isso acontecer, coloque 1 marcador neste card e, depois, encerre a Fase de Batalha. \r\nVocê só pode usar este efeito de "Vespabatalha - Ninho" uma vez por turno. \r\nSe este card tiver 2 ou mais marcadores durante a Fase Final, envie-o para o Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25224340,'Mãos do Pesadelo',replace(replace('Envie 1 monstro Ilusão do seu Deck para o Cemitério. \r\nDurante sua Fase Principal, se você controlar um monstro Ilusão de Nível 5 ou mais: você pode banir este card do seu Cemitério e, depois, escolha 1 monstro no Cemitério do seu oponente; Invoque-o por Invocação-Especial no seu campo, mas bana-o durante a Fase Final do próximo turno. \r\nVocê só pode usar 1 efeito de "Mãos do Pesadelo" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar','Invocação Especial','Invocado por Invocação Especial pelo efeito de "Mãos do Pesadelo"','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25231813,'Asa Prateada',replace(replace('Só pode ser equipado a um Monstro Sincro do Tipo Dragão de Nível 8 ou mais. \r\nDuas vezes por turno, ele não pode ser destruído em batalha. \r\nSe ele seria destruído por um efeito de card, em vez disso, você pode destruir este card.','\r',char(13)),'\n',char(10)),'Usar o efeito de "Asa Prateada" em vez de ser destruído?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25236056,'Dragão de Metal Raro','Este card não pode ser Invocado por Invocação-Normal ou Baixado.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25244515,'Yosenju Tsujik',replace(replace('Durante a Fase Final, se este card foi Invocado por Invocação-Normal neste turno: devolva-o para a mão. \r\nVocê só pode usar cada um desses efeitos de "Yosenju Tsujik" uma vez por turno.\r\n● Durante a Etapa de Dano de qualquer duelista, quando um monstro "Yosenju" que você controla batalhar um monstro do oponente: você pode descartar este card; esse monstro que você controla ganha 1000 de ATK até o final deste turno.\r\n● Você pode escolher 1 monstro "Yosenju" no campo; ele ganha 1000 de ATK até o final deste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25247218,'Golem de Fragmento Grande','Se seu oponente controlar um monstro e você não controlar nenhum monstro, você pode Invocar este card por Invocação-Normal sem oferecer Tributo.','Invocar sem oferecer Tributo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25259669,'Goblindbergh','Quando este card for Invocado por Invocação-Normal: você pode Invocar 1 monstro de Nível 4 ou menos por Invocação-Especial da sua mão e, além disso, depois, colocar este card em Posição de Defesa.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25262697,'Assaltante do Coveiro','Quando este card declarar um ataque enquanto "Necro-Vale" estiver no campo: você pode escolher 1 monstro com a face para cima que seu oponente controla; mude a posição de batalha do alvo.','Mudar a posição de batalha','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25273572,'G Golem Cão Rochoso',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode adicionar à sua mão ou Invocar por Invocação-Especial 1 "G Golem Cão Rochoso" do seu Deck e, além disso, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros Ciberso. \r\nSe este card for enviado da mão para o Cemitério: você pode adicionar 1 card "G Golem" do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "G Golem Cão Rochoso" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25274141,'Escala Urgente',replace(replace('Se seu oponente controlar mais monstros que você: Invoque por Invocação-Especial 1 monstro Máquina de TERRA de Nível 4 ou menos e 1 monstro Máquina de TERRA de Nível 5 ou mais do seu Deck, em Posição de Defesa, mas negue seus efeitos. \r\nVocê não pode declarar ataques no turno em que ativar este card, exceto com monstros Máquina. \r\nSe este card Baixado for enviado do campo para o Cemitério: você pode adicionar 1 monstro Máquina de Nível 10 do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "Escala Urgente" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25280974,'Legião Demoníaca de Bobos da Corte',replace(replace('Durante sua Fase Principal, você pode Invocar por Invocação-Tributo 1 monstro Mago em Posição de Ataque, em adição à sua Invocação-Normal/Baixar (padrão). \r\n(Você só pode se aproveitar deste efeito uma vez por turno.) \r\nSe este card for enviado do campo para o Cemitério: você pode adicionar 1 Monstro Normal Mago do seu Deck ou Cemitério à sua mão. \r\nVocê só pode usar este efeito de "Legião Demoníaca de Bobos da Corte" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Invocar pelo efeito de "Legião Demoníaca de Bobos da Corte"','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25290459,'Subida de Nível!','Envie 1 monstro "LV" com a face para cima que você controla para o Cemitério; Invoque por Invocação-Especial 1 monstro da sua mão ou do Deck que esteja listado no texto do monstro enviado, ignorando suas condições de Invocação.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25311006,'Talento da Tática Tripla',replace(replace('Se seu oponente ativou um efeito de monstro durante sua Fase Principal neste turno: ative 1 desses efeitos;\r\n● Compre 2 cards.\r\n● Tome o controle de 1 monstro que seu oponente controla até a Fase Final.\r\n● Olhe a mão do seu oponente e selecione 1 card dela para embaralhar no Deck.	\r\nVocê só pode ativar 1 "Talento da Tática Tripla" por turno.','\r',char(13)),'\n',char(10)),'Compre 2 cards','Ganhe o controle de 1 monstro que seu oponente controla até a Fase Final','Olhe a mão do seu oponente e depois escolha 1 card para embaralhar no Deck','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25334372,'Corte Tsukumo',replace(replace('Se um monstro que você controla atacar um monstro cujo ATK, durante o cálculo de dano, seja maior que o dele mesmo: seu monstro que está batalhando ganha ATK igual à diferença entre os seus PV e os do seu oponente, apenas durante o cálculo de dano. \r\nVocê só pode ativar 1 "Corte Tsukumo" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25339070,'Senhor Obscuro Nasten',replace(replace('Você pode descartar 2 outros cards "Senhor(a) Obscuro(a)"; Invoque este card por Invocação-Especial da sua mão. \r\n(Efeito Rápido): você pode pagar 1000 PV e, depois, escolha 1 Magia/Armadilha "Senhor(a) Obscuro(a)" no seu Cemitério; aplique o efeito do alvo e, depois, embaralhe o alvo no Deck. \r\nVocê só pode usar este efeito de "Senhor Obscuro Nasten" uma vez por turno. \r\nVocê só pode Invocar um ou mais "Senhor Obscuro Nasten" por Invocação-Especial uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25341652,'Maestroke, o Djinn da Sinfonia',replace(replace('2 monstros de Nível 4	\r\nUma vez por turno: você pode desassociar 1 Matéria Xyz deste card e, depois, escolher 1 monstro com a face para cima em Posição de Ataque que seu oponente controla; coloque-o com a face para baixo em Posição de Defesa. \r\nSe um Monstro Xyz "Djinn" que você controla seria destruído, em vez disso, você pode desassociar 1 Matéria Xyz desse monstro.','\r',char(13)),'\n',char(10)),'Mudar para Posição de Defesa com a face para baixo','Usar o efeito de "Maestroke, o Djinn da Sinfonia" em vez de ser destruído?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25342956,'Cavaleiro-Gema Diamante Mestre Disperso',replace(replace('3 monstros "-Gema"	\r\nDurante a Fase Principal (Efeito Rápido): você pode enviar este card do campo para o Cemitério; Invoque por Invocação-Especial até 3 monstros "-Gema" que não sejam Rocha com nomes diferentes do seu Deck Adicional e/ou Cemitério, ignorando suas condições de Invocação e, além disso, pelo resto deste turno, você não pode Invocar por Invocação-Especial do Deck Adicional, exceto Monstros de Fusão. \r\nQuando um Monstro de Fusão "Cavaleiro-Gema" seu for destruído em batalha, enquanto este card estiver no seu Cemitério: você pode Invocar este card por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Cavaleiro-Gema Diamante Mestre Disperso" uma vez por turno.','\r',char(13)),'\n',char(10)),'Enviar para o Cemitério para Invocar por Invocação Especial','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25343017,'Clérigo Psíquico Silenciado',replace(replace('Se este card for Invocado por Invocação-Normal ou Virar: coloque-o em Posição de Defesa. \r\nUma vez por turno: você pode enviar 1 card da sua mão para o Cemitério e, depois, escolher 1 monstro do Tipo Psíquico no seu Cemitério; bana o alvo. \r\nSe este card for enviado do campo para o Cemitério: escolha 1 monstro banido pelo efeito deste card; Invoque o alvo por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Mudar para Posição de Defesa','Banir','Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25343280,'Espírito de Faraó',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial por "O Primeiro Sarcófago". \r\nQuando este card for Invocado por Invocação-Especial: você pode escolher até 4 Monstros Normais Zumbi de Nível 2 ou menos no seu Cemitério; Invoque os alvos por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25345186,'Depois da Batalha',replace(replace('Este card só pode ser ativado durante a Main Phase 1. \r\nTodos os monstros no Campo que se envolveram em cálculo de dano são destruídos durante o End Step do turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25366484,'Homem-Alado da Chama Brilhante, o HERÓI do Elemento',replace(replace('"Homem-Alado das Chamas, o HERÓI do Elemento" + "Sparkman, o HERÓI do Elemento"	\r\nDeve ser Invocado por Invocação-Fusão. \r\nGanha 300 de ATK para cada card "HERÓI do Elemento" no seu Cemitério. \r\nSe este card destruir um monstro em batalha e enviá-lo para o Cemitério: cause dano ao seu oponente igual ao ATK original desse monstro no Cemitério.','\r',char(13)),'\n',char(10)),'Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25373678,'Vórtice, o Turbilhão',replace(replace('1 Regulador + 1 ou mais monstros do Tipo Besta Alada não-Reguladores	\r\nQuando este card for destruído em batalha e enviado para o Cemitério, você pode Invocar por Invocação-Especial 1 monstro do Tipo Besta Alada de Nível 4 ou menos do seu Deck.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25377819,'Selo Hierático da Convocação','Adicione 1 monstro "Hierático" do seu Deck à sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25388971,'Kaiho Sangen',replace(replace('Durante a Fase Principal, se todos os monstros que você controla forem monstros Dragão de FOGO (mín. 1) e seu oponente controlar mais monstros que você: encerre a Fase Principal. \r\nSe 3 ou mais ataques foram declarados neste turno: você pode banir este card do seu Cemitério; compre 1 card e, depois, você pode Invocar por Invocação-Especial qualquer número de monstros "Dragão Tenpai" da sua mão. \r\nVocê só pode usar cada efeito de "Kaiho Sangen" uma vez por turno.','\r',char(13)),'\n',char(10)),'Terminar a Fase Principal','Comprar e Invocar por Invocação Especial','Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25396150,'Salão Amazoness',replace(replace('Quando este card for ativado: você pode pegar 1 monstro "Amazoness" do seu Cemitério ou do seu Deck Adicional com a face para cima e adicione-o à sua mão ou (se ele for um Monstro Pêndulo) coloque-o na sua Zona de Pêndulo. \r\nSe um ou mais monstros forem Invocados por Invocação-Especial no campo do seu oponente enquanto você controlar um Card de Monstro "Amazoness" (exceto durante a Etapa de Dano): você pode escolher 1 desses monstros do oponente; ganhe PV igual ao ATK dele. \r\nVocê só pode usar este efeito de "Salão Amazoness" uma vez por turno.','\r',char(13)),'\n',char(10)),'Escolher 1 card do Cemitério ou do Deck Adicional?','Adicionar à mão','Colocar na Zona de Pêndulo','Ganhar PV','','','','','','','','','','','','');
INSERT INTO texts VALUES(25397880,'Cronista de Nephthys',replace(replace('Você pode escolher 1 card "Nephthys" no seu Cemitério, exceto "Cronista de Nephthys"; destrua 1 card na sua mão e, se isso acontecer, adicione o alvo à sua mão. \r\nDurante sua próxima Fase de Apoio depois que este card foi destruído por um efeito de card e enviado para o Cemitério: você pode adicionar 1 card "Nephthys" do seu Cemitério à sua mão, exceto "Cronista de Nephthys". \r\nVocê só pode usar cada efeito de "Cronista de Nephthys" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25401880,'Trajeto Psíquico',replace(replace('Pague 800 PV e escolha até 2 dos seus monstros do Tipo Psíquico removidos de jogo. \r\nAdicione-os à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25407406,'Gládio de Batalha da Besta Gladiadora',replace(replace('Só pode ser equipado em um monstro "Besta Gladiadora". \r\nEle ganha 300 de ATK. \r\nQuando o monstro equipado for devolvido do seu lado do campo para o Deck e este card for enviado para o Cemitério, devolva este card para a sua mão.','\r',char(13)),'\n',char(10)),'Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25407643,'Santuário Secreto dos Conjuradores',replace(replace('Quando um ou mais monstros (exceto monstros do Tipo Mago) forem Invocador por Invocação-Normal ou Especial no lado do campo do seu oponente enquanto você controlar outro Card de Magia com a face para cima e seu oponente não controlar nenhum Card de Magia com a face para cima: esse monstro não pode atacar ou ativar seus efeitos neste turno. \r\n(Isso se aplica mesmo que este card deixe o campo.) \r\nSe você não controlar monstros do Tipo Mago, destrua este card.','\r',char(13)),'\n',char(10)),'Restrição de efeito de ataque','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25415052,'Shinobaronesa Pavoa',replace(replace('Você pode Invocar este card por Invocação-Ritual com "Chamado do Shinobird". \r\nDeve ser Invocado por Invocação-Ritual e não pode ser Invocado por Invocação-Especial de nenhuma outra forma. \r\nSe este card for Invocado por Invocação-Ritual: você pode embaralhar no Deck até 3 Cards de Magia/Armadilha que seu oponente controla e, depois, você pode Invocar por Invocação-Especial 1 monstro Espírito de Nível 4 ou menos do seu Deck, ignorando suas condições de Invocação. \r\nUma vez por turno, durante a Fase Final, se este card foi Invocado por Invocação-Especial neste turno: devolva-o para a mão e, se isso acontecer, Invoque por Invocação-Especial 2 "Fichas de Shinobird" (Tipo Besta Alada/VENTO/Nível 4/ATK 1500/DEF 1500).','\r',char(13)),'\n',char(10)),'Embaralhe as Magias/Armadilhas do seu oponente no Deck','Invocar um monstro Espírito por Invocação Especial do seu Deck?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25415053,'Ficha de Shinobird','Invocado por Especial com o efeito "Shinobaronesa Pavoa" ou "Shinobarão Pavão".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25415161,'Springans Interludior',replace(replace('Quando seu oponente ativar um card ou efeito: você pode devolver 1 Monstro Xyz "Springans" que você controla para o Deck Adicional e, depois, aplique 1 desses efeitos.\r\n● Negue o efeito ativado.\r\n● Invoque por Invocação-Especial 1 monstro de Nível 8 do seu Cemitério.	\r\nSe um Monstro Xyz com a face para cima que você controla deixar o campo devido a um efeito de card: você pode fazer com que todos os monstros que seu oponente controla atualmente percam 1000 de ATK até o final deste turno (mesmo que este card deixe o campo). \r\nVocê só pode usar cada efeito de "Springans Interludior" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Negar o efeito','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25419323,'Couraça Dinomorfia',replace(replace('No começo da Fase de Batalha do seu oponente: pague metade dos seus PV; Invoque por Invocação-Especial 1 "Ficha de Dinomorfia" (Dinossauro/TREVAS/Nível 10/ATK 0/DEF 3000) e, se isso acontecer, pelo resto deste turno, enquanto você controlar essa Ficha na sua Zona de Monstros, seu oponente não pode escolher outros monstros como alvo de ataques, exceto esse. \r\nDurante o cálculo de dano, enquanto seus PV forem 2000 ou menos, se você sofreria dano de batalha: você pode banir este card do seu Cemitério; você não sofre dano de batalha dessa batalha. \r\nVocê só pode ativar 1 "Couraça Dinomorfia" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25419324,'Ficha de Dinomorfia','Invocado por Especial com o efeito "Couraça Dinomorfia".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25435080,'Asanegra - Bombardeio','Ofereça como Tributo 1 monstro "Asanegra" e, depois, escolha 1 Monstro Sincro que você controla; até o final deste turno, ele ganha ATK igual ao ATK que o monstro oferecido como Tributo tinha no campo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25449584,'Kaiza, a Estrela Oculta',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) ao oferecer como Tributo 1 monstro Guerreiro de LUZ ou de TERRA e, se isso acontecer, este card ganha ATK igual ao ATK original do monstro oferecido como Tributo. \r\nVocê só pode Invocar "Kaiza, a Estrela Oculta" por Invocação-Especial uma vez por turno desta forma. \r\nVocê pode banir 1 monstro Guerreiro do seu Cemitério; envie 1 monstro Guerreiro de LUZ ou de TERRA do seu Deck para o Cemitério. \r\nVocê só pode usar este efeito de "Kaiza, a Estrela Oculta" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Forma de Invocação: Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25451383,'Albion, o Dragão Encoberto',replace(replace('O nome deste card se torna "Caído de Arbaz" enquanto estiver no campo ou no Cemitério. \r\nSe este card estiver na sua mão ou no Cemitério: você pode enviar 1 "Caído de Arbaz" ou 1 Magia/Armadilha "Marcado" da sua mão ou do Deck para o Cemitério; aplique o seguinte efeito de acordo com de onde você o enviou.\r\n● Mão: Invoque este card por Invocação-Especial.\r\n● Deck: Coloque este card no fundo do Deck e, depois, se você colocou este card da sua mão, compre 1 card.	\r\nVocê só pode usar este efeito de "Albion, o Dragão Encoberto" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25451652,'Senhor Obscuro Estrela da Manhã',replace(replace('Não pode ser Invocado por Invocação-Especial. \r\nSe este card for Invocado por Invocação-Tributo: você pode Invocar monstros "Senhor(a) Obscuro(a)" por Invocação-Especial da sua mão e/ou do Deck, até o número de Monstros de Efeito que seu oponente controla. \r\nEnquanto você controlar outro monstro "Senhor(a) Obscuro(a)", seu oponente não pode escolher este card como alvo de efeitos de card. \r\nUma vez por turno: você pode enviar cards do topo do seu Deck para o Cemitério, igual ao número de monstros "Senhor(a) Obscuro(a)" no campo e, se isso acontecer, ganhe 500 PV para cada card "Senhor(a) Obscuro(a)" enviado para o Cemitério por este efeito.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25460258,'Dragão do Brilho Obscuro',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) ao banir 1 monstro de LUZ e 1 de TREVAS do seu Cemitério. \r\nUma vez por turno: você pode enviar 1 monstro Dragão da sua mão e 1 monstro Dragão do seu Deck para o Cemitério e, depois, escolha 1 card em qualquer Cemitério; bana o alvo.','\r',char(13)),'\n',char(10)),'Banir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25472513,'Xamã da Estrela Celestial Dupla',replace(replace('1 Regulador + 1 monstro não-Regulador	\r\nQuando este card for Invocado por Invocação-Sincro: você pode Invocar por Invocação-Especial até 4 monstros não-Reguladores de Nível 2 da sua mão e/ou Cemitério em Posição de Defesa, mas eles têm seus efeitos negados e, além disso, você não pode Invocar monstros por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto Monstros Sincro. \r\nVocê só pode usar este efeito de "Xamã da Estrela Celestial Dupla" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25484449,'Tubarão de Corda',replace(replace('Quando um monstro "de Corda" é Invocado por Inovcação-Normal ou Especial no seu lado do campo: você pode Invocar este card por Invocação-Especial da sua mão. \r\nUma vez por turno: você pode ativar um dos efeitos abaixo.\r\n● Até a Fase Final, aumente em 1 o Nível deste card.\r\n● Até a Fase Final, reduza em 1 o Nível deste card.','\r',char(13)),'\n',char(10)),'Invocação Especial','Alterar Nível','Aumentar o Nível','Reduzir o Nível','','','','','','','','','','','','');
INSERT INTO texts VALUES(25494711,'Robô-secretário 009',replace(replace('Uma vez por turno, durante sua Fase Principal 1: até o final do turno do seu oponente, você pode fazer com que este card ganhe ATK igual ao ATK combinado de todos os monstros "Robô-secretário" que você controla atualmente, exceto "Robô-secretário 009". \r\nSomente este card pode atacar no turno em que este efeito for ativado. \r\nSe este card batalhar, os cards e efeitos do seu oponente não podem ser ativados até o final da Etapa de Dano. \r\nSe este card seria destruído em batalha ou por um efeito de card, em vez disso, você pode destruir 1 card "Robô-secretário" que você controla.','\r',char(13)),'\n',char(10)),'Usar o efeito de "Robô-secretário 009" em vez de ser destruído?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25518020,'Linha de Montagem de Máquinas',replace(replace('Todos os monstros Máquina no campo ganham 200 de ATK. \r\nSempre que um ou mais monstros Máquina com a face para cima no campo forem destruídos em batalha ou por um efeito de card, coloque 2 Marcadores de Sucata neste card. \r\nVocê pode enviar este card para o Cemitério e, depois, escolha 1 monstro Máquina no seu Cemitério cujo Nível seja igual ou menor que o número de Marcadores de Sucata que estavam neste card; Invoque o alvo por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25524823,'Oráculo do Coveiro',replace(replace('Você pode oferecer como Tributo 3 monstros ou 1 monstro "do Coveiro" para Invocar este card por Invocação-Tributo (mas não Baixar). \r\nQuando este card for Invocado por Invocação-Tributo: você pode ativar quaisquer desses efeitos, até o número de monstros "do Coveiro" oferecidos como Tributo para sua Invocação, e resolvê-los em sequência;\r\n● Este card ganha ATK igual à soma dos Níveis que todos os monstros oferecidos como Tributo para sua Invocação-Tributo tinham no campo x 100.\r\n● Destrua todos os monstros Baixados que seu oponente controla.\r\n● Todos os monstros que seu oponente controla atualmente perdem 2000 de ATK/DEF.','\r',char(13)),'\n',char(10)),'Ofereça 3 monstros como Tributo para Invocar','Ofereça 1 monstro cujo nome inclua "Coveiro" como Tributo para Invocar','O ATK deste card aumenta','Destrua todos os monstros com a face para baixo que seu oponente controla','Todos os monstros que seu oponente controla perdem ATK/DEF','Continuar selecionando efeitos para ativar?','Ativar efeito','','','','','','','','','');
INSERT INTO texts VALUES(25531465,'Magigato','Se este card for enviado ao Cemitério para a Invocação-Sincro de um Monstro Sincro do Tipo Mago, você pode devolver 1 Card de Magia do seu Cemitério para o topo do seu Deck.','Retornar ao Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25533642,'Buscasina Altergeist',replace(replace('Este card pode atacar diretamente. \r\nQuando este card causar dano de batalha ao seu oponente: você pode escolher 1 card que seu oponente controla; envie-o para o Cemitério. \r\nSe este card for enviado do campo para o Cemitério: você pode adicionar 1 monstro "Altergeist" do seu Deck à sua mão, exceto "Buscasina Altergeist". \r\nVocê só pode usar este efeito de "Buscasina Altergeist" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25538345,'Os Cavaleiros Fantasmas de Escamas Rachadas',replace(replace('Você pode descartar 1 card; envie 1 card "Cavaleiros Fantasmas" do seu Deck para o Cemitério, exceto "Os Cavaleiros Fantasmas de Escamas Rachadas". \r\nSe outro card "Cavaleiros Fantasmas" no seu Cemitério for banido, enquanto este card estiver no seu Cemitério: você pode Invocar este card por Invocação-Especial, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar cada efeito de "Os Cavaleiros Fantasmas de Escamas Rachadas" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25542642,'Cavaleiros Fantasmas - Lâmina de Névoa',replace(replace('Ative este card ao escolher 1 Monstro de Efeito no campo; negue os efeitos desse monstro com a face para cima, esse monstro com a face para cima não pode atacar e, além disso, monstros não podem escolher esse monstro com a face para cima como alvo de ataques. \r\nQuando ele deixar o campo, destrua este card. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 monstro "Os Cavaleiros Fantasmas" no seu Cemitério; Invoque-o por Invocação-Especial, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar este efeito de "Cavaleiros Fantasmas - Lâmina de Névoa" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25542643,'Cavaleiros Fantasmas - Lâmina de Névoa',replace(replace('Ative este card ao escolher 1 Monstro de Efeito no campo; negue os efeitos desse monstro com a face para cima, esse monstro com a face para cima não pode atacar e, além disso, monstros não podem escolher esse monstro com a face para cima como alvo de ataques. \r\nQuando ele deixar o campo, destrua este card. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 monstro "Os Cavaleiros Fantasmas" no seu Cemitério; Invoque-o por Invocação-Especial, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar este efeito de "Cavaleiros Fantasmas - Lâmina de Névoa" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25550531,'Purrely',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode escavar os 3 cards do topo do seu Deck e, se isso acontecer, você pode adicionar à sua mão 1 Magia/Armadilha "Purrely" escavada e, além disso, coloque o resto no fundo do seu Deck em qualquer ordem. \r\nUma vez por turno, durante sua Fase Principal: você pode revelar 1 Magia Rápida "Purrely" na sua mão, Invoque por Invocação-Especial 1 Monstro Xyz do seu Deck Adicional que mencione esse card, usando este card que você controla como matéria, e associe o card revelado ao monstro Invocado. \r\n(Isso é considerado uma Invocação-Xyz.)','\r',char(13)),'\n',char(10)),'','','Adicionar 1 Magia/Armadilha "Purrely" à sua mão?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25551951,'Dragão Solta Fogo','Uma vez por turno: você pode escolher 1 card que seu oponente controla; lance uma moeda 3 vezes e destrua o alvo se pelo menos 2 resultados forem cara.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25554552,'Carregador Foguette',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 monstro Dragão de TREVAS de Nível 7 do seu Deck à sua mão e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto monstros de TREVAS. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 monstro com a face para cima no campo; ele se torna de TREVAS até o final deste turno. \r\nVocê só pode usar cada efeito de "Carregador Foguette" uma vez por turno.','\r',char(13)),'\n',char(10)),'Efeito de busca','Alterar o Atributo','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25573054,'Asas Transcendentais',replace(replace('Envie para o Cemitério 1 "Kuriboh Alado" do seu Campo e 2 cards da sua mão. \r\nInvoque, por Invocação-Especial, 1 "Kuriboh Alado LV10" da sua mão ou do seu Deck.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25573115,'Predador Alfa',replace(replace('Se você controlar um monstro Invocado por Invocação-Normal/Baixado: destrua todos os monstros no campo que foram Invocados por Invocação-Especial. \r\nAté o final do seu próximo turno depois que este card for ativado, você não pode Invocar por Invocação-Normal/Baixar. \r\nVocê só pode ativar 1 "Predador Alfa" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25577965,'Língua Flamejante, a Lâmina Ardente',replace(replace('2 monstros de FOGO	\r\nMagias/Armadilhas com a face para cima que você controla não podem ser destruídas pelos efeitos de card do seu oponente. \r\nVocê pode escolher 1 dos seus monstros de FOGO banidos; adicione-o à sua mão, mas você não pode ativar cards, ou os efeitos de cards, com o nome dele pelo resto deste turno. \r\nVocê só pode usar este efeito de "Língua Flamejante, a Lâmina Ardente" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25578802,'Batalha de Dois Homens na Cela','Apenas uma vez durante a End Phase do turno de cada jogador, ele pode Invocar, por Invocação-Especial, 1 Monstro Normal de Nível 4 da sua mão.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25586143,'Predaplanta Quimeraflésia',replace(replace('1 monstro "Predaplanta" + 1 monstro de TREVAS	\r\nUma vez por turno: você pode escolher 1 monstro no campo com um Nível igual ou menor que o deste card; bana-o. \r\nQuando um ataque for declarado envolvendo este card e um monstro com a face para cima do oponente: você pode ativar este efeito; até o final deste turno, esse monstro do oponente perde 1000 de ATK e, se isso acontecer, este card ganha 1000 de ATK. \r\nUma vez por turno, durante a próxima Fase de Apoio depois que este card foi enviado para o Cemitério: você pode adicionar 1 Magia "Polimerização" ou Magia "Fusão" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25592142,'Astellar da Floresta Branca',replace(replace('Você pode enviar 1 Magia/Armadilha da sua mão ou do campo para o Cemitério; Invoque por Invocação-Especial 1 Mago Regulador de LUZ do seu Deck. \r\nSe uma ou mais Magias/Armadilhas forem enviadas para o seu Cemitério para ativar um efeito de monstro, enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Astellar da Floresta Branca" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial do Deck','Invocar por Invocação Especial do Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25592143,'Astellar da Floresta Branca',replace(replace('Você pode enviar 1 Magia/Armadilha da sua mão ou do campo para o Cemitério; Invoque por Invocação-Especial 1 Mago Regulador de LUZ do seu Deck. \r\nSe uma ou mais Magias/Armadilhas forem enviadas para o seu Cemitério para ativar um efeito de monstro, enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Astellar da Floresta Branca" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial do Deck','Invocar por Invocação Especial do Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25607552,'Nowru Aries, o Dragão Vernal',replace(replace('Se este card estiver no seu Cemitério: você pode enviar 1 monstro de Nível 5 ou mais da sua mão para o Cemitério; Invoque este card por Invocação-Especial, mas bana-o quando ele deixar o campo. \r\nSe este card for destruído em batalha, ou se este card em posse do seu dono for destruído por um efeito de card do oponente: você pode escolher 1 card que seu oponente controla; bana-o. \r\nVocê só pode usar cada efeito de "Nowru Aries, o Dragão Vernal" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25614410,'Legado do HERÓI',replace(replace('Devolva 2 Monstros de Fusão do seu Cemitério para o Deck Adicional que listem um monstro "HERÓI" como Matéria; compre 3 cards. \r\nVocê só pode ativar 1 "Legado do HERÓI" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25629622,'Ator do Abismo - Superstar',replace(replace('Escala de Pêndulo = 3\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno: você pode oferecer como Tributo 1 monstro "Ator do Abismo" e, depois, escolher 1 Magia "Script do Abismo" no seu Cemitério; adicione-a à sua mão.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nQuando este card for Invocado por Invocação-Normal ou Especial, os Cards e efeitos de Magia/Armadilha do seu oponente não podem ser ativados. \r\nUma vez por turno: você pode Baixar 1 Magia "Script do Abismo" diretamente do seu Deck, mas ela é enviado para o Cemitério durante a Fase Final.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25642998,'Onda de Poseidon','Quando um monstro do oponente declarar um ataque: escolha o monstro atacante; negue o ataque e, se isso acontecer, cause 800 de dano ao seu oponente para cada monstro do Tipo Peixe, Serpente Marinha ou Aqua que você controla.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25643346,'Malícia, a Dama da Lamentação',replace(replace('(Efeito Rápido): você pode oferecer 2 monstros como Tributo e, depois, escolha 1 das suas Armadilhas Normais que estiverem banidas ou no seu Cemitério; Baixe o alvo, mas coloque-o no fundo do Deck quando ele deixar o campo. \r\nVocê só pode usar este efeito de "Malícia, a Dama da Lamentação" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25652259,'O Cavaleiro da Rainha','Este cavaleiro apanha os seus adversários desprevenidos, dominando-os com ataques precisos, mas graciosos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25652655,'Sincron Alterador','Se este card for enviado ao Cemitério para uma Invocação-Sincro, selecione 1 monstro que seu oponente controla e mude sua posição de batalha.','Mudar a posição de batalha','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25654671,'Arangarras de Naturia','Não pode declarar um ataque a não ser que seu oponente tenha ativado um card ou efeito neste turno.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25655502,'Bickuribox','"Palhaço Grosseiro" + "Palhaço dos Sonhos"','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25661743,'Portal Interdito do Patrono do Poder - Terminus',replace(replace('Envie 1 monstro "Patrono(a) do Poder" do seu Deck/Deck Adicional para o Cemitério e, depois, você pode adicionar 1 monstro Fada de TREVAS do seu Deck à sua mão e, além disso, você não pode declarar ataques pelo resto deste turno, exceto com monstros "Patrono(a) do Poder". \r\nNo começo da Etapa de Dano, se um monstro "Patrono(a) do Poder" seu batalhar um monstro do oponente: você pode banir este card do seu Cemitério; bana (com a face para baixo) esse monstro do oponente. \r\nVocê só pode usar cada efeito de "Portal Interdito do Patrono do Poder - Terminus" uma vez por turno.','\r',char(13)),'\n',char(10)),'Enviar para o Cemitério','Banir','Adicionar à mão?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25669282,'Esgotamento',replace(replace('Bana 1 monstro "Criaquímica" com a face para cima que você controla; Invoque por Invocação-Especial 2 monstros "Criaquímica" do seu Deck, com nomes diferentes um do outro. \r\nDurante o turno de qualquer duelista, exceto no turno em que este card foi enviado para o Cemitério, quando seu oponente declarar um ataque direto: você pode banir este card do seu Cemitério e, depois, escolher 1 de seus monstros Gêmeos banidos; Invoque-o por Invocação-Especial e, se isso acontecer, ele se torna um Monstro de Efeito e ganha seus efeitos. \r\nVocê só pode ativar 1 "Esgotamento" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25682811,'Cavaleiro Dragunidade - Barcha',replace(replace('1 Regulador Dragão + 1+ monstros Besta Alada não-Reguladores	\r\nQuando este card for Invocado por Invocação-Sincro: você pode escolher qualquer número de monstros Dragão "Dragunidade" no seu Cemitério; equipe esses monstros Dragão a este card. \r\nEste card ganha 300 de ATK para cada card "Dragunidade" equipado a ele.','\r',char(13)),'\n',char(10)),'Equipar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25687946,'Estátua Melffy',replace(replace('Adicione até 4 monstros "Melffy" com nomes diferentes do seu Deck à sua mão e, depois, essa se torna a Fase Final deste turno. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 2 cards "Melffy" no seu Cemitério, exceto "Estátua Melffy"; adicione 1 deles à sua mão e, se isso acontecer, coloque o outro no fundo do seu Deck. \r\nVocê só pode usar este efeito de "Estátua Melffy" uma vez por turno. \r\nVocê não pode Invocar por Invocação-Especial no turno em que ativar este card, exceto monstros "Melffy".','\r',char(13)),'\n',char(10)),'Adicionar à mão','Recuperar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25700114,'Rolo Poerio',replace(replace('Escolha 1 monstro no campo; neste turno, ele não pode ser oferecido como Tributo nem ser usado como Matéria Fusão, Sincro ou Xyz para uma Invocação. \r\nSe este card Baixado que você controla for destruído por um efeito de card do seu oponente e enviado para o seu Cemitério: você pode adicionar 1 monstro "Poerio" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25704359,'Despossuído',replace(replace('Monstros "Encantador(a)" que você controla não podem ser destruídos em batalha. \r\nSe um monstro "Espírito-Possuído" seu atacar um monstro do oponente, ele ganha 800 de ATK apenas durante o cálculo de dano. \r\nSe um ou mais monstros que você controla forem destruídos em batalha ou por um efeito de card, enquanto este card já estiver com a face para cima na sua Zona de Magias & Armadilhas: você pode Invocar por Invocação-Especial 1 monstro Mago com 1500 de DEF do seu Deck em Posição de Ataque ou com a face para baixo em Posição de Defesa, cujo Atributo seja diferente do Atributo original que pelo menos 1 desses monstros destruídos tinha no campo. \r\nVocê só pode usar este efeito de "Despossuído" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25716180,'Gatinho de Corda','Uma vez enquanto estiver com a face para cima no campo: você pode escolher 1 monstro que seu oponente controla; devolva o alvo para a mão.','Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25725326,'Miau-Miau-Mu dos Travesso-Guris',replace(replace('1 monstro "Travesso-Guris" de Nível 4 ou menos	\r\nVocê só pode Invocar "Miau-Miau-Mu dos Travesso-Guris" por Invocação-Link uma vez por turno. \r\nSe um monstro "Travesso-Guris" que você controla ofereceria a si mesmo como Tributo para ativar seu efeito durante o turno do seu oponente, em vez disso, você pode banir este card que você controla ou do seu Cemitério. \r\nVocê só pode usar este efeito de "Miau-Miau-Mu dos Travesso-Guris" uma vez por turno.','\r',char(13)),'\n',char(10)),'Escolha 1 card para oferecer como Tributo, ou para banir em vez disso','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25726386,'Megálito Aratron',replace(replace('Você pode Invocar este card por Invocação-Ritual com um card "Megálito". \r\nDurante a Fase Principal (Efeito Rápido): você pode descartar este card; Invoque por Invocação-Ritual 1 Monstro de Ritual "Megálito" da sua mão, ao oferecer monstros como Tributo da sua mão ou do campo cuja soma dos Níveis seja igual ou exceda seu Nível. \r\nQuando seu oponente ativar um card ou efeito que escolha um card que você controla como alvo (Efeito Rápido): você pode colocar no fundo do Deck 1 Monstro de Ritual do seu Cemitério e, se isso acontecer, negue essa ativação e, se isso acontecer, destrua-o. \r\nVocê só pode usar cada efeito de "Megálito Aratron" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25727454,'Mestre Ferreiro Gamil','Durante a Etapa de Dano, quando um monstro com a face para cima que você controla batalhar (Efeito Rápido): você pode enviar este card da sua mão para o Cemitério; esse monstro ganha 300 de ATK até o final deste turno.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25733157,'Força Celeste - Mecha - Impulsionador Águia','Se você não controlar nenhum monstro na sua Zona de Monstros Principal: escolha 1 monstro com a face para cima no campo; o alvo não é afetado por efeitos de card neste turno, exceto seus próprios e, se você tiver 3 ou mais Magias no seu Cemitério, ele não pode ser destruído em batalha neste turno.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25750986,'Caos Eterno',replace(replace('Escolha 1 monstro com a face para cima que seu oponente controla; envie 1 monstro de LUZ e 1 de TREVAS do seu Deck para o Cemitério, cuja soma do ATK seja menor ou igual que o desse monstro e, além disso, pelo resto deste turno depois que este card resolver, você só pode ativar 1 efeito de monstro no Cemitério. \r\nVocê só pode ativar 1 "Caos Eterno" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25769732,'Fábrica de Conversão de Máquina',replace(replace('Só pode ser equipado a um monstro Máquina. \r\nEle ganha 300 de ATK/DEF.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25771826,'Garadholg, Aliado da Justiça','Se este card batalhar um monstro de LUZ, ele ganha 200 de ATK apenas durante a Etapa de Dano.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25773409,'O Lendário Mestre de Jujitsu','Se este card em Posição de Defesa batalhar um monstro, no final da Etapa de Dano: coloque esse monstro no topo do Deck.','Retornar ao Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25774450,'Caixa Mágica','Escolha 1 monstro que seu oponente controla e 1 monstro que você controla; destrua o primeiro alvo e, depois, conceda o controle do segundo alvo ao seu oponente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25784595,'Arquidemônio de Ossos',replace(replace('Se este card estiver na sua mão ou no Cemitério: você pode enviar 1 outro card da sua mão ou do campo para o Cemitério; Invoque este card por Invocação-Especial e, além disso, você não pode Invocar monstros por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto Monstros Sincro Dragão de TREVAS. \r\nVocê pode escolher 1 monstro com a face para cima que você controla que tenha um Nível; envie 1 Regulador Demônio da sua mão ou do Deck para o Cemitério e, se isso acontecer, aumente ou diminua o Nível desse monstro em 1. \r\nVocê só pode usar cada efeito de "Arquidemônio de Ossos" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Aumentar o Nível','Reduzir o Nível','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25788011,'Risebell, o Ajustador de Estrelas','Quando este card for Invocado por Invocação-Especial: você pode escolher 1 monstro com a face para cima no campo; aumente o Nível dele em até 3 até o final deste turno.','Aumentar o Nível','Aumentar em 1 Nível','Aumentar o Nível em 2','Aumentar o Nível em 3','','','','','','','','','','','','');
INSERT INTO texts VALUES(25789292,'Cálice Proibido','Escolha 1 monstro com a face para cima no campo; até o final deste turno, o alvo ganha 400 de ATK, mas seus efeitos são negados.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25789293,'Cálice Proibido','Escolha 1 monstro com a face para cima no campo; até o final deste turno, o alvo ganha 400 de ATK, mas seus efeitos são negados.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25793414,'Ventobruxa - Sino de Cristal',replace(replace('"Ventobruxa - Sino do Inverno" + 1 monstro "Ventobruxa"	\r\nVocê pode escolher 1 monstro no Cemitério de qualquer duelista; até a Fase Final, o nome deste card se torna o nome original desse monstro e substitua este efeito pelos efeitos originais do alvo. \r\nSe este card em sua posse for destruído por um card do seu oponente (em batalha ou por um efeito de card) e enviado para o seu Cemitério: você pode escolher 1 "Ventobruxa - Sino do Inverno" e 1 monstro "Ventobruxa" de Nível 4 ou menos no seu Cemitério; Invoque-os por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Ventobruxa - Sino de Cristal" uma vez por turno.','\r',char(13)),'\n',char(10)),'Copiar efeito','Invocação Especial','Encerrar o efeito copiado','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25795273,'Al-Lumi''raj','Todos os monstros no campo perdem ATK e DEF igual ao seu próprio Nível/Classe x 300.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25796442,'Jaula Ritual',replace(replace('Você não sofre dano de batalha de ataques envolvendo um Monstro de Ritual que você controla. \r\nMonstros de Ritual que você controla não podem ser escolhidos como alvo de, nem destruídos por, efeitos de monstro.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25800447,'Fusão de Fogo',replace(replace('(Este card deve ser sempre considerado como um card "Salamagrande".)	\r\nInvoque por Invocação-Fusão 1 Monstro de Fusão "Salamagrande" do seu Deck Adicional, usando monstros da sua mão e/ou de qualquer campo como Matéria de Fusão. \r\nVocê só pode ativar 1 "Fusão de Fogo" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25801745,'Lo, as Orações da Voz Sem Voz',replace(replace('Se você Invocar por Invocação-Ritual exatamente 1 Monstro de Ritual (Guerreiro ou Dragão) de LUZ com um efeito de card que exige o uso de monstros, este card pode ser usado como todo o Tributo. \r\nVocê só pode usar cada um dos seguintes efeitos de "Lo, as Orações da Voz Sem Voz" uma vez por turno. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode colocar 1 Magia/Armadilha Contínua "Voz Sem Voz" do seu Deck, com a face para cima na sua Zona de Magias & Armadilhas. \r\nSe um Monstro de Ritual (Guerreiro ou Dragão) de LUZ for Invocado por Invocação-Especial no seu campo, enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25807544,'Museu das Armas Nobres',replace(replace('Todos os monstros Guerreiro de FOGO que você controla ganham 500 de ATK. \r\nUma vez por turno: você pode pagar 1200 PV; adicione 1 card "Armas Nobres" do seu Deck à sua mão, exceto "Museu das Armas Nobres". \r\nUma vez por turno, se o efeito anterior foi aplicado neste turno: você pode escolher 1 Card de Monstro "Nobre Cavaleiro" na sua Zona de Magias & Armadilhas; Invoque-o por Invocação-Especial e, além disso, se você ativou este efeito enquanto não controlava "Infernobre Cavaleiro Imperador Charles", você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros Guerreiro.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25811989,'Infernoide Piaty',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão ou do Cemitério) ao banir 2 monstros "Infernoide" da sua mão ou do Cemitério enquanto a soma dos Níveis e Classes de todos os Monstros de Efeito que você controla for 8 ou menos. \r\nQuando este card causar dano de batalha ao seu oponente ao atacar um monstro do oponente: você pode enviar 1 card aleatório da mão do seu oponente para o Cemitério. \r\nUma vez por turno (Efeito Rápido): você pode oferecer 1 monstro como Tributo e, depois, escolha 1 card no Cemitério do seu oponente; bana-o.','\r',char(13)),'\n',char(10)),'Destruir cards na mão','Banir cards do Cemitério do seu oponente','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25824484,'Arvoremita Silvestre',replace(replace('Uma vez por turno: você pode escavar o card do topo do seu Deck e, se ele for um monstro do Tipo Planta, envie-o para o Cemitério e, se isso acontecer, compre 1 card. \r\nCaso contrário, coloque-o no fundo do seu Deck. \r\nSe este card for escavado do Deck e enviado para o Cemitério por um efeito de card: olhe até 3 cards do topo do seu Deck e, depois, coloque-os no topo do Deck em qualquer ordem.','\r',char(13)),'\n',char(10)),'Revelar o Deck','Verificar a ordem do Deck','Escolha a quantidade a revelar','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25833572,'Guardião do Portão',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro deve ser Invocado por Invocação-Especial (da sua mão) ao oferecer como Tributo 1 "Sanga do Trovão", "Kazejin" e "Suijin".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25845518,'Brilho da Dragunidade',replace(replace('Adicione 1 monstro "Dragunidade" de Nível 5 ou mais do seu Deck ou Cemitério à sua mão. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 Card de Monstro na sua Zona de Magias & Armadilhas equipado a um monstro "Dragunidade"; Invoque-o por Invocação-Especial em Posição de Defesa. \r\nVocê só pode usar cada efeito de "Brilho da Dragunidade" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25847467,'Kahkki, Guerrilheiro do Mundo Negro','Se este card for descartado para o Cemitério por um efeito de card: escolha 1 monstro no campo; destrua-o.','Destrua 1 monstro no campo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25853045,'Lanceiro do Raio Negro de Armadura Completa',replace(replace('3 monstros de ÁGUA de Nível 4	\r\nVocê também pode Invocar este card por Invocação-Xyz ao usar um Monstro Xyz de ÁGUA de Classe 3 que você controla que não tenha matéria. \r\nGanha 200 de ATK para cada matéria associada a ele. \r\nSe este card no campo seria destruído em batalha ou por um efeito de card, em vez disso, você pode desassociar todas as matérias deste card. \r\nQuando este card destruir um monstro do oponente em batalha: você pode escolher 1 Magia/Armadilha que seu oponente controla; destrua o alvo.','\r',char(13)),'\n',char(10)),'Invocação Xyz usando um Monstro Xyz de ÁGUA de Classe 3 sem Matéria como matéria?','Usar o efeito de "Lanceiro do Raio Negro de Armadura Completa" em vez de ser destruído?','Destruir Magias/Armadilhas','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25857246,'Necroz de Valkyrus',replace(replace('Você pode Invocar este card por Invocação-Ritual com qualquer Magia de Ritual "Necroz". \r\nDeve ser Invocado por Invocação-Ritual sem usar quaisquer monstros de Nível 8. \r\nVocê só pode usar cada um desses efeitos de "Necroz de Valkyrus" uma vez por turno.\r\n● Quando um monstro do oponente declarar um ataque: você pode banir 1 card "Necroz" do seu Cemitério e descartar este card; negue o ataque e, depois, encerre a Fase de Batalha.\r\n● Durante sua Fase Principal: você pode oferecer como Tributo até 2 monstros da sua mão e/ou do campo e, se isso acontecer, compre o mesmo número de cards oferecidos como Tributo.','\r',char(13)),'\n',char(10)),'Negar o ataque','Comprar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25857977,'D/D/D Réquiem, o Vice Rei',replace(replace('Escala de Pêndulo = 4\r\n[ Efeito de Pêndulo ]\r\nVocê pode escolher qualquer número de cards "Pacto Obscuro" que você controla; destrua-os e, se isso acontecer, Invoque este card por Invocação-Especial da sua Zona de Pêndulo e, depois, você pode aumentar ou diminuir seu Nível pelo número destruído. \r\nVocê só pode usar este efeito de "D/D/D Réquiem, o Vice Rei" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nVocê não pode Invocar monstros por Invocação-Especial, exceto monstros "D/D/D". \r\nUm monstro "D/D/D" que foi Invocado por Invocação-Fusão, Sincro, Xyz ou Link usando este card no campo como matéria ganha este efeito.\r\n● Uma vez por turno: você pode escolher 1 card no campo; embaralhe no Deck 1 card "Pacto Obscuro" do seu campo ou Cemitério e, se isso acontecer, destrua o alvo e, depois, ganhe 1000 PV.	\r\nVocê só pode usar este efeito de "D/D/D Réquiem, o Vice Rei" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Efeito de dano "D/D/D Réquiem, o Vice Rei"','Não alterar o Nível','Aumentar o Nível','Reduzir o Nível','O efeito de "D/D/D Réquiem, o Vice Rei" está sendo aplicado.','','','','','','','','','','');
INSERT INTO texts VALUES(25861589,'Mistura Aromági',replace(replace('Descarte 1 card; coloque 1 "Ventos Húmidos", "Ventos Secos" ou "Ventos Abençoados" da sua mão ou do Deck, com a face para cima na sua Zona de Magias & Armadilhas. \r\nVocê pode banir este card do seu Cemitério; Invoque por Invocação-Fusão 1 Monstro de Fusão Planta do seu Deck Adicional, ao banir suas matérias da sua mão ou do campo. \r\nSe seus PV forem maiores que os do seu oponente, você também pode banir monstros Planta do seu Cemitério como matéria. \r\nVocê só pode usar cada efeito de "Mistura Aromági" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Colocar','Invocação Fusão','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25862681,'Dragão Fada Antigo',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nDurante sua Fase Principal: você pode Invocar por Invocação-Especial 1 monstro de Nível 4 ou menos da sua mão. \r\nVocê não pode conduzir sua Fase de Batalha no turno em que ativar este efeito. \r\nDurante sua Fase Principal: você pode destruir tantos cards nas Zonas do Campo quanto possível (mín. 1) e, se isso acontecer, ganhe 1000 PV e, depois, você pode adicionar 1 Magia de Campo com um nome diferente que o do(s) card(s) destruído(s) do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "Dragão Fada Antigo" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invoque por Invocação Especial 1 monstro de Nível 4 ou menos da sua mão','Destrua todas as Magias de Campo','Adicionar 1 Magia de Campo à sua mão?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25865565,'Cristron Sulfador',replace(replace('Se este card estiver na sua mão ou no Cemitério: você pode escolher 1 card "Cristron" que você controla; destrua-o e, se isso acontecer, Invoque este card por Invocação-Especial e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto monstros Máquina. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode enviar até 2 cards "Cristron" com nomes diferentes do seu Deck para o Cemitério, exceto "Cristron Sulfador". \r\nVocê só pode usar cada efeito de "Cristron Sulfador" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Enviar para o Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25866285,'Maria-Fedida de Naturia','Quando um monstro "Naturia" que você controla for escolhido como alvo de um ataque (Efeito Rápido): você pode enviar este card do campo para o Cemitério; negue o ataque e, depois, encerre a Fase de Batalha.','Negue o ataque e encerre a Battle Phase','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25880422,'Bloquear Ataque','Escolha 1 monstro com a face para cima em Posição de Ataque que seu oponente controla; coloque o alvo com a face para cima em Posição de Defesa.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25882881,'Dokuroizo, Anjo da Morte','Um mensageiro da morte que rouba almas com um só golpe.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25904894,'Karakuri Super Shogun mdl 00N "Bureibu"',replace(replace('1 Regulador + 1+ monstros Máquina não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro: você pode Invocar por Invocação-Especial 1 monstro "Karakuri" do seu Deck. \r\nOs monstros que você controla em Posição de Defesa não podem ser destruídos em batalha. \r\nUma vez por turno, se a posição de batalha de um ou mais monstros "Karakuri" com a face para cima que você controla for mudada (exceto durante a Etapa de Dano): você pode escolher 1 card que seu oponente controla; bana-o.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25908748,'Impasse da Tri-Brigada',replace(replace('Você não pode Invocar monstros por Invocação-Especial do Deck Adicional, exceto monstros Besta, Besta-Guerreira ou Besta Alada. \r\nVocê pode enviar 1 monstro da sua mão ou do campo para o Cemitério; adicione do seu Deck à sua mão 1 monstro "Tri-Brigada" com um Tipo original diferente que o desse monstro enviado para o Cemitério. \r\nVocê só pode usar este efeito de "Impasse da Tri-Brigada" uma vez por turno. \r\nSe este card na Zona de Magias & Armadilhas do seu dono for destruído por um efeito de card do oponente: você pode ativar este efeito; seu oponente não pode declarar ataques neste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25919316,'Cabicavaleira Filly',replace(replace('2 Monstros de Efeito	\r\nSe este card for Invocado por Invocação-Especial em uma zona para a qual um Monstro Link apontar: você pode escolher 1 monstro que você controla com 1500 ou menos de ATK; neste turno, ele pode realizar um segundo ataque durante cada Fase de Batalha e, além disso, se ele batalhar um monstro do oponente, qualquer dano de batalha que ele causar ao seu oponente é dobrado. \r\nDurante a Fase de Apoio do próximo turno depois que este card foi destruído em batalha ou por um efeito de card e enviado para o Cemitério: você pode Invocar este card por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Cabicavaleira Filly" uma vez por turno.','\r',char(13)),'\n',char(10)),'Atacar duas vezes','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25920413,'Crânio Alienígena',replace(replace('Você pode oferecer como Tributo 1 monstro de Nível 3 ou menos com a face para cima no lado do campo do oponente para Invocar este card por Invocação-Especial no lado do campo do oponente. \r\nSe você Invocar este monstro por Invocação-Especial dessa forma, coloque 1 Marcador-A neste card, e você não pode Invocar por Invocação-Normal ou Baixar no mesmo turno. \r\n(Se um monstro com um Marcador-A batalhar com um monstro "Alienígena", ele perde 300 de ATK e DEF para cada Marcador-A apenas durante o cálculo de dano).','\r',char(13)),'\n',char(10)),'Colocar "Marcador-A"','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25924653,'Besta Gladiadora Darius',replace(replace('Quando este card for Invocado por Invocação-Especial pelo efeito de um monstro "Besta Gladiadora": você pode escolher 1 monstro "Besta Gladiadora" no seu Cemitério; Invoque o alvo por Invocação-Especial, mas negue seus efeitos e, além disso, ele é embaralhado no Deck quando este card deixar o campo. \r\nNo final da Fase de Batalha, se este card batalhou: você pode embaralhá-lo no Deck; Invoque por Invocação-Especial 1 monstro "Besta Gladiadora" do seu Deck, exceto "Besta Gladiadora Darius".','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial do Cemitério','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25926710,'Kelbek, a Vanguarda Antiga',replace(replace('Se um ou mais cards forem enviados da mão ou do Deck para o Cemitério do seu oponente (exceto durante a Etapa de Dano): você pode escolher 1 monstro Invocado por Invocação-Especial que seu oponente controla; Invoque este card por Invocação-Especial da sua mão e, depois, devolva esse monstro para a mão. \r\nSe este card for enviado da mão ou do Deck para o Cemitério: você pode ativar este efeito; cada duelista envia os 5 cards do topo do Deck dele para o Cemitério (ou todo o seu Deck, se tiver menos de 5) e, depois, se "Troca de Espírito" estiver no seu Cemitério, você pode Baixar 1 Armadilha do seu Cemitério. \r\nVocê só pode usar cada efeito de "Kelbek, a Vanguarda Antiga" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invoque este card por Invocação Especial da sua mão','','Baixar 1 Card Armadilha do seu Cemitério?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25935625,'Jiaotu, Escuridão de Yang Zing',replace(replace('Quando este card que você controla for destruído em batalha ou por um efeito de card e enviado para o seu Cemitério: você pode Invocar por Invocação-Especial 1 monstro "Yang Zing" do seu Deck em Posição de Ataque, exceto "Jiaotu, Escuridão de Yang Zing". \r\nSe você não controlar nenhum monstro: você pode enviar 2 cards "Yang Zing" da sua mão para o Cemitério; Invoque por Invocação-Especial 1 monstro "Yang Zing" com ATK 0 e 1 monstro "Yang Zing" com DEF 0 do seu Deck, mas bana-os durante a Fase Final. \r\nVocê só pode usar 1 efeito de "Jiaotu, Escuridão de Yang Zing" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25940932,'Ascensão do Tufão Radiante',replace(replace('Se este card for destruído pelo efeito de "Tufão Espacial Místico": você pode Baixar este card. \r\nAtive 1 desses efeitos (mas você só pode usar cada um desses efeitos de "Ascensão do Tufão Radiante" uma vez por turno);\r\n● Invoque por Invocação-Especial 1 monstro "Tufão Radiante" de Nível 6 ou menos do seu Cemitério.\r\n● Adicione 1 "Tufão Espacial Místico" do seu Deck ou Cemitério à sua mão.','\r',char(13)),'\n',char(10)),'Ativar','Baixar','Invocação Especial','Adicionar à mão','','','','','','','','','','','','');
INSERT INTO texts VALUES(25955164,'Sanga do Trovão','Uma vez enquanto estiver com a face para cima no campo, durante o cálculo de dano do turno do seu oponente, se este card estiver sendo atacado (Efeito Rápido): você pode escolher o monstro atacante; o ATK do alvo se torna 0 apenas durante o cálculo de dano.','O ATK se torna 0','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25955749,'Força Celeste - Manobra - Bloqueio de Sinal!','Se você não controlar nenhum monstro na sua Zona de Monstros Principal: escolha 1 Magia/Armadilha Baixada no campo; destrua-o e, depois, se você tiver 3 ou mais Magias no seu Cemitério, você pode destruir 1 monstro no campo.','Destruir um card de Monstro?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25958491,'Wivern Sagrado Antigo',replace(replace('1 Regulador de LUZ + 1 ou mais monstros não-Reguladores	\r\nEnquanto seus PV forem maiores que os do seu oponente, este card ganha ATK igual à diferença. \r\nEnquanto seus PV forem menores que os do seu oponente, este card perde ATK igual à diferença. \r\nQuando este card for destruído em batalha e enviado para o Cemitério: você pode pagar 1000 PV; Invoque este card por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25964547,'Hipnagogia do Espelho Onírico',replace(replace('Selecione 1 "Espelho Onírico da Alegria" e 1 "Espelho Onírico do Terror" da sua mão e/ou do Deck e coloque 1 na sua Zona do Campo e o outro na Zona do Campo do seu oponente, com a face para cima. \r\nVocê só pode ativar 1 "Hipnagogia do Espelho Onírico" por turno.','\r',char(13)),'\n',char(10)),'Escolha 1 card para colocar na sua Zona de Campo','Escolha 1 card para colocar na Zona de Campo do seu oponente','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25988873,'Partisan Dragunidade',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode Invocar por Invocação-Especial 1 monstro Besta Alada "Dragunidade" da sua mão e, depois, equipe-o com este card. \r\nEnquanto este card estiver equipado a um monstro, esse monstro é considerado como um Regulador.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial e equipar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26016357,'Marmeloreira Magidoce',replace(replace('Quando este card em sua posse for destruído por um card do oponente (seja em batalha ou por um efeito de card) e enviado ao seu Cemitério: Embaralhe este card no Deck. \r\nQuando este card for virado com a face para cima: Você pode escolher 1 Card de Magia/Armadilha "Magidoce" no seu Cemitério; adicione o alvo à sua mão.','\r',char(13)),'\n',char(10)),'Retornar ao Deck','Retornar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26022485,'Névoa do Desarranjo','O limite de cards na mão do seu adversário torna-se 5.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26034577,'Infernoide Antra',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nVocê deve Invocá-lo por Invocação-Especial (da sua mão) ao banir 1 monstro "Infernoide" da sua mão ou Cemitério enquanto a soma dos Níveis e Classes de todos os Monstros de Efeito que você controla for 8 ou menos, e não pode Invocá-lo por Invocação-Especial de nenhuma outra forma. \r\nUma vez por turno: você pode escolher 1 card com a face para cima que seu oponente controla; devolva-o para a mão. \r\nUma vez por turno, durante o turno do seu oponente: você pode oferecer 1 monstro como Tributo e, depois, escolher 1 card no Cemitério do seu oponente; bana-o (este é um Efeito Rápido).','\r',char(13)),'\n',char(10)),'Retornar 1 card para a mão','Banir cards do Cemitério do seu oponente','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26046205,'Shinobi Vingativo','Quando este card com a face para cima em Posição de Ataque for escolhido como alvo de um ataque: Compre 1 card.','Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26050548,'Hidra Extox',replace(replace('2+ monstros que você controla, Invocados por Invocação-Especial do Deck Adicional	\r\nMonstros que seu oponente controla com o mesmo tipo de card (Fusão, Sincro, Xyz, Pêndulo ou Link) que o de qualquer matéria usada para a Invocação-Fusão deste card perdem ATK igual ao seu próprio ATK original. \r\nQuando este card causar 1000 ou mais de dano de batalha ao seu oponente: você pode comprar 1 card para cada 1000 de dano que você causar.','\r',char(13)),'\n',char(10)),'Usar um Monstro Fusão como Matéria de Fusão','Usar um Monstro Sincro como Matéria de Fusão','Usar um Monstro Xyz como Matéria de Fusão','Usar um Monstro Pêndulo como Matéria de Fusão','Usar um Monstro Link como Matéria de Fusão','','','','','','','','','','','');
INSERT INTO texts VALUES(26057276,'Cavaleirostélite Betelgeuse',replace(replace('Se este card for Invocado: você pode escolher 1 card "Cavaleirost" no seu Cemitério, exceto "Cavaleirostélite Betelgeuse"; envie este card para o Cemitério e, se isso acontecer, adicione o alvo à sua mão. \r\nVocê só pode usar este efeito de "Cavaleirostélite Betelgeuse" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26077387,'Força Celeste - Ás - Raye',replace(replace('(Efeito Rápido): você pode oferecer este card como Tributo; Invoque por Invocação-Especial 1 monstro "Força Celeste - Ás" do seu Deck Adicional na Zona de Monstros Adicional. \r\nEnquanto este card estiver no seu Cemitério, se um Monstro Link "Força Celeste - Ás" com a face para cima que você controla for destruído em batalha, ou deixar o campo por um efeito de card do oponente: você pode Invocar este card por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Força Celeste - Ás - Raye" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26077388,'Força Celeste - Ás - Raye',replace(replace('(Efeito Rápido): você pode oferecer este card como Tributo; Invoque por Invocação-Especial 1 monstro "Força Celeste - Ás" do seu Deck Adicional na Zona de Monstros Adicional. \r\nEnquanto este card estiver no seu Cemitério, se um Monstro Link "Força Celeste - Ás" com a face para cima que você controla for destruído em batalha, ou deixar o campo por um efeito de card do oponente: você pode Invocar este card por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Força Celeste - Ás - Raye" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26077389,'Força Celeste - Ás - Raye',replace(replace('(Efeito Rápido): você pode oferecer este card como Tributo; Invoque por Invocação-Especial 1 monstro "Força Celeste - Ás" do seu Deck Adicional na Zona de Monstros Adicional. \r\nEnquanto este card estiver no seu Cemitério, se um Monstro Link "Força Celeste - Ás" com a face para cima que você controla for destruído em batalha, ou deixar o campo por um efeito de card do oponente: você pode Invocar este card por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Força Celeste - Ás - Raye" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26077390,'Força Celeste - Ás - Raye',replace(replace('(Efeito Rápido): você pode oferecer este card como Tributo; Invoque por Invocação-Especial 1 monstro "Força Celeste - Ás" do seu Deck Adicional na Zona de Monstros Adicional. \r\nEnquanto este card estiver no seu Cemitério, se um Monstro Link "Força Celeste - Ás" com a face para cima que você controla for destruído em batalha, ou deixar o campo por um efeito de card do oponente: você pode Invocar este card por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Força Celeste - Ás - Raye" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26082117,'Mago Gagaga',replace(replace('Uma vez por turno: você pode declarar um Nível de 1 a 8; este card se torna desse Nível até o final deste turno. \r\nVocê só pode controlar 1 "Mago Gagaga". \r\nNão pode ser usado como Matéria Sincro.','\r',char(13)),'\n',char(10)),'Alterar Nível','Declare um Nível','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26082229,'Invasão das Chamas','Quando este card é Invocado, por Invocação-Normal, com sucesso, nenhum Card de Armadilha pode ser activado.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26084285,'Vigia do Coveiro','Quando o seu adversário activa um card que inclua o efeito de fazê-lo descartar da sua própria mão, envie este card da sua mão para o Cemitério para anular a activação e efeito desse card, e destrúi-lo.','Descarte 1 card; negue o efeito e a destrua','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26096328,'Supercouraçado Canhão de Trilho Juggernaut Liebe',replace(replace('3 monstros de Nível 11	\r\nUma vez por turno, você também pode Invocar por Invocação-Xyz "Supercouraçado Canhão de Trilho Juggernaut Liebe" ao usar 1 Monstro Xyz Máquina de Classe 10 que você controla como matéria. \r\n(Transfira as matérias dele para este card.) \r\nUma vez por turno: você pode desassociar 1 matéria deste card; ele ganha 2000 de ATK/DEF e, além disso, pelo resto deste turno, você só pode declarar um ataque com este card. \r\nDurante cada Fase de Batalha, este card pode realizar ataques contra monstros até o número de matérias que tiver +1.','\r',char(13)),'\n',char(10)),'Invocação Xyz usando um Monstro Xyz Máquina como matéria?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26096329,'Supercouraçado Canhão de Trilho Juggernaut Liebe',replace(replace('3 monstros de Nível 11	\r\nUma vez por turno, você também pode Invocar por Invocação-Xyz "Supercouraçado Canhão de Trilho Juggernaut Liebe" ao usar 1 Monstro Xyz Máquina de Classe 10 que você controla como matéria. \r\n(Transfira as matérias dele para este card.) \r\nUma vez por turno: você pode desassociar 1 matéria deste card; ele ganha 2000 de ATK/DEF e, além disso, pelo resto deste turno, você só pode declarar um ataque com este card. \r\nDurante cada Fase de Batalha, este card pode realizar ataques contra monstros até o número de matérias que tiver +1.','\r',char(13)),'\n',char(10)),'Invocação Xyz usando um Monstro Xyz Máquina como matéria?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26099457,'Corrente Cadente','Escolha 1 monstro com a face para cima que você controla e declare um Nível entre 1 e 3; ele se torna desse Nível.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26116996,'Papel Amaldiçoado de Retribuição',replace(replace('Escolha 1 monstro que você controla e 1 card com a face para cima que seu oponente control; destrua seu monstro, e se fizer, negue os efeitos daquele card do oponente até o fim deste turno.\r\nSe este card Baixado for enviado para o Cemitério: você pode escolher 1 card com a face para cima que seu oponente controla, negue seus efeitos.\r\nVocê só pode usar cada um dos efeitos de "Papel Amaldiçoado de Retribuição" uma vez por turno.','\r',char(13)),'\n',char(10)),'Negar o efeito','Negar o efeito','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26118970,'Dragão da Rosa Vermelha',replace(replace('Se este card for enviado para o Cemitério como Matéria Sincro: você pode Invocar por Invocação-Especial 1 monstro "Dragão da Rosa" da sua mão ou do Deck, exceto "Dragão da Rosa Vermelha" e, depois, se ele foi enviado para o Cemitério para a Invocação-Sincro de "Dragão da Rosa Negra" ou de um Monstro Sincro Planta, você também pode adicionar 1 "Rosa Congelada" ou 1 "Florescer da Rosa Mais Negra" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Dragão da Rosa Vermelha" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Escolher 1 card para adicionar à mão?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26120084,'Superinvocação Dupla',replace(replace('Selecione 1 monstro Gêmeos que você controla e Invoque-o por Invocação-Normal. \r\nDurante a Fase Final deste turno, devolva-o para a sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26157485,'Disparador Corrente de Ferro','Uma vez por turno, você pode enviar 1 monstro "Corrente de Ferro" que você controla ao Cemitério para causar 800 de dano ao seu oponente.','Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26162470,'Fandora, o Peloforte de Combate Voador',replace(replace('(Este card deve ser sempre considerado como um card "de Peluguel".)	\r\nMonstros "de Peluguel" que você controla ganham 300 de ATK para cada monstro "de Peluguel" que você controla com um nome diferente. \r\nVocê só pode usar cada um dos seguintes efeitos de "Fandora, o Peloforte de Combate Voador" uma vez por turno. \r\nDurante sua Fase Principal: você pode adicionar 1 monstro "de Peluguel" do seu Deck à sua mão e, depois, descarte 1 card. \r\nSe um ou mais monstros "de Peluguel" com a face para cima que você controla forem destruídos por um efeito de card do oponente (exceto durante a Etapa de Dano): você pode Invocar por Invocação-Especial 1 monstro "de Peluguel" do seu Deck.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26185991,'Gafanhoto Saltitão','Quando este card que você controla for enviado para o seu Cemitério: você pode Invocar por Invocação-Especial 1 monstro Inseto da sua mão.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26194151,'Necroide Sincro',replace(replace('Bana 1 Regulador e até 2 monstros não-Reguladores do seu Cemitério e, se isso acontecer, Invoque por Invocação-Especial 1 Monstro Sincro "Poeira Estelar" do seu Deck Adicional cujo Nível seja igual à soma dos Níveis desses monstros banidos, mas ele tem seus efeitos negados. \r\n(Esta Invocação-Especial é considerada uma Invocação-Sincro.)','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26202165,'Sangan',replace(replace('Se este card for enviado do campo para o Cemitério: adicione 1 monstro com 1500 ou menos de ATK do seu Deck à sua mão, mas você não pode ativar cards, ou os efeitos de cards, com esse nome pelo resto deste turno. \r\nVocê só pode usar este efeito de "Sangan" uma vez por turno.','\r',char(13)),'\n',char(10)),'Procurar no Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26205777,'Thestalos, o Monarca da Tempestade de Fogo','Se este card for Invocado por Invocação-Tributo: descarte 1 card aleatório da mão do seu oponente e, depois, se era um Card de Monstro, cause dano ao seu oponente igual ao Nível original desse monstro x 100.','Seu oponente descarta aleatoriamente 1 card para o Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26211048,'Exa-Cervo Inzektor',replace(replace('2 monstros Inseto de Nível 5	\r\nUma vez por turno: você pode desassociar 1 matéria deste card e, depois, escolha 1 monstro que seu oponente controla ou no Cemitério dele; equipe o alvo a este card. \r\nEste card ganha ATK/DEF igual à metade do ATK/DEF originais dos monstros equipados por este efeito.','\r',char(13)),'\n',char(10)),'Equipar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26223582,'Buerillabaisse de Nouvelles',replace(replace('Você pode Invocar este card por Invocação-Ritual com um card "Receita". \r\nSe este card for Invocado por Invocação-Especial: você pode escavar os 5 cards do topo do seu Deck e, se isso acontecer, você pode adicionar 1 card "Nouvelles" escavado à sua mão e, além disso, embaralhe o resto no Deck. \r\nQuando um card ou efeito for ativado que escolha este card no campo como alvo, ou quando este card for alvo de um ataque (Efeito Rápido): você pode oferecer como Tributo este card e 1 monstro em Posição de Ataque em qualquer campo e, se isso acontecer, Invoque por Invocação-Especial 1 Monstro de Ritual "Nouvelles" de Nível 2 ou 3 da sua mão ou do Deck. \r\nVocê só pode usar cada efeito de "Buerillabaisse de Nouvelles" uma vez por turno.','\r',char(13)),'\n',char(10)),'Revele do Deck e adicione à mão','Invocar por Invocação Especial da sua mão/Deck','Escolher 1 card para adicionar à mão?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26232916,'Vila Oculta das Artes Ninjitsu',replace(replace('Se um monstro "Ninja" for Invocado no seu campo (exceto durante a Etapa de Dano): você pode escolher 1 monstro "Ninja" ou 1 card "Ninjitsu" no seu Cemitério; adicione-o à sua mão, mas pelo resto deste turno, você não pode ativar cards, ou os efeitos de cards, com o mesmo nome que o do card adicionado. \r\nSe um ou mais monstros "Ninja" ou cards "Ninjitsu" que você controla seriam destruídos em batalha ou por um efeito de card do oponente, em vez disso, você pode banir 1 monstro "Ninja" do seu Cemitério. \r\nVocê só pode usar cada efeito de "Vila Oculta das Artes Ninjitsu" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26236560,'Gêmeos Desacorrentados - Aruha',replace(replace('Você pode escolher 1 card que você controla; você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros Demônio e, além disso, destrua o card alvo e, se isso acontecer, Invoque este card por Invocação-Especial da sua mão. \r\nSe este card no campo for destruído por um efeito de card, exceto "Gêmeos Desacorrentados - Aruha", ou em batalha: você pode Invocar por Invocação-Especial 1 monstro "Desacorrentado(a)" da sua mão ou do Deck, exceto "Gêmeos Desacorrentados - Aruha". \r\nVocê só pode usar cada efeito de "Gêmeos Desacorrentados - Aruha" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26237713,'Tesouro Pêndulo',replace(replace('Adicione 1 Monstro Pêndulo do seu Deck ao seu Deck Adicional com a face para cima. \r\nVocê só pode ativar 1 "Tesouro Pêndulo" por turno.','\r',char(13)),'\n',char(10)),'Escolha 1 card para adicionar ao Deck Adicional','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26254876,'Lanceiro Gêmeos',replace(replace('Este card é considerado como um Monstro Normal enquanto estiver com a face para cima no campo ou no Cemitério. \r\nEnquanto este card estiver com a face para cima no campo, você pode Invocá-lo por Invocação-Normal para fazer com que ele seja considerado como um Monstro de Efeito com este efeito:\r\n● Durante a batalha entre este card atacante e um monstro em Posição de Defesa cuja DEF seja menor do que o ATK deste card, cause a diferença como Dano de Batalha ao seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26257572,'Corredor da Agonia','Monstros que foram Invocados por Invocação-Especial do Deck Principal não podem ativar seus efeitos, seus efeitos são negados e eles não podem declarar um ataque, enquanto eles permanecerem com a face para cima no campo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26259179,'Par de Ases',replace(replace('Se este card estiver na sua mão: você pode lançar uma moeda e, se o resultado for cara, Invoque este card por Invocação-Especial no seu campo ou, se o resultado for coroa, Invoque este card por Invocação-Especial no campo do seu oponente. \r\nVocê só pode usar este efeito de "Par de Ases" uma vez por turno. \r\nSe este card for Invocado por Invocação-Especial por seu efeito: compre 2 cards.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26268488,'Dragão Divino Sifr da Poeira Estelar',replace(replace('1 Monstro Sincro Regulador + 2+ Monstros Sincro não-Reguladores	\r\nDeve ser Invocado por Invocação-Sincro. \r\nNa primeira vez que cada card que você controla seria destruído a cada turno, em batalha ou por um efeito de card, ele não é destruído. \r\nUma vez por turno, quando seu oponente ativar um efeito de monstro (Efeito Rápido): você pode negar esse efeito e, se isso acontecer, destrua 1 card no campo. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 monstro "Poeira Estelar" de Nível 8 ou menos no seu Cemitério; Invoque-o por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Negue o efeito e depois destrua 1 card no campo.','Invocação Especial','O efeito de prevenção de destruição já foi usado','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26270847,'Camarartista Garras Prateadas',replace(replace('Escala de Pêndulo = 5\r\n[ Efeito de Pêndulo ]\r\nTodos os monstros "Camarartista" que você controla ganham 300 de ATK.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nQuando este card declarar um ataque: até o final da Fase de Batalha, todos os monstros "Camarartista" que você controla atualmente ganham 300 de ATK.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26273196,'Mago do Tempo do Amanhã',replace(replace('"Mago do Tempo" + 1 Monstro de Efeito	\r\nUma vez por turno, enquanto você controlar este card Invocado por Invocação-Fusão: você pode lançar uma moeda e escolher cara ou coroa. \r\nDestrua tantos monstros no campo quanto possível e, se isso acontecer, cause dano igual à metade da soma do ATK original desses monstros com a face para cima destruídos. \r\nSe você ganhou o lance de moeda, seu oponente sofre o dano, se você perdeu, você sofre o dano.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26285557,'Face Turn Gouki',replace(replace('Escolha 1 card "Gouki" que você controla e 1 monstro "Gouki" no seu Cemitério; destrua esse card no campo e, se isso acontecer, Invoque por Invocação-Especial esse outro monstro do Cemitério. \r\nVocê só pode ativar 1 "Face Turn Gouki" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26285788,'Teste e Tribulação',replace(replace('Você só pode ativar 1 "Teste e Tribulação" por turno. \r\nDurante a Fase Final do turno em que este card foi ativado, aplique este efeito, dependendo do número de monstros que você ofereceu como Tributo do campo e da sua mão neste turno, exceto Fichas.\r\n● 1: Compre 1 card.\r\n● 2: Adicione 2 monstros do seu Cemitério à sua mão.\r\n● 3+: Destrua até 3 cards com a face para cima no campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26293219,'Caveira Incandescente',replace(replace('Quando este card for Invocado por Invocação-Especial da sua mão, cause 1000 de dano ao seu oponente. \r\nVocê pode remover de jogo este card com a face para cima que você controla para devolver 1 "Caveira de Chamas" removido de jogo para o Cemitério de seu dono.','\r',char(13)),'\n',char(10)),'Causar dano','Retornar ao Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26302107,'Perigo! Homem-Cão!',replace(replace('Você pode revelar este card na sua mão; seu oponente seleciona aleatoriamente 1 card de toda a sua mão e, depois, você descarta o card selecionado. \r\nDepois, se o card descartado não era "Perigo! Homem-Cão!", Invoque por Invocação-Especial 1 "Perigo! Homem-Cão!" da sua mão e, se isso acontecer, compre 1 card. \r\nSe este card for descartado: você pode fazer com que todos os monstros com a face para cima que seu oponente controla atualmente percam 1000 de ATK até o final deste turno. \r\nVocê só pode usar este efeito de "Perigo! Homem-Cão!" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26302522,'Esfera Explosiva',replace(replace('Se este card com a face para baixo em Posição de Defesa foi atacado por um monstro do oponente, antes do cálculo de dano: equipe este card no monstro atacante. \r\nDepois, durante a próxima Fase de Apoio do seu oponente: destrua o monstro ao qual este card está equipado e, se isso acontecer, cause dano ao seu oponente igual ao ATK que o monstro destruído tinha no campo.','\r',char(13)),'\n',char(10)),'Equipar','Destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26304459,'Divindade Anciã de Flamvell',replace(replace('1 Regulador de FOGO + 1+ monstros Piro não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro: bana cards do Cemitério do seu oponente, até o número de cards na mão dele e, se isso acontecer, este card ganha 200 de ATK para cada card banido por este efeito.','\r',char(13)),'\n',char(10)),'Banir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26308721,'Predaplanta Pterapenthes',replace(replace('Quando este card causar dano de batalha ao seu oponente: você pode escolher 1 monstro com a face para cima que seu oponente controla; coloque 1 Marcador de Predador sobre ele e, se ele for de Nível 2 ou mais, ele se torna de Nível 1 enquanto tiver um Marcador de Predador. \r\nUma vez por turno: você pode escolher 1 monstro que seu oponente controla com um Nível menor ou igual que o deste card; tome o controle dele até a Fase Final.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26326541,'Shiranui Espadasaga',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nVocê só pode Invocar um ou mais "Shiranui Espadasaga" por Invocação-Especial uma vez por turno. \r\nSe este card for Invocado por Invocação-Especial: você pode escolher 1 monstro no campo; mude a posição de batalha dele. \r\nSe este card for banido: você pode Invocar por Invocação-Especial 1 "Ficha Shiranui" (Zumbi/FOGO/Nível 1/ATK 0/DEF 0). \r\nVocê só pode usar este efeito de "Shiranui Espadasaga" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26326542,'Ficha Shiranui','Invocada por Invocação-Especial com o efeito "Shiranui Espadasaga".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26329679,'Constelar Ômega',replace(replace('2 monstros de LUZ de Nível 4	\r\nUma vez por turno (Efeito Rápido): você pode desassociar 1 matéria deste card; monstros "Constelar" que você controla atualmente não são afetados por efeitos de Magia/Armadilha neste turno.','\r',char(13)),'\n',char(10)),'Não é afetado por efeitos','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26334139,'Subjugar Despojos do Pecado',replace(replace('Pegue 1 monstro Ilusão de Nível 5 ou mais do seu Deck e adicione-o à sua mão ou Invoque-o por Invocação-Especial, mas se você o Invocar por Invocação-Especial com este efeito, você não pode ativar seus efeitos durante a Fase Principal deste turno. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 card com a face para baixo que você controla; devolva-o para a mão e, depois, você pode Baixar 1 Magia/Armadilha da sua mão. \r\nVocê só pode usar 1 efeito de "Subjugar Despojos do Pecado" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Retornar para a mão','Baixar?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26345570,'Cronomalia Painel do Olho da Pirâmide','Todos os monstros "Cronomalia" que você controla ganham 800 de ATK.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26357901,'Intrusão Imprudente',replace(replace('Seus PV devem ser menores que os do seu oponente para ativar e resolver este efeito.\r\nAtive 1 desses efeitos;\r\n● Destrua 1 monstro que seu oponente controla com ATK igual ou menor que a diferença de PV.\r\n● Invoque por Invocação-Especial 1 monstro do seu Cemitério com ATK igual ou menor que a diferença de PV.','\r',char(13)),'\n',char(10)),'Destruir um monstro','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26364381,'Demiurgo Ema',replace(replace('Você pode enviar 4 monstros com 2400 ou mais de ATK e 1000 de DEF da sua mão, Deck e/ou com a face para cima no campo para o Cemitério; Invoque por Invocação-Especial este card da sua mão.\r\nVocê pode escolher 1 Magia/Armadilha em cada campo; destrua-os, então Invoque por Invocação-Especial 1 "Ficha de Homúnculo" (Fada/LUZ/Nível 2/ATK 800/DEF 800) para cada campo em Posição de Defesa, e se fizer, este card ganha 1600 de ATK.\r\nVocê só pode usar cada um dos efeitos de "Demiurgo Ema" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26364382,'Ficha de Homúnculo','Invocado por Invocação-Especial com o efeito de "Demiurgo Ema".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26372118,'ALERTAR!',replace(replace('(Este card deve ser sempre considerado como um card "ÁS-Resgate".)	\r\nAdicione 1 monstro "ÁS-Resgate" do seu Cemitério à sua mão ou, se você controlar "ÁS-Resgate Hidrante", em vez disso, você pode adicionar 1 monstro "ÁS-Resgate" do seu Deck à sua mão. \r\nVocê só pode ativar 1 "ALERTAR!" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26376390,'Imitador','Se este card for Invocado: escolha 1 monstro com a face para cima que seu oponente controla; o ATK/DEF deste card se tornam iguais ao ATK/DEF originais desse monstro.','Alterar ATK/DEF','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26378150,'Kaiser Violento','Com um machado em cada mão, este monstro causa grandes estragos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26381750,'Águia Sobrevoando a Terra Ardente',replace(replace('Se este card for enviado ao Cemitério para uma Invocação-Sincro: Você pode Invocar este card por Invocação-Especial. \r\nVocê deve ter 3 ou mais monstros "Laval" com nomes diferentes no seu Cemitério para ativar e resolver este efeito. \r\nSe este card for Invocado por Invocação-Especial com este efeito, bana-o quando ele deixar o campo.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26387390,'Sinal de Sucata',replace(replace('Ative 1 desses efeitos (além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto Monstros Sincro);\r\n● Ofereça 1 monstro como Tributo; Invoque 1 monstro por Invocação-Especial, exceto o monstro oferecido como Tributo, da sua mão, do Deck ou do Cemitério, que seja "Guerreiro Sucata" ou "Dragão da Poeira Estelar", ou que mencione qualquer um dos dois.\r\n● Quando seu oponente ativar um card ou efeito em resposta à ativação de um efeito de um Monstro Sincro seu: negue o efeito.	\r\nVocê só pode ativar 1 "Sinal de Sucata" por turno.','\r',char(13)),'\n',char(10)),'Ativar','Invocação Especial','Negar o efeito','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26400609,'Maré, Dragão Soberano das Cachoeiras',replace(replace('Se este card estiver na sua mão ou no Cemitério: você pode banir um total de 2 monstros de ÁGUA e/ou Dragão da sua mão e/ou do Cemitério, exceto este card; Invoque este card por Invocação-Especial. \r\nDurante a Fase Final do seu oponente, se você controlar este card Invocado por Invocação-Especial: devolva-o para a mão. \r\nVocê pode descartar este card e 1 monstro de ÁGUA para o Cemitério; envie 1 monstro do seu Deck para o Cemitério. \r\nSe este card for banido: você pode adicionar 1 monstro Dragão de ÁGUA do seu Deck à sua mão. \r\nVocê só pode usar 1 efeito de "Maré, Dragão Soberano das Cachoeiras" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial da mão','Retornar à mão','Enviar 1 monstro do seu Deck para o Cemitério','Adicionar à mão','','','','','','','','','','','','');
INSERT INTO texts VALUES(26412047,'Tiro a Martelo','Destrua o 1 monstro em Posição de Ataque no campo com o maior ATK (em caso de empate, você seleciona).','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26420373,'Velocidaroide Planador Zunindo',replace(replace('Escala de Pêndulo = 3\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno: você pode enviar 1 Regulador "Velocidaroide" da sua mão ou com a face para cima no seu campo para o Cemitério; até o final deste turno, aumente ou reduza (mín. 1) a Escala de Pêndulo deste card pelo Nível original do monstro enviado.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe não houver monstros no campo, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Velocidaroide Planador Zunindo" por Invocação-Especial uma vez por turno desta forma. \r\nQuando este card for Invocado por Invocação-Tributo: você pode escolher 1 monstro "Velocidaroide" de Nível 4 ou menos no seu Cemitério; Invoque-o por Invocação-Especial. \r\nOs monstros do seu oponente não podem escolher monstros "Velocidaroide" como alvo de ataques, exceto este.','\r',char(13)),'\n',char(10)),'Alterar a Escala','Aumentar a Escala','Reduzir a Escala','Invocar por Invocação Especial 1 monstro "Velocidaroide" do seu Cemitério','','','','','','','','','','','','');
INSERT INTO texts VALUES(26434972,'Kyrie do Criademônio',replace(replace('Neste turno, seus monstros Demônio de LUZ não podem ser destruídos em batalha e, além disso, qualquer dano de batalha que você sofrer é diminuído pela metade. \r\nVocê pode banir este card do seu Cemitério; Invoque por Invocação-Fusão 1 Monstro de Fusão "Criademônio" do seu Deck Adicional, usando monstros que você controla, e/ou monstros nas suas Zonas de Magias & Armadilhas que estiverem equipados a um monstro "Criademônio" como uma Magia de Equipamento, como matéria. \r\nVocê só pode usar este efeito de "Kyrie do Criademônio" uma vez por turno.','\r',char(13)),'\n',char(10)),'Não pode ser destruído em batalha','Invocação Fusão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26435595,'Patissciel Couverture',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nSe você não tiver cards na sua outra Zona de Pêndulo: você pode colocar 1 Monstro Pêndulo com a face para cima do seu Deck Adicional na sua Zona de Pêndulo. \r\nVocê só pode usar este efeito de "Patissciel Couverture" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\n2 Monstros Pêndulo	\r\nSe este card na Zona de Monstros for destruído: você pode colocar este card na sua Zona de Pêndulo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26439287,'Primeiro Dragão Cibernético','O nome deste card se torna "Dragão Cibernético" enquanto estiver no campo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26443791,'Vespabatalha - Ballista, o Armagedom',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Especial: você pode banir todos os monstros Inseto do seu Cemitério; todos os monstros que seu oponente controla atualmente perdem 500 de ATK/DEF para cada um dos seus monstros Inseto banidos. \r\nSe este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante. \r\nSe este card Invocado por Invocação-Sincro sob o controle do seu dono for destruído por um card do oponente: você pode Invocar por Invocação-Especial 3 dos seus monstros Inseto banidos de Nível 11 ou menos.','\r',char(13)),'\n',char(10)),'Reduzir ATK/DEF','Invoque por Invocação Especial um monstro banido','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26462013,'Dragão Primita Nether Berzelius',replace(replace('1 monstro "Primita" + 1+ Monstros Normais	\r\nGanha 1000 de ATK para cada Monstro Normal usado em sua Invocação-Fusão. \r\nNegue os efeitos ativados dos monstros que seu oponente controla, cujos Níveis/Classes/Valores Link sejam iguais ou menores que o número de Monstros Normais no seu campo e Cemitério. \r\nSe este card for enviado do campo para o Cemitério: você pode Invocar por Invocação-Especial 1 Monstro Normal do seu Deck em Posição de Defesa.','\r',char(13)),'\n',char(10)),'','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26493435,'Onomatopia',replace(replace('Sempre que um ou mais monstros "Utopia" forem Invocados por Invocação-Especial no seu campo, coloque 1 Marcador de Subir aos Céus neste card. \r\nOs monstros que você controla ganham 200 de ATK/DEF para cada Marcador de Subir aos Céus neste card. \r\nUma vez por turno: você pode remover 2 Marcadores de Subir aos Céus deste card; Invoque por Invocação-Especial 1 monstro "Zubaba", "Gagaga", "Gogogo" ou "Dododo" do seu Deck.','\r',char(13)),'\n',char(10)),'Colocar um marcador','Invocação Especial','Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26495087,'Lady Vampira','Se este card causar dano de batalha ao seu oponente: declare 1 tipo de card (Monstro, Magia ou Armadilha); seu oponente envia 1 card desse tipo do Deck dele para o Cemitério.','Enviar para o Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26509612,'Gravidade de Terra Firma','Durante a Fase de Batalha do seu oponente, se você controlar "Terra Firma, o HERÓI do Elemento": Neste turno, todos os monstros de Nível 4 ou menos que seu oponente controla que podem atacar um "Terra Firma, o HERÓI do Elemento" com a face para cima que você controla devem atacá-lo, e não podem atacar de outra forma.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26517393,'Espírito do Vento de Outono','Se este card for Invocado por Invocação-Normal: você pode adicionar 1 monstro de Virar do seu Deck à sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26523337,'Psiics, Luar dos Ghoti',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 monstro Peixe do seu Deck à sua mão, exceto "Psiics, Luar dos Ghoti" e, depois, bana 1 monstro Peixe da sua mão ou do campo com a face para cima. \r\nSe este card for banido: você pode banir 1 monstro Peixe da sua mão, do Cemitério ou do campo com a face para cima, exceto "Psiics, Luar dos Ghoti"; Invoque este card por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Psiics, Luar dos Ghoti" uma vez por turno.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Invocar este card por Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26533075,'Orbe de Segurança',replace(replace('Quando um monstro do seu oponente declarar um ataque: escolha o monstro atacante; mude a posição de batalha do alvo. \r\nSe este card Baixado for destruído por um efeito de Magia/Armadilha do seu oponente e enviado para o Cemitério: destrua 1 monstro no campo.','\r',char(13)),'\n',char(10)),'Destrua 1 monstro no campo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26534688,'Magelhanica, a Cidade do Mar-Profundo',replace(replace('(O nome deste card deve ser sempre considerado como "Umi".)	\r\nQuando este card for ativado: você pode colocar 1 monstro de ÁGUA do seu Deck no topo do seu Deck. \r\nUma vez por turno: você pode escolher 1 monstro de ÁGUA que você controla; aumente o Nível dele em 1 ou 2 até o final deste turno (mesmo que este card deixe o campo). \r\nUma vez por turno, durante sua Fase Principal, se você Invocar por Invocação-Especial um Monstro Sincro de ÁGUA: você pode olhar a mão do seu oponente e, se isso acontecer, até a Fase Final, bana 1 card da mão dele com a face para cima.','\r',char(13)),'\n',char(10)),'','','Escolher 1 monstro de ÁGUA do seu Deck e colocá-lo no topo do Deck?','Escolha o(s) card(s) para colocar no topo do Deck','Escolha o monstro cujo Nível será aumentado','','','','','','','','','','','');
INSERT INTO texts VALUES(26548709,'Besouro Samurai Ragnaraika',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) ao colocar 1 dos seus monstros Inseto, Planta ou Réptil que estiverem banidos no fundo do seu Deck Principal. \r\nVocê só pode Invocar "Besouro Samurai Ragnaraika" por Invocação-Especial uma vez por turno desta forma. \r\nSe este card for enviado para o Cemitério como matéria para um Monstro Link "Ragnaraika": você pode escolher 1 monstro Inseto, Planta ou Réptil de Nível 4 ou menos no seu Cemitério, exceto "Besouro Samurai Ragnaraika"; Invoque-o por Invocação-Especial em Posição de Defesa. \r\nVocê só pode usar este efeito de "Besouro Samurai Ragnaraika" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Invocar por Invocação Especial um monstro Inseto/Planta/Réptil','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26556950,'Número 84: Acumuladora de Dor',replace(replace('2 monstros de Nível 11	\r\nVocê também pode Invocar este card por Invocação-Xyz ao usar um Monstro Xyz de TREVAS de Classe 8, 9 ou 10 que você controla com 2 ou mais matérias. \r\n(Transfira as matérias dele para este card.) \r\nGanha DEF igual às Classes combinadas de todos os Monstros Xyz que você controla x 200. \r\nEnquanto este card tiver matéria, sempre que seu oponente ativar um Card de Magia/Armadilha, cause 600 de dano ao seu oponente imediatamente depois que ele resolver. \r\nUma vez por turno: você pode desassociar 1 matéria deste card; destrua todos os monstros com a face para cima que seu oponente controla com DEF igual ou menor que a deste card.','\r',char(13)),'\n',char(10)),'Escolha um Monstro Xyz de TREVAS de Classe 8 a 10','Destruir 1 monstro','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26557451,'Descarga de Compra',replace(replace('Quando seu oponente comprar um ou mais cards por meio de um efeito de card dele: olhe esses cards e, se qualquer um deles for um monstro, cause dano ao seu oponente igual ao ATK combinado deles e, se isso acontecer, bana todos os cards que você olhou. \r\nVocê só pode ativar 1 "Descarga de Compra" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26561172,'Mutante Miutante',replace(replace('Se você controlar um card "Miutante": você pode Invocar este card por Invocação-Especial da sua mão. \r\nVocê pode oferecer este card como Tributo e, depois, banir 1 card "Miutante" da sua mão ou do Deck; Invoque por Invocação-Especial 1 monstro da sua mão ou do Deck, de acordo com o card banido, mas perca PV igual ao ATK original desse monstro Invocado por Invocação-Especial.\r\n● Monstro: "Besta Miutante"\r\n● Magia: "Névoa Miutante"\r\n● Armadilha: "Arsenal Miutante"\r\nVocê só pode usar cada efeito de "Mutante Miutante" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26563200,'Muzuritmo, o Djinn das Guitarras',replace(replace('2 monstros de Nível 3	\r\nQuando um Monstro Xyz "Djinn" que você controla estiver atacando um monstro do oponente, durante a Etapa de Dano: você pode desassociar 1 Matéria Xyz deste card; o ATK do monstro atacante é dobrado até a Fase Final. \r\nVocê só pode usar este efeito de "Muzuritmo, o Djinn das Guitarras" uma vez por turno.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26566878,'Demônio Escorpião','Um grande escorpião habitado pela alma de um demônio. Normalmente ele controla-se, mas tem um grande potencial.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26570480,'Pintinhocolate Magidoce',replace(replace('Quando este card em sua posse for destruído por um card do seu oponente (seja em batalha ou por um efeito de card) e enviado para o seu Cemitério: embaralhe este card no Deck. \r\nUma vez por turno, quando a posição de batalha de um ou mais monstros "Magidoce" que você controla for alterada (e se eles estiverem com a face para cima), enquanto este card estiver com a face para cima no campo (exceto durante a Etapa de Dano): você pode escolher 1 monstro no campo; coloque-o com a face para cima em Posição de Defesa e, se isso acontecer, a não ser que ele seja um monstro "Magidoce", ele não pode atacar e, além disso, seus efeitos são negados.','\r',char(13)),'\n',char(10)),'Retornar ao Deck','Mudar a posição de batalha','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26577155,'Remus Dragunidade',replace(replace('Não pode ser usado como Matéria Sincro, exceto para a Invocação-Sincro de um monstro "Dragunidade". \r\nVocê pode descartar este card; adicione 1 "Ravina de Dragões" do seu Deck à sua mão. \r\nSe você controlar um monstro "Dragunidade": você pode Invocar este card por Invocação-Especial do seu Cemitério, mas bana-o quando ele deixar o campo e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto monstros Dragão. \r\nVocê só pode usar cada efeito de "Remus Dragunidade" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26582143,'Besta Gladiadora Gistel',replace(replace('No final da Fase de Batalha, se este card batalhou: você pode embaralhar este card no Deck; Invoque por Invocação-Especial 1 monstro "Besta Gladiadora" do seu Deck, exceto "Besta Gladiadora Gistel". \r\nVocê só pode usar cada um dos seguintes efeitos de "Besta Gladiadora Gistel" uma vez por turno. \r\nVocê pode revelar este card e 1 monstro "Besta Gladiadora" na sua mão; Invoque os dois por Invocação-Especial. \r\nSe este card for Invocado por Invocação-Especial pelo efeito de um monstro "Besta Gladiadora": você pode adicionar 1 Magia/Armadilha "Gladiador" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Invocação Especial','Adicionar à mão uma Magia/Armadilha','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26585784,'Experimento de Liberação Especial K9-EW',replace(replace('Invoque por Invocação-Especial 1 monstro "K9" da sua mão ou do Cemitério e, depois, você pode Invocar por Invocação-Especial 1 Monstro Xyz "K9" do seu Deck Adicional, usando esse monstro como matéria (isso é considerado uma Invocação-Xyz), mas destrua o monstro Invocado por Invocação-Especial do Deck Adicional durante a Fase Final do próximo turno. \r\nDurante a Fase Final: você pode banir este card do seu Cemitério e, depois, escolha 1 Magia Rápida "K9" no seu Cemitério; Baixe-a. \r\nVocê só pode usar cada efeito de "Experimento de Liberação Especial K9-EW" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Baixar','Invocação Xyz?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26586849,'Prisão Real','Nenhum duelista pode Invocar monstros por Invocação-Especial do Cemitério.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26593852,'Catastor, Aliado da Justiça',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nNo começo da Etapa de Dano, se este card batalhar um monstro com a face para cima que não seja de TREVAS: destrua esse monstro.','\r',char(13)),'\n',char(10)),'Destruir monstros que não sejam de TREVAS','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26631975,'Domínio Dinomorfia',replace(replace('Durante a Fase Principal: pague metade dos seus PV; Invoque por Invocação-Fusão 1 Monstro de Fusão "Dinomorfia" do seu Deck Adicional, usando monstros da sua mão, do Deck ou do campo como matéria. \r\nQuando seu oponente ativar um card ou efeito, enquanto seus PV forem 2000 ou menos: você pode banir este card do seu Cemitério; neste turno, você não sofre dano de efeito dos efeitos de card do seu oponente. \r\nVocê só pode ativar 1 "Domínio Dinomorfia" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26638543,'Metrognomo',replace(replace('Escala de Pêndulo = 4\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno: você pode escolher 1 outro card em uma Zona de Pêndulo; até o final deste turno, a Escala de Pêndulo deste card se torna igual à desse card.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nEnquanto você tiver 2 cards com a mesma Escala de Pêndulo nas suas Zonas de Pêndulo, este card ganha ATK e DEF igual à Escala de Pêndulo x 100 e pode atacar diretamente seu oponente. \r\nSe este card causar dano de batalha ao seu oponente em um ataque direto: destrua todos os cards nas Zonas de Pêndulo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26640671,'Covil das Aranhas',replace(replace('Uma vez por turno, você pode selecionar 1 monstro do Tipo Inseto com a face para cima que você controla. \r\nEnquanto este card permanecer no campo, qualquer monstro do oponente que batalhar com um desses monstros é colocado em Posição de Defesa no final da Fase de Batalha e não pode mudar a sua posição de batalha enquanto este card estiver no campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26647858,'Anel do Herói',replace(replace('Escolha 1 monstro Guerreiro no campo com 1500 ou menos de ATK; equipe este card no alvo. \r\nMonstros que seu oponente controla com 1900 ou mais de ATK não podem atacar o monstro equipado.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26655293,'Dragão Magnafoguette',replace(replace('Quando um efeito de Monstro Link for ativado que escolha como alvo este card com a face para cima no campo (Efeito Rápido): você pode destruir este card e, depois, envie para o Cemitério 1 monstro no campo. \r\nDurante a Fase Final, se este card estiver no Cemitério porque foi destruído no campo, em batalha ou por um efeito de card e enviado para lá neste turno: você pode Invocar por Invocação-Especial 1 monstro "Foguette" do seu Deck, exceto "Dragão Magnafoguette". \r\nVocê só pode usar cada efeito de "Dragão Magnafoguette" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26669055,'Sábia do Silêncio','Se este card destruir um monstro do oponente em batalha, seu oponente não pode ativar Cards de Magia durante o próximo turno.','Restrição de ativação','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26674724,'Necroz de Brionac',replace(replace('Você pode Invocar este card por Invocação-Ritual com qualquer Magia de Ritual "Necroz". \r\nDeve ser Invocado por Invocação-Ritual sem usar "Necroz de Brionac". \r\nVocê só pode usar cada um desses efeitos de "Necroz de Brionac" uma vez por turno.\r\n● Você pode descartar este card; adicione 1 monstro "Necroz" do seu Deck à sua mão, exceto "Necroz de Brionac".\r\n● Você pode escolher até 2 monstros com a face para cima no campo que foram Invocados por Invocação-Especial do Deck Adicional; embaralhe-os no Deck.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Retornar ao Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26684111,'As Águas Sagradas no Céu',replace(replace('Ative 1 "O Santuário no Céu" diretamente do seu Deck, ou adicione 1 monstro que mencione "O Santuário no Céu" do seu Deck à sua mão e, depois, se "O Santuário no Céu" estiver no campo ou em qualquer Cemitério, você pode ganhar 500 PV para cada monstro "Hyperion" e "O Representante" que você controla. \r\nSe um monstro seu que mencione "O Santuário no Céu" seria destruído em batalha, em vez disso, você pode banir este card do seu Cemitério. \r\nVocê só pode usar cada efeito de "As Águas Sagradas no Céu" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar "O Santuário no Céu"','Adicionar 1 monstro à mão','Ganhar PV?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26692769,'Os Cavaleiros Fantasmas do Bardiche Enferrujado',replace(replace('2+ monstros de TREVAS	\r\nDurante sua Fase Principal: você pode enviar 1 monstro "Os Cavaleiros Fantasmas" do seu Deck para o Cemitério e, depois, Baixe 1 Magia/Armadilha "Cavaleiros Fantasmas" diretamente do seu Deck em uma Zona de Magias & Armadilhas sua. \r\nSe um ou mais Monstros Xyz de TREVAS forem Invocados por Invocação-Especial em uma ou mais zonas para as quais este card apontar, enquanto este monstro estiver no campo (exceto durante a Etapa de Dano): você pode escolher 1 card no campo; destrua-o. \r\nVocê só pode usar cada efeito de "Os Cavaleiros Fantasmas do Bardiche Enferrujado" uma vez por turno. \r\nNão pode ser usado como Matéria Link.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26700718,'Dramática Perseguição Olho de Cobra',replace(replace('Coloque 1 monstro "Diabellstar" da sua mão, do Deck ou do Cemitério com a face para cima na Zona de Magias & Armadilhas do seu dono como uma Magia Contínua. \r\nDurante a Fase Final: você pode banir este card do seu Cemitério e, depois, escolha 1 Card de Monstro que você controla considerado como uma Magia Contínua; Invoque-o por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Dramática Perseguição Olho de Cobra" uma vez por turno.','\r',char(13)),'\n',char(10)),'Colocar como Magia Contínua','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26701483,'Ejetor de Cards','Uma vez por turno: Você pode escolher 1 card no Cemitério do seu oponente; bana o alvo.','Banir 1 card no Cemitério do seu oponente','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26704411,'Kokkator, o Mitológico','Quando este card destruir um monstro do oponente em batalha e enviá-lo para o Cemitério: você pode descartar 1 monstro "Mitológico(a)"; compre 1 card.','Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26708437,'Reviver Xyz','Escolha 1 Monstro Xyz no seu Cemitério; Invoque-o por Invocação-Especial e, se isso acontecer, associe este card a ele como matéria.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26722601,'Protetor do Hordeum Ferro','Se um monstro "Hordeum Ferro" for Invocado por Invocação-Tributo com a face para cima enquanto este card estiver com a face para cima no campo, você pode Invocar por Invocação-Normal ou Baixar 1 monstro em adição à sua Invocação-Normal ou Baixar nesse turno.','Invocar pelo efeito de "Protetor do Hordeum Ferro"','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26725158,'Exílio do Perverso','Destrua todos os monstros Demônio no campo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26732909,'Justiça da Profecia',replace(replace('Durante sua Fase Final, se você ativou um Card de Magia "Livro de Magia" previamente neste turno: você pode banir este card do campo; adicione 1 monstro de LUZ ou TREVAS do Tipo Mago de Nível 5 ou mais e 1 Card de Magia "Livro de Magia" do seu Deck à sua mão. \r\nVocê só pode usar o efeito de "Justiça da Profecia" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26746975,'Guardião Sombrio',replace(replace('(Este card deve ser sempre considerado como um card "Guardião do Portão".)	\r\nNão pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial por "Elemento Sombrio", ou Invocado por Invocação-Especial (da sua mão ou do Cemitério) ao embaralhar no Deck 1 de cada dos seus "Sanga do Trovão", "Kazejin" e "Suijin" que estiverem na sua mão, no campo com a face para cima, no Cemitério e/ou banidos. \r\nNão pode ser destruído em batalha. \r\nSe este card for Invocado por Invocação-Especial pelo efeito de "Elemento Sombrio", ele não é afetado pelos efeitos de outros monstros ou pelos Cards de Magia ou seus efeitos, ativados por seu oponente.','\r',char(13)),'\n',char(10)),'Invocado por Invocação Especial pelo efeito de "Elemento Sombrio"','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26773909,'Fervor Psíquico',replace(replace('Durante a Fase de Batalha: escolha 1 monstro com a face para cima que você controla; você perde PV igual ao ATK dele e, se isso acontecer, o ATK desse monstro é dobrado até o final deste turno. \r\nEle não pode atacar diretamente durante o turno em que você ativar este card. \r\nVocê só pode ativar 1 "Fervor Psíquico" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26775203,'Asanegra - Ghibil, o Vento Cortante',replace(replace('Quando seu oponente declarar um ataque direto: você pode Invocar este card por Invocação-Especial da sua mão. \r\nUma vez por turno: até o final deste turno, você pode trocar o ATK e DEF originais deste card.','\r',char(13)),'\n',char(10)),'Invocação Especial','Trocar o ATK/DEF original','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26781870,'Fraude Congelada',replace(replace('Uma vez por turno, quando seu oponente Invocar um ou mais monstros por Invocação-Especial da mão (exceto durante a Etapa de Dano): você pode devolver para a mão todos os monstros que seu oponente controla que foram Invocados por Invocação-Especial da mão. \r\nSe nenhum duelista controlar um Monstro Sincro "Flor Cardian", envie este card para o Cemitério.','\r',char(13)),'\n',char(10)),'Ativar, mas não resolver o efeito','Ativar e aplicar o primeiro Efeito','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26822796,'O Despertar dos Monarcas','Se você não tiver cards no seu Deck Adicional: escolha 1 monstro com a face para cima Invocado por Invocação-Tributo que você controla; seus efeitos são negados e, além disso, ele não é afetado por efeitos de cards que não forem deste card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26834022,'Desarme','Retorne 1 card "Besta Gladiadora" da sua mão para o Deck, e negue a ativação e efeito de um Card de Magia, e destrua-o.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26841274,'D-Fusão',replace(replace('Invoque por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional, usando monstros que você controla como Matéria de Fusão e, se isso acontecer, ele não pode ser destruído em batalha ou por efeitos de card neste turno. \r\nSomente monstros "HERÓI do Destino" podem ser usados como Matéria de Fusão para uma Invocação-Fusão usando o efeito deste card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26842483,'Portador da Justiça','Uma vez por turno, quando um monstro Invocado por Invocação-Especial que seu oponente controla ativar seu efeito, você pode negar a ativação.','Negar o efeito','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26845680,'Retorno Orcustrado',replace(replace('Envie 1 monstro "Orcust" ou "Legado Mundial" da sua mão ou do campo com a face para cima para o Cemitério; compre 2 cards. \r\nVocê só pode ativar 1 "Retorno Orcustrado" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26847978,'Ferrijit, o Florescer Estéril da Tri-Brigada',replace(replace('2 monstros Besta, Besta-Guerreira e/ou Besta Alada	\r\nDurante sua Fase Principal: você pode Invocar por Invocação-Especial 1 monstro Besta, Besta-Guerreira ou Besta Alada de Nível 4 ou menos da sua mão e, além disso, você não pode usar monstros como Matéria Link pelo resto deste turno, exceto monstros Besta, Besta-Guerreira ou Besta Alada. \r\nSe este card for enviado para o Cemitério: você pode comprar 1 card e, depois, coloque 1 card da sua mão no fundo do Deck. \r\nVocê só pode usar cada efeito de "Ferrijit, o Florescer Estéril da Tri-Brigada" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26857786,'Amaldiçoado Rei de Fogo Explosão da Perdição',replace(replace('Se este card for destruído em batalha ou por um efeito de card e enviado para o Cemitério: você pode escolher 1 monstro com a face para cima que seu oponente controla; ele perde 400 de ATK até o final deste turno. \r\nVocê só pode usar cada um dos seguintes efeitos de "Amaldiçoado Rei de Fogo Explosão da Perdição" uma vez por turno. \r\nSe você controlar um Regulador Demônio: você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe este card for Invocado por Invocação-Especial: você pode escolher 1 monstro com a face para cima que seu oponente controla; ele perde 600 de ATK até o final deste turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Reduzir ATK em 600','Reduzir ATK em 400','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26864586,'Aparato Ressonante','Escolha 2 monstros com a face para cima que você controla com o mesmo Tipo e Atributo; mude um de seus Níveis para o Nível atual do outro até a Fase Final.','Escolha o monstro cujo Nível será alterado','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26866984,'Trias Hierarquia',replace(replace('Durante a Fase Principal, se este card estiver na sua mão ou no Cemitério (Efeito Rápido): você pode oferecer como Tributo até 3 monstros Fada; Invoque este card por Invocação-Especial (mas bana-o quando ele deixar o campo) e, depois, você pode aplicar o(s) seguinte(s) efeito(s) em sequência, dependendo do número de monstros oferecidos como Tributo.\r\n● 2+: Destrua 1 card que seu oponente controla.\r\n● 3: Compre 2 cards.	\r\nVocê só pode usar este efeito de "Trias Hierarquia" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Destruir 1 card que seu oponente controla?','Comprar 2 cards do seu Deck?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26873574,'Daedalus do Caos',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro deve ser Invocado por Invocação-Especial (da sua mão) ao banir 1 monstro de LUZ e 1 de TREVAS do seu Cemitério. \r\nEnquanto uma Magia de Campo estiver com a face para cima no campo, seu oponente não pode escolher monstros de LUZ ou de TREVAS que você controla como alvo de efeitos de card. \r\nVocê pode escolher cards no campo, até o número de Magias de Campo com a face para cima no campo; bana-os. \r\nVocê só pode usar este efeito de "Daedalus do Caos" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26885836,'Desafiante Heroico - Martelo de Guerra',replace(replace('Quando este card destruir um monstro do oponente em batalha e enviá-lo para o Cemitério: você pode equipar o monstro destruído a este card. \r\n(Você só pode equipar 1 monstro por vez a este card com este efeito.) \r\nEste card ganha ATK igual ao ATK do monstro equipado.','\r',char(13)),'\n',char(10)),'Equipar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26889158,'Salamagrande Gazela',replace(replace('Se um monstro "Salamagrande" for enviado para o seu Cemitério, exceto "Salamagrande Gazela" (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode enviar 1 card "Salamagrande" do seu Deck para o Cemitério, exceto "Salamagrande Gazela". \r\nVocê só pode usar cada efeito de "Salamagrande Gazela" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial da mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26902560,'Sábio da Fusão','Adicione 1 "Polimerização" do seu Deck à sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26905245,'Limo Reflete Metal',replace(replace('Invoque este card por Invocação-Especial em Posição de Defesa como um Monstro de Efeito (Aqua/ÁGUA/Nível 10/ATK 0/DEF 3000).	\r\n(Este card ainda é considerado uma Armadilha.) \r\nSe Invocado desta forma, este card não pode atacar.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26913989,'Golem Geistafiado',replace(replace('Você só pode Invocar "Golem Geistafiado" por Invocação-Especial uma vez por turno. \r\nVocê pode revelar 1 monstro "Yubel" da sua mão; Invoque este card por Invocação-Especial da sua mão no campo do seu oponente e, depois, você pode Invocar o monstro revelado por Invocação-Especial no seu campo. \r\nUma vez por turno, durante o cálculo de dano, se este card batalhar um monstro "Yubel": seu oponente ganha 3000 PV. \r\nSe você Invocar "Yubel" por Invocação-Especial enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial no campo do seu oponente.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial para o campo do seu oponente','Ganhar PV','Invocar por Invocação Especial para o campo do seu oponente','Invocar o monstro revelado por Invocação Especial?','','','','','','','','','','','','');
INSERT INTO texts VALUES(26914168,'Honesto, o Sombrio',replace(replace('Uma vez por turno, durante sua Fase Principal: você pode devolver este card com a face para cima para a mão. \r\nDurante a Etapa de Dano, quando um monstro de TREVAS seu batalhar um monstro do oponente (Efeito Rápido): você pode enviar este card da sua mão para o Cemitério; até o final deste turno, esse monstro do oponente perde ATK igual ao seu próprio ATK.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26920296,'Terra dos Sonhos',replace(replace('Este card pode ativar esses efeitos, dependendo dos tipos de cards de monstro no campo.\r\n● Fusão: Uma vez por turno, se um ou mais monstros forem enviados da sua mão ou do campo para o Cemitério por um efeito de card (exceto during a Etapa de Dano): você pode comprar 1 card.\r\n● Sincro: Quando um ou mais monstros forem Invocados por Invocação-Normal ou Especial (exceto durante a Etapa de Dano): você pode aumentar o Nível deles em 1.\r\n● Xyz: Uma vez por turno, durante sua Fase Final: destrua o(s) monstro(s) no campo com o maior Nível.	\r\nVocê só pode ativar 1 "Terra dos Sonhos" por turno.','\r',char(13)),'\n',char(10)),'Compre 1 card','Aumente em 1 o Nível de um monstro Invocado','Destrua o(s) monstro(s) com o Nível mais alto no campo','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26931058,'Formação Union',replace(replace('Ative 1 dos seguintes efeitos.\r\n● Escolha 1 monstro União com a face para cima que você controla; equipe-o a 1 monstro apropriado que você controla.\r\n● Desequipe 1 monstro União que você controla que seja um Card de Equipamento e Invoque-o por Invocação-Especial em Posição de Ataque.','\r',char(13)),'\n',char(10)),'Equipar União','Remover Equipamento','Escolha 1 monstro União','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26932788,'Besouro da Lança','Este monstro só pode ser Invocado por Invocação-Ritual com o Card de Magia de Ritual "Pacto do Besouro da Lança".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26949946,'Besta Fantasma Mecha Jaculuslan',replace(replace('1 Regulador "Besta Fantasma Mecha" + 1+ monstros não-Reguladores "Besta Fantasma Mecha"	\r\nQuando este card for Invocado por Invocação-Sincro: você pode oferecer como Tributo "Fichas de Besta Fantasma Mecha" até o número de cards na mão do seu oponente; descarte aleatoriamente cards da mão do seu oponente, igual ao número de monstros oferecidos como Tributo. \r\nOutros monstros "Besta Fantasma Mecha" que você controla não podem ser destruídos em batalha ou por efeitos de card. \r\nSe este card, em posse de seu dono, for destruído pelo seu oponente: você pode Baixar 1 Magia Rápida diretamente do seu Deck.','\r',char(13)),'\n',char(10)),'Destruir cards na mão','Procurar no Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26956670,'Libertação da Pedra',replace(replace('Selecione 1 dos seus monstros do Tipo Rocha que foi removido de jogo e Invoque-o por Invocação-Especial. \r\nQuando este card for removido do campo, destrua aquele monstro. \r\nQuando aquele monstro for destruído, destrua este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26964762,'HERÓI do Destino - Anjo Negro',replace(replace('Se você tiver 3 ou mais monstros "HERÓI do Destino" no seu Cemitério: você pode descartar este card e, depois, escolha 1 monstro "HERÓI do Destino" no seu Cemitério; Invoque-o por Invocação-Especial no campo do seu oponente em Posição de Defesa. \r\nQuando um Card de Magia, ou seus efeitos, que você ativar resolver, negue o efeito e, se isso acontecer, ou se ele não teve efeito, destrua esse card. \r\nDurante sua Fase de Apoio: você pode banir este card e 1 monstro "HERÓI do Destino" do seu Cemitério; cada duelista seleciona 1 Magia Normal do seu Deck e a coloca no topo do seu Deck.','\r',char(13)),'\n',char(10)),'Invocação Especial','Colocar no topo do Deck','Escolha o card a ser colocada no topo do Deck','Escolha o card a ser colocada no topo do Deck','','','','','','','','','','','','');
INSERT INTO texts VALUES(26973555,'Número F0: Futuro Draco Utópico',replace(replace('3 Monstros Xyz com a mesma Classe, exceto monstros "Número"	\r\n(A Classe original deste card deve ser sempre considerada como 1. Este card deve ser sempre considerado como um card "Futuro Utópico".)	\r\nVocê também pode Invocar este card por Invocação-Xyz ao usar "Número F0: Futuro Utópico" que você controla como matéria. \r\n(Transfira as matérias dele para este card.) \r\nNão pode ser destruído em batalha ou por efeitos de card. \r\nUma vez por turno, quando seu oponente ativar um efeito de monstro (Efeito Rápido): você pode desassociar 1 matéria deste card; negue a ativação e, depois, se esse monstro estiver no campo, ganhe o controle dele.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Xyz usando "Número F0: Futuro Utópico" como matéria?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26976414,'Piqueiro Atlante','O Grande Senhor do Oceano, que reina nas profundezas, é servido por esses lanceiros. As criaturas do fundo do mar têm medo de enfrentar a torrente de ataques que suas lanças são capazes de desferir.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26984177,'Muros da Tumba Imperial',replace(replace('O nome deste card se torna "Sarcófago do Rei" enquanto estiver na Zona do Campo. \r\nDurante sua Fase Principal: você pode adicionar 1 monstro "Horus" do seu Deck à sua mão e, depois, coloque 1 card da sua mão no fundo do Deck. \r\nVocê só pode usar este efeito de "Muros da Tumba Imperial" uma vez por turno. \r\nSe você ativar o efeito de "Horus, a Divindade da Chama Negra": você pode comprar 1 card.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Comprar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26988374,'Divindade Magichave - Ashtartu',replace(replace('2 monstros de Nível 8	\r\nUma vez por turno, quando um Monstro Normal ou monstro "Magichave" seu destruir um monstro do oponente em batalha: você pode desassociar 1 matéria deste card; cause dano ao seu oponente igual ao ATK original do monstro destruído. \r\nUma vez por turno, durante a Fase Principal do seu oponente (Efeito Rápido): você pode escolher 1 monstro que seu oponente controla com o mesmo Atributo que um Monstro Normal ou monstro "Magichave" que você controla ou no seu Cemitério; desassocie 1 matéria deste card e, se isso acontecer, bana esse monstro.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26993374,'Sabre-X Uruz','Quando este card destruir um monstro do oponente em batalha e enviá-lo ao Cemitério, você pode oferecer este card como Tributo para devolver o card destruído ao topo do Deck do dono.','Retornar ao Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27001740,'Entrega da Fazenda','Se você controlar um Monstro Normal: Escolha até 3 dos seus Monstros Normais banidos; embaralhe-os no Deck.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27004302,'Tatu-Gema','Quando este card for Invocado por Invocação-Normal: você pode adicionar 1 monstro "Cavaleiro-Gema" do seu Deck à sua mão.','Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27012717,'Feroz Tigre Monghu',replace(replace('Todos os outros monstros no campo perdem 500 de ATK. \r\nUma vez por turno, durante sua Fase Principal: você pode destruir todos os monstros no campo com ATK menor que o deste card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27012990,'Cascata Marincesa',replace(replace('Bana qualquer número de Monstros Link "Marincesa" que você controla (até sua próxima Fase de Apoio) e, depois, escolha 1 monstro com a face para cima no campo; até o final deste turno, ele ganha ATK igual à soma dos Valores Link dos monstros banidos para ativar este card x 300. \r\nSe você controlar um monstro "Marincesa" de Link-3 ou mais, você pode ativar este card da sua mão.','\r',char(13)),'\n',char(10)),'Ativar aplicando o efeito de "Cascata Marincesa".','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27015862,'Veda Kalanta',replace(replace('Se um ou mais cards no campo forem destruídos por um efeito de card e "Visas Starfrost" estiver no campo (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão e, depois, você pode adicionar 1 "Novo Mundo Translúcido" do seu Deck ou Cemitério à sua mão. \r\nSe um ou mais outros monstros em sua posse forem destruídos por um efeito de card (exceto durante a Etapa de Dano): você pode escolher 1 monstro que seu oponente controla; destrua-o e, se isso acontecer, até o final deste turno, este card ganha ATK igual ao ATK original desse monstro. \r\nVocê só pode usar cada efeito de "Veda Kalanta" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invoque este card por Invocação Especial da sua mão','Destrua 1 monstro do seu oponente','Adicionar "Novo Mundo Translúcido" à sua mão?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27024795,'Alviss do Alfar Nórdico',replace(replace('Se apenas este card for banido pelo efeito de um Monstro Link "Nórdic": você pode enviar para o Cemitério, 1 monstro "Nórdic" que você controla e 2 monstros "Nórdic" do seu Deck, cuja soma dos Níveis seja igual a 10 e, depois, Invoque por Invocação-Especial 1 monstro "Aesir" do seu Deck Adicional. \r\nSe um ou mais monstros "Aesir" em sua posse forem enviados para o seu Cemitério por um card do seu oponente: você pode banir este card do seu Cemitério; Invoque por Invocação-Especial 1 monstro "Aesir" do seu Deck Adicional, com um nome diferente que os cards no seu Cemitério. \r\nVocê só pode usar este efeito de "Alviss do Alfar Nórdico" uma vez por Duelo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27036706,'Cavalestrela Ciel',replace(replace('Se este card estiver na sua mão: você pode devolver para a mão 1 monstro "Cavalestrela" ou 1 monstro Dragão de LUZ de Nível 7 que você controla, exceto "Cavalestrela Ciel"; Invoque este card por Invocação-Especial. \r\nSe você não controlar nenhum monstro: você pode banir este card do seu Cemitério; Invoque por Invocação-Especial 1 monstro Dragão de LUZ de Nível 7 da sua mão. \r\nVocê só pode usar cada efeito de "Cavalestrela Ciel" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27053506,'Barril Secreto','Cause 200 de dano ao seu oponente para cada card na mão dele e para cada card que ele controla.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27054370,'Pégaso Asas de Fogo','Um garanhão celestial que galopa pelos céus com asas ardentes.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27062594,'A Porta do Destino',replace(replace('Quando um monstro do oponente declarar um ataque direto: negue o ataque e, depois, Invoque este card por Invocação-Especial como um Monstro de Efeito (Demônio/LUZ/Nível 1/ATK 0/DEF 0).	\r\n(Este card ainda é considerado um Card de Armadilha.) \r\nDurante sua Fase de Apoio, enquanto este card for considerado como um monstro: você pode banir qualquer número de monstros "Utopia" com nomes diferentes do seu Cemitério; cause 500 de dano ao seu oponente para cada um desses monstros banidos e, se isso acontecer, este card ganha ATK igual ao dano que ele sofreu.','\r',char(13)),'\n',char(10)),'Invocação Especial','Dano de efeito','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27068117,'Regeneração de Sobreposição','Escolha 1 Monstro Xyz com a face para cima no campo; associe este card a ele como matéria.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27069566,'Fênix do Mundo Virtual - Fanfan',replace(replace('2+ monstros de Nível 6	\r\nUma vez por turno: você pode desassociar 2 matérias deste card e, depois, escolha 1 card com a face para cima que seu oponente controla e 1 card em qualquer Cemitério; bana-os. \r\nSe este card Invocado por Invocação-Xyz for destruído em batalha com um monstro atacante do oponente ou por um efeito de card do oponente enquanto estiver na Zona de Monstros do seu dono: você pode Invocar por Invocação-Especial do seu Deck 2 monstros "Mundo Virtual" com o mesmo Tipo e Atributo um do outro. \r\nVocê só pode usar este efeito de "Fênix do Mundo Virtual - Fanfan" uma vez por turno.','\r',char(13)),'\n',char(10)),'Banir','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27094595,'Cemitério e a Mão do Convite','Um cemitério que serve de fonte de poder para zumbis.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27096833,'Dragão Libertador Callibregado',replace(replace('3+ Monstros de Efeito	\r\nVocê só pode Invocar "Dragão Libertador Callibregado(s)" uma vez por turno.\r\nUma vez por turno, durante a Fase de Batalha (Efeito Rápido): você pode colocar 1 monstro que seu oponente controla em uma zona que este card aponta e ganhe controle dele. \r\nSeu oponente não pode ativar cards ou efeitos em resposta a ativação deste efeito.\r\nUma vez por Corrente, se este card está no seu Cemitério (Efeito Rápido): você pode escolher 1 monstro que você controla; destrua-o, e se fizer, Invoque este card por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Tome o controle','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27096834,'Dragão Libertador Callibregado',replace(replace('3+ Monstros de Efeito	\r\nVocê só pode Invocar "Dragão Libertador Callibregado(s)" uma vez por turno.\r\nUma vez por turno, durante a Fase de Batalha (Efeito Rápido): você pode colocar 1 monstro que seu oponente controla em uma zona que este card aponta e ganhe controle dele. \r\nSeu oponente não pode ativar cards ou efeitos em resposta a ativação deste efeito.\r\nUma vez por Corrente, se este card está no seu Cemitério (Efeito Rápido): você pode escolher 1 monstro que você controla; destrua-o, e se fizer, Invoque este card por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Tome o controle','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27103517,'Acólito Perverso Chilam Sabak',replace(replace('Se você tiver 5 ou mais cards na sua mão, você pode Invocar este card por Invocação-Normal sem oferecer Tributo. \r\nQuando este card for destruído em batalha e enviado para o Cemitério: você pode Invocar este card por Invocação-Especial em Posição de Defesa e, se isso acontecer, ele é considerado um Regulador. \r\nVocê só pode usar este efeito de "Acólito Perverso Chilam Sabak" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Normal sem Tributo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27104921,'Forje um Novo Futuro',replace(replace('Uma vez por Corrente, se um monstro de Link-4 for Invocado por Invocação-Link: você pode colocar 1 marcador neste card (máx. 3) e, depois, você pode aplicar o seguinte efeito de acordo com o número de marcadores nele.\r\n● 1: Declare 1 nome de card e, se isso acontecer, os efeitos ativados e efeitos no campo de cards com esse nome original são negados neste turno.\r\n● 2: Invoque por Invocação-Especial 1 monstro de Nível 4 ou menos do seu Cemitério.\r\n● 3: Envie este card para o Cemitério e, se isso acontecer, Invoque por Invocação-Especial 1 monstro de Link-4 do seu Deck Adicional.	\r\nVocê só pode ativar 1 "Forje um Novo Futuro" por turno.','\r',char(13)),'\n',char(10)),'Declarar o nome de um card para negá-la?','Invocar por Invocação Especial do Cemitério?','Invocar por Invocação Especial do Deck Adicional?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27107590,'Donzela do Tempo',replace(replace('Se você não controlar nenhum monstro, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nEste card pode ser considerado como 2 Tributos para a Invocação-Tributo de um monstro "Senhor do Tempo". \r\nVocê pode oferecer este card como Tributo; adicione 1 monstro "Senhor do Tempo" com 0 de ATK do seu Deck à sua mão. \r\nVocê pode banir este card do seu Cemitério; Invoque por Invocação-Especial 1 monstro "Senhor do Tempo" com 0 de ATK do seu Deck, ignorando suas condições de Invocação. \r\nDurante o turno em que ativar este efeito, você não pode Invocar nenhum outro monstro por Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27118421,'Dragão Fusão de Peçonha Insaciável, os Quatro Dragões Celestiais',replace(replace('2 monstros de TREVAS no campo	\r\n(Este card deve ser sempre considerado como um card "Predaplanta".)	\r\nSe este card for Invocado por Invocação-Especial: você pode escolher 1 outro monstro com a face para cima no campo; mude o ATK dele para 0, negue seus efeitos e, além disso, ele se torna de TREVAS. \r\nQuando seu oponente ativar um card ou efeito (Efeito Rápido): você pode Invocar por Invocação-Fusão 1 Monstro de Fusão de TREVAS do seu Deck Adicional usando monstros de TREVAS em qualquer campo, incluindo este card. \r\nVocê só pode usar cada efeito de "Dragão Fusão de Peçonha Insaciável, os Quatro Dragões Celestiais" uma vez por turno.','\r',char(13)),'\n',char(10)),'Negar o efeito','Invocação Fusão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27118422,'Dragão Fusão de Peçonha Insaciável, os Quatro Dragões Celestiais',replace(replace('2 monstros de TREVAS no campo	\r\n(Este card deve ser sempre considerado como um card "Predaplanta".)	\r\nSe este card for Invocado por Invocação-Especial: você pode escolher 1 outro monstro com a face para cima no campo; mude o ATK dele para 0, negue seus efeitos e, além disso, ele se torna de TREVAS. \r\nQuando seu oponente ativar um card ou efeito (Efeito Rápido): você pode Invocar por Invocação-Fusão 1 Monstro de Fusão de TREVAS do seu Deck Adicional usando monstros de TREVAS em qualquer campo, incluindo este card. \r\nVocê só pode usar cada efeito de "Dragão Fusão de Peçonha Insaciável, os Quatro Dragões Celestiais" uma vez por turno.','\r',char(13)),'\n',char(10)),'Negar o efeito','Invocação Fusão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27125110,'Ídolo dos Mil Olhos','Uma entidade perversa que controla os corações dos homens. Seus mil olhos são capazes de ver e expandir a influência negativa na alma de um indivíduo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27126980,'Cavaleiro-Gema Safira','Seus poderes de Safira comandam as águas para protegê-lo de ataques. Seus companheiros confiam em sua proteção silenciosa.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27132350,'Feiticeira do Fogo','VIRE: Bana 2 cards aleatórios da sua mão; cause 800 de dano ao seu oponente.','Causar dano aos PV','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27132400,'Malwisp Altergeist',replace(replace('Se este card for adicionado à sua mão, exceto ao comprá-lo: você pode Invocá-lo por Invocação-Especial. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 monstro "Altergeist" no seu Cemitério, exceto "Malwisp Altergeist"; Invoque-o por Invocação-Especial em Posição de Defesa, mas pelo resto deste turno, ele não pode ativar seus efeitos. \r\nVocê só pode usar cada efeito de "Malwisp Altergeist" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','O efeito de "Malwisp Altergeist" está sendo aplicado.','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27134209,'Beargram, Imperador Concha da Coroa da Floresta',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão ou do Cemitério) ao banir 3 monstros Inseto e/ou Planta da sua mão e/ou do Cemitério. \r\nVocê só pode Invocar "Beargram, Imperador Concha da Coroa da Floresta" por Invocação-Especial uma vez por turno. \r\nSeu oponente não pode ativar efeitos de monstro em resposta à ativação do seu Card de Magia/Armadilha ou seu efeito. \r\nUma vez por turno, durante sua Fase Principal: você pode destruir todos os monstros com a face para cima no campo, exceto monstros Inseto e Planta e, além disso, este card não pode atacar diretamente pelo resto deste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27134689,'Mestre de Oz','"Grande Coala" + "Canguru Des"','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27143874,'Dino de Costura',replace(replace('Não pode ser destruído em batalha. \r\nSe este card for escolhido como alvo de um ataque: este card ganha 1000 de ATK e DEF. \r\nSe este card atacou, depois do cálculo de dano: o ATK e DEF ganhos por este efeito voltam a 0.','\r',char(13)),'\n',char(10)),'Ativar o efeito de "Dino de Costura"?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27157727,'Bastião, a Fortaleza Oculta',replace(replace('Invoque este card por Invocação-Especial como um Monstro de Efeito (Máquina/TERRA/Nível 4/ATK 0/DEF 2000) com os seguintes efeitos (este card ainda é considerado uma Armadilha).\r\n● Ganha 1000 de ATK para cada "Sarcófago Brilhante", e monstros que o mencionem, que você controla.\r\n● Uma vez por turno, quando um monstro do oponente declarar um ataque, enquanto você controlar "Sarcófago Brilhante": você pode destruir esse monstro.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27157996,'Conversão Utensilhor',replace(replace('Bana tantos Monstros Link "Utensilhor" da sua Zona de Monstros Principal quanto possível e, depois, você pode Invocar por Invocação-Especial seus Monstros Link "Utensilhor" banidos até o número banido por este efeito. \r\nDurante sua Fase Principal, se este card estiver no seu Cemitério, exceto no turno em que foi enviado para lá: você pode banir 1 outra Magia/Armadilha "Utensilhor" do seu Cemitério; adicione este card à sua mão. \r\nVocê só pode usar cada efeito de "Conversão Utensilhor" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Escolher um monstro para Invocá-lo por Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27170599,'Fantardil ou Travessura',replace(replace('Se você controlar uma Magia de Campo "Fantardil" ou um Monstro Link "Fantardil": você pode escolher 1 monstro com a face para cima que seu oponente controla; seu oponente pode pagar 2000 PV para fazer com que o efeito deste card se torne "depois da ativação, Baixe este card em vez de enviá-lo para o Cemitério", caso contrário, pelo resto deste turno, esse monstro com a face para cima não pode atacar, seus efeitos são negados e, além disso, ele é colocado com a face para baixo em Posição de Defesa durante a Fase Final. \r\nVocê só pode ativar 1 "Fantardil ou Travessura" por turno.','\r',char(13)),'\n',char(10)),'Pagar PV?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27174286,'Retorno de uma Outra Dimensão',replace(replace('Pague metade dos seus PV; Invoque por Invocação-Especial tantos dos seus monstros banidos quanto possível. \r\nDurante a Fase Final, bana todos os monstros que foram Invocados por Invocação-Especial por este efeito.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27178262,'Astúcia dos Seis Samurai','Envie 1 monstro "Seis Samurai" com a face para cima que você controla para o Cemitério e, depois, escolha 1 monstro "Seis Samurai" no Cemitério de qualquer duelista; Invoque o alvo por Invocação-Especial.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27182739,'Mechamático Sigma',replace(replace('Se você não controlar nenhum monstro na Zona de Monstros Adicional, enquanto este card estiver na sua mão ou no Cemitério: você pode Invocar este card por Invocação-Especial, mas bana-o quando ele deixar o campo e, além disso, você não pode Invocar monstros por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto monstros Ciberso. \r\nVocê só pode usar este efeito de "Mechamático Sigma" uma vez por turno. \r\nSe este card que você controla for usado como Matéria Sincro para um monstro "Mechamático(a)", você pode considerá-lo como um não-Regulador.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27184601,'Diactorus de Artmage',replace(replace('"Medius, o Puro" + 1 monstro "Artmage"	\r\nVocê pode escolher 1 monstro no campo; mude sua posição de batalha. \r\nQuando seu oponente ativar um card ou efeito no campo, se você tiver 3 ou mais Tipos de Monstro diferentes no seu campo (Efeito Rápido): você pode negar a ativação e, se isso acontecer, destrua esse card. \r\nSe este card Invocado por Invocação-Fusão for destruído: você pode Invocar por Invocação-Especial 1 "Medius, o Puro" da sua mão, do Deck ou do banimento. \r\nVocê só pode usar cada efeito de "Diactorus de Artmage" uma vez por turno.','\r',char(13)),'\n',char(10)),'Mudar a posição de batalha','Negar','Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27189308,'Piupiupiu','VIRE: Você pode Invocar por Invocação-Especial 1 monstro Regulador de Nível 5 ou mais do seu Deck.','Invocar por Invocação Especial 1 Regulador de Nível 5 ou mais do seu Deck?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27191436,'Retorno Explosivo','Se você controlar "Burstinatrix, o HERÓI do Elemento" com a face para cima: Devolva todos os monstros "HERÓI do Elemento" com a face para cima no campo à mão, exceto "Burstinatrix, o HERÓI do Elemento".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27196937,'Lampejo de Poeira Estelar','Escolha 1 monstro "Poeira Estelar" no seu Cemitério; Invoque-o por Invocação-Especial.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27198001,'Raposa de Nove Caudas',replace(replace('Se este card estiver na sua mão ou no Cemitério: você pode oferecer 2 monstros como Tributo; Invoque este card por Invocação-Especial. \r\nVocê só pode usar este efeito de "Raposa de Nove Caudas" uma vez por turno. \r\nSe este card que foi Invocado por Invocação-Especial do Cemitério atacar um monstro em Posição de Defesa, cause dano de batalha perfurante. \r\nSe este card for destruído em batalha ou por um efeito de card e enviado para o Cemitério: você pode Invocar por Invocação-Especial 2 "Ficha de Raposa" (Zumbi/FOGO/Nível 2/ATK 500/DEF 500).','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27198002,'Ficha de Raposa','Invocada por Invocação-Especial com o efeito "Raposa de Nove Caudas".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27204311,'Nibiru, o Ser Primitivo',replace(replace('Durante a Fase Principal, se seu oponente Invocou 5 ou mais monstros por Invocação-Normal ou Especial neste turno (Efeito Rápido): você pode oferecer como Tributo tantos monstros com a face para cima no campo quanto possível e, se isso acontecer, Invoque este card por Invocação-Especial da sua mão e, depois, Invoque por Invocação-Especial 1 "Ficha de Ser Primitivo" (Rocha/LUZ/Nível 11/ATK ?/DEF ?) no campo do seu oponente (o ATK/DEF dessa Ficha se tornam os ATK/DEF originais combinados dos monstros oferecidos como Tributo). \r\nVocê só pode usar este efeito de "Nibiru, o Ser Primitivo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27204312,'Ficha de Ser Primitivo','Invocada por Invocação-Especial com o efeito "Nibiru, o Ser Primitivo". Quando Invocada, ATK/DEF desta Ficha ficam iguais à soma dos ATK/DEF originais dos monstros oferecidos como Tributo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27204313,'Nibiru, o Ser Primitivo',replace(replace('Durante a Fase Principal, se seu oponente Invocou 5 ou mais monstros por Invocação-Normal ou Especial neste turno (Efeito Rápido): você pode oferecer como Tributo tantos monstros com a face para cima no campo quanto possível e, se isso acontecer, Invoque este card por Invocação-Especial da sua mão e, depois, Invoque por Invocação-Especial 1 "Ficha de Ser Primitivo" (Rocha/LUZ/Nível 11/ATK ?/DEF ?) no campo do seu oponente (o ATK/DEF dessa Ficha se tornam os ATK/DEF originais combinados dos monstros oferecidos como Tributo). \r\nVocê só pode usar este efeito de "Nibiru, o Ser Primitivo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27204314,'Nibiru, o Ser Primitivo',replace(replace('Durante a Fase Principal, se seu oponente Invocou 5 ou mais monstros por Invocação-Normal ou Especial neste turno (Efeito Rápido): você pode oferecer como Tributo tantos monstros com a face para cima no campo quanto possível e, se isso acontecer, Invoque este card por Invocação-Especial da sua mão e, depois, Invoque por Invocação-Especial 1 "Ficha de Ser Primitivo" (Rocha/LUZ/Nível 11/ATK ?/DEF ?) no campo do seu oponente (o ATK/DEF dessa Ficha se tornam os ATK/DEF originais combinados dos monstros oferecidos como Tributo). \r\nVocê só pode usar este efeito de "Nibiru, o Ser Primitivo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27207573,'Ferramenta de Infestação','Envie 1 monstro "Hordeum Ferro" do seu Deck ao Cemitério para escolher 1 monstro "Hordeum Ferro" com a face para cima que você controla; ele ganha 800 de ATK até a Fase Final.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27217742,'Manotrovão','Quando este card for Invocado por Invocação-Normal: você pode adicionar 1 monstro de LUZ do Tipo Trovão de Nível 4 do seu Deck à sua mão, exceto "Manotrovão".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27240101,'Kikinagashi Fucho',replace(replace('2 monstros de Nível 1	\r\nNão é afetado por outros efeitos de cards. \r\nUma vez por turno (Efeito Rápido): você pode desassociar 2 matérias deste card; pelo resto deste turno, este card não pode ser destruído em batalha e, além disso, você não sofre dano de batalha dos ataques envolvendo este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27243130,'Lança Proibida','Escolha 1 monstro com a face para cima no campo; até o final deste turno, o alvo perde 800 de ATK, mas não é afetado pelos efeitos de outras Magias/Armadilhas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27260347,'Diabellstar Olho de Cobra',replace(replace('Quando um ataque for declarado envolvendo este card e um monstro do oponente: você pode colocar este card do campo e esse monstro do oponente com a face para cima nas Zonas de Magias & Armadilhas dos seus donos como Magias Contínuas. \r\nEnquanto este card for uma Magia Contínua: você pode escolher 1 monstro de FOGO no seu Cemitério, exceto "Diabellstar Olho de Cobra"; coloque-o com a face para cima na Zona de Magias & Armadilhas do seu dono como uma Magia Contínua e, se isso acontecer, Invoque este card por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Diabellstar Olho de Cobra" uma vez por turno.','\r',char(13)),'\n',char(10)),'Colocar na Zona de Magias & Armadilhas','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27268998,'Metalzoa X',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro deve ser Invocado por Invocação-Especial com "Metalmorfe Máximo" que foi ativado ao oferecer como Tributo um monstro Demônio de Nível 5 ou mais. \r\nVocê pode revelar este card na sua mão; Baixe 1 Armadilha "Metalmorfe" do seu Deck e, se isso acontecer, embaralhe este card no Deck. \r\nVocê só pode usar este efeito de "Metalzoa X" uma vez por turno. \r\nDuas vezes por turno, quando seu oponente ativar um efeito de monstro, ou um Card de Magia ou seus efeitos (Efeito Rápido): você pode escolher 1 monstro com a face para cima que seu oponente controla; destrua-o.','\r',char(13)),'\n',char(10)),'Baixar o Card Armadilha "Metalmorfe"','Efeito de destruição','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27275398,'Orgulho Dourado - Pisa Fundo!',replace(replace('Escolha 1 monstro "Orgulho Dourado" que você controla; até o final deste turno, ele ganha 500 de ATK, ele não pode ser destruído em batalha ou por efeitos de card e ele não pode ativar seus efeitos. \r\nDurante a Fase Final, se um ou mais monstros "Orgulho Dourado" com a face para cima que você controla foram destruídos em batalha ou por um efeito de card neste turno: você pode Baixar este card do seu Cemitério. \r\nVocê só pode usar este efeito de "Orgulho Dourado - Pisa Fundo!" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27279764,'Torres Apoqliphort',replace(replace('Não pode ser Invocado por Invocação-Especial. \r\nRequer 3 Tributos "Qli" para ser Invocado por Invocação-Normal/Baixado. \r\nSe este card for Invocado por Invocação-Normal/Baixado, ele não é afetado por efeitos de Magia/Armadilha nem por efeitos ativados de monstros cujo Nível/Classe original seja menor que o Nível atual deste card. \r\nTodos os monstros Invocados por Invocação-Especial perdem 500 de ATK e DEF. \r\nUma vez por turno: você pode fazer com que seu oponente envie 1 monstro da mão dele ou do lado do campo dele para o Cemitério (à escolha dele).','\r',char(13)),'\n',char(10)),'Ofereça 3 monstros "Qli" como Tributo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27285068,'Teorealizar Liberação',replace(replace('Se você controlar "Medius, o Puro": adicione à sua mão ou Invoque por Invocação-Especial 1 monstro com 300 ATK/200 DEF do seu Deck. \r\nDurante sua Fase Principal: você pode banir este card do seu Cemitério e, depois, escolha 1 monstro com a face para cima que você controla; ele é considerado como um Regulador neste turno. \r\nVocê só pode usar cada efeito de "Teorealizar Liberação" uma vez por turno.','\r',char(13)),'\n',char(10)),'Escolha 1 monstro do seu Deck','Tornar-se um Regulador','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27288416,'Mokey Mokey','Um anjo expulso. Ninguém sabe de todo o que ele está a pensar. Por vezes ele irrita-se e isso é terrível.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27308231,'Liberar Restrição K9-LC',replace(replace('Escolha 1 Monstro Xyz "K9" ou 1 Monstro Xyz de Classe 5 que você controla; Invoque por Invocação-Especial do seu Deck Adicional, 1 Monstro Xyz "K9" com um nome diferente, usando esse monstro que você controla (isso é considerado uma Invocação-Xyz, transfira as matérias dele para o monstro Invocado). \r\nNo final da Fase de Batalha, se um monstro "K9" seu batalhou neste turno: você pode Baixar este card do seu Cemitério. \r\nVocê só pode usar cada efeito de "Liberar Restrição K9-LC" uma vez por turno.','\r',char(13)),'\n',char(10)),'Xyz','Baixar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27315304,'Verme da Névoa',replace(replace('1 Regulador + 2+ não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro: escolha até 3 cards que seu oponente controla; devolva os alvos para a mão.','\r',char(13)),'\n',char(10)),'Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27324313,'Herói Oscillo #2','Uma criatura que eletroculta os seus adversários com raios de relâmpagos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27331568,'Máquina de Anjo Esplendorosa',replace(replace('Ofereça como Tributo 1 Monstro de Ritual "Ciber Anjo(a)" da sua mão ou do campo e, depois, escolha 1 monstro Fada de LUZ que você controla; até o final deste turno, ele ganha ATK/DEF igual ao Nível que o monstro tinha quando foi oferecido como Tributo x 200. \r\nNeste turno, se ele batalhar um monstro do oponente que foi Invocado por Invocação-Especial do Deck Adicional, os efeitos desse monstro do oponente são negados, apenas durante a Fase de Batalha. \r\nVocê só pode ativar 1 "Máquina de Anjo Esplendorosa" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27337596,'Dragão Hierático Rei de Atum',replace(replace('2 monstros Dragão de Nível 6	\r\nUma vez por turno: você pode desassociar 1 matéria deste card; Invoque por Invocação-Especial 1 monstro Dragão do seu Deck e torne seu ATK/DEF 0. \r\nEste card não pode atacar durante o turno em que você ativou este efeito.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27340877,'Análise de DNA',replace(replace('Selecione 1 monstro com a face para baixo que você controla. \r\nSeu oponente declara 2 Atributos. \r\nRevele o monstro selecionado. \r\nSe o Atributo dele for um dos Atributos declarados, seu oponente compra 2 cards. \r\nSe não for, você compra 2 cards.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27345070,'Alma Aniquiladora - Continue?',replace(replace('Pague 500 PV e, depois, escolha 1 monstro "Alma Aniquiladora" no seu Cemitério; adicione-o à sua mão ou Invoque-o por Invocação-Especial em Posição de Defesa. \r\nVocê só pode ativar 1 "Alma Aniquiladora - Continue?" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27346636,'Besta Gladiadora Heraklinos',replace(replace('"Besta Gladiadora Laquari" + 2 monstros "Besta Gladiadora"	\r\nPrimeiro deve ser Invocado por Invocação-Especial (do seu Deck Adicional) ao embaralhar os cards acima que você controla no Deck. \r\nQuando um Card de Magia/Armadilha for ativado (Efeito Rápido): você pode descartar 1 card; negue a ativação e, se isso acontecer, destrua-o. \r\nEste card deve estar com a face para cima no campo para ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Negar a ativação e destruí-la','Invocação Especial','Escolha 1 "Besta Gladiadora Laquari"','Escolha 2 monstros cujos nomes incluam "Besta Gladiadora"','','','','','','','','','','','','');
INSERT INTO texts VALUES(27352108,'Dragão Blindagem Chobham',replace(replace('Quando um monstro do oponente declarar um ataque direto: você pode Invocar este card por Invocação-Especial da sua mão em Posição de Ataque e, se isso acontecer, pelo resto deste turno, ele não pode ser destruído em batalha e o dano de batalha que você sofrer das batalhas envolvendo este card é diminuído pela metade. \r\nSe este card for enviado para o Cemitério como Matéria Link: você pode escolher 1 outro monstro de TREVAS no seu Cemitério; adicione-o à sua mão e, além disso, seu oponente pode adicionar 1 monstro do Cemitério dele à mão dele. \r\nVocê só pode usar este efeito de "Dragão Blindagem Chobham" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar 1 monstro do Cemitério à sua mão?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27354732,'Besta Mítica Rei Chacal',replace(replace('Escala de Pêndulo = 4\r\n[ Efeito de Pêndulo ]\r\nSe você não tiver nenhum card na sua outra Zona de Pêndulo: você pode destruir este card e, se isso acontecer, Invoque por Invocação-Especial 1 Monstro Pêndulo "Besta Mítica" com a face para cima no seu Deck Adicional, exceto "Besta Mítica Rei Chacal". \r\nVocê só pode usar este efeito de "Besta Mítica Rei Chacal" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSempre que um Card de Magia for ativado, coloque 2 Marcadores de Magia neste card quando essa Magia resolver. \r\nUma vez por turno, quando um oponente ativar um efeito de monstro (Efeito Rápido): você pode remover 2 Marcadores de Magia do seu campo; negue a ativação e, se isso acontecer, destrua esse card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27381364,'Elfa Spright',replace(replace('2 monstros, incluindo um monstro de Nível/Classe/Link 2	\r\nNão pode ser usado como Matéria Link no turno em que for Invocado por Invocação-Link. \r\nSeu oponente não pode escolher monstros para os quais este card apontar como alvo de efeitos de card. \r\nDurante a Fase Principal (Efeito Rápido): você pode escolher 1 monstro de Nível 2 no seu Cemitério, ou, se seu oponente controlar um monstro, em vez disso, você pode escolher 1 monstro de Classe/Link 2; Invoque-o por Invocação-Especial. \r\nVocê só pode usar este efeito de "Elfa Spright" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27383110,'Alvorada do Arauto',replace(replace('Este card é usado para a Invocação-Ritual de "Arauto da Perfeição". \r\nVocê também deve oferecer como Tributo monstros da sua mão ou campo cuja soma dos Níveis seja exatamente igual a 6. \r\nQuando "Arauto da Perfeição" for Invocado por Invocação-Ritual pelo efeito deste card: você pode banir este card do seu Cemitério e, depois, escolher 1 dos monstros no seu Cemitério que foi oferecido como Tributo para a Invocação-Ritual; devolva o alvo para a sua mão.','\r',char(13)),'\n',char(10)),'Retornar à mão 1 monstro oferecido como Tributo para uma Invocação Ritual','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27383719,'Força-S Lapcewell',replace(replace('Se este card for Invocado por Invocação-Especial: você pode escolher 1 monstro "Força-S" no seu Cemitério, exceto "Força-S Lapcewell"; Invoque-o por Invocação-Especial. \r\nVocê pode banir 1 card "Força-S" da sua mão; destrua todos os monstros do seu oponente nas mesmas colunas que seus monstros "Força-S". \r\nVocê só pode usar cada efeito de "Força-S Lapcewell" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27407330,'Grepher Raio-de-Luz',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) ao descartar 1 monstro de LUZ de Nível 5 ou mais. \r\nUma vez por turno: você pode descartar 1 monstro de LUZ; bana 1 monstro de LUZ do seu Deck.','\r',char(13)),'\n',char(10)),'Banir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27408609,'Homúnculo Dourado','Ganha 300 de ATK/DEF para cada um dos seus cards banidos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27412542,'Prisão da Abominação',replace(replace('Adicione 1 card "Desacorrentado(a)" do seu Deck à sua mão. \r\nSe este card Baixado for destruído por um efeito de card: você pode Invocar por Invocação-Especial 1 monstro "Desacorrentado(a)" do seu Deck. \r\nVocê só pode usar cada efeito de "Prisão da Abominação" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27415516,'Correnteza, Dragão Soberano das Gotas',replace(replace('Você pode descartar este card e 1 monstro Dragão ou de ÁGUA; Invoque por Invocação-Especial 1 "Maré, Dragão Soberano das Cachoeiras" do seu Deck, mas ele não pode atacar neste turno. \r\nVocê só pode usar este efeito de "Correnteza, Dragão Soberano das Gotas" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27416701,'Shiba, o Guerreiro Taro',replace(replace('Este card não pode ser destruído em batalha. \r\nQuando um card no campo for destruído em batalha ou por um efeito de card, devolva este card virado para cima para a mão de seu dono.','\r',char(13)),'\n',char(10)),'Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27420823,'"Estripadora" K9-17',replace(replace('2 monstros de Nível 5	\r\nVocê pode desassociar 1 matéria deste card; adicione 1 card "K9" do seu Deck à sua mão e, depois, se seu oponente tiver ativado um efeito de monstro neste turno, você pode Baixar 1 Magia Rápida "K9" do seu Deck ou Cemitério. \r\nQuando seu oponente ativar um efeito de monstro na mão ou no Cemitério (Efeito Rápido): você pode desassociar 1 matéria deste card; negue o efeito. \r\nVocê só pode usar cada efeito de ""Estripadora" K9-17" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Negar o efeito','Baixar um card?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27439792,'Besta da Invocação do Caos',replace(replace('Você pode oferecer este card como Tributo; Invoque por Invocação-Especial 1 "Uria, o Senhor das Chamas Cortantes", "Hamon, o Senhor do Trovão Impactante" ou "Raviel, o Senhor dos Fantasmas" da sua mão, ignorando suas condições de Invocação. \r\nVocê pode banir este card do seu Cemitério; adicione 1 "Paraíso Caído" do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "Besta da Invocação do Caos" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27450400,'Bússola Cósmica','Quando este card for Invocado por Invocação-Normal: você pode Invocar por Invocação-Especial um número de "Fichas de Bússola" (Máquina/TERRA/Nível 1/ATK 0/DEF 0) até o número de monstros que seu oponente controla.','Invocação Especial','Continuar Invocando "Ficha de Bússola" por Invocação Especial?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27450401,'Ficha de Bússola','Invocada por Invocação-Especial com o efeito "Bússola Cósmica".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27480536,'Tubarão de Armadura',replace(replace('(Este card deve ser sempre considerado como um card "Xyz de Armadura".)	\r\nVocê pode enviar 1 Monstro Xyz de ÁGUA do seu Deck Adicional para o Cemitério e, depois, escolha 1 monstro Peixe no seu Cemitério com o mesmo Nível que a Classe desse monstro; Invoque-o por Invocação-Especial. \r\nDurante o turno do seu oponente, se este card estiver no seu Cemitério (Efeito Rápido): você pode escolher 1 Monstro Xyz de ÁGUA que você controla; equipe este card a esse monstro como uma Magia de Equipamento que concede a ele 500 de ATK. \r\nVocê só pode usar cada efeito de "Tubarão de Armadura" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Efeito de Equipamento','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27483935,'Comandante do Mecanismo Antigo',replace(replace('Você pode enviar para o Cemitério 1 "Golem do Mecanismo Antigo" da sua mão, do Deck ou da Zona de Monstros com a face para cima; imediatamente depois que este efeito resolver, Invoque por Invocação-Normal 1 monstro "Mecanismo Antigo". \r\nSe você Invocar por Invocação-Normal ou Especial "Golem do Mecanismo Antigo" (exceto durante a Etapa de Dano): você pode Invocar por Invocação-Especial 1 "Golem do Mecanismo Antigo" da sua mão ou do Cemitério, ignorando suas condições de Invocação. \r\nVocê pode banir este card do seu Cemitério; coloque 1 Armadilha Contínua "Mecanismo Antigo" da sua mão, com a face para cima no seu campo. \r\nVocê só pode usar cada efeito de "Comandante do Mecanismo Antigo" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Normal','Invocação Especial','Baixar uma Armadilha Contínua','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27491571,'Bruxa Fantardil',replace(replace('Não pode ser Invocado por Invocação-Normal a não ser que você controle um monstro "Fantardil". \r\nUma vez por turno: você pode colocar este card com a face para baixo em Posição de Defesa. \r\nUma vez por turno: você pode escolher 1 monstro com a face para cima que seu oponente controla; coloque-o com a face para baixo em Posição de Defesa.','\r',char(13)),'\n',char(10)),'Mudar para Posição de Defesa com a face para baixo','Escolha 1 monstro que seu oponente controla; mude-o para Posição de Defesa com a face para baixo','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27503418,'Sincro do Rei',replace(replace('Quando um monstro do seu oponente declarar um ataque contra um Monstro Sincro que você controla: negue o ataque e, depois, você pode aplicar o resto dos efeitos deste card. \r\nBana esse Monstro Sincro que você controla e 1 Regulador do seu Cemitério e, se isso acontecer, Invoque por Invocação-Especial do seu Deck Adicional 1 Monstro Sincro cujo Nível seja igual à soma dos Níveis que os monstros banidos tinham. \r\n(Isso é considerado uma Invocação-Sincro.)','\r',char(13)),'\n',char(10)),'Invocar o Monstro Sincro por Invocação Especial?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27519978,'Quarteto Encantador Florescendo',replace(replace('2+ monstros	\r\nGanha 300 de ATK para cada Atributo diferente no campo. \r\nUma vez, enquanto este card estiver com a face para cima no campo, durante a Fase Principal (Efeito Rápido): você pode escolher 2 monstros no seu Cemitério com o mesmo Atributo, mas Tipos diferentes, ou com o mesmo Tipo, mas Atributos diferentes; Invoque os dois por Invocação-Especial e, além disso, até o final do próximo turno, este card e os monstros Invocados por Invocação-Especial não podem ser usados como matéria para uma Invocação-Fusão, Sincro, Xyz ou Link. \r\nVocê só pode usar este efeito de "Quarteto Encantador Florescendo" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','O efeito de "Quarteto Encantador Florescendo" está sendo aplicado.','Efeito já ativado','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27520594,'Gênio Loci de Solarsemente','Esta semente só pode ser colhida da árvore sagrada uma vez a cada mil anos e se tornará o espírito guardião de sua terra mil anos depois.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27527047,'Guardas Secretos da Barreira de Gelo','Seu oponente não pode escolher monstros "Barreira de Gelo" que você controla como alvo de efeitos de monstro.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27541267,'Infestação Pandêmica','Todos os monstros "Hordeum" com a face para cima que você controla atualmente não são afetados por outros efeitos de Magia/Armadilha neste turno.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27541563,'Protocolo Altergeist',replace(replace('A ativação e os efeitos dos cards "Altergeist" ativados no seu campo não podem ser negados. \r\nQuando seu oponente ativar um efeito de monstro: você pode enviar 1 outro card "Altergeist" com a face para cima que você controla para o Cemitério; negue a ativação e, se isso acontecer, destrua-o. \r\nVocê só pode usar este efeito de "Protocolo Altergeist" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar, sem aplicar o segundo efeito','Ativar e aplicar o segundo efeito','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27548199,'Dragão Selvagem Callibregado',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro: você pode equipar a este card 1 Monstro Link do seu Cemitério e, se isso acontecer, coloque Marcadores de Callibre neste card igual ao Valor Link desse Monstro Link. \r\nEste card ganha ATK igual à metade do ATK do monstro equipado a ele por seu efeito. \r\nQuando seu oponente ativar um card ou efeito (Efeito Rápido): você pode remover 1 Marcador de Callibre deste card; negue a ativação. \r\nVocê só pode usar este efeito de "Dragão Selvagem Callibregado" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27552504,'Beatriz, a Dama Eterna',replace(replace('2 monstros de Nível 6	\r\nVocê também pode Invocar este card por Invocação-Xyz ao enviar 1 monstro "Abismo Ardente" da sua mão para o Cemitério e, depois, use 1 monstro "Dante," que você controla como matéria. \r\n(Transfira as matérias dele para este card.) \r\nSe Invocado desta forma, o seguinte efeito não pode ser ativado neste turno. \r\nUma vez por turno (Efeito Rápido): você pode desassociar 1 matéria deste card; envie 1 card do seu Deck para o Cemitério. \r\nSe este card em sua posse for destruído por um card do seu oponente e enviado para o seu Cemitério: você pode Invocar por Invocação-Especial 1 monstro "Abismo Ardente" do seu Deck Adicional, ignorando suas condições de Invocação.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Xyz sobrepondo-o ao seu monstro "Dante"?','Enviar 1 card do Deck para o Cemitério','Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27553701,'Golpe Implacável - Megassalto','Um saqueador feroz que caça sob o manto da noite iluminada pela lua. Suas garras afiadas como lâminas cortam seus inimigos!','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27556460,'Grito Primita',replace(replace('Quando seu oponente Invocaria um ou mais monstros por Invocação-Normal ou Especial, enquanto você controlar um Monstro Normal ou um monstro "Primita" de Nível 5 ou mais, exceto uma Ficha: negue a Invocação e, se isso acontecer, bana esse(s) monstro(s). \r\nDurante sua Fase de Apoio, se você controlar um monstro "Primita": você pode Baixar este card do seu Cemitério, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar cada efeito de "Grito Primita" uma vez por turno.','\r',char(13)),'\n',char(10)),'Negar','Baixar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27561302,'Tela do Clima Chuvoso',replace(replace('Monstros de Efeito "do Clima" nas suas Zonas de Monstros Principais da coluna deste card e das colunas adjacentes a ela ganham este efeito.\r\n● Você pode banir este card e, depois, escolher 1 Magia/Armadilha que seu oponente controla (Efeito Rápido); devolva-o para a mão.	\r\nVocê só pode controlar 1 "Tela do Clima Chuvoso".','\r',char(13)),'\n',char(10)),'Retornar um Card de Magia/Armadilha à mão do seu dono (Tela do Clima Chuvoso)','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27564031,'Mundo Pernicioso','Durante sua Fase de Compra, em vez de conduzir sua compra normal: você pode revelar 3 cards "Pernicioso(a)" do seu Deck e, depois, seu oponente adiciona 1 deles aleatoriamente à sua mão e você embaralha o resto de volta no seu Deck.','Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27565379,'Vespabatalha - Azusa, o Arco Fantasma',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nQuando seu oponente sofrer dano de efeito de outro monstro "Vespabatalha": você pode causar dano ao seu oponente igual ao ATK original desse monstro. \r\nVocê só pode usar este efeito de "Vespabatalha - Azusa, o Arco Fantasma" uma vez por turno. \r\nQuando um monstro for destruído em batalha com um monstro "Vespabatalha" seu, enquanto este card estiver no seu Cemitério: você pode Invocar este card por Invocação-Especial em Posição de Defesa, mas bana-o quando ele deixar o campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27572350,'Bistial Dis Pater',replace(replace('1 Regulador + 1+ monstros Dragão não-Reguladores	\r\nVocê pode escolher 1 monstro de LUZ ou de TREVAS banido; Invoque-o por Invocação-Especial no seu campo. \r\nQuando seu oponente ativar um efeito de monstro (Efeito Rápido): você pode escolher 1 card banido; embaralhe-o no Deck e, depois, se você o embaralhou no seu Deck, destrua esse monstro, ou se você o embaralhou no Deck do seu oponente, negue esse efeito ativado. \r\nVocê só pode usar cada efeito de "Bistial Dis Pater" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar escolhendo como alvo um card que seu oponente baniu','Ativar escolhendo como alvo um card que você baniu','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27581098,'Área de Não Fusão','Nenhum duelista pode Invocar por Invocação-Fusão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27618634,'A Rapariga Infeliz','Enquanto este card permanecer no Campo em Posição de Ataque com a face para cima, este monstro não é destruído como resultado de um combate.Enquanto este card permanecer no Campo em Posição de Ataque com a face para cima, um monstro que combata com este card não pode mudar a sua posição de batalha ou atacar.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27623932,'Descarga Trovão',replace(replace('Se você controlar uma "Ficha de Aventura": você pode escolher 1 monstro que você controla equipado com um Card de Equipamento que mencione "Ficha de Aventura"; destrua tantos monstros que seu oponente controla quanto possível com ATK igual ou menor que o desse monstro e, depois, você pode equipar 1 Magia de Equipamento que mencione "Ficha de Aventura" da sua mão ou do Cemitério a 1 monstro que você controla. \r\nVocê só pode ativar 1 "Descarga Trovão" por turno.','\r',char(13)),'\n',char(10)),'Equipar uma Magia de Equipamento?','Escolha a Magia para equipar','Escolha o monstro a equipar','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27632240,'Cavaleiro da Altitude','Uma vez por turno, se outro monstro no campo for devolvido para a mão ou para o Deck Principal: envie 1 monstro de VENTO do seu Deck para o Cemitério.','Enviar para o Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27632520,'Cauda de Fadas - Brugata',replace(replace('2 monstros Mago de Nível 4	\r\nCada monstro "Cauda de Fadas" que você controla cujo Atributo original seja LUZ não é afetado pelos efeitos ativados do seu oponente. \r\nVocê só pode usar cada um dos seguintes efeitos de "Cauda de Fadas - Brugata" uma vez por turno. \r\nVocê pode desassociar até 2 matérias deste card; envie cards "Cauda de Fadas" do seu Deck para o Cemitério, igual ao número desassociado. \r\nSe este card estiver no seu Cemitério (Efeito Rápido): você pode escolher 1 monstro "Cauda de Fadas" que você controla cujo Atributo original seja LUZ; Invoque este card por Invocação-Especial e, se isso acontecer, envie esse monstro para o Cemitério.','\r',char(13)),'\n',char(10)),'Enviar para o Cemitério','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27642961,'MISSÃO ESPIRÃO - Ataque',replace(replace('Destrua este card durante sua 3ª Fase Final depois de sua ativação. \r\nUma vez por turno, se um monstro "ESPIRÃO" que você controla destruir um monstro em batalha ou se você destruir um ou mais cards no campo com o efeito de um monstro "ESPIRÃO" que você controla: você pode comprar 1 card. \r\nVocê pode banir este card do seu Cemitério; Invoque por Invocação-Especial 1 monstro "ESPIRÃO" da sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27655513,'Skreech','Se este card for destruído em batalha: envie 2 monstros de ÁGUA do seu Deck para o Cemitério.','Enviar para o Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27657173,'Dragão Meteoro Negro de Olhos Vermelhos',replace(replace('Você pode enviar para o Cemitério 1 Monstro Normal de Nível 5 ou mais da sua mão ou do Deck; Invoque este card por Invocação-Especial da sua mão e, depois, aumente seu Nível em 1. \r\nDurante sua Fase Principal, exceto no turno em que este card foi enviado para o Cemitério: você pode banir este card do seu Cemitério; adicione 1 "Fusão dos Olhos Vermelhos" do seu Deck ou Cemitério à sua mão. \r\nVocê só pode usar cada efeito de "Dragão Meteoro Negro de Olhos Vermelhos" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27660735,'Velocidaroide Dado de Três Olhos','Durante o turno do seu oponente: você pode banir este card do seu Cemitério; negue o próximo ataque neste turno de um monstro que seu oponente controla (este é um Efeito Rápido).','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27664101,'Recomeço Link','Quando um Card de Magia/Armadilha ou efeito de monstro for ativado que causaria dano a você: negue a ativação e, se isso acontecer, Invoque por Invocação-Especial 1 Monstro Link do seu Cemitério.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27671321,'Enguia Relâmpago','Esta enguia gigantesca gera cargas elétricas massivas e as libera em forma de raios.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27693363,'Ursártico Polari',replace(replace('Não pode ser Invocado por Invocação-Sincro. 	\r\nDeve ser Invocado por Invocação-Especial (do seu Deck Adicional) ao enviar 2 monstros que você controla com 1 Nível de diferença para o Cemitério (1 Regulador e 1 não-Regulador). \r\nSe este card for Invocado por Invocação-Especial: você pode ativar 1 "Grande Carro Ursártico" diretamente do seu Deck. \r\nVocê pode oferecer como Tributo 1 monstro de Nível 7 ou mais; adicione à sua mão, ou Invoque por Invocação-Especial, 1 monstro "Ursártico(a)" do seu Cemitério. \r\nVocê só pode usar cada efeito de "Ursártico Polari" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27699122,'Vira-Páginas Toon',replace(replace('Se você controlar "Mundo Toon": revele 3 monstros Toon com nomes diferentes do seu Deck, seu oponente elege 1 deles aleatoriamente para que você Invoque por Invocação-Especial, ignorando suas condições de Invocação e, além disso, embaralhe o resto no seu Deck. \r\nVocê só pode ativar 1 "Vira-Páginas Toon" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27704731,'Espadachim Metalchamas',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro deve ser Invocado por Invocação-Especial com "Metalmorfe Máximo" que foi ativado ao oferecer como Tributo um monstro Guerreiro de Nível 5 ou mais. \r\nVocê pode revelar este card na sua mão; adicione 1 card que mencione "Metalmorfe Máximo" do seu Deck à sua mão, exceto "Espadachim Metalchamas" e, se isso acontecer, embaralhe este card no Deck. \r\nVocê só pode usar este efeito de "Espadachim Metalchamas" uma vez por turno. \r\nSempre que seu oponente ativar um card ou efeito, este card ganha 300 de ATK e causa 500 de dano ao seu oponente quando esse card/efeito resolver.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Aumentar ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27705190,'Vínculo Mental do Legado Mundial',replace(replace('Quando um monstro do oponente ativar seu efeito enquanto você controlar um monstro "Krawler": o efeito ativado se torna "devolva 1 monstro com a face para cima que seu oponente controla para a mão". \r\nVocê pode banir este card do seu Cemitério e, depois, escolher 1 Monstro Link no campo; Invoque por Invocação-Especial 1 monstro "Krawler" da sua mão, do Deck ou do Cemitério em uma zona sua para a qual o alvo apontar, com a face para baixo em Posição de Defesa. \r\nVocê só pode usar 1 efeito de "Vínculo Mental do Legado Mundial" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27744077,'Fim Absoluto',replace(replace('Você pode activar este card apenas durante o turno do seu adversário. \r\nEste turno, todos os ataques dos monstros do seu adversário tornam-se ataques diretos ao jogador.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27750191,'Yokotuner','Quando este card for Invocado por Invocação-Normal: você pode Invocar por Invocação-Especial 1 Regulador da sua mão ou do Cemitério, mas ele tem seus efeitos negados.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27753563,'Uradora do Destino',replace(replace('Pague 1000 PV e, depois, escolha 1 monstro com a face para cima que você controla; ele ganha 1000 de ATK até o final do turno do seu oponente e, se isso acontecer, aplique este efeito até o final do turno do seu oponente.\r\n● Sempre que ele destruir um monstro do oponente em batalha: você pode revelar o card do fundo do seu Deck e colocá-lo no topo ou no fundo do Deck.	\r\nSe o card revelado era um monstro Dragão, Dinossauro, Serpente Marinha ou Wyrm, compre 1 card para cada 1000 de ATK desse monstro e, depois, ganhe 1000 PV para cada card comprado.','\r',char(13)),'\n',char(10)),'Revele o card do fundo do seu Deck para ambos os jogadores','Colocar no topo do Deck','Retornar ao fundo do Deck','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27755794,'Tufão Radiante Meghala',replace(replace('Se você tiver "Tufão Espacial Místico" no seu Cemitério, ou seu oponente não controlar nenhuma Magia/Armadilha, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Tufão Radiante Meghala" por Invocação-Especial uma vez por turno desta forma. \r\nSe um Card de Magia Rápida "Tufão Radiante" ou "Tufão Espacial Místico" for ativado (exceto durante a Etapa de Dano): você pode Invocar por Invocação-Especial 1 monstro "Tufão Radiante" do seu Deck com um nome diferente que o dos monstros que você controla e, além disso, você não pode Invocar por Invocação-Especial pelo resto deste turno, exceto monstros de VENTO. \r\nVocê só pode usar este efeito de "Tufão Radiante Meghala" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27756115,'Samurai Superpesado Colar das Almas',replace(replace('(Este card deve ser sempre considerado como um card "Samurai Superpesado Alma".)	\r\nVocê pode escolher 1 monstro "Samurai Superpesado" que você controla; equipe este monstro da sua mão ou do campo ao alvo. \r\nNa primeira vez que o monstro equipado com este card por este efeito seria destruído por um efeito de card a cada turno, ele não é destruído. \r\nQuando um monstro em Posição de Defesa for destruído em batalha e enviado para o seu Cemitério: você pode enviar este card da sua mão para o Cemitério; Invoque esse monstro por Invocação-Especial em Posição de Ataque.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27762803,'Escaravelho de Naturia','Sempre que um Card de Magia for ativado, troque o ATK e a DEF originais deste card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27769400,'Tualatin',replace(replace('Se for a Fase de Batalha de seu oponente, e todos os monstros que você controla no início desta Fase de Batalha (mín. 2) tiverem sido destruídos em batalha e enviados ao Cemitério: Você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe Invocado dessa forma: Escolha um Atributo e destrua todos os monstros com a face para cima com esse Atributo. \r\nO oponente não pode Invocar por Invocação-Normal ou Invocação-Especial monstros com esse Atributo.','\r',char(13)),'\n',char(10)),'Invocação Especial','Destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27770341,'Super Rejuvenescimento','Durante a Fase Final do turno em que este card foi ativado, compre um número de cards igual ao número combinado de monstros Dragão que você descartou ou ofereceu como Tributo da sua mão ou do campo neste turno.','Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27780618,'Vyon, o HERÓI da Visão',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode enviar 1 monstro "HERÓI" do seu Deck para o Cemitério. \r\nVocê só pode usar este efeito de "Vyon, o HERÓI da Visão" uma vez por turno. \r\nUma vez por turno: você pode banir 1 monstro "HERÓI" do seu Cemitério; adicione 1 "Polimerização" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Envie um monstro "HERÓI" para o Cemitério','Adicione "Polimerização/Fusão" à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27781371,'Nascimento Regênese',replace(replace('Você pode enviar 1 monstro "Regênese" do seu Deck para o Cemitério e, depois, escolha 1 monstro com a face para cima que seu oponente controla; coloque-o com a face para baixo em Posição de Defesa. \r\nDurante o turno do seu oponente: você pode enviar este card para o Cemitério; Invoque por Invocação-Especial tantos monstros "Regênese" quanto possível com nomes diferentes da sua mão, do Cemitério e/ou do banimento, mas envie-os para o Cemitério durante a Fase Final. \r\nVocê só pode usar 1 efeito de "Nascimento Regênese" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Mudar a posição de batalha','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27782503,'Os Seis Samurai - Irou',replace(replace('No começo da Etapa de Dano, se este card atacou um monstro com a face para baixo em Posição de Defesa: Destrua esse monstro. \r\nVocê deve controlar um monstro "Seis Samurai" com a face para cima com um nome diferente para ativar e resolver este efeito. \r\nSe este card seria destruído, em vez disso, você pode destruir outro monstro "Seis Samurai" com a face para cima que você controla.','\r',char(13)),'\n',char(10)),'Destruir o monstro atacado em Posição de Defesa com a face para baixo','Usar o efeito de substituição de destruição de "Os Seis Samurai - Irou"?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27784944,'Pintora do Clima Aurora',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode colocar 1 Magia/Armadilha "do Clima" da sua mão, do Deck ou do Cemitério com a face para cima na sua Zona de Magias & Armadilhas. \r\nSeu oponente não pode escolher Magias/Armadilhas "do Clima" que você controla como alvo de efeitos de card e, além disso, elas não podem ser destruídas pelos efeitos de card do seu oponente. \r\nUma vez por turno, durante a Fase de Apoio do turno seguinte ao qual este card foi banido do campo para ativar um efeito de card "do Clima": você pode Invocar este card banido por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Baixar um Card de Magia/Armadilha "do Clima"','Invoque este card banido por Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27796375,'Grande Feiticeiro de Necroz',replace(replace('Se este card for oferecido como Tributo por um efeito de card: você pode adicionar 1 Monstro de Ritual "Necroz" do Tipo Mago do seu Deck à sua mão. \r\nSe este card for banido: você pode enviar 1 monstro "Necroz" do seu Deck para o Cemitério, exceto "Grande Feiticeiro de Necroz". \r\nVocê só pode usar 1 efeito de "Grande Feiticeiro de Necroz" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Enviar para o Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27813661,'Íris do Céu',replace(replace('Seu oponente não pode escolher cards "Mago", "Camarartista" ou "Olhos Anômalos" nas suas Zonas de Pêndulo como alvo de efeitos de card. \r\nVocê pode escolher 1 outro card com a face para cima que você controla; destrua-o e, se isso acontecer, adicione 1 card "Olhos Anômalos" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Íris do Céu" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27821104,'Ascetismo dos Seis Samurai','Escolha 1 monstro "Seis Samurai" que você controla; Invoque por Invocação-Especial 1 monstro "Seis Samurai" do seu Deck com o mesmo ATK mas um nome diferente e, se isso acontecer, destrua-o durante a Fase Final deste turno.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27822206,'Era das Estrelas e Geadas',replace(replace('Se um ou mais monstros que você controla foram destruídos por um efeito de Magia seu ou por um efeito de card do seu oponente e foram enviados para o Cemitério neste turno: você pode conduzir sua próxima Fase de Batalha duas vezes. \r\nSe um monstro que você controla for embaralhado no Deck ou devolvido para o Deck Adicional, com a face para baixo, enquanto este card estiver no seu Cemitério: você pode adicionar este card à sua mão. \r\nVocê só pode usar este efeito de "Era das Estrelas e Geadas" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27827272,'Brumas Mágicas de Makiu',replace(replace('Escolha 1 "Caveira Invocada" ou 1 monstro Trovão na sua Zona de Monstros; destrua todos os monstros que seu oponente controla com DEF menor ou igual ao ATK desse monstro. \r\nVocê não pode conduzir sua Fase de Batalha no turno em que ativar este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27827903,'Esmagador Aliado Genex','Uma vez por turno, quando um monstro com o mesmo Atributo deste card for Invocado por Invocação-Normal no seu lado do campo, você pode selecionar 1 card que seu oponente controla e destruí-lo.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27863269,'Foguete Pilder',replace(replace('Enquanto o monstro equipado estiver atacando, ele não pode ser destruído em batalha. \r\nNo final da Etapa de Dano, se o monstro equipado atacou: até a Fase Final, o alvo do ataque perde ATK igual ao ATK do monstro equipado.','\r',char(13)),'\n',char(10)),'Reduzir ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27868563,'Motoqueiro Goblin Boom Mach','Uma vez por Corrente, durante a Fase Principal, se este card estiver na sua mão ou no Cemitério (Efeito Rápido): você pode desassociar 1 Matéria Xyz de um monstro em qualquer campo e, se isso acontecer, Invoque este card por Invocação-Especial e, além disso, você não pode Invocar "Motoqueiro Goblin Boom Mach" por Invocação-Especial até o final do próximo turno.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27869883,'Sacerdotisa da Sombra de Ohm','Você pode oferecer como Tributo 1 monstro de TREVAS com a face para cima que você controla para causar 800 de dano ao seu oponente.','Receba 800 pontos de dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27870033,'Perseguidor','Quando um monstro em Posição de Defesa for destruído em batalha e enviado ao Cemitério, cause 500 de dano ao seu oponente.','Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27870337,'Elegância Solfacorde',replace(replace('Ative 1 desses efeitos;\r\n● Coloque 1 Monstro Pêndulo "Solfacorde" do seu Deck na sua Zona de Pêndulo.\r\n● Adicione 1 Monstro Pêndulo "Solfacorde" da sua mão ao seu Deck Adicional com a face para cima e, depois, coloque 2 Monstros Pêndulo "Solfacorde", 1 de Escala de Pêndulo ímpar e 1 de Escala de Pêndulo par, do seu Deck nas suas Zonas de Pêndulo.\r\n● Adicione 2 cards, 1 de Escala de Pêndulo ímpar e 1 de Escala de Pêndulo par, das suas Zonas de Pêndulo ao Deck Adicional com a face para cima e, se isso acontecer, compre 2 cards.	\r\nVocê só pode ativar 1 "Elegância Solfacorde" por turno.','\r',char(13)),'\n',char(10)),'Coloque 1 Monstro Pêndulo','Coloque 2 Monstros Pêndulo','Compre 2 card(s)','Escolha 1 card para adicionar ao Deck Adicional','','','','','','','','','','','','');
INSERT INTO texts VALUES(27873305,'D/D/D César Ragnarok, o Rei Esquecido das Ondas',replace(replace('2 monstros "D/D/D"	\r\nUma vez por turno, quando um ataque for declarado envolvendo este card: você pode escolher 1 outro card "D/D" ou "Pacto Obscuro" que você controla; devolva-o para a mão e, se isso acontecer, equipe 1 monstro com a face para cima que seu oponente controla a este card, exceto o monstro que está batalhando. \r\nEste card ganha ATK igual ao ATK original combinado dos monstros equipados a ele por este efeito.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27877771,'Dragão Farejador',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 "Dragão Farejador" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Dragão Farejador" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27882993,'Salmão Rainha Infernal',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode Invocar por Invocação-Especial 1 Monstro Normal Peixe da sua mão, do Deck ou do Cemitério. \r\nSe este card for destruído em batalha, ou se este card em posse do seu dono for destruído por um efeito de card do oponente: você pode Invocar por Invocação-Especial qualquer número de "Ficha de Salmão Peão Vil" (Peixe/ÁGUA/Nível 1/ATK 0/DEF 0). \r\nVocê só pode usar cada efeito de "Salmão Rainha Infernal" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Invocar outro monstro por Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27882994,'Ficha de Salmão Peão Vil','Invocado por Especial com o efeito "Salmão Rainha Infernal".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27895597,'Chamado da Senhora Fortuna',replace(replace('Se você controlar um monstro "Senhora Fortuna": Invoque por Invocação-Especial 1 monstro "Senhora Fortuna" do seu Deck com um nome diferente que o dos cards que você controla e, além disso, pelo resto deste turno despois que este card resolver, você não pode Invocar monstros do Deck Adicional por Invocação-Especial, exceto Monstros Sincro. \r\nVocê só pode ativar 1 "Chamado da Senhora Fortuna" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27911549,'Parasita Paracide',replace(replace('VIRE: Embaralhe este card com a face para cima no Deck do seu oponente.\r\nSe você comprar este card depois que ele foi adicionado ao seu Deck pelo seu efeito: Invoque-o por Invocação-Especial em Posição de Defesa e, se isso acontecer, sofra 1000 de dano. \r\nTodos os monstros controlados pelo duelista que Invocou este card pelo seu efeito se tornam monstros Insetos.','\r',char(13)),'\n',char(10)),'Embaralhe no Deck do seu oponente','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27911550,'Parasita Paracide',replace(replace('VIRE: Embaralhe este card com a face para cima no Deck do seu oponente.\r\nSe você comprar este card depois que ele foi adicionado ao seu Deck pelo seu efeito: Invoque-o por Invocação-Especial em Posição de Defesa e, se isso acontecer, sofra 1000 de dano. \r\nTodos os monstros controlados pelo duelista que Invocou este card pelo seu efeito se tornam monstros Insetos.','\r',char(13)),'\n',char(10)),'Embaralhe no Deck do seu oponente','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27918365,'Legado Mundial - "Coroa Mundial"',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) em Posição de Defesa em uma zona sua para a qual um Monstro Link apontar. \r\nVocê só pode Invocar "Legado Mundial - "Coroa Mundial"" por Invocação-Especial uma vez por turno desta forma. \r\nQuando um monstro no campo que foi Invocado por Invocação-Especial do Deck Adicional ativar seu efeito (Efeito Rápido): você pode oferecer este card como Tributo; negue a ativação e, se isso acontecer, destrua-o. \r\nSe este card Invocado por Invocação-Normal/Baixado for oferecido como Tributo: você pode adicionar 1 Magia/Armadilha "Legado Mundial" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Legado Mundial - "Coroa Mundial"" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27918963,'Campo de Treinamento Yosen',replace(replace('Sempre que um ou mais monstros "Yosenju" forem Invocados por Invocação-Normal ou Especial, coloque 1 Marcador Yosen neste card. \r\nVocê pode remover qualquer número de Marcadores Yosen deste card; aplique este efeito, dependendo do número de Marcadores Yosen removidos. \r\nVocê só pode usar este efeito de "Campo de Treinamento Yosen" uma vez por turno.\r\n● 1 Marcador: Todos os monstros "Yosenju" que você controla atualmente ganham 300 de ATK até o final deste turno (mesmo que este card deixe o campo).\r\n● 3 Marcadores: Adicione 1 card "Yosenju" do seu Deck ou Cemitério à sua mão.','\r',char(13)),'\n',char(10)),'Remova Marcadores','Aumentar ATK','Adicionar à mão','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27923575,'Jogo Perigoso',replace(replace('Durante o cálculo de dano, se um monstro batalhar: você não sofre dano de batalha dessa batalha. \r\nSe este card Baixado sob o controle do seu dono for destruído por um efeito de card do seu oponente e enviado para o Cemitério: você pode escolher até 2 Armadilhas Normais no seu Cemitério, exceto "Jogo Perigoso"; Baixe-as no seu campo. \r\nElas podem ser ativadas neste turno. \r\nVocê só pode usar este efeito de "Jogo Perigoso" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Ativar aplicando o efeito de "Jogo Perigoso".','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27927359,'Lady Harpia 2',replace(replace('(Este card deve ser sempre considerado como "Lady Harpia".)	\r\nNegue os efeitos dos monstros de Virar que este card destruir em batalha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27944249,'Windaar, Sábio de Gusto','Quando este card destruir um monstro em batalha e enviá-lo para o Cemitério: Você pode escolher 1 monstro "Gusto" de Nível 3 ou menos no seu Cemitério; Invoque por Invocação-Especial esse alvo com a face para cima em Posição de Defesa.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27946124,'Santuário de Solarvinhas',replace(replace('Ative este card ao enviar 1 card da sua mão para o Cemitério enquanto você controlar um Monstro Link "Solaravalon". \r\nVocê não pode Invocar monstros do Deck Adicional por Invocação-Especial, exceto monstros Planta. \r\nUma vez por turno, durante sua Fase Principal: você pode Invocar por Invocação-Especial 1 Monstro Normal Planta de Nível 4 ou menos do seu Cemitério. \r\nUma vez por turno, durante a Fase Final do seu oponente: você pode enviar este card com a face para cima para o Cemitério e, depois, escolha 1 Armadilha Contínua no seu Cemitério; Baixe-a na sua Zona de Magias & Armadilhas.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27967615,'Arma de Fusão',replace(replace('Só pode ser equipado a um Monstro de Fusão de Nível 6 ou menos. \r\nEle ganha 1500 de ATK/DEF.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27970830,'Portal dos Seis',replace(replace('Sempre que um ou mais monstros "Seis Samurai" forem Invocados por Invocação-Normal ou Especial, coloque 2 Marcadores de Bushido neste card. \r\nVocê pode remover Marcadores de Bushido do seu campo e, depois, ative 1 desses efeitos;\r\n● 2 Marcadores: Escolha 1 Monstro de Efeito "Seis Samurai" ou "Shien"; o alvo ganha 500 de ATK até o final deste turno.\r\n● 4 Marcadores: Adicione 1 monstro "Seis Samurai" do seu Deck ou Cemitério à sua mão.\r\n● 6 Marcadores: Escolha 1 Monstro de Efeito "Shien" no seu Cemitério; Invoque o alvo por Invocação-Especial.','\r',char(13)),'\n',char(10)),'2 Marcadores: escolha 1 "Portal dos Seis" ou monstro de Efeito "Portal dos Seis"; esse alvo escolhido ganha 500 de ATK até o final deste turno.','4 Marcadores: Adicione 1 monstro "Portal dos Seis" do seu Deck ou Cemitério para a sua mão.','6 Marcadores: escolha 1 "Portal dos Seis" monstro de Efeito no seu Cemitério; Invoque por Invocação-Especial aquele alvo escolhido.','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27971137,'Zumbibuaaaa',replace(replace('Quando este card declarar um ataque, ele ganha 500 de ATK. \r\nSe este card, no campo, for destruído e enviado para o Cemitério: você pode Invocar por Invocação-Especial do seu Deck 1 monstro de Nível 1 com ATK e DEF 0. \r\nSeus efeitos são negados e, além disso, ele é destruído durante sua próxima Fase Final.','\r',char(13)),'\n',char(10)),'Aumentar ATK','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27978707,'Samurai Superpesado Flautista',replace(replace('Você pode oferecer este card como Tributo; Invoque por Invocação-Especial 1 monstro "Samurai Superpesado" da sua mão. \r\nDurante o turno de qualquer duelista, quando um card ou efeito for ativado que escolheria como alvo um monstro "Samurai Superpesado" que você controla: você pode banir este card do seu Cemitério; negue a ativação e, se isso acontecer, destrua esse card. \r\nVocê só pode usar cada efeito de "Samurai Superpesado Flautista" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Negar a ativação e destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27979109,'Gerar Equipamento',replace(replace('Durante sua Fase de Compra, em vez de conduzir sua compra normal: você pode adicionar 1 Magia de Equipamento do seu Deck ou Cemitério à sua mão. \r\nSe você controlar uma Magia de Equipamento: você pode colocar 1 monstro Guerreiro de FOGO ou 1 monstro Gêmeos do seu Cemitério no fundo do seu Deck; compre 1 card. \r\nVocê só pode usar cada efeito de "Gerar Equipamento" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27980138,'Caneta de Pena de Gulldos','Escolha 2 monstros de VENTO no seu Cemitério e 1 card no campo; embaralhe esses 2 primeiros alvos no seu Deck e, se isso acontecer, devolva o outro para a mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27993919,'LaSolfacorde Angelia',replace(replace('Escala de Pêndulo = 3\r\n[ Efeito de Pêndulo ]\r\nSeu oponente não pode ativar Cards de Magia/Armadilha ou efeitos de monstro quando um ou mais Monstros Pêndulo "Solfacorde" seus forem Invocados por Invocação-Pêndulo.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nEnquanto você tiver uma Escala de Pêndulo ímpar na sua Zona de Pêndulo, se um Monstro Pêndulo "Solfacorde" seu atacar, seu oponente não pode ativar Cards de Magia/Armadilha ou seus efeitos até o final da Etapa de Dano. \r\nDurante sua Fase Principal: você pode oferecer como Tributo 1 Monstro Pêndulo "Solfacorde" (mesmo se estiver com a face para baixo) e, se isso acontecer, Invoque por Invocação-Especial do seu Deck 1 Monstro Pêndulo "Solfacorde" cuja Escala de Pêndulo seja 2 maior ou 2 menor que a desse monstro, exceto "LaSolfacorde Angelia". \r\nVocê só pode usar este efeito de "LaSolfacorde Angelia" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27995943,'Dr. Frankenderp',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode pagar 500 PV; olhe o card do topo do seu Deck e, depois, coloque-o no fundo do seu Deck, OU revele-o e adicione-o à sua mão, mas pule sua próxima Fase de Compra se ele for adicionado à mão. \r\nVocê só pode usar este efeito de "Dr. Frankenderp" uma vez por turno.','\r',char(13)),'\n',char(10)),'Colocar o card revelado no fundo do Deck?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28002611,'Transportador de Dispositivos','Uma vez por turno, você pode enviar qualquer número de monstros "Morfotrônico(a)" da sua mão ao Cemitério para fazer este card ganhar 800 ATK para cada.','Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28003512,'A Mão do Julgamento','Uma mão poderosa que faz ataques implacáveis.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28004531,'Rex, o Freteiro de Peluguel',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 Magia/Armadilha "de Peluguel" do seu Deck à sua mão. \r\nDurante a Fase Principal, se você controlar um monstro "de Peluguel" (Efeito Rápido): você pode banir este card do seu Cemitério e, depois, escolha 1 card "de Peluguel" no seu Cemitério; adicione-o à sua mão, ou Invoque-o por Invocação-Especial se era um monstro. \r\nVocê só pode usar cada efeito de "Rex, o Freteiro de Peluguel" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28016193,'Metalmorfose Oricalc',replace(replace('2 monstros "Metalmorfose"	\r\nSe um monstro "Metalmorfose" que você controla atacar um monstro em Posição de Defesa, cause o dobro de dano de batalha perfurante ao seu oponente. \r\nSe este card for enviado do campo para o Cemitério: você pode escolher 1 card no campo; destrua-o.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28031913,'Crusadia Leonis',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) em Posição de Defesa em uma zona sua para a qual um Monstro Link apontar. \r\nVocê só pode Invocar "Crusadia Leonis" por Invocação-Especial uma vez por turno desta forma. \r\nVocê pode escolher 1 Monstro Link "Crusadia" que você controla; se ele atacar um monstro em Posição de Defesa neste turno, cause dano de batalha perfurante ao seu oponente. \r\nVocê só pode usar este efeito de "Crusadia Leonis" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28039390,'Reviver Peladura',replace(replace('Escolha 1 monstro "Peladura" no seu Cemitério; Invoque-o por Invocação-Especial. \r\nDurante sua Fase Principal, exceto no turno em que este card foi enviado para o Cemitério: você pode banir este card do seu Cemitério e, depois, escolher 1 dos seus monstros "Fofanimal" ou "Peladura" banidos; devolva-o para o Cemitério.','\r',char(13)),'\n',char(10)),'Invocação Especial','Retornar para o Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28053106,'Anjo Ovo Ciber',replace(replace('Se este card for Invocado: você pode adicionar 1 Magia "Máquina de Anjo" ou 1 "Santuário do Ritual" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Anjo Ovo Ciber" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28053763,'Gerador Dragonoide',replace(replace('Ative este card ao pagar 1000 PV. \r\nDurante sua Fase Principal: você pode Invocar por Invocação-Especial 1 "Ficha Dragonoide" (Máquina/TERRA/Nível 1/ATK 300/DEF 300) em Posição de Ataque, você não pode Invocar monstros por Invocação-Especial do Deck Adicional pelo resto deste turno e, além disso, durante a Fase Final, seu oponente Invoca por Invocação-Especial 1 "Ficha Dragonoide" no seu próprio campo em Posição de Ataque (mesmo que este card deixe o campo). \r\nVocê pode usar este efeito de "Gerador Dragonoide" até duas vezes por turno.','\r',char(13)),'\n',char(10)),'Invocar uma Ficha por Invocação Especial','Seu oponente deve Invocar por Invocação Especial 1 "Ficha Dragonoide" no campo dele em Posição de Ataque','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28053764,'Ficha Dragonoide','Invocada por Invocação-Especial com o efeito "Gerador Dragonoide".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28062325,'Pedaço de Bambu',replace(replace('Ofereça como Tributo 1 monstro do Tipo Planta. \r\nInvoque por Invocação-Especial 2 "Fichas de Planta" (Tipo Planta/TERRA/Nível 1/ATK 800/DEF 500) no lado do campo do oponente em Posição de Defesa.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28062326,'Ficha de Planta','Invocado por Especial com o efeito "Pedaço de Bambu".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28066831,'Gusto Thunbolt','No final da Fase de Batalha, se este card estiver no Cemitério porque foi destruído em batalha e enviado para o Cemitério neste turno: Você pode banir 1 monstro "Gusto" do seu Cemitério; Invoque por Invocação-Especial 1 monstro de VENTO do Tipo Psíquico com 1500 ou menos de DEF do seu Deck.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28103028,'Cavaligni Dragonis','Este cavalo-draco corre pelo mar, fervendo a superfície da água ao mesmo tempo que impede que suas próprias chamas se apaguem. Seu sonho é um dia voltar a colocar os pés em sua terra natal.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28106077,'Cestus de Dagla',replace(replace('Só pode ser equipado a um monstro Fada. \r\nEle ganha 500 de ATK. \r\nSe ele causar dano de batalha ao seu oponente: ganhe PV igual ao dano causado.','\r',char(13)),'\n',char(10)),'Ganhar PV','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28112535,'Dragão Revólver Toon',replace(replace('Não pode atacar no turno em que for Invocado. \r\nEnquanto você controlar "Mundo Toon" e seu oponente não controlar nenhum monstro Toon, este card pode atacar diretamente seu oponente. \r\nUma vez por turno: você pode escolher 1 card no campo; lance uma moeda 3 vezes e destrua-o se pelo menos 2 resultados forem cara.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28115467,'MiSolfacorde Eliteia',replace(replace('Escala de Pêndulo = 6\r\n[ Efeito de Pêndulo ]\r\nA Invocação-Pêndulo dos seus Monstros Pêndulo "Solfacorde" não pode ser negada.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nEnquanto você tiver uma Escala de Pêndulo par na sua Zona de Pêndulo, você não sofre dano das batalhas envolvendo seus Monstros Pêndulo "Solfacorde". \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 Magia/Armadilha que seu oponente controla; devolva-a para a mão. \r\nVocê só pode usar este efeito de "MiSolfacorde Eliteia" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28118128,'Bebê Guaxinim Tantan','VIRE: Invoque por Invocação-Especial 1 monstro do Tipo Besta de Nível 2 do seu Deck, exceto "Bebê Guaxinim Tantan".','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28120197,'Desfiladeiro','Se um monstro do Tipo Rocha em Posição de Defesa for atacado, dobre qualquer Dano de Batalha causado ao controlador do monstro atacante.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28121403,'Descanço Realmente Eterno','Destrói todos os monstros equipados com Cards de Equipamento.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28124263,'Câmeran Morfotrônico',replace(replace('● Enquanto estiver em Posição de Ataque: Quando este card for destruído em batalha, você pode Invocar por Invocação-Especial 1 monstro "Morfotrônico(a)" de Nível 4 ou menos da sua mão ou Cemitério, exceto "Câmeran Morfotrônico".\r\n● Enquanto estiver em Posição de Defesa: Monstros "Morfotrônico(a)" no campo não podem ser escolhidos como alvo de efeitos.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28126717,'Brisawntarilho e o Mapa Magnífico',replace(replace('Durante sua Fase Principal: você pode revelar 1 monstro "Brisawntarilho" de Nível 1 na sua mão e banir 1 card "Brisawntarilho" com um nome diferente do seu Deck e, depois, imediatamente depois que este efeito resolver, Invoque o monstro revelado por Invocação-Normal. \r\nSe seu oponente Invocar um monstro por Invocação-Normal: imediatamente depois que este efeito resolver, você pode Invocar por Invocação-Normal 1 monstro "Brisawntarilho". \r\nVocê só pode usar cada efeito de "Brisawntarilho e o Mapa Magnífico" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28139785,'Panda-vermelho Guincho',replace(replace('Uma vez por turno, durante a Fase de Apoio: você pode pagar 500 PV; envie o card do topo do seu Deck para o Cemitério e, se isso acontecer, este card ganha ATK e DEF igual ao Nível do monstro x 200, se o card era um monstro. \r\nSe este card em sua posse for destruído por um card do seu oponente (em batalha ou por um efeito de card) e enviado para o seu Cemitério: você pode adicionar 1 monstro com o menor Nível do seu Cemitério para a sua mão (em caso de empate, você escolhe).','\r',char(13)),'\n',char(10)),'Enviar para o Cemitério','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28143384,'Comedor Aéreo',replace(replace('2 monstros Demônio com o mesmo Atributo	\r\nSe este card for Invocado por Invocação-Fusão: você pode enviar 1 monstro Demônio do seu Deck para o Cemitério. \r\nSe este card estiver no seu Cemitério: você pode banir 2 monstros Demônio de Nível 6 ou mais com o mesmo Atributo um do outro do seu Cemitério, exceto "Comedor Aéreo"; Invoque este card por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Comedor Aéreo" uma vez por turno.','\r',char(13)),'\n',char(10)),'Enviar para o Cemitério','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28143906,'Roca do Vale da Neblina','Quando este card é enviado da sua mão para o Cemitério, adicione este card ao Deck e embaralhe-o.','Retornar ao Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28150174,'Papilloperativo de Fóton',replace(replace('2 monstros de Nível 4	\r\nUma vez por turno: você pode desassociar 1 Matéria Xyz deste card e, depois, escolher 1 monstro em Posição de Defesa no campo; coloque-o com a face para cima em Posição de Ataque e, se isso acontecer, ele perde 600 de ATK.','\r',char(13)),'\n',char(10)),'Mudar a posição de batalha','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28151978,'Velocidaroide Borboleta Dominó',replace(replace('Escala de Pêndulo = 8\r\n[ Efeito de Pêndulo ]\r\nVocê não pode Invocar monstros por Invocação-Pêndulo, exceto monstros de VENTO. \r\nEste efeito não pode ser negado. \r\nVocê pode descartar 1 monstro de VENTO e, depois, escolher 1 de seus monstros de VENTO banidos; adicione-o à sua mão. \r\nVocê só pode usar este efeito de "Velocidaroide Borboleta Dominó" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nNão pode ser usado como uma Matéria Sincro, exceto para a Invocação Sincro de um Monstro Sincro de VENTO do Tipo Dragão ou Máquina. \r\nSe este card, Invocado por Invocação-Especial do Deck Adicional, for usado como uma Matéria para uma Invocação-Sincro, bana-o.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28168628,'Rocha do Aniquilador',replace(replace('1 monstro "Alma Aniquiladora"	\r\nNão pode ser usado como Matéria Link. \r\nEnquanto você controlar um monstro "Alma Aniquiladora", os monstros do seu oponente só podem escolher monstros que você controla com o maior ATK (em caso de empate, ele seleciona) como alvo de ataques. \r\nDurante a Fase Principal (Efeito Rápido): você pode ativar 1 desses efeitos;\r\n● Invoque por Invocação-Especial 1 monstro "Alma Aniquiladora" da sua mão.\r\n● Adicione 1 monstro "Alma Aniquiladora" do seu Cemitério à sua mão.	\r\nVocê só pode usar este efeito de "Rocha do Aniquilador" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invoque por Invocação Especial 1 monstro "Alma Aniquiladora" da sua mão','Adicione à sua mão 1 monstro "Alma Aniquiladora" do seu Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28168762,'Gardna de Solarvinhas',replace(replace('1 Monstro Normal Planta	\r\nSe um Monstro Link "Solaravalon" que você controla deixar o campo devido a um efeito de card: destrua este card. \r\nQuando um ataque for declarado envolvendo este card linkado a um Monstro Link "Solaravalon" e um monstro do oponente: você pode ativar este efeito; o dano que você sofrer dessa batalha é diminuído pela metade. \r\nQuando este card for destruído em batalha: encerre a Fase de Batalha depois da Etapa de Dano.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28174796,'Marincesa Mandarim',replace(replace('Se você controlar 2 ou mais monstros "Marincesa", enquanto este card estiver na sua mão ou no Cemitério: você pode escolher 1 Monstro Link de ÁGUA que você controla; Invoque este card por Invocação-Especial em uma zona sua para a qual esse monstro apontar, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar este efeito de "Marincesa Mandarim" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28183605,'Duque Dragunidade',replace(replace('Ganha 200 de ATK para cada card "Dragunidade" que você controla. \r\nQuando este card for Invocado por Invocação-Normal: você pode escolher 1 monstro Dragão "Dragunidade" de Nível 3 ou menos no seu Cemitério; equipe o alvo a este card.','\r',char(13)),'\n',char(10)),'Equipar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28189908,'T.G. Remoção de Limitador',replace(replace('Descarte 1 card; adicione 2 monstros "T.G." com nomes diferentes do seu Deck à sua mão. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 monstro "T.G." no seu Cemitério; embaralhe-o no Deck ou, se você controlar um monstro Máquina "T.G.", em vez disso, você pode adicioná-lo à sua mão. \r\nVocê só pode usar 1 efeito de "T.G. Remoção de Limitador" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Adicionar à mão?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28190303,'Asanegra - Gladius, o Sol da Meia-noite',replace(replace('Se o único monstro com a face para cima que você controla for 1 monstro "Asanegra", exceto "Asanegra - Gladius, o Sol da Meia-noite", você pode Invocar este card por Invocação-Especial (da sua mão). \r\nUma vez por turno, este card não pode ser destruído em batalha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28194325,'Desafiante Heroico - Espada Gancho',replace(replace('Quando este card for Invocado por Invocação-Especial pelo efeito de um monstro "Desafiante Heroico": você pode adicionar 1 monstro "Desafiante Heroico" do seu Deck à sua mão. \r\nVocê só pode usar o efeito de "Desafiante Heroico - Espada Gancho" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28201945,'Armadilhatrix Nepenthes',replace(replace('Não é afetado pelos efeitos de Armadilhas Normais "Buraco". \r\nSe você ativar um Card de Armadilha Normal "Buraco" (exceto durante a Etapa de Dano): você pode adicionar à sua mão, ou Invocar por Invocação-Especial, 1 monstro "Armadilhatrix" do seu Deck, exceto "Armadilhatrix Nepenthes". \r\nVocê só pode usar este efeito de "Armadilhatrix Nepenthes" uma vez por turno.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Invocar aquele monstro por Invocação Especial?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28226490,'Lagrimentiara Caleido-Heart',replace(replace('"Lagrimentiara Reinoheart" + 2 monstros Aqua	\r\nNão pode ser usado como Matéria de Fusão. \r\nSe este card for Invocado por Invocação-Especial ou se um monstro Aqua for enviado para o seu Cemitério por um efeito de card enquanto este card estiver no campo: você pode escolher 1 card que seu oponente controla; embaralhe-o no Deck. \r\nSe este card for enviado para o Cemitério por um efeito de card: você pode Invocar este card por Invocação-Especial e, se isso acontecer, envie 1 card "Lagrimentiara" do seu Deck para o Cemitério. \r\nVocê só pode usar cada efeito de "Lagrimentiara Caleido-Heart" uma vez por turno.','\r',char(13)),'\n',char(10)),'Retornar o card do seu oponente ao Deck do seu dono','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28234578,'Entrelaçamento Espiritual',replace(replace('Escolha 1 monstro com a face para cima que seu oponente controla; bana-o até a Fase Final. \r\nVocê só pode ativar 1 "Entrelaçamento Espiritual" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28240337,'Necro Dragão Zumbi de Olhos Vermelhos',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nGanha 100 de ATK/DEF para cada monstro Zumbi no campo e nos Cemitérios. \r\nQuando outro monstro Zumbi for destruído em batalha: você pode Invocar por Invocação-Especial 1 monstro Zumbi de qualquer Cemitério no seu campo. \r\nVocê só pode usar este efeito de "Necro Dragão Zumbi de Olhos Vermelhos" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28265983,'Ventos Secos',replace(replace('Se você ganhar PV: escolha 1 monstro com a face para cima que seu oponente controla; destrua-o. \r\nSe você controlar um monstro "Aromági" e tiver pelo menos 3000 PV a mais que seu oponente: você pode pagar PV igual à diferença; destrua monstros com a face para cima que seu oponente controla cujo ATK combinado seja igual ou menor que os PV que você pagou para ativar este efeito. \r\nVocê só pode usar cada efeito de "Ventos Secos" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar, mas não resolver o efeito','Escolha 1 monstro para destruir','Escolha 1 monstro com ATK menor ou igual aos PV pagos para destruí-lo','Escolher outro monstro para destruir?','','','','','','','','','','','','');
INSERT INTO texts VALUES(28270534,'Espírito LutI.A.dor',replace(replace('Escolha 1 monstro "@Ignister" no seu Cemitério; Invoque-o por Invocação-Especial. \r\nSe um ou mais monstros "@Ignister" que você controla com 2300 ou mais de ATK seriam destruídos por um efeito de card, em vez disso, você pode banir este card do seu Cemitério. \r\nSe este card for banido: você pode ativar este efeito; seus monstros "@Ignister" com 2300 ou mais de ATK não podem ser destruídos em batalha neste turno. \r\nVocê só pode ativar "Espírito LutI.A.dor" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28273805,'Ataque dos Seis - Assalto Duplo',replace(replace('Aplique 1 desses efeitos ou, se você controlar 2 ou mais monstros "Seis Samurai", você pode aplicar os dois efeitos em sequência.\r\n● Invoque por Invocação-Especial 1 monstro "Seis Samurai" com 2000 ou menos de ATK da sua mão ou do Cemitério.\r\n● Coloque 1 monstro que seu oponente controla com 2000 ou menos de ATK com a face para baixo em Posição de Defesa.	\r\nDurante sua Fase Principal: você pode banir este card do seu Cemitério e, depois, escolha 1 monstro "Seis Samurai" no seu Cemitério; adicione-o à sua mão. \r\nVocê só pode usar 1 efeito de "Ataque dos Seis - Assalto Duplo" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Mudar a posição de batalha','Escolha um jogador','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28279365,'Desmaterializar','Escolha 1 Monstro Link no campo; devolva-o para o Deck Adicional e, depois, você pode Invocar por Invocação-Especial 1 dos monstros do seu Cemitério que foram enviados para lá como Matéria Link dele.','Invocação Especial?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28279543,'Maldição do Dragão','Um dragão perverso que se apoia nas forças das trevas para executar um poderoso ataque.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28284902,'Monitron Morfotrônico','Quando um monstro "Morfotrônico(a)" for Invocado, você pode colocá-lo com a face para cima em Posição de Defesa.','Mudar para Posição de Defesa','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28290705,'Rei das Fadas Albverdich',replace(replace('2 monstros de TERRA de Nível 4	\r\nUma vez por turno: Você pode desassociar 1 Matéria Xyz deste card; todos os monstros que não sejam de TERRA atualmente no campo perdem 500 ATK e DEF.','\r',char(13)),'\n',char(10)),'Reduzir ATK/DEF','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28292031,'Reversão Dinomorfia',replace(replace('Se você controlar um Monstro de Fusão "Dinomorfia": pague metade dos seus PV e bana do seu Cemitério 1 Armadilha de Resposta; este efeito se torna o efeito dessa Armadilha de Resposta quando esse card for ativado. \r\nDurante o cálculo de dano, enquanto seus PV forem 2000 ou menos, se você sofreria dano de batalha: você pode banir este card do seu Cemitério; você não sofre dano de batalha dessa batalha. \r\nVocê só pode ativar 1 "Reversão Dinomorfia" por turno.','\r',char(13)),'\n',char(10)),'Copie um Card de Armadilha de Resposta','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28297833,'Necroface',replace(replace('Se este card for Invocado por Invocação-Normal: embaralhe todos os cards banidos no Deck. \r\nEste card ganha 100 de ATK para cada card embaralhado no Deck Principal por este efeito. \r\nSe este card for banido: cada duelista bane 5 cards do topo do seu Deck (ou todo o seu Deck, se tiver menos de 5).','\r',char(13)),'\n',char(10)),'Retornar todos os cards banidos ao Deck','Cada duelista bane 5 cards do topo do próprio Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28306253,'Hambúrguer Furioso',replace(replace('(Este card deve ser sempre considerado como "Hambúrguer Esfomeado".)	\r\nVocê pode Invocar este card por Invocação-Ritual com um card "Receita". \r\nMonstros que seu oponente controla que podem atacar devem atacar este card. \r\nVocê só pode usar cada um dos seguintes efeitos de "Hambúrguer Furioso" uma vez por turno. \r\nVocê pode revelar este card na sua mão; adicione 1 monstro "Nouvelles" do seu Deck à sua mão e, se isso acontecer, embaralhe este card no Deck. \r\n(Efeito Rápido): você pode oferecer como Tributo 1 monstro em Posição de Ataque em qualquer campo e, se isso acontecer, Invoque por Invocação-Especial 1 "Hambúrguer Esfomeado" com 2000 de ATK da sua mão ou do Deck.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28325165,'História Aqua - Urashima','Se você tiver um monstro "Aquatriz" no seu Cemitério: escolha 1 monstro no campo; até o final deste turno, os efeitos dele são negados, o ATK/DEF dele se tornam 100 e, além disso, ele não é afetado pelos efeitos de card do seu oponente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28331069,'Neo Dragão de Fóton de Olhos das Galáxias – Uivador Fóton',replace(replace('3 monstros Nível 8	\r\nUma vez por turno, você também pode Invocar "Neo Dragão de Fóton de Olhos das Galáxias – Uivador Fóton" por Invocação-Especial usando 1 Monstro Xyz de Classe 8 que você controla (transfira suas matérias para este card).\r\nSe este card for Invocado por Invocação-Xyz: você pode pegar 1 monstro "Fóton" do seu Deck, e Invoca-lo por Invocação-Especial em Posição de Defesa ou anexa-lo como matéria a este card. \r\n(Efeito Rápido): você pode desassociar 3 matérias deste card; ofereça como Tributo 1 outro Monstro Xyz, e se fizer, nege os efeitos de todos os outros cards com a face para cima atualmente no campo até o final deste turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Xyz usando um Monstro Xyz como matéria?','Invocação Especial?','Escolha o monstro a resolver','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28331070,'Neo Dragão de Fóton de Olhos das Galáxias – Uivador Fóton',replace(replace('3 monstros Nível 8	\r\nUma vez por turno, você também pode Invocar "Neo Dragão de Fóton de Olhos das Galáxias – Uivador Fóton" por Invocação-Especial usando 1 Monstro Xyz de Classe 8 que você controla (transfira suas matérias para este card).\r\nSe este card for Invocado por Invocação-Xyz: você pode pegar 1 monstro "Fóton" do seu Deck, e Invoca-lo por Invocação-Especial em Posição de Defesa ou anexa-lo como matéria a este card. \r\n(Efeito Rápido): você pode desassociar 3 matérias deste card; ofereça como Tributo 1 outro Monstro Xyz, e se fizer, nege os efeitos de todos os outros cards com a face para cima atualmente no campo até o final deste turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Xyz usando um Monstro Xyz como matéria?','Invocação Especial?','Escolha o monstro a resolver','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28332833,'Poun de Flamvell','Quando este card for destruído em batalha e enviado para o Cemitério: você pode adicionar 1 monstro com DEF 200 do seu Deck à sua mão.','Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28340377,'Corte de Figuras',replace(replace('Se você não controlar nenhum monstro ou controlar apenas "O Cavaleiro da Rainha", "O Cavaleiro do Rei" e/ou "O Cavaleiro do Valete": você pode Invocar por Invocação-Especial 1 "O Cavaleiro da Rainha", "O Cavaleiro do Rei" ou "O Cavaleiro do Valete" da sua mão ou do Cemitério. \r\nVocê pode banir até 1 de cada de "O Cavaleiro da Rainha", "O Cavaleiro do Rei" e/ou "O Cavaleiro do Valete" da sua mão e/ou do Cemitério; compre o mesmo número de cards que você baniu. \r\nVocê só pode usar 1 efeito de "Corte de Figuras" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Banir e comprar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28346136,'Dragão X Críptico de Olhos das Galáxias',replace(replace('2 monstros de Nível 10	\r\nUma vez por turno, você também pode Invocar por Invocação-Xyz "Dragão X Críptico de Olhos das Galáxias" usando um monstro "Dragão Críptico" que você controla (transfira as matérias dele). \r\nVocê pode desassociar 2 matérias deste card; até o final do turno do seu oponente, seu oponente não pode escolher monstros de LUZ que você controla como alvo de efeitos de card. \r\nUma vez por turno, durante sua Fase de Apoio: você pode devolver 1 Monstro Xyz Dragão de Classe 9 ou menos do seu Cemitério para o Deck Adicional e, depois, você pode Invocar esse monstro por Invocação-Especial do seu Deck Adicional, usando este card que você controla como matéria (isso é considerado uma Invocação-Xyz, transfira as matérias deste card).','\r',char(13)),'\n',char(10)),'Invocar por Invocação Xyz sobrepondo um monstro "Dragão Críptico"?','','','','Invocar aquele monstro por Invocação Especial?','','','','','','','','','','','');
INSERT INTO texts VALUES(28348537,'Princesa da Nevasca',replace(replace('Você pode Invocar este card por Invocação-Tributo com a face para cima em Posição de Ataque ao oferecer como Tributo 1 monstro do Tipo Mago. \r\nDepois que este card for Invocado por Invocação-Normal, seu oponente não pode ativar Cards de Magia/Armadilha pelo resto desse turno.','\r',char(13)),'\n',char(10)),'Invoque por Invocação Tributo ao oferecer 1 monstro Mago como Tributo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28348939,'Invocador do Tigre Branco',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode Invocar por Invocação-Especial 1 Monstro Normal de Nível 4 ou menos da sua mão. \r\nTodos os monstros que você controla ganham 100 de ATK e DEF.','\r',char(13)),'\n',char(10)),'Invocação Especial','Aumentar ATK/DEF','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28355718,'HERÓI do Destino - Homem-Duplicado',replace(replace('Não pode ser Invocado por Invocação-Especial. \r\nEste card pode atacar duas vezes durante cada Fase de Batalha. \r\nDurante a sua Fase de Apoio, se este card tiver sido destruído desde sua última Fase de Apoio: Você pode Invocar por Invocação-Especial 2 "Ficha de Homem-Duplicado" (Tipo Guerreiro/TREVAS/Nível 4/ATK 1000/DEF 1000). \r\nEste card deve estar no seu Cemitério para ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28355719,'Ficha de Homem-Duplicado','Invocado por Especial com o efeito "HERÓI do Destino - Homem-Duplicado".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28357177,'Hade-Hane','VIRE: Você pode devolver até 3 monstros no Campo para a mão dos seus donos.','Retornar à mão','Escolher um monstro para devolver à mão?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28358902,'Sentinela Carmesim','Ofereça como Tributo este card com a face para cima para devolver ao fundo do seu Deck 1 dos seus monstros destruídos em batalha durante este turno.','Retornar ao Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28363749,'Cabeça Opala de Fogo',replace(replace('Escala de Pêndulo = 0\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nEste líder de bando de dinossauros com uma cabeça flamejante de pedras recebe seu nome do seu ataque definitivo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28369508,'Escavação Behemoth Subterror',replace(replace('Você pode banir 1 monstro "Subterror" do seu Cemitério; pelo resto deste turno, monstros com a face para baixo que você controla não podem ser destruídos por efeitos de card e seu oponente não pode escolhê-los como alvo de efeitos de card. \r\nSe este card no campo for destruído por um efeito de card: você pode adicionar 1 monstro "Subterror" do seu Deck à sua mão. \r\nVocê pode banir este card do seu Cemitério e, depois, escolher 1 monstro "Subterror" que você controla; coloque-o com a face para baixo em Posição de Defesa.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28373620,'Geri, as Presas Rúnikas',replace(replace('2 monstros "Rúnika(o)"	\r\nNão pode ser destruído por efeitos de card. \r\nSe este card for Invocado por Invocação-Especial do Deck Adicional: você pode escolher 1 Magia "Rúnika(o)" que não seja Rápida no seu Cemitério; adicione-a à sua mão. \r\nQuando este card for destruído em batalha: você pode escolher 1 card no campo; destrua-o.','\r',char(13)),'\n',char(10)),'Recuperar do Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28378427,'Condensador de Dano','Quando você sofrer dano de batalha: descarte 1 card; Invoque por Invocação-Especial em Posição de Ataque 1 monstro do seu Deck com ATK igual ou menor que o dano de batalha que você sofreu.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28388296,'Fábrica de Restolhos',replace(replace('Todos os monstros "Restolhos" ganham 200 de ATK/DEF. \r\nQuando um ou mais monstros "Restolhos" com a face para cima no campo forem destruídos por um efeito de card e enviados para o Cemitério (exceto durante a Etapa de Dano): você pode Invocar por Invocação-Especial 1 monstro "Restolhos" do seu Deck. \r\nVocê só pode usar este efeito de "Fábrica de Restolhos" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28388927,'Vespabatalha - Sting, o Veneno',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 monstro "Vespabatalha" do seu Deck à sua mão, exceto "Vespabatalha - Sting, o Veneno". \r\n(Efeito Rápido): você pode oferecer como Tributo 1 outro monstro Inseto e, depois, escolher 1 Monstro de Efeito que seu oponente controla; negue os efeitos dele até o final deste turno. \r\nVocê só pode usar cada efeito de "Vespabatalha - Sting, o Veneno" uma vez por turno.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Negar o efeito','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28400508,'Número 97: Draglubion',replace(replace('2 monstros de Nível 8	\r\nSeu oponente não pode escolher este card como alvo de efeitos de card. \r\nVocê pode desassociar 1 matéria deste card; pegue 2 monstros Dragão "Número" com nomes diferentes do seu Deck Adicional e/ou Cemitério, exceto "Número 97: Draglubion", Invoque 1 deles por Invocação-Especial e associe o outro a ele como matéria e, além disso, pelo resto deste turno, você não pode Invocar outros monstros por Invocação-Especial ou declarar um ataque, exceto com esse monstro Invocado por Invocação-Especial. \r\nVocê só pode usar este efeito de "Número 97: Draglubion" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Escolha o card para usar como Matéria Xyz','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28403802,'Inspiração do Dragão P.U.N.K. JAM',replace(replace('1 Regulador Psíquico + 1+ não-Reguladores	\r\nSe este card for Invocado por Invocação-Especial pelo efeito de um card "P.U.N.K.", ou Invocado por Invocação-Sincro: você pode pagar 600 PV; pegue 1 monstro Psíquico de Nível 3 do seu Deck e adicione-o à sua mão ou envie-o para o Cemitério. \r\nSe seu oponente ativar um card ou efeito em resposta à ativação de um card ou efeito "P.U.N.K." seu, enquanto este card estiver no seu Cemitério: você pode Invocar este card por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Inspiração do Dragão P.U.N.K. JAM" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28403803,'Inspiração do Dragão P.U.N.K. JAM',replace(replace('1 Regulador Psíquico + 1+ não-Reguladores	\r\nSe este card for Invocado por Invocação-Especial pelo efeito de um card "P.U.N.K.", ou Invocado por Invocação-Sincro: você pode pagar 600 PV; pegue 1 monstro Psíquico de Nível 3 do seu Deck e adicione-o à sua mão ou envie-o para o Cemitério. \r\nSe seu oponente ativar um card ou efeito em resposta à ativação de um card ou efeito "P.U.N.K." seu, enquanto este card estiver no seu Cemitério: você pode Invocar este card por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Inspiração do Dragão P.U.N.K. JAM" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28406301,'D/D Grifo',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nVocê pode escolher 1 monstro Demônio que você controla; ele ganha 500 de ATK (até o final deste turno) para cada Magia/Armadilha "Pacto Obscuro" com nomes diferentes atualmente no seu campo ou no seu Cemitério e, depois, destrua este card. \r\nVocê só pode usar este efeito de "D/D Grifo" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe você controlar um monstro "D/D": você pode Invocar este card por Invocação-Especial da sua mão em Posição de Defesa. \r\nSe este card for Invocado por Invocação-Pêndulo: você pode descartar 1 card "D/D" ou "Pacto Obscuro"; compre 1 card. \r\nSe este card for Invocado por Invocação-Especial do Cemitério: você pode adicionar 1 card "D/D" do seu Deck à sua mão, exceto "D/D Grifo". \r\nVocê só pode usar cada efeito de "D/D Grifo" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invoque por Invocação Especial da sua mão em Posição de Defesa','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28423537,'Imperador Arquidemônio, o Primeiro Senhor do Terror',replace(replace('Você pode Invocar este card por Invocação-Normal sem oferecer Tributo, mas seu ATK/DEF originais são diminuídos pela metade. \r\nSe Invocado desta forma, este card é destruído durante a Fase Final. \r\nVocê não pode Invocar monstros por Invocação-Especial, exceto monstros Demônio. \r\nUma vez por turno: você pode banir 1 card "Arquidemônio" da sua mão ou do Cemitério e, depois, escolher 1 card no campo; destrua-o.','\r',char(13)),'\n',char(10)),'Invocar sem oferecer Tributo','Destruir','Destruir durante a Fase Final','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28427869,'Mosquito de Smoking',replace(replace('Durante o cálculo de dano, se você sofreria dano de batalha do ataque de um monstro do oponente (Efeito Rápido): você pode Invocar este card por Invocação-Especial da sua mão e, se isso acontecer, o dano que você sofrer dessa batalha é diminuído pela metade e, além disso, encerre a Fase de Batalha depois da Etapa de Dano. \r\nVocê pode escolher 1 monstro com a face para cima que você controla; até o final deste turno, o Nível deste card se torna o mesmo que o desse monstro. \r\nVocê só pode usar cada efeito de "Mosquito de Smoking" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28429121,'Artes Proibidas dos Gishki',replace(replace('Este card pode ser usado para a Invocação-Ritual de qualquer Monstro de Ritual "Gishki". \r\nVocê também deve oferecer como Tributo monstros de qualquer parte do campo cuja soma dos Níveis seja exatamente igual ao Nível do Monstro de Ritual que você Invocar por Invocação-Ritual. \r\nSe isso acontecer, seu ATK é diminuído pela metade. \r\nVocê não pode conduzir sua Fase de Batalha no turno em que ativar este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28450915,'Invasor de Outra Dimenção','Um monstro extraterrestre que veio de uma galáxia distante.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28454232,'Eneanave - Asta.PIXEA',replace(replace('Escala de Pêndulo = 0\r\n[ Efeito de Pêndulo ]\r\nSempre que um ou mais monstros forem virados com a face para cima, coloque 1 Marcador de E.N. neste card. \r\nNo final da Fase de Batalha, se você tiver um card "Eneanave" na sua outra Zona de Pêndulo: você pode escolher 1 monstro que seu oponente controla com ATK menor que o deste card; destrua-o.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nDepois que este card foi virado com a face para cima, enquanto ele estiver na Zona de Monstros, seu oponente não pode escolher cards no campo ou nos Cemitérios como alvo de efeitos de card. \r\nQuando seu oponente ativar um card ou efeito que escolha como alvo um ou mais cards que você controla (Efeito Rápido): você pode colocar este card que estiver com a face para baixo, com a face para cima em Posição de Defesa; negue o efeito e, depois, você pode banir (com a face para baixo) 1 card aleatório da mão do seu oponente. \r\nVocê pode revelar este card na sua mão; Invoque por Invocação-Especial 1 monstro da sua mão com a face para baixo em Posição de Defesa. \r\nVocê não pode Invocar por Invocação-Especial no turno em que ativar este efeito, exceto com a face para baixo em Posição de Defesa.','\r',char(13)),'\n',char(10)),'Destruir','Invocação Especial','Banir','Banir?','Já foi virado','','','','','','','','','','','');
INSERT INTO texts VALUES(28465301,'Lombriga Ópera','VIRE: Todos os monstros com a face para cima no campo perdem 500 de ATK, exceto monstros "Lombriga" do Tipo Réptil.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28470714,'Bladefly','Enquanto este card permanecer no Campo com a face para a cima, aumente o ATK de todos os monstros do VENTO em 500 pontos e diminua o ATK de todos os monstros da TERRA em 400 pontos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28486799,'Pelotão de Reforço','Sempre que você sofrer 1000 ou mais de dano devido a um efeito de card do seu oponente ou um ataque de monstro dele: compre 1 card para cada 1000 de dano que você sofreu.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28493337,'Designador do Armagedon','Bana 1 card da sua mão; pelo restante deste Duelo, nenhum duelista pode ativar cards ou os efeitos de cards com esse nome.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28497830,'Orgulho Dourado - Grande Gira-Bola',replace(replace('"Orgulho Dourado - Gira-Bola" + 1+ monstro "Orgulho Dourado"	\r\nSe este card for Invocado por Invocação-Fusão: você pode equipar a ele monstros com a face para cima que seu oponente controla, até o número de Matérias de Fusão usadas. \r\nVocê só pode usar o efeito anterior de "Orgulho Dourado - Grande Gira-Bola" uma vez por turno e, além disso, se você tiver menos PV que seu oponente, a ativação do efeito e o efeito não podem ser negados. \r\nUma vez por turno, durante a Fase Final, se o efeito anterior foi ativado neste turno: devolva este card para o Deck Adicional e, se isso acontecer, Invoque por Invocação-Especial 1 "Orgulho Dourado - Gira-Bola" do seu Deck ou Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28506708,'Invocação de Lombrigas','Uma vez por turno, se seu oponente controlar um monstro e você não controlar nenhum monstro, você pode Invocar por Invocação-Especial 1 monstro "Lombriga" do Tipo Réptil da sua mão com a face para baixo em Posição de Defesa.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28529976,'Nutriente Super Solar',replace(replace('Ative este card ao oferecer como Tributo 1 monstro do Tipo Planta de Nível 2 ou menos; Invoque por Invocação-Especial 1 monstro do Tipo Planta da sua mão ou Deck cujo Nível seja menor ou igual ao Nível que o monstro oferecido como Tributo tinha no campo +3. \r\nQuando este card deixar o campo, destrua esse monstro. \r\nQuando esse monstro deixar o campo, destrua este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28531163,'Apocavidades',replace(replace('Quando este card for ativado: coloque Marcadores C neste card, igual ao número de cards que seu oponente controla. \r\nVocê pode escolher 1 monstro com a face para cima que seu oponente controla e remover até 4 Marcadores C do seu campo; aplique este efeito a esse monstro, de acordo com o número removido.\r\n● 1: Ele perde 500 de ATK.\r\n● 2: O ATK dele se torna 0.\r\n● 3: Seus efeitos são negados.\r\n● 4: Destrua-o.	\r\nVocê só pode ativar 1 "Apocavidades" por turno.','\r',char(13)),'\n',char(10)),'Escolha um efeito para ativar','Reduzir ATK','ATK torna-se 0','Negar o efeito','Destruir','','','','','','','','','','','');
INSERT INTO texts VALUES(28534130,'Salamagrande Casca Ardente',replace(replace('Invoque por Invocação-Especial 1 monstro "Salamagrande" da sua mão, mas negue seus efeitos e, depois, imediatamente depois que este efeito resolver, Invoque por Invocação-Link 1 Monstro Link "Salamagrande" usando matérias que você controla, incluindo o monstro Invocado. \r\nNeste turno, esse monstro Invocado por Invocação-Link não pode atacar ou ativar seus efeitos. \r\nDurante sua Fase Principal: você pode banir este card do seu Cemitério e, depois, escolha 1 Monstro Link "Salamagrande" no seu Cemitério; devolva-o para o Deck Adicional. \r\nVocê só pode ativar 1 "Salamagrande Casca Ardente" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28546905,'Ilusionista Sem Rosto','Manipula os ataques inimigos com o poder da ilusão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28553439,'Dimensão Mágica','Se você controlar um monstro Mago: escolha 1 monstro que você controla; ofereça o alvo como Tributo e, depois, Invoque por Invocação-Especial 1 monstro Mago da sua mão e, depois, você pode destruir 1 monstro no campo.','Destruir 1 monstro?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28563545,'Caçador de Dragões','Quando este card é Invocado por Invocação-Normal ou Invocação-Virar, destrói 1 monstro do Tipo Dragão no Campo com a face para cima.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28565527,'Invocador do Dragão Dourado',replace(replace('Você pode oferecer 1 monstro como Tributo e, depois, escolher 1 monstro no campo; devolva-o para a mão. \r\nVocê só pode usar este efeito de "Invocador do Dragão Dourado" uma vez por turno.','\r',char(13)),'\n',char(10)),'Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28566710,'Último Turno',replace(replace('Este card só pode ser ativado apenas durante o turno do seu adversário, quando os seus Life Points sejam 1000 ou menos. \r\nEscolha 1 monstro do seu Campo e envie todos os outros cards no Campo e nas mãos dos respectivos jogadores para os respectivos Cemitérios. \r\nEm seguida, o seu adversário escolhe e Invoca, por Invocação-Especial, 1 monstro do seu próprio Deck com face para cima e em Posição de Ataque, atacando o seu monstro. \r\n(Qualquer dano de batalha que ocorra nesta batalha é tratado como 0). \r\nO jogador cujo monstro permaneceu sozinho no Campo no final da End Phase deste turno ganha o Duelo. \r\nQualquer outra situação resulta em um EMPATE.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28570310,'Besta Mítica Garuda',replace(replace('Escala de Pêndulo = 4\r\n[ Efeito de Pêndulo ]\r\nSe você não tiver nenhum card na sua outra Zona de Pêndulo: você pode escolher 1 outra Magia/Armadilha no campo; destrua tanto ela como este card. \r\nVocê só pode usar este efeito de "Besta Mítica Garuda" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSempre que um Card de Magia for ativado, coloque 1 Marcador de Magia neste card quando essa Magia resolver. \r\nQuando seu oponente Invocar um ou mais monstros por Invocação-Normal ou Especial (exceto durante a Etapa de Dano): você pode remover 3 Marcadores de Magia do seu campo; Invoque este card por Invocação-Especial da sua mão e, depois, devolva esse(s) monstro(s) \r\nInvocados pelo oponente para a mão. \r\nVocê só pode usar este efeito de "Besta Mítica Garuda" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28573958,'O Representante dos Milagres - Júpiter',replace(replace('Uma vez por turno: você pode banir 1 monstro "O Representante" do seu Cemitério e, depois, escolha 1 monstro Fada de LUZ que você controla; o alvo ganha 800 de ATK até o final deste turno. \r\nUma vez por turno: você pode descartar 1 monstro Fada e, depois, escolha 1 dos seus monstros Fada de LUZ banidos; Invoque-o por Invocação-Especial. "O Santuário no Céu" deve estar no campo para ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Aumentar ATK','Banir 1 monstro para Invocar por Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28577986,'Sirena Abisocea',replace(replace('Você pode escolher 1 monstro "Sirena" que você controla; Invoque por Invocação-Especial qualquer número de monstros "Sirena" de Nível 4 ou menos do seu Deck, cujos Níveis combinados sejam menor ou igual ao Nível desse monstro e, depois, envie esse monstro para o Cemitério. \r\nVocê só pode usar o efeito de "Sirena Abisocea" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Continuar a Invocar por Invocação Especial?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28593329,'Anja Negra','Quando um monstro Fada seu for escolhido como alvo de um ataque: você pode oferecê-lo como Tributo e enviar este card da sua mão para o Cemitério e, depois, escolher 1 monstro com a face para cima que você controla; mude o alvo do ataque para seu monstro alvo e, se isso acontecer, até o final deste turno, ele ganha ATK igual ao ATK original do monstro oferecido como Tributo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28593363,'Tubarão das Profundezas do Mar','"Habitante das Profundezas" + "Tongyo"','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28596933,'Bater de Asas do Dragão Gigante','Devolva 1 monstro do Tipo Dragão de Nível 5 ou mais que você controla para a mão e, se isso acontecer, destrua todos os Cards de Magia e Armadilha no campo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28601770,'Arquidemônio da Névoa',replace(replace('Você pode Invocar este card por Invocação-Normal sem oferecer Tributo. \r\nUma vez por turno, durante a Fase Final, se este card foi Invocado desta forma: destrua este card e, se isso acontecer, sofra 1000 de dano.','\r',char(13)),'\n',char(10)),'Invocação Normal sem Tributo','Destrua e cause dano','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28604635,'Erradicar',replace(replace('Pague 500 PV. \r\nDestrua todos os monstros de Nível 3 com a face para cima em Posição de Ataque.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28617139,'Investida Simorgh',replace(replace('Descarte 1 monstro Besta Alada; adicione 2 monstros "Simorgh" com Atributos diferentes do seu Deck à sua mão. \r\nVocê pode banir este card do seu Cemitério; revele 1 monstro Besta Alada na sua mão e, se isso acontecer, pelo resto deste turno, reduza em 1 os Níveis dos monstros na sua mão com esse nome (mesmo depois que eles forem Invocados). \r\nVocê só pode ativar 1 "Investida Simorgh" por turno.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Reduzir o Nível','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28630501,'Yosenju Kama 3',replace(replace('Se este card for Invocado por Invocação-Normal, você pode: imediatamente depois de resolver este efeito, Invocar por Invocação-Normal 1 monstro "Yosenju" da sua mão, exceto "Yosenju Kama 3". \r\nQuando outro monstro "Yosenju" que você controla causar dano de batalha ao seu oponente: você pode adicionar 1 card "Yosenju" do seu Deck à sua mão, exceto "Yosenju Kama 3". \r\nVocê só pode usar este efeito de "Yosenju Kama 3" uma vez por turno. \r\nUma vez por turno, durante a Fase Final, se este card foi Invocado por Invocação-Normal neste turno: devolva-o para a mão.','\r',char(13)),'\n',char(10)),'Invocar','Procurar no Deck','Retornar à mão','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28637168,'Garça Guindaste',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode escolher 1 monstro de Nível 3 no seu Cemitério; Invoque o alvo por Invocação-Especial, mas negue seus efeitos. \r\nVocê só pode usar este efeito de "Garça Guindaste" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28642461,'Jokul K9-66a',replace(replace('Se seu oponente tiver 2 ou mais cards na mão dele, você pode Invocar este card por Invocação-Normal sem oferecer Tributo. \r\nVocê só pode usar cada um dos seguintes efeitos de "Jokul K9-66a" uma vez por turno. \r\nVocê pode revelar este card e 1 outro monstro de Nível 5 na sua mão; Invoque os dois por Invocação-Especial, mas eles não podem ser usados como matéria para a Invocação-Xyz de um monstro de LUZ. \r\nDurante sua Fase Principal: você pode adicionar 1 monstro "K9" não-Aqua do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Invocação Normal sem Tributo','Invocação Especial','Adicionar à mão','Invocado por Invocação Especial pelo efeito de "Jokul K9-66a"','','','','','','','','','','','','');
INSERT INTO texts VALUES(28643791,'Marcha para Ragnarok','Escolha 1 monstro "Aesir" que você controla; até o final deste turno, os efeitos dele são negados e, além disso, esse monstro com a face para cima não é afetado pelos efeitos de outras Magias/Armadilhas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28645123,'Desafio I.A.',replace(replace('Os monstros que seu oponente controla perdem 100 de ATK para cada card que você controla. \r\nSe um monstro "@Ignister" seu batalhar, seu oponente não pode ativar cards ou efeitos até o final da Etapa de Dano. \r\nQuando um monstro "@Ignister" seu for destruído em batalha: você pode escolher 1 outro monstro Ciberso com 2300 de ATK no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê só pode usar este efeito de "Desafio I.A." uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28649820,'Encarnação de Apophis','Durante a Fase Principal: Invoque este card por Invocação-Especial como um Monstro Normal (Réptil/TERRA/Nível 4/ATK 1600/DEF 1800) (este card ainda é considerado uma Armadilha).','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28651380,'Raviel, o Senhor dos Fantasmas - Destruidor Cintilante',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao oferecer 3 monstros como Tributo. \r\nVocê só pode usar cada um dos seguintes efeitos de "Raviel, o Senhor dos Fantasmas - Destruidor Cintilante" uma vez por turno.\r\n● (Efeito Rápido): você pode descartar este card e escolher 1 "Raviel, o Senhor dos Fantasmas" que você controla; pelo resto deste turno, seu ATK se torna o dobro do seu ATK atual e, além disso, ele pode atacar todos os monstros que seu oponente controla uma vez cada.\r\n● Se este card estiver no seu Cemitério: você pode oferecer 1 monstro como Tributo; adicione este card à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28653611,'Justiceiro Infernal',replace(replace('Ative 1 desses efeitos (mas você só pode usar cada efeito de "Justiceiro Infernal" uma vez por turno);\r\n● Adicione 1 monstro Dinossauro de ÁGUA do seu Deck à sua mão e, depois, você pode Invocá-lo por Invocação-Especial se seu oponente controlar um monstro.\r\n● Ofereça 1 monstro como Tributo; Invoque por Invocação-Especial 1 monstro de FOGO de Nível 6 ou mais da sua mão, do Deck ou do Cemitério, mas negue seus efeitos se for um monstro não-Demônio.','\r',char(13)),'\n',char(10)),'Ativar','Efeito de busca','Invocação Especial','Invocação Especial?','','','','','','','','','','','','');
INSERT INTO texts VALUES(28654932,'Buraco Armadilha Sombrio e Profundo',replace(replace('Quando um ou mais Monstros de Efeito de Nível 5 ou mais forem Invocados por Invocação-Especial: bana esse(s) \r\nMonstro(s) de Efeito de Nível 5 ou mais.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28669235,'Reino Ryu-Ge - Espirais Marítimos',replace(replace('Você só pode controlar 1 "Reino Ryu-Ge - Espirais Marítimos". \r\nSeus monstros "Ryu-Ge" não podem ser destruídos em batalha. \r\nMonstros Pêndulo "Ryu-Ge", e monstros de Nível 10 ou mais cujo Tipo original seja Serpente Marinha, que você controla, ganham este efeito.\r\n● Uma vez por turno do oponente (Efeito Rápido): você pode colocar 1 Magia Contínua "Ryu-Ge" que você controla no fundo do Deck e, depois, escolha 1 card no campo; devolva-o para a mão.','\r',char(13)),'\n',char(10)),'','Retornar um card no campo à mão (Reino Ryu-Ge - Espirais Marítimos)','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28674152,'Radian, o Kaiju Multidimensional',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) em Posição de Ataque no campo do seu oponente, ao oferecer como Tributo 1 monstro que ele controla. \r\nSe seu oponente controlar um monstro "Kaiju", você pode Invocar este card por Invocação-Especial (da sua mão) em Posição de Ataque. \r\nVocê só pode controlar 1 monstro "Kaiju". \r\nUma vez por turno: você pode remover 2 Marcadores Kaiju de qualquer parte do campo; Invoque por Invocação-Especial 1 "Ficha de Radian" (Demônio/TREVAS/Nível 7/ATK 2800/DEF 0), mas ela não pode ser usada como Matéria Sincro.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28674153,'Ficha de Radian','Invocado por Especial com o efeito "Radian, o Kaiju Multidimensional". Esta Ficha não pode ser usada como Matéria Sincro.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28677304,'Neos das Trevas, o HERÓI do Elemento',replace(replace('"Neos, o HERÓI do Elemento" + "Pantera Negra Neoespacial"	\r\nDeve primeiro ser Invocado por Invocação-Especial (do seu Deck Adicional) ao embaralhar os cards acima que você controla no Deck. \r\n(Você não usa "Polimerização"). \r\nSe este card não tiver escolhido um monstro com o efeito dele: Você pode escolher 1 Monstro de Efeito com a face para cima no campo; enquanto você controlar este card com a face para cima, o efeito do alvo no campo é negado. \r\nDurante a Fase Final: Embaralhe este card no Deck Adicional.','\r',char(13)),'\n',char(10)),'Retornar ao Deck','Negar o efeito','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28692962,'Mekk-Cavaleiro do Anoitecer Púrpura',replace(replace('Se 2 ou mais cards estiverem na mesma coluna, você pode Invocar este card por Invocação-Especial (da sua mão) nessa coluna. \r\nVocê só pode Invocar "Mekk-Cavaleiro do Anoitecer Púrpura" por Invocação-Especial uma vez por turno desta forma. \r\n(Efeito Rápido): você pode escolher 1 monstro "Mekk-Cavaleiro" que você controla; bana-o (até a Fase de Apoio do seu próximo turno) e, se isso acontecer, adicione 1 monstro "Mekk-Cavaleiro" do seu Deck à sua mão, exceto "Mekk-Cavaleiro do Anoitecer Púrpura". \r\nVocê só pode usar este efeito de "Mekk-Cavaleiro do Anoitecer Púrpura" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Retornar o monstro banido ao campo','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28711704,'Soldado do Lustro Negro Toon',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro deve ser Invocado por Invocação-Especial (da sua mão) ao oferecer como Tributo monstros Toon da sua mão ou do campo, cuja soma dos Níveis seja igual a 8 ou mais. \r\nEnquanto você controlar "Mundo Toon" e seu oponente não controlar nenhum monstro Toon, este card pode atacar diretamente. \r\nUma vez por turno, se você controlar "Mundo Toon": você pode escolher 1 card no campo; bana-o e, além disso, este card não pode atacar no turno em que este efeito for ativado.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28715905,'Ursártico Megapolar',replace(replace('Durante a Fase Principal (Efeito Rápido): você pode oferecer como Tributo 1 outro monstro de Nível 7 ou mais da sua mão; Invoque este card por Invocação-Especial da sua mão e, além disso, você não pode Invocar por Invocação-Especial pelo resto deste turno, exceto monstros com um Nível. \r\nSe este card for Invocado por Invocação-Especial enquanto você controlar outro monstro "Ursártico(a)": você pode escolher 1 Magia/Armadilha que seu oponente controla; destrua-a. \r\nVocê só pode usar cada efeito de "Ursártico Megapolar" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28720123,'Dinopoderoso Potente, o Dracossassino',replace(replace('Escala de Pêndulo = 6\r\n[ Efeito de Pêndulo ]\r\nVocê pode escolher 1 card "Dracossassino" ou "Dinonévoa" na sua outra Zona de Pêndulo; Invoque-o por Invocação-Especial. \r\nVocê só pode usar este efeito de "Dinopoderoso Potente, o Dracossassino" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\n(Este card deve ser sempre considerado como um card "Dinonévoa".)	\r\nSe este card for oferecido como Tributo: você pode adicionar 1 Monstro Pêndulo "Dracossassino" ou "Dinonévoa" com a face para cima do seu Deck Adicional à sua mão, exceto "Dinopoderoso Potente, o Dracossassino". \r\nVocê só pode usar este efeito de "Dinopoderoso Potente, o Dracossassino" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28725004,'Sabedoria Corrompida','Se este card em Posição de Ataque for colocado em Posição de Defesa com a face para cima: embaralhe seu Deck.','Embaralhar o Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28736826,'Rei Supremo do Home Run do Beisebol','Quando este card destruir um monstro do oponente em batalha: Você pode fazer com que este card ganhe 1000 de ATK.','Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28741524,'Poço de Poder Telecinético',replace(replace('Invoque por Invocação-Especial qualquer número de monstros do Tipo Psíquico de Nível 2 ou menos do seu Cemitério. \r\nVocê sofre dano igual à soma dos Níveis desses monstros x 300.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28754338,'Tridão Lendário Atlante','Você pode oferecer como Tributo este card e 1 monstro do Tipo Serpente Marinha; Invoque por Invocação-Especial 1 "Poseidra, o Dragão Atlante" da sua mão ou Deck e, depois, todos os monstros que seu oponente controla atualmente perdem 300 de ATK.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28762303,'Gelojade Tinola',replace(replace('Você pode enviar 1 card da sua mão para o Cemitério e, depois, escolha 1 monstro de ÁGUA no seu Cemitério; envie este card do campo para o Cemitério e, se isso acontecer, Invoque por Invocação-Especial o monstro escolhido como alvo. \r\nSe um ou mais monstros de ÁGUA com a face para cima que você controla forem destruídos em batalha ou por um efeito de card, enquanto este card estiver no seu Cemitério: você pode banir este card; Invoque por Invocação-Especial 1 monstro "Gelojade" da sua mão ou do Cemitério, exceto "Gelojade Tinola". \r\nVocê só pode usar cada efeito de "Gelojade Tinola" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28770951,'Clérigo das Galáxias',replace(replace('Se este card estiver na sua mão: você pode escolher 1 Monstro Xyz "Fóton" ou "Galáxia" que você controla; associe este card a ele como matéria. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode escolher 5 cards "Fóton" e/ou "Galáxia" com nomes diferentes no seu Cemitério; embaralhe-os no Deck e, depois, compre 2 cards. \r\nVocê só pode usar 1 efeito de "Clérigo das Galáxias" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28776350,'Mago Akáshico',replace(replace('2 monstros com o mesmo Tipo, exceto Fichas	\r\nVocê só pode Invocar um ou mais "Mago Akáshico" por Invocação-Link uma vez por turno. \r\nSe este card for Invocado por Invocação-Link: devolva para a mão todos os monstros para os quais este card apontar. \r\nUma vez por turno: você pode declarar o nome de 1 card; escave cards do topo do seu Deck igual à soma das Valores Link de todos os Monstros Link co-linkados a este card e, depois, se você escavou qualquer cópia do card declarado, adicione-os à sua mão e, além disso, envie os cards restantes para o Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28781003,'Cavaleiro Raptor',replace(replace('2 monstros de TREVAS de Nível 4	\r\n(Este card deve ser sempre considerado como um card "Os Cavaleiros Fantasmas" e "Ataqueraptor".)	\r\nVocê pode desassociar 1 matéria deste card; Invoque por Invocação-Especial do seu Deck Adicional, 1 Monstro Xyz "Os Cavaleiros Fantasmas", "Ataqueraptor" ou "Dragão Xyz" que seja 1 Classe maior ou menor que este card, usando este card com a face para cima que você controla como matéria, mas destrua-o durante a próxima Fase Final do seu oponente (isso é considerado uma Invocação-Xyz, transfira as matérias deste card). \r\nVocê só pode usar este efeito de "Cavaleiro Raptor" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28798938,'Dois Avatares - A-Un Manifestado',replace(replace('2 monstros "Dois Avatares"	\r\nEste card ganha o(s) seguinte(s) efeito(s), de acordo com os nomes originais das matérias usadas para sua Invocação-Fusão.\r\n● "Dois Avatares - Kon-Gyo Edificado": O ATK dos seus monstros "Dois Avatares" que estiverem batalhando se torna 3000 apenas durante o cálculo de dano.\r\n● "Dois Avatares - Mitsu-Jaku Edificado": Uma vez por turno do oponente (Efeito Rápido): você pode escolher 1 card no campo; bana-o.	\r\nSe este card Invocado por Invocação-Fusão for destruído: você pode Invocar por Invocação-Especial 1 "Punhos dos Dois Avatares - Yuhi" e 1 "Pés dos Dois Avatares - Kokoku" do seu Deck e, se isso acontecer, eles não podem ser destruídos em batalha ou por efeitos de card neste turno.','\r',char(13)),'\n',char(10)),'Usar "Dois Avatares - Kon-Gyo Edificado" como Matéria de Fusão','Usar "Dois Avatares - Mitsu-Jaku Edificado" como Matéria de Fusão','','O efeito de "Dois Avatares - A-Un Manifestado" está sendo aplicado.','','','','','','','','','','','','');
INSERT INTO texts VALUES(28803166,'Lacrima, as Lágrimas Carmesim',replace(replace('(Este card deve ser sempre considerado como um card "Criademônio".)	\r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode enviar 1 card "Criademônio" do seu Deck para o Cemitério, exceto "Lacrima, as Lágrimas Carmesim". \r\nDurante o turno do seu oponente, se este card estiver no seu Cemitério (Efeito Rápido): você pode escolher 1 Monstro Link "Criademônio" no seu Cemitério; embaralhe este card no Deck e, se isso acontecer, Invoque esse monstro por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Lacrima, as Lágrimas Carmesim" uma vez por turno.','\r',char(13)),'\n',char(10)),'Enviar para o Cemitério','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28806532,'Pintor do Clima Nuvem',replace(replace('Se outro card "do Clima" com a face para cima que você controla for enviado para o Cemitério: você pode escolher até 2 Magias/Armadilhas "do Clima" no seu Cemitério; coloque-os com a face para cima na sua Zona de Magias & Armadilhas. \r\nVocê só pode usar este efeito de "Pintor do Clima Nuvem" uma vez por turno. \r\nUma vez por turno, durante a Fase de Apoio do turno seguinte ao qual este card foi banido do campo para ativar um efeito de card "do Clima": você pode Invocar este card banido por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Baixar um Card de Magia/Armadilha "do Clima" do seu Cemitério','Invoque este card banido por Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28827503,'Linkado ao VRAINS!',replace(replace('Invoque por Invocação-Especial 1 monstro da sua mão, mas negue seus efeitos e, depois, imediatamente depois que este efeito resolver, Invoque por Invocação-Link 1 Monstro Link usando monstros que você controla como matéria, incluindo esse monstro. \r\nEssa Invocação-Link não pode ser negada e, além disso, seu oponente não pode ativar cards ou efeitos quando um monstro é Invocado por Invocação-Link desta forma. \r\nSe um ou mais Monstros Link que você controla forem destruídos em batalha ou por um efeito de card enquanto este card estiver no seu Cemitério: você pode banir este card; adicione 1 monstro do seu Cemitério à sua mão com o mesmo Tipo original que 1 desses monstros destruídos. \r\nVocê só pode ativar 1 "Linkado ao VRAINS!" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28859794,'Asa Escudo','Duas vezes por turno, este card não pode ser destruído em batalha.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28865322,'Éter, o Maligno Dragão Edificante',replace(replace('Escala de Pêndulo = 4\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno: você pode banir 1 "Guerreiro(a) Edificado(a)" do seu Cemitério e, depois, escolher 1 card no campo; destrua-o.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nQuando este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 monstro no campo; bana-o.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28868394,'Armadilhatrix Vesículo',replace(replace('Não é afetado pelos efeitos de Armadilhas Normais "Buraco". \r\nVocê só pode usar 1 dos seguintes efeitos de "Armadilhatrix Vesículo" por turno e apenas uma vez por turno. \r\nVocê pode enviar para o Cemitério 1 Armadilha Baixada que você controla; Invoque este card por Invocação-Especial da sua mão. \r\nSe você não controlar nenhum card na sua Zona de Magias & Armadilhas: você pode banir este card do seu Cemitério e, depois, escolha 1 Armadilha Normal "Buraco" no seu Cemitério; Baixe-a no seu campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28877100,'Táticas de Defesa',replace(replace('Se você controlar um monstro "Besta Gladiadora" com a face para cima: Pelo resto deste turno, monstros que você controla não podem ser destruídos em batalha, e qualquer Dano de Batalha que você sofrer é reduzido a 0. \r\nDepois que este card resolver, coloque-o no fundo do seu Deck.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28877382,'DoomZ V Cinco - Amalthe',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial, ou destruído por um efeito de card: você pode adicionar 1 monstro "DoomZ" do seu Deck à sua mão, exceto "DoomZ V Cinco - Amalthe". \r\nEnquanto este card estiver equipado com um Card de Equipamento (Efeito Rápido): você pode Invocar por Invocação-Especial 1 Monstro Xyz Máquina de VENTO do seu Deck Adicional com a mesma Classe que o Nível deste card e, se isso acontecer, associe este card e seus Cards de Equipamento a esse monstro como matéria (isso é considerado uma Invocação-Xyz). \r\nVocê só pode usar cada efeito de "DoomZ V Cinco - Amalthe" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Invocação Xyz','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28877602,'Evoltil Odonto','Quando este card for Invocado por Invocação-Normal: Você pode Invocar por Invocação-Especial 1 monstro "Evolssauro" da sua mão.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28884172,'Invocador Gagaga',replace(replace('Uma vez por turno: você pode escolher 1 monstro "Gagaga" no seu Cemitério, exceto "Invocador Gagaga"; Invoque-o por Invocação-Especial e, além disso, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros "Gagaga". \r\nSe este card for desassociado de um Monstro Xyz e enviado para o Cemitério para ativar um efeito desse monstro: você pode escolher 1 Monstro Xyz com a face para cima que você controla; ele ganha 500 de ATK até o final deste turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Aumentar ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28890974,'Transformação Celestial',replace(replace('Invoque por Invocação-Especial 1 monstro Fada da sua mão. \r\nO ATK desse monstro é diminuído pela metade e, além disso, ele é destruído durante a Fase Final.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28903523,'Luz do Sol Eterna',replace(replace('Monstros que você controla ganham 500 de DEF para cada "Dragão Fada Antigo", e monstros que o mencionem, que você controla. \r\nUma vez por Corrente: você pode escolher 1 monstro com a face para cima que seu oponente controla; até o final deste turno, seu ATK/DEF são diminuídos pela metade e, além disso, seus efeitos são negados. \r\nVocê pode usar este efeito de "Luz do Sol Eterna" um número de vezes por turno, até o número de "Dragão Fada Antigo" e monstros que o mencionem que você controla.','\r',char(13)),'\n',char(10)),'','Negar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28904860,'Bastião de Anjoléquia',replace(replace('1 Regulador + 1+ não-Reguladores	\r\nVocê pode escolher 1 outro card na coluna deste card; bana-o. \r\nSe este card for colocado na Zona de Magias & Armadilhas como uma Magia Contínua: você pode colocar 1 "Shatranga de Anjoléquia" do seu Deck Adicional na sua Zona de Magias & Armadilhas como uma Magia Contínua com a face para cima. \r\nVocê só pode usar cada um dos efeitos anteriores de "Bastião de Anjoléquia" uma vez por turno. \r\nEnquanto este card for considerado como uma Magia Contínua, outros cards "Anjoléquia" no campo não podem ser destruídos pelos efeitos de card do seu oponente.','\r',char(13)),'\n',char(10)),'Efeito de banimento','Efeito de colocar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28912357,'Engrenagem Gigante X',replace(replace('2 monstros Máquina de Nível 4	\r\nUma vez por turno: você pode desassociar 1 matéria deste card; adicione 1 monstro Máquina de Nível 4 ou menos do seu Deck ou Cemitério à sua mão. \r\nQuando este card com a face para cima deixar o campo: você pode escolher 1 monstro "Engrenagi" de Nível 3 ou menos no seu Cemitério; Invoque o alvo por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28927782,'Legião Dragunidade',replace(replace('Você pode ativar 1 desses efeitos, mas você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros "Dragunidade".\r\n● Escolha 1 Card de Monstro "Dragunidade" na sua Zona de Magias & Armadilhas; Invoque-o por Invocação-Especial em Posição de Defesa.\r\n● Escolha 1 monstro "Dragunidade" que você controla; equipe o alvo com 1 monstro "Dragunidade" do seu Cemitério.	\r\nVocê só pode usar este efeito de "Legião Dragunidade" uma vez por turno.','\r',char(13)),'\n',char(10)),'Usar o efeito agora?','Invocação Especial','Equipar','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28929131,'Zaphion, o Senhor do Tempo',replace(replace('Não pode ser Invocado por Invocação-Especial do Deck. \r\nSe você não controlar nenhum monstro, você pode Invocar este card por Invocação-Normal sem oferecer Tributo. \r\nNão pode ser destruído em batalha ou por efeitos de card. \r\nVocê não sofre dano de batalha dos ataques que envolvem este card. \r\nNo final da Fase de Batalha, se este card batalhou: embaralhe todas as Magias e Armadilhas do seu oponente no Deck. \r\nSe este card for enviado do campo para o Cemitério: você pode comprar 1 card. \r\nUma vez por turno, durante sua Fase de Apoio: embaralhe este card no Deck.','\r',char(13)),'\n',char(10)),'Invocação Normal sem Tributo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28933734,'Máscara da Escuridão','VIRE: Escolha 1 Armadilha no seu Cemitério; adicione o alvo à sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28954097,'Cavaleiro da Espada Espelhado',replace(replace('Se este card batalhar um monstro, nenhum dos dois pode ser destruído nessa batalha. \r\nVocê só pode usar cada um dos seguintes efeitos de "Cavaleiro da Espada Espelhado" uma vez por turno. \r\n(Efeito Rápido): você pode oferecer este card como Tributo; Invoque por Invocação-Especial 1 monstro do seu Deck que mencione "Fusão Quimera", exceto "Cavaleiro da Espada Espelhado". \r\nQuando um monstro que seu oponente controla ativar seu efeito, enquanto você controlar "Quimera, a Besta Mística Voadora" (Efeito Rápido): você pode banir este card do seu campo ou Cemitério; negue o efeito.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial do Deck','Negue o efeito do seu oponente','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28957126,'Olho Maligno de Gorgoneio',replace(replace('Só pode ser equipado a um monstro "Olho Maligno". \r\nVocê só pode ativar 1 "Olho Maligno de Gorgoneio" por turno. \r\nO nome deste card se torna "Olho Maligno de Selene" enquanto estiver na Zona de Magias & Armadilhas. \r\nEnquanto seus PV forem menores que os do seu oponente, o monstro equipado ganha ATK igual à diferença. \r\nVocê pode banir este card do seu Cemitério e descartar 1 card "Olho Maligno"; adicione 1 Magia/Armadilha "Olho Maligno" do seu Deck à sua mão, exceto "Olho Maligno de Gorgoneio". \r\nVocê só pode usar este efeito de "Olho Maligno de Gorgoneio" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28958464,'Card de Magia "Reviver Monstro"',replace(replace('Escolha 1 monstro em qualquer Cemitério; Invoque-o por Invocação-Especial no seu campo, mas pelo resto deste turno, ele não pode atacar e nenhum duelista pode ativar seus efeitos. \r\nVocê só pode ativar 1 "Card de Magia "Reviver Monstro"" por turno.','\r',char(13)),'\n',char(10)),'','Invocado por Invocação Especial pelo efeito de "Reviver Monstro"; não pode atacar e não pode ativar seus efeitos.','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28966434,'Mago Solitário',replace(replace('Uma vez por turno, você pode selecionar 1 monstro "Senhora Fortuna" com a face para cima que você controla e 1 outro monstro com a face para cima no campo. \r\nReduza o Nível do monstro "Senhora Fortuna" selecionado em 3, e destrua o outro monstro selecionado.','\r',char(13)),'\n',char(10)),'Destruir','Escolha o monstro cujo Nível será reduzido','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28968609,'Golem de Lixo',replace(replace('Se você controla um monstro com 0 de ATK ou DEF: você pode Invocar por Invocação-Especial este card da sua mão.\r\nVocê pode revelar 3 Monstros Xyz com Classes diferentes no seu Deck Adicional, então escolha 1 outro card no campo; destrua ambos ele e este card.\r\nVocê pode banir este card do seu Cemitério; desassocie 1 matéria de um monstro que você controla, então você pode Invocar por Invocação-Especial 1 monstro com 0 de ATK ou DEF da sua mão ou Cemitério.\r\nVocê só pode usar cada um dos efeitos de "Golem de Lixo" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Efeito de destruição','Desassociar Matéria Xyz','Invocação Especial?','','','','','','','','','','','','');
INSERT INTO texts VALUES(28981598,'Gato de Nove Vidas',replace(replace('2 monstros de Nível 9	\r\nSeu oponente não pode escolher outros monstros que você controla que foram Invocados por Invocação-Especial do Cemitério como alvo de efeitos de card. \r\nVocê pode desassociar 1 matéria deste card e, depois, escolha 1 monstro de Nível 9 no seu Cemitério ou 1 monstro no Cemitério do seu oponente; Invoque-o por Invocação-Especial. \r\nVocê só pode usar este efeito de "Gato de Nove Vidas" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28985331,'Cavaleiro do Armagedom','Quando este card for Invocado: você pode enviar 1 monstro de TREVAS do seu Deck para o Cemitério.','Enviar 1 monstro de TREVAS do Deck para o Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28990150,'Cérbero de Fóton','Durante o turno em que este card foi Invocado por Invocação-Normal, nenhum duelista pode ativar Cards de Armadilha enquanto este card estiver com a face para cima no campo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29013526,'Wynn Tempestuosa','Uma vez por turno: você pode oferecer como Tributo 1 outro monstro de VENTO; Invoque por Invocação-Especial 1 monstro de VENTO da sua mão, mas destrua-o quando um "Wynn Tempestuosa" com a face para cima que você controla deixar o campo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29021114,'Dispositivo de Prata',replace(replace('Quando este card for Invocado por Invocação-Normal ou Especial: você pode Invocar por Invocação-Especial 1 monstro Máquina de Nível 4 da sua mão. \r\nSe este card for destruído em batalha ou por um efeito de card: você pode Invocar por Invocação-Especial 1 monstro "Dispositivo" de Nível 4 do seu Deck, exceto "Dispositivo de Prata". \r\nVocê só pode usar 1 efeito de "Dispositivo de Prata" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29047353,'Palco no Aquário',replace(replace('Monstros de ÁGUA que você controla não podem ser destruídos em batalha com monstros que não são de ÁGUA. \r\nMonstros "Aquatriz" que você controla não são afetados pelos efeitos de monstro do seu oponente. \r\nSe este card for enviado do campo para o Cemitério: você pode escolher 1 monstro Aqua no seu Cemitério; Invoque-o por Invocação-Especial e, além disso, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros Aqua.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29053656,'Dragão Carmesim Quetzacoatl',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nGanha ATK igual ao ATK original total de todos os oustros Monstros Sincro que você controla.\r\nVocê só pode usar cada um dos seguintes efeitos de "Dragão Carmesim Quetzacoatl" uma vez por turno.\r\nSe este card for Invocado por Invocação-Sincro: você pode Invocar quantos Monstros Sincro de Dragão do seu Cemitério possível por Invocação-Especial, você também não pode Invocar por Invocação-Especial pelo resto deste turno.\r\nQuando seu oponente ativar um efeito de monstro (Efeito Rápido): você pode retornar 1 outro Monstro Sincro de Dragão que você controla para o Deck Adicional, e se fizer, negue aquela ativação.','\r',char(13)),'\n',char(10)),'Invocação Especial','Negar a ativação','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29053657,'Dragão Carmesim Quetzacoatl',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nGanha ATK igual ao ATK original total de todos os oustros Monstros Sincro que você controla.\r\nVocê só pode usar cada um dos seguintes efeitos de "Dragão Carmesim Quetzacoatl" uma vez por turno.\r\nSe este card for Invocado por Invocação-Sincro: você pode Invocar quantos Monstros Sincro de Dragão do seu Cemitério possível por Invocação-Especial, você também não pode Invocar por Invocação-Especial pelo resto deste turno.\r\nQuando seu oponente ativar um efeito de monstro (Efeito Rápido): você pode retornar 1 outro Monstro Sincro de Dragão que você controla para o Deck Adicional, e se fizer, negue aquela ativação.','\r',char(13)),'\n',char(10)),'Invocação Especial','Negar a ativação','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29054481,'Vigia do Vale das Névoas','Descendente de uma família que serve como vigia do Vale das Névoas através das gerações. Nunca deixou de observar uma única coisa que aconteceu no vale, não importa quão pequena.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29062925,'Fusão das Figuras',replace(replace('Invoque por Invocação-Fusão 1 Monstro de Fusão Guerreiro de LUZ do seu Deck Adicional, usando monstros da sua mão ou do campo como Matéria de Fusão. \r\nSe você controlar "O Cavaleiro da Rainha", "O Cavaleiro do Rei" ou "O Cavaleiro do Valete", você pode usar 1 monstro do seu Deck como Matéria de Fusão. \r\nVocê só pode ativar 1 "Fusão das Figuras" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29071332,'Braço Arsenal',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nUma vez por turno, você pode: escolher 1 monstro no campo; equipe este card no alvo, OU: desequipe este card e Invoque-o por Invocação-Especial em Posição de Ataque. \r\nEnquanto estiver equipado por este efeito, o alvo ganha 1000 de ATK. \r\nSe o alvo destruir um monstro em batalha e enviá-lo para o Cemitério: cause dano ao seu oponente igual ao ATK original do monstro destruído.','\r',char(13)),'\n',char(10)),'Equipar a um monstro como um Card de Equipamento','Desequipar e Invocar por Invocação Especial','Causar dano ao seu oponente','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29081251,'Hublot, o Diretório Escuro da Morte',replace(replace('Você pode Invocar por Invocação-Normal este card sem oferecer Tributo.\r\nVocê só pode usar cada um dos seguintes efeitos de "Hublot, o Diretório Escuro da Morte" uma vez por turno.\r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode enviar 1 monstro Zumbi de Nível 6 ou maior do seu Deck ao Cemitério, exceto "Hublot, o Diretório Escuro da Morte", então você pode adicionar 1 monstro Zumbi de Nível 6 ou maior do seu Cemitério à sua mão.\r\nSe um ou mais monstros é Invocado por Invocação-Especial do seu Cemitério enquanto este card está na Zona de Monstros, você pode: imediatamente após ativar este efeito, Invocar por Invocação-Xyz 1 Monstro Xyz Zumbi.','\r',char(13)),'\n',char(10)),'Invocação Normal sem Tributo','Enviar para o Cemitério','Invocação Xyz','Adicionar à mão?','','','','','','','','','','','','');
INSERT INTO texts VALUES(29085954,'Número 78: Arquivo de Números',replace(replace('2 monstros de Nível 1	\r\nUma vez por turno (Efeito Rápido): você pode desassociar 1 matéria deste card; seu oponente seleciona aleatoriamente 1 card no seu Deck Adicional e se for um monstro "Número" com um número entre "1" e "99" em seu nome, Invoque-o por Invocação-Especial usando este card com a face para cima que você controla como matéria, mas bana esse monstro durante a Fase Final e, além disso, você não pode Invocar por Invocação-Especial pelo resto deste turno. \r\n(Isso é considerado uma Invocação-Xyz. Transfira as matérias dele para o monstro Invocado.)','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29087919,'Mudar Engrenagi',replace(replace('Escolha 2 ou mais monstros "Engrenagiano" com nomes diferentes no seu Cemitério; Invoque-os por Invocação-Especial. \r\nImediatamente depois que este card resolver, Invoque por Invocação-Xyz 1 Monstro Xyz usando todos os monstros Invocados (mas nenhum outro monstro) como Matérias. \r\nVocê só pode ativar 1 "Mudar Engrenagi" por turno.','\r',char(13)),'\n',char(10)),'Invocar outro monstro "Engrenagiano"?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29088922,'Senhora Fortuna da Água',replace(replace('O ATK/DEF deste card se tornam seu Nível x 300. \r\nUma vez por turno, durante sua Fase de Apoio: aumente em 1 o Nível deste card (máx. 12). \r\nSe este card for Invocado por Invocação-Especial enquanto você controlar um monstro "Senhora Fortuna" exceto "Senhora Fortuna da Água": compre 2 cards.','\r',char(13)),'\n',char(10)),'Aumentar o Nível','Comprar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29092121,'Biplano Críptico',replace(replace('Uma vez por turno: você pode escolher 2 monstros "Críptico(a)" que você controla; o Nível deles se torna 8 até o final deste turno. \r\nVocê só pode usar cada um dos seguintes efeitos de "Biplano Críptico" uma vez por turno. \r\nSe um ou mais monstros "Críptico(a)" forem Invocados por Invocação-Normal ou Especial no seu campo (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe este card for destruído em batalha ou por um efeito de card e enviado para o Cemitério: você pode banir este card do seu Cemitério; adicione 1 monstro "Críptico(a)" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29095457,'Feixe de Perfuração Primita',replace(replace('Revele 1 card "Primita", ou 1 Monstro Normal, na sua mão, exceto "Feixe de Perfuração Primita" (ou, se você controlar um Monstro Normal ou um monstro "Primita" de Nível 5 ou mais, exceto uma Ficha, você pode ativar este efeito sem revelar um card) e, depois, escolha 1 card com a face para cima no campo; negue seus efeitos e, se isso acontecer, bana-o. \r\nDurante sua Fase Principal, se você controlar um monstro "Primita": você pode Baixar este card do seu Cemitério. \r\nVocê só pode usar cada efeito de "Feixe de Perfuração Primita" uma vez por turno.','\r',char(13)),'\n',char(10)),'Revelar um card para ativar?','Baixar este card','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29095552,'Ácido, o HERÓI Mascarado',replace(replace('Deve ser Invocado por Invocação-Especial com "Mudar a Máscara". 	\r\nQuando este card for Invocado por Invocação-Especial: destrua tantas Magias e Armadilhas que seu oponente controla quanto possível e, se isso acontecer, todos os monstros que ele controla perdem 300 de ATK.','\r',char(13)),'\n',char(10)),'Destruir Magias/Armadilhas','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29099860,'Gouki Máquina Suprex',replace(replace('Você pode revelar este card e 1 monstro "Gouki" na sua mão; Invoque os dois monstros por Invocação-Especial, mas, para cada um, enquanto ele permanecer com a face para cima na sua Zona de Monstros, você não pode Invocar por Invocação-Especial, exceto monstros "Gouki". \r\nSe este card for enviado do campo para o Cemitério: você pode adicionar 1 card "Gouki" do seu Deck à sua mão, exceto "Gouki Máquina Suprex". \r\nVocê só pode usar cada efeito de "Gouki Máquina Suprex" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Adicionar à mão','Revelado pelo efeito de "Gouki Máquina Suprex"','Invocado por Invocação Especial pelo efeito de "Gouki Máquina Suprex"','','','','','','','','','','','','');
INSERT INTO texts VALUES(29107423,'Bruxa da Rosa Escarlate',replace(replace('Você pode oferecer este card como Tributo; adicione 1 "Bruxa da Rosa Negra" do seu Deck à sua mão e, se isso acontecer, pegue 1 monstro Planta de Nível 3 ou menos do seu Deck e coloque-o no topo do seu Deck e, depois, imediatamente depois que este efeito resolver, você pode Invocar por Invocação-Normal 1 "Bruxa da Rosa Negra" da sua mão. \r\nVocê pode banir este card do seu Cemitério; devolva para o Deck Adicional 1 dos seus "Dragão da Rosa Negra" ou "Dragão da Rosa Escarlate" que estiverem banidos ou no seu Cemitério. \r\nVocê só pode usar cada efeito de "Bruxa da Rosa Escarlate" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Escolha o(s) card(s) para colocar no topo do Deck','Invocar "Bruxa da Rosa Negra"?','','','','','','','','','','','','');
INSERT INTO texts VALUES(29111045,'Grande Fuga Motoqueiro Goblin',replace(replace('Ofereça 1 monstro como Tributo; Invoque por Invocação-Especial 1 monstro "Goblin" do seu Deck, mas ele não pode atacar neste turno. \r\nQuando um monstro declarar um ataque: você pode banir este card do seu Cemitério e desassociar qualquer número de matérias de Monstros Xyz "Goblin" que você controla; todos os monstros que seu oponente controla atualmente perdem 1000 de ATK para cada matéria desassociada, até o final deste turno. \r\nVocê só pode usar cada efeito de "Grande Fuga Motoqueiro Goblin" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Reduzir ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29114773,'Velocidaroide Raspar',replace(replace('Envie 1 card "Velocidaroide" da sua mão para o Cemitério; adicione 1 monstro "Velocidaroide" do seu Deck à sua mão. \r\nVocê só pode ativar 1 "Velocidaroide Raspar" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29116732,'Amanhecedor','Quando este card for Invocado por Invocação-Especial: você pode Invocar 1 "Amanhecedor" por Invocação-Especial da sua mão.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29139104,'Avalanche Aussa',replace(replace('Uma vez por turno, você pode oferecer como Tributo 1 monstro de TERRA (Exceto este card) para Invocar por Invocação-Especial 1 monstro de TERRA da sua mão. \r\nO monstro Invocado por Invocação-Especial por este efeito é destruído se "Avalanche Aussa" for removido do seu lado do campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29143457,'Formação de Fogo - Ingen',replace(replace('Quando este card for ativado: você pode Invocar por Invocação-Fusão 1 Monstro de Fusão Besta-Guerreira do seu Deck Adicional, usando monstros da sua mão ou do campo como Matéria de Fusão. \r\nSe este card com a face para cima for enviado da Zona de Magias & Armadilhas para o Cemitério: você pode escolher 1 monstro "Punho de Fogo" no seu Cemitério; adicione-o à sua mão. \r\nVocê só pode usar este efeito de "Formação de Fogo - Ingen" uma vez por turno. \r\nVocê só pode ativar 1 "Formação de Fogo - Ingen" por turno.','\r',char(13)),'\n',char(10)),'','Invocação Fusão?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29143726,'Samsara, Dragão do Renascimento',replace(replace('1 Regulador + 1 ou mais monstros não-Reguladores	\r\nSe este card for destruído em batalha e enviado para o Cemitério ou se este card que você controla for enviado para o seu Cemitério por um efeito de card do oponente: você pode escolher 1 monstro no Cemitério de qualquer duelista, exceto "Samsara, Dragão do Renascimento"; Invoque-o por Invocação-Especial. \r\nVocê só pode usar este efeito de "Samsara, Dragão do Renascimento" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29146185,'Mundo da Profecia',replace(replace('Quando este card for Invocado por Invocação-Especial pelo efeito de um monstro do Tipo Mago ou um Card de Magia "Livro de Magia": você pode escolher 2 Cards de Magia "Livro de Magia" no seu Cemitério; adicione esses alvos à sua mão. \r\nDurante o turno em que ativar este efeito, você não pode Invocar nenhum outro monstro por Invocação-Especial. \r\nQuando você adicionar card(s) à sua mão por meio deste efeito: você pode revelar 4 Cards de Magia "Livros de Magia" com nomes diferentes na sua mão; destrua todos os outros cards no campo.','\r',char(13)),'\n',char(10)),'Retornar à mão','Destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29155212,'Pumpking, o Rei dos Fantasmas',replace(replace('Ganha 100 de ATK/DEF enquanto "Castelo das Ilusões Sombrias" estiver no campo. \r\nAlém disso, durante sua Fase de Apoio, se "Castelo das Ilusões Sombrias" estiver no campo: este card ganha 100 de ATK/DEF. \r\nEste efeito é ativado uma vez por turno, por quatro das suas Fases de Apoio (contando esta como a primeira). "Castelo das Ilusões Sombrias" deve estar no campo para ativar e resolver este efeito. \r\nSe "Castelo das Ilusões Sombrias" não estiver no campo, este ganho de ATK/DEF desaparece e este efeito reinicia.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29155213,'Pumpking, o Rei dos Fantasmas',replace(replace('Ganha 100 de ATK/DEF enquanto "Castelo das Ilusões Sombrias" estiver no campo. \r\nAlém disso, durante sua Fase de Apoio, se "Castelo das Ilusões Sombrias" estiver no campo: este card ganha 100 de ATK/DEF. \r\nEste efeito é ativado uma vez por turno, por quatro das suas Fases de Apoio (contando esta como a primeira). "Castelo das Ilusões Sombrias" deve estar no campo para ativar e resolver este efeito. \r\nSe "Castelo das Ilusões Sombrias" não estiver no campo, este ganho de ATK/DEF desaparece e este efeito reinicia.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29157292,'Ilusionista Metálico',replace(replace('Aumente o Nível deste card em 4 apenas durante o turno do seu oponente. \r\nVocê só pode usar cada um dos seguintes efeitos de "Ilusionista Metálico" uma vez por turno. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode Baixar 1 Armadilha "Metalmorfe" do seu Deck e, depois, se "Metalmorfe Máximo" estiver no seu Cemitério, você pode comprar 1 card. \r\nVocê pode declarar 1 outro Tipo de Monstro; este card se torna desse Tipo até o final do turno do seu oponente.','\r',char(13)),'\n',char(10)),'Baixar uma Armadilha "Metalmorfe"','Alterar o Tipo','Comprar 1 card?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29169993,'Camarartista Gangorra',replace(replace('Na primeira vez que este card Invocado por Invocação-Especial seria destruído em batalha a cada turno, ele não é destruído. \r\nUma vez por turno, durante a Fase Final do seu oponente: você pode escolher 1 monstro "Camarartista" de Nível 3 ou menos no seu Cemitério; envie este card para o Cemitério e, se isso acontecer, adicione esse monstro à sua mão. \r\nSe um monstro "Camarartista" for enviado da mão para o seu Cemitério (exceto durante a Etapa de Dano), enquanto este card estiver no seu Cemitério: você pode Invocar este card por Invocação-Especial. \r\nVocê só pode usar este efeito de "Camarartista Gangorra" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29172562,'Ogre de Aço da Gruta nº 1','Um ídolo de aço adorado na Terra das Máquinas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29177818,'Garota da Rosa',replace(replace('Se um ou mais monstros Planta com a face para cima que você controla forem enviados para o Cemitério (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe um monstro Planta estiver no campo e este card estiver no seu Cemitério: você pode adicionar este card à sua mão. \r\nVocê só pode usar 1 efeito de "Garota da Rosa" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29185231,'Disparo Parta','No final da Fase de Batalha: essa se torna a Fase Final deste turno.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29189613,'Jardinagem Aromági',replace(replace('Se você Invocar um ou mais monstros "Aromági" por Invocação-Normal ou Especial (exceto durante a Etapa de Dano): você pode ganhar 1000 PV. \r\nQuando um monstro do oponente declarar um ataque, enquanto seus PV forem menores que os do seu oponente: você pode Invocar por Invocação-Especial 1 monstro "Aromági" do seu Deck. \r\nVocê só pode usar cada efeito de "Jardinagem Aromági" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29208536,'Número 45: Logos Destroçador, o Profeta da Demolição',replace(replace('2+ monstros de Nível 2	\r\nUma vez por turno: você pode desassociar 1 matéria deste card e, depois, escolha 1 outro card com a face para cima no campo; enquanto este monstro estiver com a face para cima no campo, os efeitos do alvo são negados. \r\nEnquanto o alvo estiver no campo, cards com o mesmo nome que o do alvo, e seus efeitos, não podem ser ativados.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29216198,'Orbe Gravítica','VIRE: Mude as posições de batalha de todos os monstros com a face para cima que seu oponente controla.','Mudar a posição de batalha','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29216967,'Engenhoca Marionete Braços de Tesoura','Quando este card for Invocado por Invocação-Normal: você pode enviar 1 monstro "Engenhoca Marionete" do seu Deck para o Cemitério.','Enviar para o Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29223325,'Artefato Ignição',replace(replace('Se você tiver um monstro "Artefato" no seu Deck: escolha 1 Magia/Armadilha no campo; destrua o alvo e, se isso acontecer, Baixe 1 monstro "Artefato" do seu Deck em uma Zona de Magias & Armadilhas sua como uma Magia. \r\nSe este card em posse do seu dono for destruído por um card do oponente: seu oponente pula sua Próxima Fase de Batalha.','\r',char(13)),'\n',char(10)),'Pular a Battle Phase','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29228350,'Laser do Dragão','Envie 1 "Trigon" equipado a um "Delta Tri" com a face para cima que você controla ao Cemitério e destrua todos os monstros que seu oponente controla.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29228529,'Reprodução de Magias','Envie 2 Magias da sua mão para o Cemitério e, depois, escolha 1 Magia no seu Cemitério; adicione-a à sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29246354,'Crisálida de Musguinho','Você pode oferecer este card como Tributo enquanto "Neo Espaço" estiver no campo para Invocar por Invocação-Especial 1 "Musgo Brilhante Neoespacial" da sua mão ou Deck.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29251488,'Chef de Nouvelles',replace(replace('Escala de Pêndulo = 0\r\n[ Efeito de Pêndulo ]\r\nDurante sua Fase Principal, se este card foi ativado neste turno: você pode adicionar 1 card "Nouvelles" que não seja Pêndulo do seu Deck à sua mão. \r\nSe um ou mais monstros forem Invocados por Invocação-Especial no campo do seu oponente (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Chef de Nouvelles" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe este card no campo for oferecido como Tributo e adicionado ao Deck Adicional com a face para cima: você pode colocar este card na sua Zona de Pêndulo. \r\nVocê não pode ativar os seguintes efeitos de "Chef de Nouvelles" na mesma Corrente. \r\nUma vez por turno (Efeito Rápido): você pode escolher 1 Monstro de Efeito no campo; aumente o Nível dele em até 3. \r\nUma vez por turno, se seu oponente Invocar um ou mais monstros por Invocação-Especial (exceto durante a Etapa de Dano): você pode banir 1 Magia de Ritual "Receita" da sua mão, do Deck ou do Cemitério; aplique o efeito de ativação desse card que Invoca um monstro por Invocação-Ritual.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Invocar este card por Invocação Especial','Aumentar o Nível','Aplicar efeitos','Colocar na Zona de Pêndulo','Escolha o Nível a aumentar','','','','','','','','','','');
INSERT INTO texts VALUES(29253591,'Couse Dragunidade',replace(replace('Não pode ser usado como Matéria Sincro, exceto para a Invocação-Sincro de um monstro "Dragunidade". \r\nEste card no campo pode ser considerado como um monstro de Nível 4 quando usado para uma Invocação-Sincro. \r\nSe este card atualmente estiver equipado a um monstro: você pode Invocar este card equipado por Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29265962,'A Liga da Nomenclatura Uniforme Entra em Greve',replace(replace('Escolha 1 monstro com a face para cima que você controla; equipe 2 monstros com o mesmo nome original que o do alvo da sua mão, do Deck e/ou do Cemitério a esse alvo como Magias de Equipamento e, se isso acontecer, ele não pode atacar ou ser destruído em batalha enquanto estiver equipado com esses 2 cards. \r\nVocê não pode Invocar por Invocação-Especial pelo resto deste turno depois que este card resolver, exceto monstros com o mesmo Tipo original que o do monstro alvo. \r\nVocê só pode ativar 1 "A Liga da Nomenclatura Uniforme Entra em Greve" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29267084,'Feitiço Sombra',replace(replace('Ative este card ao escolher 1 monstro com a face para cima que seu oponente controla; ele perde 700 de ATK e, além disso, ele não pode atacar ou mudar sua posição de batalha. \r\nQuando ele deixar o campo, destrua este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29280200,'Alma Aniquiladora Dra. Louco Amor',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 Magia/Armadilha "Alma Aniquiladora" do seu Deck à sua mão. \r\n(Efeito Rápido): você pode ativar 1 desses efeitos ao revelar um ou mais monstros na sua mão com o(s) \r\nAtributo(s) listado(s);\r\n● TREVAS: 1 monstro com a face para cima que seu oponente controla perde 500 de ATK/DEF.\r\n● TREVAS & TERRA: Devolva para a mão o 1 monstro com a menor DEF no campo (em caso de empate, você seleciona).	\r\nVocê só pode usar cada efeito de "Alma Aniquiladora Dra. Louco Amor" uma vez por turno e não pode ativar mais que 1 na mesma Corrente.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Revele um monstro de TREVAS','Revele um monstro de TREVAS ou TERRA','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29280589,'Diabrete de Foices Afiadas',replace(replace('Durante a Fase Principal do seu oponente (Efeito Rápido): você pode revelar este card na sua mão; Invoque por Invocação-Fusão 1 Monstro de Fusão "Peladura" do seu Deck Adicional, usando monstros da sua mão ou do campo como Matéria de Fusão, incluindo este card na sua mão. \r\nSe um ou mais Monstros de Fusão "Peladura" que você controla seriam destruídos em batalha ou por um efeito de card, em vez disso, você pode banir este card do seu Cemitério. \r\nVocê só pode usar cada efeito de "Diabrete de Foices Afiadas" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29284413,'O Cavaleiro do Coringa',replace(replace('Você pode enviar 1 "O Cavaleiro da Rainha", "O Cavaleiro do Rei" ou "O Cavaleiro do Valete" do seu Deck para o Cemitério; Invoque este card por Invocação-Especial da sua mão e, se isso acontecer, até a Fase Final, o nome deste card se torna o nome do monstro enviado. \r\nDurante a Fase Final, se este card estiver no seu Cemitério: você pode escolher 1 outro monstro Guerreiro de LUZ no seu Cemitério; embaralhe-o no Deck e, se isso acontecer, adicione este card à sua mão. \r\nVocê só pode usar cada efeito de "O Cavaleiro do Coringa" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29296344,'Dragão Quadricallibre',replace(replace('2 monstros Dragão, incluindo um monstro "Foguette"	\r\nVocê pode descartar 1 card e, depois, escolha 1 monstro com a face para cima no campo; você não pode Invocar por Invocação-Especial monstros de Link-2 ou menos do Deck Adicional pelo resto deste turno e, além disso, destrua o monstro alvo e, depois, se ele era um Monstro Link, você pode Invocar por Invocação-Especial qualquer número de monstros "Foguette" com nomes diferentes, da sua mão ou do Cemitério, até seu Valor Link. \r\nVocê só pode usar este efeito de "Dragão Quadricallibre" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial um monstro "Foguette"?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29301450,'S:P Pequena Cavaleira',replace(replace('2 Monstros de Efeito	\r\nSe este card for Invocado por Invocação-Link usando um Monstro de Fusão, Sincro, Xyz ou Link como matéria: você pode escolher 1 card no campo ou em qualquer Cemitério; bana-o e, além disso, seus monstros não podem atacar diretamente neste turno. \r\nQuando seu oponente ativar um card ou efeito (Efeito Rápido): você pode escolher 2 monstros com a face para cima no campo, incluindo um monstro que você controla; bana os dois até a Fase Final. \r\nVocê só pode usar cada efeito de "S:P Pequena Cavaleira" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29301451,'S:P Pequena Cavaleira',replace(replace('2 Monstros de Efeito	\r\nSe este card for Invocado por Invocação-Link usando um Monstro de Fusão, Sincro, Xyz ou Link como matéria: você pode escolher 1 card no campo ou em qualquer Cemitério; bana-o e, além disso, seus monstros não podem atacar diretamente neste turno. \r\nQuando seu oponente ativar um card ou efeito (Efeito Rápido): você pode escolher 2 monstros com a face para cima no campo, incluindo um monstro que você controla; bana os dois até a Fase Final. \r\nVocê só pode usar cada efeito de "S:P Pequena Cavaleira" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29302858,'Alma Aniquiladora Razen',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 monstro "Alma Aniquiladora" não-Guerreiro do seu Deck à sua mão. \r\n(Efeito Rápido): você pode ativar 1 desses efeitos ao revelar um ou mais monstros na sua mão com o(s) \r\nAtributo(s) listado(s);\r\n● FOGO: Neste turno, este card não pode ser destruído por efeitos de card.\r\n● FOGO & TREVAS: Destrua todos os outros monstros na coluna deste card.	\r\nVocê só pode usar cada efeito de "Alma Aniquiladora Razen" uma vez por turno e não pode ativar mais que 1 na mesma Corrente.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Revele um monstro de FOGO','Revele um monstro de FOGO ou TREVAS','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29302859,'Alma Aniquiladora Razen',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 monstro "Alma Aniquiladora" não-Guerreiro do seu Deck à sua mão. \r\n(Efeito Rápido): você pode ativar 1 desses efeitos ao revelar um ou mais monstros na sua mão com o(s) \r\nAtributo(s) listado(s);\r\n● FOGO: Neste turno, este card não pode ser destruído por efeitos de card.\r\n● FOGO & TREVAS: Destrua todos os outros monstros na coluna deste card.	\r\nVocê só pode usar cada efeito de "Alma Aniquiladora Razen" uma vez por turno e não pode ativar mais que 1 na mesma Corrente.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Revele um monstro de FOGO','Revele um monstro de FOGO ou TREVAS','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29303524,'Seleglare, o Dragão Lunar Brilhante',replace(replace('Você pode Invocar este card por Invocação-Normal/Baixar sem oferecer Tributo, mas seu ATK original se torna 1500. \r\nDurante a Fase Principal (Efeito Rápido): você pode escolher 1 monstro que seu oponente controla com ATK menor ou igual que o deste card; devolva este card para a mão e, se isso acontecer, tome o controle desse monstro do oponente até a Fase Final. \r\nVocê só pode usar este efeito de "Seleglare, o Dragão Lunar Brilhante" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Normal sem Tributo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29307554,'Linhagem de Destruição',replace(replace('Ative somente durante um turno em que você destruiu um monstro em Posição de Defesa que seu oponente controlava. \r\nSelecione 1 monstro de Nível 8 que você controla. \r\nDurante este turno, o monstro selecionado pode atacar duas vezes.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29311166,'Wivern Agressor','Quando este card destruir um monstro do oponente em batalha: você pode oferecer este card como Tributo; Invoque por Invocação-Especial 1 monstro do Tipo Dragão da sua mão ou Cemitério, exceto "Wivern Agressor".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29325276,'Dragão Chama Solar de Olhos Anômalos',replace(replace('1 Regulador + 1+ não-Reguladores	\r\nSe este card for Invocado por Invocação-Especial: você pode Invocar por Invocação-Especial 1 Monstro Pêndulo com a face para cima do seu Deck Adicional, mas você não pode Invocar por Invocação-Especial, exceto Monstros Pêndulo, enquanto você controlar esse monstro com a face para cima. \r\nSe este card estiver no seu Cemitério: você pode banir 2 outros monstros (Fusão/Sincro/Xyz/Pêndulo) do seu Cemitério; Invoque este card por Invocação-Especial. \r\nVocê só pode usar 1 efeito de "Dragão Chama Solar de Olhos Anômalos" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Invoque por Invocação Especial do Deck Adicional','Invocar este card por Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29330706,'Dragão Protetor Armado',replace(replace('Os Cards de Equipamento com a face para cima que você controla não podem ser destruídos por efeitos de card. \r\nEste card ganha 500 de ATK para cada Card de Equipamento equipado a este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29343734,'Eletro, o HERÓI do Elemento',replace(replace('"Aviário, o HERÓI do Elemento" + "Burstinatrix, o HERÓI do Elemento" + "Clayman, o HERÓI do Elemento" + "Homem Bolha, o HERÓI do Elemento"	\r\nDeve ser Invocado por Invocação-Fusão. \r\nEnquanto estiver com a face para cima no campo, este card também é dos Atributos VENTO, ÁGUA, FOGO e TERRA. \r\nQuando este card for Invocado por Invocação-Fusão: embaralhe todos os cards banidos no(s) \r\nDeck(s). \r\nGanha 300 de ATK para cada monstro que seu oponente controla com o mesmo Atributo que o deste card.','\r',char(13)),'\n',char(10)),'Retornar ao Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29348048,'Carniceiro Vendorror',replace(replace('Você pode Invocar este card por Invocação-Ritual com qualquer Magia de Ritual "Vendorror". \r\nDurante a Fase Principal (Efeito Rápido): você pode oferecer como Tributo 1 outro monstro Zumbi; até o final deste turno, este card ganha ATK igual ao ATK original do monstro oferecido como Tributo. \r\nSe você controlar "Assassino Revendorror" e este card estiver no seu Cemitério: você pode Invocar este card por Invocação-Especial, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar cada efeito de "Carniceiro Vendorror" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29353756,'ZW - Garra da Águia',replace(replace('Se os PV do seu oponente forem pelo menos 2000 a mais que os seus, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê pode escolher 1 monstro "Utopia" que você controla; equipe este monstro no campo ao alvo. \r\nEle ganha 2000 de ATK. \r\nUma vez por turno, enquanto este card estiver equipado a um monstro, negue o primeiro Card de Armadilha ou seus efeitos ativado no campo do seu oponente, quando ele resolver. \r\nVocê só pode controlar 1 "ZW - Garra da Águia".','\r',char(13)),'\n',char(10)),'Considerar como Card de Equipamento','Negar o efeito','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29354228,'Encontro Dogmatika',replace(replace('Ative 1 desses efeitos;\r\n● Invoque por Invocação-Especial 1 monstro "Dogmatika" ou "Caído de Arbaz" da sua mão.\r\n● Adicione à sua mão ou Invoque por Invocação-Especial 1 monstro "Dogmatika" ou "Caído de Arbaz" do seu Cemitério.	\r\nVocê só pode ativar 1 "Encontro Dogmatika" por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial da mão','Adicionar do Cemitério à mão ou Invocar por Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29357687,'Górgona, a Imperatriz dos Seguidores do Olho Maligno',replace(replace('2 monstros, incluindo um monstro "Olho Maligno"	\r\nGanha 100 de ATK para cada card "Olho Maligno" com nomes diferentes no seu Cemitério. \r\nSe este card estiver equipado com "Olho Maligno de Selene" (Efeito Rápido): você pode escolher 1 Monstro de Efeito que seu oponente controla; negue os efeitos dele até o final deste turno. \r\nVocê só pode usar este efeito de "Górgona, a Imperatriz dos Seguidores do Olho Maligno" uma vez por turno. \r\nUma vez por turno, durante a próxima Fase de Apoio depois que este efeito foi ativado: destrua 1 monstro para o qual este card apontar.','\r',char(13)),'\n',char(10)),'Negar os efeitos de um monstro do oponente','Destrua 1 monstro na zona apontada por este card','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29357956,'Besta Gladiadora Nerokius',replace(replace('3 monstros "Besta Gladiadora"	\r\nVocê primeiro deve Invocá-lo por Invocação-Especial (do seu Deck Adicional) ao embaralhar os cards acima que você controla no Deck. \r\n(Você não usa "Polimerização".) \r\nNão pode ser destruído em batalha. \r\nSe este card atacar ou for atacado, seu oponente não pode ativar cards ou efeitos até o final da Etapa de Dano. \r\nNo final da Fase de Batalha, se este card atacar ou for atacado: você pode embaralhá-lo no Deck Adicional; Invoque por Invocação-Especial 2 monstros "Besta Gladiadora" do seu Deck.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29369059,'Nhamy☆Surpresa',replace(replace('Ative 1 desses efeitos (mas você só pode usar cada efeito de "Nhamy☆Surpresa" uma vez por turno);\r\n● Escolha 2 monstros Besta de LUZ que você controla e 2 cards que seu oponente controla; devolva-os para a mão.\r\n● Invoque por Invocação-Especial 1 monstro "Nhamy" da sua mão ou do Cemitério, mas ele não pode atacar diretamente neste turno.\r\n● Devolva 1 Magia de Campo do seu campo com a face para cima ou Cemitério para a mão e, depois, você pode colocar 1 Magia de Campo "Nhamy" da sua mão, no seu campo com a face para cima.','\r',char(13)),'\n',char(10)),'Ativar','Retornar os cards de ambos os jogadores à mão','Invocação Especial','Retornar a Magia de Campo à mão','Colocar a Magia de Campo com a face para cima?','','','','','','','','','','','');
INSERT INTO texts VALUES(29374928,'Bitron Blindado',replace(replace('Você pode oferecer este card como Tributo: Invoque por Invocação-Especial 1 monstro Ciberso do seu Deck, exceto "Bitron Blindado", mas negue seus efeitos e, além disso, você não pode Invocar por Invocação-Especial pelo resto deste turno, exceto monstros Ciberso. \r\nSe um Monstro Link de Link-3 ou mais que você controla for destruído em batalha ou por um efeito de card do oponente, enquanto este card estiver no seu Cemitério: você pode Invocar este card por Invocação-Especial, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar cada efeito de "Bitron Blindado" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29380133,'Yado Karu','Quando este card é mudado da Posição de Ataque para a Posição de Defesa, você pode devolver qualquer número de cards da sua mão para o fundo do seu Deck na ordem que você desejar.','Retornar ao Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29389368,'Nutriente Z','Durante o cálculo de dano, quando você estiver prestes a sofrer 2000 ou mais de dano de batalha: antes, ganhe 4000 PV.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29400787,'Parada Fantardil',replace(replace('Monstros não podem atacar monstros em Posição de Defesa com a face para baixo, mas podem atacar diretamente se todos os monstros que o oponente controla estiverem em Posição de Defesa com a face para baixo. \r\nSeu oponente não sofre dano. \r\nQuando um monstro do oponente declarar um ataque direto: você pode adicionar 1 card "Fantardil" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29401950,'Buraco Armadilha Sem Fundo','Quando seu oponente Invocar um ou mais monstros com 1500 ou mais de ATK: destrua esse(s) monstro(s) com 1500 ou mais de ATK e, se isso acontecer, bana-o(s).','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29402771,'Sereia Marinha do Arco-Íris','Uma sereia incomum que aparece quando um arco-íris se forma no céu.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29415459,'Mekk-Cavaleiro da Estrela Amarela',replace(replace('Se 2 ou mais cards estiverem na mesma coluna, você pode Invocar este card por Invocação-Especial (da sua mão) nessa coluna. \r\nVocê só pode Invocar "Mekk-Cavaleiro da Estrela Amarela" por Invocação-Especial uma vez por turno desta forma. \r\nVocê pode banir 1 monstro "Mekk-Cavaleiro" do seu Cemitério e, depois, escolha 1 Magia/Armadilha na coluna deste card; destrua-o.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29417188,'Bloqueador de Psi','Uma vez por turno: Você pode declarar 1 nome de card; cards com esse nome, e seus efeitos, não podem ser usados até o fim do próximo turno do seu oponente.','Declare o nome de um card','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29423048,'Banshee da Chama Infernal',replace(replace('2 monstros de Nível 4	\r\nVocê pode desassociar 1 matéria deste card; pegue 1 monstro Piro do seu Deck e adicione-o à sua mão ou envie-o para o Cemitério. \r\nSe este card for banido e você controlar um monstro Piro: você pode Invocar este card por Invocação-Especial e, se isso acontecer, ele ganha ATK igual ao número dos seus monstros atualmente banidos x 100 até o final deste turno. \r\nVocê só pode usar cada efeito de "Banshee da Chama Infernal" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29424328,'Diábolos, o Rei do Abismo',replace(replace('Não pode ser Invocado por Invocação-Especial. \r\nSe você Invocar este card por Invocação-Tributo, os Tributos devem ser de TREVAS. \r\nNão pode ser oferecido como Tributo por efeitos de card enquanto estiver com a face para cima no campo. \r\nUma vez por turno, durante a Fase de Compra do seu oponente, antes da compra normal dele: olhe o card do topo do Deck do seu oponente e, se isso acontecer, coloque esse card no topo ou no fundo do Deck dele.','\r',char(13)),'\n',char(10)),'Revelar o Deck','Coloque no topo do Deck','Coloque no fundo do Deck','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29432356,'Zefraath',replace(replace('Escala de Pêndulo = 5\r\n[ Efeito de Pêndulo ]\r\nDurante sua Fase Principal: você pode adicionar 1 Monstro Pêndulo "Zefra" do seu Deck ao seu Deck Adicional com a face para cima e, se isso acontecer, até o final deste turno, a Escala de Pêndulo deste card se torna a mesma que a desse Monstro Pêndulo. \r\nVocê só pode usar este efeito de "Zefraath" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nNão pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (com a face para cima do seu Deck Adicional) ao oferecer como Tributo todos os monstros que você controla, incluindo pelo menos 3 monstros "Zefra", e não pode ser Invocado por Invocação-Especial de nenhuma outra forma. \r\nDepois de Invocar este card por Invocação-Especial, você pode conduzir 1 Invocação-Pêndulo de um ou mais monstros "Zefra" durante sua Fase Principal neste turno, em adição à sua Invocação-Pêndulo. \r\n(Você só pode se aproveitar deste efeito uma vez por turno.) \r\nUma vez por turno: você pode oferecer 1 monstro como Tributo; Invoque por Invocação-Especial 1 monstro "Zefra" do seu Deck.','\r',char(13)),'\n',char(10)),'Adicione um Monstro Pêndulo "Zefra" ao seu Deck Adicional','Escolha o card a ser adicionado ao seu Deck Adicional','Invocação Pêndulo usando o efeito de "Zefraath"','Invoque por Invocação Especial 1 monstro "Zefra" do Deck','','','','','','','','','','','','');
INSERT INTO texts VALUES(29432790,'Fúria com Azul nos Olhos',replace(replace('Bana, com a face para baixo, este card e tantos cards quanto possível da sua mão, do campo e do Cemitério e, se isso acontecer, Invoque por Invocação-Especial até 3 cópias de "Dragão Branco de Olhos Azuis" do seu Deck. \r\nVocê não pode Invocar monstros por Invocação-Normal ou Especial no turno em que ativar este card, exceto "Dragão Branco de Olhos Azuis".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29436665,'Bruxo Sombrio Erradicador',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nVocê deve Invocá-lo por Invocação-Especial (da sua mão) ao oferecer como Tributo 1 "Mago Negro" e não pode ser Invocado por Invocação-Especial de nenhuma outra forma. \r\nSempre que um Card de Magia Normal for ativado, cause 1000 de dano ao seu oponente imediatamente depois que ele resolver.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29439831,'Morgana, a Bruxa dos Olhos',replace(replace('(Este card deve ser sempre considerado como um card "Morganita".)	\r\nQuando um monstro do oponente declarar um ataque: você pode banir 1 Magia "Morganita" do seu Cemitério; negue o ataque. \r\nVocê só pode usar cada um dos seguintes efeitos de "Morgana, a Bruxa dos Olhos" uma vez por turno. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 Magia "Morganita" do seu Deck à sua mão. \r\nSe você tiver 3 ou mais Magias "Morganita" com nomes diferentes no seu Cemitério e/ou banimento: você pode mudar o ATK de todos os monstros com a face para cima que seu oponente controla para 0.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Negar o ataque','ATK torna-se 0','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29455728,'Lagarto Gêmeo de Fóton',replace(replace('2 monstros "Fóton"	\r\nVocê pode oferecer este card como Tributo; Invoque por Invocação-Especial, do seu Cemitério, os dois Monstros-Matéria de Fusão usados para a Invocação-Fusão deste card.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29477860,'Descarga Espiral',replace(replace('Enquanto "Gaia, o Matador de Dragões" estiver na sua Zona de Monstros, os monstros do seu oponente só podem escolher "Gaia, o Matador de Dragões" como alvo de ataques. \r\nQuando um ataque for declarado envolvendo seu "Gaia, o Matador de Dragões": você pode escolher 1 card no campo; destrua-o. \r\nVocê só pode usar este efeito de "Descarga Espiral" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29479265,'Abominação Desacorrentada',replace(replace('2+ monstros, incluindo um Monstro Link	\r\nSe um ou mais cards no campo forem destruídos por um efeito de card, exceto por "Abominação Desacorrentada" (exceto durante a Etapa de Dano): você pode escolher 1 card no campo; destrua-o. \r\nQuando outro monstro for destruído em batalha: você pode escolher 1 card no campo; destrua-o. \r\nDurante a Fase Final: você pode escolher 1 card no campo; destrua-o. \r\nVocê só pode usar cada efeito de "Abominação Desacorrentada" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29479266,'Abominação Desacorrentada',replace(replace('2+ monstros, incluindo um Monstro Link	\r\nSe um ou mais cards no campo forem destruídos por um efeito de card, exceto por "Abominação Desacorrentada" (exceto durante a Etapa de Dano): você pode escolher 1 card no campo; destrua-o. \r\nQuando outro monstro for destruído em batalha: você pode escolher 1 card no campo; destrua-o. \r\nDurante a Fase Final: você pode escolher 1 card no campo; destrua-o. \r\nVocê só pode usar cada efeito de "Abominação Desacorrentada" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29491031,'Cabelos de Cobras','Um monstro com serpentes venenosas na cabeça. Um vislumbre desse monstro pode transformar o oponente em pedra.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29491334,'CÃO Fighter de Kozmo',replace(replace('Uma vez por turno, durante a Fase de Apoio: você pode Invocar por Invocação-Especial 1 "Ficha de CÃO Fighter" (Tipo Máquina/TREVAS/Nível 6/ATK 2000/DEF 2400). \r\nSe este card for destruído em batalha ou por um efeito de card e enviado para o Cemitério: você pode banir este card do seu Cemitério; Invoque por Invocação-Especial 1 monstro "Kozmo" de Nível 5 ou menos do seu Deck.','\r',char(13)),'\n',char(10)),'Invocar uma Ficha por Invocação Especial','Invoque por Invocação Especial um monstro "Kozmo" do Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29491335,'Ficha de CÃO Fighter','Invocado por Especial com o efeito "CÃO Fighter de Kozmo".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29508346,'Chegada Rival',replace(replace('Durante a Fase de Batalha: imediatamente depois que este efeito resolver, Invoque 1 monstro por Invocação-Normal. \r\nVocê só pode ativar 1 "Chegada Rival" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29508347,'Chegada Rival',replace(replace('Durante a Fase de Batalha: imediatamente depois que este efeito resolver, Invoque 1 monstro por Invocação-Normal. \r\nVocê só pode ativar 1 "Chegada Rival" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29510428,'Princesa Imperial Quinquery',replace(replace('2 monstros de Nível 5	\r\nVocê pode desassociar 1 matéria deste card e, depois, escolha 1 monstro de Nível 5 em qualquer Cemitério; Invoque-o por Invocação-Especial em qualquer campo. \r\nSe um monstro de Nível 5 com a face para cima que você controla for destruído em batalha, ou deixar o campo por um efeito de card do oponente, enquanto você controlar este monstro: você pode adicionar à sua mão ou Invocar por Invocação-Especial, 1 monstro de Nível 5 do seu Deck. \r\nVocê só pode usar cada efeito de "Princesa Imperial Quinquery" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Invocar por Invocação Especial para o seu Campo','Invocar por Invocação Especial para o Campo do seu oponente','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29515122,'Digvorzhak, o Rei do Maquinário Pesado',replace(replace('3 monstros de Nível 5	\r\nUma vez por turno: você pode desassociar 1 matéria deste card; envie os 3 cards do topo do Deck do seu oponente para o Cemitério e, depois, se quaisquer monstros foram enviados para o Cemitério por este efeito, destrua cards que seu oponente controla, até o número de monstros enviados.','\r',char(13)),'\n',char(10)),'Enviar do Deck para o Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29537493,'Ursártico Mikpolar',replace(replace('Durante a Fase Principal (Efeito Rápido): você pode oferecer como Tributo 1 outro monstro de Nível 7 ou mais da sua mão; Invoque este card por Invocação-Especial da sua mão e, além disso, você não pode Invocar por Invocação-Especial pelo resto deste turno, exceto monstros com um Nível. \r\nSe este card for Invocado por Invocação-Especial: você pode adicionar 1 monstro "Ursártico(a)" do seu Deck à sua mão, exceto "Ursártico Mikpolar". \r\nVocê só pode usar cada efeito de "Ursártico Mikpolar" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29549364,'Máscara da Restrição','Nenhum duelista pode oferecer cards como Tributo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29552709,'Daigusto Sphreez',replace(replace('1 Regulador + 1 ou mais monstros "Gusto" não-Reguladores	\r\nQuando este card for Invocado por Invocação-Sincro: Você pode escolher 1 card "Gusto" no seu Cemitério; adicione o alvo à sua mão. \r\nSeu oponente sofre qualquer Dano de Batalha que você teria sofrido de batalhas envolvendo um monstro "Gusto" com a face para cima que você controla. \r\nEste card não pode ser destruído em batalha.','\r',char(13)),'\n',char(10)),'Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29570824,'Ekto Eneanave - "tromarIA"',replace(replace('Escala de Pêndulo = 0\r\n[ Efeito de Pêndulo ]\r\nSempre que um ou mais monstros forem virados com a face para cima, coloque 1 Marcador de E.N. neste card. \r\nVocê pode pagar 900 PV; revele 3 cards "Eneanave" do seu Deck, seu oponente elege 1 aleatoriamente para que você adicione à sua mão, embaralhe o resto no Deck. \r\nVocê só pode usar este efeito de "Ekto Eneanave - "tromarIA"" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nVIRE: Negue os efeitos de 1 Monstro de Efeito que seu oponente controla, até o final deste turno.\r\nQuando seu oponente ativar um card ou efeito que inclua um efeito que Invoque um ou mais monstros por Invocação-Especial (Efeito Rápido): você pode colocar este card que estiver com a face para baixo, com a face para cima em Posição de Defesa; adicione 1 card "Eneanave" do seu Deck à sua mão. \r\nVocê pode revelar este card na sua mão; Invoque por Invocação-Especial 1 monstro da sua mão com a face para baixo em Posição de Defesa. \r\nVocê não pode Invocar por Invocação-Especial no turno em que ativar este efeito, exceto com a face para baixo em Posição de Defesa.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Invocação Especial','Adicionar à mão','Negar','','','','','','','','','','','','');
INSERT INTO texts VALUES(29587993,'Ave Máxima do Vale das Névoas','Uma vez por Corrente, quando um card ou efeito for ativado (Efeito Rápido): você pode escolher 1 card "Vale das Névoas" que você controla; devolva o alvo para a mão e, se isso acontecer, negue a ativação e, se isso acontecer, destrua o card que ativou o card ou efeito.','Negar a ativação e destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29590752,'Besta Gladiadora Octavius',replace(replace('Quando este card for Invocado por Invocação-Especial pelo efeito de um monstro "Besta Gladiadora": Escolha 1 Card de Magia ou Armadilha com a face para baixo na Zona de Cards de Magia & Armadilha; destrua o alvo. \r\nNo final da Fase de Batalha, se este card atacou ou foi atacado: Embaralhe este card no Deck ou descarte 1 card.','\r',char(13)),'\n',char(10)),'Destruir','Descartar da mão ou retornar ao Deck','Descartar 1 card da sua mão?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29590905,'Superconfronto Júnior',replace(replace('Ative apenas quando um monstro do oponente declarar um ataque. \r\nNegue a batalha, e 1 monstro com a face para cima em Posição de Ataque com o menor ATK que seu oponente controla batalha contra 1 monstro com a face para cima em Posição de Defesa com a menor DEF que você controla. \r\nApós essa batalha, encerre a Fase de Batalha.','\r',char(13)),'\n',char(10)),'Escolha 1 monstro com o menor ATK','Escolha 1 monstro com a menor DEF','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29595202,'Sedução Rúnika',replace(replace('Sempre que um Card de Magia Rápida ativar: bana o card do topo do Deck do seu oponente. \r\nVocê só pode controlar 1 "Sedução Rúnika".','\r',char(13)),'\n',char(10)),'Banir 1 card do Deck do seu oponente','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29596581,'Rugidodragão do Trovão',replace(replace('Você pode descartar este card; adicione à sua mão 1 dos seus cards "Dragão do Trovão" que estiverem banidos ou no seu Cemitério, exceto "Rugidodragão do Trovão". \r\nSe este card for banido ou enviado do campo para o Cemitério: você pode Invocar por Invocação-Especial 1 monstro "Dragão do Trovão" do seu Deck, em Posição de Defesa, mas devolva-o para a mão durante a Fase Final. \r\nVocê só pode usar 1 efeito de "Rugidodragão do Trovão" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29599813,'Linda Lembrança Purrely',replace(replace('Cada duelista ganha 1000 PV e, depois, você pode aplicar o seguinte efeito.\r\n● Descarte 1 card e, se isso acontecer, Invoque por Invocação-Especial do seu Deck 1 monstro "Purrely" de Nível 1.	\r\nUm Monstro Xyz "Purrely" que tenha este card como matéria ganha o seguinte efeito.\r\n● Uma vez por turno: você pode enviar 1 outro card que você controla para o Cemitério e, depois, escolha 1 card que seu oponente controla; associe-o a este card.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial do Deck?','Associar Matéria Xyz (Linda Lembrança Purrely)','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29599814,'Linda Lembrança Purrely',replace(replace('Cada duelista ganha 1000 PV e, depois, você pode aplicar o seguinte efeito.\r\n● Descarte 1 card e, se isso acontecer, Invoque por Invocação-Especial do seu Deck 1 monstro "Purrely" de Nível 1.	\r\nUm Monstro Xyz "Purrely" que tenha este card como matéria ganha o seguinte efeito.\r\n● Uma vez por turno: você pode enviar 1 outro card que você controla para o Cemitério e, depois, escolha 1 card que seu oponente controla; associe-o a este card.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial do Deck?','Associar Matéria Xyz (Linda Lembrança Purrely)','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29601381,'Springans Capitão Sargas',replace(replace('Se este card estiver na sua mão, no campo ou no Cemitério: você pode escolher 1 Monstro Xyz "Springans" que você controla; associe este card a ele como matéria. \r\nDurante o turno do seu oponente (Efeito Rápido): você pode desassociar 1 matéria de um Monstro Xyz que você controla e, depois, escolha 1 card com a face para cima no campo; destrua-o. \r\nVocê só pode usar cada um dos efeitos anteriores de "Springans Capitão Sargas" uma vez por turno. \r\nUm Monstro Xyz "Springans" que tenha este card como matéria ganha este efeito.\r\n● Este card ganha 500 de ATK.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29603180,'Arquidemônio Aniquilador',replace(replace('Você pode escolher 1 card que você controla e 1 card que seu oponente controla; destrua-os e, se você destruiu um ou mais monstros Demônio com a face para cima por este efeito, até o final deste turno, este card ganha ATK igual à metade do ATK original desse(s) monstro(s) \r\nDemônio. \r\nVocê só pode usar este efeito de "Arquidemônio Aniquilador" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29612557,'Bumerangue Ciclônico',replace(replace('Equipe apenas em "Coração Selvagem, o HERÓI do Elemento". \r\nEle ganha 500 de ATK. \r\nQuando o monstro equipado for destruído por um efeito de card e enviado ao Cemitério: Destrua todos os Cards de Magia e Armadilha no campo. \r\nCause 100 de dano ao oponente para cada Card de Magia/Armadilha destruído por este efeito.','\r',char(13)),'\n',char(10)),'Destrua e cause dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29616929,'Buraco Armadilha Pesadelo Armadilhatrix','Quando um monstro que foi Invocado por Invocação-Especial neste turno ativar seu efeito no campo do seu oponente: negue o efeito e, se isso acontecer, destrua esse card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29616941,'Bela Treinadora de Bestas','Uma rara mestra das bestas com um chicote muito perigoso.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29618570,'Asa Cinzenta',replace(replace('Descarte 1 card da sua mão durante a Main Phase 1. \r\nEste card pode atacar duas vezes durante a Battle Phase deste turno.','\r',char(13)),'\n',char(10)),'Atacar duas vezes','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29628180,'Mágico Mosquete - Último Suspiro',replace(replace('Quando seu oponente ativar um Card de Magia/Armadilha enquanto você controlar um monstro "Mágico(a) Mosquete": negue a ativação e, se isso acontecer, destrua esse card. \r\nVocê só pode ativar 1 "Mágico Mosquete - Último Suspiro" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29649320,'Lançador da Força do Espelho',replace(replace('Uma vez por turno, durante sua Fase Principal: você pode descartar 1 monstro; adicione 1 "Força do Espelho" do seu Deck ou Cemitério à sua mão. \r\nSe este card Baixado for destruído por um efeito de card do seu oponente e enviado para o seu Cemitério: você pode Baixar este card do seu Cemitério e 1 "Força do Espelho" da sua mão, do Deck, ou do Cemitério. \r\nEles podem ser ativados neste turno.','\r',char(13)),'\n',char(10)),'Ativar aplicando o efeito de "Lançador da Força do Espelho".','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29650040,'Harmonia Solfacorde',replace(replace('Você pode ativar 1 desses efeitos;\r\n● Adicione 1 Monstro Pêndulo "Solfacorde" com a face para cima do seu Deck Adicional à sua mão.\r\n● Neste turno, aumente a Escala de Pêndulo de 1 card "Solfacorde" na sua Zona de Pêndulo pelo seu Nível.\r\n● Se você controlar Cards de Monstro Pêndulo "Solfacorde" com pelo menos 3 Escalas de Pêndulo pares diferentes ou pelo menos 3 Escalas de Pêndulo ímpares diferentes, destrua 1 card que seu oponente controla.	\r\nVocê só pode usar cada efeito de "Harmonia Solfacorde" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicione à sua mão 1 card do Deck Adicional','Aumentar Escala Pêndulo','Destruir 1 card que seu oponente controla','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29654737,'Mestra da Corrente Amazoness','Quando este card for destruído em batalha e enviado para o Cemitério: você pode pagar 1500 PV; olhe a mão do seu oponente e, depois, adicione 1 monstro da mão dele à sua mão.','Pegar 1 card da mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29666221,'Ataque Orcustrado','Quando um monstro declarar um ataque: ofereça como Tributo 1 monstro "Orcust" ou "Legado Mundial" e, depois, escolha 1 monstro que seu oponente controla; bana-o.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29669359,'Número 61: Vulcassauro',replace(replace('2 monstros de Nível 5	\r\nUma vez por turno: você pode desassociar 1 matéria deste card e, depois, escolha 1 monstro com a face para cima que seu oponente controla; destrua esse monstro do oponente e, se isso acontecer, cause dano ao seu oponente igual ao ATK original do monstro destruído. \r\nEste card não pode atacar diretamente no turno em que você ativar este efeito.','\r',char(13)),'\n',char(10)),'Destruir e causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29687169,'Arnis, a Guerreira Edificada','Quando este card que você controla for destruído em batalha por um monstro atacante do oponente e enviado para o seu Cemitério: você pode Invocar por Invocação-Especial 1 monstro do Tipo Mago com 1500 ou menos de ATK do seu Deck em Posição de Ataque.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29692206,'Varas Gêmeas e Longas nº 2','Uma criatura anfíbia com duas caudas similares a chicotes.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29716911,'Capacitor Perseguidor',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode escolher 1 outro monstro Ciberso que você controla; enquanto este monstro com a face para cima estiver no campo, esse monstro ganha 800 de ATK. \r\nSe este card na Zona de Monstros for destruído por um efeito de card e enviado para o Cemitério: cada duelista sofre 800 de dano. \r\nVocê só pode usar este efeito de "Capacitor Perseguidor" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29719112,'Farol Cibernético',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) ao oferecer como Tributo 1 monstro Máquina. \r\nUma vez por turno, durante sua Fase Principal: você pode Invocar por Invocação-Fusão 1 Monstro de Fusão Máquina do seu Deck Adicional, usando monstros da sua mão e/ou do campo como matéria. \r\nQuando um Monstro de Fusão que você controla for destruído em batalha: você pode banir este card do seu Cemitério; adicione 1 "Vínculo de Poder" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Farol Cibernético" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29724053,'Invocar Portal','Cada duelista pode Invocar por Invocação-Especial um máximo de 3 monstros do Deck Adicional a cada turno.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29726552,'Kumongous, o Kaiju Pegajoso da Corda',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) no campo do seu oponente em Posição de Ataque, ao oferecer como Tributo 1 monstro que ele controla. \r\nSe seu oponente controlar um monstro "Kaiju", você pode Invocar este card por Invocação-Especial (da sua mão) em Posição de Ataque. \r\nVocê só pode controlar 1 monstro "Kaiju". \r\nQuando seu oponente Invocar um ou mais monstros por Invocação-Normal ou Especial (exceto durante a Etapa de Dano): você pode remover 2 Marcadores Kaiju de qualquer parte do campo; até o final do próximo turno, esse(s) monstro(s) não pode(m) atacar e seus efeitos são negados.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29735721,'Limpeza de Spells',replace(replace('Descarte 2 cards da sua mão para anular a activação de um Card de Magia e destruí-lo. \r\nAinda, verifique a mão e Deck do seu adversário e se encontrar qualquer Card de Magia com o mesmo nome que o Card de Magia destruído, envie todos para o Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29762407,'Templo dos Reis',replace(replace('Você pode ativar 1 Card de Armadilha no turno em que ele foi Baixado. \r\nVocê pode enviar para o Cemitério 1 "Besta Mística de Serket" na sua Zona de Monstros e este card que você controla; Invoque por Invocação-Especial 1 monstro da sua mão ou do Deck, ou 1 Monstro de Fusão do seu Deck Adicional. \r\nVocê só pode usar cada efeito de "Templo dos Reis" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Ativar aplicando o efeito de "Templo dos Reis".','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29765339,'Watthidra',replace(replace('1 Regulador "Watt" + 1+ monstros Trovão não-Reguladores	\r\nEste card pode atacar diretamente. \r\nSe este card causar dano de batalha ao seu oponente em um ataque direto: bana 1 card do seu Deck e, se isso acontecer, adicione o card banido à sua mão durante sua 2ª Fase de Apoio depois da ativação deste efeito.','\r',char(13)),'\n',char(10)),'Banir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29792472,'Yad''al-Hecamãos',replace(replace('Quando seu oponente ativar um Card de Magia/Armadilha, enquanto você controlar um monstro "Hecamãos": negue a ativação e, se isso acontecer, destrua esse card e, depois, você pode Baixar a Magia/Armadilha destruída no seu campo. \r\nVocê só pode ativar 1 "Yad''al-Hecamãos" por turno.','\r',char(13)),'\n',char(10)),'','Baixar?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29795530,'Sentinela do Yokai',replace(replace('Cada monstro com a face para cima no campo perde 2 Níveis até a Fase Final. \r\nVocê pode remover de jogo este card do seu Cemitério para selecionar 1 monstro com a face para cima e reduzir o seu Nível em 1 até a Fase Final. \r\nEste efeito não pode ser ativado no turno em que este card for enviado para o Cemitério.','\r',char(13)),'\n',char(10)),'Reduzir o Nível','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29802344,'Serpentyashi','Esse monstro é formado por diversas serpentes que se separam para atacar individualmente os inimigos próximos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29826127,'As Forças das Trevas','Escolha 2 monstros "Mundo Negro" no seu Cemitério; adicione os alvos à sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29834183,'Alicercinza Águia',replace(replace('Se este card na sua Zona de Monstros for destruído em batalha ou por um efeito de monstro e enviado para o seu Cemitério: você pode escolher 1 monstro com a face para cima que seu oponente controla; equipe este card no alvo. \r\nEnquanto este card estiver equipado a um monstro por este efeito, tome o controle desse monstro. \r\nQuando este card deixar o campo, destrua o monstro equipado.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29838323,'Cristron Tistvern',replace(replace('Você pode escolher 1 card com a face para cima que você controla; você não pode Invocar monstros por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto Monstros Sincro do Tipo Máquina e, além disso, destrua esse card e, se isso acontecer, Invoque por Invocação-Especial do seu Deck 1 Regulador "Cristron". \r\nVocê pode banir este card do seu Cemitério; adicione 1 monstro "Cristron" do seu Deck à sua mão, exceto "Cristron Tistvern". \r\nVocê só pode usar 1 efeito de "Cristron Tistvern" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29843091,'Trio Ojama',replace(replace('Invoque por Invocação-Especial 3 "Ficha de Ojama" (Besta/LUZ/Nível 2/ATK 0/DEF 1000) no campo do seu oponente em Posição de Defesa. \r\nElas não podem ser oferecidas como Tributo para uma Invocação-Tributo, e sempre que 1 for destruída, seu controlador sofre 300 de dano.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29843092,'Ficha de Ojama','Invocado por Especial com o efeito "Trio Ojama". Esta Ficha não pode ser oferecida como Tributo para uma Invocação-Tributo. Quando destruída, o controlador sofre 300 de dano.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29843093,'Ficha de Ojama','Invocado por Especial com o efeito "Trio Ojama". Esta Ficha não pode ser oferecida como Tributo para uma Invocação-Tributo. Quando destruída, o controlador sofre 300 de dano.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29843094,'Ficha de Ojama','Invocado por Especial com o efeito "Trio Ojama". Esta Ficha não pode ser oferecida como Tributo para uma Invocação-Tributo. Quando destruída, o controlador sofre 300 de dano.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29843095,'Trio Ojama',replace(replace('Invoque por Invocação-Especial 3 "Ficha de Ojama" (Besta/LUZ/Nível 2/ATK 0/DEF 1000) no campo do seu oponente em Posição de Defesa. \r\nElas não podem ser oferecidas como Tributo para uma Invocação-Tributo, e sempre que 1 for destruída, seu controlador sofre 300 de dano.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29863101,'Teleporte de Ataque','Embaralhe no Deck 1 monstro "/Modo de Ataque" da sua mão; compre 2 cards.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29867611,'Divertida Atração Carrossel Majestoso',replace(replace('Escolha 1 monstro "Diversão" que você controla ou 1 monstro com a face para cima que seu oponente controla; equipe este card a ele. \r\nVocê pode aplicar o seguinte efeito, de acordo com qual duelista controla o monstro equipado;\r\n● Você: O monstro equipado ganha 500 de ATK.	\r\nSe ele seria destruído em batalha ou por um efeito de card, em vez disso, você pode enviar este card para o Cemitério.\r\n● Seu oponente: O monstro equipado perde 500 de ATK para cada uma das suas Armadilhas "Atração" equipada a um ou mais monstros.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29876299,'Anástase do Megálito',replace(replace('Você pode descartar 1 card; adicione 2 monstros "Megálito" (1 de Nível 4 ou menos e 1 de Nível 8 ou mais) do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Anástase do Megálito" uma vez por turno. \r\nUma vez por turno, se você Invocar por Invocação-Ritual um monstro "Megálito" (exceto durante a Etapa de Dano): você pode ativar 1 desses efeitos (mas você só pode usar cada um desses efeitos de "Anástase do Megálito" uma vez por turno);\r\n● Compre 2 cards e, depois, descarte 1 card.\r\n● Ofereça como Tributo 1 monstro que seu oponente controla.','\r',char(13)),'\n',char(10)),'Efeito de busca','Comprar','Oferecer como Tributo','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29876529,'Luz Negra','Ofereça como Tributo 1 monstro de TREVAS com 1500 ou mais de ATK; destrua todos os monstros que foram Invocados por Invocação-Especial neste turno.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29882827,'Ascensão de Ryu-Ge',replace(replace('Adicione 1 monstro "Ryu-Ge" do seu Deck à sua mão e, depois, você pode adicionar 1 Monstro Pêndulo "Ryu-Ge" da sua mão ao seu Deck Adicional com a face para cima. \r\nDurante sua Fase Principal, se você controlar um Card de Monstro Pêndulo "Ryu-Ge": você pode banir este card e 1 monstro "Ryu-Ge" do seu Cemitério; Invoque por Invocação-Especial do seu Deck 1 monstro "Ryu-Ge" com o mesmo Tipo original que o desse monstro banido. \r\nVocê só pode usar 1 efeito de "Ascensão de Ryu-Ge" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Depois de adicioná-lo à sua mão, coloque o Card Pêndulo no Deck Adicional','Invocar por Invocação Especial do Deck','Adicionar ao Deck Adicional?','Escolha 1 card para adicionar ao Deck Adicional','','','','','','','','','','','','');
INSERT INTO texts VALUES(29884951,'Espadalma Áugure Chunjun',replace(replace('Antes do cálculo de dano, se um monstro Wyrm seu batalhar um monstro do oponente que foi Invocado por Invocação-Especial do Deck Adicional: você pode destruir tanto esse monstro do oponente quanto este card. \r\nVocê só pode usar cada um dos seguintes efeitos de "Espadalma Áugure Chunjun" uma vez por turno. \r\nDurante a Fase Principal (Efeito Rápido): você pode oferecer 1 monstro como Tributo; Invoque este card por Invocação-Especial da sua mão. \r\nSe este card for enviado para o Cemitério como Matéria Sincro: você pode escolher 1 card no campo ou em qualquer Cemitério; bana-o.','\r',char(13)),'\n',char(10)),'','','','Ativar escolhendo como alvo um card no campo','Ativar escolhendo como alvo um card no Cemitério','','','','','','','','','','','');
INSERT INTO texts VALUES(29888389,'Sombra Gishki',replace(replace('Se você Invocar por Invocação-Ritual exatamente 1 Monstro de Ritual de ÁGUA com um efeito de card que necesita a utilização de monstros, este card pode ser usado no lugar de todos os monstros necessários. \r\nVocê pode descartar este card; adicione 1 Card de Magia de Ritual "Gishki" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Adicione uma Magia de Ritual à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29904964,'Gaia, o Cavaleiro Impetuoso Desperto',replace(replace('Se seu oponente controlar mais monstros que você, você pode Invocar este card por Invocação-Normal sem oferecer Tributo. \r\nSe este card for oferecido como Tributo: você pode Invocar por Invocação-Especial 1 monstro "Soldado do Lustro Negro" (ou "Soldado do Brilho Negro - Enviado do Princípio") da sua mão ou Cemitério. \r\nVocê só pode usar este efeito de "Gaia, o Cavaleiro Impetuoso Desperto" uma vez por turno. \r\nQuando você Invocar um monstro "Soldado do Lustro Negro" por Invocação-Ritual, você pode banir este card do seu Cemitério como 1 dos monstros necessários para a Invocação-Ritual.','\r',char(13)),'\n',char(10)),'Invocação Normal sem Tributo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29905795,'Chawa, o Mitológico','Durante sua Fase Principal: você pode ativar este efeito; descarte 1 monstro "Mitológico(a)" e, se isso acontecer, Invoque este card por Invocação-Especial da sua mão.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29913783,'Super Máquina de Guerra Anti-Kaiju Mecha-Rei-Trovão',replace(replace('Durante a Fase Principal (Efeito Rápido): você pode descartar este card; bana 1 monstro "Kaiju" que você controla do qual seu oponente seja dono e, depois, você pode Invocar por Invocação-Especial 1 monstro do seu Cemitério. \r\nVocê só pode controlar 1 monstro "Kaiju". \r\nEste card não é afetado por outros efeitos de card "Kaiju" e, além disso, ele não pode ser destruído em batalha com um monstro "Kaiju". \r\nDurante sua Fase Final, se este card estiver no seu Cemitério: você pode Invocar este card por Invocação-Especial. \r\nVocê só pode usar este efeito de "Super Máquina de Guerra Anti-Kaiju Mecha-Rei-Trovão" uma vez por Duelo.','\r',char(13)),'\n',char(10)),'Banir um Kaiju e Invocar por Invocação Especial','Invocar este card por Invocação Especial','Invocar por Invocação Especial do Cemitério?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29925614,'Rainha Cativante do Caos',replace(replace('Você pode descartar 1 outro monstro de LUZ ou de TREVAS; Invoque este card por Invocação-Especial da sua mão. \r\nVocê pode escolher 1 monstro em qualquer Cemitério; equipe-o a este card como uma Magia de Equipamento e, se isso acontecer, o nome deste card se torna o nome desse monstro equipado (até a Fase Final) e, depois, se você equipou um Card de Monstro de LUZ ou de TREVAS por este efeito, você pode Invocar por Invocação-Especial 1 monstro "Rainha Cativante" de TREVAS do seu Deck ou Cemitério. \r\nVocê só pode usar cada efeito de "Rainha Cativante do Caos" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Equipar','Invocar por Invocação Especial outro monstro?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29927283,'Daneen, o Dino Retornado',replace(replace('Se este card for Invocado por Invocação-Especial por um efeito de monstro: você pode adicionar 1 monstro "GMX" do seu Deck à sua mão. \r\nDurante sua Fase Principal: você pode Invocar por Invocação-Fusão 1 Monstro de Fusão Dinossauro do seu Deck Adicional, usando monstros da sua mão ou do campo. \r\nSe este card for enviado para o Cemitério: você pode fazer com que todos os monstros Dinossauro que você controla atualmente ganhem 400 de ATK. \r\nVocê só pode usar cada efeito de "Daneen, o Dino Retornado" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Invocação Fusão','Aumentar ATK','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29929832,'Besta Marinha','"Mago da Água" + "Behegon"','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29934351,'Onda Terrestre','Quando seu oponente ativar um Card de Magia/Armadilha enquanto você controlar um monstro "Imortal Terrestre": negue a ativação e, se isso acontecer, destrua-o.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29942771,'Camélia de Naturia',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode enviar 1 card "Naturia" do seu Deck para o Cemitério. \r\nSe você ofereceria um ou mais monstros como Tributo para ativar o efeito de um monstro "Naturia", em vez disso, você pode enviar os 2 cards do topo do seu Deck para o Cemitério. \r\nSe seu oponente Invocar um monstro por Invocação-Normal ou Especial (exceto durante a Etapa de Dano): você pode Invocar por Invocação-Especial 1 monstro "Naturia" do seu Cemitério. \r\nVocê só pode usar cada efeito de "Camélia de Naturia" uma vez por turno.','\r',char(13)),'\n',char(10)),'Enviar 1 card "Naturia" do Deck para o Cemitério','Usar o efeito de "Camélia de Naturia" no lugar de oferecer como Tributo?','Invocar por Invocação Especial 1 monstro "Naturia" do seu Cemitério','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29947751,'Ímãnem Morfotrônico',replace(replace('● Enquanto estiver em Posição de Ataque: Se seu oponente controlar um monstro com a face para cima, este card só pode selecionar o monstro dele com o maior ATK como um alvo de ataque.\r\n● Enquanto estiver em Posição de Defesa: Seu oponente não pode selecionar outro monstro como alvo de um ataque.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29948294,'Marcado em Bom Humor',replace(replace('Revele 1 monstro na sua mão e envie 1 Monstro de Fusão de Nível 8 do seu Deck Adicional para o Cemitério, com o mesmo Tipo, que tenha 2500 de ATK ou DEF, e, depois, você pode aplicar este efeito.\r\n● Descarte o monstro revelado e, se isso acontecer, adicione 1 "Caído de Arbaz" ou 1 monstro que o mencione do seu Deck à sua mão.	\r\nDurante a Fase Final, se um Monstro de Fusão foi enviado para o seu Cemitério neste turno: você pode adicionar este card do Cemitério à sua mão. \r\nVocê só pode usar 1 efeito de "Marcado em Bom Humor" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Descartar o monstro revelado e adicionar o card à sua mão?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29948642,'Bico de Escavação','Esta besta se enrola como uma cobra, e ataca rapidamente com o seu ruidoso bico.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29951323,'Zap Mustangue',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial por um efeito de card durante sua Fase Principal 1, e não pode ser Invocado por Invocação-Especial se você Invocou por Invocação-Especial neste turno. \r\nNas primeiras duas vezes que este card seria destruído em batalha a cada turno, ele não é destruído. \r\nA cada turno, o duelista do turno só pode Invocar por Invocação-Especial um número de vezes até o número de ataques conduzidos por ele (e que chegaram à Etapa de Dano) neste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29975188,'Dragão Cibernético Vier',replace(replace('O nome deste card se torna "Dragão Cibernético" enquanto estiver no campo ou no Cemitério. \r\nSe você Invocar "Dragão Cibernético" por Invocação-Normal ou Especial, exceto durante a Etapa de Dano: você pode Invocar este card por Invocação-Especial da sua mão em Posição de Defesa. \r\nVocê só pode usar este efeito de "Dragão Cibernético Vier" uma vez por turno. \r\nCada "Dragão Cibernético" que você controla ganha 500 de ATK/DEF.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29981921,'Seis Samurai Lendários - Shi Em',replace(replace('1 Regulador Guerreiro + 1+ monstros "Seis Samurai" não-Reguladores	\r\nUma vez por turno, quando seu oponente ativar um Card de Magia/Armadilha (Efeito Rápido): você pode negar a ativação e, se isso acontecer, destrua-o. \r\nSe este card no campo seria destruído em batalha ou por um efeito de card, em vez disso, você pode destruir outro monstro "Seis Samurai" que você controla.','\r',char(13)),'\n',char(10)),'Negar a ativação de um Card de Magia/Armadilha e destruí-lo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29981922,'Seis Samurai Lendários - Shi Em',replace(replace('1 Regulador Guerreiro + 1+ monstros "Seis Samurai" não-Reguladores	\r\nUma vez por turno, quando seu oponente ativar um Card de Magia/Armadilha (Efeito Rápido): você pode negar a ativação e, se isso acontecer, destrua-o. \r\nSe este card no campo seria destruído em batalha ou por um efeito de card, em vez disso, você pode destruir outro monstro "Seis Samurai" que você controla.','\r',char(13)),'\n',char(10)),'Negar a ativação de um Card de Magia/Armadilha e destruí-lo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29981935,'Bujin Torifune',replace(replace('Você pode oferecer este card como Tributo; Invoque por Invocação-Especial 2 monstros "Bujin" de 2 Tipos diferentes do Deck, em Posição de Defesa, exceto "Bujin Torifune". \r\nQuando você Invocar um Monstro Xyz "Bujin" por Invocação-Xyz, enquanto este card estiver no seu Cemitério: você pode equipar este card a ele. \r\nQualquer monstro destruído em batalha com esse monstro equipado é banido. \r\nVocê só pode usar cada efeito de "Bujin Torifune" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29996433,'Dinolutador Capoeiraptor',replace(replace('Este card em Posição de Ataque não pode ser destruído em batalha. \r\nSe este card for atacado, coloque-o em Posição de Defesa no final da Etapa de Dano. \r\nDurante a Fase de Apoio, se este card estiver em Posição de Defesa: você pode Invocar por Invocação-Especial 1 "Dinolutador Capoeiraptor" do seu Deck. \r\nVocê só pode usar este efeito de "Dinolutador Capoeiraptor" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29999161,'Zenmairch','Escolha 1 monstro "de Corda" de Nível 4 ou menos com a face para cima que você controla: Devolva o alvo à mão (não importando o seu Nível) e, depois, Invoque por Invocação-Especial 1 monstro "de Corda" da mão com o mesmo Nível do monstro devolvido.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30010480,'Gouki, Ogro Trovão',replace(replace('2+ monstros "Gouki"	\r\nSe um ou mais monstros para os quais este card apontar forem destruídos em batalha ou por um efeito de card: você pode fazer com que este card ganhe 400 de ATK. \r\nO duelista do turno aplica o seguinte efeito enquanto este monstro estiver no campo.\r\n● Durante sua Fase Principal, ele pode Invocar por Invocação-Normal 1 monstro da sua mão em uma zona sua para a qual este card apontar, em adição à sua Invocação-Normal/Baixar padrão. \r\n(Ele só pode se aproveitar deste efeito uma vez por turno.)','\r',char(13)),'\n',char(10)),'Invocar pelo efeito de "Gouki, Ogro Trovão"','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30012506,'Núcleo de Assalto A',replace(replace('Uma vez por turno, você pode: escolher 1 monstro Máquina de LUZ que você controla; equipe este card no alvo, OU: desequipe este card e Invoque-o por Invocação-Especial. \r\nUm monstro equipado com este card não é afetado pelos efeitos de monstro do seu oponente (exceto seu próprio) e, além disso, se o monstro equipado seria destruído em batalha ou por um efeito de card, em vez disso, destrua este card. \r\nSe este card for enviado do campo para o Cemitério: você pode adicionar 1 outro monstro União do seu Cemitério à sua mão.','\r',char(13)),'\n',char(10)),'Equipar','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30013902,'Sombra de Solarsemente',replace(replace('Se você controlar um Monstro Normal Planta: você pode Invocar este card por Invocação-Especial da sua mão. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 monstro "Solaravalon" ou "Solarvinhas" linkado de Link-2 ou menos que você controla; Invoque por Invocação-Especial 1 monstro com o mesmo nome do seu Deck Adicional, mas negue seus efeitos e, além disso, você não pode Invocar por Invocação-Especial pelo resto deste turno, exceto monstros Planta. \r\nVocê só pode usar cada efeito de "Sombra de Solarsemente" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30037118,'Sarcoughagos Devoradores',replace(replace('Quando este card for destruído em batalha com um monstro do oponente: você pode tomar o controle desse monstro do oponente e, se isso acontecer, ele se torna um monstro Zumbi e, além disso, seu ATK/DEF se tornam 0. \r\nQuando um monstro Zumbi seu for destruído em batalha com um monstro do oponente, enquanto este card estiver no seu Cemitério: você pode banir este card; tome o controle desse monstro do oponente e, se isso acontecer, ele se torna um monstro Zumbi e, além disso, seu ATK/DEF se tornam 0. \r\nVocê só pode usar este efeito de "Sarcoughagos Devoradores" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30042158,'Ciberouroboros','Quando este card for removido de jogo, você pode enviar 1 card da sua mão para o Cemitério para comprar 1 card.','Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30064423,'Dragão Explosivo Topológico',replace(replace('2+ Monstros de Efeito	\r\nVocê não pode Invocar/Baixar monstros em nenhuma Zona de Monstros Adicional para a qual este card apontar. \r\nSe outro monstro for Invocado por Invocação-Especial em uma zona para a qual um Monstro Link apontar, enquanto este card estiver na Zona de Monstros Adicional: aplique 1 desses efeitos (mas você não pode aplicar o mesmo efeito de "Dragão Explosivo Topológico" novamente neste turno).\r\n● Embaralhe no Deck todos os outros monstros no campo.\r\n● Embaralhe no Deck todas as Magias/Armadilhas no campo.\r\n● Olhe o Deck Adicional do seu oponente e bana 1 card dele.','\r',char(13)),'\n',char(10)),'Ativar','Retornar todos os monstros ao Deck','Retornar todos os Cards de Magia/Armadilha ao Deck','Banir 1 card do Deck Adicional','','','','','','','','','','','','');
INSERT INTO texts VALUES(30068120,'Diabrete de Lâminas Afiadas',replace(replace('Se este card estiver no seu Cemitério: você pode colocar 1 card da sua mão no topo do Deck; Invoque este card por Invocação-Especial em Posição de Defesa. \r\nVocê só pode usar este efeito de "Diabrete de Lâminas Afiadas" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30068121,'Diabrete de Lâminas Afiadas',replace(replace('Se este card estiver no seu Cemitério: você pode colocar 1 card da sua mão no topo do Deck; Invoque este card por Invocação-Especial em Posição de Defesa. \r\nVocê só pode usar este efeito de "Diabrete de Lâminas Afiadas" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30068809,'Companheiras Adamancipador',replace(replace('Adicione 1 monstro "Adamancipador" do seu Deck à sua mão.\r\nSe este card está no seu Cemitério: você pode colocar 1 card da sua mão no topo do Deck; adicione este card à sua mão.\r\nVocê só pode usar cada um dos efeitos de "Companheiras Adamancipador" uma vez por turno.','\r',char(13)),'\n',char(10)),'Efeito de busca','Retornar para a mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30069398,'Muralha de Hera',replace(replace('VIRE: Invoque por Invocação-Especial 1 "Ficha de Hera" (Tipo Planta/TERRA/Nível 1/ATK 0/DEF 0) em Posição de Defesa no lado do campo do seu oponente. \r\nQuando esta Ficha for destruída, seu controlador sofre 300 de dano.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30069399,'Ficha de Hera','Invocado por Especial com o efeito "Muralha de Hera". Quando destruída, o controlador sofre 300 de dano.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30079770,'Dragão Chamejante Negro de Olhos Vermelhos',replace(replace('Este card é considerado como um Monstro Normal enquanto estiver com a face para cima no campo ou no Cemitério. \r\nEnquanto este card for um Monstro Normal no campo, você pode Invocá-lo por Invocação-Normal para fazer com que ele se torne um Monstro de Efeito com este efeito.\r\n● Se o cálculo de dano for realizado envolvendo este card, no final da Fase de Batalha: você pode causar dano ao seu oponente igual ao ATK original deste card.	\r\nVocê só pode usar este efeito de "Dragão Chamejante Negro de Olhos Vermelhos" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30086349,'Dragão Cometa Meteoro Negro',replace(replace('1 monstro "Olhos Vermelhos" de Nível 7 + 1 monstro Dragão de Nível 6	\r\nSe este card for Invocado por Invocação-Fusão: você pode enviar 1 monstro "Olhos Vermelhos" da sua mão ou do Deck para o Cemitério e, se isso acontecer, cause dano ao seu oponente igual à metade do ATK original desse monstro. \r\nSe este card for enviado da Zona de Monstros para o Cemitério: você pode escolher 1 Monstro Normal no seu Cemitério; Invoque-o por Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30090452,'Zanki','Sua espada desembainhada de forma ágil proporciona um dano rápido e letal.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30095833,'Dragão Xyz da Rebelião de Olhos Anômalos',replace(replace('Escala de Pêndulo = 4\r\n[ Efeito de Pêndulo ]\r\nDurante sua Fase Principal: você pode Invocar este card por Invocação-Especial e, depois, você pode associar 1 monstro de TREVAS do seu Cemitério a este card como matéria. \r\nVocê só pode usar este efeito de "Dragão Xyz da Rebelião de Olhos Anômalos" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\n2 Monstros Pêndulo de Nível 7	\r\nSe você puder Invocar por Invocação-Pêndulo de Nível 7, você pode Invocar este card com a face para cima do seu Deck Adicional por Invocação-Pêndulo. \r\nEste card não pode ser usado como matéria para uma Invocação-Xyz no turno em que foi Invocado por Invocação-Xyz. \r\nVocê pode desassociar 1 matéria deste card e, depois, escolha até 2 monstros que seu oponente controla com 3000 ou menos de ATK; destrua-os. \r\nVocê só pode usar este efeito de "Dragão Xyz da Rebelião de Olhos Anômalos" uma vez por turno. \r\nSe este card na Zona de Monstros for destruído: você pode colocar este card na sua Zona de Pêndulo.','\r',char(13)),'\n',char(10)),'','','Escolher um monstro de TREVAS no Cemitério como Matéria Xyz?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30100551,'Minerva, a Luminosa Exaltada',replace(replace('2 monstros de Nível 4	\r\nVocê pode desassociar 1 matéria deste card; envie os 3 cards do topo do seu Deck para o Cemitério e, depois, compre cards igual ao número de cards "Luminoso(a)" enviados para o Cemitério por este efeito. \r\nSe este card for destruído em batalha, ou se este card em posse do seu dono for destruído por um efeito de card do oponente: você pode enviar os 3 cards do topo do seu Deck para o Cemitério e, depois, você pode destruir cards no campo até o número de cards "Luminoso(a)" enviados para o Cemitério por este efeito. \r\nVocê só pode usar cada efeito de "Minerva, a Luminosa Exaltada" uma vez por turno.','\r',char(13)),'\n',char(10)),'Escolher um card no campo para destruir?','Enviar para o Cemitério e comprar','Enviar ao Cemitério e destruir','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30106950,'Suanni, Fogo de Yang Zing',replace(replace('Quando este card que você controla for destruído em batalha ou por um efeito de card e enviado para o seu Cemitério: você pode Invocar por Invocação-Especial 1 monstro "Yang Zing" do seu Deck em Posição de Defesa, exceto "Suanni, Fogo de Yang Zing". \r\nVocê só pode usar este efeito de "Suanni, Fogo de Yang Zing" uma vez por turno. \r\nUma vez por turno, durante a Fase Principal ou a Fase de Batalha do seu oponente, você pode: imediatamente depois que este efeito resolver, Invoque por Invocação-Sincro 1 Monstro Sincro, usando apenas monstros "Yang Zing" que você controla (este é um Efeito Rápido). \r\nUm Monstro Sincro que usou este card como uma Matéria Sincro ganha 500 de ATK e DEF.','\r',char(13)),'\n',char(10)),'Invocação Especial','O efeito de "Suanni, Fogo de Yang Zing" está sendo aplicado.','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30109445,'Companhia de Palhaços Dristy',replace(replace('2 Monstros de Ritual, de Fusão, Sincro, Xyz e/ou Pêndulo	\r\nSeus monstros Invocados por Invocação-Tributo podem realizar um segundo ataque durante cada Fase de Batalha. \r\nSe este card for oferecido como Tributo: você pode ativar 1 desses efeitos (mas você só pode usar cada efeito de "Companhia de Palhaços Dristy" uma vez por turno);\r\n● Devolva para o Deck Adicional todos os Monstros Link do campo e dos Cemitérios.\r\n● Cada duelista com uma mão embaralha toda sua mão no Deck e, depois, compra o mesmo número de cards embaralhados no Deck.','\r',char(13)),'\n',char(10)),'Efeito de Tributo','Retornar ao Deck','Comprar','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30113682,'O Juiz','Este guerreiro luta até o fim com a sua clava e nunca se rende.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30114823,'Codificar Gerador',replace(replace('Se um monstro Ciberso que você controla seria usado como Matéria Link para um monstro "Codificar Transmissor", este card na sua mão também pode ser usado como matéria. \r\nSe este card for enviado da mão ou do campo para o Cemitério como matéria para a Invocação-Link de um monstro "Codificar Transmissor": você pode enviar 1 monstro Ciberso com 1200 ou menos de ATK do seu Deck para o Cemitério, ou, se este card no campo foi usado como matéria, em vez disso, você pode adicionar esse card à sua mão. \r\nVocê só pode usar cada efeito de "Codificar Gerador" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Enviar do campo para o Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30118200,'Utensilhor Aspilefante',replace(replace('1 monstro "Utensilhor"	\r\nNão pode ser usado como Matéria Link no turno em que for Invocado por Invocação-Link. \r\nPode atacar diretamente enquanto não estiver co-linkado. \r\nVocê pode enviar 1 card da sua mão para o Cemitério e, depois, escolha 1 card que seu oponente controla; destrua-o. \r\nSe este card estiver co-linkado: você pode escolher 1 monstro na Zona de Monstros Principal do seu oponente; destrua-o. \r\nVocê só pode usar 1 efeito de "Utensilhor Aspilefante" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Descarte 1 card; destrua 1 card que seu oponente controla','Destrua 1 monstro que seu oponente controla','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30118701,'Todoroki, a Estrela Terrenaraio',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) ao enviar 1 outro monstro da sua mão para o Cemitério, mas este card perde 500 de ATK. \r\nVocê só pode Invocar "Todoroki, a Estrela Terrenaraio" por Invocação-Especial uma vez por turno desta forma. \r\nDurante a Fase de Batalha (Efeito Rápido): você pode pagar 500 PV; Invoque por Invocação-Fusão 1 Monstro de Fusão Guerreiro do seu Deck Adicional, usando monstros da sua mão ou do campo como matéria. \r\nVocê só pode usar este efeito de "Todoroki, a Estrela Terrenaraio" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30118811,'Cópia @Ignister',replace(replace('Se você controlar um monstro Ciberso que foi Invocado por Invocação-Especial do Deck Adicional: você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 monstro Ciberso de TREVAS do seu Deck à sua mão, exceto "Cópia @Ignister" e, depois, descarte 1 card. \r\nVocê só pode usar cada efeito de "Cópia @Ignister" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Efeito de busca','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30123142,'Assalto Sincro','O monstro Invocado por Invocação-Sincro escolhido ganha 500 de ATK para cada Monstro-Matéria Sincro usado para Invocá-lo até a Fase Final.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30126992,'Diábolos Raio-de-Luz',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nVocê primeiro deve Invocá-lo por Invocação-Especial (da sua mão) ao ter 5 ou mais monstros de LUZ com nomes diferentes no seu Cemitério. \r\nUma vez por turno: você pode banir 1 monstro de LUZ do seu Cemitério e, depois, escolher 1 card Baixado que seu oponente controla; revele o alvo e, depois, coloque o alvo no topo ou no fundo do Deck.','\r',char(13)),'\n',char(10)),'Retornar ao Deck','Coloque no topo do Deck','Coloque no fundo do Deck','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30127518,'Queda Obscura','Quando seu oponente Invocar por Invocação-Especial 2 ou mais monstros com a face para cima ao mesmo tempo: envie esses monstros para o Cemitério e, depois, envie para o Cemitério todos os monstros na mão e no Deck do oponente que tenham o mesmo nome que os monstros enviados para o Cemitério por este efeito.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30128445,'Transcendossauro Perfurygnathus',replace(replace('2 monstros de Nível 6	\r\nEnquanto este card não tiver matérias, se ele batalhar um monstro, qualquer dano de batalha que ele causar ao seu oponente é dobrado. \r\nVocê só pode usar cada um dos seguintes efeitos de "Transcendossauro Perfurygnathus" uma vez por turno. \r\nVocê pode desassociar 1 matéria deste card e, depois, escolha 1 de seus monstros Dinossauro banidos; Invoque-o por Invocação-Especial. \r\nSe este card for destruído: você pode embaralhar no Deck 1 Monstro Normal do seu Cemitério e, depois, você pode Invocar este card por Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','Invocar este card por Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30131474,'Fornecedor Callibre',replace(replace('Durante cada Fase de Apoio, se você controlar um Monstro Link "Callibre": você pode escolher 1 monstro "Foguette" no seu Cemitério; Invoque-o por Invocação-Especial, mas destrua-o durante a Fase Final. \r\nVocê só pode usar este efeito de "Fornecedor Callibre" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30138615,'Restrição do Olho do Pesadelo',replace(replace('2 monstros com Tipos diferentes (Demônio, Ilusão ou Mago)	\r\nSe este card for Invocado por Invocação-Especial, ou no final da Fase de Batalha, se este card batalhar: você pode equipar 1 monstro que seu oponente controla a este card como uma Magia de Equipamento. \r\nVocê só pode usar este efeito de "Restrição do Olho do Pesadelo" uma vez por turno. \r\nGanha ATK igual ao ATK combinado dos monstros equipados a este card por seu efeito. \r\nSe este card batalhar um monstro, nenhum deles pode ser destruído por essa batalha. \r\nOs monstros do seu oponente não podem atacar nenhum monstro, exceto este.','\r',char(13)),'\n',char(10)),'Equipar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30155789,'Poção Brutal',replace(replace('Este card se torna um Card de Equipamento e equipa 1 monstro que você controla. \r\nUma vez por turno, quando você causar dano ao seu oponente com um efeito de card, o monstro equipado ganha 1000 de ATK até a Fase Final.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30163008,'Ra''ten, o General Celestial',replace(replace('2+ monstros com o mesmo Tipo	\r\nUma vez por turno, durante a Fase de Apoio: você pode escolher 1 monstro com a face para cima para o qual este card apontar; Invoque por Invocação-Especial 1 monstro de Nível 4 ou menos, com o mesmo Tipo que o desse monstro, da sua mão em uma zona sua para a qual este card apontar. \r\nNo começo da Fase de Batalha: você pode escolher 1 card que seu oponente controla; destrua-o. \r\nVocê só pode usar este efeito de "Ra''ten, o General Celestial" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30170981,'Mensagem do Espírito "L"','Este card só pode ser colocado no campo pelo efeito de "Tábua do Destino".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30190809,'Gear Golen a Fortaleza Móvel','Uma vez por turno, durante sua Fase Principal 1: você pode pagar 800 PV; este card pode atacar seu oponente diretamente neste turno.','Ataque direto','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30194529,'Ningirsu, o Guerreiro do Cálice Mundial',replace(replace('2+ Monstros Link	\r\nSe este card for Invocado por Invocação-Link: compre cards igual ao número de monstros "Cálice Mundial" para os quais este card apontar. \r\nVocê só pode usar este efeito de "Ningirsu, o Guerreiro do Cálice Mundial" uma vez por turno. \r\nUma vez por turno: você pode enviar 1 card do campo de cada duelista para os Cemitérios. \r\nSe este card for enviado do campo para o Cemitério: você pode Invocar por Invocação-Especial 1 monstro "Cálice Mundial" da sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30208479,'Mago do Caos das Trevas','Você pode Invocar este card por Invocação-Ritual com "Ritual de Magia Negra".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30213599,'Descendente do Coveiro','Você pode oferecer como Tributo 1 outro monstro "do Coveiro" com a face para cima para escolher 1 card que seu oponente controla; destrua o alvo.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30221870,'Senhormek Imperador Wisel - Absorção Sincro',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial por seu próprio efeito. \r\nDurante o turno do seu oponente (Efeito Rápido): você pode enviar 1 monstro "Senhormek" com a face para cima que você controla para o Cemitério; Invoque este card por Invocação-Especial da sua mão. \r\nVocê só pode usar este efeito de "Senhormek Imperador Wisel - Absorção Sincro" uma vez por turno. \r\nSe este card for Invocado por Invocação-Especial: você pode escolher 1 monstro que seu oponente controla; ele não pode atacar pelo resto deste turno. \r\nQuando um card ou efeito for ativado que destruiria um ou mais cards no campo (Efeito Rápido): você pode oferecer este card como Tributo; negue a ativação e, se isso acontecer, destrua esse card.','\r',char(13)),'\n',char(10)),'','Os monstros do seu oponente não podem atacar','Negar a ativação e destruir','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30227494,'Rastreador Psíquico',replace(replace('Se você controlar um monstro de Nível 3 que não seja "Rastreador Psíquico", você pode Invocar este card por Invocação-Especial (da sua mão) em Posição de Defesa. \r\nVocê só pode Invocar "Rastreador Psíquico" por Invocação-Especial uma vez por turno desta forma. \r\nUm Monstro Sincro que usou este card como matéria ganha 600 de ATK.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30230789,'Mercador Karakuri mod. 177 "Inashichi"',replace(replace('Este card deve atacar, se possível. \r\nQuando este card com a face para cima em Posição de Ataque no campo for selecionado como alvo de um ataque, mude-o para Posição de Defesa. \r\nQuando este card for Invocado por Invocação-Normal, adicione 1 card "Karakuri" do seu Deck para a sua mão.','\r',char(13)),'\n',char(10)),'Mudar para Posição de Defesa','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30241314,'Macrocosmo',replace(replace('Quando este card for ativado: você pode Invocar por Invocação-Especial 1 "Hélios - O Sol Primordial" da sua mão ou do Deck. \r\nEnquanto este card estiver com a face para cima no campo, qualquer card enviado para o Cemitério, em vez disso, é banido.','\r',char(13)),'\n',char(10)),'Invocação Especial?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30243636,'Hambúrguer Esfomeado','Você pode Invocar este card por Invocação-Ritual com "Receita do Hambúrguer".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30270176,'Nova Carmesim, o Senhor Cúbico Obscuro',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao revelar 3 outros cards "Cúbico(a)" com nomes diferentes na sua mão e não pode ser Invocado por Invocação-Especial de nenhuma outra forma. \r\nNão é afetado pelos efeitos ativados de outros monstros cujo ATK original seja 3000 ou menos. \r\nQuando este card atacante destruir um monstro em batalha: você pode ativar este efeito; este card pode realizar um segundo ataque durante esta Fase de Batalha. \r\nDurante sua Fase Final: cada duelista sofre 3000 de dano. \r\nVocê só pode usar este efeito de "Nova Carmesim, o Senhor Cúbico Obscuro" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30271097,'O Caído e a Virtuosa',replace(replace('(Este card deve ser sempre considerado como um card "Marcado" e "Dogmatika".)	\r\nAtive 1 desses efeitos;\r\n● Envie 1 monstro que mencione "Caído de Arbaz" do seu Deck Adicional para o Cemitério e, depois, escolha 1 card com a face para cima no campo; destrua-o.\r\n● Se você tiver um monstro "Ecclesia" no seu campo ou Cemitério: escolha 1 monstro em qualquer Cemitério; Invoque-o por Invocação-Especial no seu campo.	\r\nVocê só pode ativar 1 "O Caído e a Virtuosa" por turno.','\r',char(13)),'\n',char(10)),'Ativar','Destruir','Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30275298,'Dragão Final Cibernético, o Dragão do Golpe Decisivo',replace(replace('3 monstros Máquina com 2100 ou mais de ATK	\r\nDeve ser Invocado por Invocação-Fusão.\r\nSe este card for Invocado por Invocaçã-Fusão usando apenas monstros de LUZ: você pode pagar 4000 PV; adicione 1 "Remover Limites" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Dragão Final Cibernético, o Dragão do Golpe Decisivo" uma vez por turno.\r\nSe este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante.\r\nEste card cujo ATK atual for maior que seu ATK original pode realizar um segundo e terceiro ataque durante cada Fase de Batalha.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30275299,'Dragão Final Cibernético, o Dragão do Golpe Decisivo',replace(replace('3 monstros Máquina com 2100 ou mais de ATK	\r\nDeve ser Invocado por Invocação-Fusão.\r\nSe este card for Invocado por Invocaçã-Fusão usando apenas monstros de LUZ: você pode pagar 4000 PV; adicione 1 "Remover Limites" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Dragão Final Cibernético, o Dragão do Golpe Decisivo" uma vez por turno.\r\nSe este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante.\r\nEste card cujo ATK atual for maior que seu ATK original pode realizar um segundo e terceiro ataque durante cada Fase de Batalha.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30276969,'Reese, a Senhora do Gelo','Este card não pode ser destruído em batalha com um monstro de Nível 4 ou mais.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30284022,'Fantoches do Mundo Negro',replace(replace('Escolha até 3 cards em quaisquer Cemitérios; bana-os e, depois, descarte 1 monstro Demônio. \r\nDurante sua Fase Principal, exceto no turno em que este card foi enviado para o Cemitério: você pode banir este card do seu Cemitério e, depois, escolha 1 dos seus monstros Demônio banidos; adicione-o à sua mão. \r\nVocê só pode ativar 1 "Fantoches do Mundo Negro" por turno.','\r',char(13)),'\n',char(10)),'Banir cards de ambos os Cemitérios','Recuperar monstros banidos','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30286474,'Gouki, O Mestre Ogro',replace(replace('2+ monstros "Gouki"	\r\nUma vez por turno (Efeito Rápido): você pode devolver para a mão qualquer número de monstros "Gouki" que você controla para os quais este card apontar e, depois, escolher o mesmo número de cards com a face para cima que seu oponente controla; eles têm seus efeitos negados até o final deste turno. \r\nEste card pode atacar todos os monstros que seu oponente controla, uma vez cada. \r\nSe seu oponente controlar um ou mais monstros com a face para cima, este card só pode escolher como alvo de ataques o monstro dele com o maior ATK (em caso de empate, você seleciona).','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30291086,'Regulador Mental',replace(replace('Você pode ativar 1 desses efeitos;\r\n● Bana até 1 monstro de LUZ e até 1 monstro de TREVAS da sua mão e/ou do Cemitério; até o final deste turno, aumente ou diminua o Nível deste card pelo número exato de banidos.\r\n● Escolha até 2 dos seus monstros banidos (1 de LUZ e/ou 1 de TREVAS); devolva-os para o Cemitério e, se isso acontecer, até o final deste turno, aumente ou diminua o Nível deste card pelo número exato de devolvidos.	\r\nVocê só pode usar este efeito de "Regulador Mental" uma vez por turno.','\r',char(13)),'\n',char(10)),'Banir um monstro da mão/do Cemitério','Recuperar monstros banidos','Aumentar o Nível','Reduzir o Nível','','','','','','','','','','','','');
INSERT INTO texts VALUES(30299166,'Lombriga Tentáculos','Uma vez por turno, você pode remover de jogo 1 monstro "Lombriga" do Tipo Réptil no seu Cemitério para permitir que este card ataque duas vezes durante a mesma Fase de Batalha.','Atacar duas vezes','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30303854,'Arqueiro Laval',replace(replace('Se este card for Invocado por Invocação-Normal: durante sua Fase Principal neste turno, você pode Invocar por Invocação-Normal 1 monstro "Laval", em adição à sua Invocação-Normal/Baixar (padrão) (você só pode se aproveitar deste efeito uma vez por turno). \r\nSe este card estiver no seu Cemitério: você pode escolher 1 monstro de FOGO que você controla; destrua-o e, se isso acontecer, Invoque este card por Invocação-Especial em Posição de Defesa, mas bana-o quando ele deixar o campo e, além disso, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros de FOGO. \r\nVocê só pode usar este efeito de "Arqueiro Laval" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30312361,'Fantasma do Caos',replace(replace('Seu oponente não sofre dano de batalha dos ataques envolvendo este card. \r\nUma vez por turno: você pode escolher 1 Monstro de Efeito no seu Cemitério; bana o alvo e, se isso acontecer, até a Fase Final, o nome e o ATK original deste card se tornam o nome e o ATK original desse monstro, e troque este efeito pelos efeitos originais desse monstro.','\r',char(13)),'\n',char(10)),'Copiar efeito','Encerrar o efeito copiado','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30314994,'Dragão do Elemento',replace(replace('Este monstro obtém o(s) seguinte(s) efeito(s) enquanto existir(em) monstro(s) com o seguinte Atributo no Campo.\r\n● FOGO: Aumente o ATK deste card em 500 pontos.\r\n● VENTO: Se este card destruir um monstro como resultado de um combate, este card pode atacar mais uma vez logo em seguida.','\r',char(13)),'\n',char(10)),'Continuar atacando','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30325729,'Dokuroyaiba','Um bumerangue com cérebro que perseguirá um alvo até os confins da terra.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30327674,'Bruxa do Caos',replace(replace('Você pode oferecer este card como Tributo; Invoque por Invocação-Especial 2 "Ficha de Besta Negra" (Demônio/TREVAS/Nível 2/ATK 1000/DEF 500). \r\nSe este card for banido da mão ou do Cemitério: você pode Invocar por Invocação-Especial 2 "Ficha de Besta de Luz" (Fada/Regulador/LUZ/Nível 2/ATK 500/DEF 1000). \r\nVocê só pode usar 1 efeito de "Bruxa do Caos" por turno e apenas uma vez por turno e, além disso, você não pode Invocar monstros por Invocação-Especial do Deck Adicional, exceto Monstros Sincro de LUZ ou de TREVAS, no turno em que você ativar qualquer um desses efeitos.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30327675,'Ficha de Besta Negra','Invocado por Especial com o efeito "Bruxa do Caos".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30327676,'Ficha de Besta de Luz','Invocado por Especial com o efeito "Bruxa do Caos".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30328508,'Escamado Sombraneco',replace(replace('VIRE: Você pode escolher 1 monstro no campo; destrua-o.\r\nSe este card for enviado para o Cemitério por um efeito de card: você pode enviar 1 card "Sombraneco" do seu Deck para o Cemitério, exceto "Escamado Sombraneco". \r\nVocê só pode usar 1 efeito de "Escamado Sombraneco" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Destruir um monstro','Enviar para o Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30334522,'Gishki Psiquelone',replace(replace('Você pode Invocar este card por Invocação-Ritual com qualquer Card de Magia de Ritual "Gishki". \r\nUma vez por turno: você pode declarar 1 Tipo de Monstro e Atributo; olhe 1 card aleatório da mão do seu oponente e, se for um monstro do Tipo e Atributo declarados, embaralhe-o no Deck. \r\nCaso contrário, volte-o para a mão.','\r',char(13)),'\n',char(10)),'Declarar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30336082,'Invocação Sangen',replace(replace('Durante sua Fase Principal 1, monstros Dragão de FOGO que você controla não são afetados pelos efeitos ativados do seu oponente. \r\nDurante sua Fase Principal: você pode adicionar 1 monstro "Dragão Tenpai" do seu Deck à sua mão e, depois, descarte 1 card. \r\nVocê só pode usar este efeito de "Invocação Sangen" uma vez por turno. \r\nSe este card for destruído durante a Fase de Batalha: você pode escolher 1 Monstro Sincro Dragão que você controla; dobre o ATK dele.','\r',char(13)),'\n',char(10)),'','Adicionar à mão','Dobre o ATK dele','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30338466,'Insígnia Bujin - A Espada',replace(replace('Ative 1 desses efeitos.\r\n● Escolha 1 monstro "Bujin" no seu Cemitério; adicione o alvo para a sua mão.\r\n● Escolha 1 dos seus monstros "Bujin" banidos; envie o alvo para o Cemitério.','\r',char(13)),'\n',char(10)),'Recuperar do Cemitério','Retornar os cards banidos ao Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30339825,'Hydor, o Princípio de Todas as Coisas',replace(replace('Escolha 1 monstro em qualquer Cemitério; destrua 1 monstro de ÁGUA no campo do dono do alvo e, se isso acontecer, Invoque o alvo por Invocação-Especial nesse campo em Posição de Defesa. \r\nSe este card estiver no seu Cemitério, exceto no turno em que foi enviado para lá: você pode banir este card e, depois, escolha 1 monstro de ÁGUA em qualquer Cemitério; destrua 1 monstro no campo do dono do monstro alvo e, se isso acontecer, Invoque por Invocação-Especial esse monstro alvo em Posição de Defesa nesse campo. \r\nVocê só pode usar 1 efeito de "Hydor, o Princípio de Todas as Coisas" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar','Banir e ativar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30341772,'Utopia Buster','Se você controlar um monstro "Utopia": destrua o 1 monstro com a face para cima que seu oponente controla com o menor ATK (em caso de empate, você escolhe) e, se isso acontecer, cause dano ao seu oponente igual ao ATK que o monstro destruído tinha no campo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30342076,'Decodificar Link',replace(replace('1 monstro Ciberso de Nível 4 ou menos	\r\nSe este card for enviado para o Cemitério como matéria para um Monstro Link Ciberso com 2300 ou mais de ATK original: você pode Invocar este card por Invocação-Especial, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar este efeito de "Decodificar Link" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30348744,'T.G. Peixe Broca',replace(replace('Este card pode atacar diretamente. \r\nVocê só pode usar cada um dos seguintes efeitos de "T.G. Peixe Broca" uma vez por turno.\r\n● Se todos os monstros que você controla forem monstros "T.G." (mín. 1): você pode Invocar este card por Invocação-Especial da sua mão.\r\n● Quando um monstro "T.G." que você controla causar dano de batalha ao seu oponente: você pode escolher 1 monstro que seu oponente controla; destrua-o.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30350202,'Eclipse, Dragão Soberano das Catástrofes',replace(replace('2 monstros Dragão de Nível 7	\r\nSe este card for Invocado por Invocação-Xyz: você pode escolher 1 monstro "Dragão Soberano" de Nível 4 ou menos no seu Cemitério ou banimento; Invoque por Invocação-Especial 1 monstro "Dragão Soberano" de Nível/Classe 7 que seja mencionado no monstro alvo do seu Deck ou banimento e, depois, embaralhe o monstro alvo no Deck. \r\nQuando seu oponente ativar um Card de Magia/Armadilha ou seus efeitos (Efeito Rápido): você pode desassociar 2 matérias deste card; negue a ativação e, se isso acontecer, bana esse card. \r\nVocê só pode usar cada efeito de "Eclipse, Dragão Soberano das Catástrofes" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Negar a ativação','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30353551,'Human-Wave Tactics','Uma vez por turno, durante a Fase Final, se um ou mais dos seus Monstros Normais de Nível 2 ou menos foram destruídos em batalha neste turno: Invoque por Invocação-Especial Monstros Normais de Nível 2 ou menos do seu Deck, igual ao número dos seus Monstros Normais de Nível 2 ou menos destruídos em batalha neste turno.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30373970,'Dragão de Miasma Tistina',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 monstro "Tistina" do seu Deck à sua mão, exceto "Dragão de Miasma Tistina" e, além disso, pelo resto deste turno, monstros "Tistina" de LUZ que você controla ganham 1000 de ATK. \r\nSe este card for enviado para o Cemitério, e um card estiver na Zona do Campo: você pode Invocar este card por Invocação-Especial e, além disso, você não pode Invocar por Invocação-Especial da mão ou do Cemitério pelo resto deste turno, exceto monstros "Tistina". \r\nVocê só pode usar cada efeito de "Dragão de Miasma Tistina" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30382214,'Flor Cardian de Cerejeira',replace(replace('Se você controlar um monstro "Flor Cardian" de Nível 2 ou menos: você pode Invocar este card por Invocação-Especial da sua mão e, além disso, você não pode Invocar monstros por Invocação-Normal ou Especial pelo resto deste turno, exceto monstros "Flor Cardian". \r\nUma vez por turno: você pode oferecer como Tributo 1 monstro "Flor Cardian"; compre 1 card e, se isso acontecer, mostre-o e, depois, se ele for um monstro "Flor Cardian", você pode pegar 1 monstro "Flor Cardian" do seu Deck, exceto "Flor Cardian de Cerejeira", e adicioná-lo à sua mão ou Invocá-lo por Invocação-Especial. \r\nCaso contrário, envie o card que você comprou para o Cemitério.','\r',char(13)),'\n',char(10)),'Adicionar o monstro "Flor Cardian" à sua mão ou Invocá-lo por Invocação Especial?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30392583,'Ritual de Premonição',replace(replace('Este card é usado para a Invocação-Ritual de "Princesa da Premonição Tarotrei". \r\nVocê também deve oferecer como Tributo monstros da sua mão ou do campo cuja soma dos Níveis seja igual a 9 ou mais. \r\nDurante sua Fase Principal, exceto no turno em que este card foi enviado para o Cemitério: você pode banir este card do seu Cemitério; adicione 1 monstro "Princesa da Premonição" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30394645,'Portador da Lei Dogmatika',replace(replace('Se um monstro Invocado por Invocação-Especial do Deck Adicional estiver no campo e este card estiver na sua mão: você pode Invocar este card por Invocação-Especial. \r\nSe este card for Invocado por Invocação-Especial da mão: você pode fazer com que cada duelista envie 1 monstro do Deck Adicional dele para o Cemitério. \r\nSe este card for enviado para o Cemitério: você pode escolher 1 card "Dogmatika" no seu Cemitério, exceto "Portador da Lei Dogmatika"; adicione-o à sua mão. \r\nVocê só pode usar cada efeito de "Portador da Lei Dogmatika" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Enviar para o Cemitério','Recuperar','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30397786,'Dragão Branco de Olhos Azuis, o Fantasma Branco',replace(replace('Quando um card ou efeito é ativado que escolha este card no campo (Efeito Rápido): você pode descartar 1 card; negue aquele efeito.\r\nVocê só pode usar cada um dos seguintes efeitos de "Dragão Branco de Olhos Azuis, o Fantasma Branco" uma vez por turno.\r\nQuando este card é adicionado do seu Deck à sua mão, ou seu monstro é destruído por batalha: você pode revelar este card na sua mão; Invoque-o por Invocação-Especial.\r\nSe este card for Invocado por Invocação-Especial da sua mão ou Deck: você pode destruir todos os monstros que seu oponente controla, você também só pode ataca-lo com diretamente com monstros "Olhos Azuis" neste turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Destruir','Negar o efeito','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30397787,'Dragão Branco de Olhos Azuis, o Fantasma Branco',replace(replace('Quando um card ou efeito é ativado que escolha este card no campo (Efeito Rápido): você pode descartar 1 card; negue aquele efeito.\r\nVocê só pode usar cada um dos seguintes efeitos de "Dragão Branco de Olhos Azuis, o Fantasma Branco" uma vez por turno.\r\nQuando este card é adicionado do seu Deck à sua mão, ou seu monstro é destruído por batalha: você pode revelar este card na sua mão; Invoque-o por Invocação-Especial.\r\nSe este card for Invocado por Invocação-Especial da sua mão ou Deck: você pode destruir todos os monstros que seu oponente controla, você também só pode ataca-lo com diretamente com monstros "Olhos Azuis" neste turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Destruir','Negar o efeito','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30398342,'Criação Yang Zing',replace(replace('Uma vez por turno, se um ou mais monstros que você controla forem destruídos em batalha ou por um efeito de card: você pode Invocar por Invocação-Especial 1 monstro "Yang Zing" do seu Deck. \r\nVocê não pode Invocar monstros do Deck Adicional por Invocação-Especial, exceto Monstros Sincro.','\r',char(13)),'\n',char(10)),'Ativar e aplicar o primeiro Efeito','Ativar, mas não resolver o efeito','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30399511,'Projetista de Poder Genex','Quando este card for Invocado por Invocação-Normal: você pode adicionar 1 Monstro de Efeito "Genex" de Nível 3 do seu Deck à sua mão.','Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30411385,'Valquíria-Zweite',replace(replace('Se este card for Invocado: você pode escolher 1 monstro que seu oponente controla; destrua-o. \r\nDepois do cálculo de dano, se este card batalhou: você pode escolher 1 Magia Contínua no seu Cemitério; adicione-a à sua mão. \r\nVocê só pode usar cada efeito de "Valquíria-Zweite" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30426226,'Reveseróiroo','Se você controlar o mesmo número de monstros que seu oponente, troque o controle de todos esses monstros.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30430448,'Maldições Congelantes Rúnikas',replace(replace('Ative 1 desses efeitos, mas pule sua próxima Fase de Batalha depois da ativação;\r\n● Escolha 1 Monstro de Efeito que seu oponente controla; negue seus efeitos (até o final deste turno) e, depois, bana os 3 cards do topo do Deck do seu oponente.\r\n● Invoque por Invocação-Especial 1 monstro "Rúnika(o)" do seu Deck Adicional na Zona de Monstros Adicional.	\r\nVocê só pode ativar 1 "Maldições Congelantes Rúnikas" por turno.','\r',char(13)),'\n',char(10)),'Negar um monstro','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30432463,'Dimonno Vaalmônica',replace(replace('Escala de Pêndulo = 5\r\n[ Efeito de Pêndulo ]\r\nSempre que você sofrer dano de efeito enquanto você controlar um Card de Monstro Fada na sua outra Zona de Pêndulo, coloque 1 Marcador de Ressonância neste card. \r\nMonstros que seu oponente controla perdem 100 de ATK para cada Marcador de Ressonância no seu campo.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe este card estiver na sua mão: você pode descartar 1 outro card; pegue 1 "Angello Vaalmônica" do seu Deck e coloque este card e esse card nas suas Zonas de Pêndulo. \r\nDurante sua Fase Principal, se este card foi Invocado por Invocação-Normal ou Especial neste turno: você pode banir 1 Magia/Armadilha Normal "Vaalmônica" do seu Cemitério; aplique qualquer efeito nesse card que inclua sofrer dano. \r\nVocê só pode usar cada efeito de "Dimonno Vaalmônica" uma vez por turno.','\r',char(13)),'\n',char(10)),'Coloque esta carta e "Angello Vaalmônica" do seu Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30435145,'Fábrica do Mecanismo Antigo','Revele 1 monstro "Mecanismo Antigo" de Nível 5 ou mais da sua mão e, depois, bana um número de monstros "Mecanismo Antigo" do seu Cemitério cujos Níveis combinados sejam o dobro do monstro revelado e, se isso acontecer, se você Invocar por Invocação-Normal o monstro revelado neste turno, você deve Invocá-lo por Invocação-Normal sem oferecer Tributo.','Invocar por Invocação Normal sem Tributo','Escolha um monstro cujo nome inclua "Mecanismo Antigo"','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30439101,'Melffy da Floresta',replace(replace('2 monstros de Nível 2	\r\nVocê pode desassociar 1 matéria deste card; adicione 1 card "Melffy" do seu Deck à sua mão. \r\nSe outro monstro "Melffy" com a face para cima que você controla voltar à sua mão (exceto durante a Etapa de Dano): você pode escolher 1 monstro com a face para cima que seu oponente controla; ele não pode atacar e, além disso, seus efeitos são negados enquanto ele estiver com a face para cima no campo. \r\nVocê só pode usar cada efeito de "Melffy da Floresta" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30450531,'Ritual do Espírito',replace(replace('Escolha 1 monstro "do Coveiro" no seu Cemitério; Invoque o alvo por Invocação-Especial. \r\nA ativação e o efeito deste card não são afetados por "Necro-Vale".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30451366,'Ovelha Mística nº 1',replace(replace('Você pode substituir este card por qualquer 1 Monstro-Matéria de Fusão. \r\nQuando fizer isso, os outros Monstros-Matéria de Fusão devem ser os corretos.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30453613,'Despertar de Veidos',replace(replace('Coloque 1 "Obsidim, a Cidade Cinzenta" do seu Deck com a face para cima em qualquer Zona do Campo e, depois, se seu oponente controlar um card na Zona do Campo dele, você pode adicionar 1 monstro Piro de TREVAS de Nível 5 ou mais do seu Deck à sua mão. \r\nPelo resto deste turno depois que este card resolver, você não pode Invocar por Invocação-Especial do Deck ou Deck Adicional, exceto monstros Piro. \r\nVocê só pode ativar 1 "Despertar de Veidos" por turno.','\r',char(13)),'\n',char(10)),'','Coloque-o na sua Zona de Campo','Coloque-o na Zona de Campo do seu oponente','Adicionar 1 monstro do seu Deck à sua mão?','','','','','','','','','','','','');
INSERT INTO texts VALUES(30459350,'Barreira de Ferro Imperial','Nenhum duelista pode banir cards.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30461781,'Legado de Yata-Garasu',replace(replace('Ativar 1 destes efeitos:\r\n● Compre 1 card.\r\n● Ative apenas se o oponente controlar um monstro Espírito com a face para cima.	\r\nCompre 2 cards.','\r',char(13)),'\n',char(10)),'Comprar 1 card','Compre 2 cards','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30464153,'Uminotauro','Se um monstro do Tipo Peixe, Serpente Marinha ou Aqua que você controla atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30488793,'Força Contrária','Quando o ataque de um monstro que escolheu como alvo um monstro com a face para cima em Posição de Ataque for negado: Cause dano ao seu oponente igual à diferença em ATK entre os 2 monstros.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30492798,'Djinn, o Disserere de Rituais',replace(replace('Quando você Invocar um monstro por Invocação-Ritual, você pode banir este card do seu Cemitério como 1 dos monstros necessários para a Invocação-Ritual. \r\nO monstro Invocado por Invocação-Ritual usando este card não é afetado por efeitos de Armadilha.','\r',char(13)),'\n',char(10)),'O efeito de "Djinn, o Disserere de Rituais" está sendo aplicado.','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30494314,'Oni Ruivo','Quando este card for Invocado por Invocação-Especial do Cemitério pelo efeito de um monstro do Tipo Zumbi: Você pode escolher 1 monstro do Tipo Zumbi com a face para cima que você controla; desassocie 1 Matéria Xyz de um monstro no campo e, se isso acontecer, aumente o Nível do monstro escolhido em 1 e o ATK dele em 300 (mesmo se as condições de escolha não estiverem mais corretas.)','Aumentar Nível e ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30500113,'Ataqueraptor - Retorno',replace(replace('Se um monstro "Ataqueraptor" que você controla for destruído em batalha: escolha 1 monstro "Ataqueraptor" no seu Cemitério; adicione-o à sua mão. \r\nSe um ou mais monstros "Ataqueraptor" com a face para cima que você controla forem destruídos por um efeito de card: você pode banir este card do seu Cemitério; adicione 1 card "Ataqueraptor" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Ataqueraptor - Retorno" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30502181,'Rapieira Luminoso',replace(replace('Só pode ser equipado a um monstro "Luminoso". \r\nEle ganha 700 de ATK. \r\nQuando este card for enviado do seu Deck para o Cemitério: você pode escolher 1 monstro "Luminoso" que você controla; equipe este card ao alvo.','\r',char(13)),'\n',char(10)),'Equipar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30525991,'Médico Feiticeiro Espartano','Cause 500 de dano ao seu oponente sempre que um ou mais monstros forem Invocados por Invocação-Especial do Deck de qualquer duelista.','Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30531525,'Habitação Encantadora','Pague 800 PV; escave os 4 cards do topo do seu Deck e Invoque por Invocação-Especial todos os Monstros Normais escavados de Nível 3 ou menos e, além disso, depois, embaralhe o resto de volta no seu Deck.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30532390,'Batedor Celeste','Com os olhos de um falcão e uma velocidade de voo que excede Mach 5, este monstro é um mestre dos céus.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30537973,'Predaplanta Orquídea Aranha',replace(replace('Escala de Pêndulo = 8\r\n[ Efeito de Pêndulo ]\r\nDurante sua Fase Principal, se este card foi ativado neste turno: você pode escolher 1 outro card com a face para cima na Zona de Magias & Armadilhas; destrua-o. \r\nVocê só pode usar este efeito de "Predaplanta Orquídea Aranha" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nDurante a Fase Final, se este card foi Invocado por Invocação-Normal ou Especial neste turno: você pode descartar 1 monstro Planta; adicione 1 monstro Planta de Nível 4 ou menos do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Predaplanta Orquídea Aranha" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30539496,'Verdadeiro Rei Lithosagym, o Desastre',replace(replace('Se este card estiver na sua mão: você pode destruir 2 outros monstros na sua mão e/ou no campo com a face para cima, incluindo um monstro de TERRA e, se isso acontecer, Invoque este card por Invocação-Especial e, se isso acontecer, e os dois monstros destruídos eram de TERRA, você também pode olhar o Deck Adicional do seu oponente e banir até 3 monstros com nomes diferentes. \r\nSe este card for destruído por um efeito de card: você pode Invocar por Invocação-Especial 1 monstro Wyrm que não seja de TERRA do seu Cemitério. \r\nVocê só pode usar cada efeito de "Verdadeiro Rei Lithosagym, o Desastre" uma vez por turno.','\r',char(13)),'\n',char(10)),'Se um monstro TERRA for destruído, Invoque este card por Invocação Especial','Invocar um monstro Wyrm por Invocação Especial','Banir um monstro do Deck Adicional do seu oponente?','Continuar selecionando monstros para banir?','','','','','','','','','','','','');
INSERT INTO texts VALUES(30548775,'Ramo!','Quando um ou mais Monstros de Fusão no campo forem destruídos em batalha ou por um efeito de card e enviados para o Cemitério: você pode escolher 1 das Matérias de Fusão no seu Cemitério que foi usada para a sua Invocação-Fusão; Invoque-o por Invocação-Especial.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30552375,'Bastão Grade',replace(replace('Só pode ser equipado a um monstro Ciberso que você controla. \r\nEle ganha 300 de ATK, não é afetado pelos efeitos de card do seu oponente e, além disso, na primeira vez que ele seria destruído em batalha a cada turno, ele não é destruído. \r\nSe este card no campo com a face para cima for destruído e enviado para o Cemitério: você pode ativar este efeito; até o final deste turno, monstros Ciberso que você controla atualmente não podem ser destruídos em batalha ou por efeitos de card.','\r',char(13)),'\n',char(10)),'Todos os monstros Ciberso não podem ser destruídos','O efeito de "Bastão Grade" está sendo aplicado.','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30562585,'ZERO-MÁXIMO',replace(replace('Só pode ser ativado se você não tiver nenhum card na sua mão. \r\nSelecione 1 monstro "Inférnico(a)" no seu Cemitério. \r\nInvoque-o por Invocação-Especial e destrua todos os monstros com a face para cima no campo com ATK menor que o ATK do monstro Invocado por Invocação-Especial. \r\nVocê não pode conduzir sua Fase de Batalha durante o mesmo turno em que você ativar este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30575681,'Nobre Cavaleiro Bedwyr',replace(replace('Quando este card for Invocado por Invocação-Normal ou Especial: você pode enviar 1 Card de Magia de Equipamento "Armas Nobres" do seu Deck para o Cemitério. \r\nDurante o turno de qualquer duelista: você pode escolher 1 Card de Magia de Equipamento "Armas Nobres" e 1 monstro apropriado no campo; equipe esse Card de Magia de Equipamento ao monstro apropriado. \r\nEste efeito só pode ser usado uma vez enquanto este card estiver com a face para cima no campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30576089,'Dragão Jato de Olhos Azuis',replace(replace('Outros cards que você controla não podem ser destruídos pelos efeitos de card do seu oponente. \r\nVocê só pode usar cada um dos seguintes efeitos de "Dragão Jato de Olhos Azuis" uma vez por turno e só pode ativá-los enquanto "Dragão Branco de Olhos Azuis" estiver no seu campo ou no seu Cemitério. \r\nSe um ou mais cards no campo forem destruídos em batalha ou por um efeito de card: você pode Invocar este card por Invocação-Especial do Cemitério (se ele estava lá quando o card foi destruído) ou da mão (mesmo se ele não estava). \r\nNo começo da Etapa de Dano, se este card batalhar: você pode escolher 1 card que seu oponente controla; devolva-o para a mão.','\r',char(13)),'\n',char(10)),'Invocar este card por Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30581601,'Nhamy★Garrinha',replace(replace('1 monstro Besta de LUZ de Nível 4 ou menos	\r\nSe este card for Invocado por Invocação-Especial: você pode colocar 1 Magia de Campo "Nhamy" da sua mão ou do Deck, com a face para cima no seu campo e, além disso, você não pode Invocar por Invocação-Link Monstros Link de Link-3 ou mais pelo resto deste turno. \r\nVocê só pode usar este efeito de "Nhamy★Garrinha" uma vez por turno. \r\nUma vez por Corrente, durante a Fase Principal ou a Fase de Batalha do seu oponente (Efeito Rápido): você pode pagar 100 PV; imediatamente depois que este efeito resolver, Invoque por Invocação-Sincro usando monstros que você controla como matéria, incluindo um monstro "Nhamy".','\r',char(13)),'\n',char(10)),'Coloque uma Magia de Campo','Invocação Sincro','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30583090,'HERÓI Maligno Prisão Sem Saída',replace(replace('Se você controlar um Monstro de Fusão que deve ser Invocado por Invocação-Especial com "Fusão Negra", você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "HERÓI Maligno Prisão Sem Saída" por Invocação-Especial uma vez por turno desta forma. \r\nVocê pode enviar 1 monstro "HERÓI" do seu Deck para o Cemitério; se você Invocar por Invocação-Fusão um monstro "HERÓI" neste turno, este card com a face para cima pode ser usado como um substituto para 1 matéria mencionada por nome, mas todas as outras Matérias de Fusão devem estar corretas. \r\nVocê só pode usar este efeito de "HERÓI Maligno Prisão Sem Saída" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Efeito de substituição de Matéria aplicado','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30585393,'Quebra-cabeça Renascido','Se exatamente 1 monstro que você controla (e nenhum outro card) for destruído por um efeito de card: escolha esse monstro; Invoque-o por Invocação-Especial.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30587695,'Besourotron',replace(replace('Você pode enviar para o Cemitério 1 Magia/Armadilha com a face para cima que você controla e, depois, escolher 1 monstro Inseto de Nível 4 ou menos no seu Cemitério; Invoque esse monstro Inseto por Invocação-Especial em Posição de Defesa. \r\nVocê só pode usar este efeito de "Besourotron" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30600344,'Explosão Xyz','Se você controlar um Monstro Xyz de Classe 6 ou mais: destrua todos os cards Baixados que seu oponente controla.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30603688,'Maga da Ilusão Aprendiz',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) ao descartar 1 card. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 "Mago Negro" do seu Deck à sua mão. \r\nDurante o cálculo de dano, se outro monstro Mago de TREVAS seu batalhar um monstro do oponente (Efeito Rápido): você pode enviar este card da sua mão ou do campo com a face para cima para o Cemitério; esse monstro que você controla ganha 2000 de ATK/DEF apenas durante esse cálculo de dano.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30604579,'Thor, Senhor dos Aesir',replace(replace('1 Regulador "Besta(s) Nórdica(s)" + 2+ monstros não-Reguladores	\r\nUma vez por turno: você pode negar os efeitos de todos os monstros com a face para cima que seu oponente controla atualmente até o final deste turno. \r\nUma vez por turno, durante a Fase Final, se este card com a face para cima que você controlava foi destruído por um card do seu oponente e enviado para o seu Cemitério neste turno: você pode banir 1 Regulador "Besta(s) Nórdica(s)" do seu Cemitério; Invoque este card por Invocação-Especial. \r\nQuando Invocado desta forma: você pode causar 800 de dano ao seu oponente.','\r',char(13)),'\n',char(10)),'Negar os efeitos dos monstros','Invocação Especial','Cause 800 de dano ao seu oponente','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30606547,'A Porta Escura','Ambos os jogadores podem apenas atacar com 1 monstro durante as suas respectivas Battle Phases.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30607616,'Oboro-Guruma, o Mayakashi com Rodas',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nVocê só pode controlar 1 "Oboro-Guruma, o Mayakashi com Rodas". \r\nVocê só pode usar cada um desses efeitos de "Oboro-Guruma, o Mayakashi com Rodas" uma vez por turno.\r\n● Se um Monstro Sincro em sua posse, cujo Nível original seja 5, for destruído em batalha ou por um efeito de card do oponente enquanto este card estiver no Cemitério: você pode banir 1 outro monstro Zumbi no seu Cemitério e, se isso acontecer, Invoque este card por Invocação-Especial.\r\n● Se este card for Invocado por Invocação-Especial do Cemitério: você pode ativar este efeito; neste turno, seus monstros não podem ser destruídos em batalha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30608985,'Empreendedor Mágico','VIRE: Você pode escolher 1 monstro Mago de Nível 4 ou menos no seu Cemitério; Invoque o alvo por Invocação-Especial.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30643162,'Golpe em Corte','Quando um monstro que você controla declarar um ataque: até a Fase Final, esse monstro ganha 700 de ATK e, além disso, se ele atacar um monstro em Posição de Defesa, ele causa dano de batalha perfurante ao seu oponente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30646525,'Garlandolf, Rei da Destruição',replace(replace('Este card só pode ser Invocado por Invocação-Ritual com o Card de Magia de Ritual, "Ritual de Destruição". \r\nQuando este card for Invocado por Invocação-Ritual, destrua todos os outros monstros com a face para cima no campo com DEF menor ou igual ao ATK deste card. \r\nEste card ganha 100 de ATK para cada monstro destruído por este efeito.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30650147,'Reorigem Vendorror',replace(replace('Escolha 1 monstro com a face para cima que seu oponente controla que tenha um Nível; ofereça-o como Tributo e, se isso acontecer, Invoque por Invocação-Especial 1 "Ficha Vendorror" (Zumbi/TREVAS/ATK 0/DEF 0) com um Nível igual ao Nível original do monstro oferecido como Tributo. \r\nEnquanto a Ficha Invocada por Invocação-Especial por este efeito estiver no campo, você não pode Invocar monstros por Invocação-Normal ou Especial, exceto monstros "Vendorror".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30650148,'Ficha Vendorror','Invocado por Especial com o efeito "Reorigem Vendorror". Enquanto esta Ficha estiver no campo, o duelista que a Invocou por Especial não pode fazer a Invocação-Normal ou Especial de monstros, exceto monstros do Tipo "Vendorror".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30653113,'Bençãos do Nilo','Cada vez que um card é descartado da sua mão para o Cemitério pelo efeito de um card controlado pelo seu adversário, aumente os seus Life Points em 1000 pontos.','Ganhar PV','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30655537,'Falcão Cibernético',replace(replace('Um falção a jato que viaja à velocidade do som.	\r\n\r\n(Este card não é considerado como um card "Ciber".)','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30674956,'Wynn, a Encantadora do Vento, Verdejante',replace(replace('2 monstros, incluindo um monstro de VENTO	\r\n(Este card deve ser sempre considerado como um card "Espírito-Possuído".)	\r\nVocê pode escolher 1 monstro de VENTO no Cemitério do seu oponente; Invoque-o por Invocação-Especial em uma zona sua para a qual este card apontar. \r\nSe este card Invocado por Invocação-Link for destruído em batalha, ou for destruído por um efeito de card do oponente enquanto estiver na Zona de Monstros do seu dono: você pode adicionar 1 monstro de VENTO com 1500 ou menos de DEF do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "Wynn, a Encantadora do Vento, Verdejante" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30676200,'Herói da Cidade Cinzenta',replace(replace('Se "Obsidim, a Cidade Cinzenta" estiver na Zona do Campo, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Herói da Cidade Cinzenta" por Invocação-Especial uma vez por turno desta forma. \r\nDurante a Fase Principal (Efeito Rápido): você pode escolher 1 monstro Piro no campo; destrua-o e, depois, se você destruiu "Veidos, o Dragão de Erupção da Extinção" por este efeito, você pode colocar 1 "Obsidim, a Cidade Cinzenta" do seu Deck com a face para cima na sua Zona do Campo. \r\nVocê só pode usar este efeito de "Herói da Cidade Cinzenta" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Destruir','Colocar a Magia de Campo?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30680659,'Feiticeira da Água do Templo',replace(replace('Se você controlar uma "Ficha de Aventura": você pode Invocar este card por Invocação-Especial da sua mão. \r\nVocê pode banir este card da sua mão ou do Cemitério; adicione 1 "Ritual de Aramesir" do seu Deck ou Cemitério à sua mão. \r\nSe você controlar uma "Ficha de Aventura": você pode colocar 1 Magia de Campo que mencione "Ficha de Aventura" do seu Deck com a face para cima na sua Zona do Campo. \r\nVocê só pode usar cada efeito de "Feiticeira da Água do Templo" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar este card por Invocação Especial','Buscar ou recuperar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30683373,'Esmagar com o Escudo','Escolha 1 monstro em Posição de Defesa no campo; destrua o alvo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30691817,'Marincesa Anjo Marinho',replace(replace('1 monstro "Marincesa" de Nível 4 ou menos	\r\nSe este card for Invocado por Invocação-Link: você pode adicionar 1 Magia "Marincesa" do seu Deck à sua mão. \r\nVocê só pode Invocar "Marincesa Anjo Marinho" por Invocação-Link uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30698243,'Dragão Vermelho Hipernova',replace(replace('4 Reguladores + 1+ Monstros Sincro não-Reguladores	\r\nPrimeiro deve ser Invocado por Invocação-Sincro com as matérias acima. \r\nGanha 500 de ATK para cada Regulador no seu Cemitério. \r\nSeu oponente não pode escolher este card como alvo de efeitos de card e, além disso, ele não pode ser destruído pelos efeitos de card do seu oponente. \r\nUma vez por turno (Efeito Rápido): você pode banir este card e, além disso, bana tantos cards no campo e Cemitério do seu oponente quanto possível e, depois, você pode Invocar por Invocação-Especial 1 "Dragão Vermelho Nova" do seu Deck Adicional (isso é considerado uma Invocação-Sincro).','\r',char(13)),'\n',char(10)),'Banir','Invocação Especial?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30707994,'Máximo de Seis','Quando este card for Invocado por Invocação-Tributo: lance um dado de 6 faces e este card ganha ATK igual ao resultado x 200.','Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30741334,'Rei Técnico Treinador de Gigante',replace(replace('3 monstros de Nível 8	\r\nVocê pode desassociar 1 matéria deste card; compre 1 card e revele-o e, depois, se era um monstro, cause 800 de dano ao seu oponente. \r\nVocê não pode conduzir sua Fase de Batalha no turno em que ativar este efeito. \r\nVocê só pode usar este efeito de "Rei Técnico Treinador de Gigante" até três vezes por turno.','\r',char(13)),'\n',char(10)),'Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30741503,'Galatea, a Orcust Mecânica',replace(replace('2 Monstros de Efeito, incluindo um monstro "Orcust"	\r\nEste card linkado não pode ser destruído em batalha. \r\nVocê pode escolher 1 dos seus monstros Máquina banidos; embaralhe-o no Deck e, depois, você pode Baixar 1 Magia/Armadilha "Orcust" do seu Deck. \r\nVocê só pode usar este efeito de "Galatea, a Orcust Mecânica" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Baixar a Magia/Armadilha?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30748475,'Canhão Destrutivo Daruma Carma','Coloque tantos monstros no campo quanto possível com a face para baixo em Posição de Defesa e, depois, se qualquer duelista controlar um ou mais monstros com a face para cima, ele deve enviar todos os monstros com a face para cima que ele controla para o Cemitério.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30752324,'Segredos Ancestrais',replace(replace('Invoque por Invocação-Especial 1 Monstro Normal da sua mão, Deck, ou Cemitério em Posição de Defesa (se você Invocar por Invocação-Especial do seu Deck, ele deve ser Nível 4 ou menor), ou se você controla um Monstro Normal, em vez disso você pode aplicar esses efeitos.\r\n● Destrua todos os monstros que seu oponente controla.\r\n● Destrua todas as Magias/Armadilhas que seu oponente controla.\r\n● Compre 2 cards.\r\n● Invoque por Invocação-Especial 1 monstro de qualquer Cemitério para o seu campo.	\r\nVocê só pode ativar 1 "Segredos Ancestrais" por turno.','\r',char(13)),'\n',char(10)),'Ativar','Aplicar outro efeito?','Destruir 1 monstro','Destruir Cards de Magia/Armadilha','Comprar','Invocação Especial','','','','','','','','','','');
INSERT INTO texts VALUES(30752325,'Segredos Ancestrais',replace(replace('Invoque por Invocação-Especial 1 Monstro Normal da sua mão, Deck, ou Cemitério em Posição de Defesa (se você Invocar por Invocação-Especial do seu Deck, ele deve ser Nível 4 ou menor), ou se você controla um Monstro Normal, em vez disso você pode aplicar esses efeitos.\r\n● Destrua todos os monstros que seu oponente controla.\r\n● Destrua todas as Magias/Armadilhas que seu oponente controla.\r\n● Compre 2 cards.\r\n● Invoque por Invocação-Especial 1 monstro de qualquer Cemitério para o seu campo.	\r\nVocê só pode ativar 1 "Segredos Ancestrais" por turno.','\r',char(13)),'\n',char(10)),'Ativar','Aplicar outro efeito?','Destruir 1 monstro','Destruir Cards de Magia/Armadilha','Comprar','Invocação Especial','','','','','','','','','','');
INSERT INTO texts VALUES(30757127,'HERÓI do Destino - Perigoso',replace(replace('1 monstro "HERÓI do Destino" + 1 Monstro de Efeito de TREVAS	\r\n(Efeito Rápido): você pode descartar 1 card; envie 1 monstro "HERÓI do Destino" da sua mão ou do Deck para o Cemitério e, se isso acontecer, até o final deste turno, os monstros "HERÓI do Destino" que você controla ganham 200 de ATK para cada monstro "HERÓI do Destino" no seu Cemitério. \r\nVocê só pode usar este efeito de "HERÓI do Destino - Perigoso" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30757396,'Mefist de Sangue',replace(replace('1 Regulador + 1 ou mais monstros não-Reguladores	\r\nUma vez por turno, durante a Fase de Apoio do seu oponente: Você pode causar 300 de dano ao seu oponente para cada card que seu oponente controla. \r\nCada vez que seu oponente Baixar um ou mais Cards de Magia ou Armadilha: Cause 300 de dano ao seu oponente.','\r',char(13)),'\n',char(10)),'Cause dano ao seu oponente','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30761649,'Untopia Barian',replace(replace('(Este card deve ser sempre considerado como um card "de Barian".)	\r\nMonstros "Número" que você controla com um número entre "101" e "107" em seus nomes, assim como monstros "CXyz" e monstros "Número C" que você controla, não podem ser destruídos pelos efeitos de card do seu oponente, e seu oponente não pode escolhê-los como alvo de efeitos de card. \r\nUma vez por turno, se você Invocar por Invocação-Especial um Monstro Xyz com um efeito de Magia "Magia de Aumento de Classe": você pode escolher esse Monstro Xyz e 1 monstro que seu oponente controla; associe esse monstro do oponente a esse Monstro Xyz como matéria.','\r',char(13)),'\n',char(10)),'Usar um monstro do oponente como Matéria Xyz','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30765615,'Ringowurm, o Dragão Guardando as Cem Maçãs',replace(replace('Se um Monstro que não seja de Efeito com a face para cima estiver no campo: você pode Invocar este card por Invocação-Especial da sua mão. \r\nDurante sua Fase Principal, se você Invocou por Invocação-Sincro neste turno: você pode banir este card do seu Cemitério; Invoque por Invocação-Especial 1 "Ficha de Cem Maçãs" (Wyrm/LUZ/Nível 2/ATK 100/DEF 100). \r\nO duelista que a Invocou pode considerá-la como um Regulador para uma Invocação-Sincro. \r\nVocê só pode usar cada efeito de "Ringowurm, o Dragão Guardando as Cem Maçãs" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30765616,'Ficha de Cem Maçãs','Invocado por Especial com o efeito "Ringowurm, o Dragão Guardando as Cem Maçãs". O duelista que a Invocou pode considerá-la como um Regulador para uma Invocação-Sincro.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30770156,'Unidade de Transporte do Núcleo','Uma vez por turno, você pode descartar 1 card para adicionar 1 "Núcleo de Ferro de Koa''ki Meiru" do seu Deck para a sua mão.','Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30778711,'Carniçal das Sombras','Ganha 100 de ATK para cada monstro no seu Cemitério.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30786387,'Pilha de Flores',replace(replace('Selecione 3 monstros "Flor Cardian" com nomes diferentes do seu Deck e coloque-os no topo do seu Deck em qualquer ordem. \r\nDurante sua Fase Principal, exceto no turno em que este card foi enviado para o Cemitério: você pode banir este card do seu Cemitério e, depois, escolher 1 monstro "Flor Cardian" no seu Cemitério; adicione-o à sua mão. \r\nVocê só pode usar este efeito de "Pilha de Flores" uma vez por turno.','\r',char(13)),'\n',char(10)),'Organize os cards','Escolha os cards para colocar no topo do Deck','Recuperar cards','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30794966,'Dragão Hierático de Asar',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) ao banir 1 monstro de LUZ do Tipo Dragão e 1 Monstro Normal do Tipo Dragão do seu Cemitério. \r\nSe este card com a face para cima no campo seria destruído, em vez disso, você pode oferecer como Tributo 1 monstro "Hierático" com a face para cima, exceto este card.','\r',char(13)),'\n',char(10)),'Usar o efeito de "Dragão Hierático de Asar" em vez de ser destruído?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30802207,'Carpedivem Exoirmã',replace(replace('Nenhum duelista pode escolher monstros "Exoirmã" que você controla como alvo de efeitos de monstros que foram Invocados por Invocação-Especial do Cemitério. \r\nVocê só pode usar cada um dos seguintes efeitos de "Carpedivem Exoirmã" uma vez por turno. \r\nSe você Invocar um monstro "Exoirmã" por Invocação-Xyz: você pode declarar 1 nome de card; até o final deste turno, negue os efeitos ativados e efeitos no campo dos cards com esse nome original. \r\nQuando um ataque for declarado envolvendo um monstro "Exoirmã" seu: você pode escolher 1 Magia/Armadilha que seu oponente controla; destrua-a.','\r',char(13)),'\n',char(10)),'Declare o nome de um card para negá-lo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30811116,'Besta Fantasma Mecha Raia Furtiva',replace(replace('Quando este card causar dano de batalha a um oponente: Invoque por Invocação-Especial 1 "Ficha de Besta Fantasma Mecha" (Tipo Máquina/VENTO/Nível 3/ATK 0/DEF 0). \r\nO Nível deste card aumenta em um valor igual à soma dos Níveis de todas as "Fichas de Besta Fantasma Mecha" que você controla. \r\nEnquanto você controlar uma Ficha, este card não pode ser destruído em batalha ou por efeitos de card. \r\nUma vez por turno: você pode oferecer 1 Ficha como Tributo e, depois, escolher 1 Card de Magia/Armadilha no campo; destrua o alvo.','\r',char(13)),'\n',char(10)),'Invocar uma Ficha por Invocação Especial','Destruir Magias/Armadilhas','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30811117,'Ficha de Besta Fantasma Mecha','Invocado por Especial com o efeito de um monstro "Besta Fantasma Mecha" ou um card relacionado.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30822527,'Decodificar Transmissor Estendido',replace(replace('2+ Monstros de Efeito	\r\nO nome deste card se torna "Decodificar Transmissor" enquanto estiver no campo. \r\nGanha 500 de ATK para cada monstro para o qual ele apontar. \r\nDurante sua Fase de Batalha, se um monstro para o qual este card apontar for destruído em batalha ou enviado para o Cemitério: este card pode realizar um segundo ataque durante cada Fase de Batalha neste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30829071,'Bufo, o Embaixador da Diversão',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode escolher 1 Armadilha "Atração" no seu Cemitério e 1 monstro com a face para cima que seu oponente controla; equipe essa Armadilha ao monstro do seu oponente. \r\n(Efeito Rápido): você pode escolher 1 das suas Armadilhas "Atração" equipadas a um monstro; equipe-a a 1 monstro "Diversão" que você controla ou 1 monstro com a face para cima que seu oponente controla. \r\nVocê só pode usar este efeito de "Bufo, o Embaixador da Diversão" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30834988,'Ataque Total','Se um ou mais monstros forem Invocados por Invocação-Especial enquanto este card estiver com a face para cima no campo: coloque esse(s) monstro(s) com a face para cima em Posição de Ataque e ele(s) deve(m) atacar, se possível, durante o turno em que foi/foram Invocado(s) por Invocação-Especial.','Mudar para Posição de Ataque','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30845999,'Lançamento Qlipper','Até o final deste turno, todos os monstros "Qli" atualmente no campo que foram Invocados por Invocação-Normal/Baixados ganham 300 de ATK, mas não são afetados por outros efeitos de Magia/Armadilha e, além disso, seus efeitos são negados.','Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30860696,'Guerreiro Foguete',replace(replace('Durante sua Fase de Batalha, este card não pode ser destruído em batalha e, além disso, você não sofre dano das batalhas envolvendo este card. \r\nSe este card atacar um monstro, depois do cálculo de dano: o alvo desse ataque perde 500 de ATK até o final deste turno.','\r',char(13)),'\n',char(10)),'Reduzir ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30864377,'Besta Gladiadora Domador Editor',replace(replace('2 monstros "Besta Gladiadora" de Nível 5 ou mais	\r\nPrimeiro deve ser Invocado por Invocação-Especial (do seu Deck Adicional) ao embaralhar os cards acima que você controla no Deck. \r\nNão pode ser usado como Matéria de Fusão. \r\nUma vez por turno: você pode Invocar por Invocação-Especial 1 Monstro de Fusão "Besta Gladiadora" do seu Deck Adicional, exceto "Besta Gladiadora Domador Editor", ignorando suas condições de Invocação. \r\nNo final da Fase de Batalha, se um monstro "Besta Gladiadora" seu batalhou: você pode embaralhar esse monstro no Deck ou Deck Adicional; Invoque por Invocação-Especial 1 monstro "Besta Gladiadora" do seu Deck.','\r',char(13)),'\n',char(10)),'','','Escolha um card para retornar ao Deck','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30875635,'Ejetor Milagroso',replace(replace('(Este card deve ser sempre considerado como um card "HERÓI do Elemento".)	\r\nSe este card estiver na sua mão: você pode enviar 1 monstro "Neoespacial" do seu Deck para o Cemitério; Invoque este card por Invocação-Especial. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 Magia/Armadilha que mencione um nome de card de monstro "HERÓI do Elemento" do seu Deck à sua mão. \r\nSe este card for enviado para o Cemitério: você pode escolher 1 card no Cemitério do seu oponente; bana-o. \r\nVocê só pode usar cada efeito de "Ejetor Milagroso" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Adicionar à mão','Banir','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30888983,'A Seleção',replace(replace('Pague 1000 PV. \r\nNegue a Invocação de um monstro com o mesmo Tipo de um monstro no campo e o destrua.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30907810,'Mágico Mosquete Mentor Zakiel',replace(replace('Você pode Invocar este card por Invocação-Tributo com a face para cima ao oferecer como Tributo 1 monstro "Mágico(a) Mosquete". \r\nDurante o turno de qualquer duelista, você pode ativar Cards de Magia/Armadilha "Mágico(a) Mosquete" da sua mão. \r\nUma vez por turno, durante a Fase Final do seu oponente: você pode comprar cards igual ao número de Cards de Magia/Armadilha "Mágico(a) Mosquete" que você ativou neste turno enquanto este card estava com a face para cima no seu campo. \r\nVocê só pode usar este efeito de "Mágico Mosquete Mentor Zakiel" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ofereça 1 monstro "Mosqueteiro/a Mágico" como Tributo para Invocá-lo por Invocação Tributo com a face para cima','','Ativar aplicando o efeito de "Mágico Mosquete Mentor Zakiel".','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30913809,'Força da Luz',replace(replace('Uma vez por turno, durante sua Fase de Apoio, se "Barreira de Luz" não estiver na sua Zona do Campo: lance uma moeda. \r\nSe for coroa, os seguintes efeitos são negados até sua próxima Fase de Apoio.\r\n● Monstros Fada que você controla ganham 300 de ATK/DEF.\r\n● Você pode descartar 1 card; adicione 2 monstros "Força Arcana" com nomes diferentes do seu Deck à sua mão e, além disso, você não pode Invocar por Invocação-Especial pelo resto deste turno, exceto monstros "Força Arcana".	\r\nVocê só pode usar este efeito de "Força da Luz" uma vez por turno.','\r',char(13)),'\n',char(10)),'Jogue uma moeda','ATK/DEF +300','Adicionar à mão','Aplicando o 1º efeito (os efeitos 2 e 3 deste card são negados até a sua próxima Fase de Apoio)','','','','','','','','','','','','');
INSERT INTO texts VALUES(30914564,'Grou Sagrado','Se este card for Invocado por Invocação-Especial: compre 1 card.','Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30915572,'Gallis, a Besta Estelar','Você pode revelar este card na sua mão; envie o card do topo do seu Deck para o Cemitério e, depois, se ele era um monstro, cause dano ao seu oponente igual ao Nível dele x 200 e Invoque este card por Invocação-Especial da sua mão, caso contrário, destrua este card.','Envie o card do topo do Deck para o Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30922149,'Efeitos Colaterais?','Seu oponente compra de 1 a 3 cards e, depois, você ganha 2000 PV para cada card que ele comprou com este efeito.','Escolha quantos cards comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30929786,'Irmandade do Punho de Fogo - Galo',replace(replace('Quando este card for Invocado por Invocação-Especial pelo efeito de um monstro "Punho de Fogo": você pode adicionar 1 monstro "Punho de Fogo" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Irmandade do Punho de Fogo - Galo" uma vez por turno. \r\nUma vez por turno: você pode enviar 1 Magia/Armadilha "Formação de Fogo" com a face para cima que você controla para o Cemitério; Baixe 1 Magia/Armadilha "Formação de Fogo" diretamente do seu Deck.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Baixar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30936186,'Cavaleirur Koa''ki Meiru',replace(replace('Durante cada uma das suas Fases Finais, destrua este card a não ser que você envie 1 "Núcleo de Ferro de Koa''ki Meiru" da sua mão para o Cemitério ou revele 1 monstro do Tipo Besta-Guerreira na sua mão. \r\nUma vez por turno, você pode revelar 1 "Núcleo de Ferro de Koa''ki Meiru" na sua mão para Invocar por Invocação-Especial 1 monstro "Koa''ki Meiru" de Nível 4 ou menos do seu Deck, exceto "Cavaleirur Koa''ki Meiru".','\r',char(13)),'\n',char(10)),'Escolha 1 "Núcleo de Ferro de Koa''ki Meiru" para enviar para o Cemitério','Escolha um monstro Besta-Guerreira para mostrar ao seu oponente','Destruir "Cavaleirur Koa''ki Meiru"','Invocação Especial','','','','','','','','','','','','');
INSERT INTO texts VALUES(30945251,'Blitzclique - Sobretensão',replace(replace('Escolhe 1 card com a face para cima no campo; destrua-o, também pelo resto deste turno, você não pode Invocar por Invocação-Especial Monstros de Efeito, exceto da mão.\r\nSe um ou mais cards são destruídos pelos efeitos dos seus cards "Blitzclique", enquanto este card está no seu Cemitério (exceto durante a Etapa de Dano): você pode adicionar este card à sua mão. \r\nVocê só pode usar este efeito de "Blitzclique - Sobretensão" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar','Recuperar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30964246,'Argostars - Matança de Gigantes',replace(replace('Adicione 1 monstro "Argostars" do seu Deck à sua mão e, depois, imediatamente depois que este efeito resolver, se uma Armadilha Contínua estiver na sua Zona de Monstros, ou uma Armadilha Contínua com um efeito que Invoque a si mesma por Invocação-Especial como um monstro estiver na sua Zona de Magias & Armadilhas, você pode Invocar por Invocação-Normal 1 monstro Guerreiro. \r\nDurante sua Fase Principal: você pode banir este card do seu Cemitério e, depois, escolha 2 cards no campo, incluindo uma Armadilha Contínua "Argostars" que você controla; devolva-os para a mão. \r\nVocê só pode usar 1 efeito de "Argostars - Matança de Gigantes" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Retornar para a mão','Invocação Normal?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30968774,'Clérigo de Permuta',replace(replace('Se este card for enviado para o Cemitério como Matéria Link: você pode fazer com que esse Monstro Link perca 500 de ATK e, depois, compre 1 card. \r\nVocê só pode usar este efeito de "Clérigo de Permuta" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30979619,'APARATO ESPIRÃO - Grande Vermelho',replace(replace('Ative este card ao escolher 1 monstro "ESPIRÃO" no seu Cemitério; Invoque-o por Invocação-Especial e, se isso acontecer, equipe este card a ele. \r\nEle não pode ser destruído em batalha. \r\nVocê só pode ativar 1 "APARATO ESPIRÃO - Grande Vermelho" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30983281,'Dragão da Poeira Estelar Acelerador Sincro',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro: você pode Invocar por Invocação-Especial 1 Regulador de Nível 2 ou menos do seu Cemitério. \r\nDurante a Fase Principal (Efeito Rápido): você pode oferecer este card como Tributo; Invoque por Invocação-Especial 1 "Dragão da Poeira Estelar" do seu Deck Adicional (isso é considerado uma Invocação-Sincro) e, depois, imediatamente depois que este efeito resolver, Invoque por Invocação-Sincro usando monstros que você controla como matéria. \r\nPelo resto deste turno, os monstros Invocados por Invocação-Sincro por este efeito não são afetados pelos efeitos ativados do seu oponente. \r\nVocê só pode usar cada efeito de "Dragão da Poeira Estelar Acelerador Sincro" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Invocação Sincro','O efeito de "Dragão da Poeira Estelar Acelerador Sincro" está sendo aplicado.','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30989084,'Aromági-lilith Alecrim',replace(replace('2+ monstros Planta	\r\nSe este card for Invocado por Invocação-Especial: você pode adicionar 1 card "Aromági" do seu Deck à sua mão. \r\nSe você ganhar PV, mesmo durante a Etapa de Dano: você pode Invocar por Invocação-Especial até 3 monstros "Aromági" da sua mão em zonas suas para as quais este card apontar. \r\nVocê pode oferecer como Tributo 1 monstro para o qual este card apontar e, depois, escolha 1 card no campo; bana-o e, se isso acontecer, ganhe 1000 PV. \r\nVocê só pode usar cada efeito de "Aromági-lilith Alecrim" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Invocar por Invocação Especial da mão','Banir 1 card','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30996652,'Reuso Utensilhor','Escolha 1 monstro "Utensilhor" no seu Cemitério; Invoque-o por Invocação-Especial, mas coloque-o no fundo do Deck quando ele deixar o campo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30998403,'D/D/D Zeus Ragnarok, o Rei do Céu',replace(replace('2+ monstros "D/D"	\r\nVocê pode escolher 1 card "D/D" ou "Pacto Obscuro" que você controla; destrua-o e, além disso, durante sua Fase Principal neste turno, você pode conduzir 1 Invocação-Pêndulo de um ou mais monstros "D/D" em adição à sua Invocação-Pêndulo (padrão) (você só pode se aproveitar deste efeito uma vez por turno). \r\nQuando seu oponente ativar um efeito de monstro na mão (Efeito Rápido): você pode banir 1 monstro "D/D" e 1 card "Pacto Obscuro" do seu Cemitério; negue a ativação. \r\nVocê só pode usar este efeito de "D/D/D Zeus Ragnarok, o Rei do Céu" uma vez por turno.','\r',char(13)),'\n',char(10)),'Destruir e ganhar uma Invocação Pêndulo adicional','Negar a ativação','Invocação Pêndulo usando o efeito de "D/D/D Zeus Ragnarok, o Rei do Céu"','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31000575,'Serviço Militar',replace(replace('Escave o card do topo do Deck do seu oponente e se for um monstro que possa ser Invocado por Invocação-Normal/Baixado, Invoque-o por Invocação-Especial no seu campo. \r\nCaso contrário, adicione esse card à mão do seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31002402,'Dogmatikalamidade',replace(replace('Este card pode ser usado para a Invocação-Ritual de qualquer Monstro de Ritual "Dogmatika". \r\nVocê também deve oferecer monstros como Tributo da sua mão ou do campo, cuja soma dos Níveis seja exatamente igual ao Nível do Monstro de Ritual que você Invocou por Invocação-Ritual, ou enviar 1 monstro do seu Deck Adicional para o Cemitério, cujo Nível seja igual ao Nível do Monstro de Ritual que você Invocou por Invocação-Ritual. \r\nPelo resto deste turno depois que este card resolver, você não pode Invocar monstros por Invocação-Especial do Deck Adicional. \r\nVocê só pode ativar 1 "Dogmatikalamidade" por turno.','\r',char(13)),'\n',char(10)),'Enviar um monstro do Deck Adicional para o Cemitério como Matéria?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31006879,'Em Suas Marcas, Preparar, DUELEM!',replace(replace('Quando este card for ativado: se você não controlar nenhum outro card, você pode adicionar 1 monstro "Sincron" do seu Deck à sua mão. \r\nUma vez por turno, durante sua Fase de Apoio: coloque 1 Marcador de Sinal neste card. \r\nVocê pode remover 2 Marcadores de Sinal do seu campo e enviar este card com a face para cima para o Cemitério; compre 2 cards e, depois, envie 1 card da sua mão para o Cemitério. \r\nVocê só pode ativar 1 "Em Suas Marcas, Preparar, DUELEM!" por turno.','\r',char(13)),'\n',char(10)),'Adicionar à sua mão 1 monstro "Sincron" do seu Deck?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31010081,'Rompe DoomZ - Diactorus',replace(replace('2 monstros de Nível 4	\r\nSe este card for Invocado por Invocação-Especial: você pode destruir 1 card "DoomZ" na sua mão ou no campo com a face para cima e, depois, você pode destruir 1 monstro no campo. \r\nSe este card for destruído por um efeito de card enquanto tiver um monstro "DoomZ" ou "Medius, o Puro" como matéria: você pode pegar 1 Magia de Equipamento do seu Deck e adicioná-la à sua mão ou enviá-la para o Cemitério. \r\nVocê só pode usar cada efeito de "Rompe DoomZ - Diactorus" uma vez por turno.','\r',char(13)),'\n',char(10)),'Destruir','Adicionar à mão','Destruir um monstro no campo?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31034919,'Recarregador Louco','Se este card for destruído em batalha e enviado para o Cemitério: envie 2 cards da sua mão para o Cemitério e, se isso acontecer, compre 2 cards.','Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31036355,'Troca de Criaturas',replace(replace('Cada duelista seleciona 1 monstro que ele controla e eles trocam o controle desses monstros um com o outro. \r\nEsses monstros não podem mudar suas posições de batalha pelo resto deste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31038159,'Dragão Gênesis',replace(replace('Uma vez por turno, você pode enviar 1 monstro do Tipo Dragão da sua mão ao Cemitério para adicionar 1 monstro do Tipo Dragão do seu Cemitério à sua mão. \r\nQuando este card for enviado do campo ao Cemitério, você pode devolver todos os monstros do Tipo Dragão do seu Cemitério para o seu Deck.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Retornar ao Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31042659,'Serpente Soberana Suprema de Golgonda',replace(replace('Enquanto "Grande Mar de Areia - Gold Golgonda" estiver no campo, o ATK original deste card se torna 3000. \r\nVocê só pode usar cada um dos seguintes efeitos de "Serpente Soberana Suprema de Golgonda" uma vez por turno. \r\nEnquanto este card estiver na sua mão ou no Cemitério, se você controlar um card com a face para cima na sua Zona do Campo: você pode Invocar este card por Invocação-Especial, mas bana-o quando ele deixar o campo. \r\nSe "Grande Mar de Areia - Gold Golgonda" no campo seria destruído por um efeito de card, em vez disso, você pode banir 1 monstro do seu Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31044787,'Furão de Chamas','Se o ATK combinado de todos os monstros com a face para cima que seu oponente controla for maior que seus PV: faça com que seu oponente embaralhe no Deck os monstros com a face para cima que ele controla (ele seleciona), exceto monstros com 0 de ATK, de forma que o ATK combinado dos monstros restantes que ele controla se torne igual ou menor que os seus PV.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31053337,'Asanegra - Abrolhos, o Grande Terremoto',replace(replace('Não pode ser Invocado por Invocação-Especial. \r\nEste card não pode destruir monstros em batalha. \r\nSe este card batalhar um monstro, depois do cálculo de dano: devolva esse monstro para a mão. \r\nUma vez por turno, durante sua Fase Principal 1: você pode fazer com que este card perda exatamente 1000 de ATK e, se isso acontecer, devolva todos os cards na Zona de Magia & Armadilha do seu oponente para a mão.','\r',char(13)),'\n',char(10)),'Retornar para a mão todos os cards na Zona de Magias & Armadilhas do seu oponente','Retornar para a mão o monstro em batalha','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31059809,'Urtiga Marinha Silenciosa',replace(replace('Se você controlar um monstro de ÁGUA: você pode Invocar este card por Invocação-Especial da sua mão. \r\nVocê não pode Invocar monstros por Invocação-Especial, exceto monstros de ÁGUA, no turno em que ativar este efeito. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha até 3 monstros de ÁGUA no seu Cemitério; embaralhe-os no Deck. \r\nVocê só pode usar cada efeito de "Urtiga Marinha Silenciosa" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31061682,'Garota do Campo de Kozmo',replace(replace('Durante o turno de qualquer duelista: você pode banir este card; Invoque por Invocação-Especial 1 monstro "Kozmo" de Nível 4 ou mais da sua mão. \r\nVocê só pode usar este efeito de "Garota do Campo de Kozmo" uma vez por turno. \r\nQuando este card causar dano de batalha ao seu oponente: você pode pagar 500 PV; adicione 1 card "Kozmo" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Invoque por Invocação Especial 1 monstro "Kozmo" da sua mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31066283,'Renascimento de Motodokuro',replace(replace('Este card é usado para a Invocação-Ritual de "Motodokuro". \r\nVocê também deve oferecer como Tributo monstros da sua mão ou do campo cuja soma dos Níveis seja igual a 6 ou mais.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31076103,'O Primeiro Sarcófago',replace(replace('Uma vez por turno, durante a Fase Final do seu oponente: coloque 1 "O Segundo Sarcófago" ou (depois que fizer isso) "O Terceiro Sarcófago" da sua mão ou do Deck com a face para cima na sua Zona de Magias & Armadilhas. \r\nDepois, se você controlar "O Primeiro Sarcófago", "O Segundo Sarcófago" e "O Terceiro Sarcófago", envie todos eles para o Cemitério e, se isso acontecer, Invoque por Invocação-Especial 1 "Espírito de Faraó" da sua mão ou do Deck. \r\nSe qualquer desses cards, incluindo este card, deixar seu campo, envie todos eles que você controla para o Cemitério, incluindo este card.','\r',char(13)),'\n',char(10)),'Colocar','Invocação Especial','Escolha um card para colocar com a face para cima no seu campo','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31077447,'Caixa Surpresa','Quando um monstro do seu oponente declarar um ataque enquanto ele controlar 2 ou mais monstros: escolha o monstro atacante; negue o ataque e, se isso acontecer, envie 1 outro monstro que ele controla para o Cemitério e, depois, o monstro escolhido como alvo perde ATK igual ao ATK ou DEF original (o que for maior; em caso de empate, você escolhe) do monstro enviado para o Cemitério.','Negar o ataque','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31086840,'Número 69: Símbolo Heráldico - Fluxo de Fragmentação',replace(replace('4 monstros de Nível 4	\r\nVocê também pode Invocar este card por Invocação-Xyz ao usar um monstro que você controla cujo nome original seja "Número 69: Símbolo Heráldico". \r\n(Transfira as matérias dele para este card.) \r\nQuando seu oponente ativar um efeito de monstro no campo, ou um monstro do oponente declarar um ataque (Efeito Rápido): você pode Invocar por Invocação-Especial do seu Deck Adicional, 1 "Número 69: Símbolo Heráldico - Demolição de Matéria Escura" ao usar este card com a face para cima que você controla como matéria e, depois, destrua o monstro do oponente. \r\n(Isso é considerado uma Invocação-Xyz. Transfira as matérias deste card.) \r\nVocê só pode usar este efeito de "Número 69: Símbolo Heráldico - Fluxo de Fragmentação" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Xyz usando "Número 69: Símbolo Heráldico" como matéria?','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31102447,'Espião Amazoness',replace(replace('Você pode revelar 1 outro monstro "Amazoness" na sua mão; Invoque este card por Invocação-Especial da sua mão. \r\nVocê só pode usar este efeito de "Espião Amazoness" uma vez por turno. \r\nQuando este card for destruído em batalha e enviado para o Cemitério: você pode escolher 1 monstro "Amazoness" no seu Cemitério, exceto "Espião Amazoness"; devolva-o para a mão ou embaralhe-o no Deck.','\r',char(13)),'\n',char(10)),'Invoque este card por Invocação Especial da sua mão','Retornar um monstro para a mão ou para o Deck','Retornar para a mão?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31111109,'Neos Divino, o HERÓI do Elemento',replace(replace('Deve ser Invocado por Invocação-Fusão usando quaisquer 5 monstros "Neos", "Neo Espaço", "Neoespacial" ou "HERÓI", incluindo pelo menos 1 monstro "Neos" ou "Neo Espaço", 1 monstro "Neoespacial" e 1 monstro "HERÓI" e não pode ser Invocado por Invocação-Especial de nenhuma outra forma. 	\r\nUma vez por turno: Você pode banir 1 monstro "Neos", "Neo Espaço", "Neoespacial" ou "HERÓI" do seu Cemitério; este card ganha 500 de ATK, e até a Fase Final ele também ganha os efeitos do monstro banido.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31114334,'Asanegra Agressor - Kusanagi Tempestade Reunida',replace(replace('1 Regulador + 1+não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro usando um monstro "Asanegra" como matéria, ele é considerado como um Regulador enquanto estiver com a face para cima no campo.\r\nDepois que este card é Invocado por Invocação-Sincro, pelo resto deste turno, ele ganha ATK igual ao ATK original total dos Monstros Sincro usados como matéria.\r\nPode atacar todos os monstros do oponente, uma vez cada.\r\nSe este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31118030,'Princesa da Premonição Silflecha','VIRE: Você pode adicionar 1 Magia de Ritual do seu Deck ou Cemitério à sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31122090,'Gyakutenno Megami','Este Anjo usa o seu poder místico para proteger os fracos e fornecer apoio espiritual.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31122091,'Gyakutenno Megami','Este Anjo usa o seu poder místico para proteger os fracos e fornecer apoio espiritual.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31123642,'ZS - Sábio Utópico',replace(replace('2 monstros de Nível 4	\r\nVocê pode desassociar 2 matérias deste card; Invoque por Invocação-Especial 1 monstro "ZW -" ou "ZS -" do seu Deck e, além disso, pelo resto deste turno, você só pode atacar com monstros "Número" e você não pode Invocar por Invocação-Especial do Deck Adicional, exceto Monstros Xyz. \r\nVocê só pode usar este efeito de "ZS - Sábio Utópico" uma vez por turno. \r\nSe um ou mais Monstros Xyz "Utopia" ou "Utópico" que você controla, cujo Atributo original seja LUZ, seriam destruídos em batalha ou por um efeito de card, exceto "ZS - Sábio Utópico", em vez disso, você pode banir este card do seu campo ou Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31149212,'Riseheart Kashtira',replace(replace('Se você controlar um monstro "Kashtira": você pode Invocar este card por Invocação-Especial da sua mão e, além disso, você não pode Invocar monstros por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto Monstros Xyz. \r\nDurante sua Fase Principal, se este card foi Invocado por Invocação-Normal ou Especial neste turno: você pode banir 1 card "Kashtira" do seu Deck, exceto "Riseheart Kashtira"; bana os 3 cards do topo do Deck do seu oponente com a face para baixo e, se você banir algum, o Nível deste card se torna 7. \r\nVocê só pode usar cada efeito de "Riseheart Kashtira" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31173519,'Motoqueiro Rai','Se este card batalhar com um monstro do oponente: Esse monstro não pode atacar enquanto estiver com a face para cima no campo.','Restrição de ataque','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31175914,'Captador de Ataque',replace(replace('Se este card for enviado para o Cemitério como um Monstro-Matéria Sincro, selecione 1 monstro com a face para cima que seu oponente controla. \r\nO monstro selecionado do oponente perde 1000 de ATK até a Fase Final.','\r',char(13)),'\n',char(10)),'Reduzir ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31178212,'Unicórnio Majespectro - Kirin',replace(replace('Escala de Pêndulo = 2\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\n(Efeito Rápido): você pode escolher 1 Monstro Pêndulo na sua Zona de Monstros e 1 monstro que seu oponente controla; devolva-os para a(s) mão(s). \r\nVocê só pode usar este efeito de "Unicórnio Majespectro - Kirin" uma vez por turno. \r\nEnquanto este card estiver na sua Zona de Monstros, seu oponente não pode escolhê-lo como alvo de efeitos de card e, além disso, ele não pode ser destruído pelos efeitos de card do seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31181711,'Muralha Samurai Superpesado Escudo da Alma',replace(replace('(Este card deve ser sempre considerado como um card "Samurai Superpesado Alma".)	\r\nVocê pode escolher 1 monstro "Samurai Superpesado" que você controla; equipe este monstro da sua mão ou do campo ao alvo. \r\nEle ganha 1200 de DEF. \r\nQuando o monstro equipado com este card por este efeito for escolhido como alvo de um ataque: você pode enviar este Card de Equipamento para o Cemitério; negue o ataque, mas a DEF do monstro equipado se torna 0.','\r',char(13)),'\n',char(10)),'Equipar','Negar o ataque','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31189536,'Despertar do Vampiro',replace(replace('Invoque por Invocação-Especial 1 monstro "Vampiro(a)" do seu Deck, mas destrua-o durante a Fase Final deste turno. \r\nVocê só pode ativar 1 "Despertar do Vampiro" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31213049,'XX-clusão','Quando seu oponente ativar um efeito de monstro na mão dele: negue a ativação e, depois, se ele tiver cards na mão dele, você descarta 1 card da mão dele (ele seleciona).','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31222701,'Olhos Hesitantes',replace(replace('Destrua tantos cards quanto possível nas Zonas de Pêndulo de cada duelista e, depois, aplique esses efeitos, em sequência, dependendo do número de cards destruídos por este efeito.\r\n● 1+: Cause 500 de dano ao seu oponente.\r\n● 2+: Você pode adicionar 1 Monstro Pêndulo do seu Deck Principal à sua mão.\r\n● 3+: Você pode banir 1 card no campo.\r\n● 4: Você pode adicionar 1 "Olhos Hesitantes" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Adicionar 1 monstro Pêndulo do Deck à sua mão?','Banir 1 card no campo?','Adicionar 1 "Olhos Hesitantes" do seu Deck à sua mão?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31226177,'Imduk, o Dragão do Cálice Mundial',replace(replace('1 Monstro Normal, exceto uma Ficha	\r\nDurante sua Fase Principal, você pode Invocar por Invocação-Normal 1 monstro "Cálice Mundial" em adição à sua Invocação-Normal/Baixar (padrão). \r\n(Você só pode se aproveitar deste efeito uma vez por turno.) \r\nNo começo da Etapa de Dano, se este card batalhar um monstro do oponente para o qual este card apontar: você pode destruir esse monstro do oponente. \r\nSe este card for enviado do campo para o Cemitério: você pode Invocar por Invocação-Especial 1 monstro "Cálice Mundial" da sua mão.','\r',char(13)),'\n',char(10)),'','','Invocar pelo efeito de "Imduk, o Dragão do Cálice Mundial"','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31230289,'Besta de Rabiscos - Estego',replace(replace('Se você não controlar nenhum monstro, ou se todos os monstros que você controla forem monstros Dinossauro: você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 Magia/Armadilha "Livro de Rabiscos" do seu Deck à sua mão e, depois, descarte 1 card. \r\nVocê só pode usar cada efeito de "Besta de Rabiscos - Estego" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31241087,'Transcendossauro Meteossauro',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial por um efeito de card. \r\nDurante o turno do seu oponente (Efeito Rápido): você pode destruir 2 outros monstros Dinossauro na sua mão e/ou no campo e, se isso acontecer, Invoque este card por Invocação-Especial da sua mão. \r\nSe este card for Invocado por Invocação-Especial: você pode enviar 1 monstro Dinossauro do seu Deck para o Cemitério. \r\nSe este card for destruído: você pode embaralhar no Deck 1 Monstro Normal do seu Cemitério e, depois, você pode Invocar este card por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Transcendossauro Meteossauro" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','Invocar este card por Invocação Especial?','','','','','','','','','','','','');
INSERT INTO texts VALUES(31242786,'Devora-Almas','Uma maravilha viva de mistérios.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31245780,'Mania de Batalha',replace(replace('Ative apenas durante a Fase de Apoio do seu oponente. \r\nTodos os monstros com a face para cima que seu oponente controla são colocados em Posição de Ataque e não podem mudar suas posições de batalha neste turno. \r\nTodos os monstros que seu oponente controla atualmente devem atacar neste turno, se possível.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31247589,'Besta Gladiadora Dimacari',replace(replace('Se este card foi Invocado por Invocação-Especial pelo efeito de um monstro "Besta Gladiadora", ele pode realizar um segundo ataque durante cada Fase de Batalha. \r\nNo final da Fase de Batalha, se este card batalhou: você pode embaralhá-lo no Deck; Invoque por Invocação-Especial 1 monstro "Besta Gladiadora" do seu Deck, exceto "Besta Gladiadora Dimacari".','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31259606,'Mare do Mar Supremo',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode enviar 1 monstro Aqua do seu Deck para o Cemitério, exceto "Mare do Mar Supremo". \r\nDurante sua Fase Final: você pode oferecer este card como Tributo e, depois, escolha 1 monstro Aqua no seu Cemitério, exceto "Mare do Mar Supremo"; adicione-o à sua mão. \r\nVocê só pode usar cada efeito de "Mare do Mar Supremo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31281980,'Gerador de Ondas Curadoras','Uma vez por turno, você pode selecionar outro monstro com a face para cima que você controla para ganhar PV igual ao Nível desse monstro x 100.','Ganhar PV','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31286915,'"Estripadora/M" K9-X',replace(replace('2 monstros de Nível 9	\r\nSe este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente. \r\nVocê só pode usar cada um dos seguintes efeitos de ""Estripadora/M" K9-X" uma vez por turno. \r\nSe este card for Invocado por Invocação-Especial por um efeito de Magia/Armadilha "K9": você pode escolher até 2 cards no Cemitério do seu oponente e/ou banimento; embaralhe-os no Deck. \r\nQuando seu oponente ativar um efeito de monstro (Efeito Rápido): você pode desassociar 2 matérias deste card; negue o efeito e, depois, destrua todos os cards no campo.','\r',char(13)),'\n',char(10)),'Retornar ao Deck','Destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31292357,'Camaramágico Engana Chapéu',replace(replace('Se 2 ou mais monstros estiverem no campo, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nQuando um card ou efeito que causaria dano a você for ativado (Efeito Rápido): você pode colocar 1 Marcador Camaramágico neste card (máx. 3) e, depois, transforme em 0 esse dano de efeito a você. \r\nQuando o 3º Marcador Camaramágico for colocado neste card, seu ATK/DEF se tornam 3300.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31303283,'Hipogrifo da Chama Nebulosa',replace(replace('Seu oponente não pode escolher este card como alvo de efeitos de card. \r\nUma vez por turno: você pode oferecer como Tributo 1 outro monstro de FOGO; este card ganha 300 de ATK.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31305911,'Marshmallon',replace(replace('Não pode ser destruído em batalha. \r\nDepois do cálculo de dano, se este card foi atacado e estava com a face para baixo no começo da Etapa de Dano: o duelista atacante sofre 1000 de dano.','\r',char(13)),'\n',char(10)),'Receba 1000 pontos de dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31305912,'Marshmallon',replace(replace('Não pode ser destruído em batalha. \r\nDepois do cálculo de dano, se este card foi atacado e estava com a face para baixo no começo da Etapa de Dano: o duelista atacante sofre 1000 de dano.','\r',char(13)),'\n',char(10)),'Receba 1000 pontos de dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31313405,'Salamagrande Piro Fênix',replace(replace('2+ Monstros de Efeito de FOGO	\r\nSe este card for Invocado por Invocação-Link usando "Salamagrande Piro Fênix" como matéria: você pode destruir todos os cards que seu oponente controla. \r\nVocê só pode usar cada um dos seguintes efeitos de "Salamagrande Piro Fênix" uma vez por turno.\r\n● Você pode escolher 1 Monstro Link no Cemitério do seu oponente; Invoque-o por Invocação-Especial no campo do seu oponente.\r\n● Se um ou mais Monstros Link forem Invocados por Invocação-Especial no campo do seu oponente (exceto durante a Etapa de Dano): você pode escolher 1 desses monstros; cause dano ao seu oponente igual ao ATK original desse monstro.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31314549,'Ataqueraptor - Lanius Cantante',replace(replace('Se você controlar um Monstro Xyz com a face para cima, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Ataqueraptor - Lanius Cantante" por Invocação-Especial uma vez por turno desta forma.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31320433,'Número 47: Tubarão Pesadelo',replace(replace('2 monstros de Nível 3	\r\nQuando este card for Invocado por Invocação-Especial: você pode associar 1 monstro de ÁGUA de Nível 3 da sua mão ou do seu lado do campo a este card como uma Matéria Xyz. \r\nUma vez por turno: você pode desassociar 1 Matéria Xyz deste card e, depois, escolher 1 monstro de ÁGUA que você controla; neste turno, esse monstro pode atacar diretamente seu oponente e, além disso, outros monstros não podem atacar.','\r',char(13)),'\n',char(10)),'Associar material','Ataque direto','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31322640,'Palácio Cativante',replace(replace('Monstros Mago que você controla ganham 500 de ATK/DEF. \r\nVocê pode enviar 1 card da sua mão para o Cemitério; adicione à sua mão ou Invoque por Invocação-Especial no campo do seu oponente, 1 monstro "Rainha Cativante" do seu Deck. \r\nVocê só pode usar este efeito de "Palácio Cativante" três vezes por turno. \r\nMonstros de Efeito "Rainha Cativante" que você controla ganham este efeito.\r\n● Você pode enviar para o Cemitério este card equipado com um ou mais cards por seu próprio efeito; Invoque por Invocação-Especial 1 monstro Mago com 1500 ou menos de ATK da sua mão ou do Deck.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial (Palácio Cativante)','Escolha um monstro "Rainha do encanto" do Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31328739,'Impulso Psíquico',replace(replace('Ofereça como Tributo 1 monstro do Tipo Psíquico. \r\nDevolva todos os cards na mão do seu oponente para o Deck. \r\nDepois, ele compra 3 cards.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31339260,'Guerreiro Zumbi','"Servo Caveira" + "Guerreiro Batalhador"','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31353051,'Dragão Explosifoguette',replace(replace('Quando um efeito de Monstro Link for ativado que escolha como alvo este card com a face para cima no campo (Efeito Rápido): você pode destruir este card e, depois, cada duelista sofre 2000 de dano. \r\nDurante a Fase Final, se este card estiver no Cemitério porque foi destruído no campo, em batalha ou por um efeito de card e enviado para lá neste turno: você pode Invocar por Invocação-Especial 1 monstro "Foguette" do seu Deck, exceto "Dragão Explosifoguette". \r\nVocê só pode usar cada efeito de "Dragão Explosifoguette" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31374201,'Barba Branca, o Leme Saquepatrollha',replace(replace('Durante o turno do seu oponente (Efeito Rápido): você pode Invocar por Invocação-Especial 1 monstro "Saquepatrollha" do seu Deck Adicional com o mesmo Atributo que o de um monstro que seu oponente controla ou no Cemitério dele e, se isso acontecer, equipe este card que você controla a ele. \r\nSe este card for enviado da mão ou da Zona de Monstros para o Cemitério: você pode ativar este efeito; Invoque por Invocação-Especial 1 monstro "Saquepatrollha" do seu Deck, exceto "Barba Branca, o Leme Saquepatrollha" e, além disso, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros "Saquepatrollha". \r\nVocê só pode usar cada efeito de "Barba Branca, o Leme Saquepatrollha" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31383545,'Sabre-XX Darksoul','Uma vez por turno, durante a Fase Final, se este card estiver no Cemitério porque foi enviado para lá do seu campo neste turno: você pode adicionar 1 monstro "Sabre-X" do seu Deck à sua mão.','Procurar no Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31385077,'Deusa do Caos',replace(replace('1 Regulador de LUZ + 2+ monstros não-Reguladores de TREVAS	\r\nUma vez por turno: você pode enviar 1 monstro de LUZ da sua mão para o Cemitério e, depois, escolha 1 monstro de TREVAS de Nível 5 ou mais no seu Cemitério; Invoque esse monstro por Invocação-Especial, mas ele não pode ser usado como Matéria Sincro.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31386180,'Tiras, Protetor da Gênesis',replace(replace('2 monstros de Nível 5	\r\nOs efeitos deste card só podem ser aplicados/resolvidos enquanto ele tiver matéria. \r\nNão pode ser destruído por efeitos de card. \r\nNo final da Fase de Batalha, se este card batalhou: escolha 1 card que seu oponente controla; destrua o alvo. \r\nUma vez por turno, durante sua Fase Final: desassocie 1 matéria deste card.','\r',char(13)),'\n',char(10)),'Escolha 1 card que seu oponente controla para destruir','Desassociar 1 Matéria Xyz','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31398842,'Força Xyz',replace(replace('Envie 1 card "Xyz" do seu Deck para o Cemitério, exceto "Força Xyz", ou, se um Monstro Xyz que tiver um Monstro Xyz como matéria estiver no campo, em vez disso, você pode adicionar o card "Xyz" à sua mão. \r\nDurante sua Fase Principal, exceto no turno em que este card foi enviado para o Cemitério: você pode banir este card do seu Cemitério; desassocie 1 matéria de um Monstro Xyz em qualquer campo e, depois, se a matéria desassociada era um Monstro Xyz, você pode Invocar esse monstro por Invocação-Especial do seu Cemitério ou do seu banimento, em Posição de Defesa. \r\nVocê só pode usar cada efeito de "Força Xyz" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Desassociar Matéria Xyz','Adicionar à mão?','Invocação Especial?','','','','','','','','','','','','');
INSERT INTO texts VALUES(31411835,'Hecamãos Dandalos',replace(replace('2 monstros "Hecamãos"	\r\nVocê pode escolher 1 monstro que seu oponente controla; tome o controle dele. \r\nVocê só pode usar este efeito de "Hecamãos Dandalos" uma vez por turno. \r\nSe este card batalhar um monstro, nenhum dos dois pode ser destruído nessa batalha. \r\nSeus Monstros de Fusão "Hecamãos" e os monstros que você controla dos quais seu oponente seja dono podem atacar diretamente.','\r',char(13)),'\n',char(10)),'Tomar controle','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31423101,'Lâmina de Phoenix - Espada Divina',replace(replace('Só pode ser equipado a um monstro Guerreiro. \r\nEle ganha 300 de ATK. \r\nDurante sua Fase Principal, se este card estiver no seu Cemitério: você pode banir 2 monstros Guerreiro do seu Cemitério; adicone este card à sua mão.','\r',char(13)),'\n',char(10)),'Adicione este card à sua mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31425736,'Copinho☆Nhamy',replace(replace('Se você controlar um monstro de Link-1 ou um Monstro Sincro de Nível 2, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Copinho☆Nhamy" por Invocação-Especial uma vez por turno desta forma. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 card "Nhamy" do seu Deck à sua mão, exceto "Copinho☆Nhamy", ou, se este card foi Invocado por Invocação-Especial pelo efeito de um Monstro Sincro, em vez disso, você pode comprar 1 card. \r\nVocê só pode usar este efeito de "Copinho☆Nhamy" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Adicionar à mão','Usar como compra substituta?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31434645,'Eldland Amaldiçoada',replace(replace('Você não pode declarar ataques, exceto com monstros Zumbi. \r\nVocê só pode usar cada um dos seguintes efeitos de "Eldland Amaldiçoada" uma vez por turno.\r\n● Você pode pagar 800 PV; adicione 1 monstro "Eldlich" ou 1 Magia/Armadilha "Terra Dourada" do seu Deck à sua mão.\r\n● Se este card for enviado da Zona de Magias & Armadilhas para o Cemitério: você pode enviar 1 monstro "Eldlich" ou 1 Magia/Armadilha "Terra Dourada" do seu Deck para o Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31437713,'Número 82: Dracoração',replace(replace('2 monstros de Nível 4	\r\nEnquanto você controlar um ou mais Cards de Magia com a face para cima, este card não pode ser escolhido como alvo de ataques. \r\nUma vez por turno: você pode desassociar 1 Matéria Xyz deste card; neste turno, este card pode atacar diretamente seu oponente, mas outros monstros não podem atacar.','\r',char(13)),'\n',char(10)),'Ataque direto','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31440046,'Rochanimados Travesso-Guris',replace(replace('Se este card for enviado para o Cemitério como matéria para a Invocação-Fusão ou Link de um monstro "Travesso-Guris": você pode banir 1 card da sua mão e, se isso acontecer, compre 1 card e, depois, você pode Invocar por Invocação-Especial 1 monstro "Travesso-Guris" da sua mão ou do Deck em Posição de Defesa, exceto "Rochanimados Travesso-Guris". \r\nVocê só pode usar este efeito de "Rochanimados Travesso-Guris" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Invocação Especial?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31440542,'Sedução de Rafflesia','VIRE: Até ao final do turno, controle 1 monstro no Campo do seu adversário com a face para cima.','Tomar controle','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31443476,'Lançamento Rápido','Invoque por Invocação-Especial 1 monstro "Foguette" do seu Deck, mas ele não pode atacar e, além disso, destrua-o durante a Fase Final.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31444249,'Imaginação do Vácuo',replace(replace('Os monstros "Infernoide" que você controla cujo Nível original seja 2 ou mais se tornam de Nível 1 e todo dano de batalha que eles causarem ao seu oponente é diminuído pela metade. \r\nVocê pode enviar este card para o Cemitério; Invoque por Invocação-Fusão 1 Monstro de Fusão "Infernoide" do seu Deck Adicional, usando monstros da sua mão ou do campo como matéria. \r\nSe seu oponente controlar um monstro que foi Invocado por Invocação-Especial do Deck Adicional e você não controlar nenhum, você também pode usar até 6 monstros do seu Deck como Matérias de Fusão.','\r',char(13)),'\n',char(10)),'Escolher também Matérias de Fusão do Deck?','Escolher também Matérias de Fusão da mão/do campo?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31444250,'Imaginação do Vácuo',replace(replace('Os monstros "Infernoide" que você controla cujo Nível original seja 2 ou mais se tornam de Nível 1 e todo dano de batalha que eles causarem ao seu oponente é diminuído pela metade. \r\nVocê pode enviar este card para o Cemitério; Invoque por Invocação-Fusão 1 Monstro de Fusão "Infernoide" do seu Deck Adicional, usando monstros da sua mão ou do campo como matéria. \r\nSe seu oponente controlar um monstro que foi Invocado por Invocação-Especial do Deck Adicional e você não controlar nenhum, você também pode usar até 6 monstros do seu Deck como Matérias de Fusão.','\r',char(13)),'\n',char(10)),'Escolher também Matérias de Fusão do Deck?','Escolher também Matérias de Fusão da mão/do campo?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31447217,'Tecedor de Asas','Um anjo com seis asas que reza pela paz e esperança.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31456110,'Hordeum Maligno Golem','Uma vez por turno: você pode escolher 1 monstro que não é de TREVAS de Nível 5 ou mais no campo; destrua o alvo.','Destruir um monstro','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31458630,'Concerto das Melodiosas',replace(replace('Invoque por Invocação-Fusão 1 Monstro de Fusão Fada do seu Deck Adicional, usando monstros da sua mão, do campo e/ou das Zonas de Pêndulo. \r\nSe um ou mais Monstros de Fusão "Melodiosa(o)" forem enviados para o seu Cemitério enquanto este card estiver no seu Cemitério, mesmo durante a Etapa de Dano: você pode colocar este card no fundo do seu Deck e, depois, compre 1 card. \r\nVocê só pode usar cada efeito de "Concerto das Melodiosas" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31461282,'Pedra Milagrosa',replace(replace('Você só pode controlar 1 "Pedra Milagrosa". \r\nTodos os monstros Mago que você controla ganham 500 de ATK/DEF para cada monstro "Fada Fortuna" que você controla com nomes diferentes. \r\nUma vez por turno, quando um ataque for declarado envolvendo um monstro "Fada Fortuna" seu: você pode comprar 1 card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31464658,'Fantasma de Três Olhos',replace(replace('Você pode enviar este card do campo para o Cemitério; adicione 1 monstro de TREVAS de Nível 10 do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Fantasma de Três Olhos" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31467372,'Canhão Eterno do Submundo','Uma vez por turno, quando um monstro do Tipo Zumbi for Invocado por Invocação-Especial no seu lado do campo: cause 800 de dano ao seu oponente.','Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31467949,'Recon, a Batedora de Peluguel',replace(replace('Durante sua Fase Principal: você pode Invocar por Invocação-Especial 1 monstro "de Peluguel" da sua mão, exceto "Recon, a Batedora de Peluguel". \r\nSe um monstro "de Peluguel" for Invocado por Invocação-Especial no seu campo enquanto você controlar este monstro (exceto durante a Etapa de Dano): você pode escolher 1 card Baixado no campo; destrua-o. \r\nVocê só pode usar cada efeito de "Recon, a Batedora de Peluguel" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31472884,'Frente Unificada',replace(replace('Descarte 1 monstro e, depois, escolha 1 monstro com a face para cima no campo; até o final deste turno, seu ATK e DEF se tornam o ATK e DEF do monstro descartado. \r\nOs monstros que você controla não podem atacar diretamente durante o turno em que você ativar este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31476755,'Barreira de Poeira',replace(replace('Monstros Normais no Campo com a face para cima não são afetados pelos Cards de Magia do seu adversário. \r\nEste card é destruído durante a sua segunda Standby Phase depois da activação.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31477025,'Sr. Vulcão','Esta criatura com um comportamento aparentemente moderado tem um temperamento extremamente volátil.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31480215,'Besta Fantasma Mecha Canoburan',replace(replace('Se este card for enviado para o Cemitério para a Invocação-Sincro de um monstro do Tipo Máquina: Invoque por Invocação-Especial 1 "Ficha de Besta Fantasma Mecha" (Tipo Máquina/VENTO/Nível 3/ATK 0/DEF 0) e, além disso, pelo restante deste turno, você não pode Invocar nenhum outro monstro por Invocação-Especial, exceto monstros de VENTO. \r\nEnquanto você controlar uma Ficha, este card não pode ser destruído em batalha ou por efeitos de card. \r\nVocê pode oferecer como Tributo 1 outro monstro "Besta Fantasma Mecha"; aumente em 1 o Nível deste card. \r\nVocê só pode usar 1 efeito de "Besta Fantasma Mecha Canoburan" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar uma Ficha por Invocação Especial','Aumentar o Nível','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31480216,'Ficha de Besta Fantasma Mecha','Invocado por Especial com o efeito de um monstro "Besta Fantasma Mecha" ou um card relacionado.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31516413,'Dragão Hierático de Nebthet',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) ao oferecer como Tributo 1 monstro "Hierático". \r\nUma vez por turno: você pode oferecer como Tributo 1 outro monstro "Hierático" da sua mão ou do campo e, depois, escolha 1 monstro que seu oponente controla; destrua o alvo. \r\nSe este card for oferecido como Tributo: Invoque por Invocação-Especial 1 Monstro Normal Dragão da sua mão, do Deck ou do Cemitério, e torne seu ATK/DEF 0.','\r',char(13)),'\n',char(10)),'Destruir','Invocação Especial','Forma de Invocação: Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31525442,'Zolga, o Profeta',replace(replace('Se você controlar um monstro Fada de TERRA, exceto "Zolga, o Profeta": você pode Invocar este card por Invocação-Especial da sua mão e, depois, olhe até 5 cards do topo do Deck de cada duelista. \r\nQuando um monstro que foi Invocado por Invocação-Normal pelo Tributo deste card declarar um ataque: você pode banir este card do seu Cemitério; destrua esse monstro e, se isso acontecer, cause 2000 de dano ao seu oponente. \r\nVocê só pode usar cada efeito de "Zolga, o Profeta" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Escolha quantos cards revelar do seu Deck','Escolha quantos cards revelar do Deck do seu oponente','Ofereça "Zolga, o Profeta" como Tributo para Invocar','','','','','','','','','','','');
INSERT INTO texts VALUES(31531170,'Oscilação Harmônica','Se seu oponente tiver 2 cards nas Zonas de Pêndulo dele: escolha esses 2 cards; enquanto os dois alvos estiverem nas Zonas de Pêndulo dele, neste turno, você pode Invocar por Invocação-Pêndulo usando as Escalas de Pêndulo dele, mas apenas do Deck Adicional.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31531914,'Ogro Desacorrentado - Shma',replace(replace('Se este card for Invocado por Invocação-Normal: você pode Invocar por Invocação-Especial 1 monstro "Desacorrentado(a)" de Nível 4 ou menor do seu Deck, exceto "Ogro Desacorrentado - Shma", então destrua 1 card que você controla, você também não pode Invocar por Invocação-Especial pelo resto deste turno, exceto monstros Demônio.\r\nSe este card é destruído no campo por um efeito, exceto por "Ogro Desacorrentado - Shma", ou por batalha: você pode Invocar por Invocação-Especial 1 monstro "Desacorrentado" da sua mão ou Deck, exceto "Ogro Desacorrentado - Shma".\r\nVocê só pode usar cada um dos efeitos de "Ogro Desacorrentado - Shma" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial do Deck','Invocar por Invocação Especial da sua mão/Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31533473,'Companhia de Palhaços Diabolo',replace(replace('2 monstros com o mesmo Atributo, mas Tipos diferentes	\r\nSe um monstro Invocado por Invocação-Tributo seu atacar um monstro em Posição de Defesa, cause o dobro de dano de batalha perfurante ao seu oponente. \r\nSe este card for oferecido como Tributo: você pode ativar 1 desses efeitos (mas você só pode usar cada efeito de "Companhia de Palhaços Diabolo" uma vez por turno);\r\n● Devolva para o Deck Adicional todos os Monstros de Fusão do campo e dos Cemitérios.\r\n● Baixe 1 Armadilha "Companhia de Palhaços" do seu Deck.','\r',char(13)),'\n',char(10)),'Escolher um efeito','Retornar Monstros Fusão ao Deck','Baixar um Card de Armadilha','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31533704,'Besta Fantasma Mecha Megarraptor',replace(replace('Quando uma ou mais Fichas forem Invocadas por Invocação-Especial no seu lado do campo: Invoque por Invocação-Especial 1 "Ficha de Besta Fantasma Mecha" (Tipo Máquina/VENTO/Nível 3/ATK 0/DEF 0). \r\nVocê só pode usar este efeito de "Besta Fantasma Mecha Megarraptor" uma vez por turno. \r\nO Nível deste card aumenta em um valor igual à soma dos Níveis de todas as "Fichas de Besta Fantasma Mecha" que você controla. \r\nEnquanto você controlar uma Ficha, este card não pode ser destruído em batalha ou por efeitos de card. \r\nUma vez por turno: você pode oferecer 1 Ficha como Tributo; adicione 1 monstro "Besta Fantasma Mecha" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Invocar uma Ficha por Invocação Especial','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31533705,'Ficha de Besta Fantasma Mecha','Invocado por Especial com o efeito de um monstro "Besta Fantasma Mecha" ou um card relacionado.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31539614,'Vacinadora',replace(replace('2+ monstros de Nível 3	\r\n(Efeito Rápido): você pode desassociar 1 matéria deste card e, depois, escolha 1 monstro no campo cujo ATK ou DEF atuais sejam diferentes do seu valor original; seu ATK/DEF se tornam seus valores originais e, além disso, se você escolheu um monstro no seu campo, ele não pode ser destruído em batalha ou por efeitos de card neste turno. \r\nUma vez por turno, se um ou mais outros monstros forem Invocados por Invocação-Especial no seu campo e este card tiver 3 ou mais matérias (exceto durante a Etapa de Dano): você pode fazer com que esse(s) monstro(s) ganhe(m) 900 de ATK.','\r',char(13)),'\n',char(10)),'Redefinir ATK/DEF ao original e ganhar proteção contra destruição','Aumentar ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31548215,'Buraco Armadilha do Sepultureiro','Quando seu oponente ativar um efeito de monstro na mão ou no Cemitério dele, ou quando um efeito de monstro banido do seu oponente for ativado: negue seu efeito e, se isso acontecer, cause 2000 de dano ao seu oponente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31548814,'Banquete do Vácuo','Envie 1 Magia/Armadilha "Vácuo" da sua mão ou do campo com a face para cima para o Cemitério; Invoque por Invocação-Especial até 3 monstros "Infernoide" do seu Deck, cuja soma dos Níveis seja exatamente igual a 8, ignorando suas condições de Invocação.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31550470,'Fuga da Dimensão Negra',replace(replace('Escolha 1 dos seus monstros de TREVAS banidos; Invoque o alvo por Invocação-Especial. \r\nQuando este card deixar o campo, destrua o alvo e, se isso acontecer, bana-o. \r\nQuando o alvo for destruído, destrua este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31552317,'Inclusão Cristron',replace(replace('Quando este card for ativado: você pode adicionar 1 card "Cristron" do seu Deck à sua mão, exceto "Inclusão Cristron". \r\nNa primeira vez que cada monstro "Cristron" que você controla seria destruído em batalha a cada turno, ele não é destruído. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 monstro "Cristron" no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê só pode usar este efeito de "Inclusão Cristron" uma vez por turno. \r\nVocê só pode ativar 1 "Inclusão Cristron" por turno.','\r',char(13)),'\n',char(10)),'Ativar','Invocação Especial','Adicionar este card à mão?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31553716,'Dragão Lanceiro',replace(replace('Se este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante. \r\nSe este card atacar, ele é colocado em Posição de Defesa no final da Etapa de Dano.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31554054,'Evasão Vingativa Xyz','Quando um Monstro Xyz com a face para cima que você controla for alvo de um ataque: escolha 1 Monstro Xyz no seu Cemitério; devolva o alvo do ataque, com a face para cima, para o Deck Adicional e, depois, Invoque por Invocação-Especial o alvo deste card, do Cemitério, e, se isso acontecer, associe este card a ele como uma Matéria Xyz.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31557782,'Mecanismo Antigo','Se você controlar um "Mecanismo Antigo", você pode Invocar este card por Invocação-Especial (da sua mão) em Posição de Ataque.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31560081,'Maga da Fé','VIRE: Escolha 1 Magia no seu Cemitério; adicione o alvo à sua mão.','Recuperar uma Magia','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31562086,'Ponta Rúnika',replace(replace('Ative 1 desses efeitos, mas pule sua próxima Fase de Batalha depois da ativação;\r\n● Adicione 1 card "Rúnika(o)" do seu Deck à sua mão, exceto "Ponta Rúnika" e, depois, bana o card do topo do Deck do seu oponente.\r\n● Invoque por Invocação-Especial 1 monstro "Rúnika(o)" do seu Deck Adicional na Zona de Monstros Adicional.	\r\nVocê só pode ativar 1 "Ponta Rúnika" por turno.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31563350,'General Zubaba',replace(replace('2 monstros de Nível 4	\r\nUma vez por turno: você pode desassociar 1 Matéria Xyz deste card; equipe 1 monstro do Tipo Guerreiro da sua mão a este card. \r\nEste card ganha ATK igual à soma do ATK dos monstros equipados a ele por este efeito.','\r',char(13)),'\n',char(10)),'Equipar monstros','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31571902,'Mech Malévolo - Goku En',replace(replace('Você pode Invocar este card por Invocação-Normal sem oferecer Tributo. \r\nUma vez por turno, durante a Fase Final, se este card foi Invocado desta forma: envie-o para o Cemitério e, depois, sofra dano igual ao ATK original dele no Cemitério. \r\nEste card deve ser o único monstro Zumbi no campo para que você possa ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Invocação Normal sem Tributo','Enviar para o Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31588572,'Gêmeos Desacorrentados - Sarama',replace(replace('Você pode escolher 1 card "Desacorrentado(a)" no seu Cemitério, exceto "Gêmeos Desacorrentados - Sarama"; Baixe-o no seu campo e, depois, destrua 1 card que você controla. \r\nSe este card no campo for destruído por um efeito de card, exceto "Gêmeos Desacorrentados - Sarama", ou em batalha: você pode Invocar por Invocação-Especial 1 monstro "Desacorrentado(a)" da sua mão ou do Deck, exceto "Gêmeos Desacorrentados - Sarama". \r\nVocê só pode usar cada efeito de "Gêmeos Desacorrentados - Sarama" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31596518,'Eidos, o Monarca do Submundo',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 Magia/Armadilha "Monarca" ou 1 monstro com 2800 ATK/1000 DEF do seu Deck ou Cemitério à sua mão. \r\nVocê pode declarar 1 Atributo; faça com que 1 monstro com a face para cima no campo se torne desse Atributo. \r\nSe você Invocar por Invocação-Tributo um monstro com 2400 ou mais de ATK e 1000 de DEF, enquanto este card estiver no seu Cemitério: você pode adicionar este card à sua mão ou Invocá-lo por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Eidos, o Monarca do Submundo" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Alterar Atributo','Recuperar do Cemitério','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31600513,'Louva-a-deus Predador',replace(replace('Uma vez por turno, quando um monstro do oponente declarar um ataque: você pode enviar 1 card da sua Zona de Magias & Armadilhas para o Cemitério; devolva esse monstro do oponente para a mão. \r\nVocê só pode usar cada um dos seguintes efeitos de "Louva-a-deus Predador" uma vez por turno. \r\nDurante sua Fase de Apoio: você pode Invocar por Invocação-Especial 1 "Ficha de Louva-a-deus Bebê" (Inseto/VENTO/Nível 1/ATK 500/DEF 500). \r\nVocê pode banir este card do seu Cemitério; Invoque por Invocação-Especial 1 "Ficha de Louva-a-deus Bebê".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31600514,'Ficha de Louva-a-deus Bebê','Invocado por Especial com o efeito "Louva-a-deus Predador".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31600845,'Arlekino, a Abominação da Diversão',replace(replace('Se você controlar um monstro "Diversão": você pode Invocar este card por Invocação-Especial da sua mão e, depois, você pode adicionar 1 "Rostos Familiares da Diversão" do seu Deck ou Cemitério à sua mão. \r\nDurante o turno do seu oponente (Efeito Rápido): você pode escolher 1 outro Monstro de Efeito no campo com mais que 0 de ATK; embaralhe este card no Deck e, se isso acontecer, Invoque por Invocação-Especial 1 "Arlekino, o Administrador da Diversão" do seu Deck e, depois, mude o ATK do monstro alvo para 0. \r\nVocê só pode usar cada efeito de "Arlekino, a Abominação da Diversão" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar "Rostos Familiares da Diversão" à sua mão?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31603289,'Copinho★Via Nhamy',replace(replace('1 Regulador + 1 monstro não-Regulador	\r\nPara a Invocação-Sincro deste card, você pode considerar 1 monstro de Link-1 que você controla como um Regulador de Nível 1. \r\nVocê só pode usar cada um dos seguintes efeitos de "Copinho★Via Nhamy" uma vez por turno. \r\nSe este card for Invocado por Invocação-Sincro: você pode adicionar 2 monstros "Nhamy" do seu Deck à sua mão e, depois, descarte 1 card. \r\nQuando seu oponente ativar um card ou efeito (Efeito Rápido): você pode devolver este card para o Deck Adicional; Invoque por Invocação-Especial até 2 monstros "Nhamy" do seu Cemitério.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31615285,'Fortalhão Cacto',replace(replace('Não pode ser Invocado por Invocação-Especial. \r\nEnquanto outro monstro Planta estiver no campo, nenhum duelista pode Invocar monstros por Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31629407,'Mágica Mosqueteira Starfire',replace(replace('Durante o turno de qualquer duelista, você pode ativar Cards de Magia/Armadilha "Mágico(a) Mosquete" da sua mão. \r\nSe um Card de Magia/Armadilha for ativado na coluna deste card (exceto durante a Etapa de Dano): você pode Invocar por Invocação-Especial 1 monstro "Mágico(a) Mosquete" de Nível 4 ou menos do seu Deck em Posição de Defesa, exceto "Mágica Mosqueteira Starfire". \r\nVocê só pode usar este efeito de "Mágica Mosqueteira Starfire" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial do Deck','Ativar aplicando o efeito de "Mágica Mosqueteira Starfire".','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31632536,'Golpeador-Duplo Laval',replace(replace('1 Regulador + 1 ou mais monstros de FOGO não-Reguladores	\r\nEste card ganha efeitos baseado no número de monstros "Laval" no seu Cemitério:\r\n● 2+: Uma vez por turno, se este card atacar um monstro em Posição de Defesa, ele pode atacar novamente em seguida.\r\n● 3+: Se este card atacar um monstro em Posição de Defesa, cause Dano de Batalha perfurante ao seu oponente.','\r',char(13)),'\n',char(10)),'Continuar atacando?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31643613,'Predaprática',replace(replace('Invoque por Invocação-Especial 1 monstro "Predaplanta" da sua mão e, depois, adicione 1 card "Predap" do seu Deck à sua mão, exceto "Predaprática" e, além disso, pelo resto deste turno depois que este card resolver, você não pode Invocar monstros por Invocação-Especial do Deck Adicional, exceto Monstros de Fusão. \r\nVocê só pode ativar 1 "Predaprática" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31677606,'Onda Preta e Branca','Se houver um Monstro Xyz com a face para cima no campo com um Monstro Sincro como Matéria Xyz: escolha 1 card no campo; bana o alvo e, se isso acontecer, compre 1 card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31683874,'Fada Fortuna Ann',replace(replace('Quando você comprar este card: você pode revelá-lo; Invoque-o por Invocação-Especial da sua mão. \r\nSe este card for Invocado por Invocação-Especial da mão: você pode banir 1 monstro Mago do seu Deck. \r\nVocê só pode usar cada efeito de "Fada Fortuna Ann" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31692182,'Barreira Hídrica Koa''ki Meiru',replace(replace('Você pode devolver 1 "Núcleo de Ferro de Koa''ki Meiru" da sua mão para o topo do Deck. \r\nSe isso acontecer, os efeitos de todos os Monstros de Efeito com a face para cima são negados até a Fase de Apoio do seu próximo turno, exceto monstros "Koa''ki Meiru".','\r',char(13)),'\n',char(10)),'Negar o efeito','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31699677,'Magikuriboh',replace(replace('Durante a Fase Principal ou de Batalha, se você sofreu dano em batalha ou por um efeito de card do oponente neste turno (Efeito Rápido): você pode enviar este card da sua mão para o Cemitério; Invoque por Invocação-Especial 1 "Mago Negro" ou 1 "Pequena Maga Negra" do seu Deck ou Cemitério. \r\nSe um ou mais monstros Mago com a face para cima que você controla forem destruídos em batalha ou por um efeito de card do oponente: você pode adicionar este card do Cemitério à sua mão. \r\nVocê só pode usar cada efeito de "Magikuriboh" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31706048,'Sobrevivente do Legado Mundial',replace(replace('Escave os 5 cards do topo do seu Deck e, se isso acontecer, adicione 1 monstro "Krawler" ou card "Legado Mundial" escavado à sua mão e, além disso, envie os cards restantes para o Cemitério. \r\nCaso contrário, embaralhe todos os cards escavados no Deck. \r\nPelo resto deste turno depois que este card resolver, você não pode Invocar monstros do Deck Adicional por Invocação-Especial, exceto Monstros Link. \r\nVocê só pode ativar 1 "Sobrevivente do Legado Mundial" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31709826,'Geleia Renascida','Quando este card for destruído em batalha e enviado para o Cemitério: você pode pagar 1000 PV; Invoque-o por Invocação-Especial em Posição de Defesa durante sua próxima Fase de Apoio.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31712840,'Aliança Zexal',replace(replace('Se um ou mais Monstros Xyz com a face para cima que você controla forem destruídos em batalha ou por um efeito de card do oponente: pague PV até ter apenas 10 sobrando; Invoque por Invocação-Especial 1 monstro "Utopia" do seu Cemitério e, se isso acontecer, pegue 1 card do seu Deck e coloque-o no topo do seu Deck. \r\nO ATK desse monstro Invocado por Invocação-Especial se torna o dobro e, além disso, ele não pode ser destruído em batalha, exceto em batalha com um monstro "Número", nem por efeitos de card.','\r',char(13)),'\n',char(10)),'','O efeito de "Aliança Zexal" está sendo aplicado.','Escolha o(s) card(s) para colocar no topo do Deck','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31733941,'Dragão Toon de Olhos Vermelhos',replace(replace('Não pode atacar no turno em que for Invocado. \r\nEnquanto você controlar "Mundo Toon" e seu oponente não controlar monstros Toon, este card pode atacar diretamente seu oponente. \r\nUma vez por turno: você pode Invocar por Invocação-Especial 1 monstro Toon da sua mão, exceto "Dragão Toon de Olhos Vermelhos", ignorando suas condições de Invocação.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31755044,'Rabochicote Zoodíaco',replace(replace('(Efeito Rápido): você pode escolher 1 Monstro Xyz Besta-Guerreira que você controla; associe este card da sua mão ou do campo a ele como matéria. \r\nUm Monstro Xyz cujo Tipo original seja Besta-Guerreira e que tenha este card como matéria ganha este efeito.\r\n● Se este card batalhar um monstro do oponente, depois do cálculo de dano: bana o monstro do oponente.','\r',char(13)),'\n',char(10)),'Associar este card como Matéria Xyz','Banir o monstro em batalha do oponente (Rabochicote Zoodíaco)','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31759689,'Cão Tindângulo',replace(replace('VIRE: Você pode escolher 1 outro monstro com a face para cima no campo; este card ganha ATK igual ao ATK original do alvo e, depois, coloque o alvo com a face para baixo em Posição de Defesa.\r\nCada monstro que seu oponente controla perde 1000 de ATK para cada monstro linkado a ele. \r\nSe este card for destruído em batalha ou por um efeito de card e enviado para o Cemitério: você pode escolher 1 monstro com a face para baixo no campo; coloque-o com a face para cima em Posição de Defesa.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31764353,'Espírito-Possuído - Wynn',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão ou do Deck) ao enviar para o Cemitério 1 "Wynn, a Encantadora do Vento" com a face para cima e 1 monstro de VENTO com a face para cima que você controla. \r\nSe este card Invocado por Invocação-Especial por seu efeito atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31764354,'Espírito-Possuído - Wynn',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão ou do Deck) ao enviar para o Cemitério 1 "Wynn, a Encantadora do Vento" com a face para cima e 1 monstro de VENTO com a face para cima que você controla. \r\nSe este card Invocado por Invocação-Especial por seu efeito atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31764700,'Yubel - O Pesadelo Supremo',replace(replace('Não pode ser Invocado por Invocação-Normal ou Baixado. \r\nDeve ser Invocado por Invocação-Especial por "Yubel - Encarnação do Terror". \r\nNão pode ser destruído em batalha. \r\nVocê não sofre dano de batalha das batalhas envolvendo este card. \r\nNo final da Etapa de Dano, se este card com a face para cima em Posição de Ataque batalhou um monstro do oponente: cause dano ao seu oponente igual ao ATK desse monstro do oponente e, além disso, destrua esse monstro.','\r',char(13)),'\n',char(10)),'Causar dano e destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31766317,'Imperatriz Arquidemônio',replace(replace('Se exatamente 1 monstro Demônio de TREVAS com a face para cima no campo, exceto este card, seria destruído, em vez disso, você pode banir 1 monstro Demônio de TREVAS do seu Cemitério. \r\nQuando este card for destruído e enviado do campo para o Cemitério: você pode escolher 1 monstro Demônio de TREVAS de Nível 6 ou mais no seu Cemitério, exceto "Imperatriz Arquidemônio"; Invoque-o por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Usar o efeito de "Imperatriz Arquidemônio" em vez de ser destruído?','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31768112,'Superóleo',replace(replace('Uma vez por turno, você pode: escolher 1 monstro do Tipo Máquina que você controla; equipe este card ao alvo, OU: desequipe este card e Invoque-o por Invocação-Especial em Posição de Ataque. \r\nEnquanto estiver equipado por este efeito, se o monstro equipado destruir um monstro do oponente em batalha: compre 1 card. \r\n(Um monstro só pode estar equipado com 1 monstro União de cada vez. Se o monstro equipado seria destruído, em vez disso, destrua este card.)','\r',char(13)),'\n',char(10)),'Destruir','Comprar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31772684,'Revivido Vendorror',replace(replace('Se este card em sua posse for destruído por um card do oponente (em batalha ou por um efeito de card) e enviado para o seu Cemitério: você pode Invocar este card por Invocação-Especial, mas bana-o quando ele deixar o campo. \r\nUm monstro "Vendorror" Invocado por Invocação-Ritual usando este card no campo ganha este efeito. \r\nVocê só pode usar o efeito anterior de "Revivido Vendorror" uma vez por turno.\r\n● Uma vez por turno (Efeito Rápido): você pode escolher 1 monstro Invocado por Invocação-Especial que seu oponente controla; bana-o.','\r',char(13)),'\n',char(10)),'Invocar este card por Invocação Especial','Banir um monstro do oponente (Revivido Vendorror)','O efeito de "Revivido Vendorror" está sendo aplicado.','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31785398,'Pronto para Interceptar','Escolha 1 monstro Guerreiro ou Mago no campo; coloque o alvo com a face para baixo em Posição de Defesa.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31786629,'Dragão do Trovão','Você pode descartar este card; adicione até 2 "Dragão do Trovão" do seu Deck à sua mão.','Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31786838,'Regênese',replace(replace('Pegue 1 monstro "Regênese" do seu Deck e adicione-o à sua mão ou envie-o para o Cemitério ou, se você controlar um monstro "Regênese", em vez disso, você pode adicionar 1 monstro com 2500 de ATK e DEF do seu Deck à sua mão. \r\nSe este card estiver no seu Cemitério, exceto no turno em que foi enviado para lá: você pode bani-lo e, depois, escolha 1 monstro "Regênese" no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Regênese" uma vez por turno.','\r',char(13)),'\n',char(10)),'Manipulação do Deck','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31801517,'Número 62: Dragão Primordial de Fóton de Olhos das Galáxias',replace(replace('2 monstros de Nível 8	\r\nSe este card batalhar, durante o cálculo de dano (Efeito Rápido): uma vez por batalha, você pode desassociar 1 matéria deste card; apenas durante o cálculo de dano, este card ganha ATK igual às Classes combinadas de todos os Monstros Xyz atualmente no campo x 200. \r\nSe este card sob o controle do seu dono for destruído por um efeito de card do oponente enquanto tiver "Dragão de Fóton de Olhos das Galáxias" como matéria: você pode Invocar este card por Invocação-Especial durante sua 2ª Fase de Apoio depois da ativação e dobrar seu ATK. \r\nQualquer dano de batalha que este card causar ao seu oponente é diminuído pela metade a não ser que ele tenha "Dragão de Fóton de Olhos das Galáxias" como matéria.','\r',char(13)),'\n',char(10)),'Aumentar ATK','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31801518,'Número 62: Dragão Primordial de Fóton de Olhos das Galáxias',replace(replace('2 monstros de Nível 8	\r\nSe este card batalhar, durante o cálculo de dano (Efeito Rápido): uma vez por batalha, você pode desassociar 1 matéria deste card; apenas durante o cálculo de dano, este card ganha ATK igual às Classes combinadas de todos os Monstros Xyz atualmente no campo x 200. \r\nSe este card sob o controle do seu dono for destruído por um efeito de card do oponente enquanto tiver "Dragão de Fóton de Olhos das Galáxias" como matéria: você pode Invocar este card por Invocação-Especial durante sua 2ª Fase de Apoio depois da ativação e dobrar seu ATK. \r\nQualquer dano de batalha que este card causar ao seu oponente é diminuído pela metade a não ser que ele tenha "Dragão de Fóton de Olhos das Galáxias" como matéria.','\r',char(13)),'\n',char(10)),'Aumentar ATK','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31809476,'Lampejo de Heráldica',replace(replace('Escolha qualquer número de monstros com a face para cima que seu oponente controla; o nome desses monstros se torna "Desconhecido". \r\nDurante sua Fase Final, se você controlar um Monstro Xyz Psíquico e este card estiver no seu Cemitério: você pode Baixar este card, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar este efeito de "Lampejo de Heráldica" uma vez por turno.','\r',char(13)),'\n',char(10)),'Alterar nome do card','Baixar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31812496,'Estátua de Pedra dos Aztecas','Dobre qualquer dano de batalha que seu oponente sofrer quando ele atacar este monstro.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31817415,'Neos Armado',replace(replace('"Neos, o HERÓI do Elemento" + 1 monstro "Dragão Armado"	\r\nDeve ser Invocado por Invocação-Fusão. \r\nSe este card for Invocado por Invocação-Especial: você pode selecionar 1 monstro Dragão no seu Cemitério e destruir todos os monstros que seu oponente controla com Nível igual ou menor que o dele. \r\nQuando este card destruir um monstro em batalha: você pode fazer com que este card ganhe o seguinte efeito.\r\n● Durante a Fase Principal (Efeito Rápido): você pode oferecer este card como Tributo; Invoque por Invocação-Especial 1 Monstro de Fusão "HERÓI do Elemento" do seu Deck Adicional, ignorando suas condições de Invocação.','\r',char(13)),'\n',char(10)),'','','O efeito de "Neos Armado" está sendo aplicado.','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31822037,'Patrono do Poder da Purificação',replace(replace('2 Monstros que não sejam Link	\r\nSe este card for Invocado por Invocação-Link e você tiver um monstro "Patrono(a) do Poder" no seu Cemitério: você pode adicionar 1 card "Teorealizar" do seu Deck à sua mão. \r\nDurante a Fase Principal, se você controlar outro monstro Fada de TREVAS, você pode (Efeito Rápido): imediatamente depois que este efeito resolver, Invoque 1 Monstro Link por Invocação-Link usando matérias que você controla, incluindo este card. \r\nVocê só pode usar cada efeito de "Patrono do Poder da Purificação" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Invocação Link','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31826057,'Guerreiro Sinfônico Piaano',replace(replace('Uma vez por turno: você pode declarar 1 Tipo de Monstro e, depois, escolha 1 monstro "Guerreiro Sinfônico" no campo; ele se torna desse Tipo. \r\nVocê pode declarar 1 Tipo de Monstro e banir este card do seu Cemitério e, depois, escolha 1 monstro "Guerreiro Sinfônico" que você controla; o alvo se torna desse Tipo.','\r',char(13)),'\n',char(10)),'Alterar Tipo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31828916,'Unidade Blindada Autômata','Uma vez por turno, quando um monstro Máquina for destruído em batalha e enviado para o seu Cemitério: você pode Invocar por Invocação-Especial 1 monstro Máquina do seu Deck que tenha o mesmo Atributo e menos ATK que o monstro destruído no Cemitério.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31829185,'Necrofear das Trevas',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro deve ser Invocado por Invocação-Especial (da sua mão) ao banir 3 monstros Demônio do seu Cemitério. \r\nDurante a Fase Final, se este card estiver no seu Cemitério porque foi destruído na sua Zona de Monstros por um card do oponente e enviado para lá neste turno: escolha 1 monstro com a face para cima que seu oponente controla; equipe este card no alvo. \r\nEnquanto este card estiver equipado a um monstro por este efeito, tome o controle desse monstro.','\r',char(13)),'\n',char(10)),'Tomar controle','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31833038,'Dragão Callibregado',replace(replace('3+ Monstros de Efeito	\r\nNenhum duelista pode escolher este card como alvo de efeitos de monstro. \r\nUma vez por turno (Efeito Rápido): você pode escolher 1 monstro com a face para cima no campo; ele perde 500 de ATK/DEF. \r\nSeu oponente não pode ativar cards ou efeitos em resposta à ativação deste efeito. \r\nNo começo da Etapa de Dano, se este card atacar um monstro do oponente: você pode colocar esse monstro do oponente em uma zona para a qual este card apontar e tomar o controle dele, mas envie-o para o Cemitério durante a Fase Final do próximo turno.','\r',char(13)),'\n',char(10)),'Reduzir ATK/DEF','Tomar controle','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31833039,'Dragão Callibregado',replace(replace('3+ Monstros de Efeito	\r\nNenhum duelista pode escolher este card como alvo de efeitos de monstro. \r\nUma vez por turno (Efeito Rápido): você pode escolher 1 monstro com a face para cima no campo; ele perde 500 de ATK/DEF. \r\nSeu oponente não pode ativar cards ou efeitos em resposta à ativação deste efeito. \r\nNo começo da Etapa de Dano, se este card atacar um monstro do oponente: você pode colocar esse monstro do oponente em uma zona para a qual este card apontar e tomar o controle dele, mas envie-o para o Cemitério durante a Fase Final do próximo turno.','\r',char(13)),'\n',char(10)),'Reduzir ATK/DEF','Tomar controle','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31834488,'Livro do Eclipse Lunar','Descarte 1 card e, depois, escolha 2 monstros com a face para cima no campo; coloque-os com a face para baixo em Posição de Defesa.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31849106,'Fundamento de Outra Dimensão','Neste turno, qualquer monstro enviado para o Cemitério, em vez disso, é banido.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31855260,'Grito Miutante',replace(replace('Durante a Fase Principal: Invoque por Invocação-Fusão 1 Monstro de Fusão "Miutante" do seu Deck Adicional, embaralhando as Matérias de Fusão listadas nele no Deck, dentre os seus cards no campo, no seu Cemitério e/ou seus cards banidos com a face para cima. \r\nVocê só pode ativar 1 "Grito Miutante" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31863912,'Nega-dado','Cada vez que seu oponente Invocar um ou mais monstros por Invocação-Especial: role um dado de 6 faces e volte para a mão todos os monstros Invocados cujo Nível atual seja igual ao resultado do dado.','Role um dado','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31887806,'Tobari, o Ninja Celeste',replace(replace('Este card não pode ser destruído em batalha ou por um efeito de card no turno em que foi Invocado por Invocação-Especial ou virado com a face para cima. \r\nVocê só pode usar cada um dos seguintes efeitos de "Tobari, o Ninja Celeste" uma vez por turno. \r\nVocê pode enviar este card da sua mão para o Cemitério; Invoque por Invocação-Especial 1 monstro "Ninja" da sua mão com a face para cima ou com a face para baixo em Posição de Defesa. \r\nDurante a Fase Principal ou de Batalha do seu oponente (Efeito Rápido): você pode Invocar por Invocação-Fusão 1 Monstro de Fusão "Ninja" do seu Deck Adicional, usando monstros da sua mão ou do campo como matéria.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31887905,'Espírito-Possuído - Aussa',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão ou do Deck) ao enviar para o Cemitério 1 "Aussa, a Encantadora da Terra" com a face para cima e 1 monstro de TERRA com a face para cima que você controla. \r\nSe este card Invocado por Invocação-Especial por seu efeito atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31887906,'Espírito-Possuído - Aussa',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão ou do Deck) ao enviar para o Cemitério 1 "Aussa, a Encantadora da Terra" com a face para cima e 1 monstro de TERRA com a face para cima que você controla. \r\nSe este card Invocado por Invocação-Especial por seu efeito atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31890399,'Espelho do Demônio','Você pode Invocar este card por Invocação-Ritual com "Ritual de Espelho-Besta".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31893528,'Mensagem do Espírito "I"','Este card só pode ser colocado no campo pelo efeito de "Tábua do Destino".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31897444,'Defensor do Labirinto',replace(replace('2 Monstros Normais	\r\nMonstros que não sejam de Efeito que você controla ganham 500 de ATK e, além disso, todos os Monstros de Efeito que seu oponente controla perdem 500 de ATK. \r\nSe este card em posse do seu dono for destruído por um card do seu oponente: você pode escolher 1 Monstro que não seja de Efeito no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê só pode usar este efeito de "Defensor do Labirinto" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31904181,'Os Seis Samurai - Nisashi',replace(replace('Enquanto você controlar um monstro "Seis Samurai" com a face para cima com um nome diferente, este card pode atacar duas vezes durante cada Fase de Batalha. \r\nSe este card seria destruído, em vez disso, você pode destruir outro monstro "Seis Samurai" com a face para cima que você controla.','\r',char(13)),'\n',char(10)),'Usar o efeito de substituição de destruição de "Os Seis Samurai - Nisashi"?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31919988,'Adivinho das Trevas',replace(replace('1 Regulador de TREVAS + 1 monstro do Tipo Inseto não-Regulador	\r\nEste card não pode ser destruído em batalha. \r\nQuando este card declarar um ataque, se o ATK do alvo do ataque for maior que o deste card: O ATK do alvo do ataque se torna igual ao ATK atual deste card com a face para cima. \r\nEssa mudança dura até o final da Fase de Batalha. \r\nQuando este card destruir um monstro do oponente em batalha e enviá-lo para o Cemitério: Envie os 3 cards do topo do Deck do seu oponente para o Cemitério.','\r',char(13)),'\n',char(10)),'Alterar ATK','Enviar do Deck para o Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31924889,'Mago Arcanita',replace(replace('1 Regulador + 1+ monstros Mago não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro: coloque 2 Marcadores de Magia nele. \r\nEste card ganha 1000 de ATK para cada Marcador de Magia nele. \r\nVocê pode remover 1 Marcador de Magia do seu campo e, depois, escolher 1 card que seu oponente controla; destrua o alvo.','\r',char(13)),'\n',char(10)),'Colocar Marcadores de Magia','Destruir 1 card','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31930787,'Senhormek Imperador Skiel',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial por seu próprio efeito. \r\nQuando um monstro com a face para cima que você controla for destruído por um efeito de card e enviado para o Cemitério (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão. \r\nOutros monstros que você controla não podem declarar um ataque. \r\nUma vez por turno: você pode escolher 1 Monstro Sincro que seu oponente controla; equipe o alvo a este card. \r\nEste card ganha ATK igual ao ATK combinado dos monstros equipados a ele por este efeito. \r\nVocê pode enviar para o Cemitério 1 monstro que você controla que estiver equipado a este card; este card pode atacar diretamente seu oponente neste turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Equipar um Monstro Sincro','Ataque direto','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31944175,'Borg Limítrofe',replace(replace('Se você não controlar nenhum monstro, você pode Invocar este card por Invocação-Especial (da sua mão) ao descartar 1 monstro Ciberso. \r\nTodos os monstros que seu oponente controla perdem 500 de ATK.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial da mão','Reduzir ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31969219,'Sombra Maldita',replace(replace('Escolha 1 card com a face para cima que seu oponente controla; aplique este efeito de acordo com o número de cards no Cemitério dele com o nome desse card com a face para cima.\r\n● 1: Destrua-o.\r\n● 2: Bana-o.\r\n● 3+: Bana-o, além de todos os cards com esse nome do campo e Cemitério do seu oponente (com a face para baixo).','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31971040,'Melodia Escolhida de Vaalmônica',replace(replace('Aplique 1 desses efeitos. \r\nVocê deve controlar um Card de Monstro "Vaalmônica" para ativar e resolver este efeito. \r\nSe você controlar um Monstro Link "Vaalmônica", você pode aplicar os dois efeitos em sequência.\r\n● Ganhe 500 PV e, além disso, pelo resto deste turno, seu oponente não pode escolher Cards de Monstro "Vaalmônica" que você controla como alvo de efeitos de card.\r\n● Sofra 500 de dano e, depois, até o final deste turno, você pode negar os efeitos de 1 Monstro de Efeito que seu oponente controla.	\r\nVocê só pode ativar 1 "Melodia Escolhida de Vaalmônica" por turno.','\r',char(13)),'\n',char(10)),'','Ganhe 500 PV','Receba 500 de dano','Aplicar ambos','Negar os efeitos de 1 monstro do seu oponente?','','','','','','','','','','','');
INSERT INTO texts VALUES(31975743,'Mago Símio',replace(replace('Não pode ser Invocado por Invocação-Especial. \r\nUma vez por turno, se este card estiver com a face para cima em Posição de Ataque: Você pode enviar 1 monstro da sua mão ao Cemitério para escolher 1 monstro com a face para cima em Posição de Defesa que seu oponente controla; tome o controle dele até a Fase Final. \r\nEle não pode mudar sua posição de batalha neste turno.','\r',char(13)),'\n',char(10)),'Tomar controle','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31980955,'Vida Tranquila',replace(replace('Ative este card no começo da sua Fase Principal 1, se você não controlar nenhum monstro. \r\nSe qualquer duelista Invocar um monstro por Invocação-Normal/Baixar, esse duelista não pode Invocar por Invocação-Especial nesse turno. \r\nSe qualquer duelista Invocar um monstro por Invocação-Especial, esse duelista não pode Invocar por Invocação-Normal/Baixar nesse turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31986288,'Rosa Regenerativa','Quando este card for destruído em batalha e enviado para o Cemitério, você pode Invocar por Invocação-Especial 2 "Fichas de Rosa Regenerativa" (Tipo Planta/TREVAS/Nível 3/ATK 1200/DEF 1200).','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31986289,'Ficha de Rosa Regenerativa','Invocado por Especial com o efeito "Rosa Regenerativa".','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31987203,'Anjo da Condenação da Colheita',replace(replace('Escala de Pêndulo = 8\r\n[ Efeito de Pêndulo ]\r\nDurante sua Fase Principal: você pode destruir este card e, se isso acontecer, adicione 1 "Chifre Negro Celestial" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Anjo da Condenação da Colheita" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe este card for Invocado por Invocação-Normal ou Pêndulo: você pode adicionar 1 "Corneta Celestial" do seu Deck à sua mão. \r\nSe este card for oferecido como Tributo: você pode colocar este card na sua Zona de Pêndulo. \r\nVocê só pode usar cada efeito de "Anjo da Condenação da Colheita" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31987274,'Peixe-Voador','São concedidos três desejos a quem avistar este monstro em voo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31991800,'Guaxinim Majespectro - Bunbuku',replace(replace('Escala de Pêndulo = 5\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nQuando este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 monstro "Majespectro" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Guaxinim Majespectro - Bunbuku" uma vez por turno. \r\nEnquanto este card estiver na sua Zona de Monstros, seu oponente não pode escolhê-lo como alvo de efeitos de card e, além disso, ele não pode ser destruído pelos efeitos de card do seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32003338,'Número 34: Terror-Byte',replace(replace('3 monstros de Nível 3	\r\nUma vez por turno: você pode desassociar 1 Matéria Xyz deste card para escolher 1 monstro de Nível 4 ou menos em Posição de Ataque que seu oponente controla; ganhe o controle dele até a Fase Final.','\r',char(13)),'\n',char(10)),'Tomar controle','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32003339,'Número 34: Terror-Byte',replace(replace('3 monstros de Nível 3	\r\nUma vez por turno: você pode desassociar 1 Matéria Xyz deste card para escolher 1 monstro de Nível 4 ou menos em Posição de Ataque que seu oponente controla; ganhe o controle dele até a Fase Final.','\r',char(13)),'\n',char(10)),'Tomar controle','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32012841,'Escudo do Milênio','Dizem que esse escudo famoso pertencia a um antigo Faraó egípcio. As lendas dizem que seu poder é capaz de bloquear qualquer ataque.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32012842,'Escudo do Milênio','Dizem que esse escudo famoso pertencia a um antigo Faraó egípcio. As lendas dizem que seu poder é capaz de bloquear qualquer ataque.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32013448,'Cavaleiro do Anoitecer do Crepúsculo',replace(replace('Um monstro "Soldado do Lustro Negro" Invocado por Invocação-Ritual usando este card ganha esses efeitos. \r\nVocê só pode usar este efeito de "Cavaleiro do Anoitecer do Crepúsculo" uma vez por turno.\r\n● Uma vez por turno: você pode escolher 1 monstro que seu oponente controla; bana-o.\r\n● Uma vez por turno: até a próxima Fase Final do seu oponente, você pode banir, com a face para baixo, 1 card aleatório da mão do seu oponente.	\r\nSe este card for bando do seu Cemitério: você pode adicionar 1 Monstro de Ritual do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Cavaleiro do Anoitecer do Crepúsculo" uma vez por turno.','\r',char(13)),'\n',char(10)),'Banir 1 monstro que seu oponente controla (Cavaleiro do Anoitecer do Crepúsculo)','Banir temporariamente 1 card aleatório da mão do seu oponente (Cavaleiro do Anoitecer do Crepúsculo)','O efeito de "Cavaleiro do Anoitecer do Crepúsculo" está sendo aplicado.','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32015116,'Destruição Cega',replace(replace('Uma vez por turno, durante sua Fase de Apoio: lance um dado de 6 faces. \r\nSe o resultado for de 1 a 5, destrua todos os monstros no campo cujo Nível seja igual ao resultado. \r\nSe o resultado for 6, destrua todos os monstros no campo de Nível 6 ou mais.','\r',char(13)),'\n',char(10)),'Role um dado','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32022366,'Machado Gravitacional - Grarl',replace(replace('O monstro equipado ganha 500 de ATK. \r\nMonstros que seu oponente controla não podem mudar suas posições de batalha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32036866,'F.A. Superaquecimento',replace(replace('Se apenas seu oponente controlar um monstro: Invoque por Invocação-Especial 1 monstro "F.A." da sua mão e, se isso acontecer, até o final deste turno, aumente em 3 o Nível dele. \r\nSe este card estiver no Cemitério e você não controlar nenhum card na sua Zona do Campo: você pode banir este card do Cemitério; ative 1 Magia de Campo "F.A." diretamente da sua mão ou do Cemitério. \r\nVocê só pode usar este efeito de "F.A. Superaquecimento" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32044231,'Magia de Aumento de Classe Força Mágica',replace(replace('Escolha 1 Monstro Xyz Mago de Classe 4 no seu Cemitério; Invoque-o por Invocação-Especial (mas negue seus efeitos) e, depois, Invoque por Invocação-Especial 1 Monstro Xyz Mago de Classe 5 do seu Deck Adicional, usando-o como matéria e, se isso acontecer, associe este card ao monstro Invocado (isso é considerado uma Invocação-Xyz). \r\nVocê só pode ativar 1 "Magia de Aumento de Classe Força Mágica" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32044675,'Agarra-Glitch do Ganho-Nulo',replace(replace('1 Regulador + 1+ não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro: você pode adicionar 1 monstro de Nível 8 ou mais com 0 de ATK do seu Deck à sua mão. \r\nVocê pode escolher 1 monstro com 0 de ATK no seu Cemitério; Invoque-o por Invocação-Especial, mas negue seus efeitos e, além disso, ele não pode ser usado como matéria para uma Invocação-Fusão, Sincro, Xyz ou Link. \r\nVocê só pode usar cada efeito de "Agarra-Glitch do Ganho-Nulo" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Invocação Especial','Invocado por Invocação Especial pelo efeito de {CARD}','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32056070,'I.A. e Você',replace(replace('Se um ou mais monstros Ciberso com 2300 de ATK original forem Invocados por Invocação-Especial: você pode ativar 1 desses efeitos, de acordo com o Atributo desse(s) monstro(s) no campo;\r\n● TERRA/ÁGUA: Até o final deste turno, diminua pela metade o ATK de 1 monstro com a face para cima no campo.\r\n● VENTO/LUZ: Até o final deste turno, negue os efeitos de 1 card com a face para cima no campo.\r\n● FOGO/TREVAS: Invoque por Invocação-Especial 1 "Ficha @Ignister" (Ciberso/TREVAS/Nível 1/ATK 0/DEF 0).	\r\nVocê só pode usar cada efeito de "I.A. e Você" uma vez por turno para cada Atributo.','\r',char(13)),'\n',char(10)),'','Escolha o Atributo para ativar o efeito','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32056071,'Ficha @Ignister','Invocado por Especial com o efeito "A Chegada Ciberso @Ignister" ou um card relacionado.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32061192,'Maliss ＜P＞ Arganaz',replace(replace('Monstros Link "Maliss" que apontam para este card não podem ser destruídos por efeitos de card. \r\nVocê só pode usar cada um dos seguintes efeitos de "Maliss ＜P＞ Arganaz" uma vez por turno. \r\nDurante sua Fase Principal: você pode ativar este efeito; bana 1 monstro "Maliss" do seu Deck e, além disso, pelo resto deste turno, monstros "Maliss" que você controla ganham 600 de ATK. \r\nSe este card for banido: você pode pagar 300 PV; Invoque-o por Invocação-Especial e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto Monstros Link.','\r',char(13)),'\n',char(10)),'Banir','','Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32061744,'Wattdefensor','Escolha 1 monstro "Watt" de Nível 4 ou menos no seu Cemitério; Invoque-o por Invocação-Especial, mas destrua-o durante a Fase Final deste turno.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32062913,'Canhão Mágico Mega Ton','Remova 10 Marcadores de Magia do seu campo; destrua todos os cards que seu oponente controla.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32065885,'Apelo Sincero',replace(replace('Quando você sofre dano de batalha de um ataque direto do oponente: até sua próxima Fase Final, assuma o controle do 1 monstro com a face para cima que seu oponente controla com a maior DEF. \r\n(Em caso de empate, você pode escolher.) \r\nSeus efeitos são negados e ele não pode declarar ataque.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32086564,'Rivalidade Tribal Xyz',replace(replace('Os Monstros Xyz com a face para cima no campo com 2 ou mais matérias não podem ser destruídos por efeitos de card. \r\nDepois do cálculo de dano, se um Monstro Xyz seu batalhou um monstro do oponente enquanto este card já estava com a face para cima na sua Zona de Magias & Armadilhas: destrua o monstro do oponente. \r\nEsse Monstro Xyz deve ter 2 ou mais matérias associadas a ele para ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32104431,'Memória da Espada da Destruição',replace(replace('Descarte 1 card "Espada da Destruição"; Invoque por Invocação-Especial 1 monstro "Blader Notável" do seu Deck. \r\nVocê pode banir este card do seu Cemitério; Invoque por Invocação-Fusão 1 "Blader Notável, o Soldado da Espada Destruidora de Dragões" do seu Deck Adicional, ao banir suas Matérias de Fusão do seu Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32120116,'Julgamento de Enma','Quando seu oponente Invocar um ou mais monstros por Invocação-Especial: destrua-o e, depois, você pode banir 5 monstros Zumbi do seu Cemitério e, se isso acontecer, Invoque por Invocação-Especial 1 monstro Zumbi de Nível 7 ou mais da sua mão ou do Deck.','Invocação Especial?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32126000,'Elfa Estudiosa',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode Baixar 1 Armadilha do seu Deck com um efeito que equipe a si mesma como um Card de Equipamento. \r\nSe este card for enviado do campo para o Cemitério: você pode comprar 1 card. \r\nVocê só pode usar cada efeito de "Elfa Estudiosa" uma vez por turno.','\r',char(13)),'\n',char(10)),'Efeito de Baixar','Comprar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32134638,'Dinonévoa Anquilo',replace(replace('Escala de Pêndulo = 6\r\n[ Efeito de Pêndulo ]\r\nUma vez, enquanto este card estiver na sua Zona de Pêndulo, você pode negar um efeito de card ativado que escolhe como alvo outro(s) card(s) "Dinonévoa" que você controla e, depois, destrua este card.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nBana qualquer monstro destruído em batalha com um monstro "Dinonévoa" que você controla.','\r',char(13)),'\n',char(10)),'Negar o efeito','Usar o efeito de "Dinonévoa Anquilo"?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32138660,'Melusina Reptiliana',replace(replace('1 Regulador Réptil + 1+ monstros não-Reguladores	\r\nSe este card foi Invocado por Invocação-Sincro usando apenas monstros Réptil como matéria, ele não pode ser destruído em batalha ou por efeitos de card. \r\nUma vez por Corrente, quando seu oponente ativar um efeito de monstro, exceto durante a Etapa de Dano (Efeito Rápido): você pode escolher 1 monstro com a face para cima que seu oponente controla; mude o ATK dele para 0. \r\nSe este card Invocado por Invocação-Sincro que você controla for enviado para o seu Cemitério por um card do oponente: você pode adicionar 1 monstro Réptil do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Invoque por Invocação Sincro usando apenas monstros Réptil como Matéria','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32146097,'D/D Pandora','Quando este card for destruído em batalha e enviado para o Cemitério ou, quando este card em sua posse for destruído por um efeito de card do oponente e enviado para o seu Cemitério, e você não controlar nenhum card: você pode comprar 2 cards.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32152870,'Declínio Espantagarra',replace(replace('Escolha 1 "Planeta Primitivo Reichphobia" que você controla ou no seu Cemitério; devolva-o para a mão e, depois, se você controlar "Visas Starfrost", você pode colocar 1 monstro com a face para cima que seu oponente controla, com a face para baixo em Posição de Defesa. \r\nSe 3 ou mais monstros em Posição de Defesa estiverem no campo: você pode banir este card do seu Cemitério; adicione 1 card "Espantagarra" do seu Cemitério à sua mão. \r\nVocê só pode usar este efeito de "Declínio Espantagarra" uma vez por turno.','\r',char(13)),'\n',char(10)),'Recuperar a Magia de Campo','Recuperar card(s) "Espantagarra"','Colocar um monstro do oponente com a face para baixo?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32164201,'ZW - Pégaso Sabre Gêmeo',replace(replace('Você só pode controlar 1 "ZW - Pégaso Sabre Gêmeo". \r\nSe os PV do seu oponente forem pelo menos 2000 a mais que os seus, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê pode escolher 1 monstro "Utopia" que você controla; equipe este card que você controla a ele como uma Magia de Equipamento que concede a ele 1000 de ATK. \r\nUma vez por turno, enquanto este card estiver equipado a um monstro, você pode negar um efeito de monstro ativado no campo do seu oponente.','\r',char(13)),'\n',char(10)),'','Aplicar o efeito de "ZW - Pégaso Sabre Gêmeo" para negar?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32175429,'Chamado Heroico',replace(replace('Invoque por Invocação-Especial 1 monstro Guerreiro da sua mão ou do Cemitério, mas se você Invocou por Invocação-Especial um monstro que não seja "Heroico(a)" por este efeito, negue seus efeitos e, além disso, ele não pode atacar. \r\nSe seus PV forem 500 ou menos: você pode banir este card do seu Cemitério e, depois, escolha 1 monstro com a face para cima que você controla; ele ganha 500 de ATK para cada card "Heroico(a)" que você controla atualmente e, para cada card "Heroico(a)" associado a Monstros Xyz que você controla atualmente. \r\nVocê só pode ativar 1 "Chamado Heroico" por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Aumentar ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32176662,'Gelito Instável','Se este card for enviado para o Cemitério: coloque em Posição de Defesa todos os monstros em Posição de Ataque que seu oponente controla.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32180819,'Psicocinese','Se você controlar um monstro do Tipo Psíquico: escolha 1 card no campo; destrua-o e, se isso acontecer, você sofre 1000 de dano.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32181268,'Amano-Iwato',replace(replace('Não pode ser Invocado por Invocação-Especial. \r\nMonstros não podem ativar seus efeitos, exceto monstros Espírito. \r\nUma vez por turno, durante a Fase Final, se este card foi Invocado por Invocação-Normal ou virado com a face para cima neste turno: devolva este card para a mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32202803,'Bujingi Lobo','Outros monstros do Tipo Besta, Besta-Guerreira e Besta Alada que você controla não podem ser destruídos em batalha.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32207100,'Um Grande Distúrbio','Ofereça como Tributo 1 monstro com a face para cima em Posição de Ataque de Nível 2 ou menos; devolva para a mão todos os monstros de Nível 7 ou mais Invocados por Invocação-Especial.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32216688,'R.B. O Bruto do Blues',replace(replace('2+ monstros Máquina	\r\nGanha os seguintes efeitos enquanto este card apontar para um monstro "R.B.".\r\n● Ganha ATK igual à soma do ATK original dos monstros "R.B." para os quais apontar.\r\n● Pode realizar um segundo ataque durante cada Fase de Batalha.\r\n● Não pode ser destruído em batalha ou por efeitos de card.	\r\nDurante sua Fase Principal: você pode adicionar 1 card "R.B." do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "R.B. O Bruto do Blues" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32224143,'Cheflinda Fantardil',replace(replace('2 monstros de Nível 2	\r\nEnquanto você controlar outro monstro "Fantardil", os monstros do seu oponente não podem escolher este card como alvo de ataques. \r\nUma vez por turno: você pode desassociar 1 matéria deste card e, depois, escolha 1 monstro no campo com ATK igual ou menor que o ATK combinado de todos os monstros "Fantardil" no campo; destrua-o e, se isso acontecer, essa Zona dos Cards de Monstro não pode ser usada enquanto você controlar um monstro "Fantardil".','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32231618,'Princesa da Premonição Gnomoeda','VIRE: Você pode Invocar por Invocação-Especial 1 monstro de Virar de Nível 3 ou mais da sua mão ou do Deck com a face para baixo em Posição de Defesa e, além disso, você não pode ativar efeitos de monstro pelo resto deste turno, exceto de monstros "Princesa da Premonição".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32232538,'D/D/D Sábio Rei Salomão',replace(replace('2 monstros "D/D" de Nível 4	\r\nVocê pode desassociar 1 matéria deste card; adicione 1 card "D/D" do seu Deck à sua mão. \r\nSe este card for banido: você pode escolher 1 Monstro de Efeito "D/D" que você controla; esse Monstro de Efeito ganha este efeito até o final deste turno.\r\n● Se este card destruir um monstro em batalha: cause dano ao seu oponente igual ao ATK original desse monstro.	\r\nVocê só pode usar cada efeito de "D/D/D Sábio Rei Salomão" uma vez por turno.','\r',char(13)),'\n',char(10)),'Efeito de busca','Conceder um efeito','Destruir cards "D/D/D Sábio Rei Salomão"','O efeito de "D/D/D Sábio Rei Salomão" está sendo aplicado.','','','','','','','','','','','','');
INSERT INTO texts VALUES(32233746,'Luz da Desolação','Quando um ou mais monstros seriam Invocados: ofereça como Tributo 1 monstro "Luminoso(a)"; negue a Invocação e, se isso acontecer, destrua esses monstros.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32236916,'Ponte Arco-Íris Bifrost',replace(replace('(Este card não é considerado como um card "Ponte Arco-Íris".)	\r\nBana 3 monstros de Nível 10 ou maior do seu Deck Adicional, incluindo um Monstro Sinchro de LUZ; adicione 1 Magia de Campo do seu Deck à sua mão. \r\nVocê pode ativar 1 "Ponte Arco-Íris Bifrost" por turno.','\r',char(13)),'\n',char(10)),'Ativar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32240937,'Demônio Obediente Derradeiro',replace(replace('Este card pode atacar apenas quando não existem outros cards no seu Campo, e você não tem cards na mão. \r\nOs efeitos de Monstros de Efeito que este card destrói são anulados.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32245230,'O Acordo do Destino',replace(replace('Sempre que um ou mais cards que você controla forem destruídos em batalha ou por um efeito de card, coloque 1 Marcador de Chave do Imperador neste card (máx. 1). \r\nSe seu oponente Invocar um ou mais monstros por Invocação-Especial do Deck Adicional (exceto durante a Etapa de Dano): você pode remover 1 Marcador de Chave do Imperador deste card; envie para o Cemitério 1 "A Porta do Destino" da sua mão, do Deck ou do campo com a face para cima, Invoque por Invocação-Especial 1 Monstro Xyz "Utopia" ou "Utópico" de LUZ do seu Deck Adicional e, se isso acontecer, associe este card a ele como matéria. \r\n(Isso é considerado uma Invocação-Xyz.) \r\nVocê só pode usar este efeito de "O Acordo do Destino" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar um Monstro Xyz "Utopi" por Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32247099,'Besta Divina Definitiva',replace(replace('Quando um monstro do oponente declarar um ataque: você pode descartar 1 Magia/Armadilha e, depois, escolha 1 monstro Besta Divina no seu Cemitério; Invoque-o por Invocação-Especial em Posição de Defesa e, depois, mude o alvo do ataque para ele. \r\nDurante a Fase Final, se você controlar um monstro Besta Divina: você pode destruir todos os cards com a face para cima que seu oponente controla que ativaram seus efeitos no campo neste turno. \r\nVocê só pode usar cada efeito de "Besta Divina Definitiva" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32268901,'Salamandra',replace(replace('Só pode ser equipado a um monstro de FOGO. \r\nEle ganha 700 de ATK.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32269855,'O Tigre Branco que Tudo Vê','Um orgulhoso governador da selva, temido por alguns e respeitado por outros.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32270212,'Laços que Unem',replace(replace('Se você controlar "Sarcófago Brilhante" e um monstro que o mencione: Invoque por Invocação-Especial da sua mão e/ou do Deck, até 2 monstros de Nível 4 ou menos com nomes diferentes que mencionem "Sarcófago Brilhante" e, além disso, pelo resto deste turno depois que este card resolver, você não pode Invocar por Invocação-Especial do Deck Adicional. \r\nVocê só pode ativar 1 "Laços que Unem" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32271987,'Emplumador','Quando este card for destruído em batalha e enviado ao Cemitério, você pode enviar 1 monstro Gêmeos do seu Deck ao Cemitério e comprar 1 card.','Enviar ao Cemitério e comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32274490,'Servo Caveira','Um esqueleto fantasma que não é muito forte, mas quando estiver em grande número, pode ser um problema.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32274491,'Servo Caveira','Um esqueleto fantasma que não é muito forte, mas quando estiver em grande número, pode ser um problema.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32274492,'Servo Caveira','Um esqueleto fantasma que não é muito forte, mas quando estiver em grande número, pode ser um problema.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32278723,'Jato d''Água Emergente',replace(replace('Invoque por Invocação-Especial 1 monstro Peixe, Serpente Marinha ou Aqua de Nível 4 ou menos da sua mão ou do Cemitério, mas você não pode Invocar por Invocação-Especial do Deck Adicional, exceto Monstros Xyz, enquanto você controlar esse monstro com a face para cima. \r\nSe seu oponente controlar um monstro em Posição de Ataque: você pode banir este card do seu Cemitério e, depois, escolha 1 monstro Peixe, Serpente Marinha ou Aqua que você controla; ele ganha 1000 de ATK até o final deste turno. \r\nVocê só pode usar cada efeito de "Jato d''Água Emergente" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Aumentar ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32281491,'ZS - Sábio Ouroboros',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode Invocar por Invocação-Especial 1 monstro "Número" que não seja de LUZ do seu Cemitério, mas negue seus efeitos e, se isso acontecer, equipe tanto este card quanto 1 monstro "Utopia" que você controla a ele, cada um como uma Magia de Equipamento que concede a ele 1700 de ATK e, além disso, você só pode declarar um ataque pelo resto deste turno. \r\nQuando o monstro equipado com este card pelo efeito deste card declarar um ataque contra um monstro do seu oponente: você pode dobrar o ATK do monstro atacante, mas destrua-o durante a Fase Final.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32289031,'Cavaleirostrela Constelar Delteros',replace(replace('3+ monstros de Nível 4	\r\nSeu oponente não pode escolher Monstros Xyz "Cavaleirost" ou "Constelar" de Classe 5 ou mais que você controla como alvo de efeitos de card. \r\nUma vez por turno: você pode desassociar 1 matéria deste card; adicione 1 monstro "Cavaleirost" ou "Constelar" do seu Deck à sua mão e, depois, imediatamente depois que este efeito resolver, você pode Invocar por Invocação-Normal 1 monstro de LUZ. \r\nSe este card for enviado para o Cemitério, exceto do campo: você pode Invocar por Invocação-Especial 1 monstro "Cavaleirost" ou "Constelar" da sua mão ou do banimento.','\r',char(13)),'\n',char(10)),'Efeito de busca','Invocação Especial','Invocação Normal?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32295838,'Digitron','Uma subespécie encontrada no espaço eletrônico. Há pouca informação sobre ela.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32296881,'Artemis Benfeitor','Sempre que um Card de Armadilha de Resposta for ativado, imediatamente depois que ele resolver, compre 1 card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32298781,'Triangulo do Poder',replace(replace('Aumente o ATK e DEF original de todos os Monstros Normais de Nível 1 no seu Campo com a face para cima em 2000 pontos. \r\nDestrúa todos os Monstros Normais de Nível 1 no seu Campo durante a End Phase.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32302078,'Sheridan, o Vampiro Dampiro',replace(replace('2+ monstros de Nível 6	\r\nSe você usar um ou mais monstros com um Nível, dos quais seu oponente seja dono, para a Invocação-Xyz deste card, considere-o(s) como de Nível 6. \r\nUma vez por turno: você pode desassociar 1 matéria deste card e, depois, escolha 1 card que seu oponente controla; envie-o para o Cemitério. \r\nUma vez por turno, se um ou mais Cards de Monstro forem enviados do campo para o Cemitério do seu oponente por um efeito de card, ou se um monstro for destruído em batalha e enviado para o Cemitério do seu oponente: você pode desassociar 1 matéria deste card; Invoque 1 desses monstros por Invocação-Especial no seu campo em Posição de Defesa.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32305461,'Fada Fortuna En',replace(replace('Quando você comprar este card: você pode revelá-lo; Invoque-o por Invocação-Especial da sua mão. \r\nSe este card for Invocado por Invocação-Especial da mão: você pode escolher 1 card Baixado que seu oponente controla; destrua-o. \r\nVocê só pode usar cada efeito de "Fada Fortuna En" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32314730,'Paladino Koa''ki Meiru',replace(replace('Durante cada uma das suas Fases Finais, destrua este card a não ser que você envie 1 "Núcleo de Ferro de Koa''ki Meiru" da sua mão para o Cemitério ou revele 1 monstro do Tipo Besta-Guerreira na sua mão. \r\nSe este card destruir um monstro do oponente em batalha, você pode adicionar 1 card "Koa''ki Meiru" do seu Cemitério à sua mão.','\r',char(13)),'\n',char(10)),'Escolha 1 "Núcleo de Ferro de Koa''ki Meiru" para enviar para o Cemitério','Escolha um monstro Besta-Guerreira para mostrar ao seu oponente','Destruir "Paladino Koa''ki Meiru"','Recuperar','','','','','','','','','','','','');
INSERT INTO texts VALUES(32335697,'Zumbis Assombrados',replace(replace('Bana 1 monstro Zumbi de qualquer Cemitério e Invoque por Invocação-Especial 2 "Ficha Assombrada" (Zumbi/TREVAS/ATK 0/DEF 0) com o mesmo Nível que o do monstro banido. \r\nSe este card estiver no seu Cemitério: você pode embaralhar 1 dos seus monstros Zumbi banidos no Deck e, se isso acontecer, Baixe este card, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar 1 efeito de "Zumbis Assombrados" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32335698,'Ficha Assombrada','Invocado por Especial com o efeito "Zumbis Assombrados".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32339440,'Bujin Yamato',replace(replace('Uma vez por turno, durante sua Fase Final: você pode adicionar 1 monstro "Bujin" do seu Deck à sua mão e, depois, enviar 1 card da sua mão para o Cemitério. \r\nVocê só pode controlar 1 "Bujin Yamato".','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32344688,'Quimera das Trevas','Um monstro que cospe fogo e vive nos mundos inferiores.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32349062,'D/D Cachorro',replace(replace('Escala de Pêndulo = 3\r\n[ Efeito de Pêndulo ]\r\nVocê pode escolher 1 Monstro de Fusão, Sincro ou Xyz que seu oponente controla; negue os efeitos dele até o final deste turno e, depois, destrua este card. \r\nVocê só pode usar este efeito de "D/D Cachorro" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nUma vez por turno, se seu oponente Invocar um ou mais Monstros de Fusão, Sincro ou Xyz por Invocação-Especial (exceto durante a Etapa de Dano): você pode escolher 1 desses monstros; neste turno, esse monstro com a face para cima não pode atacar e, além disso, seus efeitos são negados.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32353566,'Fazticeira Walpurgis',replace(replace('Durante sua Fase Principal: você pode adicionar 1 monstro "Fazticeira" do seu Deck à sua mão, então descarte 1 card. \r\nVocê só pode usar este efeito de "Fazticeira Walpurgis" uma vez por turno.\r\nDurante seu turno, se você descartaria um ou mais cards para ativar o efeito de um monstro "Fazticeira" que você controla, em vez disso você pode enviar 1 Magia/Armadilha "Fazticeira" do seu Deck para o Cemitério, exceto "Fazticeira Walpurgis".','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32354768,'Oráculo de Zefra',replace(replace('Quando este card for ativado: adicione 1 monstro "Zefra" do seu Deck à sua mão. \r\nQuando você Invocar por Invocação-Ritual usando um monstro "Zefra", ou Invocar por Invocação-Especial usando um monstro "Zefra" como matéria, você pode ativar esses efeitos dependendo do monstro Invocado, uma vez por turno por efeito:\r\n● Ritual: Embaralhe no Deck 1 monstro no campo.\r\n● Fusão: Invoque por Invocação-Especial 1 monstro da sua mão.\r\n● Sincro: Selecione 1 monstro do seu Deck e coloque-o no topo do seu Deck.\r\n● Xyz: Compre 1 card e, depois, descarte 1 card.	\r\nVocê só pode ativar 1 "Oráculo de Zefra" por turno.','\r',char(13)),'\n',char(10)),'Retornar ao Deck 1 monstro no campo','Invoque 1 monstro da mão por Invocação Especial','Coloque 1 monstro do Deck no topo do Deck','Compre 1 card e depois descarte 1 card','Escolha um monstro para colocar no topo do Deck','','','','','','','','','','','');
INSERT INTO texts VALUES(32355828,'Skelgon','"Cabelos de Cobras" + "Dragão de Fogo da Terra Negra"','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32360466,'Princípio do Céu e da Terra',replace(replace('Revele 3 monstros do Tipo Guerreiro do seu Deck, incluindo pelo menos 1 monstro "Soldado do Lustro Negro" ou monstro "Gaia, o Cavaleiro Impetuoso" e faça com que seu oponente eleja 1 aleatoriamente. \r\nSe ele eleger um monstro "Soldado do Lustro Negro" ou monstro "Gaia, o Cavaleiro Impetuoso", adicione-o à sua mão e envie o resto para o Cemitério. \r\nCaso contrário, envie todos para o Cemitério. \r\nVocê só pode ativar 1 "Princípio do Céu e da Terra" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32362575,'Mercador Mágico','VIRE: Escave cards do topo do seu Deck até escavar uma Magia/Armadilha, depois, adicione esse card à sua mão e, além disso, envie os cards restantes para o Cemitério.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32391566,'Ocultador Adicional','Quando seu oponente Invocar um ou mais monstros por Invocação-Especial, exceto durante a Etapa de Dano: você pode Invocar este card por Invocação-Especial da sua mão e, se isso acontecer, em vez disso, seu oponente sofre qualquer dano de efeito que você teria sofrido dos efeitos de card dele neste turno.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32391631,'Coliseu Selvagem',replace(replace('Se um monstro atacar, no final da Etapa de Dano: o controlador dele ganha 300 PV. \r\nTodos os monstros devem atacar, se possível. \r\nDurante cada Fase Final: destrua todos os monstros com a face para cima em Posição de Ataque que o duelista do turno controla e que não declararam um ataque.','\r',char(13)),'\n',char(10)),'Ganhar PV','Destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32393580,'Tubarão Cibernético','Se controlar um monstro de ÁGUA, você pode Invocar este card por Invocação-Normal sem oferecer Tributo.','Invocação Normal sem Tributo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32422602,'Guerreiros Antigos - Engenhoso Zhuge Kong',replace(replace('Se este card for adicionado do Deck à sua mão pelo efeito de um card "Guerreiros Antigos": você pode Invocá-lo por Invocação-Especial. \r\nQuando um Card de Magia/Armadilha for ativado (Efeito Rápido): você pode enviar 1 Magia/Armadilha Contínua "Guerreiros Antigos" com a face para cima que você controla para o Cemitério; negue a ativação. \r\nQuando um efeito de monstro for ativado enquanto você controlar "Guerreiros Antigos - Virtuoso Liu Xuan" (Efeito Rápido): você pode enviar 1 Magia/Armadilha Contínua "Guerreiros Antigos" com a face para cima que você controla para o Cemitério; negue a ativação. \r\nVocê só pode usar cada efeito de "Guerreiros Antigos - Engenhoso Zhuge Kong" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32437102,'Ataque Dragônico',replace(replace('Este card só pode ser usado para equipar monstros do Tipo Guerreiro. \r\nO monstro equipado é considerado como do Tipo Dragão e aumenta o ATK e a DEF do monstro equipado em 500 pontos.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32441317,'Se-Sincro','Escolha 1 Monstro Sincro no campo; devolva o alvo para o Deck Adicional e, depois, se todos os monstros que foram usados para a Invocação-Sincro desse monstro estiverem no seu Cemitério, você pode Invocar todos eles por Invocação-Especial.','Invocar a Matéria por Invocação Especial?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32442017,'Saqueadores DoomZ',replace(replace('Durante sua Fase Principal: você pode destruir 1 outro card "DoomZ" na sua mão ou no campo com a face para cima e, depois, adicione à sua mão ou Invoque por Invocação-Especial, 1 monstro "DoomZ" do seu Deck e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto Monstros Xyz. \r\nSe este card for destruído por um efeito de card: você pode escolher 1 monstro com a face para cima no campo; destrua-o. \r\nVocê só pode usar 1 efeito de "Saqueadores DoomZ" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Destruir e buscar','Destruir 1 monstro','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32446630,'Número C43: Alto Manipulador do Caos',replace(replace('4 monstros de TREVAS de Nível 3	\r\nTodas as Fichas que você controla podem realizar um segundo ataque durante cada Fase de Batalha. \r\nSe este card tiver "Número 43: Manipulador de Almas" como uma Matéria Xyz, ele ganha este efeito.\r\n● Uma vez por turno: você pode desassociar 1 Matéria Xyz deste card; Invoque por Invocação-Especial 1 "Ficha de Manipulador" (Tipo Demônio/TREVAS/Nível 1/ATK ?/DEF ?). \r\n(Quando Invocado, seu ATK e DEF se tornam igual à metade dos PV atuais do oponente.)','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32446631,'Ficha de Manipulador','Invocado por Especial com o efeito "Número C43: Alto Manipulador do Caos". Quando Invocada, o ATK e DEF desta Ficha ficam iguais a metade dos Pontos de Vida atuais do oponente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32448765,'Trapestrela Anjo Azevinho',replace(replace('2 monstros "Trapestrela"	\r\nSempre que um ou mais monstros "Trapestrela" forem Invocados por Invocação-Normal ou Especial em uma ou mais zonas para as quais este card apontar, cause 200 de dano ao seu oponente. \r\nMonstros "Trapestrela" para os quais este card apontar não podem ser destruídos em batalha ou por efeitos de card. \r\nSe seu oponente sofrer dano pelo efeito de um monstro "Trapestrela": até o final deste turno, este card ganha ATK igual ao dano que seu oponente sofreu.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32448766,'Trapestrela Anjo Azevinho',replace(replace('2 monstros "Trapestrela"	\r\nSempre que um ou mais monstros "Trapestrela" forem Invocados por Invocação-Normal ou Especial em uma ou mais zonas para as quais este card apontar, cause 200 de dano ao seu oponente. \r\nMonstros "Trapestrela" para os quais este card apontar não podem ser destruídos em batalha ou por efeitos de card. \r\nSe seu oponente sofrer dano pelo efeito de um monstro "Trapestrela": até o final deste turno, este card ganha ATK igual ao dano que seu oponente sofreu.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32452818,'Castor Guerreiro','O que falta a esta criatura em tamanho, ela compensa em defesa quando combate na pradaria.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32453837,'Número 2: O Mosquito Ninja das Sombras',replace(replace('2+ monstros de Nível 2	\r\nNão pode ser destruído em batalha e, além disso, você não sofre dano das batalhas envolvendo este card. \r\nTodos os monstros que seu oponente controla devem atacar, se possível. \r\nQuando um ataque for declarado: você pode ativar 1 desses efeitos;\r\n● Desassocie 1 matéria deste card e, se isso acontecer, coloque 1 Marcador de Alucinação em 1 monstro com a face para cima que seu oponente controla. \r\n(Os efeitos, se houver, de monstros com Marcadores de Alucinação são negados.)\r\n● Cause dano ao seu oponente igual ao ATK de 1 monstro com um Marcador de Alucinação.','\r',char(13)),'\n',char(10)),'Colocar um marcador','Causar dano','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32465539,'Inseto Digital Casulocondensador',replace(replace('Não pode ser usado como uma Matéria Xyz para uma Invocação-Xyz, exceto para a Invocação-Xyz de um monstro do Tipo Inseto. \r\nUma vez por turno, se este card estiver em Posição de Ataque: você pode escolher 1 monstro do Tipo Inseto de Nível 3 no seu Cemitério; coloque este card em Posição de Defesa e, se isso acontecer, Invoque esse monstro por Invocação-Especial em Posição de Defesa. \r\nUm Monstro Xyz que foi Invocado usando este card no campo como Matéria Xyz ganha este efeito.\r\n● Se este card atacar um monstro em Posição de Defesa, os cards e efeitos do seu oponente não podem ser ativados até o final da Etapa de Dano.','\r',char(13)),'\n',char(10)),'Invocação Especial','O efeito de "Inseto Digital Casulocondensador" está sendo aplicado.','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32467459,'El Sombraneco Meshachrer',replace(replace('1 monstro "Sombraneco" + 1 monstro de TREVAS + 1 monstro de TERRA	\r\nDeve ser Invocado por Invocação-Fusão. \r\nNão é afetado pelos efeitos ativados de Magias/Armadilhas do seu oponente e os efeitos ativados de monstros do seu oponente cujos Níveis/Classes originais sejam menores que o Nível deste card. \r\nUma vez por turno: você pode pagar 800 PV; adicione 1 card "Sombraneco" ou 1 Magia/Armadilha "Vácuo" do seu Deck à sua mão. \r\nSe este card for enviado para o Cemitério: você pode Invocar por Invocação-Especial 1 monstro "Sombraneco" do seu Cemitério.','\r',char(13)),'\n',char(10)),'','Adicionar à mão','Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32472237,'Dragão Metalfoguette',replace(replace('Quando um efeito de um Monstro Link que escolha como alvo este card com a face para cima no campo for ativado (Efeito Rápido): você pode destruir este card e, depois, destrua todos os cards do seu oponente na coluna em que este card estava. \r\nDurante a Fase Final, se este card estiver no Cemitério porque foi destruído, no campo, em batalha ou por um efeito de card e enviado para lá neste turno: você pode Invocar por Invocação-Especial 1 monstro "Foguette" do seu Deck, exceto "Dragão Metalfoguette". \r\nVocê só pode usar cada efeito de "Dragão Metalfoguette" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32476434,'Lança Shogi','Uma vez por turno: você pode escolher 1 outro monstro do Tipo Besta-Guerreira de Nível 3 que você controla; os Níveis desse monstro e deste card se tornam igual aos Níveis combinados desses monstros.','Alterar Nível','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32476603,'Dragão Pratafoguette',replace(replace('Quando um efeito de Monstro Link for ativado que escolha como alvo este card com a face para cima no campo (Efeito Rápido): você pode destruir este card e, depois, olhe o Deck Adicional do seu oponente e bana 1 card dali. \r\nDurante a Fase Final, se este card estiver no Cemitério porque foi destruído no campo, em batalha ou por um efeito de card e enviado para lá neste turno: você pode Invocar por Invocação-Especial 1 monstro "Foguette" do seu Deck, exceto "Dragão Pratafoguette". \r\nVocê só pode usar cada efeito de "Dragão Pratafoguette" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32480825,'T.G. Golpeador Poderoso',replace(replace('1 Regulador + 1 monstro não-Regulador	\r\nUma vez por turno, durante a Fase Principal do seu oponente, você pode (Efeito Rápido): imediatamente depois que este efeito resolver, Invocar por Invocação-Sincro usando este card que você controla. \r\nVocê só pode usar cada um dos seguintes efeitos de "T.G. Golpeador Poderoso" uma vez por turno. \r\nSe este card for Invocado por Invocação-Sincro: você pode adicionar 1 Magia/Armadilha "T.G." do seu Deck à sua mão. \r\nSe este card for enviado da sua Zona de Monstros para o Cemitério: você pode enviar 1 card "T.G." do seu Deck para o Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32484853,'Demônio da Singularidade',replace(replace('Quando seu oponente Invocar um ou mais monstros por Invocação-Especial (exceto durante a Etapa de Dano): você pode descartar este card e 1 Magia; destrua esse(s) monstro(s). \r\nVocê só pode usar este efeito de "Demônio da Singularidade" uma vez por turno.','\r',char(13)),'\n',char(10)),'Destrua o(s) monstro(s) Invocado(s) por Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32485271,'Espectro da Rosa de Dunn','"Diabrete Selvagem" + "Serpentyashi"','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32485518,'Governante Imortal',replace(replace('Não pode ser Invocado por Invocação-Especial. \r\nVocê pode oferecer este card como Tributo e, depois, escolher 1 "Mundo Zumbi" no seu Cemitério; adicione o alvo à sua mão.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32491822,'Hamon, o Senhor do Trovão Impactante',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao enviar 3 Magias Contínuas com a face para cima que você controla para o Cemitério. \r\nSe este card destruir um monstro do oponente em batalha e enviá-lo para o Cemitério: cause 1000 de dano ao seu oponente. \r\nEnquanto este card estiver com a face para cima em Posição de Defesa, monstros que seu oponente controla não podem escolher monstros como alvo de ataques, exceto este.','\r',char(13)),'\n',char(10)),'Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32491823,'Hamon, o Senhor do Trovão Impactante',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao enviar 3 Magias Contínuas com a face para cima que você controla para o Cemitério. \r\nSe este card destruir um monstro do oponente em batalha e enviá-lo para o Cemitério: cause 1000 de dano ao seu oponente. \r\nEnquanto este card estiver com a face para cima em Posição de Defesa, monstros que seu oponente controla não podem escolher monstros como alvo de ataques, exceto este.','\r',char(13)),'\n',char(10)),'Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32519092,'Monge dos Tenyi','1 monstro "Tenyi" que não seja Link','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32530043,'Valente de Granito',replace(replace('2 monstros de Nível 4	\r\nVocê pode desassociar 1 matéria deste card e, depois, ative 1 desses efeitos;\r\n● Adicione 1 monstro Rocha do seu Deck à sua mão.\r\n● Invoque por Invocação-Especial 1 monstro Rocha da sua mão com a face para baixo em Posição de Defesa.	\r\nVocê só pode usar este efeito de "Valente de Granito" uma vez por turno.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32539892,'Minar','Quando este card for descartado diretamente da sua mão para o Cemitério pelo efeito de um card controlado por seu oponente, cause 1000 de dano ao seu oponente.','Causar dano aos PV','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32541773,'O Segredo do Retrato','Um retrato amaldiçoado pelo artista, dizem que trará azar a quem o possuir.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32542011,'Maré Alta na Ilha de Fogo',replace(replace('Se você controlar um monstro de ÁGUA ou de FOGO de Nível 7 ou mais: aplique os efeitos apropriados, em sequência, dependendo dos Atributos dos monstros que você controlar nesse momento.\r\n● ÁGUA: Invoque por Invocação-Especial tantos monstros de ÁGUA quanto possíveis que foram enviados para o seu Cemitério por terem sido usados para ativar efeitos de monstro neste turno e, depois, destrua 1 monstro que você controla.\r\n● FOGO: Destrua 1 monstro no campo e, depois, se você tiver algum card na sua mão, descarte 1 card para o Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32543380,'Fogo Vulcânico da Perdição',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro deve ser Invocado por Invocação-Especial (da sua mão) ao enviar 1 "Tri-Acelerador de Explosão" que você controla para o Cemitério. \r\nDurante a Fase de Batalha do seu oponente, todos os monstros em Posição de Ataque que seu oponente controla que podem atacar devem atacar este card. \r\nSe este card destruir um monstro em batalha e enviá-lo para o Cemitério: destrua tantos monstros que seu oponente controla quanto possível e, se isso acontecer, cause 500 de dano ao seu oponente para cada monstro destruído por este efeito.','\r',char(13)),'\n',char(10)),'Destrua todos os monstros que seu oponente controla','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32548318,'Caudraco Rahu',replace(replace('Invoque por Invocação-Fusão 1 monstro "Caudraco" do seu Deck Adicional, usando monstros da sua mão, do Deck ou do campo e, além disso, pelo resto deste turno depois que este card resolver, você não pode Invocar por Invocação-Especial do Deck Adicional, exceto Monstros de Fusão. \r\nVocê só pode ativar 1 "Caudraco Rahu" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32548609,'Wattoupeira',replace(replace('Este card pode realizar um segundo ataque durante cada Fase de Batalha. \r\nNo começo da Etapa de Dano, se este card atacar um monstro com a face para baixo em Posição de Defesa: você pode destruir esse monstro com a face para baixo.','\r',char(13)),'\n',char(10)),'Destruir o monstro atacado em Posição de Defesa com a face para baixo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32549749,'Regeneração das Armas',replace(replace('Ative 1 dos seguintes efeitos.\r\n● Escolha 1 monstro com a face para cima que você controla; ele ganha 800 de ATK até o final deste turno.\r\n● Escolha 1 Magia de Equipamento em qualquer Cemitério; Baixe-a no seu campo, ou equipe-a a 1 monstro apropriado que você controla.	\r\nVocê só pode ativar 1 "Regeneração das Armas" por turno.','\r',char(13)),'\n',char(10)),'Aumentar ATK','Recuperar Card(s) de Magia de Equipamento','Baixar no campo','Equipar a um monstro','','','','','','','','','','','','');
INSERT INTO texts VALUES(32557233,'Tranquilidade Rikka',replace(replace('Quando você ativar este card, você também pode oferecer 1 monstro Planta como Tributo; Invoque por Invocação-Especial 1 monstro "Rikka" do seu Cemitério em Posição de Defesa e, depois, se você ofereceu um monstro como Tributo quando ativou este card, Invoque por Invocação-Especial 1 monstro Planta do seu Cemitério em Posição de Defesa. \r\nVocê só pode ativar 1 "Tranquilidade Rikka" por turno.','\r',char(13)),'\n',char(10)),'Ativar sem oferecer um monstro como Tributo','Oferecer um monstro como Tributo para ativar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32559361,'Número C9: Esfera do Caos de Dyson',replace(replace('3 monstros de Nível 10	\r\nNo começo da Etapa de Dano, se este card batalhar um monstro do oponente: você pode associar esse monstro a este card como uma Matéria Xyz com a face para cima. \r\nUma vez por turno: você pode causar 300 de dano ao seu oponente para cada Matéria Xyz associada a este card. \r\nSe este card tiver "Número 9: Esfera de Dyson" como uma Matéria Xyz, ele ganha este efeito.\r\n● Uma vez por turno: você pode desassociar qualquer número de Matérias Xyz deste card; para cada uma, cause 800 de dano ao seu oponente.','\r',char(13)),'\n',char(10)),'Associar como matéria','Cause dano ao seu oponente igual ao número de Matérias Xyz × 300','Desassociar Matérias Xyz; cause dano ao seu oponente igual à quantidade desassociar × 800','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32566831,'Cards da Pedra Vermelha',replace(replace('Envie 1 monstro "Olhos Vermelhos" de Nível 7 da sua mão para o Cemitério; compre 2 cards e, depois, você pode enviar 1 monstro "Olhos Vermelhos" de Nível 7 do seu Deck para o Cemitério. \r\nVocê só pode ativar 1 "Cards da Pedra Vermelha" por turno.','\r',char(13)),'\n',char(10)),'Enviar 1 monstro "Olhos Vermelhos" de Nível 7 do Deck para o Cemitério?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32569498,'Korogashi','Este monstro rola um enorme pedaço de estrume para esmagar o oponente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32588805,'O Desesperador Urano',replace(replace('Quando este card for Invocado por Invocação-Tributo enquanto você não controlar Magias/Armadilhas: você pode ativar este efeito; seu oponente declara Magia Contínua ou Armadilha Contínua e, depois, você Baixa 1 card desse tipo diretamente do seu Deck. \r\nEste card ganha 300 de ATK para cada Magia/Armadilha com a face para cima que você controla. \r\nCards com a face para cima na sua Zona de Magias & Armadilhas não podem ser destruídos por efeitos de card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32600024,'Dragãozela da Câmara',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 Magia/Armadilha "Dragãozela" do seu Deck à sua mão. \r\nNo começo da Fase de Batalha: você pode devolver este card para a mão e, se isso acontecer, Invoque por Invocação-Especial 1 monstro "Dragãozela" de Nível 7 ou mais da sua mão ou do Cemitério. \r\nVocê só pode usar cada efeito de "Dragãozela da Câmara" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32603633,'De Costas na Parede',replace(replace('Pague PV até que você tenha apenas 100 sobrando; Invoque por Invocação-Especial tantos monstros "Seis Samurai" com nomes diferentes do seu Cemitério quanto possível. \r\nVocê não pode Invocar um monstro por Invocação-Especial com o mesmo nome que um monstro que você já controla.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32615065,'Shura, a Estrela Combatente',replace(replace('"Iadaten, a Estrela Conquistadora" + 1 monstro Guerreiro de Nível 5 ou mais	\r\nUma vez por turno, durante a Fase de Batalha (Efeito Rápido): você pode transformar em 0 o ATK de todos os monstros com a face para cima que seu oponente controla atualmente. \r\nUma vez por batalha, se um monstro batalhar outro monstro, durante o cálculo de dano (Efeito Rápido): você pode fazer com que cada monstro que estiver batalhando ganhe ATK igual ao seu próprio Nível x 200, apenas durante esse cálculo de dano. \r\nSe este card Invocado por Invocação-Fusão que você controla for destruído por um card do oponente e enviado para o seu Cemitério: você pode Invocar por Invocação-Especial 1 "Iadaten, a Estrela Conquistadora" do seu Deck Adicional. \r\n(Esta é considerada uma Invocação-Fusão.)','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32617464,'Mago Tri-Portal',replace(replace('2+ monstros, exceto Fichas	\r\nGanha esses efeitos de acordo com o número de monstros co-linkados a este card.\r\n● 1+: Se um monstro co-linkado a este card batalhar um monstro do seu oponente, qualquer dano de batalha que ele causar ao seu oponente é dobrado.\r\n● 2+: Uma vez por turno: você pode escolher 1 card no campo; bana-o.\r\n● 3: Uma vez por turno, quando um card ou efeito for ativado (Efeito Rápido): você pode negar a ativação e, se isso acontecer, bana esse card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32619583,'Sillva, Senhor da Guerra do Mundo Negro','Se este card for descartado para o Cemitério por um efeito de card: Invoque este card por Invocação-Especial e, depois, se ele foi descartado da sua mão para o seu Cemitério por um efeito de card do oponente, seu oponente coloca exatamente 2 cards da mão dele no fundo do Deck dele, em qualquer ordem.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32623004,'Nãopinguim',replace(replace('Durante o turno de qualquer duelista, quando um efeito de um monstro "Pinguim" for ativado: Invoque este card por Invocação-Especial do seu Cemitério. \r\nVocê só pode usar este efeito de "Nãopinguim" uma vez por turno. \r\nSe um card seria devolvido do campo para a mão por um efeito de um card "Pinguim", em vez disso, bana-o.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32626733,'Serpente Espiral','Quando grandes redemoinhos destroem as cidades, a fome desta serpente marinha entra em ação. Ninguém jamais escapou de sua temida Onda Espiral para descrever com exatidão o terror vivido.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32646477,'Guerreiro do Golpe Negro',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\n(Este card não deve ser considerado como um card "Guerreiro(a)".)	\r\nDurante sua Fase Principal 1: você pode oferecer 1 monstro como Tributo; cause dano ao seu oponente igual ao Nível que o monstro oferecido como Tributo tinha no campo x 200 (Nível original, se ele estava com a face para baixo). \r\nVocê só pode usar este efeito de "Guerreiro do Golpe Negro" uma vez por turno.','\r',char(13)),'\n',char(10)),'Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32663969,'Efeito Dominó','Quando um monstro que seu oponente controla for destruído em batalha e enviado ao Cemitério, você pode enviar 1 monstro que você controla ao Cemitério para destruir 1 monstro que seu oponente controla.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32665564,'Pacto Obscuro com o Rei Zero',replace(replace('(Este card deve ser sempre considerado como um card "D/D".)	\r\nVocê pode escolher 1 card "D/D" que você controla, exceto "Pacto Obscuro com o Rei Zero"; destrua-o e, se isso acontecer, Invoque por Invocação-Especial 1 monstro "D/D" do seu Deck e, além disso, você não pode Invocar por Invocação-Especial pelo resto deste turno, exceto monstros "D/D". \r\nVocê só pode usar este efeito de "Pacto Obscuro com o Rei Zero" uma vez por turno. \r\nUma vez por turno, durante sua Fase de Apoio: sofra 1000 de dano.','\r',char(13)),'\n',char(10)),'Invocação Especial','Efeito de dano','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32671443,'Doutor D',replace(replace('Bana 1 monstro "HERÓI do Destino" do seu Cemitério; adicione à sua mão ou Invoque por Invocação-Especial 1 monstro "HERÓI do Destino" do seu Cemitério. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 2 monstros "HERÓI do Destino" que você controla; selecione 1 desses monstros, o ATK dele se torna o ATK do outro monstro até o final deste turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão ou Invocar por Invocação Especial','Altere o ATK','Escolha o monstro cujo ATK será alterado','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32679370,'Herói Criança','Quando este card for Invocado por Invocação-Especial: Você pode Invocar por Invocação-Especial qualquer número de "Herói Criança" do seu Deck.','Invocação Especial','Invocar "Herói Criança" por Invocação Especial novamente?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32687071,'Amórfago da Preguiça',replace(replace('Escala de Pêndulo = 3\r\n[ Efeito de Pêndulo ]\r\nEnquanto você controlar um monstro "Amórfago", nenhum duelista pode adicionar cards dos seus Decks às suas mãos, exceto ao comprá-los. \r\nUma vez por turno, durante sua Fase de Apoio, ofereça 1 monstro como Tributo ou destrua este card.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nNenhum duelista pode Invocar monstros do Deck Adicional por Invocação-Especial, exceto monstros "Amórfago".','\r',char(13)),'\n',char(10)),'Oferecer como Tributo 1 monstro que você controla?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32692693,'Radiação Ursártica',replace(replace('Ative este card ao colocar 7 marcadores nele. \r\nSempre que um ou mais monstros "Ursártico(a)" forem Invocados por Invocação-Especial da mão ou do Deck Adicional: você pode remover 1 marcador deste card; compre 1 card. \r\nUma vez por turno, durante a Fase Final: você pode escolher 1 card "Ursártico(a)" no seu Cemitério, exceto "Radiação Ursártica"; embaralhe-o no Deck. \r\nVocê só pode controlar 1 "Radiação Ursártica".','\r',char(13)),'\n',char(10)),'Compre 1 card(s)','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32696942,'Cavaleiro Barrigão','Se este card for desassociado de um Monstro Xyz e enviado para o Cemitério para ativar um efeito desse monstro: você pode Invocar por Invocação-Especial 1 monstro de Nível 3 ou menos da sua mão.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32703716,'Peixes Carnívoros','Se você tiver 3 ou mais monstros do Tipo Peixe, Serpente Marinha ou Aqua banidos: Escolha 1 card no campo; bana-o.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32710364,'Fera Cristalina Carbúnculo Rubi',replace(replace('Quando este card for Invocado por Invocação-Especial: você pode Invocar por Invocação-Especial tantos Cards de Monstro "Fera Cristalina" quanto possível das suas Zonas de Magias & Armadilhas. \r\nSe este card com a face para cima for destruído em uma Zona de Monstros, em vez de enviá-lo para o Cemitério, você pode colocá-lo com a face para cima na sua Zona de Magias & Armadilhas como uma Magia Contínua.','\r',char(13)),'\n',char(10)),'Colocar na Zona de Magias & Armadilhas quando for destruído','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32723153,'Explosão Mágica',replace(replace('Você só pode ativar este card quando não tiver nenhum card na sua mão. \r\nPara cada Card de Magia no seu Cemitério, inflija 200 pontos de dano aos Life points do seu adversário.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32731036,'O Bistial Lubellion',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão ou do Cemitério) ao oferecer como Tributo 1 monstro Dragão de TREVAS de Nível 6 ou mais. \r\nVocê só pode Invocar "O Bistial Lubellion" por Invocação-Especial uma vez por turno desta forma. \r\nVocê pode enviar este card da sua mão para o Cemitério; adicione 1 monstro "Bistial" do seu Deck à sua mão, exceto "O Bistial Lubellion". \r\nDurante sua Fase Principal: você pode colocar 1 Magia/Armadilha Contínua "Marcado" do seu Deck no seu campo com a face para cima. \r\nVocê só pode usar cada efeito de "O Bistial Lubellion" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32744558,'Supervisor Genex-R','Quando este card for Invocado por Invocação-Normal ou Especial, você pode Invocar por Invocação-Especial 1 monstro "Genex" de Nível 3 ou menos da sua mão.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32750341,'Boxeador Obstinado de Aparador',replace(replace('Se você controlar um monstro "Boxeador Obstinado", você pode Invocar este card por Invocação-Especial (da sua mão). \r\nSe isso acontecer, você não pode conduzir sua Fase de Batalha pelo restante deste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32750510,'Mestre do Gelo',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) ao oferecer como Tributo 2 monstros de ÁGUA. \r\nUma vez por turno: Você pode escolher 1 monstro com a face para cima no campo; coloque um Marcador de Gelo no alvo. \r\nVocê pode oferecer este card como Tributo; destrua todos os monstros com um ou mais Marcadores de Gelo.','\r',char(13)),'\n',char(10)),'Colocar "Marcador de Gelo"','Destrua todos os monstros com "Marcador de Gelo"','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32751480,'Areia Mística','"Soldado de Pedra Gigante" + "Elfo Ancião"','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32752319,'Lutador UFOroide',replace(replace('"UFOroide" + 1 monstro Guerreiro	\r\nA Invocação-Fusão deste card só pode ser feita com as Matérias de Fusão acima. \r\nO ATK/DEF originais deste card se tornam o ATK original combinado das 2 matériais usadas para sua Invocação-Fusão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32754886,'Ilusão Negra','Até o final deste turno, todos os monstros de TREVAS do Tipo Mago com 2000 ou mais de ATK que você controla atualmente não podem ser destruídos em batalha, seus efeitos são negados e, além disso, eles não são afetados pelos efeitos de card do seu oponente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32756828,'Besta Marcado',replace(replace('Uma vez por turno, durante a Fase Principal, se você controlar um monstro "Bistial": você pode oferecer como Tributo 1 monstro Dragão e, depois, escolha 1 card que seu oponente controla; destrua-o. \r\nDurante a Fase Final: você pode escolher 1 Magia/Armadilha Contínua "Marcado" no seu Cemitério; coloque-a com a face para cima no seu campo. \r\nVocê só pode usar este efeito de "Besta Marcado" uma vez por turno.','\r',char(13)),'\n',char(10)),'Destrua um card do seu oponente','Recupere 1 Magia/Armadilha Contínua do seu Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32759190,'Hecamãos Yadel',replace(replace('Se este card batalhar um monstro, nenhum dos dois pode ser destruído nessa batalha. \r\nVocê só pode usar cada um dos seguintes efeitos de "Hecamãos Yadel" uma vez por turno. \r\nVocê pode revelar este card na sua mão; embaralhe este card no Deck e, depois, adicione 1 Magia/Armadilha "Hecamãos" do seu Deck à sua mão. \r\nSe este card for enviado para o Cemitério: você pode escolher 1 Magia/Armadilha "Hecamãos" no seu Cemitério; Baixe-a.','\r',char(13)),'\n',char(10)),'Efeito de busca','Baixar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32761286,'Lombriga de Restolhos',replace(replace('Este card pode atacar diretamente. \r\nSe este card atacar, no final da Fase de Batalha: destrua este card. \r\nSe este card for destruído pelo efeito de um card "Restolhos" e enviado para o seu Cemitério: você pode escolher 1 monstro "Restolhos" no seu Cemitério, exceto "Lombriga de Restolhos"; adicione o alvo à sua mão.','\r',char(13)),'\n',char(10)),'Destruir este card','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32762201,'Estátua do Mecanismo Antigo',replace(replace('Se seu oponente controlar mais monstros que você, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Estátua do Mecanismo Antigo" por Invocação-Especial uma vez por turno desta forma. \r\nVocê pode oferecer este card como Tributo; Invoque por Invocação-Especial da sua mão ou do Deck, 1 "Golem do Mecanismo Antigo" ou 1 monstro que o mencione, exceto "Estátua do Mecanismo Antigo", ignorando suas condições de Invocação. \r\nVocê só pode usar este efeito de "Estátua do Mecanismo Antigo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32764863,'Respingo Renovador Xyz',replace(replace('Escolha 1 Monstro Xyz de Classe 4 ou menos no seu Cemitério; Invoque-o por Invocação-Especial. \r\nSeu Atributo se torna ÁGUA. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 Monstro Xyz de ÁGUA que você controla; Invoque por Invocação-Especial do seu Deck Adicional, 1 Monstro Xyz de ÁGUA que seja 1 Classe superior à desse monstro que você controla, ao usá-lo como matéria. \r\n(Isso é considerado uma Invocação-Xyz. Transfira as matérias dele para o monstro Invocado.) \r\nVocê só pode usar 1 efeito de "Respingo Renovador Xyz" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32768230,'Cibereterno',replace(replace('Escolha 1 Monstro de Fusão Máquina "Ciber" no seu Cemitério; devolva-o para o Deck Adicional ou Invoque-o por Invocação-Especial, ignorando suas condições de Invocação. \r\nSe um ou mais Monstros de Fusão Máquina "Ciber" que você controla seriam destruídos em batalha ou por um efeito de card, em vez disso, você pode banir este card do seu Cemitério. \r\nVocê só pode usar cada efeito de "Cibereterno" uma vez por turno.','\r',char(13)),'\n',char(10)),'Retornar ao Deck Adicional','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32775808,'Manifestação do Arquidemônio',replace(replace('"Caveira Invocada" + 1 monstro de TREVAS	\r\nO nome deste card se torna "Caveira Invocada" no campo, mas ele ainda é considerado como um card "Arquidemônio". \r\nTodos os "Caveira Invocada" que você controla ganham 500 de ATK. \r\nSe este card Invocado por Invocação-Fusão que você controla for enviado para o seu Cemitério por um card do oponente: você pode Invocar por Invocação-Especial 1 "Caveira Invocada" da sua mão, do Deck ou do Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32785578,'Não Boas-vindas a Labrinto','Quando um monstro declarar um ataque, enquanto você controlar um monstro Demônio: escolha 1 card no campo; negue o ataque e, se isso acontecer, destrua o card alvo e, depois, você pode Baixar 1 Armadilha Normal que não seja "Labrinto" da sua mão ou do Deck.','Baixar o card selecionado?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32787239,'Camarartista Trumpanda',replace(replace('Escala de Pêndulo = 3\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno: você pode aumentar a Escala de Pêndulo deste card em 1 (máx. 12).\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nQuando um Monstro Pêndulo seu for escolhido como alvo de um ataque: você pode negar o ataque. \r\nVocê só pode usar este efeito de "Camarartista Trumpanda" uma vez por turno.','\r',char(13)),'\n',char(10)),'Aumentar Escala Pêndulo','Negar o ataque','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32807846,'Reforço do Exército','Adicione 1 monstro Guerreiro de Nível 4 ou menos do seu Deck à sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32807847,'Reforço do Exército','Adicione 1 monstro Guerreiro de Nível 4 ou menos do seu Deck à sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32807848,'Reforço do Exército','Adicione 1 monstro Guerreiro de Nível 4 ou menos do seu Deck à sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32807849,'Reforço do Exército','Adicione 1 monstro Guerreiro de Nível 4 ou menos do seu Deck à sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32809211,'Jinzo Nº 7','Este monstro pode atacar diretamente os Life Points do seu adversário.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32825095,'Moreia Branca',replace(replace('Durante o turno em que você Invocou este card por Invocação-Normal, ele pode atacar diretamente seu oponente. \r\nSe este card for Invocado por Invocação-Especial do Cemitério: você pode considerá-lo como um Regulador neste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32828466,'Desperte Seu HERÓI do Elemento',replace(replace('1 Monstro de Fusão "HERÓI do Elemento" + 1+ monstros Guerreiro	\r\nDeve ser Invocado por Invocação-Fusão. \r\nGanha 300 de ATK para cada matéria usada para sua Invocação. \r\nPode realizar um número de ataques contra monstros a cada Fase de Batalha, até o número de Monstros de Fusão usados como matéria para sua Invocação. \r\nDepois do cálculo de dano, se este card batalhou um monstro: destrua esse monstro e, se isso acontecer, cause dano ao seu oponente igual ao ATK original dele. \r\nSe este card Invocado por Invocação-Fusão for destruído: Invoque por Invocação-Especial 1 monstro Guerreiro da sua mão ou do Deck.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32828467,'Desperte Seu HERÓI do Elemento',replace(replace('1 Monstro de Fusão "HERÓI do Elemento" + 1+ monstros Guerreiro	\r\nDeve ser Invocado por Invocação-Fusão. \r\nGanha 300 de ATK para cada matéria usada para sua Invocação. \r\nPode realizar um número de ataques contra monstros a cada Fase de Batalha, até o número de Monstros de Fusão usados como matéria para sua Invocação. \r\nDepois do cálculo de dano, se este card batalhou um monstro: destrua esse monstro e, se isso acontecer, cause dano ao seu oponente igual ao ATK original dele. \r\nSe este card Invocado por Invocação-Fusão for destruído: Invoque por Invocação-Especial 1 monstro Guerreiro da sua mão ou do Deck.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32828635,'Ciclo do Mundo',replace(replace('Este card é usado para a Invocação-Ritual de "Ruína, a Rainha do Esquecimento" ou "Demise, o Rei do Armagedom". \r\nVocê também deve oferecer como Tributo monstros do campo cuja soma dos Níveis seja igual ou exceda o Nível do Monstro de Ritual que você Invocar por Invocação-Ritual. \r\nDurante sua Fase Principal, exceto no turno em que este card foi enviado para o Cemitério: você pode embaralhar este card no Deck; adicione 1 "Fim do Mundo" do seu Deck à sua mão e, depois, você pode adicionar 1 "Ruína, a Rainha do Esquecimento" ou "Demise, o Rei do Armagedom" do seu Cemitério à sua mão.','\r',char(13)),'\n',char(10)),'','Recuperar o card?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32835363,'Rompimento','Uma vez por turno, quando um ou mais monstros forem enviados do campo para o Cemitério por um efeito de card: Cause 800 de dano ao dono dos monstros.','Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32841045,'Mágico Mosqueteiro Caspar',replace(replace('Durante o turno de qualquer duelista, você pode ativar Cards de Magia/Armadilha "Mágico(a) Mosquete" da sua mão. \r\nSe um Card de Magia/Armadilha for ativado na coluna deste card (exceto durante a Etapa de Dano): você pode adicionar 1 card "Mágico(a) Mosquete" do seu Deck à sua mão, mas não um card com o mesmo nome que o desse card ativado. \r\nVocê só pode usar este efeito de "Mágico Mosqueteiro Caspar" uma vez por turno.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Ativar aplicando o efeito de "Mágico Mosqueteiro Caspar".','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32854013,'Super Impulso Precipitado','Escolha 1 monstro Besta que você controla e 1 monstro que seu oponente controla; destrua o primeiro alvo e, se isso acontecer, embaralhe o segundo alvo no Deck.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32872239,'Gallugallud, o Enigma Sem Fim',replace(replace('Escala de Pêndulo = 9\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nEste espírito sinistro de chamas ondulantes pode se transformar em qualquer ser. À medida que mudava de pássaro para humano, e de humano para pássaro, ele foi se esquecendo de seu verdadeiro eu.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32872833,'Parsec, o Dragão Interestelar','Se você controlar um monstro de Nível 8, você pode Invocar este card por Invocação-Normal sem oferecer Tributo.','Invocar sem oferecer Tributo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32875265,'Parada das Marionetes',replace(replace('Se seu oponente controlar mais monstros que você: Invoque por Invocação-Especial monstros "Engenhoca Marionete" com nomes diferentes do seu Deck, até a diferença e, depois, se os PV do seu oponente forem pelo menos 2000 a mais que os seus, você pode Baixar 1 Magia Normal "Magia de Aumento de Classe" diretamente do seu Deck. \r\nPelo resto deste turno depois que este card resolver, você não pode Invocar monstros por Invocação-Especial, exceto monstros "Engenhoca Marionete". \r\nVocê só pode ativar 1 "Parada das Marionetes" por turno.','\r',char(13)),'\n',char(10)),'Baixar o Card de Magia "Magia de Aumento de Classe"?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32887445,'Gracejo Florescente',replace(replace('Escave cards do seu Deck igual ao número de "Gracejo Florescente" no seu Cemitério +3 e, se você escavar pelo menos 1 Monstro, 1 Magia e 1 Armadilha, adicione 1 deles à sua mão e envie os outros cards para o Cemitério. \r\nCaso contrário, embaralhe todos os cards escavados no seu Deck. \r\nVocê só pode ativar 1 "Gracejo Florescente" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32907538,'Constritor Octópode',replace(replace('Quando este card for Invocado por Invocação-Normal, você pode selecionar 1 monstro que seu oponente controla. \r\nO monstro selecionado não pode atacar ou ser oferecido como Tributo, enquanto este card permanecer com a face para cima no campo. \r\nDurante cada uma das suas Fases Finais, pague 500 PV ou destrua este card.','\r',char(13)),'\n',char(10)),'Pagar 500 PV para manter "Constritor Octópode"?','Restrição de ataque','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32909498,'Fenrir Kashtira',replace(replace('Se você não controlar nenhum monstro, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode usar cada um dos seguintes efeitos de "Fenrir Kashtira" uma vez por turno. \r\nDurante sua Fase Principal: você pode adicionar 1 monstro "Kashtira" do seu Deck à sua mão. \r\nQuando este card declarar um ataque, ou se seu oponente ativar um efeito de monstro (exceto durante a Etapa de Dano): você pode escolher 1 card com a face para cima que seu oponente controla; bana-o com a face para baixo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32912040,'Triâmide Mestre',replace(replace('Uma vez por turno: você pode enviar 1 card "Triâmide" com a face para cima que você controla para o Cemitério e, depois, escolher 1 card Baixado no campo; destrua-o. \r\nUma vez por turno, durante o turno do seu oponente: você pode escolher 1 Card de Magia de Campo "Triâmide" na sua Zona do Campo; envie-o para o Cemitério e, se isso acontecer, ative 1 Card de Magia de Campo "Triâmide" do seu Deck com um nome diferente (este é um Efeito Rápido).','\r',char(13)),'\n',char(10)),'Destrua 1 card Baixado no campo','Ativar uma Magia de Campo','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32918479,'Meca Majestoso - Senku',replace(replace('Quando este card causar Dano de Batalha ao seu oponente com um ataque direto: Compre 1 card. \r\nDurante a Fase Final do turno em que este card foi Invocado: Envie-o ao Cemitério.','\r',char(13)),'\n',char(10)),'Comprar','Enviar para o Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32919136,'Queda',replace(replace('Ative este card ao escolher um monstro do oponente; equipe este card a ele. \r\nTome o controle dele. \r\nDestrua este card a não ser que você controle um card "Arquidemônio". \r\nDurante cada uma das Fases de Apoio do seu oponente: você sofre 800 de dano.','\r',char(13)),'\n',char(10)),'Causar dano aos PV','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32933942,'Fera Cristalina Gata Ametista',replace(replace('Este card pode atacar diretamente seu oponente, mas quando ele usar este efeito, qualquer dano de batalha que ele causar ao seu oponente é diminuído pela metade. \r\nSe este card com a face para cima for destruído em uma Zona de Monstros, em vez de enviá-lo para o Cemitério, você pode colocá-lo com a face para cima na sua Zona de Magias & Armadilhas como uma Magia Contínua.','\r',char(13)),'\n',char(10)),'Colocar na Zona de Magias & Armadilhas quando for destruído','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32939238,'Ferramenta da Arte Ninjitsu - Escavadora de Ferro',replace(replace('O monstro equipado ganha 500 de ATK e, além disso, ele é considerado como um monstro "Ninja". \r\nVocê só pode usar cada um dos seguintes efeitos de "Ferramenta da Arte Ninjitsu - Escavadora de Ferro" uma vez por turno. \r\nVocê pode banir 1 monstro "Ninja" do seu Cemitério e, depois, escolha 1 card no campo; destrua-o. \r\nSe este card for enviado do campo para o Cemitério: você pode escolher 1 dos seus monstros "Ninja" banidos; adicione-o à sua mão ou Invoque-o por Invocação-Especial com a face para baixo em Posição de Defesa.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32965616,'Doriado, Graça dos Elementos',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao ter 6 ou mais monstros com Atributos diferentes nos Cemitérios. \r\nGanha ATK/DEF igual ao número de Atributos diferentes nos Cemitérios x 500. \r\nQuando seu oponente Invocaria um ou mais monstros por Invocação-Especial (Efeito Rápido): você pode banir 3 monstros do seu Cemitério; negue a Invocação e, se isso acontecer, destrua esses monstros.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32975247,'Dragão Divino Titanomakhia',replace(replace('Este card Invocado por Invocação-Especial não pode ser destruído em batalha. \r\nVocê só pode usar cada um dos seguintes efeitos de "Dragão Divino Titanomakhia" uma vez por turno. \r\nVocê pode banir 3 "Dragão Divino Titanomakhia" do seu Cemitério e/ou do campo com a face para cima, incluindo este card no campo; destrua todos os cards que seu oponente controla. \r\nDurante a Fase Final: você pode enviar cards do topo do seu Deck para o seu Cemitério, igual ao número de monstros Dragão que você controla.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32986898,'Estrela de Aço Reguladora',replace(replace('3 Monstros que não sejam Link	\r\nGanha ATK igual aos Níveis/Classes originais combinados dos monstros usados para a sua Invocação-Link x 100. \r\nVocê pode escolher 1 Monstro que não seja Link que seu oponente controla com ATK igual ou menor que o deste card; destrua-o e, depois, se este card foi Invocado por Invocação-Link usando um Monstro Xyz como matéria, cause dano ao seu oponente igual à metade do ATK original do monstro destruído. \r\nVocê só pode usar este efeito de "Estrela de Aço Reguladora" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32991027,'Georgius, o Espadachim da Barreira de Gelo',replace(replace('Enquanto você controlar outro monstro "Barreira de Gelo", seu oponente não pode ativar os efeitos de monstros no Cemitério. \r\nVocê só pode usar cada um dos seguintes efeitos de "Georgius, o Espadachim da Barreira de Gelo" uma vez por turno. \r\nSe você controlar um monstro "Barreira de Gelo": você pode Invocar este card por Invocação-Especial da sua mão em Posição de Defesa. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode Invocar por Invocação-Especial 1 monstro "Barreira de Gelo" de Nível 5 ou menos da sua mão ou do Cemitério.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial da mão','Invoque por Invocação Especial da sua mão ou do seu Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32991300,'Agnumdía do Criademônio',replace(replace('2+ monstros, incluindo um monstro Demônio de LUZ	\r\nUma vez por turno (Efeito Rápido): você pode escolher 1 monstro Demônio de LUZ que não seja Link no seu Cemitério; Invoque-o por Invocação-Especial e, se isso acontecer, equipe este card que você controla a esse monstro como uma Magia de Equipamento com os seguintes efeitos.\r\n● O monstro equipado ganha ATK igual à soma dos Valores Link dos Monstros Link equipados a ele x 600.\r\n● Se o monstro equipado atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32995007,'Senhor Lobo Celestial, Sirius Azul',replace(replace('1 Regulador + 1 ou mais monstros não-Reguladores	\r\nQuando este card no campo for destruído e enviado para o Cemitério: escolha 1 monstro com a face para cima que seu oponente controla; ele perde 2400 de ATK.','\r',char(13)),'\n',char(10)),'Reduzir ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32995276,'Link Discípulo',replace(replace('1 monstro Ciberso de Nível 4 ou menos	\r\nVocê pode oferecer como Tributo 1 monstro para o qual este card apontar; compre 1 card e, depois, coloque 1 card da sua mão no fundo do Deck. \r\nVocê só pode usar este efeito de "Link Discípulo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32999573,'Domínio Xyz',replace(replace('Se um Monstro Xyz no campo ativaria o seu efeito ao desassociar uma ou mais de suas próprias Matérias Xyz, seu controlador pode banir 1 card da mão dele com a face para baixo em vez de desassociar 1 dessas Matérias Xyz. \r\nCada duelista só pode usar este efeito uma vez por turno.','\r',char(13)),'\n',char(10)),'Usar o efeito de "Domínio Xyz"?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33008376,'Materriator Gigadra',replace(replace('Você pode descartar 1 card; Invoque por Invocação-Especial 1 Monstro Normal de Nível 3 da sua mão ou do Deck ou, se você descartou um Monstro Normal para ativar este efeito, em vez disso, você pode Invocar por Invocação-Especial 1 monstro "Materriator". \r\nVocê só pode usar este efeito de "Materriator Gigadra" uma vez por turno. \r\nVocê não pode Invocar monstros do Deck Adicional por Invocação-Especial, exceto Monstros Xyz.','\r',char(13)),'\n',char(10)),'Você não pode Invocar por Invocação Especial do Deck Adicional a menos que controle um Monstro Xyz','Invocar por Invocação Especial da mão/Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33015627,'Sandaion, o Senhor do Tempo',replace(replace('Não pode ser Invocado por Invocação-Especial do Deck. \r\nVocê só pode controlar 1 "Sandaion, o Senhor do Tempo". \r\nSe somente seu oponente controlar um monstro, você pode Invocar este card por Invocação-Normal sem oferecer Tributo. \r\nNão pode ser destruído em batalha ou por efeitos de card. \r\nNenhum duelista sofre dano de batalha de ataques envolvendo este card. \r\nNo final da Fase de Batalha, se este card batalhou: cause 2000 de dano ao seu oponente. \r\nUma vez por turno, durante sua Fase de Apoio: embaralhe este card no Deck.','\r',char(13)),'\n',char(10)),'Invocação Normal sem Tributo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33017655,'Os Portões do Mundo Negro',replace(replace('Todos os monstros Demônio ganham 300 de ATK/DEF. \r\nUma vez por turno: você pode banir 1 monstro Demônio do seu Cemitério; descarte 1 monstro Demônio e, depois, compre 1 card.','\r',char(13)),'\n',char(10)),'Descartar e comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33017964,'Portão da Ilusão',replace(replace('Pague metade dos seus PV; destrua tantos monstros que seu oponente controla quanto possível e, depois, você pode Invocar por Invocação-Especial 1 monstro do Cemitério do seu oponente no seu campo, ignorando suas condições de Invocação. \r\nVocê só pode aplicar este efeito de "Portão da Ilusão" uma vez por Duelo.','\r',char(13)),'\n',char(10)),'Ativar','Invocação Especial?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33022867,'Imperador Maju Garzett',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao oferecer 3 monstros como Tributo. \r\nO ATK deste card se torna a soma do ATK original dos monstros oferecidos como Tributo. \r\nSeu oponente não pode ativar cards ou efeitos durante a Fase de Batalha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33026283,'Dois Avatares - Kon-Gyo Edificado',replace(replace('"Punhos dos Dois Avatares - Yuhi" + 2 monstros "Dois Avatares"	\r\nSe este card batalhar, seu oponente não pode ativar cards ou efeitos até o final da Etapa de Dano. \r\nSe este card atacar, depois do cálculo de dano: você pode devolver 1 monstro que seu oponente controla para a mão. \r\nQuando um Card de Magia/Armadilha do seu oponente ou seus efeitos forem ativados que escolham como alvo este card no campo, enquanto você controlar 2 ou mais Monstros de Fusão (Efeito Rápido): você pode negar a ativação. \r\nVocê só pode usar este efeito de "Dois Avatares - Kon-Gyo Edificado" uma vez por turno.','\r',char(13)),'\n',char(10)),'Destruir 1 monstro','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33031674,'Provação Incandescente',replace(replace('Este card é usado para a Invocação-Ritual de "Lord da Chama Lendária". \r\nTambém deve oferecer como Tributo monstros cuja soma dos Níveis seja igual ou maior que 7, do Campo ou da sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33034646,'Ninja da Armadura de Chamas','Quando este card for Invocado: você pode escolher 1 monstro "Ninja" que você controla; aumente seu Nível em 1.','Aumentar o Nível','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33041277,'Revsistema Cibernético',replace(replace('Invoque por Invocação-Especial 1 "Dragão Cibernético" da sua mão ou do Cemitério. \r\nEle não pode ser destruído por efeitos de card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33055499,'Presa do Jirai Gumo',replace(replace('Invoque este card por Invocação-Especial como um Monstro Normal (Inseto/TERRA/Nível 5/ATK 2100/DEF 100) na sua Zona de Monstros Principal em sua mesma coluna (este card ainda é considerado uma Armadilha) e, depois, você pode destruir 1 monstro que seu oponente controla na coluna deste card. \r\nVocê pode banir este card do seu Cemitério; adicione à sua mão 1 dos seus "Sanga do Trovão", "Kazejin" ou "Suijin" que estiverem banidos ou no seu Deck. \r\nVocê só pode usar cada efeito de "Presa do Jirai Gumo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Destruir o monstro do seu oponente?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33057951,'Emergir','Escolha 1 monstro Peixe, Serpente Marinha ou Aqua de Nível 3 ou menos no seu Cemitério; Invoque-o por Invocação-Especial em Posição de Defesa.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33062423,'Decodificar Destruição',replace(replace('Escolha 1 "Decodificar Transmissor" que você controla; neste turno, aplique os seguintes efeitos, dependendo do número de monstros para os quais ele apontar atualmente.\r\n● 1+: Esse monstro ganha 500 de ATK para cada monstro para os quais ele apontar atualmente.\r\n● 2+: Os monstros destruídos em batalha com esse monstro são banidos depois do cálculo de dano.\r\n● 3: Depois do cálculo de dano, se esse monstro destruir um monstro do seu oponente em batalha: destrua todos os cards que seu oponente controla.	\r\nVocê só pode ativar 1 "Decodificar Destruição" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33064647,'Dragão Escudo de Um Só Olho','Este dragão usa um escudo não só para sua proteção, mas também para esmagar seus inimigos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33066139,'Ceifador de Cards',replace(replace('VIRE: Destrói 1 Card de Armadilha no Campo. \r\nSe o alvo deste card está com a face para baixo, vire a face para cima. \r\nSe for um Card de Armadilha é destruído. \r\nSe não, coloque-o novamente com a face para baixo. \r\nO card virado não é Activado.','\r',char(13)),'\n',char(10)),'Destruir uma Armadilha','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33093439,'Eltanin Cibernético',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao banir todos os monstros Máquina de LUZ no seu campo e Cemitério. \r\nO ATK/DEF deste card se tornam o número de monstros banidos para sua Invocação-Especial x 500. \r\nSe este card for Invocado por Invocação-Especial: envie todos os outros monstros com a face para cima no campo para o Cemitério.','\r',char(13)),'\n',char(10)),'Enviar para o Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33099732,'Fusão Futura Sobrecarregada',replace(replace('Você pode ativar 1 desses efeitos (mas você só pode usar cada efeito de "Fusão Futura Sobrecarregada" uma vez por turno);\r\n● Revele 1 Monstro de Fusão no seu Deck Adicional e envie 1 matéria cujo nome seja mencionado nele do seu Deck para o Cemitério, mas pelo resto deste turno, você não pode Invocar por Invocação-Especial, nem ativar os efeitos de, monstros com o mesmo nome que o do enviado para o Cemitério por este efeito.\r\n● Invoque por Invocação-Fusão 1 Monstro de Fusão Máquina de TREVAS do seu Deck Adicional, ao banir suas matérias do seu Cemitério.','\r',char(13)),'\n',char(10)),'Enviar matérias para o Cemitério','Invocação Fusão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33103459,'Camarartista Córnio',replace(replace('Uma vez por turno, durante sua Fase Principal, se este card foi Invocado por Invocação-Normal ou Especial neste turno: você pode escolher 1 outro monstro "Camarartista" que você controla com 1000 ou menos de ATK; mude tanto ele quanto este card, que você controla, de Posição de Ataque com a face para cima para Posição de Defesa e, se isso acontecer, adicione 1 monstro "Olhos Anômalos" do seu Deck à sua mão. \r\nDurante o turno do seu oponente (Efeito Rápido): você pode banir 1 monstro "Camarartista", exceto "Camarartista Córnio", e este card do seu Cemitério; ganhe 500 PV.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33112041,'Rato Vulcânico','Este rato mutante vive no núcleo dos vulcões ativos. Nenhum calor é muito para ele.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33113958,'Dragão LeVirtude',replace(replace('2 monstros de Nível 3	\r\nSe este card for Invocado por Invocação-Especial: você pode adicionar 1 "Fluxo de Virtude" do seu Deck à sua mão. \r\nVocê pode ativar 1 desses efeitos;\r\n● Desassocie 1 matéria de um monstro que você controla e, depois, adicione 1 monstro Peixe, Serpente Marinha ou Aqua do seu Cemitério à sua mão, exceto "Dragão LeVirtude".\r\n● Escolha 2 Monstros Xyz no campo; associe 1 matéria de 1 desses monstros ao outro.	\r\nVocê só pode usar cada efeito de "Dragão LeVirtude" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Recuperar do Cemitério','Transferir Matérias Xyz','Escolha o monstro que perdeu Matéria Xyz','','','','','','','','','','','','');
INSERT INTO texts VALUES(33114323,'Armadura de Prata','Enquanto você controlar o monstro equipado com este card, o seu adversário não pode usar o efeito de um Card de Magia, Armadilha, ou Monstro de Efeito que designe 1 monstro como alvo exceto o monstro equipado.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33129626,'Centauro Mina',replace(replace('1 monstro Guerreiro de LUZ + 1 monstro Besta	\r\nUma vez por turno, durante o seu turno, quando seu oponente ativar um Card de Armadilha (Efeito Rápido): você pode negar a ativação e, se isso acontecer, Baixe esse card. \r\nVocê só pode usar cada um dos seguintes efeitos de "Centauro Mina" uma vez por turno. \r\nDurante sua Fase Principal: você pode Invocar por Invocação-Especial 1 monstro de Nível 2 ou menos da sua mão ou do Cemitério. \r\nSe este card for enviado para o Cemitério como Matéria Sincro para um monstro Guerreiro de VENTO: você pode destruir 1 monstro com a face para cima no campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33145233,'Djinn, o Demolidor de Rituais',replace(replace('Quando você Invocar um monstro por Invocação-Ritual, você pode banir este card do seu Cemitério como 1 dos monstros exigidos para a Invocação-Ritual. \r\nSe um duelista Invocar por Invocação-Ritual usando este card, esse monstro Invocado por Invocação-Ritual não pode ser escolhido como alvo de efeitos de card do outro duelista.','\r',char(13)),'\n',char(10)),'O efeito de "Djinn, o Demolidor de Rituais" está sendo aplicado.','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33158448,'F.A. Dragster Aurora',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nGanha ATK igual ao seu Nível x 300. \r\nSe este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente. \r\nSempre que um Card de Magia/Armadilha "F.A." ou seus efeitos forem ativados (mesmo durante a Etapa de Dano): você pode aumentar em 1 o Nível deste card. \r\nUma vez por turno, quando seu oponente ativar um Card de Magia/Armadilha ou seus efeitos (Efeito Rápido): você pode reduzir o Nível deste card em 2 e, se isso acontecer, negue a ativação e, se isso acontecer, destrua esse card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33166263,'Éon, o Hiperinvokado',replace(replace('2+ Monstros de Fusão com Atributos diferentes	\r\nSe este card for Invocado por Invocação-Fusão: você pode banir cards do campo e/ou dos Cemitérios, até o número de monstros usados como matéria e, depois, se você usou 3 ou mais matérias, você pode olhar o Deck Adicional do seu oponente e banir até 3 cards dali. \r\n(Efeito Rápido): você pode declarar 1 Atributo; todos os outros monstros no campo se tornam desse Atributo até o final deste turno. \r\nVocê só pode usar 1 efeito de "Éon, o Hiperinvokado" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Efeito de banimento','Alterar o Atributo','Banir do Deck Adicional?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33171768,'Chutador Axônico Oráculo',replace(replace('1 monstro Psíquico + 1 Monstro Sincro, Xyz ou Link	\r\nDepois que este card for Invocado por Invocação-Fusão, ele ganha 1000 de ATK para cada Monstro Sincro, Xyz e Link usado como sua matéria, até o final do próximo turno. \r\nVocê só pode usar cada um dos seguintes efeitos de "Chutador Axônico Oráculo" uma vez por turno. \r\nQuando seu oponente Invocaria um ou mais monstros por Invocação-Especial (Efeito Rápido): você pode negar a Invocação e, se isso acontecer, bana esse(s) monstro(s). \r\nSe este card Invocado por Invocação-Fusão for enviado para o Cemitério: você pode banir 1 Magia Normal ou Rápida "Teleporte" do seu Cemitério; Invoque este card por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Negar a Invocação Especial','Invocação Especial','O efeito de "Chutador Axônico Oráculo" está sendo aplicado.','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33178416,'Misairuzame','Um peixe lança-mísseis protegido por espinhos letais.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33184167,'Vírus Infecta-Tribus','Descarte 1 card da sua mão e declare um Tipo de monstro para destruir todos os monstros do Tipo declarado no Campo com a face para cima.','Destrua todos os monstros do Tipo declarado','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33184236,'Loja de Mágicas Karakuri',replace(replace('Só pode ser ativado quando a posição de batalha de um monstro "Karakuri" com a face para cima que você controla for alterada. \r\nSelecione 1 card no campo e destrua-o.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33198837,'Besta de Naturia',replace(replace('1 Regulador de TERRA + 1+ monstros não-Reguladores de TERRA	\r\nQuando um Card de Magia for ativado (Efeito Rápido): você pode enviar os 2 cards do topo do seu Deck para o Cemitério; negue a ativação e, se isso acontecer, destrua-o. \r\nEste card deve estar com a face para cima no campo para ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Negue a ativação de um Card de Magia e destrua-o','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33202303,'Servente Terrestre Geo Gremlina',replace(replace('1 monstro "Terrestre" + 1 monstro de TREVAS	\r\nSe este card for Invocado por Invocação-Especial: você pode adicionar 1 monstro "Terrestre" do seu Deck à sua mão. \r\nVocê pode escolher 1 Monstro Sincro de TREVAS que você controla; ele pode atacar diretamente neste turno. \r\nSe um ou mais monstros que seu oponente controla forem destruídos por um efeito de card "Terrestre" (exceto durante a Etapa de Dano): você pode escolher 1 desses monstros destruídos; cause dano ao seu oponente igual ao ATK original desse monstro. \r\nVocê só pode usar cada efeito de "Servente Terrestre Geo Gremlina" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33206889,'Camaramágico Bruxa Trapezista',replace(replace('2 monstros "Camaramágico"	\r\nMonstros "Camaramágico" que você controla não podem ser destruídos por seus efeitos de card e, além disso, seu oponente não pode escolhê-los como alvo de efeitos de card. \r\nEnquanto você controlar um monstro "Camaramágico", exceto "Camaramágico Bruxa Trapezista", os monstros do seu oponente não podem escolher este card como alvo de ataques. \r\nQuando um ataque for declarado envolvendo um monstro "Camaramágico" seu e um monstro do oponente: você pode fazer com que esse monstro do oponente perca 600 de ATK.','\r',char(13)),'\n',char(10)),'Reduzir ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33212663,'Arquinêmeses Eschatos',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro deve ser Invocado por Invocação-Especial (da sua mão) ao banir 3 monstros com Tipos diferentes do seu Cemitério e/ou do campo com a face para cima. \r\nNão pode ser destruído por efeitos de card. \r\nVocê pode declarar 1 Tipo de Monstro no campo; destrua todos os monstros no campo com esse Tipo e, além disso, até o final do próximo turno, nenhum duelista pode Invocar monstros com esse Tipo por Invocação-Especial. \r\nVocê só pode usar este efeito de "Arquinêmeses Eschatos" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33225925,'Milla, a Maga Temporal',replace(replace('Quando este card for Invocado por Invocação-Normal: Escolha 1 card Baixado que seu oponente controla; olhe-o. \r\nSeu oponente não pode ativar Cards de Magia/Armadilha em resposta à ativação deste efeito.','\r',char(13)),'\n',char(10)),'Revelar 1 card Baixado que seu oponente controla','Escolha um card para revelar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33236860,'Asanegra - Vento Prateado, o Ascendente',replace(replace('1 Regulador "Asanegra" + 2+ monstros não-Reguladores	\r\nQuando este card for Invocado por Invocação-Sincro: você pode escolher até 2 monstros com a face para cima no campo com DEF menor que o ATK deste card; destrua os alvos. \r\nVocê não pode conduzir sua Fase de Batalha no turno em que ativar este efeito. \r\nDurante cada um dos turnos do seu oponente, o primeiro monstro "Asanegra" que você controla que seria destruído em batalha, não é destruído.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33244944,'Contrato com Exodia','Se você tiver todos os 5 "Exodia, "O Proibido"", "Braço Direito de "O Proibido"", "Braço Esquerdo de "O Proibido"", "Perna Direita de "O Proibido"", e "Perna Esquerda de "O Proibido"" no seu Cemitério: Invoque 1 "Exodia Necross" por Invocação-Especial da sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33245030,'Esfera Kuriboh',replace(replace('Quando um monstro do oponente declarar um ataque: você pode enviar este card da sua mão para o Cemitério; coloque o monstro atacante em Posição de Defesa. \r\nQuando você Invocar por Invocação-Ritual, você pode banir este card do seu Cemitério como 1 dos monstros necessários para a Invocação-Ritual.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33248692,'Caçador de Opções',replace(replace('Ative apenas quando um monstro que você controla for destruído em batalha e enviado ao Cemitério. \r\nGanhe PV igual ao ATK original do monstro destruído.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33250142,'Capitânia Ursatron Definitiva',replace(replace('(Este card deve ser sempre considerado como um card "Ursártico(a)" e "Drytron".)	\r\nDeve ser Invocado por Invocação-Especial com "Drytron Ursártico". \r\nUma vez por turno, se outro Monstro de Efeito for Invocado por Invocação-Especial no seu campo (exceto durante a Etapa de Dano): você pode adicionar 1 monstro "Ursártico(a)" ou "Drytron" do seu Deck à sua mão. \r\nUma vez por turno: você pode escolher 1 dos seus monstros "Ursártico(a)" ou "Drytron" banidos; adicione-o à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33252803,'Magia de Aumento de Classe Caos Célere',replace(replace('Escolha 1 Monstro Xyz "Número" que você controla, exceto um monstro "Número C"; Invoque por Invocação-Especial do seu Deck Adicional, 1 monstro "Número C" com o mesmo número que o alvo em seu nome, mas 1 Classe maior, usando-o como uma Matéria Xyz. \r\n(Isso é considerado uma Invocação-Xyz. Transfira as matérias dele para o monstro Invocado.)','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33256280,'Metalmorfose Motourista',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno: você pode escolher 1 outro card com a face para cima que você controla; destrua-o e, se isso acontecer, Baixe 1 Magia/Armadilha "Metalmorfose" diretamente do seu Deck.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nEsse buggy dourado e reluzente realmente acaba com os vilões. Que lindas rodas! (Mas com um motorista trapalhão....)','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33280639,'Prólogo do Soldado da Espada da Destruição',replace(replace('Envie 1 card "Espada da Destruição" e 1 monstro "Blader Notável" do seu Deck para o Cemitério, exceto "Prólogo do Soldado da Espada da Destruição"; Invoque por Invocação-Especial 1 "Dragão Notável" do seu Deck Adicional ou Cemitério, mas destrua-o durante a Fase Final do próximo turno. \r\nVocê pode banir este card do seu Cemitério; neste turno, cards "Espada da Destruição" que você controla não podem ser destruídos em batalha ou por efeitos de card. \r\nVocê só pode ativar 1 "Prólogo do Soldado da Espada da Destruição" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33282498,'Dragão do Arco da Coragem',replace(replace('Se este card for Invocado por Invocação-Especial do Cemitério: você pode banir tantas Magias/Armadilhas com a face para cima que seu oponente controla quanto possível e, se isso acontecer, este card ganha 200 de ATK/DEF para cada card banido. \r\nUma vez por turno, durante a Fase de Apoio, se este card estiver no Cemitério porque foi enviado para lá no turno passado: você pode escolher 1 monstro Dragão de Nível 7 ou 8 no seu Cemitério, exceto "Dragão do Arco da Coragem"; Invoque-o por Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33296432,'Dogmatika Adin, o Iluminado',replace(replace('Não pode ser destruído em batalha com um monstro Invocado por Invocação-Especial do Deck Adicional. \r\nVocê só pode usar cada um dos seguintes efeitos de "Dogmatika Adin, o Iluminado" uma vez por turno. \r\nSe um monstro Invocado por Invocação-Especial do Deck Adicional estiver no campo: você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe este card no campo for destruído em batalha ou por um efeito de card: você pode Invocar por Invocação-Especial 1 monstro "Dogmatika" do seu Deck, exceto "Dogmatika Adin, o Iluminado".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33298291,'Dança com Bestas',replace(replace('Quando um monstro do oponente declarar um ataque direto, enquanto o ATK combinado de todos os monstros com a face para cima que ele controla for 8000 ou mais: Invoque por Invocação-Especial, em Posição de Ataque, 3 monstros com nomes originais diferentes, 1 da sua mão, 1 do Deck e 1 do Cemitério. \r\nVocê só pode ativar 1 "Dança com Bestas" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33300669,'Amórfago da Inveja',replace(replace('Escala de Pêndulo = 5\r\n[ Efeito de Pêndulo ]\r\nEnquanto você controlar um monstro "Amórfago", nenhum duelista pode ativar cards ou efeitos como um Elo de Corrente 2 ou mais. \r\nUma vez por turno, durante sua Fase de Apoio, ofereça 1 monstro como Tributo ou destrua este card.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe este card for Invocado por Invocação-Pêndulo ou virado com a face para cima, nenhum duelista pode Invocar monstros do Deck Adicional por Invocação-Especial enquanto este card estiver no campo com a face para cima, exceto monstros "Amórfago".','\r',char(13)),'\n',char(10)),'Oferecer como Tributo 1 monstro que você controla?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33302407,'Corrente Envenenada','Durante a Fase Final do seu turno, se você não atacou, você pode fazer com que seu oponente envie cards igual ao número de monstros "Corrente de Ferro" com a face para cima que você controla do topo do Deck dele ao Cemitério.','Enviar do Deck para o Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33302589,'Constelar Castor',replace(replace('Se este card for Invocado: você pode Invocar por Invocação-Especial 1 monstro "Constelar" do seu Deck, exceto "Constelar Castor" e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto monstros de LUZ ou de TREVAS. \r\nVocê só pode usar este efeito de "Constelar Castor" uma vez por turno. \r\nUm Monstro Xyz "Constelar" que tenha este card como matéria ganha este efeito.\r\n● Uma vez por turno, quando seu oponente ativar um Card de Magia ou seus efeitos (Efeito Rápido): você pode desassociar 2 matérias de um ou mais monstros que você controla e, se isso acontecer, negue esse efeito e, se isso acontecer, destrua esse card.','\r',char(13)),'\n',char(10)),'Invocação Especial','Negar a ativação de um efeito de Magia (Constelar Castor)','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33314479,'Carpa Vermelha Voadora',replace(replace('(Efeito Rápido): você pode descartar 1 monstro de ÁGUA; este card ganha 500 de ATK. \r\nQuando este card destruir um monstro do oponente em batalha: você pode oferecer este card como Tributo; Invoque por Invocação-Especial 1 monstro Peixe, Serpente Marinha ou Aqua da sua mão ou do Deck. \r\nVocê só pode usar cada efeito de "Carpa Vermelha Voadora" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33318980,'Soldado Gaia, o Cavaleiro Impetuoso',replace(replace('(Efeito Rápido): você pode oferecer como Tributo 1 Monstro de Fusão Dragão; Invoque este card por Invocação-Especial da sua mão. \r\nSe este card for Invocado por Invocação-Especial: você pode escolher 1 monstro em Posição de Ataque no campo; coloque-o em Posição de Defesa. \r\nVocê pode oferecer este card como Tributo; adicione 1 monstro Guerreiro de Nível 7 ou mais do seu Deck à sua mão, exceto "Soldado Gaia, o Cavaleiro Impetuoso". \r\nVocê só pode usar cada efeito de "Soldado Gaia, o Cavaleiro Impetuoso" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33323657,'Alma Psíquica',replace(replace('Ofereça como Tributo 1 monstro do Tipo Psíquico que você controla. \r\nGanhe PV igual ao Nível do monstro oferecido como Tributo x 300.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33325951,'Shinobaronesa Pavoa das Sombras',replace(replace('Você pode Invocar este card por Invocação-Ritual com "Chamado do Shinobird". \r\nO nome deste card se torna "Shinobaronesa Pavoa" enquanto estiver na mão ou no campo. \r\nSe este card for Invocado por Invocação-Ritual: você pode adicionar 1 Magia/Armadilha do seu Deck à sua mão que mencione "monstro Espírito" em seu texto. \r\nVocê só pode usar este efeito de "Shinobaronesa Pavoa das Sombras" uma vez por turno. \r\nUma vez por turno, durante a Fase de Apoio do próximo turno depois que este card foi banido: Invoque este card banido por Invocação-Especial. \r\nUma vez por turno, durante a Fase Final, se este card foi Invocado por Invocação-Especial neste turno: devolva este card para a mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33327029,'Contragolpe Metalmorfose',replace(replace('Se um ou mais cards que você controla forem destruídos em batalha ou por um efeito de card: Invoque por Invocação-Especial 1 monstro "Metalmorfose" do seu Deck. \r\nDurante o turno de qualquer duelista, exceto no turno em que este card foi enviado para o Cemitério: você pode banir este card do seu Cemitério; adicione 1 Monstro Pêndulo "Metalmorfose" com a face para cima do seu Deck Adicional à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33331231,'Força Cirúrgica - H.A.M.P.',replace(replace('(Este card deve ser sempre considerado como um card "Força Celeste".)	\r\nSe você controlar um monstro "Força Celeste - Ás", você pode Invocar este card por Invocação-Especial (da sua mão) em qualquer campo ao oferecer como Tributo 1 monstro desse campo. \r\nVocê só pode Invocar "Força Cirúrgica - H.A.M.P." por Invocação-Especial uma vez por turno desta forma. \r\nQuando este card for destruído em batalha: você pode escolher 1 card que seu oponente controla; destrua-o.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial para o seu campo','Invocar por Invocação Especial para o campo do seu oponente','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33334269,'D/D Fantasma',replace(replace('Se este card for enviado para o Cemitério: você pode escolher 1 monstro "D/D" ou card "Pacto Obscuro" no seu Cemitério, exceto "D/D Fantasma"; envie 1 card do seu Deck para o Cemitério com esse nome. \r\nSe este card for banido: você pode escolher 1 dos seus monstros "D/D" banidos ou cards "Pacto Obscuro", exceto "D/D Fantasma"; devolva-o para o Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33347467,'Navio Fantasma',replace(replace('Não pode ser Invocado por Invocação-Normal ou Baixado. \r\nDeve primeiro ser Invocado por Invocação-Especial (da sua mão) ao banir 1 monstro de LUZ do seu Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33365932,'Cápsula Vulcânica',replace(replace('Uma vez por turno: você pode pagar 500 PV; adicione 1 "Cápsula Vulcânica" do seu Deck à sua mão. \r\nEste card deve estar no Cemitério para ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Adicione à sua mão 1 "Cápsula Vulcânica"','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33391067,'Boneca de Reflexo de Maldição',replace(replace('Quando um efeito de monstro que causaria dano a você for ativado: em vez disso, seu oponente sofre esse dano. \r\nQuando você sofrer dano de batalha, enquanto este card estiver no seu Cemitério: você pode Baixar este card. \r\nVocê só pode usar este efeito de "Boneca de Reflexo de Maldição" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33393090,'Yowie',replace(replace('Se este card for Invocado (e nenhum outro card): você pode ativar este efeito; seu oponente pula sua próxima Fase de Compra. \r\nVocê só pode Invocar por Invocação-Especial uma vez no turno em que ativar este efeito. \r\nVocê só pode usar este efeito de "Yowie" uma vez por Duelo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33396948,'Exodia, "O Proibido"','Se você tiver "Perna Direita de "O Proibido"", "Perna Esquerda de "O Proibido"", "Braço Direito de "O Proibido"" e "Braço Esquerdo de "O Proibido"", além de este card na sua mão, você vence o Duelo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33396949,'Exodia, "O Proibido"','Se você tiver "Perna Direita de "O Proibido"", "Perna Esquerda de "O Proibido"", "Braço Direito de "O Proibido"" e "Braço Esquerdo de "O Proibido"", além de este card na sua mão, você vence o Duelo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33396950,'Exodia, "O Proibido"','Se você tiver "Perna Direita de "O Proibido"", "Perna Esquerda de "O Proibido"", "Braço Direito de "O Proibido"" e "Braço Esquerdo de "O Proibido"", além de este card na sua mão, você vence o Duelo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33407125,'Labirinto de Labrinto',replace(replace('Se você ativar uma Armadilha Normal "Boas-vindas a Labrinto" Baixada, você pode adicionar este efeito adicional ao efeito desse card na resolução.\r\n● Além disso, depois, destrua 1 card no campo.	\r\nSe você ativar um Card de Armadilha Normal que não seja "Labrinto" (exceto durante a Etapa de Dano): você pode Invocar por Invocação-Especial 1 monstro Demônio da sua mão ou do Cemitério. \r\nVocê só pode usar cada efeito de "Labirinto de Labrinto" uma vez por turno.','\r',char(13)),'\n',char(10)),'Usar o efeito de "Labirinto de Labrinto"?','Invoque por Invocação Especial 1 monstro Demônio','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33413279,'Mago Explosivo',replace(replace('1 Regulador + 1+ monstros Mago não-Reguladores	\r\nVocê pode remover 2 Marcadores de Magia do seu campo e, depois, escolher 1 Magia/Armadilha que seu oponente controla; destrua o alvo.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33413638,'Cavaleiro Barata','Quando este card for enviado ao Cemitério, ele será devolvido ao topo do Deck.','Retornar ao Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33420078,'Zumbi Espalha-praga','Se este card estiver no seu Cemitério: você pode colocar 1 card da sua mão no topo do Deck; Invoque este card por Invocação-Especial, mas bana-o quando ele deixar o campo.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33423043,'Designador D.D.',replace(replace('Declare 1 nome de card. \r\nOlhe a mão do seu oponente e, se ele tiver o card declarado na mão dele, bana esse 1 card. \r\nSe ele não tiver o card declarado na mão dele, bana 1 card aleatório na sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33438265,'Cortador R.B. Ga10',replace(replace('Se você não controlar nenhum monstro com a face para cima, ou os únicos monstros com a face para cima que você controla forem monstros "R.B.", você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Cortador R.B. Ga10" por Invocação-Especial uma vez por turno desta forma. \r\nQuando um Card de Magia/Armadilha do seu oponente ou seus efeitos forem ativados, e este card estiver linkado a um Monstro Link "R.B." (Efeito Rápido): você pode pagar 700 PV; destrua este card e, se isso acontecer, negue esse efeito e, se isso acontecer, destrua esse card. \r\nVocê só pode usar este efeito de "Cortador R.B. Ga10" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Negar e destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33438666,'Ceifarmesim Vampiro',replace(replace('Se um ou mais monstros que você controla seriam destruídos em batalha ou por um efeito de card do oponente, em vez disso, você pode pagar 1000 PV para cada monstro que seria destruído (se usar este efeito, você deve proteger todos os seus monstros que seriam destruídos). \r\nNo final da Fase de Batalha, se este card destruiu quaisquer monstros em batalha: você pode Invocá-los por Invocação-Especial dos Cemitérios no seu campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33453260,'Mão Cômica',replace(replace('Se você controlar "Mundo Toon", equipe a um monstro do oponente. \r\nTome o controle dele. \r\nEle é considerado como um monstro Toon. \r\nSe seu oponente não controlar nenhum monstro Toon, esse monstro pode atacar seu oponente diretamente. \r\nSe "Mundo Toon" não estiver no campo, destrua este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33455338,'Servo Maníaco',replace(replace('Uma vez por turno, durante a Fase de Apoio do seu oponente, você pode remover de jogo qualquer número de monstros de TREVAS do seu Cemitério. \r\nEste monstro ganha 500 de DEF para cada monstro removido até a Fase Final.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33460840,'Guardião de Felgrand',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode equipar a este card 1 monstro do Tipo Dragão de Nível 7 ou 8 da sua mão ou do Cemitério. \r\nEste card ganha ATK e DEF igual à metade do ATK e DEF do monstro equipado a ele por este efeito. \r\nVocê pode oferecer como Tributo 1 monstro e este card e, depois, escolher 1 monstro do Tipo Dragão de Nível 7 ou 8 no seu Cemitério; Invoque-o por Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33467872,'Repetiteur do Mar Profundo',replace(replace('"Diva do Mar Profundo" + 1+ monstros não-Reguladores	\r\nUma vez por turno (Efeito Rápido): você pode descartar 1 monstro de ÁGUA de Nível 4 ou menos; este card ganha 800 de ATK até o final deste turno. \r\nSe este card Invocado por Invocação-Sincro for enviado para o seu Cemitério: você pode escolher 1 monstro de ÁGUA de Nível 5 ou mais no seu Cemitério, exceto "Repetiteur do Mar Profundo"; Invoque-o por Invocação-Especial em Posição de Defesa e, além disso, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros de ÁGUA. \r\nVocê só pode usar este efeito de "Repetiteur do Mar Profundo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33475154,'Fazticeira Madame Rilliona',replace(replace('"Fazticeira Madame Verre" + 2 monstros Mago	\r\nSe este card for Invocado por Invocação-Fusão: você pode Invocar por Invocação-Especial até 3 monstros "Fazticeira" de Nível 7 ou menor com Atributos diferentes de cada outra na sua mão e/ou Deck, você também não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto Monstros de Fusão.\r\nDurante sua Fase Final, se este card está no seu Cemitério: você pode revelar 1 Magia na sua mão; Invoque por Invocação-Especial este card em Posição de Defesa.\r\nVocê só pode usar cada um dos efeitos de "Fazticeira Madame Rilliona" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial do Deck','Invocar este card por Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33491462,'Floco de Neve, a Fada Rikka',replace(replace('Você pode oferecer 1 monstro Planta como Tributo; Invoque por Invocação-Especial tanto este card quanto 1 outro monstro Planta da sua mão e, além disso, você não pode Invocar por Invocação-Especial pelo resto deste turno, exceto monstros Planta. \r\nVocê pode escolher 1 monstro Planta que você controla; todos os monstros Planta que você controla atualmente se tornam do Nível desse monstro até o final deste turno. \r\nVocê só pode usar cada efeito de "Floco de Neve, a Fada Rikka" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33499794,'Nemleria Repeter',replace(replace('Se você controlar outro card "Nemleria": você pode banir, com a face para baixo, o seguinte número de cards do seu Deck Adicional, exceto "Nemleria Sonhadora" e, depois, ative o efeito apropriado;\r\n● 1: Adicione 1 card "Nemleria" do seu Cemitério à sua mão.\r\n● 2: Qualquer dano que você sofrer neste turno é diminuído pela metade.\r\n● 3: Envie para o Cemitério 1 monstro Besta de Nível 10 que você controla e, se isso acontecer, até o final deste turno, negue os efeitos de todos os monstros com a face para cima que seu oponente controla atualmente.	\r\nVocê só pode usar o efeito de "Nemleria Repeter" uma vez por turno.','\r',char(13)),'\n',char(10)),'1 card: Adicione à sua mão 1 card "Nemleria" do seu Cemitério','2 cards: Neste turno, todo o dano que você sofre é reduzido pela metade','3 cards: Negue os efeitos de todos os monstros com a face para cima que seu oponente controla','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33503878,'Script do Abismo - História Dramática',replace(replace('Escolha 1 Monstro Pêndulo "Ator do Abismo" que você controla; Invoque por Invocação-Especial 1 monstro "Ator do Abismo" do seu Deck com um nome diferente e, depois, coloque o monstro alvo na sua Zona de Pêndulo ou destrua-o. \r\nSe este card Baixado sob o controle do seu dono for destruído por um efeito de card do oponente e você tiver um Monstro Pêndulo "Ator do Abismo" com a face para cima no seu Deck Adicional: você pode devolver até 2 cards no campo para a mão. \r\nVocê só pode ativar 1 "Script do Abismo - História Dramática" por turno.','\r',char(13)),'\n',char(10)),'','','Colocar na Zona de Pêndulo','Destruir','','','','','','','','','','','','');
INSERT INTO texts VALUES(33506331,'Cubo Translúcido',replace(replace('Você não é afetado pelos efeitos de "Mundo Translúcido". \r\nDurante sua Fase Principal, você pode Invocar por Invocação-Normal 1 monstro que mencione "Mundo Translúcido", em adição à sua Invocação-Normal/Baixar (padrão). \r\n(Você só pode se aproveitar deste efeito uma vez por turno.) \r\nSe este card com a face para cima sob o controle do seu dono deixar o campo devido a um card do oponente: você pode Invocar por Invocação-Especial 1 monstro que mencione "Mundo Translúcido" do seu Deck.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33508719,'Jarro Metamórfico','VIRE: Os dois duelistas descartam tantos cards quanto possível de suas mãos e, depois, cada duelista compra 5 cards.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33537328,'Imortal Terrestre Cusillu',replace(replace('Só pode haver 1 monstro "Imortal Terrestre" no campo. \r\nSe não houver Magias de Campo com a face para cima no campo, destrua este card. \r\nOs monstros do seu oponente não podem escolher este card como alvo de ataques. \r\nEste card pode atacar diretamente seu oponente. \r\nSe este card seria destruído em batalha, em vez disso, você pode oferecer como Tributo 1 outro monstro e, se isso acontecer, diminua pela metade os PV do seu oponente.','\r',char(13)),'\n',char(10)),'Usar o efeito de "Imortal Terrestre Cusillu" em vez de ser destruído?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33541430,'Flor Cardian Luabservar Flores',replace(replace('1 Regulador + 2 monstros não-Reguladores	\r\nUma vez por turno, durante sua Fase Principal: você pode comprar 1 card e, se isso acontecer, mostre-o e, depois, se era um monstro "Flor Cardian", você pode Invocá-lo por Invocação-Especial, ignorando suas condições de Invocação, e ele pode atacar diretamente neste turno. \r\nSe você ativou este efeito, pule a Fase de Compra do seu próximo turno. \r\nQuando este card for usado como Matéria Sincro, você pode considerá-lo e todas as outras Matérias Sincro (que tenham um Nível) como monstros de Nível 2.','\r',char(13)),'\n',char(10)),'Comprar','Invocação Especial?','Considerar todos os monstros Matéria Sincro como monstros de Nível 2?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33543890,'Drytron Beta Rastaban',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial com o efeito de um card "Drytron". \r\nVocê pode oferecer como Tributo 1 outro monstro "Drytron" ou 1 Monstro de Ritual, da sua mão ou do campo; Invoque este card por Invocação-Especial da sua mão ou do Cemitério em Posição de Defesa e, depois, você pode devolver 1 dos seus monstros "Drytron" banidos para o Cemitério. \r\nVocê não pode Invocar monstros por Invocação-Especial no turno em que ativar este efeito, exceto monstros que não podem ser Invocados por Invocação-Normal/Baixados. \r\nVocê só pode usar este efeito de "Drytron Beta Rastaban" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Retornar ao Cemitério um monstro banido?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33545259,'Guerreiros Antigos - Ambicioso Cao De',replace(replace('Enquanto você controlar outro monstro "Guerreiros Antigos", seu oponente não pode escolher este card como alvo de efeitos de card e, além disso, ele não pode ser destruído pelos efeitos de card do seu oponente. \r\nVocê só pode usar cada um dos seguintes efeitos de "Guerreiros Antigos - Ambicioso Cao De" uma vez por turno.\r\n● Se um ou mais cards que seu oponente controla forem destruídos em batalha ou por um efeito de card: você pode enviar 1 outro card da sua mão ou do campo para o Cemitério; Invoque este card por Invocação-Especial da sua mão.\r\n● Quando este card destruir um monstro do oponente em batalha e enviá-lo para o Cemitério: você pode Invocar esse monstro por Invocação-Especial no seu campo em Posição de Defesa.','\r',char(13)),'\n',char(10)),'Invocar este card por Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33550694,'Portal de Fusão','Durante a Fase Principal: o duelista do turno pode Invocar por Invocação-Fusão 1 Monstro de Fusão do Deck Adicional dele, banindo as Matérias de Fusão mencionadas nele da sua mão ou do campo.','Invocação Fusão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33551032,'Terror Umbral Malformado',replace(replace('Quando este card for destruído em batalha e enviado para o Cemitério enquanto estiver atacando um monstro: você pode Invocar por Invocação-Especial 2 monstros "Terror Umbral" do seu Deck. \r\nVocê só pode usar o efeito de "Terror Umbral Malformado" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33574806,'Escuridão, o HERÓI do Elemento',replace(replace('1 monstro "HERÓI do Elemento" + 1 monstro de TREVAS	\r\nDeve ser Invocado por Invocação-Fusão. \r\nGanha 100 de ATK para cada monstro "HERÓI do Elemento" no seu Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33578406,'Espada Bambu Original',replace(replace('O monstro equipado ganha 0 de ATK. \r\nQuando o monstro equipado causar dano de batalha em um ataque direto: você pode destruir todos os monstros que seu oponente controla. \r\nVocê pode enviar este card equipado para o Cemitério; equipe 1 Magia de Equipamento "Espada Bambu" do seu Deck a 1 monstro com a face para cima no campo, exceto "Espada Bambu Original".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33599853,'Ritual da Luz e das Trevas',replace(replace('Este card pode ser usado para Invocar por Invocação-Ritual "Mago do Caos Negro - Caos das Trevas" ou "Soldado do Lustro Negro - Soldado da Luz e das Trevas". \r\nVocê também deve oferecer como Tributo monstros da sua mão ou do campo e/ou banir monstros do seu Cemitério, cuja soma dos Níveis seja igual ou exceda seu Nível. \r\nSe este card estiver no seu Cemitério: você pode adicionar este card e 1 card que mencione "Ritual da Luz e das Trevas" do seu Cemitério à sua mão. \r\nVocê só pode usar este efeito de "Ritual da Luz e das Trevas" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar','Efeito de recuperação','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33609093,'Saga dos Guerreiros Antigos - Flechas Emprestadas',replace(replace('Você pode escolher 1 monstro com a face para cima que seu oponente controla e 1 monstro "Guerreiros Antigos" que você controla; até o final deste turno, diminua pela metade o ATK desse monstro do oponente e, se isso acontecer, adicione esse ATK perdido ao seu monstro (mesmo que este card deixe o campo). \r\nSe este card for enviado para o Cemitério enquanto você controlar monstros "Guerreiros Antigos" com 2 ou mais Atributos diferentes: você pode colocar 1 Magia/Armadilha Contínua "Guerreiros Antigos" da sua mão ou do Deck, com a face para cima no seu campo, exceto "Saga dos Guerreiros Antigos - Flechas Emprestadas". \r\nVocê só pode usar cada efeito de "Saga dos Guerreiros Antigos - Flechas Emprestadas" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33609262,'Tenacidade dos Monarcas',replace(replace('Revele 1 monstro na sua mão com 2400 de ATK/1000 de DEF, ou 2800 de ATK/1000 de DEF; adicione 1 Magia/Armadilha "Monarca" do seu Deck à sua mão, exceto "Tenacidade dos Monarcas". \r\nVocê só pode ativar 1 "Tenacidade dos Monarcas" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33611061,'Bujinunidade',replace(replace('Se você não controlar nenhum outro card e tiver pelo menos 1 outro card na sua mão: embaralhe todos os monstros "Bujin" do Tipo Besta-Guerreira do seu Cemitério no Deck (mín. 1) e, se isso acontecer, envie toda a sua mão para o Cemitério (mín. 1) e, depois, você pode adicionar até 3 monstros "Bujin" do Tipo Besta-Guerreira com nomes diferentes do seu Deck à sua mão. \r\nVocê só pode ativar 1 "Bujinunidade" por turno.','\r',char(13)),'\n',char(10)),'Escolher outro monstro Besta-Guerreira cujo nome contenha "Bujin"?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33621868,'Giganto','Uma bola de aço massiva que arrasta tudo em seu caminho.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33622465,'Pelotão de Primeiros Socorros',replace(replace('Escolha 1 Monstro Normal no seu Cemitério; adicione-o à sua mão. \r\nQuando um Monstro Normal for destruído em batalha: você pode Invocar este card por Invocação-Especial do seu Cemitério em Posição de Defesa como um Monstro Normal (Tipo Guerreiro/TERRA/Nível 3/ATK 1200/DEF 400).	\r\n(Este card NÃO é considerado como um Card de Armadilha.) \r\nVocê só pode usar este efeito de "Pelotão de Primeiros Socorros" uma vez por turno. \r\nSe Invocado desta forma, bana este card quando ele deixar o campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33652635,'Besta Gladiadora Domiciano',replace(replace('"Besta Gladiadora Vespasio" + 2 monstros "Besta Gladiadora"	\r\nPrimeiro deve ser Invocado por Invocação-Especial (do seu Deck Adicional) ao embaralhar os cards acima que você controla no Deck. \r\n(Você não usa "Polimerização".) \r\nUma vez por turno, quando seu oponente ativar um efeito de monstro (Efeito Rápido): você pode negar a ativação e, se isso acontecer, destrua-o. \r\nVocê seleciona os alvos dos ataques do seu oponente. \r\nNo final da Fase de Batalha, se este card batalhou: você pode devolver este card para o Deck Adicional; Invoque por Invocação-Especial 1 monstro "Besta Gladiadora" do seu Deck.','\r',char(13)),'\n',char(10)),'Negar a ativação e destruir','Retornar ao Deck e Invocar por Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33655493,'Belial - Marquês da Escuridão','Seu oponente não pode escolher os monstros com a face para cima que você controla, exceto "Belial - Marquês da Escuridão", como alvo de um ataque ou de efeitos de Magias/Armadilhas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33656832,'Mago Acrobata',replace(replace('Escala de Pêndulo = 2\r\n[ Efeito de Pêndulo ]\r\nQuando um ou mais monstros que você controla forem destruídos por um efeito de card (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua Zona de Pêndulo. \r\nVocê só pode usar este efeito de "Mago Acrobata" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe a ativação de um Card de Magia/Armadilha for negada (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão. \r\nQuando este card for destruído em batalha: você pode colocar este card na sua Zona de Pêndulo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33665663,'Formação de Fogo - Kaiyo',replace(replace('Durante o turno em que este card for ativado, se um monstro do Tipo Besta-Guerreira que você controla atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente. \r\n(Isso se aplica mesmo que este card deixe o campo.) \r\nTodos os monstros do Tipo Besta-Guerreira que você controla ganham 300 de ATK.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33676146,'Bode Expiatório de Fuga',replace(replace('Quando seu oponente ativar um card ou efeito que escolha como alvo um ou mais monstros que você controla, exceto uma Ficha: você pode oferecer 1 monstro como Tributo; Invoque por Invocação-Especial 1 "Ficha de Bode Expiatório de Fuga" (Besta/TERRA/Nível 1/ATK 0/DEF 0) em Posição de Defesa. \r\nSe um ou mais monstros que não são Fichas que você controla seriam destruídos em batalha ou por um efeito de card, em vez disso, você pode destruir 1 Ficha na sua Zona de Monstros.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33676147,'Ficha de Bode Expiatório de Fuga','Invocado por Especial com o efeito "Bode Expiatório de Fuga".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33691040,'Prágtico','"Trakodonte" + "Víbora Flamejante"','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33695750,'Des Mosquito',replace(replace('Quando este card for Invocado por Invocação-Normal ou Especial: coloque 2 marcadores sobre ele. \r\nEle ganha 500 de ATK para cada um desses marcadores. \r\nSe este card seria destruído em batalha, em vez disso, remova 1 desses marcadores.','\r',char(13)),'\n',char(10)),'Colocar um marcador','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33698022,'Dragão do Luar da Rosa Negra',replace(replace('1 Regulador + 1+ não-Reguladores	\r\nSe este card for Invocado por Invocação-Especial, ou se um ou mais monstros de Nível 5 ou mais forem Invocados por Invocação-Especial no campo do seu oponente: escolha 1 monstro Invocado por Invocação-Especial que seu oponente controla; devolva o alvo para a mão. \r\nVocê só pode usar este efeito de "Dragão do Luar da Rosa Negra" uma vez por turno.','\r',char(13)),'\n',char(10)),'Retornar para a mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33725002,'V Salamandra',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode escolher 1 monstro "Utopia" no seu Cemitério; Invoque o alvo por Invocação-Especial. \r\nVocê pode escolher 1 "Número C39: Raio V Utopia" que você controla; equipe este monstro que você controla ao alvo. \r\nUma vez por turno, enquanto este card estiver equipado a um monstro: você pode desassociar 1 Matéria Xyz do monstro equipado; negue os efeitos do monstro equipado (mesmo depois que este card deixar o campo ou que o monstro não possa mais ser afetado por efeitos de card) e, se isso acontecer, destrua todos os monstros que seu oponente controla e, se isso acontecer, cause 1000 de dano ao seu oponente para cada monstro destruído por este efeito.','\r',char(13)),'\n',char(10)),'Invocação Especial','Equipar','Destrua e cause dano','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33725271,'Recarga Vulcânica','Devolva até 3 Cards de Monstro "Vulcânico(a)" do seu Cemitério para o seu Deck.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33731070,'Beiige, Vanguarda do Mundo Negro','Se este card for descartado para o Cemitério por um efeito de card: Invoque este card por Invocação-Especial.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33734439,'Zumbi Trípede','Uma dupla de esqueletos simpáticos, um gordo e um magro, que viajam juntos com extrema dificuldade.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33737664,'Retribuição dos Assaltantes de Túmulos','Durante cada uma das suas Standby Phases, inflija 100 pontos de dano aos Life Points do seu adversário por cada Card de Monstro do seu adversário que está removido de jogo.','Causar dano aos PV','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33744268,'Tanque Zilhão-Z',replace(replace('Se este card for Invocado por Invocação-Especial: você pode equipar 1 dos seus monstros Máquina de LUZ de Nível 4 banidos a este card como uma Magia de Equipamento e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto monstros de LUZ. \r\nUma vez por turno, você pode: escolher 1 monstro Máquina que você controla; equipe este card no alvo, OU: desequipe este card e Invoque-o por Invocação-Especial. \r\nSe o monstro equipado seria destruído em batalha ou por um efeito de card, em vez disso, destrua este card.','\r',char(13)),'\n',char(10)),'Efeito de Equipamento','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33746252,'Demônio da Sua Majestade',replace(replace('Não pode ser Invocado por Invocação-Especial. \r\nNenhum duelista pode ativar efeitos de monstro.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33750025,'Dragão Samsara',replace(replace('Pode ser considerado como 2 Tributos para a Invocação-Tributo de um monstro Dragão. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 monstro Dragão de Nível 5 ou mais no seu Cemitério; adicione-o à sua mão e, depois, imediatamente depois que este efeito resolver, você pode Invocar esse monstro por Invocação-Tributo. \r\nVocê só pode usar este efeito de "Dragão Samsara" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Tributo?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33750856,'Hackear Código',replace(replace('Monstros Link Ciberso que você controla não podem ser destruídos pelos efeitos de card do seu oponente. \r\nUma vez por turno, durante a Etapa de Batalha, se um monstro seu batalhar um monstro do oponente: você pode ativar este efeito; o ATK desse monstro do oponente se torna 0 até o final deste turno e, além disso, nessa batalha, monstros não podem ser destruídos em batalha e nenhum duelista sofre dano de batalha. \r\nEsse monstro do oponente deve estar com a face para cima no campo para ativar e resolver este efeito. \r\nQuando seu oponente ativar um card ou efeito durante uma Etapa de Dano na qual um monstro "Codificar Transmissor" seu estiver atacando: você pode banir este card do seu Cemitério; negue a ativação e, se isso acontecer, seu monstro atacante ganha 700 de ATK.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33760966,'Arthalion Caudraco',replace(replace('1 monstro "Caudraco" + 1+ monstros na mão	\r\nSe este card for Invocado por Invocação-Fusão: você pode escolher monstros no campo e/ou Cemitérios, até o número de monstros usados como matéria da mão; devolva-os para a mão. \r\nSe 2 ou mais monstros forem enviados para o Cemitério ao mesmo tempo, enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar cada efeito de "Arthalion Caudraco" uma vez por turno.','\r',char(13)),'\n',char(10)),'Retornar para a mão','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33767325,'Meteorito da Destruição','Se os Pontos de Vida do seu oponente estiverem acima de 3000: cause 1000 de dano ao seu oponente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33773528,'Precioso Parque da Diversão',replace(replace('Durante sua Fase Principal, você pode ativar 1 Armadilha "Atração" no turno em que ela for Baixada. \r\nDurante a Fase Final: você pode enviar para o Cemitério 1 Armadilha "Atração" que você controla equipada a um monstro e, depois, escolha 1 das suas Armadilhas "Atração", com um nome diferente, que estiver banida ou no seu Cemitério; Baixe esse card. \r\nVocê só pode usar cada efeito de "Precioso Parque da Diversão" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Ativar aplicando o efeito de "Precioso Parque da Diversão".','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33776734,'Kuriboh Alado LV9',replace(replace('Ative apenas como Elo de Corrente 3 ou mais (Efeito Rápido): Você pode Invocar este card por Invocação-Especial da sua mão. \r\nCards de Magia que foram ativados são banidos em vez de serem enviados para o Cemitério. \r\nO ATK/DEF deste card é igual ao número de Magias no Cemitério do seu oponente x 500. \r\nVocê só pode controlar 1 "Kuriboh Alado LV9".','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33776843,'Número C15: Engenhoca Marionete Caçador Gigante',replace(replace('3 monstros de Nível 9	\r\nUma vez por turno: você pode desassociar 1 matéria deste card e, depois, escolha 1 card que seu oponente controla; destrua-o e, se era um monstro, cause dano ao seu oponente igual ao seu ATK original.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33779875,'Lágrima, a Rainha Rikka',replace(replace('2 monstros de Nível 8	\r\nVocê pode desassociar 1 matéria deste card e, depois, escolha 1 monstro no campo; ofereça-o como Tributo. \r\nEste é um Efeito Rápido se este card tiver um monstro Planta como matéria. \r\nVocê só pode usar este efeito de "Lágrima, a Rainha Rikka" uma vez por turno. \r\nSempre que um ou mais monstros forem oferecidos como Tributo: até o final deste turno, este card ganha 200 de ATK para cada um.','\r',char(13)),'\n',char(10)),'Ofereça 1 monstro como Tributo','Aumentar ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33781156,'Mouser, Armas da Tri-Brigada',replace(replace('2 monstros Besta, Besta-Guerreira e/ou Besta Alada	\r\nSe este card for Invocado por Invocação-Link: você pode enviar 2 cards "Tri-Brigada" com nomes diferentes do seu Deck e/ou Deck Adicional para o Cemitério, exceto "Mouser, Armas da Tri-Brigada" e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto monstros Besta, Besta-Guerreira ou Besta Alada. \r\nSe este card for enviado para o Cemitério: você pode escolher 1 monstro com a face para cima no campo; coloque-o com a face para baixo em Posição de Defesa. \r\nVocê só pode usar cada efeito de "Mouser, Armas da Tri-Brigada" uma vez por turno.','\r',char(13)),'\n',char(10)),'Enviar para o Cemitério','Mudar a posição de batalha','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33782437,'Um Dia de Paz','Cada duelista compra 1 card e nenhum duelista sofre dano até o final do próximo turno do oponente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33784505,'Ladrão de Jarros',replace(replace('Você pode activar este card apenas quando "Pote da Ganância" é activado. \r\nAnule o efeito de "Pote da Ganância" e compre 1 card do seu Deck.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33787730,'Buraco de Plasma Ryzeal',replace(replace('Escolha cards com a face para cima que seu oponente controla, até o número de Monstros Xyz "Ryzeal" que você controla; destrua-os e, depois, você pode associar 1 card "Ryzeal" do seu Cemitério a 1 Monstro Xyz de Classe 4 que você controla. \r\nVocê pode banir este card do seu Cemitério; imediatamente depois que este efeito resolver, Invoque por Invocação-Xyz 1 Monstro Xyz usando monstros que você controla, incluindo um monstro "Ryzeal". \r\nVocê só pode usar cada efeito de "Buraco de Plasma Ryzeal" uma vez por turno.','\r',char(13)),'\n',char(10)),'Efeito de destruição','Invocação Xyz','Associar Matéria Xyz?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33814281,'Pacto Obscuro com Licença de Patente',replace(replace('Se seu oponente Invocar um ou mais monstros por Invocação-Especial com o mesmo tipo de card (Fusão, Sincro, Xyz ou Link) que o de um monstro "D/D/D" que você controla (exceto durante a Etapa de Dano): você pode causar 1000 de dano ao seu oponente e, além disso, enquanto este card estiver no campo, pelo resto deste turno, seu oponente não pode Invocar por Invocação-Especial monstros com o mesmo tipo de card que o desse monstro Invocado por Invocação-Especial. \r\nSe este card for enviado para o Cemitério: você pode adicionar à sua mão 1 monstro "D/D" do seu Cemitério ou 1 Monstro Pêndulo "D/D" com a face para cima do seu Deck Adicional. \r\nVocê só pode usar este efeito de "Pacto Obscuro com Licença de Patente" uma vez por turno.','\r',char(13)),'\n',char(10)),'Não pode mais Invocar por Invocação Especial Monstros Fusão','Não pode mais Invocar por Invocação Especial Monstros Sincro','Não pode mais Invocar por Invocação Especial Monstros Xyz','Não pode mais Invocar por Invocação Especial Monstros Link','','','','','','','','','','','','');
INSERT INTO texts VALUES(33823832,'Camarartista Mufflion de Fogo',replace(replace('Escala de Pêndulo = 5\r\n[ Efeito de Pêndulo ]\r\nQuando um Monstro Pêndulo que você controla for destruído em batalha: você pode Invocar este card por Invocação-Especial da sua Zona de Pêndulo.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nUma vez por turno, se um Monstro Pêndulo que você controla destruir um monstro do oponente em batalha, depois do cálculo de dano: você pode fazer com que esse monstro que você controla ganhe 200 de ATK até o final da Fase de Batalha e, se isso acontecer, ele pode realizar um segundo ataque em seguida.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33833230,'Enguia-Foca do Mar Camarartista',replace(replace('Escala de Pêndulo = 3\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno: você pode escolher 1 monstro com a face para cima que seu oponente controla; esse monstro com a face para cima tem seus efeitos negados até o final deste turno (mesmo que este card deixe o campo).\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nQuando este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 Card de Magia/Armadilha que seu oponente controla; esse card Baixado não pode ser ativado neste turno. \r\nNenhum duelista pode ativar cards ou efeitos em resposta à ativação deste efeito.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33837653,'Tenma, a Estrela Celeste',replace(replace('Se somente seu oponente controlar um monstro, ou se você controlar um monstro de TERRA, você pode Invocar este card por Invocação-Normal sem oferecer Tributo. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode Invocar por Invocação-Especial 1 monstro Guerreiro de TERRA de Nível 5 da sua mão. \r\nVocê só pode usar este efeito de "Tenma, a Estrela Celeste" uma vez por turno. \r\nUma vez por turno, quando seu oponente ativar um card ou efeito que escolha como alvo um monstro Guerreiro que você controla (Efeito Rápido): você pode fazer com que este card perca exatamente 500 de ATK e, se isso acontecer, negue a ativação e, se isso acontecer, destrua esse card.','\r',char(13)),'\n',char(10)),'Invocação Normal sem Tributo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33846209,'Centelha de Gêmeos','Ofereça como Tributo 1 monstro Gêmeos de Nível 4 com a face para cima e, depois, escolha 1 card no campo; destrua-o e, se isso acontecer, compre 1 card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33854624,'Bistial Magnamhut',replace(replace('Você pode escolher 1 monstro de LUZ ou de TREVAS em qualquer Cemitério; bana-o e, se isso acontecer, Invoque este card por Invocação-Especial da sua mão. \r\nEste é um Efeito Rápido se seu oponente controlar um monstro. \r\nSe este card for Invocado por Invocação-Especial: você pode ativar este efeito; durante a Fase Final deste turno, adicione 1 monstro Dragão do seu Deck ou Cemitério à sua mão, exceto "Bistial Magnamhut". \r\nVocê só pode usar cada efeito de "Bistial Magnamhut" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33866130,'Falésia de Naturia','Quando este card for enviado do campo para o Cemitério: você pode Invocar por Invocação-Especial 1 monstro "Naturia" de Nível 4 ou menos do seu Deck em Posição de Ataque.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33872334,'Gearlâmina Fênix',replace(replace('Só pode ser equipado a um monstro Guerreiro ou de FOGO. \r\nEle ganha 300 de ATK. \r\nNo final da Etapa de Dano, se o monstro equipado atacou: você pode enviar este card para o Cemitério; durante esta Fase de Batalha, cada um dos seus monstros Guerreiro e monstros de FOGO pode realizar um segundo ataque. \r\nSe este card for enviado para o Cemitério, ou banido, para ativar um efeito de monstro: você pode adicionar este card à sua mão. \r\nVocê só pode usar este efeito de "Gearlâmina Fênix" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33875961,'Catapultador Sombrio',replace(replace('Uma vez por turno, durante sua Fase de Apoio, se este card estiver em Posição de Defesa: coloque 1 marcador neste card. \r\nVocê pode banir cards no seu Cemitério igual ao número de marcadores neste card e, depois, escolha esse número de Magias/Armadilhas no campo; destrua-as e, depois, remova todos os marcadores deste card.','\r',char(13)),'\n',char(10)),'Colocar um marcador','Destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33878367,'Lagrimentiara Pesar',replace(replace('Invoque por Invocação-Especial 1 monstro "Lagrimentiara" ou "Visas Starfrost" do seu Deck ou Cemitério e, depois, envie 1 monstro que você controla para o Cemitério, com o mesmo Tipo ou Atributo que esse monstro Invocado por Invocação-Especial. \r\nSe este card for enviado para o Cemitério por um efeito de card: você pode escolher 1 das suas Armadilhas "Lagrimentiara" banidas; adicione-a à sua mão. \r\nVocê só pode usar 1 efeito de "Lagrimentiara Pesar" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33878931,'Togex','Um monstro ágil que rola para atacar seus oponentes.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33883834,'Escudeiro de Shien','Durante o cálculo de dano, no turno de qualquer duelista, se um monstro "Seis Samurai" que você controla batalhar: Você pode enviar este card da sua mão para o Cemitério; esse monstro não pode ser destruído em batalha neste turno.','Não pode ser destruído em batalha','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33897356,'Disparocodificar Transmissor',replace(replace('2+ monstros Ciberso	\r\nNo começo da sua Fase de Batalha: você pode ativar este efeito; nesta Fase de Batalha, este card pode realizar ataques contra os monstros do seu oponente, até o número de monstros para os quais este card apontar atualmente +1, mas neste turno, quando ele atacar o último monstro do seu oponente, este card perde 400 de ATK apenas durante esse cálculo de dano. \r\nNo final de cada Fase de Batalha: você pode comprar cards igual ao número de monstros que este card destruiu em batalha neste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33900648,'Mundo Translúcido',replace(replace('Uma vez por turno, durante sua Fase Final, pague 500 PV ou destrua este card. \r\nCada duelista recebe efeitos, dependendo dos Atributos de monstro que eles controlam.\r\n● LUZ: Duele com sua mão revelada o tempo todo.\r\n● TREVAS: Se você controlar 2 ou mais monstros, você não pode declarar um ataque.\r\n● TERRA: Durante sua Fase de Apoio, destrua 1 monstro com a face para cima em Posição de Defesa que você controla.\r\n● ÁGUA: Durante sua Fase Final, descarte 1 card.\r\n● FOGO: Durante sua Fase Final, sofra 1000 de dano.\r\n● VENTO: Você deve pagar 500 PV para ativar um Card de Magia.','\r',char(13)),'\n',char(10)),'Pagar 500 PV para manter "Mundo Translúcido"?','Destruir','Descartar 1 card','Receba 1000 pontos de dano','','','','','','','','','','','','');
INSERT INTO texts VALUES(33904024,'Fragmento de Ganância',replace(replace('Sempre que você comprar um ou mais cards em sua compra normal na sua Fase de Compra, coloque 1 Marcador de Ganância neste card. \r\nVocê pode enviar este card com 2 ou mais Marcadores de Ganância para o Cemitério; compre 2 cards.','\r',char(13)),'\n',char(10)),'Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33907039,'Mapa de Piri Reis',replace(replace('No começo da sua Fase Principal 1: adicione 1 monstro com 0 de ATK do seu Deck à sua mão, mas diminua seus PV pela metade. \r\nDepois de adicioná-lo à sua mão, até o final do próximo turno depois que este card resolver, você não pode ativar os efeitos do monstro adicionado ou os efeitos de cards com o nome dele, até que você Invoque esse monstro ou um card com o nome dele por Invocação-Normal.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33909817,'Princesaduende Silvestre',replace(replace('2 monstros de Nível 1	\r\nVocê pode desassociar 1 Matéria Xyz deste card; escave o card do topo do seu Deck e, se for uma Magia/Armadilha, adicione-a à sua mão. \r\nCaso contrário, envie-a para o Cemitério. \r\nVocê pode enviar 1 outro monstro Planta da sua mão ou com a face para cima no seu campo para o Cemitério e, depois, escolher 1 monstro "Silvestre" no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Princesaduende Silvestre" uma vez por turno.','\r',char(13)),'\n',char(10)),'Escave cards do seu Deck','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33911264,'Disruptor do Vento Solar',replace(replace('Se você não controlar nenhum monstro, você pode Invocar este card por Invocação-Especial (da sua mão), mas seu ATK e DEF originais são diminuídos pela metade. \r\nDurante cada uma de suas Fases de Apoio: aumente em 1 o Nível deste card. \r\nSó pode haver 1 "Disruptor do Vento Solar" no campo.','\r',char(13)),'\n',char(10)),'Aumentar o Nível','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33918636,'Samurai Superpesado Espantalho',replace(replace('1 monstro "Samurai Superpesado"	\r\nNão pode ser usado como Matéria Link. \r\nEnquanto você não tiver Magias/Armadilhas no seu Cemitério, você não sofre dano de batalha dos ataques que envolvem este card. \r\nSe você não tiver Magias/Armadilhas no seu Cemitério: você pode descartar 1 monstro e, depois, escolha 1 monstro "Samurai Superpesado" no seu Cemitério; Invoque-o por Invocação-Especial em uma zona sua para a qual este card apontar, em Posição de Defesa. \r\nVocê só pode usar este efeito de "Samurai Superpesado Espantalho" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33925864,'Big Bang Kashtira',replace(replace('Se um Monstro Xyz "Kashtira" estiver no campo e um duelista controlar 2 ou mais monstros: ele deve banir monstros que ele controla, com a face para baixo, até controlar apenas 1 monstro. \r\nSe este card for banido: você pode escolher 1 Monstro Xyz "Kashtira" que você controla; adicione à sua mão 1 dos seus monstros "Kashtira" associados a ele e, depois, você pode Invocar esse monstro por Invocação-Especial da sua mão. \r\nVocê só pode usar cada efeito de "Big Bang Kashtira" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33945211,'Marincesa Basilalima',replace(replace('Se um ou mais monstros que você controla seriam destruídos por um efeito de card, em vez disso, você pode banir este card do seu Cemitério. \r\nVocê só pode usar cada um dos seguintes efeitos de "Marincesa Basilalima" uma vez por turno.\r\n● Você pode banir 1 Armadilha "Marincesa" do seu Cemitério; adicione 1 Armadilha "Marincesa" com um nome diferente do seu Deck à sua mão.\r\n● Se este card for banido: você pode escolher 1 monstro com a face para cima que você controla; ele ganha 600 de ATK.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33950246,'Comando Real','Os efeitos de monstros de Virar não podem ser ativados e, além disso, os efeitos deles são negados.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33951077,'Super Leão-de-Guerra','Você pode Invocar este card por Invocação-Ritual com "Ritual do Leão-de-Guerra".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33955120,'Bruxa da Rosa Raivosa',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nMonstros Planta que você controla não podem ser destruídos por efeitos de card. \r\nVocê só pode usar cada um dos seguintes efeitos de "Bruxa da Rosa Raivosa" uma vez por turno. \r\nSe este card for Invocado por Invocação-Sincro: você pode enviar até 1 monstro Planta cada do seu Deck e Deck Adicional para o Cemitério e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto Monstros Sincro. \r\nSe um ou mais cards no campo forem destruídos por um efeito de card enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Enviar para o Cemitério','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33964637,'Seis Samurai Secretos - Rihan',replace(replace('3 monstros "Seis Samurai" com Atributos diferentes	\r\nPrimeiro deve ser Invocado por Invocação-Especial (do seu Deck Adicional) ao enviar os cards acima que você controla para o Cemitério. \r\n(Você não usa "Polimerização".) \r\nNão pode ser usado como Matéria de Fusão. \r\nUma vez por turno: você pode banir 1 card "Seis Samurai" da sua mão ou com a face para cima do seu campo e, depois, escolher 1 card no campo; bana-o. \r\nSe um ou mais monstros "Seis Samurai" que você controla seriam destruídos em batalha ou por um efeito de card, em vez disso, você pode banir este card do seu Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33970665,'Entranhas de Aço',replace(replace('Selecione 3 monstros "Restolhos" no seu Cemitério. \r\nSeu oponente pega 1 deles, você o Invoca por Invocação-Especial no lado do campo de qualquer duelista e remove o restante de jogo.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial para o seu Campo','Invocar por Invocação Especial para o Campo do seu oponente','Escolha 3 monstros cujo nome contenha "Restolhos"','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33971095,'Pesadelo Vendorror',replace(replace('Uma vez por turno: você pode oferecer como Tributo 1 ou mais monstros "Vendorror" da sua mão e/ou do campo e, depois, escolher 1 monstro com a face para cima que você controla; até o final deste turno, aumente o Nível dele pelo número de monstros oferecidos como Tributo. \r\nQuando um Monstro de Ritual "Vendorror" atacante seu destruir um monstro do oponente em batalha: você pode fazer com que seu monstro ganhe 1000 de ATK. \r\nVocê só pode usar este efeito de "Pesadelo Vendorror" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33972299,'Geogenex',replace(replace('"Controlador Genex" + 1 ou mais monstros de TERRA não-Reguladores	\r\nUma vez por turno, se você controlar um ou mais monstros "Genex" de Nível 4 ou menos com a face para cima, você pode trocar o ATK e DEF originais deste card até a Fase Final, enquanto você controlar um ou mais monstros "Genex" de Nível 4 ou menos com a face para cima.','\r',char(13)),'\n',char(10)),'Trocar ATK e DEF','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33977496,'Mil Agulhas','Quando este card, em Posição de Defesa, é atacado e o ATK do monstro atacante é menor que o DEF deste card, depois do cálculo de dano destrúa o monstro atacante.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33981008,'A Grande Torre do Livro de Magia',replace(replace('Uma vez por turno, durante sua Fase de Apoio, se você tiver um monstro do Tipo Mago no seu lado do campo ou no seu Cemitério: você pode colocar no fundo do seu Deck 1 Card de Magia "Livro de Magia" do seu Cemitério, exceto "A Grande Torre do Livro de Magia" e, depois, comprar 1 card. \r\nQuando este card em sua posse for destruído por um card do seu oponente e enviado para o seu Cemitério: você pode Invocar por Invocação-Especial 1 monstro do Tipo Mago da sua mão ou Deck cujo Nível seja menor ou igual que o número de Cards de Magia "Livro de Magia" no seu Cemitério.','\r',char(13)),'\n',char(10)),'Retornar para o Deck e depois compre 1 card','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33995387,'Regra do Herói 1: Cinco Liberdades',replace(replace('Escolha até 5 cards em quaisquer Cemitérios; bana-os. \r\nSe este card estiver no seu Cemitério, exceto no turno em que foi enviado para lá: você pode bani-lo e, depois, escolha 1 dos seus monstros "HERÓI do Elemento" banidos; Invoque-o por Invocação-Especial, ignorando suas condições de Invocação. \r\nVocê só pode usar este efeito de "Regra do Herói 1: Cinco Liberdades" uma vez por turno.','\r',char(13)),'\n',char(10)),'Banir','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34001672,'Motoqueiro Goblin Grande Gabonga',replace(replace('2 monstros de Nível 3	\r\nSe este card for Invocado por Invocação-Xyz: você pode adicionar 1 monstro "Goblin" do seu Deck à sua mão. \r\nSe matéria for desassociada de um ou mais monstros no campo (exceto durante a Etapa de Dano): você pode escolher 1 monstro com a face para cima no campo, exceto este card; associe-o a este card como matéria. \r\nDurante a Fase Final: você pode associar 1 monstro "Goblin" do seu Deck a este card como matéria. \r\nVocê só pode usar cada efeito de "Motoqueiro Goblin Grande Gabonga" uma vez por turno.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Use um monstro no campo como Matéria Xyz','Use um monstro do Deck como Matéria Xyz','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34002992,'Vida Arco-Íris','Descarte 1 card; até o final deste turno, sempre que você sofreria dano, em vez disso, ganhe essa quantidade de PV.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34004470,'O Grande Saturno',replace(replace('Não pode ser Invocado por Invocação-Especial da mão ou Deck. \r\nUma vez por turno: Você pode descartar 1 card e pagar 1000 PV; este card ganha 1000 de ATK até a Fase Final. \r\nQuando este card em sua posse for destruído por um efeito de card do seu oponente e enviado para o seu Cemitério: Ambos os duelistas sofrem dano igual ao ATK deste card no Cemitério.','\r',char(13)),'\n',char(10)),'Aumentar ATK','Causar dano','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34010534,'Cinet Otimização',replace(replace('Se um monstro "Codificar Transmissor" seu batalhar, seu oponente não pode ativar cards ou efeitos até o final da Etapa de Dano. \r\nDurante sua Fase Principal, você pode: imediatamente depois que este efeito resolver, Invoque por Invocação-Normal 1 monstro Ciberso e, além disso, você não pode Invocar monstros por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto monstros Ciberso (mesmo que este card deixe o campo). \r\nVocê só pode usar este efeito de "Cinet Otimização" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34016756,'Riryoku',replace(replace('Escolha 2 monstros com a face para cima no campo; diminua pela metade o ATK de 1 monstro e, se isso acontecer, adicione esse ATK perdido ao outro monstro. \r\nEsses efeitos duram até o final deste turno.','\r',char(13)),'\n',char(10)),'Escolha o monstro cujo ATK é reduzido pela metade','Escolha o monstro cujo ATK aumentará','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34022290,'Guardião Eatos',replace(replace('Se você não tiver monstros no seu Cemitério, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê pode enviar para o Cemitério 1 das suas Magias de Equipamento equipados a este card e, depois, escolha até 3 monstros no Cemitério do seu oponente; bana os alvos e, se isso acontecer, até o final deste turno, este card ganha 500 de ATK para cada monstro banido por este efeito.','\r',char(13)),'\n',char(10)),'Banir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34022970,'Combustão Externa de Ryzeal',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) ao enviar 1 Monstro Xyz do seu Deck Adicional para o Cemitério. \r\nSe Invocado desta forma, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto Monstros Xyz de Classe 4. \r\nVocê só pode Invocar "Combustão Externa de Ryzeal" por Invocação-Especial uma vez por turno desta forma. \r\nSe este card for Invocado por Invocação-Normal ou Especial e você não controlar nenhum outro monstro com a face para cima, exceto monstros de Nível/Classe 4: você pode adicionar 1 monstro Trovão de FOGO do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Combustão Externa de Ryzeal" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial da mão','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34026662,'Evo-Milagre','Escolha 1 monstro que foi Invocado por Invocação-Especial pelo efeito de um monstro "Evoltil"; neste turno, ele não pode ser destruído em batalha ou por efeitos de card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34029630,'Pedra do Poder Negra como Azeviche',replace(replace('Ative este card ao colocar 3 Marcadores de Magia sobre ele. \r\nUma vez por turno, durante o seu turno: você pode escolher 1 outro card com a face para cima no campo sobre o qual você possa colocar um Marcador de Magia; remova 1 Marcador de Magia deste card e, se isso acontecer, coloque 1 Marcador de Magia no alvo. \r\nQuando o(s) último(s) \r\nMarcador(es) de Magia for(em) removido(s) deste card, destrua-o.','\r',char(13)),'\n',char(10)),'Usar o efeito de "Pedra do Poder Negra como Azeviche" agora?','Transferir marcadores','Escolha um card na qual colocar Marcadores de Magia','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34031284,'Imperador Ojama',replace(replace('3 monstros Besta, incluindo um monstro "Ojama"	\r\nEnquanto "Nação Ojama" estiver na Zona do Campo, este card ganha 3000 de ATK e, além disso, ele não pode ser destruído por efeitos de card. \r\nSeu oponente, em vez de você, sofre qualquer dano de batalha que você teria sofrido dos ataques contra este card. \r\nVocê pode escolher 1 monstro "Ojama" que não seja Link no seu Cemitério; Invoque-o por Invocação-Especial e, além disso, pelo resto deste turno, você não pode Invocar monstros por Invocação-Especial do Deck Adicional, exceto Monstros de Fusão. \r\nVocê só pode usar este efeito de "Imperador Ojama" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34034150,'Aranha Mãe Talhadeira',replace(replace('Se você não controlar nenhum monstro, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê pode oferecer este card como Tributo; você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto Monstros Xyz e, além disso, Invoque por Invocação-Especial até 3 "Aranha Bebê" da sua mão e/ou do Deck e, se isso acontecer, eles se tornam de Nível 5, mas não podem ser usados como matéria para uma Invocação-Xyz, exceto a Invocação-Xyz de um monstro de TREVAS. \r\nVocê só pode usar este efeito de "Aranha Mãe Talhadeira" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34041788,'Império de Endymion',replace(replace('Quando este card for ativado: adicione 1 "Regulus, o Príncipe de Endymion" ou 1 monstro que o mencione do seu Deck à sua mão e, depois, se seu oponente controlar um monstro, você pode Invocar por Invocação-Especial 1 monstro Mago da sua mão. \r\nSe um ou mais cards que você controla seriam destruídos em batalha ou por um efeito de card, em vez disso, você pode destruir 1 "Regulus, o Príncipe de Endymion" na sua mão ou no campo com a face para cima. \r\nVocê só pode usar este efeito de "Império de Endymion" uma vez por turno. \r\nVocê só pode ativar 1 "Império de Endymion" por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34047456,'Gigantesca Cruz-Trovão',replace(replace('Escolha um número de monstros no campo e/ou nos Cemitérios, igual à diferença entre seus cards banidos e os do seu oponente; bana-os e, depois, seu oponente pode Invocar por Invocação-Especial 1 monstro do Deck dele. \r\nVocê só pode ativar 1 "Gigantesca Cruz-Trovão" por turno.','\r',char(13)),'\n',char(10)),'','Invocar por Invocação Especial do Deck?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34072799,'Transpássaro Sônico',replace(replace('Você pode Invocar este card por Invocação-Ritual com "Rastreador Sônico". \r\nUma vez por turno: você pode revelar 1 Magia de Ritual na sua mão, adicionar 1 Monstro de Ritual do seu Deck à sua mão cujo nome esteja listado nesse card e, se isso acontecer, embaralhe o card revelado no Deck. \r\nUma vez por turno do oponente (Efeito Rápido): você pode enviar 1 Magia de Ritual do seu Deck para o Cemitério; este efeito se torna o efeito desse card que Invoca um monstro por Invocação-Ritual quando o card for ativado. \r\nSe este card Invocado por Invocação-Ritual for oferecido como Tributo: você pode escolher 1 card com a face para cima que seu oponente controla; negue seus efeitos até o final deste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34079868,'Master da Paz, o Verdadeiro Dracossassino',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nVocê deve Invocá-lo por Invocação-Especial (da sua mão) ao oferecer como Tributo 1 monstro "Dracossassino" e 1 monstro "Dracosuserano" e não pode ser Invocado por Invocação-Especial de nenhuma outra forma. \r\nUma vez por turno, durante o turno de qualquer duelista, quando um card ou efeito for ativado: você pode negar a ativação e, se isso acontecer, destrua esse card. \r\nSe este card sob o controle do seu dono for destruído por um card do oponente (em batalha ou por um efeito de card): você pode Invocar por Invocação-Especial 1 monstro "Dracossassino" e 1 monstro "Dracosuserano" do seu Deck.','\r',char(13)),'\n',char(10)),'Negue a ativação do efeito','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34086406,'Corrente Lavalval',replace(replace('2 monstros de Nível 4	\r\nUma vez por turno: você pode desassociar 1 Matéria Xyz deste card para ativar 1 desses efeitos;\r\n● Envie 1 card do seu Deck para o Cemitério.\r\n● Selecione 1 monstro do seu Deck e coloque-o no topo do seu Deck.','\r',char(13)),'\n',char(10)),'Ativar 1 efeito','Escolha 1 card do seu Deck; envie-o para o Cemitério.','Escolha 1 monstro do seu Deck e coloque-o no topo do seu Deck.','Escolha o monstro para colocar no topo do Deck','','','','','','','','','','','','');
INSERT INTO texts VALUES(34088136,'Inseto Supremo LV3',replace(replace('Se este card foi Invocado, por Invocação-Especial, pelo efeito de "Inseto Supremo LV1", enquanto este card permanecer no Campo, diminua o ATK de todos os monstros do seu adversário em 300 pontos. \r\nDurante as Standby Phases do seu turno, envie este card, com a face para cima, para o Cemitério para Invocar, por Invocação-Especial, o "Inseto Supremo LV5" da sua mão ou do seu Deck (exepto no turno em que este card é Invocado por Invocação-Normal, Invocação-Especial ou virado com a face para cima).','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34090915,'Marcado Reconquistado',replace(replace('Se um ou mais monstros de LUZ ou de TREVAS forem banidos (exceto durante a Etapa de Dano): você pode escolher 1 desses monstros; coloque esse monstro no fundo do Deck e, se isso acontecer, compre 1 card. \r\nVocê só pode usar este efeito de "Marcado Reconquistado" uma vez por turno. \r\nUma vez por turno, se seu oponente Invocar um monstro por Invocação-Normal ou Especial (exceto durante a Etapa de Dano): você pode escolher 1 monstro "Bistial" no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê só pode ativar este efeito de "Marcado Reconquistado" uma vez por Corrente.','\r',char(13)),'\n',char(10)),'Retornar um monstro banido e compre','Invoque por Invocação Especial 1 monstro do seu Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34093683,'Executor Revendorror',replace(replace('Você pode Invocar este card por Invocação-Ritual com qualquer Magia de Ritual "Vendorror". \r\nO nome deste card se torna "Assassino Revendorror" enquanto ele estiver no campo. \r\nEnquanto este card Invocado por Invocação-Ritual estiver no campo, seu oponente não pode escolher cards que você controla como alvo de efeitos de card, exceto este card. \r\nSe este card Invocado por Invocação-Ritual for destruído em batalha ou for destruído por um efeito de card do oponente enquanto estava na Zona de Monstros do seu dono: você pode adicionar 1 card "Vendorror" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Executor Revendorror" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34100324,'Rapariga Harpia','Uma Harpia criança que aspira voar bela e esplendidamente, mas atacar fortemente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34103656,'Lemúria, a Cidade Esquecida',replace(replace('(Este card deve ser sempre considerado como "Umi".)	\r\nTodos os monstros de ÁGUA ganham 200 de ATK/DEF. \r\nUma vez por turno, durante sua Fase Principal: você pode fazer com que todos os monstros de ÁGUA que você controla atualmente ganhem Níveis igual ao número de monstros de ÁGUA que você controla atualmente, até o final deste turno.','\r',char(13)),'\n',char(10)),'Aumentar o Nível','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34109611,'Falcos Daigusto',replace(replace('1 Regulador + 1 ou mais monstros "Gusto" não-Reguladores	\r\nQuando este card for Invocado por Invocação-Sincro: Todos os monstros "Gusto" atualmente no campo ganham 600 de ATK.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34116027,'Cavaleiro Dragunidade - Gae Dearg',replace(replace('1 Regulador Dragão + 1+ monstros Besta Alada não-Reguladores	\r\nUma vez por turno: você pode adicionar 1 monstro Dragão ou Besta Alada de Nível 4 ou menos do seu Deck à sua mão e, depois, descarte 1 monstro Dragão ou Besta Alada.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34124316,'Jarro Cibernético',replace(replace('VIRE: Destrua todos os monstros no campo e, depois, os dois duelistas revelam os 5 cards do topo dos seus Decks e, depois, Invocam por Invocação-Especial, com a face para cima em Posição de Ataque ou com a face para baixo em Posição de Defesa, todos os monstros revelados de Nível 4 ou menos e, além disso, adicionam quaisquer cards restantes às suas mãos. \r\n(Se algum dos duelistas tiver menos de 5 cards em seu Deck, ele revela tantos quanto possível.)','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34130561,'Gaia, o Cavaleiro Mágico',replace(replace('(Este card deve ser sempre considerado como um card "Gaia, o Cavaleiro Impetuoso".)	\r\nSe você não controlar nenhum monstro ou seu oponente controlar um monstro com 2300 ou mais de ATK, você pode Invocar este card por Invocação-Normal sem oferecer Tributo. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode Invocar por Invocação-Especial 1 monstro Dragão de Nível 5 da sua mão ou do Cemitério em Posição de Defesa. \r\nVocê só pode usar este efeito de "Gaia, o Cavaleiro Mágico" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Normal sem Tributo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34137269,'Hailon, o Senhor do Tempo',replace(replace('Não pode ser Invocado por Invocação-Especial do Deck. \r\nSe você não controlar nenhum monstro, você pode Invocar este card por Invocação-Normal sem oferecer Tributo. \r\nNão pode ser destruído em batalha ou por efeitos de card. \r\nVocê não sofre dano de batalha dos ataques envolvendo este card. \r\nNo final da Fase de Batalha, se este card batalhou: se você tiver menos PV que seu oponente, cause dano de batalha ao seu oponente igual à diferença. \r\nUma vez por turno, durante sua Fase de Apoio: embaralhe este card no Deck.','\r',char(13)),'\n',char(10)),'Invocação Normal sem Tributo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34143852,'Desafiante Heroico - Espada Dupla',replace(replace('Um Monstro Xyz que foi Invocado usando este card como matéria ganha este efeito.\r\n● Quando ele for Invocado por Invocação-Xyz: ele ganha 1000 de ATK.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34149150,'Brutamontes com Chifres Carnovorus',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nDurante a Fase Principal ou de Batalha, você pode (Efeito Rápido): imediatamente depois que este efeito resolver, Invoque por Invocação-Sincro 1 monstro Dinossauro usando este card que você controla. \r\nQuando um monstro declarar um ataque: você pode Invocar por Invocação-Especial 1 monstro Dinossauro da sua mão, ignorando suas condições de Invocação e, além disso, você não pode Invocar por Invocação-Especial pelo resto deste turno, exceto monstros Dinossauro. \r\nVocê só pode usar cada efeito de "Brutamontes com Chifres Carnovorus" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Sincro','Invocar por Invocação Especial da mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34149830,'Mudança Desesperada','Se um monstro com a face para cima em Posição de Ataque que você controla for destruído em batalha, durante o cálculo de dano, você pode reduzir o Dano de Batalha desta batalha a 0 e Invocar por Invocação-Especial 1 monstro do Tipo Guerreiro de Nível 4 ou menos da sua mão no final da Etapa de Dano.','O dano de batalha se torna 0','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34160055,'Mestre das Dracoespadas Flamejantes','Quando um monstro for Invocado por Invocação-Normal no seu lado do campo, exceto "Mestre das Dracoespadas Flamejantes": Você pode aumentar o Nível desse monstro em 1, e este card ganha 300 de ATK até a Fase Final.','Aumentar Nível e ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34172284,'Aron, o Rei Ogdoádico',replace(replace('Se este card estiver no seu Cemitério: você pode oferecer 2 monstros como Tributo; Invoque este card por Invocação-Especial. \r\nSe seu oponente adicionar um ou mais cards à mão dele (exceto durante a Fase de Compra ou Etapa de Dano): você pode enviar 1 card aleatório da mão dele para o Cemitério. \r\nSe um ou mais monstros que seu oponente controla forem enviados para o Cemitério (exceto durante a Etapa de Dano): você pode adicionar 1 monstro Réptil de LUZ ou de TREVAS do seu Deck ou Cemitério à sua mão, exceto "Aron, o Rei Ogdoádico". \r\nVocê só pode usar cada efeito de "Aron, o Rei Ogdoádico" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Envie para o Cemitério 1 card aleatório da mão do seu oponente','Adicione à sua mão 1 monstro Réptil do seu Deck ou do seu Cemitério','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34187685,'Ataque Duplo',replace(replace('Descarte 1 Card de Monstro da sua mão para o Cemitério. \r\nEscolha 1 monstro no seu Campo com um Nível inferior ao do monstro descartado. \r\nO monstro escolhido pode atacar duas vezes este turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34193084,'Medo do Escuro','Quando este card for enviado da sua mão ou Deck para o seu Cemitério por um efeito de card do oponente: Invoque este card por Invocação-Especial.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34198387,'Miauseclick',replace(replace('Se um Card de Magia de Campo for ativado: você pode Invocar este card por Invocação-Especial da sua mão e, depois, se cards com a face para cima estiverem nas duas Zonas do Campo, este card não pode ser destruído em batalha ou por efeitos de card neste turno. \r\nVocê só pode usar este efeito de "Miauseclick" uma vez por turno. \r\nDurante o seu turno, os efeitos do card com a face para cima na Zona do Campo do seu oponente são negados. \r\nDurante o turno do seu oponente, os efeitos do card com a face para cima na sua Zona do Campo são negados.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34206604,'Cientista Mágico',replace(replace('Pague 1000 Life Points para Invocar, por Invocação-Especial, 1 Monstro de Fusão de Nível 6 ou menos do seu Deck de Fusão. \r\nEsse Monstro de Fusão não pode atacar diretamente os Life Points do seu adversário, e é devolvido para o seu Deck de Fusão no final do turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34225426,'Lagrimentiara Perlegia',replace(replace('Monstros de Fusão e monstros "Lagrimentiara" que você controla ganham 500 de ATK. \r\nSe um monstro Aqua "Lagrimentiara" for enviado para o seu Cemitério por um efeito de card (exceto durante a Etapa de Dano): você pode enviar 1 monstro Aqua de Nível 4 ou menos do seu Deck para o Cemitério, mas se você enviou um monstro que não seja "Lagrimentiara" para o Cemitério, pelo resto deste turno você não pode ativar cards, ou os efeitos de cards, com o mesmo nome que o desse card enviado. \r\nVocê só pode usar este efeito de "Lagrimentiara Perlegia" uma vez por turno.','\r',char(13)),'\n',char(10)),'Envie para o Cemitério 1 monstro Aqua de Nível 4 ou menos do seu Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34230233,'Grapha, Senhor Dragão do Mundo Negro',replace(replace('Você pode Invocar este card por Invocação-Especial (do seu Cemitério) ao devolver 1 monstro "Mundo Negro" que você controla para a mão, exceto "Grapha, Senhor Dragão do Mundo Negro". \r\nSe este card for descartado para o Cemitério por um efeito de card: escolha 1 card que seu oponente controla; destrua o alvo e, depois, se este card foi descartado da sua mão para o seu Cemitério por um efeito de card do oponente, olhe 1 card aleatório na mão do seu oponente e, depois, se era um monstro, você pode Invocá-lo por Invocação-Especial no seu campo.','\r',char(13)),'\n',char(10)),'Destrua 1 card que seu oponente controla','Invocação Especial?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34235530,'Senhor dos Seis Samurai Lendários - Shi Em',replace(replace('1 Regulador Guerreiro + 1+ monstros "Seis Samurai" não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro: você pode adicionar 1 monstro "Seis Samurai" ou Monstro de Efeito "Shien" do seu Deck ou Cemitério à sua mão. \r\nVocê só pode usar este efeito de "Senhor dos Seis Samurai Lendários - Shi Em" uma vez por turno. \r\nUma vez por turno, quando seu oponente ativar um efeito de monstro (Efeito Rápido): você pode negar a ativação e, se isso acontecer, destrua esse card. \r\nSe este card no campo seria destruído em batalha ou por um efeito de card, em vez disso, você pode destruir 1 monstro que você controla.','\r',char(13)),'\n',char(10)),'Efeito de busca','Negar a ativação','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34236961,'Ante',replace(replace('Cada jogador escolhe 1 card da sua própria mão, em seguida, comparam o Nível dos cards escolhidos. \r\nO card com maior Nível é devolvido para a mão do jogador que o escolheu. \r\nO jogador que escolheu o card com o menor Nível recebes 1000 pontos de dano e envia o card que ele escolheu para o Cemitério. \r\nCards escolhidos que não sejam Cards de Monstro são tratados como Nível 0. \r\nSe ambos os jogadores escolheram cards com o mesmo Nível, devolva ambos os cards para a mão dos jogadores que os escolheram.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34242278,'Portador do Escudo do Nobre Cavaleiro',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode banir 1 monstro de LUZ do seu Cemitério; compre 1 card. \r\nVocê pode banir este card da sua mão ou do campo; adicione 1 monstro Besta de VENTO de Nível 6 ou menos do seu Deck à sua mão. \r\nVocê só pode usar 1 efeito de "Portador do Escudo do Nobre Cavaleiro" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34244455,'Estorno Encara Estrela',replace(replace('Este card ganha um efeito baseado na Zona de Monstros Principal em que estiver.\r\n● Mais à Esquerda: Aumente seu Nível em 4.\r\n● Mais à Direita: Aumente seu Nível em 3.\r\n● Centro: Aumente seu Nível em 2.\r\n● Outras: Aumente seu Nível em 1.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34250214,'Familiar Vampiro',replace(replace('Se este card for Invocado por Invocação-Especial: você pode pagar 500 PV; adicione 1 monstro "Vampiro(a)" do seu Deck à sua mão, exceto "Familiar Vampiro". \r\nSe este card estiver no seu Cemitério: você pode enviar 1 card "Vampiro(a)" da sua mão ou do campo com a face para cima para o Cemitério; Invoque este card por Invocação-Especial, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar cada efeito de "Familiar Vampiro" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34251483,'Esquadrão de Pilhagem Goblin',replace(replace('Quando este card declarar um ataque, seu oponente não pode ativar cards ou efeitos. \r\nSe este card atacar, ele é mudado para Posição de Defesa no final da Fase de Batalha, e sua posição de batalha não pode ser alterada até a Fase Final do seu próximo turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34257001,'Guerreiro de Corrida','Se este card atacar, ele ganha 1200 de ATK apenas durante a Etapa de Dano.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34267821,'Artefato Lança do Destino',replace(replace('Você pode Baixar este card da sua mão na sua Zona de Magias & Armadilhas como uma Magia. \r\nDurante o turno do seu oponente, se este card Baixado na Zona de Magias & Armadilhas for destruído e enviado para o seu Cemitério: Invoque-o por Invocação-Especial. \r\nDurante o turno do seu oponente (Efeito Rápido): você pode oferecer este card como Tributo da sua mão ou do campo com a face para cima; nenhum duelista pode banir cards pelo resto deste turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Nenhum duelista pode banir cards','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34290067,'Tubarão Corrosivo','Um tubarão zumbi que pode lançar sua praga letal com uma magia.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34293667,'Barreira de Gelo',replace(replace('Quando um ataque for declarado envolvendo um monstro do seu oponente: mude o ATK desse monstro do oponente para 0, negue seus efeitos e, além disso, ele não pode mudar sua posição de batalha. \r\nVocê pode banir este card do seu Cemitério; envie 1 monstro de ÁGUA de Nível 5 ou mais do seu Deck para o Cemitério e, depois, você pode adicionar 1 monstro de ÁGUA do seu Cemitério à sua mão e, além disso, até o final do seu próximo turno depois que este efeito resolver, você não pode Invocar monstros por Invocação-Especial, exceto monstros de ÁGUA. \r\nVocê só pode usar este efeito de "Barreira de Gelo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Adicionar à sua mão 1 monstro de ÁGUA do seu Cemitério?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34294855,'Maldição do Vampiro',replace(replace('Quando este card for destruído em batalha e enviado para o Cemitério: você pode pagar 500 PV; Invoque-o por Invocação-Especial durante a Fase de Apoio do próximo turno. \r\nSe isso acontecer: ele ganha 500 de ATK.','\r',char(13)),'\n',char(10)),'Invocação Especial','Aumentar ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34298391,'Ler Mente',replace(replace('(Temporariamente indisponível)	\r\nEnquanto você tem um card "Toon" no seu campo ou Cemitério, seu oponente deve jogar com sua mão revelada, você também pode ver seus cards Baixados a qualquer momento.\r\nSe você tem um monstro "Toon" e uma Magia "Toon" no seu campo e/ou Cemitério: você pode declarar o nome de 1 card que não foi ativado e que não ativou seus efeitos, neste Corrente; negue os efeitos ativados dos cards com aquele nome original até o final deste turno enquanto este card está no campo com a face para cima. \r\nVocê só pode usar este efeito de "Ler Mente" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Declarar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34302287,'Batalha Fantasma Espiral',replace(replace('Se todos os monstros que você controla forem Monstros Normais (mín. 1): escolha 1 card que seu oponente controla; destrua-o. \r\nSe "Umi" estiver no campo, você pode ativar este card da sua mão. \r\nVocê pode banir este card do seu Cemitério e, depois, escolher 1 Monstro Normal que você controla; equipe esse Monstro Normal com todos os Cards de Magia de Equipamento "Fantasma Espiral" que você controla que podem ser equipados a ele.','\r',char(13)),'\n',char(10)),'','Ativar aplicando o efeito de "Batalha Fantasma Espiral".','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34314989,'Mago Ilusionista Sem Rosto de Olhos Negros',replace(replace('Você pode descartar este card, então ative 1 desses efeitos (mas você só pode usar cada um desses efeitos de "Mago Ilusionista Sem Rosto de Olhos Negros" uma vez por turno);\r\n● Coloque 1 "Ler Mente" da sua mão ou Deck no seu campo com a face para cima.\r\n● Adicione 1 outro monstro do seu Cemitério à sua mão que mencione "Mundo Toon", então você pode Invoca-lo por Invocação-Especial, ignorando suas condições de Invocação.	\r\nSe este card batalhar com um monstro, nenhum pode ser destruído naquela batalha.','\r',char(13)),'\n',char(10)),'Descartar','Colocar um Card de Armadilha','Recuperar um monstro','Invocação Especial?','','','','','','','','','','','','');
INSERT INTO texts VALUES(34318086,'Pequena Maga Limão',replace(replace('Uma vez por turno: você pode oferecer como Tributo 1 monstro "Pequena Maga", exceto "Pequena Maga Limão"; adicione 1 monstro do Tipo Mago do seu Deck à sua mão. \r\nUma vez por turno, se este card for alvo de um ataque: você pode Invocar por Invocação-Especial 1 monstro do Tipo Mago da sua mão, mas seus efeitos (se houverem) são negados e, depois, mude o alvo do ataque para ele e, se isso acontecer, o ATK do monstro atacante se torna metade do seu ATK atual.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34320307,'Vaso Vivo','Um vaso vivo que morde os inimigos e os cega com uma explosão de pólen de sua flor.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34323367,'Camaramágico Dançarina de Água',replace(replace('Escala de Pêndulo = 2\r\n[ Efeito de Pêndulo ]\r\nSe você controlar um monstro "Camaramágico": você pode Invocar este card por Invocação-Especial. \r\nQuando um monstro declarar um ataque: você pode escolher 1 monstro em Posição de Ataque no campo; coloque-o em Posição de Defesa. \r\nVocê só pode usar cada efeito de "Camaramágico Dançarina de Água" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe este card for Invocado por Invocação-Pêndulo: você pode adicionar 1 "Polimerização" do seu Deck ou Cemitério à sua mão. \r\nVocê só pode usar este efeito de "Camaramágico Dançarina de Água" uma vez por turno. \r\nSe este card no campo for destruído em batalha ou por um efeito de card: você pode escolher 1 monstro em Posição de Ataque no campo; coloque-o em Posição de Defesa.','\r',char(13)),'\n',char(10)),'Invocação Especial','Alterar a posição de batalha','Adicionar "Polimerização/Fusão" à mão','Alterar a posição de batalha','','','','','','','','','','','','');
INSERT INTO texts VALUES(34325937,'Unificação dos Senhores Cúbicos',replace(replace('Invoque por Invocação-Fusão 1 Monstro de Fusão "Cúbico(a)" do seu Deck Adicional, usando monstros da sua mão ou do campo como Matérias de Fusão. \r\nSe um monstro "Cúbico(a)" com a face para cima for destruído em batalha ou deixar o campo: você pode banir este card do seu Cemitério; Invoque por Invocação-Especial 1 monstro "Cúbico(a)" de Nível 4 ou menos da sua mão ou do Deck, ignorando suas condições de Invocação e, se isso acontecer, ele não pode ser destruído em batalha ou por efeitos de card neste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34334692,'Corvo Ritual','Se você Invocar por Invocação-Ritual exatamente 1 Monstro de Ritual de TREVAS com um efeito de card que requer o uso de monstros, este card pode ser usado como todo o requisito.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34351849,'Campo de Força dos Sapos',replace(replace('Ative apenas quando um monstro "Sapo" com a face para cima que você controla for selecionado como alvo de um ataque. \r\nDestrua todos os monstros em Posição de Ataque que seu oponente controla.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34358408,'Djinn, o Oficiante de Rituais',replace(replace('Quando você Invocar um monstro por Invocação-Ritual, você pode banir este card do seu Cemitério como 1 dos monstros necessários para a Invocação-Ritual. \r\nSe o monstro Invocado por Invocação-Ritual usando este card destruir um monstro em batalha, o controlador do Monstro de Ritual compra 1 card.','\r',char(13)),'\n',char(10)),'O efeito de "Djinn, o Oficiante de Rituais" está sendo aplicado.','Comprar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34365442,'EZ GG da Evil★Gêmea',replace(replace('Você pode oferecer como Tributo 1 monstro "Ki-sikil" ou 1 monstro "Lil-la" e, depois, ative 1 dos seguintes efeitos.\r\n● Você pode escolher 1 monstro "Ki-sikil" ou 1 monstro "Lil-la" que você controla; até o final deste turno, ele ganha ATK igual ao ATK original do monstro oferecido como Tributo.\r\n● Quando um card ou efeito for ativado que destruiria um ou mais cards no campo: você pode negar o efeito.	\r\nVocê só pode usar este efeito de "EZ GG da Evil★Gêmea" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar, mas não resolver o efeito','Aumentar ATK','Negue o efeito de destruição','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34370473,'Espanador de Grifo',replace(replace('Destrua todos os Cards de Magia e Armadilha no seu campo. \r\nAumente seus PV pelo número de cards destruídos x 500.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34379489,'Camarartista Borbuldogue',replace(replace('Escala de Pêndulo = 5\r\n[ Efeito de Pêndulo ]\r\nSe um ou mais Monstros não-Pêndulo com a face para cima que você controla que foram Invocados por Invocação-Especial do Deck Adicional seriam destruídos em batalha ou por um efeito de card, em vez disso, você pode destruir este card.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nQuando este card for Invocado por Invocação-Especial do Deck Adicional: você pode ativar este efeito; pelo resto deste turno, Monstros Pêndulo que você controla que foram Invocados por Invocação-Especial do Deck Adicional não podem ser destruídos por efeitos de card.','\r',char(13)),'\n',char(10)),'Usar o efeito de "Camarartista Borbuldogue" em vez de ser destruído?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34408491,'Belze dos Dragões Diabólicos',replace(replace('1 Regulador de TREVAS + 1+ monstros não-Reguladores	\r\nNão pode ser destruído em batalha ou por efeitos de card. \r\nSe você sofrer dano de um ataque envolvendo este card ou de um efeito de card do oponente: este card ganha ATK igual ao dano que você sofreu.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34419588,'Kuribeh',replace(replace('(Este card deve ser sempre considerado como um card "Kuriboh".)	\r\n(Efeito Rápido): você pode descartar este card e, depois, escolha 1 monstro "Kuriboh" que você controla; ele ganha 1500 de ATK. \r\nVocê pode oferecer este card que você controla como Tributo e 1 de cada de "Kuribah", "Kuribee", "Kuriboo" e "Kuriboh" da sua mão e/ou do campo; adicione 1 "Kuribandido" do seu Deck ou Cemitério à sua mão e, depois, imediatamente depois que este efeito resolver, você pode Invocar por Invocação-Normal 1 monstro Demônio da sua mão.','\r',char(13)),'\n',char(10)),'','','Invocar um monstro Demônio?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34433770,'Força Celeste - Manobra Especial - Lemnisporta!',replace(replace('Escolha um mesmo número de monstros "Força Celeste - Ás" e Magias "Força Celeste" no seu Cemitério; embaralhe-os no Deck e, depois, para cada 3 cards embaralhados, você pode devolver até 1 card no campo para a mão. \r\nSe um ou mais monstros "Força Celeste" forem Invocados por Invocação-Especial no seu campo, enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode banir este card; imediatamente depois que este efeito resolver, Invoque 1 Monstro Link "Força Celeste - Ás" por Invocação-Link. \r\nVocê só pode usar cada efeito de "Força Celeste - Manobra Especial - Lemnisporta!" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Retornar o card selecionado para à mão?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34442949,'Caracol Mecânico','Um caracol ciborgue que também viaja lentamente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34446231,'Infernoide Flood',replace(replace('2+ monstros, incluindo um monstro "Infernoide"	\r\nQuando seu oponente Invocaria um ou mais monstros por Invocação-Especial (Efeito Rápido): você pode oferecer 1 monstro como Tributo; negue a Invocação e, se isso acontecer, bana esse(s) monstro(s). \r\nSe um ou mais cards forem banidos do seu Cemitério (exceto durante a Etapa de Dano): você pode banir 1 card no campo. \r\nSe este card Invocado por Invocação-Link sob o controle do seu dono for destruído por um card do oponente: você pode Invocar por Invocação-Especial 1 monstro "Infernoide" do seu Deck, ignorando suas condições de Invocação. \r\nVocê só pode usar cada efeito de "Infernoide Flood" uma vez por turno.','\r',char(13)),'\n',char(10)),'Negar a Invocação Especial','Banir 1 card','Invocar por Invocação Especial do Deck','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34447918,'Kashtirateose',replace(replace('Escolha 1 monstro "Kashtira" que você controla; Invoque por Invocação-Especial 1 monstro "Kashtira" com um Atributo diferente do seu Deck em Posição de Defesa e, além disso, pelo resto deste turno depois que este card resolver, você não pode Invocar monstros por Invocação-Especial do Deck Adicional, exceto Monstros Xyz. \r\nSe este card for banido: você pode escolher 1 dos seus cards "Kashtira" banidos, exceto "Kashtirateose"; adicione-o à sua mão. \r\nVocê só pode usar cada efeito de "Kashtirateose" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34449261,'Valsa Assustadora de Fusão','Escolha 1 Monstro de Fusão "Peladura" que você controla e 1 Monstro de Fusão que seu oponente controla; destrua tantos outros monstros Invocados por Invocação-Especial no campo quanto possível e, depois, cada duelista que teve um ou mais monstros destruídos por este efeito sofre dano igual ao ATK atual combinado dos monstros escolhidos no campo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34456146,'Sábia da Benevolência - Ciela',replace(replace('(Este card deve ser sempre considerado como um card "Força Celeste".)	\r\nVocê pode descartar 1 Magia; Invoque este card por Invocação-Especial da sua mão. \r\nVocê pode banir 1 Magia do seu Cemitério; conceda o controle deste card ao seu oponente e, se isso acontecer, Invoque por Invocação-Especial 1 monstro "Força Celeste - Ás" do seu Cemitério. \r\nSe este card for destruído em batalha ou por um efeito de card e enviado para o Cemitério: você pode escolher 1 das suas Magias "Força Celeste" banidas; adicione-a à sua mão. \r\nVocê só pode usar cada efeito de "Sábia da Benevolência - Ciela" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34460239,'Mudança de Geração','Escolha 1 monstro com a face para cima que você controla; destrua o alvo e, depois, adicione 1 card com o mesmo nome que o card destruído do seu Deck à sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34460851,'Manipulador de Chamas','Este mago ataca os inimigos com magias de fogo como "Mar de Chamas" e "Parede de Fogo".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34471458,'Senhora Fortuna da Luz',replace(replace('O ATK/DEF deste card se tornam seu Nível x 200. \r\nUma vez por turno, durante sua Fase de Apoio: aumente em 1 o Nível deste card (máx. 12). \r\nQuando este card com a face para cima deixar o campo por um efeito de card: você pode Invocar por Invocação-Especial 1 monstro "Senhora Fortuna" do seu Deck.','\r',char(13)),'\n',char(10)),'Aumentar o Nível','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34472920,'Bot de Mel',replace(replace('2 monstros Ciberso	\r\nNenhum duelista pode escolher como alvo de efeitos de card os monstros para os quais este card apontar, e esses monstros não podem ser destruídos em batalha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34475451,'Trem de Construção Sinal Vermelho',replace(replace('Quando um monstro do oponente declarar um ataque: você pode Invocar este card por Invocação-Especial da sua mão e, se isso acontecer, mude o alvo do ataque para este card e prossiga para o cálculo de dano. \r\nEste card não pode ser destruído em batalha.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34479658,'Jacaré Negro',replace(replace('Você pode Invocar este card por Invocação-Tributo ao oferecer como Tributo 1 monstro Réptil. \r\nQuando este card for Invocado por Invocação-Tributo: você pode Invocar por Invocação-Especial uma ou mais "Ficha de Jacaré" (Réptil/TREVAS/Nível 1/ATK 2000/DEF 0), até o número de monstros Réptil oferecidos como Tributo para a Invocação-Tributo deste card. \r\nSe este card Invocado por Invocação-Tributo for destruído em batalha, ou for destruído por um efeito de card do oponente enquanto estiver na Zona de Monstros do seu dono: você pode adicionar 1 monstro Réptil do seu Deck à sua mão, exceto "Jacaré Negro".','\r',char(13)),'\n',char(10)),'Ofereça 1 monstro Réptil como Tributo para uma Invocação Tributo','','Invocar outro monstro por Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34479659,'Ficha de Jacaré','Invocado por Especial com o efeito "Jacaré Negro".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34481518,'Grenossauro Gigacanhão',replace(replace('2 monstros de Nível 4	\r\nQuando um monstro Dinossauro seu destruir um monstro do oponente em batalha e enviá-lo para o Cemitério: você pode desassociar 1 matéria deste card; cause 1000 de dano ao seu oponente e, depois, este card ganha 1000 de ATK. \r\nSe este card Invocado por Invocação-Xyz for destruído: você pode escolher 1 card no campo; destrua-o e, se isso acontecer, cause 1000 de dano ao seu oponente. \r\nVocê só pode usar este efeito de "Grenossauro Gigacanhão" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34487429,'Cidade Antiga - Ruínas Arco-Íris',replace(replace('Você deve ter esse número de cards "Fera Cristalina" na sua Zona de Magias & Armadilhas para ativar e resolver esses efeitos.\r\n● 1+: Este card não pode ser destruído por efeitos de card.\r\n● 2+: Uma vez por turno (incluindo o do oponente) você pode diminuir pela metade o dano de batalha que você sofrer.\r\n● 3+: Quando um Card de Magia/Armadilha for ativado: você pode enviar 1 monstro "Fera Cristalina" que você controla para o Cemitério; negue a ativação e, se isso acontecer, destrua-o.\r\n● 4+: Uma vez por turno, durante sua Fase Principal: você pode comprar 1 card.\r\n● 5: Uma vez por turno, durante sua Fase Principal: você pode escolher 1 card "Fera Cristalina" na sua Zona de Magias & Armadilhas; Invoque o alvo por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Reduzir o dano pela metade','Negue a ativação de um Card de Magia/Armadilha e destrua-o','Compre 1 card do seu Deck','Invoque por Invocação Especial cards "Fera Cristalina" da sua Zona de Magias & Armadilhas','','','','','','','','','','','','');
INSERT INTO texts VALUES(34492631,'Gigante Sucata',replace(replace('Se seu oponente controlar um monstro de Nível 5 ou mais, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nUma Invocação-Sincro que usar este card como uma Matéria não pode ser negada. \r\nSe um duelista Invocar por Invocação-Sincro usando este card como uma Matéria, o outro duelista não pode ativar cards ou efeitos quando esse monstro for Invocado por Invocação-Sincro.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34496660,'Samurai Superpesado Vagão',replace(replace('Quando este card for Invocado por Invocação-Normal ou Especial: você pode mudar sua posição de batalha. \r\nEste card pode atacar enquanto estiver com a face para cima em Posição de Defesa. \r\nSe o fizer, use sua DEF para o cálculo de dano. \r\nSe você não tiver Magias/Armadilhas no seu Cemitério: você pode colocar este card com a face para cima em Posição de Defesa que você controla, em Posição de Ataque e, se isso acontecer, adicione 1 monstro "Samurai Superpesado Alma" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Samurai Superpesado Vagão" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34507039,'Escuta','Quando uma Armadilha for ativada: negue a ativação e, se isso acontecer, embaralhe esse card no Deck.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34522216,'Amórfago da Gula',replace(replace('Escala de Pêndulo = 5\r\n[ Efeito de Pêndulo ]\r\nEnquanto você controlar um monstro "Amórfago", monstros não podem ativar seus efeitos, exceto monstros "Amórfago". \r\nUma vez por turno, durante sua Fase de Apoio, ofereça 1 monstro como Tributo ou destrua este card.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe este card for Invocado por Invocação-Pêndulo ou virado com a face para cima, nenhum duelista pode Invocar monstros do Deck Adicional por Invocação-Especial enquanto este card estiver no campo com a face para cima, exceto monstros "Amórfago".','\r',char(13)),'\n',char(10)),'Oferecer como Tributo 1 monstro que você controla?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34528176,'Cavaleiro Dragunidade - Areus',replace(replace('1 Regulador + 1+ Monstros Sincro não-Reguladores	\r\nVocê pode escolher cards com a face para cima que seu oponente controla, até o número de Cards de Monstro com a face para cima na sua Zona de Magias & Armadilhas; negue seus efeitos até o final deste turno. \r\nEste é um Efeito Rápido se este card estiver equipado com um Card de Equipamento. \r\nEnquanto este card estiver equipado a um monstro: você pode Invocar este card por Invocação-Especial e, depois, você pode Invocar por Invocação-Especial 1 Regulador "Dragunidade" do seu Cemitério. \r\nVocê só pode usar cada efeito de "Cavaleiro Dragunidade - Areus" uma vez por turno.','\r',char(13)),'\n',char(10)),'Negar o efeito','Invocação Especial','Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34536276,'Ganigumo','Um caranguejo que prende seus inimigos numa teia pegajosa e os ataca com suas garras afiadas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34536828,'Discípulo Marcado',replace(replace('Quando um efeito de monstro ativado pelo seu oponente resolver, se esse monstro do oponente tiver 0 de ATK ou DEF e você controlar um Monstro de Fusão Demônio de Nível 8 ou mais, você pode negar esse efeito ativado. \r\nNo final da Etapa de Dano, se monstros com 0 de ATK batalharam um com o outro: você pode destruir o monstro do seu oponente que estiver batalhando. \r\nVocê só pode usar cada efeito de "Discípulo Marcado" uma vez por turno.','\r',char(13)),'\n',char(10)),'Aplicar o efeito de "Discípulo Marcado" para negar?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34541543,'Mestre Tao, o Declamador',replace(replace('Se este card batalhar um monstro, nenhum dos dois pode ser destruído nessa batalha. \r\nSe este card for enviado para o Cemitério: você pode escolher 1 monstro Ilusão no seu Cemitério, exceto "Mestre Tao, o Declamador"; Invoque-o por Invocação-Especial em Posição de Defesa e, além disso, você não pode Invocar por Invocação-Especial do Cemitério pelo resto deste turno, exceto monstros Ilusão. \r\nVocê só pode usar este efeito de "Mestre Tao, o Declamador" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34541863,'Mecanismo Reprodutor de Células "A"','Durante cada uma das suas Fases de Apoio, coloque 1 Marcador-A em 1 monstro com a face para cima que seu oponente controla.','Colocar "Marcador-A"','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34541940,'Finmel de Artmage',replace(replace('Seu oponente não pode escolher monstros "Artmage" de Nível 6 ou menos que você controla como alvo de efeitos de card. \r\nVocê só pode usar cada um dos seguintes efeitos de "Finmel de Artmage" uma vez por turno. \r\nSe você controlar um card "Artmage": você pode Invocar este card por Invocação-Especial da sua mão e, depois, você pode comprar 1 card. \r\nDurante a Fase Principal, se você tiver 3 ou mais Tipos de Monstro diferentes no seu campo (Efeito Rápido): você pode negar os efeitos de todos os monstros com a face para cima que seu oponente controla atualmente e, além disso, até o final deste turno, o ATK deles é diminuído pela metade.','\r',char(13)),'\n',char(10)),'Invocação Especial','Negar','Comprar 1 card?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34545235,'Brilho do Núcleo de Ferro',replace(replace('Revele 1 "Núcleo de Ferro de Koa''ki Meiru" na sua mão. \r\nNegue a ativação de um Card de Magia ou Armadilha do oponente e destrua-o.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34550857,'Lirilusc - Pardal de Cobalto',replace(replace('Se este card for Invocado por Invocação-Especial: você pode adicionar 1 monstro Besta Alada de Nível 1 do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Lirilusc - Pardal de Cobalto" uma vez por turno. \r\nUm Monstro Xyz de VENTO que foi Invocado usando este card no campo como matéria ganha este efeito.\r\n● Seu oponente não pode escolher este card como alvo de efeitos de card.','\r',char(13)),'\n',char(10)),'Procurar no Deck','O efeito de "Lirilusc - Pardal de Cobalto" está sendo aplicado.','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34559295,'Saque de Ferro',replace(replace('Se você controlar exatamente 2 Monstros de Efeito Máquina e nenhum outro monstro: compre 2 cards. \r\nPelo resto deste turno depois que este card resolver, você só pode Invocar uma vez por Invocação-Especial. \r\nVocê só pode ativar 1 "Saque de Ferro" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34566435,'Diabrete de Peladuloides Afiadas',replace(replace('(Este card deve ser sempre considerado como um card "Peladura".)	\r\nVocê pode escolher 1 Monstro de Fusão "Peladura" que você controla ou no seu Cemitério; até o final deste turno, o ATK e a DEF deste card se tornam iguais ao ATK e DEF originais desse monstro. \r\nVocê só pode usar este efeito de "Diabrete de Peladuloides Afiadas" uma vez por turno.','\r',char(13)),'\n',char(10)),'Alterar ATK/DEF','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34568403,'Força Arcana VII - A Carruagem',replace(replace('Se este card for Invocado: lance uma moeda.\r\n● Cara: Quando este card destruir um monstro do oponente em batalha: você pode Invocar esse monstro por Invocação-Especial no seu campo.\r\n● Coroa: Conceda o controle deste card ao seu oponente.','\r',char(13)),'\n',char(10)),'Jogar uma moeda','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34568783,'Undina Genex-R',replace(replace('Uma vez por turno: você pode banir 1 monstro "Genex" do seu Cemitério; este card ganha o Atributo desse monstro e, depois, se você baniu um Regulador para ativar este efeito, você pode considerar este card como um Regulador até o final deste turno. \r\nSe você controlar um Monstro Sincro "Genex": você pode escolher 2 monstros "Genex" no seu Cemitério, incluindo este card; adicione-os à sua mão e, além disso, pelo resto deste turno, qualquer card enviado para o seu Cemitério, em vez disso, é banido.','\r',char(13)),'\n',char(10)),'Alterar o Atributo','Recuperar do Cemitério','Considerar este card como Regulador?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34572613,'Laboratório de Evolução Miutante',replace(replace('Quando este card for ativado: você pode Invocar por Invocação-Especial 1 dos seus monstros "Miutante" de Nível 4 ou menos da sua mão ou que estiver banido. \r\nMonstros "Miutante" que você controla ganham 100 de ATK para cada um dos seus cards "Miutante" banidos com nomes diferentes. \r\nUma vez por turno, durante sua Fase Principal: você pode colocar 1 monstro "Miutante" da sua mão no fundo do Deck e, se isso acontecer, compre 1 card. \r\nVocê só pode ativar 1 "Laboratório de Evolução Miutante" por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial?','Retornar ao Deck e comprar 1 card','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34611551,'Lampejo do Dragão Armado',replace(replace('Invoque por Invocação-Especial do seu Deck 1 monstro "Dragão Armado" de Nível 3 em Posição de Defesa. \r\nVocê só pode ativar 1 "Lampejo do Dragão Armado" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34614289,'U.A. Volante',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) ao devolver 1 monstro "U.A." que você controla para a mão, exceto "U.A. Volante". \r\nVocê só pode Invocar "U.A. Volante" por Invocação-Especial uma vez por turno desta forma. \r\nUma vez por turno, quando seu oponente Invocar um ou mais monstros por Invocação-Especial: você pode mudar a posição de batalha deles e, se isso acontecer, os efeitos deles são negados.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34614910,'Ciclame, a Fada Rikka',replace(replace('Você pode oferecer este card como Tributo da sua mão ou do campo com a face para cima e, depois, escolha até 2 monstros Planta que você controla; reduza o Nível dele(s) em 2 até o final deste turno. \r\nDurante a Fase Final, se este card estiver no Cemitério porque foi oferecido como Tributo e enviado para lá neste turno: você pode Invocar este card por Invocação-Especial, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar cada efeito de "Ciclame, a Fada Rikka" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34620088,'Engenhoca Marionete Palpo Sombrio',replace(replace('Não pode ser destruído em batalha. \r\nQuando você sofrer dano de batalha de um ataque direto do oponente enquanto este card estiver no seu Cemitério: você pode Invocar este card por Invocação-Especial do seu Cemitério com a face para cima em Posição de Ataque e, se isso acontecer, você sofre 1000 de dano. \r\nVocê só pode usar este efeito de "Engenhoca Marionete Palpo Sombrio" uma vez por turno. \r\nSe este card for uma Matéria Xyz e seria enviado para o Cemitério, em vez disso, bana-o.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34627841,'Kaibaman','Você pode oferecer este card como Tributo; Invoque por Invocação-Especial 1 "Dragão Branco de Olhos Azuis" da sua mão.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34646691,'Tropeçar','Qualquer monstro que for Invocado por Invocação-Normal, Virar ou Especial é colocado em Posição de Defesa.','Mudar para Posição de Defesa','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34659866,'Resgate do Mar Sombrio','Se este card for usado para uma Invocação-Sincro e enviado ao Cemitério, o dono deste card compra 1 card.','Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34664411,'Machado de Ferro da Sorte',replace(replace('O monstro equipado ganha 500 de ATK. \r\nSe este card com a face para cima que você controla for destruído por um efeito de card do seu oponente e enviado para o seu Cemitério: compre 1 card.','\r',char(13)),'\n',char(10)),'Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34680482,'Magidoce Angeleia',replace(replace('Você pode oferecer este card como Tributo; Invoque por Invocação-Especial 1 monstro "Magidoce" do seu Deck e, se isso acontecer, ele não pode ser destruído em batalha, mas embaralhe-o no Deck durante a Fase Final do seu próximo turno. \r\nVocê só pode usar este efeito de "Magidoce Angeleia" uma vez por turno. \r\nSe este card em sua posse for destruído por um card do seu oponente e enviado para o seu Cemitério: embaralhe este card no Deck.','\r',char(13)),'\n',char(10)),'Retornar ao Deck','Invocação Especial','O efeito de "Magidoce Angeleia" está sendo aplicado.','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34688023,'Diabrete de Serras Afiadas',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode enviar 1 monstro "Fofanimal" da sua mão para o Cemitério; compre 2 cards e, depois, coloque 1 card da sua mão no topo ou no fundo do seu Deck. \r\nVocê só pode usar este efeito de "Diabrete de Serras Afiadas" uma vez por turno.','\r',char(13)),'\n',char(10)),'Compre 2 card(s)','Retornar ao topo do Deck','Retornar ao fundo do Deck','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34690519,'Espírito da Montanha','Quem escutar o assobio desta criatura sofrerá uma grande perda de energia.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34690953,'Maldição de Aramatir',replace(replace('Durante sua Fase Principal: você pode Invocar por Invocação-Especial 1 "Ficha de Aventura" (Fada/TERRA/Nível 4/ATK 2000/DEF 2000) em qualquer campo e, depois, envie 1 card da sua mão para o Cemitério. \r\nVocê não pode Invocar monstros por Invocação-Especial no turno em que ativar este efeito, exceto "Ficha de Aventura" e monstros que o mencionem. \r\nSe um ou mais monstros que você controla forem destruídos em batalha ou por um efeito de card: você pode Invocar por Invocação-Especial 1 "Ficha de Aventura" em qualquer campo. \r\nVocê só pode usar cada efeito de "Maldição de Aramatir" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Invocar uma Ficha por Invocação Especial','Invocar por Invocação Especial para o seu Campo','Invocar por Invocação Especial para o Campo do seu oponente','','','','','','','','','','','','');
INSERT INTO texts VALUES(34690954,'Ficha de Aventura','Invocado por Especial com o efeito "Ritual de Aramesir".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34694160,'Olho Mágico da Verdade',replace(replace('Seu oponente deve manter sua mão revelada. \r\nUma vez por turno, durante a Fase de Apoio do seu oponente, se ele tiver uma ou mais Magias em sua mão: ele ganha 1000 PV se tiver uma ou mais Magias em sua mão na resolução.','\r',char(13)),'\n',char(10)),'Ganhar PV','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34695290,'Besta Miutante',replace(replace('Não pode ser Invocado por Invocação-Especial, exceto com o efeito de um card "Miutante". \r\nSeu oponente não pode escolher este card como alvo de efeitos de monstro. \r\nVocê só pode usar cada um dos seguintes efeitos de "Besta Miutante" uma vez por turno. \r\nQuando seu oponente ativar um Card de Magia ou seus efeitos (Efeito Rápido): você pode banir 1 card da sua mão ou do campo; negue a ativação e, se isso acontecer, bana esse card. \r\nSe este card em posse do seu dono for destruído por um card do oponente: você pode escolher 1 das suas Armadilhas "Miutante" banidas; adicione-a à sua mão.','\r',char(13)),'\n',char(10)),'Negar e banir','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34707034,'Abis-Temporal',replace(replace('Escolha 3 monstros "Sirena" no seu Cemitério; Invoque os alvos por Invocação-Especial com a face para cima em Posição de Defesa. \r\nSeus efeitos são negados e eles não podem declarar um ataque. \r\nDestrua-os durante a Fase Final.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34710660,'Tartaruga Eletromagnética',replace(replace('Durante a Fase de Batalha do seu oponente (Efeito Rápido): você pode banir este card do seu Cemitério; encerre a Fase de Batalha. \r\nVocê só pode usar este efeito de "Tartaruga Eletromagnética" uma vez por Duelo.','\r',char(13)),'\n',char(10)),'Encerrar a Fase de Batalha','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34717238,'Puxando o Tapete','Quando um efeito de monstro for ativado que ative quando um monstro é Invocado por Invocação-Normal: negue a ativação e, se isso acontecer, destrua esse monstro.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34721681,'Forte Avanço',replace(replace('Quando este card for ativado: você pode adicionar 1 monstro "Infinisteira" do seu Deck à sua mão. \r\nUma vez por turno: você pode escolher 1 Monstro Xyz Máquina que você controla e, depois, ative 1 desses efeitos;\r\n● Mude sua posição de batalha.\r\n● Associe este card a ele como matéria.	\r\nVocê só pode ativar 1 "Forte Avanço" por turno.','\r',char(13)),'\n',char(10)),'Adicionar à sua mão 1 monstro "Infinisteira"?','Alterar posição de batalha','Associar Matéria Xyz','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34743446,'Interceptador','Construído a partir de vários componentes, este monstro pode lançá-los em ataques de pinça.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34755994,'Artemis, a Donzela da Lua Magistus',replace(replace('1 monstro Mago de Nível 4 ou menos	\r\nSe um ou mais outros monstros "Magistus" forem Invocados por Invocação-Normal ou Especial enquanto você controlar este monstro (exceto durante a Etapa de Dano): você pode escolher 1 desses monstros; equipe este card que você controla a ele. \r\nEnquanto este card estiver equipado a um monstro: você pode adicionar 1 monstro "Magistus" do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "Artemis, a Donzela da Lua Magistus" uma vez por turno. \r\nVocê só pode Invocar "Artemis, a Donzela da Lua Magistus" por Invocação-Especial uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34755995,'Artemis, a Donzela da Lua Magistus',replace(replace('1 monstro Mago de Nível 4 ou menos	\r\nSe um ou mais outros monstros "Magistus" forem Invocados por Invocação-Normal ou Especial enquanto você controlar este monstro (exceto durante a Etapa de Dano): você pode escolher 1 desses monstros; equipe este card que você controla a ele. \r\nEnquanto este card estiver equipado a um monstro: você pode adicionar 1 monstro "Magistus" do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "Artemis, a Donzela da Lua Magistus" uma vez por turno. \r\nVocê só pode Invocar "Artemis, a Donzela da Lua Magistus" por Invocação-Especial uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34761062,'Cavaleiro das Chamas Pesado',replace(replace('Este card é considerado como um Monstro Normal enquanto estiver com a face para cima no campo ou no Cemitério. \r\nEnquanto este card for um Monstro Normal no campo, você pode Invocá-lo por Invocação-Normal para fazer com que ele se torne um Monstro de Efeito com este efeito.\r\n● No começo da Etapa de Dano, se este card atacar um monstro Invocado por Invocação-Especial: você pode banir esse monstro.','\r',char(13)),'\n',char(10)),'Banir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34761841,'Ressonador Carmesim',replace(replace('Se você não controlar nenhum monstro: você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe o único outro monstro que você controla for exatamente 1 Monstro Sincro Dragão de TREVAS: você pode Invocar por Invocação-Especial até 2 monstros "Ressonador" da sua mão ou do Deck, exceto "Ressonador Carmesim". \r\nVocê só pode usar cada efeito de "Ressonador Carmesim" uma vez por turno. \r\nVocê não pode Invocar monstros por Invocação-Especial do Deck Adicional no turno em que ativar qualquer um dos efeitos deste card, exceto Monstros Sincro Dragão de TREVAS.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34767865,'Cinet Ritual',replace(replace('Este card pode ser usado para a Invoção-Ritual de qualquer Monstro de Ritual Ciberso. \r\nVocê também deve oferecer como Tributo monstros da sua mão ou do campo cuja soma dos Níveis seja igual ou exceda o Nível do Monstro de Ritual que você Invocar por Invocação-Ritual. \r\nSe você não controlar nenhum monstro: você pode banir este card e 1 Monstro de Ritual do Cemitério; Invoque por Invocação-Especial 2 "Fichas Cinet" (Ciberso/LUZ/Nível 4/ATK 0/DEF 0). \r\nVocê não pode ativar este efeito no turno em que este card for enviado para o Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34767866,'Ficha Cinet','Invocada por Invocação-Especial com o efeito "Cinet Ritual".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34771947,'Sombra das Paredes do Labirinto',replace(replace('Monstros não podem atacar no turno em que forem Invocados, exceto monstros cujo Nível original seja 5 ou mais. \r\nUma vez por turno, durante sua Fase Principal: você pode colocar 1 dos seus "Sanga do Trovão", "Kazejin" ou "Suijin" que estiverem banidos, ou na sua mão ou no Deck, com a face para cima na sua Zona de Magias & Armadilhas como uma Magia Contínua. \r\nNo começo da Fase de Batalha do seu oponente: você pode escolher 1 monstro que seu oponente controla com menos de 1600 de ATK; destrua-o.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34773082,'Retalhos de Peladura',replace(replace('Adicione 1 monstro "Diabrete de" e 1 "Polimerização" do seu Deck à sua mão. \r\nVocê só pode ativar 1 "Retalhos de Peladura" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34796454,'Trion da Estrela Tripla','Durante a Fase Final, se este card estiver no Cemitério porque foi enviado para lá neste turno ao ter sido oferecido como Tributo para uma Invocação-Tributo bem-sucedida: você pode Invocar este card por Invocação-Especial do seu Cemitério.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34800281,'Melffy Pinny',replace(replace('Se um monstro Besta com a face para cima que você controla foi devolvido para a mão neste turno, exceto "Melffy Pinny" (Efeito Rápido): você pode Invocar este card por Invocação-Especial da sua mão e, depois, imediatamente depois que este efeito resolver, Invoque por Invocação-Sincro 1 Monstro Sincro usando apenas este card que você controla e monstros "Melffy" na sua mão. \r\nDurante sua Fase Final, se este card estiver no seu Cemitério: você pode escolher 1 Monstro Xyz Besta que você controla; associe este card a ele como matéria. \r\nVocê só pode usar cada efeito de "Melffy Pinny" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Invocação Sincro?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34813443,'Cinzenta ao Infinito',replace(replace('Durante a Fase Principal: você pode Invocar por Invocação-Fusão 1 Monstro de Fusão Piro do seu Deck Adicional usando monstros de qualquer campo como matéria, incluindo "Veidos, o Dragão de Erupção da Extinção" e, se isso acontecer, ele ganha 500 de ATK para cada matéria usada. \r\nVocê pode banir este card e 1 monstro Piro de TREVAS do seu Cemitério; todos os monstros que seu oponente controla atualmente se tornam Piro até o final deste turno. \r\nVocê só pode usar cada efeito de "Cinzenta ao Infinito" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Invocação Fusão','Alterar o Tipo','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34813545,'Benção de Naturia',replace(replace('Ative 1 desses efeitos;\r\n● Invoque por Invocação-Especial 1 monstro "Naturia" da sua mão ou do Cemitério.\r\n● Imediatamente depois que este efeito resolver, Invoque por Invocação-Sincro 1 Monstro Sincro, usando monstros que você controla como matéria, incluindo um monstro "Naturia".\r\n● Invoque por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional, usando monstros que você controla como matéria, incluindo um monstro "Naturia".','\r',char(13)),'\n',char(10)),'Invocação Especial','Invocação Sincro','Invocação Fusão','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34815282,'Miniaturizar',replace(replace('Ative este card ao escolher 1 monstro no campo com mais de 1000 de ATK original e que tenha um Nível; seu Nível é reduzido em 1 e, além disso, ele perde 1000 de ATK. \r\nQuando esse monstro deixar o campo, destrua este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34822850,'Expansão do Vácuo',replace(replace('Durante sua Fase de Apoio: você pode Invocar por Invocação-Especial 1 "Ficha Infernoide" (Tipo Demônio/FOGO/Nível 1/ATK 0/DEF 0). \r\nPara Invocar por Invocação-Especial um monstro "Infernoide" usando seus próprios métodos, você pode banir um ou mais monstros "Infernoide" que você controla em vez de aqueles no Cemitério (ou qualquer combinação dos dois). \r\nSeu oponente não pode escolher monstros "Infernoide" que você controla como alvo de ataques ou de efeitos de card, exceto o monstro "Infernoide" que você controla de maior Nível (em caso de empate, qualquer um dos dois).','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34822851,'Ficha Infernoide','Invocado por Especial com o efeito "Expansão do Vácuo".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34830502,'Inseto Supremo LV5',replace(replace('Se este card foi Invocado, por Invocação-Especial, pelo efeito de "Inseto Supremo LV3", enquanto este card permanecer no Campo, diminua o ATK de todos os monstros do seu adversário em 500 pontos. \r\nDurante as Standby Phases do seu turno, envie este card, com a face para cima, para o Cemitério para Invocar, por Invocação-Especial, 1 "Inseto Supremo LV7" da sua mão ou do seu Deck (exepto no turno em que este card é Invocado por Invocação-Normal, Invocação-Especial ou virado com a face para cima).','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34834619,'Ritual do Dragão Brilhante',replace(replace('Este card é usado para Invocar "Paladino do Dragão de Fóton" por Invocação-Ritual. \r\nVocê também deve oferecer como Tributo monstros da sua mão ou campo cuja soma dos Níveis seja exatamente igual a 4. \r\nVocê pode banir este card do seu Cemitério; bana monstros do seu Cemitério cuja soma dos Níveis seja exatamente igual a 4 e Invoque por Invocação-Especial 1 "Paladino do Dragão de Fóton" da sua mão depois disso. \r\n(Esta Invocação-Especial é considerada uma Invocação-Ritual.)','\r',char(13)),'\n',char(10)),'Invocação Ritual','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34838437,'Aceleruz',replace(replace('Se você não controlar nenhum monstro: Invoque por Invocação-Especial 1 monstro "Fóton" ou "Galáxia" de Nível 4 ou menos do seu Deck. \r\nVocê só pode ativar 1 "Aceleruz" por turno. \r\nVocê não pode Invocar por Invocação-Normal/Baixar durante o turno em que ativou este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34848821,'Brigrand, o Dragão da Glória',replace(replace('"Caído de Arbaz" + 1 monstro de Nível 8 ou mais	\r\nNão pode ser destruído em batalha. \r\nEnquanto você controlar este card Invocado por Invocação-Fusão, seu oponente não pode escolher outros monstros que você controla como alvo de efeitos de monstro. \r\nDurante a Fase Final, se este card estiver no Cemitério porque foi enviado para lá neste turno: você pode adicionar à sua mão, ou Invocar por Invocação-Especial, 1 monstro "Tri-Brigada" ou 1 "Caído de Arbaz" do seu Deck. \r\nVocê só pode usar este efeito de "Brigrand, o Dragão da Glória" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34853266,'Tsukuyomi',replace(replace('Não pode ser Invocado por Invocação-Especial. \r\nSe este card for Invocado por Invocação-Normal ou virado coma face para cima: escolha 1 monstro com a face para cima no campo; coloque o alvo com a face para baixo em Posição de Defesa. \r\nUma vez por turno, durante a Fase Final, se este card foi Invocado por Invocação-Normal ou virado com a face para cima neste turno: devolva-o para a mão.','\r',char(13)),'\n',char(10)),'Retornar à mão','Mudar a posição de batalha','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34873741,'Kuribon, o Espírito Fada',replace(replace('Se você controlar "Dragão Fada Antigo" ou um monstro de LUZ (Besta, Planta ou Fada): você pode Invocar este card por Invocação-Especial da sua mão e, se isso acontecer, ele é considerado como um Regulador. \r\nSe um ou mais outros cards que você controla, que forem "Dragão Fada Antigo" ou um ou mais monstros que o mencionem, seriam destruídos por um efeito de card, em vez disso, você pode devolver este card que você controla para a mão. \r\nVocê só pode usar cada efeito de "Kuribon, o Espírito Fada" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34876719,'Cavaleiro N.As.H.',replace(replace('2 monstros de Nível 5	\r\nNão pode ser destruído em batalha enquanto um monstro "Número" estiver no campo. \r\nDurante a Fase Principal (Efeito Rápido): você pode desassociar 2 matérias deste card; associe 1 Monstro Xyz "Número", com um número entre "101" e "107" em seu nome, do seu Deck Adicional a este card e, depois, você pode associar 1 outro monstro com a face para cima no campo a este card. \r\nVocê só pode usar este efeito de "Cavaleiro N.As.H." uma vez por turno.','\r',char(13)),'\n',char(10)),'','Escolher mais 1 monstro como Matéria Xyz?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34884015,'Alma Pêndulo',replace(replace('Você pode escolher 2 cards nas suas Zonas de Pêndulo; mude em 1 a Escala Pêndulo de cada alvo (mín. 1). \r\nVocê só pode usar este efeito de "Alma Pêndulo" uma vez por turno. \r\nSempre que um ou mais Monstros Pêndulo forem Invocados por Invocação-Pêndulo, coloque 1 marcador neste card. \r\nOs Monstros Pêndulo no campo ganham 300 de ATK para cada marcador neste card. \r\nVocê pode remover 3 marcadores deste card; durante sua Fase Principal deste turno, você pode conduzir 1 Invocação-Pêndulo de um ou mais monstros em adição à sua Invocação-Pêndulo. \r\n(Você só pode se aproveitar deste efeito uma vez por turno.)','\r',char(13)),'\n',char(10)),'Alterar a Escala','Aumentar a Escala','Reduzir a Escala','Invocação Pêndulo adicional','Invocação Pêndulo usando o efeito de "Alma Pêndulo"','','','','','','','','','','','');
INSERT INTO texts VALUES(34898052,'Dragurro','Bana 1 monstro de TERRA, 1 de ÁGUA, 1 de FOGO e 1 de VENTO do seu Cemitério; embaralhe no Deck 1 card no campo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34904525,'Guardião do Portão do Trovão e do Vento',replace(replace('"Sanga do Trovão" + "Kazejin"	\r\nDeve ser Invocado por Invocação-Especial (do seu Deck Adicional) ao banir os cards acima que você controla. \r\nDurante sua Fase Principal: você pode adicionar 1 Magia/Armadilha do seu Deck à sua mão que mencione "Sanga do Trovão", "Kazejin" E "Suijin". \r\nVocê só pode usar este efeito de "Guardião do Portão do Trovão e do Vento" uma vez por turno. \r\nSe este card com a face para cima Invocado por Invocação-Especial sob o controle do seu dono deixar o campo devido a um card do oponente: você pode Invocar por Invocação-Especial 1 dos seus "Sanga do Trovão" ou "Kazejin" banidos.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34906152,'Motorista de Massas','Ofereça 1 monstro no seu Campo como Tributo para infligir 400 pontos de dano aos Life Points do seu adversário.','Cause 400 de dano ao seu oponente','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34909328,'Detonador de Ryzeal',replace(replace('2+ monstros "Ryzeal" de Nível 4	\r\nQuando seu oponente ativar um card ou efeito (Efeito Rápido): você pode desassociar 1 matéria deste card e, depois, escolha 1 card no campo; destrua-o. \r\nVocê só pode usar cada um dos seguintes efeitos de "Detonador de Ryzeal" uma vez por turno. \r\nSe este card for Invocado por Invocação-Especial: você pode associar 1 monstro do seu Cemitério a este card como matéria. \r\nSe um ou mais Monstros Xyz que você controla seriam destruídos em batalha ou por um efeito de card, em vez disso, você pode desassociar 1 matéria deste card.','\r',char(13)),'\n',char(10)),'Associar matéria','Efeito de destruição','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34923554,'Escavadeira Drag Infinisteira',replace(replace('Você pode oferecer como Tributo 1 monstro Máquina de TERRA; Invoque este card por Invocação-Especial da sua mão em Posição de Defesa. \r\nVocê pode banir 1 monstro Máquina do seu Cemitério; adicione 1 "Inversão do Sentido" do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "Escavadeira Drag Infinisteira" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34926568,'Escorpião Impiedoso de Serket',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro deve ser Invocado por Invocação-Especial (da sua mão) ao banir 1 monstro de Nível 10 ou mais da sua mão ou do Deck, enquanto você controlar "Templo dos Reis". \r\nVocê só pode Invocar "Escorpião Impiedoso de Serket" por Invocação-Especial uma vez por turno desta forma. \r\nUma vez por turno, durante sua Fase Principal: você pode adicionar 1 "Templo dos Reis" ou 1 Magia que o mencione do seu Deck à sua mão. \r\nNo começo da Etapa de Dano, se este card batalhar um monstro do oponente: você pode destruir esse monstro do oponente e, se isso acontecer, este card ganha ATK igual à metade do ATK original do monstro destruído.','\r',char(13)),'\n',char(10)),'Invocação Especial','Adicionar à mão','Destruir','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34933456,'Invokação Magistus',replace(replace('Invoque por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional, usando monstros da sua mão ou do campo como matéria, incluindo um monstro Mago. \r\nSe você estiver Invocando um Monstro de Fusão "Magistus" desta forma, você também pode usar monstros nas suas Zonas de Magias & Armadilhas que estiverem equipados a um monstro "Magistus". \r\nVocê só pode ativar 1 "Invokação Magistus" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34945480,'Entidade Exterior Azathot',replace(replace('3 monstros de Nível 5	\r\nVocê também pode Invocar este card por Invocação-Xyz ao usar um Monstro Xyz "Entidade Exterior" que você controla como matéria. \r\n(Transfira as matérias dele para este card.) \r\nNão pode ser usado como matéria para uma Invocação-Xyz. \r\nDepois que este card foi Invocado por Invocação-Xyz, seu oponente não pode ativar efeitos de monstro pelo resto desse turno. \r\nSe este card tiver pelo menos 3 Matérias Xyz (1 Monstro de Fusão, 1 Sincro e 1 Xyz): você pode desassociar 1 matéria deste card; destrua todos os cards que seu oponente controla.','\r',char(13)),'\n',char(10)),'Destruir todos os cards que seu oponente controla','Invocar por Invocação Xyz usando seu Monstro Xyz "Entidade Exterior" como matéria?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34950192,'Fusão Lev Sombraneco',replace(replace('Quando este card for ativado: envie 1 Monstro de Fusão do seu Deck Adicional para o Cemitério. \r\nVocê pode oferecer como Tributo 1 Monstro de Fusão; Invoque por Invocação-Especial 1 Monstro de Fusão "Sombraneco" com um Atributo diferente do seu Deck Adicional (isso é considerado uma Invocação-Fusão), mas o ATK dele se torna 0. \r\nVocê só pode usar cada efeito de "Fusão Lev Sombraneco" uma vez por turno e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional no turno em que ativar qualquer um dos efeitos deste card, exceto monstros "Sombraneco".','\r',char(13)),'\n',char(10)),'Ativar','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34959756,'Fóssil Vivo',replace(replace('Ative este card ao escolher 1 monstro de Nível 4 ou menos no seu Cemitério; Invoque-o por Invocação-Especial e equipe-o com este card, mas bana-o quando ele deixar o campo (mesmo que este card deixe o campo). \r\nQuando este card deixar o campo, bana o monstro equipado. \r\nO monstro equipado perde 1000 de ATK/DEF e, além disso, seus efeitos são negados. \r\nVocê só pode ativar 1 "Fóssil Vivo" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34961968,'Besta Fantasma Pégaso-Trovão','Quando um monstro do oponente declarar um ataque: você pode banir este card do seu Cemitério e, depois, escolha 1 monstro "Besta Fantasma" que você controla; esse monstro que você controla não pode ser destruído em batalha neste turno.','Não pode ser destruído em batalha','Escolha 1 monstro cujo nome contenha "Besta Fantasma"','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34966096,'Traidor do Caos',replace(replace('Se este card estiver no seu Cemitério: você pode banir 1 monstro de LUZ e 1 de TREVAS do seu Cemitério, exceto "Traidor do Caos"; Invoque este card por Invocação-Especial em Posição de Defesa, mas bana-o quando ele deixar o campo. \r\nSe este card for Invocado por Invocação-Especial: você pode escolher 1 card no Cemitério do seu oponente; bana-o. \r\nVocê só pode usar cada efeito de "Traidor do Caos" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34968834,'Luzente, o Senhor Inferior do Mundo Negro','Se este card for descartado para o Cemitério por um efeito de card: Invoque este card por Invocação-Especial e, depois, se este card foi descartado da sua mão para o seu Cemitério por um efeito de card do oponente, você pode Invocar por Invocação-Especial em qualquer campo 1 monstro Demônio do seu Deck.','Invocação Especial','Invocar por Invocação Especial do seu Deck?','Invocar por Invocação Especial para o seu Campo','Invocar por Invocação Especial para o Campo do seu oponente','','','','','','','','','','','','');
INSERT INTO texts VALUES(34974462,'Harmonista do Florescer, a Compositora Melodiosa',replace(replace('2 monstros Fada	\r\nSe este card for Invocado por Invocação-Link: você pode descartar 1 card; Invoque por Invocação-Especial 2 monstros "Melodiosa" com Níveis diferentes do seu Deck em zonas suas para as quais este card apontar, em Posição de Defesa. \r\nVocê não pode Invocar monstros por Invocação-Especial no turno em que ativar este efeito, exceto monstros "Melodiosa". \r\nVocê só pode usar este efeito de "Harmonista do Florescer, a Compositora Melodiosa" uma vez por turno. \r\nSe um monstro "Melodiosa" para o qual este card apontar atacar, seu oponente não pode ativar cards ou efeitos até o final da Etapa de Dano.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34976176,'Asanegra - Chinook, a Explosão de Neve',replace(replace('Você pode enviar este card da sua mão ou do campo para o Cemitério e, depois, escolha 1 monstro com a face para cima que seu oponente controla; envie 1 Monstro Sincro "Asanegra" ou 1 "Dragão de Asas Negras" do seu Deck Adicional para o Cemitério e, se isso acontecer, até o final deste turno, o monstro alvo perde 700 de ATK e, além disso, negue seus efeitos. \r\nEste é um Efeito Rápido se você controlar um Monstro Sincro de TREVAS. \r\nVocê só pode usar este efeito de "Asanegra - Chinook, a Explosão de Neve" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34989413,'Reprodoco',replace(replace('2 monstros	\r\nVocê pode ativar 1 desses efeitos.\r\n● Declare 1 Tipo de Monstro; até o final deste turno, todos os monstros com a face para cima para os quais este card apontar se tornam desse Tipo.\r\n● Declare 1 Atributo; até o final deste turno, todos os monstros com a face para cima para os quais este card apontar se tornam desse Atributo.	\r\nVocê só pode usar este efeito de "Reprodoco" uma vez por turno.','\r',char(13)),'\n',char(10)),'Alterar o Tipo','Alterar o Atributo','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34995106,'Marcado em Branco',replace(replace('Invoque por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional, usando monstros da sua mão ou do campo, incluindo um monstro Dragão. \r\nVocê também pode banir monstros do seu Cemitério como matéria se você usar "Caído de Arbaz" como Matéria de Fusão da sua mão, do campo ou ao bani-lo do seu Cemitério. \r\nDurante a Fase Final, se este card estiver no Cemitério porque foi enviado para lá para ativar o efeito de "Caído de Arbaz" neste turno: você pode Baixar este card. \r\nVocê só pode usar cada efeito de "Marcado em Branco" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35011819,'Por Ordem do Imperador','Quando um efeito de monstro que ativa quando um monstro é Invocado por Invocação-Normal for ativado: você pode negar a ativação e, depois, o duelista cuja ativação do efeito foi negada compra 1 card.','Negar e comprar','Negar a ativação do efeito do monstro?','Ativar e aplicar o efeito','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35014241,'Limitar Sobremarcha',replace(replace('Devolva 1 Monstro Sincro Regulador e 1 Monstro Sincro não-Regulador que você controla para o Deck Adicional; Invoque por Invocação-Especial 1 Monstro Sincro do seu Deck Adicional que tenha um Nível igual aos Níveis combinados que os 2 monstros tinham no campo, ignorando suas condições de Invocação. \r\nVocê só pode ativar 1 "Limitar Sobremarcha" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35026117,'Tanque Pesado do Labirinto',replace(replace('Você pode Invocar este card por Invocação-Normal sem oferecer Tributo. \r\nNão pode atacar no turno em que for Invocado por Invocação-Normal. \r\nDurante sua Fase Principal: você pode colocar 1 dos seus "Sanga do Trovão", "Kazejin" ou "Suijin" que estiverem banidos, ou na sua mão ou no Deck, com a face para cima na sua Zona de Magias & Armadilhas como uma Magia Contínua e, depois, se você controlar um card "Paredes do Labirinto", você pode destruir 1 monstro que seu oponente controla. \r\nVocê só pode usar este efeito de "Tanque Pesado do Labirinto" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Normal sem Tributo','','Destruir 1 monstro que seu oponente controla?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35027493,'Vírus Devastador de Decks','Ofereça como Tributo 1 monstro de TREVAS com 2000 ou mais de ATK; olhe a mão do seu oponente, todos os monstros que ele controla e todos os cards que ele comprar até o final do 3º turno dele depois que este card resolver e destrua todos esses monstros com 1500 ou menos de ATK.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35035481,'Paleozoico Olenoides',replace(replace('Escolha 1 Magia/Armadilha no campo; destrua-a. \r\nUma vez por Corrente, quando um Card de Armadilha for ativado enquanto este card estiver no seu Cemitério: Invoque este card por Invocação-Especial como um Monstro Normal (Aqua/ÁGUA/Nível 2/ATK 1200/DEF 0) (este card NÃO é considerado como uma Armadilha). \r\nSe Invocado desta forma, este card não é afetado por efeitos de monstro e, além disso, bana-o quando ele deixar o campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35035985,'Brasas do Cinzento',replace(replace('2 monstros Piro	\r\nSe este card for Invocado por Invocação-Fusão: você pode escolher 1 Magia de Campo no seu Cemitério; adicione-a à sua mão. \r\nNo começo da Etapa de Dano, se este card batalhar um monstro Piro do oponente: você pode destruir esse monstro do oponente e, se for seu turno, este card pode realizar um segundo ataque em seguida. \r\nVocê só pode usar cada efeito de "Brasas do Cinzento" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35037880,'Reflexo do Sabre',replace(replace('Quando você sofrer dano de batalha ou dano de efeito enquanto você controlar um monstro "Sabre-X": ganhe PV igual ao dano que você sofrer e, se isso acontecer, cause a mesma quantidade de dano ao seu oponente e, depois, você pode adicionar 1 Card de Magia/Armadilha "Sabre" ou card "Gottoms" do seu Deck à sua mão. \r\nVocê só pode ativar 1 "Reflexo do Sabre" por turno.','\r',char(13)),'\n',char(10)),'Procurar no Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35050257,'Larva Cibernética',replace(replace('Se este card for escolhido como alvo de um ataque: você não sofre dano de batalha pelo resto deste turno. \r\nQuando este card for destruído em batalha e enviado para o Cemitério: você pode Invocar por Invocação-Especial 1 "Larva Cibernética" do seu Deck.','\r',char(13)),'\n',char(10)),'O dano de batalha se torna 0','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35052053,'Cavaleiro Insecto','De todos os lutadores insecto, ele é o modelo dos Invasores Insecto Indestructíveis, à qual apenas a elite da elite pode entrar. Já não podemos ignorar as suas habilidade de batalha sem rival.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35057188,'Vespabatalha - Grande Partasana, a Revolução',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nNão pode ser destruído por efeitos de card. \r\nMonstros Sincro Inseto que você controla ganham 200 de ATK para cada um dos seus monstros Inseto banidos. \r\nSe este card for banido: você pode Invocá-lo por Invocação-Especial e, depois, você pode destruir cards que seu oponente controla até o número dos seus monstros Inseto banidos e, depois, cause 500 de dano ao seu oponente para cada card destruído. \r\nVocê só pode usar este efeito de "Vespabatalha - Grande Partasana, a Revolução" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Destruir 1 card que seu oponente controla?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35058588,'Onda Cúbica',replace(replace('Escolha 1 monstro "Cúbico(a)" que você controla e 1 monstro com a face para cima que seu oponente controla; o ATK desse monstro que você controla se torna o dobro do seu ATK atual e, se isso acontecer, o ATK desse monstro que seu oponente controla se torna metade do seu ATK atual. \r\nVocê pode banir este card e qualquer número de monstros "Cúbico(a)" do seu Cemitério e, depois, escolher um número de monstros com a face para cima que seu oponente controla igual ao número de monstros "Cúbico(a)" banidos; coloque 1 Marcador Cúbico em cada um deles. \r\n(Monstros com um Marcador Cúbico não podem atacar e, além disso, negue seus efeitos.)','\r',char(13)),'\n',char(10)),'Altere o ATK','Colocar um marcador','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35058857,'Rei Mágico Estrela Lunar',replace(replace('Não pode ser usado como Matéria Sincro, exceto para a Invocação-Sincro de um Monstro Sincro de TREVAS. \r\nSe você controlar um Regulador, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 outro monstro com a face para cima que você controla ou no seu Cemitério; até o final deste turno, o Nível deste card se torna o mesmo que o desse monstro e, além disso, você não pode Invocar por Invocação-Especial, exceto por Invocação-Sincro.','\r',char(13)),'\n',char(10)),'Alterar Nível','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35059553,'Coliseu Kaiser',replace(replace('Quando existirem 1 ou mais monstros no Campo do controlador deste card, o adversário não pode colocar um monstro no Campo se o adversário fosse então ter mais monstros no Campo do que o controlador deste card. \r\nOs cards que estavam no Campo antes da activação deste card não são afectados por este efeito.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35073065,'Furtador Ilusório','Quando você Invocar um monstro por Invocação-Tributo: você pode Invocar este card por Invocação-Especial da sua mão e, se isso acontecer, o Tipo, Atributo e Nível deste card se tornam o mesmo que o desse monstro com a face para cima Invocado por Invocação-Tributo.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35089369,'Pulao, Vento de Yang Zing',replace(replace('Quando este card que você controla for destruído em batalha ou por um efeito de card e enviado para o seu Cemitério: você pode Invocar por Invocação-Especial 1 monstro "Yang Zing" do seu Deck em Posição de Ataque, exceto "Pulao, Vento de Yang Zing". \r\nVocê só pode usar este efeito de "Pulao, Vento de Yang Zing" uma vez por turno. \r\nUma vez por turno, durante a Fase Principal ou a Fase de Batalha do seu oponente, você pode: imediatamente depois que este efeito resolver, Invoque por Invocação-Sincro 1 Monstro Sincro, usando apenas monstros "Yang Zing" que você controla (este é um Efeito Rápido). \r\nUm Monstro Sincro que usou este card como uma Matéria Sincro não é afetado por efeitos de Magia.','\r',char(13)),'\n',char(10)),'Invocação Especial','O efeito de "Pulao, Vento de Yang Zing" está sendo aplicado.','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35095329,'HERÓI Maligno Garras Malignas',replace(replace('Você pode escolher 1 monstro "HERÓI" no campo; Invoque este card por Invocação-Especial da sua mão em Posição de Defesa e, se isso acontecer, esse monstro ganha 300 de ATK. \r\nVocê só pode usar este efeito de "HERÓI Maligno Garras Malignas" uma vez por turno. \r\nSe um ou mais monstros que você controla forem destruídos em batalha ou por um efeito de card, enquanto este card estiver no seu Cemitério: você pode Invocar este card por Invocação-Especial e, depois, se você tiver um monstro que mencione "Fusão Negra" no seu Cemitério, você pode destruir 1 card no campo. \r\nVocê só pode usar este efeito de "HERÓI Maligno Garras Malignas" uma vez por Duelo.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial da mão','Invocar por Invocação Especial do Cemitério','Destruir o card?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35098357,'Confessar Confusão Fazticeira',replace(replace('Invoque por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional, usando monstros da sua mão ou do campo como matéria, incluindo um monstro "Fazticeira". \r\nDurante sua Fase Final, se você controlar um monstro "Fazticeira", enquanto este card estiver no seu Cemitério: você pode adicionar este card à sua mão. \r\nVocê só pode usar 1 efeito de "Confessar Confusão Fazticeira" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35100834,'Autórito, a Bateria Móvel',replace(replace('Invoque este card por Invocação-Especial como um Monstro de Efeito (Máquina/TERRA/Nível 4/ATK 0/DEF 2000) e, depois, você pode equipar a este card 1 monstro Máquina "Dispositivo" de Nível 4 da sua mão ou do Deck.	\r\n(Este card ainda é considerado uma Armadilha.) \r\nSe Invocado desta forma, este card ganha ATK igual ao dobro do ATK do monstro equipado a ele por este efeito.','\r',char(13)),'\n',char(10)),'Equipar?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35103106,'Evolzar Lars',replace(replace('2 monstros de Nível 6	\r\nEnquanto este card tiver matéria, seu oponente não pode escolhê-lo como alvo de efeitos de monstro. \r\nQuando seu oponente ativar um card ou efeito (Efeito Rápido): você pode desassociar 2 matérias deste card, ou apenas 1 matéria se todas as matérias deste card forem Réptil e/ou Dinossauro e, depois, escolha 1 card com a face para cima que seu oponente controla; negue seus efeitos até o final deste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35112613,'Kurifóton',replace(replace('(Efeito Rápido): você pode enviar este card da sua mão para o Cemitério e pagar 2000 PV; você não sofre dano neste turno. \r\nSe este card estiver no seu Cemitério: você pode enviar 1 monstro "Fóton" da sua mão para o Cemitério, exceto "Kurifóton"; adicione este card do seu Cemitério à sua mão. \r\nVocê só pode usar este efeito de "Kurifóton" uma vez por turno.','\r',char(13)),'\n',char(10)),'O dano se torna 0','Retornar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35125879,'O Retorno do Verdadeiro Rei',replace(replace('Se este card for enviado da Zona de Magias & Armadilhas para o Cemitério: você pode escolher 1 monstro no campo; destrua-o. \r\nVocê não pode ativar os seguintes efeitos de "O Retorno do Verdadeiro Rei" na mesma Corrente. \r\nVocê pode escolher 1 monstro "Verdadeiro(a) Draco" ou "Verdadeiro Rei" no seu Cemitério; Invoque-o por Invocação-Especial em Posição de Defesa e, além disso, pelo resto deste turno, você não pode Invocar por Invocação-Especial. \r\nDurante a Fase Principal do seu oponente, você pode: imediatamente depois que este efeito resolver, Invocar por Invocação-Tributo 1 monstro "Verdadeiro(a) Draco" ou "Verdadeiro Rei" com a face para cima. \r\nVocê só pode usar cada efeito de "O Retorno do Verdadeiro Rei" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invoque por Invocação Especial do Cemitério','Invocação Tributo','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35129241,'Desejo da Poeira Estelar',replace(replace('Uma vez por turno, se um Monstro Sincro "Poeira Estelar" que você controla for oferecido como Tributo para ativar seu próprio efeito (exceto durante a Etapa de Dano): você pode escolher esse monstro; Invoque-o por Invocação-Especial. \r\nSeu oponente não pode ativar cards ou efeitos em resposta à ativação deste efeito. \r\nMonstros Invocados por Invocação-Especial por este efeito não podem ser destruídos em batalha enquanto estiverem em Posição de Ataque.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35146019,'Manifestação Altergeist',replace(replace('Escolha 1 monstro "Altergeist" no seu Cemitério; Invoque-o por Invocação-Especial em Posição de Ataque e, se isso acontecer, equipe-o com este card. \r\nQuando este card deixar o campo, destrua esse monstro. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 Armadilha "Altergeist" no seu Cemitério; adicione-a à sua mão. \r\nVocê só pode usar este efeito de "Manifestação Altergeist" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35149085,'Mutilação do Gado','Escolha 1 monstro do Tipo Besta que você controla; devolva-o para a mão e, se isso acontecer, Invoque por Invocação-Especial 1 monstro do Tipo Besta da sua mão com o mesmo Nível que o monstro que foi devolvido para a mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35151572,'Xamã da Cidade Cinzenta',replace(replace('Se "Obsidim, a Cidade Cinzenta" estiver na Zona do Campo, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Xamã da Cidade Cinzenta" por Invocação-Especial uma vez por turno desta forma. \r\nVocê pode escolher 3 dos seus monstros Piro que estiverem banidos e/ou no seu Cemitério; embaralhe-os no Deck e, depois, se você embaralhou um monstro "Cinzento(a)", você pode adicionar 1 "Obsidim, a Cidade Cinzenta" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Xamã da Cidade Cinzenta" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Recuperar um monstro','Adicionar "Obsidim, a Cidade Cinzenta" à sua mão?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35167375,'Fusão Surpresa',replace(replace('Escolha 1 monstro com a face para cima que você controla e, depois, declare 1 Tipo de Monstro e 1 Atributo; esse monstro se torna desse Tipo e Atributo e, depois, você pode Invocar por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional, usando monstros que você controla, incluindo esse monstro. \r\nVocê pode banir este card do seu Cemitério; ofereça como Tributo 1 Monstro de Fusão e, se isso acontecer, Invoque por Invocação-Especial 2 "Ficha de Surpresa" (Mago/TREVAS/ATK 0/DEF 0) com o mesmo Nível que o monstro oferecido como Tributo tinha no campo. \r\nVocê só pode usar este efeito de "Fusão Surpresa" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Fusão','Invocar uma Ficha por Invocação Especial','Invocação Fusão?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35167376,'Ficha de Surpresa','Invocado por Especial com o efeito "Fusão Surpresa".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35183584,'Mardark, o Dragão-Guarda do Legado Mundial',replace(replace('Todos os monstros que seu oponente controla perdem 500 de ATK/DEF para cada monstro Dragão que você controla. \r\nVocê só pode usar cada um dos seguintes efeitos de "Mardark, o Dragão-Guarda do Legado Mundial" uma vez por turno.\r\n● Você pode banir 2 Monstros Normais da sua mão ou do Cemitério; Invoque este card por Invocação-Especial da sua mão.\r\n● Se este card no campo for destruído em batalha ou por um efeito de card: você pode adicionar, do seu Cemitério à sua mão, 1 monstro de Nível 9 com um Tipo e Atributo originais diferentes que o deste card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35183853,'Insígnia Bujin - O Espelho','No começo da sua Fase Principal 1, se seu oponente controlar mais monstros que você e você controlar um monstro "Bujin" do Tipo Besta-Guerreira: até o final do próximo turno do seu oponente, Cards de Magia/Armadilha e seus efeitos não podem ser ativados.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35187185,'Oniro, o Erlking do Espelho Onírico',replace(replace('2 monstros "Espelho Onírico" com Atributos diferentes	\r\nEnquanto estiver com a face para cima no campo, este card também é de Atributo TREVAS. \r\nVocê só pode usar cada um dos seguintes efeitos de "Oniro, o Erlking do Espelho Onírico" uma vez por turno.\r\n● Se outro monstro que você controla for oferecido como Tributo (exceto durante a Etapa de Dano): você pode escolher 1 card no campo; destrua-o.\r\n● Se este card em posse do seu dono for destruído por um card do oponente: você pode Invocar por Invocação-Especial 1 monstro "Espelho Onírico" do seu Cemitério, exceto "Oniro, o Erlking do Espelho Onírico".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35191415,'Mago da Ilusão Negra',replace(replace('O nome deste card se torna "Mago Negro" enquanto estiver no campo. \r\nVocê só pode usar cada um desses efeitos de "Mago da Ilusão Negra" uma vez por turno.\r\n● Durante o turno do seu oponente, se você ativar um Card de Magia/Armadilha ou seus efeitos (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão.\r\n● Se você ativar um Card de Magia/Armadilha ou seus efeitos enquanto este card estiver com a face para cima no seu campo (exceto durante a Etapa de Dano): você pode escolher 1 "Mago Negro" no seu Cemitério; Invoque-o por Invocação-Especial.	\r\nEste efeito só pode ser usado uma vez enquanto este card estiver com a face para cima no campo.','\r',char(13)),'\n',char(10)),'Invoque este card por Invocação Especial da sua mão','Invoque por Invocação Especial 1 "Mago Negro" do seu Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35195612,'Cavaleiro da Poeira','VIRE: Envie 1 monstro de TERRA do seu Deck ao Cemitério.','Adicionar à mão e enviar para o Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35199656,'Trapestrela Lycoris',replace(replace('(Efeito Rápido): você pode revelar este card na sua mão e, depois, escolher 1 monstro "Trapestrela" que você controla, exceto "Trapestrela Lycoris"; Invoque este card por Invocação-Especial e, se isso acontecer, devolva esse monstro para a mão. \r\nSempre que um ou mais cards forem adicionados à mão do seu oponente, cause 200 de dano a ele para cada um.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35209994,'Hordeum Maligno Hraesvelg','VIRE: Escolha 1 card com a face para cima que seu oponente controla; volte o alvo para a mão.','Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35215622,'Goblin Cegamente Leal','Enquanto este card permanecer no Campo com a face para cima, o controle deste cad não pode trocar.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35220244,'Propulsor Gravitacional',replace(replace('Equipe apenas em um monstro do Tipo Máquina. \r\nUma vez por turno: Você pode ativar este efeito; ele ganha 400 de ATK permanentemente. \r\n(Este ganho de ATK permanece mesmo se este card deixar o campo ou se o monstro se tornar imune a efeitos de card.) \r\nSe ele batalhar com um monstro do oponente, o efeito desse monstro é negado apenas durante a Fase de Batalha.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35224440,'Campo de Provas dos Gladiadores','Adicione 1 monstro "Besta Gladiadora" de Nível 4 ou menos do seu Deck à sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35240714,'Combinação do Sabre',replace(replace('Enquanto 10 ou mais monstros "Sabre-X" estiverem no seu campo, Cemitério e/ou banimento, monstros "Sabre-X" que você controla ganham ATK igual à sua DEF original. \r\nVocê só pode usar cada um dos seguintes efeitos de "Combinação do Sabre" uma vez por turno. \r\nSe você Invocar por Invocação-Especial um ou mais monstros "Sabre-X" do Deck Adicional (exceto durante a Etapa de Dano): você pode Invocar por Invocação-Especial 1 monstro "Sabre-X" da sua mão ou do Deck. \r\nQuando um monstro do oponente declarar um ataque: você pode Invocar por Invocação-Especial 1 monstro "Sabre-X" da sua mão.','\r',char(13)),'\n',char(10)),'','Invocação Especial','Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35252119,'Besta do Mundo Virtual - Jiujiu',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nNão pode ser destruído em batalha ou por efeitos de card enquanto você tiver 2 ou mais monstros no seu Cemitério com o mesmo Tipo e Atributo originais, mas nomes diferentes. \r\nVocê pode banir 2 monstros do seu Cemitério com o mesmo Tipo e Atributo originais, mas nomes diferentes e, depois, escolha 1 card no campo; envie-o para o Cemitério. \r\nVocê só pode usar este efeito de "Besta do Mundo Virtual - Jiujiu" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35255456,'Contato Milagroso','Embaralhe no Deck, da sua mão, do campo ou do Cemitério, as Matérias de Fusão que forem mencionadas em um Monstro de Fusão "HERÓI do Elemento" que mencione "Neos, o HERÓI do Elemento" como matéria e, depois, Invoque por Invocação-Especial esse Monstro de Fusão do seu Deck Adicional, ignorando suas condições de Invocação.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35259350,'Universo Sorridente',replace(replace('Invoque por Invocação-Especial tantos Monstros Pêndulo com a face para cima no seu Deck Adicional quanto possível, mas eles têm seus efeitos negados (se houver) e, depois, seu oponente ganha PV igual à soma do ATK original desses monstros Invocados por Invocação-Especial. \r\nVocê não pode Invocar outros monstros por Invocação-Normal ou Especial, nem atacar, durante o turno em que ativar este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35261759,'Pote dos Desejos',replace(replace('Bana 10 cards do topo do seu Deck, com a face para baixo; compre 2 cards. \r\nVocê só pode ativar 1 "Pote dos Desejos" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35262428,'Cálice do Sábio',replace(replace('Se você não controlar nenhum monstro, selecione 1 monstro no Cemitério do oponente. \r\nInvoque-o por Invocação-Especial. \r\nO monstro não pode ser oferecido como Tributo ou usado como um Monstro-Matéria Sincro. \r\nDurante a Fase Final deste turno, ceda o controle desse monstro Invocado por Invocação-Especial ao seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35263180,'Mudas Cuspidoras de Sementes',replace(replace('Uma vez por turno, quando um card ou efeito for ativado que escolha este card no campo como alvo, ou quando este card for alvo de um ataque (Efeito Rápido): você pode Invocar por Invocação-Especial 1 "Ficha de Merenda" (Planta/LUZ/Nível 1/ATK 800/DEF 800). \r\nUma vez por turno, quando seu oponente Invocaria um ou mais monstros por Invocação-Especial (Efeito Rápido): você pode oferecer como Tributo 1 Monstro Normal; negue a Invocação-Especial e, se isso acontecer, destrua esse(s) monstro(s).','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35263181,'Ficha de Merenda','Invocado por Especial com o efeito "Mudas Cuspidoras de Sementes".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35268887,'Tradução de Dano',replace(replace('Reduza pela metade todo o dano de efeito que você sofrer neste turno. \r\nDurante a Fase Final deste turno, Invoque por Invocação-Especial 1 "Ficha de Espectro" (Tipo Demônio/TREVAS/Nível 1/ATK 0/DEF 0) em Posição de Defesa para cada vez que você sofreu dano de efeito neste turno.','\r',char(13)),'\n',char(10)),'Invocar uma Ficha por Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35268888,'Ficha de Espectro','Invocado por Especial com o efeito "Tradução de Dano".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35269904,'Estocada da Tática Tripla',replace(replace('Se seu oponente ativou um efeito de monstro durante este turno: Baixe 1 Magia/Armadilha Normal do seu Deck, exceto "Estocada da Tática Tripla" ou, se seu oponente controlar um monstro, em vez disso, você pode adicioná-la à sua mão. \r\nEsse card Baixado não pode ser ativado neste turno. \r\nVocê só pode ativar 1 "Estocada da Tática Tripla" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35269905,'Estocada da Tática Tripla',replace(replace('Se seu oponente ativou um efeito de monstro durante este turno: Baixe 1 Magia/Armadilha Normal do seu Deck, exceto "Estocada da Tática Tripla" ou, se seu oponente controlar um monstro, em vez disso, você pode adicioná-la à sua mão. \r\nEsse card Baixado não pode ser ativado neste turno. \r\nVocê só pode ativar 1 "Estocada da Tática Tripla" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35272499,'Predaplanta Escorpião Ophrys',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode enviar 1 monstro da sua mão para o Cemitério; Invoque por Invocação-Especial 1 monstro "Predaplanta" do seu Deck, exceto "Predaplanta Escorpião Ophrys". \r\nVocê só pode usar este efeito de "Predaplanta Escorpião Ophrys" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35282433,'Zumbi Prateado de Olhos-Azuis','Dizem que os raios que saem dos olhos desta criatura transformam seus inimigos em zumbis.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35283277,'Eka, o Companheiro Flamejante',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 Card de Monstro com a face para cima na Zona de Magias & Armadilhas de qualquer duelista; Invoque-o por Invocação-Especial no seu campo. \r\nVocê pode escolher 1 outro monstro com a face para cima que você controla; equipe esse monstro com a face para cima a este card como uma Magia de Equipamento que concede a ele 500 de ATK. \r\nVocê só pode usar cada efeito de "Eka, o Companheiro Flamejante" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35306215,'Senhora Obscura Condenada',replace(replace('2 monstros Fada	\r\nVocê pode Invocar por Invocação-Tributo monstros Fada que requerem 2 Tributos ao banir 2 monstros do seu Cemitério em vez de oferecer Tributos (isso ainda é considerado uma Invocação-Tributo). \r\nVocê pode descartar 1 card; pegue 1 monstro "Senhor(a) Obscuro(a)" do seu Deck e adicione-o à sua mão ou envie-o para o Cemitério. \r\nVocê só pode usar este efeito de "Senhora Obscura Condenada" uma vez por turno. \r\nUma vez por turno, durante sua Fase Final: ganhe 500 PV para cada monstro Fada no campo.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Tributo banindo 2 monstros do seu Cemitério','Procurar no Deck','Ganhar PV','Escolha um card para adicionar à sua mão ou enviar para o Cemitério','','','','','','','','','','','','');
INSERT INTO texts VALUES(35307484,'Colher Malívora',replace(replace('Quando um monstro "Malívoro(a)" com um nome diferente for Invocado por Invocação-Normal ou Especial no seu lado do campo (exceto durante a Etapa de Dano): você pode escolher 1 monstro do Tipo Demônio de Nível 2 no seu Cemitério; Invoque o alvo por Invocação-Especial. \r\nSeus efeitos são negados. \r\nVocê só pode usar o efeito de "Colher Malívora" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35311929,'Fengli, o Soldrapom',replace(replace('Se este card for enviado do Deck para o seu Cemitério por um efeito de monstro: você pode Invocar este card por Invocação-Especial e, depois, se você controlar outro monstro Planta, você pode diminuir pela metade o ATK/DEF de 1 monstro no campo. \r\nVocê só pode usar este efeito de "Fengli, o Soldrapom" uma vez por turno. \r\nUma vez por turno, se este card no campo seria destruído em batalha ou por um efeito de card, em vez disso, você pode enviar 1 monstro Planta do seu Deck para o Cemitério.','\r',char(13)),'\n',char(10)),'','Reduzir pela metade o ATK/DEF de 1 monstro?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35316708,'Selo Temporal','Pule a Fase de Compra do próximo turno do seu oponente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35322812,'Inpachi Madeiraborg','A nova forma do enigmático Inpachi, remodelado pelas tecnologias de ponta do Mundo das Trevas. Maneabilidade foi sacrificada em troca de uma armadura mais forte, que foi considerada mais importante.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35329581,'Impulso Sombrio',replace(replace('Quando um ou mais Monstros Sincro que você controla forem destruídos em batalha ou por um efeito de card e enviados para o Cemitério: escolha 1 desses Monstros Sincro; Invoque por Invocação-Especial do seu Deck Adicional, 1 Monstro Sincro com o mesmo Nível e Tipo que esse monstro, mas com um nome diferente. \r\nVocê só pode ativar 1 "Impulso Sombrio" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35330871,'Malacoda, Senhor Inferior do Abismo Ardente',replace(replace('Você pode Invocar este card por Invocação-Ritual com "Bem & Mal no Abismo Ardente". \r\nDeve ser Invocado por Invocação-Ritual e não pode ser Invocado por Invocação-Especial de nenhuma outra forma. \r\nUma vez por turno, durante o turno de qualquer duelista: você pode enviar 1 monstro "Abismo Ardente" da sua mão para o Cemitério e, depois, escolher 1 monstro com a face para cima que seu oponente controla; até o final deste turno, o alvo perde ATK e DEF igual ao ATK e DEF do monstro "Abismo Ardente" enviado para o Cemitério desta forma. \r\nSe este card for enviado do campo para o Cemitério: você pode escolher 1 card no campo; envie-o para o Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35334193,'Força-S Justify',replace(replace('3 Monstros de Efeito, incluindo um monstro "Força-S"	\r\nVocê não pode Invocar/Baixar monstros em uma ou mais zonas para as quais este card apontar. \r\n(Efeito Rápido): você pode escolher 1 Monstro de Efeito com a face para cima que seu oponente controla; negue seus efeitos até o final deste turno e, depois, você pode mover esse monstro do oponente a uma Zona de Monstros dele para a qual este card apontar. \r\nVocê só pode usar este efeito de "Força-S Justify" uma vez por turno. \r\nNo começo da Etapa de Dano, se este card atacar: você pode banir todos os monstros para os quais este card apontar.','\r',char(13)),'\n',char(10)),'','','Mover aquele monstro?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35346968,'Desejos Solenes','Sempre que comprar um ou mais cards, você ganha 500 PV.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35371948,'Palco Iluminado Trapestrela',replace(replace('Quando este card for ativado: você pode adicionar 1 monstro "Trapestrela" do seu Deck à sua mão. \r\nUma vez por turno: você pode escolher 1 card Baixado na Zona de Magias & Armadilhas do seu oponente; enquanto este card estiver na Zona do Campo, esse card Baixado não pode ser ativado até a Fase Final e seu oponente deve ativá-lo durante a Fase Final ou senão, envie-o para o Cemitério. \r\nSempre que um monstro "Trapestrela" que você controla causar dano de batalha ou de efeito ao seu oponente, cause 200 de dano a ele.','\r',char(13)),'\n',char(10)),'Adicionar à sua mão 1 monstro "Trapestrela" do seu Deck?','Restrição de ativação','Escolha 1 card Baixado na Zona de Magias & Armadilhas do seu oponente','Ativar','Enviar para o Cemitério','','','','','','','','','','','');
INSERT INTO texts VALUES(35380371,'Domínio Congelado da Barreira de Gelo',replace(replace('Seu oponente não pode ativar cards ou efeitos em resposta à ativação dos efeitos dos seus monstros "Barreira de Gelo". \r\nSe um ou mais monstros forem Invocados por Invocação-Especial do Deck Adicional (exceto durante a Etapa de Dano): você pode devolver para a mão, ou embaralhar no Deck, 1 monstro "Barreira de Gelo" que você controla e, depois, você pode colocar no fundo do Deck 1 card do campo ou de qualquer Cemitério. \r\nVocê só pode usar este efeito de "Domínio Congelado da Barreira de Gelo" uma vez por turno. \r\nUma vez por turno, durante sua Fase Final: revele 3 monstros "Barreira de Gelo" com nomes diferentes no seu Deck Adicional ou destrua este card.','\r',char(13)),'\n',char(10)),'Retornar ao Deck','Manter este card','Retornar para a mão','Retornar ao Deck','Escolher outro card para retornar ao Deck?','Revelar o card para o seu oponente?','','','','','','','','','','');
INSERT INTO texts VALUES(35394356,'Derruba Daruma',replace(replace('(Efeito Rápido): você pode desassociar 1 matéria de um Monstro Xyz que você controla e, depois, escolha 1 monstro com a face para cima que seu oponente controla; até o final deste turno, mude o ATK dele para 0. \r\nSe um Monstro Xyz que você controla ativaria um efeito ao desassociar uma ou mais matérias, exceto no turno em que este card foi enviado para o Cemitério, você pode banir este card do seu Cemitério em vez de 1 dessas matérias. \r\nVocê só pode usar cada efeito de "Derruba Daruma" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35405755,'Kurikara Divincarnada',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao oferecer como Tributo todos os monstros com a face para cima no campo que ativaram seus efeitos neste turno na Zona de Monstros do seu oponente. \r\nGanha 1500 de ATK para cada monstro oferecido como Tributo para Invocar este card por Invocação-Especial. \r\nDurante sua Fase Final: você pode escolher 1 monstro no Cemitério do seu oponente; Invoque-o por Invocação-Especial no seu campo. \r\nVocê só pode usar este efeito de "Kurikara Divincarnada" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35405756,'Kurikara Divincarnada',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao oferecer como Tributo todos os monstros com a face para cima no campo que ativaram seus efeitos neste turno na Zona de Monstros do seu oponente. \r\nGanha 1500 de ATK para cada monstro oferecido como Tributo para Invocar este card por Invocação-Especial. \r\nDurante sua Fase Final: você pode escolher 1 monstro no Cemitério do seu oponente; Invoque-o por Invocação-Especial no seu campo. \r\nVocê só pode usar este efeito de "Kurikara Divincarnada" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35419032,'Infecção da Infestação','Uma vez por turno: você pode embaralhar no Deck Principal 1 monstro "Hordeum" da sua mão ou com a face para cima no seu lado do campo; adicione 1 monstro "Hordeum" do seu Deck à sua mão.','Procurar no Deck','Usar o efeito de "Infecção da Infestação" agora?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35429292,'Cavaleiro Pixie','Quando este card é enviado para o Cemitério como resultado de um combate, o seu adversário escolhe 1 Card de Magia do seu Cemitério, e esse card é colocado no topo do seu Deck.','Retornar ao Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35448319,'Snyffus',replace(replace('Uma vez por turno, você pode oferecer como Tributo 1 monstro do Tipo Planta para selecionar e destruir 1 card com a face para cima que seu oponente controla. \r\nQuando um ou mais monstros do Tipo Planta no campo forem destruídos enquanto este card estiver no Cemitério, você pode Invocar este card por Invocação-Especial do Cemitério. \r\nSe isso acontecer, remova este card de jogo quando ele for removido do campo.','\r',char(13)),'\n',char(10)),'Destruir','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35464895,'Sinal do Destino','Quando um monstro que você controla for destruído em batalha e enviado para o Cemitério: Invoque por Invocação-Especial 1 monstro "HERÓI do Destino" de Nível 4 ou menos da sua mão ou do Deck.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35479109,'Duplo Tornado de Pó Gêmeo',replace(replace('Escolha qualquer número de cards Baixados na sua Zona de Magias & Armadilhas; devolva este card para a mão, juntamente com tantos desses cards Baixados quanto possível (mín. 1) e, depois, você pode Baixar Magias/Armadilhas da sua mão igual ao número de cards devolvidos à sua mão por este efeito. \r\nVocê só pode ativar 1 "Duplo Tornado de Pó Gêmeo" por turno.','\r',char(13)),'\n',char(10)),'Baixar a mesma quantidade de cards da sua mão?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35480699,'Livro do Eclipse',replace(replace('Coloque todos os monstros que estiverem com a face para cima no campo, com a face para baixo em Posição de Defesa. \r\nDurante a Fase Final deste turno, coloque tantos monstros quanto possível que seu oponente controla que estiverem com a face para baixo em Posição de Defesa, com a face para cima em Posição de Defesa e, depois, seu oponente compra cards igual ao número de monstros colocados com a face para cima por este efeito.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35486099,'Bênção Cristalina','Escolha até 2 monstros "Fera Cristalina" no seu Cemitério; coloque os alvos com a face para cima na sua Zona de Magias & Armadilhas como Magias Contínuas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35487920,'Canal da Live☆Gêmea',replace(replace('Quando um monstro declarar um ataque: você pode oferecer como Tributo 1 monstro "Ki-sikil" ou 1 monstro "Lil-la"; negue o ataque. \r\nDurante a Fase Final: você pode escolher 1 monstro "Ki-sikil" ou 1 monstro "Lil-la" no seu Cemitério; embaralhe-o no Deck, ou, se você não controlar nenhum monstro, em vez disso, você pode adicioná-lo à sua mão. \r\nVocê só pode usar cada efeito de "Canal da Live☆Gêmea" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Retornar ao Deck','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35488287,'Irmandade do Punho de Fogo - Panda',replace(replace('Se você ativar um Card de Magia/Armadilha "Formação de Fogo" (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão e, depois, você pode Invocar por Invocação-Especial 1 monstro "Punho de Fogo" do seu Cemitério, exceto "Irmandade do Punho de Fogo - Panda" e, além disso, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros "Punho de Fogo". \r\nSe um ou mais monstros "Punho de Fogo" que você controla seriam destruídos por um efeito de card do seu oponente, em vez disso, você pode enviar 1 Magia/Armadilha "Formação de Fogo" com a face para cima que você controla para o Cemitério. \r\nVocê só pode usar cada efeito de "Irmandade do Punho de Fogo - Panda" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Invocar um monstro "Punho de Fogo" por Invocação Especial do Cemitério?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35494087,'Velocidaroide Mármore Caveira',replace(replace('Uma vez por turno, durante a Fase de Apoio, se seu oponente controlar um monstro com a face para cima que foi Invocado por Invocação-Especial do Deck Adicional: você pode Invocar este card por Invocação-Especial da sua mão. \r\nNão pode ser destruído em batalha com um monstro Invocado por Invocação-Normal/Baixado. \r\nSeu oponente sofre qualquer dano de batalha que você teria sofrido das batalhas que envolvem este card. \r\nVocê só pode usar este efeito de "Velocidaroide Mármore Caveira" uma vez por turno. \r\nSe você controlar um monstro com a face para cima que não seja um monstro "Velocidaroide", destrua este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35498188,'Magia de Ação - Esterço Duplo',replace(replace('Descarte 1 card; neste turno, se um monstro que você controla atualmente destruir um monstro do oponente em batalha, ele pode realizar um segundo ataque em seguida. \r\nDurante sua Fase Principal, se este card estiver no seu Cemitério, exceto no turno em que este card foi enviado para o Cemitério: você pode descartar 1 Magia; Baixe este card.','\r',char(13)),'\n',char(10)),'Baixar este card','Continuar atacando?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35514096,'Caça Espacial do Senhor Britânico',replace(replace('Se este card destruir um monstro do oponente em batalha: ative 1 desses efeitos;\r\n● Este card pode realizar um segundo ataque em seguida.\r\n● Escolha 1 card Baixado no campo; destrua o alvo.\r\n● Invoque por Invocação-Especial 1 "Ficha Multi" (Máquina/LUZ/Nível 4/ATK 1200/DEF 1200).','\r',char(13)),'\n',char(10)),'Ativar 1 efeito','Você só pode continuar atacando 1 vez','Destruir 1 card Baixado no campo','Invocar 1 "Ficha Multi" por Invocação Especial para o seu campo','','','','','','','','','','','','');
INSERT INTO texts VALUES(35514097,'Ficha Multi','Invocado por Especial com o efeito "Caça Espacial do Senhor Britânico".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35537251,'Boxeador Obstinado Sombrio',replace(replace('Durante sua Fase Principal: você pode desassociar 1 matéria de um Monstro Xyz "Boxeador Obstinado" que você controla e, se isso acontecer, Invoque este card por Invocação-Especial da sua mão. \r\nVocê só pode usar este efeito de "Boxeador Obstinado Sombrio" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35537860,'Onda Explosiva Sinc','Se você controlar um Monstro Sincro: escolha 1 monstro que seu oponente controla; destrua o alvo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35539880,'Direito de Nascença',replace(replace('Ative este card ao escolher 1 Monstro Normal no seu Cemitério; Invoque o alvo por Invocação-Especial em Posição de Ataque. \r\nQuando este card deixar o campo, destrua esse monstro. \r\nQuando esse monstro deixar o campo, destrua este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35544402,'Centelha Constelar',replace(replace('Escolha 1 monstro "Constelar" que você controla; aumente o Nível dele em 1 ou 2. \r\nSe este card estiver no Cemitério: você pode banir 1 monstro "Constelar" do seu Cemitério; adicione este card do Cemitério à sua mão. \r\nVocê só pode usar este efeito de "Centelha Constelar" uma vez por turno.','\r',char(13)),'\n',char(10)),'Aumentar o Nível','Adicionar à mão','Aumentar o Nível em 1','Aumentar o Nível em 2','','','','','','','','','','','','');
INSERT INTO texts VALUES(35546670,'Cicatrizes do Legado Mundial',replace(replace('Todos os monstros "Mekk-Cavaleiro" no campo ganham 300 de ATK/DEF. \r\nUma vez por turno: você pode descartar 1 monstro "Mekk-Cavaleiro" ou 1 card "Legado Mundial"; compre 1 card. \r\nVocê pode banir 8 monstros "Mekk-Cavaleiro" com nomes diferentes do seu Cemitério e/ou com a face para cima no seu campo; envie toda a mão e o Deck Adicional do seu oponente para o Cemitério.','\r',char(13)),'\n',char(10)),'Comprar','Enviar tudo para o Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35550352,'Alma Aniquiladora, Iniciar!',replace(replace('Você pode escolher 1 monstro "Alma Aniquiladora" que você controla; adicione 1 monstro "Alma Aniquiladora" com um Atributo diferente do seu Deck à sua mão. \r\nSe um ou mais monstros "Alma Aniquiladora" que você controla seriam destruídos em batalha ou por um efeito de card, em vez disso, você pode revelar 1 monstro "Alma Aniquiladora" da sua mão. \r\nDurante sua Fase Final, se você controlar 2 ou mais monstros "Alma Aniquiladora": você pode Baixar 1 Armadilha "Alma Aniquiladora" do seu Deck. \r\nVocê só pode usar cada efeito de "Alma Aniquiladora, Iniciar!" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Baixar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35552985,'Sanct do Criademônio',replace(replace('Se você não controlar nenhum monstro com a face para cima, ou os únicos monstros com a face para cima que você controlar forem monstros Demônio de LUZ: Invoque por Invocação-Especial 1 "Ficha de Criademônio" (Demônio/LUZ/Nível 1/ATK 0/DEF 0) e, além disso, você não pode declarar ataques pelo resto deste turno, exceto com monstros Demônio. \r\nSe um ou mais monstros "Criademônio" com a face para cima que você controla forem destruídos por um efeito de card do oponente, enquanto este card estiver no seu Cemitério: você pode Baixar este card. \r\nVocê só pode usar cada efeito de "Sanct do Criademônio" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Baixar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35552986,'Ficha de Criademônio','Invocado por Especial com o efeito "Sanct do Criademônio".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35561352,'Golpe Divino de Zefra','Quando um Card de Magia/Armadilha ou efeito de monstro for ativado: bana 1 monstro "Zefra" com a face para cima no seu Deck Adicional; negue a ativação e, se isso acontecer, destrua-o.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35563539,'Mística do Espelho',replace(replace('Ative apenas quando um Card de Magia que escolha 1 duelista como alvo for ativado. \r\nO efeito desse Card de Magia é aplicado ao outro duelista em vez disso.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35565537,'Bruxa das Trevas','Uma criatura popular da mitologia que realiza ataques letais com uma lança afiada.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35569555,'Dogmatikamatriz',replace(replace('Quando este card for ativado: você pode adicionar 1 Monstro de Ritual "Dogmatika" ou 1 Magia de Ritual "Dogmatika" do seu Deck à sua mão e, depois, se seu oponente controlar um monstro, você pode adicionar 1 card "Dogmatika" do seu Deck à sua mão. \r\nUma vez por turno, se você controlar um Monstro de Ritual "Dogmatika": você pode olhar o Deck Adicional de qualquer duelista e enviar 1 monstro de lá para o Cemitério. \r\nVocê só pode ativar 1 "Dogmatikamatriz" por turno.','\r',char(13)),'\n',char(10)),'Adicionar à sua mão 1 Card Magia Ritual "Dogmatika" do seu Deck?','Adicionar à sua mão outro card "Dogmatika" do seu Deck?','','Revelar o seu Deck Adicional','Revelar o Deck Adicional do seu oponente','','','','','','','','','','','');
INSERT INTO texts VALUES(35577420,'Espiral de Luz','Cada vez que um ou mais cards forem enviados do seu Deck ao Cemitério pelo efeito de um monstro "Luminoso(a)", remova do jogo o card do topo do Deck do seu oponente.','Banir o card do topo do Deck do seu oponente','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35595518,'Linkassassino',replace(replace('Se você não controlar nenhum monstro, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nUma vez por turno: você pode descartar até 2 cards e, depois, escolher esse número de Magias/Armadilhas no campo; destrua-as.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35606858,'Rei dos Mestres Arquidemônio',replace(replace('2 monstros Demônio	\r\nUma vez por turno, durante sua Fase de Apoio, pague 500 PV ou destrua este card. \r\nUma vez por Corrente, se você pagar PV (exceto durante a Etapa de Dano): você pode enviar 1 monstro Demônio com ATK ou DEF igual ao valor pago do seu Deck para o Cemitério. \r\nUma vez por Corrente, se um ou mais monstros Demônio forem enviados para o seu Cemitério (exceto durante a Etapa de Dano): você pode lançar um dado de seis faces e, depois, aplicar este efeito em 1 desses monstros, de acordo com o resultado.\r\n● 1: Adicione-o à sua mão.\r\n● 2, 3, 4, 5: Embaralhe-o no Deck.\r\n● 6: Invoque-o por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Enviar para o Cemitério 1 monstro Demônio do seu Deck','Lançar 1 dado','Manter "Rei dos Mestres Arquidemônio"?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35614780,'Dragão da Sublimação Final de Luz',replace(replace('Você pode banir 1 monstro Dragão de Nível 8 do seu Deck Adicional; Invoque este card por Invocação-Especial da sua mão e, além disso, você não pode Invocar por Invocação-Especial pelo resto deste turno, exceto monstros Dragão. \r\nDurante sua Fase Principal: você pode Invocar por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional, usando monstros da sua mão ou do campo. \r\nQuando um monstro do oponente declarar um ataque: você pode fazer com que este card perca exatamente 500 de ATK/DEF e, se isso acontecer, esse monstro do oponente perde 1500 de ATK. \r\nVocê só pode usar cada efeito de "Dragão da Sublimação Final de Luz" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial da mão','Invocação Fusão','Reduzir ATK/DEF','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35618217,'Caleido Filhote Luzlunar',replace(replace('Uma vez por turno: você pode enviar 1 monstro "Luzlunar" do seu Deck ou Deck Adicional para o Cemitério; o nome deste card com a face para cima no campo pode ser considerado como o desse monstro enviado, se for usado como Matéria de Fusão neste turno. \r\nSe este card for enviado para o Cemitério por um efeito de card: você pode escolher 1 "Polimerização" no seu Cemitério; adicione-o à sua mão. \r\nVocê só pode usar este efeito de "Caleido Filhote Luzlunar" uma vez por turno. \r\nSe este card for banido: você pode ativar este efeito; neste turno, os cards e efeitos do seu oponente não podem ser ativados durante a Fase de Batalha.','\r',char(13)),'\n',char(10)),'Matéria de substituição','Adicionar "Polimerização/Fusão" do seu Cemitério à sua mão','Seu oponente não pode ativar efeitos durante a Fase de Batalha','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35618486,'Ferrão Hordeum Ferro','Quando este card que você controla for enviado para o seu Cemitério: Escolha 1 Monstro de Ritual, de Fusão ou Sincro com a face para cima no campo; destrua o alvo.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35622739,'Cavaleiro-Gema Quartzo',replace(replace('Se seu oponente controlar um monstro: você pode descartar este card; Baixe 1 Magia Contínua "Fusão" diretamente do seu Deck e, além disso, você não pode Invocar monstros por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto monstros "Cavaleiro-Gema". \r\nSe este card for usado como matéria para uma Invocação-Fusão e enviado para o Cemitério ou banido: você pode adicionar à sua mão 1 monstro "Cavaleiro-Gema" do seu Cemitério, exceto "Cavaleiro-Gema Quartzo". \r\nVocê só pode usar cada efeito de "Cavaleiro-Gema Quartzo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35629124,'Dragão-de-Kidmodo',replace(replace('Se este card for enviado para o Cemitério: você pode Invocar por Invocação-Especial 1 monstro do Tipo Dragão da sua mão. \r\nVocê não pode Invocar monstros por Invocação-Especial, exceto monstros do Tipo Dragão, nem conduzir sua Fase de Batalha, no turno em que ativar este efeito. \r\nVocê só pode usar este efeito de "Dragão-de-Kidmodo" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35631584,'Carta Celeste Constelar','Uma vez por turno, quando um ou mais Monstros Xyz "Constelar" forem Invocados por Invocação-Especial no seu lado do campo (exceto durante a Etapa de Dano): você pode comprar 1 card.','Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35638627,'Lombriga Senhor da Guerra',replace(replace('Este card não pode ser Invocado por Invocação-Especial. \r\nNegue os efeitos de Monstros de Efeito destruídos em batalha com este card. \r\nSe este card destruir um monstro do oponente em batalha, ele pode atacar mais uma vez, em sequência.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35645105,'Colheitadeira Infinisteira',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 monstro "Infinisteira" do seu Deck à sua mão, exceto "Colheitadeira Infinisteira". \r\nVocê pode escolher 1 outro monstro Máquina que você controla; até o final deste turno, os Níveis tanto desse monstro quanto deste card se tornam os Níveis originais combinados desses 2 monstros. \r\nVocê só pode usar cada efeito de "Colheitadeira Infinisteira" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35659410,'Visão com Azul nos Olhos',replace(replace('Quando você ativar este card: você pode revelar 1 "Dragão Branco de Olhos Azuis" na sua mão; Invoque por Invocação-Especial 1 monstro da sua mão. \r\nUma vez por turno: você pode escolher 1 monstro com a face para cima que você controla; devolva esse monstro com a face para cima para a mão e, depois, você pode aplicar o seguinte efeito, de acordo com o nome original do card devolvido para a mão.\r\n● "Dragão Branco de Olhos Azuis": Invoque por Invocação-Especial 1 monstro da sua mão.\r\n● Outro: Invoque por Invocação-Especial 1 monstro "Olhos Azuis" da sua mão.	\r\nVocê só pode ativar 1 "Visão com Azul nos Olhos" por turno.','\r',char(13)),'\n',char(10)),'Revelar "Dragão Branco de Olhos Azuis" e Invocar por Invocação Especial um monstro da sua mão?','Invocar por Invocação Especial um monstro da sua mão?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35686187,'Tragédia','Quando um ou mais monstros com a face para cima em Posição de Ataque que seu oponente controla forem colocados com a face para cima em Posição de Defesa: destrua todos os monstros em Posição de Defesa que seu oponente controla.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35686188,'Tragédia','Quando um ou mais monstros com a face para cima em Posição de Ataque que seu oponente controla forem colocados com a face para cima em Posição de Defesa: destrua todos os monstros em Posição de Defesa que seu oponente controla.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35697544,'Espada das Chamas Lutadora',replace(replace('Ative 1 desses efeitos;\r\n● Adicione 1 card do seu Deck à sua mão que mencione "Espadachim das Chamas", exceto "Espada das Chamas Lutadora".\r\n● Quando um ataque for declarado envolvendo um monstro Guerreiro de FOGO que você controla: você pode escolher 1 card no campo; destrua-o.\r\n● Quando seu oponente ativar um card ou efeito que escolha como alvo "Espadachim das Chamas", ou um ou mais monstros que o mencionem, que você controla: negue o efeito.	\r\nVocê só pode ativar 1 "Espada das Chamas Lutadora" por turno.','\r',char(13)),'\n',char(10)),'Procurar um card que mencione "Espadachim das Chamas"','Destruir 1 card no campo','Negar os efeitos do seu oponente','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35705817,'Fusão Fantasma',replace(replace('Invoque por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional, usando apenas monstros Zumbi que você controla como matéria. \r\nSe você tiver menos PV que seu oponente, você também pode banir até 1 monstro Zumbi da sua mão, do Deck ou do Cemitério como matéria. \r\nVocê só pode ativar 1 "Fusão Fantasma" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35712107,'Pássaro Monstruoso','Poucos cruzaram com este pássaro mergulhão e viveram para contar a história.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35726888,'Espólios do Enterro Tolo',replace(replace('Envie 1 Magia/Armadilha do seu Deck para o Cemitério. \r\nVocê só pode ativar 1 "Espólios do Enterro Tolo" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35752363,'Pardal Vermillion','"Rhaimundos da Espada Vermelha" + "Fireyarou"','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35756798,'Cruz Final',replace(replace('Durante o seu turno, se um ou mais Monstros Sincro foram enviados para o seu Cemitério neste turno: escolha 1 Monstro Sincro que você controla; ele pode realizar um segundo ataque durante cada Fase de Batalha neste turno e, além disso, se você ativou este card ao escolher um Monstro Sincro com "Guerreiro(a)", "Sincron" ou "Poeira Estelar" em seu nome original, você pode fazer com que ele ganhe ATK igual ao ATK de 1 Monstro Sincro no seu Cemitério. \r\nVocê só pode ativar 1 "Cruz Final" por turno.','\r',char(13)),'\n',char(10)),'','Escolher um monstro para aumentar seu ATK?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35762283,'Coração do Desfavorecido','Durante sua Fase de Compra, quando você comprar um ou mais Monstros Normais: você pode revelá-los; compre mais 1 card.','Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35763582,'Sabuja Prateada Luzlunar',replace(replace('Se este card for enviado para o Cemitério por um efeito de card: você pode Invocar por Invocação-Especial 1 monstro "Luzlunar" do seu Deck, exceto "Sabuja Prateada Luzlunar", mas você não pode Invocar por Invocação-Especial do Deck Adicional, exceto monstros "Luzlunar", enquanto você controlar esse monstro com a face para cima. \r\nQuando um Card de Magia/Armadilha ou seus efeitos forem ativados no campo (Efeito Rápido): você pode banir este card e 1 Monstro de Fusão "Luzlunar" do seu Cemitério; negue a ativação. \r\nVocê só pode usar cada efeito de "Sabuja Prateada Luzlunar" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Negar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35770983,'Dinolutador Anqui Marcial',replace(replace('Durante o cálculo de dano, se outro monstro "Dinolutador" que você controla batalhar um monstro do oponente (Efeito Rápido): você pode enviar este card da sua mão ou do campo para o Cemitério; esse monstro que você controla não pode ser destruído nessa batalha e, além disso, o ATK do monstro do oponente que está batalhando é diminuído pela metade no final da Etapa de Dano. \r\nDurante a Fase Final, se este card estiver no Cemitério porque foi enviado do campo para lá neste turno: você pode Invocar este card por Invocação-Especial, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar este efeito de "Dinolutador Anqui Marcial" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35772782,'Número 67: Par-de-Dados Esmagador',replace(replace('2+ monstros de Nível 5	\r\nUma vez por turno, durante sua Fase Principal 1: você pode desassociar 2 matérias deste card; cada duelista lança um dado de seis faces duas vezes. \r\nAté o final do próximo turno, o duelista com o maior total não pode ativar efeitos de monstro ou declarar um ataque. \r\nUma vez por turno, se qualquer duelista lançar um ou mais dados de seis faces enquanto este card tiver matéria, você pode considerar um dos resultados como 7.','\r',char(13)),'\n',char(10)),'','Alterar o resultado do dado?','Escolha o número do dado a alterar','O efeito de "Número 67: Par-de-Dados Esmagador" está sendo aplicado.','','','','','','','','','','','','');
INSERT INTO texts VALUES(35778533,'Cuidado com a Floresta Branca',replace(replace('Se você controlar um monstro Ilusão ou Mago de Nível 6 ou mais: escolha 1 card que seu oponente controla; destrua-o. \r\nSe este card for enviado para o Cemitério para ativar um efeito de monstro: você pode Baixar este card. \r\nVocê só pode usar cada efeito de "Cuidado com a Floresta Branca" uma vez por turno.','\r',char(13)),'\n',char(10)),'Destruir 1 card','Baixar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35781051,'Força Arcana III - A Imperatriz',replace(replace('Se este card for Invocado: lance uma moeda.\r\n● Cara: Quando seu oponente Invocar um monstro por Invocação-Normal/Baixar: você pode Invocar por Invocação-Especial 1 monstro "Força Arcana" da sua mão.\r\n● Coroa: Sempre que seu oponente Invocar um monstro por Invocação-Normal/Baixar: envie 1 card da sua mão para o Cemitério.','\r',char(13)),'\n',char(10)),'Jogar uma moeda','Invocação Especial','Enviar 1 card da sua mão para o Cemitério','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35787450,'Horror Eterno','Coloque 2 Marcadores de Relógio em cada "Prisão da Torre do Relógio".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35798491,'Arquidemônio Bispo das Trevas',replace(replace('Uma vez por turno, durante sua Fase de Apoio, você deve pagar 500 PV (isso não é opcional), ou este card é destruído. \r\nQuando estiver resolvendo um efeito de card do oponente que escolha como alvo um monstro "Arquidemônio" que você controla, lance um dado de seis faces e negue esse efeito se o resultado for um 1, 3 ou 6 e, se isso acontecer, destrua esse card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35800511,'Manopla Samurai Superpesado Alma Demolidora',replace(replace('Você pode escolher 1 monstro "Samurai Superpesado" que você controla; equipe este monstro da sua mão ou do campo no alvo. \r\nEle ganha 400 de DEF. \r\nDurante a Etapa de Dano de qualquer duelista, quando um monstro "Samurai Superpesado" em Posição de Defesa que você controla batalhar um monstro do oponente e você não tiver Cards de Magia/Armadilha no seu Cemitério: você pode enviar este card da sua mão para o Cemitério; até o final deste turno, a DEF do seu monstro que está batalhando se torna o dobro da DEF original.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35803249,'Jinzo - Senhor',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao enviar 1 "Jinzo" com a face para cima que você controla para o Cemitério. \r\nOs Cards de Armadilha, bem como seus efeitos no campo, não podem ser ativados. \r\nNegue todos os efeitos de Armadilha no campo. \r\nUma vez por turno: você pode destruir tantas Armadilhas com a face para cima no campo quanto possível e, se isso acontecer, cause 300 de dano ao seu oponente para cada card destruído.','\r',char(13)),'\n',char(10)),'Destruir todos os Cards de Armadilha com a face para cima','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35809262,'Homem-Alado das Chamas, o HERÓI do Elemento',replace(replace('"Aviário, o HERÓI do Elemento" + "Burstinatrix, o HERÓI do Elemento"	\r\nDeve ser Invocado por Invocação-Fusão. \r\nQuando este card destruir um monstro em batalha e enviá-lo para o Cemitério: cause dano ao seu oponente igual ao ATK do monstro destruído no Cemitério.','\r',char(13)),'\n',char(10)),'Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35809263,'Homem-Alado das Chamas, o HERÓI do Elemento',replace(replace('"Aviário, o HERÓI do Elemento" + "Burstinatrix, o HERÓI do Elemento"	\r\nDeve ser Invocado por Invocação-Fusão. \r\nQuando este card destruir um monstro em batalha e enviá-lo para o Cemitério: cause dano ao seu oponente igual ao ATK do monstro destruído no Cemitério.','\r',char(13)),'\n',char(10)),'Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35815783,'Mundo Magichave',replace(replace('Quando este card for ativado: você pode adicionar 1 monstro "Magichave" do seu Deck à sua mão. \r\nNa primeira vez que cada Monstro Normal que não seja uma Ficha que você controla seria destruído em batalha ou por um efeito de card a cada turno, ele não é destruído. \r\nDurante sua Fase Principal: você pode adicionar 1 "Maftea Magichave" do seu Deck à sua mão e, depois, coloque 1 card da sua mão no fundo do Deck. \r\nVocê só pode usar este efeito de "Mundo Magichave" uma vez por turno. \r\nVocê só pode ativar 1 "Mundo Magichave" por turno.','\r',char(13)),'\n',char(10)),'Adicionar à sua mão 1 monstro "Magichave" do seu Deck?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35817848,'Transmissão Sincro',replace(replace('Durante a Fase Principal: imediatamente depois que este efeito resolver, Invoque por Invocação-Sincro 1 Monstro Sincro usando monstros que você controla como matéria. \r\nDurante sua Fase Principal, exceto no turno em que este card foi enviado para o Cemitério: você pode banir este card do seu Cemitério e, depois, escolha 1 Monstro Sincro no seu Cemitério; devolva-o para o Deck Adicional e, depois, compre 1 card. \r\nVocê só pode usar cada efeito de "Transmissão Sincro" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35818851,'Shiranui Samurai',replace(replace('(Efeito Rápido): você pode banir 1 monstro Zumbi do seu Cemitério; este card ganha 600 de ATK e, se isso acontecer, depois do cálculo de dano, bana qualquer monstro que batalhar este card. \r\nEsses efeitos duram até o final deste turno. \r\nSe este card for banido: você pode escolher 1 monstro "Shiranui" no seu Cemitério, exceto "Shiranui Samurai"; adicione-o à sua mão. \r\nVocê só pode usar cada efeito de "Shiranui Samurai" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35834119,'Lâmpada Peixe',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nSe este card for enviado para o Cemitério como Matéria Sincro: você pode Invocar por Invocação-Especial 2 "Ficha de Lâmpada" (Peixe/FOGO/Nível 2/ATK 0/DEF 0) e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto monstros Peixe. \r\nSe você controlar um Monstro Sincro Peixe: você pode banir este card do seu Cemitério e, depois, escolha 1 card no campo; destrua-o. \r\nVocê só pode usar cada efeito de "Lâmpada Peixe" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar uma Ficha por Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35834120,'Ficha de Lâmpada','Invocado por Especial com o efeito "Lâmpada Peixe".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35842855,'Pirorex, o Senhor Elemental',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao ter exatamente 5 monstros de FOGO no seu Cemitério. \r\nQuando este card for Invocado por Invocação-Especial: você pode escolher 1 monstro que seu oponente controla; destrua-o e, se isso acontecer, os dois duelistas sofrem dano igual à metade do ATK original do monstro destruído. \r\nVocê só pode usar este efeito de "Pirorex, o Senhor Elemental" uma vez por turno. \r\nSe este card com a face para cima deixar o campo, pule a Fase de Batalha do seu próximo turno.','\r',char(13)),'\n',char(10)),'Destrua e cause dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35844557,'Espada de Ryzeal',replace(replace('Se você tiver um monstro "Ryzeal" no seu campo ou Cemitério, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nSe Invocado desta forma, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto Monstros Xyz de Classe 4. \r\nVocê só pode Invocar "Espada de Ryzeal" por Invocação-Especial uma vez por turno desta forma. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 monstro Piro de LUZ do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Espada de Ryzeal" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial da mão','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35848254,'Condutor de Fóton','Invoque por Invocação-Especial 1 monstro de LUZ de Nível 4 ou menos da sua mão com a face para cima em Posição de Ataque.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35866404,'Grandaríete','Se seu oponente controlar um Monstro Xyz com a face para cima, você pode Invocar este card por Invocação-Especial (da sua mão) com a face para cima em Posição de Ataque.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35870016,'Golpe Final Gouki',replace(replace('Escolha 1 Monstro Link "Gouki" que você controla; até o final deste turno, ele ganha ATK igual ao seu Valor Link x 1000 e, além disso, se ele atacar um monstro em Posição de Defesa neste turno, cause dano de batalha perfurante ao seu oponente. \r\nPelo resto deste turno depois que este card resolver, você não pode declarar ataques, exceto com monstros "Gouki". \r\nVocê só pode ativar 1 "Golpe Final Gouki" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35871958,'Festival Fantardil',replace(replace('1 monstro "Fantardil" que não seja Link	\r\nVocê também pode usar um monstro "Fantardil" com a face para baixo que você controla como matéria para Invocar este card por Invocação-Link. \r\nEnquanto um card "Fantardil" estiver na Zona do Campo, seus monstros "Fantardil" podem atacar diretamente. \r\nQuando um monstro do oponente declarar um ataque: você pode oferecer este card como Tributo; Invoque por Invocação-Especial 1 monstro "Fantardil" do seu Deck com a face para baixo em Posição de Defesa. \r\nVocê só pode usar este efeito de "Festival Fantardil" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35877582,'Aiwass, o Espírito Mágico Magistus',replace(replace('1 monstro "Magistus" + 1 monstro Mago	\r\nEnquanto este card for um Card de Equipamento, o monstro equipado ganha 1000 de ATK/DEF. \r\nDurante a Fase Principal (Efeito Rápido): você pode escolher 1 outro monstro com a face para cima no campo; equipe este card que você controla a ele. \r\nSe este card foi equipado a um monstro do oponente por este efeito, tome o controle do monstro equipado e, além disso, ele não pode ativar seus efeitos. \r\nVocê só pode usar este efeito de "Aiwass, o Espírito Mágico Magistus" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35884610,'U.A. Jersey Potencializada',replace(replace('Só pode ser equipado a um monstro "U.A.". \r\nEle ganha 1000 de ATK e DEF e, além disso, se ele batalhar um monstro do oponente, qualquer dano de batalha que ele causar ao seu oponente é dobrado. \r\nSe o monstro equipado destruir um monstro no seu ataque: ele pode realizar um segundo ataque durante esta Fase de Batalha. \r\nDurante sua Fase de Apoio: bana o monstro equipado. \r\nSe este card for enviado para o Cemitério porque o monstro equipado foi devolvido para a mão: você pode devolver este card para a mão.','\r',char(13)),'\n',char(10)),'Continuar atacando','Retornar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35886170,'Goblindbergh Gogogo',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode Invocar por Invocação-Especial 1 monstro "Gogogo" não-Guerreiro da sua mão, do Deck ou do Cemitério e, depois, se este card estiver em Posição de Ataque, coloque-o em Posição de Defesa e, além disso, pelo resto deste turno, você não pode Invocar por Invocação-Especial do Deck Adicional, exceto Monstros Xyz. \r\nSe este card for desassociado de um Monstro Xyz para ativar o efeito desse monstro: você pode adicionar 1 monstro "Dododo" do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "Goblindbergh Gogogo" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35906693,'Compra Brilhante',replace(replace('Para ativar este card, você deve comprá-lo em sua compra normal na sua Fase de Compra, revelá-lo e mantê-lo revelado até a Fase Principal 1. \r\nDurante sua Fase Principal 1 nesse mesmo turno: você pode escolher 1 Monstro Xyz "Utopia" que você controla e, depois, ativar 1 desses efeitos;\r\n● Equipe qualquer número de monstros "ZW -" com nomes diferentes do seu Deck/Deck Adicional a ele.\r\n● Invoque por Invocação-Especial do seu Deck Adicional, 1 Monstro Xyz "Utopia" com um nome diferente que o do alvo, usando o alvo como matéria. \r\n(Isso é considerado uma Invocação-Xyz. Transfira as matérias dele para o monstro Invocado.)','\r',char(13)),'\n',char(10)),'Manter "Compra Brilhante" revelado?','Equipar','Invocação Xyz','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35911108,'Comandante Iniciador',replace(replace('Todos os outros monstros Ciberso que você controla ganham 300 de ATK/DEF. \r\nUma vez por turno: você pode oferecer como Tributo 1 monstro Ciberso e, depois, escolher 1 monstro com a face para cima que seu oponente controla; destrua-o.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35950025,'Cavaleiro da Galáxia',replace(replace('Se você controlar um monstro "Fóton" ou "Galáxia", você pode Invocar este card por Invocação-Normal sem oferecer Tributo. \r\nSe Invocado desta forma: escolha 1 "Dragão de Fóton de Olhos das Galáxias" no seu Cemitério (se possível); independente disso, este card perde 1000 de ATK e, se isso acontecer, Invoque o alvo (se houver) por Invocação-Especial em Posição de Defesa. \r\nEssa diminuição do ATK dura até o final deste turno.','\r',char(13)),'\n',char(10)),'Invocação Normal sem Tributo','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35952884,'Dragão da Explosão Quasar',replace(replace('1 Monstro Sincro Regulador + 2+ Monstros Sincro não-Reguladores	\r\nDeve ser Invocado por Invocação-Sincro. \r\nPode atacar um número de vezes a cada Fase de Batalha, até o número de não-Reguladores usados para sua Invocação-Sincro. \r\nUma vez por turno, quando um card ou efeito for ativado (Efeito Rápido): você pode negar a ativação e, se isso acontecer, destrua-o. \r\nQuando este card com a face para cima deixar o campo: você pode Invocar por Invocação-Especial 1 "Dragão da Explosão Estelar" do seu Deck Adicional.','\r',char(13)),'\n',char(10)),'Negar seus efeitos e destruí-lo','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35952885,'Dragão da Explosão Quasar',replace(replace('1 Monstro Sincro Regulador + 2+ Monstros Sincro não-Reguladores	\r\nDeve ser Invocado por Invocação-Sincro. \r\nPode atacar um número de vezes a cada Fase de Batalha, até o número de não-Reguladores usados para sua Invocação-Sincro. \r\nUma vez por turno, quando um card ou efeito for ativado (Efeito Rápido): você pode negar a ativação e, se isso acontecer, destrua-o. \r\nQuando este card com a face para cima deixar o campo: você pode Invocar por Invocação-Especial 1 "Dragão da Explosão Estelar" do seu Deck Adicional.','\r',char(13)),'\n',char(10)),'Negar seus efeitos e destruí-lo','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35956022,'Tempestade Ácida','Todos os monstros de TERRA perdem 500 de ATK e ganham 400 de DEF.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35960413,'Tacada do Cupido',replace(replace('Se todos os monstros que você controla forem monstros com 600 de DEF (mín. 1): você pode Invocar este card por Invocação-Especial da sua mão. \r\n(Efeito Rápido): você pode descartar 1 card e, depois, escolha 1 monstro Fada de LUZ que você controla e 1 monstro com a face para cima no campo; até o final deste turno, o Nível do seu monstro se torna o Nível do outro monstro. \r\nVocê só pode usar cada efeito de "Tacada do Cupido" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35975813,'Rei do Terror Arquidemônio',replace(replace('Não pode ser Invocado por Invocação-Normal ou Virar a não ser que você controle um monstro "Arquidemônio". \r\nUma vez por turno, durante sua Fase de Apoio, você deve pagar 800 PV (isso não é opcional), ou este card é destruído. \r\nQuando estiver resolvendo um efeito de card do oponente que escolha este card como alvo, lance um dado de seis faces e negue esse efeito se o resultado for um 2 ou 5 e, se isso acontecer, destrua esse card. \r\nNegue os efeitos de Monstros de Efeito destruídos em batalha com este card (incluindo no Cemitério).','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35984222,'Ido, a Força Mágica Suprema',replace(replace('Você não pode Invocar monstros ou Baixá-los Normalmente. \r\nVocê só pode controlar 1 "Ido, a Força Mágica Suprema". \r\nUma vez por turno, durante a Fase de Apoio do próximo turno depois que este card foi destruído por um efeito de card e enviado para o Cemitério: Invoque este card por Invocação-Especial do Cemitério e, se isso acontecer, destrua todos os outros monstros que você controla.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35989913,'Elo Sem Fim',replace(replace('(Este card deve ser sempre considerado como um card "Xyz".)	\r\nQuando este card for ativado: você pode Invocar por Invocação-Especial 1 "Número 39: Utopia" do seu Cemitério e, se isso acontecer, ele ganha ATK igual ao ATK combinado de todos os Monstros Xyz "Utopia" e "Utópico" de LUZ no seu Cemitério. \r\nQuando um Monstro Xyz "Utopia" ou "Utópico" atacante seu cujo Atributo original seja LUZ destruir um monstro do oponente em batalha: você pode fazer com que seu monstro perca exatamente 1000 de ATK e, se isso acontecer, ele pode atacar novamente em seguida. \r\nVocê só pode ativar 1 "Elo Sem Fim" por turno.','\r',char(13)),'\n',char(10)),'Ativar','Continuar atacando','Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35998832,'Zohah, o Infinito Ogdoádico',replace(replace('Se este card for enviado do campo para o Cemitério ou Invocado por Invocação-Especial do Cemitério: você pode ativar este efeito; seu oponente compra 1 card e, se isso acontecer, você adiciona 1 monstro "Ogdoádico(a)" do seu Deck à sua mão, exceto "Zohah, o Infinito Ogdoádico" e, depois, cada duelista envia 1 card da mão dele para o Cemitério. \r\nSe este card estiver no seu Cemitério: você pode enviar 1 card da sua mão para o Cemitério; adicione este card à sua mão. \r\nVocê só pode usar cada efeito de "Zohah, o Infinito Ogdoádico" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36006208,'Lago de Fogo do Abismo Ardente','Envie 2 monstros "Abismo Ardente" com a face para cima que você controla para o Cemitério e, depois, escolha até 3 cards no campo; destrua os alvos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36010310,'Nunu, o Remanescente Ogdoádico',replace(replace('Você pode enviar este card da sua mão para o Cemitério; envie 1 monstro Réptil de TREVAS do seu Deck para o Cemitério. \r\nSe você não controlar nenhum monstro ou controlar um monstro "Ogdoádico(a)": você pode Invocar este card por Invocação-Especial do seu Cemitério, mas bana-o quando ele deixar o campo e, além disso, você não pode Invocar monstros por Invocação-Especial, exceto monstros Réptil, enquanto este card estiver com a face para cima na Zona de Monstros. \r\nVocê só pode usar cada efeito de "Nunu, o Remanescente Ogdoádico" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36016907,'Jack Caveira de Abóbora',replace(replace('Você pode descartar 1 monstro Zumbi; Invoque este card por Invocação-Especial da sua mão. \r\nDurante a Fase Principal do seu oponente (Efeito Rápido): você pode escolher 1 monstro Zumbi em qualquer Cemitério; Invoque esse monstro por Invocação-Especial (mas bana-o quando ele deixar o campo) e, depois, bana este card com a face para cima até a Fase Final. \r\nVocê só pode usar cada efeito de "Jack Caveira de Abóbora" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36021814,'Rei dos Servos Caveira',replace(replace('O ATK original deste card é o número combinado de "Rei dos Servos Caveira" e "Servo Caveira" no seu Cemitério x 1000. \r\nQuando este card for destruído em batalha e enviado para o Cemitério: você pode banir 1 outro "Rei dos Servos Caveira" ou 1 "Servo Caveira" do seu Cemitério; Invoque este card por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36029076,'Horror de Cem-Pés','Se seu oponente controlar um monstro e você não controlar nenhum, você pode Invocar este card por Invocação-Normal sem oferecer Tributo, mas seu ATK original se torna 1300.','Invocar sem oferecer monstros como Tributo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36033786,'Mago Ciberso','Uma vez por turno: você pode escolher 1 monstro em Posição de Ataque do oponente; coloque-o em Posição de Defesa e, se isso acontecer, pelo resto deste turno, seus monstros não podem atacar, exceto atacar esse monstro, e se um monstro Ciberso seu atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36039163,'Cavaleiro Pinguim','Quando este card for enviado diretamente do seu Deck para o Cemitério pelo efeito de um card controlado por seu oponente, junte os cards do seu Cemitério e do seu próprio Deck, embaralhe-os e forme um novo Deck.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36042004,'Bebecerassauro','Se este card for destruído por um efeito de card e enviado para o Cemitério: Invoque por Invocação-Especial 1 monstro Dinossauro de Nível 4 ou menos do seu Deck.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36042825,'Varinha Descartável',replace(replace('Só pode ser equipado a um monstro do Tipo Mago. \r\nEle ganha 800 de ATK. \r\nSe o monstro equipado atacar ou for atacado, depois do cálculo de dano: você pode destruir este card e, se isso acontecer, compre 1 card.','\r',char(13)),'\n',char(10)),'Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36045450,'Magos Unidos','Se você controlar 2 ou mais monstros Mago em Posição de Ataque: escolha 1 deles; o ATK dele se torna 3000 até o final deste turno e, além disso, pelo resto deste turno depois que este card resolver, outros monstros Mago que você controla não podem atacar.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36046926,'Marefolha Silvestre',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode selecionar um número entre 1 ou 2 e, depois, escavar esse número de cards do topo do seu Deck, enviar quaisquer monstros escavados do Tipo Planta para o Cemitério e, além disso, colocar os outros cards no fundo do seu Deck em qualquer ordem. \r\nSe este card for escavado do Deck e enviado para o Cemitério por um efeito de card: você pode escolher 1 monstro no campo; destrua o alvo.','\r',char(13)),'\n',char(10)),'Revelar o Deck','Escolha quantos deseja revelar','Destruir','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36076683,'Número 73: Suntuoso do Abismo',replace(replace('2 monstros de ÁGUA de Nível 5	\r\nUma vez por turno (Efeito Rápido): você pode desassociar 1 matéria deste card; dobre o ATK deste card até o final do turno do seu oponente e, além disso, qualquer dano de batalha que ele causar ao seu oponente neste turno é diminuído pela metade.','\r',char(13)),'\n',char(10)),'Dobrar o ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36088082,'Touro Laminador','Quando um ataque for declarado envolvendo este card e um monstro do oponente: você pode ativar este efeito; durante esta batalha envolvendo este monstro, nenhum duelista sofre qualquer dano de batalha e, além disso, destrua o monstro do oponente depois do cálculo de dano.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36092504,'Justiceiro Baioneta',replace(replace('Aplique esses efeitos, em sequência, dependendo do(s) tipo(s) de monstro(s) "Callibre" que você controla e no seu Cemitério. \r\nSe você controlar um monstro com 3000 ou mais de ATK, seu oponente não pode ativar cards ou efeitos em resposta à ativação deste card.\r\n● Fusão: Bana 1 monstro que seu oponente controla.\r\n● Sincro: Bana, com a face para cima, 3 cards aleatórios, que estiverem com a face para baixo, do Deck Adicional do seu oponente.\r\n● Xyz: Bana 1 Magia/Armadilha que seu oponente controla.\r\n● Link: Bana até 3 cards do Cemitério do seu oponente.	\r\nVocê só pode ativar 1 "Justiceiro Baioneta" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36099130,'Zoroa, o Magistus das Chamas',replace(replace('Você pode escolher 1 monstro "Magistus" que você controla; equipe-o com 1 monstro "Magistus" do seu Deck Adicional. \r\nSe este card se tornar equipado com um Card de Monstro "Magistus": você pode Invocar por Invocação-Especial 1 monstro Mago de Nível 4 da sua mão ou do Cemitério em Posição de Defesa, exceto "Zoroa, o Magistus das Chamas", mas seus efeitos são negados. \r\nVocê só pode usar cada efeito de "Zoroa, o Magistus das Chamas" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36099620,'Reino da Luz',replace(replace('Sempre que um ou mais cards forem enviados do seu Deck para o Cemitério, coloque 1 Marcador de Brilho neste card. \r\nTodos os monstros "Luminoso(a)" ganham 100 de ATK para cada Marcador de Brilho neste card. \r\nSe este card seria destruído por um efeito de card, em vez disso, remova 2 Marcadores de Brilho deste card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36100154,'Espírito Lutador de Amazoness','Se um monstro "Amazoness" seu atacar um monstro com maior ATK, o monstro atacante ganha 1000 de ATK apenas durante o cálculo de dano.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36107810,'Feiticeiro do Fim da Noite','Quando este card for Invocado por Invocação-Especial: você pode escolher até 2 cards no Cemitério do seu oponente; bana-os.','Banir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36111775,'Parada Pêndulo',replace(replace('Se você tiver 3 ou mais Monstros Pêndulo com a face para cima com nomes diferentes no seu Deck Adicional: compre 2 cards. \r\nVocê não pode adicionar cards do Deck à sua mão pelo resto deste turno depois que este card resolver.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36114945,'Yuki-Onna, a Mayakashi Sincelo',replace(replace('2+ monstros Zumbi	\r\nVocê só pode controlar 1 "Yuki-Onna, a Mayakashi Sincelo". \r\nVocê só pode usar cada um dos seguintes efeitos de "Yuki-Onna, a Mayakashi Sincelo" uma vez por turno. \r\nSe este card for Invocado por Invocação-Especial: você pode escolher 1 Monstro de Efeito que seu oponente controla; negue seus efeitos. \r\n(Efeito Rápido): você pode banir este card do seu Cemitério; Invoque por Invocação-Especial 1 dos seus Monstros Sincro Zumbi que estiverem banidos ou no seu Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36119641,'Lua-Do-Mar Espacial','Uma lua-do-mar espacial flutuando no universo. Diz-se que este fóssil vivo foi desenterrado de uma civilização antiga em Alphard4.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36121917,'Monstro Ovo','Um guerreiro escondido dentro de um ovo que ataca inimigos arremessando cascas de ovo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36148308,'Vida Extrema',replace(replace('Só pode ser equipado a um Monstro Sincro de TERRA. \r\nSe o monstro equipado batalhar um monstro do oponente, o monstro do oponente perde 1500 de ATK apenas durante esse cálculo de dano. \r\nUma vez por turno, se a posição de batalha de um monstro for mudada (exceto durante a Etapa de Dano): você pode escolher 1 card no campo; destrua-o. \r\nSe este card for enviado da Zona de Magias & Armadilhas para o Cemitério: você pode oferecer como Tributo 1 Monstro Sincro "Ferramenteiro"; Invoque por Invocação-Especial 1 "Dragão do Fluxo de Vida" do seu Deck Adicional. \r\n(Isso é considerado uma Invocação-Sincro.)','\r',char(13)),'\n',char(10)),'Destrua 1 card no campo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36151751,'Cavaleiro Arma','Um guerreiro amonita que protegeu os mares ao longo da história.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36183881,'Tornado Majespectro','Ofereça como Tributo 1 monstro Mago de VENTO e, depois, escolha 1 monstro que seu oponente controla; bana-o.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36187051,'Xenoguitarra da Banda de Rock',replace(replace('Se este card for enviado para o Cemitério: você pode escolher 1 monstro Rocha no seu Cemitério, exceto "Xenoguitarra da Banda de Rock"; adicione-o à sua mão e, depois, coloque 1 card da sua mão no topo do Deck. \r\nSe este card for banido do campo ou Cemitério: você pode enviar 1 monstro Rocha do seu Deck para o Cemitério. \r\nVocê só pode usar cada efeito de "Xenoguitarra da Banda de Rock" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36197902,'Colapso do Legado Mundial',replace(replace('Você pode banir 1 monstro "Legado Mundial" da sua mão, do Cemitério ou com a face para cima no campo e, depois, escolher 1 Monstro Link no campo; ele ganha ATK igual ao ATK original do monstro banido (mesmo que este card deixe o campo). \r\nSe um ou mais Monstros Link que você controla forem destruídos em batalha ou por um efeito de card do oponente enquanto este card estiver no seu Cemitério: você pode banir este card; Invoque por Invocação-Especial 1 Monstro Link Ciberso do seu Cemitério. \r\nVocê só pode usar cada efeito de "Colapso do Legado Mundial" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36205132,'Filo, o Mensageiro de Peluguel',replace(replace('Durante sua Fase Principal: você pode Invocar por Invocação-Especial 1 monstro "de Peluguel" da sua mão, exceto "Filo, o Mensageiro de Peluguel". \r\nSe um monstro "de Peluguel" for Invocado por Invocação-Especial no seu campo enquanto você controlar este monstro (exceto durante a Etapa de Dano): você pode escolher 1 monstro "de Peluguel" no seu Cemitério; Invoque-o por Invocação-Especial em Posição de Defesa, mas coloque-o no fundo do Deck se ele deixar o campo. \r\nVocê só pode usar cada efeito de "Filo, o Mensageiro de Peluguel" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36211150,'Bitron','Uma nova espécie encontrada no espaço eletrônico. Não há muita informação sobre ela.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36218106,'Ministro Psíquico Silenciado',replace(replace('Se você controlar um monstro Psíquico que não seja "Ministro Psíquico Silenciado", você pode Invocar este card por Invocação-Especial (da sua mão) em Posição de Defesa. \r\nVocê só pode Invocar "Ministro Psíquico Silenciado" por Invocação-Especial uma vez por turno desta forma. \r\nVocê pode banir este card e 1 monstro Psíquico do seu Cemitério e, depois, escolha 1 monstro com a face para cima no campo; bana-o até a Fase Final. \r\nVocê só pode usar este efeito de "Ministro Psíquico Silenciado" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Banir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36224040,'Magia de Aumento de Classe Força Zexal',replace(replace('Escolha 1 Monstro Xyz que você controla; Invoque por Invocação-Especial do seu Deck Adicional, 1 monstro "Utopia" ou "ZW -" que seja 1 Classe maior que esse monstro que você controla, usando-o como matéria e, se isso acontecer, pegue 1 monstro "ZW -" ou "ZS -" do seu Deck e coloque-o no topo do seu Deck. \r\n(Isso é considerado uma Invocação-Xyz. Transfira as matérias dele para o monstro Invocado.) \r\nSe os PV do seu oponente forem pelo menos 2000 a mais que os seus: você pode banir este card do seu Cemitério; compre 1 card. \r\nVocê só pode usar este efeito de "Magia de Aumento de Classe Força Zexal" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Escolha o(s) card(s) para colocar no topo do Deck','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36227804,'Besta Gishki','Quando este card for Invocado por Invocação-Normal: você pode escolher 1 monstro "Gishki" de Nível 4 ou menos no seu Cemitério; Invoque o alvo por Invocação-Especial em Posição de Defesa.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36239585,'Fada Fantardil',replace(replace('Não pode ser Invocado por Invocação-Normal, a não ser que você controle um monstro "Fantardil". \r\nUma vez por turno: você pode colocar este card com a face para baixo em Posição de Defesa. \r\nQuando este card for virado com a face para cima: você pode escolher 1 card "Fantardil" no seu Cemitério; Baixe esse card (mas bana-o quando ele deixar o campo) e, depois, você pode colocar monstros com a face para cima que seu oponente controla com a face para baixo em Posição de Defesa, até o número de cards Baixados que você controla.','\r',char(13)),'\n',char(10)),'','','Mudar um monstro do seu oponente para a Posição de Defesa com a face para baixo?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36247316,'Os Cavaleiros Fantasmas da Manopla Perdida',replace(replace('Escolha 1 monstro com a face para cima no campo; se o alvo ainda estiver com a face para cima no campo, os monstros "Os Cavaleiros Fantasmas" que você controla não podem ser destruídos em batalha e, além disso, o alvo perde 600 de ATK e, além disso, o Nível dele se torna 2. \r\nEsses efeitos duram até o final deste turno. \r\nDepois, Invoque este card por Invocação-Especial em Posição de Defesa como um Monstro Normal (Guerreiro/TREVAS/Nível 2/ATK 600/DEF 0).	\r\n(Este card NÃO é considerado como uma Armadilha.)','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36256625,'Super Veicroide Perfuratriz Gigante',replace(replace('"Vaporoide" + "Perfuroide" + "Submariroide"	\r\nA Invocação-Fusão deste card só pode ser feita com as Matérias de Fusão acima. \r\nSe este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36261276,'Transportador Interdimensional de Matéria','Escolha 1 monstro com a face para cima que você controla; bana o alvo até a Fase Final.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36262024,'Filhote do Dragão Negro','Você pode enviar este card com a face para cima que você controla para o Cemitério; Invoque por Invocação-Especial 1 "Dragão Negro de Olhos Vermelhos" da sua mão.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36270527,'Ars Magna da Finidade e Infinidade',replace(replace('Você pode banir este card da sua mão; adicione 1 monstro não-Guerreiro "Ars Magna" do seu Deck à sua mão, também o ATK original do Link "Patrono(a) do Poder".\r\nSe um ou mais Monstros Link e/ou Fusão são Invocados por Invocação-Especial enquanto este card está banido: você pode Invocar este card por Invocação-Especial.\r\nSe você controla um Monstro Link "Patrono(a) do Poder": você pode escolher 1 monstro no campo; bana-o.\r\nVocê só pode usar cada um dos efeitos de "Ars Magna da Finidade e Infinidade" uma vez por turno.','\r',char(13)),'\n',char(10)),'Efeito de busca','Invocação Especial','Efeito de banimento','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36278828,'Serpente da Peçonha','Uma vez por turno, você pode colocar 1 Marcador de Veneno em 1 monstro que seu oponente controla.','Colocar um marcador','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36280194,'Soldado de Reforço','Enquanto houver 5 ou mais monstros no seu Cemitério: escolha até 3 Monstros que não sejam de Efeito com 1500 ou menos de ATK no seu Cemitério; adicione-os à sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36304921,'Fantasma Sarcástico','Vestido com um smoking preto como a noite, esta criatura preside à morte.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36318200,'Uniflora, Besta Mística da Floresta','Se todos os monstros no seu Cemitério forem monstros Besta: você pode oferecer este card como Tributo; Invoque por Invocação-Especial 1 monstro Besta da sua mão ou do Cemitério, exceto "Uniflora, Besta Mística da Floresta", mas ele não pode atacar neste turno.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36319131,'Dragão das Chamas Lutador',replace(replace('1 monstro Dragão + 1 monstro Guerreiro de FOGO	\r\nExceto durante a Etapa de Dano (Efeito Rápido): você pode escolher 1 Monstro de Fusão Guerreiro que você controla; equipe este card do seu campo ou Cemitério a esse monstro que você controla como uma Magia de Equipamento. \r\nVocê só pode usar este efeito de "Dragão das Chamas Lutador" uma vez por turno. \r\nEnquanto este card estiver equipado com "Espadachim das Chamas" ou um monstro que o mencione, o monstro equipado ganha 700 de ATK e pode realizar um segundo ataque durante cada Fase de Batalha.','\r',char(13)),'\n',char(10)),'Considerar como Card de Equipamento','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36320744,'Angélica, Princesa das Armas Nobres',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Especial: você pode adicionar 1 "Chifre do Olifante", ou 1 card que mencione "Infernobre Cavaleiro Imperador Charles", do seu Deck à sua mão. \r\nQuando um card ou efeito for ativado que escolha este card no campo como alvo, ou quando este card for alvo de um ataque (Efeito Rápido): você pode enviar 1 monstro Guerreiro de FOGO do seu Deck para o Cemitério e, se isso acontecer, bana este card (até a Fase Final) e, depois, você pode Invocar por Invocação-Especial 1 monstro "Roland" do seu Deck ou Deck Adicional. \r\nVocê só pode usar cada efeito de "Angélica, Princesa das Armas Nobres" uma vez por turno.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Banir este card','Invocar por Invocação Especial do Deck/Deck Adicional?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36322312,'Almirante de Inicialização - Dínamo de Destruição',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao enviar 2 Cards de Monstro "Dispositivo" da sua mão e/ou do campo com a face para cima para o Cemitério. \r\nNão pode ser destruído em batalha ou por efeitos de card enquanto você controlar um monstro "Dispositivo" ou um Card de Monstro "Dispositivo" equipado a um monstro. \r\nUma vez por turno: você pode escolher 1 outro card no campo; destrua-o.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36326160,'Live☆Gêmea Ki-sikil',replace(replace('Sempre que um monstro do oponente declarar um ataque, você ganha 500 PV. \r\nSe este card for Invocado por Invocação-Normal ou Especial e você não controlar nenhum outro monstro: você pode Invocar por Invocação-Especial 1 monstro "Lil-la" da sua mão ou do Deck. \r\nVocê só pode usar este efeito de "Live☆Gêmea Ki-sikil" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36328300,'Magia Cristalina Definitiva',replace(replace('Quando um monstro "Fera Cristalina" seu for destruído em batalha: você pode enviar para o Cemitério 7 cards "Fera Cristalina" com nomes diferentes da sua mão, do Deck e/ou do campo com a face para cima; Invoque por Invocação-Especial 1 Monstro de Fusão "Cristalino(a) Definitivo(a)" do seu Deck Adicional. \r\n(Isso é considerado uma Invocação-Fusão.) \r\nSe um monstro "Cristalino(a) Definitivo(a)" com a face para cima que você controla deixar o campo devido a um efeito de card do oponente: você pode banir este card do seu Cemitério; coloque qualquer número de monstros "Fera Cristalina" do seu Cemitério, com a face para cima na sua Zona de Magias & Armadilhas como Magias Contínuas.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36331074,'Reeze, Redemoinho de Gusto','Uma vez por turno: Você pode devolver 1 card da sua mão para o fundo do Deck para escolher 1 monstro que seu oponente controla e 1 monstro "Gusto" com a face para cima que você controla; troque o controle de ambos os monstros.','Trocar o controle','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36346532,'Paleozoico Cambroraster',replace(replace('2 monstros "Paleozoico"	\r\nNão é afetado pelos efeitos de outros monstros. \r\nVocê só pode usar cada um dos seguintes efeitos de "Paleozoico Cambroraster" uma vez por turno. \r\nVocê pode escolher 1 card Baixado na Zona de Magias & Armadilhas; envie-o para o Cemitério e, se isso acontecer, Baixe 1 Armadilha "Paleozoico" diretamente do seu Deck. \r\nEla pode ser ativada neste turno. \r\nSe um ou mais cards Baixados que você controla seriam destruídos por um efeito de card, em vez disso, você pode banir este card do seu campo ou Cemitério.','\r',char(13)),'\n',char(10)),'','Ativar aplicando o efeito de "Paleozoico Cambroraster".','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36350300,'Arte Ritual Superior',replace(replace('Este card pode ser usado para a Invocação-Ritual de qualquer Monstro de Ritual do seu Deck. \r\nVocê também deve oferecer como Tributo Monstros Normais da sua mão cuja soma dos Níveis seja igual ao Nível do Monstro de Ritual que você Invocou por Invocação-Ritual. \r\nEmbaralhe esse Monstro de Ritual no Deck durante a Fase Final do seu oponente. \r\nVocê só pode ativar 1 "Arte Ritual Superior" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36352429,'Dragão Vampiro','Quando este card Invocado por Invocação-Tributo for enviado do campo para o Cemitério: você pode adicionar 1 monstro de Nível 4 ou menos do seu Deck à sua mão.','Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36354007,'Gilford, o Relâmpago',replace(replace('Você pode oferecer 3 monstros como Tributo para Invocar este card por Invocação-Tributo (mas não para Baixar). \r\nSe Invocado desta forma: destrua todos os monstros que seu oponente controla.','\r',char(13)),'\n',char(10)),'Ofereça 3 monstros como Tributo para Invocar','Destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36354008,'Gilford, o Relâmpago',replace(replace('Você pode oferecer 3 monstros como Tributo para Invocar este card por Invocação-Tributo (mas não para Baixar). \r\nSe Invocado desta forma: destrua todos os monstros que seu oponente controla.','\r',char(13)),'\n',char(10)),'Ofereça 3 monstros como Tributo para Invocar','Destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36361633,'Rugido Ameaçador','Seu oponente não pode declarar um ataque neste turno.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36368606,'Cinet Atualização',replace(replace('Quando um monstro Ciberso do oponente declarar um ataque: destrua todos os monstros nas Zonas de Monstros Principais. \r\nDurante a Fase Final deste turno, Invoque por Invocação-Especial do Cemitério, nos campos dos seus donos, tantos Monstros Link Ciberso quanto possível que foram destruídos por este efeito. \r\nQuando um monstro do oponente ativar seu efeito: você pode banir este card do seu Cemitério; até o final deste turno, Monstros Link Ciberso que você controla atualmente não são afetados por efeitos de card, exceto seus próprios.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36376145,'Golpe da Alma',replace(replace('Se seus PV forem 4000 ou menos, quando um ataque for declarado envolvendo um monstro que você controla e um monstro do oponente: pague metade dos seus PV e, depois, escolha 1 monstro com a face para cima que você controla; até o final do turno do seu oponente, ele ganha ATK igual ao déficit entre seus PV atuais e 4000. \r\nVocê só pode ativar 1 "Golpe da Alma" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36378044,'Murro Afortunado',replace(replace('Uma vez por turno, quando um monstro do oponente declarar um ataque: Você pode lançar uma moeda 3 vezes. \r\nSe o resultado for 3 Caras, compre 3 cards, mas se o resultado for 3 Coroas, destrua este card. \r\nSe este card com a face para cima no campo for destruído: Você perde 6000 PV.','\r',char(13)),'\n',char(10)),'Role um dado','Usar o efeito de "Murro Afortunado" agora?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36378213,'Ambulânciroide','Quando um ou mais monstros "roide" forem adicionados do seu Cemitério à sua mão (exceto durante a Etapa de Dano): você pode Invocá-lo por Invocação-Especial.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36400569,'Serviço de Marionetes do Espetáculo',replace(replace('Escolha monstros que seu oponente controla, até o número de Monstros Xyz "Engenhoca Marionete" que você controla; tome o controle desses monstros até a Fase Final. \r\nSe este card estiver no seu Cemitério, exceto no turno em que foi enviado para lá, e você controlar um Monstro Xyz "Engenhoca Marionete": você pode banir este card e, depois, escolha 1 Monstro Xyz em qualquer Cemitério; Invoque-o por Invocação-Especial em qualquer campo em Posição de Defesa. \r\nVocê só pode usar cada efeito de "Serviço de Marionetes do Espetáculo" uma vez por turno.','\r',char(13)),'\n',char(10)),'Tome o controle de um monstro que seu oponente controla','Invocar por Invocação Especial para o seu campo ou para o campo do seu oponente','Invocar por Invocação Especial para o seu Campo','Invocar por Invocação Especial para o Campo do seu oponente','','','','','','','','','','','','');
INSERT INTO texts VALUES(36405256,'Sorciere de Fleur',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: escolha 1 monstro no Cemitério do seu oponente; Invoque-o por Invocação-Especial no seu campo, mas ele não pode atacar seu oponente diretamente e é destruído durante a Fase Final deste turno. \r\nVocê só pode usar este efeito de "Sorciere de Fleur" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36407615,'Rei do Caos Arquidemônio',replace(replace('1 Regulador do Tipo Demônio + 1 ou mais monstros não-Reguladores	\r\nQuando este card declarar um ataque: até o final da Fase de Batalha, você pode trocar o ATK e DEF atuais de todos os monstros com a face para cima que seu oponente controla.','\r',char(13)),'\n',char(10)),'Trocar ATK e DEF','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36415522,'Pequena Ajuda do Camarartista',replace(replace('Uma vez por turno, quando um monstro do oponente declarar um ataque direto: você pode negar o ataque e, se isso acontecer, Invoque por Invocação-Especial 1 monstro "Camarartista" do seu Deck, mas seus efeitos são negados. \r\nQuando um ataque for declarado envolvendo um monstro que você controla e um monstro do oponente: você pode enviar este card para o Cemitério; você não sofre dano de batalha dessa batalha.','\r',char(13)),'\n',char(10)),'Usar o efeito?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36426778,'Os Cavaleiros Fantasmas das Botas Silenciosas',replace(replace('Se você controlar um monstro "Os Cavaleiros Fantasmas", você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Os Cavaleiros Fantasmas das Botas Silenciosas" por Invocação-Especial uma vez por turno desta forma. \r\nVocê pode banir este card do seu Cemitério; adicione 1 Magia/Armadilha "Cavaleiros Fantasmas" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Os Cavaleiros Fantasmas das Botas Silenciosas" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36429703,'Ataqueraptor - Sábio Strix',replace(replace('2 monstros Besta Alada de TREVAS	\r\nSe este card for Invocado por Invocação-Link: você pode Invocar por Invocação-Especial 1 monstro Besta Alada de TREVAS de Nível 4 do seu Deck em Posição de Defesa, mas negue seus efeitos e, além disso, ele não pode ser usado como Matéria Link. \r\nSe um efeito de um Monstro Xyz "Ataqueraptor" seu for ativado: Baixe 1 Magia "Magia de Aumento de Classe" do seu Deck e, se for uma Magia Rápida, ela pode ser ativada neste turno. \r\nVocê só pode usar cada efeito de "Ataqueraptor - Sábio Strix" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Ativar aplicando o efeito de "Ataqueraptor - Sábio Strix".','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36436372,'Engenhoca Marionete Soldadinhos',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode enviar 1 monstro "Engenhoca Marionete" com um Nível diferente que o deste card do seu Deck para o Cemitério; o Nível deste card se torna o desse monstro. \r\nVocê só pode usar este efeito de "Engenhoca Marionete Soldadinhos" uma vez por turno. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha até 2 monstros "Engenhoca Marionete" que você controla; aumente o Nível deles em 4 até o final deste turno.','\r',char(13)),'\n',char(10)),'Enviar para o Cemitério para alterar o Nível','Aumentar o Nível','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36442179,'Asanegra - Furacão, o Tornado','Uma vez por turno: você pode escolher 1 Monstro Sincro no campo; até o final deste turno, o ATK deste card se torna o ATK atual desse monstro.','Alterar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36458063,'Golpe da Bruxa','Se seu oponente negar a Invocação-Normal ou Especial de um ou mais monstros ou a ativação de um card ou efeito: destrua todos os cards que seu oponente controla e na mão dele.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36468556,'Cessar-Fogo','Se um monstro com a face para baixo em Posição de Defesa ou um Monstro de Efeito estiverem no campo: coloque com a face para cima em Posição de Defesa todos os monstros que estiverem no campo com a face para baixo em Posição de Defesa (os efeitos de monstros de Virar não são ativados neste momento) e, além disso, cause 500 de dano ao seu oponente para cada Monstro de Efeito no campo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36472900,'Filhote Sônico','Não pode ser destruído em batalha com um monstro que tenha 1900 ou mais de ATK.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36484016,'Fusão Sincro Milagrosa',replace(replace('Invoque por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional que liste um Monstro Sincro como matéria, ao banir Matérias de Fusão listadas nele do seu campo ou do Cemitério. \r\nSe este card Baixado for destruído por um efeito de card do seu oponente e enviado para o seu Cemitério: compre 1 card.','\r',char(13)),'\n',char(10)),'Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36492575,'Marincesa Cavalo Marinho',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) em uma zona sua para a qual um Monstro Link "Marincesa" apontar. \r\nVocê só pode Invocar "Marincesa Cavalo Marinho" por Invocação-Especial uma vez por turno desta forma. \r\nDurante sua Fase Principal, exceto no turno em que este card foi enviado para o Cemitério: você pode banir este card do seu Cemitério; Invoque por Invocação-Especial 1 monstro de ÁGUA da sua mão em uma zona sua para a qual um Monstro Link "Marincesa" apontar. \r\nVocê só pode usar este efeito de "Marincesa Cavalo Marinho" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36494597,'Fusão de Teleporte',replace(replace('Durante a Fase Principal: Invoque por Invocação-Fusão 1 Monstro de Fusão Psíquico do seu Deck Adicional, ao banir monstros Psíquico do seu campo ou Cemitério como matéria. \r\nSe um ou mais monstros Psíquico com a face para cima que você controla que foram Invocados por Invocação-Especial do Deck Adicional forem destruídos em batalha ou por um efeito de card: você pode banir este card do seu Cemitério e, depois, escolha 1 dos seus monstros Psíquico banidos; Invoque-o por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Fusão de Teleporte" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Fusão','Invocar por Invocação Especial um monstro banido','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36499284,'Formação de Fogo - Yoko',replace(replace('Quando este card for ativado: você pode escolher 1 card com a face para cima que seu oponente controla; descarte 1 monstro Besta-Guerreira e, se isso acontecer, destrua esse card. \r\nTodos os monstros Besta-Guerreira que você controla ganham 100 de ATK.','\r',char(13)),'\n',char(10)),'Escolher 1 card com a face para cima que seu oponente controla para destruir?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36521307,'Mechamático Circular',replace(replace('Você pode enviar 1 monstro "Mechamático(a)", exceto "Mechamático Circular" do seu Deck para o seu Cemitério; Invoque este card por Invocação-Especial da sua mão e, além disso, você só pode atacar com 1 monstro pelo resto deste turno. \r\nSe um monstro "Mechamático(a)" for Invocado por Invocação-Normal ou Especial no seu campo enquanto você controlar este monstro (exceto durante a Etapa de Dano): você pode adicionar 1 Magia/Armadilha "Mechamático(a)" do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "Mechamático Circular" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36521459,'Dragão da Poeira Estelar Pernicioso',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao banir 1 "Dragão da Poeira Estelar" do seu Deck Adicional. \r\nSó pode haver 1 monstro "Pernicioso(a)" no campo. \r\nMagias de Campo com a face para cima não podem ser destruídas por efeitos de card. \r\nOutros monstros que você controla não podem declarar um ataque. \r\nSe não houver Magias de Campo com a face para cima no campo, destrua este card.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36523152,'Samurai Superpesado Grande Waraji',replace(replace('Se você não tiver nenhum Card de Magia/Armadilha no seu Cemitério, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nDepois que este card foi Invocado por Invocação-Especial desta forma, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros "Samurai Superpesado". \r\nEste card pode ser considerado como 2 Tributos para a Invocação-Tributo de um monstro do Tipo Máquina.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36527535,'Camarartista Dançarina Revue',replace(replace('Se seu oponente controlar um monstro e você não controlar nenhum monstro, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nEste card pode ser considerado como 2 Tributos para a Invocação-Tributo de um monstro "Camarartista".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36539330,'Panda Golpeador',replace(replace('Se 2 ou mais monstros Besta-Guerreira estiverem no campo, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Panda Golpeador" por Invocação-Especial uma vez por turno desta forma. \r\nSe este card for enviado do campo para o seu Cemitério: você pode escolher 1 monstro com a face para cima que você controla; ele ganha 500 de ATK. \r\nVocê só pode usar este efeito de "Panda Golpeador" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36553319,'Farfa, Malebranche do Abismo Ardente',replace(replace('Se você controlar um monstro que não seja um monstro "Abismo Ardente", destrua este card. \r\nVocê só pode usar 1 desses efeitos de "Farfa, Malebranche do Abismo Ardente" por turno e apenas uma vez por turno.\r\n● Se você não controlar nenhuma Magia/Armadilha: você pode Invocar este card por Invocação-Especial da sua mão.\r\n● Se este card for enviado para o Cemitério: você pode escolher 1 monstro no campo; bana-o até a Fase Final.','\r',char(13)),'\n',char(10)),'Invocação Especial','Banir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36556781,'Cavaleiro Dragunidade - Gormfaobhar',replace(replace('1 Regulador "Dragunidade" + 1+ monstros não-Reguladores	\r\nQuando este card for Invocado por Invocação-Sincro: você pode escolher 1 Regulador "Dragunidade" no seu Cemitério; equipe-o neste card. \r\n(Efeito Rápido): você pode enviar para o Cemitério 1 Card de Equipamento que você controla que esteja equipado a este card e, depois, escolha até 2 cards no Cemitério do seu oponente; bana-os. \r\nVocê só pode usar cada efeito de "Cavaleiro Dragunidade - Gormfaobhar" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36560997,'Aceleração do Núcleo',replace(replace('Todos os monstros "Koa''ki Meiru" com a face para cima que você controla ganham 500 de ATK. \r\nUma vez por turno, durante sua Fase Principal, você pode descartar 1 "Núcleo de Ferro de Koa''ki Meiru" para que todos os monstros "Koa''ki Meiru" com a face para cima que você controla ganhem 1000 de ATK até a Fase Final.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36562627,'Segundo Atirar de Moeda',replace(replace('Quando um desafio de moedas for realizado, você pode decidir refazer o desafio. \r\n(Se esse desafio envolvia vários lances de moeda, refaça todos.) \r\nVocê só pode usar o efeito de "Segundo Atirar de Moeda" uma vez por turno.','\r',char(13)),'\n',char(10)),'Usar o efeito de "Segundo Atirar de Moeda"?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36565699,'Buscador Mental',replace(replace('Quando este card removido de jogo for Invocado por Invocação-Especial, revele os 3 cards do topo do Deck do seu oponente. \r\nEscolha 1 desses cards e remova-o de jogo. \r\nDepois, embaralhe os outros no Deck.','\r',char(13)),'\n',char(10)),'Banir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36569343,'Cavaleiro Arrastafogo',replace(replace('Quando um monstro de FOGO for destruído e enviado para o seu Cemitério: envie 1 monstro de FOGO do seu Deck para o Cemitério. \r\nQuando este card for destruído e enviado para o Cemitério: envie 1 monstro de FOGO do seu Deck para o Cemitério. \r\nVocê só pode usar 1 efeito de "Cavaleiro Arrastafogo" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Enviar do Deck para o Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36577931,'Tragédia Despiana',replace(replace('Se este card for enviado para o Cemitério, ou banido, por um efeito de card: você pode adicionar 1 monstro "Despia" do seu Deck à sua mão, exceto "Tragédia Despiana". \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 Magia/Armadilha "Marcado" no seu Cemitério; Baixe-a no seu campo. \r\nVocê só pode usar 1 efeito de "Tragédia Despiana" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36584821,'Gren Maju Da Eiza','O ATK/DEF deste card se tornam o número dos seus cards banidos x 400.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36586443,'Recarga do Elemento','Ganhe 1000 PV para cada monstro "HERÓI do Elemento" com a face para cima que você controla.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36591747,'Divertida Atração Trem da Emoção',replace(replace('Escolha 1 monstro "Diversão" que você controla ou 1 monstro com a face para cima que seu oponente controla; equipe este card a ele. \r\nVocê pode ativar o seguinte efeito, de acordo com qual duelista controla o monstro equipado;\r\n● Você: Mude a posição de batalha do monstro equipado e, depois, seu oponente seleciona 1 Armadilha "Atração" no seu Cemitério e você a Baixa no seu campo.\r\n● Seu oponente: Bana o monstro equipado até a Fase Final.	\r\nVocê só pode usar este efeito de "Divertida Atração Trem da Emoção" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36607978,'Lua Mística',replace(replace('Só pode ser equipado a um monstro do Tipo Besta-Guerreira. \r\nEle ganha 300 de ATK e DEF.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36608728,'Saiba, o Soldado Ferreiro',replace(replace('1 Regulador + 1+ não-Reguladores	\r\nVocê pode escolher 1 monstro Guerreiro de Nível 6 ou menos no seu Cemitério; Invoque-o por Invocação-Especial (mas negue seus efeitos) e, além disso, este card não pode ser usado como Matéria Sincro neste turno. \r\nDurante a Fase Principal do seu oponente, você pode (Efeito Rápido): imediatamente depois que este efeito resolver, Invoque por Invocação-Sincro 1 Monstro Sincro, usando monstros que você controla como matéria, incluindo um monstro Guerreiro. \r\nVocê só pode usar cada efeito de "Saiba, o Soldado Ferreiro" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial do Cemitério','Invocação Sincro','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36609518,'Evil★Gêmea Lil-la',replace(replace('2 monstros, incluindo um monstro "Lil-la"	\r\nSe este card for Invocado por Invocação-Especial e você controlar um monstro "Ki-sikil": você pode escolher 1 card no campo; destrua-o. \r\nDurante a Fase Principal, se você não controlar um monstro "Ki-sikil" (Efeito Rápido): você pode Invocar por Invocação-Especial 1 monstro "Ki-sikil" do seu Cemitério e, além disso, você não pode Invocar monstros por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto monstros Demônio. \r\nVocê só pode usar cada efeito de "Evil★Gêmea Lil-la" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36609519,'Evil★Gêmea Lil-la',replace(replace('2 monstros, incluindo um monstro "Lil-la"	\r\nSe este card for Invocado por Invocação-Especial e você controlar um monstro "Ki-sikil": você pode escolher 1 card no campo; destrua-o. \r\nDurante a Fase Principal, se você não controlar um monstro "Ki-sikil" (Efeito Rápido): você pode Invocar por Invocação-Especial 1 monstro "Ki-sikil" do seu Cemitério e, além disso, você não pode Invocar monstros por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto monstros Demônio. \r\nVocê só pode usar cada efeito de "Evil★Gêmea Lil-la" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36614113,'D/D Arca',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nVocê pode escolher 1 monstro Invocado por Invocação-Pêndulo que seu oponente controla; destrua tanto esse monstro como este card. \r\nVocê só pode usar este efeito de "D/D Arca" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe este card for destruído por um efeito de card: você pode Invocar por Invocação-Especial 1 Monstro Pêndulo "D/D" com a face para cima do seu Deck Adicional, exceto "D/D Arca", mas seus efeitos são negados. \r\nVocê só pode usar este efeito de "D/D Arca" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36623431,'Núcleo de Ferro de Koa''ki Meiru','Durante sua Fase de Compra, se este card estiver no seu Cemitério, você pode adicionar este card à sua mão, em vez de comprar e/ou enviar 1 monstro "Koa''ki Meiru" da sua mão para o seu Cemitério para adicionar este card à sua mão.','Adicionar à mão em vez de comprar','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36625827,'HERÓI do Destino - Servo do Horror',replace(replace('Se este card for Invocado por Invocação-Normal: coloque 1 Marcador de Relógio em cada "Prisão da Torre do Relógio". \r\nQuando este card for destruído em batalha e enviado para o Cemitério: você pode escolher 1 Magia/Armadilha que você controla; destrua o alvo.','\r',char(13)),'\n',char(10)),'Colocar um marcador','Destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36629203,'Aliado da Justiça Destruidor de Núcleo','No começo da Etapa de Dano, se este card batalhar um monstro de LUZ: destrua esse monstro.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36629635,'Dente-de-leão Branco',replace(replace('Se este card for enviado da mão ou do campo para o Cemitério: você pode Invocar por Invocação-Especial 3 "Ficha de Felpa Branca" (Planta/VENTO/Nível 1/ATK 0/DEF 0) em Posição de Defesa. \r\nVocê não pode Invocar por Invocação-Especial do Deck Adicional no turno em que ativar este efeito. \r\nVocê só pode usar este efeito de "Dente-de-leão Branco" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36629636,'Ficha de Felpa Branca','Invocado por Especial com o efeito "Dente-de-leão Branco".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36630403,'Shiranui Espada Espectral',replace(replace('Se este card estiver no seu Cemitério, exceto no turno em que este card foi enviado para o Cemitério: você pode escolher 1 monstro Zumbi não-Regulador no seu Cemitério; bana tanto ele como este card e, se isso acontecer, Invoque por Invocação-Especial 1 Monstro Sincro Zumbi do seu Deck Adicional cujo Nível seja igual à soma dos Níveis que esses 2 monstros tinham. \r\nVocê só pode usar este efeito de "Shiranui Espada Espectral" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36637374,'Abertura dos Marcados',replace(replace('Descarte 1 card e, depois, pegue 1 monstro "Despia" do seu Deck, e adicione-o à sua mão ou Invoque-o por Invocação-Especial em Posição de Defesa e, além disso, pelo resto deste turno depois que este card resolver, você não pode Invocar por Invocação-Especial do Deck Adicional, exceto Monstros de Fusão. \r\nSe um ou mais Monstros de Fusão que você controla seriam destruídos por um efeito de card, em vez disso, você pode banir este card do seu Cemitério. \r\nVocê só pode usar cada efeito de "Abertura dos Marcados" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36643046,'Explorador Sincron','Quando este card for Invocado por Invocação-Normal: você pode escolher 1 monstro "Sincron" no seu Cemitério; Invoque o alvo por Invocação-Especial, mas negue seus efeitos.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36668118,'Lançar Registro de Inicialização',replace(replace('Todos os monstros "Foguette" no campo ganham 300 de ATK/DEF.\r\nVocê pode ativar 1 desses efeitos;\r\n● Invoque por Invocação-Especial em Posição de Defesa até 2 monstros "Foguette" com nomes diferentes da sua mão.\r\n● Se seu oponente controlar mais monstros que você: Invoque por Invocação-Especial em Posição de Defesa monstros "Foguette" com nomes diferentes do seu Cemitério, até a diferença.	\r\nVocê só pode usar este efeito de "Lançar Registro de Inicialização" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial da mão','Invocar por Invocação Especial do Cemitério','Continuar selecionando monstros para Invocar por Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36672909,'Ciclo Regênese',replace(replace('Se você controlar um monstro com 2500 de ATK ou DEF original: escolha 1 card que seu oponente controla, ou você pode escolher 2 se controlar "Senhor Regênese"; bana esse(s) card(s). \r\nSe este card estiver no seu Cemitério, exceto no turno em que foi enviado para lá: você pode bani-lo; Invoque por Invocação-Especial 1 monstro com 2500 de ATK ou DEF da sua mão. \r\nVocê só pode usar cada efeito de "Ciclo Regênese" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36687247,'T.G. Rino Arremetedor',replace(replace('Se este card atacar, ele ganha 400 de ATK apenas durante a Etapa de Dano. \r\nUma vez por turno, durante a Fase Final, se este card estiver no Cemitério porque foi destruído no campo e enviado para lá neste turno: você pode adicionar 1 monstro "T.G." do seu Deck à sua mão, exceto "T.G. Rino Arremetedor".','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36690018,'Reversão do Destino','Escolha 1 monstro "Força Arcana" que você controla; o efeito desse monstro é considerado como o resultado oposto do lance de moedas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36693940,'Designer Peladura','Escolha 1 monstro "Diabrete de" ou "Fofanimal" no seu Cemitério; Invoque-o por Invocação-Especial e, se isso acontecer, ele pode ser considerado como um monstro "Peladura" para uma Invocação-Fusão.','O efeito de "Designer Peladura" está sendo aplicado.','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36694815,'Bitsoldado',replace(replace('Você pode enviar 1 monstro de Nível 2 ou menos da sua mão para o Cemitério; Invoque este card por Invocação-Especial da sua mão. \r\nVocê só pode usar este efeito de "Bitsoldado" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36704180,'Os Cavaleiros Fantasmas da Armadura Frágil',replace(replace('Se um ou mais monstros "Os Cavaleiros Fantasmas" com a face para cima que você controla forem destruídos em batalha ou por um efeito de card: você pode Invocar este card por Invocação-Especial da sua mão. \r\nVocê pode banir este card do seu Cemitério e enviar 1 card "Cavaleiros Fantasmas" da sua mão para o Cemitério; compre 1 card. \r\nVocê só pode usar cada efeito de "Os Cavaleiros Fantasmas da Armadura Frágil" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36708764,'Aranha Roleta',replace(replace('Quando um monstro do oponente declarar um ataque: lance um dado de seis faces e aplique o resultado.\r\n1: Diminua pela metade seus PV.\r\n2: Transforme o ataque em um ataque direto.\r\n3: Selecione 1 monstro que você controla, mude o alvo do ataque para ele e realize o cálculo de dano.\r\n4: Selecione 1 outro monstro que seu oponente controla, mude o alvo do ataque para ele e realize o cálculo de dano.\r\n5: Negue o ataque e, se isso acontecer, cause dano ao seu oponente igual ao ATK do monstro.\r\n6: Destrua o monstro do oponente.','\r',char(13)),'\n',char(10)),'Escolha um alvo de ataque','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36709484,'Teorealizar a Calmaria Passada',replace(replace('Se você controlar um card "Artmage", "DoomZ" ou "Elfnota": você pode Invocar por Invocação-Especial 1 "Medius, o Puro" da sua mão ou do Deck. \r\nSeu oponente não pode ativar cards ou efeitos quando esse monstro for Invocado por Invocação-Especial. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 Monstro de Fusão, Sincro ou Xyz no seu Cemitério; Invoque-o por Invocação-Especial em uma zona sua para a qual um Monstro Link apontar. \r\nVocê só pode usar 1 efeito de "Teorealizar a Calmaria Passada" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36717258,'Monoloph Jurrac','Este card pode atacar todos os monstros que seu oponente controla uma vez cada.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36730805,'Drift em Velocidade',replace(replace('Se você controlar exatamente 1 Regulador e nenhum outro monstro: Invoque por Invocação-Especial 1 monstro "Velocidaroide" de Nível 4 ou menos do seu Deck. \r\nNenhum duelista pode ativar cards ou efeitos quando esse monstro for Invocado por Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36733451,'Alquimista Dimensional',replace(replace('Uma vez por turno: você pode ativar este efeito; bana o card do topo do seu Deck e, se isso acontecer, até o final deste turno, este card ganha 500 de ATK. \r\nQuando este card que você controla for destruído e enviado para o seu Cemitério: você pode escolher 1 dos seus monstros banidos; adicione-o à sua mão.','\r',char(13)),'\n',char(10)),'Aumentar ATK','Adicionar à sua mão 1 dos seus monstros banidos','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36734924,'Sacerdotisa com Azul nos Olhos',replace(replace('Quando um card ou efeito for ativado que escolha este card como alvo (Efeito Rápido): você pode enviar 1 Monstro de Efeito que você controla para o Cemitério e, se isso acontecer, adicione até 2 monstros "Olhos Azuis" com nomes diferentes do seu Deck à sua mão. \r\nSe este card estiver no seu Cemitério: você pode escolher 1 monstro "Olhos Azuis" que você controla; embaralhe-o no Deck e, se isso acontecer, Invoque este card por Invocação-Especial. \r\nVocê só pode usar 1 efeito de "Sacerdotisa com Azul nos Olhos" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicione até 2 monstros "Olhos Azuis" à sua mão','Invocar este card por Invocação Especial do Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36736723,'Guerreiro Apressado',replace(replace('Durante o cálculo de dano, se um Monstro Sincro "Guerreiro(a)" que você controla batalhar um monstro do oponente (Efeito Rápido): você pode enviar este card da sua mão para o Cemitério; o ATK do seu monstro que está batalhando se torna o dobro do seu ATK atual apenas durante esse cálculo de dano. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 monstro "Sincron" no seu Cemitério; adicione-o à sua mão. \r\nVocê só pode usar cada efeito de "Guerreiro Apressado" uma vez por turno.','\r',char(13)),'\n',char(10)),'Aumentar ATK','Recuperar cards','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36737092,'Alteração Sincro',replace(replace('Remova de jogo 1 Monstro Sincro com a face para cima que você controla. \r\nInvoque por Invocação-Especial 1 Monstro Sincro do seu Deck Adicional cujo Nível seja o mesmo que o do monstro removido. \r\nSeus efeitos são negados.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36742774,'Mundo Sincro',replace(replace('Sempre que um monstro for Invocado por Invocação-Sincro, coloque 2 Marcadores de Sinal neste card. \r\nSe este card sob o controle do seu dono for destruído por um efeito de card do oponente: você pode Invocar por Invocação-Especial 1 "Dragão Carmesim" do seu Deck Adicional. \r\nVocê pode remover 4, 7 ou 10 Marcadores de Sinal do seu campo; aplique o efeito apropriado.\r\n● 4: Aumente ou diminua em 1 o Nível de 1 monstro com a face para cima que você controla.\r\n● 7: Invoque por Invocação-Especial 1 Regulador do seu Cemitério.\r\n● 10: Invoque por Invocação-Especial 1 Monstro Sincro do seu Cemitério.','\r',char(13)),'\n',char(10)),'4: Alterar o Nível','7: Invocar por Invocação Especial um Regulador','10: Invocar por Invocação Especial um Monstro Sincro','Invocar por Invocação Especial 1 "Dragão Carmesim" do seu Deck Adicional','Aumentar o Nível','Reduzir o Nível','','','','','','','','','','');
INSERT INTO texts VALUES(36745317,'Vernasílfide das Florestas Despertas',replace(replace('Você pode descartar este card e 1 monstro ou card "Vernasílfide"; envie do seu Deck para o Cemitério, 1 monstro de TERRA que possa ser Invocado por Invocação-Normal/Baixado e, depois, você pode Invocar por Invocação-Especial 1 monstro de TERRA do seu Cemitério com um nome diferente que o desse monstro e, além disso, você não pode ativar efeitos de monstros que não sejam de TERRA pelo resto deste turno. \r\nVocê pode escolher 1 monstro "Vernasílfide" que você controla; seu ATK se torna o dobro até o final deste turno. \r\nVocê só pode usar cada efeito de "Vernasílfide das Florestas Despertas" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial do Cemitério?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36750412,'Magna Drago','Se este card causar dano de batalha ao seu oponente: ele ganha 200 de ATK.','Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36757171,'Hordeum Maligno Bahamut',replace(replace('2 monstros "Hordeum" de Nível 4	\r\nUma vez por turno: você pode desassociar 1 Matéria Xyz deste card para escolher 1 monstro com a face para cima que seu oponente controla; descarte 1 monstro "Hordeum" e, se isso acontecer, assuma o controle desse monstro do oponente.','\r',char(13)),'\n',char(10)),'Tomar controle','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36768783,'Armillyre, o Dragão Lidestelar',replace(replace('2 Monstros de Efeito	\r\nNão pode ser usado como Matéria Link. \r\nVocê pode escolher 1 monstro com a face para cima para o qual este card apontar; Invoque por Invocação-Especial 1 monstro com o mesmo Nível original da sua mão para uma zona sua para a qual este card apontar, em Posição de Defesa, mas negue seus efeitos. \r\nVocê só pode usar este efeito de "Armillyre, o Dragão Lidestelar" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36776089,'Cavalaria Celeste de Centaurea',replace(replace('2 monstros de Nível 2	\r\nNão pode ser destruído em batalha enquanto tiver matéria. \r\nNo final da Etapa de Dano, se este card batalhou um monstro do oponente: você pode desassociar 1 matéria deste card; devolva esse monstro do oponente para a mão.','\r',char(13)),'\n',char(10)),'Retornar para a mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36795102,'Fera Cristalina Dragão Arco-Íris',replace(replace('Se este card com a face para cima for destruído na Zona de Monstros, você pode colocá-lo com a face para cima na sua Zona de Magias & Armadilhas como uma Magia Contínua em vez de enviá-lo para o Cemitério. \r\nVocê só pode usar cada um dos seguintes efeitos de "Fera Cristalina Dragão Arco-Íris" uma vez por turno. \r\nQuando um ataque for declarado envolvendo um monstro "Fera Cristalina": você pode Invocar este card por Invocação-Especial da sua mão. \r\nVocê pode banir este card considerado como uma Magia Contínua; Invoque por Invocação-Especial 1 monstro "Fera Cristalina" de Nível 4 ou menos do seu Deck, mas negue seus efeitos e, se isso acontecer, adicione 1 monstro "Cristalino(a) Definitivo(a)" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36809777,'Batalha de Bestas Brutais',replace(replace('Se um duelista controlar 2 ou mais monstros com o mesmo tipo de card (Ritual, Fusão, Sincro, Xyz ou Link), ele deve enviar algum(ns) para o Cemitério até que não controle mais que 1 monstro desse tipo de card. \r\nDepois, cada duelista que enviou um monstro para o Cemitério por este efeito compra cards igual ao número de tipos de card diferentes (Ritual, Fusão, Sincro, Xyz ou Link) que ele controla. \r\nVocê só pode ativar 1 "Batalha de Bestas Brutais" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36821538,'Feiticeiro Antigo','Armado com uma gama de varinhas mágicas, esta criatura realiza diversos ataques.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36834155,'Pirata de Fóton',replace(replace('Você pode banir 1 monstro "Fóton" do seu Cemitério; este card ganha 1000 de ATK até a Fase Final. \r\nVocê pode usar o efeito de "Pirata de Fóton" até duas vezes por turno.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36841733,'Grãonião, o HERÓI do Elemento',replace(replace('2 Monstros Normais "HERÓI"	\r\nDeve ser Invocado por Invocação-Fusão. \r\nGanha ATK/DEF igual aos Níveis originais combinados das matérias usadas para a sua Invocação-Fusão x 300. \r\nQuando este card destruir um monstro do oponente em batalha: você pode oferecer este card como Tributo; Invoque por Invocação-Especial 1 Monstro de Fusão "HERÓI do Elemento" do seu Deck Adicional, ignorando suas condições de Invocação, mas ele não pode atacar monstros com um Nível igual ou menor que o dele.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36848764,'Doce Camareira',replace(replace('Se um ou mais cards forem enviados da mão e/ou do Deck para o Cemitério: escolha 1 card em qualquer Cemitério; embaralhe-o no Deck. \r\nVocê só pode ativar 1 "Doce Camareira" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36849933,'Megálito Och',replace(replace('Você pode Invocar este card por Invocação-Ritual com um card "Megálito". \r\nSe este card for Invocado por Invocação-Ritual: você pode comprar 1 card e, depois, descarte 1 card. \r\nDurante a Fase Principal (Efeito Rápido): você pode ativar este efeito; Invoque por Invocação-Ritual 1 Monstro de Ritual da sua mão, ao oferecer como Tributo monstros da sua mão ou do campo, incluindo este card no seu campo, cuja soma dos Níveis seja igual ou exceda o Nível do Monstro de Ritual. \r\nVocê só pode usar este efeito de "Megálito Och" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36857073,'Abrasador Dragão Vermelho Arquidemônio do Banimento',replace(replace('1 Regulador + 1 Monstro Sincro Dragão não-Regulador de TREVAS	\r\nVocê pode oferecer 1 monstro como Tributo e, depois, escolha 1 monstro "Dragão Vermelho Arquidemônio" no seu Cemitério; Invoque-o por Invocação-Especial. \r\nQuando este card causar dano de batalha ao seu oponente: você pode Invocar por Invocação-Especial 2 Reguladores com o mesmo Nível (1 do seu Deck e 1 do seu Cemitério) em Posição de Defesa. \r\nVocê só pode usar cada efeito de "Abrasador Dragão Vermelho Arquidemônio do Banimento" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36868108,'Armadura de Vidro',replace(replace('Você pode ativar este card quando um monstro for equipado com um Card de Equipamento. \r\nNegue os efeitos de todos os Cards de Equipamento no campo durante o turno em que este card for ativado.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36870345,'Aklys Dragunidade',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode Invocar por Invocação-Especial 1 monstro "Dragunidade" da sua mão e, depois, equipá-lo com este card. \r\nSe este card for enviado para o Cemitério enquanto estiver equipado a um monstro: escolha 1 card no campo; destrua-o.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial e equipar','Destruir 1 card no campo','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36890111,'Mansão das Terríveis Bonecas',replace(replace('Quando este card for ativado: você pode adicionar 1 monstro "Engenhoca Marionete" do seu Deck à sua mão. \r\nMonstros "Engenhoca Marionete" que você controla não podem ser destruídos em batalha e não são afetados pelos efeitos ativados dos monstros do seu oponente, exceto os Monstros Xyz dele. \r\nUma vez por turno: você pode desassociar 1 matéria de um Monstro Xyz que você controla e, depois, escolha 1 monstro "Engenhoca Marionete" no seu Cemitério; Invoque-o por Invocação-Especial no campo do seu oponente em Posição de Defesa. \r\nVocê só pode ativar 1 "Mansão das Terríveis Bonecas" por turno.','\r',char(13)),'\n',char(10)),'Adicionar 1 monstro "Engenhoca Marionete" do seu Deck à sua mão?','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36894320,'Máquina Infinita',replace(replace('Ative este card ao enviar 1 "Máquina Vazia" com a face para cima da sua Zona de Magias & Armadilhas para o Cemitério. \r\nUma vez por turno, este card com a face para cima não pode ser destruído pelos efeitos de card do seu oponente. \r\nUma vez por turno, você pode ativar 1 desses efeitos.\r\n● Durante a Fase Principal: Invoque por Invocação-Especial 1 monstro "Senhor do Tempo" da sua mão.\r\n● Você pode escolher 1 monstro "Senhor do Tempo" no seu Cemitério; embaralhe-o no Deck e, depois, você pode Baixar 1 "Luz Infinita" diretamente da sua mão ou do seu Deck.','\r',char(13)),'\n',char(10)),'Invocação Especial','Recuperar do Cemitério','Baixar "Luz Infinita"?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36898537,'Horus Metafis',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro: você pode ativar o(s) efeito(s) apropriado(s), dependendo do(s) monstro(s) não-Regulador(es) usado(s) como Matéria Sincro;\r\n● Monstro Normal: Este card com a face para cima não é afetado por outros efeitos de card neste turno.\r\n● Monstro de Efeito: Você pode escolher 1 outro card com a face para cima no campo; negue os efeitos do alvo.\r\n● Monstro Pêndulo: Seu oponente seleciona 1 monstro que ele controla e concede o controle dele a você, mas ele não pode atacar neste turno.','\r',char(13)),'\n',char(10)),'Não afetado','Negar o efeito','Tome o controle','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36904469,'Akihiron','Essa criatura estranha se esconde nos cantos profundos e obscuros dos sete mares.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36916401,'Espíritos Boxeadores Obstinados',replace(replace('Envie o card do topo do seu Deck para o Cemitério e, depois, escolha 1 monstro "Boxeador Obstinado" no seu Cemitério; Invoque o alvo por Invocação-Especial com a face para cima em Posição de Defesa. \r\nVocê só pode ativar 1 "Espíritos Boxeadores Obstinados" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36920182,'Ressonância do Reino',replace(replace('Ative 1 desses efeitos;\r\n● Invoque por Invocação-Especial 1 monstro com 1500 de ATK/2100 de DEF do seu Cemitério.\r\n● Embaralhe no Deck, 1 dos seus "Visas Starfrost" e 4 dos seus monstros com 1500 de ATK/2100 de DEF, que estiverem banidos, no seu Cemitério e/ou no seu campo com a face para cima e, se isso acontecer, Invoque por Invocação-Especial 1 Monstro Sincro "Visas" do seu Deck Adicional. \r\n(Isso é considerado uma Invocação-Sincro.)\r\nVocê só pode ativar 1 "Ressonância do Reino" por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial do Cemitério','Recuperar e Invocar por Invocação Sincro','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36931229,'Portão do Castelo',replace(replace('Este card não pode ser destruído em batalha. \r\nUma vez por turno, se este card estiver com a face para cima em Posição de Ataque, você pode oferecer como Tributo 1 monstro de Nível 5 ou menos para causar dano ao oponente igual ao ATK original desse monstro.','\r',char(13)),'\n',char(10)),'Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36935434,'Trilho do Sacrifício',replace(replace('Ative apenas se um monstro no seu lado do campo for destruído em batalha. \r\nInvoque por Invocação-Especial 1 "Ciberogro" da sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36953371,'Samurai Superpesado Ogro Shutendoji',replace(replace('1 Regulador do Tipo Máquina + 1 ou mais monstros "Samurai Superpesado" não-Reguladores	\r\nEste card pode atacar enquanto estiver com a face para cima em Posição de Defesa. \r\nSe o fizer, use sua DEF para o cálculo de dano. \r\nQuando este card for Invocado por Invocação-Sincro, enquanto você não tiver Cards de Magia/Armadilha no seu Cemitério: você pode destruir todos os Cards de Magia e Armadilha que seu oponente controla.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36956512,'Gadarla, o Kaiju da Poeira Misteriosa',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) no campo do seu oponente em Posição de Ataque ao oferecer como Tributo 1 monstro que ele controla. \r\nSe seu oponente controlar um monstro "Kaiju", você pode Invocar este card por Invocação-Especial (da sua mão) em Posição de Ataque. \r\nVocê só pode controlar 1 monstro "Kaiju". \r\nUma vez por turno (Efeito Rápido): você pode remover 3 Marcadores Kaiju de qualquer parte do campo; o ATK/DEF de todos os outros monstros no campo são diminuídos pela metade.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36970611,'Sobrecarga PSÍ-Armação',replace(replace('Uma vez por turno: você pode banir 1 monstro "PSÍ-Armação" da sua mão ou com a face para cima do seu lado do campo e, depois, escolha 1 card no campo; bana-o com a face para baixo. \r\nDurante o turno de qualquer duelista, exceto no turno em que este card foi enviado para o Cemitério: você pode banir este card do seu Cemitério; adicione 1 card "PSÍ-Armação" do seu Deck à sua mão, exceto "Sobrecarga PSÍ-Armação".','\r',char(13)),'\n',char(10)),'Banir','Adicionar à mão','Usar o efeito agora?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36974120,'Vouinterro, o Dragão Sepultureiro',replace(replace('Se este card batalhar um monstro, nenhum dos dois pode ser destruído nessa batalha. \r\nDurante a Fase Principal, se um ou mais monstros que seu oponente controla forem enviados para o Cemitério: você pode ativar o seguinte efeito, de acordo com onde este card estava na ativação (mas você só pode usar cada efeito de "Vouinterro, o Dragão Sepultureiro" uma vez por turno);\r\n● Mão: Invoque este card por Invocação-Especial.\r\n● Campo: Faça com que 1 Monstro de Efeito que seu oponente controla perca 1500 de ATK e, depois, se o ATK dele se tornar 0 por este efeito, você pode destruí-lo.','\r',char(13)),'\n',char(10)),'','','Destruir aquele monstro?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36975314,'Repressão',replace(replace('Ative ao escolher 1 monstro com a face para cima que seu oponente controla; tome o controle desse monstro. \r\nEnquanto você controlar esse monstro, ele não pode atacar ou ativar efeitos. \r\nQuando esse monstro deixar o campo, destrua este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36982581,'Necroespelho Gishki',replace(replace('Este card pode ser usado para a Invocação-Ritual de qualquer Monstro de Ritual "Gishki". \r\nVocê também deve oferecer como Tributo monstros da sua mão ou do campo, cuja soma dos Níveis seja exatamente igual ao Nível do Monstro de Ritual que você Invocar por Invocação-Ritual, OU ofereça como Tributo 1 monstro com a face para cima que seu oponente controla. \r\nSe você Invocar por Invocação-Ritual usando este card, você perde PV igual ao ATK original do monstro Invocado por Invocação-Ritual. \r\nSe este card estiver no seu Cemitério: você pode escolher 1 monstro "Gishki" no seu Cemitério; coloque esse card no topo do Deck e, se isso acontecer, coloque este card no fundo do Deck.','\r',char(13)),'\n',char(10)),'Oferecer como Tributo 1 monstro que seu oponente controla para uma Invocação Ritual?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36995273,'Circuito Degenerativo',replace(replace('O controlador deste card paga 500 PV durante cada uma de suas Fases de Apoio (isso não é opcional). \r\nCards de Monstro que seriam devolvidos do campo à mão, em vez disso, são removidos de jogo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37006702,'Bruxa Krishnerd',replace(replace('Não pode ser destruído pelos efeitos de card do seu oponente enquanto "Multi-Universo" estiver no campo. \r\nVocê só pode usar cada um dos seguintes efeitos de "Bruxa Krishnerd" uma vez por turno. \r\nSe um ou mais cards na Zona do Campo deixarem o campo devido a um efeito de card (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão. \r\nQuando uma Magia de Campo que já estiver com a face para cima no campo ativar seu efeito (Efeito Rápido): você pode embaralhar no Deck 1 dos seus monstros que estiverem banidos ou no seu Cemitério ou, se esse monstro mencionar essa Magia de Campo, em vez disso, você pode Invocá-lo por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Invocação Especial?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37007105,'Ciclone Cibersal','Escolha 1 Monstro Link que seu oponente controla; bana 1 monstro do seu Cemitério que tenha o mesmo Valor Link que esse monstro e, se isso acontecer, destrua esse monstro e, depois, se o Tipo original do monstro que você baniu era Ciberso, você pode destruir 1 card com a face para cima na Zona de Magias & Armadilhas do seu oponente.','Destruir outra Magia/Armadilha que seu oponente controla?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37011715,'Renascimento Miraculoso',replace(replace('Ative apenas como Elo de Corrente 4 ou mais. \r\nSelecione 1 monstro do Cemitério de cada duelista e Invoque-o por Invocação-Especial. \r\nVocê não pode ativar este card se vários cards/efeitos com o mesmo nome estiverem na Corrente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37021315,'Primineral Mandrilorte',replace(replace('Você pode Baixar este card da sua mão na sua Zona de Magias & Armadilhas como uma Magia. \r\nDurante a Fase Final, se este card estiver no Cemitério porque foi destruído por um efeito de card do oponente neste turno enquanto estava Baixado no seu campo: você pode Invocar este card por Invocação-Especial e, depois, você pode adicionar 1 monstro do seu Cemitério à sua mão, exceto "Primineral Mandrilorte". \r\nVocê só pode usar este efeito de "Primineral Mandrilorte" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar este card por Invocação Especial','Adicionar um monstro do Cemitério à sua mão?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37038993,'Puralis, o Pyrolite Púrpura',replace(replace('1 Regulador + 1 monstro não-Regulador	\r\nQuando este card for enviado do campo para o Cemitério: todos os monstros que seu oponente controla atualmente perdem 500 de ATK.','\r',char(13)),'\n',char(10)),'Reduzir ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37042505,'Liga Eterna',replace(replace('Se você controlar "Jinzo": ative 1 desses efeitos;\r\n● Até o final deste turno, todos os monstros Máquina que você controla atualmente não podem ser destruídos pelos efeitos de card do seu oponente.\r\n● Quando um card ou efeito for ativado que escolha como alvo um ou mais monstros Máquina que você controla: negue o efeito.','\r',char(13)),'\n',char(10)),'Não pode ser destruído','Negar o efeito','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37043180,'Guerreiro D.D.','Quando este card combater um monstro, depois do cálculo de dano, remova de jogo o monstro combatido e este card.','Banir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37053871,'Barreira Astral','Se um monstro do seu oponente atacar um monstro que você controla: em vez disso, você pode transformar o ataque em um ataque direto.','Usar o efeito de "Barreira Astral" agora?','Ataque direto','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37055344,'Carrossel Fantardil',replace(replace('Uma vez por turno, durante a Fase de Batalha: você pode ativar 1 desses efeitos.\r\n● Escolha 1 monstro "Fantardil" que você controla; coloque o alvo com a face para baixo em Posição de Defesa e, se isso acontecer, coloque 1 monstro com a face para baixo em Posição de Defesa que seu oponente controla com a face para cima em Posição de Ataque.\r\n● Escolha 1 monstro com a face para baixo em Posição de Defesa que você controla; coloque o alvo com a face para cima em Posição de Ataque e, se ele for um monstro "Fantardil", coloque 1 monstro com a face para cima que seu oponente controla com a face para baixo em Posição de Defesa.','\r',char(13)),'\n',char(10)),'Escolher um efeito','Mudar o seu monstro "Fantardil" para a Posição de Defesa com a face para baixo','Mudar o seu monstro para a Posição de Ataque com a face para cima','Escolha 1 efeito para ativar','','','','','','','','','','','','');
INSERT INTO texts VALUES(37057012,'Ciberogro 2',replace(replace('"Ciberogro" + "Ciberogro"	\r\nA Invocação-Fusão deste monstro só pode ser realizada com os Monstros-Matéria de Fusão acima. \r\nQuando este card atacar, ele ganha ATK igual à metade do ATK do alvo de ataque apenas durante o cálculo de dano.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37057743,'Irmandade do Punho de Fogo - Imperador Leão',replace(replace('2 monstros de FOGO de Nível 3	\r\nUma vez por turno: você pode desassociar 1 matéria deste card e, depois, escolha 1 monstro de FOGO no seu Cemitério; adicione o alvo à sua mão e, além disso, pelo resto deste turno, você não pode Invocar esse monstro ou um monstro com o mesmo nome por Invocação-Normal ou Especial.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37061511,'Leviatã Aquático @Ignister',replace(replace('Você pode Invocar este card por Invocação-Ritual com "Ritual da I.A.". \r\nSe este card for Invocado por Invocação-Ritual: você pode devolver para a mão todos os monstros que seu oponente controla com 2300 ou menos de ATK. \r\nVocê pode escolher 1 monstro com a face para cima que seu oponente controla; devolva todos os Monstros Link do seu Cemitério para o Deck Adicional e, se isso acontecer, mude o ATK do monstro alvo para 0. \r\nVocê só pode usar este efeito de "Leviatã Aquático @Ignister" uma vez por turno. \r\nUma vez por batalha, durante o cálculo de dano, se este card batalhar um monstro do oponente (Efeito Rápido): você pode diminuir pela metade o ATK desse monstro do oponente, apenas durante o cálculo de dano.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37083210,'Cross Counter',replace(replace('Se o DEF de um monstro atacado em Posição de Defesa é superior ao ATK do monstro atacante no Campo do seu adversário, o dano de batalha infligido ao seu adversário é dobrado. \r\nDestrúa o monstro atacante depois do cálculo de dano.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37092104,'Braços Monstruosos de Atlantis',replace(replace('O nome deste card se torna "Umi" enquanto está na Zona de Monstros.\r\nVocê só pode usar cada um dos seguintes efeitos de "Braços Monstruosos de Atlantis" uma vez por turno.\r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 monstro no seu Cemitério que mencione "Atlantis, a Cidade do Dragão"; Invoque-o por Invocação-Especial em Posição de Defesa.\r\nQuando seu oponente ativar um efeito de monstro (Efeito Rápido): você pode banir este card do seu campo ou Cemitério e enviar 1 "Umi" com a face para cima que você controla para o Cemitério; negue aquele efeito.','\r',char(13)),'\n',char(10)),'Invocação Especial','Negar o efeito','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37101832,'Guarda do Coveiro','VIRE: Devolva 1 monstro no Campo do seu adversário para a mão do seu dono.','Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37104630,'Infantaria Pesada Atlante',replace(replace('Durante sua Fase Principal, você pode Invocar por Invocação-Normal 1 monstro Serpente Marinha de Nível 4 ou menos em adição à sua Invocação-Normal/Baixar (padrão). \r\n(Você só pode se aproveitar deste efeito uma vez por turno.) \r\nSe este card for enviado para o Cemitério para ativar o efeito de um monstro de ÁGUA: escolha 1 card com a face para cima que seu oponente controla; destrua o alvo.','\r',char(13)),'\n',char(10)),'Destruir','Invocar pelo efeito de "Infantaria Pesada Atlante"','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37115575,'Dragão da Verdade Perniciosa',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial por seu próprio efeito e não pode ser Invocado por Invocação-Especial de nenhuma outra forma. \r\nSe um monstro "Pernicioso(a)" que você controla, exceto "Dragão da Verdade Perniciosa", for destruído em batalha ou por um efeito de card: você pode pagar metade dos seus Pontos de Vida; Invoque este card por Invocação-Especial da sua mão ou Cemitério. \r\nSó pode haver 1 monstro "Pernicioso(a)" no campo. \r\nSe não houver nenhum Card de Magia de Campo com a face para cima no campo, destrua este card. \r\nSe este card destruir um monstro do oponente em batalha: destrua todos os monstros com a face para cima que seu oponente controla.','\r',char(13)),'\n',char(10)),'Invocação Especial','Destruir todos os monstros com a face para cima que seu oponente controla','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37115973,'Caçador de Númerais',replace(replace('Se este card for Invocado: devolva para o Deck Adicional todos os Monstros Xyz "Número" no campo. \r\nNenhum duelista pode Invocar Monstros Xyz "Número" por Invocação-Especial. \r\nNão pode ser destruído em batalha com um Monstro Xyz. \r\nEste card não é afetado por efeitos de Monstros Xyz.','\r',char(13)),'\n',char(10)),'Retornar ao Deck Adicional','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37119142,'Codificar Exportador',replace(replace('Se um monstro Ciberso que você controla seria usado como Matéria Link para um monstro "Codificar Transmissor", este card na sua mão também pode ser usado como matéria. \r\nSe este card for enviado da mão ou do campo para o Cemitério como matéria para a Invocação-Link de um monstro "Codificar Transmissor": você pode escolher 1 monstro Ciberso de Nível 4 ou menos no seu Cemitério; adicione-o à sua mão ou, se este card no campo foi usado como matéria, em vez disso, você pode Invocar esse monstro por Invocação-Especial, mas negue seus efeitos. \r\nVocê só pode usar cada efeito de "Codificar Exportador" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Enviar do campo para o Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37120512,'Espada Sombria da Destruição',replace(replace('Só pode ser equipado a um monstro de TREVAS. \r\nEle ganha 400 de ATK e perde 200 de DEF.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37129797,'Vampira Sugador',replace(replace('2 monstros Zumbi	\r\nSe você fosse oferecer como Tributo um ou mais monstros para uma Invocação-Tributo, você pode oferecer como Tributo um ou mais monstros Zumbi que seu oponente controla, mesmo que você não os controle. \r\nVocê só pode usar cada um dos seguintes efeitos de "Vampira Sugador" uma vez por turno. \r\nVocê pode escolher 1 monstro no Cemitério do seu oponente; Invoque-o por Invocação-Especial em Posição de Defesa no campo do seu oponente, mas ele se torna um monstro Zumbi. \r\nSe um ou mais monstros Zumbi forem Invocados por Invocação-Especial de qualquer Cemitério: compre 1 card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37132349,'Ojama Vermelho','Quando este card for Invocado por Invocação-Normal: você pode Invocar por Invocação-Especial até 4 monstros "Ojama" da sua mão em Posição de Ataque.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37160778,'Fadabruxa','Apesar destinada a ser uma fada, esta criatura preferiu o caminho de bruxa.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37164373,'Rainha Magidoce Tiaramisu',replace(replace('2 monstros "Magidoce" de Nível 4	\r\nUma vez por turno: você pode desassociar 1 matéria deste card e, depois, escolha até 2 cards "Magidoce" no seu Cemitério; embaralhe esses cards no Deck e, além disso, depois, embaralhe cards que seu oponente controla no Deck, até o número de cards "Magidoce" devolvidos.','\r',char(13)),'\n',char(10)),'Retornar ao Deck','Escolher um card que seu oponente controla para retornar ao Deck?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37168514,'Cérbero Gorgônico','Quando este card for Invocado por Invocação-Normal: você pode fazer com que todos os monstros do Tipo Rocha que você controla se tornem de Nível 3.','Alterar Nível','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37169670,'Hiper Destruidor Psíquico/Modo de Ataque',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial com "Ativar Modo de Ataque". \r\nNo final da Etapa de Dano, se este card batalhou um monstro do oponente: cause dano ao seu oponente igual à DEF desse monstro do oponente e, além disso, ganhe PV igual ao ATK dele. \r\nQuando este card no campo for destruído: você pode escolher 1 "Hiper Destruidor Psíquico" no seu Cemitério; Invoque o alvo por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Dano e recuperação','Invocar "Hiper Destruidor Psíquico" por Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37192109,'PSÍ-Armação Senhor Zeta',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nUma vez por turno (Efeito Rápido): você pode escolher 1 monstro Invocado por Invocação-Especial que seu oponente controla com a face para cima em Posição de Ataque; bana tanto esse monstro quanto este card no campo, mas devolva-os na sua próxima Fase de Apoio. \r\nSe este card estiver no seu Cemitério: você pode escolher 1 outro card "PSÍ-Armação" no seu Cemitério; devolva este card para o Deck Adicional e, se isso acontecer, adicione o alvo à sua mão.','\r',char(13)),'\n',char(10)),'Banir um monstro do seu oponente e este card','Retornar card(s) "PSÍ-Armação" para a mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37195861,'Oceano, o HERÓI do Elemento','Uma vez por turno, durante sua Fase de Apoio: você pode escolher 1 monstro "HERÓI" que você controla ou no seu Cemitério; devolva o alvo para a mão.','Retornar para a mão do seu dono 1 monstro cujo nome contenha "HERÓI"','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37198732,'Subir de Nível','Envie 1 monstro da sua mão para o Cemitério e, depois, escolha até 2 monstros com a face para cima que você controla; até o final deste turno, o Nível deles se torna o Nível original do monstro enviado para o Cemitério para ativar este card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37209439,'Pacto Obscuro com Erros',replace(replace('Uma vez por turno, se você controlar um monstro "D/D": pelo resto deste turno (mesmo que este card deixe o campo), você pode negar todos os efeitos dos Cards de Armadilha no campo (que não sejam deste card). \r\nUma vez por turno, durante sua Fase de Apoio: sofra 1000 de dano.','\r',char(13)),'\n',char(10)),'Negar o efeito','Causar dano','Usar o efeito?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37231841,'Aliviar a Carga',replace(replace('Adicione 1 monstro de Nível 7 ou mais da sua mão ao seu Deck, embaralhe-o, e compre 1 card. \r\nVocê pode usar este efeito apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Trocar as mãos','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37241623,'Inscrição Heráldica','Quando um efeito de um Monstro Xyz do seu oponente for ativado quando ele desassociar uma ou mais de suas próprias Matérias Xyz: negue a ativação e, se isso acontecer, destrua-o.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37243151,'Controle Climático','Esta criatura controla o clima e frequentemente é a causa de tempestades nas montanhas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37256135,'Pega-pega Melffy',replace(replace('Escolha 1 monstro "Melffy" no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê só pode ativar 1 "Pega-pega Melffy" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37256334,'Card Gardna Camarartista',replace(replace('Escala de Pêndulo = 8\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno: você pode escolher 1 monstro com a face para cima em Posição de Defesa que você controla; sua DEF se torna igual à DEF original combinada de todos os monstros com a face para cima em Posição de Defesa que você controla atualmente (mesmo que este card deixe o campo).\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nGanha DEF igual à DEF original combinada de todos os outros monstros "Camarartista" que você controla.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37260677,'Zoroa, o Verethragna Magistus',replace(replace('1 monstro "Magistus" + 1 Monstro de Fusão, Sincro, Xyz ou Link	\r\nVocê pode escolher 1 Monstro de Efeito no seu Cemitério ou que seu oponente controla; equipe esse Monstro de Efeito a este card. \r\nQuando um efeito de monstro for ativado (Efeito Rápido): você pode enviar 1 Card de Monstro "Magistus" com a face para cima que você controla para o Cemitério; negue esse efeito e, depois, você pode destruir 1 card que seu oponente controla. \r\nVocê só pode usar cada efeito de "Zoroa, o Verethragna Magistus" uma vez por turno.','\r',char(13)),'\n',char(10)),'Equipar','Negar o efeito','Destruir o card?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37260946,'Fonvido Morfotrônico',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nEnquanto este card for um Card de Equipamento, o monstro equipado pode realizar até 2 ataques contra monstros durante cada Fase de Batalha. \r\nVocê só pode usar cada um dos seguintes efeitos de "Fonvido Morfotrônico" uma vez por turno. \r\nSe este card for Invocado por Invocação-Especial: você pode escolher 1 monstro com a face para cima no campo; considere-o como um Regulador até o final deste turno. \r\nVocê pode escolher 1 Monstro Sincro no campo; equipe este card do seu campo ou Cemitério a ele.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37261776,'Salamagrande Quimera Violeta',replace(replace('1 monstro "Salamagrande" + 1 Monstro Link	\r\nSe este card for Invocado por Invocação-Fusão: até o final deste turno, você pode fazer com que este card ganhe ATK igual à metade do ATK original combinado das matérias usadas para Invocá-lo. \r\nUma vez por batalha, durante o cálculo de dano, se este monstro batalhar um monstro cujo ATK atual seja diferente do seu ATK original (Efeito Rápido): você pode dobrar o ATK deste card, apenas durante o cálculo de dano. \r\nSe este card que foi Invocado por Invocação-Fusão usando "Salamagrande Quimera Violeta" como matéria batalhar um monstro, o ATK desse monstro se torna 0 apenas durante o cálculo de dano.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37265642,'Sabressauro','Este dinossauro, normalmente gentil, gosta de relaxar em seu lar nas pradarias. Mas se ele se zanga, fica extremamente furioso.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37267041,'Espadachim Silencioso LV7',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial por "Espadachim Silencioso LV5" e não pode ser Invocado por Invocação-Especial de nenhuma outra forma. \r\nNegue todos os efeitos de Magia no campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37279096,'Ars Magna - "Citrinitas"',replace(replace('(Este card é sempre considerado como um card "Artmage", "DoomZ" e "Elfnota".)	\r\nVocê pode ativar os efeitos de monstros que você controla com "Ars Magna" em seus normais originais como Efeitos Rápido enquanto você controlar um Monstro Link "Patrono(a) do Poder".\r\nUma vez enquanto está com a face para cima no campo: você pode adicionar 1 monstro "Medius" ou "Ars Magna" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Ars Magna - "Citrinitas"" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Efeito de busca','Efeito já ativado','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37279508,'Número 37: Dragão Aranha Tubarão Trama da Esperança',replace(replace('2 monstros de ÁGUA de Nível 4	\r\nQuando o monstro de qualquer duelista declarar um ataque: você pode desassociar 1 Matéria Xyz deste card; todos os monstros que seu oponente controla atualmente perdem 1000 de ATK até o final deste turno. \r\nQuando este card for destruído em batalha ou por um efeito de card e enviado para o Cemitério: você pode escolher 1 outro monstro no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Número 37: Dragão Aranha Tubarão Trama da Esperança" uma vez por turno.','\r',char(13)),'\n',char(10)),'Reduzir ATK','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37300735,'T.G. Jato Falcão','Se este card for enviado para o Cemitério como uma Matéria Sincro: cause 500 de dano ao seu oponente.','Cause 500 de dano ao seu oponente','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37301660,'Ventos da Vitória','O monstro equipago ganha 300 de ATK e também se torna VENTO.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37310367,'Gardna Bloqueado',replace(replace('Quando um monstro do oponente declarar um ataque direto: você pode Invocar este card por Invocação-Especial da sua mão em Posição de Ataque e, se isso acontecer, ele não pode ser destruído em batalha neste turno. \r\nQuando um efeito de um monstro que seu oponente controla for ativado que escolha 1 monstro Ciberso que você controla como alvo (e nenhum outro card) (Efeito Rápido): até o final deste turno, você pode negar tanto os efeitos desse monstro Ciberso que você controla quanto desse monstro do oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37313338,'Vernasílfide e a Mudança de Estação',replace(replace('Escolha 1 monstro "Vernasílfide" no seu Cemitério; adicione-o à sua mão ou Invoque-o por Invocação-Especial. \r\nDurante o turno do seu oponente, exceto no turno em que este card foi enviado para o Cemitério, se você não tiver cards na sua mão: você pode banir este card do seu Cemitério; Invoque por Invocação-Especial tantos monstros "Vernasílfide" quanto possível com nomes diferentes do seu Cemitério, mas devolva-os para a mão durante sua Fase Final. \r\nVocê só pode usar cada efeito de "Vernasílfide e a Mudança de Estação" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37313348,'Tigre Tartaruga','Um tigre protegido por uma carapaça, que usa suas presas afiadas como lâminas para atacar.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37313786,'Apostar',replace(replace('Você só pode ativar este card quando a mão do seu oponente tiver 6 ou mais cards e sua mão tiver 2 ou menos. \r\nLance uma moeda e selecione cara ou coroa. \r\nSe ganhar, compre até que sua mão tenha 5 cards. \r\nSe perder, pule seu próximo turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37318031,'R - Justiça Honrada','Destrua Magias/Armadilhas no campo igual ao número de cards "HERÓI do Elemento" que você controla.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37322745,'Floresta de Naturia','Se você negar a ativação de um ou mais Cards de Magia/Armadilha do oponente, ou um ou mais efeitos de monstro do oponente (exceto durante a Etapa de Dano): você pode adicionar 1 monstro "Naturia" de Nível 3 ou menos do seu Deck à sua mão.','Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37337327,'Conector Sucata',replace(replace('2 Monstros de Efeito (Guerreiro e/ou Máquina), incluindo um Regulador	\r\nUma vez por turno, durante a Fase Principal ou de Batalha, você pode (Efeito Rápido): imediatamente depois que este efeito resolver, Invocar por Invocação-Sincro 1 Monstro Sincro, usando apenas matérias para as quais este card apontar. \r\nSe este card Invocado por Invocação-Link que você controla for destruído em batalha ou por um efeito de card do oponente e enviado para o seu Cemitério: você pode Invocar por Invocação-Especial 1 Monstro Sincro "Sucata" do seu Deck Adicional. \r\n(Essa é considerada uma Invocação-Sincro.)','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37343995,'Exoirmã Martha',replace(replace('Se você não controlar nenhum monstro ou controlar apenas Monstros Xyz: você pode Invocar este card por Invocação-Especial da sua mão e, se isso acontecer, Invoque por Invocação-Especial 1 "Exoirmã Elis" do seu Deck. \r\nVocê não pode Invocar por Invocação-Especial no turno em que ativar este efeito, exceto monstros "Exoirmã". \r\nSe um ou mais cards se moverem para fora de qualquer Cemitério (exceto durante a Etapa de Dano): você pode Invocar por Invocação-Especial do seu Deck Adicional, 1 Monstro Xyz "Exoirmã", usando este card com a face para cima que você controla como matéria (isso é considerado uma Invocação-Xyz). \r\nVocê só pode usar cada efeito de "Exoirmã Martha" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Invocar por Invocação Especial do Deck Adicional como uma Invocação Xyz','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37349495,'Berinjela de Naturia','Quando este card for enviado do campo para o Cemitério, você pode selecionar 1 monstro "Naturia" no seu Cemitério, exceto "Berinjela de Naturia", e adicioná-lo à sua mão.','Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37351133,'Força Celeste - Ás - Roze',replace(replace('Se um ou mais monstros "Força Celeste - Ás" forem Invocados por Invocação-Normal ou Especial, exceto "Força Celeste - Ás - Roze" (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe um monstro do oponente na Zona de Monstros Adicional for destruído em batalha, ou deixar o campo por um efeito de card seu, enquanto este card estiver no seu Cemitério: você pode Invocar este card por Invocação-Especial e, depois, você pode negar os efeitos de 1 monstro com a face para cima que seu oponente controla até o final deste turno. \r\nVocê só pode usar cada efeito de "Força Celeste - Ás - Roze" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invoque este card por Invocação Especial da sua mão','Invocar este card por Invocação Especial do Cemitério','Escolher um monstro do seu oponente para negar seus efeitos?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37351134,'Força Celeste - Ás - Roze',replace(replace('Se um ou mais monstros "Força Celeste - Ás" forem Invocados por Invocação-Normal ou Especial, exceto "Força Celeste - Ás - Roze" (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe um monstro do oponente na Zona de Monstros Adicional for destruído em batalha, ou deixar o campo por um efeito de card seu, enquanto este card estiver no seu Cemitério: você pode Invocar este card por Invocação-Especial e, depois, você pode negar os efeitos de 1 monstro com a face para cima que seu oponente controla até o final deste turno. \r\nVocê só pode usar cada efeito de "Força Celeste - Ás - Roze" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invoque este card por Invocação Especial da sua mão','Invocar este card por Invocação Especial do Cemitério','Escolher um monstro do seu oponente para negar seus efeitos?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37351135,'Força Celeste - Ás - Roze',replace(replace('Se um ou mais monstros "Força Celeste - Ás" forem Invocados por Invocação-Normal ou Especial, exceto "Força Celeste - Ás - Roze" (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe um monstro do oponente na Zona de Monstros Adicional for destruído em batalha, ou deixar o campo por um efeito de card seu, enquanto este card estiver no seu Cemitério: você pode Invocar este card por Invocação-Especial e, depois, você pode negar os efeitos de 1 monstro com a face para cima que seu oponente controla até o final deste turno. \r\nVocê só pode usar cada efeito de "Força Celeste - Ás - Roze" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invoque este card por Invocação Especial da sua mão','Invocar este card por Invocação Especial do Cemitério','Escolher um monstro do seu oponente para negar seus efeitos?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37354507,'Mestre Ninja Saizo',replace(replace('2 monstros "Ninja"	\r\nDurante sua Fase Principal: você pode Baixar 1 Magia/Armadilha "Ninjitsu" diretamente do seu Deck. \r\nVocê só pode usar este efeito de "Mestre Ninja Saizo" uma vez por turno. \r\nEnquanto este card apontar para um ou mais monstros, este card não pode ser escolhido como alvo de um ataque e, além disso, seu oponente não pode escolhê-lo como alvo de efeitos de card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37364101,'Desafio Estoico',replace(replace('Você só pode controlar 1 "Desafio Estoico". \r\nSó pode ser equipado a um Monstro Xyz com a face para cima que tenha Matéria Xyz. \r\nEle ganha 600 de ATK para cada Matéria Xyz associada a um monstro que você controla e qualquer dano de batalha que seu oponente sofrer de batalhas envolvendo este o monstro equipado e o monstro do oponente é dobrado, mas seus efeitos não podem ser ativados. \r\nDurante a Fase Final do seu oponente: envie este card para o Cemitério. \r\nQuando este card deixa o campo, destrua o monstro equipado.','\r',char(13)),'\n',char(10)),'Enviar para o Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37383714,'Laço das Almas','Quando um monstro que você controla for destruído por um efeito de card e enviado para o Cemitério (exceto durante a Etapa de Dano): pague 1000 PV; Invoque por Invocação-Especial 1 monstro de Nível 4 do seu Deck.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37390589,'Kunai com Corrente',replace(replace('Ative 1 ou os dois efeitos abaixo (simultaneamente);\r\n● Quando um monstro do oponente declarar um ataque: escolha o monstro atacante; mude o alvo para a Posição de Defesa.\r\n● Escolha 1 monstro com a face para cima que você controla; equipe este card no alvo.	\r\nEle ganha 500 de ATK.','\r',char(13)),'\n',char(10)),'Mudar o monstro atacante para a Posição de Defesa','Tornar-se um Card de Equipamento','Use ambos os efeitos','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37390590,'Kunai com Corrente',replace(replace('Ative 1 ou os dois efeitos abaixo (simultaneamente);\r\n● Quando um monstro do oponente declarar um ataque: escolha o monstro atacante; mude o alvo para a Posição de Defesa.\r\n● Escolha 1 monstro com a face para cima que você controla; equipe este card no alvo.	\r\nEle ganha 500 de ATK.','\r',char(13)),'\n',char(10)),'Mudar o monstro atacante para a Posição de Defesa','Tornar-se um Card de Equipamento','Use ambos os efeitos','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37405032,'Trapestrela Anjo Aqua',replace(replace('(Este card deve ser sempre considerado como um card "Marincesa".)	\r\nMonstros Link que apontarem para este card não podem ser destruídos em batalha. \r\nVocê só pode usar cada um dos seguintes efeitos de "Trapestrela Anjo Aqua" uma vez por Duelo. \r\nSe você controlar um monstro "Trapestrela" ou "Marincesa": você pode Invocar este card por Invocação-Especial da sua mão ou do Cemitério. \r\nSe este card for enviado para o Cemitério como Matéria Link: você pode olhar todos os cards na mão do seu oponente e todos os cards Baixados que ele controla.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37406863,'Espelho Fengsheng',replace(replace('Olhe a mão do oponente. \r\nSelecione e descarte 1 monstro Espírito no Cemitério se o oponente tiver monstros Espírito na mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37412656,'Explosão do Herói','Escolha 1 Monstro Normal "HERÓI do Elemento" no seu Cemitério; adicione o alvo à sua mão e, depois, se seu oponente controlar qualquer monstro com ATK menor ou igual ao ATK do alvo, destrua 1 deles.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37414347,'F.A. GT Estrela Brilhante',replace(replace('2 monstros Máquina	\r\nGanha ATK igual à soma dos Níveis dos monstros "F.A." para os quais este card apontar x 300. \r\nNenhum duelista sofre qualquer dano de batalha dos ataques envolvendo este card. \r\nSempre que um Card ou efeito de Magia/Armadilha "F.A." for ativado: coloque 1 Marcador de Atleta neste card. \r\nQuando seu oponente ativar um efeito de monstro (Efeito Rápido): você pode remover 1 Marcador de Atleta deste card; negue a ativação e, se isso acontecer, destrua-o. \r\nVocê só pode usar este efeito de "F.A. GT Estrela Brilhante" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37421075,'Força Degen','Ofereça como Tributo 1 monstro do Tipo Dinossauro de Nível 4 ou mais; Invoque por Invocação-Especial 2 monstros do Tipo Réptil de Nível 3 ou menos da sua mão e/ou Cemitério.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37421579,'Charubin, O Cavaleiro do Fogo','"Monstro Ovo" + "Alma Hinotama"','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37426272,'Materriator Exareptor',replace(replace('Você pode revelar este card na sua mão e descartar 1 outro card; adicione 1 Monstro Normal de Nível 3 do seu Deck ou Cemitério à sua mão, exceto o card descartado e, depois, você pode Invocar este card por Invocação-Especial em Posição de Defesa. \r\nVocê só pode usar este efeito de "Materriator Exareptor" uma vez por turno. \r\n(Efeito Rápido): você pode descartar este card e, depois, escolha 1 Monstro Xyz de Classe 3 que você controla; ele ganha 1500 de ATK até o final deste turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Aumentar ATK','Invocar este card por Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37432075,'Invokação - "Espada"',replace(replace('Invoque por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional, usando monstros que você controla. \r\nSe estiver Invocando um Monstro de Fusão "Invokado(a)" desta forma, você também pode devolver monstros de qualquer banimento para o Cemitério como matéria. \r\nDurante sua Fase Principal, se este card estiver no seu Cemitério: você pode escolher 1 monstro "Aleister" ou "Invokação" no seu Cemitério; embaralhe este card no Deck e, se isso acontecer, adicione o alvo à sua mão. \r\nVocê só pode usar cada efeito de "Invokação - "Espada"" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Fusão','Efeito de recuperação','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37433748,'APARATO ESPIRÃO - Último Resort',replace(replace('Você pode escolher 1 monstro "ESPIRÃO" que você controla; equipe este monstro da sua mão ou do campo no alvo. \r\nEnquanto este card estiver equipado a um monstro por este efeito, o monstro equipado não pode ser destruído em batalha ou por efeitos de card e, além disso, seu oponente não pode escolhê-lo como alvo de efeitos de card. \r\nUma vez por turno, se este card for equipado a um monstro por este efeito: você pode enviar 1 outro card que você controla para o Cemitério; o monstro equipado pode atacar diretamente neste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37436476,'Muralha Giratória Incandescente','Todos os monstros "Laval" com a face para cima que você controla ganham 100 de ATK para cada monstro "Laval" no seu Cemitério.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37440988,'Supradragão Arco-Íris',replace(replace('7 monstros "Fera Cristalina"	\r\n(Este card deve ser sempre considerado como um card "Cristalino(a) Definitivo(a)".)	\r\nDeve ser Invocado por Invocação-Fusão ou por Invocação-Especial ao oferecer como Tributo 1 monstro "Cristalino(a) Definitivo(a)" de Nível 10. \r\nUma vez por turno: você pode banir 1 monstro "Fera Cristalina" do seu Cemitério; até o final deste turno, este card ganha ATK igual ao do monstro banido. \r\n(Efeito Rápido): você pode oferecer este card Invocado por Invocação-Fusão como Tributo; embaralhe no Deck todos os cards no campo.','\r',char(13)),'\n',char(10)),'Aumentar ATK','Retornar ao Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37442336,'Dragão Cósmico Quasar',replace(replace('1 Monstro Sincro Regulador + 2+ Monstros Sincro não-Reguladores	\r\nPrimeiro deve ser Invocado por Invocação-Sincro com as matérias acima. \r\nUma vez por turno: você pode escolher cards com a face para cima no campo, até o número de monstros usados como Matéria Sincro para este card +1; negue seus efeitos. \r\nA ativação e o efeito deste efeito não podem ser negados. \r\n(Efeito Rápido): você pode banir este card Invocado por Invocação-Sincro; Invoque por Invocação-Especial 1 Monstro Sincro Dragão do seu Deck Adicional que requer 2+ Monstros Sincro não-Reguladores como matéria. \r\n(Isso é considerado uma Invocação-Sincro.)','\r',char(13)),'\n',char(10)),'Negar os efeitos dos cards no campo','Banir este card e Invocar por Invocação Sincro','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37444964,'Fantasia do Espelho Onírico',replace(replace('Se você controlar um monstro "Espelho Onírico": escolha 1 de cada dos seus "Espelho Onírico da Alegria" e "Espelho Onírico do Terror" banidos; embaralhe-os no Deck e, se isso acontecer, bana 1 card no campo. \r\nSe um ou mais cards "Espelho Onírico" que você controla seriam destruídos em batalha ou por um efeito de card, em vez disso, você pode banir este card do seu Cemitério. \r\nVocê só pode ativar 1 "Fantasia do Espelho Onírico" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37445295,'Falco Sombraneco',replace(replace('VIRE: Você pode escolher 1 monstro "Sombraneco" no seu Cemitério, exceto "Falco Sombraneco"; Invoque-o por Invocação-Especial com a face para baixo em Posição de Defesa.\r\nSe este card for enviado para o Cemitério por um efeito de card: você pode Invocá-lo por Invocação-Especial com a face para baixo em Posição de Defesa. \r\nVocê só pode usar 1 efeito de "Falco Sombraneco" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial 1 monstro "Sombraneco"','Invocar este card por Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37457534,'Tanque do Mecanismo Antigo',replace(replace('Equipe apenas em um monstro "Mecanismo Antigo". \r\nEle ganha 600 de ATK. \r\nQuando este card for destruído e enviado ao Cemitério: Cause 600 de dano ao oponente.','\r',char(13)),'\n',char(10)),'Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37458564,'Bruxa do Contrato Ciberso',replace(replace('2 monstro do mesmo Tipo	\r\nSe este card for Invocado por Invocação-Link, ou um ou mais monstros é Invocado por Invocação-Especial para uma ou mais zonas que este card aponta: você pode enviar 1 Magia da sua mão ou com a face para cima no campo para o Cemitério; adicione 1 Monstro Ritual do seu Deck à sua mão.\r\nVocê pode escolher 1 Monstro Ritual, Fusão, Sincro ou Xyz que este card aponta; Invoque por Invocação-Especial 1 monstro do seu Cemitério com o mesmo Tipo mas com tipo de monstro diferente (Ritual, Fusão, Sincro, Xyz).\r\nVocê só pode usar cada um dos efeitos de "Bruxa do Contrato Ciberso" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicione à sua mão um Monstro Ritual','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37458565,'Bruxa do Contrato Ciberso',replace(replace('2 monstro do mesmo Tipo	\r\nSe este card for Invocado por Invocação-Link, ou um ou mais monstros é Invocado por Invocação-Especial para uma ou mais zonas que este card aponta: você pode enviar 1 Magia da sua mão ou com a face para cima no campo para o Cemitério; adicione 1 Monstro Ritual do seu Deck à sua mão.\r\nVocê pode escolher 1 Monstro Ritual, Fusão, Sincro ou Xyz que este card aponta; Invoque por Invocação-Especial 1 monstro do seu Cemitério com o mesmo Tipo mas com tipo de monstro diferente (Ritual, Fusão, Sincro, Xyz).\r\nVocê só pode usar cada um dos efeitos de "Bruxa do Contrato Ciberso" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicione à sua mão um Monstro Ritual','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37469904,'Aliança dos Duelistas',replace(replace('Se houver um card na Zona de Pêndulo: adicione 1 Monstro Pêndulo "Pêndulo" ou Magia/Armadilha "Pêndulo" do seu Deck à sua mão. \r\nVocê só pode ativar 1 "Aliança dos Duelistas" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37474917,'Guerreiro Catapulta',replace(replace('1 Regulador + 1 ou mais monstros não-Reguladores	\r\nUma vez por turno: você pode oferecer 1 monstro "Sucata" como Tributo; cause dano ao seu oponente igual ao ATK original do monstro oferecido como Tributo.','\r',char(13)),'\n',char(10)),'Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37478723,'"Infernarmas Nobres - Durendal"',replace(replace('Enquanto este card estiver equipado a um monstro: você pode adicionar 1 monstro Guerreiro de FOGO de Nível 5 ou menos do seu Deck à sua mão e, depois, destrua este card. \r\nSe este card for enviado para o Cemitério porque o monstro equipado foi enviado para o Cemitério: você pode escolher 1 monstro Guerreiro de FOGO de Nível 5 ou menos no seu Cemitério; Invoque-o por Invocação-Especial e, além disso, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros Guerreiro. \r\nVocê só pode usar 1 efeito de ""Infernarmas Nobres - Durendal"" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37480144,'Trocar de Coluna','Escolha 1 monstro na sua Zona de Monstros Principal; mova o alvo para outra das suas Zonas de Monstros Principais.','Escolha 1 monstro para mover','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37491810,'Parametalmorfose Azortless',replace(replace('Escala de Pêndulo = 8\r\n[ Efeito de Pêndulo ]\r\nSe um ou mais cards "Metalmorfose" com a face para cima que você controla forem destruídos por um efeito de card (exceto durante a Etapa de Dano): você pode escolher 1 card com a face para cima no campo; destrua-o. \r\nVocê só pode usar este efeito de "Parametalmorfose Azortless" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\n1 monstro "Metalmorfose" + 1 Monstro de Fusão	\r\nSe este card for Invocado por Invocação-Especial do Deck Adicional: você pode escolher 1 card que seu oponente controla; embaralhe no Deck 2 Monstros Pêndulo com a face para cima do seu Deck Adicional e, se isso acontecer, destrua esse card. \r\nVocê só pode usar este efeito de "Parametalmorfose Azortless" uma vez por turno. \r\nSe este card na Zona de Monstros for destruído: você pode colocar este card na sua Zona de Pêndulo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37495766,'ÁS-Resgate Turbulência',replace(replace('Você pode banir 2 cards "ÁS-Resgate" do seu Cemitério; Invoque este card por Invocação-Especial da sua mão. \r\nDurante sua Fase Principal: você pode Baixar até 4 Magias Rápidas/Armadilhas Normais "ÁS-Resgate", com nomes diferentes, diretamente do seu Deck. \r\nSe um ou mais outros cards que você controla deixarem o campo por um efeito de card do oponente (exceto durante a Etapa de Dano): você pode escolher 1 card no campo; destrua-o. \r\nVocê só pode usar cada efeito de "ÁS-Resgate Turbulência" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Destruir 1 card no campo','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37495767,'ÁS-Resgate Turbulência',replace(replace('Você pode banir 2 cards "ÁS-Resgate" do seu Cemitério; Invoque este card por Invocação-Especial da sua mão. \r\nDurante sua Fase Principal: você pode Baixar até 4 Magias Rápidas/Armadilhas Normais "ÁS-Resgate", com nomes diferentes, diretamente do seu Deck. \r\nSe um ou mais outros cards que você controla deixarem o campo por um efeito de card do oponente (exceto durante a Etapa de Dano): você pode escolher 1 card no campo; destrua-o. \r\nVocê só pode usar cada efeito de "ÁS-Resgate Turbulência" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Destruir 1 card no campo','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37507488,'Socorrer o Monstro','Quando um monstro do oponente declarar um ataque: escolha 1 monstro que você controla; devolva o alvo para a mão e, depois, Invoque por Invocação-Especial 1 monstro de Nível 4 da sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37511832,'Farol Sargaço',replace(replace('Quando um efeito de Magia que causaria dano a você for ativado: você não sofre dano desse efeito. \r\nEnquanto este card estiver em seu Cemitério, você não sofre dano do efeito de "Sargaço, o Campo de Batalha D.D.". \r\nQuando este card Baixado for enviado para o Cemitério: você pode adicionar 1 "Sargaço, o Campo de Batalha D.D." do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37517035,'Obra-prima de Artmage -Sucessão-',replace(replace('Durante a Fase Principal: Invoque por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional, usando monstros da sua mão ou do campo, incluindo um monstro "Artmage" e, depois, se um card estiver na Zona do Campo, esse monstro ganha 500 de ATK. \r\nDurante sua Fase Principal: você pode banir este card do seu Cemitério e, depois, escolha 3 cards "Artmage" com nomes diferentes no seu Cemitério; embaralhe-os no Deck. \r\nVocê só pode usar cada efeito de "Obra-prima de Artmage -Sucessão-" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Fusão','Retornar ao Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37520316,'Controle Mental','Escolha 1 monstro que seu oponente controla; até a Fase Final, tome o controle do alvo, mas ele não pode declarar um ataque nem ser oferecido como Tributo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37531679,'Salamandra, o Dragão das Chamas Voador',replace(replace('Enquanto este card estiver equipado a "Espadachim das Chamas" ou um monstro que o mencione, o monstro equipado ganha 700 de ATK. \r\nVocê só pode usar cada um dos seguintes efeitos de "Salamandra, o Dragão das Chamas Voador" uma vez por turno. \r\nSe este card estiver na sua mão ou no Cemitério: você pode escolher 1 monstro Guerreiro que você controla; equipe este card a esse monstro que você controla como uma Magia de Equipamento. \r\nSe este card for enviado para o Cemitério: você pode adicionar 1 Magia/Armadilha "Salamandra" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Efeito de Equipamento','Procurar 1 Magia/Armadilha "Salamandra"','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37534148,'Faixa do Renascimento','Durante a Fase Final, se o monstro equipado foi destruído em batalha e enviado para o Cemitério neste turno: Invoque-o por Invocação-Especial do Cemitério no seu lado do campo.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37542782,'Dragão Final Cibersombrio',replace(replace('"Dragão Cibersombrio" + "Dragão Final Cibernético"	\r\nDeve ser Invocado por Invocação-Fusão, ou Invocado por Invocação-Especial ao oferecer como Tributo 1 Monstro de Fusão "Cibersombrio(a)" de Nível 10 ou menos equipado com "Dragão Final Cibernético". \r\nNão é afetado pelos efeitos ativados do seu oponente. \r\nUma vez por turno: você pode equipar a este card 1 monstro de qualquer Cemitério. \r\nEste card pode atacar um número de vezes a cada Fase de Batalha até o número de Cards de Equipamento equipados a ele.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37552929,'Dama da Lua do Milênio',replace(replace('Se este card batalhar um monstro, nenhum dos dois pode ser destruído nessa batalha. \r\nVocê só pode usar cada um dos seguintes efeitos de "Dama da Lua do Milênio" uma vez por turno. \r\nSe este card estiver na sua mão: você pode colocá-lo na sua Zona de Magias & Armadilhas como uma Magia Contínua com a face para cima. \r\nSe seu oponente ativar um card ou efeito, enquanto este card for uma Magia Contínua (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial e, se isso acontecer, pelo resto deste turno, seu oponente não pode escolher monstros Ilusão ou Mago de Nível 5 ou mais que você controla como alvo de efeitos de card.','\r',char(13)),'\n',char(10)),'Colocá-la como Card de Magia','Invocação Especial','O efeito de "Dama da Lua do Milênio" está sendo aplicado.','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37557626,'Substituto Gishki',replace(replace('Quando este card for Invocado por Invocação-Normal ou Virar: você pode escolher 1 outro monstro que você controla; devolva o alvo para a mão. \r\nVocê deve controlar outro monstro "Gishki" para ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37561138,'Trono de Necro-Vale',replace(replace('Ative 1 desses efeitos.\r\n● Adicione 1 monstro "do Coveiro" do seu Deck à sua mão.\r\n● Imediatamente depois que este efeito resolver, Invoque por Invocação-Normal 1 monstro "do Coveiro".	\r\nVocê só pode ativar 1 "Trono de Necro-Vale" por turno.','\r',char(13)),'\n',char(10)),'Adicionar à sua mão 1 monstro "Coveiro" do seu Deck','Invocar por Invocação Normal 1 monstro "Coveiro" da sua mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37576645,'Ganância Descuidada','Compre 2 cards e pule suas 2 próximas Fases de Compra.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37580756,'Michizure','Quando um monstro for enviado do campo para o seu Cemitério, mesmo durante a Etapa de Dano: escolha 1 monstro no campo; destrua-o.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37582948,'Fofoca da Sunny Live☆Gêmea',replace(replace('Quando este card for ativado: você pode adicionar 1 monstro "Live☆Gêmea" do seu Deck à sua mão. \r\nEnquanto você controlar um monstro "Evil★Gêmea", sempre que seu oponente Invocar um ou mais monstros por Invocação-Normal ou Especial, você ganha 200 PV e, se isso acontecer, cause 200 de dano ao seu oponente. \r\nVocê só pode ativar 1 "Fofoca da Sunny Live☆Gêmea" por turno.','\r',char(13)),'\n',char(10)),'Adicionar à sua mão 1 monstro "Live☆Gêmea" do seu Deck?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37613663,'Ankh do Milênio',replace(replace('Mostre 5 Cards de Monstro "O Proibido" da sua mão, do Deck e/ou do campo com a face para cima e, depois, Invoque por Invocação-Especial 1 "O Imparável Exodia Encarnado" do seu Deck Adicional e, depois, embaralhe no Deck os Cards de Monstro com a face para cima que você controla, exceto Cards de Monstro "Exodia" cujos Níveis originais sejam 10 ou mais e Cards de Monstro "Milênio" e, além disso, você não pode Invocar pelo resto deste turno. \r\nDepois da ativação, embaralhe este card no Deck em vez de enviá-lo para o Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37617348,'ÁS-Resgate Hidrante',replace(replace('Enquanto você controlar um monstro "ÁS-Resgate" que não seja "ÁS-Resgate Hidrante", os monstros do seu oponente não podem escolher este card como alvo de ataques e, além disso, seu oponente não pode escolher este card como alvo de efeitos de card. \r\nVocê só pode usar cada um dos seguintes efeitos de "ÁS-Resgate Hidrante" uma vez por turno. \r\nVocê pode ativar uma Magia Rápida ou um Card de Armadilha que foi Baixado pelo efeito de um card "ÁS-Resgate" seu no turno em que foi Baixado. \r\nDurante sua Fase Principal: você pode adicionar 1 monstro "ÁS-Resgate" do seu Deck à sua mão, exceto "ÁS-Resgate Hidrante".','\r',char(13)),'\n',char(10)),'','Ativar aplicando o efeito de "ÁS-Resgate Hidrante".','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37620434,'Manipuladora Sombria',replace(replace('(Este card é tratado como um card "Arquidemônio".)	\r\nVIRE: Escolha 1 monstro do Tipo Demônio que seu oponente controla; até a Fase Final, tome o controle do alvo.','\r',char(13)),'\n',char(10)),'Transferir o controle','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37626500,'Benção dos Duendes',replace(replace('Este card pode ser usado para a Invocação-Ritual de qualquer Monstro de Ritual de LUZ. \r\nVocê também deve oferecer como Tributo monstros da sua mão ou do campo cuja soma dos Níveis seja exatamente igual ao Nível do Monstro de Ritual que você Invocar por Invocação-Ritual.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37629703,'Candragela Labrinto',replace(replace('(Efeito Rápido): você pode enviar este card da sua mão ou do campo para o Cemitério e descartar 1 card; Baixe 1 Magia/Armadilha "Labrinto" da sua mão ou do Deck. \r\nSe um ou mais monstros deixarem o campo pelo efeito de uma Armadilha Normal sua, enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode adicionar este card à sua mão. \r\nVocê só pode usar cada efeito de "Candragela Labrinto" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Adicionar este card à sua mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37630732,'Vínculo de Poder',replace(replace('Invoque por Invocação-Fusão 1 Monstro de Fusão Máquina do seu Deck Adicional, usando monstros da sua mão ou do campo como Matéria de Fusão, e ele ganha ATK igual ao seu próprio ATK original. \r\nDurante a Fase Final do turno em que este card for ativado, você sofre dano igual ao valor de ATK ganho por este efeito no momento da Invocação.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37649320,'Paleozoico Opabinia',replace(replace('2 monstros de Nível 2	\r\nEste card não é afetado por outros efeitos de monstro. \r\nVocê pode ativar Cards de Armadilha "Paleozoico" da sua mão. \r\nSe este card tiver um Card de Armadilha como Matéria Xyz: você pode desassociar 1 Matéria Xyz deste card; adicione 1 Card de Armadilha "Paleozoico" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Paleozoico Opabinia" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Ativar aplicando o efeito de "Paleozoico Opabinia".','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37654623,'Esconderijo no Céu, Coulomb',replace(replace('Monstros que você controla que foram Invocados por Invocação-Normal ou Especial da mão ganham 500 de ATK/DEF. \r\nVocê só pode usar cada um dos seguintes efeitos de "Esconderijo no Céu, Coulomb" uma vez por turno. \r\nDurante sua Fase Principal: você pode Invocar por Invocação-Especial 1 "Ficha de Besta Mech" (Máquina/TERRA/Nível 6/ATK 2000/DEF 2000) no campo do seu oponente e, se isso acontecer, adicione 1 monstro "Blitzclique" do seu Deck à sua mão. \r\nSe um ou mais cards forem destruídos por um efeito de card "Blitzclique" seu, enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode adicionar este card à sua mão.','\r',char(13)),'\n',char(10)),'','Invocar por Invocação Especial e adicionar à mão','Retornar para a mão','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37654624,'Ficha de Mecabesta','Invocado por Invocação-Especial pelo efeito de "Kowloon, a Cidade do Céu".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37663536,'Golem Megaton do Mecanismo Antigo',replace(replace('3 monstros "Mecanismo Antigo"	\r\nSe este card atacar, seu oponente não pode ativar Cards de Magia/Armadilha até o final da Etapa de Dano. \r\nSe este card foi Invocado por Invocação-Fusão usando 2 ou mais "Golem do Mecanismo Antigo" e/ou "Golem do Mecanismo Antigo - Murro Definitivo" como matéria, ele pode atacar até esse número de vezes durante cada Fase de Batalha. \r\nSe este card com a face para cima Invocado por Invocação-Fusão e sob o controle do seu dono deixar o campo devido a um efeito de card do oponente: você pode Invocar por Invocação-Especial 1 "Golem do Mecanismo Antigo Definitivo" do seu Deck Adicional, ignorando suas condições de Invocação.','\r',char(13)),'\n',char(10)),'Invocar "Golem do Mecanismo Antigo Definitivo" por Invocação Especial','O efeito de "Golem Megaton do Mecanismo Antigo" está sendo aplicado.','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37675138,'Esmagador de Ossos',replace(replace('Quando este card for Invocado por Invocação-Especial do seu Cemitério pelo efeito de um monstro do Tipo Zumbi: Você pode escolher 1 Card de Magia/Armadilha que seu oponente controla; destrua o alvo. \r\nDurante a Fase Final do turno em que este card foi Invocado por Invocação-Especial: Destrua-o.','\r',char(13)),'\n',char(10)),'Destruir','Autodestruir-se','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37675907,'Acelerador Sincron',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nUma vez por turno: você pode enviar 1 monstro "Sincron" do seu Deck para o Cemitério e, depois, ative 1 desses efeitos;\r\n● Aumente o Nível deste card pelo Nível do monstro enviado.\r\n● Reduza o Nível deste card pelo Nível do monstro enviado.	\r\nDurante a Fase Principal do seu oponente, você pode (Efeito Rápido): imediatamente depois que este efeito resolver, Invoque por Invocação-Sincro usando este card que você controla. \r\nVocê só pode Invocar "Acelerador Sincron" por Invocação-Sincro uma vez por turno.','\r',char(13)),'\n',char(10)),'Alterar o Nível','Invocação Sincro','Aumentar o Nível','Reduzir o Nível','','','','','','','','','','','','');
INSERT INTO texts VALUES(37678339,'Oniro, o Atormentador do Espelho Onírico',replace(replace('2 monstros "Espelho Onírico" com Atributos diferentes	\r\nEnquanto estiver com a face para cima no campo, este card também é de Atributo LUZ. \r\nVocê só pode usar cada um dos seguintes efeitos de "Oniro, o Atormentador do Espelho Onírico" uma vez por turno.\r\n● Quando um efeito de monstro for ativado enquanto "Espelho Onírico do Terror" estiver em uma Zona do Campo (Efeito Rápido): você pode negar o efeito.\r\n● Se "Espelho Onírico da Alegria" estiver em uma Zona do Campo (Efeito Rápido): você pode oferecer este card como Tributo; Invoque por Invocação-Especial 1 "Oniro, o Erlking do Espelho Onírico" do seu Deck Adicional em Posição de Defesa.','\r',char(13)),'\n',char(10)),'Negar o efeito','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37679169,'Transporte Delta de Kozmo',replace(replace('Uma vez por turno: você pode enviar 1 monstro "Kozmo" do seu Deck para o Cemitério e, depois, escolher 1 monstro com a face para cima no campo; ele perde ATK e DEF igual ao Nível do monstro enviado x 100. \r\nSe este card for destruído em batalha ou por um efeito de card e enviado para o Cemitério: você pode banir este card do seu Cemitério; Invoque por Invocação-Especial 1 monstro "Kozmo" de Nível 4 ou menos do seu Deck.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37683441,'Trapestrela Anjo Nobre',replace(replace('2 monstros "Trapestrela"	\r\nSe este card for Invocado por Invocação-Link: você pode adicionar 1 card "Lágrimas Azuis" do seu Deck à sua mão. \r\nSe você tiver um Monstro de Fusão no seu campo ou Cemitério: você pode escolher 1 monstro "Trapestrela" no seu Cemitério; Invoque-o por Invocação-Especial. \r\nSe dano de efeito for causado (exceto durante a Etapa de Dano): você pode escolher 1 card com a face para cima no campo; destrua-o. \r\nVocê só pode usar cada efeito de "Trapestrela Anjo Nobre" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicione à sua mão 1 card "Lágrimas Azuis"','Efeito de ressuscitar','Efeito de destruição','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37683547,'Arbaz, o Cinzento',replace(replace('O nome deste card se torna "Caído de Arbaz" enquanto estiver no campo ou no Cemitério. \r\nEnquanto um Monstro de Fusão de Nível 8 estiver no seu Cemitério, este card ganha 200 de ATK para cada monstro no seu Cemitério e, além disso, seu oponente não pode escolher outros monstros que você controla como alvo de efeitos de card. \r\nSe um ou mais monstros que você controla deixarem o campo por um efeito de card do oponente, enquanto este card e um Monstro de Fusão estiverem no seu Cemitério (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial. \r\nVocê só pode usar este efeito de "Arbaz, o Cinzento" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37684215,'Espada de Fusão Lâmina Murasame',replace(replace('Só pode ser equipado a um monstro Guerreiro. \r\nEle ganha 800 de ATK. \r\nEnquanto estiver equipado a um monstro, este card não pode ser destruído por efeitos de card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37694547,'Vila Mecânica',replace(replace('Os dois duelistas podem Invocar por Invocação-Normal monstros "Mecanismo Antigo" oferecendo 1 Tributo a menos. \r\nQuando este card for destruído e enviado para o Cemitério: você pode Invocar por Invocação-Especial 1 monstro "Mecanismo Antigo" da sua mão, do Deck ou do Cemitério.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37706769,'O Executor do Submundo - Plutão',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\n(Este card deve ser sempre considerado como um card "O Representante".)	\r\nUma vez por turno: você pode banir 1 monstro do seu Cemitério e, depois, escolha 1 Monstro de Efeito no campo; coloque-o com a face para baixo em Posição de Defesa. \r\nEste é um Efeito Rápido se "O Santuário no Céu" estiver no campo ou em qualquer Cemitério. \r\nVocê pode banir este card do seu Cemitério; adicione 1 "O Santuário no Céu" do seu Deck ou Cemitério à sua mão. \r\nVocê só pode usar este efeito de "O Executor do Submundo - Plutão" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37720300,'Avião Espacial de Ajuste',replace(replace('Você pode escolher 1 outro monstro Máquina que você controla; até o final deste turno, os Níveis tanto desse monstro quanto deste card se tornam os Níveis combinados desses 2 monstros e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto Monstros Xyz Máquina. \r\nVocê só pode usar este efeito de "Avião Espacial de Ajuste" uma vez por turno.','\r',char(13)),'\n',char(10)),'Alterar Nível','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37721209,'Levia-Dragão - Daedalus','Você pode enviar 1 "Umi" com a face para cima que você controla para o Cemitério; destrua todos os outros cards no campo.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37742478,'Honesto',replace(replace('Durante sua Fase Principal: você pode devolver este card com a face para cima do campo para a mão. \r\nDurante a Etapa de Dano, quando um monstro de LUZ que você controla batalhar (Efeito Rápido): você pode enviar este card da sua mão para o Cemitério; até o final deste turno, esse monstro ganha ATK igual ao ATK do monstro do oponente que ele estiver batalhando.','\r',char(13)),'\n',char(10)),'Retornar à mão','Aumentar ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37742479,'Honesto',replace(replace('Durante sua Fase Principal: você pode devolver este card com a face para cima do campo para a mão. \r\nDurante a Etapa de Dano, quando um monstro de LUZ que você controla batalhar (Efeito Rápido): você pode enviar este card da sua mão para o Cemitério; até o final deste turno, esse monstro ganha ATK igual ao ATK do monstro do oponente que ele estiver batalhando.','\r',char(13)),'\n',char(10)),'Retornar à mão','Aumentar ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37744402,'Wynn, a Encantadora do Vento','VIRE: Escolha 1 monstro de VENTO que seu oponente controla; tome o controle desse monstro enquanto este card estiver com a face para cima no campo.','Tome o controle de 1 monstro de VENTO que seu oponente controla','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37744403,'Wynn, a Encantadora do Vento','VIRE: Escolha 1 monstro de VENTO que seu oponente controla; tome o controle desse monstro enquanto este card estiver com a face para cima no campo.','Tome o controle de 1 monstro de VENTO que seu oponente controla','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37744404,'Wynn, a Encantadora do Vento','VIRE: Escolha 1 monstro de VENTO que seu oponente controla; tome o controle desse monstro enquanto este card estiver com a face para cima no campo.','Tome o controle de 1 monstro de VENTO que seu oponente controla','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37745740,'Camarartista Grilarco',replace(replace('Você pode oferecer 1 monstro "Camarartista" como Tributo; cause dano ao seu oponente igual ao Nível que ele tinha no campo x 100 (o Nível original, se ele estava com a face para baixo). \r\nVocê pode oferecer 1 monstro "Camarartista" como Tributo e, depois, escolher 1 monstro "Camarartista" no seu Cemitério que não seja o monstro oferecido como Tributo; adicione-o à sua mão. \r\nVocê só pode usar cada efeito de "Camarartista Grilarco" uma vez por turno.','\r',char(13)),'\n',char(10)),'Dano de efeito','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37745919,'Caixa de Sucata','Escolha 1 monstro "Morfotrônico(a)" de Nível 4 ou menos no seu Cemitério; Invoque-o por Invocação-Especial, mas destrua-o durante a Fase Final deste turno.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37750912,'Iluminação da Poeira Estelar',replace(replace('Envie 1 monstro "Poeira Estelar" do seu Deck para o Cemitério, ou se você controlar "Dragão da Poeira Estelar" ou um Monstro Sincro que o mencione, em vez disso, você pode Invocá-lo por Invocação-Especial. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 monstro "Poeira Estelar" que você controla; aumente ou diminua o Nível dele em 1 até o final deste turno. \r\nVocê só pode usar cada efeito de "Iluminação da Poeira Estelar" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Aumentar o Nível','Reduzir o Nível','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37752990,'Dinonévoa Cerátopo',replace(replace('Escala de Pêndulo = 3\r\n[ Efeito de Pêndulo ]\r\nSe outro(s) card(s) "Dinonévoa" que você controla seria(m) destruído(s) em batalha ou por um efeito de card do oponente, em vez disso, você pode destruir este card.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe todos os monstros que você controla forem monstros "Dinonévoa" (mín. 1) e nenhum for "Dinonévoa Cerátopo", você pode Invocar este card por Invocação-Especial (da sua mão).','\r',char(13)),'\n',char(10)),'Usar o efeito de "Dinonévoa Cerátopo" em vez de ser destruído?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37780349,'HERÓI do Destino - Dínatag',replace(replace('Durante o cálculo de dano, quando você sofreria dano de batalha (Efeito Rápido): você pode descartar este card; faça com que você não sofra dano de batalha dessa batalha e, se isso acontecer, cada duelista sofre 1000 de dano. \r\nVocê pode banir este card do seu Cemitério e, depois, escolher 1 monstro "HERÓI do Destino" que você controla; ele ganha 1000 de ATK até o final do próximo turno do seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37781520,'Sirena Abisleed',replace(replace('Você pode descartar 3 outros monstros de ÁGUA para o Cemitério; Invoque este card por Invocação-Especial da sua mão. \r\nQuando Invocado desta forma: você pode escolher 1 Magia/Armadilha "Abis-" no seu Cemitério; adicione o alvo à sua mão. \r\nVocê pode oferecer como Tributo 1 outro monstro "Sirena" em Posição de Ataque; envie 1 card aleatório da mão do seu oponente para o Cemitério. \r\nVocê só pode usar este efeito de "Sirena Abisleed" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Recuperar Magias/Armadilhas','Enviar 1 card da sua mão para o Cemitério','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37792478,'Metabo-Tubarão','Quando este card for Invocado por Invocação-Normal: você pode escolher 2 monstros do Tipo Peixe no seu Cemitério; embaralhe os alvos no seu Deck.','Retornar ao Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37798171,'Tubarão das Profundezas',replace(replace('Se você não controlar nenhum monstro, você pode Invocar este card por Invocação-Normal sem oferecer Tributo. \r\nUma vez por turno, durante a Fase de Apoio do seu oponente: o ATK deste card se torna o dobro do seu ATK atual até o final deste turno.','\r',char(13)),'\n',char(10)),'Invocar sem oferecer monstros como Tributo','Aumentar ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37799519,'Sincron da Poeira Estelar',replace(replace('Se este card estiver na sua mão ou no Cemitério: você pode oferecer 1 monstro como Tributo; Invoque este card por Invocação-Especial, mas bana-o quando ele deixar o campo e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto Monstros Sincro. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 Magia/Armadilha do seu Deck à sua mão que mencione "Dragão da Poeira Estelar". \r\nVocê só pode usar cada efeito de "Sincron da Poeira Estelar" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37803172,'Peryton da Chama Nebulosa',replace(replace('Não pode ser Invocado por Invocação-Especial, exceto por um efeito de monstro "Chama Nebulosa". \r\nSeu oponente não pode escolher este card como alvo de efeitos de card. \r\nVocê pode enviar 1 monstro de FOGO da sua mão para o Cemitério e oferecer este card como Tributo; Invoque por Invocação-Especial 2 monstros "Chama Nebulosa" do seu Deck. \r\nVocê só pode usar este efeito de "Peryton da Chama Nebulosa" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37803970,'Pêndulo Incrível',replace(replace('Se você não tiver cards na sua Zona de Pêndulo: adicione 2 Monstros Pêndulo "Mago" com a face para cima com nomes diferentes do seu Deck Adicional à sua mão. \r\nVocê só pode ativar 1 "Pêndulo Incrível" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37806313,'Caravana da Barreira de Gelo','Uma vez por turno: você pode escolher 2 monstros "Barreira de Gelo" no seu Cemitério; embaralhe os dois no Deck e, depois, cada duelista compra 1 card.','Retornar ao Deck e comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37812118,'Taça de Ases',replace(replace('Lance uma moeda:\r\n● Cara: Compre 2 cards.\r\n● Coroa: Seu oponente compra 2 cards.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37818794,'Dragoon Negro de Olhos Vermelhos',replace(replace('"Mago Negro" + "Dragão Negro de Olhos Vermelhos" ou 1 Monstro de Efeito Dragão	\r\nNão pode ser destruído por efeitos de card. \r\nNenhum duelista pode escolher este card como alvo de efeitos de card. \r\nDurante sua Fase Principal: você pode destruir 1 monstro que seu oponente controla e, se isso acontecer, cause dano ao seu oponente igual ao ATK original desse monstro. \r\nVocê pode usar este efeito um número de vezes por turno até o número de Monstros Normais usados como Matéria de Fusão para este card. \r\nUma vez por turno, quando um card ou efeito for ativado (Efeito Rápido): você pode descartar 1 card; negue a ativação e, se isso acontecer, destrua esse card e, se isso acontecer, este card ganha 1000 de ATK.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37818795,'Dragoon Negro de Olhos Vermelhos',replace(replace('"Mago Negro" + "Dragão Negro de Olhos Vermelhos" ou 1 Monstro de Efeito Dragão	\r\nNão pode ser destruído por efeitos de card. \r\nNenhum duelista pode escolher este card como alvo de efeitos de card. \r\nDurante sua Fase Principal: você pode destruir 1 monstro que seu oponente controla e, se isso acontecer, cause dano ao seu oponente igual ao ATK original desse monstro. \r\nVocê pode usar este efeito um número de vezes por turno até o número de Monstros Normais usados como Matéria de Fusão para este card. \r\nUma vez por turno, quando um card ou efeito for ativado (Efeito Rápido): você pode descartar 1 card; negue a ativação e, se isso acontecer, destrua esse card e, se isso acontecer, este card ganha 1000 de ATK.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37820550,'Chicote Elétrico','Um monstro do Tipo Trovão equipado com este card aumenta o seu ATK e DEF em 300 pontos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37829468,'Rai-Jin',replace(replace('Todos os monstros de LUZ que você controla ganham 100 de ATK para cada monstro de LUZ no seu Cemitério. \r\nDurante sua Fase Final, destrua 1 monstro de LUZ que você controla. \r\nSó pode haver 1 "Rai-Jin" com a face para cima no campo.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37839434,'Domnínio Divino de Asutra',replace(replace('Ative 1 desses efeitos;\r\n● Invoque por Invocação-Especial este card como um Monstro Normal (Aqua/Regulador/TREVAS/Nível 1/ATK 0/DEF 0) (este card NÃO é considerado como uma Armadilha), então imediatamente após ativar este efeito, você pode Invocar por Invocação-Sincro 1 Monstro Sincro.\r\n● Quando seu oponente ativar um Magia/Armadilha ou efeito e ele não controla cards com a face para baixo: negue aquele efeito.	\r\nVocê só pode ativar 1 "Domnínio Divino de Asutra" por turno.','\r',char(13)),'\n',char(10)),'Ativar','Invocar por Invocação Especial como monstro','Negar o efeito','Invocação Sincro?','','','','','','','','','','','','');
INSERT INTO texts VALUES(37869028,'Víbora Hídrica',replace(replace('Sempre que este card declarar um ataque, você deve oferecer como Tributo 1 monstro do Tipo Aqua. \r\nEste card pode atacar 3 vezes durante cada Fase de Batalha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37880706,'Quimera Pequena Preguiçosa',replace(replace('2 monstros de FOGO	\r\nTodos os monstros de FOGO no campo ganham 500 de ATK/DEF e, além disso, todos os monstros de ÁGUA no campo perdem 400 de ATK/DEF. \r\nSe este card for destruído em batalha ou por um efeito de card: você pode escolher 1 monstro de FOGO no seu Cemitério; adicione-o à sua mão. \r\nVocê só pode usar este efeito de "Quimera Pequena Preguiçosa" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37890974,'Treinamento de Peluguel, Pelos Todas as Necessidades de Treinamento',replace(replace('Se um ou mais monstros "de Peluguel" com a face para cima que você controla forem destruídos em batalha ou por um efeito de card do oponente: você pode escolher 1 desses monstros; Invoque por Invocação-Especial 1 monstro "de Peluguel" do seu Deck, cujo Nível seja menor que o Nível original do alvo. \r\nVocê só pode usar este efeito de "Treinamento de Peluguel, Pelos Todas as Necessidades de Treinamento" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar, mas não resolver o efeito','Invocar por Invocação Especial do Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37910722,'Dragão Celeste da Ascensão',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro: ele ganha 800 de ATK para cada card atualmente na sua mão. \r\nQuando este card que você controla for destruído por um card do seu oponente e enviado para o seu Cemitério, se todos os monstros que foram usados para a Invocação-Sincro deste card estiverem no seu Cemitério: você pode Invocar todos eles por Invocação-Especial, mas seus efeitos são negados. \r\nVocê só pode usar este efeito de "Dragão Celeste da Ascensão" uma vez por turno.','\r',char(13)),'\n',char(10)),'Aumentar ATK','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37926346,'Barata Hordeum Ferro',replace(replace('2 monstros de Nível 4	\r\nQuando um ou mais monstros de Nível 5 ou mais seriam Invocados por Invocação-Especial (Efeito Rápido): você pode desassociar 1 matéria deste card; negue a Invocação-Especial e, se isso acontecer, destrua-o.','\r',char(13)),'\n',char(10)),'Negar a Invocação Especial de um monstro de Nível 5 ou mais e destruí-lo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37930737,'Equilíbrio Gravitacional',replace(replace('(Este card deve ser sempre considerado como um card "G Golem".)	\r\nEscolha 2 dos seus monstros de TERRA com o mesmo nome que estiverem banidos ou no seu Cemitério; Invoque os dois por Invocação-Especial em Posição de Defesa, mas negue seus efeitos, mude o ATK/DEF deles para 0 e, além disso, destrua-os durante a Fase Final. \r\nSe um ou mais monstros "G Golem" que você controla seriam destruídos em batalha ou por um efeito de card do oponente, em vez disso, você pode banir este card do seu Cemitério. \r\nVocê só pode usar cada efeito de "Equilíbrio Gravitacional" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37931734,'Luta do Chefe Generaidor',replace(replace('Ative 1 Magia de Campo "Generaidor" diretamente do seu Deck ou Cemitério e, depois, seu oponente compra 1 card. \r\nVocê só pode ativar 1 "Luta do Chefe Generaidor" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37953640,'Enguia Real do Pântano','Se este card for usado como um Monstro Matéria Sincro, todos os outros Monstros Matéria Sincro devem ser do Tipo Peixe.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37955049,'Gaap, o Soldado Divino',replace(replace('Todos os monstros são colocados em Posição de Ataque e, além disso, suas posições de batalha não podem ser mudadas. \r\n(Efeitos de Virar não são ativados.) \r\nUma vez por turno: você pode revelar qualquer número de monstros Demônio na sua mão; até o final deste turno, este card ganha 300 de ATK para cada um.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37957847,'Princesa Inseto',replace(replace('Todos os monstros Inseto que seu oponente controla são colocados em Posição de Ataque. \r\nSe este card destruir um monstro Inseto em batalha: este card ganha 500 de ATK.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37961969,'Lagrimentiara Havnis',replace(replace('Quando seu oponente ativar um efeito de monstro no campo (Efeito Rápido): você pode Invocar este card por Invocação-Especial da sua mão e, se isso acontecer, envie os 3 cards do topo do seu Deck para o Cemitério. \r\nSe este card for enviado para o Cemitério por um efeito de card (exceto durante a Etapa de Dano): você pode Invocar por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional, ao colocar as Matérias de Fusão mencionadas nele da sua mão, do campo e/ou do Cemitério, incluindo este card do seu Cemitério, no fundo do Deck em qualquer ordem. \r\nVocê só pode usar cada efeito de "Lagrimentiara Havnis" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37970940,'Aussa, a Encantadora da Terra','VIRE: Escolha 1 monstro de TERRA que seu oponente controla; tome o controle desse monstro enquanto este card estiver com a face para cima no campo.','Tome o controle de 1 monstro de TERRA que seu oponente controla','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37970941,'Aussa, a Encantadora da Terra','VIRE: Escolha 1 monstro de TERRA que seu oponente controla; tome o controle desse monstro enquanto este card estiver com a face para cima no campo.','Tome o controle de 1 monstro de TERRA que seu oponente controla','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37970942,'Aussa, a Encantadora da Terra','VIRE: Escolha 1 monstro de TERRA que seu oponente controla; tome o controle desse monstro enquanto este card estiver com a face para cima no campo.','Tome o controle de 1 monstro de TERRA que seu oponente controla','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37972500,'MaiorSolfacorde Musecia',replace(replace('2 Monstros Pêndulo	\r\nDurante sua Fase Principal: você pode adicionar 1 Monstro Pêndulo da sua mão ao Deck Adicional com a face para cima, e 1 Monstro Pêndulo com a face para cima do seu Deck Adicional à mão, contanto que um deles tenha uma Escala de Pêndulo par e o outro tenha uma Escala de Pêndulo ímpar. \r\nQuando você Invocar um ou mais monstros "Solfacorde" por Invocação-Pêndulo: você pode escolher 1 deles; adicione 1 Monstro Pêndulo "Solfacorde" do seu Deck à sua mão, cujo Nível seja igual à Escala de Pêndulo desse monstro. \r\nVocê só pode ativar cada efeito de "MaiorSolfacorde Musecia" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Escolha 1 card para adicionar ao Deck Adicional','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37984162,'Golem Gorgônico',replace(replace('Se este card for destruído em batalha e enviado para o Cemitério: o ATK do monstro que o destruiu se torna 0. \r\nVocê pode banir este card do seu Cemitério e, depois, escolher 1 Card de Magia/Armadilha Baixado que seu oponente controla; o alvo não pode ser ativado neste turno. \r\nSeu oponente não pode ativar o card escolhido em resposta à ativação deste efeito.','\r',char(13)),'\n',char(10)),'O ATK se torna 0','Restrição de ativação','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37984331,'Verdadeiro Exodia','Se os únicos monstros no campo forem este card e 4 monstros Normais ''O Proibido'' com nomes diferentes, o oponente do controlador deste card vence o Duelo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37991342,'Espiral Qliphort',replace(replace('Escala de Pêndulo = 9\r\n[ Efeito de Pêndulo ]\r\nVocê não pode Invocar monstros por Invocação-Especial, exceto monstros "Qli". \r\nEste efeito não pode ser negado. \r\nTodos os monstros que seu oponente controla perdem 300 de ATK.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nVocê pode Invocar este card por Invocação-Normal sem oferecer Tributo. \r\nSe este card for Invocado por Invocação-Normal sem oferecer Tributo, ou se for Invocado por Invocação-Especial, o Nível dele se torna 4 e o ATK original dele se torna 1800. \r\nSe este card for Invocado por Invocação-Normal/Baixado, ele não é afetado por efeitos ativados de monstros cujo Nível/Classe original seja menor que o Nível atual deste card. \r\nSe este card for oferecido como Tributo: você pode escolher 1 Card de Magia/Armadilha no campo; destrua-o.','\r',char(13)),'\n',char(10)),'Invocação Normal sem Tributo','Destruir Magias/Armadilhas','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37993923,'Gardna da Sucata',replace(replace('"Sucata Sincron" + 1 ou mais monstros não-Reguladores	\r\nUma vez por turno, você pode selecionar 1 monstro que seu oponente controla e mudar sua posição de batalha. \r\nEste efeito pode ser ativado durante o turno de qualquer duelista. \r\nSe este card for enviado do campo ao Cemitério, você pode selecionar 1 monstro no campo e mudar sua posição de batalha.','\r',char(13)),'\n',char(10)),'Mudar a posição de batalha','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38001022,'Selo de Barian',replace(replace('Quando seu oponente ativa uma Magia/Armadilha, ou efeito de monstro, enquanto você controla um monstro "CXyz" ou um monstro "Número C" com um número entre "101" e "107" em seu nome: negue a ativação, então você pode associar 1 monstro de qualquer campo ou Cemitério à 1 Monstro Xyz que você controla.\r\nVocê pode banir este card do seu Cemitério; Invoque por Invocação-Especial 2 monstros "Terror Umbral" do seu Cemitério.\r\nVocê só pode usar 1 dos efeitos de "Selo de Barian" e somente uma vez por turno.','\r',char(13)),'\n',char(10)),'Negar','Invocação Especial','Associar Matéria Xyz?','Escolha 1 Monstro Xyz','','','','','','','','','','','','');
INSERT INTO texts VALUES(38007649,'Mudança DoomZ',replace(replace('Destrua 1 card "DoomZ" na sua mão, no Deck ou no campo com a face para cima, exceto "Mudança DoomZ". \r\nSe este card for destruído por um efeito de card: você pode adicionar 1 card "DoomZ" do seu Cemitério à sua mão, exceto "Mudança DoomZ" e, depois, você pode Invocar por Invocação-Especial 1 monstro "DoomZ" da sua mão. \r\nVocê só pode usar cada efeito de "Mudança DoomZ" uma vez por turno.','\r',char(13)),'\n',char(10)),'Destruir','Recuperar','Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38007744,'Cronomalia Portador Moai','Se seu oponente controlar um card e você não controlar nenhum card, você pode Invocar este card por Invocação-Especial (da sua mão).','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38026562,'Vola-Criaquímica Methidraco',replace(replace('2 monstros Gêmeos de Nível 8	\r\nQuando este card for Invocado por Invocação-Xyz: você pode escolher 1 monstro Gêmeos no seu Cemitério; Invoque-o por Invocação-Especial. \r\nEnquanto este card tiver Matérias Xyz, monstros que seu oponente controla não podem escolher monstros Gêmeos que você controla como alvo de ataques e, além disso, seu oponente não pode escolher monstros Gêmeos que você controla como alvo de efeitos de card. \r\nQuando um monstro Gêmeos for Invocado por Invocação-Normal: você pode desassociar 1 Matéria Xyz deste card; faça com que seu oponente envie 1 card da mão ou do campo dele para o Cemitério (ele seleciona).','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial um monstro Gêmeos do Cemitério','Enviar para o Cemitério 1 card do seu oponente','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38030232,'Espírito Tenyi - Sahasrara',replace(replace('2+ monstros Wyrm	\r\nEnquanto você controlar um Monstro que não seja de Efeito com a face para cima, os monstros que seu oponente controla não podem escolher Monstros de Efeito como alvo de ataques e, além disso, seu oponente não pode escolher Monstros de Efeito no campo como alvo de efeitos de card. \r\n(Efeito Rápido): você pode escolher 1 Monstro de Efeito que seu oponente controla; Invoque por Invocação-Especial 1 "Ficha de Espírito Tenyi" (Wyrm/LUZ/Nível 4/ATK ?/DEF 0). \r\nO ATK dessa Ficha se torna o ATK original desse monstro alvo. \r\nVocê só pode usar este efeito de "Espírito Tenyi - Sahasrara" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38030233,'Ficha de Espírito Tenyi','Invocada por Invocação-Especial com o efeito "Espírito Tenyi - Sahasrara". Quando Invocada, o ATK desta Ficha fica igual ao ATK original do monstro-alvo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38033121,'Pequena Maga Negra','Ganha 300 de ATK para cada "Mago Negro" ou "Mago do Caos das Trevas" nos Cemitérios.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38033122,'Pequena Maga Negra','Ganha 300 de ATK para cada "Mago Negro" ou "Mago do Caos das Trevas" nos Cemitérios.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38033123,'Pequena Maga Negra','Ganha 300 de ATK para cada "Mago Negro" ou "Mago do Caos das Trevas" nos Cemitérios.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38033124,'Pequena Maga Negra','Ganha 300 de ATK para cada "Mago Negro" ou "Mago do Caos das Trevas" nos Cemitérios.','','','','','','','','','','','','','','','','');
