INSERT INTO texts VALUES(46999905,'Saambell, o Vínculo Estelar',replace(replace('Escala de Pêndulo = 7\r\n[ Efeito de Pêndulo ]\r\nSe você tiver um Card de Monstro Pêndulo com o mesmo Nível que o deste card na sua outra Zona de Pêndulo: você pode destruir o card na sua outra Zona de Pêndulo e, se isso acontecer, Invoque este card por Invocação-Especial. \r\nVocê só pode usar este efeito de "Saambell, o Vínculo Estelar" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe um monstro for Invocado por Invocação-Especial no seu campo enquanto você controlar este monstro (exceto durante a Etapa de Dano): você pode Invocar por Invocação-Especial 1 monstro da sua mão com o mesmo Nível que o deste card. \r\nVocê só pode usar este efeito de "Saambell, o Vínculo Estelar" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47013502,'Dragão Esquivador',replace(replace('A Invocação-Normal deste card não pode ser negada. \r\nDepois que este card foi Invocado por Invocação-Normal, seu oponente não pode ativar Cards de Resposta pelo resto do turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47017574,'Número C92: Dragão do Caos Heart-eartH',replace(replace('4 monstros de Nível 10	\r\nNão pode ser destruído em batalha. \r\nSe um monstro que você controla causar dano de batalha ao seu oponente: você ganha PV igual ao dano que ele sofreu. \r\nSe este card tiver "Número 92: Dragão Heart-eartH" como matéria, ele ganha este efeito.\r\n● Uma vez por turno: você pode desassociar 1 matéria deste card; até o final deste turno, negue os efeitos de todos os cards com a face para cima que seu oponente controla atualmente.	\r\nEsta ativação e efeito não podem ser negados.','\r',char(13)),'\n',char(10)),'Ganhar PV','Negar o efeito','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47021196,'U.A. Agente do Jogador',replace(replace('Se você Invocar um ou mais monstros "U.A." por Invocação-Normal ou Especial (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe este card for Invocado por Invocação-Especial: você pode ativar 1 desses efeitos.\r\n● Escolha 1 card no campo; destrua-o.\r\n● Até o final deste turno, negue os efeitos de todos os monstros com a face para cima no campo, exceto monstros "U.A.".	\r\nVocê só pode usar cada efeito de "U.A. Agente do Jogador" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invoque este card por Invocação Especial da sua mão','Destruir 1 card','Negar o efeito','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47025270,'Robô Ajudante de Combate','Se este card destruir um monstro do oponente em batalha: compre 1 card e, depois, devolva 1 card da sua mão para o fundo do Deck.','Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47027714,'T.G. Canhão Alabarda/Modo de Ataque',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial com "Ativar Modo de Ataque". \r\nVocê só pode usar cada um dos seguintes efeitos de "T.G. Canhão Alabarda/Modo de Ataque" uma vez por turno.\r\n● Quando seu oponente Invocaria um monstro (Efeito Rápido): você pode negar a Invocação e, se isso acontecer, bana esse monstro e todos os monstros Invocados por Invocação-Especial que seu oponente controla.\r\n● Quando este card no campo for destruído: você pode escolher 1 "T.G. Canhão Alabarda" no seu Cemitério; Invoque-o por Invocação-Especial, ignorando suas condições de Invocação.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47028805,'Magi Mesclada L',replace(replace('Ganha ATK igual à soma dos Valores Link dos Monstros Link no seu Cemitério x 400. \r\nDurante a Fase Principal, se este card estiver na sua mão (Efeito Rápido): você pode oferecer como Tributo 1 monstro Ciberso ou 1 Monstro Link; Invoque este card por Invocação-Especial. \r\nVocê só pode usar este efeito de "Magi Mesclada L" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Aumentar ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47030842,'Engrenagiacelerador',replace(replace('Se você controlar um monstro "Engrenagi", você pode Invocar este card por Invocação-Especial (da sua mão) em Posição de Defesa. \r\nQuando este card for enviado do campo para o Cemitério: você pode escolher 1 monstro "Engrenagi" no seu Cemitério, exceto "Engrenagiacelerador"; adicione o alvo à sua mão.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47051709,'Caça Delta de Fóton',replace(replace('Se este card for Invocado por Invocação-Normal: você pode Invocar por Invocação-Especial 1 "Caça Delta de Fóton" da sua mão ou do Deck em Posição de Defesa e, além disso, você não pode Invocar por Invocação-Especial pelo resto deste turno, exceto monstros de LUZ. \r\nSeu oponente não pode declarar um ataque enquanto você controlar outro "Caça Delta de Fóton".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47060154,'Palhaço Místico','Nada pode parar o ataque enlouquecido desta poderosa criatura.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47060347,'Égide de Gaia',replace(replace('Ganhe 3000 PV. \r\nSe este card com a face para cima deixar o campo, o controlador deste card sofre 3000 de dano.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47060528,'Sakra Vendifúria',replace(replace('2 monstros de Nível 4	\r\nVocê pode desassociar 1 matéria deste card e, depois, escolha 1 monstro Psíquico de Nível/Classe 4 no seu Cemitério, exceto "Sakra Vendifúria"; Invoque-o por Invocação-Especial. \r\nSe um ou mais monstros forem Invocados por Invocação-Especial, enquanto este card estiver na sua Zona de Monstros (exceto durante a Etapa de Dano): você pode escolher 1 outro monstro com a face para cima no campo; o nome desse monstro se torna "Sakra Vendifúria" até a Fase Final. \r\nVocê só pode usar cada efeito de "Sakra Vendifúria" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Alterar nome do card','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47075569,'Camarartista Feiticeiro Pêndulo',replace(replace('Escala de Pêndulo = 2\r\n[ Efeito de Pêndulo ]\r\nSe um ou mais monstros "Camarartista" forem Invocados por Invocação-Pêndulo no seu campo: até o final deste turno, todos os monstros "Camarartista" que você controla atualmente ganham 1000 de ATK (mesmo que este card deixe o campo).\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe este card for Invocado por Invocação-Especial: você pode escolher até 2 cards que você controla; destrua-os e, se isso acontecer, adicione monstros "Camarartista" com nomes diferentes do seu Deck à sua mão, exceto "Camarartista Feiticeiro Pêndulo", igual ao número de cards destruídos. \r\nVocê só pode usar este efeito de "Camarartista Feiticeiro Pêndulo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47077318,'Leilaranja Silvestre',replace(replace('Quando este card que você controla for destruído por um card do seu oponente (seja em batalha ou por um efeito de card) e enviado para o seu Cemitério: você pode escavar o card do topo do seu Deck e, se ele for um monstro do Tipo Planta, envie-o para o Cemitério. \r\nCaso contrário, coloque-o no fundo do seu Deck. \r\nSe este card for escavado do Deck e enviado para o Cemitério por um efeito de card: todos os monstros do Tipo Planta que você controla atualmente ganham 300 de ATK e DEF.','\r',char(13)),'\n',char(10)),'Escave cards do seu Deck','Aumentar ATK/DEF','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47077697,'Urubonus, o Avatar da Malícia',replace(replace('Monstros que seu oponente controla perdem 300 de ATK/DEF. \r\nVocê só pode usar cada um dos seguintes efeitos de "Urubonus, o Avatar da Malícia" uma vez por turno. \r\nVocê pode oferecer como Tributo 1 monstro Réptil; Invoque este card por Invocação-Especial da sua mão. \r\nVocê pode oferecer 1 monstro como Tributo; até o final deste turno, todos os monstros que seu oponente controla atualmente perdem ATK/DEF igual ao ATK original do monstro oferecido como Tributo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47082621,'Suserano Regênese',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (do seu Cemitério) ao banir 2 monstros do seu Cemitério com 2500 de ATK ou DEF. \r\nVocê só pode Invocar "Suserano Regênese" por Invocação-Especial uma vez por turno desta forma. \r\nSe este card for Invocado por Invocação-Especial: você pode escolher cards no campo e/ou Cemitério do seu oponente, até o número dos seus monstros banidos com 2500 de ATK ou DEF; devolva-os para a mão. \r\nMonstros que seu oponente controla perdem 2500 de ATK apenas durante a Fase de Batalha.','\r',char(13)),'\n',char(10)),'','Retornar para a mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47084486,'Demônio da Vaidade',replace(replace('Não pode ser Invocado por Invocação-Especial. \r\nNenhum duelista pode Invocar monstros por Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47106439,'Visão Gishki',replace(replace('Se você Invocar por Invocação-Ritual exatamente 1 Monstro de Ritual de ÁGUA com um efeito de card que necesita a utilização de monstros, este card pode ser usado no lugar de todos os monstros necessários. \r\nVocê pode descartar este card; adicione 1 Monstro de Ritual "Gishki" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Adicione à sua mão um Monstro Ritual','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47111934,'Lombriga Yagan',replace(replace('Se o único monstro que você controla for "Lombriga Xex", você pode Invocar este card por Invocação-Especial do seu Cemitério com a face para baixo em Posição de Defesa. \r\nSe isso acontecer, remova-o de jogo quando ele for removido do campo. \r\nQuando este card for virado com a face para cima, selecione 1 monstro com a face para cima que seu oponente controla e devolva-o para a mão de seu dono.','\r',char(13)),'\n',char(10)),'Invocação Especial','Retornar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47120245,'Nobre Cavaleiro Borz',replace(replace('Este card é considerado um Monstro Normal enquanto estiver com a face para cima no campo. \r\nEnquanto estiver equipado com uma Magia de Equipamento "Armas Nobres", este card se torna um Monstro de Efeito com esses efeitos.\r\n● Este card se torna de TREVAS e seu Nível aumenta em 1.\r\n● Durante sua Fase Principal: você pode revelar 3 cards "Armas Nobres" do seu Deck, fazer com que seu oponente adicione 1 deles aleatoriamente à sua mão e envie os restantes para o Cemitério.	\r\nVocê só pode usar este efeito de "Nobre Cavaleiro Borz" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47121070,'Par Cristalino','Quando um monstro "Fera Cristalina" que você controla for destruído em batalha e enviado para o Cemitério: coloque 1 monstro "Fera Cristalina" do seu Deck com a face para cima na sua Zona de Magias & Armadilhas como uma Magia Contínua e, se isso acontecer, você não sofre dano de batalha pelo resto deste turno.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47126872,'Polícia do Espaço-Tempo',replace(replace('Quando este card for Invocado por Invocação-Especial: Escolha 1 card com a face para cima que seu oponente controla; bana o alvo. \r\nQuando este card deixar o campo: Baixe o card que foi banido por este efeito no lado do campo do oponente.','\r',char(13)),'\n',char(10)),'Banir','Baixar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47128571,'Presas Ocultas da Vingança',replace(replace('Nenhum duelista pode ativar cards ou efeitos em resposta à ativação deste card. \r\nQuando um monstro declarar um ataque: destrua 2 cards Baixados que você controla e, se isso acontecer, negue o ataque e, depois, se quaisquer Cards de Monstro foram destruídos por este efeito e enviados para o Cemitério, selecione 1 e destrua tantos monstros que seu oponente controla quanto possível com ATK igual ou menor que a DEF desse monstro e, depois, a fase se torna a Fase Final. \r\nVocê só pode ativar 1 "Presas Ocultas da Vingança" por turno.','\r',char(13)),'\n',char(10)),'Escolha 1 monstro','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47132793,'Blaze, o Governante Supremo de todos os Dragões',replace(replace('2 monstros de Nível 7	\r\nUma vez por turno: você pode desassociar 1 matéria deste card; destrua 2 cards (1 da sua mão ou do campo e 1 que seu oponente controla). \r\nVocê pode banir um total de 2 monstros de FOGO e/ou Dragão da sua mão e/ou do Cemitério; Invoque este card por Invocação-Especial do seu Cemitério, mas devolva-o para o Deck Adicional quando ele deixar o campo. \r\nVocê só pode usar este efeito de "Blaze, o Governante Supremo de todos os Dragões" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47149093,'Brilho Cristalino',replace(replace('Você só pode controlar 1 "Brilho Cristalino". \r\nCada monstro "Fera Cristalina" que você controla ganha ATK igual à sua DEF original. \r\nSe um ou mais cards "Fera Cristalina" forem colocados na sua Zona de Magias & Armadilhas, mesmo durante a Etapa de Dano: você pode enviar este card com a face para cima para o Cemitério; Invoque por Invocação-Especial 1 monstro "Fera Cristalina" da sua mão ou do Cemitério e, além disso, qualquer dano que você sofrer neste turno é diminuído pela metade.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47150851,'Guardião Grarl',replace(replace('Este card pode ser Invocado, por Invocação-Normal, Invocação-Virar, ou Invocação-Especial apenas quando "Machado Gravitacional - Grarl" estiver no seu Campo. \r\nSe este card for o único na sua mão, você pode Invocá-lo, por Invocação-Especial, da sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47158777,'Filhote Protetor do Soldado da Espada da Destruição',replace(replace('2 monstros	\r\nSe este card for Invocado por Invocação-Link: você pode enviar 1 card "Espada da Destruição" do seu Deck para o Cemitério e, depois, você pode Invocar por Invocação-Especial 1 monstro "Blader Notável" da sua mão. \r\nNo final da sua Fase de Batalha, se seu oponente não controlar nenhum monstro: você pode escolher 1 monstro "Blader Notável" que você controla que não declarou um ataque neste turno; cause dano ao seu oponente igual ao ATK desse monstro. \r\nVocê só pode usar cada efeito de "Filhote Protetor do Soldado da Espada da Destruição" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Invocar por Invocação Especial um monstro "Blader Notável"?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47163170,'Bearbrumm, o Furioso Enlouquecido da Tri-Brigada',replace(replace('2 monstros "Tri-Brigada"	\r\nVocê pode descartar 2 cards e, depois, escolha 1 dos seus monstros Besta, Besta-Guerreira ou Besta Alada banidos de Nível 4 ou menos; Invoque-o por Invocação-Especial. \r\nSe este card for enviado para o Cemitério: você pode adicionar 1 Magia/Armadilha "Tri-Brigada" do seu Deck à sua mão e, depois, coloque 1 card da sua mão no fundo do Deck e, além disso, você não pode Invocar por Invocação-Especial pelo resto deste turno, exceto monstros "Tri-Brigada". \r\nVocê só pode usar cada efeito de "Bearbrumm, o Furioso Enlouquecido da Tri-Brigada" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47171541,'Liberação Orcustrada',replace(replace('Ofereça como Tributo 2 monstros Máquina e, depois, escolha 1 monstro no seu Cemitério; Invoque-o por Invocação-Especial. \r\nSe seu oponente controlar um Monstro Link, em vez disso, você pode escolher 2 monstros. \r\nVocê só pode ativar 1 "Liberação Orcustrada" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47172959,'Yubel - O Amoroso Eterno Defensor',replace(replace('1 monstro "Yubel" + 1+ Monstros de Efeito no campo	\r\nSe este card for Invocado por Invocação-Fusão: você pode causar 500 de dano ao seu oponente para cada matéria usada. \r\nVocê só pode usar este efeito de "Yubel - O Amoroso Eterno Defensor" uma vez por turno. \r\nNão pode ser destruído em batalha ou por efeitos de card e, além disso, você não sofre dano de batalha das batalhas envolvendo este card. \r\nNo final da Etapa de Dano, se este card batalhou um monstro do oponente: cause dano ao seu oponente igual ao ATK desse monstro do oponente e, se isso acontecer, bana esse monstro.','\r',char(13)),'\n',char(10)),'Causar dano e banir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47185546,'Sinal do Inseto',replace(replace('Escolha 1 Monstro Xyz Inseto que você controla; Invoque por Invocação-Especial do seu Deck Adicional, 1 monstro Inseto que seja 2 Classes maior ou menor que esse monstro que você controla, usando-o como Matéria Xyz. \r\n(Esta Invocação-Especial é considerada uma Invocação-Xyz. Matérias Xyz associadas ao alvo também se tornam Matérias Xyz no monstro Invocado.) \r\nVocê só pode ativar 1 "Sinal do Inseto" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47195442,'Quarteto Instável',replace(replace('2+ monstros de Nível 4	\r\nNão é afetado por outros efeitos de cards. \r\nSe este card for Invocado por Invocação-Xyz e, além disso, uma vez por turno durante sua Fase de Apoio: associe os 3 cards do topo do seu Deck a este card como matéria e, depois, aplique o seguinte efeito de acordo com o número de monstros associados a este card.\r\n● 4 ou menos: Conceda o controle deste card ao seu oponente.\r\n● 5 ou mais: Sofra 400 de dano por cada matéria que este card tiver e, se isso acontecer, destrua todos os monstros que você controla.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47198668,'D/D/D Armagedom, o Rei do Fim',replace(replace('Escala de Pêndulo = 4\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno: você pode escolher 1 monstro "D/D" que você controla; ele ganha 800 de ATK até o final deste turno (mesmo que este card deixe o campo).\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nUma vez por turno, se um ou mais monstros que você controla forem destruídos em batalha ou por um efeito de card: você pode escolher 1 desses monstros; até o final deste turno, este card ganha ATK igual ao ATK original desse monstro. \r\nEste card não pode atacar diretamente seu oponente durante o turno em que este efeito for ativado. \r\nNão pode ser destruído por efeitos de Magia/Armadilha que não escolherem este card como alvo.','\r',char(13)),'\n',char(10)),'Aumentar ATK em 800','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47217354,'Corvo Mitológico','Uma vez por turno: você pode descartar qualquer número de cards e, se isso acontecer, até o final deste turno, este card ganha 1 Nível e 400 de ATK para cada card descartado.','Aumentar Nível e ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47219274,'Freki, as Presas Rúnikas',replace(replace('2 monstros "Rúnika(o)"	\r\nQuando um ataque for declarado envolvendo este card na Zona de Monstros Adicional: você pode banir os 2 cards do topo do Deck do seu oponente. \r\nNenhum duelista sofre qualquer dano de batalha de ataques envolvendo este card. \r\nSe este card no campo for destruído em batalha ou por um efeito de card: você pode escolher 1 Magia Rápida "Rúnika(o)" no seu Cemitério; adicione-a à sua mão. \r\nVocê só pode usar este efeito de "Freki, as Presas Rúnikas" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47222536,'Círculo Mágico Negro',replace(replace('Quando este card for ativado: olhe os 3 cards do topo do seu Deck e, depois, você pode revelar 1 deles que seja "Mago Negro" ou uma Magia/Armadilha que mencione "Mago Negro" e adicioná-lo à sua mão e, além disso, coloque os cards restantes no topo do seu Deck em qualquer ordem. \r\nSe "Mago Negro" for Invocado por Invocação-Normal ou Especial no seu campo (exceto durante a Etapa de Dano): você pode escolher 1 card que seu oponente controla; bana-o. \r\nVocê só pode usar cada efeito de "Círculo Mágico Negro" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar 1 card à sua mão?','Banir 1 card que seu oponente controla','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47222537,'Círculo Mágico Negro',replace(replace('Quando este card for ativado: olhe os 3 cards do topo do seu Deck e, depois, você pode revelar 1 deles que seja "Mago Negro" ou uma Magia/Armadilha que mencione "Mago Negro" e adicioná-lo à sua mão e, além disso, coloque os cards restantes no topo do seu Deck em qualquer ordem. \r\nSe "Mago Negro" for Invocado por Invocação-Normal ou Especial no seu campo (exceto durante a Etapa de Dano): você pode escolher 1 card que seu oponente controla; bana-o. \r\nVocê só pode usar cada efeito de "Círculo Mágico Negro" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar 1 card à sua mão?','Banir 1 card que seu oponente controla','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47226949,'Leotron','Um monstro eletrônico territorial que protege seu próprio domínio.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47228077,'Vylon Pentachloro',replace(replace('Uma vez por turno, você pode: Escolher 1 monstro "Vylon" com a face para cima que você controla; equipe este card ao alvo, OU: Desequipe este card e Invoque-o por Invocação-Especial com a face para cima em Posição de Ataque. \r\nEnquanto estiver equipado por este efeito, se o monstro equipado destruir um monstro do oponente em batalha: Você pode escolher 1 card que seu oponente controla; destrua o alvo. \r\n(Um monstro só pode ser equipado com 1 Monstro União por vez. Se o monstro equipado seria destruído, em vez disso, destrua este card.)','\r',char(13)),'\n',char(10)),'Tornar-se um Card de Equipamento','Invocação Especial','Destrua 1 card que seu oponente controla','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47233801,'Síndroma da Cobra das Trevas',replace(replace('Inflija dano aos seus e aos Life Points do seu adversário durante cada uma das suas Standby Phases. \r\nO primeiro dano começa nos 200 pontos e duplica em cada uma das seguintes Standby Phases.','\r',char(13)),'\n',char(10)),'Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47247413,'Retorno','Quando seu oponente adicionar um ou mais cards do Cemitério para a mão dele: Ele deve embaralhar 1 desses cards no Deck dele.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47247792,'Guerreiro Condutor Plasma Magnum',replace(replace('2 monstros Rocha de TERRA	\r\nMonstros com a face para cima no campo se tornam de TERRA. \r\nVocê só pode usar cada um dos seguintes efeitos de "Guerreiro Condutor Plasma Magnum" uma vez por turno. \r\nSe este card for Invocado por Invocação-Fusão: você pode adicionar 1 Magia Normal, Rápida ou de Campo "Ímã" do seu Deck à sua mão. \r\nVocê pode enviar 1 monstro "Guerreiro Ímã" de Nível 8 do seu Deck para o Cemitério; imediatamente depois que este efeito resolver, Invoque por Invocação-Normal 1 monstro "Guerreiro Ímã" de Nível 4 ou menos.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Invocar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47264717,'Estrela Cadente','Se um monstro "Poeira Estelar" estiver no campo: escolha 1 card no campo; destrua o alvo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47274077,'Força Neos',replace(replace('Só pode ser equipado a "Neos, o HERÓI do Elemento". \r\nEle ganha 800 de ATK. \r\nQuando ele destruir um monstro em batalha e enviá-lo para o Cemitério: Cause dano ao seu oponente igual ao ATK original do monstro destruído no Cemitério. \r\nDurante a Fase Final: Embaralhe este card no Deck.','\r',char(13)),'\n',char(10)),'Causar dano','Retornar ao Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47292920,'Dado Dimensional','Se você controlar um card com um efeito que requer um lance de dados: você pode oferecer 1 monstro como Tributo; Invoque por Invocação-Especial da sua mão ou do Deck 1 monstro com um efeito que requer um lance de dados.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47295267,'Zona Cibernética',replace(replace('Escolha 1 Monstro de Fusão do Tipo Máquina com a face para cima que você controla e o remova de jogo até a Fase Final deste turno. \r\nQuando esse monstro for devolvido para o campo, dobre o seu ATK. \r\nDurante sua próxima Fase de Apoio, destrua-o.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47297616,'Dragão da Luz e das Trevas',replace(replace('Não pode ser Invocado por Invocação-Especial. \r\nEnquanto estiver com a face para cima no campo, este card também é do Atributo TREVAS. \r\nUma vez por Corrente, quando um Card de Magia/Armadilha, ou efeito de monstro, for ativado (Efeito Rápido): este card perde exatamente 500 de ATK/DEF e essa ativação é negada. \r\nQuando este card for destruído e enviado para o Cemitério: escolha 1 monstro no seu Cemitério (se possível); destrua todos os cards que você controla e, além disso, Invoque esse monstro por Invocação-Especial (se houver).','\r',char(13)),'\n',char(10)),'Não pode ser Invocado por Invocação Especial','Também é considerado TREVAS','Negue a ativação do efeito','Reduzir ATK/DEF em 500','Invocação Especial','','','','','','','','','','','');
INSERT INTO texts VALUES(47319141,'Águia Alada','Esta criatura voadora nunca erra um alvo pretendido.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47325505,'Escavar Fóssil','Adicione 1 monstro Dinossauro de Nível 6 ou menos do seu Deck à sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47325506,'Escavar Fóssil','Adicione 1 monstro Dinossauro de Nível 6 ou menos do seu Deck à sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47330808,'Hapi, a Orientação de Horus',replace(replace('Se você controlar "Sarcófago do Rei", você pode Invocar este card por Invocação-Especial (do seu Cemitério). \r\nVocê só pode Invocar "Hapi, a Orientação de Horus" por Invocação-Especial uma vez por turno desta forma. \r\nSe um ou mais outros cards que você controla deixarem o campo por um efeito de card do oponente, enquanto este card estiver na sua Zona de Monstros (exceto durante a Etapa de Dano): você pode escolher 2 cards que estiverem banidos e/ou nos Cemitérios; adicione os dois à mão ou embaralhe os dois no Deck. \r\nVocê só pode usar este efeito de "Hapi, a Orientação de Horus" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Adicionar à mão','Retornar ao Deck','','','','','','','','','','','','');
INSERT INTO texts VALUES(47346782,'Centrosapo',replace(replace('Não pode ser usado como matéria para uma Invocação-Fusão, Sincro, Xyz ou Link. \r\nSe este card for Invocado por Invocação-Normal ou Virar: coloque-o em Posição de Defesa. \r\nUma vez por turno: você pode escolher 1 monstro na Zona de Monstros Principal do seu oponente; conceda ao seu oponente o controle deste card em Posição de Defesa, movendo-o para uma zona dele adjacente ao alvo e, depois, se seu oponente controlar exatamente 2 "Centrosapo" na Zona de Monstros Principal, ganhe o controle de todos os monstros entre esses 2 cards.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47346845,'Homem-Bateria AAA','Quando este card for Invocado por Invocação-Normal ou virado com a face para cima, você pode Invocar por Invocação-Especial 1 "Homem-Bateria AAA" da sua mão ou Cemitério.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47349116,'Mago Estrela do Tempo',replace(replace('2 Monstros Pêndulo "Mago" de Nível 4	\r\nPrimeiro deve ser Invocado por Invocação-Xyz com as Matérias Xyz acima. \r\nUma vez por turno: você pode desassociar 1 Matéria Xyz deste card; adicione à sua mão, 1 monstro de TREVAS do Tipo Mago do seu Deck, Cemitério ou com a face para cima no seu Deck Adicional. \r\nUma vez por turno, se um ou mais Cards de Monstro Pêndulo nas suas Zonas de Monstro ou Zonas de Pêndulo seriam destruídos em batalha ou por um efeito de card, em vez disso, você pode enviar 1 monstro do Tipo Mago do seu Deck para o Cemitério.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Usar o efeito de "Mago Estrela do Tempo" em vez de ser destruído?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47349310,'Raistreleste',replace(replace('Este card pode atacar diretamente seu oponente. \r\nNo final da Fase de Batalha, se este card atacou diretamente: bana este card até sua próxima Fase de Apoio.','\r',char(13)),'\n',char(10)),'Banir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47355498,'Necro-Vale',replace(replace('Todos os monstros "do Coveiro" ganham 500 de ATK/DEF. \r\nOs cards no Cemitério não podem ser banidos. \r\nNegue qualquer efeito de card que moveria um card do Cemitério para um lugar diferente. \r\nNegue qualquer efeito de card que mude Tipos ou Atributos no Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47360060,'Selo Hierático da Reflexão','Quando um Card de Magia/Armadilha ou efeito de monstro for ativado: ofereça como Tributo 1 monstro "Hierático"; negue a ativação e, se isso acontecer, destrua-o.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47363932,'Wivern de Restolhos',replace(replace('2 monstros, incluindo um monstro "Restolhos"	\r\nVocê pode escolher 1 monstro "Restolhos" no seu Cemitério; Invoque-o por Invocação-Especial e, depois, destrua 1 card que você controla. \r\nSe outro monstro "Restolhos" com a face para cima for destruído por um efeito de card, enquanto você controlar este monstro (exceto durante a Etapa de Dano): você pode Invocar por Invocação-Especial 1 monstro "Restolhos" do seu Deck e, depois, destrua 1 card no campo. \r\nVocê só pode usar cada efeito de "Wivern de Restolhos" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47372349,'Macaco Acrobata','Um macaco autónomo do tipo robot que foi desenvolvido com tecnologia de ponto. Move-se muito acrobaticamente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47387961,'Número 8: Rei Heráldico Herança Genética',replace(replace('2 monstros "Besta Heráldica" de Nível 4	\r\nUma vez por turno: você pode escolher 1 Monstro Xyz com a face para cima que seu oponente controla; o nome e o ATK originais deste card se tornam o nome original e o ATK atual desse monstro, e além disso, substitua este efeito pelo efeito original desse monstro e, depois, o ATK desse monstro se torna 0 e, além disso, seus efeitos são negados. \r\nEste efeito se aplica até a Fase Final.','\r',char(13)),'\n',char(10)),'Obter o efeito','Encerrar o efeito copiado','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47393199,'Cataclismo Dragão-Guarda',replace(replace('Ofereça como Tributo 1 monstro Dragão e, depois, escolha 2 cards no campo; destrua-os. \r\nVocê só pode ativar 1 "Cataclismo Dragão-Guarda" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47395382,'Ragin Mitológico',replace(replace('1 Regulador "Mitológico(a)" + 1+ monstros não-Reguladores	\r\nQuando este card for Invocado por Invocação-Sincro: você pode comprar até ter 2 cards na sua mão.','\r',char(13)),'\n',char(10)),'Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47404795,'Ator do Abismo - Superprodutor',replace(replace('2 monstros, incluindo um monstro Demônio	\r\nDurante a Fase Principal (Efeito Rápido): você pode escolher 1 card com a face para cima que você controla; destrua-o e, depois, você pode aplicar 1 desses efeitos.\r\n● Coloque 1 "Palco do Abismo - Teatro Fantástico" do seu Deck com a face para cima na sua Zona do Campo.\r\n● Coloque 1 Monstro Pêndulo "Ator do Abismo" do seu Deck na sua Zona de Pêndulo.	\r\nVocê só pode usar este efeito de "Ator do Abismo - Superprodutor" uma vez por turno.','\r',char(13)),'\n',char(10)),'Colocar um card do seu Deck no campo?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47408488,'Árvore Cristalina',replace(replace('Sempre que um ou mais monstros "Fera Cristalina" forem colocados na Zona de Magias & Armadilhas de qualquer duelista, coloque 1 Marcador Cristalino neste card. \r\nVocê pode enviar este card para o Cemitério; pegue um número de monstros "Fera Cristalina" do seu Deck igual ao número de Marcadores Cristalinos que estavam neste card e coloque-os com a face para cima na sua Zona de Magias & Armadilhas como Magias Contínuas.','\r',char(13)),'\n',char(10)),'Colocar 1 Marcador de Cristal','Coloque uma Fera Cristalina na Zona de Magia/Armadilha','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47415292,'Dragão Negro como Azeviche',replace(replace('Uma vez por turno, durante a sua Main Phase, você pode equipar este card a "Lâmina Sombria" como um Card de Magia de Equipamento, OU separar o Equipamento e Invocar, por Invocação-Especial, este card em Posição de Ataque com a face para cima. \r\nQuando este card é equipado pelo efeito deste card, aumente o ATK/DEF do monstro equipado em 400 pontos, e quando ataca com um ATK superior ao DEF dum monstro em Posição de Defesa, inflija a diferença aos Life Points do seu adversário como dano de batalha. \r\n(1 monstro pode ser equipado apenas por 1 Monstro de Union de cada vez. Se o monstro equipado com este card é destruído como resultado de um combate, em vez disso destrúa este card.)','\r',char(13)),'\n',char(10)),'Equipar','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47421985,'Hidrogenex',replace(replace('"Controlador Genex" + 1 ou mais monstros de ÁGUA não-Reguladores	\r\nQuando este card destruir um monstro do oponente em batalha e enviá-lo ao Cemitério, ganhe PV igual ao ATK do monstro destruído.','\r',char(13)),'\n',char(10)),'Ganhar PV','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47425162,'ÁS-Resgate Atacante Rápido',replace(replace('Você pode embaralhar no Deck 1 outro card "ÁS-Resgate" da sua mão ou do campo com a face para cima; Invoque este card por Invocação-Especial da sua mão. \r\nVocê pode oferecer este card como Tributo; adicione 1 monstro "ÁS-Resgate" do seu Deck à sua mão e, depois, você pode Invocá-lo por Invocação-Especial se somente seu oponente controlar um monstro e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto monstros de FOGO. \r\nVocê só pode usar cada efeito de "ÁS-Resgate Atacante Rápido" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Efeito de busca','Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47432275,'Kuribon','Durante o cálculo de dano, se este card for atacado por um monstro do seu oponente: você pode ativar este efeito; você não sofre dano de batalha dessa batalha, seu oponente ganha PV igual ao ATK do monstro atacante e, além disso, você devolve este card para a mão.','O dano se torna 0','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47435107,'Grito Primário',replace(replace('Este card é usado para a Invocação-Ritual de "Vennu, o Pássaro Brilhante da Divindade". \r\nVocê também deve oferecer como Tributo monstros da sua mão ou do campo cuja soma dos Níveis seja igual a 8 ou mais. \r\nDurante sua Fase Final: você pode banir este card do seu Cemitério e, depois, escolher 1 Monstro de Ritual no seu Cemitério que foi enviado do campo para lá neste turno; Invoque-o por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Invocação Especial','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47436247,'Dojo de Shien',replace(replace('Sempre que um ou mais monstros "Seis Samurai" forem Invocados por Invocação-Normal ou Especial, coloque 1 Marcador de Bushido neste card. \r\nVocê pode enviar este card para o Cemitério; Invoque por Invocação-Especial 1 Monstro de Efeito "Seis Samurai" ou "Shien" do seu Deck Principal, cujo Nível seja menor ou igual que o número de Marcadores de Bushido neste card.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47439573,'Jogar Fora Impiedoso','Quando um ou mais cards com a face para cima no campo e/ou no Cemitério forem adicionados à mão do seu oponente por um efeito: olhe a mão dele e, além disso, bana o(s) card(s) adicionado(s) e todos os cards com o mesmo nome, se houver.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47453433,'Regresso ao Início','Descarte 1 card e, depois, escolha 1 monstro no campo; coloque o alvo no topo do Deck.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47457347,'Invocação Ômega','Escolha qualquer número dos seus monstros "Invokado(a)" banidos com nomes diferentes; Invoque-os por Invocação-Especial em Posição de Defesa.','Continuar selecionando monstros para Invocar por Invocação Especial?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47459126,'Mago Regulado',replace(replace('Este card é considerado como um Monstro Normal enquanto estiver com a face para cima no campo ou no Cemitério. \r\nEnquanto este card estiver com a face para cima no campo, você pode Invocá-lo por Invocação-Normal para fazer com que ele seja considerado como um Monstro de Efeito com este efeito:\r\n● Este card é considerado como um monstro Regulador.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47471667,'D-Explosão',replace(replace('Você só pode ativar 1 "D-Explosão" uma vez por turno.\r\nEscolha 1 Magia com a face para cima que você controla; destrua-o, e se o fizer, compre 1 card, então se você controla um monstro "HERÓI do Destino", você pode Invocar por Invocação-Especial 1 monstro "HERÓI do Destino" da sua mão, Cemitério, ou banimento.\r\nSe um monstro equipado com uma Magia de Equipamento ou "HERÓI do Destino - Dogma", atacar, no fim da Etapa de Dano: você pode banir este card do seu Cemitério; aquele monstro pode realizar um segundo ataque em seguida.','\r',char(13)),'\n',char(10)),'Comprar','Fazer outro ataque','Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47474172,'Baioneteiro, o Tambor Funesto','Uma vez por turno: você pode escolher 1 monstro com a face para cima que seu oponente controla; ele perde 1000 de ATK para cada monstro que seu oponente controla.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47475363,'Força do Espelho do Afogamento','Quando um monstro do oponente declarar um ataque direto: embaralhe no Deck todos os monstros em Posição de Ataque do seu oponente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47480070,'Paladino Amazoness','Ganha 100 de ATK para cada monstro "Amazoness" que você controla.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47482043,'Renascimento do Mecanismo Antigo',replace(replace('Uma vez por turno, se você não controlar nenhum monstro: você pode escolher 1 monstro "Mecanismo Antigo" no seu Cemitério; Invoque-o por Invocação-Especial e, se isso acontecer, ele ganha 200 de ATK (mesmo que este card deixe o campo). \r\nVocê só pode controlar 1 "Renascimento do Mecanismo Antigo".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47484352,'Dragão do Multiverso','Este dragão misterioso conquistou muitas dimensões, mas só pode ser visto pelo campeão do tempo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47504322,'Caverguerra Wento',replace(replace('Se um monstro Guerreiro de TERRA seu batalhar um monstro do oponente, durante o cálculo de dano (Efeito Rápido): você pode pagar 800 PV; até o final deste turno, seu monstro que está batalhando ganha 800 de ATK. \r\nSe este card for enviado da sua Zona de Monstros para o seu Cemitério por um efeito de card do oponente: você pode Invocar por Invocação-Especial 1 monstro "Caverguerra" de Nível 5 ou mais da sua mão ou do Deck. \r\nVocê só pode usar cada efeito de "Caverguerra Wento" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47506081,'Grenossauro',replace(replace('2 monstros de Nível 3	\r\nQuando este card destruir um monstro do oponente em batalha e o enviar para o Cemitério: você pode desassociar 1 Matéria Xyz deste card; cause 1000 de dano ao seu oponente.','\r',char(13)),'\n',char(10)),'Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47507260,'Homem das Espadas Místicas LV2',replace(replace('Se este card atacar um monstro em Posição de Defesa com a face para baixo, destrúa o monstro com o efeito deste card, sem aplicar o cálculo de dano. \r\nDurante a End Phase do turno em que este card destrúa um monstro como resultado de um combate, envie este card para o Cemitério para Invocar, por Invocação-Especial, "Homem das Espadas Místicas LV4" da sua mão ou do seu Deck.','\r',char(13)),'\n',char(10)),'Destruir','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47529357,'Corpo de Névoa','O monstro equipado não pode ser destruído em batalha.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47556396,'Speleogeist, o Behemoth Subterror',replace(replace('VIRE: Você pode escolher 1 monstro no campo; coloque-o com a face para cima em Posição de Ataque se ele estiver em Posição de Defesa e, além disso, mude o ATK dele para 0. \r\nVocê só pode usar este efeito de "Speleogeist, o Behemoth Subterror" uma vez por turno.\r\nQuando um monstro com a face para cima que você controla for virado com a face para baixo, se você não controlar nenhum monstro com a face para cima: você pode Invocar este card por Invocação-Especial da sua mão em Posição de Defesa. \r\nUma vez por turno: você pode colocar este card com a face para baixo em Posição de Defesa.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47558785,'Peru Tenro',replace(replace('Escala de Pêndulo = 7\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno: você pode lançar um dado de seis faces. Até o final deste turno, reduza a Escala de Pêndulo deste card por esse número (mín. 1).\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nO sabor da vitória vai dominar você.','\r',char(13)),'\n',char(10)),'Reduzir Escala de Pêndulo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47579719,'Constelar Híades',replace(replace('2 monstros de LUZ de Nível 3	\r\nUma vez por turno: você pode desassociar 1 Matéria Xyz deste card; coloque todos os monstros que seu oponente controla com a face para cima em Posição de Defesa.','\r',char(13)),'\n',char(10)),'Mudar para Posição de Defesa com a face para cima','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47594192,'Trinca','Se você controlar 3 ou mais monstros com o mesmo nome, exceto Fichas: escolha 3 cards que seu oponente controla; destrua os alvos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47594939,'E a Banda Continua a Tocar',replace(replace('Nenhum duelista pode Invocar por Invocação-Especial monstros com o mesmo Nível que aqueles que ele controla. \r\nNenhum duelista pode Invocar por Invocação-Especial monstros com a mesma Classe que aqueles que ele controla.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47596607,'Arranha-Céu 2 - Cidade de Heróis','Uma vez por turno, durante sua Fase Principal, se você controlar este card: você pode escolher 1 monstro "HERÓI do Elemento" no seu Cemitério que foi destruído em batalha e enviado para lá; Invoque o alvo por Invocação-Especial.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47598941,'Lise Amórfaga',replace(replace('Todos os monstros no campo, exceto monstros "Amórfago", perdem 100 de ATK e DEF para cada card "Amórfago(a)" no campo. \r\nSe um ou mais cards nas suas Zonas de Pêndulo forem destruídos (exceto durante a Etapa de Dano): você pode colocar 1 Monstro Pêndulo "Amórfago" do seu Deck na sua Zona de Pêndulo. \r\nVocê só pode usar este efeito de "Lise Amórfaga" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar, mas não resolver o efeito','Ativar e aplicar o segundo efeito','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47606319,'Gigantes',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro deve ser Invocado por Invocação-Especial (da sua mão) ao banir 1 monstro de TERRA do seu Cemitério. \r\nSe este card for destruído em batalha e enviado para o Cemitério: destrua todas as Magias e Armadilhas no campo.','\r',char(13)),'\n',char(10)),'Destrua todos os Cards de Magia/Armadilha','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47611119,'Dama Cavaleiro-Gema Lápis-Lazúli',replace(replace('"Cavaleiro-Gema Lápis" + 1 monstro "Cavaleiro-Gema"	\r\nPrimeiro deve ser Invocado por Invocação-Fusão com as Matérias de Fusão acima. \r\nVocê só pode Invocar um ou mais "Dama Cavaleiro-Gema Lápis-Lazúli" por Invocação-Especial uma vez por turno. \r\nUma vez por turno: você pode enviar 1 monstro "Cavaleiro-Gema" do seu Deck/Deck Adicional para o Cemitério e, se isso acontecer, cause 500 de dano ao seu oponente para cada monstro Invocado por Invocação-Especial no campo.','\r',char(13)),'\n',char(10)),'Dano aos Pontos de Vida','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47643326,'Coelho Lunar Omajinai',replace(replace('Um visitante misterioso que desceu dos céus. Ele converte a dor em sinais e os envia para o espaço, mas seu propósito ainda é desconhecido.\r\nDor que me assola, vá embora.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47647354,'Rex, a Montaria de Peluguel',replace(replace('Você pode revelar este card na sua mão; Invoque por Invocação-Especial 1 monstro "de Peluguel" da sua mão, exceto "Rex, a Montaria de Peluguel" e, depois, Invoque este card por Invocação-Especial. \r\nVocê só pode usar este efeito de "Rex, a Montaria de Peluguel" uma vez por turno. \r\nSe um ou mais cards forem adicionados do Deck à mão do seu oponente, exceto por um efeito de card "de Peluguel", e você controlar outro monstro "de Peluguel" (exceto durante a Etapa de Dano): você pode comprar 1 card.','\r',char(13)),'\n',char(10)),'Invocação Especial','Comprar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47658964,'Muralha de Fogo Ardente','Bana qualquer número de monstros "Laval" do seu Cemitério; Invoque por Invocação-Especial um número igual de "Fichas de Laval" (Tipo Piro/FOGO/Nível 1/ATK 0/DEF 0) em Posição de Defesa.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47658965,'Ficha de Laval','Invocado por Especial com o efeito "Muralha de Fogo Ardente".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47660516,'Magia de Aumento de Classe Força de Barian','Escolha 1 Monstro Xyz com a face para cima que você controla; Invoque por Invocação-Especial do seu Deck Adicional, 1 monstro "Número C" ou "CXyz" com o mesmo Tipo que o desse monstro que você controla, mas 1 Classe maior, usando-o como matéria (isso é considerado uma Invocação-Xyz, transfira as matérias dele para o monstro Invocado) e, depois, se possível, desassocie 1 Matéria Xyz de um monstro que seu oponente controla e associe-a ao monstro Invocado.','Escolha a(s) Matéria(s) a transferir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47664723,'Senhor Obscuro Edeh Arae',replace(replace('Se este card for Invocado por Invocação-Especial do Cemitério, ele ganha este efeito.\r\n● Se este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47674738,'Ressurgido Adamancipador - Leonita',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nDurante sua Fase Principal: você pode escavar os 5 cards do topo do seu Deck e, se isso acontecer, você pode adicionar 1 card "Adamancipador" escavado à sua mão e, além disso, coloque o resto no fundo do seu Deck em qualquer ordem. \r\nDurante o turno do seu oponente, se um monstro de FOGO estiver no seu Cemitério (Efeito Rápido): você pode escolher 1 monstro Rocha no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Ressurgido Adamancipador - Leonita" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Escolher 1 card para adicionar à mão?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47679935,'Derretimento Mágico',replace(replace('Quando este card for ativado: você pode adicionar 1 "Aleister, Aquele que Invoka" do seu Deck à sua mão. \r\nA ativação dos seus cards e efeitos que incluem um efeito que Invoca um Monstro de Fusão por Invocação-Fusão não podem ser negados e, além disso, os cards e efeitos do seu oponente não podem ser ativados quando um monstro é Invocado por Invocação-Fusão desta forma. \r\nVocê só pode ativar 1 "Derretimento Mágico" por turno.','\r',char(13)),'\n',char(10)),'Adicionar "Aleister, Aquele que Invoka" do seu Deck à sua mão?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47687766,'Engrenagibroca','Quando este card for Invocado por Invocação-Normal: você pode adicionar 1 monstro de TERRA do Tipo Máquina de Nível 4 do seu Deck à sua mão, exceto "Engrenagibroca" e, além disso, pelo resto deste turno, você não pode declarar ataques, nem Invocar monstros por Invocação-Especial, exceto monstros do Tipo Máquina.','Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47693640,'Tigre Zumbi',replace(replace('Uma vez por turno, você pode: escolher 1 "Comandante Decaído" que você controla; equipe este card no alvo, OU: desequipe este card e Invoque-o por Invocação-Especial em Posição de Ataque. \r\nEnquanto estiver equipado por este efeito, o monstro equipado ganha 500 de ATK/DEF. \r\nSe o monstro equipado destruir um monstro do oponente em batalha: descarte 1 card aleatório da mão dele. \r\n(Um monstro só pode ser equipado por 1 monstro União por vez. Se o monstro equipado seria destruído em batalha, em vez disso, destrua este card.)','\r',char(13)),'\n',char(10)),'Equipar','Invocação Especial','Descartar da mão','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47695416,'Vela do Destino','Decidirá o destino de um oponente quando a chama da vela em seus dedos se extinguir.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47699948,'Dilema Sincro',replace(replace('Você pode ativar 1 dos seguintes efeitos;\r\n● Envie para o Cemitério 1 monstro "Sincron" da sua mão ou do campo com a face para cima; Invoque por Invocação-Especial 1 monstro da sua mão.\r\n● Escolha 1 outro card que você controla; destrua-o e, se isso acontecer, Invoque por Invocação-Especial 1 monstro "Sincron" com um nome original diferente da sua mão ou do Cemitério.	\r\nVocê só pode usar este efeito de "Dilema Sincro" uma vez por turno.','\r',char(13)),'\n',char(10)),'Enviar para o Cemitério e Invocar por Invocação Especial','Destruir e Invocar por Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47705572,'Loba Luzlunar',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nVocê não pode Invocar por Invocação-Pêndulo, exceto monstros "Luzlunar". \r\nEste efeito não pode ser negado. \r\nUma vez por turno: você pode Invocar por Invocação-Fusão 1 Monstro de Fusão "Luzlunar" do seu Deck Adicional, ao banir suas matérias do seu campo ou Cemitério.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe um monstro "Luzlunar" que você controla atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47710198,'Espadalma Soberano Sinistro - Qixing Longyuan',replace(replace('1 Regulador + 1+ monstros Wyrm não-Reguladores	\r\nSe você Invocar outro monstro Wyrm por Invocação-Sincro, enquanto este monstro estiver no campo: você pode comprar 1 card. \r\nSe seu oponente Invocar um ou mais monstros por Invocação-Especial (exceto durante a Etapa de Dano): você pode banir 1 desses monstros e, se isso acontecer, cause 1200 de dano ao seu oponente. \r\nQuando seu oponente ativar um Card de Magia/Armadilha ou seus efeitos (Efeito Rápido): você pode banir esse card e, se isso acontecer, cause 1200 de dano ao seu oponente. \r\nVocê só pode usar cada efeito de "Espadalma Soberano Sinistro - Qixing Longyuan" uma vez por turno.','\r',char(13)),'\n',char(10)),'Comprar','Banir o(s) monstro(s) Invocado(s) por Invocação Especial','Banir o card ativado','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47728740,'Alich, Malebranche do Abismo Ardente',replace(replace('Se você controlar um monstro que não seja um monstro "Abismo Ardente", destrua este card. \r\nVocê só pode usar 1 desses efeitos de "Alich, Malebranche do Abismo Ardente" por turno e apenas uma vez por turno.\r\n● Se você não controlar Cards de Magia/Armadilha: você pode Invocar este card por Invocação-Especial da sua mão.\r\n● Se este card for enviado para o Cemitério: você pode escolher 1 monstro com a face para cima no campo; negue os efeitos dele até o final deste turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Negar o efeito','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47731128,'Mei-Kou, Mestre das Barreiras','Você pode oferecer este card como Tributo e, depois, escolha 1 Magia/Armadilha Contínua com a face para cima no campo; destrua o alvo.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47736165,'Cristron Eleskeletus',replace(replace('1 Regulador + 1+ não-Reguladores	\r\nTodos os monstros que seu oponente controla perdem 500 de ATK/DEF. \r\nVocê só pode usar cada um dos seguintes efeitos de "Cristron Eleskeletus" uma vez por turno. \r\nSe este card for Invocado por Invocação-Sincro: você pode adicionar 1 card "Cristron" do seu Cemitério ou banimento à sua mão. \r\nSe este card Invocado por Invocação-Sincro for destruído em batalha ou por um efeito de card: você pode Invocar por Invocação-Especial 1 monstro "Cristron" do seu Cemitério ou banimento.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47737087,'Disparador Destrutivo, o HERÓI do Elemento',replace(replace('"Clayman, o HERÓI do Elemento" + "Burstinatrix, o HERÓI do Elemento"	\r\nDeve ser Invocado por Invocação-Fusão. \r\nEste card pode atacar diretamente enquanto estiver em Posição de Defesa. \r\nSe o fizer, aplique seu ATK no cálculo de dano e seu ATK é diminuído pela metade apenas durante o cálculo de dano.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47741109,'Boca-de-leão Silvestre',replace(replace('Se este card for enviado do campo ou da mão para o Cemitério: você pode escavar o card do topo do seu Deck e, se ele for um monstro do Tipo Planta, envie-o para o Cemitério. \r\nCaso contrário, coloque-o no fundo do seu Deck. \r\nSe este card for escavado do Deck e enviado para o Cemitério por um efeito de card: você pode escavar o card do topo do seu Deck e, se for um monstro do Tipo Planta, enviá-lo para o Cemitério. \r\nCaso contrário, coloque-o no fundo do seu Deck.','\r',char(13)),'\n',char(10)),'Escave cards do seu Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47754278,'Dragão Infernal',replace(replace('Uma vez por turno, durante a Fase Final, se este card atacou neste turno: destrua este card. \r\nQuando este card no campo for destruído e enviado para o Cemitério: você pode oferecer 1 monstro como Tributo; Invoque este card por Invocação-Especial do Cemitério.','\r',char(13)),'\n',char(10)),'Destruir','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47759571,'Cabicavaleira Earlie',replace(replace('2 Monstros de Efeito	\r\nQuando um monstro para o qual este card apontar ativar seu efeito (exceto durante a Etapa de Dano) (Efeito Rápido): você pode escolher 1 Monstro de Efeito que seu oponente controla; até o final deste turno, mude o ATK dele para 0 e, além disso, negue seus efeitos. \r\nDurante a Fase Final, se este card estiver no Cemitério porque foi destruído em batalha ou por um efeito de card e enviado para lá neste turno: você pode Invocar este card por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Cabicavaleira Earlie" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47766694,'Tornado Selvagem',replace(replace('Escolha 1 card com a face para cima na Zona de Magias & Armadilhas; destrua esse card com a face para cima e, depois, seu controlador pode Baixar 1 Magia/Armadilha da mão dele. \r\nSe este card Baixado for destruído e enviado para o Cemitério: escolha 1 card com a face para cima no campo; destrua o alvo.','\r',char(13)),'\n',char(10)),'Baixar um Card de Magia ou Armadilha?','Destrua 1 card com a face para cima','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47778083,'Bloco do Templo de Ossos',replace(replace('Descarte 1 card. \r\nInvoque por Invocação-Especial 1 monstro de Nível 4 ou menos do Cemitério do seu oponente no seu lado do campo, e seu oponente Invoca por Invocação-Especial 1 monstro de Nível 4 ou menos do seu Cemitério no lado do campo do seu oponente. \r\nEsses monstros são destruídos durante a Fase Final do próximo turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47795344,'Hortênsia de Naturia','Durante o seu turno, se o efeito de um monstro "Naturia" foi ativado no seu campo, você pode Invocar este card por Invocação-Especial (da sua mão).','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47805931,'Número 20: Giga-Brilhante',replace(replace('2 monstros de Nível 3	\r\nUma vez por turno: você pode desassociar 1 matéria deste card; todos os monstros que você controla atualmente ganham 300 de ATK.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47810543,'Mágico Mosquete - Coroa Tortuosa',replace(replace('Você só pode controlar 1 "Mágico Mosquete - Coroa Tortuosa". \r\nDurante a Fase Principal: você pode Invocar por Invocação-Especial 1 monstro "Mágico(a) Mosquete" da sua mão e, se isso acontecer, se a Zona de Monstros Principal do seu oponente na coluna atual desse monstro não estiver usada, essa zona não pode ser usada até o final deste turno (mesmo que este card deixe o campo). \r\nVocê só pode usar este efeito de "Mágico Mosquete - Coroa Tortuosa" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47819246,'Espada Mech Super Quantal - Magnassassina',replace(replace('Escolha 1 Monstro Xyz "Super Quant" que você controla; equipe este card nele. \r\nEle ganha ATK igual à sua Classe x 100 e, além disso, se ele atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente. \r\nDurante sua Fase de Batalha: você pode enviar este Card de Equipamento para o Cemitério; o monstro que estava equipado com este card pode realizar 3 ataques durante cada Fase de Batalha neste turno.','\r',char(13)),'\n',char(10)),'3 ataques','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47826112,'Poseidra, o Dragão Atlante',replace(replace('Você pode oferecer como Tributo 3 monstros de ÁGUA de Nível 3 ou menos; Invoque este card por Invocação-Especial da sua mão ou do Cemitério. \r\nSe isso acontecer: devolva todas as Magias/Armadilhas no campo para a mão e, se 3 ou mais cards forem devolvidos para a mão por este efeito, todos os monstros que seu oponente controla atualmente perdem 300 de ATK para cada um.','\r',char(13)),'\n',char(10)),'Invocação Especial','Retornar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47829960,'Gustaph, o Motoqueiro do Caos','Uma vez por turno: você pode banir até 2 Magias do seu Cemitério; este card ganha 300 de ATK para cada card banido por este efeito, até o final do turno do seu oponente.','Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47840168,'Tubarão de Mão-Esquerda',replace(replace('Se este card for Invocado por Invocação-Especial do Cemitério: o Nível deste card se torna 4. \r\nVocê só pode usar cada um dos seguintes efeitos de "Tubarão de Mão-Esquerda" uma vez por turno. \r\nSe você controlar "Tubarão de Mão-Direita" e este card estiver na sua mão ou no Cemitério: você pode Invocar este card por Invocação-Especial, mas bana-o quando ele deixar o campo. \r\nUm Monstro Xyz que foi Invocado usando apenas monstros de ÁGUA como matéria, incluindo este card no campo, ganha este efeito.\r\n● Este card não pode ser destruído por efeitos de card.','\r',char(13)),'\n',char(10)),'','','O efeito de "Tubarão de Mão-Esquerda" está sendo aplicado.','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47852924,'Alma do Puro','Aumente os seus Life Points em 800 pontos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47852925,'Alma do Puro','Aumente os seus Life Points em 800 pontos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47863787,'Artefato Labrys',replace(replace('Você pode Baixar este card da sua mão na sua Zona de Magias & Armadilhas como um Card de Magia. \r\nDurante o turno do seu oponente, se este card Baixado na Zona de Magias & Armadilhas for destruído e enviado para o seu Cemitério: Invoque-o por Invocação-Especial. \r\nQuando um ou mais cards "Artefato" forem destruídos e enviados para o seu Cemitério (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão.','\r',char(13)),'\n',char(10)),'Invocação Especial','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47870325,'Ação Sorridente',replace(replace('Quando este card for ativado: cada duelista pode banir, com a face para baixo, até 5 Magias do seu próprio Cemitério. \r\nSe um monstro declarar um ataque: o duelista atacado ativa este efeito;\r\n● Você (o duelista atacado) pode adicionar aleatoriamente à sua mão 1 dos seus cards banidos pelo efeito deste card e, depois, você pode descartá-lo e negar o ataque, mas se você não descartar o card adicionado, qualquer dano de batalha que você sofrer neste turno é dobrado (mesmo que este card deixe o campo).','\r',char(13)),'\n',char(10)),'Banir 1 Card de Magia do Cemitério com a face para baixo?','Usar o efeito de "Ação Sorridente"?','Descartar esse card para negar o ataque?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47873397,'Poste Totêmico',replace(replace('Seu oponente não pode escolher monstros Rocha que você controla com 0 de ATK original como alvo de efeitos de card. \r\nUma vez por batalha, quando um monstro do oponente declarar um ataque: você pode negar o ataque e, se isso acontecer, coloque 1 marcador neste card. \r\nSe este card tiver 3 marcadores, envie-o para o Cemitério. \r\nSe você tiver 3 ou mais monstros Rocha no seu Cemitério com 0 de ATK e nomes diferentes uns dos outros: você pode banir este card do seu Cemitério; qualquer dano de efeito que seu oponente sofrer neste turno é dobrado.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47879985,'Guardião da Sala do Trono','Um guarda robô contruído para proteger salas de trono. Está armado com mísseis automáticos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47882565,'Magia de Aumento de Classe Ascensão Críptica',replace(replace('Durante a Fase Principal de qualquer duelista: escolha 1 Monstro Xyz "Críptico(a)" que você controla; Invoque por Invocação-Especial do seu Deck Adicional, 1 Monstro Xyz "Críptico(a)" de 1 Classe maior que o alvo, usando o alvo como Matéria Xyz. \r\n(Esta Invocação-Especial é considerada uma Invocação-Xyz. Matérias Xyz associadas ao alvo também se tornam Matérias Xyz no monstro Invocado.) \r\nEle ganha este efeito.\r\n● Este card ganha 500 de ATK para cada monstro de Nível 4 ou mais que você controla.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47882774,'Dignidade Caverguerra',replace(replace('Você deve controlar um monstro "Caverguerra" para ativar qualquer um desses efeitos.\r\n● Quando um monstro que seu oponente controla ativar seu efeito: negue o efeito.\r\n● Durante a Fase de Batalha, quando seu oponente ativar um Card de Magia/Armadilha ou um efeito de monstro: negue o efeito.	\r\nVocê só pode ativar 1 "Dignidade Caverguerra" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47894537,'Ilusionista Jongleur-Carniçal','Um artista de rua cativante que surpreende com sua canção e dança, e seus ataques hocus pocus. Quando seus olhos começam a girar, o perigo é iminente, então é melhor correr por sua vida!','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47897376,'Cristal Adamancipador - Leonita',replace(replace('Se este card for Invocado por Invocação-Especial pelo efeito de um card "Adamancipador": você pode colocar 1 card "Adamancipador" da sua mão ou do Cemitério no topo do Deck. \r\nSe este card estiver no seu Cemitério: você pode escolher 1 Monstro Sincro de FOGO que você controla ou no seu Cemitério; devolva-o para o Deck Adicional e, se isso acontecer, coloque este card no topo do Deck. \r\nVocê só pode usar cada efeito de "Cristal Adamancipador - Leonita" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47910940,'Marincesa Grande Recife de Bolhas',replace(replace('2+ monstros de ÁGUA	\r\nUma vez por turno, durante cada Fase de Apoio: você pode banir 1 monstro de ÁGUA do seu Cemitério ou do campo com a face para cima; compre 1 card. \r\nSempre que um ou mais monstros forem banidos com a face para cima: até o final deste turno, este card ganha 600 de ATK para cada um. \r\nVocê pode enviar 1 monstro de ÁGUA da sua mão para o Cemitério; Invoque por Invocação-Especial 1 dos seus monstros "Marincesa" banidos. \r\nVocê só pode usar este efeito de "Marincesa Grande Recife de Bolhas" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Aumentar ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47914440,'Restrição de Faixa',replace(replace('Quando este card for ativado: você pode Invocar por Invocação-Especial 1 dos seus monstros banidos na sua Zona de Monstros Principal mais à direita. \r\nSe seu oponente Invocaria um ou mais monstros por Invocação-Normal ou Especial na Zona de Monstros Principal dele, ele deve usar sua(s) zona(s) mais à esquerda que possa(m) ser usadas.','\r',char(13)),'\n',char(10)),'','Invocação Especial?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47921178,'Boxeador Obstinado Córner',replace(replace('Durante sua Fase Principal, você pode Invocar por Invocação-Normal 1 monstro "Boxeador Obstinado" em adição à sua Invocação-Normal/Baixar (padrão). \r\n(Você só pode se aproveitar deste efeito uma vez por turno.) \r\nQuando um monstro do oponente declarar um ataque, enquanto você controlar um monstro Guerreiro ou de FOGO: você pode Invocar este card por Invocação-Especial da sua mão e, se isso acontecer, negue o ataque e, depois, bana 1 monstro no campo até a Fase Final. \r\nVocê só pode usar este efeito de "Boxeador Obstinado Córner" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Invocar pelo efeito de "Boxeador Obstinado Córner"','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47922711,'Tatsunootoshigo','Um peixe-garanhão que galopa pelo fundo do oceano.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47929865,'Magicão','Se este card for enviado ao Cemitério para a Invocação-Sincro de um Monstro Sincro do Tipo Mago, você pode selecionar e adicionar 1 Card de Magia de Campo do seu Cemitério para a sua mão.','Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47942531,'Grande Maju Garzett','O ATK deste card torna-se igual ao dobro do ATK original do monstro que foi oferecido como Tributo para a Invocação-Tributo deste card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47946130,'Gouki, O Ogro Gigante',replace(replace('3+ monstros "Gouki"	\r\nNão pode ser destruído em batalha e não é afetado pelos efeitos ativados dos monstros do seu oponente com ATK menor ou igual ao deste card. \r\nQuando seu oponente ativar um card ou efeito que escolha como alvo este card e/ou um ou mais monstros para os quais este card apontar (Efeito Rápido): você pode fazer com que este card perca exatamente 500 de ATK e, se isso acontecer, negue a ativação. \r\nUma vez por turno, se o ATK atual deste card for diferente do seu ATK original (Efeito Rápido): até o final deste turno, você pode fazer com que este card ganhe 1000 de ATK.','\r',char(13)),'\n',char(10)),'Negar a ativação','Aumentar ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47960073,'Noroi K9-04',replace(replace('Se seu oponente tiver 2 ou mais cards na mão dele, você pode Invocar este card por Invocação-Normal sem oferecer Tributo. \r\nVocê só pode usar cada um dos seguintes efeitos de "Noroi K9-04" uma vez por turno. \r\nSe este card for Invocado por Invocação-Normal: você pode Invocar por Invocação-Especial 1 monstro "K9" não-Máquina do seu Deck, mas você não pode Invocar por Invocação-Especial do Deck Adicional, exceto monstros "K9", enquanto você controlar esse monstro com a face para cima. \r\nVocê pode enviar 1 card "K9" com a face para cima que você controla para o Cemitério; olhe a mão do seu oponente.','\r',char(13)),'\n',char(10)),'Invocação Normal sem Tributo','Invocação Especial','Revelar a mão','Invocado por Invocação Especial pelo efeito de "Noroi K9-04"','','','','','','','','','','','','');
INSERT INTO texts VALUES(47961342,'Ponto de Comutação',replace(replace('Selecione 1 monstro que seu oponente controla e seu oponente envia um dos seguintes para o Cemitério.\r\n● O monstro selecionado.\r\n● Os outros monstros que ele controla.	\r\nSeu oponente deve controlar 3 ou mais monstros para você ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'','Envie o monstro selecionado para o Cemitério','Envie todos os outros monstros para o Cemitério','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47961808,'Estátua Barreira do Inferno','Nenhum duelista pode Invocar monstros por Invocação-Especial, exceto monstros de FOGO.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47963370,'Mago do Caos',replace(replace('Você pode Invocar este card por Invocação-Ritual com "Forma do Caos". \r\nO nome deste card se torna "Mago Negro" enquanto estiver no campo ou no Cemitério. \r\nUma vez por turno, quando um Card de Magia/Armadilha ou seus efeitos for ativado (Efeito Rápido): você pode escolher 1 card no campo; destrua-o. \r\nSe este card Invocado por Invocação-Ritual for destruído em batalha ou por um efeito de card: você pode Invocar por Invocação-Especial 1 Monstro de Ritual "Caos" ou "Soldado do Lustro Negro" da sua mão, exceto "Mago do Caos", ignorando suas condições de Invocação.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47985614,'Dispositivo Braçal','VIRE: Escolha 1 Card de Magia ou Armadilha "Morfotrônico(a)" no seu Cemitério e adicione-o à sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(47986555,'Golem Milênio','Por quase um milênio, este golem serviu como guardião de um antigo tesouro.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48009503,'Campeão Heroico - Gandiva',replace(replace('2 monstros Guerreiro de Nível 4	\r\nUma vez por turno, quando um ou mais monstros de Nível 4 ou menos forem Invocados por Invocação-Especial no campo do seu oponente (exceto durante a Etapa de Dano): você pode desassociar 1 matéria deste card; destrua esses monstros Invocados por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48015771,'Invocar Novamente',replace(replace('Sempre que um ou mais monstros forem Invocados por Invocação-Especial, coloque 1 Marcador de Invocação neste card (máx. 6). \r\nEste card com 6 Marcadores de Invocação não pode ser destruído por efeitos de card. \r\nNo começo de cada Fase Principal 1, se este card tiver 6 Marcadores de Invocação: o duelista do turno pode ativar este efeito; ele envia este card para o Cemitério e, se isso acontecer, ele envia para o Cemitério todos os monstros Invocados por Invocação-Especial que o oponente dele controla.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48016074,'Encantadoras do Círculo Maior',replace(replace('2+ monstros "Encantador(a)" ou "Espírito-Possuído"	\r\nSe este card for Invocado por Invocação-Fusão: você pode ativar este efeito; para cada Atributo original diferente usado para sua Invocação-Fusão (máx. 4), você pode aplicar 1 efeito desta lista. \r\nVocê pode selecionar o mesmo efeito mais de uma vez. \r\nResolva cada efeito antes de selecionar novamente.\r\n● Este card ganha 800 de ATK.\r\n● Adicione 1 Magia/Armadilha "Possuído(a)" do seu Deck à sua mão.\r\n● Devolva 1 card no campo para a mão.\r\n● Invoque por Invocação-Especial 1 monstro Mago do seu Cemitério.	\r\nVocê só pode usar este efeito de "Encantadoras do Círculo Maior" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar','Aumentar ATK','Adicionar à mão','Retornar para a mão','Invocação Especial','Encerrar','','','','','','','','','','');
INSERT INTO texts VALUES(48017189,'EM:P Minamiau',replace(replace('Se um Monstro Link estiver no campo ou em qualquer Cemitério, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "EM:P Minamiau" por Invocação-Especial uma vez por turno desta forma. \r\nSe um monstro de Link-2 que você controla for enviado para o Cemitério ou banido com a face para cima (exceto durante a Etapa de Dano): você pode banir este card do seu Cemitério (se ele estava lá quando o monstro foi enviado ou banido) ou da mão (mesmo se ele não estava) e, depois, escolha 1 card que seu oponente controla; devolva-o para a mão. \r\nVocê só pode usar este efeito de "EM:P Minamiau" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Escolha o(s) card(s) para banir','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48017809,'Tubo de Miragem',replace(replace('Este card não pode ser ativado da sua mão. \r\nAtive apenas quando um monstro com a face para cima que você controla for escolhido como alvo de um ataque. \r\nCause 1000 de dano ao seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48032131,'D - Tática',replace(replace('Durante a Fase de Apoio: você pode fazer com que todos os monstros "HERÓI" que você controla ganhem 400 de ATK (mesmo que este card deixe o campo). \r\nSe um ou mais monstros "HERÓI do Destino" de Nível 8 ou mais ou um "Dragoon do Destino Final" for Invocado por Invocação-Especial no seu campo (exceto durante a Etapa de Dano): você pode banir 1 card da mão (aleatório), do campo ou do Cemitério do seu oponente. \r\nSe este card na Zona de Magias & Armadilhas for destruído por um efeito de card: você pode adicionar 1 monstro "HERÓI do Destino" do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "D - Tática" uma vez por turno.','\r',char(13)),'\n',char(10)),'Aumentar ATK','Banir 1 card','Banir 1 card da mão','Banir 1 card do campo ou do Cemitério','','','','','','','','','','','','');
INSERT INTO texts VALUES(48048590,'Defensor da Magia do Dragão',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode descartar 1 card; adicione 1 Magia Normal "Polimerização" ou Magia Normal "Fusão" do seu Deck à sua mão. \r\nVocê pode revelar 1 Monstro de Fusão no seu Deck Adicional; Invoque por Invocação-Especial 1 das Matérias de Fusão mencionadas nesse monstro do seu Cemitério, com a face para baixo em Posição de Defesa. \r\nVocê só pode usar cada efeito de "Defensor da Magia do Dragão" uma vez por turno. \r\nVocê não pode Invocar por Invocação-Especial do Deck Adicional, exceto Monstros de Fusão, no turno em que ativar qualquer um dos efeitos deste card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48049769,'Cavalo-marinho do Trovão',replace(replace('Você pode descartar este card; adicione 2 monstros de LUZ do Tipo Trovão de Nível 4 com o mesmo nome e com 1600 ou menos de ATK do seu Deck à sua mão. \r\nVocê só pode usar o efeito de "Cavalo-marinho do Trovão" uma vez por turno. \r\nVocê não pode Invocar por Invocação-Especial durante o turno em que ativar este efeito.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48063985,'Besta Espiritual Ulti-Cannáguia',replace(replace('1 monstro "Domador da Besta Espiritual" + 1 monstro "Avatar da Besta Espiritual"	\r\nDeve ser Invocado por Invocação-Especial (do seu Deck Adicional) ao banir os cards acima que você controla. \r\nUma vez por turno: você pode escolher 2 dos seus cards "Besta Espiritual" banidos; devolva-os para o Cemitério e, se isso acontecer, adicione 1 card "Besta Espiritual" do seu Deck à sua mão. \r\n(Efeito Rápido): você pode devolver este card que você controla para o Deck Adicional e, depois, escolha 2 dos seus monstros banidos (1 monstro "Domador da Besta Espiritual" e 1 monstro "Avatar da Besta Espiritual"); Invoque-os por Invocação-Especial em Posição de Defesa.','\r',char(13)),'\n',char(10)),'Retornar card(s) banido(s) e depois adicione um card à sua mão','Retornar ao Deck Adicional e depois Invoque por Invocação Especial um monstro banido','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48063986,'Besta Espiritual Ulti-Cannáguia',replace(replace('1 monstro "Domador da Besta Espiritual" + 1 monstro "Avatar da Besta Espiritual"	\r\nDeve ser Invocado por Invocação-Especial (do seu Deck Adicional) ao banir os cards acima que você controla. \r\nUma vez por turno: você pode escolher 2 dos seus cards "Besta Espiritual" banidos; devolva-os para o Cemitério e, se isso acontecer, adicione 1 card "Besta Espiritual" do seu Deck à sua mão. \r\n(Efeito Rápido): você pode devolver este card que você controla para o Deck Adicional e, depois, escolha 2 dos seus monstros banidos (1 monstro "Domador da Besta Espiritual" e 1 monstro "Avatar da Besta Espiritual"); Invoque-os por Invocação-Especial em Posição de Defesa.','\r',char(13)),'\n',char(10)),'Retornar card(s) banido(s) e depois adicione um card à sua mão','Retornar ao Deck Adicional e depois Invoque por Invocação Especial um monstro banido','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48068378,'Link Devoto',replace(replace('1 monstro Ciberso de Nível 4 ou menos	\r\nSe este card for Invocado por Invocação-Especial: pelo resto deste turno, você não pode Invocar por Invocação-Link Monstros Link de Link-3 ou mais. \r\nSe este card co-linkado for oferecido como Tributo: você pode Invocar por Invocação-Especial 2 "Fichas Link" (Ciberso/LUZ/Nível 1/ATK 0/DEF 0). \r\nVocê só pode usar este efeito de "Link Devoto" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48068379,'Ficha Link','Invocado por Especial com o efeito "Link Devoto" ou um card relacionado.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48086335,'Artefato Failnaught',replace(replace('Você pode Baixar este card da sua mão na sua Zona de Magias & Armadilhas como um Card de Magia. \r\nDurante o turno do seu oponente, se este card Baixado na Zona de Magias & Armadilhas for destruído e enviado para o seu Cemitério: Invoque-o por Invocação-Especial. \r\nSe este card for Invocado por Invocação-Especial durante o turno do seu oponente: você pode escolher 1 monstro "Artefato" no seu Cemitério; Baixe o alvo na sua Zona dos Cards de Magia e Armadilha como um Card de Magia.','\r',char(13)),'\n',char(10)),'Invocação Especial','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48092532,'Sobrevivente D.D.',replace(replace('Durante a Fase Final, se este card foi banido enquanto estava com a face para cima no seu campo, neste turno: Invoque este card banido por Invocação-Especial. \r\nEste efeito só pode ser ativado uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48094997,'Futebolista de Combate','Um cyborg com um elevado poder de defesa. Originalmente foi inventado para ser uma máquina de futebol.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48109103,'Vingador Kappa','Um anfíbio que vendeu sua alma em troca de poder ilimitado para vingar seu amigo falecido.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48115277,'Bloqueador',replace(replace('Você pode oferecer este card como Tributo; Invoque por Invocação Especial em Posição de Defesa, um número de "Fichas de Bloqueio" (Tipo Rocha/TERRA/Nível 4/ATK 1000/DEF 1500) igual ao número de turnos seus em que este card esteve com a face para cima no seu campo. \r\nEssas Fichas não podem declarar um ataque.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48115278,'Ficha de Bloqueio','Invocado por Especial com o efeito "Bloqueador". Esta Ficha não pode declarar um ataque.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48130397,'Super Polimerização',replace(replace('Descarte 1 card; Invoque por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional, usando monstros de qualquer campo. \r\nNenhum duelista pode ativar cards ou efeitos em resposta à ativação deste card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48130398,'Super Polimerização',replace(replace('Descarte 1 card; Invoque por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional, usando monstros de qualquer campo. \r\nNenhum duelista pode ativar cards ou efeitos em resposta à ativação deste card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48135190,'Tempestade de Cascalho','Escolha 1 Magia/Armadilha em cada campo; devolva-os para a mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48144509,'Fusão dos Olhos Anômalos',replace(replace('Invoque por Invocação-Fusão 1 Monstro de Fusão Dragão do seu Deck Adicional, usando monstros da sua mão ou do campo como Matérias de Fusão. \r\nSe seu oponente controlar 2 ou mais monstros e você não controlar nenhum monstro, você também pode usar até 2 monstros "Olhos Anômalos" do seu Deck Adicional como Matérias de Fusão. \r\nVocê só pode ativar 1 "Fusão dos Olhos Anômalos" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48144778,'Conjurador Inférnico',replace(replace('Enquanto você não tiver cards na sua mão, os monstros que seu oponente controla perdem 800 de ATK. \r\nEnquanto você não tiver cards na sua mão e este card estiver no seu Cemitério: você pode Invocar este card por Invocação-Especial, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar este efeito de "Conjurador Inférnico" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48148828,'Besta Maluca D.D.','Um monstro que este card destrua como resultado de um combate é removido de jogo.','Banir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48150362,'HERÓI do Destino - Mão Rápida',replace(replace('Se este card for Invocado por Invocação-Especial pelo efeito de um monstro "HERÓI": você pode fazer com que cada duelista compre 1 card. \r\nDurante a próxima Fase de Apoio depois que este card foi enviado para o Cemitério: você pode Invocar este card por Invocação-Especial do seu Cemitério, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar cada efeito de "HERÓI do Destino - Mão Rápida" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48152161,'O Santificado Senhor Obscuro',replace(replace('Envie 1 monstro "Senhor(a) Obscuro(a)" da sua mão ou com a face para cima do seu campo para o Cemitério; até o final deste turno, negue os efeitos de 1 Monstro de Efeito no campo e, se isso acontecer, ganhe PV igual ao ATK dele. \r\nVocê só pode ativar 1 "O Santificado Senhor Obscuro" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48156348,'Besta Gladiadora Gyzarus',replace(replace('"Besta Gladiadora Bestiari" + 1 monstro "Besta Gladiadora"	\r\nPrimeiro deve ser Invocado por Invocação-Especial (do seu Deck Adicional) ao embaralhar os cards acima que você controla no Deck. \r\n(Você não usa "Polimerização".) \r\nQuando este card for Invocado por Invocação-Especial: você pode escolher até 2 cards no campo; destrua os alvos. \r\nNo final da Fase de Batalha, se este card batalhou: você pode devolvê-lo para o Deck Adicional; Invoque por Invocação-Especial 2 monstros "Besta Gladiadora" do seu Deck, exceto "Besta Gladiadora Bestiari".','\r',char(13)),'\n',char(10)),'Destruir','Invocação Especial','Escolha 1 "Besta Gladiadora Bestiari"','Escolha 1 monstro "Besta Gladiadora"','','','','','','','','','','','','');
INSERT INTO texts VALUES(48171151,'Feiticeiro Astrógrafo, o Mago da Estrelas',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nVocê só pode ativar o Efeito de Pêndulo de "Feiticeiro Astrógrafo, o Mago da Estrelas" uma vez por turno.\r\nDurante sua Fase Principal: você pode destruir este card, e se fizer, coloque 1 Monstro Pêndulo cuja Escala de Pêndulo seja 1 da sua mão ou Deck na sua Zona de Pêndulo, exceto "Feiticeiro Astrógrafo, o Mago da Estrelas", mas ele não pode ativar seus Efeitos de Pêndulo nesse turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe um ou mais cards de Monstros com a face para cima que você controla são destruídos por batalha ou efeito: você pode Invocar por Invocação-Especial este card da sua mão, então você pode Invocar por Invocação-Especial 1 daqueles monstros destruídos do seu Cemitério ou com a face para cima no Deck Adicional.\r\nDurante a Fase Principal (Efeito Rápido): você pode oferecer este card como Tributo, então você pode Invocar por Invocação-Fusão 1 Monstro Dragão de Fusão do seu Deck Adicional, por embaralhar seus matérias do seu campo e/ou com a face para cima no seu Deck Adicional em seu Deck.\r\nVocê só pode usar cada um dos efeitos de "Feiticeiro Astrógrafo, o Mago da Estrelas" uma vez por turno.','\r',char(13)),'\n',char(10)),'Colocar na Zona de Pêndulo','Invocação Especial','Invocação Fusão','Invocar um monstro por Invocação Especial?','Invocação Fusão?','','','','','','','','','','','');
INSERT INTO texts VALUES(48171152,'Feiticeiro Astrógrafo, o Mago da Estrelas',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nVocê só pode ativar o Efeito de Pêndulo de "Feiticeiro Astrógrafo, o Mago da Estrelas" uma vez por turno.\r\nDurante sua Fase Principal: você pode destruir este card, e se fizer, coloque 1 Monstro Pêndulo cuja Escala de Pêndulo seja 1 da sua mão ou Deck na sua Zona de Pêndulo, exceto "Feiticeiro Astrógrafo, o Mago da Estrelas", mas ele não pode ativar seus Efeitos de Pêndulo nesse turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe um ou mais cards de Monstros com a face para cima que você controla são destruídos por batalha ou efeito: você pode Invocar por Invocação-Especial este card da sua mão, então você pode Invocar por Invocação-Especial 1 daqueles monstros destruídos do seu Cemitério ou com a face para cima no Deck Adicional.\r\nDurante a Fase Principal (Efeito Rápido): você pode oferecer este card como Tributo, então você pode Invocar por Invocação-Fusão 1 Monstro Dragão de Fusão do seu Deck Adicional, por embaralhar seus matérias do seu campo e/ou com a face para cima no seu Deck Adicional em seu Deck.\r\nVocê só pode usar cada um dos efeitos de "Feiticeiro Astrógrafo, o Mago da Estrelas" uma vez por turno.','\r',char(13)),'\n',char(10)),'Colocar na Zona de Pêndulo','Invocação Especial','Invocação Fusão','Invocar um monstro por Invocação Especial?','Invocação Fusão?','','','','','','','','','','','');
INSERT INTO texts VALUES(48179391,'O Selo de Orichalcos',replace(replace('Todos os monstros que você controla ganham 500 de ATK. \r\nUma vez por turno, este card não pode ser destruído por efeitos de card. \r\nEnquanto você controlar 2 ou mais monstros com a face para cima em Posição de Ataque, seu oponente não pode escolher seu(s) monstro(s) com o menor ATK como alvo de um ataque. \r\nSe este card for ativado: destrua todos os monstros Invocados por Invocação-Especial que você controla. \r\nVocê não pode Invocar monstros por Invocação-Especial do Deck Adicional. \r\nVocê só pode ativar "O Selo de Orichalcos" uma vez por Duelo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48183890,'Armadilhatrix Atypus',replace(replace('2+ monstros, incluindo um monstro Inseto ou Planta	\r\nEste card Invocado por Invocação-Link não é afetado por efeitos de Armadilha. \r\nTodos os monstros "Armadilhatrix" que você controla ganham 1000 de ATK enquanto você tiver uma Armadilha Normal no seu Cemitério. \r\nUma vez por turno: você pode escolher cards com a face para cima que seu oponente controla até o número de monstros Inseto e Planta que você controla; negue seus efeitos (até o final deste turno) e, depois, você pode aplicar este efeito.\r\n● Bana 1 Armadilha Normal do seu Cemitério e, se isso acontecer, destrua 1 desses cards alvo com a face para cima.','\r',char(13)),'\n',char(10)),'','Destruir 1 deles?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48202661,'Aitsu','Ele parece não ser de confiança, mas ele pode ter um potencial incrível.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48206762,'Execução De Um Contrato',replace(replace('Ative este card ao pagar 800 PV e, depois, escolha 1 Monstro de Ritual no seu Cemitério; Invoque-o por Invocação-Especial e equipe-o com este card. \r\nQuando este card for destruído, bana o monstro equipado.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48210156,'D/D Uivo Noturno',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode escolher 1 monstro "D/D" no seu Cemitério; Invoque-o por Invocação-Especial e, além disso, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros do Tipo Demônio. \r\nO ATK e DEF desse monstro se tornam 0. \r\nSe ele for destruído, você sofre 1000 de dano.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48214588,'Novato de Peluguel',replace(replace('Ofereça 1 monstro como Tributo; Invoque por Invocação-Especial 1 monstro "de Peluguel" da sua mão ou do Deck, cujo Nível seja 1 maior ou 1 menor que o monstro oferecido como Tributo tinha no campo. \r\nVocê não pode declarar ataques no turno em que ativar este card, exceto com monstros "de Peluguel". \r\nVocê só pode ativar 1 "Novato de Peluguel" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48216773,'Aparato de Fuga Obrigatória','Cada duelista escolhe 1 monstro que controla e, depois, embaralha-o no Deck.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48228390,'Cavaleiro Pirita',replace(replace('Se este card estiver na sua mão ou no Cemitério: você pode escolher 1 monstro Guerreiro (de TERRA ou de FOGO) que você controla, exceto "Cavaleiro Pirita"; devolva-o para a mão e, se isso acontecer, Invoque este card por Invocação-Especial e, depois, Invoque por Invocação-Especial 1 "Ficha de Pirita" (Guerreiro/FOGO/Nível 4/ATK 0/DEF 2000) no campo do seu oponente em Posição de Defesa. \r\nDurante a Fase de Batalha (Efeito Rápido): você pode Invocar por Invocação-Especial 1 monstro Guerreiro da sua mão. \r\nVocê só pode usar cada efeito de "Cavaleiro Pirita" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar este card por Invocação Especial','Invocar por Invocação Especial da mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48228391,'Ficha de Pirita','Invocado por Especial com o efeito "Cavaleiro Pirita".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48229808,'Horus, o Dragão da Chama Negra LV8',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial por "Horus, o Dragão da Chama Negra LV6" e não pode ser Invocado por Invocação-Especial de nenhuma outra forma. \r\nDurante o turno de qualquer duelista, quando um Card de Magia for ativado: você pode negar a ativação e, se isso acontecer, destrua-o. \r\nVocê deve controlar este card com a face para cima para ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Negue a ativação de uma Magia e a destrua','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48252330,'Mordorrada Magidoce',replace(replace('Quando este card que você controla for destruído por um card do seu oponente (seja em batalha ou por um efeito de card) e enviado ao seu Cemitério: Embaralhe este card no seu Deck. \r\nQuando este card for Invocado por Invocação-Normal: Você pode adicionar 1 Card de Magia de Campo do seu Deck à sua mão. \r\nDeve haver outro monstro "Magidoce" com a face para cima no campo para ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Retornar ao Deck','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48276469,'Explosão em Cadeia','Inflija 1000 pontos de dano a cada jogador que active um Card de Armadilha.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48285768,'Springans Festeiro',replace(replace('2 monstros de Nível 4	\r\nSe este card for Invocado por Invocação-Especial do seu Deck Adicional: você pode enviar 1 monstro "Springans" do seu Deck para o Cemitério. \r\nDurante a Fase Principal ou de Batalha do seu oponente (Efeito Rápido): você pode banir este card até a Fase Final e, depois, se você baniu este card com 2 ou mais Matérias Xyz, você também pode enviar 1 Monstro de Fusão do seu Deck Adicional para o Cemitério que liste "Caído de Arbaz" como matéria. \r\nVocê só pode usar cada efeito de "Springans Festeiro" uma vez por turno.','\r',char(13)),'\n',char(10)),'Enviar 1 monstro "Springans" do seu Deck para o Cemitério','Banir este card até a Fase Final','Enviar outro Monstro Fusão para o Cemitério?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48305365,'Predador com Machado','Um monstro de tremenda força e agilidade que brande seu machado.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48308134,'Colisão Fantasma Espiral',replace(replace('Só pode ser equipado a um Monstro Normal. \r\nSe o monstro equipado atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente. \r\nQuando o monstro equipado causar dano de batalha ao seu oponente: você pode Invocar por Invocação-Especial 1 "Dragão Fantasma Espiral" de sua mão, Deck ou Cemitério, e equipe-o com este card e, depois, você pode mudar 1 monstro em Posição de Ataque que seu oponente controla para Posição de Defesa. \r\nVocê só pode usar este efeito de "Colisão Fantasma Espiral" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar "Dragão Fantasma Espiral" por Invocação Especial','Mudar um monstro do seu oponente para Posição de Defesa?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48310593,'Cards Finitos','O limite de cards na mão de cada duelista se torna 3.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48333324,'Magia de Aumento de Classe Força Numeron',replace(replace('Escolha 1 Monstro Xyz com a face para cima que você controla; Invoque por Invocação-Especial do seu Deck Adicional, 1 monstro "Número C" com o mesmo Tipo que esse monstro que você controla, mas 1 Classe maior, usando-o como Matéria Xyz. \r\n(Esta Invocação-Especial é considerada uma Invocação-Xyz. Matérias Xyz associadas a ele também se tornam Matérias Xyz no monstro Invocado.) \r\nDepois, se houver qualquer outro card com a face para cima no campo, diferente deste card e do monstro Invocado por ele, negue os efeitos desses outros cards.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48343627,'Serpeador do Túmulo','Se este card for destruído em batalha e enviado para o Cemitério: escolha 1 card no campo; destrua o alvo.','Destrua 1 card no campo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48348921,'Número C62: Neo Dragão Primordial de Fóton de Olhos das Galáxias',replace(replace('3 monstros de LUZ de Nível 8	\r\nVocê também pode Invocar este card por Invocação-Xyz ao usar "Número 62: Dragão Primordial de Fóton de Olhos das Galáxias" que você controla. \r\n(Transfira as matérias dele para este card.) \r\nNo começo da sua Fase de Batalha: você pode desassociar 1 matéria deste card; este card pode realizar até 3 ataques contra monstros durante esta Fase de Batalha. \r\nSe este card tiver "Dragão de Fóton de Olhos das Galáxias" como matéria, ele ganha esses efeitos.\r\n● Não é afetado pelos efeitos de monstro do seu oponente.\r\n● Ganha ATK igual à soma dos Níveis/Classes das matérias associadas a ele x 100.','\r',char(13)),'\n',char(10)),'','Invocar por Invocação Xyz usando "Número 62: Dragão Primordial de Fóton de Olhos das Galáxias" como matéria?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48355999,'Foguette Sincron','Quando este card for Invocado por Invocação-Normal: você pode escolher 1 monstro Dragão de TREVAS de Nível 5 ou mais no seu Cemitério; Invoque-o por Invocação-Especial em Posição de Defesa, negue seus efeitos, destrua-o durante a Fase Final e, além disso, você não pode Invocar monstros por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto monstros de TREVAS.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48356796,'Cards Místicos da Luz',replace(replace('Você não pode usar 1 das suas Zonas de Cards de Magia & Armadilha. \r\nDurante sua Fase de Compra, se você controlar outro "Cards Místicos da Luz", você pode comprar 2 cards em vez de 1 na sua compra normal.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48357738,'Dor de Barriga do Tirano',replace(replace('Ative ao oferecer 1 monstro como Tributo. \r\nNenhum duelista pode Invocar por Invocação-Especial monstros de Nível 6 ou mais. \r\nSe você tiver 3 ou mais cards na mão, destrua este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48365709,'Ansatsu','Um guerreiro silencioso e mortal especializado em assassínios.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48370501,'Sigma Vylon',replace(replace('1 Regulador de LUZ + 1 ou mais monstros de LUZ não-Reguladores	\r\nQuando este card declarar um ataque, se ele for o único monstro que você controla: Você pode equipar 1 Card de Magia de Equipamento do seu Deck a este card com a face para cima.','\r',char(13)),'\n',char(10)),'Equipar','Escolha 1 Card de Magia de Equipamento','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48372950,'Dinolutador Escrimamenchi',replace(replace('Se você controlar um monstro "Dinolutador", você pode Invocar este card por Invocação-Normal sem oferecer Tributo. \r\nDurante o seu turno, se seu oponente Invocar um ou mais monstros por Invocação-Especial enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode escolher 1 monstro "Dinolutador" de Nível 4 ou menos no seu Cemitério; Invoque-o por Invocação-Especial e, depois, adicione este card à sua mão. \r\nVocê só pode usar este efeito de "Dinolutador Escrimamenchi" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Normal sem Tributo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48381268,'Pranchen Morfotrônica',replace(replace('● Posição de Ataque: Monstros "Morfotrônico(a)" que você controla podem atacar diretamente.\r\n● Posição de Defesa: Outros monstros "Morfotrônico(a)" que você controla não podem ser destruídos em batalha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48386462,'O Cuco Comandado a Cantarolar',replace(replace('Você pode ativar 1 desses efeitos;\r\n● Destrua este card e, depois, compre 1 card.\r\n● Descarte 1 card e, depois, compre 1 card.\r\n● Durante a Fase Final deste turno, compre 1 card.	\r\nVocê só pode usar este efeito de "O Cuco Comandado a Cantarolar" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Destruir este card e depois comprar 1 card','Descarte 1 card e depois compre 1 card','Durante a Fase Final deste turno, compre 1 card','','','','','','','','','','','','');
INSERT INTO texts VALUES(48393693,'Garota Gagaga – Subtração de Celular',replace(replace('Se seu oponente Invocar por Invocação-Especial um ou mais monstros do Deck Adicional: você pode escolher 1 monstro com a face para cima que você controla; Invoque este card da sua mão por Invocação-Especial, então, imediatamente após ativar este efeito, Invoque por Invocação-Xyz usando apenas ele e o monstro escolhido. \r\nQuando fizer isso, considere este card do mesmo nível daquele monstro.\r\nSe este card for desassociado para ativar um efeito de um Monstro Xyz: você pode alterar o ATK de 1 monstro com a face para cima que seu oponente controla para 0.\r\nVocê só pode usar cada um dos efeitos de "Garota Gagaga – Subtração de Celular" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','ATK torna-se 0','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48393694,'Garota Gagaga – Subtração de Celular',replace(replace('Se seu oponente Invocar por Invocação-Especial um ou mais monstros do Deck Adicional: você pode escolher 1 monstro com a face para cima que você controla; Invoque este card da sua mão por Invocação-Especial, então, imediatamente após ativar este efeito, Invoque por Invocação-Xyz usando apenas ele e o monstro escolhido. \r\nQuando fizer isso, considere este card do mesmo nível daquele monstro.\r\nSe este card for desassociado para ativar um efeito de um Monstro Xyz: você pode alterar o ATK de 1 monstro com a face para cima que seu oponente controla para 0.\r\nVocê só pode usar cada um dos efeitos de "Garota Gagaga – Subtração de Celular" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','ATK torna-se 0','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48411996,'Jurrac Estaurico',replace(replace('Se este card for destruído em batalha: Invoque por Invocação-Especial 2 "Ficha de Jurrac" (Dinossauro/FOGO/Nível 1/ATK 0/DEF 0) em Posição de Defesa. \r\nElas não podem ser oferecidas como Tributo para uma Invocação-Tributo, exceto para um monstro "Jurrac".','\r',char(13)),'\n',char(10)),'Invocar uma Ficha por Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48411997,'Ficha de Jurrac','Invocado por Especial com o efeito "Jurrac Estaurico". Esta Ficha não pode ser oferecida como Tributo para uma Invocação-Tributo, a menos que seja para um monstro "Jurrac".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48421595,'Necro Sincron',replace(replace('O nome deste card se torna "Fleur Sincron" enquanto estiver no campo ou no Cemitério. \r\nVocê só pode usar cada um dos seguintes efeitos de "Necro Sincron" uma vez por turno. \r\nVocê pode escolher 1 outro monstro com a face para cima que você controla; aumente o Nível dele em 2 até o final deste turno. \r\nSe este card for enviado para o Cemitério como Matéria Sincro para um monstro de VENTO: você pode Invocar por Invocação-Especial 1 monstro Planta de Nível 1 do seu Deck.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48422921,'Super Impulso Impetuoso','Escolha 1 monstro com a face para cima que você controla e declare 1 Atributo; se o alvo batalhar um monstro do oponente com esse Atributo neste turno, destrua esse monstro do oponente no começo da Etapa de Dano.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48424886,'El Sombraneco Grista',replace(replace('1 monstro "Sombraneco" + 1 monstro de FOGO	\r\nPrimeiro deve ser Invocado por Invocação-Fusão. \r\nQuando seu oponente Invocaria um ou mais monstros por Invocação-Especial enquanto você tiver um card "Sombraneco" na sua mão (Efeito Rápido): você pode negar a Invocação e, se isso acontecer, destrua esse monstro e, depois, envie 1 card "Sombraneco" da sua mão para o Cemitério. \r\nVocê só pode usar este efeito de "El Sombraneco Grista" uma vez por turno. \r\nSe este card for enviado para o Cemitério: você pode escolher 1 Magia/Armadilha "Sombraneco" no seu Cemitério; adicione-a à sua mão.','\r',char(13)),'\n',char(10)),'Negar e destruir','Recuperar cards','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48427163,'Borboleta Roxa Luzlunar',replace(replace('Você pode enviar este card da sua mão ou do campo para o Cemitério e, depois, escolher 1 monstro "Luzlunar" que você controla; ele ganha 1000 de ATK até o final deste turno. \r\nVocê pode banir este card do seu Cemitério; Invoque por Invocação-Especial 1 monstro "Luzlunar" da sua mão. \r\nVocê só pode usar este efeito de "Borboleta Roxa Luzlunar" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48439321,'Valsa Magidoce','Cada vez que um monstro "Magidoce" que você controla atacar ou for atacado, depois do cálculo de dano: Cause 300 de dano ao seu oponente.','Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48444114,'Perfume Luz Lunar',replace(replace('Escolha 1 monstro "Luzlunar" no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê pode banir este card do seu Cemitério e, depois, descartar 1 card; adicione 1 monstro "Luzlunar" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Invocação Especial','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48445393,'Tempestade de Restolhos','Escolha 1 monstro "Restolhos" que você controla; envie 1 monstro "Restolhos" do seu Deck para o Cemitério, compre 1 card e, depois, destrua esse monstro.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48447192,'Espada da Centelha',replace(replace('Só pode ser equipado a um monstro "Sabre-X". \r\nSe ele destruir um monstro do oponente em batalha, você pode destruir 1 card que seu oponente controla. \r\nVocê pode oferecer como Tributo 1 monstro que você controla para devolver este card do seu Cemitério para o topo do seu Deck.','\r',char(13)),'\n',char(10)),'Destrua 1 card que seu oponente controla','Colocar no topo do Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48452496,'Dragão Flambérgia Olho de Cobra',replace(replace('Você pode escolher 1 monstro com a face para cima no campo ou em qualquer Cemitério; coloque-o com a face para cima na Zona de Magias & Armadilhas do seu dono como uma Magia Contínua. \r\nDurante o turno do seu oponente (Efeito Rápido): você pode escolher 1 Card de Monstro que é considerado como uma Magia Contínua no campo; Invoque-o por Invocação-Especial no seu campo. \r\nSe este card for enviado da mão ou do campo para o Cemitério: você pode Invocar por Invocação-Especial 2 monstros de FOGO de Nível 1 do seu Cemitério. \r\nVocê só pode usar cada efeito de "Dragão Flambérgia Olho de Cobra" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48453776,'Flagelo dos Céus Norleras',replace(replace('Este card não pode ser Invocado por Invocação-Normal ou Baixado. \r\nEste card não pode ser Invocado por Invocação-Especial exceto ao remover de jogo 1 monstro de LUZ do Tipo Fada e 3 monstros de TREVAS do Tipo Demônio no seu Cemitério. \r\nVocê pode pagar 1000 PV para enviar todos os cards no campo e nas mãos de ambos os duelistas para o Cemitério e, depois, você compra 1 card.','\r',char(13)),'\n',char(10)),'Enviar para o Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48461764,'Mago de Veneno Púrpura',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno, se um dos seus monstros de TREVAS do Tipo Mago batalhar, antes do cálculo de dano: você pode ativar este efeito; esse monstro ganha 1200 de ATK (até o final da Etapa de Dano) e, depois, destrua este card.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\n(Este card deve ser sempre considerado como um card "Dragão Fusão".)	\r\nSe este card for destruído em batalha ou por um efeito de card: você pode escolher 1 card com a face para cima no campo; destrua-o.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48468330,'Apavorante Criança do Tormento',replace(replace('VIRE: Você pode enviar 1 monstro Demônio do seu Deck para o Cemitério.\r\nSe este card for enviado da mão ou do Deck para o Cemitério: você pode Invocar este card por Invocação-Especial com a face para baixo em Posição de Defesa. \r\nVocê só pode usar cada efeito de "Apavorante Criança do Tormento" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48469380,'Imperador Arquidemônio',replace(replace('Escala de Pêndulo = 0\r\n[ Efeito de Pêndulo ]\r\nVocê pode escolher 1 outra Magia/Armadilha com a face para cima no campo; destrua tanto ela como este card. \r\nVocê só pode usar este efeito de "Imperador Arquidemônio" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nVocê pode Invocar este card por Invocação-Ritual com "Trono dos Arquidemônios". \r\nDeve ser Invocado por Invocação-Ritual. \r\nNão é afetado por outros efeitos de monstro enquanto estiver na Zona de Monstros Adicional. \r\nVocê só pode usar cada um dos seguintes efeitos de "Imperador Arquidemônio" uma vez por turno. \r\nSe este card for Invocado por Invocação-Ritual do Deck Adicional: você pode banir todos os monstros no campo, exceto nas Zonas de Monstros Adicionais. \r\nSe este card estiver na Zona de Monstros Adicional: você pode Invocar por Invocação-Especial 1 monstro Demônio da sua mão, do Deck, do Cemitério ou do banimento.','\r',char(13)),'\n',char(10)),'Efeito de destruição','Efeito de banimento','Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48486809,'Kuriboh Alado LV6',replace(replace('(Este card deve ser sempre considerado como um card "HERÓI do Elemento" e "Favorito(a)".)	\r\nNão pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão ou do Cemitério) ao banir 1 Monstro de Fusão "HERÓI do Elemento" ou 1 "Kuriboh Alado" da sua mão, do campo com a face para cima ou do Cemitério. \r\nVocê só pode Invocar "Kuriboh Alado LV6" por Invocação-Especial uma vez por turno desta forma. \r\nQuando um monstro do oponente declarar um ataque, ou seu oponente ativar um efeito de monstro no campo (Efeito Rápido): você pode oferecer este card como Tributo; destrua esse 1 monstro e, se isso acontecer, cause dano ao seu oponente igual ao ATK original dele.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48497555,'Estátua de Ferro-Velho',replace(replace('Quando um Card de Magia/Armadilha que já estiver com a face para cima no campo do seu oponente ativar seus efeitos: destrua esse card e, além disso, depois, Baixe este card com a face para baixo em vez de enviá-lo para o Cemitério. \r\nSe este card for enviado para o Cemitério: você pode escolher 1 monstro "Sucata" no seu Cemitério; Invoque-o por Invocação-Especial em Posição de Defesa. \r\nVocê só pode usar cada efeito de "Estátua de Ferro-Velho" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48505422,'Seis Samurai Lendários - Shinai',replace(replace('Se você controlar "Seis Samurai Lendários - Mizuho", você pode Invocar este card por Invocação-Especial (da sua mão). \r\nSe este card no campo for oferecido como Tributo: escolha 1 monstro "Seis Samurai" no seu Cemitério, exceto "Seis Samurai Lendários - Shinai"; adicione-o à sua mão.','\r',char(13)),'\n',char(10)),'Recuperar do Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48519867,'Caçador Adamancipador',replace(replace('Se você controlar um monstro "Adamancipador", exceto "Caçador Adamancipador": você pode Invocar este card por Invocação-Especial da sua mão. \r\nDurante sua Fase Principal: você pode escavar os 5 cards do topo do seu Deck e, se isso acontecer, você pode Invocar por Invocação-Especial 1 monstro Rocha não-Regulador escavado de Nível 4 ou menos e, além disso, coloque o resto no fundo do seu Deck em qualquer ordem. \r\nVocê só pode usar cada efeito de "Caçador Adamancipador" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Invocar por Invocação Especial o monstro?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48531733,'Pinguim Elétrico','Os braços desse monstro formam chicotes elétricos que paralisam seus inimigos com choques elétricos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48539234,'Apropriar',replace(replace('Ative apenas quando seu oponente comprar um ou mais cards fora de qualquer Fase de Compra. \r\nDepois, sempre que seu oponente comprar um ou mais cards fora de qualquer Fase de Compra, imediatamente compre 2 cards.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48546368,'Arauto da Inevitabilidade',replace(replace('Você pode Invocar este card por Invocação-Ritual com "Oráculo do Arauto". \r\nDeve ser Invocado por Invocação-Ritual. \r\nQuando seu oponente Invocaria um ou mais monstros por Invocação-Especial OU quando ele ativar um Card de Magia/Armadilha ou um efeito de monstro (Efeito Rápido): você pode enviar 1 monstro Fada da sua mão para o Cemitério; negue a Invocação-Especial ou ativação e, se isso acontecer, destrua esse card.','\r',char(13)),'\n',char(10)),'Negar e destruir','Negar e destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48568432,'Trigon',replace(replace('Uma vez por turno, durante sua Fase Principal, você pode equipar este card a um monstro do Tipo Máquina que você controla como um Card de Equipamento, OU desequipá-lo para Invocar este card por Invocação-Especial com a face para cima em Posição de Ataque. \r\nEnquanto estiver equipado a um monstro por este efeito, se o monstro equipado destruir um monstro do oponente em batalha, selecione e Invoque por Invocação-Especial 1 monstro de LUZ do Tipo Máquina de Nível 4 ou menos do seu Cemitério. \r\n(Um monstro só pode ser equipado com 1 monstro União por vez. Se o monstro equipado seria destruído, em vez disso, destrua este card.)','\r',char(13)),'\n',char(10)),'Equipar','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48576971,'Colar do Comando',replace(replace('Quando um monstro no seu Campo equipado com este card é destruído como resultado de um combate, e este card é enviado para o Cemitério, escolha e active 1 dos seguintes efeitos:\r\n● Compre 1 card do seu Deck.\r\n● Descarte 1 card aleatóriamente da mão do seu adversário para o Cemitério.','\r',char(13)),'\n',char(10)),'Ativar o efeito escolhido','Compre 1 card(s)','Seu oponente descarta 1 card aleatório da mão dele para o Cemitério','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48579379,'Grande Moth Final Perfeito',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro deve ser Invocado por Invocação-Especial (da sua mão) ao oferecer como Tributo 1 "Pequeno Moth" no seu 6º turno ou posterior depois que ele foi equipado com "Casulo de Evolução".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48582558,'Rufião Sentinela',replace(replace('Escolha 1 monstro "Rufião" com a face para cima que você controla; neste turno, ele não pode ser escolhido como alvo de outros efeitos de card ou ser destruído em batalha. \r\nNeste turno, se um monstro do oponente atacar, ele deve escolher esse monstro como alvo do ataque se ele ainda estiver no campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48588176,'Danipon','Quando este card for destruído em batalha e enviado para o Cemitério: você pode adicionar 1 monstro Inseto com 1000 ou menos de DEF do seu Deck à sua mão.','Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48589580,'Senhor Cavaleiro Celeste Parshath',replace(replace('2+ monstros Fada	\r\nVocê pode descartar 1 card; adicione 1 "O Santuário no Céu" ou 1 card que liste especificamente "O Santuário no Céu" em seu texto, do seu Deck à sua mão, ou, se "O Santuário no Céu" estiver no campo, em vez disso, você pode adicionar 1 monstro Fada. \r\nSe outro monstro Fada com a face para cima que você controla for enviado para o Cemitério (exceto durante a Etapa de Dano): você pode banir 1 monstro Fada do seu Cemitério; Invoque por Invocação-Especial 1 monstro Fada da sua mão cujo Nível seja maior que o desse monstro banido. \r\nVocê só pode usar cada efeito de "Senhor Cavaleiro Celeste Parshath" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48596760,'Luna, o Espírito Negro',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro deve ser Invocado por Invocação-Especial (da sua mão) ao banir 1 monstro de TREVAS do seu Cemitério. \r\nUma vez por turno, durante sua Fase de Apoio: cause 500 de dano ao seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48605591,'Mundo Terminal NEXT',replace(replace('Ative este card se seu oponente controlar 3 ou menos monstros e 3 ou menos Cards de Magia/Armadilha, enquanto você não controlar nenhum outro card. \r\nCards não podem ser colocados no campo se isso deixaria qualquer duelista com mais de 3 monstros ou mais de 3 Cards de Magia/Armadilha no campo dele.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48608796,'Lirilusc - Rouxinol Construído',replace(replace('2+ monstros de Nível 1	\r\nGanha 200 de ATK para cada matéria associada a ele. \r\nEste card pode atacar diretamente. \r\nEnquanto este card tiver matéria, ele pode atacar um número de vezes a cada Fase de Batalha, até o número de matérias associadas a ele. \r\nUma vez por turno (Efeito Rápido): você pode desassociar 1 matéria deste card; até o final deste turno, monstros "Lirilusc" que você controla não podem ser destruídos em batalha ou por efeitos de card e, além disso, você não sofre dano de batalha.','\r',char(13)),'\n',char(10)),'Seus monstros "Lirilusc" não podem ser destruídos','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48626373,'Arise-Heart Kashtira',replace(replace('3 monstros de Nível 7	\r\nUma vez por turno, você também pode Invocar "Arise-Heart Kashtira" por Invocação-Xyz ao usar 1 monstro "Kashtira" que você controla, se um efeito de "Shangri-Ira Kashtira" foi ativado com sucesso neste turno. \r\n(Transfira as matérias dele para este card.) \r\nQualquer card enviado para o Cemitério, em vez disso, é banido. \r\nUma vez por Corrente, sempre que um ou mais cards forem banidos: associe 1 card banido a este card como matéria. \r\nUma vez por turno (Efeito Rápido): você pode desassociar 3 matérias deste card e, depois, escolha 1 card no campo; bana-o com a face para baixo.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Xyz sobrepondo um monstro "Kashtira"?','Associar 1 card banido a este card como Matéria Xyz','Banir 1 card com a face para baixo','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48633301,'T.G. Raptor Dínamo',replace(replace('Se você controlar um monstro "T.G.", você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "T.G. Raptor Dínamo" por Invocação-Especial uma vez por turno desta forma. \r\nUma vez por turno, durante a Fase Final, se este card estiver no Cemitério porque foi destruído no campo e enviado para lá neste turno: você pode adicionar 1 monstro "T.G." do seu Deck à sua mão, exceto "T.G. Raptor Dínamo".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48636108,'U.A. Craque da Partida',replace(replace('(Este card deve ser sempre considerado como um card "F.A.")	\r\nDepois do cálculo de dano, se um monstro "U.A." ou "F.A." seu destruir um monstro do oponente em batalha, OU quando um monstro "U.A." ou "F.A." seu causar dano de batalha ao seu oponente: Invoque por Invocação-Especial qualquer número de monstros "U.A." e/ou "F.A." com nomes diferentes da sua mão e/ou do Cemitério em Posição de Defesa. \r\nVocê só pode ativar 1 "U.A. Craque da Partida" por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48642904,'Controle Hipnotizante','Durante o próximo turno do oponente, depois de ativar este card, seu oponente não pode mudar as posições de batalha dos monstros, exceto com um efeito de card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48649353,'Ushi Oni','Um touro demônio restaurado por magia das trevas que sai de um jarro.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48653261,'Penalidade da Guarda',replace(replace('Selecione 1 monstro no campo. \r\nSe ele mudar para Posição de Defesa neste turno, compre 1 card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48654267,'Rei Supremo Z-ARC - Universo Sincro',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nVocê pode oferecer como Tributo 1 Monstro Pêndulo "Rei Supremo Dragão" ou "Rei Supremo Portal"; Invoque este card por Invocação-Especial. \r\nVocê só pode usar este efeito de "Rei Supremo Z-ARC - Universo Sincro" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\n1 Regulador + 1+ Monstros Pêndulo de TREVAS não-Reguladores	\r\nO nome deste card se torna "Rei Supremo Z-ARC" enquanto estiver no campo. \r\nDepois do cálculo de dano, se este card destruiu um monstro do oponente em batalha OU, quando este card causar dano de batalha ao seu oponente: você pode Invocar por Invocação-Especial até 2 monstros "Rei Supremo Dragão" do seu Deck, Deck Adicional e/ou Cemitério em Posição de Defesa. \r\nSe este card na Zona de Monstros for destruído em batalha ou por um efeito de card: você pode colocar este card na sua Zona de Pêndulo.','\r',char(13)),'\n',char(10)),'Invoque por Invocação Especial da Zona de Pêndulo','Invocar por Invocação Especial 1 monstro "Rei Supremo Dragão"','Colocar na Zona de Pêndulo','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48654323,'Relíquia Branca de Dogmatika',replace(replace('Você pode Invocar este card por Invocação-Ritual com "Dogmatikamacabro". \r\nSe este card for Invocado por Invocação-Ritual: você pode escolher 2 monstros com a face para cima no campo; faça com que 1 desses monstros ganhe ATK igual ao ATK do outro monstro. \r\nMonstros "Dogmatika" de Nível 8 ou mais que você controla não podem ser destruídos em batalha. \r\nSe um ou mais monstros forem Invocados por Invocação-Especial do Deck Adicional do seu oponente (exceto durante a Etapa de Dano): você pode olhar o Deck Adicional do seu oponente e enviar 1 monstro dali para o Cemitério. \r\nVocê só pode usar este efeito de "Relíquia Branca de Dogmatika" uma vez por turno.','\r',char(13)),'\n',char(10)),'Aumentar ATK','Enviar do Deck Adicional para o Cemitério','Escolha o monstro cujo ATK aumentar','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48658295,'Dragãozela da Dama',replace(replace('2 monstros "Dragãozela" com o mesmo Atributo, mas Níveis diferentes	\r\nPrimeiro deve ser Invocado por Invocação-Especial (do seu Deck Adicional) ao banir os monstros acima, 1 cada do seu campo e Cemitério. \r\nSe este card for Invocado por Invocação-Especial: você pode Invocar por Invocação-Especial 1 monstro "Dragãozela" de Nível 4 ou menos do seu Deck. \r\nDurante a Fase de Apoio: você pode Invocar por Invocação-Fusão 1 Monstro de Fusão Dragão do seu Deck Adicional, ao embaralhar suas matérias do seu campo e/ou banimento no Deck. \r\nVocê só pode usar cada efeito de "Dragãozela da Dama" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Invocação Fusão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48659020,'Convocador de Espitritos','VIRE: Você pode Invocar, por Invocação-Especial, 1 Monstro Normal de Nível 3 ou menos, do seu Cemitério para o seu Campo.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48675364,'General Arquidemônio',replace(replace('Você pode descartar este card para o Cemitério; adicione 1 "Pandemônio" do seu Deck à sua mão. \r\nSe "Pandemônio" não estiver no campo, destrua este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48680970,'Alma Eterna',replace(replace('Cada "Mago Negro" na sua Zona de Monstros não é afetado pelos efeitos de card do seu oponente. \r\nSe este card com a face para cima deixar o campo: destrua todos os monstros que você controla. \r\nVocê só pode usar o seguinte efeito de "Alma Eterna" uma vez por turno. \r\nVocê pode ativar 1 destes efeitos;\r\n● Invoque por Invocação-Especial 1 "Mago Negro" da sua mão ou do Cemitério.\r\n● Adicione 1 "Ataque da Magia Negra" ou "Mil Facas" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Usar o efeito de "Alma Eterna"?','Invocar "Mago Negro" por Invocação Especial','Adicione "Ataque da Magia Negra" ou "Mil Facas" à sua mão','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48686504,'Florescer do Fogo Solitário','Uma vez por turno: você pode oferecer como Tributo 1 monstro Planta com a face para cima; Invoque por Invocação-Especial 1 monstro Planta do seu Deck.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48700891,'Esmagador de Memórias','Se este card acertar um ataque direto, cause 100 de dano ao oponente para cada card no Deck Adicional dele.','Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48705086,'Kunzita Dragolítia',replace(replace('Se este card estiver na sua mão: você pode enviar 1 Monstro Normal de Nível 7 ou mais da sua mão ou do Deck para o Cemitério e, se isso acontecer, Invoque este card por Invocação-Especial. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 Monstro Normal no seu Cemitério; Invoque-o por Invocação-Especial em Posição de Defesa. \r\nVocê só pode usar 1 efeito de "Kunzita Dragolítia" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar este card por Invocação Especial','Invocar por Invocação Especial do Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48712195,'Mercador de Cards','Uma vez por turno, durante sua Fase de Apoio: você pode embaralhar 1 card da sua mão no Deck; compre 1 card.','Trocar mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48716139,'Espada de Kusanagi',replace(replace('Só pode ser equipado a um monstro Espírito. \r\nDurante a batalha, quando ele atacar um monstro em Posição de Defesa cuja DEF seja menor que o ATK do monstro equipado, cause a diferença como Dano de Batalha ao seu oponente. \r\nQuando o monstro equipado que você controla for devolvido à mão e este card for enviado para o Cemitério, devolva este card à sua mão.','\r',char(13)),'\n',char(10)),'Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48716527,'A Erupção dos Monarcas',replace(replace('Ative este card somente se você não tiver cards no seu Deck Adicional e controlar um monstro Invocado por Invocação-Tributo. \r\nNegue os efeitos de todos os monstros com a face para cima no campo, enquanto esses monstros estiverem com a face para cima no campo, exceto monstros Invocados por Invocação-Tributo. \r\nDurante sua Fase Final, se você não controlar monstros Invocados por Invocação-Tributo, envie este card para o Cemitério.','\r',char(13)),'\n',char(10)),'Enviar para o Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48736598,'Vírus Rompe-código Enfurecido',replace(replace('2+ monstros, incluindo um monstro "Rompe-código"	\r\nQuando este card for Invocado por Invocação-Especial, se ele estiver co-linkado: você pode Invocar por Invocação-Especial até 2 monstros "Rompe-código" da sua mão e/ou do Cemitério em qual(is)quer zona(s) para a(s) qual(is) um ou mais Monstros Link apontarem. \r\nDurante sua Fase Principal: você pode destruir Magias/Armadilhas que seu oponente controla, até o número de monstros "Rompe-código" linkados no campo. \r\nVocê só pode usar cada efeito de "Vírus Rompe-código Enfurecido" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48737767,'Capitão Marmitex','Quando este card for Invocado por Invocação-Normal: você pode embaralhar 1 card da sua mão no Deck e, depois, comprar 1 card e, depois, você pode Invocá-lo por Invocação-Especial se ele for um monstro.','Retornar sua mão para o Deck','Invocação Especial?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48739166,'Número 101: ARCA da Honra Silenciosa',replace(replace('2 monstros de Nível 4	\r\nVocê pode desassociar 2 matérias deste card e, depois, escolha 1 monstro Invocado por Invocação-Especial com a face para cima em Posição de Ataque que seu oponente controla; associe-o a este card como matéria. \r\nVocê só pode usar este efeito de "Número 101: ARCA da Honra Silenciosa" uma vez por turno. \r\nSe este card com a face para cima no campo seria destruído em batalha ou por um efeito de card, em vez disso, você pode desassociar 1 matéria deste card.','\r',char(13)),'\n',char(10)),'Associar como matéria','Usar o efeito de "Número 101: ARCA da Honra Silenciosa" em vez de ser destruído?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48739627,'Teorealizar',replace(replace('Envie 1 "Medius, o Puro" do seu Deck para o Cemitério; olhe o card do topo do Deck do seu oponente e coloque-o no topo ou no fundo do Deck. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 monstro com a face para cima que você controla e declare 1 Tipo de Monstro e 1 Atributo; esse monstro se torna desse Tipo e Atributo, até o final do turno do seu oponente. \r\nVocê só pode usar cada efeito de "Teorealizar" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar','Alterar o Atributo','Coloque no topo do Deck','Coloque no fundo do Deck','','','','','','','','','','','','');
INSERT INTO texts VALUES(48742406,'Arqueira Feérica',replace(replace('Durante sua Fase Principal, você pode causar 400 de dano ao seu oponente para cada monstro de LUZ com a face para cima que você controla. \r\nEste card não pode atacar durante o mesmo turno em que você ativar este efeito. \r\nSó um "Arqueira Feérica" pode ter seu efeito ativado por turno.','\r',char(13)),'\n',char(10)),'Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48745395,'Arquidemônio de Labrinto',replace(replace('Ganha 400 de ATK para cada Armadilha Normal com um nome diferente no seu Cemitério. \r\nOs monstros do seu oponente não podem escolher monstros Demônio como alvo de ataques, exceto "Arquidemônio de Labrinto". \r\nVocê só pode usar cada um dos seguintes efeitos de "Arquidemônio de Labrinto" uma vez por turno. \r\nSe um Card de Armadilha for ativado (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe este card for Invocado por Invocação-Especial: você pode Baixar 1 Armadilha Normal do seu Deck que só pode ser ativada quando um ataque for declarado.','\r',char(13)),'\n',char(10)),'Invoque este card por Invocação Especial da sua mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48766543,'Jacaré Cyber-Tech','Originalmente um pterodátilo, esse monstro foi atacado violentamente por um dragão. Utilizando tecnologias recentes, seu mestre o salvou dos ferimentos quase fatais e o trouxe de volta como um poderoso Cyborg.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48768179,'Escorpião das Trevas - Gorg o Forte',replace(replace('Quando este card causar dano de batalha ao seu oponente, você pode ativar 1 desses efeitos:\r\n● Escolha 1 monstro que seu oponente controla; devolva o alvo para o topo do Deck.\r\n● Envie o card do topo do Deck dele para o Cemitério.','\r',char(13)),'\n',char(10)),'Ativar 1 efeito','Retornar 1 monstro que seu oponente controla para o topo do Deck dele.','Envie o card do topo do Deck do seu oponente para o Cemitério.','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48770333,'Rei Trovão, o Kaiju do Golpe Relâmpago',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) no campo do seu oponente em Posição de Ataque, ao oferecer como Tributo 1 monstro que ele controla. \r\nSe seu oponente controlar um monstro "Kaiju", você pode Invocar este card por Invocação-Especial (da sua mão) em Posição de Ataque. \r\nVocê só pode controlar 1 monstro "Kaiju". \r\nUma vez por turno: você pode remover 3 Marcadores Kaiju de qualquer parte do campo; seu oponente não pode ativar cards ou efeitos pelo resto deste turno e, além disso, este card pode realizar até 3 ataques contra monstros durante cada Fase de Batalha neste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48770334,'Rei Trovão, o Kaiju do Golpe Relâmpago',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) no campo do seu oponente em Posição de Ataque, ao oferecer como Tributo 1 monstro que ele controla. \r\nSe seu oponente controlar um monstro "Kaiju", você pode Invocar este card por Invocação-Especial (da sua mão) em Posição de Ataque. \r\nVocê só pode controlar 1 monstro "Kaiju". \r\nUma vez por turno: você pode remover 3 Marcadores Kaiju de qualquer parte do campo; seu oponente não pode ativar cards ou efeitos pelo resto deste turno e, além disso, este card pode realizar até 3 ataques contra monstros durante cada Fase de Batalha neste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48783998,'Invocador Nova',replace(replace('Quando este card for destruído em batalha e enviado para o Cemitério: você pode Invocar por Invocação-Especial 1 monstro Fada de LUZ com 1500 ou menos de ATK do seu Deck. \r\nSe "O Santuário no Céu" estiver no campo, em vez disso, você pode Invocar por Invocação-Especial 1 "Cavaleiro Celeste Parshath".','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48784854,'Herança da Luz',replace(replace('Se um monstro for Invocado por Invocação-Ritual, Fusão, Sincro ou Xyz, enquanto um monstro com o mesmo tipo de card (Ritual, Fusão, Sincro ou Xyz) estiver no campo: você pode comprar 1 card. \r\nVocê só pode usar este efeito de "Herança da Luz" uma vez por turno.','\r',char(13)),'\n',char(10)),'Compre 1 card(s)','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48791583,'Magollanica, o Invokado','"Aleister, Aquele que Invoka" + 1 monstro de TERRA','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48800175,'A Melodia do Despertar do Dragão','Descarte 1 card; adicione até 2 monstros Dragão com 3000 ou mais de ATK e 2500 ou menos de DEF do seu Deck à sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48805472,'Melodia Armadilhatrizante',replace(replace('Descarte 1 monstro Inseto ou Planta de Nível 4, ou 1 Armadilha Normal; compre 2 cards. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 dos seus monstros Inseto ou Planta banidos de Nível 4, ou Armadilhas Normais; coloque-o no fundo do Deck. \r\nVocê só pode usar cada efeito de "Melodia Armadilhatrizante" uma vez por turno.','\r',char(13)),'\n',char(10)),'Comprar','Recuperar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48806195,'Therion "Imperatriz" Alasia',replace(replace('Você só pode usar cada um dos seguintes efeitos de "Therion "Imperatriz" Alasia" uma vez por turno.\r\n● Você pode escolher 1 monstro "Therion" ou 1 monstro Réptil no seu Cemitério; Invoque este card por Invocação-Especial da sua mão e, se isso acontecer, equipe esse monstro a este card.\r\n● Você pode descartar 1 card e, depois, escolha 1 Card de Monstro "Therion" na sua Zona de Magias & Armadilhas; Invoque-o por Invocação-Especial.	\r\nUm monstro "Therion" equipado com este card ganha 700 de ATK e, além disso, ele pode ativar o 2º efeito listado acima como se fosse "Therion "Imperatriz" Alasia".','\r',char(13)),'\n',char(10)),'','Invoque por Invocação Especial um monstro da Zona de Magia/Armadilha (Therion "Imperatriz" Alasia)','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48814566,'Banquete de Milhões','Bana, com a face para baixo, qualquer número de cards do seu Deck Adicional e, até a Fase Final, bana, com a face para cima, o mesmo número de cards aleatórios com a face para baixo do Deck Adicional do seu oponente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48815792,'Hiita, a Encantadora do Fogo, em Chamas',replace(replace('2 monstros, incluindo um monstro de FOGO	\r\n(Este card deve ser sempre considerado como um card "Espírito-Possuído".)	\r\nVocê pode escolher 1 monstro de FOGO no Cemitério do seu oponente; Invoque-o por Invocação-Especial em uma zona sua para a qual este card apontar. \r\nSe este card Invocado por Invocação-Link for destruído em batalha, ou for destruído por um efeito de card do oponente enquanto estiver na Zona de Monstros do seu dono: você pode adicionar 1 monstro de FOGO com 1500 ou menos de DEF do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "Hiita, a Encantadora do Fogo, em Chamas" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48829461,'Mecanismo do Paradoxo Pernicioso',replace(replace('Se uma Magia de Campo estiver com a face para cima no campo: você pode oferecer este card como Tributo; Invoque por Invocação-Especial 1 "Mecanismo do Paralelo Pernicioso" do seu Deck e, depois, adicione 1 monstro "Pernicioso(a)" do seu Deck à sua mão, exceto "Mecanismo do Paradoxo Pernicioso". \r\nSe um monstro "Pernicioso(a)" baniria um monstro para Invocar a si mesmo por Invocação-Especial por seus próprios meios, em vez disso, você pode banir este card que você controla ou no seu Cemitério. \r\nVocê só pode usar cada efeito de "Mecanismo do Paradoxo Pernicioso" uma vez por turno.','\r',char(13)),'\n',char(10)),'Banir "Mecanismo do Paradoxo Pernicioso" em vez disso?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48832775,'Dinomorfia Kentregina',replace(replace('2 monstros "Dinomorfia" com nomes diferentes	\r\nPerde ATK igual aos seus PV. \r\nVocê só pode usar cada um dos seguintes efeitos de "Dinomorfia Kentregina" uma vez por turno. \r\nDurante a Fase Principal (Efeito Rápido): você pode pagar metade dos seus PV e banir 1 Armadilha Normal "Dinomorfia" do seu Cemitério; este efeito se torna o efeito dessa Armadilha quando esse card for ativado. \r\nSe este card for destruído em batalha ou por um efeito de card: você pode Invocar por Invocação-Especial 1 monstro "Dinomorfia" de Nível 4 ou menos do seu Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48835607,'Galatea-I, a Orcust Mecânica',replace(replace('1 monstro "Orcust" ou "Legado Mundial"	\r\nVocê só pode Invocar "Galatea-I, a Orcust Mecânica" por Invocação-Link uma vez por turno. \r\nNão pode ser usado como matéria para uma Invocação-Xyz. \r\nVocê pode enviar 1 card da sua mão para o Cemitério; adicione 1 monstro "Legado Mundial" ou 1 "Babel Orcustrado" do seu Deck ou Cemitério à sua mão. \r\nSe este card estiver no seu Cemitério: você pode banir 1 outro card "Orcust" do seu Cemitério; Invoque este card por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Galatea-I, a Orcust Mecânica" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Invocar por Invocação Especial do Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48868994,'Aspiradoren Morfotrônico',replace(replace('● Enquanto estiver em Posição de Ataque: Uma vez por turno, você pode enviar 1 Card de Equipamento equipado a este card ao Cemitério para causar 500 de dano ao seu oponente.\r\n● Enquanto estiver em Posição de Defesa: Uma vez por turno, você pode equipar 1 monstro com a face para cima em Posição de Ataque que seu oponente controla a este card como um Card de Equipamento. \r\n(Você só pode equipar 1 monstro por vez a este card por este efeito).','\r',char(13)),'\n',char(10)),'Cause 500 de dano ao seu oponente','Equipar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48882106,'Peixe-cofre Tóxico',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro: você pode escolher 1 card em qualquer Cemitério; bana-o. \r\nSe este card for banido: você pode escolher 1 card com a face para cima que seu oponente controla; negue seus efeitos até o final deste turno. \r\nVocê só pode usar cada efeito de "Peixe-cofre Tóxico" uma vez por turno.','\r',char(13)),'\n',char(10)),'Banir','Ilimitado','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48891960,'Cavaleiro Dragunidade - Ascalon',replace(replace('1 Regulador "Dragunidade" + 1+ não-Reguladores	\r\nVocê pode banir 1 monstro "Dragunidade" do seu Cemitério e, depois, escolha 1 monstro que seu oponente controla; bana-o. \r\nSe este card Invocado por Invocação-Sincro sob o controle do seu dono for destruído por um card do oponente: você pode Invocar por Invocação-Especial 1 Monstro Sincro "Dragunidade" com 3000 ou menos de ATK do seu Deck Adicional (isso é considerado uma Invocação-Sincro). \r\nVocê só pode usar este efeito de "Cavaleiro Dragunidade - Ascalon" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48905153,'Dridente Zoodíaco',replace(replace('4 monstros de Nível 4	\r\nUma vez por turno, você também pode Invocar "Dridente Zoodíaco" por Invocação-Xyz ao usar 1 monstro "Zoodíaco(a)" que você controla com um nome diferente como matéria. \r\n(Transfira as matérias dele para este card.) \r\nGanha ATK/DEF igual ao ATK/DEF de todos os monstros "Zoodíaco(a)" associados a ele como matéria. \r\nUma vez por turno (Efeito Rápido): você pode desassociar 1 matéria deste card e, depois, escolha 1 card com a face para cima no campo; destrua-o.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Xyz sobrepondo um monstro "Zoodíaco(a)"?','Destruir 1 card','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48928529,'Número 83: Rainha da Galáxia',replace(replace('3 monstros de Nível 1	\r\nUma vez por turno: você pode desassociar 1 Matéria Xyz deste card; até a próxima Fase Final do oponente, os monstros que você atualmente controla não podem ser destruídos em batalha e, se eles atacarem um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente.','\r',char(13)),'\n',char(10)),'Habilidade adicional','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48934760,'Morte da Terra','Quando seu oponente Invocar um ou mais monstros por Invocação-Especial: ative 1 Card de Magia de Campo diretamente do seu Deck.','Escolha a Magia de Campo para ativar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48940337,'Lançaforrinco',replace(replace('Escala de Pêndulo = 7\r\n[ Efeito de Pêndulo ]\r\nSe um Monstro Normal que você controla atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nEsta espécie primordial sobreviveu à extinção ao desenvolver uma lança ofensiva que pode perfurar qualquer coisa, embora sua dieta ainda consista principalmente de peixe.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48948935,'Demônio Mascarado Des Gardius',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro deve ser Invocado por Invocação-Especial (da sua mão) ao oferecer como Tributo 2 monstros, incluindo pelo menos 1 "Grande Ancião Tiki" ou "Melchid, a Besta de Quatro Faces". \r\nSe este card for enviado do campo para o seu Cemitério: escolha 1 monstro com a face para cima que seu oponente controla; equipe 1 "A Máscara dos Remanescentes" do seu Deck a ele.','\r',char(13)),'\n',char(10)),'Equipar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48958757,'Besta Gladiadora Claudius',replace(replace('5 monstros "Besta Gladiadora"	\r\nPrimeiro deve ser Invocado por Invocação-Especial (do seu Deck Adicional) ao embaralhar no Deck/Deck Adicional os cards acima do seu campo e/ou Cemitério. \r\nSe Invocado desta forma: você pode conduzir sua próxima Fase de Batalha duas vezes. \r\nUma vez por turno, se seu oponente ativar um efeito de monstro (exceto durante a Etapa de Dano): você pode ativar o seguinte efeito dependendo de quem é o turno;\r\n● Seu: Invoque por Invocação-Especial 1 monstro "Besta Gladiadora" do seu Deck.\r\n● Do oponente: Invoque por Invocação-Especial 1 monstro "Besta Gladiadora" de Nível 11 ou menos do seu Deck Adicional, ignorando suas condições de Invocação.','\r',char(13)),'\n',char(10)),'2 Fases de Batalha','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48964966,'Atena',replace(replace('Se um ou mais outros monstros Fada forem Invocados: cause 600 de dano ao seu oponente. \r\nUma vez por turno: você pode enviar 1 monstro Fada com a face para cima que você controla para o Cemitério, exceto "Atena" e, depois, escolher 1 monstro Fada no seu Cemitério, exceto "Atena"; Invoque o alvo por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Invocação Especial','Causar dano','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48976825,'Enterro de Outra Dimensão','Escolha até 3 monstros banidos; devolva-os para o Cemitério.','Escolha o card a ser devolvido ao Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48995978,'Número 88: Engenhoca Marionete de Leão',replace(replace('3 monstros de Nível 8	\r\nUma vez por turno, se você não tiver cards na sua Zona dos Cards de Magia & Armadilha: você pode desassociar 1 Matéria Xyz deste card e, se isso acontecer, coloque 1 Marcador de Destino neste card. \r\nVocê não pode conduzir sua Fase de Batalha no turno em que ativar este efeito. \r\nQuando 3 Marcadores de Destino estiverem neste card, você vence o Duelo.','\r',char(13)),'\n',char(10)),'Colocar um marcador','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(48996569,'Neos Grandioso, o HERÓI do Elemento',replace(replace('"Neos, o HERÓI do Elemento" + "Grande Toupeira Neoespacial"	\r\nVocê primeiro deve Invocá-lo por Invocação-Especial (do seu Deck Adicional) ao embaralhar os cards acima que você controla no Deck. \r\n(Você não usa "Polimerização".) \r\nUma vez por turno: Você pode escolher 1 monstro que seu oponente controla; devolva o alvo para a mão. \r\nDurante a Fase Final: Embaralhe este card no Deck Adicional.','\r',char(13)),'\n',char(10)),'Retornar ao Deck','Retornar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49003308,'Gagagigo','Este pequeno malvado costumava ter um mau coração, mas ao conhecer uma pessoa especial, ele descobriu a justiça.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49003716,'Asanegra - Bora, a Lança',replace(replace('Se você controlar um monstro "Asanegra" que não seja "Asanegra - Bora, a Lança", você pode Invocar este card por Invocação-Especial (da sua mão). \r\nSe este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49010598,'Cólera Divina','Quando um efeito de monstro for ativado: descarte 1 card; negue a ativação e, se isso acontecer, destrua esse monstro.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49027020,'Armadilhatrix Pudica',replace(replace('Não é afetado pelos efeitos de Armadilhas Normais "Buraco". \r\nVocê só pode usar cada um dos seguintes efeitos de "Armadilhatrix Pudica" uma vez por turno. \r\nQuando este card for Invocado por Invocação-Normal: você pode adicionar 1 "Jardim Armadilhatrip" do seu Deck à sua mão. \r\nSe este card for Invocado por Invocação-Especial: você pode escolher 1 monstro Invocado por Invocação-Especial que seu oponente controla; bana-o e, além disso, durante a próxima Fase de Apoio, seu oponente pode Invocar por Invocação-Especial 1 dos monstros banidos dele.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Banir 1 monstro','Invocar por Invocação Especial 1 dos seus monstros banidos?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49032236,'Número 81: Supercouraçado Canhão de Trilho Super Dora',replace(replace('2 monstros de Nível 10	\r\nUma vez por turno (Efeito Rápido): você pode desassociar 1 matéria deste card e, depois, escolha 1 monstro com a face para cima no campo; até o final deste turno, o alvo não é afetado por efeitos de card, exceto seus próprios.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49033797,'Trapezoedro Proibido',replace(replace('Se você controlar exatamente 2 tipos de card de monstro (entre Fusão, Sincro e/ou Xyz): aplique o seguinte efeito baseado nesses tipos.\r\n● Fusão e Sincro: Invoque por Invocação-Especial 1 Monstro Xyz "Entidade Exterior" do seu Deck Adicional e, se isso acontecer, associe este card a ele como matéria.\r\n● Sincro e Xyz: Invoque por Invocação-Especial 1 Monstro de Fusão "Entidade Anciã" do seu Deck Adicional.\r\n● Xyz e Fusão: Invoque por Invocação-Especial 1 Monstro Sincro "Entidade Antiga" do seu Deck Adicional.	\r\nVocê só pode ativar 1 "Trapezoedro Proibido" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49036338,'PSÍ-Armação Condutor','Um soldado Psíquico que entra em conflito com as Forças de Segurança como ondas relâmpago, usando um amplificador autonômico chamado "PSÍ-Armação".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49064413,'Demônio Mascarado','Você pode Invocar este card por Invocação-Ritual com "A Maldição do Demônio Mascarado".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49080532,'Besouro Inférnico','Se você não tiver cards na sua mão: você pode oferecer este card como Tributo; Invoque por Invocação-Especial até 2 "Besouro Inférnico" do seu Deck.','Invocação Especial','Invocar outro monstro por Invocação Especial?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49082032,'Resurgam Xyz',replace(replace('Todos os Monstros Xyz que você controla ganham 800 de ATK. \r\nUma vez por turno: você pode descartar 1 Magia e, depois, escolha 1 Monstro Xyz que você controla; Invoque por Invocação-Especial do seu Deck Adicional, 1 monstro "Número C" ou 1 monstro "CXyz", com o mesmo Tipo que o desse monstro que você controla, mas 1 Classe maior, usando-o como matéria. \r\n(Isso é considerado uma Invocação-Xyz. Transfira as matérias dele para o monstro Invocado.) \r\nSe você descartou um card que não seja uma Magia "Magia de Aumento de Classe" para ativar este efeito, devolva esse monstro Invocado por Invocação-Especial para o Deck Adicional durante a Fase Final (mesmo que este card deixe o campo).','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49088914,'Mai-Hime do Mundo Virtual - Lulu',replace(replace('Se este card estiver na sua mão: você pode escolher 1 card "Mundo Virtual" que você controla; envie 1 card "Mundo Virtual" de um tipo diferente (Monstro, Magia, Armadilha) do seu Deck para o Cemitério e, se isso acontecer, Invoque este card por Invocação-Especial e, depois, você pode adicionar 1 card "Mundo Virtual" do terceiro tipo do seu Deck à sua mão, exceto "Mai-Hime do Mundo Virtual - Lulu". \r\nPelo resto deste turno, você só pode Invocar por Invocação-Especial monstros de Nível/Classe 3 ou mais. \r\nVocê só pode usar este efeito de "Mai-Hime do Mundo Virtual - Lulu" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial da mão','Adicionar 1 carta do seu Deck à sua mão?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49094491,'Salamagrande Fennec',replace(replace('Se um ou mais monstros Ciberso que você controla que foram Invocados por Invocação-Especial do Deck Adicional forem destruídos em batalha ou por um efeito de card do oponente: você pode Invocar este card por Invocação-Especial do Cemitério (se ele estava lá quando o monstro foi destruído) ou da mão (mesmo se ele não estava), mas bana-o quando ele deixar o campo. \r\nSe este card for enviado para o Cemitério como matéria para a Invocação-Link de um Monstro Link Ciberso de Link-2 ou mais: você pode adicionar 1 Magia Normal "Salamagrande" do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "Salamagrande Fennec" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49105782,'Hraesvelgr, a Terrível Águia da Perdição',replace(replace('2+ monstros de VENTO	\r\nGanha 2400 de ATK enquanto seu oponente não tiver monstros no Cemitério dele. \r\n(Efeito Rápido): você pode escolher 1 monstro no Cemitério do seu oponente; embaralhe-o no Deck. \r\nVocê só pode usar este efeito de "Hraesvelgr, a Terrível Águia da Perdição" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49109013,'Ulka da Destrela',replace(replace('Quando exatamente 1 monstro que você controla (e nenhum outro monstro) deixar o campo por um efeito de card do oponente (exceto durante a Etapa de Dano): você pode banir este card da sua mão ou do Cemitério; se esse monstro estiver no Cemitério ou banido com a face para cima, Invoque-o por Invocação-Especial, caso contrário, Invoque este card banido por Invocação-Especial. \r\nSe este card for Invocado por Invocação-Especial: você pode fazer com que este card ganhe 1500 de ATK até o final do próximo turno. \r\nVocê só pode usar cada efeito de "Ulka da Destrela" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49121795,'Trem de Armadura Pesada Lobo de Ferro',replace(replace('2 monstros do Tipo Máquina de Nível 4	\r\nUma vez por turno: você pode desassociar 1 Matéria Xyz deste card e, depois, escolher 1 monstro do Tipo Máquina que você controla; neste turno, ele pode atacar seu oponente diretamente e, além disso, outros monstros não podem atacar. \r\nSe este card em sua posse for destruído por um card do oponente (em batalha ou por um efeito de card) e enviado para o seu Cemitério: você pode adicionar 1 Monstro do Tipo Máquina de Nível 4 do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49127943,'Planta Devoradora de Homens','Uma planta carnívora linda de longe, mas perigosa de perto.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49131917,'Shinonome, a Sacerdotisa Vaylantz',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nDurante sua Fase Principal: você pode Invocar este card por Invocação-Especial na sua Zona de Monstros Principal em sua mesma coluna e, além disso, você não pode Invocar por Invocação-Especial monstros que não sejam "Vaylantz" pelo resto deste turno, exceto do Deck Adicional. \r\nVocê só pode usar este efeito de "Shinonome, a Sacerdotisa Vaylantz" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nDurante sua Fase Principal, se você controlar este card Invocado por Invocação-Especial: você pode adicionar 1 Magia "Vaylantz" do seu Deck à sua mão. \r\nSe este card na Zona de Monstros se mover para outra Zona de Monstros: você pode adicionar 1 monstro "Vaylantz" do seu Deck à sua mão, exceto "Shinonome, a Sacerdotisa Vaylantz". \r\nVocê só pode usar cada efeito de "Shinonome, a Sacerdotisa Vaylantz" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49139666,'Big Bang Estranho E',replace(replace('Se um monstro Invocado por Invocação-Especial do Deck Adicional estiver no campo: você pode Invocar este card por Invocação-Especial da sua mão. \r\nDurante sua Fase Principal: você pode reduzir em 1 os Níveis de todos os outros monstros no campo e, se isso acontecer, aumente o Nível deste card pelo número de monstros cujo Nível foi reduzido por este efeito. \r\nDurante sua Fase de Batalha ou a Fase Principal do seu oponente, se o Nível deste card for 8 ou mais (Efeito Rápido): você pode destruir 1 outro card no campo e, se isso acontecer, o Nível deste card se torna 5. \r\nVocê só pode usar cada efeito de "Big Bang Estranho E" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar este card por Invocação Especial','Aumentar o Nível','Destruir 1 card','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49140998,'Uma Pena da Fénix','Descarte 1 card e, depois, escolha 1 card no seu Cemitério; devolva o alvo para o topo do seu Deck.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49144107,'Coelhinho Medonho','VIRE: Cause 1000 de dano ao seu oponente para cada Monstro Normal com a face para cima que você controla, exceto Fichas.','Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49154689,'Substituir',replace(replace('Ofereça 1 monstro como Tributo e, depois, escolha 1 monstro no Cemitério do seu oponente com o mesmo Tipo e Atributo originais; Invoque-o por Invocação-Especial no seu campo. \r\nVocê só pode ativar 1 "Substituir" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49158617,'A Derrota do Mal Pelos Dois Avatares',replace(replace('Escolha 1 monstro "Dois Avatares" que você controla e 1 card que seu oponente controla; destrua-os e, depois, se você destruiu um Monstro de Fusão "Dois Avatares" que você controla com este efeito, você pode aplicar 1 desses efeitos.\r\n● Compre 1 card.\r\n● Bana 1 card do Cemitério do seu oponente.	\r\nVocê só pode ativar 1 "A Derrota do Mal Pelos Dois Avatares" por turno.','\r',char(13)),'\n',char(10)),'Compre 1 card(s)','Banir 1 card do Cemitério','Não fazer nada','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49161188,'Gilti-Gearfried, o Cavaleiro de Aço Mágico',replace(replace('2 monstros Guerreiro com Atributos diferentes	\r\nUma vez por turno, quando um card ou efeito for ativado que escolha este card como alvo (Efeito Rápido): você pode negar o efeito e, se isso acontecer, destrua 1 card no campo. \r\nSe este card foi Invocado por Invocação-Fusão usando apenas monstros no campo como matéria, ele pode realizar um segundo ataque durante cada Fase de Batalha. \r\nUma vez por turno, se este card batalhar um monstro do oponente, durante o cálculo de dano (Efeito Rápido): você pode banir 1 Magia do seu Cemitério; até o final deste turno, este card ganha ATK igual à metade da sua DEF atual.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49181828,'Dragão Armado com Punhos',replace(replace('Se este card estiver no seu Cemitério: você pode escolher 1 monstro Dragão que você controla; destrua-o e, se isso acontecer, Invoque este card por Invocação-Especial. \r\nVocê pode descartar 1 card e, depois, escolha 1 monstro no campo com 2400 ou menos de ATK; destrua-o e, depois, se você destruiu um monstro que você controla, você pode Invocar por Invocação-Especial 1 monstro Dragão da sua mão ou do Deck, cujo Nível original seja 2 a mais que o desse monstro. \r\nVocê só pode usar cada efeito de "Dragão Armado com Punhos" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49191560,'Cocheiro da Profecia','Uma vez por turno: Você pode descartar 1 Card de Magia "Livro de Magia" para escolher 1 monstro do Tipo Mago no seu Cemitério; adicione o alvo à sua mão.','Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49195710,'Número C65: Rei Suprademônio',replace(replace('3 monstros de TREVAS de Nível 3	\r\nUma vez por turno: você pode desassociar 1 Matéria Xyz deste card e, depois, escolher 1 monstro com a face para cima que seu oponente controla; ele perde 1000 de ATK e DEF. \r\nEnquanto este card tiver "Número 65: Djinn Notável" como uma Matéria Xyz, ele ganha este efeito.\r\n● Os Monstros de Efeito que seu oponente controla não podem ativar seus efeitos.','\r',char(13)),'\n',char(10)),'Reduzir ATK/DEF','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49202162,'Soldado do Lustro Negro - Soldado do Caos',replace(replace('3 monstros com nomes diferentes	\r\nSe este card foi Invocado por Invocação-Link usando um ou mais monstros de Nível 7 ou mais como matéria, seu oponente não pode escolhê-lo como alvo de efeitos de card e, além disso, ele não pode ser destruído pelos efeitos de card do seu oponente. \r\nQuando este card destruir um monstro do oponente em batalha: você pode ativar 1 desses efeitos;\r\n● Este card ganha 1500 de ATK.\r\n● Este card pode realizar um segundo ataque durante a Fase de Batalha do seu próximo turno.\r\n● Bana 1 card no campo.','\r',char(13)),'\n',char(10)),'Ativar o efeito escolhido','Aumentar ATK','Atacar duas vezes','Banir 1 card no campo','Invocação Link usando um monstro de Nível 7 ou mais como matéria','','','','','','','','','','','');
INSERT INTO texts VALUES(49202331,'CXyz Palácio Celeste Babilônia',replace(replace('3 monstros de Nível 11	\r\nQuando este card destruir um monstro em batalha e enviá-lo para o Cemitério: cause dano ao seu oponente igual à metade do ATK original do monstro destruído no Cemitério. \r\nSe este card tiver "Palácio Celeste Gangaridai" como uma Matéria Xyz, ele ganha este efeito.\r\n● Uma vez por turno, se este card destruir um monstro em batalha: você pode desassociar 1 Matéria Xyz deste card; ele pode realizar um segundo ataque em sequência.','\r',char(13)),'\n',char(10)),'Causar dano','Continuar atacando','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49204190,'Tonto Astuto','Descarte 1 monstro e, depois, escolha 1 monstro com a face para cima no campo; ele perde ATK igual ao ATK original do monstro descartado.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49217579,'Cavaleiro Miragem',replace(replace('Este card não pode ser Invocado por Invocação-Normal ou Baixado. \r\nEste card não ser pode ser Invocado, por Invocação-Especial, exceto pelo efeito de "Cavaleiro da Chama Negra". \r\nDurante o cálculo de dano, aumente o ATK deste card pelo ATK original do monstro do seu adversário. \r\nDurante a End Phase do turno em que este card realizou um combate, remova este card de jogo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49218300,'Feiticeiro dos Condenados','Um escravo das artes das trevas, este feiticeiro é um mestre nas magias letais.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49221191,'Número C32: Dragonete Tubarão Veiss',replace(replace('4 monstros de ÁGUA de Nível 4	\r\nVocê também pode Invocar este card por Invocação-Xyz ao usar "Número 32: Dragonete Tubarão" que você controla como matéria. \r\n(Transfira as matérias dele para este card.) \r\nSe seus PV forem 1000 ou menos (Efeito Rápido): você pode banir 1 monstro do seu Cemitério e desassociar 1 matéria deste card e, depois, escolha 1 monstro com a face para cima no campo; seu ATK/DEF se tornam 0 até o final do seu turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Xyz este card sobrepondo "Número 32: Dragonete Tubarão"?','Alterar ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49238328,'Pote da Extravagância',replace(replace('No começo da sua Fase Principal 1: bana, com a face para baixo, 3 ou 6 cards aleatórios com a face para baixo do seu Deck Adicional; compre 1 card para cada 3 cards banidos. \r\nPelo resto deste turno depois que este card resolver, você não pode comprar nenhum card devido a efeitos de card.','\r',char(13)),'\n',char(10)),'Ativar banindo 3 card(s)','Ativar banindo 6 card(s)','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49238329,'Pote da Extravagância',replace(replace('No começo da sua Fase Principal 1: bana, com a face para baixo, 3 ou 6 cards aleatórios com a face para baixo do seu Deck Adicional; compre 1 card para cada 3 cards banidos. \r\nPelo resto deste turno depois que este card resolver, você não pode comprar nenhum card devido a efeitos de card.','\r',char(13)),'\n',char(10)),'Ativar banindo 3 card(s)','Ativar banindo 6 card(s)','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49249907,'Yosenju Magat',replace(replace('Se este card for Invocado por Invocação-Normal: você pode Invocar por Invocação-Especial 1 monstro "Yosenju" do seu Deck, exceto "Yosenju Magat". \r\nDurante a Fase Final, se este card foi Invocado por Invocação-Especial neste turno: devolva-o para a mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49251811,'Sonda Mística',replace(replace('Você pode ativar este card quando um Card de Magia Contínua for ativado. \r\nNegue os efeitos de todos os Cards de Magia Contínua durante o turno em que este card for ativado.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49258578,'Portão Deeg','Este monstro estranho tem um portal na barriga que chama reforços dos cantos mais profundos do mundo inferior.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49267971,'Vulnerabilidade sob Ataque',replace(replace('Selecione 1 monstro com a face para cima em Posição de Defesa que seu oponente controla e 1 monstro com a face para cima em Posição de Ataque que você controla. \r\nO monstro que você controla ganha ATK igual à DEF do monstro do oponente até a Fase Final.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49275969,'Nidhogg, Chefe Generaidor do Gelo',replace(replace('Você só pode controlar 1 "Nidhogg, Chefe Generaidor do Gelo". \r\nQuando seu oponente Invocaria por Invocação-Especial um ou mais monstros (Efeito Rápido): você pode oferecer como Tributo 1 monstro "Generaidor" ou 1 monstro Wyrm; negue a Invocação e, se isso acontecer, destrua esses monstros. \r\nVocê só pode usar este efeito de "Nidhogg, Chefe Generaidor do Gelo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49296203,'Karakuri Bonzo mdl 9763 "Kunamzan"',replace(replace('Este card deve atacar, se possível. \r\nSe este card for escolhido como alvo de um ataque: mude a posição de batalha deste card. \r\nSe este card estiver na sua mão: você pode escolher 1 monstro "Karakuri" que você controla; mude sua posição de batalha e, se isso acontecer, Invoque este card por Invocação-Especial como um Regulador e, além disso, você não pode Invocar monstros por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto monstros Máquina de TERRA. \r\nVocê só pode usar este efeito de "Karakuri Bonzo mdl 9763 "Kunamzan"" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49299410,'A Cabra Negra Ri',replace(replace('Declare 1 nome de Card de Monstro; neste turno, nenhum duelista pode Invocar monstros com esse nome original por Invocação-Especial, exceto do Cemitério. \r\nVocê pode banir este card do Cemitério e, depois, declare 1 nome de Card de Monstro; neste turno, nenhum duelista pode ativar os efeitos de monstros no campo com esse nome original. \r\nVocê só pode usar 1 efeito de "A Cabra Negra Ri" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49306994,'Véu Branco',replace(replace('Enquanto o monstro equipado batalhar, seu oponente não pode ativar quaisquer Cards de Magia/Armadilha até o final da Etapa de Dano. \r\nQuando um ataque for declarado envolvendo o monstro equipado: Cards de Magia/Armadilha com a face para cima que seu oponente controla têm seus efeitos negados até o final da Etapa de Dano (mesmo que este card deixe o campo). \r\nQuando o monstro equipado destruir um monstro do oponente em batalha: você pode destruir todos os Cards de Magia e Armadilha que seu oponente controla. \r\nQuando este card com a face para cima na Zona de Magias & Armadilhas de um duelista deixar o campo, esse duelista sofre 3000 de dano.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49328340,'Ataque da Lança em Espiral',replace(replace('Se "Gaia, o Cavaleiro Impetuoso", "Gaia, o Cavaleiro Impetuoso Célere" ou "Gaia, o Matador de Dragões" que você controla atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente. \r\nSe "Gaia, o Matador de Dragões" causar dano de batalha com este efeito: compre 2 cards e, depois, descarte 1 card.','\r',char(13)),'\n',char(10)),'Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49352945,'Neos Tempestade, o HERÓI do Elemento',replace(replace('"Neos, o HERÓI do Elemento" + "Beija-flor do Ar Neoespacial" + "Golfinho Aqua Neoespacial"	\r\nPrimeiro deve ser Invocado por Invocação-Especial (do seu Deck Adicional) ao embaralhar os cards acima que você controla no Deck. \r\n(Você não usa "Polimerização".) \r\nUma vez por turno: Você pode destruir todos os Cards de Magia e Armadilha no campo. \r\nDurante a Fase Final: Embaralhe este card no Deck Adicional. \r\nQuando este card for embaralhado no Deck Adicional desta forma: Embaralhe todos os cards do campo no Deck.','\r',char(13)),'\n',char(10)),'Retornar ao Deck','Destruir Magias/Armadilhas','Retornar ao Deck','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49366157,'Ciclone Majespectro','Ofereça como Tributo 1 monstro Mago de VENTO e, depois, escolha 1 monstro que seu oponente controla; destrua-o.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49370016,'Sessão Extrema P.U.N.K. JAM',replace(replace('Uma vez por turno: você pode banir 1 card "P.U.N.K." do seu Cemitério; Invoque por Invocação-Especial 1 monstro "P.U.N.K." da sua mão. \r\nSe um monstro Psíquico que você controla pagou PV para ativar seu efeito: você pode comprar 1 card. \r\nVocê pode usar este efeito de "Sessão Extrema P.U.N.K. JAM" duas vezes por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49370026,'Guênim','Uma criatura que derrota seus inimigos utilizando trapaças.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49374988,'Magidoce Buurdo',replace(replace('Se este card em sua posse for destruído por um card do seu oponente (seja em batalha ou por um efeito de card) e enviado para o seu Cemitério: embaralhe este card no seu Deck. \r\nUma vez por turno: você pode escolher 1 monstro "Magidoce" em Posição de Ataque que você controla e 1 monstro com a face para cima em Posição de Ataque que seu oponente controla; se os dois monstros ainda estiverem no campo, coloque-os com a face para cima em Posição de Defesa e, se isso acontecer, os que tiveram suas posições de batalha mudadas por este efeito não podem ter suas posições de batalha mudadas até o final do próximo turno do seu oponente.','\r',char(13)),'\n',char(10)),'Retornar ao Deck','Mudar para Posição de Defesa com a face para cima','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49375719,'Cibertutu','Se o ATK de cada monstro que seu oponente controla for maior que o deste card, este card pode atacar diretamente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49389190,'Ikelos, a Fadinha do Espelho Onírico',replace(replace('Se este card for Invocado por Invocação-Especial pelo efeito de um monstro "Espelho Onírico": você pode adicionar 1 card "Espelho Onírico" do seu Deck à sua mão, exceto "Ikelos, a Fadinha do Espelho Onírico". \r\nDurante a Fase Principal ou de Batalha, se "Espelho Onírico do Terror" estiver em uma Zona do Campo (Efeito Rápido): você pode oferecer este card como Tributo; Invoque por Invocação-Especial 1 "Ikelos, a Moura do Espelho Onírico" do seu Deck. \r\nVocê só pode usar cada efeito de "Ikelos, a Fadinha do Espelho Onírico" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49389523,'Tricórnio Relâmpago',replace(replace('1 Regulador + 1 ou mais monstros do Tipo Besta não-Reguladores	\r\nSe este card for destruído por um card do seu oponente (seja em batalha ou por um efeito de card), você pode selecionar 1 "Unicórnio do Trovão" ou "Bicórnio Voltaico" no seu Cemitério e Invocá-lo por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49394035,'Núcleo Vendorror',replace(replace('Se este card estiver no seu Cemitério: você pode banir 1 outro monstro Zumbi do seu Cemitério; Invoque este card por Invocação-Especial, mas bana-o quando ele deixar o campo. \r\nUm monstro "Vendorror" Invocado por Invocação-Ritual usando este card no campo ganha o seguinte efeito. \r\nVocê só pode usar cada um dos efeitos anteriores de "Núcleo Vendorror" uma vez por turno.\r\n● Seu oponente não pode escolher este card como alvo de efeitos de card.','\r',char(13)),'\n',char(10)),'','O efeito de "Núcleo Vendorror" está sendo aplicado.','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49398568,'Magia em Série',replace(replace('Você pode activar este card apenas quando você activa um Card de Magia Normal. \r\nDescarte todos os cards na sua mão para o Cemitério. \r\nO efeito deste card torna-se o mesmo que o Card de Magia Normal.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49407319,'Mina de Estrelas',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nVocê só pode Invocar um ou mais "Mina de Estrelas" por Invocação-Especial uma vez por turno. \r\nSe este card em posse do seu dono for destruído por um ataque ou efeito de card do oponente: sofra 2000 de dano e, depois, cause 2000 de dano ao seu oponente. \r\nSe um monstro em uma zona adjacente a este card for destruído por um ataque ou efeito de card do seu oponente: destrua este card e, se isso acontecer, sofra 2000 de dano e, depois, cause 2000 de dano ao seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49415281,'Emergência Sincro',replace(replace('Você só pode ativar 1 "Emergência Sincro" por turno. \r\nSe somente seu oponente controlar um monstro, você pode ativar este card da sua mão.\r\nVocê não pode Invocar por Invocação-Especial do seu Deck Adicional até o fim do seu próximo turno após ativar este card, exceto Monstros Sincro, também Invoque por Invocação-Especial 1 monstro da sua mão (mas seus efeitos são negados), então, se seu oponente controlar um monstro que foi Invocado por Invocação-Especial do seu Deck Adiciona, você pode Invocar por Invocação-Especial 1 monstro "Sincron" do seu Deck.\r\nVocê pode banir este card do seu Cemitério; imediatamente após resolver este efeito, Invoque por Invocação-Sincro 1 Monstro Sincro usando monstros que você controla.','\r',char(13)),'\n',char(10)),'Invocação Especial','Invocação Sincro','Invocar por Invocação Especial novamente?','Ativar aplicando o efeito de "Emergência Sincro".','O efeito de "Emergência Sincro" está sendo aplicado.','','','','','','','','','','','');
INSERT INTO texts VALUES(49415282,'Emergência Sincro',replace(replace('Você só pode ativar 1 "Emergência Sincro" por turno. \r\nSe somente seu oponente controlar um monstro, você pode ativar este card da sua mão.\r\nVocê não pode Invocar por Invocação-Especial do seu Deck Adicional até o fim do seu próximo turno após ativar este card, exceto Monstros Sincro, também Invoque por Invocação-Especial 1 monstro da sua mão (mas seus efeitos são negados), então, se seu oponente controlar um monstro que foi Invocado por Invocação-Especial do seu Deck Adiciona, você pode Invocar por Invocação-Especial 1 monstro "Sincron" do seu Deck.\r\nVocê pode banir este card do seu Cemitério; imediatamente após resolver este efeito, Invoque por Invocação-Sincro 1 Monstro Sincro usando monstros que você controla.','\r',char(13)),'\n',char(10)),'Invocação Especial','Invocação Sincro','Invocar por Invocação Especial novamente?','Ativar aplicando o efeito de "Emergência Sincro".','O efeito de "Emergência Sincro" está sendo aplicado.','','','','','','','','','','','');
INSERT INTO texts VALUES(49417509,'Lobo','Esse lobo alfa alpha usa o cheiro para encontrar o inimigo. Eiii, sai de perto das minhas meias!','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49430782,'Herança do Verdadeiro Draco',replace(replace('Durante sua Fase Principal: você pode comprar cards igual ao número de tipos de card (Monstro, Magia e Armadilha) "Verdadeiro(a) Draco" e "Verdadeiro Rei" enviados do campo para o Cemitério neste turno. \r\nDurante sua Fase Principal, você pode: imediatamente depois que este efeito resolver, Invocar por Invocação-Tributo com a face para cima 1 monstro "Verdadeiro(a) Draco" ou "Verdadeiro Rei". \r\nSe este card for enviado da Zona de Magias & Armadilhas para o Cemitério: você pode escolher 1 Magia/Armadilha no campo; destrua-a. \r\nVocê só pode usar cada efeito de "Herança do Verdadeiro Draco" uma vez por turno.','\r',char(13)),'\n',char(10)),'Comprar','Invocação Tributo','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49441499,'Inseto Supremo LV1',replace(replace('Este card no seu Campo, com a face para cima, não é afetado por qualquer Card de Magia. \r\nDurante as Standby Phases do seu turno, envie este card, com a face para cima, para o Cemitério para Invocar, por Invocação-Especial, o "Inseto Supremo LV3" da sua mão ou do seu Deck (exepto no turno em que este card é Invocado por Invocação-Normal, Invocação-Especial ou virado com a face para cima).','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49451215,'Ukanomitsune-no-Onari',replace(replace('2 monstros de LUZ, incluindo um monstro Besta	\r\nSeu oponente não pode escolher cards nas Zonas do Campo como alvo de efeitos de card. \r\nVocê só pode usar cada um dos seguintes efeitos de "Ukanomitsune-no-Onari" uma vez por turno. \r\nSe este card for Invocado por Invocação-Link: você pode escolher 1 Magia Rápida no seu Cemitério; Baixe-a. \r\nSe este card for destruído: para cada card em uma Zona do Campo, você pode aplicar 1 desses efeitos. \r\n(Se forem os dois, aplique-os em sequência.)\r\n● Destrua 1 card que seu oponente controla.\r\n● Cause 1500 de dano ao seu oponente.','\r',char(13)),'\n',char(10)),'Baixar','Destruir 1 card que seu oponente controla','Cause 1500 de dano ao seu oponente','Aplicar ambos efeitos','','','','','','','','','','','','');
INSERT INTO texts VALUES(49456901,'Número C104: Terror Umbral Mascarado',replace(replace('4 monstros de Nível 5	\r\nQuando este card for Invocado por Invocação-Especial: você pode escolher 1 Magia/Armadilha no campo; destrua o alvo. \r\nSe este card tiver "Número 104: Mascarado" como matéria, ele ganha este efeito.\r\n● Uma vez por turno, quando um efeito de monstro for ativado no campo do seu oponente (Efeito Rápido): você pode desassociar 1 matéria deste card; negue a ativação e, depois, você pode enviar 1 card aleatório da mão do seu oponente para o Cemitério e, se isso acontecer, diminua pela metade os PV do seu oponente.','\r',char(13)),'\n',char(10)),'Destruir','Negar o efeito','Enviar 1 card aleatório da mão do seu oponente para o Cemitério e reduzir os PV dele pela metade?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49460512,'Asanegra - Kogarashi, o Andarilho',replace(replace('Quando um monstro "Asanegra" com a face para cima que você controla for destruído por um efeito de card e enviado para o Cemitério (exceto durante a Etapa de Dano): você pode Invocar este card por invocação-Especial da sua mão. \r\nQuando um monstro for Invocado por Invocação-Sincro usando este card como uma Matéria Sincro, o oponente do dono deste card não pode ativar cards ou efeitos.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49469105,'Revogar Fusão',replace(replace('Descarte 1 "Polimerização" para o Cemitério. \r\nEnvie 1 Monstro de Fusão do seu Deck Adicional para o seu Cemitério e Invoque por Invocação-Especial 1 monstro da sua mão que esteja listado como um Monstro-Matéria de Fusão nesse card. \r\nO monstro Invocado por Invocação-Especial é enviado para o Cemitério durante a Fase Final deste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49477180,'Striges Vendorror',replace(replace('Se este card for enviado para o Cemitério: você pode revelar 1 card "Vendorror" na sua mão; Invoque este card por Invocação-Especial, mas bana-o quando ele deixar o campo. \r\nUm monstro "Vendorror" Invocado por Invocação-Ritual usando este card no campo ganha o seguinte efeito. \r\nVocê só pode usar cada um dos efeitos anteriores de "Striges Vendorror" uma vez por turno.\r\n● Depois do cálculo de dano, se este card batalhou um monstro do oponente: você pode comprar 1 card e, depois, descartar 1 card.','\r',char(13)),'\n',char(10)),'','','O efeito de "Striges Vendorror" está sendo aplicado.','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49479374,'Carregador Rápido','Adicione 2 monstros "Homem-Bateria" de Nível 4 ou menos do seu Cemitério à sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49511705,'Ataque Explosão de Laser',replace(replace('Uma vez por turno, se um efeito de card ativado lançar moedas, imediatamente depois que ele resolver, aplique o(s) seguinte(s) efeito(s), dependendo do número de caras.\r\n● 1+: Cause 500 de dano ao seu oponente.\r\n● 2+: Destrua 1 card que seu oponente controla.\r\n● 3+: Olhe a mão do seu oponente e descarte 1 card da mão dele.	\r\nQuando um efeito for ativado que lance uma moeda 2 ou mais vezes: você pode banir este card do Cemitério; considere todos os resultados como caras.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49513164,'Raidjin, o Invokado',replace(replace('"Aleister, Aquele que Invoka" + 1 monstro de VENTO	\r\nUma vez por turno (Efeito Rápido): você pode escolher 1 monstro com a face para cima no campo; coloque-o com a face para baixo em Posição de Defesa.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49514333,'Alma Tiki',replace(replace('Invoque este card por Invocação-Especial como um Monstro de Efeito (Tipo Rocha/LUZ/Nível 4/ATK 1000/DEF 1800).	\r\n(Este card ainda é considerado um Card de Armadilha.) \r\nEnquanto este card for um Monstro de Efeito, se outro Card de Armadilha que você controla que seja um monstro seria destruído por um card do oponente (seja em batalha ou por um efeito de card) e enviado para o seu Cemitério, em vez disso, você pode Baixá-lo na Zona dos Cards de Magia e Armadilha.','\r',char(13)),'\n',char(10)),'Usar o efeito de "Alma Tiki"?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49522489,'Belz Sapo','Este card ganha 300 de ATK para cada "T.A.D.P.O.L.E." no seu Cemitério.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49551909,'Espada Heroica da Retribuição',replace(replace('Escolha 1 monstro "Heroico(a)" com a face para cima que você controla; equipe este card ao alvo. \r\nTodo dano de batalha que você sofrer de batalhas envolvendo o monstro equipado também é causado ao seu oponente. \r\nDepois do cálculo de dano: destrua qualquer monstro do oponente que batalhar com o monstro equipado.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49563947,'Neo Aqua Madoor','A imagem real de um mago que reina as águas. Defende-se com uma enorme parede feita a partir de um gelo que se diz ser inquebrável.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49565413,'Besta do Caos',replace(replace('1 Regulador de LUZ + 1+ monstros não-Reguladores de TREVAS	\r\nSe quaisquer cards foram banidos neste turno, este card ganha 1000 de ATK. \r\nVocê só pode usar cada um dos seguintes efeitos de "Besta do Caos" uma vez por turno. \r\nVocê pode escolher 1 dos seus monstros de LUZ ou de TREVAS banidos; adicione-o à sua mão. \r\nDurante sua Fase Principal, exceto no turno em que este card foi enviado para o Cemitério: você pode banir 1 monstro de LUZ e 1 de TREVAS da sua mão e/ou do Cemitério, exceto este card; Invoque este card por Invocação-Especial do seu Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49568943,'Mundo Vaylantz - Shinra Bansho',replace(replace('Quando este card for ativado: coloque 1 Magia de Campo "Vaylantz" do seu Deck com a face para cima na Zona do Campo do seu oponente, exceto "Mundo Vaylantz - Shinra Bansho". \r\nSe houver 2 cards nas Zonas do Campo: o duelista do turno pode escolher 1 Card de Monstro na sua própria Zona de Magias & Armadilhas; ele Invoca esse card por Invocação-Especial na sua própria Zona de Monstros Principal em sua mesma coluna. \r\nO duelista do turno só pode usar este efeito de "Mundo Vaylantz - Shinra Bansho" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49575521,'Dragãozela Laravidae',replace(replace('Não pode ser destruído por efeitos de card enquanto você controlar um Monstro de Fusão. \r\nVocê só pode usar cada um dos seguintes efeitos de "Dragãozela Laravidae" uma vez por turno.\r\n● Você pode descartar este card e, depois, escolha 1 monstro em qualquer Cemitério; embaralhe-o no Deck.\r\n● No final da Fase de Batalha: você pode devolver este card para a mão e, se isso acontecer, Invoque por Invocação-Especial 1 monstro "Dragãozela" de Nível 2 da sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49587034,'Espada Força da Luz',replace(replace('Bana, com a face para baixo, 1 card aleatório da mão do seu oponente. \r\nDurante a 4ª Fase de Apoio do seu oponente depois da ativação deste card, devolva esse card para a mão dele.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49587396,'Ferramenta Antiga','Uma máquina destruidora descoberta nas Ruínas dos Antigos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49597193,'Cavaleiro-Gema Topázio',replace(replace('"Cavaleiro-Gema Turmalina" + 1 monstro "Cavaleiro-Gema"	\r\nPrimeiro deve ser Invocado por Invocação-Fusão com as Matérias de Fusão acima. \r\nPode realizar um segundo ataque durante cada Fase de Batalha. \r\nSe este card destruir um monstro em batalha e enviá-lo para o Cemitério: cause dano ao seu oponente igual ao ATK original desse monstro.','\r',char(13)),'\n',char(10)),'Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49600724,'Fissura para Diversas Dimensões',replace(replace('Declare 1 Atributo e selecione um total de 2 monstros com esse Atributo dos Cemitérios. \r\nRemova esses monstros de jogo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49604192,'Tempestade de Mitsurugi',replace(replace('Se você tiver uma Magia de Ritual "Mitsurugi" no seu Cemitério: ofereça como Tributo 3 monstros cujos nomes originais sejam "Ame no Murakumo no Mitsurugi", "Futsu no Mitama no Mitsurugi" e "Ame no Habakiri no Mitsurugi"; faça com que seu oponente bana exatamente 8 cards da mão, do Deck Adicional, do campo e/ou do Cemitério dele. \r\nVocê só pode ativar 1 "Tempestade de Mitsurugi" por turno.','\r',char(13)),'\n',char(10)),'Ativar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49633574,'Oltro Mitológico','Uma vez por turno: você pode enviar 1 card da sua mão para o Cemitério; Invoque por Invocação-Especial 1 monstro "Mitológico(a)" de Nível 3 da sua mão.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49645921,'Besouro-Sabre','Durante uma batalha entre este card atacante e um monstro em Posição de Defesa cuja DEF seja menor que o ATK deste card, cause a diferença como Dano de Batalha ao seu oponente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49652661,'Auditoria do Arsenal',replace(replace('Envie até 2 Magias de Equipamento com nomes diferentes do seu Deck para o Cemitério. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 monstro com a face para cima que você controla; equipe-o com até 2 Magias de Equipamento com nomes diferentes da sua mão e/ou do Cemitério que podem ser equipadas a ele, mas qualquer dano de batalha que ele causar ao seu oponente é diminuído pela metade enquanto equipado com um card por este efeito. \r\nVocê só pode usar 1 efeito de "Auditoria do Arsenal" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar','Equipar','Reduza pela metade o dano de batalha envolvendo o monstro equipado','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49655592,'F.A. Whip Crosser',replace(replace('Ganha ATK igual ao seu próprio Nível x 300. \r\nSeu oponente deve pagar 300 PV para ativar o efeito de um monstro cujo Nível/Classe original seja menor que o Nível deste card. \r\nSempre que um Card ou efeito de Magia/Armadilha "F.A." for ativado: você pode aumentar em 1 o Nível deste card. \r\nSe este card for de Nível 7 ou mais, seu oponente não pode descartar ou enviar cards da mão dele para o Cemitério para ativar efeitos de card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49658464,'Obstruir Dígitos',replace(replace('Durante o cálculo de dano, se um monstro batalhar enquanto um monstro com 1000 ou mais de ATK estiver no campo: o ATK de todos os monstros atualmente no campo é reduzido em 1000 para cada 1000 de ATK que eles tiverem e, além disso, suas DEF são reduzidas em 1000 para cada 1000 de DEF que eles tiverem. \r\nSe este card for destruído: até o final deste turno, aplique os ajustes de ATK/DEF acima a todos os monstros atualmente no campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49669730,'Risco Aquático',replace(replace('Uma vez por turno: você pode Invocar por Invocação-Especial 1 monstro de ÁGUA de Nível 4 ou menos da sua mão. \r\nVocê não pode controlar nenhum monstro para ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49674183,'Anjo Caído das Rosas','Você pode Invocar este card por Invocação-Especial (da sua mão) ao devolver 1 monstro Planta que você controla para a mão, exceto "Anjo Caído das Rosas", mas bana-o quando ele deixar o campo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49678559,'Número 102: Sentinela Serafim Estelar',replace(replace('3 monstros de LUZ de Nível 4	\r\nUma vez por turno: você pode desassociar 1 Matéria Xyz deste card e, depois, escolher 1 monstro com a face para cima que seu oponente controla; diminua o ATK dele pela metade e, além disso, negue os efeitos dele. \r\nSe este card com a face para cima no campo seria destruído, em vez disso, você pode desassociar todas as Matérias Xyz dele. \r\nSe isso acontecer, qualquer dano de batalha que você sofrer neste turno é diminuído pela metade.','\r',char(13)),'\n',char(10)),'Negar o efeito','Usar o efeito de "Número 102: Sentinela Serafim Estelar" em vez de ser destruído?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49680980,'João Pestana Koa''ki Meiru',replace(replace('Durante cada uma das suas Fases Finais, destrua este card a não ser que você envie 1 "Núcleo de Ferro de Koa''ki Meiru" da sua mão para o Cemitério ou revele 1 monstro Rocha da sua mão. \r\nQuando seu oponente ativar um Card de Armadilha (Efeito Rápido): você pode oferecer este card como Tributo; negue a ativação e, se isso acontecer, destrua esse card.','\r',char(13)),'\n',char(10)),'Escolha 1 "Núcleo de Ferro de Koa''ki Meiru" para enviar para o Cemitério','Revelar ao oponente 1 monstro Rocha','Destruir "João Pestana Koa''ki Meiru"','Negue a ativação de uma Armadilha e a destrua','','','','','','','','','','','','');
INSERT INTO texts VALUES(49681811,'Freed, o General sem Igual',replace(replace('Negue qualquer efeito de Magia que escolha este card no campo como alvo quando ele resolver e, se isso acontecer, destrua esse card. \r\nDurante sua Fase de Compra, em vez de conduzir sua compra normal: você pode adicionar 1 monstro Guerreiro de Nível 4 ou menos do seu Deck à sua mão. \r\nEste card deve estar com a face para cima no campo para ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49684352,'Mago de Duas Íris',replace(replace('Escala de Pêndulo = 8\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno: você pode escolher 1 monstro de TREVAS do Tipo Mago que você controla; aplique este efeito a ele e, depois, destrua este card. \r\nDepois de aplicado, dobre qualquer dano de batalha que esse monstro causar ao seu oponente neste turno se ele batalhou um monstro do oponente.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\n(Este card deve ser sempre considerado como um card "Dragão Pêndulo".)	\r\nSe este card for destruído em batalha ou por um efeito de card: você pode adicionar 1 card "Pêndulografo(a)" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49689480,'Rainha Magidoce Tiarafraise',replace(replace('3 monstros "Magidoce" de Nível 5	\r\nUma vez por turno, você também pode Invocar "Rainha Magidoce Tiarafraise" por Invocação-Xyz ao usar "Rainha Magidoce Tiaramisu" que você controla. \r\n(Transfira as matérias dele para este card.) \r\nUma vez por turno do oponente (Efeito Rápido): você pode desassociar 1 matéria deste card e, depois, escolha até 2 cards "Magidoce" no seu Cemitério; embaralhe-os no Deck e, além disso, embaralhe no Deck até o mesmo número de cards que seu oponente controla. \r\nSe este card em sua posse for destruído por um card do oponente e enviado para o seu Cemitério: devolva este card para o Deck Adicional.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Xyz sobrepondo este card no seu "Rainha Magidoce Tiaramisu"?','Retornar ao Deck','Retornar ao Deck Adicional','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49702428,'Ataque Ardente das Trevas','Se você controlar um monstro "Pequena Maga Negra": destrua todos os monstros com a face para cima que o seu oponente controla.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49721684,'Espelho de Mitsurugi',replace(replace('Este card pode ser usado para a Invocação-Ritual de qualquer Monstro de Ritual Réptil da sua mão ou do Cemitério. \r\nVocê também deve oferecer como Tributo monstros Réptil da sua mão ou do campo cuja soma dos Níveis seja igual ou exceda o Nível do Monstro de Ritual. \r\nSe "Ame no Murakumo no Mitsurugi", "Futsu no Mitama no Mitsurugi" ou "Ame no Habakiri no Mitsurugi" que você controla for oferecido como Tributo, enquanto este card estiver no seu Cemitério: você pode embaralhar este card no Deck. \r\nVocê só pode usar cada efeito de "Espelho de Mitsurugi" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Ritual','Retornar ao Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49721904,'Seis Samurai Lendários - Kizan',replace(replace('Se você controlar um monstro "Seis Samurai" com um nome diferente, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nEnquanto você controlar 2 ou mais outros monstros "Seis Samurai", este card ganha 300 de ATK/DEF.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49725936,'Dragão das Três Explosões',replace(replace('2+ monstros, exceto Fichas	\r\nUma vez por turno, durante a Etapa de Dano, quando um Card de Magia/Armadilha ou efeito de monstro for ativado (Efeito Rápido): você pode negar a ativação. \r\nSe este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante. \r\nDurante sua Fase Principal, exceto no turno em que este card foi Invocado por Invocação-Especial: você pode oferecer este card como Tributo e, depois, escolha 1 monstro de Link-2 ou menos no seu Cemitério; Invoque-o por Invocação-Especial e, depois, você pode Invocar por Invocação-Especial 1 monstro Dragão de Nível 4 ou menos da sua mão.','\r',char(13)),'\n',char(10)),'','','Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49729312,'Primineral Kongrande',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial por um efeito de card. \r\nSe um monstro for enviado da mão ou do Deck do seu oponente para o Cemitério (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão com a face para baixo em Posição de Defesa. \r\nSe este card for virado com a face para cima: você pode escolher até 2 cards no campo; destrua-os.','\r',char(13)),'\n',char(10)),'Invocar este card por Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49752795,'Retorno dos Dois Avatares',replace(replace('Escolha 1 monstro "Dois Avatares" no seu Cemitério; Invoque-o por Invocação-Especial e, depois, se seu Nível original era 4 ou menos, você pode Invocar por Invocação-Especial 1 "Ficha do Espírito dos Dois Avatares" (Guerreiro/LUZ/Nível 2/ATK 0/DEF 0). \r\nVocê só pode ativar 1 "Retorno dos Dois Avatares" por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial uma Ficha?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49752796,'Ficha do Espírito dos Dois Avatares','Invocado por Especial com o efeito "Convite dos Dois Avatares" ou um card relacionado.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49771608,'Criança Absorvedora do Céu','Quando este card destrói um monstro como resultado de um combate e o envia para o Cemitério, aumente os seus Life Points num valor igual ao Nível do monstro destruído x 300 pontos.','Ganhar PV','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49776811,'Piecephilia Brilhante',replace(replace('Não pode ser destruído em batalha. \r\nNo final da Etapa de Dano, se este card batalhou um monstro do oponente: você pode colocar 1 Marcador de Piece neste card (máx. 4) e, depois, você pode aplicar o seguinte efeito, de acordo com o número de Marcadores de Piece nele.\r\n● 1: Coloque 1 monstro do seu Deck no topo do seu Deck.\r\n● 2: Compre 1 card.\r\n● 3: Adicione 1 monstro do seu Deck à sua mão.\r\n● 4: Adicione 1 card do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Escolher 1 monstro do seu Deck e colocá-lo no topo do Deck?','Comprar 1 card do seu Deck?','Adicionar 1 monstro do seu Deck à sua mão?','Adicionar 1 card do seu Deck à sua mão?','Escolher o monstro para colocar no topo do Deck','','','','','','','','','','','');
INSERT INTO texts VALUES(49785720,'Irmandade do Punho de Fogo - Coiote','Se você controlar uma Magia/Armadilha "Formação de Fogo" e nenhum monstro, você pode Invocar este card por Invocação-Especial (da sua mão).','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49791927,'Tigre do Machado','Uma besta guerreira veloz e poderosa que brande um machado.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49791928,'Tigre do Machado','Uma besta guerreira veloz e poderosa que brande um machado.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49808196,'Metabo Globster',replace(replace('Quando você oferecer este card como Tributo para a Invocação-Tributo de um monstro de TREVAS, Invoque por Invocação-Especial 3 "Fichas de Metabo" (Tipo Demônio/TREVAS/Nível 1/ATK 0/DEF 0) em Posição de Defesa. \r\nEssas Fichas não podem ser oferecidas como Tributo para uma Invocação-Tributo.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49808197,'Ficha de Metabo','Invocado por Especial com o efeito "Metabo Globster". Esta Ficha não pode ser oferecida como Tributo para uma Invocação-Tributo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49814180,'Mestre Monge',replace(replace('Este card não pode ser Invocado, por Invocação-Normal, ou Baixado. \r\nEste card não pode ser Invocado, por Invocação-Especial, exceto oferecendo como Tributo 1 "Monge Lutador" no seu Campo. \r\nEste card pode atacar duas vezes durante o mesmo turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49816630,'Gaiarmadura Couraça de Dragão',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nVocê pode oferecer este card como Tributo e, depois, escolha 3 outros Monstros Sincro no seu Cemitério; devolva-os para o Deck Adicional. \r\nVocê pode escolher 1 monstro que você controla Invocado por Invocação-Especial do Deck Adicional; equipe este card do seu Cemitério a ele. \r\nQuando um ataque for declarado envolvendo o monstro equipado com este card: você pode comprar 1 card. \r\nVocê só pode usar cada efeito de "Gaiarmadura Couraça de Dragão" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49820233,'Camarartista Metracarniçal',replace(replace('1 monstro "Camarartista" + 1 monstro de TREVAS de Nível 5 ou mais	\r\nSe este card for Invocado por Invocação-Fusão: você pode causar 200 de dano ao seu oponente para cada card no campo e, depois, se este card foi Invocado por Invocação-Fusão usando um Monstro Pêndulo como matéria, destrua 1 monstro que seu oponente controla e, se isso acontecer, cause dano ao seu oponente igual ao ATK original desse monstro. \r\nVocê só pode usar este efeito de "Camarartista Metracarniçal" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49823708,'Filhote Notável do Soldado da Espada da Destruição',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode adicionar 1 card "Espada da Destruição" do seu Deck à sua mão, exceto "Filhote Notável do Soldado da Espada da Destruição". \r\nVocê só pode usar 1 dos seguintes efeitos de "Filhote Notável do Soldado da Espada da Destruição" por turno e apenas uma vez por turno.\r\n● Você pode oferecer este card como Tributo; Invoque por Invocação-Especial 1 "Blader Notável" da sua mão ou do Cemitério.\r\n● Se este card estiver no seu Cemitério e você controlar "Blader Notável": você pode descartar 1 card "Espada da Destruição"; Invoque este card por Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49826746,'Feiticeira Asa da Noite','Você pode ativar "Ativar Modo de Ataque" no turno em que ele for Baixado.','Ativar aplicando o efeito de "Feiticeira Asa da Noite".','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49828011,'Oficiante Reverie',replace(replace('Se este card estiver na sua mão: você pode descartar 1 outro card; Invoque este card por Invocação-Especial. \r\nSe um ou mais Monstros Xyz forem enviados para o Cemitério, enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode banir este card; Invoque por Invocação-Especial 1 monstro Zumbi do seu Cemitério. \r\nDurante a Fase de Apoio do próximo turno depois que este card foi banido: você pode escolher 1 Monstro Xyz Zumbi que você controla; associe este card banido a ele. \r\nVocê só pode usar cada efeito de "Oficiante Reverie" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Invocar por Invocação Especial do Cemitério','Como Matéria Xyz','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49833312,'Morfotrônicos, atacar!',replace(replace('Só pode ser ativado quando seu oponente declarar um ataque direto enquanto você não controlar nenhum monstro. \r\nNegue o ataque e Invoque por Invocação-Especial 1 monstro "Morfotrônico(a)" da sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49838105,'Tobogã Silvestre',replace(replace('Sempre que um monstro do oponente declarar um ataque direto: você pode escavar o card do topo do seu Deck e, se ele for um monstro do Tipo Planta, envie-o para o Cemitério. \r\nCaso contrário, coloque-o no fundo do seu Deck. \r\nDurante sua Fase de Compra, em vez de conduzir sua compra normal: escave o card do topo do seu Deck e, se ele for um monstro do Tipo Planta, envie-o para o Cemitério. \r\nCaso contrário, adicione-o à sua mão.','\r',char(13)),'\n',char(10)),'Escave cards do seu Deck','Substituição de compra','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49847524,'Administrador das Chamas',replace(replace('2 monstros Ciberso	\r\nTodos os Monstros Link que você controla ganham 800 de ATK. \r\nVocê só pode controlar 1 "Administrador das Chamas".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49858495,'Irmãs Lady Power Pro',replace(replace('Essas três garotas Power Pro são melhores amigas! E sua paixão pelo beisebol paira como um home run!	\r\n\r\nAoi Hayakawa foi a primeira jogadora mulher na liga. Sua jogada característica é um lançamento baixo que ela chama de Marine Ball!\r\nMizuki Tachibana é mais tomboy que sua senpai, conhecida por seu Crescent Moon Pitch e seu amor pelo pudim vendido em Pawado!\r\nHijiri Rokudo é uma recebedora com um dom raro para o beisebol! Ela tem sido a melhor amiga de Mizuki desde o ensino fundamental e seu prato favorito em Pawado é o Kintsuba!','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49867899,'Sequência do Criademônio',replace(replace('2 monstros, incluindo um monstro Demônio de LUZ	\r\nDurante sua Fase Principal: você pode Invocar por Invocação-Fusão 1 Monstro de Fusão Demônio do seu Deck Adicional, ao embaralhar no Deck suas matérias do seu Cemitério. \r\nVocê pode escolher 1 monstro Demônio de LUZ que não seja Link que você controla; equipe este card do seu campo ou Cemitério a esse monstro que você controla como uma Magia de Equipamento com o seguinte efeito.\r\n● Seu oponente não pode escolher o monstro equipado como alvo de efeitos de card.	\r\nVocê só pode usar cada efeito de "Sequência do Criademônio" uma vez por turno.','\r',char(13)),'\n',char(10)),'Efeito de Fusão','Efeito de Equipamento','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49868263,'Ryu Senshi',replace(replace('"Guerreiro Dai Grepher" + "Espírito Ryu"	\r\nA Invocação-Fusão deste card só pode ser feita com as Matérias de Fusão acima. \r\nQuando um Card de Armadilha Normal for ativado (Efeito Rápido): você pode pagar 1000 PV; negue o efeito. \r\nEste card deve estar com a face para cima no campo para ativar e resolver este efeito. \r\nNegue os efeitos de qualquer Card de Magia que escolha este card como alvo e destrua-o.','\r',char(13)),'\n',char(10)),'Negar efeitos','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49879995,'Dragão Fantasma','Quando seu oponente Invocar um monstro por Invocação-Especial (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão. 2 de suas Zonas dos Cards de Monstro não podem ser usadas.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49881766,'Soldado Arquidemônio','Um perito em batalha que pertence a uma unidade diabólica. Ele é famoso porque faz sempre o seu trabalho.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49885567,'Avatar da Besta Espiritual Cannáguia',replace(replace('Uma vez por turno: você pode banir 1 card "Besta Espiritual" do seu Deck, com a face para cima. \r\nDurante sua segunda Fase de Apoio depois da ativação deste efeito, adicione à sua mão o card banido por este efeito. \r\nVocê só pode Invocar "Avatar(es) da Besta Espiritual Cannáguia" por Invocação-Especial uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49888191,'Garnecia Elefantis','Um monstro tão pesado que cada passo seu estremece o chão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49904658,'Hrimnir, a Seguidora Divina',replace(replace('Você pode oferecer como Tributo 3 monstros Fada da sua mão e/ou do campo; Baixe 1 Magia Contínua do seu Deck, mas envie-a para o Cemitério durante a Fase Final do seu oponente. \r\nSe este card for enviado para o Cemitério por um efeito de card: você pode Invocar este card por Invocação-Especial, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar cada efeito de "Hrimnir, a Seguidora Divina" uma vez por turno.','\r',char(13)),'\n',char(10)),'Baixar','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49905576,'Meltiel, a Sábia dos Céus','Sempre que um Card de Armadilha de Resposta for ativado, imediatamente depois que ele resolver, ganhe 1000 PV e, se isso acontecer, se "O Santuário no Céu" estiver no campo, destrua 1 card que seu oponente controla.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49919798,'Guerreiro Sinfônico Síntesse',replace(replace('VIRE: Você pode adicionar 1 monstro "Guerreiro Sinfónico" do seu Deck à sua mão, exceto "Guerreiro Sinfônico Síntesse".\r\nUma vez por turno: você pode escolher 1 monstro que você controla ou no seu Cemitério, cujo nome original inclui "Guerreiro Sinfónico", exceto "Guerreiro Sinfônico Síntesse"; até a Fase Final, o nome deste card se torna o nome original desse monstro e troque este efeito pelos efeitos originais desse monstro. \r\nVocê pode banir este card do seu Cemitério e, depois, escolher 1 dos seus monstros "Guerreiro Sinfónico" banidos, exceto "Guerreiro Sinfônico Síntesse"; Invoque-o por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Terminar o efeito copiado','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49922726,'Leraje, o Deus da Arquearia',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode fazer com que este card ganhe 100 de ATK para cada Tipo de Monstro atualmente no seu Cemitério, até o final deste turno. \r\nVocê pode escolher 1 outro monstro com a face para cima no campo; este card não pode atacar pelo resto deste turno e, além disso, esse monstro perde DEF igual ao ATK deste card e, depois, se a DEF dele se tornar 0 por este efeito, destrua-o. \r\nVocê só pode usar este efeito de "Leraje, o Deus da Arquearia" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49928686,'Pixies Spright',replace(replace('Se você controlar um monstro de Nível/Classe 2, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Pixies Spright" por Invocação-Especial uma vez por turno desta forma. \r\nDurante o cálculo de dano, se outro monstro de Nível/Classe/Link 2 que você controla batalhar um monstro do oponente (Efeito Rápido): você pode enviar este card da sua mão ou do campo para o Cemitério; até o final deste turno, esse monstro que você controla ganha ATK/DEF igual ao ATK do monstro do oponente. \r\nVocê só pode usar este efeito de "Pixies Spright" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49930315,'Raio-ferrão Branco',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) ao descartar 1 monstro de ÁGUA. \r\nVocê só pode Invocar "Raio-ferrão Branco" por Invocação-Especial uma vez por turno desta forma. \r\nSe este card for Invocado por Invocação-Especial do Cemitério: você pode considerá-lo como um Regulador neste turno. \r\nVocê só pode usar este efeito de "Raio-ferrão Branco" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49936169,'U.A. Vestiário',replace(replace('(Este card deve ser sempre considerado como um card "F.A.")	\r\nEscolha 1 monstro "U.A." ou "F.A." que você controla ou no seu Cemitério; adicione-o à mão e, se isso acontecer, você ganha 500 PV e, depois, você pode aplicar este efeito.\r\n● Revele qualquer número de monstros "U.A." e/ou "F.A." na sua mão, embaralhe-os no Deck e, depois, compre cards igual ao número de cards embaralhados.	\r\nVocê só pode ativar 1 "U.A. Vestiário" por turno.','\r',char(13)),'\n',char(10)),'Retornar card(s) da sua mão para o Deck e comprar?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49941059,'Portão Mágico dos Milagres','Se você controlar 2 ou mais monstros Mago: coloque em Posição de Defesa 1 monstro em Posição de Ataque que seu oponente controla e, depois, tome o controle dele e, se isso acontecer, ele não pode ser destruído em batalha.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49959355,'Uni-Zumbi',replace(replace('Você pode escolher 1 monstro com a face para cima no campo; descarte 1 card e, se isso acontecer, aumente o Nível do alvo em 1. \r\nVocê pode escolher 1 monstro com a face para cima no campo; os monstros que você controla não podem atacar pelo resto deste turno, exceto monstros Zumbi e, além disso, envie 1 monstro Zumbi do seu Deck para o Cemitério e, se isso acontecer, aumente o Nível do alvo em 1. \r\nVocê só pode usar cada efeito de "Uni-Zumbi" uma vez por turno.','\r',char(13)),'\n',char(10)),'Descarte 1 card','Envie um monstro do seu Deck para o Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49964567,'Maruja de Estai Romarin',replace(replace('(Efeito Rápido): você pode escolher 1 monstro com a face para cima que você controla; envie 1 outro monstro Planta que você controla para o Cemitério e, se isso acontecer, na próxima vez que o monstro alvo seria destruído em batalha ou por um efeito de card neste turno, ele não é destruído. \r\nSe este card for enviado para o Cemitério por um efeito de card: você pode enviar 1 monstro Planta de Nível 5 ou menos do seu Deck ou Deck Adicional para o Cemitério. \r\nVocê só pode usar cada efeito de "Maruja de Estai Romarin" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','O efeito de "Maruja de Estai Romarin" está sendo aplicado.','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49966326,'Kirin do Mundo Virtual - Lili',replace(replace('Se este card estiver na sua mão: você pode escolher 1 card "Mundo Virtual" que você controla; envie 1 card "Mundo Virtual" de um tipo diferente (Monstro, Magia, Armadilha) do seu Deck para o Cemitério e, se isso acontecer, Invoque este card por Invocação-Especial e, depois, você pode enviar 1 card "Mundo Virtual" do terceiro tipo do seu Deck para o Cemitério, exceto "Kirin do Mundo Virtual - Lili". \r\nPelo resto deste turno, você só pode Invocar por Invocação-Especial monstros de Nível/Classe 3 ou mais. \r\nVocê só pode usar este efeito de "Kirin do Mundo Virtual - Lili" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial da mão','Enviar 1 card do seu Deck para o Cemitério?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49966595,'Parasita Alicercinza',replace(replace('Quando um monstro do oponente declarar um ataque direto: se você não controlar nenhum monstro, você pode Invocar por Invocação-Especial 1 monstro "Alicercinza" do seu Deck em Posição de Ataque. \r\nQuando um monstro "Alicercinza" que você controla declarar um ataque direto: você pode escolher 1 monstro no Cemitério do seu oponente; se ele não controlar nenhum monstro, Invoque o alvo por Invocação-Especial no lado do campo dele. \r\nVocê só pode usar cada efeito de "Parasita Alicercinza" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invoque por Invocação Especial 1 monstro "Alicercinza" do seu Deck em Posição de Ataque','Invoque por Invocação Especial 1 monstro do Cemitério do seu oponente para o campo dele','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49980185,'Regeneração Sobrenatural',replace(replace('Ative apenas durante a Fase Final. \r\nGanhe 1000 PV para cada monstro do Tipo Psíquico enviado para o Cemitério neste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(49998907,'Frutos dos Estudos de Kozaky','Veja os 3 cards do topo do seu Deck, arranje-os na ordem desejada, e devolva-os para o topo do Deck.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50005218,'Força Celeste - Espaço Aéreo - Área Zero',replace(replace('Você pode escolher 1 outro card que você controla; escave os 3 cards do topo do seu Deck e, se isso acontecer, você pode adicionar 1 card "Força Celeste" escavado à sua mão e, além disso, embaralhar o resto no Deck e, depois, se você escavou um card "Força Celeste", envie o card alvo para o Cemitério. \r\nSe este card na Zona do Campo for enviado para o Cemitério por um efeito de card: você pode Invocar por Invocação-Especial 1 monstro "Força Celeste - Ás" do seu Deck. \r\nVocê só pode usar cada efeito de "Força Celeste - Espaço Aéreo - Área Zero" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Escolher 1 card para adicionar à mão?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50005633,'Espadachim Sorrateiro','Um monstro formado pelas almas vingativas daqueles que pereceram em batalha.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50032342,'Estrategista da Barreira de Gelo','Uma vez por turno: você pode enviar 1 monstro "Barreira de Gelo" da sua mão para o Cemitério; compre 1 card.','Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50042011,'Sonovelha Mementotlan',replace(replace('Durante o turno em que um ou mais monstros em sua posse foram destruídos por um efeito de card (Efeito Rápido): você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode Invocar por Invocação-Fusão 1 Monstro de Fusão "Memento" do seu Deck Adicional, usando monstros da sua mão ou do campo. \r\nSe este card for destruído em batalha ou por um efeito de card: você pode enviar 1 card "Memento" do seu Deck para o Cemitério, exceto "Sonovelha Mementotlan". \r\nVocê só pode usar cada efeito de "Sonovelha Mementotlan" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial da mão','Invocação Fusão','Enviar do Deck para o Cemitério','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50045299,'Jarro de Captura de Dragões','Enquanto este card permanece no Campo com a face para cima, todos os monstros do Tipo Dragão no Campo, mudam para Posição de Defesa.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50056656,'Zona Vermelha',replace(replace('Quando seu oponente ativar um card ou efeito enquanto você controlar "Dragão Vermelho Arquidemônio" ou um Monstro Sincro que o mencione: você pode escolher 1 card no campo; destrua-o. \r\nVocê pode escolher 1 dos seus Monstros Sincro Dragão de TREVAS banidos; Invoque-o por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Zona Vermelha" uma vez por turno.','\r',char(13)),'\n',char(10)),'Destrua cards no campo','Invoque por Invocação Especial um monstro banido','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50065971,'Samurai Superpesado Ninja Furtivo',replace(replace('1 Regulador do Tipo Máquina + 1 ou mais monstros não-Reguladores do Tipo Máquina	\r\nEste card pode atacar enquanto estiver com a face para cima em Posição de Defesa. \r\nSe o fizer, use sua DEF para o cálculo de dano. \r\nSe você não tiver nenhum Card de Magia/Armadilha no seu Cemitério: até o final deste turno, você pode diminuir pela metade a DEF original deste card e, se isso acontecer, este card pode atacar diretamente seu oponente neste turno. \r\nUma vez por turno, durante a próxima Fase de Apoio depois que este card for destruído por um efeito de card e enviado para o Cemitério: você pode Invocar este card por Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50073633,'Místico Céltica',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode revelar toda a sua mão, e se revelar um card que mencione "Ritual da Luz e das Trevas", você pode comprar 3 cards e, depois, descarte 2 cards e, além disso, pelo resto deste turno, você só pode Invocar por Invocação-Especial uma vez do Deck Adicional. \r\nVocê pode oferecer este card como Tributo; Invoque por Invocação-Especial da sua mão, 1 Monstro de Ritual que mencione "Ritual da Luz e das Trevas". \r\nVocê só pode usar cada efeito de "Místico Céltica" uma vez por turno.','\r',char(13)),'\n',char(10)),'Comprar','Invocação Especial','Comprar 1 card?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50074392,'Sereiorca',replace(replace('Se você controlar monstros tanto do Tipo Peixe como do Tipo Besta Alada, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nQuando isso acontecer: você pode declarar um Nível de 3 a 5; o Nível de todos os monstros que você controla atualmente se torna o Nível declarado. \r\nSe você ativar este efeito, os monstros que você controla não podem ativar seus efeitos pelo resto do turno, exceto monstros de ÁGUA.','\r',char(13)),'\n',char(10)),'Alterar Nível','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50074522,'Mosquito Magnético','VIRE: Destrua todos os monstros Máquina no campo.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50078320,'Gravador da Máscara',replace(replace('Quando seu oponente ativar um card ou efeito ao declarar exatamente 1 nome de card (Efeito Rápido): você pode enviar este card da sua mão para o Cemitério; declare 1 outro nome de card. \r\nO nome de card declarado por seu oponente se torna o nome de card declarado por este efeito. \r\nUma vez por turno (Efeito Rápido): você pode escolher 1 card com a face para cima no campo; destrua-o durante a Fase Final do próximo turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50078509,'Corrente Demoníaca',replace(replace('Ative este card ao escolher 1 Monstro de Efeito no campo; negue os efeitos desse monstro com a face para cima enquanto ele estiver no campo e, além disso, esse monstro com a face para cima não pode atacar. \r\nQuando ele for destruído, destrua este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50088247,'Prior da Barreira de Gelo',replace(replace('Se você controlar um monstro "Barreira de Gelo", você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê não pode Invocar por Invocação-Especial qualquer monstro de Nível 5 ou mais no turno em que Invocar desta forma. \r\nVocê pode oferecer este card como Tributo e, depois, escolha 1 monstro "Barreira de Gelo" no seu Cemitério, exceto "Prior da Barreira de Gelo"; Invoque o alvo por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50091196,'Fórmula Sincron',replace(replace('1 Regulador + 1 monstro não-Regulador	\r\nQuando este card for Invocado por Invocação-Sincro: você pode comprar 1 card. \r\nUma vez por Corrente, durante a Fase Principal do seu oponente, você pode (Efeito Rápido): imediatamente depois que este efeito resolver, Invoque por Invocação-Sincro usando este card que você controla.','\r',char(13)),'\n',char(10)),'Comprar','Invocação Sincro','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50122883,'Sapatos das Dentadas',replace(replace('VIRE: Mude a posição de batalha de 1 monstro com a face para cima no campo. \r\nO card deve permanecer com a face para cima.','\r',char(13)),'\n',char(10)),'Mudar a posição de batalha','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50123605,'Cavalaria Pesada dos Insetos Indestrutíveis',replace(replace('1 monstro Inseto de Nível 5 ou mais + 1 monstro Inseto	\r\nNão pode ser destruído pelos efeitos de card do seu oponente. \r\nSe todos os monstros com a face para cima que você controla forem monstros Inseto (Efeito Rápido): você pode escolher 2 monstros no campo, incluindo um monstro Inseto que você controla; bana-os. \r\nVocê só pode usar este efeito de "Cavalaria Pesada dos Insetos Indestrutíveis" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Banir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50134646,'Juntar o Bando',replace(replace('Coloque 1 monstro do seu Deck na sua Zona de Magias & Armadilhas como uma Magia Contínua com a face para cima. \r\nVocê pode banir este card do seu Cemitério; coloque 1 monstro do seu Deck na sua Zona de Magias & Armadilhas como uma Armadilha Contínua com a face para cima. \r\nVocê só pode usar 1 efeito de "Juntar o Bando" por turno e apenas uma vez por turno. \r\nO número total de cards nas Zonas de Monstros e Cards de Monstro com a face para cima nas Zonas de Magias & Armadilhas deve ser 10 ou mais para ativar qualquer um dos efeitos deste card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50139096,'Ruína, a Anja do Esquecimento',replace(replace('Você pode Invocar este card por Invocação-Ritual com "Ciclo do Mundo". \r\nO nome deste card se torna "Ruína, a Rainha do Esquecimento" enquanto estiver na mão ou no campo. \r\nSe este card for Invocado por Invocação-Ritual: ele pode realizar até 2 ataques contra monstros durante cada Fase de Batalha neste turno. \r\nSe este card for enviado para o Cemitério: você pode escolher 1 Monstro de Ritual que você controla; enquanto ele estiver com a face para cima no seu campo, seu oponente não pode ativar cards ou efeitos quando seus Monstros de Ritual declararem um ataque.','\r',char(13)),'\n',char(10)),'','','O efeito de "Ruína, a Anja do Esquecimento" está sendo aplicado.','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50140163,'Rainha Cativante LV7',replace(replace('Uma vez por turno, se você controlar este card que foi Invocado por Invocação-Especial pelo efeito de "Rainha Cativante LV5": você pode escolher 1 monstro que seu oponente controla; equipe o alvo a este card como uma Magia de Equipamento (máx. 1). \r\nSe este card seria destruído em batalha, em vez disso, destrua esse monstro equipado a ele.','\r',char(13)),'\n',char(10)),'Equipar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50147815,'Ataque Combinado das Bestas Sagradas',replace(replace('Invoque por Invocação-Especial 1 monstro "Bestas Sagradas" da sua mão ou do Cemitério em Posição de Defesa e, depois, se você controlar 2 ou mais monstros "Bestas Sagradas" cujos Níveis originais sejam 10, você pode negar os efeitos de 1 card com a face para cima que seu oponente controla e, se isso acontecer, destrua-o. \r\nVocê pode banir este card do seu Cemitério; Invoque por Invocação-Fusão 1 Monstro de Fusão "Fantasma" do seu Deck Adicional, usando monstros da sua mão ou do campo. \r\nVocê só pode usar cada efeito de "Ataque Combinado das Bestas Sagradas" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Invocação Fusão','Negar os efeitos do card?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50152549,'Poção Paralisante','Um monstro que não seja do Tipo Máquina equipado com este card, não pode atacar.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50155385,'Sussurro Espiritual',replace(replace('Uma vez por turno, este card não pode ser destruído em batalha. \r\nQuando este card for Invocado por Invocação-Pêndulo: você pode adicionar 1 Monstro de Ritual ou 1 Card de Magia de Ritual do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Procurar no Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50164989,'Verger Obscuro','Quando um monstro Regulador do Tipo Planta for Invocado por Invocação-Normal no seu lado do campo: você pode Invocar este card por Invocação-Especial do seu Cemitério em Posição de Ataque.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50176820,'Mecaperca','Este monstro carrega um canhão de plasma devastador em suas costas poderosas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50179591,'Script do Abismo - Covil do Dragão de Fogo',replace(replace('Escolha 1 monstro "Ator do Abismo" que você controla; se ele destruir um monstro do seu oponente em batalha neste turno, seu oponente bane 3 monstros do seu Deck Adicional (ele seleciona). \r\nSe este card Baixado sob o controle do seu dono for destruído por um efeito de card do oponente e você tiver um Monstro Pêndulo "Ator do Abismo" com a face para cima no seu Deck Adicional: você pode olhar o Deck Adicional do seu oponente e, além disso, banir 1 monstro do Deck Adicional dele. \r\nVocê só pode usar este efeito de "Script do Abismo - Covil do Dragão de Fogo" uma vez por turno.','\r',char(13)),'\n',char(10)),'O efeito de "Script do Abismo - Covil do Dragão de Fogo" está sendo aplicado no momento.','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50185950,'Renunkuriboh',replace(replace('Se este card for oferecido como Tributo: compre 1 card. \r\nSe um monstro seu seria destruído em batalha, em vez disso, você pode banir este card do seu Cemitério.','\r',char(13)),'\n',char(10)),'Comprar','Usar o efeito de "Renunkuriboh" em vez de ser destruído?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50186558,'Escudo do Dragão-Guarda',replace(replace('Você pode escolher 1 monstro Dragão que você controla; até o final do turno do oponente, ele ganha ATK/DEF igual à soma do Valor Link dos Monstros Link atualmente no campo x 100. \r\nVocê só pode usar este efeito de "Escudo do Dragão-Guarda" uma vez por turno. \r\nUma vez por turno, se exatamente 1 monstro Dragão que você controla seria destruído em batalha ou por um efeito de card, em vez disso, você pode enviar 1 Monstro Normal da sua mão ou do Deck para o Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50208444,'Saga Elemental Doriado',replace(replace('Nenhum jogador por ativar cards ou efeitos em resposta a ativação dos efeitos deste card.\r\nSe você tem 3 ou mais diferentes Atributos no seu Cemitério e este card está na sua mão: você pode escolher 1 monstro no seu Cemitério; Invoque por Invocação-Especial ambos ele e este card.\r\nSe você tem 3 ou mais diferentes Atributos no seu Cemitério: você pode Invocar por Invocação-Especial 1 monstro do seu Deck com um Atributo diferente dos monstros no seu campo e Cemitério.\r\nVocê só pode usar cada um dos efeitos de "Saga Elemental Doriado" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Invocar por Invocação Especial do Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50208445,'Saga Elemental Doriado',replace(replace('Nenhum jogador por ativar cards ou efeitos em resposta a ativação dos efeitos deste card.\r\nSe você tem 3 ou mais diferentes Atributos no seu Cemitério e este card está na sua mão: você pode escolher 1 monstro no seu Cemitério; Invoque por Invocação-Especial ambos ele e este card.\r\nSe você tem 3 ou mais diferentes Atributos no seu Cemitério: você pode Invocar por Invocação-Especial 1 monstro do seu Deck com um Atributo diferente dos monstros no seu campo e Cemitério.\r\nVocê só pode usar cada um dos efeitos de "Saga Elemental Doriado" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Invocar por Invocação Especial do Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50213848,'Reviver Monstro Revivido',replace(replace('Escolha 3 monstros no seu Cemitério; seu oponente seleciona 1, você o Invoca por Invocação-Especial e, se isso acontecer, bana o resto. \r\nVocê só pode ativar 1 "Reviver Monstro Revivido" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50215517,'Segurança Escarlate','Se você controlar um "Dragão Vermelho Arquidemônio": destrua todos os Cards de Magia e Armadilha que seu oponente controla.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50237654,'Os Magos Negros',replace(replace('"Mago Negro" ou "Pequena Maga Negra" + 1 monstro Mago	\r\nUma vez por turno, se um Card de Magia/Armadilha ou seus efeitos forem ativados (exceto durante a Etapa de Dano): você pode comprar 1 card e, depois, se era uma Magia/Armadilha, você pode Baixá-la e, se era uma Armadilha ou Magia Rápida, você pode ativá-la neste turno. \r\nSe este card for destruído: você pode Invocar por Invocação-Especial tanto 1 "Mago Negro" quanto 1 "Pequena Maga Negra" da sua mão, do Deck e/ou do Cemitério.','\r',char(13)),'\n',char(10)),'Baixar esse card?','Compre 1 card(s)','Ativar aplicando o efeito de "Os Magos Negros".','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50243722,'Explosão de Renascimento','Pague 2000 Pontos de Vida e, depois, escolha 1 monstro no seu Cemitério; Invoque o alvo por Invocação-Especial com a face para baixo em Posição de Defesa.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50251045,'Calamidade das Bestas Sagradas - Hamon, o Senhor do Trovão Impactante',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial com o efeito de um card "Bestas Sagradas". \r\nVocê pode revelar este card na sua mão; adicione 1 Magia "Bestas Sagradas" do seu Deck à sua mão e, depois, descarte 1 card. \r\nVocê só pode usar este efeito de "Calamidade das Bestas Sagradas - Hamon, o Senhor do Trovão Impactante" uma vez por turno. \r\nUma vez por turno, se um ou mais monstros forem enviados para o Cemitério do seu oponente: cause 1000 de dano ao seu oponente. \r\nSe este card for destruído em batalha ou por um efeito de card: você pode ativar este efeito; você não sofre dano neste turno.','\r',char(13)),'\n',char(10)),'Efeito de busca','Efeito de dano','Imunidade a dano','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50259460,'Versago, o Destruidor','Este card pode ser usado como um substituto para qualquer 1 Matéria de Fusão mencionada por nome no Card de Monstro de Fusão, mas a(s) outra(s) matéria(s) deve(m) estar correta(s).','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50260683,'Número 36: Cronomalia Chateau Huyuk',replace(replace('2 monstros "Cronomalia" de Nível 4	\r\nUma vez por turno, durante o turno de qualquer duelista: você pode desassociar 1 Matéria Xyz deste card e, depois, escolher 1 monstro com a face para cima que seu oponente controla; até o final deste turno, mude o ATK dele para 0. \r\nVocê pode oferecer como Tributo 1 monstro "Cronomalia" e, depois, escolher 1 monstro que seu oponente controla cujo ATK atual seja diferente do ATK original; destrua o alvo.','\r',char(13)),'\n',char(10)),'O ATK se torna 0','Destruir um monstro','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50263751,'Quasar Ganancioso',replace(replace('O ATK e a DEF originais deste card ficam iguais ao Nível dele x 300. \r\nO Nível deste monstro aumenta de acordo com o Nível dos monstros que ele destrói em batalha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50275295,'Portão do Mundo Virtual - Qinglong',replace(replace('Você pode banir 1 card "Mundo Virtual" do seu Cemitério e, depois, escolha 1 monstro com a face para cima no campo; negue os efeitos dele até o final deste turno (mesmo que este card deixe o campo). \r\nVocê pode banir este card do seu Cemitério; adicione 1 monstro "Mundo Virtual" do seu Deck à sua mão e, depois, envie 1 card da sua mão para o Cemitério. \r\nVocê só pode usar cada efeito de "Portão do Mundo Virtual - Qinglong" uma vez por turno.','\r',char(13)),'\n',char(10)),'Negar um monstro','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50277355,'Ponto-ovelha',replace(replace('2 monstros com nomes diferentes	\r\nSe um monstro for Invocado por Invocação-Especial em uma zona para a qual este card apontar (exceto durante a Etapa de Dano): você pode aplicar os seguintes efeitos, em sequência, de acordo com os tipos de card dos monstros para os quais este card apontar.\r\n● Ritual: Compre 2 cards e, depois, descarte 2 cards.\r\n● Fusão: Invoque por Invocação-Especial 1 monstro de Nível 4 ou menos do seu Cemitério.\r\n● Sincro: Todos os monstros que você controla ganham 700 de ATK.\r\n● Xyz: Todos os monstros que seu oponente controla perdem 700 de ATK.	\r\nVocê só pode usar este efeito de "Ponto-ovelha" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50277356,'Ponto-ovelha',replace(replace('2 monstros com nomes diferentes	\r\nSe um monstro for Invocado por Invocação-Especial em uma zona para a qual este card apontar (exceto durante a Etapa de Dano): você pode aplicar os seguintes efeitos, em sequência, de acordo com os tipos de card dos monstros para os quais este card apontar.\r\n● Ritual: Compre 2 cards e, depois, descarte 2 cards.\r\n● Fusão: Invoque por Invocação-Especial 1 monstro de Nível 4 ou menos do seu Cemitério.\r\n● Sincro: Todos os monstros que você controla ganham 700 de ATK.\r\n● Xyz: Todos os monstros que seu oponente controla perdem 700 de ATK.	\r\nVocê só pode usar este efeito de "Ponto-ovelha" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50277973,'Espelhador do Pântano',replace(replace('Ative este card ao declarar 1 Tipo de Monstro e 1 Atributo; Invoque este card por Invocação-Especial como um Monstro Normal (Nível 4/ATK 1800/DEF 1000) com esse Tipo e Atributo.	\r\n(Este card ainda é considerado uma Armadilha.)','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50278554,'Dragão Gêmeo de Restolhos',replace(replace('1 Regulador "Restolhos" + 1+ monstros não-Reguladores	\r\nUma vez por turno: você pode escolher 1 card que você controla e 2 cards que seu oponente controla; destrua o que você controla e, se isso acontecer, devolva os que seu oponente controla para a mão. \r\nSe este card em sua posse for destruído por um card do seu oponente e enviado para o seu Cemitério: escolha 1 monstro "Restolhos" que não seja Sincro no seu Cemitério; Invoque-o por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Destruir','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50281477,'Maculado da Tistina',replace(replace('Você pode Invocar este card por Invocação-Tributo com a face para cima ao oferecer como Tributo 1 monstro com a face para baixo que seu oponente controla. \r\nO Nível deste card se torna 10 se ele foi Invocado por Invocação-Normal/Baixado. \r\nSe este card for enviado para o Cemitério, exceto do campo: você pode escolher 1 monstro "Tistina" que você controla; neste turno, ele pode realizar um segundo ataque durante cada Fase de Batalha e, além disso, você só pode atacar com 1 monstro.','\r',char(13)),'\n',char(10)),'Ofereça como Tributo 1 monstro com a face para baixo que seu oponente controla para fazer uma Invocação Tributo','Atacar duas vezes','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50282757,'HERÓI Maligno Franco-Atiradora Infernal',replace(replace('"Clayman, o HERÓI do Elemento" + "Burstinatrix, o HERÓI do Elemento"	\r\nDeve ser Invocado por Invocação-Especial com "Fusão Negra". \r\nNão pode ser destruído por efeitos de Magia. \r\nUma vez por turno, durante sua Fase de Apoio: cause 1000 de dano ao seu oponente. \r\nEste card deve estar com a face para cima em Posição de Defesa para ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50287060,'Arquidemônio de Gilfer',replace(replace('Quando este card for enviado para o Cemitério: você pode escolher 1 monstro com a face para cima no campo; equipe este card no alvo. \r\nEsse monstro perde 500 de ATK enquanto estiver equipado com este card.','\r',char(13)),'\n',char(10)),'Equipar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50292967,'Imagem do Passado',replace(replace('Se você controlar um monstro do Tipo Psíquico com a face para cima: Escolha 1 monstro que seu oponente controla; bana-o. \r\nDurante a próxima Fase de Apoio, ele é devolvido para o lado do campo do oponente na mesma Posição de Batalha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50304345,'HERÓI Maligno Prodígio Infernal',replace(replace('Se você não controlar nenhum monstro, você pode Invocar este card por Invocação-Especial (da sua mão) em Posição de Ataque. \r\nUma vez por turno, durante a Fase Final, se este card foi oferecido como Tributo neste turno para a Invocação-Tributo de um monstro "HERÓI": compre 1 card.','\r',char(13)),'\n',char(10)),'Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50311058,'Grande Debandada Motoqueiro Goblin',replace(replace('Durante a Fase Principal, você pode: imediatamente depois que este efeito resolver, Invocar por Invocação-Xyz 1 Monstro Xyz, usando apenas monstros "Goblin" que você controla. \r\nSe você controlar um Monstro Xyz "Goblin": você pode escolher 1 Monstro de Efeito no campo; desassocie 1 Matéria Xyz de um monstro em qualquer campo e, se isso acontecer, negue os efeitos desse monstro até o final deste turno. \r\nVocê só pode usar 1 efeito de "Grande Debandada Motoqueiro Goblin" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Xyz','Negar o efeito','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50319138,'Papa-Bugs Z',replace(replace('Quando este card for Invocado por Invocação-Normal: Você pode Invocar por Invocação-Especial 1 "Papa-Bugs Y" do seu Deck. \r\nVocê deve controlar um "Papa-Bugs X" com a face para cima para ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50321796,'Brionac, o Dragão da Barreira de Gelo',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nVocê pode descartar qualquer número de cards para o Cemitério e, depois, escolha o mesmo número de cards que seu oponente controla; devolva esses cards para a mão. \r\nVocê só pode usar este efeito de "Brionac, o Dragão da Barreira de Gelo" uma vez por turno.','\r',char(13)),'\n',char(10)),'Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50323155,'Chifre Negro Celestial','Quando seu oponente Invocaria exatamente 1 monstro por Invocação-Especial: negue a Invocação-Especial e, se isso acontecer, destrua-o.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50354944,'Origem de Gaia, o Cavaleiro Impetuoso',replace(replace('Este card pode ser considerado como 2 Tributos para a Invocação-Tributo de um monstro Guerreiro. \r\nVocê só pode usar cada um dos seguintes efeitos de "Origem de Gaia, o Cavaleiro Impetuoso" uma vez por turno. \r\nVocê pode enviar 1 monstro de Nível 5 ou mais da sua mão para o Cemitério; Invoque este card por Invocação-Especial da sua mão. \r\nDurante a Fase de Batalha (Efeito Rápido): você pode banir este card do seu Cemitério e, depois, escolha 1 monstro no campo cujo ATK atual seja diferente do seu ATK original; o ATK dele se torna seu ATK original.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50357013,'Tokusano Shinkyojin','Envie para o Cemitério um ou mais monstros da sua mão e/ou do campo com a face para cima cuja soma dos Níveis seja igual a 10; compre 2 cards.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50366775,'Formatador-do-lodo',replace(replace('Durante sua Fase Principal: você pode revelar 1 Monstro Link no seu Deck Adicional e, se isso acontecer, quando você Invocar por Invocação-Link neste turno, você pode considerar este card como uma Matéria Link com o mesmo nome, Tipo e Atributo que o monstro revelado. \r\nSe este card for enviado para o Cemitério como Matéria Link: você pode adicionar 1 monstro Ciberso de Nível 5 ou mais do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "Formatador-do-lodo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50371210,'Baliza de Branco',replace(replace('Se você não controlar outro "Baliza de Branco", e tiver 3 ou mais monstros "Olhos Azuis" no seu Cemitério: escolha 1 deles; Invoque-o por Invocação-Especial, mas negue seus efeitos e, além disso, equipe-o com este card. \r\nQuando este card deixar o campo, bana o monstro equipado. \r\nOutros monstros que você controla não podem atacar e, além disso, se você tiver qualquer número de monstros "Olhos Azuis" no seu Cemitério, o monstro equipado pode atacar até esse número de vezes durante cada Fase de Batalha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50383626,'Diábolos Tenebroso, Senhor do Covil',replace(replace('Seu oponente não pode oferecer este card com a face para cima no campo como Tributo e não pode escolhê-lo como alvo de efeitos de card. \r\nVocê só pode usar cada um desses efeitos de "Diábolos Tenebroso, Senhor do Covil" uma vez por turno.\r\n● Se um monstro de TREVAS que você controla for oferecido como Tributo (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial do seu Cemitério (se ele estava lá quando você ofereceu o Tributo) ou da mão (mesmo se ele não estava).\r\n● Você pode oferecer como Tributo 1 monstro de TREVAS; seu oponente coloca 1 card da mão dele no topo ou no fundo do Deck.','\r',char(13)),'\n',char(10)),'','','Topo do Deck','Fundo do Deck','','','','','','','','','','','','');
INSERT INTO texts VALUES(50400231,'Canhão Satélite',replace(replace('Este card não pode ser destruído em batalhas com monstros de Nível 7 ou menos. \r\nDurante cada uma das suas Fases Finais: este card ganha 1000 de ATK. \r\nSe este card atacar, esse aumento de ATK volta a 0 depois do cálculo de dano.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50407691,'Cavaleirardor Margrave',replace(replace('Escala de Pêndulo = 7\r\n[ Efeito de Pêndulo ]\r\nSe você tiver um card "Cavaleirardor" na sua outra Zona de Pêndulo: você pode destruir os dois cards nas suas Zonas de Pêndulo e, se isso acontecer, adicione 1 monstro de FOGO do Tipo Guerreiro do seu Deck ou Cemitério à sua mão.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nUm guerreiro Cavaleirardor de alto escalão. Quando ele entra na luta, seus ataques violentos são temidos não só pelo inimigo, mas também por suas próprias tropas.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50412166,'Amuleto de Shabti',replace(replace('Descarte este card da sua mão. \r\nAté à End Phase torne o dano de batalha que os monstros que incluam "Coveiro" no seu nome recebem em 0. \r\nNo entanto, o dano aos seus Life Points é calculado normalmente.','\r',char(13)),'\n',char(10)),'O dano de batalha envolvendo monstros cujo nome contenha "Coveiro" torna-se 0','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50415441,'Arquidemônio Mimicarniçal',replace(replace('VIRE: Se for a Fase Principal: aplique esses efeitos em sequência.\r\n● Seu oponente compra 1 card.\r\n● Envie 1 card da sua mão para o Cemitério.\r\n● Conceda o controle deste card ao seu oponente.	\r\nDurante sua Fase Principal: você pode Invocar este card por Invocação-Especial da sua mão no campo do seu oponente com a face para baixo em Posição de Defesa. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode colocar 1 monstro com a face para baixo no campo, com a face para cima em Posição de Ataque ou Defesa. \r\nVocê só pode usar cada efeito de "Arquidemônio Mimicarniçal" uma vez por turno.','\r',char(13)),'\n',char(10)),'Efeito de Virar','Invocação Especial','Mudar a posição de batalha','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50418970,'Queimador de Espírito',replace(replace('Uma vez por turno, você pode mudar a posição de batalha do monstro equipado para Posição de Defesa. \r\nQuando o monstro equipado for devolvido do campo para a mão e este card for enviado ao Cemitério, cause 600 de dano ao seu oponente. \r\nSe este card estiver no Cemitério, você pode adicioná-lo à sua mão em vez de conduzir uma compra normal durante sua Fase de Compra.','\r',char(13)),'\n',char(10)),'Mudar para Posição de Defesa','Causar dano','Adicionar à mão','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50426119,'Degradador Notável',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro deve ser Invocado por Invocação-Especial (da sua mão) ao banir 2 monstros Ciberso do seu Cemitério. \r\nVocê pode escolher 1 monstro que seu oponente controla com ATK maior que o deste card (Efeito Rápido); bana-o até a Fase Final. \r\nVocê só pode usar este efeito de "Degradador Notável" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50427388,'Magia Bizarra!','Bana todos os Cards de Magia do seu Cemitério; destrua todos os monstros com a face para cima que seu oponente controla com DEF menor ou igual ao número de Cards de Magia que você baniu x 300.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50433147,'As Luzes Nórdicas',replace(replace('Monstros "Nórdic" no campo não podem ser destruídos em batalha. \r\nSe este card no campo for destruído: destrua todos os monstros "Nórdic" no campo.','\r',char(13)),'\n',char(10)),'Destrua todos os monstros com a face para cima cujo nome contenha "Nórdico/a"','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50449881,'Fortaleza Tubarão',replace(replace('2 monstros de Nível 5	\r\nSeu oponente não pode escolher monstros para atacar, exceto este. \r\nUma vez por turno: você pode desassociar 1 Matéria Xyz deste card e, depois, escolher 1 monstro com a face para cima que você controla; ele pode realizar um segundo ataque durante cada Fase de Batalha neste turno.','\r',char(13)),'\n',char(10)),'Ataques múltiplos','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50457953,'Dragão da Árvore Mística','Uma vez por turno: você pode escolher 1 monstro de ÁGUA do Tipo Dragão que você controla; o Nível deste card se torna o Nível atual desse monstro.','Alterar Nível','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50470982,'Caminhos do Destino',replace(replace('Ambos os duelistas lançam uma moeda. \r\nSe o resultado de um duelista for Cara, ele ganha 2000 PV, e se o resultado for Coroa, ele sofre 2000 de dano.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50474354,'Pavão Bujingi',replace(replace('Durante sua Fase Principal 2: você pode enviar este card da sua mão para o Cemitério; adicione 1 monstro "Bujin" do seu Deck à sua mão. \r\nVocê não pode ativar cards ou efeitos no turno em que ativar este efeito, exceto cards "Bujin" e seus efeitos. \r\nVocê só pode usar o efeito de "Pavão Bujingi" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50482813,'Velocidaroide Flautista Fuki-Modoshi',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode escavar cards do topo do seu Deck igual ao número de outros monstros de VENTO que você controla, adicione 1 card escavado à sua mão e, além disso, coloque o resto no fundo do seu Deck em qualquer ordem. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 monstro de VENTO de Nível 3 ou mais que você controla; reduza o Nível dele em 2. \r\nVocê só pode usar cada efeito de "Velocidaroide Flautista Fuki-Modoshi" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50485594,'Hamster de Resgate',replace(replace('Escala de Pêndulo = 5\r\n[ Efeito de Pêndulo ]\r\nVocê pode banir este card da sua Zona de Pêndulo; adicione 2 Cards de Monstro Pêndulo com a face para cima e com o mesmo nome do seu Deck Adicional à sua mão. \r\nVocê só pode usar este efeito de "Hamster de Resgate" uma vez por Duelo.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe este card foi Invocado por Invocação-Normal neste turno e você tiver um Card de Monstro Pêndulo de Nível 5 ou menos com a face para cima no seu Deck Adicional: você pode oferecer este card como Tributo; selecione 1 Card de Monstro Pêndulo de Nível 5 ou menos com a face para cima no seu Deck Adicional e Invoque por Invocação-Especial 2 monstros do seu Deck com o mesmo nome que esse card, mas eles têm seus efeitos negados e, além disso, eles são destruídos durante a Fase Final.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50486289,'Chefa de Guerra Amazoness',replace(replace('Se você não controlar nenhum monstro, ou apenas monstros "Amazoness": você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode Baixar 1 Magia/Armadilha "Amazoness" ou 1 "Polimerização" diretamente do seu Deck e, além disso, você só pode atacar com monstros "Amazoness" pelo resto deste turno. \r\nVocê só pode usar cada efeito de "Chefa de Guerra Amazoness" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50491121,'Desafiante Heroico - Espartano','Uma vez por turno, quando um monstro do oponente declarar um ataque: você pode escolher 1 outro monstro "Heroico(a)" que você controla; este card ganha ATK igual ao ATK original desse monstro com a face para cima até o final da Fase de Batalha.','Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50501121,'Rebelião do Senhor Obscuro',replace(replace('Envie 1 monstro "Senhor(a) Obscuro(a)" da sua mão ou do campo com a face para cima para o Cemitério; destrua 1 card no campo. \r\nVocê só pode ativar 1 "Rebelião do Senhor Obscuro" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50527144,'Desaparecimento Fantardil','Revele 1 monstro "Fantardil" na sua mão; neste turno, cards "Fantardil" que você controla e monstros com a face para baixo em Posição de Defesa que você controla não podem ser escolhidos como alvo nem destruídos por efeitos de card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50532786,'Homem-Mandíbulas',replace(replace('Não pode ser Invocado por Invocação-Especial. \r\nSe você Invocar este card por Invocação-Tributo, todos os Tributos devem ser de ÁGUA. \r\nEste card ganha 300 de ATK para cada monstro de ÁGUA com a face para cima que você controla, exceto este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50546029,'G Golem Trilito Imponente',replace(replace('2+ monstros de TERRA	\r\nTodos os monstros que seu oponente controla devem atacar este card, se possível. \r\nUma vez por batalha, se este card batalhar um monstro do oponente, antes do cálculo de dano (Efeito Rápido): você pode enviar 1 monstro de TERRA da sua mão para o Cemitério; até o final deste turno, esse monstro do oponente perde 200 de ATK e, além disso, negue seus efeitos. \r\nQuando seu oponente ativar um card ou efeito que escolha um ou mais Monstros Link que você controla como alvo (Efeito Rápido): você pode negar esse efeito e, se isso acontecer, destrua esse card. \r\nVocê só pode usar este efeito de "G Golem Trilito Imponente" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50546208,'Marta Amarela Luzlunar',replace(replace('Se este card estiver na sua mão ou no Cemitério: você pode escolher 1 card "Luzlunar" que você controla, exceto "Marta Amarela Luzlunar"; devolva-o para a mão e, se isso acontecer, Invoque este card por Invocação-Especial em Posição de Defesa, mas bana este card quando ele deixar o campo. \r\nSe este card for enviado para o Cemitério por um efeito de card: você pode adicionar 1 Magia/Armadilha "Luzlunar" do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "Marta Amarela Luzlunar" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50548657,'Chifreprompt',replace(replace('Você pode oferecer como Tributo 1 monstro Ciberso de Nível 4 ou menos; Invoque por Invocação-Especial qualquer número de Monstros Normais Ciberso do seu Deck e/ou Cemitério cuja soma dos Níveis seja igual ao Nível do monstro oferecido como Tributo no campo, mas bana-os durante a Fase Final. \r\nVocê só pode usar este efeito de "Chifreprompt" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50554729,'Infecção Amórfaga',replace(replace('Todos os monstros "Amórfago" no campo ganham 100 de ATK e DEF para cada card "Amórfago(a)" no campo. \r\nSe um ou mais monstros na sua mão ou que você controla forem oferecidos como Tributo, ou destruídos em batalha ou por um efeito de card: você pode adicionar 1 card "Amórfago(a)" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Infecção Amórfaga" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50584941,'Supremacia Vermelha','Bana 1 Monstro Sincro "Dragão Vermelho Arquidemônio" do seu Cemitério e, depois, escolha 1 Monstro Sincro "Dragão Vermelho Arquidemônio" que você controla; o nome dele se torna o nome original do monstro banido e troque os efeitos dele pelos efeitos originais do monstro banido.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50588353,'Cristron Halqifibrax',replace(replace('2 monstros, incluindo um Regulador	\r\nSe este card for Invocado por Invocação-Link: você pode Invocar por Invocação-Especial 1 Regulador de Nível 3 ou menos da sua mão ou do Deck em Posição de Defesa, mas ele não pode ativar seus efeitos neste turno. \r\nDurante a Fase Principal ou Fase de Batalha do seu oponente (Efeito Rápido): você pode banir este card que você controla; Invoque por Invocação-Especial 1 Monstro Sincro Regulador do seu Deck Adicional. \r\n(Isso é considerado uma Invocação-Sincro.) \r\nVocê só pode usar cada efeito de "Cristron Halqifibrax" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50590801,'Elfnotas: Aristeia da Confiança',replace(replace('Uma vez por turno: você pode escolher 1 monstro com a face para cima que você controla; mova esse monstro que você controla para outra das suas Zonas de Monstros Principais. \r\nQuando seu oponente ativar um Card de Magia/Armadilha, enquanto você controlar 3 ou mais monstros "Elfnota": você pode negar esse efeito e, depois, se você controlar um Monstro Sincro, você pode destruir esse card. \r\nVocê só pode usar este efeito de "Elfnotas: Aristeia da Confiança" uma vez por turno. \r\nVocê não pode ativar esses efeitos de "Elfnotas: Aristeia da Confiança" na mesma Corrente.','\r',char(13)),'\n',char(10)),'Mover para outra Zona','Negar o efeito','Destruir?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50593156,'Jogador de Areia',replace(replace('Lance uma moeda 3 vezes. \r\nSe os 3 resultados forem Caras, destrúa todos os monstros no Campo do seu adversário. \r\nSe os 3 resultados forem Coroa, destrúa todos os monstros no seu Campo. \r\nEste efeito apenas pode ser usado uma vez por turno, durante a sua Main Phase.','\r',char(13)),'\n',char(10)),'Jogar uma moeda','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50596425,'Espelho Divino Necroz',replace(replace('Durante a Fase Principal: Invoque por Invocação-Ritual 1 Monstro de Ritual "Necroz" da sua mão ou do banimento, oferecendo como Tributo monstros da sua mão/do campo, e/ou enviando monstros "Necroz" do seu Deck Adicional para o Cemitério, cuja soma dos Níveis seja igual ou exceda seu Nível. \r\nDurante sua Fase Principal: você pode banir este card e 1 monstro "Necroz" do seu Cemitério; adicione 1 Magia "Necroz" do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "Espelho Divino Necroz" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Ritual','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50599453,'Platalinguado Colocado',replace(replace('Ganha 200 de ATK/DEF para cada card no Cemitério do seu oponente. \r\nDurante sua Fase de Apoio, se este card estiver na sua mão ou no Cemitério e seu oponente tiver mais cards no Cemitério dele que você: você pode Invocar este card por Invocação-Especial. \r\nVocê só pode usar este efeito de "Platalinguado Colocado" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50604072,'Laminador Carmesim/Modo de Ataque',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial com "Ativar Modo de Ataque". \r\nSeu oponente não pode ativar os efeitos de monstros de Nível 5 ou mais Invocados por Invocação-Especial do Deck Adicional. \r\nVocê pode revelar este card na sua mão; adicione 1 "Ativar Modo de Ataque" ou 1 card que o mencione do seu Deck à sua mão e, se isso acontecer, embaralhe este card no Deck. \r\nVocê só pode usar este efeito de "Laminador Carmesim/Modo de Ataque" uma vez por turno. \r\nSe este card for destruído: você pode Invocar por Invocação-Especial 1 "Laminador Carmesim" do seu Cemitério.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50604950,'Sabre-X Galahad',replace(replace('Se este card atacar um monstro do oponente, este card ganha 300 de ATK apenas durante a Etapa de Dano. \r\nSe este card for atacado por um monstro do oponente, este card perde 500 de ATK apenas durante a Etapa de Dano. \r\nQuando este card for selecionado como alvo de um ataque, você pode oferecer como Tributo outro monstro "Sabre" para negar o ataque.','\r',char(13)),'\n',char(10)),'Negar o ataque','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50608164,'Koga, o HERÓI Mascarado',replace(replace('Deve ser Invocado por Invocação-Especial com "Mudar a Máscara" e não pode ser Invocado por Invocação-Especial de nenhuma outra forma. 	\r\nEste card ganha 500 de ATK para cada monstro que seu oponente controla. \r\nUma vez por turno, durante o turno de qualquer duelista: você pode banir 1 monstro "HERÓI" do seu Cemitério e, depois, escolher 1 monstro com a face para cima no campo; até o final deste turno, o alvo perde ATK igual ao ATK do monstro banido para ativar este efeito.','\r',char(13)),'\n',char(10)),'Reduzir ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50613779,'Maga do Dano','Quando você sofrer dano de um efeito de card: Você pode Invocar este card por Invocação-Especial da sua mão e, se isso acontecer, ganhe PV igual ao dano que você sofreu.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50615578,'Ninja Karakuri mod. 7749 "Nanashick"',replace(replace('Este card deve atacar se possível. \r\nQuando este card com a face para cima no campo for selecionado como alvo de um ataque, mude sua posição de batalha. \r\nQuando este card for Invocado por Invocação-Normal, você pode comprar um número de cards igual ao número de monstros "Karakuri" com a face para cima em Posição de Defesa que você controla.','\r',char(13)),'\n',char(10)),'Alterar posição de batalha','Comprar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50619462,'Chamado do Rebanho',replace(replace('Envie para o Cemitério, 1 monstro com a face para cima que você controla, cujo Tipo original seja Besta, Besta-Guerreira ou Besta Alada; Invoque por Invocação-Especial 1 monstro do seu Deck Adicional com o mesmo Tipo original, mas ele não pode atacar, seus efeitos são negados e, além disso, ele é destruído durante a Fase Final. \r\nVocê só pode ativar 1 "Chamado do Rebanho" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50621530,'Regulador Potencializado','Este card ganha 500 de ATK para cada monstro Regulador com a face para cima no campo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50642380,'Wa Gon Gagaku-P.U.N.K.',replace(replace('Você pode pagar 600 PV; adicione 1 Magia "P.U.N.K." do seu Deck à sua mão. \r\nQuando seu oponente ativar um card ou efeito que escolha como alvo um ou mais monstros "P.U.N.K." que você controla, ou quando um monstro do seu oponente escolher um deles como alvo de um ataque (Efeito Rápido): você pode comprar 1 card. \r\nVocê só pode usar cada efeito de "Wa Gon Gagaku-P.U.N.K." uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50643638,'Chanbar, o Cavaleiro Esportivo Chamativo',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nMonstros que seu oponente controla perdem 400 de ATK para cada Magia de Equipamento que você controla. \r\nVocê só pode usar cada um dos seguintes efeitos de "Chanbar, o Cavaleiro Esportivo Chamativo" uma vez por turno. \r\nVocê pode escolher 1 outro card no campo; envie 1 Magia de Equipamento da sua mão ou do Deck para o Cemitério e, se isso acontecer, destrua o alvo. \r\nSe este card estiver no seu Cemitério: você pode escolher 2 cards com a face para cima na sua Zona de Magias & Armadilhas; destrua-os e, se isso acontecer, Invoque este card por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Efeito de destruição','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50669347,'Nephthys, a Preservadora Sagrada',replace(replace('2 monstros "Nephthys"	\r\nVocê só pode usar o seguinte efeito de "Nephthys, a Preservadora Sagrada" uma vez por turno. \r\nDurante sua Fase Principal, se este card foi Invocado por Invocação-Link: você pode ativar 1 desses efeitos;\r\n● Adicione 1 monstro Besta Alada de Nível 8 do seu Deck à sua mão e, depois, você pode adicionar 1 Magia de Ritual do seu Cemitério à sua mão.\r\n● Destrua 1 monstro "Nephthys" para o qual este card apontar e Invoque por Invocação-Especial 1 monstro "Nephthys" com um nome original diferente do seu Cemitério, mas negue seus efeitos.','\r',char(13)),'\n',char(10)),'','Procurar e recuperar','Destruir e Invocar por Invocação Especial','Adicionar um Card de Magia de Ritual do seu Cemitério à sua mão?','','','','','','','','','','','','');
INSERT INTO texts VALUES(50675040,'Libertação do Rei das Bestas',replace(replace('Uma vez por turno, no começo da Etapa de Dano, se um monstro seu batalhar um monstro do oponente na mesma coluna: você pode devolver para a mão seu monstro e quaisquer outros cards nessa coluna. \r\nVocê só pode ativar o efeito de "Libertação do Rei das Bestas" uma vez por Corrente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50684552,'Garagem das Maravilhas','Quando este card Baixado for destruído e enviado para o Cemitério: você pode Invocar por Invocação-Especial 1 monstro Máquina "roide" de Nível 4 ou menos da sua mão.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50687050,'Arktos XII - Vaylantz do Cronoabismo',replace(replace('Escala de Pêndulo = 12\r\n[ Efeito de Pêndulo ]\r\nVocê pode ativar 1 desses efeitos;\r\n● Invoque este card por Invocação-Especial na sua Zona de Monstros Principal em sua mesma coluna.\r\n● Mova 1 monstro na sua Zona de Monstros Principal para uma Zona de Monstros adjacente (horizontal).	\r\nVocê só pode usar este efeito de "Arktos XII - Vaylantz do Cronoabismo" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\n2 monstros "Vaylantz" de Nível 5 ou mais	\r\nPrimeiro deve ser Invocado por Invocação-Especial (do seu Deck Adicional com a face para baixo) ao oferecer como Tributo os cards acima. \r\n(Efeito Rápido): você pode trocar a localização de 2 monstros nas suas Zonas de Monstros Principais ou 2 monstros nas Zonas de Monstros Principais do seu oponente. \r\nSe um card na Zona de Monstros se mover para outra Zona de Monstros (exceto durante a Etapa de Dano): você pode destruir 1 card no campo. \r\nVocê só pode usar cada efeito de "Arktos XII - Vaylantz do Cronoabismo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Invocação Especial','Mover a posição','Trocar posições','Destruir 1 card','','','','','','','','','','','');
INSERT INTO texts VALUES(50690129,'Eva Capche N2',replace(replace('Se este card estiver na sua mão: você pode escolher 1 monstro de Nível 3 ou mais que você controla; reduza o Nível dele em exatamente 2 e, se isso acontecer, Invoque este card por Invocação-Especial. \r\nVocê só pode usar este efeito de "Eva Capche N2" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50692511,'Ataqueraptor - Chamado',replace(replace('Escolha 1 monstro "Ataqueraptor" que você controla; Invoque por Invocação-Especial, da sua mão ou do Deck, em Posição de Defesa, 1 monstro com o mesmo nome que o desse monstro no campo. \r\nVocê só pode ativar 1 "Ataqueraptor - Chamado" por turno. \r\nVocê não pode Invocar monstros por Invocação-Especial durante o turno em que ativar este card, exceto monstros "Ataqueraptor".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50696588,'Dança Dai',replace(replace('Selecione 1 Zona de Monstros Principal não utilizada do oponente; se seu oponente Invocaria um monstro por Invocação-Normal ou Especial em uma Zona de Monstros Principal dele e a zona selecionada puder ser usada, ele deve usar essa zona. \r\n(Ele não pode Invocar diversos monstros em suas Zonas de Monstros Principais enquanto este efeito for aplicado.) \r\nEste efeito se aplica até que a zona seja ocupada ou se torne inutilizável. \r\nVocê só poder aplicar o efeito de "Dança Dai" uma vez por Duelo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50699850,'Loris, a Dama da Lamentação',replace(replace('Você pode escolher 3 ou 6 das suas Armadilhas Normais que estiverem banidas e/ou no seu Cemitério; coloque-as no fundo do seu Deck em qualquer ordem e, depois, compre 1 card para cada 3 cards colocados. \r\nSe um ou mais outros monstros forem oferecidos como Tributo, ou se uma ou mais Armadilhas Normais forem enviadas para o seu Cemitério por um efeito de card do oponente (exceto durante a Etapa de Dano): você pode escolher 1 Armadilha Normal no seu Cemitério; Baixe-a. \r\nVocê só pode usar cada efeito de "Loris, a Dama da Lamentação" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50702124,'Imã Sincro',replace(replace('Este card não pode ser Invocado por Invocação-Normal ou Baixado. \r\nQuando você Invocar por Invocação-Sincro um Monstro Sincro, você pode Invocar este card por Invocação-Especial da sua mão.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50705071,'Metalzoa',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nVocê primeiro deve Invocá-lo por Invocação-Especial (do seu Deck) ao oferecer como Tributo "Zoa" equipada com "Metalmorfo".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50712728,'Maldição do Coveiro','Se este card for Invocado: cause 500 de dano ao seu oponente.','Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50720316,'Névoa Sombria, o HERÓI do Elemento',replace(replace('Se este card for Invocado por Invocação-Especial: você pode adicionar 1 Card de Magia Rápida "Mudar" do seu Deck à sua mão. \r\nSe este card for enviado para o Cemitério: você pode adicionar 1 monstro "HERÓI" do seu Deck à sua mão, exceto "Névoa Sombria, o HERÓI do Elemento". \r\nVocê só pode usar 1 efeito de "Névoa Sombria, o HERÓI do Elemento" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicione 1 Card de Magia Rápida "Mudar" do seu Deck à sua mão','Adicionar à sua mão 1 monstro "HERÓI" do seu Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50725996,'Cavaleiro Mago Negro',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial com "Título de Cavaleiro" e não pode ser Invocado por Invocação-Especial de nenhuma outra forma. \r\nQuando este card for Invocado por Invocação-Especial: Escolha 1 card no campo; destrua o alvo.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50727844,'Força de Retorno Sincro',replace(replace('Escolha monstros no campo, até o número de Monstros Sincro com nomes diferentes que você controla; devolva-os para a mão. \r\nVocê só pode ativar 1 "Força de Retorno Sincro" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50732780,'Seguranças de Estígia','Se este card for destruído em batalha e enviado para o Cemitério: Invoque por Invocação-Especial do seu Deck 1 monstro do Tipo Demônio de Nível 1.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50750868,'T.G. Lançador de Tridente',replace(replace('2+ Monstros de Efeito, incluindo um Regulador "T.G."	\r\nSe este card for Invocado por Invocação-Link, você pode: Invocar por Invocação-Especial 3 monstros "T.G." (1 da sua mão, 1 do seu Deck e 1 do seu Cemitério) em Posição de Defesa em zonas suas para as quais este card apontar e, além disso, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros "T.G.". \r\nVocê só pode usar este efeito de "T.G. Lançador de Tridente" uma vez por turno. \r\nSeu oponente não pode escolher Monstros Sincro "T.G." para os quais este card apontar como alvo de efeitos de card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50756327,'Crowley, o Primeiro Profevidenta',replace(replace('2 monstros Mago	\r\nSe este card for Invocado por Invocação-Link: você pode revelar 3 cards "Livro de Magia" com nomes diferentes do seu Deck e seu oponente elege 1 deles aleatoriamente para que você adicione à sua mão e, além disso, embaralhe o resto no seu Deck. \r\nVocê só pode usar este efeito de "Crowley, o Primeiro Profevidenta" uma vez por turno. \r\nA cada turno, 1 monstro Mago de Nível 5 ou mais que você Invocar por Invocação-Normal pode ser Invocado sem Tributo.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Invocação Normal sem Tributo','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50766506,'Arte Ninjitsu da Duplicação',replace(replace('Ative este card ao oferecer como Tributo 1 monstro "Ninja"; Invoque por Invocação-Especial qualquer número de monstros "Ninja" do seu Deck, com a face para cima em Posição de Ataque e/ou com a face para baixo em Posição de Defesa, cuja soma dos Níveis seja igual ou menor que o Nível do monstro oferecido como Tributo. \r\nQuando este card deixar o campo, destrua esses monstros.','\r',char(13)),'\n',char(10)),'Continuar a Invocar por Invocação Especial?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50781944,'Antigo Primata Escarlate','Quando um ou mais monstros que você controla forem destruídos e enviados para o Cemitério, ganhe 1000 PV.','Ganhar PV','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50785356,'Guerreiro de Retroalimentação','Quando este card for Invocado por Invocação-Normal ou Invocação-Especial: Você pode escolher 1 monstro com a face para cima que você controla; ele se torna de Nível 3.','Alterar Nível','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50789693,'Kappa com Armadura',replace(replace('2 monstros de Nível 2	\r\nUma vez por turno: você pode desassociar 1 Matéria Xyz deste card; este card ganha 1000 de ATK ou de DEF. \r\nDurante a Etapa de Batalha de cada duelista, enquanto um ataque envolvendo um monstro seu estiver ocorrendo: você pode descartar 1 card; pelo resto do turno, os monstros que você controla não podem ser destruídos em batalha e, além disso, você não sofre dano de batalha. \r\nVocê só pode usar este efeito de "Kappa com Armadura" uma vez por Duelo.','\r',char(13)),'\n',char(10)),'Aumentar ATK/DEF','Não pode ser destruído','Aumentar ATK em 1000','Aumente a DEF em 1000','','','','','','','','','','','','');
INSERT INTO texts VALUES(50793215,'Prima Donna do Mar Profundo',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nSeu oponente não pode escolher um Monstro Sincro que usou este card como matéria como alvo de efeitos de monstro. \r\nVocê só pode usar cada um dos seguintes efeitos de "Prima Donna do Mar Profundo" uma vez por turno.\r\n● Você pode escolher 1 dos cards banidos do seu oponente; adicione à sua mão, ou Invoque por Invocação-Especial, 1 monstro de ÁGUA de Nível 4 ou menos do seu Deck e, se isso acontecer, adicione o alvo à mão do oponente.\r\n● Se este card for enviado para o Cemitério: você pode escolher 1 card banido; embaralhe-o no Deck.','\r',char(13)),'\n',char(10)),'','','O efeito de "Prima Donna do Mar Profundo" está sendo aplicado.','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50797682,'Cronomalia Glifo Esperanza',replace(replace('Durante a Fase Principal: escolha 1 Card de Monstro Xyz que você controla ou no seu Cemitério; Invoque por Invocação-Especial da sua mão, do Deck e/ou do Cemitério, 2 monstros "Cronomalia" que sejam 1 Nível maior que a Classe desse monstro, mas negue seus efeitos e, depois, imediatamente depois que este efeito resolver, Invoque por Invocação-Xyz 1 Monstro Xyz "Cronomalia" usando apenas esses 2 monstros. \r\nVocê só pode ativar 1 "Cronomalia Glifo Esperanza" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50810455,'Kerass da Tri-Brigada',replace(replace('Você pode descartar 1 outro monstro Besta, Besta-Guerreira ou Besta Alada; Invoque este card por Invocação-Especial da sua mão. \r\nVocê pode banir qualquer número de monstros Besta, Besta-Guerreira e/ou Besta Alada no seu Cemitério; Invoque por Invocação-Especial 1 Monstro Link Besta, Besta-Guerreira ou Besta Alada do seu Deck Adicional, com um Valor Link igual ao número de banidos e, além disso, você só pode usar monstros Besta, Besta-Guerreira e Besta Alada como Matéria Link pelo resto deste turno. \r\nVocê só pode usar cada efeito de "Kerass da Tri-Brigada" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50820852,'Simorgh, Pássaro do Início',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode ativar este efeito; durante sua Fase Principal deste turno, você pode Invocar por Invocação-Normal 1 monstro "Simorgh" em adição à sua Invocação-Normal/Baixar (padrão). \r\n(Você só pode se aproveitar deste efeito uma vez por turno.) \r\nSe este card estiver no seu Cemitério e seu oponente não controlar nenhum card na Zona de Magias & Armadilhas dele: você pode Invocar este card por Invocação-Especial em Posição de Defesa, mas bana-o quando ele deixar o campo e, além disso, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros Besta Alada. \r\nVocê só pode usar cada efeito de "Simorgh, Pássaro do Início" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50823978,'Piranha Army','O dano de batalha que este card inflige ao atacar diretamente os Life Points do seu adversário é duplicado.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50834074,'Kaitoptera',replace(replace('Se seu oponente controlar 2 ou mais monstros com a face para cima, exceto monstros de VENTO, esses monstros não podem escolher este card como alvo de ataques. \r\nVocê só pode usar cada um dos seguintes efeitos de "Kaitoptera" uma vez por turno. \r\nDurante sua Fase Principal: você pode adicionar 1 "Polimerização" do seu Deck à sua mão. \r\nSe este card for banido: você pode Invocá-lo por Invocação-Especial e, depois, você pode adicionar 1 "Polimerização" do seu Cemitério à sua mão.','\r',char(13)),'\n',char(10)),'','Adicionar 1 "Polimerização/Fusão" do seu Cemitério à sua mão?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50838440,'Três em Um',replace(replace('Durante a Fase Final do seu oponente, se seu oponente tiver um total de cards maior na mão e no campo dele que os que você tem na sua mão e no campo: Invoque por Invocação-Especial 3 Monstros Normais do seu Cemitério. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 3 Cards de Monstro que você controla com nomes originais diferentes; Baixe 1 Magia/Armadilha da sua mão ou do Deck que mencione os nomes originais de todos os 3 alvos.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50847759,'Última Esperança de Nephthys',replace(replace('Escolha 1 outro card "Nephthys" que você controla e 1 card que seu oponente controla; destrua-os. \r\nVocê só pode ativar 1 "Última Esperança de Nephthys" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50855622,'Hércules Absoluto Ultrabezoudado',replace(replace('4 monstros Inseto	\r\nDepois que este card for Invocado por Invocação-Fusão, ele não é afetado por outros efeitos de card até o final do seu próximo turno. \r\nNo final da Fase de Batalha: você pode escolher 1 monstro Inseto com 3000 ou menos de ATK no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê só pode usar este efeito de "Hércules Absoluto Ultrabezoudado" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50863093,'Irradiador Autômato',replace(replace('Você pode descartar 1 outro monstro "Autômata(o)"; Invoque este card por Invocação-Especial da sua mão. \r\nVocê pode escolher 1 monstro Máquina que você controla; Invoque por Invocação-Especial do seu Cemitério, 1 monstro "Autômata(o)" com um nome diferente e um Nível igual ou menor que o desse monstro e, se isso acontecer, destrua o monstro alvo. \r\nVocê só pode usar cada efeito de "Irradiador Autômato" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50866755,'Fenghuang',replace(replace('Não pode ser Invocado por Invocação-Especial. \r\nDurante a Fase Final do turno em que este card for Invocado por Invocação-Normal ou virado com a face para cima: Devolva-o para a mão. \r\nQuando este card for Invocado por Invocação-Normal ou virado com a face para cima: Destrua todos os Cards de Magia/Armadilha Baixados que seu oponente controla.','\r',char(13)),'\n',char(10)),'Retornar à mão','Destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50893987,'Besta Gladiadora Tygerius',replace(replace('Este card não pode ser usado como um Monstro-Matéria de Fusão. \r\nQuando este card for Invocado por Invocação-Especial pelo efeito de um monstro "Besta Gladiadora", você pode descartar 1 card "Besta Gladiadora" para adicionar 1 monstro "Besta Gladiadora" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50896944,'Braquio Negro','Quando este card for Invocado por Invocação-Normal: você pode escolher 1 monstro no campo; coloque o alvo com a face para cima em Posição de Defesa.','Mudar para Posição de Defesa','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50901852,'Bugiganga Inaba, a Lebre Saltitante de Hakuto',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode Invocar por Invocação-Especial da sua mão, em Posição de Defesa, 1 monstro Máquina cujo ATK seja igual à sua própria DEF. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 monstro Máquina que você controla cujo ATK seja igual à sua própria DEF; neste turno, você não pode declarar ataques, exceto com esse monstro e, além disso, seu ATK/DEF se tornam o ATK original combinado de todos os monstros Máquina que você controla atualmente cujo ATK seja igual à sua própria DEF. \r\nVocê só pode usar este efeito de "Bugiganga Inaba, a Lebre Saltitante de Hakuto" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50903514,'Espadachim da Chama Azul',replace(replace('Uma vez por turno, durante a Fase de Batalha de qualquer duelista: você pode escolher 1 outro monstro do Tipo Guerreiro que você controla; este card perde exatamente 600 de ATK e, se isso acontecer, esse monstro ganha 600 de ATK. \r\nQuando este card que você controla for destruído por um card do seu oponente (em batalha ou por um efeito de card) e enviado para o seu Cemitério: você pode banir este card do seu Cemitério e, depois, escolher 1 monstro de FOGO do Tipo Guerreiro no seu Cemitério; Invoque o alvo por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Alterar ATK/DEF','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50907446,'El Sombraneco Apkallone',replace(replace('2 monstros "Sombraneco" com Atributos diferentes	\r\nPrimeiro deve ser Invocado por Invocação-Fusão. \r\nNão pode ser destruído em batalha. \r\nVocê só pode usar cada um dos seguintes efeitos de "El Sombraneco Apkallone" uma vez por turno.\r\n● Se este card for Invocado por Invocação-Especial: você pode escolher 1 card com a face para cima no campo; negue seus efeitos.\r\n● Se este card for enviado para o Cemitério: você pode adicionar 1 card "Sombraneco" do seu Deck ou Cemitério à sua mão e, depois, descarte 1 card.','\r',char(13)),'\n',char(10)),'Negar o efeito','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50913601,'Montanha','Todos os monstros Dragão, Besta Alada e Trovão no campo ganham 200 de ATK/DEF.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50915474,'Deusa dos Dois Lados',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 monstro do seu Deck à sua mão que tenha um efeito de lançar moeda, exceto "Deusa dos Dois Lados". \r\nDurante sua Fase Principal: você pode lançar uma moeda e escolher cara ou coroa. \r\nSe você ganhar, dobre o ATK de todos os monstros que você controla atualmente até o final deste turno. \r\nSe você perder, envie tantos monstros que você controla quanto possível para o Cemitério (mín. 1) e, se isso acontecer, compre 1 card. \r\nVocê só pode usar cada efeito de "Deusa dos Dois Lados" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Escolher cara ou coroa','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50916353,'Soldado Ctoniano','Quando este card for destruído pelo monstro atacante do oponente e enviado ao Cemitério, o Dano de Batalha que você sofreu nesta batalha também será causado ao oponente.','Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50920465,'Pássaro-trovão da Nevasca',replace(replace('Você pode descartar 1 card; Invoque por Invocação-Especial 2 monstros de ÁGUA do Tipo Besta Alada, 1 da sua mão e 1 do seu Cemitério, exceto "Pássaro-trovão da Nevasca" e, depois, de volta este card do campo para a mão. \r\nVocê só pode usar este efeito de "Pássaro-trovão da Nevasca" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50930991,'Neo, o Espadachim Mágico','Um viajante dimensional que além de praticar as artes mágicas, também é um mestre com a espada e artes marciais.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50933533,'Dragão Gadjiltron do Mecanismo Antigo',replace(replace('Se este card atacar, seu oponente não pode ativar nenhum Card de Magia/Armadilha até o final da Etapa de Dano. \r\nEste card ganha os efeitos apropriados se você Invocá-lo por Invocação-Normal oferecendo como Tributo esses monstros.\r\n● Dispositivo Verde: Se este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente.\r\n● Dispositivo Vermelho: Se este card causar dano de batalha ao seu oponente: cause 400 de dano ao seu oponente.\r\n● Dispositivo Amarelo: Se este card destruir um monstro do oponente em batalha: cause 600 de dano ao seu oponente.','\r',char(13)),'\n',char(10)),'Cause 400 de dano ao seu oponente','Cause 600 de dano ao seu oponente','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50939127,'Dragão de uma Dimensão Diferente',replace(replace('Este card não é destruído pelo efeito de um Card de Magia ou Armadilha que não o designe como alvo. \r\nAinda, este card não é destruído como resultado de um combate com um monstro com um ATK de 1900 ou menos.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50947142,'Sinal de Ferro-Velho',replace(replace('Quando seu oponente ativar um efeito de monstro, enquanto você controlar um Monstro Sincro que mencione um Monstro Sincro como matéria: negue a ativação e, além disso, depois, Baixe este card com a face para baixo em vez de enviá-lo para o Cemitério. \r\nVocê só pode ativar 1 "Sinal de Ferro-Velho" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50951254,'Dragão Magmacho',replace(replace('Você pode banir até 3 monstros de FOGO do seu Cemitério; até o final deste turno, este card ganha 400 de ATK para cada um. \r\nSe um ou mais monstros de FOGO com a face para cima que você controla forem destruídos por um efeito de card, enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial (mas bana-o quando ele deixar o campo) e, depois, compre 1 card. \r\nVocê só pode usar cada efeito de "Dragão Magmacho" uma vez por turno.','\r',char(13)),'\n',char(10)),'Aumentar ATK','Invocar este card por Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50951359,'Captura de Regulador',replace(replace('Ative apenas quando seu oponente Invocar um monstro por Invocação-Sincro. \r\nInvoque por Invocação-Especial 1 Monstro Regulador usado para essa Invocação-Sincro do Cemitério dele no seu lado do campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50954680,'Dragão Sincro de Asas de Cristal',replace(replace('1 Regulador + 1+ Monstros Sincro não-Reguladores	\r\nUma vez por turno, quando o efeito de outro monstro for ativado (Efeito Rápido): você pode negar a ativação e, se isso acontecer, destrua esse monstro e, se isso acontecer, até o final deste turno, este card ganha ATK igual ao ATK original do monstro destruído. \r\nSe este card batalhar um monstro de Nível 5 ou mais do oponente, durante o cálculo de dano: este card ganha ATK igual ao ATK atual do monstro do oponente que ele estiver batalhando, apenas durante esse cálculo de dano.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(50957346,'Terra Enfurecida','Quando este card for destruído em batalha e enviado para o Cemitério, destrua todos monstros com a face para baixo e os que não sejam de TERRA.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51011872,'Trapestrela Coração Carmesim',replace(replace('2 monstros "Trapestrela"	\r\nSempre que um ou mais monstros "Trapestrela" forem Invocados por Invocação-Normal ou Especial em uma ou mais zonas para as quais este card apontar, ganhe 200 PV. \r\nVocê pode descartar 1 card "Trapestrela"; os dois duelistas compram 1 card, mas se os seus PV estiverem pelo menos 2000 acima dos do seu oponente quando este efeito foi ativado, em vez disso, você compra 2 cards. \r\nVocê só pode usar este efeito de "Trapestrela Coração Carmesim" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51020079,'Doutor Ciborgue','Uma vez por turno, você pode oferecer como Tributo 1 monstro Regulador que você controla para Invocar por Invocação-Especial um monstro do seu Cemitério com o mesmo Atributo e Nível do monstro oferecido como Tributo.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51023024,'Wendi Reesombraneco',replace(replace('VIRE: Você pode Invocar por Invocação-Especial 1 monstro "Sombraneco" do seu Deck com a face para cima ou com a face para baixo em Posição de Defesa, exceto "Wendi Reesombraneco".\r\nSe este card for enviado para o Cemitério por um efeito de card: você pode Invocar por Invocação-Especial 1 monstro "Sombraneco" do seu Deck com a face para baixo em Posição de Defesa, exceto "Wendi Reesombraneco". \r\nVocê só pode usar 1 efeito de "Wendi Reesombraneco" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51028231,'Ator do Abismo - Novato Insolente',replace(replace('Escala de Pêndulo = 2\r\n[ Efeito de Pêndulo ]\r\nSe um ou mais monstros "Ator do Abismo" que você controla seriam destruídos em batalha ou por um efeito de card do oponente, em vez disso, você pode destruir este card.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nNa primeira vez que este card seria destruído em batalha ou por um efeito de card a cada turno, ele não é destruído. \r\nSe este card for destruído em batalha, ou se este card na Zona de Monstros do seu dono for destruído por um efeito de card do oponente: você pode Invocar por Invocação-Especial 1 monstro "Ator do Abismo" de Nível 4 ou menos do seu Deck, exceto "Ator do Abismo - Novato Insolente". \r\nSe este card na Zona de Pêndulo for destruído: você pode escolher 1 monstro de Nível 4 ou menos que seu oponente controla; destrua-o.','\r',char(13)),'\n',char(10)),'Usar o efeito de "Ator do Abismo - Novato Insolente" em vez de ser destruído?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51043053,'Dragão da Heliosfera',replace(replace('Enquanto seu oponente tiver 4 ou menos cards na mão dele e este card for o único monstro que você controla, seu oponente não pode declarar um ataque. \r\nUma vez por turno, se você controlar um monstro do Tipo Dragão de Nível 8: você pode fazer com que este card se torne de Nível 8 até o final deste turno.','\r',char(13)),'\n',char(10)),'Alterar Nível','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51043243,'Lombriga Cártaros','VIRE: Adicione 1 monstro "Lombriga" do Tipo Réptil de Nível 4 ou menos do seu Deck à sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51047350,'Rachador de Cards',replace(replace('Este card não pode ser Invocado por Invocação-Normal ou Baixado. \r\nEste card só pode ser Invocado por Invocação-Especial, com a face para cima em Posição de Ataque, ao enviar 1 card da sua Zona de Cards de Magia & Armadilha para o Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51053997,'Acelerador PSÍ-Armação',replace(replace('Uma vez por turno: você pode pagar 500 PV e, depois, escolher 1 monstro "PSÍ-Armação" que você controla; bana-o até sua próxima Fase de Apoio. \r\nUma vez por turno, se outro card "PSÍ-Armação" com a face para cima que você controla deixar o campo (exceto durante a Etapa de Dano): você pode Invocar por Invocação-Especial 1 monstro "PSÍ-Armação" da sua mão.','\r',char(13)),'\n',char(10)),'Ativar, sem aplicar o segundo efeito','Ativar e aplicar o segundo efeito','Banir 1 monstro','Invoque por Invocação Especial um monstro da mão','Retornar o monstro banido ao campo','','','','','','','','','','','');
INSERT INTO texts VALUES(51073802,'Porco-espinho Majespectro - Yamarashi',replace(replace('Escala de Pêndulo = 2\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nDurante a Fase Principal, se você controlar um monstro "Majespectro" (Efeito Rápido): você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 Magia "Majespectro" no seu Cemitério; Baixe-a. \r\nVocê só pode usar cada um dos efeitos anteriores de "Porco-espinho Majespectro - Yamarashi" uma vez por turno. \r\nEnquanto este card estiver em uma Zona de Monstros sua, seu oponente não pode escolhê-lo como alvo de efeitos de card e, além disso, ele não pode ser destruído pelos efeitos de card do seu oponente.','\r',char(13)),'\n',char(10)),'Invocação Especial','Baixar 1 Card de Magia','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51083544,'Tigre da Geada',replace(replace('Se este card for Invocado por Invocação-Especial: você pode adicionar 1 monstro Mago de AGUÁ de Nível 5 ou maior ou "Pilares Gêmeos de Gelo" do seu Deck à sua mão.\r\nVocê só pode usar o efeito de "Tigre da Geada" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51085303,'Rosa Venenosa, o HERÓI do Elemento',replace(replace('Não pode ser Invocado por Invocação-Normal ou Baixado. \r\nDeve ser Invocado por Invocação-Especial com "Botão de Rosa" e não pode ser Invocado por Invocação-Especial de nenhuma outra forma. \r\nSempre que este card causar Dano de Batalha ao oponente: Ele ganha 200 de ATK e perde 200 de DEF. \r\nSeu oponente só pode escolher "Rosa Venenosa, o HERÓI do Elemento" como alvo de ataques.','\r',char(13)),'\n',char(10)),'Alterar ATK/DEF','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51091138,'Fundir Cabos','Enquanto este card estiver Baixado: escolha 1 card no campo na coluna deste card; destrua-o.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51097887,'Ataque Aéreo da Tri-Brigada',replace(replace('Escolha 1 monstro Besta, Besta-Guerreira ou Besta Alada que você controla; Invoque por Invocação-Especial do seu Deck, em Posição de Defesa, 1 monstro Besta, Besta-Guerreira ou Besta Alada com um Tipo diferente e com ATK igual ou menor que o desse monstro, mas seus efeitos são negados até o final deste turno e, além disso, você não pode Invocar monstros por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto Monstros Link. \r\nVocê só pode ativar 1 "Ataque Aéreo da Tri-Brigada" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51099515,'Fantasmas do Passado','Bana 2 monstros do seu Cemitério e, depois, escolha 1 monstro em Posição de Ataque no campo; mude o ATK dele para 0 até o final deste turno.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51119924,'Planta Marionete','Você pode descartar este card para o Cemitério e, depois, escolha 1 monstro Guerreiro ou Mago que seu oponente controla; tome o controle do alvo até a Fase Final.','Tomar controle','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51124303,'Caleidoscópio Necroz',replace(replace('Este card pode ser usado para Invocar por Invocação-Ritual qualquer número de Monstros de Ritual "Necroz". \r\nOfereça como Tributo 1 monstro da sua mão ou do campo, ou envie 1 monstro do seu Deck Adicional para o Cemitério e, além disso, depois, Invoque por Invocação-Ritual qualquer número de monstros "Necroz" cuja soma dos Níveis seja igual ao Nível desse monstro. \r\nVocê só pode usar este efeito de "Caleidoscópio Necroz" uma vez por turno. \r\nSe você não controlar nenhum monstro: você pode banir este card e 1 monstro "Necroz" do seu Cemitério; adicione 1 Magia "Necroz" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Usar como Tributo para cumprir os Níveis necessários para uma Invocação Ritual?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51126152,'Cavaleiro do Expresso Noturno',replace(replace('Não pode ser Invocado por Invocação-Especial do Deck. \r\nVocê pode Invocar este card por Invocação-Normal sem oferecer Tributo, mas seu ATK original se torna 0.','\r',char(13)),'\n',char(10)),'Invocação Normal sem oferecer Tributo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51132012,'Grande Cavaleiro do Lótus Vermelho',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão ou do Cemitério) ao embaralhar até 3 Monstros que não sejam de Efeito do seu Cemitério no Deck/Deck Adicional. \r\nVocê só pode Invocar "Grande Cavaleiro do Lótus Vermelho" por Invocação-Especial uma vez por turno desta forma. \r\nSe Invocado desta forma, este card ganha 800 de ATK para cada Monstro Normal embaralhado no Deck para sua Invocação. \r\nUma vez por turno, você pode escolher 1 monstro no campo e 1 Monstro que não seja de Efeito no seu Cemitério; destrua esse monstro no campo e, se isso acontecer, Invoque por Invocação-Especial esse outro monstro do seu Cemitério.','\r',char(13)),'\n',char(10)),'','Destruir e Invocar por Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51192573,'Gangi''el, Horror Cósmico',replace(replace('Se você oferecer como Tributo um monstro no seu lado do campo que pertença ao oponente, este card pode ser Invocado por Invocação-Normal com 1 Tributo. \r\nUma vez por turno, você pode colocar 1 Marcador-A em um monstro no lado do campo do oponente. \r\n(Se um monstro com um Marcador-A batalhar com um monstro "Alienígena", ele perde 300 de ATK e DEF para cada Marcador-A apenas durante o cálculo de dano).','\r',char(13)),'\n',char(10)),'Invocar por Invocação Tributo com 1 Tributo','Colocar "Marcador-A"','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51194046,'Qliphort Monolito',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nVocê não pode Invocar monstros por Invocação-Especial, exceto monstros "Qli". Este efeito não pode ser negado. Uma vez por turno, durante a Fase Final, se você realizou uma Invocação-Tributo neste turno: você pode comprar um número de cards igual ao número de monstros "Qli" que você ofereceu como Tributo neste turno para a Invocação-Tributo.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nExceção não tratada em 0x1i-666 em qliphort.exe: Violação de acesso em local de gravação 0x00-000\r\nContinuar ignorando esse erro? <S/N>...[ ]\r\nXlmgzxg drgs gsv Hzxivw Givv rh uliyrwwvm. Gsv hxlfitv szh yvvm fmovzhsvw.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51196174,'O Calculador','O ATK deste card é igual ao Nível combinado de todos os monstros com a face para cima que você controla x 300.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51196805,'Esqueleto Fantardil',replace(replace('Não pode ser Invocado por Invocação-Normal, a não ser que você controle um monstro "Fantardil". \r\nUma vez por turno: você pode colocar este card com a face para baixo em Posição de Defesa. \r\nQuando este card for virado com a face para cima: bana cards do topo do Deck do seu oponente, com a face para baixo, até o número de monstros "Fantardil" que você controla. \r\nVocê só pode usar este efeito de "Esqueleto Fantardil" uma vez por turno.','\r',char(13)),'\n',char(10)),'Mudar para Posição de Defesa com a face para baixo','Banir com a face para baixo','Escolha o número de cards a banir','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51205763,'Glial Krawler',replace(replace('VIRE: Você pode Invocar por Invocação-Especial 1 monstro "Krawler" da sua mão ou do Cemitério, em Posição de Ataque com a face para cima ou em Posição de Defesa com a face para baixo, exceto "Glial Krawler".\r\nSe este card com a face para cima sob o controle do seu dono deixar o campo devido a um efeito de card do oponente: você pode Invocar por Invocação-Especial 2 monstros "Krawler" com nomes diferentes do seu Deck em Posição de Defesa com a face para baixo, exceto "Glial Krawler". \r\nVocê só pode usar cada efeito de "Glial Krawler" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Invoque 2 monstros por Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51208046,'Apresentação ao Vivo Trapestrela',replace(replace('Quando este card for ativado: você pode adicionar 1 monstro "Trapestrela" do seu Cemitério à sua mão. \r\nVocê só pode usar cada um dos seguintes efeitos de "Apresentação ao Vivo Trapestrela" uma vez por turno e, além disso, você não pode Invocar monstros por Invocação-Especial no turno em que ativar esses efeitos, exceto monstros "Trapestrela" (mesmo que este card deixe o campo).\r\n● Se você controlar um Monstro Link "Trapestrela": você pode Invocar por Invocação-Especial 1 "Ficha Trapestrela" (Fada/LUZ/Nível 1/ATK 0/DEF 0).\r\n● Se seu oponente controlar um card na Zona de Magias & Armadilhas dele: você pode Invocar por Invocação-Especial 1 "Ficha Trapestrela".','\r',char(13)),'\n',char(10)),'Adicionar à sua mão 1 monstro "Trapestrela" do seu Cemitério?','Invocar uma Ficha por Invocação Especial (Ficha Trapestrela)','Invocar uma Ficha por Invocação Especial (Ficha Trapestrela)','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51208047,'Ficha Trapestrela','Invocado por Especial com o efeito "Apresentação ao Vivo Trapestrela" ou um card relacionado.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51208877,'Explosão Causada pelo Destino',replace(replace('Quando um monstro do oponente declarar um ataque: destrua o 1 monstro que seu oponente controla com o maior ATK (em caso de empate, você seleciona) e, se isso acontecer, cause dano ao seu oponente igual ao ATK original dele e, depois, se "Troca de Espírito" não estiver no seu Cemitério, você sofre dano igual ao dano que ele sofreu. \r\nSe este card for enviado da mão ou do Deck para o Cemitério: você pode escolher 1 monstro Fada de TERRA de Nível 4 no seu Cemitério; adicione-o à sua mão. \r\nVocê só pode usar cada efeito de "Explosão Causada pelo Destino" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51225407,'Inverno Mayakashi',replace(replace('Os monstros que seu oponente controla perdem 100 de ATK/DEF para cada monstro "Mayakashi" com um nome diferente no seu Cemitério. \r\nVocê só pode usar 1 dos seguintes efeitos de "Inverno Mayakashi" por turno e apenas uma vez por turno.\r\n● Envie este card e 1 monstro "Mayakashi" que você controla para o Cemitério; compre 1 card.\r\n● Bana este card e 1 monstro Zumbi do seu Cemitério e, depois, escolha 1 monstro "Mayakashi" no seu Cemitério; Invoque-o por Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51227866,'Força Celeste - Mecha - Canhão Tubarão','Se você não controlar nenhum monstro na sua Zona de Monstros Principal: escolha 1 monstro no Cemitério do seu oponente; bana esse monstro, ou, se você tiver 3 ou mais Magias no seu Cemitério, em vez disso, você pode Invocar esse monstro por Invocação-Especial no seu campo, mas ele não pode atacar.','Invocação Especial?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51228280,'Lombriga da Masmorra','Escondido sob o chão de um labirinto, ele engole qualquer um que passe por cima dele.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51232472,'Gren, Estrategista do Mundo Negro','Se este card for descartado para o Cemitério por um efeito de card: escolha 1 Magia/Armadilha no campo; destrua-a.','Destrua 1 Card de Magia ou Armadilha no campo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51250293,'Vento Majespectro',replace(replace('Quando você ativar este card, você também pode oferecer como Tributo 1 monstro Mago de VENTO; Invoque por Invocação-Especial 1 monstro "Majespectro" da sua mão ou do Cemitério ou, se você ofereceu um monstro como Tributo na ativação, em vez disso, você pode Invocar por Invocação-Especial 1 monstro "Majespectro" do seu Deck. \r\nVocê só pode ativar 1 "Vento Majespectro" por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Ativar ao oferecer como Tributo um monstro?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51254277,'Mandíbulas Grandes','No final da Fase de Batalha, se este card atacou: bana-o.','Banir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51254980,'Louva-a-Deus de Naturia','Quando seu oponente Invocar um monstro por Invocação-Normal: você pode enviar 1 monstro "Naturia" da sua mão para o Cemitério; destrua o monstro Invocado.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51267887,'Aumentar a Temperatura Corporal',replace(replace('Só pode ser equipado a um monstro Dinossauro. \r\nEle ganha 300 de ATK/DEF.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51275027,'A Donzela Infeliz','Quando este card é enviado para o Cemitério como resultado de uma batalha, a Battle Phase desse turno termina imediatamente.','Encerrar a Fase de Batalha','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51282878,'Plantador Peixeborgue',replace(replace('Uma vez, enquanto este card estiver no Cemitério: você pode enviar o card do topo do seu Deck para o Cemitério e, depois, se for um monstro de ÁGUA, Invoque este card por Invocação-Especial do Cemitério. \r\nVocê só pode usar este efeito de "Plantador Peixeborgue" uma vez por turno.','\r',char(13)),'\n',char(10)),'Enviar do Deck para o Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51296484,'Saffira, a Rainha Dragão da Voz Sem Voz',replace(replace('Você pode descartar este card; envie 1 Magia de Ritual do seu Deck para o Cemitério e, depois, você pode adicionar 1 Monstro de Ritual (Guerreiro ou Dragão) de LUZ do seu Deck ou Cemitério à sua mão. \r\nVocê pode banir este card do seu Cemitério; Invoque por Invocação-Ritual 1 Monstro de Ritual (Guerreiro ou Dragão) de LUZ da sua mão, ao oferecer como Tributo monstros da sua mão ou do campo cuja soma dos Níveis seja igual ou exceda o Nível do Monstro de Ritual. \r\nVocê só pode usar cada efeito de "Saffira, a Rainha Dragão da Voz Sem Voz" uma vez por turno.','\r',char(13)),'\n',char(10)),'Enviar do Deck para o Cemitério','Adicionar à sua mão um Monstro Ritual?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51303014,'Portar de Luta Wattsíquico',replace(replace('Invoque por Invocação-Especial até 2 monstros de LUZ de Nível 3 ou menos da sua mão. \r\nSe você Invocou 2 monstros com o mesmo Tipo original, esses monstros podem atacar diretamente neste turno. \r\nSe eles tiverem o mesmo Nível original, eles também não podem ser destruídos em batalha neste turno. \r\nVocê só pode ativar 1 "Portar de Luta Wattsíquico" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51316684,'Infernoide Seitsemas',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão ou do Cemitério) ao banir 2 monstros "Infernoide" da sua mão ou do Cemitério enquanto a soma dos Níveis e Classes de todos os Monstros de Efeito que você controla for 8 ou menos. \r\nNo final da Fase de Batalha, se este card atacou um monstro do oponente: você pode banir 1 card no campo. \r\nUma vez por turno (Efeito Rápido): você pode oferecer 1 monstro como Tributo e, depois, escolha 1 card no Cemitério do seu oponente; bana-o.','\r',char(13)),'\n',char(10)),'Banir cards no campo','Banir cards do Cemitério do seu oponente','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51324455,'Ninhada do Submundo','Quando um monstro do Tipo Peixe, Serpente Marinha ou Aqua com a face para cima que você controla for banido: Adicione 1 monstro do Tipo Peixe, Serpente Marinha ou Aqua de Nível 4 ou menos do seu Deck à sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51335426,'Elo Link',replace(replace('Escolha 1 Monstro Link que você controla ou no seu Cemitério; devolva-o para o Deck Adicional e, se isso acontecer, compre cards igual ao seu Valor Link e, depois, coloque cards da sua mão no fundo do Deck, em qualquer ordem, igual ao número de cards que você comprou. \r\nVocê só pode ativar 1 "Elo Link" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51339637,'Rugido Salamagrande',replace(replace('Quando um Card de Magia/Armadilha ou efeito de monstro for ativado enquanto você controlar um Monstro Link "Salamagrande": negue a ativação e, se isso acontecer, destrua esse card. \r\nEnquanto este card estiver no Cemitério, se um Monstro Link "Salamagrande" for Invocado por Invocação-Link no seu campo usando um monstro com seu mesmo nome como matéria: você pode Baixar este card, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar 1 efeito de "Rugido Salamagrande" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51345461,'Caçador das Espadas',replace(replace('No final da Fase de Batalha, se este card destruiu um ou mais monstros em batalha e os enviou para o Cemitério nesta Fase de Batalha: equipe esses monstros do Cemitério a este card como Cards de Magia de Equipamento com este efeito.\r\n● O monstro equipado ganha 200 de ATK.','\r',char(13)),'\n',char(10)),'Equipar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51351302,'Um Homem com Wdjat','Quando você Invoca, por Invocação-Normal, este card e durante cada uma das suas Standby Phases seguintes, escolha 1 card Baixado no Campo do seu adversário, veja-o e devolva o card à sua posição original.','Confirmar','Escolha um card para revelar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51355346,'Alma de Gaia, o Coletivo de Combustível',replace(replace('Uma vez por turno: você pode oferecer como Tributo até 2 monstros do Tipo Piro; este card ganha 1000 de ATK para cada um. \r\nSe este card atacar um monstro em Posição de Defesa, ele causa dano de batalha perfurante ao seu oponente. \r\nDurante a Fase Final: destrua este card.','\r',char(13)),'\n',char(10)),'Aumentar ATK','Destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51365514,'Selo Hierático da Supremacia','Invoque por Invocação-Especial 1 monstro "Hierático" da sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51369889,'Barragem Explosiva',replace(replace('Uma vez por turno, você pode desassociar qualquer número de matérias dos Monstros Xyz Máquina que você controla e, depois, escolha esse número de cards no campo; destrua-os. \r\nSe um ou mais Monstros Xyz Máquina que você controla forem destruídos em batalha ou por um efeito de card do oponente enquanto este card estiver no seu Cemitério: você pode banir este card e 1 Monstro Xyz Máquina do seu Cemitério; cause dano ao seu oponente igual à Classe do monstro banido x 200.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51371017,'Princesa de Tsurugi','VIRE: Inflija 500 pontos de dano aos Life Points do seu adversário para cada Card de Magia e de Armadilha que ele tem no Campo.','Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51391183,'Ator do Abismo - Esperança Selvagem',replace(replace('Escala de Pêndulo = 2\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno: você pode escolher 1 card "Ator do Abismo" na sua Zona de Pêndulo; sua Escala de Pêndulo se torna 9 até o final deste turno e, além disso, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros "Ator do Abismo" (mesmo que este card deixe o campo).\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nUma vez por turno: até o final deste turno, você pode fazer com que este card ganhe 100 de ATK para cada monstro "Ator do Abismo" com nomes diferentes que você controla atualmente. \r\nSe este card for destruído em batalha ou por um efeito de card: você pode adicionar 1 card "Ator do Abismo" do seu Deck à sua mão, exceto "Ator do Abismo - Esperança Selvagem". \r\nVocê só pode usar este efeito de "Ator do Abismo - Esperança Selvagem" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51394546,'Bomba do Cemitério','Inflija ao seu adversário dano igual ao número de cards no Cemitério do seu adversário x 100 pontos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51402177,'Esfinge Teleia',replace(replace('Você pode pagar 500 PV para Invocar este card por Invocação-Especial quando "Pirâmide de Luz" estiver no campo. \r\nEste card não pode atacar durante o turno em que foi Invocado por Invocação-Normal ou Invocação-Especial. \r\nEste card não pode ser Invocado por Invocação-Especial do Cemitério. \r\nSe este card destruir um monstro em Posição de Defesa como resultado de uma batalha, cause dano aos PV do oponente igual à metade da DEF do monstro destruído.','\r',char(13)),'\n',char(10)),'Causar dano aos PV','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51402908,'O Sol da Supremacia',replace(replace('Não pode ser Invocado por Invocação-Especial, exceto por seu próprio efeito. \r\nDepois que este card com a face para cima no campo for destruído e enviado para o Cemitério, durante a Fase de Apoio do próximo turno: você pode descartar 1 card; Invoque este card por Invocação-Especial do Cemitério.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51405049,'Onde Estarás Tu?',replace(replace('Se você controlar um monstro de Nível 1: adicione 1 monstro de Nível 1 do seu Deck à sua mão. \r\nDurante a Fase Final deste turno, sofra 2000 de dano se você não Invocou por Invocação-Normal o monstro adicionado ou um card com o mesmo nome depois de ter ativado este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51409648,'Rindbrumm, o Dragão Atacante',replace(replace('"Caído de Arbaz" + 1 monstro Besta, Besta-Guerreira ou Besta Alada	\r\nQuando um efeito de um Monstro de Fusão, Sincro, Xyz ou Link for ativado (Efeito Rápido): você pode negar o efeito e, depois, você pode devolver 1 monstro do campo para a mão. \r\nDurante o turno do seu oponente, enquanto este card estiver no seu Cemitério (Efeito Rápido): você pode escolher 1 "Caído de Arbaz" no seu Cemitério; Invoque por Invocação-Especial esse monstro ou este card e bana o outro. \r\nVocê só pode usar cada efeito de "Rindbrumm, o Dragão Atacante" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Retornar 1 monstro para a mão?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51412776,'Herança do Cálice',replace(replace('Adicione 1 monstro "Nobre Cavaleiro" ou 1 card "Armas Nobres" do seu Deck ou Cemitério à sua mão. \r\nSe um monstro "Nobre Cavaleiro" seu equipado com uma Magia de Equipamento "Armas Nobres" for destruído em batalha e enviado para o Cemitério, enquanto este card estiver no seu Cemitério: você pode adicionar este card à sua mão. \r\nVocê só pode usar 1 efeito de "Herança do Cálice" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51420096,'Cristal Adamancipador - Tiamite',replace(replace('Se este card for Invocado por Invocação-Especial por um efeito de um card "Adamancipador": você pode adicionar 1 card "Adamancipador" do seu Deck à sua mão, exceto "Cristal Adamancipador - Tiamite", então você pode Invocar por Invocação-Especial 1 monstro Rocha da sua mão.\r\nSe este card está no seu Cemitério: você pode escolher 1 Monstro Sincro Rocha no seu campo ou Cemitério; retorne-o para o Deck Adicional, e se fizer, coloque este card no topo do Deck.\r\nVocê só pode usar cada um dos efeitos de "Cristal Adamancipador - Tiamite" uma vez por turno.','\r',char(13)),'\n',char(10)),'Efeito de busca','Retornar ao Deck','Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51435705,'Cronomalia Caveira de Cristal',replace(replace('Se você controlar um monstro "Cronomalia": Você pode descartar este card para o Cemitério; adicione 1 monstro "Cronomalia" do seu Deck ou Cemitério à sua mão, exceto "Cronomalia Caveira de Cristal". \r\nVocê só pode usar esse efeito de "Cronomalia Caveira de Cristal" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51447164,'T.G. Destruidor Laminado',replace(replace('1 Monstro Sincro Regulador + 1 ou mais Monstros Sincro não-Reguladores	\r\nDurante o turno de qualquer duelista, quando seu oponente ativar um Card de Magia/Armadilha que escolher este card com a face para cima como alvo: você pode enviar 1 card da sua mão para o Cemitério; negue o efeito. \r\nUma vez por turno, durante o turno do seu oponente: você pode banir 1 monstro "T.G." do seu Cemitério; bana este card com a face para cima no campo (este é um Efeito Rápido). \r\nDurante a próxima Fase de Apoio depois que este card foi banido por este efeito: Invoque este card por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Negar os efeitos de Cards de Magia/Armadilha','Banir este card','Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51449743,'Detonação em Cadeia',replace(replace('Cause 500 de dano ao oponente. \r\nCaso este card tenha sido ativado como Elo de Corrente 2 ou 3, adicione-o ao Deck e embaralhe. \r\nCaso este card tenha sido ativado como Elo de Corrente 4 ou mais, devolva-o à mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51452091,'Decreto Real','Negue todos os outros efeitos de Armadilha no campo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51473858,'Motoqueiro Goblin Clatter Explosivo',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 monstro "Goblin" no seu Cemitério, exceto "Motoqueiro Goblin Clatter Explosivo"; Invoque-o por Invocação-Especial. \r\nDurante a Fase Principal do seu oponente, se este card estiver no seu Cemitério (Efeito Rápido): você pode desassociar 1 Matéria Xyz de um monstro em qualquer campo e, se isso acontecer, Invoque este card por Invocação-Especial, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar cada efeito de "Motoqueiro Goblin Clatter Explosivo" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invoque por Invocação Especial 1 monstro do Cemitério','Invocar este card por Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51474037,'Yamorimori',replace(replace('Você pode banir este card do seu Cemitério e, depois, escolha 1 monstro Réptil que você controla e 1 monstro com a face para cima que seu oponente controla, para ativar 1 desses efeitos;\r\n● Coloque esses monstros com a face para baixo em Posição de Defesa.\r\n● Destrua esse monstro que você controla e, se isso acontecer, mude o ATK do outro monstro para 0 até o final deste turno.	\r\nVocê só pode usar este efeito de "Yamorimori" uma vez por turno.','\r',char(13)),'\n',char(10)),'Mudar para Posição de Defesa com a face para baixo','ATK torna-se 0','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51476410,'Lagarto Clock',replace(replace('2 monstros Ciberso	\r\nVocê pode oferecer este card como Tributo; devolva 1 Monstro de Fusão do seu Cemitério para o Deck Adicional e, depois, Invoque esse Monstro de Fusão por Invocação-Fusão do seu Deck Adicional, banindo as Matérias de Fusão listadas nele do seu Cemitério. \r\nSe este card for banido do seu Cemitério: até o final deste turno, você pode fazer com que os monstros Invocados por Invocação-Especial que seu oponente controla atualmente percam 400 de ATK para cada monstro Ciberso atualmente no seu Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51481927,'Absorção de Magia','Sempre que um Card de Magia for ativado, ganhe 500 PV imediatamente depois que ele resolver.','Recuperar PV','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51482758,'Remover Armadilha','Destrói 1 Card de Armadilha que está no Campo com a face para cima.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51497409,'D/D/D Darius, o Rei de Pedra',replace(replace('2 monstros do Tipo Demônio de Nível 3	\r\nUma vez por turno, durante o turno de qualquer duelista: você pode desassociar 1 Matéria Xyz deste card e, depois, escolher 1 card "Pacto Obscuro" que você controla; destrua-o e, se isso acontecer, compre 1 card. \r\nSe este card batalhar um monstro do oponente, durante o cálculo de dano: você pode desassociar 1 Matéria Xyz deste card; faça com que este card não possa ser destruído por essa batalha, depois do cálculo de dano destrua o monstro do oponente que batalhou com ele e, se isso acontecer, cause 500 de dano ao seu oponente.','\r',char(13)),'\n',char(10)),'Destruir e comprar 1 card','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51510279,'Dupla Magichave',replace(replace('Você pode escolher 1 Monstro Normal ou 1 monstro "Magichave" no seu Cemitério; adicione-o à sua mão e, depois, você pode aplicar 1 desses efeitos.\r\n● Invoque por Invocação-Fusão 1 Monstro de Fusão "Magichave" do seu Deck Adicional em Posição de Defesa, usando monstros da sua mão ou do campo como Matéria de Fusão.\r\n● Invoque por Invocação-Ritual 1 Monstro de Ritual "Magichave" da sua mão em Posição de Defesa, ao oferecer como Tributo monstros da sua mão ou do campo cuja soma dos Níveis seja igual ou exceda seu Nível.','\r',char(13)),'\n',char(10)),'Não fazer nada','Invocação Fusão','Invocação Ritual','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51522296,'Dogmatika Arba Zoa',replace(replace('Não pode ser Invocado por Invocação-Ritual, exceto com "Dogmatikalamidade" ou outro efeito de card "Dogmatika". \r\nMonstros "Dogmatika" que você controla não são afetados pelos efeitos ativados dos Monstros de Fusão, Sincro, Xyz e Link do seu oponente. \r\nDurante sua Fase Principal: você pode fazer com que seu oponente selecione e aplique 1 desses efeitos (''você'' nesses efeitos, significa esse oponente).\r\n● Para cada 2 cards no seu Deck Adicional, envie 1 card da sua mão ou do Deck Adicional para o Cemitério.\r\n● Devolva todos os Monstros de Fusão, Sincro, Xyz e Link que você controla para o Deck Adicional.	\r\nVocê só pode usar este efeito de "Dogmatika Arba Zoa" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Enviar 1 card da sua mão ou do Deck Adicional para o Cemitério','Retornar ao Deck Adicional todos os Monstros Fusão, Sincro, Xyz e Link no campo','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51531505,'Mago do Fosso do Dragão',replace(replace('Escala de Pêndulo = 8\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno, se você tiver um card "Mago" na sua outra Zona de Pêndulo: você pode descartar 1 Monstro Pêndulo e, depois, escolher 1 Card de Magia/Armadilha no campo; destrua-o.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nEste mago talentoso pode despertar a energia guardada nas profundezas da terra, conhecida como Fosso do Dragão. Sua visão impassível normalmente não faz muitos amigos e ele frequentemente cede aos desejos do seu pupilo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51534754,'Navio Yomi','Se este card for destruído em batalha e enviado para o Cemitério: destrua o monstro que destruiu este card.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51543904,'Número 99: Dragão Utópico',replace(replace('3 monstros de Nível 10	\r\nVocê também pode Invocar este card por Invocação-Xyz ao descartar 1 Card de Magia "Magia de Aumento de Classe" e usar um monstro "Utopia" que você controla como uma Matéria Xyz. \r\n(Matérias Xyz associadas a esse monstro também se tornam Matéria Xyz neste card.) \r\nUma vez por turno: você pode escolher 1 monstro "Número" no seu Cemitério; Invoque-o por Invocação-Especial em Posição de Defesa, mas seus efeitos são negados. \r\nDurante o turno de qualquer duelista, quando um efeito de monstro que escolher como alvo este card com a face para cima for ativado: você pode desassociar 1 Matéria Xyz deste card; negue a ativação e, se isso acontecer, destrua o card.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Xyz sobrepondo um monstro "Utópico"?','Invocação Especial','Negar a ativação e destruir','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51546708,'Regulador Sombrio Mão do Pesadelo',replace(replace('Você pode revelar este card na sua mão; imediatamente após ativar este efeito, Invoque por Invocação-Normal 1 monstro "Regulador Sombrio". \r\nVocê só pode usar este efeito de "Regulador Sombrio Mão do Pesadelo" uma vez por turno.\r\nSe este card for Invocado por Invocação-Normal: você pode Invocar por Invocação-Especial 1 monstro de Nível 2 ou menor da sua mão.\r\nUma vez por turno, se você controla este card Invocado por Invocação-Normal/Baixado: você pode oferecer como Tributo este card com a face para cima e 1 não-Regulador com a face para cima com Nível menor, e se fizer, Invoque por Invocação-Especial 1 Monstro Sincro do seu Deck Adicional com Nível igual a diferença entre os Níveis daqueles monstros (isso é considerado uma Invocação-Sincro), então você pode destruir 1 card que seu oponente controla.','\r',char(13)),'\n',char(10)),'Invocação Normal','Invocação Especial','Invocação Sincro','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51548207,'Dragão Ocofoguette',replace(replace('Quando um efeito de Monstro Link for ativado que escolha como alvo este card com a face para cima no campo (Efeito Rápido): você pode destruir este card e, depois, escave até 6 cards do topo do Deck do seu oponente e bana 1 deles e, se isso acontecer, coloque o resto no topo do Deck na mesma ordem. \r\nDurante a Fase Final, se este card estiver no Cemitério porque foi destruído no campo, em batalha ou por um efeito de card, e enviado para lá neste turno: você pode Invocar por Invocação-Especial 1 monstro "Foguette" do seu Deck, exceto "Dragão Ocofoguette". \r\nVocê só pode usar cada efeito de "Dragão Ocofoguette" uma vez por turno.','\r',char(13)),'\n',char(10)),'Banir o Deck','Invocação Especial','Escolha a quantidade de cards a revelar','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51549976,'Inzektição Final','Envie 5 cards "Inzektor" com a face para cima que você controla ao Cemitério; destrua todos os cards que seu oponente controla e, além disso, durante a Fase de Batalha deste turno, seu oponente não pode ativar efeitos de monstro que ativam na mão ou Cemitério.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51554871,'Kayenn, o Forjador-Mestre do Magma','Você pode banir este card do seu Cemitério; todos os monstros "Laval" com a face para cima que você controla atualmente ganham 400 de ATK.','Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51555725,'Quebrador de Restolhos',replace(replace('Se seu oponente controlar um monstro, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nSe Invocado desta forma: escolha 1 monstro "Restolhos" que você controla; destrua o alvo.','\r',char(13)),'\n',char(10)),'Destrua um monstro cujo nome contenha "Restolhos"','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51562916,'Onda Pequena da Onda Grande','Destrua tantos monstros de ÁGUA que você controla quanto possível e, depois, você pode Invocar por Invocação-Especial monstros de ÁGUA da sua mão, até o número de monstros destruídos por este efeito.','Invocar por Invocação Especial um monstro de ÁGUA?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51566770,'Guardião Inférnico','Enquanto você não tiver cards na sua mão, este card com a face para cima não pode ser destruído em batalha ou por efeitos de card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51570882,'Dragão Fusão de Peçonha Voraz',replace(replace('1 monstro "Predaplanta" + 1 monstro de TREVAS cujo Nível original seja 8 ou mais	\r\nPrimeiro deve ser Invocado por Invocação-Fusão. \r\nUma vez por turno: você pode escolher 1 monstro com a face para cima no campo; até o final deste turno, mude o ATK do alvo para 0 e, além disso, o alvo tem seus efeitos negados. \r\nSe este card for destruído e enviado para o Cemitério: destrua tantos monstros no campo quanto possível e, depois, você pode banir 1 monstro de TREVAS de Nível 8 ou mais do seu Cemitério e Invocar este card por Invocação-Especial do Cemitério.','\r',char(13)),'\n',char(10)),'Negar o efeito','Destruir tudo','Invocar "Dragão Fusão de Peçonha Voraz" por Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51578214,'Rolador de Assalto Bezoudado',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) ao banir 1 monstro Inseto do seu Cemitério. \r\nVocê só pode Invocar "Rolador de Assalto Bezoudado" por Invocação-Especial uma vez por turno desta forma. \r\nGanha 200 de ATK para cada monstro Inseto que você controla, exceto este card. \r\nQuando este card for destruído em batalha: você pode adicionar 1 monstro "Bezoudado" do seu Deck à sua mão, exceto "Rolador de Assalto Bezoudado". \r\nVocê só pode usar este efeito de "Rolador de Assalto Bezoudado" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51589188,'Tridente de Fóton',replace(replace('Escolha 1 monstro "Fóton" com a face para cima que você controla; até a Fase Final, ele ganha 700 de ATK, e se ele atacar um monstro em Posição de Defesa, cause Dano de Batalha perfurante ao seu oponente. \r\nQuando ele causar Dano de Batalha ao seu oponente neste turno: Você pode escolher 1 Card de Magia/Armadilha no campo; destrua o alvo.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51606429,'Os Cavaleiros Fantasmas do Escudo Sepulcral',replace(replace('Invoque este card por Invocação-Especial em Posição de Ataque como um Monstro Normal (Guerreiro/TREVAS/Nível 3/ATK 0/DEF 0).	\r\n(Este card NÃO é considerado como uma Armadilha.) \r\nDurante o seu turno, exceto no turno em que este card foi enviado para o Cemitério: você pode banir este card do seu Cemitério e, depois, escolher 1 Armadilha com a face para cima que seu oponente controla; negue seus efeitos até o final deste turno.','\r',char(13)),'\n',char(10)),'Negar os efeitos de Cards de Armadilha com a face para cima','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51611041,'Epigonen, o Invasor Personificador',replace(replace('Você pode oferecer como Tributo 1 Monstro de Efeito: Invoque este card por Invocação-Especial da sua mão e, depois, Invoque por Invocação-Especial 1 "Ficha de Epigonos" (Nível 1/ATK 0/DEF 0) com o mesmo Tipo e Atributo que o Tipo e Atributo originais do monstro oferecido como Tributo. \r\nVocê só pode usar este efeito de "Epigonen, o Invasor Personificador" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51611042,'Ficha de Epigonos','Invocado por Especial com o efeito "Epigonen, o Invasor Personificador".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51612489,'Motivo do Motim',replace(replace('Escolha 1 monstro com a face para baixo em Posição de Defesa no campo; devolva-o para a mão e, depois, o duelista cujo card foi adicionado à sua mão pode Invocar por Invocação-Especial 1 monstro da mão dele com a face para baixo em Posição de Defesa. \r\nQuando um monstro do oponente declarar um ataque: você pode banir este card do seu Cemitério; coloque 1 monstro que está com a face para baixo em Posição de Defesa no campo, com a face para cima em Posição de Ataque. \r\nVocê só pode usar cada efeito de "Motivo do Motim" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar','Posição de batalha','Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51616747,'Guardião Nubian','Quando este card inflige dano de batalha aos Life Points do seu adversário, você pode devolver 1 Card de Magia Contínua do seu Cemitério para o topo do seu Deck.','Retornar ao Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51617185,'Megaforma Autômata',replace(replace('Você pode oferecer este card como Tributo; Invoque por Invocação-Especial 1 monstro "Autômata(o)" da sua mão ou do Deck, exceto "Megaforma Autômata". \r\nSe uma "Fortaleza Autômata" com a face para cima que você controla for enviada para o seu Cemitério enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode banir essa "Fortaleza Autômata" do Cemitério; Invoque este card por Invocação-Especial. \r\nVocê só pode usar 1 efeito de "Megaforma Autômata" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51618973,'Avance, Espadachim de Necroz',replace(replace('Se você Invocar por Invocação-Ritual exatamente 1 Monstro de Ritual "Necroz" com um efeito de card que requer o uso de monstros, este card que você controla pode ser usado como todo o Tributo. \r\nQuando este card for Invocado por Invocação-Normal: você pode Invocar por Invocação-Especial 1 monstro "Necroz" do seu Deck, exceto "Avance, Espadachim de Necroz". \r\nSe este card for oferecido como Tributo por um efeito de card: você pode adicionar qualquer número dos seus cards "Necroz" banidos com nomes diferentes à sua mão. \r\nVocê só pode usar este efeito de "Avance, Espadachim de Necroz" uma vez por Duelo.','\r',char(13)),'\n',char(10)),'Invocação Especial','Recuperar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51630558,'Compra Avançada','Ofereça como Tributo 1 monstro com a face para cima de Nível 8 ou mais que você controla; compre 2 cards.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51632798,'Dragão Fuzileiro, a Besta de Dois Modos','Você pode Invocar este card por Invocação-Normal/Baixar sem oferecer Tributo, mas seu ATK e DEF originais são reduzidos à metade.','Invocar por Invocação Normal sem Tributo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51638941,'V-Jato Tigre','Este ás lutador é invencível em batalhas aéreas. Ele combina com outros monstros para lançar uma série de ataques cercantes.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51644030,'Diabólico Kernel',replace(replace('Quando este card declarar um ataque: ele ganha 600 de ATK. \r\n(Efeito Rápido): você pode escolher 1 monstro com a face para cima que seu oponente controla; até o final deste turno, ele perde ATK igual ao ATK atual deste card e, depois, bana este card até a Fase de Apoio do próximo turno. \r\nVocê só pode usar este efeito de "Diabólico Kernel" uma vez por turno.','\r',char(13)),'\n',char(10)),'Este card ganha 60 ATK','Reduzir o ATK do monstro do oponente','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51650038,'Sobremesa Magidoce',replace(replace('Escolha 2 Monstros de Efeito no campo, incluindo um monstro "Magidoce"; devolva esses Monstros de Efeito para a mão/o Deck Adicional e, depois, você pode Invocar por Invocação-Especial 1 monstro "Magidoce" da sua mão ou do Deck Adicional com ATK igual ou menor que o ATK original total desses monstros devolvidos. \r\nSe um ou mais cards "Magidoce" forem embaralhados do seu Cemitério no Deck/Deck Adicional, enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode associar este card a um Monstro Xyz que você controla. \r\nVocê só pode usar 1 efeito de "Sobremesa Magidoce" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Recuperar e Invocar por Invocação Especial','Tornar-se Matéria Xyz','Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51669847,'Plano Saqueado do Patrono do Poder - Vidólio',replace(replace('Você pode revelar 1 monstro "Patrono(a) do Poder" no seu Deck Adicional; bana (com a face para baixo) 1 card da sua mão e, depois, adicione à sua mão ou Invoque por Invocação-Especial, 1 monstro do seu Deck que mencione o nome desse monstro revelado (exceto por sua cláusula de restrição de "uma vez por turno"). \r\nVocê só pode usar este efeito de "Plano Saqueado do Patrono do Poder - Vidólio" uma vez por turno. \r\nMonstros que seu oponente controla perdem 100 de ATK para cada card banido. \r\nSeu oponente não pode ativar os efeitos de cards no Cemitério, enquanto você controlar "Nerva, a Patrona do Poder da Criação", "Júpiter, o Patrono do Poder da Destruição" e "Junora, o Patrono do Poder da Afinação".','\r',char(13)),'\n',char(10)),'Ativar','Efeito de busca','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51670553,'Espada Bambu Devoradora de Almas',replace(replace('Escolha 1 monstro equipado com uma Magia de Equipamento "Espada Bambu". \r\nSe o alvo causar dano de batalha ao seu oponente: ele pula sua próxima Fase de Compra se o alvo equipado ainda estiver no campo nesse momento. \r\nDestrua este card durante sua 2ª Fase de Apoio depois da ativação.','\r',char(13)),'\n',char(10)),'Pular a Fase de Compra','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51684157,'Círculo do Dragão Celestial',replace(replace('Ofereça como Tributo 1 monstro Wyrm; adicione 1 monstro Wyrm do seu Deck à sua mão ou, se você ofereceu como Tributo um Monstro que não seja de Efeito para ativar este card, em vez disso, você pode Invocá-lo por Invocação-Especial, mas negue seus efeitos. \r\nDurante sua Fase Principal, se você controlar um Monstro que não seja de Efeito com a face para cima: você pode banir este card do seu Cemitério; adicione 1 card "Tenyi" do seu Deck à sua mão. \r\nVocê só pode usar 1 efeito de "Círculo do Dragão Celestial" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Escolha um card para adicionar à sua mão ou Invocar por Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51686645,'Protesto Vingativo',replace(replace('Escolha 1 monstro com a face para cima que seu oponente controla; equipe este card no alvo. \r\nEle ganha 500 de ATK/DEF. \r\nSe este card for enviado para o Cemitério porque o monstro equipado deixou o campo: compre 1 card ou, em vez disso, se você ativou este card neste turno, compre 2 cards e, depois, descarte 1 card. \r\nVocê só pode usar este efeito de "Protesto Vingativo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51697825,'Jack-na-Mão',replace(replace('Revele 3 monstros de Nível 1 com nomes diferentes do seu Deck, seu oponente adiciona 1 à mão dele, você adiciona 1 à sua mão e você embaralha o terceiro no Deck. \r\nVocê só pode ativar 1 "Jack-na-Mão" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51701885,'Telepon D.D.',replace(replace('Se este card com a face para cima que você controla for banido: Você pode banir 1 monstro do Tipo Psíquico com 1500 ou menos de ATK do seu Deck. \r\nDepois, durante sua próxima Fase de Apoio, se este card ainda estiver banido: Invoque por Invocação-Especial o monstro banido por este efeito.','\r',char(13)),'\n',char(10)),'Banir','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51706604,'Nevasca',replace(replace('Escolha 1 Magia com a face para cima que seu oponente controla; neste turno, negue os efeitos ativados dessa Magia e de todas as Magias no campo com esse mesmo nome original. \r\nSe o card alvo seria enviado para o Cemitério do oponente neste turno, em vez disso, adicione-o à mão dele. \r\nVocê só pode ativar 1 "Nevasca" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51717541,'Fuga Inférnica','Se você não tiver cards na sua mão: escolha 1 card "Inférnico(a)" no seu Cemitério e 1 card que seu oponente controla; bana o primeiro alvo e, se isso acontecer, destrua o segundo alvo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51728779,'Senhor Obscuro Amdusc',replace(replace('Você pode descartar este card e 1 card "Senhor(a) Obscuro(a)" e, depois, escolha 1 card "Senhor(a) Obscuro(a)" no seu Cemitério; adicione-o à sua mão. \r\n(Efeito Rápido): você pode pagar 1000 PV e, depois, escolha 1 Magia/Armadilha "Senhor(a) Obscuro(a)" no seu Cemitério; aplique o efeito de ativação do alvo e, depois, embaralhe o alvo no Deck. \r\nVocê só pode usar cada efeito de "Senhor Obscuro Amdusc" uma vez por turno. \r\nVocê só pode Invocar um ou mais "Senhor Obscuro Amdusc" por Invocação-Especial uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51735257,'Número 50: Navio Negro de Milho',replace(replace('2 monstros de Nível 4	\r\nUma vez por turno: você pode desassociar 1 Matéria Xyz deste card e, depois, escolher 1 monstro com a face para cima que seu oponente controla com ATK menor ou igual a este card; envie-o para o Cemitério e, se isso acontecer, cause 1000 de dano ao seu oponente. \r\nEste card não pode atacar no turno em que você ativar este efeito.','\r',char(13)),'\n',char(10)),'Enviar para o Cemitério e causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51773900,'Magia Calmante',replace(replace('Este card só pode ser ativado no começo da Fase Principal 1. \r\nDurante as Fases Principais e Fase de Batalha deste turno, nenhum duelista pode Invocar monstros.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51777272,'Gata Dançarina Luzlunar',replace(replace('2 monstros "Luzlunar"	\r\nNão pode ser destruído em batalha. \r\nUma vez por turno, durante sua Fase Principal 1: você pode oferecer como Tributo 1 outro monstro "Luzlunar"; pelo resto deste turno, na primeira vez que cada monstro que seu oponente controla seria destruído em batalha, ele não é destruído e, além disso, neste turno, este card pode atacar todos os monstros que seu oponente controla, duas vezes cada. \r\nSe este card declarar um ataque: cause 100 de dano ao seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51779204,'Força de Poder Absoluta',replace(replace('Escolha 1 "Dragão Vermelho Arquidemônio" que você controla; se esse monstro que você controla batalhar um monstro do oponente neste turno, aplique esses efeitos até o final da Etapa de Dano.\r\n● Ele ganha 1000 de ATK.\r\n● Seu oponente não pode ativar cards ou efeitos.\r\n● Se ele atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente.\r\n● Qualquer dano de batalha que seu oponente sofrer dessa batalha é dobrado.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51782995,'Defensora de Nephthys',replace(replace('Durante sua Fase Principal: você pode destruir 1 card na sua mão e, se isso acontecer, Invoque por Invocação-Especial 1 monstro "Nephthys" de Nível 4 ou menos da sua mão, exceto "Defensora de Nephthys". \r\nDurante sua próxima Fase de Apoio depois que este card foi destruído por um efeito de card e enviado para o Cemitério: você pode destruir 1 monstro "Nephthys" no seu Deck, exceto "Defensora de Nephthys". \r\nVocê só pode usar cada efeito de "Defensora de Nephthys" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51786039,'Dragão Nébula',replace(replace('Você pode revelar este card e 1 outro monstro Dragão de Nível 8 na sua mão; Invoque os dois por Invocação-Especial em Posição de Defesa, mas negue seus efeitos e, além disso, você não pode Invocar por Invocação-Normal ou Especial pelo resto deste turno, exceto monstros Dragão de LUZ ou de TREVAS. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 monstro Dragão de LUZ ou de TREVAS de Nível 4 no seu Cemitério; adicione-o à sua mão. \r\nVocê só pode usar cada efeito de "Dragão Nébula" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51788412,'Gigante do Mecanismo Antigo do Caos',replace(replace('4 monstros "Mecanismo Antigo"	\r\nDeve ser Invocado por Invocação-Fusão. \r\nNão é afetado por efeitos de Magia/Armadilha. \r\nSeu oponente não pode ativar efeitos de monstro durante a Fase de Batalha. \r\nPode atacar todos os monstros que seu oponente controla, uma vez cada. \r\nSe este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51790181,'Pote de Benevolência',replace(replace('Escolha 2 cards do(s) \r\nCemitério(s) e embaralhe-os no(s) \r\nDeck(s) do(s) dono(s). \r\nDepois da ativação, remova este card de jogo em vez de enviá-lo ao Cemitério. \r\nVocê só pode ativar 1 "Pote de Benevolência" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51808422,'Sabre-XX Faultroll',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao controlar 2 ou mais monstros "Sabre-X". \r\nUma vez por turno: você pode escolher 1 monstro "Sabre-X" de Nível 4 ou menos no seu Cemitério; Invoque-o por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51814159,'Ataqueraptor - Abutre Necro','Uma vez por turno: você pode oferecer como Tributo 1 monstro "Ataqueraptor" e, depois, escolher 1 Card de Magia "Magia de Aumento de Classe" no seu Cemitério; adicione-o à sua mão e, além disso, você não pode Invocar por Invocação-Xyz pelo resto deste turno, exceto pelo efeito de um Card de Magia "Magia de Aumento de Classe".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51822687,'Felicidade Expurrely',replace(replace('2 monstros de Nível 7	\r\nVocê também pode Invocar este card por Invocação-Xyz usando um monstro de Classe 2 que você controla com 5 ou mais matérias. \r\n(Transfira as matérias dele para este card.) \r\nDurante sua Fase Principal: você pode desassociar 1 matéria deste card e, se isso acontecer, até o final deste turno, negue os efeitos de todos os monstros com a face para cima que seu oponente controla atualmente. \r\nSeu oponente não pode ativar cards ou efeitos em resposta à ativação deste efeito se este card tiver um monstro "Purrely" de Nível 1 como matéria. \r\nQuando um ataque for declarado envolvendo este card que tenha 5 ou mais matérias: cause 1500 de dano ao seu oponente.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Xyz sobrepondo seu monstro de Classe 2 com 5 ou mais matérias?','Negar os efeitos de todos os monstros do oponente','Cause 1500 de dano ao seu oponente','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51826619,'Guerreiro Ímã Sigma Plus',replace(replace('Enquanto você controlar um monstro de TERRA, os monstros do seu oponente que podem atacar devem atacar monstros de TERRA. \r\nEnquanto seu oponente controlar um monstro de TERRA, você seleciona os alvos dos ataques do seu oponente. \r\nSe este card for enviado para o Cemitério: você pode escolher 1 monstro "Guerreiro Ímã" de Nível 4 ou menos no seu Cemitério, exceto "Guerreiro Ímã Sigma Plus"; adicione-o à sua mão ou Invoque-o por Invocação-Especial. \r\nVocê só pode usar este efeito de "Guerreiro Ímã Sigma Plus" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Efeito de recuperação','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51827737,'Genex Reciclado','Uma vez por turno: você pode escolher 1 monstro "Genex" no seu Cemitério; o nome deste card se torna o nome desse monstro até a Fase Final.','Alterar nome','Escolha 1 monstro cujo nome contenha "Genex"','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51828629,'Giltia, o Cavaleiro D.','"Guardião do Labirinto" + "Protetora do Trono"','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51831560,'Cavaleiro-Gema Nepyrim',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 card "Cavaleiro-Gema" do seu Deck à sua mão, exceto "Cavaleiro-Gema Nepyrim" e, além disso, qualquer dano de efeito que seu oponente sofrer durante a Fase Principal deste turno é diminuído pela metade. \r\nDurante sua Fase Principal, você pode: imediatamente depois que este efeito resolver, Invocar por Invocação-Normal 1 monstro "-Gema". \r\nSe este card for enviado da mão ou do Deck para o Cemitério: você pode enviar 1 card da sua mão para o Cemitério e, se isso acontecer, Invoque este card por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Cavaleiro-Gema Nepyrim" uma vez por turno.','\r',char(13)),'\n',char(10)),'Efeito de busca','Invocação Normal adicional','Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51838385,'Pesadelo de Theban','Ganha 1500 de ATK enquanto você não tiver cards na sua mão nem nas suas Zonas de Magias & Armadilhas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51849216,'Masmorra da Dragunidade',replace(replace('Quando seu oponente ativar um Card de Magia/Armadilha enquanto você controlar um Monstro Sincro "Dragunidade": negue a ativação e, se isso acontecer, bana esse card e, depois, se você controlar um monstro "Dragunidade" de Nível 10, você pode fazer com que 1 monstro "Dragunidade" que você controla ganhe 100 de ATK para cada card com a face para cima que estiver banido atualmente. \r\nVocê só pode ativar 1 "Masmorra da Dragunidade" por turno.','\r',char(13)),'\n',char(10)),'Aumentar o ATK de um monstro?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51849482,'Finis Terrae, a Torre do Necromundo',replace(replace('Se você controlar um monstro de Nível 10, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Finis Terrae, a Torre do Necromundo" por Invocação-Especial uma vez por turno desta forma. \r\nSe este card for enviado para o Cemitério: você pode escolher 1 card com a face para cima no campo; esse card não pode ser destruído por efeitos de card neste turno. \r\nVocê só pode usar este efeito de "Finis Terrae, a Torre do Necromundo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51852507,'Arqueiro das Rosas','Quando seu oponente ativar um Card de Armadilha enquanto você controlar um monstro Planta (Efeito Rápido): você pode enviar este card da sua mão para o Cemitério; negue a ativação e, se isso acontecer, destrua-o.','Negar a ativação de uma Armadilha e destruí-la','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51855378,'Laminador Sucata','Você pode banir 1 monstro "Sucata" no seu Cemitério; este card ganha 400 de ATK até o final deste turno.','Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51858200,'Predaplaneta',replace(replace('Se um monstro com um Marcador de Predador deixar o campo enquanto este card estiver com a face para cima no campo: adicione 1 card "Predap" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Predaplaneta" uma vez por turno. \r\nVocê pode banir este card do seu Cemitério; Invoque por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional, usando monstros da sua mão ou do campo como Matérias de Fusão. \r\nSomente monstros "Predaplanta" podem ser usados como Matérias de Fusão para uma Invocação-Fusão realizada por este efeito.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51858306,'Wivern do Eclipse',replace(replace('Se este card for enviado para o Cemitério: bana 1 monstro Dragão de LUZ ou de TREVAS de Nível 7 ou mais do seu Deck. \r\nSe este card for banido do seu Cemitério: você pode adicionar à sua mão o monstro banido pelo efeito deste card.','\r',char(13)),'\n',char(10)),'Banir','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51865604,'ZS - Sábio do Sumiço',replace(replace('Se você controlar um monstro "Utopia": você pode comprar 1 card. \r\nSe um ou mais monstros que você controla forem banidos durante a Fase de Batalha (exceto durante a Etapa de Dano): você pode banir este card do campo e, depois, escolher 1 desses monstros banidos; Invoque o alvo por Invocação-Especial e, se isso acontecer, bana 1 monstro que seu oponente controla com 3000 de ATK ou menos. \r\nVocê só pode usar 1 efeito de "ZS - Sábio do Sumiço" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Comprar','Invocar por Invocação Especial e banir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51869363,'Explosão de Plasma Supercondutor',replace(replace('Ative o seguinte efeito dependendo de quem é o turno;\r\n● Seu: Coloque 1 monstro Trovão ou Rocha do seu Deck no topo do seu Deck e, depois, se você tiver um monstro Trovão ou Rocha no seu campo ou Cemitério, você pode destruir 1 card no campo.\r\n● Oponente: Adicione 1 monstro Trovão ou Rocha do seu campo, Cemitério ou banimento à sua mão, ou se um ou mais monstros foram destruídos em batalha ou por um efeito de card neste turno, em vez disso, você pode adicionar 1 desses monstros do seu Deck.	\r\nVocê só pode ativar 1 "Explosão de Plasma Supercondutor" por turno.','\r',char(13)),'\n',char(10)),'Ativar','Destruir o card?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51912531,'Semente Mística Macrocarpa',replace(replace('Não pode ser usado como um Monstro Matéria Sincro, exceto para a Invocação-Sincro de um monstro de TERRA. \r\nVocê pode escolher 1 monstro de TERRA no campo; reduza o Nível dele em 1. \r\nVocê só pode usar o efeito de "Semente Mística Macrocarpa" até duas vezes por turno.','\r',char(13)),'\n',char(10)),'Reduzir o Nível em 1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51916032,'Jinzo - Jector',replace(replace('O nome deste card se torna "Jinzo" enquanto ele estiver no campo ou no Cemitério. \r\nVocê pode oferecer este card como Tributo; adicione 1 monstro "Jinzo" do seu Deck à sua mão, exceto "Jinzo - Jector" e, depois, revele todos os cards Baixados nas Zonas de Magias & Armadilhas do seu oponente e, se houver Armadilhas entre eles, você pode Invocar monstros "Jinzo" da sua mão por Invocação-Especial, até o número de Armadilhas reveladas. \r\nVocê só pode usar este efeito de "Jinzo - Jector" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Invocar por Invocação Especial um monstro "Jinzo"?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51916853,'Cão de Caça Mágico',replace(replace('Se este card estiver na sua mão ou no Cemitério: você pode escolher 1 Magia/Armadilha com a face para cima que seu oponente controla; devolva-a para a mão e, se isso acontecer, Invoque este card por Invocação-Especial. \r\nVocê só pode usar este efeito de "Cão de Caça Mágico" uma vez por Duelo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51925772,'Dragão de Dreadlock','Quando este card for destruído em batalha e enviado para o Cemitério, você pode adicionar 1 monstro do Tipo Dragão de Nível 3 ou menos do seu Deck para a sua mão.','Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51933043,'Ataqueraptor - Águia Infame',replace(replace('Se todos os monstros que você controla forem monstros "Ataqueraptor" (mín. 1): você pode Invocar este card por Invocação-Especial da sua mão. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 Magia/Armadilha "Ataqueraptor" no seu Cemitério; adicione-o à sua mão. \r\nVocê só pode usar cada efeito de "Ataqueraptor - Águia Infame" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51934376,'Kabazauls','Um monstro enorme com a forma de um hipopótamo. O espirro do seu gigantesco corpo é tão feroz que as pessoas confundem-no com um furacão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51945556,'Zaborg o Trovão Monarca','Se este card for Invocado por Invocação-Tributo: escolha 1 monstro no campo; destrua o alvo.','Destrua 1 monstro no campo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51960178,'Fada Menina de Torcida',replace(replace('2 monstros do Tipo Fada de Nível 4	\r\nVocê pode desassociar 1 Matéria Xyz deste card; compre 1 card. \r\nVocê só pode usar este efeito de "Fada Menina de Torcida" uma vez por turno.','\r',char(13)),'\n',char(10)),'Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51962254,'Coruja Caçadora',replace(replace('Este card ganha 500 de ATK para cada monstro de VENTO com a face para cima que você controla. \r\nEnquanto você controlar outro monstro de VENTO com a face para cima, seu oponente não pode selecionar este card como alvo de um ataque.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51976476,'Buraco Armadilha Duplo',replace(replace('Se seu oponente Invocar um ou mais monstros por Invocação-Especial em Posição de Defesa: bana esse(s) monstro(s) que foi(ram) \r\nInvocado(s) e atualmente está(ão) em Posição de Defesa.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51987571,'Guerreiro Pedregulho',replace(replace('Você não sofre Dano de Batalha das batalhas envolvendo este card. \r\nQuando este card atacante for destruído em batalha e enviado para o Cemitério, Invoque por Invocação-Especial 2 "Ficha de Pedregulho" (Tipo Rocha/TERRA/Nível 1/ATK 0/DEF 0). \r\nEssas Fichas não podem ser oferecidas como Tributo para uma Invocação-Tributo.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51987572,'Ficha de Pedregulho','Invocado por Especial com o efeito "Guerreiro Pedregulho". Esta Ficha não pode ser oferecida como Tributo para uma Invocação-Tributo.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(51993760,'Espírito Negro do Banimento',replace(replace('Se um monstro do seu oponente atacar, no começo da Etapa de Dano: você pode enviar este card da sua mão ou do campo para o Cemitério e, depois, escolha 1 monstro Demônio de Nível 8 no seu Cemitério; Invoque-o por Invocação-Especial, mas seus efeitos são negados e, se isso acontecer, mude o alvo do ataque para ele e realize o cálculo de dano. \r\nSe um ou mais monstros Demônio de Nível 8 forem enviados para o seu Cemitério enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode adicionar este card à sua mão. \r\nVocê só pode usar cada efeito de "Espírito Negro do Banimento" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Adicionar este card à sua mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52020510,'Alerta Dinomorfia',replace(replace('Pague metade dos seus PV; Invoque por Invocação-Especial até 2 monstros "Dinomorfia" do seu Cemitério cuja soma dos Níveis seja igual a 8 ou menos, mas você não pode declarar um ataque com eles neste turno e, além disso, você não pode Invocar por Invocação-Especial pelo resto deste turno, exceto monstros "Dinomorfia". \r\nQuando seu oponente ativar um card ou efeito, enquanto seus PV forem 2000 ou menos: você pode banir este card do seu Cemitério; neste turno, você não sofre dano de efeito dos efeitos de card do seu oponente. \r\nVocê só pode ativar 1 "Alerta Dinomorfia" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52022648,'Cauda de Fadas - Rella',replace(replace('Nenhum duelista pode escolher monstros no campo como alvo de Cards de Magia ou seus efeitos, exceto este. \r\nUma vez por turno: você pode descartar 1 Magia; equipe 1 Magia de Equipamento da sua mão, do Deck ou do Cemitério a este card, mas devolva essa Magia de Equipamento para a mão durante a Fase Final.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52031567,'Homem-Bola-de-Lama, o HERÓI do Elemento',replace(replace('"Homem Bolha, o HERÓI do Elemento" + "Clayman, o HERÓI do Elemento"	\r\nDeve ser Invocado por Invocação-Fusão e não pode ser Invocado por Invocação-Especial de nenhuma outra forma.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52035300,'O Bushi Imortal',replace(replace('Enquanto este card estiver com a face para cima no campo, ele não pode ser oferecido como Tributo, exceto para a Invocação-Tributo de um monstro do Tipo Guerreiro. \r\nDurante sua Fase de Apoio, se este card estiver no seu Cemitério e todos os monstros no seu Cemitério forem do Tipo Guerreiro: você pode Invocar este card por Invocação-Especial. \r\nAlém disso, você não pode controlar nenhum monstro para ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52038272,'Infernoide Harmadik',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao banir 1 monstro "Infernoide" da sua mão ou do Cemitério enquanto a soma dos Níveis e Classes de todos os Monstros de Efeito que você controla for 8 ou menos. \r\nUma vez por turno: você pode escolher 1 monstro no campo; destrua-o. \r\nEste card não pode atacar no turno em que este efeito for ativado. \r\nUma vez por turno do oponente (Efeito Rápido): você pode oferecer 1 monstro como Tributo e, depois, escolha 1 card no Cemitério do seu oponente; bana-o.','\r',char(13)),'\n',char(10)),'Destruir um monstro','Banir cards do Cemitério do seu oponente','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52038441,'Fantasma Chorão & Calafrio da Meia-noite',replace(replace('Se seu oponente Invocar um ou mais monstros por Invocação-Especial com a face para cima (exceto durante a Etapa de Dano): você pode descartar este card e, depois, escolha 1 desses monstros com a face para cima; negue seus efeitos até o final deste turno e, além disso, se esse monstro com a face para cima deixar o campo neste turno, seu controlador sofre dano igual ao ATK original dele. \r\nVocê só pode usar este efeito de "Fantasma Chorão & Calafrio da Meia-noite" uma vez por turno.','\r',char(13)),'\n',char(10)),'Negar os efeitos dos monstros Invocados por Invocação Especial','O efeito de "Fantasma Chorão & Calafrio da Meia-noite" está sendo aplicado.','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52038442,'Fantasma Chorão & Calafrio da Meia-noite',replace(replace('Se seu oponente Invocar um ou mais monstros por Invocação-Especial com a face para cima (exceto durante a Etapa de Dano): você pode descartar este card e, depois, escolha 1 desses monstros com a face para cima; negue seus efeitos até o final deste turno e, além disso, se esse monstro com a face para cima deixar o campo neste turno, seu controlador sofre dano igual ao ATK original dele. \r\nVocê só pode usar este efeito de "Fantasma Chorão & Calafrio da Meia-noite" uma vez por turno.','\r',char(13)),'\n',char(10)),'Negar os efeitos dos monstros Invocados por Invocação Especial','O efeito de "Fantasma Chorão & Calafrio da Meia-noite" está sendo aplicado.','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52038443,'Fantasma Chorão & Calafrio da Meia-noite',replace(replace('Se seu oponente Invocar um ou mais monstros por Invocação-Especial com a face para cima (exceto durante a Etapa de Dano): você pode descartar este card e, depois, escolha 1 desses monstros com a face para cima; negue seus efeitos até o final deste turno e, além disso, se esse monstro com a face para cima deixar o campo neste turno, seu controlador sofre dano igual ao ATK original dele. \r\nVocê só pode usar este efeito de "Fantasma Chorão & Calafrio da Meia-noite" uma vez por turno.','\r',char(13)),'\n',char(10)),'Negar os efeitos dos monstros Invocados por Invocação Especial','O efeito de "Fantasma Chorão & Calafrio da Meia-noite" está sendo aplicado.','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52040216,'Dragão de Estimação da Harpia','Ganha 300 de ATK/DEF para cada "Lady Harpia" no campo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52068432,'Necroz de Trishula',replace(replace('Você pode Invocar este card por Invocação-Ritual com qualquer Magia de Ritual "Necroz". \r\nDeve ser Invocado por Invocação-Ritual, usando monstros, e você não pode usar monstros de Nível 9. \r\nVocê só pode usar cada um desses efeitos de "Necroz de Trishula" uma vez por turno.\r\n● Quando um card ou efeito for ativado que escolha como alvo um ou mais monstros "Necroz" que você controla (Efeito Rápido): você pode descartar este card; negue a ativação.\r\n● Quando este card for Invocado por Invocação-Ritual, você pode: banir exatamente 3 cards do seu oponente, 1 de cada da mão, do campo e do Cemitério dele. \r\n(O card na mão é selecionado aleatoriamente.)','\r',char(13)),'\n',char(10)),'Negar o efeito','Banir 1 card','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52068433,'Necroz de Trishula',replace(replace('Você pode Invocar este card por Invocação-Ritual com qualquer Magia de Ritual "Necroz". \r\nDeve ser Invocado por Invocação-Ritual, usando monstros, e você não pode usar monstros de Nível 9. \r\nVocê só pode usar cada um desses efeitos de "Necroz de Trishula" uma vez por turno.\r\n● Quando um card ou efeito for ativado que escolha como alvo um ou mais monstros "Necroz" que você controla (Efeito Rápido): você pode descartar este card; negue a ativação.\r\n● Quando este card for Invocado por Invocação-Ritual, você pode: banir exatamente 3 cards do seu oponente, 1 de cada da mão, do campo e do Cemitério dele. \r\n(O card na mão é selecionado aleatoriamente.)','\r',char(13)),'\n',char(10)),'Negar o efeito','Banir 1 card','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52077741,'Guarda Celta Re-treinado','Não pode ser destruído em batalha com um monstro com 1900 ou mais de ATK.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52083044,'Ladrão do Tempo Temporwhal',replace(replace('Você pode oferecer este card como Tributo e, depois, escolha 1 monstro que seu oponente controla; bana-o até a Fase Final. \r\nSe este card estiver no seu Cemitério: você pode escolher 1 monstro "Ladrão do Tempo" que você controla, exceto "Ladrão do Tempo Temporwhal"; devolva esse monstro para a mão e, se isso acontecer, Invoque este card por Invocação-Especial, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar cada efeito de "Ladrão do Tempo Temporwhal" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52085072,'Distopia, o Desesperado',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão ou do Cemitério) ao enviar 4 monstros de Nível 1 com a face para cima que você controla para o Cemitério e não pode ser Invocado por Invocação-Especial de nenhuma outra forma. \r\nOutros monstros que você controla não podem atacar. \r\nDurante a Etapa de Batalha de qualquer duelista, uma vez por batalha envolvendo este card: você pode banir 1 monstro de Nível 1 do seu Cemitério; até o final da Etapa de Dano, este card não é afetado por outros efeitos de card e, além disso, ele não pode ser destruído em batalha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52090844,'Bowganian','Uma vez por turno, durante sua Fase de Apoio: cause 600 de dano ao seu oponente.','Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52097679,'Escudo & Espada','Até o final deste turno, troque o ATK original com a DEF original de todos os monstros com a face para cima atualmente no campo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52098461,'Ira de Neos','Escolha 1 "Neos, o HERÓI do Elemento" na sua Zona de Monstros; embaralhe esse "Neos, o HERÓI do Elemento" no Deck e, se isso acontecer, destrua todos os cards no campo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52101615,'As Trevas - Fusão Selada por Feitiço',replace(replace('Você pode substituir este card por qualquer 1 Monstro-Matéria para a Fusão. \r\nQuando faz isto, o(s) outro(s) \r\nMonstro-Matéria para a Fusão têm de ser o(s) correto(s). \r\nOfereça como Tributo Monstros-Matéria para a Fusão incluíndo este card no Campo para Invocar, por Invocação-Especial, 1 Monstro de Fusão das TREVAS do seu Deck de Fusão.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52105192,'Arsenal Oculto',replace(replace('Envie o card do topo do seu Deck para o Cemitério; adicione 1 Magia de Equipamento do seu Deck ou Cemitério à sua mão. \r\nVocê não pode Invocar por Invocação-Normal/Baixar no turno em que ativar este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52112003,'Avançar Card',replace(replace('Olhe até 5 cards do topo do seu Deck e, depois, coloque-os no topo do Deck em qualquer ordem. \r\nNeste turno, você pode Invocar 1 monstro por Invocação-Tributo em adição à sua Invocação-Normal/Baixar (padrão). \r\n(Você só pode se aproveitar deste efeito uma vez por turno.)','\r',char(13)),'\n',char(10)),'Invocar pelo efeito de "Avançar Card"','Escolha a quantidade de cards a revelar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52119435,'Transversionista Geonadora',replace(replace('2 Monstros de Efeito	\r\nEste card linkado e os monstros para os quais ele aponta não podem ser destruídos pelos efeitos de card do seu oponente. \r\nSe este card apontar para 2 monstros: você pode trocar o controle desses monstros. \r\nVocê só pode usar este efeito de "Transversionista Geonadora" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52121290,'Dama Espiral','Muitos foram enganados pela beleza desta vampira.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52126602,'Gen, o Tigre de Diamante',replace(replace('Uma vez por turno, no final da Fase de Batalha: devolva este card do campo para a mão. \r\nVocê só pode usar cada um dos seguintes efeitos de "Gen, o Tigre de Diamante" uma vez por turno. \r\nDurante sua Fase Principal: você pode Invocar por Invocação-Especial 1 "Ken, o Dragão Guerreiro" da sua mão ou do Deck no campo do seu oponente em Posição de Defesa. \r\nSe este card for Invocado por Invocação-Especial pelo efeito de "Ken, o Dragão Guerreiro": descarte 1 card.','\r',char(13)),'\n',char(10)),'Retornar para a mão','Invocar "Ken, o Dragão Guerreiro" por Invocação Especial','Descarte 1 card','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52128900,'Presente Sincro',replace(replace('Selecione 2 monstros com a face para cima que você controla (1 Monstro Sincro e 1 monstro não-Sincro). \r\nAté a Fase Final deste turno, reduza o ATK do Monstro Sincro para 0 e o outro monstro ganha ATK igual ao ATK original do Monstro Sincro.','\r',char(13)),'\n',char(10)),'Escolha 1 Monstro Sincro','Escolha 1 monstro que não seja Sincro','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52140003,'Ouriço-do-Mar Explosivo',replace(replace('Ative apenas quando seu oponente ativar um Card de Armadilha. \r\nDurante sua Fase de Apoio: Cause 1000 de dano ao seu oponente. \r\nSeu oponente deve controlar um Card de Armadilha com a face para cima para que você ative e resolva este efeito. \r\nDurante sua 3ª Fase Final, depois da ativação, envie este card ao Cemitério.','\r',char(13)),'\n',char(10)),'Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52145422,'Alicercinza Dragão',replace(replace('1 Regulador do Tipo Aqua + 1 ou mais monstros não-Reguladores	\r\nQuando este card for Invocado por Invocação-Sincro: você pode escolher cards que seu oponente controla, até o número de monstros de ÁGUA usados para a Invocação-Sincro deste card; destrua-os. \r\nSe este card for destruído em batalha ou por um efeito de card e enviado para o Cemitério: você pode escolher 1 outro monstro de ÁGUA no seu Cemitério; Invoque-o por Invocação-Especial, mas seus efeitos são negados. \r\nVocê só pode usar cada efeito de "Alicercinza Dragão" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52155219,'Círculo Salamagrande',replace(replace('Ative 1 desses efeitos;\r\n● Adicione 1 monstro "Salamagrande" do seu Deck à sua mão.\r\n● Escolha 1 Monstro Link "Salamagrande" que você controla que foi Invocado por Invocação-Link usando um monstro com seu mesmo nome como matéria; esse Monstro Link não é afetado por efeitos de monstro neste turno, exceto seus próprios.	\r\nVocê só pode ativar 1 "Círculo Salamagrande" por turno.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Efeito de proteção','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52158283,'Cronomalia Cabeça Colossal',replace(replace('Você pode banir este card do seu Cemitério para escolher 1 monstro de Nível 3 ou mais em Posição de Ataque no campo; mude-o para Posição de Defesa com a face para cima ou com a face para baixo. \r\nO efeito de "Cronomalia Cabeça Colossal" só pode ser usado uma vez por turno.','\r',char(13)),'\n',char(10)),'Mudar a posição de batalha','Mudar para Posição de Defesa com a face para cima','Mudar para Posição de Defesa com a face para baixo','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52159691,'Asa do Raptor',replace(replace('(Este card deve ser sempre considerado como um card "Os Cavaleiros Fantasmas" e "Ataqueraptor".)	\r\nSe este card estiver na sua mão ou no Cemitério: você pode desassociar 1 matéria de um Monstro Xyz de TREVAS seu; Invoque este card por Invocação-Especial, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar este efeito de "Asa do Raptor" uma vez por turno. \r\nUm Monstro Xyz cujo Atributo original seja TREVAS e que tenha este card como matéria ganha este efeito.\r\n● Seu oponente não pode escolher este card como alvo de efeitos de card.','\r',char(13)),'\n',char(10)),'','','Escolha o card da qual você vai desassociar a Matéria Xyz','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52176579,'Entrada Cristron',replace(replace('Invoque por Invocação-Especial 2 Reguladores "Cristron" (1 da sua mão e 1 do seu Cemitério). \r\nDurante o turno de qualquer duelista, exceto no turno em que este card foi enviado para o Cemitério: você pode banir este card do seu Cemitério e, depois, escolher 1 monstro "Cristron" que você controla; envie 1 monstro "Cristron" do seu Deck para o Cemitério cujo Nível seja diferente que o desse monstro e, se isso acontecer, esse monstro se torna do Nível desse monstro enviado para o Cemitério. \r\nVocê só pode usar este efeito de "Entrada Cristron" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52182715,'Poerio Verde',replace(replace('Não pode ser usado como Matéria Fusão, Sincro ou Xyz para uma Invocação. \r\nEnquanto este card estiver no campo com a face para cima, ele não pode ser oferecido como Tributo. \r\nQuando este card, no campo, for destruído: o controlado escolhe 1 Card de Magia/Armadilha que ele controla; devolva o alvo para a mão. \r\nVocê só pode controlar 1 "Poerio Verde" com a face para cima.','\r',char(13)),'\n',char(10)),'Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52198054,'Recarregar Acelerador de Explosão',replace(replace('O nome deste card se torna "Tri-Acelerador de Explosão" enquanto ele estiver na Zona de Magias & Armadilhas. \r\nDurante a Fase Principal: você pode enviar 1 card "Vulcânico(a)" da sua mão para o Cemitério e, se isso acontecer, compre 1 card. \r\nVocê só pode usar este efeito de "Recarregar Acelerador de Explosão" uma vez por turno. \r\nDurante a Fase Principal: você pode banir este card do seu Cemitério; envie 1 card "Vulcânico(a)" do seu Deck para o Cemitério.','\r',char(13)),'\n',char(10)),'Usar o efeito de "Recarregar Acelerador de Explosão"?','Enviar para o Cemitério','Ativar e aplicar o efeito','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52222372,'Turbina Genex','Enquanto você controlar este card com a face para cima, todos os monstros "Genex" com a face para cima que você controla ganham 400 de ATK','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52228131,'Aparar','Devolva 1 card "Besta Gladiadora" da sua mão para o Deck, e negue a ativação e efeito de um Card de Armadilha, e destrua-o.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52240819,'Ator do Abismo - Calcanhar Malvado',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno: você pode oferecer como Tributo 1 monstro "Ator do Abismo" e, depois, escolher 1 monstro com a face para cima que seu oponente controla; até o final deste turno, ele perde ATK igual ao ATK original do monstro oferecido como Tributo (mesmo que este card deixe o campo).\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 monstro com a face para cima que seu oponente controla; até o final deste turno, ele perde 1000 de ATK para cada monstro "Ator do Abismo" que você controla. \r\nQuando este card destruir um monstro do oponente em batalha: você pode escolher 1 Card de Magia "Script do Abismo" no seu Cemitério; Baixe esse card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52248570,'Arquidemônio Rainha Aprisionada',replace(replace('Uma vez por turno, durante sua Fase de Apoio, você deve pagar 1000 PV (isso não é opcional), ou este card é destruído. \r\nUma vez por turno, durante sua Fase de Apoio: escolha 1 monstro Demônio de Nível 4 ou menos no campo; o alvo ganha 1000 de ATK até o final deste turno. "Pandemônio" deve estar no campo e este card deve estar no seu Cemitério para ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52253888,'Médium Lei da Luz',replace(replace('No começo da Fase de Batalha do seu oponente: você pode escolher qualquer número de monstros em Posição de Ataque que seu oponente controla; enquanto este card estiver na sua Zona de Monstros, esses monstros devem atacar este card neste turno, se possível. \r\nUma vez por turno, quando um ataque for declarado envolvendo este card e um monstro em Posição de Ataque do oponente: você pode negar o ataque e, se isso acontecer, cause dano ao seu oponente igual à metade do ATK original desse monstro do oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52254878,'Alótropo Dimensional Varis',replace(replace('Não pode ser destruído em batalha com um monstro com o mesmo Tipo ou Atributo que o deste card. \r\nVocê pode declarar 1 Tipo de Monstro e 1 Atributo; este card se torna desse Tipo e Atributo até o final do turno do seu oponente. \r\nVocê só pode usar este efeito de "Alótropo Dimensional Varis" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52263685,'Goblin Curioso',replace(replace('Seu oponente revela os 3 cards do topo do Deck dele. \r\nEscolha um para colocar no fundo do Deck e coloque os outros dois no topo do Deck em qualquer ordem.','\r',char(13)),'\n',char(10)),'Escolha um card para colocar no fundo do Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52265835,'Rudra, Aliado da Justiça','Se este card batalhar um monstro de LUZ, ele ganha 700 de ATK apenas durante a Etapa de Dano.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52277807,'Salamagrande Espiraloso',replace(replace('Se você controlar um card "Salamagrande": você pode descartar este card e, depois, escolher 1 monstro com a face para cima no campo; ele ganha 500 de ATK até o final deste turno. \r\nSe você controlar um monstro "Salamagrande" que não seja "Salamagrande Espiraloso" e este card estiver no seu Cemitério: você pode Invocar este card por Invocação-Especial, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar cada efeito de "Salamagrande Espiraloso" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52286175,'Reator de Armadilha・DO','Uma vez por turno, quando seu oponente ativar um Card de Armadilha, você pode destruir o Card de Armadilha e causar 800 de dano ao seu oponente.','Destrua e cause dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52296675,'Anchamoufrite',replace(replace('Escala de Pêndulo = 4\r\n[ Efeito de Pêndulo ]\r\nSe você não tiver cards no seu Deck Adicional, exceto "Anchamoufrite": você pode destruir este card e, depois, compre 1 card. \r\nVocê só pode usar este efeito de "Anchamoufrite" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nNão pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (com a face para cima do seu Deck Adicional) ao não ter cards no seu Deck Adicional, exceto "Anchamoufrite". \r\nVocê só pode Invocar "Anchamoufrite" por Invocação-Especial uma vez por turno desta forma. \r\nSe este card com a face para cima na Zona de Monstros deixar o campo, bana-o.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52319752,'Veloci Negro',replace(replace('Se este card atacar um monstro do oponente, este card ganha 400 de ATK, apenas durante a Etapa de Dano. \r\nSe este card for atacado por um monstro do oponente, este card perde 400 de ATK, apenas durante a Etapa de Dano.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52323207,'Golem Sentinela',replace(replace('Uma vez por turno: você pode colocar este card com a face para baixo em Posição de Defesa. \r\nQuando este card for Invocado por Invocação-Virar: escolha 1 monstro que seu oponente controla; devolva o alvo para a mão.','\r',char(13)),'\n',char(10)),'Mudar para Posição de Defesa com a face para baixo','Retornar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52323874,'Ataqueraptor - Águia Demônio',replace(replace('2 monstros "Ataqueraptor" de Nível 3	\r\nVocê pode desassociar 1 Matéria Xyz deste card e, depois, escolher 1 monstro com a face para cima Invocado por Invocação-Especial que seu oponente controla; cause dano ao seu oponente igual ao ATK original dele no campo. \r\nVocê só pode usar este efeito de "Ataqueraptor - Águia Demônio" uma vez por turno.','\r',char(13)),'\n',char(10)),'Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52331012,'Rugal, o Protetor de Prata da Tri-Brigada',replace(replace('2+ monstros Besta, Besta-Guerreira e/ou Besta Alada	\r\nDurante a Fase Principal do seu oponente (Efeito Rápido): você pode Invocar por Invocação-Especial 1 monstro Besta, Besta-Guerreira ou Besta Alada de Nível 4 ou menos da sua mão ou do Cemitério, mas negue seus efeitos e, além disso, devolva-o para a mão durante a Fase Final. \r\nSe este card for enviado para o Cemitério: até o final deste turno, você pode fazer com que todos os monstros que seu oponente controla atualmente percam 300 de ATK para cada Tipo de Monstro que você controla. \r\nVocê só pode usar cada efeito de "Rugal, o Protetor de Prata da Tri-Brigada" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52335937,'Traição da Exoirmã',replace(replace('Quando este card for ativado: adicione 2 monstros "Exoirmã" do seu Deck à sua mão e, depois, descarte 1 card. \r\nVocê pode escolher 1 monstro com a face para cima que você controla; imediatamente depois que este efeito resolver, Invoque por Invocação-Normal 1 monstro "Exoirmã" mencionado nesse monstro. \r\nSe um ou mais monstros forem enviados para o Cemitério do seu oponente, mesmo durante a Etapa de Dano: você pode ativar este efeito; seu oponente bane 1 deles. \r\nVocê só pode usar cada efeito de "Traição da Exoirmã" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar','Invocação Normal adicional','Efeito de banimento','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52339733,'Lindorescer','Se um monstro que você controla batalhar um monstro do oponente, durante o cálculo de dano: até o final da Etapa de Dano, o ATK de cada monstro nessa batalha se torna igual à DEF dele.','Alterar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52340274,'Luz da Rainha da Galáxia','Escolha 1 monstro de Nível 7 ou mais com a face para cima que você controla; os Níveis de todos os outros monstros com a face para cima que você controla atualmente se tornam o Nível atual desse monstro até a Fase Final.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52340444,'Força Celeste - Mecha - Drones Zangões','Se você não controlar nenhum monstro na sua Zona de Monstros Principal: Invoque por Invocação-Especial 1 "Ficha de Força Celeste - Ás" (Guerreiro/TREVAS/Nível 1/ATK 0/DEF 0) em Posição de Defesa, mas ela não pode ser oferecida como Tributo e, se você tiver 3 ou mais Magias no seu Cemitério quando este efeito resolver, em vez disso, o ATK/DEF dessa Ficha se tornam 1500.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52340445,'Ficha de Força Celeste - Ás','Invocado por Especial com o efeito "Força Celeste - Mecha - Drones Zangões". Esta Ficha não pode ser oferecida como Tributo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52346240,'Gato de Fechadura',replace(replace('Quando este card for Invocado por Invocação-Normal, você pode selecionar 1 monstro do Tipo Besta de Nível 1 no seu Cemitério e Invocá-lo por Invocação-Especial com a face para cima em Posição de Defesa. \r\nSeus efeitos são negados.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52350806,'Perigo! Homem-Mariposa!',replace(replace('Você pode revelar este card na sua mão; seu oponente seleciona aleatoriamente 1 card de toda a sua mão e, depois, você descarta o card selecionado. \r\nDepois, se o card descartado não era "Perigo! Homem-Mariposa!", Invoque por Invocação-Especial 1 "Perigo! Homem-Mariposa!" da sua mão e, se isso acontecer, compre 1 card. \r\nSe este card for descartado: você pode fazer com que os dois duelistas comprem 1 card e, depois, os dois duelistas descartam 1 card. \r\nVocê só pode usar este efeito de "Perigo! Homem-Mariposa!" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52352005,'Sabre-XX Gottoms',replace(replace('1 Regulador + 1+ monstros de TERRA	\r\nVocê pode oferecer como Tributo 1 monstro "Sabre-X"; descarte 1 card aleatório da mão do seu oponente.','\r',char(13)),'\n',char(10)),'Seu oponente descarta 1 card(s) aleatoriamente','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52354896,'Mechamático Multiplicação',replace(replace('Você pode escolher 1 monstro Ciberso de Nível 4 que você controla; o Nível dele se torna 8 até o final deste turno. \r\nSe este card for enviado para o Cemitério: você pode escolher 1 monstro Ciberso que você controla na Zona de Monstros Adicional; o ATK dele se torna o dobro até o final deste turno. \r\nVocê só pode usar cada efeito de "Mechamático Multiplicação" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52367652,'A Bruxa que se Alimenta da Vida','Um monstro que se alimenta da energia de outras criaturas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52370835,'Desafiante Heroico - Espadescudo','Se você controlar um monstro "Heroico(a)" (Efeito Rápido): você pode enviar este card da sua mão para o Cemitério; pelo resto deste turno, você não sofre dano de batalha e, além disso, monstros "Heroico(a)" que você controla não podem ser destruídos em batalha neste turno.','Não pode ser destruído','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52382379,'Devorador dos Sonhos de Nemleria - Reveil',replace(replace('Se este card estiver na sua mão ou no Cemitério: você pode banir, com a face para baixo, 3 cards do seu Deck Adicional, exceto "Nemleria Sonhadora"; Invoque este card por Invocação-Especial. \r\nVocê não pode Invocar monstros por Invocação-Especial do Deck Adicional no turno em que ativar este efeito, exceto Monstros Pêndulo. \r\nVocê pode enviar para o Cemitério 1 outro monstro Besta de Nível 10 da sua mão ou do campo com a face para cima; Baixe 1 Armadilha "Nemleria" diretamente do seu Deck. \r\nVocê só pode usar cada efeito de "Devorador dos Sonhos de Nemleria - Reveil" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52394047,'Naumaquia do Gladiador',replace(replace('Enquanto você controlar um monstro "Besta Gladiadora", todos os monstros que seu oponente controla devem atacar, se possível. \r\nUma vez por turno: você pode embaralhar 1 monstro "Besta Gladiadora" da sua mão ou do Cemitério no Deck Principal e, depois, escolha 1 monstro "Besta Gladiadora" que você controla; até o final deste turno, ele ganha ATK igual à sua DEF original (mesmo que este card deixe o campo). \r\nSe este card na Zona de Magias & Armadilhas for destruído por um efeito de card: você pode ativar este efeito; neste turno, monstros "Besta Gladiadora" que você controla não podem ser destruídos em batalha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52404456,'Mensagelado Magidoce',replace(replace('Se este card em sua posse for destruído por um card do oponente e enviado para o seu Cemitério: embaralhe este card no Deck. \r\nQuando este card for Invocado por Invocação-Especial: você pode adicionar 1 Magia/Armadilha "Magidoce" do seu Deck à sua mão. \r\nVocê deve controlar um monstro Besta "Magidoce" com a face para cima para ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Retornar ao Deck','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52417194,'Ruína','Se seu oponente tiver 8 ou mais cards na mão dele: ele embaralha toda a sua mão no Deck e, depois, compra 2 cards.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52430902,'Saltador Psíquico','Uma vez por turno: você pode pagar 1000 PV e, depois, escolher 1 monstro com a face para cima que seu oponente controla e 1 monstro do Tipo Psíquico que você controla, exceto "Saltador Psíquico"; troque o controle desses alvos e, se isso acontecer, suas posições de batalha não podem ser mudadas neste turno.','Trocar o controle','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52445243,'Mestre Tri-Lâmina',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro: você pode aplicar o efeito apropriado, de acordo com os Níveis usados para sua Invocação-Sincro ou, se você usou 3 ou mais monstros como matéria, aplique todos esses efeitos, em sequência.\r\n● 1 & 5: Destrua 1 outro card no campo.\r\n● 2 & 4: Compre 1 card.\r\n● 3 & 3: Considere este card como um Regulador.	\r\nVocê só pode usar este efeito de "Mestre Tri-Lâmina" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52467217,'Gozuki',replace(replace('Durante sua Fase Principal: você pode enviar 1 monstro Zumbi do seu Deck para o Cemitério. \r\nSe este card for enviado para o Cemitério: você pode banir 1 monstro Zumbi do seu Cemitério, exceto "Gozuki"; Invoque por Invocação-Especial 1 monstro Zumbi da sua mão. \r\nVocê só pode usar cada efeito de "Gozuki" uma vez por turno.','\r',char(13)),'\n',char(10)),'Envie um monstro Zumbi do Deck para o Cemitério','Invoque por Invocação Especial um monstro Zumbi da sua mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52472775,'Orações da Voz Sem Voz',replace(replace('Este card pode ser usado para a Invocação-Ritual de qualquer Monstro de Ritual de LUZ. \r\nVocê também deve oferecer como Tributo monstros de LUZ da sua mão ou do campo cuja soma dos Níveis seja igual ou exceda o Nível do Monstro de Ritual. \r\nSe um ou mais Monstros de Ritual de LUZ com a face para cima que você controla deixarem o campo por um efeito de card do oponente (exceto durante a Etapa de Dano): você pode banir este card do seu Cemitério; Invoque por Invocação-Especial 1 "Sauravis, o Antigo e Ascenso", "Saffira, a Rainha dos Dragões" ou "Guardião Caveira, o Protetor da Voz Sem Voz" da sua mão ou do Deck, ignorando suas condições de Invocação. \r\nVocê só pode usar este efeito de "Orações da Voz Sem Voz" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52481437,'Trem Bala Super Expresso',replace(replace('Não pode declarar um ataque a não ser que você envie 2 outros cards que você controla para o Cemitério. \r\nVocê só pode usar cada um desses efeitos de "Trem Bala Super Expresso" uma vez por turno.\r\n● Se todos os monstros que você controla forem monstros Máquina de TERRA (mín. 1): você pode Invocar este card por Invocação-Especial da sua mão.\r\n● Durante a Fase Final, se este card estiver no Cemitério porque foi enviado para lá neste turno: você pode escolher 1 monstro Máquina no seu Cemitério, exceto "Trem Bala Super Expresso"; adicione-o à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52495649,'Balameuniere de Nouvelles',replace(replace('Você pode Invocar este card por Invocação-Ritual com um card "Receita". \r\nSe este card for Invocado por Invocação-Especial: você pode adicionar 1 card "Nouvelles" ou "Receita" do seu Deck à sua mão. \r\nVocê pode escolher 1 monstro em Posição de Ataque que seu oponente controla; ofereça-o como Tributo e, se isso acontecer, Invoque por Invocação-Especial 1 Monstro de Ritual "Nouvelles" de Nível 6 da sua mão ou do Deck. \r\nEste é um Efeito Rápido se este card foi Invocado por Invocação-Especial pelo efeito de um monstro "Nouvelles". \r\nVocê só pode usar cada efeito de "Balameuniere de Nouvelles" uma vez por turno.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Invocar por Invocação Especial da sua mão/Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52496105,'Manga de Batalha da Besta Gladiadora',replace(replace('Só pode ser equipado em um monstro "Besta Gladiadora". \r\nEle não pode ser destruído em batalha (o cálculo de dano é aplicado normalmente). \r\nQuando o monstro equipado for devolvido do seu lado do campo para o Deck e este card for enviado para o Cemitério, devolva este card para a sua mão.','\r',char(13)),'\n',char(10)),'Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52497105,'Escamas Frenéticas',replace(replace('Escolha 1 monstro com a face para cima que você controla (exceto um monstro que esteja atacando diretamente); ele ganha 1000 de ATK e, além disso, ele não pode atacar diretamente pelo resto deste turno. \r\nDurante a Fase Final deste turno, ele perde 2000 de ATK.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52502677,'Besta Gladiadora Attorix',replace(replace('Se este card for Invocado por Invocação-Especial pelo efeito de um monstro "Besta Gladiadora": você pode enviar 1 monstro "Besta Gladiadora" do seu Deck ou Deck Adicional para o Cemitério, exceto "Besta Gladiadora Attorix"; até a Fase Final, o Nível e o nome deste card se tornam o mesmo que o desse monstro enviado para o Cemitério. \r\nNo final da Fase de Batalha, se este card batalhou: você pode embaralhá-lo no Deck; Invoque por Invocação-Especial 1 monstro "Besta Gladiadora" do seu Deck, exceto "Besta Gladiadora Attorix".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52503575,'Ordens para o Ataque Final','Todos os monstros com a face para cima no campo são colocados em Posição de Ataque e suas posições de batalha não podem ser mudadas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52512994,'Kasha',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao controlar 2 ou mais monstros Zumbi. \r\nSe este card for Invocado por Invocação-Especial: embaralhe no Deck tantos monstros no campo quanto possível e, se isso acontecer, o ATK deste card se torna 1000 x o número de monstros com a face para cima embaralhados no Deck desta forma, cujo Tipo original era Zumbi.','\r',char(13)),'\n',char(10)),'Retornar ao Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52518793,'Coliseu - Jaula da Besta Gladiadora',replace(replace('Coloque 1 Marcador neste card sempre que um monstro for Invocado por Invocação-Especial do Deck de qualquer duelista. \r\nTodos os monstros "Besta Gladiadora" ganham 100 de ATK e DEF para cada um desses Marcadores neste card. \r\nSe este card seria destruído por um efeito de card, você pode descartar 1 "Coliseu - Jaula da Besta Gladiadora" para impedir que este card seja destruído.','\r',char(13)),'\n',char(10)),'Colocar um marcador','Descartar 1 "Coliseu - Jaula da Besta Gladiadora" em vez de ser destruído?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52534264,'Segunda Expedição ao Perigo!',replace(replace('Descarte 1 card e, depois, escolha 1 monstro "Perigo!" que você controla; ele ganha 500 de ATK/DEF até o final deste turno. \r\nSe este card estiver no Cemitério: você pode descartar 1 monstro "Perigo!"; coloque este card no fundo do Deck e, depois, compre 1 card. \r\nVocê só pode usar cada efeito de "Segunda Expedição ao Perigo!" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52543404,'Lagarto Blindado Ragnaraika',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) ao banir 1 monstro Inseto, Planta ou Réptil do seu Cemitério. \r\nVocê só pode Invocar "Lagarto Blindado Ragnaraika" por Invocação-Especial uma vez por turno desta forma. \r\nVocê pode descartar 1 monstro Inseto, Planta ou Réptil e, depois, escolha 1 monstro com a face para cima que seu oponente controla, exceto um monstro Inseto, Planta ou Réptil; devolva-o para a mão. \r\nVocê só pode usar este efeito de "Lagarto Blindado Ragnaraika" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Retornar um monstro para a mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52550973,'Servo do Faraó','Uma aparição da qual se diz ter servido antigamente o Faraó. Tem uma tremenda lealdade que não desaparece.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52551211,'Sabujo Sombraneco',replace(replace('VIRE: Você pode escolher 1 card "Sombraneco" no seu Cemitério; adicione-o à sua mão.\r\nSe este card for enviado para o Cemitério por um efeito de card: você pode escolher 1 monstro no campo; mude a posição de batalha dele. \r\n(Os efeitos de monstros de Virar não são ativados neste momento, exceto os efeitos de monstros "Sombraneco".) \r\nVocê só pode usar 1 efeito de "Sabujo Sombraneco" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Alterar posição de batalha','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52553102,'Jurrac Astero',replace(replace('1 Regulador + 1+ monstros Dinossauro não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro: você pode Baixar 1 Magia/Armadilha "Jurrac" do seu Deck ou Cemitério. \r\nUma vez por turno, quando seu oponente Invocaria um ou mais monstros por Invocação-Especial (Efeito Rápido): você pode banir 2 monstros Dinossauro do seu Cemitério; negue a Invocação e, se isso acontecer, destrua esse(s) monstro(s). \r\nDurante o turno do seu oponente (Efeito Rápido): você pode banir 2 monstros "Jurrac" do seu Cemitério, incluindo este card; Invoque por Invocação-Especial 1 "Meteoro Jurrac" do seu Deck Adicional (isso é considerado uma Invocação-Sincro).','\r',char(13)),'\n',char(10)),'Baixar','Negar e destruir','Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52553471,'Sobrefusão',replace(replace('Escolha 1 monstro com a face para cima no campo; revele 1 monstro "HERÓI do Elemento", "Neoespacial" ou de Nível 10 da sua mão, do Deck ou do Deck Adicional, e o nome do monstro alvo pode ser considerado como o do monstro revelado se usado como Matéria de Fusão neste turno. \r\nEnvie o monstro revelado para o Cemitério se você tiver "Neos, o HERÓI do Elemento" no seu campo ou no seu Cemitério, caso contrário, embaralhe-o devolta no seu Deck (se revelado da mão, embaralhe-o no Deck Principal). \r\nVocê só pode ativar 1 "Sobrefusão" por turno.','\r',char(13)),'\n',char(10)),'O efeito de "Sobrefusão" está sendo aplicado.','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52558805,'Temtempo, o Djinn da Percussão',replace(replace('2 monstros de Nível 3	\r\nUma vez por turno, durante o turno de qualquer duelista: você pode desassociar 1 Matéria Xyz deste card e, depois, escolher 1 Monstro Xyz com a face para cima que seu oponente controla; desassocie 1 Matéria Xyz desse monstro e, se isso acontecer, todos os Monstros Xyz "Djinn" que você controla atualmente ganham 500 de ATK.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52566270,'Épsilon, o Guerreiro Ímã',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode enviar 1 monstro "Guerreiro Ímã" de Nível 4 ou menos do seu Deck para o Cemitério, exceto "Épsilon, o Guerreiro Ímã"; o nome deste card se torna o nome do monstro enviado (até a Fase Final) e, depois, você pode Invocar por Invocação-Especial 1 monstro "Guerreiro Ímã" do seu Cemitério com um nome diferente que o dos cards que você controla. \r\nVocê só pode usar este efeito de "Épsilon, o Guerreiro Ímã" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Invocar por Invocação Especial outro monstro do Cemitério?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52571838,'Manta da Maldição Rastejante','Quando este card é Invocado, por Invocação-Normal, com sucesso, nenhum Card de Armadilha pode ser activado.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52575195,'Cavaleiro Vívido','Durante o turno de qualquer duelista (exceto durante a Etapa de Dano), quando seu oponente escolher exatamente 1 monstro de LUZ do Tipo Besta-Guerreira que você controla (e nenhum outro card) como alvo de um ataque ou efeito de card: bana o monstro que você controla até sua próxima Fase de Apoio e, se isso acontecer, Invoque este card por Invocação-Especial da sua mão.','Banir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52584282,'Escaravelho-Hércules','Um grande besouro com uma carapaça dura e um chifre perigoso.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52589809,'Rei Vagante Vento Selvagem',replace(replace('Se você controlar um Regulador Demônio com 1500 ou menos de ATK, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nSe Invocado desta forma, você não pode Invocar monstros por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto Monstros Sincro. \r\nDurante sua Fase Principal, exceto no turno em que este card foi enviado para o Cemitério: você pode banir este card do seu Cemitério; adicione 1 Regulador Demônio com 1500 ou menos de ATK do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52596406,'Rolim Branco',replace(replace('Se este card estiver na sua mão: você pode escolher 1 monstro Peixe de Nível 4 ou menos no seu Cemitério com o mesmo nome de um card que você controla; Invoque este card por Invocação-Especial e, se isso acontecer, Invoque esse monstro por Invocação-Especial. \r\nVocê só pode usar este efeito de "Rolim Branco" uma vez por turno. \r\nSe este card for Invocado por Invocação-Especial do Cemitério: você pode considerá-lo como um Regulador neste turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52601736,'Saltador Inzektor',replace(replace('Uma vez por turno: você pode equipar 1 monstro "Inzektor" da sua mão ou do Cemitério a este card. \r\nEnquanto este card estiver equipado a um monstro, o Nível desse monstro aumenta em 4. \r\nEnquanto este card estiver equipado a um monstro: você pode enviar este Card de Equipamento para o Cemitério; o monstro ao qual estava equipado pode atacar diretamente neste turno. \r\nOutros monstros não podem atacar no turno em que você ativar este efeito.','\r',char(13)),'\n',char(10)),'Equipar','Ataque direto','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52607696,'Força do Espelho Miragem',replace(replace('Quando um monstro do oponente declarar um ataque: Invoque por Invocação-Especial 1 monstro Ilusão da sua mão ou do Cemitério e, se isso acontecer, devolva o monstro atacante para a mão. \r\nSe um ou mais monstros Ilusão com a face para cima que você controla deixarem o campo devido a um efeito de card do oponente, enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode banir este card; Invoque por Invocação-Especial 1 monstro Ilusão da sua mão ou do Cemitério. \r\nVocê só pode usar este efeito de "Força do Espelho Miragem" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52615248,'Progleo',replace(replace('2 monstros, exceto Fichas	\r\nDurante sua Fase Principal, se você controlar este card Invocado por Invocação-Link: você pode banir este card e 1 dos seus monstros para os quais este card apontar e, depois, escolha 1 Monstro Link em qualquer Cemitério; Invoque-o por Invocação-Especial, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar este efeito de "Progleo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52624755,'Peten, o Palhaço das Trevas','Quando este card for enviado para o Cemitério: você pode banir este card do seu Cemitério; Invoque por Invocação-Especial 1 "Peten, o Palhaço das Trevas" da sua mão ou do Deck.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52628687,'Livro de Magia da Vida',replace(replace('Bana 1 monstro do Tipo Mago do seu Cemitério e revele 1 outro Card de Magia "Livro de Magia" na sua mão para escolher 1 monstro do Tipo Mago no seu Cemitério; Invoque o alvo por Invocação-Especial com a face para cima em Posição de Ataque e equipe-o com este card. \r\nO Nível do monstro equipado é aumentado pelo Nível do monstro que foi banido para a ativação deste card. \r\nVocê só pode ativar 1 "Livro de Magia da Vida" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52639377,'Guerreiro do Submundo Balmung',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\n(Este card não deve ser considerado como um card "Guerreiro(a)".)	\r\nQuando este card for destruído por um efeito de card e enviado para o Cemitério: você pode escolher 1 monstro de Nível 4 ou menos no seu Cemitério, exceto este card; Invoque o alvo por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52644170,'Arquidemônio Cruzamente',replace(replace('1 Regulador Psíquico + 1+ monstros não-Reguladores	\r\nDurante a Fase Principal (Efeito Rápido): você pode escolher 1 dos seus monstros Psíquico banidos de Nível 7 ou menos; Invoque-o por Invocação-Especial. \r\nDurante a Fase de Batalha (Efeito Rápido): você pode oferecer como Tributo 1 outro monstro; ganhe PV igual ao seu ATK original e, se isso acontecer, este card ganha esse valor de ATK até o final deste turno. \r\nVocê só pode usar cada efeito de "Arquidemônio Cruzamente" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Ganhar PV','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52645235,'Felicidade Epurrely',replace(replace('2 monstros de Nível 2	\r\nNo final da Etapa de Dano, se este card batalhou: você pode adicionar 1 card "Purrely" do seu Deck à sua mão e, além disso, se este card tiver "Feliz Lembrança Purrely" como matéria, você pode diminuir pela metade o ATK de 1 monstro com a face para cima no campo. \r\nAté três vezes por turno, quando você ativar um Card de Magia Rápida "Purrely" (Efeito Rápido): você pode associar esse card no campo a este card como matéria e, depois, você pode devolver para a mão 1 Magia/Armadilha que seu oponente controla.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Associar a Magia Rápida ativada a este card','Reduzir o ATK de um monstro pela metade?','Retornar para a mão um card do oponente?','','','','','','','','','','','','');
INSERT INTO texts VALUES(52648457,'Olho de Gorgon','Até ao final da End Phase, todos os efeitos de monstros no Campo em Posição de Defesa são anulados.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52653092,'Número S0: ZEXAL Utópico',replace(replace('3 Monstros Xyz "Número" com a mesma Classe	\r\n(A Classe original deste card deve ser sempre considerada como 1.) \r\nVocê também pode Invocar este card por Invocação-Xyz ao descartar 1 Card de Magia Normal "Magia de Aumento de Classe" e, depois, usar um monstro "Utopia" que você controla como Matéria Xyz. \r\n(Transfira as Matérias Xyz dela para este card.) \r\nA Invocação Xyz deste card não pode ser negada. \r\nQuando Invocados por Invocação Xyz, os cards e efeitos do seu oponente não podem ser ativados. \r\nGanha 1000 de ATK e DEF para cada Matéria Xyz associada a ele. \r\nUma vez por turno do oponente (Efeito Rápido): você pode desassociar 1 Matéria Xyz deste card; os cards e efeitos do seu oponente não podem ser ativados neste turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Xyz sobrepondo seu monstro "Utópico" no campo?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52665542,'Santuário Luminoso',replace(replace('Uma vez por turno: você pode enviar 1 monstro "Luminoso(a)" da sua mão para o Cemitério e, depois, escolher 1 outro monstro "Luminoso(a)" no seu Cemitério; adicione-o à sua mão. \r\nSempre que um ou mais cards forem enviados do seu Deck para o Cemitério, coloque 1 Marcador de Brilho neste card. \r\nSe um ou mais cards "Luminoso(a)" que você controla seriam destruídos por um efeito de card, em vez disso, você pode remover 2 Marcadores de Brilho do seu lado do campo para cada um desses cards "Luminoso(a)".','\r',char(13)),'\n',char(10)),'Enviar para o Cemitério','Usar o efeito de "Santuário Luminoso" em vez de ser destruído?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52675689,'Convite para um Pesadelo',replace(replace('Quando este monstro for Invocado (exceto Invocação-Especial), selecione 1 monstro do seu oponente. \r\nEnquanto este card permanecer com a face para cima no campo, o monstro selecionado não pode atacar.','\r',char(13)),'\n',char(10)),'Restrição de ataque','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52684508,'Explosão de Fogo Infernal','Escolha 1 "Dragão Negro de Olhos Vermelhos" na sua Zona de Monstros; cause dano ao seu oponente igual ao ATK original desse "Dragão Negro de Olhos Vermelhos". "Dragão Negro de Olhos Vermelhos" não pode atacar no turno em que você ativar este card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52687916,'Trishula, o Dragão da Barreira de Gelo',replace(replace('1 Regulador + 2+ não-Reguladores	\r\nQuando este card for Invocado por Invocação-Sincro: você pode banir até 1 card cada da mão, do campo e do Cemitério do seu oponente (o card na mão é selecionado aleatoriamente).','\r',char(13)),'\n',char(10)),'Banir','Banir um card no campo?','Banir um card no Cemitério?','Banir cards da sua mão?','','','','','','','','','','','','');
INSERT INTO texts VALUES(52687917,'Trishula, o Dragão da Barreira de Gelo',replace(replace('1 Regulador + 2+ não-Reguladores	\r\nQuando este card for Invocado por Invocação-Sincro: você pode banir até 1 card cada da mão, do campo e do Cemitério do seu oponente (o card na mão é selecionado aleatoriamente).','\r',char(13)),'\n',char(10)),'Banir','Banir um card no campo?','Banir um card no Cemitério?','Banir cards da sua mão?','','','','','','','','','','','','');
INSERT INTO texts VALUES(52698008,'Wiccaroto Ciberso',replace(replace('2 monstros Ciberso	\r\nEste card Invocado por Invocação-Link não pode ser destruído em batalha ou por efeitos de card. \r\nMonstros Ciberso para os quais este card apontar não podem ser destruídos por efeitos de card. \r\nSe um ou mais monstros forem Invocados por Invocação-Especial em uma ou mais zonas para as quais este card apontar enquanto você controlar este monstro (exceto durante a Etapa de Dano): você pode banir 1 monstro Ciberso do seu Cemitério; adicione 1 Regulador Ciberso do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Wiccaroto Ciberso" uma vez por turno.','\r',char(13)),'\n',char(10)),'Procurar no Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52702748,'Guia D.D.',replace(replace('Quando este card for Invocado por Invocação-Normal, ceda o controle dele ao seu oponente. \r\nDurante a Fase Final de cada duelista, o oponente seleciona 1 card do Cemitério do controlador deste card e o remove do jogo.','\r',char(13)),'\n',char(10)),'Transferir o controle','Banir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52707042,'Mistigarota Livromante',replace(replace('Você pode Invocar este card por Invocação-Ritual com um card "Livromante". \r\nSe este card foi Invocado por Invocação-Ritual usando um ou mais monstros no campo, seu oponente não pode escolher Monstros de Ritual que você controla como alvo de efeitos de monstro. \r\nSe este card for Invocado por Invocação-Especial: você pode escolher 1 monstro com a face para cima que seu oponente controla; até o final deste turno, mude o ATK dele para 0 e, além disso, negue seus efeitos. \r\nVocê só pode usar este efeito de "Mistigarota Livromante" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Ritual usando monstros no campo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52709508,'Triforça Aliado Genex',replace(replace('1 Regulador "Genex" + 1 ou mais monstros não-Reguladores	\r\nO efeito deste card depende dos Atributos dos seus Monstros-Matéria Sincro não-Reguladores.\r\n● TERRA: Se este card atacar, seu oponente não pode ativar quaisquer Cards de Magia/Armadilha até o final da Etapa de Dano.\r\n● FOGO: Se este card destruir um monstro em batalha, cause dano ao seu oponente igual ao ATK do monstro destruído.\r\n● LUZ: Uma vez por turno, você pode escolher 1 monstro de LUZ no seu Cemitério e Invocá-lo por Invocação-Especial com a face para baixo em Posição de Defesa.','\r',char(13)),'\n',char(10)),'Causar dano','Baixar no seu campo 1 monstro de LUZ no seu Cemitério','Usar um monstro de TERRA como Matéria de Sincro','Usar um monstro de FOGO como Matéria de Sincro','Usar um monstro de LUZ como Matéria Sincro','','','','','','','','','','','');
INSERT INTO texts VALUES(52711246,'Shiranui Escudeirosaga',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nVocê só pode Invocar um ou mais "Shiranui Escudeirosaga" por Invocação-Especial uma vez por turno. \r\nUma vez por turno: você pode banir 1 monstro com a face para cima que você controla ou no seu Cemitério e, depois, aplique esses efeitos, em sequencia, dependendo do que era o monstro antes de ser banido, caso fosse algum desses.\r\n● Zumbi: Você pode fazer com que todos os monstros que você controla ganhem 300 de ATK.\r\n● FOGO: Você pode destruir 1 Magia/Armadilha no campo.\r\n● Sincro: Você pode destruir 1 monstro no campo.','\r',char(13)),'\n',char(10)),'','Aumentar o ATK de todos os monstros?','Destruir um Card de Magia/Armadilha?','Destruir aquele monstro?','','','','','','','','','','','','');
INSERT INTO texts VALUES(52714670,'Dimensão Metafis',replace(replace('Se seu oponente Invocar um monstro por Invocação-Especial (exceto durante a Etapa de Dano): você pode escolher 1 dos seus monstros "Metafis" banidos; Invoque-o por Invocação-Especial, mas bana-o durante a Fase Final do próximo turno. \r\nSe outro card "Metafis" seu em posse do seu dono for banido enquanto este card já estiver com a face para cima na sua Zona de Magias & Armadilhas: você pode escolher 1 card que seu oponente controla; bana-o. \r\nVocê só pode usar cada efeito de "Dimensão Metafis" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar, mas não resolver o efeito','Ativar e aplicar o primeiro Efeito','Banir um card do oponente','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52738610,'Princesa da Dança de Necroz',replace(replace('Seu oponente não pode ativar cards ou efeitos em resposta à ativação de um Card de Magia de Ritual "Necroz". \r\nMonstros de Ritual "Necroz" que você controla não podem ser escolhidos como alvo de efeitos de card do oponente. \r\nSe este card for oferecido como Tributo por um efeito de card: você pode escolher 1 dos seus monstros "Necroz" banidos, exceto "Princesa da Dança de Necroz"; adicione-o à sua mão. \r\nVocê só pode usar este efeito de "Princesa da Dança de Necroz" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52768103,'KA-2 Des Scissors','Quando este card destrói um monstro como resultado de um combate e o envia para o Cemitério, inflija dano aos Life Points do seu adversário igual ao Nível do monstro destruído x 500 pontos.','Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52768390,'Senhor das Trevas',replace(replace('Você pode Invocar por Invocação-Especial este card (da sua mão) ao oferecer como Tributo 2 monstros Demônio e/ou Fada.\r\nNão pode ser destruído por batalha.\r\nUma vez por turno: você pode Invocar por Invocação-Especial quantas "Fichas de Senhor das Trevas" (Demônio/TREVAS/Nível 10/ATK 3000/DEF 1000) forem possíveis para o seu campo, mas eles não podem atacar diretamente ou serem destruídas por batalha, destrua-os quando este card for destruído, você também não pode Invocar por Invocação-Especial pelo resto desse turno.\r\nSe um ou mais monstros forem destruídos por batalha: cause 700 de dano ao seu oponente.','\r',char(13)),'\n',char(10)),'','Invocação Especial','Causar dano','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52768391,'Ficha de Senhor das Trevas','Invocado por Invocação-Especial com o efeito de "Senhor das Trevas".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52782439,'Escala Excepcional',replace(replace('Adicione 1 "Escala Especial" ou "Escala Urgente" do seu Deck à sua mão e, depois, você pode Invocar por Invocação-Especial 1 "Ficha de Diagrama" (Máquina/TERRA/Nível 10/ATK 3000/DEF 3000) no campo do seu oponente. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 monstro Máquina de Nível 10 no seu Cemitério ou banimento; envie 1 card que você controla para o Cemitério e, se isso acontecer, Invoque esse monstro por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Escala Excepcional" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Invocação Especial','Invocar uma Ficha por Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52782440,'Ficha de Diagrama','Invocado por Especial com o efeito "Escala Excepcional".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52786469,'Guerreiro Laval',replace(replace('Quando este card destruir um monstro do oponente em batalha: Cause dano ao seu oponente igual ao ATK original do monstro destruído. \r\nVocê deve ter 4 ou mais monstros "Laval" com nomes diferentes no seu Cemitério para ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52792430,'Predaplanta Espinodionaea',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 monstro com a face para cima que seu oponente controla; coloque 1 Marcador de Predador sobre ele e, se ele for de Nível 2 ou mais, ele se torna de Nível 1 enquanto tiver um Marcador de Predador. \r\nDepois do cálculo de dano, se este card batalhou um monstro de Nível igual ou menor: você pode Invocar por Invocação-Especial 1 monstro "Predaplanta" do seu Deck, exceto "Predaplanta Espinodionaea".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52800428,'Mão do Demônio','Braços que surgem do Pântano do Caos para arrastar os desprevenidos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52807032,'Sônico Dinomorfia',replace(replace('Quando seu oponente ativar um Card de Magia/Armadilha, enquanto você controlar um monstro "Dinomorfia": pague metade dos seus PV; negue a ativação e, se isso acontecer, destrua esse card e, depois, destrua 1 monstro "Dinomorfia" que você controla. \r\nDurante o cálculo de dano, enquanto seus PV forem 2000 ou menos, se você sofreria dano de batalha: você pode banir este card do seu Cemitério; você não sofre dano de batalha dessa batalha. \r\nVocê só pode ativar 1 "Sônico Dinomorfia" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52817046,'Memória Apagada',replace(replace('Você pode activar este card se o seu adversário tiver 3 ou menos cards na sua mão. \r\nO seu adversário adiciona a sua mão ao seu Deck e embaralha-o. \r\nEm seguida, o seu adversário compra um número de cards igual ao número de cards que adicionou ao seu Deck.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52823314,'Ônibus de Excursão do Submundo','Quando este card for enviado para o Cemitério: escolha 1 monstro no Cemitério de qualquer um dos duelistas, exceto "Ônibus de Excursão do Submundo"; embaralhe o alvo no Deck.','Retornar ao Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52824910,'Planador Kaiser',replace(replace('Não pode ser destruído em uma batalha com um monstro que tenha o mesmo ATK. \r\nSe este card for destruído e enviado para o Cemitério: escolha 1 monstro no campo; devolva o alvo para a mão.','\r',char(13)),'\n',char(10)),'Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52833089,'Trovão Negro','Quando um monstro "Asanegra" que você controla for destruído em batalha e enviado para o Cemitério: cause 400 de dano ao seu oponente para cada card que ele controla.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52834429,'Tela do Clima Auroreal',replace(replace('Monstros de Efeito "do Clima" nas suas Zonas de Monstros Principais da coluna deste card e das colunas adjacentes a ela ganham este efeito.\r\n● Quando exatamente 1 card for adicionado à mão de um duelista (exceto durante a Etapa de Dano): você pode banir este card; bana o card adicionado e, se isso acontecer, esse duelista compra 1 card.	\r\nVocê só pode controlar 1 "Tela do Clima Auroreal".','\r',char(13)),'\n',char(10)),'Banir o card adicionado e comprar 1 card (Tela do Clima Auroreal)','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52838896,'Invocação do Enxame',replace(replace('Escolha monstros "Vespabatalha" de Nível 4 ou menos no seu Cemitério, até o número de monstros que seu oponente controla; Invoque-os por Invocação-Especial. \r\nVocê só pode ativar 1 "Invocação do Enxame" por turno. \r\nVocê não pode Invocar monstros por Invocação-Especial do Deck Adicional no turno em que ativar este card, exceto monstros Inseto.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52840267,'Senhora Obscura Ixchel',replace(replace('Você pode descartar este card e 1 card "Senhor(a) Obscuro(a)"; compre 2 cards. \r\n(Efeito Rápido): você pode pagar 1000 PV e, depois, escolha 1 Magia/Armadilha "Senhor(a) Obscuro(a)" no seu Cemitério; aplique o efeito do alvo e, depois, embaralhe o alvo no Deck. \r\nVocê só pode usar cada efeito de "Senhora Obscura Ixchel" uma vez por turno. \r\nVocê só pode Invocar um ou mais "Senhora Obscura Ixchel" por Invocação-Especial uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52840598,'Bri Sincron','Se este card for enviado para o Cemitério como uma Matéria Sincro, até o final deste turno, o Monstro Sincro que usou este card como uma Matéria Sincro ganha 600 de ATK, mas seus efeitos são negados.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52843699,'Simorgh, Pássaro da Perfeição',replace(replace('Enquanto estiver com a face para cima no campo, este card também é de Atributo VENTO. \r\nVocê só pode usar cada um dos seguintes efeitos de "Simorgh, Pássaro da Perfeição" uma vez por turno. \r\nDurante sua Fase Principal, se você Invocar por Invocação-Normal ou Especial um ou mais monstros Besta Alada: você pode revelar este card na sua mão; imediatamente depois que este efeito resolver, Invoque por Invocação-Normal 1 monstro "Simorgh". \r\nSe este card for Invocado por Invocação-Normal: você pode enviar 1 monstro "Simorgh" do seu Deck para o Cemitério; adicione 1 Magia/Armadilha "Simorgh" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52846880,'Necroz de Catastor',replace(replace('Você pode Invocar este card por Invocação-Ritual com qualquer Card de Magia de Ritual "Necroz". \r\nDeve ser Invocado por Invocação-Ritual sem usar "Necroz de Catastor" e não pode ser Invocado por Invocação-Especial de nenhuma outra forma. \r\nVocê pode descartar este card e, depois, escolher 1 monstro "Necroz" no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê só pode usar este efeito de "Necroz de Catastor" uma vez por turno. \r\nNo começo da Etapa de Dano, se um monstro "Necroz" que você controla batalhar um monstro com a face para cima do oponente que foi Invocado por Invocação-Especial do Deck Adicional: destrua esse monstro.','\r',char(13)),'\n',char(10)),'Invocação Especial','Destruir um monstro','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52854600,'Espírito Tenyi - Suruya',replace(replace('Se você controlar um monstro Wyrm, ou um Monstro que não seja de Efeito com a face para cima: você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe este card for enviado para o Cemitério como matéria para um Monstro Sincro Wyrm: você pode Invocar por Invocação-Especial 1 Monstro Link "Tenyi" do seu Deck Adicional (mas ele não pode ser usado como Matéria Link) e, depois, você perde PV igual ao Valor Link dele x 1000. \r\nVocê só pode usar cada efeito de "Espírito Tenyi - Suruya" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Invoque por Invocação Especial do Deck Adicional','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52860176,'Alma Negra Possuída','Você pode oferecer este card com a face para cima como Tributo; tome o controle de todos os monstros com a face para cima de Nível 3 ou menos que seu oponente controla atualmente.','Tome o controle','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52869807,'Asanegra - Sopro, o Vento Traseiro',replace(replace('Se você não controlar nenhum card, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nSe um monstro do seu oponente atacar um monstro "Asanegra" que você controla: o monstro atacante perde 300 de ATK apenas durante a Etapa de Dano.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52875873,'Explosão Evolutiva','Se você controlar "Dragão Cibernético": escolha 1 card que seu oponente controla; destrua o alvo. "Dragão Cibernético" não pode atacar no turno em que você ativar este card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52900000,'Shinobarão Pavão',replace(replace('Você pode Invocar este card por Invocação-Ritual com "Chamado do Shinobird". \r\nDeve ser Invocado por Invocação-Ritual e não pode ser Invocado por Invocação-Especial de nenhuma outra forma. \r\nSe este card for Invocado por Invocação-Ritual: você pode devolver para a mão até 3 monstros que seu oponente controla e, depois, você pode Invocar por Invocação-Especial 1 monstro Espírito de Nível 4 ou menos da sua mão, ignorando suas condições de Invocação. \r\nUma vez por turno, durante a Fase Final, se este card foi Invocado por Invocação-Especial neste turno: devolva-o para a mão e, se isso acontecer, Invoque por Invocação-Especial 2 "Fichas de Shinobird" (Tipo Besta Alada/VENTO/Nível 4/ATK 1500/DEF 1500).','\r',char(13)),'\n',char(10)),'Retornar um monstro do oponente para a mão','Invocar por Invocação Especial um monstro Espírito da sua mão?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52900001,'Ficha de Shinobird','Invocado por Especial com o efeito "Shinobaronesa Pavoa" ou "Shinobarão Pavão".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52900379,'Asanegra - Brisote, o Vento Lateral',replace(replace('Se 2 ou mais monstros "Asanegra" com a face para cima que você controla forem destruídos neste turno, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nSe este card for enviado para o Cemitério como uma Matéria Sincro: ganhe 600 PV.','\r',char(13)),'\n',char(10)),'Recupere 600 PV','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52904476,'Matriarca de Nephthys',replace(replace('Você pode escolher 1 monstro "Nephthys" de Nível 4 ou menos no seu Cemitério, exceto "Matriarca de Nephthys"; destrua 1 card na sua mão e, se isso acontecer, Invoque o monstro alvo por Invocação-Especial em Posição de Defesa, mas negue seus efeitos. \r\nDurante sua próxima Fase de Apoio depois que este card foi destruído por um efeito de card e enviado para o Cemitério: você pode Invocar este card por Invocação-Especial do Cemitério. \r\nVocê só pode usar cada efeito de "Matriarca de Nephthys" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52913738,'Ritual de Destruição',replace(replace('Este card é usado para a Invocação-Ritual de "Garlandolf, Rei da Destruição". \r\nVocê também deve oferecer como Tributo monstros cuja soma dos Níveis seja igual a 7 ou mais do campo ou da sua mão. \r\nDurante sua Fase Principal, você pode remover de jogo este card do seu Cemitério. \r\nSe isso acontecer, durante este turno, qualquer monstro destruído em batalha com um Monstro de Ritual que você controla será devolvido ao topo do Deck em vez de ser enviado para o Cemitério.','\r',char(13)),'\n',char(10)),'Monstros destruídos em batalha por um Monstro Ritual são devolvidos ao Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52918032,'Fantasótão Mementotlan',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 card "Memento" no seu Cemitério, exceto "Fantasótão Mementotlan"; adicione-o à sua mão. \r\nSe este card for enviado para o Cemitério por um efeito de monstro "Memento": você pode Invocar este card por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Fantasótão Mementotlan" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52927340,'Kuntisulta Altergeist',replace(replace('Quando um monstro do oponente declarar um ataque, se você controlar um card "Altergeist": você pode Invocar este card por Invocação-Especial da sua mão e, se isso acontecer, negue o ataque. \r\nSe este card for Invocado por Invocação-Especial: você pode escolher 1 card com a face para cima que seu oponente controla; negue os efeitos desse card enquanto ele e este monstro estiverem com a face para cima no campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52945066,'Onda Marincesa',replace(replace('Se você controlar um Monstro Link "Marincesa": escolha 1 monstro com a face para cima que seu oponente controla; até o final deste turno, negue os efeitos desse monstro com a face para cima e, depois, se você controlar um monstro "Marincesa" de Link-2 ou mais, até o final deste turno, todos os monstros com a face para cima que você controla atualmente não são afetados pelos efeitos de card do seu oponente. \r\nSe você controlar um monstro "Marincesa" de Link-3 ou mais, você pode ativar este card da sua mão.','\r',char(13)),'\n',char(10)),'Ativar aplicando o efeito de "Onda Marincesa".','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52947044,'Fusão do Destino',replace(replace('Invoque por Invocação-Fusão do seu Deck Adicional 1 Monstro de Fusão que mencione um monstro "HERÓI do Destino" como matéria, usando monstros da sua mão ou do Deck como Matéria de Fusão, mas destrua-o durante a Fase Final do próximo turno e, além disso, pelo resto deste turno depois que este card resolver, você não pode Invocar monstros por Invocação-Especial, exceto monstros "HERÓI" de TREVAS. \r\nVocê só pode ativar 1 "Fusão do Destino" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52962804,'Recrutamento da Dragunidade',replace(replace('Quando este card for ativado: você pode escolher 1 monstro "Dragunidade" de Nível 4 ou menos no seu Cemitério; adicione-o à sua mão. \r\nSe um monstro "Dragunidade" seu, cujo Nível original seja 5 ou mais, atacar, ele não é afetado pelos efeitos de card do seu oponente até o final da Etapa de Dano. \r\nVocê só pode ativar 1 "Recrutamento da Dragunidade" por turno.','\r',char(13)),'\n',char(10)),'Ativar escolhendo como alvo um monstro no seu Cemitério?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52963531,'Camarartista Mamute d''Água',replace(replace('Escala de Pêndulo = 4\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno, quando um ou mais Monstros de Fusão forem Invocados por Invocação-Especial do seu lado do campo (exceto durante a Etapa de Dano): você pode Invocar por Invocação-Especial 1 Monstro Pêndulo "Olhos Anômalos" com a face para cima do seu Deck Adicional.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nDurante sua Fase Principal: você pode Invocar por Invocação-Fusão 1 Monstro de Fusão do Tipo Dragão do seu Deck Adicional, usando monstros que você controla como Matérias de Fusão. \r\nVocê só pode usar este efeito de "Camarartista Mamute d''Água" uma vez por Duelo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52971673,'Sundae de Fichas','Destrua tantas Fichas que você controla quanto possível e, depois, destrua cards no campo até o número de Fichas destruídas por este efeito.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52971944,'Cerimônia de Selamento de Katon','Uma vez por turno: Você pode banir 1 monstro de FOGO do seu Cemitério para escolher 1 card no Cemitério do oponente; bana o alvo.','Usar o efeito de "Cerimônia de Selamento de Katon" agora?','Banir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(52977572,'Pilo Dragunidade',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode Invocar por Invocação-Especial 1 monstro Besta Alada "Dragunidade" da sua mão e, depois, equipe-o com este card. \r\nEnquanto este card estiver equipado a um monstro, esse monstro pode atacar seu oponente diretamente, mas quando ele faz isso usando este efeito, o dano de batalha causado ao seu oponente é diminuído pela metade.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial e equipar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53008933,'Advento do Arquidemônio',replace(replace('Enquanto você controlar "Sarcófago Brilhante", você pode Invocar este card por Invocação-Normal sem oferecer Tributo. \r\nOutros monstros que você controla ganham 500 de ATK, apenas durante o seu turno. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 monstro que seu oponente controla; tome o controle dele até a Fase Final, mas esse monstro não pode atacar a não ser que você controlasse "Sarcófago Brilhante" quando este efeito foi ativado. \r\nVocê só pode usar este efeito de "Advento do Arquidemônio" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Normal sem Tributo','Tome o controle','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53025096,'Dragão de Olhos Anômalos','Se este card destruir um monstro do oponente em batalha e enviá-lo para o Cemitério: cause dano ao seu oponente igual à metade do ATK original desse monstro no Cemitério.','Dano aos Pontos de Vida','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53027855,'Rosa-dos-ventos, o Senhor Elemental',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao ter exatamente 5 monstros de VENTO no seu Cemitério. \r\nSe este card for Invocado por Invocação-Especial: destrua todas as Magias e Armadilhas que seu oponente controla. \r\nVocê só pode usar este efeito de "Rosa-dos-ventos, o Senhor Elemental" uma vez por turno. \r\nSe este card com a face para cima deixar o campo, pule a Fase de Batalha do seu próximo turno.','\r',char(13)),'\n',char(10)),'Destruir Magias/Armadilhas','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53039326,'Laboratório de Criaturas do Núcleo de Ferro',replace(replace('Durante cada uma das suas Fases Finais, destrua este card a não ser que você revele 1 "Núcleo de Ferro de Koa''ki Meiru" na sua mão. \r\nSempre que um monstro "Koa''ki Meiru" no campo for destruído durante a Fase Final, seu dono pode adicionar 1 monstro "Koa''ki Meiru" do Deck dele para a mão dele.','\r',char(13)),'\n',char(10)),'Revele 1 "Núcleo de Ferro de Koa''ki Meiru" para o seu oponente','Destruir "Laboratório de Criaturas do Núcleo de Ferro"','Adicionar à mão','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53046408,'Provisões de Emergência','Envie qualquer número de outras Magias/Armadilhas que você controla para o Cemitério; ganhe 1000 PV para cada card enviado para o Cemitério desta forma.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53054164,'Melffys Alegres',replace(replace('2+ monstros Besta de Nível 2	\r\nVocê pode desassociar 1 matéria deste card; seus monstros "Melffy" podem atacar diretamente neste turno. \r\nDurante o turno do seu oponente (Efeito Rápido): você pode escolher 1 Monstro Xyz Besta que você controla; devolva esse monstro para o Deck Adicional e, depois, você pode Invocar por Invocação-Especial monstros Besta de Nível 2 ou menos do seu Cemitério, até o número de matérias que esse monstro tinha. \r\nVocê só pode usar este efeito de "Melffys Alegres" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53054833,'Velocidaroide Ioiô Duplo','Quando este card for Invocado por Invocação-Normal: você pode escolher 1 monstro "Velocidaroide" de Nível 3 ou menos no seu Cemitério; Invoque-o por Invocação-Especial.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53063039,'Fluxo de Garras Pernicioso',replace(replace('Ative apenas se você controlar um monstro "Pernicioso(a)" com a face para cima. \r\nSelecione 1 monstro que seu oponente controla e destrua-o.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53077251,'Adaptador Universal','Escolha 1 monstro com a face para cima que seu oponente controla; até o final deste turno, o ATK de todos os outros monstros atualmente no campo se torna igual ao ATK atual desse monstro.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53085623,'Esquadrão das Sombras Sirena',replace(replace('(Este card deve ser sempre considerado como um card "Atlante".)	\r\nVocê pode descartar 1 card para o Cemitério; monstros de ÁGUA que você controla atualmente se tornam de Nível 7 até o final deste turno. \r\nSe este card for enviado para o Cemitério para ativar o efeito de um monstro de ÁGUA: Invoque por Invocação-Especial 1 monstro "Atlante" ou "Sirena" de Nível 4 ou menos do seu Deck, exceto "Esquadrão das Sombras Sirena" e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto monstros de ÁGUA. \r\nVocê só pode usar cada efeito de "Esquadrão das Sombras Sirena" uma vez por turno.','\r',char(13)),'\n',char(10)),'Alterar Nível','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53087962,'Ursártico Septentrion',replace(replace('Não pode ser Invocado por Invocação-Sincro. 	\r\nDeve ser Invocado por Invocação-Especial (do seu Deck Adicional) ao enviar 2 monstros que você controla com 7 Níveis de diferença para o Cemitério (1 Regulador de Nível 8 ou mais e 1 Monstro Sincro não-Regulador). \r\nNegue os efeitos dos monstros com a face para cima sem um Nível que foram Invocados por Invocação-Especial do Deck Adicional. \r\nSe seu oponente Invocar um ou mais monstros por Invocação-Especial (exceto durante a Etapa de Dano): você pode adicionar 1 card "Ursártico(a)" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Ursártico Septentrion" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53090623,'Oni Inchado Amarelo',replace(replace('Quando você Invocar um monstro por Invocação-Xyz: você pode Invocar este card por Invocação-Especial da sua mão. \r\nUma vez por turno: você pode desassociar 1 Matéria Xyz de um monstro que você controla e, depois, escolher 1 Monstro Xyz com a face para cima no campo; reduza sua Classe em 1 e, se isso acontecer, ele perde 300 de ATK.','\r',char(13)),'\n',char(10)),'Invocação Especial','Reduzir a Classe','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53094821,'Terror Toon',replace(replace('Quando um Card de Magia/Armadilha, ou efeito de monstro, for ativado, enquanto você controlar tanto "Mundo Toon" quanto um ou mais monstros Toon: negue a ativação e, se isso acontecer, destrua esse card. \r\nVocê só pode ativar 1 "Terror Toon" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53100061,'Sabre-X Axel','Enquanto você controlar este card com a face para cima, quando um monstro "Sabre" for destruído em batalha e enviado para o Cemitério, compre 1 card.','Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53112492,'Anti-Magia',replace(replace('Remova 2 Contadores Mágicos no seu Campo. \r\nAnule a activação de um Card de Magia e destrúa-o.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53116300,'Chamador de Hordeum Ferro','Quando um monstro "Hordeum Ferro" for Invocado por Invocação-Tributo com a face para cima ao oferecer este card como Tributo: Você pode Invocar por Invocação-Especial 1 monstro "Hordeum Ferro" de Nível 4 ou menos do seu Deck.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53119267,'Espinho Mágico','Quando um card da mão do seu adversário é descartada para o Cemitério, inflija 500 pontos de dano aos Life Points do seu adversário por cada card que ele descartou.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53129443,'Buraco Negro','Destrua todos os monstros no campo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53134520,'Besta da Invocação Fantasmal',replace(replace('Você pode oferecer este card como Tributo; adicione 1 "Uria, o Senhor das Chamas Cortantes", "Hamon, o Senhor do Trovão Impactante" ou "Raviel, o Senhor dos Fantasmas" do seu Deck ou Cemitério à sua mão e, depois, você pode Invocar por Invocação-Especial 1 monstro Piro, Trovão ou Demônio de Nível 10 da sua mão cujo ATK seja igual à sua própria DEF, ignorando suas condições de Invocação, mas ele não pode atacar diretamente neste turno. \r\nVocê pode banir este card do seu Cemitério; adicione 1 "Destruição da Dimensão Fusão" do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "Besta da Invocação Fantasmal" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Adicionar "Destruição da Dimensão Fusão" à mão','Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53136004,'Imperador da Profecia',replace(replace('Você pode banir ambos 1 monstro do Tipo Mago com a face para cima que você controla, exceto este card, e 1 card "Livro de Magia" do seu Cemitério para escolher 1 monstro com a face para cima que seu oponente controla; tome o controle do alvo até a Fase Final. \r\nVocê só pode usar o efeito de "Imperador da Profecia" uma vez por turno. \r\nEste card não pode atacar no turno em que você ativar este efeito.','\r',char(13)),'\n',char(10)),'Tomar controle','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53143898,'Titereiro Altergeist',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode Baixar 1 Armadilha "Altergeist" diretamente do seu Deck. \r\nVocê pode escolher 1 card "Altergeist" que você controla e 1 monstro "Altergeist" no seu Cemitério; envie esse card no campo para o Cemitério e, se isso acontecer, Invoque por Invocação-Especial esse outro monstro do seu Cemitério. \r\nVocê só pode usar este efeito de "Titereiro Altergeist" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53152590,'Bobina de Corrente de Ferro','Uma vez por turno, você pode selecionar 1 monstro "Corrente de Ferro" que você controla para fazer com que ele ganhe 300 de ATK e DEF, enquanto este card estiver com a face para cima no campo.','Aumentar ATK/DEF','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53153481,'Armaill','Um guerreiro estranho que manipula três lâminas letais e usando ambas as mãos e a cauda.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53154400,'Rover Psíquico',replace(replace('Se este card for Invocado por Invocação-Especial: você pode lançar um dado de seis faces e se o resultado for 1 ou 6, destrua até 2 cards no campo. \r\nSe este card for enviado para o Cemitério: você pode lançar um dado de seis faces, e se o resultado for 2, 3, 4 ou 5, Invoque este card por Invocação-Especial. \r\nO duelista que o Invocou não pode Invocar por Invocação-Especial do Deck Adicional enquanto ele estiver com a face para cima na Zona de Monstros.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53162898,'Sábia Amazoness','No final da Etapa de Dano, se este card atacou e ainda estiver no campo: escolha 1 Magia/Armadilha que seu oponente controla; destrua o alvo.','Destruir Magias/Armadilhas','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53167658,'Cortina de Bloqueio',replace(replace('Se um ou mais cards que você controla seriam destruídos em batalha ou por um efeito de card do oponente, você pode destruir este card em vez de 1 desses cards. \r\nSe um ou mais cards que seu oponente controla seriam destruídos em batalha ou por um efeito de card, você pode banir este card do seu Cemitério em vez de 1 desses cards. \r\nVocê só pode usar cada efeito de "Cortina de Bloqueio" uma vez por turno.','\r',char(13)),'\n',char(10)),'Escolha um card para usar como substituição de destruição','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53174748,'Caminhada Espiritual de Mikanko',replace(replace('Escolha 1 monstro com a face para cima que seu oponente controla; equipe esse monstro com a face para cima a 1 monstro "Mikanko" que você controla como uma Magia de Equipamento e, depois, se um Card de Monstro de Ritual estiver no campo, você pode causar 500 de dano ao seu oponente para cada Magia de Equipamento que você controla. \r\nVocê pode banir este card do seu Cemitério; Invoque por Invocação-Especial 1 dos seus monstros "Mikanko" que estiverem banidos ou na sua mão. \r\nVocê só pode usar cada efeito de "Caminhada Espiritual de Mikanko" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Causar dano ao seu oponente?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53180020,'Exa, o Executor de Necroz',replace(replace('Se este card for oferecido como Tributo por um efeito de card: você pode adicionar 1 Monstro de Ritual "Necroz" do Tipo Dragão do seu Deck à sua mão. \r\nSe este card for banido: você pode escolher 1 dos seus monstros "Necroz" banidos, exceto este card; Invoque esse monstro por Invocação-Especial. \r\nVocê só pode usar 1 efeito de "Exa, o Executor de Necroz" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53183600,'Dragão Toon de Olhos Azuis',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nVocê primeiro deve Invocá-lo por Invocação-Especial (da sua mão) ao oferecer 2 monstros como Tributo, enquanto você controlar "Mundo Toon". \r\nNão pode atacar no turno em que for Invocado por Invocação-Especial. \r\nVocê deve pagar 500 PV para declarar um ataque com este monstro. \r\nSe "Mundo Toon", no campo, for destruído, destrua este card. \r\nPode atacar diretamente seu oponente, a não ser que ele controle um monstro Toon, em cujo caso este card deve escolher um monstro Toon como alvo de seus ataques.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53183601,'Dragão Toon de Olhos Azuis',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nVocê primeiro deve Invocá-lo por Invocação-Especial (da sua mão) ao oferecer 2 monstros como Tributo, enquanto você controlar "Mundo Toon". \r\nNão pode atacar no turno em que for Invocado por Invocação-Especial. \r\nVocê deve pagar 500 PV para declarar um ataque com este monstro. \r\nSe "Mundo Toon", no campo, for destruído, destrua este card. \r\nPode atacar diretamente seu oponente, a não ser que ele controle um monstro Toon, em cujo caso este card deve escolher um monstro Toon como alvo de seus ataques.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53184342,'Arma Gram Dragunidade',replace(replace('Você pode banir 2 monstros Dragão e/ou Besta Alada do seu Cemitério: Invoque este card por Invocação-Especial da sua mão ou do Cemitério. \r\nVocê pode escolher 1 monstro com a face para cima; seus efeitos são negados e, além disso, ele perde 1000 de ATK para cada Card de Equipamento que você controla. \r\nQuando um monstro do seu oponente for destruído em batalha e enviado para o Cemitério: você pode equipá-lo a este card. \r\nVocê só pode usar cada efeito de "Arma Gram Dragunidade" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53193261,'Wattchave','Monstros "Watt" que você controla atualmente podem atacar diretamente neste turno.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53194323,'Elemento Sombrio',replace(replace('Se você tiver um monstro "Guardião do Portão" no seu Cemitério: pague metade dos seus PV; Invoque por Invocação-Especial 1 monstro "Guardião do Portão" de Nível 11 ou mais da sua mão, do Deck ou do Deck Adicional, ignorando suas condições de Invocação. \r\nVocê pode banir este card do seu Cemitério; adicione 1 dos seus "Sanga do Trovão", "Kazejin" ou "Suijin" do seu Deck ou do banimento à sua mão. \r\nVocê só pode usar cada efeito de "Elemento Sombrio" uma vez por turno.','\r',char(13)),'\n',char(10)),'Escolha um monstro para Invocar por Invocação Especial','Escolha um monstro para adicionar à sua mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53199020,'Dianaira Mitológico',replace(replace('Você pode Invocar este card por Invocação-Tributo com a face para cima em Posição de Ataque ao oferecer como Tributo 1 monstro "Mitológico(a)". \r\nUma vez por turno, o primeiro efeito de Card de Magia Normal do oponente que resolver se torna "Seu oponente descarta 1 card".','\r',char(13)),'\n',char(10)),'Invoque por Tributo 1 monstro cujo nome contenha "Mitológico(a)"','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53208660,'Chamado do Pêndulo',replace(replace('Descarte 1 card; adicione 2 Monstros Pêndulo "Mago" com nomes diferentes do seu Deck à sua mão e, além disso, até o final do próximo turno do seu oponente depois que este card resolver, cards "Mago" nas suas Zonas de Pêndulo não podem ser destruídos por efeitos de card. \r\nVocê só pode ativar 1 "Chamado do Pêndulo" por turno. \r\nVocê não pode ativar este card se você já ativou um Efeito de Pêndulo de um monstro "Mago" neste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53212882,'Brisawntarilho & Coruneve',replace(replace('Uma vez por turno, enquanto você controlar este card Invocado por Invocação-Tributo: você pode conduzir até 3 Invocações-Normal/Baixar neste turno, não apenas 1. \r\nEnquanto este card Invocado por Invocação-Tributo estiver na Zona de Monstros, se um monstro seu atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente. \r\nUma vez por turno do oponente (Efeito Rápido): você pode banir 1 card da sua mão; coloque todos os monstros Invocados por Invocação-Especial que seu oponente controla com a face para baixo em Posição de Defesa.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53239672,'Barreira Espiritual','Enquanto você controlar um monstro, você não sofre dano de batalha.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53241226,'Cross Over',replace(replace('Escolha 1 monstro com a face para cima que seu oponente controla e 1 monstro Guerreiro que você controla; equipe esse monstro com a face para cima do oponente ao seu monstro como uma Magia de Equipamento e, se isso acontecer, até o final deste turno, seu oponente não sofre dano das batalhas envolvendo esse monstro que você controla. \r\nVocê só pode ativar 1 "Cross Over" por turno. \r\nEnquanto estiver equipado, se o monstro equipado seria destruído em batalha ou por um efeito de card, em vez disso, destrua o monstro equipado a ele por este efeito.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53244294,'Número 57: Dragão do Pó de Três Cabeças',replace(replace('3 monstros de Nível 4	\r\nQuando este card for Invocado por Invocação-Especial: você pode escolher 1 monstro que seu oponente controla; este card ganha ATK igual ao ATK atual desse monstro. \r\nSe o seu oponente controlar mais cards que você: você pode desassociar 1 Matéria Xyz deste card e, depois, selecionar 1 Zona dos Cards de Monstro ou Zona dos Cards de Magia & Armadilha desocupados; enquanto este card estiver com a face para cima no campo, essa Zona de Cards não pode ser usada.','\r',char(13)),'\n',char(10)),'Aumentar ATK','Bloquear Zona','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53246495,'Rainha Inférnica',replace(replace('Se você não tiver cards na sua mão e este card estiver no seu Cemitério: você pode banir 1 monstro de TREVAS do seu Cemitério e, depois, escolha 1 monstro de TREVAS que você controla; ele pode atacar diretamente neste turno. \r\nVocê só pode usar este efeito de "Rainha Inférnica" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ataque direto','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53251824,'Ataqueraptor - Laniidae Sorrateiro','Uma vez por turno, durante sua Fase Principal, se este card foi Invocado por Invocação-Normal ou Especial neste turno: você pode Invocar por Invocação-Especial 1 monstro "Ataqueraptor" de Nível 4 ou menos da sua mão.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53257892,'Gigaplanta',replace(replace('Este card é considerado um Monstro Normal enquanto estiver com a face para cima no campo ou Cemitério. \r\nEnquanto este card for um Monstro Normal no campo, você pode Invocá-lo por Invocação-Normal para fazer com que ele se torne um Monstro de Efeito com este efeito.\r\n● Uma vez por turno: você pode Invocar por Invocação-Especial 1 monstro Inseto ou Planta da sua mão ou do Cemitério.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53262004,'Dragão Vórtice de Olhos Anômalos',replace(replace('1 monstro "Olhos Anômalos" + 1 Monstro Pêndulo	\r\nQuando este card for Invocado por Invocação-Especial: você pode escolher 1 monstro em Posição de Ataque do seu oponente; devolva-o para a mão. \r\nQuando um Card de Magia/Armadilha ou outro efeito de monstro for ativado (Efeito Rápido): você pode embaralhar 1 Monstro Pêndulo com a face para cima do seu Deck Adicional no Deck, negue a ativação e, se isso acontecer, destrua esse card. \r\nVocê só pode usar cada efeito de "Dragão Vórtice de Olhos Anômalos" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53265336,'Escala Solfacorde',replace(replace('Você pode aplicar quaisquer dos seguintes efeitos, em sequência, de acordo com o número de Cards de Monstro Pêndulo "Solfacorde" com nomes diferentes que você controla.\r\n● 3+: Devolva 1 card da sua Zona de Pêndulo para a mão e, se isso acontecer, coloque 1 Monstro Pêndulo "Solfacorde" com a face para cima do seu Deck Adicional na sua Zona de Pêndulo.\r\n● 5+: Invoque por Invocação-Especial 1 Monstro Pêndulo "Solfacorde" da sua mão.\r\n● 7+: Destrua todos os cards com a face para cima que seu oponente controla.	\r\nVocê só pode ativar 1 "Escala Solfacorde" por turno.','\r',char(13)),'\n',char(10)),'Colocar um Card Pêndulo do Deck Adicional?','Invocar por Invocação Especial da sua mão?','Destruir todos os cards com a face para cima que o seu oponente controla?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53266486,'Dragão Anestefoguette',replace(replace('Quando um efeito de Monstro Link for ativado que escolha como alvo este card com a face para cima no campo (Efeito Rápido): você pode destruir este card e, depois, faça com que 1 monstro com a face para cima no campo seja incapaz de atacar e, além disso, ele tem seus efeitos negados. \r\nDurante a Fase Final, se este card estiver no Cemitério porque foi destruído no campo, em batalha ou por um efeito de card e enviado para lá neste turno: você pode Invocar por Invocação-Especial 1 monstro "Foguette" do seu Deck, exceto "Dragão Anestefoguette". \r\nVocê só pode usar cada efeito de "Dragão Anestefoguette" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53270092,'Espírito do Kyudo Han-Shi',replace(replace('Escala de Pêndulo = 9\r\n[ Efeito de Pêndulo ]\r\nSe um ou mais monstros forem Invocados por Invocação-Pêndulo: devolva este card para a mão.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nQuando este card for Invocado por Invocação-Normal: você pode devolver para a mão todos os cards que você controla nas mesmas colunas que os cards nas suas Zonas de Pêndulo (incluindo os próprios cards da Zona de Pêndulo) e, depois, você pode adicionar 1 monstro com 2400 de ATK/1000 de DEF do seu Deck à sua mão, exceto "Espírito do Kyudo Han-Shi". \r\nUma vez por turno, durante a Fase Final, se este card foi Invocado por Invocação-Normal ou virado com a face para cima neste turno: devolva este card para a mão.','\r',char(13)),'\n',char(10)),'Adicionar 1 monstro do seu Deck à sua mão?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53274132,'Técnico da Corrente de Ferro',replace(replace('Quando este card destruir um monstro em batalha e enviá-lo para o Cemitério, cause 300 de dano ao seu oponente. \r\nUma vez por turno, você pode Invocar por Invocação-Especial 1 monstro "Corrente de Ferro" de Nível 4 ou menos do seu Cemitério, exceto "Técnico da Corrente de Ferro". \r\nEste card não pode atacar no turno em que você ativar este efeito.','\r',char(13)),'\n',char(10)),'Causar dano','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53276089,'Acelerador de Massa de Ryzeal',replace(replace('Aplique o seguinte efeito e, depois, você pode associar este card a um Monstro Xyz de Classe 4 que você controla.\r\n● Pelo resto deste turno, todos os monstros "Ryzeal" que você controla ganham 1000 de ATK.	\r\nSe este card for enviado para o Cemitério, exceto do campo: você pode escolher 1 card no Cemitério do seu oponente; bana-o. \r\nVocê só pode usar cada efeito de "Acelerador de Massa de Ryzeal" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar','Banir','Usar como Matéria Xyz?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53286626,'Semeadura de Solarvinhas',replace(replace('Invoque por Invocação-Especial 1 monstro "Solarsemente" do seu Deck e, se isso acontecer, sofra 1000 de dano. \r\nSe você não controlar nenhum Monstro Link "Solaravalon", você só pode Invocar "Gênio Loci de Solarsemente" por Invocação-Especial com este efeito. \r\nPelo resto deste turno depois que este card resolver, você não pode Invocar monstros do Deck Adicional por Invocação-Especial, exceto monstros Planta. \r\nSe um ou mais Monstros Link Planta que você controla seriam destruídos em batalha ou por um efeito de card do oponente, em vez disso, você pode banir este card do seu Cemitério. \r\nVocê só pode ativar 1 "Semeadura de Solarvinhas" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53291093,'Triângulo Misterioso',replace(replace('Destrua 1 monstro no campo com um Marcador-A. \r\nDepois, você pode Invocar por Invocação-Especial 1 monstro "Alienígena" de Nível 4 do seu Deck. \r\nDestrua-o durante a Fase Final.','\r',char(13)),'\n',char(10)),'Invocação Especial?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53293545,'Relva-Fogo','É uma planta cuspidora de fogo que cresce próxima de vulcões.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53303460,'Diabretiço Velaneco',replace(replace('Você pode revelar 1 Magia de Ritual na sua mão; Invoque por Invocação-Especial tanto este card da sua mão quanto 1 monstro "Diabretiço" do seu Deck, exceto "Diabretiço Velaneco". \r\nSe este card for Invocado por Invocação-Especial do Deck: você pode adicionar 1 Magia de Ritual do seu Deck à sua mão. \r\nVocê só pode usar 1 efeito de "Diabretiço Velaneco" por turno e apenas uma vez por turno. \r\nVocê não pode Invocar monstros por Invocação-Especial do Deck Adicional.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53309998,'Arquivador Marinho',replace(replace('Se um monstro for Invocado por Invocação-Normal ou Especial em uma zona para a qual um Monstro Link apontar (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial do seu Cemitério (se ele estava lá quando a Invocação resolveu) ou da mão (mesmo se ele não estava), mas bana-o quando ele deixar o campo. \r\nVocê só pode usar este efeito de "Arquivador Marinho" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53315891,'Timaeus, o Cavaleiro do Destino',replace(replace('"Cavaleiro Lendário Timaeus" + "Cavaleiro Lendário Critias" + "Cavaleiro Lendário Hermos"	\r\nDeve ser Invocado por Invocação-Especial (do seu Deck Adicional) ao enviar os cards acima que você controla para o Cemitério. \r\n(Você não usa "Polimerização".) \r\nNão é afetado por outros efeitos de card. \r\nUma vez por batalha, se este card batalhar, durante o cálculo de dano (Efeito Rápido): você pode fazer com que o ATK/DEF deste card se tornem iguais ao ATK do monstro no campo com o maior ATK (em caso de empate, você seleciona). \r\nQuando este card for destruído em batalha: você pode Invocar por Invocação-Especial 3 monstros "Cavaleiro Lendário" da sua mão, do Deck e/ou do Cemitério, ignorando suas condições de Invocação.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53318263,'Bahalutiya, a Grande Radiância',replace(replace('Você pode Invocar este card por Invocação-Tributo ao oferecer como Tributo 1 Monstro de Efeito. \r\nDurante a Fase Principal do seu oponente, se um ou mais cards forem adicionados do Deck Principal à mão dele (exceto ao comprá-los) e este card estiver na sua mão, você pode: imediatamente depois que este efeito resolver, Invoque este card por Invocação-Tributo. \r\nSe este card for Invocado por Invocação-Normal ou Especial da mão, você pode: faça com que seu oponente bana cards do topo do Deck dele com a face para baixo, igual ao número de cards na mão dele e, depois, ele embaralha toda a mão no Deck e, se isso acontecer, ele adiciona o(s) card(s) banido(s) por este efeito à mão dele. \r\nVocê só pode usar este efeito de "Bahalutiya, a Grande Radiância" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ofereça como Tributo 1 Monstro de Efeito para realizar uma Invocação Tributo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53323475,'Tubarão Marionete',replace(replace('Desassocie 1 matéria de um monstro em qualquer campo e, se isso acontecer, escave os 4 cards do topo do seu Deck, selecione 1 deles e aplique o efeito apropriado de acordo com seu tipo de card e, além disso, coloque o resto no topo do Deck na mesma ordem.\r\n● Monstro/Magia: Adicione-o à sua mão.\r\n● Armadilha: Baixe-a.	\r\nEla pode ser ativada neste turno.\r\nVocê só pode ativar 1 "Tubarão Marionete" por turno.','\r',char(13)),'\n',char(10)),'','Ativar aplicando o efeito de "Tubarão Marionete".','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53325667,'Donzela da Rosa do Jardim',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Especial: você pode adicionar 1 "Jardim Negro" do seu Deck ou Cemitério à sua mão. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 monstro "Dragão da Rosa" ou 1 Monstro Sincro Dragão no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Donzela da Rosa do Jardim" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53325668,'Donzela da Rosa do Jardim',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Especial: você pode adicionar 1 "Jardim Negro" do seu Deck ou Cemitério à sua mão. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 monstro "Dragão da Rosa" ou 1 Monstro Sincro Dragão no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Donzela da Rosa do Jardim" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53329234,'Despojos do Pecado do Sono - Morrian',replace(replace('Escolha 1 monstro com a face para cima Invocado por Invocação-Especial no campo; coloque-o com a face para baixo em Posição de Defesa. \r\nSe você controlar um monstro Ilusão de Nível 5 ou mais, enquanto este card estiver no seu Cemitério: você pode Baixar este card, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar 1 efeito de "Despojos do Pecado do Sono - Morrian" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Mudar para Posição de Defesa com a face para baixo','Baixar este card no campo','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53330789,'Explosão da Trindade da Alma Aniquiladora',replace(replace('Escolha 1 monstro "Alma Aniquiladora" que você controla; Invoque por Invocação-Especial até 2 monstros "Alma Aniquiladora" da sua mão, com nomes diferentes um do outro, nenhum dos quais tenha o mesmo Atributo original que o do monstro alvo (mas negue seus efeitos e devolva-os para a mão durante a Fase Final) e, depois, você pode devolver para a mão todos os cards que seu oponente controla que estiverem na mesma coluna que a do monstro alvo que você controla e do(s) monstro(s) \r\nInvocado(s) por Invocação-Especial por este efeito. \r\nVocê só pode ativar 1 "Explosão da Trindade da Alma Aniquiladora" por turno.','\r',char(13)),'\n',char(10)),'','Retornar para a mão um card do oponente?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53334471,'Duelo Gozen',replace(replace('Cada duelista só pode controlar monstros de 1 único Atributo. \r\nEnvie todos os outros monstros com a face para cima que eles controlam para o Cemitério.','\r',char(13)),'\n',char(10)),'Escolha o Atributo a manter','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53334641,'Anjo Travesso Fantardil',replace(replace('2 monstros de Nível 4	\r\nVocê também pode Invocar este card por Invocação-Xyz ao usar um Monstro Xyz "Fantardil" que você controla como matéria, exceto "Anjo Travesso Fantardil". \r\n(Transfira as matérias dele para este card.) \r\nQuando o número de matérias neste card se tornar 10, você vence o Duelo. \r\nUma vez por turno: você pode desassociar 1 matéria deste card; adicione 1 Magia/Armadilha "Fantardil" do seu Deck à sua mão. \r\nUma vez por turno: você pode associar 1 card "Fantardil" da sua mão a este card como matéria.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Xyz usando um Monstro Xyz "Fantardil" como matéria?','Procurar no Deck','Adicionar matérias','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53341729,'Espelho Aprisionador de Luz','Negue todos os efeitos de monstros de LUZ que ativaram no campo ou no Cemitério.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53347303,'Dragão Brilhante de Olhos Azuis',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao oferecer como Tributo 1 "Dragão Definitivo de Olhos Azuis". \r\nGanha 300 de ATK para cada monstro Dragão no seu Cemitério. \r\nQuando um card ou efeito for ativado que escolha este card como alvo (Efeito Rápido): você pode negar esse efeito.','\r',char(13)),'\n',char(10)),'Negue os efeitos que escolherem este card como alvo.','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53363708,'Espada Supermágica de Raptinus',replace(replace('No começo da Fase de Batalha: você pode mudar a posição de batalha do monstro equipado e, se isso acontecer, imediatamente depois que este efeito resolver, Invoque 1 monstro por Invocação-Normal. \r\nVocê só pode usar este efeito de "Espada Supermágica de Raptinus" uma vez por turno. \r\nAplique este efeito de acordo com a posição de batalha do monstro equipado.\r\n● Posição de Ataque: Seu oponente não pode escolher o monstro equipado como alvo de efeitos de card.\r\n● Posição de Defesa: O monstro equipado não pode ser destruído em batalha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53375573,'Rei Negro do Abismo','Diz-se que este Rei dos Mundos Baixos já teve o poder para governar as trevas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53388413,'Comandante Gottoms, Mestre da Espada','Todos os monstros "Sabre" com a face para cima que você controla ganham 400 de ATK.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53389254,'Asanegra Agressor - Sohaya, a Chuva Tempestuosa',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro usando um monstro "Asanegra" como matéria, ele é considerado como um Regulador enquanto estiver com a face para cima no campo. \r\nVocê só pode usar cada um desses efeitos de "Asanegra Agressor - Sohaya, a Chuva Tempestuosa" uma vez por turno.\r\n● Quando este card for Invocado por Invocação-Sincro: você pode escolher 1 monstro "Asanegra Agressor" no seu Cemitério; Invoque-o por Invocação-Especial.\r\n● Durante sua Fase Principal, se este card estiver no Cemitério porque foi enviado para lá neste turno: você pode banir 1 outro "Asanegra Agressor - Sohaya, a Chuva Tempestuosa" do seu Cemitério; Invoque este card por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Invoque por Invocação Especial um monstro do Cemitério','Invocar este card por Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53404966,'Infernobre Cavaleiro Ricciardetto',replace(replace('Você pode banir este card da sua mão ou do Cemitério; Invoque por Invocação-Especial 1 monstro Guerreiro de FOGO de Nível 4 ou menos da sua mão como um Regulador. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 monstro Guerreiro de FOGO de Nível 4 ou menos no seu Cemitério, exceto "Infernobre Cavaleiro Ricciardetto"; Invoque-o por Invocação-Especial e, além disso, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros Guerreiro. \r\nVocê só pode usar 1 efeito de "Infernobre Cavaleiro Ricciardetto" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53408006,'Mercador-Gema','Durante a Etapa de Dano, quando um Monstro Normal de TERRA que você controla batalhar (Efeito Rápido): você pode enviar este card da sua mão para o Cemitério; esse monstro ganha 1000 de ATK/DEF até o final deste turno.','Aumentar ATK/DEF','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53413628,'Codificar Transmissor',replace(replace('2 Monstros de Efeito	\r\nGanha 500 de ATK para cada monstro para o qual este card apontar. \r\nNão pode ser destruído em batalha ou pelos efeitos de card do seu oponente enquanto este card apontar para um monstro.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53416326,'Formifada, a Feiticeira Circular',replace(replace('Se um monstro Inseto ou Planta estiver em qualquer Cemitério, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Formifada, a Feiticeira Circular" por Invocação-Especial uma vez por turno desta forma. \r\nSe este card que você controla seria usado como Matéria Sincro para um monstro Inseto ou Planta, você pode considerá-lo como um não-Regulador.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53417695,'Fuga dos Desacorrentados',replace(replace('Escolha 1 monstro "Desacorrentado(a)" que você controla e 1 card no campo; destrua os dois. \r\nSe este card Baixado for destruído por um efeito de card: você pode Invocar por Invocação-Especial 1 monstro "Desacorrentado(a)" do seu Deck. \r\nVocê só pode usar cada efeito de "Fuga dos Desacorrentados" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53442500,'Fim da Linha','Se seus PV forem menores que 100: compre 2 cards e, depois, se seus PV forem menores que 10, compre 2 cards adicionais.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53451824,'Besta Fantasma Mecha Concoruda',replace(replace('1 Regulador + 1 ou mais monstros não-Reguladores	\r\nAs Fichas que você controla não podem ser destruídas em batalha ou por efeitos de card. \r\nSe este card que você controla for destruído por um card do seu oponente (seja em batalha ou por um efeito de card) e enviado para o seu Cemitério: você pode oferecer como Tributo todas as Fichas que você controla e, depois, escolher 1 monstro "Besta Fantasma Mecha" de Nível 4 ou menos no seu Cemitério; Invoque o alvo por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53461122,'Efígie da Terra','Este card pode ser considerado como 2 Tributos para a Invocação-Tributo de um Monstro Normal de TERRA.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53466722,'Primeiro dos Senhores Dragões',replace(replace('3 Monstros Normais	\r\nDeve ser Invocado por Invocação-Fusão. \r\nVocê só pode controlar 1 "Primeiro dos Senhores Dragões". \r\nNão pode ser destruído em batalha, e não é afetado por outros efeitos de monstro. \r\nUma vez, enquanto estiver com a face para cima no campo, quando um Card de Magia/Armadilha ou seus efeitos forem ativados (Efeito Rápido): você pode destruir todas as Magias e Armadilhas no campo. \r\nVocê só pode usar este efeito de "Primeiro dos Senhores Dragões" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Destruir','','Efeito já ativado','','','','','','','','','','','','');
INSERT INTO texts VALUES(53466826,'Oportunidade Heroica',replace(replace('Escolha 1 monstro "Heroico(a)" com a face para cima que você controla; neste turno, dobre o seu ATK, mas ele não pode atacar seu oponente diretamente. \r\nVocê só pode ativar 1 "Oportunidade Heroica" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53481938,'Barragem Foguette',replace(replace('Você pode enviar 1 monstro Dragão de TREVAS do seu Deck para o Cemitério, exceto um monstro de Nível 5; Invoque por Invocação-Especial este card da sua mão, você também não pode Invocar por Invocação-Especial do seu Deck Adicional pelo resto deste turno, exceto monstros de TREVAS.\r\nQuando um efeito de um Monstro Link que escolha este card no campo como alvo for ativado (Efeito Rápido): você pode destruir este card, então Invoque por Invocação-Especial até 1 monstro "Foguette" da sua mão, Deck, Cemitério, e/ou banimento, exceto "Barragem Foguette".\r\nVocê só pode usar cada um dos efeitos de "Barragem Foguette" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53481939,'Barragem Foguette',replace(replace('Você pode enviar 1 monstro Dragão de TREVAS do seu Deck para o Cemitério, exceto um monstro de Nível 5; Invoque por Invocação-Especial este card da sua mão, você também não pode Invocar por Invocação-Especial do seu Deck Adicional pelo resto deste turno, exceto monstros de TREVAS.\r\nQuando um efeito de um Monstro Link que escolha este card no campo como alvo for ativado (Efeito Rápido): você pode destruir este card, então Invoque por Invocação-Especial até 1 monstro "Foguette" da sua mão, Deck, Cemitério, e/ou banimento, exceto "Barragem Foguette".\r\nVocê só pode usar cada um dos efeitos de "Barragem Foguette" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53485634,'Dragão Retrô de Olhos Vermelhos',replace(replace('Se um ou mais monstros "Olhos Vermelhos" de Nível 7 ou menos que você controla forem destruídos por um ataque ou efeito de card do seu oponente e enviados para o seu Cemitério, enquanto este card estiver na sua mão: você pode Invocar este card por Invocação-Especial em Posição de Defesa e, se isso acontecer, Invoque por Invocação-Especial tantos desses monstros destruídos quanto possível na mesma posição em que estavam quando foram destruídos. \r\nVocê pode oferecer este card como Tributo; você pode Invocar por Invocação-Normal 1 monstro "Olhos Vermelhos" durante sua Fase Principal deste turno, em adição à sua Invocação-Normal/Baixar (padrão). \r\n(Você só pode se aproveitar deste efeito uma vez por turno.)','\r',char(13)),'\n',char(10)),'','','Invocar pelo efeito de "Dragão Retrô de Olhos Vermelhos"','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53490455,'Salamagrande Guaxinim',replace(replace('Quando um monstro "Salamagrande" seu for escolhido como alvo de um ataque por um monstro do oponente: você pode enviar este card da sua mão para o Cemitério e, depois, escolher esses 2 monstros que iriam batalhar; ganhe PV igual ao ATK desse monstro do oponente e, além disso seu monstro alvo não pode ser destruído em batalha neste turno. \r\nQuando um monstro "Salamagrande" seu destruir um monstro do oponente em batalha e enviá-lo para o Cemitério, enquanto este card estiver no seu Cemitério: você pode adicionar este card à sua mão. \r\nVocê só pode usar este efeito de "Salamagrande Guaxinim" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53493204,'Deusa com o Terceiro Olho','Este card pode ser usado como um substituto para qualquer 1 Matéria de Fusão mencionada por nome no Card de Monstro de Fusão, mas a(s) outra(s) matéria(s) deve(m) estar correta(s).','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53503015,'Rosa Congelada',replace(replace('Envie 1 monstro com a face para cima que você controla para o Cemitério; aplique este efeito, dependendo do Tipo que ele tinha no campo.\r\n● Planta: Durante a Fase Final deste turno, compre 2 cards e, depois, descarte 1 card.\r\n● Não-Planta: Adicione 1 monstro Planta de Nível 4 ou menos do seu Deck à sua mão.	\r\nVocê só pode ativar 1 "Rosa Congelada" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53519297,'Intensificação Negra','Bana 2 monstros Reguladores "Asanegra" com a face para cima que você controla; compre 2 cards.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53527835,'Cidade de Trevas','Se um monstro "HERÓI do Destino" atacar um monstro de maior ATK, o monstro atacante ganha 1000 de ATK apenas durante o cálculo de dano.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53530069,'Espírito da Brisa','Enquanto este card permanecer com a face para cima em Posição de Ataque no seu lado do campo, aumente seus PV em 1000 pontos durante cada uma de suas Fases de Apoio.','Ganhar PV','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53535814,'Juíza da Barreira de Gelo',replace(replace('Enquanto você controlar outro monstro "Barreira de Gelo", sempre que seu oponente ativar um card ou efeito ao pagar PV, ele perde 500 PV. \r\nVocê só pode usar cada um dos seguintes efeitos de "Juíza da Barreira de Gelo" uma vez por turno. \r\nVocê pode escolher 1 ou 2 monstros "Barreira de Gelo" no seu Cemitério e 1 ou 2 cards no Cemitério do seu oponente; embaralhe-os no Deck. \r\nSe você controlar um monstro "Barreira de Gelo": você pode banir este card do seu Cemitério e, depois, escolha 1 monstro em Posição de Ataque no campo; coloque-o em Posição de Defesa.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53539634,'Sanwitch','"Sangan" + "Bruxa da Floresta Negra"','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53540729,'Guerreiro de Corda',replace(replace('Você pode escolher 1 monstro "de Corda" com a face para cima que você controla; aumente o seu Nível em 1 e o seu ATK em 600 até a Fase Final. \r\nEste efeito só pode ser usado uma vez, enquanto este card estiver com a face para cima no campo.','\r',char(13)),'\n',char(10)),'Aumentar Nível e ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53541822,'Duelo do Mecanismo Antigo',replace(replace('"Golem do Mecanismo Antigo", e monstros que o mencionem, na sua Zona de Monstros não são afetados pelos efeitos de monstro ativados do seu oponente. \r\nSe seu oponente controlar um monstro: você pode Invocar por Invocação-Fusão 1 Monstro de Fusão que mencione "Golem do Mecanismo Antigo" do seu Deck Adicional, ao banir monstros do seu campo ou Cemitério como matéria, incluindo "Golem do Mecanismo Antigo" que você controla e, se isso acontecer, ele pode realizar até 3 ataques durante cada Fase de Batalha. \r\nVocê só pode usar este efeito de "Duelo do Mecanismo Antigo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Invocado por Invocação Especial pelo efeito de "Duelo do Mecanismo Antigo"','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53545926,'Apoio das Fichas',replace(replace('Você pode oferecer como Tributo qualquer número de Fichas e, depois, escolha 1 monstro que você controla com 0 de ATK; ele ganha ATK igual ao número oferecido como Tributo x 1000 (até o final deste turno) e, se isso acontecer, ele pode atacar monstros até o número oferecido como Tributo durante cada Fase de Batalha neste turno. \r\nVocê só pode usar este efeito de "Apoio das Fichas" uma vez por turno. \r\nNo final da Fase de Batalha do seu oponente: você pode Invocar por Invocação-Especial uma ou mais "Ficha de Apoio" (Besta/TERRA/Nível 1/ATK 0/DEF 0) até o número de Fichas destruídas durante esta Fase de Batalha.','\r',char(13)),'\n',char(10)),'','Escolha a quantidade de Fichas a Invocar por Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53545927,'Ficha de Apoio','Invocado por Especial com o efeito "Apoio das Fichas".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53550467,'Nobre Cavaleiro Drystan',replace(replace('Enquanto você controlar outro monstro "Nobre Cavaleiro", seu oponente não pode escolher seus monstros com menos de 1800 de ATK, exceto este card, como alvo de efeitos de card e os monstros dele não podem escolhê-los como alvo de ataques. \r\nSe uma Magia de Equipamento "Armas Nobres" se tornar equipada a este card: escolha 1 card com a face para cima no campo; destrua o alvo. \r\nVocê só pode usar este efeito de "Nobre Cavaleiro Drystan" uma vez por turno.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53557529,'Redemoinho de Peluguel',replace(replace('Se você não controlar nenhum monstro: Invoque por Invocação-Especial 1 monstro "de Peluguel" de Nível 4 ou menos do seu Deck e, depois, se seu oponente controlar 2 ou mais monstros, você pode Invocar por Invocação-Especial 1 monstro "de Peluguel" do seu Deck e, além disso, pelo resto deste turno, você não pode Invocar por Invocação-Especial, exceto monstros "de Peluguel". \r\nSe você descartaria para ativar o efeito de um monstro "de Peluguel", você pode banir este card do seu Cemitério em vez de 1 desses cards. \r\nVocê só pode usar cada efeito de "Redemoinho de Peluguel" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar','','Invocar por Invocação Especial novamente?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53567095,'Ataque de Ícaro','Ofereça como Tributo 1 monstro Besta Alada e, depois, escolha 2 cards no campo; destrua-os.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53569894,'Pirâmide de Luz','Se este card com a face para cima for removido do seu lado do campo, destrua "Androesfinge" e "Esfinge Teleia" no seu lado do campo e os remova de jogo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53573406,'Camaleão Mascarado',replace(replace('Não pode ser Invocado por Invocação-Normal se você controlar um monstro de Nível 5 ou mais. \r\nQuando este card for Invocado por Invocação-Normal: você pode escolher 1 monstro de DEF 0 no seu Cemitério; Invoque o alvo por Invocação-Especial com a face para cima em Posição de Defesa. \r\nSeus efeitos são negados. \r\nDurante o turno em que ativar este efeito, você não pode Invocar nenhum outro monstro por Invocação-Especial, exceto do Deck Adicional.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53577438,'Mechamático Nabla',replace(replace('Você pode oferecer como Tributo 1 monstro Ciberso; Invoque por Invocação-Especial 1 monstro "Mechamático(a)" do seu Deck. \r\nSe este card for enviado para o Cemitério: você pode escolher 1 monstro Ciberso que você controla na Zona de Monstros Adicional; ele pode realizar até 2 ataques contra monstros durante cada Fase de Batalha neste turno. \r\nVocê só pode usar cada efeito de "Mechamático Nabla" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53581214,'Ceifador de Fogo','Um ceifador com uma flecha flamejante que queima os inimigos até transformá-los em cinzas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53582587,'Tributo Torrencial','Quando um ou mais monstros forem Invocados: destrua todos os monstros no campo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53586134,'Lança-Bolhas',replace(replace('Você só pode equipar este card em "Homem Bolha, o HERÓI do Elemento". \r\nAumente o ATK do monstro equipado em 800 pontos. \r\nSe o monstro equipado seria destruído como resultado de uma batalha, em vez disso, destrua este card, e faça com que o Dano de Batalha causado ao controlador do monstro equipado seja 0.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53589300,'Nerva, a Patrona do Poder da Criação',replace(replace('3 monstros "Artmage"	\r\nPrimeiro deve ser Invocado por Invocação-Fusão, ou por Invocação-Especial (do seu Deck Adicional) em Posição de Defesa ao oferecer como Tributo 3 monstros com Tipos diferentes. \r\nVocê só pode Invocar um ou mais "Nerva, a Patrona do Poder da Criação" por Invocação-Especial uma vez por turno. \r\nEnquanto um card estiver na Zona do Campo, este card não pode ser destruído por efeitos de card. \r\nUma vez por turno, quando você ativar um efeito de um monstro "Artmage" (Efeito Rápido): você pode fazer com que o efeito ativado se torne "Destrua todos os cards que seu oponente controla".','\r',char(13)),'\n',char(10)),'Efeito de alterar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53606874,'Inseto Grande','Uma formiga gigante que vive na floresta e é muito poderosa tanto atacando quanto defendendo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53610653,'Varinha Atada',replace(replace('Só pode ser equipado a um monstro Mago que tenha Nível. \r\nEle ganha ATK igual ao seu próprio Nível x 100. \r\nSe o monstro equipado for destruído por um card do seu oponente e enviado para o Cemitério e este card for enviado para o seu Cemitério como resultado: você pode Invocar esse monstro por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53618197,'Confiras de Nouvelles',replace(replace('Você pode Invocar este card por Invocação-Ritual com um card "Receita". \r\nSe este card for Invocado por Invocação-Especial: você pode escolher 1 Magia/Armadilha no campo; destrua-a. \r\nQuando um card ou efeito for ativado que escolha este card no campo como alvo, ou quando este card for alvo de um ataque (Efeito Rápido): você pode oferecer como Tributo este card e 1 monstro em Posição de Ataque em qualquer campo e, se isso acontecer, Invoque por Invocação-Especial 1 Monstro de Ritual "Nouvelles" de Nível 3 ou 4 da sua mão ou do Deck. \r\nVocê só pode usar cada efeito de "Confiras de Nouvelles" uma vez por turno.','\r',char(13)),'\n',char(10)),'Destruir um Card de Magia/Armadilha','Invocar por Invocação Especial da sua mão/Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53618293,'Donzela de Solarvinhas',replace(replace('Quando seu oponente ativar um card ou efeito que escolha como alvo um ou mais monstros Planta que você controla que foram Invocados por Invocação-Especial do Deck Adicional (Efeito Rápido): você pode Invocar este card por Invocação-Especial da sua mão e, se isso acontecer, negue o efeito. \r\nVocê só pode usar este efeito de "Donzela de Solarvinhas" uma vez por turno. \r\nSeu oponente não pode escolher Magias/Armadilhas "Solaravalon" ou "Solarvinhas" que você controla como alvo de efeitos de card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53620899,'Donzelas Lonchuras de Mahjong',replace(replace('VIRE: Você pode comprar 1 card e, depois, descartar 1 card.\r\nUma vez por turno: você pode colocar este card com a face para baixo em Posição de Defesa.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53623827,'Melhor Corredor','Todos os Monstros Sincro com a face para cima que você controla ganham 600 de ATK','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53624265,'Gêmeos Desacorrentados - Rakea',replace(replace('(Efeito Rápido): você pode escolher 1 card que você controla; destrua-o e, além disso, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros Demônio. \r\nSe este card no campo for destruído por um efeito de card, exceto "Gêmeos Desacorrentados - Rakea", ou em batalha: você pode Invocar por Invocação-Especial 1 monstro "Desacorrentado(a)" da sua mão ou do Deck, exceto "Gêmeos Desacorrentados - Rakea". \r\nVocê só pode usar cada efeito de "Gêmeos Desacorrentados - Rakea" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53639887,'Templo Divino do Olho de Cobra',replace(replace('Quando este card for ativado: você pode colocar 1 monstro "Olho de Cobra" da sua mão, do Deck ou do Cemitério com a face para cima na Zona de Magias & Armadilhas do seu dono como uma Magia Contínua. \r\nMonstros de FOGO de Nível 1 que você controla ganham 1100 de ATK. \r\nUma vez por turno, se seu oponente Invocar um ou mais monstros por Invocação-Normal ou Especial (exceto durante a Etapa de Dano): você pode escolher 1 Card de Monstro no campo considerado como uma Magia Contínua; Invoque-o por Invocação-Especial no seu campo. \r\nVocê só pode ativar 1 "Templo Divino do Olho de Cobra" por turno.','\r',char(13)),'\n',char(10)),'','Colocar um monstro "Olho de Cobra" no campo?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53656677,'Chama Poderosa',replace(replace('Quando um monstro com a face para cima que você controla for escolhido como alvo de um ataque por um monstro de maior ATK: escolha o alvo do ataque; negue o ataque e, se isso acontecer, equipe este card no alvo. \r\nO monstro equipado ganha ATK igual à diferença entre o seu ATK e o ATK do seu atacante quando este card resolver.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53666449,'Minerva, a Estudiosa dos Céus','Sempre que um Card de Armadilha de Resposta for ativado, imediatamente depois que ele resolver, este card ganha 500 de ATK e, se isso acontecer, e "O Santuário no Céu" estiver no campo, adicione 1 Armadilha de Resposta com um nome diferente do seu Cemitério à sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53670497,'Selo Hierático das Cinzas',replace(replace('Uma vez por turno do oponente: você pode enviar 1 monstro "Hierático" do seu Deck para o seu Cemitério. \r\nUma vez por turno, durante o seu turno: você pode escolher 1 dos seus monstros "Hierático" banidos; devolva o alvo para o Cemitério. \r\nSe este card com a face para cima no campo for enviado para o Cemitério: escolha 1 monstro "Hierático" no seu Cemitério; Invoque o alvo por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Usar o efeito de "Selo Hierático das Cinzas" agora?','Enviar para o Cemitério','Invocação Especial','Invocação Especial','','','','','','','','','','','','');
INSERT INTO texts VALUES(53678698,'Bujin Mikazuchi',replace(replace('Quando um ou mais monstros "Bujin" do Tipo Besta-Guerreira que você controla forem destruídos em batalha ou por efeitos de card e enviados para o Cemitério: você pode Invocar este card por Invocação-Especial da sua mão. \r\nUma vez por turno, durante a Fase Final, se um ou mais monstros "Bujin" foram enviados da sua mão para o seu Cemitério neste turno enquanto você controlava este card com a face para cima: você pode adicionar 1 Card de Magia/Armadilha "Bujin" do seu Deck à sua mão. \r\nVocê só pode controlar 1 "Bujin Mikazuchi".','\r',char(13)),'\n',char(10)),'Invocação Especial','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53693416,'Olho de Águia','Quando este card é Invocado, por Invocação-Normal, com sucesso, nenhum Card de Armadilha pode ser activado.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53701259,'Despertar das Bestas Sagradas',replace(replace('Este card ganha esses efeitos de acordo com o número de "Uria, o Senhor das Chamas Cortantes", "Hamon, o Senhor do Trovão Impactante" e/ou "Raviel, o Senhor dos Fantasmas" com nomes diferentes que você controla.\r\n● 1+: Sempre que seu oponente Invocar um ou mais monstros por Invocação-Normal ou Especial: ganhe PV igual ao ATK desses monstros.\r\n● 2+: Negue os efeitos ativados dos monstros que seu oponente controla.\r\n● 3: Quaisquer monstros enviados para o Cemitério do seu oponente, em vez disso, são banidos.	\r\nUma vez por turno seu, se você controlar um monstro de Nível 10: você pode adicionar 1 Armadilha Contínua do seu Cemitério à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53701457,'Número 28: Mariposa Colossal',replace(replace('2 monstros de Nível 7	\r\nSe você não controlar nenhum outro monstro, este card pode atacar diretamente, mas quando ele fizer isso usando este efeito, o dano de batalha causado ao seu oponente é diminuído pela metade. \r\nQuando este card causar dano de batalha ao seu oponente: você pode desassociar 1 matéria deste card; cause 500 de dano ao seu oponente para cada card na mão dele.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53713014,'Peixe Louco','Um peixe voador que ataca com sua cabeça pontiaguda.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53714009,'Flamvell Uruquizas',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nSe este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante. \r\nSe este card causar dano de batalha ao seu oponente: ele ganha 300 de ATK.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53724621,'Camarartista Guitartaruga',replace(replace('Escala de Pêndulo = 6\r\n[ Efeito de Pêndulo ]\r\nSe um card "Camarartista" for ativado na sua outra Zona de Pêndulo: você pode comprar 1 card. \r\nVocê só pode usar este efeito de "Camarartista Guitartaruga" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nUma vez por turno: você pode escolher 1 card na sua Zona de Pêndulo; até o final deste turno, aumente em 2 a Escala de Pêndulo dele.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53742162,'Erosão Gelojade',replace(replace('Você pode escolher 1 card com a face para cima que seu oponente controla; destrua 1 monstro "Gelojade" que você controla e, se isso acontecer, negue os efeitos do card alvo até o final deste turno. \r\nSe um monstro de ÁGUA com a face para cima que você controla deixar o campo devido a um card do oponente, exceto ao ser destruído (e exceto durante a Etapa de Dano): você pode adicionar à sua mão ou Invocar por Invocação-Especial, 1 monstro "Gelojade" do seu Deck. \r\nVocê só pode usar cada efeito de "Erosão Gelojade" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Adicionar à mão ou Invocar por Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53753697,'Zoa, a Besta Demoníaca',replace(replace('Se seu oponente controlar um monstro, você pode Invocar este card por Invocação-Normal sem oferecer Tributo. \r\nVocê só pode usar cada um dos seguintes efeitos de "Zoa, a Besta Demoníaca" uma vez por turno. \r\nSe este card estiver na sua mão: você pode Invocar este card por Invocação-Especial em Posição de Defesa e, depois, se "Metalmorfe Máximo" não estiver no seu Cemitério, seu oponente pode Invocar por Invocação-Especial 1 monstro da mão dele. \r\nDurante sua Fase Principal: você pode Baixar 1 Armadilha "Metalmorfe" do seu Deck.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Normal sem Tributo','Invocação Especial','Baixar uma Armadilha "Metalmorfe"','Invocação Especial?','','','','','','','','','','','','');
INSERT INTO texts VALUES(53754104,'Louva-a-deus Defensor',replace(replace('Você pode pagar 1000 PV; Invoque este card por Invocação-Especial da sua mão em Posição de Defesa, mas enquanto ele estiver com a face para cima na Zona de Monstros, você não pode Invocar monstros por Invocação-Especial, exceto monstros Inseto. \r\nDurante o turno do seu oponente (Efeito Rápido): você pode escolher 1 monstro Inseto que você controla; mude sua posição de batalha. \r\nVocê só pode usar cada efeito de "Louva-a-deus Defensor" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53754391,'Trovão Estrondoso Esbustalho',replace(replace('Sempre que um ou mais monstros não-Trovão forem Invocados por Invocação-Especial com a face para cima, enquanto este card estiver na Zona de Monstros: esse(s) monstro(s) não pode(m) atacar neste turno e, além disso, destrua-o(s) durante a Fase Final. \r\nSe este card estiver no seu Cemitério: você pode escolher 1 card com a face para cima que você controla; destrua-o e, se isso acontecer, adicione este card à sua mão. \r\nVocê só pode usar este efeito de "Trovão Estrondoso Esbustalho" uma vez por turno.','\r',char(13)),'\n',char(10)),'Restrição de ataque','Recuperar','O efeito de "Thundercrash Snarecrow" está sendo aplicado.','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53765052,'Diabellze, a Protetora do Pecado Original',replace(replace('Se um card "Despojos do Pecado" estiver no Cemitério de qualquer duelista, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Diabellze, a Protetora do Pecado Original" por Invocação-Especial uma vez por turno desta forma. \r\nSeu oponente deve Baixar Cards de Magia/Armadilha antes de ativá-los. \r\nSe uma Magia/Armadilha se tornar Baixada no campo, enquanto este card estiver na Zona de Monstros (exceto durante a Etapa de Dano): você pode escolher 1 card que você controla e 1 card que seu oponente controla; destrua-os. \r\nVocê só pode usar este efeito de "Diabellze, a Protetora do Pecado Original" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53765053,'Diabellze, a Protetora do Pecado Original',replace(replace('Se um card "Despojos do Pecado" estiver no Cemitério de qualquer duelista, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Diabellze, a Protetora do Pecado Original" por Invocação-Especial uma vez por turno desta forma. \r\nSeu oponente deve Baixar Cards de Magia/Armadilha antes de ativá-los. \r\nSe uma Magia/Armadilha se tornar Baixada no campo, enquanto este card estiver na Zona de Monstros (exceto durante a Etapa de Dano): você pode escolher 1 card que você controla e 1 card que seu oponente controla; destrua-os. \r\nVocê só pode usar este efeito de "Diabellze, a Protetora do Pecado Original" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53770666,'Reencarnação do Armamento',replace(replace('Invoque por Invocação-Especial "Ficha de Reencarnação do Armamento" (Guerreiro/LUZ/Nível 1/ATK 500/DEF 500) até o número de cards no seu Cemitério, que sejam Magias de Equipamento OU Armadilhas com efeitos que equipem a si mesmas como Cards de Equipamento e, depois, você pode aplicar o seguinte efeito e, além disso, você não pode Invocar por Invocação-Especial pelo resto deste turno.\r\n● Destrua tantos cards na sua Zona de Magias & Armadilhas quanto possível, incluindo este card e, depois, Baixe tantos cards quanto possível do seu Cemitério, que sejam Magias de Equipamento OU Armadilhas com efeitos que equipem a si mesmas como Cards de Equipamento.	\r\nEssas Armadilhas Baixadas podem ser ativadas neste turno.','\r',char(13)),'\n',char(10)),'Ativar','Continuar a Invocar Fichas por Invocação Especial?','Aplicar o seguinte efeito?','Ativar aplicando o efeito de "Reencarnação do Armamento".','','','','','','','','','','','','');
INSERT INTO texts VALUES(53770667,'Ficha de Armamento da Reencarnação','Invocado por Invocação-Especial pelo efeito de "Armamento da Reencarnação".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53776525,'Gigobyte','Ele tem uma alma tranquila, mas carrega o destino de que um dia o seu coração será corrompido pelo mal….','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53776969,'Espantagarra Luz-Heart',replace(replace('1 monstro "Espantagarra" ou 1 "Visas Starfrost"	\r\nPara a Invocação-Link deste card, você só pode usar monstros na sua Zona de Monstros Principal como matéria. \r\nSe este card for Invocado por Invocação-Link na Zona de Monstros Adicional: você pode adicionar 1 "Planeta Primitivo Reichphobia" do seu Deck à sua mão. \r\nSe você controlar "Visas Starfrost": você pode Invocar este card por Invocação-Especial do seu Cemitério. \r\nVocê só pode usar este efeito de "Espantagarra Luz-Heart" uma vez por Duelo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53778229,'Cemitério Silencioso','Descarte 1 card; neste turno, os efeitos que ativam no Cemitério são negados.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53782828,'Força-S Retroativa',replace(replace('Se um monstro que você controla seria usado como Matéria Link para um monstro "Força-S", este card na sua mão também pode ser usado como matéria. \r\nDurante a Fase Principal (Efeito Rápido): você pode devolver este card para a mão e, se isso acontecer, Invoque por Invocação-Especial 1 monstro "Força-S" de Nível 2 ou mais da sua mão. \r\nSe um monstro "Força-S" que você controla baniria um ou mais cards da sua mão para ativar seu efeito, em vez disso, você pode banir este card do seu Cemitério. \r\nVocê só pode usar cada efeito de "Força-S Retroativa" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53792930,'Liberação Forçada K9-X',replace(replace('Durante a Fase Principal: escolha 1 Monstro Xyz "K9" que você controla; Invoque por Invocação-Especial do seu Deck Adicional, 1 Monstro Xyz "K9" com um nome diferente, usando esse monstro que você controla (isso é considerado uma Invocação-Xyz, transfira as matérias dele para o monstro Invocado) e, depois, você pode destruir 1 card que seu oponente controla. \r\nNo final da Fase de Batalha, se um monstro "K9" seu batalhou neste turno: você pode Baixar este card do seu Cemitério. \r\nVocê só pode usar cada efeito de "Liberação Forçada K9-X" uma vez por turno.','\r',char(13)),'\n',char(10)),'Xyz','Baixar','Destruir o card?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53797637,'Chamusca, Dragão Soberado das Faíscas',replace(replace('(Este card deve ser sempre considerado como um card "Dragão Soberano".)	\r\nVocê pode descartar este card e 1 monstro Dragão ou de FOGO; Invoque por Invocação-Especial 1 "Dinamite, Dragão Soberano dos Infernos" do seu Deck, mas ele não pode atacar neste turno. \r\nVocê só pode usar este efeito de "Chamusca, Dragão Soberado das Faíscas" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53804307,'Dinamite, Dragão Soberano dos Infernos',replace(replace('Se este card estiver na sua mão ou no Cemitério: você pode banir um total de 2 monstros de FOGO e/ou Dragão da sua mão e/ou do Cemitério, exceto este card; Invoque este card por Invocação-Especial. \r\nDurante a Fase Final do seu oponente, se você controlar este card Invocado por Invocação-Especial: devolva-o para a mão. \r\nVocê pode descartar este card e 1 monstro de FOGO para o Cemitério e, depois, escolha 1 card no campo; destrua o alvo. \r\nSe este card for banido: você pode adicionar 1 monstro Dragão de FOGO do seu Deck à sua mão. \r\nVocê só pode usar 1 efeito de "Dinamite, Dragão Soberano dos Infernos" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial da mão','Retornar à mão','Escolha 1 card no Campo para destruí-la','Adicionar à mão','','','','','','','','','','','','');
INSERT INTO texts VALUES(53813120,'Mandato do Tufão Radiante',replace(replace('Uma vez por turno: você pode escolher 3 Magias Rápidas no seu Cemitério, incluindo um card "Tufão Radiante"; aplique os seguintes efeitos em sequência.\r\n● Embaralhe-as no Deck e, depois, compre 1 card.\r\n● Todos os monstros de VENTO que você controla ganham 300 de ATK/DEF neste turno.	\r\nUma vez por Corrente, quando "Tufão Espacial Místico" for ativado: você pode escolher 1 card com a face para cima que seu oponente controla; negue seus efeitos. \r\nSe este card for destruído pelo efeito de "Tufão Espacial Místico": você pode Baixar este card.','\r',char(13)),'\n',char(10)),'Efeito de recuperação','Negar o efeito','Baixar','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53819028,'Predaplanta Formisarracenia',replace(replace('Quando um monstro do oponente declarar um ataque direto: você pode Invocar este card por Invocação-Especial da sua mão. \r\nDepois do cálculo de dano, se este card batalhou um monstro do oponente: você pode destruir esse monstro do oponente. \r\nSe este card for destruído em batalha, ou se este card no campo for enviado para o Cemitério por um efeito de card: você pode adicionar 1 card "Predap" do seu Deck à sua mão, exceto "Predaplanta Formisarracenia". \r\nVocê só pode usar este efeito de "Predaplanta Formisarracenia" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53819808,'Templo dos Seis',replace(replace('Sempre que um ou mais monstros "Seis Samurai" for Invocado por Invocação-Normal ou Especial, coloque 1 Marcador de Bushido neste card. \r\nOs monstros que seu oponente controla perdem 100 de ATK para cada Marcador de Bushido neste card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53828396,'Explosivo Adesivo',replace(replace('Antes do cálculo de dano, se este card foi atacado por um monstro do oponente e estava com a face para baixo em Posição de Defesa no começo da Etapa de Dano: equipe este card no monstro atacante. \r\nDepois, durante a próxima Fase de Apoio do seu oponente, destrua o monstro no qual este card está equipado.','\r',char(13)),'\n',char(10)),'Tornar-se um Card de Equipamento','Destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53829412,'Griffore','A grossa couraça desse monstro desvia a maioria dos ataques.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53829527,'Aglomerado Cristron',replace(replace('Cards "Cristron" que você controla não podem ser banidos pelos efeitos de card do seu oponente. \r\nVocê pode escolher 1 card com a face para cima no campo ou, se você controlar um Monstro Sincro "Cristron", você pode escolher 2; embaralhe no Deck 1 card "Cristron" do seu Cemitério ou banimento, exceto "Aglomerado Cristron" e, se isso acontecer, destrua o(s) card(s) alvo. \r\nVocê só pode usar este efeito de "Aglomerado Cristron" uma vez por turno.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53830602,'Fungos do Almíscar','Derrete tudo aquilo que ousar se aproximar dele.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53832650,'Meotoko','Ess grannn monstro con un grannn olho dissspara un raio feeeo em vocé!','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53839837,'Senhor dos Vampiros',replace(replace('Se este card causar dano de batalha ao seu oponente: declare 1 tipo de card (Monstro, Magia ou Armadilha); seu oponente envia 1 card desse tipo do Deck dele para o Cemitério. \r\nUma vez por turno, durante sua próxima Fase de Apoio depois que este card em sua posse foi destruído e enviado para o seu Cemitério por um efeito de card do oponente: Invoque este card por Invocação-Especial do Cemitério.','\r',char(13)),'\n',char(10)),'Declarar um tipo de card; envie-o para o Cemitério','Card de Monstro','Card de Magia','Card de Armadilha','Invocação Especial','Declare um tipo de card','','','','','','','','','','');
INSERT INTO texts VALUES(53839838,'Senhor dos Vampiros',replace(replace('Se este card causar dano de batalha ao seu oponente: declare 1 tipo de card (Monstro, Magia ou Armadilha); seu oponente envia 1 card desse tipo do Deck dele para o Cemitério. \r\nUma vez por turno, durante sua próxima Fase de Apoio depois que este card em sua posse foi destruído e enviado para o seu Cemitério por um efeito de card do oponente: Invoque este card por Invocação-Especial do Cemitério.','\r',char(13)),'\n',char(10)),'Declarar um tipo de card; envie-o para o Cemitério','Card de Monstro','Card de Magia','Card de Armadilha','Invocação Especial','Declare um tipo de card','','','','','','','','','','');
INSERT INTO texts VALUES(53842431,'Besta Mítica Mestre Cérbero',replace(replace('Escala de Pêndulo = 4\r\n[ Efeito de Pêndulo ]\r\nSe você não tiver nenhum card na sua outra Zona de Pêndulo: você pode destruir este card e, se isso acontecer, adicione 1 Monstro de Efeito "Besta Mítica" de Nível 7 ou menos do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Besta Mítica Mestre Cérbero" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSempre que um Card de Magia for ativado, coloque 2 Marcadores de Magia neste card quando essa Magia resolver. \r\nNão pode ser destruído por efeitos de card enquanto 4 ou mais Marcadores de Magia estiverem no seu campo. \r\nUma vez por turno: você pode remover 4 Marcadores de Magia do seu campo e, depois, escolha 1 monstro que seu oponente controla; bana-o com a face para cima e, se isso acontecer, até o final do turno do oponente, este card ganha ATK igual ao ATK original do monstro banido.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53855409,'Guerreiro Doppel',replace(replace('Quando um ou mais monstros forem Invocados por Invocação-Especial do seu Cemitério (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe este card for enviado para o Cemitério como Matéria Sincro: você pode Invocar por Invocação-Especial 2 "Ficha de Doppel" (Guerreiro/TREVAS/Nível 1/ATK 400/DEF 400) em Posição de Ataque.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial da mão','Invocar uma Ficha por Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53855410,'Ficha de Doppel','Invocado por Especial com o efeito "Guerreiro Doppel".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53855411,'Ficha de Doppel','Invocado por Especial com o efeito "Guerreiro Doppel".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53860621,'Besta Brilhante',replace(replace('Só pode ser equipado a um monstro "Asanegra". \r\nEle ganha 500 de ATK/DEF. \r\nVocê só pode usar cada um dos seguintes efeitos de "Besta Brilhante" uma vez por turno.\r\n● Se o monstro equipado destruir um monstro do oponente em batalha: você pode descartar 1 card aleatório da mão do seu oponente.\r\n● Se este card for enviado para o Cemitério porque o monstro equipado foi usado como uma Matéria Sincro: você pode adicionar este card do Cemitério à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53865474,'Deslizador Ursártico',replace(replace('Escolha 1 dos seus monstros "Ursártico(a)" que estiverem banidos ou no seu Cemitério; Invoque-o por Invocação-Especial, mas ele não pode atacar e, além disso, destrua-o durante a Fase Final. \r\nPelo resto deste turno depois que este card resolver, você não pode Invocar por Invocação-Especial, exceto monstros com um Nível. \r\nVocê só pode ativar 1 "Deslizador Ursártico" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53871273,'Valquíria Caos',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial por um efeito de card. \r\nVocê pode banir 1 monstro de LUZ ou de TREVAS do seu Cemitério; Invoque este card por Invocação-Especial da sua mão. \r\nSe este card for banido: você pode enviar 1 monstro de LUZ ou de TREVAS do seu Deck para o Cemitério, mas pelo resto deste turno, você não pode ativar cards, ou os efeitos de cards, com o mesmo nome que o desse card. \r\nVocê só pode usar cada efeito de "Valquíria Caos" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53890795,'Saltador de Foguete','Se os únicos cards no Campo do seu adversário são monstros em Posição de Defesa, este card pode atacar diretamente os Life Points do seu adversário.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53904087,'Rahamu, o Enviado do Tomo Sagrado',replace(replace('2 Monstros de Efeito	\r\nUma vez, enquanto este card Invocado por Invocação-Link estiver com a face para cima no campo, você pode Invocar por Invocação-Normal 1 monstro de Nível 5 ou mais sem oferecer Tributo. \r\nDurante a Fase Principal, você pode (Efeito Rápido): imediatamente depois que este efeito resolver, Invocar por Invocação-Normal 1 monstro de TREVAS de Nível 5 ou mais. \r\nDurante sua Fase Final: você pode revelar qualquer número de monstros na sua mão e colocá-los no fundo do Deck em qualquer ordem e, depois, compre cards igual ao número colocado. \r\nVocê só pode usar cada efeito de "Rahamu, o Enviado do Tomo Sagrado" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Normal sem Tributo, pelo efeito de "Rahamu, o Enviado do Tomo Sagrado"','Invocação Normal','Comprar','O primeiro efeito já foi aplicado','','','','','','','','','','','','');
INSERT INTO texts VALUES(53921056,'General Gantala da Barreira de Gelo','Uma vez por turno, durante sua Fase Final: você pode escolher 1 monstro "Barreira de Gelo" no seu Cemitério, exceto "General Gantala da Barreira de Gelo"; Invoque-o por Invocação-Especial.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53923690,'Julgamento Ômega','Escolha 1 Card de Monstro com a face para cima na sua Zona de Magias & Armadilhas e 2 cards que seu oponente controla; destrua-os.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53927679,'Soldado do Fogo','Quando este card for Invocado, você pode enviá-lo para o Cemitério para causar 1000 de dano ao seu oponente','Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53927851,'Tufão Radiante Varuroon, o Vórtice Vibrante',replace(replace('Se um Card de Magia Rápida for ativado (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão. \r\nQuando seu oponente ativar um efeito de monstro e você tiver "Tufão Espacial Místico" no seu Cemitério (Efeito Rápido): você pode negar o efeito e, depois, se você tiver 2 ou mais "Tufão Espacial Místico" no seu Cemitério, você pode destruir esse monstro. \r\nSe "Tufão Espacial Místico" for ativado enquanto este card estiver no seu Cemitério: você pode Invocar este card por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Tufão Radiante Varuroon, o Vórtice Vibrante" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Negar o efeito','Invocação Especial','Destruir o card?','','','','','','','','','','','','');
INSERT INTO texts VALUES(53932291,'Velocidaroide Taketomborg',replace(replace('Se você controlar um monstro de VENTO, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê pode oferecer este card como Tributo; Invoque por Invocação-Especial 1 Regulador "Velocidaroide" do seu Deck e, além disso, você não pode Invocar por Invocação-Especial pelo resto deste turno, exceto monstros de VENTO. \r\nVocê só pode Invocar um ou mais "Velocidaroide Taketomborg" por Invocação-Especial uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Oferecer como Tributo e Invocar por Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53936268,'Spoofing Pessoal','Uma vez por turno: você pode embaralhar no Deck Principal 1 card "Altergeist" da sua mão ou com a face para cima no seu campo; adicione 1 monstro "Altergeist" do seu Deck à sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53944920,'Fornalha Genex','Se você controlar um "Controlador Genex" com a face para cima, você pode Invocar este card por Invocação-Normal sem oferecer Tributo.','Invocação Normal sem Tributo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53950487,'Vespabatalha - Halberd, a Carga',replace(replace('1 Inseto Regulador + 1+ monstros não-Reguladores	\r\nUma vez por batalha, durante o cálculo de dano, se este card atacar um monstro do oponente de ATK igual ou maior (Efeito Rápido): você pode diminuir pela metade o ATK desse monstro do oponente, apenas durante esse cálculo de dano. \r\nQuando este card causar dano de batalha ao seu oponente: você pode causar 200 de dano ao seu oponente para cada monstro "Vespabatalha" que você controla. \r\nVocê só pode usar este efeito de "Vespabatalha - Halberd, a Carga" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53956001,'Tela do Clima Nublado',replace(replace('Monstros de Efeito "do Clima" nas suas Zonas de Monstros Principais da coluna deste card e das colunas adjacentes a ela ganham este efeito.\r\n● Você pode banir este card e, depois, escolha 1 monstro com a face para cima no campo (exceto durante a Etapa de Dano) (Efeito Rápido); pelo resto deste turno, diminua o ATK atual dele pela metade, mas ele pode atacar diretamente neste turno.	\r\nVocê só pode controlar 1 "Tela do Clima Nublado".','\r',char(13)),'\n',char(10)),'Reduza o ATK pela metade e ataque diretamente (Tela do Clima Nublado)','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53971455,'Despiana Luluwalilith',replace(replace('1 Regulador de Nível 4 + 1+ não-Reguladores	\r\nUma vez por turno, se um ou mais cards deixarem o Deck Adicional (exceto durante a Etapa de Dano): você pode fazer com que todos os monstros que você controla atualmente ganhem 500 de ATK (permanentemente) e, depois, você pode negar os efeitos de 1 card com a face para cima no campo, até o final deste turno. \r\nDurante a Fase Final, se este card estiver no Cemitério porque foi enviado para lá neste turno: você pode Invocar por Invocação-Especial 1 monstro Mago de LUZ da sua mão ou do Deck cujo ATK seja igual à sua própria DEF. \r\nVocê só pode usar este efeito de "Despiana Luluwalilith" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Negar os efeitos de um card?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53981499,'Guerreiro Poderoso',replace(replace('1 Regulador + 1 ou mais monstros não-Reguladores	\r\nSe este card destruir um monstro do oponente em batalha: cause dano ao seu oponente igual à metade do ATK original do monstro destruído.','\r',char(13)),'\n',char(10)),'Causar dano aos PV','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53982768,'Governante Sombrio Ha Des',replace(replace('Não pode ser Invocado por Invocação-Especial do Cemitério. \r\nNegue os efeitos de monstros destruídos em batalha com monstros Demônio que você controla.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(53989821,'APARATO ESPIRÃO - Fio Utilitário',replace(replace('Se você controlar "Super Agente ESPIRÃO": escolha 1 card com a face para cima que seu oponente controla; coloque-o no topo do Deck. \r\nVocê só pode ativar 1 "APARATO ESPIRÃO - Fio Utilitário" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54020393,'Liberar Eneanave',replace(replace('Coloque 1 Monstro Pêndulo "Eneanave" do seu Deck na sua Zona de Pêndulo. \r\nSe este card estiver no seu Cemitério, exceto no turno em que foi enviado para lá: você pode bani-lo; adicione 1 monstro "Eneanave" com a face para cima do seu Deck Adicional à sua mão. \r\nVocê só pode ativar 1 "Liberar Eneanave" por turno.','\r',char(13)),'\n',char(10)),'Colocar','Recuperar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54031490,'Sinal de Fumaça de Shien','Adicione 1 monstro "Seis Samurai" de Nível 3 ou menos do seu Deck à sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54040221,'Guardas Reais da Tempestade de Fogo','Se este card for Invocado por Invocação-Normal: escolha 4 monstros Piro no seu Cemitério; embaralhe todos os 4 no Deck e, depois, compre 2 cards.','Retornar ao Deck e comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54040484,'Núcleo do Caos',replace(replace('Quando qualquer duelista ativar um card ou efeito que escolha este card como alvo, ou quando um monstro do seu oponente escolhê-lo como alvo de um ataque (Efeito Rápido): você pode enviar até 1 de cada de "Uria, o Senhor das Chamas Cortantes", "Hamon, o Senhor do Trovão Impactante" e "Raviel, o Senhor dos Fantasmas" da sua mão e/ou do Deck para o Cemitério e, se isso acontecer, coloque 1 Marcador de Fantasma neste card para cada card enviado para o Cemitério e, se você colocou pelo menos 1, você não sofre dano de batalha neste turno. \r\nVocê só pode usar este efeito de "Núcleo do Caos" uma vez por turno. \r\nSe este card seria destruído em batalha ou por um efeito de card, em vez disso, você pode remover 1 Marcador de Fantasma deste card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54048462,'Valkyrus Mitológico',replace(replace('1 Regulador "Mitológico(a)" + 1+ monstros não-Reguladores	\r\nUma vez por turno: você pode descartar 1 monstro Demônio; compre 1 card.','\r',char(13)),'\n',char(10)),'Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54059040,'Eisbahn','Se um ou mais monstros que não sejam de ÁGUA forem Invocados por Invocação-Normal ou Especial enquanto você controlar um monstro de ÁGUA: coloque o monstro Invocado em Posição de Defesa.','Mudar para Posição de Defesa','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54077752,'Olhar dos Cabelos de Cobras',replace(replace('Você pode descartar este card; adicione 1 "Chamado dos Assombrados" ou 1 Magia/Armadilha que o mencione do seu Deck à sua mão. \r\nSe este card for Invocado por Invocação-Especial: você pode escolher 1 monstro em Posição de Ataque que seu oponente controla; esse monstro com a face para cima não pode atacar, seus efeitos são negados e, além disso, ele não pode ser usado como matéria para uma Invocação-Fusão, Sincro, Xyz ou Link. \r\nVocê só pode usar cada efeito de "Olhar dos Cabelos de Cobras" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Negar o efeito','O efeito de "Olhar dos Cabelos de Cobras" está sendo aplicado.','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54082269,'Mestre de Armadura Completa Asanegra',replace(replace('1 Regulador "Asanegra" + 1+ monstros não-Reguladores	\r\nNão é afetado por outros efeitos de cards. \r\nSempre que um monstro do oponente ativar seu efeito, coloque 1 Marcador de Cunha nesse monstro do oponente (máx. 1) quando esse efeito resolver. \r\nUma vez por turno: você pode escolher 1 monstro que seu oponente controla com um Marcador de Cunha; tome o controle dele. \r\nUma vez por turno, durante sua Fase Final: você pode destruir todos os monstros no campo que tenham um Marcador de Cunha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54088068,'Gouki Cabeça de Morcego',replace(replace('Se este card estiver na sua mão: você pode enviar 1 outro monstro "Gouki" da sua mão para o Cemitério e, depois, escolher 1 monstro "Gouki" que você controla; Invoque este card por Invocação-Especial em Posição de Defesa e, se isso acontecer, o monstro alvo ganha 800 de ATK até o final deste turno. \r\nSe este card for enviado do campo para o Cemitério: você pode adicionar 1 card "Gouki" do seu Deck à sua mão, exceto "Gouki Cabeça de Morcego". \r\nVocê só pode usar cada efeito de "Gouki Cabeça de Morcego" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54092240,'Aparato Celestial Tesea',replace(replace('Se você controlar uma "Ficha de Aventura": você pode Invocar este card por Invocação-Especial da sua mão. \r\nVocê pode revelar 1 card na sua mão que mencione uma "Ficha de Aventura"; adicione 1 Magia que mencione uma "Ficha de Aventura" do seu Deck à sua mão, exceto uma Magia Normal. \r\nVocê não pode Invocar monstros por Invocação-Especial no turno em que ativar este efeito, exceto uma "Ficha de Aventura" ou monstros que a mencionem. \r\nVocê só pode usar cada efeito de "Aparato Celestial Tesea" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54094821,'Demolidor Ritual',replace(replace('Só pode ser ativado quando um Monstro de Ritual for Invocado por Invocação-Ritual. \r\nSeu oponente não pode ativar quaisquer Cards de Magia ou Armadilha ou usar seus efeitos até a sua próxima Fase de Apoio.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54098121,'Misterioso Mestre das Marionetes',replace(replace('(Este card não é considerado como um card "Marionete".)	\r\nSe outro monstro for Invocado por Invocação-Normal ou Virar: ganhe 500 PV.','\r',char(13)),'\n',char(10)),'Ganhar PV','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54100561,'FaSolfacorde Fancia',replace(replace('Escala de Pêndulo = 5\r\n[ Efeito de Pêndulo ]\r\nA Invocação-Pêndulo dos seus Monstros Pêndulo "Solfacorde" não pode ser negada.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nEnquanto você tiver uma Escala de Pêndulo ímpar na sua Zona de Pêndulo, se um Monstro Pêndulo "Solfacorde" seu seria destruído em batalha, em vez disso, você pode destruir este card. \r\nDurante sua Fase Principal: você pode adicionar 1 Monstro Pêndulo "Solfacorde" do seu Deck ao seu Deck Adicional com a face para cima, exceto "FaSolfacorde Fancia". \r\nVocê só pode usar este efeito de "FaSolfacorde Fancia" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Escolha 1 card para adicionar ao Deck Adicional','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54109233,'Dispensar Infinito','Monstros de Nível 3 ou menos são destruídos durante a Fase Final do turno em que foram Invocados por Invocação-Normal ou Virar.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54112932,'Batata & Chips','Batata e Chips sempre se dão bem. Eles sempre ficam na sala, comendo batatas fritas. As de punch de consommé também são deliciosas. As de Norishio também são deliciosas. A deliciosa vida de Batata e Chips.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54120521,'A Lenda dos Ingressos',replace(replace('Escolha 1 card no seu Cemitério; coloque-a no topo do Deck durante a Fase Final deste turno, além disso, compre 2 cards em vez de 1 durante a sua próxima Fase de Compra. \r\nVocê pode ativar apenas 1 ''A Lenda dos Ingressos'' por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54126514,'Peritrador Altergeist',replace(replace('Este card pode atacar diretamente. \r\nVocê só pode usar cada um dos seguintes efeitos de "Peritrador Altergeist" uma vez por turno. \r\nQuando este card causar dano de batalha ao seu oponente: você pode comprar 1 card. \r\nSe este card for enviado do campo para o Cemitério: você pode enviar para o Cemitério 1 card "Altergeist" da sua mão, do Deck ou do campo com a face para cima, exceto "Peritrador Altergeist".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54135423,'Flor Cardian Salgueiro',replace(replace('Enquanto você controlar um monstro "Flor Cardian" de Nível 10 ou menos: você pode Invocar este card por Invocação-Especial da sua mão e, além disso, você não pode Invocar monstros por Invocação-Normal ou Especial pelo resto deste turno, exceto monstros "Flor Cardian". \r\nUma vez por turno: você pode escolher 1 monstro "Flor Cardian" no seu Cemitério; embaralhe-o no seu Deck e, depois, compre 1 card.','\r',char(13)),'\n',char(10)),'Invocação Especial','Recuperar do Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54143349,'Tufão Radiante Eldam',replace(replace('Se você tiver "Tufão Espacial Místico" no seu Cemitério, ou seu oponente não controlar nenhuma Magia/Armadilha, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Tufão Radiante Eldam" por Invocação-Especial uma vez por turno desta forma. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 monstro "Tufão Radiante" (exceto "Tufão Radiante Eldam") ou 1 "Tufão Espacial Místico" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Tufão Radiante Eldam" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54149433,'Avatar do Rei de Fogo Garunix',replace(replace('Se um ou mais monstros "Rei(s) de Fogo" com a face para cima que você controla forem destruídos por um efeito de card (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe este card em sua posse for destruído por um card do oponente e enviado para o seu Cemitério: você pode Invocar por Invocação-Especial 1 monstro "Avatar do Rei de Fogo" do seu Deck.','\r',char(13)),'\n',char(10)),'Invocação Especial','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54161401,'Rocha de Naturia','Uma vez por Corrente, quando um Card de Armadilha for ativado (Efeito Rápido): você pode enviar o card do topo do seu Deck para o Cemitério; Invoque este card por Invocação-Especial da sua mão.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54171327,'Distúrbio de Anjoléquia',replace(replace('Conceda o controle de 1 monstro "Anjoléquia" que você controla ao seu oponente (até a Fase Final) e, depois, se seu oponente controlar um ou mais cards com a face para cima em suas Zonas de Monstros e/ou Zonas de Magias & Armadilhas adjacentes, seus efeitos são negados. \r\nVocê pode banir este card do seu Cemitério; adicione 1 Magia/Armadilha "Anjoléquia" do seu Deck à sua mão, exceto "Distúrbio de Anjoléquia". \r\nVocê só pode usar cada efeito de "Distúrbio de Anjoléquia" uma vez por turno.','\r',char(13)),'\n',char(10)),'Transferir o controle','Efeito de busca','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54175023,'Guardião Dimensional',replace(replace('Ative este card ao escolher 1 monstro com a face para cima em Posição de Ataque que você controla. \r\nEle não pode ser destruído em batalha ou por efeitos de cards. \r\nSe o monstro escolhido deixar o campo, destrua este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54178050,'Ira do Dragão','Se um monstro Dragão seu atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54178659,'Pintora do Clima Arco-Íris',replace(replace('3 monstros "do Clima"	\r\nQuando seu oponente Invocaria um ou mais monstros por Invocação-Especial (Efeito Rápido): você pode enviar este card Invocado por Invocação-Link para o Cemitério; negue a Invocação e, se isso acontecer, destrua esses monstros. \r\nUma vez por turno, durante a Fase de Apoio do turno seguinte ao qual este card foi banido do campo para ativar um efeito de card "do Clima": você pode Invocar este card banido por Invocação-Especial. \r\nOs Monstros de Efeito "do Clima" para os quais este card apontar ganham o seguinte efeito.\r\n● Quando um card ou efeito for ativado (Efeito Rápido): você pode banir este card; negue a ativação e, se isso acontecer, destrua esse card.','\r',char(13)),'\n',char(10)),'Negar a Invocação Especial e destruir','Invoque este card banido por Invocação Especial','Negar a ativação e destruir (Pintora do Clima Arco-Íris)','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54185227,'Gravito, o HERÓI da Visão',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 dos seus monstros "HERÓI" banidos; adicione-o à sua mão. \r\nVocê pode oferecer este card como Tributo e, depois, escolha 2 Cards de Monstro "HERÓI da Visão" na sua Zona de Magias & Armadilhas; Invoque-os por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Gravito, o HERÓI da Visão" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54191698,'Número 29: Gato Manequim',replace(replace('2 monstros de Nível 2	\r\nUma vez por turno: você pode desassociar 1 matéria deste card e, depois, escolha 1 monstro no Cemitério do seu oponente; Invoque-o por Invocação-Especial no campo do seu oponente. \r\nSe um ou mais monstros forem Invocados por Invocação-Especial no campo do seu oponente, enquanto você controlar este monstro (exceto durante a Etapa de Dano): você pode escolher 1 monstro com a face para cima que seu oponente controla; Invoque por Invocação-Especial 1 monstro com o mesmo Tipo ou Atributo da sua mão, do Deck ou do Cemitério. \r\nVocê só pode usar este efeito de "Número 29: Gato Manequim" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54199839,'Ascensão Metafis',replace(replace('Descarte 1 card "Metafis"; compre 1 card e, depois, você pode banir 1 monstro "Metafis" do seu Deck. \r\nSe este card for banido: você pode adicionar 1 card "Metafis" do seu Deck à sua mão, exceto "Ascensão Metafis". \r\nVocê só pode usar 1 efeito de "Ascensão Metafis" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Banir 1 monstro "Metafis"?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54207171,'Akihiron Mementotlan',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode ativar este efeito; neste turno, monstros "Memento" de Nível 9 ou mais podem atacar diretamente. \r\nSe este card for destruído por um efeito de card: você pode escolher 1 dos seus outros cards "Memento" que estiverem banidos ou no seu Cemitério; adicione-o à sua mão. \r\nSe um ou mais monstros "Memento" na sua mão e/ou no campo com a face para cima forem destruídos em batalha ou por um efeito de card, enquanto este card estiver no seu Cemitério: você pode Invocar este card por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Akihiron Mementotlan" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ataque direto','Retornar para a mão','Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54239282,'Mico Preto',replace(replace('Olhe 1 card aleatório na mão do seu oponente e, depois, aplique 1 dos seguintes efeitos.\r\n● Descarte tanto esse card do oponente quanto 1 card da sua mão com o mesmo tipo (Monstro, Magia ou Armadilha) e, depois, adicione este card do campo à mão do seu oponente e, se isso acontecer, compre 1 card.\r\n● Perca 1000 PV.	\r\nVocê só pode ativar 1 "Mico Preto" por turno.','\r',char(13)),'\n',char(10)),'Descarte 1 card','Perder PV','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54241725,'O Monarca Primordial',replace(replace('Uma vez por turno: você pode escolher 2 Magias/Armadilhas "Monarca" no seu Cemitério; embaralhe-as no Deck e, depois, compre 1 card. \r\nSe este card estiver no seu Cemitério: você pode banir 1 outra Magia/Armadilha "Monarca" do seu Cemitério; Invoque este card por Invocação-Especial em Posição de Defesa como um Monstro Normal (Fada/LUZ/Nível 5/ATK 1000/DEF 2400).	\r\n(Este card NÃO é considerado como uma Armadilha.) \r\nVocê só pode usar este efeito de "O Monarca Primordial" uma vez por turno.','\r',char(13)),'\n',char(10)),'Embaralhar no Deck?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54248491,'Aranha Renunciada','Se você tiver 4 ou mais monstros do Tipo Inseto no seu Cemitério, você pode oferecer este card como Tributo para destruir todos os monstros com a face para cima em Posição de Defesa que seu oponente controla.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54250060,'Edificar',replace(replace('Todos os monstros do Tipo Dragão, Guerreiro e Mago que você controla ganham 300 de ATK e DEF. \r\nUma vez por turno: você pode descartar 1 card; Invoque por Invocação-Especial 1 monstro "Guerreiro(a) Edificado(a)" do seu Deck. \r\nUma vez por turno: você pode banir um total de 4 monstros do Tipo Guerreiro e/ou Mago do seu Cemitério; adicione 1 monstro "Éter" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Invocação Especial','Procurar no Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54257392,'Live☆Gêmea Ki-sikil Gélida',replace(replace('Se você controlar um monstro "Lil-la", você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Live☆Gêmea Ki-sikil Gélida" por Invocação-Especial uma vez por turno desta forma. \r\nSe um ou mais cards forem adicionados do Deck Principal à mão do seu oponente por um efeito de card (exceto durante a Etapa de Dano), enquanto você controlar um monstro "Evil★Gêmea": você pode banir este card do seu Cemitério; compre 1 card. \r\nVocê só pode usar este efeito de "Live☆Gêmea Ki-sikil Gélida" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Banir e comprar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54261514,'Arauto Final do Fim dos Tempos',replace(replace('Escolha 1 monstro que você controla e 1 card que seu oponente controla; destrua-os. \r\nVocê só pode ativar 1 "Arauto Final do Fim dos Tempos" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54265980,'DoomZ VII Sete - Elara',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial, ou destruído por um efeito de card: você pode Baixar 1 Magia/Armadilha "DoomZ" do seu Deck. \r\nEnquanto este card estiver equipado com um Card de Equipamento (Efeito Rápido): você pode Invocar por Invocação-Especial 1 Monstro Xyz Máquina de VENTO do seu Deck Adicional com a mesma Classe que o Nível deste card e, se isso acontecer, associe este card e seus Cards de Equipamento a esse monstro como matéria (isso é considerado uma Invocação-Xyz). \r\nVocê só pode usar cada efeito de "DoomZ VII Sete - Elara" uma vez por turno.','\r',char(13)),'\n',char(10)),'Baixar','Invocação Xyz','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54266211,'Evolssauro Vulcano',replace(replace('Quando este card for Invocado por Invocação-Especial pelo efeito de um monstro "Evoltil": Você pode escolher 1 monstro "Evolssauro" no seu Cemitério; Invoque o alvo por Invocação-Especial. \r\nEle não pode declarar um ataque.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54283059,'Fusão do Mundo Paralelo',replace(replace('Invoque por Invocação-Fusão 1 Monstro de Fusão "HERÓI do Elemento" do seu Deck Adicional, ao embaralhar no seu Deck as Matérias de Fusão banidas listadas nele. \r\nDurante o turno em que ativar este card, você não pode Invocar monstros por Invocação-Especial exceto pelo efeito deste card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54289683,'Cápsula de Poder',replace(replace('Selecione 1 "Vitória Víbora XX03" com a face para cima que você controla para ativar este card. \r\nSelecione 1 efeito de "Vitória Víbora XX03" e aplique-o como efeito deste card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54297661,'Refletor Dimensional',replace(replace('Ative este card ao banir 2 monstros que você controla e, depois, escolha 1 monstro com a face para cima que seu oponente controla; Invoque este card por Invocação-Especial em Posição de Ataque como um Monstro de Efeito (Tipo Mago/TREVAS/Nível 4/ATK ?/DEF ?) com ATK e DEF iguais ao ATK desse monstro com a face para cima.	\r\n(Este card ainda é considerado um Card de Armadilha.) \r\nSe este monstro for Invocado desta forma: cause dano ao seu oponente igual ao ATK deste card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54306223,'Pântano Peçonha',replace(replace('Durante a Fase Final de cada duelista: Coloque 1 Marcador de Veneno em cada monstro com a face para cima, exceto monstros "Peçonha". \r\nMonstros perdem 500 de ATK para cada Marcador de Veneno sobre eles. \r\nDestrua um monstro se seu ATK se tornar 0 por este efeito.','\r',char(13)),'\n',char(10)),'Colocar um marcador','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54320860,'Patriarca Inférnico',replace(replace('Se este for o único card na sua mão, você pode Invocá-lo por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Patriarca Inférnico" por Invocação-Especial uma vez por turno desta forma. \r\nEnquanto você não tiver nenhum card na sua mão, se um ou mais monstros "Inférnico" que você controla seriam destruídos em batalha ou por um efeito de card, em vez disso, você pode banir este card do seu Cemitério.','\r',char(13)),'\n',char(10)),'Usar o efeito de "Patriarca Inférnico" em vez de ser destruído?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54326448,'Arqueiro de Flamvell','Uma vez por turno, você pode oferecer como Tributo 1 monstro do Tipo Piro com a face para cima que você controla para fazer com que todos os monstros "Flamvell" no campo ganhem 800 de ATK até a Fase Final.','Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54332792,'Neo Cavalo-marinho de Kaiser',replace(replace('Se você controlar "Dragão Branco de Olhos Azuis": você pode Invocar este card por Invocação-Especial da sua mão. \r\nVocê pode escolher 1 Regulador de LUZ que você controla; aumente ou diminua o Nível dele em 1. \r\nSe este card for enviado do campo para o Cemitério: você pode enviar 1 monstro "Olhos Azuis" ou 1 monstro que mencione "Dragão Branco de Olhos Azuis" do seu Deck para o Cemitério, exceto "Neo Cavalo-marinho de Kaiser". \r\nVocê só pode usar cada efeito de "Neo Cavalo-marinho de Kaiser" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial da mão','Alterar Nível','Enviar do Deck para o Cemitério','Aumentar o Nível','Reduzir o Nível','','','','','','','','','','','');
INSERT INTO texts VALUES(54334420,'Brisawntarilho & Águian',replace(replace('Se este card com a face para cima deixaria o campo, em vez disso, bana-o. \r\nVocê só pode usar cada um dos seguintes efeitos de "Brisawntarilho & Águian" uma vez por turno e não pode Invocar por Invocação-Especial durante o turno em que ativar qualquer desses efeitos. \r\nSe este card for Invocado por Invocação-Normal: você pode adicionar 1 monstro Besta Alada de Nível 7 ou mais do seu Deck à sua mão e, depois, imediatamente depois que este efeito resolver, você pode Invocar 1 monstro Besta Alada por Invocação-Normal. \r\nSe um monstro Besta Alada for Invocado por Invocação-Normal no seu campo enquanto este card estiver banido: você pode adicionar este card à sua mão.','\r',char(13)),'\n',char(10)),'','Adicionar este card à sua mão','Invocar 1 monstro Besta Alada?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54338958,'Célula Hordeum Ferro',replace(replace('Se você não controlar nenhum monstro, você pode Invocar por Invocação-Especial este card (da sua mão). \r\nEnquanto este card estiver com a face para cima no campo, ele não pode ser oferecido como Tributo, exceto para a Invocação-Tributo de um monstro "Hordeum Ferro", e não pode ser usado como um Monstro-Matéria Sincro.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54340229,'Florescer de Solaravalon',replace(replace('Quando este card for ativado: se você controlar um monstro Planta de Link-4 ou mais quando este efeito resolver, negue os efeitos de todos os monstros com a face para cima que seu oponente controla atualmente. \r\nDurante o cálculo de dano, se um Monstro Link Planta seu batalhar: você pode ativar este efeito; até o final deste turno, ele ganha ATK igual ao ATK combinado dos monstros para o qual ele apontar atualmente. \r\n(Esses efeitos permanecem mesmo que este card deixe o campo.) \r\nVocê só pode usar este efeito de "Florescer de Solaravalon" uma vez por turno. \r\nVocê só pode ativar 1 "Florescer de Solaravalon" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54343893,'Vice-Dragão','Se somente seu oponente controlar um monstro, você pode Invocar este card por Invocação-Especial (da sua mão), mas seu ATK/DEF originais são diminuídos pela metade.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54351224,'Arma de Ritual',replace(replace('Só pode ser equipado a um Monstro de Ritual de Nível 6 ou menos. \r\nEle ganha 1500 de ATK/DEF.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54358015,'Dragão Furtivo da Galáxia',replace(replace('2 monstros Dragão de Nível 4	\r\nUma vez por turno: você pode desassociar 1 matéria deste card; Invoque por Invocação-Especial 1 monstro Dragão da sua mão. \r\nSeu oponente não pode escolher outros cards "Galáxia" que você controla como alvo de efeitos de card e, além disso, esses cards não podem ser destruídos pelos efeitos de card do seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54359696,'Estoico da Profecia','Quando este card for enviado ao Cemitério: Adicione 1 monstro "Profecia" de Nível 3 do seu Deck à sua mão.','Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54360049,'Catóblepa e a Bruxa do Destino','Quando seu oponente Invocar um ou mais monstros por Invocação-Especial, você pode remover de jogo 1 monstro com ? de ATK do seu Cemitério para destruir esses monstros Invocados por Invocação-Especial.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54366836,'Número 54: Coração de Leão',replace(replace('3 monstros de Nível 1	\r\nEste card em Posição de Ataque não pode ser destruído em batalha. \r\nSe você sofrer dano de batalha das batalhas envolvendo este card: cause dano ao seu oponente igual ao dano de batalha que você sofreu. \r\nUma vez por batalha, durante o cálculo de dano, se este card batalhar um monstro do oponente (Efeito Rápido): você pode desassociar 1 matéria deste card; seu oponente sofre qualquer dano de batalha que você teria sofrido nessa batalha.','\r',char(13)),'\n',char(10)),'Causar dano aos PV','Refletir dano','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54374642,'Apresentação da I.A.','Enquanto você controlar um monstro "@Ignister" de Link-3 ou mais na Zona de Monstros Adicional, quando um monstro do oponente declarar um ataque: Invoque por Invocação-Especial do seu Deck Adicional qualquer número de monstros Ciberso que não sejam Link com 2300 de ATK, cujo ATK combinado seja igual ou menor que o ATK do monstro atacante e, depois, encerre a Fase de Batalha.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54387923,'SiSolfacorde Beautia',replace(replace('Escala de Pêndulo = 2\r\n[ Efeito de Pêndulo ]\r\nSeu oponente não pode ativar Cards de Magia/Armadilha ou efeitos de monstro quando um ou mais Monstros Pêndulo "Solfacorde" seus forem Invocados por Invocação-Pêndulo.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\n(Efeito Rápido): você pode escolher 1 Monstro de Efeito que seu oponente controla, ou, se você tiver uma Escala de Pêndulo par na sua Zona de Pêndulo, em vez disso, você pode escolher 1 Magia/Armadilha com a face para cima que seu oponente controla; neste turno, bana-o(a) quando ele(a) deixar o campo. \r\nVocê só pode usar este efeito de "SiSolfacorde Beautia" uma vez por turno. \r\nUma vez por turno, no começo da Etapa de Dano, se este card batalhar um monstro com um ATK igual ou maior que a menor Escala de Pêndulo na sua Zona de Pêndulo x 300: destrua esse monstro.','\r',char(13)),'\n',char(10)),'Banir quando ele deixar o campo','O efeito de "SiSolfacorde Beautia" está sendo aplicado.','Destrua 1 monstro do seu oponente','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54399598,'Flor Fugaz do Mago',replace(replace('Escolha 1 Magia/Armadilha com a face para cima que seu oponente controla, ou 1 Magia/Armadilha que você controla; destrua-a e, depois, se você escolheu um card que você controla, você pode aplicar 1 desses efeitos.\r\n● Coloque 1 monstro do seu Cemitério na sua Zona de Magias & Armadilhas como uma Magia Contínua com a face para cima.\r\n● Adicione 1 Magia de Equipamento ou Contínua do seu Cemitério à sua mão.	\r\nVocê só pode ativar 1 "Flor Fugaz do Mago" por turno.','\r',char(13)),'\n',char(10)),'Ativar','Colocar um monstro','Recuperar 1 Card de Magia','Não fazer nada','','','','','','','','','','','','');
INSERT INTO texts VALUES(54401832,'Metalmorfose Carmesita','1 monstro "Metalmorfose" + 2 monstros com 3000 ou menos de ATK','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54407825,'Evento Estremecedor','Se um ou mais cards forem enviados do Deck para o Cemitério: escolha 1 card no Cemitério de qualquer duelista; embaralhe-o no Deck e, além disso, nenhum duelista pode enviar cards do Deck para o Cemitério pelo resto deste turno.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54408264,'Batalha Magichave','Escolha 1 Monstro Normal, 1 monstro "Magichave" ou 1 "Maftea Magichave" no seu Cemitério; embaralhe-o no Deck e, depois, se você ativou este card em resposta à ativação de um card ou efeito do seu oponente, Monstros Normais e monstros "Magichave" que você controla (exceto Fichas) não são afetados por esse efeito de card do oponente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54415063,'Lady Harpia 3',replace(replace('(Este card deve ser sempre considerado como "Lady Harpia".)	\r\nUm monstro do oponente que batalhar este card não pode declarar um ataque durante os próximos 2 turnos do seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54423935,'Réplica Ataqueraptor','Escolha 1 monstro "Ataqueraptor" que você controla; Invoque por Invocação-Especial 1 monstro com o mesmo nome do seu Deck e, se isso acontecer, enquanto você controlar esse monstro Invocado por Invocação-Especial com a face para cima, monstros que seu oponente controla não podem escolher o monstro escolhido, como alvo de ataques e, além disso, seu oponente não pode escolher o monstro escolhido, como alvo de efeitos de card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54446813,'Dinolutador Ampelo Marcial',replace(replace('Durante o cálculo de dano, se outro monstro "Dinolutador" seu batalhar um monstro do oponente com ATK maior ou igual (Efeito Rápido): você pode enviar este card da sua mão ou do campo para o Cemitério; nessa batalha, seu monstro não pode ser destruído e o dano de batalha que você sofrer é diminuído pela metade. \r\nQuando um monstro do oponente declarar um ataque: você pode banir este card do seu Cemitério; adicione 1 monstro "Dinolutador" do seu Deck à sua mão, exceto "Dinolutador Ampelo Marcial". \r\nVocê só pode usar este efeito de "Dinolutador Ampelo Marcial" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54447022,'Carregar Alma',replace(replace('Escolha qualquer número de monstros no seu Cemitério; Invoque-os por Invocação-Especial e, se isso acontecer, você perde 1000 PV para cada monstro Invocado por Invocação-Especial por este efeito. \r\nVocê não pode conduzir sua Fase de Batalha no turno em que ativar este card. \r\nVocê só pode ativar 1 "Carregar Alma" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54451023,'Cadeia Alimentar da Planta',replace(replace('Escolha 1 monstro do Tipo Planta que você controla; equipe este card ao alvo. \r\nEle ganha 500 de ATK. \r\nSe este card for destruído por um efeito de card enquanto estiver equipado: você pode escolher 1 monstro do Tipo Planta no seu Cemitério; Invoque o alvo por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54455435,'Winda, Sacerdotisa de Gusto','Quando este card for destruído em batalha com um monstro atacante do oponente e enviado para o Cemitério: Você pode Invocar por Invocação-Especial 1 monstro "Gusto" Regulador do seu Deck.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54455664,'Brandistock Dragunidade','Enquanto este card estiver equipado a um monstro, esse monstro pode realizar um segundo ataque durante cada Fase de Batalha.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54458867,'Compra Falsa',replace(replace('Escolha 1 monstro "Foguette" que você controla; destrua-o e, se isso acontecer, compre 2 cards. \r\nVocê só pode ativar 1 "Compra Falsa" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54475145,'Coração dos Olhos Azuis',replace(replace('(Este card deve ser sempre considerado como um card "Milênio".)	\r\nO controle deste card não pode ser trocado. \r\nVocê pode descartar este card; adicione 1 "Ankh do Milênio" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Coração dos Olhos Azuis" uma vez por turno. \r\nSe este card estiver no seu Cemitério e você já ativou com sucesso "Ankh do Milênio" neste Duelo e seu oponente Invocar por Invocação-Normal ou Especial um ou mais monstros que forem de Nível 8 ou mais, ou que tenham 3000 ou mais de ATK: você pode enviar esse monstro para o Cemitério e, se isso acontecer, Invoque este card por Invocação-Especial. \r\nVocê só pode usar este efeito de "Coração dos Olhos Azuis" uma vez por Duelo.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54484652,'Soldado do Lustro Negro - Super Soldado',replace(replace('Você pode Invocar este card por Invocação-Ritual com "Ritual do Super Soldado". \r\nSe este card destruir um monstro do oponente em batalha e enviá-lo para o Cemitério: cause dano ao seu oponente igual ao ATK do monstro destruído no Cemitério. \r\nSe este card for destruído em batalha e enviado para o Cemitério, ou se este card em sua posse for destruído por um efeito de card do seu oponente e enviado para o seu Cemitério: você pode Invocar por Invocação-Especial 1 monstro "Gaia, o Cavaleiro Impetuoso" (ou "Gaia, o Cavaleiro do Vento Negro") da sua mão, Deck ou Cemitério. \r\nVocê só pode Invocar um ou mais "Soldado do Lustro Negro - Super Soldado" por Invocação-Especial uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54485355,'Cavaleiro da Sublimação',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode equipar 1 monstro Guerreiro de FOGO ou 1 monstro Gêmeos da sua mão ou do Deck a este card como uma Magia de Equipamento que concede 500 de ATK a este card. \r\nSe este card sob o controle do seu dono for destruído por um card do oponente enquanto estiver equipado com um ou mais monstros Gêmeos: você pode Invocar por Invocação-Especial tantos desses monstros Gêmeos do seu Cemitério quanto possível, como Monstros de Efeito que ganham seus próprios efeitos. \r\nVocê só pode usar cada efeito de "Cavaleiro da Sublimação" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54490275,'Yuki-onna Fantardil',replace(replace('Não pode ser Invocado por Invocação-Normal a não ser que você controle um monstro "Fantardil". \r\nUma vez por turno: você pode colocar este card com a face para baixo em Posição de Defesa. \r\nQuando este card for destruído em batalha e enviado para o Cemitério: você pode colocar o monstro que o destruiu com a face para baixo em Posição de Defesa e, se isso acontecer, ele não pode mudar sua posição de batalha.','\r',char(13)),'\n',char(10)),'Mudar para Posição de Defesa com a face para baixo','Mudar para Posição de Defesa com a face para baixo','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54493213,'Hélios - O Sol Primordial','O ATK/DEF deste card se tornam o número de monstros banidos x 100.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54497620,'Condutor de Dispositivos','(Efeito Rápido): você pode enviar este card da sua mão para o Cemitério e, depois, escolha qualquer número de monstros "Morfotrônico(a)" que você controla; mude a posição de batalha desses alvos.','Mudar a posição de batalha','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54498517,'Spright Gigantesco',replace(replace('2 monstros de Nível 2	\r\nPara a Invocação-Xyz deste card, você pode considerar monstros de Link-2 que você controla como monstros de Nível 2 para matéria. \r\nO ATK original deste card que tenha um Monstro de Fusão, Sincro, Xyz ou Link como matéria é dobrado. \r\nDurante sua Fase Principal: você pode ativar este efeito; desassocie 1 matéria de um monstro que você controla e, se isso acontecer, Invoque por Invocação-Especial 1 monstro de Nível 2 do seu Deck e, além disso, nenhum duelista pode Invocar por Invocação-Especial pelo resto deste turno, exceto monstros de Nível/Classe/Link 2. \r\nVocê só pode usar este efeito de "Spright Gigantesco" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54507222,'Lombriga das Galáxias','Quando este card for Invocado por Invocação-Normal enquanto você não controlar nenhum outro monstro: você pode Invocar por Invocação-Especial 1 Monstro de Efeito "Galáxia" de Nível 3 ou menos do seu Deck, mas negue seus efeitos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54512827,'Lanterna Fantardil',replace(replace('Não pode ser Invocado por Invocação-Normal, a não ser que você controle um monstro "Fantardil". \r\nUma vez por turno: você pode colocar este card com a face para baixo em Posição de Defesa. \r\nQuando um monstro do oponente declarar um ataque direto ou quando um monstro "Fantardil" que você controla for escolhido como alvo de um ataque: você pode negar o ataque e, se isso acontecer, Invoque este card por Invocação-Especial da sua mão com a face para baixo em Posição de Defesa.','\r',char(13)),'\n',char(10)),'Mudar para a posição com a face para baixo','Negar o ataque e Invocar por Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54514594,'Martelador Vulcânico',replace(replace('Uma vez por turno, durante sua Fase Principal: você pode causar dano ao seu oponente igual ao número de monstros "Vulcânico(a)" no seu Cemitério x 200. \r\nEste card não pode atacar no turno em que ativar este efeito.','\r',char(13)),'\n',char(10)),'Causar dano ao seu oponente','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54520292,'Geleira de Koa''ki Meiru',replace(replace('Durante cada uma das suas Fases Finais, destrua este card a não ser que você envie 1 "Núcleo de Ferro de Koa''ki Meiru" da sua mão para o Cemitério ou revele 1 Card de Magia Contínua na sua mão. \r\nVocê pode enviar 1 card da sua mão ao Cemitério para destruir 1 monstro Invocado por Invocação-Especial no campo.','\r',char(13)),'\n',char(10)),'Escolha 1 "Núcleo de Ferro de Koa''ki Meiru" para enviar para o Cemitério','Revele 1 Card de Magia Contínua para o seu oponente','Destruir "Geleira de Koa''ki Meiru"','Destruir','','','','','','','','','','','','');
INSERT INTO texts VALUES(54525057,'Crusadia Draco',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) em Posição de Defesa em uma zona sua para a qual um Monstro Link apontar. \r\nVocê só pode Invocar "Crusadia Draco" por Invocação-Especial uma vez por turno desta forma. \r\nSe este card for Invocado por Invocação-Normal ou Especial em uma zona para a qual um Monstro Link apontar: você pode escolher 1 card "Crusadia" no seu Cemitério, exceto "Crusadia Draco"; adicione-o à sua mão. \r\nVocê só pode usar este efeito de "Crusadia Draco" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54527349,'Revolta do Senhor Obscuro',replace(replace('Envie 1 monstro "Senhor(a) Obscuro(a)" da sua mão ou do campo com a face para cima para o Cemitério; Invoque por Invocação-Fusão 1 Monstro de Fusão de TREVAS do seu Deck Adicional, usando monstros da sua mão ou do campo como Matéria de Fusão e, depois, você pode ganhar PV igual ao ATK original do monstro enviado para o Cemitério para ativar este card. \r\nVocê só pode ativar 1 "Revolta do Senhor Obscuro" por turno.','\r',char(13)),'\n',char(10)),'Ganhar PV?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54529134,'Transcendência Salamagrande',replace(replace('Escolha 1 Monstro Link "Salamagrande" que você controla; Invoque por Invocação-Especial 1 Monstro Link "Salamagrande" com o mesmo nome do seu Deck Adicional, usando esse monstro que você controla como toda a matéria. \r\n(Isso é considerado uma Invocação-Link.) \r\nVocê só pode ativar 1 "Transcendência Salamagrande" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54537489,'Mare Mare',replace(replace('Não pode ser Invocado por Invocação-Especial, exceto pelo efeito de um monstro Wyrm. \r\nDurante sua Fase Principal: você pode reduzir o Nível deste card em 1 e, se isso acontecer, Invoque por Invocação-Especial 1 "Ficha de Mini Mare Mare" (Wyrm/ÁGUA/Nível 1/ATK 300/DEF 200). \r\nVocê só pode usar este efeito de "Mare Mare" até três vezes por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54537490,'Ficha de Mini Mare Mare','Invocado por Especial com o efeito "Mare Mare".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54539105,'Ritual do Leão-de-Guerra',replace(replace('Este card é usado para a Invocação-Ritual de "Super Leão-de-Guerra". \r\nVocê também deve oferecer como Tributo monstros da sua mão ou do campo cuja soma dos Níveis seja 7 ou mais.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54541900,'Guerreiro Karbonala','"Guerreiro M nº 1" + "Guerreiro M nº 2"','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54550967,'Anjobruxa Mementotlan',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 monstro "Memento" do seu Deck à sua mão, exceto "Anjobruxa Mementotlan". \r\nVocê pode escolher 1 monstro "Memento" de Nível 2 ou menos no seu Cemitério; destrua 1 monstro "Memento" que você controla e, se isso acontecer, Invoque o monstro alvo por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Anjobruxa Mementotlan" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54562327,'Aposte sua Alma!',replace(replace('Revele 1 monstro na sua mão; Invoque por Invocação-Especial 1 monstro "Alma Aniquiladora" com o mesmo Atributo, mas um nome diferente, do seu Deck, mas devolva-o para a mão durante a Fase Final. \r\nVocê só pode ativar 1 "Aposte sua Alma!" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54563536,'Reservingador Autômato',replace(replace('(Efeito Rápido): você pode enviar este card da sua mão ou do campo para o Cemitério e, depois, escolha 1 monstro "Autômata(o)" que você controla; ele ganha 1200 de ATK até o final deste turno. \r\nQuando um monstro "Autômata(o)" seu destruir um monstro do oponente em batalha, enquanto este card estiver no seu Cemitério: você pode adicionar este card à sua mão. \r\nVocê só pode usar cada efeito de "Reservingador Autômato" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54564198,'Monstro Renascido',replace(replace('Se um ou mais monstros foram destruídos em batalha neste turno: envie para o Cemitério 1 "Reviver Monstro" da sua mão ou do Deck e, depois, escolha 1 monstro em qualquer Cemitério; Invoque esse monstro por Invocação-Especial no seu campo. \r\n(Isso é considerado uma Invocação-Especial pelo efeito de "Reviver Monstro".)','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54569495,'Marincesa Cauda de Coroa',replace(replace('Durante o cálculo de dano, se um monstro batalhar outro monstro (Efeito Rápido): você pode enviar 1 outro monstro "Marincesa" da sua mão para o Cemitério; Invoque este card por Invocação-Especial da sua mão e, se isso acontecer, o dano que você sofrer dessa batalha é diminuído pela metade. \r\nNo começo da Etapa de Dano, se um monstro do oponente atacar: você pode banir este card do seu Cemitério; neste turno, você não sofre dano de batalha que seja menor ou igual que a soma dos Valores Link dos Monstros Link "Marincesa" no seu Cemitério x 1000. \r\nVocê só pode usar cada efeito de "Marincesa Cauda de Coroa" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54573517,'T.G. Tudo Limpo',replace(replace('Todos os monstros "T.G." no campo se tornam monstros Máquina. \r\nDurante sua Fase Principal, você pode Invocar por Invocação-Normal 1 monstro "T.G.", em adição à sua Invocação-Normal/Baixar (padrão). \r\n(Você só pode se aproveitar deste efeito uma vez por turno.) \r\nDurante sua Fase Principal: você pode destruir 1 monstro "T.G." na sua mão ou no campo e, se isso acontecer, adicione 1 monstro "T.G." com um nome diferente do seu Deck ou Cemitério à sua mão. \r\nVocê só pode usar este efeito de "T.G. Tudo Limpo" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar pelo efeito de "T.G. Tudo Limpo"','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54577949,'Testemunha dos Antigos',replace(replace('Se você tiver um Monstro Sincro no seu campo ou Cemitério: você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe este card for Invocado por Invocação-Especial: você pode colocar até 3 Monstros Sincro com nomes diferentes do seu Deck Adicional e/ou Cemitério na sua Zona de Magias & Armadilhas, como Magias Contínuas com a face para cima e Invoque por Invocação-Especial 1 "Ficha de Arca" (Máquina/LUZ/ATK 0/DEF 0) com um Nível igual ao número colocado e, além disso, pelo resto deste turno, você não pode Invocar por Invocação-Especial do Deck Adicional, exceto Monstros Sincro. \r\nVocê só pode usar cada efeito de "Testemunha dos Antigos" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Colocar um monstro','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54577950,'Ficha de Arc','Invocado por Invocação-Especial pelo efeito de "Testeminho do Ancião".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54577951,'Testemunha dos Antigos',replace(replace('Se você tiver um Monstro Sincro no seu campo ou Cemitério: você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe este card for Invocado por Invocação-Especial: você pode colocar até 3 Monstros Sincro com nomes diferentes do seu Deck Adicional e/ou Cemitério na sua Zona de Magias & Armadilhas, como Magias Contínuas com a face para cima e Invoque por Invocação-Especial 1 "Ficha de Arca" (Máquina/LUZ/ATK 0/DEF 0) com um Nível igual ao número colocado e, além disso, pelo resto deste turno, você não pode Invocar por Invocação-Especial do Deck Adicional, exceto Monstros Sincro. \r\nVocê só pode usar cada efeito de "Testemunha dos Antigos" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Colocar um monstro','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54578613,'Legionário Dragunidade',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode escolher 1 monstro Dragão "Dragunidade" de Nível 3 ou menos no seu Cemitério; equipe o alvo a este card. \r\nVocê pode enviar 1 card "Dragunidade" da sua Zona de Magias & Armadilhas para o Cemitério e, depois, escolher 1 monstro com a face para cima que seu oponente controla; destrua o alvo.','\r',char(13)),'\n',char(10)),'Equipar','Destrua 1 monstro com a face para cima que seu oponente controla','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54579801,'Gyojin da Maré Alta','Um guerreiro meio peixe, muito ágil e conhecido pelos seus ataques implacáveis.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54582424,'Borbolespiã Imperadora Azul',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nQuando você Invocar um monstro Guerreiro por Invocação-Normal: você pode Invocar este card por Invocação-Especial da sua mão. \r\nNão pode ser usado como Matéria Sincro.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54591086,'Canhão Vírus','Ofereça como Tributo qualquer número de monstros, exceto Fichas; seu oponente envia um número igual de Magias do Deck dele para o Cemitério (ou todas as Magias dele, se forem menos que o número de Tributos).','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54594017,'Asanegra - Sharnga, a Lua Minguante',replace(replace('Se um monstro com 2000 ou mais de ATK estiver no campo, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Asanegra - Sharnga, a Lua Minguante" por Invocação-Especial uma vez por turno desta forma. \r\nSe você controlar um Monstro Sincro "Asanegra" (Efeito Rápido): você pode banir este card do seu Cemitério e, depois, escolha 1 card com a face para cima que seu oponente controla; destrua-o. \r\nVocê só pode usar este efeito de "Asanegra - Sharnga, a Lua Minguante" uma vez por Duelo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54603525,'Dragão Sincro de Asas Transparentes, os Quatro Dragões Celestiais',replace(replace('1 Regulador + 1+ não-Reguladores	\r\n(Este card deve ser sempre considerado como um card "Velocidaroide".)	\r\nSe este card for Invocado por Invocação-Especial: você pode destruir 1 Monstro de Efeito que seu oponente controla e, se isso acontecer, este card ganha ATK igual ao ATK original desse monstro. \r\nQuando seu oponente ativar um card ou efeito (Efeito Rápido): você pode Invocar por Invocação-Especial 1 Regulador de VENTO de Nível 4 ou menos da sua mão ou do Cemitério (mas negue seus efeitos) e, depois, imediatamente depois que este efeito resolver, você pode Invocar por Invocação-Sincro 1 Monstro Sincro de VENTO. \r\nVocê só pode usar cada efeito de "Dragão Sincro de Asas Transparentes, os Quatro Dragões Celestiais" uma vez por turno.','\r',char(13)),'\n',char(10)),'Efeito de destruição','Invocação Especial','Invocação Sincro?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54603526,'Dragão Sincro de Asas Transparentes, os Quatro Dragões Celestiais',replace(replace('1 Regulador + 1+ não-Reguladores	\r\n(Este card deve ser sempre considerado como um card "Velocidaroide".)	\r\nSe este card for Invocado por Invocação-Especial: você pode destruir 1 Monstro de Efeito que seu oponente controla e, se isso acontecer, este card ganha ATK igual ao ATK original desse monstro. \r\nQuando seu oponente ativar um card ou efeito (Efeito Rápido): você pode Invocar por Invocação-Especial 1 Regulador de VENTO de Nível 4 ou menos da sua mão ou do Cemitério (mas negue seus efeitos) e, depois, imediatamente depois que este efeito resolver, você pode Invocar por Invocação-Sincro 1 Monstro Sincro de VENTO. \r\nVocê só pode usar cada efeito de "Dragão Sincro de Asas Transparentes, os Quatro Dragões Celestiais" uma vez por turno.','\r',char(13)),'\n',char(10)),'Efeito de destruição','Invocação Especial','Invocação Sincro?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54611591,'Hallo, o Espírito das Travessuras',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode ativar este efeito; se você ainda controlar este card com a face para cima, seu oponente seleciona 1 desses efeitos para que você aplique.\r\n● Este card ganha 800 de ATK para cada monstro Demônio atualmente no seu Cemitério.\r\n● Cause 500 de dano ao seu oponente para cada monstro Demônio no seu Cemitério.	\r\nSe este card for destruído em batalha ou por um efeito de card: você pode enviar 1 monstro que seu oponente controla para o Cemitério.\r\nVocê só pode usar cada efeito de "Hallo, o Espírito das Travessuras" uma vez por turno.','\r',char(13)),'\n',char(10)),'Aumentar ATK ou causar dano','Enviar o monstro do seu oponente para o Cemitério','Aumentar ATK','Causar dano','','','','','','','','','','','','');
INSERT INTO texts VALUES(54615781,'Espírito dos Ventos','Um espírito do vento que cria uma tempestade quando está de mau humor.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54620698,'Cavaleiro-Gema Turmalina','Ele canaliza energias místicas e as transforma em força de combate por meio da Turmalina. Muitos admiram essa forma de vida.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54622031,'Grande Mamute de Goldfine','"Cabelos de Cobras" + "Dragão Zumbi"','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54629413,'Pipa de Guerrilha',replace(replace('Se este card for enviado do campo para o Cemitério: cause 500 de dano ao seu oponente. \r\nVocê só pode usar este efeito de "Pipa de Guerrilha" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54631665,'ESPIRÃO do Resort',replace(replace('Seu oponente não pode escolher outros cards "ESPIRÃO" que você controla como alvo de efeitos de card. \r\nUma vez por turno: você pode adicionar 1 monstro "ESPIRÃO" do seu Deck à sua mão. \r\nUma vez por turno, durante sua Fase Final, embaralhe no Deck 1 monstro do seu Cemitério ou destrua este card.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Embaralhe 1 monstro do seu Cemitério no Deck','Destruir este card','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54631834,'Mundo Terminal',replace(replace('Ative apenas durante a Fase Principal 1. \r\nEnquanto este card estiver no campo, os dois duelistas pulam sua Fase Principal 2.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54635100,'Linkinho',replace(replace('2 monstros	\r\nVocê não pode Invocar este card por Invocação-Link a não ser que você tenha pelo menos 3 cards a mais que seu oponente no seu Deck Adicional.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54635862,'Salamangentil',replace(replace('Quando um monstro do oponente declarar um ataque: você pode Invocar este card por Invocação-Especial da sua mão. \r\nOs monstros do seu oponente não podem atacar nenhum monstro, exceto este.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54641720,'HERÓI do Destino – Dreadnought',replace(replace('2 monstros "HERÓI do Destino" de Nível 5 ou maior	\r\nDeve ser Invocado por Invocação-Fusão ou Especial (do seu Deck Adicional) oferecendo como Tributo 1 "HERÓI do Destino - Mestre do Horror". \r\nVocê só pode Invocar por Invocação-Especial "HERÓI do Destino - Mestre do Horror" uma vez por turno dessa forma, não importa qual método use.\r\nSe este card for Invocado por Invocação-Especial: você pode adicionar 2 monstro "HERÓI do Destino" e/ou cards que mencione o nome de um card "HERÓI do Destino" do seu Deck à sua mão.\r\nO ATK deste card se tornal o total original do ATK de todos os monstros "HERÓI do Destino" no seu campo e Cemitério.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54652250,'Inseto Devorador de Homens','VIRE: Escolha 1 monstro no campo; destrua-o.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54656181,'Coronel na Corda C','Quando este card for Invocado por Invocação-Normal: você pode Invocar por Invocação-Especial 2 monstros Guerreiro de Nível 4 ou menos com nomes diferentes da sua mão em Posição de Defesa.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54656950,'Ouriço Ancorafusado',replace(replace('Se você controlar "Guerreiro Sucata" ou um monstro que o mencione, exceto "Ouriço Ancorafusado", e este card estiver no seu Cemitério (Efeito Rápido): você pode Invocar este card por Invocação-Especial em Posição de Defesa e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto Monstros Sincro. \r\nVocê só pode usar este efeito de "Ouriço Ancorafusado" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54658815,'Renascimento Remoto','Escolha 1 monstro no Cemitério do seu oponente; Invoque-o por Invocação-Especial em uma Zona de Monstros Principal do oponente para a qual um Monstro Link seu apontar.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54670997,'Orgulho Dourado - Mais Sorte da Próxima Vez!',replace(replace('Quando este card for ativado: você pode adicionar 1 monstro "Orgulho Dourado" do seu Deck à sua mão e, se isso acontecer, perca PV igual ao seu ATK. \r\nSe um ou mais monstros "Orgulho Dourado" com a face para cima que você controla que foram Invocados por Invocação-Especial do Deck Adicional forem devolvidos para o Deck Adicional (exceto durante a Etapa de Dano): você pode comprar 1 card. \r\nVocê só pode usar este efeito de "Orgulho Dourado - Mais Sorte da Próxima Vez!" uma vez por turno. \r\nVocê só pode ativar 1 "Orgulho Dourado - Mais Sorte da Próxima Vez!" por turno.','\r',char(13)),'\n',char(10)),'','Adicionar à sua mão 1 monstro "Orgulho Dourado" do seu Deck?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54693926,'Governante Sombrio, Não Mais!',replace(replace('Até o final deste turno, negue os efeitos de monstros com a face para cima que seu oponente controla atualmente e, além disso, pelo resto deste turno depois que este card resolver, seu oponente não sofre dano. \r\nNenhum duelista pode ativar efeitos de monstro em resposta à ativação deste card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54693927,'Governante Sombrio, Não Mais!',replace(replace('Até o final deste turno, negue os efeitos de monstros com a face para cima que seu oponente controla atualmente e, além disso, pelo resto deste turno depois que este card resolver, seu oponente não sofre dano. \r\nNenhum duelista pode ativar efeitos de monstro em resposta à ativação deste card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54700519,'Ursártico Megatanus',replace(replace('Durante a Fase Principal (Efeito Rápido): você pode oferecer como Tributo 1 outro monstro de Nível 7 ou mais da sua mão; Invoque este card por Invocação-Especial da sua mão e, além disso, você não pode Invocar por Invocação-Especial pelo resto deste turno, exceto monstros com um Nível. \r\nSe este card for Invocado por Invocação-Especial enquanto você controlar outro monstro "Ursártico(a)": você pode escolher 1 monstro com a face para cima que seu oponente controla; coloque-o com a face para baixo em Posição de Defesa. \r\nVocê só pode usar cada efeito de "Ursártico Megatanus" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54701958,'Ligre Dançarina Luzlunar',replace(replace('"Leoa Dançarina Luzlunar" + 3 monstros "Luzlunar"	\r\nDeve ser Invocado por Invocação-Fusão com as Matérias de Fusão acima. \r\nNão é afetado por efeitos de card, exceto cards "Luzlunar". \r\nPode realizar um segundo ataque durante cada Fase de Batalha. \r\nUma vez por turno (Efeito Rápido): você pode enviar 1 monstro "Luzlunar" do seu Deck Adicional para o Cemitério; destrua todos os monstros Invocados por Invocação-Especial do seu oponente.','\r',char(13)),'\n',char(10)),'','','Destruir','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54702678,'Barbaroide, a Máquina de Guerra Definitiva',replace(replace('5 monstros "roide" do Tipo Máquina	\r\nEste card pode realizar um segundo ataque durante cada Fase de Batalha. \r\nEste card não pode atacar diretamente seu oponente. \r\nDepois do cálculo de dano, se este card atacou um monstro do oponente: negue os efeitos desse monstro (inclusive no Cemitério). \r\nSe este card destruir um monstro do oponente em batalha: cause 1000 de dano ao seu oponente.','\r',char(13)),'\n',char(10)),'Negar o efeito','Receba 1000 pontos de dano','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54704216,'Roda dos Pesadelos',replace(replace('Ative este card ao escolher 1 monstro que seu oponente controla; ele não pode atacar ou mudar sua posição de batalha. \r\nQuando ele deixar o campo, destrua este card. \r\nUma vez por turno, durante sua Fase de Apoio: cause 500 de dano ao seu oponente. \r\nEsse monstro deve estar no campo para ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54706054,'O Calibrador','Este card ganha ATK igual à soma das Classes de todos os Monstros Xyz com a face para cima que seu oponente controla x 300.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54719828,'Número 16: Mestre do Choque',replace(replace('3 monstros de Nível 4	\r\nUma vez por turno: você pode desassociar 1 Matéria Xyz deste card para declarar 1 tipo de card (Monstro, Magia ou Armadilha); esse tipo de card (se Magia ou Armadilha) não pode ser ativado, ou (se Monstro) não pode ativar seus efeitos até o final do próximo turno do seu oponente.','\r',char(13)),'\n',char(10)),'Restrição de ativação','Declare um tipo de card','"Número 16: Mestre do Choque": Declarar um Card de Monstro','"Número 16: Mestre do Choque": Declarar um Card de Magia','"Número 16: Mestre do Choque": Declarar um Card de Armadilha','','','','','','','','','','','');
INSERT INTO texts VALUES(54725177,'Dragão de Mudança de Fóton de Olhos das Galáxias',replace(replace('Você pode Invocar por Invocação-Especial este card (da sua mão) oferecendo como Tributo 2 monstros com a face para cima em qualquer campo com 2000 ou mais de ATK, incluindo um monstro que você controla. \r\nVocê só pode Invocar por Invocação-Especial por este efeito de "Dragão de Mudança de Fóton de Olhos das Galáxias" uma vez por turno.\r\nDurante a Fase Principal (Efeito Rápido): você pode banir este card; Invoque por Invocação-Especial 1 "Dragão de Fóton de Olhos das Galáxias" do seu Deck ou Cemitério, então você pode banir 1 monstro do oponente que foi Invocado por Invocação-Especial do Deck Adicional até a Fase Final. \r\nVocê só pode ativar este efeito de "Dragão de Mudança de Fóton de Olhos das Galáxias" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Invocação Especial','Banir o monstro?','Banir até a Fase Final','','','','','','','','','','','','');
INSERT INTO texts VALUES(54725178,'Dragão de Mudança de Fóton de Olhos das Galáxias',replace(replace('Você pode Invocar por Invocação-Especial este card (da sua mão) oferecendo como Tributo 2 monstros com a face para cima em qualquer campo com 2000 ou mais de ATK, incluindo um monstro que você controla. \r\nVocê só pode Invocar por Invocação-Especial por este efeito de "Dragão de Mudança de Fóton de Olhos das Galáxias" uma vez por turno.\r\nDurante a Fase Principal (Efeito Rápido): você pode banir este card; Invoque por Invocação-Especial 1 "Dragão de Fóton de Olhos das Galáxias" do seu Deck ou Cemitério, então você pode banir 1 monstro do oponente que foi Invocado por Invocação-Especial do Deck Adicional até a Fase Final. \r\nVocê só pode ativar este efeito de "Dragão de Mudança de Fóton de Olhos das Galáxias" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Invocação Especial','Banir o monstro?','Banir até a Fase Final','','','','','','','','','','','','');
INSERT INTO texts VALUES(54734082,'Indução Ímã',replace(replace('Se você controlar um monstro "Guerreiro Ímã" cujo Nível original seja 4 ou menos: Invoque por Invocação-Especial 1 monstro "Guerreiro Ímã" de Nível 4 ou menos do seu Deck com um nome diferente que o dos cards que você controla e, além disso, pelo resto deste turno depois que este card resolver, monstros "Guerreiro Ímã" que você controla não podem ser destruídos em batalha ou pelos efeitos de card do seu oponente. \r\nVocê só pode ativar 1 "Indução Ímã" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54747648,'Invocador da Tartaruga Verde','VIRE: Escolha 1 monstro que seu oponente controla; destrua-o.','Destruir um monstro','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54749427,'HERÓI do Destino - Defensor',replace(replace('Durante cada uma das Fases de Apoio do seu oponente: seu oponente compra 1 card. \r\nEste card deve estar com a face para cima em Posição de Defesa para que você possa ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Seu oponente compra','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54752875,'Dragão do Trovão de Duas Cabeças','"Dragão do Trovão" + "Dragão do Trovão"','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54757758,'Lamadragão do Pântano',replace(replace('2 monstros com o mesmo Atributo, mas Tipos diferentes	\r\nSeu oponente não pode escolher este card, ou monstros no campo com o mesmo Atributo que o deste card, como alvo de efeitos de card. \r\nUma vez por turno (Efeito Rápido): você pode declarar 1 Atributo; até o final deste turno, este card se torna desse Atributo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54762426,'Mapa do Tesouro',replace(replace('Você só pode ativar este card em resposta à ativação de um efeito que devolveria este card do campo à mão. \r\nCompre 2 cards do seu Deck e descarte 1 card da sua mão.','\r',char(13)),'\n',char(10)),'Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54766667,'Efígie de Luz','Se você Invocar por Invocação-Tributo um Monstro Normal de LUZ, você pode considerar este 1 monstro como 2 Tributos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54772065,'Vespabatalha - Arcoduplo, o Atacante',replace(replace('Durante sua Fase Principal: você pode Invocar este card por Invocação-Especial da sua mão e, além disso, você não pode Invocar por Invocação-Especial monstros do Deck Adicional pelo resto deste turno, exceto monstros Inseto. \r\nVocê só pode usar este efeito de "Vespabatalha - Arcoduplo, o Atacante" uma vez por turno. \r\nEste card pode realizar um segundo ataque durante cada Fase de Batalha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54773234,'Escritura Proibida','Se um monstro batalhar um monstro do oponente, durante o cálculo de dano: negue os efeitos de todos os outros cards no campo até o final da Etapa de Dano e, além disso, o cálculo de dano desta batalha usa o ATK e DEF originais de cada monstro.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54807656,'Uivo da Alma Desacorrentada',replace(replace('Se você Invocar um Monstro Link "Desacorrentado(a)" por Invocação-Link: você pode escolher 1 card no campo; destrua-o. \r\nSe este card Baixado for destruído por um efeito de card: você pode Invocar por Invocação-Especial 1 monstro "Desacorrentado(a)" do seu Deck. \r\nVocê só pode usar cada efeito de "Uivo da Alma Desacorrentada" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54813225,'Caça-Pato',replace(replace('Se este card estiver em sua mão ou Cemitério: você pode oferecer como Tributo Fichas cujos Níveis totalizem 3 ou mais; Invoque este card por Invocação-Especial. \r\nVocê só pode usar o efeito de "Caça-Pato" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54828837,'Fogo Celeste Cerúleo',replace(replace('Para Invocar "Hamon, o Senhor do Trovão Impactante" por Invocação-Especial usando seus próprios métodos, você também pode usar Magias com a face para baixo que você controla. \r\nUma vez por turno, enquanto você controlar um "Hamon, o Senhor do Trovão Impactante" em Posição de Ataque, você pode negar qualquer efeito de Magia/Armadilha ativado pelo seu oponente e, depois, coloque 1 "Hamon, o Senhor do Trovão Impactante" que você controla em Posição de Defesa. \r\nSe um "Uria, o Senhor das Chamas Cortantes", "Hamon, o Senhor do Trovão Impactante" ou "Raviel, o Senhor dos Fantasmas" com a face para cima que você controla deixar o campo: você não sofre dano neste turno.','\r',char(13)),'\n',char(10)),'Usar o efeito de "Fogo Celeste Cerúleo"?','Todo o dano se torna 0','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54842941,'Eneanave - Atori.MAR',replace(replace('Escala de Pêndulo = 0\r\n[ Efeito de Pêndulo ]\r\nSempre que um ou mais monstros forem virados com a face para cima, coloque 1 Marcador de E.N. neste card. \r\nNo final da Fase de Batalha, se você tiver um card "Eneanave" na sua outra Zona de Pêndulo: você pode escolher 1 monstro que seu oponente controla com ATK menor que o deste card; destrua-o.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nVIRE: Coloque todos os monstros do seu oponente com a face para baixo em Posição de Defesa. \r\nOs monstros que foram, não podem mudar suas posições de batalha.\r\nDurante o seu turno, quando seu oponente ativar um card ou efeito no campo (Efeito Rápido): você pode colocar este card que estiver com a face para baixo, com a face para cima em Posição de Defesa; negue a ativação e, se isso acontecer, destrua esse card. \r\nVocê pode revelar este card na sua mão; Invoque por Invocação-Especial 1 monstro da sua mão com a face para baixo em Posição de Defesa. \r\nVocê não pode Invocar por Invocação-Especial no turno em que ativar este efeito, exceto com a face para baixo em Posição de Defesa.','\r',char(13)),'\n',char(10)),'Destruir','Invocação Especial','Negar','Baixar','','','','','','','','','','','','');
INSERT INTO texts VALUES(54844990,'Perseguidor de Crâneos','Elll vaaa agarrrarrr vocé con as garrrasss e deposss con o ferrrão!','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54851325,'Encômio do Reino',replace(replace('Escolha 1 monstro que você controla e 1 Monstro de Efeito que seu oponente controla; destrua esse monstro que você controla e, se isso acontecer, negue os efeitos desse monstro do oponente até o final deste turno e, depois, se "Visas Starfrost" estiver no campo, você pode destruir esse monstro alvo. \r\nDurante sua Fase Principal, se um Card de Monstro "Veda" estiver no campo: você pode banir este card do seu Cemitério; destrua 1 monstro que você controla. \r\nVocê só pode usar cada efeito de "Encômio do Reino" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Destruir o monstro alvo?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54860010,'Príncipe Lombriga',replace(replace('Se este card destruir um monstro do oponente em batalha, você pode adicionar 1 monstro "Lombriga" do Tipo Réptil do seu Deck à sua mão. \r\nDestrua este card durante a Fase Final se você não controlar um monstro "Lombriga" do Tipo Réptil que não seja este card.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Autodestruir-se','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54862960,'Ni-Ni, o Espelho Mikanko',replace(replace('Se este card não estiver equipado com um Card de Equipamento, você não sofre dano das batalhas envolvendo este card. \r\nSe este card estiver equipado com um Card de Equipamento, ele não pode ser destruído em batalha e seu oponente sofre qualquer dano de batalha que você teria sofrido das batalhas envolvendo este card. \r\nDurante o turno do seu oponente, enquanto este card estiver equipado com um Card de Equipamento (Efeito Rápido): você pode escolher 1 monstro com a face para cima que seu oponente controla; tome o controle dele até a Fase Final. \r\nVocê só pode usar este efeito de "Ni-Ni, o Espelho Mikanko" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54878498,'Kelbek','Se este card for atacado por um monstro, depois do cálculo de dano: devolva esse monstro para a mão.','Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54878729,'Feiticeira das Crônicas',replace(replace('Você pode ativar 1 desses efeitos de acordo com os Atributos no seu Cemitério;\r\n● LUZ: Envie 1 "Dragão Branco de Olhos Azuis" ou 1 card que o mencione do seu Deck para o Cemitério, exceto "Feiticeira das Crônicas".\r\n● TREVAS: Envie 1 "Mago Negro" ou 1 card que o mencione do seu Deck para o Cemitério, exceto "Feiticeira das Crônicas".	\r\nVocê só pode usar este efeito de "Feiticeira das Crônicas" uma vez por turno.','\r',char(13)),'\n',char(10)),'','LUZ','TREVAS','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54880296,'Adoração do Vento Yosenju',replace(replace('Se você controlar 3 ou mais Cards de Monstro "Yosenju" com nomes diferentes: devolva para a mão tantos Cards de Monstro "Yosenju" que você controla quanto possível e, depois, você pode comprar até ter 5 cards na sua mão. \r\nVocê só pode ativar 1 "Adoração do Vento Yosenju" por turno.','\r',char(13)),'\n',char(10)),'Comprar 1 card?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54895237,'Pintor do Clima Sol',replace(replace('Se este card estiver no seu Cemitério: você pode enviar 1 Magia/Armadilha Contínua com a face para cima que você controla para o Cemitério; Invoque este card por Invocação-Especial em Posição de Defesa e, se isso acontecer, coloque 1 Magia/Armadilha "do Clima" da sua mão com a face para cima na sua Zona de Magias & Armadilhas. \r\nVocê só pode usar este efeito de "Pintor do Clima Sol" uma vez por turno. \r\nUma vez por turno, durante a Fase de Apoio do turno seguinte ao qual este card foi banido do campo para ativar um efeito de card "do Clima": você pode Invocar este card banido por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Invocar este card por Invocação Especial do seu Cemitério','Invoque este card banido por Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54903668,'Golpe Secreto de Yosenju','Quando um Card de Magia/Armadilha ou um efeito de monstro for ativado enquanto você controlar pelo menos 1 card "Yosenju" e todos os monstros com a face para cima que você controlar forem monstros "Yosenju": negue a ativação e, se isso acontecer, destrua esse card.','Negar a ativação e destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54912977,'Lâmpada Antiga',replace(replace('Durante sua Fase Principal: você pode Invocar por Invocação-Especial "La Jinn, o Gênio Místico da Lâmpada" da sua mão. \r\nEste card deve estar com a face para cima no campo para que você possa ativar e resolver este efeito. \r\nAntes do cálculo de dano, se este card estiver sendo atacado por um monstro do oponente e estava com a face para baixo no começo da Etapa de Dano: você pode escolher 1 monstro que seu oponente controla, exceto o monstro atacante; em vez disso, o monstro atacante ataca o monstro alvo e você prossegue para o cálculo de dano.','\r',char(13)),'\n',char(10)),'Alterar o alvo do ataque','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54913680,'Seis Pergaminhos do Samurai',replace(replace('Ofereça como Tributo 2 monstros "Seis Samurai" com a face para cima. \r\nInvoque por Invocação-Especial 1 "Grande Shogun Shien" do seu Deck.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54919528,'"Caçador" K9-ØØ',replace(replace('2 monstros de Nível 5	\r\nNão pode ser destruído em batalha ou pelos efeitos de card do seu oponente no turno em que for Invocado por Invocação-Especial. \r\nSempre que seu oponente ativar um efeito de monstro, este card ganha 500 de ATK quando esse efeito resolver. \r\nUma vez por turno, durante a Fase de Apoio: você pode desassociar 1 matéria deste card e, depois, escolha 1 card no campo; bana-o.','\r',char(13)),'\n',char(10)),'','Banir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54927180,'Fukubiki',replace(replace('Cada duelista embaralha seu Deck e escava o card do topo do seu Deck. \r\nAdicione o card escavado com o maior ATK à mão desse duelista e, além disso, envie o card com o menor ATK para o Cemitério desse duelista (Magias/Armadilhas e monstros com ATK ? são considerados como 0). \r\nEm caso de empate, coloque esses cards no fundo dos Decks.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54936498,'Dragão Influência','Uma vez por turno: Você pode escolher 1 monstro com a face para cima que você controla; ele se torna do Tipo Dragão até a Fase Final.','Alterar Tipo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54936778,'Pacto Obscuro com a Dimensão Diferente',replace(replace('Uma vez por turno, durante sua Fase de Apoio: sofra 1000 de dano. \r\nVocê só pode usar cada um dos seguintes efeitos de "Pacto Obscuro com a Dimensão Diferente" uma vez por turno. \r\nVocê pode embaralhar 2 cards "Pacto Obscuro" do seu Cemitério no Deck e, depois, escolha 1 card no campo ou Cemitério do seu oponente; bana-o. \r\nSe este card for destruído: você pode ganhar 500 PV e, depois, se ele foi destruído por um efeito de card do oponente, ganhe outros 500 PV.','\r',char(13)),'\n',char(10)),'Efeito de banimento','Efeito de dano','Ganhar PV','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54941203,'Mago Regulador',replace(replace('Se você tiver 2 cards "Mago" nas suas Zonas de Pêndulo, enquanto este card estiver na sua mão ou no Cemitério: você pode Invocar este card por Invocação-Especial, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar este efeito de "Mago Regulador" uma vez por turno. \r\nSe este card for Invocado por Invocação-Normal ou Especial: seu oponente ganha 400 PV e, depois, você sofre 400 de dano.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54959865,'Beija-flor do Ar Neoespacial','Uma vez por turno: você pode ganhar 500 PV para cada card na mão do seu oponente.','Ganhar PV','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54965929,'Besta Mítica Medusa',replace(replace('Escala de Pêndulo = 4\r\n[ Efeito de Pêndulo ]\r\nSe você não tiver nenhum card na sua outra Zona de Pêndulo: você pode escolher 1 monstro no seu Cemitério sobre o qual você possa colocar um Marcador de Magia; destrua este card e, se isso acontecer, Invoque esse monstro por Invocação-Especial e, se isso acontecer, coloque 1 Marcador de Magia sobre ele. \r\nVocê só pode usar este efeito de "Besta Mítica Medusa" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSempre que um Card de Magia for ativado, coloque 1 Marcador de Magia neste card quando essa Magia resolver. \r\nUma vez por turno, durante a Fase de Batalha (Efeito Rápido): você pode remover 2 Marcadores de Magia do seu campo e, depois, escolher 1 monstro com a face para cima no campo; o ATK/DEF dele se tornam metade do seu ATK/DEF atual até o final deste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54974237,'Vírus Epidêmico Erradicador','Ofereça como Tributo 1 monstro de TREVAS com 2500 ou mais de ATK e declare 1 tipo de card (Magia ou Armadilha); olhe a mão do seu oponente, todas as Magias/Armadilhas que ele controla e todos os cards que ele comprar até o final do 3º turno dele depois que este card resolver e destrua todos os cards do tipo declarado.','Card de Magia','Card de Armadilha','Declare um tipo de card','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54976796,'Limite de Nível - Área A','Coloque em Posição de Ataque todos os monstros de Nível 3 ou menos com a face para cima.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(54977057,'Cards dos Céus',replace(replace('Bana 1 monstro Fada de LUZ da sua mão e, se isso acontecer, compre 2 cards. \r\nVocê não pode Invocar por Invocação-Especial ou conduzir sua Fase de Batalha no turno em que ativar este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55001420,'Arqueiro Arcano do Bosque',replace(replace('Este card não pode ser atacado se existir um monstro do Tipo Planta no seu Campo. \r\nOfereça 1 monstro do Tipo Planta no seu Campo, como Tributo, para destruír um Card de Magia ou Armadilha no Campo.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55008284,'A Liga da Nomenclatura Uniforme',replace(replace('Selecione 1 Monstro Normal de Nível 2 ou menos com a face para cima que você controla para ativar este card. \r\nInvoque por Invocação-Especial tantos cards quanto possível do seu Deck com o mesmo nome do monstro selecionado.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55010259,'Dispositivo de Ouro',replace(replace('Quando este card for Invocado por Invocação-Normal ou Especial: você pode Invocar por Invocação-Especial 1 monstro Máquina de Nível 4 da sua mão. \r\nSe este card for destruído em batalha ou por um efeito de card: você pode Invocar por Invocação-Especial 1 monstro "Dispositivo" de Nível 4 do seu Deck, exceto "Dispositivo de Ouro". \r\nVocê só pode usar 1 efeito de "Dispositivo de Ouro" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55013285,'Dragão de Infantaria','Se este card for destruído em batalha e enviado para o Cemitério: Invoque por Invocação-Especial 1 "Dragão de Infantaria" do seu Deck.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55014050,'Menina Aquática','Uma moça adorável que pode disparar projéteis de água que se transformam em lanças de gelo antes de atingir o oponente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55031170,'Lanterna K9-66b',replace(replace('Se seu oponente tiver 2 ou mais cards na mão dele, você pode Invocar este card por Invocação-Normal sem oferecer Tributo. \r\nVocê só pode usar cada um dos seguintes efeitos de "Lanterna K9-66b" uma vez por turno. \r\nSe este card estiver na sua mão: você pode escolher 1 monstro "K9" não-Piro de Nível 5 no seu Cemitério; Invoque por Invocação-Especial tanto ele quanto este card, mas eles não podem ser usados como matéria para a Invocação-Xyz de um monstro de LUZ. \r\nDurante sua Fase Principal: você pode adicionar 1 Magia/Armadilha "K9" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Invocação Normal sem Tributo','Invocação Especial','Adicionar à mão','Invocado por Invocação Especial pelo efeito de "Lanterna K9-66b"','','','','','','','','','','','','');
INSERT INTO texts VALUES(55034079,'Torre Link',replace(replace('Quando este card for ativado: coloque 4 marcadores neste card. \r\nSempre que você sofrer dano de batalha, coloque 1 marcador neste card. \r\nDurante sua Fase Principal 2: você pode remover 1 marcador deste card e, depois, escolha 1 monstro "Foguette" no seu Cemitério; Invoque-o por Invocação-Especial, mas seus efeitos são negados e, além disso, ele é banido quando deixar o campo. \r\nVocê não pode Invocar monstros por Invocação-Especial do seu Deck Adicional no turno em que ativar este efeito, exceto Monstros Link de TREVAS (mesmo que este card deixe o campo).','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55046718,'Componente Vylon',replace(replace('Só pode ser equipado a um monstro "Vylon". \r\nSe ele atacar um monstro em Posição de Defesa, cause Dano de Batalha perfurante ao seu oponente. \r\nSe este card com a face para cima no campo for enviado para o Cemitério: Você pode adicionar 1 Card de Magia "Vylon" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55049722,'Perseguição Força-S',replace(replace('Escolha cards com a face para cima que seu oponente controla, até o número de monstros "Força-S" que você controla com nomes diferentes; devolva-os para a mão. \r\nSe um monstro "Força-S" que você controla baniria um ou mais cards da sua mão para ativar seu efeito, em vez disso, você pode banir este card do seu Cemitério. \r\nVocê só pode usar cada efeito de "Perseguição Força-S" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55051920,'Núcleo Orcustrado',replace(replace('Uma vez por turno: você pode banir 1 monstro do seu campo ou Cemitério e, depois, escolher 1 card "Orcust" ou "Legado Mundial" que você controla, exceto "Núcleo Orcustrado"; nenhum duelista pode escolhê-lo como alvo de efeitos de card neste turno (mesmo que este card deixe o campo). \r\nSe um ou mais outros cards "Orcust" e/ou "Legado Mundial" que você controla seriam destruídos em batalha ou por um efeito de card, em vez disso, você pode enviar este card para o Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55063681,'Produtor de Poder',replace(replace('Uma vez por turno, você pode selecionar 1 monstro com a face para cima que você controla. \r\nEle ganha 400 de ATK enquanto você controlar este card com a face para cima. \r\n(Um monstro não pode ganhar mais do que 400 de ATK com o efeito deste card.)','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55063751,'Gameciel, o Kaiju Tartaruga Marinha',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) em Posição de Ataque no campo do seu oponente, ao oferecer como Tributo 1 monstro que ele controla. \r\nSe seu oponente controlar um monstro "Kaiju", você pode Invocar este card por Invocação-Especial (da sua mão) em Posição de Ataque. \r\nVocê só pode controlar 1 monstro "Kaiju". \r\nQuando seu oponente ativar um card ou efeito, exceto "Gameciel, o Kaiju Tartaruga Marinha" (Efeito Rápido): você pode remover 2 Marcadores Kaiju de qualquer parte do campo; negue a ativação e, se isso acontecer, bana esse card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55067058,'Número 19: Freezadon',replace(replace('2 monstros de Nível 5	\r\nUma vez por turno, se um Monster Xyz que você controla ativaria um efeito ao desassociar uma ou mais Matérias Xyz, você pode desassociar 1 Matéria Xyz deste card em vez de 1 dessas Matérias Xyz.','\r',char(13)),'\n',char(10)),'Usar o efeito de "Número 19: Freezadon"?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55072170,'Obra de Arte Fazticeira',replace(replace('Se você controlar um monstro "Fazticeira": escolha 1 Magia em qualquer Cemitério; adicione 1 card com o mesmo nome do seu Deck à sua mão. \r\nDurante o turno de qualquer duelista, exceto no turno em que este card foi enviado para o Cemitério: você pode banir este card e qualquer número de Magias do seu Cemitério; Invoque por Invocação-Especial 1 monstro "Fazticeira" do seu Deck cujo Nível seja igual ao número de Magias banidas para ativar este efeito. \r\nVocê só pode usar cada efeito de "Obra de Arte Fazticeira" uma vez por turno.','\r',char(13)),'\n',char(10)),'Escolha um card com o mesmo nome do card a ser adicionada à sua mão','Invocação Especial','Escolha o Nível do monstro a Invocar por Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55088578,'Onomatokage',replace(replace('(Este card deve ser sempre considerado como um card "Zubaba", "Gagaga", "Gogogo" e "Dododo".)	\r\nSe você controlar um monstro "Zubaba", "Gagaga", "Gogogo" ou "Dododo" e este card estiver na sua mão ou no Cemitério: você pode Invocar este card por Invocação-Especial, mas bana-o quando ele deixar o campo. \r\nVocê pode banir este card do seu Cemitério; devolva até 2 Monstros Xyz do seu Cemitério para o Deck Adicional. \r\nVocê só pode usar cada efeito de "Onomatokage" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Recuperar um Monstro Xyz','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55099248,'Morango de Naturia','Uma vez por turno, se seu oponente Invocar um ou mais monstros por Invocação-Normal ou Especial: escolha 1 desses monstros; até o final deste turno, este card ganha 100 de ATK x o Nível desse monstro.','Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55100740,'Criaquímica Hidro Harpyja',replace(replace('Este card é considerado um Monstro Normal enquanto estiver com a face para cima no campo ou no Cemitério. \r\nEnquanto este card for um Monstro Normal no campo, você pode Invocá-lo por Invocação-Normal para fazer com que ele se torne um Monstro de Efeito com este efeito.\r\n● Você pode descartar 1 card e, depois, escolher 1 monstro Gêmeos no seu Cemitério; Invoque-o por Invocação-Especial em Posição de Defesa.	\r\nVocê só pode usar este efeito de "Criaquímica Hidro Harpyja" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55106249,'Robô-secretário 006',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nVocê não pode Invocar monstros por Invocação-Pêndulo, exceto monstros "Robô-secretário". \r\nEste efeito não pode ser negado.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 monstro no campo; mude sua posição de batalha. \r\nEste card ganha 500 de ATK para cada monstro "Robô-secretário" com a face para cima no seu Deck Adicional. \r\nSe este card na Zona de Pêndulo for destruído: você pode escolher 1 card "Robô-secretário" no seu Cemitério; adicione o alvo à sua mão. \r\nVocê só pode usar este efeito de "Robô-secretário 006" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55117418,'Núcleo Neutro-Destruidor',replace(replace('Só pode ser ativado se você controlar um monstro "Koa''ki Meiru" com a face para cima e tiver "Núcleo de Ferro de Koa''ki Meiru" no seu Cemitério. \r\nNegue a ativação de um efeito de um Monstro de Efeito e destrua-o.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55119278,'Rádion Morfotrônico',replace(replace('● Enquanto estiver em Posição de Ataque: Monstros "Morfotrônico(a)" que você controla ganham 800 de ATK.\r\n● Enquanto estiver em Posição de Defesa: Monstros "Morfotrônico(a)" que você controla ganham 1000 de DEF.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55125728,'Vera, a Deusa Vernasílfide',replace(replace('Uma vez por turno, quando um efeito de monstro ativado pelo seu oponente resolver, se você controlar 5 ou mais monstros de TERRA, você pode negar esse efeito e, se isso acontecer, destrua esse card. \r\nVocê só pode usar cada um dos seguintes efeitos de "Vera, a Deusa Vernasílfide" uma vez por turno. \r\nVocê pode escolher 1 monstro com a face para cima que seu oponente controla; tome o controle dele e, se isso acontecer, ele se torna de TERRA. \r\nDurante o turno do seu oponente (Efeito Rápido): você pode escolher 1 monstro de TERRA no seu Cemitério; Invoque-o por Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','Aplicar o efeito de "Vera, a Deusa Vernasílfide" para negar?','Efeito já usado','','','','','','','','','','','','');
INSERT INTO texts VALUES(55136228,'Besta Gladiadora Indomável',replace(replace('Selecione 1 monstro "Besta Gladiadora" com a face para cima que você controla para ganhar 500 de ATK até a Fase Final. \r\nEnquanto este card estiver no seu Cemitério, você pode devolver 2 cards "Besta Gladiadora" do seu Cemitério ao Deck para devolver este card à sua mão.','\r',char(13)),'\n',char(10)),'Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55144522,'Pote da Ganância','Compre 2 cards.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55151012,'Gelojade Tremora',replace(replace('Você pode enviar este card da sua mão para o Cemitério; Invoque por Invocação-Especial 1 monstro de ÁGUA da sua mão. \r\nSe um ou mais monstros de ÁGUA com a face para cima que você controla forem destruídos em batalha ou por um efeito de card, enquanto este card estiver no seu Cemitério: você pode banir este card; Invoque por Invocação-Especial 1 monstro "Gelojade" da sua mão ou do Cemitério, exceto "Gelojade Tremora". \r\nVocê só pode usar cada efeito de "Gelojade Tremora" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55154048,'Relíquia Nórdica Draupnir',replace(replace('Só pode ser equipado a um monstro "Aesir" ou "Nórdic". \r\nEle ganha 800 de ATK. \r\nSe este card com a face para cima no campo for destruído por um efeito de card: você pode adicionar 1 card "Relíquia Nórdica" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55154344,'Reino Ryu-Ge - Ventos Wyrm',replace(replace('Você só pode controlar 1 "Reino Ryu-Ge - Ventos Wyrm". \r\nQualquer monstro enviado do campo para o Cemitério durante o turno do seu oponente, em vez disso, é banido. \r\nMonstros Pêndulo "Ryu-Ge", e monstros de Nível 10 ou mais cujo Tipo original seja Wyrm, que você controla, ganham este efeito.\r\n● Uma vez por turno do oponente (Efeito Rápido): você pode colocar 1 Magia Contínua "Ryu-Ge" que você controla no fundo do Deck e, depois, escolha 1 monstro com a face para cima no campo; o ATK dele se torna 0.','\r',char(13)),'\n',char(10)),'','Alterar ATK (Reino Ryu-Ge - Ventos Wyrm)','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55158350,'Draft de Fusão',replace(replace('Descarte 1 card e, depois, revele 1 Monstro de Fusão no seu Deck Adicional; adicione do seu Deck ou Cemitério à sua mão, 1 das Matérias de Fusão cujo nome seja mencionado nesse monstro revelado, exceto o card descartado e, depois, você pode adicionar um segundo card desses à sua mão, se o primeiro card adicionado era um Monstro Normal. \r\nPelo resto deste turno depois que este card resolver, você não pode Invocar por Invocação-Especial do Deck Adicional, exceto Monstros de Fusão. \r\nVocê só pode ativar 1 "Draft de Fusão" por turno.','\r',char(13)),'\n',char(10)),'Ativar','Adicionar mais 1 à sua mão?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55168550,'Destemido das Galáxias',replace(replace('Se este card estiver na sua mão: você pode revelar 1 monstro "Fóton" da sua mão; Invoque este card por Invocação-Especial e, se isso acontecer, seu Nível se torna o Nível desse monstro "Fóton". \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 monstro "Galáxia" no seu Cemitério; o ATK/DEF deste card se tornam o ATK/DEF desse monstro. \r\nVocê só pode usar cada efeito de "Destemido das Galáxias" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55171412,'Neos Aqua, o HERÓI do Elemento',replace(replace('"Neos, o HERÓI do Elemento" + "Golfinho Aqua Neoespacial"	\r\nDeve primeiro ser Invocado por Invocação-Especial (do seu Deck Adicional) ao embaralhar os cards acima que você controla no Deck. \r\n(Você não usa "Polimerização"). \r\nUma vez por turno: Você pode descartar 1 card; destrua 1 card aleatório na mão do oponente. \r\nDurante a Fase Final: Embaralhe este card no Deck Adicional.','\r',char(13)),'\n',char(10)),'Retornar ao Deck','Descartar da mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55204071,'Engenhoca Marionete Pesadelo',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) ao oferecer como Tributo 1 Monstro Xyz com a face para cima. \r\nVocê só pode Invocar "Engenhoca Marionete Pesadelo" por Invocação-Especial uma vez por turno desta forma. \r\nAo fazê-lo: você pode Invocar por Invocação-Especial 1 "Engenhoca Marionete Pesadelo" da sua mão ou do Cemitério. \r\nSe este card for Invocado por Invocação-Especial, você não pode Invocar nenhum monstro por Invocação-Especial pelo resto deste turno, exceto monstros "Engenhoca Marionete".','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55210709,'Lisark','Uma criatura com olhos de safira que hipnotizam e confundem seus inimigos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55226153,'DoSolfacorde Cutia',replace(replace('Escala de Pêndulo = 8\r\n[ Efeito de Pêndulo ]\r\nA Invocação-Pêndulo dos seus Monstros Pêndulo "Solfacorde" não pode ser negada.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nEnquanto você tiver uma Escala de Pêndulo par na sua Zona de Pêndulo, Monstros Pêndulo "Solfacorde" que você controla ganham ATK igual a 100 x sua própria Escala de Pêndulo. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 Monstro Pêndulo "Solfacorde" do seu Deck à sua mão, exceto "DoSolfacorde Cutia". \r\nVocê só pode usar este efeito de "DoSolfacorde Cutia" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55226821,'Lâmina Relâmpago',replace(replace('Só pode ser equipado a um monstro Guerreiro. \r\nEle ganha 800 de ATK. \r\nTodos os monstros de ÁGUA no campo perdem 500 de ATK.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55241609,'Crusadia Reclusia',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) em Posição de Defesa em uma zona sua para a qual um Monstro Link apontar. \r\nVocê só pode Invocar "Crusadia Reclusia" por Invocação-Especial uma vez por turno desta forma. \r\nSe este card for Invocado por Invocação-Normal ou Especial em uma zona para a qual um Monstro Link apontar: você pode escolher 1 card "Crusadia" que você controla e 1 card que seu oponente controla; destrua-os. \r\nVocê só pode usar este efeito de "Crusadia Reclusia" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55256016,'Julgamento de Anúbis','Quando seu oponente ativar um Card de Magia que destruiria uma ou mais Magias/Armadilhas no campo: descarte 1 card; negue a ativação e, se isso acontecer, destrua-o e, depois, você pode destruir 1 monstro com a face para cima que seu oponente controla e, se isso acontecer, cause dano ao seu oponente igual ao ATK que o monstro destruído tinha no campo.','Destruir 1 monstro com a face para cima que seu oponente controla?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55262310,'Divertida Atração Corrida Rápida',replace(replace('Escolha 1 monstro "Diversão" que você controla ou 1 monstro com a face para cima que seu oponente controla; equipe este card a ele. \r\nVocê pode ativar o seguinte efeito, de acordo com qual duelista controla o monstro equipado;\r\n● Você: Escolha 1 card no Cemitério do seu oponente; mude a posição de batalha do monstro equipado e, se isso acontecer, embaralhe o alvo no Deck.\r\n● Seu oponente: Aumente em 1 o Nível do monstro equipado (até o final deste turno) e, se isso acontecer, mude sua posição de batalha.	\r\nVocê só pode usar este efeito de "Divertida Atração Corrida Rápida" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55271628,'Agonia do Tirano',replace(replace('Ative ao oferecer como Tributo 2 Monstros Normais (exceto Fichas). \r\nNenhum duelista pode Invocar por Invocação-Normal ou Invocação-Especial Monstros de Efeito.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55272555,'Dragão de Chifres Mementotlan',replace(replace('Se você tiver 3 ou mais monstros "Memento" com nomes diferentes no seu Cemitério, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Dragão de Chifres Mementotlan" por Invocação-Especial uma vez por turno desta forma. \r\nSe este card no campo for destruído por um efeito de card: você pode escolher 3 cards com a face para cima no campo, incluindo um card "Memento" que você controla; destrua-os. \r\nVocê só pode usar este efeito de "Dragão de Chifres Mementotlan" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55273560,'Incrível Ecclesia, a Virtuosa',replace(replace('Se seu oponente controlar mais monstros que você, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Incrível Ecclesia, a Virtuosa" por Invocação-Especial uma vez por turno desta forma. \r\nVocê só pode usar cada um dos seguintes efeitos de "Incrível Ecclesia, a Virtuosa" uma vez por turno. \r\nDurante a Fase Principal (Efeito Rápido): você pode oferecer este card como Tributo; Invoque por Invocação-Especial 1 monstro "Espadalma" ou 1 "Caído de Arbaz" da sua mão ou do Deck. \r\nDurante a Fase Final, se um ou mais Monstros de Fusão foram enviados para o seu Cemitério neste turno: você pode adicionar este card do Cemitério à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55273561,'Incrível Ecclesia, a Virtuosa',replace(replace('Se seu oponente controlar mais monstros que você, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Incrível Ecclesia, a Virtuosa" por Invocação-Especial uma vez por turno desta forma. \r\nVocê só pode usar cada um dos seguintes efeitos de "Incrível Ecclesia, a Virtuosa" uma vez por turno. \r\nDurante a Fase Principal (Efeito Rápido): você pode oferecer este card como Tributo; Invoque por Invocação-Especial 1 monstro "Espadalma" ou 1 "Caído de Arbaz" da sua mão ou do Deck. \r\nDurante a Fase Final, se um ou mais Monstros de Fusão foram enviados para o seu Cemitério neste turno: você pode adicionar este card do Cemitério à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55273562,'Incrível Ecclesia, a Virtuosa',replace(replace('Se seu oponente controlar mais monstros que você, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Incrível Ecclesia, a Virtuosa" por Invocação-Especial uma vez por turno desta forma. \r\nVocê só pode usar cada um dos seguintes efeitos de "Incrível Ecclesia, a Virtuosa" uma vez por turno. \r\nDurante a Fase Principal (Efeito Rápido): você pode oferecer este card como Tributo; Invoque por Invocação-Especial 1 monstro "Espadalma" ou 1 "Caído de Arbaz" da sua mão ou do Deck. \r\nDurante a Fase Final, se um ou mais Monstros de Fusão foram enviados para o seu Cemitério neste turno: você pode adicionar este card do Cemitério à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55276522,'Zona de Guerra de Ryu-Ge',replace(replace('Quando este card for ativado: pegue 1 monstro Dinossauro, 1 Serpente Marinha e 1 Wyrm do seu Deck, adicione 1 à sua mão, bana 1 e envie 1 para o Cemitério e, além disso, você não pode Invocar por Invocação-Especial pelo resto deste turno, exceto monstros Dragão, Dinossauro, Serpente Marinha ou Wyrm. \r\nSe você tiver "Sosei Ryu-Ge Mistva" no seu Deck Adicional com a face para cima: você pode Invocar por Invocação-Especial 3 monstros "Ryu-Ge" com Tipos diferentes, 1 de cada do seu Deck, Cemitério e banimento. \r\nVocê só pode usar cada efeito de "Zona de Guerra de Ryu-Ge" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão/Enviar ao Cemitério/Banir','Invocação Especial','Escolha o card cujo efeito será resolvido','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55277252,'Nozoochee, o Mitológico',replace(replace('Durante sua Fase Principal: você pode descartar 1 monstro "Mitológico(a)" e, se isso acontecer, Invoque este card por Invocação-Especial da sua mão. \r\nQuando este card for Invocado por Invocação-Especial desta forma: você pode Invocar por Invocação-Especial 1 monstro "Mitológico(a)" de Nível 2 ou menos da sua mão.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55285840,'Ladrão do Tempo Refeitor',replace(replace('2 monstros de Nível 4	\r\nUma vez por turno, durante a Fase de Apoio: você pode associar o card do topo do Deck do seu oponente a este card. \r\n(Efeito Rápido): você pode desassociar até 3 tipos diferentes de matérias deste card e, depois, aplique o(s) seguinte(s) efeito(s) dependendo do que foi desassociado.\r\n● Monstro: Bana este card até a Fase Final.\r\n● Magia: Compre 1 card.\r\n● Armadilha: Coloque 1 card com a face para cima que seu oponente controla no topo do Deck.	\r\nVocê só pode usar este efeito de "Ladrão do Tempo Refeitor" uma vez por turno.','\r',char(13)),'\n',char(10)),'Associar Matéria Xyz','Desassociar Matéria Xyz','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55289183,'Senhora Obscura Caprichosa',replace(replace('Durante a Fase Principal (Efeito Rápido): você pode ativar este efeito; Invoque por Invocação-Tributo 1 monstro Fada com a face para cima. \r\nSe este card for enviado para o Cemitério: até o final deste turno, você pode fazer com que todos os monstros que seu oponente controla atualmente percam 500 de ATK/DEF para cada monstro Fada no campo. \r\nVocê só pode usar cada efeito de "Senhora Obscura Caprichosa" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55291359,'Campeã Succubus','Uma indigna maga guerreira perita em mágicas letais.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55312487,'Vanguarda Crusadia',replace(replace('Quando você ativar este card: você também pode oferecer como Tributo 1 monstro "Crusadia" ou "Legado Mundial"; se você fez isso, Invoque por Invocação-Especial 1 monstro "Crusadia" ou "Legado Mundial", com um nome original diferente, do seu Deck ou Cemitério. \r\nEnquanto você controlar um Monstro Link "Crusadia", os monstros do seu oponente só podem escolher Monstros Link como alvo de ataques. \r\nVocê só pode ativar 1 "Vanguarda Crusadia" por turno.','\r',char(13)),'\n',char(10)),'Oferecer um monstro como Tributo e Invocar por Invocação Especial?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55320758,'Motoqueiro Goblin Enlouquecendo',replace(replace('Se você não controlar nenhum monstro, ou se todos os monstros que você controla forem monstros "Goblin", você pode Invocar este card por Invocação-Normal sem oferecer Tributo. \r\nVocê só pode usar cada um dos seguintes efeitos de "Motoqueiro Goblin Enlouquecendo" uma vez por turno. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode Invocar por Invocação-Especial 1 monstro "Goblin" de Nível 4 ou menos do seu Deck. \r\nSe este card for enviado para o Cemitério: você pode escolher 1 card no campo; associe-o a 1 Monstro Xyz "Goblin" que você controla.','\r',char(13)),'\n',char(10)),'Invocação Normal sem Tributo','Invocação Especial','Como Matéria Xyz','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55321970,'Leque da Ventania','Um monstro de VENTO equipado com este card tem seu ATK aumentado em 400 pontos e sua DEF reduzida em 200 pontos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55326322,'Cristron Rosênix',replace(replace('Você pode escolher 1 card com a face para cima que você controla; você não pode Invocar monstros por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto Monstros Sincro do Tipo Máquina e, além disso, destrua esse card e, se isso acontecer, Invoque por Invocação-Especial do seu Deck 1 monstro Regulador "Cristron". \r\nVocê pode banir este card do seu Cemitério; Invoque por Invocação-Especial 1 "Ficha de Cristron" (Tipo Máquina/ÁGUA/Nível 1/ATK 0/DEF 0), mas ele não pode ser oferecido como Tributo. \r\nVocê só pode usar 1 efeito de "Cristron Rosênix" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55326323,'Ficha de Cristron','Invocado por Especial com o efeito "Cristron Rosênix". Esta Ficha não pode ser oferecida como Tributo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55337339,'Espelho Mudança de Função','Um espelho perverso que bloqueia os efeitos de dano de um ataque.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55343172,'Campo de Duelo Lendário',replace(replace('Um campo de batalha para aqueles que acreditam nos Decks que construíram, aqueles que nunca viram as costas para seus inimigos, aqueles corajosos o suficiente para lutar até o fim e travar rituais decidindo vencedores e perdedores. \r\nDiz-se que, quando unem seus corações com os corações de suas cards através de laços e dão um passo à frente jurando sobre seu orgulho e suas almas, podem abrir um caminho que segue até o futuro ainda inacabado.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55343236,'Dragão Negro de Olhos Vermelhos Pernicioso',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro deve ser Invocado por Invocação-Especial (da sua mão) ao banir 1 "Dragão Negro de Olhos Vermelhos" do seu Deck. \r\nSó pode haver 1 monstro "Pernicioso(a)" no campo. \r\nOutros monstros que você controla não podem declarar um ataque. \r\nSe não houver Magias de Campo com a face para cima no campo, destrua este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55343303,'Berço de Gelojade','Adicione 1 monstro "Gelojade" do seu Deck à sua mão com um nome diferente que o dos cards que você controla ou no seu Cemitério.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55348096,'Ladrão de Arsenáis','O seu adversário escolhe 1 Card de Magia de Equipamento do seu próprio Deck e envia-o para o Cemitério.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55349196,'Dino Rei Rex de Duas Cabeças',replace(replace('Se você não controlar nenhum monstro, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Dino Rei Rex de Duas Cabeças" por Invocação-Especial uma vez por turno desta forma. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 monstro no campo com menos ATK que o ATK total de todos os monstros Dinossauro que você controla; destrua-o. \r\nVocê só pode usar este efeito de "Dino Rei Rex de Duas Cabeças" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55349375,'Barba Azul, o Engenheiro Saquepatrollha',replace(replace('Se você controlar um monstro "Saquepatrollha", exceto "Barba Azul, o Engenheiro Saquepatrollha": você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe este card for enviado da mão ou da Zona de Monstros para o Cemitério: você pode descartar 1 card; compre 1 card. \r\nVocê só pode usar cada efeito de "Barba Azul, o Engenheiro Saquepatrollha" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55351724,'Recãopensa',replace(replace('Se um monstro atacante seu destruir um monstro do oponente em batalha: escolha 1 card no seu Cemitério; adicione-o à sua mão, mas pelo resto deste turno, você não pode ativar cards, ou os efeitos de cards, com o mesmo nome que o card adicionado tinha quando estava na sua mão. \r\nVocê só pode ativar 1 "Recãopensa" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55359571,'Hinamatsuri de Kochobo',replace(replace('Se este card estiver na sua mão ou no Cemitério: você pode escolher 1 monstro Máquina no campo; pelo resto deste turno, você não pode Invocar por Invocação-Especial do Deck Adicional, exceto Monstros Xyz e, além disso, Invoque este card por Invocação-Especial (mas bana-o quando ele deixar o campo) e, se isso acontecer, diminua pela metade o ATK desse monstro e, além disso, o Nível deste card se torna o desse monstro. \r\nVocê só pode usar este efeito de "Hinamatsuri de Kochobo" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55363218,'Sombra de Cartoon',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) enquanto um monstro que não pode ser Invocado por Invocação-Normal/Baixado está no campo com a face para cima. \r\nVocê só pode Invocar por Invocação-Especial "Sombra de Cartoon" uma vez por turno dessa forma.\r\nSe este card é Invocado por Invocação-Especial: você pode adicionar 1 monstro com 2000 de ATK ou DEF que não pode ser Invocado por Invocação-Normal/Baixado do seu Deck à sua mão.\r\nSe este card for oferecido como Tributo no campo: você pode escolher 1 card no campo, ou você pode escolher 2 se você controal um monstro com 2000 de ATK ou DEF; retorne aquele(s) card(s) para à mão.','\r',char(13)),'\n',char(10)),'Efeito de busca','Retornar para a mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55375684,'Invocação de Nuvem',replace(replace('Uma vez por turno, durante sua Fase Principal: você pode Invocar por Invocação-Especial 1 monstro "Nuviano" de Nível 4 ou menos da sua mão ou de qualquer Cemitério. \r\nVocê não pode controlar nenhum monstro para ativar e resolver este efeito. \r\nSe você Invocar por Invocação-Especial um monstro do Cemitério com este efeito, destrua este card.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55393975,'Destrier de Anjoléquia',replace(replace('1 Regulador + 1+ não-Reguladores	\r\nVocê pode escolher 1 monstro em outra coluna; bana-o. \r\nSe este card for colocado na Zona de Magias & Armadilhas como uma Magia Contínua: você pode adicionar 1 Magia "Anjoléquia" do seu Deck à sua mão. \r\nVocê só pode usar cada um dos efeitos anteriores de "Destrier de Anjoléquia" uma vez por turno. \r\nEnquanto este card for considerado como uma Magia Contínua, sempre que seu oponente ativar um card ou efeito, cause 500 de dano ao seu oponente quando ele resolver.','\r',char(13)),'\n',char(10)),'Efeito de banimento','Efeito de busca','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55397172,'Futsu no Mitama no Mitsurugi',replace(replace('Você pode Invocar este card por Invocação-Ritual com "Ritual de Mitsurugi". \r\nSe seu oponente Invocar um ou mais monstros por Invocação-Especial (exceto durante a Etapa de Dano): você pode escolher 1 monstro Réptil no seu Cemitério, exceto "Futsu no Mitama no Mitsurugi"; Invoque-o por Invocação-Especial. \r\nVocê só pode ativar este efeito de "Futsu no Mitama no Mitsurugi" uma vez por Corrente. \r\nSe este card for oferecido como Tributo: você pode adicionar 1 card "Mitsurugi" do seu Deck à sua mão, exceto "Futsu no Mitama no Mitsurugi" e, depois, você pode Invocar este card por Invocação-Especial. \r\nVocê só pode usar este efeito de "Futsu no Mitama no Mitsurugi" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Adicionar à mão','Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55401221,'Homem-Bateria D','O oponente não pode selecionar um monstro do Tipo Trovão que você controla como alvo de ataque (exceto "Homem-Bateria D").','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55410871,'Dragão MÁX do Caos de Olhos Azuis',replace(replace('Você pode Invocar este card por Invocação-Ritual com "Forma do Caos". \r\nDeve ser Invocado por Invocação-Ritual. \r\nSeu oponente não pode escolher este card como alvo de efeitos de card e, além disso, ele não pode ser destruído pelos efeitos de card do seu oponente. \r\nSe este card atacar um monstro em Posição de Defesa, cause o dobro de dano de batalha perfurante ao seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55410872,'Dragão MÁX do Caos de Olhos Azuis',replace(replace('Você pode Invocar este card por Invocação-Ritual com "Forma do Caos". \r\nDeve ser Invocado por Invocação-Ritual. \r\nSeu oponente não pode escolher este card como alvo de efeitos de card e, além disso, ele não pode ser destruído pelos efeitos de card do seu oponente. \r\nSe este card atacar um monstro em Posição de Defesa, cause o dobro de dano de batalha perfurante ao seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55415564,'D/D Maligno',replace(replace('Escala de Pêndulo = 8\r\n[ Efeito de Pêndulo ]\r\nUma vez, enquanto este card estiver na sua Zona de Pêndulo, quando seu oponente Invocar um ou mais monstros por Invocação-Pêndulo (exceto durante a Etapa de Dano): você pode ativar este efeito; neste turno, esse monstro Invocado por Invocação-Pêndulo não pode atacar e, além disso, seus efeitos são negados.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nNão pode atacar a não ser que você controle outro monstro "D/D". \r\nDurante a Fase Principal do seu oponente (Efeito Rápido): você pode escolher 1 monstro Invocado por Invocação-Pêndulo com a face para cima que seu oponente controla; até o final deste turno, negue os efeitos desse monstro com a face para cima. \r\nVocê só pode usar este efeito de "D/D Maligno" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55416843,'Banquete Selvagem NV5','Invoque por Invocação-Especial até 2 monstros do Tipo Guerreiro de Nível 5 da sua mão e/ou Cemitério, mas seus efeitos são negados, além disso, pelo resto deste turno eles não podem atacar.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55421040,'Chifre de Caça',replace(replace('Invoque por Invocação-Fusão 1 Monstro de Fusão Guerreiro de TERRA do seu Deck Adicional, usando monstros Guerreiro da sua mão ou do campo e, depois, se você ativou este card durante a Fase de Batalha, você pode selecionar monstros que seu oponente controla, até o número de matérias usadas da mão para esta Invocação-Fusão, e o ATK deles é diminuído pela metade até o final da Fase de Batalha. \r\nVocê não pode declarar ataques no turno em que ativar este card, exceto com monstros Guerreiro de TERRA. \r\nVocê só pode ativar 1 "Chifre de Caça" por turno.','\r',char(13)),'\n',char(10)),'Ativar','Reduzir pela metade o ATK do monstro?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55423549,'Leão Mago, o Demônio Negro',replace(replace('Para que um duelista Invoque um monstro por Invocação-Normal da mão dele com mais de 1350 de ATK ou DEF e um Nível original de 4 ou menos, ele deve Invocá-lo por Invocação-Tributo ao oferecer 1 monstro como Tributo. \r\nNo começo da Etapa de Dano, se este card batalhar um monstro de LUZ: você pode destruir esse monstro. \r\nSe este card for destruído em batalha ou por um efeito de card: você pode adicionar 1 monstro com 1350 de ATK do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Leão Mago, o Demônio Negro" uma vez por turno.','\r',char(13)),'\n',char(10)),'Destruir um monstro','Procurar no Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55424270,'Besta Mítica Cérbero',replace(replace('Sempre que um Card de Magia for ativado, coloque 1 Marcador de Magia neste card quando essa Magia resolver. \r\nGanha 500 de ATK para cada Marcador de Magia sobre ele. \r\nNo final da Fase de Batalha, se este card batalhou, remova todos os Marcadores de Magia sobre ele.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55428242,'Armadilhatrix Atrax',replace(replace('Não é afetado pelos efeitos de Armadilhas Normais "Buraco". \r\nVocê pode ativar Cards de Armadilha Normal "Buraco" da sua mão. \r\nA ativação e os efeitos das Armadilhas Normais ativados no seu campo não podem ser negados.','\r',char(13)),'\n',char(10)),'Ativar aplicando o efeito de "Armadilhatrix Atrax".','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55428811,'Quinta Esperança','Escolha 5 cards "HERÓI do Elemento" no seu Cemitério; embaralhe-os no Deck e, depois, compre 2 cards ou, em vez disso, compre 3 cards se você não tinha outros cards no seu campo e na sua mão quando você ativou este card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55444629,'Dragão Inferior','Um dragão inferior incapaz de cuspir fogo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55461064,'HERÓI do Destino - Mestre da Lâmina','Durante a Fase de Batalha do seu oponente (Efeito Rápido): você pode descartar este card; todos os monstros "HERÓI do Destino" que você controla atualmente ganham 800 de ATK até o final deste turno.','Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55461744,'Berfomet de Grandes Asas',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 monstro Besta de Nível 4 e/ou 1 "Fusão Quimera" do seu Deck à sua mão e, além disso, você não pode Invocar monstros por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto Monstros de Fusão. \r\nSe este card for enviado para o Cemitério como matéria para uma Invocação-Fusão: você pode escolher 1 monstro Ilusão no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Berfomet de Grandes Asas" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55465441,'Toma Lá, Dá Cá','Invoque por Invocação-Especial 1 monstro do seu Cemitério no lado do campo do oponente em Posição de Defesa, e aumente o Nível de 1 monstro que você controla de acordo com o Nível do monstro Invocado por Invocação-Especial, até a Fase Final.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55470553,'Número 98: Antitopia',replace(replace('2 monstros de Nível 4	\r\nQuando um monstro declarar um ataque: você pode desassociar 1 matéria deste card; coloque esse monstro em Posição de Defesa. \r\nEnquanto este card estiver no seu Cemitério (Efeito Rápido): você pode escolher 1 monstro "Utopia" no campo; Invoque este card por Invocação-Especial em Posição de Defesa e, se isso acontecer, associe esse monstro a este card como matéria. \r\nVocê só pode usar este efeito de "Número 98: Antitopia" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55484152,'Furo Sangen',replace(replace('Uma vez por turno, quando um monstro for destruído em uma batalha envolvendo um monstro Dragão de FOGO seu: você pode escolher 1 desses monstros destruídos; Invoque-o por Invocação-Especial no seu campo em Posição de Defesa. \r\nDurante a Fase Final do seu oponente: você pode pagar 1000 PV e, depois, escolha 1 Magia/Armadilha "Sangen" no seu Cemitério; Baixe-a, mas bana-a quando ela deixar o campo. \r\nVocê só pode usar este efeito de "Furo Sangen" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Baixar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55488859,'Evoltil Gephyro','Quando este card for destruído em batalha e enviado ao Cemitério: Você pode escolher 1 monstro "Evolssauro" no seu Cemitério; Invoque o alvo por Invocação-Especial.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55496220,'Interferência Críptica',replace(replace('Durante o cálculo de dano, se um monstro "Críptico(a)" seu batalhar, enquanto outro monstro com seu mesmo nome estiver no campo: até o final da Fase de Batalha, você pode dobrar o ATK do seu monstro "Críptico(a)" que está batalhando. \r\nVocê só pode usar este efeito de "Interferência Críptica" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55501446,'Serpente de Luz',replace(replace('Se este card for enviado da mão para o Cemitério: você pode Invocar este card por Invocação-Especial do seu Cemitério. \r\nNão pode ser usado como Matéria Sincro.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55521751,'Brisawntarilho e os Ventos Inexplorados',replace(replace('Você pode conduzir Invocações-Tributo que requerem 2 Tributos ao enviar para o Cemitério 1 monstro que você controla e 1 card que seu oponente controla em vez de oferecer Tributo (isso ainda é considerado uma Invocação-Tributo). \r\nDurante sua Fase Principal: você pode revelar até 2 monstros Besta Alada na sua mão e coloque-os no fundo do seu Deck em qualquer ordem e, depois, compre o mesmo número de cards. \r\nVocê só pode usar este efeito de "Brisawntarilho e os Ventos Inexplorados" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar pelo efeito de "Brisawntarilho e os Ventos Inexplorados"','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55537983,'Mestre Mimicarniçal',replace(replace('Não pode ser destruído em batalha ou por efeitos de card enquanto seu oponente controlar quaisquer monstros com a face para baixo ou você controlar um monstro "Mimicarniçal" que não seja "Mestre Mimicarniçal". \r\nVocê só pode usar cada um dos seguintes efeitos de "Mestre Mimicarniçal" uma vez por turno. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 monstro "Mimicarniçal" do seu Deck à sua mão, exceto "Mestre Mimicarniçal". \r\nDurante a Fase Principal do seu oponente (Efeito Rápido): você pode colocar 1 monstro com a face para baixo no campo, com a face para cima em Posição de Ataque ou de Defesa.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Mudar a posição de batalha','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55538156,'Formação de Fogo Definitiva - Sinto',replace(replace('Quando um Card de Magia/Armadilha for ativado, enquanto você controlar um monstro "Punho de Fogo" e uma Magia/Armadilha "Formação de Fogo": negue a ativação e, se isso acontecer, destrua esse card. \r\nVocê só pode ativar 1 "Formação de Fogo Definitiva - Sinto" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55550921,'Guerreiro Batalhador','Um guerreiro que luta com as mãos nuas!!!','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55553602,'Teatro Dramático Camarartista',replace(replace('Os monstros que você controla ganham 200 de ATK para cada monstro que você controla com um Tipo diferente. \r\nUma vez por turno, se você controlar 4 monstros "Camarartista" com Tipos diferentes: você pode Invocar por Invocação-Especial 1 monstro "Olhos Anômalos" da sua mão, Deck ou Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55554175,'Camarartista Classikuriboh',replace(replace('Escala de Pêndulo = 8\r\n[ Efeito de Pêndulo ]\r\nQuando um monstro do oponente declarar um ataque direto, este card é destruído.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe este card for destruído por seu próprio Efeito de Pêndulo: encerre a Fase de Batalha. \r\nVocê só pode usar cada um dos seguintes efeitos de "Camarartista Classikuriboh" uma vez por turno. \r\nVocê pode descartar este card e, depois, escolha 1 card na sua Zona de Pêndulo; sua Escala de Pêndulo se torna 1 até o final deste turno. \r\nQuando você sofrer dano de batalha enquanto este card estiver no seu Cemitério: você pode colocar este card na sua Zona de Pêndulo.','\r',char(13)),'\n',char(10)),'Alterar a Escala de Pêndulo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55557574,'Invocação Cintilante',replace(replace('Durante a Fase Principal ou de Batalha: imediatamente depois que este efeito resolver, Invoque por Invocação-Normal 1 monstro de Nível 10 ou, se você controlar "O Cavaleiro da Rainha", "O Cavaleiro do Rei" e "O Cavaleiro do Valete", em vez disso, você pode aplicar este efeito.\r\n● Adicione 1 monstro de Nível 10 que não seja de TREVAS com ATK ? do seu Deck à sua mão e, depois, imediatamente depois que este efeito resolver, você pode Invocar por Invocação-Normal 1 monstro de Nível 10.	\r\nVocê só pode ativar 1 "Invocação Cintilante" por turno.','\r',char(13)),'\n',char(10)),'','Adicionar à sua mão um monstro de Nível 10 do seu Deck?','Invocar um monstro de Nível 10?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55567161,'Pote, o Truque','Um servo não tão poderoso, ele é o menino errante de um mestre feiticeiro.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55569674,'Espada Celestial - Eatos',replace(replace('(Este card deve ser sempre considerado como um card "Armas Nobres".)	\r\nO monstro equipado ganha 500 de ATK. \r\nQuando este card for enviado do campo para o Cemitério: você pode escolher 1 "Guardião Eatos" que você controla; ele ganha 500 de ATK para cada monstro banido.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55573346,'Oops!','Escolha 1 card que você controla; destrua-o.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55584558,'Deliciosa Lembrança Purrely',replace(replace('Selecione 1 monstro no campo e, até o final do próximo turno, ele não pode ser destruído em batalha. \r\nDepois de selecionar um card, você pode aplicar o seguinte efeito.\r\n● Descarte 1 card e, se isso acontecer, Invoque por Invocação-Especial do seu Deck 1 monstro "Purrely" de Nível 1.	\r\nUm Monstro Xyz "Purrely" que tenha este card como matéria ganha o seguinte efeito.\r\n● Ganha 300 de ATK/DEF para cada matéria associada a ele.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial do Deck?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55585856,'Misstic Call',replace(replace('Se este card está na sua mão ou Cemitério: você pode descartar 1 outro monstro Mago ou 1 Magia/Armadilha; Invoque por Invocação-Especial este card, mas bana-o quando ele deixar o campo.\r\nSe este card é Invocado por Invocação-Especial: você pode banir 1 monstro Mago de Nível 4 do seu Deck, e se fizer, durante a Fase Final deste turno, adicione-o à sua mão ou Invoque-o por Invocação-Especial.\r\nVocê só pode usar cada efeito de "Misstic Call" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Efeito de banimento','Banir pelo efeito de "Misstic Call"','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55586621,'Senhora Fortuna das Trevas',replace(replace('O ATK/DEF deste card se tornam seu Nível x 400. \r\nUma vez por turno, durante sua Fase de Apoio: aumente em 1 o Nível deste card (máx. 12). \r\nQuando um monstro "Senhora Fortuna" seu destruir um monstro do oponente em batalha e enviá-lo para o Cemitério: você pode escolher 1 monstro "Senhora Fortuna" no seu Cemitério; Invoque-o por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Aumentar o Nível','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55589254,'Dragão das Chamas e da Geada',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao banir 1 monstro de FOGO e 2 de ÁGUA do seu Cemitério. \r\nUma vez por turno: você pode descartar 1 card e, depois, escolha 1 monstro no campo; destrua o alvo.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55591586,'Duodragão do Trovão',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro deve ser Invocado por Invocação-Especial (da sua mão) ao banir 1 monstro de LUZ e 1 monstro de TREVAS do seu Cemitério. \r\nUma vez por turno, se um efeito de monstro for ativado na mão: este card ganha 300 de ATK até o final deste turno. \r\nQuando este card destruir um monstro do oponente em batalha: você pode banir 1 card do seu Cemitério; adicione 1 monstro Trovão do seu Deck à sua mão. \r\nUma vez por turno, durante a Fase Final do seu oponente: você pode escolher 1 dos seus cards banidos; coloque-o no topo ou no fundo do seu Deck.','\r',char(13)),'\n',char(10)),'','','','','Colocar no topo do Deck','Retornar ao fundo do Deck','','','','','','','','','','');
INSERT INTO texts VALUES(55599882,'Bujintervenção',replace(replace('Escolha 1 monstro "Bujin" no campo; aplique este efeito a ele pelo resto deste turno. \r\nSempre que ele destruir um monstro em batalha, cujo ATK seja maior ou igual que o ATK original do monstro alvo, e enviá-lo para o Cemitério: bana o monstro destruído e, se isso acontecer, bana todos os monstros na mão, no Deck Principal, Deck Adicional e Cemitério do oponente, que tenham o mesmo nome que o monstro destruído tinha no Cemitério.','\r',char(13)),'\n',char(10)),'Banir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55608151,'Asa de Grifo','Quando seu oponente ativar "Espanador de Penas da Harpia": negue seu efeito e, se isso acontecer, destrua todas as Magias e Armadilhas que seu oponente controla.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55610199,'Dama Cavaleiro-Gema Diamante Rosa',replace(replace('1 monstro "Cavaleiro-Gema" + 1 monstro Fada	\r\nUma vez por turno do oponente, na primeira vez que um ou mais monstros "Cavaleiro-Gema" que você controla seriam destruídos por um efeito de card, ele(s) não é(são) destruído(s). \r\nDurante o seu turno, quando seu oponente ativar um efeito de monstro (Efeito Rápido): você pode banir 1 card "Cavaleiro-Gema" do seu Cemitério e, depois, escolha 1 card com a face para cima que seu oponente controla; destrua-o.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55610595,'Asanegra - Pinaki, a Lua Crescente',replace(replace('Não pode ser usado como Matéria Sincro, exceto para a Invocação-Sincro de um Monstro Sincro "Asanegra". \r\nDurante a Fase Final, se este card estiver no Cemitério porque foi enviado do campo para lá neste turno: você pode adicionar 1 monstro "Asanegra" do seu Deck à sua mão, exceto "Asanegra - Pinaki, a Lua Crescente". \r\nVocê só pode usar este efeito de "Asanegra - Pinaki, a Lua Crescente" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55615891,'Homem-Alado Selvagem, o HERÓI do Elemento',replace(replace('"Coração Selvagem, o HERÓI do Elemento" + "Aviário, o HERÓI do Elemento"	\r\nDeve ser Invocado por Invocação-Fusão. \r\nVocê pode descartar 1 card e, depois, escolha 1 Magia/Armadilha no campo; destrua o alvo.','\r',char(13)),'\n',char(10)),'Destruir Magias/Armadilhas','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55623480,'Cauda de Fadas - Neves',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 monstro com a face para cima que seu oponente controla; coloque-o com a face para baixo em Posição de Defesa. \r\nSe este card estiver no seu Cemitério (Efeito Rápido): você pode banir 7 outros cards da sua mão, do campo e/ou do Cemitério; Invoque este card por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Mudar para Posição de Defesa com a face para baixo','Invocar este card por Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55624610,'Caçador de Restolhos','Uma vez por turno, você pode selecionar 1 monstro "Restolhos" com a face para cima que você controla, exceto este card, destrua-o e envie 1 monstro Regulador do seu Deck ao seu Cemitério.','Destruir e enviar ao Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55673611,'Gatilho Psíquico',replace(replace('Ative apenas enquanto seus PV forem menores que os do seu oponente. \r\nSelecione 2 monstros do Tipo Psíquico no seu Cemitério. \r\nRemova-os de jogo e compre 2 cards.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55688914,'Alma Aniquiladora Pluton HG',replace(replace('Durante o turno do seu oponente, se você não controlar nenhum monstro, ou controlar apenas monstros "Alma Aniquiladora", na sua Zona de Monstros Principal (Efeito Rápido): você pode Invocar este card por Invocação-Especial da sua mão. \r\n(Efeito Rápido): você pode ativar 1 desses efeitos ao revelar um ou mais monstros na sua mão com o(s) \r\nAtributo(s) listado(s);\r\n● FOGO: Este card ganha 3000 de DEF até o final deste turno.\r\n● TREVAS & TERRA: Este card ganha 3000 de ATK até o final deste turno.	\r\nVocê só pode usar cada efeito de "Alma Aniquiladora Pluton HG" uma vez por turno e não pode ativar mais que 1 na mesma Corrente.','\r',char(13)),'\n',char(10)),'Invoque este card por Invocação Especial da sua mão','Revele um monstro de FOGO','Revele um monstro de TREVAS ou TERRA','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55690251,'Senhor Obscuro Desejo',replace(replace('Não pode ser Invocado por Invocação-Especial. \r\nVocê pode Invocar este card por Invocação-Tributo ao oferecer como Tributo 1 monstro do Tipo Fada. \r\nUma vez por turno: você pode escolher 1 monstro que seu oponente controla; este card perde exatamente 1000 de ATK e, se isso acontecer, envie o alvo para o Cemitério.','\r',char(13)),'\n',char(10)),'Ofereça 1 monstro Fada como Tributo para uma Invocação Tributo','Envie para o Cemitério 1 monstro que seu oponente controla','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55691901,'Bicudão','Nada escapa da boca enorme desta besta.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55696885,'Lobo da Praga',replace(replace('Uma vez por turno: até o final deste turno, você pode fazer com que o ATK deste card se torne o dobro do seu ATK original. \r\nUma vez por turno, durante a Fase Final, se este efeito foi ativado: destrua este card.','\r',char(13)),'\n',char(10)),'Aumentar ATK','Destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55697723,'Mandíbulas Grandes Emergentes',replace(replace('Se este card for usado para a Invocação-Xyz de um monstro de ÁGUA, ele pode ser considerado como um monstro de Nível 3 ou 5. \r\nVocê só pode usar cada um dos seguintes efeitos de "Mandíbulas Grandes Emergentes" uma vez por turno. \r\nDurante sua Fase Principal, se um Card de Magia foi ativado neste turno: você pode Invocar este card por Invocação-Especial da sua mão e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto Monstros Xyz. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 monstro Peixe "Tubarão" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Invocação Especial','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55702233,'Ret-time Reviver Emit-ter',replace(replace('Se este card estiver na sua mão ou no Cemitério: você pode escolher 1 monstro com a face para cima em cada campo; coloque-os com a face para baixo em Posição de Defesa e, se isso acontecer, Invoque este card por Invocação-Especial, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar este efeito de "Ret-time Reviver Emit-ter" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55704856,'Fusão Cibercarga',replace(replace('Invoque por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional que liste um monstro "Dragão Cibernético" como matéria, ao embaralhar no Deck as Matérias de Fusão listadas nele, dentre seus cards no campo e/ou seus cards banidos com a face para cima, mas os monstros que você controla não podem atacar pelo resto deste turno, exceto esse monstro Invocado por Invocação-Fusão. \r\nVocê só pode ativar 1 "Fusão Cibercarga" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55705473,'Baobabuíno',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode comprar 1 card e, depois, coloque 1 card da sua mão no topo ou no fundo do seu Deck. \r\nSe este card for destruído em batalha ou por um efeito de card: você pode Invocar por Invocação-Especial qualquer número de "Baobabuíno" do seu Deck.','\r',char(13)),'\n',char(10)),'Comprar','Colocar no topo do Deck','Retornar ao fundo do Deck','Invocação Especial','','','','','','','','','','','','');
INSERT INTO texts VALUES(55713623,'Encolher','Escolha 1 monstro com a face para cima no campo; o ATK original dele é diminuído pela metade até o final deste turno.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55725117,'Gotanimados Travesso-Guris',replace(replace('Se este card for enviado para o Cemitério como matéria para a Invocação-Fusão ou Link de um monstro "Travesso-Guris": você pode ganhar 1000 PV e, depois, você pode Invocar por Invocação-Especial 1 monstro "Travesso-Guris" da sua mão ou do Deck em Posição de Defesa, exceto "Gotanimados Travesso-Guris". \r\nVocê só pode usar este efeito de "Gotanimados Travesso-Guris" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55727845,'Número 96: Névoa Obscura',replace(replace('3 monstros de Nível 2	\r\nUma vez por batalha, quando um ataque for declarado envolvendo este card e um monstro do oponente (Efeito Rápido): você pode desassociar 1 matéria deste card; diminua pela metade o ATK do monstro do oponente e, se isso acontecer, este card ganha o mesmo valor de ATK.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55733143,'Encanto Mimicarniçal',replace(replace('Uma vez por Corrente, durante a Fase Principal, se um monstro "Mimicarniçal" que seu oponente controla for virado com a face para cima: você pode selecionar aleatoriamente 1 card com a face para baixo no Deck Adicional do seu oponente e, se for um monstro que possa ser Invocado por Invocação-Especial, Invoque-o por Invocação-Especial no seu campo, mas ele não pode ativar seus efeitos neste turno. \r\nSe não era, ou se não podia ser Invocado por Invocação-Especial, bana esse card. \r\nVocê só pode usar este efeito de "Encanto Mimicarniçal" duas vezes por turno.','\r',char(13)),'\n',char(10)),'','Verificar o Deck Adicional','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55735315,'Dragão Drena Almas',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial pelo efeito de um Monstro Xyz do Tipo Dragão em sua posse e não pode ser Invocado por Invocação-Especial de nenhuma outra forma. \r\nQuando ele for Invocado por Invocação-Especial, se você tiver menos Pontos de Vida que seu oponente: este card ganha ATK igual ao seu déficit de Pontos de Vida e, se isso acontecer, seu oponente não sofre mais dano neste turno. \r\nEste card não pode atacar diretamente seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55737443,'Exxod, Mestre da Guarda',replace(replace('Este card não pode ser Invocado por Invocação-Normal ou Baixado. \r\nEste card não pode ser Invocado por Invocação-Especial, exceto oferecendo como Tributo 1 monstro"esfinge". \r\nSempre que um monstro de TERRA for Invocado por Invocação-Virar, enquanto este card permanecer com a face para cima no campo, cause 1000 de dano ao seu oponente.','\r',char(13)),'\n',char(10)),'Causar dano aos PV','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55742055,'Nobre Cavaleiros da Távola Redonda',replace(replace('Durante sua Fase Final: você pode ativar cada um desses efeitos até uma vez por turno, dependendo do número total de cards "Nobre Cavaleiro" com nomes diferentes no seu Cemitério e/ou que você controla;\r\n● 3+: Envie 1 card "Nobre Cavaleiro" do seu Deck para o Cemitério.\r\n● 6+: Invoque por Invocação-Especial 1 monstro "Nobre Cavaleiro" da sua mão e, depois, você pode equipar a esse monstro 1 Magia de Equipamento "Armas Nobres" da sua mão.\r\n● 9+: Escolha 1 monstro "Nobre Cavaleiro" no seu Cemitério; adicione o alvo à sua mão.\r\n● 12: Compre 1 card.','\r',char(13)),'\n',char(10)),'Enviar 1 card "Nobre Cavaleiro" do seu Deck para o Cemitério','Invoque por Invocação Especial 1 monstro "Nobre Cavaleiro" da sua mão','Adicione à sua mão 1 monstro "Nobre Cavaleiro" do seu Cemitério','Compre 1 card(s)','Equipar o Card de Magia de Equipamento àquele monstro?','','','','','','','','','','','');
INSERT INTO texts VALUES(55749927,'Chifre do Olifante',replace(replace('Ative 1 desses efeitos;\r\n● Bana 1 Magia de Equipamento que você controla ou no seu Cemitério e, depois, você pode destruir 1 card no campo.\r\n● Destrua 1 monstro "Roland" que você controla e, depois, Invoque por Invocação-Especial em Posição de Defesa, até 3 monstros Guerreiro de FOGO do seu Deck, cuja soma dos Níveis seja igual a 9, mas seus efeitos são negados e, além disso, até o final do seu próximo turno depois que este efeito resolver, você não pode Invocar monstros por Invocação-Especial, exceto monstros Guerreiro.	\r\nVocê só pode ativar 1 "Chifre do Olifante" por turno.','\r',char(13)),'\n',char(10)),'Banir e destruir','Destruir e Invocar por Invocação Especial','Destruir o card selecionado?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55758589,'Wivern de Fóton','Quando este card for Invocado por Invocação-Normal ou Virar: destrua todos os cards Baixados que seu oponente controla.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55761792,'Ritual do Lustro Negro',replace(replace('Este card é usado para a Invocação-Ritual de "Soldado do Lustro Negro". \r\nVocê também deve oferecer como Tributo monstros da sua mão ou do campo cuja soma dos Níveis seja igual a 8 ou mais.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55762976,'Gussari @Ignister',replace(replace('Quando um Monstro Link for destruído em batalha: você pode Invocar este card por Invocação-Especial da sua mão. \r\nQuando um Monstro Link seu destruir um monstro do oponente em batalha: você pode causar dano ao seu oponente igual ao ATK original desse monstro destruído. \r\nQuando um ataque for declarado envolvendo um Monstro Link que você controla e um monstro do oponente: você pode banir este card do seu Cemitério; o ATK desses monstros se torna 3000. \r\nVocê só pode usar cada efeito de "Gussari @Ignister" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55763552,'Flautista de Dragões','VIRE: Destrói "Jarro de Captura de Dragões", e todos os monstros do Tipo Dragão com a face para cima mudam para a Posição de Ataque.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55766177,'Traição Mitológica',replace(replace('Escolha 1 monstro "Mitológico(a)" no seu Cemitério e 1 card com a face para cima no campo; descarte 1 card e, se isso acontecer, Invoque esse monstro por Invocação-Especial do seu Cemitério e, se isso acontecer, destrua esse card no campo. \r\nVocê só pode ativar 1 "Traição Mitológica" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55773067,'Jogar Fora','Quando seu oponente realizar sua compra normal na Fase de Compra dele: seu oponente descarta 1 card que ele acabou de comprar.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55784832,'Morinphen','Um estranho demônio com longos braços e garras afiadas como lâminas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55787576,'Legado Mundial - "Escudo Mundial"',replace(replace('Não pode ser afetado por efeitos ativados de quaisquer monstros Invocados por Invocação-Especial do Deck Adicional. \r\nSeu oponente não pode escolher seus cards "Legado Mundial" na coluna deste card como alvo de efeitos de card e, além disso, eles não podem ser destruídos pelos efeitos de card do seu oponente. \r\nDurante a Fase de Apoio, se este card estiver no seu Cemitério: você pode pagar 1000 PV; Invoque este card por Invocação-Especial e, depois, seu oponente pode Invocar por Invocação-Especial 1 monstro da mão ou do Cemitério dele. \r\nVocê só pode usar este efeito de "Legado Mundial - "Escudo Mundial"" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Invocar por Invocação Especial 1 monstro da sua mão ou Cemitério?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55794644,'Mestre Hyperion',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) ao banir 1 monstro "O Representante" da sua mão, do campo ou do Cemitério. \r\nUma vez por turno: você pode banir 1 monstro Fada de LUZ do seu Cemitério e, depois, escolha 1 card no campo; destrua o alvo. \r\nEnquanto "O Santuário no Céu" estiver no campo, você pode ativar este efeito até duas vezes por turno.','\r',char(13)),'\n',char(10)),'Destruir 1 card no campo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55795155,'Evolução Pêndulo',replace(replace('Você pode embaralhar no Deck 1 Monstro Pêndulo da sua mão; adicione, do seu Deck à sua mão, 1 Monstro Pêndulo com 2500 de ATK e um nome diferente. \r\nDurante sua Fase Principal, se neste turno você Invocou por Invocação-Especial um Monstro Pêndulo do Deck Adicional com a face para baixo, você pode: imediatamente depois que este efeito resolver, Invocar um ou mais monstros por Invocação-Pêndulo. \r\nVocê pode escolher 1 "Rei Supremo Z-ARC" que você controla; neste turno, ele pode atacar todos os monstros que seu oponente controla, uma vez cada. \r\nVocê só pode usar cada efeito de "Evolução Pêndulo" uma vez por turno.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Invocação Pêndulo','Atacar todos os monstros','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55818463,'Senhor dos Liches, o Rei do Submundo',replace(replace('Se você Invocar este card por Invocação-Tributo, o Tributo deve ser de TREVAS. \r\nSe este card for oferecido como Tributo por um efeito de card e enviado para o Cemitério: adicione este card do seu Cemitério à sua mão.','\r',char(13)),'\n',char(10)),'Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55821894,'Lutador Amazoness','Você não sofre dano de batalha dos ataques que envolvem este card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55824220,'Fusão de Piroxênio',replace(replace('Envie, da sua mão ou do seu lado do campo para o Cemitério, os Monstros-Matéria de Fusão que estiverem listados em um Card de Monstro de Fusão "Cavaleiro-Gema" e, depois, Invoque por Invocação-Especial esse Monstro de Fusão do seu Deck Adicional. \r\n(Essa Invocação-Especial é considerada como uma Invocação-Fusão.)','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55838342,'Crusadia Krawler',replace(replace('Invoque este card por Invocação-Especial como um Monstro de Efeito (Inseto/TERRA/Nível 2/ATK 300/DEF 2100).	\r\n(Este card ainda é uma Armadilha.) \r\nSe este card for Invocado por Invocação-Especial por este efeito em uma zona para a qual um Monstro Link apontar: você pode adicionar 1 card "Legado Mundial" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55863245,'Tatsunoko',replace(replace('1 Regulador + 1+ não-Reguladores	\r\nSe este monstro Invocado por Invocação-Sincro seria usado como uma Matéria Sincro, 1 monstro da sua mão pode ser usado como 1 outra matéria. \r\nNão é afetado por outros efeitos de monstro.','\r',char(13)),'\n',char(10)),'Usar 1 monstro da sua mão como Matéria Sincro?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55870497,'Espada Bambu Flamejante','Se você ativar um card "Espada Bambu" enquanto este card já estiver com a face para cima na sua Zona de Magias & Armadilhas: você pode pular a próxima Fase Principal 1 do seu oponente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55875323,'Lagarto Elétrico','Um monstro que não seja do Tipo Zumbi que esteja atacando "Lagarto Elétrico" não pode atacar no seu turno seguinte.','Restrição de ataque','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55878038,'Dragão do Caos Levianeiro',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro deve ser Invocado por Invocação-Especial (da sua mão) ao banir 3 monstros de LUZ e/ou de TREVAS do seu Cemitério. \r\nQuando Invocado desta forma: você pode ativar este efeito; aplique o seguinte efeito, de acordo com o(s) \r\nAtributo(s) dos monstros banidos para a Invocação-Especial e, além disso, este card não pode atacar pelo resto deste turno.\r\n● Apenas LUZ: Invoque por Invocação-Especial 1 monstro do seu Cemitério em Posição de Defesa.\r\n● Apenas TREVAS: Embaralhe 1 card aleatório da mão do seu oponente no Deck.\r\n● Tanto LUZ como TREVAS: Destrua até 2 cards no campo.	\r\nVocê só pode usar este efeito de "Dragão do Caos Levianeiro" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Invoque por Invocação Especial 1 monstro do seu Cemitério em Posição de Defesa','Embaralhe aleatoriamente 1 card da mão do seu oponente no Deck','Escolha até 2 cards no campo para destruí-los','','','','','','','','','','','','');
INSERT INTO texts VALUES(55878039,'Dragão do Caos Levianeiro',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro deve ser Invocado por Invocação-Especial (da sua mão) ao banir 3 monstros de LUZ e/ou de TREVAS do seu Cemitério. \r\nQuando Invocado desta forma: você pode ativar este efeito; aplique o seguinte efeito, de acordo com o(s) \r\nAtributo(s) dos monstros banidos para a Invocação-Especial e, além disso, este card não pode atacar pelo resto deste turno.\r\n● Apenas LUZ: Invoque por Invocação-Especial 1 monstro do seu Cemitério em Posição de Defesa.\r\n● Apenas TREVAS: Embaralhe 1 card aleatório da mão do seu oponente no Deck.\r\n● Tanto LUZ como TREVAS: Destrua até 2 cards no campo.	\r\nVocê só pode usar este efeito de "Dragão do Caos Levianeiro" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Invoque por Invocação Especial 1 monstro do seu Cemitério em Posição de Defesa','Embaralhe aleatoriamente 1 card da mão do seu oponente no Deck','Escolha até 2 cards no campo para destruí-los','','','','','','','','','','','','');
INSERT INTO texts VALUES(55885348,'Destruidor Negro de Kozmo',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 monstro no campo; destrua-o. \r\nSeu oponente não pode escolher este card como alvo de efeitos de card. \r\nSe este card for destruído em batalha ou por um efeito de card e enviado para o Cemitério: você pode banir este card do seu Cemitério; Invoque por Invocação-Especial 1 monstro "Kozmo" de Nível 7 ou menos do seu Deck.','\r',char(13)),'\n',char(10)),'Destruir 1 monstro','Invoque por Invocação Especial um monstro "Kozmo" do Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55888045,'Número C106: Mão Vermelha Gigante',replace(replace('3 monstros de Nível 5	\r\nSe este card tiver um monstro "Número" como matéria, ele ganha este efeito.\r\n● Uma vez por turno, quando um card ou efeito for ativado no campo (Efeito Rápido): desassocie 1 matéria deste card e, se isso acontecer, até o final deste turno, negue os efeitos de todos os outros cards com a face para cima atualmente no campo.','\r',char(13)),'\n',char(10)),'Negar o efeito','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55920742,'Melodia Vulpina Noh-P.U.N.K.',replace(replace('Uma vez por turno, quando este card destruir um monstro do oponente em batalha: você pode ganhar PV igual ao ATK original desse monstro. \r\nVocê só pode usar cada um dos seguintes efeitos de "Melodia Vulpina Noh-P.U.N.K." uma vez por turno. \r\nVocê pode oferecer como Tributo 1 monstro "P.U.N.K."; Invoque este card por Invocação-Especial da sua mão. \r\nVocê pode enviar este card da sua mão ou do campo para o Cemitério; envie 1 card da sua mão para o Cemitério e, se isso acontecer, Invoque por Invocação-Especial 1 monstro "P.U.N.K." do seu Deck, exceto um monstro de Nível 8.','\r',char(13)),'\n',char(10)),'Invocar este card por Invocação Especial','Invocar por Invocação Especial do Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55935416,'Número 56: Rato Dourado',replace(replace('3 monstros de Nível 1	\r\nUma vez por turno: você pode desassociar 1 Matéria Xyz deste card; compre 1 card e, depois, embaralhe 1 card da sua mão no Deck.','\r',char(13)),'\n',char(10)),'Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55936191,'Ursártico Miktanus',replace(replace('Durante a Fase Principal (Efeito Rápido): você pode oferecer como Tributo 1 outro monstro de Nível 7 ou mais da sua mão; Invoque este card por Invocação-Especial da sua mão e, além disso, você não pode Invocar por Invocação-Especial pelo resto deste turno, exceto monstros com um Nível. \r\nSe este card for Invocado por Invocação-Especial: você pode escolher 1 monstro "Ursártico(a)" no seu Cemitério, exceto "Ursártico Miktanus"; adicione-o à sua mão. \r\nVocê só pode usar cada efeito de "Ursártico Miktanus" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55948544,'Julgamento do Faraó',replace(replace('Pague metade dos seus PV. \r\nSelecione e ative um efeito apropriado que seja aplicável:\r\n● Se "Amizade Yu-Jo" estiver no seu Cemitério, até o fim deste turno: Seu oponente não pode Invocar um ou mais monstros por Invocação-Normal, Invocação-Baixar, Invocação-Virar ou Invocação-Especial ou ativar o efeito de um Monstro de Efeito, e os efeitos de monstros dele são negados.\r\n● Se "Unidade" estiver no seu Cemitério, até o fim deste turno: negue os efeitos de todos os Cards de Magia e Armadilha no lado do campo do oponente, e seu oponente não pode ativar nem Baixar Cards de Magia ou Armadilha.','\r',char(13)),'\n',char(10)),'"Amizade Yu-Jo"','"Unidade"','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55965529,'Enato Eneanave - "oknirIA"',replace(replace('Escala de Pêndulo = 0\r\n[ Efeito de Pêndulo ]\r\nSempre que um ou mais monstros forem virados com a face para cima, coloque 1 Marcador de E.N. neste card. \r\nVocê pode pagar 900 PV; revele 3 cards "Eneanave" do seu Deck, seu oponente elege 1 aleatoriamente para que você adicione à sua mão, embaralhe o resto no Deck. \r\nVocê só pode usar este efeito de "Enato Eneanave - "oknirIA"" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nVIRE: Embaralhe no Deck até 3 cards do Cemitério do seu oponente e/ou banimento.\r\nQuando seu oponente ativar um efeito de card no Cemitério ou banimento (Efeito Rápido): você pode colocar este card que estiver com a face para baixo, com a face para cima em Posição de Defesa; adicione 1 card "Eneanave" do seu Deck à sua mão. \r\nVocê pode revelar este card na sua mão; Invoque por Invocação-Especial 1 monstro da sua mão com a face para baixo em Posição de Defesa. \r\nVocê não pode Invocar por Invocação-Especial no turno em que ativar este efeito, exceto com a face para baixo em Posição de Defesa.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Invocação Especial','Adicionar à mão','Retornar ao Deck','','','','','','','','','','','','');
INSERT INTO texts VALUES(55969226,'Invocador do Dragão Azul','Se este card for enviado do campo para o Cemitério: você pode adicionar 1 Monstro Normal Dragão, Guerreiro ou Mago do seu Deck à sua mão.','Procurar no Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55976207,'Execução do Contrato',replace(replace('Você pode revelar 1 Monstro de Ritual na sua mão; até o final deste turno, o monstro equipado se torna do Nível do monstro revelado (mesmo que este card deixe o campo). \r\nSe este card for enviado para o Cemitério porque o monstro equipado foi oferecido como Tributo: você pode escolher 1 monstro que seu oponente controla; destrua-o. \r\nVocê só pode usar cada efeito de "Execução do Contrato" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55982698,'Interruptivo, Aliado da Justiça',replace(replace('Se um monstro de LUZ estiver no campo, destrua este card. \r\nNo começo da Etapa de Dano, se este card atacar um monstro com a face para baixo em Posição de Defesa: destrua esse monstro com a face para baixo.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55985014,'Crianças Milagrosas','Escolha 1 monstro que seu oponente controla; esse alvo perde 400 de ATK para cada "Herói Criança" no seu Cemitério até a Fase Final.','Reduzir ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55990317,'Hugin, as Asas Rúnikas',replace(replace('2 monstros "Rúnika(o)"	\r\nSe este card for Invocado por Invocação-Especial do Deck Adicional: você pode descartar 1 card; adicione 1 Magia de Campo "Rúnika(o)" do seu Deck à sua mão. \r\nSe um ou mais outros cards que você controla seriam destruídos por um efeito de card, em vez disso, você pode banir este card que você controla. \r\nSe este card no campo for destruído em batalha ou por um efeito de card: devolva este card para o Deck Adicional.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55991637,'Tiro do Dragão',replace(replace('Se você controlar um monstro Dragão: ative 1 desses efeitos;\r\n● Cause 800 de dano ao seu oponente.\r\n● Escolha 1 monstro com 800 ou menos de DEF; destrua o alvo.','\r',char(13)),'\n',char(10)),'Cause 800 de dano ao seu oponente','Destrua 1 monstro com a face para cima no campo com 800 DEF ou menos','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55997110,'Camarartista Samurailigrante',replace(replace('Quando este card destruir um monstro do oponente em batalha e enviá-lo para o Cemitério: você pode adicionar 1 Monstro Pêndulo de Nível 5 ou mais do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Camarartista Samurailigrante" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(55998462,'Peixe Metálico','Um peixe metálico com uma barbatana afiada como uma lâmina.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56001930,'O Retorno do Normal',replace(replace('Quando exatamente 1 monstro for Invocado por Invocação-Normal ou Especial com a face para cima (exceto durante a Etapa de Dano): destrua todos os monstros no campo com ATK menor que o desse monstro. \r\nVocê só pode ativar 1 "O Retorno do Normal" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56003780,'Salamagrande Jack Jaguar',replace(replace('Se este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante. \r\nSe você controlar um Monstro Link "Salamagrande", enquanto este card estiver no seu Cemitério: você pode escolher 1 monstro "Salamagrande" no seu Cemitério, exceto "Salamagrande Jack Jaguar"; embaralhe o alvo no Deck e, se isso acontecer, Invoque este card por Invocação-Especial em uma zona sua para a qual um Monstro Link "Salamagrande" seu apontar. \r\nVocê só pode usar este efeito de "Salamagrande Jack Jaguar" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56034579,'Kimridge, o Professor da GMX',replace(replace('Você pode revelar este card na sua mão; adicione 1 "Experimento Aplicado GMX nº 55" do seu Deck ou Cemitério à sua mão e, se isso acontecer, embaralhe este card no Deck. \r\nSe este card for Invocado por Invocação-Especial por um efeito de monstro: você pode escolher 2 cards no seu Cemitério, que sejam cards "GMX" e/ou monstros Dinossauro; coloque-os no topo do seu Deck em qualquer ordem e, depois, você pode destruir 1 monstro em Posição de Ataque que seu oponente controla. \r\nVocê só pode usar cada efeito de "Kimridge, o Professor da GMX" uma vez por turno.','\r',char(13)),'\n',char(10)),'Efeito de busca','Retornar ao Deck','Destruir aquele monstro?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56043446,'Viser Des',replace(replace('Se este card for Invocado por Invocação-Normal: escolha 1 monstro que seu oponente controla; durante sua terceira Fase de Apoio depois da ativação deste efeito, destrua esse monstro. \r\nEste card não pode ser destruído em batalha enquanto o monstro alvo estiver no campo.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56043447,'Viser Des',replace(replace('Se este card for Invocado por Invocação-Normal: escolha 1 monstro que seu oponente controla; durante sua terceira Fase de Apoio depois da ativação deste efeito, destrua esse monstro. \r\nEste card não pode ser destruído em batalha enquanto o monstro alvo estiver no campo.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56049970,'Cristron Tartasiolita',replace(replace('Você pode escolher 1 card com a face para cima que você controla; você não pode Invocar monstros por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto Monstros Sincro do Tipo Máquina e, além disso, destrua esse card e, se isso acontecer, Invoque por Invocação-Especial do seu Deck 1 monstro Regulador "Cristron". \r\nVocê pode banir este card do seu Cemitério; Invoque por Invocação-Especial 1 monstro "Cristron" da sua mão. \r\nVocê só pode usar 1 efeito de "Cristron Tartasiolita" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56051086,'Número 43: Manipulador de Almas',replace(replace('3 monstros de TREVAS de Nível 2	\r\nUma vez por turno: você pode desassociar 1 Matéria Xyz deste card e, depois, escolher 1 monstro "Número" no seu Cemitério; equipe o alvo a este card. \r\nEnquanto estiver equipado com um card "Número", este card não pode ser destruído em batalha ou por efeitos de card. \r\nUma vez por turno, quando você ganhar PV (exceto durante a Etapa de Dano): você pode fazer com que este card ganhe o mesmo valor de ATK e, além disso, cause esse valor de dano ao seu oponente se este card ainda estiver com a face para cima no campo.','\r',char(13)),'\n',char(10)),'Equipar','Aumentar ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56051648,'Ovo de Aranha','Quando seu oponente declarar um ataque direto, enquanto você tiver 3 ou mais monstros Inseto no seu Cemitério: negue o ataque e, se isso acontecer, Invoque por Invocação-Especial 3 "Ficha de Aranha" (Inseto/TERRA/Nível 1/ATK 100/DEF 100) em Posição de Ataque.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56051649,'Ficha de Aranha','Invocado por Especial com o efeito "Ovo de Aranha".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56052205,'Unissapo',replace(replace('Este card pode atacar seu oponente diretamente. \r\nQuando este card atacar diretamente com sucesso, se você controlar um monstro "Sapo" diferente de "Unissapo", você pode destruir 1 Magia ou Armadilha que seu oponente controla.','\r',char(13)),'\n',char(10)),'Destrua 1 Card de Magia/Armadilha que seu oponente controla','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56058749,'Música Solfacorde',replace(replace('Ative 1 desses efeitos, de acordo com as Escalas de Pêndulo dos Cards de Monstro Pêndulo "Solfacorde" que você controla.\r\n● Ímpar: Invoque por Invocação-Especial 1 Monstro Pêndulo "Solfacorde" com a face para cima com uma Escala de Pêndulo ímpar do seu Deck Adicional.\r\n● Par: Invoque por Invocação-Especial 1 Monstro Pêndulo "Solfacorde" com a face para cima com uma Escala de Pêndulo par do seu Deck Adicional.\r\n● Par e Ímpar: escolha 1 card que seu oponente controla; destrua-o.	\r\nVocê só pode ativar 1 "Música Solfacorde" por turno.','\r',char(13)),'\n',char(10)),'Ímpar: Invocação Especial','Par: Invocação Especial','Destruir 1 card','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56058888,'Rendição Real',replace(replace('Você pode ativar este card apenas quando o seu adversário ativa um Card de Armadilha Contínua. \r\nAnule a ativação e o efeito do card e destrua-o.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56063182,'Planeta Primitivo Reichphobia',replace(replace('Quando este card for ativado: você pode adicionar 1 monstro "Espantagarra" ou "Visas Starfrost" do seu Deck à sua mão. \r\nMonstros que seu oponente controla perdem 100 de ATK/DEF para cada monstro em Posição de Defesa no campo. \r\nSe 3 ou mais monstros em Posição de Defesa estiverem no campo: você pode escolher 1 card que seu oponente controla; destrua-o. \r\nVocê só pode usar este efeito de "Planeta Primitivo Reichphobia" uma vez por turno. \r\nVocê só pode ativar 1 "Planeta Primitivo Reichphobia" por turno.','\r',char(13)),'\n',char(10)),'Adicionar 1 monstro do seu Deck à sua mão?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56074358,'Mapa Morfotrônico',replace(replace('Sempre que a posição de batalha de um monstro for alterada, coloque 1 Marcador de Morfo neste card. \r\nTodos os monstros "Morfotrônico(a)" ganham 300 de ATK para cada Marcador de Morfo neste card. \r\nQuando este card for destruído e enviado do campo para o Cemitério, você pode Invocar por Invocação-Especial 1 monstro "Morfotrônico(a)" do seu Cemitério.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56094445,'Soldado do Mecanismo Antigo','Se este card atacar, seu oponente não pode ativar quaisquer Cards de Magia/Armadilha até o final da Etapa de Dano.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56099748,'Visas Starfrost',replace(replace('Se este card estiver na sua mão: você pode escolher 1 monstro que você controla com um Tipo e Atributo diferentes que o deste card; destrua esse monstro e, se isso acontecer, Invoque este card por Invocação-Especial. \r\nVocê só pode usar este efeito de "Visas Starfrost" uma vez por turno. \r\nQuando este card destruir um monstro do oponente em batalha: você pode fazer com que este card ganhe ATK igual à metade do ATK ou DEF original desse monstro (o que for maior, em caso de empate, você seleciona).','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56100345,'Verme Cibersombrio',replace(replace('O nome deste card se torna "Dragão Cibernético" enquanto estiver no campo ou no Cemitério. \r\nSe este card estiver na sua mão ou no Cemitério e você tiver outro monstro Máquina "Ciber" no seu campo ou Cemitério: você pode enviar para o Cemitério 1 monstro "Dragão Cibernético" da sua mão ou do Deck; Invoque este card por Invocação-Especial e, depois, você pode adicionar 1 Magia/Armadilha "Ciber" do seu Cemitério à sua mão. \r\nVocê só pode usar este efeito de "Verme Cibersombrio" uma vez por Duelo.','\r',char(13)),'\n',char(10)),'','Invocação Especial','Adicionar este card à mão?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56105047,'Fantasma Gogogo',replace(replace('Se este card for Invocado por Invocação-Especial: você pode escolher 1 "Golem Gogogo" em seu Cemitério; Invoque o alvo por Invocação-Especial com a face para cima em Posição de Defesa e depois coloque este card em Posição de Defesa. \r\nVocê só pode usar o efeito de "Fantasma Gogogo" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56111151,'Margem Kyoutou',replace(replace('Sempre que um ou mais cards forem enviados do campo para o Cemitério, coloque 1 Marcador Kaiju neste card para cada card enviado (máx. 5). \r\nUma vez por turno, enquanto 3 ou mais Marcadores Kaiju estiverem neste card: você pode adicionar 1 monstro "Kaiju" do seu Deck à sua mão. \r\nSe este card seria destruído por um efeito de card, em vez disso, você pode remover 1 Marcador Kaiju deste card.','\r',char(13)),'\n',char(10)),'Remover um marcador de "Margem Kyoutou" em vez de destruí-lo?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56119752,'Cartão de Presente',replace(replace('Seu oponente descarta toda a sua mão e, depois, compra 5 cards. \r\nVocê só pode ativar 1 "Cartão de Presente" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56120475,'Armadura Sakuretsu','Quando um monstro do oponente declarar um ataque: escolha o monstro atacante; destrua o alvo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56132807,'Pequena Maga Maçã',replace(replace('Uma vez por turno, se este card for escolhido como alvo de um ataque: você pode Invocar por Invocação-Especial 1 monstro do Tipo Mago de Nível 5 ou menos da sua mão e, depois, mudar o alvo do ataque para ele e, se isso acontecer, o ATK do monstro atacante se torna metade do seu ATK atual. \r\nSe este card for destruído em batalha ou por um efeito de card: você pode escolher até 3 outros monstros "Pequena Maga" com nomes diferentes no seu Cemitério; adicione-os à sua mão.','\r',char(13)),'\n',char(10)),'Continuar escolhendo monstros para adicionar à sua mão?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56146300,'Vespabatalha - Florete, o Agressor',replace(replace('Se você não controlar nenhum monstro com a face para cima, ou os únicos monstros com a face para cima que você controlar forem monstros Insetos: você pode descartar 1 outro monstro Inseto; coloque 1 "Vento de Vespabatalha" do seu Deck, com a face para cima na sua Zona de Magias & Armadilhas e, depois, Invoque este card por Invocação-Especial da sua mão e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto monstros Insetos. \r\nVocê pode banir este card do seu Cemitério; reduza o Nível de 1 monstro Inseto que você controla em 1. \r\nVocê só pode usar cada efeito de "Vespabatalha - Florete, o Agressor" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Reduzir o Nível','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56161953,'Scripton',replace(replace('Você pode banir 1 monstro Ciberso do seu Cemitério, exceto "Scripton"; Invoque este card por Invocação-Especial da sua mão. \r\nSe este card for enviado para o Cemitério como matéria para a Invocação-Link de um monstro Ciberso: você pode escolher 1 monstro banido; embaralhe-o no Deck. \r\nVocê só pode usar cada efeito de "Scripton" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56166150,'Lumina, a Xamã Crepúsculo Luminosa',replace(replace('Uma vez por turno: você pode banir 1 monstro "Luminoso(a)" da sua mão ou do Cemitério e, depois, escolha 1 dos seus monstros "Luminoso(a)" banidos, exceto "Lumina, a Xamã Crepúsculo Luminosa"; Invoque-o por Invocação-Especial. \r\nUma vez por turno, se o efeito de outro monstro "Luminoso(a)" seu for ativado: envie os 3 cards do topo do seu Deck para o Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56174248,'Destruidor da Profecia','Se este card estiver no seu Cemitério: Você pode banir 3 Cards de Magia "Livro de Magia" do seu Cemitério; Invoque este card por Invocação-Especial do seu Cemitério.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56187077,'Proto Eneanave - "orgeIA"',replace(replace('Escala de Pêndulo = 0\r\n[ Efeito de Pêndulo ]\r\nSempre que um ou mais monstros forem virados com a face para cima, coloque 1 Marcador de E.N. neste card. \r\nVocê pode pagar 900 PV; revele 3 cards "Eneanave" do seu Deck, seu oponente elege 1 aleatoriamente para que você adicione à sua mão, embaralhe o resto no Deck. \r\nVocê só pode usar este efeito de "Proto Eneanave - "orgeIA"" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nVIRE: Destrua 1 monstro que seu oponente controla.\r\nQuando seu oponente ativar um efeito de monstro na mão (Efeito Rápido): você pode colocar este card que estiver com a face para baixo, com a face para cima em Posição de Defesa; adicione 1 card "Eneanave" do seu Deck à sua mão. \r\nVocê pode revelar este card na sua mão; Invoque por Invocação-Especial 1 monstro da sua mão com a face para baixo em Posição de Defesa. \r\nVocê não pode Invocar por Invocação-Especial no turno em que ativar este efeito, exceto com a face para baixo em Posição de Defesa.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Invocação Especial','Adicionar à mão','Destruir','','','','','','','','','','','','');
INSERT INTO texts VALUES(56196385,'Kitt da Tri-Brigada',replace(replace('Você pode banir qualquer número de monstros Besta, Besta-Guerreira e/ou Besta Alada no seu Cemitério; Invoque por Invocação-Especial 1 Monstro Link Besta, Besta-Guerreira ou Besta Alada do seu Deck Adicional, com um Valor Link igual ao número banido e, além disso, você só pode usar monstros Besta, Besta-Guerreira e Besta Alada como Matéria Link pelo resto deste turno. \r\nSe este card for enviado para o Cemitério: você pode enviar 1 card "Tri-Brigada" do seu Deck para o Cemitério, exceto "Kitt da Tri-Brigada". \r\nVocê só pode usar cada efeito de "Kitt da Tri-Brigada" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56196386,'Kitt da Tri-Brigada',replace(replace('Você pode banir qualquer número de monstros Besta, Besta-Guerreira e/ou Besta Alada no seu Cemitério; Invoque por Invocação-Especial 1 Monstro Link Besta, Besta-Guerreira ou Besta Alada do seu Deck Adicional, com um Valor Link igual ao número banido e, além disso, você só pode usar monstros Besta, Besta-Guerreira e Besta Alada como Matéria Link pelo resto deste turno. \r\nSe este card for enviado para o Cemitério: você pode enviar 1 card "Tri-Brigada" do seu Deck para o Cemitério, exceto "Kitt da Tri-Brigada". \r\nVocê só pode usar cada efeito de "Kitt da Tri-Brigada" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56198785,'Guarda Fantasma',replace(replace('Se este card for Invocado por Invocação-Especial do Cemitério: você pode escolher 1 monstro que você controla; ele não pode ser destruído em batalha ou por efeitos de card neste turno. \r\nDurante a Fase Final, se este card atualmente estiver banido e foi banido neste turno: você pode adicionar este card à sua mão. \r\nVocê só pode usar cada efeito de "Guarda Fantasma" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56208713,'Bacha, a Maestra Melodiosa',replace(replace('2 monstros "Melodiosa(o)"	\r\nEnquanto você controlar este card Invocado por Invocação-Fusão, os efeitos ativados dos seus Monstros de Fusão "Melodiosa(o)" não podem ser negados. \r\nVocê só pode usar cada um dos seguintes efeitos de "Bacha, a Maestra Melodiosa" uma vez por turno. \r\nSe este card for Invocado por Invocação-Especial: você pode Invocar por Invocação-Especial 1 monstro "Melodiosa(o)" do seu Deck. \r\nSe este card for enviado para o Cemitério: você pode escolher 1 monstro "Melodiosa(o)" no seu Cemitério, exceto "Bacha, a Maestra Melodiosa"; Invoque-o por Invocação-Especial em Posição de Defesa.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56209279,'Necromante Inférnico',replace(replace('Se este card for Invocado por Invocação-Normal: coloque este card em Posição de Defesa. \r\nUma vez por turno, se você não tiver cards na sua mão: você pode escolher 1 monstro "Inférnico(a)" no seu Cemitério, exceto "Necromante Inférnico"; Invoque-o por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Mudar para Posição de Defesa','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56223084,'Rolim de Agulhas','Se este card for enviado para o Cemitério: escolha 1 monstro com a face para cima que seu oponente controla; o alvo perde 500 de ATK.','Reduzir ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56240989,'Evoltil Casinerio',replace(replace('No final da Fase de Batalha, se este card destruiu um monstro do oponente em batalha: Você pode oferecer este card como Tributo; Invoque por Invocação-Especial 2 monstros de FOGO do Tipo Dinossauro de Nível 6 ou menos com o mesmo nome do seu Deck. \r\nSeus efeitos são negados, e eles são banidos durante a Fase Final.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56246017,'Rugido do Arquidemônio','Pague 500 PV e, depois, escolha 1 monstro "Arquidemônio" no seu Cemitério; Invoque o alvo por Invocação-Especial, mas ele não pode ser oferecido como Tributo e, além disso, ele é destruído durante a Fase Final deste turno.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56252810,'Renascimento de Ataque','Bana 1 "Ativar Modo de Ataque" do seu Cemitério e, depois, escolha 1 monstro "/Modo de Ataque" no seu Cemitério que foi Invocado anteriormente com "Ativar Modo de Ataque"; destrua todos os monstros que você controla e, se isso acontecer, Invoque o alvo por Invocação-Especial, ignorando suas condições de Invocação, mas seus efeitos são negados, ele não pode ser oferecido como Tributo e, além disso, bana-o quando ele deixar o campo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56256517,'Ledger da Prestidigitação',replace(replace('Bana, com a face para baixo, 3 cards do topo do seu Deck. \r\nDurante sua 3ª Fase de Apoio depois da ativação deste card, adicione todos os 3 cards à sua mão. \r\nVocê só pode ativar 1 "Ledger da Prestidigitação" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56260110,'Raimei','Reduza os PV do oponente em 300 pontos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56283725,'Kumootoko','Uma aranha gigante e inteligente que aprisiona seus inimigos com teias.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56286179,'Broca Sincron',replace(replace('Se um monstro do Tipo Guerreiro que você controla atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente. \r\nUma vez por turno, quando você causar dano de batalha ao seu oponente com este efeito: você pode comprar 1 card.','\r',char(13)),'\n',char(10)),'Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56292140,'Número 51: Finalizador, o Braço Forte',replace(replace('3 monstros de Nível 3	\r\nNão pode ser destruído em batalha. \r\nNo final da Etapa de Dano, se este card batalhou: você pode desassociar 1 matéria deste card; coloque 1 marcador neste card (máx. 3). \r\nNo final da Fase de Batalha, se este card batalhou e tiver 3 desses marcadores: você pode destruir todos os cards que seu oponente controla.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56294501,'Sono Sucata',replace(replace('Se seu oponente Invocar um ou mais monstros por Invocação-Normal ou Especial: você pode colocar todos os monstros com a face para baixo em Posição de Defesa que você controla, com a face para cima em Posição de Ataque. \r\nDurante a Fase Final: você pode colocar todos os monstros que você controla com a face para baixo em Posição de Defesa. \r\nVocê só pode usar cada efeito de "Sono Sucata" uma vez por turno.','\r',char(13)),'\n',char(10)),'Mudar para Posição com a face para cima','Mudar para a posição com a face para baixo','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56308388,'Ladrão do Tempo Dobrador',replace(replace('Você pode desassociar 1 matéria de qualquer Monstro Xyz que você controla; Invoque este card por Invocação-Especial da sua mão. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 card "Ladrão do Tempo" do seu Deck à sua mão, exceto "Ladrão do Tempo Dobrador". \r\nVocê só pode usar cada efeito de "Ladrão do Tempo Dobrador" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56311997,'GMX - ALLOS',replace(replace('1 monstro "GMX" + 1 monstro Dinossauro	\r\nSempre que seu oponente Invocar um ou mais monstros por Invocação-Normal ou Especial, ganhe 200 PV. \r\nVocê só pode usar cada um dos seguintes efeitos de "GMX - ALLOS" uma vez por turno. \r\nVocê pode escolher 1 monstro "GMX" ou 1 monstro Dinossauro no seu Cemitério ou banimento; Invoque-o por Invocação-Especial. \r\nEste card não pode atacar no turno em que este efeito for ativado. \r\nNo começo da Etapa de Dano, se este card batalhar um monstro do oponente: você pode destruir esse monstro.','\r',char(13)),'\n',char(10)),'','Invocação Especial','Destruir um monstro do oponente','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56321639,'Livro de Magia do Salão Estelar',replace(replace('Sempre que um Card de Magia "Livro de Magia" for ativado, coloque 1 Marcador de Magia neste card. \r\nTodos os monstros do Tipo Mago que você controla ganham 100 de ATK para cada Marcador de Magia neste card. \r\nQuando este card com um ou mais Marcadores de Magia for destruído e enviado para o Cemitério: você pode adicionar 1 monstro do Tipo Mago do seu Deck para a sua mão, cujo Nível seja menor ou igual ao número de Marcadores de Magia que estavam neste card.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56322832,'Tensei Ryu-Ge Anva',replace(replace('Escala de Pêndulo = 11\r\n[ Efeito de Pêndulo ]\r\nVocê não pode Invocar por Invocação-Pêndulo, exceto monstros "Ryu-Ge" (este efeito não pode ser negado). \r\nVocê pode negar um card ou efeito do seu oponente ativado em resposta à ativação de um dos seus Cards de Magia "Ryu-Ge" ou seus efeitos e, depois, destrua este card. \r\nVocê só pode usar este efeito de "Tensei Ryu-Ge Anva" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nVocê pode oferecer como Tributo 1 monstro "Ryu-Ge" da sua mão ou do campo, exceto "Tensei Ryu-Ge Anva"; Invoque este card por Invocação-Especial da sua mão. \r\nSe este card for Invocado por Invocação-Especial: você pode escolher 1 card no campo; destrua-o. \r\nSe este card for destruído: você pode colocar 1 Magia/Armadilha Contínua "Ryu-Ge" do seu Deck, Cemitério ou banimento, no seu campo com a face para cima. \r\nVocê só pode usar cada efeito de "Tensei Ryu-Ge Anva" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Aplicar o efeito de "Tensei Ryu-Ge Anva" para negar?','Invocação Especial','Efeito de destruição','Baixar uma Magia/Armadilha','','','','','','','','','','','');
INSERT INTO texts VALUES(56337500,'Lembrete Ciberso',replace(replace('2 monstros de Nível 3	\r\nVocê pode desassociar 1 matéria deste card e, depois, escolher 1 Magia/Armadilha "Cinet" no seu Cemitério; adicione-a à sua mão. \r\nSe este card Invocado por Invocação-Xyz for destruído em batalha, ou se ele for destruído por um efeito de card do oponente enquanto estava na Zona de Monstros do seu dono: você pode Invocar por Invocação-Especial 2 monstros Ciberso de Nível 4 com nomes diferentes do seu Deck, mas seus efeitos são negados. \r\nVocê só pode usar cada efeito de "Lembrete Ciberso" uma vez por turno e, além disso, você não pode Invocar monstros por Invocação-Especial do Deck Adicional no turno em que ativar qualquer um dos efeitos deste card, exceto monstros Ciberso.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56339050,'Rugido do Imortal Terrestre',replace(replace('Uma vez por turno, se um monstro do oponente declarar um ataque: escolha o monstro atacante; destrua o alvo e, se isso acontecer, cause dano ao seu oponente igual à metade do ATK do monstro destruído. \r\nVocê deve controlar um monstro "Imortal Terrestre" com ATK maior que o ATK do monstro atacante para ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Destrua e cause dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56342351,'Guerreiro M nº 1','Especializado em ataques combinados, este guerreiro usa magnetismo para impedir a fuga do inimigo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56343672,'Furão de Socorro',replace(replace('Você pode embaralhar este card que você controla no Deck; Invoque por Invocação-Especial um ou mais monstros do seu Deck, exceto "Furão de Socorro", cuja soma dos Níveis seja igual a 6, em uma ou mais zonas suas para as quais um ou mais Monstros Link apontarem, mas esses monstros Invocados têm seus efeitos negados e, além disso, destrua-os durante a Fase Final. \r\nVocê só pode usar este efeito de "Furão de Socorro" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56346071,'Cinco Tótens','Se 5 monstros forem Invocados por Invocação-Especial ao mesmo tempo, incluindo este card: destrua tantos cards que seu oponente controla quanto possível e, se isso acontecer, cause 500 de dano ao seu oponente para cada card destruído.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56347375,'Ignis Fênix, o Dracossassino',replace(replace('Escala de Pêndulo = 7\r\n[ Efeito de Pêndulo ]\r\nDurante sua Fase Principal: você pode embaralhar no Deck 1 Monstro Pêndulo com a face para cima do seu Deck Adicional e, depois, adicione 1 monstro "Dracossassino" ou "Cavaleirardor" que não seja Pêndulo do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Ignis Fênix, o Dracossassino" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\n(Este card deve ser sempre considerado como um card "Cavaleirardor".)	\r\nSe este card no campo for destruído em batalha ou por um efeito de card: você pode Invocar por Invocação-Especial 1 monstro "Dracossassino" ou "Cavaleirardor" do seu Deck, exceto "Ignis Fênix, o Dracossassino" e, se isso acontecer, ele é considerado como um Regulador. \r\nVocê só pode usar este efeito de "Ignis Fênix, o Dracossassino" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56350972,'Saffira, a Rainha dos Dragões',replace(replace('Você pode Invocar este card por Invocação-Ritual com "Hino da Luz". \r\nDurante a Fase Final, se este card foi Invocado por Invocação-Ritual neste turno ou se um monstro de LUZ foi enviado da mão ou Deck para o Cemitério neste turno enquanto este card estava com a face para cima no campo: você pode ativar 1 desses efeitos;\r\n● Compre 2 cards e, depois, descarte 1 card.\r\n● Descarte 1 card aleatório da mão do seu oponente.\r\n● Adicione 1 monstro de LUZ do seu Cemitério à sua mão.	\r\nVocê só pode usar este efeito de "Saffira, a Rainha dos Dragões" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar o efeito escolhido','Compre 2 cards, depois descarte 1 card','Descarte aleatoriamente 1 card da mão do seu oponente','Adicione à sua mão 1 monstro de LUZ do seu Cemitério','','','','','','','','','','','','');
INSERT INTO texts VALUES(56364287,'Dragão Cibernético Herz',replace(replace('O nome deste card se torna "Dragão Cibernético" enquanto estiver no campo ou no Cemitério. \r\nVocê só pode usar 1 dos seguintes efeitos de "Dragão Cibernético Herz" por turno e apenas uma vez por turno.\r\n● Se este card for Invocado por Invocação-Especial: você pode fazer com que o Nível deste card se torne 5 até o final deste turno e, além disso, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros Máquina.\r\n● Se este card for enviado para o Cemitério: você pode adicionar 1 outro "Dragão Cibernético" do seu Deck ou Cemitério à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56369281,'Lobo Manejador de Machado','Depois que a batalha começa, este monstro ataca ferozmente e não consegue parar.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56387350,'Bebê Vampiro','No final da Fase de Batalha, se este card destruiu um monstro em batalha e o enviou para o Cemitério neste turno: você pode Invocar esse monstro por Invocação-Especial no seu campo.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56399890,'Catsith, o Mitológico','Se este card for descartado para o Cemitério: escolha 1 card com a face para cima no campo; destrua o alvo.','Destrua 1 card com a face para cima','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56401775,'Melffy Pony',replace(replace('Se seu oponente Invocar um ou mais monstros por Invocação-Normal ou Especial (exceto durante a Etapa de Dano), ou se um monstro do oponente escolher este card como alvo de um ataque: você pode devolver este card para a mão e, depois, você pode adicionar 1 monstro Besta de Nível 2 ou menos do seu Cemitério à sua mão, exceto "Melffy Pony". \r\nDurante sua Fase Final: você pode Invocar este card por Invocação-Especial da sua mão. \r\nVocê só pode usar cada efeito de "Melffy Pony" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Adicionar à sua mão uma card do Cemitério?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56410040,'Corredor Sucata','Se você não controlar nenhum monstro, você pode Invocar este card por Invocação-Especial (da sua mão).','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56410769,'Pássaro Ondulado',replace(replace('2 monstros de Nível 1	\r\nVocê pode desassociar 1 matéria deste card e, depois, escolha 1 monstro no campo; mude sua posição de batalha. \r\nEnquanto todos os monstros que você controla estiverem em Posição de Ataque, eles ganham 500 de ATK. \r\nEnquanto todos os monstros que você controla estiverem em Posição de Defesa, seu oponente não pode declarar um ataque.','\r',char(13)),'\n',char(10)),'Alterar posição de batalha','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56413937,'Guerreira da Tradição','"Donzela Sônica" + "Decapitadora Fatal"','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56421754,'U.A. Rebatedor Poderoso',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) ao devolver 1 monstro "U.A." que você controla para a mão, exceto "U.A. Rebatedor Poderoso". \r\nVocê só pode Invocar "U.A. Rebatedor Poderoso" por Invocação-Especial desta forma uma vez por turno. \r\nSe este card atacar, seu oponente não pode ativar cards ou efeitos até o final da Etapa de Dano.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56427559,'Engenhoca Marionete Cambia Mecanismo',replace(replace('Não pode ser Invocado por Invocação-Especial do Deck. \r\nUma vez por turno: você pode escolher 1 monstro "Engenhoca Marionete" que você controla, exceto este card; o Nível deste card se torna o Nível desse monstro.','\r',char(13)),'\n',char(10)),'Alterar Nível','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56433456,'O Santuário no Céu','O dano de batalha causado ao controlador de um monstro Fada de uma batalha envolvendo esse monstro se torna 0.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56460688,'Porta para uma Dimensão Diferente',replace(replace('Ative este card ao escolher 1 monstro em cada campo; bana os alvos. \r\nQuando este card for destruído e enviado para o Cemitério: devolva os monstros banidos para o campo nas mesmas posições de batalha que estavam antes.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56461575,'Espiral Renascido',replace(replace('Escolha 1 monstro Dragão de Nível 7 ou menos no seu Cemitério; Invoque-o por Invocação-Especial. \r\nSe você Invocou por Invocação-Especial um "Gaia, o Matador de Dragões" com este efeito, seu oponente não pode escolhê-lo como alvo de efeitos de card e ele não pode ser destruído pelos efeitos de card dele. \r\nVocê só pode ativar 1 "Espiral Renascido" por turno.','\r',char(13)),'\n',char(10)),'O efeito de "Espiral Renascido" está sendo aplicado.','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56465981,'Emergência Espadalma',replace(replace('Adicione 1 monstro "Espadalma" do seu Deck à sua mão ou, se você controlar um Monstro Sincro, em vez disso, você pode adicionar 1 monstro Wyrm. \r\nSe este card for banido: você pode escolher 1 monstro "Espadalma", ou monstro Wyrm, que você controla; aumente ou diminua o Nível dele em 1 até o final deste turno. \r\nVocê só pode usar cada efeito de "Emergência Espadalma" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Aumentar o Nível','Reduzir o Nível','','','','','','','','','','','','');
INSERT INTO texts VALUES(56495147,'Espadalma de Taia',replace(replace('Você pode banir 1 card "Espadalma" ou 1 monstro Wyrm do seu Cemitério; Invoque por Invocação-Especial 1 "Ficha de Espadalma" (Wyrm/Regulador/ÁGUA/Nível 4/ATK 0/DEF 0). \r\nEnquanto essa Ficha estiver na Zona de Monstros, o duelista que a Invocou não pode Invocar do Deck Adicional por Invocação-Especial, exceto Monstros Sincro. \r\nSe este card for enviado para o Cemitério como Matéria Sincro: você pode enviar 1 card "Espadalma" ou 1 monstro Wyrm do seu Deck para o Cemitério. \r\nVocê só pode usar cada efeito de "Espadalma de Taia" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56495148,'Ficha de Espadalma','Invocado por Especial com o efeito de um card "Espadalma".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56499179,'Genro Ryu-Ge Hakva',replace(replace('Você pode banir este card da sua mão; adicione 1 "Reino Ryu-Ge - Ventos Wyrm" do seu Deck à sua mão. \r\nSe um monstro for banido com a face para cima, este card já estiver banido e agora houver pelo menos 2 outros monstros banidos que não forem "Genro Ryu-Ge Hakva" (exceto durante a Etapa de Dano): você pode Invocar este card banido por Invocação-Especial. \r\nVocê pode colocar 1 "Reino Ryu-Ge - Ventos Wyrm" que você controla no fundo do Deck; adicione 1 card "Ryu-Ge" do seu Deck, Cemitério ou banimento à sua mão, exceto "Genro Ryu-Ge Hakva". \r\nVocê só pode usar cada efeito de "Genro Ryu-Ge Hakva" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Invocar por Invocação Especial um monstro banido','Adicione à sua mão 1 card "Ryu-Ge" do seu Deck, Cemitério ou banidos','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56506740,'Senhorial Veio Primita',replace(replace('Quando este card for ativado: adicione 1 card "Primita" do seu Deck à sua mão, exceto "Senhorial Veio Primita". \r\nVocê pode declarar 1 nome de Card de Monstro Normal; Invoque por Invocação-Especial 1 Monstro Normal declarado da sua mão, do Deck ou do Cemitério em Posição de Defesa e, além disso, neste turno, você não pode ativar os efeitos de monstros no campo Invocados por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Senhorial Veio Primita" uma vez por turno. \r\nMonstros Normais e monstros "Primita" que você controla ganham 300 de ATK para cada Monstro Normal com nomes diferentes no seu Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56510115,'Sinfonia Solfacorde',replace(replace('Aplique esses efeitos, em sequência, de acordo com o número de Monstros Pêndulo "Solfacorde" com a face para cima com nomes diferentes no seu Deck Adicional.\r\n● 3+: Neste turno, Monstros Pêndulo "Solfacorde" que você controla ganham ATK igual à sua própria Escala de Pêndulo x 300.\r\n● 5+: Você pode destruir 1 card que seu oponente controla e, depois, se você tiver uma Escala de Pêndulo ímpar na sua Zona de Pêndulo, compre 1 card.\r\n● 7+: Você pode Invocar por Invocação-Especial 1 monstro "MaiorSolfacorde" do seu Deck Adicional.	\r\nVocê só pode ativar 1 "Sinfonia Solfacorde" por turno.','\r',char(13)),'\n',char(10)),'','Destruir 1 card que seu oponente controla?','Invocar por Invocação Especial do Deck Adicional?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56511382,'Vulcanhão Aliado Genex','Uma vez por turno, você pode enviar 1 monstro "Genex" de FOGO com a face para cima que você controla ao Cemitério para selecionar 1 monstro com a face para cima que seu oponente controla, destrua-o e cause dano ao seu oponente igual ao Nível do monstro destruído x 400.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56514812,'Kunoichi','Quando o controle deste card com a face para cima mudar, seu novo controlador descarta 1 card aleatório.','Descartar 1 card','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56518311,'Metalmorfose Voraz',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nSe um ou mais monstros que você controla forem destruídos por um efeito de card (exceto durante a Etapa de Dano): você pode adicionar 1 card "Metalmorfose" do seu Cemitério à sua mão, exceto "Metalmorfose Voraz". \r\nVocê só pode usar este efeito de "Metalmorfose Voraz" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nEnquanto este card estiver na sua mão: você pode escolher 2 cards com a face para cima que você controla, incluindo um card "Metalmorfose"; destrua-os e, se isso acontecer, Invoque este card por Invocação-Especial da sua mão. \r\nSe este card for Invocado por Invocação-Especial pelo efeito de um card "Metalmorfose": você pode escolher 1 monstro que seu oponente controla ou no Cemitério dele; bana-o. \r\nVocê só pode usar cada efeito de monstro de "Metalmorfose Voraz" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Destruir e Invocar por Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56524813,'Eria Furiosa','Uma vez por turno: você pode oferecer como Tributo 1 outro monstro de ÁGUA; Invoque por Invocação-Especial 1 monstro de ÁGUA da sua mão, mas destrua-o quando um "Eria Furiosa" com a face para cima que você controla deixar o campo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56526564,'Livrar-se do Buraco Armadilha','Quando um Monstro Link for Invocado por Invocação-Link: destrua todos os monstros no campo que não estiverem linkados.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56532353,'Neo Dragão Definitivo de Olhos Azuis',replace(replace('"Dragão Branco de Olhos Azuis" + "Dragão Branco de Olhos Azuis" + "Dragão Branco de Olhos Azuis"	\r\nNo final da Etapa de Dano, se este card Invocado por Invocação-Fusão atacou e este for o único card com a face para cima que você controla: você pode enviar 1 Monstro de Fusão "Olhos Azuis" do seu Deck Adicional para o Cemitério; este card pode atacar novamente em seguida. \r\nVocê pode usar este efeito de "Neo Dragão Definitivo de Olhos Azuis" duas vezes por turno. \r\nQuando um card ou efeito for ativado que escolha como alvo um ou mais monstros "Olhos Azuis" que você controla (Efeito Rápido): você pode banir este card do seu Cemitério; negue a ativação e, se isso acontecer, destrua esse card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56532632,'Cavalheirismo',replace(replace('Só pode ser ativado durante a Fase de Batalha, quando o efeito de um Monstro de Efeito do oponente for ativado. \r\nNegue a ativação e destrua esse card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56535497,'Selvageria',replace(replace('Uma vez por turno, durante sua Fase Principal ou a Fase de Batalha do seu oponente, você pode selecionar 2 monstros do Tipo Besta com a face para cima no campo. \r\nAté o final do turno, 1 dos monstros selecionados perde metade do seu ATK, e o outro monstro ganha uma quantidade igual de ATK.','\r',char(13)),'\n',char(10)),'Usar o efeito de "Selvageria" agora?','Alterar ATK','Escolha o monstro cujo ATK é reduzido pela metade','Escolha o monstro cujo ATK aumentará','','','','','','','','','','','','');
INSERT INTO texts VALUES(56562619,'Ninja do Dragão Negro',replace(replace('Não pode ser Invocado por Invocação-Especial, exceto pelo efeito de um monstro "Ninja" ou card "Ninjitsu". \r\nUma vez por turno, durante o turno de qualquer duelista: você pode enviar para o Cemitério 1 monstro "Ninja" e 1 card "Ninjitsu" da sua mão e/ou com a face para cima no seu lado do campo e, depois, escolher 1 monstro no campo; bana-o. \r\nSe este card com a face para cima deixar o campo: Invoque por Invocação-Especial tantos monstros banidos pelo efeito deste card quanto possível aos campos dos seus donos.','\r',char(13)),'\n',char(10)),'Banir 1 card','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56570271,'HERÓI do Destino - Comandante dos Discos',replace(replace('Não pode ser Invocado por Invocação-Especial do Cemitério no turno em que este card foi enviado para o Cemitério. \r\nSe este card for Invocado por Invocação-Especial do Cemitério: você pode comprar 2 cards. \r\nVocê só pode usar este efeito de "HERÓI do Destino - Comandante dos Discos" uma vez por Duelo.','\r',char(13)),'\n',char(10)),'Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56574543,'Bujingi Sinyou',replace(replace('Durante a Etapa de Dano de qualquer duelista, se um monstro "Bujin" do Tipo Besta-Guerreira que você controla batalhar um monstro do oponente: você pode banir este card do seu Cemitério; até o final da Etapa de Dano, esse monstro que você controla ganha ATK igual ao ATK atual do monstro do oponente que ele estiver batalhando e, se isso acontecer, todo dano de batalha que seu oponente sofrer dessa batalha é diminuído pela metade. \r\nVocê só pode usar este efeito de "Bujingi Sinyou" uma vez por turno.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56577312,'Wattrem',replace(replace('Adicione cards "Watt" com nomes diferentes do seu Deck à sua mão, exceto "Wattrem", até o número de monstros Trovão que você controla com nomes diferentes. \r\nDurante sua Fase Principal, exceto no turno em que este card foi enviado para o Cemitério: você pode banir este card do seu Cemitério; Invoque por Invocação-Especial tantos monstros "Watt" quanto possível com nomes diferentes da sua mão. \r\nVocê só pode usar cada efeito de "Wattrem" uma vez por turno.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56585883,'Harpia Harpista',replace(replace('O nome deste card se torna "Lady Harpia" enquanto estiver no campo ou no Cemitério. \r\nVocê só pode usar cada um desses efeitos de "Harpia Harpista" uma vez por turno.\r\n● Quando este card for Invocado por Invocação-Normal: você pode escolher 1 outro monstro Besta Alada que você controla e 1 monstro com a face para cima que seu oponente controla; devolva-os para a mão.\r\n● Durante a Fase Final, se este card estiver no Cemitério porque foi enviado para lá neste turno: você pode adicionar 1 monstro Besta Alada de Nível 4 com 1500 ou menos de ATK do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Retornar à mão','Procurar no Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56588755,'Gênesis Dogmatika',replace(replace('Escolha 1 Monstro de Fusão, Sincro, Xyz ou Link banido e 1 Monstro de Efeito que seu oponente controla do mesmo tipo (Fusão, Sincro, Xyz ou Link); devolva esse monstro banido para o Deck Adicional e, se isso acontecer, negue os efeitos desse monstro que seu oponente controla. \r\nVocê só pode ativar 1 "Gênesis Dogmatika" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56594520,'Poder de Gaia','Aumente em 500 o ATK de todos os monstros de TERRA e diminua em 400 suas DEF.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56597272,'Nuviano - Nuvem de Ovelha',replace(replace('Se este card for destruído em batalha e enviado para o Cemitério: Invoque por Invocação-Especial 2 "Ficha de Nuviano" (Fada/ÁGUA/Nível 1/ATK 0/DEF 0) em Posição de Defesa. \r\nEssas Fichas não podem ser oferecidas como Tributo para uma Invocação-Tributo, exceto para monstros "Nuviano".','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56597273,'Ficha de Nuviano','Invocado por Especial com o efeito "Nuviano - Nuvem de Ovelha". Esta Ficha não pode ser oferecida como Tributo para uma Invocação-Tributo, a menos que seja para um monstro "Nuviano".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56605802,'Grilo Fantasmagórico','VIRE: Devolva 1 monstro com a face para baixo no campo para o topo do Deck do seu dono.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56606928,'Aridez Eterna','Destrua todos os monstros do Tipo Peixe com a face para cima no campo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56611470,'Liberar Artefatos',replace(replace('Escolha 2 monstros "Artefato" que você controla; imediatamente depois de resolver este efeito, Invoque por Invocação-Xyz 1 Monstro Xyz usando apenas esses 2 monstros e, além disso, pelo resto deste turno depois que este card resolver, os monstros que você controla não podem atacar, exceto monstros "Artefato". \r\nSe este card em posse do seu dono for destruído por um card do oponente: você pode revelar 1 monstro de LUZ de Nível 5 da sua mão; compre 1 card.','\r',char(13)),'\n',char(10)),'Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56619314,'D/D/D Pendragon, o Rei dos Dragões',replace(replace('Se este card estiver na sua mão: você pode oferecer como Tributo 1 monstro do Tipo Dragão e 1 outro monstro do Tipo Demônio da sua mão e/ou do seu lado do campo; Invoque este card por Invocação-Especial. \r\nUma vez por turno: você pode descartar 1 card; este card ganha 500 de ATK e, depois, você pode destruir 1 Card de Magia/Armadilha no campo. \r\nEsse aumento de ATK dura até o final deste turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Aumentar ATK','Destruir 1 Magia/Armadilha no campo?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56619778,'Lirilusc - Golpe do Pássaro',replace(replace('Se você controlar um monstro "Lirilusc": até o final deste turno, negue os efeitos de todos os monstros com a face para cima que seu oponente controla atualmente. \r\nVocê só pode ativar 1 "Lirilusc - Golpe do Pássaro" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56638325,'Cavaleirostelar Delteros',replace(replace('3 monstros de Nível 4	\r\nEnquanto este card tiver matéria, seu oponente não pode ativar cards ou efeitos quando você Invoca um ou mais monstros por Invocação-Normal ou Especial. \r\nUma vez por turno: você pode desassociar 1 matéria deste card e, depois, escolha 1 card no campo; destrua-o. \r\nSe este card for enviado do campo para o Cemitério: você pode Invocar por Invocação-Especial 1 monstro "Cavaleirost" da sua mão ou do Deck.','\r',char(13)),'\n',char(10)),'Destruir 1 card','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56638326,'Cavaleirostelar Delteros',replace(replace('3 monstros de Nível 4	\r\nEnquanto este card tiver matéria, seu oponente não pode ativar cards ou efeitos quando você Invoca um ou mais monstros por Invocação-Normal ou Especial. \r\nUma vez por turno: você pode desassociar 1 matéria deste card e, depois, escolha 1 card no campo; destrua-o. \r\nSe este card for enviado do campo para o Cemitério: você pode Invocar por Invocação-Especial 1 monstro "Cavaleirost" da sua mão ou do Deck.','\r',char(13)),'\n',char(10)),'Destruir 1 card','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56641453,'Véu de Casulo',replace(replace('Ative ao oferecer como Tributo 1 monstro "Crisálida" com a face para cima. \r\nNeste turno, qualquer dano a um duelista causado por um efeito se torna 0. \r\nInvoque por Invocação-Especial 1 monstro "Neoespacial" escrito no monstro "Crisálida" que você ofereceu como Tributo da sua mão, Deck ou do Cemitério de qualquer duelista.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56647086,'Invasor das Trevas','Seu oponente não pode ativar Cards de Magia Rápida.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56649609,'Dragão Fantasma Espiral','Uma serpente feroz que foi caçada pelos Atlantes. Cansada e destroçada pela batalha, ela chegou a uma luz antiga e encontrou novas forças para continuar sua batalha. Com seu poder aprimorado, ela iniciou uma invasão no território inimigo com um ataque renovado.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56651978,'Regina de Elfnota',replace(replace('Se este card estiver na sua mão (Efeito Rápido): você pode enviar 1 outro card "Elfnota" da sua mão ou do campo com a face para cima para o Cemitério; Invoque este card por Invocação-Especial. \r\nSe este card for Invocado por Invocação-Normal ou Especial na Zona de Monstros Principal central: você pode Invocar por Invocação-Especial 1 monstro "Elfnota" do seu Deck, exceto "Regina de Elfnota". \r\nSe este card for enviado para o Cemitério como Matéria Sincro: você pode adicionar este card à sua mão. \r\nVocê só pode usar cada efeito de "Regina de Elfnota" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Invocação Especial','Retornar para a mão','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56655675,'Besta Espiritual Ulti-Gaiapeleão',replace(replace('1 monstro "Besta Espiritual Ulti" + 1 monstro "Domador da Besta Espiritual" + 1 monstro "Avatar da Besta Espiritual"	\r\nDeve ser Invocado por Invocação-Especial (do seu Deck Adicional) ao banir os cards acima que você controla. \r\nSe Invocado desta forma, este card ganha este efeito.\r\n● Quando um Card de Magia/Armadilha, ou efeito de monstro, for ativado (Efeito Rápido): você pode banir 1 card "Besta Espiritual" da sua mão; negue a ativação e, se isso acontecer, destrua-o.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56673112,'Guarda-costas Imperiais',replace(replace('Se você não controlar nenhum outro monstro: você pode oferecer este card como Tributo; pegue 2 monstros diferentes do seu Deck entre "O Cavaleiro da Rainha", "O Cavaleiro do Rei" e/ou "O Cavaleiro do Valete" e, para cada um, adicione-o à sua mão ou Invoque-o por Invocação-Especial. \r\nVocê só pode usar este efeito de "Guarda-costas Imperiais" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Adicionar um monstro dentre eles à sua mão?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56673480,'Contrato com Don Mil',replace(replace('Quando este card for ativado: os dois duelistas perdem 1000 PV e, se isso acontecer, cada um compra 1 card. \r\nTodos os cards que forem comprados enquanto o efeito deste card estiver ativo devem permanecer revelados. \r\nEnquanto um Card de Magia de um duelista na mão dele estiver revelado por este efeito, esse duelista não pode Invocar monstros por Invocação-Normal/Baixar. \r\nVocê só pode ativar 1 "Contrato com Don Mil" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56675280,'Camarartista Papagaiada',replace(replace('Escala de Pêndulo = 2\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno, se você controlar um card "Camarartista", "Mago" ou "Olhos Anômalos" na sua outra Zona de Pêndulo, exceto "Camarartista Papagaiada": você pode fazer com que a Escala de Pêndulo deste card se torne 7 até o final deste turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nQuando este card for destruído em batalha: você pode Invocar por Invocação-Especial 1 monstro "Camarartista" do seu Deck, exceto um Monstro Pêndulo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56677752,'Mordomo Camarartista de Olhos Anômalos',replace(replace('Escala de Pêndulo = 2\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno, quando um monstro do oponente declarar um ataque: você pode adicionar 1 Monstro Pêndulo "Olhos Anômalos" do seu Cemitério ao Deck Adicional com a face para cima e, se isso acontecer, negue o ataque e, depois, você pode ganhar PV igual ao ATK desse Monstro Pêndulo.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe este card estiver na sua mão ou no Cemitério: você pode escolher 1 Card de Monstro "Camarartista" ou "Olhos Anômalos" que você controla, exceto "Mordomo Camarartista de Olhos Anômalos"; Invoque este card por Invocação-Especial e, depois, destrua esse card. \r\nVocê só pode usar este efeito de "Mordomo Camarartista de Olhos Anômalos" uma vez por turno. \r\nSe este card na Zona de Monstros for destruído: você pode colocar este card na sua Zona de Pêndulo.','\r',char(13)),'\n',char(10)),'Escolha 1 card para adicionar ao Deck Adicional','Ganhar PV?','Invocar por Invocação Especial, depois destruir','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56681873,'Terratigre, o Guerreiro Edificado','Quando este card for Invocado por Invocação-Normal: você pode Invocar por Invocação-Especial 1 Monstro Normal de Nível 4 ou menos da sua mão em Posição de Defesa.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56700100,'Minha Amiga Purrely',replace(replace('Você pode pagar 500 PV; revele 3 cards "Purrely" do seu Deck, exceto "Minha Amiga Purrely", e seu oponente elege 1 aleatoriamente para que você adicione à sua mão e, além disso, embaralhe o resto no seu Deck. \r\nSe um ou mais Monstros Xyz "Purrely" com a face para cima que você controla deixarem o campo devido a um card do oponente, mesmo durante a Etapa de Dano: você pode adicionar até 3 Magias Rápidas "Purrely" com nomes diferentes do seu Cemitério à sua mão. \r\nVocê só pode usar cada efeito de "Minha Amiga Purrely" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56704140,'Geomante da Barreira de Gelo','Uma vez enquanto estiver com a face para cima no campo: você pode descartar 1 card e declarar 1 Atributo; monstros com esse Atributo declarado não podem escolher este card como alvo de ataques.','Não pode ser selecionado como alvo de ataque','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56713174,'Negrodragão do Trovão',replace(replace('(Efeito Rápido): você pode descartar este card; adicione 1 "Negrodragão do Trovão" do seu Deck à sua mão. \r\nSe este card for banido ou enviado do campo para o Cemitério: você pode adicionar 1 card "Dragão do Trovão" do seu Deck à sua mão, exceto "Negrodragão do Trovão". \r\nVocê só pode usar 1 efeito de "Negrodragão do Trovão" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56713552,'Marmota Obesa da Maldade','Um patife mal-educado que enfiará os dentes em qualquer coisa.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56725612,'Baile da Cauda de Fadas',replace(replace('Quando este card for ativado: você pode adicionar 1 monstro "Cauda de Fadas" ou 1 "Conto de Fadas de Caudas" do seu Deck ou banimento à sua mão. \r\nSeus monstros "Cauda de Fadas" podem atacar diretamente. \r\nUma vez por turno, se seu oponente Invocar um ou mais monstros por Invocação-Especial e você controlar um monstro "Cauda de Fadas" (exceto durante a Etapa de Dano): você pode escolher 1 Monstro de Efeito que seu oponente controla; negue seus efeitos e, além disso, o nome dele se torna "Príncipe das Fadas". \r\nVocê só pode ativar 1 "Baile da Cauda de Fadas" por turno.','\r',char(13)),'\n',char(10)),'Adicionar este card à mão?','Alterar o nome do card','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56727340,'Intensificador Samurai Superpesado Alma Gaia',replace(replace('Você pode escolher 1 monstro "Samurai Superpesado" que você controla; equipe este card da sua mão ou do campo a esse monstro que você controla. \r\nO monstro equipado é considerado como um Regulador. \r\nSe você não tiver Magias/Armadilhas no seu Cemitério e este card foi equipado a um monstro pelo efeito deste card: você pode Invocar este card equipado por Invocação-Especial. \r\nVocê só pode usar este efeito de "Intensificador Samurai Superpesado Alma Gaia" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56733747,'Homem-Alado Neos Brilhante, o HERÓI do Elemento',replace(replace('"Neos, o HERÓI do Elemento" + 1 Monstro de Fusão "Homem-Alado"	\r\nDeve ser Invocado por Invocação-Fusão. \r\nGanha 300 de ATK para cada monstro no seu Cemitério e, além disso, não pode ser destruído por efeitos de card. \r\nSe este card for Invocado por Invocação-Especial: você pode destruir cards que seu oponente controla até o número de Atributos diferentes entre os monstros no campo. \r\nVocê só pode usar este efeito de "Homem-Alado Neos Brilhante, o HERÓI do Elemento" uma vez por turno. \r\nSe este card destruir um monstro em batalha: cause dano ao seu oponente igual ao ATK original desse monstro.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56741506,'Força Celeste - Ás - Azalea Temperança',replace(replace('2+ monstros, incluindo um Monstro Link	\r\nPrimeiro deve ser Invocado por Invocação-Link. \r\nSe este card for Invocado por Invocação-Especial: você pode banir 1 Magia da sua mão ou do Cemitério e, depois, escolha 1 monstro que seu oponente controla com 2500 ou menos de ATK; equipe esse monstro com a face para cima a este card como uma Magia de Equipamento. \r\nVocê só pode usar este efeito de "Força Celeste - Ás - Azalea Temperança" uma vez por turno. \r\nQuando este card for destruído em batalha: você pode Invocar por Invocação-Especial 1 outro monstro "Força Celeste" da sua mão ou do Cemitério.','\r',char(13)),'\n',char(10)),'Considerar como um Card de Equipamento','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56746202,'Quimera de Restolhos',replace(replace('Não pode ser usado como Matéria Sincro, exceto para a Invocação-Sincro de um monstro "Restolhos", e todas as outras matérias devem ser monstros "Restolhos". \r\nQuando este card for Invocado por Invocação-Normal: você pode escolher 1 Regulador "Restolhos" no seu Cemitério; Invoque o alvo por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Invocação Especial','Usar "Quimera de Restolhos" como Matéria Sincro?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56747793,'Juntos Resistiremos','O monstro equipado ganha 800 de ATK/DEF para cada monstro com a face para cima que você controla.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56768355,'Alfa Vylon',replace(replace('1 Regulador "Vylon" + 1 ou mais monstros não-Reguladores	\r\nQuando este card for Invocado por Invocação-Sincro: Você pode escolher 1 Card de Magia de Equipamento no seu Cemitério; equipe o alvo a este card. \r\nEnquanto este card estiver equipado com um Card de Equipamento, ele não pode ser destruído por efeitos de Magia/Armadilha, exceto por Cards de Equipamento.','\r',char(13)),'\n',char(10)),'Equipar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56769674,'Transplante de DNA',replace(replace('Ative ao declarar 1 Atributo de monstro. \r\nTodos os monstros com a face para cima se tornam desse Atributo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56773577,'Templo de Necro-Vale',replace(replace('Enquanto um ou mais monstros "do Coveiro" e "Necro-Vale" estiverem ambos no campo, os monstros que seu oponente controla perdem 500 de ATK/DEF. \r\nUma vez por turno, durante a Fase Principal, se você não controlar nenhum card na sua Zona do Campo: você pode ativar 1 "Necro-Vale" diretamente da sua mão ou do Cemitério. \r\nSe este card em sua posse for destruído por um efeito do oponente e enviado para o seu Cemitério: você pode Baixar 1 Magia/Armadilha "Necro-Vale" diretamente do seu Deck, exceto "Templo de Necro-Vale".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56784842,'Anjo O7',replace(replace('Se este card for Invocado por Invocação-Tributo, ele ganha este efeito:\r\n● Nenhum duelista pode ativar efeitos de monstro.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56787189,'Nova Fronteira',replace(replace('Se seu oponente Invocar por Invocação-Especial um ou mais Monstros de Ritual, de Fusão, Sincro, Xyz e/ou Link (exceto durante a Etapa de Dano): você pode ativar 1 desses efeitos;\r\n● Adicione 1 "Caído de Arbaz", ou 1 monstro que o mencione, do seu Deck à sua mão.\r\n● Invoque por Invocação-Especial 1 "Caído de Arbaz", ou 1 monstro que o mencione, da sua mão.	\r\nVocê só pode usar cada efeito de "Nova Fronteira" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar o efeito escolhido','Procurar no Deck','Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56787190,'Nova Fronteira',replace(replace('Se seu oponente Invocar por Invocação-Especial um ou mais Monstros de Ritual, de Fusão, Sincro, Xyz e/ou Link (exceto durante a Etapa de Dano): você pode ativar 1 desses efeitos;\r\n● Adicione 1 "Caído de Arbaz", ou 1 monstro que o mencione, do seu Deck à sua mão.\r\n● Invoque por Invocação-Especial 1 "Caído de Arbaz", ou 1 monstro que o mencione, da sua mão.	\r\nVocê só pode usar cada efeito de "Nova Fronteira" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar o efeito escolhido','Procurar no Deck','Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56789759,'Tyhone #2','Um dragão carmesim que cospe bolas de fogo para criar um resplandecente mar de fogo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56790702,'Porta-aviões de Assalto D.D.',replace(replace('Não pode declarar um ataque a não ser que você bana 1 card do seu Cemitério. \r\nSe exatamente 3 dos seus cards estiverem banidos: você pode Invocar este card por Invocação-Especial da sua mão. \r\nVocê só pode usar este efeito de "Porta-aviões de Assalto D.D." uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56804361,'Éter, o Dragão Edificante',replace(replace('Quando este card for Invocado por Invocação-Pêndulo: você pode escolher 1 card no campo; devolva-o para a mão. \r\nVocê só pode usar este efeito de "Éter, o Dragão Edificante" uma vez por turno.','\r',char(13)),'\n',char(10)),'Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56809158,'Mekk-Cavaleiro da Lua Vermelha',replace(replace('Se 2 ou mais cards estiverem na mesma coluna, você pode Invocar este card por Invocação-Especial (da sua mão) nessa coluna. \r\nVocê só pode Invocar "Mekk-Cavaleiro da Lua Vermelha" por Invocação-Especial uma vez por turno desta forma. \r\nVocê pode banir 1 monstro "Mekk-Cavaleiro" do seu Cemitério e, depois, escolha 1 monstro com a face para cima na coluna deste card; destrua-o.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56818742,'Transcendossauro Exaraptor',replace(replace('2+ monstros Dinossauro, incluindo um monstro de Nível 6 ou mais	\r\nSe este card for Invocado por Invocação-Especial: você pode Invocar por Invocação-Especial 1 monstro Dinossauro da sua mão. \r\nSe um monstro Dinossauro com a face para cima para o qual este card apontar for destruído em batalha ou enviado para o Cemitério: você pode comprar 1 card. \r\nSe este card for destruído: você pode embaralhar no Deck 1 Monstro Normal do seu Cemitério e, depois, você pode Invocar este card por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Transcendossauro Exaraptor" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','Invocar este card por Invocação Especial?','','','','','','','','','','','','');
INSERT INTO texts VALUES(56818977,'Springans Pedor',replace(replace('Você pode oferecer este card como Tributo e, depois, escolha 1 monstro "Springans" no seu Cemitério, exceto "Springans Pedor"; Invoque-o por Invocação-Especial. \r\nSe este card estiver na sua mão, no campo ou no Cemitério: você pode escolher 1 Monstro Xyz "Springans" que você controla; associe este card a ele como matéria. \r\nVocê só pode usar cada efeito de "Springans Pedor" uma vez por turno.','\r',char(13)),'\n',char(10)),'Oferecer como Tributo e Invocar por Invocação Especial','Associar Matéria Xyz','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56824871,'Infernobre Cavaleiro - Renaud',replace(replace('Se você controlar um monstro Guerreiro de FOGO, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nSe Invocado desta forma, considere este card como um Regulador. \r\nVocê só pode Invocar "Infernobre Cavaleiro - Renaud" por Invocação-Especial uma vez por turno desta forma. \r\nSe este card for Invocado por Invocação-Especial: você pode escolher 1 dos seus monstros Guerreiro de FOGO, ou 1 das suas Magias de Equipamento, que estiverem banidos ou no seu Cemitério, exceto "Infernobre Cavaleiro - Renaud"; adicione-o à sua mão. \r\nVocê só pode usar este efeito de "Infernobre Cavaleiro - Renaud" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56827051,'Ariel, a Sacerdotisa de Necroz',replace(replace('Uma vez por turno: você pode revelar um número de cards "Necroz" na sua mão; até o final deste turno, aumente ou diminua o Nível deste card pelo número revelado. \r\nSe este card for oferecido como Tributo por um efeito de card: você pode adicionar 1 monstro "Necroz" do seu Deck à sua mão, exceto um Monstro de Ritual. \r\nVocê só pode usar este efeito de "Ariel, a Sacerdotisa de Necroz" uma vez por turno.','\r',char(13)),'\n',char(10)),'Alterar Nível','Adicionar à mão','Aumentar o Nível','Reduzir o Nível','','','','','','','','','','','','');
INSERT INTO texts VALUES(56830749,'Compartilhar a Dor','Ofereça 1 monstro como Tributo; faça com que seu oponente ofereça 1 monstro como Tributo (sem obter efeitos).','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56832966,'Número S39: Utopia, o Relâmpago',replace(replace('3 monstros de LUZ de Nível 5	\r\nVocê também pode Invocar este card por Invocação-Xyz ao usar um monstro "Utopia" de Classe 4 que você controla como matéria. \r\n(Transfira as matérias dele para este card.) \r\nNão pode ser usado como matéria para uma Invocação-Xyz. \r\nSe este card batalhar, seu oponente não pode ativar cards ou efeitos até o final da Etapa de Dano. \r\nUma vez por Corrente, durante o cálculo de dano, se este card batalhar um monstro do oponente enquanto este card tiver um Monstro Xyz "Utopia" como matéria (Efeito Rápido): você pode desassociar 2 matérias deste card; o ATK deste card se torna 5000, apenas durante esse cálculo de dano.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Xyz usando o monstro "Utópico" de Classe 4 como matéria?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56838842,'Golem de Fragmento Demônio',replace(replace('Se você controlar um Regulador Demônio e este card estiver na sua mão: você pode Invocar este card por Invocação-Especial. \r\nSe este card for Invocado por Invocação-Especial: você pode reduzir o Nível dele em até 2. \r\nSe este card for enviado para o Cemitério como Matéria Sincro para "Dragão Vermelho Arquidemônio" ou um Monstro Sincro que o mencione: você pode escolher 1 monstro Demônio de Nível 4 ou menos no seu Cemitério; Invoque-o por Invocação-Especial em Posição de Defesa. \r\nVocê só pode usar cada efeito de "Golem de Fragmento Demônio" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Reduzir o Nível','Invocação Especial','Reduzir em 1 Nível','Reduzir em 2 Níveis','','','','','','','','','','','');
INSERT INTO texts VALUES(56839613,'Microcélula do Homem-Bateria',replace(replace('VIRE: Invoque por Invocação-Especial 1 monstro "Homem-Bateria" de Nível 4 ou menos do seu Deck, exceto "Microcélula do Homem-Bateria". \r\nDepois que este card for virado com a face para cima, quando ele for destruído em batalha e enviado para o Cemitério, compre 1 card.','\r',char(13)),'\n',char(10)),'Invocação Especial','Comprar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56840427,'Número C39: Raio Utopia',replace(replace('3 monstros de LUZ de Nível 4	\r\nVocê também pode Invocar este card por Invocação-Xyz ao usar um "Número 39: Utopia" que você controla como matéria. \r\n(Transfira as matérias dele para este card.) \r\nVocê pode desassociar 1 matéria deste card; ele ganha 500 de ATK até o final deste turno e, se isso acontecer, 1 monstro que seu oponente controla perde 1000 de ATK até o final deste turno. \r\nVocê deve ter 1000 PV ou menos para ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Alterar ATK','Invocar por Invocação Xyz usando "Número 39: Utopia" como matéria?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56840658,'Sapo de Ferrão Envenenado','Quando este card no Campo com a face para cima é enviado para o Cemitério (a menos que ele tenha sido atacado com a face para baixo e destruído como resultado de uma batalha), você pode comprar 1 card do seu Deck.','Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56856951,'Ardor Meteórico',replace(replace('Ative ao enviar 2 cards da sua mão para o Cemitério enquanto seu oponente tiver mais que 3000 PV. \r\nCause 2000 de dano ao seu oponente. \r\nSe este card estiver no Cemitério, você pode adicioná-lo à sua mão em vez de conduzir sua compra normal durante sua Fase de Compra.','\r',char(13)),'\n',char(10)),'Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56863746,'Drytron Meteonis DA Draconids',replace(replace('Você pode Invocar este card por Invocação-Ritual com "Drytron Meteonis". \r\nOutros monstros "Drytron" que você controla não podem ser destruídos pelos efeitos de card do seu oponente. \r\nDuas vezes por turno, quando seu oponente ativar um efeito de monstro (Efeito Rápido): você pode banir monstros "Drytron" (mín. 1) do seu Cemitério cujo ATK total seja igual ou exceda o ATK original desse monstro; negue a ativação e, se isso acontecer, destrua-o. \r\nSe este card Invocado por Invocação-Ritual sob o controle do seu dono for destruído por um card do oponente: você pode Invocar por Invocação-Especial 1 Monstro de Ritual com 4000 de ATK da sua mão ou do Deck. \r\n(Isso é considerado uma Invocação-Ritual.)','\r',char(13)),'\n',char(10)),'Não pode ser destruído','Negue seus efeitos e destrua-o','Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56870908,'Nham☆Nham☆Nhamys',replace(replace('Sempre que 2 ou mais monstros "Nhamy" forem Invocados por Invocação-Especial no seu campo ao mesmo tempo, você ganha 500 PV e, se isso acontecer, seu oponente perde 500 PV. \r\nVocê só pode usar cada um dos seguintes efeitos de "Nham☆Nham☆Nhamys" uma vez por turno. \r\nVocê pode pagar 500 PV e, depois, escolha 2 monstros com a face para cima no campo incluindo um "Nhamy★Garrinha"; envie os dois para o Cemitério e, se isso acontecer, Invoque por Invocação-Especial 1 Monstro Sincro "Nhamy" do seu Deck Adicional (isso é considerado uma Invocação-Sincro). \r\nSe seu oponente ativar um card ou efeito (exceto durante a Etapa de Dano): você pode pagar 100 PV; imediatamente depois que este efeito resolver, Invoque por Invocação-Link 1 Monstro Link "Nhamy".','\r',char(13)),'\n',char(10)),'Invocação Sincro','Invocação Link','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56894757,'Ondulação Fazticeira',replace(replace('Escolha Magias/Armadilhas que seu oponente controla, até o número de monstros "Fazticeira" que você controla; devolva esses cards escolhidos como alvo para a mão. \r\nDurante sua Fase Final, se você controlar um monstro "Fazticeira", enquanto este card estiver no seu Cemitério: você pode adicionar este card à sua mão. \r\nVocê só pode usar 1 efeito de "Ondulação Fazticeira" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56897896,'Mono Sincron',replace(replace('Quando estiver usando este card como uma Matéria Sincro, a(s) outra(s) \r\nMatéria(s) \r\nSincro deve(m) ser um() monstro(s) de Nível 4 ou menos do Tipo Guerreiro ou Máquina e ele(s) é(são) considerado(s) de Nível 1.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56907389,'Rei Músico','"Bruxa da Floresta Negra" + "Lady da Fé"','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56907986,'Espantalho de Kozmo',replace(replace('Durante o turno de qualquer duelista: você pode banir este card; Invoque por Invocação-Especial 1 monstro "Kozmo" de Nível 3 ou mais da sua mão. \r\nVocê só pode usar este efeito de "Espantalho de Kozmo" uma vez por turno. \r\nUma vez por turno: você pode pagar 500 PV e, depois, escolher 1 dos seus monstros "Kozmo" banidos; Invoque-o por Invocação-Especial, mas seus efeitos são negados e, além disso, destrua-o durante a Fase Final.','\r',char(13)),'\n',char(10)),'Invoque por Invocação Especial 1 monstro "Kozmo" da sua mão','Invoque por Invocação Especial 1 monstro "Kozmo" banido','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56910167,'Supercouraçado Canhão de Trilho',replace(replace('2 monstros de Nível 10	\r\nUma vez por turno: você pode desassociar 1 matéria deste card; cause 2000 de dano ao seu oponente.','\r',char(13)),'\n',char(10)),'Receba 2000 pontos de dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56916805,'Escoar Energia','Escolha 1 monstro com a face para cima que você controla; até o final deste turno, ele ganha 200 de ATK/DEF para cada card que seu oponente tem na mão dele atualmente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56920308,'A Criatura Definitiva da Destruição',replace(replace('Escolha 1 monstro "Olhos Azuis" que você controla; neste turno, esse monstro com a face para cima não é afetado por efeitos de card, exceto seus próprios, ele não pode ser destruído em batalha e, além disso, qualquer monstro que ele batalhar é destruído no final da Etapa de Dano. \r\nEnquanto este card estiver no seu Cemitério, se você Invocar um "Dragão Branco de Olhos Azuis" por Invocação-Normal ou Especial: você pode Baixar este card, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar este efeito de "A Criatura Definitiva da Destruição" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56921677,'Besta Heráldica Basilisco','Depois do cálculo de dano: destrua qualquer monstro do oponente que batalhou este card.','Destruir um monstro','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56931015,'Beemote de Gravidade',replace(replace('Se não for o primeiro turno do Duelo e não houver nenhum card no campo, você pode Invocar este card por Invocação-Normal sem oferecer Tributo. \r\nVocê pode destruir todos os Cards de Magia de Campo no campo. \r\nEste card não pode atacar no turno em que você ativar este efeito.','\r',char(13)),'\n',char(10)),'Invocação Normal sem Tributo','Destruir a Magia de Campo','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56948373,'Máscara dos Amaldiçoados',replace(replace('O monstro equipado não pode atacar. \r\nUma vez por turno, durante sua Fase de Apoio: cause 500 de dano ao controlador do monstro equipado.','\r',char(13)),'\n',char(10)),'Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56980148,'Dinolutador Sistegossauro',replace(replace('Se este card for Invocado por Invocação-Especial: você pode adicionar 1 monstro "Dinolutador" ou 1 "Mundo Dino Lutador" do seu Deck à sua mão. \r\nDurante a Fase Final, se este card estiver no Cemitério porque foi enviado para lá neste turno e seu oponente controlar mais monstros que você: você pode escolher 1 monstro "Dinolutador" no seu Cemitério, exceto "Dinolutador Sistegossauro"; Invoque-o por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Dinolutador Sistegossauro" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56981417,'Livro de Magia do Mestre',replace(replace('Se você controlar um monstro do Tipo Mago: você pode revelar 1 outro card "Livro de Magia" da sua mão e, depois, escolher 1 Card de Magia Normal "Livro de Magia" no seu Cemitério, exceto "Livro de Magia do Mestre"; o efeito deste card se torna o efeito do alvo. \r\nVocê só pode ativar 1 "Livro de Magia do Mestre" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56984514,'Terra Dourada Eternamente!',replace(replace('Quando um Card de Magia/Armadilha, ou efeito de monstro, for ativado, enquanto você controlar um monstro "Eldlich": ofereça como Tributo 1 monstro Zumbi; negue a ativação e, se isso acontecer, destrua esse card. \r\nVocê só pode ativar 1 "Terra Dourada Eternamente!" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56993276,'Wattcancelar','Quando seu oponente Invocaria um ou mais monstros por Invocação-Normal ou Especial: descarte 1 monstro "Watt"; negue a Invocação e, se isso acontecer, destrua esse(s) monstro(s).','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56993277,'Wattcancelar','Quando seu oponente Invocaria um ou mais monstros por Invocação-Normal ou Especial: descarte 1 monstro "Watt"; negue a Invocação e, se isso acontecer, destrua esse(s) monstro(s).','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(56995655,'Previsão Agoirenta',replace(replace('Durante a sua Standby Phase, escolha 1 card aleatoriamente da mão do seu adversário e nomei um tipo de card (Monstro, Magia, ou Armadilha). \r\nSe você o nomear corretamente, inflija 700 pontos de dano aos Life Points do seu adversário. \r\nVocê pode usar este efeito apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Adivinhar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57006589,'Monólito de Absorção Energética',replace(replace('Ative este card em Corrente a um efeito de card do oponente que causaria dano a você. \r\nO dano é negado e você ganha PV igual à quantidade que você sofreria.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57019473,'Manatrovã',replace(replace('Quando este card for Invocado por Invocação-Normal: Você pode escolher 1 monstro de LUZ do Tipo Trovão de Nível 4 com 1600 ou menos de ATK no seu Cemitério, exceto "Manatrovã"; bana o alvo. \r\nDurante a Fase Final deste turno, adicione esse card à sua mão.','\r',char(13)),'\n',char(10)),'Banir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57030525,'Dragão Armado do Trovão LV3',replace(replace('O nome deste card se torna "Dragão Armado LV3" enquanto ele estiver no campo ou no Cemitério. \r\nVocê só pode usar cada um dos seguintes efeitos de "Dragão Armado do Trovão LV3" uma vez por turno. \r\nVocê pode enviar 1 monstro da sua mão para o Cemitério; envie este card do campo para o Cemitério e, se isso acontecer, Invoque por Invocação-Especial 1 monstro "Dragão Armado" de Nível 5 ou menos da sua mão ou do Deck. \r\nSe este card for enviado para o Cemitério para ativar o efeito de um monstro Dragão: você pode comprar 1 card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57031794,'Besta Mech Super Quantal Magnaligre',replace(replace('2 monstros de Nível 5	\r\nNão pode atacar a não ser que tenha matéria. \r\nUma vez por turno: você pode desassociar 1 matéria deste card e, depois, escolher 1 monstro no campo; destrua-o. \r\nEste é um Efeito Rápido se este card tiver "Camada Vermelha Super Quantum" como matéria. \r\nUma vez por turno: você pode associar 1 monstro "Super Quantum" da sua mão ou do campo a este card como matéria.','\r',char(13)),'\n',char(10)),'Destruir um monstro','Matéria Xyz','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57036718,'Demolidor Zubaba','Se este card causar dano de batalha ao seu oponente, no final da Etapa de Dano: destrua o 1 monstro com a face para cima no campo com o menor ATK (em caso de empate, você escolhe) e, se isso acontecer, este card perde 800 de ATK.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57043117,'Soldado Gigante de Aço',replace(replace('2 monstros de Nível 3 do Tipo Rocha	\r\nEste card não é afetado por outros efeitos de monstro. \r\nUma vez por turno, durante o turno de qualquer duelista: você pode desassociar 1 Matéria Xyz deste card; ele ganha 1000 de DEF até o final deste turno e, se isso acontecer, você não sofre dano de efeito dos efeitos de card do seu oponente neste turno.','\r',char(13)),'\n',char(10)),'Aumentar DEF','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57043986,'Dragão Sólido de Olhos Azuis',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 monstro com a face para cima que seu oponente controla; negue seus efeitos. \r\nQuando seu oponente ativar um card ou efeito (Efeito Rápido): você pode embaralhar este card do campo no Deck e, se isso acontecer, Invoque por Invocação-Especial 1 "Dragão Branco de Olhos Azuis" do seu Deck. \r\nVocê só pode usar cada efeito de "Dragão Sólido de Olhos Azuis" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57046845,'Gearfried, o Mestre da Espada',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial com "Libertado". \r\nSempre que um ou mais Cards de Equipamento forem equipados a este card: escolha 1 monstro que seu oponente controla; destrua o alvo.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57047293,'Olhos do Vácuo','Invoque por Invocação-Especial 1 monstro "Infernoide" da sua mão, ignorando suas condições de Invocação, mas seus efeitos são negados até o final deste turno.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57062206,'Doitsu',replace(replace('Uma vez por turno, durante a sua Main Phase, você pode equipar este card a "Soitsu" como um Card de Equipamento, OU separar o Equipamento e Invocar, por Invocação-Especial, este card em Posição de Ataque com a face para cima. \r\nQuando este card é equipado pelo efeito deste card, aumente o ATK/DEF do monstro equipado em 2500 pontos. \r\n(1 monstro pode ser equipado apenas por 1 Monstro de Union de cada vez. Se o monstro equipado com este card é destruído como resultado de um combate, em vez disso destrua este card.)','\r',char(13)),'\n',char(10)),'Equipar','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57069605,'Alma Congelada',replace(replace('Você pode activar este card apenas quando os Life Points do seu adversário forem pelo menos 2000 pontos superiores aos seus. \r\nSalte a próxima Battle Phase do seu adversário.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57093995,'Marionete da Condolência',replace(replace('Envie monstros "Engenhoca Marionete" com nomes diferentes do seu Deck para o Cemitério, até o número de monstros que seu oponente controla que foram Invocados por Invocação-Especial do Deck Adicional +1. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 Monstro Xyz Máquina que você controla; ele não pode ser destruído pelos efeitos de card do seu oponente enquanto estiver com a face para cima no campo. \r\nVocê só pode usar cada efeito de "Marionete da Condolência" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57103969,'Formação de Fogo - Tenki',replace(replace('Quando este card for ativado: você pode adicionar 1 monstro Besta-Guerreira de Nível 4 ou menos do seu Deck à sua mão. \r\nTodos os monstros Besta-Guerreira que você controla ganham 100 de ATK. \r\nVocê só pode ativar 1 "Formação de Fogo - Tenki" por turno.','\r',char(13)),'\n',char(10)),'Adicionar à sua mão 1 monstro Besta-Guerreira de Nível 4 ou menos do seu Deck?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57103970,'Formação de Fogo - Tenki',replace(replace('Quando este card for ativado: você pode adicionar 1 monstro Besta-Guerreira de Nível 4 ou menos do seu Deck à sua mão. \r\nTodos os monstros Besta-Guerreira que você controla ganham 100 de ATK. \r\nVocê só pode ativar 1 "Formação de Fogo - Tenki" por turno.','\r',char(13)),'\n',char(10)),'Adicionar à sua mão 1 monstro Besta-Guerreira de Nível 4 ou menos do seu Deck?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57108202,'Controle Remoton Morfotrônico',replace(replace('● Posição de Ataque: Uma vez por turno: você pode escolher 1 monstro "Morfotrônico(a)" no seu Cemitério; bana o alvo e, se isso acontecer, adicione 1 monstro "Morfotrônico(a)" com o mesmo Nível do alvo do seu Deck à sua mão.\r\n● Posição de Defesa: Uma vez por turno: você pode enviar 1 monstro "Morfotrônico(a)" da sua mão para o Cemitério e, se isso acontecer, adicione 1 outro monstro "Morfotrônico(a)" com o mesmo Nível que o desse monstro do seu Cemitério à sua mão.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Recuperar do Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57111330,'Therion "Duque" Yul',replace(replace('Você só pode usar o 1º dos seguintes efeitos de "Therion "Duque" Yul" uma vez por turno.\r\n● Você pode escolher 1 monstro "Therion" ou 1 monstro Psíquico no seu Cemitério; Invoque este card por Invocação-Especial da sua mão e, se isso acontecer, equipe esse monstro a este card.\r\n● Enquanto você controlar um Card de Equipamento, monstros "Therion" que você controla não podem ser destruídos pelos efeitos de card do seu oponente.	\r\nUm monstro "Therion" equipado com este card ganha 700 de ATK e, além disso, ele ganha o 2º efeito listado acima como se fosse "Therion "Duque" Yul".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57111661,'Maliss ＜C＞ TB-11',replace(replace('Você pode ativar este card no turno em que foi Baixado, ao banir 1 monstro "Maliss" com a face para cima que você controla. \r\nInvoque por Invocação-Especial 1 monstro "Maliss" do seu Deck ou, se seu oponente controlar 3 ou mais cards, em vez disso, você pode Invocar por Invocação-Especial 1 Monstro Link "Maliss" do seu Deck Adicional. \r\nPelo resto deste turno, esse monstro Invocado não pode atacar e nenhum duelista pode ativar seus efeitos. \r\nVocê só pode ativar 1 "Maliss ＜C＞ TB-11" por turno.','\r',char(13)),'\n',char(10)),'','','Ativar aplicando o efeito de "Maliss ＜C＞ TB-11".','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57115864,'Luminescer','Quando um monstro do oponente declarar um ataque: Escolha o monstro atacante; negue o ataque, e 1 monstro de LUZ com a face para cima que você controla ganha ATK igual ao ATK do alvo até a sua próxima Fase Final.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57116033,'Kuriboh Alado','Se este card no campo for destruído e enviado para o Cemitério: pelo resto deste turno, você não sofre dano de batalha.','O dano de batalha se torna 0','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57116034,'Kuriboh Alado','Se este card no campo for destruído e enviado para o Cemitério: pelo resto deste turno, você não sofre dano de batalha.','O dano de batalha se torna 0','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57116035,'Kuriboh Alado','Se este card no campo for destruído e enviado para o Cemitério: pelo resto deste turno, você não sofre dano de batalha.','O dano de batalha se torna 0','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57134592,'Salamagrande Fênix Furiosa',replace(replace('2+ Monstros de Efeito de FOGO	\r\nSe este card for Invocado por Invocação-Link usando "Salamagrande Fênix Furiosa" como matéria: você pode adicionar 1 card "Salamagrande" do seu Deck à sua mão. \r\nSe um ou mais monstros de FOGO com a face para cima que você controla forem destruídos em batalha ou por um efeito de card enquanto este card estiver no seu Cemitério: você pode escolher 1 desses monstros; Invoque este card por Invocação-Especial e, se isso acontecer, este card ganha ATK igual ao ATK desse monstro. \r\nVocê só pode usar cada efeito de "Salamagrande Fênix Furiosa" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57135971,'Presas de Olhos Vermelhos com Correntes',replace(replace('Escolha 1 monstro "Olhos Vermelhos" que você controla; equipe este card a ele. \r\nEle pode realizar até 2 ataques contra monstros durante cada Fase de Batalha. \r\nVocê pode enviar este Card de Equipamento para o Cemitério e, depois, escolha 1 Monstro de Efeito no campo; equipe o alvo ao monstro ao qual este card estava equipado e, se isso acontecer, enquanto um monstro estiver equipado a ele por este efeito, o ATK/DEF dele se tornam iguais ao ATK/DEF originais desse monstro equipado.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57139487,'Desaparecimento em Cadeia','Quando um ou mais monstros com 1000 ou menos de ATK forem Invocados: bana esses monstros com 1000 ou menos de ATK e, depois, seu oponente bane da mão e do Deck dele todos os cards com o mesmo nome que os desses cards.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57143342,'Cir, Malebranche do Abismo Ardente',replace(replace('Se você controlar um monstro que não seja um monstro "Abismo Ardente", destrua este card. \r\nVocê só pode usar 1 desses efeitos de "Cir, Malebranche do Abismo Ardente" por turno e apenas uma vez por turno.\r\n● Se você não controlar nenhuma Magia/Armadilha: você pode Invocar este card por Invocação-Especial da sua mão.\r\n● Se este card for enviado para o Cemitério: você pode escolher 1 monstro "Abismo Ardente" no seu Cemitério, exceto "Cir, Malebranche do Abismo Ardente"; Invoque-o por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57157964,'Máquina Fóssil Comboio Caveira',replace(replace('1 monstro Rocha no seu Cemitério + 1 monstro de Nível 7 ou mais	\r\nPrimeiro deve ser Invocado por Invocação-Especial com "Fusão Fóssil". \r\nEnquanto você controlar este card Invocado por Invocação-Fusão, todos os monstros que seu oponente controla perdem ATK igual à sua DEF original. \r\nEste card pode realizar até 3 ataques contra monstros durante cada Fase de Batalha. \r\nQuando este card destruir um monstro do oponente em batalha: você pode causar 1000 de dano ao seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57160136,'Mineração Cinet',replace(replace('Envie 1 card da sua mão para o Cemitério; adicione 1 monstro Ciberso de Nível 4 ou menos do seu Deck à sua mão. \r\nVocê só pode ativar 1 "Mineração Cinet" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57182235,'Ação de Graças dos Tokens',replace(replace('Destrua todas as Fichas no Campo. \r\nAumente os seus Life Points em número de Fichas destruídos x 800 pontos.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57201737,'Juba do Dragonete-de-Leão',replace(replace('Selecione 1 monstro "Naturia" com a face para cima que você controla. \r\nSeu ATK se torna 3000, e seus efeitos são negados até a Fase Final.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57232301,'Ataque do Corte das Sombras',replace(replace('Se um ou mais cards forem banidos da mão e/ou do campo para ativar um efeito de monstro (exceto durante a Etapa de Dano): você pode aplicar 1 dos seguintes efeitos, de acordo com 1 dos tipos de card banidos.\r\n● Monstro: Negue os efeitos de 1 Magia/Armadilha com a face para cima no campo até o final deste turno.\r\n● Magia: Compre 2 cards.\r\n● Armadilha: Bana 1 monstro no campo.	\r\nSe este card for banido para ativar um efeito de monstro: você pode adicionar 1 dos seus outros cards banidos à sua mão. \r\nVocê só pode usar cada efeito de "Ataque do Corte das Sombras" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar efeito','Adicionar à mão','Monstro: Negar efeitos de Magia/Armadilha','Magia: Comprar 1 card','Armadilha: Banir um monstro','','','','','','','','','','','');
INSERT INTO texts VALUES(57238939,'Aliado Remoto Genex',replace(replace('Uma vez por turno, você pode selecionar 1 monstro Regulador com a face para cima no campo. \r\nO nome do monstro selecionado é considerado como "Controlador Genex" até a Fase Final.','\r',char(13)),'\n',char(10)),'Alterar nome','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57246528,'Transcendência Sincro',replace(replace('Escolha 1 Monstro Sincro que seu oponente controla; Invoque por Invocação-Especial 1 Monstro Sincro que seja 1 Nível maior que o dele do seu Deck Adicional, mas ele não pode ativar seus efeitos neste turno. \r\nVocê só pode ativar 1 "Transcendência Sincro" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57256127,'Arquidemônio Shippador',replace(replace('Você pode escolher qualquer número de monstros com a face para cima no campo e declarar 1 Tipo ou Atributo; eles se tornam desse Tipo ou Atributo. \r\nSe um ou mais monstros forem Invocados por Invocação-Especial no campo do seu oponente, enquanto este card estiver na sua Zona de Monstros (exceto durante a Etapa de Dano): você pode escolher 1 monstro em cada campo com o mesmo Tipo e Atributo um do outro; devolva-os para a mão. \r\nVocê só pode usar cada efeito de "Arquidemônio Shippador" uma vez por turno.','\r',char(13)),'\n',char(10)),'Alterar Tipo/Atributo','Retornar para a mão','Declarar um Atributo','Declarar um Tipo de monstro','','','','','','','','','','','','');
INSERT INTO texts VALUES(57261568,'Flor Cardian Peônia com Borboleta',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro deve ser Invocado por Invocação-Especial (da sua mão) ao oferecer como Tributo 1 monstro "Flor Cardian", exceto "Flor Cardian Peônia com Borboleta". \r\nSe este card for Invocado por Invocação-Especial: compre 1 card e, se isso acontecer, mostre-o e, depois, se for um monstro "Flor Cardian", olhe os 3 cards do topo do Deck do seu oponente e, depois, coloque-os no topo ou no fundo do Deck em qualquer ordem. \r\nCaso contrário, envie-o para o Cemitério. \r\nQuando este card for usado como Matéria Sincro, você pode considerá-lo e todas as outras Matérias Sincro (que tiverem um Nível) como monstros de Nível 2.','\r',char(13)),'\n',char(10)),'Comprar','Colocar no topo do Deck','Colocar no fundo do Deck','Considerar todos os monstros Matéria Sincro como monstros de Nível 2?','','','','','','','','','','','','');
INSERT INTO texts VALUES(57270476,'Isca do Sepultura',replace(replace('Gire o card do topo do Deck do seu adversário com a face para cima e ele embaralha o Deck. \r\nQuando o seu adversário compra o card com a face para cima, envia-o imediatamente para o Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57272170,'Evigishki Ogro de Alma',replace(replace('Você pode Invocar este card por Invocação-Ritual com qualquer Magia de Ritual "Gishki". \r\nUma vez por turno: você pode descartar 1 monstro "Gishki" e, depois, escolha 1 card com a face para cima que seu oponente controla; embaralhe o alvo no Deck.','\r',char(13)),'\n',char(10)),'Retornar ao Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57274196,'Iluminação',replace(replace('Você não pode Invocar no turno em que você ativar este card. \r\nAtive no final da Etapa de Dano, se um monstro do Tipo Mago que você controla atacou e destruiu um monstro do oponente em batalha. \r\nEsse monstro pode atacar novamente (imediatamente).','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57281778,'Ryu Kokki','No final da Etapa de Dano, se este card batalhou um monstro Guerreiro ou Mago: destrua esse monstro.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57282724,'Mecanismo Mundial da Teurlógica Demiúrgica',replace(replace('3 monstros de Nível 5 ou mais	\r\nNão pode ser usado como Matéria Link. \r\nEste card Invocado por Invocação-Link não é afetado por outros efeitos de monstro. \r\nVocê só pode usar cada um dos seguintes efeitos de "Mecanismo Mundial da Teurlógica Demiúrgica" uma vez por turno.\r\n● Durante sua Fase Principal, se você controlar este card que foi Invocado por Invocação-Link usando 3 monstros que tinham 3 Tipos e Atributos diferentes no campo: você pode destruir todos os outros cards no campo.\r\n● Se seu oponente Invocar um ou mais monstros por Invocação-Especial do Deck Adicional (exceto durante a Etapa de Dano): você pode Invocar por Invocação-Especial 1 monstro "Legado Mundial" do seu Deck.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57285770,'Investida Therion',replace(replace('Envie para o Cemitério 1 card "Therion", exceto "Investida Therion", ou 1 "Motor Interminável Sistema Argyro" da sua mão ou da sua Zona de Magias & Armadilhas com a face para cima; compre 2 cards. \r\nVocê só pode ativar 1 "Investida Therion" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57288064,'Shiranui Samuraisaga',replace(replace('1 Regulador do Tipo Zumbi + 1 ou mais monstros não-Reguladores do Tipo Zumbi	\r\nUma vez por turno, durante o turno de qualquer duelista: você pode escolher 1 dos seus monstros banidos do Tipo Zumbi; embaralhe-o no Deck e, se isso acontecer, coloque em Posição de Defesa todos os monstros que seu oponente controla com ATK menor ou igual ao desse monstro. \r\nSe este card for banido: você pode escolher 1 monstro com a face para cima que seu oponente controla; ele perde 500 de ATK. \r\nVocê só pode Invocar um ou mais "Shiranui Samuraisaga" por Invocação-Especial uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57288708,'Legado Mundial - "Cálice Mundial"',replace(replace('Se um ou mais monstros forem Invocados por Invocação-Especial do Deck Adicional (exceto durante a Etapa de Dano): você pode oferecer este card como Tributo; envie esse(s) monstro(s) para o Cemitério. \r\nVocê só pode usar cada um dos seguintes efeitos de "Legado Mundial - "Cálice Mundial"" uma vez por turno.\r\n● Se este card Invocado/Baixado por Invocação-Normal com a face para cima deixar o campo: você pode Invocar por Invocação-Especial 2 monstros "Cálice Mundial" do seu Deck, exceto "Legado Mundial - "Cálice Mundial"".\r\n● Durante sua Fase Principal, exceto no turno em que este card foi enviado para o Cemitério: você pode banir este card do seu Cemitério; adicione 1 card "Legado Mundial" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57294268,'Aleister, o Reminiscente',replace(replace('Se este card estiver na sua mão: você pode escolher 1 monstro Mago ou 1 Monstro de Fusão no campo; Invoque este card por Invocação-Especial e, se isso acontecer, o monstro alvo ganha 1000 de ATK até o final deste turno. \r\nSe este card for Invocado por Invocação-Normal ou Especial, ou virado com a face para cima: você pode banir 1 monstro "Invokado(a)" do seu Deck Adicional; adicione 1 "Invokação", ou 1 Magia que o mencione, do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "Aleister, o Reminiscente" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Efeito de busca','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57296396,'Nemleria Louve',replace(replace('Invoque por Invocação-Especial 1 monstro "Nemleria" ou 1 monstro Besta de Nível 10 da sua mão ou do Deck em Posição de Defesa, mas devolva-o para a mão durante a Fase Final. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 monstro com a face para cima que seu oponente controla; até o final deste turno, ele perde 100 de ATK/DEF para cada um dos seus cards atualmente banidos com a face para baixo. \r\nVocê só pode usar cada efeito de "Nemleria Louve" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57305373,'Senhor das Trevas de Duas Bocas','Este dinossauro com duas mandíbulas mortíferas armazena eletricidade em seu chifre e liberta raios de alta voltagem pela boca nas suas costas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57308711,'Unicular','O terceiro dos irmãos, seguido de Tricular e Bicular.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57312333,'Chamado Amazoness',replace(replace('Pegue 1 card "Amazoness" no seu Deck, exceto "Chamado Amazoness", e adicione-o à sua mão ou envie-o para o Cemitério. \r\nDurante sua Fase Principal: você pode banir este card do seu Cemitério e, depois, escolha 1 monstro "Amazoness" que você controla; neste turno, esse monstro pode atacar todos os monstros que seu oponente controla, uma vez cada e, além disso, outros monstros que você controla não podem atacar. \r\nVocê só pode ativar 1 "Chamado Amazoness" por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57314798,'Número 100: Dragão Numeron',replace(replace('2 Monstros Xyz "Número" com o mesmo nome e Classe	\r\nUma vez por turno: você pode desassociar 1 matéria deste card; até o final do turno do seu oponente, este card ganha ATK igual à Classe combinada de todos os Monstros Xyz atualmente no campo x 1000. \r\nQuando este card for destruído por um efeito de card: você pode destruir tantos monstros no campo quanto possível (mín. 1) e, depois, cada duelista Baixa 1 Magia/Armadilha do seu próprio Cemitério no seu próprio campo. \r\nQuando um monstro do oponente declarar um ataque enquanto este card estiver no seu Cemitério e você não tiver cards na sua mão ou no campo: você pode Invocar este card por Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57319935,'Xyz Extremo!!',replace(replace('Quando um Monstro Xyz que você controla for destruído em batalha: Pague 1000 PV; você revela 1 Monstro Xyz do Deck Adicional com uma Classe menor ou igual a desse monstro destruído, e seu oponente também pode fazê-lo (simultaneamente). \r\nO duelista que revelou o monstro com o menor ATK sofre dano igual à diferença entre os ATKs dos monstros revelados. \r\nSe o oponente não revelar um monstro, cause dano ao seu oponente igual ao ATK do seu monstro revelado.','\r',char(13)),'\n',char(10)),'Escolha um Monstro Xyz','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57329501,'Mergulho Marincesa',replace(replace('Ative 1 dos seguintes efeitos. \r\nPelo resto deste turno depois que este card resolver, você não pode Invocar monstros por Invocação-Especial, exceto monstros de ÁGUA.\r\n● Escolha 1 monstro "Marincesa" que não seja Link no seu Cemitério; Invoque-o por Invocação-Especial.\r\n● Se "Oceano de Batalha Marincesa" estiver na sua Zona do Campo: Invoque por Invocação-Especial 1 monstro "Marincesa" do seu Deck.	\r\nVocê só pode ativar 1 "Mergulho Marincesa" por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial do Cemitério','Invocar por Invocação Especial do Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57346400,'Sabujo de Guarda','VIRE: Seu oponente não pode Invocar por Invocação-Especial pelo resto deste turno.','Restrição de Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57348141,'Apagador do Crepúsculo',replace(replace('Se você controlar 2 ou mais monstros "Luminoso(a)" com o mesmo Tipo, mas com nomes diferentes: bana 2 monstros "Luminoso(a)" do seu Cemitério e, depois, escolha 2 cards no campo; bana-os. \r\nSe este card for enviado do Deck para o Cemitério pelo efeito de um monstro "Luminoso(a)": você pode Invocar por Invocação-Especial 1 monstro "Luminoso(a)" da sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57354389,'Soldado de Pedra Sentinela',replace(replace('Se todos os monstros que você controla forem monstros do Tipo Rocha (mín. 1), enquanto este card estiver no seu Cemitério: você pode Invocar este card por Invocação-Especial. \r\nVocê só pode usar este efeito de "Soldado de Pedra Sentinela" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57355219,'Fusão Paradoxo','Quando um ou mais monstros seriam Invocados por Invocação-Especial, OU um Card de Magia/Armadilha for ativado: bana 1 Monstro de Fusão com a face para cima que você controla; negue a Invocação ou ativação e, se isso acontecer, destrua esse card e, além disso, durante sua 2ª Fase Final, devolva o Monstro de Fusão banido para o seu campo com a face para cima em Posição de Ataque.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57357130,'Salamagrande Doninha',replace(replace('Se você tiver 2 ou mais monstros "Salamagrande" no seu Cemitério: você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe um ou mais Monstros de Ritual, de Fusão, Sincro, Xyz ou Link "Salamagrande" forem Invocados por Invocação-Especial no seu campo, enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode escolher 1 outro monstro "Salamagrande" no seu Cemitério; coloque este card no fundo do seu Deck e, se isso acontecer, Invoque esse monstro por Invocação-Especial no campo do seu oponente e, depois, compre 1 card. \r\nVocê só pode usar cada efeito de "Salamagrande Doninha" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57384901,'Deformação Interdimensional',replace(replace('Escolha um monstro que você controla e um monstro com um ou mais Marcadores-A que seu oponente controla. \r\nTroque o controle desses monstros.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57405307,'Dragão Alado, Guardião da Fortaleza Nº2','As asas deste monstro são capazes de criar tornados.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57409948,'Besouro Bombardeiro',replace(replace('VIRE: Pegue e olhe 1 Card de Monstro com a face para baixo em Posição de Defesa no campo do seu oponente. \r\nSe for um Monstro de Efeito, destrua-o (seu efeito de Virar não é ativado) e, se não for, devolva-o para sua posição original.','\r',char(13)),'\n',char(10)),'Revelar um card Baixado','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57416183,'Arrumação Dragãozela',replace(replace('Escolha 1 monstro Dragão que você controla e 1 card que seu oponente controla ou no Cemitério dele; devolva-os para a mão. \r\nVocê pode banir este card do seu Cemitério; Invoque por Invocação-Especial 1 monstro "Dragãozela" da sua mão ou do Cemitério em Posição de Defesa, mas devolva-o para a mão durante a Fase Final. \r\nVocê só pode usar 1 efeito de "Arrumação Dragãozela" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57420265,'Arpoador Peixeborgue',replace(replace('Você pode revelar este card e 1 monstro de ÁGUA na sua mão; Invoque por Invocação-Especial 1 deles e descarte o outro. \r\nVocê só pode usar este efeito de "Arpoador Peixeborgue" uma vez por turno. \r\nSe este card for enviado para o Cemitério como matéria para um Monstro Sincro de ÁGUA: até o final deste turno, você pode negar os efeitos de 1 Monstro de Efeito que seu oponente controla.','\r',char(13)),'\n',char(10)),'Invocação Especial','Negar um monstro do oponente','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57421866,'Devorador de Níveis',replace(replace('Se este card estiver no seu Cemitério: você pode escolher 1 monstro de Nível 5 ou mais que você controla; reduza o Nível dele em 1 e, se isso acontecer, Invoque este card por Invocação-Especial. \r\nEste card com a face para cima no campo não pode ser oferecido como Tributo, exceto para uma Invocação-Tributo.','\r',char(13)),'\n',char(10)),'Invocação Especial','Escolha 1 monstro de Nível 5 ou mais','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57425061,'Fusão da Visão',replace(replace('Invoque por Invocação-Fusão 1 Monstro de Fusão "HERÓI" do seu Deck Adicional, usando monstros da sua mão ou do campo como Matéria de Fusão. \r\nVocê também pode usar como Matéria de Fusão até 2 monstros na sua Zona de Magias & Armadilhas que sejam considerados como Armadilhas Contínuas, ao bani-los. \r\nVocê só pode ativar 1 "Fusão da Visão" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57433966,'Perigo! Excitação! Mistério!',replace(replace('Descarte 1 monstro "Perigo!" de Nível 5 ou mais; adicione 1 monstro "Perigo!" de Nível 4 ou menos do seu Deck à sua mão. \r\nVocê não pode Invocar monstros por Invocação-Especial pelo resto deste turno depois que este card resolver, exceto monstros "Perigo!". \r\nVocê só pode ativar 1 "Perigo! Excitação! Mistério!" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57441100,'Poder Hercúleo','Uma vez por turno, se seu oponente controlar um monstro e você não controlar nenhum monstro, você pode Invocar por Invocação-Especial 1 monstro Gêmeos de Nível 4 ou menos da sua mão.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57448410,'Materriator Prima',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nMonstros Xyz que você controla ganham 100 de ATK para cada Matéria Xyz no campo. Você pode escolher 1 Monstro Xyz "Materriator" que você controla; associe este card a ele como matéria e, depois, compre 1 card. Você só pode usar este efeito de "Materriator Prima" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nUma forma de vida alienígena que surgiu repentinamente dos céus distantes. Muitos pesquisadores já tentaram determinar sua verdadeira identidade, mas sua luminosidade e o miasma que emite há muito tempo envolveram sua existência em mistério, tornando extremamente difícil ver a extensão total de sua existência. Recentemente, contudo, uma série de novas espécies foram descobertas por pesquisadores promissores, e parece que a extensão total da existência da espécie está finalmente sendo revelada.','\r',char(13)),'\n',char(10)),'','Como Matéria Xyz','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57450198,'Besta Mech Super Quantal Lusterrex',replace(replace('2 monstros de Nível 7	\r\nNão pode atacar a não ser que tenha matéria. \r\nUma vez por turno: você pode desassociar 1 matéria deste card e, depois, escolher 1 Monstro de Efeito no campo; até o final deste turno, negue os efeitos desse monstro com a face para cima. \r\nEste é um Efeito Rápido se este card tiver "Camada Branca Super Quantum" como matéria. \r\nUma vez por turno: você pode associar 1 monstro "Super Quantum" da sua mão ou do campo a este card como matéria.','\r',char(13)),'\n',char(10)),'Negar o efeito','Associar Matéria Xyz','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57458399,'Sincron Satélite',replace(replace('Se um ou mais monstros forem Invocados por Invocação-Especial do seu Cemitério (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe você tiver um Monstro Sincro com "Guerreiro(a)", "Sincron" ou "Poeira Estelar" em seu nome original no seu campo ou Cemitério: você pode fazer com que o Nível deste card se torne 4 até o final deste turno. \r\nVocê só pode usar cada efeito de "Sincron Satélite" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57470761,'Asa Tirana',replace(replace('Escolha 1 monstro Dragão no campo; equipe este card a ele. \r\nEle ganha 400 de ATK/DEF e, além disso, ele pode realizar até 2 ataques contra monstros durante cada Fase de Batalha. \r\nUma vez por turno, durante a Fase Final, se o monstro equipado com este card por este efeito atacou um monstro do oponente neste turno: destrua este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57473560,'Príncipe Inumano',replace(replace('Se este card for enviado para o Cemitério: você pode enviar 1 "Servo Caveira" e 1 "A Dama Inumana" da sua mão e/ou do Deck para o Cemitério. \r\nVocê pode banir 2 "Servo Caveira" e este card do seu Cemitério; Invoque por Invocação-Especial 1 "Rei dos Servos Caveira" do seu Deck. \r\nO nome deste card se torna "Servo Caveira" enquanto estiver no Cemitério.','\r',char(13)),'\n',char(10)),'Enviar para o Cemitério','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57477163,'Ovelha Peladura',replace(replace('"Diabrete de Correntes Afiadas" + 1 monstro "Fofanimal"	\r\nSe este card batalhar, seu oponente não pode ativar cards ou efeitos até o final da Etapa de Dano. \r\nSe este card for destruído em batalha e enviado para o Cemitério ou se este card em sua posse for destruído por um efeito de card do oponente e enviado para o seu Cemitério: você pode Invocar este card por Invocação-Especial e, se isso acontecer, ele ganha 800 de ATK. \r\nVocê só pode usar este efeito de "Ovelha Peladura" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57482479,'Soldado do Sol','Se este card combater com um monstro das TREVAS, aumente o ATK deste card em 500 pontos durante o Damage Step.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57496978,'Colisão de Almas',replace(replace('Durante o cálculo de dano, se seu monstro em Posição de Ataque batalhar um monstro em Posição de Ataque do oponente com maior ATK: o controlador do monstro com o menor ATK que estiver batalhando pode pagar 500 PV para que esse monstro ganhe 500 de ATK apenas durante o cálculo de dano e, depois, continue repetindo este efeito até que um duelista selecione não pagar PV. \r\nNenhum duelista sofre qualquer dano de batalha dessa batalha e, além disso, depois do cálculo de dano, se o monstro de qualquer duelista seria destruído por essa batalha, em vez disso, envie todos os cards que esse duelista controla para o Cemitério.','\r',char(13)),'\n',char(10)),'Pagar PV?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57499304,'Reencarnação dos Sétimos Imperadores',replace(replace('Durante o cálculo de dano, se um Monstro Xyz "Número" seu com um número entre "101" e "107" em seu nome, ou um Monstro Xyz seu que tenha qualquer desses monstros como matéria, batalhar: bana esse monstro que você controla (além disso, bana suas matérias). \r\nDurante a Fase Final do turno em que você ativou este card, Invoque por Invocação-Especial 1 Monstro Xyz de Classe 3 ou menos do seu Deck Adicional, exceto um monstro "Número" e, se isso acontecer, cause dano ao seu oponente igual ao ATK original dele.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57511992,'Yorishiro da Água',replace(replace('Você pode escolher 1 monstro de ÁGUA no seu Cemitério; aplique 1 desses efeitos e, além disso, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros de ÁGUA.\r\n● (Apenas se o alvo tiver um Nível) até a Fase Final, o Nível deste card e, além disso, seu nome, se tornam o mesmo que o desse monstro.\r\n● (Apenas se "Umi" estiver no campo), Invoque esse monstro por Invocação-Especial em Posição de Defesa.	\r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 "Umi" no seu Cemitério; adicione-o à sua mão. \r\nVocê só pode usar cada efeito de "Yorishiro da Água" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Alterar o nome do card e o Nível','Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57523313,'Melffy Fenny',replace(replace('Se seu oponente Invocar um ou mais monstros por Invocação-Normal ou Especial (exceto durante a Etapa de Dano), ou se um monstro do oponente escolher este card como alvo de um ataque: você pode devolver este card para a mão e, depois, você pode Invocar por Invocação-Especial 1 monstro Besta da sua mão, exceto "Melffy Fenny". \r\nDurante sua Fase Final: você pode Invocar este card por Invocação-Especial da sua mão. \r\nVocê só pode usar cada efeito de "Melffy Fenny" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Invocar por Invocação Especial da sua mão?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57541158,'Marincesa Donzela Sonolenta',replace(replace('Você pode escolher 1 card "Marincesa" que você controla; Invoque este card por Invocação-Especial da sua mão e, se isso acontecer, ele ganha este efeito.\r\n● Enquanto este card estiver na Zona de Monstros, o card alvo não pode ser destruído pelos efeitos de card do seu oponente.	\r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 Monstro Link "Marincesa" que você controla; equipe-o com 1 Monstro Link "Marincesa" do seu Cemitério. \r\nVocê só pode usar cada efeito de "Marincesa Donzela Sonolenta" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57543573,'Lombriga Illidan',replace(replace('Cada vez que um card for Baixado no seu lado do campo, coloque 1 Marcador de Lombriga neste card. \r\nVocê pode remover 2 Marcadores de Lombriga deste card para selecionar 1 card que seu oponente controla e destruí-lo.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57549932,'Gardna do Amanhecer',replace(replace('Este card é considerado como um Monstro Normal enquanto estiver com a face para cima no campo ou no Cemitério. \r\nEnquanto este card estiver com a face para cima no campo, você pode Invocá-lo por Invocação-Normal para fazer com que ele seja considerado como um Monstro de Efeito com este efeito:\r\n● A DEF original deste card se torna 2300.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57554544,'Ilha do Rei de Fogo',replace(replace('Se este card com a face para cima na Zona do Campo for enviado para o Cemitério ou banido: destrua todos os monstros que você controla. \r\nVocê só pode usar 1 dos seguintes efeitos de "Ilha do Rei de Fogo" por turno e apenas uma vez por turno.\r\n● Durante sua Fase Principal: você pode destruir 1 monstro na sua mão ou no campo e, se isso acontecer, adicione 1 monstro "Rei(s) de Fogo" do seu Deck à sua mão.\r\n● Se você não controlar nenhum monstro: você pode Invocar por Invocação-Especial 1 monstro Besta Alada de FOGO da sua mão.','\r',char(13)),'\n',char(10)),'Destruir um monstro','Invocação Especial','Destruir um monstro','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57566760,'Uzuhime, a Mikanko Manifesta',replace(replace('2 monstros "Mikanko" de Nível 3	\r\nSe este card for Invocado por Invocação-Especial: você pode adicionar 1 Magia de Equipamento do seu Deck ou Cemitério à sua mão. \r\nVocê só pode usar este efeito de "Uzuhime, a Mikanko Manifesta" uma vez por turno. \r\nNão pode ser destruído em batalha e, além disso, seu oponente sofre qualquer dano de batalha que você teria sofrido das batalhas envolvendo este card. \r\nSe este card atacar e batalhar, no final da Etapa de Dano: você pode desassociar 1 matéria deste card; ele pode atacar novamente em seguida.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','Continuar atacando','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57568840,'Voador Delta','Uma vez por turno, você pode selecionar 1 outro monstro com a face para cima que você controla e aumentar seu Nível em 1.','Aumentar o Nível','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57579381,'Senhora Obscura Maria',replace(replace('Uma vez por turno, durante sua Fase de Apoio: você ganha 200 PV. \r\nEste card deve estar no Cemitério para ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Ganhar PV','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57585212,'Botão de Auto-Destruição',replace(replace('Você só pode ativar este card enquanto seus PV forem menores que os PV do seu oponente e a diferença for de 7000 ou mais. \r\nOs PV dos dois duelistas se torna 0.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57594700,'Schuberta, a Maestra Melodiosa',replace(replace('2 monstros "Melodiosa(o)"	\r\nUma vez enquanto estiver com a face para cima no campo (Efeito Rápido): você pode escolher até 3 cards em quaisquer Cemitérios; bana-os e, se isso acontecer, este card ganha 200 de ATK para cada um.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57605303,'Raio do Dragão Armado',replace(replace('Escolha 1 monstro "Dragão Armado" que você controla; ele ganha 1000 de ATK para cada monstro "Dragão Armado" no seu Cemitério com um Nível igual ou menor que o dele e com nomes diferentes uns dos outros e, além disso, pelo resto deste turno, seu oponente não sofre dano de batalha dos ataques dele. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 Magia "Dragão Armado" no seu Cemitério; adicione-a à sua mão. \r\nVocê só pode usar 1 efeito de "Raio do Dragão Armado" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57610714,'Nuviano - Olho do Tufão',replace(replace('Não pode ser destruído em batalha. \r\nSe este card estiver com a face para cima em Posição de Defesa, destrua-o. \r\nSe este card declarar um ataque: mude as posições de batalha de todos os monstros com a face para cima, exceto monstros "Nuviano".','\r',char(13)),'\n',char(10)),'Mudar a posição de batalha','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57617178,'Pássaro Sônico','Quando este card for Invocado por Invocação-Normal ou Virar: você pode adicionar 1 Magia de Ritual do seu Deck à sua mão.','Adicione à sua mão 1 Card de Magia de Ritual','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57624336,'Arquidemônio Excêntruque',replace(replace('Escala de Pêndulo = 7\r\n[ Efeito de Pêndulo ]\r\nVocê pode escolher 1 outra Magia/Armadilha no campo; destrua tanto ela como este card. \r\nVocê só pode usar este efeito de "Arquidemônio Excêntruque" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nVocê pode oferecer este card como Tributo e, depois, escolha 1 monstro no campo; destrua-o. \r\nVocê só pode usar este efeito de "Arquidemônio Excêntruque" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57630503,'Marcosia Mitológico',replace(replace('Se este card estiver na sua mão: você pode descartar até 2 monstros, exceto "Marcosia Mitológico", mas incluindo outro monstro "Mitológico(a)" e, se isso acontecer, Invoque este card por Invocação-Especial. \r\nSe Invocado desta forma, este card ganha 200 de ATK para cada monstro descartado. \r\nSe este card for descartado para o Cemitério: adicione 1 Magia/Armadilha "Mitológico(a)" do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "Marcosia Mitológico" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57647597,'Lâmia Reptiliana',replace(replace('Se este card estiver na sua mão e todos os monstros que você controla forem monstros Réptil com a face para cima (mín. 1): você pode escolher 1 monstro com a face para cima que seu oponente controla; mude o ATK dele para 0 e, se isso acontecer, Invoque este card por Invocação-Especial e, depois, sofra dano igual ao ATK original desse monstro. \r\nSe este card for enviado para o Cemitério como Matéria Sincro: você pode escolher até 2 monstros com a face para cima no campo; mude o ATK deles para 0. \r\nVocê só pode usar 1 efeito de "Lâmia Reptiliana" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57649113,'Stinger, o Expulsor Elétrico','Ao longo de batalhas tenazes, Stinger e os Defensores das Dunas repeliram todas as ameaças externas que se aproximavam. Sua espada deve ser usada apenas para a defesa de seu povo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57662975,'Dragão da Tempestade Negra',replace(replace('Este card é considerado um Monstro Normal enquanto estiver com a face para cima no campo ou no Cemitério. \r\nEnquanto este card for um Monstro Normal no campo, você pode Invocá-lo por Invocação-Normal para torná-lo um Monstro de Efeito com este efeito.\r\n● Uma vez por turno: você pode enviar 1 Card de Magia/Armadilha com a face para cima que você controla para o Cemitério; destrua todos os Cards de Magia e de Armadilha no campo.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57666212,'Kuraz, o Monarca da Luz',replace(replace('Quando este card for Invocado por Invocação-Normal ou Especial: você pode escolher até 2 cards no campo; destrua os alvos e, se isso acontecer, cada duelista pode comprar 1 card para cada um dos cards que ele controlava que foi destruído por este efeito. \r\nEste card não pode atacar durante o turno em que for Invocado por Invocação-Normal ou Especial.','\r',char(13)),'\n',char(10)),'Destrua até 2 cards no campo','Comprar 1 card?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57690191,'Irmãos Nobre Cavaleiros',replace(replace('Este card só pode atacar se você controlar exatamente 3 monstros "Nobre Cavaleiro" (e nenhum outro monstro). \r\nQuando este card for Invocado por Invocação-Normal: você pode Invocar por Invocação-Especial até 2 monstros "Nobre Cavaleiro" da sua mão e, além disso, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros "Nobre Cavaleiro". \r\nUma vez por turno: você pode escolher 3 cards "Nobre Cavaleiro" e/ou "Armas Nobres" no seu Cemitério; embaralhe os 3 no Deck e, depois, compre 1 card.','\r',char(13)),'\n',char(10)),'Invocação Especial','Recuperar cards','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57707471,'Número 21: Justiça da Dama de Gelo',replace(replace('2 monstros de Nível 6	\r\nVocê também pode Invocar este card por Invocação-Xyz ao desassociar 1 Matéria Xyz de um Monstro Xyz de Classe 5 que você controla e, depois, usar esse Monstro Xyz como Matéria Xyz. \r\n(Matérias Xyz associadas a esse monstro também se tornam Matéria Xyz neste card.) \r\nEste card ganha 1000 de ATK para cada Matéria Xyz associada a ele. \r\nUma vez por turno: você pode desassociar 1 Matéria Xyz deste card; destrua todos os monstros em Posição de Defesa que seu oponente controla.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Xyz usando um Monstro Xyz de Classe 5 como matéria?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57722593,'Konohanasakuya',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao controlar um monstro Espírito. \r\nVocê só pode Invocar "Konohanasakuya" por Invocação-Especial uma vez por turno desta forma. \r\nUma vez por turno, durante a Fase Final, se este card foi Invocado por Invocação-Especial neste turno: devolva-o para a mão. \r\nUma vez por turno, durante a Fase Final: você pode banir este card do seu Cemitério e, depois, escolha 1 monstro Espírito que você controla; nenhum duelista pode ativar os efeitos desse monstro com a face para cima no campo pelo resto deste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57728570,'Vírus Esmaga-Card','Ofereça como Tributo 1 monstro de TREVAS com 1000 ou menos de ATK; seu oponente não sofre dano até o final do próximo turno depois que este card resolver e, além disso, você olha a mão do seu oponente e todos os monstros que ele controla e, se isso acontecer, destrua os monstros entre eles com 1500 ou mais de ATK e, depois, seu oponente pode destruir até 3 monstros com 1500 ou mais de ATK no Deck dele.','Destruir o(s) monstro(s) no Deck?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57728571,'Vírus Esmaga-Card','Ofereça como Tributo 1 monstro de TREVAS com 1000 ou menos de ATK; seu oponente não sofre dano até o final do próximo turno depois que este card resolver e, além disso, você olha a mão do seu oponente e todos os monstros que ele controla e, se isso acontecer, destrua os monstros entre eles com 1500 ou mais de ATK e, depois, seu oponente pode destruir até 3 monstros com 1500 ou mais de ATK no Deck dele.','Destruir o(s) monstro(s) no Deck?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57731460,'Besta Gladiadora Equeste',replace(replace('Se este card for Invocado por Invocação-Especial pelo efeito de um monstro "Besta Gladiadora": escolha 1 card "Besta Gladiadora" no seu Cemitério; adicione o alvo à sua mão. \r\nNo final da Fase de Batalha, se este card batalhou: você pode embaralhá-lo no Deck; Invoque por Invocação-Especial 1 monstro "Besta Gladiadora" do seu Deck, exceto "Besta Gladiadora Equeste".','\r',char(13)),'\n',char(10)),'Recuperar do Cemitério','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57734012,'Magia de Aumento de Classe - O Sétimo',replace(replace('Para ativar este card, você deve comprá-lo em sua compra normal na sua Fase de Compra, revelá-lo e mantê-lo revelado até o começo da Fase Principal 1. \r\nNo começo da sua Fase Principal 1 do mesmo turno, você pode: Invocar por Invocação-Especial, do seu Deck Adicional ou Cemitério, 1 monstro "Número" com um número entre "101" e "107" em seu nome, exceto monstros "Número C" e, depois, Invoque por Invocação-Especial do seu Deck Adicional, 1 monstro "Número C" com o mesmo número em seu nome que o primeiro monstro, usando o primeiro como matéria. \r\n(A segunda Invocação-Especial é considerada uma Invocação-Xyz. Transfira as matérias dele para o monstro Invocado.) \r\nVocê só poder aplicar este efeito de "Magia de Aumento de Classe - O Sétimo" uma vez por Duelo.','\r',char(13)),'\n',char(10)),'Manter "Magia de Aumento de Classe - O Sétimo" revelado?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57736667,'Dança Mikanko - Mayowashidori',replace(replace('O monstro equipado não pode ser destruído por efeitos de card. \r\nVocê só pode usar cada um dos seguintes efeitos de "Dança Mikanko - Mayowashidori" uma vez por turno. \r\nNo final da Etapa de Dano, se um monstro "Mikanko" seu batalhou: você pode escolher 1 card no campo; devolva-o para a mão. \r\nSe este card estiver no seu Cemitério: você pode escolher 1 monstro "Mikanko" no seu Cemitério; Invoque-o por Invocação-Especial e, se isso acontecer, equipe-o com este card, mas bana-o quando ele deixar o campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57753602,'Energia Ofuscante da Gema','Durante cada uma das suas Fases de Apoio, cause dano ao seu oponente igual ao número de Cards de Magia Contínua com a face para cima no campo x 300.','Cause dano ao seu oponente','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57761191,'Metaltron XII, o Verdadeiro Dracombatente',replace(replace('Requer 3 Tributos para ser Invocado por Invocação-Normal (não pode ser Baixado Normalmente). \r\nPara Invocar este card por Invocação-Tributo com a face para cima, você pode oferecer como Tributo um ou mais Cards de Magia/Armadilha Contínuas que você controla, assim como monstros. \r\nNão é afetado pelos efeitos de cards com o mesmo tipo de card (Monstro, Magia e/ou Armadilha) que os tipos de card originais dos cards oferecidos como Tributo para sua Invocação-Tributo. \r\nSe este monstro Invocado por Invocação-Tributo sob o controle do seu dono for destruído por um card do oponente (em batalha ou por um efeito de card): você pode Invocar por Invocação-Especial 1 Monstro de Fusão, Sincro ou Xyz de TERRA, ÁGUA, FOGO ou VENTO do seu Deck Adicional.','\r',char(13)),'\n',char(10)),'Oferecer uma Magia/Armadilha como Tributo?','Invoque por Invocação Especial um Monstro Fusão, Sincro ou Xyz do Deck Adicional','Invocação Tributo ao oferecer como Tributo um Monstro','Invocação Tributo ao oferecer como Tributo um Card de Magia','Invocação Tributo ao oferecer como Tributo um Card de Armadilha','','','','','','','','','','','');
INSERT INTO texts VALUES(57769391,'Pixiel Altergeist',replace(replace('Você pode oferecer este card como Tributo; escave os 3 cards do topo do seu Deck, adicione 1 card "Altergeist" escavado à sua mão e, além disso, envie o resto para o Cemitério. \r\nVocê só pode usar este efeito de "Pixiel Altergeist" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57774843,'Dragão do Julgamento',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao ter 4 ou mais monstros "Luminoso(a)" com nomes diferentes no seu Cemitério. \r\nVocê pode pagar 1000 PV; destrua todos os outros cards no campo. \r\nUma vez por turno, durante sua Fase Final: envie os 4 cards do topo do seu Deck para o Cemitério.','\r',char(13)),'\n',char(10)),'Invocação Especial','Destrua todos os cards no campo exceto esta carta','Envie os 4 cards do topo do seu Deck para o Cemitério','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57775790,'Renascimento do Reino Mitológico',replace(replace('Quando este card for ativado: você pode Baixar 1 Magia/Armadilha "Mitológico(a)" do seu Deck, exceto "Renascimento do Reino Mitológico". \r\nSeu oponente não pode ativar cards ou efeitos quando você Invocar um Monstro Sincro "Mitológico(a)" por Invocação-Sincro. \r\nUma vez por turno: você pode descartar 1 card "Mitológico(a)" e, depois, ative 1 desses efeitos;\r\n● Compre 1 card.\r\n● Invoque por Invocação-Especial 1 monstro "Mitológico(a)" do seu Cemitério ou banimento.	\r\nVocê só pode ativar 1 "Renascimento do Reino Mitológico" por turno.','\r',char(13)),'\n',char(10)),'Ativar','Ativar o efeito escolhido','Baixar um card?','Comprar','Invocação Especial','','','','','','','','','','','');
INSERT INTO texts VALUES(57777714,'Domador da Besta Espiritual Zeframpilica',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nVocê não pode Invocar monstros por Invocação-Pêndulo, exceto monstros "Besta Espiritual" e "Zefra". \r\nEste efeito não pode ser negado.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nQuando este card for Invocado por Invocação-Normal ou Pêndulo: você pode escolher 1 monstro "Besta Espiritual" ou "Zefra" no seu Cemitério, exceto "Domador da Besta Espiritual Zeframpilica"; Invoque-o por Invocação-Especial, mas destrua-o durante a Fase Final. \r\nVocê só pode Invocar um ou mais "Domador da Besta Espiritual Zeframpilica" por Invocação-Especial uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57782164,'Gagagavento','Invoque por Invocação-Especial 1 monstro "Gagaga" da sua mão como um monstro de Nível 4.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57784563,'Lâmina Sombria, Capitão do Mundo das Trevas',replace(replace('Uma vez por turno: Você pode banir 1 monstro de TREVAS do seu Cemitério para escolher 1 monstro de LUZ de Nível 4 ou menos que seu oponente controla; equipe-o a este card. \r\n(Você só pode equipar 1 monstro por vez a este card com este efeito.) \r\nSe este card no campo seria destruído, em vez disso, o monstro equipado a ele por este efeito é destruído.','\r',char(13)),'\n',char(10)),'Equipar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57793869,'O Perverso Apagador',replace(replace('Não pode ser Invocado por Invocação-Especial. \r\nDeve ser Invocado por Invocação-Normal/Baixado ao oferecer 3 monstros como Tributo. \r\nO ATK/DEF deste card são iguais ao número de cards que seu oponente controla x 1000. \r\nDurante sua Fase Principal: você pode destruir este card. \r\nSe este card for destruído e enviado para o Cemitério: destrua todos os cards no campo.','\r',char(13)),'\n',char(10)),'Destruir todos os cards no Campo','Destruir este card','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57809669,'Hecamãos Tartaros',replace(replace('Ative 1 desses efeitos (mas você só pode usar cada efeito de "Hecamãos Tartaros" uma vez por turno);\r\n● Se você controlar um monstro "Hecamãos": você pode escolher 1 Magia/Armadilha que seu oponente controla; devolva-a para a mão.\r\n● Invoque por Invocação-Fusão 1 Monstro de Fusão "Hecamãos" do seu Deck Adicional, ao banir suas matérias do seu campo e/ou Cemitério.	\r\nSe você usar um monstro com a face para cima que você controla do qual seu oponente seja dono como matéria, você pode considerá-lo como um monstro "Hecamãos".','\r',char(13)),'\n',char(10)),'','Retornar uma Magia/Armadilha à mão','Invocação Fusão','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57815601,'Emboscada da Besta Espiritual',replace(replace('Escolha 1 dos seus monstros "Domador da Besta Espiritual" e 1 dos seus monstros "Avatar da Besta Espiritual" que estiverem banidos e/ou no seu Cemitério; Invoque-os por Invocação-Especial em Posição de Defesa. \r\nPelo resto deste turno depois que este card resolver, você não pode Invocar por Invocação-Especial, exceto monstros "Besta Espiritual". \r\nVocê só pode ativar 1 "Emboscada da Besta Espiritual" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57823578,'Batalha Celeste Simorgh',replace(replace('Monstros Besta Alada que você controla não podem ser escolhidos como alvo dos efeitos de card do seu oponente, ou dos ataques dos monstros dele, exceto seu(s) monstro(s) \r\nBesta Alada com o maior ATK. \r\nVocê pode enviar para o Cemitério, este card e 2 monstros "Simorgh" que você controla com Atributos originais diferentes cujos Níveis originais sejam 7 ou mais; devolva para a mão tantos cards no campo quanto possível e, se isso acontecer, sofra 500 de dano para cada card devolvido para a mão e, depois, cause dano ao seu oponente igual ao dano que você sofreu. \r\nVocê só pode usar este efeito de "Batalha Celeste Simorgh" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57827484,'Sombra Escavadora',replace(replace('Este card é considerado como um Monstro Normal enquanto estiver com a face para cima no campo ou no Cemitério. \r\nEnquanto este card estiver com a face para cima no campo, você pode Invocá-lo por Invocação-Normal para fazer com que ele seja considerado como um Monstro de Efeito com este efeito:\r\n● Uma vez por turno, você pode selecionar 1 monstro de TREVAS de Nível 4 ou menos que você controla.	\r\nEle pode atacar diretamente seu oponente neste turno.','\r',char(13)),'\n',char(10)),'Ataque direto','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57831349,'Nove Pilares de Yang Zing','Quando um Card de Magia/Armadilha, ou efeito de monstro, for ativado, e você controlar um card "Yang Zing": negue a ativação e, se isso acontecer, embaralhe esse card no Deck e, depois, destrua 1 outro card "Yang Zing" que você controla.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57835716,'Orcust Horror de Harpa',replace(replace('Você pode banir este card do seu Cemitério; Invoque por Invocação-Especial 1 monstro "Orcust" do seu Deck, exceto "Orcust Horror de Harpa" e, além disso, você não pode Invocar por Invocação-Especial pelo resto deste turno, exceto monstros de TREVAS. \r\nVocê só pode usar este efeito de "Orcust Horror de Harpa" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57836546,'Volta Dupla Xyz','Durante o turno em que um Monstro Xyz com a face para cima que você controla foi destruído, se você não controlar outros monstros: escolha 1 Monstro Xyz em seu Cemitério que foi destruído neste turno e 1 monstro em seu Cemitério com ATK menor ou igual ao ATK desse Monstro Xyz; Invoque esses alvos por Invocação-Especial, mas eles são destruídos durante a Fase Final.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57839750,'Mãe Ursa Parda','Quando este card for destruído em batalha e enviado para o Cemitério: você pode Invocar por Invocação-Especial do seu Deck 1 monstro da ÁGUA com 1500 ou menos de ATK, em Posição de Ataque.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57844634,'Musasabi Ágil',replace(replace('Quando este card for destruído em batalha e enviado para o Cemitério, cause 500 de dano ao seu oponente. \r\nVocê também pode Invocar por Invocação-Especial até 2 "Musasabi Ágil" do seu Deck no lado do campo do seu oponente com a face para cima em Posição de Ataque. \r\nEste card não pode ser oferecido como Tributo para uma Invocação-Tributo.','\r',char(13)),'\n',char(10)),'Causar dano','Invocar "Musasabi Ágil" por Invocação Especial?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57847269,'Ópera Matinê da Companhia de Palhaços',replace(replace('Durante sua Fase Principal: você pode Invocar por Invocação-Especial 1 monstro "Companhia de Palhaços" do seu Deck ou Deck Adicional, ignorando suas condições de Invocação e, além disso, até o final do próximo turno depois que este efeito resolver, você não pode ativar os efeitos de monstros Invocados por Invocação-Especial do Deck ou Deck Adicional. \r\nDurante a Fase Final: você pode comprar cards igual ao número de tipos de cards de monstro diferentes oferecidos como Tributo neste turno (Ritual, Fusão, Sincro, Xyz, Pêndulo, Link) e, depois, você pode Baixar 1 Magia/Armadilha da sua mão. \r\nVocê só pode usar cada efeito de "Ópera Matinê da Companhia de Palhaços" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Comprar','Baixar um card?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57869175,'Senhora Fortuna do Passado',replace(replace('O ATK/DEF deste card se tornam seu Nível x 200. \r\nUma vez por turno, durante sua Fase de Apoio: aumente em 1 o Nível deste card (máx. 12). \r\nVocê pode escolher 1 monstro "Senhora Fortuna" que você controla; bana qualquer número de outros monstros Mago da sua mão, do campo e/ou do Cemitério e, se isso acontecer, até o final deste turno, aumente ou reduza o Nível desse monstro pelo número de monstros banidos. \r\nVocê só pode usar este efeito de "Senhora Fortuna do Passado" uma vez por turno.','\r',char(13)),'\n',char(10)),'Aumentar o Nível em 1','Alterar o Nível','Aumentar o Nível','Reduzir o Nível','','','','','','','','','','','','');
INSERT INTO texts VALUES(57882509,'Máscara da Fraqueza','Escolha 1 monstro atacante; o alvo perde 700 de ATK até o final deste turno.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57900671,'Cinet Restauração',replace(replace('Escolha 1 de seus monstros Ciberso banidos; Invoque-o por Invocação-Especial. \r\nDurante sua Fase Principal, se seus PV forem 2000 ou menos: você pode banir este card do seu Cemitério e, depois, escolha 2 dos seus monstros Ciberso banidos; adicione-os à sua mão. \r\nVocê só pode usar cada efeito de "Cinet Restauração" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Recuperar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57902193,'Regresso Doloroso',replace(replace('Seu oponente escolhe 1 monstro no seu Cemitério. \r\nDurante a Fase Final, adicione esse monstro à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57902462,'Cavaleiro Divino Ishzark','Depois do cálculo de dano, quando este card destruir um monstro em batalha: bana esse monstro.','Banir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57916305,'Criação da Fazticeira',replace(replace('Adicione 1 monstro "Fazticeira" do seu Deck à sua mão. \r\nDurante sua Fase Final, se você controlar um monstro "Fazticeira", enquanto este card estiver no seu Cemitério: você pode adicionar este card à sua mão. \r\nVocê só pode usar 1 efeito de "Criação da Fazticeira" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar do Deck à mão','Adicionar este card à sua mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57935140,'Ternura','Uma fada adorável que celebra o dom do amor.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57940938,'Fantasma Firewall',replace(replace('Se este card for enviado para o Cemitério como matéria para a Invocação-Link de um monstro Ciberso: você pode adicionar 1 Magia/Armadilha "Cinet" do seu Deck à sua mão e, depois, descarte 1 card. \r\nVocê pode banir este card do seu Cemitério; durante a Fase Final deste turno, embaralhe 1 monstro Ciberso do seu Cemitério no Deck. \r\nVocê só pode usar cada efeito de "Fantasma Firewall" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57946551,'Escamas Rochosas',replace(replace('Se este card for Invocado por Invocação-Especial: você pode escolher 1 outro monstro com a face para cima no campo; equipe esse monstro com a face para cima a este card. \r\nNo começo da Etapa de Dano, se este card batalhar um monstro do oponente com o mesmo Tipo e Atributo que o do Card de Monstro equipado pelo efeito deste card: você pode destruir esse monstro do oponente. \r\nVocê só pode usar cada efeito de "Escamas Rochosas" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57953380,'Card do Regresso Seguro','Quando um ou mais monstros forem Invocados por Invocação-Especial do seu Cemitério (exceto durante a Etapa de Dano): você pode comprar 1 card.','Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57962537,'Rato de Corda',replace(replace('Durante sua Fase Principal: Você pode escolher 1 monstro "de Corda" no seu Cemitério; mude este card em Posição de Ataque com a face para cima que você controla para Posição de Defesa com a face para cima, e Invoque o alvo por Invocação-Especial em Posição de Defesa com a face para cima. \r\nEste efeito só pode ser usado uma vez, enquanto este card estiver com a face para cima no campo.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57964143,'Arbitragem do Branco',replace(replace('Você pode escolher 1 monstro Peixe que você controla; ele é considerado como um Regulador neste turno. \r\nQuando um monstro do oponente declarar um ataque: você pode descartar 1 monstro Peixe; coloque todos os monstros que seu oponente controla em Posição de Defesa. \r\nSe um ou mais dos seus monstros Peixe forem destruídos em batalha ou enviados para o seu Cemitério: você pode enviar este card com a face para cima da sua Zona de Magias & Armadilhas para o Cemitério; Invoque por Invocação-Especial 1 monstro Peixe do seu Cemitério. \r\nVocê só pode usar cada efeito de "Arbitragem do Branco" uma vez por turno.','\r',char(13)),'\n',char(10)),'Considerar como um Regulador','Mudar para Posição de Defesa','Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57970721,'Asterismo Drytron',replace(replace('Durante a Fase Principal: escolha 1 monstro "Drytron" ou 1 Monstro de Ritual que você controla e 1 monstro com a face para cima que seu oponente controla; seu monstro perde exatamente 1000 de ATK até o final do turno do seu oponente e, se isso acontecer, destrua o monstro do oponente. \r\nVocê só pode ativar 1 "Asterismo Drytron" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57985393,'Vassourinha',replace(replace('Não pode ser usado como Matéria Sincro, exceto para a Invocação-Sincro de um monstro de Nível 8 ou menos. \r\nVocê pode revelar este card e 1 monstro na sua mão; Invoque por Invocação-Especial 1 dos 2 e, se isso acontecer, bana o outro e, além disso, pelo resto deste turno, você não pode Invocar por Invocação-Especial do Deck Adicional, exceto Monstros Sincro, e só pode declarar um ataque com Monstros Sincro. \r\nVocê só pode usar este efeito de "Vassourinha" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57995165,'Enterro Extra-Tolo',replace(replace('Pague metade dos seus PV; envie 1 monstro do seu Deck Adicional para o Cemitério. \r\nVocê só pode ativar 1 "Enterro Extra-Tolo" por turno. \r\nVocê não pode Baixar Magias/Armadilhas durante o turno em que ativar este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(57996334,'Demolidor Dododo',replace(replace('Se apenas seu oponente controlar um monstro, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nSe Invocado desta forma, seu Nível se torna 4. \r\nQuando este card for Invocado por Invocação-Tributo: você pode escolher 1 monstro "Dododo" no seu Cemitério; Invoque o alvo por Invocação-Especial em Posição de Defesa.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58004362,'Cruz Cruzado, o HERÓI Xtra',replace(replace('2 monstros Guerreiro	\r\nSe este card for Invocado por Invocação-Link: você pode escolher 1 monstro "HERÓI do Destino" no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê pode oferecer como Tributo 1 monstro "HERÓI do Destino"; adicione 1 monstro "HERÓI" com um nome diferente do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "Cruz Cruzado, o HERÓI Xtra" uma vez por turno e, além disso, você não pode Invocar monstros por Invocação-Especial no turno em que ativar qualquer um dos efeitos deste card, exceto monstros "HERÓI".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58012107,'Alienígena Psíquico',replace(replace('Este card é colocado em Posição de Defesa quando for Invocado por Invocação-Normal ou Invocação-Virar. \r\nMonstros com Marcadores-A não podem declarar um ataque.','\r',char(13)),'\n',char(10)),'Mudar para Posição de Defesa','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58012707,'Estádio dos Gigantes',replace(replace('Durante o cálculo de dano, se um duelista sofreria dano de batalha: você pode fazer com que qualquer duelista sofra qualquer dano de batalha dessa batalha e, se isso acontecer, envie 1 monstro Inseto de Nível 4 ou menos do seu Deck para o Cemitério e, depois, se você enviou um Monstro Normal desta forma, você pode Invocar por Invocação-Especial qualquer número de monstros com o mesmo nome que esse monstro, da sua mão, do Deck e/ou do Cemitério. \r\nSe um ou mais monstros que você controla forem enviados para o Cemitério por um efeito de card do oponente (exceto durante a Etapa de Dano): você pode Invocar por Invocação-Especial 1 Monstro Normal Inseto do seu Cemitério. \r\nVocê só pode usar cada efeito de "Estádio dos Gigantes" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Invocar 1 monstro com o mesmo nome por Invocação Especial?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58015506,'Segunda Visão de Pikeru','Até à segunda End Phase do seu adversário, ele revela a você todos os cards que ele compra e em seguida, adiciona-os à sua respectiva mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58016954,'Zefranaga Sombraneco',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nVocê não pode Invocar monstros por Invocação-Pêndulo, exceto monstros "Sombraneco" e "Zefra". \r\nEste efeito não pode ser negado.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe este card for Invocado por Invocação-Pêndulo ou enviado para o Cemitério: você pode escolher 1 card na Zona de Pêndulo de qualquer duelista; devolva-o para a mão. \r\nVocê deve ter um card "Zefra" na sua Zona de Pêndulo para ativar e resolver este efeito. \r\nVocê só pode usar este efeito de "Zefranaga Sombraneco" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58019984,'Formação do Novo Mundo',replace(replace('Escolha 1 Magia/Armadilha no seu Cemitério que mencione "Visas Starfrost"; Baixe-a e, se você Baixou uma Armadilha ou Magia Rápida, ela pode ser ativada neste turno. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 3 Magias/Armadilhas no seu Cemitério que mencionem "Visas Starfrost", exceto "Formação do Novo Mundo"; embaralhe-as no Deck. \r\nVocê só pode usar cada efeito de "Formação do Novo Mundo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Ativar aplicando o efeito de "Formação do Novo Mundo".','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58036097,'Recreação Surpresa dos Melffy',replace(replace('Escolha 1 monstro "Melffy" no seu campo ou Cemitério; devolva-o para a mão e, depois, você pode Invocar por Invocação-Fusão 1 Monstro de Fusão Besta do seu Deck Adicional, usando monstros da sua mão ou do campo. \r\nSe você controlar um Monstro Xyz "Melffy": você pode banir este card do seu Cemitério; pelo resto deste turno, monstros "Melffy" que você controla que forem Invocados por Invocação-Especial do Deck Adicional não são afetados pelos efeitos ativados do seu oponente. \r\nVocê só pode usar cada efeito de "Recreação Surpresa dos Melffy" uma vez por turno.','\r',char(13)),'\n',char(10)),'Retornar para a mão','Não afetado','Invocação Fusão?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58036229,'Protecodificar Transmissor',replace(replace('2+ Monstros de Efeito	\r\nSeu oponente não pode escolher monstros de Link-4 ou mais que você controla como alvo de efeitos de card e, além disso, eles não podem ser destruídos em batalha. \r\nSe você controlar um Monstro Link "Firewall" (Efeito Rápido): você pode banir Monstros Link do seu Cemitério cuja soma dos Valores Link seja exatamente igual a 3; Invoque este card por Invocação-Especial do seu Cemitério, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar este efeito de "Protecodificar Transmissor" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58053438,'Canções dos Dominadores',replace(replace('Se você não tiver monstros no seu Cemitério, você pode ativar este card da sua mão. \r\nQuando seu oponente ativar um efeito de monstro no campo: negue o efeito e, depois, se você tiver uma Armadilha no seu Cemitério, você pode adicionar 1 card "Dominus" do seu Deck à sua mão. \r\nSe você ativou este card da sua mão, até o final do próximo turno, você não pode ativar os efeitos de monstros na sua mão, no Cemitério e no banimento. \r\nVocê só pode ativar 1 "Canções dos Dominadores" por turno.','\r',char(13)),'\n',char(10)),'Negar o efeito','Ativar aplicando o efeito de "Canções dos Dominadores".','Adicionar este card à mão?','O efeito de "Canções dos Dominadores" está sendo aplicado.','','','','','','','','','','','','');
INSERT INTO texts VALUES(58054262,'Força Autômata',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial por "Comandante Covington". \r\nVocê deve pagar 1000 PV para declarar um ataque com este card. \r\nVocê pode enviar este card que você controla para o Cemitério e, depois, escolha 1 "Soldado Autômato", 1 "Franco-atirador Autômato" e 1 "Defensor Autômato" no seu Cemitério; Invoque os alvos por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58058134,'Maga Preguiçosa',replace(replace('2 monstros de Nível 1	\r\nUma vez por turno, este card não pode ser destruído em batalha. \r\nDurante o turno de qualquer duelista, quando um card ou efeito for ativado e escolher este card com a face para cima como alvo: você pode desassociar 1 Matéria Xyz deste card; negue a ativação e, se isso acontecer, destrua o card.','\r',char(13)),'\n',char(10)),'Negar a ativação e destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58062306,'Princesa das Rosas',replace(replace('Se somente seu oponente controlar um monstro, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nSe Invocado desta forma, considere este card como um Regulador. \r\nVocê só pode Invocar "Princesa das Rosas" por Invocação-Especial uma vez por turno desta forma. \r\nVocê pode descartar este card; adicione 1 "Claustro das Rosas Brancas" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58066722,'Furtidestruidor Alienígena',replace(replace('Se este card for enviado para o Cemitério: você pode escolher 1 monstro com a face para cima no campo; coloque 2 Marcadores-A nele. \r\nDurante sua Fase Principal, exceto no turno em que este card foi enviado para o Cemitério: você pode banir este card do seu Cemitério e, depois, escolha 1 card com um Marcador-A; destrua-o. \r\nVocê só pode usar cada efeito de "Furtidestruidor Alienígena" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58069384,'Dragão Cibernético Nova',replace(replace('2 monstros Máquina de Nível 5	\r\nUma vez por turno: você pode desassociar 1 matéria deste card e, depois, escolha 1 "Dragão Cibernético" no seu Cemitério; Invoque o alvo por Invocação-Especial. \r\nUma vez por turno (Efeito Rápido): você pode banir 1 "Dragão Cibernético" da sua mão ou da sua Zona de Monstros com a face para cima; este card ganha 2100 de ATK até o final deste turno. \r\nSe este card em sua posse for enviado para o seu Cemitério por um efeito de card do seu oponente: você pode Invocar por Invocação-Especial 1 Monstro de Fusão Máquina do seu Deck Adicional.','\r',char(13)),'\n',char(10)),'Invoque por Invocação Especial 1 "Dragão Cibernético" do seu Cemitério','Ganhe 2100 de ATK até a Fase Final','Invoque por Invocação Especial um Monstro Fusão','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58071123,'Oxygeddon','Se este card for destruído em batalha com um monstro Piro e enviado para o Cemitério: cada duelista sofre 800 de dano.','Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58071334,'Dragão Condenado Olho de Cobra',replace(replace('1 monstro "Olho de Cobra" + 1 monstro Ilusão	\r\nDeve ser Invocado por Invocação-Fusão, ou por Invocação-Especial ao enviar 2 Cards de Monstro com a face para cima da sua Zona de Magias & Armadilhas para o Cemitério. \r\nSe este card for Invocado por Invocação-Especial: você pode escolher 1 monstro com a face para cima no campo; coloque-o com a face para cima na Zona de Magias & Armadilhas do seu dono como uma Magia Contínua. \r\nVocê só pode usar este efeito de "Dragão Condenado Olho de Cobra" uma vez por turno.','\r',char(13)),'\n',char(10)),'Colocar com a face para cima','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58074177,'Dragão Alado de Olhos Anômalos',replace(replace('Escala de Pêndulo = 10\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno, antes do cálculo de dano, se um monstro seu batalhar um monstro do oponente: até o final da Etapa de Dano, você pode fazer com que seu monstro ganhe ATK igual ao ATK do monstro do oponente.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\n1 Regulador de TREVAS + 1 monstro "Asas Transparentes" não-Regulador	\r\nSe este card na Zona de Monstros for destruído: você pode colocar este card na sua Zona de Pêndulo. \r\nVocê só pode usar 1 dos seguintes efeitos de "Dragão Alado de Olhos Anômalos" por turno e apenas uma vez por turno.\r\n● Você pode escolher 1 Monstro de Efeito que seu oponente controla; negue seus efeitos até o final deste turno.\r\n● Durante a Fase de Batalha, se você controlar este card Invocado por Invocação-Sincro (Efeito Rápido): você pode destruir todos os monstros de Nível 5 ou mais que seu oponente controla.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58074572,'Mooyan Curry','Escolha 1 jogador; esse jogador ganha 200 Pontos de Vida.','Recupere 200 PV','Seu oponente recupera 200 PV','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58083496,'Dragão de Substituição de Olhos Anômalos',replace(replace('2+ monstros, incluindo um Monstro Pêndulo	\r\nVocê pode escolher 1 outro card que você controla; destrua-o e, se isso acontecer, compre 1 card. \r\nDurante o seu turno, quando seu oponente ativar um card ou efeito (Efeito Rápido): você pode descartar 1 card; negue esse efeito. \r\nVocê só pode usar cada um dos efeitos anteriores de "Dragão de Substituição de Olhos Anômalos" uma vez por turno. \r\nSe você destruiu um Card de Monstro Pêndulo com o primeiro efeito deste card, durante sua Fase Principal neste turno, você pode conduzir 1 Invocação-Pêndulo de um ou mais monstros "Camarartista", um ou mais Monstros Pêndulo "Mago" e/ou um ou mais monstros "Olhos Anômalos", em adição à sua Invocação-Pêndulo (padrão) (você só pode se aproveitar deste efeito uma vez por turno).','\r',char(13)),'\n',char(10)),'Destruir','Negar o efeito','Invocação Pêndulo usando o efeito de "Dragão Sobreescrevedor de Olhos Anômalos"','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58092907,'Camarartista Mago Celestial',replace(replace('Escala de Pêndulo = 8\r\n[ Efeito de Pêndulo ]\r\nQuando exatamente 1 Monstro de Fusão, Sincro ou Xyz com a face para cima que você controla que foi Invocado por Invocação-Especial do Deck Adicional for destruído em batalha ou por um efeito de card do oponente: você pode Invocar por Invocação-Especial esse monstro destruído e, depois, destrua este card. \r\nVocê só pode usar este efeito de "Camarartista Mago Celestial" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nDurante sua Fase Principal, se este card foi Invocado por Invocação-Normal ou Especial neste turno: você pode aplicar o(s) seguinte(s) efeito(s) pelo resto deste turno, de acordo com os outros monstros que você controla atualmente.\r\n● Fusão: Este card pode atacar diretamente.\r\n● Sincro: Seu oponente não pode ativar efeitos de monstro.\r\n● Xyz: O ATK deste card se torna o dobro do seu ATK original.\r\n● Pêndulo: Durante a Fase Final, adicione 1 Monstro Pêndulo do seu Deck à sua mão.	\r\nVocê só pode usar este efeito de "Camarartista Mago Celestial" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58098303,'Ogro Flamejante',replace(replace('Este card não pode ser Invocado por Invocação-Especial. \r\nQuando este card for Invocado por Invocação-Normal, compre 1 card.','\r',char(13)),'\n',char(10)),'Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58116537,'Saga dos Guerreiros Antigos - Aliança Sun-Liu',replace(replace('Se você controlar monstros "Guerreiros Antigos" com 2 ou mais Atributos diferentes: você pode declarar 1 Atributo; até o final deste turno, seu oponente não pode ativar os efeitos dos monstros que ele controla atualmente com esse Atributo (mesmo que este card deixe o campo). \r\nSe seu oponente Invocar um ou mais monstros por Invocação-Especial, ou você ativar um efeito de monstro "Guerreiros Antigos" (exceto durante a Etapa de Dano): até o final deste turno, você pode fazer com que todos os monstros "Guerreiros Antigos" que você controla ganhem 300 de ATK para cada monstro "Guerreiros Antigos" que você controla (mesmo que este card deixe o campo). \r\nVocê só pode usar cada efeito de "Saga dos Guerreiros Antigos - Aliança Sun-Liu" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Aumentar ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58120309,'Estrada da Luz Estrelada','Quando um card ou efeito que destruiria 2 ou mais cards que você controla for ativado: negue o efeito e, se isso acontecer, destrua esse card e, depois, você pode Invocar por Invocação-Especial 1 "Dragão da Poeira Estelar" do seu Deck Adicional.','Invocação Especial?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58131925,'Asanegra - Damascus, a Noite Polar','Durante o turno de qualquer duelista: você pode descartar este card para escolher 1 monstro "Asanegra" que você controla; ele ganha 500 de ATK até a Fase Final.','Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58132856,'Mago de Brinquedo',replace(replace('Você pode Baixar este card da sua mão em sua Zona de Cards de Magia & Armadilha como uma Magia. \r\nDurante a Fase Final, se este card Baixado em sua Zona de Cards de Magia & Armadilha tiver sido destruído por um efeito de card do oponente e enviado ao Cemitério neste turno: Invoque este card por Invocação-Especial. \r\nSe este card for Invocado por Invocação-Virar: Destrua Magias e Armadilhas no campo igual ao número de "Mago de Brinquedo" no campo.','\r',char(13)),'\n',char(10)),'Invocação Especial','Destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58139128,'Xamã do Coveiro',replace(replace('Ganha 200 de DEF para cada monstro "do Coveiro" no seu Cemitério. \r\nNegue todos os efeitos de monstro que ativam no Cemitério, exceto de monstros "do Coveiro". \r\nEnquanto "Necro-Vale" estiver no campo, seu oponente não pode ativar Cards de Magia de Campo e, além disso, Cards de Magia de Campo não podem ser destruídos por efeitos de card do seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58139997,'Fazticeira Edel',replace(replace('(Efeito Rápido): você pode descartar 1 Magia; Invoque por Invocação-Especial 1 monstro "Fazticeira" da sua mão, exceto "Fazticeira Edel". \r\nVocê pode oferecer este card como Tributo e, depois, escolher 1 monstro Mago no seu Cemitério, exceto "Fazticeira Edel"; Invoque-o por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Fazticeira Edel" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial da mão','Invocar por Invocação Especial do Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58143766,'Emissão Vulcânica',replace(replace('Ative 1 desses efeitos (mas você só pode usar cada efeito de "Emissão Vulcânica" uma vez por turno);\r\n● Pegue 1 monstro "Vulcânico(a)" do seu Deck e adicione-o à sua mão ou Invoque-o por Invocação-Especial, ignorando suas condições de Invocação, mas devolva-o para a mão durante a Fase Final.\r\n● Escolha 1 monstro Piro no campo; cause dano ao seu oponente igual ao ATK original desse monstro ou, se você escolheu um monstro que você controla, o dano é diminuído pela metade.','\r',char(13)),'\n',char(10)),'Adicionar à mão ou Invocar por Invocação Especial','Cause dano ao seu oponente','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58143852,'Aprendiz do Pesadelo',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) ao descartar 1 card. \r\nVocê só pode Invocar "Aprendiz do Pesadelo" por Invocação-Especial uma vez por turno desta forma. \r\nSe este card batalhar um monstro, nenhum dos dois pode ser destruído nessa batalha. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 monstro Ilusão do seu Deck à sua mão, exceto "Aprendiz do Pesadelo". \r\nVocê só pode usar este efeito de "Aprendiz do Pesadelo" uma vez por turno.','\r',char(13)),'\n',char(10)),'Buscar 1 monstro Ilusão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58143853,'Aprendiz do Pesadelo',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) ao descartar 1 card. \r\nVocê só pode Invocar "Aprendiz do Pesadelo" por Invocação-Especial uma vez por turno desta forma. \r\nSe este card batalhar um monstro, nenhum dos dois pode ser destruído nessa batalha. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 monstro Ilusão do seu Deck à sua mão, exceto "Aprendiz do Pesadelo". \r\nVocê só pode usar este efeito de "Aprendiz do Pesadelo" uma vez por turno.','\r',char(13)),'\n',char(10)),'Buscar 1 monstro Ilusão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58147549,'Goka, o HERÓI Mascarado',replace(replace('Deve ser Invocado por Invocação-Especial com "Mudar a Máscara". 	\r\nGanha 100 de ATK para cada monstro "HERÓI" no seu Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58153103,'Dragão Armado do Trovão LV10',replace(replace('Se este card foi Invocado por Invocação-Especial pelo efeito de um monstro "Dragão Armado", ele ganha os seguintes efeitos de acordo com seu ATK.\r\n● 1+: Seu nome se torna "Dragão Armado LV10".\r\n● 10+: Seu controle não pode ser trocado.\r\n● 100+: Não pode ser destruído em batalha.\r\n● 1000+: Uma vez por turno do oponente (Efeito Rápido): você pode enviar 1 card da sua mão para o Cemitério e, depois, escolha 1 outro card no campo; destrua-o e, se isso acontecer, este card ganha 1000 de ATK.\r\n● 10000+: Uma vez por turno: você pode destruir todos os outros cards no campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58165765,'Ninja do Dragão Vermelho',replace(replace('Quando este card for Invocado: você pode banir 1 card "Ninja" ou "Ninjitsu" do seu Cemitério e, depois, escolher 1 card Baixado que seu oponente controla; revele o card Baixado e, depois, devolva-o para o topo ou para o fundo do Deck. \r\nSeu oponente não pode ativar o card escolhido em resposta à ativação deste efeito. \r\nVocê só pode usar este efeito de "Ninja do Dragão Vermelho" uma vez por turno.','\r',char(13)),'\n',char(10)),'Retornar ao Deck','Retornar ao topo do Deck','Retornar ao fundo do Deck','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58169731,'Parede da Disrupção','Quando um monstro do oponente declarar um ataque: todos os monstros em Posição de Ataque que seu oponente controla atualmente perdem 800 de ATK para cada monstro que ele controla.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58185394,'Kozaky Gigante',replace(replace('Se não existir nenhum "Kozaky" no Campo com a face para cima, destrua este card. \r\nSe este card no Campo com a face para cima é destruído, inflija ao Life Points do controlador deste card dano igual ao ATK original deste card.','\r',char(13)),'\n',char(10)),'Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58192742,'Pequeno Moth','É melhor evitar ficar perto desta criatura que, embora pequena, é extremamente mortífera.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58199906,'Suporte à Fusão Cibernética',replace(replace('Pague metade dos seus PV; uma vez, se você Invocar por Invocação-Fusão um Monstro de Fusão Máquina neste turno, você pode banir monstros da sua mão, do campo e/ou do Cemitério como Matérias de Fusão. \r\nVocê só pode ativar 1 "Suporte à Fusão Cibernética" por turno.','\r',char(13)),'\n',char(10)),'Usar o efeito de "Suporte à Fusão Cibernética"?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58201062,'Espectral, Dragão Soberano das Cintilações',replace(replace('Você pode descartar este card e 1 monstro Dragão ou de LUZ; adicione 2 monstros "Dragão Soberano" do seu Deck à sua mão, exceto "Espectral, Dragão Soberano das Cintilações". \r\nVocê pode banir do seu Cemitério este card e 1 monstro Dragão ou de LUZ e, depois, escolha 1 "Chasma, Dragão Soberano das Auroras" no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê só pode usar 1 efeito de "Espectral, Dragão Soberano das Cintilações" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Efeito de busca','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58203736,'Furtivo do Mar II',replace(replace('O nome deste card se torna "Umi" enquanto estiver no campo ou no Cemitério. \r\nSeu oponente não pode escolher monstros de ÁGUA que você controla como alvo de efeitos de monstros que não sejam de ÁGUA. \r\nNo começo da Fase de Batalha: você pode Invocar por Invocação-Especial da sua mão ou do Cemitério, 1 monstro que mencione "Umi", ou 1 Monstro Normal de ÁGUA, em Posição de Defesa, mas destrua-o no final da Fase de Batalha. \r\nVocê só pode usar este efeito de "Furtivo do Mar II" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58205203,'Mariamne do Paradoxo, a Verdadeira Dracofênix Cavaleira',replace(replace('Para Invocar este card por Invocação-Tributo com a face para cima, você pode oferecer como Tributo Magias/Armadilhas Contínuas que você controla, assim como monstros. \r\nVocê só pode usar cada um dos seguintes efeitos de "Mariamne do Paradoxo, a Verdadeira Dracofênix Cavaleira" uma vez por turno. \r\nSe este card estiver na sua mão: você pode destruir 1 outro card "Verdadeiro(a) Draco" ou "Verdadeiro Rei" na sua mão ou no seu campo com a face para cima e, se isso acontecer, Invoque este card por Invocação-Especial em qualquer campo. \r\nSe este card for Invocado por Invocação-Normal ou Especial da mão: bana os 4 cards do topo do seu Deck.','\r',char(13)),'\n',char(10)),'Invocação Especial','Banir','Invocar por Invocação Especial para o seu Campo','Invocar por Invocação Especial para o Campo do seu oponente','','','','','','','','','','','','');
INSERT INTO texts VALUES(58206034,'Lucius das Trevas LV8','Se este card foi Invocado por Invocação-Especial pelo efeito de "Lucius das Trevas LV6", bana os monstros do seu oponente destruídos em batalha com este card e, além disso, negue seus efeitos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58242947,'Colecionador Sucata',replace(replace('(Efeito Rápido): você pode banir este card no campo e 1 Armadilha Normal no seu Cemitério; aplique o efeito dessa Armadilha banida. \r\n(Os requisitos de ativação da Armadilha ainda devem estar corretos, mas nenhum custo é pago.)','\r',char(13)),'\n',char(10)),'Ganhar e ativar o efeito de uma Armadilha Normal no Cemitério','Escolher um Card de Armadilha Normal','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58257569,'Dragão Filhote de Olhos Vermelhos',replace(replace('Quando este card for destruído em batalha e enviado para o Cemitério: você pode Invocar por Invocação-Especial 1 monstro "Olhos Vermelhos" de Nível 7 ou menos do seu Deck e, se isso acontecer, equipe este card do Cemitério a ele. \r\nEle ganha 300 de ATK. \r\nSe este card for enviado para o Cemitério enquanto estiver equipado a um monstro: você pode adicionar 1 monstro Dragão de Nível 1 do seu Deck ou Cemitério à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58258899,'TGX300','Todos os monstros com a face para cima que você controla ganham 300 de ATK para cada monstro "T.G." que você controla.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58268433,'Coelho Lâmina','Quando este card é mudado de Posição de Ataque para Posição de Defesa com a face para cima, destrúa 1 monstro no Campo do seu adversário.','Destrua 1 monstro que seu oponente controla','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58270977,'Alquimista do Magistério',replace(replace('Bana 4 monstros "HERÓI" do seu Cemitério e/ou do campo com a face para cima e, depois, escolha 1 monstro "HERÓI" no seu Cemitério; Invoque-o por Invocação-Especial, ignorando suas condições de Invocação. \r\nSe você baniu os Atributos TERRA, ÁGUA, FOGO e VENTO para ativar este efeito, o ATK original desse monstro se torna o dobro e, além disso, negue os efeitos de todos os cards com a face para cima que seu oponente controla atualmente. \r\nVocê só pode ativar 1 "Alquimista do Magistério" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58272005,'Sobrevivência do Mais Apto',replace(replace('Escolha 1 monstro do Tipo Dinossauro que você controla; equipe este card no alvo. \r\nEle ganha 1000 de ATK. \r\nQuando esse monstro atacante destruir um monstro do oponente em batalha e enviá-lo para o Cemitério: você pode ativar este efeito; o monstro equipado pode realizar um segundo ataque em seguida contra um monstro do oponente.','\r',char(13)),'\n',char(10)),'Continuar atacando','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58288218,'Fornalha, o HERÓI Mascarado',replace(replace('Você pode revelar este card na sua mão; adicione 1 "Mudar a Máscara" ou "Polimerização" do seu Deck à sua mão e, depois, descarte 1 card. \r\nVocê não pode Invocar por Invocação-Especial do Deck Adicional no turno em que ativar este efeito, exceto monstros "HERÓI". \r\nSe você Invocar por Invocação-Especial um ou mais Monstros de Fusão "HERÓI" que não sejam de FOGO (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial do seu Cemitério (se ele estava lá quando a Invocação resolveu) ou da mão (mesmo se ele não estava), mas bana-o quando ele deixar o campo. \r\nVocê só pode usar cada efeito de "Fornalha, o HERÓI Mascarado" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58288565,'Peixe-Borboleta',replace(replace('Se este card for enviado para o Cemitério para ativar um efeito de monstro: você pode adicionar este card à sua mão. \r\nSe um ou mais monstros forem enviados para o seu Cemitério, exceto em batalha, enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode descartar 1 card para o Cemitério; Invoque este card por Invocação-Especial. \r\nVocê só pode usar 1 efeito de "Peixe-Borboleta" por turno e apenas uma vez por turno. \r\nVocê não pode Invocar monstros do Deck Adicional por Invocação-Especial, exceto monstros de ÁGUA, no turno em que ativar qualquer um dos efeitos deste card.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58293343,'Dragão da Explosão Tirana',replace(replace('Deve ser Invocado por Invocação-Especial com "A Presa de Critias", usando "Asa Tirana". 	\r\nEste card pode atacar todos os monstros do seu oponente, uma vez cada. \r\nVocê pode escolher 1 monstro com a face para cima que você controla; equipe este monstro no alvo. \r\nEle ganha 400 de ATK/DEF e, além disso, ele pode realizar 3 ataques durante cada Fase de Batalha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58297729,'Engrenagem de Transmissão',replace(replace('Durante o cálculo de dano, se um monstro seu batalhar um monstro do oponente: jogue pedra, papel e tesoura com seu oponente. \r\nFaça com que o duelista perdedor bana, com a face para baixo, o monstro que estiver batalhando que ele controla.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58308221,'Pêndulo Extra',replace(replace('Durante sua Fase Principal deste turno, você pode conduzir 1 Invocação-Pêndulo de um ou mais monstros do seu Deck Adicional em adição à sua Invocação-Pêndulo padrão. \r\n(Você só pode se aproveitar deste efeito uma vez por turno.)','\r',char(13)),'\n',char(10)),'Invocação Pêndulo usando o efeito de "Pêndulo Extra"','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58314394,'Bugroth de Ataque Terrestre',replace(replace('Um robô de batalha terrestre que já foi usado em combates marítimos.	\r\n\r\n(Este card não é considerado como um card "Terrestre".)','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58324930,'Monge Anarquista Ranshin','Se este card for enviado do seu campo para o seu Cemitério por um card do oponente: escolha 1 monstro no Cemitério do seu oponente; bana o alvo.','Banir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58330108,'Gandora Gigaraios, o Dragão da Destruição',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro deve ser Invocado por Invocação-Especial (da sua mão) ao enviar 2 outros monstros da sua mão e/ou do campo para o Cemitério. \r\nGanha 300 de ATK para cada card banido. \r\nUma vez por turno: você pode pagar metade dos seus PV; aplique 1 dos seguintes efeitos, de acordo com o número de monstros "Gandora" com nomes diferentes no seu Cemitério.\r\n● 1: Destrua todos os outros cards no campo.\r\n● 2: Bana todos os outros cards no campo.\r\n● 3+: Bana todos os outros cards no campo e nos Cemitérios.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58332301,'HERÓI Maligno Gaia das Trevas',replace(replace('1 monstro Demônio + 1 monstro Rocha	\r\nDeve ser Invocado por Invocação-Especial com "Fusão Negra". \r\nO ATK original deste card se torna o ATK original combinado das matérias usadas para sua Invocação-Fusão. \r\nQuando este card declarar um ataque: você pode colocar todos os monstros em Posição de Defesa que seu oponente controla em Posição de Ataque com a face para cima. \r\n(Efeitos de Virar não são ativados neste momento.)','\r',char(13)),'\n',char(10)),'Mudar a posição de batalha','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58346901,'Infernobre Cavaleiro Oliver',replace(replace('Enquanto este card for um Card de Equipamento, seu oponente não pode escolher o monstro equipado como alvo de efeitos de card. \r\nVocê só pode usar cada um dos seguintes efeitos de "Infernobre Cavaleiro Oliver" uma vez por turno. \r\nVocê pode enviar 1 monstro Guerreiro de FOGO ou 1 Magia de Equipamento da sua mão ou do campo com a face para cima para o Cemitério; Invoque este card por Invocação-Especial da sua mão como um monstro de Nível 1. \r\nSe este card estiver no seu Cemitério: você pode escolher 1 monstro Guerreiro que você controla; equipe este card a esse monstro que você controla.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58354899,'Vulcarrion, a Fênix Apodrecida',replace(replace('Se você controlar um monstro Zumbi: você pode Invocar este card por Invocação-Especial da sua mão. \r\nDurante sua Fase Principal: você pode devolver este card do campo para a mão e, depois, você pode Invocar por Invocação-Especial 1 monstro Zumbi da sua mão. \r\nVocê só pode usar cada efeito de "Vulcarrion, a Fênix Apodrecida" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Retornar para a mão','Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58363151,'Força-S Pla-Tina',replace(replace('Cada um dos monstros do seu oponente na mesma coluna que um dos seus monstros "Força-S" perde 600 de ATK. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 dos seus monstros "Força-S" banidos, exceto "Força-S Pla-Tina"; Invoque-o por Invocação-Especial. \r\nVocê só pode usar este efeito de "Força-S Pla-Tina" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58369990,'Mago da Destrela','Uma vez por turno: você pode descartar 1 card e, depois, escolher 1 card na Zona de Pêndulo de qualquer duelista; destrua esse card e, se isso acontecer, compre 1 card.','Destruir Magias/Armadilhas','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58371671,'Égide Cristalino',replace(replace('Escolha 1 Card de Monstro "Fera Cristalina" que você controla; destrua-o e, depois, Invoque por Invocação-Especial 1 "Ficha de Fera Cristalina" com o Tipo, Atributo, Nível e ATK/DEF originais do monstro destruído. \r\nSe um ou mais cards "Fera Cristalina" forem colocados na sua Zona de Magias & Armadilhas enquanto este card estiver no seu Cemitério, mesmo durante a Etapa de Dano: você pode banir este card; Invoque por Invocação-Especial 1 Card de Monstro "Fera Cristalina" da sua Zona de Magias & Armadilhas. \r\nVocê só pode usar este efeito de "Égide Cristalino" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58371672,'Ficha de Fera Cristalina','Invocado por Especial com o efeito "Égide Cristalino".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58374502,'Explosão de Cavalestrela',replace(replace('Quando seu oponente ativar um card ou efeito: devolva para a mão 1 monstro Dragão de LUZ de Nível 7 que você controla; negue o efeito e, se isso acontecer, destrua esse card. \r\nVocê só pode ativar "Explosão de Cavalestrela" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58374719,'Luta do Legado Mundial','Escolha Magias/Armadilhas no campo, até o número de monstros co-linkados no campo; destrua-as.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58383100,'Cavaleiro Espelho Críptico',replace(replace('Quando um monstro "Críptico(a)" que você controla for destruído em batalha e enviado para o seu Cemitério: você pode descartar este card; envie 1 card da sua mão ou do campo para o Cemitério e, se isso acontecer, Invoque esse monstro destruído por Invocação-Especial. \r\nDurante a Fase Final, se este card estiver no Cemitério porque foi enviado para lá neste turno: você pode adicionar 1 card "Críptico(a)" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Cavaleiro Espelho Críptico" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58392024,'Despolimerização',replace(replace('Você pode ativar este card apenas quando um Monstro de Fusão é Invocado, por Invocação-Especial. \r\nDevolva todos os Monstros de Fusão no Campo com a face para cima para os respectivos Decks de Fusão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58400390,'Postulado pelo Cálice Mundial','Sua batalha contra as Mekkstruosidade parece nunca terminar. Mesmo quando sua floresta foi invadida por Insetos Mekkstruosos, ele permaneceu firme e inspirou os demais defensores ao seu redor.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58406094,'Céu de Cavalestrela',replace(replace('Durante sua Fase Principal, você pode Invocar por Invocação-Normal 1 monstro "Cavalestrela" ou 1 monstro Dragão de LUZ de Nível 7 em adição à sua Invocação-Normal/Baixar (padrão). \r\n(Você só pode se aproveitar deste efeito uma vez por turno.) \r\nDurante o seu turno, se um monstro Dragão de LUZ de Nível 7 com a face para cima que você controla for devolvido à mão: você pode comprar 1 card. \r\nVocê só pode usar este efeito de "Céu de Cavalestrela" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar pelo efeito de "Céu de Cavalestrela"','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58415502,'Sequência Real','Envie para o Cemitério 1 "O Cavaleiro da Rainha", "O Cavaleiro do Rei" e "O Cavaleiro do Valete" da sua mão e/ou da Zona de Monstros com a face para cima e, depois, Invoque por Invocação-Especial 1 monstro da sua mão, do Deck, do Deck Adicional ou do Cemitério que mencione todos dentre "O Cavaleiro da Rainha", "O Cavaleiro do Rei" e "O Cavaleiro do Valete".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58419204,'Instinto de Sobrevivência','Bana qualquer número de monstros do Tipo Dinossauro no seu Cemitério; ganhe 400 Pontos de Vida para cada monstro do Tipo Dinossauro banido para ativar este card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58421530,'Permutador Tático',replace(replace('Escolha 1 monstro com a face para cima que você controla; destrua-o e, se isso acontecer, Invoque por Invocação-Especial 1 monstro "Foguette" com um nome original diferente do seu Deck ou Cemitério. \r\nVocê só pode ativar 1 "Permutador Tático" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58441120,'Ondas Harmônicas','Escolha 1 monstro com a face para cima no campo; ele se torna de Nível 4 até a Fase Final.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58446973,'Infernoide Decatron','Se este card for Invocado por Invocação-Normal ou Especial: você pode enviar 1 monstro "Infernoide" do seu Deck para o Cemitério, exceto "Infernoide Decatron" e, se isso acontecer, aumente o Nível deste card pelo Nível do monstro enviado e, se isso acontecer, o nome deste card se torna o nome original desse monstro e substitua este efeito pelos efeitos originais desse monstro.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58453942,'Lesma Psíquica',replace(replace('Você pode pagar 800 PV e selecionar 1 outro monstro do Tipo Psíquico com a face para cima que você controla. \r\nEsse monstro pode atacar duas vezes durante cada Fase de Batalha. \r\nEste card não pode atacar no turno em que você ativar este efeito.','\r',char(13)),'\n',char(10)),'Ataques múltiplos','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58464739,'Minas de Pulso','Se você controlar um monstro Máquina: coloque os monstros em Posição de Ataque do seu oponente (se houver), em Posição de Defesa e, além disso, até o final deste turno, se um ou mais monstros forem Invocados por Invocação-Normal ou Especial no campo do seu oponente, coloque-os em Posição de Defesa.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58468105,'Marinoite Peladura Perigosa',replace(replace('1 monstro "Diabrete de" + 2 monstros "Fofanimal"	\r\nGanha 300 de ATK para cada monstro Fada e Demônio no seu Cemitério, apenas durante o seu turno. \r\nQuando este card Invocado por Invocação-Fusão destruir um monstro em batalha: você pode enviar monstros "Peladura", "Fofanimal" e/ou "Diabrete de" do seu Deck para o Cemitério, igual ao Nível original desse monstro destruído. \r\nQuando seu oponente ativar um card ou efeito que escolha como alvo este card no campo (Efeito Rápido): você pode banir 1 monstro "Peladura" do seu Deck Adicional; negue o efeito.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58471134,'Sirena Abispiga',replace(replace('Quando este card for Invocado por Invocação-Normal ou Especial: você pode descartar 1 monstro de ÁGUA para o Cemitério; adicione 1 monstro de ÁGUA de Nível 3 do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Sirena Abispiga" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58475908,'Caracol de Corda',replace(replace('Durante sua Fase Principal: Você pode escolher 1 card Baixado no campo; devolva o alvo para a mão. \r\nEste efeito só pode ser usado uma vez, enquanto este card estiver com a face para cima no campo.','\r',char(13)),'\n',char(10)),'Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58477767,'Seleção da Rainha','Quando um monstro "Amazoness" que você controla destruir um monstro do oponente em batalha e enviá-lo para o Cemitério: Invoque por Invocação-Especial 1 monstro "Amazoness" de Nível 4 ou menos do seu Deck.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58481572,'Lei Obscura, o HERÓI Mascarado',replace(replace('Deve ser Invocado por Invocação-Especial com "Mudar a Máscara". 	\r\nQualquer card enviado para o Cemitério do seu oponente, em vez disso, é banido. \r\nUma vez por turno, se seu oponente adicionar um ou mais cards do Deck dele para a mão dele (exceto durante a Fase de Compra ou Etapa de Dano): você pode banir 1 card aleatório da mão do seu oponente.','\r',char(13)),'\n',char(10)),'Banir 1 card','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58481573,'Lei Obscura, o HERÓI Mascarado',replace(replace('Deve ser Invocado por Invocação-Especial com "Mudar a Máscara". 	\r\nQualquer card enviado para o Cemitério do seu oponente, em vez disso, é banido. \r\nUma vez por turno, se seu oponente adicionar um ou mais cards do Deck dele para a mão dele (exceto durante a Fase de Compra ou Etapa de Dano): você pode banir 1 card aleatório da mão do seu oponente.','\r',char(13)),'\n',char(10)),'Banir 1 card','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58494728,'Girastag Hordeum Ferro',replace(replace('Você pode Invocar este card por Invocação-Tributo com a face para cima em Posição de Ataque ao oferecer como Tributo 1 monstro "Hordeum Ferro". \r\nQuando este card for Invocado por Invocação-Tributo ao oferecer como Tributo um ou mais monstros "Hordeum Ferro": Você pode escolher 1 card que seu oponente controla; envie esse alvo para o Cemitério e ganhe 1000 PV.','\r',char(13)),'\n',char(10)),'Invocação Tributo usando 1 monstro','Enviar para o Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58504745,'Irmandade do Punho de Fogo - Cardeal',replace(replace('2 monstros "Punho de Fogo" de Nível 4	\r\nVocê pode desassociar 2 matérias deste card e, depois, escolha 2 cards "Punho de Fogo" / "Formação de Fogo" no seu Cemitério e/ou no campo com a face para cima e 2 cards no Cemitério e/ou no campo com a face para cima do seu oponente; embaralhe os alvos no Deck. \r\nVocê só pode usar o efeito de "Irmandade do Punho de Fogo - Cardeal" uma vez por turno.','\r',char(13)),'\n',char(10)),'Retornar ao Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58518520,'Efector de Limpeza',replace(replace('Se este card for enviado para o Cemitério como uma Matéria Sincro: compre 1 card. \r\nUm Monstro Sincro que usou este card como uma Matéria Sincro não pode ser destruído por efeitos de card.','\r',char(13)),'\n',char(10)),'Compre 1 card(s)','O efeito de "Efector de Limpeza" está sendo aplicado.','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58528964,'Fantasma da Chama','"Servo Caveira" + "Dissolve-rocha"','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58531587,'Portador das Bolhas',replace(replace('Monstros de Nível 4 ou mais não podem atacar diretamente. \r\nDurante o seu turno: Você pode enviar este card com a face para cima do campo para o Cemitério para escolher 2 monstros de ÁGUA de Nível 3 ou menos com o mesmo nome no seu Cemitério; Invoque os alvos por Invocação-Especial. \r\nSeus efeitos são negados.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58538870,'Pessoas Oprimidas','Eles são oprimidos, mas acreditam que algum dia serão livres.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58543073,'Velocidaroide Dupliportal',replace(replace('Bana 1 monstro de VENTO do seu Cemitério e, depois, escolha 1 card que seu oponente controla; devolva-o para a mão. \r\nDurante sua Fase Principal, se este card estiver no seu Cemitério: você pode escolher 1 monstro "Velocidaroide" de Nível 2 ou mais que você controla; reduza o Nível dele em 1 e, se isso acontecer, Invoque este card por Invocação-Especial como um Monstro Normal (Máquina/Regulador/VENTO/Nível 1/ATK 0/DEF 0).	\r\n(Este card NÃO é considerado como uma Armadilha.) \r\nVocê só pode usar este efeito de "Velocidaroide Dupliportal" uma vez por Duelo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58549532,'Fusão Parametalmorfose',replace(replace('Invoque por Invocação-Fusão 1 Monstro de Fusão "Metalmorfose" do seu Deck Adicional, usando como Matéria de Fusão até 1 monstro cada da sua mão, do campo e/ou do Deck Adicional com a face para cima. \r\nVocê só pode ativar 1 "Fusão Parametalmorfose" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58551308,'Idiota da Lança','VIRE: Quando este card for enviado do campo para o Cemitério depois de ser virado com a face para cima: cada duelista escolhe 1 monstro no seu próprio Cemitério, exceto este card; cada duelista Invoca seu alvo por Invocação-Especial com a face para cima em Posição de Ataque ou com a face para baixo em Posição de Defesa.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58554959,'HERÓI Maligno Malicious Edge',replace(replace('Se seu oponente controlar um monstro, você pode Invocar este card por Invocação-Tributo com a face para cima oferecendo 1 Tributo. \r\nSe este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante.','\r',char(13)),'\n',char(10)),'Ofereça 1 monstro como Tributo para Invocar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58569561,'Aromágico Alecrim',replace(replace('Enquanto seus PV forem maiores que os do seu oponente, se um monstro Planta que você controla atacar, seu oponente não pode ativar efeitos de monstro até o final da Etapa de Dano. \r\nUma vez por turno, se você ganhar PV: escolha 1 monstro com a face para cima no campo; mude sua posição de batalha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58570206,'Polimerização Pesada',replace(replace('Invoque por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional, usando 3 ou mais monstros da sua mão ou do campo. \r\nVocê também pode banir monstros do seu Deck Adicional como matéria, até o número de monstros que seu oponente controla, mas você perde PV igual à soma do ATK dos monstros banidos desta forma, quando o monstro for Invocado por Invocação-Fusão.','\r',char(13)),'\n',char(10)),'Invocação Fusão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58577036,'Raciocínio',replace(replace('Seu oponente declara um Nível de monstro de 1 a 12. \r\nEscave cards do topo do seu Deck até escavar um monstro que possa ser Invocado por Invocação-Normal/Baixado e, depois, se esse monstro for do mesmo Nível que o declarado pelo seu oponente, envie todos os cards escavados para o Cemitério. \r\nCaso contrário, Invoque o monstro escavado por Invocação-Especial e, além disso, envie os cards restantes para o Cemitério.','\r',char(13)),'\n',char(10)),'Declare o Nível do monstro','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58582979,'Dragão Defrag',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) ao enviar 1 outro monstro da sua mão para o Cemitério. \r\nVocê só pode Invocar "Dragão Defrag" por Invocação-Especial uma vez por turno desta forma. \r\nSe este card estiver no Cemitério: você pode banir 3 monstros com o mesmo nome do seu Cemitério, exceto "Dragão Defrag"; Invoque este card por Invocação-Especial. \r\nVocê só pode usar este efeito de "Dragão Defrag" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58589739,'Força-S Professor DiGama',replace(replace('Cada um dos monstros do seu oponente na mesma coluna que um dos seus monstros "Força-S" não pode mudar sua posição de batalha. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 monstro com a face para cima que seu oponente controla; mude a posição de batalha dele. \r\nVocê só pode usar este efeito de "Força-S Professor DiGama" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58600555,'Inseto Digital Borbonúcleo',replace(replace('2 ou mais monstros de LUZ do Tipo Inseto de Nível 5	\r\nVocê também pode Invocar este card por Invocação-Xyz ao desassociar 2 Matérias Xyz de um Monstro Xyz do Tipo Inseto de Classe 3 ou 4 que você controla e, depois, usar esse Monstro Xyz como Matéria Xyz. \r\n(Matérias Xyz associadas a esse monstro também se tornam Matérias Xyz neste card.) \r\nUma vez por turno: você pode desassociar 1 Matéria Xyz deste card e, depois, escolher 1 monstro em Posição de Defesa que seu oponente controla; embaralhe-o no Deck. \r\nUma vez por turno, se a posição de batalha de um ou mais monstros no campo for mudada (exceto durante a Etapa de Dano): você pode associar 1 monstro do Tipo Inseto do seu Cemitério a este card como uma Matéria Xyz.','\r',char(13)),'\n',char(10)),'Retornar ao Deck do dono','Associar Matéria Xyz','Invocar por Invocação Xyz sobrepondo em cima de um Monstro Xyz?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58601383,'Gaia Drake, a Força Universal',replace(replace('1 "Cavaleiro Gaia, a Força da Terra" + 1 Monstro Sincro que não seja de Efeito	\r\nEste card não pode ser escolhido como alvo ou destruído por efeitos de Monstros de Efeito.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58604027,'O Lendário Exodia Encarnado',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao oferecer como Tributo 1 monstro "O Proibido". \r\nGanha 1000 de ATK para cada monstro "O Proibido" no seu Cemitério. \r\nNão é afetado por outros efeitos de cards. \r\nUma vez por turno, durante sua Fase Final: adicione 1 monstro "O Proibido" do seu Cemitério à sua mão. \r\nQuando este card for destruído em batalha e enviado para o Cemitério: você pode revelar qualquer número de monstros "O Proibido" na sua mão e, se isso acontecer, compre 1 card para cada.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58607704,'Espelho de Mão do Demônio','Troque para outro alvo apropriado o efeito de um Card de Magia do oponente que escolha como alvo 1 Card de Magia ou Armadilha.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58616392,'Cãodenação Oirthros',replace(replace('Se este card for enviado do campo para o Cemitério: adicione 1 monstro do Tipo Demônio de Nível 8 do seu Deck para a sua mão. \r\nVocê só pode usar este efeito de "Cãodenação Oirthros" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58621589,'Sombra dos Olhos',replace(replace('Quando um ou mais monstros forem Baixados no campo do seu oponente: escolha 1 desses monstros Baixados; coloque esse monstro Baixado com a face para cima em Posição de Ataque. \r\n(Efeitos de Virar não são ativados.)','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58628539,'Efeito Xyz','Quando você Invocar um monstro por Invocação-Xyz: você pode escolher 1 card no campo; destrua-o.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58641905,'Anel da Defesa','Quando um efeito de Armadilha que cause dano for ativado: transforme em 0 esse dano de efeito.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58655504,'Gnomatéria',replace(replace('Se seu oponente Invocar um ou mais monstros por Invocação-Especial enquanto você não controlar nenhum card: você pode descartar este card e, depois, escolha 1 monstro com a face para cima que seu oponente controla; neste turno, esse monstro não pode ser oferecido como Tributo nem usado como matéria para uma Invocação-Fusão, Sincro, Xyz ou Link. \r\nVocê só pode usar este efeito de "Gnomatéria" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58657303,'Espiritualista do Coveiro',replace(replace('Durante sua Fase Principal, se "Necro-Vale" estiver no campo: você pode Invocar por Invocação-Fusão 1 Monstro de Fusão Mago do seu Deck Adicional, usando este card que você controla e outros monstros da sua mão ou do campo como Matéria de Fusão. \r\nVocê só pode usar este efeito de "Espiritualista do Coveiro" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58672736,'Dinolutador Giga Espinosavate',replace(replace('1 Regulador Dinossauro + 1+ monstros não-Reguladores	\r\nSe este card batalhar, seu oponente não pode ativar Cards de Magia/Armadilha até o final da Etapa de Dano. \r\nOs monstros do seu oponente não podem escolher monstros como alvo de ataques, exceto este. \r\nUma vez por turno: você pode escolher 1 monstro que seu oponente controla; destrua-o. \r\nSe este card seria destruído em batalha ou por um efeito de card, em vez disso, você pode destruir 1 card que você controla.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58680635,'Besta Eletrodo Anion',replace(replace('Se este card for Invocado por Invocação-Normal: você pode tornar este card de Nível 4 e, depois, você pode adicionar 1 "Conversor de Espírito" do seu Deck ou Cemitério à sua mão. \r\nVocê pode escolher 1 outro card que você controla; envie tanto ele quanto este card para o Cemitério e, se isso acontecer, compre 1 card. \r\nVocê só pode usar cada efeito de "Besta Eletrodo Anion" uma vez por turno.','\r',char(13)),'\n',char(10)),'Alterar o Nível','Comprar','Adicionar 1 "Conversor de Espírito" à sua mão?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58685438,'Bicórnio Re''em','Se este card for enviado ao Cemitério como um Monstro-Matéria Sincro para uma Invocação-Sincro, envie os 2 cards do topo do Deck do seu oponente ao Cemitério.','Enviar do Deck para o Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58695102,'Recaparar',replace(replace('Se este card estiver no Cemitério e seu oponente tiver 5 ou mais cards a mais que você no Deck Adicional dele: você pode pagar 2000 PV; Invoque este card por Invocação-Especial, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar este efeito de "Recaparar" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58696829,'Biomago','Um sacerdote misterioso criado como resultado dos recentes avanços da biotecnologia.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58699500,'Querubini, o Anjo de Ébano do Abismo Ardente',replace(replace('2 monstros de Nível 3	\r\nMonstros para o qual este card apontar não podem ser destruídos por efeitos de card. \r\nSe este card seria destruído em batalha ou por um efeito de card do oponente, em vez disso, você pode enviar 1 outro card que você controla para o Cemitério. \r\nVocê pode enviar 1 monstro de Nível 3 do seu Deck para o Cemitério e, depois, escolha 1 monstro "Abismo Ardente" no campo; até o final deste turno, ele ganha ATK/DEF igual ao ATK/DEF do monstro enviado para o Cemitério. \r\nVocê só pode usar este efeito de "Querubini, o Anjo de Ébano do Abismo Ardente" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58707981,'Desatexplosão, a Fortaleza da Negação',replace(replace('Escala de Pêndulo = 5\r\n[ Efeito de Pêndulo ]\r\nNegue quaisquer efeitos de card ativados na coluna deste card.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe houver uma coluna sem cards, você pode Invocar este card por Invocação-Especial (da sua mão) em uma zona sua nessa coluna. \r\nVocê só pode Invocar "Desatexplosão, a Fortaleza da Negação" por Invocação-Especial uma vez por turno desta forma. \r\nNegue quaisquer efeitos de card ativados na coluna deste card. \r\nSe este card na Zona de Monstros for destruído: você pode colocar este card na sua Zona de Pêndulo.','\r',char(13)),'\n',char(10)),'Colocar na Zona de Pêndulo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58712976,'Megera da Chama Infernal',replace(replace('2 monstros do Tipo Piro de Nível 4	\r\nUma vez por turno: você pode desassociar 1 Matéria Xyz deste card; este card ganha 500 de ATK até a próxima Fase Final do seu oponente. \r\nQuando este card, com ATK 2500 ou mais, for destruído: escolha 3 monstros em quaisquer Cemitérios; bana esses alvos.','\r',char(13)),'\n',char(10)),'Aumentar ATK','Banir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58720904,'Pendrasação',replace(replace('2 monstros de Nível 4	\r\nVocê pode desassociar 1 matéria deste card; se você tiver mais cards no seu Deck Adicional que o seu oponente, aplique esses efeitos em sequência, dependendo da diferença.\r\n● 1+: Este card ganha 1000 de ATK até o final do turno do seu oponente.\r\n● 5+: Nenhum duelista pode escolher este card como alvo de efeitos de card até o final do turno do seu oponente.\r\n● 10+: Bana 1 card que seu oponente controla.\r\n● 15+: Transforme os PV do seu oponente em 3000.	\r\nVocê só pode usar este efeito de "Pendrasação" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58753372,'Fada Alfan Super Quantal',replace(replace('Uma vez por turno: você pode escolher 1 monstro "Super Quant" que você controla; todos os monstros com a face para cima que você controla atualmente se tornam do Nível desse monstro. \r\nVocê pode oferecer este card como Tributo; revele 3 monstros "Super Quant" com nomes diferentes do seu Deck, seu oponente define 1 aleatoriamente para que você Invoque por Invocação-Especial no seu campo e você envia o resto para o Cemitério. \r\nVocê só pode usar este efeito de "Fada Alfan Super Quantal" uma vez por turno.','\r',char(13)),'\n',char(10)),'Alterar Nível','Oferecer como Tributo','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58760121,'Lombriga Falco','VIRE: Coloque todos os monstros "Lombriga" do Tipo Réptil com a face para cima que você controla com a face para baixo em Posição de Defesa, exceto este card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58761791,'Erro de Envio','Quando um card ou efeito for ativado que inclua um efeito que adicione um ou mais cards do Deck à mão: o efeito ativado se torna "Seu oponente pega 1 card do Deck dele para que você adicione à sua mão, e você deve manter esse card revelado. Durante a Fase Final deste turno, embaralhe-o no Deck e, se isso acontecer, compre 1 card".','Ativar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58769832,'Arquidemônio Real',replace(replace('Você pode oferecer este card como Tributo da sua mão ou do campo com a face para cima; adicione 1 card "Arquidemônio" do seu Deck à sua mão, exceto "Arquidemônio Real" e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto monstros "Arquidemônio", mas você pode Invocar por Invocação-Normal 1 monstro Demônio durante sua Fase Principal neste turno, em adição à sua Invocação-Normal/Baixar (padrão) (você só pode se aproveitar deste efeito uma vez por turno). \r\nQuando um Monstro de Ritual seu for destruído em batalha enquanto este card estiver no seu Cemitério: você pode Invocar este card por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Arquidemônio Real" uma vez por turno.','\r',char(13)),'\n',char(10)),'Efeito de busca','Invocação Especial','Invocar pelo efeito de "Arquidemônio Real"','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58775978,'Jaula de Metal do Pesadelo',replace(replace('Este card permanece no campo por 2 dos turnos do seu oponente. \r\nEnquanto este card estiver com a face para cima no campo, os monstros não podem atacar.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58786132,'Lucius, o Vassalo das Sombras',replace(replace('Você pode banir 1 monstro de Nível 5 ou mais do seu Cemitério; Invoque este card por Invocação-Especial da sua mão e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno. \r\nSe este card for oferecido como Tributo para uma Invocação-Tributo: você pode olhar todos os cards Baixados que seu oponente controla. \r\nSeu oponente não pode ativar cards ou efeitos em resposta à ativação deste efeito. \r\nVocê só pode usar cada efeito de "Lucius, o Vassalo das Sombras" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58787301,'Rasante do Senhor Obscuro','Pague metade dos seus PV; Invoque por Invocação-Especial em Posição de Defesa até 2 monstros "Senhor Obscuro" do seu Cemitério com o mesmo Nível que 1 monstro com a face para cima que seu oponente controla.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58793369,'Fafnir Drytron',replace(replace('Quando este card for ativado: você pode adicionar 1 Magia/Armadilha "Drytron" do seu Deck à sua mão, exceto "Fafnir Drytron". \r\nA ativação e os efeitos ativados de Cards de Magia de Ritual não podem ser negados. \r\nUma vez por turno, se um monstro for Invocado por Invocação-Normal ou Especial com a face para cima enquanto você controlar um monstro "Drytron" (exceto durante a Etapa de Dano): você pode reduzir o Nível desse monstro em 1 para cada 1000 do seu ATK atual (mín. Nível 1) pelo resto deste turno. \r\nVocê só pode ativar 1 "Fafnir Drytron" por turno.','\r',char(13)),'\n',char(10)),'Adicionar 1 Card de Magia/Armadilha "Drytron" à sua mão?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58807980,'Monoceronte',replace(replace('Este card não pode ser Invocado por Invocação-Normal ou Baixado. \r\nEste card só pode ser Invocado por Invocação-Especial ao remover de jogo 1 Card de Magia da sua mão. \r\nQuando você Invocar por Invocação-Sincro usando este card e um monstro Regulador do Tipo Besta como os Monstros-Matéria Sincro, você pode selecionar 1 monstro Regulador do Tipo Besta usado para a Invocação-Sincro e Invocá-lo por Invocação-Especial do Cemitério.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58809685,'Elfnotas: Quarteto de Sucessão',replace(replace('O monstro na sua Zona de Monstros Principal central não pode ser banido pelos efeitos de card do seu oponente. \r\nVocê pode enviar 1 outra Magia/Armadilha da sua mão ou do campo para o Cemitério e, depois, declare um Nível de 1 a 4; Invoque por Invocação-Especial 1 "Ficha de Serafim Elfnota" (Planta/Regulador/FOGO/ATK 0/DEF 0) com o Nível declarado. \r\nEnquanto essa Ficha estiver na Zona de Monstros, o duelista que a Invocou não pode Invocar por Invocação-Especial do Deck Adicional, exceto monstros "Elfnota". \r\nVocê só pode usar este efeito de "Elfnotas: Quarteto de Sucessão" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58809686,'Ficha de Serafim Elfnota',replace(replace('Invocado por Invocação-Especial pelo efeito de "Elfnotas: Quadra da Sucessão".\r\nEnquanto esta Ficha Invocada por Invocação-Especial por esse efeito existir, você não pode Invocar por Invocação-Especial monstros do seu Deck Adicional que não sejam "Elfnota".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58811192,'Besta Espiritual Ulti-Kimunfalcos',replace(replace('2 monstros "Besta Espiritual"	\r\nMonstros "Besta Espiritual" para os quais este card apontar ganham 600 de ATK/DEF. \r\nVocê pode banir 1 card "Besta Espiritual" do seu Cemitério; imediatamente depois que este efeito resolver, Invoque por Invocação-Normal 1 monstro "Besta Espiritual" da sua mão. \r\nVocê só pode usar este efeito de "Besta Espiritual Ulti-Kimunfalcos" uma vez por turno. \r\n(Efeito Rápido): você pode devolver este card que você controla para o Deck Adicional e, depois, escolha 2 dos seus monstros banidos (1 monstro "Domador da Besta Espiritual" e 1 monstro "Avatar da Besta Espiritual"); Invoque-os por Invocação-Especial em Posição de Defesa.','\r',char(13)),'\n',char(10)),'Invoque por Invocação Normal 1 monstro da sua mão','Invoque por Invocação Especial 2 monstros banidos','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58818411,'Louva-a-deus Imperadora','Rainha de um exército de louva-a-deus gigantes. Suas ordens movem legiões.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58820853,'Asanegra - Shura, a Chama Azul','Quando este card destruir um monstro do oponente em batalha e enviá-lo para o Cemitério: você pode Invocar por Invocação-Especial 1 monstro "Asanegra" com 1500 ou menos de ATK do seu Deck, mas seus efeitos são negados.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58820923,'Número 95: Dragão da Matéria Escura de Olhos das Galáxias',replace(replace('3 monstros de Nível 9	\r\nVocê também pode Invocar este card por Invocação-Xyz ao usar um Monstro Xyz "Olhos das Galáxias" que você controla (transfira as matérias dele para este card). \r\nNão pode ser usado como matéria para uma Invocação-Xyz. \r\nQuando este card for Invocado por Invocação-Xyz: você pode enviar 3 monstros Dragão com nomes diferentes do seu Deck para o Cemitério; seu oponente bane 3 monstros do Deck dele. \r\nVocê pode desassociar 1 matéria deste card; este card pode realizar até 2 ataques contra monstros durante cada Fase de Batalha neste turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Xyz usando um Monstro Xyz "Olhos das Galáxias" como matéria?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58827995,'Ritual do Dragão Blindagem',replace(replace('Este card é usado para a Invocação-Ritual de "Cavaleiro do Dragão Blindagem". \r\nVocê também deve oferecer como Tributo monstros da sua mão ou do campo cuja soma dos Níveis seja igual a 4 ou mais. \r\nDurante sua Fase Principal, exceto no turno em que este card foi enviado para o Cemitério: você pode banir monstros da sua mão ou do campo com a face para cima cuja soma dos Níveis seja igual a 4 ou mais; bana este card do seu Cemitério e, se isso acontecer, Invoque por Invocação-Especial 1 "Cavaleiro do Dragão Blindagem" do seu Cemitério. \r\nVocê só pode usar este efeito de "Ritual do Dragão Blindagem" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58831685,'Cobra d''Água Vermelha Gigante','Uma cobra que vive no mar e ataca os inimigos com suas presas afiadas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58843503,'Golem de Fragmento Médio',replace(replace('Quando este card for Invocado, se você controlar um "Golem de Fragmento Grande", você pode Invocar por Invocação-Especial 1 "Golem de Fragmento Pequeno" do seu Deck. \r\nO efeito desse monstro é negado enquanto ele estiver com a face para cima no campo.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58844135,'Inteligência Anti-humana ME-PSY-YA',replace(replace('Escala de Pêndulo = 0\r\n[ Efeito de Pêndulo ]\r\nQualquer card enviado para o Cemitério, em vez disso, é banido, exceto Cards de Monstro.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nVocê pode revelar este card na sua mão; adicione 1 outro Monstro Pêndulo da sua mão, ou 1 card da sua Zona de Pêndulo, ao Deck Adicional do seu dono com a face para cima e, se isso acontecer, Invoque este card por Invocação-Especial. \r\nVocê só pode usar este efeito de "Inteligência Anti-humana ME-PSY-YA" uma vez por turno. \r\nSe um ou mais outros monstros forem Invocados por Invocação-Normal ou Especial enquanto você controlar este card: envie esse(s) monstro(s) para o Cemitério durante a Fase Final deste turno.','\r',char(13)),'\n',char(10)),'Invocar este card por Invocação Especial','Envie o monstro Invocado para o Cemitério durante a Fase Final','Escolha 1 card para adicionar ao Deck Adicional','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58851034,'Selo Amaldiçoado da Magia Proibida','Quando um Card de Magia for ativado: descarte 1 Magia; negue a ativação e, se isso acontecer, destrua-o e, se isso acontecer, seu oponente não pode ativar Cards de Magia com esse nome pelo resto deste Duelo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58858807,'Cavaleirostrela Constelar Caduceu',replace(replace('2+ monstros de Nível 4	\r\nSe este card for Invocado por Invocação-Xyz: você pode escolher 1 card "Cavaleirost" e/ou 1 card "Constelar" no seu Cemitério; adicione-os à sua mão. \r\nVocê pode banir 1 monstro "Cavaleirost" ou 1 monstro "Constelar" da sua mão ou do Deck, e desassocie 1 matéria deste card; este efeito se torna o efeito desse monstro banido que ativa quando ele é Invocado por Invocação-Normal. \r\nVocê só pode usar cada efeito de "Cavaleirostrela Constelar Caduceu" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58859575,'VW-Catapulta Tigre',replace(replace('"V-Jato Tigre" + "W-Catapulta de Asa"	\r\nPrimeiro deve ser Invocado por Invocação-Especial (do seu Deck Adicional) ao banir os cards acima que você controla. \r\nVocê pode descartar 1 card e, depois, escolha 1 monstro que seu oponente controla; mude a posição de batalha do alvo. \r\n(Efeitos de Virar não são ativados.)','\r',char(13)),'\n',char(10)),'Mudar a posição de batalha','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58861941,'Ooguchi','Este monstro pode atacar diretamente os Life Points do seu adversário.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58873391,'Torpedo Ictíico','Ofereça como Tributo 1 monstro Peixe e, depois, escolha 1 card no campo; destrua o alvo e, se isso acontecer, compre 1 card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58882608,'Sopro da Tistina',replace(replace('Durante sua Fase Principal, você pode Invocar por Invocação-Normal 1 monstro "Tistina" em adição à sua Invocação-Normal/Baixar (padrão). \r\n(Você só pode se aproveitar deste efeito uma vez por turno.) \r\nVocê pode escolher 1 monstro com a face para cima que você controla ou, se você controlar um monstro "Tistina" de LUZ, em vez disso, você pode escolher 1 monstro com a face para cima no campo; coloque esse monstro com a face para baixo em Posição de Defesa e, depois, adicione 1 card "Tistina" do seu Deck à sua mão, exceto "Sopro da Tistina". \r\nVocê só pode usar este efeito de "Sopro da Tistina" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar pelo efeito de "Sopro da Tistina"','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58884063,'Orgulho Dourado - Explosão Nytro',replace(replace('2 monstros "Orgulho Dourado" com Níveis diferentes	\r\nVocê pode escolher 1 monstro que seu oponente controla; destrua-o e, depois, se você tiver menos PV que seu oponente, você pode destruir todos os cards nas Zonas de Monstros e Zonas de Magias & Armadilhas adjacentes a ele. \r\nVocê só pode usar este efeito de "Orgulho Dourado - Explosão Nytro" uma vez por turno. \r\nUma vez por turno, durante a Fase Final, se este efeito foi ativado neste turno: devolva este card para o Deck Adicional e, se isso acontecer, Invoque por Invocação-Especial 1 "Orgulho Dourado - Cabeça Nytro" do seu Deck ou Cemitério.','\r',char(13)),'\n',char(10)),'','Destruir todos os cards na área?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58901502,'Defensor Goyo',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nUma vez por turno, se todos os monstros que você controla forem Monstros Sincro Guerreiro de TERRA (mín. 1): você pode Invocar "Defensor Goyo" por Invocação-Especial do seu Deck Adicional. \r\nQuando este card for escolhido como alvo de um ataque: até o final da Etapa de Dano, você pode fazer com que este card ganhe 1000 de ATK para cada Monstro Sincro Guerreiro de TERRA que você controla (que não seja este card).','\r',char(13)),'\n',char(10)),'Invocação Especial','Aumentar ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58911105,'Ninja Dourado Presunçoso','Uma vez por turno: você pode enviar 1 Armadilha da sua mão para o Cemitério; Invoque por Invocação-Especial 1 monstro "Ninja" de Nível 4 ou menos do seu Deck com a face para cima em Posição de Defesa ou com a face para baixo em Posição de Defesa.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58916810,'Trepidação Blitzclique',replace(replace('Durante o turno do seu oponente, quando seu oponente ativar um efeito de monstro no campo (Efeito Rápido): você pode revelar este card na sua mão; destrua esse monstro e, se isso acontecer, Invoque por Invocação-Especial 1 monstro Trovão da sua mão e, além disso, pelo resto deste turno, você não pode Invocar Monstros de Efeito por Invocação-Especial, exceto da mão. \r\nSe um ou mais outros cards forem destruídos por um efeito de card, enquanto este card estiver na Zona de Monstros (exceto durante a Etapa de Dano): você pode enviar 1 Magia/Armadilha "Blitzclique" do seu Deck para o Cemitério. \r\nVocê só pode usar cada efeito de "Trepidação Blitzclique" uma vez por turno.','\r',char(13)),'\n',char(10)),'Efeito de destruição','Enviar para o Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58921041,'Fragrância Anti-Magia','Os dois duelistas devem Baixar Cards de Magia antes de ativá-los e não podem ativá-los até seu próximo turno depois de Baixá-los.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58924378,'Watt-Castelo','Qualquer monstro que atacar um monstro "Watt" perde 1000 de ATK depois do cálculo de dano.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58931850,'Senhores Mestres dos Dragões',replace(replace('2 monstros de Nível 12	\r\nEnquanto este card Invocado por Invocação-Xyz estiver na sua Zona de Monstros, seu oponente não pode escolhê-lo como alvo de efeitos de card e, além disso, ele não pode ser destruído pelos efeitos de card do seu oponente. \r\nEnquanto você tiver 25 ou mais cards no seu Cemitério, se este card atacar um monstro em Posição de Defesa, cause o dobro de dano de batalha perfurante ao seu oponente. \r\nUma vez por turno, se o seu oponente tiver 25 ou mais cards no Cemitério dele: você pode desassociar 1 matéria deste card; Invoque por Invocação-Especial 1 monstro do seu Deck, Deck Adicional ou Cemitério.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58932615,'Burstinatrix, o HERÓI do Elemento','Uma manipuladora das chamas que é a primeira mulher HERÓI do Elemento. Sua Explosão de Fogo queima os vilões.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58932616,'Burstinatrix, o HERÓI do Elemento','Uma manipuladora das chamas que é a primeira mulher HERÓI do Elemento. Sua Explosão de Fogo queima os vilões.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58938528,'Damange Camarartista',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno, quando um ataque for declarado envolvendo um monstro seu e um monstro do oponente: você pode descartar 1 Monstro Pêndulo; esse monstro do oponente perde 1000 de ATK até o final deste turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nVocê pode descartar este card e 1 monstro "Camarartista", exceto "Damange Camarartista"; compre 2 cards. \r\nSe este card estiver no seu Cemitério e você controlar um card "Olhos Anômalos" ou "Gentrude Camarartista": você pode colocar este card na sua Zona de Pêndulo. \r\nVocê só pode usar 1 efeito de "Damange Camarartista" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','Compre 2 card(s)','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58947797,'Duque Vampiro',replace(replace('Não pode ser usado como matéria para uma Invocação-Xyz, exceto para a Invocação-Xyz de um monstro de TREVAS. \r\nQuando este card for Invocado por Invocação-Normal: você pode escolher 1 monstro "Vampiro(a)" de TREVAS no seu Cemitério; Invoque o alvo por Invocação-Especial em Posição de Defesa. \r\nQuando este card for Invocado por Invocação-Especial: você pode declarar 1 tipo de card (Monstro, Magia ou Armadilha); seu oponente envia 1 card desse tipo do Deck dele para o Cemitério. \r\nVocê só pode usar este efeito de "Duque Vampiro" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Declarar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58981727,'Yosenju Sabu',replace(replace('Uma vez por turno, durante a Fase Final, se este card foi Invocado por Invocação-Normal neste turno: devolva-o para a mão. \r\nVocê só pode usar cada um dos seguintes efeitos de "Yosenju Sabu" uma vez por turno.\r\n● Se este card for Invocado por Invocação-Normal: se você controlar outro card "Yosenju", você pode adicionar 1 Monstro Pêndulo "Yosenju" do seu Deck à sua mão.\r\n● Você pode escolher 1 card "Yosenju" que você controla; coloque 1 "Ventos Vertiginosos da Vila de Yosen" ou "Furacão Yosen" do seu Deck com a face para cima na sua Zona de Magias & Armadilhas e, se isso acontecer, embaralhe o card alvo no Deck.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58984738,'Kavaleiro Dinopoder, o Verdadeiro Dracolutador',replace(replace('Para Invocar este card por Invocação-Tributo com a face para cima, você pode oferecer como Tributo uma Magia/Armadilha Contínua que você controla, em vez de um monstro. \r\nUma vez por turno, quando seu oponente ativar um card ou efeito enquanto você controlar este monstro Invocado por Invocação-Tributo (Efeito Rápido): você pode pegar 1 Armadilha Contínua "Verdadeiro(a) Draco" ou "Verdadeiro Rei" do seu Deck e ativá-la ou adicioná-la à sua mão.','\r',char(13)),'\n',char(10)),'Invocação Tributo ao oferecer como Tributo um Card de Magia/Armadilha','Adicionar à mão ou ativar no seu Campo','Adicionar à mão?','Escolha o card que deseja adicionar à sua mão ou ativar no seu Campo','','','','','','','','','','','','');
INSERT INTO texts VALUES(58988903,'Magia de Aumento de Classe Força Intermitente',replace(replace('Escolha 1 Monstro Xyz "Ataqueraptor" que você controla; Invoque por Invocação-Especial do seu Deck Adicional, 1 monstro "Ataqueraptor" que seja 2 Classes maior que o alvo, usando o alvo como matéria. \r\n(Isso é considerado uma Invocação-Xyz. Transfira as matérias dele para o monstro Invocado.) \r\nDurante sua Fase Principal, exceto no turno em que este card foi enviado para o Cemitério: você pode banir este card e 1 monstro "Ataqueraptor" do seu Cemitério e, depois, escolha 1 Monstro Xyz "Ataqueraptor" no seu Cemitério; Invoque-o por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Invocação Especial','Banir este card e 1 monstro "Ataqueraptor"','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58990362,'Zefraniu, Segredo de Yang Zing',replace(replace('Escala de Pêndulo = 7\r\n[ Efeito de Pêndulo ]\r\nVocê não pode Invocar monstros por Invocação-Pêndulo, exceto monstros "Yang Zing" e "Zefra". \r\nEste efeito não pode ser negado.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nQuando este card for Invocado por Invocação-Pêndulo ou quando este card for destruído em batalha ou por um efeito de card enquanto estiver na sua Zona de Monstros: você pode adicionar 1 Magia/Armadilha "Yang Zing" ou "Zefra" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Zefraniu, Segredo de Yang Zing" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58990631,'Laser Automático',replace(replace('Quando seu oponente Invocar por Invocação-Normal ou por Invocação-Especial um ou mais monstros com 1000 ou mais de ATK, revele 1 "Núcleo de Ferro de Koa''ki Meiru" na sua mão para ativar este card. \r\nDestrua esses monstros Invocados.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58995660,'Vantagem do Primeiro Atacante',replace(replace('Uma vez por turno, quando um ataque for declarado envolvendo um monstro seu: você pode lançar um dado de seis faces e aplicar este efeito ao seu monstro de acordo com o resultado, até o final deste turno. \r\nSe os dois monstros estavam na mesma coluna quando este efeito foi ativado, selecione o efeito em vez de lançar o dado.\r\n● 1 ou 4: Na primeira vez que ele seria destruído em batalha ou por um efeito de card, ele não é destruído.\r\n● 2 ou 5: Ele perde 500 de ATK e, além disso, ele não é afetado por efeitos ativados de Magias/Armadilhas, exceto "Vantagem do Primeiro Atacante".\r\n● 3 ou 6: Ele ganha 1000 de ATK e, além disso, ele pode realizar até 2 ataques contra monstros durante cada Fase de Batalha.','\r',char(13)),'\n',char(10)),'','Não pode ser destruído','Não é afetado por efeitos','Continuar atacando','O efeito de "Vantagem do Primeiro Atacante" 1·4 está sendo aplicado.','O efeito de "Vantagem do Primeiro Atacante" 2·5 está sendo aplicado.','O efeito de "Vantagem do Primeiro Atacante" 3·6 está sendo aplicado.','','','','','','','','','');
INSERT INTO texts VALUES(58996430,'Wulf, a Besta Luminosa',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial por um efeito de card. \r\nSe este card for enviado do seu Deck para o Cemitério: Invoque-o por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(58996839,'Pilar de Ashoka',replace(replace('Se este card for Invocado: você pode adicionar 1 Magia de Equipamento do seu Deck à sua mão e, depois, se este card estiver em Posição de Ataque, coloque-o em Posição de Defesa. \r\nVocê só pode usar este efeito de "Pilar de Ashoka" uma vez por turno. \r\nSe este card for destruído em batalha ou por um efeito de card: sofra 2000 de dano.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59011257,'Chita Apaixonada',replace(replace('Não pode ser oferecido como Tributo, nem usado como matéria para uma Invocação-Fusão, Sincro, Xyz ou Link, enquanto estiver com a face para cima no campo. \r\nSe um ou mais monstros forem Invocados por Invocação-Especial no campo do seu oponente, enquanto este card estiver na sua Zona de Monstros: escolha 1 deles; conceda o controle deste card ao controlador desse monstro e, além disso, esse monstro não pode ser oferecido como Tributo nem usado como matéria para uma Invocação-Fusão, Sincro, Xyz ou Link enquanto este monstro estiver com a face para cima no campo.','\r',char(13)),'\n',char(10)),'','Transferir o controle','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59016454,'Força do Espelho da Magia Negra','Quando um monstro do oponente declarar um ataque, ou um efeito de monstro do oponente for ativado que destruiria um ou mais monstros no campo, enquanto um monstro que mencione "Sarcófago Brilhante" estiver no campo: destrua tantos monstros em Posição de Ataque que seu oponente controla quanto possível e, depois, se você controlar "Mago Negro", cause 500 de dano ao seu oponente para cada monstro destruído e, além disso, pelo resto deste turno depois que este card resolver, na primeira vez que cada monstro que você controla que mencione "Sarcófago Brilhante" seria destruído em batalha ou por um efeito de card, ele não é destruído.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59019082,'Garoth, o Guerreiro Luminoso','Se um ou mais cards forem enviados do seu Deck para o Cemitério pelo efeito de um monstro "Luminoso(a)" que você controla, exceto "Garoth, o Guerreiro Luminoso": envie os 2 cards do topo do seu Deck para o Cemitério e, depois, compre 1 card para cada monstro "Luminoso(a)" enviado para o Cemitério por este efeito.','Envie 2 cards do seu Deck para o Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59023523,'Mago Cibernético',replace(replace('Descarte 1 card da sua mão. \r\nO ATK de 1 monstro no Campo com a face para cima torna-se 2000 até a End Phase deste turno.','\r',char(13)),'\n',char(10)),'Alterar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59036972,'Mavelus','"Tyhone" + "Asas da Chama Perversa"','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59042331,'Cerca Vigia','Durante o cálculo de dano, no turno de qualquer duelista, quando um monstro que você controla atacar ou for atacado: você pode enviar este card da sua mão para o Cemitério; até o final deste turno, diminua pela metade o ATK desse monstro que você controla, mas esse monstro não pode ser destruído por esta batalha.','Alterar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59048135,'Heráldica Melhorada',replace(replace('Nenhum duelista pode escolher Monstros Xyz Psíquico no campo como alvo de Cards de Magia/Armadilha ou seus efeitos. \r\nUma vez por turno: você pode descartar 1 monstro "Besta Heráldica"; adicione 1 Magia/Armadilha "Heráldico(a)" do seu Deck à sua mão, exceto "Heráldica Melhorada". \r\nVocê não pode Invocar por Invocação-Normal ou Especial no turno em que ativar este efeito, exceto Monstros Xyz Psíquico e monstros "Besta Heráldica" (mesmo que este card deixe o campo).','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59053232,'Turu-Purun','Um monstro estranho com um só olho que consegue derrubar um inimigo com uma única punhalada de sua lança.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59054773,'I.A.Terra Ignister',replace(replace('Se você não controlar nenhum monstro na sua Zona de Monstros Principal: você pode Invocar por Invocação-Especial 1 monstro "@Ignister" de Nível 4 ou menos da sua mão, mas pelo resto deste turno, você não pode Invocar monstros por Invocação-Especial com o mesmo Atributo original pelo efeito de "I.A.Terra Ignister" e, além disso, você não pode Invocar por Invocação-Especial, exceto monstros Ciberso (mesmo que este card deixe o campo). \r\nSe este card estiver no seu Cemitério: você pode banir 1 monstro "@Ignister" do seu Cemitério; Baixe este card. \r\nVocê só pode usar este efeito de "I.A.Terra Ignister" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59057152,'Nobre Cavaleiro Medraut',replace(replace('Este card é considerado um Monstro Normal enquanto estiver no campo com a face para cima. \r\nEnquanto estiver equipado com uma Magia de Equipamento "Armas Nobres", este card se torna um Monstro de Efeito com este efeito.\r\n● Este card se torna de TREVAS e seu Nível aumenta em 1.\r\n● Uma vez por turno, se você não controlar nenhum outro monstro: você pode Invocar por Invocação-Especial 1 monstro "Nobre Cavaleiro" do seu Deck em Posição de Defesa, exceto "Nobre Cavaleiro Medraut" e, se isso acontecer, destrua 1 Magia de Equipamento que você controla.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59057953,'Bastidores do Ator do Abismo',replace(replace('Se você tiver 2 cards "Ator do Abismo" nas suas Zonas de Pêndulo: adicione 2 Monstros Pêndulo "Ator do Abismo" com nomes diferentes do seu Deck ao seu Deck Adicional com a face para cima. \r\nVocê só pode ativar 1 "Bastidores do Ator do Abismo" por turno.','\r',char(13)),'\n',char(10)),'Escolha o(s) card(s) para adicionar ao seu Deck Adicional','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59069885,'Abraço da Tistina',replace(replace('Quando seu oponente ativar um efeito de monstro no campo: você pode escolher esse monstro; coloque-o com a face para baixo em Posição de Defesa. \r\nDurante a Fase Final: você pode escolher 1 monstro com a face para baixo em Posição de Defesa que seu oponente controla; tome o controle desse monstro. \r\nVocê só pode usar cada efeito de "Abraço da Tistina" uma vez por turno e só pode ativá-los enquanto você controlar um monstro "Tistina" com 3000 ou mais de DEF.','\r',char(13)),'\n',char(10)),'Mudar para a posição com a face para baixo','Tome o controle','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59070329,'Aura Utópica','Desassocie 1 matéria de um monstro que você controla; Monstros Xyz com a face para cima que você controla atualmente não podem ser destruídos por efeitos de card até o final deste turno.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59071624,'Armadilhatrix Allomerus',replace(replace('2+ monstros de Nível 4	\r\nNão é afetado por efeitos de Armadilha enquanto tiver matéria. \r\nVocê só pode usar cada um dos seguintes efeitos de "Armadilhatrix Allomerus" uma vez por turno.\r\n● Você pode desassociar 2 matérias deste card; Invoque por Invocação-Especial 1 monstro Inseto ou Planta de Nível 4 do seu Cemitério.\r\n● Se um ou mais monstros do oponente deixarem o campo por um efeito de card seu e agora estiverem no Cemitério ou banidos (exceto durante a Etapa de Dano): você pode desassociar 1 matéria deste card e, depois, escolha 1 deles; Invoque-o por Invocação-Especial no seu campo.','\r',char(13)),'\n',char(10)),'','Invoque por Invocação Especial um monstro do seu oponente','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59094601,'O Renascido Deus Celeste',replace(replace('A ativação deste card, ou seus efeitos, não pode ser negada, nem seus efeitos podem ser negados. \r\nInvoque por Invocação-Especial 1 "Slifer, o Dragão Celeste" do seu Cemitério e, depois, cada duelista compra até ter 6 cards em sua mão. \r\nVocê pode banir este card do seu Cemitério; coloque 1 "Reviver Monstro" do seu Deck ou Cemitério no topo do seu Deck e, depois, se um monstro Besta Divina estiver no seu Cemitério, compre 1 card. \r\nVocê só pode usar cada efeito de "O Renascido Deus Celeste" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Escolha o card a ser colocada no topo do Deck','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59106048,'Fazticeira Semente',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial e você controla um monstro "Fazticeira" que não seja "Fazticeira Semente" ou "Regulus, o Príncipe de Endymion": você pode escolher 1 card com a face para cima no campo; retorne-o para a mão.\r\nVocê pode banir este card do seu Cemitério; revele qualquer número de cards na sua mão, incluindo uma Magia, e embaralhe-os no Deck, então compre aquela quantia de card.\r\nVocê só pode usar cada um dos efeitos de "Fazticeira Semente" uma vez por turno.','\r',char(13)),'\n',char(10)),'Retornar para a mão','Comprar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59120809,'Espantagarra Tri-Heart',replace(replace('3 Monstros de Efeito	\r\nDeve ser Invocado por Invocação-Link. \r\nTodos os monstros com a face para cima no campo são colocados em Posição de Defesa. \r\nNão é afetado pelos efeitos ativados de monstros em Posição de Defesa. \r\nUma vez por turno, se este card estiver na Zona de Monstros Adicional: você pode escolher 1 monstro "Espantagarra" de Nível 3 no seu Cemitério; Invoque-o por Invocação-Especial e, se isso acontecer, adicione 1 monstro "Espantagarra" do seu Deck à sua mão e, além disso, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros "Espantagarra".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59123194,'Paladino da Iluminação',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro usando um Monstro Pêndulo "Mago" como matéria: você pode escolher 1 Magia no seu Cemitério; adicione-a à sua mão. \r\nVocê só pode usar este efeito de "Paladino da Iluminação" uma vez por turno. \r\nQuando este card destruir um monstro do oponente em batalha: você pode causar dano ao seu oponente igual ao ATK original desse monstro.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59123937,'D/D Vice Tifon',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode oferecer como Tributo 1 monstro "D/D"; Invoque por Invocação-Especial 1 monstro "D/D/D" de Nível 7 do seu Deck. \r\nDurante sua Fase Principal, se este card estiver no Cemitério porque foi enviado para lá neste turno: você pode Invocar por Invocação-Fusão 1 Monstro de Fusão "D/D/D" de Nível 8 ou mais do seu Deck Adicional, ao banir Matérias de Fusão listadas nele do seu Cemitério, incluindo este card. \r\nVocê só pode usar cada efeito de "D/D Vice Tifon" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59131526,'Rodada de Aquarefrão',replace(replace('Bana 1 card da sua mão e, se isso acontecer, durante sua próxima Fase de Apoio, você pode adicionar até 2 cards com o mesmo nome que o desse card banido do seu Deck à sua mão. \r\nSe você ativou este card enquanto seu oponente não controlava nenhum card, pelo resto deste turno você não pode ativar cards, ou os efeitos de cards, com o mesmo nome original que o desse card banido.','\r',char(13)),'\n',char(10)),'','Adicionar à sua mão 1 card com o mesmo nome de um card banido por "Rodada de Aquarefrão"?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59138498,'Mártir das Bestas Sagradas',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode colocar 1 Magia de Campo "Bestas Sagradas" ou 1 Magia/Armadilha Contínua "Bestas Sagradas" do seu Deck, com a face para cima no seu campo. \r\nSe você controlar outro monstro "Bestas Sagradas": você pode Invocar por Invocação-Especial 2 "Mártir das Bestas Sagradas" da sua mão, do Deck e/ou do Cemitério. \r\nDurante a Fase Final do seu oponente, se você tiver este card e um monstro "Bestas Sagradas" de Nível 10 no seu Cemitério: você pode adicionar este card à sua mão. \r\nVocê só pode usar cada efeito de "Mártir das Bestas Sagradas" uma vez por turno.','\r',char(13)),'\n',char(10)),'Baixar Magia/Armadilha','Invocação Especial','Adicionar à mão','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59156966,'Caixa de Engrenagens Dourada',replace(replace('Selecione 1 monstro "Karakuri" com a face para cima no campo. \r\nEle ganha 500 de ATK e 1500 de DEF até a Fase Final.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59160188,'Covil das Trevas',replace(replace('Todos os monstros com a face para cima no campo se tornam de TREVAS. \r\nUma vez por turno, se você fosse oferecer como Tributo um monstro que você controla para ativar um efeito de card, você pode oferecer como Tributo 1 monstro de TREVAS que seu oponente controla, mesmo que você não o controle. \r\nUma vez por turno, durante a Fase Final: Invoque por Invocação-Especial tantas "Ficha de Tormento" (Demônio/TREVAS/Nível 3/ATK 1000/DEF 1000) quanto possível no campo do duelista do turno em Posição de Defesa, até o número de monstros oferecidos como Tributo neste turno enquanto este card estava com a face para cima.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59160189,'Ficha de Tormento','Invocada por Invocação-Especial com o efeito "Covil das Trevas".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59170782,'Sirena Abistrite',replace(replace('3 monstros de Nível 3	\r\nDurante o turno de qualquer duelista, quando seu oponente escolher exatamente 1 monstro "Sirena" com a face para cima que você controla como alvo de um ataque ou de um efeito de Magia/Armadilha que poderia ter escolhido este card (exceto durante a Etapa de Dano): você pode desassociar 1 Matéria Xyz deste card; o ataque/efeito agora escolhem este card como alvo. \r\nQuando este card for destruído e enviado para o Cemitério: você pode escolher 1 monstro "Sirena" em seu Cemitério, exceto "Sirena Abistrite"; Invoque o alvo por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Alterar alvo','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59185998,'Pookuery Altergeist',replace(replace('Se um monstro "Altergeist" que você controla seria usado como Matéria Link para um monstro "Altergeist", este card na sua mão também pode ser usado como matéria. \r\nVocê só pode usar este efeito de "Pookuery Altergeist" uma vez por turno. \r\nSe um Monstro Link "Altergeist" for Invocado por Invocação-Link no seu campo, enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode adicionar este card à sua mão. \r\nVocê só pode usar este efeito de "Pookuery Altergeist" uma vez por Duelo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59197169,'Yami','Todos os monstros Demônio e Mago no campo ganham 200 de ATK/DEF e, além disso, todos os monstros Fada no campo perdem 200 de ATK/DEF.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59208943,'Ladrão do Tempo Perpétua',replace(replace('2 monstros de Nível 4	\r\nDurante a Fase de Apoio: você pode desassociar 1 matéria deste card e, depois, escolha 1 monstro "Ladrão do Tempo" no seu Cemitério, exceto "Ladrão do Tempo Perpétua"; Invoque esse monstro por Invocação-Especial. \r\n(Efeito Rápido): você pode escolher 1 outro Monstro Xyz que você controla; associe 1 card "Ladrão do Tempo" do seu Deck a ele como matéria. \r\nVocê só pode usar cada efeito de "Ladrão do Tempo Perpétua" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial do Cemitério','Associar Matéria Xyz','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59228631,'Cavalestrela Astel',replace(replace('(Efeito Rápido): você pode escolher 1 monstro de LUZ que você controla; ofereça-o como Tributo e, se isso acontecer, Invoque por Invocação-Especial 1 monstro Dragão de LUZ de Nível 7 da sua mão. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 monstro Dragão de LUZ de Nível 7 que você controla; ele ganha 1000 de ATK até o final do turno do seu oponente. \r\nVocê só pode usar cada efeito de "Cavalestrela Astel" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59235795,'Ciclone Destruidor','Quando este card for destruído em batalha e enviado para o Cemitério, destrua todos os monstros com a face para baixo e os que não sejam de VENTO.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59237154,'Sombras em Mudança',replace(replace('Pague 300 Life Points para embaralhar os monstros no seu Campo em Posição de Defesa com a face para baixo, e em seguida devolva-os à Posição de Defesa com a face para baixo. \r\nVocê pode usar este efeito apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Embaralhar monstros virados para baixo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59242457,'Exoirmãs Magnifica',replace(replace('2 Monstros Xyz "Exoirmã" de Classe 4	\r\nDeve ser Invocado por Invocação-Xyz com as matérias acima. \r\nPode realizar um segundo ataque durante cada Fase de Batalha. \r\nUma vez por turno (Efeito Rápido): você pode desassociar 1 matéria deste card; bana 1 card que seu oponente controla. \r\nUma vez por Corrente, quando seu oponente ativar um card ou efeito (Efeito Rápido): você pode devolver para o seu Deck Adicional 1 Monstro Xyz do qual você é dono associado a este card e, depois, você pode Invocar esse monstro por Invocação-Especial do seu Deck Adicional, usando este card que você controla como matéria (isso é considerado uma Invocação-Xyz, transfira as matérias dele).','\r',char(13)),'\n',char(10)),'Banir 1 card do seu oponente','Retornar as Matérias Xyz ao Deck Adicional','Invocar aquele monstro por Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59242458,'Exoirmãs Magnifica',replace(replace('2 Monstros Xyz "Exoirmã" de Classe 4	\r\nDeve ser Invocado por Invocação-Xyz com as matérias acima. \r\nPode realizar um segundo ataque durante cada Fase de Batalha. \r\nUma vez por turno (Efeito Rápido): você pode desassociar 1 matéria deste card; bana 1 card que seu oponente controla. \r\nUma vez por Corrente, quando seu oponente ativar um card ou efeito (Efeito Rápido): você pode devolver para o seu Deck Adicional 1 Monstro Xyz do qual você é dono associado a este card e, depois, você pode Invocar esse monstro por Invocação-Especial do seu Deck Adicional, usando este card que você controla como matéria (isso é considerado uma Invocação-Xyz, transfira as matérias dele).','\r',char(13)),'\n',char(10)),'Banir 1 card do seu oponente','Retornar as Matérias Xyz ao Deck Adicional','Invocar aquele monstro por Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59251766,'Lebre Bujingi',replace(replace('Durante o turno de qualquer duelista: você pode banir este card do seu Cemitério e, depois, escolher 1 monstro "Bujin" do Tipo Besta-Guerreira que você controla; uma vez durante este turno, ele não pode ser destruído em batalha ou por efeitos de card. \r\nVocê só pode usar o efeito de "Lebre Bujingi" uma vez por turno.','\r',char(13)),'\n',char(10)),'Não pode ser destruído','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59255742,'Imperador Goyo',replace(replace('2 Monstros Sincro de TERRA do Tipo Guerreiro	\r\nQuando este card ou um monstro que você controla do qual seu oponente é dono destruir um monstro do oponente em batalha e enviá-lo para o Cemitério: você pode Invocar esse monstro por Invocação-Especial no seu lado do campo. \r\nQuando seu oponente Invocar um ou mais monstros por Invocação-Especial, exceto durante a Etapa de Dano: você pode oferecer como Tributo 1 Monstro Sincro de TERRA do Tipo Guerreiro; tome o controle desse(s) monstro(s). \r\nSe este card com a face para cima deixar o campo: devolva o controle de todos os monstros que você controla aos seus danos.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59258334,'Raio de Lavagem Cerebral',replace(replace('Selecione 1 monstro com pelo menos 1 Marcador-A no lado do campo do oponente e tome o controle desse monstro. \r\nDurante cada uma de suas Fases Finais, remova 1 Marcador-A desse monstro controlado. \r\nSe todos os Marcadores-A forem removidos desse monstro ou esse monstro for destruído, destrua este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59277750,'Alarme de Intruso - Alerta Amarelo',replace(replace('Quando um monstro do oponente declarar um ataque: Invoque por Invocação-Especial 1 monstro da sua mão, mas devolva-o para a mão no final da Fase de Batalha. \r\nEnquanto você controlar esse monstro com a face para cima Invocado por Invocação-Especial, seu oponente não pode escolher outros monstros como alvo de ataques. \r\nVocê só pode ativar 1 "Alarme de Intruso - Alerta Amarelo" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59281822,'Umbriragem, o Senhor Elemental',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao ter exatamente 5 monstros de TREVAS no seu Cemitério. \r\nSe este card for Invocado por Invocação-Especial: adicione 1 monstro com 1500 ou menos de ATK do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Umbriragem, o Senhor Elemental" uma vez por turno. \r\nSe este card com a face para cima deixar o campo, pule a Fase de Batalha do seu próximo turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59281922,'Dragão Cibernético Drei',replace(replace('O nome deste card se torna "Dragão Cibernético" enquanto estiver no campo ou no Cemitério. \r\nQuando este card for Invocado por Invocação-Normal: você pode fazer com que todos os "Dragão Cibernético" que você controla atualmente se tornem de Nível 5. \r\nVocê não pode Invocar monstros por Invocação-Especial no turno em que ativar este efeito, exceto monstros Máquina. \r\nSe este card for banido: você pode escolher 1 "Dragão Cibernético" que você controla; ele não pode ser destruído em batalha ou por efeitos de card neste turno.','\r',char(13)),'\n',char(10)),'Alterar Nível','Não pode ser destruído','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59290628,'Cavalo Pesadelo','Este monstro pode atacar diretamente os Life Points do seu adversário mesmo que exista um monstro no Campo do seu adversário.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59293853,'Quarto Mimicarniçal',replace(replace('Invoque por Invocação-Especial 1 monstro "Mimicarniçal" da sua mão ou do Deck no seu campo, ou com a face para baixo em Posição de Defesa no campo do seu oponente e, depois, você pode colocar 1 monstro com a face para cima no campo, com a face para baixo em Posição de Defesa. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha qualquer número de cards "Mimicarniçal" que você controla; devolva-os para a mão. \r\nVocê só pode usar 1 efeito de "Quarto Mimicarniçal" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Retornar para a mão','Invocar por Invocação Especial para o seu Campo','Invocar por Invocação Especial para o Campo do seu oponente','Mudar um monstro para Posição de Defesa com a face para baixo?','','','','','','','','','','','');
INSERT INTO texts VALUES(59297550,'Mago de Corda',replace(replace('Se o efeito de um monstro "de Corda" for ativado, exceto "Mago de Corda": você pode Invocar por Invocação-Especial 1 monstro "de Corda" de Nível 4 ou menos do seu Deck com a face para cima em Posição de Defesa. \r\nEste efeito só pode ser usado uma vez enquanto este card estiver com a face para cima no campo.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59305593,'Erro','Nenhum duelista pode adicionar cards do seu Deck à sua mão exceto comprando-os.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59312550,'Jurrac Velo','Quando este card em Posição de Ataque que você controla for destruído em batalha e enviado para o seu Cemitério: você pode Invocar por Invocação-Especial 1 monstro "Jurrac" com 1700 ou menos de ATK do seu Deck.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59323650,'Dragão Regênese',replace(replace('Se um monstro com 2500 de ATK ou DEF original estiver no campo, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Dragão Regênese" por Invocação-Especial uma vez por turno desta forma. \r\nVocê só pode usar cada um dos seguintes efeitos de "Dragão Regênese" uma vez por turno. \r\n(Efeito Rápido): você pode oferecer este card como Tributo e, depois, escolha 1 Magia/Armadilha que seu oponente controla; bana-o. \r\nDurante a Fase Final do seu oponente, se este card estiver no Cemitério porque foi enviado para lá neste turno: você pode adicionar este card à sua mão.','\r',char(13)),'\n',char(10)),'','Banir','Recuperar','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59332125,'Fusão Amorosa I.A.',replace(replace('Invoque por Invocação-Fusão 1 Monstro de Fusão Ciberso do seu Deck Adicional, usando monstros da sua mão ou do campo como Matéria de Fusão. \r\nSe você usar um monstro "@Ignister" seu como Matéria de Fusão, você também pode usar 1 Monstro Link que seu oponente controla como matéria. \r\nVocê só pode ativar 1 "Fusão Amorosa I.A." por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59344077,'Escoadouro Mágico','Quando seu oponente ativar um Card de Magia: ele pode descartar 1 Magia para negar o efeito deste card, caso contrário, negue a ativação do Card de Magia dele e, se isso acontecer, destrua-o.','Descartar 1 Card de Magia?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59353647,'Rei Ligre de Estimação Amazoness',replace(replace('1 monstro "Amazoness" de Nível 5 ou mais + 1 monstro "Amazoness"	\r\nOs monstros do seu oponente não podem atacar nenhum monstro, exceto este. \r\nVocê pode escolher 1 card "Amazoness" que você controla e 1 monstro Guerreiro "Amazoness" no seu Cemitério; destrua esse card no campo e, se isso acontecer, Invoque o outro monstro por Invocação-Especial do Cemitério. \r\nEste card não pode atacar no turno em que este efeito for ativado. \r\nVocê só pode usar este efeito de "Rei Ligre de Estimação Amazoness" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59364406,'Besta em Brasa',replace(replace('Uma vez por turno, durante a sua Main Phase, você pode equipar este card a "Besta Congelada" como um Card de Magia de Equipamento, OU separar o Equipamento e Invocar, por Invocação-Especial, este card em Posição de Ataque com a face para cima. \r\nQuando este card é equipado pelo efeito deste card, cada vez que o monstro equipado inflige dano de batalha ao seu adversário, destrúa 1 Card de Magia ou Armadilha no Campo com a face para cima. \r\n(1 monstro pode ser equipado apenas por 1 Monstro de Union de cada vez. Se o monstro equipado com este card é destruído como resultado de um combate, em vez disso destrúa este card.)','\r',char(13)),'\n',char(10)),'Equipar','Invocação Especial','Destruir','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59368956,'Robô-secretário 002',replace(replace('Se este card for Invocado por Invocação-Especial: você pode adicionar 1 card "Robô-secretário" do seu Deck à sua mão. \r\nTodos os monstros do Tipo Máquina que você controla ganham 500 de ATK e DEF, exceto este card.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Alterar ATK/DEF','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59369430,'Gargóleo, o Esmagador Sísmico de Aço',replace(replace('Se este card batalhar um monstro, nenhum dos dois pode ser destruído nessa batalha. \r\nVocê só pode usar cada um dos seguintes efeitos de "Gargóleo, o Esmagador Sísmico de Aço" uma vez por turno. \r\nDepois do cálculo de dano, se um dos seus monstros Máquina ou Ilusão batalharam: você pode escolher 1 dos seus monstros que estiverem banidos ou no seu Cemitério; Invoque-o por Invocação-Especial. \r\nSe este card for banido do campo: você pode Invocá-lo por Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59371387,'O Resoluto Exército Senhormek','Todos os monstros "Exército Senhormek" em Posição de Ataque que você controla não podem ser destruídos em batalha e, além disso, seus efeitos são negados.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59374259,'Técnicas Furtivas de Peluguel, Pelos Todos os Movimentos Definitivos',replace(replace('Escolha cards com a face para cima no campo, até o número de monstros "de Peluguel" que você controla com nomes diferentes; destrua esses cards alvo, ou se você controlar pelo menos 1 de cada de monstros "de Peluguel" de Nível 8 ou mais e de Link-3 ou mais, em vez disso, você pode banir esses cards alvo. \r\nSe um monstro "de Peluguel" de Nível 8 ou mais, ou de Link-3 ou mais, for Invocado por Invocação-Especial no seu campo, enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode adicionar este card à sua mão. \r\nVocê só pode usar 1 efeito de "Técnicas Furtivas de Peluguel, Pelos Todos os Movimentos Definitivos" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Banir em vez disso?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59380081,'Mamute com Grandes Presas','Monstros que seu oponente controla não podem atacar no turno em que forem Invocados.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59383041,'Jacaré Toon','Um monstro jacaré vindo diretamente dos desenhos animados.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59385322,'Destruição de Núcleo',replace(replace('Só pode ser equipado a um monstro "Koa''ki Meiru". \r\nSe ele batalhar um monstro de LUZ ou TREVAS, destrua esse monstro sem aplicar o cálculo de dano. \r\nQuando o monstro equipado for removido do campo e este card for enviado ao Cemitério, você pode devolver este card para a sua mão.','\r',char(13)),'\n',char(10)),'Destruir','Retornar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59388357,'Círculo dos Reis de Fogo',replace(replace('Escolha 1 monstro de FOGO que você controla e 1 monstro de FOGO no seu Cemitério; destrua esse monstro que você controla e, se isso acontecer, Invoque por Invocação-Especial o outro monstro do seu Cemitério. \r\nVocê só pode ativar 1 "Círculo dos Reis de Fogo" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59392529,'Soldado Líquido, o HERÓI do Elemento',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode escolher 1 monstro "HERÓI" de Nível 4 ou menos no seu Cemitério, exceto "Soldado Líquido, o HERÓI do Elemento"; Invoque-o por Invocação-Especial. \r\nSe este card for usado como Matéria de Fusão para um monstro "HERÓI" e enviado para o Cemitério ou banido: você pode comprar 2 cards e, depois, descarte 1 card. \r\nVocê só pode usar 1 efeito de "Soldado Líquido, o HERÓI do Elemento" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Comprar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59400890,'Mago Negro da Destruição',replace(replace('"Mago Negro" + 1 monstro de LUZ ou de TREVAS	\r\nDeve ser Invocado por Invocação-Fusão, ou por Invocação-Especial (do seu Deck Adicional) durante o turno em que um Card de Magia ou seus efeitos for ativado, ao banir 1 monstro Mago de TREVAS de Nível 6 ou mais que você controla como matéria. \r\nVocê só pode Invocar "Mago Negro da Destruição" por Invocação-Especial uma vez por turno desta forma, não importa o método que usar. \r\nO nome deste card se torna "Mago Negro" enquanto estiver no campo ou no Cemitério. \r\nSe este card for Invocado por Invocação-Especial: você pode adicionar 1 "Mago Negro" ou 1 card que o mencione do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59419719,'Fusão Fóssil',replace(replace('Invoque por Invocação-Fusão 1 Monstro de Fusão "Fóssil" do seu Deck Adicional, ao banir as Matérias de Fusão mencionadas nele de quaisquer Cemitérios (exceto por matérias que listem uma exigência específica de Cemitério). \r\nSe você baniu monstros dos dois Cemitérios, nenhum duelista pode escolher esse monstro Invocado por Invocação-Especial como alvo de efeitos de monstro. \r\nSe um ou mais Monstros de Fusão "Fóssil" com a face para cima que você controla forem destruídos em batalha ou por um efeito de card, enquanto este card estiver no seu Cemitério: você pode adicionar este card do Cemitério à sua mão. \r\nVocê só pode usar este efeito de "Fusão Fóssil" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Fusão','Recuperar do Cemitério','O efeito de "Fusão Fóssil" está sendo aplicado.','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59432181,'Identificar Fusão','Escolha 1 monstro que você controla; revele 1 Monstro de Fusão no seu Deck Adicional e, se isso acontecer, o nome do monstro alvo pode ser considerado como o nome do Monstro de Fusão revelado, se ele for usado como Matéria de Fusão neste turno.','O efeito de "Identificar Fusão" está sendo aplicado.','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59438930,'Ogro Fantasma & Coelho da Neve',replace(replace('Quando um monstro no campo ativar seu efeito, ou quando uma Magia/Armadilha que já esteja com a face para cima no campo ativar seu efeito (Efeito Rápido): você pode enviar este card da sua mão ou do campo para o Cemitério; destrua esse card no campo. \r\nVocê só pode usar este efeito de "Ogro Fantasma & Coelho da Neve" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59438931,'Ogro Fantasma & Coelho da Neve',replace(replace('Quando um monstro no campo ativar seu efeito, ou quando uma Magia/Armadilha que já esteja com a face para cima no campo ativar seu efeito (Efeito Rápido): você pode enviar este card da sua mão ou do campo para o Cemitério; destrua esse card no campo. \r\nVocê só pode usar este efeito de "Ogro Fantasma & Coelho da Neve" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59438932,'Ogro Fantasma & Coelho da Neve',replace(replace('Quando um monstro no campo ativar seu efeito, ou quando uma Magia/Armadilha que já esteja com a face para cima no campo ativar seu efeito (Efeito Rápido): você pode enviar este card da sua mão ou do campo para o Cemitério; destrua esse card no campo. \r\nVocê só pode usar este efeito de "Ogro Fantasma & Coelho da Neve" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59463312,'Eidos, o Escudeiro do Submundo',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: durante sua Fase Principal deste turno, você pode Invocar 1 monstro por Invocação-Tributo, em adição à sua Invocação-Normal/Baixar (padrão). \r\n(Você só pode se aproveitar deste efeito uma vez por turno.) \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 monstro com 800 de ATK/1000 de DEF no seu Cemitério, exceto "Eidos, o Escudeiro do Submundo"; Invoque-o por Invocação-Especial em Posição de Defesa e, além disso, você não pode Invocar monstros do Deck Adicional por Invocação-Especial pelo resto deste turno. \r\nVocê só pode usar este efeito de "Eidos, o Escudeiro do Submundo" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','Invocar pelo efeito de "Eidos, o Escudeiro do Submundo"','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59464593,'Dragão Armado LV10',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao oferecer como Tributo 1 "Dragão Armado LV7". \r\nVocê pode enviar 1 card da sua mão para o Cemitério; destrua todos os monstros com a face para cima que seu oponente controla.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59464594,'Dragão Armado LV10',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao oferecer como Tributo 1 "Dragão Armado LV7". \r\nVocê pode enviar 1 card da sua mão para o Cemitério; destrua todos os monstros com a face para cima que seu oponente controla.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59479050,'Número 71: Tubarão Rebarian',replace(replace('2 monstros de Nível 3	\r\nUma vez por turno, se este card tiver alguma matéria: você pode escolher 1 Monstro Xyz "Número" no seu Cemitério, exceto "Número 71: Tubarão Rebarian"; Invoque-o por Invocação-Especial e, se isso acontecer, associe 1 matéria deste card a ele. \r\nSe este card for enviado para o Cemitério: você pode colocar no topo do seu Deck 1 Magia "Magia de Aumento de Classe" do seu Deck.','\r',char(13)),'\n',char(10)),'Invocação Especial','Escolha a(s) Matéria(s) Xyz deste card','Procurar no Deck','Escolha o(s) card(s) para colocar no topo do Deck','','','','','','','','','','','','');
INSERT INTO texts VALUES(59481082,'Dragãozinho Luminoso',replace(replace('Se você tiver um monstro "Luminoso(a)" no seu Cemitério: você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe este card for Invocado por Invocação-Especial: você pode enviar 1 card "Luminoso(a)" do seu Deck para o Cemitério, exceto "Dragãozinho Luminoso". \r\nSe este card for enviado para o Cemitério: você pode adicionar 1 monstro Dragão com 3000 de ATK/2600 de DEF do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "Dragãozinho Luminoso" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Enviar para o Cemitério','Adicionar à mão','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59482302,'Defesa Aliada','Quando este card for destruído em batalha com um monstro de LUZ e enviado ao Cemitério, selecione 2 cards no campo e destrua-os.','Destrua 2 cards no campo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59490397,'Fim de Gergonne',replace(replace('Escolha 1 Monstro Link "Tindângulo" que você controla; equipe este card a ele. \r\nEle não pode ser destruído em batalha ou por efeitos de card e, além disso, seu oponente não pode escolhê-lo como alvo de efeitos de card. \r\nUma vez por turno, se houver monstros em todas as zonas para as quais o monstro equipado apontar: se ainda houver monstros em todas as zonas para as quais o monstro equipado apontar, você pode destruir este card e todos esses monstros e, depois, cause dano ao seu oponente igual ao ATK do monstro equipado antes de ele ser destruído.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59494222,'Inscrição do Coveiro',replace(replace('No começo da sua Fase Principal 1: aplique 1 dos seguintes efeitos até o final do turno do seu oponente.\r\n● Nenhum duelista pode ativar efeitos de card no Cemitério.\r\n● Nenhum duelista pode banir cards do Cemitério.\r\n● Nenhum duelista pode Invocar monstros por Invocação-Especial dos Cemitérios.','\r',char(13)),'\n',char(10)),'Nenhum jogador pode ativar os efeitos de cards no Cemitério','Nenhum jogador pode banir cards do Cemitério','Nenhum jogador pode Invocar por Invocação Especial monstros do Cemitério','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59496924,'Transporte Blindado de Kozmo',replace(replace('Se um ou mais cards "Kozmo" que você controla seriam destruídos em batalha ou por um efeito de card do oponente, em vez disso, você pode destruir 1 outro card "Kozmo" que você controla. \r\nSe este card for destruído em batalha ou por um efeito de card e enviado para o Cemitério: você pode banir este card do seu Cemitério; Invoque por Invocação-Especial 1 monstro "Kozmo" de Nível 5 ou menos do seu Deck.','\r',char(13)),'\n',char(10)),'Usar o efeito de "Transporte Blindado de Kozmo" para usar outro card como substituto da destruição?','Invoque por Invocação Especial um monstro "Kozmo" do Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59504256,'Semideus da Tistina',replace(replace('Se você controlar um card "Tistina": você pode Invocar este card por Invocação-Especial da sua mão e, depois, você pode adicionar 1 Magia/Armadilha "Tistina" do seu Deck à sua mão. \r\nDurante o turno do seu oponente, se você controlar "Deus de Cristal Tistina" (Efeito Rápido): você pode colocar tantos monstros que seu oponente controla quanto possível com a face para baixo em Posição de Defesa e, depois, você pode enviar para o Cemitério todos os cards com a face para cima que seu oponente controla. \r\nVocê só pode usar cada efeito de "Semideus da Tistina" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Adicionar 1 Card de Magia/Armadilha "Tistina" do seu Deck à sua mão?','Enviar para o Cemitério todos os cards com a face para cima que seu oponente controla?','','','','','','','','','','','','');
INSERT INTO texts VALUES(59509952,'Archlord Kristya',replace(replace('Se você tiver exatamente 4 monstros Fada no seu Cemitério, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nSe Invocado desta forma: escolha 1 monstro Fada no seu Cemitério; adicione o alvo à sua mão. \r\nNenhum duelista pode Invocar monstros por Invocação-Especial. \r\nSe este card com a face para cima seria enviado do campo para o Cemitério, em vez disso, coloque-o no topo do Deck.','\r',char(13)),'\n',char(10)),'Invocação Especial','Recuperar do Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59514116,'Segredos da Magia Negra',replace(replace('Ative 1 dos seguintes efeitos;\r\n● Invoque por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional, usando monstros da sua mão ou do campo, incluindo "Mago Negro" ou "Pequena Maga Negra".\r\n● Invoque por Invocação-Ritual 1 Monstro de Ritual da sua mão, ao oferecer como Tributo monstros da sua mão ou do campo, incluindo "Mago Negro" ou "Pequena Maga Negra", cuja soma dos Níveis seja igual ou exceda o Nível do Monstro de Ritual.','\r',char(13)),'\n',char(10)),'Invocação Fusão','Invocação Ritual','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59514117,'Segredos da Magia Negra',replace(replace('Ative 1 dos seguintes efeitos;\r\n● Invoque por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional, usando monstros da sua mão ou do campo, incluindo "Mago Negro" ou "Pequena Maga Negra".\r\n● Invoque por Invocação-Ritual 1 Monstro de Ritual da sua mão, ao oferecer como Tributo monstros da sua mão ou do campo, incluindo "Mago Negro" ou "Pequena Maga Negra", cuja soma dos Níveis seja igual ou exceda o Nível do Monstro de Ritual.','\r',char(13)),'\n',char(10)),'Invocação Fusão','Invocação Ritual','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59531356,'Guerreiro Fóssil Cavaleiro Caveira',replace(replace('1 monstro Rocha + 1 monstro de Nível 5 ou 6	\r\nPrimeiro deve ser Invocado por Invocação-Especial com "Fusão Fóssil". \r\nSe este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante. \r\nQuando este card atacante destruir um monstro em batalha: você pode ativar este efeito; este card pode realizar um segundo ataque em seguida. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 monstro no campo; destrua-o. \r\nVocê só pode usar este efeito de "Guerreiro Fóssil Cavaleiro Caveira" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59537380,'Dragão-Guarda Agardor',replace(replace('2 monstros Dragão	\r\nVocê não pode Invocar monstros por Invocação-Especial, exceto monstros Dragão. \r\nDurante sua Fase Principal: você pode Invocar por Invocação-Especial 1 monstro Dragão do seu Deck Adicional, em uma Zona de Monstros Adicional ou Zona de Monstros Principal onde você possa Invocar, para a qual 2 ou mais Monstros Link apontarem. \r\nVocê só pode usar este efeito de "Dragão-Guarda Agardor" uma vez por turno. \r\nVocê só pode Invocar um ou mais "Dragão-Guarda Agardor" por Invocação-Especial uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59546528,'Princesa Dançarina da Barreira de Gelo','Uma vez por turno, se você controlar outro monstro "Barreira de Gelo": você pode revelar qualquer número de monstros "Barreira de Gelo" na sua mão e, depois, escolha um mesmo número de Magias/Armadilhas Baixadas que seu oponente controla; devolva os alvos para a mão.','Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59546797,'Juragedo',replace(replace('Durante a Etapa de Batalha (Efeito Rápido): você pode Invocar este card por Invocação-Especial da sua mão e, se isso acontecer, ganhe 1000 PV. \r\nVocê só pode usar este efeito de "Juragedo" uma vez por turno. \r\n(Efeito Rápido): você pode oferecer este card como Tributo e, depois, escolha 1 monstro com a face para cima que você controla; ele ganha 1000 de ATK até o final do próximo turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59560625,'Mudança','Quando seu oponente escolher exatamente 1 monstro que você controla (e nenhum outro card) como alvo de um ataque ou com um efeito de Magia/Armadilha: escolha outro monstro que você controla que seria um alvo apropriado; esse ataque/Magia/Armadilha agora escolhe esse novo alvo como alvo.','Mude o alvo de um efeito do seu oponente','Mude o alvo de ataque do seu oponente','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59563768,'Tenshin','Este card ganha 400 de ATK para cada monstro de Nível 2 com a face para cima que você controla.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59575539,'Krebons','Quando este card for alvo de um ataque: você pode pagar 800 PV; negue o ataque.','Negue o ataque','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59576447,'Veredito de Anúbis',replace(replace('Quando seu oponente ativar um Card de Magia/Armadilha, enquanto você controlar 3 ou mais outras Magias/Armadilhas: negue a ativação e, se isso acontecer, destrua esse card e, depois, se você controlar "Templo dos Reis", você pode destruir tantos monstros que seu oponente controla quanto possível e, depois, cause dano ao seu oponente igual à metade da soma do ATK original desses monstros destruídos. \r\nVocê só pode ativar 1 "Veredito de Anúbis" por turno.','\r',char(13)),'\n',char(10)),'','Destruir todos os monstros?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59577547,'Salamagrande Papaga',replace(replace('Quando um monstro do oponente declarar um ataque: você pode Invocar este card por Invocação-Especial da sua mão, em Posição de Ataque. \r\nSe este card for Invocado por Invocação-Especial: você pode escolher 1 monstro "Salamagrande" no seu Cemitério; o ATK deste card se torna o do alvo. \r\nVocê pode oferecer este card como Tributo; ganhe 2000 PV. \r\nVocê só pode usar este efeito de "Salamagrande Papaga" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59581480,'Tinia de Elfnota',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) em sua Zona de Monstros Principal central. \r\nVocê só pode Invocar "Tinia de Elfnota" por Invocação-Especial uma vez por turno desta forma. \r\nVocê só pode usar cada um dos seguintes efeitos de "Tinia de Elfnota" uma vez por turno. \r\nDurante sua Fase Principal: você pode colocar 1 Magia Contínua "Elfnota" do seu Deck com a face para cima no seu campo. \r\nDurante o turno do seu oponente (Efeito Rápido): você pode trocar as localizações deste card na sua Zona de Monstros Principal e o monstro na sua Zona de Monstros Principal central e, depois, você pode banir (com a face para cima) 1 card aleatório da mão do seu oponente, até a Fase Final.','\r',char(13)),'\n',char(10)),'Baixar 1 Card de Magia','Trocar posições','Banir 1 card da sua mão?','Banir até a Fase Final','','','','','','','','','','','','');
INSERT INTO texts VALUES(59593925,'Destruição do Ressonante',replace(replace('Sempre que um ou mais monstros "Ressonador" forem enviados para o Cemitério como Matérias Sincro: escolha 1 card que seu oponente controla; destrua o alvo. \r\nDestrua este card durante sua 2ª Fase Final depois da sua ativação.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59604521,'Trapestrela Rodode',replace(replace('Você pode descartar 1 card "Trapestrela" e, depois, escolher 1 Monstro Link "Trapestrela" no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê só pode usar este efeito de "Trapestrela Rodode" uma vez por turno. \r\nSempre que um ou mais cards forem banidos do Cemitério do seu oponente, imediatamente cause 200 de dano ao seu oponente para cada card banido.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59616123,'Atordoar Armadilha','Negue todos os outros efeitos de Armadilha no campo neste turno.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59627393,'Número 105: Boxeador Obstinado Estrela Cestus',replace(replace('3 monstros de Nível 4	\r\nUma vez por Corrente, durante a Etapa de Batalha, se um monstro "Boxeador Obstinado" seu batalhar um monstro do oponente (Efeito Rápido): você pode desassociar 1 matéria deste card; negue os efeitos desse monstro do oponente enquanto ele estiver com a face para cima até o final deste turno, esse monstro que você controla não pode ser destruído nessa batalha e, além disso, seu oponente sofre todo o dano de batalha que você teria sofrido nessa batalha.','\r',char(13)),'\n',char(10)),'Negar o efeito','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59640711,'Duke Den-Den Daiko Velocidaroide',replace(replace('Você pode banir este card do seu Cemitério; Invoque por Invocação-Especial 1 Regulador "Velocidaroide" da sua mão ou do Cemitério, exceto "Duke Den-Den Daiko Velocidaroide". \r\nVocê só pode usar este efeito de "Duke Den-Den Daiko Velocidaroide" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59642500,'Anki, o HERÓI Mascarado',replace(replace('Deve ser Invocado por Invocação-Especial com "Mudar a Máscara". 	\r\nEste card pode atacar diretamente, mas quando ele fizer isso usando este efeito, o dano de batalha causado ao seu oponente é diminuído pela metade. \r\nQuando este card destruir um monstro do oponente em batalha e enviá-lo para o Cemitério: você pode adicionar 1 Card de Magia Rápida "Mudar" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Anki, o HERÓI Mascarado" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59644128,'Gouki, Ogro de Jato',replace(replace('2 monstros "Gouki"	\r\nUma vez por turno: você pode escolher 1 card "Gouki" que você controla; destrua-o e, se isso acontecer, coloque todos os monstros no campo com a face para cima em Posição de Ataque. \r\nSe este card for enviado do campo para o Cemitério: você pode fazer com que todos os monstros "Gouki" que você controla atualmente ganhem 500 de ATK até o final deste turno. \r\nVocê só pode usar este efeito de "Gouki, Ogro de Jato" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59644958,'Coruja de Sobreposição','Uma vez por turno: Você pode pagar 600 PV; desassocie 1 Matéria Xyz de um monstro no campo.','Desassociar Matéria','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59650656,'Buraco Caótico de Táquion',replace(replace('Quando um ou mais Monstros Xyz "Galáxia" com a face para cima que você controla forem destruídos em batalha com um monstro atacante do oponente ou por um efeito de card do oponente e enviados para o seu Cemitério: destrua tantos cards com a face para cima que seu oponente controla quanto possível e, se isso acontecer, bana-os. \r\nDurante sua Fase de Compra, se este card estiver no seu Cemitério, em vez de conduzir sua compra normal: você pode banir este card e, depois, escolher 1 Monstro Xyz "Galáxia" no seu Cemitério; Invoque o alvo por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Destruir e banir','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59687381,'Zona de Defesa','Para cada monstro que um duelista controla em sua Zona de Monstros Principal, suas Magias/Armadilhas na mesma coluna que esse monstro não podem ser destruídas por efeitos de card do seu oponente e seu oponente não pode escolhê-las como alvo de efeitos de card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59695933,'Interceptação',replace(replace('Ative apenas quando um monstro for Invocado por Invocação-Tributo com 1 Tributo. \r\nTome o controle desse monstro.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59699355,'Ira de Restolhos',replace(replace('Só pode ser ativado durante o cálculo de dano, se um monstro "Restolhos" em Posição de Defesa no campo estiver sendo atacado. \r\nEle ganha 2000 de DEF e é destruído no final da Fase de Batalha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59707204,'Simorgh, Pássaro da Proteção',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode escolher 1 card na Zona de Magias & Armadilhas do seu oponente; devolva-o para a mão. \r\nSe este card estiver no seu Cemitério e seu oponente não controlar nenhum card na Zona de Magias & Armadilhas dele: você pode Invocar este card por Invocação-Especial em Posição de Defesa, mas bana-o quando ele deixar o campo e, além disso, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros Besta Alada. \r\nVocê só pode usar cada efeito de "Simorgh, Pássaro da Proteção" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59708927,'Terror Umbral Fantasma',replace(replace('Durante sua Fase Principal: você pode Invocar por Invocação-Especial este card e 1 monstro do Tipo Demônio de Nível 4 ou menos da sua mão. \r\nVocê não pode Invocar por Invocação-NormaI/Baixar durante o turno em que ativar este efeito. \r\nVocê só pode usar este efeito de "Terror Umbral Fantasma" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59712426,'Força Arcana XV - O Demônio',replace(replace('Você pode descartar este card; adicione 1 "Barreira de Luz" do seu Deck ou Cemitério à sua mão. \r\nSe este card for Invocado: lance uma moeda e este card ganha o efeito apropriado.\r\n● Cara: Quando um ataque for declarado envolvendo este card: você pode escolher 1 monstro no campo; destrua-o e, se isso acontecer, cause 500 de dano ao seu controlador.\r\n● Coroa: Se um ataque for declarado envolvendo este card: destrua todos os monstros no campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59718521,'Mente Sobre a Matéria','Quando um monstro seria Invocado por Invocação-Normal ou Especial OU um Card de Magia/Armadilha for ativado: ofereça como Tributo 1 monstro do Tipo Psíquico; negue a Invocação ou ativação e, se isso acontecer, destrua esse card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59724555,'Dodododanão Gogogogluva',replace(replace('Durante sua Fase Principal: você pode Invocar por Invocação-Especial 1 monstro "Zubaba" ou "Gagaga" da sua mão. \r\nSe você controlar um monstro "Gogogo" ou "Dododo" exceto "Dodododanão Gogogogluva", enquanto este card estiver no seu Cemitério: você pode Invocar este card por Invocação-Especial, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar cada efeito de "Dodododanão Gogogogluva" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59741415,'Extenuação Autômata',replace(replace('Escolha 1 monstro Máquina que você controla; Invoque por Invocação-Especial 1 monstro "Autômata(o)" com um nome diferente da sua mão ou do Deck e, se isso acontecer, destrua esse monstro alvo. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 3 dos seus monstros Máquina que estiverem banidos e/ou no seu Cemitério; embaralhe-os no seu Deck e, depois, compre 1 card. \r\nVocê só pode usar 1 efeito de "Extenuação Autômata" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59744639,'Tufão de Etaqua','Mude a posição de batalha de todos os monstros com a face para cima que seu oponente controla.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59750328,'Despedida Final',replace(replace('Compre até ter 3 cards na sua mão e, além disso, pelo resto deste turno depois que este card resolver, seu oponente não sofre dano. \r\nDurante a Fase Final deste turno, envie toda sua mão para o Cemitério. \r\nVocê só pode ativar 1 "Despedida Final" por turno. \r\nVocê não pode Invocar por Invocação-Especial durante o turno em que ativar este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59755122,'Falange Dragunidade','Uma vez por turno, enquanto este card estiver equipado a um monstro: você pode Invocar este card equipado por Invocação-Especial.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59762399,'Fênix de Luz Camarartista de Olhos Anômalos',replace(replace('Escala de Pêndulo = 3\r\n[ Efeito de Pêndulo ]\r\nQuando um monstro do oponente declarar um ataque direto enquanto você tiver um card na sua outra Zona de Pêndulo: você pode destruir o card na sua outra Zona de Pêndulo e, se isso acontecer, Invoque este card por Invocação-Especial.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\n(Efeito Rápido): você pode oferecer este card como Tributo e, depois, escolher 1 monstro "Camarartista" que você controla; ele ganha 1000 de ATK até o final deste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59765225,'Dragão Sincro de Asas Transparentes Cristalinas',replace(replace('1 Monstro Sincro Regulador + 1 monstro "Asas Transparentes" não-Regulador	\r\nUma vez por turno, quando seu oponente ativar um efeito de monstro (exceto durante a Etapa de Dano) (Efeito Rápido): você pode ativar este efeito; até o final deste turno, este card com a face para cima não é afetado pelos efeitos ativados dos monstros do seu oponente e, além disso, este card ganha ATK igual ao ATK original desse monstro do oponente. \r\nUma vez por turno, quando um Card de Magia/Armadilha ou seus efeitos forem ativados (Efeito Rápido): você pode negar a ativação e, se isso acontecer, destrua esse card. \r\nSe este card Invocado por Invocação-Sincro que você controla for enviado para o seu Cemitério por um card do oponente: você pode adicionar 1 monstro de VENTO do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Aumentar ATK','Negar a ativação e destruir','','Não é afetado por efeitos de monstros ativados pelo seu oponente','','','','','','','','','','','','');
INSERT INTO texts VALUES(59771339,'Enfurecido Sucata',replace(replace('"Sucata Sincron" + 1 ou mais monstros não-Reguladores	\r\nVocê pode banir 1 monstro "Sucata" do seu Cemitério e, depois, escolher 1 monstro com a face para cima que seu oponente controla; o alvo perde ATK igual ao ATK do monstro banido. \r\nNo começo da Etapa de Dano, se este card atacar um monstro em Posição de Defesa: destrua esse monstro.','\r',char(13)),'\n',char(10)),'Reduzir ATK','Destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59778096,'Concessão do Legado Mundial',replace(replace('Ative 1 dos seguintes efeitos.\r\n● Envie 1 Monstro Link que seu oponente controla para o Cemitério.\r\n● Bana 7 cards "Legado Mundial" do seu Cemitério; adicione 1 monstro Ciberso do seu Deck à sua mão.	\r\nVocê só pode ativar 1 "Concessão do Legado Mundial" por turno.','\r',char(13)),'\n',char(10)),'Enviar para o Cemitério','Procurar no Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59784896,'Zebra das Trevas',replace(replace('Se este for o único card sob o seu controle durante sua Fase de Apoio, ele é automaticamente colocado em Posição de Defesa. \r\nVocê não pode mudar a posição de batalha deste card durante o mesmo turno.','\r',char(13)),'\n',char(10)),'Mudar para Posição de Defesa','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59785059,'Cavaleirardor Campeão',replace(replace('Enquanto este card estiver na sua mão: você pode escolher 3 cards "Cavaleirardor" que você controla; destrua-os e, se isso acontecer, Invoque este card por Invocação-Especial. \r\nUma vez por turno: você pode escolher 1 outro monstro "Cavaleirardor" que você controla; devolva-o para a mão e, se isso acontecer, coloque 1 monstro que seu oponente controla no fundo do Deck.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59789370,'Bugiganga Arakami, o Porco Arauto do Granizo',replace(replace('Se você controlar um monstro Máquina cujo ATK seja igual à sua própria DEF: você pode Invocar este card por Invocação-Especial da sua mão. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 monstro Máquina que você controla cujo ATK seja igual à sua própria DEF; envie 1 monstro Máquina, cujo ATK seja igual à sua própria DEF, do seu Deck para o Cemitério, com um Nível menor que o do monstro alvo e, se isso acontecer, o monstro alvo ganha ATK/DEF igual ao Nível do monstro enviado para o Cemitério x 100. \r\nVocê só pode usar cada efeito de "Bugiganga Arakami, o Porco Arauto do Granizo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59793705,'Lâmina Afiada, o HERÓI do Elemento','Se este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59797187,'Gonogo','No final da Etapa de Dano, se este card batalhou um monstro do oponente: coloque esse monstro com a face para baixo em Posição de Defesa.','Mudar para Posição de Defesa com a face para baixo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59805313,'Circunfogo Vulcânico',replace(replace('Se este card for enviado para o Cemitério: você pode ativar 1 desses efeitos (mas você só pode usar cada efeito de "Circunfogo Vulcânico" uma vez por turno);\r\n● Bana este card do seu Cemitério e, se isso acontecer, envie 1 monstro "Vulcânico(a)" do seu Deck para o Cemitério, exceto "Circunfogo Vulcânico".\r\n● Bana 1 card "Acelerador de Explosão" do seu campo com a face para cima ou Cemitério e, se isso acontecer, coloque com a face para cima no seu campo 1 Magia/Armadilha Contínua "Acelerador de Explosão" da sua mão ou do Deck.','\r',char(13)),'\n',char(10)),'Ativar o efeito escolhido','Enviar do Deck para o Cemitério','Baixar da mão/Deck','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59808784,'Berlineth, o Vassalo da Tempestade de Fogo',replace(replace('Você pode descartar 1 card; Invoque este card por Invocação-Especial da sua mão e, além disso, você não pode Invocar por Invocação-Especial monstros do Deck Adicional pelo resto deste turno. \r\nSe este card for oferecido como Tributo para uma Invocação-Tributo: você pode olhar a mão do seu oponente e banir 1 card da mão dele até a Fase Final. \r\nVocê só pode usar cada efeito de "Berlineth, o Vassalo da Tempestade de Fogo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59811955,'Oficina do Mecanismo Antigo','Escolha 1 monstro "Mecanismo Antigo" no seu Cemitério; adicione o alvo à sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59820352,'Cântico da Terra',replace(replace('Este card pode ser usado para a Invocação-Ritual de qualquer Monstro de Ritual de TERRA. \r\nVocê também deve oferecer como Tributo monstros da sua mão ou do campo cuja soma dos Níveis seja exatamente igual ao Nível do Monstro de Ritual que você Invocar por Invocação-Ritual.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59822133,'Dragão Espírito de Olhos Azuis',replace(replace('1 Regulador + 1+ monstros "Olhos Azuis" não-Reguladores	\r\nNenhum duelista pode Invocar 2 ou mais monstros por Invocação-Especial ao mesmo tempo. \r\nUma vez por turno, quando um efeito de um card no Cemitério for ativado (Efeito Rápido): você pode negar a ativação. \r\n(Efeito Rápido): você pode oferecer este card Invocado por Invocação-Sincro como Tributo; Invoque por Invocação-Especial 1 Monstro Sincro Dragão de LUZ do seu Deck Adicional em Posição de Defesa, exceto "Dragão Espírito de Olhos Azuis", mas destrua-o durante a Fase Final deste turno.','\r',char(13)),'\n',char(10)),'Negar a ativação','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59829423,'Senhor dos Bariões Desaparecidos',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) ao banir 3 cards do seu Cemitério (1 monstro, 1 Magia e 1 Armadilha). \r\nSe este card for Invocado por Invocação-Especial da mão: você pode banir 1 monstro e 2 Magias/Armadilhas do campo e/ou Cemitério do seu oponente. \r\nVocê só pode usar este efeito de "Senhor dos Bariões Desaparecidos" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invoque por Invocação Especial da mão','Banir 1 card','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59834564,'Colosso da Fogueira',replace(replace('Se você controlar um monstro de FOGO, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nSe este card for Invocado por Invocação-Especial: escolha 2 monstros de FOGO que você controla; destrua esses alvos.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59839761,'Corvo Delta - Anti Reversão',replace(replace('Se você controlar um monstro "Asanegra": destrua todas as Magias/Armadilhas com a face para baixo que seu oponente controla. \r\nSe você controlar exatamente 3 monstros "Asanegra", você pode ativar este card da sua mão.','\r',char(13)),'\n',char(10)),'Ativar aplicando o efeito de "Corvo Delta - Anti Reversão".','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59843383,'Shiranui Solsaga',replace(replace('1 Regulador Zumbi + 1+ monstros Zumbi não-Reguladores	\r\nSe este card for Invocado por Invocação-Especial: você pode devolver para o Deck Adicional qualquer número dos seus Monstros Sincro Zumbi que estiverem banidos ou no seu Cemitério e, depois, você pode destruir cards que seu oponente controla, igual ao número de cards devolvidos. \r\nSe um ou mais monstros Zumbi que você controla seriam destruídos em batalha ou por um efeito de card, em vez disso, você pode banir 1 monstro "Shiranui" do seu Cemitério. \r\nVocê só pode Invocar um ou mais "Shiranui Solsaga" por Invocação-Especial uma vez por turno.','\r',char(13)),'\n',char(10)),'Recupere um Monstro Sincro Zumbi','Destruir 1 card que seu oponente controla?','Usar o efeito de "Shiranui Solsaga" para banir um monstro em vez de ser destruído?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59851535,'Fazticeira Potterie',replace(replace('Durante a Fase Principal (Efeito Rápido): você pode oferecer este card como Tributo e, depois, descartar 1 Magia; Invoque por Invocação-Especial 1 monstro "Fazticeira" do seu Deck, exceto "Fazticeira Potterie". \r\nSe você não tiver cards na sua mão: você pode banir este card do seu Cemitério e, depois, escolher 1 card "Fazticeira" no seu Cemitério; adicione-o à sua mão. \r\nVocê só pode usar cada efeito de "Fazticeira Potterie" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Recuperar do Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59859086,'Mago do Esguicho',replace(replace('2 monstros Ciberso	\r\nVocê pode escolher 1 monstro Ciberso no seu Cemitério; Invoque-o por Invocação-Especial em Posição de Defesa, mas negue seus efeitos e, além disso, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros Ciberso. \r\nVocê só pode usar este efeito de "Mago do Esguicho" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59893882,'HERÓI Maligno Asa do Inferno - Retaliação',replace(replace('"Aviário, o HERÓI do Elemento" ou "Burstinatrix, o HERÓI do Elemento" + 1 monstro "HERÓI"	\r\nDeve ser Invocado por Invocação-Especial com "Fusão Negra". \r\nSe este card for Invocado por Invocação-Especial: você pode adicionar 1 "Fusão Negra" ou 1 card que o mencione do seu Deck ou Cemitério à sua mão, exceto Monstros de Fusão. \r\nSe um monstro "HERÓI" seu destruir um monstro do oponente em batalha: cause 2100 de dano ao seu oponente. \r\nVocê só pode usar cada efeito de "HERÓI Maligno Asa do Inferno - Retaliação" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Causar dano','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59900655,'Orgulho Dourado - Cabeça Nytro',replace(replace('Se você tiver menos PV que seu oponente: você pode Invocar este card por Invocação-Especial da sua mão. \r\nDurante a Fase de Apoio do seu oponente: você pode Invocar por Invocação-Especial 1 "Ficha de Nytro" (Piro/FOGO/Nível 8/ATK 0/DEF 0) no campo do seu oponente, mas ela não pode ser usada como Matéria Link. \r\nDurante a Fase Principal do seu oponente (Efeito Rápido): você pode escolher 1 "Ficha Nitro" no campo; destrua essa Ficha e, além disso, destrua todos os cards nas Zonas de Monstros e Zonas de Magias & Armadilhas adjacentes a ela. \r\nVocê só pode usar cada efeito de "Orgulho Dourado - Cabeça Nytro" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59900656,'Ficha de Nytro','Invocado por Especial com o efeito "Orgulho Dourado - Cabeça Nytro". Esta Ficha não pode ser usada como Matéria Link.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59901153,'Irmãs Phalaenop',replace(replace('Se a soma dos Níveis dos monstros que você controla for igual ou menor que a soma dos Níveis dos monstros que seu oponente controla: você pode oferecer este card como Tributo; adicione 1 monstro Inseto ou Planta de Nível 7 ou mais do seu Deck à sua mão. \r\nDurante a Fase Final deste turno, sofra 2700 de dano se você não Invocou o monstro adicionado, ou um card com o mesmo nome original, por Invocação-Normal ou Especial depois de ativar este efeito. \r\nVocê só pode usar este efeito de "Irmãs Phalaenop" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59905358,'Tentativa com Dado!','Quando seu oponente ativar um Card de Magia/Armadilha, ou um efeito de monstro que requer um lance de dados: negue a ativação e, se isso acontecer, destrua esse Card de Magia/Armadilha ou monstro.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59907935,'Demônio Cibernético',replace(replace('No começo da sua Draw Phase, se você não tiver cards na sua mão, compre 1 card a mais além da compra normal. \r\nDurante a sua End Phase, se você tiver 1 ou mais cards na sua mão, destrua este card.','\r',char(13)),'\n',char(10)),'Comprar','Destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59911557,'Goram Gogogo',replace(replace('Se este card for Invocado: mude a posição de batalha deste card. \r\nSe este card no campo for destruído e enviado para o Cemitério: envie 1 monstro "Gogogo" do seu Deck para o Cemitério.','\r',char(13)),'\n',char(10)),'Mudar a posição de batalha','Enviar para o Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59913418,'Demise, o Rei Supremo do Armagedom',replace(replace('Você pode Invocar este card por Invocação-Ritual com "Ciclo do Mundo". \r\nO nome deste card se torna "Demise, o Rei do Armagedom" enquanto estiver na mão ou no campo. \r\nEnquanto este card Invocado por Invocação-Ritual estiver no campo, seus Monstros de Ritual não podem ser destruídos em batalha. \r\nSe todos os monstros usados para a Invocação-Ritual deste card eram Monstros de Ritual, você não paga PV para ativar seus efeitos. \r\nUma vez por turno: você pode pagar 2000 PV; destrua tantos outros cards no campo quanto possível e, se isso acontecer, cause 200 de dano ao seu oponente para cada card destruído que ele controlava.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59919307,'De Trás à Frente','Escolha 1 monstro no seu Cemitério; Invoque-o por Invocação-Especial em Posição de Defesa.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59921227,'Alternador Blitzclique',replace(replace('Monstros que seu oponente controla perdem 300 de ATK/DEF para cada monstro Trovão que você controla. \r\nVocê só pode usar cada um dos seguintes efeitos de "Alternador Blitzclique" uma vez por turno. \r\nVocê pode embaralhar no Deck 1 outro card "Blitzclique" da sua mão ou do campo com a face para cima; adicione 1 monstro Trovão com um nome diferente do seu Deck à sua mão. \r\nVocê pode banir este card do seu Cemitério; adicione 1 Magia "Blitzclique" ou "Esconderijo no Céu, Coulomb" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'','Adicionar à mão um monstro','Adicionar uma Magia à mão','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59934749,'Isolde, Dois Contos dos Nobre Cavaleiros',replace(replace('2 monstros Guerreiro	\r\nSe este card for Invocado por Invocação-Link: você pode adicionar 1 monstro Guerreiro do seu Deck à sua mão, mas pelo resto deste turno, você não pode Invocar monstros com esse nome por Invocação-Normal/Baixar ou por Invocação-Especial, nem ativar seus efeitos de monstro. \r\nVocê pode enviar qualquer número de Magias de Equipamento com nomes diferentes do seu Deck para o Cemitério; Invoque por Invocação-Especial 1 monstro Guerreiro do seu Deck, cujo Nível seja igual ao número de cards enviado para o Cemitério. \r\nVocê só pode usar cada efeito de "Isolde, Dois Contos dos Nobre Cavaleiros" uma vez por turno.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Invocação Especial','Escolha o Nível do monstro a Invocar por Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59951714,'Majiosheldon',replace(replace('Não pode ser Invocado por Invocação-Especial, exceto por seu próprio efeito. \r\nSe este card for oferecido como Tributo para uma Invocação-Tributo, durante sua próxima Fase de Apoio: você pode Invocar este card por Invocação-Especial do seu Cemitério. \r\nVocê não pode Invocar monstros por Invocação-Especial do Deck Adicional durante o turno em que ativar este efeito.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59957503,'Troco','Quando seu oponente ativar um Card de Magia/Armadilha ou efeito de monstro ao pagar os PV dele: Negue a ativação e, se isso acontecer, devolva-o para o Deck.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59965151,'Fantasma de Gardna',replace(replace('Quando um monstro com a face para cima que você controla for selecionado como alvo de um ataque, você pode mudar o alvo para este card. \r\nQuando este card for destruído e enviado para o Cemitério, 1 monstro com a face para cima que seu oponente controla perde 1000 de ATK até a Fase Final.','\r',char(13)),'\n',char(10)),'Mudar alvo de ataque','Reduzir ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59969392,'Caveira Zumbi Arquidemônio',replace(replace('"Zumbi Espalha-praga" + 2+ monstros Zumbi não-Reguladores	\r\nMonstros Zumbi que você controla não podem ser destruídos por efeitos de card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(59975920,'Camada Vermelha Super Quantum',replace(replace('Se você não controlar nenhum monstro, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode usar cada um dos seguintes efeitos de "Camada Vermelha Super Quantum" uma vez por turno. \r\nQuando este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 card "Super Quant" no seu Cemitério; adicione-o à sua mão. \r\nSe este card for enviado para o Cemitério: você pode escolher 1 monstro "Super Quant" no seu Cemitério, exceto "Camada Vermelha Super Quantum"; Invoque-o por Invocação-Especial, mas ele não pode ativar seus efeitos.','\r',char(13)),'\n',char(10)),'Invoque este card por Invocação Especial da sua mão','Adicionar à mão','Invocação Especial','O efeito de "Camada Vermelha Super Quantum" está sendo aplicado.','','','','','','','','','','','','');
INSERT INTO texts VALUES(59983249,'Perfeição dos Monarcas',replace(replace('Uma vez por Corrente, se seu oponente Invocar um ou mais monstros por Invocação-Especial, e você controlar um monstro Invocado por Invocação-Tributo (exceto durante a Etapa de Dano): você pode banir 1 Magia/Armadilha "Monarca" do seu Cemitério e, depois, ative 1 desses efeitos (mas você só pode usar cada efeito de "Perfeição dos Monarcas" uma vez por turno);\r\n● Destrua 1 monstro no campo.\r\n● Destrua até 2 Magias/Armadilhas no campo.\r\n● Descarte 1 card aleatório da mão do seu oponente.\r\n● Destrua 1 card com a face para baixo no campo.\r\n● Coloque 1 card do campo no topo do Deck.\r\n● Bana 1 card no campo.','\r',char(13)),'\n',char(10)),'Ativar','Destrua 1 monstro no campo','Destrua até 2 Cards de Magia/Armadilha no campo','Seu oponente descarta 1 card aleatório','Destrua 1 card virado para baixo no campo','Retornar 1 card no campo para o topo do Deck','Banir 1 card no campo','','','','','','','','','');
INSERT INTO texts VALUES(59983499,'Elfa Dançante','Uma elfa que dança pelos céus com asas afiadas como navalhas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60004971,'Lança Divina da Dragunidade',replace(replace('Só pode ser equipado a um monstro "Dragunidade". \r\nEle ganha ATK igual ao seu Nível x 100 e, além disso, ele não é afetado por efeitos de Armadilha. \r\nDurante sua Fase Principal: você pode equipar 1 Dragão Regulador "Dragunidade" do seu Deck ao monstro equipado com este card como uma Magia de Equipamento. \r\nVocê só pode usar este efeito de "Lança Divina da Dragunidade" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60018643,'Codec Cinet',replace(replace('Se um ou mais monstros "Codificar Transmissor" forem Invocados por Invocação-Especial do Deck Adicional no seu campo (exceto durante a Etapa de Dano): você pode escolher 1 desses monstros; adicione 1 monstro Ciberso com o mesmo Atributo do seu Deck à sua mão e, além disso, você não pode Invocar monstros por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto monstros Ciberso (mesmo que este card deixe o campo). \r\nNeste turno, você não pode adicionar à sua mão outros monstros com esse mesmo Atributo com o efeito de "Codec Cinet" e você só pode ativar o efeito de "Codec Cinet" uma vez por Corrente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60023855,'Aranha Bebê',replace(replace('Você pode oferecer como Tributo 1 monstro de TREVAS; aumente os Níveis de todos os "Aranha Bebê" que você controla atualmente pelo Nível desse monstro oferecido como Tributo. \r\nVocê pode pagar metade dos seus PV, bana este card do seu Cemitério e desassocie 1 matéria de um Monstro Xyz de TREVAS seu e, depois, escolha 1 monstro de TREVAS no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Aranha Bebê" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60025883,'Dragão Duel Link, o Dragão de Duelo',replace(replace('2+ monstros, incluindo um Monstro Sincro	\r\nDurante a Fase Principal (Efeito Rápido): você pode banir 1 Monstro Sincro "Ferramenteiro" ou 1 Monstro Sincro Dragão de Nível 7 ou 8 do seu Deck Adicional; Invoque por Invocação-Especial 1 "Ficha de Dragão de Duelo" com o mesmo Tipo, Atributo, Nível, ATK e DEF que esse monstro tinha no Deck Adicional, em uma zona sua para a qual este card apontar. \r\nVocê só pode usar este efeito de "Dragão Duel Link, o Dragão de Duelo" uma vez por turno. \r\nEnquanto você controlar "Ficha de Dragão de Duelo", os monstros do seu oponente não podem escolher este card como alvo de ataques e, além disso, seu oponente não pode escolher este card como alvo de efeitos de card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60025884,'Ficha de Dragão de Duelo','Invocado por Especial com o efeito "Dragão Duel Link, o Dragão de Duelo". Quando Invocada, o Tipo/Atributo/Nível/ATK/DEF desta Ficha se tornam os mesmos que o Tipo/Atributo/Nível/ATK/DEF originais do monstro banido para Invocar esta Ficha por Especial.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60033398,'Guerreiros Antigos - Terrível Zhang Yuan',replace(replace('Todos os outros monstros "Guerreiros Antigos" que você controla não podem ser destruídos em batalha. \r\nVocê só pode usar cada um dos seguintes efeitos de "Guerreiros Antigos - Terrível Zhang Yuan" uma vez por turno.\r\n● No começo da Etapa de Dano, quando um monstro "Guerreiros Antigos" seu batalhar um monstro com a face para cima do oponente: você pode Invocar este card por Invocação-Especial da sua mão e, se isso acontecer, esse monstro do oponente perde 1000 de ATK.\r\n● Se um ou mais cards que seu oponente controla forem destruídos em batalha ou por um efeito de card: você pode escolher 1 card que seu oponente controla; destrua-o.','\r',char(13)),'\n',char(10)),'','Destruir 1 card','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60037599,'Drytron Gama Eltanin',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial com o efeito de um card "Drytron". \r\nVocê pode oferecer como Tributo 1 outro monstro "Drytron" ou 1 Monstro de Ritual, da sua mão ou do campo; Invoque este card por Invocação-Especial da sua mão ou do Cemitério em Posição de Defesa e, depois, você pode Invocar por Invocação-Especial 1 monstro "Drytron" com 2000 de ATK do seu Cemitério, exceto "Drytron Gama Eltanin". \r\nVocê não pode Invocar monstros por Invocação-Especial no turno em que ativar este efeito, exceto monstros que não podem ser Invocados por Invocação-Normal/Baixados. \r\nVocê só pode usar este efeito de "Drytron Gama Eltanin" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Invocar por Invocação Especial 1 monstro do Cemitério?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60071928,'Chave da Direita',replace(replace('Durante uma Invocação-Sincro, você pode substituir este card por qualquer 1 Regulador "Sincron". \r\nSe este card for Invocado por Invocação-Normal: você pode Invocar por Invocação-Especial 1 "Chave da Esquerda" da sua mão, do Deck ou do Cemitério. \r\nVocê só pode usar este efeito de "Chave da Direita" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60080151,'Memória de um Adversário',replace(replace('Quando um monstro do oponente declarar um ataque: você sofre dano igual ao ATK do monstro atacante e, se isso acontecer, bana o monstro. \r\nDurante a Fase Final do próximo turno do seu oponente, Invoque esse monstro por Invocação-Especial no seu lado do campo.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60082869,'Tornado de Pó','Escolha 1 Magia/Armadilha que seu oponente controla; destrua o alvo e, depois, você pode Baixar 1 Magia/Armadilha da sua mão.','Baixar um Card de Magia ou Armadilha?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60095092,'Despertar Vaylantz - Ativação Individual',replace(replace('Coloque 1 Monstro Pêndulo "Vaylantz" do seu Deck na sua Zona de Pêndulo. \r\nSe um card estiver em uma Zona do Campo: você pode banir este card do seu Cemitério e, depois, escolha 1 monstro "Vaylantz" na sua Zona de Monstros Principal; mova esse monstro que você controla para uma Zona de Monstros adjacente (horizontal). \r\nVocê só pode usar cada efeito de "Despertar Vaylantz - Ativação Individual" uma vez por turno.','\r',char(13)),'\n',char(10)),'Colocar na Zona de Pêndulo','Mover a posição','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60102563,'Panda Maji-Gire','Enquanto este card permanecer no Campo com a face para cima, cada vez que um monstro(s) do Tipo Besta no Campo é destruído, aumente o ATK deste card em 500 pontos.','Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60110982,'Armityle, o Fantasma do Caos - Fantasma da Fúria',replace(replace('"Uria, o Senhor das Chamas Cortantes" + "Hamon, o Senhor do Trovão Impactante" + "Raviel, o Senhor dos Fantasmas"	\r\nO nome deste card se torna "Armityle, o Fantasma do Caos" enquanto estiver no campo. \r\nUma vez por turno, durante sua Fase Principal: você pode conceder o controle deste card ao seu oponente. \r\nUma vez por turno, durante a Fase Final, se o controle deste card foi mudado neste turno: bana todos os cards que você controla e, depois, o dono deste card pode Invocar por Invocação-Especial 1 "Armityle, o Fantasma do Caos" do Deck Adicional dele, ignorando suas condições de Invocação.','\r',char(13)),'\n',char(10)),'','','Invocar "Armityle, o Fantasma do Caos" por Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60145298,'Diabellze, a Bruxa Branca',replace(replace('(Este card deve ser sempre considerado como um card "Floresta Branca".)	\r\nMonstros que você controla não podem ser destruídos pelos efeitos de card do seu oponente enquanto você controlar 2 ou mais monstros "Diabell". \r\nVocê só pode usar cada um dos seguintes efeitos de "Diabellze, a Bruxa Branca" uma vez por turno. \r\nVocê pode enviar 1 Magia/Armadilha da sua mão ou do campo para o Cemitério; Invoque este card por Invocação-Especial da sua mão. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode enviar 1 card "Despojos do Pecado" ou "Diabell" do seu Deck para o Cemitério.','\r',char(13)),'\n',char(10)),'Invocação Especial','Enviar para o Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60158866,'Eternidade do Sétimo',replace(replace('Escolha 1 Monstro Xyz "Número" que você controla com um número entre "101" e "107" em seu nome, ou 1 Monstro Xyz que você controla que tenha qualquer desses monstros como matéria e, depois, ative 1 desses efeitos;\r\n● Até o final deste turno, negue os efeitos de 1 monstro que seu oponente controla com ATK igual ou menor que o ATK do monstro alvo.\r\n● Desassocie todas as matérias do monstro alvo e, depois, você pode Invocar por Invocação-Especial 1 Monstro Xyz "Número" do seu Cemitério.	\r\nVocê só pode usar este efeito de "Eternidade do Sétimo" uma vez por turno.','\r',char(13)),'\n',char(10)),'Negar o efeito','Invocação Especial','Invocar por Invocação Especial um Monstro Xyz "Número" do Cemitério?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60161788,'Blizzed, o Defensor da Barreira de Gelo','Se este card for destruído em batalha e enviado para o Cemitério: compre 1 card.','Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60162470,'Extra Link Zero',replace(replace('Ative este card ao escolher 1 Monstro Link que você controla que esteja co-linkado a um Monstro Link na Zona de Monstros Adicional. \r\nO monstro alvo ganha 800 de ATK para cada Monstro Link no campo. \r\nSe um Monstro Link for Invocado por Invocação-Link usando o monstro alvo como matéria: até o final deste turno, esse Monstro Link ganha o mesmo aumento de ATK que o monstro alvo tinha (mesmo que este card deixe o campo). \r\nDepois do cálculo de dano, se o monstro alvo atacou: destrua este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60168186,'Pacto Obscuro com as Entidades',replace(replace('Quando um monstro "D/D/D" do tipo de card abaixo for Invocado por Invocação-Especial do Deck Adicional no seu campo: você pode ativar o efeito apropriado uma vez por turno;\r\n● Fusão: Ganhe 1000 PV.\r\n● Sincro: Seu oponente não pode escolher esse monstro Invocado por Invocação-Especial como alvo de efeitos de card.\r\n● Xyz: Bana 1 card do campo ou Cemitério.\r\n● Pêndulo: Compre 1 card e, depois, descarte 1 card.	\r\nUma vez por turno, durante sua Fase de Apoio: sofra 2000 de dano.','\r',char(13)),'\n',char(10)),'Fusão: Recupere 1000 PV.','Sincro: Monstros Invocados por Invocação Especial desta forma não podem ser alvo dos efeitos do seu oponente.','Xyz: Banir 1 card no campo ou em qualquer Cemitério.','Pêndulo: Compre 1 card e depois descarte 1 card.','Receba 2000 de dano','','','','','','','','','','','');
INSERT INTO texts VALUES(60176682,'Ataque Duplo! Vento e Trovão!!',replace(replace('Se você controlar um monstro "Guardião do Portão": escolha 1 card no campo; destrua-o. \r\nDurante sua Fase Principal: você pode banir este card do seu Cemitério; adicione à sua mão 1 dos seus "Sanga do Trovão", "Kazejin" ou "Suijin" que estiverem banidos ou no seu Deck. \r\nVocê só pode usar este efeito de "Ataque Duplo! Vento e Trovão!!" uma vez por turno.','\r',char(13)),'\n',char(10)),'Destruir 1 card','Procurar no Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60181553,'Mira, a Portadora da Estrela',replace(replace('3 monstros de Nível 1	\r\nSe este card com a face para cima seria destruído, em vez disso, você pode desassociar 1 Matéria Xyz deste card. \r\nOs monstros de Nível 4 ou menos que você controla não podem ser destruídos por efeitos de card.','\r',char(13)),'\n',char(10)),'Usar o efeito de "Mira, a Portadora da Estrela" em vez de ser destruído?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60187739,'Turborreforço',replace(replace('Se você tiver Invocado um monstro por Invocação-Normal neste turno, você pode Invocar este card por Invocação-Especial da sua mão. \r\nVocê pode oferecer este card como Tributo para destruir 1 monstro que seu oponente controla que batalhou com um dos seus monstros neste turno.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60195675,'Smaga Montanha Infinisteira',replace(replace('2 monstros de Nível 7	\r\nQuando este card destruir um monstro do oponente em batalha: você pode associar esse monstro a este card como matéria. \r\nVocê só pode usar cada um dos seguintes efeitos de "Smaga Montanha Infinisteira" uma vez por turno.\r\n● Você pode desassociar 1 matéria deste card; ele ganha 1000 de ATK.\r\n● Se este card estiver no seu Cemitério: você pode oferecer 1 Monstro Link Máquina como Tributo; Invoque este card por Invocação-Especial em Posição de Defesa.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60202749,'Abis-Esfera',replace(replace('Invoque por Invocação-Especial 1 monstro "Sirena" do seu Deck. \r\nSeus efeitos são negados. \r\nVocê não pode ativar quaisquer Cards de Magia. \r\nQuando este card deixar o campo, destrua esse monstro. \r\nDestrua este card durante a próxima Fase Final do seu oponente depois da ativação.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60203670,'Orgulho Dourado - Eliminador',replace(replace('Se você tiver menos PV que seu oponente: você pode Invocar este card por Invocação-Especial da sua mão. \r\nVocê pode banir 1 outro monstro "Orgulho Dourado" da sua mão, do campo com a face para cima ou do Cemitério; Invoque por Invocação-Especial 1 "Ficha de Orgulho Dourado" (Máquina/TREVAS/ATK 0/DEF 0) com o mesmo Nível que o desse monstro banido e, além disso, este card não pode ser usado como matéria para uma Invocação-Fusão, Sincro, Xyz ou Link neste turno, exceto por um monstro "Orgulho Dourado". \r\nVocê só pode usar cada efeito de "Orgulho Dourado - Eliminador" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Invocar uma Ficha por Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60203671,'Ficha de Orgulho Dourado','Invocado por Especial com o efeito "Orgulho Dourado - Eliminador".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60222213,'Raphion, o Senhor do Tempo',replace(replace('Não pode ser Invocado por Invocação-Especial do Deck. \r\nSe você não controlar nenhum monstro, você pode Invocar este card por Invocação-Normal sem oferecer Tributo. \r\nNão pode ser destruído em batalha ou por efeitos de card. \r\nVocê não sofre dano de batalha dos ataques envolvendo este card. \r\nNo final da Fase de Batalha, se este card batalhou: cause dano ao seu oponente igual ao ATK de 1 monstro que seu oponente controla que batalhou este card neste turno. \r\nUma vez por turno, durante sua Fase de Apoio: embaralhe este card no Deck.','\r',char(13)),'\n',char(10)),'Invocação Normal sem Tributo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60222582,'Expedição da Galáxia',replace(replace('Se você controlar um monstro "Fóton" ou "Galáxia" de Nível 5 ou mais: Invoque por Invocação-Especial 1 monstro "Fóton" ou "Galáxia" de Nível 5 ou mais do seu Deck em Posição de Defesa. \r\nVocê só pode ativar 1 "Expedição da Galáxia" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60226558,'Fusão Sombraneco Nephe',replace(replace('Ative este card ao declarar 1 Atributo. \r\nSó pode ser equipado a um monstro "Sombraneco" e ele se torna desse Atributo. \r\nDurante sua Fase Principal: você pode Invocar por Invocação-Fusão 1 Monstro de Fusão "Sombraneco" do seu Deck Adicional, usando monstros da sua mão ou do campo como Matéria de Fusão, incluindo o monstro equipado. \r\nVocê só pode usar este efeito de "Fusão Sombraneco Nephe" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60228941,'Snoww, Sem Luz do Mundo Negro','Se este card for descartado para o Cemitério por um efeito de card: se ele foi descartado da sua mão para o seu Cemitério por um efeito de card do oponente, você pode escolher 1 monstro no Cemitério do seu oponente; adicione 1 card "Mundo Negro" do seu Deck à sua mão e, depois, Invoque o alvo (se houver) por Invocação-Especial em Posição de Defesa.','Adicionar à mão','Invocar por Invocação Especial um monstro do Cemitério do seu oponente?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60229110,'Grandmarg, o Monarca da Rocha','Se este card for Invocado por Invocação-Tributo: escolha 1 card Baixado no campo; destrua o alvo.','Destrua 1 card Baixado no campo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60234913,'Ritual da Graça',replace(replace('Este card é usado para a Invocação-Ritual de "Graça Divina - Nortewemko". \r\nVocê também deve oferecer como Tributo monstros cuja soma dos Níveis seja igual a 7 ou mais do campo ou da sua mão. \r\nDurante sua Fase Principal, você pode remover de jogo este card do seu Cemitério para fazer com que 1 Monstro de Ritual com a face para cima que você controla não possa ser escolhido como alvo de efeitos neste turno.','\r',char(13)),'\n',char(10)),'Monstros Ritual não podem ser alvo de efeitos','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60237530,'Punhos dos Dois Avatares - Ah-Gyo com Armadura',replace(replace('2 monstros "Dois Avatares"	\r\nSe este card for Invocado por Invocação-Especial: você pode escolher 1 monstro em Posição de Ataque que seu oponente controla; destrua-o e, além disso, este card não pode atacar diretamente pelo resto deste turno. \r\nVocê só pode usar este efeito de "Punhos dos Dois Avatares - Ah-Gyo com Armadura" uma vez por turno. \r\nEnquanto você controlar um Monstro de Fusão "Dois Avatares" que foi Invocado por Invocação-Fusão usando um Monstro de Efeito como matéria, todos os Monstros de Fusão "Dois Avatares" que você controla ganham 300 de ATK/DEF.','\r',char(13)),'\n',char(10)),'Destruir 1 monstro','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60238002,'Expedidor Interdimensional de Matéria',replace(replace('Você pode escolher 1 monstro no campo; bana-o e, depois, devolva-o para o campo. \r\nSe seu oponente ativar um card ou efeito: você pode escolher 1 monstro com a face para cima no campo cujos efeitos estejam sendo negados; bana-o e, depois, devolva-o para o campo. \r\nAntes de resolver um efeito do oponente que escolha este card no campo como alvo, bana este card até a Fase Final do próximo turno. \r\nVocê só pode usar cada efeito de "Expedidor Interdimensional de Matéria" uma vez por turno.','\r',char(13)),'\n',char(10)),'Banir um monstro','Banir um monstro com efeitos negados','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60242223,'Bistial Saronir',replace(replace('Você pode escolher 1 monstro de LUZ ou de TREVAS em qualquer Cemitério; bana-o e, se isso acontecer, Invoque este card por Invocação-Especial da sua mão. \r\nEste é um Efeito Rápido se seu oponente controlar um monstro. \r\nSe este card for enviado para o Cemitério: você pode enviar 1 monstro "Bistial" ou 1 Magia/Armadilha "Marcado" do seu Deck para o Cemitério, exceto "Bistial Saronir". \r\nVocê só pode usar cada efeito de "Bistial Saronir" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60246171,'Soitsu','Aparentemente totalmente não confiável, ele imagina se ele tem um incrível potencial.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60258960,'Lord da Chama Lendária',replace(replace('Este card não pode ser Invocado a não ser por Invocação-Ritual com o Card de Magia de Ritual "Provação Incandescente". \r\nTambém deve oferecer como Tributo monstros cuja soma dos Níveis seja igual ou maior que 7, do Campo ou da sua mão. \r\nCada vez que você ou o seu adversário activam 1 Card de Magia, ponha 1 Contador Mágico neste card. \r\nRemova 3 Contadores Mágicos deste card para destruir todos os monstros no Campo exceto este card.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60268386,'Besta Heráldica Grifo',replace(replace('Você pode enviar 1 monstro "Besta Heráldica" do seu Deck para o Cemitério, exceto "Besta Heráldica Grifo"; Invoque este card por Invocação-Especial da sua mão e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto por uma Invocação-Xyz que use como matéria apenas monstros com "Besta Heráldica" ou "Número" em seus nomes originais. \r\nPode ser considerado como 2 matérias para a Invocação-Xyz de um Monstro Xyz "Número" que requer 3 ou mais matérias. \r\nVocê só pode usar cada efeito de "Besta Heráldica Grifo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60279710,'Ardiloso Ciberso',replace(replace('2+ monstros	\r\nSe você controlar este card que foi Invocado por Invocação-Link usando "Mago Ciberso" como matéria (Efeito Rápido): você pode escolher 1 monstro que seu oponente controla; mude sua posição de batalha e, se isso acontecer, negue seus efeitos até o final do turno. \r\nSe este card for destruído em batalha, ou se este card em posse do seu dono for destruído por um efeito de card do oponente: você pode Invocar por Invocação-Especial 1 "Mago Ciberso" da sua mão, do Deck ou do Cemitério. \r\nVocê só pode usar cada efeito de "Ardiloso Ciberso" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60283232,'Roda Sincron',replace(replace('Se este card que você controla for usado como Matéria Sincro, você pode considerá-lo como um não-Regulador. \r\nVocê só pode usar cada um dos seguintes efeitos de "Roda Sincron" uma vez por turno. \r\nDurante sua Fase Principal, você pode: imediatamente depois que este efeito resolver, Invoque por Invocação-Normal 1 monstro de Nível 4 ou menos e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto Monstros Sincro. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 Monstro Sincro que você controla; reduza o Nível dele em até 4.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60292055,'Elfase',replace(replace('2 monstros Ciberso de Nível 3 ou mais	\r\nGanha 300 de ATK para cada monstro para o qual este card apontar. \r\nSe este card Invocado por Invocação-Link deixar o campo: você pode escolher 1 monstro Ciberso de Nível 4 ou menos no seu Cemitério; Invoque-o por Invocação-Especial, mas pelo resto deste turno, seus efeitos (se houver) são negados e ele não pode ser usado como Matéria Link. \r\nVocê só pode usar este efeito de "Elfase" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60303245,'Salamagrande Almiraj',replace(replace('1 monstro Invocado por Invocação-Normal com 1000 ou menos de ATK	\r\n(Efeito Rápido): você pode oferecer este card como Tributo e, depois, escolha 1 monstro que você controla; ele não pode ser destruído pelos efeitos de card do seu oponente neste turno. \r\nQuando um monstro Invocado por Invocação-Normal que você controla for destruído em batalha, enquanto este card estiver no seu Cemitério: você pode Invocar este card por Invocação-Especial. \r\nVocê só pode usar este efeito de "Salamagrande Almiraj" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60303688,'Dogmatika Ecclesia, a Virtuosa',replace(replace('Não pode ser destruído em batalha com um monstro Invocado por Invocação-Especial do Deck Adicional. \r\nVocê só pode usar cada um dos seguintes efeitos de "Dogmatika Ecclesia, a Virtuosa" uma vez por turno. \r\nSe um monstro Invocado por Invocação-Especial do Deck Adicional estiver no campo: você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode ativar este efeito; adicione 1 card "Dogmatika" do seu Deck à sua mão, exceto "Dogmatika Ecclesia, a Virtuosa" e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60303689,'Dogmatika Ecclesia, a Virtuosa',replace(replace('Não pode ser destruído em batalha com um monstro Invocado por Invocação-Especial do Deck Adicional. \r\nVocê só pode usar cada um dos seguintes efeitos de "Dogmatika Ecclesia, a Virtuosa" uma vez por turno. \r\nSe um monstro Invocado por Invocação-Especial do Deck Adicional estiver no campo: você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode ativar este efeito; adicione 1 card "Dogmatika" do seu Deck à sua mão, exceto "Dogmatika Ecclesia, a Virtuosa" e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60306104,'Não Entre!','Coloque em Posição de Defesa todos os monstros que estão em Posição de Ataque.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60306277,'Zona Sincro',replace(replace('Nenhum duelista pode declarar ataques, exceto com Monstros Sincro. \r\nVocê só pode usar cada um dos seguintes efeitos de "Zona Sincro" uma vez por turno. \r\nSe um ou mais Monstros Sincro não-Reguladores forem enviados para o seu Cemitério (exceto durante a Etapa de Dano): você pode escolher 1 desses monstros; Invoque-o por Invocação-Especial e, se isso acontecer, ele é considerado como um Regulador. \r\nDurante a Fase Principal do seu oponente: você pode enviar este card com a face para cima para o Cemitério; imediatamente depois que este efeito resolver, Invoque por Invocação-Sincro usando monstros que você controla como matéria.','\r',char(13)),'\n',char(10)),'Reviva um Monstro Sincro','Invocação Sincro','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60312997,'Onda de Reanimação',replace(replace('Só pode ser ativado quando um monstro do oponente declarar um ataque direto. \r\nSelecione 1 Monstro Sincro no seu Cemitério com um Nível menor ou igual ao do monstro atacante. \r\nO Dano de Batalha que você sofrer desse ataque é reduzido pela metade. \r\nNo final da Etapa de Dano, Invoque por Invocação-Especial o Monstro Sincro selecionado do Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60316373,'Besta Heráldica Aberconway',replace(replace('Se este card estiver no seu Cemitério: você pode banir 1 outro "Besta Heráldica Aberconway" do seu Cemitério e, depois, escolha 1 monstro "Besta Heráldica" no seu Cemitério; adicione o alvo à sua mão. \r\nVocê só pode usar este efeito de "Besta Heráldica Aberconway" uma vez por turno.','\r',char(13)),'\n',char(10)),'Recuperar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60329973,'Caos Fantasma','Escolha 1 dos seus Reguladores de LUZ banidos e 1 dos seus não-Reguladores de TREVAS banidos de Nível 8 ou menos; devolva os dois para o Cemitério e, depois, Invoque por Invocação-Especial 1 Monstro Sincro de LUZ ou de TREVAS do seu Deck Adicional cujo Nível seja igual à soma dos Níveis desses monstros devolvidos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60349525,'Dragão Crack',replace(replace('Não pode ser destruído em batalha com um monstro de Nível menor ou igual. \r\nQuando seu oponente Invocar exatamente 1 monstro por Invocação-Normal ou Especial (e nenhum outro monstro for Invocado) enquanto este monstro estiver no campo: você pode fazer com que esse monstro perca ATK igual ao seu próprio Nível x 200 (até o final deste turno) e, se isso acontecer, cause dano ao seu oponente igual ao ATK reduzido por este efeito.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60362066,'Lagrimentiara Batimento Cardíaco',replace(replace('Escolha 1 Magia/Armadilha no campo, ou você pode escolher 2 se você controlar "Visas Starfrost"; embaralhe-a(s) no Deck e, depois, envie 1 card da sua mão para o Cemitério. \r\nSe este card for enviado para o Cemitério por um efeito de card: você pode escolher 1 Armadilha "Lagrimentiara" no seu Cemitério; adicione-a à sua mão. \r\nVocê só pode usar 1 efeito de "Lagrimentiara Batimento Cardíaco" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60365591,'Arca de Shinato',replace(replace('Este card é usado para a Invocação-Ritual de "Shinato, Rei de um Plano Superior". \r\nTambém deve oferecer como Tributo monstros cuja soma dos Níveis seja igual ou maior que 8, do Campo ou da sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60369732,'Ritual Final dos Anciãos',replace(replace('Este card é usado para a Invocação-Ritual de "Reshef, o Ser das Trevas". \r\nTambém deve oferecer como Tributo monstros cuja soma dos Níveis seja igual ou maior que 8, do Campo ou da sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60375194,'Aurora Vendorror',replace(replace('Se seu oponente controlar mais cards que você: selecione 1 monstro "Vendorror" Invocado por Invocação-Ritual que você controla e destrua todos os cards no campo, exceto o monstro selecionado. \r\nEle não pode atacar diretamente enquanto permanecer com a face para cima no campo. \r\nVocê só pode ativar 1 "Aurora Vendorror" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60391791,'Olho Senri',replace(replace('Durante cada uma das suas Standby Phases, você pode ver 1 card do topo do Deck do seu adversário, e devolvê-lo à sua posição original, pagando 100 Life Points. \r\nO seu adversário não pode ver o card.','\r',char(13)),'\n',char(10)),'Revelar o Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60394026,'Plugin de Ryzeal',replace(replace('Escolha 1 dos seus Monstros Xyz ou monstros "Ryzeal" que estiverem banidos ou no seu Cemitério; Invoque-o por Invocação-Especial e, depois, você pode associar 1 card "Ryzeal" do seu Deck a 1 Monstro Xyz de Classe 4 que você controla e, além disso, você não pode declarar ataques pelo resto deste turno, exceto com Monstros Xyz de Classe 4. \r\nVocê só pode ativar 1 "Plugin de Ryzeal" por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Associar Matéria Xyz?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60398723,'Murmúrio da Floresta','Escolha 1 monstro com a face para cima que seu oponente controla; coloque o alvo com a face para baixo em Posição de Defesa e, depois, você pode devolver todos os Cards de Magia de Campo do campo para a mão.','Retornar a Magia de Campo para a mão?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60399954,'Ataque Unido','Escolha 1 monstro com a face para cima que você controla; some o total dos ATKs de todos os outros monstros com a face para cima em Posição de Ataque que você controla atualmente e, depois, apenas durante a Fase de Batalha deste turno, o monstro ganha esse valor de ATK, mas não pode causar dano de batalha ao seu oponente e, além disso, os outros monstros com a face para cima em Posição de Ataque não podem atacar.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60406591,'Sementes Sinistras','Quando um monstro que você controla for destruído em uma batalha na qual você sofreu dano e ele estava com a face para cima em Posição de Ataque no começo da Etapa de Dano e quando ele foi destruído: Invoque por Invocação-Especial 1 "Ficha de Semente Sinistra" (Tipo Planta/TREVAS/Nível 1/ATK 100/DEF 100) para cada 500 pontos de dano de batalha que você sofreu nesta batalha.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60406592,'Ficha de Semente Sinistra','Invocado por Especial com o efeito "Sementes Sinistras".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60410769,'Guerreiro de Juta','Uma vez por turno, você pode colocar 1 monstro com a face para cima em Posição de Ataque que seu oponente controla com a face para cima em Posição de Defesa.','Mudar para Posição de Defesa','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60411677,'Anúbis, o Último Juiz',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro deve ser Invocado por Invocação-Especial (da sua mão ou do Cemitério) enquanto você tiver 3 ou mais cards no seu Cemitério com nomes diferentes que sejam "Templo dos Reis" e/ou Armadilhas, ao colocar 2 deles no fundo do Deck em qualquer ordem. \r\nVocê pode enviar este card da sua mão para o Cemitério; adicione 1 "O Homem com a Marca" do seu Deck à sua mão. \r\nSe uma ou mais Magias/Armadilhas que você controla forem destruídas por um efeito de card: você pode escolher 1 card que seu oponente controla; destrua-o. \r\nVocê só pode usar cada efeito de "Anúbis, o Último Juiz" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60417395,'Esfera Neos da Escuridão',replace(replace('Este card não pode ser Invocado por Invocação-Normal ou Baixado. \r\nEste card não pode ser Invocado por Invocação-Especial, exceto ao enviar 1 monstro do Tipo Demônio que você controla e 1 monstro do Tipo Demônio da sua mão para o Cemitério quando um monstro do seu oponente declarar um ataque. \r\nEste card não pode ser destruído em batalha. \r\nUma vez por turno, você pode devolver todos os Cards de Armadilha com a face para cima que você controla à mão.','\r',char(13)),'\n',char(10)),'Invocação Especial','Retornar 1 Card de Armadilha para a mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60431417,'Dragões Gêmeos do Crepúsculo',replace(replace('Se você controlar "Dragão do Castigo": escolha 1 "Dragão do Julgamento" no seu Cemitério; adicione-o à sua mão e, depois, envie os 4 cards do topo do seu Deck para o Cemitério. \r\nSe este card for enviado do Deck para o Cemitério pelo efeito de um monstro "Luminoso(a)": você pode escolher 1 "Dragão do Castigo" no seu Cemitério; adicione-o à sua mão e, depois, bana os 4 cards do topo do seu Deck.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60433216,'Rei Escarlate',replace(replace('Se um monstro "Dragão Vermelho Arquidemônio" que você controla batalhar, durante o cálculo de dano: faça com que esse monstro que você controla não possa ser destruído por essa batalha e, se isso acontecer, Invoque este card por Invocação-Especial como um Monstro Normal (Tipo Demônio/Regulador/FOGO/Nível 1/ATK 0/DEF 0).	\r\n(Este card ainda é considerado um Card de Armadilha.)','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60434101,'Gallabas Mitológico','Você pode descartar 1 card para o Cemitério e, depois, escolha 1 monstro que seu oponente controla com DEF igual ou menor que o ATK deste card; destrua o alvo.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60434189,'Pêndulo Impenetrável','Neste turno, cards nas Zonas de Pêndulo não podem ser destruídos por efeitos de card do seu oponente e, além disso, negue qualquer efeito ativado pelo seu oponente que escolher como alvo um ou mais cards nas Zonas de Pêndulo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60439482,'Flecha de Regulus',replace(replace('Se você controlar "Regulus, o Príncipe de Endymion": ative 1 desses efeitos;\r\n● Destrua 1 monstro que seu oponente controla que batalhou neste turno.\r\n● Quando um Card de Magia Normal ou Rápida for ativado: negue o efeito.	\r\nDurante sua Fase Principal: você pode banir este card do seu Cemitério e, depois, escolha 1 "Regulus, o Príncipe de Endymion" ou 1 monstro que o mencione no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Flecha de Regulus" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar','Invocação Especial','Destruir','Negar o efeito','','','','','','','','','','','','');
INSERT INTO texts VALUES(60442460,'Ocorrência do Marcado','Uma vez por turno, quando seu oponente ativar um card ou efeito que escolha como alvo 1 monstro "Bistial" que você controla (e nenhum outro card), ou quando seu oponente ativar um card ou efeito em resposta à ativação de um efeito de monstro "Bistial" seu: você pode escolher 1 monstro de LUZ ou de TREVAS em qualquer Cemitério; bana-o e, se isso acontecer, negue esse efeito ativado.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60448701,'Origem Ogdoádica',replace(replace('Se um ou mais monstros Réptil com a face para cima que você controla forem destruídos em batalha ou por um efeito de card do oponente: você pode escolher 1 card que seu oponente controla; envie-o para o Cemitério. \r\nSe este card na Zona do Campo for destruído por um efeito de card do seu oponente: você pode enviar cards do topo do Deck do seu oponente para o Cemitério, igual ao número de monstros Réptil com nomes diferentes no seu Cemitério. \r\nVocê só pode usar cada efeito de "Origem Ogdoádica" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60461077,'Gouki Riscorpião',replace(replace('Se você não controlar nenhum monstro, ou se todos os monstros que você controlar forem monstros "Gouki", você pode Invocar este card por Invocação-Normal sem oferecer Tributo. \r\nSe este card for enviado do campo para o Cemitério: você pode adicionar 1 card "Gouki" do seu Deck à sua mão, exceto "Gouki Riscorpião". \r\nVocê só pode usar este efeito de "Gouki Riscorpião" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Normal sem Tributo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60461804,'HERÓI do Destino - Fênix Executora Destruidora',replace(replace('1 monstro "HERÓI" de Nível 6 ou mais + 1 monstro "HERÓI do Destino"	\r\nMonstros que seu oponente controla perdem 200 de ATK para cada card "HERÓI" no seu Cemitério. \r\nVocê só pode usar cada um dos seguintes efeitos de "HERÓI do Destino - Fênix Executora Destruidora" uma vez por turno. \r\n(Efeito Rápido): você pode destruir tanto 1 card que você controla quanto 1 card no campo. \r\nSe este card for destruído em batalha ou por um efeito de card: você pode ativar este efeito; Invoque por Invocação-Especial 1 monstro "HERÓI do Destino" do seu Cemitério durante a Fase de Apoio do próximo turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60465049,'Justiceiro Final Psíquico',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nEnquanto seus PV forem iguais ou menores que os do seu oponente, este card Invocado por Invocação-Sincro não é afetado pelos efeitos ativados do seu oponente. \r\nUma vez por turno: você pode pagar 1000 PV e, depois, escolha 1 monstro que você controla e 1 card que seu oponente controla; bana-os. \r\nNo começo da Fase de Batalha: você pode fazer com que este card ganhe ATK igual à diferença entre seus PV e os do seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60470713,'Bilhete Magidoce',replace(replace('Se um ou mais outros cards "Magidoce" que você controla ou no seu Cemitério forem adicionados à sua mão ou embaralhados no seu Deck Principal por um efeito de card: adicione 1 monstro "Magidoce" do seu Deck à sua mão. \r\nSe você controlar um monstro Fada "Magidoce", você pode Invocar esse monstro do seu Deck por Invocação-Especial em Posição de Ataque em vez de adicioná-lo à sua mão. \r\nVocê só pode usar o efeito de "Bilhete Magidoce" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Invocar por Invocação Especial em Posição de Ataque com a face para cima?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60473572,'Metalmorfose Açero',replace(replace('Escala de Pêndulo = 8\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno: você pode escolher 1 outro card com a face para cima que você controla; destrua-o e, se isso acontecer, Baixe 1 Magia/Armadilha "Metalmorfose" diretamente do seu Deck.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nCorpos de ferro frio se encontram com máquinas de metal ardente e homem/máquina se combinam. Queime a alma - Fusão Metalmorfose!!','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60482781,'Homem das Espadas Místicas LV6',replace(replace('Se você Invocar este monstro por Invocação-Normal, você tem de colocá-lo em Posição de Defesa com a face para baixo. \r\nSe este card atacar um monstro em Posição de Defesa com a face para baixo, destrúa o monstro com o efeito deste card, sem aplicar o cálculo de dano. \r\nVocê pode colocar o monstro destruído com este efeito no topo do Deck do seu adversário em vez de o enviar para o Cemitério.','\r',char(13)),'\n',char(10)),'Destruir','Devolver ao Deck do seu oponente?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60493189,'Plasma Vice, o HERÓI do Elemento',replace(replace('"Sparkman, o HERÓI do Elemento" + "Lâmina Afiada, o HERÓI do Elemento"	\r\nDeve ser Invocado por Invocação-Fusão. \r\nSe este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante. \r\nVocê pode descartar 1 card e, depois, escolha 1 monstro em Posição de Ataque que seu oponente controla; destrua o alvo.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60508057,'Ataqueraptor - Dragonius Napalm',replace(replace('Uma vez por turno: você pode causar 600 de dano ao seu oponente e, além disso, você não pode ativar efeitos de monstros pelo resto deste turno, exceto de monstros "Ataqueraptor". \r\nQuando este card for destruído em batalha e enviado para o Cemitério: você pode Invocar por Invocação-Especial 1 monstro "Ataqueraptor" do seu Deck, mas seus efeitos são negados.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60514625,'Ecole de Zone',replace(replace('Se o duelista do turno Invocar exatamente 1 monstro: destrua-o e, se isso acontecer, o controlador desse monstro Invoca por Invocação-Especial 1 "Ficha de Máscara" (Mago/TREVAS/Nível 1/ATK ?/DEF ?) no campo dele, que não pode atacar diretamente, com ATK/DEF iguais ao que o monstro destruído tinha no campo. \r\nVocê só pode usar este efeito de "Ecole de Zone" uma vez por turno. \r\nSe este card com a face para cima deixar o campo, destrua todas as "Ficha de Máscara" no campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60514626,'Ficha de Máscara','Invocado por Especial com o efeito "Ecole de Zone". Esta Ficha não pode atacar diretamente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60516416,'Destino Possuído - Wynn',replace(replace('1 monstro Mago + 1 monstro de VENTO	\r\n(Este card deve ser sempre considerado como um card "Espírito-Possuído".)	\r\nSe este card for Invocado por Invocação-Fusão: você pode colocar 1 monstro de VENTO do seu Cemitério no fundo do Deck e, depois, escolha 1 monstro que seu oponente controla; tome o controle desse monstro. \r\nDurante o turno do seu oponente (Efeito Rápido): você pode escolher 2 cards no campo, incluindo um monstro de VENTO que você controla; coloque-os no fundo do Deck em qualquer ordem. \r\nVocê só pode usar 1 efeito de "Destino Possuído - Wynn" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Tomar controle','Retornar ao Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60517697,'Poseidra do Abismo, o Senhor Dragão Atlante',replace(replace('3 monstros de Nível 7	\r\nUma vez por turno, você também pode Invocar "Poseidra do Abismo, o Senhor Dragão Atlante" por Invocação-Xyz ao usar 1 Monstro Xyz "Atlante" ou "Sirena" que você controla. \r\n(Transfira as matérias dele para este card.) \r\nUma vez por turno: você pode desassociar 2 matérias deste card e, depois, envie para o Cemitério 1 monstro de ÁGUA da sua mão ou do Deck; devolva até 3 cards que seu oponente controla para a mão. \r\nSe este card Invocado por Invocação-Xyz for enviado para o Cemitério: você pode descartar 1 card para o Cemitério; Invoque por Invocação-Especial 3 monstros Peixe, Serpente Marinha e/ou Aqua de Nível 3 ou menos da sua mão e/ou do Cemitério.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Xyz usando um Monstro Xyz como matéria?','Efeito de retornar à mão','Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60519422,'Espírito Kishido','Os Monstros no seu Campo não são destruídos como resultado de um combate com um monstro com o mesmo ATK.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60530944,'Batalha dos Elementos',replace(replace('Só pode ser ativado enquanto todos os monstros no campo estiverem com a face para cima. \r\nAmbos os duelistas enviam monstros que eles controlam para o Cemitério até que cada um deles controle apenas 1 Atributo.','\r',char(13)),'\n',char(10)),'Escolha o Atributo a manter','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60534585,'Instinto de Batalha',replace(replace('Só pode ser ativado quando seu oponente declarar um ataque direto e você não controlar nenhum monstro. \r\nInvoque por Invocação-Especial 1 monstro do Tipo Besta de Nível 4 ou menos da sua mão com a face para cima em Posição de Ataque.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60549248,'Homem-Bateria 9-Volts',replace(replace('Quando este card for Invocado: você pode adicionar 1 monstro "Homem-Bateria" do seu Deck à sua mão e, se isso acontecer, o ATK e DEF deste card se tornam o dobro do seu ATK e DEF originais. \r\nVocê só pode usar este efeito de "Homem-Bateria 9-Volts" uma vez por turno. \r\nDurante sua Fase Final: destrua este card.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60551528,'Infernoide Pirmais',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao banir 1 monstro "Infernoide" da sua mão ou do Cemitério enquanto a soma dos Níveis e Classes de todos os Monstros de Efeito que você controla for 8 ou menos. \r\nUma vez por turno: você pode escolher 1 card Baixado no campo; embaralhe-o no Deck. \r\nNenhum duelista pode ativar esse card em resposta à ativação deste efeito. \r\nUma vez por turno do oponente (Efeito Rápido): você pode oferecer 1 monstro como Tributo e, depois, escolha 1 card no Cemitério do seu oponente; bana-o.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60577362,'Olho Esmagador','Escolha 1 monstro Zumbi que você controla com 2000 ou menos de ATK; neste turno ele pode atacar diretamente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60589682,'Varas Gêmeas e Longas nº 1','Com braços como chicotes, esta criatura pode atacar inimigos à distância.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60600126,'Emergência Cibernética',replace(replace('Adicione 1 monstro Máquina de LUZ que não possa ser Invocado por Invocação-Normal/Baixado, ou 1 monstro "Dragão Cibernético", do seu Deck à sua mão. \r\nSe a ativação deste card em posse do seu dono foi negada por um efeito de card do seu oponente e enviado para o seu Cemitério: você pode descartar 1 card; adicione este card à sua mão. \r\nVocê só pode ativar 1 "Emergência Cibernética" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60600821,'Primavera',replace(replace('Uma vez por turno: você pode selecionar qualquer número das suas Zonas de Monstros Principais não utilizadas e, se isso acontecer, coloque esse número de Marcadores de Estações neste card e, além disso, essas zonas não podem ser usadas enquanto este card estiver no campo. \r\nMonstros que você controla ganham 400 de ATK para cada Marcador de Estações neste card. \r\nUma vez por turno, durante a Fase Final do seu oponente: você pode pegar 1 Magia de Campo do seu Deck sobre a qual você possa colocar um Marcador de Estações, e colocá-la no seu campo com a face para cima (mas nenhum duelista pode ativar seus efeitos neste turno) e, se isso acontecer, coloque nesse card todos os Marcadores de Estações deste card.','\r',char(13)),'\n',char(10)),'Colocar um marcador','Coloque uma Magia de Campo','Escolha uma Zona de Monstros Principal','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60606759,'Renge, Porteiro do Mundo Negro','Seu renomado físico atlético o tornou famoso com a população do Mundo Negro. Eles o chamam de "Renge Parede de Ferro" porque ninguém pode romper suas incríveis defesas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60619435,'Jogo de Bola Gigante',replace(replace('Durante sua Fase Principal, se este card foi ativado neste turno: você pode Invocar por Invocação-Especial 1 monstro Inseto de Nível 6 ou menos do seu Cemitério. \r\nVocê pode revelar 1 monstro Inseto na sua mão e, depois, escolha 1 monstro com a face para cima que seu oponente controla e 1 monstro Inseto que você controla com ATK menor que o do monstro revelado; troque o controle desses monstros e, se isso acontecer, o monstro do qual você tomou o controle se torna um monstro Inseto. \r\nVocê só pode usar 1 efeito de "Jogo de Bola Gigante" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial do Cemitério','Trocar o controle','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60621361,'Reviver Monstrosso',replace(replace('Se seu oponente Invocar um monstro por Invocação-Especial neste turno: ative este card ao escolher 1 monstro no Cemitério do seu oponente; Invoque-o por Invocação-Especial no seu lado do campo em Posição de Defesa. \r\nQuando este card deixar o campo, bana esse monstro. \r\nQuando esse monstro deixar o campo, destrua este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60623203,'Alinhar Xyz',replace(replace('Declare um Nível de 1 a 12 e, depois, escolha 2 monstros com a face para cima com um Nível no campo, incluindo 1 monstro que você controla; eles se tornam do Nível declarado (até o final deste turno) e, além disso, pelo resto deste turno depois que este card resolver, você não pode Invocar monstros por Invocação-Especial do Deck Adicional, exceto monstros com o mesmo Tipo que o do monstro alvo. \r\nVocê só pode ativar 1 "Alinhar Xyz" por turno.','\r',char(13)),'\n',char(10)),'Escolha o monstro cujo Nível será alterado','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60627999,'Pântano Sanguíneo',replace(replace('Se você controlar quaisquer outros Cards de Magia ou Armadilha, destrua este card. \r\nCards de Magia e Armadilha com a face para baixo não podem ser ativados. \r\nDestrua este card durante sua 2ª Fase de Apoio, depois da ativação.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60634565,'Hidra Reptiliana',replace(replace('1 Regulador "Reptiliano(a)" + 1+ monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro: destrua tantos monstros que seu oponente controla com 0 de ATK quanto possível e, se isso acontecer, compre 1 card para cada monstro destruído.','\r',char(13)),'\n',char(10)),'Destruir e comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60643553,'Irmã Fantasma & Cornales Assustador',replace(replace('Durante qualquer turno, exceto na Fase Final (Efeito Rápido): você pode descartar este card; aplique este efeito neste turno. \r\nVocê só pode usar este efeito de "Irmã Fantasma & Cornales Assustador" uma vez por turno.\r\n● Sempre que seu oponente Invocar um ou mais Monstros de Efeito por Invocação-Especial durante a Fase Principal ou Fase de Batalha, você ganha PV igual ao ATK desse monstro.	\r\nSe você não ganhou PV por este efeito, seus PV são diminuídos pela metade durante a Fase Final.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60643554,'Irmã Fantasma & Cornales Assustador',replace(replace('Durante qualquer turno, exceto na Fase Final (Efeito Rápido): você pode descartar este card; aplique este efeito neste turno. \r\nVocê só pode usar este efeito de "Irmã Fantasma & Cornales Assustador" uma vez por turno.\r\n● Sempre que seu oponente Invocar um ou mais Monstros de Efeito por Invocação-Especial durante a Fase Principal ou Fase de Batalha, você ganha PV igual ao ATK desse monstro.	\r\nSe você não ganhou PV por este efeito, seus PV são diminuídos pela metade durante a Fase Final.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60645181,'Campeão Heroico - Excalibur',replace(replace('2 monstros Guerreiro de Nível 4	\r\nUma vez por turno: você pode desassociar 2 matérias deste card; o ATK deste card se torna o dobro do seu ATK original até o final do turno do seu oponente.','\r',char(13)),'\n',char(10)),'Alterar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60666820,'Arquidemônio Nefário, o Comedor da Perversidade',replace(replace('Você só pode controlar 1 "Arquidemônio Nefário, o Comedor da Perversidade". \r\nSe você controlar um monstro Mago, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nUma vez por turno, durante a Fase Final do seu oponente, se este card estiver no seu Cemitério: você pode escolher 1 monstro com a face para cima que você controla; destrua-o e, se isso acontecer, Invoque este card por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60668166,'Cerejas de Naturia','Se este card for enviado do seu campo para o seu Cemitério por um card do oponente: você pode Invocar por Invocação-Especial até 2 "Cerejas de Naturia" do seu Deck com a face para baixo em Posição de Defesa.','Invocação Especial','Invocar outro monstro por Invocação Especial?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60675348,'Uivo Dinonévoa',replace(replace('Quando este card for ativado: você pode colocar 1 ou 2 Monstros Pêndulo "Dinonévoa" do seu Deck na(s) sua(s) \r\nZona(s) de Pêndulo, mas você não pode Invocar monstros por Invocação-Pêndulo até o final do próximo turno, exceto monstros "Dinonévoa" (mesmo que este card deixe o campo). \r\nUma vez por turno, se este card já estiver com a face para cima na sua Zona de Magias & Armadilhas: você pode oferecer como Tributo 1 monstro "Dinonévoa" e, depois, escolher 1 card que seu oponente controla; devolva-o para a mão.','\r',char(13)),'\n',char(10)),'Colocar o Monstro Pêndulo "Dinonévoa"?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60681103,'Felgrand, o Divino Senhor Dragão',replace(replace('Se este card for Invocado por Invocação-Especial do Cemitério: você pode escolher 1 monstro que seu oponente controla ou no Cemitério dele; bana-o e, se isso acontecer, este card ganha ATK e DEF igual ao Nível/Classe original do monstro banido x 100. \r\nSe este card destruir um monstro do oponente em batalha: você pode escolher 1 monstro do Tipo Dragão de Nível 7 ou 8 no Cemitério, exceto "Felgrand, o Divino Senhor Dragão"; Invoque-o por Invocação-Especial no seu campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60681372,'Nurikabe',replace(replace('Se este card estiver no seu Cemitério, exceto no turno em que foi enviado para lá: você pode pagar 1000 PV e, depois, escolha 1 outro monstro Zumbi no seu Cemitério; Invoque por Invocação-Especial tanto ele como este card, mas seus efeitos são negados e, além disso, bana-os quando eles deixarem o campo. \r\nVocê só pode usar este efeito de "Nurikabe" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60682203,'Onda Fria',replace(replace('Este card só pode ser ativado no começo da Fase Principal 1. \r\nAté seu próximo turno, você e seu oponente não podem usar ou Baixar quaisquer Cards de Magia ou Armadilha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60694662,'Skelengel','VIRE: Compre 1 card.','Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60700283,'Cavaleirostrela Cygnian',replace(replace('(Este card deve ser sempre considerado como um card "Constelar".)	\r\nSe este card for Invocado: você pode adicionar 1 monstro "Cavaleirost" ou "Constelar" do seu Deck à sua mão. \r\nVocê pode escolher 1 outro monstro de LUZ que você controla; aumente em 1 tanto o Nível dele como o deste card. \r\nEste card pode ser considerado como 2 matérias para a Invocação-Xyz de um Monstro Xyz "Cavaleirost" que requer 3 ou mais matérias. \r\nVocê só pode usar cada efeito de "Cavaleirostrela Cygnian" uma vez por turno.','\r',char(13)),'\n',char(10)),'Efeito de busca','Alterar o Nível','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60709218,'Elo Entre Professor e Estudante',replace(replace('Se você controlar "Mago Negro": Invoque por Invocação-Especial 1 "Pequena Maga Negra" da sua mão, do Deck ou do Cemitério e, depois, você pode Baixar 1 "Ataque da Magia Negra", "Ataque Ardente das Trevas", "Magia Ardente das Trevas" ou "Explosão Gêmea da Magia Negra" do seu Deck. \r\nVocê só pode ativar 1 "Elo Entre Professor e Estudante" por turno.','\r',char(13)),'\n',char(10)),'Baixar um card?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60715406,'Planta Tentaculada','Este monstro se estende com gavinhas azuis compridas e agarra o que quer que se aproxime.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60718396,'Contra-ataque Flamvell','Quando um Card de Magia/Armadilha for ativado: bana 1 monstro de FOGO com DEF 200 do seu Cemitério; negue a ativação e, se isso acontecer, destrua-o.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60728397,'Disparo de Peçonha',replace(replace('Ative apenas enquanto você controlar um monstro "Peçonha" com a face para cima, "Vennominaga, a Divindade das Serpentes Venenosas" ou "Vennominon, o Rei das Serpentes Venenosas". \r\nEnvie 1 monstro do Tipo Réptil do seu Deck para o Cemitério e coloque 2 Marcadores de Veneno em 1 monstro com a face para cima que seu oponente controla.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60741115,'Devorador de Dano','Durante o turno do seu oponente, quando seu oponente ativar um card ou efeito que causaria dano, em vez disso, você pode remover de jogo este card no seu Cemitério para mudar esse efeito para que ele aumente os PV na mesma quantidade.','Recuperar PV','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60743819,'Pirraça do Demônio','Escolha 1 monstro no Cemitério do seu oponente; embaralhe-o no Deck e, depois, você pode enviar 1 monstro Demônio do seu Deck para o Cemitério.','Enviar 1 monstro Demônio para o Cemitério?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60759087,'Presente da Evil★Gêmea',replace(replace('Se você controlar um monstro "Ki-sikil" e controlar um monstro "Lil-la": ative 1 desses efeitos;\r\n● Escolha 1 monstro "Ki-sikil" ou 1 monstro "Lil-la" que você controla e 1 monstro com a face para cima que seu oponente controla; troque o controle desses monstros.\r\n● Escolha 1 Magia/Armadilha Baixada que seu oponente controla; embaralhe-a no Deck.	\r\nVocê só pode ativar 1 "Presente da Evil★Gêmea" por turno.','\r',char(13)),'\n',char(10)),'Trocar o controle','Retornar ao Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60764581,'Cordeiros Perdidos',replace(replace('Invoque por Invocação-Especial 2 "Fichas de Cordeiro" (Besta/TERRA/Nível 1/ATK 0/DEF 0) em Posição de Defesa. \r\nVocê não pode Invocar outros monstros no turno em que ativar este card (mas pode Baixá-los).','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60764582,'Ficha de Cordeiro','Invocado por Especial com o efeito "Cordeiros Perdidos".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60764583,'Ficha de Cordeiro','Invocado por Especial com o efeito "Cordeiros Perdidos".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60764609,'Gravador Criademônio',replace(replace('Você pode descartar este card; adicione 1 Magia/Armadilha "Criademônio" do seu Deck à sua mão. \r\nVocê pode escolher 1 Card de Equipamento "Criademônio" que você controla e 1 monstro no campo; envie-os para o Cemitério. \r\nSe este card estiver no seu Cemitério: você pode embaralhar 1 outro monstro Demônio de LUZ do seu Cemitério no Deck/Deck Adicional; Invoque este card por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Gravador Criademônio" uma vez por turno.','\r',char(13)),'\n',char(10)),'Efeito de busca','Enviar para o Cemitério','Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60800381,'Guerreiro Sucata',replace(replace('"Sucata Sincron" + 1+ monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro: ele ganha ATK igual ao ATK total de todos os monstros de Nível 2 ou menos que você controla atualmente.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60800382,'Guerreiro Sucata',replace(replace('"Sucata Sincron" + 1+ monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro: ele ganha ATK igual ao ATK total de todos os monstros de Nível 2 ou menos que você controla atualmente.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60800383,'Guerreiro Sucata',replace(replace('"Sucata Sincron" + 1+ monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro: ele ganha ATK igual ao ATK total de todos os monstros de Nível 2 ou menos que você controla atualmente.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60800384,'Guerreiro Sucata',replace(replace('"Sucata Sincron" + 1+ monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro: ele ganha ATK igual ao ATK total de todos os monstros de Nível 2 ou menos que você controla atualmente.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60802233,'Kuwagata α','Um besouro muito feroz que ataca a cabeça.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60806437,'Tartaruga Disco Voador','Quando este card for destruído em batalha e enviado para o Cemitério: você pode Invocar por Invocação-Especial 1 monstro de FOGO com 1500 ou menos de ATK do seu Deck, em Posição de Ataque.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60822251,'Kaiki, a Estrela da União',replace(replace('Se este card for Invocado por Invocação-Especial (exceto durante a Etapa de Dano): você pode pagar 500 PV; Invoque por Invocação-Fusão 1 Monstro de Fusão Guerreiro do seu Deck Adicional, usando monstros da sua mão ou do campo como Matéria de Fusão. \r\nDurante o turno do seu oponente, se este card estiver no seu Cemitério e você controlar um monstro Guerreiro de Nível 5 ou mais cujo ATK atual seja diferente do seu ATK original (Efeito Rápido): você pode Invocar este card por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Kaiki, a Estrela da União" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60823690,'Shinobarão Pavão das Sombras',replace(replace('Você pode Invocar este card por Invocação-Ritual com "Chamado do Shinobird". \r\nO nome deste card se torna "Shinobarão Pavão" enquanto estiver na mão ou no campo. \r\nVocê pode oferecer como Tributo este card Invocado por Invocação-Ritual; adicione 1 monstro Espírito e 1 Magia de Ritual do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Shinobarão Pavão das Sombras" uma vez por turno. \r\nUma vez por turno, durante a Fase de Apoio do próximo turno depois que este card foi banido: Invoque este card banido por Invocação-Especial. \r\nUma vez por turno, durante a Fase Final, se este card foi Invocado por Invocação-Especial neste turno: devolva este card para a mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60830240,'Reignição do Vácuo',replace(replace('Revele 1 monstro "Infernoide" ou 1 Magia/Armadilha "Vácuo" na sua mão; descarte toda a sua mão e, depois, compre o mesmo número de cards que você descartou. \r\nSe você não controlar nenhum monstro, ou todos os monstros que você controlar forem monstros Demônio, exceto no turno em que este card foi enviado para o Cemitério: você pode banir este card do seu Cemitério e, depois, escolha até 11 dos seus monstros "Infernoide" banidos com nomes diferentes; devolva-os para o Cemitério. \r\nVocê só pode usar este efeito de "Reignição do Vácuo" uma vez por Duelo.','\r',char(13)),'\n',char(10)),'Descartar e comprar','Retornar para o Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60832978,'Ressonador Duplo',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 monstro com a face para cima no campo; o alvo é considerado como um Regulador neste turno. \r\nVocê pode banir este card do seu Cemitério e, depois, escolher 1 monstro Demônio que você controla; esse monstro Demônio é considerado como um Regulador neste turno. \r\nVocê só pode usar este efeito de "Ressonador Duplo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60862676,'Cerebrus de Chamas','Conhecido por muitos como "Carrasco em Chamas", este monstro é capaz de transformar seus inimigos em cinzas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60866277,'Agitador de Terra',replace(replace('Selecione 2 Atributos de Cards de Monstro. \r\nSeu oponente então seleciona 1 dos 2 Atributos e destrói todos os monstros com a face para cima no campo com esse Atributo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60876124,'Valor Raro','Se você controlar 2 ou mais cards "Fera Cristalina" na sua Zona de Magias & Armadilhas: seu oponente seleciona 1 card "Fera Cristalina" na sua Zona de Magias & Armadilhas, envie-o para o Cemitério e, se isso acontecer, compre 2 cards.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60879050,'Acoplar Vagão',replace(replace('Você deve equipar este card a um monstro Máquina de TERRA, ao banir 2 monstros Máquina de Nível 10 ou mais do seu Cemitério. \r\nO ATK do monstro equipado se torna o dobro do seu ATK original e, além disso, se ele atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente. \r\nOutros monstros que você controla não podem atacar.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60880471,'Heléboro, a Fada Rikka',replace(replace('Quando seu oponente ativar um efeito de monstro que escolha como alvo um ou mais monstros que você controla, enquanto você controlar um monstro "Rikka" (Efeito Rápido): você pode oferecer este card como Tributo da sua mão ou do campo com a face para cima; negue o efeito. \r\nSe este card estiver no seu Cemitério: você pode oferecer 1 monstro Planta como Tributo; Invoque este card por Invocação-Especial em Posição de Defesa, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar cada efeito de "Heléboro, a Fada Rikka" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60883493,'Redemoinho de Neve da Alma Aniquiladora',replace(replace('Revele monstros na sua mão até 1 de cada de TREVAS, de TERRA e de FOGO; aplique o(s) seguinte(s) efeito(s) em sequência, de acordo com o número revelado.\r\n● 1+: Cause 400 de dano ao seu oponente e, depois, você pode Invocar por Invocação-Especial 1 monstro "Alma Aniquiladora" da sua mão.\r\n● 2+: Cause 600 de dano ao seu oponente e, além disso, neste turno, monstros "Alma Aniquiladora" que você controla não podem ser destruídos por efeitos de card.\r\n● 3: Cause 800 de dano ao seu oponente e, depois, você pode destruir todos os monstros no campo.	\r\nVocê só pode ativar 1 "Redemoinho de Neve da Alma Aniquiladora" por turno.','\r',char(13)),'\n',char(10)),'','Invocar por Invocação Especial da sua mão?','Destruir todos os monstros no campo?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60884672,'Grande Mar de Areia - Gold Golgonda',replace(replace('Todos os Monstros Xyz "Springans" no campo ganham 1000 de ATK. \r\nVocê só pode usar cada um dos seguintes efeitos de "Grande Mar de Areia - Gold Golgonda" uma vez por turno. \r\nSe você não controlar nenhum Monstro Xyz "Springans": você pode descartar 1 card "Springans"; Invoque por Invocação-Especial 1 Monstro Xyz "Springans" do seu Deck Adicional. \r\nSe um Monstro Xyz com a face para cima que você controla deixar o campo devido a um efeito de card (exceto durante a Etapa de Dano): você pode escolher 1 monstro que seu oponente controla; ele não pode atacar pelo resto deste turno (mesmo que este card deixe o campo).','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60912752,'Fronteira de D. D.','Enquanto não houver Magias no seu Cemitério, nenhum duelista pode conduzir sua Fase de Batalha.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60921537,'Dogmatikamacabro',replace(replace('Este card pode ser usado para Invocar por Invocação-Ritual qualquer Monstro de Ritual "Dogmatika" da sua mão ou do Cemitério. \r\nVocê também deve oferecer como Tributo monstros da sua mão ou do campo, e/ou banir Monstros de Fusão ou Sincro do seu Cemitério, cuja soma dos Níveis seja igual ou exceda o Nível do Monstro de Ritual que você estiver Invocando por Invocação-Ritual e, depois, se tanto "Cavaleiro Branco de Dogmatika" quanto "Relíquia Branca de Dogmatika" estiverem no campo, você pode olhar seu Deck Adicional ou o do seu oponente e enviar 1 monstro dali para o Cemitério. \r\nVocê só pode ativar 1 "Dogmatikamacabro" por turno.','\r',char(13)),'\n',char(10)),'Revelar o Deck Adicional e enviar um monstro para o Cemitério?','Ver o seu Deck Adicional','Ver o Deck Adicional do oponente','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60930169,'Bloqueador Quebrado',replace(replace('Ative apenas quando um monstro em Posição de Defesa que você controla, cuja DEF seja maior que o seu ATK, for destruído em batalha. \r\nInvoque por Invocação-Especial até 2 monstros com o mesmo nome desse monstro do seu Deck com a face para cima em Posição de Defesa.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60942444,'Espírito Tenyi - Mapura',replace(replace('Se você não controlar nenhum Monstro de Efeito: você pode Invocar este card por Invocação-Especial da sua mão. \r\nQuando seu oponente ativar um card ou efeito que escolha como alvo um ou mais Monstros que não sejam de Efeito com a face para cima que você controla (Efeito Rápido): você pode banir este card da sua mão ou do Cemitério; negue a ativação e, se isso acontecer, destrua esse card. \r\nVocê só pode usar cada efeito de "Espírito Tenyi - Mapura" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Negar a ativação e destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60944809,'Números Gloriosos',replace(replace('Se você não controlar nenhum monstro: escolha 1 Monstro Xyz "Número" no seu Cemitério; Invoque-o por Invocação-Especial e, depois, compre 1 card. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 Monstro Xyz "Número" que você controla; associe 1 card da sua mão a ele como matéria. \r\nVocê só pode usar cada efeito de "Números Gloriosos" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60946049,'Graflare de Artmage',replace(replace('Na primeira vez que este card seria destruído em batalha a cada turno, ele não é destruído. \r\nVocê só pode usar cada um dos seguintes efeitos de "Graflare de Artmage" uma vez por turno. \r\nSe você controlar um card "Artmage": você pode Invocar este card por Invocação-Especial da sua mão e, depois, você pode Baixar 1 Magia "Artmage" do seu Deck. \r\nVocê pode escolher 1 Magia/Armadilha que seu oponente controla; destrua-a. \r\nEste é um Efeito Rápido se você tiver 3 ou mais Tipos de Monstro diferentes no seu campo.','\r',char(13)),'\n',char(10)),'Invocação Especial','Destruir','Baixar?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60946968,'Outro Mundo - A Zona "A"','Se um monstro do seu oponente batalhar com um monstro "Alienígena" que você controla, o monstro do oponente perde 300 de ATK e DEF apenas durante o cálculo de dano','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60948488,'Mago das Crônicas',replace(replace('Se um ou mais monstros com 2500 de ATK ou DEF original forem Invocados por Invocação-Normal ou Especial no seu campo (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão em Posição de Defesa. \r\nSe este card for Invocado por Invocação-Especial: você pode escolher 1 "Mago Negro" ou "Dragão Branco de Olhos Azuis" na sua Zona de Monstros; ele ganha 2500 de ATK/DEF até o final deste turno. \r\nVocê só pode usar cada efeito de "Mago das Crônicas" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar este card por Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60950180,'Ataqueraptor - Lanius Cortante',replace(replace('Uma vez por turno, durante sua Fase Principal, se este card foi Invocado por Invocação-Normal ou Especial neste turno: você pode escolher 1 monstro em Posição de Ataque com a face para cima no campo; coloque-o com a face para cima em Posição de Defesa. \r\nDurante sua Fase Principal 2, se este card atacou neste turno: você pode escolher 1 monstro "Ataqueraptor" no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê só pode usar este efeito de "Ataqueraptor - Lanius Cortante" uma vez por turno.','\r',char(13)),'\n',char(10)),'Alterar a posição de batalha','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60953118,'Força Arcana XIV - A Temperança',replace(replace('Durante o cálculo de dano (Efeito Rápido): você pode descartar este card; você não sofre dano de batalha dessa batalha. \r\nQuando este card for Invocado: lance uma moeda.\r\n● Cara: Diminua pela metade todo o dano de batalha que você sofrer.\r\n● Coroa: Diminua pela metade todo o dano de batalha que seu oponente sofrer.','\r',char(13)),'\n',char(10)),'Jogar uma moeda','O dano de batalha se torna 0','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60953949,'Caixa de Mecanismo Antigo',replace(replace('Se este card for adicionado à sua mão do Deck ou Cemitério, exceto ao comprá-lo: você pode adicionar 1 monstro de TERRA do Tipo Máquina com 500 de ATK e/ou DEF do seu Deck à sua mão, exceto "Caixa de Mecanismo Antigo". \r\nVocê só pode usar este efeito de "Caixa de Mecanismo Antigo" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60954556,'Lirilusc - Andorinha de Safira',replace(replace('Se você controlar um monstro Besta Alada: você pode Invocar por Invocação-Especial tanto este card quanto 1 monstro Besta Alada de Nível 1 da sua mão. \r\nVocê só pode usar este efeito de "Lirilusc - Andorinha de Safira" uma vez por turno. \r\nUm Monstro Xyz de VENTO que foi Invocado usando este card no campo como matéria ganha este efeito.\r\n● Se for Invocado por Invocação-Xyz: você pode escolher 1 monstro "Lirilusc" no seu Cemitério; associe-o a este card como matéria.','\r',char(13)),'\n',char(10)),'Invocação Especial','Associar Matéria Xyz (Lirilusc - Andorinha de Safira)','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60967717,'Expansão Miutante',replace(replace('Quando você ativar este card: você pode pegar 1 monstro "Miutante" de Nível 4 ou menos do seu Deck e adicioná-lo à sua mão ou Invocá-lo por Invocação-Especial. \r\nSe um ou mais monstros "Miutante" de Nível 8 ou mais que você controla seriam destruídos por um efeito de card, em vez disso, você pode banir este card que você controla. \r\nVocê só pode ativar 1 "Expansão Miutante" por turno.','\r',char(13)),'\n',char(10)),'Adicionar à sua mão um monstro do seu Deck ou Invocá-lo por Invocação Especial?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60990740,'Rei Absoluto de Mochila a Jato',replace(replace('Durante o turno do seu oponente (Efeito Rápido): você pode banir este card do Cemitério; escave o card do topo do seu Deck e, se for uma Armadilha Normal, Baixe-a no seu campo. \r\nCaso contrário, envie-a para o Cemitério. \r\nEsse card Baixado pode ser ativado durante este turno. \r\nSe este card for enviado para o Cemitério: você pode olhar os 3 cards do topo do seu Deck e, depois, coloque-os no topo do Deck em qualquer ordem. \r\nVocê só pode usar cada efeito de "Rei Absoluto de Mochila a Jato" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar aplicando o efeito de "Rei Absoluto de Mochila a Jato".','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60992105,'Dragão Penanegra Fúria-obscura',replace(replace('1 Regulador + 1 ou mais monstros não-Reguladores	\r\nUma vez por turno, quando você sofrer dano: você pode enviar até 5 cards do topo do seu Deck para o Cemitério e, depois, se algum monstro foi enviado para o Cemitério por este efeito, este card ganha 400 de ATK.','\r',char(13)),'\n',char(10)),'Enviar do Deck para o Cemitério','Escolha a quantidade de cards para enviar ao Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60992364,'ZW - Leão de Armas',replace(replace('2 monstros de Nível 5	\r\nNão pode atacar diretamente. \r\nUma vez por turno: você pode desassociar 1 matéria deste card; adicione 1 monstro "ZW -" do seu Deck à sua mão. \r\nVocê pode escolher 1 monstro "Utopia" que você controla; equipe este monstro no campo ao alvo. \r\nEle ganha 3000 de ATK. \r\nDurante sua Fase de Batalha, se o monstro equipado atacou neste turno: você pode enviar este Card de Equipamento para o Cemitério; o monstro equipado pode realizar um segundo ataque contra um monstro do oponente durante esta Fase de Batalha.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Considerar como Card de Equipamento','Ataques múltiplos','','','','','','','','','','','','','');
INSERT INTO texts VALUES(60999392,'Soldado Autômato','Quando este card for Invocado por Invocação-Normal enquanto você não controlar nenhum outro monstro: você pode Invocar por Invocação-Especial 1 monstro "Autômata(o)" da sua mão, exceto "Soldado Autômato".','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61011311,'Defeito Zenmai',replace(replace('Escolha 1 monstro "de Corda" no seu Cemitério; Invoque-o por Invocação-Especial com a face para cima em Posição de Defesa. \r\nSeus efeitos são negados, e ele não pode ser oferecido como Tributo ou usado como um Monstro-Matéria Sincro.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61011438,'Rosa Brilhante',replace(replace('(Este card deve ser sempre considerado como um card "Cavaleiro-Gema".)	\r\nVocê pode descartar 1 card "Cavaleiro-Gema" ou "Melodiosa(o)"; Invoque este card por Invocação-Especial da sua mão. \r\nVocê só pode usar este efeito de "Rosa Brilhante" uma vez por turno. \r\nUma vez por turno: você pode enviar 1 monstro "Cavaleiro-Gema" ou "Melodiosa(o)" do seu Deck Adicional para o Cemitério; até a Fase Final, o nome/Tipo/Atributo deste card se tornam o mesmo que o nome/Tipo/Atributo originais do monstro enviado para o Cemitério para ativar este efeito.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61019812,'Poerio Vermelho',replace(replace('Não pode ser usado como Matéria Fusão, Sincro ou Xyz para uma Invocação. \r\nEnquanto este card estiver no campo com a face para cima, ele não pode ser oferecido como Tributo. \r\nQuando este card no campo for destruído: o controlador sofre 500 de dano. \r\nVocê só pode controlar 1 "Poerio Vermelho" com a face para cima.','\r',char(13)),'\n',char(10)),'Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61027400,'Ikura do Naviushi Gunkan',replace(replace('Se você controlar "Shari do Naviushi Gunkan", você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Ikura do Naviushi Gunkan" por Invocação-Especial uma vez por turno desta forma. \r\nDurante sua Fase Principal: você pode escavar os 3 cards do topo do seu Deck e, se isso acontecer, você pode adicionar à sua mão ou Invocar por Invocação-Especial 1 "Shari do Naviushi Gunkan" escavado e, além disso, embaralhe o resto no seu Deck. \r\nVocê só pode usar este efeito de "Ikura do Naviushi Gunkan" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Adicionar 1 card à sua mão ou Invocá-lo por Invocação Especial?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61032879,'Reino Sinc','Sempre que você Invocar um Monstro Sincro por Invocação-Sincro: cause 500 de dano ao seu oponente.','Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61044390,'Fim do Caos',replace(replace('Você só pode ativar este card se 7 ou mais dos seus cards estiverem atualmente removidos do Duelo. \r\nDestrua todos os Cards de Monstro no campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61049315,'Roseira de Naturia','Seu oponente só pode ativar 1 Card de Magia/Armadilha a cada turno.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61052897,'Turing Genex-R',replace(replace('Durante a Fase Principal do seu oponente, se você controlar um monstro "Genex" (Efeito Rápido): você pode Invocar este card por Invocação-Especial da sua mão e, depois, imediatamente depois que este efeito resolver, você pode Invocar por Invocação-Sincro 1 Monstro Sincro "Genex". \r\nVocê só pode usar este efeito de "Turing Genex-R" uma vez por turno. \r\nEste card no campo pode ser considerado como um monstro de Nível 1 ou 3 quando usado para uma Invocação-Sincro de um Monstro Sincro "Genex".','\r',char(13)),'\n',char(10)),'Invocação Especial','Invocação Sincro?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61068510,'Furacão',replace(replace('Ative apenas quando houver 3 ou mais cards na Zona de Cards de Magia & Armadilha do seu oponente. \r\nDestrua 1 card na Zona de Cards de Magia & Armadilha do seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61070601,'Armamento de Fusão',replace(replace('Revele 1 Monstro de Fusão no seu Deck Adicional, e Invoque por Invocação-Especial 1 das Matérias de Fusão cujo nome seja mencionado nesse monstro do seu Deck Adicional ou Cemitério, mas até o final do turno do seu oponente, ele não pode atacar e seus efeitos (se houver) são negados. \r\nVocê só pode ativar 1 "Armamento de Fusão" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61082944,'Poção de Recuperação de Poder Espiritual',replace(replace('(Este card deve ser sempre considerado como um card "Possuído(a)".)	\r\nBana qualquer número de monstros Mago e/ou Magias do seu Cemitério; monstros que você controla ganham 200 de ATK x o número banido e, se isso acontecer, você ganha 400 PV x o número banido. \r\nDurante sua Fase Principal: você pode banir este card do seu Cemitério; Invoque por Invocação-Especial qualquer número de monstros Mago com Atributos diferentes da sua mão. \r\nVocê só pode usar 1 efeito de "Poção de Recuperação de Poder Espiritual" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61089209,'Névoa Miutante',replace(replace('Não pode ser Invocado por Invocação-Especial, exceto com o efeito de um card "Miutante". \r\nSeu oponente não pode escolher este card como alvo de efeitos de Magia. \r\nVocê só pode usar cada um dos seguintes efeitos de "Névoa Miutante" uma vez por turno. \r\nQuando seu oponente ativar um Card de Armadilha ou seus efeitos (Efeito Rápido): você pode banir 1 card da sua mão ou do campo; compre 2 cards. \r\nSe este card em posse do seu dono for destruído por um card do oponente: você pode escolher 1 dos seus monstros "Miutante" banidos; adicione-o à sua mão.','\r',char(13)),'\n',char(10)),'Comprar','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61103515,'Wyvern Fantasma, o Dragão do Submundo',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 "Fusão Fantasma" do seu Deck à sua mão. \r\nDurante a Fase Final, se este card atualmente estiver banido e foi banido neste turno: você pode pegar 1 Regulador Zumbi de Nível 2 ou menos do seu Deck e adicioná-lo à sua mão ou enviá-lo para o Cemitério. \r\nVocê só pode usar cada efeito de "Wyvern Fantasma, o Dragão do Submundo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61116514,'Palma de Ryzeal',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro deve ser Invocado por Invocação-Especial (da sua mão) ao embaralhar 1 monstro "Ryzeal" da sua mão ou do Cemitério no Deck/Deck Adicional. \r\nVocê não pode Invocar por Invocação-Especial do Deck Adicional, exceto Monstros Xyz de Classe 4. \r\nUma vez por turno, durante o cálculo de dano, se este card batalhar um monstro do oponente: você pode enviar 1 monstro de Nível 4 da sua mão ou do Deck para o Cemitério e, se isso acontecer, este card ganha ATK igual ao ATK desse monstro, até o final da Fase de Batalha.','\r',char(13)),'\n',char(10)),'Invocação Especial','Aumentar ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61127349,'Explosão do Big Bang',replace(replace('O monstro equipado ganha 400 de ATK. \r\nSe o monstro equipado atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente. \r\nQuando este card deixar o campo, bana o monstro equipado.','\r',char(13)),'\n',char(10)),'Banir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61132951,'Desafiante Heroico - Vigia Noturno','Se este card atacar um monstro em Posição de Defesa que seu oponente controla, antes do cálculo de dano: você pode destruir esse monstro.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61151074,'Força Celeste - Mecha - Sabre Adil',replace(replace('Durante a Fase de Batalha (Efeito Rápido): você pode descartar este card e, depois, escolha 1 monstro "Força Celeste" no campo; ele ganha 1500 de ATK até o final deste turno. \r\nSe um ou mais monstros forem Invocados por Invocação-Especial, enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode escolher 1 Monstro Link "Força Celeste" que você controla; equipe este card a ele como uma Magia de Equipamento que concede a ele 1500 de ATK. \r\nVocê só pode usar cada efeito de "Força Celeste - Mecha - Sabre Adil" uma vez por turno.','\r',char(13)),'\n',char(10)),'Aumentar ATK','Considerar como Card de Equipamento','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61156777,'BOXeador',replace(replace('Quando este card destruir um monstro do oponente em batalha e enviá-lo para o Cemitério: você pode colocar 1 marcador neste card. \r\nVocê pode enviar este card com 2 ou mais marcadores para o Cemitério; Invoque por Invocação-Especial 1 monstro de TERRA do seu Deck. \r\nSe este card seria destruído em batalha ou por um efeito de card, em vez disso, você pode remover 1 marcador deste card.','\r',char(13)),'\n',char(10)),'Coloque 1 marcador neste card','Invocação Especial','Substituir a destruição?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61159609,'Trismagistus',replace(replace('Na primeira vez que cada monstro "Magistus" equipado com um Card de Equipamento seria destruído em batalha a cada turno, ele não é destruído. \r\nVocê só pode usar 1 dos seguintes efeitos de "Trismagistus" por turno e apenas uma vez por turno.\r\n● Durante sua Fase Principal: você pode Invocar por Invocação-Especial 1 monstro Mago de Nível 4 da sua mão.\r\n● Você pode enviar este card com a face para cima para o Cemitério; Invoque por Invocação-Especial qualquer número de monstros "Magistus" com nomes diferentes da sua mão.','\r',char(13)),'\n',char(10)),'Invoque por Invocação Especial 1 monstro Mago de Nível 4 da sua mão','Invoque por Invocação Especial qualquer número de monstros "Magistus" da sua mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61160289,'Amunessia, a Rainha Ogdoádica',replace(replace('Se este card estiver no seu Cemitério: você pode oferecer 2 monstros como Tributo; Invoque este card por Invocação-Especial. \r\nSe um ou mais monstros forem Invocados por Invocação-Especial do Cemitério do seu oponente (exceto durante a Etapa de Dano): você pode enviar 1 card que ele controla para o Cemitério. \r\nSe um ou mais monstros forem enviados da mão ou do Deck do seu oponente para o Cemitério (exceto durante a Etapa de Dano): você pode Invocar por Invocação-Especial 1 monstro Réptil de LUZ ou de TREVAS do seu Cemitério, exceto "Amunessia, a Rainha Ogdoádica". \r\nVocê só pode usar cada efeito de "Amunessia, a Rainha Ogdoádica" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Envie para o Cemitério 1 card que seu oponente controla','Invoque por Invocação Especial um monstro Réptil do seu Cemitério','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61166988,'Libertação da Natureza Selvagem','Escolha 1 monstro Besta ou Besta-Guerreira; ele ganha ATK igual à sua DEF atual (até a Fase Final) e, se isso acontecer, ele é destruído durante a Fase Final.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61168637,'Linkassassino @Ignister',replace(replace('Se um monstro Ciberso que você controla seria usado como Matéria Link para um monstro "@Ignister", este card na sua mão também pode ser usado como matéria. \r\nSe este card for enviado para o Cemitério como Matéria Link: você pode descartar 1 card e, depois, escolha 1 Magia/Armadilha no campo, ou você pode escolher 2 se este card no campo foi usado como matéria; destrua esse(s) card(s). \r\nVocê só pode usar cada efeito de "Linkassassino @Ignister" uma vez por turno.','\r',char(13)),'\n',char(10)),'Destruir','Enviar do campo para o Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61173621,'Diabrete de Correntes Afiadas',replace(replace('Quando este card declarar um ataque: você pode adicionar 1 "Diabrete de Correntes Afiadas" do seu Deck à sua mão. \r\nSe este card for enviado da mão ou do campo para o Cemitério: você pode adicionar 1 card "Peladura" do seu Deck à sua mão. \r\nVocê só pode usar 1 efeito de "Diabrete de Correntes Afiadas" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicione 1 "Diabrete de Correntes Afiadas" do seu Deck à sua mão','Adicione 1 card "Peladura" do seu Deck à sua mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61175706,'Força Arcana IV - O Imperador',replace(replace('Se este card for Invocado: lance uma moeda.\r\n● Cara: Todos os monstros "Força Arcana" que você controla ganham 500 de ATK.\r\n● Coroa: Todos os monstros "Força Arcana" que você controla perdem 500 de ATK.','\r',char(13)),'\n',char(10)),'Jogar uma moeda','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61181383,'Carregador de Baterias',replace(replace('Pague 500 Life Points. \r\nInvoque, por Invocação-Especial, 1 monstro do seu Cemitério que inclua "Homem-Bateria" no seu nome.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61190918,'Blader Notável Toon',replace(replace('Não pode atacar no turno em que for Invocado. \r\nGanha 500 de ATK para cada monstro Dragão que seu oponente controla ou que estiver no Cemitério dele. \r\nEnquanto você controlar "Mundo Toon" e seu oponente não controlar nenhum monstro Toon, este card pode atacar diretamente seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61201220,'Espírito Fantasmagórico','Um espírito vingativo criado de muitas almas inquietas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61204971,'Gigante do Trovão, o HERÓI do Elemento',replace(replace('"Sparkman, o HERÓI do Elemento" + "Clayman, o HERÓI do Elemento"	\r\nDeve ser Invocado por Invocação-Fusão. \r\nUma vez por turno: você pode descartar 1 card e, depois, escolha 1 monstro no campo com um ATK original menor que o ATK deste card; destrua o alvo.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61231400,'Mecha Pirotech - Shiryu',replace(replace('Você pode Invocar este card por Invocação-Tributo oferecendo 1 Tributo. \r\nSe ele for Invocado desta forma, durante cada Fase Final: você sofre 1000 de dano. \r\nSe este card atacar um monstro em Posição de Defesa, ele causa dano de batalha perfurante ao seu oponente.','\r',char(13)),'\n',char(10)),'Ofereça 1 monstro como Tributo para Invocar','Causar dano','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61245403,'Maliciomilho',replace(replace('Se este card for Invocado por Invocação-Especial, enquanto você não controlar nenhum card na sua Zona do Campo: você pode adicionar 1 Magia de Campo do seu Deck à sua mão. \r\nSe este card for destruído em batalha ou por um efeito de card e enviado para o Cemitério: você pode escolher 1 Magia de Campo no seu Cemitério; adicione 1 card com o nome dela do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "Maliciomilho" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61245672,'Decodificar Transmissor Almardente',replace(replace('2+ monstros Ciberso com Atributos diferentes	\r\nGanha 500 de ATK para cada monstro para o qual ele apontar. \r\n(Efeito Rápido): você pode pagar 1000 PV; compre 1 card e, depois, se seus PV forem 2000 ou menos, você pode aplicar este efeito.\r\n● Bana este card do campo e, se isso acontecer, Invoque por Invocação-Especial 1 monstro Ciberso de Link-3 ou menos do seu Deck Adicional, exceto "Decodificar Transmissor Almardente".	\r\nVocê só pode usar este efeito de "Decodificar Transmissor Almardente" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Invocação Especial?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61248471,'Ascensão do Arquidemônio',replace(replace('2 monstros de Nível 6	\r\nO nome deste card se torna "Caveira Invocada" no campo, mas ele ainda é considerado como um card "Arquidemônio". \r\nSe um ou mais "Caveira Invocada" que você controla seriam destruídos em batalha ou por um efeito de card, em vez disso, você pode desassociar 1 matéria deste card. \r\nSe este card Invocado por Invocação-Xyz que você controla for enviado para o seu Cemitério por um card do oponente: você pode Invocar por Invocação-Especial 1 "Caveira Invocada" da sua mão, do Deck ou do Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61254509,'Peixe Tripé','Quando este card for Invocado por Invocação-Especial do Cemitério: Você pode escolher 1 monstro do Tipo Peixe, Serpente Marinha ou Aqua com a face para cima no campo; aumente o Nível dele em 1.','Aumentar o Nível','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61257789,'Dragão da Poeira Estelar/Modo de Ataque',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial com "Ativar Modo de Ataque" (ou por seu próprio efeito). \r\nQuando um card ou efeito for ativado (Efeito Rápido): você pode oferecer este card como Tributo; negue a ativação e, se isso acontecer, destrua-o. \r\nUma vez por turno, durante a Fase Final, se este efeito foi ativado neste turno (e não foi negado): você pode Invocar este card por Invocação-Especial do seu Cemitério. \r\nQuando este card no campo for destruído: você pode escolher 1 "Dragão da Poeira Estelar" no seu Cemitério; Invoque-o por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Negar a ativação e destruir','Invocação Especial','Invocar "Dragão da Poeira Estelar" por Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61257790,'Dragão da Poeira Estelar/Modo de Ataque',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial com "Ativar Modo de Ataque" (ou por seu próprio efeito). \r\nQuando um card ou efeito for ativado (Efeito Rápido): você pode oferecer este card como Tributo; negue a ativação e, se isso acontecer, destrua-o. \r\nUma vez por turno, durante a Fase Final, se este efeito foi ativado neste turno (e não foi negado): você pode Invocar este card por Invocação-Especial do seu Cemitério. \r\nQuando este card no campo for destruído: você pode escolher 1 "Dragão da Poeira Estelar" no seu Cemitério; Invoque-o por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Negar a ativação e destruir','Invocação Especial','Invocar "Dragão da Poeira Estelar" por Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61258740,'Amuleto do Senhor dos Mares',replace(replace('Envie este card para o Cemitério durante a 3ª Fase Final do seu oponente depois de sua ativação. \r\nMonstros de ÁGUA que você controla não podem ser destruídos pelos efeitos de card do seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61264008,'Troca de Terras',replace(replace('Escolha 1 card com a face para cima na Zona do Campo; bana-o e, depois, coloque-o com a face para cima na outra Zona do Campo e, depois, você pode selecionar 1 Magia de Campo com um nome original diferente no Cemitério do seu controlador atual e colocá-la com a face para cima na Zona do Campo do duelista cujo card foi banido. \r\nVocê só pode ativar 1 "Troca de Terras" por turno.','\r',char(13)),'\n',char(10)),'Colocar uma Magia de Campo do Cemitério?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61269611,'Dinolutador Iguanodraka',replace(replace('Você pode descartar 1 outro monstro Dinossauro; Invoque este card por Invocação-Especial da sua mão. \r\nVocê pode oferecer como Tributo 1 monstro Dinossauro e, depois, escolha 1 monstro "Dinolutador" no seu Cemitério com um nome original diferente que o do monstro oferecido como Tributo; Invoque-o por Invocação-Especial em Posição de Defesa. \r\nVocê só pode usar cada efeito de "Dinolutador Iguanodraka" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61272280,'Vahram, o Dragão da Divindade Magistus',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nEnquanto este card for um Card de Equipamento, o monstro equipado não pode ser destruído pelos efeitos de Magia/Armadilha do seu oponente. \r\nVocê só pode usar cada um dos seguintes efeitos de "Vahram, o Dragão da Divindade Magistus" uma vez por turno. \r\nSe este card Invocado por Invocação-Sincro for destruído: você pode destruir todos os cards com a face para cima que seu oponente controla. \r\nNo começo da Etapa de Dano, se o monstro ao qual este card estiver equipado batalhar um monstro do oponente: você pode destruir esse monstro do oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61283655,'Trapestrela Candina',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode adicionar 1 card "Trapestrela" do seu Deck à sua mão. \r\nSempre que seu oponente ativar um Card de Magia/Armadilha, cause 200 de dano a ele imediatamente depois que ele resolver.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61292243,'EMERGÊNCIA!',replace(replace('(Este card deve ser sempre considerado como um card "ÁS-Resgate".)	\r\nInvoque por Invocação-Especial 1 monstro "ÁS-Resgate" do seu Deck em Posição de Defesa e, depois, ofereça como Tributo 1 monstro "ÁS-Resgate" da sua mão ou do campo. \r\nDurante sua Fase Principal: você pode banir este card do seu Cemitério e, depois, escolha 1 Armadilha "ÁS-Resgate" no seu Cemitério; Baixe-a. \r\nVocê só pode usar cada efeito de "EMERGÊNCIA!" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61307542,'Paleozoico Anomalocaris',replace(replace('3+ monstros de Nível 2	\r\nNão é afetado por outros efeitos de monstro. \r\nUma vez por turno, se uma ou mais Armadilhas forem enviadas da sua Zona de Magias & Armadilhas para o Cemitério (exceto durante a Etapa de Dano): você pode escavar o card do topo do seu Deck e, se for uma Armadilha, adicione-a à sua mão. \r\nCaso contrário, envie-o para o Cemitério. \r\nUma vez por turno, se este card tiver uma Armadilha como matéria (Efeito Rápido): você pode desassociar 1 matéria deste card e, depois, escolha 1 card no campo; destrua-o.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61314842,'Arte Heráldica Avançada','Escolha 2 monstros "Besta Heráldica" no seu Cemitério; Invoque esses dois alvos por Invocação-Especial e, depois, imediatamente depois que este efeito resolver, Invoque por Invocação-Xyz 1 Monstro Xyz usando apenas esses 2 monstros.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61318483,'Jackfrost Fantardil',replace(replace('Não pode ser Invocado por Invocação-Normal, a não ser que você controle um monstro "Fantardil". \r\nUma vez por turno: você pode colocar este card com a face para baixo em Posição de Defesa. \r\nQuando um monstro do oponente declarar um ataque direto: você pode colocar esse monstro do oponente com a face para baixo em Posição de Defesa e, se isso acontecer, Invoque este card por Invocação-Especial da sua mão com a face para baixo em Posição de Defesa.','\r',char(13)),'\n',char(10)),'Mudar para Posição de Defesa com a face para baixo','Mudar para Posição de Defesa com a face para baixo','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61320914,'Raio Tênue, o HERÓI da Visão',replace(replace('Se você sofrer dano de batalha ou de efeito enquanto este card estiver no seu Cemitério: você pode colocar este card do seu Cemitério na sua Zona de Magias & Armadilhas como uma Armadilha Contínua com a face para cima. \r\nDurante a Fase Principal, se este card for considerado como uma Armadilha Contínua: você pode oferecer como Tributo 1 monstro "HERÓI"; Invoque este card por Invocação-Especial. \r\nSe este card for Invocado por Invocação-Especial da Zona de Magias & Armadilhas: você pode destruir 1 monstro de Nível 4 ou menos que seu oponente controla. \r\nVocê só pode usar cada efeito de "Raio Tênue, o HERÓI da Visão" uma vez por turno.','\r',char(13)),'\n',char(10)),'Baixar este card como um Card de Armadilha Contínua','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61322713,'Luz da Sombra',replace(replace('Escolha 1 monstro de TREVAS que você controla; Invoque por Invocação-Especial 1 monstro de LUZ do seu Deck ou Deck Adicional com o mesmo Tipo e Nível originais. \r\nVocê pode banir este card do seu Cemitério; durante sua Fase Principal neste turno, você pode Invocar por Invocação-Normal 1 monstro de LUZ ou de TREVAS em adição à sua Invocação-Normal/Baixar (padrão). \r\n(Você só pode se aproveitar deste efeito uma vez por turno.) \r\nVocê só pode usar cada efeito de "Luz da Sombra" uma vez por turno. \r\nVocê não pode conduzir sua Fase de Batalha no turno em que ativar qualquer um dos efeitos deste card.','\r',char(13)),'\n',char(10)),'Invocação Especial','Invocação Normal adicional','Invocar pelo efeito de "Luz da Sombra"','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61344030,'Paladínamo Galáctico',replace(replace('2 monstros de LUZ de Nível 4	\r\nUma vez por turno: você pode desassociar 2 Matérias Xyz deste card e, depois, escolher 1 monstro com a face para cima que seu oponente controla; mude o ATK dele para 0 e, se isso acontecer, ele tem seus efeitos negados. \r\nSe este card que você controla for destruído por um card do seu oponente (em batalha ou por um efeito de card) e enviado para o seu Cemitério: compre 1 card.','\r',char(13)),'\n',char(10)),'O ATK se torna 0','Comprar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61345801,'Liberação do Vácuo',replace(replace('Revele 1 card "Sombraneco" na sua mão; adicione 2 cards "Sombraneco" do seu Deck à sua mão, cada um com um tipo diferente (Monstro, Magia ou Armadilha) que o do card revelado e um do outro e, depois, descarte 1 card. \r\nVocê pode banir este card do seu Cemitério; adicione 1 monstro "Infernoide" do seu Deck ou Cemitério à sua mão. \r\nVocê só pode usar cada efeito de "Liberação do Vácuo" uma vez por turno.','\r',char(13)),'\n',char(10)),'Buscar e descartar','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61370518,'Caveira Arquidemônio do Relâmpago',replace(replace('Uma vez por turno, durante sua Fase de Apoio, você deve pagar 500 PV (isso não é opcional), ou este card é destruído. \r\nQuando estiver resolvendo um efeito de card do oponente que escolha este card como alvo, lance um dado de seis faces e negue esse efeito se o resultado for um 1, 3 ou 6 e, se isso acontecer, destrua esse card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61374414,'CXyz Cavaleiro N.As.Ch.',replace(replace('3 monstros de Nível 6	\r\nVocê também pode Invocar este card por Invocação-Xyz ao usar um "Cavaleiro N.As.H." que você controla (transfira as matérias dele para este card). \r\nNão pode ser destruído por efeitos de card. \r\nVocê pode desassociar 1 matéria deste card; Invoque por Invocação-Especial do seu Deck Adicional, 1 Monstro Xyz "Número" com um número entre "101" e "107" em seu nome, usando este card com a face para cima que você controla (isso é considerado uma Invocação-Xyz, transfira as matérias dele para o monstro Invocado), mas destrua-o durante a próxima Fase Final do seu oponente. \r\nVocê só pode usar este efeito de "CXyz Cavaleiro N.As.Ch." uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Xyz usando "Cavaleiro N.As.H." como matéria?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61380658,'Wattsaltador','Os monstros do seu oponente não podem escolher monstros "Watt" como alvo de ataques, exceto este e, além disso, seu oponente não pode escolhê-los como alvo de efeitos de card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61391302,'Dragão Avançado de Olhos Anômalos',replace(replace('Você pode Invocar este card por Invocação-Tributo ao oferecer como Tributo 1 monstro de Nível 5 ou mais. \r\nSe este card for Invocado por Invocação-Tributo: você pode destruir 1 monstro que seu oponente controla e, se isso acontecer, cause dano ao seu oponente igual ao ATK original desse monstro. \r\nQuando este card destruir um monstro em batalha: você pode Invocar por Invocação-Especial 1 monstro de Nível 5 ou mais da sua mão ou do Cemitério em Posição de Defesa, exceto "Dragão Avançado de Olhos Anômalos". \r\nVocê só pode usar este efeito de "Dragão Avançado de Olhos Anômalos" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ofereça 1 monstro de Nível 5 ou mais como Tributo para uma Invocação Tributo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61397885,'Poder Fantasma Espiral',replace(replace('Se todos os monstros que você controla forem Monstros Normais (mín. 1): escolha 1 Monstro de Efeito que seu oponente controla; até o final deste turno, ele perde 1000 de ATK e DEF e, além disso, ele tem seus efeitos negados. \r\nSe "Umi" estiver no campo, você pode ativar este card da sua mão. \r\nVocê pode banir este card do seu Cemitério e, depois, escolher 1 Monstro Normal que você controla; equipe 1 Cards de Magia de Equipamento "Fantasma Espiral" da sua mão ou do Cemitério nesse Monstro Normal.','\r',char(13)),'\n',char(10)),'','Ativar aplicando o efeito de "Poder Fantasma Espiral".','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61398234,'Guardião do Portão do Vento e da Água',replace(replace('"Kazejin" + "Suijin"	\r\nDeve ser Invocado por Invocação-Especial (do seu Deck Adicional) ao banir os cards acima que você controla. \r\nUma vez por Corrente, quando seu oponente ativar um Card de Magia/Armadilha ou seus efeitos no campo (Efeito Rápido): você pode negar o efeito. \r\nVocê só pode usar este efeito de "Guardião do Portão do Vento e da Água" duas vezes por turno. \r\nSe este card com a face para cima Invocado por Invocação-Especial sob o controle do seu dono deixar o campo devido a um card do oponente: você pode Invocar por Invocação-Especial 1 dos seus "Kazejin" ou "Suijin" banidos.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61399402,'Dragão de Luz @Ignister',replace(replace('2 monstros de Nível 4	\r\nSe um ou mais monstros que você controla seriam destruídos por um efeito de card, em vez disso, você pode desassociar 1 matéria deste card. \r\nVocê só pode usar cada um dos seguintes efeitos de "Dragão de Luz @Ignister" uma vez por turno. \r\nVocê pode desassociar 1 matéria deste card; destrua monstros com a face para cima que seu oponente controla, até o número de monstros "@Ignister" que você controla. \r\nQuando outro monstro Ciberso que você controla causar dano de batalha ao seu oponente: você pode Invocar por Invocação-Especial 1 Monstro Link do seu Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61405855,'Espada da Alma do Dragão',replace(replace('Só pode ser equipado a um monstro Guerreiro. \r\nEle ganha 700 de ATK. \r\nDepois do cálculo de dano, se o monstro equipado batalhar um monstro Dragão: destrua esse monstro no final dessa Fase de Batalha.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61411502,'Rebentar do Elemento',replace(replace('Ofereça como Tributo 1 monstro de cada VENTO, ÁGUA, FOGO, e TERRA no seu Campo para activar este card. \r\nDestrúa todos os cards no Campo do seu adversário.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61420130,'Paleozoico Hallucigenia',replace(replace('Escolha 1 monstro com a face para cima no campo; até o final deste turno, o ATK/DEF dele se tornam metade do seu ATK/DEF atuais. \r\nUma vez por Corrente, quando um Card de Armadilha for ativado enquanto este card estiver no seu Cemitério: você pode Invocar este card por Invocação-Especial como um Monstro Normal (Aqua/ÁGUA/Nível 2/ATK 1200/DEF 0).	\r\n(Este card NÃO é considerado como uma Armadilha.) \r\nSe Invocado desta forma, este card não é afetado por efeitos de monstro e, além disso, bana-o quando ele deixar o campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61434639,'Reacender o Cinzento',replace(replace('Coloque 1 dos seus cards "Cinzento(a)" que estiverem banidos ou no seu Cemitério no fundo do seu Deck Principal, exceto "Reacender o Cinzento" e, depois, escolha 1 Monstro de Efeito que seu oponente controla; negue seus efeitos até o final deste turno. \r\nVocê só pode ativar 1 "Reacender o Cinzento" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61441708,'Fênix Sagrada de Nephthys',replace(replace('Uma vez por turno, durante sua próxima Fase de Apoio depois que este card foi destruído por um efeito de card e enviado para o Cemitério: Invoque este card por Invocação-Especial do Cemitério. \r\nSe isso acontecer: destrua todas as Magias e Armadilhas no campo.','\r',char(13)),'\n',char(10)),'Invocação Especial','Destrua todos os Cards de Magia/Armadilha','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61454890,'Necrolançador, Senhor das Horas','O Necrolançador caolho lança suas investidas usando um anel dimensional que pode aparecer de forma inesperada.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61459246,'Oniromancia do Espelho Onírico',replace(replace('Ative 1 desses efeitos.\r\n● Quando seu oponente ativar um Card de Magia/Armadilha enquanto um "Espelho Onírico da Alegria" estiver em uma Zona do Campo: negue a ativação e, se isso acontecer, destrua esse card.\r\n● Quando seu oponente Invocaria um ou mais monstros por Invocação-Especial enquanto um "Espelho Onírico do Terror" estiver em uma Zona do Campo: negue a Invocação e, se isso acontecer, destrua esse monstro.	\r\nVocê só pode ativar 1 "Oniromancia do Espelho Onírico" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61465001,'Nuvem Ruidosa, a Serpente da Tempestade',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro deve ser Invocado por Invocação-Especial (da sua mão) ao banir 1 monstro de FOGO e 1 de VENTO do seu Cemitério. \r\nVocê só pode usar cada um dos seguintes efeitos de "Nuvem Ruidosa, a Serpente da Tempestade" uma vez por turno.\r\n● Você pode banir 1 monstro de FOGO do seu Cemitério e, depois, escolher 1 monstro que seu oponente controla; destrua esse monstro e, se isso acontecer, este card ganha ATK igual ao ATK original do monstro destruído.\r\n● Você pode banir 1 monstro de VENTO do seu Cemitério e, depois, escolher 1 card na Zona de Magias & Armadilhas do seu oponente; destrua-o.','\r',char(13)),'\n',char(10)),'Destruir 1 monstro','Destruir Magia/Armadilha','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61466310,'Retorno dos Monarcas',replace(replace('Você não pode Invocar monstros por Invocação-Especial do Deck Adicional. \r\nQuando você Invocar um monstro por Invocação-Tributo: você pode ativar 1 desses efeitos;\r\n● Adicione, do seu Deck à sua mão, 1 monstro com 2400 de ATK e 1000 de DEF com um nome diferente que o do monstro Invocado por Invocação-Tributo.\r\n● Adicione, do seu Deck à sua mão, 1 monstro com 2800 de ATK e 1000 de DEF com um nome diferente que o do monstro Invocado por Invocação-Tributo.	\r\nO monstro Invocado por Invocação-Tributo deve estar com a face para cima no campo para que você possa ativar e resolver este efeito. \r\nVocê só pode usar este efeito de "Retorno dos Monarcas" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Monstro com 2400 ATK / 1000 DEF','Monstro com 2800 ATK / 1000 DEF','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61468779,'Grandesolo, o Senhor Elemental',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao ter exatamente 5 monstros de TERRA no seu Cemitério. \r\nQuando este card for Invocado por Invocação-Especial: você pode escolher 1 monstro no Cemitério de qualquer duelista; Invoque o alvo por Invocação-Especial. \r\nVocê só pode usar este efeito de "Grandesolo, o Senhor Elemental" uma vez por turno. \r\nSe este card com a face para cima deixar o campo, pule a Fase de Batalha do seu próximo turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Pular a Fase de Batalha','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61470213,'Altergeist Adminia',replace(replace('2+ monstros "Altergeist"	\r\nSe este card for Invocado por Invocação-Link: você pode Baixar 1 Armadilha "Altergeist" diretamente do seu Deck. \r\nUma vez enquanto este card estiver com a face para cima no campo, durante a Fase Principal (Efeito Rápido): você pode enviar para o Cemitério 1 card que você controla e, depois, escolha 1 Monstro de Efeito que seu oponente controla; tome o controle do alvo e, se isso acontecer, ele também é considerado como um monstro "Altergeist". \r\nVocê só pode usar cada efeito de "Altergeist Adminia" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61472381,'Irmandade do Punho de Fogo - Cefo',replace(replace('Você pode Invocar este card por Invocação-Ritual com "Formação de Fogo - Domei". \r\nVocê pode descartar 1 monstro; Baixe 1 Magia/Armadilha "Formação de Fogo" diretamente do seu Deck ou Cemitério. \r\nQuando seu oponente ativar um efeito de monstro (Efeito Rápido): você pode enviar 1 card "Punho de Fogo" ou "Formação de Fogo" com a face para cima que você controla para o Cemitério, exceto "Irmandade do Punho de Fogo - Cefo"; negue esse efeito. \r\nVocê só pode usar cada efeito de "Irmandade do Punho de Fogo - Cefo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61480937,'Regulus, a Besta Fada',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 Magia/Armadilha que mencione "Dragão Fada Antigo" do seu Deck à sua mão. \r\nDurante sua Fase Principal: você pode Invocar por Invocação-Especial 1 monstro de LUZ de Nível 4 ou menos (Besta, Planta ou Fada) da sua mão em Posição de Defesa. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 Magia de Campo no seu Cemitério; coloque-a no fundo do Deck e, depois, compre 1 card. \r\nVocê só pode usar cada efeito de "Regulus, a Besta Fada" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Invocação Especial','Recuperar','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61488417,'Chiwen, Luz de Yang Zing',replace(replace('Quando este card que você controla for destruído em batalha ou por um efeito de card e enviado para o seu Cemitério: você pode Invocar por Invocação-Especial 1 monstro "Yang Zing" do seu Deck, exceto "Chiwen, Luz de Yang Zing". \r\nQuando um ou mais monstros "Yang Zing" que você controla forem destruídos em batalha ou por um efeito de card e enviado para o Cemitério, enquanto este card estiver no seu Cemitério: você pode Invocar este card por Invocação-Especial e, se isso acontecer, bana-o quando ele deixar o campo. \r\nVocê só pode usar 1 efeito de "Chiwen, Luz de Yang Zing" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Invoque por Invocação Especial um monstro "Yang Zing" do Deck','Invocar este card por Invocação Especial do Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61496006,'Tubarão do Abismo',replace(replace('Se este card for usado para a Invocação-Xyz de um monstro "Número", ele pode ser considerado como um monstro de Nível 3 ou 4. \r\nSe todos os monstros que você controla forem de ÁGUA (mín. 1): você pode Invocar este card por Invocação-Especial da sua mão e, se isso acontecer, adicione 1 monstro Peixe de Nível 3, 4 ou 5 do seu Deck à sua mão, exceto "Tubarão do Abismo". \r\nPelo resto deste turno, você não pode Invocar monstros por Invocação-Especial, exceto monstros de ÁGUA e, além disso, dobre o primeiro dano de batalha causado ao seu oponente neste turno por um monstro "Número" seu que estiver batalhando outro monstro. \r\nVocê só pode usar este efeito de "Tubarão do Abismo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61505339,'O Criador',replace(replace('Escolha 1 monstro do seu Cemitério. \r\nEnvie 1 card da sua mão para o Cemitério e Invoque, por Invocação-Especial, o monstro escolhido. \r\nVocê pode usar este efeito apenas uma vez por turno. \r\nEste card não pode ser Invocado, por Invocação-Especial, do Cemitério.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61525276,'Maldição do Dragão, o Dragão Amaldiçoado',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 Magia/Armadilha do seu Deck à sua mão, que liste especificamente o card "Gaia, o Matador de Dragões" em seu texto. \r\nSe este card for enviado para o Cemitério: você pode escolher 1 "Gaia, o Matador de Dragões" na sua Zona de Monstros; até o final deste turno, negue os efeitos dos monstros com a face para cima que seu oponente controla atualmente com ATK menor ou igual que o dele. \r\nVocê só pode usar cada efeito de "Maldição do Dragão, o Dragão Amaldiçoado" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61528025,'Exorcista da Luz','Qualquer card enviado para o Cemitério, em vez disso, é banido.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61529473,'Verdadeiro Draco Apocalipse',replace(replace('Se este card for enviado da Zona de Magias & Armadilhas para o Cemitério: você pode escolher 1 monstro no campo; destrua-o. \r\nVocê não pode ativar os seguintes efeitos de "Verdadeiro Draco Apocalipse" na mesma Corrente. \r\nVocê pode escolher 1 outro card "Verdadeiro(a) Draco" ou "Verdadeiro Rei" que você controla; destrua-o e, se isso acontecer, o ATK/DEF de todos os monstros com a face para cima que seu oponente controla se tornam a metade dos seus ATK/DEF atuais (mesmo que este card deixe o campo). \r\nDurante a Fase Principal do seu oponente, você pode: imediatamente depois que este efeito resolver, Invocar por Invocação-Tributo 1 monstro "Verdadeiro(a) Draco" ou "Verdadeiro Rei" com a face para cima. \r\nVocê só pode usar cada efeito de "Verdadeiro Draco Apocalipse" uma vez por turno.','\r',char(13)),'\n',char(10)),'Reduzir ATK/DEF pela metade','Invocação Tributo','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61538782,'Caminharoide',replace(replace('Se este card destruir um monstro do oponente em batalha e enviá-lo para o Cemitério: equipe o monstro destruído a este card. \r\nGanha ATK igual ao ATK combinado dos monstros equipados a ele por este efeito.','\r',char(13)),'\n',char(10)),'Equipar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61557074,'Palácio do Senhor Elemental',replace(replace('Todos os monstros que você controla ganham ATK/DEF igual ao número de Atributos diferentes no seu Cemitério x 200. \r\nUma vez por turno: você pode adicionar 1 monstro "Sabrelemento" do seu Deck à sua mão, mas pule a Fase de Batalha do seu próximo turno (mesmo que este card deixe o campo). \r\nUma vez por turno, se um monstro "Sabrelemento" na sua mão ou no campo enviar um ou mais cards da mão para o Cemitério para ativar um efeito, em vez disso, você pode enviar esse número de monstros "Sabrelemento" do seu Deck para o Cemitério.','\r',char(13)),'\n',char(10)),'Procurar no Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61583217,'Cinet Universo',replace(replace('Todos os Monstros Link que você controla ganham 300 de ATK. \r\nUma vez por turno: você pode escolher 1 monstro no Cemitério; embaralhe-o no Deck. \r\nSe este card no campo for destruído por um efeito de card: envie para o Cemitério todos os monstros nas Zonas de Monstros Adicionais.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61587183,'Escorpião das Trevas - Chick o Cobarde',replace(replace('Quando este card causar dano de batalha ao seu oponente: você pode ativar 1 desses efeitos.\r\n● Escolha 1 card no campo; devolva o alvo para a mão.\r\n● Olhe o card do topo do Deck dele e, depois, coloque-o no topo ou no fundo do Deck.','\r',char(13)),'\n',char(10)),'Ativar 1 efeito','Retornar à mão do dono 1 card no campo.','Veja a(s) 1 carta(s) do topo do Deck do seu oponente.','Colocar no topo do Deck','Colocar no fundo do Deck','','','','','','','','','','','');
INSERT INTO texts VALUES(61592395,'Livro de Magia da Eternidade',replace(replace('Escolha 1 dos seus Cards de Magia "Livro de Magia" banidos, exceto "Livro de Magia da Eternidade"; adicione o alvo à sua mão. \r\nVocê só pode ativar 1 "Livro de Magia da Eternidade" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61606250,'Blitz do Dragão Armado',replace(replace('Escolha 1 monstro "Dragão Armado" que você controla; pegue 1 monstro com o mesmo nome do seu Deck ou Cemitério e adicione-o à sua mão ou Invoque-o por Invocação-Especial, ignorando suas condições de Invocação, mas ele não pode atacar diretamente. \r\nVocê só pode ativar 1 "Blitz do Dragão Armado" por turno. \r\nVocê não pode Invocar monstros por Invocação-Especial no turno em que ativar este card, exceto monstros Dragão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61613388,'U.A. Tática de Contra-ataque',replace(replace('Se você controlar 2 ou mais monstros "U.A." com nomes diferentes: embaralhe no Deck tantos monstros no campo quanto possível e, depois, Invoque por Invocação-Especial monstros "U.A." do seu Deck que tenham nomes diferentes uns dos outros, até o número de cards embaralhados no seu Deck Principal, mas esses monstros não podem atacar neste turno. \r\nDepois, seu oponente pode Invocar por Invocação-Especial monstros do Deck dele até o número de cards embaralhados no Deck Principal dele. \r\nVocê só pode ativar 1 "U.A. Tática de Contra-ataque" por turno.','\r',char(13)),'\n',char(10)),'Escolher outro monstro "U.A."?','Invocar por Invocação Especial um monstro do Deck?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61622107,'Destruição da Bolha',replace(replace('Este card só pode ser ativado quando qualquer jogador tenha 6 ou mais cards no Campo e/ou na sua mão. \r\nO(s) jogador(es) depois escolhem e enviam cards para os seus respetivos Cemitérios até que os cards no Campo e na sua mão sejam igual a 5.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61623148,'Grimório do Mundo Negro','Durante sua Fase Final, se você descartar um ou mais monstros para o Cemitério porque você tinha mais cards que o seu limite de cards na mão: você pode escolher 1 desses monstros; Invoque o alvo por Invocação-Especial.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61632317,'Roda Dentada Sinistra','Se este card for enviado ao Cemitério para a Invocação-Sincro de um Monstro Sincro de TREVAS, você pode destruir 1 Card de Magia ou Armadilha com a face para cima.','Destruir Magias/Armadilhas','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61639289,'Cavaleirardor Cruzado',replace(replace('Escala de Pêndulo = 2\r\n[ Efeito de Pêndulo ]\r\nSe você tiver um card "Cavaleirardor" na sua outra Zona de Pêndulo: você pode destruir os dois cards nas suas Zonas de Pêndulo e, se isso acontecer, adicione 1 monstro de FOGO do Tipo Guerreiro do seu Deck ou Cemitério à sua mão.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nEste impulsivo guerreiro Cavaleirardor é fanático em relação as causas pelas quais ele luta. Por causa dessa paixão, seus companheiros sempre tentam mantê-lo próximo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61641818,'Dragão do Mundo Virtual - Longlong',replace(replace('2+ monstros de Nível 3 com o mesmo Tipo e Atributo	\r\nSeu oponente não pode escolher este card como alvo de efeitos de card enquanto ele tiver Matérias Xyz. \r\nQuando seu oponente ativar o efeito de um monstro com um Atributo que ele não tenha no seu campo, enquanto ele controlar um monstro com a face para cima (Efeito Rápido): você pode desassociar 2 matérias deste card; negue a ativação. \r\nVocê só pode usar este efeito de "Dragão do Mundo Virtual - Longlong" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61650133,'Maldição da Invocação',replace(replace('Se um ou mais monstros forem Invocados por Invocação-Especial: o controlador atual desse(s) monstro(s) bane 1 card da mão dele. \r\nUma vez por turno, durante sua Fase Final, pague 500 PV ou destrua este card.','\r',char(13)),'\n',char(10)),'Pagar 500 PV para manter "Maldição da Invocação"?','Banir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61654098,'Descobrimento do Legado Mundial',replace(replace('Todos os monstros "Cálice Mundial" no campo ganham 300 de ATK/DEF. \r\nUma vez por turno, se um monstro "Cálice Mundial" com a face para cima que você controla for destruído em batalha ou deixar o campo devido a um efeito de card do oponente: você pode escolher 1 monstro "Cálice Mundial" no seu Cemitério; Invoque-o por Invocação-Especial em Posição de Defesa.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61656650,'Vingança Remota',replace(replace('Ative apenas quando um monstro que você controla for escolhido como alvo de um efeito de Magia, Armadilha ou Monstro de Efeito que destrua 1 monstro no campo. \r\nTroque o alvo para um monstro apropriado que seu oponente controla.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61665245,'Feiticeira Invocadora',replace(replace('2+ monstros com o mesmo Tipo, exceto Fichas	\r\nSe este card for Invocado por Invocação-Link: você pode Invocar por Invocação-Especial 1 monstro da sua mão em Posição de Defesa, em uma zona do seu oponente para a qual este card apontar (mas negue seus efeitos) e, depois, você pode Invocar por Invocação-Especial 1 monstro do seu Deck em Posição de Defesa com o mesmo Tipo que o desse monstro (mas negue seus efeitos). \r\nSe você Invocar do seu Deck desta forma, você não pode Invocar por Invocação-Especial pelo resto deste turno, exceto monstros com esse mesmo Tipo original. \r\nVocê só pode usar este efeito de "Feiticeira Invocadora" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial da mão','Invocar por Invocação Especial do Deck?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61668670,'G Golem Coração de Cristal',replace(replace('2 monstros Ciberso	\r\nVocê pode escolher 1 Monstro Link de TERRA no seu Cemitério; Invoque-o por Invocação-Especial em uma zona sua para a qual este card apontar e, se isso acontecer, coloque 1 Marcador de GG neste card. \r\nVocê só pode usar este efeito de "G Golem Coração de Cristal" uma vez por turno. \r\nMonstros de TERRA co-linkados a este card ganham 600 de ATK para cada Marcador de GG neste card, podem realizar um segundo ataque durante cada Fase de Batalha e, além disso, se eles atacarem um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61677004,'Predaplanta Cobra Darlingtonia',replace(replace('Se este card for Invocado por Invocação-Especial pelo efeito de um monstro "Predaplanta": você pode adicionar 1 Card de Magia "Polimerização" ou Card de Magia "Fusão" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Predaplanta Cobra Darlingtonia" uma vez por Duelo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61679541,'Boxeador Obstinado Pegador de Nuca','No começo da Etapa de Dano, se este card atacar um monstro em Posição de Defesa: destrua esse monstro.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61681816,'Propa Gandake',replace(replace('Uma vez por turno, se você controlar um ou mais monstros cujo Tipo original seja Besta, Inseto, Planta ou Rocha: você pode declarar 1 desses Tipos que você controla; este card se torna do Tipo declarado. \r\nSe este card aplicou este efeito, além disso, aplique os seguintes efeitos enquanto ele permanecer na Zona de Monstros.\r\n● Todos os monstros com a face para cima no campo se tornam do mesmo Tipo que este card.\r\n● Os monstros no campo com o Tipo deste card não podem ser escolhidos como alvo por nenhum duelista usando os efeitos de monstros que seu oponente controla com esse mesmo Tipo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61692648,'Locomotiva Coração de Leão','Quando este card declarar um ataque: até o final da Etapa de Dano, seu ATK se torna metade do seu ATK original.','Alterar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61705417,'Ladrão de Túmulos',replace(replace('Selecione 1 Card de Magia do Cemitério do seu oponente. \r\nAté o final do turno, você pode usá-lo como se estivesse na sua mão. \r\nSe o usar, você sofre 2000 de dano.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61728808,'Metalmorfose Pesado Amalgam',replace(replace('2 monstros "Metalmorfose"	\r\nSe este card for enviado da Zona de Monstros para o Cemitério por um efeito de card: você pode ativar 1 desses efeitos;\r\n● Escolha 1 monstro "Metalmorfose" que você controla; equipe este card a ele.	\r\nEle ganha 1000 de ATK.\r\n● Escolha 1 card "Metalmorfose" que você controla; destrua-o e, se isso acontecer, Invoque este card por Invocação-Especial.	\r\nVocê só pode usar este efeito de "Metalmorfose Pesado Amalgam" uma vez por turno.','\r',char(13)),'\n',char(10)),'Equipe este card como um Card de Equipamento','Invocar este card por Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61737116,'Ancião dos Seis Samurai','Se o seu oponente controlar um monstro e você não controlar nenhum monstro, você pode Invocar este card (da sua mão) por Invocação-Especial.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61740673,'Ordem Imperial',replace(replace('Negue todos os efeitos de Magia no campo. \r\nUma vez por turno, durante a Fase de Apoio, você deve pagar 700 PV (isso não é opcional) ou este card é destruído.','\r',char(13)),'\n',char(10)),'Pague 700 PV','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61757117,'Graça Divina - Nortewemko',replace(replace('Este card só pode ser Invocado por Invocação-Ritual com o Card de Magia de Ritual "Ritual da Graça". \r\nQuando este card for Invocado por Invocação-Ritual, selecione um número de cards com a face para cima no campo (exceto este card) até o número de monstros usados para a Invocação-Ritual. \r\nEnquanto qualquer um dos cards selecionados estiver com a face para cima no campo, este card não pode ser destruído por efeitos de card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61764082,'Dinolutador Braquiaríete',replace(replace('Quando um monstro "Dinolutador" seu causar dano de batalha ao seu oponente: você pode Invocar este card por Invocação-Especial da sua mão em Posição de Defesa. \r\nVocê só pode usar este efeito de "Dinolutador Braquiaríete" uma vez por turno. \r\nSeu oponente não pode escolher outros monstros "Dinolutador" que você controla como alvo de efeitos de card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61773610,'Guardião da Voz Sem Voz',replace(replace('Se um ou mais monstros com a face para cima que você controla forem destruídos em batalha ou por um efeito de card, exceto Monstros de Ritual: você pode Invocar por Invocação-Especial 1 "Guardião Caveira" da sua mão ou do Deck. \r\nVocê pode enviar este card com a face para cima para o Cemitério e, depois, escolha 1 Monstro de Ritual que você controla; ele ganha ATK igual ao ATK original combinado dos outros monstros atualmente no campo, até o final deste turno. \r\nVocê só pode usar cada efeito de "Guardião da Voz Sem Voz" uma vez por turno e não pode ativar mais que 1 na mesma Corrente.','\r',char(13)),'\n',char(10)),'Invocação Especial','Aumentar ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61775475,'Armas Genex Retorno Zero',replace(replace('1 Regulador de TREVAS + 1+ monstros não-Reguladores	\r\nQuando seu oponente ativar um efeito de monstro (Efeito Rápido): você pode banir 1 monstro do seu Cemitério com o mesmo Atributo; negue a ativação e, se isso acontecer, destrua esse monstro. \r\n(Você só pode banir cada Atributo uma vez por turno para ativar este efeito de "Armas Genex Retorno Zero".) \r\nUma vez por turno: você pode escolher até 6 dos seus monstros "Genex" com Atributos diferentes que estiverem banidos e/ou no seu Cemitério; embaralhe-os no Deck e, depois, você pode destruir até esse número de cards nas Zonas de Magias & Armadilhas.','\r',char(13)),'\n',char(10)),'Negar a ativação','Destruir um card na Zona de Magias/Armadilhas?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61777313,'Vanadis do Ascendente Nórdico',replace(replace('Para uma Invocação-Sincro, você pode substituir este card por qualquer 1 Regulador "Nórdic". \r\nSe este card for usado como Matéria Sincro, todas as outras Matérias Sincro devem ser monstros "Nórdic". \r\nUma vez por turno: você pode enviar 1 monstro "Nórdic" do seu Deck para o Cemitério; até o final deste turno, o Nível deste card se torna o Nível desse monstro.','\r',char(13)),'\n',char(10)),'Alterar Nível','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61791132,'Garfo Malívoro','Você pode enviar 1 outro monstro do Tipo Demônio da sua mão para o Cemitério; Invoque este card por Invocação-Especial da sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61802346,'Dragão da Nevasca','Uma vez por turno: você pode escolher 1 monstro que seu oponente controla; ele não pode mudar sua posição de batalha ou declarar um ataque até o final do próximo turno do seu oponente.','Restrição de ação','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61807040,'Flelfo','Uma vez por turno: você pode revelar 1 monstro da sua mão; até a Fase Final, aumente o Nível deste card pelo Nível do monstro revelado.','Aumentar o Nível','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61818176,'Renovação Fantardil',replace(replace('Escolha 1 Magia de Campo "Fantardil" na sua Zona do Campo; devolva-a para a mão e, depois, você pode ativar 1 Magia de Campo da sua mão ou do Deck. \r\nVocê pode banir este card do seu Cemitério e, depois, escolher 1 Monstro Xyz "Fantardil" que você controla; Invoque por Invocação-Especial do seu Deck Adicional, 1 Monstro Xyz "Fantardil" com um nome diferente, usando o alvo como matéria. \r\n(Isso é considerado uma Invocação-Xyz. Transfira as matérias dele para o monstro Invocado.) \r\nVocê só pode usar este efeito de "Renovação Fantardil" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Ativar uma Magia de Campo?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61822419,'Morganita Controla-Culpa',replace(replace('Pelo resto deste Duelo, aplique os seguintes efeitos.\r\n● Você não pode ativar efeitos de monstro na mão.\r\n● Você pode Invocar monstros de Nível 5 ou mais por Invocação-Normal sem oferecer Tributo.\r\n● Você não paga PV para ativar Cards de Magia/Armadilha.	\r\nVocê pode banir este card do seu Cemitério e, depois, revele 1 card "Morganita" na sua mão; coloque o card revelado no fundo do Deck e, depois, compre 1 card.','\r',char(13)),'\n',char(10)),'Ativar','O efeito de "Morganita Controla-Culpa" está sendo aplicado.','Invocação Normal sem Tributo, pelo efeito de "Morganita Controla-Culpa"','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61831093,'O Verde Kappa','VIRE: Escolha 2 Cards de Magia ou de Armadilha no Campo com a face para baixo e os destrua.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61840587,'Conjunto de Baterias Portátil',replace(replace('Escolha 2 monstros "Homem-Bateria" do seu Cemitério e Invoque-os por Invocação-Especial em Posição de Ataque. \r\nQuando este card for removido do campo, destrua esses monstros. \r\nQuando ambos os monstros forem removidos do campo, destrua este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61844784,'Refletor Mágico',replace(replace('Escolha 1 Card de Magia com a face para cima no Campo e ponha 1 contador nele. \r\nSe o card escolhido for destruído, remova 1 contador ao invés de destruír o card.','\r',char(13)),'\n',char(10)),'Escolha 1 Card de Magia com a face para cima','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61845881,'Minairuka',replace(replace('Quando o efeito de um monstro de ÁGUA for ativado (Efeito Rápido): você pode Invocar este card por Invocação-Especial da sua mão. \r\nVocê pode banir 1 monstro Peixe, Serpente Marinha ou Aqua com a face para cima que você controla e, depois, escolha 1 card com a face para cima no campo; negue seus efeitos até o final do turno do seu oponente. \r\nVocê só pode usar cada efeito de "Minairuka" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61850482,'Modulação de Nível',replace(replace('Seu oponente compra 2 cards. \r\nInvoque por Invocação-Especial 1 monstro "LV" do seu Cemitério, ignorando as condições de Invocação. \r\nO monstro Invocado por Invocação-Especial com este efeito não pode atacar nem ativar ou aplicar seu efeito neste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61854111,'Espada Lendária',replace(replace('Só pode ser equipado a um monstro Guerreiro. \r\nEle ganha 300 de ATK/DEF.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61864793,'Gigante do Terremoto','Uma vez por turno, quando a posição de batalha deste card for alterada, você pode selecionar 1 monstro que seu oponente controla e mudar sua posição de batalha.','Alterar posição de batalha','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61884774,'Canalização de Yosenju Oroshi',replace(replace('Se você não controlar nenhum monstro: ative 1 dos seguintes efeitos; além disso, pelo resto deste turno depois que este card resolver, você não pode Invocar monstros por Invocação-Especial, exceto monstros "Yosenju".\r\n● Adicione 1 monstro "Yosenju" de Nível 5 ou mais do seu Deck à sua mão.\r\n● Coloque 1 "Yosenju Shinchu E" e 1 "Yosenju Shinchu D" do seu Deck nas suas Zonas de Pêndulo, mas destrua-os durante a Fase Final do seu oponente.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Colocar na Zona de Pêndulo','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61888819,'Origem da Hordeum Ferro',replace(replace('2 monstros "Hordeum"	\r\nEnquanto este card estiver na Zona de Monstros Adicional, se um monstro seria Invocado por Invocação-Especial do Deck Adicional na Zona de Monstros Principal, ele deve ser Invocado em uma zona para a qual este card apontar. \r\nEnquanto este card apontar para um monstro, nenhum duelista pode escolhê-lo como alvo de efeitos de card e, além disso, ele não pode ser destruído em batalha ou por efeitos de card. \r\nUma vez por turno, quando um ou mais monstros no campo forem destruídos em batalha ou por um efeito de card: você pode Invocar por Invocação-Especial monstros "Hordeum" de Nível 4 ou menos do seu Deck em Posição de Defesa, até o número de monstros destruídos.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61901281,'Dragão Negro Colapserpente',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao banir 1 monstro de LUZ do seu Cemitério. \r\nVocê só pode Invocar "Dragão Negro Colapserpente" por Invocação-Especial uma vez por turno desta forma. \r\nSe este card for enviado do campo para o Cemitério: você pode adicionar 1 "Dragão Branco Wivexplosão" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61912252,'Valetadeira Infinisteira',replace(replace('Você pode oferecer como Tributo 1 monstro Máquina de TERRA; Invoque este card por Invocação-Especial da sua mão em Posição de Defesa. \r\nVocê pode banir este card do seu Cemitério e, depois, escolher 1 monstro "Infinisteira" de Nível 5 ou menos no seu Cemitério, exceto "Valetadeira Infinisteira"; Invoque esse monstro por Invocação-Especial em Posição de Defesa. \r\nVocê só pode usar cada efeito de "Valetadeira Infinisteira" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61936647,'Cavaleiros Fantasmas - Espada',replace(replace('Ative este card ao escolher 1 monstro com a face para cima no campo; ele ganha 800 de ATK e, além disso, se o alvo seria destruído em batalha ou por um efeito de card, em vez disso, você pode destruir este card. \r\nQuando ele deixar o campo, destrua este card. \r\nVocê pode banir este card do seu Cemitério e, depois, escolher 1 monstro "Os Cavaleiros Fantasmas" no seu Cemitério; Invoque-o por Invocação-Especial, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar este efeito de "Cavaleiros Fantasmas - Espada" uma vez por turno.','\r',char(13)),'\n',char(10)),'Usar o efeito de "Cavaleiros Fantasmas - Espada" em vez de ser destruído?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61944066,'Livro de Receitas de Nouvelles "Recettes de Nouvellez"',replace(replace('Enquanto você controlar um Card de Monstro "Nouvelles", todos os monstros com a face para cima que seu oponente controla são colocados em Posição de Ataque. \r\nSempre que um ou mais monstros forem oferecidos como Tributo pelo efeito de um Monstro de Ritual, seu oponente paga 850 PV. \r\nUma vez por turno, se você Invocar um ou mais Monstros de Ritual por Invocação-Especial (exceto durante a Etapa de Dano): você pode escolher 1 deles; adicione 1 card "Receita" ou "Nouvelles" do seu Deck à sua mão, exceto uma Magia Contínua e, se isso acontecer, aumente o Nível desse monstro em 1. \r\nVocê só pode ativar 1 "Livro de Receitas de Nouvelles "Recettes de Nouvellez"" por turno.','\r',char(13)),'\n',char(10)),'','','Adicionar à mão','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61948106,'O Segundo Chamado de Gottoms',replace(replace('Se você controlar um Monstro Sincro "Sabre-X": você pode escolher 2 monstros "Sabre-X" no seu Cemitério; Invoque os dois alvos por Invocação-Especial, ignorando suas condições de Invocação, mas mude o ATK deles para 0 e, além disso, destrua-os durante a Fase Final deste turno. \r\nVocê só pode ativar 1 "O Segundo Chamado de Gottoms" por turno. \r\nVocê não pode conduzir sua Fase de Batalha no turno em que ativar este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61950680,'Salvação do Emblemado',replace(replace('Bana 1 Card de Monstro "Centur-Ião" com a face para cima da sua Zona de Magias & Armadilhas e, depois, escolha 1 card que seu oponente controla; bana-o. \r\nSe este card Baixado sob o controle do seu dono for destruído ou banido por um efeito ativado do oponente: você pode colocar 2 monstros "Centur-Ião" com nomes diferentes da sua mão, do Deck, do Cemitério e/ou do banimento na sua Zona de Magias & Armadilhas como Armadilhas Contínuas com a face para cima. \r\nVocê só pode ativar 1 "Salvação do Emblemado" por turno.','\r',char(13)),'\n',char(10)),'Colocar com a face para cima','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61962135,'Ilusão Gloriosa',replace(replace('Ative este card ao escolher 1 monstro "Luminoso(a)" no seu Cemitério; Invoque o alvo por Invocação-Especial com a face para cima em Posição de Ataque. \r\nDurante cada uma das suas Fases Finais: envie os 2 cards do topo do seu Deck para o Cemitério. \r\nQuando este card deixar o campo, destrua o monstro. \r\nQuando o monstro deixar o campo, destrua este card.','\r',char(13)),'\n',char(10)),'Enviar o(s) 2 card(s) do topo do seu Deck para o Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61965407,'Purificação do Vácuo',replace(replace('Se você controlar um monstro que não seja um monstro "Infernoide", envie este card para o Cemitério. \r\nVocê só pode usar cada um desses efeitos de "Purificação do Vácuo" uma vez por turno.\r\n● Durante cada uma das suas Fases de Apoio do seu oponente: você pode escolher 1 monstro "Infernoide" no seu Cemitério; adicione-o à sua mão.\r\n● Durante cada uma das suas Fases de Apoio: você pode escolher 1 dos seus monstros "Infernoide" banidos; devolva-os para o Cemitério.','\r',char(13)),'\n',char(10)),'Usar o efeito?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61968753,'Embaralhar as Bolhas',replace(replace('Você só pode ativar este card quando existir um "Homem Bolha, o HERÓI do Elemento" no Campo com a face para cima. \r\nMude 1 "Homem Bolha, o HERÓI do Elemento" no seu Campo em Posição de Ataque com a face para cima e 1 monstro no Campo do seu adversário em Posição de Ataque com a face para cima, para a Posição de Defesa. \r\nOfereça como tributo o "Homem Bolha, o HERÓI do Elemento" que foi colocado na Posição de Defesa e Invoque, por Invocação Especial 1 monstro da sua mão que inclua "HERÓI do Elemento" no seu nome.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61976639,'Senha Secreta',replace(replace('Adicione 1 Magia/Armadilha "Live☆Gêmea" ou "Evil★Gêmea" do seu Deck à sua mão. \r\nSe você controlar um monstro "Ki-sikil" e controlar um monstro "Lil-la", em vez disso, você pode adicionar 1 monstro "Evil★Gêmea" do seu Deck à sua mão. \r\nVocê só pode ativar 1 "Senha Secreta" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(61980241,'Elzette da Floresta Branca',replace(replace('Você pode enviar 1 Magia/Armadilha da sua mão ou do campo para o Cemitério; Invoque este card por Invocação-Especial da sua mão e, depois, adicione 1 monstro "Floresta Branca" do seu Deck à sua mão, exceto "Elzette da Floresta Branca". \r\nDurante o turno do seu oponente, se um Mago Regulador de LUZ for Invocado por Invocação-Especial no seu campo, enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode adicionar este card à sua mão. \r\nVocê só pode usar cada efeito de "Elzette da Floresta Branca" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial da mão','Adicionar do Cemitério à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62000467,'Besta Gladiadora Dragases',replace(replace('2 monstros "Besta Gladiadora"	\r\nSe um monstro "Besta Gladiadora" que você controla atacar, ele não pode ser destruído nessa batalha e, além disso, seu oponente não pode ativar cards ou efeitos até o final da Etapa de Dano. \r\nNo final da Fase de Batalha, se este card batalhou: você pode devolver este card para o Deck Adicional; Invoque por Invocação-Especial 2 monstros "Besta Gladiadora" com nomes diferentes do seu Deck. \r\nVocê só pode usar este efeito de "Besta Gladiadora Dragases" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62002838,'Dragão da Evaporação Final de Trevas',replace(replace('Você pode banir 1 monstro Dragão de Nível 8 do seu Deck Adicional; Invoque este card por Invocação-Especial da sua mão e, além disso, você não pode Invocar por Invocação-Especial pelo resto deste turno, exceto monstros Dragão. \r\nVocê pode ativar 1 desses efeitos;\r\n● Invoque por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional, usando monstros da sua mão ou do campo.\r\n● Escolha 1 outro monstro em Posição de Ataque no campo; faça com que este card perca exatamente 500 de ATK/DEF e, se isso acontecer, destrua esse monstro.	\r\nVocê só pode usar cada efeito de "Dragão da Evaporação Final de Trevas" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial da mão','Invocação Fusão','Destruir um monstro','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62006866,'Cavaleiro Zubababa',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode ativar 1 desses efeitos;\r\n● Adicione 1 monstro "Zubaba" do seu Deck à sua mão, exceto "Cavaleiro Zubababa".	\r\nO Nível deste card se torna o Nível desse monstro adicionado.\r\n● Destrua 1 monstro de Nível 4 ou menos em Posição de Defesa que seu oponente controla.	\r\nSe este card for desassociado de um Monstro Xyz para ativar o efeito desse monstro: você pode adicionar 1 monstro "Gagaga" do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "Cavaleiro Zubababa" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar','Adicionar à mão','Efeito de busca','Destruir 1 monstro','','','','','','','','','','','','');
INSERT INTO texts VALUES(62007535,'Hordeum Ferro de Chifre Longo','Uma vez por turno, se este card foi Invocado por Invocação-Tributo ao oferecer como Tributo um ou mais monstros "Hordeum Ferro": Você pode pagar 1000 PV para escolher 1 monstro no campo; destrua o alvo.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62015408,'Ceifador Fantasma & Cerejas de Inverno',replace(replace('Se seu oponente controlar mais monstros que você (Efeito Rápido): você pode descartar este card; revele 1 card no seu Deck Adicional e, depois, olhe o Deck Adicional do seu oponente e, além disso, bana todos os cards no Deck Adicional dele com o mesmo nome que o card revelado. \r\nVocê só pode usar este efeito de "Ceifador Fantasma & Cerejas de Inverno" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62015409,'Ceifador Fantasma & Cerejas de Inverno',replace(replace('Se seu oponente controlar mais monstros que você (Efeito Rápido): você pode descartar este card; revele 1 card no seu Deck Adicional e, depois, olhe o Deck Adicional do seu oponente e, além disso, bana todos os cards no Deck Adicional dele com o mesmo nome que o card revelado. \r\nVocê só pode usar este efeito de "Ceifador Fantasma & Cerejas de Inverno" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62017867,'Samurai Superpesado Gigaluvas',replace(replace('Se este card for enviado para o Cemitério e você não tiver Cards de Magia/Armadilha no seu Cemitério: você pode olhar os 5 cards do topo do seu Deck e, depois, colocá-los no topo do Deck em qualquer ordem. \r\nQuando um monstro do oponente declarar um ataque direto: você pode banir este card do seu Cemitério; escave o card do topo do seu Deck e, se for um monstro "Samurai Superpesado", adicione-o à sua mão e, se isso acontecer, o ATK do monstro atacante se torna 0. \r\nCaso contrário, envie-o para o Cemitério.','\r',char(13)),'\n',char(10)),'Revelar o Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62022479,'Vínculo Marcado',replace(replace('Invoque por Invocação-Especial 1 "Caído de Arbaz" da sua mão, do Cemitério ou do banimento. \r\nDurante a Fase Final, se este card estiver no Cemitério porque foi enviado para lá para ativar o efeito de "Caído de Arbaz" neste turno: você pode Baixar este card. \r\nVocê só pode usar cada efeito de "Vínculo Marcado" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62023839,'Arqueiro Peixeborgue',replace(replace('Se este card estiver em seu Cemitério e você não controlar nenhum monstro durante qualquer uma das suas Fases Principais: você pode descartar 1 monstro de ÁGUA; Invoque este card por Invocação-Especial do seu Cemitério, mas, no começo da Fase de Batalha deste turno, destrua todos os monstros que você controla, exceto monstros de ÁGUA. \r\nVocê só pode usar o efeito de "Arqueiro Peixeborgue" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62034800,'Perfuradora Infinisteira',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode Invocar por Invocação-Especial 1 monstro Máquina de TERRA da sua mão em Posição de Defesa, exceto "Perfuradora Infinisteira". \r\nVocê pode escolher 1 outro monstro Máquina que você controla; até o final deste turno, os Níveis tanto desse monstro quanto deste card se tornam iguais aos Níveis originais combinados desses 2 monstros. \r\nVocê só pode usar cada efeito de "Perfuradora Infinisteira" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62038047,'Shiranui Ferreiro',replace(replace('Se este card for enviado do campo para o Cemitério como uma Matéria Sincro: você pode adicionar 1 card "Shiranui" do seu Deck à sua mão, exceto "Shiranui Ferreiro". \r\nVocê só pode usar este efeito de "Shiranui Ferreiro" uma vez por turno. \r\nSe este card for banido: você pode ativar este efeito; neste turno, monstros do Tipo Zumbi que você controla não podem ser destruídos em batalha.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62054060,'Sábio da Quietude','Se este card destruir um monstro do oponente em batalha, seu oponente não pode ativar Cards de Armadilha durante o próximo turno.','Restrição de ativação','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62070231,'Número 94: Cristalzero',replace(replace('2 monstros de ÁGUA de Nível 5	\r\nDurante o turno de qualquer duelista: você pode desassociar 1 Matéria Xyz deste card e, depois, escolher 1 monstro com a face para cima no campo; o ATK dele se torna metade do seu ATK atual até o final do seu turno.','\r',char(13)),'\n',char(10)),'Reduzir ATK pela metade','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62076252,'Urso de Laboratório',replace(replace('Se você controlar um monstro "Besta Gladiadora" Invocado por Invocação-Especial do Deck/Deck Adicional, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Urso de Laboratório" por Invocação-Especial uma vez por turno desta forma. \r\nVocê pode oferecer este card como Tributo e, depois, embaralhe 1 monstro "Besta Gladiadora" da sua mão ou do campo com a face para cima no Deck/Deck Adicional; Invoque por Invocação-Especial até 2 monstros "Besta Gladiadora" do seu Deck. \r\n(Isso é considerado uma Invocação-Especial pelo efeito de um monstro "Besta Gladiadora".) \r\nVocê só pode usar este efeito de "Urso de Laboratório" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial da mão','Invocar por Invocação Especial do Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62089826,'Luz Verdadeira',replace(replace('Seu oponente não pode escolher "Dragão Branco de Olhos Azuis" na sua Zona de Monstros como alvo de efeitos de card. \r\nSe este card com a face para cima for enviado da Zona de Magias & Armadilhas para o Cemitério: destrua todos os monstros que você controla. \r\nVocê só pode usar o seguinte efeito de "Luz Verdadeira" uma vez por turno. \r\nVocê pode ativar 1 desses efeitos;\r\n● Invoque por Invocação-Especial 1 "Dragão Branco de Olhos Azuis" da sua mão ou do Cemitério.\r\n● Baixe 1 Magia/Armadilha do seu Deck, que mencione "Dragão Branco de Olhos Azuis" em seu texto, com um nome diferente que o dos cards que você controla e no seu Cemitério.','\r',char(13)),'\n',char(10)),'Ativar o efeito escolhido','Invocação Especial','Baixar Magia/Armadilha','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62091148,'Salamandra com Corrente',replace(replace('Escolha 1 monstro de FOGO no campo; equipe este card a ele como um Card de Equipamento que concede a ele 700 de ATK e, depois, você pode colocar 1 Monstro de Efeito no campo com a face para baixo em Posição de Defesa. \r\nVocê pode banir este card do seu Cemitério; Invoque por Invocação-Fusão 1 Monstro de Fusão Guerreiro ou Dragão de FOGO do seu Deck Adicional, embaralhando suas matérias da sua mão, do campo e/ou do Cemitério no Deck, mas destrua-o durante a Fase Final. \r\nVocê só pode usar este efeito de "Salamandra com Corrente" uma vez por turno.','\r',char(13)),'\n',char(10)),'Efeito de Equipamento','Efeito de Fusão','Mudar 1 monstro no campo para Posição de Defesa com a face para baixo?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62098216,'Evil★Gêmeas Ki-sikil & Lil-la',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão ou do Cemitério) ao oferecer como Tributo 2 Monstros Link. \r\nSe este card for Invocado por Invocação-Especial: você pode ativar este efeito; se seu oponente controlar 3 ou mais cards, ele deve enviar cards para o Cemitério até controlar 2 cards. \r\nVocê só pode usar este efeito de "Evil★Gêmeas Ki-sikil & Lil-la" uma vez por turno. \r\nEnquanto você tiver um monstro "Ki-sikil" no seu Cemitério e tiver um monstro "Lil-la" no seu Cemitério, este card ganha 2200 de ATK/DEF.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62104532,'Magia de Aumento de Classe Réquiem de Os Cavaleiros Fantasmas',replace(replace('Escolha 1 monstro "Os Cavaleiros Fantasmas" ou "Dragão Xyz" no seu Cemitério ou banimento; Invoque-o por Invocação-Especial, mas negue seus efeitos e, depois, aplique o seguinte efeito.\r\n● Selecione 1 Monstro Xyz de TREVAS que você controla e Invoque por Invocação-Especial do seu Deck Adicional, 1 Monstro Xyz "Os Cavaleiros Fantasmas" ou "Dragão Xyz" que seja 1 Classe maior que a desse monstro, usando-o como matéria (isso é considerado uma Invocação-Xyz, transfira as matérias dele).	\r\nVocê só pode ativar 1 "Magia de Aumento de Classe Réquiem de Os Cavaleiros Fantasmas" por turno.','\r',char(13)),'\n',char(10)),'Ativar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62107612,'Andarilho Dimensional',replace(replace('Quando um monstro for banido pelo efeito de "Dragão de Fóton de Olhos das Galáxias": você pode enviar este card da sua mão para o Cemitério; cause 3000 de dano ao seu oponente. \r\nVocê só pode usar o efeito de "Andarilho Dimensional" uma vez por turno.','\r',char(13)),'\n',char(10)),'Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62107981,'Knospe, o HERÓI do Elemento',replace(replace('Sempre que este card causar Dano de Batalha ao oponente: Ele ganha 100 de ATK e perde 100 de DEF. \r\nEnquanto você controlar outro monstro "HERÓI do Elemento" com a face para cima, seu oponente não pode escolher este card como alvo de um ataque, e este card pode atacar seu oponente diretamente.','\r',char(13)),'\n',char(10)),'Alterar ATK/DEF','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62111090,'Golem de Terra @Ignister',replace(replace('1 monstro Ciberso + 1 Monstro Link	\r\nDepois que este card for Invocado por Invocação-Fusão, você não sofre dano pelo resto deste turno. \r\nSe este card atacar um monstro que foi Invocado por Invocação-Especial do Deck Adicional, este card ganha ATK igual ao seu ATK original apenas durante a Etapa de Dano. \r\nQuando este card for destruído em batalha: você pode escolher 1 monstro Ciberso no seu Cemitério, exceto "Golem de Terra @Ignister"; Invoque-o por Invocação-Especial. \r\nVocê só pode usar este efeito de "Golem de Terra @Ignister" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62113340,'Ragnarok, Dragão Sagrado','Um dragão lendário enviado por Deus. Se ficar zangado, o mundo inteiro afundar-se-á no mar.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62125438,'Portador Sincron',replace(replace('Durante sua Fase Principal, você pode Invocar por Invocação-Normal 1 monstro "Sincron" em adição à sua Invocação-Normal/Baixar (padrão). \r\n(Você só pode se aproveitar deste efeito uma vez por turno.) \r\nSe, enquanto você controlar este card, outro monstro "Sincron" for enviado para o seu Cemitério como matéria para a Invocação-Sincro de um Monstro Sincro Guerreiro ou Máquina: você pode Invocar por Invocação-Especial 1 "Ficha Sincron" (Máquina/TERRA/Nível 2/ATK 1000/DEF 0). \r\nVocê só pode usar este efeito de "Portador Sincron" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar pelo efeito de "Portador Sincron"','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62125439,'Ficha Sincron','Invocado por Especial com o efeito "Portador Sincron".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62133026,'Vernasílfide dos Campos Floridos',replace(replace('Seu oponente não pode escolher monstros "Vernasílfide" que você controla como alvo de efeitos de card. \r\nVocê pode descartar este card e 1 monstro ou card "Vernasílfide"; adicione 1 monstro de TERRA do seu Cemitério à sua mão, exceto "Vernasílfide dos Campos Floridos" e, depois, você pode Invocar por Invocação-Especial 1 monstro de TERRA do seu Cemitério e, além disso, você não pode ativar efeitos de monstros que não sejam de TERRA pelo resto deste turno. \r\nVocê só pode usar este efeito de "Vernasílfide dos Campos Floridos" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial do Cemitério?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62154416,'Mago da Frequência',replace(replace('Quando este card for Invocado por Invocação-Normal, coloque 1 Marcador de Magia nele (máx. 1). \r\nVocê pode remover 1 Marcador de Magia deste card para fazer com que 1 monstro com a face para cima que você controla ganhe 500 de ATK até a Fase Final.','\r',char(13)),'\n',char(10)),'Colocar Marcadores de Magia','Aumentar ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62156277,'Ponta de Lança da Cidade Cinzenta',replace(replace('Se "Obsidim, a Cidade Cinzenta" estiver na Zona do Campo, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Ponta de Lança da Cidade Cinzenta" por Invocação-Especial uma vez por turno desta forma. \r\nSe seu oponente controlar um monstro com 2800 ou mais de ATK: você pode oferecer este card como Tributo e, depois, escolha 1 card que seu oponente controla; devolva-o para a mão. \r\nVocê só pode usar este efeito de "Ponta de Lança da Cidade Cinzenta" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62161698,'Bexigas Ilusórias','Se um ou mais monstros foram destruídos durante este turno, enquanto você os controlava: escave os 5 cards do topo do seu Deck e, depois, você pode Invocar por Invocação-Especial 1 monstro "Camarartista" escavado e, além disso, embaralhe o resto dos cards no seu Deck.','Invocação Especial','Invocar por Invocação Especial um monstro "Camarartista"?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62171834,'Fantasmas do Espelho Onírico',replace(replace('Quando este card for ativado: você pode adicionar 1 monstro "Espelho Onírico" do seu Deck à sua mão. \r\nSe "Espelho Onírico da Alegria" estiver em uma Zona do Campo, todos os monstros que você controla ganham 500 de ATK/DEF. \r\nSe "Espelho Onírico do Terror" estiver em uma Zona do Campo, todos os monstros que seu oponente controla perdem 500 de ATK/DEF. \r\nVocê só pode ativar 1 "Fantasmas do Espelho Onírico" por turno.','\r',char(13)),'\n',char(10)),'Adicionar 1 monstro "Espelho Onírico" do seu Deck à sua mão?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62173132,'Susurrus dos Despojos do Pecado',replace(replace('Escolha 1 monstro Ilusão ou Mago que você controla; devolva esse monstro com a face para cima para a mão ou para o Deck Adicional e, depois, Invoque por Invocação-Especial 1 monstro Ilusão ou Mago do seu Cemitério ou banimento. \r\nSe este card for enviado para o Cemitério para ativar um efeito de monstro: você pode Baixar este card. \r\nVocê só pode usar cada efeito de "Susurrus dos Despojos do Pecado" uma vez por turno.','\r',char(13)),'\n',char(10)),'Retornar à mão/ao Deck Adicional e, depois, Invocar por Invocação Especial','Baixar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62180201,'A Perversa Raiz do Medo',replace(replace('Não pode ser Invocado por Invocação-Especial. \r\nDeve ser Invocado por Invocação-Normal/Baixado ao oferecer 3 monstros como Tributo. \r\nO ATK/DEF de todos os outros monstros no campo são diminuídos pela metade.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62188962,'Reino Vampiro',replace(replace('Monstros Zumbi ganham 500 de ATK apenas durante o cálculo de dano. \r\nUma vez por turno, quando um ou mais cards forem enviados do Deck do seu oponente para o Cemitério: escolha 1 card no campo; envie 1 monstro "Vampiro(a)" de TREVAS da sua mão ou do Deck para o Cemitério e, se isso acontecer, destrua o alvo.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62193699,'Ogro de Rocha da Gruta #2','Um golem formado por rochas, este monstro transforma seus inimigos em pedra e os mói até virarem pó.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62200831,'Estaleiro Naviushi Gunkan à Beira-Jantar',replace(replace('Uma vez por turno, se você Invocar por Invocação-Normal ou Especial um ou mais monstros "Gunkan", mesmo durante a Etapa de Dano: você pode colocar 1 card "Gunkan" do seu Deck no topo do seu Deck. \r\nUma vez por turno, se um ou mais monstros "Gunkan" com a face para cima que você controla que foram Invocados por Invocação-Especial do Deck Adicional forem enviados para o seu Cemitério por um card do oponente: ative este efeito; seu oponente paga PV exatamente igual à DEF desse monstro no Cemitério e, depois, você pode aplicar este efeito.\r\n● Invoque por Invocação-Especial 1 "Shari do Naviushi Gunkan" da sua mão e, depois, Invoque por Invocação-Especial 1 Monstro Xyz "Gunkan" do seu Deck Adicional, usando esse card que você controla como matéria. \r\n(Isso é considerado uma Invocação-Xyz.)','\r',char(13)),'\n',char(10)),'Escolha 1 card "Gunkan" do seu Deck e coloque-o no topo do seu Deck','Escolha o(s) card(s) para colocar no topo do Deck','Seu oponente paga PV','Invocação Especial?','','','','','','','','','','','','');
INSERT INTO texts VALUES(62201847,'Miutante M-05',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 monstro "Miutante" do seu Deck à sua mão, exceto "Miutante M-05". \r\nVocê pode oferecer este card como Tributo e, depois, bana 1 card da sua mão ou do campo com a face para cima; Invoque por Invocação-Especial 1 monstro da sua mão ou do Deck, de acordo com o card banido.\r\n● Monstro: "Besta Miutante"\r\n● Magia: "Névoa Miutante"\r\n● Armadilha: "Arsenal Miutante"\r\nVocê só pode usar cada efeito de "Miutante M-05" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62210247,'Rainha Lunar Elzaim','Uma criatura amável protegida pela lua. Sua cortina lunar pode bloquear praticamente qualquer ataque.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62219643,'Fantasma Encontra Garota - Uma Saga Shiranui de um Mayakashi Habilidoso',replace(replace('Ofereça como Tributo 1 Monstro Sincro ou Link "Mayakashi" ou "Shiranui"; nenhum duelista pode Invocar monstros por Invocação-Especial da mão, do Deck ou do Deck Adicional pelo resto deste turno. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 dos seus monstros Zumbi banidos; devolva-o para o Cemitério. \r\nVocê só pode usar 1 efeito de "Fantasma Encontra Garota - Uma Saga Shiranui de um Mayakashi Habilidoso" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62242678,'Abrasador Dragão Vermelho Arquidemônio Rei da Calamidade',replace(replace('2 Reguladores + 1 Monstro Sincro Dragão não-Regulador de TREVAS	\r\nQuando este card for Invocado por Invocação-Sincro: você pode ativar este efeito; pelo resto deste turno, seu oponente não pode ativar cards ou efeitos no campo. \r\nSeu oponente não pode ativar cards ou efeitos em resposta à ativação deste efeito. \r\nSe este card destruir um monstro em batalha: cause dano ao seu oponente igual ao ATK original desse monstro. \r\nSe este card em posse do seu dono for destruído por um card do oponente: você pode escolher 1 Monstro Sincro Dragão de TREVAS de Nível 8 ou menos no seu Cemitério; Invoque-o por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Não pode ativar','Dano de efeito','Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62256492,'Despertar dos Possuídos',replace(replace('Monstros que você controla ganham 300 de ATK para cada Atributo diferente que você controla. \r\nMonstros "Encantador(a)" e "Espírito-Possuído" que você controla não podem ser destruídos por efeitos de card. \r\nSe um ou mais monstros Mago com ATK original de 1850 forem Invocados por Invocação-Normal ou Especial no seu campo: compre 1 card. \r\nVocê só pode usar este efeito de "Despertar dos Possuídos" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62265044,'Ravina de Dragões',replace(replace('Uma vez por turno: você pode descartar 1 card e, depois, ative 1 desses efeitos;\r\n● Adicione 1 monstro "Dragunidade" de Nível 4 ou menos do seu Deck à sua mão.\r\n● Envie 1 monstro Dragão do seu Deck para o Cemitério.','\r',char(13)),'\n',char(10)),'Ativar 1 efeito','Adicionar 1 monstro "Dragunidade" à mão','Enviar 1 monstro Dragão para o Cemitério','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62271284,'Justiquebra','Quando um monstro do seu oponente declarar um ataque contra um Monstro Normal seu: destrua todos os monstros no campo, exceto Monstros Normais em Posição de Ataque.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62279055,'Cilindro Mágico','Quando um monstro do oponente declarar um ataque: escolha o monstro atacante; negue o ataque e, se isso acontecer, cause dano ao seu oponente igual ao ATK dele.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62279056,'Cilindro Mágico','Quando um monstro do oponente declarar um ataque: escolha o monstro atacante; negue o ataque e, se isso acontecer, cause dano ao seu oponente igual ao ATK dele.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62279666,'Corrupção do Legado Mundial',replace(replace('Uma vez por turno, se um Monstro Link com a face para cima que você controla for destruído em batalha ou deixar o campo devido a um efeito de card do oponente: você pode Invocar por Invocação-Especial 1 monstro "Legado Mundial" da sua mão ou do Deck em Posição de Defesa. \r\nVocê só pode controlar 1 "Corrupção do Legado Mundial".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62306203,'Motorista Salvagente',replace(replace('Se um Monstro Link Ciberso que você controla for destruído por um efeito de card do oponente enquanto este card estiver na sua mão ou no Cemitério (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial. \r\nVocê pode descartar 1 Magia e, depois, escolher 1 monstro Ciberso no seu Cemitério; Invoque-o por Invocação-Especial, mas ele não pode atacar diretamente neste turno. \r\nVocê só pode usar cada efeito de "Motorista Salvagente" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62312469,'Doriado Sombrio',replace(replace('Escala de Pêndulo = 5\r\n[ Efeito de Pêndulo ]\r\nTodos os monstros de TERRA, ÁGUA, FOGO e VENTO que você controla ganham 200 de ATK/DEF para cada Atributo diferente entre os monstros que você controla.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode selecionar 4 monstros do seu Deck (1 de TERRA, 1 de ÁGUA, 1 de FOGO e 1 de VENTO) e, depois, coloque-os no topo do Deck em qualquer ordem.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62314831,'Novo Mundo - Amritara',replace(replace('Ative apenas enquanto "Visas Starfrost" estiver no campo. \r\nUma vez por turno, se um ou mais monstros que você controla forem destruídos em batalha ou por um efeito de card e enviados para o Cemitério ou banidos: você pode ativar 1 desses efeitos;\r\n● Invoque por Invocação-Especial 1 desses monstros em Posição de Defesa.\r\n● 1 Regulador no campo ganha ATK igual à metade do ATK original de 1 desses monstros.\r\n● Embaralhe 1 desses monstros no Deck e, se isso acontecer, compre 1 card.\r\n● Embaralhe este card no Deck e, se isso acontecer, adicione 1 Magia de Campo do seu Cemitério à sua mão.','\r',char(13)),'\n',char(10)),'Ativar o efeito escolhido','Invocação Especial','Aumentar ATK','Reciclar e comprar','Recuperar a Magia de Campo','','','','','','','','','','','');
INSERT INTO texts VALUES(62315111,'Caçador Alienígena','Se este card destruir um monstro com um Marcador-A em batalha, ele pode atacar mais uma vez, em sequência.','Continuar atacando','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62318994,'Lótus de Samsara D',replace(replace('Você pode oferecer este card como Tributo; Invoque por Invocação-Especial 1 monstro "Yubel" do seu Deck. \r\nDurante o turno do seu oponente, quando um efeito de monstro for ativado, enquanto você controlar um monstro "Yubel" (Efeito Rápido): você pode oferecer este card como Tributo; o efeito ativado se torna "Destrua 1 monstro "Yubel" no campo". \r\nDurante sua Fase Final, se você controlar "Yubel" e este card estiver no seu Cemitério: você pode adicionar este card à sua mão ou Invocá-lo por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Lótus de Samsara D" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial do Deck','Efeito de modificar','Recuperar do Cemitério','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62320425,'Agido, o Sentinela Antigo',replace(replace('Se um ou mais cards forem enviados da mão ou do Deck para o Cemitério do seu oponente (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão e, depois, você pode Invocar por Invocação-Especial 1 monstro Fada de TERRA de Nível 4 do seu Cemitério, exceto "Agido, o Sentinela Antigo". \r\nSe este card for enviado da mão ou do Deck para o Cemitério: você pode ativar este efeito; cada duelista envia os 5 cards do topo do Deck dele para o Cemitério (ou todo o seu Deck, se tiver menos de 5) e, depois, se "Troca de Espírito" estiver no seu Cemitério, você pode enviar 5 cards adicionais do topo do Deck de qualquer duelista para o Cemitério. \r\nVocê só pode usar cada efeito de "Agido, o Sentinela Antigo" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invoque este card por Invocação Especial da sua mão','','Invocar por Invocação Especial um monstro do Cemitério?','','Enviar 5 card(s) do seu Deck para o Cemitério','Envie 5 card(s) do Deck do seu oponente para o Cemitério','Não fazer nada','','','','','','','','','');
INSERT INTO texts VALUES(62325062,'Buraco Armadilha da Adesão','Quando seu oponente Invocar um ou mais monstros: diminua pela metade o ATK original desses monstros.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62327910,'Guarda Poderoso','Um soldado máquina que foi desenvolvido como guarda. É feito de metal à prova de ferrugem.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62337487,'Baleia Fortaleza','Você pode Invocar este card por Invocação-Ritual com "Juramento da Baleia Fortaleza".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62340868,'Kazejin','Uma vez enquanto estiver com a face para cima no campo, durante o cálculo de dano do turno do seu oponente, se este card estiver sendo atacado (Efeito Rápido): você pode escolher o monstro atacante; o ATK do alvo se torna 0 apenas durante o cálculo de dano.','O ATK se torna 0','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62368221,'Ars Magna da Corrupção e Purificação',replace(replace('Você pode banir este card da sua mão; adicione 1 Magia/Armadilha "Ars Magna" do seu Deck à sua mão, também até o final do seu próximo turno, as 3 primeiras vezes que cada um dos seus Monstros Link "Patrono(a) do Poder" seria destruído por batalha todo turno, ele não é destruído.\r\nSe um ou mais Monstros Link e/ou Xyz são Invocados por Invocação-Especial enquanto este card está banido: você pode Invocar este card por Invocação-Especial.\r\nVocê pode escolher Magias/Armadilhas no campo até o número de Monstros Link "Patrono(a) do Poder" que você controla; bana-os.\r\nVocê só pode usar cada um dos efeitos de "Ars Magna da Corrupção e Purificação" uma vez por turno.','\r',char(13)),'\n',char(10)),'Efeito de busca','Invocação Especial','Efeito de banimento','O efeito de "Ars Magna da Corrupção e Purificação" está sendo aplicado.','','','','','','','','','','','','');
INSERT INTO texts VALUES(62370023,'Efeito Boneco de Neve',replace(replace('Escolha 1 monstro com a face para cima que você controla; até o final deste turno, ele ganha ATK igual ao ATK original combinado dos outros monstros que você controla. \r\nEle não pode atacar diretamente durante o turno em que você ativou este card. \r\nVocê só pode ativar 1 "Efeito Boneco de Neve" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62376646,'Revanche Gouki',replace(replace('Escolha 2 monstros "Gouki" com Níveis diferentes no seu Cemitério; Invoque-os por Invocação-Especial em Posição de Defesa. \r\nVocê só pode ativar 1 "Revanche Gouki" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62379337,'Bruxa Violeta','Se este card for destruído em batalha e enviado para o Cemitério: adicione 1 monstro do Tipo Planta com 1500 ou menos de DEF do seu Deck à sua mão.','Procurar no Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62383431,'Keurse, a Luz Ogdoádica',replace(replace('Se este card estiver no seu Cemitério: você pode oferecer 1 monstro como Tributo; Invoque este card por Invocação-Especial e, depois, seu oponente pode Invocar por Invocação-Especial 1 monstro do Cemitério dele, mas negue seus efeitos. \r\nSe este card for Invocado por Invocação-Especial: você pode escolher 1 monstro "Ogdoádico(a)" de Nível 4 ou menos no seu Cemitério; Invoque-o por Invocação-Especial, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar cada efeito de "Keurse, a Luz Ogdoádica" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Invocar por Invocação Especial um monstro do Cemitério com seus efeitos negados?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62393472,'Fântaso, o Amigo do Espelho Onírico',replace(replace('Se este card for Invocado por Invocação-Especial pelo efeito de um monstro "Espelho Onírico": você pode escolher 1 monstro "Espelho Onírico" de Nível 8 ou menos no seu Cemitério, exceto "Fântaso, o Amigo do Espelho Onírico"; Invoque-o por Invocação-Especial em Posição de Defesa. \r\nDurante a Fase Principal ou de Batalha, se "Espelho Onírico do Terror" estiver em uma Zona do Campo (Efeito Rápido): você pode oferecer este card como Tributo; Invoque por Invocação-Especial 1 "Fântaso, o Inimigo do Espelho Onírico" do seu Deck. \r\nVocê só pode usar cada efeito de "Fântaso, o Amigo do Espelho Onírico" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62397231,'Hyozanryu','Um dragão criado a partir de um diamante maciço, e que brilha com uma luz ofuscante.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62403074,'Rhaimundos da Espada Vermelha','Armado com a Espada das Chamas Carmesim, este guerreiro pode prender um monstro com amarras ardentes.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62405028,'Nauya, o Remanescente Ogdoádico',replace(replace('Você pode enviar este card da sua mão para o Cemitério; envie 1 monstro Réptil de LUZ do seu Deck para o Cemitério. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 Magia/Armadilha "Ogdoádico(a)" do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "Nauya, o Remanescente Ogdoádico" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62411042,'Ibicella Lutea',replace(replace('Não pode ser destruído em batalha enquanto você controlar outro monstro. \r\nNenhum duelista pode escolher Magias/Armadilhas com a face para cima que você controla como alvo de efeitos de card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62411811,'Carniçal das Sombras do Labirinto',replace(replace('Você pode descartar este card; adicione 1 card "Paredes do Labirinto" do seu Deck à sua mão. \r\nNo começo da Etapa de Dano, se um monstro do seu oponente batalhar, enquanto você controlar um card "Paredes do Labirinto": você pode banir este card do seu Cemitério; destrua o monstro do oponente. \r\nVocê só pode usar cada efeito de "Carniçal das Sombras do Labirinto" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62420419,'Reshef, o Ser das Trevas',replace(replace('Este card só pode ser Invocado por Invocação-Ritual com o Card de Magia de Ritual "Ritual Final dos Anciãos". \r\nDescarte 1 Card de Magia da sua mão. \r\nGanhe o controle de 1 monstro no Campo do seu adversário até à End Phase. \r\nVocê pode usar este efeito apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Tomar controle','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62434031,'Cavaleiroso Silvestre',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode escavar o card do topo do seu Deck e, se ele for um monstro do Tipo Planta, envie-o para o Cemitério. \r\nCaso contrário, coloque-o no fundo do seu Deck. \r\nSe este card for escavado do Deck e enviado para o Cemitério por um efeito de card: você pode selecionar 1 card "Silvestre" do seu Deck e colocá-lo no topo do seu Deck.','\r',char(13)),'\n',char(10)),'Revelar o Deck','Colocar no topo do Deck','Escolha um card cujo nome contenha "Silvestre"','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62437430,'Fossa das Profundezas de Outra Dimensão',replace(replace('Quando este card resolver: Bana 1 monstro de ÁGUA da sua mão, Cemitério ou com a face para cima no seu campo. \r\nDepois, quando este card com a face para cima no campo for destruído: Invoque por Invocação-Especial o monstro banido no seu lado do campo.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62437709,'Alienígena Cinzento',replace(replace('VIRE: Coloque 1 Marcador-A em 1 monstro com a face para cima no lado do campo do oponente. \r\n(Se um monstro com um Marcador-A batalhar com um monstro "Alienígena", ele perde 300 de ATK e DEF para cada Marcador-A apenas durante o cálculo de dano). \r\nApós este card ser virado com a face para cima, quando ele for destruído em batalha e enviado ao Cemitério, compre 1 card.','\r',char(13)),'\n',char(10)),'Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62472614,'Peste',replace(replace('Só pode ser equipado a um monstro do Tipo Guerreiro, Tipo Besta-Guerreira ou Tipo Mago. \r\nSeu ATK se torna 0. \r\nDurante cada uma das suas Fases de Apoio, cause 500 de dano ao controlador do monstro equipado.','\r',char(13)),'\n',char(10)),'Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62473983,'Chefe do Coveiro',replace(replace('Você só pode controlar 1 "Chefe do Coveiro" com a face para cima. \r\nSeu Cemitério não é afetado por "Necro-Vale". \r\nQuando este card for Invocado por Invocação-Tributo: você pode escolher 1 monstro "do Coveiro" no seu Cemitério; Invoque o alvo por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62476197,'Achacha Chanbara','Durante o turno de qualquer duelista, quando um card ou efeito for ativado que causará dano quando ele resolver: Você pode Invocar este card por Invocação-Especial da sua mão e, se isso acontecer, cause 400 de dano ao seu oponente.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62476815,'Golem Gogogo','Uma vez por turno, este card em Posição de Defesa não pode ser destruído em batalha.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62480168,'Nascente Ardente Amazoness',replace(replace('Quando este card for ativado: você pode pegar 1 monstro "Amazoness" do seu Deck e adicioná-lo à sua mão ou (se for um Monstro Pêndulo) coloque-o na sua Zona de Pêndulo. \r\nQuando você sofrer dano de batalha enquanto você controlar um Card de Monstro "Amazoness": você pode ganhar PV igual ao dano que você sofreu. \r\nVocê só pode usar este efeito de "Nascente Ardente Amazoness" uma vez por turno.','\r',char(13)),'\n',char(10)),'Escolher um card do Deck?','Adicionar à mão','Colocar na Zona de Pêndulo','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62481203,'Festival Trapestrela',replace(replace('Invoque por Invocação-Especial 2 "Ficha Trapestrela" (Fada/LUZ/Nível 1/ATK 0/DEF 0). \r\nSe um ou mais monstros "Trapestrela" que você controla que foram Invocados por Invocação-Especial do Deck Adicional seriam destruídos em batalha ou por um efeito de card, em vez disso, você pode banir este card do seu Cemitério. \r\nVocê não pode Invocar monstros por Invocação-Normal ou Especial no turno em que ativar este card, exceto monstros "Trapestrela". \r\nVocê só pode ativar 1 "Festival Trapestrela" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62481204,'Ficha Trapestrela','Invocado por Especial com o efeito "Apresentação ao Vivo Trapestrela" ou um card relacionado.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62487836,'Uivo Branco','Se você controlar um monstro de ÁGUA: escolha 1 Magia no Cemitério do seu oponente; bana-a e, se isso acontecer, pelo resto deste turno negue todos os efeitos de Magia no campo do seu oponente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62499965,'Z-ONE','Se este card Baixado for destruído e enviado para o Cemitério: escolha 1 Magia Contínua ou Magia de Campo no seu Cemitério; adicione-a à sua mão.','Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62503746,'Senko, a Estrela Céuraio',replace(replace('Se um ou mais monstros de TERRA forem Invocados por Invocação-Normal ou Especial no seu campo (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 monstro Guerreiro de Nível 5 ou mais que você controla e 1 monstro em Posição de Ataque que seu oponente controla; seu monstro perde exatamente 1500 de ATK e, se isso acontecer, destrua o monstro do oponente. \r\nVocê só pode usar cada efeito de "Senko, a Estrela Céuraio" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invoque este card por Invocação Especial da sua mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62514770,'Dragão Labradorite','Os antigos comparavam essa criatura estimada ao reflexo da luz da lua sobre as águas. Um portador da harmonia, das lembranças de glórias passadas, capaz de amolecer o coração até dos homens mais ambiciosos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62517849,'Número 39: Dublê da Utopia',replace(replace('2 monstros de Nível 4	\r\n(Efeito Rápido): você pode desassociar 1 matéria deste card; adicione 1 "O Dobro ou Nada!" do seu Deck à sua mão e, depois, Invoque por Invocação-Especial do seu Deck Adicional, 1 Monstro Xyz "Utopia", exceto "Número 39: Dublê da Utopia", usando este card com a face para cima que você controla como matéria e, se isso acontecer, o ATK dele se torna o dobro, mas ele não pode atacar diretamente. \r\n(Isso é considerado uma Invocação-Xyz. Transfira suas matérias para o monstro Invocado.) \r\nVocê só pode usar este efeito de "Número 39: Dublê da Utopia" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62528292,'Saga dos Guerreiros Antigos - Ventos do Sudeste',replace(replace('Você deve enviar este card para o Cemitério durante sua 2ª Fase de Apoio depois da ativação. \r\nUma vez por turno, durante sua Fase Principal: lance uma moeda e se o resultado for cara, envie este card para o Cemitério. \r\nSe este card for enviado da Zona de Magias & Armadilhas para o Cemitério: você pode ativar este efeito; neste turno, seu oponente não pode ativar cards ou efeitos em resposta à ativação dos seus cards e efeitos "Guerreiros Antigos" e, além disso, até o final do turno, todos os Monstros de Efeito "Guerreiros Antigos" que você controla atualmente ganham este efeito.\r\n● Quando este card declarar um ataque: você pode destruir 1 card que seu oponente controla.','\r',char(13)),'\n',char(10)),'','','','O efeito de "Saga dos Guerreiros Antigos - Ventos do Sudeste" está sendo aplicado.','','','','','','','','','','','','');
INSERT INTO texts VALUES(62530723,'Sussurros do Legado Mundial',replace(replace('Quando este card for ativado: você pode escolher 1 monstro de Nível 5 ou mais no campo; ele ganha 1000 de ATK/DEF até o final deste turno. \r\nNegue qualquer efeito de Magia do oponente que ative na mesma coluna que um monstro "Mekk-Cavaleiro" que você controla.','\r',char(13)),'\n',char(10)),'Aumentar o ATK de um monstro?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62541668,'Número 77: Os Sete Pecados',replace(replace('2 monstros de Nível 12	\r\nVocê também pode Invocar este card por Invocação-Xyz ao usar um Monstro Xyz de TREVAS de Classe 10 ou 11 que você controla como matéria. \r\n(Transfira as matérias dele para este card.) \r\nSe Invocado desta forma, o seguinte efeito não pode ser ativado neste turno. \r\nUma vez por turno: você pode desassociar 2 matérias deste card; bana tantos monstros Invocados por Invocação-Especial que seu oponente controla quanto possível e, depois, associe 1 desses monstros banidos a este card como matéria. \r\nSe este card com a face para cima no campo seria destruído em batalha ou por um efeito de card, em vez disso, você pode desassociar 1 matéria deste card.','\r',char(13)),'\n',char(10)),'Escolha um Monstro Xyz de TREVAS de Classe 10/11','Banir todos os monstros Invocados por Invocação Especial que seu oponente controla','','Desassociar 1 matéria em vez de ser destruído?','','','','','','','','','','','','');
INSERT INTO texts VALUES(62542673,'HERÓI do Destino – Liege da Condenação',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 monstro que seu oponente controla; bana-o até a próxima Fase de Apoio.\r\nVocê pode enviar 1 monstro "HERÓI do Destino" do seu Deck ao Cemitério; adicione 1 "Prisão da Torre do Relógio" ou "Prisão da Torre do Relógio da Cidade – Cidade Sombria" do seu Deck ou Cemitério à sua mão. \r\nVocê não pode Invocar por Invocação-Especial pelo resto deste turno, exceto monstros "HERÓI" de TREVAS.\r\nVocê só pode usar cada um dos efeitos de "HERÓI do Destino – Liege da Condenação" uma vez por turno.','\r',char(13)),'\n',char(10)),'Banir','Adicionar à mão','Banir até a próxima Fase de Apoio','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62543393,'Lekunga','Você pode banir 2 monstros de ÁGUA do seu Cemitério; Invoque por Invocação-Especial 1 "Ficha de Lekunga" (Tipo Planta/ÁGUA/Nível 2/ATK 700/DEF 700) em Posição de Ataque.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62543394,'Ficha de Lekunga','Invocado por Especial com o efeito "Lekunga".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62560742,'T.G. Reciprolibélula',replace(replace('1 Regulador + 1 monstro não-Regulador	\r\nUma vez por turno: você pode escolher 1 outro Monstro Sincro "T.G." que você controla; envie-o para o Cemitério e, depois, se todos os Monstros Sincro que foram usados para a Invocação-Sincro dele estiverem no seu Cemitério, você pode Invocar todos eles por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Des-Sincro','Invocar a Matéria por Invocação Especial?','Escolha 1 Monstro Sincro "T.G."','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62587693,'Deus X-Krawler',replace(replace('Quando seu oponente ativar um card ou efeito que escolha como alvo este monstro com a face para baixo (Efeito Rápido): você pode colocar este card com a face para cima em Posição de Defesa; negue a ativação e, se isso acontecer, destrua esse card. \r\nDepois que este card foi virado com a face para cima, enquanto ele estiver na Zona de Monstros, negue todos os efeitos de monstro ativados no campo do seu oponente. \r\nSe este card no campo for destruído em batalha ou por um efeito de card: você pode adicionar, do seu Deck à sua mão, 1 monstro de Nível 9 com um Tipo e Atributo originais diferentes que o deste card. \r\nVocê só pode usar este efeito de "Deus X-Krawler" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62592805,'Noir Epurrely',replace(replace('2 monstros de Nível 2	\r\nUma vez por turno: você pode descartar 1 card e, depois, escolha 1 card que seu oponente controla, ou até 2 se este card tiver "Sonolenta Lembrança Purrely" como matéria; devolva esse(s) card(s) para a mão. \r\nAté três vezes por turno, quando você ativar um Card de Magia Rápida "Purrely" (Efeito Rápido): você pode associar esse card no campo a este card como matéria e, depois, você pode Baixar 1 Armadilha "Purrely" diretamente do seu Deck.','\r',char(13)),'\n',char(10)),'Retornar um card do seu oponente para a mão','Associar a Magia Rápida ativada a este card','Baixar um Card de Armadilha do seu Deck?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62606805,'Método da Mente',replace(replace('Se este card que você controla seria usado como Matéria Sincro para um monstro Psíquico, você pode considerá-lo como um não-Regulador. \r\nVocê só pode usar 1 dos seguintes efeitos de "Método da Mente" por turno e apenas uma vez por turno. \r\nSe este card for Invocado por Invocação-Normal, ou Invocado por Invocação-Especial por um efeito de monstro: você pode pagar 2000 PV; adicione 1 Magia Normal ou Rápida "Teleporte" do seu Deck ou Cemitério à sua mão. \r\nSe este card for banido: você pode pagar 1000 PV; Invoque-o por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62623659,'Construção Zexal',replace(replace('Revele 1 card na sua mão e, se isso acontecer, adicione 1 dos seguintes cards do seu Deck à sua mão e, depois, embaralhe o card revelado no Deck.\r\n● Monstro "ZW -"\r\n● Monstro "ZS -"\r\n● Magia/Armadilha "Zexal"\r\n● Magia "Magia de Aumento de Classe"\r\n● Magia "Magia de Redução de Classe"\r\nVocê só pode ativar 1 "Construção Zexal" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62624486,'Dian, o HERÓI Mascarado',replace(replace('Deve ser Invocado por Invocação-Especial com "Mudar a Máscara". 	\r\nQuando este card destruir um monstro do oponente em batalha e enviá-lo para o Cemitério: você pode Invocar por Invocação-Especial 1 monstro "HERÓI" de Nível 4 ou menos do seu Deck.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62632427,'Negociação de Margem',replace(replace('Seu oponente pode descartar 1 card para negar este efeito, caso contrário, os dois duelistas olham o Deck do seu oponente e selecionam 1 card e, depois, adicionam à sua mão o card do seu próprio Deck selecionado pelo seu oponente. \r\nVocê só pode ativar 1 "Negociação de Margem" por turno.','\r',char(13)),'\n',char(10)),'','Descartar 1 card para negar "Negociação de Margem"?','Escolha o card a ser adicionado à mão do seu oponente','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62633180,'Um Assalto ao Quartel','Escolha 1 monstro que você controla; destrua-o e, depois, envie 2 cards do topo do Deck do seu oponente para o Cemitério.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62645025,'Os Cavaleiros Fantasmas do Imãnel Errôneo',replace(replace('Quando um monstro do oponente declarar um ataque: negue o ataque e, depois, Invoque este card por Invocação-Especial em Posição de Ataque como um Monstro de Efeito (Guerreiro/TREVAS/Nível 2/ATK 0/DEF 0) com o seguinte efeito.	\r\n(Este card NÃO é considerado como uma Armadilha.)\r\n● (Efeito Rápido): você pode enviar este card e 1 card com a face para cima que você controla para o Cemitério (seja um monstro "Os Cavaleiros Fantasmas" ou uma Magia/Armadilha Contínua "Cavaleiros Fantasmas"); compre 2 cards.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62651957,'Cabeça de Canhão X','Um monstro com um poderoso tambor de canhões, capaz de integrar os seus ataques. Ele ataca de muitas maneiras, combinando-se e separando-se de outros monstros.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62671448,'Mestre Batráquio','Um sapo eremita que existe há milhares de anos, ataca com girinos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62681049,'Ventos Vertiginosos da Vila de Yosen',replace(replace('Ative este card apenas se você controlar um monstro "Yosenju" de Nível 6 ou mais. \r\nEnquanto você tiver um card "Yosenju" na sua Zona de Pêndulo, se um monstro seria devolvido do campo para a mão por um efeito de card, em vez disso, embaralhe-o no Deck, a não ser que ele seja um monstro "Yosenju".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62694833,'Irmandade do Punho de Fogo - Carneiro',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode descartar 1 card e, depois, escolha 1 Magia/Armadilha "Formação de Fogo" que você controla; Baixe 1 Magia/Armadilha "Formação de Fogo" com um nome diferente diretamente do seu Deck. \r\nSe este card for Invocado por Invocação-Especial pelo efeito de um monstro "Punho de Fogo": você pode Baixar 1 Magia/Armadilha "Formação de Fogo" diretamente do seu Deck, com um nome diferente que o dos cards no seu Cemitério. \r\nVocê só pode usar cada efeito de "Irmandade do Punho de Fogo - Carneiro" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62701967,'Jurrac Tyrannus',replace(replace('Você pode oferecer como Tributo 1 monstro Dinossauro; este card ganha 500 de ATK. \r\nSe este card destruir um monstro do oponente em batalha e enviá-lo para o Cemitério: este card ganha 300 de ATK.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62706865,'Draconet','Quando este card for Invocado por Invocação-Normal: você pode Invocar por Invocação-Especial 1 Monstro Normal de Nível 2 ou menos da sua mão ou do Deck em Posição de Defesa.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62709239,'Os Cavaleiros Fantasmas da Espada Quebrada',replace(replace('2 monstros de Nível 3	\r\nUma vez por turno: você pode desassociar 1 matéria deste card e, depois, escolha 1 card que você controla e 1 card que seu oponente controla; destrua-os. \r\nSe este card Invocado por Invocação-Xyz for destruído: você pode escolher 2 monstros "Os Cavaleiros Fantasmas" com o mesmo Nível no seu Cemitério; Invoque-os por Invocação-Especial e aumente o Nível deles em 1 e, além disso, você não pode Invocar por Invocação-Especial pelo resto deste turno, exceto monstros de TREVAS.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62714453,'Ursártico Estrela Polar',replace(replace('Não pode ser Invocado por Invocação-Sincro. 	\r\nDeve ser Invocado por Invocação-Especial (do seu Deck Adicional) ao enviar para o Cemitério 2 monstros que você controla com 1 Nível de diferença (1 Regulador e 1 não-Regulador). \r\nVocê pode oferecer como Tributo este card e 1 monstro "Ursártico(a)" de Nível 8 da sua mão ou do campo; Invoque por Invocação-Especial 1 Monstro Sincro "Ursártico(a)" de Nível 7 do seu Deck Adicional, ignorando suas condições de Invocação e, se isso acontecer, ele ganha este efeito.\r\n● Seu oponente não pode ativar os efeitos de monstros com um Nível, que foram Invocados por Invocação-Especial do Deck Adicional.','\r',char(13)),'\n',char(10)),'','O efeito de "Ursártico Estrela Polar" está sendo aplicado.','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62729173,'Genoma Hordeum Ferro','Este card pode ser considerado como 2 Tributos para a Invocação-Tributo de um monstro "Hordeum Ferro".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62742651,'Chutador Axônico Blindado',replace(replace('Se você controlar um monstro do Tipo Psíquico com a face para cima, você pode Invocar este card por Invocação-Normal sem oferecer Tributo. \r\nSe este card destruir um monstro do oponente em batalha, você sofre dano igual à metade do ATK do monstro destruído. \r\nDepois, você pode Invocar por Invocação-Especial 1 monstro do seu Cemitério com ATK menor ou igual ao dano que você sofreu.','\r',char(13)),'\n',char(10)),'Invocação Normal sem Tributo','Causar dano','Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62753201,'Refrigerar Callibre',replace(replace('Ofereça como Tributo 1 monstro "Foguette" e, depois, escolha 1 Monstro Link "Callibre" que você controla; equipe-o com este card. \r\nSe este card for equipado a um monstro por este efeito, o monstro equipado ganha este efeito.\r\n● Uma vez por turno (Efeito Rápido): você pode escolher 1 monstro que você controla; ele não pode ser destruído em batalha ou por um efeito de card neste turno.','\r',char(13)),'\n',char(10)),'Proteção adicional (Refrigerar Callibre)','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62762898,'Dragão Papagaio','Um dragão dos desenhos animados que é mais perigoso do que aparenta.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62767644,'Inferno do Cinzento',replace(replace('Quando este card for ativado: você pode colocar 1 "Obsidim, a Cidade Cinzenta" do seu Deck, com a face para cima em qualquer Zona do Campo. \r\nVocê pode escolher 1 card com a face para cima que seu oponente controla e 1 monstro Piro de TREVAS de Nível 8 ou mais no seu Cemitério; envie esse card no campo para o Cemitério e, se isso acontecer, Invoque por Invocação-Especial esse outro monstro do seu Cemitério no campo do seu oponente em Posição de Defesa. \r\nVocê só pode usar este efeito de "Inferno do Cinzento" uma vez por turno. \r\nVocê só pode ativar 1 "Inferno do Cinzento" por turno.','\r',char(13)),'\n',char(10)),'Ativar','Invocação Especial','Colocar "Obsidim, a Cidade Cinzenta"?','Colocá-lo no seu campo?','','','','','','','','','','','','');
INSERT INTO texts VALUES(62777823,'CONTER!',replace(replace('(Este card deve ser sempre considerado como um card "ÁS-Resgate".)	\r\nSe você controlar um monstro "ÁS-Resgate": escolha 1 Monstro de Efeito que seu oponente controla; neste turno, esse Monstro de Efeito não pode atacar e, além disso, seus efeitos são negados. \r\nSe você controlar "ÁS-Resgate Hidrante" na resolução deste efeito, esse monstro também não pode ser usado como matéria para uma Invocação-Fusão, Sincro, Xyz ou Link neste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62782218,'Condutor de Crâneos',replace(replace('Se este card estiver com a face para cima no campo no final da Fase de Batalha: destrua este card com a face para cima. \r\nVocê pode enviar este card da sua mão para o Cemitério; Invoque por Invocação-Especial até 2 monstros do Tipo Zumbi da sua mão cujo ATK combinado seja exatamente 2000.','\r',char(13)),'\n',char(10)),'Destruir','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62784717,'Passeio da Perdição',replace(replace('Durante a Fase de Apoio do seu oponente, lance uma moeda.\r\n● Cara: Seu oponente não pode Invocar por Invocação-Normal ou Invocação-Virar até a Fase Final.\r\n● Coroa: Você não pode Invocar por Invocação-Normal ou Invocação-Virar durante seu próximo turno.','\r',char(13)),'\n',char(10)),'Jogar uma moeda','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62793020,'Mão do Mistério','Este monstro distorce a realidade e ocupa o espaço entre dimensões para atacar seus inimigos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62803464,'Aussa, a Canalizadora da Terra',replace(replace('(Este card deve ser sempre considerado como um card "Encantador(a)".)	\r\nVocê pode descartar este card e 1 outro monstro de TERRA; adicione, do seu Deck à sua mão, 1 monstro de TERRA com 1850 ou menos de ATK, cujo Tipo original seja o mesmo que um dos monstros descartados e, além disso, você não pode ativar os efeitos de monstros que não sejam de TERRA pelo resto deste turno. \r\nQuando um monstro de TERRA seu for destruído em batalha: você pode Invocar este card por Invocação-Especial da sua mão. \r\nVocê só pode usar cada efeito de "Aussa, a Canalizadora da Terra" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62829077,'Estrada da Esperança Radiante',replace(replace('Escolha 3 monstros no seu Cemitério; Invoque os 3 por Invocação-Especial, mas seus efeitos são negados. \r\nImediatamente depois de resolver este efeito, Invoque por Invocação-Xyz 1 Monstro Xyz "Utopia" ou "Utópico" usando apenas esses 3 monstros. \r\nVocê não pode Invocar outros monstros por Invocação-Especial durante o turno em que ativar este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62834295,'Einsatz Orcustrado',replace(replace('Se seu oponente Invocar um ou mais monstros por Invocação-Normal ou Especial (exceto durante a Etapa de Dano): você pode pegar 1 monstro "Orcust" ou "Legado Mundial" da sua mão ou do Deck e enviá-lo para o Cemitério ou bani-lo. \r\nVocê só pode usar este efeito de "Einsatz Orcustrado" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Escolha o monstro para enviar para o Cemitério ou banir','Enviar para o Cemitério?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62835876,'Bem & Mal no Abismo Ardente',replace(replace('Este card é usado para Invocar "Malacoda, Senhor Inferior do Abismo Ardente" por Invocação-Ritual. \r\nVocê também deve oferecer como Tributo monstros da sua mão ou campo cuja soma dos Níveis seja igual a 6 ou mais. \r\nDurante sua Fase Principal, exceto no turno em que este card foi enviado para o Cemitério: você pode banir este card do seu Cemitério e enviar 1 monstro "Abismo Ardente" da sua mão para o Cemitério; adicione 1 card "Abismo Ardente" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Bem & Mal no Abismo Ardente" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62849088,'A Espadalma Iris',replace(replace('Durante a Fase Principal, se um monstro cujos efeitos foram negados estiver no campo (Efeito Rápido): você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe seu oponente Invocar um ou mais monstros por Invocação-Especial (exceto durante a Etapa de Dano): você pode ativar 1 desses efeitos de acordo com de onde eles foram Invocados por Invocação-Especial;\r\n● Mão: Invoque por Invocação-Especial 1 monstro da sua mão.\r\n● Deck: Compre 2 cards.\r\n● Deck Adicional: Destrua 1 desses monstros Invocados por Invocação-Especial do Deck Adicional.	\r\nVocê só pode usar cada efeito de "A Espadalma Iris" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Ativar o efeito escolhido','Invoque por Invocação Especial 1 monstro da sua mão','Compre 2 card(s)','Destrua o monstro Invocado por Invocação Especial do Deck Adicional','','','','','','','','','','','');
INSERT INTO texts VALUES(62850093,'Frieira Circumpolar Cataclísmica',replace(replace('Se um ou mais monstros de ÁGUA com a face para cima que você controla forem destruídos em batalha ou por um efeito de card do oponente: você pode Invocar este card por Invocação-Especial da sua mão e, depois, você pode enviar 1 card aleatório da mão do seu oponente para o Cemitério. \r\nVocê só pode usar este efeito de "Frieira Circumpolar Cataclísmica" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Enviar para o Cemitério 1 card aleatório da mão do seu oponente?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62867251,'Luz da Intervenção',replace(replace('Enquanto este card estiver no campo, Cards de Monstro não podem ser Baixados ou virados com a face para baixo. \r\nSe um Card de Monstro seria Baixado, ele deve ser Invocado por Invocação-Normal com a face para cima em Posição de Defesa.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62868900,'Escudo-D',replace(replace('Quando um monstro "HERÓI do Destino" em Posição de Ataque que você controla for escolhido como alvo de um ataque: Escolha-o; mude-o para Posição de Defesa e o equipe com este card. \r\nO monstro equipado não pode ser destruído em batalha.','\r',char(13)),'\n',char(10)),'Equipar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62873545,'Supremo Cavaleiro Mestre dos Dragões',replace(replace('"Soldado do Lustro Negro" + "Dragão Definitivo de Olhos Azuis"	\r\nDeve ser Invocado por Invocação-Fusão. \r\nEste card ganha 500 de ATK para cada monstro Dragão que você controla, exceto este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62878208,'Disparo de Equipamento',replace(replace('Ative apenas durante a Fase de Batalha. \r\nSelecione 1 Card de Equipamento equipado a um monstro com a face para cima em Posição de Ataque que você controla, e selecione 1 monstro com a face para cima em Posição de Ataque que seu oponente controla. \r\nEquipe esse monstro com o Card de Equipamento selecionado. \r\nDepois, conduza a batalha entre seu monstro anteriormente equipado e o monstro elecionado (outros efeitos não podem ser ativados durante esta batalha).','\r',char(13)),'\n',char(10)),'Escolha o Card de Equipamento para equipar ao seu oponente','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62880279,'Guerreiro Dodododo',replace(replace('Você pode enviar 1 monstro "Dododo" do seu Deck para o Cemitério; Invoque este card por Invocação-Especial da sua mão (seu Nível se torna 4 e, além disso, seu ATK se torna 1800) e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto Monstros Xyz. \r\nSe este card for desassociado de um Monstro Xyz para ativar o efeito desse monstro: você pode adicionar 1 monstro "Zubaba" do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "Guerreiro Dodododo" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62886670,'Marincesa Estrela do Mar',replace(replace('Você pode enviar este card da sua mão para o Cemitério e, depois, escolher 1 monstro "Marincesa" que você controla; ele ganha 800 de ATK até o final deste turno. \r\nVocê pode usar este efeito de "Marincesa Estrela do Mar" até duas vezes por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62892347,'Força Arcana 0 - O Tolo',replace(replace('Não pode ser destruído em batalha. \r\nNão pode ser colocado em Posição de Defesa, exceto com efeitos de card. \r\nQuando este card for Invocado: lance uma moeda.\r\n● Cara: Negue os seus efeitos de card que escolham este card como alvo e, se isso acontecer, destrua-os.\r\n● Coroa: Negue os efeitos de card do seu oponente que escolham este card como alvo e, se isso acontecer, destrua-os.','\r',char(13)),'\n',char(10)),'Jogar uma moeda','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62893810,'Dadlope',replace(replace('Uma vez por turno: você pode lançar um dado de seis faces e, depois, aplicar o resultado.\r\n● 1: Olhe a mão do seu oponente e, além disso, descarte 1 card da mão dele.\r\n● 2, 3, 4, 5: Descarte 1 card.\r\n● 6: Descarte toda a sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62895219,'Soprano, a Cantora Melodiosa',replace(replace('Quando este card for Invocado por Invocação-Especial: você pode escolher 1 monstro "Melodiosa" no seu Cemitério, exceto "Soprano, a Cantora Melodiosa"; adicione-o à sua mão. \r\nVocê só pode usar este efeito de "Soprano, a Cantora Melodiosa" uma vez por turno. \r\nUma vez por turno: você pode Invocar por Invocação-Fusão 1 Monstro de Fusão "Melodiosa" do seu Deck Adicional, usando monstros que você controla como Matérias de Fusão, incluindo este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62896588,'Sintonia Natural',replace(replace('Escolha 1 Monstro Normal de Nível 4 ou menos com a face para cima que você controla. \r\nEle é considerado como um monstro Regulador enquanto ele estiver com a face para cima no campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62899696,'Velocidaroide Imãmalicioso',replace(replace('Não pode ser usado como Matéria Sincro exceto para uma Invocação-Sincro por seu próprio efeito. \r\nDurante sua Fase Principal, se este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 monstro com a face para cima que seu oponente controla; imediatamente depois que este efeito resolver, Invoque por Invocação-Sincro 1 Monstro Sincro de VENTO usando apenas este card que você controla e esse monstro. \r\nVocê só pode usar este efeito de "Velocidaroide Imãmalicioso" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Sincro?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62941499,'Nave Springans - Exblowrer',replace(replace('2+ monstros de Nível 8	\r\nVocê pode selecionar 1 das Zonas de Monstros ou Zonas de Magias & Armadilhas do seu oponente; desassocie qualquer número de matérias deste card e, se isso acontecer, destrua o mesmo número de cards que seu oponente controla nessa zona selecionada e suas Zonas de Monstros e/ou Zonas de Magias & Armadilhas adjacentes. \r\nDurante a Fase Principal ou de Batalha do seu oponente (Efeito Rápido): você pode banir este card até a Fase Final. \r\nVocê só pode usar cada efeito de "Nave Springans - Exblowrer" uma vez por turno.','\r',char(13)),'\n',char(10)),'Destruir cards na zona em cruz selecionado','Banir temporariamente este card','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62950604,'Mago Psíquico Silencioso',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode escolher 1 monstro do Tipo Psíquico no seu Cemitério; bana o alvo. \r\nSe este card for enviado do campo para o Cemitério: Invoque por Invocação-Especial o monstro banido por este efeito.','\r',char(13)),'\n',char(10)),'Banir','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62953041,'Fogo Inari',replace(replace('Você só pode controlar 1 "Fogo Inari". \r\nSe você controlar um monstro Mago, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nUma vez por turno, durante sua próxima Fase de Apoio depois que este card com a face para cima no campo foi destruído por um efeito de card e enviado para o Cemitério: Invoque-o por Invocação-Especial do seu Cemitério.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62957424,'Libic, Malebranche do Abismo Ardente',replace(replace('Se você controlar um monstro que não seja um monstro "Abismo Ardente", destrua este card. \r\nVocê só pode usar 1 desses efeitos de "Libic, Malebranche do Abismo Ardente" por turno e apenas uma vez por turno.\r\n● Se você não controlar nenhum Card de Magia/Armadilha: você pode Invocar este card por Invocação-Especial da sua mão.\r\n● Se este card for enviado para o Cemitério: você pode Invocar por Invocação-Especial 1 monstro de TREVAS do Tipo Demônio de Nível 3 da sua mão, mas seus efeitos são negados.','\r',char(13)),'\n',char(10)),'Invocação Especial','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62962630,'Aluber, o Bobo da Corte de Despia',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 Magia/Armadilha "Marcado" do seu Deck à sua mão. \r\nSe um Monstro de Fusão com a face para cima que você controla for destruído em batalha, ou deixar o campo devido a um efeito de card do oponente, enquanto este card estiver no seu Cemitério: você pode escolher 1 Monstro de Efeito que seu oponente controla; Invoque este card por Invocação-Especial e, se isso acontecer, até o final deste turno, negue os efeitos do monstro alvo. \r\nVocê só pode usar 1 efeito de "Aluber, o Bobo da Corte de Despia" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62962631,'Aluber, o Bobo da Corte de Despia',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 Magia/Armadilha "Marcado" do seu Deck à sua mão. \r\nSe um Monstro de Fusão com a face para cima que você controla for destruído em batalha, ou deixar o campo devido a um efeito de card do oponente, enquanto este card estiver no seu Cemitério: você pode escolher 1 Monstro de Efeito que seu oponente controla; Invoque este card por Invocação-Especial e, se isso acontecer, até o final deste turno, negue os efeitos do monstro alvo. \r\nVocê só pode usar 1 efeito de "Aluber, o Bobo da Corte de Despia" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62966332,'Convulsão da Natureza','Vire para cima os Decks de ambos os jogadores (o Duelo prossegue normalmente).','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62967433,'Boromet, o Arbusto Sagrado da Ovelha',replace(replace('2+ monstros de Nível 4	\r\nVocê pode desassociar 1 matéria deste card e, depois, escolha 1 Armadilha Normal no seu Cemitério; coloque-a no fundo do Deck e, depois, compre 1 card. \r\nSe um Card de Armadilha Normal for ativado (exceto durante a Etapa de Dano): você pode desassociar 1 matéria de um Monstro Xyz que você controla e, se isso acontecer, Invoque por Invocação-Especial 1 monstro de Nível 4 da sua mão. \r\nVocê só pode usar cada efeito de "Boromet, o Arbusto Sagrado da Ovelha" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62968263,'Dragão do Arrebol de Olhos das Galáxias',replace(replace('Se você controlar um monstro "Olhos das Galáxias": você pode Invocar este card por Invocação-Especial da sua mão em Posição de Defesa. \r\nSe este card for desassociado de um Monstro Xyz para ativar o efeito desse monstro: você pode pegar 1 "Dragão de Fóton de Olhos das Galáxias" da sua mão ou do Deck e Invocá-lo por Invocação-Especial ou associá-lo a um Monstro Xyz que você controla como matéria e, depois, se você ativou este efeito durante a Fase de Batalha, dobre o ATK de todos os Monstros Xyz "Número" que você controla. \r\nVocê só pode usar cada efeito de "Dragão do Arrebol de Olhos das Galáxias" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Como Matéria Xyz','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62980542,'Destruição de Destino','Envie 3 cards do topo do seu Deck ao Cemitério e sofra 1000 de dano para cada Card de Magia ou Armadilha enviado ao Cemitério dessa forma.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62991792,'Ressonador da Alma',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 monstro Demônio de Nível 4 ou menos do seu Deck à sua mão, exceto "Ressonador da Alma" e, além disso, você não pode Invocar monstros por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto Monstros Sincro de TREVAS. \r\nSe um ou mais cards que você controla seriam destruídos por um efeito de card, enquanto você controlar "Dragão Vermelho Arquidemônio" ou um Monstro Sincro que o mencione, em vez disso, você pode banir este card do seu Cemitério. \r\nVocê só pode usar cada efeito de "Ressonador da Alma" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62991886,'Evolução Instável',replace(replace('Enquanto você tiver menos PV que seu oponente, o ATK original do monstro equipado se torna 2400. \r\nEnquanto você tiver mais PV que seu oponente, o ATK original do monstro equipado se torna 1000.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(62995268,'Desgraças da Floresta Branca',replace(replace('Invoque por Invocação-Especial 1 monstro "Floresta Branca" da sua mão ou do Deck e, depois, imediatamente depois que este efeito resolver, você pode Invocar por Invocação-Sincro 1 Monstro Sincro "Floresta Branca". \r\nSe este card for enviado para o Cemitério para ativar um efeito de monstro: você pode Baixar este card. \r\nVocê só pode usar cada efeito de "Desgraças da Floresta Branca" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial, depois Invocação Sincro','Baixar','Invocação Sincro?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63009228,'Entrelaçador de Socorro',replace(replace('Durante o cálculo de dano, se um monstro Ciberso seu for atacado (Efeito Rápido): você pode descartar este card; você não sofre dano de batalha dessa batalha. \r\nVocê só pode usar este efeito de "Entrelaçador de Socorro" uma vez por turno. \r\nUma vez por turno, durante a Fase Final, se este card estiver no Cemitério porque foi descartado para lá para ativar este efeito neste turno: Invoque este card por Invocação-Especial.','\r',char(13)),'\n',char(10)),'O dano de batalha se torna 0','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63012333,'Torre de Ossos que Absorve Almas',replace(replace('Se você controlar outro monstro do Tipo Zumbi, seu oponente não pode escolher este card como alvo de ataques. \r\nSempre que um ou mais monstros do Tipo Zumbi forem Invocador por Invocação-Especial: envie os 2 cards do topo do Deck do seu oponente para o Cemitério.','\r',char(13)),'\n',char(10)),'Enviar os 2 cards do topo do Deck do seu oponente para o Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63013339,'Força Celeste - Ás - Camellia',replace(replace('2 Monstros de Efeito	\r\nPrimeiro deve ser Invocado por Invocação-Link. \r\nVocê só pode Invocar um ou mais "Força Celeste - Ás - Camellia" por Invocação-Especial uma vez por turno. \r\nUma vez por turno, se você tiver 3 ou menos Magias no seu Cemitério: você pode enviar 1 card "Força Celeste" do seu Deck para o Cemitério. \r\nSe este card for enviado para o Cemitério: você pode escolher 1 monstro que seu oponente controla; Invoque este card por Invocação-Especial no campo do seu oponente (mas mude o controle para seu dono durante a Fase Final deste turno) e, se isso acontecer, envie o monstro alvo para o Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63014935,'Rainha Vulcânica',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro deve ser Invocado por Invocação-Especial (da sua mão) no campo do seu oponente ao oferecer como Tributo 1 monstro que ele controla. \r\nVocê não pode Invocar por Invocação-Normal/Baixar no turno em que Invocar este card por Invocação-Especial. \r\nUma vez por turno: você pode enviar 1 outro card que você controla para o Cemitério; cause 1000 de dano ao seu oponente. \r\nUma vez por turno, durante sua Fase Final: ofereça 1 outro monstro como Tributo ou sofra 1000 de dano.','\r',char(13)),'\n',char(10)),'Cause 1000 de dano ao seu oponente','Escolha: Oferecer um monstro como Tributo ou sofrer dano','Oferecer um monstro como Tributo?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63017368,'Templo de Wedju',replace(replace('Durante sua Fase Principal: você pode colocar 1 monstro da sua mão na sua Zona de Magias & Armadilhas como uma Magia Contínua com a face para cima e, depois, coloque 1 monstro "Milênio" do seu Deck na sua Zona de Magias & Armadilhas como uma Magia Contínua com a face para cima. \r\nVocê só pode usar este efeito de "Templo de Wedju" uma vez por turno. \r\nSe um ou mais monstros "Milênio" com a face para cima que você controla forem destruídos em batalha ou por um efeito de card, você pode colocá-los na sua Zona de Magias & Armadilhas como uma Magia Contínua com a face para cima em vez de enviá-los para o Cemitério.','\r',char(13)),'\n',char(10)),'Colocar um monstro','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63018036,'Eliminação Instantânea do Núcleo de Ferro','Escolha e envie 1 "Núcleo de Ferro de Koa''ki Meiru" do seu Deck para o seu Cemitério.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63018132,'Manipulador de Dragões','VIRE: Ganhe o controle 1 monstro do Tipo Dragão com a face para cima no Campo do seu adversário até à End Phase.','Tomar controle','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63028558,'Multiverso de Solaria','O deus estelar de outro mundo, abrigando seu sol crepuscular. Suas chamas congeladas deixam um rastro queimado através das dimensões, buscando eternamente nova força.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63031396,'Horizonte Cibernético',replace(replace('(Este card deve ser sempre considerado como um card "Cibersombrio(a)".)	\r\nEnvie para o Cemitério 2 monstros Dragão e/ou Máquina "Ciber" com Atributos diferentes, 1 de cada da sua mão e do Deck; adicione 1 monstro Dragão ou Máquina "Ciber" do seu Deck à sua mão e, se isso acontecer, envie para o Cemitério 1 Monstro de Fusão Máquina "Ciber" do seu Deck Adicional. \r\nVocê só pode ativar 1 "Horizonte Cibernético" por turno. \r\nVocê não pode Invocar monstros por Invocação-Especial do Deck Adicional no turno em que ativar este card, exceto monstros Máquina.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63035430,'Arranha-Céu','Se um monstro "HERÓI do Elemento" atacar um monstro que tenha um ATK maior, o monstro atacante ganha 1000 de ATK apenas durante o cálculo de dano.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63049052,'Insígnia Bujin - A Joia',replace(replace('Escolha 1 Monstro Xyz de Classe 4 que você controla; equipe este card no alvo. \r\nEle ganha 300 de ATK para cada Matéria Xyz associada a ele. \r\nUma vez por turno, enquanto este card estiver equipado em um monstro por este efeito: você pode associar 1 monstro "Bujin" da sua mão ao monstro equipado como uma Matéria Xyz.','\r',char(13)),'\n',char(10)),'Associar Matéria','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63053267,'Proteção de Nagel',replace(replace('Monstros "Tindângulo" nas suas Zonas de Monstros Principais não podem ser destruídos em batalha ou por efeitos de card do seu oponente. \r\nUma vez por turno, se um monstro "Tindângulo" seu causar dano de batalha ao seu oponente, o dano é dobrado. \r\nVocê pode banir este card do seu Cemitério e descartar 1 card "Tindângulo"; adicione 1 "Proteção de Nagel" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Proteção de Nagel" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63056220,'Megálito Ophiel',replace(replace('Você pode Invocar este card por Invocação-Ritual com um card "Megálito". \r\nSe este card for Invocado por Invocação-Ritual: você pode adicionar 1 monstro "Megálito" do seu Deck à sua mão, exceto "Megálito Ophiel". \r\nDurante sua Fase Principal: você pode ativar este efeito; Invoque por Invocação-Ritual 1 Monstro de Ritual da sua mão, ao oferecer como Tributo monstros da sua mão ou do campo, incluindo este card no seu campo, cuja soma dos Níveis seja igual ou exceda o Nível do Monstro de Ritual. \r\nVocê só pode usar este efeito de "Megálito Ophiel" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63060238,'Homem em Chamas, o HERÓI do Elemento',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 "Polimerização" do seu Deck à sua mão. \r\nDurante sua Fase Principal: você pode ativar este efeito; você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto Monstros de Fusão e, além disso, envie 1 monstro "HERÓI do Elemento" do seu Deck para o Cemitério, exceto "Homem em Chamas, o HERÓI do Elemento" e, se isso acontecer, até o final deste turno, o Atributo e o ATK/DEF deste card se tornam os mesmos que o do monstro enviado para o Cemitério. \r\nVocê só pode usar 1 efeito de "Homem em Chamas, o HERÓI do Elemento" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Enviar para o Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63086455,'Terrores da Raiz Superior',replace(replace('Escolha 1 card que seu oponente controla e 1 card no Cemitério dele; envie esse card no campo para o Cemitério e, se isso acontecer, Baixe o outro card do Cemitério no campo do seu oponente. \r\nVocê só pode ativar 1 "Terrores da Raiz Superior" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63092423,'Dragão da Muralha Linkesteira',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial por seu próprio efeito. \r\nQuando você Invocar por Invocação-Link: você pode Invocar este card por Invocação-Especial da sua mão e, se isso acontecer, coloque 2 marcadores sobre ele. \r\nSe um monstro for Invocado por Invocação-Link: remova 2 desses marcadores deste card (ou todos, se houver menos de 2). \r\nUma vez por turno, durante cada Fase de Apoio: coloque 1 desses marcadores neste card. \r\nNenhum monstro pode ser Invocado por Invocação-Link a não ser que este card tenha pelo menos tantos desses marcadores quanto o Valor Link desse monstro. \r\nMonstros não podem atacar, exceto Monstros Link.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63101468,'Iluminamestre Hyperion',replace(replace('1 Regulador + 1+ monstros Fada não-Reguladores	\r\nVocê pode enviar 1 monstro "O Representante", ou 1 monstro que mencione "O Santuário no Céu", da sua mão, do Deck ou do Deck Adicional para o Cemitério; até a Fase Final, o nome deste card se torna o nome original desse monstro e substitua este efeito pelos efeitos originais desse monstro. \r\nQuando seu oponente ativar um card ou efeito (Efeito Rápido): você pode banir 1 monstro Fada da sua mão ou do Cemitério e, depois, escolha 1 card no campo; bana-o. \r\nVocê só pode usar cada efeito de "Iluminamestre Hyperion" uma vez por turno.','\r',char(13)),'\n',char(10)),'Copiar efeito','Banir 1 card','Encerrar o efeito copiado','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63101919,'Mago da Tempestade',replace(replace('1 Regulador + 1 ou mais monstros do Tipo Mago não-Reguladores	\r\nQuando este card for Invocado por Invocação-Sincro, coloque 1 Marcador de Magia nele. \r\nUma vez por turno você pode descartar qualquer número de cards para colocar 1 Marcador de Magia em um ou mais monstros que você controla para cada card que você descartou. \r\nVocê pode remover todos os Marcadores de Magia no campo para causar 500 de dano ao seu oponente para cada Marcador de Magia removido.','\r',char(13)),'\n',char(10)),'Colocar Marcadores de Magia','Colocar Marcadores de Magia igual ao número de cards enviados da sua mão para o Cemitério','Remover todos os Marcadores de Magia para causar dano ao seu oponente','Escolha o monstro no qual colocar Marcadores de Magia','','','','','','','','','','','','');
INSERT INTO texts VALUES(63102017,'Impedir a Defesa',replace(replace('Escolha 1 monstro no Campo do seu adversário e mude-o para a Posição de Ataque. \r\nSe o card estiver com a face para baixo, vire a face para cima. \r\nSe o card tiver algum efeito, ele é Activado imediatamente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63111591,'Corvo Vendedor de Cadáveres',replace(replace('Envie cards do topo do seu Deck para o Cemitério até o número de Armadilhas em Cemitérios com nomes diferentes +1 (máx. 4), então você pode aplicar 1 desses efeitos.\r\n● Invoque por Invocação-Especial 1 dos monstros enviados para o Cemitério.\r\n● Baixe 1 das Magias/Armadilhas eviando para o Cemitério, exceto "Corvo Vendedor de Cadáveres", e se você Baixou uma Armadilha ou Magia Rápida, ela pode ser ativada neste turno.','\r',char(13)),'\n',char(10)),'Ativar','Escolha a quantidade de cards a enviar para o Cemitério','Invocação Especial','Baixar','Sem efeito','Ativar aplicando o efeito de "Corvo Vendedor de Cadáveres".','','','','','','','','','','');
INSERT INTO texts VALUES(63120904,'Mega Fortaleza Orca das Trevas',replace(replace('Ofereça como Tributo 1 "Peixe Torpedo" no seu campo para destruir 1 monstro no campo. \r\nOfereça como Tributo 1 "Projétil Molusco-Lança" no seu campo para destruir 1 Card de Magia ou Armadilha no campo.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63125616,'A Sombra que Controla as Trevas','Uma sombra que habita na escuridão, paralisando seus oponentes e tornando-os inofensivos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63136489,'Fusão Quimera',replace(replace('Durante a Fase Principal: Invoque por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional, usando monstros da sua mão ou do campo como matéria, incluindo um monstro Besta ou Demônio. \r\nDurante sua Fase Principal, se este card estiver no seu Cemitério e você tiver "Quimera, a Besta Mística Voadora" no seu campo ou no seu Cemitério: você pode ativar 1 desses efeitos;\r\n● Adicione este card à sua mão.\r\n● Bana este card e, se isso acontecer, Invoque por Invocação-Especial tanto 1 "Gazelle, o Rei das Bestas Místicas" e 1 "Berfomet" do seu Deck e/ou Cemitério.	\r\nVocê só pode usar este efeito de "Fusão Quimera" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Adicionar este card à sua mão','Banir este card e Invocar por Invocação Especial','','','','','','','','','','','','');
INSERT INTO texts VALUES(63142001,'Homem-Bateria AA',replace(replace('Se todos os "Homem-Bateria AA" no seu Campo estão em Posição de Ataque, aumente o ATK deste card em 1000 pontos por cada "Homem-Bateria AA" no seu Campo. \r\nSe todos os "Homem-Bateria AA" no seu Campo estão em Posição de Defesa, aumente a DEF deste card em 1000 pontos por cada "Homem-Bateria AA" no seu Campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63144961,'Absorção Majestosa',replace(replace('Escolha 1 "Dragão da Poeira Estelar" ou 1 Monstro Sincro que o mencione que você controla e, depois, ative 1 desses efeitos;\r\n● Equipe 1 monstro com a face para cima que seu oponente controla ao alvo.\r\n● Ele pode atacar diretamente neste turno.\r\n● Neste turno, sempre que ele destruir um monstro do oponente em batalha, cause dano ao seu oponente igual ao ATK original do monstro destruído.	\r\nVocê só pode ativar 1 "Absorção Majestosa" por turno.','\r',char(13)),'\n',char(10)),'Equipar um monstro do seu oponente','Atacar diretamente','Causar dano quando destruir um monstro em batalha','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63162310,'Parede das Sombras',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro deve ser Invocado por Invocação-Especial com "Labirinto Mágico".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63166095,'Força Celeste - Mobilizar - Engajar!','Se você não controlar nenhum monstro na sua Zona de Monstros Principal: adicione 1 card "Força Celeste" do seu Deck à sua mão, exceto "Força Celeste - Mobilizar - Engajar!" e, depois, se você tiver 3 ou mais Magias no seu Cemitério, você pode comprar 1 card.','Comprar 1 card?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63166096,'Força Celeste - Mobilizar - Engajar!','Se você não controlar nenhum monstro na sua Zona de Monstros Principal: adicione 1 card "Força Celeste" do seu Deck à sua mão, exceto "Força Celeste - Mobilizar - Engajar!" e, depois, se você tiver 3 ou mais Magias no seu Cemitério, você pode comprar 1 card.','Comprar 1 card?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63166097,'Força Celeste - Mobilizar - Engajar!','Se você não controlar nenhum monstro na sua Zona de Monstros Principal: adicione 1 card "Força Celeste" do seu Deck à sua mão, exceto "Força Celeste - Mobilizar - Engajar!" e, depois, se você tiver 3 ou mais Magias no seu Cemitério, você pode comprar 1 card.','Comprar 1 card?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63175639,'Tolo da Profecia',replace(replace('Uma vez por turno: você pode enviar 1 Card de Magia "Livro de Magia" do seu Deck para o Cemitério. \r\nDurante a Fase Final do turno em que este card ativou este efeito: você pode oferecer este card como Tributo; Invoque por Invocação-Especial 1 monstro de TREVAS do Tipo Mago de Nível 5 ou mais do seu Deck. \r\nVocê deve ter 5 ou mais Cards de Magia "Livro de Magia" com nomes diferentes em seu Cemitério para ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Enviar para o Cemitério','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63176202,'Grande Shogun Shien',replace(replace('Se você controlar 2 ou mais monstros "Seis Samurai" com a face para cima, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nSeu oponente só pode ativar 1 Card de Magia/Armadilha por turno. \r\nSe este card seria destruído, em vez disso, você pode destruir 1 monstro "Seis Samurai" que você controla.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63180841,'Dragão da Explosão Estelar T.G. EX',replace(replace('1 Monstro Sincro Regulador + 1+ Monstros Sincro não-Reguladores	\r\nQuando um efeito de monstro for ativado que escolha como alvo um ou mais monstros que você controla (Efeito Rápido): você pode banir 1 Regulador do seu Cemitério; negue a ativação e, se isso acontecer, destrua esse card. \r\nVocê só pode usar cada um dos seguintes efeitos de "Dragão da Explosão Estelar T.G. EX" uma vez por turno.\r\n● Quando um monstro do oponente declarar um ataque: você pode negar o ataque.\r\n● Durante o turno do seu oponente, se este card estiver no seu Cemitério (Efeito Rápido): você pode oferecer como Tributo 2 Monstros Sincro; Invoque este card por Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63181559,'Difusão Trapestrela',replace(replace('Ative 1 desses efeitos;\r\n● Invoque por Invocação-Fusão 1 Monstro de Fusão "Trapestrela" do seu Deck Adicional, ao banir suas matérias do seu Cemitério.\r\n● Imediatamente depois que este efeito resolver, Invoque por Invocação-Link 1 Monstro Link "Trapestrela".	\r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 monstro "Trapestrela" que você controla; neste turno, enquanto esse monstro estiver com a face para cima no seu campo, os monstros do seu oponente só podem escolher esse monstro como alvo de ataques. \r\nVocê só pode usar cada efeito de "Difusão Trapestrela" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Forçar o alvo de ataque','Efeito de Fusão','Invocação Link','','','','','','','','','','','','');
INSERT INTO texts VALUES(63184227,'Rastro da Poeira Estelar',replace(replace('Se um monstro que você controla for oferecido como Tributo (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão ou do Cemitério, mas bana-o quando ele deixar o campo. \r\nSe um Monstro Sincro "Guerreiro(a)", "Sincron" ou "Poeira Estelar" for Invocado por Invocação-Sincro usando este card como matéria: você pode Invocar por Invocação-Especial 1 "Ficha de Poeira Estelar" (Dragão/LUZ/Nível 1/ATK 0/DEF 0). \r\nVocê só pode usar cada efeito de "Rastro da Poeira Estelar" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63184228,'Ficha de Poeira Estelar','Invocado por Especial com o efeito "Rastro da Poeira Estelar".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63193536,'Superlotação','Quando seu oponente Invocar um monstro por Invocação-Especial: Bana todos os monstros de Nível 2 ou menos com a face para cima no campo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63193879,'Tubarão Sabre',replace(replace('Não pode ser usado como uma Matéria Sincro. \r\nDuas vezes por turno: você pode escolher 1 monstro Peixe no campo e, depois, ative 1 desses efeitos.\r\n● Aumente o Nível dele em 1.\r\n● Reduza o Nível dele em 1.	\r\nVocê não pode Invocar quaisquer monstros por Invocação-Especial durante o turno em que ativar este efeito, exceto monstros de ÁGUA.','\r',char(13)),'\n',char(10)),'Ativar efeito','Aumentar o Nível em 1','Reduzir o Nível em 1','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63198739,'Dragão Primita Berilo de Ether',replace(replace('Se este card for Invocado por Invocação-Normal: você pode Baixar 1 Magia/Armadilha "Primita" do seu Deck. \r\nVocê só pode usar cada um dos seguintes efeitos de "Dragão Primita Berilo de Ether" uma vez por turno. \r\nVocê pode oferecer este card como Tributo; envie 1 Monstro Normal do seu Deck para o Cemitério. \r\nDurante sua Fase de Apoio, se você tiver um Monstro Normal no seu campo ou Cemitério: você pode adicionar este card do Cemitério à sua mão.','\r',char(13)),'\n',char(10)),'Baixar','Enviar para o Cemitério','Adicionar à mão','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63211608,'Libertador Aliado Genex','Se você negar a ativação de um Card de Magia, Card de Armadilha ou efeito de Monstro de Efeito ativado pelo seu oponente, você pode Invocar este card por Invocação-Especial da sua mão.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63223260,'Satélite de Fóton','Uma vez por turno: você pode escolher 1 outro monstro "Fóton" que você controla; os Níveis tanto do monstro escolhido quanto deste card se tornam a soma dos Níveis atuais desses 2 monstros.','Alterar Nível','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63223467,'Rai-Mei','Quando este card for destruído em batalha e enviado para o Cemitério, você pode adicionar 1 monstro de LUZ de Nível 2 ou menos do seu Deck à sua mão.','Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63224564,'Ciberescudo',replace(replace('Só pode ser equipado a "Lady Harpia" ou "Irmãs de Lady Harpia". \r\nEle ganha 500 de ATK.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63227401,'Prisioneiro Habiloroso',replace(replace('Escolha 1 card que você controla; neste turno, quando qualquer efeito de monstro que escolhia esse card como alvo durante a ativação resolver, negue esse efeito. \r\nDurante o turno de qualquer duelista, exceto no turno em que este card for enviado para o Cemitério: você pode banir este card do seu Cemitério e, depois, escolher 1 card que você controla; neste turno, quando qualquer efeito de monstro que escolheria esse card como alvo durante a ativação resolver, negue o efeito.','\r',char(13)),'\n',char(10)),'Não afetado','O efeito de "Prisioneiro Habiloroso" está sendo aplicado.','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63233638,'Megálito Phaleg',replace(replace('Você pode Invocar este card por Invocação-Ritual com um card "Megálito". \r\nVocê pode descartar este card; Invoque por Invocação-Ritual 1 Monstro de Ritual "Megálito" da sua mão, ao oferecer como Tributo monstros da sua mão ou do campo cuja soma dos Níveis seja igual ou exceda o seu Nível. \r\nVocê só pode usar este efeito de "Megálito Phaleg" uma vez por turno. \r\nOs monstros que você controla ganham 300 de ATK/DEF para cada Monstro de Ritual no seu Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63251695,'Dinonévoa Rex',replace(replace('Escala de Pêndulo = 6\r\n[ Efeito de Pêndulo ]\r\nUma vez, enquanto este card estiver na sua Zona de Pêndulo, você pode negar um efeito de card ativado que escolhe como alvo outro(s) card(s) "Dinonévoa" que você controla e, depois, destrua este card.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe este card atacar, no final da Etapa de Dano: você pode oferecer como Tributo 1 outro monstro "Dinonévoa" e, depois, ativar 1 desses efeitos;\r\n● Este card pode atacar um monstro do oponente novamente em seguida e, se ele atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente.\r\n● Embaralhe no Deck 1 card da mão do seu oponente (aleatório) ou do lado do campo dele e, depois, este card ganha 100 de ATK.','\r',char(13)),'\n',char(10)),'Escolher um efeito','Usar o efeito de "Dinonévoa Rex"?','Fazer outro ataque','Retornar ao Deck','Retornar 1 card da mão do seu oponente para o Deck do dono','Retornar 1 card que o seu oponente controla para o Deck do dono','','','','','','','','','','');
INSERT INTO texts VALUES(63253763,'Suserano Alienígena',replace(replace('Você pode remover 2 Marcadores-A de qualquer lugar no campo para Invocar este card por Invocação-Especial da sua mão. \r\nUma vez por turno, você pode colocar 1 Marcador-A em cada monstro com a face para cima que seu oponente controla. \r\n(Se um monstro com um Marcador-A batalhar com um monstro "Alienígena", ele perde 300 de ATK e DEF para cada Marcador-A apenas durante o cálculo de dano.) \r\nVocê só pode controlar 1 "Suserano Alienígena".','\r',char(13)),'\n',char(10)),'Colocar "Marcador-A"','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63257623,'Ervidião Silvestre',replace(replace('Quando este card for Invocado por Invocação-Normal ou Especial: você pode escavar o card do topo do seu Deck e, se ele for um monstro do Tipo Planta, envie-o para o Cemitério. \r\nCaso contrário, coloque-o no fundo do seu Deck. \r\nSe este card for escavado do Deck e enviado para o Cemitério por um efeito de card: você pode escolher 1 monstro do Tipo Planta de Nível 4 ou menos no seu Cemitério; Invoque o alvo por Invocação-Especial. \r\nVocê só pode usar este efeito de "Ervidião Silvestre" uma vez por turno.','\r',char(13)),'\n',char(10)),'Revelar o Deck','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63259351,'Ovo Jurássico Milagroso',replace(replace('Enquanto estiver com a face para cima no campo, este card não pode ser banido. \r\nSempre que um ou mais monstros do Tipo Dinossauro forem enviados para o seu Cemitério, coloque 2 marcadores neste card. \r\nVocê pode oferecer este card como Tributo; Invoque por Invocação-Especial 1 monstro do Tipo Dinossauro do seu Deck cujo Nível seja menor ou igual ao número de marcadores que estavam neste card.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63261835,'Cyber Lady Harpia Retalhadora',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nPara a Invocação-Sincro deste card, você pode considerar 1 monstro "Harpia" que você controla como um Regulador. \r\nO nome deste card se torna "Lady Harpia" enquanto estiver no campo ou no Cemitério. \r\nQuando um Card de Magia/Armadilha ou seus efeitos forem ativados (exceto durante a Etapa de Dano) (Efeito Rápido): você pode escolher 1 monstro que seu oponente controla ou 1 monstro "Harpia" que você controla; devolva-o para a mão. \r\nVocê só pode usar este efeito de "Cyber Lady Harpia Retalhadora" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63265554,'Dragão Bravo Ferramenteiro',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Especial: você pode equipar até 3 Magias de Equipamento com nomes diferentes do seu Deck e/ou Cemitério a este card. \r\nDurante a Fase Principal (Efeito Rápido): você pode enviar para o Cemitério 1 das suas Magias de Equipamento equipadas a este card e, depois, escolha 1 Monstro de Efeito no campo; mude sua posição de batalha ou, até o final deste turno, negue seus efeitos. \r\nVocê só pode usar cada efeito de "Dragão Bravo Ferramenteiro" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Alterar posição de batalha','Negar o efeito','','','','','','','','','','','','');
INSERT INTO texts VALUES(63274863,'Cavaleirostélite Sirius',replace(replace('Se este card for Invocado: você pode escolher 5 monstros "Cavaleirost" no seu Cemitério; embaralhe todos os 5 no Deck e, depois, compre 1 card. \r\nVocê só pode usar este efeito de "Cavaleirostélite Sirius" uma vez por turno.','\r',char(13)),'\n',char(10)),'Recuperar do Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63288573,'Força Celeste - Ás - Kagari',replace(replace('1 monstro "Força Celeste - Ás" que não seja de FOGO	\r\nSe este card for Invocado por Invocação-Especial: você pode escolher 1 Magia "Força Celeste" no seu Cemitério; adicione-a à sua mão. \r\nGanha 100 de ATK para cada Magia no seu Cemitério. \r\nVocê só pode Invocar um ou mais "Força Celeste - Ás - Kagari" por Invocação-Especial uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63288574,'Força Celeste - Ás - Kagari',replace(replace('1 monstro "Força Celeste - Ás" que não seja de FOGO	\r\nSe este card for Invocado por Invocação-Especial: você pode escolher 1 Magia "Força Celeste" no seu Cemitério; adicione-a à sua mão. \r\nGanha 100 de ATK para cada Magia no seu Cemitério. \r\nVocê só pode Invocar um ou mais "Força Celeste - Ás - Kagari" por Invocação-Especial uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63295720,'Luz e Trevas do Dragão',replace(replace('Ative 1 desses efeitos (mas você só pode usar cada efeito de "Luz e Trevas do Dragão" uma vez por turno);\r\n● Embaralhe no Deck 1 monstro Dragão de Nível 8 da sua mão e adicione 1 monstro Dragão de Nível 8 com um Atributo diferente do seu Deck à sua mão.\r\n● Escolha 1 monstro Dragão que você controla; ele ganha ATK igual ao seu próprio Nível x 200.\r\n● Quando um card ou efeito for ativado que escolha como alvo um monstro Dragão que você controla: negue o efeito.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Aumentar ATK','Negar o efeito','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63300440,'Escudo Dragão',replace(replace('Só pode ser equipado a um monstro do Tipo Dragão. \r\nEle não pode ser destruído em batalha ou por efeitos de cards. \r\nNenhum duelista sofre qualquer dano de batalha de ataques que o envolvam.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63308047,'Terra, O Terrível','Conhecida como residente dos pântanos, esta criatura é um assecla das forças negras.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63323539,'Explosão Troiana',replace(replace('Ative apenas quando um efeito de card do oponente mudar o controle de um monstro no seu lado do campo para o dele. \r\nDestrua esse 1 monstro e cause dano ao seu oponente igual ao ATK dele.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63356631,'Sopro da Asa da Fênix','Descarte 1 card e, depois, escolha 1 card que seu oponente controla; coloque o alvo no topo do Deck.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63362460,'HERÓI do Destino - Celestial',replace(replace('Quando este card declarar um ataque: você pode escolher 1 Magia com a face para cima que seu oponente controla; destrua-a e, se isso acontecer, cause 500 de dano ao seu oponente. \r\nEnquanto você não tiver cards na sua mão, exceto no turno em que este card foi enviado para o Cemitério: você pode banir este card e 1 monstro "HERÓI do Destino" do seu Cemitério; compre 2 cards. \r\nVocê só pode usar este efeito de "HERÓI do Destino - Celestial" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63364266,'Perseguidor Goyo',replace(replace('1 Regulador + 1 ou mais monstros não-Reguladores	\r\nEste card ganha 300 de ATK para cada Monstro Sincro de TERRA do Tipo Guerreiro no campo (que não seja este card). \r\nQuando este card destruir um monstro do oponente em batalha e enviá-lo para o Cemitério: você pode Invocar esse monstro por Invocação-Especial no seu lado do campo, mas o ATK dele é reduzido à metade.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63378869,'Aiza, a Dragonesa da Devoção Perturbadora',replace(replace('Se este card for Invocado por Invocação-Especial: você pode colocar 1 Marcador de Perturbação em 1 monstro com a face para cima que seu oponente controla, e ele não pode ser usado como matéria para uma Invocação-Fusão, Sincro, Xyz ou Link enquanto tiver esse marcador. \r\nNo começo da Etapa de Dano, se este card batalhar um monstro do oponente com um Marcador de Perturbação: você pode destruir esse monstro do oponente e, se isso acontecer, os dois duelistas sofrem dano igual ao ATK original dele e, além disso, destrua este card no final desta Fase de Batalha. \r\nVocê só pode usar cada efeito de "Aiza, a Dragonesa da Devoção Perturbadora" uma vez por turno.','\r',char(13)),'\n',char(10)),'Colocar um marcador','Destruir um monstro do oponente','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63391643,'Mil Facas','Se você controlar "Mago Negro": escolha 1 monstro que seu oponente controla; destrua o alvo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63394872,'Troca de Senet','Uma vez por turno: você pode escolher 1 monstro na sua Zona de Monstros Principal e selecionar 1 das suas Zonas de Monstros não utilizadas adjacentes (horizontal); mova o alvo para a zona adjacente selecionada.','Mover a posição','Escolha o monstro a mover','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63410069,'Gafanhotos do Deserto',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro: o duelista do turno descarta 1 card. \r\nVocê só pode usar este efeito de "Gafanhotos do Deserto" uma vez por turno. \r\nUma vez por Corrente, durante a Fase Principal do seu oponente, você pode (Efeito Rápido): imediatamente depois que este efeito resolver, Invocar por Invocação-Sincro usando este card que você controla.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63413494,'Prêmio de Consolação',replace(replace('Se um ou mais monstros forem enviados da mão para o Cemitério: escolha 1 deles; Invoque-o por Invocação-Especial no seu campo. \r\nVocê só pode ativar 1 "Prêmio de Consolação" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63422098,'Gigastelo',replace(replace('1 Regulador + 1 ou mais monstros não-Reguladores	\r\nEste card ganha 200 de ATK e DEF para cada Monstro-Matéria Sincro não-Regulador usado para Invocar este card por Invocação-Sincro.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63432835,'Armadilheiro de Pedra','Esss roedor de pedra tennn casssca duuura. Connn isss tennn unnna defesa boooaaa!','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63436931,'Dragão Carmesim',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Especial: você pode adicionar do seu Deck à sua mão 1 Magia/Armadilha que mencione "Dragão Carmesim". \r\n(Efeito Rápido): você pode escolher 1 Monstro Sincro de Nível 7 ou mais no campo, exceto "Dragão Carmesim"; devolva este card para o Deck Adicional e, se isso acontecer, Invoque por Invocação-Especial 1 Monstro Sincro Dragão do seu Deck Adicional com o mesmo Nível que o do monstro alvo (isso é considerado uma Invocação-Sincro). \r\nVocê só pode usar cada efeito de "Dragão Carmesim" uma vez por turno.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Invocação Sincro','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63442604,'Duplo Físico',replace(replace('Você pode activar este card apenas durante o turno do seu adversário. \r\nEscolha 1 monstro no Campo do seu adversário, e Invoque, por Invocação-Especial, 1 "Ficha de Miragem" no seu Campo com o mesmo Nível, Tipo, Atributo, ATK, e DEF que o mostro escolhido. \r\nDestrúa o "Ficha de Miragem" no final do turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63442605,'Ficha de Miragem','Invocada por Invocação-Especial com o efeito "Duplo Físico". Destrua esta ficha no final do turno.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63465535,'Aracnídeo Subterrâneo',replace(replace('1 Regulador de TREVAS + 1 monstro do Tipo Inseto não-Regulador	\r\nSe este card atacar, seu oponente não pode ativar quaisquer Cards de Magia ou Armadilha até o final da Etapa de Dano. \r\nUma vez por turno, você pode selecionar 1 monstro com a face para cima que seu oponente controla e equipá-lo a este card. \r\nSe este card seria destruído em batalha, em vez disso, você pode destruir o monstro equipado a este card pelo seu efeito. \r\n(Você só pode equipar 1 monstro de por vez a este card.)','\r',char(13)),'\n',char(10)),'Equipar','Usar o efeito de "Aracnídeo Subterrâneo" em vez de ser destruído?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63468625,'Senhormek Astro Mekanikle',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao enviar 3 monstros "Senhormek" da sua mão para o Cemitério. \r\nUma vez por turno: você pode escolher 1 Monstro Sincro que seu oponente controla; equipe o alvo a este card. \r\nEste card ganha ATK igual ao ATK combinado dos monstros equipados a ele por este efeito. \r\nUma vez por turno, durante sua Fase de Apoio: você pode enviar 1 desses monstros equipados que você controla para o Cemitério; cause dano ao seu oponente igual ao ATK original desse monstro. \r\nVocê não pode conduzir sua Fase de Batalha no turno em que ativar este efeito.','\r',char(13)),'\n',char(10)),'Equipar','Causar dano','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63477921,'Destruidor de Invocação Ciber','Sempre que um ou mais monstros Máquina forem Invocados por Invocação-Especial, enquanto este card já estiver com a face para cima na sua Zona de Magias & Armadilhas: cause 300 de dano ao seu oponente.','Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63481713,'Vórtice Demoníaco de Atlantis',replace(replace('O nome deste card se torna "Umi" enquanto está na Zona de Monstros.\r\nVocê só pode usar cada um dos seguintes efeitos de "Vórtice Demoníaco de Atlantis" uma vez por turno.\r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode enviar 1 card que mencione "Atlantis, a Cidade do Dragão" do seu Deck para o Cemitério, exceto "Vórtice Demoníaco de Atlantis"\r\nSe este card for enviado para o Cemitério e você controla "Umi": você pode Invocar por Invocação-Especial 1 monstro ÁGUA da sua mão.','\r',char(13)),'\n',char(10)),'Enviar para o Cemitério','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63485233,'Mudar Estrela',replace(replace('Escolha 1 monstro com a face para cima no campo e, depois, ative 1 desses efeitos;\r\n● Aumente o Nível do alvo em 1.\r\n● Reduza o Nível do alvo em 1.','\r',char(13)),'\n',char(10)),'Aumentar o Nível em 1','Reduzir o Nível em 1','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63487632,'Arma Leyvaten Dragunidade',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão ou do Cemitério) ao banir 1 monstro que você controla equipado com um ou mais cards "Dragunidade". \r\nQuando este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 monstro Dragão no seu Cemitério, exceto "Arma Leyvaten Dragunidade"; equipe o alvo a este card. \r\nQuando este card que você controla for enviado para o seu Cemitério por um efeito de card do seu oponente: você pode escolher 1 dos monstros que estava equipado a este card quando ele foi enviado para o Cemitério; Invoque esse monstro por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Equipar','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63492244,'Arena de Luz Trapestrela',replace(replace('Se você Invocar por Invocação-Link um monstro "Trapestrela": você pode escolher 1 monstro "Trapestrela" no seu Cemitério que foi usado como matéria para ele; Invoque-o por Invocação-Especial em Posição de Defesa, mas negue seus efeitos. \r\nVocê só pode usar este efeito de "Arena de Luz Trapestrela" uma vez por turno. \r\nUma vez por turno: você pode escolher 1 card Baixado na Zona de Magias & Armadilhas do seu oponente; enquanto este card estiver na Zona do Campo, esse card Baixado não pode ser ativado até a Fase Final e seu oponente deve ativá-lo durante a Fase Final ou senão, devolva-o para a mão.','\r',char(13)),'\n',char(10)),'','','Escolha 1 card Baixado na Zona de Magias & Armadilhas do seu oponente','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63503850,'Executor Violento',replace(replace('2 Monstros de Efeito	\r\nVocê pode descartar 1 card e, depois, escolha 1 card com a face para cima que seu oponente controla; seu oponente pode descartar 1 card com o mesmo tipo original (Monstro/Magia/Armadilha) que o desse card com a face para cima para negar este efeito, caso contrário, destrua esse card com a face para cima. \r\nVocê só pode usar este efeito de "Executor Violento" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Descartar um card do mesmo tipo original?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63504681,'Número 86: Campeão Heroico - Rhongomyniad',replace(replace('2 ou mais (máx. 5) monstros Guerreiro de Nível 4	\r\nUma vez por turno, durante a Fase Final do seu oponente: desassocie 1 matéria deste card. \r\nEste card ganha efeitos de acordo com o número de matérias associadas a ele.\r\n● 1+: Não pode ser destruído em batalha.\r\n● 2+: Ganha 1500 de ATK/DEF.\r\n● 3+: Não é afetado por outros efeitos de cards.\r\n● 4+: Seu oponente não pode Invocar monstros por Invocação-Normal ou Especial.\r\n● 5: Uma vez por turno: você pode destruir todos os cards que seu oponente controla.','\r',char(13)),'\n',char(10)),'Desassociar Matéria Xyz','Destruir tudo','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63509474,'Salvamento Sável',replace(replace('Você pode escolher 1 monstro Peixe no seu Cemitério; adicione-o à sua mão. \r\nVocê só pode usar este efeito de "Salvamento Sável" uma vez por turno. \r\nSe este card em sua posse for destruído por um efeito de card do oponente e enviado para o seu Cemitério: pegue 1 monstro Peixe do seu Deck e adicione-o à sua mão ou Invoque-o por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Recuperar do Cemitério','Escolha um card para adicionar à sua mão ou Invocar por Invocação Especial','Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63515678,'Correntes Místicas de Captura','Uma corrente mística que aprisiona os inimigos, imobilizando-os.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63516460,'Tufão de Vento Místico',replace(replace('Ative apenas como Elo de Corrente 3 ou mais. \r\nDestrua 1 Card de Magia ou Armadilha no campo. \r\nVocê não pode ativar este card se vários cards/efeitos com o mesmo nome estiverem na Corrente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63519819,'Restrição dos Mil Olhos',replace(replace('"Renunciado" + "Ídolo dos Mil Olhos"	\r\nOutros monstros no campo não podem mudar suas posições de batalha ou atacar. \r\nUma vez por turno: você pode escolher 1 monstro que seu oponente controla; equipe o alvo a este card (máx. 1). \r\nO ATK/DEF deste card se tornam iguais ao do monstro equipado. \r\nSe este card seria destruído em batalha, em vez disso, destrua o monstro equipado.','\r',char(13)),'\n',char(10)),'Equipar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63526052,'Soma Krawler',replace(replace('Você pode escolher 1 monstro com a face para cima que você controla; Invoque este card por Invocação-Especial da sua mão e, se isso acontecer, coloque o monstro alvo com a face para baixo em Posição de Defesa e, além disso, pelo resto deste turno, ele não pode mudar sua posição de batalha. \r\nDurante sua Fase Principal: você pode reduzir o Nível deste card em 2 ou 4 e, se isso acontecer, Invoque por Invocação-Especial um ou mais monstros "Krawler" com nomes diferentes da sua mão, do Deck ou do Cemitério cuja soma dos Níveis seja igual à quantidade reduzida, com a face para cima e/ou com a face para baixo em Posição de Defesa. \r\nVocê só pode usar cada efeito de "Soma Krawler" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Reduzir em 2 Níveis','Reduzir em 4 Níveis','','','','','','','','','','','','');
INSERT INTO texts VALUES(63528891,'Secretária Cópia',replace(replace('Se você controlar um monstro Ciberso, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Secretária Cópia" por Invocação-Especial uma vez por turno desta forma.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63533837,'Dragão Quântico Ciberso',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nEnquanto você controlar um Monstro Link, os monstros que seu oponente controla não podem escolher monstros que você controla como alvo de ataques, exceto este e, além disso, seu oponente não pode escolher monstros que você controla como alvo de efeitos de card, exceto este. \r\nUma vez por turno, no começo da Etapa de Dano, se este card batalhar um monstro do oponente: você pode devolver esse monstro do oponente para a mão e, além disso, este card pode realizar um segundo ataque em seguida.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63542003,'Keldo, a Protetora Sagrada',replace(replace('Você pode descartar 1 outro monstro Fada de TERRA; Invoque este card por Invocação-Especial da sua mão e, depois, adicione 1 "Troca de Espírito", ou 1 card que o mencione, do seu Deck à sua mão. \r\n(Efeito Rápido): você pode banir este card do seu campo ou Cemitério e, depois, escolha até 3 cards em quaisquer Cemitérios, ou até 5 se "Troca de Espírito" estiver no seu campo ou no seu Cemitério; embaralhe-os no Deck. \r\nVocê só pode usar cada efeito de "Keldo, a Protetora Sagrada" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63545455,'Mecanotoupeira Zumbi','Esta criatura ataca lançando braços-projéteis.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63545861,'Constelar Meteoro','Durante o turno em que este card for ativado, se um monstro do oponente batalhar um monstro "Constelar" e o monstro do oponente não for destruído, embaralhe-o no Deck no final da Etapa de Dano.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63571750,'O Tesouro do Faraó',replace(replace('Embaralhe este card no seu Deck, com a face para cima. \r\nSe você comprar este card com a face para cima que foi adicionado ao Deck por este efeito: envie-o para o Cemitério e, depois, escolha 1 card no seu Cemitério, exceto este card; adicione o alvo à sua mão.','\r',char(13)),'\n',char(10)),'Recuperar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63583431,'Talismã Gogogo',replace(replace('Enquanto você controlar 2 ou mais monstros "Gogogo", você não sofre dano de efeito. \r\nUma vez por turno, quando um ataque for declarado envolvendo um monstro "Gogogo" que você controla: você pode ativar este efeito; esse monstro que você controla não pode ser destruído nessa batalha.','\r',char(13)),'\n',char(10)),'Não pode ser destruído','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63595262,'Baliza de Unicórnio',replace(replace('Selecione 1 monstro removido de jogo do Tipo Besta ou do Tipo Besta Alada de Nível 5 ou menos. \r\nRemova de jogo 1 card na sua mão e Invoque por Invocação-Especial o monstro selecionado em Posição de Ataque.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63612442,'Sabre-X Souza',replace(replace('1 Regulador + 1+ monstros "Sabre-X" não-Reguladores	\r\nVocê pode oferecer como Tributo 1 monstro "Sabre-X" e, depois, selecione 1 desses efeitos; este card ganha esse efeito até o final deste turno.\r\n● No começo da Etapa de Dano, se este card batalhar um monstro: destrua esse monstro.\r\n● Não pode ser destruído por efeitos de Armadilha.','\r',char(13)),'\n',char(10)),'Escolher um efeito','Se este card batalhar com um monstro, destrua-o sem cálculo de dano.','Este card não pode ser destruído por efeitos de Armadilha.','Destruir o alvo de batalha','','','','','','','','','','','','');
INSERT INTO texts VALUES(63626024,'Arte Ninjitsu da Miragem - Transformação',replace(replace('Ofereça como Tributo 1 monstro "Ninja" e, depois, escolha 1 monstro no Cemitério do seu oponente; Invoque-o por Invocação-Especial no seu campo. \r\nEle também é considerado como um monstro "Ninja" enquanto este card estiver com a face para cima no campo. \r\nQuando este card deixar o campo, envie esse monstro para o Cemitério. \r\nVocê só pode ativar 1 "Arte Ninjitsu da Miragem - Transformação" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63630268,'Proteção Borbolespiã','Escolha 1 monstro com a face para cima e em Posição de Ataque no campo; coloque-o com a face para cima em Posição de Defesa e, além disso, qualquer dano que você sofrer pelo resto deste turno é diminuído pela metade.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63633694,'Bugiganga Kaku, o Supremo Cervo Celeste Brilhante',replace(replace('Se um monstro estiver na Zona de Monstros Adicional: você pode Invocar este card por Invocação-Especial da sua mão. \r\nVocê pode escolher 1 monstro com a face para cima na Zona de Monstros Adicional; equipe esse monstro com a face para cima a este card (máx. 1). \r\nQuando este card destruir um monstro do oponente em batalha: você pode Invocar por Invocação-Especial 1 dos seus Cards de Monstro equipados a este card. \r\nVocê só pode usar cada efeito de "Bugiganga Kaku, o Supremo Cervo Celeste Brilhante" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63644830,'Esconde-esconde Melffy',replace(replace('Na primeira vez que cada monstro Besta que você controla seria destruído por um efeito de card a cada turno, ele não é destruído. \r\nVocê pode escolher 3 monstros Besta no seu Cemitério com nomes diferentes; embaralhe-os no Deck e, depois, compre 1 card. \r\nVocê só pode usar este efeito de "Esconde-esconde Melffy" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63665606,'Inferno de Movimento Ondular',replace(replace('Enquanto você não tiver cards na sua mão, monstros "Inférnico(a)" com a face para cima que você controla ganham 400 de ATK e DEF. \r\nVocê pode enviar este card com a face para cima do campo ao Cemitério para enviar todos os cards da sua mão ao Cemitério.','\r',char(13)),'\n',char(10)),'Enviar todos os cards na mão para o Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63665875,'Goblin Zumbi',replace(replace('Se este card causar dano de batalha ao seu oponente: envie o card do topo do Deck dele para o Cemitério. \r\nSe este card for enviado do campo para o Cemitério: adicione 1 monstro Zumbi com 1200 ou menos de DEF do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Enviar o card do topo do Deck do seu oponente para o Cemitério','Procurar no Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63676256,'Destruidor Implacável',replace(replace('Uma vez por turno, você pode: Escolher 1 monstro com a face para cima que você controla; equipe este card no alvo, OU: Desequipe este card e Invoque-o por Invocação-Especial com a face para cima em Posição de Ataque. \r\nEnquanto estiver equipado por este efeito, o monstro equipado perde 500 de ATK e DEF. \r\nSe o monstro equipado destruir um monstro do oponente em batalha: Destrua todos os monstros com a face para cima no campo com o mesmo Tipo de Monstro que o monstro destruído. \r\n(Um monstro só pode ser equipado com 1 Monstro União por vez. Se o monstro equipado seria destruído, em vez disso, destrua este card.)','\r',char(13)),'\n',char(10)),'Equipar','Invocação Especial','Destruir','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63679166,'Trono dos Arquidemônios',replace(replace('Invoque por Invocação-Ritual 1 Monstro de Ritual "Arquidemônio" da sua mão, do Deck Adicional com a face para cima, do Cemitério ou do banimento, ao oferecer como Tributo monstros da sua mão ou do campo cuja soma dos Níveis seja igual ou exceda seu Nível. \r\nDurante a Fase de Apoio, se você tiver "Imperador Arquidemônio" no seu Deck Adicional com a face para cima: você pode adicionar este card do seu Cemitério ou banimento à sua mão. \r\nVocê só pode usar este efeito de "Trono dos Arquidemônios" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Ritual','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63689843,'Atacar e Receber',replace(replace('Você só pode ativar este card quando sofrer dano. \r\nCause 700 de dano ao seu oponente. \r\nAlém disso, cause 300 de dano ao seu oponente para cada card "Atacar e Receber" no seu Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63695531,'Soldado da Lança do Coveiro','Se este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63703130,'O - Sobrealma','Escolha 1 Monstro Normal "HERÓI do Elemento" no seu Cemitério; Invoque o alvo por Invocação-Especial.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63708033,'Vernasílfide e os Botões de Flor',replace(replace('Escolha cards com a face para cima que seu oponente controla, até o número de monstros de TERRA que você controla com nomes diferentes que foram Invocados por Invocação-Especial do Cemitério; devolva para a mão monstros de TERRA que você controla igual ao número de alvos e, se você devolveu pelo menos 1 para a mão, devolva os cards alvo para a mão. \r\nVocê só pode ativar 1 "Vernasílfide e os Botões de Flor" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63717421,'Ordem de Inicialização - Carga do Mecanismo',replace(replace('Quando este card for ativado: você pode escolher qualquer número de Cards de Monstro "Dispositivo" que você controla que estiverem equipados a um monstro; Invoque-os por Invocação-Especial. \r\nVocê pode descartar 1 card; adicione 1 "Almirante de Inicialização - Dínamo de Destruição" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Ordem de Inicialização - Carga do Mecanismo" uma vez por turno. \r\nVocê só pode ativar 1 "Ordem de Inicialização - Carga do Mecanismo" por turno.','\r',char(13)),'\n',char(10)),'','Escolher um card de Monstro "Dispositivo" equipado para ativar?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63730624,'Ferramenta Dupla S&F',replace(replace('Só pode ser equipado a um "Dragão Ferramenteiro" ou a um monstro Máquina "Morfotrônico(a)" de Nível 4 ou mais que você controla. \r\nEnquanto estiver equipado:\r\n● Durante o seu turno: o monstro equipado ganha 1000 de ATK.	\r\nSe ele atacar, negue os efeitos do alvo do ataque durante essa Fase de Batalha.\r\n● Durante o turno do seu oponente: os monstros do seu oponente não podem escolher monstros como alvo de ataques, exceto o monstro equipado.	\r\nNo final da Etapa de Dano, se o monstro equipado batalhou um monstro do oponente: destrua esse monstro do oponente.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63731062,'Monoceros Aura Branca',replace(replace('1 Regulador de ÁGUA + 1+ monstros não-Reguladores	\r\nQuando este card for Invocado por Invocação-Sincro: você pode escolher 1 monstro Peixe no seu Cemitério; Invoque-o por Invocação-Especial, mas ele não pode atacar neste turno. \r\nVocê só pode usar este efeito de "Monoceros Aura Branca" uma vez por turno. \r\nSe este card que você controla for destruído por um card do seu oponente e enviado para o seu Cemitério: você pode banir 1 outro monstro de ÁGUA no seu Cemitério; Invoque este card por Invocação-Especial e, se isso acontecer, ele é considerado como um Regulador.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63737050,'Ryu Okami','Se seu oponente Invocar um ou mais monstros por Invocação-Especial: seu oponente envia 1 card do seu Deck Adicional para o Cemitério.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63741331,'Controle de Nevoeiro','Ofereça como Tributo 1 monstro "Nuviano" com a face para cima e, depois, escolha 1 monstro com a face para cima no campo; coloque 3 Marcadores de Névoa no alvo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63746411,'Número 106: Mão Gigante',replace(replace('2 monstros de Nível 4	\r\nQuando um efeito de monstro for ativado no campo do seu oponente (Efeito Rápido): você pode desassociar 2 matérias deste card e, depois, escolha 1 Monstro de Efeito que seu oponente controla; enquanto este monstro estiver com a face para cima no campo, os efeitos desse Monstro de Efeito são negados e, além disso, ele não pode mudar sua posição de batalha.','\r',char(13)),'\n',char(10)),'Negar efeitos','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63748694,'Vermelho Shari do Naviushi Gunkan',replace(replace('O nome deste card se torna "Shari do Naviushi Gunkan" enquanto estiver na mão, no Deck, no Cemitério ou no campo. \r\nVocê só pode usar o seguinte efeito de "Vermelho Shari do Naviushi Gunkan" uma vez por turno. \r\nVocê pode revelar 1 outro "Shari do Naviushi Gunkan" na sua mão; Invoque este card por Invocação-Especial da sua mão e, depois, você pode aplicar este efeito.\r\n● Invoque por Invocação-Especial 1 monstro "Gunkan" do seu Deck, exceto "Shari do Naviushi Gunkan", mas negue seus efeitos (se houver) e, depois, Invoque por Invocação-Especial do seu Deck Adicional, 1 Monstro Xyz que mencione o nome desse monstro Invocado por Invocação-Especial, usando esse monstro e este card como matéria. \r\n(Isso é considerado uma Invocação-Xyz.)','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial e depois Invocar por Invocação Xyz?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63749102,'Universo Exarion',replace(replace('Durante sua Etapa de Batalha, se este card atacar um monstro em Posição de Defesa: você pode fazer com que este card perca exatamente 400 de ATK e, se isso acontecer, ele causará dano de batalha perfurante. \r\nEsses efeitos duram até o final deste turno.','\r',char(13)),'\n',char(10)),'Reduzir ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63767246,'Número 38: Dragão Titã da Galáxia Arauto da Esperança',replace(replace('2 monstros de Nível 8	\r\nUma vez por turno, quando um Card de Magia ou seus efeitos forem ativados no campo (Efeito Rápido): você pode negar esse efeito e, se isso acontecer, associe esse card a este card como matéria. \r\nQuando um monstro do oponente declarar um ataque: você pode desassociar 1 matéria deste card; mude o alvo do ataque para este card e realize o cálculo de dano. \r\nSe um ou mais outros Monstros Xyz com a face para cima que você controla forem destruídos em batalha ou por um efeito de card: você pode escolher 1 Monstro Xyz com a face para cima que você controla; ele ganha ATK igual ao ATK original de 1 desses monstros destruídos.','\r',char(13)),'\n',char(10)),'Negar o efeito do Card de Magia','Redirecionar o alvo de ataque para este card','Aumentar ATK','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63789924,'Granada de Fumo do Ladrão','Quando este card for destruído por um efeito de card enquanto estava equipado a um monstro: olhe a mão do seu oponente e descarte 1 card da mão dele.','Descartar da mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63804637,'Ilusão Melodiosa','Escolha 1 monstro "Melodiosa" que você controla; neste turno, esse monstro com a face para cima que você controla não é afetado pelos efeitos de Magia/Armadilha do seu oponente e ele pode realizar um segundo ataque durante cada Fase de Batalha.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63804806,'Caveira de Chamas Supersônica',replace(replace('Este card não pode ser Invocado por Invocação-Normal ou Baixado. \r\nEste card só pode ser Invocado por Invocação-Especial ao remover de jogo 1 "Caveira de Chamas" do seu Cemitério. \r\nUma vez por turno, você pode causar 400 de dano ao seu oponente para cada "Caveira Incandescente" no seu Cemitério. \r\nQuando este card for enviado do campo ao Cemitério, você pode Invocar por Invocação-Especial 1 "Caveira de Chamas" do seu Cemitério.','\r',char(13)),'\n',char(10)),'Causar dano','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63806265,'Gravidade Arco-Íris','Se você tiver 7 cards "Fera Cristalina" com nomes diferentes no seu campo e/ou no seu Cemitério: Invoque por Invocação-Especial 1 monstro "Cristalino(a) Definitivo(a)" do seu Deck ou Cemitério, ignorando suas condições de Invocação.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63813056,'Dizimador Horrífico, o HERÓI Xtra',replace(replace('2+ monstros "HERÓI"	\r\nEste card, assim como quaisquer monstros "HERÓI" para os quais ele apontar, ganham 100 de ATK para cada monstro "HERÓI" com um nome diferente no seu Cemitério. \r\nSe este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63821877,'Os Cavaleiros Fantasmas das Luvas Gastas',replace(replace('Um Monstro Xyz de TREVAS que foi Invocado usando este card no campo como matéria ganha este efeito.\r\n● Se for Invocado por Invocação-Xyz: ele ganha 1000 de ATK.	\r\nVocê pode banir este card do seu Cemitério; envie 1 card "Cavaleiros Fantasmas" do seu Deck para o Cemitério. \r\nVocê só pode usar cada efeito de "Os Cavaleiros Fantasmas das Luvas Gastas" uma vez por turno.','\r',char(13)),'\n',char(10)),'Este card ganha 1000 de ATK (Os Cavaleiros Fantasmas das Luvas Gastas)','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63825486,'Engenhoca Marionete Boneca Rouge',replace(replace('Se este card estiver na sua mão: você pode revelar 1 Monstro Xyz "Engenhoca Marionete" no seu Deck Adicional; Invoque por Invocação-Especial tanto este card quanto 1 monstro "Engenhoca Marionete" com o mesmo Nível que a Classe do monstro revelado do seu Deck. \r\nSe este card for enviado para o Cemitério, exceto da mão: você pode adicioná-lo à sua mão. \r\nVocê só pode usar cada efeito de "Engenhoca Marionete Boneca Rouge" uma vez por turno e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional no turno em que ativar qualquer um dos efeitos deste card, exceto monstros "Engenhoca Marionete".','\r',char(13)),'\n',char(10)),'Invocação Especial','Retornar para a mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63845230,'Comedor de Milhões',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao banir, com a face para baixo, 5 ou mais cards da sua mão, do campo e/ou do Deck Adicional. \r\nGanha 100 de ATK/DEF para cada card banido com a face para baixo. \r\nNão pode ser oferecido como Tributo, nem usado como matéria para uma Invocação-Fusão, Sincro ou Xyz. \r\nUma vez por turno, no começo da Etapa de Dano, se este card batalhar um monstro do oponente: você pode banir, com a face para baixo, o monstro do oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63851864,'Destruir! Comprar!',replace(replace('Só pode ser equipado a um monstro Máquina. \r\nSe o monstro equipado destruir um monstro do oponente em batalha e enviá-lo para o Cemitério: compre 1 card. \r\nDestrua este card durante sua 3ª Fase Final depois da sua ativação.','\r',char(13)),'\n',char(10)),'Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63854005,'Fusão Pronta',replace(replace('Pague 1000 PV; Invoque por Invocação-Especial 1 Monstro de Fusão de Nível 6 ou menos que não seja de Efeito do seu Deck Adicional, mas ele não pode atacar e, além disso, destrua-o durante a Fase Final. \r\n(Esta é considerada uma Invocação-Fusão.) \r\nVocê só pode ativar 1 "Fusão Pronta" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63875853,'Trocar de Lugares','Se seus PV forem maiores que o do seu oponente, troque seus PV com os do seu oponente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63881033,'Campo Marshalling',replace(replace('Você não pode Invocar monstros por Invocação-Especial, exceto monstros Máquina. \r\nUma vez por turno: você pode declarar um Nível de 5 a 9; todos os monstros Máquina de Nível 5 ou mais que você controla se tornam desse Nível. \r\nSe um ou mais Monstros Xyz Máquina que você controla seriam destruídos, em vez disso, você pode enviar este card para o Cemitério. \r\nSe este card for enviado do campo para o Cemitério: você pode adicionar 1 "Magia de Aumento de Classe Força do Caos Argênteo" do seu Deck ou Cemitério à sua mão.','\r',char(13)),'\n',char(10)),'Alterar Nível','Escolha o Nível para alterar','Usar o efeito de "Campo Marshalling" em vez de ser destruído?','Adicionar à mão','','','','','','','','','','','','');
INSERT INTO texts VALUES(63883999,'Palabirinto Arquidemônio',replace(replace('Todos os monstros do Tipo Demônio que você controla ganham 500 de ATK. \r\nVocê pode escolher 1 monstro "Arquidemônio" que você controla; bana 1 outro monstro do Tipo Demônio que você controla e, se isso acontecer, Invoque por Invocação-Especial da sua mão, Deck, ou Cemitério, 1 monstro "Arquidemônio" com o mesmo Nível que o monstro escolhido. \r\nVocê só pode usar este efeito de "Palabirinto Arquidemônio" uma vez por turno.','\r',char(13)),'\n',char(10)),'Escolher 1 card com a face para cima que seu oponente controla para destruir?','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63899196,'O Plano Diretor dos Monarcas',replace(replace('Envie 1 Magia/Armadilha "Monarca" do seu Deck para o Cemitério, exceto "O Plano Diretor dos Monarcas". \r\nSe este card for banido: você pode escolher 1 monstro com a face para cima que seu oponente controla; adicione 1 monstro com o mesmo Atributo que tenha 2400 de ATK/1000 de DEF, do seu Deck ou Cemitério à sua mão e, depois, você pode aplicar este efeito.\r\n● Imediatamente depois que este efeito resolver, Invoque por Invocação-Normal 1 "Zaborg o Trovão Monarca", "Mebius, o Monarca Frio como o Gelo", "Thestalos, o Monarca da Tempestade de Fogo", "Grandmarg, o Monarca da Rocha", "Raiza, a Monarca da Tempestade" ou "Caius, o Monarca das Sombras".	\r\nVocê só pode usar este efeito de "O Plano Diretor dos Monarcas" uma vez por turno.','\r',char(13)),'\n',char(10)),'Enviar para o Cemitério','Adicionar à mão','Invocação Normal?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63899465,'QG ÁS-Resgate',replace(replace('Enquanto seu oponente controla um monstro, todos os monstros "ÁS-Resgate" que você controla ganham 500 de ATK/DEF. \r\nDurante sua Fase Principal, você pode Invocar por Invocação-Normal 1 monstro "ÁS-Resgate", em adição à sua Invocação-Normal/Baixar (padrão). \r\n(Você só pode se aproveitar deste efeito uma vez por turno.) \r\nUma vez por turno: você pode escolher 4 dos seus cards "ÁS-Resgate" que estiverem banidos e/ou no seu Cemitério; embaralhe-os no Deck e, depois, compre 1 card.','\r',char(13)),'\n',char(10)),'Invocar pelo efeito de "QG ÁS-Resgate"','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63926180,'Espada do Espírito Sagrado Aiwass',replace(replace('Ative 1 desses efeitos, mas você não pode declarar ataques pelo resto deste turno, exceto com Monstros de Fusão;\r\n● Invoque por Invocação-Especial 1 "Aiwass, o Espírito Divino da Lei" do seu Deck ou Cemitério.\r\n● Pegue 1 monstro "Aleister" do seu Deck e envie-o para o Cemitério ou bana-o.\r\n● Olhe 3 cards aleatórios com a face para baixo no Deck Adicional do seu oponente e, se isso acontecer, bana 1 deles.	\r\nVocê só pode ativar 1 "Espada do Espírito Sagrado Aiwass" por turno.','\r',char(13)),'\n',char(10)),'Ativar','Invocação Especial','Escolha 1 monstro "Aleister" do seu Deck','Banir do Deck Adicional','','','','','','','','','','','','');
INSERT INTO texts VALUES(63941169,'Abis-time',replace(replace('Compre cards igual ao número de Tipos de Monstro diferentes entre os monstros que você controla que forem monstros Peixe, Serpente Marinha ou Aqua e, além disso, até o final do seu próximo turno depois que este card resolver, você não pode Invocar por Invocação-Especial do Deck Adicional, exceto monstros de ÁGUA. \r\nSe um ou mais monstros de ÁGUA com a face para cima que você controla forem destruídos em batalha ou por um efeito de card, enquanto este card estiver no seu Cemitério: você pode banir este card; adicione 1 monstro "Sirena" do seu Cemitério ou banimento à sua mão. \r\nVocê só pode usar cada efeito de "Abis-time" uma vez por turno.','\r',char(13)),'\n',char(10)),'Comprar','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63941210,'Jizukiru, o Kaiju Destruidor de Estrelas',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) no campo do seu oponente em Posição de Ataque ao oferecer como Tributo 1 monstro que ele controla. \r\nSe seu oponente controlar um monstro "Kaiju", você pode Invocar este card por Invocação-Especial (da sua mão) em Posição de Ataque. \r\nVocê só pode controlar 1 monstro "Kaiju". \r\nQuando um card ou efeito for ativado que escolha como alvo 1 card (e nenhum outro card) (Efeito Rápido): você pode remover 3 Marcadores Kaiju de qualquer parte do campo; negue o efeito e, se isso acontecer, você pode destruir 1 card no campo.','\r',char(13)),'\n',char(10)),'Negar a ativação','Destruir 1 card no campo?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63942761,'Noellia Gishki','Quando este card for Invocado por Invocação-Normal: você pode escavar os 5 cards do topo do seu Deck, enviar qualquer Card de Magia de Ritual e quaisquer monstros "Gishki" escavados para o Cemitério e, além disso, colocar os outros cards no fundo do seu Deck em qualquer ordem.','Verificar o Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63945693,'Ponte Arco-Íris','Adicione 1 Magia/Armadilha "Cristalino(a)" do seu Deck à sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63947968,'Reflexo Demoníaco do Milênio',replace(replace('Se este card batalhar um monstro, nenhum dos dois pode ser destruído nessa batalha. \r\nVocê só pode usar cada um dos seguintes efeitos de "Reflexo Demoníaco do Milênio" uma vez por turno. \r\nSe este card estiver na sua mão: você pode colocá-lo na sua Zona de Magias & Armadilhas como uma Magia Contínua com a face para cima. \r\nSe seu oponente ativar um card ou efeito, enquanto este card for uma Magia Contínua (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial e, depois, você pode ganhar PV igual à metade do ATK de 1 monstro no campo.','\r',char(13)),'\n',char(10)),'Colocá-la como Card de Magia','Invocação Especial','Ganhar PV?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63948258,'Sapo Submarino','Durante a batalha entre este card atacante e um monstro em Posição de Defesa cuja DEF for menor do que o ATK deste card, cause a diferença como Dano de Batalha ao seu oponente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63956833,'Transe das Galáxias',replace(replace('Pague 2000 PV e, depois, escolha 1 monstro "Fóton" no seu Cemitério; Invoque por Invocação-Especial tanto ele quanto 1 monstro "Galáxia" do seu Deck, os dois com o mesmo Nível, em Posição de Defesa e, se isso acontecer, o ATK de cada monstro se torna 2000 e, além disso, seus efeitos são negados. \r\nVocê só pode ativar 1 "Transe das Galáxias" por turno. \r\nVocê não pode Invocar monstros por Invocação-Normal ou Especial durante o turno em que ativar este card, exceto monstros "Fóton" e "Galáxia".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63972571,'Besta Rei Bárbaros',replace(replace('Este card pode atacar todos os monstros que seu oponente controla uma vez cada. \r\nVocê só pode usar cada um dos seguintes efeitos de "Besta Rei Bárbaros" uma vez por turno.\r\n● Você pode oferecer como Tributo monstros cuja soma dos Níveis seja igual a 8 ou mais; Invoque este card por Invocação-Especial da sua mão.\r\n● Você pode banir 1 monstro "Bárbaros" do seu Cemitério ou do campo com a face para cima e, depois, escolha 2 cards que seu oponente controla; destrua-os.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63977008,'Sucata Sincron','Quando este card for Invocado por Invocação-Normal: você pode escolher 1 monstro de Nível 2 ou menos no seu Cemitério; Invoque o alvo por Invocação-Especial em Posição de Defesa, mas negue seus efeitos.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63992027,'Duplamente Críptico','Se seu oponente controlar um monstro com o maior ATK no campo (mesmo se empatado): escolha 1 Monstro Xyz "Olhos das Galáxias" ou "Críptico(a)" que você controla que tenha Matérias Xyz; desassocie todas as Matérias Xyz desse Monstro Xyz e, se isso acontecer, Invoque por Invocação-Especial 1 monstro do seu Deck Adicional com o mesmo nome que esse Monstro Xyz.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(63995093,'Duplicação de Máquinas','Escolha 1 monstro Máquina que você controla com 500 ou menos de ATK; Invoque por Invocação-Especial até 2 monstros do seu Deck com o mesmo nome que esse monstro com a face para cima.','Escolha 1 monstro Máquina com 500 ou menos de ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64002884,'Repulsão Simorgh',replace(replace('Descarte 1 monstro Besta Alada; devolva para a mão todos os cards nas Zonas de Magias & Armadilhas do seu oponente. \r\nVocê pode banir este card do seu Cemitério; revele 1 monstro Besta Alada na sua mão e, se isso acontecer, pelo resto deste turno, reduza em 1 os Níveis dos monstros na sua mão com esse nome (mesmo depois que eles forem Invocados). \r\nVocê só pode ativar 1 "Repulsão Simorgh" por turno.','\r',char(13)),'\n',char(10)),'Retornar para a mão','Reduzir o Nível','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64014615,'Pote da Aquisitividade',replace(replace('Escolha 3 monstros banidos; embaralhe os 3 no Deck e, depois, compre 1 card. \r\nVocê só pode ativar 1 "Pote da Aquisitividade" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64018647,'Sopro da Ressurreição',replace(replace('Se você controlar uma "Ficha de Aventura": Invoque por Invocação-Especial até 2 monstros com nomes diferentes da sua mão e/ou do Cemitério (mas bana-os quando eles deixarem o campo) e, depois, você pode equipar 1 Magia de Equipamento que mencione "Ficha de Aventura" da sua mão ou do Cemitério a 1 monstro que você controla. \r\nVocê só pode ativar 1 "Sopro da Ressurreição" por turno.','\r',char(13)),'\n',char(10)),'Equipar uma Magia de Equipamento?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64025981,'Dragão Primitivo, o Primordial',replace(replace('Seu oponente não sofre dano de batalha de ataques envolvendo este card. \r\nVocê só pode usar cada um dos seguintes efeitos de "Dragão Primitivo, o Primordial" uma vez por turno. \r\nVocê pode banir 1 monstro Dragão do seu Cemitério; até o final do próximo turno, este card ganha ATK/DEF igual ao ATK desse monstro banido. \r\nSe este card for oferecido como Tributo: você pode escolher 1 monstro que você controla; ele pode realizar um segundo ataque durante cada Fase de Batalha neste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64034255,'Aliado Genex Homem-pássaro','Você pode devolver para a mão 1 monstro com a face para cima que você controla; Invoque este card por Invocação-Especial da sua mão, mas bana-o quando ele deixar o campo e, além disso, ele ganha 500 de ATK se o monstro devolvido era de VENTO no campo.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64034256,'Aliado Genex Homem-pássaro','Você pode devolver para a mão 1 monstro com a face para cima que você controla; Invoque este card por Invocação-Especial da sua mão, mas bana-o quando ele deixar o campo e, além disso, ele ganha 500 de ATK se o monstro devolvido era de VENTO no campo.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64038662,'Forma Variável',replace(replace('Uma vez por turno, você pode ativar 1 desses efeitos.\r\n● Escolha 2 monstros "Inzektor" com a face para cima que você controla; equipe um ao outro.\r\n● Escolha 1 monstro "Inzektor" que você controla que seja um Card de Equipamento; Invoque o alvo por Invocação-Especial com a face para cima em Posição de Defesa.','\r',char(13)),'\n',char(10)),'Ativar 1 efeito','Usar o efeito de "Forma Variável" agora?','Equipar','Invocação Especial','Escolha o monstro para considerar como um Card de Equipamento','','','','','','','','','','','');
INSERT INTO texts VALUES(64043465,'Obliterar!!!',replace(replace('Você pode escolher 1 monstro no campo; envie 1 monstro "O Proibido" ou card "Exodia" da sua mão ou do Deck para o Cemitério e, se isso acontecer, devolva o alvo para a mão. \r\nSe este card for enviado da Zona de Magias & Armadilhas para o Cemitério: você pode escolher 1 monstro "O Proibido" ou card "Exodia" no seu Cemitério; adicione-o à sua mão. \r\nVocê só pode usar 1 efeito de "Obliterar!!!" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Retornar um monstro no campo para a mão','Adicionar um card do Cemitério à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64047146,'Chifre do Unicórnio',replace(replace('O monstro equipado ganha 700 de ATK e DEF. \r\nQuando este card for enviado do campo para o Cemitério: devolva-o para o topo do Deck.','\r',char(13)),'\n',char(10)),'Retornar ao Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64049553,'Ataqueraptor - Pouso',replace(replace('Se um ou mais monstros "Ataqueraptor" forem Invocados por Invocação-Especial do Deck Adicional no seu campo (exceto durante a Etapa de Dano): você pode adicionar 1 Magia/Armadilha "Ataqueraptor" do seu Deck à sua mão, exceto "Ataqueraptor - Pouso". \r\nVocê pode escolher 3 dos seus monstros "Ataqueraptor" que estiverem banidos e/ou no seu Cemitério; coloque-os no fundo do seu Deck em qualquer ordem e, depois, compre 1 card. \r\nVocê só pode usar cada efeito de "Ataqueraptor - Pouso" uma vez por turno.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Recuperar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64049762,'Blitzclique - Destruição',replace(replace('Ative 1 desses efeitos;\r\n● Coloque 1 Armadilha Contínua "Blitzclique" do seu Deck, com a face para cima no seu campo.\r\n● Devolva 1 monstro Trovão que você controla para a mão e, depois, escolha 1 card no campo; destrua-o.	\r\nSe um ou mais cards forem destruídos por um efeito de card "Blitzclique" seu, enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode adicionar este card à sua mão. \r\nVocê só pode usar cada efeito de "Blitzclique - Destruição" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar','Retornar para a mão','Baixar 1 Card de Armadilha Contínua','Efeito de destruição','','','','','','','','','','','','');
INSERT INTO texts VALUES(64061284,'Fusão do Mecanismo Antigo',replace(replace('Invoque por Invocação-Fusão 1 Monstro de Fusão "Mecanismo Antigo" do seu Deck Adicional, usando monstros da sua mão ou do campo. \r\nSe você usar "Golem do Mecanismo Antigo" ou "Golem do Mecanismo Antigo - Murro Definitivo" que você controla como matéria, você também pode usar monstros do seu Deck.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64063868,'Eclipser Sombrio de Kozmo',replace(replace('Não pode ser escolhido como alvo de efeitos de card do oponente. \r\nDurante o turno de qualquer duelista, quando um Card de Armadilha for ativado: você pode banir 1 monstro "Kozmo" do seu Cemitério; negue a ativação e, se isso acontecer, destrua esse card. \r\nSe este card for destruído em batalha ou por um efeito de card e enviado para o Cemitério: você pode banir este card do seu Cemitério; adicione 1 monstro "Kozmo" de Nível 8 ou menos do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64104037,'Lanceiro Fantasma, o Lanceiro do Submundo',replace(replace('Se somente seu oponente controlar um monstro, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nNão pode ser destruído em batalha, exceto com monstros Invocados por Invocação-Especial do Deck Adicional. \r\nSe este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64107820,'Brilho Futuro','Ative este card ao banir 1 monstro do Tipo Psíquico do seu Cemitério e anote o Nível dele; todos os monstros do Tipo Psíquico que você controla ganham ATK igual a esse Nível x 200.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64116319,'Lady Harpia Toon',replace(replace('Não pode atacar no turno em que for Invocado. \r\nSe você controlar "Mundo Toon": você pode Invocar este card por Invocação-Especial da sua mão e, depois, se você controlar outro monstro Toon, você pode destruir 1 Magia/Armadilha que seu oponente controla. \r\nVocê só pode usar este efeito de "Lady Harpia Toon" uma vez por turno. \r\nEnquanto você controlar "Mundo Toon" e seu oponente não controlar nenhum monstro Toon, este card pode atacar diretamente.','\r',char(13)),'\n',char(10)),'','Destruir 1 Card de Magia/Armadilha que seu oponente controla?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64145892,'Círculo de Fóton','Qualquer Dano de Batalha que você sofrer de batalhas envolvendo este card é reduzido pela metade.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64154377,'Besta Embrionária','Um monstro imperfeito com um vórtice na barriga que suga oponentes de qualquer tamanho.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64160836,'Criança Alienígena',replace(replace('Coloque 1 Marcador-A em todos os monstros Invocados por Invocação-Especial no lado do campo do seu oponente. \r\n(Se um monstro com um Marcador-A batalhar com um monstro "Alienígena", ele perde 300 de ATK e DEF para cada Marcador-A apenas durante o cálculo de dano.)','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64161630,'Raio Purificador','Ofereça como Tributo 1 Monstro Xyz; durante a Fase Final, Invoque por Invocação-Especial do seu Deck Adicional 1 monstro "Número" com o mesmo Tipo, mas 1 Classe menor que o monstro oferecido como Tributo tinha quando estava no campo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64163367,'Incubadora de Células "A"',replace(replace('Toda vez que um ou mais Marcadores-A forem removidos do jogo por um efeito de card, coloque 1 Marcador-A neste card. \r\nQuando este card for destruído, distribua os Marcadores-A neste card entre os monstros com a face para cima.','\r',char(13)),'\n',char(10)),'Colocar "Marcador-A"','Escolha o monstro no qual colocar "Marcador-A"','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64178424,'Determinação de Salamagrande',replace(replace('Durante sua Fase Principal: você pode Invocar por Invocação-Especial 1 monstro "Salamagrande" da sua mão ou do Cemitério. \r\nVocê pode enviar este card com a face para cima do campo para o Cemitério e, depois, escolher 1 Monstro Link "Salamagrande" que você controla que foi Invocado por Invocação-Link usando um monstro com seu mesmo nome como matéria; Invoque por Invocação-Especial um ou mais monstros "Salamagrande" da sua mão e/ou do Cemitério em Posição de Defesa, até o número do Valor Link desse monstro. \r\nVocê só pode usar 1 efeito de "Determinação de Salamagrande" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar 1 monstro por Invocação Especial','Invocar por Invocação Especial um número de monstros igual ao número de Marcadores de Link','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64178868,'Sobrevivente da Batalha',replace(replace('No final da Fase de Batalha: você pode adicionar 1 card do seu Cemitério à sua mão, exceto "Sobrevivente da Batalha", que foi enviado para lá durante esta Fase de Batalha enquanto você controlava este card com a face para cima. \r\nVocê só pode usar este efeito de "Sobrevivente da Batalha" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64182380,'Eternidade Garunix, o Hyang dos Reis de Fogo',replace(replace('2+ monstros de Nível 8	\r\nSe este card for Invocado por Invocação-Xyz: você pode destruir todos os outros monstros no campo. \r\nVocê pode desassociar 1 matéria deste card e, depois, escolha 1 Magia/Armadilha no campo; destrua-a e, se isso acontecer, este card ganha 500 de ATK. \r\nSe este card for destruído enquanto tiver matéria: você pode Invocar monstros "Rei(s) de Fogo" por Invocação-Especial do seu Cemitério, até o número de matérias que este card tinha. \r\nVocê só pode usar cada efeito de "Eternidade Garunix, o Hyang dos Reis de Fogo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64184058,'HERÓI do Destino - Decisor',replace(replace('Monstros de Nível 6 ou mais que seu oponente controla não podem escolher este card como alvo de ataques. \r\nVocê só pode usar cada um dos seguintes efeitos de "HERÓI do Destino - Decisor" uma vez por Duelo.\r\n● Se este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 monstro "HERÓI" do seu Cemitério à sua mão durante a Fase Final deste turno.\r\n● Quando um card ou efeito que causaria dano a você for ativado, enquanto este card estiver no seu Cemitério (Efeito Rápido): devolva este card para a sua mão e, se isso acontecer, transforme em 0 esse dano de efeito a você.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64187086,'Renascimento do Imortal Terrestre','Descarte 1 card e, depois, escolha 1 monstro "Imortal Terrestre" e 1 Magia de Campo no seu Cemitério; adicione os alvos à sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64193046,'Samurai Superpesado Corajoso Masurawo',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nEste card pode atacar enquanto estiver com a face para cima em Posição de Defesa. \r\nSe o fizer, use sua DEF para o cálculo de dano. \r\nSe um ou mais monstros "Samurai Superpesado" que você controla seriam destruídos em batalha ou por um efeito de card, em vez disso, você pode destruir 1 card "Samurai Superpesado" que você controla. \r\nUma vez por turno, se seu oponente ativar um Card de Magia/Armadilha ou seus efeitos (exceto durante a Etapa de Dano): você pode comprar até ter 3 cards na sua mão.','\r',char(13)),'\n',char(10)),'Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64202399,'Dragão do Abismo de Olhos Azuis',replace(replace('Se este card for Invocado por Invocação-Especial: você pode adicionar 1 Magia de Ritual ou 1 "Polimerização" do seu Deck à sua mão. \r\nDurante sua Fase Final: você pode adicionar 1 monstro Dragão de Nível 8 ou mais do seu Deck à sua mão. \r\nVocê pode banir este card do seu Cemitério; todos os monstros Dragão de Nível 8 ou mais que você controla ganham 1000 de ATK. \r\nVocê só pode usar cada efeito de "Dragão do Abismo de Olhos Azuis" uma vez por turno e só pode ativá-los enquanto "Dragão Branco de Olhos Azuis" estiver no seu campo ou no seu Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64203620,'Jormungardr, a Serpente Nórdica',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nSe um monstro "Aesir" estiver no campo, você pode Invocar este card por Invocação-Especial (da sua mão) no lado do campo do seu oponente em Posição de Defesa. \r\nSe não houver um monstro "Aesir" no campo, destrua este card. \r\nSe este card que você controla com a face para cima em Posição de Defesa for colocado com a face para cima em Posição de Ataque: sofra 3000 de dano. \r\nEste efeito só pode ser usado uma vez enquanto este card estiver com a face para cima no campo.','\r',char(13)),'\n',char(10)),'Invocação Especial','Receba 3000 pontos de dano','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64207696,'Camarartista Dente de Ouro',replace(replace('Escala de Pêndulo = 3\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno, se um monstro "Camarartista" seu destruir um monstro do oponente em batalha: cause 1000 de dano ao seu oponente.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe este card for Invocado por Invocação-Normal ou Especial: todos os monstros "Camarartista" que você controla atualmente ganham 200 de ATK até o final deste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64211118,'Dragão Firewall Fluido Negro - Neotempestade Terahertz',replace(replace('3+ monstros Ciberso	\r\nNegue quaisquer efeitos de monstro ativados pelo seu oponente durante a Fase de Batalha. \r\n(Efeito Rápido): você pode enviar 1 monstro Ciberso do seu Deck ou Deck Adicional para o Cemitério e, se isso acontecer, este card ganha o Atributo desse monstro enviado para o Cemitério e, além disso, ele ganha 2500 de ATK. \r\nVocê só pode usar este efeito de "Dragão Firewall Fluido Negro - Neotempestade Terahertz" uma vez por turno. \r\nEste card pode atacar monstros um número de vezes a cada Fase de Batalha, até o número de Atributos diferentes que ele tiver.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64213017,'Formação Bezoudado',replace(replace('Você pode escolher 1 monstro "Bezoudado" no seu Cemitério; Invoque-o por Invocação-Especial, mas ele não pode atacar neste turno e, além disso, você perde PV igual ao ATK original dele. \r\nSe um ou mais monstros Inseto com a face para cima que você controla forem destruídos em batalha ou por um efeito de card: você pode Invocar por Invocação-Especial 1 "Ficha de Bezoudado" (Inseto/TERRA/Nível 3/ATK 1000/DEF 1000). \r\nVocê só pode usar cada efeito de "Formação Bezoudado" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64213018,'Ficha de Bezoudado','Invocado por Especial com o efeito de um card "Bezoudado".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64230128,'Zaralaam, o Palácio Negro',replace(replace('Enquanto você controlar um monstro equipado com "Dunnell, Armas Nobres da Luz", seu oponente não pode ativar cards ou efeitos durante a Fase de Batalha. \r\nUma vez por turno, quando uma "Ficha de Aventura" sua destruir um monstro do oponente em batalha: você pode causar dano ao seu oponente igual ao ATK original desse monstro destruído. \r\nUma vez por turno, durante sua Fase Principal, se o efeito anterior foi ativado neste turno: você pode adicionar 1 Magia de Campo que mencione "Ficha de Aventura" do seu Deck ou Cemitério à sua mão, exceto "Zaralaam, o Palácio Negro".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64233143,'Redemoinho Daedalus',replace(replace('Quando seu oponente Invocaria por Invocação-Normal ou Especial um ou mais monstros enquanto você controla "Atlantis, a Cidade do Dragão": negue a Invocação, e se fizer, destrua ataqueles monstros, então se você controla um Monstro Link ÁGUA, você pode destruir todos os monstros não-ÁGUA no campo.\r\nVocê pode banir este card do seu Cemitério e enviar 1 "Umi" com a face para cima que você controla para o Cemitério, então escolha 1 monstro que seu oponente controla; envie-o para o Cemitério.\r\nVocê só pode usar 1 dos efeitos de "Redemoinho Daedalus", e somente uma vez por turno.','\r',char(13)),'\n',char(10)),'Negar a Invocação','Enviar para o Cemitério','Destruir aquele monstro?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64238008,'Canhão Acelerador Linear',replace(replace('Ofereça como Tributo 1 monstro e cause dano ao oponente igual à metade do ATK original desse monstro. \r\nSe ativar este card, você não pode ativar nenhum outro Card de Magia neste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64245689,'Meliae das Árvores',replace(replace('2 monstros de TERRA de Nível 3	\r\nUma vez por turno: você pode desassociar 1 Matéria Xyz deste card e, depois, ativar 1 desses efeitos.\r\n● Envie 1 monstro do Tipo Planta do seu Deck para o Cemitério.\r\n● Escolha 1 monstro do Tipo Planta no seu Cemitério; Invoque o alvo por Invocação-Especial com a face para cima em Posição de Defesa.','\r',char(13)),'\n',char(10)),'Enviar um monstro Planta do Deck para o Cemitério','Invocar um monstro Planta do Cemitério por Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64257161,'Motoqueiro Goblin Mean Impiedosa',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode Invocar por Invocação-Especial 1 monstro "Goblin" da sua mão, exceto "Motoqueiro Goblin Mean Impiedosa". \r\nDurante sua Fase Principal, se este card estiver no seu Cemitério: você pode desassociar 1 Matéria Xyz de um monstro em qualquer campo e, se isso acontecer, Invoque este card por Invocação-Especial, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar cada efeito de "Motoqueiro Goblin Mean Impiedosa" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial da mão','Invocar este card por Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64262809,'Dragão-Gelo',replace(replace('Quando seu oponente Invocar um monstro por Invocação-Especial (exceto durante a Etapa de Dano): você pode descartar 1 card; Invoque este card por Invocação-Especial da sua mão ou Cemitério. \r\nSó pode haver 1 "Dragão-Gelo" em campo.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64268668,'Ciberogro',replace(replace('Ao descartar este card da sua mão para o Cemitério, negue 1 batalha envolvendo um "Ciberogro" no seu lado do campo, ele ganha 2000 de ATK até o fim da próxima batalha dele. \r\nEste efeito pode ser ativado durante o turno de qualquer duelista.','\r',char(13)),'\n',char(10)),'Negar a batalha','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64271667,'Dragão Meteoro','Este dragão surgiu nos céus e colidiu na terra.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64274292,'Meteo-Chuva','Durante este turno, quando os seus monstros atacam com um ATK superior ao DEF do monstro em Posição de Defesa, inflija a diferença aos Life Points do seu adversário como dano de batalha.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64276752,'Dragão Xyz da Rebelião Arc',replace(replace('3 monstros de Nível 5	\r\nEste card Invocado por Invocação-Xyz não pode ser destruído por efeitos de card. \r\nVocê pode desassociar 1 matéria deste card; este card ganha ATK igual à soma do ATK original de todos os outros monstros no campo e, depois, se este card tiver um Monstro Xyz de TREVAS como matéria, negue os efeitos de todos os outros monstros com a face para cima no campo. \r\nDepois que este efeito resolver, você não pode declarar ataques com outros monstros pelo resto deste turno. \r\nVocê só pode usar este efeito de "Dragão Xyz da Rebelião Arc" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64280356,'Tincan de Kozmo',replace(replace('(Efeito Rápido): você pode banir este card; Invoque por Invocação-Especial 1 monstro "Kozmo" de Nível 2 ou mais da sua mão. \r\nVocê só pode usar este efeito de "Tincan de Kozmo" uma vez por turno. \r\nUma vez por turno, durante a Fase Final: você pode pagar 500 PV; revele 3 cards "Kozmo" com nomes diferentes do seu Deck, seu oponente elege 1 aleatoriamente para que você adicione à sua mão e você envia o resto para o Cemitério.','\r',char(13)),'\n',char(10)),'Invoque por Invocação Especial 1 monstro "Kozmo" da sua mão','Adicionar à sua mão 1 card "Kozmo" do seu Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64283880,'Gadogo, avante!','Se um ou mais monstros "Gagaga", "Dododo" e/ou "Gogogo" que você controla forem destruídos em batalha ou por um efeito de card e enviados para o Cemitério: escolha 1 desses monstros; Invoque-o por Invocação-Especial e, depois, você pode Invocar por Invocação-Especial até 2 monstros "Gagaga", "Dododo" e/ou "Gogogo" da sua mão em Posição de Defesa.','Invocar por Invocação Especial um monstro da sua mão?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64306248,'Joaninha com Marca de Caveira','Quando este card for enviado para o Cemitério, aumente seus PV em 1000.','Recupere 1000 PV','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64319467,'Tubarão de Nadadeiras Duplas',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode escolher 1 monstro Peixe de ÁGUA de Nível 3 ou 4 no seu Cemitério; Invoque o alvo por Invocação-Especial em Posição de Defesa, mas negue seus efeitos. \r\nVocê não pode Invocar quaisquer monstros por Invocação-Especial durante o turno em que ativar este efeito, exceto monstros de ÁGUA.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64325438,'Sala do Chefe Generaidor',replace(replace('Quando seu oponente ativar um card ou efeito em resposta à ativação de um card ou efeito "Generaidor" seu: você pode descartar 1 card; o efeito ativado do seu oponente se torna "cada duelista compra 1 card". \r\nVocê só pode usar este efeito de "Sala do Chefe Generaidor" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar, mas não resolver o efeito','Altere o efeito do seu oponente','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64327901,'Grande Encontro Motoqueiro Goblin',replace(replace('Monstros "Goblin" que você controla ganham 300 de ATK para cada monstro "Goblin" que você controla. \r\nDurante sua Fase Principal, você pode Invocar por Invocação-Normal 1 monstro "Goblin", em adição à sua Invocação-Normal/Baixar (padrão). \r\n(Você só pode se aproveitar deste efeito uma vez por turno.) \r\nVocê pode escolher 2 monstros "Goblin" que você controla e, depois, ative 1 desses efeitos;\r\n● Faça com que o Nível de 1 desses monstros se torne o Nível atual do outro.\r\n● Os Níveis dos dois se tornam seus Níveis originais combinados.	\r\nVocê só pode usar este efeito de "Grande Encontro Motoqueiro Goblin" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar pelo efeito de "Grande Encontro Motoqueiro Goblin"','Alterar Nível','Fazer o Nível de 1 deles se tornar igual ao do outro','Fazer os Níveis dos 2 monstros se tornarem a soma dos seus Níveis originais','Escolha o outro monstro (seu Nível não muda)','','','','','','','','','','','');
INSERT INTO texts VALUES(64332231,'Dragão Solar Hierático Suserano de Heliópolis',replace(replace('2 monstros de Nível 8	\r\nUma vez por turno: você pode desassociar 1 matéria deste card; ofereça como Tributo qualquer número de monstros da sua mão e/ou do campo (mín. 1) e, depois, destrua o mesmo número de cards no campo.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64335804,'Dragão Metálico Negro de Olhos Vermelhos',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nVocê primeiro deve Invocá-lo por Invocação-Especial (do seu Deck) ao oferecer como Tributo "Dragão Negro de Olhos Vermelhos" equipado com "Metalmorfo".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64335805,'Dragão Metálico Negro de Olhos Vermelhos',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nVocê primeiro deve Invocá-lo por Invocação-Especial (do seu Deck) ao oferecer como Tributo "Dragão Negro de Olhos Vermelhos" equipado com "Metalmorfo".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64342551,'Bugroth Anfíbio MK-3','Enquanto "Umi" permanecer no Campo com a face para cima, este card pode atacar os Life Points do seu adversário diretamente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64373401,'Samurai Superpesado Trompetista',replace(replace('Se você não tiver Cards de Magia/Armadilha no seu Cemitério, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nDepois que este card foi Invocado por Invocação-Especial desta forma, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros "Samurai Superpesado". \r\nSe este card for oferecido como Tributo para a Invocação-Tributo de um monstro "Samurai Superpesado" e enviado para o Cemitério e você não tiver Cards de Magia/Armadilha no seu Cemitério: você pode Invocar este card por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64379261,'Gárgula Gorgônico','Quando você Invocar por Invocação-Normal um monstro do Tipo Rocha: você pode Invocar este card por Invocação-Especial da sua mão.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64379430,'Terror do Juízo Final',replace(replace('O ATK e DEF deste card são iguais ao número de monstros de TREVAS banidos x 300. \r\nSe este card for destruído e enviado para o Cemitério: devolva todos os monstros de TREVAS banidos para o Cemitério.','\r',char(13)),'\n',char(10)),'Retornar ao Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64382839,'Reticulante Zeta',replace(replace('Você pode oferecer como Tributo 1 "Ficha de Eva" para Invocar este card por Invocação-Especial da sua mão. \r\nEnquanto este card estiver no seu Cemitério, sempre que um ou mais monstros controlados pelo seu oponente forem removidos de jogo, Invoque por Invocação-Especial 1 "Ficha de Eva" (Tipo Demônio/TREVAS/Nível 2/ATK 500/DEF 500).','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64382840,'Ficha de Eva','Invocado por Especial com o efeito "Reticulante Zeta".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64389297,'Labirinto Mágico',replace(replace('Só pode ser equipado a "Paredes do Labirinto". \r\nVocê pode oferecer o monstro equipado como Tributo; Invoque por Invocação-Especial "Parede das Sombras" do seu Deck.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64398890,'Os Seis Samurai - Yaichi',replace(replace('Uma vez por turno: Você pode escolher 1 Card de Magia ou Armadilha Baixado; destrua o alvo. \r\nVocê deve controlar um monstro "Seis Samurai" com a face para cima com um nome diferente para ativar e resolver este efeito. \r\nEste monstro não pode declarar um ataque no turno em que este efeito for ativado. \r\nSe este card seria destruído, em vez disso, você pode destruir outro monstro "Seis Samurai" com a face para cima que você controla.','\r',char(13)),'\n',char(10)),'Destruir 1 Magia/Armadilha Baixada','Usar o efeito de substituição de destruição de "Os Seis Samurai - Yaichi"?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64400161,'Fandora, o Peloforte Voador',replace(replace('Durante sua Fase de Compra, antes de comprar: você pode renunciar à sua compra normal neste turno e, se isso acontecer, adicione 1 monstro "de Peluguel" do seu Deck à sua mão. \r\nSe você controlar 5 ou mais monstros "de Peluguel" com nomes diferentes: você pode enviar este card da Zona do Campo para o Cemitério; destrua todos os cards que seu oponente controla e, além disso, pelo resto deste turno, seu oponente não sofre dano.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64413994,'Berçange Furtivo','Uma entidade misteriosa que dizem ser um anjo que traz a salvação às almas hereges". Depois que "ele" passa, só resta um silêncio eterno. - Ange Passe.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64414267,'Cavaleirostrelanegra Batlamyus',replace(replace('2 monstros "Cavaleirost" de Nível 4	\r\nTodos os monstros com a face para cima no campo se tornam de TREVAS. \r\nVocê pode desassociar 1 Matéria Xyz deste card e descartar 1 card; Invoque por Invocação-Especial do seu Deck Adicional, 1 Monstro Xyz "Cavaleirost" de LUZ ao usar este card com a face para cima que você controla como Matéria Xyz e, além disso, você não pode Invocar outros monstros por Invocação-Xyz pelo resto deste turno. \r\n(Isso é considerado uma Invocação-Xyz. As Matérias Xyz associadas a este card também se tornam Matérias Xyz no monstro Invocado.) \r\nEste efeito pode ser ativado durante o turno de qualquer duelista se você tiver 7 ou mais monstros "Cavaleirost" com nomes diferentes no seu Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64428736,'Espada do Jacaré','Esss poderoso homen lagarto pode brandir sua essspada masss rápido q a velocidade do sonnn!','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64437633,'Ilusão Aqua-espelhada',replace(replace('Invoque por Invocação-Especial 1 Monstro de Ritual "Gishki" da sua mão. \r\nEle não pode atacar e é devolvido para a mão durante a Fase Final.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64442155,'Máquina de Anjo Misericordiosa',replace(replace('Ofereça como Tributo 1 Monstro de Ritual "Ciber Anjo(a)" da sua mão ou do campo; compre 2 cards e, depois, coloque 1 card da sua mão no fundo do Deck. \r\nPelo resto deste turno depois que este card resolver, você não pode Invocar monstros por Invocação-Especial, exceto Monstros de Ritual. \r\nVocê só pode ativar 1 "Máquina de Anjo Misericordiosa" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64450427,'Bruxa Caprichosa Camarartista',replace(replace('Escala de Pêndulo = 4\r\n[ Efeito de Pêndulo ]\r\nSe seu oponente controlar um monstro com a face para cima que foi Invocado por Invocação-Especial do Deck Adicional e você não: você pode Invocar este card por Invocação-Especial da sua Zona de Pêndulo. \r\nVocê só pode usar este efeito de "Bruxa Caprichosa Camarartista" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nEste card pode ser considerado como 2 Tributos para a Invocação-Tributo de um Monstro Pêndulo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64454614,'Extra Coringa Arcano',replace(replace('3 monstros Guerreiro com nomes diferentes	\r\nUma vez por turno, quando um Card de Magia/Armadilha ou efeito de monstro for ativado que escolha como alvo este card com a face para cima no campo ou um monstro para o qual este card apontar (Efeito Rápido): você pode descartar o mesmo tipo de card (Monstro, Magia ou Armadilha); negue a ativação. \r\nQuando este card Invocado por Invocação-Link for destruído em batalha e enviado para o Cemitério: você pode Invocar por Invocação-Especial 1 Monstro Normal Guerreiro de Nível 4 do seu Deck e, se isso acontecer, adicione 1 monstro Guerreiro de Nível 4 do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64455720,'Inseto Venenoso de Asutra',replace(replace('Ative 1 desses efeitos;\r\n● Invoque por Invocação-Especial este card como um Monstro Normal (Inseto/Regulador/TREVAS/Nível 1/ATK 0/DEF 0) (este card NÃO é considerado como uma Armadilha), então imediatamente após ativar este efeito, você pode Invocar por Invocação-Sincro 1 Monstro Sincro.\r\n● Escolha 1 monstro "Asutra" no seu Cemitério; Invoque-o por Invocação-Especial.	\r\nVocê só pode ativar 1 "Inseto Venenoso de Asutra" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar','Invocar por Invocação Especial como monstro','Invoque por Invocação Especial 1 monstro do Cemitério','Invocação Sincro?','','','','','','','','','','','','');
INSERT INTO texts VALUES(64463828,'Besta de Superliga Metálica Raptinus',replace(replace('1 Monstro Gêmeos + 1 Monstro Gêmeos	\r\nTodos os Monstros Gêmeos no campo são considerados como Monstros de Efeito e ganham seus efeitos.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64475743,'Rabigatinha, Besta Mística da Floresta',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 monstro Besta, Besta-Guerreira, Besta Alada, Inseto ou Planta no seu Cemitério; envie 1 monstro do seu Deck para o Cemitério com o mesmo Tipo original que o desse monstro. \r\nSe este card em posse do seu dono for destruído por um card do oponente: você pode adicionar 1 monstro Besta, Besta-Guerreira, Besta Alada, Inseto ou Planta do seu Deck à sua mão, exceto "Rabigatinha, Besta Mística da Floresta". \r\nVocê só pode usar cada efeito de "Rabigatinha, Besta Mística da Floresta" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64487132,'Jogador Dispositivo',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode adicionar 1 monstro Máquina de Nível 1 do seu Deck à sua mão. \r\nVocê pode oferecer este card como Tributo; Invoque por Invocação-Especial 1 monstro "Morfotrônico(a)" da sua mão e, depois, você pode Invocar por Invocação-Especial 1 "Transportador de Dispositivos" da sua mão ou do Deck. \r\nVocê só pode usar cada efeito de "Jogador Dispositivo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Invocar "Transportador de Dispositivos" por Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64491754,'Elfnotas: Bem-vindo ao Lar',replace(replace('O monstro na sua Zona de Monstros Principal central não pode ser destruído por efeitos de card. \r\nVocê pode enviar 1 monstro da sua mão ou do campo para o Cemitério; Invoque por Invocação-Especial 1 monstro "Elfnota" com um Atributo original diferente do seu Deck em Posição de Defesa e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto Monstros Sincro. \r\nVocê só pode usar este efeito de "Elfnotas: Bem-vindo ao Lar" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64496451,'Disco Qliphort',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nVocê não pode Invocar monstros por Invocação-Especial, exceto monstros "Qli". \r\nEste efeito não pode ser negado. \r\nTodos os monstros "Qli" que você controla ganham 300 de ATK.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nVocê pode Invocar este card por Invocação-Normal sem oferecer Tributo. \r\nSe este card for Invocado por Invocação-Normal sem oferecer Tributo, ou se for Invocado por Invocação-Especial, o Nível dele se torna 4 e o ATK original dele se torna 1800. \r\nSe este card for Invocado por Invocação-Normal/Baixado, ele não é afetado por efeitos ativados de monstros cujo Nível/Classe original seja menor que o Nível atual deste card. \r\nQuando este card for Invocado por Invocação-Tributo pelo Tributo de um ou mais monstros "Qli": você pode Invocar por Invocação-Especial 2 monstros "Qli" do seu Deck, mas destrua-os durante a Fase Final.','\r',char(13)),'\n',char(10)),'Invocação Normal sem Tributo','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64500000,'Tanque Metálico Z',replace(replace('Uma vez por turno, você pode: escolher 1 "Cabeça de Canhão X" ou "Cabeça de Dragão Y" que você controla; equipe este card no alvo, OU: desequipe este card e Invoque-o por Invocação-Especial. \r\nUm monstro equipado com este card ganha 600 de ATK/DEF e, além disso, se o monstro equipado seria destruído em batalha ou por um efeito de card, em vez disso, destrua este card.','\r',char(13)),'\n',char(10)),'Equipar','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64501875,'Hibikime','Confunde os monstros inimigos com um barulho que agride os ouvidos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64511793,'Optoarmadura','Este guerreiro se transforma em diversas criaturas para confundir os inimigos nas batalhas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64514622,'Selo Hierático do Rei Dragão',replace(replace('Este card é considerado um Monstro Normal enquanto estiver com a face para cima no campo ou no Cemitério. \r\nEnquanto este card for um Monstro Normal no campo, você pode Invocá-lo por Invocação-Normal para fazer com que ele se torne um Monstro de Efeito com este efeito.\r\n● Você pode oferecer este card como Tributo; Invoque por Invocação-Especial 1 monstro "Hierático", exceto "Selo Hierático do Rei Dragão", da sua mão, do Deck ou do Cemitério, com a face para cima em Posição de Defesa.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64514892,'Boneco Daruma de Combate ao Fogo',replace(replace('2 monstros Besta, Besta-Guerreira e/ou Besta Alada	\r\nEste card ganha 100 de ATK para cada monstro Besta, Besta-Guerreira ou Besta Alada no campo. \r\nUma vez por turno: você pode escolher 1 Magia/Armadilha em cada campo; destrua-as. \r\nQuando este card destruir um monstro do oponente em batalha: você pode escolher 1 dos seus monstros Besta, Besta-Guerreira ou Besta Alada que estiverem banidos ou no seu Cemitério; adicione-o à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64538655,'Samurai Sasuke nº 4',replace(replace('Se este card combater, lance uma moeda e escolha cara ou coroa antes do cálculo de dano. \r\nSe acertou, destrúa o monstro do seu adversário com este efeito.','\r',char(13)),'\n',char(10)),'Destruir o monstro com o qual batalhou','Cara','Coroa','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64538914,'Mantícora do Esmagamento',replace(replace('Durante sua Fase Principal: você pode adicionar 1 "Fissura" ou 1 "Esmagando o Chão" do seu Deck à sua mão. \r\nSe este card estiver no seu Cemitério: você pode banir 1 "Fissura" ou 1 "Esmagando o Chão" da sua mão ou do Cemitério; Invoque este card por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Mantícora do Esmagamento" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64550682,'Ortros de Restolhos',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro deve ser Invocado por Invocação-Especial (da sua mão) enquanto você controlar um monstro "Restolhos". \r\nSe Invocado desta forma: escolha 1 monstro "Restolhos" que você controla; destrua o alvo. \r\nSe este card for destruído pelo efeito de um card "Restolhos" e enviado para o Cemitério: você pode escolher 1 monstro "Restolhos" no seu Cemitério, exceto "Ortros de Restolhos"; adicione o alvo à sua mão.','\r',char(13)),'\n',char(10)),'Destruir','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64554883,'Número 25: Foco em Força',replace(replace('2 monstro de Nível 6	\r\nUma vez por turno, durante o turno de qualquer duelista: você pode desassociar 1 Matéria Xyz deste card e, depois, escolher 1 Monstro de Efeito de Nível 5 ou mais que seu oponente controla; até o final do turno, negue o efeito desse monstro do oponente com a face para cima.','\r',char(13)),'\n',char(10)),'Negar o efeito','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64576557,'Carregando Triâmide',replace(replace('Se uma Magia de Campo for colocada com a face para cima na Zona do Campo: você pode adicionar 1 Magia/Armadilha "Triâmide" do seu Deck à sua mão, exceto "Carregando Triâmide". \r\nSe um ou mais monstros Rocha com a face para cima que você controla forem destruídos em batalha ou por um efeito de card do oponente: você pode Invocar por Invocação-Especial 1 monstro "Triâmide" com um nome diferente do seu Deck. \r\nVocê só pode usar cada efeito de "Carregando Triâmide" uma vez por turno.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64583600,'Dragão dos Desejos',replace(replace('Você pode oferecer este card como Tributo; Invoque por Invocação-Especial 2 "Ficha de Dragão" (Dragão/TERRA/Nível 1/ATK 0/DEF 0) e, além disso, você não pode Invocar monstros por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto monstros Dragão de Nível 5 ou mais. \r\nVocê só pode usar este efeito de "Dragão dos Desejos" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64583601,'Ficha de Dragão','Invocado por Especial com o efeito "Dragão dos Desejos".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64591429,'Kuriboh Astral',replace(replace('Você pode revelar 1 Monstro Xyz "Número" no seu Deck Adicional; Invoque este card por Invocação-Especial da sua mão. \r\nSe isso acontecer, o Nível deste card se torna a Classe do monstro revelado e, além disso, enquanto ele estiver com a face para cima na Zona de Monstros, você não pode Invocar monstros por Invocação-Especial do Deck Adicional, exceto Monstros Xyz "Número". \r\nVocê só pode usar este efeito de "Kuriboh Astral" uma vez por turno. \r\nUm Monstro Xyz "Número" que foi Invocado usando este card no campo como matéria ganha este efeito.\r\n● Não pode ser destruído em batalha ou pelos efeitos de card do seu oponente.','\r',char(13)),'\n',char(10)),'','O efeito de "Kuriboh Astral" está sendo aplicado.','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64599569,'Superdragão Quimeratech',replace(replace('"Dragão Cibernético" + 1+ monstros Máquina	\r\nDeve ser Invocado por Invocação-Fusão. \r\nSe este card for Invocado por Invocação-Fusão: envie todos os outros cards que você controla para o Cemitério. \r\nO ATK/DEF originais deste card se tornam iguais ao número de Matérias de Fusão usadas para sua Invocação-Fusão x 800. \r\nA cada Fase de Batalha, este card pode atacar os monstros do seu oponente um número de vezes até o número de Matérias de Fusão usadas para sua Invocação-Fusão.','\r',char(13)),'\n',char(10)),'Enviar todos as outros card que você controla para o Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64603182,'Golem Sombrio do Mecanismo Antigo',replace(replace('O nome deste card se torna "Golem do Mecanismo Antigo" enquanto estiver no campo ou no Cemitério. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode adicionar até 2 cards (cards "Mecanismo Antigo" e/ou "Vila Mecânica") do seu Deck à sua mão, exceto "Golem Sombrio do Mecanismo Antigo" e, depois, descarte 1 card e, além disso, você não pode Baixar cards pelo resto deste turno. \r\nVocê só pode usar este efeito de "Golem Sombrio do Mecanismo Antigo" uma vez por turno. \r\nSe este card atacar, seu oponente não pode ativar Cards de Magia/Armadilha até o final da Etapa de Dano.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64603351,'Senhor Dragão de Atlantis - Daedalus',replace(replace('O nome deste card se torna "Umi" enquanto está na Zona de Monstros.\r\nVocê só pode usar cada um dos seguintes efeitos de "Senhor Dragão de Atlantis - Daedalus" uma vez por turno.\r\nSe você controla "Atlantis, a Cidade do Dragão" ou "Umi": você pode Invocar por Invocação-Especial este card da sua mão.\r\nVocê pode enviar até 3 "Umi" com a face para cima que você controla para o Cemitério; adicione aquela mesma quantia de cards que mencionem "Atlantis, a Cidade do Dragão" do seu Deck à sua mão, exceto monstros de Nível 7, então você pode enviar 1 card no campo para o Cemitério.','\r',char(13)),'\n',char(10)),'Invocação Especial','Efeito de busca','Enviar o card selecionado para o Cemitério?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64605089,'Espadachím da Luz Reveladora',replace(replace('Quando um monstro do oponente declarar um ataque direto: você pode Invocar este card por Invocação-Especial da sua mão e, depois, se a DEF deste card for maior que o ATK do monstro atacante, destrua esse monstro atacante. \r\nUm Monstro Xyz que foi Invocado usando este card no campo como Matéria Xyz ganha este efeito.\r\n● A cada turno, na primeira vez que este card seria destruído em batalha, ele não é destruído.','\r',char(13)),'\n',char(10)),'Invocação Especial','O efeito de "Espadachím da Luz Reveladora" está sendo aplicado.','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64612053,'ÁS-Resgate Afrontador do Fogo',replace(replace('Se um ou mais monstros "ÁS-Resgate" forem Invocados por Invocação-Normal ou Especial no seu campo, exceto "ÁS-Resgate Afrontador do Fogo" (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe um ou mais cards forem adicionados à mão do seu oponente, exceto ao comprá-los (exceto durante a Etapa de Dano): você pode comprar 2 cards e, depois, descarte 1 card. \r\nVocê só pode usar cada efeito de "ÁS-Resgate Afrontador do Fogo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64626565,'Ceruvim Negro Irisfil',replace(replace('2 monstros de Nível 8	\r\nUma vez por turno, você também pode Invocar por Invocação-Xyz "Ceruvim Negro Irisfil" ao usar 1 Monstro Xyz que você controla que não ativou seus efeitos na Zona de Monstros neste turno (transfira as matérias dele). \r\nSe este card for Invocado por Invocação-Xyz: você pode ativar este efeito; durante a Fase de Batalha deste turno, Monstros Xyz que você controla ganham ATK igual à sua Classe x 100. \r\nSe este card seria destruído em batalha ou por um efeito de card, em vez disso, você pode desassociar 1 matéria de um monstro que você controla. \r\nVocê só pode usar este efeito de "Ceruvim Negro Irisfil" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Xyz usando um Monstro Xyz como matéria?','Aumentar ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64627453,'Ojama Azul','Quando este card for destruído em batalha e enviado para o Cemitério: você pode adicionar 2 cards "Ojama" do seu Deck à sua mão.','Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64631466,'Renunciado',replace(replace('Você pode Invocar este card por Invocação-Ritual com "Ritual de Ilusão Negra". \r\nUma vez por turno: você pode escolher 1 monstro que seu oponente controla; equipe o alvo a este card (máx. 1). \r\nO ATK/DEF deste card se tornam iguais aos do monstro equipado. \r\nSe este card seria destruído em batalha, em vez disso, destrua o monstro equipado. \r\nEnquanto estiver equipado com esse monstro, qualquer dano de batalha que você sofrer de batalhas envolvendo este card causa o mesmo dano de efeito ao seu oponente.','\r',char(13)),'\n',char(10)),'Equipar','Seu oponente sofre dano de batalha','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64635042,'Convocação do Arquidemônio',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nO nome deste card se torna "Caveira Invocada" no campo, mas ele ainda é considerado como um card "Arquidemônio". \r\nSeu oponente não pode escolher nenhum "Caveira Invocada" que você controla como alvo de efeitos de card. \r\nSe este card Invocado por Invocação-Sincro que você controla for enviado para o seu Cemitério por um card do oponente: você pode Invocar por Invocação-Especial 1 "Caveira Invocada" da sua mão, do Deck ou do Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64655485,'Neos Corajoso, o HERÓI do Elemento',replace(replace('"Neos, o HERÓI do Elemento" + 1 Monstro de Efeito de Nível 4 ou menos	\r\nDeve ser Invocado por Invocação-Fusão. \r\nGanha 100 de ATK para cada monstro "Neoespacial" e "HERÓI" no seu Cemitério. \r\nQuando este card destruir um monstro do oponente em batalha: você pode adicionar 1 Magia/Armadilha do seu Deck à sua mão, que liste especificamente o card "Neos, o HERÓI do Elemento" no seu texto.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64659851,'Lei do Cosmo',replace(replace('Seu oponente pode Baixar 1 Armadilha diretamente da mão ou do Deck dele. \r\nDepois, se ele o fez, Invoque por Invocação-Especial 1 "Jinzo" do seu Deck. \r\nSe ele não o fez, adicione 1 "Jinzo", ou 1 monstro que liste especificamente esse card em seu texto, do seu Deck à sua mão. \r\nVocê só pode ativar 1 "Lei do Cosmo" por turno.','\r',char(13)),'\n',char(10)),'Baixar o Card de Armadilha e deixar seu oponente Invocar por Invocação Especial?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64662453,'Chamado do Ferro','Se você controlar um monstro Máquina: escolha 1 monstro Máquina de Nível 4 ou menos no seu Cemitério; Invoque o alvo por Invocação-Especial, mas seus efeitos são negados e, além disso, destrua-o durante a Fase Final.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64664373,'Metaltronus',replace(replace('Escolha 1 monstro com a face para cima que não seja Ficha que seu oponente controla; Invoque por Invocação-Especial 1 monstro da sua mão, do Deck ou do Deck Adicional que tenha 2 ou mais do mesmo Tipo, Atributo e/ou ATK (mas negue seus efeitos) e, se isso acontecer, negue os efeitos do monstro alvo e, além disso, depois, se esses monstros tiverem o mesmo nome, você pode banir os dois, com a face para baixo. \r\nSeu oponente não pode ativar os efeitos do monstro alvo em resposta à ativação deste card. \r\nVocê só pode ativar 1 "Metaltronus" por turno.','\r',char(13)),'\n',char(10)),'','Banir esses 2 monstros com a face para baixo?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64681263,'Tornado Localizado','Embaralhe todos os cards da sua mão e Cemitério no Deck.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64681432,'Gandora o Dragão da Destruição',replace(replace('Não pode ser Invocado por Invocação-Especial. \r\nVocê pode pagar metade dos seus PV; destrua tantos cards no campo quanto possível (que não sejam este card) e, se isso acontecer, bana-os. \r\nEste card ganha 300 de ATK para cada card destruído desta forma. \r\nUma vez por turno, durante a Fase Final, se este card foi Invocado por Invocação-Normal ou Virar neste turno: envie-o para o Cemitério.','\r',char(13)),'\n',char(10)),'Destruir','Enviar para o Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64689404,'Quebra-Espadas',replace(replace('2 monstros de Nível 6	\r\nUma vez por turno: Você pode desassociar 1 Matéria Xyz deste card para declarar 1 Tipo de Monstro; este card ganha o seguinte efeito. \r\nNo começo da Etapa de Dano, se este card batalhar com um monstro de um Tipo que foi declarado: Destrua esse monstro.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64697231,'Trap Dustshoot','Se seu oponente tiver 4 ou mais cards na mão dele: olhe a mão do seu oponente e selecione 1 monstro dela para embaralhar no Deck.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64697431,'Ei, Trunade!','Devolva para a mão todas as Magias e Armadilhas Baixadas no campo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64726269,'Escala Serafim Estelar',replace(replace('Quando este card for Invocado por Invocação-Especial: você pode Invocar por Invocação-Especial 1 monstro "Serafim Estelar" da sua mão e, depois, você pode colocar no topo do seu Deck 1 monstro de LUZ do seu Cemitério. \r\nUm Monstro Xyz que foi Invocado usando 3 ou mais monstros como Matérias Xyz, incluindo este card no campo, ganha este efeito.\r\n● Uma vez por turno, enquanto este card tiver Matérias Xyz, se um ou mais monstros forem Invocados por Invocação-Especial da mão, compre 1 card imediatamente.','\r',char(13)),'\n',char(10)),'Invocação Especial','Colocar 1 monstro de LUZ do Cemitério no topo do Deck?','O efeito de "Escala Serafim Estelar" está sendo aplicado.','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64730881,'Ladrão do Tempo Ajustador',replace(replace('Se você Invocar por Invocação-Normal ou Especial um ou mais monstros "Ladrão do Tempo", exceto "Ladrão do Tempo Ajustador" (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode enviar 1 card "Ladrão do Tempo" do seu Deck para o Cemitério, exceto "Ladrão do Tempo Ajustador". \r\nVocê só pode usar 1 efeito de "Ladrão do Tempo Ajustador" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64734090,'Tartaruga-Gema','VIRE: Você pode adicionar 1 "Fusão Cavaleiro-Gema" do seu Deck à sua mão.','Adicionar à mão','Adicionar 1 "Fusão Cavaleiro-Gema" à sua mão?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64734921,'O Representante da Criação - Vênus','Você pode pagar 500 PV; Invoque por Invocação-Especial 1 "Bola com Brilho Místico" da sua mão ou do Deck.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64749612,'Ninja Amarelo',replace(replace('Se este card for Invocado por Invocação-Normal ou virado com a face para cima: você pode Invocar por Invocação-Especial 1 monstro "Ninja" de Nível 4 ou menos da sua mão em Posição de Ataque ou com a face para baixo em Posição de Defesa e, além disso, você não pode Invocar monstros por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto monstros "Ninja". \r\nVocê só pode usar este efeito de "Ninja Amarelo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64751286,'Lady Guerreira da Lua','Se este card combater com um monstro da LUZ, aumente o ATK deste card em 1000 pontos durante o Damage Step.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64752646,'Princesa de Fogo','Cada vez que você ganhar PV, cause 500 de dano ao seu oponente.','Causar dano quando você ganhar PV','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64753157,'Simpática Equipe do Resort',replace(replace('Quando um ataque for declarado envolvendo um "Super Agente ESPIRÃO" que você controla e um monstro com a face para cima do oponente: você pode mudar o ATK desse monstro do oponente para 0. \r\nSe este card for destruído em batalha ou por um efeito de card: você pode Invocar por Invocação-Especial 1 "Super Agente ESPIRÃO" do seu Deck. \r\nSe um "Super Agente ESPIRÃO" que você controla for destruído em batalha ou enviado para o Cemitério enquanto este card estiver no seu Cemitério: você pode banir este card do seu Cemitério; devolva 1 "Super Agente ESPIRÃO" do seu Cemitério para a sua mão.','\r',char(13)),'\n',char(10)),'Fazer o ATK do monstro do seu oponente se tornar 0','Invocar "Super Agente ESPIRÃO" do Deck por Invocação Especial','Adicionar "Super Agente ESPIRÃO" do seu Cemitério à sua mão','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64753988,'Reino Cibersombrio',replace(replace('Quando este card for ativado: você pode adicionar 1 monstro "Cibersombrio(a)" do seu Deck à sua mão, com um nome diferente que o dos cards no seu Cemitério. \r\nDurante sua Fase Principal, você pode: imediatamente depois que este efeito resolver, Invoque por Invocação-Normal 1 monstro "Cibersombrio(a)". \r\nVocê só pode usar o efeito anterior de "Reino Cibersombrio" uma vez por turno. \r\nSe você equipou um monstro do seu Cemitério pelo efeito de um monstro "Cibersombrio(a)" que foi ativado quando ele foi Invocado por Invocação-Normal ou Especial, em vez disso, você pode equipar do Cemitério do seu oponente. \r\nVocê só pode ativar 1 "Reino Cibersombrio" por turno.','\r',char(13)),'\n',char(10)),'','Adicionar 1 monstro "Cibersombrio(a)" do seu Deck à sua mão?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64756282,'Fazticeira Genni',replace(replace('Durante a Fase Principal (Efeito Rápido): você pode oferecer este card como Tributo e descartar 1 Magia; Invoque por Invocação-Especial 1 monstro "Fazticeira" do seu Deck, exceto "Fazticeira Genni". \r\nVocê pode banir este card e 1 Magia "Fazticeira" do seu Cemitério; este efeito se torna o efeito dessa Magia quando esse card for ativado. \r\nVocê só pode usar cada efeito de "Fazticeira Genni" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64765016,'Paleozoico Marrella',replace(replace('Envie 1 Armadilha do seu Deck para o Cemitério. \r\nUma vez por Corrente, quando um Card de Armadilha for ativado enquanto este card estiver no seu Cemitério: você pode Invocar este card por Invocação-Especial como um Monstro Normal (Aqua/ÁGUA/Nível 2/ATK 1200/DEF 0).	\r\n(Este card NÃO é considerado como uma Armadilha.) \r\nSe Invocado desta forma, este card não é afetado por efeitos de monstro e, além disso, bana-o quando ele deixar o campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64767757,'Materriator Crítico',replace(replace('Quando um Card de Magia/Armadilha, ou efeito de monstro, for ativado: adicione à sua mão 1 de suas matérias associadas a um Monstro Xyz "Materriator" que você controla e, se isso acontecer, negue a ativação e, depois, aplique o seguinte efeito, de acordo com o tipo de card adicionado.\r\n● Monstro: Coloque 1 card da sua mão no fundo do Deck.\r\n● Magia: Monstros Xyz "Materriator" que você controla ganham 1000 de ATK.\r\n● Armadilha: Você pode Baixar esse card adicionado.	\r\nVocê só pode ativar 1 "Materriator Crítico" por turno.','\r',char(13)),'\n',char(10)),'Negar','','Baixar?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64788463,'O Cavaleiro do Rei','Quando este card for Invocado por Invocação-Normal enquanto você controlar "O Cavaleiro da Rainha": você pode Invocar por Invocação-Especial 1 "O Cavaleiro do Valete" do seu Deck.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64797746,'Relíquia Nórdica Svalinn',replace(replace('Se você controlar um monstro "Aesir": até o final deste turno, você pode negar os efeitos de todos os cards com a face para cima que seu oponente controla atualmente. \r\nVocê pode oferecer como Tributo 1 monstro "Nórdic" e, depois, escolha 1 monstro "Aesir" no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê só pode usar 1 efeito de "Relíquia Nórdica Svalinn" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Negar o efeito','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64801562,'Coração de Água Pura',replace(replace('Se o ATK do monstro equipado é 1300 ou superior, destrua este card. \r\nO monstro equipado com este card não é destruído como resultado de um combate ou por um efeito de um card que o designa como alvo. \r\nO dano de batalha é calculado normalmente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64804137,'Trapestrela Tambormatis da Banda',replace(replace('2 monstros "Trapestrela"	\r\nMonstros Link "Trapestrela" que você controla que apontem para este card ganham 1000 de ATK. \r\nVocê só pode usar cada um dos seguintes efeitos de "Trapestrela Tambormatis da Banda" uma vez por turno. \r\nSe este card for Invocado por Invocação-Fusão: você pode adicionar 1 card "Trapestrela" do seu Deck à sua mão com um nome diferente dos cards que você controla e no seu Cemitério. \r\nSe dano de efeito for causado (exceto durante a Etapa de Dano): você pode escolher 1 monstro com a face para cima no campo; o ATK dele se torna 0.','\r',char(13)),'\n',char(10)),'Adicione à sua mão 1 card "Trapestrela"','Altere o ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64804316,'Sereia Fantardil',replace(replace('Não pode ser Invocado por Invocação-Normal, a não ser que você controle um monstro "Fantardil". \r\nUma vez por turno, durante sua Fase Principal: você pode colocar este card com a face para baixo em Posição de Defesa. \r\nSe este card for Invocado por Invocação-Normal ou virado com a face para cima: envie os 2 cards do topo do seu Deck para o Cemitério e, depois, se algum dos cards era um card "Fantardil", você pode aplicar 1 desses efeitos.\r\n● Adicione 1 Magia/Armadilha "Fantardil" do seu Deck à sua mão.\r\n● Coloque 1 Monstro de Efeito que seu oponente controla com a face para baixo em Posição de Defesa.','\r',char(13)),'\n',char(10)),'Enviar os 2 cards do topo do seu Deck para o Cemitério','Adicionar à sua mão 1 Magia/Armadilha "Fantardil" do seu Deck','Mudar 1 Monstro de Efeito que o seu oponente controla para a Posição de Defesa com a face para baixo','Não fazer nada','','','','','','','','','','','','');
INSERT INTO texts VALUES(64806765,'Tengu Corvo',replace(replace('Se este card em sua posse for destruído por um efeito de card do oponente e enviado para o seu Cemitério, ou se este card for Invocado por Invocação-Especial do Cemitério: você pode escolher 1 monstro em Posição de Ataque que seu oponente controla; destrua-o. \r\nVocê só pode usar este efeito de "Tengu Corvo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64815084,'Evo-Ramo','Escolha 1 monstro do Tipo Réptil com a face para cima que você controla; destrua-o e Invoque por Invocação-Especial 1 monstro "Evoltil" com a face para baixo em Posição de Defesa do seu Deck.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64867422,'"Infernarmas Nobres - Hauteclere"',replace(replace('Enquanto este card estiver equipado a um monstro: você pode escolher 1 monstro com a face para cima que você controla; neste turno, você não pode declarar ataques, exceto com esse monstro e, além disso, neste turno, ele ganha a habilidade de realizar um segundo ataque durante cada Fase de Batalha e, depois, destrua este card. \r\nSe este card for enviado para o Cemitério porque o monstro equipado foi enviado para o Cemitério: você pode escolher 1 monstro com a face para cima no campo; destrua-o. \r\nVocê só pode usar 1 efeito de ""Infernarmas Nobres - Hauteclere"" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64880894,'Guerreiro Algoz da Poeira Estelar',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nQuando este card for Invocado por Invocação-Sincro: você pode comprar 1 card. \r\nVocê só pode usar este efeito de "Guerreiro Algoz da Poeira Estelar" uma vez por turno. \r\nEste card pode atacar todos os monstros Invocados por Invocação-Especial que seu oponente controla, uma vez cada.','\r',char(13)),'\n',char(10)),'Compre 1 card(s)','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64881644,'Refrão, a Cantora Melodiosa',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nVocê pode escolher 1 Monstro de Fusão "Melodiosa(o)" que você controla; envie 1 monstro "Melodiosa(o)" do seu Deck para o Cemitério e, se isso acontecer, o monstro alvo ganha ATK igual ao Nível desse monstro enviado para o Cemitério x 200 até o final deste turno. \r\nVocê só pode usar este efeito de "Refrão, a Cantora Melodiosa" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 monstro "Melodiosa(o)" do seu Deck à sua mão, exceto "Refrão, a Cantora Melodiosa". \r\nSe um ou mais Monstros de Fusão "Melodiosa(o)" forem Invocados por Invocação-Especial no seu campo, enquanto este card estiver com a face para cima no seu Deck Adicional (exceto durante a Etapa de Dano): você pode colocar este card na sua Zona de Pêndulo. \r\nVocê só pode usar cada efeito de "Refrão, a Cantora Melodiosa" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64892035,'Orc Tardio','Este card não pode atacar no turno em que for Invocado por Invocação-Normal.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64898834,'T.G. Dragão Catapulta','Uma vez por turno: você pode Invocar por Invocação-Especial 1 monstro "T.G." Regulador de Nível 3 ou menos da sua mão.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64910482,'T.G. Mago Cibernético',replace(replace('Se este card que você controla seria usado como Matéria Sincro para um monstro "T.G.", os monstros "T.G." na sua mão podem ser usados como as Matérias Sincro não-Reguladores. \r\nUma vez por turno, durante a Fase Final, se este card estiver no Cemitério porque foi destruído no campo e enviado para lá neste turno: você pode adicionar 1 monstro "T.G." do seu Deck à sua mão, exceto "T.G. Mago Cibernético".','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64911387,'Materriator Zeptasa',replace(replace('Se você controlar um card "Materriator": você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe este card for Invocado por Invocação-Normal ou Especial, ou virado com a face para cima: você pode adicionar 1 card "Materriator" do seu Deck à sua mão, exceto "Materriator Zeptasa" e, depois, você pode adicionar à sua mão ou Invocar por Invocação-Especial, 1 Monstro Normal de Nível 3 do seu Cemitério. \r\nVocê só pode usar cada efeito de "Materriator Zeptasa" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Adicionar à mão','Escolher um Monstro Normal?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64926005,'Samurai da Barreira de Gelo','Se este card com a face para cima em Posição de Ataque for colocado com a face para cima em Posição de Defesa: destrua este card e, se isso acontecer, compre 1 card.','Destruir e comprar 1 card','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64927055,'O Coro no Céu',replace(replace('Pague 1000 PV e, depois, escolha 1 monstro Fada no seu Cemitério; adicione-o à sua mão e, depois, se "O Santuário no Céu" estiver no campo ou em qualquer Cemitério, você pode adicionar à sua mão 1 dos seus "O Santuário no Céu" banidos, ou 1 dos seus cards banidos que o mencione. \r\nVocê só pode ativar 1 "O Coro no Céu" por turno.','\r',char(13)),'\n',char(10)),'Adicionar um card banido à sua mão?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64952266,'Contra o Vento','Escolha 1 monstro "Asanegra" no seu Cemitério; sofra dano igual ao ATK do alvo e, se isso acontecer, adicione-o à sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64961254,'Orientação da Deusa Verdandi',replace(replace('Quando este card for ativado: se todos os monstros que você controla forem monstros "Valquíria-" (mín. 1), você pode adicionar 1 "Veredito da Deusa Urd" do seu Deck à sua mão. \r\nUma vez por turno: você pode declarar 1 tipo de card (Monstro, Magia ou Armadilha); revele o card do topo do Deck do seu oponente e se era do tipo declarado, ele Baixa o card no seu próprio campo. \r\nCaso contrário, ele o adiciona à sua mão. \r\nVocê só pode ativar 1 "Orientação da Deusa Verdandi" por turno.','\r',char(13)),'\n',char(10)),'Adicionar "Veredito da Deusa Urd" à sua mão?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64964750,'Banir Vendas',replace(replace('Declare 1 nome de card; pelo resto deste turno, seu oponente não pode ativar cards, ou os efeitos de cards, com o mesmo nome original que o desse card declarado. \r\nAs mesmas restrições se aplicam a você, mas pelo resto deste Duelo, em vez de apenas neste turno. \r\nVocê só pode ativar 1 "Banir Vendas" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64966519,'Despachapaparazzi',replace(replace('2 Monstros de Efeito	\r\nQuando outro monstro que você controla for escolhido como alvo de um ataque: você pode mudar o alvo do ataque para este card e realizar o cálculo de dano. \r\nQuando este card for destruído em batalha com um monstro do oponente: você pode destruir esse monstro do oponente e, se isso acontecer, ganhe PV igual à metade do ATK original desse monstro. \r\nVocê só pode usar cada efeito de "Despachapaparazzi" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64973287,'Dinonévoa Pteran',replace(replace('Escala de Pêndulo = 3\r\n[ Efeito de Pêndulo ]\r\nSe outro(s) card(s) "Dinonévoa" que você controla seria(m) destruído(s) em batalha ou por um efeito de card do oponente, em vez disso, você pode destruir este card.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nQuando este card destruir um monstro do oponente em batalha: você pode adicionar 1 card "Dinonévoa" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Usar o efeito de "Dinonévoa Pteran" em vez de ser destruído?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64973456,'Renascimento da Víbora','Se todos os monstros no seu Cemitério forem Réptil: escolha 1 não-Regulador no seu Cemitério; Invoque-o por Invocação-Especial, mas destrua-o durante a Fase Final deste turno.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64977888,'Flautista Aprendiz',replace(replace('VIRE: Você pode Invocar 1 monstro da sua mão por Invocação-Especial.\r\nSe este card for destruído em batalha ou por um efeito de card e enviado para o Cemitério: você pode Invocar 1 monstro da sua mão por Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64990807,'Triângulo Mágico da Barreira de Gelo','Revele 3 monstros "Barreira de Gelo" com nomes diferentes na sua mão e, depois, escolha 1 card que seu oponente controla; destrua o alvo e, se isso acontecer, Invoque por Invocação-Especial 1 monstro "Barreira de Gelo" da sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(64998567,'Maldição de Diabell',replace(replace('Se você controlar 2 ou mais monstros "Diabell": envie 1 monstro que você controla para o Cemitério; destrua todos os cards com a face para cima que seu oponente controla. \r\nSe este card for enviado para o Cemitério, ou banido, da mão ou do Deck: você pode adicionar 1 Magia/Armadilha "Diabell" do seu Deck à sua mão, exceto "Maldição de Diabell". \r\nVocê só pode usar cada efeito de "Maldição de Diabell" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65017789,'Pintora do Clima Neve',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode colocar 1 Magia/Armadilha "do Clima" do seu Deck com a face para cima na sua Zona de Magias & Armadilhas. \r\nVocê só pode usar este efeito de "Pintora do Clima Neve" uma vez por turno. \r\nUma vez por turno, durante a Fase de Apoio do turno seguinte ao qual este card foi banido do campo para ativar um efeito de card "do Clima": você pode Invocar este card banido por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Baixar 1 Magia/Armadilha "do Clima" do seu Deck','Invoque este card banido por Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65025250,'Yosenju Shinchu E',replace(replace('Escala de Pêndulo = 3\r\n[ Efeito de Pêndulo ]\r\nSe um ou mais monstros "Yosenju" que você controla seriam destruídos em batalha ou por um efeito de card, em vez disso, você pode destruir este card.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe este card for Invocado por Invocação-Normal: coloque-o em Posição de Defesa. \r\nSeu oponente não pode escolher monstros "Yosenju" que você controla como alvos de efeitos de card, exceto este.','\r',char(13)),'\n',char(10)),'Mudar para Posição de Defesa','Usar o efeito de "Yosenju Shinchu E" em vez de ser destruído?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65026212,'Maximus Koa''ki Meiru',replace(replace('Este card não pode ser Invocado por Invocação-Normal ou Baixado. \r\nEste card só pode ser Invocado por Invocação-Especial ao remover de jogo 1 "Núcleo de Ferro de Koa''ki Meiru" da sua mão. \r\nDurante cada uma das suas Fases Finais, destrua este card a não ser que você envie 1 "Núcleo de Ferro de Koa''ki Meiru" ou 1 monstro "Koa''ki Meiru" da sua mão ao Cemitério. \r\nUma vez por turno, durante sua Fase Principal, você pode selecionar e destruir 1 card que seu oponente controla.','\r',char(13)),'\n',char(10)),'Escolha 1 "Núcleo de Ferro de Koa''ki Meiru" para enviar para o Cemitério','Enviar para o Cemitério um monstro cujo nome contenha "Koa''ki Meiru"','Destruir "Maximus Koa''ki Meiru"','Destruir','','','','','','','','','','','','');
INSERT INTO texts VALUES(65029288,'Garra Metálica Camarartista de Olhos Anômalos',replace(replace('1 monstro "Olhos Anômalos" + 1 monstro "Camarartista"	\r\nNão pode ser usado como Matéria de Fusão. \r\nSe este card foi Invocado por Invocação-Fusão com "Polimerização", ele não é afetado por outros efeitos de cards. \r\nQuando este card declarar um ataque: todos os monstros que você controla atualmente ganham 300 de ATK até o final da Fase de Batalha.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Fusão com o efeito de "Polimerização/Fusão"','Aumentar ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65033975,'Rainha Azamina',replace(replace('(Este card deve ser sempre considerado como um card "Despojos do Pecado".)	\r\nSe este card na sua mão ou no campo for enviado para o Cemitério ou banido por um efeito ativado: você pode Invocá-lo por Invocação-Especial. \r\nQuando um monstro "Azamina" ou "Floresta Branca" seu destruir um monstro do oponente em batalha: você pode escolher 1 Magia/Armadilha "Despojos do Pecado" no seu Cemitério; adicione-a à sua mão. \r\nVocê só pode usar cada efeito de "Rainha Azamina" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Retornar uma Magia/Armadilha para a mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65037172,'Sábia Ciberso',replace(replace('Você pode Invocar este card por Invocação-Ritual com "Cinet Ritual". \r\nDurante sua Fase Principal: você pode Invocar por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional, ao banir matérias mencionadas nele do seu campo ou Cemitério, incluindo um monstro Ciberso. \r\nSe este card for enviado para o Cemitério como Matéria Sincro: você pode escolher 1 monstro Ciberso ou 1 Magia de Ritual no seu Cemitério; adicione-o à sua mão. \r\nVocê só pode usar cada efeito de "Sábia Ciberso" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65046521,'Parceria dos Possuídos',replace(replace('Invoque por Invocação-Especial 1 monstro Mago com 1500 de DEF, da sua mão ou do Cemitério, em Posição de Ataque ou com a face para baixo em Posição de Defesa e, depois, se você controlar monstros com 2 ou mais Atributos diferentes, você pode destruir 1 card com a face para cima no campo. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 Magia/Armadilha Contínua "Possuído(a)" no seu Cemitério; coloque-a com a face para cima no seu campo. \r\nVocê só pode usar 1 efeito de "Parceria dos Possuídos" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','Destruir 1 card?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65056481,'Cavaleirostélite Alsahm',replace(replace('Se este card for Invocado: você pode causar 1000 de dano ao seu oponente. \r\nVocê só pode usar este efeito de "Cavaleirostélite Alsahm" uma vez por turno.','\r',char(13)),'\n',char(10)),'Dano aos Pontos de Vida','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65064143,'Flor Antiaérea','Ofereça como Tributo 1 monstro Inseto no seu campo para causar 800 de dano ao seu oponente.','Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65079854,'Espinhos da Malícia',replace(replace('Só pode ser equipado a "Dragão da Rosa Negra" ou um monstro Planta. \r\nEle ganha 600 de ATK. \r\nSe o monstro equipado atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente. \r\nSe o monstro equipado atacar um monstro, depois do cálculo de dano: o monstro atacado perde 600 de ATK/DEF. \r\nUm monstro do oponente que batalhar com o monstro equipado não pode ser destruído nessa batalha.','\r',char(13)),'\n',char(10)),'Reduzir ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65100616,'Link Infra-Planador',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) para uma zona sua para a qual um Monstro Link apontar. \r\nVocê só pode Invocar "Link Infra-Planador" por Invocação-Especial uma vez por turno desta forma.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65107325,'Agendamento Azedo - Vinagre Vermelho Vamoose',replace(replace('Ative este card apenas se seu oponente controlar um card na coluna deste card Baixado; devolva para a mão todos os outros cards na coluna deste card. \r\nNenhum duelista pode usar as zonas não utilizadas na coluna deste card. \r\nVocê só pode controlar 1 "Agendamento Azedo - Vinagre Vermelho Vamoose".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65114115,'Corte das Sete Estrelas - Aniquilador de Exércitos Hagun',replace(replace('Escolha 1 monstro com a face para cima que você controla; equipe-o com 1 monstro de Nível 7 com o mesmo Tipo, mas um nome diferente da sua mão ou do Deck como uma Magia de Equipamento que concede a ele 700 de ATK, mas devolva essa Magia de Equipamento para a mão durante a Fase Final. \r\nQuando um monstro de Nível/Classe 8 ou mais do seu oponente for destruído em batalha, enquanto este card estiver no seu Cemitério: você pode adicionar este card à sua mão. \r\nVocê só pode ativar 1 "Corte das Sete Estrelas - Aniquilador de Exércitos Hagun" por turno.','\r',char(13)),'\n',char(10)),'','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65118318,'Ladrão de Túmulos Tolo',replace(replace('Envie 1 card que menciona "Mago do Tempo Sombrio" do seu Deck ao Cemitério, exceto "Ladrão de Túmulos Tolo", então você pode Invocar por Invocação-Especial 1 monstro de qualquer Cemitério para o seu campo.\r\nVocê pode banir este card do seu Cemitério; Baixe 1 destes cards para o seu campo.\r\n● Magia/Armadilha no seu Cemitério que menciona "Mago do Tempo Sombrio", exceto "Ladrão de Túmulos Tolo".\r\n● Magia/Armadilha no Cemitério do seu oponente.	\r\nVocê só pode usar cada um dos efeitos de "Ladrão de Túmulos Tolo" uma vez por turno.','\r',char(13)),'\n',char(10)),'Enviar para o Cemitério','Baixar','Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65124425,'Receptáculo para o Ciclo do Dragão',replace(replace('Envie 1 monstro Wyrm do seu Deck para o Cemitério e, depois, se você controlar um Monstro que não seja de Efeito com a face para cima, você pode adicionar do seu Deck à sua mão 1 monstro "Tenyi" com um nome diferente que o do monstro enviado para o Cemitério. \r\nVocê só pode ativar 1 "Receptáculo para o Ciclo do Dragão" por turno.','\r',char(13)),'\n',char(10)),'Adicionar 1 monstro "Tenyi" à sua mão?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65149697,'Esmagador Genex-R','Quando este card for Invocado por Invocação-Normal: você pode adicionar 1 monstro "Genex-R" de Nível 4 do seu Deck à sua mão.','Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65150219,'Habilidade Ninjitsu do Congelamento',replace(replace('Quando um monstro do oponente declarar um ataque, se você controlar um monstro "Ninja": você pode virar este card com a face para cima; negue o ataque e encerre a Fase de Batalha. \r\nEnquanto este card estiver com a face para cima no campo e você controlar um monstro "Ninja", os monstros que seu oponente controla não podem mudar suas posições de batalha.','\r',char(13)),'\n',char(10)),'Negar o ataque','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65155517,'Velocidaroide Coronel Bate-Bate',replace(replace('Escala de Pêndulo = 8\r\n[ Efeito de Pêndulo ]\r\nVocê pode banir 1 card "Velocidaroide" do seu Cemitério; coloque 1 Monstro Pêndulo "Velocidaroide" do seu Deck na sua Zona de Pêndulo e, além disso, você não pode Invocar por Invocação-Especial pelo resto deste turno, exceto monstros de VENTO. \r\nVocê só pode usar este efeito de "Velocidaroide Coronel Bate-Bate" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe este card no campo for destruído em batalha ou por um efeito de card: você pode Invocar por Invocação-Especial 1 "Velocidaroide Coronel Bate-Bate" como um Regulador da sua mão, do Deck ou do Cemitério. \r\nDurante o cálculo de dano, se um monstro "Asas Transparentes" seu batalhar, enquanto este card estiver com a face para cima no seu Deck Adicional: você pode banir este card e, se isso acontecer, esse monstro ganha 700 de ATK. \r\nVocê só pode usar cada efeito de "Velocidaroide Coronel Bate-Bate" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Aumentar ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65156847,'Garuda de Neoflamvell','Uma vez por turno, durante sua Fase Final, se você controlar outro monstro "Flamvell": escolha 1 card no Cemitério do seu oponente; bana-o.','Banir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65169794,'Pendente Negro',replace(replace('O monstro equipado ganha 500 de ATK. \r\nQuando este card for enviado do campo para o Cemitério: cause 500 de dano ao seu oponente.','\r',char(13)),'\n',char(10)),'Cause 500 de dano ao seu oponente','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65170459,'Mistar Menino Estrela',replace(replace('2 monstros de ÁGUA	\r\nTodos os monstros de ÁGUA no campo ganham 500 de ATK e DEF e, além disso, todos os monstros de FOGO no campo perdem 400 de ATK e DEF. \r\nSe este card for destruído em batalha ou por um efeito de card: você pode escolher 1 monstro de ÁGUA no seu Cemitério; adicione-o à sua mão. \r\nVocê só pode usar este efeito de "Mistar Menino Estrela" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65172015,'A a Z - Dragão Canhão Banimento',replace(replace('"ABC - Dragão Banimento" + "XYZ - Dragão Canhão"	\r\nDeve ser Invocado por Invocação-Especial (do seu Deck Adicional) ao banir cards que você controla com os nomes originais acima e não pode ser Invocado por Invocação-Especial de nenhuma outra forma. \r\n(Você não usa "Polimerização".) \r\nDurante o turno de qualquer duelista, quando seu oponente ativar um Card de Magia/Armadilha ou efeito de monstro: você pode descartar 1 card; negue a ativação e, se isso acontecer, destrua esse card. \r\nDurante o turno de qualquer duelista: você pode banir este card e, depois, escolher 1 de cada dos seus "ABC - Dragão Banimento" e "XYZ - Dragão Canhão" banidos; Invoque-os por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Descarte 1 card: negue a ativação e destrua-o','Banir este card; Invoque por Invocação Especial os monstros banidos','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65187687,'Dragão Esquelético Felgrand',replace(replace('1 Regulador Zumbi + 1+ monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Especial: você pode escolher 1 monstro que seu oponente controla ou no Cemitério dele; bana-o. \r\nSe um ou mais monstros forem Invocados por Invocação-Especial de qualquer Cemitério, enquanto este monstro estiver no campo (exceto durante a Etapa de Dano): você pode escolher 1 outro monstro com a face para cima no campo; negue seus efeitos até o final deste turno. \r\nVocê só pode usar cada efeito de "Dragão Esquelético Felgrand" uma vez por turno.','\r',char(13)),'\n',char(10)),'Banir um monstro do oponente','Negue os efeitos dos monstros no Campo','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65192027,'Dragão Negro Armado',replace(replace('(Este card deve ser sempre considerado como um card "Dragão Armado".)	\r\nNão pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao ter exatamente 3 monstros de TREVAS no seu Cemitério. \r\nVocê pode banir 1 monstro de TREVAS do seu Cemitério e, depois, escolha 1 card no campo; destrua o alvo.','\r',char(13)),'\n',char(10)),'Não pode ser Invocado por Invocação Normal','Só pode ser Invocado por Invocação Especial se você tiver 3 monstros de TREVAS no seu Cemitério','Destrua 1 card no Campo','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65193366,'Domador Avatar da Besta Espiritual Winda',replace(replace('(Este card deve ser sempre considerado como um card "Domador da Besta Espiritual".)	\r\nSe este card em posse do seu dono for destruído por um card do oponente: você pode Invocar por Invocação-Especial 1 monstro "Besta Espiritual" do seu Deck ou Deck Adicional, ignorando suas condições de Invocação. \r\nVocê só pode Invocar um ou mais "Domador Avatar da Besta Espiritual Winda" por Invocação-Especial uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65195959,'Camarartista Cartaruga','Uma vez por turno: você pode escolher até 2 monstros com a face para cima no campo; aumente o Nível deles em 1.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65196094,'Variedade Revelada',replace(replace('Devolva 1 Monstro Sincro com a face para cima que você controla ao Deck Adicional para selecionar e Invocar por Invocação-Especial um ou mais monstros Reguladores do seu Cemitério cuja soma dos Níveis seja igual ao Nível desse Monstro Sincro. \r\nVocê não pode Invocar por Invocação-Sincro no turno em que você ativar este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65236257,'Gênesis Cavaleirostrela','Destrua Cards de Magia/Armadilha no campo igual ao número de outros cards "Cavaleirost" que você controla.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65240384,'Grande Escudo Gardna',replace(replace('Quando um Card de Magia for ativado que escolha como alvo este card com a face para baixo (e nenhum outro card) (Efeito Rápido): coloque este card com a face para cima em Posição de Defesa e, se isso acontecer, negue a ativação. \r\nSe este card for atacado, coloque-o em Posição de Ataque no final da Etapa de Dano.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65247798,'Yosenju Kama 1',replace(replace('Se este card for Invocado por Invocação-Normal, você pode: imediatamente depois de resolver este efeito, Invocar por Invocação-Normal 1 monstro "Yosenju" da sua mão, exceto "Yosenju Kama 1". \r\nSe você controlar outro monstro "Yosenju": você pode escolher 1 card com a face para cima que seu oponente controla; devolva-o para a mão. \r\nEste efeito só pode ser usado uma vez enquanto este card estiver com a face para cima no campo. \r\nUma vez por turno, durante a Fase Final, se este card foi Invocado por Invocação-Normal neste turno: devolva-o para a mão.','\r',char(13)),'\n',char(10)),'Invocar','Retornar à mão','Retornar à mão','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65260293,'Mago do Elemento',replace(replace('Este monstro obtém o(s) seguinte(s) efeito(s) enquanto existir(em) monstro(s) com o seguinte Atributo no Campo.\r\n● ÁGUA: O controle deste card não pode ser mudado.\r\n● VENTO: Se este card destruir um monstro como resultado de um combate, este card pode atacar mais uma vez logo em seguida.','\r',char(13)),'\n',char(10)),'Continuar atacando','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65261141,'Dor do Pesadelo',replace(replace('Durante sua Fase Principal: você pode destruir 1 monstro de TREVAS na sua mão ou no campo com a face para cima e, se isso acontecer, adicione 1 "Yubel" ou 1 card que o mencione, do seu Deck à sua mão, exceto "Dor do Pesadelo". \r\nVocê só pode usar este efeito de "Dor do Pesadelo" uma vez por turno. \r\nEnquanto você controlar um monstro "Yubel", os monstros do seu oponente que podem atacar devem atacar monstros "Yubel". \r\nSeu oponente sofre qualquer dano de batalha que você teria sofrido das batalhas envolvendo seus monstros "Yubel".','\r',char(13)),'\n',char(10)),'Destruir e buscar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65268179,'Despertar dos Possuídos - Arquidemônio Nefárior',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão ou do Deck) ao enviar para o Cemitério 1 monstro Mago com a face para cima que você controla e 1 monstro de TERRA de Nível 4 ou menos com a face para cima que você controla. \r\nVocê só pode usar cada um dos seguintes efeitos de "Despertar dos Possuídos - Arquidemônio Nefárior" uma vez por turno. \r\nQuando este card for Invocado por Invocação-Especial por seu efeito: você pode Invocar por Invocação-Especial 1 monstro de Nível 4 ou menos do seu Cemitério, mas negue seus efeitos. \r\nSe este card for enviado do campo para o Cemitério: você pode adicionar 1 card "Arte Espiritual da Terra" ou 1 Magia/Armadilha "Possuído(a)" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65277087,'Gulldo Gusto','Quando este card for enviado do campo para o Cemitério: Você pode Invocar por Invocação-Especial 1 monstro "Gusto" de Nível 2 ou menos do seu Deck.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65282484,'Voltanis das Trevas',replace(replace('Depois que 1 Card de Armadilha de Resposta que você controla foi ativado e tiver resolvido, você pode oferecer como Tributo 1 monstro de TREVAS para Invocar este card por Invocação-Especial da sua mão. \r\nSe este card for Invocado por Invocação-Especial desta forma, destrua 1 card no campo.','\r',char(13)),'\n',char(10)),'Invocação Especial','Destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65285459,'Drianome de Solaravalon',replace(replace('2+ monstros Planta	\r\nEste card não pode ser escolhido como alvo de ataques, mas isso não impede que seu oponente ataque você diretamente. \r\nTrês vezes por turno, se você sofrer dano de batalha ou de efeito: você pode ganhar esse tanto de PV e, se isso acontecer, Invoque por Invocação-Especial 1 monstro "Solarvinhas" do seu Deck Adicional. \r\nUma vez por turno, quando um monstro para o qual este card apontar for escolhido como alvo de um ataque: você pode negar o ataque e, se isso acontecer, mova esse monstro que você controla para outra das suas Zonas de Monstros Principais.','\r',char(13)),'\n',char(10)),'Ganhar PV e Invocar por Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65287621,'Driceratops Negro','Se este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65289956,'Como Diabell',replace(replace('Se uma ou mais Magias/Armadilhas forem enviadas para o Cemitério por um efeito de card: Baixe 1 Magia/Armadilha da sua mão ou do Cemitério, mas ela não pode ser ativada neste turno. \r\nDurante sua Fase Principal: você pode banir 3 Magias/Armadilhas do seu Cemitério, incluindo este card; Invoque por Invocação-Especial 1 monstro "Diabell" da sua mão ou do Cemitério. \r\nVocê só pode usar cada efeito de "Como Diabell" uma vez por turno.','\r',char(13)),'\n',char(10)),'Efeito de Baixar','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65301952,'Mago Alquimista',replace(replace('3 monstros do Tipo Mago de Nível 4	\r\nEste card ganha 200 de ATK para cada Card de Magia no seu Cemitério. \r\nUma vez por turno, durante sua Fase Final: Você pode desassociar 1 Matéria Xyz deste card e enviar 1 card da sua mão ao Cemitério; escolha 1 Card de Magia do seu Deck e, depois, Baixe-o em sua Zona de Cards de Magia & Armadilha.','\r',char(13)),'\n',char(10)),'Baixar 1 Card de Magia','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65302903,'Dominusteer Rosepamela',replace(replace('Cards com a face para baixo na sua Zona de Magia & Armadilhas não podem ser destruídas por efeitos.\r\nVocê só pode usar cada um dos seguintes efeitos de "Dominusteer Rosepamela" uma vez por turno.\r\nDurante o turno do seu oponente (Efeito Rápido): você pode revelar este card na sua mão; adicionar 1 card "Purga Dominus" do seu Deck à sua mão, então descarte 1 card.\r\nSe este card é Invocado por Invocação-Normal ou Especial: você pode Baixar 1 Armadilha "Dominadores" ou "Purga Dominus" do seu Deck ou Cemitério. \r\nEla pode ser ativada neste turno.','\r',char(13)),'\n',char(10)),'Efeito de busca','Efeito de Baixar','Ativar aplicando o efeito de "Dominusteer Rosepamela".','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65302904,'Dominusteer Rosepamela',replace(replace('Cards com a face para baixo na sua Zona de Magia & Armadilhas não podem ser destruídas por efeitos.\r\nVocê só pode usar cada um dos seguintes efeitos de "Dominusteer Rosepamela" uma vez por turno.\r\nDurante o turno do seu oponente (Efeito Rápido): você pode revelar este card na sua mão; adicionar 1 card "Purga Dominus" do seu Deck à sua mão, então descarte 1 card.\r\nSe este card é Invocado por Invocação-Normal ou Especial: você pode Baixar 1 Armadilha "Dominadores" ou "Purga Dominus" do seu Deck ou Cemitério. \r\nEla pode ser ativada neste turno.','\r',char(13)),'\n',char(10)),'Efeito de busca','Efeito de Baixar','Ativar aplicando o efeito de "Dominusteer Rosepamela".','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65303664,'Babuíno Amarelo, Arqueiro da Floresta','Quando um monstro do Tipo Besta que você controla for destruído em batalha e enviado ao Cemitério, você pode remover de jogo 2 monstros do Tipo Besta no seu Cemitério para Invocar este card por Invocação-Especial da sua mão.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65305468,'Número F0: Futuro Utópico',replace(replace('2 Monstros Xyz com a mesma Classe, exceto monstros "Número"	\r\n(A Classe original deste card deve ser sempre considerada como 1.)	\r\nNão pode ser destruído em batalha e nenhum duelista sofre qualquer dano de batalha dos ataques envolvendo este card. \r\nNo final da Etapa de Dano, se este card batalhou um monstro do oponente: até o final da Fase de Batalha, você pode assumir o controle desse monstro do oponente. \r\nSe este card com a face para cima no campo seria destruído por um efeito de card, em vez disso, você pode desassociar 1 matéria deste card.','\r',char(13)),'\n',char(10)),'Tomar controle','Usar o efeito de "Número F0: Futuro Utópico" em vez de ser destruído?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65305469,'Número F0: Futuro Utópico',replace(replace('2 Monstros Xyz com a mesma Classe, exceto monstros "Número"	\r\n(A Classe original deste card deve ser sempre considerada como 1.)	\r\nNão pode ser destruído em batalha e nenhum duelista sofre qualquer dano de batalha dos ataques envolvendo este card. \r\nNo final da Etapa de Dano, se este card batalhou um monstro do oponente: até o final da Fase de Batalha, você pode assumir o controle desse monstro do oponente. \r\nSe este card com a face para cima no campo seria destruído por um efeito de card, em vez disso, você pode desassociar 1 matéria deste card.','\r',char(13)),'\n',char(10)),'Tomar controle','Usar o efeito de "Número F0: Futuro Utópico" em vez de ser destruído?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65305978,'Santuário do Rei de Fogo',replace(replace('Quando este card for ativado: você pode colocar 1 "Ilha do Rei de Fogo" do seu Deck com a face para cima na sua Zona do Campo. \r\nUma vez por turno, se um card na sua Zona do Campo seria destruído por um efeito de card, em vez disso, você pode destruir 1 monstro de FOGO na sua mão ou no campo com a face para cima. \r\nUma vez por turno, se seu oponente Invocar um ou mais monstros por Invocação-Especial, você pode: imediatamente depois que este efeito resolver, Invocar por Invocação-Xyz 1 Monstro Xyz de FOGO usando apenas monstros "Rei(s) de Fogo" que você controla. \r\nVocê só pode ativar 1 "Santuário do Rei de Fogo" por turno.','\r',char(13)),'\n',char(10)),'Colocar "Ilha do Rei de Fogo"?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65314286,'Sadion, o Senhor do Tempo',replace(replace('Não pode ser Invocado por Invocação-Especial do Deck. \r\nSe você não controlar nenhum monstro, você pode Invocar este card por Invocação-Normal sem oferecer Tributo. \r\nNão pode ser destruído em batalha ou por efeitos de card. \r\nVocê não sofre dano de batalha dos ataques que envolvem este card. \r\nNo final da Fase de Batalha, se este card batalhou e você tiver menos que 4000 PV: seus PV se tornam 4000. \r\nUma vez por turno, durante sua Fase de Apoio: embaralhe este card no Deck.','\r',char(13)),'\n',char(10)),'Invocação Normal sem Tributo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65325949,'Kuzuha, a Divindade Encantadora Asutra',replace(replace('Você pode Invocar por Invocação-Especial este card (da sua mão) revelando 1 card com a face para baixo que você controla e o retornando para a mão/Deck Adicional. \r\nVocê só pode Invocar por Invocação-Especial "Kuzuha, a Divindade Encantadora Asutra" uma vez por turno dessa forma.\r\nVocê só pode usar cada um dos seguintes efeitos de "Kuzuha, a Divindade Encantadora Asutra" uma vez por turno.\r\nVocê pode escolher até 1 card no campo para cada 2 cards com a face para baixo no campo; destrua-os.\r\nDurante sua Fase Final: você pode escolher 1 Armadilha "Asutra" no seu Cemitério; baixe-a.','\r',char(13)),'\n',char(10)),'','Destruir','Baixar','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65326118,'Dragão Tenpai Fadra',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial, ou no começo da Etapa de Dano, se um monstro batalhar: você pode escolher 1 monstro Dragão de FOGO de Nível 4 ou menos no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê só pode usar este efeito de "Dragão Tenpai Fadra" uma vez por turno. \r\nSeus monstros Dragão de FOGO não podem ser destruídos em batalha. \r\nUma vez por turno, durante a Fase de Batalha, você pode (Efeito Rápido): imediatamente depois que este efeito resolver, Invocar por Invocação-Sincro usando este card que você controla.','\r',char(13)),'\n',char(10)),'Invoque por Invocação Especial 1 monstro do Cemitério','','Invocação Sincro','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65330383,'Cavaleiro do Pesadelo Grifo',replace(replace('2+ monstros com nomes diferentes	\r\nSe este card for Invocado por Invocação-Link: você pode descartar 1 card e, depois, escolha 1 Magia/Armadilha no seu Cemitério; Baixe-a no seu campo, mas ela não pode ser ativada neste turno e, depois, se este card estava co-linkado quando este efeito foi ativado, você pode comprar 1 card. \r\nVocê só pode usar este efeito de "Cavaleiro do Pesadelo Grifo" uma vez por turno. \r\nMonstros Invocados por Invocação-Especial no campo não podem ativar seus efeitos, a não ser que eles estejam linkados.','\r',char(13)),'\n',char(10)),'','Comprar 1 card?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65331686,'Fofanimal Coruja',replace(replace('Quando este card for Invocado por Invocação-Normal ou Especial da mão: você pode adicionar 1 "Polimerização" do seu Deck à sua mão. \r\nVocê pode pagar 500 PV; Invoque por Invocação-Fusão 1 Monstro de Fusão "Peladura" do seu Deck Adicional, usando monstros da sua mão ou do seu campo como Matérias de Fusão. \r\nVocê só pode usar 1 efeito de "Fofanimal Coruja" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65338781,'Mago Vermelho Habilidoso',replace(replace('Sempre que um Card de Magia for ativado, coloque 1 Marcador de Magia neste card quando esse Card de Magia resolver (máx. 3). \r\nVocê pode oferecer este card com 3 Marcadores de Magia nele como Tributo; Invoque por Invocação-Especial 1 monstro "Arquidemônio" da sua mão, Deck ou Cemitério. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 card que você controla no qual você possa colocar um Marcador de Magia; coloque 1 Marcador de Magia nele.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65342096,'Laboratório de Endymion',replace(replace('O nome deste card se torna "Cidadela Mágica de Endymion" enquanto estiver na Zona de Magias & Armadilhas. \r\nSempre que um Card de Magia for ativado, coloque 1 Marcador de Magia neste card quando essa Magia resolver. \r\nUma vez por turno, depois do cálculo de dano, se um monstro Mago seu for destruído em batalha: você pode remover 6 Marcadores de Magia do seu campo; Invoque por Invocação-Especial 1 monstro Mago de Nível 7 ou mais da sua mão ou do Deck. \r\nVocê só pode ativar 1 "Laboratório de Endymion" por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65351555,'Basiltrice, o Familiar do Olho Maligno',replace(replace('Se você controlar um monstro "Olho Maligno" e este card estiver na sua mão ou no Cemitério (Efeito Rápido): você pode Invocar este card por Invocação-Especial, mas bana-o quando ele deixar o campo. \r\nDurante o turno do seu oponente, você pode (Efeito Rápido): imediatamente depois que este efeito resolver, Invocar por Invocação-Link 1 Monstro Link "Olho Maligno" usando monstros que você controla como matéria. \r\nAo fazê-lo, você também pode usar Magias de Equipamento "Olho Maligno" que você controla como monstros "Olho Maligno". \r\nVocê só pode usar cada efeito de "Basiltrice, o Familiar do Olho Maligno" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65357623,'Luta pelo Poder Zumbi',replace(replace('Escolha 1 monstro Zumbi no campo; até o final deste turno, ele ganha 1000 de ATK ou perde 1000 de ATK. \r\nDurante sua Fase Principal, se este card estiver no seu Cemitério: você pode embaralhar no Deck 1 dos seus monstros Zumbi banidos e, se isso acontecer, Baixe este card, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar este efeito de "Luta pelo Poder Zumbi" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Aumentar ATK','Reduzir ATK','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65367484,'Agressor de Fóton',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro deve ser Invocado por Invocação-Especial (da sua mão) enquanto você não controlar nenhum monstro. \r\nNão pode atacar se você controlar outro monstro.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65384019,'Ciclo Alquímico',replace(replace('O ATK original de todos os monstros com a face para cima que você controla se torna 0 até a Fase Final. \r\nSempre que um monstro que teve seu ATK original reduzido a 0 por este efeito for destruído em batalha e enviado para o Cemitério, compre 1 card.','\r',char(13)),'\n',char(10)),'Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65384188,'Indiferença','Escolha 1 Monstro de Efeito com a face para cima em Posição de Ataque em cada lado do campo; se os dois monstros ainda estiverem com a face para cima no campo, negue osefeitos deles e, depois, se os efeitos deles dois forem negados por este efeito, enquanto esses dois monstros estiverem com a face para cima em Posição de Ataque, eles não podem ser destruídos em batalha, não podem ser afetados por outros efeitos de card e, além disso, não podem atacar ou mudar suas posições de batalha.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65393205,'Chakra','Você pode Invocar este card por Invocação-Ritual com "Ressurreição de Chakra".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65396880,'Enorme Revolução',replace(replace('Este card pode ser activado apenas durante a sua Main Phase, quando "Pessoas Correndo às Voltas", "Pessoas Oprimidas", e "Resistência Unida" estiverem no seu Campo com a face para cima. \r\nEnvie todos os cards na mão do seu adversário para o Cemitério e destrúa todos os cards que o seu adversário controla no Campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65398390,'Infernobre Cavaleiro Capitão Oliver',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nQuando este card declarar um ataque enquanto estiver equipado: você pode escolher 1 card com a face para cima no campo; destrua-o. \r\nDurante sua Fase Principal, exceto no turno em que este card foi enviado para o Cemitério: você pode escolher 1 monstro Guerreiro que você controla; Invoque este card por Invocação-Especial do seu Cemitério como um Regulador e, se isso acontecer, equipe esse monstro que você controla a este card como uma Magia de Equipamento que concede 500 de ATK a ele. \r\nVocê só pode usar este efeito de "Infernobre Cavaleiro Capitão Oliver" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65400671,'Prisma Cristron Halqifibrax',replace(replace('2+ monstros, incluindo um Regulador	\r\nSe este card for Invocado por Invocação-Link: você pode Invocar por Invocação-Especial 1 Regulador do seu Deck Adicional em Posição de Defesa, com um Nível igual ou menor que os Níveis originais combinados dos monstros usados para sua Invocação-Link. \r\nDurante a Fase Principal ou Fase de Batalha do seu oponente (Efeito Rápido): você pode banir este card que você controla; Invoque por Invocação-Especial 3 "Ficha de Cristron" (Máquina/ÁGUA/Nível 1/ATK 0/DEF 0), mas elas não podem ser oferecidas como Tributo. \r\nVocê só pode usar cada efeito de "Prisma Cristron Halqifibrax" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial um Regulador','Invocar uma Ficha por Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65400672,'Ficha de Cristron',replace(replace('Invocado por Invocação-Especial com o efeito de "Cristron Prisma Halqifibrax". \r\nEssa Ficha não pode ser oferecida como Tributo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65403020,'O Fim de Anubis','Enquanto este card estiver com a face para cima no campo, todos os cards e efeitos que escolham um ou mais cards no Cemitério como alvo, ou que ativem no Cemitério, são negados.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65422840,'Shutendoji',replace(replace('Uma vez por turno: você pode ativar 1 desses efeitos.\r\n● Bana 2 monstros Zumbi do seu Cemitério; compre 1 card.\r\n● Escolha 1 dos seus monstros Zumbi banidos; coloque o alvo no topo do seu Deck.','\r',char(13)),'\n',char(10)),'Banir e comprar','Recuperar um card banido','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65424481,'Ekhajar, Dragão Descendente da Barreira de Gelo',replace(replace('1 Regulador + 1+ não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro: você pode descartar 1 card; banir 2 cards do campo do seu oponente e/ou Cemitério.\r\nSe seu oponente Invocar por Invocação-Especial um ou mais monstros: você pode banir 1 card da sua mão; retorne 1 card de qualquer campo ou Cemitério para a mão.\r\nSe este card Invocado por Invocação-Sincro é enviado para o Cemitério durante o turno do seu oponente: você pode banir 1 card da mão (aleatoriamente), campo ou cemitério do seu oponente.\r\nVocê só pode usar cada um dos efeitos de "Ekhajar, Dragão Descendente da Barreira de Gelo" uma vez por turno.','\r',char(13)),'\n',char(10)),'Banir do campo/Cemitério','Retornar para a mão','Banir da mão/campo/Cemitério','Banir 1 card da sua mão?','','','','','','','','','','','','');
INSERT INTO texts VALUES(65424482,'Ekhajar, Dragão Descendente da Barreira de Gelo',replace(replace('1 Regulador + 1+ não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro: você pode descartar 1 card; banir 2 cards do campo do seu oponente e/ou Cemitério.\r\nSe seu oponente Invocar por Invocação-Especial um ou mais monstros: você pode banir 1 card da sua mão; retorne 1 card de qualquer campo ou Cemitério para a mão.\r\nSe este card Invocado por Invocação-Sincro é enviado para o Cemitério durante o turno do seu oponente: você pode banir 1 card da mão (aleatoriamente), campo ou cemitério do seu oponente.\r\nVocê só pode usar cada um dos efeitos de "Ekhajar, Dragão Descendente da Barreira de Gelo" uma vez por turno.','\r',char(13)),'\n',char(10)),'Banir do campo/Cemitério','Retornar para a mão','Banir da mão/campo/Cemitério','Banir 1 card da sua mão?','','','','','','','','','','','','');
INSERT INTO texts VALUES(65430555,'Lanceiro Agulha Bezoudado',replace(replace('Durante a Fase Principal (Efeito Rápido): você pode escolher 1 monstro Inseto no seu Cemitério e 1 monstro no Cemitério do seu oponente; Invoque este card por Invocação-Especial da sua mão e, se isso acontecer, coloque os monstros alvo no fundo dos Decks. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 Magia/Armadilha "Bezoudado" do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "Lanceiro Agulha Bezoudado" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65430834,'Impacto Jurássico',replace(replace('Se você controlar 2 ou mais monstros Dinossauro e tiver menos PV que seu oponente: destrua tantos monstros no campo quanto possível e, se isso acontecer, sofra 1000 de dano para cada monstro destruído e, depois, cause dano ao seu oponente igual ao dano que você sofreu. \r\nAté o final do próximo turno depois que este card foi ativado, nenhum duelista pode Invocar por Invocação-Normal ou Especial.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65433790,'Modo de Batalha Real - Juntando-se',replace(replace('Ative este card ao escolher 1 Monstro de Efeito no campo. \r\nNas primeiras duas vezes que esse monstro seria destruído em batalha a cada turno, ele não é destruído. \r\nQuando ele for destruído em batalha, o duelista que o destruiu ganha 2000 PV. \r\nSe o oponente do duelista do turno sofrer dano de batalha ou de efeito: ative este efeito; esse oponente pode aplicar o seguinte efeito.\r\n● Invoque por Invocação-Especial 1 monstro de Nível 4 ou menos da sua mão ou do Deck, mas perca 2000 PV.','\r',char(13)),'\n',char(10)),'Ativar quando você receber dano','Invocação Especial?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65446452,'Cenário no Aquário',replace(replace('Todos os monstros de ÁGUA que você controla ganham 300 de ATK/DEF. \r\nTodos os monstros "Aquatriz" que você controla ganham 300 de ATK/DEF. \r\nSe este card for enviado do campo para o Cemitério: você pode escolher 1 monstro Aqua no seu Cemitério; Invoque-o por Invocação-Especial e, além disso, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros Aqua.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65450690,'Ritual Prenunciado',replace(replace('Pague 1000 PV; Invoque por Invocação-Especial 1 Monstro de Ritual da sua mão, mas ele não pode atacar e, além disso, destrua-o durante a Fase Final. \r\nVocê só pode ativar 1 "Ritual Prenunciado" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65458948,'Sereia Toon',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro deve ser Invocado por Invocação-Especial (da sua mão) enquanto você controlar "Mundo Toon". \r\nNão pode atacar no turno em que for Invocado por Invocação-Especial. \r\nVocê deve pagar 500 PV para declarar um ataque com este monstro. \r\nSe "Mundo Toon" no campo for destruído, destrua este card. \r\nPode atacar diretamente seu oponente, a não ser que ele controle um monstro Toon e, nesse caso, este card deve escolher um monstro Toon como alvo dos seus ataques.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65471349,'Fronteira Psíquica',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 "Jinzo" ou 1 Magia/Armadilha que liste especificamente esse card em seu texto, do seu Deck à sua mão. \r\nQuando outro monstro que você controla for atacado por um monstro do oponente, antes do cálculo de dano: você pode destruir tanto o monstro atacante quanto este card. \r\nVocê só pode usar cada efeito de "Fronteira Psíquica" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65472618,'Dragodies, o Guerreiro Edificado',replace(replace('Escala de Pêndulo = 2\r\n[ Efeito de Pêndulo ]\r\nNo começo da Etapa de Dano, se um monstro que você controla batalhar um monstro com a face para cima do oponente: você pode descartar 1 card; o ATK e DEF do monstro batalhante do oponente se tornam metade do seu ATK e DEF atuais (mesmo que este card deixe o campo).\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe este card na Zona de Monstros do seu dono for destruído por um ataque ou efeito de card do seu oponente: você pode adicionar 1 monstro do Tipo Guerreiro ou Mago com 2000 ou menos de ATK do seu Deck à sua mão, exceto "Dragodies, o Guerreiro Edificado", durante a Fase Final deste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65475294,'A Amazona Hostil',replace(replace('Ofereça como Tributo 1 dos seus monstros no campo (exceto este) durante cada uma de suas Fases de Apoio. \r\nSe não o fizer, este card é destruído. \r\nMonstros usados em Invocação-Tributo ou oferecidos como Tributo pelos efeitos de outros cards não contam.','\r',char(13)),'\n',char(10)),'Oferecer 1 monstro como Tributo para manter "A Amazona Hostil"?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65477143,'Ator do Abismo - Dramaturga da Liberdade',replace(replace('Escala de Pêndulo = 8\r\n[ Efeito de Pêndulo ]\r\nQuando um monstro declarar um ataque: você pode descartar 1 card; Invoque este card por Invocação-Especial no campo do seu oponente. \r\nVocê só pode usar este efeito de "Ator do Abismo - Dramaturga da Liberdade" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe este card for Invocado por Invocação-Especial da Zona de Pêndulo: o dono deste card revela 3 Magias "Script do Abismo" do Deck dele, o oponente dele elege 1 delas aleatoriamente para que o dono deste card Baixe no campo dele (mas o dono a destrói durante a Fase Final) e, além disso, embaralhe o resto no Deck. \r\nSe este card for destruído: você pode embaralhar no Deck 1 Magia "Script do Abismo" do seu Cemitério. \r\nVocê só pode usar cada efeito de "Ator do Abismo - Dramaturga da Liberdade" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65479980,'Força-S Cão de Patrulha',replace(replace('Durante sua Fase Principal, seu oponente não pode ativar os efeitos de monstros na mesma coluna que um dos seus monstros "Força-S". \r\nSe seu oponente Invocar um ou mais monstros por Invocação-Normal ou Especial enquanto você controlar um monstro "Força-S" (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão. \r\nVocê só pode usar este efeito de "Força-S Cão de Patrulha" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65496056,'Codarus','Você pode enviar 1 "Umi" com a face para cima que você controla ao Cemitério para escolher até 2 cards que seu oponente controla; envie os alvos ao Cemitério.','Enviar para o Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65496951,'Disarmonia Vaalmônica',replace(replace('Coloque 1 Marcador de Ressonância em 1 card na sua Zona de Pêndulo sobre o qual você possa colocar um Marcador de Ressonância e, depois, aplique 1 desses efeitos.\r\n● Ganhe 500 PV e, depois, você pode adicionar 1 dos seus cards "Vaalmônica" banidos à sua mão, exceto "Disarmonia Vaalmônica".\r\n● Sofra 500 de dano e, depois, você pode adicionar 1 card "Vaalmônica" do seu Cemitério à sua mão, exceto "Disarmonia Vaalmônica".	\r\nVocê só pode ativar 1 "Disarmonia Vaalmônica" por turno.','\r',char(13)),'\n',char(10)),'','Ganhe 500 PV','Receba 500 de dano','Recuperar um card banido?','Recuperar um card do Cemitério?','','','','','','','','','','','');
INSERT INTO texts VALUES(65500515,'Esguicho de Lula',replace(replace('Uma vez por turno, quando este card for escolhido como alvo de um ataque por um monstro do oponente: você pode mover este card que você controla para outra das suas Zonas de Monstros Principais e, depois, Invoque por Invocação-Especial 1 "Ficha de Tinta de Lula" (Aqua/ÁGUA/Nível 2/ATK ?/DEF 0). \r\nO ATK desta Ficha se torna o ATK desse monstro do oponente. \r\nEnquanto este card estiver na sua Zona de Monstros Principal mais à esquerda ou mais à direita, os monstros do seu oponente com ATK menor ou igual à DEF deste card não podem escolhê-lo como alvo de ataques.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65500516,'Ficha de Tinta de Lula','Invocada por Invocação-Especial com o efeito "Esguicho de Lula". Quando Invocada, o ATK desta Ficha fica igual ao ATK atual do monstro atacante.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65503206,'Soldado de Restolhos',replace(replace('Não pode ser usado como Matéria Sincro, exceto para a Invocação-Sincro de um monstro "Restolhos". \r\nNo final da Fase de Batalha, se este card com a face para cima em Posição de Defesa for escolhido como alvo de um ataque: destrua este card. \r\nSe este card for destruído pelo efeito de um card "Restolhos" e enviado para o Cemitério: você pode escolher 1 monstro "Restolhos" no seu Cemitério, exceto "Soldado de Restolhos"; adicione o alvo à sua mão.','\r',char(13)),'\n',char(10)),'Destruir este card','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65504487,'Soldado de Brinquedo',replace(replace('Você pode Baixar este card da sua mão na sua Zona de Magias & Armadilhas como uma Magia. \r\nVocê só pode usar cada um dos seguintes efeitos de "Soldado de Brinquedo" uma vez por turno. \r\nSe este card Baixado na Zona de Magias & Armadilhas for enviado para o Cemitério: você pode Invocar este card por Invocação-Especial. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 "Caixa de Brinquedos" do seu Deck à sua mão, ou, se você controlar "Caixa de Brinquedos", em vez disso, você pode adicionar 1 monstro de LUZ de Nível 4.','\r',char(13)),'\n',char(10)),'Adicionar 1 monstro de LUZ de Nível 4 à sua mão?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65514302,'Ligação Ímã',replace(replace('Durante a Fase Principal: ative 1 desses efeitos (mas você só pode usar cada efeito de "Ligação Ímã" uma vez por turno);\r\n● Adicione 1 "Guerreiro Condutor Magnum Plus Minus Linear" ou 1 monstro "Guerreiro Ímã" de Nível 4 ou menos do seu Deck à sua mão.\r\n● Adicione 1 monstro "Guerreiro Ímã" de Nível 8 do seu Deck à sua mão.\r\n● Invoque por Invocação-Fusão 1 Monstro de Fusão Rocha do seu Deck Adicional, ao embaralhar no Deck monstros Rocha da sua mão, do campo, do Cemitério e/ou do banimento como matéria.','\r',char(13)),'\n',char(10)),'Ativar','Adicione "Guerreiro Condutor Magnum Plus Minus Linear" ou 1 monstro "Guerreiro Imã" de Nível 4 ou menos à sua mão','Adicione 1 "Guerreiro Imã" de Nível 8 à sua mão','Invocação Fusão','','','','','','','','','','','','');
INSERT INTO texts VALUES(65515667,'Kaiser do Motor',replace(replace('Você pode revelar este card na sua mão; imediatamente depois que este efeito resolver, Invoque por Invocação-Normal 1 monstro Máquina de TREVAS. \r\nVocê pode escolher 1 monstro que você controla; destrua-o e, depois, você pode Invocar por Invocação-Especial 1 "Ficha de Motor" (Máquina/TERRA/Nível 1/ATK 200/DEF 200) em Posição de Ataque. \r\nVocê só pode usar cada efeito de "Kaiser do Motor" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar','Destruir','Invocar uma Ficha por Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65515668,'Ficha de Motor','Invocado por Especial com o efeito "Motor Demoníaco Ω".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65518099,'Batedor Qliphort',replace(replace('Escala de Pêndulo = 9\r\n[ Efeito de Pêndulo ]\r\nVocê não pode Invocar monstros por Invocação-Especial, exceto monstros "Qli". Este efeito não pode ser negado. Uma vez por turno: você pode pagar 800 PV; adicione 1 card "Qli" do seu Deck à sua mão, exceto "Batedor Qliphort".\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nReiniciando em Modo de Réplica...\r\nUm erro aconteceu ao executar C:\sofia\zefra.exe\r\nAutor desconhecido.\r\nPermitir C:\tierra\qliphort.exe ? <S/N>...[S]\r\nReiniciando em Modo Autônomo...','\r',char(13)),'\n',char(10)),'Procurar no Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65536818,'Denglong, Primeiro dos Yang Zing',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Especial: você pode adicionar 1 card "Yang Zing" do seu Deck à sua mão. \r\nUma vez por turno: você pode enviar 1 monstro Wyrm do seu Deck para o Cemitério; o Nível deste card se torna o desse monstro enviado. \r\nSe este card com a face para cima deixar o campo: você pode Invocar por Invocação-Especial 1 monstro "Yang Zing" do seu Deck. \r\nVocê só pode Invocar um ou mais "Denglong, Primeiro dos Yang Zing" por Invocação-Especial uma vez por turno.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Alterar o Nível','Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65541655,'Dragão Vermelho Nova – Alma Ardente',replace(replace('2 Reguladores + 1 não-Regulador	\r\nDeve ser Invocado por Invocação-Sincro ou Especial (do seu Deck Adicional) ao banir 2 Reguladores e 1 "Dragão Vermelho Arquidemônio" do seu Cemitério.\r\nSe este card for Invocado por Invocação-Especial: você pode adicionar 1 card do seu Cemitério à sua mão, e se fizer, este card ganha 2000 de ATK. \r\nVocê só pode usar este efeito de "Dragão Vermelho Nova – Alma Ardente" durante o Duelo que Invocou por Invocação-Sincro um "Dragão Vermelho Arquidemônio", e somente uma vez por Duelo.\r\nNão pode ser destruído por efeitos de cards.','\r',char(13)),'\n',char(10)),'Efeito de recuperação','','Você já usou o primeiro efeito de "Dragão Vermelho Nova – Alma Ardente"','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65541656,'Dragão Vermelho Nova – Alma Ardente',replace(replace('2 Reguladores + 1 não-Regulador	\r\nDeve ser Invocado por Invocação-Sincro ou Especial (do seu Deck Adicional) ao banir 2 Reguladores e 1 "Dragão Vermelho Arquidemônio" do seu Cemitério.\r\nSe este card for Invocado por Invocação-Especial: você pode adicionar 1 card do seu Cemitério à sua mão, e se fizer, este card ganha 2000 de ATK. \r\nVocê só pode usar este efeito de "Dragão Vermelho Nova – Alma Ardente" durante o Duelo que Invocou por Invocação-Sincro um "Dragão Vermelho Arquidemônio", e somente uma vez por Duelo.\r\nNão pode ser destruído por efeitos de cards.','\r',char(13)),'\n',char(10)),'Efeito de recuperação','','Você já usou o primeiro efeito de "Dragão Vermelho Nova – Alma Ardente"','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65549080,'Condor das Névoas',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) ao devolver 1 monstro "Vale das Névoas" que você controla para a mão. \r\nSe Invocado desta forma, o ATK deste card se torna 1700.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65563871,'Curandeira de Solarvinhas',replace(replace('1 Monstro Normal Planta	\r\nSe um Monstro Link "Solaravalon" que você controla deixar o campo devido a um efeito de card: destrua este card. \r\nSe este card for Invocado por Invocação-Especial: você pode escolher 1 Monstro Link "Solaravalon" no campo; ganhe PV igual ao seu Valor Link x 300. \r\nQuando um Monstro Link Planta seu causar dano de batalha ao seu oponente: você pode ganhar 600 PV.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65569724,'Espelho do Boneco de Gelo',replace(replace('Envie para o Cemitério 1 monstro de ÁGUA da sua mão ou do campo com a face para cima; Invoque por Invocação-Especial 1 monstro da sua mão ou do Deck com o mesmo nome que 1 monstro de ÁGUA que você controla e, além disso, você não pode Invocar por Invocação-Especial pelo resto deste turno depois que este card resolver, exceto monstros de ÁGUA. \r\nVocê pode banir este card do seu Cemitério; adicione 1 "Boneco de Gelo" do seu Deck ou Cemitério à sua mão. \r\nVocê só pode usar cada efeito de "Espelho do Boneco de Gelo" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65570596,'Moça Arqueira Vermelha','Uma sereia arqueira que se esconde na sua concha protetora, esperando pelo momento certo para atacar.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65589010,'Nação Dogmatika',replace(replace('Nenhum duelista pode escolher monstros "Dogmatika" que você controla como alvo de efeitos de monstros que foram Invocados por Invocação-Especial do Deck Adicional. \r\nVocê só pode usar cada um dos seguintes efeitos de "Nação Dogmatika" uma vez por turno. \r\nDepois do cálculo de dano, se um monstro "Dogmatika" seu batalhou um monstro do oponente: você pode destruir esse monstro do oponente. \r\nSe este card com a face para cima na Zona do Campo for destruído por um efeito de card do oponente: você pode fazer com que cada duelista envie 1 monstro do seu Deck Adicional para o Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65591858,'Cronomalia Esfinge Alada',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode escolher 1 monstro "Cronomalia" de Nível 5 no seu Cemitério; Invoque o alvo por Invocação-Especial. \r\nVocê não pode Invocar monstros por Invocação-Especial no turno em que ativar este efeito, exceto monstros "Cronomalia".','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65612386,'Angmarl, o Monarca Demoníaco','Quando este card for Invocado por Invocação-Tributo: você pode banir 1 Card de Magia do seu Cemitério; adicione 1 card com o mesmo nome que o Card de Magia banido do seu Deck à sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65612454,'Wattcubo',replace(replace('Só pode ser equipado a um monstro Trovão. \r\nEle ganha 100 de ATK para cada monstro Trovão no seu Cemitério. \r\nVocê pode enviar este card com a face para cima para o Cemitério e, depois, escolha 1 monstro Trovão com a face para cima que você controla; o alvo ganha 1000 de ATK.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65622692,'Cabeça de Dragão Y',replace(replace('Uma vez por turno, você pode: escolher 1 "Cabeça de Canhão X" que você controla; equipe este card no alvo, OU: desequipe este card e Invoque-o por Invocação-Especial. \r\nUm monstro equipado com este card ganha 400 de ATK/DEF e, além disso, se o monstro equipado seria destruído em batalha ou por um efeito de card, em vez disso, destrua este card.','\r',char(13)),'\n',char(10)),'Equipar','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65623423,'Gosma Horripilante','Uma gosma soberana que é definitivamente mais ameaçadora do que parece.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65626958,'Gullinbursti das Bestas Nórdicas',replace(replace('Para uma Invocação-Sincro, você pode substituir este card por qualquer 1 Regulador "Nórdic". \r\nVocê só pode usar cada um dos seguintes efeitos de "Gullinbursti das Bestas Nórdicas" uma vez por turno. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode Invocar por Invocação-Especial 1 monstro "Nórdic" da sua mão. \r\nVocê pode escolher 1 monstro "Nórdic" no seu Cemitério, exceto "Gullinbursti das Bestas Nórdicas"; adicione-o à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65646587,'Fusão Pêndulo',replace(replace('Invoque por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional, usando monstros que você controla como Matérias de Fusão. \r\nSe você tiver 2 cards nas suas Zonas de Pêndulo, você também pode usar cards nas suas Zonas de Pêndulo como Matéria(s) de Fusão. \r\nVocê só pode ativar 1 "Fusão Pêndulo" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65659181,'Politopo Vylon',replace(replace('Escolha qualquer número de Cards de Monstro "Vylon" que você controla que forem Cards de Equipamento; Invoque-os por Invocação-Especial com a face para cima em Posição de Defesa. \r\nBana-os quando eles deixarem o campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65664792,'Elegância da Lady Harpia',replace(replace('Embaralhe no Deck 1 "Irmãs de Lady Harpia" da sua Zona de Monstros e, depois, você pode Invocar por Invocação-Especial 3 monstros "Harpia" com nomes originais diferentes, 1 da sua mão, 1 do Deck e 1 do Cemitério. \r\nPelo resto deste turno depois que este card resolver, você não pode Invocar monstros por Invocação-Especial, exceto monstros de VENTO. \r\nSe este card que você controla for destruído por um efeito de card "Harpia" ou por um efeito de card do seu oponente: adicione 1 monstro "Harpia" do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "Elegância da Lady Harpia" uma vez por turno.','\r',char(13)),'\n',char(10)),'Retornar ao Deck do dono','Procurar no Deck','Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65676461,'Número 32: Dragonete Tubarão',replace(replace('3 monstros de Nível 4	\r\nUma vez por turno, quando este card atacante destruir um monstro do oponente em batalha e enviá-lo para o Cemitério: você pode desassociar 1 matéria deste card; Invoque o monstro destruído por Invocação-Especial no campo do seu oponente em Posição de Ataque (mas ele perde 1000 de ATK) e, se isso acontecer, este card pode realizar um segundo ataque durante esta Fase de Batalha.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65676462,'Número 32: Dragonete Tubarão',replace(replace('3 monstros de Nível 4	\r\nUma vez por turno, quando este card atacante destruir um monstro do oponente em batalha e enviá-lo para o Cemitério: você pode desassociar 1 matéria deste card; Invoque o monstro destruído por Invocação-Especial no campo do seu oponente em Posição de Ataque (mas ele perde 1000 de ATK) e, se isso acontecer, este card pode realizar um segundo ataque durante esta Fase de Batalha.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65681983,'Designador de Crossout',replace(replace('Declare 1 nome de card; bana 1 desse card declarado do seu Deck Principal e, se isso acontecer, até o final deste turno, negue seus efeitos, assim como os efeitos ativados e efeitos no campo de cards com o mesmo nome original. \r\nVocê só pode ativar 1 "Designador de Crossout" por turno.','\r',char(13)),'\n',char(10)),'Declare 1 nome de card que exista no seu Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65681984,'Designador de Crossout',replace(replace('Declare 1 nome de card; bana 1 desse card declarado do seu Deck Principal e, se isso acontecer, até o final deste turno, negue seus efeitos, assim como os efeitos ativados e efeitos no campo de cards com o mesmo nome original. \r\nVocê só pode ativar 1 "Designador de Crossout" por turno.','\r',char(13)),'\n',char(10)),'Declare 1 nome de card que exista no seu Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65685470,'Espírito dos Seis Samurai',replace(replace('Uma vez por turno, você pode: Escolher 1 monstro "Seis Samurai" com a face para cima que você controla; equipe este card no alvo, OU: Desequipe este card e Invoque-o por Invocação-Especial com a face para cima em Posição de Ataque. \r\nEnquanto equipado com este efeito, o monstro equipado ganha 500 de ATK e DEF. \r\nSe o monstro equipado destruir um monstro do oponente em batalha: Compre 1 card. \r\n(Um monstro só pode ser equipado com 1 Monstro União por vez. Se o monstro equipado seria destruído, em vez disso, destrua este card.)','\r',char(13)),'\n',char(10)),'Tornar-se um Card de Equipamento','Invocação Especial','Comprar','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65687442,'Cavalgada das Valquírias',replace(replace('(Este card deve ser sempre considerado como um card "Valquíria-".)	\r\nInvoque por Invocação-Especial qualquer número de monstros "Valquíria-" com nomes diferentes da sua mão. \r\nSe você Invocou por Invocação-Especial 3 ou mais monstros com este efeito, você não sofre dano de batalha até o final do próximo turno. \r\nDurante a Fase Final do turno em que você ativou este card, embaralhe todos os monstros que você controla no Deck. \r\nVocê pode banir este card do seu Cemitério; adicione 1 "Travessura da Deusa do Tempo" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Cavalgada das Valquírias" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65703851,'Desmerecer','Quando um efeito de monstro for ativado na mão ou no Cemitério: negue a ativação e, se isso acontecer, bana-o.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65711558,'Juramento dos Guerreiros Antigos - Senhores Dragão',replace(replace('2 monstros Besta-Guerreira, incluindo um monstro "Guerreiros Antigos" de VENTO	\r\nTodos os monstros "Guerreiros Antigos" que você controla ganham 500 de ATK/DEF. \r\nVocê só pode usar cada um dos seguintes efeitos de "Juramento dos Guerreiros Antigos - Senhores Dragão" uma vez por turno. \r\nSe este card for Invocado por Invocação-Link: você pode adicionar 1 card "Guerreiros Antigos" do seu Deck à sua mão. \r\n(Efeito Rápido): você pode enviar 1 card da sua mão ou do campo para o Cemitério e, depois, escolha 1 card com a face para cima que seu oponente controla; devolva-o para a mão.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Retornar para a mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65726770,'Mago Silencioso Zero',replace(replace('Se seu oponente comprar um ou mais cards: aumente o Nível deste card pelo número comprado. \r\nEnquanto o Nível deste card for maior que seu Nível original, ele ganha ATK igual à diferença x 500. \r\nQuando seu oponente ativar um Card de Magia ou seus efeitos, enquanto você controlar "Sarcófago Brilhante" (Efeito Rápido): você pode negar a ativação e, se isso acontecer, aumente em 1 o Nível deste card. \r\nVocê só pode usar este efeito de "Mago Silencioso Zero" uma vez por turno.','\r',char(13)),'\n',char(10)),'Aumentar o Nível','Negue a ativação de um efeito de Magia','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65734501,'ÁS-Resgate Jato de Ar',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 Magia "ÁS-Resgate" do seu Deck à sua mão. \r\nQuando seu oponente ativar um efeito de monstro no campo (Efeito Rápido): você pode oferecer este card como Tributo da sua mão ou do campo com a face para cima; Invoque por Invocação-Especial 1 monstro "ÁS-Resgate" da sua mão, exceto "ÁS-Resgate Jato de Ar". \r\nVocê só pode usar cada efeito de "ÁS-Resgate Jato de Ar" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65737274,'Dragard',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode escolher 1 Monstro Normal com 1000 ou menos de ATK no seu Cemitério; Invoque o alvo por Invocação-Especial com a face para cima em Posição de Defesa. \r\nUma vez por turno: você pode oferecer como Tributo 1 monstro do Tipo Dragão e, depois, escolher 1 monstro com a face para cima que você controla; até a Fase Final, o Nível dele se torna 8 e, se isso acontecer, ele ganha 800 de ATK.','\r',char(13)),'\n',char(10)),'Invocação Especial','Alterar Nível/ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65741786,'I:P Mascarena',replace(replace('2 Monstros que não sejam Link	\r\nDurante a Fase Principal do seu oponente, você pode (Efeito Rápido): imediatamente depois que este efeito resolver, Invocar por Invocação-Link 1 Monstro Link usando matérias que você controla, incluindo este card. \r\nVocê só pode usar este efeito de "I:P Mascarena" uma vez por turno. \r\nUm Monstro Link que usou este card como matéria não pode ser destruído pelos efeitos de card do seu oponente.','\r',char(13)),'\n',char(10)),'Invocação Link','O efeito de "I:P Mascarena" está sendo aplicado.','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65741787,'I:P Mascarena',replace(replace('2 Monstros que não sejam Link	\r\nDurante a Fase Principal do seu oponente, você pode (Efeito Rápido): imediatamente depois que este efeito resolver, Invocar por Invocação-Link 1 Monstro Link usando matérias que você controla, incluindo este card. \r\nVocê só pode usar este efeito de "I:P Mascarena" uma vez por turno. \r\nUm Monstro Link que usou este card como matéria não pode ser destruído pelos efeitos de card do seu oponente.','\r',char(13)),'\n',char(10)),'Invocação Link','O efeito de "I:P Mascarena" está sendo aplicado.','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65741788,'I:P Mascarena',replace(replace('2 Monstros que não sejam Link	\r\nDurante a Fase Principal do seu oponente, você pode (Efeito Rápido): imediatamente depois que este efeito resolver, Invocar por Invocação-Link 1 Monstro Link usando matérias que você controla, incluindo este card. \r\nVocê só pode usar este efeito de "I:P Mascarena" uma vez por turno. \r\nUm Monstro Link que usou este card como matéria não pode ser destruído pelos efeitos de card do seu oponente.','\r',char(13)),'\n',char(10)),'Invocação Link','O efeito de "I:P Mascarena" está sendo aplicado.','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65741789,'I:P Mascarena',replace(replace('2 Monstros que não sejam Link	\r\nDurante a Fase Principal do seu oponente, você pode (Efeito Rápido): imediatamente depois que este efeito resolver, Invocar por Invocação-Link 1 Monstro Link usando matérias que você controla, incluindo este card. \r\nVocê só pode usar este efeito de "I:P Mascarena" uma vez por turno. \r\nUm Monstro Link que usou este card como matéria não pode ser destruído pelos efeitos de card do seu oponente.','\r',char(13)),'\n',char(10)),'Invocação Link','O efeito de "I:P Mascarena" está sendo aplicado.','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65743242,'Chamado do Terrestre','Quando um monstro do oponente declarar um ataque: você seleciona o alvo do ataque.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65749035,'Gungnir, o Dragão da Barreira de Gelo',replace(replace('1 Regulador + 1+ monstros não-Reguladores de ÁGUA	\r\nUma vez por turno: você pode descartar até 2 cards para o Cemitério e, depois, escolha o mesmo número de cards que seu oponente controla; destrua-os.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65758454,'Lanceiro Ganbara','Quando este card for Invocado por Invocação-Normal: você pode Invocar por Invocação-Especial 1 "Lanceiro Ganbara" da sua mão ou Cemitério com a face para cima em Posição de Defesa.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65785782,'Chamado de Atlantis',replace(replace('Adicione 1 monstro que mencione "Atlantis, a Cidade do Dragão" do seu Deck à sua mão, então se você controla "Atlantis, a Cidade do Dragão", você pode negar os efeitos de 1 Monstro de Efeito que seu oponente controla até o final deste turno.\r\nSe você controla "Umi": você pode banir este card do seu Cemitério; todos os monstros ÁGUA que você controla atualmente ganham 500 de ATK/DEF.\r\nVocê só pode usar cada um dos efeitos de "Chamado de Atlantis" uma vez por turno.','\r',char(13)),'\n',char(10)),'Efeito de busca','Aumentar ATK/DEF','Negar um monstro?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65801012,'Cinet Fusão',replace(replace('Invoque por Invocação-Fusão 1 Monstro de Fusão Ciberso do seu Deck Adicional, usando monstros da sua mão ou do campo como Matéria de Fusão. \r\nSe você não controlar nenhum monstro na Zona de Monstros Adicional, você também pode banir até 1 Monstro Link Ciberso do seu Cemitério como Matéria de Fusão.','\r',char(13)),'\n',char(10)),'Usar um monstro no Cemitério como Matéria?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65810489,'Estátua dos Perversos','Se este card Baixado for destruído e enviado para o Cemitério: Invoque por Invocação-Especial 1 "Ficha de Perverso" (Demônio/TREVAS/Nível 4/ATK 1000/DEF 1000).','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65810490,'Ficha de Perverso','Invocado por Especial com o efeito "Estátua dos Perversos".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65815684,'Astraloud Perverso',replace(replace('"Visas Starfrost" + 1 monstro com 1500 de ATK/2100 de DEF	\r\nDeve ser Invocado por Invocação-Especial (do seu Deck Adicional) ao banir os cards acima do seu campo e/ou Cemitério. \r\nNão pode ser destruído em batalha. \r\nSe este card for Invocado por Invocação-Especial: você pode escolher 1 outro monstro no campo; destrua-o e, se isso acontecer, este card ganha ATK igual à metade do ATK ou DEF original desse monstro (o que for maior).','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65824822,'Negócio das Trevas','Quando seu oponente ativar um Card de Magia Normal: pague 1000 PV; o efeito ativado dessa Magia Normal se torna "Seu oponente descarta 1 card aleatório".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65830223,'Vendedor de Caixões','Sempre que um ou mais monstros forem enviados para o Cemitério do seu oponente: cause 300 de dano ao seu oponente.','Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65844845,'Gigagrilo Inzektor',replace(replace('Se este card estiver no seu Cemitério: Você pode banir 1 monstro do Tipo Inseto do seu Cemitério para escolher 1 monstro "Inzektor" com a face para cima que você controla; equipe este card do Cemitério ao alvo. \r\nEste efeito de "Gigagrilo Inzektor" só pode ser usado uma vez por turno. \r\nEnquanto este card estiver equipado a um monstro, o ATK original desse monstro se torna 2000 e, se ele atacar um monstro em Posição de Defesa, cause Dano de Batalha perfurante ao seu oponente.','\r',char(13)),'\n',char(10)),'Equipar','Aumentar ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65848113,'Sobre DoomZ XIII - Graflareio',replace(replace('3 monstros de Nível 5	\r\nUma vez por turno, você também pode Invocar por Invocação-Xyz "Sobre DoomZ XIII - Graflareio" ao usar 1 Monstro Xyz "DoomZ" que você controla (transfira as matérias dele). \r\nVocê só pode usar cada um dos seguintes efeitos de "Sobre DoomZ XIII - Graflareio" uma vez por turno. \r\nVocê pode desassociar 1 matéria deste card; adicione 1 Magia/Armadilha "DoomZ" do seu Deck à sua mão e, depois, você pode destruir 1 card no campo. \r\nSe este card for destruído por um efeito de card: você pode Invocar por Invocação-Especial 1 monstro "DoomZ" que não seja Xyz do seu Deck ou Cemitério.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Xyz usando um Monstro Xyz como matéria?','Efeito de busca','Invocação Especial','Destruir o card?','','','','','','','','','','','','');
INSERT INTO texts VALUES(65848811,'Desafiante Heroico - Alabarda de Ataque',replace(replace('Se seu oponente controlar um monstro e você não controlar nenhum monstro, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nSe este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente. \r\nQuando este card causar dano de batalha ao seu oponente: você pode adicionar 1 card "Heroico(a)" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Procurar no Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65853758,'Nhamy★Redenção',replace(replace('Monstros que seu oponente controla perdem 200 de ATK para cada monstro Besta de LUZ no seu campo e Cemitério. \r\nUma vez por Corrente, se você Invocar por Invocação-Sincro um monstro Besta de LUZ: você pode comprar 1 card e, depois, coloque 1 card da sua mão no fundo do Deck. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 monstro "Nhamy" que você controla e 1 monstro que seu oponente controla; troque o controle desses 2 monstros. \r\nVocê só pode usar este efeito de "Nhamy★Redenção" uma vez por turno.','\r',char(13)),'\n',char(10)),'Comprar','Trocar o controle','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65861210,'Paraíso Caído das Bestas Sagradas',replace(replace('Até três vezes por turno, durante sua Fase Principal: você pode enviar 3 outros cards do mesmo tipo (Monstro, Magia ou Armadilha) da sua mão e/ou do campo com a face para cima para o Cemitério e, depois, você pode Invocar por Invocação-Especial 1 monstro "Bestas Sagradas" da sua mão, do Deck, do Cemitério ou do banimento e, se isso acontecer, ele não é afetado pelos efeitos ativados de Magias/Armadilhas do seu oponente. \r\nSe você controlar um monstro "Bestas Sagradas" cujo Nível original seja 10: você pode comprar 2 cards. \r\nVocê só pode usar este efeito de "Paraíso Caído das Bestas Sagradas" uma vez por turno.','\r',char(13)),'\n',char(10)),'Enviar para o Cemitério','Comprar','Invocação Especial?','Invocado por Invocação Especial pelo efeito de "Paraíso Caído das Bestas Sagradas"','','','','','','','','','','','','');
INSERT INTO texts VALUES(65872270,'Explosão Cavaleirardor',replace(replace('Uma vez por turno, durante sua Fase Principal: você pode destruir até 3 outros cards "Cavaleirardor" que você controla e, depois, devolver um mesmo número de cards que seu oponente controla para a mão. \r\nSe este card for enviado para o Cemitério: você pode adicionar 1 Monstro Pêndulo "Cavaleirardor" com a face para cima do seu Deck Adicional à sua mão.','\r',char(13)),'\n',char(10)),'Usar o efeito?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65877963,'Diabretiço Calislimo',replace(replace('Você pode Invocar este card por Invocação-Ritual com "Diabretiço de Criação". \r\nVocê pode revelar este card na sua mão; descarte 1 card e, se isso acontecer, Invoque por Invocação-Especial 1 monstro "Diabretiço" do seu Deck e, além disso, durante a Fase Final, perca 2500 PV se você não Invocou um Monstro de Ritual por Invocação-Especial neste turno depois que você resolveu este efeito. \r\nVocê pode enviar 1 card "Diabretiço" da sua mão ou do campo com a face para cima para o Cemitério e, depois, escolha 1 monstro que seu oponente controla; destrua-o. \r\nVocê só pode usar 1 efeito de "Diabretiço Calislimo" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65878864,'Inseto Comedor de Nobres','VIRE: Destrói 2 monstros no Campo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65884091,'Hordeum Maligno Tânatos',replace(replace('2 monstros de TREVAS de Nível 4	\r\nUma vez por turno (Efeito Rápido): você pode desassociar 1 matéria deste card; este card com a face para cima não é afetado por outros efeitos de monstro neste turno.','\r',char(13)),'\n',char(10)),'Não é afetado por efeitos','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65889305,'Argostars - Tydeu Relâmpago',replace(replace('Enquanto este card estiver com a face para cima na Zona de Magias & Armadilhas, monstros Guerreiro que você controla ganham 500 de ATK/DEF. \r\nUma vez por turno: você pode descartar 1 card; Invoque este card por Invocação-Especial como um Monstro de Efeito (Guerreiro/LUZ/Nível 4/ATK 2000/DEF 2000) com o seguinte efeito (este card ainda é considerado uma Armadilha) e, depois, você pode adicionar 1 card "Argostars" do seu Deck à sua mão, exceto "Argostars - Tydeu Relâmpago".\r\n● Uma vez por turno (Efeito Rápido): você pode colocar este card com a face para cima na sua Zona de Magias & Armadilhas.','\r',char(13)),'\n',char(10)),'Invocação Especial','Colocar com a face para cima','Adicionar este card à mão?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65892310,'Brionac, o Dragão de Gelo Mágico',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro: você pode descartar 1 card e, depois, escolha 1 card no campo; devolva-o para a mão. \r\nSe este card for Invocado por Invocação-Especial do Cemitério: você pode descartar 1 card e, depois, escolha 1 card no campo; devolva-o para a mão. \r\nVocê só pode usar cada efeito de "Brionac, o Dragão de Gelo Mágico" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65892585,'Orgulho Dourado - Carrie Carruagem',replace(replace('2 monstros de Nível 3	\r\nVocê pode desassociar 1 matéria deste card; adicione 1 Magia "Orgulho Dourado" do seu Deck à sua mão e, depois, se você tiver menos PV que seu oponente, você pode enviar 1 monstro "Orgulho Dourado" do seu Deck para o Cemitério. \r\nVocê só pode usar o efeito anterior de "Orgulho Dourado - Carrie Carruagem" uma vez por turno. \r\nUma vez por turno, durante a Fase Final, se o efeito anterior foi ativado neste turno: devolva este card para o Deck Adicional e, se isso acontecer, Invoque por Invocação-Especial 1 "Orgulho Dourado - Capitã Carrie" do seu Deck ou Cemitério.','\r',char(13)),'\n',char(10)),'','','Enviar mais 1 monstro para o Cemitério?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65898344,'Fúria Ghoti',replace(replace('Você pode escolher 1 monstro Peixe que você controla e 1 monstro que seu oponente controla; bana os dois monstros até sua próxima Fase de Apoio. \r\nSe um ou mais monstros Peixe forem Invocados por Invocação-Especial no seu campo enquanto qualquer card estiver banido: você pode banir este card do seu Cemitério ou com a face para cima na sua Zona de Magias & Armadilhas; até o final deste turno, todos os monstros Peixe que você controla atualmente ganham 100 de ATK para cada card atualmente banido. \r\nVocê só pode usar cada efeito de "Fúria Ghoti" uma vez por turno.','\r',char(13)),'\n',char(10)),'Banir ambos os monstros','Aumentar ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65899613,'Vespabatalha - Alfinete, o Alvo',replace(replace('Se você controlar um monstro Inseto: você pode Invocar este card por Invocação-Especial da sua mão. \r\nDurante sua Fase Principal: você pode causar 200 de dano ao seu oponente para cada "Vespabatalha - Alfinete, o Alvo" que você controla. \r\nVocê só pode usar cada efeito de "Vespabatalha - Alfinete, o Alvo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65910922,'Arionpos, a Serpente dos Ghoti',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro: você pode banir 1 monstro Peixe de Nível 6 ou menos do seu Deck. \r\nSe este card for enviado para o Cemitério como Matéria Sincro: você pode escolher 1 monstro Peixe no seu Cemitério; bana o alvo e, depois, você pode adicionar 1 monstro Peixe com um Nível igual ou menor do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "Arionpos, a Serpente dos Ghoti" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Adicionar 1 monstro Peixe do seu Deck à sua mão?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65914127,'Pingente Pêndulo',replace(replace('Bana 5 Monstros Pêndulo com a face para cima do seu Deck Adicional; coloque na sua Zona de Pêndulo 1 Monstro Pêndulo do seu Deck ou do Deck Adicional com a face para cima. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 card em qualquer Zona de Pêndulo; reduza sua Escala de Pêndulo em 1 (mín. 0). \r\nVocê só pode ativar 1 "Pingente Pêndulo" por turno.','\r',char(13)),'\n',char(10)),'Colocar na Zona de Pêndulo','Reduzir a Escala','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65938950,'Não Soltem, Cães de Guerra',replace(replace('Quando qualquer duelista comprar um ou mais Reguladores em sua compra normal em sua Fase de Compra: ele pode revelar esse(s) card(s); ele compra 2 cards. \r\nSe seu oponente comprar por este efeito: você perde 2000 PV e, se isso acontecer, envie este card para o Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65952776,'Dunnell, Armas Nobres da Luz',replace(replace('Só pode ser equipado a um monstro que você controla. \r\nVocê só pode controlar 1 "Dunnell, Armas Nobres da Luz". \r\nO monstro equipado ganha 500 de ATK para cada monstro que você controla com um nome diferente que mencione "Ficha de Aventura". \r\nSe este card for enviado para o Cemitério: você pode escolher 1 "Ficha de Aventura" que você controla; equipe este card no alvo. \r\nVocê só pode usar este efeito de "Dunnell, Armas Nobres da Luz" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65953423,'Cauda de Fadas - Rochka',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode fazer com que seu oponente ganhe 500 PV e, depois, seu oponente olha os 3 cards do topo do seu Deck e seleciona 1 deles para que você adicione à sua mão e, além disso, embaralhe o resto de volta no Deck. \r\nVocê só pode usar este efeito de "Cauda de Fadas - Rochka" uma vez por turno. \r\nUma vez por batalha, se este card batalhar, antes do cálculo de dano: você pode enviar este card para o Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65956182,'Acessão do Mundo Negro',replace(replace('Durante a Fase Principal: Invoque por Invocação-Fusão 1 Monstro de Fusão Demônio do seu Deck Adicional, ao banir matérias mencionadas nele do seu campo ou Cemitério. \r\nSe estiver Invocando um monstro "Mundo Negro" por Invocação-Fusão desta forma, você também pode descartar monstros como matéria. \r\nDurante sua Fase Principal, se este card estiver no seu Cemitério: você pode adicionar este card à sua mão e, depois, descarte 1 monstro "Mundo Negro". \r\nVocê só pode usar cada efeito de "Acessão do Mundo Negro" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65957473,'Inseto com Armadura Metálica','Uma criatura gigante semelhante a um inseto, coberta por uma espessa armadura. Tudo o que esteja no seu caminho é destruído.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65959844,'Campo Catalisador',replace(replace('A cada turno, 1 monstro Gêmeos de Nível 5 ou mais que você Invocar por Invocação-Normal pode ser Invocado sem Tributo. \r\nDurante sua Fase Principal, você pode Invocar por Invocação-Normal 1 monstro Gêmeos em adição à sua Invocação-Normal/Baixar (padrão). \r\n(Você só pode se aproveitar deste efeito uma vez por turno.) \r\nUma vez por turno: você pode escolher 1 card que seu oponente controla; até a Fase Final do seu oponente, bana 1 monstro Gêmeos que você controla, que seja considerado um Monstro de Efeito e tenha ganho seus efeitos e, se isso acontecer, destrua esse card.','\r',char(13)),'\n',char(10)),'Invocação Normal sem Tributo','Destruir','Invocar pelo efeito de "Campo Catalisador"','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65961085,'Roda da Profecia',replace(replace('Quando este card for Invocado por Invocação-Especial pelo efeito de um monstro do Tipo Mago: você pode escolher qualquer número dos seus Cards de Magia "Livro de Magia" banidos; embaralhe-os no Deck e, se isso acontecer, coloque seus outros Cards de Magia "Livro de Magia" banidos em seu Cemitério. \r\nVocê só pode usar o efeito de "Roda da Profecia" uma vez por turno.','\r',char(13)),'\n',char(10)),'Retornar ao Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65961304,'Kewl Tune B2B',replace(replace('1 Regulador + 1+ Monstros Sincro	\r\nOs Níveis dos monstros que seu oponente controla aumentam em 2. \r\nSeus Reguladores podem realizar um segundo ataque durante cada Fase de Batalha. \r\nQuando seu oponente ativar um efeito de monstro (Efeito Rápido): você pode escolher 1 Regulador no seu Cemitério ou banimento, exceto um Regulador de Nível 10; adicione-o à sua mão ou Invoque-o por Invocação-Especial e, depois, imediatamente depois que este efeito resolver, você pode Invocar 1 Monstro Sincro por Invocação-Sincro. \r\nVocê só pode usar este efeito de "Kewl Tune B2B" duas vezes por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão ou Invocar por Invocação Especial','Invocação Sincro?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65961683,'Jurrac Velphito',replace(replace('1 Regulador + 1+ monstros Dinossauro não-Reguladores	\r\nO ATK/DEF deste card se tornam a soma do ATK original das matérias usadas para a sua Invocação-Sincro. \r\nNo começo da Etapa de Dano, se este card atacar um monstro com a face para baixo em Posição de Defesa: você pode destruir esse monstro com a face para baixo em Posição de Defesa.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65976795,'Estigokraken, o Behemoth Subterror',replace(replace('VIRE: Você pode escolher cards Baixados no campo, igual ao número de monstros "Behemoth Subterror" que você controla; destrua-os. \r\nVocê só pode usar este efeito de "Estigokraken, o Behemoth Subterror" uma vez por turno.\r\nQuando um monstro com a face para cima que você controla for virado com a face para baixo, se você não controlar nenhum monstro com a face para cima: você pode Invocar este card por Invocação-Especial da sua mão em Posição de Defesa. \r\nUma vez por turno: você pode colocar este card com a face para baixo em Posição de Defesa.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65984457,'Besta Gladiadora Tórax','Se este card foi Invocado por Invocação-Especial pelo efeito de um monstro "Besta Gladiadora", no final de qualquer Fase de Batalha em que este card atacou ou foi atacado, você pode devolvê-lo ao Deck para comprar 1 card.','Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(65993085,'Enterro Extravagante',replace(replace('Ative este card ao descartar 1 monstro e, depois, escolha 1 monstro no seu Cemitério cujo Nível seja menor que o Nível original do monstro descartado; Invoque-o por Invocação-Especial e equipe-o com este card. \r\nO monstro equipado tem seus efeitos negados. \r\nVocê só pode ativar 1 "Enterro Extravagante" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66002986,'Maravilha Velocidaroide de Asas Transparentes',replace(replace('Escolha cards que seu oponente controla, até o número de Tipos de Monstro diferentes entre os Monstros Sincro de VENTO que você controla; destrua-os. \r\nSe seu oponente Invocar um ou mais monstros por Invocação-Especial (exceto durante a Etapa de Dano): você pode banir este card do seu Cemitério e, depois, escolha 1 Monstro Sincro de VENTO que você controla; bana-o e, depois, devolva-o para o campo. \r\nVocê só pode usar cada efeito de "Maravilha Velocidaroide de Asas Transparentes" uma vez por turno.','\r',char(13)),'\n',char(10)),'Destruir','Banir e retornar ao Campo','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66011101,'Número 60: Dugares, o Atemporal',replace(replace('2 monstros de Nível 4	\r\nVocê pode desassociar 2 matérias deste card e, depois, ative 1 dos seguintes efeitos;\r\n● Pule sua próxima Fase de Compra e, além disso, compre 2 cards e, depois, descarte 1 card.\r\n● Pule sua próxima Fase Principal 1 e, além disso, Invoque por Invocação-Especial 1 monstro do seu Cemitério em Posição de Defesa.\r\n● Pule a Fase de Batalha do seu próximo turno e, além disso, dobre o ATK de 1 monstro que você controla até o final deste turno.	\r\nVocê só pode usar este efeito de "Número 60: Dugares, o Atemporal" uma vez por turno.','\r',char(13)),'\n',char(10)),'Compre e depois descarte 1 card','Invocar por Invocação Especial do Cemitério','Dobre o ATK dele','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66015185,'Dragão dos Triângulos Gêmeos',replace(replace('2 monstros Dragão de Nível 4 ou menos, exceto Fichas	\r\nQuando este card for Invocado por Invocação-Link: você pode pagar 500 PV e, depois, escolher 1 monstro de Nível 5 ou mais no seu Cemitério; Invoque-o por Invocação-Especial em uma zona sua para a qual este card apontar, mas ele não pode atacar neste turno e, além disso, ele tem seus efeitos negados.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66022706,'Mekk-Cavaleiro do Horizonte Verde',replace(replace('Se 2 ou mais cards estiverem na mesma coluna, você pode Invocar este card por Invocação-Especial (da sua mão) nessa coluna. \r\nVocê só pode Invocar "Mekk-Cavaleiro do Horizonte Verde" por Invocação-Especial uma vez por turno desta forma. \r\nQuando um ataque for declarado envolvendo este card e um monstro do oponente na coluna deste card: você pode escolher 1 monstro "Mekk-Cavaleiro" no seu Cemitério; adicione-o à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66023650,'Folgo, a Justiça de Peluguel',replace(replace('3 monstros com Tipos diferentes	\r\nNão pode ser usado como Matéria Link. \r\nSe este card for Invocado por Invocação-Link: você pode Invocar por Invocação-Especial, do seu Deck e em Posição de Defesa, 1 monstro "de Peluguel" com um Tipo diferente dos 3 monstros usados para a Invocação-Link. \r\nSe um ou mais cards que seu oponente controla for destruído em batalha ou por um efeito de card: você pode comprar 1 card e, depois, se você controlar 3 ou mais monstros "de Peluguel" com nomes diferentes, compre 2 cards adicionais. \r\nVocê só pode usar cada efeito de "Folgo, a Justiça de Peluguel" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Comprar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66059345,'Derretinvasão do Materriator',replace(replace('Quando este card for ativado: escave os 6 cards do topo do seu Deck e, depois, coloque-os no topo do Deck em qualquer ordem. \r\nUma vez por turno: você pode pagar 1500 PV; Invoque por Invocação-Especial 1 Monstro Xyz "Materriator" do seu Deck Adicional, ao usar 1 Monstro Normal de Nível 3 que você controla como matéria (isso é considerado uma Invocação-Xyz) e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto Monstros Xyz. \r\nSe um Monstro Xyz for Invocado por Invocação-Xyz: você pode associar o card do topo do seu Deck a 1 Monstro Xyz "Materriator" que você controla.','\r',char(13)),'\n',char(10)),'','Invocação Especial','Como Matéria Xyz','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66066482,'Vaga-Lume Inzektor',replace(replace('Uma vez por turno: Você pode equipar 1 monstro "Inzektor" da sua mão ou Cemitério a este card. \r\nSe um card "Inzektor" for equipado a este card: Você pode olhar todos os cards Baixados que seu oponente controla. \r\nEnquanto este card estiver equipado a um monstro, o Nível desse monstro é aumentado em 1 e, além disso, ele ganha ATK e DEF iguais ao ATK e DEF deste card.','\r',char(13)),'\n',char(10)),'Equipar','Revelar um card Baixado','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66069967,'Princesa da Premonição Bibliomusa',replace(replace('VIRE: Você pode adicionar 1 monstro "Princesa da Premonição", exceto "Princesa da Premonição Bibliomusa", e 1 Magia de Ritual do seu Deck à sua mão.\r\nSe este card for oferecido como Tributo e enviado para o Cemitério: você pode Invocar este card por Invocação-Especial com a face para baixo em Posição de Defesa.\r\nVocê só pode usar cada um dos efeitos anteriores de "Princesa da Premonição Bibliomusa" uma vez por turno. \r\nSeu oponente não pode escolher Monstros de Ritual que você controla como alvo de efeitos de card e, além disso, eles não podem ser destruídos pelos efeitos de card do seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66073051,'Guerreiro de Zera','Um guerreiro vagueante que procura o santuário, onde pode ganhar o poder dos Senhores Arqueiros. Para escapar á tentação de demônios malignos, ele luta sozinho no dia a dia.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66078354,'Guerreiro Maginério das Relíquias',replace(replace('Não pode atacar a não ser que você controle uma "Ficha de Aventura". \r\nVocê só pode usar cada um dos seguintes efeitos de "Guerreiro Maginério das Relíquias" uma vez por turno. \r\nSe você controlar uma "Ficha de Aventura": você pode Invocar este card por Invocação-Especial da sua mão. \r\nNo final da Fase de Batalha, se um monstro seu que mencione "Ficha de Aventura" batalhou: você pode Baixar 1 Armadilha que mencione "Ficha de Aventura" diretamente do seu Deck.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66084673,'Irmandade do Punho de Fogo - Rinoceronte','Se um monstro "Punho de Fogo" que você controla atacar ou for atacado, durante o cálculo de dano (no turno de qualquer duelista): uma vez por batalha, você pode enviar 1 Card de Magia/Armadilha "Formação de Fogo" com a face para cima que você controla e 1 monstro "Punho de Fogo" da sua mão para o Cemitério; o seu monstro que atacou ou foi atacado ganha ATK igual ao ATK original do monstro enviado para o Cemitério, apenas durante o cálculo de dano.','Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66092596,'Despertar Draco',replace(replace('Quando este card for ativado: você pode adicionar 1 monstro do seu Deck à sua mão ("Verdadeiro(a) Draco", "Verdadeiro Rei", Pêndulo "Dracossassino" ou Pêndulo "Dracosuserano"). \r\nSe um ou mais monstros "Verdadeiro(a) Draco" ou "Verdadeiro Rei" com a face para cima que você controla forem destruídos em batalha ou por um efeito de card e enviados para o Cemitério: você pode escolher 1 deles; coloque-o na sua Zona de Magias & Armadilhas como uma Magia Contínua com a face para cima. \r\nVocê só pode usar este efeito de "Despertar Draco" uma vez por turno. \r\nVocê só pode ativar 1 "Despertar Draco" por turno.','\r',char(13)),'\n',char(10)),'Adicionar aquele monstro à mão?','Efeito de colocar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66094973,'Esfera Transformadora',replace(replace('Uma vez por turno: Você pode escolher 1 monstro com a face para cima em Posição de Defesa que seu oponente controla; descarte 1 card e equipe o alvo a este card. \r\n(Você só pode equipar 1 monstro por vez a este card com este efeito.) \r\nEste card ganha o ATK do monstro equipado. \r\nSe este card atacar, ele é colocado em Posição de Defesa no final da Fase de Batalha. \r\nDurante a Fase Final: O monstro equipado a este card pelo efeito deste card é Invocado por Invocação-Especial no lado do campo do oponente com a face para cima em Posição de Defesa.','\r',char(13)),'\n',char(10)),'Equipar','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66100045,'Quebra de Transmigração','Todos os cards que seriam devolvidos para o Deck do Cemitério, em vez disso, são removidos de jogo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66100116,'Bruxa Vingativa',replace(replace('Se você controlar "Dragão da Rosa Negra", um monstro que o mencione ou um Monstro Sincro Planta: você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe este card for enviado para o Cemitério e um Monstro Sincro estiver no campo: você pode descartar 1 card; Invoque por Invocação-Especial 1 monstro Planta com 1500 ou menos de DEF do seu Deck e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto Monstros Sincro. \r\nVocê só pode usar cada efeito de "Bruxa Vingativa" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar este card por Invocação Especial','Invocar por Invocação Especial do Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66102515,'Kurikurinku @Ignister',replace(replace('Se este card estiver na sua mão ou no Cemitério (Efeito Rápido): você pode oferecer como Tributo 1 monstro "@Ignister"; Invoque este card por Invocação-Especial, mas bana-o quando ele deixar o campo. \r\nQuando um card ou efeito for ativado que escolha como alvo um ou mais monstros Ciberso que você controla, e você controlar um monstro Ciberso que foi Invocado por Invocação-Especial do Deck Adicional (Efeito Rápido): você pode oferecer este card como Tributo; negue o efeito. \r\nVocê só pode usar cada efeito de "Kurikurinku @Ignister" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Negar o efeito','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66104644,'Magistrado de Endymion',replace(replace('Escala de Pêndulo = 8\r\n[ Efeito de Pêndulo ]\r\nSempre que um Card de Magia for ativado, coloque 1 Marcador de Magia neste card quando essa Magia resolver. \r\nVocê pode remover 3 Marcadores de Magia deste card; Invoque por Invocação-Especial tanto este card da sua Zona de Pêndulo quanto 1 monstro com a face para cima no seu Deck Adicional sobre o qual você possa colocar um Marcador de Magia e, se isso acontecer, coloque 1 Marcador de Magia em cada.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nVocê só pode Invocar um ou mais "Magistrado de Endymion" por Invocação-Especial uma vez por turno. \r\nQuando este card declarar um ataque: você pode colocar 1 Marcador de Magia sobre ele. \r\nUma vez por turno do oponente (Efeito Rápido): você pode remover 3 Marcadores de Magia do seu campo; Invoque por Invocação-Especial 1 monstro do seu Deck sobre o qual você possa colocar um Marcador de Magia. \r\nSe este card na Zona de Monstros for destruído: você pode colocar este card na sua Zona de Pêndulo e, depois, coloque neste card o mesmo número de Marcadores de Magia que ele tinha como monstro.','\r',char(13)),'\n',char(10)),'Invocação Especial','Colocar um marcador','Remova Marcadores para Invocar por Invocação Especial do Deck','Colocar na Zona de Pêndulo','','','','','','','','','','','','');
INSERT INTO texts VALUES(66122213,'Lutador do Golpe Infernal',replace(replace('1 Regulador + 1+ não-Reguladores	\r\nDurante a Fase Principal 2 (Efeito Rápido): você pode destruir tantos monstros com a face para cima no campo quanto possível e, se isso acontecer, cause dano ao seu oponente igual aos Níveis originais combinados dos monstros destruídos x 200. \r\nSe este card for destruído em batalha ou por um efeito de card: você pode escolher 1 monstro Máquina de Nível 5 ou menos no seu Cemitério; Invoque-o por Invocação-Especial em Posição de Defesa. \r\nVocê só pode usar cada efeito de "Lutador do Golpe Infernal" uma vez por turno.','\r',char(13)),'\n',char(10)),'Destruir','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66127916,'Fusão Reversa','Revele 1 Monstro de Fusão do seu Deck Adicional, adicione 1 das Matérias de Fusão cujo nome esteja especificamente listado nesse card do seu Deck à sua mão e, depois, você pode adicionar 1 "Polimerização" do seu Cemitério à sua mão.','Adicionar 1 card "Polimerização/Fusão" do seu Cemitério à sua mão?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66141736,'Dragão da Ascendência Vermelha',replace(replace('1 Regulador Demônio + 1+ monstros não-Reguladores	\r\nQuando este card for Invocado por Invocação-Sincro: você pode escolher 1 monstro "Ressonador" no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê não pode Invocar monstros por Invocação-Especial do Deck Adicional no turno em que ativar este efeito, exceto Monstros Sincro Dragão de TREVAS. \r\nDurante sua Fase Principal, exceto no turno em que este card foi enviado para o Cemitério: você pode banir este card do seu Cemitério e, depois, escolha 2 monstros "Ressonador" de Nível 1 no seu Cemitério; Invoque os dois por Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66149377,'Mágico Mosquete - Agulha Dançante',replace(replace('Se você controlar um monstro "Mágico(a) Mosquete": escolha até 3 cards no Cemitério; bana-os. \r\nVocê só pode ativar 1 "Mágico Mosquete - Agulha Dançante" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66150724,'PênduLoMoon',replace(replace('Escala de Pêndulo = 0\r\n[ Efeito de Pêndulo ]\r\nDurante sua Fase Principal: você pode adicionar 1 Monstro Pêndulo "Pêndulo" com a face para cima do seu Deck Adicional à sua mão e, depois, destrua este card. \r\nVocê só pode usar este efeito de "PênduLoMoon" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nDurante sua Fase Principal: você pode adicionar até 2 Monstros Pêndulo com a face para cima do seu Deck Adicional à sua mão, com Níveis entre as Escalas de Pêndulo dos 2 cards nas suas Zonas de Pêndulo e, além disso, pelo resto deste turno, até que você Invoque por Invocação-Pêndulo, você não pode ativar efeitos de monstro e os efeitos de quaisquer cards nas suas Zonas de Pêndulo são negados. \r\nVocê só pode usar este efeito de "PênduLoMoon" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66156348,'Saga do Imperador Dragão',replace(replace('Escolha 1 monstro Dragão que você controla; seu ATK se torna o dobro (até o final deste turno) e, depois, se seu oponente atualmente controla um monstro Dragão, a ativação dos efeitos do monstro alvo não pode ser negada pelo resto deste turno. \r\nDurante sua Fase Principal: você pode banir este card do seu Cemitério; Invoque por Invocação-Especial 1 dos seus Monstros Xyz Dragão que estiverem banidos ou no seu Cemitério, em Posição de Defesa. \r\nVocê só pode usar 1 efeito de "Saga do Imperador Dragão" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66165755,'Axoide Aliado Genex',replace(replace('1 Regulador "Genex" + 1+ monstros não-Reguladores	\r\nUma vez por turno: você pode descartar 1 card e, depois, escolha 1 monstro Máquina de Nível 4 ou menos no seu Cemitério; Invoque o alvo por Invocação-Especial e, se isso acontecer, seu ATK se torna o dobro até o final deste turno, ele não pode atacar seu oponente diretamente e, além disso, bana-o durante sua Fase Final.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66171432,'Super Koi Koi',replace(replace('Escave os 3 cards do topo do seu Deck e Invoque por Invocação-Especial tantos monstros "Flor Cardian" dentre eles quanto possível, ignorando suas condições de Invocação, mas o Nível deles se torna 2 e eles tem seus efeitos negados. \r\nBana os cards restantes, com a face para baixo e, se isso acontecer, perca 1000 PV para cada. \r\nVocê pode banir este card do seu Cemitério e oferecer 1 monstro como Tributo; Invoque por Invocação-Especial 1 monstro "Flor Cardian" da sua mão, ignorando suas condições de Invocação. \r\nVocê só pode ativar 1 "Super Koi Koi" por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial do Deck','Invocar por Invocação Especial da mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66192538,'Danmari @Ignister',replace(replace('Quando um ataque for declarado envolvendo um monstro "@Ignister" seu: você pode Invocar este card por Invocação-Especial da sua mão e, se isso acontecer, negue o ataque. \r\nEnquanto você controlar um monstro de Link-6 (Efeito Rápido): você pode banir este card do seu campo ou Cemitério e, depois, escolha 1 card com a face para cima que seu oponente controla; negue seus efeitos até o final deste turno. \r\nVocê só pode usar cada efeito de "Danmari @Ignister" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66194206,'Julgamento Luminoso',replace(replace('Coloque este card no topo do Deck. \r\nSe este card for enviado do Deck para o Cemitério por um efeito de monstro "Luminoso(a)": você pode adicionar 1 "Dragão do Julgamento" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66200210,'Besta Fantasma Mecha Hamstrat',replace(replace('Quando este card for virado com a face para cima: Invoque por Invocação-Especial 2 "Fichas de Besta Fantasma Mecha" (Tipo Máquina/VENTO/Nível 3/ATK 0/DEF 0). \r\nO Nível deste card aumenta em um valor igual à soma dos Níveis de todas as "Fichas de Besta Fantasma Mecha" que você controla. \r\nEnquanto você controlar uma Ficha, este card não pode ser destruído em batalha ou por efeitos de card. \r\nVocê pode oferecer 1 Ficha como Tributo e, depois, escolher 1 monstro "Besta Fantasma Mecha" em seu Cemitério; Invoque o alvo por Invocação-Especial. \r\nVocê só pode usar este efeito de "Besta Fantasma Mecha Hamstrat" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar uma Ficha por Invocação Especial','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66200211,'Ficha de Besta Fantasma Mecha','Invocado por Especial com o efeito de um monstro "Besta Fantasma Mecha" ou um card relacionado.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66206748,'Fountain, o HERÓI Mascarado',replace(replace('Você pode revelar este card na sua mão; Invoque por Invocação-Especial 1 monstro "HERÓI" da sua mão em Posição de Defesa. \r\nSe este card for enviado para o Cemitério por um efeito de card, ou para ativar um efeito de card: você pode Baixar 1 "Mudar a Máscara" do seu Deck ou Cemitério. \r\nVocê só pode usar cada efeito de "Fountain, o HERÓI Mascarado" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Baixar "Mudar a Máscara"','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66214679,'Horus das Trevas',replace(replace('Uma vez por turno, depois de resolver um Card de Magia que foi ativado durante a Fase Principal do seu oponente: você pode escolher 1 monstro de TREVAS de Nível 4 no seu Cemitério; Invoque o alvo por Invocação-Especial. \r\nEste card deve estar com a face para cima no campo para ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66226132,'Trackblack',replace(replace('2 Monstros de Efeito	\r\nVocê pode escolher 1 monstro que você controla para o qual este card apontar; sempre que ele destruir um monstro do oponente em batalha neste turno, compre 1 card. \r\nVocê só pode usar este efeito de "Trackblack" uma vez por turno.','\r',char(13)),'\n',char(10)),'','O efeito de "Trackblack" está sendo aplicado.','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66235877,'Demônio Dragão Caveira',replace(replace('"Dragão da Caverna" + "Demônio Menor"	\r\n(Este card é tratado como um card "Arquidemônio".)	\r\nA Invocação-Fusão deste card só pode ser feita com os Monstros-Matéria de Fusão acima. \r\nNegue os efeitos dos Monstros de Efeito de Virar. \r\nNegue quaisquer efeitos de Armadilha que escolham este card no campo como alvo e, se isso acontecer, destrua esse Card de Armadilha.','\r',char(13)),'\n',char(10)),'Negar efeitos','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66236707,'Cortador de Górdio',replace(replace('A ativação e o efeito deste card não podem ser negados. \r\nNo começo da sua Fase Principal 1 ou 2: escolha qualquer número de cards com a face para cima no campo; para cada card alvo, bana 1 card da sua mão, ou 6 cards do seu Deck Adicional, com a face para baixo e, depois, devolva os cards alvo para a mão.','\r',char(13)),'\n',char(10)),'Ativar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66247039,'Força do Espelho da Mente',replace(replace('Se seu oponente controla 5 ou mais cards com a face para cima, a ativação deste card e o efeito não podem ser negados, você também pode ativar este card no turno que foi Baixado.\r\nEm qualquer dos seguintes momentos: negue os efeitos de tantos cards com a face para cima que seu oponente controla forem possíveis, e se fizer, destrua-os, seus monstros também não podem atacar diretamente até o próximo turno após a ativação deste card.\r\n● Quando o monstro que seu oponente controla com maior ATK (mesmo se empatado) declarar um ataque.\r\n● Quando seu oponente ativar um efeito de monstro que detruiria um ou mais cards no campo.\r\n● Quando seu oponente ativar um efeito de monstro na mão ou campo durante o seu turno.','\r',char(13)),'\n',char(10)),'Ativar','Ativar aplicando o efeito de "Força do Espelho da Mente".','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66247040,'Força do Espelho da Mente',replace(replace('Se seu oponente controla 5 ou mais cards com a face para cima, a ativação deste card e o efeito não podem ser negados, você também pode ativar este card no turno que foi Baixado.\r\nEm qualquer dos seguintes momentos: negue os efeitos de tantos cards com a face para cima que seu oponente controla forem possíveis, e se fizer, destrua-os, seus monstros também não podem atacar diretamente até o próximo turno após a ativação deste card.\r\n● Quando o monstro que seu oponente controla com maior ATK (mesmo se empatado) declarar um ataque.\r\n● Quando seu oponente ativar um efeito de monstro que detruiria um ou mais cards no campo.\r\n● Quando seu oponente ativar um efeito de monstro na mão ou campo durante o seu turno.','\r',char(13)),'\n',char(10)),'Ativar','Ativar aplicando o efeito de "Força do Espelho da Mente".','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66262416,'HERÓI do Destino - Devaneador',replace(replace('Durante o cálculo de dano, se um monstro "HERÓI do Destino" seu batalhar e este card estiver no seu Cemitério: você pode Invocar este card por Invocação-Especial e, se isso acontecer, seu monstro não pode ser destruído por essa batalha e, além disso, você não sofre dano de batalha dessa batalha. \r\nSe Invocado desta forma, bana este card quando ele deixar o campo. \r\nVocê só pode usar este efeito de "HERÓI do Destino - Devaneador" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66288028,'Guerreiro da Fortaleza',replace(replace('Você não sofre dano de batalha dos ataques que envolvem este card. \r\nUma vez por turno, este card não pode ser destruído em batalha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66290900,'Besta Gladiadora - União',replace(replace('Durante a Fase de Batalha: embaralhe no Deck, da sua mão, do campo ou do Cemitério, as Matérias de Fusão que estiverem listadas em um Monstro de Fusão "Besta Gladiadora" e, depois, Invoque por Invocação-Especial esse Monstro de Fusão do seu Deck Adicional, ignorando suas condições de Invocação. \r\nVocê só pode ativar 1 "Besta Gladiadora - União" por turno. \r\nVocê não pode declarar ataques no turno em que ativar este card, exceto com monstros "Besta Gladiadora".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66309175,'Predaplanta Ambulomelides',replace(replace('2 monstros "Predaplanta"	\r\nSe este card for Invocado por Invocação-Fusão: você pode adicionar à sua mão 1 monstro "Predaplanta" ou 1 Magia/Armadilha "Predap" do seu Deck, Cemitério ou Deck Adicional com a face para cima. \r\nVocê pode escolher 1 monstro que seu oponente controla com um Marcador de Predador ou 1 monstro que você controla; ofereça-o como Tributo e, se isso acontecer, Invoque por Invocação-Especial 1 monstro "Predaplanta" do seu Deck. \r\nVocê só pode usar cada efeito de "Predaplanta Ambulomelides" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66322203,'F.A. Sustentação Negativa',replace(replace('Escolha 1 monstro "F.A." que você controla; até o final deste turno, aumente o Nível dele em 2. \r\nDurante sua Fase Principal, exceto no turno em que este card foi enviado para o Cemitério: você pode banir este card do seu Cemitério e, depois, escolher 1 monstro "F.A." que você controla; até o final deste turno, aumente o Nível dele em 2. \r\nVocê só pode usar cada efeito de "F.A. Sustentação Negativa" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66328392,'Enganação dos Despojos do Pecado',replace(replace('Você pode oferecer 1 monstro como Tributo da sua mão ou do campo; adicione 1 card "Azamina" do seu Deck à sua mão. \r\nSe um ou mais monstros forem enviados para o Cemitério do seu oponente e você controlar um monstro "Azamina" (exceto durante a Etapa de Dano): você pode fazer com que seu oponente perca 1500 PV e, se isso acontecer, ganhe 1500 PV. \r\nDurante a Fase Final, se este card estiver no Cemitério porque foi enviado para lá da Zona de Magias & Armadilhas neste turno enquanto estava com a face para cima: você pode Baixá-lo. \r\nVocê só pode usar cada efeito de "Enganação dos Despojos do Pecado" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Perder e recuperar PV','Baixar no seu Campo','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66331855,'Dadotron Morfotrônico',replace(replace('● Enquanto estiver em Posição de Ataque: Uma vez por turno, você pode oferecer 1 monstro como Tributo para causar 600 de dano ao seu oponente.\r\n● Enquanto estiver em Posição de Defesa: Uma vez por turno, você pode causar 300 de dano ao seu oponente.','\r',char(13)),'\n',char(10)),'Cause 600 de dano ao seu oponente','Cause 300 de dano ao seu oponente','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66331856,'Dadotron Morfotrônico',replace(replace('● Enquanto estiver em Posição de Ataque: Uma vez por turno, você pode oferecer 1 monstro como Tributo para causar 600 de dano ao seu oponente.\r\n● Enquanto estiver em Posição de Defesa: Uma vez por turno, você pode causar 300 de dano ao seu oponente.','\r',char(13)),'\n',char(10)),'Cause 600 de dano ao seu oponente','Cause 300 de dano ao seu oponente','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66337215,'Arauto da Criação','Uma vez por turno: você pode descartar 1 card e, depois, escolher 1 monstro de Nível 7 ou mais no seu Cemitério; adicione o alvo à sua mão.','Adicione 1 monstro de Nível 7 ou mais à sua mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66362965,'Demônio Megacyber','Se seu oponente controlar pelo menos 2 monstros a mais que você, você pode Invocar este card por Invocação-Especial (da sua mão).','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66367984,'Proteção dos Elementos',replace(replace('Quando um Card de Magia/Armadilha for ativado: bana 1 monstro "HERÓI do Elemento" com a face para cima que você controla até a Fase Final; negue a ativação e, se isso acontecer, destrua esse card. \r\nSe você controlar "Terra Firma, o HERÓI do Elemento": você pode banir este card do seu Cemitério; Invoque por Invocação-Especial 1 dos seus monstros "HERÓI do Elemento" que estiverem banidos, ou na sua mão ou no Cemitério, ignorando suas condições de Invocação. \r\nVocê só pode usar este efeito de "Proteção dos Elementos" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66378485,'Origem de Neoflamvell','Se você controlar um monstro "Flamvell", exceto "Origem de Neoflamvell", e seu oponente tiver 3 ou menos cards no Cemitério dele, você pode Invocar este card por Invocação-Especial (da sua mão).','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66380357,'Teste Utensilhor',replace(replace('Escolha 1 Monstro Link "Utensilhor" que você controla; Invoque por Invocação-Especial tantos monstros "Utensilhor" de Link-1 do seu Cemitério quanto possível em zonas suas para as quais esse monstro apontar, mas bana-os durante a Fase Final. \r\nVocê só pode ativar 1 "Teste Utensilhor" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66384688,'Ortos Majespectro - Nue',replace(replace('2 Monstros Pêndulo, incluindo um monstro "Majespectro"	\r\nSe este card for Invocado por Invocação-Link: você pode adicionar até 2 Monstros Pêndulo "Majespectro" com a face para cima do seu Deck Adicional à sua mão e, depois, você pode adicionar até 2 Monstros Pêndulo "Majespectro" com nomes diferentes do seu Deck ao seu Deck Adicional com a face para cima e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto monstros "Majespectro" ou "Dracossassino". \r\nVocê só pode usar este efeito de "Ortos Majespectro - Nue" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicione à sua mão um Monstro Pêndulo do seu Deck Adicional','Colocar Monstros Pêndulo do seu Deck no seu Deck Adicional?','Escolha 1 card para adicionar ao Deck Adicional','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66386380,'Oráculo Harpia',replace(replace('O nome deste card se torna "Lady Harpia" enquanto estiver no campo ou no Cemitério. \r\nVocê só pode usar cada um desses efeitos de "Oráculo Harpia" uma vez por turno.\r\n● Se você controlar um monstro "Harpia" de Nível 5 ou mais: você pode Invocar este card por Invocação-Especial da sua mão.\r\n● Se este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 Magia/Armadilha do seu Cemitério à sua mão, que liste especificamente o card "Irmãs de Lady Harpia" em seu texto, durante a Fase Final deste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66393507,'Neurogos X-Krawler',replace(replace('2 monstros Inseto	\r\nMonstros "Krawler" para os quais este card apontar não pode ser destruído em batalha, ganham 300 de ATK/DEF e, se eles batalharem um monstro do seu oponente, qualquer dano de batalha que eles causarem ao seu oponente é dobrado. \r\nSe este card com a face para cima for destruído em batalha ou deixar o campo devido a um efeito de card do oponente enquanto seu dono o controlar: você pode escolher 2 monstros "Krawler" com nomes diferentes no seu Cemitério; Invoque-os por Invocação-Especial com a face para baixo em Posição de Defesa.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66395299,'Doppelganger','Quando você sofrer dano do efeito de um monstro que seu oponente controla, cause a mesma quantidade de dano ao seu oponente.','Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66399653,'Hangar da União',replace(replace('Quando este card for ativado: você pode adicionar 1 monstro União Máquina de LUZ do seu Deck à sua mão. \r\nUma vez por turno, se um ou mais monstros União Máquina de LUZ forem Invocados por Invocação-Normal ou Especial no seu campo (exceto durante a Etapa de Dano): você pode escolher 1 desses monstros; equipe 1 monstro União Máquina de LUZ apropriado, com um nome diferente, do seu Deck, nesse monstro, mas o monstro União que você equipou não pode ser Invocado por Invocação-Especial neste turno. \r\nVocê só pode ativar 1 "Hangar da União" por turno.','\r',char(13)),'\n',char(10)),'Adicionar 1 monstro União à sua mão?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66399675,'Corrente Gishki','Se este card for Invocado por Invocação-Normal: olhe os 3 cards do topo do seu Deck e você pode revelar 1 Monstro de Ritual ou 1 Card de Magia de Ritual entre eles e adicioná-lo à sua mão e, além disso, depois, coloque quaisquer cards restantes no topo do seu Deck em qualquer ordem.','Verificar o Deck','Adicionar 1 Monstro Ritual ou 1 Magia Ritual à sua mão?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66401502,'Alma Aniquiladora Pantera',replace(replace('Se você não controlar nenhum monstro na sua Zona de Monstros Principal: você pode Invocar este card por Invocação-Especial da sua mão. \r\n(Efeito Rápido): você pode ativar 1 desses efeitos ao revelar um ou mais monstros na sua mão com o(s) \r\nAtributo(s) listado(s);\r\n● TERRA: Este card não pode ser destruído em batalha neste turno.\r\n● TERRA & FOGO: Destrua todas as Magias/Armadilhas na coluna deste card.	\r\nVocê só pode usar cada efeito de "Alma Aniquiladora Pantera" uma vez por turno e não pode ativar mais que 1 na mesma Corrente.','\r',char(13)),'\n',char(10)),'Invoque este card por Invocação Especial da sua mão','Revele 1 monstro de TERRA','Revele 1 monstro de TERRA ou FOGO','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66403530,'Zeroboros Topológico',replace(replace('2+ Monstros de Efeito	\r\nVocê não pode Invocar/Baixar monstros em uma Zona de Monstros Adicional para a qual este card apontar. \r\nGanha 200 de ATK para cada card banido. \r\nSe outro monstro for Invocado por Invocação-Especial em uma zona para a qual um Monstro Link apontar, enquanto este monstro estiver no campo: bana todos os cards no campo. \r\nUma vez por turno, durante a Fase de Apoio do próximo turno depois que este card foi banido por seu próprio efeito: Invoque este card banido por Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66407907,'Gêmeos de Solarsemente',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial enquanto você controlar um Monstro Link "Solaravalon": você pode escolher 1 Monstro Normal Planta de Nível 4 ou menos no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê pode banir este card no seu Cemitério e 1 Monstro Link que você controla; se você tiver 2 ou mais Monstros Link Planta com o mesmo nome uns dos outros no seu Cemitério, Invoque 1 deles por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Gêmeos de Solarsemente" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66413481,'Avatar do Rei de Fogo Yaksha',replace(replace('Se um ou mais monstros "Rei(s) de Fogo" com a face para cima que você controla forem destruídos por um efeito de card (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe este card for destruído e enviado para o Cemitério: você pode destruir 1 card na sua mão ou no campo. \r\nVocê só pode usar este efeito de "Avatar do Rei de Fogo Yaksha" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66425726,'Dragão-Pêndulografo de Olhos Anômalos',replace(replace('Escala de Pêndulo = 4\r\n[ Efeito de Pêndulo ]\r\nDurante a Fase Final: você pode adicionar à sua mão 1 Magia de Ritual do seu Deck ou Cemitério e, depois, devolva este card para a mão. \r\nVocê só pode usar este efeito de "Dragão-Pêndulografo de Olhos Anômalos" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nVocê pode Invocar este card por Invocação-Ritual com "Advento do Olhos Anômalos". \r\nDeve ser Invocado por Invocação-Ritual, ou por Invocação-Pêndulo da sua mão. \r\nSempre que seu oponente Invocar um ou mais monstros por Invocação-Especial do Deck Adicional, cause 300 de dano a ele. \r\nUma vez por turno, quando seu oponente ativar um Card de Magia ou seus efeitos (Efeito Rápido): você pode colocar este card na sua Zona de Pêndulo e, se isso acontecer, negue esse efeito e, depois, se você colocou este card Invocado por Invocação-Ritual na Zona de Pêndulo, você pode Invocar por Invocação-Especial 1 monstro "Olhos Anômalos" do seu Deck Adicional.','\r',char(13)),'\n',char(10)),'','','Invocar por Invocação Especial 1 monstro "Olhos Anômalos" do seu Deck Adicional?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66429798,'Pesanta, o Titã dos Trovadores','Um ser aberrante que se manifesta em resposta a orações devotas. Dizem que o canto que ele recita revela o futuro, mas ele é misterioso e incompreensível para a maioria.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66431519,'Sagrado Rei de Fogo Garunix',replace(replace('Se um ou mais dos seus monstros que eram originalmente de FOGO forem destruídos em batalha ou por um efeito de card: você pode Invocar este card por Invocação-Especial do seu Cemitério (se ele estava lá quando o monstro foi destruído) ou da mão (mesmo se ele não estava). \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode destruir 1 monstro Besta, Besta-Guerreira ou Besta Alada de FOGO na sua mão, no Deck ou no campo com a face para cima, exceto "Sagrado Rei de Fogo Garunix" e, se isso acontecer, até o final deste turno, este card ganha ATK igual à metade do ATK que o monstro destruído tinha lá. \r\nVocê só pode usar cada efeito de "Sagrado Rei de Fogo Garunix" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66436257,'Marcador Vulcânico','Quando você sofer dano de batalha enquanto este card estiver em seu Cemitério: bana-o do seu Cemitério e, depois, se houver outro monstro de FOGO, exceto "Marcador Vulcânico", em seu Cemitério, cause ao seu oponente um valor de dano igual ao dano de batalha que você sofreu.','Banir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66451379,'Alicercinza Jacaré',replace(replace('Se este card na sua Zona de Monstros for destruído em batalha ou por um efeito de Magia e enviado para o seu Cemitério: você pode escolher 1 monstro com a face para cima que seu oponente controla; equipe este card no alvo. \r\nEnquanto este card estiver equipado a um monstro por este efeito, tome o controle desse monstro. \r\nQuando este card deixar o campo, destrua o monstro equipado.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66452432,'Dragão Callibrescondido',replace(replace('3+ Monstros de Efeito	\r\nSeu oponente não pode oferecer este card com a face para cima no campo como Tributo. \r\nUma vez por turno, durante a Fase Principal (Efeito Rápido): você pode escolher 1 monstro "Foguette" que você controla; negue os efeitos de 1 card com a face para cima que seu oponente controla e, depois, destrua o monstro alvo. \r\nSeu oponente não pode ativar cards ou efeitos em resposta à ativação deste efeito. \r\nUma vez enquanto estiver com a face para cima no campo, no começo da Fase de Batalha: você pode Invocar por Invocação-Especial 1 Monstro Link "Callibre" de Link-4 ou menos do seu Deck Adicional.','\r',char(13)),'\n',char(10)),'','Negar e destruir','Invocação Especial','Efeito ③ já ativado','','','','','','','','','','','','');
INSERT INTO texts VALUES(66457138,'Fofanimal Leão','Quando este card declarar um ataque: ele ganha 500 de ATK até o final da Fase de Batalha.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66457407,'Planta Copiadora','Uma vez por turno: você pode escolher 1 outro monstro do Tipo Planta no campo que tenha Nível; até o final deste turno, o Nível deste card se torna o Nível atual desse monstro.','Alterar Nível','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66472129,'Demônio Profunmar',replace(replace('Você pode descartar 1 card e, depois, declare 1 Atributo, exceto ÁGUA; Invoque este card por Invocação-Especial da sua mão em qualquer campo e, depois, este card se torna desse Atributo (até o final deste turno) e, depois, se você Invocou este card por Invocação-Especial no campo do seu oponente, você pode Invocar por Invocação-Especial 1 monstro Demônio de Nível 4 ou menos com um Atributo original que não seja o declarado, da sua mão ou do Cemitério no seu campo e, além disso, pelo resto deste turno, você não pode Invocar por Invocação-Especial do Deck Adicional, exceto monstros Demônio. \r\nVocê só pode usar este efeito de "Demônio Profunmar" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial da mão','Invocar por Invocação Especial para o seu Campo','Invocar por Invocação Especial para o Campo do seu oponente','Invocar por Invocação Especial outro monstro Demônio?','','','','','','','','','','','','');
INSERT INTO texts VALUES(66499018,'Tigre das Chamas','Durante sua Fase de Compra, se este card estiver no seu Cemitério e você não controlar nenhum monstro, em vez de conduzir sua compra normal: você pode Invocar este card por Invocação-Especial e, se isso acontecer, bana-o quando ele deixar o campo.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66500065,'Bi''an, Terra de Yang Zing',replace(replace('Quando este card que você controla for destruído em batalha ou por um efeito de card e enviado para o seu Cemitério: você pode Invocar por Invocação-Especial 1 monstro "Yang Zing" do seu Deck em Posição de Defesa, exceto "Bi''an, Terra de Yang Zing". \r\nVocê só pode usar este efeito de "Bi''an, Terra de Yang Zing" uma vez por turno. \r\nUma vez por turno, durante a Fase Principal ou a Fase de Batalha do seu oponente, você pode: imediatamente depois que este efeito resolver, Invoque por Invocação-Sincro 1 Monstro Sincro, usando apenas monstros "Yang Zing" que você controla (este é um Efeito Rápido). \r\nUm Monstro Sincro que usou este card como uma Matéria Sincro não pode ser destruído em batalha.','\r',char(13)),'\n',char(10)),'Invocação Especial','O efeito de "Bi''an, Terra de Yang Zing" está sendo aplicado.','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66506689,'Arquiduque de Lata',replace(replace('3 monstros de Nível 4	\r\nUma vez por turno, durante o turno de qualquer duelista: você pode desassociar 1 Matéria Xyz deste card e, depois, escolher 1 monstro controlado por seu oponente; mude sua posição de batalha. \r\n(Efeitos de monstros de Virar não são ativados.)','\r',char(13)),'\n',char(10)),'Mudar a posição de batalha','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66516792,'Dragão-Serpente da Noite','Um dragão criado a partir da alma de um cavaleiro perverso.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66518509,'Fusão Mementotlan',replace(replace('Durante a Fase Principal: Invoque por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional, usando monstros da sua mão ou do campo como matéria, incluindo um monstro "Memento". \r\nSe um ou mais monstros em sua posse foram destruídos por um efeito de card neste turno, você também pode embaralhar monstros "Memento" do seu Cemitério no Deck como matéria. \r\nDurante sua Fase Principal: você pode banir este card do seu Cemitério; destrua 1 monstro que você controla e, se isso acontecer, adicione 1 Magia/Armadilha "Memento" do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "Fusão Mementotlan" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Fusão','Destrua e adicione 1 Magia/Armadilha "Memento" à sua mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66518841,'Rugido Orgulhoso','Durante o cálculo de dano, se um monstro seu batalhar um monstro do oponente com um maior ATK: pague PV igual à diferença de ATK; seu monstro ganha ATK igual à diferença +300, apenas durante o cálculo de dano.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66523544,'Robô Sobredimensional Destruidor das Galáxias',replace(replace('3 monstros de Nível 10	\r\nUma vez por turno: você pode desassociar 1 matéria deste card; destrua todas as Magias e Armadilhas que seu oponente controla. \r\nSeu oponente não pode ativar Cards de Magia/Armadilha em resposta à ativação deste efeito.','\r',char(13)),'\n',char(10)),'Destruir Magias/Armadilhas','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66526672,'Labirinto do Pesadelo','Uma vez por turno, durante a Fase Final: mude a posição de batalha de todos os monstros com a face para cima que o duelista do turno controla.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66532962,'Chorozo Magistus',replace(replace('1 Monstro de Fusão, Sincro, Xyz ou Link + 1 monstro Mago	\r\nPrimeiro deve ser Invocado por Invocação-Fusão, ou por Invocação-Especial (do seu Deck Adicional) ao enviar os Cards de Monstro Matérias de Fusão corretos que você controla para o Cemitério. \r\nUma vez por turno, quando um monstro declarar um ataque: você pode escolhê-lo; negue o ataque e, se isso acontecer, este card ganha ATK igual ao ATK desse monstro (até o final deste turno) e, depois, você pode devolver esse monstro para a mão.','\r',char(13)),'\n',char(10)),'Negar o ataque','Retornar o monstro alvo para a mão?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66540884,'Herdeira Arquidemônio',replace(replace('Se este card for enviado para o Cemitério por um efeito de card ou ao ser destruído em batalha: você pode adicionar 1 card "Arquidemônio" do seu Deck à sua mão, exceto "Herdeira Arquidemônio". \r\nVocê só pode usar este efeito de "Herdeira Arquidemônio" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66540885,'Herdeira Arquidemônio',replace(replace('Se este card for enviado para o Cemitério por um efeito de card ou ao ser destruído em batalha: você pode adicionar 1 card "Arquidemônio" do seu Deck à sua mão, exceto "Herdeira Arquidemônio". \r\nVocê só pode usar este efeito de "Herdeira Arquidemônio" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66547759,'Número 23: Lancelot, Cavaleiro Negro do Submundo',replace(replace('2 monstros de Nível 8	\r\nEste card pode atacar diretamente seu oponente enquanto tiver uma Matéria Xyz. \r\nQuando este card causar dano de batalha ao seu oponente: você pode escolher 1 monstro com a face para cima que seu oponente controla; destrua-o. \r\nUma vez por turno, durante o turno de qualquer duelista, quando um Card de Magia/Armadilha ou outro efeito de monstro for ativado: desassocie 1 Matéria Xyz deste card; negue a ativação.','\r',char(13)),'\n',char(10)),'Destruir um monstro','Negar a ativação','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66569334,'Nightmell, o Vínculo Obscuro',replace(replace('Você pode oferecer 1 monstro como Tributo; Invoque por Invocação-Especial do seu Deck, 1 monstro com o mesmo Tipo, Atributo, Nível e ATK/DEF originais que o do monstro oferecido como Tributo, mas com um nome original diferente. \r\nSe você ofereceu como Tributo um monstro Invocado por Invocação-Especial do Deck Adicional, em vez disso, você pode Invocar um monstro por Invocação-Especial do seu Deck Adicional que cumpra esses mesmos critérios. \r\nVocê só pode usar este efeito de "Nightmell, o Vínculo Obscuro" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66570171,'Banshee do Necromundo',replace(replace('"Mundo Zumbi" na Zona do Campo não pode ser destruído por efeitos de card e, além disso, nenhum duelista pode escolhê-lo como alvo de efeitos de card. \r\n(Efeito Rápido): você pode banir este card do seu campo ou Cemitério; ative 1 "Mundo Zumbi" da sua mão ou do Deck. \r\nVocê só pode usar este efeito de "Banshee do Necromundo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66574418,'A Pedra Negra das Lendas',replace(replace('Você pode oferecer este card como Tributo; Invoque por Invocação-Especial 1 monstro "Olhos Vermelhos" de Nível 7 ou menos do seu Deck. \r\nSe este card estiver no seu Cemitério: você pode escolher 1 monstro "Olhos Vermelhos" de Nível 7 ou menos no seu Cemitério; embaralhe-o no Deck e, se isso acontecer, adicione este card à sua mão. \r\nVocê só pode usar 1 efeito de "A Pedra Negra das Lendas" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66594927,'Deflexão Senhormek',replace(replace('Escolha 1 monstro "Senhormek" que você controla; até o final deste turno, seu oponente não sofre dano de batalha de ataques envolvendo esse monstro com a face para cima e, além disso, seu ATK se torna (permanentemente) o ATK original combinado de todos os monstros "Senhormek" que você controla atualmente. \r\nSe um ou mais monstros "Senhormek" que você controla seriam destruídos em batalha ou por um efeito de card, em vez disso, você pode banir este card do seu Cemitério. \r\nVocê só pode ativar 1 "Deflexão Senhormek" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66602787,'Saggi, o Palhaço Sombrio','Este palhaço aparece do nada e usa movimentos estranhos para se esquivar de ataques inimigos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66604523,'Inversão Xyz','Escolha 1 Monstro Xyz com a face para cima que seu oponente controla e 1 Monstro Xyz com a face para cima que você controla; troque o controle dos dois monstros.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66607691,'Unidade de Geração de Fótons',replace(replace('Ofereça como Tributo 2 "Dragão Cibernético". \r\nInvoque por Invocação-Especial 1 "Dragão Ciberlaser" da sua mão, Deck ou Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66625883,'Estrategista Karakuri mod. 248 "Nishipachi"',replace(replace('Este card deve atacar, se possível. \r\nQuando este card com a face para cima em Posição de Ataque for selecionado como alvo de um ataque, mude-o para Posição de Defesa. \r\nQuando este card for Invocado por Invocação-Normal ou Especial, selecione 1 monstro no campo e mude sua posição de batalha.','\r',char(13)),'\n',char(10)),'Mudar para Posição de Defesa','Mudar a posição de batalha','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66646087,'Fada Zetan Super Quantal',replace(replace('Se você controlar um monstro "Super Quant", exceto "Fada Zetan Super Quantal", e este card estiver na sua mão: você pode Invocar este card por Invocação-Especial e, depois, você pode fazer com que o Nível deste card se torne o mesmo que 1 monstro "Super Quant" que você controla. \r\nVocê pode oferecer este card como Tributo e enviar 1 card "Super Quant" do seu Deck para o Cemitério, exceto um monstro de TREVAS; Invoque por Invocação-Especial 1 monstro "Super Quant" do seu Deck, exceto "Fada Zetan Super Quantal". \r\nVocê só pode usar cada efeito de "Fada Zetan Super Quantal" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar este card por Invocação Especial','Invocar por Invocação Especial do Deck','Alterar o Nível?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66661678,'Cavaleiro Real da Barreira de Gelo',replace(replace('Se este card for Invocado por Invocação-Tributo: Invoque por Invocação-Especial 1 "Ficha de Caixão de Gelo" (Aqua/ÁGUA/Nível 1/ATK 1000/DEF 0) em Posição de Ataque no campo do seu oponente. \r\nEssa Ficha não pode ser oferecida como Tributo para uma Invocação-Tributo.','\r',char(13)),'\n',char(10)),'Invocar uma Ficha por Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66661679,'Ficha de Caixão de Gelo','Invocado por Especial com o efeito "Cavaleiro Real da Barreira de Gelo". Esta Ficha não pode ser oferecida como Tributo para uma Invocação-Tributo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66664203,'Dragão Cibernético da Revolução',replace(replace('Se você não controlar monstros, você pode Invocar por Invocação-Especial este card (da sua mão).\r\nVocê só pode usar cada um dos seguintes efeitos de "Dragão Cibernético da Revolução" uma vez por turno.\r\nSe este card for Invocado por Invocação-Especial: você pode escolher 1 monstro com a face para cima que seu oponente controla; negue seus efeitos até o final desse turno.\r\nDurante sua Fase Principal: você pode Invocar por Invocação-Especial 1 Monstro Fusão Máquina do seu Deck Adicional, usando monstros da sua mão ou campo, incluindo este card que você controla.','\r',char(13)),'\n',char(10)),'Negar o efeito','Invocação Fusão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66664204,'Dragão Cibernético da Revolução',replace(replace('Se você não controlar monstros, você pode Invocar por Invocação-Especial este card (da sua mão).\r\nVocê só pode usar cada um dos seguintes efeitos de "Dragão Cibernético da Revolução" uma vez por turno.\r\nSe este card for Invocado por Invocação-Especial: você pode escolher 1 monstro com a face para cima que seu oponente controla; negue seus efeitos até o final desse turno.\r\nDurante sua Fase Principal: você pode Invocar por Invocação-Especial 1 Monstro Fusão Máquina do seu Deck Adicional, usando monstros da sua mão ou campo, incluindo este card que você controla.','\r',char(13)),'\n',char(10)),'Negar o efeito','Invocação Fusão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66668900,'Aquatriz Guppy','Uma vez por turno: você pode Invocar por Invocação-Especial 1 monstro "Aquatriz" da sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66672569,'Dragão Zumbi','Um dragão renascido por feitiçaria. O seu hálito é altamente corrosivo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66675911,'Gênio Nehsombraneco',replace(replace('VIRE: Você pode escolher 1 monstro "Sombraneco" que você controla; esse monstro com a face para cima não é afetado por efeitos de monstro neste turno, exceto seus próprios.\r\nSe este card for enviado para o Cemitério por um efeito de card: você pode escolher 1 Monstro de Efeito no campo; nenhum duelista pode ativar os efeitos desse alvo no campo neste turno. \r\nVocê só pode usar 1 efeito de "Gênio Nehsombraneco" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66690411,'Cabeça no Ar','Enquanto este card permanecer no Campo com a face para cima, o seu adversário tem de mostrar a sua mão continuamente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66698383,'Dragão Mech Vermillion',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nUma vez por turno: você pode banir 1 Regulador da sua mão, do Cemitério ou do campo com a face para cima e, depois, escolha 1 card no campo; destrua-o. \r\nSe este card Invocado por Invocação-Sincro for destruído por um efeito de card e enviado para o Cemitério: você pode escolher 1 dos seus Reguladores banidos; adicione-o à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66699781,'Dragão Miragem do Caos',replace(replace('Você pode escolher 1 monstro banido de LUZ ou de TREVAS; Invoque-o por Invocação-Especial no seu campo, mas negue seus efeitos e, além disso, pelo resto deste turno, você não pode Invocar monstros por Invocação-Especial do Deck Adicional, exceto Monstros Sincro de LUZ ou de TREVAS. \r\nSe este card for enviado para o Cemitério como Matéria Sincro: você pode escolher cards que seu oponente controla, até o número de outros monstros usados para a Invocação-Sincro; bana-os. \r\nVocê só pode usar cada efeito de "Dragão Miragem do Caos" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66707058,'Goblin Infiltrado',replace(replace('Este card pode atacar diretamente seu oponente. \r\nSe este card atacar, ele é colocado em Posição de Defesa no final da Fase de Batalha. \r\nA posição de batalha deste card não pode ser alterada até o final do seu próximo turno, exceto com um efeito de card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66712593,'Soldado do Elemento',replace(replace('Este monstro obtém o(s) seguinte(s) efeito(s) enquanto existir(em) monstro(s) com o seguinte Atributo no Campo.\r\n● ÁGUA: O controle deste card não pode ser mudado.\r\n● TERRA: O efeito do Card de Monstro que este card destrúa como resultado de um combate é anulado.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66712905,'Anulação Rúnika',replace(replace('Ative 1 desses efeitos, mas pule sua próxima Fase de Batalha depois da ativação;\r\n● Se seu oponente adicionar um ou mais cards do Deck dele à mão dele, exceto durante a Fase de Compra, descarte 1 card aleatório da mão dele e, depois, bana os 2 cards do topo do Deck dele.\r\n● Invoque por Invocação-Especial 1 monstro "Rúnika(o)" do seu Deck Adicional na Zona de Monstros Adicional.	\r\nVocê só pode ativar 1 "Anulação Rúnika" por turno.','\r',char(13)),'\n',char(10)),'Descarte 1 card','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66719324,'Chuva da Misericórdia','Aumente em 1000 os PV dos dois duelistas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66719533,'Asimmetafis',replace(replace('Uma vez por turno: você pode banir 1 card "Metafis" da sua mão e, se isso acontecer, compre 1 card. \r\nUma vez por turno, se um card "Metafis" seu em posse do seu dono for banido: aplique este efeito dependendo de quem é o turno.\r\n● Seu turno: Todos os monstros no campo perdem 500 de ATK/DEF, exceto monstros "Metafis".\r\n● Turno do oponente: Mude a posição de batalha de todos os monstros no campo, exceto monstros "Metafis".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66722103,'Monge da Trovoada',replace(replace('Quando seu oponente ativar um efeito de monstro enquanto você controlar este monstro Invocado por Invocação-Especial (Efeito Rápido): você pode oferecer este card como Tributo; negue a ativação e, se isso acontecer, destrua-o. \r\nSe este card for enviado do campo para o Cemitério: você pode Invocar por Invocação-Especial 1 monstro Trovão da sua mão em Posição de Defesa. \r\nVocê só pode usar cada efeito de "Monge da Trovoada" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66727115,'Bujinfiel','Ofereça como Tributo 1 monstro "Bujin" do Tipo Besta-Guerreira e, depois, escolha 1 monstro "Bujin" com um nome diferente no seu Cemitério; Invoque o alvo por Invocação-Especial.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66729231,'Gishki Zielgigas',replace(replace('Você pode Invocar este card por Invocação-Ritual com qualquer Card de Magia de Ritual "Gishki". \r\nUma vez por turno: você pode pagar 1000 Pontos de Vida; compre 1 card e, se isso acontecer, revele-o e, depois, se o card for um monstro "Gishki", embaralhe 1 card do campo no Deck.','\r',char(13)),'\n',char(10)),'Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66730191,'Kaimen Sangen',replace(replace('Aplique 1 desses efeitos ou, se você ativou este card durante a Fase de Batalha, você pode aplicar quaisquer deles, em sequência.\r\n● Adicione 1 monstro Dragão de FOGO de Nível 4 ou menos do seu Deck à sua mão.\r\n● Invoque por Invocação-Especial 1 monstro Dragão de FOGO da sua mão.	\r\nVocê só pode ativar 1 "Kaimen Sangen" por turno.','\r',char(13)),'\n',char(10)),'','Adicionar do Deck à sua mão?','Invocar por Invocação Especial da sua mão?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66733743,'T.G. Esqueleto de Metal',replace(replace('Se um ou mais monstros no campo forem destruídos em batalha ou por um efeito de card do oponente: você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe um ou mais monstros "T.G." que você controla seriam destruídos em batalha ou por um efeito de card, em vez disso, você pode banir este card do seu campo ou Cemitério. \r\nVocê só pode usar cada efeito de "T.G. Esqueleto de Metal" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66736715,'Cavaleiro Moissa, o General Cometa',replace(replace('Escala de Pêndulo = 11\r\n[ Efeito de Pêndulo ]\r\nSe você Invocar um ou mais monstros por Invocação-Pêndulo: coloque este card no topo ou no fundo do Deck.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nQuando você comprar este card: você pode revelá-lo; durante sua Fase Principal neste turno, você pode conduzir 1 Invocação-Pêndulo de um ou mais monstros da sua mão em adição à sua Invocação-Pêndulo. \r\n(Você só pode se aproveitar deste efeito uma vez por turno.)','\r',char(13)),'\n',char(10)),'','Topo do Deck','Fundo do Deck','','Invocação Pêndulo usando o efeito de "Cavaleiro Moissa, o General Cometa"','','','','','','','','','','','');
INSERT INTO texts VALUES(66736884,'Keel, o Construtor Naval de Peluguel',replace(replace('2 monstros com Tipos diferentes	\r\nSe este card for Invocado por Invocação-Link: você pode Baixar 1 Magia/Armadilha "de Peluguel" ou 1 "Fandora, o Peloforte Voador" do seu Deck e, além disso, você não pode Invocar por Invocação-Especial pelo resto deste turno, exceto monstros "de Peluguel". \r\nDurante o turno do seu oponente (Efeito Rápido): você pode banir este card do seu Cemitério e, se isso acontecer, Invoque por Invocação-Especial 1 monstro "de Peluguel" da sua mão e, depois, se seu oponente controlar um monstro com o maior ATK original no campo (mesmo se empatado), você pode Invocar por Invocação-Especial mais 1 desses monstros. \r\nVocê só pode usar cada efeito de "Keel, o Construtor Naval de Peluguel" uma vez por turno.','\r',char(13)),'\n',char(10)),'Baixar','Invocação Especial','Invocar por Invocação Especial novamente?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66740005,'Bravo, o Lutador de Peluguel',replace(replace('Durante sua Fase Principal: você pode Invocar por Invocação-Especial 1 monstro "de Peluguel" da sua mão, exceto "Bravo, o Lutador de Peluguel". \r\nSe um monstro "de Peluguel" for Invocado por Invocação-Especial no seu campo enquanto você controlar este monstro (exceto durante a Etapa de Dano): você pode fazer com que todos os monstros "de Peluguel" atualmente no campo ganhem 500 de ATK/DEF até o final deste turno. \r\nVocê só pode usar cada efeito de "Bravo, o Lutador de Peluguel" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66742250,'Maldição de Anúbis',replace(replace('Coloque todos os Monstros de Efeito no campo em Posição de Defesa. \r\nAté o final deste turno, a DEF original desses monstros se torna 0 e, além disso, suas posições de batalha não podem ser alteradas.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66749546,'Gelojade Rei Pescador da Criação',replace(replace('Você pode escolher 1 monstro de ÁGUA que você controla; equipe este card da sua mão ou do campo a ele. \r\nUm monstro "Gelojade" equipado com este card pode atacar enquanto estiver em Posição de Defesa. \r\nSe o fizer, use sua DEF para o cálculo de dano. \r\nEnquanto este card estiver equipado a um monstro: você pode escolher 1 monstro que seu oponente controla com ATK igual ou menor que a DEF do monstro equipado; Invoque este card por Invocação-Especial e, se isso acontecer, devolva o monstro alvo para a mão. \r\nVocê só pode usar este efeito de "Gelojade Rei Pescador da Criação" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66750703,'Fortaleza de Fogo sobre os Picos Liang',replace(replace('(Este card deve ser sempre considerado como um card "Formação de Fogo".)	\r\nSempre que um ou mais monstros "Punho de Fogo" forem Invocados por Invocação-Normal ou Especial, coloque 1 Marcador de Punho de Fogo neste card. \r\nUma vez por turno: você pode remover Marcadores de Punho de Fogo do seu campo para ativar 1 desses efeitos;\r\n● 2: Se um monstro Besta-Guerreira seu atacar neste turno, seu oponente não pode ativar cards ou efeitos até o final da Etapa de Dano.\r\n● 6: Adicione 1 monstro Besta-Guerreira do seu Deck à sua mão.\r\n● 10: Invoque por Invocação-Especial 1 monstro Besta-Guerreira do seu Deck ou Deck Adicional, ignorando suas condições de Invocação.','\r',char(13)),'\n',char(10)),'2: Restrição de efeito','6: Busca no Deck','10: Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66752837,'Defensor do Santuário',replace(replace('Este card pode ser considerado como 2 Tributos para a Invocação-Tributo de um monstro Dragão. \r\nEnquanto este card estiver na sua mão ou no Cemitério, se um monstro Dragão com a face para cima no campo, exceto "Defensor do Santuário", for enviado para o Cemitério por um efeito de card ou porque foi destruído em batalha: você pode Invocar este card por Invocação-Especial e, depois, se esse monstro enviado para o Cemitério for um Monstro Normal, você pode adicionar 1 Monstro Normal Dragão do seu Cemitério à sua mão. \r\nVocê só pode usar este efeito de "Defensor do Santuário" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar 1 Monstro Normal Dragão do seu Cemitério à sua mão?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66762372,'Irmandade do Punho de Fogo - Javali',replace(replace('Não pode ser usado como um Monstro-Matéria Sincro, exceto para a Invocação-Sincro de um monstro de FOGO. \r\nQuando este card for destruído em batalha e enviado para o Cemitério: você pode Invocar por Invocação-Especial 1 monstro "Punho de Fogo" de Nível 4 do seu Deck, exceto "Irmandade do Punho de Fogo - Javali". \r\nUma vez por turno, quando um monstro "Punho de Fogo" for Invocado por Invocação-Especial do seu Deck Adicional: você pode Baixar 1 Card de Magia "Formação de Fogo" diretamente do seu Deck.','\r',char(13)),'\n',char(10)),'Invocação Especial','Baixar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66765023,'Elefante Voador',replace(replace('Uma vez por turno do oponente, se este card seria destruído por um efeito de card do oponente, ele não é destruído. \r\nUma vez por turno, durante a Fase Final do oponente, se esse efeito foi aplicado neste turno: aplique o seguinte efeito.\r\n● Durante seu próximo turno, se este card causar dano de batalha ao seu oponente em um ataque direto, você vence o Duelo.','\r',char(13)),'\n',char(10)),'Efeito está sendo aplicado','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66768175,'Camarartista de Baladas',replace(replace('Escala de Pêndulo = 2\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno, no começo da Etapa de Dano, quando seu monstro "Camarartista" batalhar um monstro com a face para cima do oponente: você pode fazer com que esse monstro do oponente perca 600 de ATK (mesmo que este card deixe o campo).\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe seu monstro "Camarartista" atacou, depois do cálculo de dano: você pode escolher 1 monstro com a face para cima que seu oponente controla; o alvo perde ATK igual ao ATK desse monstro "Camarartista".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66787942,'Predaplanta Bal Teah',replace(replace('1 Regulador + 1+ não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro: você pode Invocar por Invocação-Especial 1 monstro "Predaplanta" ou "Peçonha Insaciável" do seu Deck Adicional com a face para cima ou Cemitério. \r\nSe um ou mais monstros forem Invocados por Invocação-Especial no campo do seu oponente (exceto durante a Etapa de Dano): você pode banir 1 "Polimerização" e este card do seu Cemitério; Invoque por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional, usando monstros da sua mão ou do campo. \r\nVocê só pode usar cada efeito de "Predaplanta Bal Teah" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Invocação Fusão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66788016,'Fissura','Destrua o 1 monstro com a face para cima que seu oponente controla com o menor ATK (em caso de empate, você seleciona).','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66789970,'Dragão Hierático de Sutekh',replace(replace('Não pode ser Invocado por Invocação-Normal ou Baixado. \r\nDeve primeiro ser Invocado por Invocação-Especial (da sua mão) ao banir 3 Monstros Normais do Tipo Dragão do seu Cemitério. \r\nUma vez por turno: Você pode banir 1 monstro do Tipo Dragão do seu Cemitério para escolher 1 card no campo; destrua o alvo.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66809920,'Valquíria-Erste',replace(replace('Se este card for Invocado por Invocação-Especial da sua mão por um efeito de Magia: você pode escolher 1 "Travessura da Deusa do Tempo" no seu Cemitério; adicione-o à sua mão. \r\nSe você controlar um monstro "Valquíria-" que não seja "Valquíria-Erste" (Efeito Rápido): você pode banir 1 monstro do Cemitério do seu oponente e, depois, até o final deste turno, o ATK deste card se torna igual ao ATK original do monstro banido. \r\nVocê só pode usar cada efeito de "Valquíria-Erste" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66815913,'Shinobird Grua',replace(replace('Não pode ser Invocado por Invocação-Especial. \r\nUma vez por turno, se outro monstro Espírito for Invocado por Invocação-Normal ou Especial enquanto este monstro estiver no campo: você pode comprar 1 card. \r\nUma vez por turno, durante a Fase Final, se este card foi Invocado por Invocação-Normal ou virado com a face para cima neste turno: devolva-o para a mão.','\r',char(13)),'\n',char(10)),'Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66816282,'Parede Koa''ki Meiru',replace(replace('Durante cada uma das suas Fases Finais, destrua este card a não ser que você envie 1 "Núcleo de Ferro de Koa''ki Meiru" da sua mão para o Cemitério ou revele 1 monstro Rocha da sua mão. \r\nQuando seu oponente ativar um Card de Magia (Efeito Rápido): você pode oferecer este card como Tributo; negue a ativação e, se isso acontecer, destrua esse card.','\r',char(13)),'\n',char(10)),'Escolha 1 "Núcleo de Ferro de Koa''ki Meiru" para enviar para o Cemitério','Revelar ao oponente 1 monstro Rocha','Destruir "Parede Koa''ki Meiru"','Negue a ativação de uma Magia e a destrua','','','','','','','','','','','','');
INSERT INTO texts VALUES(66818682,'Dragão da Lua Quilla',replace(replace('"Supay" + 1+ monstros não-Reguladores	\r\nSe este card for escolhido como alvo de um ataque: ganhe PV igual à metade do ATK do monstro atacante. \r\nSe este card no campo for destruído: você pode escolher 1 "Dragão do Sol Inti" no seu Cemitério; Invoque o alvo por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Ganhar PV','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66835946,'Pirâmide das Maravilhas',replace(replace('Todos os monstros Zumbi que você controla ganham 200 de ATK para cada monstro que seu oponente controla. \r\nSe exatamente 1 monstro Zumbi que você controla (e nenhum outro card) seria destruído, em vez disso, você pode enviar este card para o Cemitério.','\r',char(13)),'\n',char(10)),'Usar o efeito de "Pirâmide das Maravilhas" em vez de ser destruído?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66836598,'Hidrodragão Fada','Uma fada de água que dizem ser capaz de invocar uma serpente marinha gigante.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66848311,'Cinzenta pela Eternidade',replace(replace('Quando este card for ativado: você pode adicionar 1 "Veidos, o Dragão de Erupção da Extinção" ou 1 monstro "Cinzento(a)" do seu Cemitério à sua mão. \r\nVocê pode escolher 1 monstro com a face para cima que seu oponente controla do qual você seja dono; tome o controle desse monstro e, depois, você pode fazer com que todos os monstros com a face para cima que seu oponente controla atualmente percam ATK igual ao ATK original do monstro alvo. \r\nEsta mudança de ATK dura até o final deste turno. \r\nVocê só pode usar este efeito de "Cinzenta pela Eternidade" uma vez por turno. \r\nVocê só pode ativar 1 "Cinzenta pela Eternidade" por turno.','\r',char(13)),'\n',char(10)),'Adicionar do Cemitério à sua mão?','Tomar controle','Reduzir ATK?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66853752,'Lançador Peixeborgue',replace(replace('Não pode ser usado como Matéria Sincro, exceto para a Invocação-Sincro de um Monstro Sincro de ÁGUA. \r\nSe você tiver um ou mais monstros no seu Cemitério que não sejam "Lançador Peixeborgue" e todos eles forem de ÁGUA: você pode Invocar este card por Invocação-Especial do seu Cemitério, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar este efeito de "Lançador Peixeborgue" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66863374,'Pantera de Laboratório',replace(replace('2 monstros, incluindo um monstro "Besta Gladiadora"	\r\nSe este card for Invocado por Invocação-Link: você pode adicionar 1 card "Besta Gladiadora" do seu Deck à sua mão. \r\nVocê pode escolher 1 monstro "Besta Gladiadora" que você controla; embaralhe esse monstro "Besta Gladiadora" no Deck e, se isso acontecer, Invoque por Invocação-Especial do seu Deck 1 monstro "Besta Gladiadora" com um nome original diferente. \r\n(Isso é considerado uma Invocação-Especial pelo efeito de um monstro "Besta Gladiadora".) \r\nVocê só pode usar cada efeito de "Pantera de Laboratório" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66865880,'Óculos de Marshmallon','Enquanto "Marshmallon" estiver na sua Zona de Monstros, seu oponente não pode escolher atacar monstros que não sejam "Marshmallon".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66870733,'Yuki-Onna, a Mayakashi de Gelo',replace(replace('2 monstros "Mayakashi"	\r\nVocê só pode controlar 1 "Yuki-Onna, a Mayakashi de Gelo". \r\nEnquanto este card apontar para um ou mais Monstros Sincro, os monstros do seu oponente não podem escolher este card como alvo de ataques. \r\nSe um ou mais Monstros Sincro em sua posse forem destruídos em batalha ou por um efeito de card do oponente enquanto este card estiver no campo: você pode escolher 1 monstro com a face para cima no campo; até o final deste turno, seu ATK/DEF se tornam metade do seu ATK/DEF atuais. \r\nVocê só pode usar este efeito de "Yuki-Onna, a Mayakashi de Gelo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66889139,'Gaia, o Matador de Dragões','"Gaia, o Cavaleiro Impetuoso" + "Maldição do Dragão"','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66926224,'A Lei do Normal',replace(replace('Você pode activar este card apenas quando estiverem 5 Monstros Normais de Nível 2 ou menos no seu Campo com a face para cima. \r\nAmbos os jogadores descartam todos os cards nas suas mãos, e destróiem todos os cards no Campo exceto os Monstros Normais de Nível 2 ou menos.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66927994,'Tanque Oni T-34','Um tanque blindado possuído por um demônio que perseguirá seus inimigos até os esmagar.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66938505,'Cristron Rion',replace(replace('Durante a Fase Principal ou Fase de Batalha do seu oponente: você pode escolher 1 dos seus monstros não-Regulador banidos; Invoque-o por Invocação-Especial, mas ele tem seus efeitos negados (se houver) e, se isso acontecer, imediatamente depois que este efeito resolver, Invoque por Invocação-Sincro 1 Monstro Sincro do Tipo Máquina usando apenas esse monstro e este card (este é um Efeito Rápido). \r\nEssas Matérias Sincro são embaralhadas no Deck em vez de serem enviadas para o Cemitério. \r\nVocê só pode usar este efeito de "Cristron Rion" uma vez por turno.','\r',char(13)),'\n',char(10)),'Banir, Invocar por Invocação Especial e fazer uma Invocação Sincro Acelerada','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66947414,'Corrida para o Chefe',replace(replace('Só pode ser ativado se você não Invocou por Invocação-Normal/Baixou neste turno. \r\nVocê não pode Invocar por Invocação-Normal/Baixar. \r\nDurante a Fase Final, se um ou mais monstros "B.E.S." com a face para cima que você controla foram destruídos e enviados para o Cemitério neste turno enquanto este card estava com a face para cima na sua Zona de Magias & Armadilhas: você pode Invocar por Invocação-Especial 1 monstro "B.E.S." do seu Deck.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66947913,'Fogo Ascendente',replace(replace('(Este card deve ser sempre considerado como um card "Salamagrande".)	\r\nSe você não controlar nenhum monstro: ative este card ao escolher 1 monstro de FOGO no seu Cemitério; Invoque-o por Invocação-Especial e equipe-o com este card. \r\nO monstro equipado ganha 500 de ATK. \r\nQuando este card deixar o campo, destrua esse monstro. \r\nSe este card em sua posse for destruído por um efeito de card do oponente: você pode banir 1 monstro no campo. \r\nVocê só pode usar cada efeito de "Fogo Ascendente" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66957584,'Lançador Inférnico',replace(replace('Uma vez por turno: você pode enviar 1 monstro "Inférnico(a)" da sua mão para o Cemitério. \r\nVocê pode enviar este card com a face para cima da Zona de Magias & Armadilhas para o Cemitério e, depois, escolha até 2 monstros "Inférnico(a)" no seu Cemitério; Invoque-os por Invocação-Especial. \r\nVocê não pode ter cards na sua mão para ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Enviar 1 monstro "Inférnico/a" da sua mão para o Cemitério','Invocar por Invocação Especial 1 monstro "Inférnico/a" do seu Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66957585,'Lançador Inférnico',replace(replace('Uma vez por turno: você pode enviar 1 monstro "Inférnico(a)" da sua mão para o Cemitério. \r\nVocê pode enviar este card com a face para cima da Zona de Magias & Armadilhas para o Cemitério e, depois, escolha até 2 monstros "Inférnico(a)" no seu Cemitério; Invoque-os por Invocação-Especial. \r\nVocê não pode ter cards na sua mão para ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Enviar 1 monstro "Inférnico/a" da sua mão para o Cemitério','Invocar por Invocação Especial 1 monstro "Inférnico/a" do seu Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66961194,'Ditador dos Dragões',replace(replace('Enquanto você controlar um monstro "Olhos Azuis", você seleciona os alvos dos ataques do seu oponente. \r\nVocê só pode usar cada um dos seguintes efeitos de "Ditador dos Dragões" uma vez por turno. \r\nVocê pode enviar 1 "Dragão Branco de Olhos Azuis" da sua mão ou do Deck para o Cemitério; Invoque este card por Invocação-Especial da sua mão. \r\nVocê pode descartar 1 "Dragão Branco de Olhos Azuis" ou 1 card que o mencione e, depois, escolha 1 monstro "Olhos Azuis" no seu Cemitério; Invoque-o por Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66970002,'Número C39: Raio V Utopia',replace(replace('3 monstros de Nível 5	\r\nQuando este card em posse do seu dono for destruído por um card do oponente: você pode escolher 1 Monstro Xyz no seu Cemitério; devolva o alvo para o Deck Adicional. \r\nSe este card tiver um monstro "Utopia" como matéria, ele ganha este efeito.\r\n● Uma vez por turno: você pode desassociar 1 matéria deste card e, depois, escolha 1 monstro que seu oponente controla; destrua esse monstro e, se ele estava com a face para cima, cause dano ao seu oponente igual ao ATK que o monstro destruído tinha no campo.','\r',char(13)),'\n',char(10)),'Retornar ao Deck','Destrua e cause dano','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66970385,'Capítulo Perdido dos Nobre Cavaleiros',replace(replace('Se seu oponente controlar um monstro e você não controlar nenhum monstro: você pode escolher 1 Card de Magia de Equipamento "Armas Nobres" e 1 monstro "Nobre Cavaleiro" apropriado no seu Cemitério; Invoque esse monstro por Invocação-Especial e, se isso acontecer, equipe esse Card de Magia de Equipamento ao monstro apropriado. \r\nVocê só pode ativar 1 "Capítulo Perdido dos Nobre Cavaleiros" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66973070,'Ceifador da Foice Temível','Você pode oferecer como Tributo 1 monstro do Tipo Inseto para fazer com que este card ganhe 500 de ATK até o final do turno.','Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66975205,'Nhamyversão☆Mignon',replace(replace('Monstros "Nhamy" que você controla ganham 500 de ATK para cada monstro Besta de LUZ no campo. \r\nVocê só pode usar cada um dos seguintes efeitos de "Nhamyversão☆Mignon" uma vez por turno. \r\nSe você controlar um monstro de Link-1: você pode escolher 1 monstro "Nhamy" de Nível 1 no seu Cemitério; Invoque-o por Invocação-Especial. \r\nSe este card estiver no seu Cemitério: você pode escolher 2 monstros "Nhamy" no seu Cemitério e/ou banimento; coloque este card, e eles, no fundo do Deck em qualquer ordem.','\r',char(13)),'\n',char(10)),'','Invoque por Invocação Especial 1 monstro do Cemitério','Retornar ao Deck','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66976526,'Karakuri Shogun de Aço mdl 00X "Bureido"',replace(replace('1 Regulador + 1+ monstros Máquina não-Reguladores	\r\nQuando este card for Invocado por Invocação-Sincro: você pode Invocar por Invocação-Especial 1 monstro "Karakuri" do seu Deck. \r\nUma vez por turno, se a posição de batalha de um ou mais monstros "Karakuri" com a face para cima que você controla for mudada: compre 1 card.','\r',char(13)),'\n',char(10)),'Invocação Especial','Comprar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66984907,'Divertida Atração Montanha Ciclone',replace(replace('Escolha 1 monstro "Diversão" que você controla ou 1 monstro com a face para cima que seu oponente controla; equipe este card a ele. \r\nVocê pode ativar o seguinte efeito, de acordo com qual duelista controla o monstro equipado;\r\n● Você: Escolha 1 Magia/Armadilha que seu oponente controla; envie tanto ele como este card para o Cemitério.\r\n● Seu oponente: Adicione 1 monstro "Diversão" do seu Deck à sua mão e, se isso acontecer, envie este card para o Cemitério.	\r\nVocê só pode usar este efeito de "Divertida Atração Montanha Ciclone" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66989694,'O Conde da Morte','Esta criatura cavalheiresca é extremamente perversa, temida tanto por homens como demônios.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(66994718,'Vendaval do Raptor','Quando um Card de Magia/Armadilha for ativado enquanto você controlar um card "Ataqueraptor" card: negue a ativação e, se isso acontecer, destrua esse card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67007102,'Guardião da Terra Dourada',replace(replace('Invoque este card por Invocação-Especial como um Monstro Normal (Zumbi/LUZ/Nível 8/ATK 800/DEF 2500) (este card ainda é considerado uma Armadilha) e, depois, se você controlar "Eldlich, o Senhor Dourado", você pode fazer com que o ATK de 1 monstro com a face para cima no campo se torne 0. \r\nDurante a Fase Final: você pode banir este card do seu Cemitério; Baixe 1 Magia/Armadilha "Eldlixir" diretamente do seu Deck. \r\nVocê só pode usar 1 efeito de "Guardião da Terra Dourada" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Fazer o ATK do card selecionado se tornar 0?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67021206,'Hecamãos Jauzah',replace(replace('1 monstro "Hecamãos" + 1 monstro Ilusão	\r\nPrimeiro deve ser Invocado por Invocação-Fusão, ou por Invocação-Especial (do seu Deck Adicional) ao oferecer como Tributo 2 monstros que você controla (1 monstro com a face para cima do qual seu oponente seja dono e 1 monstro Ilusão). \r\nSe este card batalhar um monstro, nenhum dos dois pode ser destruído nessa batalha. \r\nDurante sua Fase Principal: você pode adicionar 1 card "Hecamãos" do seu Deck ou Cemitério à sua mão. \r\nVocê só pode usar este efeito de "Hecamãos Jauzah" uma vez por turno.','\r',char(13)),'\n',char(10)),'Efeito de busca','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67030233,'Dragão Vermelho Majestoso',replace(replace('"Dragão Majestoso" + "Dragão Vermelho Arquidemônio" + 1 monstro não-Regulador	\r\nNão pode ser destruído por efeitos de card. \r\nDepois do cálculo de dano, se este card atacar: destrua todos os monstros em Posição de Defesa no campo. \r\nUma vez por turno: você pode escolher 1 monstro com a face para cima que seu oponente controla; negue os efeitos dele e, se isso acontecer, este card ganha ATK igual ao ATK desse monstro. \r\nEssas mudanças duram até o final deste turno. \r\nDurante a Fase Final: escolha 1 "Dragão Vermelho Arquidemônio" no seu Cemitério; devolva este card do campo para o Deck Adicional e, depois, Invoque o alvo por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Destrua todos os monstros em Posição de Defesa','Negar efeitos','Retornar ao Deck Adicional','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67037924,'Titanocida',replace(replace('Escolha 1 monstro com a face para cima que seu oponente controla que foi Invocado por Invocação-Especial do Deck Adicional; mude o ATK dele para 0 e, se isso acontecer, negue seus efeitos. \r\nSe seu oponente Invocar um ou mais monstros por Invocação-Especial do Deck Adicional enquanto este card estiver no seu Cemitério, exceto no turno em que este card foi enviado para o Cemitério: você pode Baixar este card. \r\nVocê só pode usar cada efeito de "Titanocida" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67038874,'Leitor de Mentes de Restolhos',replace(replace('Uma vez por turno, enquanto este card estiver no seu Cemitério durante a sua Fase Principal 2, você pode selecionar 1 monstro "Restolhos" com a face para cima que você controla, exceto "Leitor de Mentes de Restolhos". \r\nDestrua esse monstro e Invoque por Invocação-Especial este card do Cemitério. \r\nSe isso acontecer, remova este card de jogo quando ele for removido do campo. \r\nSe este card for usado como um Monstro-Matéria Sincro, todos os outros Monstros-Matéria Sincro devem ser monstros "Restolhos".','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67045174,'Buraco Armadilha de Gêmeos',replace(replace('Ative apenas quando um monstro Gêmeos que é considerado como um Monstro de Efeito for destruído em batalha. \r\nDestrua todos os monstros que seu oponente controla.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67045745,'F.A. Amo Sônico',replace(replace('Ganha ATK igual ao seu Nível x 300. \r\nNão pode ser destruído em batalha com um monstro do oponente cujo Nível/Classe original seja menor que o Nível deste card. \r\nSempre que um Card ou efeito de Magia/Armadilha "F.A." for ativado: você pode aumentar em 1 o Nível deste card. \r\nSe este card for de Nível 7 ou mais, ele pode realizar até 2 ataques contra monstros durante cada Fase de Batalha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67048711,'7',replace(replace('Quando estiverem 3 cards "7" no seu Campo com a face para cima, compre 3 cards do seu Deck. \r\nEm seguida, destrúa todos os cards "7". \r\nQuando este card é enviado do Campo para o seu Cemitério, aumente os seus Life Points em 700 pontos.','\r',char(13)),'\n',char(10)),'Comprar','Ganhar PV','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67049542,'Morcego das Trevas','Morcegos dos mundos baixos que usam seus hiper sentidos para detectar seus inimigos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67050396,'Bruxa Bondosa de Kozmo',replace(replace('Durante o turno de qualquer duelista: você pode banir este card; Invoque por Invocação-Especial 1 monstro "Kozmo" de Nível 5 ou mais da sua mão. \r\nVocê só pode usar este efeito de "Bruxa Bondosa de Kozmo" uma vez por turno. \r\nUma vez por turno: você pode pagar 500 PV e, depois, escolher 1 monstro com a face para cima que seu oponente controla; coloque-o com a face para baixo em Posição de Defesa.','\r',char(13)),'\n',char(10)),'Invoque por Invocação Especial 1 monstro "Kozmo" da sua mão','Mudar um monstro para Posição de Defesa com a face para baixo','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67073561,'Baba Barbeira',replace(replace('2 monstros	\r\nNo começo de cada Fase de Batalha: você pode escolher este card ou 1 monstro para o qual este card apontar; bana-o até a Fase Final. \r\nVocê só pode usar este efeito de "Baba Barbeira" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67095270,'Barreira Dimensional',replace(replace('Você só pode ativar este card quando o seu adversário declarar um ataque com um monstro. \r\nSomente o seu adversário recebe o Dano de Batalha que você iria receber como resultado desta batalha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67098114,'Loki, Senhor dos Aesir',replace(replace('1 Regulador "Alfar Nórdico" + 2+ monstros não-Reguladores	\r\nUma vez por turno, quando seu oponente ativar um Card de Magia/Armadilha durante sua Fase de Batalha (Efeito Rápido): você pode negar a ativação e, se isso acontecer, destrua-o. \r\nUma vez por turno, durante a Fase Final, se este card com a face para cima que você controlava foi destruído por um card do seu oponente e enviado para o seu Cemitério neste turno: você pode banir 1 Regulador "Alfar Nórdico" do seu Cemitério; Invoque este card por Invocação-Especial. \r\nQuando Invocado desta forma: você pode escolher 1 Armadilha no seu Cemitério; adicione o alvo à sua mão.','\r',char(13)),'\n',char(10)),'Negue a ativação de uma Magia/Armadilha e a destrua','Invocação Especial','Adicione 1 Card de Armadilha do Cemitério à sua mão','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67098897,'Biscoito★Via Nhamy',replace(replace('1 Regulador + 1 monstro não-Regulador	\r\nPara a Invocação-Sincro deste card, você pode considerar 1 monstro de Link-1 que você controla como um Regulador de Nível 1. \r\nVocê só pode usar cada um dos seguintes efeitos de "Biscoito★Via Nhamy" uma vez por turno. \r\nSe este card for Invocado por Invocação-Sincro: você pode escolher até 2 monstros com a face para cima no campo; coloque-os com a face para baixo em Posição de Defesa. \r\nQuando seu oponente ativar um card ou efeito (Efeito Rápido): você pode devolver este card para o Deck Adicional; Invoque por Invocação-Especial até 2 monstros "Nhamy" do seu Cemitério.','\r',char(13)),'\n',char(10)),'Mudar para Posição de Defesa com a face para baixo','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67100549,'Gritos do Marcado',replace(replace('Se um Monstro de Fusão foi enviado para o seu Cemitério neste turno: Invoque por Invocação-Especial 1 dos seus Monstros de Fusão que estiverem banidos ou no seu Cemitério. \r\nDurante a Fase Final, se este card estiver no Cemitério porque foi enviado para lá para ativar o efeito de "Caído de Arbaz" neste turno: você pode Baixar este card. \r\nVocê só pode usar este efeito de "Gritos do Marcado" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67105242,'Espírito Terrestre','Uma criatura vingativa formada pelos espíritos de guerreiros caídos. Ela arrasta todos os que ousam se aproximar para as entranhas mais profundas da terra.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67111213,'Abismo Gishki','Quando este card for Invocado: você pode adicionar 1 monstro "Gishki" com 1000 ou menos de DEF do seu Deck à sua mão, exceto "Abismo Gishki".','Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67113830,'Fantasma de um Rancor','Se seu oponente tiver 8 ou mais cards no Cemitério dele: o ATK de todos os monstros que seu oponente controla atualmente se torna 0.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67115133,'Cântico do Tufão Radiante',replace(replace('Se este card for destruído pelo efeito de "Tufão Espacial Místico": você pode Baixar este card. \r\nAtive 1 desses efeitos (mas você só pode usar cada um desses efeitos de "Cântico do Tufão Radiante" uma vez por turno);\r\n● Adicione 1 monstro "Tufão Radiante" de Nível 4 ou menos do seu Deck à sua mão.\r\n● Adicione 1 "Tufão Espacial Místico" do seu Deck ou Cemitério à sua mão.','\r',char(13)),'\n',char(10)),'Ativar','Baixar','Adicionar à mão 1 monstro "Tufão Radiante"','Adicionar "Tufão Espacial Místico" à mão','','','','','','','','','','','','');
INSERT INTO texts VALUES(67120578,'Gagaga Cabeça',replace(replace('Se somente seu oponente controlar um monstro, você pode Invocar este card por Invocação-Normal sem oferecer Tributo como um monstro de Nível 4. \r\nQuando este card for Invocado por Invocação-Normal: você pode escolher até 2 monstros "Gagaga" no seu Cemitério, exceto "Gagaga Cabeça"; Invoque-os por Invocação-Especial e, além disso, você não pode Invocar por Invocação-Especial pelo resto deste turno, exceto por uma Invocação-Xyz que use apenas monstros "Gagaga" como matéria. \r\nUm Monstro Xyz que foi Invocado usando este card no campo como matéria ganha este efeito.\r\n● Se for Invocado por Invocação-Xyz: compre 1 card.','\r',char(13)),'\n',char(10)),'','','Compre 1 card (Gagaga Cabeça)','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67127799,'Calibre Foguette',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) em uma zona sua para a qual um Monstro Link de TREVAS apontar. \r\nVocê só pode Invocar "Calibre Foguette" por Invocação-Especial uma vez por turno desta forma. \r\nVocê pode oferecer este card como Tributo; Invoque por Invocação-Especial 1 monstro Dragão ou Máquina de TREVAS da sua mão, exceto "Calibre Foguette". \r\nVocê só pode usar este efeito de "Calibre Foguette" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67136033,'Capitão Técnico Homen-urso',replace(replace('Não pode ser usado como matéria para uma Invocação-Xyz, exceto para a Invocação-Xyz de um monstro Guerreiro de FOGO. \r\nVocê pode Invocar este card por Invocação-Normal sem oferecer Tributo, mas seu ATK original se torna 1300. \r\nUma vez por turno: você pode fazer com que todos os monstros Besta-Guerreira de Nível 4 que você controla atualmente se tornem de Nível 8 até o final deste turno.','\r',char(13)),'\n',char(10)),'Invocação Normal sem Tributo','Alterar Nível','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67159705,'Cibern de Armadura',replace(replace('Uma vez por turno, você pode: escolher 1 "Dragão Cibernético" que você controla ou 1 Monstro de Fusão que você controla que liste "Dragão Cibernético" como uma Matéria de Fusão; equipe este card no alvo, OU: desequipar este card e Invocá-lo por Invocação-Especial. \r\nUma vez por turno, enquanto este card estiver equipado a um monstro por este efeito: você pode escolher 1 monstro com a face para cima no campo; o monstro equipado perde exatamente 1000 de ATK (mesmo que este card eixe o campo) e, se isso acontecer, destrua o alvo. \r\nSe o monstro equipado seria destruído em batalha ou por um efeito de card, em vez disso, destrua este card.','\r',char(13)),'\n',char(10)),'Equipar','Invoque por Invocação Especial em Posição de Ataque com a face para cima','Reduza o ATK do monstro equipado em 1000 e depois destrua 1 monstro com a face para cima no Campo','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67169062,'Pote da Avarice','Escolha 5 monstros no seu Cemitério; embaralhe todos os 5 no Deck e, depois, compre 2 cards.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67169063,'Pote da Avarice','Escolha 5 monstros no seu Cemitério; embaralhe todos os 5 no Deck e, depois, compre 2 cards.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67171933,'Código Regênese',replace(replace('Invoque por Invocação-Especial 1 monstro "Regênese" do seu Deck (mas envie-o para o Cemitério durante a Fase Final do seu oponente) e, além disso, até o final do próximo turno depois que este card resolver, você não pode Invocar por Invocação-Especial do Deck Adicional. \r\nDurante sua Fase Principal, se este card estiver no seu Cemitério, exceto no turno em que foi enviado para lá: você pode bani-lo e, depois, escolha 1 dos seus monstros "Regênese" banidos; Invoque-o por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Código Regênese" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial do Deck','Invoque por Invocação Especial um monstro banido','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67173574,'Número C102: Arquidemônio Serafim',replace(replace('4 monstros de LUZ de Nível 5	\r\nSe este card com a face para cima seria destruído em batalha ou por um efeito de card, em vez disso, você pode desassociar 2 matérias deste card. \r\nSe a última matéria for desassociada deste card: cause 1500 de dano ao seu oponente. \r\nSe este card tiver "Número 102: Sentinela Serafim Estelar" como matéria, ele ganha este efeito.\r\n● Uma vez por turno: você pode desassociar 1 matéria deste card e, depois, escolha 1 monstro com a face para cima que seu oponente controla; mude o ATK do alvo para 0 e, se isso acontecer, negue seus efeitos.','\r',char(13)),'\n',char(10)),'Usar o efeito de "Número C102: Arquidemônio Serafim" em vez de ser destruído?','Causar dano','O ATK se torna 0','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67196946,'Explosão Estelar','Pague qualquer número de Pontos de Vida em múltiplos de 500; até a Fase Final, reduza o Nível de 1 monstro que você controla ou que esteja em sua mão em 1 para cada 500 Pontos de Vida que você pagou.','Escolha os PV a pagar','Escolha o monstro cujo Nível será reduzido','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67211766,'Majioshaleon',replace(replace('Seu oponente não pode selecionar este card como alvo de ataque enquanto ele controlar quaisquer Cards de Magia/Armadilha. \r\nDurante a batalha entre este card atacante e um monstro em Posição de Defesa cuja DEF seja menor que o ATK deste card, cause a diferença como Dano de Batalha ao seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67216732,'Força-S Apanhador Noturno',replace(replace('2 monstros, incluindo um monstro "Força-S"	\r\nSe este card for Invocado por Invocação-Especial: você pode adicionar 1 Magia/Armadilha "Força-S" do seu Deck à sua mão. \r\n(Efeito Rápido): você pode banir este card que você controla e 1 card "Força-S" na sua mão; Invoque por Invocação-Especial 1 monstro "Força-S" do seu Deck/Deck Adicional, exceto "Força-S Apanhador Noturno". \r\nVocê só pode usar cada efeito de "Força-S Apanhador Noturno" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67218327,'SIMM Tablir',replace(replace('Você pode revelar este card na sua mão e, depois, escolher 1 monstro Ciberso de Nível 4 no seu Cemitério; Invoque este card por Invocação-Especial da sua mão em uma zona sua para a qual um Monstro Link linkado que você controla apontar e, se isso acontecer, devolva o monstro alvo para a mão. \r\nVocê só pode usar este efeito de "SIMM Tablir" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67223587,'Equipe de Luta Dupla',replace(replace('Ative apenas quando você Invocar por Invocação-Especial um monstro "Besta Gladiadora". \r\nInvoque por Invocação-Especial 1 monstro "Besta Gladiadora" de Nível 4 ou menos da sua mão ou Deck.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67225377,'Salamagrande Surica',replace(replace('Se este card for adicionado à sua mão, exceto se comprado em sua compra normal: você pode revelar este card; Invoque-o por Invocação-Especial da sua mão. \r\nSe este card estiver na sua mão: você pode descartar 1 outro card "Salamagrande"; Invoque este card por Invocação-Especial da sua mão. \r\nVocê só pode usar cada efeito de "Salamagrande Surica" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67227834,'Fórmula Mágica',replace(replace('Só pode ser equipado a "Mago Negro" ou "Pequena Maga Negra". \r\nEle ganha 700 de ATK. \r\nSe este card for enviado do campo para o Cemitério: ganhe 1000 PV.','\r',char(13)),'\n',char(10)),'Ganhar PV','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67231737,'Link Bumper',replace(replace('2 monstros Ciberso	\r\nUma vez por turno, no final da Etapa de Dano, se um monstro seu para o qual este card apontar atacar um Monstro Link do oponente: você pode ativar este efeito; o monstro atacante ganha 1 ataque adicional contra outro Monstro Link do oponente durante esta Fase de Batalha para cada Monstro Link que você controla atualmente, exceto este card. \r\nSeus monstros (exceto esse monstro) não podem atacar no turno em que você ativar este efeito.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67232306,'Correspondência do Espelho','Quando um monstro com a face para cima que você controla for escolhido como alvo de um ataque: o seu ATK se torna igual ao desse monstro atacante.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67234805,'Pedra Absorve-Poder',replace(replace('Sempre que um efeito de monstro for ativado, coloque 1 Marcador de Pedra Mágica neste card quando esse efeito resolver (máx. 2). \r\nEnquanto este card tiver 2 Marcadores de Pedra Mágica, nenhum duelista pode ativar os efeitos de monstros com a face para cima no campo e, além disso, os efeitos dos monstros com a face para cima no campo são negados. \r\nUma vez por turno, durante a Fase Final, se este card tiver quaisquer Marcadores de Pedra Mágica: remova-os.','\r',char(13)),'\n',char(10)),'Remova Marcadores','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67237709,'Cidade de Kozmo',replace(replace('Uma vez por turno: você pode escolher 1 dos seus monstros "Kozmo" banidos; devolva-o para a mão e, se isso acontecer, perca PV igual ao Nível original dele x 100. \r\nUma vez por turno: você pode revelar qualquer número de monstros "Kozmo" da sua mão e embaralhá-los no Deck e, depois, compre cards igual ao número de cards que você embaralhou no Deck. \r\nSe este card na Zona do Campo for destruído por um efeito de card: você pode adicionar 1 card "Kozmo" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Adicione 1 monstro "Kozmo" banido à sua mão','Retornar 1 monstro "Kozmo" da sua mão para o Deck e depois compre','Adicionar à sua mão 1 card "Kozmo" do seu Deck','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67248304,'Jarra Reversa',replace(replace('VIRE: Coloque tantos outros monstros no campo quanto possível com a face para baixo em Posição de Defesa e, depois, devolva tantas Magias/Armadilhas com a face para cima quanto possível do campo para a mão e, depois, cada duelista pode Baixar Magias/Armadilhas da mão dele, até o número devolvido à sua própria mão por este efeito. \r\nVocê só pode usar este efeito de "Jarra Reversa" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Baixar uma Magia/Armadilha?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67249508,'Brutalidade Yang Zing','Se um monstro "Yang Zing" que você controla batalhar um monstro do oponente, durante o cálculo de dano: o ATK/DEF do seu monstro que está batalhando se tornam o dobro do seu ATK/DEF originais, apenas durante esse cálculo de dano, mas destrua-o no final da Etapa de Dano.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67267333,'Cães de Caça Vendorror',replace(replace('Se este card estiver no seu Cemitério: você pode descartar 1 card "Vendorror"; Invoque este card por Invocação-Especial, mas bana-o quando ele deixar o campo. \r\nUm monstro "Vendorror" Invocado por Invocação-Ritual usando este card no campo ganha o seguinte efeito. \r\nVocê só pode usar cada um dos efeitos anteriores de "Cães de Caça Vendorror" uma vez por turno.\r\n● Uma vez por turno (Efeito Rápido): você pode escolher 1 Magia/Armadilha que seu oponente controla; bana-a.','\r',char(13)),'\n',char(10)),'Invocar este card por Invocação Especial','Banir uma Magia/Armadilha do seu oponente (Cães de Caça Vendorror)','O efeito de "Cães de Caça Vendorror" está sendo aplicado.','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67270095,'Turbo Sincron',replace(replace('Quando este card declarar um ataque: você pode colocar o alvo do ataque em Posição de Defesa. \r\nQuando você sofrer dano de batalha enquanto este card estiver atacando: você pode Invocar por Invocação-Especial 1 monstro da sua mão com ATK menor ou igual ao dano de batalha que você sofreu.','\r',char(13)),'\n',char(10)),'Mude o alvo do ataque para Posição de Defesa','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67273917,'Cavaleirardor Cavalier',replace(replace('Escala de Pêndulo = 2\r\n[ Efeito de Pêndulo ]\r\nSe você tiver um card "Cavaleirardor" na sua outra Zona de Pêndulo: você pode destruir os dois cards nas suas Zonas de Pêndulo e, se isso acontecer, adicione 1 monstro de FOGO do Tipo Guerreiro do seu Deck ou Cemitério à sua mão.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nAs ostentosas armas desse Cavaleirardor rosa já causaram tanto dano ao seu inimigo quanto às suas próprias tropas, mas ela alcança resultados, então poucos reclamam.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67282505,'Mitsu, a Ninja Inseto',replace(replace('Se você controlar um card "Ninja" ou um monstro com a face para baixo em Posição de Defesa: você pode Invocar este card por Invocação-Especial da sua mão. \r\nQuando seu oponente ativar um efeito de monstro (Efeito Rápido): você pode escolher 1 monstro com a face para baixo em Posição de Defesa que você controla; coloque-o com a face para cima em Posição de Defesa e, se isso acontecer, coloque este card com a face para baixo em Posição de Defesa e, depois, se o monstro alvo era um monstro "Ninja", exceto "Mitsu, a Ninja Inseto", negue esse efeito ativado do oponente. \r\nVocê só pode usar cada efeito de "Mitsu, a Ninja Inseto" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67284107,'Fantasma Expiatório','VIRE: Você pode Invocar por Invocação-Especial qualquer número de "Ficha de Ovelha Negra" (Zumbi/TREVAS/Nível 1/ATK 0/DEF 0).','Invocar uma Ficha por Invocação Especial','Continuar Invocando "Ficha de Ovelha Negra" por Invocação Especial?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67284108,'Ficha de Ovelha Negra','Invocado por Especial com o efeito "Fantasma Expiatório".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67284908,'Paredes do Labirinto','Estas paredes formam um labirinto sem saída para os inimigos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67287533,'Mensagem do Espírito "N"','Este card só pode ser colocado no campo pelo efeito de "Tábua do Destino".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67288539,'Dragão Codicallibre',replace(replace('2+ Monstros de Efeito	\r\nEste card não pode ser destruído por efeitos de card enquanto um Monstro Link apontar para ele. \r\nVocê só pode usar cada um dos seguintes efeitos de "Dragão Codicallibre" uma vez por turno. \r\nNo começo da Etapa de Dano, se este card que foi Invocado por Invocação-Link usando 3 monstros como matéria batalhar um monstro do oponente: você pode destruir todos os monstros no campo. \r\nVocê pode banir este card do seu Cemitério; bana 1 monstro de TREVAS com 3000 ou mais de ATK do campo e, se isso acontecer, Invoque por Invocação-Especial 1 monstro "Topológico(a)" do seu Deck Adicional ou Cemitério.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Link usando 3 monstros como Matéria','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67300516,'Wivern de Olhos Vermelhos',replace(replace('Uma vez por turno, durante sua Fase Final: você pode banir este card do seu Cemitério e, depois, escolha 1 monstro "Olhos Vermelhos" no seu Cemitério; Invoque o alvo por Invocação-Especial. \r\nVocê não pode Invocar por Invocação-Normal/Baixar durante o turno em que ativar este efeito.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67310848,'Dragão da Estrela Anã Planeter','Uma vez por turno, durante a Fase Final, se este card foi Invocado por Invocação-Normal neste turno: você pode adicionar 1 monstro de LUZ ou de TREVAS de Nível 7 do seu Deck à sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67314110,'Cômica, a Assistente da Diversão',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode Baixar 1 Armadilha "Atração" diretamente do seu Deck. \r\n(Efeito Rápido): você pode escolher 1 das suas Armadilhas "Atração" equipadas a um monstro; equipe-a a 1 monstro "Diversão" que você controla ou 1 monstro com a face para cima que seu oponente controla. \r\nVocê só pode usar este efeito de "Cômica, a Assistente da Diversão" uma vez por turno.','\r',char(13)),'\n',char(10)),'Baixar','Alterar o alvo de Equipamento','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67316075,'Senhora Obscura Enfermeira Reficule','Qualquer efeito que faria com que seu oponente ganhasse PV, em vez disso, causa o mesmo valor de dano a ele.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67322708,'D/D Soldado com Lança',replace(replace('Você pode escolher 1 monstro "D/D" que você controla; aumente o Nível dele em até o número de cards "Pacto Obscuro" no seu campo e Cemitério. \r\nSe este card estiver no seu Cemitério: você pode escolher 1 card "Pacto Obscuro" que você controla; destrua-o e, se isso acontecer, Invoque este card por Invocação-Especial, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar cada efeito de "D/D Soldado com Lança" uma vez por turno.','\r',char(13)),'\n',char(10)),'Aumentar o Nível','Invocação Especial','Escolha o Nível para aumentar','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67328336,'Fortaleza Senhormek',replace(replace('Nenhum duelista pode escolher monstros "Senhormek Imperador" que você controla como alvo de efeitos de Monstros Sincro. \r\nQuando este card no campo for destruído e enviado para o Cemitério: você pode adicionar 1 monstro "Senhormek Imperador" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67331360,'Casa de Bonecas',replace(replace('Você pode escolher 1 Monstro Normal no seu Cemitério com 0 de ATK ou de DEF, ou, se você controlar "Princesa Colônia", em vez disso, você pode escolher 2 desses monstros; Invoque por Invocação-Especial 1 monstro do seu Deck com o mesmo nome que cada um dos alvos, como um monstro de TREVAS de Nível 6. \r\nVocê só pode usar este efeito de "Casa de Bonecas" uma vez por turno. \r\nQuando um monstro do oponente declarar um ataque: você pode associar 1 "Vovô Demetto" que você controla a "Princesa Colônia" que você controla como matéria e, depois, encerre a Fase de Batalha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67359907,'Desastre, Dragão Soberano de Todos os Apocalipses',replace(replace('2 monstros de Classe 7	\r\nSe este card for Invocado por Invocação-Xyz: você pode escolher até 4 monstros "Dragão Soberano" de Nível 7 no seu Cemitério e/ou banimento; associe-os a este card e, depois, você pode banir todos os monstros do campo e Cemitério do seu oponente com um mesmo Atributo que o das matérias deste card. \r\nVocê só pode usar este efeito de "Desastre, Dragão Soberano de Todos os Apocalipses" uma vez por turno. \r\nEnquanto este card tiver monstros "Dragão Soberano" de LUZ, TREVAS, TERRA, ÁGUA, FOGO e VENTO como matéria, ele ganha 4600 de ATK/DEF e, além disso, ele não é afetado por outros efeitos de cards.','\r',char(13)),'\n',char(10)),'Associar matéria','Banir outro monstro?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67371383,'Besta Anfíbia','Na terra ou no mar, a velocidade deste monstro é imbatível.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67378104,'Observatório Celestial',replace(replace('Coloque no fundo do Deck 1 monstro de Nível 6 da sua mão ou com a face para cima no campo; compre 2 cards. \r\nVocê só pode ativar 1 "Observatório Celestial" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67378935,'Rede de Camadas',replace(replace('Você pode ativar 1 dos seguintes efeitos.\r\n● Escolha 1 monstro com a face para cima que você controla; Invoque por Invocação-Especial 1 monstro com o mesmo Nível da sua mão ou do Cemitério em Posição de Defesa, mas negue seus efeitos.	\r\nVocê não pode Invocar monstros por Invocação-Especial do Deck Adicional no turno em que ativar este efeito, exceto Monstros Xyz.\r\n● Escolha 1 Monstro Xyz que você controla; adicione à mão 1 card associado a ele.	\r\nVocê só pode usar este efeito de "Rede de Camadas" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invoque por Invocação Especial um monstro com o mesmo Nível','Adicione Matéria Xyz à sua mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67381587,'Gatástrofe Preto',replace(replace('Durante a Fase de Batalha do seu oponente, se você controlar 2 ou mais monstros com a face para baixo em Posição de Defesa: encerre a Fase de Batalha. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 2 monstros com a face para cima no campo, incluindo pelo menos 1 monstro "Princesa da Premonição"; coloque-os com a face para baixo em Posição de Defesa.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67385964,'Besta Gladiadora Noxious',replace(replace('Quando um monstro do oponente declarar um ataque direto: você pode Invocar este card por Invocação-Especial da sua mão e, se isso acontecer, mude o alvo do ataque para este card e siga para o cálculo de dano. \r\nEste card não pode ser destruído em batalha. \r\nSe este card for Invocado por Invocação-Especial pelo efeito de um monstro "Besta Gladiadora": você pode enviar 1 monstro "Besta Gladiadora" do seu Deck para o Cemitério. \r\nNo final da Fase de Batalha, se este card batalhar: você pode embaralhá-lo no Deck; Invoque por Invocação-Especial 1 monstro "Besta Gladiadora" do seu Deck, exceto "Besta Gladiadora Noxious".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67436768,'Springans Irmãos',replace(replace('Se este card for enviado da mão ou do Deck para o Cemitério: você pode escolher 1 monstro "Springans" no seu Cemitério, exceto "Springans Irmãos"; Invoque-o por Invocação-Especial em Posição de Defesa. \r\nSe este card estiver na sua mão, no campo ou no Cemitério: você pode escolher 1 Monstro Xyz "Springans" que você controla; associe este card a ele como matéria. \r\nVocê só pode usar cada efeito de "Springans Irmãos" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67441435,'Bulbo Brilhante',replace(replace('Se este card estiver no seu Cemitério: você pode enviar o card do topo do seu Deck para o Cemitério e, se isso acontecer, Invoque este card por Invocação-Especial. \r\nVocê só pode usar este efeito de "Bulbo Brilhante" uma vez por Duelo.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67441879,'Vento de Vespabatalha',replace(replace('Duas vezes por turno, se um ou mais monstros "Vespabatalha" forem Invocados por Invocação-Normal ou Especial no seu campo (exceto durante a Etapa de Dano): você pode escolher 1 deles; adicione 1 monstro "Vespabatalha" com menos ATK que o desse monstro do seu Deck à sua mão. \r\nUma vez por turno: você pode escolher 1 monstro Inseto que você controla com um Nível; neste turno, você pode considerá-lo como um Regulador se usado como Matéria Sincro. \r\nVocê só pode ativar 1 "Vento de Vespabatalha" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67443336,'Balança do Julgamento',replace(replace('Se seu oponente controlar mais cards que o número combinado de cards na sua mão e os que você controla: compre cards igual a esse excesso. \r\nVocê só pode ativar 1 "Balança do Julgamento" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67445676,'Pinhoto','Se este card for enviado para o Cemitério pelo efeito de "Boloto": Você pode Invocar por Invocação-Especial este card do seu Cemitério.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67457739,'Luta dos Despojos do Pecado',replace(replace('Escolha qualquer número de cards no campo (o número máx. de alvos em cada lado é o número de cards "Despojos do Pecado" desse duelista que estiverem banidos ou no Cemitério dele); destrua-os. \r\nSe este card Baixado for destruído ou banido por um efeito ativado do seu oponente: você pode embaralhar no Deck até 2 cards do campo. \r\nVocê só pode ativar 1 "Luta dos Despojos do Pecado" por turno.','\r',char(13)),'\n',char(10)),'Ativar o efeito','Escolha 1 card no Campo para retornar ao Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67464807,'Dora do Destino',replace(replace('Você pode activar este card apenas durante o turno do seu adversário. \r\nEscolha 1 monstro com a face para cima no Campo do seu adversário. \r\nDurante o seu próximo turno, quando você Invocar, por Invocação-Normal, um monstro com sucesso, com 1 Nível a menos que o monstro escolhido, inflija dano igual ao Nível do monstro escolhido x 500 pontos aos Life Points do seu adversário.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67466547,'Helmer, o Timoneiro de Peluguel',replace(replace('Durante sua Fase Principal: você pode Invocar por Invocação-Especial 1 monstro "de Peluguel" da sua mão, exceto "Helmer, o Timoneiro de Peluguel". \r\nSe um monstro "de Peluguel" for Invocado por Invocação-Especial no seu campo enquanto você controlar este monstro (exceto durante a Etapa de Dano): você pode descartar 1 card "de Peluguel"; compre 1 card. \r\nVocê só pode usar cada efeito de "Helmer, o Timoneiro de Peluguel" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67468948,'Layard, o Liberador','Sempre que um Card de Armadilha de Resposta for ativado, imediatamente depois que ele resolver, adicione 2 dos seus monstros Fada banidos à sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67483216,'Examinador Genex','Quando este card for destruído em batalha e enviado para o Cemitério: você pode Invocar por Invocação-Especial 1 monstro "Genex" com 1500 ou menos de ATK do seu Deck em Posição de Ataque.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67489919,'Besta Fantasma Mecha Opala Azul',replace(replace('Não pode ser usado como um Monstro-Matéria Sincro, exceto para a Invocação-Sincro de um monstro Máquina. \r\nO(s) outro(s) \r\nMonstro(s)-Matéria Sincro são monstros "Besta Fantasma Mecha" na sua mão ou no seu campo. \r\nEnquanto você controlar uma Ficha, este card não pode ser destruído em batalha ou por efeitos de card. \r\nSe somente seu oponente controlar um monstro: você pode banir este card do seu Cemitério; Invoque por Invocação-Especial 1 "Ficha de Besta Fantasma Mecha" (Máquina/VENTO/Nível 3/ATK 0/DEF 0).','\r',char(13)),'\n',char(10)),'Invocar uma Ficha por Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67489920,'Ficha de Besta Fantasma Mecha','Invocado por Especial com o efeito de um monstro "Besta Fantasma Mecha" ou um card relacionado.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67494157,'Dragão Rastejante','Este dragão enfraquecido já não pode voar, mas ainda é uma força letal a ser reconhecida.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67503139,'Princesa da Premonição Cristaldina','VIRE: Você pode adicionar 1 Monstro de Ritual do seu Deck ou Cemitério à sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67508932,'Vorportal, o Senhor do Tempo Progenitor',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nNão pode ser destruído em batalha ou por efeitos de card. \r\nVocê não sofre dano de batalha dos ataques envolvendo este card. \r\nNo final da Etapa de Dano, se este card que foi Invocado por Invocação-Especial do Deck Adicional batalhou: você pode ativar este efeito; bana todos os monstros que seu oponente controla e, além disso, pelo resto deste turno, diminua pela metade o dano de batalha que seu oponente sofrer. \r\nUma vez por turno, durante a Fase Final, se este efeito foi ativado neste turno: Invoque por Invocação-Especial tantos monstros quanto possível que você baniu com o efeito deste card, no campo do seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67511500,'Senhora de D.',replace(replace('Seu oponente não pode escolher monstros do Tipo Dragão com a face para cima que você controla para ataques. \r\nSe este card no campo seria destruído em batalha ou por um efeito de card, em vez disso, você pode enviar 1 monstro do Tipo Dragão da sua mão ao Cemitério.','\r',char(13)),'\n',char(10)),'Usar o efeito de "Senhora de D." em vez de ser destruído?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67515699,'"Jacks" K9-66X',replace(replace('2 monstros de Nível 5	\r\nSe este card for Invocado por Invocação-Xyz, ou se seu oponente ativar um efeito de monstro na mão ou no Cemitério: você pode desassociar 1 matéria deste card e, depois, escolha 1 monstro no campo; destrua-o. \r\nVocê só pode usar este efeito de ""Jacks" K9-66X" uma vez por turno. \r\nUm Monstro Xyz "K9" que tenha este card como matéria ganha este efeito.\r\n● Durante qualquer turno no qual seu oponente tenha ativado um efeito de monstro na mão ou no Cemitério, qualquer dano de batalha que este card causar ao seu oponente é dobrado.','\r',char(13)),'\n',char(10)),'Efeito de destruição','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67517351,'Hiper Magia de Aumento de Classe Utopiforça',replace(replace('Escolha 1 Monstro Xyz "Utopia" de Classe 9 ou menos que você controla; Invoque por Invocação-Especial 1 Monstro Xyz "Utopia" ou "Utópico" de Classe 10 ou mais do seu Deck Adicional, usando esse Monstro Xyz que você controla como matéria. \r\n(Isso é considerado uma Invocação-Xyz. Transfira as matérias dele para o monstro Invocado.) \r\nSe um ou mais Monstros Xyz forem Invocados por Invocação-Especial pelo efeito de um Monstro Xyz "Utopia" ou "Utópico" de Classe 10 ou mais, enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode escolher 1 desses monstros Invocados por Invocação-Especial; associe este card a ele como matéria. \r\nVocê só pode usar cada efeito de "Hiper Magia de Aumento de Classe Utopiforça" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67523044,'Marco Xeno',replace(replace('Adicione 1 Regulador Dinossauro ou Monstro Normal Dinossauro do seu Deck à sua mão e, depois, destrua 1 card na sua mão. \r\nVocê pode banir este card do seu Cemitério; Invoque por Invocação-Fusão 1 Monstro de Fusão Dinossauro do seu Deck Adicional, usando monstros da sua mão ou do campo. \r\nVocê só pode usar cada efeito de "Marco Xeno" uma vez por turno.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Invocação Fusão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67526112,'Gatilho Rápido',replace(replace('Invoque por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional, ao destruir as Matérias de Fusão listadas nele do seu campo, mas ele só pode atacar monstros Invocados por Invocação-Especial do Deck Adicional e, além disso, ele não é afetado pelos efeitos ativados de outros monstros Invocados por Invocação-Especial do Deck Adicional. \r\nVocê só pode ativar 1 "Gatilho Rápido" por turno.','\r',char(13)),'\n',char(10)),'','O efeito de "Gatilho Rápido" está sendo aplicado.','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67532912,'Soldado Científico','Soldados equipados com o armamento mais moderno para enfrentar monstros desconhecidos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67547370,'Zushin, o Gigante Adormecido',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao oferecer como Tributo um monstro que você controla com 10 Marcadores Zushin. \r\nUma vez por turno: você pode revelar este card da sua mão e, depois, escolha 1 Monstro Normal de Nível 1 que você controla (mantenha este card revelado até o final deste turno); coloque 1 Marcador Zushin sobre ele. \r\nNão é afetado por outros efeitos de cards. \r\nSe este card batalhar um monstro, durante o cálculo de dano: o ATK/DEF deste card se tornam iguais ao ATK atual do monstro que ele estiver batalhando +1000, apenas durante esse cálculo de dano.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67556500,'Dragão de Pulso Fônon',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nQuando este card for Invocado por Invocação-Sincro: você pode declarar um Nível de 1 a 3; este card se torna desse Nível e, além disso, você não pode Invocar por Invocação-Especial pelo resto deste turno, exceto por Invocações-Sincro usando este card como matéria. \r\nVocê só pode Invocar um ou mais "Dragão de Pulso Fônon" por Invocação-Especial uma vez por turno.','\r',char(13)),'\n',char(10)),'Alterar Nível','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67557908,'Número 4: Furtivo Kragen',replace(replace('2 monstros de ÁGUA de Nível 4	\r\nTodos os monstros com a face para cima no campo se tornam de ÁGUA. \r\nUma vez por turno, durante a Fase Principal (Efeito Rápido): você pode destruir 1 monstro de ÁGUA que seu oponente controla e, se isso acontecer, cause dano ao seu oponente igual à metade do ATK que ele tinha no campo. \r\nSe este card Invocado por Invocação-Xyz for destruído: você pode Invocar por Invocação-Especial um ou mais "Cria de Furtivo Kragen" do seu Deck Adicional, até o número de matérias que este card tinha e, depois, você pode associar até 1 monstro de ÁGUA do seu Cemitério a cada um desses monstros Invocados por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Destrua 1 monstro de ÁGUA','','Associar Matéria Xyz a este monstro?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67559101,'Cronomalia Golem de Lama','Se um monstro "Cronomalia" que você controla atacar um monstro em Posição de Defesa, ele causa dano de batalha perfurante ao seu oponente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67584223,'Tessera, o Escudeiro Primitivo',replace(replace('Você pode revelar 1 Magia/Armadilha "Monarca" na sua mão; Invoque este card por Invocação-Especial da sua mão. \r\nDurante sua Fase Principal, você pode: imediatamente depois que este efeito resolver, Invocar 1 monstro por Invocação-Tributo. \r\nSe este card for enviado para o Cemitério: você pode Invocar por Invocação-Especial 1 monstro com 800 de ATK/1000 de DEF do seu Deck e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno. \r\nVocê só pode usar cada efeito de "Tessera, o Escudeiro Primitivo" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Invocação Tributo','Invocar por Invocação Especial do Deck','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67586735,'Gouki Parceiro de Tag',replace(replace('Se este card for enviado para o Cemitério como Matéria Link para a Invocação-Link de um monstro "Gouki": você pode fazer com que esse Monstro Link "Gouki" ganhe 1000 de ATK até o final deste turno. \r\nDurante sua Fase Principal, exceto no turno em que este card foi enviado para o Cemitério: você pode banir este card do seu Cemitério e, depois, escolher 1 Magia "Gouki" no seu Cemitério; embaralhe-a no Deck.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67598234,'Sabre Gaia, a Sombra Relâmpago','2+ monstros','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67616300,'Jogo da Galinha',replace(replace('O duelista com menos PV não sofre dano. \r\nUma vez por turno, durante a Fase Principal: o duelista do turno pode pagar 1000 PV e, depois, ative 1 desses efeitos;\r\n● Compre 1 card.\r\n● Destrua este card.\r\n● Seu oponente ganha 1000 PV.	\r\nNenhum duelista pode ativar cards ou efeitos em resposta à ativação deste efeito.','\r',char(13)),'\n',char(10)),'Compre 1 card(s)','Destruir este card','Seu oponente ganha 1000 PV','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67629977,'Hoshiningen','Enquanto este card permanecer no Campo com a face para a cima, aumente o ATK de todos os monstros da LUZ em 500 pontos e diminua o ATK de todos os monstros das TREVAS em 400 pontos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67630339,'Zombaria Confusa',replace(replace('Ative apenas quando seu oponente declarar um segundo ataque direto durante a mesma Fase de Batalha. \r\nConduza a batalha entre o monstro atacante e o primeiro monstro que atacou diretamente (outros efeitos não podem ser ativados durante esta batalha.)','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67630394,'Lanceiro Cavaleiro Negro de Armadura Completa',replace(replace('3 monstros de Nível 7	\r\nUma vez por turno, você também pode Invocar por Invocação-Xyz "Lanceiro Cavaleiro Negro de Armadura Completa" ao usar 1 Monstro Xyz de Classe 5 ou 6 que você controla. \r\n(Transfira as matérias dele para este card.) \r\nGanha 300 de ATK para cada matéria e Card de Equipamento que tiver. \r\nUma vez por turno: você pode escolher 1 card "Xyz" no seu Cemitério; adicione-o à sua mão. \r\nUma vez por turno, se um Card de Equipamento se tornar equipado a um monstro que você controla (exceto durante a Etapa de Dano): você pode associar 1 monstro que seu oponente controla a este card como matéria.','\r',char(13)),'\n',char(10)),'Invocação Xyz usando como Matéria um Monstro Xyz de Classe 5 ou 6 que você controla','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67646312,'Homem-Holofote','VIRE: Seu oponente não pode Baixar (ou virar com a face para baixo) quaisquer cards pelo resto deste turno.','Restrição de Baixar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67647362,'Barba Negra, o Capitão Saquepatrollha',replace(replace('2 monstros, incluindo um monstro "Saquepatrollha"	\r\n(Efeito Rápido): você pode escolher 1 Monstro de Efeito que você controla; Invoque por Invocação-Especial 1 monstro "Saquepatrollha" do seu Deck Adicional com o mesmo Atributo que o de um monstro que seu oponente controla ou no Cemitério dele e, se isso acontecer, equipe o alvo a ele e, depois, compre 1 card. \r\nVocê só pode usar este efeito de "Barba Negra, o Capitão Saquepatrollha" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67660909,'Sacerdotisa da Cidade Cinzenta',replace(replace('Se "Obsidim, a Cidade Cinzenta" estiver na Zona do Campo, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Sacerdotisa da Cidade Cinzenta" por Invocação-Especial uma vez por turno desta forma. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 card "Cinzento(a)" do seu Deck à sua mão, exceto "Sacerdotisa da Cidade Cinzenta". \r\nVocê só pode usar este efeito de "Sacerdotisa da Cidade Cinzenta" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67675300,'Dragão de Pó de Neve',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) ao remover 4 Marcadores de Gelo de qualquer lugar no campo. \r\nOutros monstros com Marcadores de Gelo não podem atacar ou mudar suas posições de batalha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67680512,'Alma Desacorrentada da Raiva',replace(replace('2 monstros, incluindo um monstro "Alma Desacorrentada"	\r\nDurante a Fase Principal do seu oponente (Efeito Rápido): você pode escolher 1 monstro Invocado por Invocação-Especial com a face para cima que seu oponente controla; imediatamente depois que este efeito resolver, Invoque por Invocação-Link 1 Monstro Link de TREVAS, exceto "Alma Desacorrentada da Raiva", usando apenas esse monstro do oponente e este card que você controla como matéria. \r\nSe este card no campo for destruído em batalha ou por um efeito de card: você pode escolher 1 monstro Demônio no seu Cemitério, exceto "Alma Desacorrentada da Raiva"; adicione-o à sua mão. \r\nVocê só pode usar cada efeito de "Alma Desacorrentada da Raiva" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67688478,'Diabretes Gêmeos',replace(replace('Durante o turno de qualquer duelista, quando seu oponente ativar um Card de Magia, Armadilha ou um efeito de monstro que faria você descartar ao resolver: Você pode enviar este card da sua mão ao Cemitério; negue a ativação e, se isso acontecer, destrua-o. \r\nDepois, compre 1 card.','\r',char(13)),'\n',char(10)),'Negar o efeito e comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67692580,'Corvo da Garra Negra',replace(replace('Se você controlar um monstro de TREVAS, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Corvo da Garra Negra" por Invocação-Especial uma vez por turno desta forma.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67694706,'Sol Magicoloidal',replace(replace('Se um ou mais monstros forem Invocados por Invocação-Especial por um efeito de Armadilha seu (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão ou do Cemitério, mas se você o Invocar do Cemitério, bana-o quando ele deixar o campo. \r\nDurante a Fase de Batalha do seu oponente (Efeito Rápido): você pode ativar 1 desses efeitos;\r\n● Imediatamente depois que este efeito resolver, Invoque por Invocação-Sincro usando este card que você controla.\r\n● Imediatamente depois que este efeito resolver, Invoque por Invocação-Xyz usando este card que você controla.	\r\nVocê só pode usar cada efeito de "Sol Magicoloidal" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Invocação Especial','Invocação Sincro','Invocação Xyz','','','','','','','','','','','','');
INSERT INTO texts VALUES(67696066,'Camaramágico Palhaço Ardiloso',replace(replace('Se este card for enviado para o Cemitério: você pode escolher 1 monstro "Camaramágico" no seu Cemitério; Invoque-o por Invocação-Especial, mas seu ATK/DEF se tornam 0 e, depois, você sofre 1000 de dano. \r\nVocê só pode usar este efeito de "Camaramágico Palhaço Ardiloso" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67712104,'Marincesa Coração de Cristal',replace(replace('2 monstros de ÁGUA	\r\nNão é afetado pelos efeitos de monstro do seu oponente enquanto este card estiver na Zona de Monstros Adicional. \r\nDurante a Etapa de Dano, se este card batalhar um monstro do oponente, esse monstro do oponente não é afetado por efeitos de card, exceto seus próprios. \r\nQuando este card, ou um Monstro Link "Marincesa" seu para o qual este card apontar, for escolhido como alvo de um ataque: você pode enviar 1 monstro "Marincesa" da sua mão para o Cemitério; nessa batalha, seu monstro não pode ser destruído em batalha e, além disso, você não sofre dano de batalha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67723438,'Teleporte de Emergência','Invoque por Invocação-Especial 1 monstro Psíquico de Nível 3 ou menos da sua mão ou do Deck, mas bana-o durante a Fase Final deste turno.','Banir os monstros Invocados por Invocação Especial pelo efeito de "Teleporte de Emergência"','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67724379,'Dragão Koumori','Um dragão malígno que cospe fogo. As suas chamas maléficas corrompem as almas de suas vítimas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67724434,'Coringa Duplo',replace(replace('Escolha 1 monstro de Nível 5 ou menos que você controla; adicione 1 monstro de Nível 10 do seu Deck à sua mão com o mesmo Tipo original e, depois, você pode descartar 1 card e, se isso acontecer, Invoque por Invocação-Especial 1 monstro da sua mão com esse mesmo Tipo, em Posição de Defesa. \r\nVocê não pode Invocar por Invocação-Especial pelo resto deste turno depois que este card resolver, exceto monstros com esse Tipo original. \r\nVocê só pode ativar 1 "Coringa Duplo" por turno.','\r',char(13)),'\n',char(10)),'Ativar','Invocação Especial?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67725394,'Besta de Rabiscos - Tirano',replace(replace('Você pode Invocar este card por Invocação-Tributo ao oferecer como Tributo 1 monstro Dinossauro. \r\nDurante a Fase Principal, se um monstro Dinossauro estiver no campo, você pode (Efeito Rápido): imediatamente depois que este efeito resolver, Invoque este card por Invocação-Tributo da sua mão. \r\nVocê só pode usar este efeito de "Besta de Rabiscos - Tirano" uma vez por turno. \r\nSe este card for Invocado por Invocação-Normal: você pode destruir 1 monstro no campo e, depois, se este card foi Invocado por Invocação-Tributo pelo Tributo de um ou mais monstros "Besta de Rabiscos", ele ganha ATK igual à metade do ATK do monstro destruído no campo.','\r',char(13)),'\n',char(10)),'Ofereça como Tributo 1 monstro Dinossauro para Invocar por Invocação Tributo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67744384,'Protetor Tindângulo',replace(replace('VIRE: Você pode mudar até 3 monstros com a face para baixo em Posição de Defesa que você controla, para com a face para cima em Posição de Defesa e, depois, se todos esses monstros forem monstros "Tindângulo", você pode adicionar até esse número de cards "Tindângulo" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Protetor Tindângulo" uma vez por turno.','\r',char(13)),'\n',char(10)),'Mudar para Posição de Defesa com a face para cima','Adicionar este card à mão?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67745632,'Transcendossauro Gigantozowler',replace(replace('1 monstro Dinossauro + 1 Monstro Normal	\r\nSe este card for Invocado por Invocação-Especial: você pode escolher 1 monstro Dinossauro no seu Cemitério; adicione-o à sua mão e, depois, se este card foi Invocado por Invocação-Especial do Cemitério, você pode destruir 2 cards (1 da sua mão ou do campo e 1 que seu oponente controla). \r\nSe este card for destruído: você pode embaralhar no Deck 1 Monstro Normal do seu Cemitério e, depois, você pode Invocar este card por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Transcendossauro Gigantozowler" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Destruir 1 card no Campo de cada jogador?','Invocar este card por Invocação Especial?','','','','','','','','','','','','');
INSERT INTO texts VALUES(67748760,'Dragão Absoroteador',replace(replace('Se você controlar um monstro "Foguette", você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Dragão Absoroteador" por Invocação-Especial uma vez por turno desta forma. \r\nSe este card for enviado para o Cemitério: você pode adicionar 1 monstro "Foguette" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Dragão Absoroteador" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67750322,'Amo Caveira','Quando um efeito de card for ativado no Cemitério do seu oponente (Efeito Rápido): você pode enviar este card da sua mão para o Cemitério; negue o efeito.','Negue os efeitos ativados no Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67752972,'Wattkyuki',replace(replace('1 Regulador "Watt" + 1+ monstros Trovão não-Reguladores	\r\nEste card pode atacar diretamente. \r\nQuando este card causar dano de batalha ao seu oponente em um ataque direto: você pode embaralhar no Deck tanto 1 Regulador "Watt" do seu Cemitério quanto 1 monstro Trovão não-Regulador com a face para cima que você controla e, se isso acontecer, Invoque por Invocação-Especial 1 Monstro Sincro "Watt" do seu Deck Adicional, exceto "Wattkyuki". \r\nVocê só pode usar este efeito de "Wattkyuki" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67754901,'Dragão Miragem de Olhos Anômalos',replace(replace('Escala de Pêndulo = 8\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno, se um ou mais Monstros Pêndulo "Olhos Anômalos" com a face para cima que você controla forem destruídos em batalha ou por um efeito de card: você pode destruir 1 card na sua Zona de Pêndulo e, se isso acontecer, coloque 1 Monstro Pêndulo "Olhos Anômalos" que estiver com a face para cima no seu Deck Adicional na sua Zona de Pêndulo, exceto "Dragão Miragem de Olhos Anômalos".\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nEnquanto um card "Olhos Anômalos" estiver na sua Zona de Pêndulo (Efeito Rápido): você pode escolher 1 monstro "Olhos Anômalos" que você controla; na primeira vez que ele seria destruído em batalha ou por um efeito de card neste turno, ele não é destruído. \r\nVocê só pode usar este efeito de "Dragão Miragem de Olhos Anômalos" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67757079,'Rei das Bestas',replace(replace('Você pode oferecer como Tributo 1 "Moja" com a face para cima que você controla para Invocar este card por Invocação-Especial da sua mão ou Cemitério. \r\nSó pode haver 1 "Rei das Bestas" com a face para cima no campo.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67768675,'Kaibaman, a Lenda',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode mostrar 3 "Dragão Branco de Olhos Azuis" na sua mão, no Deck, no campo com a face para cima e/ou no Cemitério e, depois, Invoque por Invocação-Especial 1 "Dragão Branco de Olhos Azuis" da sua mão, do Deck ou do Cemitério. \r\nSe você Invocar "Dragão Branco de Olhos Azuis" por Invocação-Especial enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode banir este card; adicione 1 monstro "Olhos Azuis" do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "Kaibaman, a Lenda" uma vez por turno.','\r',char(13)),'\n',char(10)),'Confirmar','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67775894,'Varinha das Maravilhas',replace(replace('Só pode ser equipado a um monstro Mago. \r\nEle ganha 500 de ATK. \r\nSe você controlar o monstro equipado e este card: você pode enviar os dois para o Cemitério; compre 2 cards.','\r',char(13)),'\n',char(10)),'Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67779172,'Ofensiva de Asas Negras',replace(replace('Envie 1 monstro "Asanegra" da sua mão ao Cemitério para selecionar 1 monstro em Posição de Defesa que seu oponente controla. \r\nEnvie esse monstro ao Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67797569,'Salamandra Lavalval',replace(replace('1 Regulador + 1+ monstros de FOGO não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro: você pode comprar 2 cards e, depois, se você tiver um monstro de FOGO na sua mão, envie 2 cards da sua mão para o Cemitério, incluindo um monstro de FOGO. \r\nCaso contrário, revele toda a sua mão e embaralhe-a no Deck. \r\nVocê só pode usar este efeito de "Salamandra Lavalval" uma vez por turno. \r\nUma vez por turno: você pode banir 1 monstro de FOGO do seu Cemitério; coloque, com a face para baixo em Posição de Defesa, monstros com a face para cima que seu oponente controla, até o número de monstros "Laval" que você controla.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67803035,'Reencarnação do Desacorrentado',replace(replace('Quando este card é ativado: você pode adicionar 1 Magia "Desacorrentado(a)" (exceto "Reencarnação do Desacorrentado") ou 1 "Prisão da Abominação" do seu Deck à sua mão.\r\nUma vez por turno: você pode escolher até 3 cards "Desacorrentado(a)" no seu Cemitério, exceto "Reencarnação do Desacorrentado"; embaralhe-os no Deck, então você pode destruir outros cards que você controla até o número embaralhado.\r\nVocê só pode ativar 1 "Reencarnação do Desacorrentado" por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão?','Efeito de recuperação','Destruir o card?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67808837,'Camarartista Rei Urso',replace(replace('Escala de Pêndulo = 7\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno, durante a Fase Final, se este card foi ativado neste turno: você pode destruir este card e, se isso acontecer, adicione 1 monstro de Nível 7 ou mais à sua mão, que esteja ou no seu Cemitério ou com a face para cima no seu Deck Adicional.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nNão pode ser destruído por efeitos de Magia/Armadilha enquanto estiver com a face para cima em Posição de Ataque. \r\nEste card ganha 100 de ATK para cada card "Camarartista" que você controla, apenas durante sua Fase de Batalha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67809530,'O Rei Carmesim',replace(replace('1 Regulador + 1+ monstros não-Reguladores de TREVAS	\r\nSe este card for Invocado por Invocação-Sincro: você pode adicionar 1 card que mencione "Dragão Vermelho Arquidemônio" do seu Deck à sua mão. \r\nQuando seu oponente ativar um efeito de monstro (Efeito Rápido): você pode banir este card que você controla; Invoque por Invocação-Especial 1 "Dragão Vermelho Arquidemônio" do seu Deck Adicional (isso é considerado uma Invocação-Sincro) e, se isso acontecer, seu ATK se torna o dobro e, além disso, ele não pode ser destruído pelos efeitos de card do seu oponente. \r\nVocê só pode usar cada efeito de "O Rei Carmesim" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Invocação Especial','Invocado por Invocação Especial pelo efeito de "O Rei Carmesim"','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67820935,'Morph Massivo','Escolha 1 monstro com a face para cima que seu oponente controla; o ATK e DEF dele se tornam o dobro do ATK e DEF atuais, mas ele não pode atacar diretamente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67829249,'Broca do Mecanismo Antigo',replace(replace('Se você controlar um monstro "Mecanismo Antigo": Descarte 1 card; Baixe 1 Card de Magia direto do seu Deck. \r\nNeste turno, este Card de Magia não pode ser ativado.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67831115,'Sombras do Legado Mundial',replace(replace('Todos os monstros "Krawler" no campo ganham 300 de ATK/DEF. \r\nUma vez por turno: você pode Invocar por Invocação-Especial 1 monstro Inseto de Nível 2 ou menos da sua mão com a face para cima ou com a face para baixo em Posição de Defesa. \r\nQuando um monstro de Virar seu for destruído em batalha com um monstro do oponente: você pode enviar esse monstro do oponente para o Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67835547,'Sono Rúniko',replace(replace('Ative 1 desses efeitos, mas pule sua próxima Fase de Batalha depois da ativação;\r\n● Escolha 1 monstro com a face para cima no campo; na próxima vez que esse monstro seria destruído em batalha ou por um efeito de card neste turno, ele não é destruído e, além disso, ele não pode atacar neste turno e, depois, (depois de aplicar este efeito) bana os 3 cards do topo do Deck do seu oponente.\r\n● Invoque por Invocação-Especial 1 monstro "Rúnika(o)" do seu Deck Adicional na Zona de Monstros Adicional.	\r\nVocê só pode ativar 1 "Sono Rúniko" por turno.','\r',char(13)),'\n',char(10)),'Proteção contra destruição','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67841515,'Lírio Revólver','Esta flor perversa ataca os inimigos com balas de pólen.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67853262,'Maga da Fidelidade',replace(replace('VIRE: Você pode escolher 1 Magia no seu Cemitério; adicione-a à sua mão e, depois, você pode Invocar por Invocação-Especial 1 "Maga da Fé" ou "Maga da Fidelidade" do seu Deck com a face para baixo em Posição de Defesa. \r\nVocê só pode usar este efeito de "Maga da Fidelidade" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Invocar por Invocação Especial do Deck?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67865534,'Mago da Esperança',replace(replace('Escala de Pêndulo = 8\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno, quando um monstro declarar um ataque: você pode negar o ataque e, depois, destrua este card.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\n2 monstros de Nível 4	\r\nSe você puder Invocar por Invocação-Pêndulo de Nível 4, você pode Invocar este card com a face para cima no seu Deck Adicional por Invocação-Pêndulo. \r\nVocê pode desassociar 1 matéria deste card; Invoque por Invocação-Especial 1 Monstro Pêndulo de Nível 7 ou menos da sua mão em Posição de Defesa, mas negue seus efeitos e, depois, você pode colocar este card com a face para cima na sua Zona de Pêndulo. \r\nVocê só pode usar este efeito de "Mago da Esperança" uma vez por turno. \r\nSe este card for Invocado por Invocação-Pêndulo: você pode escolher 1 Monstro Pêndulo no seu Cemitério; associe-o a este card como matéria.','\r',char(13)),'\n',char(10)),'','','','Colocar este card na sua Zona de Pêndulo?','','','','','','','','','','','','');
INSERT INTO texts VALUES(67886895,'Dragão Branco de Olhos Azuis Profundos, o Abismo Azul',replace(replace('Este card é sempre considerado como um card "Olhos Azuis".\r\nVocê pode descartar este card; adicione 1 Regulador de LUZ de Nível 1 do seu Deck à sua mão.\r\nSe um ou mais Monstros Ritual "Olhos Azuis" e/ou "Dragão Branco de Olhos Azuis" for enviado para o seu Cemitério: você pode escolher 1 deles; Invoque por Invocação-Especial este card do seu Cemitério (se ele estava lá quando o monstro foi enviado) ou mão (mesmo que não), e se fizer, seu ATK se torna o daquele monstro, mas bana-o quando deixar o campo.\r\nVocê só pode usar cada um dos efeitos de "Dragão Branco de Olhos Azuis Profundos, o Abismo Azul" uma vez por turno.','\r',char(13)),'\n',char(10)),'Efeito de busca','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67886896,'Dragão Branco de Olhos Azuis Profundos, o Abismo Azul',replace(replace('Este card é sempre considerado como um card "Olhos Azuis".\r\nVocê pode descartar este card; adicione 1 Regulador de LUZ de Nível 1 do seu Deck à sua mão.\r\nSe um ou mais Monstros Ritual "Olhos Azuis" e/ou "Dragão Branco de Olhos Azuis" for enviado para o seu Cemitério: você pode escolher 1 deles; Invoque por Invocação-Especial este card do seu Cemitério (se ele estava lá quando o monstro foi enviado) ou mão (mesmo que não), e se fizer, seu ATK se torna o daquele monstro, mas bana-o quando deixar o campo.\r\nVocê só pode usar cada um dos efeitos de "Dragão Branco de Olhos Azuis Profundos, o Abismo Azul" uma vez por turno.','\r',char(13)),'\n',char(10)),'Efeito de busca','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67901914,'Mágico Mosquete - Mãos Firmes',replace(replace('Escolha 1 monstro "Mágico(a) Mosquete" que você controla; até o final deste turno, o ATK/DEF dele se tornam o dobro do seu ATK/DEF originais. \r\nEle não pode atacar diretamente no turno em que você ativar este card. \r\nVocê só pode ativar 1 "Mágico Mosquete - Mãos Firmes" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67904682,'Porta-Aviões das Trevas',replace(replace('1 Regulador de TREVAS + 1 ou mais monstros do Tipo Máquina não-Reguladores	\r\nUma vez por turno: você pode escolher 1 monstro "Reator" ou "Fortaleza Voadora FOGO DO CÉU" no seu Cemitério; Invoque por Invocação-Especial esse alvo, ignorando suas condições de Invocação. \r\nSe este card for destruído e enviado para o Cemitério: você pode Invocar por Invocação-Especial 1 monstro do Tipo Máquina de Nível 5 ou menos da sua mão.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67906797,'A Grande Inversão Noodle','Adicione o card do fundo do seu Deck à sua mão e, depois, pegue 1 card do seu Deck, embaralhe e coloque esse card no fundo do Deck.','','Escolha 1 card para colocá-lo no fundo do Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67922702,'Besta Fantasma Mecha Lobo-corrente',replace(replace('Se este card for Invocado por Invocação-Normal: Invoque por Invocação-Especial 1 "Ficha de Besta Fantasma Mecha" (Máquina/VENTO/Nível 3/ATK 0/DEF 0). \r\nO Nível deste card aumenta em um valor igual à soma dos Níveis de todas as "Fichas de Besta Fantasma Mecha" que você controla. \r\nEnquanto você controlar uma Ficha, este card não pode ser destruído em batalha ou por efeitos de card. \r\nUma vez por batalha, durante a Etapa de Dano, quando este card batalhar um monstro do oponente (Efeito Rápido): você pode oferecer 1 Ficha como Tributo; este card ganha 800 de ATK até o final deste turno.','\r',char(13)),'\n',char(10)),'Invocar uma Ficha por Invocação Especial','Aumentar ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67922703,'Ficha de Besta Fantasma Mecha','Invocado por Especial com o efeito de um monstro "Besta Fantasma Mecha" ou um card relacionado.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67926903,'CXyz Esperança Barian',replace(replace('3 ou mais monstros de Nível 7	\r\nVocê também pode Invocar este card por Invocação-Xyz ao usar 1 monstro que você controla com "Número C101" até "Número C107" no seu nome como uma Matéria Xyz. \r\n(Matérias Xyz associadas a esse monstro também se tornam Matéria Xyz neste card.) \r\nEste card ganha 1000 de ATK para cada Matéria Xyz associada a ele. \r\nVocê pode escolher 1 monstro "Número" no seu Cemitério; até a próxima Fase Final do seu oponente, o nome deste card se torna o nome desse monstro e substitua este efeito pelo efeito original desse monstro. \r\nVocê só pode usar este efeito de "CXyz Esperança Barian" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Xyz sobrepondo um monstro que você controla?','Efeito de copiar','Terminar o efeito copiado','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67934141,'Rapaz de Baseball Derradeiro',replace(replace('Este card ganha 1000 de ATK para cada monstro de FOGO com a face para cima no campo, exceto por este card. \r\nVocê pode enviar 1 outro monstro de FOGO com a face para cima que você controla para o Cemitério; cause 500 de dano ao seu oponente.','\r',char(13)),'\n',char(10)),'Cause 1000 de dano ao seu oponente','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67949763,'Chaves Corrompidas',replace(replace('Escolha 1 Monstro Xyz com a face para cima que você controla; Invoque por Invocação-Especial 3 "Fichas de Terror Umbral Miragem" (Tipo Demônio/TREVAS/Nível 1/ATK ?/DEF 0.) (Quando Invocadas, o ATK de cada Ficha se torna igual ao ATK atual desse Monstro Xyz. Elas não podem atacar diretamente seu oponente nem podem ser oferecidas como Tributo, exceto para uma Invocação-Tributo.) \r\nQuando esse Monstro Xyz com a face para cima deixar o campo, destrua essas Fichas.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67949764,'Ficha de Terror Umbral Miragem','Invocado por Especial com o efeito "Chaves Corrompidas". Quando Invocada, o ATK desta Ficha fica igual ao ATK atual do Monstro Xyz alvejado por "Chaves Corrompidas". Esta Ficha não pode atacar diretamente o oponente nem ser oferecida como Tributo, exceto para uma Invocação-Tributo. Quando aquele Monstro Xyz de face para cima sair do campo, destrua esta Ficha.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67951831,'Coração do Herói','Escolha 1 monstro "HERÓI do Elemento" com a face para cima que você controla; reduza à metade o ATK dele até o fim deste turno, mas ele pode atacar duas vezes durante a Fase de Batalha deste turno.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67955331,'Empréstimo Afortunado',replace(replace('Escolha 1 monstro "Fada Fortuna" que você controla; Invoque por Invocação-Especial 1 monstro Mago da sua mão ou do Deck, cujo Nível original seja 1 a menos que o desse monstro e, além disso, durante seu próximo turno depois que este card resolver, você não pode Invocar monstros por Invocação-Normal ou Especial, exceto monstros Mago. \r\nVocê só pode ativar 1 "Empréstimo Afortunado" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67957315,'Espírito Ryu','Durante sua Etapa de Batalha, se este card batalhar (Efeito Rápido): você pode descartar 1 monstro Dragão para o Cemitério; este card ganha 1000 de ATK/DEF até o final da Fase de Batalha.','Aumentar ATK/DEF','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67959180,'Deusa dos Caprichos',replace(replace('Uma vez por turno: Você pode lançar uma moeda e escolher Cara ou Coroa. \r\nSe você acertar o resultado, dobre o ATK deste card neste turno. \r\nSe você errar, reduza à metade o ATK dele neste turno.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67964209,'Dragão Divino Aquabizarro','Uma vez por turno, você pode oferecer como Tributo 1 outro monstro de ÁGUA com a face para cima e selecionar 1 Card de Magia Contínua ou Magia de Campo no seu Cemitério para devolvê-lo ao topo do seu Deck.','Retornar ao Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67968069,'Marionete Sucata',replace(replace('Escolha 1 monstro "Engenhoca Marionete" no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê só pode ativar 1 "Marionete Sucata" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67972302,'Sakitama',replace(replace('Não pode ser Invocado por Invocação-Especial. \r\nUma vez por turno, durante a Fase Final, se este card foi Invocado por Invocação-Normal ou virado com a face para cima neste turno: devolva este card para a mão. \r\nVocê só pode usar cada um dos seguintes efeitos de "Sakitama" uma vez por turno. \r\nVocê pode revelar este card na sua mão; imediatamente depois que este efeito resolver, Invoque por Invocação-Normal 1 monstro Espírito da sua mão. \r\nSe este card for oferecido como Tributo: escolha 1 monstro Espírito no seu Cemitério; adicione-o à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67985943,'Cavaleiro-Gema Citrina',replace(replace('1 monstro "Cavaleiro-Gema" + 1 monstro Piro	\r\nPrimeiro deve ser Invocado por Invocação-Fusão. \r\nSe este card batalhar, seu oponente não pode ativar cards ou efeitos até o final da Etapa de Dano.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67987302,'Terrestre Que Caminha nas Linhas','Monstros "Imortal Terrestre" não podem ser destruídos por seus próprios efeitos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(67987611,'Arqueiros Amazoness','Quando um monstro do oponente declarar um ataque, enquanto você controlar um monstro "Amazoness": coloque com a face para cima em Posição de Ataque todos os monstros que seu oponente controla atualmente (efeitos de Virar não são ativados), eles perdem 500 de ATK e, além disso, eles devem atacar neste turno, se possível.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68001309,'Confronto na Caverna Subterror',replace(replace('Todos os monstros "Subterror" que você controla ganham 500 de ATK e DEF para cada monstro Baixado no campo. \r\nUma vez por turno, quando um monstro "Subterror" que você controla causar dano de batalha ao seu oponente: você pode escolher 1 card "Subterror" no seu Cemitério, exceto "Confronto na Caverna Subterror"; adicione-o à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68005187,'Troca de Almas',replace(replace('Escolha 1 monstro que seu oponente controla; neste turno, se você oferecer um monstro como Tributo, você deve oferecer o alvo como Tributo, como se você o controlasse. \r\nVocê não pode conduzir sua Fase de Batalha no turno em que ativar este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68007326,'Joan, o Anjo da Guarda',replace(replace('(Este card deve ser sempre considerado como um card "Guardião".)	\r\nQuando este card destruir um monstro em batalha e enviá-lo para o Cemitério: ganhe PV igual ao ATK original do monstro destruído no Cemitério.','\r',char(13)),'\n',char(10)),'Ganhar PV','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68018709,'Donzela Condenada',replace(replace('Durante o turno do seu oponente, você pode ativar 1 Card de Magia Rápida da sua mão. \r\nVocê só pode usar este efeito de "Donzela Condenada" uma vez por Duelo.','\r',char(13)),'\n',char(10)),'Ativar aplicando o efeito de "Donzela Condenada".','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68024506,'Mágica Mosqueteira Calamity',replace(replace('Durante o turno de qualquer duelista, você pode ativar Cards de Magia/Armadilha "Mágico(a) Mosquete" da sua mão. \r\nSe um Card de Magia/Armadilha for ativado na coluna deste card: você pode escolher 1 monstro "Mágico(a) Mosquete" no seu Cemitério; Invoque-o por Invocação-Especial em Posição de Defesa. \r\nVocê só pode usar este efeito de "Mágica Mosqueteira Calamity" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invoque por Invocação Especial do Cemitério','Ativar aplicando o efeito de "Mágica Mosqueteira Calamity".','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68038375,'Arte Ninjitsu das Folhas Dançantes',replace(replace('Ative este card ao escolher 1 monstro "Ninja" ou 1 monstro com a face para baixo em Posição de Defesa no campo; ofereça-o como Tributo e, se isso acontecer, Invoque por Invocação-Especial 1 monstro "Ninja" do seu Deck. \r\nQuando este card deixar o campo, envie esse monstro para o Cemitério. \r\nVocê pode escolher 1 Magia/Armadilha Contínua "Ninjitsu" na sua Zona de Magias & Armadilhas; devolva-a para a mão. \r\nVocê só pode usar 1 efeito de "Arte Ninjitsu das Folhas Dançantes" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68045685,'Bujincandescente',replace(replace('Monstros Besta-Guerreira "Bujin" que você controla não podem ser destruídos pelos efeitos de card do seu oponente, exceto durante a Fase de Batalha. \r\nUma vez por turno: você pode enviar para o Cemitério 1 monstro "Bujin" da sua mão ou do campo com a face para cima e, depois, escolha 1 card com a face para cima que seu oponente controla; negue seus efeitos até o final deste turno. \r\nDurante sua Fase Final: você pode enviar este card com a face para cima do campo para o Cemitério e, depois, escolha 1 monstro "Bujin" no seu Cemitério; Invoque-o por Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68049471,'O Fantasma Vulgar de Sonhos Fugazes','Este monstro se alimenta dos sonhos dos adormecidos incautos, levando a vítima a um sono eterno.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68054593,'Fervor Ardente',replace(replace('Escolha 1 monstro com a face para cima que você controla; equipe este card ao alvo. \r\nSe seu oponente controlar um monstro com ATK maior que o ATK original desse mesmo monstro, o ATK do monstro equipado se torna o dobro do ATK original do monstro equipado, apenas durante a Etapa de Dano.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68057622,'Murro da Destruição Contínuo',replace(replace('Quando o ATK de um monstro atacante no Campo do seu adversário é inferior ao DEF do monstro atacado no seu Campo em Posição de Defesa, destrúa o monstro atacante. \r\nO cálculo de dano é aplicado normalmente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68059897,'Maliss ＜Q＞ Resgate Rubro',replace(replace('2+ monstros, incluindo um monstro "Maliss"	\r\nEnquanto este card apontar para um monstro, o ATK e DEF originais de todos os Monstros de Efeito que seu oponente controla são invertidos. \r\nVocê só pode usar cada um dos seguintes efeitos de "Maliss ＜Q＞ Resgate Rubro" uma vez por turno. \r\nSe este card for Invocado por Invocação-Especial: você pode adicionar 1 Magia "Maliss" do seu Deck à sua mão. \r\nSe este card for banido: você pode pagar 900 PV; Invoque-o por Invocação-Especial e, depois, você pode banir 1 monstro Ciberso do seu Deck.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','Invocação Especial','Banir o monstro?','','','','','','','','','','','','');
INSERT INTO texts VALUES(68073522,'Absorção de Alma','Se um ou mais cards forem banidos: ganhe 500 PV para cada um.','Recuperar PV','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68075840,'Irmãs Cavaleiras Power Pro',replace(replace('O estádio está aberto e nossas estrelas estão prontas para te levar para o jogo! É o começo de uma nova lenda do beisebol!	\r\n\r\nApresentando: As três monitoras do mundo Power Pro! Essa é a Paa-chan à esquerda, brilhante, energética e (normalmente) confiável. À direita temos Waa-chan, tranquila, sincera e senseta (normalmente...). E Namiki está liderando com seu pequeno Chikuwa na bolsa, ajudando a animar a todos!','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68077936,'Explosão Induzida',replace(replace('Quando um ou mais cards que você controla forem destruídos por um efeito de Magia (exceto durante a Etapa de Dano): escolha 1 card que seu oponente controla; destrua-o. \r\nDurante o turno de qualquer duelista, exceto no turno em que este card foi enviado para o Cemitério, quando um ou mais cards que você controla forem destruídos por um efeito de Magia (exceto durante a Etapa de Dano): você pode banir este card do seu Cemitério e, depois, escolher 1 card que seu oponente controla; destrua-o.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68078978,'Fada Fortuna Chee',replace(replace('Quando você comprar este card: você pode revelá-lo; Invoque-o por Invocação-Especial da sua mão. \r\nSe este card for Invocado por Invocação-Especial da mão: você pode fazer com que cada duelista compre 1 card. \r\nVocê só pode usar cada efeito de "Fada Fortuna Chee" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68084557,'Dragão Mecha Ferramenteiro',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nDurante o seu turno, quando uma ou mais Magias de Equipamento se tornarem equipadas a este card: você pode comprar 1 card. \r\nVocê só pode usar este efeito de "Dragão Mecha Ferramenteiro" uma vez por turno. \r\nUma vez por turno (Efeito Rápido): você pode escolher 1 Card de Equipamento apropriado com a face para cima no campo; equipe o alvo a este card.','\r',char(13)),'\n',char(10)),'Comprar','Transfira o Card de Equipamento','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68087897,'Mariposa Pavorosa','Cada duelista só pode Invocar um ou mais monstros por Invocação-Especial uma vez por turno.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68120130,'Defensor Sucata',replace(replace('Quando um monstro do oponente declarar um ataque direto: você pode Invocar este card por Invocação-Especial da sua mão. \r\nUma vez por turno, durante o turno de qualquer duelista: você pode fazer com que este card ganhe 300 de DEF até o final deste turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Aumentar DEF','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68124775,'Dragão do Oriente',replace(replace('1 Regulador + 1 ou mais monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro: escolha 1 Monstro Sincro que seu oponente controla; bana o alvo.','\r',char(13)),'\n',char(10)),'Banir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68140974,'Senhormek Imperador Wisel',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial por seu próprio efeito. \r\nQuando um monstro com a face para cima que você controla for destruído por um efeito de card e enviado para o Cemitério (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão. \r\nOutros monstros que você controla não podem declarar um ataque. \r\nUma vez por turno: você pode escolher 1 Monstro Sincro que seu oponente controla; equipe o alvo a este card. \r\nGanha ATK igual ao ATK combinado dos monstros equipados a ele por este efeito. \r\nUma vez por turno, quando seu oponente ativar um Card de Magia (Efeito Rápido): você pode negar a ativação e, se isso acontecer, destrua-o.','\r',char(13)),'\n',char(10)),'Invocação Especial','Equipar um Monstro Sincro','Negar uma Magia e destruí-la','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68144350,'Boxeador Obstinado Ambidestro',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode escolher 1 monstro "Boxeador Obstinado" no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê não pode Invocar quaisquer monstros por Invocação-Especial durante o turno em que ativar este efeito, exceto monstros "Boxeador Obstinado".','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68144894,'Hecamãos Godos',replace(replace('Se este card batalhar um monstro, nenhum dos dois pode ser destruído nessa batalha. \r\nVocê só pode usar cada um dos seguintes efeitos de "Hecamãos Godos" uma vez por turno. \r\nSe um ou mais cards forem adicionados à mão do seu oponente (exceto durante a Fase de Compra ou Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão. \r\nDurante a Fase Principal do seu oponente (Efeito Rápido): você pode escolher 1 monstro no Cemitério do seu oponente; Invoque-o por Invocação-Especial no seu campo, mas bana-o quando ele deixar o campo.','\r',char(13)),'\n',char(10)),'Invocação Especial','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68159562,'Passeio Magidoce',replace(replace('Escolha 1 card com a face para cima que seu oponente controla e 1 monstro "Magidoce" que você controla ou no seu Cemitério; negue os efeitos desse card do oponente até o final deste turno e, se isso acontecer, devolva seu monstro para a mão. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 Monstro Xyz "Magidoce" que você controla; associe 1 monstro "Magidoce" da sua mão, do Deck ou do Cemitério a ele como matéria. \r\nVocê só pode usar 1 efeito de "Passeio Magidoce" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68167124,'Espadachim Agulha','Quando este card causar Dano de Batalha ao seu oponente: Devolva todos os cards com a face para cima nas Zonas de Cards de Magia & Armadilha de seu oponente à mão.','Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68170903,'Simulação de Plano','Duelistas não podem atacar monstros com a face para baixo durante este turno.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68171737,'Dragão de Pedra','Um dragão formado por enormes penedos que também servem para atacar inimigos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68182934,'Dragoons Celestes de Draconia',replace(replace('Escala de Pêndulo = 7\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno, quando um Monstro Normal que você controla causar dano de batalha a um oponente: você pode escolher 1 card no campo; destrua-o.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSupostamente criadas para invadir o Estado-Celeste neutro e flutuante de Cxulub, essas tropas celestes do Império de Draconia veem pedindo permissão às nações vizinhas para fortalecer sua segurança.','\r',char(13)),'\n',char(10)),'Destruir 1 card','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68184115,'Libélula Inzektor',replace(replace('Uma vez por turno: você pode equipar 1 monstro "Inzektor" da sua mão ou do Cemitério a este card. \r\nSe um ou mais Cards de Equipamento forem enviados para o seu Cemitério enquanto estiverem equipados a este card (exceto durante a Etapa de Dano): você pode Invocar por Invocação-Especial 1 monstro "Inzektor" do seu Deck, exceto "Libélula Inzektor". \r\nEnquanto este card estiver equipado a um monstro, o Nível desse monstro aumenta em 3.','\r',char(13)),'\n',char(10)),'Equipar','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68191243,'Junção dos Escorpião das Trevas',replace(replace('Você pode activar este card apenas quando você tem "Dom Zaloog" no seu Campo com a face para cima. \r\nVocê pode Invocar, por Invocação-Especial, qualquer card da sua mão que inclua "Escorpião das Trevas" no nome. \r\nVocê não pode Invocar, por Invocação-Especial, 2 cards com o mesmo nome com o efeito deste card.','\r',char(13)),'\n',char(10)),'Continuar a Invocar por Invocação Especial?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68191756,'Memória do Legado Mundial',replace(replace('Invoque por Invocação-Especial 1 monstro "Mekk-Cavaleiro" da sua mão ou do Deck em Posição de Defesa, mas devolva-o para a mão durante a Fase Final. \r\nPelo resto deste turno depois que este card resolver, você não pode Invocar monstros por Invocação-Especial, exceto monstros "Mekk-Cavaleiro". \r\nVocê só pode ativar 1 "Memória do Legado Mundial" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68199168,'Harr, Chefe Generaidor das Tempestades',replace(replace('Você só pode controlar 1 "Harr, Chefe Generaidor das Tempestades". \r\nUma vez por turno, se seu oponente adicionar um ou mais cards do Deck à mão dele, exceto durante a Fase de Compra (Efeito Rápido): você pode fazer com que seu oponente envie 1 monstro da mão dele ou do campo para o Cemitério (ele seleciona). \r\nQuando um card ou efeito for ativado (Efeito Rápido): você pode oferecer como Tributo 2 monstros "Generaidor" e/ou Mago; negue a ativação e, se isso acontecer, destrua esse card. \r\nVocê só pode usar este efeito de "Harr, Chefe Generaidor das Tempestades" uma vez por turno.','\r',char(13)),'\n',char(10)),'Enviar um monstro para o Cemitério','Negar a ativação e destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68215963,'Fera Cristalina Tartaruga Esmeralda',replace(replace('Uma vez por turno: você pode escolher 1 monstro que você controla que atacou neste turno; coloque o alvo em Posição de Defesa. \r\nSe este card com a face para cima for destruído em uma Zona de Monstros, em vez de enviá-lo para o Cemitério, você pode colocá-lo com a face para cima na sua Zona de Magias & Armadilhas como uma Magia Contínua.','\r',char(13)),'\n',char(10)),'Colocar na Zona de Magias & Armadilhas quando for destruído','Mudar a posição de batalha','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68223137,'Kuri de Mão Única',replace(replace('Escolha 1 monstro de Link-1 em qualquer Cemitério; devolva-o para o Deck Adicional ou Invoque-o por Invocação-Especial no campo do seu dono. \r\nVocê só pode ativar 1 "Kuri de Mão Única" por turno.','\r',char(13)),'\n',char(10)),'Escolha um monstro para retornar ao Deck ou Invocar por Invocação Especial','Retornar ao Deck Adicional','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68226653,'Flamvell Draganov',replace(replace('Se este card for destruído em batalha e enviado para o Cemitério: cause 500 de dano ao seu oponente. \r\nVocê pode banir este card do seu Cemitério e 1 monstro de FOGO com a face para cima que você controla; adicione 1 "Flamvell Draganov" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Cause 500 de dano ao seu oponente','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68231287,'Júpiter, o Patrono do Poder da Destruição',replace(replace('3 monstros de Nível 10	\r\nUma vez por turno, você também pode Invocar "Júpiter, o Patrono do Poder da Destruição" por Invocação-Xyz ao usar 1 monstro que você controla equipado com 3 ou mais Cards de Equipamento (transfira as matérias dele). \r\nSe este card for Invocado por Invocação-Xyz: você pode equipar qualquer número de Magias de Equipamento do seu Cemitério a este card que possam ser equipadas a ele. \r\nGanha 3000 de ATK enquanto tiver um Monstro Xyz como matéria. \r\nUma vez por turno: você pode desassociar 1 matéria deste card; Invoque por Invocação-Especial 1 monstro "DoomZ" do seu Cemitério e, depois, você pode destruir 1 card no campo.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Xyz usando como Matéria um monstro equipado com um Card de Equipamento?','Efeito de Equipamento','Invocação Especial','Destruir o card?','','','','','','','','','','','','');
INSERT INTO texts VALUES(68246154,'Mágico Mosqueteiro Doc',replace(replace('Durante o turno de qualquer duelista, você pode ativar Cards de Magia/Armadilha "Mágico(a) Mosquete" da sua mão. \r\nSe um Card de Magia/Armadilha for ativado na coluna deste card: você pode adicionar 1 card "Mágico(a) Mosquete" do seu Cemitério à sua mão, mas não um card com o mesmo nome que o desse card ativado. \r\nVocê só pode usar este efeito de "Mágico Mosqueteiro Doc" uma vez por turno.','\r',char(13)),'\n',char(10)),'Recuperar do Cemitério','Ativar aplicando o efeito de "Mágico Mosqueteiro Doc".','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68250822,'Dupla Traição Spright',replace(replace('Escolha 1 monstro no campo ou em qualquer Cemitério e, depois, ative 1 desses efeitos apropriados;\r\n● Associe o monstro alvo a 1 monstro de Classe 2 que você controla como matéria.\r\n● Coloque o monstro alvo que seu oponente controla em uma zona sua para a qual um monstro de Link-2 seu apontar e tome o controle dele.\r\n● Invoque o monstro alvo por Invocação-Especial de qualquer Cemitério em uma zona sua para a qual um monstro de Link-2 seu apontar.	\r\nVocê só pode ativar 1 "Dupla Traição Spright" por turno.','\r',char(13)),'\n',char(10)),'Associar Matéria Xyz','Tome o controle','Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68258355,'ZS - Sábio Armado',replace(replace('Se o único monstro que você controla for 1 monstro de Nível 4 que não se chama "ZS - Sábio Armado", você pode Invocar este card por Invocação-Especial (da sua mão). \r\nUm Monstro Xyz "Utopia" que foi Invocado usando este card no campo como matéria ganha este efeito.\r\n● Se este card for Invocado por Invocação-Xyz: você pode adicionar 1 monstro "ZW -" do seu Deck à sua mão.	\r\nVocê só pode usar este efeito de "ZS - Sábio Armado" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Buscar um ZW - (ZS - Sábio Armado)','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68280530,'Cavaleiro Real','Quando este card destruir um monstro em batalha e enviá-lo ao Cemitério, ganhe PV iguais à DEF do monstro destruído.','Ganhar PV','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68295149,'Arquidemônio Linkmail',replace(replace('2+ monstros, incluindo um Monstro de Ritual, de Fusão, Sincro ou Xyz	\r\nSe este card for Invocado por Invocação-Especial: você pode escolher 1 Monstro de Ritual, de Fusão, Sincro ou Xyz que você controla ou no seu Cemitério; até o final deste turno, todos os monstros que seu oponente controla atualmente perdem ATK igual ao ATK do monstro alvo. \r\nSeu oponente não pode escolher monstros que você controla, que foram Invocados por Invocação-Especial do Deck Adicional, como alvo de efeitos de monstro. \r\nSe este card seria destruído em batalha ou por um efeito de card, em vez disso, você pode banir 1 Monstro de Ritual, de Fusão, Sincro ou Xyz do seu Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68299524,'Dragão Pandêmico',replace(replace('Uma vez por turno: você pode pagar PV em múltiplos de 100; outros monstros com a face para cima no campo perdem esse tanto de ATK. \r\nUma vez por turno: você pode escolher 1 monstro no campo com ATK menor ou igual ao deste card; destrua-o. \r\nSe este card for destruído em batalha ou por um efeito de card: todos os monstros com a face para cima no campo perdem 1000 de ATK.','\r',char(13)),'\n',char(10)),'Reduzir ATK','Destruir um monstro','Todos os monstros perdem 1000 ATK','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68300121,'Espírito Magichave - Vepartu',replace(replace('2 monstros de Nível 4	\r\nSe este card for Invocado por Invocação-Xyz: você pode desassociar 1 matéria deste card; adicione 1 Monstro Normal de Nível 4 ou mais do seu Deck ou Cemitério à sua mão. \r\nSe este card tiver um Monstro Normal como matéria, ele ganha este efeito.\r\n● No começo da Etapa de Dano, se este card batalhar um monstro do oponente com o mesmo Atributo que o de um Monstro Normal ou monstro "Magichave" no seu Cemitério: você pode desassociar 1 matéria deste card; seu oponente deve enviar esse monstro para o Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68304193,'Unicórnio Kashtira',replace(replace('Se você não controlar nenhum monstro, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode usar cada um dos seguintes efeitos de "Unicórnio Kashtira" uma vez por turno. \r\nDurante sua Fase Principal: você pode adicionar 1 Magia "Kashtira" do seu Deck à sua mão. \r\nQuando este card declarar um ataque, ou se seu oponente ativar um efeito de monstro (exceto durante a Etapa de Dano): você pode olhar o Deck Adicional do seu oponente e, se isso acontecer, bana 1 monstro dali, com a face para baixo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68304813,'Cards Preciosos do Além','Quando você Invoca, por Invocação-Tributo, com sucesso um monstro que requira 2 ou mais Tributos, compre 2 cards do seu Deck.','Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68316358,'Dança Cativante',replace(replace('Quando este card for ativado: você pode adicionar 1 monstro "Rainha Cativante" ou 1 "Palácio Cativante" do seu Deck à sua mão. \r\nCada monstro "Rainha Cativante" que você controla ganha ATK, igual ao ATK dos monstros equipados a ele por seu efeito. \r\nVocê pode enviar 1 outra Magia/Armadilha que você controla para o Cemitério; Invoque por Invocação-Especial tantos monstros "Rainha Cativante" com nomes diferentes quanto possível do seu Cemitério. \r\nVocê só pode usar este efeito de "Dança Cativante" uma vez por turno. \r\nVocê só pode ativar 1 "Dança Cativante" por turno.','\r',char(13)),'\n',char(10)),'Adicionar do Deck à sua mão?','Invoque por Invocação Especial o máximo possível','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68319538,'Fortaleza Cósmica Gol''gar',replace(replace('"Amonite Alienígena" + 1 ou mais monstros "Alienígena" não-Reguladores	\r\nUma vez por turno, você pode selecionar qualquer número de Cards de Magia ou Armadilha com a face para cima. \r\nDevolva esses cards para as mãos de seus donos e distribua novos Marcadores-A entre os monstros no campo igual ao número de cards devolvidos. \r\nUma vez por turno, você pode remover 2 Marcadores-A de qualquer lugar no campo para destruir 1 card que seu oponente controla.','\r',char(13)),'\n',char(10)),'Retornar a Magia/Armadilha para a mão do dono','Destrua 1 card que seu oponente controla','Escolha o monstro no qual colocar "Marcador-A"','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68334074,'Restaurar Milagroso','Remova 2 Marcadores de Magia do seu campo e, depois, escolha 1 "Mago Negro" ou "Blader Notável" no seu Cemitério; Invoque o alvo por Invocação-Especial.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68337209,'Maliss no Subterrâneo',replace(replace('Quando este card for ativado: você pode banir 1 card "Maliss" da sua mão, do Deck ou do Cemitério. \r\nEnquanto 3 ou mais das suas Armadilhas "Maliss" com nomes diferentes estiverem banidas, Monstros Link "Maliss" que você controla ganham 3000 de ATK. \r\nEnquanto você controlar um Monstro Link "Maliss", os monstros do seu oponente só podem escolher Monstros Link "Maliss" como alvo de ataques. \r\nVocê só pode ativar 1 "Maliss no Subterrâneo" por turno.','\r',char(13)),'\n',char(10)),'','','','Banir o card "Maliss"?','','','','','','','','','','','','');
INSERT INTO texts VALUES(68337210,'Maliss no Subterrâneo',replace(replace('Quando este card for ativado: você pode banir 1 card "Maliss" da sua mão, do Deck ou do Cemitério. \r\nEnquanto 3 ou mais das suas Armadilhas "Maliss" com nomes diferentes estiverem banidas, Monstros Link "Maliss" que você controla ganham 3000 de ATK. \r\nEnquanto você controlar um Monstro Link "Maliss", os monstros do seu oponente só podem escolher Monstros Link "Maliss" como alvo de ataques. \r\nVocê só pode ativar 1 "Maliss no Subterrâneo" por turno.','\r',char(13)),'\n',char(10)),'','','','Banir o card "Maliss"?','','','','','','','','','','','','');
INSERT INTO texts VALUES(68339286,'Guardião de Metal','Um demônio que guarda os tesouros do mundo inferior. Sente-se em casa nas trevas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68353324,'Castor Ágil','Quando este card for Invocado por Invocação-Normal: você pode Invocar por Invocação-Especial 1 monstro "Ágil" de Nível 3 ou menos do seu Deck ou Cemitério.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68366996,'Soldado Gêmeos',replace(replace('Este card é considerado como um Monstro Normal enquanto estiver com a face para cima no campo ou no Cemitério. \r\nEnquanto este card estiver com a face para cima no campo, você pode Invocá-lo por Invocação-Normal para que ele seja considerado como um Monstro de Efeito com este efeito:\r\n● Uma vez por turno, se este card seria destruído em batalha, ele não é destruído.	\r\nSe este card batalhar, depois do cálculo de dano, você pode Invocar por Invocação-Especial 1 monstro Gêmeos de Nível 4 ou menos do seu Deck, exceto "Soldado Gêmeos".','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68371799,'Comandante Arquidemônio',replace(replace('Se você controlar um card "Arquidemônio", você pode Invocar este card por Invocação-Especial (da sua mão), mas ele não pode atacar neste turno. \r\nVocê só pode Invocar "Comandante Arquidemônio" por Invocação-Especial uma vez por turno desta forma. \r\nQuando ele for Invocado por Invocação-Especial desta forma: escolha 1 card "Arquidemônio" que você controla; destrua o alvo. \r\nQuando este card for Invocado por Invocação-Tributo: você pode escolher 1 monstro "Arquidemônio" de Nível 6 no seu Cemitério; Invoque o alvo por Invocação-Especial com a face para cima em Posição de Defesa.','\r',char(13)),'\n',char(10)),'Destruir','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68378605,'Vodnika, o Espírito da Fonte',replace(replace('Se um ou mais monstros de Nível 10 forem enviados para o Cemitério, exceto "Vodnika, o Espírito da Fonte" (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial do seu Cemitério (se ele estava lá quando o monstro foi enviado) ou da mão (mesmo se ele não estava) em Posição de Defesa, mas bana-o quando ele deixar o campo. \r\nVocê pode escolher 1 monstro de Nível 10 no seu Cemitério; Invoque-o por Invocação-Especial no campo do seu oponente (mas negue seus efeitos) e, depois, compre 1 card. \r\nVocê só pode usar cada efeito de "Vodnika, o Espírito da Fonte" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar este card por Invocação Especial','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68392533,'Célula de Recarga Telecinética',replace(replace('Só pode ser equipado a um monstro do Tipo Psíquico. \r\nVocê não precisa pagar PV para ativar os seus efeitos. \r\nQuando o monstro equipado for destruído e este card enviado ao Cemitério, você pode pagar 1000 PV para devolver este card à sua mão.','\r',char(13)),'\n',char(10)),'Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68395509,'Corvo Majespectro - Yata',replace(replace('Escala de Pêndulo = 5\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nQuando este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 Magia "Majespectro" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Corvo Majespectro - Yata" uma vez por turno. \r\nEnquanto este card estiver na sua Zona de Monstros, seu oponente não pode escolhê-lo como alvo de efeitos de card e, além disso, ele não pode ser destruído pelos efeitos de card do seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68396121,'Número C107: Neo Dragão de Táquion de Olhos das Galáxias',replace(replace('3 monstros de Nível 9	\r\nUma vez por turno: você pode desassociar 1 matéria deste card; até o final deste turno, negue os efeitos de todos os outros cards com a face para cima atualmente no campo e, além disso, seu oponente não pode ativar cards ou efeitos no campo. \r\nSe este card tiver "Número 107: Dragão de Táquion de Olhos das Galáxias" como matéria, ele ganha este efeito.\r\n● Você pode oferecer 2 monstros como Tributo; este card pode realizar até 3 ataques contra monstros durante cada Fase de Batalha neste turno.','\r',char(13)),'\n',char(10)),'Negar o efeito','Ataques múltiplos','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68396778,'Barganha Faustiana','Escolha 1 monstro Invocado por Invocação-Especial em qualquer campo; envie-o para o Cemitério e, se isso acontecer, Invoque por Invocação-Especial 1 Monstro Normal de Nível 4 ou menos da sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68400115,'Férias do Imperador','Anule os efeitos de todos os Cards de Equipamento.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68401546,'Fada-Madrinha','Este monstro voador é conhecido por trazer felicidade a todos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68406755,'Triâmide Esfinge',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial com o efeito de um card "Triâmide", e não pode ser Invocado por Invocação-Especial de nenhuma outra forma. \r\nSe um ou mais cards "Triâmide" com a face para cima que você controla, exceto "Triâmide Esfinge", forem destruídos em batalha ou por um efeito de card: você pode Invocar este card por Invocação-Especial da sua mão. \r\nEnquanto você controlar outro card "Triâmide", este card ganha 500 de ATK e DEF para cada Card de Magia de Campo com um nome diferente no seu Cemitério e, além disso, monstros que seu oponente controla não podem atacar, exceto atacar "Triâmide Esfinge".','\r',char(13)),'\n',char(10)),'Invocar este card por Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68427465,'Flamberge Perverso - Baou',replace(replace('Envie 1 card da sua mão para o Cemitério e, depois, escolha 1 monstro no campo; equipe este card no alvo. \r\nEle ganha 500 de ATK. \r\nNegue os efeitos dos monstros do oponente destruídos em batalha com o monstro equipado.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68431965,'Dragão da Explosão Sublime',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro: você pode enviar 1 monstro do seu Deck para o Cemitério, cujo Nível seja menor que o Nível deste card no campo e, se isso acontecer, reduza o Nível deste card pelo Nível desse monstro, mas pelo resto deste turno, você não pode ativar os efeitos de monstros com o mesmo nome que o monstro enviado tinha no Cemitério. \r\nVocê só pode usar este efeito de "Dragão da Explosão Sublime" uma vez por turno. \r\nUma vez por Corrente, durante a Fase Principal do seu oponente, você pode (Efeito Rápido): imediatamente depois que este efeito resolver, Invoque por Invocação-Sincro usando este card que você controla.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68441986,'Habilidade Ninjitsu da Marcha dos Mosquitos',replace(replace('Invoque por Invocação-Especial até 2 monstros Inseto de Nível 4 ou menos da sua mão (com o mesmo Nível, se estiver Invocando 2). \r\nSe você controlar "Número 2: O Mosquito Ninja das Sombras": você pode banir este card do seu Cemitério e, depois, escolha monstros com a face para cima que seu oponente controla até o número de monstros Inseto que você controla; coloque 1 Marcador de Alucinação em cada um desses monstros. \r\n(Os efeitos, se houver, de monstros com Marcadores de Alucinação são negados.) \r\nVocê só pode usar cada efeito de "Habilidade Ninjitsu da Marcha dos Mosquitos" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Colocar um marcador','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68450517,'Duratrevas Aliado Genex',replace(replace('Uma vez por turno: você pode escolher 1 monstro em Posição de Ataque que seu oponente controla com o mesmo Atributo que o deste card; destrua o alvo. \r\nEste card não pode atacar no turno em que este efeito for ativado.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68456353,'Caninos de Exterio','Quando seu oponente ativar um Card de Magia/Armadilha enquanto você controlar um monstro "Naturia" e tiver pelo menos 1 card na sua mão: negue a ativação e, se isso acontecer, destrua-o e, depois, envie 1 card da sua mão para o Cemitério.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68462976,'Vila Secreta dos Magos',replace(replace('Se somente você controlar um monstro Mago, seu oponente não pode ativar Cards de Magia. \r\nSe você não controlar nenhum monstro Mago, você não pode ativar Cards de Magia.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68464358,'Rastreador Foguette',replace(replace('(Efeito Rápido): você pode escolher 1 card com a face para cima que você controla; destrua-o e, se isso acontecer, Invoque por Invocação-Especial 1 monstro "Foguette" do seu Deck, exceto "Rastreador Foguette" e, além disso, pelo resto deste turno, você não pode Invocar por Invocação-Especial do Deck Adicional, exceto monstros de TREVAS. \r\nVocê só pode usar este efeito de "Rastreador Foguette" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68468459,'Caído de Arbaz',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial (exceto durante a Etapa de Dano): você pode descartar 1 card; Invoque por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional usando monstros em qualquer campo, incluindo este card, mas você não pode usar outros monstros que você controla como matéria. \r\nVocê só pode usar este efeito de "Caído de Arbaz" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68468460,'Caído de Arbaz',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial (exceto durante a Etapa de Dano): você pode descartar 1 card; Invoque por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional usando monstros em qualquer campo, incluindo este card, mas você não pode usar outros monstros que você controla como matéria. \r\nVocê só pode usar este efeito de "Caído de Arbaz" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68468461,'Caído de Arbaz',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial (exceto durante a Etapa de Dano): você pode descartar 1 card; Invoque por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional usando monstros em qualquer campo, incluindo este card, mas você não pode usar outros monstros que você controla como matéria. \r\nVocê só pode usar este efeito de "Caído de Arbaz" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68473226,'Dragão Endurecido Armado',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) ao enviar 1 monstro de Nível 8 ou mais da sua mão para o Cemitério. \r\nSe você oferecer este card como Tributo para a Invocação-Tributo de um monstro de Nível 7 ou mais, esse monstro não pode ser destruído por efeitos de card.','\r',char(13)),'\n',char(10)),'O efeito de "Dragão Endurecido Armado" está sendo aplicado.','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68477598,'Fissura Pêndulo','Quando um ou mais monstros seriam Invocados por Invocação-Pêndulo: negue a Invocação-Pêndulo e, se isso acontecer, embaralhe esses monstros no Deck.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68490573,'Hora de se Levantar',replace(replace('Se um Monstro Sincro Dragão estiver no campo: Invoque por Invocação-Especial do seu Deck até 2 monstros, que sejam monstros "Ressonador" e/ou monstros Dragão de Nível 1. \r\nQuando um efeito de monstro for ativado, enquanto você controlar um Monstro Sincro Dragão de TREVAS de Nível 10 ou mais: você pode banir este card do seu Cemitério; negue o efeito e, se isso acontecer, 1 Monstro Sincro que você controla ganha 2000 de ATK até o final do próximo turno. \r\nVocê só pode usar cada efeito de "Hora de se Levantar" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Escolha o monstro cujo ATK aumentar','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68505803,'Controlador Genex','Como um mestre de todos os poderes e elementos, este é um dos poucos monstros Genex capazes de se comunicar com seus companheiros.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68507541,'Ligre de Estimação Amazoness',replace(replace('"Tigre Amazoness" + 1 monstro "Amazoness"	\r\nUma vez por batalha, se este card atacar, durante o cálculo de dano: você pode fazer com que esse card ganha 500 de ATK, apenas durante esse cálculo de dano. \r\nSe um monstro "Amazoness" seu atacou um monstro do oponente, depois do cálculo de dano: você pode escolher 1 monstro com a face para cima que seu oponente controla; ele perde 800 de ATK. \r\nMonstros que seu oponente controla não podem atacar monstros "Amazoness" que você controla, exceto este.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68508433,'Espírito Mestre da Força Técnica – Pêndulo Governante',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nDurante sua Fase Principal: você pode retornar este card para o Deck Adicional, então você pode adicionar 1 Monstro Pêndulo de Nível 7 do seu Deck ou com a face para cima no seu Deck Adicional à sua mão. \r\nVocê só pode usar este efeito de "Espírito Mestre da Força Técnica – Pêndulo Governante" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\n1 Monstro Pêndulo de Nível 7 ou maior + 1 Monstro Pêndulo	\r\nNão pode ser destruído por efeitos.\r\nOs monstros do seu oponente não podem atacar, exceto Monstros Pêndulo sem um Nível.\r\nUma vez por turno: você pode colocar este card na sua Zona de Pêndulo.\r\nVocê pode oferecer 1 monstro como Tributo, então escolha 1 card que seu oponente controla; destrua-o, e se fizer, cause 1600 de dano a ele. \r\nVocê só pode usar este efeito de "Espírito Mestre da Força Técnica – Pêndulo Governante" até duas vezes por turno.','\r',char(13)),'\n',char(10)),'Retornar ao Deck Adicional','Destruir','Colocar na Zona de Pêndulo','Adicionar aquele monstro à mão?','','','','','','','','','','','','');
INSERT INTO texts VALUES(68516705,'Centauro Místico','Sendo metade homem, metade cavalo, este monstro é conhecido por sua enorme velocidade.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68535320,'Mão de Fogo','Quando este card em sua posse for destruído por um card do seu oponente e enviado para o seu Cemitério: você pode escolher 1 monstro que ele controla; destrua o alvo e, depois, você pode Invocar por Invocação-Especial 1 "Mão de Gelo" do seu Deck.','Destruir e Invocar por Invocação Especial','Invocação Especial?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68540058,'Metalmorfo',replace(replace('(Este card deve ser sempre considerado como um card "Metalmorfe".)	\r\nEscolha 1 monstro com a face para cima no campo; equipe este card no alvo. \r\nEle ganha 300 de ATK/DEF. \r\nSe ele atacar, ele ganha ATK igual à metade do ATK do alvo do ataque, apenas durante o cálculo de dano.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68540059,'Metalmorfo',replace(replace('(Este card deve ser sempre considerado como um card "Metalmorfe".)	\r\nEscolha 1 monstro com a face para cima no campo; equipe este card no alvo. \r\nEle ganha 300 de ATK/DEF. \r\nSe ele atacar, ele ganha ATK igual à metade do ATK do alvo do ataque, apenas durante o cálculo de dano.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68543408,'Xiaolong da Poeira Estelar',replace(replace('Quando você Invocar "Dragão da Poeira Estelar" por Invocação-Sincro: você pode Invocar este card por Invocação-Especial do seu Cemitério em Posição de Ataque. \r\nA cada turno, na primeira vez que este card seria destruído em batalha, ele não é destruído.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68597372,'Zenmaister de Corda',replace(replace('2 monstros de Nível 4	\r\nEste card ganha 300 de ATK para cada Matéria Xyz associada a este card. \r\nUma vez por turno: Você pode desassociar 1 Matéria Xyz deste card para escolher 1 monstro com a face para cima que você controla; coloque esse monstro com a face para cima com a face para baixo em Posição de Defesa e, se isso acontecer, durante a Fase Final deste turno, coloque-o com a face para cima em Posição de Ataque.','\r',char(13)),'\n',char(10)),'Mudar a posição de batalha','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68601507,'Bujingi Garça','Durante o cálculo de dano (no turno de qualquer duelista), se um monstro "Bujin" do Tipo Besta-Guerreira que você controla batalhar um monstro do oponente: você pode enviar este card da sua mão para o Cemitério; apenas durante esse cálculo de dano, o ATK do seu monstro se torna o dobro do seu ATK original.','Alterar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68618157,'Bujinki Amaterasu',replace(replace('3 monstros de Nível 4	\r\nVocê só pode controlar 1 "Bujinki Amaterasu". \r\nUma vez por turno, durante o turno de qualquer duelista: você pode desassociar 1 Matéria Xyz deste card; aplique este efeito, dependendo de quem é o turno.\r\n● Seu turno: Escolha 1 dos seus monstros banidos de Nível 4 ou menos; Invoque o alvo por Invocação-Especial.\r\n● Turno do seu oponente: Escolha 1 dos seus monstros banidos de Nível 4 ou menos; adicione o alvo à sua mão.','\r',char(13)),'\n',char(10)),'Invocação Especial','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68625623,'Magistrado Malévolo Desacorrentado - Kamura',replace(replace('Você pode escolher até 3 cards que você controla; destrua-os, e se fizer, Invoque por Invocação-Especial este card da sua mão, então você pode aplicar qualquer um dos seguintes efeitos, em sequência, baseado nos tipos originais dos cards destruídos.\r\n● Monstro: compre 1 card.\r\n● Magia: mude a posição de batalha de 1 monstro no campo.\r\n● Armadilha: destrói 1 outro card no campo.	\r\nSe este card no campo é destruído por um efeito: você pode destruir todos os monstros no campo.\r\nVocê só pode usar cada um dos efeitos de "Magistrado Malévolo Desacorrentado - Kamura" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Efeito de destruição','Comprar 1 card?','Mudar a posição de batalha?','Destruir?','','','','','','','','','','','');
INSERT INTO texts VALUES(68625727,'Princesa da Premonição Petalelfa',replace(replace('VIRE: Você pode colocar todos os monstros com a face para cima em Posição de Ataque que seu oponente controla, com a face para cima em Posição de Defesa. \r\nMonstros colocados em Posição de Defesa por este efeito não podem mudar suas posições de batalha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68630939,'Proteção de Números',replace(replace('Quando um Card de Magia/Armadilha, ou efeito de monstro, for ativado, enquanto você controlar um Monstro Xyz "Número": negue a ativação e, se isso acontecer, destrua esse card. \r\nSe um ou mais Monstros Xyz "Número" que você controla forem destruídos em batalha ou por um efeito de card, enquanto este card estiver no seu Cemitério: você pode Baixar este card, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar 1 efeito de "Proteção de Números" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68638985,'Rã Limo','Um limo com a cabeça de um sapo que ataca com um coaxar terrível.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68658728,'Quimera Pequena',replace(replace('Todos os monstros de FOGO no campo ganham 500 de ATK. \r\nTodos os monstros de ÁGUA no campo perdem 400 de ATK.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68661341,'Compra Única',replace(replace('Se você tiver 3 ou mais cards na sua mão (sem contar este card) e nenhum deles for um monstro: bana toda a sua mão com a face para cima; adicione 1 monstro do seu Deck à sua mão. \r\nSe isso acontecer, você não pode Invocar por Invocação-Normal ou Especial nenhum monstro pelo restante do turno, exceto monstros com esse nome.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68663427,'Malha Reveladora da Reencarnação',replace(replace('(Este card deve ser sempre considerado como um card "Xyz de Armadura".)	\r\nUm Monstro Xyz equipado com este card ganha esses efeitos.\r\n● Não pode ser destruído em batalha.\r\n● Uma vez por turno, se este card batalhou neste turno (Efeito Rápido): você pode devolver 1 card equipado a este card para a mão e, depois, imediatamente depois que este efeito resolver, Invoque por Invocação-Xyz 1 Monstro Xyz de ÁGUA.	\r\nUma vez por turno, durante a Fase Final, se este card estiver no Cemitério porque foi enviado para lá neste turno: você pode equipar este card a 1 Monstro Xyz que você controla. \r\nVocê só pode ativar 1 "Malha Reveladora da Reencarnação" por turno.','\r',char(13)),'\n',char(10)),'','Invocar por Invocação Xyz (Malha Reveladora da Reencarnação)','Efeito de Equipamento','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68663748,'Futuro da Fortuna','Escolha 1 de seus monstros "Senhora Fortuna" banidos; devolva-o para o Cemitério e, depois, compre 2 cards.','Escolha um card para retornar ao Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68670547,'Paladino do Dragão Amaldiçoado','Uma vez por turno: você pode escolher 1 monstro Zumbi de Nível 4 ou menos no Cemitério do seu oponente que foi destruído em batalha; Invoque o alvo por Invocação-Especial.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68679595,'Raio Utopia Leão Definitivo',replace(replace('3 monstros de Nível 5	\r\n(Este card deve ser sempre considerado como "Número C39: Raio Utopia".)	\r\nUma vez por turno: você pode desassociar 1 matéria deste card; equipe 1 monstro "ZW -" do seu Deck ou Deck Adicional a este card como se ele tivesse sido equipado pelo efeito desse monstro. \r\nA ativação deste efeito, bem como este efeito, não podem ser negados. \r\nUma vez por turno, enquanto este card estiver equipado com um Card de Monstro "ZW -" (Efeito Rápido): você pode escolher 1 Monstro de Efeito que seu oponente controla; negue seus efeitos e, se isso acontecer, diminua o ATK dele pela metade.','\r',char(13)),'\n',char(10)),'Equipe um monstro ZW','Negue os efeitos de um monstro do seu oponente','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68688135,'Controle do Vampiro',replace(replace('Quando um Card de Magia/Armadilha, ou efeito de monstro, for ativado enquanto você controlar um monstro "Vampiro(a)": negue a ativação e, se isso acontecer, destrua esse card e, depois, se era um Card de Monstro, ganhe PV igual ao ATK original dele. \r\nVocê só pode ativar 1 "Controle do Vampiro" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68721020,'Força Perniciosa',replace(replace('Escolha 1 monstro com a face para cima no campo; equipe este card a ele como um Card de Equipamento com esses efeitos.\r\n● O monstro equipado não é afetado por efeitos de Magias.\r\n● Uma vez por turno: você pode destruir este card, e se fizer, adicione 1 card "Pernicioso(a)" do seu Deck à sua mão.	\r\nSe um card estiver na Zona de Campo: você pode banir este card e 1 outro card "Pernicioso(a)" do seu Cemitério; destrua todos os monstros no campo.\r\nVocê só pode usar cada um dos efeitos de "Força Perniciosa" uma vez por turno.','\r',char(13)),'\n',char(10)),'Equipar','Efeito de destruição','Destruir e buscar','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68722455,'Ogro Vermelho','Quando este card for Invocado por Invocação Normal: você pode enviar qualquer número de cards da sua mão para o Cemitério e, depois, escolher o mesmo número de cards no campo; devolva os alvos para a mão.','Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68745629,'Inferno, o HERÓI do Elemento',replace(replace('"Calor, o HERÓI do Elemento" + "Sra. Cálida, o HERÓI do Elemento"	\r\nDeve ser Invocado por Invocação-Fusão e não pode ser Invocado por Invocação-Especial de nenhuma outra forma. \r\nSe este card batalhar com um monstro de ÁGUA, este card ganha 1000 de ATK apenas durante a Etapa de Dano.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68756810,'Tubarão Cortador',replace(replace('Quando um card ou efeito for ativado que escolha como alvo 1 monstro que você controla (e nenhum outro card) ou quando um monstro que você controla for escolhido como alvo de um ataque, enquanto este card estiver na sua mão ou no Cemitério (Efeito Rápido): você pode oferecer esse monstro como Tributo; Invoque este card por Invocação-Especial. \r\nSe este card for Invocado por Invocação-Especial: você pode ativar este efeito; durante a Fase Final deste turno, adicione 1 monstro de ÁGUA do seu Cemitério à sua mão, exceto "Tubarão Cortador". \r\nVocê só pode usar cada efeito de "Tubarão Cortador" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68762510,'Flautista Sortudo',replace(replace('Este card é considerado como um Monstro Normal enquanto estiver com a face para cima no campo ou no Cemitério. \r\nEnquanto este card estiver com a face para cima no campo, você pode Invocá-lo por Invocação-Normal para fazer com que ele seja considerado como um Monstro de Efeito com este efeito:\r\n● Quando este card destruir um monstro do oponente em batalha e enviá-lo para o Cemitério, compre 1 card.','\r',char(13)),'\n',char(10)),'Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68769900,'Barba Vermelha, o Marujo Saquepatrollha',replace(replace('Durante o turno do seu oponente (Efeito Rápido): você pode Invocar por Invocação-Especial 1 monstro "Saquepatrollha" do seu Deck Adicional com o mesmo Atributo que o de um monstro que seu oponente controla ou no Cemitério dele e, se isso acontecer, equipe este card que você controla a ele. \r\nSe este card for enviado da mão ou da Zona de Monstros para o Cemitério: você pode escolher 1 monstro "Saquepatrollha" que você controla, exceto "Barba Vermelha, o Marujo Saquepatrollha"; equipe este card a ele. \r\nVocê só pode usar cada efeito de "Barba Vermelha, o Marujo Saquepatrollha" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68774379,'Dragão Ciberbarreira',replace(replace('Este card não pode ser Invocado por Invocação-Normal ou Baixado. \r\nEste card não pode ser Invocado por Invocação-Especial, exceto com "Unidade Refletora de Ataque". \r\nUma vez por turno, enquanto este card estiver em Posição de Ataque, o próximo ataque do oponente é negado.','\r',char(13)),'\n',char(10)),'Negar o ataque','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68779682,'Barragem de Labrinto','Quando você ativar um Card de Armadilha Normal Baixado, exceto "Barragem de Labrinto": este efeito se torna o efeito dessa Armadilha Normal quando esse card for ativado e, além disso, até o final do próximo turno do seu oponente depois que este card resolver, seu oponente não sofre dano de efeito dos seus efeitos de card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68786330,'Feromônios de Ataque','Se um monstro que você controla atacar um monstro em Posição de Defesa, mude esse monstro para Posição de Ataque com a face para cima no final da Etapa de Dano se seu monstro atacante for do Tipo Réptil.','Mudar a posição de batalha','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68809475,'Velociclo Koa''ki Meiru',replace(replace('Durante cada uma das suas Fases Finais, destrua este card a não ser que você envie 1 "Núcleo de Ferro de Koa''ki Meiru" da sua mão para o Cemitério ou revele 1 monstro do Tipo Máquina na sua mão. \r\nSe você comprar "Núcleo de Ferro de Koa''ki Meiru" durante sua Fase de Compra, você pode revelá-lo ao seu oponente para comprar mais 1 card.','\r',char(13)),'\n',char(10)),'Escolha 1 "Núcleo de Ferro de Koa''ki Meiru" para enviar para o Cemitério','Revele ao oponente 1 monstro Máquina','Destruir "Velociclo Koa''ki Meiru"','Comprar','','','','','','','','','','','','');
INSERT INTO texts VALUES(68810435,'Biscoito☆Nhamy',replace(replace('Se você controlar um monstro de Link-1 ou um Monstro Sincro de Nível 2, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Biscoito☆Nhamy" por Invocação-Especial uma vez por turno desta forma. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 monstro com a face para cima que seu oponente controla; ele perde 1000 de ATK, ou, se este card foi Invocado por Invocação-Especial pelo efeito de um Monstro Sincro, em vez disso, você pode destruir esse monstro. \r\nVocê só pode usar este efeito de "Biscoito☆Nhamy" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Reduzir ATK','Usar como substituição de destruição?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68811206,'Tyler, o Grande Guerreiro',replace(replace('Este monstro não pode ser Invocado por Invocação-Especial. \r\nQuando esta carta destruir um monstro em batalha e enviá-lo para o Cemitério, cause dano aos Pontos de Vida do seu oponente igual ao ATK do monstro destruído.','\r',char(13)),'\n',char(10)),'Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68812773,'Lillybô',replace(replace('Quando este card for Invocado por Invocação-Normal ou virado com a face para cima: você pode escolher 1 "Orbital 7" no seu Cemitério; Invoque o alvo por Invocação-Especial com a face para cima em Posição de Ataque ou com a face para baixo em Posição de Defesa. \r\nUma vez por turno: você pode oferecer como Tributo qualquer número de monstros Máquina; Invoque por Invocação-Especial um mesmo número de monstros "Fóton" e/ou "Galáxia" da sua mão.','\r',char(13)),'\n',char(10)),'Invocação Especial','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68815132,'Dançarina Harpia',replace(replace('Você pode escolher 1 monstro de VENTO que você controla; devolva-o para a mão e, depois, você pode Invocar por Invocação-Normal 1 monstro de VENTO. \r\nVocê só pode usar este efeito de "Dançarina Harpia" uma vez por turno. \r\nO nome deste card se torna "Lady Harpia" enquanto estiver no campo ou no Cemitério.','\r',char(13)),'\n',char(10)),'Retornar à mão','Escolher 1 monstro de VENTO para Invocar?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68815401,'Fogo Selvagem',replace(replace('Pague 500 PV; destrua todos os cards "Acelerador de Explosão" que você controla e, se isso acontecer, destrua tantos monstros no campo quanto possível e, depois, Invoque por Invocação-Especial 1 "Ficha de Fogo Selvagem" (Piro/FOGO/Nível 3/ATK 1000/DEF 1000) em Posição de Ataque. \r\nSeus monstros não podem atacar no turno em que você ativar este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68815402,'Ficha de Fogo Selvagem','Invocado por Especial com o efeito "Fogo Selvagem".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68819554,'Camaramágico Malabarista Danoso',replace(replace('Quando um card ou efeito que causaria dano a você for ativado (Efeito Rápido): você pode descartar este card; negue a ativação e, se isso acontecer, destrua esse card. \r\nDurante a Fase de Batalha (Efeito Rápido): você pode descartar este card; reduza a 0 o próximo dano de batalha que você sofreria neste turno. \r\nVocê pode banir este card do seu Cemitério; adicione 1 monstro "Camaramágico" do seu Deck à sua mão, exceto "Camaramágico Malabarista Danoso". \r\nVocê só pode usar este efeito de "Camaramágico Malabarista Danoso" uma vez por turno.','\r',char(13)),'\n',char(10)),'Negar a ativação e destruir','O dano de batalha se torna 0','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68823957,'Defensor Nêmesis Subterror',replace(replace('Durante o turno de qualquer duelista, quando seu oponente ativar um card ou efeito que escolha como alvo exatamente 1 monstro Baixado que você controla (e nenhum outro card), ou quando um monstro Baixado que você controla for escolhido como alvo de um ataque por um monstro do oponente: você pode enviar este card da sua mão ou com a face para cima no seu campo para o Cemitério e, depois, escolher outro monstro que você controla que seria um alvo apropriado; esse card/efeito/ataque agora escolhe o novo alvo. \r\nEnquanto você controlar um monstro Baixado, este card não pode ser destruído em batalha ou por efeitos de card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68829754,'Eldlixir do Despertar Negro',replace(replace('Invoque por Invocação-Especial 1 monstro Zumbi da sua mão ou do Deck em Posição de Defesa, mas se você não controlar nenhum monstro "Eldlich", você só pode Invocar monstros "Eldlich" por Invocação-Especial com este efeito. \r\nPelo resto deste turno depois que este card resolver, você não pode Invocar por Invocação-Especial, exceto monstros Zumbi. \r\nVocê pode banir este card do seu Cemitério; Baixe 1 Magia/Armadilha "Terra Dourada" do seu Deck. \r\nVocê só pode usar 1 efeito de "Eldlixir do Despertar Negro" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Baixar Magia/Armadilha','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68831625,'Comando DoomZ "D.O.O.M.D.U.R.G."',replace(replace('Uma vez por turno, durante a Fase de Apoio: cause 500 de dano ao controlador do monstro equipado. \r\nUm monstro "DoomZ" equipado com este card, ou um Monstro Xyz Máquina de VENTO que tenha este card como matéria, ganha os seguintes efeitos.\r\n● Seu oponente não pode escolher este card como alvo de efeitos de card.\r\n● Uma vez por turno (Efeito Rápido): você pode ativar este efeito; destrua 1 outro card com a face para cima que você controla e, além disso, pelo resto deste turno, este card ganha ATK igual ao seu próprio Nível/Classe x 100, pode atacar diretamente e, se ele batalhou, ele é destruído no final da Etapa de Dano.','\r',char(13)),'\n',char(10)),'Causar dano','Destruir (Comando DoomZ "D.O.O.M.D.U.R.G.")','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68833958,'Ginete Reserva','Escolha 1 monstro com a face para cima no campo; ele ganha 1500 de ATK até o final deste turno.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68836428,'Levia de Três Pontas',replace(replace('3 monstros de Nível 3	\r\nBana quaisquer monstros destruídos em batalha com este card. \r\nUma vez por turno, durante o turno de qualquer duelista: você pode desassociar 1 Matéria Xyz deste card e, depois, escolher 1 monstro com a face para cima no campo; ele perde 800 de ATK e, além disso, seus efeitos são negados. \r\nEssas mudanças duram até o final deste turno.','\r',char(13)),'\n',char(10)),'Banir','Negar o efeito','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68846917,'Ogro de Rocha da Gruta #1','Protegido por um sólido corpo de rocha, este monstro desfere socos capazes de quebrar ossos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68860936,'Anjo Tindângulo',replace(replace('VIRE: Você pode Invocar por Invocação-Especial 1 monstro Virar da sua mão ou do Cemitério com a face para baixo em Posição de Defesa, exceto "Anjo Tindângulo" e, depois, se for a Fase de Batalha do seu oponente, encerre a Fase de Batalha. \r\nVocê só pode usar este efeito de "Anjo Tindângulo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68870276,'Reflexo Demoníaco nº 1','Este monstro pode atrair os inimigos para o mundo dos espelhos, deixando-os indefesos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68875140,'Goblin Vendedor','Sempre que um monstro que você controla causar dano de batalha ao seu oponente, retorne 1 card na Zona de Cards de Magia & Armadilha do seu oponente para a mão do dono.','Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68881649,'Espírito-Possuído - Eria',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão ou do Deck) ao enviar para o Cemitério 1 "Eria, a Encantadora da Água" com a face para cima e 1 monstro de ÁGUA com a face para cima que você controla. \r\nSe este card Invocado por Invocação-Especial por seu efeito atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68881650,'Espírito-Possuído - Eria',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão ou do Deck) ao enviar para o Cemitério 1 "Eria, a Encantadora da Água" com a face para cima e 1 monstro de ÁGUA com a face para cima que você controla. \r\nSe este card Invocado por Invocação-Especial por seu efeito atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68897338,'Behilmoth, o Mitológico',replace(replace('Se este card estiver na sua mão: você pode descartar 2 ou mais monstros "Mitológico(a)", incluindo este card e, se isso acontecer, Invoque por Invocação-Especial 1 Monstro Sincro "Mitológico(a)" do seu Deck Adicional cujo Nível seja igual à soma dos Níveis originais dos monstros descartados (isso é considerado uma Invocação-Sincro). \r\nSe um ou mais cards forem enviados da sua mão para o Cemitério, enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode banir este card; Invoque por Invocação-Especial 1 monstro "Mitológico(a)" da sua mão. \r\nVocê só pode usar cada efeito de "Behilmoth, o Mitológico" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial como uma Invocação Sincro','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68928540,'Kamakiriman','Um louva-a-deus com forma humana, com duas foices afiadas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68933343,'Guerreiro Sinfônico Baixxos',replace(replace('Uma vez por turno: você pode escolher 1 monstro "Guerreiro Sinfônico" no campo; até o final deste turno, aumente seu Nível pelo número de cards na sua mão. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 monstro "Guerreiro Sinfônico" que você controla; até o final deste turno, aumente o Nível do alvo pelo número de cards na sua mão.','\r',char(13)),'\n',char(10)),'Aumentar o Nível','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68934651,'Dragão Firewall Fluido Negro',replace(replace('3+ Monstros de Efeito	\r\nSe este card for Invocado por Invocação-Link: você pode colocar marcadores neste card igual ao número de tipos diferentes de monstros Ciberso no seu Cemitério (Ritual, Fusão, Sincro, Xyz). \r\nEste card ganha 2500 de ATK para cada marcador nele, apenas durante a Fase de Batalha. \r\nQuando seu oponente ativar um efeito de monstro (Efeito Rápido): você pode remover 1 marcador deste card; negue a ativação e, além disso, se este efeito foi ativado entre a declaração de ataque deste card e o final da Etapa de Dano, este card pode realizar outro ataque em sequência.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68937720,'Drenar Mente',replace(replace('Ative este card ao pagar 1000 PV. \r\nNenhum duelista pode ativar os efeitos de monstros na mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68941332,'Crosta Rikka',replace(replace('Escolha 1 monstro com a face para cima que seu oponente controla e, além disso, você pode oferecer 1 monstro Planta como Tributo; duelistas não podem ativar os efeitos desse monstro com a face para cima no campo neste turno e, depois, se você ofereceu um monstro como Tributo quando ativou este card, tome o controle desse monstro até a Fase Final e, se isso acontecer, ele se torna um monstro Planta até a Fase Final. \r\nVocê só pode ativar 1 "Crosta Rikka" por turno.','\r',char(13)),'\n',char(10)),'Ativar sem oferecer um monstro como Tributo','Oferecer um monstro como Tributo para ativar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68950538,'Inseto Digital Bitopeia',replace(replace('Não pode ser usado como uma Matéria Xyz para uma Invocação-Xyz, exceto para a Invocação-Xyz de monstros do Tipo Inseto. \r\nUma vez por turno, quando este card com a face para cima for mudado de Posição de Ataque para Posição de Defesa: você pode Invocar por Invocação-Especial 1 monstro do Tipo Inseto de Nível 3 do seu Deck, em Posição de Defesa. \r\nUm Monstro Xyz que foi Invocado usando este card no campo como Matéria Xyz ganha este efeito.\r\n● Este card pode atacar todos os monstros em Posição de Defesa que seu oponente controla uma vez cada.','\r',char(13)),'\n',char(10)),'Invocação Especial','O efeito de "Inseto Digital Bitopeia" está sendo aplicado.','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68957034,'Fogo Reluzente Rúniko',replace(replace('Ative 1 desses efeitos, mas pule sua próxima Fase de Batalha depois da ativação;\r\n● Escolha 1 monstro Invocado por Invocação-Especial que seu oponente controla; destrua-o e, depois, bana os 2 cards do topo do Deck do seu oponente.\r\n● Invoque por Invocação-Especial 1 monstro "Rúnika(o)" do seu Deck Adicional na Zona de Monstros Adicional.	\r\nVocê só pode ativar 1 "Fogo Reluzente Rúniko" por turno.','\r',char(13)),'\n',char(10)),'Destruir um monstro','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68957925,'Festa Link',replace(replace('Aplique este efeito de acordo com o número de Atributos originais diferentes dentre os Monstros Link no campo.\r\n● 1: Todos os Monstros Link que você controla ganham 500 de ATK.\r\n● 2: Todos os Monstros Link que seu oponente controla perdem 1000 de ATK.\r\n● 3: Ganhe 1500 PV.\r\n● 4: Cause 2000 de dano ao seu oponente.\r\n● 5: Invoque por Invocação-Especial 1 monstro com 2500 ou mais de ATK do seu Deck.\r\n● 6: Destrua todos os monstros que seu oponente controla com 3000 ou menos de ATK.	\r\nVocê só pode ativar 1 "Festa Link" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68963107,'Li Vroo','Um mago em forma de livro que contém em si verdadeiros tesouros mágicos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68987122,'Dragão Callibreservar',replace(replace('3+ Monstros de Efeito	\r\nNão pode ser destruído por efeitos de card. \r\nUma vez por turno: você pode enviar 1 card da sua Zona de Magias & Armadilhas para o Cemitério; Invoque por Invocação-Especial de qualquer Cemitério no seu campo, 1 monstro que foi destruído e enviado para lá neste turno, mas negue seus efeitos. \r\nUma vez por turno (Efeito Rápido): você pode escolher 1 monstro no campo; coloque-o com a face para cima em Posição de Defesa. \r\nSeu oponente não pode ativar cards ou efeitos em resposta à ativação deste efeito.','\r',char(13)),'\n',char(10)),'Invocação Especial','Mudar para Posição de Defesa com a face para cima','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68989420,'T.G. Sobredragonar',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro: você pode Invocar por Invocação-Especial qualquer número de monstros "T.G." do seu Cemitério em Posição de Defesa e, além disso, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros "T.G.". \r\nVocê só pode usar este efeito de "T.G. Sobredragonar" uma vez por turno. \r\nSe este card no campo for destruído: compre 1 card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(68989981,'Caveira Samurai',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode enviar 1 monstro Zumbi do seu Deck para o Cemitério. \r\nSe este card com a face para cima sob o controle do seu dono deixar o campo devido a um efeito de card do oponente: você pode Invocar por Invocação-Especial 1 monstro Zumbi de Nível 4 ou menos do seu Deck, exceto "Caveira Samurai".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69000994,'Avatar do Rei de Fogo Barong',replace(replace('Se um ou mais monstros "Rei(s) de Fogo" com a face para cima que você controla forem destruídos por um efeito de card (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão. \r\nUma vez por turno, durante a próxima Fase de Apoio depois que este card foi destruído por um efeito de card e enviado para o Cemitério: adicione 1 card "Rei(s) de Fogo" do seu Deck à sua mão, exceto "Avatar do Rei de Fogo Barong".','\r',char(13)),'\n',char(10)),'Invocação Especial','Procurar no Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69003792,'Megálito Não Formado',replace(replace('Ative 1 desses efeitos;\r\n● Até o final deste turno, todos os monstros que seu oponente controla perdem 500 de ATK para cada Monstro de Ritual no campo.\r\n● Invoque por Invocação-Ritual 1 Monstro de Ritual "Megálito" do seu Deck em Posição de Defesa, ao oferecer como Tributo monstros da sua mão ou do campo cuja soma dos Níveis seja exatamente igual a duas vezes o Nível dele.','\r',char(13)),'\n',char(10)),'Reduzir ATK','Invocação Ritual','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69015963,'Ciber-Stein',replace(replace('(Este card não é considerado como um card "Ciber".)	\r\nVocê pode pagar 5000 PV; Invoque por Invocação-Especial 1 Monstro de Fusão do seu Deck Adicional em Posição de Ataque.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69023354,'Ninja da Armadura de Ar','Quando este card for Invocado: você pode escolher 1 monstro "Ninja" que você controla; reduza seu Nível em 1.','Reduzir o Nível','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69025477,'Os Seis Samurai - Yariza',replace(replace('Enquanto você controlar um monstro "Seis Samurai" com a face para cima com um nome diferente, este card pode atacar diretamente seu oponente. \r\nSe este card seria destruído, em vez disso, você pode destruir outro monstro "Seis Samurai" com a face para cima que você controla.','\r',char(13)),'\n',char(10)),'Usar o efeito de substituição de destruição de "Os Seis Samurai - Yariza"?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69031175,'Mestre de Armaduras Asanegra',replace(replace('1 Regulador "Asanegra" + 1+ monstros não-Reguladores	\r\nNão pode ser destruído em batalha e você não sofre dano de batalha dos ataques envolvendo este card. \r\nNo final da Etapa de Dano, se este card atacou um monstro: você pode colocar 1 Marcador de Cunha nesse monstro (máx. 1). \r\nVocê pode remover todos os Marcadores de Cunha dos monstros do seu oponente; o ATK e a DEF dos monstros que tinham Marcadores de Cunha se tornam 0 até o final deste turno.','\r',char(13)),'\n',char(10)),'Colocar um marcador','Alterar ATK/DEF','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69035382,'Contrato com o Abismo',replace(replace('Este card pode ser usado para a Invocação-Ritual de qualquer Monstro de Ritual de TREVAS. \r\nVocê também deve oferecer como Tributo monstros da sua mão ou do campo cuja soma dos Níveis seja exatamente igual ao Nível do Monstro de Ritual que você Invocar por Invocação-Ritual.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69039982,'Renascimento Crusadia',replace(replace('Todos os Monstros Link "Crusadia" no campo ganham 500 de ATK. \r\nUma vez por turno: você pode escolher 1 Monstro Link "Crusadia" que você controla; neste turno (mesmo que este card deixe o campo), ele pode atacar todos os monstros que seu oponente controla uma vez cada e, além disso, outros monstros que você controla não podem atacar.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69042950,'Estrada do Comedor de Bugs','Cada duelista pode Invocar por Invocação-Especial 1 monstro de sua mão com o mesmo Nível de 1 monstro de Nível 4 ou menos com a face para cima que ele controla.','Invocar um monstro da mão por Invocação Especial?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69053263,'Jardim das Rosas Negras',replace(replace('Quando este card for ativado: você pode adicionar 1 monstro "Dragão da Rosa" do seu Deck ou Cemitério à sua mão. \r\nTodos os monstros com a face para cima no campo se tornam monstros Planta. \r\nSe este card for destruído: cause 100 de dano ao seu oponente para cada monstro Planta no seu Cemitério e banimento e, depois, se este card foi destruído pelo efeito de "Dragão da Rosa Negra", cause 2400 de dano ao seu oponente. \r\nVocê só pode usar este efeito de "Jardim das Rosas Negras" uma vez por turno. \r\nVocê só pode ativar 1 "Jardim das Rosas Negras" por turno.','\r',char(13)),'\n',char(10)),'Adicionar à sua mão 1 monstro "Dragão da Rosa"?','Efeito de dano','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69058960,'Número 13: Personificação do Crime',replace(replace('2 monstros de Nível 1	\r\nUma vez por turno, durante o turno de qualquer duelista: você pode desassociar 1 Matéria Xyz deste card; coloque todos os monstros que seu oponente controla com a face para cima em Posição de Ataque e, além disso, todos os monstros que seu oponente controla atualmente devem atacar este card neste turno, se possível. \r\nEnquanto você controlar "Número 31: Personificação do Castigo", este card ganha esses efeitos.\r\n● Este card não pode ser destruído em batalha ou por um efeito de card enquanto tiver Matérias Xyz.\r\n● Seu oponente sofre qualquer dano de batalha que você teria sofrido de ataques a este card.','\r',char(13)),'\n',char(10)),'Mudar para Posição de Ataque com a face para cima','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69069911,'Dragão Kachi Kochi',replace(replace('2 monstros de Nível 4	\r\nUma vez por turno, quando este card destruir um monstro do oponente em batalha e enviá-lo para o Cemitério: você pode desassociar 1 Matéria Xyz deste card; ele pode realizar um segundo ataque em seguida.','\r',char(13)),'\n',char(10)),'Continuar atacando','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69072185,'Amórfago Golias',replace(replace('Escala de Pêndulo = 5\r\n[ Efeito de Pêndulo ]\r\nEnquanto você controlar um monstro "Amórfago", qualquer card enviado para o Cemitério, em vez disso, é banido, exceto cards "Amórfago(a)". \r\nUma vez por turno, durante sua Fase de Apoio, ofereça 1 monstro como Tributo ou destrua este card.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nNenhum duelista pode Invocar monstros do Deck Adicional por Invocação-Especial, exceto monstros "Amórfago".','\r',char(13)),'\n',char(10)),'Oferecer como Tributo 1 monstro que você controla?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69073023,'Fortaleza Megaclope Infinisteira',replace(replace('3 Monstros Xyz	\r\nNão é afetado pelos efeitos de outros monstros, exceto os de Monstros Xyz. \r\nNão pode ser destruído em batalha, exceto com um Monstro Xyz. \r\nVocê pode escolher 1 Monstro Xyz no seu Cemitério e 1 card que seu oponente controla; Invoque esse monstro por Invocação-Especial do seu Cemitério e, se isso acontecer, associe esse card do oponente a ele como matéria e, além disso, pelo resto deste turno, qualquer dano que seu oponente sofrer é diminuído pela metade. \r\nVocê só pode usar este efeito de "Fortaleza Megaclope Infinisteira" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69087397,'Brisawntarilho e o Advento da Aventura',replace(replace('Bana 1 monstro Besta Alada da sua mão ou do campo com a face para cima; adicione 1 monstro "Brisawntarilho" ou Magia de Campo "Brisawntarilho" do seu Deck à sua mão e, depois, ganhe 500 PV. \r\nVocê só pode ativar 1 "Brisawntarilho e o Advento da Aventura" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69091732,'Introdução à Galanteria',replace(replace('Ative apenas quando seu oponente tiver 5 ou mais cards na mão dele. \r\nSeu oponente descarta 1 card aleatório.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69105797,'Predaplanta Lula Drosera',replace(replace('Você pode enviar este card da sua mão para o Cemitério e, depois, escolher 1 monstro com a face para cima que você controla; neste turno, ele pode atacar todos os monstros que seu oponente controla com um Marcador de Predador, uma vez cada. \r\nSe este card com a face para cima deixar o campo: coloque 1 Marcador de Predador em cada monstro Invocado por Invocação-Especial que seu oponente controla e, se isso acontecer, qualquer desses monstros que forem de Nível 2 ou mais se tornam de Nível 1 enquanto tiverem um Marcador de Predador.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69109764,'Dragão da Hibernação',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 monstro Dragão de Nível 4 ou menos no seu Cemitério; adicione-o à sua mão. \r\nEnquanto você não controlar nenhum Monstro Link, exceto no turno em que este card foi enviado para o Cemitério: você pode banir este card do seu Cemitério e, depois, escolha 1 Monstro Link Dragão de TREVAS no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Dragão da Hibernação" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69112325,'Floresta Espiritual','Na primeira vez que cada monstro Besta, Besta-Guerreira ou Planta que você controla seria destruído em batalha a cada turno, ele não é destruído.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69120785,'O Bistial Arba Los',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão ou do Cemitério) ao oferecer como Tributo 2 monstros "Bistial". \r\nEnquanto este card, Invocado desta forma, estiver na Zona de Monstros, negue os efeitos de todos os Monstros de Ritual, de Fusão, Sincro, Xyz e Link com a face para cima no campo. \r\nSe este card com a face para cima sob o controle do seu dono deixar o campo devido a um efeito de card do oponente: até a Fase Final do seu oponente, você pode banir com a face para cima todos os cards com a face para baixo nos Decks Adicionais.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69121954,'Dinolutador Terra Parkourio',replace(replace('2 monstros "Dinolutador"	\r\nSe você ativar "Mundo Dino Lutador": você pode escolher 1 monstro "Dinolutador" no seu Cemitério; adicione-o à sua mão. \r\nSe este card for enviado para o Cemitério como Matéria Link: você pode escolher 1 monstro "Dinolutador" no seu Cemitério; Invoque-o por Invocação-Especial em Posição de Defesa, mas negue seus efeitos e, além disso, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros "Dinolutador". \r\nVocê só pode usar cada efeito de "Dinolutador Terra Parkourio" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69122763,'Pacto do Fantasma',replace(replace('Selecione 1 monstro com a face para cima no campo. \r\nAumente o ATK do monstro selecionado em 100 pontos para cada monstro no seu Cemitério durante o turno em que este card foi ativado. \r\nO número de monstros é aplicado quando este card é ativado.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69123138,'Zera, o Mante','Você pode Invocar este card por Invocação-Ritual com "Ritual de Zera".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69133798,'Daidara-Bocchi',replace(replace('Não pode ser Invocado por Invocação-Especial. \r\nVocê pode Invocar este card por Invocação-Tributo com a face para cima ao oferecer como Tributo 1 monstro Zumbi. \r\nGanha 200 de ATK para cada monstro Zumbi que você controla, exceto este card. \r\nNo começo da sua Fase Principal 1, se você tiver este card e 2 ou mais monstros Zumbi que não sejam "Daidara-Bocchi" no seu Cemitério: você pode descartar 1 card; adicione este card à sua mão.','\r',char(13)),'\n',char(10)),'Ofereça 1 monstro Zumbi como Tributo para Invocá-lo por Invocação Tributo com a face para cima','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69140098,'Elfos Gêmeos','Elfos gêmeos que alternam os seus ataques.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69140099,'Elfos Gêmeos','Elfos gêmeos que alternam os seus ataques.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69145169,'Alma do Sucessor',replace(replace('Ofereça como Tributo 1 Monstro de Efeito e, depois, escolha 1 Monstro de Efeito que seu oponente controla; envie-o para o Cemitério e, depois, Invoque por Invocação-Especial 1 Monstro Normal de Nível 7 ou mais da sua mão ou do Deck. \r\nVocê só pode ativar 1 "Alma do Sucessor" por turno. \r\nVocê só pode atacar com 1 monstro durante o turno em que ativar este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69155991,'Tubarão de Restolhos',replace(replace('Quando o efeito de um Monstro de Efeito ou um Card de Magia/Armadilha for ativado, destrua este card com a face para cima no campo. \r\nSe este card for destruído pelo efeito de um card "Restolhos" e enviado para o Cemitério, você pode enviar 1 monstro "Restolhos" do seu Deck para o Cemitério.','\r',char(13)),'\n',char(10)),'Enviar para o Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69162969,'Turbilhão de Relâmpagos','Descarte 1 card; destrua todos os monstros com a face para cima que seu oponente controla.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69164989,'Glamour Rikka',replace(replace('Quando você ativar este card, você também pode oferecer 1 monstro Planta como Tributo; adicione 1 monstro "Rikka" do seu Deck à sua mão e, depois, se você ofereceu um monstro como Tributo quando ativou este card, adicione 1 monstro Planta, com o mesmo Nível original que o desse monstro "Rikka", mas um nome diferente, do seu Deck à sua mão. \r\nVocê só pode ativar 1 "Glamour Rikka" por turno.','\r',char(13)),'\n',char(10)),'Ativar sem oferecer um monstro como Tributo','Oferecer um monstro como Tributo para ativar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69167267,'Disparo Fundamental da Rosa',replace(replace('Invoque por Invocação-Especial 1 monstro "Dragão da Rosa" da sua mão ou do Cemitério em Posição de Defesa. \r\nSe este card Baixado for destruído: você pode escolher 1 dos seus "Dragão da Rosa Negra", ou 1 monstro que o mencione, que estiver banido ou no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Disparo Fundamental da Rosa" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69170403,'Carniçais Astra',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode escolher 1 monstro de Nível 4 ou menos no seu Cemitério; Invoque-o por Invocação-Especial em Posição de Defesa, mas seus efeitos são negados e, além disso, bana-o durante a Fase Final. \r\nUma vez por turno: você pode lançar um dado de seis faces e, até o final deste turno, os monstros com a face para cima que você controla atualmente se tornam do Nível do resultado.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69170557,'Número C40: Engenhoca Marionete das Cordas Negras',replace(replace('3 monstros de Nível 9	\r\nSe este card for Invocado por Invocação-Especial: destrua tantos monstros com Marcadores de Corda quanto possível e, se isso acontecer, compre 1 card e, depois, cause dano ao seu oponente igual ao maior ATK original dentre esses monstros destruídos no Cemitério (em caso de empate, você seleciona). \r\nUma vez por turno: você pode desassociar 1 matéria deste card; coloque 1 Marcador de Corda sobre cada monstro com a face para cima que seu oponente controla.','\r',char(13)),'\n',char(10)),'Destruir','Colocar um marcador','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69176131,'Ciclone Espacial','Desassocie 1 Matéria Xyz de um monstro.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69176851,'Necromante do Miasma',replace(replace('2 monstros, incluindo um monstro Mago de TREVAS	\r\nSe este card for Invocado por Invocação-Link: você pode adicionar 1 monstro Mago de TREVAS de Nível 5 ou mais do seu Cemitério à sua mão, mas você não pode ativar cards, ou os efeitos de cards, com o nome dele pelo resto deste turno. \r\nVocê pode enviar 1 Magia/Armadilha da sua mão ou do campo para o Cemitério; imediatamente depois que este efeito resolver, Invoque por Invocação-Normal 1 monstro Mago. \r\nVocê só pode usar cada efeito de "Necromante do Miasma" uma vez por turno.','\r',char(13)),'\n',char(10)),'Efeito de recuperação','Invocação Normal adicional','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69181753,'Kuribohble Camarartista',replace(replace('Quando um monstro do oponente declarar um ataque direto: você pode Invocar este card por Invocação-Especial da sua mão e, se isso acontecer, mude o alvo do ataque para este card e prossiga para o cálculo de dano. \r\nSe você sofreria dano de batalha dessa batalha, em vez disso, você ganha esse tanto de PV.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69191257,'Dragão Mech Jade',replace(replace('1 Regulador + 1+ não-Reguladores	\r\nSe este card for Invocado por Invocação-Especial: você pode enviar 1 Regulador Máquina do seu Deck para o Cemitério, ou se você controlar um monstro cujo Nível atual seja diferente do seu Nível original, em vez disso, você pode Invocá-lo por Invocação-Especial. \r\nVocê só pode usar este efeito de "Dragão Mech Jade" uma vez por turno. \r\nSe este card Invocado por Invocação-Sincro for destruído por um efeito de card e enviado para o Cemitério: você pode banir qualquer número de Reguladores do seu Cemitério e, depois, escolha esse número de cards no campo; destrua-os.','\r',char(13)),'\n',char(10)),'Enviar para o Cemitério','Destruir','Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69196160,'Queda do Trovão','Destrua todos os monstros que você controla e, se isso acontecer, cause 300 de dano ao seu oponente para cada monstro destruído.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69207766,'Vespa Inzektor',replace(replace('Uma vez por turno: você pode equipar 1 monstro "Inzektor" da sua mão ou do Cemitério a este card. \r\nEnquanto este card estiver equipado a um monstro, o Nível desse monstro aumenta em 3 e, além disso, ele ganha ATK/DEF igual ao ATK/DEF deste card. \r\nEnquanto este card estiver equipado a um monstro: você pode enviar este Card de Equipamento para o Cemitério e, depois, escolha 1 card no campo; destrua o alvo.','\r',char(13)),'\n',char(10)),'Equipar','Destrua 1 card no campo','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69211541,'Camarartista Nagarceiro',replace(replace('Escala de Pêndulo = 3\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno: você pode escolher 1 monstro com a face para cima que você controla; até o final deste turno, ele ganha 300 de ATK para cada card "Camarartista" que você controla atualmente.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 monstro que você controla; ele ganha 300 de ATK para cada monstro "Camarartista" que você controla atualmente. \r\nMonstros de Nível 5 ou menos não podem atacar.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69217334,'Quebra do Mundo',replace(replace('Uma vez por turno: você pode escolher 1 Monstro de Ritual que você controla; até o final deste turno, mostre 1 Monstro de Ritual na sua mão. \r\nAté o final deste turno, o Nível do Monstro de Ritual mostrado se torna o Nível do monstro alvo (mesmo que este card deixe o campo). \r\nUma vez por turno, se "Ruína, a Rainha do Esquecimento" ou "Demise, o Rei do Armagedom" forem Invocados por Invocação-Ritual no seu campo (exceto durante a Etapa de Dano): você pode ativar 1 desses efeitos;\r\n● Compre1 card.\r\n● Destrua 1 card no campo.','\r',char(13)),'\n',char(10)),'Compre 1 card(s)','Destrua 1 card no campo','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69228245,'Girafa Gira Corrente Camarartista',replace(replace('Escala de Pêndulo = 5\r\n[ Efeito de Pêndulo ]\r\nQuando exatamente 1 monstro que você controla (e nenhum outro card) for destruído em batalha: você pode destruir este card e, se isso acontecer, Invoque esse monstro destruído em batalha por Invocação-Especial em Posição de Ataque e, se isso acontecer, ele não pode ser destruído em batalha neste turno (mesmo que este card deixe o campo).\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nQuando este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 monstro com a face para cima que seu oponente controla; enquanto este card estiver com a face para cima no campo, esse monstro com a face para cima não pode atacar e, além disso, negue os efeitos desse monstro com a face para cima enquanto ele estiver no campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69230391,'Thestalos, o Mega Monarca',replace(replace('Você pode Invocar este card por Invocação-Tributo ao oferecer como Tributo 1 monstro Invocado por Invocação-Tributo. \r\nSe este card for Invocado por Invocação-Tributo: olhe a mão do seu oponente e descarte 1 card da mão dele e, depois, se era um monstro, cause dano ao seu oponente igual ao Nível original dele x 200. \r\nSe este card foi Invocado por Invocação-Tributo pelo Tributo de um monstro de FOGO, adicione este efeito adicional.\r\n● Além disso, depois disso, cause 1000 de dano ao seu oponente.','\r',char(13)),'\n',char(10)),'Ofereça 1 monstro Invocado por Invocação Tributo como Tributo para uma Invocação Tributo','Revelar a mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69243722,'Cavaleiro-Gema Esmeralda','Você pode banir este card com a face para cima que você controla e 1 Monstro Normal com a face para cima que você controla e, depois, escolha 1 Monstro de Fusão "Cavaleiro-Gema" no seu Cemitério; Invoque-o por Invocação-Especial.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69243953,'Punhal Borboleta - Elma',replace(replace('Um monstro equipado com este card aumenta o seu ATK em 300 pontos. \r\nQuando este card é destruído e enviado para o Cemitério enquanto equipado a um monstro, este card pode ser devolvido para a mão do seu dono.','\r',char(13)),'\n',char(10)),'Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69247929,'Lobo de Guerra Geneticamente Alterado','Este lobo de guerra recebeu força incalculável por meio de uma manipulação genética. Sua natureza gentil foi completamente anulada e ele agora só existe para causar destruição.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69248256,'Espadalma Grão-mestre - Chixiao',replace(replace('1 Regulador + 1+ monstros Wyrm não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro: você pode adicionar à sua mão ou banir 1 card "Espadalma" do seu Deck. \r\n(Efeito Rápido): você pode banir 1 card "Espadalma" ou 1 monstro Wyrm da sua mão ou do Cemitério e, depois, escolha 1 outro Monstro de Efeito no campo; negue seus efeitos até o final deste turno. \r\nVocê só pode usar 1 efeito de "Espadalma Grão-mestre - Chixiao" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69257165,'Poluente Mental','Descarte 1 monstro para escolher 1 monstro desse Nível que seu oponente controla; tome o controle do alvo até a Fase Final.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69270537,'Fora de Contato',replace(replace('Devolva 1 Monstro de Fusão "Neos" que você controla para o Deck Adicional. \r\nSe todos os Monstros-Matéria de Fusão listados nesse Monstro de Fusão estiverem no seu Deck, você pode Invocá-los por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial um conjunto de Matérias de Fusão?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69272449,'Maliss ＜P＞ Coelho Branco',replace(replace('Você não sofre dano das batalhas envolvendo Monstros Link "Maliss" que apontam para este card. \r\nVocê só pode usar cada um dos seguintes efeitos de "Maliss ＜P＞ Coelho Branco" uma vez por turno. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode Baixar 1 Armadilha "Maliss" do seu Deck com um nome diferente que o dos cards no seu Cemitério. \r\nSe este card for banido: você pode pagar 300 PV; Invoque-o por Invocação-Especial e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto Monstros Link.','\r',char(13)),'\n',char(10)),'Baixar','','Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69272450,'Maliss ＜P＞ Coelho Branco',replace(replace('Você não sofre dano das batalhas envolvendo Monstros Link "Maliss" que apontam para este card. \r\nVocê só pode usar cada um dos seguintes efeitos de "Maliss ＜P＞ Coelho Branco" uma vez por turno. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode Baixar 1 Armadilha "Maliss" do seu Deck com um nome diferente que o dos cards no seu Cemitério. \r\nSe este card for banido: você pode pagar 300 PV; Invoque-o por Invocação-Especial e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto Monstros Link.','\r',char(13)),'\n',char(10)),'Baixar','','Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69279219,'O Meu Corpo como Escudo','Quando seu oponente ativar um Card de Magia/Armadilha ou efeito de monstro que destruiria um ou mais monstros no campo: pague 1500 PV; negue a ativação e, se isso acontecer, destrua-o.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69293721,'Sirena Abisgunde',replace(replace('Se este card for descartado para o Cemitério: você pode escolher 1 monstro "Sirena" no seu Cemitério, exceto "Sirena Abisgunde"; Invoque o alvo por Invocação-Especial. \r\nVocê só pode usar este efeito de "Sirena Abisgunde" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69296555,'Espaço de Luz Reveladora',replace(replace('Declare 1 Tipo de monstro. \r\nQualquer monstro do Tipo declarado não pode declarar um ataque durante o turno em que é Invocado por Invocação-Normal, Invocação-Virar ou Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69299029,'Tesouros dos Reis',replace(replace('Quando este card for ativado: você pode Baixar 1 Armadilha "Apophis" do seu Deck. \r\nO nome deste card se torna "Templo dos Reis" enquanto ele estiver na Zona do Campo. \r\nUma vez por turno, se você tiver 2 ou mais cards Baixados no seu campo, ou uma Armadilha no seu Cemitério: você pode adicionar 1 monstro que mencione "Templo dos Reis" do seu Deck à sua mão. \r\nVocê só pode ativar 1 "Tesouros dos Reis" por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Baixar uma Card de Armadilha?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69303178,'Mecha Majestoso - Ohka',replace(replace('Você pode Invocar este card por Invocação-Normal sem oferecer Tributo. \r\nSe isso acontecer, durante a Fase Final: envie-o para o Cemitério.','\r',char(13)),'\n',char(10)),'Invocação Normal sem Tributo','Enviar para o Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69304426,'Artefato Vajra',replace(replace('Você pode Baixar este card da sua mão na sua Zona de Magias & Armadilhas como uma Magia. \r\nDurante o turno do seu oponente, se este card Baixado na Zona de Magias & Armadilhas for destruído e enviado para o seu Cemitério: Invoque-o por Invocação-Especial. \r\nSe este card for Invocado por Invocação-Especial durante o turno do seu oponente: destrua todos os cards nas suas Zonas de Magias & Armadilhas. \r\nQuando um monstro do oponente declarar um ataque direto: você pode Invocar este card por Invocação-Especial da sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69313735,'Xeque-Mate','Ofereça 1 monstro "Arquidemônio" como Tributo e, depois, escolha 1 "Rei do Terror Arquidemônio" que você controla; ele pode atacar diretamente neste turno.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69319869,'Açoite Gravitacional','Escolha 1 monstro com a face para cima no campo; até o final deste turno, ele perde ATK igual à sua DEF.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69320362,'Chave de Corda Lendária','Coloque todos os monstros "de Corda" com a face para cima que você controla com a face para baixo em Posição de Defesa.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69327790,'Raiza, a Mega Monarca',replace(replace('Você pode Invocar este card por Invocação-Tributo ao oferecer como Tributo 1 monstro Invocado por Invocação-Tributo. \r\nSe este card for Invocado por Invocação-Tributo: escolha 1 card no campo e 1 card em qualquer Cemitério e, além disso, se este card foi Invocado por Invocação-Tributo pelo Tributo de um monstro de VENTO, você pode escolher um card adicional no campo; coloque o(s) primeiro(s) alvo(s) no topo do Deck em qualquer ordem e, além disso, depois, devolva o alvo adicional (se houver) para a mão.','\r',char(13)),'\n',char(10)),'Ofereça 1 monstro Invocado por Invocação Tributo como Tributo para uma Invocação Tributo','Coloque no topo do Deck','Retornar para a mão 1 card no campo?','Coloque um card no campo no topo do Deck','Coloque 1 card do Cemitério no topo do Deck','','','','','','','','','','','');
INSERT INTO texts VALUES(69351984,'Metalmorfose Volflâmio',replace(replace('Escala de Pêndulo = 8\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno: você pode escolher 1 outro card com a face para cima que você controla; destrua-o e, se isso acontecer, Baixe 1 Magia/Armadilha "Metalmorfose" diretamente do seu Deck.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nFoguetes vermelhos ardentes como a lava impulsionam essa linda máquina, com explosões brilhantes. Destruidor dos Vorazes!','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69380702,'Baunelho','Este coelho adora doces! Ele está em busca da cenoura mais doce do mundo, e só quer mordiscar cenouras o dia todo, hoje, amanhã e depois!','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69381150,'I.A.Q',replace(replace('Ative apenas se você controlar um monstro "@Ignister". \r\nUma vez por turno, durante sua Fase de Apoio, ofereça como Tributo 1 Monstro Link ou destrua este card. \r\nCada duelista só pode Invocar um monstro por Invocação-Link uma vez por turno enquanto este card estiver com a face para cima no campo.','\r',char(13)),'\n',char(10)),'Oferecer como Tributo um Monstro Link?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69385019,'Rei Sirena - Neptabismo',replace(replace('2+ monstros, incluindo um monstro Peixe, Serpente Marinha ou Aqua	\r\nSeu oponente não pode escolher monstros de ÁGUA para os quais este card apontar como alvo de efeitos de card. \r\nVocê só pode usar cada um dos seguintes efeitos de "Rei Sirena - Neptabismo" uma vez por turno. \r\nSe um ou mais monstros de ÁGUA forem enviados para o Cemitério para ativar um card ou efeito (exceto durante a Etapa de Dano): você pode pegar 1 Magia de Equipamento "Abis-" do seu Deck ou Cemitério e adicioná-la à sua mão ou equipá-la a este card. \r\nSe este card em posse do seu dono for destruído por um card do oponente: você pode adicionar 1 monstro "Atlante" ou "Sirena" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'','Efeito de busca','Adicionar à mão','Equipar','','','','','','','','','','','','');
INSERT INTO texts VALUES(69389481,'União de Almas',replace(replace('Escolha 1 monstro com a face para cima no campo e 1 monstro "HERÓI do Elemento" no seu Cemitério; esse alvo no campo ganha ATK igual ao ATK do outro alvo (até o final deste turno) e, depois, se você tiver um Monstro Normal "HERÓI do Elemento" no seu campo ou Cemitério (exceto durante a Etapa de Dano), você pode Invocar por Invocação-Fusão 1 Monstro de Fusão "HERÓI do Elemento" do seu Deck Adicional, ao banir suas matérias do seu Cemitério. \r\nVocê só pode ativar 1 "União de Almas" por turno.','\r',char(13)),'\n',char(10)),'Ativar','Realizar uma Invocação Fusão?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69394324,'HERÓI do Destino - Domínio',replace(replace('3 monstros "HERÓI do Destino"	\r\nDurante sua Fase Principal: você pode olhar os 5 cards do topo do seu Deck ou do Deck do seu oponente e, depois, colocá-los no topo do Deck em qualquer ordem. \r\nQuando este card destruir um monstro do oponente em batalha: você pode comprar 1 card. \r\nSe este card Invocado por Invocação-Fusão for destruído em batalha ou por um efeito de card: você pode escolher 3 monstros "HERÓI do Destino" de Nível 9 ou menos com nomes diferentes no seu Cemitério; Invoque-os por Invocação-Especial. \r\nVocê só pode usar cada efeito de "HERÓI do Destino - Domínio" uma vez por turno.','\r',char(13)),'\n',char(10)),'Revele o seu Deck','Revele o Deck do seu oponente','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69402394,'Plano Obscuro','Seu oponente pode descartar 1 card para negar o efeito deste card, caso contrário, ambos os duelistas descartam 2 cards e, depois, compram 2 cards.','Descartar 1 card para negar o efeito de "Plano Obscuro"?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69408987,'Teia de Aranha',replace(replace('Se um monstro declarar um ataque, ele é colocado em Posição de Defesa no final da Etapa de Dano. \r\nEle não pode mudar sua posição de batalha até a Fase Final do próximo turno de seu controlador, enquanto este card permanecer no campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69436288,'Kraken da Condenação',replace(replace('Se "Umi" estiver no campo (Efeito Rápido): você pode escolher 1 monstro de ÁGUA que você controla, exceto "Kraken da Condenação", e 1 monstro que seu oponente controla; Invoque este card por Invocação-Especial da sua mão e, se isso acontecer, devolva esse monstro que você controla para a mão e, se isso acontecer, destrua esse monstro do oponente. \r\nQuando um monstro do oponente declarar um ataque: você pode devolver este card para a mão e, se isso acontecer, negue o ataque. \r\nVocê só pode usar cada efeito de "Kraken da Condenação" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69448290,'Pássaro-Trovão do Vale das Névoas','Se este card com a face para cima no campo for devolvido para a mão: Invoque-o por Invocação-Especial, mas ele não pode atacar neste turno.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69452756,'Pesadelo Interminável',replace(replace('Você pode pagar 1000 PV e, depois, escolha 1 Magia/Armadilha com a face para cima no campo; destrua-a. \r\nVocê só pode ativar este efeito de "Pesadelo Interminável" uma vez por Corrente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69453825,'Gouki Ogro Dragão',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro: você pode adicionar 1 Magia "Gouki" do seu Deck à sua mão. \r\nSe este card for enviado para o Cemitério: você pode escolher 1 monstro de TERRA que você controla; enquanto você controlar esse monstro com a face para cima, os monstros do seu oponente só podem escolhê-lo como alvo de ataques e, além disso, adicione 1 monstro "Gouki" com menos ATK que o desse monstro do seu Cemitério à sua mão. \r\nVocê só pode usar cada efeito de "Gouki Ogro Dragão" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Recuperar','O efeito de "Gouki Ogro Dragão" está sendo aplicado.','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69455834,'Rei de Yamimakai','Empunha o poder das trevas para destruir os seus inimigos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69456283,'Koitsu',replace(replace('Uma vez por turno, durante a sua Main Phase, você pode equipar este card a "Aitsu" como um Card de Magia de Equipamento, OU separar o Equipamento e Invocar, por Invocação-Especial, este card em Posição de Ataque com a face para cima. \r\nQuando este card é equipado pelo efeito deste card, aumente o ATK do monstro equipado em 3000 pontos, e quando ataca com um ATK superior ao DEF dum monstro em Posição de Defesa, inflija a diferença aos Life Points do seu adversário como dano de batalha. \r\n(1 monstro pode ser equipado apenas por 1 Monstro de Union de cada vez. Se o monstro equipado com este card é destruído como resultado de um combate, em vez disso destrúa este card.)','\r',char(13)),'\n',char(10)),'Equipar','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69461394,'Marechal de Campo, Aliado da Justiça',replace(replace('1 Regulador + 2+ monstros não-Reguladores	\r\nDeve ser Invocado por Invocação-Sincro. \r\nSe este card atacante destruir um monstro com a face para baixo em Posição de Defesa em batalha e enviá-lo para o Cemitério: compre 1 card.','\r',char(13)),'\n',char(10)),'Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69488544,'Gearfried Fênix',replace(replace('Este card é considerado um Monstro Normal enquanto estiver com a face para cima no campo ou no Cemitério. \r\nEnquanto este card for um Monstro Normal no campo, você pode Invocá-lo por Invocação-Normal para fazer com que ele se torne um Monstro de Efeito com este efeito.\r\n● Se seu oponente ativar um Card de Magia: você pode escolher 1 monstro Gêmeos no seu Cemitério; Invoque o alvo por Invocação-Especial.\r\n● Durante o turno de qualquer duelista, quando um Card de Magia/Armadilha que escolha como alvo um ou mais monstros no campo for ativado: você pode enviar 1 Card de Equipamento com a face para cima que você controla para o Cemitério; negue a ativação e, se isso acontecer, destrua-o.','\r',char(13)),'\n',char(10)),'Invocação Especial','Negar e destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69492187,'Espelho de Gelo','Escolha 1 monstro de ÁGUA de Nível 3 ou menos que você controla; Invoque por Invocação-Especial 1 monstro com o mesmo nome do seu Deck, mas você não pode Invocar por Invocação-Especial do Deck Adicional enquanto você controlar esse monstro com a face para cima Invocado por Invocação-Especial.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69512157,'Pêndulo Vector, o Dracosuserano',replace(replace('Escala de Pêndulo = 3\r\n[ Efeito de Pêndulo ]\r\nNegue todos os efeitos de card nas Zonas de Pêndulo do seu oponente.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nEste Suserano invadiu um mundo inteiro com seu exército de Dracodemônios, usando sua Alquimia Dragão para converter toda forma de vida em lacaios terríveis. A fonte deste poder é desconhecida e provavelmente de outra dimensão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69514125,'Cavaleiro Vingador Parshath',replace(replace('1 Regulador + 1 ou mais monstros de LUZ não-Reguladores	\r\nUma vez por turno: você pode escolher 1 monstro com a face para cima que seu oponente controla; mude a posição de batalha do alvo. \r\nSe este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente.','\r',char(13)),'\n',char(10)),'Mudar a posição de batalha','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69522668,'Demônio Magichave - Transfurlmine',replace(replace('1 Regulador "Magichave" + 1+ Monstros Normais não-Reguladores	\r\nEste card pode realizar até 2 ataques contra monstros durante cada Fase de Batalha. \r\nVocê só pode usar cada um dos seguintes efeitos de "Demônio Magichave - Transfurlmine" uma vez por turno. \r\nSe você controlar este card que foi Invocado por Invocação-Sincro usando pelo menos 2 Atributos de monstros: você pode Baixar 1 Magia/Armadilha "Magichave" diretamente do seu Deck na sua Zona de Magias & Armadilhas. \r\nSe seu oponente Invocar por Invocação-Normal ou Especial um ou mais monstros com o mesmo Atributo que um monstro no seu Cemitério (exceto durante a Etapa de Dano): você pode destruir esse(s) monstro(s).','\r',char(13)),'\n',char(10)),'','Destrua monstros com o mesmo Atributo que um monstro no seu Cemitério','As Matérias de Sincro têm 2 ou mais Atributos diferentes','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69526976,'Enterrada do Cupido',replace(replace('Não pode ser destruído em batalha com um monstro, a não ser que esse monstro tenha um Nível maior. \r\nUma vez por turno, durante sua Fase de Apoio: você pode aumentar em 1 o Nível deste card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69529337,'Triâmide Dançarina',replace(replace('Uma vez por turno: você pode escolher 1 card "Triâmide" no seu Cemitério; embaralhe-o no Deck e, se isso acontecer, todos os monstros do Tipo Rocha que você controla ganham 500 de ATK e DEF. \r\nUma vez por turno, durante o turno do seu oponente: você pode escolher 1 Card de Magia de Campo "Triâmide" na sua Zona de Campo; envie-o para o Cemitério e, se isso acontecer, ative 1 Card de Magia de Campo "Triâmide" do seu Deck com um nome diferente (este é um Efeito Rápido).','\r',char(13)),'\n',char(10)),'Alterar ATK/DEF','Ativar uma Magia de Campo','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69529567,'Sariguê Brincalhão',replace(replace('Durante sua Fase Principal: você pode destruir este card com a face para cima no campo. \r\nSeu oponente deve controlar um monstro com um ATK maior que o deste card para que você possa ativar e resolver este efeito. \r\nDurante sua Fase de Apoio, se este card foi destruído por este efeito: você pode Invocar este card por Invocação-Especial do Cemitério.','\r',char(13)),'\n',char(10)),'Destruir este card','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69533836,'Punho da Alma',replace(replace('Só pode ser equipado a um Monstro Sincro Dragão que você controla. "Dragão Vermelho Arquidemônio" equipado com este card não é afetado pelos efeitos ativados do seu oponente. \r\nUma vez por turno, durante sua Fase Principal: você pode fazer com que o ATK de todos os monstros que seu oponente controla atualmente se torne igual ao do monstro equipado. \r\nUma vez por turno, quando um ataque for declarado envolvendo o monstro equipado: você pode escolher 1 monstro no Cemitério do seu oponente; bana-o e, se isso acontecer, o monstro equipado ganha ATK igual ao desse monstro banido, até o final deste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69537999,'Acelerador de Explosão',replace(replace('Você pode escolher 1 monstro que seu oponente controla; envie 1 monstro Piro com 500 ou menos de ATK da sua mão para o Cemitério e, se isso acontecer, destrua o alvo. \r\nSeus monstros não podem atacar no turno em que ativar este efeito.','\r',char(13)),'\n',char(10)),'Destruir 1 monstro que seu oponente controla','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69540484,'Nascimento Kashtira',replace(replace('Você pode Invocar por Invocação-Normal monstros de Nível 7 sem oferecer Tributo. \r\nDurante sua Fase Principal: você pode Invocar por Invocação-Especial 1 dos seus monstros "Kashtira" que não forem Xyz que estiverem banidos ou no seu Cemitério. \r\nSe seu oponente ativar um Card de Magia ou seus efeitos e você controlar um monstro "Kashtira": você pode escolher 3 cards no Cemitério do seu oponente; bana-os, com a face para baixo. \r\nVocê só pode usar cada efeito de "Nascimento Kashtira" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar pelo efeito de "Nascimento Kashtira"','','Banir 3 cards do Cemitério do seu oponente','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69542930,'Dedicação Através da Luz e das Trevas','Ofereça como Tributo 1 "Mago Negro"; Invoque por Invocação-Especial 1 "Mago Negro do Caos" da sua mão, Deck ou Cemitério.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69550259,'Velocidaroide Block-n-Roll',replace(replace('Se este card for enviado para o Cemitério como Matéria Sincro: você pode Invocar por Invocação-Especial 1 "Ficha de Velocidaroide" (Máquina/VENTO/ATK 0/DEF 0) com um Nível igual ao Nível original do Monstro Sincro que usou este card como matéria. \r\nVocê só pode usar este efeito de "Velocidaroide Block-n-Roll" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69550260,'Ficha de Velocidaroide','Invocado por Especial com o efeito "Velocidaroide Block-n-Roll".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69553552,'F.A. Vencedores',replace(replace('Se você controlar um monstro "F.A.", este card não pode ser destruído pelos efeitos de card do seu oponente. \r\nQuando um monstro "F.A." seu, cujo Nível seja pelo menos 5 a mais que seu Nível original, batalhar um monstro do oponente e causar dano de batalha ao oponente: você pode banir 1 card da sua mão, do campo ou do Cemitério. \r\nvocê só pode ativar este efeito de "F.A. Vencedores" uma vez por turno. \r\nSe 3 das suas Magias de Campo "F.A." com nomes diferentes estiverem atualmente banidas e todas foram banidas pelo efeito de "F.A. Vencedores", você vence o Duelo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69572024,'Tongyo','Este monstro captura outros peixes com sua longa língua e suga toda a energia que tiverem.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69572169,'Flash, o HERÓI do Elemento','Quando este card for destruído em batalha e enviado ao Cemitério: Você pode banir este card e 3 Cards de Monstro "HERÓI do Elemento" com nomes diferentes do seu Cemitério para escolher 1 Card de Magia Normal no seu Cemitério; adicione o alvo à sua mão.','Recuperar uma Magia','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69579761,'Des Koala',replace(replace('(Este card deve ser sempre considerado como um card "Coala".)	\r\nVIRE: Cause 400 de dano ao seu oponente para cada card na mão dele.','\r',char(13)),'\n',char(10)),'Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69579762,'Des Koala',replace(replace('(Este card deve ser sempre considerado como um card "Coala".)	\r\nVIRE: Cause 400 de dano ao seu oponente para cada card na mão dele.','\r',char(13)),'\n',char(10)),'Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69584564,'Tempestade das Fragrâncias','Escolha 1 monstro Planta no campo; destrua o alvo e, se isso acontecer, compre 1 card e, depois, se esse card for um monstro Planta, você pode revelá-lo e comprar mais 1 card.','Revelar ao oponente o card comprado?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69599136,'Comporta Buraco Armadilha',replace(replace('Quando seu oponente Invocar um ou mais monstros: coloque esse(s) monstro(s) com a face para baixo em Posição de Defesa. \r\nMonstros colocados com a face para baixo em Posição de Defesa por este efeito não podem mudar suas posições de batalha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69601012,'Berfomet, o Rei Místico Besta Fantasma',replace(replace('2 monstros com Tipos diferentes (Besta, Demônio ou Ilusão)	\r\n(Este card não é considerado como um card "Fantasma".)	\r\nO nome deste card se torna "Quimera, a Besta Mística Voadora" enquanto estiver no campo ou no Cemitério. \r\nVocê só pode usar cada um dos seguintes efeitos de "Berfomet, o Rei Místico Besta Fantasma" uma vez por turno. \r\nSe este card for Invocado por Invocação-Fusão: você pode enviar 1 monstro Besta, Demônio ou Ilusão do seu Deck para o Cemitério. \r\nDurante o turno do seu oponente (Efeito Rápido): você pode banir este card do seu Cemitério e, depois, escolha 1 dos seus monstros Besta, Demônio ou Ilusão banidos, exceto "Berfomet, o Rei Místico Besta Fantasma"; Invoque-o por Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69610326,'Rei Supremo Dragão Wurmescuro',replace(replace('Escala de Pêndulo = 5\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno, se você não controlar nenhum monstro: você pode colocar 1 Monstro Pêndulo "Rei Supremo Portal" do seu Deck na sua Zona de Pêndulo e, além disso, você não pode Invocar monstros por Invocação-Pêndulo pelo resto deste turno, exceto monstros de TREVAS.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 Monstro Pêndulo "Rei Supremo Portal" do seu Deck à sua mão. \r\nSe este card estiver no seu Cemitério e você não controlar nenhum monstro: você pode Invocar este card por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Rei Supremo Dragão Wurmescuro" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69610924,'Número 17: Dragão Leviatã',replace(replace('2 monstros de Nível 3	\r\nNão pode atacar diretamente a não ser que tenha matéria. \r\nUma vez por turno: você pode desassociar 1 matéria deste card; ele ganha 500 de ATK.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69632396,'Goblin Fora da Frigideira',replace(replace('Pague 500 PV. \r\nNegue a ativação de um Card de Magia e o devolva à mão de seu dono.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69633792,'Evolssauro Terias','Quando este card for Invocado por Invocação-Especial pelo efeito de um monstro "Evoltil": Este card perde 500 de ATK.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69655484,'Camaramágico Criador Sombrio',replace(replace('3 monstros de Nível 5	\r\nQuando um card ou efeito for ativado que escolha este card como alvo (Efeito Rápido): você pode desassociar 1 matéria deste card; Invoque por Invocação-Especial 1 "Camaramágico Criador Sombrio" do seu Deck Adicional. \r\nVocê só pode usar cada um dos seguintes efeitos de "Camaramágico Criador Sombrio" uma vez por turno. \r\nVocê pode desassociar 1 matéria deste card e, depois, envie 1 monstro "Camaramágico" do seu Deck para o Cemitério; adicione 1 Magia "Magia de Aumento de Classe" do seu Deck à sua mão. \r\nSe a última matéria for desassociada deste card (exceto durante a Etapa de Dano): você pode Invocar por Invocação-Especial 1 monstro "Camaramágico" do seu Cemitério.','\r',char(13)),'\n',char(10)),'Adicionar "Magia de Aumento de Classe" à mão','Invocar "Camaramágico Criador Sombrio" por Invocação Especial','Invocar por Invocação Especial do Cemitério','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69669405,'Demônio Chifrudo','Um pequeno demônio que vive nas trevas, seu único chifre o torna um adversário formidável.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69678646,'Restrição Novastelar',replace(replace('Ative 1 desses efeitos, mas você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto Monstros Xyz;\r\n● Descarte 1 card e, se isso acontecer, Invoque por Invocação-Especial 1 monstro "Cavaleirost" ou "Constelar" do seu Deck com um Tipo diferente que o dos monstros que você controla.\r\n● Escolha monstros com a face para cima que seu oponente controla, até o número de monstros "Cavaleirost" e "Constelar" que você controla; negue seus efeitos até o final deste turno.	\r\nVocê só pode ativar 1 "Restrição Novastelar" por turno.','\r',char(13)),'\n',char(10)),'Ativar','Invocação Especial','Negar o efeito','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69680031,'Dogmatika Fleurdelis, a Cavaleira Nomeada',replace(replace('Durante a Fase Principal, se um monstro Invocado por Invocação-Especial do Deck Adicional estiver no campo (Efeito Rápido): você pode Invocar este card por Invocação-Especial da sua mão e, depois, se você controlar outro monstro "Dogmatika", até o final deste turno, você pode negar os efeitos de 1 monstro com a face para cima no campo. \r\nQuando um monstro "Dogmatika" seu declarar um ataque: você pode fazer com que todos os monstros "Dogmatika" que você controla atualmente ganhem 500 de ATK. \r\nVocê só pode usar cada efeito de "Dogmatika Fleurdelis, a Cavaleira Nomeada" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Negar o efeito de 1 monstro?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69680032,'Dogmatika Fleurdelis, a Cavaleira Nomeada',replace(replace('Durante a Fase Principal, se um monstro Invocado por Invocação-Especial do Deck Adicional estiver no campo (Efeito Rápido): você pode Invocar este card por Invocação-Especial da sua mão e, depois, se você controlar outro monstro "Dogmatika", até o final deste turno, você pode negar os efeitos de 1 monstro com a face para cima no campo. \r\nQuando um monstro "Dogmatika" seu declarar um ataque: você pode fazer com que todos os monstros "Dogmatika" que você controla atualmente ganhem 500 de ATK. \r\nVocê só pode usar cada efeito de "Dogmatika Fleurdelis, a Cavaleira Nomeada" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Negar o efeito de 1 monstro?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69695704,'Tempestade de Batalha',replace(replace('Este card ganha 100 de ATK para cada monstro do Tipo Besta Alada que você controla. \r\nUma vez por turno: você pode escolher 1 Card de Magia/Armadilha que seu oponente controla; destrua o alvo. \r\nVocê deve controlar 3 ou mais monstros do Tipo Besta Alada para ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Destruir Magias/Armadilhas','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69700783,'Desejo do Vampiro',replace(replace('Ative 1 desses efeitos.\r\n● Escolha 1 monstro com a face para cima que você controla; envie 1 monstro "Vampiro(a)", do seu Deck para o Cemitério, com um Nível diferente e, se isso acontecer, até o final deste turno, o monstro alvo se torna do Nível desse monstro enviado no Cemitério.\r\n● Escolha 1 monstro "Vampiro(a)" no seu Cemitério; envie 1 monstro que você controla para o Cemitério e, se isso acontecer, Invoque o monstro alvo por Invocação-Especial.	\r\nVocê só pode ativar 1 "Desejo do Vampiro" por turno.','\r',char(13)),'\n',char(10)),'Alterar o Nível','Invoque por Invocação Especial do Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69711728,'Combinação Metalmorfose',replace(replace('Uma vez por turno, se um Monstro de Fusão for Invocado por Invocação-Fusão: você pode escolher 1 monstro "Metalmorfose" no seu Cemitério de Nível menor que o desse Monstro de Fusão; Invoque-o por Invocação-Especial. \r\nSe este card for enviado do campo para o Cemitério: você pode adicionar 1 monstro "Metalmorfose" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Ativar, mas não resolver o efeito','Ativar e aplicar o primeiro Efeito','Adicionar à mão','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69718652,'Besta Espiritual Ulti-Nochiudrago',replace(replace('1 monstro "Domador da Besta Espiritual" + 1 monstro "Avatar da Besta Espiritual"	\r\nDeve ser Invocado por Invocação-Especial (do seu Deck Adicional) ao banir os cards acima do seu campo e/ou Cemitério. \r\nVocê só pode Invocar um ou mais "Besta Espiritual Ulti-Nochiudrago" por Invocação-Especial uma vez por turno. \r\nSeu oponente não pode escolher outro monstro "Besta Espiritual" que você controla como alvo de efeitos de card. \r\n(Efeito Rápido): você pode devolver este card para o Deck Adicional e, depois, escolha 1 dos seus monstros "Besta Espiritual" banidos; Invoque-o por Invocação-Especial, mas ele não pode atacar diretamente.','\r',char(13)),'\n',char(10)),'O efeito de "Besta Espiritual Ulti-Nochiudrago" está sendo aplicado.','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69723159,'Bujingi Quilin',replace(replace('Se você controlar um monstro "Bujin" do Tipo Besta-Guerreira: você pode banir este card do seu Cemitério e, depois, escolher 1 card com a face para cima que seu oponente controla; destrua o alvo. \r\nVocê só pode usar o efeito de "Bujingi Quilin" uma vez por turno.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69724380,'Péssimo Acordo',replace(replace('Ative apenas ao pagar 1000 PV quando seu oponente ativar um Card de Magia. \r\nSeu oponente descarta 1 card aleatório.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69748261,'Distorção Fazticeira',replace(replace('Quando um Card de Magia/Armadilha, ou um efeito de monstro, é ativado e você controla um monstro "Fazticeira" de Nível 5 ou maior: negue a ativação, e se fizer, destrua aquele card.\r\nSe este card está no seu Cemitério, exceto no turno em que foi enviado para lá: você pode bani-lo; adicione 1 monstro Mago de Nível 5 ou maior do seu Deck à sua mão, então descarte 1 card.\r\nVocê só pode usar cada um dos efeitos de "Distorção Fazticeira" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69750536,'Guerreiro Uau','Um peixe com braços, pernas e dentes muito afiados.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69750546,'Disparo Dispersivo Vulcânico',replace(replace('Se este card for enviado para o Cemitério: cause 500 de dano ao seu oponente. \r\nSe este card for enviado para o Cemitério pelo efeito de um card "Acelerador de Explosão": você pode enviar 2 "Disparo Dispersivo Vulcânico" da sua mão e/ou Deck para o Cemitério; destrua todos os monstros que seu oponente controla.','\r',char(13)),'\n',char(10)),'Cause 500 de dano ao seu oponente','Destrua todos os monstros que seu oponente controla','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69757518,'Número C5: Dragão Quimera do Caos',replace(replace('3+ monstros de Nível 6	\r\nGanha 1000 de ATK para cada matéria associada a ele. \r\nSe este card atacar, no final da Etapa de Dano: você pode desassociar 1 matéria deste card; este card pode atacar um monstro do oponente novamente em seguida. \r\nNo final da Fase de Batalha: você pode pagar metade dos seus PV e, depois, escolha 2 cards em quaisquer Cemitérios; coloque 1 deles no topo do Deck e, se isso acontecer, associe o outro a este card como matéria.','\r',char(13)),'\n',char(10)),'Fazer outro ataque','Escolha um card para retornar ao Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69761020,'Confronto Força-S',replace(replace('Ative 1 dos seguintes efeitos.\r\n● Invoque por Invocação-Especial 1 monstro "Força-S" da sua mão em Posição de Defesa.\r\n● Escolha 1 monstro "Força-S" no seu Cemitério; adicione-o à sua mão.	\r\nVocê só pode ativar 1 "Confronto Força-S" por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial da mão','Adicionar do Cemitério à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69764158,'Slurp Cérpero','Se você sofrer dano de batalha ou de um efeito de card do oponente enquanto este card estiver no Cemitério: você pode banir este card do Cemitério e, depois, escolha 1 card no campo; destrua-o.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69780745,'Garvas','Uma besta malvada que se parece com um leão alado.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69792699,'Espada Pinguim',replace(replace('Só pode ser equipado a um monstro "Pinguim". \r\nEle ganha 800 de ATK. \r\nQuando o monstro equipado causar dano de batalha ao seu oponente: você pode devolver 1 card que seu oponente controla para a mão. \r\nSe um card com a face para cima que seu oponente controla deixar o campo pelo efeito de um card "Pinguim" e voltar à mão ou for banido: até o final do próximo turno, negue os efeitos ativados e efeitos no campo dos cards com esse nome original. \r\nVocê só pode usar este efeito de "Espada Pinguim" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69802283,'Agrupamento de Luz',replace(replace('Você pode banir 1 monstro que você controla e 1 Monstro Sincro no seu Cemitério que seja um monstro "Ferramenteiro" ou um monstro Dragão de Nível 7 ou 8 e, depois, escolha 1 card que seu oponente controla; destrua-o. \r\nMonstros Sincro de Nível 7 ou mais que você controla ganham 400 de ATK para cada um dos seus Monstros Sincro de Nível 7 ou mais que estiverem banidos. \r\nUma vez por turno, quando um monstro do oponente declarar um ataque enquanto você tiver um Monstro Sincro banido: você pode negar o ataque.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69809989,'Disparo Fantardil',replace(replace('Invoque por Invocação-Especial 1 monstro "Fantardil" da sua mão ou do Cemitério e, depois, você pode colocar 1 monstro "Fantardil" com a face para baixo que você controla, com a face para cima em Posição de Ataque. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 Monstro Xyz "Fantardil" que você controla; associe 1 card "Fantardil" do seu Cemitério a esse monstro como matéria. \r\nVocê só pode usar cada efeito de "Disparo Fantardil" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Associar Matéria Xyz','Mudar um monstro para Posição de Ataque com a face para cima?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69811710,'Girsu, o Mekk-Cavaleiro Orcust',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode enviar 1 card "Orcust" ou "Legado Mundial" do seu Deck para o Cemitério e, depois, se houver 2 ou mais outros cards na coluna deste card, considere este card como um Regulador neste turno. \r\nSe você não controlar nenhum outro monstro: você pode Invocar por Invocação-Especial 1 "Ficha de Legado Mundial" (Máquina/TREVAS/Nível 1/ATK 0/DEF 0) no campo dos dois duelistas em Posição de Defesa. \r\nVocê só pode usar cada efeito de "Girsu, o Mekk-Cavaleiro Orcust" uma vez por turno.','\r',char(13)),'\n',char(10)),'Enviar para o Cemitério','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69811711,'Ficha de Legado Mundial','Invocado por Especial com o efeito ''Legado Mundial - "Lança Mundial"'' ou um card relacionado.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69815951,'Drytron Meteonis Draconids',replace(replace('Você pode Invocar este card por Invocação-Ritual com "Drytron Meteonis". \r\nSeu oponente não pode escolher este card como alvo de efeitos de monstro. \r\nSe a soma dos Níveis dos monstros usados para sua Invocação-Ritual for 2 ou menos, este card pode atacar todos os monstros Invocados por Invocação-Especial que seu oponente controla uma vez cada. \r\nDurante o turno do seu oponente (Efeito Rápido): você pode banir monstros do seu Cemitério cujo ATK combinado seja exatamente igual a 2000 ou 4000 e, depois, escolha 1 card com a face para cima que seu oponente controla para cada 2000 de ATK desse total; envie esse(s) card(s) para o Cemitério. \r\nVocê só pode usar este efeito de "Drytron Meteonis Draconids" uma vez por turno.','\r',char(13)),'\n',char(10)),'','A soma dos Níveis dos monstros usados para a Invocação Ritual é 2 ou menos','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69831560,'Força Arcana EX - O Senhor das Trevas',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao enviar 3 monstros que você controla para o Cemitério e não pode ser Invocado por Invocação-Especial de nenhuma outra forma. \r\nQuando este card for Invocado por Invocação-Especial: jogue uma moeda e ganhe o efeito apropriado.\r\n● Cara: Este card pode realizar um segundo ataque durante cada Fase de Batalha, mas se ele fizer isso por meio deste efeito, mude-o para Posição de Defesa no final da Fase de Batalha.	\r\nSua Posição de Batalha não pode ser mudada até o final do seu próximo turno.\r\n● Coroa: Se este card for destruído, destrua todos os cards no campo.','\r',char(13)),'\n',char(10)),'Jogar uma moeda','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69832741,'Eliminação Espiritual',replace(replace('Quando monstros no Cemitério forem banidos, em vez disso, bana monstros do seu lado do campo como substitutos. \r\nEste card permanece ativado até o final do turno em que foi ativado. \r\nOs substitutos permanecem banidos.','\r',char(13)),'\n',char(10)),'Escolha o monstro para ser banido no lugar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69838592,'Yosenju Oyam',replace(replace('Quando um monstro do oponente declarar um ataque direto: você pode enviar 1 monstro "Yosenju" da sua mão para o Cemitério, exceto "Yosenju Oyam"; Invoque este card por Invocação-Especial da sua mão. \r\nVocê só pode usar este efeito de "Yosenju Oyam" uma vez por turno. \r\nNo começo da Etapa de Dano, se este card batalhar um monstro com a face para cima do oponente: até o final deste turno, você pode fazer com que o ATK e DEF deste card se tornem iguais ao ATK original do monstro do oponente que ele estiver batalhando. \r\nQuando este card for destruído em batalha e enviado para o Cemitério: você pode adicionar 1 card "Yosenju" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Invocação Especial','Alterar ATK/DEF','Adicione 1 card "Yosenju" do seu Deck à sua mão','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69838761,'Triturador de Metal Autômato',replace(replace('Se você não controlar nenhum card com a face para cima, você pode Invocar este card por Invocação-Normal sem oferecer Tributo, mas seu ATK original se torna 1800. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode revelar 3 monstros Máquina de TERRA do seu Deck e, depois, seu oponente adiciona 1 deles aleatoriamente à sua mão e você embaralha o resto de volta no seu Deck. \r\nVocê só pode usar este efeito de "Triturador de Metal Autômato" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Normal sem Tributo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69840739,'Artefato Durindana',replace(replace('2 monstros de Nível 5	\r\nUma vez por turno (Efeito Rápido): você pode ativar 1 desses efeitos;\r\n● Quando um efeito de monstro for ativado no campo ou um Card de Magia/Armadilha Normal for ativado: você pode desassociar 1 matéria deste card; o efeito ativado se torna "Destrua 1 Magia/Armadilha que seu oponente controla".\r\n● Você pode desassociar 1 matéria deste card; cada duelista com uma mão embaralha toda sua mão no Deck e, depois, compra o mesmo número de cards embaralhados no Deck.','\r',char(13)),'\n',char(10)),'Efeito de alterar','Interferência na mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69846323,'Moreia Perfurante',replace(replace('Uma vez por turno: você pode oferecer como Tributo 1 outro monstro Peixe, Serpente Marinha ou Aqua; este card ganha 600 de ATK. \r\nSe este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69852487,'Astraltópico',replace(replace('Se um ou mais Monstros Xyz estiverem no campo: você pode Invocar este card por Invocação-Especial da sua mão. \r\nVocê pode enviar 1 outro card da sua mão ou do campo para o Cemitério; adicione 1 Magia/Armadilha "Xyz", "Onomat", "Zexal" ou "Número" do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "Astraltópico" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69865139,'Luz Guia','Quando este card for Invocado por Invocação-Normal: você pode escolher 1 monstro de LUZ de Nível 1 no seu Cemitério; Invoque o alvo por Invocação-Especial.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69868555,'Ruínas dos Divinos Senhores Dragão',replace(replace('Se um ou mais monstros forem Invocados por Invocação-Especial, exceto do Cemitério, enquanto você controlar um monstro Dragão de Nível 7 ou 8: até o final deste turno, negue os efeitos desse(s) monstro(s) com a face para cima Invocado(s) por Invocação-Especial (mesmo que este card deixe o campo). \r\nUma vez por turno: você pode enviar 1 outro card com a face para cima que você controla para o Cemitério; Invoque por Invocação-Especial 1 "Ficha de Senhor Dragão" (Dragão/LUZ/Nível 1/ATK 0/DEF 0). \r\nSe este card estiver no seu Cemitério: você pode enviar para o Cemitério 1 monstro Dragão de Nível 7 ou 8 da sua mão ou do campo com a face para cima; adicione este card à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69868556,'Ficha de Senhor Dragão','Invocado por Especial com o efeito "Ruínas dos Divinos Senhores Dragão".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69873498,'Romper o Selo',replace(replace('Você pode ativar 1 desses efeitos;\r\n● Coloque 1 "Romper o Selo" do seu Deck ou Cemitério, com a face para cima no seu campo.\r\n● Envie 2 "Romper o Selo" com a face para cima que você controla para o Cemitério, incluindo este card; adicione 1 monstro "O Proibido" do seu Deck à sua mão.	\r\nSe este card no campo for destruído: você pode revelar até 5 monstros "O Proibido" na sua mão; devolva esse número de cards que seu oponente controla para a mão. \r\nVocê só pode usar cada efeito de "Romper o Selo" uma vez por turno.','\r',char(13)),'\n',char(10)),'Coloque um card com o mesmo nome com a face para cima','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69884162,'Neos Alius, o HERÓI do Elemento',replace(replace('Este card é considerado como um Monstro Normal enquanto estiver com a face para cima no campo ou no Cemitério. \r\nEnquanto este card for um Monstro Normal no campo, você pode Invocá-lo por Invocação-Normal para fazer com que ele se torne um Monstro de Efeito com este efeito.\r\n● O nome deste card se torna "Neos, o HERÓI do Elemento" enquanto estiver no campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69890967,'Raviel, o Senhor dos Fantasmas',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao oferecer como Tributo 3 monstros Demônio. \r\nSempre que seu oponente Invocar um monstro por Invocação-Normal: Invoque por Invocação-Especial 1 "Ficha de Fantasma" (Demônio/TREVAS/Nível 1/ATK 1000/DEF 1000), mas ela não pode declarar um ataque. \r\nUma vez por turno: você pode oferecer 1 monstro como Tributo; até o final deste turno, este card ganha ATK igual ao ATK original do monstro oferecido como Tributo.','\r',char(13)),'\n',char(10)),'Invocar uma Ficha por Invocação Especial','Aumentar ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69890968,'Ficha de Fantasma','Invocado por Especial com o efeito "Raviel, o Senhor dos Fantasmas". Esta Ficha não pode declarar um ataque.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69893315,'Tatu-Dado','Um monstro tatu que se enrola em uma forma semelhante a de um dado.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69895264,'Preparação de Labrinto',replace(replace('Escolha 2 das suas Magias/Armadilhas "Labrinto" que estiverem banidas ou no seu Cemitério, exceto "Preparação de Labrinto"; embaralhe-as no Deck e, depois, se você controlar um monstro Demônio, você pode Baixar Armadilhas Normais que não sejam "Labrinto" com nomes diferentes diretamente do seu Deck igual ao número embaralhado. \r\nVocê só pode ativar 1 "Preparação de Labrinto" por turno.','\r',char(13)),'\n',char(10)),'Baixar o card selecionado?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69925461,'Tanque de Brinquedo',replace(replace('Você pode Baixar este card da sua mão na sua Zona de Magias & Armadilhas como uma Magia. \r\nVocê só pode usar cada um dos seguintes efeitos de "Tanque de Brinquedo" uma vez por turno. \r\nSe este card Baixado na Zona de Magias & Armadilhas for enviado para o Cemitério: você pode Invocar este card por Invocação-Especial. \r\nVocê pode oferecer este monstro como Tributo; Invoque por Invocação-Especial 1 monstro de Nível 6 ou menos da sua mão, ou, se você controlar "Caixa de Brinquedos", em vez disso, você pode Invocar por Invocação-Especial 1 monstro de Nível 6 ou menos do seu Cemitério, exceto "Tanque de Brinquedo".','\r',char(13)),'\n',char(10)),'Invoque por Invocação Especial da sua mão ou do seu Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69931927,'Imortal Terrestre Chacu Challhua',replace(replace('Só pode haver 1 monstro "Imortal Terrestre" no campo. \r\nSe não houver Magias de Campo com a face para cima no campo, destrua este card. \r\nOs monstros do seu oponente não podem escolher este card como alvo de ataques. \r\nEste card pode atacar diretamente seu oponente. \r\nUma vez por turno: você pode causar dano ao seu oponente igual à metade da DEF deste card no campo. \r\nEste card não pode atacar no turno em que este efeito for ativado. \r\nEnquanto este card estiver em Posição de Defesa, seu oponente não pode conduzir a Fase de Batalha dele.','\r',char(13)),'\n',char(10)),'Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69932023,'Chifre Caudraco',replace(replace('Escolha 1 monstro em Posição de Ataque no campo; devolva-o para a mão/o Deck Adicional e, depois, você pode colocar 1 card "Caudraco" do seu Cemitério ou banimento no fundo do Deck, exceto "Chifre Caudraco" e, depois, compre 1 card. \r\nVocê só pode ativar 1 "Chifre Caudraco" por turno.','\r',char(13)),'\n',char(10)),'','Recuperar e comprar 1 card?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69933858,'Gilford, a Lenda',replace(replace('Não pode ser Invocado por Invocação-Especial. \r\nQuando este card for Invocado por Invocação-Normal: você pode equipar tantos Cards de Magia de Equipamento quanto forem possível do seu Cemitério a um ou mais monstros do Tipo Guerreiro que você controla.','\r',char(13)),'\n',char(10)),'Equipar','Escolha uma Magia de Equipamento','Escolha o monstro para equipar','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69937550,'Fera Cristalina Mamute Âmbar',replace(replace('Quando outro monstro "Fera Cristalina" que você controla for escolhido como alvo de um ataque: você pode mudar o alvo do ataque para este card. \r\nSe este card com a face para cima for destruído em uma Zona de Monstros, em vez de enviá-lo para o Cemitério, você pode colocá-lo com a face para cima na sua Zona de Magias & Armadilhas como uma Magia Contínua.','\r',char(13)),'\n',char(10)),'Colocar na Zona de Magias & Armadilhas quando for destruído','Redirecionar o alvo do ataque','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69946549,'Predaplanta Dragostapelia',replace(replace('1 Monstro de Fusão + 1 monstro de TREVAS	\r\nUma vez por turno (Efeito Rápido): você pode escolher 1 monstro com a face para cima que seu oponente controla; coloque 1 Marcador de Predador nele e se ele for de Nível 2 ou mais, ele se torna de Nível 1 enquanto tiver um Marcador de Predador. \r\nNegue os efeitos ativados dos monstros do seu oponente que tiverem Marcadores de Predador.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69954399,'Ekibyo Drakmord',replace(replace('Um monstro equipado com este card não pode atacar. \r\nDestrua o monstro equipado no final do 2º turno do jogador que controla o monstro. \r\nNessa altura, este card é devolvido para a mão do seu dono.','\r',char(13)),'\n',char(10)),'Destruir','Retornar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69964858,'Pupilas de Fazticeira',replace(replace('1 monstro "Fazticeira" + 1 monstro Mago	\r\nDurante a Fase Principal ou de Batalha (Efeito Rápido): você pode ativar 1 desses efeitos;\r\n● Adicione 1 Magia "Fazticeira" do seu Deck à sua mão.\r\n● Revele 1 Magia Normal "Fazticeira" ou Magia de Efeito Rápido na sua mão; aplique o efeito de ativação daquela Magia.	\r\nDurante sua Fase Final: você pode retornar 1 dos seus cards "Fazticeira" banidos para o Cemitério.\r\nVocê só pode usar cada efeito de "Pupilas de Fazticeira" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar','Retornar para o Cemitério','Efeito de busca','Copiar efeito','','','','','','','','','','','','');
INSERT INTO texts VALUES(69973414,'Asanegra - Sombra Gêmea',replace(replace('Embaralhe no Deck/Deck Adicional 2 dos seus monstros "Asanegra" (1 Regulador e 1 não-Regulador) que estiverem banidos e/ou no seu Cemitério; Invoque por Invocação-Especial 1 Monstro Sincro "Asanegra" ou "Dragão de Asas Negras" do seu Deck Adicional cujo Nível seja igual à soma dos Níveis desses 2 monstros. \r\n(Isso é considerado uma Invocação-Sincro.) \r\nSe você controlar 2 ou mais monstros "Asanegra", você pode ativar este card da sua mão. \r\nVocê só pode ativar 1 "Asanegra - Sombra Gêmea" por turno.','\r',char(13)),'\n',char(10)),'Ativar aplicando o efeito de "Asanegra - Sombra Gêmea".','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69975751,'Bisarma Dragunidade',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode escolher 1 monstro Dragão ou Besta Alada de VENTO de Nível 4 ou menos no seu Cemitério; Invoque-o por Invocação-Especial, mas negue seus efeitos. \r\nEnquanto este card estiver equipado a um monstro: você pode Invocar este card equipado por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Bisarma Dragunidade" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69982329,'Mudança de Pêndulo','Escolha 1 card na Zona de Pêndulo de qualquer duelista e declare uma Escala de Pêndulo de 1 a 10; neste turno, esse card se torna dessa Escala de Pêndulo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(69992868,'Musa-A','Uma fada das artes que é imbatível na harpa.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70000776,'Templos Ocultos de Necro-Vale',replace(replace('Ative apenas se tanto um monstro "do Coveiro" quanto "Necro-Vale" estiverem no campo. \r\nNenhum duelista pode Invocar monstros por Invocação-Especial, exceto monstros "do Coveiro". \r\nSe um monstro "do Coveiro" ou "Necro-Vale" não estiverem no campo, destrua este card.','\r',char(13)),'\n',char(10)),'Usar o efeito de "Domínio Xyz"?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70026064,'Bujin Hiruko',replace(replace('Escala de Pêndulo = 3\r\n[ Efeito de Pêndulo ]\r\nVocê pode banir este card na sua Zona de Pêndulo e, depois, escolher 1 Monstro Xyz "Bujin" que você controla; Invoque por Invocação-Especial do seu Deck Adicional, 1 Monstro Xyz "Bujin" com um nome diferente, usando o alvo como uma Matéria Xyz. (Esta Invocação-Especial é considerada uma Invocação-Xyz. Matérias Xyz associadas a ele também se tornam Matérias Xyz no monstro Invocado.)\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nAprisionado após um confronto com "Bujin Hirume" sobre o Trono Celeste, este mestre maquinador escapou ao manipular Hirume e criou o sinistro "Bujinki Amaterasu". Ele posteriormente quase inundou o mundo em trevas, mas foi finalmente derrotado por Yamato e seus aliados.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70043345,'U.A. Sala de Punição',replace(replace('No começo da Etapa de Dano, se um monstro "U.A." seu batalhar um monstro do oponente: você pode banir esse monstro do oponente até a 2ª Fase Final do seu oponente. \r\nVocê só pode usar este efeito de "U.A. Sala de Punição" uma vez por turno. \r\nVocê pode banir este card do seu Cemitério; adicione 1 Card de Magia "U.A." do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Retornar o monstro banido ao campo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70046172,'Impulso Precipitado','Escolha 1 monstro como a face para cima no campo; ele ganha 700 de ATK até o final deste turno.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70050374,'Dragão de Cano Duplo','Se este card for Invocado: escolha 1 card que seu oponente controla; lance uma moeda duas vezes e, se o resultado for 2 caras, destrua-o.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70054514,'Boia do Mar Sombrio','Quando este card no campo for destruído por um efeito de card e enviado ao Cemitério, o dono deste card compra 1 card.','Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70058649,'Operações Soirée da Companhia de Palhaços',replace(replace('Ative 1 desses efeitos (mas você só pode usar cada um desses efeitos de "Operações Soirée da Companhia de Palhaços" uma vez por turno e, além disso, até o final do próximo turno depois que este card resolver, você não pode ativar os efeitos de monstros Invocados por Invocação-Especial do Deck ou Deck Adicional);\r\n● Invoque por Invocação-Especial até 2 monstros "Companhia de Palhaços" do seu Deck e/ou Deck Adicional, ignorando suas condições de Invocação.\r\n● Adicione 1 monstro "Companhia de Palhaços" do seu Deck à sua mão.	\r\nDurante a Fase Principal: você pode banir este card do seu Cemitério; imediatamente depois que este efeito resolver, Invoque por Invocação-Tributo 1 monstro "Companhia de Palhaços" com a face para cima.','\r',char(13)),'\n',char(10)),'Escolher um efeito','Invocação Tributo','Invocação Especial','Adicionar à mão','','','','','','','','','','','','');
INSERT INTO texts VALUES(70070211,'Surpresa Nashiwari Joruri-P.U.N.K.',replace(replace('Escolha 1 card Baixado que seu oponente controla ou, se você controlar um monstro "P.U.N.K.", em vez disso, você pode escolher 1 card com a face para cima que seu oponente controla; destrua-o. \r\nVocê só pode ativar 1 "Surpresa Nashiwari Joruri-P.U.N.K." por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70074904,'Assaltante D.D.','Depois do cálculo de dano, quando este card for destruído em uma batalha com um monstro do oponente: bana esse monstro e, além disso, bana este card.','Banir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70083592,'Sutura do Renascimento',replace(replace('Escolha 1 monstro "Fofanimal" ou "Peladura" no seu Cemitério; Invoque-o por Invocação-Especial, mas seus efeitos são negados. \r\nVocê só pode ativar 1 "Sutura do Renascimento" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70083723,'Libélula de Naturia',replace(replace('Não pode ser destruído em batalha com um monstro que tenha 2000 ou mais de ATK. \r\nGanha 200 de ATK para cada monstro "Naturia" no seu Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70084224,'Caçador de Cabeças','Um demônio que leva uma foice e dispara raios devastadores dos seus olhos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70088809,'Harmonia Fydraulis',replace(replace('Quando um monstro que seu oponente controla ativar seu efeito (Efeito Rápido): você pode revelar este card na sua mão e até 5 Monstros Sincro no seu Deck Adicional; aplique todos esses efeitos em sequência, de acordo com o número revelado e, além disso, você não pode ativar os efeitos de monstros Invocados por Invocação-Especial do Deck Adicional até o final do seu próximo turno depois que este efeito resolver, exceto Monstros Sincro.\r\n● 2+: Invoque este card por Invocação-Especial.\r\n● 4+: Envie 1 Monstro Sincro revelado para o Cemitério.\r\n● 6: Destrua 1 monstro que seu oponente controla.	\r\nVocê só pode usar este efeito de "Harmonia Fydraulis" uma vez por turno.','\r',char(13)),'\n',char(10)),'Revele o Deck Adicional e ative o efeito','Revelado por "Harmonia Fydraulis"','O efeito de "Harmonia Fydraulis" está sendo aplicado.','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70089580,'Asa Aurora',replace(replace('Quando este card for destruído em batalha e enviado para o Cemitério: você pode Invocar este card por Invocação-Especial com a face para cima em Posição de Ataque. \r\nVocê só pode usar o efeito de "Asa Aurora" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70095046,'Cavaleiro Cruel Translúcido',replace(replace('Você pode Invocar este card por Invocação-Tributo ao oferecer como Tributo 1 monstro que mencione "Mundo Translúcido". \r\nGanha ATK igual ao maior ATK original dentre os monstros que seu oponente controla (em caso de empate, você seleciona). \r\nVocê não é afetado pelos efeitos de "Mundo Translúcido". \r\nEnquanto este card Invocado por Invocação-Tributo estiver na Zona de Monstros, seu oponente não pode ativar os efeitos de monstros Invocados por Invocação-Especial no campo com menos ATK que este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70095154,'Dragão Cibernético','Se somente seu oponente controlar um monstro, você pode Invocar este card por Invocação-Especial (da sua mão).','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70095155,'Dragão Cibernético','Se somente seu oponente controlar um monstro, você pode Invocar este card por Invocação-Especial (da sua mão).','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70101178,'Tubarão Pantera',replace(replace('Se seu oponente controlar 2 ou mais monstros, você pode Invocar este card por Invocação-Normal sem oferecer Tributo. \r\nSe você controlar "Tubarão Águia", você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode controlar 1 "Tubarão Pantera".','\r',char(13)),'\n',char(10)),'Invocar sem oferecer Tributo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70105073,'Ritual do Matador',replace(replace('Este card pode ser usado para Invocar "Arquidemônio Matador" por Invocação-Ritual. \r\nVocê também deve oferecer como Tributo monstros da sua mão ou do campo cuja soma dos Níveis seja igual a 6 ou mais. \r\nVocê pode banir este card do seu Cemitério; Invoque por Invocação-Especial 1 monstro "Arquidemônio" que não seja de Ritual da sua mão. \r\nVocê só pode usar este efeito de "Ritual do Matador" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Invocar por Invocação Especial da mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70109009,'Imortal Terrestre Definitivo',replace(replace('Se um monstro "Imortal Terrestre" Invocado por Invocação-Normal/Baixado estiver no campo: você pode escolher 1 monstro com a face para cima no campo; destrua-o. \r\nVocê só pode usar este efeito de "Imortal Terrestre Definitivo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70117791,'Besta Ardente do Bombardeio',replace(replace('1 monstro Máquina + 1 monstro Piro	\r\nSe este card for Invocado por Invocação-Especial: você pode destruir todos os monstros que seu oponente controla com 1900 ou menos de ATK. \r\nSe este card for enviado para o Cemitério: você pode escolher 1 monstro que seu oponente controla com 1900 ou menos de ATK; destrua esse monstro e, se isso acontecer, cause dano ao seu oponente igual ao ATK original dele. \r\nVocê só pode usar cada efeito de "Besta Ardente do Bombardeio" uma vez por turno.','\r',char(13)),'\n',char(10)),'Destruir um monstro','Destruir o card selecionado','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70117860,'Ventobruxa - Sino de Neve',replace(replace('Se você controlar 2 ou mais monstros de VENTO e nenhum monstro que não seja de VENTO: você pode Invocar este card por Invocação-Especial da sua mão. \r\nUm Monstro Sincro de VENTO que foi Invocado usando este card como Matéria Sincro não pode ser destruído pelos efeitos de card do seu oponente.','\r',char(13)),'\n',char(10)),'Invocação Especial','O efeito de "Ventobruxa - Sino de Neve" está sendo aplicado.','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70122149,'Domínio de Olho Maligno - Pareidolia',replace(replace('Quando este card for ativado: você pode adicionar 1 monstro "Olho Maligno" do seu Deck à sua mão. \r\nUma vez por turno, durante o cálculo de dano, se um monstro "Olho Maligno" seu for atacado, enquanto "Olho Maligno de Selene" estiver na sua Zona de Magias & Armadilhas: você pode fazer com que o dano de batalha que você sofrer dessa batalha também seja causado ao seu oponente. \r\nSe este card na Zona do Campo for destruído por um efeito de card: você pode escolher 1 monstro "Olho Maligno" no seu Cemitério; adicione-o à sua mão. \r\nVocê só pode ativar 1 "Domínio de Olho Maligno - Pareidolia" por turno.','\r',char(13)),'\n',char(10)),'Adicionar à sua mão 1 monstro "Olho Maligno"?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70124586,'Algemas de Pernas',replace(replace('Se este card for Invocado: devolva todas as Magias/Armadilhas Baixadas no campo para a mão. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 Magia/Armadilha Baixada que seu oponente controla; ela não pode ser ativada até o final do próximo turno.','\r',char(13)),'\n',char(10)),'Retornar para a mão','Não pode ativar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70138455,'Malabarista Explosivo','Ofereça este card com a face para cima como Tributo durante a sua Standby Phase, para destruir 2 monstros com a face para cima com um ATK de 1000 pontos ou menos.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70147689,'Fortaleza do Mecanismo Antigo',replace(replace('Durante o turno em que eles foram Invocados por Invocação-Normal ou Especial, seu oponente não pode escolher monstros "Mecanismo Antigo" que você controla como alvo de efeitos de card e eles não podem ser destruídos por efeitos de card do seu oponente. \r\nSeu oponente não pode ativar cards ou efeitos em resposta à ativação de cards e efeitos "Mecanismo Antigo". \r\nSe este card for destruído na Zona de Magias & Armadilhas: você pode Invocar por Invocação-Especial 1 monstro "Mecanismo Antigo" da sua mão ou do Cemitério e, além disso, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros "Mecanismo Antigo".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70155677,'Nemleria Sonhadora',replace(replace('Escala de Pêndulo = 8\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno, durante sua Fase Principal: você pode colocar 1 Magia Contínua "Nemleria" do seu Deck ou Cemitério com a face para cima no seu campo e, se isso acontecer, adicione este card ao seu Deck Adicional com a face para cima. \r\nVocê não pode Invocar "Nemleria Sonhadora" por Invocação-Especial no turno em que ativar este efeito.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nNão pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (com a face para cima do seu Deck Adicional) ao não ter nenhum card no seu Deck Adicional, exceto "Nemleria Sonhadora". \r\nVocê só pode Invocar um ou mais "Nemleria Sonhadora" por Invocação-Especial uma vez por turno. \r\nSe este card for Invocado por Invocação-Especial: para cada 3 dos seus cards banidos com a face para baixo, você pode banir até 1 card do campo e/ou Cemitério do seu oponente, com a face para baixo e, depois, embaralhe no seu Deck 1 dos seus cards banidos com a face para baixo para cada card que você baniu com este efeito.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70156946,'Tubarão Lanterna',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode Invocar por Invocação-Especial 1 monstro de ÁGUA de Nível 3, 4 ou 5 da sua mão, em Posição de Defesa, exceto "Tubarão Lanterna" e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto Monstros Xyz. \r\nVocê só pode usar este efeito de "Tubarão Lanterna" uma vez por turno. \r\nSe este card for usado para a Invocação-Xyz de um monstro de ÁGUA, ele pode ser considerado como um monstro de Nível 3 ou 5.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70156997,'Kurogane - Arte Espiritual da Terra','Ofereça 1 monstro de TERRA como Tributo e escolha 1 outro monstro de TERRA de Nível 4 ou menos no seu Cemitério; Invoque esse monstro de TERRA por Invocação-Especial.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70168345,'Explosão Gêmea da Magia Negra',replace(replace('Escolha 1 "Mago Negro" que você controla; até o final deste turno, ele ganha ATK igual ao ATK combinado de todos os "Pequena Maga Negra" atualmente no campo e nos Cemitérios. \r\nVocê só pode ativar 1 "Explosão Gêmea da Magia Negra" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70180284,'Seis Samurai Secretos - Doji',replace(replace('Quando outro monstro "Seis Samurai" for Invocado por Invocação-Normal ou Especial no seu campo (exceto durante a Etapa de Dano): você pode enviar 1 card "Seis Samurai" do seu Deck para o Cemitério. \r\nSe exatamente 1 monstro "Seis Samurai" que você controla (e nenhum outro card) seria destruído por um efeito de card, em vez disso, você pode banir este card do seu Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70187958,'Tapir-do-Deserto das Trevas','Quando este card for removido de jogo, você pode escolher 1 monstro do Tipo Besta de Nível 4 ou menos no seu Cemitério e Invocá-lo por Invocação-Especial.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70194827,'Rufião Lâminas','Uma vez por turno, se este card atacar e seu oponente controlar um monstro no final da Etapa de Dano: Você pode descartar 1 card; este card pode atacar um monstro do oponente mais uma vez durante esta Fase de Batalha.','Fazer outro ataque','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70204022,'Guerreiro Sinfônico DJJ',replace(replace('Escala de Pêndulo = 8\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno, durante sua Fase Principal: você pode virar com a face para cima em Posição de Defesa, 1 monstro "Guerreiro Sinfônico" com a face para baixo em Posição de Defesa que você controla. \r\nSe o efeito de um monstro "Guerreiro Sinfônico" for ativado (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua Zona de Pêndulo. \r\nVocê só pode usar este efeito de "Guerreiro Sinfônico DJJ" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode Invocar por Invocação-Especial 1 monstro "Guerreiro Sinfônico" do seu Deck com a face para baixo em Posição de Defesa, exceto "Guerreiro Sinfônico DJJ", ou, se "Sinfo Amplificardor" estiver na sua Zona do Campo, em vez disso, você pode Invocar por Invocação-Especial 1 monstro "Guerreiro Sinfônico" do seu Deck, exceto "Guerreiro Sinfônico DJJ", mas negue seus efeitos. \r\nVocê só pode usar este efeito de "Guerreiro Sinfônico DJJ" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','Invocar por Invocação Especial em Posição com a face para cima?','','','','','','','','','','','','');
INSERT INTO texts VALUES(70219023,'Coordius, o Dealmon Trifásico',replace(replace('1 Monstro Sincro + 1 Monstro Xyz + 1 Monstro Link	\r\nUma vez enquanto este card Invocado por Invocação-Fusão estiver com a face para cima no campo: você pode pagar PV em múltiplos de 2000 e selecionar 1 efeito para cada 2000 PV pagos (você só pode aplicar cada efeito uma vez e você os resolve na ordem listada, pulando quaisquer que não tenham sido selecionados);\r\n● Adicione 1 Magia/Armadilha do seu Cemitério à sua mão.\r\n● Destrua 3 cards que seu oponente controla.\r\n● Neste turno, este card ganha ATK igual à metade da diferença entre os seus PV e os do seu oponente e, além disso, seus outros monstros não podem atacar.	\r\nVocê só pode usar este efeito de "Coordius, o Dealmon Trifásico" uma vez por turno.','\r',char(13)),'\n',char(10)),'Efeito já ativado','Adicione à sua mão 1 Magia/Armadilha do seu Cemitério','Destrua 3 cards no campo do oponente','O ATK deste card aumenta','Parar de selecionar','','','','','','','','','','','');
INSERT INTO texts VALUES(70222318,'Monte Silvestrea',replace(replace('Você pode enviar para o Cemitério 1 monstro do Tipo Planta da sua mão ou com a face para cima do seu lado do campo; selecione 1 card "Silvestre" do seu Deck e coloque-o no topo do Deck. \r\nVocê só pode usar este efeito de "Monte Silvestrea" uma vez por turno. \r\nUma vez por turno, durante a Fase Final do seu oponente: você pode escavar o card do topo do seu Deck e, se ele for um monstro do Tipo Planta, envie-o para o Cemitério. \r\nCaso contrário, coloque-o no topo ou no fundo do seu Deck.','\r',char(13)),'\n',char(10)),'Escolha um card cujo nome inclua "Silvestre"','Colocar no topo do Deck','Colocar no fundo do Deck','Adicionar à mão','','','','','','','','','','','','');
INSERT INTO texts VALUES(70226289,'Revelação Fazticeira',replace(replace('Invoque por Invocação-Especial 1 monstro "Fazticeira" da sua mão e, se isso acontecer, seu oponente não pode ativar cards ou efeitos em resposta à ativação dos efeitos dos seus monstros Mago pelo resto deste turno. \r\nDurante sua Fase Final, se você controlar um monstro "Fazticeira", enquanto este card estiver no seu Cemitério: você pode adicionar este card à sua mão. \r\nVocê só pode usar 1 efeito de "Revelação Fazticeira" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70231910,'Núcleo Escuro','Descarte 1 card e, depois, escolha 1 monstro com a face para cima no campo; bana o alvo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70238111,'Recodificar Vivo',replace(replace('Escolha 1 Monstro Link Ciberso Link-3 que você controla ou no seu Cemitério; bana-o e, se isso acontecer, Invoque por Invocação-Especial 1 monstro "Codificar Transmissor" do seu Deck Adicional. \r\nSe você não controlar nenhum monstro na Zona de Monstros Adicional: você pode banir este card do seu Cemitério e, depois, escolha 1 de seus monstros "Codificar Transmissor" banidos; Invoque-o por Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70245411,'Vendedor de Brinquedos',replace(replace('Uma vez por turno: você pode descartar 1 card; compre 1 card e mostre-o e, depois, se for um monstro "Fofanimal", você pode Invocar por Invocação-Especial 1 monstro da sua mão. \r\nCaso contrário, descarte o card que você comprou. \r\nSe este card for enviado para o Cemitério: você pode adicionar 1 "Diabrete de Lâminas Afiadas" ou 1 monstro "Fofanimal" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Compre 1 card(s)','Adicione à sua mão 1 monstro do seu Deck','Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70252926,'Senhora Fortuna do Sempre',replace(replace('1 Regulador + 1+ monstros Mago não-Reguladores	\r\nO ATK/DEF deste card se tornam seu Nível x 400. \r\nUma vez por turno, durante sua Fase de Apoio: aumente em 1 o Nível deste card (máx. 12) e, depois, você pode banir 1 monstro com a face para cima que seu oponente controla. \r\nDurante a Fase Final do seu oponente, se este card estiver no seu Cemitério: você pode banir 1 outro monstro Mago no seu Cemitério; Invoque este card por Invocação-Especial. \r\nVocê só pode usar este efeito de "Senhora Fortuna do Sempre" uma vez por turno.','\r',char(13)),'\n',char(10)),'Aumentar o Nível em 1','Invocar este card por Invocação Especial','Banir um monstro do oponente?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70261145,'Tulipa de Naturia','Sempre que seu oponente ativar um Card de Magia/Armadilha, pelo resto deste turno, todos os monstros "Naturia" que você controla ganham 500 de ATK.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70271583,'Cão de guarda Karakuri mod. 313 "Saizan"',replace(replace('Este card deve atacar se possível. \r\nQuando este card com a face para cima for escolhido como alvo de um ataque, mude sua posição de batalha. \r\nQuando você sofrer Dano de Batalha de uma batalha envolvendo este card, todos os monstros "Karakuri" com a face para cima que você controla ganham 800 de ATK e DEF até a Fase Final. \r\nEnquanto este card estiver com a face para cima em Posição de Ataque, ele não pode ser destruído em batalha.','\r',char(13)),'\n',char(10)),'Alterar posição de batalha','Aumentar ATK/DEF','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70278545,'Pote da Generosidade',replace(replace('Devolva 2 cards da sua mão para o seu Deck. \r\nEm seguida, embaralhe o seu Deck.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70284332,'Plano do Regulador',replace(replace('Só pode ser ativado quando um Monstro Sincro for Invocado por Invocação-Especial no lado do campo do oponente. \r\nTome o controle desse Monstro Sincro. \r\nRemova-o de jogo quando ele for destruído. \r\nDestrua este card quando esse monstro for removido do campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70298454,'Leng Ling',replace(replace('Uma vez por turno, você pode: escolher 1 monstro com a face para cima que você controla; equipe este card ao alvo, OU: desequipe este card e Invoque-o por Invocação-Especial. \r\nO ATK original de um monstro equipado com este card se torna 1000, ele pode realizar um segundo ataque durante cada Fase de Batalha e, além disso, se o monstro equipado seria destruído em batalha ou por um efeito de card, em vez disso, destrua este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70307656,'Bolsa de Muco',replace(replace('Este card pode atacar os Life Points do seu adversário diretamente. \r\nCada vez que este card inflige dano de batalha aos Life Points do seu adversário, aumenta o ATK deste card em 1000 pontos durante a sua próxima Standby Phase. \r\nO aumento do ATK dura enquanto este card permanecer no Campo com a face para cima.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70329348,'Formação de Fogo - Tenken',replace(replace('Só pode ser ativado durante a Fase Principal 1. \r\nQuando este card for ativado: escolha 1 monstro do Tipo Besta-Guerreira que você controla; durante esta fase, seus efeitos são negados e, além disso, ele não pode ser afetado por efeitos de card de outros cards. \r\n(Isso se aplica mesmo que este card deixe o campo.) \r\nTodos os monstros do Tipo Besta-Guerreira que você controla ganham 300 de ATK.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70333910,'Dragão Notuvisão',replace(replace('Quando seu oponente ativar um card ou efeito que escolha como alvo um ou mais cards com a face para baixo que você controla (Efeito Rápido): você pode banir este card do seu Cemitério; negue o efeito e, além disso, seu oponente não pode escolher esse(s) card(s) com a face para baixo como alvo de efeitos de card pelo resto deste turno. \r\nVocê só pode usar cada um dos seguintes efeitos de "Dragão Notuvisão" uma vez por turno.\r\n● Se um ou mais monstros Dragão de TREVAS forem Invocados por Invocação-Especial no seu campo (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão.\r\n● Se este card for enviado para o Cemitério como Matéria Link: você pode comprar 1 card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70335319,'Dragão Fantasma de Olhos Plenos',replace(replace('Escala de Pêndulo = 0\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno, no final da Etapa de Dano, se um Monstro Pêndulo Dragão seu atacou um monstro do oponente: você pode ativar este efeito; ele pode atacar novamente em seguida. \r\nVocê não pode declarar ataques no turno em que ativar este efeito, exceto com esse monstro.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nNão pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão ou com a face para cima no Deck Adicional) ao oferecer como Tributo todos os monstros que você controla (mín. 2), incluindo um Monstro Pêndulo Dragão. \r\nVocê só pode Invocar "Dragão Fantasma de Olhos Plenos" por Invocação-Especial uma vez por turno desta forma. \r\nUma vez por turno, durante o cálculo de dano, se este card batalhar um monstro do oponente: dobre o ATK atual deste card até o final deste turno. \r\nUma vez por turno, quando seu oponente ativar um Card ou efeito de Magia/Armadilha (Efeito Rápido): você pode enviar 1 Magia/Armadilha que você controla para o Cemitério; negue a ativação.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70342110,'Prisão Dimensional','Quando um monstro do oponente declarar um ataque: escolha o monstro atacante; bana o alvo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70344351,'Campo Riryoku','Quando um Card de Magia que escolher como alvo exatamente 1 monstro no campo (e nenhum outro card) for ativado: negue a ativação e, se isso acontecer, destrua-o.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70345785,'Yamadron','Este monstro tem três cabeças que cospem fogo e podem criar um mar de chamas ardentes.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70355994,'Irmandade do Punho de Fogo - Gorila',replace(replace('Uma vez por turno, quando este card destruir um monstro do oponente em batalha e enviá-lo para o Cemitério: você pode Baixar 1 Magia "Formação de Fogo" diretamente do seu Deck. \r\nUma vez por turno: você pode enviar 1 Magia/Armadilha "Formação de Fogo" com a face para cima que você controla para o Cemitério e, depois, escolha 1 Magia/Armadilha no campo; destrua o alvo.','\r',char(13)),'\n',char(10)),'Baixar','Destruir Magias/Armadilhas','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70366448,'Compra Drástica',replace(replace('Bana todos os monstros que você controla (mín. 2); compre 3 cards. \r\nVocê não pode Invocar por Invocação-Normal ou Especial no turno em que ativar este card, exceto monstros Ciberso. \r\nVocê só pode ativar 1 "Compra Drástica" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70368879,'Goblin Inexperiente','Compre 1 card e, depois, seu oponente ganha 1000 PV.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70369116,'Predaplanta Anaconda Verte',replace(replace('2 Monstros de Efeito	\r\nVocê pode escolher 1 monstro com a face para cima no campo; ele se torna de TREVAS até o final deste turno. \r\nVocê pode pagar 2000 PV e enviar 1 Magia Normal ou Rápida "Fusão" ou "Polimerização" do seu Deck para o Cemitério; este efeito se torna o efeito dessa Magia quando esse card for ativado e, além disso, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno. \r\nVocê só pode usar cada efeito de "Predaplanta Anaconda Verte" uma vez por turno.','\r',char(13)),'\n',char(10)),'Alterar o Atributo','Magia de Fusão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70383419,'Baybarron, a Invokada',replace(replace('1 monstro "Aleister" + 1 monstro de LUZ ou de TERRA	\r\nSe este card for Invocado por Invocação-Especial: você pode adicionar 1 "Virakam, o Espírito Divino do Artifício" ou 1 "Invocação Gama" do seu Deck à sua mão e, depois, você pode banir 1 monstro de qualquer Cemitério. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 Monstro de Fusão que você controla; até o final deste turno, monstros que seu oponente controla atualmente perdem ATK igual ao ATK do monstro alvo. \r\nVocê só pode usar cada efeito de "Baybarron, a Invokada" uma vez por turno.','\r',char(13)),'\n',char(10)),'Efeito de busca','Altere o ATK','Banir o card?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70389815,'Divertido Bilhete do Tempo',replace(replace('Pague 800 PV; aplique este efeito, dependendo de quem é o turno.\r\n● Seu turno: Adicione 1 card "Diversão" do seu Deck à sua mão.\r\n● Turno do seu oponente: Baixe 1 Armadilha "Atração" diretamente do seu Deck.	\r\nEla pode ser ativada neste turno.\r\nVocê só pode ativar 1 "Divertido Bilhete do Tempo" por turno.','\r',char(13)),'\n',char(10)),'Ativar aplicando o efeito de "Divertido Bilhete do Tempo".','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70391588,'Sifão Estrela',replace(replace('Quando um ou mais Monstros Sincro forem Invocados por Invocação-Especial: escolha 1 deles; Invoque por Invocação-Especial 1 "Ficha Sifão" (Tipo Mago/TREVAS/Nível 1/ATK 0/DEF 0). \r\nO Nível dela se torna o Nível atual desse monstro e o Nível desse monstro se torna 1.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70391589,'Ficha Sifão','Invocado por Especial com o efeito "Sifão Estrela".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70405001,'Soldado do Lustro Negro - Soldado da Luz e das Trevas',replace(replace('Você pode Invocar este card por Invocação-Ritual com "Ritual da Luz e das Trevas". \r\nNão é afetado pelos efeitos ativados do seu oponente, a não ser que eles escolham este card como alvo e, além disso, não pode ser destruído em batalha. \r\nVocê só pode usar cada um dos seguintes efeitos de "Soldado do Lustro Negro - Soldado da Luz e das Trevas" uma vez por turno. \r\nSe este card for Invocado por Invocação-Especial: você pode escolher 1 card que seu oponente controla; bana-o. \r\nQuando este card destruir um monstro do oponente em batalha: você pode fazer com que este card ganhe 1500 de ATK e, se isso acontecer, ele pode realizar um segundo ataque em seguida.','\r',char(13)),'\n',char(10)),'Efeito de banimento','Aumentar ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70405002,'Soldado do Lustro Negro - Soldado da Luz e das Trevas',replace(replace('Você pode Invocar este card por Invocação-Ritual com "Ritual da Luz e das Trevas". \r\nNão é afetado pelos efeitos ativados do seu oponente, a não ser que eles escolham este card como alvo e, além disso, não pode ser destruído em batalha. \r\nVocê só pode usar cada um dos seguintes efeitos de "Soldado do Lustro Negro - Soldado da Luz e das Trevas" uma vez por turno. \r\nSe este card for Invocado por Invocação-Especial: você pode escolher 1 card que seu oponente controla; bana-o. \r\nQuando este card destruir um monstro do oponente em batalha: você pode fazer com que este card ganhe 1500 de ATK e, se isso acontecer, ele pode realizar um segundo ataque em seguida.','\r',char(13)),'\n',char(10)),'Efeito de banimento','Aumentar ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70406920,'Rei Máquina - 3000 A.C.',replace(replace('Invoque este card por Invocação-Especial como um Monstro de Efeito (Máquina/TERRA/Nível 4/ATK 1000/DEF 1000).	\r\n(Este card ainda é considerado uma Armadilha.) \r\nSe Invocado desta forma, uma vez por turno, durante sua Fase Principal: você pode oferecer como Tributo 1 monstro Máquina; até o final deste turno, este card ganha ATK igual ao ATK que o monstro oferecido como Tributo tinha no campo. \r\nVocê não pode Invocar outros monstros por Invocação-Normal ou Especial no turno em que ativar este card.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70410002,'O Acumulador','Ganha ATK igual ao Valor Link combinada de todos os Monstros Link no campo x 300.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70417076,'Camaramágico Escorredor do Vento',replace(replace('Escala de Pêndulo = 4\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno: você pode escolher 1 Monstro Pêndulo "Camaramágico" que você controla e, depois, ative 1 desses efeitos;\r\n● Reduza o Nível dele em 1.\r\n● Aumente a Escala de Pêndulo deste card pela desse monstro.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe seu oponente controlar um monstro, ou um monstro "Camaramágico" estiver no campo: você pode Invocar este card por Invocação-Especial da sua mão, mas enquanto ele estiver com a face para cima na Zona de Monstros, você não pode Invocar por Invocação-Especial, exceto monstros "Camaramágico". \r\nVocê só pode usar este efeito de "Camaramágico Escorredor do Vento" uma vez por turno. \r\nSe este card for Invocado por Invocação-Especial: você pode reduzir o Nível dele em 1. \r\nUma vez por turno: você pode mudar os Níveis de todos os monstros "Camaramágico" de Nível 4 que você controla para Nível 5.','\r',char(13)),'\n',char(10)),'Reduzir o Nível','Aumentar a Escala','Invocação Especial','Reduzir o Nível','Alterar o Nível','','','','','','','','','','','');
INSERT INTO texts VALUES(70422863,'Hexcavaleirostelar',replace(replace('Cada Monstro Xyz "Cavaleirost" ganha 200 de ATK e DEF para cada Matéria Xyz associada a ele. \r\nQuando um Monstro Xyz "Cavaleirost" que você controla for escolhido como alvo de um ataque: você pode enviar 1 card "Cavaleirost" da sua mão para o Cemitério; negue o ataque.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70423794,'Cordão Morfotrônico',replace(replace('Só pode ser equipado a um monstro "Morfotrônico(a)". \r\nCada vez que a posição de batalha do monstro equipado mudar, destrua 1 Card de Magia ou Armadilha no campo.','\r',char(13)),'\n',char(10)),'Destrua 1 Card de Magia ou Armadilha','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70427670,'Predaplanta Bufolicula',replace(replace('Escala de Pêndulo = 0\r\n[ Efeito de Pêndulo ]\r\nDurante sua Fase Principal: você pode Invocar por Invocação-Fusão 1 Monstro de Fusão de TREVAS do seu Deck Adicional, usando monstros da sua mão ou do campo como Matéria de Fusão. \r\nVocê só pode usar este efeito de "Predaplanta Bufolicula" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe este card for enviado para o Cemitério ou adicionado ao seu Deck Adicional com a face para cima porque foi usado como Matéria de Fusão: você pode adicionar 1 Monstro Pêndulo de TREVAS com a face para cima do seu Deck Adicional à sua mão, exceto "Predaplanta Bufolicula". \r\nVocê só pode usar este efeito de "Predaplanta Bufolicula" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70456282,'Asanegra Agressor - Kunai, o Alvejador',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) ao oferecer como Tributo 1 monstro "Asanegra". \r\nSe Invocado desta forma, este card é considerado como um monstro Regulador. \r\nUma vez por turno: você pode escolher 1 Monstro Sincro que você controla e declarar um Nível de 1 a 8; ele se torna desse Nível até o final deste turno.','\r',char(13)),'\n',char(10)),'Declarar um Nível','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70458081,'Camarartista Rinotrovão',replace(replace('Monstros que seu oponente controla não podem escolher monstros "Camarartista" com a face para cima como alvo de ataques, exceto este. \r\nSe um ou mais cards "Camarartista" que você controla, exceto "Camarartista Rinotrovão", seriam destruídos em batalha ou por um efeito de card enquanto este card estiver no seu Cemitério, em vez disso, você pode banir este card.','\r',char(13)),'\n',char(10)),'Usar o efeito de "Camarartista Rinotrovão" em vez de ser destruído?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70465810,'Asanegra - Sudri, o Cintilar Fantasma',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode adicionar 1 card que mencione "Dragão de Asas Negras" do seu Deck à sua mão, exceto "Asanegra - Sudri, o Cintilar Fantasma". \r\nVocê pode oferecer 1 monstro como Tributo; Invoque por Invocação-Especial 1 "Ficha de Cintilar Fantasma" (Besta Alada/Regulador/TREVAS/Nível 2/ATK 700/DEF 700) e, depois, você sofre 700 de dano. \r\nVocê não pode Invocar por Invocação-Especial do Deck Adicional no turno em que ativar este efeito, exceto Monstros Sincro. \r\nVocê só pode usar este efeito de "Asanegra - Sudri, o Cintilar Fantasma" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70465811,'Ficha de Cintilar Fantasma','Invocado por Especial com o efeito "Asanegra - Sudri, o Cintilar Fantasma".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70473293,'Raça Cruzada de Solarvinhas',replace(replace('Ofereça como Tributo 1 Monstro Link e, depois, escolha 1 outro monstro Planta no seu Cemitério; Invoque-o por Invocação-Especial, mas negue seus efeitos. \r\nVocê só pode usar este efeito de "Raça Cruzada de Solarvinhas" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70479321,'Camarartista Baterila',replace(replace('Escala de Pêndulo = 2\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno, quando um ataque for declarado envolvendo um monstro que você controla e um monstro do oponente: você pode escolher esse monstro que você controla; ele ganha 600 de ATK até o final da Fase de Batalha (mesmo que este card deixe o campo).\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe não houver monstros no campo, você pode Invocar este card por Invocação-Normal sem oferecer Tributo. \r\nSe este card for Invocado por Invocação-Normal sem oferecer Tributo, o Nível dele se torna 4. \r\nUma vez por turno, quando um ataque for declarado envolvendo um monstro que você controla e um monstro do oponente: você pode escolher esse monstro que você controla; ele ganha 600 de ATK até o final da Fase de Batalha.','\r',char(13)),'\n',char(10)),'Invocação Normal sem Tributo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70485614,'Batalha Decisiva de Golgonda',replace(replace('O nome deste card se torna "Grande Mar de Areia - Gold Golgonda" enquanto estiver no campo ou no Cemitério. \r\nUma vez por turno, se um ou mais cards que você controla seriam destruídos em batalha ou por um efeito de card, em vez disso, você pode enviar 1 Monstro de Fusão que mencione "Caído de Arbaz" como matéria do seu Deck Adicional para o Cemitério. \r\nDurante a Fase Final, se você tiver "Caído de Arbaz" no seu campo ou no seu Cemitério: você pode Invocar por Invocação-Especial 1 monstro "Springans" da sua mão ou do Deck. \r\nVocê só pode usar este efeito de "Batalha Decisiva de Golgonda" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70488851,'Vidolium, o Instável Patrono do Poder da União',replace(replace('Escala de Pêndulo = 11\r\n[ Efeito de Pêndulo ]\r\nVocê pode ativar 1 desses efeitos;\r\n● Destrua este card e, se isso acontecer, Invoque por Invocação-Especial 1 monstro "Patrono(a) do Poder" da sua mão ou do Cemitério.\r\n● Destrua este card e, além disso, pelo resto deste turno, monstros "Patrono(a) do Poder" que você controla cujos Níveis originais sejam 12 ganham 5000 de ATK.	\r\nVocê só pode usar este efeito de "Vidolium, o Instável Patrono do Poder da União" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nNão pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (do seu Deck Adicional ou Cemitério) ao devolver 3 monstros (1 de Fusão, 1 Sincro e 1 Xyz) do seu campo com a face para cima e/ou Cemitério para o Deck Adicional. \r\nNão é afetado por efeitos de monstro, exceto monstros "Patrono(a) do Poder". \r\nSe este card for adicionado ao seu Deck Adicional com a face para cima: você pode adicionar 1 card "Patrono(a) do Poder" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Vidolium, o Instável Patrono do Poder da União" uma vez por turno. \r\nSe este card for Invocado por Invocação-Especial: bana (com a face para baixo) todos os cards nos Cemitérios.','\r',char(13)),'\n',char(10)),'Escolher um efeito','Invocação Especial','Aumentar ATK','Efeito de busca','Efeito de banimento','','','','','','','','','','','');
INSERT INTO texts VALUES(70491413,'Cadeia Surpresa',replace(replace('Ative apenas como Elo de Corrente 2 ou mais; aplique os seguintes efeitos, em sequência, dependendo do número do Elo de Corrente deste card (pule qualquer um que não se aplique). \r\nVocê não pode ativar este card se múltiplos cards/efeitos com o mesmo nome estiverem nessa Corrente.\r\n● 2+: Escave os cards do topo do seu Deck, igual ao número do Elo de Corrente deste card e, depois, coloque-os no topo do seu Deck em qualquer ordem.\r\n● 3+: Envie o card do topo do seu Deck para o Cemitério.\r\n● 4+: Compre 1 card.	\r\nVocê só pode ativar 1 "Cadeia Surpresa" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70491682,'Anima Vendorror',replace(replace('Você pode banir este card do seu Cemitério e, depois, escolher 1 dos seus monstros "Vendorror" banidos, exceto "Anima Vendorror"; Invoque-o por Invocação-Especial e, além disso, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros Zumbi. \r\nUm monstro "Vendorror" Invocado por Invocação-Ritual usando este card no campo ganha o seguinte efeito. \r\nVocê só pode usar cada um dos efeitos anteriores de "Anima Vendorror" uma vez por turno.\r\n● Bana quaisquer monstros destruídos em batalha com este card.','\r',char(13)),'\n',char(10)),'','O efeito de "Anima Vendorror" está sendo aplicado.','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70493141,'O Ascensionado do Trovão',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) ao pagar 3000 PV. \r\nSe este card Invocado desta forma, sob o controle do seu dono, for destruído por um card do oponente (em batalha ou por um efeito de card): ganhe 5000 PV.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70508653,'Caixa de Ferramentas',replace(replace('Se você controlar um monstro: você pode revelar 2 Magias de Equipamento do seu Deck com nomes diferentes, seu oponente elege 1 aleatoriamente para que você adicione à sua mão e, além disso, coloque o card restante no fundo do seu Deck. \r\nVocê só pode usar este efeito de "Caixa de Ferramentas" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70514456,'Monge Louva-a-deus Ragnaraika',replace(replace('2+ monstros, incluindo um monstro Inseto, Planta ou Réptil	\r\nVocê pode banir 2 monstros Inseto, Planta e/ou Réptil do seu Cemitério; adicione 1 Armadilha "Ragnaraika" do seu Deck à sua mão. \r\nSe este card estiver no seu Cemitério: você pode escolher 1 monstro Inseto, Planta ou Réptil que você controla; coloque-o no fundo do Deck e, se isso acontecer, Invoque este card por Invocação-Especial e, além disso, você não pode Invocar por Invocação-Especial pelo resto deste turno, exceto monstros Inseto, Planta ou Réptil. \r\nVocê só pode usar cada efeito de "Monge Louva-a-deus Ragnaraika" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicione à sua mão 1 Card de Armadilha "Ragnaraika"','Invocar-se por Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70522875,'Senhor Dragunidade - Georgius',replace(replace('2+ monstros, incluindo um Regulador	\r\nEnquanto este card estiver equipado com um card "Dragunidade", seu oponente não pode ativar os efeitos de monstros no Cemitério. \r\nVocê só pode usar cada um dos seguintes efeitos de "Senhor Dragunidade - Georgius" uma vez por turno. \r\nSe este card for Invocado por Invocação-Link, ou seu oponente Invocar um ou mais monstros por Invocação-Especial: você pode Invocar por Invocação-Especial 1 monstro "Dragunidade" de Nível 5 ou mais do seu Deck Adicional ou Cemitério. \r\nQuando seu oponente ativar um Card de Magia/Armadilha ou seus efeitos (Efeito Rápido): você pode enviar 1 Card de Equipamento que você controla para o Cemitério; negue o efeito.','\r',char(13)),'\n',char(10)),'Invocação Especial','Negar o efeito','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70534340,'Lubellion, o Dragão Ardente',replace(replace('1 monstro de TREVAS + "Caído de Arbaz"	\r\nSe este card for Invocado por Invocação-Fusão: você pode descartar 1 card; Invoque por Invocação-Fusão 1 Monstro de Fusão de Nível 8 ou menos do seu Deck Adicional, exceto "Lubellion, o Dragão Ardente", ao embaralhar no Deck as Matérias de Fusão mencionadas nele, dentre seus monstros no campo, Cemitério e/ou cards banidos com a face para cima. \r\nPelo resto deste turno, este card não pode atacar e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional, exceto Monstros de Fusão. \r\nVocê só pode usar este efeito de "Lubellion, o Dragão Ardente" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70538272,'Filia Regis',replace(replace('1 Monstro de Fusão Dragão + 1 monstro Dragão de Nível 7 ou mais	\r\nDurante a Fase Principal (Efeito Rápido): você pode escolher 1 card que seu oponente controla ou no Cemitério dele; bana-o e, depois, se você baniu um card no campo, devolva 1 monstro Dragão que você controla para a mão. \r\nNo começo da Fase de Batalha do seu oponente, se este card estiver no seu Cemitério: você pode devolver 1 monstro Dragão que você controla para a mão ou para o Deck Adicional e, se isso acontecer, Invoque este card por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Filia Regis" uma vez por turno.','\r',char(13)),'\n',char(10)),'Banir','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70546737,'Terror Umbral Fogo-fátuo',replace(replace('Quando este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 monstro "Terror Umbral" que você controla ou no seu Cemitério, exceto este card; o Nível deste card se torna o Nível atual desse monstro. \r\nQuando este card em Posição de Ataque for destruído em batalha e enviado para o Cemitério e estava com a face para cima em Posição de Ataque no começo da Etapa de Dano: destrua o monstro que destruiu este card.','\r',char(13)),'\n',char(10)),'Alterar Nível','Destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70551291,'Soldado do Lustro Negro - Espadachim Lendário',replace(replace('Você pode Invocar este card por Invocação-Ritual com "Forma do Caos" ou "Ritual do Super Soldado". \r\nDeve ser Invocado por Invocação-Ritual. \r\nDurante sua Fase de Compra, antes de comprar: você pode revelar este card na sua mão; renuncie à sua compra normal neste turno e, se isso acontecer, adicione 1 Magia de Ritual do seu Deck à sua mão. \r\nSeu oponente não pode ativar cards ou efeitos durante sua Fase de Batalha. \r\nQuando este card atacante, que foi Invocado por Invocação-Ritual usando um Monstro Normal, destruir um monstro do oponente em batalha: você pode embaralhar todos os cards que seu oponente controla no Deck.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70560957,'Reversão Toon','Escolha 1 monstro Toon que você controla; ele pode realizar um segundo ataque durante cada Fase de Batalha neste turno.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70564929,'Script do Abismo - Abismotrenimento',replace(replace('Você pode oferecer como Tributo 1 monstro "Ator do Abismo" e, depois, escolher 1 Magia "Script do Abismo" no seu Cemitério; Baixe-a no seu campo. \r\nVocê pode usar este efeito de "Script do Abismo - Abismotrenimento" até duas vezes por turno. \r\nSe este card Baixado sob o controle do seu dono for destruído por um efeito de card do oponente e você tiver um Monstro Pêndulo "Ator do Abismo" com a face para cima no seu Deck Adicional: você pode Invocar por Invocação-Especial qualquer número de Monstros Pêndulo "Ator do Abismo" do seu Deck.','\r',char(13)),'\n',char(10)),'Baixar 1 Card de Magia do Cemitério','Invocar 1 monstro por Invocação Especial do Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70569684,'Compra de Alta Intensidade',replace(replace('Destrua 2 ou mais monstros que você controla e, se isso acontecer, compre 1 card para cada 2 monstros destruídos. \r\nDurante a Fase Principal do seu oponente, se este card estiver no seu Cemitério: você pode escolher 1 monstro que você controla; destrua-o e, se isso acontecer, Baixe este card, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar este efeito de "Compra de Alta Intensidade" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70576413,'D/D/D Primeiro Rei Clovis',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro: você pode escolher 1 dos seus monstros "D/D" banidos, ou se um card "Pacto Obscuro" estiver no campo, em vez disso, você pode escolher 1 no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê só pode usar este efeito de "D/D/D Primeiro Rei Clovis" uma vez por turno. \r\nSe este card for banido: você pode ativar este efeito; se um monstro "D/D" seu atacar um monstro em Posição de Defesa neste turno, cause dano de batalha perfurante ao seu oponente.','\r',char(13)),'\n',char(10)),'Invocação Especial','Perfurante','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70583986,'Dewloren, o Rei Tigre da Barreira de Gelo',replace(replace('1 Regulador + 1+ monstros não-Reguladores de ÁGUA	\r\nVocê pode escolher qualquer número de outros cards com a face para cima que você controla; devolva os alvos para a mão e, depois, até o final deste turno, este card ganha 500 de ATK para cada card devolvido para a mão por este efeito. \r\nVocê só pode usar este efeito de "Dewloren, o Rei Tigre da Barreira de Gelo" uma vez por turno.','\r',char(13)),'\n',char(10)),'Retornar à mão e aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70595331,'Sangue Ruim',replace(replace('Este card é considerado como um Monstro Normal enquanto estiver com a face para cima no campo ou no Cemitério. \r\nEnquanto este card for um Monstro Normal no campo, você pode Invocá-lo por Invocação-Normal para fazer com que ele se torne um Monstro de Efeito com este efeito.\r\n● Uma vez por turno: você pode Invocar por Invocação-Especial 1 monstro Zumbi da sua mão ou de qualquer Cemitério, mas se este card deixar o campo, destrua todos os monstros Zumbi Invocados por Invocação-Especial por este efeito.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70597485,'Materriator Gigaboros',replace(replace('2+ monstros de Nível 3	\r\nGanha 500 de ATK/DEF para cada card na sua mão. \r\nVocê só pode usar cada um dos seguintes efeitos de "Materriator Gigaboros" uma vez por turno. \r\nVocê pode desassociar 1 matéria deste card; associe 1 monstro "Materriator" do seu Deck a este card como matéria. \r\nDurante a Fase Principal ou de Batalha do seu oponente (Efeito Rápido): você pode adicionar 1 card associado a este card à mão.','\r',char(13)),'\n',char(10)),'Aumentar ATK/DEF','Use um monstro do Deck como Matéria Xyz','Adicione Matéria Xyz à sua mão','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70624184,'Constelar Rasalhague','Você pode oferecer este card como Tributo; Invoque por Invocação-Especial 1 monstro "Constelar" da sua mão ou Cemitério com a face para cima em Posição de Defesa, exceto "Constelar Rasalhague".','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70628672,'Chamado Emergeroide',replace(replace('Quando um Card de Magia/Armadilha ou efeito de monstro for ativado enquanto você controlar um Monstro de Fusão "roide": negue a ativação e, depois, envie para o Cemitério todos os cards com o mesmo nome que o desse card do Deck e Deck Adicional do duelista que estiver ativando. \r\nVocê pode banir este card do Cemitério e, depois, escolha 1 monstro "roide" no seu Cemitério; adicione-o à sua mão. \r\nVocê só pode usar este efeito de "Chamado Emergeroide" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70630741,'Guerreiro de Resgate',replace(replace('Você não sofre Dano de Batalha de batalhas envolvendo este card. \r\nSe este card for destruído em batalha, selecione 1 monstro com a face para cima que seu oponente controla que você seja o dono e tome o controle dele.','\r',char(13)),'\n',char(10)),'Tomar controle','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70634245,'Senhor dos Seis Samurai Lendários - Enishi',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nMonstros Guerreiro que você controla ganham 500 de ATK/DEF apenas durante a Fase de Batalha. \r\nVocê só pode usar cada um dos seguintes efeitos de "Senhor dos Seis Samurai Lendários - Enishi" uma vez por turno. \r\nSe este card for Invocado por Invocação-Sincro: você pode banir qualquer número de monstros "Seis Samurai" do seu Cemitério e, depois, escolha esse número de monstros que seu oponente controla; devolva esses monstros para a mão. \r\nSe este card for enviado para o Cemitério: você pode Invocar por Invocação-Especial 1 dos seus monstros "Seis Samurai" banidos.','\r',char(13)),'\n',char(10)),'Retornar para a mão um monstro do oponente','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70636044,'Varudras, o Arauto Final do Fim dos Tempos',replace(replace('2+ monstros de Nível 10	\r\nQuando seu oponente ativar um card ou efeito (Efeito Rápido): você pode desassociar 1 matéria deste card; negue a ativação e, depois, você pode desassociar 1 matéria deste card e, depois, destrua 1 card no campo. \r\nNo começo da Etapa de Dano, se este card atacar enquanto tiver matéria: você pode destruir 1 card no campo. \r\nSe este card Invocado por Invocação-Xyz for destruído: você pode destruir 1 card no campo. \r\nVocê só pode usar cada efeito de "Varudras, o Arauto Final do Fim dos Tempos" uma vez por turno.','\r',char(13)),'\n',char(10)),'Negue o efeito do seu oponente','Destruir 1 card no campo','Destruir 1 card no campo','Desassociar outra Matéria Xyz e destruir um card no campo?','','','','','','','','','','','','');
INSERT INTO texts VALUES(70645913,'Criado Vampiro',replace(replace('Se este card for Invocado por Invocação-Especial: você pode pagar 500 PV; adicione 1 Magia/Armadilha "Vampiro(a)" do seu Deck à sua mão. \r\nSe este card estiver no seu Cemitério: você pode enviar 1 card "Vampiro(a)" da sua mão ou do campo com a face para cima para o Cemitério; Invoque este card por Invocação-Especial, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar cada efeito de "Criado Vampiro" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70655556,'Tubarão Lança',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode aumentar em 1 os Níveis de todos os monstros do Tipo Peixe de Nível 3 que você controla. \r\nSe este card atacar um monstro em Posição de Defesa, ele causa dano de batalha perfurante ao seu oponente.','\r',char(13)),'\n',char(10)),'Aumentar o Nível','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70659412,'Omnidemolidor Psíquico',replace(replace('1 Regulador + 1+ monstros Psíquico não-Reguladores	\r\nSempre que seu oponente ativar um card ou efeito no campo (exceto durante a Etapa de Dano): você pode pagar 2000 PV e declarar 1 tipo de card (Monstro, Magia ou Armadilha) (mas você só pode declarar cada tipo de card uma vez por turno para ativar este efeito de "Omnidemolidor Psíquico"); olhe 1 card aleatório na mão do seu oponente, e se for do tipo de card declarado, aplique esses efeitos em sequência (pule qualquer um que não se aplique).\r\n● Este card não pode ser destruído pelos efeitos do tipo de card declarado neste turno.\r\n● Bana o card que você olhou, com a face para cima, até a Fase Final.','\r',char(13)),'\n',char(10)),'Ativar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70668285,'Espada Serafim Estelar','Uma vez por turno: você pode enviar 1 monstro "Serafim Estelar" da sua mão para o Cemitério; até a Fase Final, este card ganha ATK igual ao ATK original do monstro enviado.','Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70676581,'Freed, General das Trevas',replace(replace('Não pode ser Invocado por Invocação-Especial. \r\nNegue quaisquer efeitos de Magia que escolham um ou mais monstros de TREVAS com a face para cima que você controla e, se isso acontecer, destrua esse Card de Magia. \r\nDurante sua Fase de Compra, em vez de conduzir sua compra normal: Você pode adicionar 1 monstro de TREVAS de Nível 4 do seu Deck à sua mão. \r\nEste card deve estar com a face para cima no campo para ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Negar uma Magia e destruí-la','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70681994,'Dragoness, O Cavaleiro Perverso','"Armaill" + "Dragão Escudo de Um Só Olho"','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70686400,'Fazticeira Terracottan',replace(replace('Se este card estiver na sua mão: você pode escolher 1 card "Fazticeira" no seu Cemitério, exceto "Fazticeira Terracottan"; adicione-o a sua mão, e se fizer, Invoque este card por Invocação-Especial, você também não pode Invocar por Invocação-Especial do seu Deck Adicional pelo resto deste turno, exceto monstros "Fazticeira".\r\nDurante sua Fase Principal: você pode Invocar por Invocação-Fusão 1 monstro "Fazticeira" do seu Deck Adicional, usando monstros da sua mão ou campo.\r\nVocê só pode usar cada um dos efeitos de "Fazticeira Terracottan" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Invocação Fusão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70703416,'Espírito Hexa da Barreira de Gelo',replace(replace('Enquanto você controlar outro monstro "Barreira de Gelo", os monstros que seu oponente controla perdem 500 de ATK/DEF. \r\nDurante sua Fase Principal: você pode enviar 1 monstro "Barreira de Gelo" de Nível 3 ou menos do seu Deck para o Cemitério e, se isso acontecer, até o final deste turno, o Nível deste card se torna o mesmo que o desse monstro. \r\nVocê só pode usar este efeito de "Espírito Hexa da Barreira de Gelo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70709488,'Inseto Shinobi Hagakuremino',replace(replace('2 monstros com nomes diferentes	\r\nEnquanto este card apontar para um ou mais monstros, os monstros do seu oponente não podem escolher este card como alvo de ataques. \r\nSe um ou mais monstros para os quais este card apontar forem destruídos em batalha ou por um efeito de card: você pode Invocar por Invocação-Especial 1 monstro Inseto de Nível 4 ou menos da sua mão ou do Cemitério, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar este efeito de "Inseto Shinobi Hagakuremino" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70711847,'Perigo! Nessie!',replace(replace('Você pode revelar este card na sua mão; seu oponente seleciona aleatoriamente 1 card de toda a sua mão e, depois, você descarta o card selecionado. \r\nDepois, se o card descartado não era "Perigo! Nessie!", Invoque por Invocação-Especial 1 "Perigo! Nessie!" da sua mão e, se isso acontecer, compre 1 card. \r\nSe este card for descartado: você pode adicionar 1 card "Perigo!" do seu Deck à sua mão, exceto "Perigo! Nessie!". \r\nVocê só pode usar este efeito de "Perigo! Nessie!" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70717628,'Fantasma Translúcido',replace(replace('Você não é afetado pelos efeitos de "Mundo Translúcido". \r\nVocê pode descartar 2 cards, incluindo este card; adicione 2 cards do seu Deck à sua mão, que sejam "Mundo Translúcido" ou Magias/Armadilhas que o mencionem. \r\nVocê só pode usar este efeito de "Fantasma Translúcido" uma vez por turno. \r\nSe este card for destruído: você pode escolher 1 monstro que seu oponente controla; destrua-o e, se isso acontecer, envie os 3 cards do topo do Deck dele para o Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70744296,'Ipíria',replace(replace('Se este card for Invocado: compre 1 card. \r\nVocê só pode usar este efeito de "Ipíria" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70771599,'Rei Supremo Dragão de Asas Transparentes',replace(replace('1 Regulador + 1+ Monstros Pêndulo não-Reguladores de TREVAS	\r\nSe este card for Invocado por Invocação-Sincro: você pode destruir todos os monstros com a face para cima que seu oponente controla. \r\nUma vez por turno, antes do cálculo de dano, se este card batalhar um monstro do oponente: você pode destruir esse monstro e, se isso acontecer, cause dano ao seu oponente igual ao ATK original do monstro destruído. \r\nSe este card estiver no seu Cemitério: você pode oferecer como Tributo 2 monstros "Rei Supremo Dragão"; Invoque este card por Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70780151,'Arquidemônio Senhor dos Pensamentos',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nSe este card destruir um monstro em batalha e enviá-lo para o Cemitério: ganhe PV igual ao ATK original desse monstro no Cemitério. \r\nQuando um Card de Magia/Armadilha for ativado que escolha como alvo 1 monstro Psíquico (e nenhum outro card) (Efeito Rápido): você pode pagar 1000 PV; negue a ativação e, se isso acontecer, destrua-o.','\r',char(13)),'\n',char(10)),'Ganhe PV iguais ao ATK original do monstro destruído','Negue a ativação de uma Magia/Armadilha que tenha um monstro Psíquico como alvo e a destrua','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70781052,'Caveira Invocada',replace(replace('Um demônio com poderes das trevas para confundir o inimigo. Entre os monstros do tipo demônio, é dos mais fortes.	\r\n\r\n(Este card é tratado como um card "Arquidemônio".)','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70781053,'Caveira Invocada',replace(replace('Um demônio com poderes das trevas para confundir o inimigo. Entre os monstros do tipo demônio, é dos mais fortes.	\r\n\r\n(Este card é tratado como um card "Arquidemônio".)','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70781054,'Caveira Invocada',replace(replace('Um demônio com poderes das trevas para confundir o inimigo. Entre os monstros do tipo demônio, é dos mais fortes.	\r\n\r\n(Este card é tratado como um card "Arquidemônio".)','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70781055,'Caveira Invocada',replace(replace('Um demônio com poderes das trevas para confundir o inimigo. Entre os monstros do tipo demônio, é dos mais fortes.	\r\n\r\n(Este card é tratado como um card "Arquidemônio".)','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70781056,'Caveira Invocada',replace(replace('Um demônio com poderes das trevas para confundir o inimigo. Entre os monstros do tipo demônio, é dos mais fortes.	\r\n\r\n(Este card é tratado como um card "Arquidemônio".)','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70781057,'Caveira Invocada',replace(replace('Um demônio com poderes das trevas para confundir o inimigo. Entre os monstros do tipo demônio, é dos mais fortes.	\r\n\r\n(Este card é tratado como um card "Arquidemônio".)','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70786111,'Stonehenge',replace(replace('Escolha 1 monstro com 0 de ATK no seu Cemitério; Invoque-o por Invocação-Especial em Posição de Ataque e, se isso acontecer, equipe-o com este card. \r\nQuando este card, equipado por este efeito, deixar o campo, destrua esse monstro. \r\nVocê só pode ativar 1 "Stonehenge" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70791313,'Biblioteca Mágica Real',replace(replace('Sempre que um Card de Magia for ativado, coloque 1 Marcador de Magia neste card quando essa Magia resolver (máx. 3). \r\nVocê pode remover 3 Marcadores de Magia deste card; compre 1 card.','\r',char(13)),'\n',char(10)),'Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70797118,'Nyan Nyan Trovão','Se existir no seu Campo um monstro que não seja da LUZ, destrua este card com a face para cima.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70821187,'Múmia Regenerativa','Quando este card for enviado da sua mão para o seu Cemitério por um efeito de card do oponente: devolva este card para a mão.','Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70825459,'Rastros de Armadilha',replace(replace('Escolha 1 monstro que você controla; destrua-o e, se isso acontecer, Baixe 1 Armadilha Normal diretamente do seu Deck, exceto "Rastros de Armadilha". \r\nEla pode ser ativada neste turno. \r\nVocê só pode ativar 1 Card de Armadilha pelo resto deste turno depois que este card resolver. \r\nVocê só pode ativar 1 "Rastros de Armadilha" por turno.','\r',char(13)),'\n',char(10)),'Ativar aplicando o efeito de "Rastros de Armadilha".','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70828912,'Enterro Precoce',replace(replace('Ative este card ao pagar 800 PV e, depois, escolha 1 monstro no seu Cemitério; Invoque-o por Invocação-Especial em Posição de Ataque e equipe-o com este card. \r\nQuando este card for destruído, destrua o monstro equipado.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70832512,'Cruzado Absoluto','Se um ou mais monstros de Nível 5 ou mais forem Invocados por Invocação-Especial: ofereça este card com a face para cima como Tributo; destrua esses monstros de Nível 5 ou mais.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70843274,'Processador Psíquico',replace(replace('Você pode banir este card que você controla; Invoque por Invocação-Especial até 2 monstros Máquina, Psíquico e/ou Ciberso da sua mão e eles podem atacar diretamente neste turno. \r\nDurante a Fase de Apoio do próximo turno depois que este card foi banido: você pode adicionar este card banido à sua mão. \r\nVocê só pode usar cada efeito de "Processador Psíquico" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70856343,'Guivrecente Radiante',replace(replace('Quando este card for Invocado por Invocação-Normal enquanto seu oponente controlar um monstro: você pode descartar 1 card; envie qualquer número de "Guivrecente Radiante" do seu Deck para o Cemitério. \r\nUma vez por turno, se este card estiver no seu Cemitério: você pode fazer com que este card no Cemitério se torne de TREVAS até o final deste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70860415,'Canhão Cruz-X',replace(replace('Se você controlar um monstro de Fusão ou União Máquina de LUZ: você pode Invocar este card por Invocação-Especial da sua mão. \r\nDurante sua Fase Principal: você pode equipar 1 monstro União Máquina de LUZ apropriado do seu Deck a este card como uma Magia de Equipamento como se ele tivesse sido equipado pelo efeito desse monstro e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto monstros de LUZ. \r\nVocê só pode usar cada efeito de "Canhão Cruz-X" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Efeito de Equipamento','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70861343,'A Arte de Transformação Ninjitsu',replace(replace('Ative este card ao oferecer como Tributo 1 monstro "Ninja" com a face para cima; Invoque por Invocação-Especial 1 monstro Besta, Besta Alada ou Inseto da sua mão ou do Deck cujo Nível seja menor ou igual que o Nível que o monstro oferecido como Tributo tinha no campo +3. \r\nQuando este card deixar o campo, destrua esse monstro.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70865988,'Ataque Completo','Envie toda a sua mão para o Cemitério e, se isso acontecer, cause 200 de dano ao seu oponente para cada card enviado para o Cemitério por este efeito.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70871153,'Urgula Caudraco',replace(replace('Se este card for enviado para o Cemitério como matéria para uma Invocação-Fusão: você pode Baixar 1 Magia/Armadilha "Caudraco" do seu Deck e, depois, você pode destruir 1 Magia/Armadilha no campo. \r\nSe este card estiver no seu Cemitério: você pode escolher 1 monstro Mago "Caudraco" no seu Cemitério; coloque este card no fundo do seu Deck e, se isso acontecer, adicione esse monstro à sua mão. \r\nVocê só pode usar cada efeito de "Urgula Caudraco" uma vez por turno.','\r',char(13)),'\n',char(10)),'Baixar Magia/Armadilha','Recuperar um monstro','Destruir uma Magia/Armadilha?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70875686,'Rasgo-Rugido-Raivoso dos Travesso-Guris',replace(replace('2+ monstros "Travesso-Guris"	\r\nDeve ser Invocado por Invocação-Link. \r\n(Efeito Rápido): você pode oferecer este card como Tributo; destrua todas as Magias e Armadilhas que seu oponente controla. \r\nSe este card em sua posse for enviado para o seu Cemitério por um card do seu oponente: você pode escolher 1 card no seu Cemitério, exceto um Monstro Link; adicione-o à sua mão. \r\nVocê só pode usar este efeito de "Rasgo-Rugido-Raivoso dos Travesso-Guris" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70875955,'Recarga Aérea',replace(replace('Uma vez por turno: você pode Invocar por Invocação-Especial 1 "Ficha de Besta Fantasma Mecha" (Tipo Máquina/VENTO/Nível 3/ATK 0/DEF 0). \r\nDurante a Fase Final de cada duelista, ofereça como Tributo 1 Ficha ou monstro "Besta Fantasma Mecha", ou envie este card para o Cemitério.','\r',char(13)),'\n',char(10)),'Invocar uma Ficha por Invocação Especial','Usar o efeito de "Recarga Aérea" agora?','Oferecer como Tributo 1 Ficha ou um monstro cujo nome inclua "Besta Fantasma Mecha" para manter "Recarga Aérea"?','Ativar e aplicar o efeito','','','','','','','','','','','','');
INSERT INTO texts VALUES(70875956,'Ficha de Besta Fantasma Mecha','Invocado por Especial com o efeito de um monstro "Besta Fantasma Mecha" ou um card relacionado.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70899775,'Pianíssimo','Escolha 1 monstro com a face para cima que você controla; neste turno, o ATK original desse monstro com a face para cima se torna 100 e, além disso, esse monstro com a face para cima não pode ser destruído em batalha ou por efeitos de card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70902743,'Dragão Vermelho Arquidemônio',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nDepois do cálculo de dano, se este card atacou um monstro do oponente em Posição de Defesa: destrua todos os monstros em Posição de Defesa que seu oponente controla. \r\nUma vez por turno, durante sua Fase Final: destrua todos os outros monstros que você controla que não declararam um ataque neste turno. \r\nEste card deve estar com a face para cima no campo para ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Destrua todos os monstros em Posição de Defesa','Destrua todos os monstros que não atacaram','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70903634,'Braço Direito de "O Proibido"','Um braço direito, proibido e selado por magia. Qualquer um que romper este selo obterá poder infinito.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70908596,'Constelar Kaus',replace(replace('Não pode ser usado como uma Matéria Sincro. \r\nAté duas vezes por turno: você pode escolher 1 monstro "Constelar" no campo e, depois, ativar 1 desses efeitos;\r\n● Aumente seu Nível em 1.\r\n● Reduza seu Nível em 1.','\r',char(13)),'\n',char(10)),'Alterar Nível','Aumentar em 1 Nível.','Reduzir em 1 Nível.','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70913714,'Entidade Antiga Hastorr',replace(replace('1 Regulador + 1 ou mais monstros não-Reguladores	\r\nSe este card for enviado da Zona de Monstros para o Cemitério: você pode escolher 1 monstro com a face para cima que seu oponente controla; equipe este card do seu Cemitério a esse monstro. \r\nEsse monstro não pode atacar e, além disso, seus efeitos são negados. \r\nSe este card deixar o campo enquanto estiver equipado a um monstro do oponente por este efeito: tome o controle do monstro ao qual este card estava equipado.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70914287,'Kuribabylon',replace(replace('Ganha 300 de ATK/DEF para cada monstro "Kuriboh" que você controla e no seu Cemitério. \r\nVocê só pode usar 1 dos seguintes efeitos de "Kuribabylon" por turno e apenas uma vez por turno.\r\n● Se você tiver mais monstros no seu Cemitério que seu oponente: você pode Invocar este card por Invocação-Especial da sua mão.\r\n● Durante sua Fase Principal ou de Batalha: você pode devolver este card para a mão e, se isso acontecer, Invoque por Invocação-Especial 5 monstros (1 "Kuribah", 1 "Kuribee", 1 "Kuriboo", 1 "Kuribeh" e 1 "Kuriboh") da sua mão e/ou Cemitério em Posição de Ataque.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70916046,'Canhão da Equação Linear',replace(replace('Durante a Fase de Batalha: declare um número inteiro de 1 a 6; selecione 1 Monstro de Efeito que seu oponente controla. \r\nMultiplique o Nível do Monstro de Efeito x o número declarado e, depois, adicione o número de cards que seu oponente controla e verifique se o resultado é igual ao número de cards no seu Cemitério.\r\n● Se for: Envie cards do topo do seu Deck para o Cemitério, até o número declarado e, se isso acontecer, embaralhe cards que seu oponente controla no Deck, até o número enviado para o Cemitério.\r\n● Se não for: Você perde PV igual ao número declarado x 500.	\r\nVocê só pode ativar 1 "Canhão da Equação Linear" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70917315,'Amórfago da Luxúria',replace(replace('Escala de Pêndulo = 5\r\n[ Efeito de Pêndulo ]\r\nEnquanto você controlar um monstro "Amórfago", nenhum duelista pode ativar Cards de Magia ou seus efeitos, exceto cards "Amórfago(a)". \r\nUma vez por turno, durante sua Fase de Apoio, ofereça 1 monstro como Tributo ou destrua este card.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe este card for Invocado por Invocação-Pêndulo ou virado com a face para cima, nenhum duelista pode Invocar monstros do Deck Adicional por Invocação-Especial enquanto este card estiver no campo com a face para cima, exceto monstros "Amórfago".','\r',char(13)),'\n',char(10)),'Oferecer como Tributo 1 monstro que você controla?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70924884,'Alinsection','Um escaravelho-veado com a cabeça e os braços em forma de serra.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70939418,'Velocidaroide Prêmio Goma',replace(replace('Durante a Fase de Batalha, se você sofrer dano de batalha ou de efeito: você pode Invocar este card por Invocação-Especial da sua mão. \r\nDurante a Fase de Batalha de qualquer duelista na qual este card foi Invocado por Invocação-Especial por seu efeito, você pode: imediatamente depois que este efeito resolver, Invoque 1 Monstro Sincro por Invocação-Sincro, usando apenas monstros de VENTO que você controla, incluindo este card. \r\nSe este card for enviado para o Cemitério como uma Matéria Sincro: você pode enviar o card do topo do seu Deck para o Cemitério e se o card enviado era um monstro "Velocidaroide", o Monstro Sincro que usou este card como Matéria Sincro ganha 1000 de ATK.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70946699,'Explosão dos Cinco Irmãos',replace(replace('Quando este card for ativado: ganhe 500 Pontos de Vida para cada Card de Magia/Armadilha Contínua que você controla. \r\nSe este card que você controla com a face para cima for enviado para o seu Cemitério por um efeito de card do seu oponente: cause 500 de dano ao seu oponente para cada Card de Magia/Armadilha Contínua em seu Cemitério.','\r',char(13)),'\n',char(10)),'Causar dano aos PV','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70948327,'Nanoquebrador','Se este card atacar um monstro de Nível 3 ou menos com a face para cima, destrua o monstro imediatamente com o efeito deste card sem aplicar o cálculo de dano.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70950698,'Boot Veassutado',replace(replace('Quando um monstro Ciberso for Invocado por Invocação-Normal no seu campo: você pode Invocar este card por Invocação-Especial da sua mão. \r\nVocê só pode usar este efeito de "Boot Veassutado" uma vez por turno. \r\nQuando este card causar dano de batalha ao seu oponente: você pode Invocar por Invocação-Especial 1 "Ficha de Veado" (Ciberso/TERRA/Nível 1/ATK 0/DEF 0).','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70950699,'Ficha de Veado','Invocada por Invocação-Especial com o efeito "Boot Veassutado".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70969517,'Besta Fantasma Lagarto-de-Rocha',replace(replace('Se você oferecer como Tributo um monstro "Besta Fantasma" ou "Gazelle, o Rei das Bestas Místicas", este card pode ser Invocado por Invocação-Normal com 1 Tributo. \r\nQuando este card destruir um monstro em batalha, cause 500 de dano ao seu oponente. \r\nQuando este card for destruído e enviado para o Cemitério por um efeito de card do oponente, cause 2000 de dano ao seu oponente.','\r',char(13)),'\n',char(10)),'Ofereça 1 monstro como Tributo para Invocar por Tributo','Cause 500 de dano ao seu oponente','Cause 2000 de dano ao seu oponente','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70975131,'Gato de Guarda',replace(replace('Se você não controlar nenhum monstro: você pode Invocar este card por Invocação-Especial da sua mão. \r\nDurante sua Fase Final, se este card foi Invocado por Invocação-Especial neste turno: você pode banir este card; Baixe 1 Magia Contínua diretamente do seu Deck. \r\nVocê só pode usar cada efeito de "Gato de Guarda" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(70980824,'Trishula, o Dragão Zero da Barreira de Gelo',replace(replace('1 Regulador + 2+ monstros não-Reguladores	\r\nQuando este card for Invocado por Invocação-Sincro: você pode banir até 3 cards que seu oponente controla. \r\nSe este card Invocado por Invocação-Sincro sob o controle do seu dono for destruído por um card do oponente: você pode Invocar por Invocação-Especial 1 "Trishula, o Dragão da Barreira de Gelo" do seu Deck Adicional ou do Cemitério, seu ATK se torna 3300 e, depois, diminua pela metade o ATK de qualquer monstro com a face para cima que seu oponente controla atualmente e, além disso, negue os efeitos deles. \r\nVocê só pode usar este efeito de "Trishula, o Dragão Zero da Barreira de Gelo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71002019,'Mudan, a Fada Rikka',replace(replace('Você pode oferecer como Tributo 1 monstro Planta; Invoque este card por Invocação-Especial da sua mão. \r\nSe este card for Invocado por Invocação-Normal, ou Invocado por Invocação-Especial pelo efeito de um monstro Planta: você pode adicionar 1 Magia/Armadilha "Rikka" do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "Mudan, a Fada Rikka" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71007216,'Ventobruxa - Sino de Vidro',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 monstro "Ventobruxa" do seu Deck à sua mão, exceto "Ventobruxa - Sino de Vidro" e, além disso, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros de VENTO. \r\nVocê só pode usar este efeito de "Ventobruxa - Sino de Vidro" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71015787,'Canhestro Silencioso',replace(replace('Durante sua Fase Principal: você pode Invocar este card por Invocação-Especial, da sua mão, no lado do campo do seu oponente. \r\nQuando Invocado desta forma: compre 1 card e, se isso acontecer, seu oponente ganha 2000 Pontos de Vida. \r\nVocê só pode usar este efeito de "Canhestro Silencioso" uma vez por turno. \r\nO limite de cards na mão do controlador deste card se torna 3.','\r',char(13)),'\n',char(10)),'Invocação Especial','Comprar e ganhar PV','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71036835,'Kuribee',replace(replace('(Este card deve ser sempre considerado como um card "Kuriboh".)	\r\nQuando este card ou outro monstro "Kuriboh" que você controla for destruído em batalha: você pode adicionar 1 Magia/Armadilha do seu Deck à sua mão que liste o card "Kuriboh" em seu texto. \r\nVocê só pode usar este efeito de "Kuribee" uma vez por turno. \r\nUma vez por turno, quando um monstro do oponente declarar um ataque enquanto você controlar outro monstro "Kuriboh": até o final deste turno, você pode mudar o ATK de todos os outros monstros que você controla para 0 e, se isso acontecer, negue o ataque.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71039903,'A Pedra Branca dos Antigos',replace(replace('Uma vez por turno, durante a Fase Final, se este card estiver no Cemitério porque foi enviado para lá neste turno: você pode Invocar por Invocação-Especial 1 monstro "Olhos Azuis" do seu Deck. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 monstro "Olhos Azuis" no seu Cemitério; adicione-o à sua mão. \r\nVocê só pode usar este efeito de "A Pedra Branca dos Antigos" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71044499,'O Nobre de Crossout','Escolha 1 monstro com a face para baixo no campo; destrua o alvo e, se isso acontecer, bana-o e, depois, se ele era um monstro de Virar, cada duelista revela o seu Deck Principal e, depois, bane dele todos os cards com aquele nome de monstro.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71060915,'Vento de Pena','Quando um Card de Magia/Armadilha for ativado enquanto você controlar um "Aviário, o HERÓI do Elemento" com a face para cima: Negue a ativação e destrua esse card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71068247,'Pássaro Totem',replace(replace('2 monstros de VENTO de Nível 3	\r\nQuando um Card de Magia/Armadilha for ativado (Efeito Rápido): você pode desassociar 2 matérias deste card; negue a ativação e, se isso acontecer, destrua-o. \r\nEste card perde 300 de ATK enquanto não tiver matérias.','\r',char(13)),'\n',char(10)),'Negar seus efeitos e destruí-lo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71068263,'Bicho de Pelúcia','Pode parecer um bicho de pelúcia inofensivo, mas a mordida da sua boca de zíper é mortal.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71069715,'D/D Rerrolagem',replace(replace('Cards "Pacto Obscuro" que você controla não podem ser destruídos por efeitos de card do seu oponente. \r\nVocê pode banir este card do seu Cemitério e, depois, escolher até 3 dos seus outros cards "D/D" banidos; embaralhe-os no Deck.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71071546,'Orbital 7',replace(replace('Quando este card for virado com a face para cima: coloque 1 Marcador Sim Chefinho! sobre ele. \r\nVocê pode remover todos os Marcadores Sim Chefinho! neste card; seu ATK se torna 2000. \r\nDepois que você mudar o ATK deste card com este efeito, ele não pode atacar diretamente seu oponente pelo restante do turno e é enviado para o Cemitério durante a Fase Final. \r\nVocê pode oferecer este card como Tributo para escolher 1 monstro "Fóton" ou "Galáxia" em seu Cemitério; adicione o alvo à sua mão.','\r',char(13)),'\n',char(10)),'Colocar um marcador','O ATK deste card se torna 2000','Adicione à sua mão 1 monstro "Fóton" ou "Galáxia" do seu Cemitério','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71074418,'Fazticeira Golem Aruru',replace(replace('Quando seu oponente ativar um card ou efeito que escolha como alvo um ou mais monstros Mago que você controla, ou os escolha como alvo de um ataque (Efeito Rápido): você pode escolher 1 card que seu oponente controla ou 1 Magia "Fazticeira" no seu Cemitério; Invoque este card por Invocação-Especial da sua mão e, se isso acontecer, devolva esse card alvo para a mão. \r\nVocê só pode usar este efeito de "Fazticeira Golem Aruru" uma vez por turno. \r\nUma vez por turno, durante a Fase de Apoio do seu oponente: devolva este card para a mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71083002,'Espiral de Destruição de Táquion',replace(replace('Ative 1 desses efeitos (mas você só pode usar cada efeito de "Espiral de Destruição de Táquion" uma vez por turno);\r\n● Se você controlar um Monstro Xyz "Galáxia": destrua todos os cards com a face para cima que seu oponente controla cujos efeitos foram negados.\r\n● Escolha 1 card "Táquion" no seu Cemitério, exceto "Espiral de Destruição de Táquion"; adicione-o à sua mão.\r\n● Escolha 1 monstro Dragão "Número" no seu Cemitério; Invoque-o por Invocação-Especial em Posição de Defesa.','\r',char(13)),'\n',char(10)),'Destruir','Recuperar','Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71089030,'Prisão Terrestre',replace(replace('Quando este card for ativado: você pode escolher 1 Monstro de Efeito que seu oponente controla; este card ganha este efeito.\r\n● Enquanto este card estiver na Zona do Campo, negue os efeitos desse Monstro de Efeito com a face para cima enquanto ele estiver no campo.	\r\nDurante sua Fase Principal, você pode Invocar por Invocação-Normal 1 monstro "Terrestre" em adição à sua Invocação-Normal/Baixar (padrão). \r\n(Você só pode se aproveitar deste efeito uma vez por turno.) \r\nSe este card em sua posse for destruído por um efeito de card do oponente e você tiver um monstro "Terrestre" no seu campo ou Cemitério: diminua pela metade os PV do seu oponente e, se isso acontecer, até o final deste turno, negue os efeitos de todos os cards com a face para cima que seu oponente controla atualmente.','\r',char(13)),'\n',char(10)),'Invocar pelo efeito de "Prisão Terrestre"','','Escolher como alvo um monstro do oponente?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71095768,'Bujinki Ahashima',replace(replace('2 monstros com o mesmo Nível	\r\nNão pode ser usado como Matéria Link. \r\nVocê só pode usar cada um dos seguintes efeitos de "Bujinki Ahashima" uma vez por turno.\r\n● Se este card for Invocado por Invocação-Link: você pode Invocar por Invocação-Especial 2 monstros com o mesmo Nível, 1 da sua mão e 1 do seu Cemitério, mas negue seus efeitos e, imediatamente depois que este efeito resolver, Invoque por Invocação-Xyz 1 Monstro Xyz usando apenas esses 2 monstros.\r\n● Se um Monstro Xyz para o qual este card apontar ativar um efeito ao desassociar uma ou mais matérias (exceto durante a Etapa de Dano): você pode escolher 1 Magia/Armadilha que seu oponente controla; destrua-a.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71098407,'Perda de Memória','Quando um efeito de um monstro em Posição de Ataque que seu oponente controla for ativado: negue esse efeito e, se isso acontecer, coloque esse monstro com a face para cima em Posição de Defesa.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71100270,'Besta Enlouquecida dos Goblins',replace(replace('2+ monstros de Nível 6	\r\nUma vez por turno (Efeito Rápido): você pode escolher 1 Magia/Armadilha no campo; desassocie 2 matérias de um ou mais monstros no campo e, se isso acontecer, associe o alvo a este card como matéria. \r\nSe um ou mais monstros que você controla seriam destruídos por um efeito de card, em vez disso, você pode desassociar 1 matéria deste card. \r\nSe este card estiver no seu Cemitério: você pode Invocar este card por Invocação-Especial e, depois, você pode associar 1 monstro "Goblin" do seu Cemitério a este card como matéria. \r\nVocê só pode usar este efeito de "Besta Enlouquecida dos Goblins" uma vez por Duelo.','\r',char(13)),'\n',char(10)),'Use um card no campo como Matéria Xyz','Associar a este card 1 monstro "Goblin" do Cemitério como Matéria Xyz?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71101678,'Servente Terrestre Geo Grasha',replace(replace('1 Monstro de Fusão "Terrestre" + 1 Monstro Sincro "Terrestre"	\r\nDeve ser Invocado por Invocação-Fusão. \r\nNo começo da Etapa de Dano, se este card batalhar um monstro: mude o ATK/DEF desse monstro para 0. \r\nSe um ou mais monstros em posse do seu oponente forem destruídos em batalha ou por um efeito de card: você pode destruir todos os cards que seu oponente controla. \r\nVocê só pode usar este efeito de "Servente Terrestre Geo Grasha" uma vez por turno. \r\nSe este card com a face para cima sob o controle do seu dono deixar o campo devido a um card do oponente: você pode Invocar por Invocação-Especial 1 monstro "Terrestre" do seu Deck ou Deck Adicional.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71106375,'Iguana Jurrac','Se este card destruir um monstro do oponente em batalha: você pode escolher 1 card Baixado que seu oponente controla; devolva o alvo para a mão.','Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71107816,'O Carniceiro do Bar','Quando este card inflige dano de batalha ao seu adversário, o seu adversário compra 2 cards do seu próprio Deck.','Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71108540,'Invencível Senhor da Morte',replace(replace('Durante a Fase Final, se um ou mais monstros forem destruídos por batalha neste turno: você pode Invocar por Invocação-Especial este card da sua mão ou Cemitério, e se "Invencível Senhor da Morte" foi destruído por batalha neste turno, o ATK original deste card se torne 3000, ele também não pode ser destruído por efeitos de cards.\r\nDurante sua Fase Principal: você pode revelar cards no seu Deck, incluindo "Sacar da Espada", igual ao número de cards que seu oponente controla +1 e coloque aqueles revelados no topo do Deck em qualquer ordem.\r\nVocê só pode usar cada um dos efeitos de "Invencível Senhor da Morte" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Colocar no topo do Deck','Escolha um card para colocar no topo do Deck.','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71133680,'Sirena Abisnereida',replace(replace('(Efeito Rápido): Você pode descartar este card e, depois, escolher 1 monstro de ÁGUA que você controla; destrua 1 outro monstro de ÁGUA na sua mão ou no campo e, se isso acontecer, até o final deste turno, o monstro escolhido como alvo ganha ATK/DEF igual ao ATK/DEF originais do monstro destruído. \r\nSe este card for enviado do campo para o Cemitério: você pode comprar 1 card e, depois, descartar 1 card. \r\nVocê só pode usar cada efeito de "Sirena Abisnereida" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71143015,'Fusão Definitiva',replace(replace('Durante a Fase Principal: Invoque por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional que mencione "Dragão Branco de Olhos Azuis" ou "Dragão Definitivo de Olhos Azuis" como matéria, ao embaralhar no Deck as matérias mencionadas nele da sua mão, do campo e/ou do Cemitério e, depois, você pode destruir cards com a face para cima que seu oponente controla, até o número de "Dragão Branco de Olhos Azuis" e "Dragão Definitivo de Olhos Azuis" usados do campo como matéria. \r\nVocê só pode ativar 1 "Fusão Definitiva" por turno.','\r',char(13)),'\n',char(10)),'Destruir 1 card que seu oponente controla?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71159974,'Dragão Magichave - Andrabime',replace(replace('1 Monstro de Efeito "Magichave" + 1 Monstro Normal, exceto uma Ficha	\r\nQuando este card for Invocado por Invocação-Fusão, seu oponente não pode ativar cards ou efeitos. \r\nUma vez por turno: você pode escolher 1 Monstro Normal ou monstro "Magichave" no seu Cemitério; destrua todos os monstros que seu oponente controla com o Atributo desse monstro. \r\nUma vez por turno, se um monstro do oponente com o mesmo Atributo que o de um monstro no seu Cemitério for destruído em batalha ou por um efeito de card, se este card foi Invocado por Invocação-Fusão usando 2 Atributos diferentes como matéria: você pode comprar 1 card.','\r',char(13)),'\n',char(10)),'Destrua todos os monstros do oponente com o mesmo Atributo','Comprar','As Matérias de Fusão têm 2 Atributos diferentes','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71164684,'Rompeheart Mannadium',replace(replace('Escolha 1 Regulador ou 1 Monstro Sincro no seu Cemitério; Invoque-o por Invocação-Especial e, depois, se você Invocou por Invocação-Especial um monstro de LUZ, você pode destruir 1 monstro que seu oponente controla com ATK igual ou menor que o desse monstro Invocado por Invocação-Especial. \r\nSe "Visas Starfrost", ou um monstro com 1500 de ATK/2100 de DEF, que você controla seria destruído em batalha ou por um efeito de card, em vez disso, você pode banir este card do seu Cemitério. \r\nVocê só pode usar cada efeito de "Rompeheart Mannadium" uma vez por turno.','\r',char(13)),'\n',char(10)),'Destruir um monstro do oponente?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71166481,'Número 75: Sombra Fofoqueira Enganadora',replace(replace('2+ monstros de Nível 3	\r\nUma vez por turno, quando um monstro do oponente ativar seu efeito (Efeito Rápido): você pode desassociar 2 matérias deste card; o efeito ativado se torna "os dois duelistas compram 1 card". \r\nVocê pode escolher 1 outro Monstro Xyz "Número" que você controla; associe este card a ele como matéria. \r\n(Transfira suas matérias para esse monstro.) \r\nVocê só pode usar este efeito de "Número 75: Sombra Fofoqueira Enganadora" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71172240,'Backlinker',replace(replace('Se somente seu oponente controlar um monstro na Zona de Monstros Adicional, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê pode oferecer este card como Tributo; embaralhe no Deck todos os monstros da Zona do Deck Adicional e, além disso, você não pode Invocar monstros por Invocação-Especial do Deck Adicional pelo resto deste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71175527,'Pilica, Descendente de Gusto',replace(replace('Quando este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 monstro Regulador de VENTO no seu Cemitério; Invoque o alvo por Invocação-Especial em Posição de Defesa com a face para cima. \r\nSeus efeitos são negados. \r\nSe você ativar este efeito, você não pode Invocar monstros por Invocação-Especial pelo restante deste turno, exceto monstros de VENTO. \r\nVocê só pode usar este efeito de "Pilica, Descendente de Gusto" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71181155,'Besta Fantasma Asa-Cruzada','Enquanto este card estiver no Cemitério, todos os monstros "Besta Fantasma" no campo ganham 300 de ATK.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71187462,'Asanegra - Vata, o Emblema da Peregrinação',replace(replace('Se você controlar um monstro "Asanegra" que não seja "Asanegra - Vata, o Emblema da Peregrinação", você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Asanegra - Vata, o Emblema da Peregrinação" por Invocação-Especial uma vez por turno desta forma. \r\nDurante sua Fase Principal: você pode enviar este card no campo para o Cemitério juntamente com 1 ou mais monstros "Asanegra" não-Reguladores do seu Deck cuja soma dos Níveis seja exatamente igual a 8 e, se isso acontecer, Invoque por Invocação-Especial 1 "Dragão de Asas Negras" do seu Deck Adicional e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto monstros de TREVAS. \r\nVocê só pode usar este efeito de "Asanegra - Vata, o Emblema da Peregrinação" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71197066,'Bugiganga Orochi, o Cortador Celeste Serpentron',replace(replace('Se este card estiver na sua mão ou no Cemitério (Efeito Rápido): você pode banir, com a face para baixo, 8 cards do topo do seu Deck; Invoque este card por Invocação-Especial. \r\nVocê pode banir, com a face para baixo, 3 cards do seu Deck Adicional e, depois, escolha 1 monstro com a face para cima no campo; destrua-o. \r\nVocê só pode usar 1 efeito de "Bugiganga Orochi, o Cortador Celeste Serpentron" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71200730,'Desespero do Escuro','Se este card for enviado da sua mão ou do Deck para o seu Cemitério por um efeito de card do oponente: Invoque este card por Invocação-Especial.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71203602,'Evigishki Levianima',replace(replace('Você pode Invocar este card por Invocação-Ritual com qualquer Card de Magia de Ritual "Gishki". \r\nQuando este card declarar um ataque: compre 1 card e, se isso acontecer, revele-o e, depois, se o card revelado for um monstro "Gishki", olhe 1 card aleatório da mão do seu oponente.','\r',char(13)),'\n',char(10)),'Comprar e revelar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71207871,'Seis Samurai Secretos - Fuma',replace(replace('Se este card for destruído em batalha ou por um efeito de card: você pode Invocar por Invocação-Especial 1 monstro "Seis Samurai" do seu Deck, exceto "Seis Samurai Secretos - Fuma". \r\nSe exatamente 1 monstro "Seis Samurai" que você controla (e nenhum outro card) seria destruído por um efeito de card, em vez disso, você pode banir este card do seu Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71209500,'Batedores Amazoness','(Efeito Rápido): você pode oferecer este card como Tributo; neste turno, nenhum duelista pode escolher monstros "Amazoness" que você controla atualmente como alvo de efeitos de monstro e, além disso, eles não podem ser destruídos por efeitos de card.','Proteção','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71218746,'Perfuroide','Antes do cálculo de dano, se este card atacar um monstro em Posição de Defesa: destrua esse monstro.','Destruir monstros em Posição de Defesa','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71222649,'Espectro do Crepúsculo Rayragem',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nSe um ou mais Monstros Pêndulo que você controla seriam destruídos por um efeito de card do oponente, você pode destruir este card em vez de 1 desses Monstros Pêndulo. \r\nVocê só pode usar este efeito de "Espectro do Crepúsculo Rayragem" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe este card estiver na sua mão: você pode escolher 1 Monstro Pêndulo que você controla; coloque esse Monstro Pêndulo na sua Zona de Pêndulo (nenhum duelista pode ativar seus Efeitos de Pêndulo neste turno) e, se isso acontecer, Invoque este card por Invocação-Especial. \r\n(Efeito Rápido): você pode oferecer este card como Tributo e, depois, escolha 1 card na sua Zona de Pêndulo; ele não pode ser destruído pelos efeitos de card do seu oponente neste turno. \r\nVocê só pode usar cada efeito de "Espectro do Crepúsculo Rayragem" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Invocação Especial','Conceder proteção','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71222868,'Ataqueraptor - Falcão da Rebelião Ascendente',replace(replace('5 monstros Besta Alada de Nível 13	\r\nNão é afetado por outros efeitos de cards. \r\nSe este card for Invocado por Invocação-Xyz: você pode destruir tantos cards que seu oponente controla quanto possível e, depois, se este card tiver 3 ou mais Monstros Xyz "Ataqueraptor" com nomes diferentes como matéria, cause dano ao seu oponente igual ao ATK original combinado dos monstros destruídos. \r\nUma vez por turno: você pode desassociar 3 matérias deste card e, depois, escolha 1 Monstro Xyz "Ataqueraptor" no seu Cemitério; este card ganha os efeitos desse monstro até a Fase Final.','\r',char(13)),'\n',char(10)),'Destruir','Ganhar um efeito','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71228611,'Toupeira Eucalipto',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode Invocar por Invocação-Especial 1 monstro Besta de Nível 4 ou menos do seu Deck com a face para baixo em Posição de Defesa e, depois, se este card estiver em Posição de Ataque, coloque-o em Posição de Defesa. \r\nSe este card for destruído: você pode Invocar por Invocação-Especial 1 monstro "Coala" ou 1 "Lontra de Árvore" do seu Deck e, se isso acontecer, aplique este efeito até o final do próximo turno.\r\n● Monstros Besta que não sejam de Efeito que você controla ganham ATK igual à sua DEF original.	\r\nVocê só pode usar cada efeito de "Toupeira Eucalipto" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Invocar por Invocação Especial 1 monstro "Koala"','O efeito de "Toupeira Eucalipto" está sendo aplicado.','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71233859,'Intensificador Fóton','Escolha 1 monstro de LUZ de Nível 4 ou menos no campo, exceto uma Ficha; até o final deste turno, o ATK de todos os monstros com esse nome atualmente no campo se torna 2000.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71249758,'Escudo D2',replace(replace('Selecione 1 monstro com a face para cima em Posição de Defesa que você controla. \r\nSua DEF se torna o dobro de sua DEF original.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71272951,'Excesso de Trabalho','Destrua cada monstro cujo ATK seja maior que seu ATK original.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71275181,'Meio a Meio?',replace(replace('Pegue 1 monstro e 2 Armadilhas do seu Deck e revele-os, seu oponente elege 1 aleatoriamente e você olha os 2 restantes para banir 1 Armadilha dali e, depois, seu oponente seleciona 1 desses efeitos para que você aplique.\r\n● Revele o card que seu oponente elegeu e, se era um monstro, adicione-o à sua mão ou Invoque-o por Invocação-Especial, ou, se não era, bana-o e, além disso, embaralhe o resto no Deck.\r\n● Revele o card que não foi eleito pelo seu oponente nem banido por você e, se era um monstro, adicione-o à sua mão, ou, se não era, bana-o e, além disso, embaralhe o resto no Deck.','\r',char(13)),'\n',char(10)),'Ativar','Confirmar o card selecionado','Confirmar o card não selecionado','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71277255,'Mannadium Riumheart',replace(replace('Durante a Fase Principal, se este card estiver na sua mão (Efeito Rápido): você pode escolher 1 monstro "Mannadium" que você controla ou 1 monstro que você controla com 1500 de ATK/2100 de DEF; destrua-o e, se isso acontecer, Invoque este card por Invocação-Especial. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 card "Mannadium" do seu Deck à sua mão, exceto "Mannadium Riumheart". \r\nVocê só pode usar cada efeito de "Mannadium Riumheart" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71278040,'Paralelo eXcede',replace(replace('Se este card for Invocado por Invocação-Especial pelo efeito de "Paralelo eXcede", seu Nível se torna 4 e seu ATK/DEF originais são diminuídos pela metade. \r\nVocê só pode usar cada um dos seguintes efeitos de "Paralelo eXcede" uma vez por turno.\r\n● Se você Invocar por Invocação-Link: você pode Invocar este card por Invocação-Especial da sua mão em uma zona sua para a qual esse Monstro Link apontar.\r\n● Se este card for Invocado por Invocação-Normal ou Especial: você pode Invocar por Invocação-Especial 1 "Paralelo eXcede" do seu Deck.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71279983,'U.A. Enterrador Couraçado',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) ao devolver 1 monstro "U.A." que você controla para a mão, exceto "U.A. Enterrador Couraçado". \r\nVocê só pode Invocar "U.A. Enterrador Couraçado" por Invocação-Especial uma vez por turno desta forma. \r\nSe este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente. \r\nQuando este card causar dano de batalha ao seu oponente: você pode escolher 1 card no campo; destrua-o.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71280811,'Yaranzo','Uma caixa de tesouros contendo um monstro que ataca bandidos desprevenidos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71283180,'Pássaro Tornado','VIRE: Devolva 2 Cards de Magia ou Armadilha no Campo para as mãos dos respectivos donos.','Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71315423,'Lombriga Millidith',replace(replace('VIRE: Você pode equipar este card a um monstro que seu oponente controla como um Card de Equipamento. \r\nCause 400 de dano ao controlador do monstro equipado durante cada Fase de Apoio.','\r',char(13)),'\n',char(10)),'Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71331215,'Provação Caverguerra',replace(replace('Você só pode controlar 1 "Provação Caverguerra". \r\nQuando este card for ativado: coloque 3 marcadores nele. \r\nQuando um monstro "Caverguerra" seu destruir um monstro do oponente em batalha e enviá-lo para o Cemitério dele: você pode remover 1 marcador deste card e, se isso acontecer, compre 1 card. \r\nSe o último marcador foi removido por este efeito, envie este card para o Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71340250,'Mixeroide',replace(replace('Você pode oferecer como Tributo 1 monstro Máquina; Invoque por Invocação-Especial 1 monstro "roide" que não seja de VENTO do seu Deck. \r\nVocê pode pagar metade dos seus PV e banir qualquer número de monstros Máquina do seu Cemitério, incluindo este card; Invoque por Invocação-Especial do seu Deck Adicional, 1 Monstro de Fusão "roide" com o mesmo Nível que o número desses monstros banidos, ignorando suas condições de Invocação, mas destrua-o durante a Fase Final. \r\nVocê só pode usar cada efeito de "Mixeroide" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Invoque um Monstro Fusão por Invocação Especial','Escolha o Nível do Monstro Fusão a ser Invocado por Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71341529,'Cavaleiro Inférnico','Quando este card no campo for destruído e enviado ao Cemitério: Você pode descartar 2 cards; Invoque por Invocação-Especial este card do seu Cemitério.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71344451,'Sacar da Espada',replace(replace('Descarte 1 card; envie cards do topo do seu Deck para o Cemitério, igual ao número de cards que seu oponente controla e, depois, compre 1 card e mostre-o. \r\nDepois, se era "Sacar da Espada", envie-o para o Cemitério e, se isso acontecer, destrua tantos cards no campo quanto possível e, depois, cause 2000 de dano ao seu oponente para cada card destruído e enviado para o Cemitério por este efeito. \r\nSe o card que você comprou não era "Sacar da Espada", embaralhe cards do seu Cemitério no seu Deck, igual ao número de cards enviados do seu Deck para o Cemitério por este efeito. \r\nVocê só pode ativar 1 "Sacar da Espada" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71345905,'Magia de Redução de Classe Queda Numeron',replace(replace('Escolha 1 monstro "Utopia" que você controla; Invoque por Invocação-Especial do seu Deck Adicional, 1 monstro "Utopia" de Classe menor que o monstro que você controla, ao usá-lo como Matéria Xyz. \r\n(Esta Invocação-Especial é considerada uma Invocação-Xyz. Matérias Xyz associadas a ele também se tornam Matéria Xyz no monstro Invocado.) \r\nO monstro Invocado por Invocação Xyz por este efeito ganha este efeito.\r\n● Se este card atacar ou for atacado por um monstro do oponente, os efeitos do monstro do oponente são negado durante a Fase de Batalha, apenas.','\r',char(13)),'\n',char(10)),'O efeito de "Magia de Redução de Classe Queda Numeron" está sendo aplicado.','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71348837,'Salão Magidoce',replace(replace('Durante sua Fase Principal, você pode Invocar por Invocação-Normal 1 monstro "Magidoce" em adição à sua Invocação-Normal/Baixar (padrão). \r\n(Você só pode se aproveitar deste efeito uma vez por turno.) \r\nSe um ou mais outros cards "Magidoce" que você controla ou no seu Cemitério forem adicionados à sua mão ou embaralhados no seu Deck Principal por um efeito de card: Baixe 1 Magia/Armadilha "Magidoce" diretamente do seu Deck, exceto "Salão Magidoce". \r\nVocê só pode usar este efeito de "Salão Magidoce" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar pelo efeito de "Salão Magidoce"','Baixar 1 Magia/Armadilha do Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71353388,'Borboleta de Junco','Se seu oponente controlar um ou mais Monstros Sincro com a face para cima e você não controlar nenhum Monstro Sincro com a face para cima, você pode Invocar este card por Invocação-Especial da sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71384012,'Pequena Aprendiz de Bruxa',replace(replace('2 monstros de TREVAS	\r\nTodos os monstros de TREVAS no campo ganham 500 de ATK/DEF e, além disso, todos os monstros de LUZ no campo perdem 400 de ATK/DEF. \r\nSe este card for destruído em batalha ou por um efeito de card: você pode escolher 1 monstro de TREVAS no seu Cemitério; adicione-o à sua mão. \r\nVocê só pode usar este efeito de "Pequena Aprendiz de Bruxa" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71386411,'Samurai Superpesado Punho',replace(replace('Durante sua Fase de Batalha, se um monstro "Samurai Superpesado" seu destruiu um monstro do oponente em batalha nesta Fase de Batalha, você pode (Efeito Rápido): imediatamente depois que este efeito resolver, Invocar por Invocação-Sincro 1 Monstro Sincro, usando matérias que você controla, incluindo este card. \r\nSe você não tiver Magias/Armadilhas no seu Cemitério: você pode escolher 1 Monstro Sincro "Samurai Superpesado" que você controla; reduza o Nível dele em 1 e, se isso acontecer, Invoque este card por Invocação-Especial do seu Cemitério e, além disso, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros "Samurai Superpesado". \r\nVocê só pode usar cada efeito de "Samurai Superpesado Punho" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Sincro','Invocação Especial','Escolha o monstro cujo Nível será reduzido','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71395725,'Besta Humana de Ares','Após uma Corrente (de Elo 2 ou mais) ser resolvida, este card ganha 500 de ATK.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71398055,'D/D/D/D Rei Dimensional Crise Arc',replace(replace('Escala de Pêndulo = 13\r\n[ Efeito de Pêndulo ]\r\nVocê pode escolher qualquer número de cards "Pacto Obscuro" que você controla; destrua-os e, depois, você pode Invocar por Invocação-Especial até esse número de Monstros Pêndulo "Rei do Fim" do seu Deck e/ou Deck Adicional. \r\nVocê só pode usar este efeito de "D/D/D/D Rei Dimensional Crise Arc" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\n4 monstros Demônio (1 de Fusão, 1 Sincro, 1 Xyz e 1 Pêndulo)	\r\nDeve ser Invocado por Invocação-Fusão, ou por Invocação-Especial (do seu Deck Adicional com a face para baixo) ao banir os cards acima do seu campo e/ou Cemitério. \r\nVocê só pode Invocar "D/D/D/D Rei Dimensional Crise Arc" por Invocação-Especial uma vez por turno desta forma, não importa o método que usar. \r\nSe este card for Invocado por Invocação-Especial: você pode negar os efeitos de todos os monstros com a face para cima que seu oponente controla atualmente. \r\nPode atacar todos os monstros do seu oponente, uma vez cada. \r\nSe este card na Zona de Monstros for destruído: você pode colocar este card na sua Zona de Pêndulo.','\r',char(13)),'\n',char(10)),'Efeito de destruição','Negar o efeito','Colocar na Zona de Pêndulo','Invocação Especial?','','','','','','','','','','','','');
INSERT INTO texts VALUES(71406430,'Doombroker Livromante',replace(replace('Você pode Invocar este card por Invocação-Ritual com um card "Livromante". \r\nSe este card for Invocado por Invocação-Ritual ao usar um ou mais monstros no campo, ele pode atacar diretamente. \r\nVocê só pode usar cada um dos seguintes efeitos de "Doombroker Livromante" uma vez por turno. \r\nDurante sua Fase Principal: você pode Baixar 1 Armadilha "Livromante" diretamente do seu Deck. \r\nQuando este card causar dano de batalha ao seu oponente: você pode escolher 1 monstro com a face para cima que seu oponente controla; embaralhe-o no Deck.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Ritual usando monstros no campo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71407486,'Fireyarou','Uma criatura maléfica envolvida em chamas que ataca os inimigos com fogo intenso.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71408082,'Paladino do Dragão Negro',replace(replace('Você pode Invocar este card por Invocação-Ritual com "Ritual do Dragão Negro". \r\nNo começo da Etapa de Dano, se este card atacar um monstro em Posição de Defesa: destrua o monstro. \r\nVocê pode oferecer este card como Tributo; Invoque por Invocação-Especial 1 monstro "Olhos Vermelhos" da sua mão ou do Deck. \r\nVocê só pode usar este efeito de "Paladino do Dragão Negro" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71410542,'DESPERTAÇA! Macchia',replace(replace('VIRE: Escolha 1 monstro com a face para baixo em Posição de Defesa no campo; coloque-o com a face para cima em Posição de Ataque.\r\nVocê pode revelar este card e 1 monstro de Virar na sua mão; Invoque os dois por Invocação-Especial com a face para baixo em Posição de Defesa. \r\nVocê só pode usar cada um dos efeitos anteriores de "DESPERTAÇA! Macchia" uma vez por turno. \r\nUma vez por turno, durante sua Fase Final: você pode escolher 1 card com a face para baixo no campo; envie-o para o Cemitério.','\r',char(13)),'\n',char(10)),'Invocação Especial','Alterar posição de batalha','Enviar para o Cemitério','Revelado pelo efeito de "DESPERTAÇA! Macchia"','','','','','','','','','','','','');
INSERT INTO texts VALUES(71411377,'Guarda da Rainha','Monstros "Rainha Cativante" no seu lado do campo não podem ser selecionados como alvos de ataque.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71413901,'Breaker, o Guerreiro Mágico',replace(replace('Se este card for Invocado por Invocação-Normal: coloque 1 Marcador de Magia nele (máx. 1). \r\nGanha 300 de ATK para cada Marcador de Magia nele. \r\nVocê pode remover 1 Marcador de Magia deste card e, depois, escolha 1 Magia/Armadilha no campo; destrua o alvo.','\r',char(13)),'\n',char(10)),'Colocar Marcadores de Magia','Aumentar ATK','Destrua 1 Card de Magia/Armadilha','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71413902,'Breaker, o Guerreiro Mágico',replace(replace('Se este card for Invocado por Invocação-Normal: coloque 1 Marcador de Magia nele (máx. 1). \r\nGanha 300 de ATK para cada Marcador de Magia nele. \r\nVocê pode remover 1 Marcador de Magia deste card e, depois, escolha 1 Magia/Armadilha no campo; destrua o alvo.','\r',char(13)),'\n',char(10)),'Colocar Marcadores de Magia','Aumentar ATK','Destrua 1 Card de Magia/Armadilha','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71415349,'Humpty Grumpty',replace(replace('Uma vez por turno: você pode colocar este card com a face para baixo em Posição de Defesa. \r\nSe este card for Invocado por Invocação-Virar: ele ganha 800 de ATK até o final deste turno.','\r',char(13)),'\n',char(10)),'Mudar para a posição com a face para baixo','Alterar ATK/DEF','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71417170,'Cruzamento de Defensores',replace(replace('Só pode ser ativado durante a Fase de Batalha. \r\nMonstros em Posição de Defesa que seu oponente controla são colocados com a face para cima em Posição de Ataque e seus efeitos são negados.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71422989,'Absorver Fusão',replace(replace('Adicione 1 card "Cavaleiro-Gema" do seu Deck à sua mão e, depois, você pode aplicar este efeito.\r\n● Invoque por Invocação-Fusão 1 Monstro de Fusão "Cavaleiro-Gema" do seu Deck Adicional, ao banir suas matérias da sua mão ou do campo.	\r\nVocê só pode ativar 1 "Absorver Fusão" por turno. \r\nVocê não pode Invocar por Invocação-Especial no turno em que ativar este card, exceto monstros "Cavaleiro-Gema".','\r',char(13)),'\n',char(10)),'Invoque por Invocação Fusão um Monstro Fusão "Cavaleiro-Gema"','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71438011,'Blindagem Trovejante, Aliado da Justiça',replace(replace('Não pode ser Invocado por Invocação-Especial. \r\nSe um monstro "Aliado da Justiça" seu atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71440209,'Talismã de Magia Negra',replace(replace('Você pode ativar este card no turno em que foi Baixado, ao revelar 1 monstro Mago na sua mão. \r\nQuando um efeito de monstro for ativado em resposta à ativação de um card ou efeito de um card que mencione "Mago Negro": negue o efeito e, se isso acontecer, pelo resto deste turno, negue os efeitos ativados de monstros com esse mesmo nome original. \r\nSe você Invocar "Mago Negro" por Invocação-Especial enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode pagar 2500 PV; Baixe este card.','\r',char(13)),'\n',char(10)),'Ativar aplicando o efeito de "Talismã de Magia Negra".','Negar','Baixar','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71442223,'Renascimento Cúbico',replace(replace('Quando um monstro do oponente declarar um ataque direto: escolha o monstro atacante; seu oponente Invoca por Invocação-Especial, em Posição de Ataque, tantos monstros quanto possível da mão, Deck e/ou Cemitério com o mesmo nome que esse monstro e, além disso, o ATK do monstro escolhido e desses monstros Invocados por Invocação-Especial se torna 0 e coloque 1 Marcador Cúbico em cada um deles. \r\n(Monstros com um Marcador Cúbico não podem atacar e, além disso, negue seus efeitos.) \r\nAlém disso, depois, se qualquer Marcador Cúbico foi colocado por este efeito, Invoque por Invocação-Especial 1 monstro "Cúbico(a)" de Nível 4 ou menos da sua mão, ignorando suas condições de Invocação.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71453557,'Unidade de Ação Autônoma',replace(replace('Pague 1500 PV e, depois, escolha 1 monstro no Cemitério do seu oponente; Invoque-o por Invocação-Especial no seu campo em Posição de Ataque e equipe-o com este card. \r\nQuando este card deixar o campo, destrua o monstro equipado.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71456737,'Vespabatalha - Sachi, o Arco Cerimonial',replace(replace('1 Regulador Inseto + 1+ monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro: você pode considerá-lo como um Regulador. \r\nUma vez por turno: você pode devolver 1 Magia Contínua que você controla para a mão; você pode Invocar por Invocação-Normal 1 monstro "Vespabatalha" durante sua Fase Principal neste turno, em adição à sua Invocação-Normal/Baixar (padrão). \r\n(Você só pode se aproveitar deste efeito uma vez por turno.) \r\nSe este card for enviado para o Cemitério como Matéria Sincro: você pode causar 100 de dano ao seu oponente para cada um dos seus monstros "Vespabatalha" banidos. \r\nVocê só pode usar este efeito de "Vespabatalha - Sachi, o Arco Cerimonial" uma vez por turno.','\r',char(13)),'\n',char(10)),'Considerar como um Regulador','Invocar','Causar dano','Invocar pelo efeito de "Vespabatalha - Sachi, o Arco Cerimonial"','','','','','','','','','','','','');
INSERT INTO texts VALUES(71459017,'Hinezumi Hanabi',replace(replace('Não pode ser usado como matéria para uma Invocação-Fusão, Sincro, Xyz ou Link. \r\nSe este card for Invocado por Invocação-Normal ou Especial: coloque 6 marcadores nele. \r\nUma vez por turno, durante sua Fase Final: conceda o controle deste card ao seu oponente. \r\nUma vez por turno, se o controle deste card com a face para cima com um ou mais marcadores mudar: lance um dado de seis faces, remova tantos marcadores deste card quanto possível, até o resultado e se todos os marcadores deste card forem removidos por este efeito, destrua este card e, se isso acontecer, sofra 2000 de dano.','\r',char(13)),'\n',char(10)),'Colocar um marcador','Transferir o controle','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71459861,'Invocar Tempestade',replace(replace('Pague 800 PV; Invoque por Invocação-Especial 1 monstro de VENTO de Nível 6 ou menos da sua mão. \r\nDurante sua Fase Principal, exceto no turno em que este card foi enviado para o Cemitério: você pode banir este card do seu Cemitério; Invoque por Invocação-Especial 1 monstro de VENTO de Nível 4 ou menos da sua mão. \r\nVocê só pode usar este efeito de "Invocar Tempestade" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invoque por Invocação Especial 1 monstro de VENTO de Nível 6 ou menos da mão','Invoque por Invocação Especial 1 monstro de VENTO de Nível 4 ou menos da mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71466592,'Maryokutai','Durante o turno do seu oponente, quando seu oponente ativar um Card de Magia (Efeito Rápido): você pode oferecer este card como Tributo; negue a ativação e, se isso acontecer, destrua-o.','Negue a ativação de um Card de Magia e destrua-o','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71490127,'Espelho Dragão','Invoque por Invocação-Fusão 1 Monstro de Fusão Dragão do seu Deck Adicional, ao banir as Matérias de Fusão listadas nele do seu campo ou do Cemitério.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71519605,'Oshaleon',replace(replace('Enquanto você controlar este card com a face para cima em Posição de Ataque, seu oponente não pode selecionar um monstro que não seja "Oshaleon" como alvo de um ataque. \r\nQuando este card for destruído em batalha e enviado ao Cemitério, você pode adicionar 1 monstro do Tipo Réptil com 500 de ATK ou menos do seu Deck para a sua mão.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71521025,'Florescer Vermelho de Raiz Inferior',replace(replace('Se este card estiver na sua mão: você pode escolher 1 Magia/Armadilha em cada Cemitério; bana-as e, se isso acontecer, Invoque este card por Invocação-Especial. \r\nVocê pode oferecer este card como Tributo e, depois, escolha 1 Monstro de Fusão, Sincro, Xyz ou Link em qualquer Cemitério; bana o alvo e, se isso acontecer, Invoque por Invocação-Especial 1 monstro do seu Cemitério com um tipo de card de monstro diferente (Fusão, Sincro, Xyz ou Link) que o do alvo. \r\nVocê só pode usar cada efeito de "Florescer Vermelho de Raiz Inferior" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71525232,'Gandora-X, o Dragão da Demolição',replace(replace('Quando este card for Invocado por Invocação-Normal ou Especial da mão: você pode destruir tantos outros monstros no campo quanto possível e, se isso acontecer, cause dano ao seu oponente igual ao maior ATK original no campo dentre esses monstros destruídos (em caso de empate, você seleciona). \r\nO ATK deste card se torna igual ao dano causado ao seu oponente por este efeito. \r\nUma vez por turno, durante sua Fase Final: diminua pela metade seus PV.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71541986,'Resquícios da Dimensão Xyz',replace(replace('Se este card, Baixado, for banido: você pode Invocar por Invocação-Especial 2 monstros de ÁGUA de Nível 8 do seu Deck. \r\nSeus efeitos são negados e eles não podem declarar ataque ou serem oferecidos como Tributos.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71544954,'Dragão Mega-Rocha',replace(replace('Este card não pode ser Invocado, por Invocação-Normal, ou Baixado. \r\nEste card não pode ser Invocado, por Invocação-Especial, exceto removendo de jogo monstro(s) do Tipo Rocha no seu Cemitério. \r\nO ATK e a DEF original deste card tornam-se no número de monstros do Tipo Rocha que você removeu de jogo quando você Invocou, por Invocação-Especial, este card x 700 pontos.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71545247,'Boneca de Noiva Amaldiçoada',replace(replace('Quando você comprar este card: você pode revelá-lo; Invoque este card por Invocação-Especial. \r\nNo começo de cada Fase de Batalha: se houver mais cards no seu Deck que no do seu oponente, até o final deste turno, este card ganha ATK igual à diferença x 300. \r\nUma vez por turno, durante a Fase Final, se este card estiver no Cemitério porque foi enviado para lá neste turno: coloque este card no topo do Deck.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71549257,'Desafiante Heroico - Espada Inglesa',replace(replace('Se você controlar um monstro "Heroico(a)", exceto um monstro de Nível 1: você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 outro monstro Guerreiro que você controla com um Nível; o Nível desse monstro ou deste card se torna o Nível do outro e, além disso, você não pode declarar um ataque pelo resto deste turno, exceto com Monstros Xyz. \r\nVocê só pode usar cada efeito de "Desafiante Heroico - Espada Inglesa" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Escolha um card com o Nível qual você quer que se torne','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71555408,'Gouki Garras de Ferro',replace(replace('Durante a Etapa de Dano, quando um monstro "Gouki" seu batalhar um monstro do oponente (Efeito Rápido): você pode enviar este card da sua mão para o Cemitério; até o final deste turno, seu monstro ganha 500 de ATK e, se isso acontecer, ele não é afetado pelos efeitos de card do seu oponente. \r\nSe este card for enviado do campo para o Cemitério: você pode adicionar 1 card "Gouki" do seu Deck à sua mão, exceto "Gouki Garras de Ferro". \r\nVocê só pode usar cada efeito de "Gouki Garras de Ferro" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71564150,'Malicioso Mestre das Marionetes',replace(replace('Uma vez por turno: Você pode descartar 1 card; ganhe o controle de todos os monstros de Nível 3 ou menos com a face para cima que seu oponente controla até a Fase Final. \r\nEsses monstros não podem ativar seus efeitos e não podem ser oferecidos como Tributo ou usados como um Monstro-Matéria Sincro.','\r',char(13)),'\n',char(10)),'Tomar controle','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71564252,'Rei do Trovão Rai-Oh',replace(replace('Nenhum duelista pode adicionar cards do seu Deck à sua mão, exceto ao comprá-los. \r\nQuando seu oponente Invocaria exatamente 1 monstro por Invocação-Especial (Efeito Rápido): você pode enviar este card com a face para cima para o Cemitério; negue a Invocação-Especial e, se isso acontecer, destrua-o.','\r',char(13)),'\n',char(10)),'Negar a Invocação Especial e destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71564253,'Rei do Trovão Rai-Oh',replace(replace('Nenhum duelista pode adicionar cards do seu Deck à sua mão, exceto ao comprá-los. \r\nQuando seu oponente Invocaria exatamente 1 monstro por Invocação-Especial (Efeito Rápido): você pode enviar este card com a face para cima para o Cemitério; negue a Invocação-Especial e, se isso acontecer, destrua-o.','\r',char(13)),'\n',char(10)),'Negar a Invocação Especial e destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71578874,'Camaramágico Espelho Condutor',replace(replace('Escala de Pêndulo = 3\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno: você pode escolher 1 monstro com a face para cima no campo Invocado por Invocação-Especial; seu ATK e DEF se tornam igual ao seu ATK e DEF atuais (o que for menor) até o final deste turno (mesmo que este card deixe o campo).\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nUma vez por turno, durante o turno de qualquer duelista: você pode escolher 1 monstro com a face para cima no campo; troque o ATK atual pela DEF atual dele e, depois, sofra 500 de dano. \r\nEsta troca de ATK e DEF dura até o final deste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71583486,'Cadela Mary Fantástica',replace(replace('Se este card for enviado para o Cemitério: você pode ativar 1 desses efeitos;\r\n● Coloque este card no fundo do seu Deck.\r\n● Adicione 1 "Cão Marron Fantástico" do seu Deck à sua mão e, se isso acontecer, coloque este card no topo do seu Deck.	\r\nVocê só pode usar este efeito de "Cadela Mary Fantástica" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar o efeito escolhido','Coloque este card no fundo do Deck','Adicione 1 "Cão Marron Fantástico" do seu Deck à sua mão','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71587526,'Corte do Carma','Descarte 1 card e, depois, escolha 1 monstro com a face para cima que seu oponente controla; bana o alvo e, depois, bana do Cemitério do seu oponente todos os cards com o mesmo nome que o desse monstro.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71593652,'Motim no Céu',replace(replace('Invoque por Invocação-Fusão 1 Monstro de Fusão Demônio ou Fada do seu Deck Adicional, ao embaralhar no Deck monstros Demônio e/ou Fada do seu Cemitério como matéria. \r\nSe este card estiver no seu Cemitério: você pode enviar 1 monstro Demônio ou Fada da sua mão ou do campo com a face para cima para o Cemitério; adicione este card à sua mão. \r\nVocê só pode usar cada efeito de "Motim no Céu" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Fusão','Adicionar este card à sua mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71594310,'Cavaleiro-Gema Pérola','2 monstros de Nível 4','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71595845,'Felicidade da Boneca',replace(replace('Quando este card for ativado: adicione 1 "Vovô Demetto" ou "Caixa de Amigos" do seu Deck à sua mão. \r\nEnquanto você controlar "Princesa Colônia", os monstros do seu oponente não podem escolher monstros com 0 de ATK ou de DEF como alvo de ataques. \r\nUma vez por turno: você pode destruir 1 monstro na sua mão ou no campo e, se isso acontecer, envie 1 card "Monstro Boneca" do seu Deck para o Cemitério e, além disso, você não pode Invocar monstros por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto Monstros Xyz. \r\nVocê só pode ativar "Felicidade da Boneca" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71607202,'Sensacionalistas do Submundo',replace(replace('2 Monstros de Efeito	\r\nNão pode ser usado como Matéria Link no turno em que for Invocado por Invocação-Link. \r\nSe um ou mais monstros que você controla seriam destruídos em batalha ou por um efeito de card, em vez disso, você pode oferecer como Tributo 1 monstro Demônio. \r\nVocê pode escolher 1 monstro Demônio no seu Cemitério, exceto "Sensacionalistas do Submundo"; descarte 1 card e, se isso acontecer, Invoque esse monstro por Invocação-Especial e, além disso, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros Demônio. \r\nVocê só pode usar este efeito de "Sensacionalistas do Submundo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71612253,'D/D/D Tell, o Rei Atirador',replace(replace('2 monstros de Nível 5	\r\nVocê também pode Invocar este card por Invocação-Xyz ao usar um Monstro Xyz "D/D/D" de Classe 4 que você controla (transfira as matérias dele para este card). \r\nUma vez por turno, se você sofreu qualquer dano de efeito neste turno (Efeito Rápido): você pode desassociar 1 matéria deste card e, depois, escolha 1 monstro com a face para cima no campo; ele perde 1000 de ATK/DEF e, se isso acontecer, cause 1000 de dano ao seu oponente. \r\nSe este card for enviado do campo para o Cemitério: você pode enviar 1 card "D/D" ou "Pacto Obscuro" do seu Deck para o Cemitério.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Xyz sobrepondo um Monstro Xyz "D/D/D" de Classe 4?','Reduzir ATK/DEF e causar dano','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71614230,'Espírito do Kendo Kai-Den',replace(replace('Escala de Pêndulo = 9\r\n[ Efeito de Pêndulo ]\r\nSe um ou mais monstros forem Invocados por Invocação-Pêndulo: devolva este card da Zona de Pêndulo para a mão.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nQuando este card for Invocado por Invocação-Normal: você pode selecionar 1 card na sua Zona de Pêndulo e enviar para o Cemitério todos os cards que seu oponente controla na mesma coluna que esse card. \r\nUma vez por turno, durante a Fase Final, se este card foi Invocado por Invocação-Normal ou virado com a face para cima neste turno: devolva este card para a mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71616908,'Cavaleiro-Gema Ametista',replace(replace('1 monstro "Cavaleiro-Gema" + 1 monstro Aqua	\r\nPrimeiro deve ser Invocado por Invocação-Fusão. \r\nSe este card for enviado do campo para o Cemitério: devolva todas as Magias/Armadilhas Baixadas no campo para a mão.','\r',char(13)),'\n',char(10)),'Retornar para a mão todas as Magias/Armadilhas Baixadas','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71620241,'Fera Cristalina Avançada Pégaso Safira',replace(replace('Se "Trevas Avançadas" não estiver em uma Zona do Campo, envie este monstro para o Cemitério. \r\nSe este card for Invocado: você pode colocar 1 dos seus monstros "Fera Cristalina Avançada" que estiverem banidos, ou na sua mão, no Deck ou no Cemitério, com a face para cima na sua Zona de Magias & Armadilhas como uma Magia Contínua. \r\nSe este card com a face para cima for destruído em uma Zona de Monstros, em vez de enviá-lo para o Cemitério, você pode colocá-lo com a face para cima na sua Zona de Magias & Armadilhas como uma Magia Contínua.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71625222,'Mago do Tempo',replace(replace('Uma vez por turno: você pode lançar uma moeda e escolher cara ou coroa. \r\nSe você ganhar, destrua todos os monstros que seu oponente controla. \r\nSe você perder, destrua tantos monstros que você controla quanto possível e, se isso acontecer, sofra dano igual à metade da soma do ATK que esses monstros destruídos tinham enquanto estavam com a face para cima no campo.','\r',char(13)),'\n',char(10)),'Escolher cara ou coroa','Escolha cara ou coroa','Coroa','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71625223,'Mago do Tempo',replace(replace('Uma vez por turno: você pode lançar uma moeda e escolher cara ou coroa. \r\nSe você ganhar, destrua todos os monstros que seu oponente controla. \r\nSe você perder, destrua tantos monstros que você controla quanto possível e, se isso acontecer, sofra dano igual à metade da soma do ATK que esses monstros destruídos tinham enquanto estavam com a face para cima no campo.','\r',char(13)),'\n',char(10)),'Escolher cara ou coroa','Escolha cara ou coroa','Coroa','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71625224,'Mago do Tempo',replace(replace('Uma vez por turno: você pode lançar uma moeda e escolher cara ou coroa. \r\nSe você ganhar, destrua todos os monstros que seu oponente controla. \r\nSe você perder, destrua tantos monstros que você controla quanto possível e, se isso acontecer, sofra dano igual à metade da soma do ATK que esses monstros destruídos tinham enquanto estavam com a face para cima no campo.','\r',char(13)),'\n',char(10)),'Escolher cara ou coroa','Escolha cara ou coroa','Coroa','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71628381,'Golem de Fragmentos Múltiplos',replace(replace('"Golem de Fragmento Grande" + "Golem de Fragmento Médio"	\r\nNo final da Fase de Batalha, se este card atacou ou foi atacado, você pode devolvê-lo para o Deck Adicional. \r\nDepois, se todos os Monstros-Matéria de Fusão que foram usados para a Invocação-Fusão deste card estiverem no seu Cemitério, você pode Invocá-los por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Retornar ao Deck Adicional','Invocar Matérias de Fusão por Invocação Especial?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71645242,'Jardim Negro',replace(replace('Se um ou mais monstros forem Invocados por Invocação-Normal ou Especial com a face para cima, exceto pelo efeito de "Jardim Negro": diminua o ATK deles pela metade e, depois, o controlador desse(s) monstro(s) \r\nInvoca por Invocação-Especial 1 "Ficha de Rosa" (Planta/TREVAS/Nível 2/ATK 800/DEF 800) no campo do seu oponente, em Posição de Ataque. \r\n(Esta perda de ATK permanece mesmo que este card deixe o campo.) \r\nVocê pode escolher 1 monstro no seu Cemitério com ATK igual à soma do ATK de todos os monstros Planta no campo; destrua este card e tantos monstros Planta no campo quanto possível e, depois, se você destruiu todos eles, Invoque o monstro alvo por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Reduza o ATK pela metade e Invoque uma Ficha por Invocação Especial','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71645243,'Ficha de Rosa','Invocado por Especial com o efeito "Jardim Negro" ou um card relacionado.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71645463,'Quirinus Dragunidade',replace(replace('Enquanto este card estiver equipado com um Card de Equipamento, seus monstros "Dragunidade" não podem ser destruídos em batalha. \r\nVocê só pode usar cada um dos seguintes efeitos de "Quirinus Dragunidade" uma vez por turno. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 Magia/Armadilha "Dragunidade" do seu Deck à sua mão. \r\nVocê pode escolher 1 outro Card de Monstro "Dragunidade" que você controla; devolva-o para a mão/Deck Adicional e, depois, você pode Invocar por Invocação-Especial 1 monstro "Dragunidade" da sua mão.','\r',char(13)),'\n',char(10)),'Efeito de busca','Retornar à mão/Deck Adicional','Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71650854,'Campo Mágico de Dissociação',replace(replace('Ative este card no começo da sua Fase Principal 1 ou 2. \r\nDurante a Fase Principal 1 de cada duelista, monstros no campo não podem ser destruídos por efeitos de card do seu oponente e, além disso, nenhum duelista pode escolher como alvo monstros que seu oponente controla. \r\nVocê não pode ativar ou Baixar Cards de Magia de Campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71652522,'Teleporte de Batalha',replace(replace('Ative se você controlar somente 1 monstro do Tipo Psíquico com a face para cima e selecione esse monstro. \r\nEle pode atacar seu oponente diretamente neste turno. \r\nNo final da Fase de Batalha, conceda o controle desse monstro ao seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71692913,'Mago Xiangke',replace(replace('Escala de Pêndulo = 3\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno: você pode escolher 1 Monstro Xyz com a face para cima que você controla; neste tuno, você pode usá-lo como uma Matéria Xyz para uma Invocação-Xyz usando a Classe dele como se fosse o Nível (mesmo que este card deixe o campo).\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nUma vez por turno, durante o turno de qualquer duelista: você pode escolher 1 monstro de LUZ no campo; esse monstro com a face para cima tem seus efeitos negados até o final deste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71696014,'Túnica do Mago',replace(replace('Durante o turno do seu oponente (Efeito Rápido): você pode descartar 1 Magia/Armadilha; Invoque por Invocação-Especial 1 "Mago Negro" do seu Deck. \r\nDurante o turno do seu oponente, se você ativar um Card de Magia/Armadilha ou seus efeitos enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar cada efeito de "Túnica do Mago" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Invocar este card por Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71703785,'Mahad, o Oráculo de Paládio',replace(replace('Quando você comprar este card: você pode revelar este card; Invoque-o por Invocação-Especial da sua mão. \r\nSe este card batalhar um monstro de TREVAS, seu ATK é dobrado, apenas durante a Etapa de Dano. \r\nSe este card for destruído em batalha ou por um efeito de card: você pode Invocar por Invocação-Especial 1 "Mago Negro" da sua mão, Deck ou Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71705144,'Renovar Elenco Camarartista',replace(replace('Revele qualquer número de monstros "Camarartista" da sua mão e embaralhe-os no Deck e, depois, compre cards igual ao número de cards que você embaralhou no Deck +1. \r\nVocê só pode ativar 1 "Renovar Elenco Camarartista" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71717923,'Mormolito','Você pode oferecer como Tributo 1 monstro de TERRA com a face para cima para destruir todos os monstros com a face para cima com a DEF igual ou menor que o ATK do card Tributado.','Destruir um monstro','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71734607,'Pétala Rikka',replace(replace('Durante sua Fase Principal: você pode pegar 1 monstro "Rikka" do seu Deck, exceto "Pétala Rikka", e adicione-o à sua mão ou envie-o para o Cemitério e, além disso, você não pode Invocar por Invocação-Especial pelo resto deste turno, exceto monstros Planta. \r\nDurante a Fase Final do seu oponente, enquanto este card estiver no seu Cemitério, se você não controlar nenhum monstro ou todos os monstros que você controla forem monstros Planta: você pode Invocar este card por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Pétala Rikka" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Escolha um card para adicionar à sua mão ou enviar para o Cemitério','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71736213,'Cavalo dos Cavaleiros Florais',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 monstro "Nobre Cavaleiro" de LUZ do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Cavalo dos Cavaleiros Florais" uma vez por turno. \r\nUma vez por turno, durante sua Fase Principal: você pode Invocar por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional, usando este card que você controla e outros monstros da sua mão ou do campo como Matéria de Fusão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71746462,'Kamen do Mar','Um monstro misericordioso que destroça seus oponentes com garras afiadas como navalhas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71750854,'Bombardeiro Posicionador',replace(replace('Uma vez por Corrente (Efeito Rápido): você pode pagar 600 PV e, depois, ative 1 desses efeitos;\r\n● Se você controlar 6 monstros com Níveis diferentes (1, 2, 3, 4, 5 e 6): selecione 1 monstro com a face para cima que seu oponente controla com um Nível, e destrua todos os outros monstros que seu oponente controla com o mesmo Nível/Classe/Valor Link desse monstro.\r\n● Selecione 1 monstro com a face para cima que você controla com um Nível, e destrua todos os monstros do seu oponente na mesma coluna com o mesmo Nível/Classe/Valor Link desse monstro.','\r',char(13)),'\n',char(10)),'Escolha um monstro do oponente','Escolha um monstro que você controla','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71759912,'Lontra de Árvore',replace(replace('Uma vez por turno: você pode escolher 1 monstro com a face para cima que você controla; ele ganha 1000 de ATK até o final deste turno. \r\nVocê deve controlar um monstro do Tipo Besta (que não seja este card) para ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71768839,'E.A.I. -Espécies Alienígenas Invasivas-',replace(replace('Não pode ser destruído em batalha ou por efeitos de card enquanto seu oponente tiver um card com a face para cima na Zona do Campo dele. \r\nVocê só pode usar cada um dos seguintes efeitos de "E.A.I. -Espécies Alienígenas Invasivas-" uma vez por turno. \r\nSe seu oponente tiver um card com a face para cima na Zona do Campo dele: você pode escolher 1 monstro que ele controla; destrua-o e, se isso acontecer, este card ganha 1000 de ATK. \r\nSe seu oponente tiver um card com a face para cima na Zona do Campo dele, enquanto este card estiver no seu Cemitério: você pode Invocar este card por Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71771004,'Preparar Ritos',replace(replace('Adicione 1 Monstro de Ritual Demônio do seu Deck à sua mão e, depois, se você adicionou um Monstro Pêndulo, você pode Invocar por Invocação-Especial 1 "Ficha de Oferenda de Sacrifício" (Demônio/TREVAS/Nível 1/ATK 300/DEF 300). \r\nEnquanto você controlar essa Ficha, você não pode Invocar por Invocação-Especial do Deck Adicional. \r\nQuando um Monstro de Ritual seu causar dano de batalha ao seu oponente: você pode banir este card do seu Cemitério; compre 1 card. \r\nVocê só pode usar cada efeito de "Preparar Ritos" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Comprar','Invocar uma Ficha por Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71771005,'Ficha de Oferenda de Sacrifício','Invocado por Especial com o efeito "Preparar Ritos".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71782404,'Queimadura dos Olhos Vermelhos',replace(replace('Se um ou mais monstros "Olhos Vermelhos" com a face para cima que você controla forem destruídos em batalha ou por um efeito de card: escolha 1 desses monstros; os dois duelistas sofrem dano igual ao ATK original dele. \r\nVocê só pode ativar 1 "Queimadura dos Olhos Vermelhos" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71786742,'Engrenagiano','Você pode oferecer este card como Tributo e, depois, escolher 1 monstro do Tipo Máquina de Nível 4 no seu Cemitério; Invoque-o por Invocação-Especial, mas seus efeitos são negados.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71791814,'Mágico Mosqueteiro Max',replace(replace('1 monstro "Mágico(a) Mosqueteiro" de Nível 8 ou menos	\r\nSe este card for Invocado por Invocação-Link: você pode ativar 1 desses efeitos;\r\n● Adicione Magias/Armadilhas "Mágico(a) Mosqueteiro" com nomes diferentes do seu Deck à sua mão, até o número de monstros que seu oponente controla.\r\n● Invoque por Invocação-Especial monstros "Mágico(a) Mosqueteiro" com nomes diferentes do seu Deck, até o número de Magias/Armadilhas que seu oponente controla.	\r\nVocê só pode usar este efeito de "Mágico Mosqueteiro Max" uma vez por turno. \r\nDurante o turno de qualquer duelista, você pode ativar Cards de Magia/Armadilha "Mágico(a) Mosqueteiro" da sua mão.','\r',char(13)),'\n',char(10)),'Adicionar à mão uma Magia/Armadilha','Invocação Especial','Continuar selecionando?','Continuar selecionando?','Ativar aplicando o efeito de "Mágico Mosqueteiro Max".','','','','','','','','','','','');
INSERT INTO texts VALUES(71797713,'Sabrelemento Lapauila Mana',replace(replace('Você pode enviar 2 outros monstros da sua mão para o Cemitério; Invoque este card por Invocação-Especial da sua mão. \r\nVocê só pode usar este efeito de "Sabrelemento Lapauila Mana" uma vez por turno. \r\nAplique o(s) seguinte(s) efeito(s) aos monstros "Sabrelemento" e "Senhor Elemental" que você controla, dependendo dos Atributos originais de quaisquer monstros "Sabrelemento" enviados para o Cemitério para ativar o efeito deste card.\r\n● TERRA ou VENTO: Não pode ser destruído em batalha.\r\n● ÁGUA ou FOGO: Não pode ser destruído por efeitos.\r\n● LUZ ou TREVAS: Seu oponente não pode escolhê-lo como alvo de efeitos de card.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial da mão','Invocar por Invocação Especial usando TERRA/VENTO','Invocar por Invocação Especial usando ÁGUA/FOGO','Invocar por Invocação Especial usando LUZ/TREVAS','','','','','','','','','','','','');
INSERT INTO texts VALUES(71799173,'Guardião da Ordem',replace(replace('Se você controlar 2 ou mais monstros de LUZ, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode controlar 1 "Guardião da Ordem".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71801447,'Eneanave - Atil.SPIA',replace(replace('Escala de Pêndulo = 0\r\n[ Efeito de Pêndulo ]\r\nSempre que um ou mais monstros forem virados com a face para cima, coloque 1 Marcador de E.N. neste card. \r\nNo final da Fase de Batalha, se você tiver um card "Eneanave" na sua outra Zona de Pêndulo: você pode escolher 1 monstro que seu oponente controla com ATK menor que o deste card; destrua-o.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nDepois que este card foi virado com a face para cima, enquanto ele estiver na Zona de Monstros, seu oponente não pode ativar cards ou efeitos em resposta à ativação dos cards ou efeitos dele. \r\nQuando seu oponente ativar um card ou efeito como Elo de Corrente 3 ou mais (Efeito Rápido): você pode colocar este card que estiver com a face para baixo, com a face para cima em Posição de Defesa; negue a ativação dos cards e efeitos do seu oponente ativados antes deste card nesta Corrente e, se isso acontecer, destrua-os. \r\nVocê pode revelar este card na sua mão; Invoque por Invocação-Especial 1 monstro da sua mão com a face para baixo em Posição de Defesa. \r\nVocê não pode Invocar por Invocação-Especial no turno em que ativar este efeito, exceto com a face para baixo em Posição de Defesa.','\r',char(13)),'\n',char(10)),'Destruir','Invocação Especial','Negar o efeito','Já foi virado','','','','','','','','','','','','');
INSERT INTO texts VALUES(71808988,'Dragão Definitivo Toon de Olhos Azuis',replace(replace('"Dragão Toon de Olhos Azuis" + 2 monstros Toon	\r\nDeve ser Invocado por Invocação-Especial (do seu Deck Adicional) por embaralhar os cards acima da sua mão, campo e/ou Cemitério no Deck/Deck Adicional.\r\nSeus monstros Toon podem atacar diretamente.\r\nUma vez por turno: você pode adicionar 1 card "Toon", ou 1 card que mencione o noem daquele card "Toon", do seu Cemitério à sua mão.\r\nSe seu monstro Toon é atacado, durante o cálculo de dano: você pode bani-lo até o final da Estapa de Dano.','\r',char(13)),'\n',char(10)),'','Recuperar','Banir','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71817640,'Pêndulo Dragônico',replace(replace('Todos os monstros "Dracossassino" no campo ganham 300 de ATK/DEF. \r\nVocê só pode usar cada um dos seguintes efeitos de "Pêndulo Dragônico" uma vez por turno. \r\nSe um monstro Dragão "Dracossassino" que você controla ativar seu efeito (exceto durante a Etapa de Dano): você pode escolher 1 card no campo; destrua-o. \r\nSe este card no campo for destruído: você pode adicionar à sua mão ou Invocar por Invocação-Especial 1 monstro "Dracossassino" ou "Dracosuserano" do seu Deck.','\r',char(13)),'\n',char(10)),'Destruir um card no Campo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71818935,'Lua do Paraíso Fechado',replace(replace('2 Monstros de Efeito	\r\nVocê pode escolher 1 monstro com a face para cima que seu oponente controla para o qual este card apontar; neste turno, se você Invocar por Invocação-Link um monstro de Link-5 usando este card que você controla, você também pode usar esse monstro que seu oponente controla como matéria. \r\nVocê só pode usar este efeito de "Lua do Paraíso Fechado" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71821687,'Ascator, o Andarilho da Aurora',replace(replace('Você pode descartar 1 card; Invoque este card por Invocação-Especial da sua mão em Posição de Defesa e, depois, você pode Invocar por Invocação-Especial 1 "Formiga de Fogo Ascator" da sua mão ou do Deck. \r\nVocê não pode Invocar monstros por Invocação-Especial do Deck Adicional no turno em que ativar este efeito, exceto Monstros Sincro. \r\nVocê só pode usar este efeito de "Ascator, o Andarilho da Aurora" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Invocar "Formiga de Fogo Ascator" por Invocação Especial?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71829750,'Princesa Serpente','Se este card com a face para cima for embaralhado do campo no seu Deck: Invoque por Invocação-Especial 1 monstro de Nível 3 ou menos do seu Deck.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71832012,'Planeta Pressionado Wraitsoth',replace(replace('Quando este card for ativado: você pode adicionar 1 monstro "Kashtira" do seu Deck à sua mão. \r\nMonstros que você controla ganham 100 de ATK/DEF para cada Atributo diferente no campo. \r\nSe um "Shangri-Ira Kashtira" que você controla ativar um efeito (exceto durante a Etapa de Dano): você pode escolher 1 card no campo; destrua-o. \r\nVocê só pode usar este efeito de "Planeta Pressionado Wraitsoth" uma vez por turno. \r\nVocê só pode ativar 1 "Planeta Pressionado Wraitsoth" por turno.','\r',char(13)),'\n',char(10)),'Adicionar à sua mão 1 monstro "Kashtira" do seu Deck?','Destrua 1 card no campo','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71858682,'Centur-Ião Auxila',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nCards com a face para cima na sua Zona de Magias & Armadilhas não podem ser destruídos por efeitos de card. \r\nVocê só pode usar cada um dos seguintes efeitos de "Centur-Ião Auxila" uma vez por turno. \r\nSe este card for Invocado por Invocação-Especial: você pode adicionar 1 card "Centur-Ião" do seu Deck à sua mão. \r\nDurante a Fase Final: você pode colocar 1 dos seus monstros "Centur-Ião" que não sejam Sincro que estiverem banidos ou no seu Cemitério, na sua Zona de Magias & Armadilhas como uma Armadilha Contínua com a face para cima.','\r',char(13)),'\n',char(10)),'Adicione à sua mão 1 card "Centur-Ião"','Coloque um monstro "Centur-Ião"','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71861848,'Salamagrande Coiote',replace(replace('Durante a Fase Final, se este card estiver no Cemitério porque foi enviado para lá como Matéria Link neste turno: você pode ativar 1 dos seguintes efeitos.\r\n● Escolha 1 monstro "Salamagrande" no seu Cemitério, exceto "Salamagrande Coiote"; Invoque-o por Invocação-Especial em Posição de Defesa.\r\n● Escolha 1 card "Salamagrande" no seu Cemitério, exceto "Salamagrande Coiote"; adicione-o à sua mão.	\r\nVocê só pode usar este efeito de "Salamagrande Coiote" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71863024,'Camarartista Cavalo Rabo Rabanete',replace(replace('Escala de Pêndulo = 3\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno: você pode escolher 1 monstro com a face para cima que seu oponente controla e 1 monstro "Camarartista" que você controla; esse monstro do oponente perde ATK igual ao ATK desse monstro "Camarartista" que você controla (mesmo que este card deixe o campo).\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe seu oponente controlar um monstro Invocado por Invocação-Especial e controlar pelo menos tantos monstros quanto você, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nUma vez por turno: você pode escolher 1 monstro com a face para cima no campo de cada duelista; até o final deste turno, esse monstro do oponente perde ATK igual ao ATK deste card e, se isso acontecer, esse monstro que você controla ganha ATK igual ao ATK deste card.','\r',char(13)),'\n',char(10)),'Invocar este card por Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71867500,'Rapsódia da Ressuscitação do Dragão',replace(replace('Se você controlar um monstro Mago: você pode escolher até 2 monstros Dragão no seu Cemitério, incluindo pelo menos 1 Monstro Normal; Invoque-os por Invocação-Especial e, além disso, pelo resto deste turno depois que este card resolver, seu oponente não sofre dano. \r\nVocê só pode ativar 1 "Rapsódia da Ressuscitação do Dragão" por turno.','\r',char(13)),'\n',char(10)),'Continuar selecionando?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71870152,'Senhora Fortuna do Fogo',replace(replace('O ATK/DEF deste card se tornam seu Nível x 200. \r\nUma vez por turno, durante sua Fase de Apoio: aumente em 1 o Nível deste card (máx. 12). \r\nQuando este card for Invocado por Invocação-Especial em Posição de Ataque pelo efeito de um card "Senhora Fortuna": escolha 1 monstro com a face para cima que seu oponente controla; destrua o alvo e, se isso acontecer, cause dano ao seu oponente igual ao ATK do monstro destruído no campo.','\r',char(13)),'\n',char(10)),'Aumentar o Nível','Destrua e cause dano','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71880877,'Super Robô de Defesa Macaqui',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode Invocar por Invocação-Especial 1 monstro "Super Robô de Defesa" ou "Orbital 7" da sua mão. \r\nUma vez por turno: você pode banir 1 monstro do Tipo Máquina do seu Cemitério e, depois, escolher 1 monstro "Super Robô de Defesa" ou "Orbital 7" no seu Cemitério; adicione o alvo à sua mão.','\r',char(13)),'\n',char(10)),'Invocação Especial','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71921856,'Número 79: Boxeador Obstinado Kaiser Nova',replace(replace('2 monstros de Nível 4	\r\nGanha 100 de ATK para cada matéria associada a ele. \r\nUma vez por turno, durante sua Fase Principal: você pode associar 1 monstro "Boxeador Obstinado" da sua mão ou do Cemitério a este card como matéria. \r\nQuando este card em sua posse for destruído por um card do seu oponente e enviado para o seu Cemitério enquanto tiver matéria: você pode escolher monstros "Boxeador Obstinado" de Nível 4 ou menos no seu Cemitério, até o número de matérias que este card tinha no campo; Invoque-os por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Associar Matéria','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71923655,'Tubarão-kraken','Você pode Invocar este card por Invocação-Especial (da sua mão) ao oferecer como Tributo 1 monstro de ÁGUA.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71930383,'Patroide',replace(replace('Pegue e veja 1 card Baixado no Campo do seu adversário, feito isso, devolva-o para a sua posição original. \r\nVocê só pode ativar este efeito uma vez por turno, durante a sua Main Phase.','\r',char(13)),'\n',char(10)),'Revelar um card Baixado','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71934924,'Tempestade de Samurai Velozes!','Cada turno, depois da primeira vez que um monstro "Seis Samurai" que você controla batalhar, todos os monstros "Seis Samurai" que você controla ganham 300 de ATK até o final deste turno.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71939275,'Ilusão Espiritual',replace(replace('Só pode ser equipado a um monstro Demônio ou Zumbi de Nível 5 ou mais. \r\nQuando um ataque for declarado envolvendo o monstro equipado e um monstro do oponente: você pode fazer com que esse monstro do oponente perca ATK igual ao ATK do monstro equipado. \r\nVocê pode ativar 1 desses efeitos;\r\n● Invoque por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional, usando monstros da sua mão ou do campo.\r\n● Invoque por Invocação-Especial 1 "Ficha de Sócia" (Nível 5/ATK ?/DEF 0) com o Tipo, Atributo e ATK do monstro equipado.	\r\nVocê só pode usar este efeito de "Ilusão Espiritual" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Fusão','Invocar uma Ficha por Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71939276,'Ficha de Sócia','Invocado por Especial com o efeito "Ilusão Espiritual".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71948047,'REFORÇOS!',replace(replace('(Este card deve ser sempre considerado como um card "ÁS-Resgate".)	\r\nEscolha 1 monstro "ÁS-Resgate" que você controla; pelo resto deste turno, esse monstro que você controla ganha 1500 de ATK/DEF, não é afetado pelos efeitos de monstro do seu oponente e, na próxima vez que ele seria destruído em batalha, ele não é destruído. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 Magia "ÁS-Resgate" no seu Cemitério; Baixe esse card. \r\nVocê só pode usar este efeito de "REFORÇOS!" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71950093,'Pá Esmagadora','Armado com duas pás, este monstro destruirá qualquer coisa à sua frente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71971554,'Sincron da Estrada',replace(replace('Quando estiver usando este card como uma Matéria Sincro para a Invocação-Sincro de um monstro que não seja "Guerreiro da Estrada", reduza em 2 o Nível deste card. \r\nSe este card atacar, no final da Etapa de Dano: até o final deste turno, aumente o Nível dele em 1.','\r',char(13)),'\n',char(10)),'Aumentar em 1 Nível','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71978434,'Menestrel do Mar Profundo',replace(replace('Você pode descartar este card e 1 monstro de ÁGUA; olhe a mão do seu oponente e bana 1 card da mão dele, com a face para cima, até a Fase Final. \r\nSe este card for Invocado por Invocação-Especial: você pode enviar os 3 cards do topo do seu Deck para o Cemitério e, depois, escolha 1 monstro de ÁGUA de Nível 4 ou menos no seu Cemitério, exceto "Menestrel do Mar Profundo"; coloque-o no topo ou no fundo do Deck. \r\nVocê só pode usar cada efeito de "Menestrel do Mar Profundo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Colocar no topo do Deck','Retornar ao fundo do Deck','','','','','','','','','','','','');
INSERT INTO texts VALUES(71983925,'Talismã de Selar Spells',replace(replace('Ative este card apenas se você controlar "Meisei, Mestre dos Selos". \r\nCards de Magia e seus efeitos no campo não podem ser ativados. \r\nNegue todos os efeitos de Magia no campo. \r\nSe você não controlar "Meisei, Mestre dos Selos", destrua este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(71985676,'Camarartista Anta Infladora',replace(replace('Durante o cálculo de dano (no turno de qualquer duelista), se um monstro que você controla batalhar um monstro do oponente: você pode descartar este card; nenhum duelista sofre qualquer dano de batalha dessa batalha. \r\nQuando um monstro do oponente declarar um ataque direto enquanto este card estiver no seu Cemitério: você pode descartar 1 monstro "Camarartista"; Invoque este card por Invocação-Especial em Posição de Defesa. \r\nVocê só pode usar este efeito de "Camarartista Anta Infladora" uma vez por turno.','\r',char(13)),'\n',char(10)),'O dano de batalha se torna 0','Invocar este card por Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72006609,'Mekk-Cavaleiro da Estrela da Manhã',replace(replace('2 monstros, incluindo um monstro "Mekk-Cavaleiro"	\r\nSe este card for Invocado por Invocação-Link: você pode descartar 1 monstro "Mekk-Cavaleiro" ou 1 card "Legado Mundial"; adicione 1 card "Legado Mundial" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Mekk-Cavaleiro da Estrela da Manhã" uma vez por turno. \r\nSe um monstro "Mekk-Cavaleiro" seu batalhar um monstro em uma coluna diferente da dele, seu monstro não pode ser destruído por essa batalha e, além disso, você não sofre dano de batalha dessa batalha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72022087,'Enfim, Liberdade!','Quando um monstro que você controla for destruído em batalha e enviado para o Cemitério: escolha 2 monstros com a face para cima no campo; embaralhe os alvos no Deck.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72029628,'Fusão Fragmentada',replace(replace('Bana do seu Cemitério os Monstros-Matéria de Fusão listados em um Card de Monstro de Fusão "Cavaleiro-Gema" e, depois, Invoque por Invocação-Especial esse Monstro de Fusão do seu Deck Adicional. \r\n(Esta Invocação-Especial é considerada uma Invocação-Fusão.) \r\nDestrua-o durante a Fase Final.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72043279,'Castelo do Rei Supremo',replace(replace('Você pode Invocar por Invocação-Fusão, Monstros de Fusão que devem ser Invocados por Invocação-Especial com "Fusão Negra", usando outros efeitos que não sejam "Fusão Negra". \r\nUma vez por turno, durante o cálculo de dano, se um monstro Demônio seu batalhar um monstro do oponente: você pode enviar 1 monstro "HERÓI Maligno" do seu Deck ou Deck Adicional para o Cemitério; até o final deste turno, seu monstro ganha ATK igual ao Nível do monstro enviado para o Cemitério x 200 (mesmo que este card deixe o campo).','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72044448,'Raio de Fóton de Destruição',replace(replace('Se você controlar um monstro "Olhos das Galáxias": escolha 1 card no campo; bana o alvo. \r\nVocê só pode ativar este card durante o seu turno, a não ser que você controle "Dragão de Fóton de Olhos das Galáxias".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72053645,'Boletim Metereológico',replace(replace('VIRE: Destrói todos os "Espadas da Luz Reveladora" do seu oponente que estiverem com a face para cima no campo. \r\nSe "Espadas da Luz Reveladora" for destruído, você pode executar sua Fase de Batalha duas vezes neste turno (ou no seu próximo turno, se ativado durante o turno do seu oponente).','\r',char(13)),'\n',char(10)),'Destruir','Realizar outra Fase de Batalha?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72056560,'Cavaleiro-Gema Âmbar',replace(replace('Este card é considerado como um Monstro Normal enquanto estiver com a face para cima no campo ou no Cemitério. \r\nEnquanto este card for um Monstro Normal no campo, você pode Invocá-lo por Invocação-Normal para fazer com que ele se torne um Monstro de Efeito com este efeito.\r\n● Uma vez por turno: você pode enviar 1 card "Cavaleiro-Gema" da sua mão para o Cemitério e, depois, escolha 1 dos seus monstros banidos; adicione o alvo à sua mão.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72060415,'Aria do Mar Profundo',replace(replace('Bana 1 monstro de ÁGUA do seu Cemitério; adicione 1 monstro Serpente Marinha de Nível 4 ou menos do seu Deck à sua mão. \r\nVocê só pode ativar 1 "Aria do Mar Profundo" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72064891,'Maldição do Dragão, o Dragão Cavaleiro Mágico',replace(replace('1 monstro Guerreiro + 1 monstro Dragão de Nível 5 ou mais	\r\nSe você Invocar por Invocação-Fusão um Monstro de Fusão Dragão de Nível 7, você também pode banir monstros do seu Cemitério como matéria. \r\nSe este card for Invocado por Invocação-Fusão: você pode escolher 1 Magia/Armadilha no seu Cemitério que mencione "Gaia, o Matador de Dragões"; adicione-o à sua mão. \r\nVocê só pode usar este efeito de "Maldição do Dragão, o Dragão Cavaleiro Mágico" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72076281,'Morcego','Um morcego mecânico que lança raios das asas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72083436,'Asa de Pegasus','Se você tiver um monstro União no seu Cemitério: escolha qualquer número de monstros "Valquíria-" que você controla; esses monstros podem atacar diretamente neste turno, mas se o fizerem usando este efeito, o dano de batalha que eles causarem ao seu oponente é diminuído pela metade.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72090076,'Corredor Nêmeses',replace(replace('Você pode escolher 1 dos seus monstros banidos, exceto "Corredor Nêmeses"; Invoque este card por Invocação-Especial da sua mão e, se isso acontecer, embaralhe o alvo no Deck. \r\nVocê pode escolher 1 dos seus monstros "Nêmeses" banidos, exceto "Corredor Nêmeses"; adicione-o à sua mão. \r\nVocê só pode usar cada efeito de "Corredor Nêmeses" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72129804,'Predaplasto',replace(replace('Revele qualquer número de cards "Predap" na sua mão e, depois, escolha esse número de monstros com a face para cima que seu oponente controla; coloque 1 Marcador de Predador em cada um e, se isso acontecer, quaisquer desses monstros que forem de Nível 2 ou mais se tornam de Nível 1 enquanto tiverem um Marcador de Predador. \r\nSe um monstro "Predaplanta" seu seria destruído em batalha, em vez disso, você pode banir este card do seu Cemitério.','\r',char(13)),'\n',char(10)),'Usar o efeito de "Predaplasto" em vez de ser destruído?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72142276,'Campo de Condução Derretido','Envie 2 monstros "Laval" do seu Deck para o Cemitério.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72144675,'Troposfera',replace(replace('Se você Invocar por Invocação-Tributo este card, todos os Tributos devem ser do Tipo Besta Alada. \r\nEste card não é afetado por efeitos de Armadilhas.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72150572,'Aparato Antifusão','Destrua 1 Monstro de Fusão com a face para cima no campo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72162751,'Rainha do Domínio Ardente',replace(replace('Não pode ser destruído por efeitos de card. \r\nSe este card estiver na sua mão: você pode escolher até 2 cards que você controla, incluindo uma Magia/Armadilha com a face para cima; destrua-os e, se isso acontecer, Invoque este card por Invocação-Especial. \r\nSe você destruiu 1 card, devolva este card para a mão durante a Fase Final do próximo turno, ou se você destruiu 2, em vez disso, este card ganha este efeito.\r\n● Qualquer monstro enviado do campo para o Cemitério do seu oponente, em vez disso, é banido.	\r\nVocê só pode usar este efeito de "Rainha do Domínio Ardente" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Destruir apenas 1 card','Ganhar um efeito','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72167543,'Maga Nerfada',replace(replace('2 monstros Mago de Nível 4	\r\nDurante sua Fase Principal 2, você também pode Invocar este card por Invocação-Xyz ao usar um Monstro Xyz de Classe 3 ou menos que você controla como matéria. \r\n(Transfira as matérias dele para este card.) \r\nEste card ganha 200 de ATK para cada matéria associada a ele. \r\nSe este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante. \r\nSe este card batalhar, depois do cálculo de dano: desassocie 1 matéria deste card.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Xyz usando um Monstro Xyz de Classe 3 ou menor como Matéria?','Desassociar Matéria','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72171665,'Corretor Mágico',replace(replace('Enquanto você controlar uma Magia/Armadilha Contínua, este card não pode ser destruído em batalha ou por efeitos de card. \r\nDurante o turno do seu oponente (Efeito Rápido): você pode enviar 1 Magia/Armadilha Contínua com a face para cima que você controla para o Cemitério; compre 1 card. \r\nVocê só pode usar este efeito de "Corretor Mágico" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72181263,'D/D Orthros',replace(replace('Escala de Pêndulo = 3\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno: você pode escolher 1 Card de Magia/Armadilha no campo e 1 outro card "D/D" ou "Pacto Obscuro" que você controla; destrua-os.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nQuando você sofrer dano de batalha ou de efeito: você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe este card for Invocado por Invocação-Especial no seu campo, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros do Tipo Demônio.','\r',char(13)),'\n',char(10)),'','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72192100,'Arquidemônio Desrook',replace(replace('Uma vez por turno, durante sua Fase de Apoio, você deve pagar 500 PV (isso não é opcional), ou este card é destruído. \r\nQuando estiver resolvendo um efeito de card do oponente que escolha este card como alvo, lance um dado de seis faces e negue o efeito se esse resultado for um 3 e, se isso acontecer, destrua esse card. \r\nQuando "Rei do Terror Arquidemônio" que você controla for destruído e enviado para o Cemitério (mesmo durante a Etapa de Dano) (Efeito Rápido): você pode enviar este card da sua mão para o Cemitério e, depois, escolha esse "Rei do Terror Arquidemônio" enviado para o seu Cemitério; Invoque-o por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72204747,'Além do Destino','Escolha 1 monstro "HERÓI do Destino" no seu Cemitério; Invoque por Invocação-Especial 1 monstro "HERÓI do Destino" do seu Deck cujo Nível seja igual ou menor que a metade do Nível do alvo, mas destrua-o durante a Fase Final deste turno.','Escolha 1 monstro cujo nome inclua "HERÓI do Destino"','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72218246,'Dragão da Rosa Mestiço',replace(replace('2 monstros com Tipos diferentes	\r\nDurante a Fase Principal (Efeito Rápido): você pode oferecer como Tributo este card e 1 monstro Planta; Invoque por Invocação-Especial 1 Monstro Sincro "Rosa" ou 1 Monstro Sincro Planta do seu Deck Adicional (isso é considerado uma Invocação-Sincro). \r\nSe um ou mais monstros que você controla forem destruídos por um efeito de card, enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode banir este card; Invoque por Invocação-Especial 1 monstro "Dragão da Rosa" do seu Cemitério. \r\nVocê só pode usar cada efeito de "Dragão da Rosa Mestiço" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72228247,'Crusadia Magius',replace(replace('1 monstro "Crusadia", exceto "Crusadia Magius"	\r\nGanha ATK igual ao ATK original do monstro para o qual este card apontar. \r\nO monstro para o qual este card apontar não pode atacar. \r\nSe um Monstro de Efeito for Invocado por Invocação-Especial em uma zona para a qual este card apontar (exceto durante a Etapa de Dano): você pode adicionar 1 monstro "Crusadia" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Crusadia Magius" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72233469,'Rap de Lil-la',replace(replace('Uma vez por turno, se você Invocar por Invocação-Especial um ou mais monstros do Cemitério (exceto durante a Etapa de Dano): você pode fazer com que seu oponente perca 1000 PV e, se isso acontecer, você ganha 500 PV. \r\nVocê só pode ativar este efeito de "Rap de Lil-la" uma vez por Corrente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72237166,'Kaiser Samsara','Quando você Invocar um monstro por Invocação-Tributo ao oferecer este card como Tributo, devolva este card à sua mão.','Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72238166,'Nó de Ryzeal',replace(replace('Se você tiver um Monstro Xyz no seu campo ou Cemitério, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nSe Invocado desta forma, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto Monstros Xyz de Classe 4. \r\nVocê só pode Invocar "Nó de Ryzeal" por Invocação-Especial uma vez por turno desta forma. \r\nVocê pode enviar 1 card da sua mão ou do campo para o Cemitério e, depois, escolha 1 monstro "Ryzeal" no seu Cemitério, exceto "Nó de Ryzeal"; Invoque-o por Invocação-Especial em Posição de Defesa, mas negue seus efeitos. \r\nVocê só pode usar este efeito de "Nó de Ryzeal" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial da mão','Invocar por Invocação Especial do Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72246674,'Besta Gladiadora Dareios',replace(replace('2 monstros, incluindo um monstro "Besta Gladiadora"	\r\nDurante a Fase de Batalha do seu oponente, monstros "Besta Gladiadora" que você controla não podem ser destruídos em batalha ou por efeitos de card. \r\nSe este card for Invocado por Invocação-Link: você pode Invocar por Invocação-Especial 1 monstro "Besta Gladiadora" de Nível 4 ou menos da sua mão ou do Cemitério, ou se seu oponente controlar um monstro, em vez disso, você pode Invocar por Invocação-Especial 1 monstro "Besta Gladiadora" do seu Deck e, além disso, pelo resto deste turno, você só pode usar monstros "Besta Gladiadora" como Matéria Link. \r\nVocê só pode usar este efeito de "Besta Gladiadora Dareios" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Não pode ser destruído em batalha ou por efeitos','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72258771,'Valafar Koa''ki Meiru',replace(replace('Durante cada uma das suas Fases Finais, destrua este card a não ser que você envie 1 "Núcleo de Ferro de Koa''ki Meiru" da sua mão para o Cemitério. \r\nVocê pode Invocar este monstro por Invocação-Tributo ao oferecer como Tributo 1 monstro "Koa''ki Meiru". \r\nEste card não pode ser destruído pelos efeitos de Cards de Armadilha. \r\nDurante a batalha entre este card atacante e um monstro em Posição de Defesa cuja DEF seja menor do que o ATK deste card, cause a diferença como Dano de Batalha ao seu oponente.','\r',char(13)),'\n',char(10)),'Escolha 1 "Núcleo de Ferro de Koa''ki Meiru" para enviar para o Cemitério','Destruir "Valafar Koa''ki Meiru"','Invoque por Invocação Tributo oferecendo 1 monstro cujo nome inclua "Koa''ki Meiru"','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72269672,'Fantasma da Pedra','Com uma cabeça que irrompe quando irritado, este monstro lança uma perigosa chuva de pedregulhos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72270339,'Diabellstar, a Bruxa Negra',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) ao enviar 1 card da sua mão ou do campo para o Cemitério. \r\nVocê só pode Invocar "Diabellstar, a Bruxa Negra" por Invocação-Especial uma vez por turno desta forma. \r\nVocê só pode usar cada um dos seguintes efeitos de "Diabellstar, a Bruxa Negra" uma vez por turno. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode Baixar 1 Magia/Armadilha "Despojos do Pecado" do seu Deck. \r\nDurante o turno do seu oponente, se este card for enviado da mão ou do campo do seu dono para o Cemitério: você pode enviar 1 card da sua mão ou do campo para o Cemitério e, se isso acontecer, Invoque este card por Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72270340,'Diabellstar, a Bruxa Negra',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) ao enviar 1 card da sua mão ou do campo para o Cemitério. \r\nVocê só pode Invocar "Diabellstar, a Bruxa Negra" por Invocação-Especial uma vez por turno desta forma. \r\nVocê só pode usar cada um dos seguintes efeitos de "Diabellstar, a Bruxa Negra" uma vez por turno. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode Baixar 1 Magia/Armadilha "Despojos do Pecado" do seu Deck. \r\nDurante o turno do seu oponente, se este card for enviado da mão ou do campo do seu dono para o Cemitério: você pode enviar 1 card da sua mão ou do campo para o Cemitério e, se isso acontecer, Invoque este card por Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72270341,'Diabellstar, a Bruxa Negra',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) ao enviar 1 card da sua mão ou do campo para o Cemitério. \r\nVocê só pode Invocar "Diabellstar, a Bruxa Negra" por Invocação-Especial uma vez por turno desta forma. \r\nVocê só pode usar cada um dos seguintes efeitos de "Diabellstar, a Bruxa Negra" uma vez por turno. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode Baixar 1 Magia/Armadilha "Despojos do Pecado" do seu Deck. \r\nDurante o turno do seu oponente, se este card for enviado da mão ou do campo do seu dono para o Cemitério: você pode enviar 1 card da sua mão ou do campo para o Cemitério e, se isso acontecer, Invoque este card por Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72272462,'Despiano Quaeritis',replace(replace('1 monstro "Despia" + 1 monstro de LUZ ou de TREVAS	\r\nDurante a Fase Principal (Efeito Rápido): você pode mudar o ATK de todos os monstros atualmente no campo para 0 até o final deste turno, exceto Monstros de Fusão de Nível 8 ou mais. \r\nSe este card com a face para cima sob o controle do seu dono deixar o campo por um efeito de card do oponente: você pode adicionar à sua mão, ou Invocar por Invocação-Especial, 1 "Caído de Arbaz" ou 1 monstro "Despia", do seu Deck. \r\nVocê só pode usar cada efeito de "Despiano Quaeritis" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72278479,'Retorno Negro','Quando exatamente 1 monstro "Asanegra" (e nenhum outro monstro) for Invocado por Invocação-Especial: escolha 1 monstro com a face para cima que seu oponente controla; ganhe PV igual ao ATK do alvo e, se isso acontecer, devolva-o para a mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72283691,'Castelo Dourado de Stromberg',replace(replace('Uma vez por turno, durante sua Fase de Apoio, você deve banir, com a face para baixo, 10 cards do topo do seu Deck (isso não é opcional), ou este card é destruído. \r\nDurante sua Fase Principal: você pode Invocar por Invocação-Especial 1 monstro do seu Deck que liste especificamente o card "Castelo Dourado de Stromberg" em seu texto. \r\nVocê não pode Invocar por Invocação-Normal/Baixar no turno em que ativar este efeito (mesmo que este card deixe o campo). \r\nVocê só pode usar este efeito de "Castelo Dourado de Stromberg" uma vez por turno. \r\nQuando um monstro do oponente declarar um ataque: destrua o monstro atacante e, se isso acontecer, cause dano ao seu oponente igual à metade do ATK que esse monstro tinha no campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72287557,'Polímero Ctoniano',replace(replace('Ative apenas quando seu oponente Invocar um Monstro de Fusão por Invocação-Fusão. \r\nOfereça como Tributo 1 monstro para tomar o controle desse Monstro de Fusão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72291078,'Besta Fantasma Mecha O-Leão',replace(replace('Enquanto você controlar uma Ficha, este card não pode ser destruído em batalha ou por efeitos de card. \r\nSe este card for enviado para o Cemitério: você pode Invocar por Invocação-Especial 1 "Ficha de Besta Fantasma Mecha" (Máquina/VENTO/Nível 3/ATK 0/DEF 0). \r\nVocê só pode usar este efeito de "Besta Fantasma Mecha O-Leão" uma vez por turno. \r\nVocê pode banir este card do seu Cemitério; imediatamente depois que este efeito resolver, Invoque por Invocação-Normal 1 monstro "Besta Fantasma Mecha" da sua mão.','\r',char(13)),'\n',char(10)),'Invocação Especial','Invocar uma Ficha por Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72291079,'Ficha de Besta Fantasma Mecha','Invocado por Especial com o efeito de um monstro "Besta Fantasma Mecha" ou um card relacionado.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72291412,'D/D Limo Necro',replace(replace('Se este card estiver no seu Cemitério: você pode Invocar por Invocação-Fusão 1 Monstro de Fusão "D/D/D" do seu Deck Adicional, ao banir as Matérias de Fusão mencionadas nele do seu Cemitério, incluindo este card. \r\nVocê só pode usar este efeito de "D/D Limo Necro" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72299832,'Mecha-Soldado Gigante','Este monstro brande um machado capaz de estremecer a terra que não pode ser bloqueado por uma espada comum.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72302403,'Espadas da Luz Reveladora',replace(replace('Depois da ativação deste card, ele permanece no campo, mas você deve destruí-lo durante a Fase Final do 3º turno do seu oponente. \r\nQuando este card for ativado: se seu oponente controlar um monstro com a face para baixo, vire com a face para cima todos os monstros que ele controla. \r\nEnquanto este card estiver com a face para cima no campo, os monstros do seu oponente não podem declarar um ataque.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72302404,'Espadas da Luz Reveladora',replace(replace('Depois da ativação deste card, ele permanece no campo, mas você deve destruí-lo durante a Fase Final do 3º turno do seu oponente. \r\nQuando este card for ativado: se seu oponente controlar um monstro com a face para baixo, vire com a face para cima todos os monstros que ele controla. \r\nEnquanto este card estiver com a face para cima no campo, os monstros do seu oponente não podem declarar um ataque.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72305034,'Senhor Gêmeosnizar Golknight',replace(replace('Este card é considerado como um Monstro Normal enquanto estiver com a face para cima no campo ou no Cemitério. \r\nEnquanto este card for um Monstro Normal no campo, você pode Invocá-lo por Invocação-Normal para fazer com que ele se torne um Monstro de Efeito com esses efeitos.\r\n● Se este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 Magia/Armadilha do seu Deck à sua mão que tenha "monstro(s) Gêmeos" em seu texto.	\r\nVocê só pode usar este efeito de "Senhor Gêmeosnizar Golknight" uma vez por turno.\r\n● Este card se torna um monstro Máquina e, além disso, ganha 500 de ATK.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72309040,'Ghoti da Profundeza Distante',replace(replace('1+ Reguladores Peixe + 1+ monstros não-Reguladores	\r\nO ATK original deste card se torna 500 x o número de monstros banidos. \r\nSe este card for Invocado por Invocação-Sincro durante o turno do seu oponente: você pode banir todos os cards no campo. \r\nDurante a Fase de Apoio do próximo turno depois que este card foi banido da Zona de Monstros: você pode Invocar este card banido por Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72318602,'Gardna Vermelho','Durante o turno de qualquer duelista, quando seu oponente ativar um card ou efeito enquanto você controlar um monstro "Dragão Vermelho Arquidemônio": você pode enviar este card da sua mão para o Cemitério; neste turno, monstros que você controla não podem ser destruídos por efeitos de card do seu oponente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72321198,'Força Arcana XII – O Enforcado',replace(replace('Quando um card ou efeito é ativado (Efeito Rápido): você pode revelar este card na sua mão; Invoque por Invocação-Especial 1 monstro "Força Arcana" da sua mão em Posição de Defesa. \r\nVocê só pode usar este efeito de "Força Arcana XII – O Enforcado" uma vez por turno.\r\nSe este card for Invocado: jogue uma moeda e este card ganha o efeito apropriado.\r\n● Cara: Destrói 1 monstro que você controla, e se fizer, você recebe dano igual ao seu ATK original.\r\n● Coroa: Destrói 1 monstro que seu oponente controla, e se fizer, cause dano a ele igual ao seu ATK original.','\r',char(13)),'\n',char(10)),'Invocação Especial','Efeito de jogar moeda','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72323266,'Prisioneiro Terrestre Varredor de Pedra',replace(replace('Se houver um card em uma Zona do Campo, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Prisioneiro Terrestre Varredor de Pedra" por Invocação-Especial uma vez por turno desta forma. \r\nVocê pode descartar este card; adicione 1 Regulador Demônio de Nível 3 ou menos do seu Deck à sua mão e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto Monstros de Fusão ou Sincro. \r\nVocê só pode usar este efeito de "Prisioneiro Terrestre Varredor de Pedra" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invoque este card por Invocação Especial da sua mão','Procurar no Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72328962,'Soulkius Mitológico','Se este card estiver no seu Cemitério: você pode enviar 2 cards da sua mão para o Cemitério, exceto "Soulkius Mitológico"; Invoque este card por Invocação-Especial.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72329844,'Mecanorde Spright',replace(replace('2 monstros, incluindo um monstro de Nível/Classe/Link 2	\r\nNão pode ser usado como Matéria Link no turno em que for Invocado por Invocação-Link. \r\nVocê só pode usar 1 dos seguintes efeitos de "Mecanorde Spright" por turno e apenas uma vez por turno. \r\nSe este card for Invocado por Invocação-Link: você pode enviar 1 monstro de Nível 2 do seu Deck para o Cemitério. \r\nSe outro monstro for Invocado por Invocação-Especial enquanto este card estiver no campo (exceto durante a Etapa de Dano): você pode desassociar 1 matéria de um Monstro Xyz que você controla e, depois, escolha 1 monstro no campo; devolva-o para a mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72330894,'Simorgh, Pássaro da Soberania',replace(replace('2+ monstros, incluindo um monstro Besta Alada	\r\nNão pode ser usado como Matéria Link. \r\nSeu oponente não pode escolher este card, ou um ou mais monstros Besta Alada para os quais este card apontar, como alvo de efeitos de card. \r\nSe este card seria destruído em batalha, em vez disso, você pode destruir 1 outro card "Simorgh" que você controla. \r\nDurante a Fase Final: você pode Invocar por Invocação-Especial 1 monstro Besta Alada da sua mão ou do Deck, com um Nível igual ou menor que o número total de Zonas de Magias & Armadilhas não utilizadas no campo. \r\nVocê só pode usar este efeito de "Simorgh, Pássaro da Soberania" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72332074,'Espinhos Alfan Super Quantal',replace(replace('Se você controlar 3 ou mais monstros "Super Quantum" com nomes diferentes: embaralhe no Deck tantos cards que seu oponente controla quanto possível e, depois, seu oponente Invoca por Invocação-Especial 1 monstro do Deck Adicional dele, ignorando suas condições de Invocação. \r\nVocê pode banir este card e 1 "Fada Alfan Super Quantal" do seu Cemitério; ative 1 "Nave Mech Super Quantal Magnaportador" do seu Deck.','\r',char(13)),'\n',char(10)),'Retornar ao Deck','Ativar uma Magia de Campo','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72336818,'Lucanintrusteste',replace(replace('2 Monstros de Efeito	\r\nSe um monstro linkado seu atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72345736,'Os Seis Samurai Unidos',replace(replace('Sempre que um ou mais monstros "Seis Samurai" forem Invocados por Invocação-Normal ou Especial, coloque 1 Marcador de Bushido neste card (máx. 2). \r\nVocê pode enviar este card para o Cemitério; compre 1 card para cada Marcador de Bushido neste card.','\r',char(13)),'\n',char(10)),'Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72355272,'Nephthys Metafis',replace(replace('Se este card for Invocado por Invocação-Especial pelo efeito de um monstro "Metafis": você pode banir todas as Magias e Armadilhas Baixadas no campo. \r\nSe este card for banido, durante a Fase de Apoio do próximo turno: você pode embaralhar este card banido no Deck; adicione 1 card "Metafis" do seu Deck à sua mão, exceto "Nephthys Metafis".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72355441,'Presente Xyz','Se você controlar 2 ou mais Monstros Xyz com a face para cima: Desassocie 2 Matérias Xyz de um monstro que você controla e compre 2 cards.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72370114,'Engrenagiatacante',replace(replace('Uma vez por turno: você pode colocar este card com a face para baixo em Posição de Defesa. \r\nQuando este card for virado com a face para cima: você pode destruir qualquer número de Cards de Magia/Armadilha no campo, até o número de outros monstros "Engrenagi" que você controla.','\r',char(13)),'\n',char(10)),'Mudar para Posição de Defesa com a face para baixo','Destruir Magias/Armadilhas','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72374522,'Espinhos de Veneno Violeta',replace(replace('(Este card deve ser sempre considerado como um card "Predap".)	\r\nEscolha 1 "Dragão Fusão de Peçonha Insaciável" na sua Zona de Monstros; ele não pode atacar neste turno e, além disso, destrua tantos monstros que seu oponente controla quanto possível com ATK menor que o desse monstro e, depois, você pode descartar toda a sua mão e, se isso acontecer, cause dano ao seu oponente igual ao ATK original combinado dos monstros destruídos por este efeito.','\r',char(13)),'\n',char(10)),'Ativar','Causar dano adicional?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72378329,'Dragão Pêndulo de Olhos Bestiais',replace(replace('1 monstro de TREVAS do Tipo Dragão + 1 monstro do Tipo Besta	\r\nVocê deve Invocá-lo por Invocação-Fusão ou Invocação-Especial ao oferecer como Tributo os cards acima que você controla (e nesse caso, você não usa "Polimerização") e não pode Invocá-lo por Invocação-Especial de nenhuma outra forma. \r\nSe este card destruir um monstro em batalha: cause dano ao seu oponente igual ao ATK original da Matéria de Fusão do Tipo Besta usada para a Invocação deste card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72386290,'Enfoque Aqua-espelhado',replace(replace('Adicione 1 monstro "Gishki" do seu Deck à sua mão. \r\nDurante a Fase Final, se você controlar um Monstro de Ritual de ÁGUA: você pode banir este card do seu Cemitério; Baixe 1 Magia/Armadilha "Aqua-espelhado(a)" diretamente do seu Deck ou Cemitério, exceto "Enfoque Aqua-espelhado". \r\nVocê só pode usar este efeito de "Enfoque Aqua-espelhado" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72402069,'D/D/D Armagedom Brilhante, o Super Rei do Fim',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno, quando um monstro do oponente declarar um ataque: você pode escolher 1 Monstro Sincro "D/D/D" que você controla; destrua tantos monstros que seu oponente controla quanto possível com DEF menor ou igual ao ATK do monstro alvo e, se isso acontecer, cause 1000 de dano ao seu oponente para cada monstro destruído.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\n1 Regulador "D/D" + 1+ monstros "D/D/D" não-Reguladores	\r\nSeu oponente não pode escolher monstros que você controla como alvo de efeitos de card. \r\nSe outro monstro for Invocado por Invocação-Normal ou Especial enquanto este monstro estiver no campo (exceto durante a Etapa de Dano): você pode fazer com que seu oponente selecione 1 Monstro Pêndulo que ele controla e negue os efeitos de todos os outros monstros que ele controla atualmente. \r\nSe este card na Zona de Monstros for destruído: você pode colocar este card na sua Zona de Pêndulo.','\r',char(13)),'\n',char(10)),'Destrua e cause dano','Negar o efeito','Escolha 1 Monstro Pêndulo no campo','Colocar este card na sua Zona de Pêndulo','','','','','','','','','','','','');
INSERT INTO texts VALUES(72403299,'Adivinho Gishki',replace(replace('Uma vez por turno: Você pode declarar 1 nome de card; revele o card do topo do seu Deck e, se ele for o card declarado, adicione-o à sua mão. \r\nCaso contrário, devolva-o para o topo do Deck.','\r',char(13)),'\n',char(10)),'Declare o nome de um card','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72405967,'Tributo Real',replace(replace('Este card pode ser activado apenas quando o seu "Necro-Vale" estiver Campo com a face para cima. \r\nAmbos os jogadores descartam todos os Cards de Monstro das suas mãos para o Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72409226,'Materriator Exagard',replace(replace('2+ monstros de Nível 3	\r\nVocê pode desassociar 1 matéria deste card; Invoque por Invocação-Especial 1 monstro "Materriator" do seu Deck, ou adicione 1 Magia/Armadilha "Materriator" do seu Deck à sua mão. \r\nSe seu oponente Invocar um ou mais monstros por Invocação-Normal ou Especial (exceto durante a Etapa de Dano): você pode adicionar até 2 matérias deste card à sua mão, incluindo um card "Materriator" e, depois, se um Monstro Normal estiver no seu Cemitério, você pode devolver 1 card no campo para a mão. \r\nVocê só pode usar cada efeito de "Materriator Exagard" uma vez por turno.','\r',char(13)),'\n',char(10)),'Manipulação do Deck','Retornar a Matéria Xyz para a mão','Retornar à mão um card no campo?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72413000,'Fofanimal Asas',replace(replace('Se você controlar "Vendedor de Brinquedos": você pode banir este card do seu Cemitério e, depois, escolha 1 monstro "Fofanimal" no seu Cemitério; bana-o e, se isso acontecer, compre 1 card e, depois, você pode enviar 1 "Vendedor de Brinquedos" que você controla para o Cemitério e, se isso acontecer, compre 1 card. \r\nVocê só pode usar este efeito de "Fofanimal Asas" uma vez por turno.','\r',char(13)),'\n',char(10)),'Enviar "Vendedor de Brinquedos" para o Cemitério para comprar 1 card?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72426662,'Demise, o Rei do Armagedom',replace(replace('Você pode Invocar este card por Invocação-Ritual com "Fim do Mundo". \r\nVocê pode pagar 2000 PV; destrua todos os outros cards no campo.','\r',char(13)),'\n',char(10)),'Destrua todos os outros cards','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72427512,'Inseto Devorador de Homens Imitador',replace(replace('VIRE: Escolha 1 monstro no campo; destrua-o e, se isso acontecer, este card ganha ATK igual ao ATK original desse monstro e, depois, você pode mudar o Tipo deste card para o Tipo original desse monstro.\r\nNão pode ser destruído em batalha. \r\nNão pode ser destruído pelos efeitos de monstros com seu mesmo Tipo.','\r',char(13)),'\n',char(10)),'','Alterar o Tipo?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72429240,'Hordeum Maligno O''lanterna','Você pode oferecer este card como Tributo e, depois, escolher 1 monstro com a face para cima que seu oponente controla; destrua o alvo.','Destruir um monstro','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72439556,'Kamui, Esperança de Gusto','VIRE: Invoque por Invocação-Especial 1 monstro Regulador "Gusto" do seu Deck.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72443568,'Mago Silencioso LV8',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial por "Mago Silencioso LV4". \r\nNão é afetado pelos efeitos de Magia do seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72443569,'Mago Silencioso LV8',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial por "Mago Silencioso LV4". \r\nNão é afetado pelos efeitos de Magia do seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72444406,'Enigmestre Packbit',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro ou enviado para o Cemitério: você pode escolher 1 monstro no seu Cemitério ou 1 monstro com a face para cima que seu oponente controla; descarte 1 card e, se isso acontecer, coloque esse monstro na Zona de Magias & Armadilhas do seu dono como uma Armadilha Contínua com a face para cima. \r\nDurante o turno de qualquer duelista, se este card for uma Armadilha Contínua: você pode Invocar por Invocação-Especial 1 Card de Monstro com a face para cima da sua Zona de Magias & Armadilhas. \r\nVocê só pode usar cada efeito de "Enigmestre Packbit" uma vez por turno.','\r',char(13)),'\n',char(10)),'Colocar como Armadilha Contínua','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72446038,'Magia de Síntese',replace(replace('Este card é usado para a Invocação-Ritual de "Licantropo". \r\nVocê também deve oferecer como Tributo monstros da sua mão ou campo cuja soma dos Níveis seja igual a 6 ou mais.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72453068,'Perda de Tempo',replace(replace('Se os PV do seu oponente forem 4000 ou mais, seus PV se tornam 1000 a menos que os dele. \r\nVocê só pode ativar 1 "Perda de Tempo" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72490637,'Fusão Radiestesia',replace(replace('Invoque 1 Monstro de Fusão por Invocação-Fusão do seu Deck Adicional, ao banir Matérias de Fusão listadas nele do seu Cemitério. \r\nApenas Monstros Pêndulo podem ser usados como Matéria de Fusão para o efeito deste card. \r\nVocê só pode ativar 1 "Fusão Radiestesia" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72491806,'U.A. Meio de Campo',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) ao devolver 1 monstro "U.A." que você controla para a mão, exceto "U.A. Meio de Campo". \r\nVocê só pode Invocar "U.A. Meio de Campo" por Invocação-Especial uma vez por turno desta forma. \r\nDurante o turno de qualquer duelista: você pode escolher 1 outro monstro "U.A." que você controla; devolva esse monstro com a face para cima para a mão e, depois, Invoque por Invocação-Especial 1 monstro "U.A." da sua mão com um nome diferente que o desse monstro. \r\nVocê só pode usar este efeito de "U.A. Meio de Campo" uma vez por turno.','\r',char(13)),'\n',char(10)),'Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72497366,'Yorishiro Sinistro',replace(replace('A cada turno, 1 monstro Demônio de Nível 5 ou mais que você Invocar por Invocação-Normal pode ser Invocado sem Tributo. \r\nSe exatamente 1 monstro Demônio de Nível 5 ou mais Invocado por Invocação-Normal/Baixado (e nenhum outro card) seria destruído, em vez disso, você pode enviar este card para o Cemitério.','\r',char(13)),'\n',char(10)),'Invocar pelo efeito de "Yorishiro Sinistro"','Usar o efeito de "Yorishiro Sinistro" em vez de ser destruído?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72498838,'Rilliona, a Magistus de Verre',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode ativar 1 desses efeitos;\r\n● Adicione 1 Magia/Armadilha "Magistus" do seu Deck à sua mão.\r\n● Devolva para o seu Cemitério 1 dos seus monstros Mago banidos de Nível 4 ou menos.	\r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 monstro "Magistus" que você controla; equipe-o com 1 monstro "Magistus" do seu Cemitério, exceto um monstro de Nível 4.\r\nVocê só pode usar cada efeito de "Rilliona, a Magistus de Verre" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à sua mão 1 Magia/Armadilha "Magistus" do seu Deck','Escolha 1 dos seus monstros Mago de Nível 4 ou menor banidos; devolva-o ao Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72502414,'Agente Xyz',replace(replace('Se este card estiver no seu Cemitério: você pode escolher 1 Monstro Xyz "Utopia" que você controla; associe este card do Cemitério a ele como uma Matéria Xyz. \r\nVocê só pode usar o efeito de "Agente Xyz" uma vez por Duelo.','\r',char(13)),'\n',char(10)),'Reabastecer matérias','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72520073,'Artista Negro','Se este card estiver sendo atacado por um monstro de LUZ, sua DEF é diminuída pela metade, apenas durante o cálculo de dano.','Mudar para Posição de Defesa','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72529749,'Trisbena Topológica',replace(replace('2+ Monstros de Efeito	\r\nSe um ou mais monstros forem Invocados por Invocação-Especial para uma ou mais zonas para as quais este card apontar: bana tantos desses monstros quanto possível e, além disso, tantas Magias/Armadilhas no campo quanto possível e, se isso acontecer, cause 500 de dano ao seu oponente para cada um dos cards dele banidos por este efeito.','\r',char(13)),'\n',char(10)),'Banir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72537897,'Obediência Ensinada',replace(replace('Se você não controlar nenhum monstro: Invoque por Invocação-Especial 3 Monstros de Efeito Besta de Nível 2 ou menos com nomes diferentes do seu Deck, mas seus efeitos são negados e, além disso, eles são destruídos durante a Fase Final. \r\nPelo resto deste turno depois que este card resolver, você não pode Invocar por Invocação-Especial, exceto monstros Besta.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72549351,'Táticas Dragônicas','Ofereça como Tributo 2 monstros Dragão; Invoque por Invocação-Especial do seu Deck 1 monstro Dragão de Nível 8.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72554664,'Luz do Marcado',replace(replace('Escolha 1 Monstro de Fusão no campo ou em qualquer Cemitério; devolva-o para o Deck Adicional e, depois, você pode Invocar por Invocação-Especial 1 "Caído de Arbaz" do seu Cemitério no seu campo e 1 monstro do Cemitério do seu oponente no campo dele. \r\nVocê só pode ativar 1 "Luz do Marcado" por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial do Cemitério?','Escolha seu monstro para Invocá-lo por Invocação Especial','Escolha um monstro do oponente para Invocá-lo por Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72554862,'Caverguerra Skyler',replace(replace('Ganha 100 de ATK para cada monstro que seu oponente controla. \r\nDurante uma Fase de Batalha na qual um monstro Guerreiro de TERRA seu batalhar (Efeito Rápido): você pode escolher 1 monstro Guerreiro de Nível 5 ou menos no seu Cemitério; Invoque-o por Invocação-Especial e, além disso, todos os monstros "Caverguerra" que você controla atualmente ganham 200 de ATK até o final do turno do seu oponente e, além disso, pelo resto deste turno, você não pode atacar diretamente com monstros de Nível 5 ou menos. \r\nVocê só pode usar este efeito de "Caverguerra Skyler" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72563071,'Onda de Choque Psíquica','Quando seu oponente ativar um Card de Armadilha: descarte 1 Magia/Armadilha; Invoque por Invocação-Especial 1 monstro Máquina de TREVAS de Nível 6 do seu Deck.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72566043,'Espadachim da Condenação Tornassol',replace(replace('Você pode Invocar este card por Invocação-Ritual com "Ritual da Condenação Tornassol". \r\nEle não é afetado por efeitos de Armadilha e não pode ser destruído em batalha. \r\nGanha 3000 de ATK/DEF enquanto uma Armadilha estiver no campo. \r\nSe este card Invocado por Invocação-Ritual sob o controle do seu dono for destruído por um card do seu oponente: você pode escolher 1 Armadilha em qualquer Cemitério; Baixe-a na sua Zona de Magias & Armadilhas.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72575145,'Despromoção','Diminua em 2 Níveis o monstro equipado com este card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72578374,'Dragão da Origem Estelar Khaos',replace(replace('1 monstro Dragão de LUZ ou de TREVAS + 1 monstro Dragão	\r\nSe este card for Invocado por Invocação-Fusão: você pode escolher cards que seu oponente controla, até o número de monstros de LUZ e de TREVAS seus usados como matéria para este card; destrua-os. \r\nSe este card for banido: você pode escolher 1 monstro Dragão de LUZ ou de TREVAS de Nível 4 que você controla; seu Nível se torna 8. \r\nVocê só pode usar cada efeito de "Dragão da Origem Estelar Khaos" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72580321,'Golem de Blocos','Se todos os monstros no seu Cemitério forem de TERRA: você pode oferecer este card como Tributo e, depois, escolha 2 monstros Rocha de Nível 4 ou menos no seu Cemitério, exceto "Golem de Blocos"; Invoque esses monstros Rocha por Invocação-Especial, mas seus efeitos que ativam no campo não podem ser ativados neste turno.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72589042,'Deusa da Doce Vingança','Enquanto você não controlar nenhum card e este for o único card na sua mão, quando um monstro do oponente declarar um ataque: você pode descartar este card; destrua tantos cards quanto possivel que seu oponente controla e, depois, você pode Invocar 1 monstro do seu Deck por Invocação-Especial.','','Invocação Especial?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72621670,'Braço Mágico Duplo','Ofereça 2 monstros como Tributo e, depois, escolha 2 monstros com a face para cima que seu oponente controla; tome o controle dos dois alvos até a sua Fase Final.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72630549,'Mago Comandante do Caos','Negue quaisquer efeitos de monstro que escolham este 1 card como alvo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72631243,'Bravura de Energia','Monstros Gêmeos que você controla que estiverem sendo considerados como Monstros de Efeito não podem ser destruídos por efeitos de card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72632190,'Behemoth de Três Cabeças',replace(replace('Se um ou mais cards com a face para cima que você controla forem destruídos por um efeito de card, mesmo durante a Etapa de Dano: você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode Invocar por Invocação-Especial 1 monstro de VENTO do seu Cemitério durante a Fase Final deste turno, mas seu ATK/DEF se tornam 1000. \r\nVocê só pode usar este efeito de "Behemoth de Três Cabeças" uma vez por Duelo, e seu efeito anterior apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar este card por Invocação Especial','Invocar por Invocação Especial do Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72634965,'Soberano da Vaidade',replace(replace('Não pode ser Invocado por Invocação-Especial. \r\nSeu oponente não pode Invocar monstros por Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72648577,'D/D/D Recursos Humanos','Embaralhe 3 cards no Deck (qualquer combinação de monstros "D/D" na sua mão, campo ou Cemitério, e/ou cards "D/D" nas suas Zonas de Pêndulo) e, depois, você pode adicionar 2 monstros "D/D" do seu Deck à sua mão.','Procurar no Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72648810,'Vínculo Resoluto','Quando seu oponente ativar um efeito de Monstro Pêndulo ou um efeito de um card na Zona de Pêndulo: negue a ativação e, se isso acontecer, bana esse card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72656408,'Bistial Baldragonete',replace(replace('Você pode escolher 1 monstro de LUZ ou de TREVAS em qualquer Cemitério; bana-o e, se isso acontecer, Invoque este card por Invocação-Especial da sua mão. \r\nEste é um Efeito Rápido se seu oponente controlar um monstro. \r\nSe seu oponente Invocar por Invocação-Especial um ou mais Monstros de Ritual, de Fusão, Sincro, Xyz e/ou Link (exceto durante a Etapa de Dano): você pode oferecer como Tributo 1 outro monstro de LUZ ou de TREVAS e, depois, escolha 1 desses monstros Invocados por Invocação-Especial; bana-o. \r\nVocê só pode usar cada efeito de "Bistial Baldragonete" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Banir o(s) monstro(s) Invocado(s) por Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72657739,'Boneca Malíciosa da Morte','Durante sua próxima Fase de Apoio depois que este card foi enviado do campo para o Cemitério pelo efeito de um Card de Magia Contínua: Invoque este card por Invocação-Especial do Cemitério.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72664875,'Trindade Nova Carmesim, o Senhor Cúbico Obscuro',replace(replace('3 x "Nova Carmesim, o Senhor Cúbico Obscuro"	\r\nDeve ser Invocado por Invocação-Fusão com as Matérias de Fusão acima e não pode ser Invocado por Invocação-Especial de nenhuma outra forma. \r\nNão pode ser escolhido como alvo de, ou destruído por, efeitos de card do seu oponente. \r\nQuando este card declarar um ataque: diminua pela metade os PV do seu oponente. \r\nQuando este card destruir um monstro em batalha: você pode ativar este efeito; este card pode realizar um segundo ataque durante esta Fase de Batalha. \r\nSe você sofrer dano de efeito: cause dano ao seu oponente igual ao dano que você sofreu.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72677437,'Vennominon, o Rei das Serpentes Venenosas',replace(replace('Não pode ser Invocado por Invocação-Especial pelo efeito de outro Monstro de Efeito. \r\nNão é afetado por "Pântano Peçonha". \r\nGanha 500 de ATK para cada monstro Réptil no seu Cemitério. \r\nQuando este card for destruído em batalha e enviado para o Cemitério: você pode banir 1 outro monstro Réptil do seu Cemitério; Invoque este card por Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72700231,'Yuki-Musume, a Mayakashi de Gelo',replace(replace('Se você controlar um card "Mayakashi" que não seja "Yuki-Musume, a Mayakashi de Gelo" enquanto este card estiver na sua mão ou no Cemitério: você pode Invocar este card por Invocação-Especial e, depois, enviar 1 monstro Zumbi do seu Deck para o Cemitério. \r\nVocê só pode usar este efeito de "Yuki-Musume, a Mayakashi de Gelo" uma vez por turno. \r\nVocê não pode Invocar monstros do Deck Adicional por Invocação-Especial, exceto monstros "Mayakashi".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72705654,'Dragão de Bruma de Táquion',replace(replace('Se este card for adicionado à sua mão, exceto ao comprá-lo: você pode Invocar este card por Invocação-Especial. \r\nVocê pode oferecer este card como Tributo; Invoque por Invocação-Especial 1 monstro "Táquion" do seu Deck ou Cemitério, exceto "Dragão de Bruma de Táquion". \r\nSe você Invocar por Invocação-Especial um ou mais Monstros Xyz Dragão (exceto durante a Etapa de Dano): você pode escolher 1 deles; associe este card a esse monstro, do Cemitério (se ele estava lá quando o monstro foi Invocado por Invocação-Especial) ou da mão (mesmo se ele não estava), como matéria. \r\nVocê só pode usar cada efeito de "Dragão de Bruma de Táquion" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Invocar por Invocação Especial do Deck/Cemitério','Tornar-se Matéria Xyz','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72708264,'Lagarto Camarartista Olhos de Robô','Uma vez por turno, durante sua Fase Principal, se este card foi Invocado por Invocação-Normal ou Especial neste turno: você pode enviar 1 monstro "Olhos Anômalos" do seu Deck para o Cemitério; até a Fase Final, o nome deste card se torna o nome original do monstro enviado.','Tornar do mesmo nome','Encerrar o efeito de “mesmo nome”','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72709014,'Julgamento das Princesas',replace(replace('Só pode ser equipado em um "Mágico Branco Pikeru" ou "Maga de Ébano Curran"; ele ganha 800 de ATK. \r\nDurante o turno em que o monstro equipado destruiu um monstro de Nível 5 ou mais em batalha, você pode oferecer como Tributo o monstro equipado e este card para Invocar por Invocação-Especial da sua mão ou Deck: 1 "Princesa Pikeru" se você tiver oferecido como Tributo "Mágico Branco Pikeru" ou 1 "Princesa Curran" se você tiver oferecido como Tributo "Maga de Ébano Curran".','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72710085,'Joias do Destemido',replace(replace('Se exatamente 1 monstro for banido do seu Cemitério (e nenhum outro card for banido ao mesmo tempo), exceto durante a Etapa de Dano: você pode enviar, do seu Deck para o Cemitério, 1 monstro com o Atributo diferente que o do monstro banido. \r\nVocê só pode usar o efeito de "Joias do Destemido" uma vez por turno.','\r',char(13)),'\n',char(10)),'Enviar para o Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72714226,'Cão de Assalto','Quando este card for destruído em batalha e enviado para o Cemitério: você pode Invocar por Invocação-Especial qualquer número de "Cão de Assalto" do seu Deck.','Invocação Especial','Invocar outro monstro por Invocação Especial?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72714392,'Asanegra - Vayu, o Emblema de Honra',replace(replace('Este card com a face para cima no campo não pode ser usado como uma Matéria Sincro. \r\nSe este card estiver no Cemitério: você pode escolher 1 monstro "Asanegra" não-Regulador no seu Cemitério; bana tanto este card quanto o alvo e, se isso acontecer, Invoque por Invocação-Especial 1 Monstro Sincro "Asanegra" do seu Deck Adicional cujo Nível seja igual à soma dos Níveis dos monstros banidos, mas seus efeitos são negados.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72714461,'Mago do Olho-Sábio',replace(replace('Escala de Pêndulo = 5\r\n[ Efeito de Pêndulo ]\r\nSe você tiver um card "Mago" ou "Camarartista" na sua outra Zona de Pêndulo: você pode destruir este card e, se isso acontecer, coloque 1 Monstro Pêndulo "Mago" do seu Deck na sua Zona de Pêndulo, exceto "Mago do Olho-Sábio".\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nVocê pode descartar este card e, depois, escolha 1 card na sua Zona de Pêndulo cuja Escala de Pêndulo atual seja diferente da sua Escala de Pêndulo original; sua Escala de Pêndulo se torna sua Escala de Pêndulo original até o final deste turno.','\r',char(13)),'\n',char(10)),'Ativar na Zona de Pêndulo','Alterar a Escala de Pêndulo','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72717433,'Monstro Boneca Miss Mädchen',replace(replace('Bem-vindo à nossa casa!\r\nAqui eu vivo com Colônia, Vovô Demetto e todas as outras bonecas!','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72767833,'Rotação de Cards',replace(replace('Envie 1 card da sua mão para o Cemitério. \r\nMude a posição de batalha de todos os monstros que seu oponente controla. \r\n(Monstros com a face para baixo em Posição de Defesa são virados com a face para cima em Posição de Ataque.)','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72772445,'Reigolem Triâmide',replace(replace('Todos os monstros do Tipo Rocha no campo ganham 500 de ATK. \r\nSe um monstro "Triâmide" que você controla batalhar, os cards e efeitos do seu oponente não podem ser ativados até o final da Etapa de Dano. \r\nSe este card com a face para cima na Zona do Campo for enviado para o Cemitério: você pode Invocar por Invocação-Especial 1 monstro "Triâmide" da sua mão. \r\nVocê só pode usar este efeito de "Reigolem Triâmide" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72776252,'Manifestação Gelojade',replace(replace('Se você controlar um monstro de ÁGUA e seu oponente tiver um monstro no campo dele ou Cemitério: pegue 1 monstro "Gelojade" do seu Deck e envie-o para o Cemitério ou Invoque-o por Invocação-Especial. \r\nSe um monstro "Gelojade" com a face para cima que você controla deixar o campo por um card do oponente, exceto ao ser destruído (e exceto durante a Etapa de Dano): você pode banir este card do seu Cemitério e, depois, escolha 1 card que seu oponente controla; bana-o. \r\nVocê só pode usar cada efeito de "Manifestação Gelojade" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72782945,'Otonari Trovão',replace(replace('Se você controlar 2 ou mais monstros Trovão e este card estiver na sua mão ou no Cemitério: você pode Invocar este card por Invocação-Especial, mas bana-o quando ele deixar o campo. \r\nVocê pode escolher 1 Monstro Xyz que você controla; associe 2 monstros Trovão de LUZ de Nível 4 da sua mão, do campo com a face para cima e/ou do Cemitério a ele como matéria, incluindo este card que você controla. \r\nVocê só pode usar cada efeito de "Otonari Trovão" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72813401,'Alta-Velocidaroide Elástico Disparador',replace(replace('2 monstros de VENTO	\r\nDurante sua Fase Principal, você pode: imediatamente depois que este efeito resolver, Invoque por Invocação-Normal 1 monstro de VENTO e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto Monstros Sincro. \r\nVocê pode banir 1 Monstro Sincro de VENTO do seu Deck Adicional; revele 2 monstros "Velocidaroide" com nomes diferentes do seu Deck cuja soma dos Níveis seja igual ao Nível desse Monstro Sincro, seu oponente elege 1 deles aleatoriamente para que você adicione à sua mão e você envia o outro para o Cemitério. \r\nVocê só pode usar cada efeito de "Alta-Velocidaroide Elástico Disparador" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar','Procurar no Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72819261,'Sabrelemento Malo',replace(replace('Uma vez por turno: você pode enviar 1 monstro "Sabrelemento" da sua mão para o Cemitério; envie 1 monstro "Sabrelemento" ou "Senhor Elemental" do seu Deck para o Cemitério, exceto "Sabrelemento Malo". \r\nUma vez por turno, se este card estiver no Cemitério: você pode declarar 1 Atributo; este card no Cemitério se torna desse Atributo até o final deste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72837335,'Cronomalia Nó Górdio','Quando este card for Invocado por Invocação-Normal: você pode Invocar por Invocação-Especial 1 monstro "Cronomalia" da sua mão e, se isso acontecer, o Nível deste card se torna igual ao Nível atual desse monstro Invocado por Invocação-Especial.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72842870,'Tyhone','Capaz de atirar balas de canhão de sua boca para realizar ataques à distância, esta criatura é especialmente eficaz em batalhas nas montanhas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72843899,'Fera Cristalina Avançada Tigre Topázio',replace(replace('Se "Trevas Avançadas" não estiver em uma Zona do Campo, envie este monstro para o Cemitério. \r\nTodos os monstros "Fera Cristalina Avançada" que você controla ganham 400 de ATK/DEF e, além disso, monstros que seu oponente controla perdem 400 de ATK/DEF. \r\nSe este card com a face para cima for destruído em uma Zona de Monstros, em vez de enviá-lo para o Cemitério, você pode colocá-lo com a face para cima na sua Zona de Magias & Armadilhas como uma Magia Contínua.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72845813,'Quarentena, Aliado da Justiça','Nenhum duelista pode Invocar monstros de LUZ por Invocação-Especial.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72855441,'Protetor com Azul nos Olhos',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode Invocar por Invocação-Especial 1 Regulador de LUZ de Nível 1 da sua mão. \r\nVocê pode escolher 1 Monstro de Efeito que você controla; envie-o para o Cemitério e, se isso acontecer, Invoque por Invocação-Especial 1 monstro "Olhos Azuis" da sua mão. \r\nVocê só pode usar este efeito de "Protetor com Azul nos Olhos" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72859417,'Lirilusc - Santuário do Pássaro',replace(replace('Você pode escolher 2 Monstros Xyz Besta Alada que você controla; associe 1 desses monstros ao outro como matéria. \r\n(Transfira as matérias dele para esse monstro.) \r\nSe você controlar um Monstro Xyz com 3 ou mais matérias: você pode comprar 1 card. \r\nVocê só pode usar cada efeito de "Lirilusc - Santuário do Pássaro" uma vez por turno.','\r',char(13)),'\n',char(10)),'Sobrepor','Comprar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72860663,'Vampira Fascinadora',replace(replace('2+ monstros, incluindo um monstro Zumbi	\r\nSe este card for Invocado por Invocação-Link: você pode escolher 1 monstro no Cemitério do seu oponente; Invoque-o por Invocação-Especial no seu campo em Posição de Defesa e, além disso, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros Zumbi. \r\nVocê pode oferecer como Tributo 1 monstro "Vampiro(a)" e, depois, escolha 1 monstro que seu oponente controla; tome o controle dele até a Fase Final. \r\nVocê só pode usar cada efeito de "Vampira Fascinadora" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72867001,'Comandante Souza, Mestre da Espada',replace(replace('1 Regulador + 1+ monstros de TERRA	\r\n(Este card deve ser sempre considerado como um card "Sabre-X".)	\r\nGanha 200 de ATK para cada monstro banido. \r\nQuando este card destruir um monstro em batalha: você pode comprar 1 card. \r\nUma vez por turno, quando seu oponente ativar um card ou efeito (Efeito Rápido): você pode oferecer como Tributo 1 monstro "Sabre-X"; destrua 1 card que seu oponente controla. \r\nSe este card seria destruído em batalha ou por um efeito de card, em vez disso, você pode banir 1 card "Sabre" do seu Cemitério.','\r',char(13)),'\n',char(10)),'Comprar','Destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72869010,'Caçador de Almas','"Senhor da Lampada" + "Invasor de Outra Dimenção"','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72880377,'Dragão do Buraco Negro',replace(replace('Não pode ser destruído por efeitos de card. \r\nVocê só pode usar cada um dos seguintes efeitos de "Dragão do Buraco Negro" uma vez por turno. \r\nSe um ou mais monstros no campo forem destruídos por um efeito de card que não os escolha como alvo (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial do Cemitério (se ele estava lá quando o monstro foi destruído) ou da mão (mesmo se ele não estava). \r\nSe este card for Invocado por Invocação-Especial: você pode ativar este efeito; durante a Fase Final deste turno, adicione 1 "Buraco Negro" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72881007,'Abundância Cristalina','Envie 4 cards "Fera Cristalina" da sua Zona de Magias & Armadilhas para o Cemitério; envie para o Cemitério tantos cards no campo quanto possível e, depois, Invoque por Invocação-Especial tantos monstros "Fera Cristalina" quanto possível do seu Cemitério, até o número de cards enviados do campo do seu oponente para o Cemitério pelo efeito deste card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72883039,'Luz Infinita',replace(replace('Ative este card ao enviar 1 "Máquina Infinita" com a face para cima da sua Zona de Magias & Armadilhas para o Cemitério. \r\nEste card com a face para cima não pode ser destruído pelos efeitos de card do seu oponente. \r\nNenhum duelista pode escolher monstros "Senhor do Tempo" que você controla como alvo de efeitos de card, nem devolver monstros "Senhor do Tempo" do campo para o Deck. \r\nUma vez por turno, se você não controlar nenhum monstro: você pode Invocar por Invocação-Especial até 1 monstro "Senhor do Tempo" tanto da sua mão, quanto do seu Deck, quanto do seu Cemitério, com nomes diferentes, ignorando suas condições de Invocação.','\r',char(13)),'\n',char(10)),'','Invocar por Invocação Especial da sua mão?','Invocar por Invocação Especial do Deck?','Invocar por Invocação Especial do Cemitério?','','','','','','','','','','','','');
INSERT INTO texts VALUES(72885174,'Lapso de Fortuna',replace(replace('Só pode ser ativado quando um monstro do seu oponente declarar um ataque que escolha um monstro como alvo. \r\nNegue o ataque e remova de jogo o monstro alvo do ataque até a próxima Fase de Apoio.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72892473,'Destruição de Cards','Os dois duelistas descartam tantos cards quanto possível de suas mãos e, depois, cada duelista compra o mesmo número de cards que ele descartou.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72896720,'Dragão da Condenação Inférnico',replace(replace('1 Regulador de TREVAS + 1+ monstros não-Reguladores	\r\nUma vez por turno, se você não tiver cards na sua mão: você pode escolher 1 monstro que seu oponente controla; destrua o alvo e, se isso acontecer, cause dano ao seu oponente igual à metade do ATK que ele tinha no campo e, além disso, este card não pode atacar no turno em que este efeito for ativado.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72903645,'Dragão de Corte Magno','Você pode enviar 1 Card de Magia Contínua com a face para cima que você controla ao Cemitério para destruir 1 Card de Magia ou Armadilha que seu oponente controla.','Destruir Magias/Armadilhas','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72913666,'Lobo de Guerra Fantardil',replace(replace('Não pode ser Invocado por Invocação-Normal, a não ser que você controle um monstro "Fantardil". \r\nUma vez por turno: você pode colocar este card em Posição de Defesa com a face para baixo. \r\nQuando este card for virado com a face para cima: cause 100 de dano ao seu oponente para cada card Baixado no campo. \r\nVocê só pode usar este efeito de "Lobo de Guerra Fantardil" uma vez por turno.','\r',char(13)),'\n',char(10)),'Mudar para a posição com a face para baixo','Causar dano aos PV','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72921536,'Gato Cômico',replace(replace('Este card é considerado um monstro Toon enquanto "Mundo Toon" está no campo.\r\nDurante a Fase Principal (Efeito Rápido): você pode oferecer 1 monstro como Tributo (se você controla "Mundo Toon", você pode oferecer 1 monstro do oponente como Tributo, mesmo que você não o controle), e se fizer, Invoque por Invocação-Especial 1 monstro da sua mão ou Deck que menciona "Mundo Toon", ignorando suas condições de Invocação. \r\nVocê só pode usar este efeito de "Gato Cômico" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72924435,'Periallis, a Imperatriz de Florescência',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nGanha 400 de ATK para cada monstro Planta que você controla, exceto este card. \r\nDurante sua Fase Principal: você pode Invocar por Invocação-Especial 1 monstro Planta de Nível 5 ou mais da sua mão ou do Cemitério em Posição de Defesa, exceto "Periallis, a Imperatriz de Florescência". \r\nVocê só pode usar este efeito de "Periallis, a Imperatriz de Florescência" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72926163,'Cavaleiro Neos, o HERÓI do Elemento',replace(replace('"Neos, o HERÓI do Elemento" + 1 monstro Guerreiro	\r\nDeve ser Invocado por Invocação-Fusão. \r\nGanha ATK igual à metade do ATK original da Matéria de Fusão Guerreiro usada para sua Invocação-Fusão, exceto "Neos, o HERÓI do Elemento". \r\nPode realizar um segundo ataque durante cada Fase de Batalha. \r\nSeu oponente não sofre dano de batalha de ataques envolvendo este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72929454,'Pássaro Tartaruga','Uma tartaruga incomum que não só nada a uma velocidade tremenda, como também pode navegar pelos céus.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72930878,'Sonido Negro',replace(replace('Quando um monstro do oponente declarar um ataque contra um monstro "Asanegra" que você controla: bana todos os monstros com a face para cima em Posição de Ataque que seu oponente controla. \r\nSe você controlar exatamente 3 monstros "Asanegra" (e nenhum outro monstro), você pode ativar este card da sua mão.','\r',char(13)),'\n',char(10)),'Ativar aplicando o efeito de "Sonido Negro".','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72932673,'Abis-escamas de Mizuchi',replace(replace('Só pode ser equipado em um monstro "Sirena". \r\nEle ganha 800 de ATK. \r\nQuando um efeito de Magia que foi ativado no lado do campo do seu oponente resolver, negue esse efeito e, depois, envie este card para o Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72957245,'Sinais do Adamancipador','Escolha 1 monstro Rocha no seu Cemitério; Invoque-o por Invocação-Especial em Posição de Defesa e, depois, se você Invocou por Invocação-Especial um monstro "Adamancipador" por este efeito, você pode pegar 1 monstro Rocha de Nível 4 ou menos do seu Deck e colocá-lo no topo do seu Deck.','Colocar o card no topo do Deck?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72959823,'Dragão Blindado',replace(replace('1 monstro Máquina + 1 monstro Dragão	\r\nSe este card for destruído e enviado para o Cemitério: você pode escolher 1 card no campo; destrua-o.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72971064,'Lirilusc - Tordo Enlazazul',replace(replace('2+ monstros de Nível 1	\r\nGanha 500 de ATK para cada matéria associada a ele. \r\nSe seu oponente Invocar um ou mais monstros por Invocação-Especial (exceto durante a Etapa de Dano): você pode desassociar 1 matéria deste card e, depois, escolha 1 desses monstros Invocados por Invocação-Especial; devolva-o para a mão. \r\nSe este card em sua posse for enviado para o seu Cemitério por um card do oponente: você pode escolher 1 outro monstro "Lirilusc" no seu Cemitério; adicione-o à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72989439,'Soldado do Lustro Negro - Enviado do Princípio',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro deve ser Invocado por Invocação-Especial (da sua mão) ao banir 1 monstro de LUZ e 1 de TREVAS do seu Cemitério. \r\nUma vez por turno, você pode ativar 1 desses efeitos.\r\n● Escolha 1 monstro no campo; bana-o.	\r\nEste card não pode atacar no turno em que este efeito for ativado.\r\n● Se este card que estiver atacando destruir um monstro do oponente em batalha: ele pode realizar um segundo ataque em seguida.','\r',char(13)),'\n',char(10)),'Invocação Especial','Banir','Continuar atacando','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72989440,'Soldado do Lustro Negro - Enviado do Princípio',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro deve ser Invocado por Invocação-Especial (da sua mão) ao banir 1 monstro de LUZ e 1 de TREVAS do seu Cemitério. \r\nUma vez por turno, você pode ativar 1 desses efeitos.\r\n● Escolha 1 monstro no campo; bana-o.	\r\nEste card não pode atacar no turno em que este efeito for ativado.\r\n● Se este card que estiver atacando destruir um monstro do oponente em batalha: ele pode realizar um segundo ataque em seguida.','\r',char(13)),'\n',char(10)),'Invocação Especial','Banir','Continuar atacando','','','','','','','','','','','','','');
INSERT INTO texts VALUES(72992744,'Lorde dos Bobos da Corte','Enquanto este card for o único monstro no campo, ele ganha 1000 de ATK para cada card na Zona de Cards de Magia & Armadilha.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73001017,'Silpheed',replace(replace('Este card não pode ser Invocado por Invocação-Normal ou Baixado. \r\nEste card só pode ser Invocado por Invocação-Especial ao remover do Duelo 1 monstro de VENTO no seu Cemitério. \r\nQuando este card for destruído como resultado de uma batalha e enviado para o Cemitério, seu oponente descarta 1 card aleatório da mão dele.','\r',char(13)),'\n',char(10)),'Descartar da mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73018302,'Caçador de Plumas Negras','Enquanto seu oponente controlar 2 ou mais monstros com a face para cima, todos do mesmo Tipo, você pode enviar 1 card da sua mão ao Cemitério para selecionar e destruir 1 monstro com a face para cima que seu oponente controla.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73026394,'Guarda de Fusão',replace(replace('Ative apenas quando um efeito que causa dano for ativado. \r\nNegue a ativação e efeito, e envie aleatoriamente 1 Monstro de Fusão do seu Deck Adicional para o Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73040500,'Urustos Mitológico','Enquanto você tiver 2 cards ou menos na sua mão, todos os monstros "Mitológico(a)" com a face para cima que você controla ganham 400 de ATK.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73046708,'Xyz de Armadura',replace(replace('Escolha 1 monstro com a face para cima que você controla e 1 Monstro Xyz no seu Cemitério; equipe esse monstro do seu Cemitério a esse monstro no campo como uma Magia de Equipamento com esses efeitos.\r\n● Mude o ATK do monstro equipado para o ATK deste card.\r\n● O monstro equipado ganha o Atributo deste card.\r\n● No final da Etapa de Dano, se o monstro equipado atacou: você pode enviar este card para o Cemitério; o monstro atacante pode realizar um segundo ataque em seguida.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73048641,'Meio Fechado','Escolha 1 monstro com a face para cima no campo; ele não pode ser destruído em batalha neste turno e, além disso, seu ATK é diminuído pela metade até o final deste turno.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73051941,'Monstro de Arenito','Ele aparece do sub-solo e ataca com longos tentáculos em forma de serpentes.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73055622,'Chamado do Shinobird',replace(replace('Este card é usado para a Invocação-Ritual de "Shinobaronesa Pavoa" ou "Shinobarão Pavão". \r\nVocê também deve oferecer como Tributo monstros da sua mão ou do campo e/ou banir monstros Espírito do seu Cemitério, cuja soma dos Níveis seja igual ou exceda o Nível do Monstro de Ritual que você Invocou por Invocação-Ritual.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73061465,'Quebra-feitiços da Barreira de Gelo','Uma vez por turno: você pode enviar 1 monstro "Barreira de Gelo" da sua mão para o Cemitério; nenhum duelista pode ativar Cards de Magia até o final do seu próximo turno enquanto este monstro estiver com a face para cima no campo.','Não é possível ativar Cards de Magia','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73079365,'Vendaval',replace(replace('Você pode ativar este card quando 1 ou mais dos seus Cards de Magia forem destruídos e enviados do campo para o Cemitério por um efeito de card que seu oponente controla. \r\nDestrua 1 Card de Magia ou Armadilha no campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73079836,'Ressurgido Adamancipador - Raptita',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nDurante sua Fase Principal: você pode escavar os 5 cards do topo do seu Deck e, se isso acontecer, você pode Invocar por Invocação-Especial 1 monstro Rocha escavado em Posição de Defesa e, além disso, coloque o resto no fundo do seu Deck em qualquer ordem. \r\nDurante o turno do seu oponente, se um monstro de VENTO estiver no seu Cemitério (Efeito Rápido): você pode escolher 1 card no Cemitério do seu oponente; bana-o. \r\nVocê só pode usar cada efeito de "Ressurgido Adamancipador - Raptita" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Invocar por Invocação Especial o monstro?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73081602,'Pássaro Rainha','Este monstro ataca seus inimigos com seu enorme bico.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73082255,'O Vampiro Zumbi',replace(replace('2+ monstros de Nível 8	\r\nSe você usar um ou mais monstros com um Nível dos quais seu oponente seja dono, para a Invocação-Xyz deste card, considere-o(s) como de Nível 8. \r\nNenhum duelista pode escolher este card como alvo de efeitos de monstros Invocados por Invocação-Especial, exceto aqueles Invocados por Invocação-Especial do Cemitério. \r\nVocê pode desassociar 1 matéria deste card; cada duelista envia os 4 cards do topo do Deck dele para o Cemitério e, depois, se qualquer monstro foi enviado para qualquer Cemitério por este efeito, você pode Invocar por Invocação-Especial 1 desses monstros no seu campo. \r\nVocê só pode usar este efeito de "O Vampiro Zumbi" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Invocar por Invocação Especial o monstro enviado ao Cemitério?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73104892,'Donzela de Bordo',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Especial: você pode declarar 1 Atributo; este card ganha o seguinte efeito.\r\n● Todos os monstros com a face para cima se tornam desse Atributo.	\r\nVocê pode escolher 1 monstro na Zona de Monstros Principal do seu oponente; seu oponente deve enviar para o Cemitério 1 card das suas Zonas de Monstros ou Zonas de Magias & Armadilhas adjacentes. \r\nVocê só pode usar cada efeito de "Donzela de Bordo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73121813,'Espírito Tenyi - Mula Adhara',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro e 2 ou mais monstros Wyrm estiverem no seu Cemitério e/ou banimento: você pode adicionar 1 Magia de Campo do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Espírito Tenyi - Mula Adhara" uma vez por turno. \r\nEnquanto um Monstro que não seja de Efeito estiver com a face para cima no campo, este card ganha esses efeitos.\r\n● Não pode ser destruído por efeitos de card do oponente.\r\n● Seu oponente não pode escolher este card como alvo de efeitos de card.\r\n● Pode realizar um segundo ataque durante cada Fase de Batalha.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73125233,'Raiza, a Monarca da Tempestade','Se este card for Invocado por Invocação-Tributo: escolha 1 card no campo; coloque o alvo no topo do Deck.','Retornar ao Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73129314,'Coração de Gaia',replace(replace('(Este card deve ser sempre considerado como um card "Milênio" e "Gaia, o Cavaleiro Impetuoso".)	\r\nSe um Card de Monstro de Nível 5 ou mais estiver no campo, você pode Invocar este card por Invocação-Normal sem oferecer Tributo. \r\nEnquanto este card estiver na sua Zona de Monstros, o Nível de qualquer monstro que seu oponente Invocar por Invocação-Normal ou Especial em Posição de Ataque aumenta em 7. \r\nQuando seu oponente ativar um efeito de monstro (Efeito Rápido): você pode enviar para o Cemitério 1 outro Card de Monstro de Nível 5 ou mais com a face para cima que você controla; negue a ativação e, se isso acontecer, destrua esse card. \r\nVocê só pode usar este efeito de "Coração de Gaia" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Normal sem Tributo','','Negar a ativação','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73130445,'Camarartista Compragarto',replace(replace('Escala de Pêndulo = 6\r\n[ Efeito de Pêndulo ]\r\nSe você tiver um card "Camarartista" na sua outra Zona de Pêndulo, exceto "Camarartista Compragarto": você pode destruir este card e, se isso acontecer, compre 1 card. \r\nVocê só pode usar este efeito de "Camarartista Compragarto" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe outro monstro com a face para cima que você controla for destruído por um ataque ou efeito de card do seu oponente: você pode comprar cards igual ao número de monstros "Camarartista" que você controla atualmente. \r\nVocê só pode usar este efeito de "Camarartista Compragarto" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73134081,'Chama Final','Inflija 600 pontos de dano aos Life Points do seu adversário.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73134082,'Chama Final','Inflija 600 pontos de dano aos Life Points do seu adversário.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73136204,'Translotus Silvestre',replace(replace('Uma vez por turno: você pode escavar um número de cards do topo do seu Deck igual ao número de cards que seu oponente controla, enviar quaisquer monstros escavados do Tipo Planta para o Cemitério e, além disso, colocar os outros cards no fundo do seu Deck em qualquer ordem. \r\nSe este card for escavado do Deck e enviado para o Cemitério por um efeito de card: você pode escolher até 5 cards "Silvestre" no seu Cemitério, exceto "Translotus Silvestre"; coloque-os no fundo do seu Deck em qualquer ordem.','\r',char(13)),'\n',char(10)),'Escave cards do seu Deck','Retornar ao Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73146473,'Carregador Cruzado',replace(replace('Você pode enviar 1 monstro que você controla para o Cemitério e Invocar por Invocação-Especial 1 monstro "Neoespacial" da sua mão. \r\nQuando este card for enviado para o Cemitério, você pode adicionar 1 monstro "Neoespacial" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Invocação Especial','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73148972,'Negação Impiedosa','Escolha 1 monstro que você controla e envie-o para o Cemitério, e envie 1 card aleatório na mão do seu oponente para o Cemitério.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73167098,'Aromági-lilith Magnólia',replace(replace('1 monstro "Aromági" + 1 monstro Planta	\r\nEnquanto seus PV forem maiores que os do seu oponente, monstros Planta que você controla não podem ser destruídos pelos efeitos de card do seu oponente. \r\nUma vez por turno: você pode pagar 2000 PV; bana cards no campo igual ao número de "Ventos Húmidos", "Ventos Secos" e "Ventos Abençoados" que você controla. \r\nUma vez por turno, se você ganhar PV, mesmo durante a Etapa de Dano: você pode fazer com que, até o final deste turno, todos os monstros Planta que você controla atualmente ganhem ATK igual aos PV ganhos.','\r',char(13)),'\n',char(10)),'','Banir card(s)','Aumentar ATK','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73176465,'Felis, a Arqueira Luminosa',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial por um efeito de card. \r\nSe este card for enviado do Deck para o seu Cemitério por um efeito de monstro: Invoque-o por Invocação-Especial. \r\nVocê pode oferecer este card como Tributo e, depois, escolha 1 monstro que seu oponente controla; destrua o alvo e, depois, envie os 3 cards do topo do seu Deck para o Cemitério.','\r',char(13)),'\n',char(10)),'Invocação Especial','Destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73178098,'Intensificador de Ego','Quando um monstro declarar um ataque: escolha 1 monstro com a face para cima no campo; ele ganha 1000 de ATK até o final da Fase de Batalha.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73192600,'Cliffhanger do Legado Mundial',replace(replace('Quando um ataque for declarado envolvendo 2 Monstros Link: embaralhe nos Decks todos os monstros no campo e nos Cemitérios. \r\nPelo resto deste turno depois que este card resolver, nenhum duelista pode Invocar por Invocação-Link.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73193552,'Flâmula da Revolução',replace(replace('Se um ou mais outros cards que você controla forem destruídos em batalha ou por um efeito de card: você pode adicionar 1 "Enfim, Liberdade!" do seu Deck ou Cemitério à sua mão. \r\nNo começo da Etapa de Dano, se um Monstro Sincro batalhar um monstro: você pode destruir o monstro que está batalhando do seu oponente. \r\nSe este card na Zona de Magias & Armadilhas seria destruído por um efeito de card, em vez disso, você pode destruir 1 monstro que você controla. \r\nVocê só pode usar cada efeito de "Flâmula da Revolução" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicione "Enfim, Liberdade!" à mão','Destrua o monstro do oponente em batalha','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73199638,'Chamado de Atlante',replace(replace('Escolha 3 monstros do Tipo Serpente Marinha de Nível 3 ou menos no seu Cemitério; Invoque os 3 por Invocação-Especial. \r\nVocê não pode Invocar outros monstros por Invocação-Especial durante o turno em que ativar este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73206827,'Barreira de Luz',replace(replace('Uma vez por turno, durante sua Fase de Apoio: lance uma moeda. \r\nSe o resultado for Coroa, os seguintes efeitos são negados até sua próxima Fase de Apoio.\r\n● Quando você Invocar um monstro "Força Arcana", selecione qual efeito aplicar sem lançar uma moeda.\r\n● Se um monstro "Força Arcana" seu destruir um monstro do oponente em batalha: você ganha PV igual ao ATK original do monstro destruído.','\r',char(13)),'\n',char(10)),'Jogar uma moeda','Ganhar PV','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73213494,'Calcab, Malebranche do Abismo Ardente',replace(replace('Se você controlar um monstro que não seja um monstro "Abismo Ardente", destrua este card. \r\nVocê só pode usar 1 desses efeitos de "Calcab, Malebranche do Abismo Ardente" por turno e apenas uma vez por turno.\r\n● Se você não controlar Cards de Magia/Armadilha: você pode Invocar este card por Invocação-Especial da sua mão.\r\n● Se este card for enviado para o Cemitério: você pode escolher 1 Card Baixado de Magia/Armadilha no campo; devolva o alvo para a mão.','\r',char(13)),'\n',char(10)),'Invocação Especial','Retornar para a mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73216412,'Dragonete-Lombriga','Depois que este monstro envolve sua vítima, não há como escapar.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73218792,'Meister Sucata',replace(replace('Se este card estiver na sua mão: você pode revelar 1 Monstro Sincro "Guerreiro(a)" ou "Poeira Estelar" no seu Deck Adicional; Invoque este card por Invocação-Especial e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto Monstros Sincro. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 card "Sucata" do seu Deck à sua mão, exceto "Meister Sucata". \r\nVocê pode escolher 1 monstro "Sucata" que você controla; reduza o Nível dele em até 2. \r\nVocê só pode usar cada efeito de "Meister Sucata" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Efeito de busca','Alterar o Nível','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73218989,'Dragão de Assalto de Asas Negras',replace(replace('1 Monstro Sincro Regulador + 1+ monstros não-Reguladores	\r\nDeve ser Invocado por Invocação-Sincro, ou Invocado por Invocação-Especial do seu Deck Adicional ao banir 1 Monstro Sincro Regulador e 1 "Dragão de Asas Negras" do seu campo com a face para cima e/ou Cemitério. \r\nSempre que seu oponente ativar um efeito de monstro, coloque 1 Marcador de Pena Negra neste card quando esse efeito resolver e, se isso acontecer, cause 700 de dano ao seu oponente. \r\nDurante o turno do seu oponente (Efeito Rápido): você pode oferecer como Tributo este card com 4 ou mais Marcadores de Pena Negra nele; destrua todos os cards no campo.','\r',char(13)),'\n',char(10)),'Banir "Dragão de Asas Negras" para Invocá-lo por Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73219648,'Peão Vil Arquidemônio',replace(replace('Uma vez por turno, durante sua Fase de Apoio, você deve pagar 500 PV (isso não é opcional), ou este card é destruído. \r\nQuando estiver resolvendo um efeito de card do oponente que escolha este card como alvo, lance um dado de seis faces e negue esse efeito se o resultado for um 3 e, se isso acontecer, destrua esse card. \r\nOs monstros do seu oponente não podem atacar nenhum monstro "Arquidemônio" que você controla, exceto "Peão Vil Arquidemônio".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73239437,'Ataque Duplo do Herói',replace(replace('Se você controlar um Monstro de Fusão que liste "Neos, o HERÓI do Elemento" como matéria: escolha 1 Monstro de Fusão "HERÓI" no seu Cemitério; Invoque-o por Invocação-Especial, ignorando suas condições de Invocação. \r\nVocê só pode ativar 1 "Ataque Duplo do Herói" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73240432,'Diabrete de Dentes Comedor de Algodão',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nTodos os Monstros de Fusão que você controla ganham 300 de ATK. \r\nUma vez por turno, se um ou mais Monstros de Fusão "Peladura" forem Invocados por Invocação-Fusão no seu campo (exceto durante a Etapa de Dano): você pode comprar 1 card.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe este card for Invocado por Invocação-Especial: você pode causar 200 de dano ao seu oponente para cada monstro "Peladura" no seu Cemitério. \r\nVocê só pode usar este efeito de "Diabrete de Dentes Comedor de Algodão" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73244186,'Moreia da Avareza',replace(replace('Bana 1 monstro Peixe, Serpente Marinha ou Aqua com a face para cima que você controla; compre 2 cards. \r\nVocê só pode ativar 1 "Moreia da Avareza" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73262676,'Dispersão de Células "A"',replace(replace('Escolha 1 monstro "Alienígena" com a face para cima que você controla. \r\nDestrua-o e distribua novos Marcadores-A igual ao seu Nível entre os monstros com a face para cima do seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73271204,'Recardianação',replace(replace('Escolha 1 monstro "Flor Cardian" no seu Cemitério; adicione-o à sua mão e, depois, você pode Invocar por Invocação-Especial 1 monstro "Flor Cardian" da sua mão, ignorando suas condições de Invocação. \r\nSe este card for enviado para o Cemitério pelo efeito de um monstro "Flor Cardian": você pode escavar os 5 cards do topo do seu Deck e, se isso acontecer, você pode adicionar 1 Card de Magia/Armadilha escavado à sua mão. \r\nColoque os cards restantes no topo do seu Deck em qualquer ordem.','\r',char(13)),'\n',char(10)),'Invocação Especial','Escave cards do seu Deck','Invocar por Invocação Especial um monstro "Flor Cardian"?','Adicionar à sua mão um Card de Magia/Armadilha?','','','','','','','','','','','','');
INSERT INTO texts VALUES(73275815,'Buraco Link',replace(replace('Se você controlar um monstro de Link-4 ou mais: destrua monstros que seu oponente controla, até o número de monstros de Link-3 ou mais que você controla. \r\nVocê só pode ativar 1 "Buraco Link" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73285669,'Besta Gladiadora Essedarii',replace(replace('2 monstros "Besta Gladiadora"	\r\nPrimeiro deve ser Invocado por Invocação-Especial (do seu Deck Adicional) ao embaralhar os cards acima que você controla no Deck.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73287067,'Explosão Link',replace(replace('Escolha 1 Monstro Link que você controla e 1 monstro que seu oponente controla; destrua-os e, depois, compre 1 card. \r\nVocê só pode ativar 1 "Explosão Link" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73289035,'Bujintei Tsukuyomi',replace(replace('2 monstros de LUZ de Nível 4	\r\nUma vez por turno: você pode desassociar 1 matéria deste card; envie toda a sua mão para o Cemitério (mín. 1) e, se isso acontecer, compre 2 cards. \r\nQuando este card que você controlava enquanto estava com a face para cima deixar o campo devido ao efeito de um card do oponente: você pode escolher monstros "Bujin" Besta-Guerreira de Nível 4 no seu Cemitério, até o número de Matérias Xyz que este card tinha no campo; Invoque os alvos por Invocação-Especial. \r\nVocê só pode controlar 1 "Bujintei Tsukuyomi".','\r',char(13)),'\n',char(10)),'Comprar','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73304257,'Alfa, o Mestre das Bestas',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro deve ser Invocado por Invocação-Especial (da sua mão) enquanto o ATK total de todos os monstros que seu oponente controla for maior que o de todos os monstros que você controla. \r\nVocê pode escolher qualquer número de monstros Besta, Besta-Guerreira e/ou Besta Alada que você controla; devolva-os para a mão e, depois, devolva monstros com a face para cima que seu oponente controla para a mão, igual ao número de cards que você devolveu para a mão e, além disso, pelo resto deste turno, "Alfa, o Mestre das Bestas" que você controla não pode atacar diretamente. \r\nVocê só pode usar este efeito de "Alfa, o Mestre das Bestas" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73309655,'Eria, a Encantadora da Água, Gentil',replace(replace('2 monstros, incluindo um monstro de ÁGUA	\r\n(Este card deve ser sempre considerado como um card "Espírito-Possuído".)	\r\nVocê pode escolher 1 monstro de ÁGUA no Cemitério do seu oponente; Invoque-o por Invocação-Especial em uma zona sua para a qual este card apontar. \r\nSe este card Invocado por Invocação-Link for destruído em batalha, ou for destruído por um efeito de card do oponente enquanto estiver na Zona de Monstros do seu dono: você pode adicionar 1 monstro de ÁGUA com 1500 ou menos de DEF do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "Eria, a Encantadora da Água, Gentil" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73318863,'Lyna, a Encantadora da Luz','VIRE: Escolha 1 monstro de LUZ que seu oponente controla; tome o controle dele enquanto este card estiver com a face para cima no campo.','Ganhe o controle de 1 monstro de LUZ que seu oponente controla','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73318864,'Lyna, a Encantadora da Luz','VIRE: Escolha 1 monstro de LUZ que seu oponente controla; tome o controle dele enquanto este card estiver com a face para cima no campo.','Ganhe o controle de 1 monstro de LUZ que seu oponente controla','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73320394,'Senhor Maligno – Zorc',replace(replace('Você pode descartar 2 cards, incluindo este card; adicione 1 monstro Demônio de Nível 8 do seu Deck à sua mão.\r\nQuando seu monstro Demônio é destruído por batalha: você pode Invocar por Invocação-Especial este card do seu Cemitério.\r\nDurante a sua Fase Principal: você pode rolar um dado e aplicar este efeito baseado no resultado.\r\n● 1, 2, 3, ou 4: tome controle ou destrua, 1 monstro que seu oponente controla.\r\n● 5 ou 6: destrua 1 card que você controla.	\r\nVocê só pode usar cada um dos efeitos de "Senhor Maligno – Zorc" uma vez por turno.','\r',char(13)),'\n',char(10)),'Efeito de busca','Invocação Especial','Efeito do dado','Tomar controle?','','','','','','','','','','','','');
INSERT INTO texts VALUES(73333463,'Armaduroide','Se este card for Invocado por Invocação-Tributo pelo Tributo de pelo menos 1 monstro "roide": bana todas as Magias e Armadilhas no campo.','Banir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73341839,'Dragão Minicallibre',replace(replace('2 monstros "Foguette"	\r\nSe você controlar um Monstro Link "Callibre" enquanto este card estiver no seu Cemitério: você pode oferecer como Tributo 1 monstro de Link-3 ou menos; Invoque este card por Invocação-Especial, mas ele não pode ser usado como matéria para a Invocação-Link de um monstro com o mesmo Valor Link que o monstro oferecido como Tributo. \r\nVocê só pode usar este efeito de "Dragão Minicallibre" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73345237,'Benghalanceiro, o Ressurgente',replace(replace('2+ monstros Planta	\r\nDurante a Fase Principal (Efeito Rápido): você pode escolher 1 Monstro de Efeito que seu oponente controla; sofra dano igual ao ATK dele e, se você sofreu dano, devolva-o para a mão. \r\nSe este card estiver no seu Cemitério: você pode banir 2 ou mais Monstros Link do seu Cemitério cuja soma dos Valores Link seja exatamente igual a 4; Invoque este card por Invocação-Especial, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar 1 efeito de "Benghalanceiro, o Ressurgente" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73347079,'Ataqueraptor - Força Strix',replace(replace('2 monstros de Nível 4	\r\nGanha 500 de ATK/DEF para cada monstro Besta Alada que você controla, exceto este card. \r\nUma vez por turno: você pode desassociar 1 matéria deste card; adicione 1 monstro Besta Alada de TREVAS de Nível 4 do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73355772,'Dogmatika Fleurdelis, o Raio',replace(replace('Durante a Fase Principal, se um monstro Invocado por Invocação-Especial do Deck Adicional estiver no campo (Efeito Rápido): você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe este card for Invocado por Invocação-Especial da mão: você pode Baixar 1 Armadilha "Dogmatika" do seu Deck. \r\nEla pode ser ativada neste turno, enquanto seu oponente controlar um Monstro de Fusão, Sincro, Xyz ou Link com 2500 ou mais de ATK. \r\nVocê só pode usar cada efeito de "Dogmatika Fleurdelis, o Raio" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Baixar','Ativar aplicando o efeito de "Dogmatika Fleurdelis, o Raio".','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73355951,'Invocação Alfa',replace(replace('Escolha 1 dos seus monstros banidos e 1 dos monstros banidos do seu oponente; Invoque por Invocação-Especial seu monstro no campo do seu oponente e, se isso acontecer, Invoque por Invocação-Especial esse monstro do oponente no seu campo. \r\nVocê só pode ativar 1 "Invocação Alfa" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73356503,'Estátua Barreira do Vendaval','Nenhum duelista pode Invocar monstros por Invocação-Especial, exceto monstros de VENTO.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73359475,'Nobre Cavaleiro Peredur',replace(replace('Enquanto este card estiver equipado com um Card de Magia de Equipamento "Armas Nobres", ele se torna de TREVAS e seu Nível aumenta em 1. \r\nSe este card for enviado para o Cemitério enquanto estiver equipado com um Card de Magia de Equipamento "Armas Nobres": escolha 1 card "Armas Nobres" no seu Cemitério; adicione o alvo à sua mão.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73360025,'Pacto Obscuro com o Rei do Pântano',replace(replace('Durante sua Fase Principal: você pode Invocar por Invocação-Fusão 1 Monstro de Fusão Demônio do seu Deck Adicional, usando monstros da sua mão ou do campo como matéria. \r\nVocê só pode usar este efeito de "Pacto Obscuro com o Rei do Pântano" uma vez por turno. \r\nSe estiver Invocando um Monstro de Fusão "D/D" desta forma, você também pode banir monstros do seu Cemitério como matéria. \r\nUma vez por turno, durante sua Fase de Apoio: sofra 1000 de dano.','\r',char(13)),'\n',char(10)),'Invocação Fusão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73391962,'Azamina Mu Rcielago',replace(replace('1 monstro Ilusão + 1 monstro Mago de LUZ	\r\nMonstros que seu oponente controla perdem 500 de ATK/DEF para cada monstro "Azamina" que você controla. \r\nVocê só pode usar cada um dos seguintes efeitos de "Azamina Mu Rcielago" uma vez por turno. \r\nSe este card for Invocado por Invocação-Fusão: você pode adicionar 1 card "Azamina" ou "Despojos do Pecado" do seu Deck à sua mão. \r\nSe este card for destruído em batalha ou por um efeito de card: você pode adicionar 1 Magia "Despojos do Pecado" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73398797,'Paladino do Dragão Branco',replace(replace('Você pode Invocar este card por Invocação-Ritual com "Ritual do Dragão Branco". \r\nNo começo da Etapa de Dano, se este card atacar um monstro com a face para baixo em Posição de Defesa: destrua esse monstro com a face para baixo. \r\nVocê pode oferecer este card como Tributo; Invoque por Invocação-Especial 1 "Dragão Branco de Olhos Azuis" da sua mão ou do Deck, mas "Dragão Branco de Olhos Azuis" não pode atacar pelo resto deste turno.','\r',char(13)),'\n',char(10)),'Destruir','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73405179,'Cavaleiro de Ferro',replace(replace('Perde 1000 de ATK enquanto você controlar "Hans de Ferro". \r\nSe este card no campo for destruído em batalha ou enviado para o Cemitério por um efeito de card: você pode adicionar 1 "Hans de Ferro" do seu Deck à sua mão, ou, se "Castelo Dourado de Stromberg" estiver em uma Zona do Campo, em vez disso, você pode adicionar 1 monstro Guerreiro do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Cavaleiro de Ferro" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73413514,'Absorvedor do Pesadelo Sem Fim',replace(replace('Ganha 1000 de ATK sempre que seu oponente ativar um efeito de monstro. \r\nSe seu oponente ativar um efeito de monstro na mão, no Cemitério ou no banimento dele (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial do seu Cemitério (se ele estava lá quando o efeito ativou) ou da mão (mesmo se ele não estava), mas destrua-o durante a Fase Final. \r\nVocê só pode usar este efeito de "Absorvedor do Pesadelo Sem Fim" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73414375,'Jarro Dimensional','VIRE: Ambos os jogadores podem remover de jogo até 3 cards do Cemitério do seus próprios adversários.','Banir','Escolher um card para banir?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73417207,'Mara do Alfar Nórdico','Quando usar este card como uma Matéria Sincro, as outras Matérias Sincro devem ser 2 monstros "Nórdic" da sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73421698,'Shif, a Fada dos Ghoti',replace(replace('Você pode banir este card do seu Cemitério e, depois, escolha 1 monstro Peixe que você controla; ele ganha 500 de ATK até o final deste turno. \r\nDurante a Fase de Apoio do próximo turno depois que este card foi banido: você pode Invocar este card banido por Invocação-Especial. \r\nDurante a Fase Principal do seu oponente, se este card foi Invocado por Invocação-Especial neste turno, você pode (Efeito Rápido): imediatamente depois que este efeito resolver, Invoque por Invocação-Sincro 1 Monstro Sincro Peixe usando este card que você controla. \r\nVocê só pode usar cada efeito de "Shif, a Fada dos Ghoti" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73422829,'Camada Branca Super Quantum',replace(replace('Você pode enviar para o Cemitério 1 monstro "Super Quant" que não seja de LUZ da sua mão ou com a face para cima no campo; Invoque este card por Invocação-Especial da sua mão em Posição de Defesa. \r\nQuando este card for Invocado por Invocação-Normal ou Especial: você pode enviar 1 monstro "Super Quant" do seu Deck para o Cemitério e, se isso acontecer, o Atributo e o Nível deste card se tornam o mesmo que o desse monstro. \r\nSe este card for enviado para o Cemitério: você pode adicionar 1 "Fada Alfan Super Quantal" do seu Deck ou Cemitério à sua mão. \r\nVocê só pode usar cada efeito de "Camada Branca Super Quantum" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73428497,'Engrenagiarsenal',replace(replace('Este card ganha 200 de ATK para cada monstro "Engrenagi" que você controla. \r\nVocê pode oferecer este card como Tributo; Invoque por Invocação-Especial 1 monstro "Engrenagi" do seu Deck em Posição de Defesa, exceto "Engrenagiarsenal".','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73431236,'Ferreiro Kotetsu','VIRE: Adicione 1 Magia de Equipamento do seu Deck à sua mão.','Adicione uma Magia de Equipamento','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73443672,'Círculo do Submundo',replace(replace('Você só pode ativar 1 "Círculo do Submundo" por Duelo.\r\nAtive este card se houver 5 ou mais monstros em cada Cemitério; destrua quantos monstros no campo possível, então cada jogador bani todos os monstros de seus Decks com a face para baixo, então você pode Invocar 1 Monstro Normal por Invocação-Especial do seu Cemitério.\r\nUma vez por turno, durante a Fase de Apoio: cada jogador pode Invocar 1 monstro por Invocação-Especial de seu Cemitério, ignorando suas condições de Invocação, mas bana-o quando sair do campo.','\r',char(13)),'\n',char(10)),'Ativar','Invocação Especial','Invocação Especial?','Invocar por Invocação Especial, ignorando suas condições de Invocação?','Invocado por Invocação Especial pelo efeito de "Círculo do Submundo"','','','','','','','','','','','');
INSERT INTO texts VALUES(73445448,'Número 22: Zumbistein',replace(replace('2 monstros de TREVAS de Nível 8	\r\nDeve ser Invocado por Invocação-Xyz. \r\nUma vez por turno (Efeito Rápido): você pode desassociar 1 matéria deste card e enviar 1 card da sua mão para o Cemitério e, depois, escolha 1 card com a face para cima que seu oponente controla; coloque este card em Posição de Defesa e, se isso acontecer, negue os efeitos do card alvo até o final deste turno.','\r',char(13)),'\n',char(10)),'Negar o efeito','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73452089,'Cavalaria Negra',replace(replace('"Mago Negro" + 1 monstro Guerreiro	\r\nGanha 100 de ATK para cada Magia/Armadilha no campo e nos Cemitérios. \r\nSe este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente. \r\nQuando um card ou efeito for ativado que escolha um card no campo como alvo (Efeito Rápido): você pode descartar 1 card; negue a ativação e, se isso acontecer, destrua-o.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73468603,'Rotação de Cenário',replace(replace('Baixe 2 Magias de Campo com nomes diferentes do seu Deck no campo (1 no seu campo e 1 no campo do seu oponente). \r\nEnquanto qualquer um desses cards permanecer Baixado no campo, nenhum duelista pode ativar ou Baixar outras Magias de Campo.','\r',char(13)),'\n',char(10)),'Escolha um card para Baixar no seu campo','Escolha um card para Baixar no campo do oponente','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73478096,'Soberano de Fóton',replace(replace('Se este card for enviado para o Cemitério, exceto do campo, enquanto outro monstro "Fóton" ou "Galáxia" estiver no seu campo ou no seu Cemitério: você pode Invocar este card por Invocação-Especial em Posição de Defesa. \r\nVocê só pode usar este efeito de "Soberano de Fóton" uma vez por turno. \r\nDepois que você Invocar este card por Invocação-Normal ou Especial, você pode Invocar por Invocação-Normal 1 monstro de LUZ durante sua Fase Principal neste turno, em adição à sua Invocação-Normal/Baixar (padrão). \r\n(Você só pode se aproveitar deste efeito uma vez por turno.)','\r',char(13)),'\n',char(10)),'','Invocar pelo efeito de "Soberano de Fóton"','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73481154,'Golem Destruidor','Um golem com uma poderosa mão direita e que a usa para esmagar as suas vítimas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73483491,'Vindikite Genex-R',replace(replace('1 Regulador "Genex" + 1+ monstros não-Reguladores de VENTO	\r\nOs monstros do seu oponente não podem escolher este card como alvo de ataques. \r\nQuando este card destruir um monstro do oponente em batalha: você pode adicionar 1 monstro "Genex" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73490417,'Habitante da Selva',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial por um efeito de card. \r\nEnquanto houver 2 cards nas Zonas do Campo, seu oponente não pode escolher este card como alvo de efeitos de card. \r\nVocê só pode usar cada um dos seguintes efeitos de "Habitante da Selva" uma vez por turno. \r\nVocê pode banir 1 monstro de LUZ ou de TREVAS do seu Cemitério; Invoque este card por Invocação-Especial da sua mão. \r\nSe este card em posse do seu dono for destruído por um card do oponente: você pode embaralhar no Deck até 2 das suas Magias de Campo do seu Cemitério ou banimento e, depois, você pode destruir até esse número de cards que seu oponente controla.','\r',char(13)),'\n',char(10)),'Destruir um card que seu oponente controla?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73496100,'Ilusão Gagaga',replace(replace('Se você controlar um monstro "Gagaga": escolha 1 monstro no seu Cemitério; Invoque-o por Invocação-Especial e, depois, você pode fazer com que seu Nível/Classe se torne igual ao de 1 monstro "Gagaga" que você controla. \r\nSe este card estiver no seu Cemitério, exceto no turno em que foi enviado para lá: você pode bani-lo; imediatamente depois que este efeito resolver, Invoque por Invocação-Normal 1 monstro "Gagaga". \r\nVocê só pode usar cada efeito de "Ilusão Gagaga" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Invocação Normal adicional','Alterar Nível/Classe?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73507661,'Vento Feérico','Destrua tantas Magias/Armadilhas com a face para cima no campo quanto possível, exceto este card e, se isso acontecer, cada duelista sofre dano igual ao número total de cards destruídos por este efeito x 300.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73511233,'Camarartista U Go Golem',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno, se um monstro for Invocado por Invocação-Fusão no seu campo (exceto durante a Etapa de Dano): você pode adicionar à sua mão 1 Monstro Pêndulo "Camarartista", "Olhos Anômalos" ou "Mago" do seu Cemitério ou com a face para cima no seu Deck Adicional.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nUma vez por turno, durante sua Fase Principal, se este card foi Invocado por Invocação-Pêndulo neste turno: você pode Invocar por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional, usando este card que você controla e monstros Dragão que você controla como Matérias de Fusão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73534250,'Asanegra - Tornado, o Giro Reverso','Quando este card for Invocado por Invocação-Normal enquanto seu oponente controlar um monstro Invocado por Invocação-Especial: você pode escolher 1 Regulador "Asanegra" no seu Cemitério; você não pode Invocar monstros por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto monstros "Asanegra" e, além disso, Invoque esse monstro por Invocação-Especial, mas seus efeitos são negados.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73539069,'Dragão Golpeador',replace(replace('1 monstro Dragão de Nível 4 ou menos	\r\nSe este card for Invocado por Invocação-Link: você pode adicionar 1 "Lançar Registro de Inicialização" do seu Deck à sua mão. \r\nVocê pode escolher 1 monstro com a face para cima que você controla e 1 monstro "Foguette" no seu Cemitério; destrua esse monstro no campo e, se isso acontecer, adicione o outro monstro do Cemitério à sua mão. \r\nVocê só pode usar cada efeito de "Dragão Golpeador" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73542331,'Shangri-Ira Kashtira',replace(replace('2+ monstros de Nível 7	\r\nDurante cada Fase de Apoio: você pode Invocar por Invocação-Especial 1 monstro "Kashtira" do seu Deck. \r\nVocê só pode usar o efeito anterior de "Shangri-Ira Kashtira" uma vez por turno. \r\nSempre que um ou mais cards dos quais seu oponente seja dono e em posse dele seja banido com a face para baixo (exceto durante a Etapa de Dano): você pode selecionar 1 Zona de Monstros Principal ou Zona de Magias & Armadilhas não utilizada; ela não pode ser usada enquanto este monstro estiver com a face para cima no campo. \r\nSe este card no campo seria destruído em batalha ou por um efeito de card, em vez disso, você pode desassociar 1 matéria deste card.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial do Deck','A zona selecionado não pode ser usada','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73544866,'Guardião Baou',replace(replace('Este card pode ser Invocado, por Invocação-Normal, Invocação-Virar, ou Invocação-Especial apenas quando "Flamberge Perverso - Baou" estiver no seu Campo. \r\nCada vez que este card destrói 1 dos monstros do seu adversário como resultado de um combate e o envia para o Cemitério, aumente o ATK deste card em 1000 pontos. \r\nO efeito de um Monstro de Efeito que este card destrúa como resultado de um combate é anulado.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73551138,'Emília Gishki',replace(replace('Não pode ser Invocado por Invocação-Especial. \r\nDurante a Fase Final do turno em que este card for Invocado por Invocação-Normal ou virado com a face para cima: Devolva-o para a mão. \r\nQuando este card for Invocado por Invocação-Normal ou virado com a face para cima: Negue todos os efeitos de Cards de Armadilha no campo, até a Fase Final. \r\nVocê deve controlar outro monstro "Gishki" com a face para cima para ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Retornar à mão','Negue os efeitos de Armadilhas','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73558460,'Cinet Recuperação',replace(replace('Se um ou mais Monstros Link que você controla forem destruídos em batalha ou por um efeito de card do oponente: você pode escolher 1 monstro no seu Cemitério, exceto um Monstro Link; Invoque-o por Invocação-Especial em Posição de Defesa. \r\nVocê só pode usar este efeito de "Cinet Recuperação" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73567374,'Liberte o Seu Poder!',replace(replace('Todos os Monstros Gêmeos que estavam no seu lado do campo quando este card foi ativado são considerados como Monstros de Efeito, e ganham seu(s) efeito(s). \r\nDurante a Fase Final deste turno, Baixe todos os monstros afetados pelo efeito deste card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73574678,'Amazoness da Zarabatana',replace(replace('Escolha 1 monstro no Campo do seu adversário com a face para cima durante cada uma das suas Standby Phases. \r\nDiminua o ATK do monstro escolhido em 500 pontos até ao final do turno.','\r',char(13)),'\n',char(10)),'Reduzir ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73575650,'Sucessão Subterror',replace(replace('Ative 1 desses efeitos e, além disso, depois, Baixe este card com a face para baixo em vez de enviá-lo para o Cemitério.\r\n● Envie 1 monstro da sua mão ou do campo com a face para cima para o Cemitério e, se isso acontecer, adicione 1 monstro de Virar do seu Deck à sua mão com o mesmo Atributo, mas com um nome diferente, que o desse monstro antes de ele ser enviado para o Cemitério.\r\n● Envie 1 monstro de Virar da sua mão ou do campo com a face para cima para o Cemitério e, se isso acontecer, adicione 1 monstro do seu Deck à sua mão com o mesmo Atributo, mas um Nível original menor, que o desse monstro antes de ele ser enviado para o Cemitério.	\r\nVocê só pode ativar 1 "Sucessão Subterror" por turno.','\r',char(13)),'\n',char(10)),'Adicione um monstro de Virar com um nome diferente','Adicione um monstro de Nível inferior','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73578229,'Pole Position',replace(replace('O(s) monstro(s) com a face para cima com o maior ATK no Campo não é afetado por qualquer Card de Magia. \r\nQuando "Pole Position" é removido do Campo, destrúa o monstro(s) com o maior ATK no Campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73580471,'Dragão da Rosa Negra',replace(replace('1 Regulador + 1+ não-Reguladores	\r\nQuando este card for Invocado por Invocação-Sincro: você pode destruir todos os cards no campo. \r\nUma vez por turno: você pode banir 1 monstro Planta do seu Cemitério e, depois, escolha 1 monstro em Posição de Defesa que seu oponente controla; coloque o alvo com a face para cima em Posição de Ataque e, se isso acontecer, o ATK dele se torna 0 até o final deste turno.','\r',char(13)),'\n',char(10)),'Destrua todos os cards no campo','Mudar a posição de batalha','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73580472,'Dragão da Rosa Negra',replace(replace('1 Regulador + 1+ não-Reguladores	\r\nQuando este card for Invocado por Invocação-Sincro: você pode destruir todos os cards no campo. \r\nUma vez por turno: você pode banir 1 monstro Planta do seu Cemitério e, depois, escolha 1 monstro em Posição de Defesa que seu oponente controla; coloque o alvo com a face para cima em Posição de Ataque e, se isso acontecer, o ATK dele se torna 0 até o final deste turno.','\r',char(13)),'\n',char(10)),'Destrua todos os cards no campo','Mudar a posição de batalha','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73580473,'Dragão da Rosa Negra',replace(replace('1 Regulador + 1+ não-Reguladores	\r\nQuando este card for Invocado por Invocação-Sincro: você pode destruir todos os cards no campo. \r\nUma vez por turno: você pode banir 1 monstro Planta do seu Cemitério e, depois, escolha 1 monstro em Posição de Defesa que seu oponente controla; coloque o alvo com a face para cima em Posição de Ataque e, se isso acontecer, o ATK dele se torna 0 até o final deste turno.','\r',char(13)),'\n',char(10)),'Destrua todos os cards no campo','Mudar a posição de batalha','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73594093,'Fusão Metalmorfose',replace(replace('Invoque por Invocação-Fusão 1 Monstro de Fusão "Metalmorfose" do seu Deck Adicional, usando monstros da sua mão ou do campo como Matérias de Fusão. \r\nSe este card estiver no seu Cemitério: você pode embaralhá-lo no Deck e, depois, compre 1 card. \r\nVocê só pode usar este efeito de "Fusão Metalmorfose" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Fusão','Comprar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73599290,'Drenar Alma',replace(replace('Ative ao pagar 1000 PV. \r\nMonstros banidos, assim como monstros no Cemitério, não podem ativar seus efeitos.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73602965,'Arias, o Mordomo de Labrinto',replace(replace('Durante a Fase Principal (Efeito Rápido): você pode enviar para o Cemitério este card da sua mão ou do campo; Invoque por Invocação-Especial 1 monstro "Labrinto" ou Baixe 1 Armadilha Normal, da sua mão. \r\nA Armadilha Normal Baixada pode ser ativada neste turno. \r\nQuando seu oponente ativar um card ou efeito em resposta à ativação de um dos seus cards ou efeitos de uma Armadilha Normal ou um card "Labrinto", exceto "Arias, o Mordomo de Labrinto" (Efeito Rápido): você pode ativar este efeito no Cemitério; Invoque este card por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Arias, o Mordomo de Labrinto" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Ativar aplicando o efeito de "Arias, o Mordomo de Labrinto".','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73616671,'Mágica de Ilusão',replace(replace('Ofereça como Tributo 1 monstro Mago; adicione até 2 cópias de "Mago Negro" do seu Deck e/ou Cemitério à sua mão. \r\nVocê só pode ativar 1 "Mágica de Ilusão" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73625877,'Fugitivo do Tempo','Durante o turno de qualquer duelista: você pode descartar este card e, depois, escolher 1 monstro do Tipo Psíquico que você controla; bana-o até sua próxima Fase de Apoio.','Banir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73628505,'Transformação Campal','Adicione 1 Magia de Campo do seu Deck à sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73632127,'Corte Dimensional',replace(replace('Quando um ou mais monstros forem Invocados por Invocação-Especial no seu lado do campo (exceto durante a Etapa de Dano): escolha 1 monstro com a face para cima que seu oponente controla; bana o alvo. \r\nSe a Invocação for uma Invocação-Xyz, você pode ativar este card no turno em que ele foi Baixado.','\r',char(13)),'\n',char(10)),'Ativar aplicando o efeito de "Corte Dimensional".','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73639099,'Armadilhatrix Sera',replace(replace('1 monstro "Armadilhatrix" que não seja Link	\r\nEste card Invocado por Invocação-Link não é afetado por efeitos de Armadilha. \r\nVocê só pode usar cada um dos seguintes efeitos de "Armadilhatrix Sera" uma vez por turno e não durante a Etapa de Dano. \r\nSe um Card de Armadilha Normal for ativado: você pode Invocar por Invocação-Especial 1 monstro "Armadilhatrix" do seu Deck com um nome diferente que o dos cards que você controla. \r\nSe um efeito de outro monstro "Armadilhatrix" seu for ativado: você pode Baixar 1 Armadilha Normal "Buraco" do seu Deck.','\r',char(13)),'\n',char(10)),'Invocação Especial','Baixar uma Armadilha','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73639100,'Armadilhatrix Sera',replace(replace('1 monstro "Armadilhatrix" que não seja Link	\r\nEste card Invocado por Invocação-Link não é afetado por efeitos de Armadilha. \r\nVocê só pode usar cada um dos seguintes efeitos de "Armadilhatrix Sera" uma vez por turno e não durante a Etapa de Dano. \r\nSe um Card de Armadilha Normal for ativado: você pode Invocar por Invocação-Especial 1 monstro "Armadilhatrix" do seu Deck com um nome diferente que o dos cards que você controla. \r\nSe um efeito de outro monstro "Armadilhatrix" seu for ativado: você pode Baixar 1 Armadilha Normal "Buraco" do seu Deck.','\r',char(13)),'\n',char(10)),'Invocação Especial','Baixar uma Armadilha','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73640163,'Clérigo Pinguim',replace(replace('Se um ou mais monstros "Pinguim" forem enviados da sua Zona de Monstros para o seu Cemitério por um card do oponente, mesmo durante a Etapa de Dano: você pode escolher 1 deles; descarte este card e, se isso acontecer, Invoque esse monstro por Invocação-Especial com a face para baixo em Posição de Defesa. \r\nVocê só pode usar este efeito de "Clérigo Pinguim" uma vez por turno. \r\nUma vez por turno: você pode escolher 1 monstro "Pinguim" que você controla; ele ganha 600 de ATK até o final do turno e você ganha 600 PV.','\r',char(13)),'\n',char(10)),'Descartar e Invocar por Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73642296,'Fantasma Belle & Mansão Assombrada',replace(replace('Quando um card ou efeito for ativado que inclua qualquer um desses efeitos (Efeito Rápido): você pode descartar este card; negue a ativação.\r\n● Adicionar um ou mais cards do Cemitério à mão, ao Deck e/ou ao Deck Adicional.\r\n● Invocar por Invocação-Especial um ou mais Cards de Monstro do Cemitério.\r\n● Banir um ou mais cards do Cemitério.	\r\nVocê só pode usar este efeito de "Fantasma Belle & Mansão Assombrada" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73642297,'Fantasma Belle & Mansão Assombrada',replace(replace('Quando um card ou efeito for ativado que inclua qualquer um desses efeitos (Efeito Rápido): você pode descartar este card; negue a ativação.\r\n● Adicionar um ou mais cards do Cemitério à mão, ao Deck e/ou ao Deck Adicional.\r\n● Invocar por Invocação-Especial um ou mais Cards de Monstro do Cemitério.\r\n● Banir um ou mais cards do Cemitério.	\r\nVocê só pode usar este efeito de "Fantasma Belle & Mansão Assombrada" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73642298,'Fantasma Belle & Mansão Assombrada',replace(replace('Quando um card ou efeito for ativado que inclua qualquer um desses efeitos (Efeito Rápido): você pode descartar este card; negue a ativação.\r\n● Adicionar um ou mais cards do Cemitério à mão, ao Deck e/ou ao Deck Adicional.\r\n● Invocar por Invocação-Especial um ou mais Cards de Monstro do Cemitério.\r\n● Banir um ou mais cards do Cemitério.	\r\nVocê só pode usar este efeito de "Fantasma Belle & Mansão Assombrada" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73648243,'Mariposa de Areia','Se este card com a face para baixo em Posição de Defesa for destruído e enviado para o Cemitério: Invoque-o por Invocação-Especial e troque seu ATK original pela DEF original, e vice-versa.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73652465,'Asanegra - Oroshi, a Rajada de Vento',replace(replace('Se você controlar um monstro "Asanegra" que não seja "Asanegra - Oroshi, a Rajada de Vento", você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Asanegra - Oroshi, a Rajada de Vento" por Invocação-Especial uma vez por turno desta forma. \r\nSe este card for enviado para o Cemitério como uma Matéria Sincro: você pode escolher 1 monstro no campo; mude a posição de batalha do alvo.','\r',char(13)),'\n',char(10)),'Mudar a posição de batalha','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73659078,'Gigante de Pó de Neve',replace(replace('2 monstros de ÁGUA de Nível 4	\r\nUma vez por turno: Você pode desassociar 1 Matéria Xyz deste card; revele qualquer número de monstros de ÁGUA da sua mão e coloque essa quantidade de Marcadores de Gelo em monstros com a face para cima no campo. \r\nMonstros que não sejam de ÁGUA no campo perdem 200 de ATK para cada Marcador de Gelo no campo.','\r',char(13)),'\n',char(10)),'Colocar um marcador','Escolha o monstro no qual colocar um Marcador de Gelo','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73664385,'Magia Verre - Lacrima da Luz',replace(replace('(Este card deve ser sempre considerado como um card "Magistus" e "Fazticeira".)	\r\nAtive 1 desses efeitos (mas você só pode usar cada efeito de "Magia Verre - Lacrima da Luz" uma vez por turno);\r\n● Se você controlar um monstro "Magistus" ou "Fazticeira": envie 1 monstro Mago ou 1 Magia do seu Deck para o Cemitério.\r\n● Quando seu oponente ativar um card ou efeito: Invoque por Invocação-Especial 1 monstro "Magistus" ou "Fazticeira" da sua mão ou do Deck.','\r',char(13)),'\n',char(10)),'Ativar','Enviar para o Cemitério','Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73665146,'Mago Silencioso LV4',replace(replace('Sempre que seu oponente comprar um ou mais cards, coloque 1 Marcador de Magia neste card (máx. 5). \r\nEste card ganha 500 de ATK para cada Marcador de Magia sobre ele. \r\nDurante a Fase de Apoio do seu próximo turno depois que o 5º Marcador de Magia for colocado neste card: você pode enviar este card com a face para cima com 5 Marcadores de Magia sobre ele para o Cemitério; Invoque por Invocação-Especial 1 "Mago Silencioso LV8" da sua mão ou Deck.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73667937,'Ventobruxa - Sino de Diamante',replace(replace('1 Regulador + 1+ monstros de VENTO não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro: você pode escolher 1 monstro "Ventobruxa" no seu Cemitério; cause dano ao seu oponente igual à metade do ATK dele. \r\nVocê só pode usar este efeito de "Ventobruxa - Sino de Diamante" uma vez por turno. \r\nUma vez por turno, se seu oponente sofrer dano de batalha ou de efeito: você pode escolher 1 card no campo; destrua-o. \r\nSe você controlar este card que foi Invocado por Invocação-Sincro usando apenas monstros "Ventobruxa" como matéria, você pode usar este efeito até duas vezes por turno.','\r',char(13)),'\n',char(10)),'Causar dano','Destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73680966,'O Começo do Fim','Se você tiver 7 ou mais monstros de TREVAS no seu Cemitério: bana 5 monstros de TREVAS do seu Cemitério; compre 3 cards.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73694478,'Renascimento do Super Soldado',replace(replace('Escolha 1 monstro "Soldado do Lustro Negro" (ou "Soldado do Brilho Negro - Enviado do Princípio") que você controla; envie-o para o Cemitério e, se isso acontecer, Invoque por Invocação-Especial 1 monstro "Soldado do Lustro Negro" (ou "Soldado do Brilho Negro - Enviado do Princípio") da sua mão com um nome diferente que o desse monstro, ignorando suas condições de Invocação. \r\nDurante sua Fase Principal, exceto no turno em que este card foi enviado para o Cemitério: você pode banir este card do seu Cemitério e, depois, escolher 1 monstro "Soldado do Lustro Negro" (ou "Soldado do Brilho Negro - Enviado do Princípio") no seu Cemitério; adicione-o à sua mão. \r\nVocê só pode ativar 1 "Renascimento do Super Soldado" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73698349,'Orc Gigante',replace(replace('Se este card atacar, ele é colocado em Posição de Defesa no final da Fase de Batalha. \r\nEle não pode mudar sua posição de batalha até o final do seu próximo turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73702909,'Soldadinho','Se este card for destruído em batalha: Você pode Invocar por Invocação-Especial 1 monstro do Tipo Guerreiro de Nível 2 ou menos do seu Deck com a face para baixo em Posição de Defesa.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73714736,'Reinoespada das Chamas',replace(replace('Seu oponente não pode ativar cards ou efeitos quando você Invocar um monstro Guerreiro de FOGO por Invocação-Normal. \r\nUma vez por turno: você pode enviar 1 monstro da sua mão ou do campo com a face para cima para o Cemitério; Invoque por Invocação-Especial 1 "Espadachim das Chamas" do seu Deck Adicional. \r\n(Isso é considerado uma Invocação-Fusão.) \r\nUma vez por turno, quando um monstro declarar um ataque: você pode escolher 1 monstro Guerreiro que você controla; até o final deste turno, ele perde exatamente 1000 de ATK, mas todos os outros monstros que você controla atualmente ganham 1000 de ATK.','\r',char(13)),'\n',char(10)),'Invoque "Espadachim das Chamas" por Invocação Fusão','Reduza o ATK de um monstro e aumente o ATK dos outros monstros','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73729209,'Sucessor em Habilidade',replace(replace('Escolha 1 monstro com a face para cima que você controla; ele ganha 400 de ATK até o final deste turno. \r\nDurante o seu turno, exceto no turno em que este card foi enviado para o Cemitério: você pode banir este card do seu Cemitério e, depois, escolha 1 monstro com a face para cima que você controla; o alvo ganha 800 de ATK até o final deste turno.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73734821,'Camarartista Mago do Céu',replace(replace('Uma vez por turno, se você ativar um Card de Magia: este card ganha 300 de ATK. \r\n(Efeito Rápido): você pode escolher 1 Magia Contínua que você controla; devolva-a para a mão e, depois, você pode ativar 1 Magia Contínua "Mago" da sua mão. \r\nVocê só pode usar este efeito de "Camarartista Mago do Céu" uma vez por turno. \r\nSe este card com a face para cima deixar o campo: você pode escolher 1 card no campo; destrua-o.','\r',char(13)),'\n',char(10)),'Este card ganha ATK','Retornar à mão sua Magia Contínua','Ativar "Mago" como Magia Contínua?','Destruir um card no Campo','','','','','','','','','','','','');
INSERT INTO texts VALUES(73752131,'Mago Negro Habilidoso',replace(replace('Sempre que um Card de Magia for ativado, coloque 1 Marcador de Magia neste card quando essa Magia resolver (máx. 3). \r\nVocê pode oferecer como Tributo este card com 3 Marcadores de Magia sobre ele; Invoque por Invocação-Especial 1 "Mago Negro" da sua mão, do Deck ou do Cemitério.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73776643,'Papamilho','Enquanto um Card de Magia de Campo estiver com a face para cima no campo, este card ganha 1000 de ATK.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73778008,'Ira do Mar Profundo','Este card ganha 500 de ATK e DEF para cada monstro do Tipo Peixe, Serpente Marinha ou Aqua no seu Cemitério.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73779005,'Dragoons de Draconia',replace(replace('Escala de Pêndulo = 2\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno, se um Monstro Normal que você controla destruir um monstro do oponente em batalha, depois do cálculo de dano: você pode adicionar 1 Monstro Normal de Nível 4 ou mais do seu Deck à sua mão.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nArmado com mosquetes e lanças de ferro, essas tropas montadas terrestres do Império de Draconia são temidas pelo Reino Réptil e outras nações fronteiriças.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73783043,'Acelerador Genex-R','Quando um ou mais monstros "Genex" forem adicionados do seu Deck à sua mão: você pode revelar 1 deles; Invoque-o por Invocação-Especial.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73787254,'Cofre-de-Sabres','Cada monstro "Sabre-X" com a face para cima no campo ganha 100 de ATK x o seu Nível e perde 100 de DEF x o seu Nível.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73810864,'Live☆Gêmea Lil-la',replace(replace('Seu oponente deve pagar 500 PV para declarar um ataque. \r\nSe este card for Invocado por Invocação-Normal ou Especial e você não controlar nenhum outro monstro: você pode Invocar por Invocação-Especial 1 monstro "Ki-sikil" da sua mão ou do Deck. \r\nVocê só pode usar este efeito de "Live☆Gêmea Lil-la" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73819701,'Caído do Dragão Branco',replace(replace('(Este card deve ser sempre considerado como "Caído de Arbaz".)	\r\nSe este card estiver na sua mão: você pode enviar 1 monstro que mencione "Caído de Arbaz" do seu Deck Adicional para o Cemitério; Invoque este card por Invocação-Especial e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto Monstros de Fusão ou Sincro de Nível 8. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode Invocar por Invocação-Especial 1 monstro "Ecclesia" da sua mão, do Deck ou do Cemitério. \r\nVocê só pode usar cada efeito de "Caído do Dragão Branco" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar este card por Invocação Especial','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73820802,'Onikuji',replace(replace('Uma vez por turno, durante sua Fase de Apoio: seu oponente declara 1 tipo de card (Monstro, Magia ou Armadilha). \r\nEscave o card do topo do seu Deck e, depois, se for um card desse tipo, seu oponente compra 1 card. \r\nCaso contrário, descarte 1 card aleatório da mão dele. \r\nColoque o card escavado no fundo do seu Deck.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73828446,'APARATO ESPIRÃO - Totalmente Armado',replace(replace('Só pode ser equipado a "Super Agente ESPIRÃO". \r\nEle ganha 1000 de ATK. \r\nSe ele destruir um monstro do oponente seu em batalha: você pode banir tanto o monstro destruído do oponente quanto 1 outro card que seu oponente controla. \r\nQuando este card com a face para cima no campo for destruído e enviado para o Cemitério: você pode escolher 1 "Super Agente ESPIRÃO" no seu Cemitério; Invoque-o por Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73837870,'Pixie Ensolarada','Se este card for enviado ao Cemitério para a Invocação-Sincro de um Monstro Sincro de LUZ: Ganhe 1000 PV.','Ganhar PV','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73853830,'Cruzado de Endymion',replace(replace('Este card é considerado como um Monstro Normal enquanto estiver com a face para cima no campo ou no Cemitério. \r\nEnquanto este card for um Monstro Normal no campo, você pode Invocá-lo por Invocação-Normal para fazer com que ele se torne um Monstro de Efeito com este efeito.\r\n● Uma vez por turno: você pode escolher 1 card com a face para cima no campo sobre o qual você possa colocar um Marcador de Magia; coloque 1 Marcador de Magia sobre ele e, se isso acontecer, este card ganha 600 de ATK até o final deste turno.','\r',char(13)),'\n',char(10)),'Colocar Marcadores de Magia','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73860462,'Maravilha Xyz','Imediatamente depois que este efeito resolver, Invoque 1 Monstro Xyz por Invocação-Xyz, usando monstros que você controla como Matérias.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73866096,'Dododocomprar',replace(replace('Envie 1 monstro "Dododo" da sua mão ou com a face para cima no seu lado do campo para o Cemitério; compre 2 cards. \r\nVocê só pode ativar 1 "Dododocomprar" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73872164,'Eliminando a Liga','Descarte 1 Magia e, depois, escolha 1 monstro com a face para cima que seu oponente controla; destrua o alvo e, depois, olhe a mão do seu oponente e envie para o Cemitério todos os cards na mão dele com o mesmo nome que o do card destruído.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73879377,'Dragão Armado LV7',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial por "Dragão Armado LV5". \r\nVocê pode enviar 1 monstro da sua mão para o Cemitério; destrua todos os monstros que seu oponente controla com ATK igual ou menor que o ATK desse monstro enviado.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73881652,'Combo Zoodíaco',replace(replace('Escolha 1 Monstro Xyz "Zoodíaco(a)" que você controla; associe 1 monstro "Zoodíaco(a)" do seu Deck a esse Monstro Xyz como Matéria Xyz. \r\nDurante o turno de qualquer duelista, exceto no turno em que este card foi enviado para o Cemitério: você pode banir este card do seu Cemitério e, depois, escolher 5 cards "Zoodíaco(a)" com nomes diferentes no seu Cemitério; embaralhe todos os 5 no Deck e, depois, compre 1 card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73887236,'Ataqueraptor - Falcão Ascendente',replace(replace('3 monstros do Tipo Besta Alada de Nível 4	\r\nEste card pode atacar todos os monstros Invocados por Invocação-Especial que seu oponente controla, uma vez cada. \r\nUma vez por turno: você pode desassociar 1 Matéria Xyz deste card e, depois, escolher 1 monstro Invocado por Invocação-Especial com a face para cima que seu oponente controla; este card ganha ATK igual ao ATK atual desse monstro.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73891874,'Dragão de Chifre Branco','Quando este card for Invocado por Invocação-Normal ou Especial: Escolha até 5 Cards de Magia no Cemitério do oponente; bana o(s) alvo(s) e, se isso acontecer, este card ganha 300 de ATK para cada card banido por este efeito.','Banir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73898890,'Daina Mondo',replace(replace('2 monstros, incluindo um Monstro de Ritual	\r\nSe este card for Invocado por Invocação-Especial: você pode escolher 1 card no campo e 1 Monstro de Ritual no seu Cemitério; embaralhe os dois no Deck. \r\nDurante o turno do seu oponente (Efeito Rápido): você pode oferecer este card como Tributo e, depois, escolha 1 Monstro de Ritual no seu Cemitério; adicione-o à sua mão ou Invoque-o por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Daina Mondo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73899015,'Víbora da Peçonha',replace(replace('Uma vez por turno, você pode colocar 1 Marcador de Veneno sobre 1 monstro que seu oponente controla. \r\nSe você ativar este efeito, este card não pode atacar durante este turno.','\r',char(13)),'\n',char(10)),'Colocar um marcador','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73906480,'Bujincarnação',replace(replace('Se seu oponente controlar um monstro e você não controlar nenhum monstro: escolha 1 monstro "Bujin" no seu Cemitério e 1 dos seus monstros "Bujin" banidos; Invoque os dois alvos por Invocação-Especial. \r\nEles não podem ser usados como Matéria Xyz para Invocações-Xyz, exceto para a Invocação-Xyz de um monstro do Tipo Besta, Besta-Guerreira ou Besta Alada.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73911410,'Matador com Espada','Um motor letal de destruição que empunha duas lâminas afiadas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73915051,'Bode Expiatório',replace(replace('Invoque por Invocação-Especial 4 "Ficha de Ovelha" (Besta/TERRA/Nível 1/ATK 0/DEF 0) em Posição de Defesa. \r\nElas não podem ser oferecidas como Tributo para uma Invocação-Tributo. \r\nVocê não pode Invocar outros monstros no turno em que ativar este card (mas pode Baixá-los Normalmente).','\r',char(13)),'\n',char(10)),'Invocar uma Ficha por Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73915052,'Ficha de Ovelha','Invocado por Especial com o efeito "Bode Expiatório". Esta Ficha não pode ser oferecida como Tributo para uma Invocação-Tributo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73915053,'Ficha de Ovelha','Invocado por Especial com o efeito "Bode Expiatório". Esta Ficha não pode ser oferecida como Tributo para uma Invocação-Tributo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73915054,'Ficha de Ovelha','Invocado por Especial com o efeito "Bode Expiatório". Esta Ficha não pode ser oferecida como Tributo para uma Invocação-Tributo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73915055,'Ficha de Ovelha','Invocado por Especial com o efeito "Bode Expiatório". Esta Ficha não pode ser oferecida como Tributo para uma Invocação-Tributo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73915056,'Bode Expiatório',replace(replace('Invoque por Invocação-Especial 4 "Ficha de Ovelha" (Besta/TERRA/Nível 1/ATK 0/DEF 0) em Posição de Defesa. \r\nElas não podem ser oferecidas como Tributo para uma Invocação-Tributo. \r\nVocê não pode Invocar outros monstros no turno em que ativar este card (mas pode Baixá-los Normalmente).','\r',char(13)),'\n',char(10)),'Invocar uma Ficha por Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73936388,'Espadachim Miragem',replace(replace('Se um ou mais Monstros de Fusão de FOGO com a face para cima que você controla forem destruídos em batalha ou por um efeito de card: você pode Invocar este card por Invocação-Especial do seu Cemitério (se ele estava lá quando o monstro foi destruído) ou da mão (mesmo se ele não estava). \r\nNo começo da Etapa de Dano, se este card batalhar um monstro do oponente: você pode destruir os dois monstros que estão batalhando. \r\nSe este card for destruído em batalha ou pelo efeito de outro card: você pode Invocar por Invocação-Especial 1 monstro de Nível 7 ou menos que seja "Espadachim das Chamas", ou que o mencione, do seu Deck ou Deck Adicional. \r\nVocê só pode usar cada efeito de "Espadachim Miragem" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar-se por Invocação Especial','Destrua os monstros de ambos os jogadores','Invoque por Invocação Especial "Espadachim das Chamas" ou Invoque por Invocação Especial um monstro que o mencione','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73941492,'Mago Harmônico',replace(replace('Escala de Pêndulo = 8\r\n[ Efeito de Pêndulo ]\r\nTodos os monstros que você controla ganham 100 de ATK e DEF para cada Monstro Pêndulo "Mago" com a face para cima com um nome diferente no seu Deck Adicional.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nNão pode ser Invocado por Invocação-Especial do Deck Adicional. \r\nNão pode ser usado como matéria para uma Invocação-Fusão, Sincro ou Xyz, a não ser que todas as outras matérias sejam Monstros Pêndulo "Mago". \r\nQuando este card for Invocado por Invocação-Pêndulo da mão: você pode Invocar por Invocação-Especial 1 Monstro Pêndulo "Mago" do seu Deck em Posição de Defesa, exceto "Mago Harmônico", mas negue seus efeitos e, além disso, bana-o quando ele deixar o campo. \r\nVocê só pode usar este efeito de "Mago Harmônico" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73956664,'Lagrimentiara Reinoheart',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode enviar 1 monstro "Lagrimentiara" do seu Deck para o Cemitério, exceto "Lagrimentiara Reinoheart". \r\nSe este card for enviado para o Cemitério por um efeito de card: você pode Invocar este card por Invocação-Especial (mas bana-o quando ele deixar o campo) e, se isso acontecer, envie 1 card "Lagrimentiara" da sua mão para o Cemitério. \r\nVocê só pode usar cada efeito de "Lagrimentiara Reinoheart" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73964868,'Constelar Plêiades',replace(replace('2 monstros de LUZ de Nível 5	\r\nUma vez por turno (Efeito Rápido): você pode desassociar 1 matéria deste card e, depois, escolha 1 card no campo; devolva o alvo para a mão.','\r',char(13)),'\n',char(10)),'Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73977033,'Ataqueraptor - Impulsionador Strix','Quando um monstro "Ataqueraptor" que você controla for escolhido como alvo de um ataque por um monstro do oponente: você pode banir este card da sua mão; destrua o monstro atacante.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73979030,'Guarda-chuva Angraecum','Quando este card for Invocado por Invocação-Normal: você pode descartar 1 card e, depois, escolha 1 monstro de Nível 4 ou menos no seu Cemitério; Invoque-o por Invocação-Especial em Posição de Defesa, mas negue seus efeitos e, além disso, pelo resto deste turno, você não pode Invocar monstros do Deck Adicional por Invocação-Especial, exceto Monstros Sincro.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(73988674,'Trestar-e-Adivinhar','Se os dois duelistas tiverem um Deck Adicional: declare 1 tipo de card de monstro do Deck Adicional (Fusão, Sincro ou Xyz); os dois duelistas revelam seu Deck Adicional e o duelista que tiver mais cards do tipo declarado ganha 3000 Pontos de Vida.','Card de Fusão','Card Sincro','Card Xyz','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74003290,'Vento Perdido',replace(replace('Escolha 1 monstro com a face para cima Invocado por Invocação-Especial no campo; negue seus efeitos e, além disso, seu ATK original é diminuído pela metade. \r\nSe um monstro for Invocado por Invocação-Especial do Deck Adicional do seu oponente, enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode Baixar este card, mas bana-o quando ele deixar o campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74009824,'El Sombraneco Wendigo',replace(replace('1 monstro "Sombraneco" + 1 monstro de VENTO	\r\nPrimeiro deve ser Invocado por Invocação-Fusão. \r\n(Efeito Rápido): você pode escolher 1 monstro que você controla; neste turno, ele não pode ser destruído em batalha contra um monstro do oponente Invocado por Invocação-Especial. \r\nVocê só pode usar este efeito de "El Sombraneco Wendigo" uma vez por turno. \r\nSe este card for enviado para o Cemitério: você pode escolher 1 Magia/Armadilha "Sombraneco" no seu Cemitério; adicione-a à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74010769,'Grifo da Chama Nebulosa',replace(replace('Se seu oponente controlar um monstro e todos os monstros (se houver) do seu lado do campo ou no seu Cemitério forem de FOGO (e apenas FOGO), você pode Invocar este card por Invocação-Especial (da sua mão). \r\nSeu oponente não pode escolher este card como alvo de efeitos de card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74011784,'Verniz de Artmage -Alteração-',replace(replace('Coloque 1 "Artmage, Academia Acrópole de Artes Arcanas" do seu Deck ou Cemitério, com a face para cima na sua Zona do Campo, ou se você controlar "Artmage, Academia Acrópole de Artes Arcanas", em vez disso, adicione 1 card "Artmage" do seu Deck à sua mão, exceto "Verniz de Artmage -Alteração-". \r\nQuando um monstro "Artmage" seu for escolhido como alvo de um ataque: você pode banir este card do seu Cemitério; negue o ataque e, depois, você pode Invocar por Invocação-Especial 1 "Medius, o Puro" da sua mão. \r\nVocê só pode usar cada efeito de "Verniz de Artmage -Alteração-" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar','Negar o ataque','Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74018812,'Estufi Cascoruga Labrinto',replace(replace('(Efeito Rápido): você pode enviar este card da sua mão ou do campo para o Cemitério e descartar 1 card; Baixe 1 Magia/Armadilha "Labrinto" da sua mão ou do Deck. \r\nSe um ou mais monstros deixarem o campo pelo efeito de uma Armadilha Normal sua, enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Estufi Cascoruga Labrinto" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Invocar este card por Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74029853,'Espada Bambu Dourada','Se você controlar uma Magia de Equipamento "Espada Bambu": compre 2 cards.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74055055,'Petróleo',replace(replace('Escolha até 2 monstros de FOGO de Nível 4 ou menos com nomes diferentes no seu Cemitério; adicione-os à sua mão. \r\nVocê só pode ativar 1 "Petróleo" por turno.','\r',char(13)),'\n',char(10)),'Recuperar monstros de FOGO','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74063034,'Invokação',replace(replace('Invoque por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional, usando monstros da sua mão como matéria. \r\nSe estiver Invocando um Monstro de Fusão "Invokado(a)" desta forma, você também pode banir monstros do seu campo e/ou do Cemitério de qualquer duelista como matéria. \r\nSe este card estiver no seu Cemitério: você pode escolher 1 dos seus "Aleister, Aquele que Invoka" banidos; embaralhe este card no Deck e, se isso acontecer, adicione esse monstro à sua mão. \r\nVocê só pode usar este efeito de "Invokação" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Fusão','Recuperar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74063035,'Invokação',replace(replace('Invoque por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional, usando monstros da sua mão como matéria. \r\nSe estiver Invocando um Monstro de Fusão "Invokado(a)" desta forma, você também pode banir monstros do seu campo e/ou do Cemitério de qualquer duelista como matéria. \r\nSe este card estiver no seu Cemitério: você pode escolher 1 dos seus "Aleister, Aquele que Invoka" banidos; embaralhe este card no Deck e, se isso acontecer, adicione esse monstro à sua mão. \r\nVocê só pode usar este efeito de "Invokação" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Fusão','Recuperar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74064212,'Prisma Vylon',replace(replace('Se este card for enviado da Zona dos Cards de Monstro para o Cemitério: você pode pagar 500 Pontos de Vida e, depois, escolher 1 monstro com a face para cima que você controla; equipe este card ao alvo. \r\nSe o monstro equipado atacar ou for atacado: ele ganha 1000 de ATK apenas durante a Etapa de Dano.','\r',char(13)),'\n',char(10)),'Equipar como Card de Equipamento','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74069667,'D/D/D Abismo Ragnarok, o Rei Esquecido',replace(replace('Escala de Pêndulo = 5\r\n[ Efeito de Pêndulo ]\r\nSe você Invocar por Invocação-Especial um ou mais monstros "D/D", exceto durante a Etapa de Dano: você pode escolher 1 monstro "D/D" no seu Cemitério; qualquer dano de batalha que seu oponente sofrer é reduzido à metade pelo resto deste turno e, além disso, Invoque esse monstro por Invocação-Especial e, se isso acontecer, sofra 1000 de dano. \r\nVocê só pode usar este efeito de "D/D/D Abismo Ragnarok, o Rei Esquecido" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 monstro "D/D/D" no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê só pode usar este efeito de "D/D/D Abismo Ragnarok, o Rei Esquecido" uma vez por turno. \r\nUma vez por turno: você pode oferecer como Tributo 1 outro monstro "D/D" e, depois, escolher 1 monstro que seu oponente controla; bana-o.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74078255,'Lagrimentiara Merrli',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode enviar os 3 cards do topo do seu Deck para o Cemitério. \r\nSe este card for enviado para o Cemitério por um efeito de card (exceto durante a Etapa de Dano): você pode Invocar por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional, ao colocar as Matérias de Fusão mencionadas nele da sua mão, do campo e/ou do Cemitério, incluindo este card do seu Cemitério, no fundo do Deck em qualquer ordem. \r\nVocê só pode usar cada efeito de "Lagrimentiara Merrli" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74093656,'Guerreiro Regulador','A antena deste guerreiro pode sintonizá-lo a qualquer onda de energia. Ele pode monitorar transmissões a quilômetros de distância, mas sempre sofre de má recepção.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74094021,'Seis Samurai Lendários - Mizuho',replace(replace('Se você controlar "Seis Samurai Lendários - Shinai", você pode Invocar este card por Invocação-Especial (da sua mão). \r\nUma vez por turno: você pode oferecer como Tributo outro monstro "Seis Samurai" com a face para cima e, depois, escolher 1 card no campo; destrua o alvo.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74095602,'Mudança de Herói - Raio Refletor','Quando um Monstro de Fusão "HERÓI do Elemento" que você controla for destruído em batalha e enviado para o Cemitério: Cause dano ao seu oponente igual ao seu Nível original x 300.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74100225,'Evo-Singularidade','Escolha 1 monstro "Evoltil" e 1 monstro "Evolssauro" no seu Cemitério; Invoque por Invocação-Especial 1 Monstro Xyz "Evolzar" do seu Deck Adicional e, se isso acontecer, associe esses monstros a ele como Matérias Xyz.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74115234,'Esfera de Yasaka',replace(replace('Só pode ser equipado a um monstro Espírito. \r\nQuando ele destruir um monstro do oponente em batalha e enviá-lo para o Cemitério, ganhe PV igual ao ATK original desse monstro. \r\nQuando o monstro equipado que você controla for devolvido para a mão e este card for enviado para o Cemitério, devolva este card à sua mão.','\r',char(13)),'\n',char(10)),'Ganhar PV','Retornar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74117290,'Negócios do Mundo Negro','Cada duelista compra 1 card e, depois, cada duelista descarta 1 card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74122412,'Necroz de Gungnir',replace(replace('Você pode Invocar este card por Invocação-Ritual com qualquer Magia de Ritual "Necroz". \r\nDeve ser Invocado por Invocação-Ritual sem usar quaisquer monstros de Nível 7. \r\nVocê só pode usar cada um desses efeitos de "Necroz de Gungnir" uma vez por turno.\r\n● (Efeito Rápido): você pode descartar este card e, depois, escolha 1 monstro "Necroz" que você controla; ele não pode ser destruído em batalha ou por efeitos de card neste turno.\r\n● (Efeito Rápido): você pode descartar 1 card "Necroz" e, depois, escolha 1 card no campo; destrua-o.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74130411,'Falcão Biônico','Quando um monstro do Tipo Máquina que você controla for destruído em batalha e enviado ao Cemitério enquanto este card estiver com a face para cima no campo, você pode adicionar 1 monstro do Tipo Máquina com 1000 ou menos de ATK do seu Deck para a sua mão.','Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74131780,'Força Exilada','Você pode oferecer este card como Tributo e, depois, escolha 1 monstro no campo; destrua o alvo.','Destrua 1 monstro no campo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74137509,'Dado Gracioso',replace(replace('Lance um dado de seis faces. \r\nAté o final deste turno, todos os monstros que você controla atualmente ganham ATK/DEF igual ao resultado x 100.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74139959,'Árvore Cósmica Irmistil',replace(replace('3+ Monstros de Efeito	\r\nVocê só pode controlar 1 "Árvore Cósmica Irmistil". \r\nSempre que seu oponente Invocar um ou mais monstros por Invocação-Especial com a face para cima durante a Fase Principal, você ganha PV igual ao ATK deles. \r\nUma vez por turno (Efeito Rápido): você pode pagar PV em múltiplos de 1000 (máx. 3000); este card ganha esse valor de ATK.','\r',char(13)),'\n',char(10)),'Aumentar ATK','Escolher o valor a pagar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74148483,'Gato Selvagem Inférnico',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) ao enviar 1 outro monstro "Inférnico(a)" na sua mão para o Cemitério. \r\nVocê só pode Invocar "Gato Selvagem Inférnico" por Invocação-Especial uma vez por turno desta forma. \r\nEnquanto você não tiver cards na sua mão: você pode banir 1 monstro "Inférnico(a)" do seu Cemitério; até o final deste turno, aumente ou diminua em 1 o Nível deste card. \r\nVocê só pode usar este efeito de "Gato Selvagem Inférnico" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Aumentar o Nível','Reduzir o Nível','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74150658,'Garras de Shurilane',replace(replace('Se este card batalhar um monstro, nenhum dos dois pode ser destruído nessa batalha. \r\nVocê só pode usar cada um dos seguintes efeitos de "Garras de Shurilane" uma vez por turno. \r\nDurante o turno do seu oponente (Efeito Rápido): você pode escolher 1 monstro Demônio ou Ilusão que você controla, exceto "Garras de Shurilane"; devolva-o para a mão e, se isso acontecer, Invoque este card por Invocação-Especial da sua mão. \r\nQuando seu oponente ativar um card ou efeito que escolha como alvo um ou mais dos seus cards (Efeito Rápido): você pode escolher 1 monstro que seu oponente controla; devolva este card do campo para a mão e, se isso acontecer, destrua esse monstro.','\r',char(13)),'\n',char(10)),'Invocação Especial','Destruir um monstro do oponente','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74153887,'Escorpião das Trevas - Meanae o Espinho',replace(replace('Quando este card causar dano de batalha ao seu oponente, você pode ativar 1 desses efeitos:\r\n● Adicione 1 card "Escorpião das Trevas" do seu Deck à sua mão.\r\n● Escolha 1 card "Escorpião das Trevas" no seu Cemitério; adicione o alvo à sua mão.','\r',char(13)),'\n',char(10)),'Ativar 1 efeito','Procurar no Deck','Recuperar do Cemitério','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74157028,'Dragão Gêmeo Cibernético',replace(replace('"Dragão Cibernético" + "Dragão Cibernético"	\r\nA Invocação-Fusão deste card só pode ser feita com as Matérias de Fusão acima. \r\nEste card pode realizar um segundo ataque durante cada Fase de Batalha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74163487,'Guarda do Ponto de Restauração',replace(replace('2 monstros Ciberso	\r\nUma vez por turno, se outro Monstro Link for Invocado por Invocação-Link: pelo resto deste turno, este card não pode ser destruído em batalha ou por efeitos de card. \r\nSe um Monstro Link, que foi Invocado por Invocação-Link usando este card como matéria, for destruído por um efeito de card do oponente, enquanto este card estiver no Cemitério (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial. \r\nVocê só pode usar este efeito de "Guarda do Ponto de Restauração" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74168099,'Irmandade do Punho de Fogo - Príncipe Cavalo',replace(replace('1 Regulador de FOGO + 1+ monstros não-Reguladores	\r\nQuando este card for Invocado por Invocação-Sincro: você pode Invocar por Invocação-Especial 1 monstro de FOGO de Nível 3 do seu Deck. \r\nDepois de Invocar este card por Invocação-Sincro, pelo resto do turno, você não pode Invocar monstros de Nível 5 ou mais por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74169516,'Golem que Guarda os Tesouros do Milênio',replace(replace('A ativação de um "Ankh do Milênio" seu não pode ser negada. \r\nVocê só pode usar cada um dos seguintes efeitos de "Golem que Guarda os Tesouros do Milênio" uma vez por turno. \r\nSe este card estiver na sua mão: você pode colocá-lo na sua Zona de Magias & Armadilhas como uma Magia Contínua com a face para cima. \r\nEnquanto este card for uma Magia Contínua: você pode pagar 2000 PV ou revelar 1 "Ankh do Milênio" na sua mão; Invoque este card por Invocação-Especial e, depois, você pode adicionar 1 "Templo de Wedju" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Colocá-la como Card de Magia','Invocação Especial','Revelar "Ankh do Milênio"?','Adicionar "Templo de Wedju" à sua mão?','','','','','','','','','','','','');
INSERT INTO texts VALUES(74191528,'Card do Destino',replace(replace('Cada duelista seleciona 1 card do seu próprio Deck e, depois, cada duelista o combina com 4 cards aleatórios adicionais selecionados do seu Deck pelo seu oponente e, depois, aleatoriamente seleciona 1 desses 5 cards para revelar e adicionar à sua mão. \r\nEmbaralhe o resto de volta nos Decks. \r\nVocê só pode ativar 1 "Card do Destino" por turno.','\r',char(13)),'\n',char(10)),'Escolha 1 card que você controla','Escolha aleatoriamente 4 cards do seu oponente','Escolha aleatoriamente um card para adicionar à mão do oponente','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74191942,'Escolha Dolorosa',replace(replace('Selecione 5 cards do seu Deck e mostre-os ao seu oponente. \r\nSeu oponente seleciona 1 card dentre eles. \r\nAdicione esse card à sua mão e descarte os cards restantes para o Cemitério.','\r',char(13)),'\n',char(10)),'Escolha 5 cards','Escolha um card para adicionar à mão do oponente','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74202664,'Um ou Oito',replace(replace('Se você tiver menos PV que seu oponente: revele o card do topo do seu Deck e, se for de Nível 1 ou 8, adicione-o à sua mão ou Invoque-o por Invocação-Especial. \r\nCaso contrário, seu oponente pode aplicar 1 desses efeitos.\r\n● Os PV do duelista que ativou este card se tornam 1000.\r\n● O oponente do duelista que ativou este card ganha PV até que eles se tornem 8000.	\r\nVocê só pode ativar 1 "Um ou Oito" por turno.','\r',char(13)),'\n',char(10)),'Os PV do controlador de "Um ou Oito" tornam-se 1000','Os PV do oponente do controlador de "Um ou Oito" tornam-se 8000','Não fazer nada','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74203495,'PSÍ-Armação Equipamento Delta',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial por um efeito de card. \r\nUma vez por Corrente, quando seu oponente ativar um Card de Magia enquanto você não controlar nenhum monstro (Efeito Rápido): você pode Invocar por Invocação-Especial tanto este card da sua mão quanto 1 "PSÍ-Armação Condutor" da sua mão, do Deck ou do Cemitério e, se isso acontecer, negue a ativação e, se isso acontecer, destrua essa Magia. \r\nDurante a Fase Final, bana os monstros com a face para cima Invocados por Invocação-Especial por este efeito.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74210057,'Textranformar','Uma vez por turno, quando um monstro seu for escolhido como alvo de um ataque: você pode negar esse ataque e, depois, Invocar por Invocação-Especial 1 Monstro Normal Ciberso da sua mão, do Deck ou do Cemitério.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74213995,'Ecos do Guarda de Batalha',replace(replace('Quando este card for ativado: você pode adicionar 1 monstro Guerreiro de TERRA de Nível 5 do seu Deck à sua mão e, depois, descarte 1 card. \r\nUma vez por turno, se um ou mais monstros forem devolvidos do campo para a mão, mesmo durante a Etapa de Dano: você pode ativar 1 desses efeitos;\r\n● Adicione 1 "Fúria do Guarda de Batalha" ou "Uivo do Guarda de Batalha" do seu Deck à sua mão.\r\n● Coloque 1 monstro com a face para cima no campo, com a face para baixo em Posição de Defesa.	\r\nVocê só pode ativar 1 "Ecos do Guarda de Batalha" por turno.','\r',char(13)),'\n',char(10)),'Ativar','Adicionar à mão ou colocar o monstro com a face para baixo','Adicionar à sua mão 1 monstro Guerreiro TERRA de Nível 5 do seu Deck?','Adicione à sua mão 1 "Fúria do Guarda de Batalha" ou "Uivo do Guarda de Batalha" do seu Deck','Mude 1 monstro com a face para cima no campo para Posição de Defesa com a face para baixo','','','','','','','','','','','');
INSERT INTO texts VALUES(74218258,'Tela do Clima Arco-íris',replace(replace('Você só pode controlar 1 "Tela do Clima Arco-íris". \r\nMonstros de Efeito "do Clima" nas suas Zonas de Monstros Principais da coluna deste card e das colunas adjacentes a ela ganham este efeito.\r\n● Se seu oponente controlar um monstro (Efeito Rápido): você pode banir este card; Invoque por Invocação-Especial 1 monstro "do Clima" com um nome diferente do seu Deck e, além disso, você não pode Invocar outros monstros por Invocação-Especial do Deck pelo resto deste turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial do Deck (Tela do Clima Arco-íris)','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74270067,'Círculo de Encantamentos de Pikeru','Você não sofre dano de efeito até o final deste turno.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74271714,'Peixe e Ofertas',replace(replace('No começo da sua Fase Principal 1: bana 1 card da sua mão; seu oponente pode banir 2 cards da mão dele e, se ele não o fizer, você aplica este efeito.\r\n● Pegue 2 monstros Peixe do seu Deck e bana os dois ou envie os dois para o Cemitério e, além disso, você não pode Invocar por Invocação-Especial pelo resto deste turno, exceto monstros Peixe.','\r',char(13)),'\n',char(10)),'Ativar','Banir 1 card da sua mão?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74277583,'Talhador Corajoso','Armado com diversas tesouras, este monstro pode talhar um inimigo em qualquer forma e tamanho.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74289646,'Rino Real do Dado Enganador',replace(replace('Uma vez por turno, quando um card ou efeito for ativado, mesmo durante a Etapa de Dano (Efeito Rápido): você pode lançar um dado de seis faces e, depois, aplique o efeito apropriado, dependendo do número do Elo de Corrente deste efeito.\r\n● 2: Este card ganha ATK igual ao resultado x 500 até o final deste turno.\r\n● 3: Cause dano ao seu oponente igual ao resultado x 500.\r\n● 4+: Destrua cards no campo até o resultado.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74294676,'Evolzar Laggia',replace(replace('2 monstros Dinossauro de Nível 4	\r\nQuando um ou mais monstros seriam Invocados por Invocação-Normal ou Especial, OU um Card de Magia/Armadilha for ativado (Efeito Rápido): você pode desassociar 2 matérias deste card; negue a Invocação ou ativação e, se isso acontecer, destrua-o.','\r',char(13)),'\n',char(10)),'Negue a ativação de um Card de Magia/Armadilha e destrua-o','Negar a Invocação e destruir','Negar a Invocação Especial e destruir','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74294677,'Evolzar Laggia',replace(replace('2 monstros Dinossauro de Nível 4	\r\nQuando um ou mais monstros seriam Invocados por Invocação-Normal ou Especial, OU um Card de Magia/Armadilha for ativado (Efeito Rápido): você pode desassociar 2 matérias deste card; negue a Invocação ou ativação e, se isso acontecer, destrua-o.','\r',char(13)),'\n',char(10)),'Negue a ativação de um Card de Magia/Armadilha e destrua-o','Negar a Invocação e destruir','Negar a Invocação Especial e destruir','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74298287,'Sirena Abisdina',replace(replace('Quando este card for adicionado do seu Deck ou Cemitério à sua mão devido a um efeito de card: você pode Invocar este card da sua mão por Invocação-Especial. \r\nVocê deve controlar um monstro "Sirena" para ativar e resolver este efeito. \r\nQuando este card for Invocado por Invocação-Especial pelo efeito de um monstro "Sirena": você pode escolher 1 monstro "Sirena" de Nível 3 ou menos em seu Cemitério; Invoque o alvo por Invocação-Especial. \r\nVocê só pode usar 1 efeito de "Sirena Abisdina" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74311226,'Soldados de Cavalaria Atlante',replace(replace('Todos os seus monstros Serpente Marinha de Nível 3 ou menos podem atacar diretamente. \r\nSe este card for enviado para o Cemitério para ativar o efeito de um monstro de ÁGUA: adicione 1 monstro Serpente Marinha do seu Deck à sua mão, exceto "Soldados de Cavalaria Atlante".','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74329404,'Formação-D',replace(replace('Cada vez que um ou mais monstros "HERÓI do Destino" com a face para cima que você controla forem destruídos, coloque 1 Marcador D neste card para cada um desses monstros. \r\nQuando você Invocar um monstro por Invocação-Normal ou Especial durante sua Fase Principal: Você pode enviar este card com 2 ou mais Marcadores D para o Cemitério; adicione até 2 cards do seu Deck e/ou Cemitério à sua mão, com o mesmo nome que esse monstro.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74335036,'Substituir Fusão',replace(replace('(Este card deve ser sempre considerado como "Polimerização".)	\r\nInvoque por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional, usando monstros que você controla como Matéria de Fusão. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 Monstro de Fusão no seu Cemitério; devolva-o para o Deck Adicional e, depois, compre 1 card.','\r',char(13)),'\n',char(10)),'Invocação Fusão','Retornar ao Deck Adicional','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74364659,'Eria, a Encantadora da Água','VIRE: Escolha 1 monstro de ÁGUA que seu oponente controla; tome o controle desse monstro enquanto este card estiver com a face para cima no campo.','Ganhe o controle de 1 monstro de ÁGUA que seu oponente controla','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74364660,'Eria, a Encantadora da Água','VIRE: Escolha 1 monstro de ÁGUA que seu oponente controla; tome o controle desse monstro enquanto este card estiver com a face para cima no campo.','Ganhe o controle de 1 monstro de ÁGUA que seu oponente controla','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74364661,'Eria, a Encantadora da Água','VIRE: Escolha 1 monstro de ÁGUA que seu oponente controla; tome o controle desse monstro enquanto este card estiver com a face para cima no campo.','Ganhe o controle de 1 monstro de ÁGUA que seu oponente controla','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74367458,'Guardião Elma',replace(replace('Este card pode ser Invocado, por Invocação-Normal, Invocação-Virar, ou Invocação-Especial apenas quando "Punhal Borboleta - Elma" estiver no seu Campo. \r\nQuando este card é Invocado, por Invocação-Normal, ou Invocação-Especial, com sucesso, você pode equipar 1 Card de Magia de Equipamento apropriado do seu Cemitério a este card.','\r',char(13)),'\n',char(10)),'Equipar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74371660,'Sirena Abisgaios',replace(replace('2 monstros de ÁGUA de Nível 7	\r\nEnquanto este card tiver matéria, monstros de Nível 5 ou mais não podem atacar. \r\nUma vez por turno (Efeito Rápido): você pode desassociar 1 matéria deste card; até o final deste turno, negue os efeitos de todos os monstros com a face para cima que seu oponente controla atualmente com ATK menor que o deste card.','\r',char(13)),'\n',char(10)),'Negar o efeito','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74378580,'Laboratório GMX nº 5',replace(replace('Seu oponente não pode ativar cards ou efeitos quando você Invocar um ou mais monstros "GMX" por Invocação-Normal ou Especial. \r\nDurante sua Fase Principal: você pode Baixar 1 Magia/Armadilha "GMX" do seu Deck, exceto "Laboratório GMX nº 5" e, depois, coloque 1 card da sua mão no topo do Deck. \r\nVocê só pode usar este efeito de "Laboratório GMX nº 5" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Baixar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74387963,'D/D Pesquisador Adicional',replace(replace('Escala de Pêndulo = 4\r\n[ Efeito de Pêndulo ]\r\nSe um ou mais Cards de Monstro com a face para cima que seu oponente controla forem destruídos em batalha ou por um efeito de card: você pode escolher 1 monstro "D/D/D" que você controla; bana 2 cards das suas Zonas de Pêndulo e, se isso acontecer, esse monstro pode realizar um segundo ataque durante cada Fase de Batalha neste turno. \r\nVocê só pode usar este efeito de "D/D Pesquisador Adicional" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nVocê pode descartar este card; adicione 1 Monstro Pêndulo "D/D" com a face para cima do seu Deck Adicional à sua mão, exceto "D/D Pesquisador Adicional". \r\nSe este card for banido: você pode banir os cards do topo do Deck do seu oponente igual ao número de Monstros Pêndulo com a face para cima no Deck Adicional dele e, depois, você pode fazer com que 1 monstro "D/D" que você controla ganhe 200 de ATK para cada card banido. \r\nVocê só pode usar cada efeito de "D/D Pesquisador Adicional" uma vez por turno.','\r',char(13)),'\n',char(10)),'Atacar duas vezes','Adicione à sua mão um Monstro Pêndulo','Banir','Aumentar o ATK dos monstros "D/D"?','','','','','','','','','','','','');
INSERT INTO texts VALUES(74388798,'Espadachim Silencioso LV5',replace(replace('Não é afetado pelos efeitos de Magia do seu oponente. \r\nDurante sua próxima Fase de Apoio depois que este card causar dano de batalha ao seu oponente em um ataque direto: você pode enviar este card com a face para cima para o Cemitério; Invoque por Invocação-Especial 1 "Espadachim Silencioso LV7" da sua mão ou Deck.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74393852,'Javalarco Zoodíaco',replace(replace('5 monstros de Nível 4	\r\nUma vez por turno, você também pode Invocar "Javalarco Zoodíaco" por Invocação-Xyz ao usar 1 monstro "Zoodíaco(a)" que você controla com um nome diferente como matéria. \r\n(Transfira as matérias dele para este card.) \r\nGanha ATK/DEF igual ao ATK/DEF de todos os monstros "Zoodíaco(a)" associados a ele como matéria. \r\nEste card pode atacar diretamente. \r\nQuando este card causar dano de batalha ao seu oponente enquanto tiver 12 ou mais matérias: você pode enviar tantos cards quanto possível da mão e do campo do seu oponente para o Cemitério e, depois, coloque este card em Posição de Defesa.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Xyz sobrepondo um monstro "Zoodíaco(a)"?','Envie para o Cemitério todos os cards que seu oponente controla','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74402414,'Crônica da Magia',replace(replace('Ative este card ao enviar toda a sua mão para o Cemitério; bana 5 Magias/Armadilhas do seu Deck. \r\nSempre que seu oponente ativar um Card de Magia, coloque 1 Marcador de Crônica neste card quando esse Card de Magia resolver. \r\nVocê pode remover 2 Marcadores de Crônica deste card; seu oponente seleciona 1 card banido pelo efeito deste card para que você adicione à sua mão. \r\nSe este card com a face para cima na Zona de Magias & Armadilhas deixar o campo, você sofre 500 de dano para cada card atualmente banido pelo efeito deste card.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74405783,'Os Três Campeões de Espadalmas',replace(replace('1 Regulador de Nível 4 + 1+ não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro: você pode adicionar 1 monstro Mago de Nível 4 ou 8 cujo ATK seja igual à sua própria DEF do seu Deck ou Cemitério à sua mão. \r\nVocê pode escolher 1 card com a face para cima no campo; negue seus efeitos e, depois, se um monstro "Ecclesia" ou "Caído de Arbaz" estiver no seu Cemitério, você pode destruir esse card. \r\nVocê só pode usar cada efeito de "Os Três Campeões de Espadalmas" uma vez por turno.','\r',char(13)),'\n',char(10)),'Efeito de busca','Negar o efeito','Destruir?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74414885,'NEXT',replace(replace('Invoque por Invocação-Especial qualquer número de monstros com nomes diferentes da sua mão e/ou do Cemitério, em Posição de Defesa, que sejam todos "Neos, o HERÓI do Elemento" ou monstros "Neoespacial", mas negue seus efeitos e, enquanto você controlar qualquer um desses monstros Invocados por Invocação-Especial com a face para cima, você não pode Invocar monstros do Deck Adicional por Invocação-Especial, exceto Monstros de Fusão. \r\nVocê só pode ativar 1 "NEXT" por turno. \r\nSe você não controlar nenhum card, você pode ativar este card da sua mão.','\r',char(13)),'\n',char(10)),'Continuar selecionando?','Ativar aplicando o efeito de "NEXT".','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74416026,'Marcha Peladura',replace(replace('Quando um Card de Magia/Armadilha ou efeito de monstro do oponente for ativado que escolha como alvo um ou mais monstros "Peladura" que você controla: negue a ativação e, se isso acontecer, destrua esse card e, depois, você pode enviar 1 dos monstros "Peladura" escolhidos como alvo para o Cemitério e, se isso acontecer, Invoque por Invocação-Especial 1 Monstro de Fusão "Peladura" de Nível 8 ou mais do seu Deck Adicional. \r\n(Esta Invocação-Especial é considerada como uma Invocação-Fusão.) \r\nDurante sua próxima Fase Final, bana o monstro Invocado por Invocação-Especial por este efeito.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74416224,'Lanceiro do Raio Negro',replace(replace('2 monstros de ÁGUA de Nível 3	\r\nUma vez por turno: você pode desassociar 1 Matéria Xyz deste card para escolher 1 monstro com a face para cima no campo; negue o efeito do alvo até a Fase Final.','\r',char(13)),'\n',char(10)),'Negar efeitos','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74426895,'Despertar dos Possuídos - Gagigobyte',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão ou do Deck) ao enviar para o Cemitério 1 monstro Mago com a face para cima que você controla e 1 monstro de ÁGUA de Nível 4 ou menos com a face para cima que você controla. \r\nVocê só pode usar cada um dos seguintes efeitos de "Despertar dos Possuídos - Gagigobyte" uma vez por turno. \r\nQuando este card for Invocado por Invocação-Especial por seu efeito: você pode enviar 1 card aleatório da mão do seu oponente para o Cemitério e, depois, cada duelista compra 1 card. \r\nSe este card for enviado do campo para o Cemitério: você pode adicionar 1 card "Arte Espiritual da Água" ou 1 Magia/Armadilha "Possuído(a)" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74431740,'Reinicialização de Ataque',replace(replace('Ofereça como Tributo 1 monstro "/Modo de Ataque"; Invoque por Invocação-Especial 1 monstro "/Modo de Ataque" do seu Deck com um nome diferente em Posição de Defesa, ignorando suas condições de Invocação. \r\nVocê pode banir este card do seu Cemitério e, depois, escolher qualquer número de cards no seu Cemitério, com nomes diferentes, que sejam "Ativar Modo de Ataque" e/ou listem especificamente "Ativar Modo de Ataque" em seus textos, exceto "Reinicialização de Ataque"; embaralhe-os no Deck. \r\nVocê só pode usar cada efeito de "Reinicialização de Ataque" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74439492,'Resplendor de Restolhos',replace(replace('Selecione 1 monstro "Restolhos" com a face para cima que você controla e destrua-o. \r\nTodos os monstros "Restolhos" com a face para cima que você controla ganham 1000 de ATK até a Fase Final.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74440055,'Cacto Lutador','Se este card destruir um monstro do oponente em batalha, Invoque por Invocação-Especial 1 "Ficha de Agulha" (Tipo Planta/TERRA/Nível 1/ATK 500/DEF 500) no lado do campo do seu oponente em Posição de Defesa.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74440056,'Ficha de Agulha','Invocado por Especial com o efeito "Cacto Lutador".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74458486,'Cobertura de Fogo','Durante a Etapa de Dano, se um monstro do oponente atacar um monstro seu: escolha 1 outro monstro com a face para cima que você controla; seu monstro que foi atacado ganha ATK igual ao ATK do alvo, apenas durante a Etapa de Dano.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74506079,'Lombriga Zero',replace(replace('2 ou mais monstros "Lombriga" do Tipo Réptil	\r\nPara cada Monstro-Matéria de Fusão com um nome diferente usado para a Invocação-Fusão deste card, ele ganha 500 de ATK e também ganha esses efeitos:\r\n● 2+: Uma vez por turno, você pode selecionar 1 monstro do Tipo Réptil no seu Cemitério e Invocá-lo por Invocação-Especial com a face para baixo em Posição de Defesa.\r\n● 4+: Você pode remover de jogo 1 monstro do Tipo Réptil do seu Cemitério para enviar 1 monstro no campo para o Cemitério.\r\n● 6+: Uma vez por turno, você pode comprar 1 card.','\r',char(13)),'\n',char(10)),'Invoque por Invocação Especial 1 monstro Réptil do seu Cemitério','Enviar 1 monstro no campo para o Cemitério','Compre 1 card(s)','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74509280,'Mecanismo do Paralelo Pernicioso','Quando usar este card como Matéria Sincro, a outra Matéria Sincro deve ser 1 monstro "Pernicioso(a)" na sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74519184,'Destruição da Mão','Cada duelista envia 2 cards da sua mão para o Cemitério e, depois, compra 2 cards.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74530899,'Metaion, o Senhor do Tempo',replace(replace('Não pode ser Invocado por Invocação-Especial do Deck. \r\nSe você não controlar nenhum monstro, você pode Invocar este card por Invocação-Normal sem oferecer Tributo. \r\nNão pode ser destruído em batalha ou por efeitos de card. \r\nVocê não sofre dano de batalha dos ataques envolvendo este card em Posição de Ataque. \r\nNo final da Fase de Batalha, se este card batalhou: devolva para a mão tantos monstros no campo quanto possível (exceto este card) e, se isso acontecer, cause 300 de dano ao seu oponente para cada card devolvido. \r\nUma vez por turno, durante sua Fase de Apoio: embaralhe este card no Deck.','\r',char(13)),'\n',char(10)),'Invocação Normal sem Tributo','Retornar à mão todos os outros monstros','Retornar este card ao Deck','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74567889,'Infante Negro @Ignister',replace(replace('1 monstro "@Ignister" que não seja Link	\r\nSe este card for Invocado por Invocação-Link: você pode adicionar 1 "I.A.Terra Ignister" do seu Deck à sua mão. \r\nQuando um monstro Ciberso com 2300 de ATK original ativar seu efeito (Efeito Rápido): você pode mover este card para uma Zona de Monstros Principal sua para a qual este card apontar e, depois, você pode torná-lo de qualquer Atributo até o final deste turno. \r\nVocê só pode usar cada efeito de "Infante Negro @Ignister" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Alterar o Atributo deste card?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74576482,'Pantera Marinha de Koa''ki Meiru',replace(replace('Durante cada uma das suas Fases Finais, destrua este card a não ser que você envie 1 "Núcleo de Ferro de Koa''ki Meiru" da sua mão ao Cemitério ou revele 1 monstro de ÁGUA na sua mão. \r\nUma vez por turno, você pode enviar 1 "Núcleo de Ferro de Koa''ki Meiru" da sua mão ao Cemitério para devolver 1 Card de Magia do seu Cemitério para o topo do seu Deck.','\r',char(13)),'\n',char(10)),'Escolha 1 "Núcleo de Ferro de Koa''ki Meiru" para enviar para o Cemitério','Revele ao oponente 1 monstro de ÁGUA','Destruir "Pantera Marinha de Koa''ki Meiru"','Retornar ao Deck','','','','','','','','','','','','');
INSERT INTO texts VALUES(74577599,'Armadilhatrix Buracotea',replace(replace('Você pode ativar este card no turno em que foi Baixado ao descartar 1 Armadilha Normal. \r\nInvoque este card por Invocação-Especial em Posição de Defesa como um Monstro Normal (Planta/TERRA/Nível 4/ATK 400/DEF 2400).	\r\n(Este card NÃO é considerado como uma Armadilha.) \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 monstro "Armadilhatrix" no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê só pode usar 1 efeito de "Armadilhatrix Buracotea" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Ativar aplicando o efeito de "Armadilhatrix Buracotea".','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74578720,'Ladrão do Tempo Cronogravador',replace(replace('Durante a Fase de Batalha do seu oponente (Efeito Rápido): você pode oferecer este card como Tributo; o próximo dano de batalha que você sofrer do ataque de um monstro do oponente neste turno, em vez disso, é causado ao seu oponente. \r\nSe um Monstro Xyz com a face para cima que você controla deixar o campo devido a um efeito de card, enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar cada efeito de "Ladrão do Tempo Cronogravador" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74580251,'Providência Zefra',replace(replace('Adicione 1 card "Zefra" do seu Deck à sua mão, exceto "Providência Zefra". \r\nSe um ou mais cards "Zefra" que você controla seriam destruídos, exceto no turno em que este card foi enviado para o Cemitério, em vez disso, você pode banir este card do seu Cemitério. \r\nVocê só pode ativar 1 "Providência Zefra" por turno.','\r',char(13)),'\n',char(10)),'Usar o efeito de "Providência Zefra" em vez de ser destruído?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74582050,'Erupção Dinonévoa','Se um ou mais monstros "Dinonévoa" que você controla forem destruídos em batalha ou por um efeito de card: escolha 1 card que seu oponente controla; destrua-o.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74583607,'D/D/D Gêngis, o Rei das Chamas',replace(replace('2 monstros "D/D"	\r\nSe um ou mais outros monstros "D/D" forem Invocados por Invocação-Especial no seu campo, enquanto você controlar este monstro (exceto durante a Etapa de Dano): você pode escolher 1 monstro "D/D" no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê só pode usar este efeito de "D/D/D Gêngis, o Rei das Chamas" uma vez por turno. \r\nSe este card for destruído em batalha ou se este card em posse do seu dono for destruído por um efeito de card do oponente: você pode escolher 1 card "Pacto Obscuro" no seu Cemitério; adicione-o à sua mão.','\r',char(13)),'\n',char(10)),'Invocação Especial','Recuperar cards','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74586817,'PSÍ-Armação Senhor Omega',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nUma vez por turno, durante a Fase Principal (Efeito Rápido): você pode banir tanto este card com a face para cima do campo quanto 1 card aleatório da mão do seu oponente, com a face para cima, até sua próxima Fase de Apoio. \r\nUma vez por turno, durante a Fase de Apoio do seu oponente: você pode escolher 1 card banido; devolva-o para o Cemitério. \r\nSe este card estiver no seu Cemitério: você pode escolher 1 outro card no Cemitério; embaralhe tanto esse card quanto este card do Cemitério no Deck.','\r',char(13)),'\n',char(10)),'Banir a mão do oponente e este card','Retornar o card banido para o Cemitério','Escolha o card a ser devolvido ao Cemitério','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74591968,'Homem das Espadas Místicas LV4',replace(replace('Se você Invocar este monstro por Invocação-Normal, você tem de colocá-lo em Posição de Defesa com a face para baixo. \r\nSe este card atacar um monstro em Posição de Defesa com a face para baixo, destrúa o monstro com o efeito deste card, sem aplicar o cálculo de dano. \r\nDurante a End Phase do turno em que este card destrúa um monstro como resultado de um combate, envie este card para o Cemitério para Invocar, por Invocação-Especial, "Homem das Espadas Místicas LV6" da sua mão ou do seu Deck.','\r',char(13)),'\n',char(10)),'Destruir','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74593218,'Campeão Heroico- Kusanagi',replace(replace('3 monstros de Nível 4 do Tipo Guerreiro	\r\nUma vez por turno, durante o turno de qualquer duelista, quando um Card de Armadilha for ativado: você pode desassociar 1 Matéria Xyz deste card; negue a ativação e, se isso acontecer, destrua-o e, depois, este card ganha 500 de ATK.','\r',char(13)),'\n',char(10)),'Negar a ativação de uma Armadilha e destruí-la','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74605254,'D/D Galilei, o Erudito',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nVocê não pode Invocar monstros por Invocação-Pêndulo, exceto monstros "D/D". \r\nEste efeito não pode ser negado. \r\nUma vez por turno, durante sua Fase de Apoio: aumente a Escala de Pêndulo deste card em 2 (máx. 10) e, depois, destrua todos os monstros que você controla com um Nível menor ou igual à Escala de Pêndulo deste card, exceto monstros "D/D".\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nDurante o turno de qualquer duelista: você pode descartar este card e, depois, escolher 1 card "D/D" ou "Pacto Obscuro" que você controla; devolva-o para a mão. \r\nVocê só pode usar este efeito de "D/D Galilei, o Erudito" uma vez por turno.','\r',char(13)),'\n',char(10)),'Recuperar cards','Ativar como Card de Magia','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74611888,'Reviravolta','Se houver um monstro com a face para cima no campo cujo Nível atual seja diferente do seu Nível original: Mude todos os monstros no campo para Posição de Defesa com a face para baixo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74615388,'Laevatein, Chefe Generaidor das Sombras',replace(replace('2+ monstros de Nível 9	\r\nVocê só pode controlar 1 "Laevatein, Chefe Generaidor das Sombras". \r\nMonstros que seu oponente controla perdem 1000 de ATK/DEF. \r\n(Efeito Rápido): você pode oferecer como Tributo este card Invocado por Invocação-Xyz; Invoque por Invocação-Especial 1 Monstro Xyz "Generaidor" não-Fada do seu Deck Adicional e, depois, você pode associar cards de qualquer campo e/ou Cemitérios a esse monstro Invocado por Invocação-Especial, até o número de matérias que este card tinha.','\r',char(13)),'\n',char(10)),'Invoque por Invocação Especial do Deck Adicional','Sobrepor um card como Matéria Xyz?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74627016,'T.G. Larva Tanque',replace(replace('Se este card que você controla for usado como Matéria Sincro para um monstro "T.G.", você pode considerá-lo como um não-Regulador. \r\nSe este card for enviado para o Cemitério como Matéria Sincro para um monstro "T.G.": você pode Invocar por Invocação-Especial 1 "Ficha T.G." (Máquina/TERRA/Nível 1/ATK 0/DEF 0) em Posição de Ataque. \r\nVocê só pode usar este efeito de "T.G. Larva Tanque" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74627017,'Ficha T.G.','Invocada por Invocação-Especial com o efeito "T.G. Larva Tanque".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74631897,'Non-Finito de Artmage',replace(replace('2 monstros "Artmage"	\r\nDeve ser Invocado por Invocação-Fusão, ou por Invocação-Especial (do seu Deck Adicional) ao descartar 1 Magia/Armadilha e oferecer como Tributo 1 monstro "Artmage" de Nível 7 ou mais da sua mão ou do campo. \r\nVocê só pode Invocar "Non-Finito de Artmage" por Invocação-Especial uma vez por turno desta forma, não importa o método que usar. \r\nSe este card for Invocado por Invocação-Especial: você pode Baixar 1 Magia/Armadilha "Artmage" do seu Deck. \r\nUma vez por turno do oponente (Efeito Rápido): você pode Invocar por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional, usando monstros que você controla.','\r',char(13)),'\n',char(10)),'Baixar','Invocação Fusão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74637266,'Octoberser','Essa estranha criatura, com cabeça de peixe e pernas de polvo, ataca seus inimigos arremessando lanças.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74640994,'Batalha Final Subterror',replace(replace('Ative 1 desses efeitos e, além disso, depois, Baixe este card com a face para baixo em vez de enviá-lo para o Cemitério.\r\n● Coloque 1 monstro "Subterror" Baixado no campo, com a face para cima em Posição de Ataque ou de Defesa.\r\n● Coloque 1 monstro "Subterror" que estiver com a face para cima no campo, com a face para baixo em Posição de Defesa.\r\n● Até o final deste turno, o ATK/DEF de 1 monstro "Subterror" no campo se tornam iguais ao seu ATK/DEF originais combinados.\r\n● Neste turno, os efeitos ativados de cards "Subterror" não podem ser negados.','\r',char(13)),'\n',char(10)),'Vire para cima um monstro com a face para baixo','Baixar um monstro com a face para cima','Aumentar ATK/DEF','O efeito ativado não pode ser negado','','','','','','','','','','','','');
INSERT INTO texts VALUES(74641045,'Pudincesa Magidoce',replace(replace('Ganha 800 de ATK/DEF enquanto você não tiver monstros no seu Cemitério. \r\nSe este card em sua posse for destruído por um card do oponente e enviado para o seu Cemitério: embaralhe este card no Deck. \r\nDepois do cálculo de dano, se este card batalhar um monstro do oponente: você pode escolher 1 card que seu oponente controla; destrua o alvo.','\r',char(13)),'\n',char(10)),'Retornar ao Deck','Destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74644400,'Refletor Psíquico',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 "Ativar Modo de Ataque" ou 1 card que o mencione do seu Deck à sua mão, exceto "Refletor Psíquico". \r\nVocê pode revelar 1 "Ativar Modo de Ataque" na sua mão e, depois, escolha 1 monstro no seu Cemitério que o mencione, exceto "Refletor Psíquico"; Invoque-o por Invocação-Especial e, se isso acontecer, aumente o Nível dele em até 4. \r\nVocê só pode usar cada efeito de "Refletor Psíquico" uma vez por turno.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Invoque por Invocação Especial do Cemitério','Escolha o Nível a aumentar','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74652966,'Codificar Alma',replace(replace('Se você controlar um Monstro Link: você pode Invocar este card por Invocação-Especial da sua mão. \r\nDurante sua Fase Principal: você pode ativar este efeito; uma vez neste turno, se você Invocar por Invocação-Link um Monstro Link "Salamagrande", você pode usar 1 Monstro Link "Salamagrande" que você controla com seu mesmo nome como toda a matéria. \r\nDurante a Fase Principal do seu oponente (Efeito Rápido): você pode banir este card do seu Cemitério; imediatamente depois que este efeito resolver, Invoque por Invocação-Link 1 Monstro Link Ciberso de Link-3 ou mais. \r\nVocê só pode usar cada efeito de "Codificar Alma" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Link de Reencarnação','Link Acelerado','Invocação Link pelo efeito de "Codificar Alma"','','','','','','','','','','','','');
INSERT INTO texts VALUES(74657662,'Material Vylon',replace(replace('Só pode ser equipado a um monstro "Vylon". \r\nEle ganha 600 de ATK. \r\nSe este card com a face para cima for enviado do campo ao Cemitério: Você pode adicionar 1 Card de Magia "Vylon" do seu Deck para a sua mão.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74659582,'Sleipnir, a Juba Rúnika',replace(replace('2 monstros "Rúnika(o)"	\r\nDurante sua Fase Principal ou a Fase de Batalha do seu oponente (Efeito Rápido): você pode escolher 1 monstro com a face para cima que seu oponente controla; bana tanto esse monstro quanto este card até a Fase Final. \r\nSe um ou mais cards forem adicionados do Deck Principal à mão do seu oponente (exceto durante a Etapa de Dano): você pode Invocar por Invocação-Especial 1 "Ficha Rúnika" (Fada/LUZ/Nível 4/ATK 1500/DEF 1500) em Posição de Ataque. \r\nVocê só pode usar cada efeito de "Sleipnir, a Juba Rúnika" uma vez por turno.','\r',char(13)),'\n',char(10)),'Banir 1 monstro','Invoque uma Ficha','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74659583,'Ficha Rúnika','Invocado por Especial com o efeito "Sleipnir, a Juba Rúnika".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74665150,'Decodificar Transmissor de Integração',replace(replace('2+ Monstros de Efeito	\r\nEste card ganha 500 ATK para cada outro Monstro Link no campo e nos Cemitérios quando está na Zona de Monstros Adicional, seu oponente também não pode escolher ele com efeitos. \r\n(Efeito Rápido): você pode oferecer como Tributo 1 monstro para qual esse card aponta; envie 1 monstro Ciberso do seu Deck Adicional para o Cemitério, este card também pode realizar até 2 ataques a monstros durante cada Fase de Batalha neste turno. \r\nVocê só pode usar este efeito de "Decodificar Transmissor de Integração" uma vez por turno.','\r',char(13)),'\n',char(10)),'Atacar duas vezes','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74665151,'Decodificar Transmissor de Integração',replace(replace('2+ Monstros de Efeito	\r\nEste card ganha 500 ATK para cada outro Monstro Link no campo e nos Cemitérios quando está na Zona de Monstros Adicional, seu oponente também não pode escolher ele com efeitos. \r\n(Efeito Rápido): você pode oferecer como Tributo 1 monstro para qual esse card aponta; envie 1 monstro Ciberso do seu Deck Adicional para o Cemitério, este card também pode realizar até 2 ataques a monstros durante cada Fase de Batalha neste turno. \r\nVocê só pode usar este efeito de "Decodificar Transmissor de Integração" uma vez por turno.','\r',char(13)),'\n',char(10)),'Atacar duas vezes','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74665651,'Espelho Onírico da Alegria',replace(replace('Durante a Fase Final: você pode banir este card; ative 1 "Espelho Onírico do Terror" da sua mão ou do Deck. \r\nVocê só pode usar este efeito de "Espelho Onírico da Alegria" uma vez por turno. \r\nMonstros "Espelho Onírico" que você controla não podem ser escolhidos como alvo dos efeitos de card do seu oponente, ou dos ataques dos monstros dele, exceto seu(s) monstro(s) "Espelho Onírico" com o maior Nível. \r\nEste efeito só se aplica enquanto você controlar um monstro "Espelho Onírico" de LUZ.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74677422,'Dragão Negro de Olhos Vermelhos','Um dragão feroz com um ataque letal.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74677423,'Dragão Negro de Olhos Vermelhos','Um dragão feroz com um ataque letal.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74677424,'Dragão Negro de Olhos Vermelhos','Um dragão feroz com um ataque letal.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74677425,'Dragão Negro de Olhos Vermelhos','Um dragão feroz com um ataque letal.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74677426,'Dragão Negro de Olhos Vermelhos','Um dragão feroz com um ataque letal.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74677427,'Dragão Negro de Olhos Vermelhos','Um dragão feroz com um ataque letal.','','','','','','','','','','','','','','','','');
