INSERT INTO texts VALUES(74677432,'Dragão Negro de Olhos Vermelhos','Um dragão feroz com um ataque letal.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74689476,'Rilliona, a Maravilhosa Magistus do Guarda-Roupa de Bruxas',replace(replace('2 monstros Mago de Nível 4 com Atributos diferentes	\r\nVocê pode desassociar 1 matéria deste card; Invoque por Invocação-Especial 1 monstro "Magistus" do seu Deck e, além disso, você não pode Invocar monstros por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto monstros "Magistus". \r\nEnquanto este card estiver equipado a um monstro: você pode escolher 1 Monstro de Efeito que seu oponente controla; negue seus efeitos até o final deste turno. \r\nVocê só pode usar cada efeito de "Rilliona, a Maravilhosa Magistus do Guarda-Roupa de Bruxas" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74694807,'Re-Fusão',replace(replace('Ative este card ao pagar 800 PV e, depois, escolha 1 Monstro de Fusão no seu Cemitério; Invoque-o por Invocação-Especial e equipe-o com este card. \r\nQuando este card for destruído, bana o monstro equipado.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74701381,'Cirurgia ao DNA',replace(replace('Ative este card ao declarar 1 Tipo de Monstro. \r\nTodos os monstros com a face para cima no campo se tornam desse Tipo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74703140,'Águia Punida','"Coroa de Asas Azuis" + "Niwatori"','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74711057,'Terra Firma, o HERÓI do Elemento',replace(replace('"Oceano, o HERÓI do Elemento" + "Lenhador, o HERÓI do Elemento"	\r\nDeve ser Invocado por Invocação-Fusão e não pode ser Invocado por Invocação-Especial de nenhuma outra forma. \r\nVocê pode oferecer como Tributo 1 monstro "HERÓI do Elemento" com a face para cima; este card ganha ATK igual ao ATK do monstro oferecido como Tributo até a Fase Final.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74713516,'Mímico Negro LV1',replace(replace('VIRE: Compre 1 card.\r\nUma vez por turno, durante sua Fase de Apoio: você pode enviar este card para o Cemitério; Invoque por Invocação-Especial 1 "Mímico Negro LV3" da sua mão ou do Deck.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74715061,'Parceiro Divisor',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial pelo seguinte efeito. \r\nSe o efeito de ativação de um monstro que você controla for negado (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão.\r\nQuando este card for Invocado por Invocação-Especial: você pode escolher 1 monstro Ciberso de Nível 4 ou menos no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê só pode usar este efeito de "Parceiro Divisor" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74717840,'Musgo Brilhante de Landoíse',replace(replace('Só pode ser ativado se você controlar um monstro "Naturia" com a face para cima. \r\nOs Monstros de Efeito do oponente não podem ativar seus efeitos neste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74725513,'Quebesenuefe, a Proteção de Horus',replace(replace('Se você controlar "Sarcófago do Rei", você pode Invocar este card por Invocação-Especial (do seu Cemitério). \r\nVocê só pode Invocar "Quebesenuefe, a Proteção de Horus" por Invocação-Especial uma vez por turno desta forma. \r\nSe um ou mais outros cards que você controla deixarem o campo por um efeito de card do oponente, enquanto este card estiver na sua Zona de Monstros (exceto durante a Etapa de Dano): você pode ativar este efeito; neste turno, os monstros do seu oponente não podem escolher monstros "Horus" como alvo de ataques e, além disso, seu oponente não pode escolher monstros "Horus" no campo como alvo de efeitos de card. \r\nVocê só pode usar este efeito de "Quebesenuefe, a Proteção de Horus" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74728028,'Recepção Xyz',replace(replace('Escolha 1 monstro com a face para cima que você controla e que tenha Nível; Invoque por Invocação-Especial 1 monstro da sua mão com o mesmo Nível que esse monstro. \r\nSeus efeitos são negados e, além disso, seu ATK e DEF se tornam 0.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74730899,'Célula de Combustível do Homem-Bateria',replace(replace('Se você controlar 2 ou mais monstros "Homem-Bateria" com a face para cima, você pode Invocar este card por Invocação-Especial da sua mão. \r\nUma vez por turno, você pode oferecer como Tributo 1 monstro "Homem-Bateria", exceto este card, para selecionar 1 card que o seu oponente controla e devolvê-lo à mão do dono.','\r',char(13)),'\n',char(10)),'Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74733322,'Artmage, Academia Acrópole de Artes Arcanas',replace(replace('Durante sua Fase Principal, você pode Invocar 1 "Medius, o Puro" por Invocação-Normal, em adição à sua Invocação-Normal/Baixar (padrão) (você só pode se aproveitar deste efeito uma vez por turno). \r\nVocê pode descartar 1 Magia/Armadilha e declarar 1 nome de Card de Monstro "Artmage" que não esteja entre os monstros que você controla e não tenha sido declarado para "Artmage, Academia Acrópole de Artes Arcanas" neste turno; adicione esse monstro do seu Deck à sua mão e, além disso, você não pode Invocar por Invocação-Especial pelo resto deste turno, exceto monstros "Artmage", "Medius, o Puro", ou do Deck Adicional.','\r',char(13)),'\n',char(10)),'Invocar pelo efeito de "Artmage, Academia Acrópole de Artes Arcanas"','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74741494,'Afinação de Nível','Reduza o Nível de todos os monstros com a face para cima que você controla em 1 até a Fase Final.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74752631,'Shogun Guerreiro dos Seis Samurai',replace(replace('2 monstros Guerreiro, incluindo um monstro "Seis Samurai"	\r\nSe este card for Invocado por Invocação-Link: você pode descartar 1 card; adicione 1 card do seu Deck à sua mão que tenha um efeito que coloque um ou mais Marcadores de Bushido. \r\nVocê só pode usar este efeito de "Shogun Guerreiro dos Seis Samurai" uma vez por turno. \r\nSempre que um ou mais monstros "Seis Samurai" forem Invocados por Invocação-Normal ou Especial em uma ou mais zonas para as quais este card apontar, coloque 1 Marcador de Bushido neste card. \r\nGanha 100 de ATK para cada Marcador de Bushido no seu campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74762582,'Mulher Demônio Subterror',replace(replace('Quando seu oponente ativar um card ou efeito (Efeito Rápido): você pode enviar este card da sua mão ou do campo para o Cemitério e, depois, escolha 1 monstro "Subterror" que você controla; negue a ativação e, depois, coloque o monstro alvo com a face para baixo em Posição de Defesa. \r\nVocê pode escolher 1 monstro com a face para cima que você controla; coloque-o com a face para baixo em Posição de Defesa e, se isso acontecer, Invoque por Invocação-Especial 1 monstro "Subterror" da sua mão ou do Cemitério, com a face para cima ou com a face para baixo em Posição de Defesa. \r\nVocê só pode usar cada efeito de "Mulher Demônio Subterror" uma vez por turno.','\r',char(13)),'\n',char(10)),'Negar a ativação','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74798297,'Sucesso do Estilo Shiranui',replace(replace('Invoque por Invocação-Especial 1 monstro Zumbi da sua mão, mas bana-o quando ele deixar o campo. \r\nVocê pode banir este card do seu Cemitério e, depois, escolher 1 monstro Zumbi que você controla; esse monstro Zumbi não é afetado por efeitos de card neste turno, exceto seus próprios. \r\nVocê só pode usar 1 efeito de "Sucesso do Estilo Shiranui" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74820316,'Enlilgirsu, o Mekk-Cavaleiro Orcust',replace(replace('2+ monstros, incluindo um Monstro Link "Orcust"	\r\nVocê pode escolher 1 dos seus cards "Orcust" ou "Legado Mundial" banidos; adicione-o à sua mão e, depois, você pode embaralhar 1 card da sua mão no Deck e tomar o controle de 1 monstro com a face para cima que seu oponente controla. \r\nDurante sua Fase Principal, se este card estiver no Cemitério porque foi enviado para lá da Zona de Monstros Adicional neste turno: você pode banir este card; envie 1 card no campo para o Cemitério. \r\nVocê só pode usar cada efeito de "Enlilgirsu, o Mekk-Cavaleiro Orcust" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão e assumir o controle','Enviar para o Cemitério','Tome o controle do monstro do oponente?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74822425,'El Sombraneco Shekhinaga',replace(replace('1 monstro "Sombraneco" + 1 monstro de TERRA	\r\nPrimeiro deve ser Invocado por Invocação-Fusão. \r\nQuando um monstro Invocado por Invocação-Especial ativar seu efeito enquanto você tiver um card "Sombraneco" na sua mão (Efeito Rápido): você pode negar a ativação e, se isso acontecer, destrua esse monstro e, depois, envie 1 card "Sombraneco" da sua mão para o Cemitério. \r\nVocê só pode usar este efeito de "El Sombraneco Shekhinaga" uma vez por turno. \r\nSe este card for enviado para o Cemitério: você pode escolher 1 Magia/Armadilha "Sombraneco" no seu Cemitério; adicione-a à sua mão.','\r',char(13)),'\n',char(10)),'Negar e destruir','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74823665,'Inferno',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro deve ser Invocado por Invocação-Especial (da sua mão) ao banir 1 monstro de FOGO do seu Cemitério. \r\nSe este card destruir um monstro do oponente em batalha e enviá-lo para o Cemitério: cause 1500 de dano ao seu oponente.','\r',char(13)),'\n',char(10)),'Receba 1500 pontos de dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74825788,'H - Coração Ardente','Escolha 1 monstro com a face para cima que você controla; até o final deste turno, ele ganha 500 de ATK e, se ele atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74839123,'Santuário Peladura',replace(replace('Ative este card ao descartar 1 card e enviar 2 monstros "Peladura" do seu Deck Adicional para o Cemitério. \r\nTodos os Monstros de Fusão que você controla também são considerados como monstros "Peladura". \r\nSe este card for enviado para o Cemitério: você pode escolher 1 Monstro de Fusão "Peladura" no seu Cemitério; devolva-o para o Deck Adicional.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74841885,'Flagelo dos Céus Invicil',replace(replace('Este card não pode ser Invocado por Invocação-Especial. \r\nSe você Invocar este card por Invocação-Tributo ao oferecer como Tributo 1 dos seguintes monstros, este card ganha o efeito apropriado:\r\n● Monstro de LUZ do Tipo Fada: Negue os efeitos de todos os Cards de Magia.\r\n● Monstro de TREVAS do Tipo Demônio: Negue os efeitos de todos os Cards de Armadilha.','\r',char(13)),'\n',char(10)),'Negar o efeito do Card de Magia','Negue os efeitos dos Cards de Armadilha','Negue os efeitos dos Cards de Magia e Armadilha','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74845897,'Reacender','Invoque por Invocação-Especial do seu Cemitério tantos monstros de FOGO quanto possível com DEF 200, mas bana-os durante a Fase Final deste turno.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74848038,'Reencarnação de Monstros','Descarte 1 card e, depois, escolha 1 monstro no seu Cemitério; adicione-o à sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74850403,'Estrela Pêndulografa',replace(replace('Seu oponente não pode escolher monstros do Tipo Mago que você controla como alvo de Cards ou efeitos de Magia. \r\nSe um ou mais Cards de Monstro Pêndulo "Mago" com a face para cima deixarem suas Zonas de Monstro ou Zonas de Pêndulo: adicione 1 Monstro Pêndulo "Mago" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Estrela Pêndulografa" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74852097,'Grifo Fantasma','Um monstro lendário que habita em segredo nas montanhas, lutando contra as harpias pelo terreno de caça. Um único bater de suas asas é suficiente para causar uma tempestade violenta.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74852810,'Capturar Camadas','Escolha 1 Monstro Xyz com a face para cima que seu oponente controla que tenha Matéria Xyz e 1 Monstro Xyz com a face para cima que você controla; desassocie todas as Matérias Xyz do monstro do oponente e, se isso acontecer, associe este card ao seu monstro como uma Matéria Xyz.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74854609,'Conversão Zekt',replace(replace('Quando um monstro "Inzektor" com a face para cima que você controla for alvo de um ataque: Escolha o monstro atacante; equipe o alvo do ataque no monstro atacante. \r\nTome o controle do monstro equipado, enquanto ele estiver equipado com um monstro "Inzektor" por este efeito.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74860293,'Destruidor Sucata',replace(replace('"Sucata Sincron" + 1 ou mais monstros não-Reguladores	\r\nQuando este card for Invocado por Invocação-Sincro: você pode escolher cards no campo, até o número de monstros não-Reguladores usados para a Invocação-Sincro deste card; destrua os alvos.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74875003,'Discípulo de Rá',replace(replace('Quando este card for Invocado: você pode Invocar por Invocação-Especial até 2 "Discípulo de Rá" da sua mão e/ou do Deck. \r\nNão pode ser oferecido como Tributo, exceto para a Invocação-Tributo de "Slifer, o Dragão Celeste", "Obelisco, o Atormentador" ou "O Dragão Alado de Rá". \r\nVocê não pode Invocar monstros por Invocação-Especial, exceto pelo efeito de "Discípulo de Rá".','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74879881,'Mimikuril',replace(replace('Durante sua Fase Principal: você pode escavar o card do topo do seu Deck e, se for um monstro, Invoque-o por Invocação-Especial e, se isso acontecer, coloque este card no fundo do Deck. \r\nSe não era um monstro, ou se não podia ser Invocado por Invocação-Especial, coloque-o no fundo do Deck. \r\nDurante a Fase Final, coloque o monstro Invocado por Invocação-Especial por este efeito no fundo do Deck. \r\nVocê só pode usar este efeito de "Mimikuril" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74889525,'Eldlich, o Senhor Dourado Louco',replace(replace('1 monstro "Eldlich" + 1 monstro Zumbi de Nível 5 ou mais	\r\nO nome deste card se torna "Eldlich, o Senhor Dourado" enquanto estiver no campo. \r\nNão pode ser destruído em batalha ou por efeitos de card. \r\nVocê pode oferecer como Tributo 1 monstro Zumbi e, depois, escolha 1 monstro com a face para cima que seu oponente controla; tome o controle dele, mas ele não pode atacar ou ativar seus efeitos neste turno. \r\nVocê só pode usar este efeito de "Eldlich, o Senhor Dourado Louco" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74891384,'Cristal Adamancipador - Raptita',replace(replace('Se este card for Invocado por Invocação-Especial pelo efeito de um card "Adamancipador": você pode colocar 1 monstro Rocha da sua mão ou do Cemitério no topo do Deck. \r\nSe este card estiver no seu Cemitério: você pode escolher 1 Monstro Sincro de VENTO que você controla ou no seu Cemitério; devolva-o para o Deck Adicional e, se isso acontecer, coloque este card no topo do Deck. \r\nVocê só pode usar cada efeito de "Cristal Adamancipador - Raptita" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74892653,'Guerreiro da Poeira Estelar',replace(replace('1 Monstro Sincro Regulador + 1+ Monstros Sincro não-Reguladores	\r\nSe seu oponente Invocaria um ou mais monstros por Invocação-Especial (Efeito Rápido): você pode oferecer este card como Tributo; negue a Invocação e, se isso acontecer, destrua esse(s) monstro(s). \r\nDurante a Fase Final, se este efeito foi ativado neste turno (e não foi negado): você pode Invocar este card por Invocação-Especial do seu Cemitério. \r\nSe este card for destruído em batalha ou se este card com a face para cima que você controla deixar o campo devido a um efeito de card do oponente: você pode Invocar por Invocação-Especial 1 Monstro Sincro "Guerreiro(a)" de Nível 8 ou menos do seu Deck Adicional (isso é considerado uma Invocação-Sincro).','\r',char(13)),'\n',char(10)),'Negue a Invocação Especial','Ressuscitar','Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74906081,'Olhar Surpreendente do Olho de Cobra',replace(replace('Se a soma dos Níveis dos monstros "Olho de Cobra" que você controla for 2 ou mais: ative 1 desses efeitos;\r\n● Escolha 1 monstro com a face para cima que seu oponente controla ou no Cemitério dele; coloque-o com a face para cima na Zona de Magias & Armadilhas do seu dono como uma Magia Contínua.\r\n● Escolha 1 Card de Monstro considerado como uma Magia Contínua no campo; Invoque-o por Invocação-Especial no seu campo.	\r\nVocê só pode ativar 1 "Olhar Surpreendente do Olho de Cobra" por turno.','\r',char(13)),'\n',char(10)),'','Colocar um monstro','Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74920585,'Lagrimentiara Guinchacular',replace(replace('Se você controlar um monstro "Lagrimentiara" ou "Visas Starfrost": você pode escolher 1 Monstro de Efeito que seu oponente controla; negue seus efeitos e, depois, envie 1 monstro que você controla para o Cemitério. \r\nSe este card for enviado para o Cemitério por um efeito de card: você pode adicionar 1 monstro "Lagrimentiara" do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "Lagrimentiara Guinchacular" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74923978,'Requisição Forçada',replace(replace('Você pode ativar este card quando descartar um card da sua mão. \r\nDepois disso, sempre que você descartar da sua mão, seu oponente também deve descartar o mesmo número de cards da mão dele.','\r',char(13)),'\n',char(10)),'Descartar da mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74926274,'Pêndulo Crescente',replace(replace('Envie 1 monstro que você controla para o Cemitério; Invoque por Invocação-Especial do seu Deck, 1 Monstro Pêndulo com o mesmo Nível que o Nível original do monstro enviado, mas destrua-o durante a Fase Final. \r\nVocê só pode ativar 1 "Pêndulo Crescente" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74936480,'Dinomorfia Stealthbergia',replace(replace('2 monstros "Dinomorfia" com nomes diferentes	\r\nEnquanto seus PV forem 2000 ou menos, você não paga PV para ativar Cards de Armadilha ou os efeitos de monstros "Dinomorfia". \r\nVocê só pode usar cada um dos seguintes efeitos de "Dinomorfia Stealthbergia" uma vez por turno. \r\nQuando seu oponente ativar um efeito de monstro (Efeito Rápido): você pode causar dano ao seu oponente igual ao ATK original desse monstro. \r\nSe este card for destruído em batalha ou por um efeito de card: você pode Invocar por Invocação-Especial 1 monstro "Dinomorfia" de Nível 4 ou menos do seu Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74937659,'Behemoth Subterror Demônia',replace(replace('2 monstros Virar	\r\nGanha ATK igual aos Níveis originais combinados dos monstros "Subterror" usados para sua Invocação-Link x 100. \r\nDurante sua Fase Principal: você pode enviar 1 monstro Virar do seu Deck para o Cemitério e, se isso acontecer, Invoque por Invocação-Especial 1 monstro da sua mão, com a face para baixo em Posição de Defesa, em uma zona sua para a qual este card apontar. \r\nVocê só pode usar este efeito de "Behemoth Subterror Demônia" uma vez por turno. \r\nUma vez por turno, se um monstro para o qual este card apontar for virado com a face para cima: adicione 1 monstro Virar do seu Deck ou do Cemitério à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74941992,'Mago Lunar',replace(replace('Se seu oponente controlar um Monstro Xyz, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Mago Lunar" por Invocação-Especial uma vez por turno desta forma. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 monstro de LUZ de Nível 4 no seu Cemitério, exceto "Mago Lunar"; Invoque-o por Invocação-Especial, mas negue seus efeitos. \r\nVocê só pode usar este efeito de "Mago Lunar" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74952447,'Testudo erat Numen','Nenhum duelista pode Invocar por Invocação-Especial monstros com 1800 ou mais de ATK.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74968065,'Hecatrice','Você pode descartar este card para o Cemitério; adicione 1 "Valhala, o Salão dos Caídos" do seu Deck à sua mão.','Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74974229,'Tropa de Choque Alienígena Armação-M',replace(replace('2 monstros Réptil	\r\n(Efeito Rápido): você pode descartar 1 monstro; coloque Marcadores-A igual ao Nível original desse monstro em um ou mais monstros com a face para cima no campo, distribuídos como você quiser. \r\nSe este card for destruído em batalha ou por um efeito de card e enviado para o Cemitério: você pode Invocar por Invocação-Especial monstros Réptil que não sejam Link com nomes diferentes do seu Cemitério, até o número de monstros que seu oponente controla com Marcadores-A. \r\nVocê só pode usar cada efeito de "Tropa de Choque Alienígena Armação-M" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Escolha o monstro no qual colocar um marcador','Continuar selecionando?','','','','','','','','','','','','');
INSERT INTO texts VALUES(74976215,'Besouro Cruza-Espadas','Enquanto você controlar outro monstro Inseto, se um monstro Inseto que você controla atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74983881,'Milho Doce','Uma vez por turno, durante sua Fase Principal 2: Você pode pagar 500 PV; Invoque por Invocação-Especial 1 "Ficha Amido" (Tipo Planta/TERRA/Nível 1/ATK 0/DEF 0).','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74983882,'Ficha Amido','Invocado por Especial com o efeito "Milho Doce".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74997493,'Caveira Ameaçadora Saryuja',replace(replace('2+ monstros com nomes diferentes	\r\nEste card ganha efeitos de acordo com o número de matérias usadas para sua Invocação-Link.\r\n● 2+: Se um ou mais monstros forem Invocados por Invocação-Normal ou Especial em uma zona para a qual este card apontar: esse(s) monstro(s) ganha(m) 300 de ATK/DEF.\r\n● 3+: Uma vez por turno, durante sua Fase Principal: você pode Invocar por Invocação-Especial 1 monstro da sua mão.\r\n● 4: Quando este card for Invocado por Invocação-Link: você pode comprar 4 cards e, depois, coloque 3 cards da sua mão no fundo do Deck em qualquer ordem.','\r',char(13)),'\n',char(10)),'Aumentar ATK/DEF','Invoque por Invocação Especial 1 monstro da sua mão','Descartar e comprar','2+ monstros como Matéria','3+ monstros como Matéria','','','','','','','','','','','');
INSERT INTO texts VALUES(75003700,'Lukias Caudraco',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 monstro "Caudraco" do seu Deck à sua mão, exceto "Lukias Caudraco". \r\nSe este card for enviado para o Cemitério como matéria para uma Invocação-Fusão: você pode Baixar 1 Magia/Armadilha "Caudraco" do seu Deck. \r\nVocê só pode usar cada efeito de "Lukias Caudraco" uma vez por turno.','\r',char(13)),'\n',char(10)),'Efeito de busca','Baixar Magia/Armadilha','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75014062,'Domínio do Poder Mágico',replace(replace('Escolha 1 card com a face para cima no campo sobre o qual você possa colocar um Marcador de Magia; coloque 1 Marcador de Magia no alvo e, depois, você pode adicionar 1 "Domínio do Poder Mágico" do seu Deck à sua mão. \r\nVocê só pode ativar 1 "Domínio do Poder Mágico" por turno.','\r',char(13)),'\n',char(10)),'Adicionar 1 "Domínio do Poder Mágico" à sua mão?','Escolha o card no qual colocar "Marcador de Magia"','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75025112,'Monstros à Solta','Durante a Fase Principal: imediatamente depois que este efeito resolver, Invoque 1 monstro por Invocação-Normal/Baixar.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75041269,'Prisão da Torre do Relógio',replace(replace('Uma vez por turno, durante a Fase de Apoio do seu oponente: coloque 1 Marcador de Relógio neste card. \r\nEnquanto houver 4 ou mais Marcadores de Relógio neste card, você não sofre qualquer dano de batalha. \r\nSe este card com 4 ou mais Marcadores de Relógio for destruído e enviado para o Cemitério: Invoque por Invocação-Especial 1 "HERÓI do Destino - Mestre do Horror" da sua mão ou do Deck.','\r',char(13)),'\n',char(10)),'Colocar um marcador','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75043725,'Emissário de Outra Vida',replace(replace('Quando este card é enviado do Campo para o Cemitério, cada jogador escolhe 1 Monstro Normal de Nível 3 ou menos do seu Deck, revela-o ao adversário e adiciona-o à sua mão. \r\nEm seguida, embaralhe os Decks.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75046994,'Escama Ascendente Noh-P.U.N.K.',replace(replace('Você pode banir 1 outro card "P.U.N.K." da sua mão ou do Cemitério; Invoque este card por Invocação-Especial da sua mão. \r\nSe este card for Invocado por Invocação-Especial: você pode pagar 600 PV; adicione à sua mão, ou Invoque por Invocação-Especial, 1 monstro "P.U.N.K." do seu Deck ou Cemitério, exceto um monstro de Nível 8. \r\nQuando um monstro que seu oponente controla com 2500 ou mais de ATK ativar seu efeito (Efeito Rápido): você pode colocá-lo com a face para baixo em Posição de Defesa. \r\nVocê só pode usar cada efeito de "Escama Ascendente Noh-P.U.N.K." uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar este card por Invocação Especial','Adicionar à mão ou Invocar por Invocação Especial','Mudar a posição de batalha','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75047173,'Contato Favorito',replace(replace('Invoque por Invocação-Especial 1 Monstro de Fusão do seu Deck Adicional que mencione um monstro "HERÓI" como matéria, ignorando suas condições de Invocação, ao colocar as Matérias de Fusão mencionadas nele no fundo do Deck em qualquer ordem, dentre os cards na sua mão, no campo, no Cemitério e/ou seus cards banidos. \r\nSe você colocou "Neos, o HERÓI do Elemento" no Deck, nenhum duelista pode devolver o monstro Invocado por Invocação-Especial por este efeito para o Deck Adicional. \r\nVocê só pode ativar 1 "Contato Favorito" por turno.','\r',char(13)),'\n',char(10)),'','O efeito de "Contato Favorito" está sendo aplicado.','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75059201,'F.A. Turbo Charger',replace(replace('Ganha ATK igual ao seu próprio Nível x 300. \r\nOs monstros do seu oponente cujo Nível/Classe original seja menor que o Nível deste card não podem escolher monstros como alvo de ataques, exceto este. \r\nSeu oponente não pode escolher monstros, exceto este, como alvo de efeitos de monstros cujo Nível/Classe original seja menor que o Nível deste card. \r\nSempre que um Card ou efeito de Magia/Armadilha "F.A." for ativado: você pode aumentar em 1 o Nível deste card. \r\nSe um monstro "F.A." seu batalhar enquanto você controlar este card de Nível 7 ou mais, os monstros do seu oponente não podem ativar seus efeitos até o final da Etapa de Dano.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75064463,'Rainha Harpia',replace(replace('O nome deste card se torna "Lady Harpia" enquanto estiver no campo ou no Cemitério. \r\nVocê pode descartar este card para o Cemitério; adicione 1 "Terreno de Caça das Harpias" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75078585,'Decolar Ovo','Se um monstro que você controla for destruído em batalha ou por um efeito de card e enviado para o Cemitério: você pode Invocar por Invocação-Especial 1 "Filhote Sônico" da sua mão, do Deck ou do Cemitério.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75081613,'Aztekipede, a Lombriga Guerreira',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nVocê deve Invocá-lo por Invocação-Especial ao banir 1 monstro do Tipo Inseto do seu Cemitério e não pode Invocá-lo por Invocação-Especial de nenhuma outra forma. \r\nSe este card causar dano de batalha ao seu oponente: envie o card do topo do Deck dele para o Cemitério.','\r',char(13)),'\n',char(10)),'Enviar do Deck para o Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75083197,'Dragãotovia Pairen',replace(replace('2 monstros de Nível 6	\r\nNão pode ser destruído em batalha ou por um efeito de card enquanto um monstro, que não seja "Dragãotovia Pairen", que foi Invocado por Invocação-Especial do Cemitério estiver com a face para cima no campo. \r\nDurante a Fase de Apoio: você pode desassociar 1 matéria deste card e, depois, escolha 1 monstro de Nível 5 ou menos no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê só pode usar este efeito de "Dragãotovia Pairen" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75105429,'Ejeção Sincro',replace(replace('Escolha 1 Monstro Sincro com a face para cima que seu oponente controla e remova-o de jogo. \r\nDepois, seu oponente compra 1 card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75109441,'Sakuzy, a Cobra-Humana',replace(replace('Uma vez por turno, durante a sua Fase Principal, você pode virar este card com a face para baixo em Posição de Defesa. \r\nQuando este card for virado com a face para cima, olhe os Cards de Magia e Armadilha Baixados no lado do campo do oponente e os devolva às suas posições originais.','\r',char(13)),'\n',char(10)),'Mudar para Posição de Defesa com a face para baixo','Revelar um card Baixado','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75116619,'Seis Samurai Lendários - Enishi',replace(replace('Uma vez por turno (Efeito Rápido): você pode banir 2 monstros "Seis Samurai" do seu Cemitério e, depois, escolha 1 monstro com a face para cima no campo; devolva o alvo para a mão. \r\nVocê deve controlar um monstro "Seis Samurai" com a face para cima com um nome diferente para ativar e resolver este efeito. \r\nEnquanto você controlar 2 ou mais monstros "Seis Samurai", exceto "Seis Samurai Lendários - Enishi", este card ganha 500 de ATK/DEF.','\r',char(13)),'\n',char(10)),'Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75119040,'Cérbero Aguçado Tindângulo',replace(replace('3 monstros "Tindângulo"	\r\nGanha 3000 de ATK se você tiver 3 ou mais monstros "Tindângulo" com nomes diferentes no seu Cemitério, incluindo "Base Gardna Tindângulo". \r\nGanha 500 de ATK para cada monstro "Tindângulo" para o qual ele apontar. \r\nNo final da Fase de Batalha, se este card declarar um ataque: você pode Invocar por Invocação-Especial 1 "Ficha Tindângulo" (Demônio/TREVAS/Nível 1/ATK 0/DEF 0).','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75119041,'Ficha Tindângulo','Invocada por Invocação-Especial com o efeito "Cérbero Aguçado Tindângulo".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75130221,'Codificar Radiador',replace(replace('Se um monstro Ciberso que você controla seria usado como Matéria Link para um monstro "Codificar Transmissor", este card na sua mão também pode ser usado como matéria. \r\nSe este card for enviado da mão ou do campo para o Cemitério como matéria para a Invocação-Link de um monstro "Codificar Transmissor": você pode escolher 1 monstro com a face para cima que seu oponente controla; mude o ATK dele para 0 e, além disso, negue seus efeitos. \r\nSe este card no campo foi usado como matéria, em vez disso, você pode escolher 2 monstros. \r\nVocê só pode usar cada efeito de "Codificar Radiador" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Enviar do campo para o Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75132317,'Irmandade do Punho de Fogo - Serpente',replace(replace('Uma vez por turno, se um ou mais Cards de Magia/Armadilha "Formação de Fogo" forem enviados para o seu Cemitério (exceto durante a Etapa de Dano): você pode Baixar 1 Card de Armadilha "Formação de Fogo" diretamente do seu Deck. \r\nUma vez por turno, se você não controlar outros monstros: você pode enviar 2 Cards de Magia/Armadilha "Formação de Fogo" com a face para cima que você controla para o Cemitério; compre 1 card.','\r',char(13)),'\n',char(10)),'Baixar','Comprar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75141056,'Máscara do Herói','Escolha 1 monstro com a face para cima que você controla; envie 1 monstro "HERÓI do Elemento" do seu Deck para o Cemitério e, se isso acontecer, até a Fase Final, o nome do alvo se torna o nome do monstro enviado.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75147529,'Força Celeste - Ás - Zeke',replace(replace('2 monstros, incluindo um monstro "Força Celeste - Ás"	\r\nDeve ser Invocado por Invocação-Link. \r\nVocê só pode Invocar um ou mais "Força Celeste - Ás - Zeke" por Invocação-Especial uma vez por turno. \r\nSe este card for Invocado por Invocação-Link: você pode escolher 1 monstro com a face para cima no campo; bana-o até a próxima Fase Final do seu oponente. \r\nUma vez por turno: você pode escolher 1 outro card que você controla; este card ganha 1000 de ATK e, depois, envie o card alvo para o Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75153328,'Troca de Pacote',replace(replace('Escolha 1 Monstro que não seja Link com a face para cima que você controla e 1 Monstro Link que seu oponente controla; troque o controle desses monstros. \r\nVocê só pode ativar 1 "Troca de Pacote" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75157704,'União dos Dois Avatares',replace(replace('Durante a Fase Principal: bana 1 Magia/Armadilha "Dois Avatares" do seu Cemitério, exceto "União dos Dois Avatares"; o efeito deste card se torna o efeito dessa Magia/Armadilha quando esse card for ativado. \r\nVocê só pode ativar 1 "União dos Dois Avatares" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75162696,'Victória',replace(replace('Uma vez por turno: você pode escolher 1 monstro do Tipo Dragão no Cemitério do seu oponente; Invoque o alvo por Invocação-Especial no seu lado do campo. \r\nSeu oponente não pode escolher monstros do Tipo Fada com a face para cima como alvo de ataques, exceto por este.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75180828,'Sirena Abisbalea',replace(replace('Você pode descartar 4 outros monstros "Sirena" para o Cemitério; Invoque este card por Invocação-Especial da sua mão. \r\nAo fazê-lo: escolha cards que seu oponente controla até o número de monstros "Sirena" em seu Cemitério (se possível); este card ganha 500 de ATK e, se isso acontecer, destrua os alvos (se houver). \r\nVocê pode oferecer como Tributo 1 outro monstro "Sirena" com a face para cima em Posição de Ataque; neste turno, este card ganha o seguinte efeito.\r\n● No começo da Etapa de Dano, se este card batalhar um monstro em Posição de Defesa: destrua esse monstro.','\r',char(13)),'\n',char(10)),'Invocação Especial','Destruir','Ganhar um efeito adicional','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75190122,'Magia Ardente das Trevas','Se você controlar monstros cujos nomes originais sejam "Mago Negro" e "Pequena Maga Negra": destrua todos os cards que seu oponente controla.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75191028,'GMX - COMPREX',replace(replace('1 monstro "GMX" + 2+ monstros Dinossauro	\r\nGanha esses efeitos de acordo com o número de monstros Dinossauro usados como Matéria de Fusão para este card.\r\n● 3+: Seu oponente não pode escolher este card como alvo de efeitos de card.\r\n● 4+: Pode realizar até 3 ataques durante cada Fase de Batalha.\r\n● 5+: Sempre que seu oponente Invocar um ou mais monstros por Invocação-Normal ou Especial, ele perde 800 PV.	\r\nUma vez por turno, se você escavar um ou mais cards devido a um efeito de card "GMX": você pode destruir todos os outros monstros no campo.','\r',char(13)),'\n',char(10)),'','Destruir','3+ monstros Dinossauro usados como Matéria de Fusão','4+ monstros Dinossauro usados como Matéria de Fusão','5+ monstros Dinossauro usados como Matéria de Fusão','','','','','','','','','','','');
INSERT INTO texts VALUES(75195825,'Pêndulo Master, o Dracossassino',replace(replace('Escala de Pêndulo = 3\r\n[ Efeito de Pêndulo ]\r\nUma vez, enquanto este card estiver na sua Zona de Pêndulo: você pode escolher 1 card em uma Zona de Pêndulo; destrua-o.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\n"Pêndulo Luster, o Dracossassino" continua sua jornada para desvendar os segredos da Alquimia Dragão, acreditando ser a chave para desfazer sua maldição e restaurar sua memória. Seu poder continua a crescer... talvez o mesmo poder usado pelos Dracodemônios?','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75198893,'Scanner',replace(replace('Uma vez por turno, você pode selecionar 1 monstro do seu oponente que foi removido de jogo. \r\nAté a Fase Final, o nome deste card é considerado como o nome do monstro selecionado, e este card tem o mesmo Atributo, Nível, ATK e DEF do monstro selecionado. \r\nSe este card for removido do campo enquanto este efeito estiver aplicado, remova-o de jogo.','\r',char(13)),'\n',char(10)),'Alterar nome','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75209824,'Estátua Guardião',replace(replace('Você pode virar este card para Posição de Defesa com a face para baixo uma vez por turno durante a sua Main Phase. \r\nQuando este card é Invocado, por Invocação-Virar, com sucesso, devolva 1 monstro no Campo do seu adversário para a mão do seu dono.','\r',char(13)),'\n',char(10)),'Mudar para Posição de Defesa com a face para baixo','Retornar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75214390,'Impulsionador Revestido',replace(replace('Se você controlar um monstro com 2000 ou mais de ATK, você pode Invocar este card por Invocação-Especial (da sua mão) em Posição de Defesa. \r\nVocê só pode Invocar "Impulsionador Revestido" por Invocação-Especial uma vez por turno desta forma. \r\nSe este card estiver no seu Cemitério, exceto no turno em que foi enviado para lá: você pode bani-lo e, depois, escolha 1 Monstro Xyz com a face para cima que você controla que tenha matéria; ele ganha 500 de ATK para cada matéria associada a ele.','\r',char(13)),'\n',char(10)),'Alterar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75215744,'Naviushi Gunkan Couraçado Classe Ikura',replace(replace('2 monstros de Nível 4	\r\nSe este card for Invocado por Invocação-Xyz: você pode aplicar esses efeitos, em sequência, de acordo com as matérias usadas. \r\nVocê só pode usar este efeito de "Naviushi Gunkan Couraçado Classe Ikura" uma vez por turno.\r\n● "Shari do Naviushi Gunkan": Compre 1 card.\r\n● "Ikura do Naviushi Gunkan": Este card pode realizar um segundo ataque durante cada Fase de Batalha.	\r\nUma vez por turno, quando um monstro "Gunkan" seu Invocado por Invocação-Especial do Deck Adicional causar dano de batalha ao seu oponente: você pode escolher 1 card que seu oponente controla; destrua-o.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75220074,'Dragão Armado, o Dragão Encouraçado','Quando este card destruir um monstro do oponente em batalha: você pode Invocar por Invocação-Especial 1 monstro Dragão de VENTO de Nível 5 ou menos da sua mão ou do Deck, exceto "Dragão Armado, o Dragão Encouraçado", mas ele não pode atacar diretamente neste turno.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75223115,'Território Pernicioso',replace(replace('Quando este card for ativado: você pode ativar 1 "Mundo Pernicioso" do seu Deck. \r\nEnquanto esse card estiver na Zona do Campo, nenhum duelista pode escolher um ou mais cards na Zona do Campo como alvo de efeitos de card. \r\nO efeito dos monstros "Pernicioso(a)", "Só pode haver 1 monstro "Pernicioso(a)" com a face para cima no campo" se torna "Só pode haver 1 monstro "Pernicioso(a)" com o mesmo nome com a face para cima no campo". \r\nDurante a Fase de Batalha, negue os efeitos dos monstros "Pernicioso(a)" com a face para cima no campo.','\r',char(13)),'\n',char(10)),'Ativar uma Magia de Campo?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75249652,'Força do Espelho em Chamas','Quando um monstro do oponente declarar um ataque: destrua tantos monstros em Posição de Ataque que seu oponente controla quanto possível e, se isso acontecer, sofra dano igual à metade do ATK original combinado desses monstros destruídos e, depois, cause dano ao seu oponente igual ao dano que você sofreu.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75252099,'Pássaro de Rosas','Quando este card com a face para cima em Posição de Ataque que você controla for destruído em batalha com um monstro atacante do oponente e enviado para o seu Cemitério: você pode Invocar por Invocação-Especial 2 Reguladores Planta do seu Deck em Posição de Defesa.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75253697,'Número 72: Torre Shogi',replace(replace('2 monstros de Nível 6	\r\nUma vez por turno: você pode desassociar 2 matérias deste card e, depois, escolha 1 monstro com a face para cima que seu oponente controla e 1 Magia/Armadilha Baixada que seu oponente controla; destrua-os e, além disso, qualquer dano de batalha que seu oponente sofrer é diminuído pela metade pelo resto deste turno.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75285069,'Criatura da Humidade',replace(replace('Você pode oferecer 3 monstros como Tributo para Invocar este card por Invocação-Tributo (mas não para Baixar). \r\nSe Invocado desta forma: destrua todas as Magias e Armadilhas que seu oponente controla.','\r',char(13)),'\n',char(10)),'Ofereça 3 monstros como Tributo para Invocar','Destruir Magias/Armadilhas','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75286621,'Mechaba, o Invokado',replace(replace('"Aleister, Aquele que Invoka" + 1 monstro de LUZ	\r\nUma vez por turno, quando um Card de Magia/Armadilha ou efeito de monstro for ativado (Efeito Rápido): você pode enviar o mesmo tipo de card (Monstro, Magia ou Armadilha) da sua mão para o Cemitério; negue a ativação e, se isso acontecer, bana esse card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75286622,'Mechaba, o Invokado',replace(replace('"Aleister, Aquele que Invoka" + 1 monstro de LUZ	\r\nUma vez por turno, quando um Card de Magia/Armadilha ou efeito de monstro for ativado (Efeito Rápido): você pode enviar o mesmo tipo de card (Monstro, Magia ou Armadilha) da sua mão para o Cemitério; negue a ativação e, se isso acontecer, bana esse card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75290703,'Therion Irregular',replace(replace('Você pode escolher até 3 monstros "Therion" no seu Cemitério; Invoque este card por Invocação-Especial da sua mão e, se isso acontecer, equipe-os a este card. \r\nVocê pode descartar 1 "Motor Interminável Sistema Argyro"; destrua todos os cards que seu oponente controla. \r\nEnquanto este card estiver equipado a um monstro: você pode Invocar este card por Invocação-Especial e, depois, equipe o monstro ao qual este card estava equipado a este card. \r\nVocê só pode usar cada efeito de "Therion Irregular" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Destruir todos os cards que seu oponente controla','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75292259,'Besouro Gigante Poseidon',replace(replace('Se este card escolher um monstro com a face para cima em Posição de Ataque do oponente como alvo de um ataque, e esse monstro não for destruído em batalha, este card pode atacar o mesmo monstro novamente, em sequência. \r\nEste efeito só pode ser usado duas vezes por turno.','\r',char(13)),'\n',char(10)),'Continuar atacando?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75294187,'Aterrorizante Pesadelo Buraco Armadilha',replace(replace('Se seu oponente tiver Invocado um ou mais monstros por Invocação-Especial neste turno: escolha 1 monstro que seu oponente controla com 2000 ou mais de ATK; destrua-o e, depois, se você tiver uma Armadilha Normal "Buraco" no seu Cemitério, você pode banir 1 monstro do Cemitério do seu oponente. \r\nVocê só pode ativar 1 "Aterrorizante Pesadelo Buraco Armadilha" por turno.','\r',char(13)),'\n',char(10)),'Banir 1 monstro do Cemitério do oponente?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75304793,'Sinfo Amplificardor',replace(replace('Sempre que um efeito de um card "Guerreiro Sinfônico" for ativado, coloque 1 Marcador Sinfônico neste card quando esse efeito resolver. \r\nTodos os monstros "Guerreiro Sinfônico" no campo ganham 100 de ATK para cada Marcador Sinfônico neste card. \r\nUma vez por turno: você pode remover 5 ou 7 Marcadores Sinfônicos do seu campo; aplique este efeito, dependendo do número de Marcadores Sinfônicos removidos.\r\n● 5: Cause 300 de dano ao seu oponente para cada card "Guerreiro Sinfônico" no campo.\r\n● 7: Bana cards que seu oponente controla e/ou no Cemitério dele, até o número de cards "Guerreiro Sinfônico" no campo.','\r',char(13)),'\n',char(10)),'5: Causar dano ao seu oponente','7: Banir os cards do oponente','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75311421,'Votis',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode escavar os 3 cards do topo do seu Deck e, se isso acontecer, você pode banir 1 monstro escavado para adicionar à sua mão 1 monstro com seu mesmo nome, do seu Deck ou dentre os outros cards escavados e, além disso, embaralhe o resto no Deck. \r\nUma vez por turno, durante a Fase Final, se este card estiver no seu Cemitério porque foi enviado para lá neste turno depois de ser Invocado por Invocação-Normal/Baixado: você pode escavar os 3 cards do topo do seu Deck e, se isso acontecer, coloque-os no topo do Deck em qualquer ordem.','\r',char(13)),'\n',char(10)),'Banir e adicionar um card com o mesmo nome?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75326861,'Highlander das Trevas',replace(replace('1 Regulador do Tipo Demônio + 1 ou mais monstros do Tipo Demônio não-Reguladores	\r\nNenhum duelista pode Invocar por Invocação-Sincro. \r\nUma vez por turno: Você pode escolher 1 monstro que seu oponente controla que estiver equipado com um Card de Equipamento; destrua todos os Cards de Equipamento equipados a esse monstro e, se isso acontecer, cause 400 de dano ao seu oponente para cada card destruído.','\r',char(13)),'\n',char(10)),'Destruir Cards de Equipamento','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75347539,'Valkyrion, o Guerreiro Ímã',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro deve ser Invocado por Invocação-Especial (da sua mão) ao oferecer como Tributo 1 "Alfa, o Guerreiro Ímã", "Beta, o Guerreiro Ímã" e "Gama, o Guerreiro Ímã" da sua mão e/ou do campo. \r\nVocê pode oferecer este card como Tributo e, depois, escolha 1 "Alfa, o Guerreiro Ímã", "Beta, o Guerreiro Ímã" e "Gama, o Guerreiro Ímã" no seu Cemitério; Invoque-os por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75352507,'Selene Mordedora Ragnaraika',replace(replace('2+ monstros Inseto, Planta e/ou Réptil	\r\nVocê pode banir até 2 monstros do seu Cemitério e, depois, escolha esse número de Magias/Armadilhas que seu oponente controla; destrua-as. \r\nSe este card estiver no seu Cemitério: você pode escolher 1 monstro Inseto, Planta ou Réptil que você controla; coloque-o no fundo do Deck e, se isso acontecer, Invoque este card por Invocação-Especial e, além disso, você não pode Invocar por Invocação-Especial pelo resto deste turno, exceto monstros Inseto, Planta ou Réptil. \r\nVocê só pode usar cada efeito de "Selene Mordedora Ragnaraika" uma vez por turno.','\r',char(13)),'\n',char(10)),'Destruir Magias/Armadilhas','Invocar por Invocação Especial do Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75356564,'Pequeno Dragão','Um dragão muito pequeno conhecido pelos seus ataques ferozes.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75361204,'Divisão Alicercinza',replace(replace('Escolha 1 monstro com a face para cima que você controla; equipe este card nele. \r\nEle ganha 500 de ATK. \r\nDurante sua Fase Principal: você pode enviar para o Cemitério este card equipado a um monstro por este efeito; destrua o monstro ao qual este card estava equipado e, se isso acontecer, Invoque por Invocação-Especial 2 monstros "Alicercinza" com nomes diferentes do seu Deck, mas destrua-os durante a Fase Final. \r\nVocê só pode usar este efeito de "Divisão Alicercinza" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75363626,'Gineterole Magidoce',replace(replace('Quando este card que você controla for destruído por um card do oponente (seja em batalha ou por um efeito de card) e enviado ao seu Cemitério: Embaralhe este card no seu Deck. \r\nSeu oponente não pode escolher monstros "Magidoce" com a face para cima para ataques, exceto "Gineterole Magidoce".','\r',char(13)),'\n',char(10)),'Retornar ao Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75364199,'Destruição Mútua Pelegurada',replace(replace('Os dois duelistas devem manter suas mãos reveladas neste turno. \r\nEnquanto suas mãos estiverem reveladas por este efeito, se os dois tiverem um card com o mesmo nome em suas mãos, nenhum duelista pode ativar cards com esse nome, ou seus efeitos.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75366958,'Dinolutador Celasilat',replace(replace('Se você não controlar nenhum monstro, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nSe Invocado desta forma, este card não pode ser usado como Matéria Link, exceto para a Invocação-Link de um monstro "Dinolutador". \r\nVocê só pode Invocar "Dinolutador Celasilat" por Invocação-Especial uma vez por Duelo desta forma.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75367227,'Alucard Fantardil',replace(replace('2 monstros de Nível 3	\r\nOs monstros do seu oponente não podem escolher monstros "Fantardil", ou qualquer monstro com a face para baixo em Posição de Defesa, como alvos de ataque, exceto este. \r\nVocê pode desassociar 1 matéria deste card e, depois, escolha 1 card Baixado que seu oponente controla; destrua o alvo. \r\nVocê só pode usar este efeito de "Alucard Fantardil" uma vez por turno. \r\nSe este card for enviado para o Cemitério: você pode escolher 1 outro card "Fantardil" no seu Cemitério; adicione o alvo à sua mão.','\r',char(13)),'\n',char(10)),'Destruir 1 card Baixado','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75372290,'Shogun da Defesa Total',replace(replace('Se este card for Invocado, por Invocação-Normal ou por Invocação-Virar, com sucesso, é mudado para Posição de Defesa. \r\nEste card pode atacar enquanto está em Posição de Defesa. \r\nSe este card atacar em Posição de Defesa, aplique o ATK deste card para o cálculo de dano.','\r',char(13)),'\n',char(10)),'Mudar para Posição de Defesa','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75375465,'Urso de Vigia do Pandemónio','Enquanto este card permanecer no Campo com a face para cima, um "Pandemônio" no seu Campo não pode ser destruído por efeitos de cards do seu adversário.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75376965,'Sereia Fascinante','Uma linda sereia que atrai viajantes para um túmulo aquático.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75380687,'Dragão Amuleto',replace(replace('"Mago Negro" + 1 monstro Dragão	\r\nDeve ser Invocado por Invocação-Fusão com as Matérias de Fusão acima ou com "O Olho de Timaeus". \r\nSe este card for Invocado por Invocação-Especial: escolha qualquer número de Magias em quaisquer Cemitérios (mín.1); bana os alvos e, se isso acontecer, este card ganha 100 de ATK para cada card banido por este efeito. \r\nSe este card for destruído: você pode escolher 1 monstro Mago no seu Cemitério; Invoque o alvo por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Banir','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75390004,'Megazowler','Nada fica no caminho deste dinossauro coberto de pontas!','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75392615,'Hack Mental',replace(replace('Pague 500 Life Points. \r\nVeja a mão do seu adversário e todos os cards Baixados no Campo do seu adversário.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75402014,'Raio Utopia Dragônico Definitivo',replace(replace('3 monstros de Nível 5	\r\n(Este card deve ser sempre considerado como "Número C39: Raio Utopia".)	\r\nUma vez por turno, quando um card ou efeito for ativado que escolha este card como alvo, ou quando este card for alvo de um ataque (Efeito Rápido): você pode equipar 1 monstro "ZW -" da sua mão ou do Deck a este card como se ele tivesse sido equipado pelo efeito desse monstro. \r\nUma vez por turno: você pode desassociar 1 matéria deste card e, depois, escolha cards com a face para cima que seu oponente controla até o número de Cards de Monstro "ZW -" equipados a este card; negue seus efeitos.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75416738,'Armadilhatrix Aracnocampa',replace(replace('Não é afetado pelos efeitos de Armadilhas Normais "Buraco". \r\nNa primeira vez que cada card Baixado na sua Zona de Magias & Armadilhas seria destruído por um efeito de card a cada turno, ele não é destruído. \r\nDurante a Fase Principal, se você controlar um monstro "Armadilhatrix" (Efeito Rápido): você pode Invocar este card por Invocação-Especial da sua mão e, além disso, você não pode Invocar monstros por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto monstros Inseto ou Planta. \r\nVocê só pode usar este efeito de "Armadilhatrix Aracnocampa" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75417459,'Libertado','Ofereça como Tributo 1 "Gearfried, o Cavaleiro de Ferro"; Invoque por Invocação-Especial 1 "Gearfried, o Mestre da Espada" da sua mão ou do Deck.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75421661,'Espadachim Dododo',replace(replace('Enquanto este card que foi Invocado por Invocação-Virar estiver com a face para cima no campo, ele ganha 3500 de ATK. \r\nQuando este card for virado com a face para cima: você pode escolher até 2 monstros no campo com a face para cima; destrua-os.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75425043,'PSÍ-Armação Equipamento Alfa',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial por um efeito de card e não pode ser Invocado por Invocação-Especial de nenhuma outra forma. \r\nQuando seu oponente Invocar um ou mais monstros por Invocação-Normal ou Especial enquanto você não controlar nenhum monstro (exceto durante a Etapa de Dano): você pode Invocar por Invocação-Especial tanto este card da sua mão quanto 1 "PSÍ-Armação Condutor" da sua mão, Deck ou Cemitério e, se isso acontecer, adicione 1 card "PSÍ-Armação" do seu Deck à sua mão, exceto "PSÍ-Armação Equipamento Alfa". \r\nDurante a Fase Final, bana os monstros com a face para cima Invocados por Invocação-Especial por este efeito.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75425320,'Discípulos da Verdadeira Dracofênix',replace(replace('Você pode escolher 3 cards "Verdadeiro(a) Draco" e/ou "Verdadeiro Rei" no seu Cemitério; embaralhe-os no Deck e, depois, compre 1 card. \r\nDurante sua Fase Principal, você pode: imediatamente depois que este efeito resolver, Invocar por Invocação-Tributo com a face para cima 1 monstro "Verdadeiro(a) Draco" ou "Verdadeiro Rei". \r\nSe este card for enviado da Zona de Magias & Armadilhas para o Cemitério: você pode escolher 1 Magia/Armadilha no campo; destrua-a. \r\nVocê só pode usar cada efeito de "Discípulos da Verdadeira Dracofênix" uma vez por turno.','\r',char(13)),'\n',char(10)),'Reciclar e comprar','Invocação Tributo','Destruir um Card de Magia/Armadilha','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75433814,'Número 40: Engenhoca Marionete das Cordas',replace(replace('2 monstros de Nível 8	\r\nUma vez por turno: você pode desassociar 1 matéria deste card; coloque 1 Marcador de Corda em cada monstro com a face para cima no campo, exceto este card. \r\nUma vez por turno, durante a próxima Fase Final do oponente do duelista que colocou um ou mais Marcadores de Corda com este efeito: destrua os monstros com Marcadores de Corda e, se isso acontecer, cause 500 de dano ao seu oponente para cada monstro destruído.','\r',char(13)),'\n',char(10)),'Colocar um marcador','Destrua e cause dano','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75434695,'Lenhador, o HERÓI do Elemento','Uma vez por turno, durante sua Fase de Apoio: você pode adicionar 1 "Polimerização" do seu Deck ou Cemitério à sua mão.','Adicione à sua mão 1 Card de Magia "Polimerização/Fusão".','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75448086,'Missão do Chefe Generaidor',replace(replace('Revele 1 monstro "Generaidor" na sua mão e, se isso acontecer, adicione até 2 Magias/Armadilhas "Generaidor" com nomes diferentes uma da outra do seu Deck à sua mão, exceto "Missão do Chefe Generaidor". \r\nDepois coloque o card revelado no fundo do seu Deck. \r\nVocê só pode ativar 1 "Missão do Chefe Generaidor" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75452921,'Cavaleiro do Pesadelo Cérbero',replace(replace('2 monstros com nomes diferentes	\r\nSe este card for Invocado por Invocação-Link: você pode descartar 1 card e, depois, escolha 1 monstro Invocado por Invocação-Especial em uma Zona de Monstros Principal do seu oponente; destrua-o e, depois, se este card estava co-linkado quando este efeito foi ativado, você pode comprar 1 card. \r\nVocê só pode usar este efeito de "Cavaleiro do Pesadelo Cérbero" uma vez por turno. \r\nMonstros co-linkados que você controla não podem ser destruídos por efeitos de card.','\r',char(13)),'\n',char(10)),'','Comprar 1 card?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75457624,'Vínculo da Besta Espiritual','Bana 2 monstros "Besta Espiritual" que você controla; Invoque por Invocação-Especial 1 monstro "Besta Espiritual" do seu Deck Adicional, ignorando suas condições de Invocação.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75487237,'Escudo Médio Gardna',replace(replace('Você pode virar este card para Posição de Defesa com a face para baixo uma vez por turno durante a sua Main Phase. \r\nAnule a ativação de um Card de Magia que designe como alvo este 1 monstro com a face para baixo. \r\nNessa altura, vire este card para Posição de Defesa com a face para cima.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75493362,'Bênção de Vingolfe',replace(replace('Quando este card for ativado: você pode enviar 1 monstro Fada de LUZ do seu Deck para o Cemitério. \r\nMonstros Fada que você controla ganham 100 de ATK para cada monstro Fada no seu campo e Cemitério. \r\nSe este card for enviado para o Cemitério: você pode escolher 1 monstro Fada de Nível 4 ou menos no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê só pode usar este efeito de "Bênção de Vingolfe" uma vez por turno. \r\nVocê só pode ativar 1 "Bênção de Vingolfe" por turno.','\r',char(13)),'\n',char(10)),'Ativar','Invocação Especial','Enviar o card para o Cemitério?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75498415,'Asanegra - Sirocco, o Amanhecer',replace(replace('Se somente seu oponente controlar um monstro, você pode Invocar este card por Invocação-Normal/Baixar sem oferecer Tributo. \r\nUma vez por turno, durante sua Fase Principal 1: você pode escolher 1 monstro "Asanegra" que você controla; até o final deste turno, ele ganha ATK igual ao ATK combinado de todos os monstros "Asanegra" atualmente no campo, exceto ele mesmo e, além disso, pelo resto deste turno, você só pode atacar com esse monstro.','\r',char(13)),'\n',char(10)),'Invocação Normal sem Tributo','Aumentar ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75499502,'Mestre & Especialista','Uma dupla letal formada por um mestre de bestas e pelo seu fiel servo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75500286,'Sarcófago Dourado',replace(replace('Bana, com a face para cima, 1 card do seu Deck. \r\nDurante sua 2ª Fase de Apoio depois da ativação deste card, adicione esse card à mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75518330,'Esperança de Barian',replace(replace('Invoque por Invocação-Especial 1 monstro "Terror Umbral" ou Monstro Xyz "Mascarado" da sua mão ou Cemitério, então você pode fazer com que os Níveis de todos os monstros "Terror Umbral" que você controla se tornem do Nível de 1 monstro "Terror Umbral" no seu campo ou Cemitério.\r\nVocê pode banir este card do seu Cemitério, então escolha 1 Monstro Xyz que você controla; associe 1 Monstro Xyz "Número" do seu Deck Adicional ou Cemitério nele.\r\nVocê só pode usar cada um dos efeitos de "Esperança de Barian" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar','Como matéria','Alterar o Nível?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75524092,'Garra Maligna',replace(replace('O monstro equipado ganha 300 de ATK. \r\nSe o monstro equipado seria destruído em batalha, em vez disso, devolva este card para a mão do seu dono. \r\nDepois, destrua 1 monstro, exceto aquele que batalhou com o monstro equipado, e cause 600 de dano ao seu oponente. \r\nDepois disso, Invoque por Invocação-Especial 1 "Ficha Maligna" (Tipo Demônio/TREVAS/Nível 7/ATK 2500/DEF 2500) no lado do campo do seu oponente. \r\nDurante o turno em que este card foi devolvido para a sua mão, você não pode usar "Garra Maligna" da sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75524093,'Ficha Maligna','Invocado por Especial com o efeito "Garra Maligna".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75525309,'Estilo dos Seis - Duas Armas','Se o único monstro que você controla for 1 monstro "Seis Samurai" com a face para cima em Posição de Ataque: Escolha 2 cards que seu oponente controla; devolva os alvos para a mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75527221,'Sopro Mortal do Zumbi',replace(replace('Se você controlar um monstro Zumbi e "Chamado dos Assombrados": escolha 1 monstro que seu oponente controla; envie-o para o Cemitério. \r\nSe você controlar um monstro Zumbi: você pode banir este card do seu Cemitério e, depois, escolha 1 card com a face para cima que você controla e 1 card com a face para cima que seu oponente controla; envie-os para o Cemitério. \r\nVocê só pode usar 1 efeito de "Sopro Mortal do Zumbi" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar','Enviar para o Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75539614,'Lâmina Psíquica',replace(replace('Pague PV em múltiplos de 100 (máx. 2000); equipe este card a um monstro. \r\nEle ganha esse tanto de ATK e DEF. \r\nVocê só pode ativar 1 "Lâmina Psíquica" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75559356,'Cibersoldado do Mundo das Trevas',replace(replace('Um soldado mecânico que não para de atacar até que todos os sinais de vida desapareçam de seus sensores.	\r\n\r\n(Este card não é considerado como um card "Ciber".)','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75560629,'Flint',replace(replace('O monstro equipado perde 300 de ATK e não pode mudar sua posição de batalha ou declarar um ataque. \r\nSe este card for destruído porque o monstro equipado foi destruído: escolha 1 monstro no campo; equipe este card a esse monstro.','\r',char(13)),'\n',char(10)),'Equipar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75574498,'Princesa Colônia',replace(replace('2 monstros de Nível 4	\r\nQuando este card for Invocado por Invocação-Xyz: você pode escolher 1 "Caixa de Amigos" no seu Cemitério; Invoque o alvo por Invocação-Especial. \r\nSe você controlar outro monstro, os monstros do seu oponente não podem escolher este card como alvo de ataques e, além disso, seu oponente não pode escolher este card como alvo de efeitos de card. \r\nSe um ou mais Monstros Normais com a face para cima que você controla forem destruídos em batalha ou por um efeito de card e enviados para o Cemitério: você pode desassociar 1 matéria deste card; Invoque por Invocação-Especial 1 Monstro Normal do seu Deck ou Cemitério em Posição de Defesa.','\r',char(13)),'\n',char(10)),'Invocação Especial','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75582395,'Pássaro da Fé','Esse pássaro de rabo cumprido cega seus inimigos com uma luz mística.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75620895,'Receptáculo de Habilidades de um Só Olho',replace(replace('3 monstros de Nível 4	\r\nVocê pode desassociar 1 Matéria Xyz deste card para escolher 1 Monstro Xyz com a face para cima que seu oponente controla; o nome e efeito originais deste card se tornam os mesmo que os desse monstro. \r\nEste efeito só pode ser usado uma vez, enquanto este card estiver com a face para cima no campo.','\r',char(13)),'\n',char(10)),'Efeito de copiar','Terminar o efeito copiado','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75622824,'Traiçoeiro Feitiço 4','Envie 1 "O Enganador" com a face para cima que você controla para o Cemitério; Invoque por Invocação-Especial "Fichas de Traiçoeiro" (Tipo Mago/VENTO/Nível 5/ATK 2000/DEF 1200) em Posição de Defesa, igual ao número de monstros que seu oponente controla. "Fichas de Traiçoeiro" não podem declarar ataque.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75622825,'Ficha de Traiçoeiro','Invocado por Especial com o efeito "Traiçoeiro Feitiço 4". Esta Ficha não pode declarar um ataque.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75646173,'Sincroar','Esta criatura de duas cabeças cospe raios laser em seus inimigos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75646520,'Detector de Metais',replace(replace('Você pode ativar este card quando um Card de Armadilha Contínua for ativado. \r\nNegue os efeitos de todos os Cards de Armadilha Contínua durante o turno em que este card for ativado.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75652080,'Ciclone Duplo','Escolha 1 Magia/Armadilha que você controla e 1 Magia/Armadilha que seu oponente controla; destrua-as.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75660578,'Hela, Chefe Generaidora da Perdição',replace(replace('Você só pode controlar 1 "Hela, Chefe Generaidora da Perdição". \r\n(Efeito Rápido): você pode oferecer como Tributo 1 monstro "Generaidor" ou 1 monstro Zumbi e, depois, escolha 1 monstro "Generaidor" ou 1 monstro Zumbi no seu Cemitério, com um nome diferente que o monstro oferecido como Tributo tinha no campo; Invoque esse monstro por Invocação-Especial em Posição de Defesa. \r\nVocê só pode usar este efeito de "Hela, Chefe Generaidora da Perdição" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75672051,'Mago de Presa Negra',replace(replace('Escala de Pêndulo = 8\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno: você pode escolher 1 monstro com a face para cima que seu oponente controla; seu ATK se torna metade do seu ATK atual (até o final deste turno) e, depois, destrua este card.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\n(Este card deve ser sempre considerado como um card "Dragão Xyz".)	\r\nSe este card for destruído em batalha ou por um efeito de card: você pode escolher 1 monstro de TREVAS do Tipo Mago no seu Cemitério; Invoque-o por Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75673220,'Boca-de-Dragão',replace(replace('Quando este card for enviado para o Cemitério: até a Fase Final, bana 1 card aleatoriamente da mão do seu oponente. \r\nVocê só pode usar o efeito de "Boca-de-Dragão" uma vez por turno.','\r',char(13)),'\n',char(10)),'Banir da mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75675029,'Rei Esmaga Memória','Quando este card causar Dano de Batalha ao seu oponente por um ataque direto, remova de jogo todos os Monstros Sincro no Cemitério do seu oponente e cause 1000 de dano ao seu oponente para cada monstro removido.','Banir e causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75676192,'F.A. Autocaravana de Transporte',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nGanha ATK igual ao seu Nível x 300. \r\nSempre que um Card ou efeito de Magia/Armadilha "F.A." for ativado: você pode aumentar em 1 o Nível deste card. \r\nEste card ganha o(s) seguinte(s) efeito(s), baseado no seu Nível atual.\r\n● Nível 11 ou mais: Não pode ser destruído em batalha ou por efeitos de card.\r\n● Nível 13 ou mais: Uma vez por turno: você pode escolher 1 monstro "F.A." no seu Cemitério; Invoque-o por Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75690317,'Karakuri Gama mdl 4624 "Shirokunishi"',replace(replace('Este card deve atacar, se possível. \r\nSe este card for escolhido como alvo de um ataque: mude a posição de batalha deste card. \r\n(Efeito Rápido): você pode banir este card do seu Cemitério e, depois, escolha 1 monstro "Karakuri" que você controla; mude sua posição de batalha. \r\nVocê só pode usar este efeito de "Karakuri Gama mdl 4624 "Shirokunishi"" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75702749,'Aperto Fantasma Espiral',replace(replace('Só pode ser equipado a um Monstro Normal. \r\nEle ganha 500 de ATK. \r\nQuando o monstro equipado destruir um monstro do oponente em batalha: você pode Invocar por Invocação-Especial 1 "Dragão Fantasma Espiral" de sua mão, Deck ou Cemitério, e equipe-o com este card e, depois, cause 1000 de dano ao seu oponente. \r\nVocê só pode usar este efeito de "Aperto Fantasma Espiral" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75713017,'Prometeoro, a Estrela Ardente','Quando este card atacante destruir um monstro na Zona de Monstros Principal do seu oponente: você pode descartar 1 card; este card pode atacar novamente em seguida e, além disso, a zona na qual esse monstro estava não pode ser usada até o final do próximo turno.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75719089,'Glória dos Nobre Cavaleiros',replace(replace('Escolha 1 monstro "Nobre Cavaleiro" que você controla; equipe-o com 1 Magia de Equipamento do seu Deck que você possa equipar nesse alvo. \r\nVocê só pode ativar 1 "Glória dos Nobre Cavaleiros" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75728539,'Sharv Sarga',replace(replace('Se "Visas Starfrost" estiver no campo: escolha 1 Monstro de Efeito no campo; embaralhe o alvo no Deck e, se isso acontecer, durante a Fase Final deste turno, seu dono pode adicionar 1 monstro do Deck dele à mão dele com um Tipo diferente e um Nível menor que o Nível/Classe/Valor Link desse monstro. \r\nSe um ou mais monstros "Veda" forem Invocados por Invocação-Especial, enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode adicionar este card à sua mão. \r\nVocê só pode usar cada efeito de "Sharv Sarga" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Adicionar 1 monstro do seu Deck à sua mão?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75730490,'Ariane, a Serva de Labrinto',replace(replace('Você pode enviar para o Cemitério 1 Armadilha Normal da sua mão ou que estiver Baixada no seu campo; Invoque por Invocação-Especial 1 monstro Demônio de Nível 4 ou menos do seu Deck em Posição de Defesa, exceto "Ariane, a Serva de Labrinto". \r\nSe um ou mais outros monstros deixarem o campo pelo efeito de uma Armadilha Normal sua (exceto durante a Etapa de Dano): você pode comprar 1 card e, depois, você pode aplicar este efeito.\r\n● Da sua mão, Invoque 1 monstro Demônio por Invocação-Especial ou Baixe 1 Magia/Armadilha.	\r\nVocê só pode usar cada efeito de "Ariane, a Serva de Labrinto" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Comprar','Invocar por Invocação Especial da mão','Baixar da mão','Não fazer nada','','','','','','','','','','','');
INSERT INTO texts VALUES(75732622,'Golem Afiador',replace(replace('Não pode ser Invocado por Invocação-Normal ou Baixado. \r\nPrimeiro deve ser Invocado por Invocação-Especial (da sua mão) no lado do campo do seu oponente ao Invocar por Invocação-Especial 2 "Fichas de Triturador" (Tipo Demônio/TREVAS/Nível 1/ATK 0/DEF 0) com a face para cima em Posição de Ataque no seu lado do campo. \r\nSe você Invocar este monstro por Invocação-Especial, você não pode Invocar um monstro por Invocação-Normal ou Baixar durante o mesmo turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75732623,'Ficha de Triturador','Invocado por Especial com o efeito "Golem Afiador".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75733063,'Exército Senhormek de Skiel',replace(replace('Ganha 200 de ATK para cada monstro "Senhormek" no campo, exceto este card. \r\nQuando este card for destruído em batalha e enviado para o Cemitério: você pode Invocar por Invocação-Especial 1 monstro "Exército Senhormek" do seu Deck.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75745607,'Hino-Kagu-Tsuchi',replace(replace('Não pode ser Invocado por Invocação-Especial. \r\nDurante a Fase Final do turno em que este card for Invocado por Invocação-Normal ou virado com a face para cima: devolva-o para a mão. \r\nSe este card causar dano de batalha ao seu oponente: ele descarta toda a sua mão durante a Fase de Compra do próximo turno, antes que o duelista do turno compre.','\r',char(13)),'\n',char(10)),'Retornar à mão','Descartar da mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75748977,'XYZ - Hiper Dragão Canhão',replace(replace('"Canhão Cruz-X" + "Cabeça Yare-Y" + "Tanque Zilhão-Z"	\r\nPrimeiro deve ser Invocado por Invocação-Especial (do seu Deck Adicional) ao banir os cards acima do seu campo e/ou Cemitério. \r\nUma vez por turno do oponente (Efeito Rápido): você pode descartar 1 card e, depois, escolha 1 card que seu oponente controla; destrua-o. \r\nVocê pode banir este card do seu campo ou Cemitério e revelar 1 Monstro de Fusão Máquina de LUZ de Nível 8 no seu Deck Adicional; Invoque por Invocação-Especial até 3 das Matérias de Fusão mencionadas nele do seu Cemitério e/ou do banimento.','\r',char(13)),'\n',char(10)),'Efeito de destruição','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75771170,'Arahime, a Mikanko Manifesta',replace(replace('Você pode Invocar este card por Invocação-Ritual com "Kagura Mikanko". \r\nNão pode ser destruído em batalha e, além disso, seu oponente sofre qualquer dano de batalha que você sofreria de batalhas envolvendo este card. \r\nSe você tiver este card na sua mão ou no Cemitério e outro card "Mikanko" estiver no seu Cemitério: você pode escolher 1 monstro com a face para cima no campo; equipe este card a ele como uma Magia de Equipamento. \r\nVocê só pode usar este efeito de "Arahime, a Mikanko Manifesta" uma vez por turno. \r\nUma vez por turno, durante a Fase Final, enquanto este card estiver equipado a um monstro: você pode devolver este card e o monstro equipado para a mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75775867,'Fundan Morfotrônica',replace(replace('● Enquanto estiver em Posição de Ataque: Uma vez por turno, você pode oferecer como Tributo 1 monstro "Morfotrônico(a)", exceto "Fundan Morfotrônica", para destruir 1 card no campo.\r\n● Enquanto estiver em Posição de Defesa: Se este card seria destruído, em vez disso, você pode destruir outro monstro "Morfotrônico(a)" que você controla.','\r',char(13)),'\n',char(10)),'Destrua 1 card no campo','Destruir, em vez disso, 1 monstro cujo nome inclua "Morfotrônico(a)"?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75779210,'Épsilon Vylon',replace(replace('1 Regulador de LUZ + 1 ou mais monstros não-Reguladores	\r\nCards de Equipamento equipados a este card não podem ser escolhidos como alvo por cards ou efeitos. \r\nUma vez por turno: Você pode enviar 1 Card de Equipamento equipado a este card ao Cemitério para escolher 1 monstro que seu oponente controla; destrua o alvo.','\r',char(13)),'\n',char(10)),'Destrua 1 monstro que seu oponente controla','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75780818,'Tanque Dyna',replace(replace('1 monstro Máquina + 1 monstro Dinossauro	\r\nGanha ATK igual ao ATK original do monstro Dinossauro usado para sua Invocação-Fusão. \r\nVocê só pode usar cada um dos seguintes efeitos de "Tanque Dyna" uma vez por turno. \r\nQuando um card ou efeito for ativado que escolha este 1 card no campo como alvo (e nenhum outro card) (Efeito Rápido): você pode escolher 1 outro card no campo que seria um alvo apropriado; esse card ou efeito agora escolhe o novo alvo como alvo. \r\nSe este card em posse do seu dono for destruído por um card do oponente: você pode Invocar por Invocação-Especial 1 monstro Dinossauro do seu Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75782277,'Terreno de Caça das Harpias',replace(replace('Todos os monstros Besta Alada ganham 200 de ATK/DEF. \r\nSe qualquer "Lady Harpia" ou "Irmãs de Lady Harpia" for Invocado por Invocação-Normal ou Especial: o duelista que conduziu a Invocação escolhe 1 Magia/Armadilha no campo; esse duelista destrói o alvo.','\r',char(13)),'\n',char(10)),'Destruir Magias/Armadilhas','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75787708,'Dragão Pêndulo de Olhos Anômalos dos Quatro Dragões Celestiais',replace(replace('Escala de Pêndulo = 4\r\n[ Efeito de Pêndulo ]\r\nVocê só pode usar o Efeito de Pêndulo de "Dragão Pêndulo de Olhos Anômalos dos Quatro Dragões Celestiais" uma vez por turno.\r\nDurante sua Fase Principal: você pode destruir este card, e se fizer, adicione 1 Monstro Pêndulo com 1500 ou menos ATK do seu Deck à sua mão, também, pelo resto deste turno, a menos que você realize uma Invocação-Pêndulo após a ativação deste efeito, você não pode ativar efeitos de monstros no campo.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nEste card ganha os seguintes efeitos se foi Invocado por Invocação-Pêndulo.\r\n● Ganha ATK igual a diferença entre as Escalas Pêndulo de 2 cards na suas Zona de Pêndulo x 300.\r\n● Qualquer dano de batalha que seu oponente receba de batalhas envolvendo este card são dobrados.	\r\nSe este card na for destruído por batalha ou efeito na Zona de Monstros: você pode adiciona-lo à sua mão, então, se foi destruído pelo seu oponente, você pode Invoca-lo por Invocação-Especial. \r\nVocê só pode usar este efeito de "Dragão Pêndulo de Olhos Anômalos dos Quatro Dragões Celestiais" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Adicionar à mão','Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75787709,'Dragão Pêndulo de Olhos Anômalos dos Quatro Dragões Celestiais',replace(replace('Escala de Pêndulo = 4\r\n[ Efeito de Pêndulo ]\r\nVocê só pode usar o Efeito de Pêndulo de "Dragão Pêndulo de Olhos Anômalos dos Quatro Dragões Celestiais" uma vez por turno.\r\nDurante sua Fase Principal: você pode destruir este card, e se fizer, adicione 1 Monstro Pêndulo com 1500 ou menos ATK do seu Deck à sua mão, também, pelo resto deste turno, a menos que você realize uma Invocação-Pêndulo após a ativação deste efeito, você não pode ativar efeitos de monstros no campo.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nEste card ganha os seguintes efeitos se foi Invocado por Invocação-Pêndulo.\r\n● Ganha ATK igual a diferença entre as Escalas Pêndulo de 2 cards na suas Zona de Pêndulo x 300.\r\n● Qualquer dano de batalha que seu oponente receba de batalhas envolvendo este card são dobrados.	\r\nSe este card na for destruído por batalha ou efeito na Zona de Monstros: você pode adiciona-lo à sua mão, então, se foi destruído pelo seu oponente, você pode Invoca-lo por Invocação-Especial. \r\nVocê só pode usar este efeito de "Dragão Pêndulo de Olhos Anômalos dos Quatro Dragões Celestiais" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Adicionar à mão','Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75797046,'Rainha de Fóton Alexandra',replace(replace('2 monstros "Borbolespiã" de Nível 4	\r\nVocê pode desassociar 1 Matéria Xyz deste card; devolva todos os monstros no campo para a mão e, depois, cause 300 de dano a cada duelista para cada card devolvido para a mão dele.','\r',char(13)),'\n',char(10)),'Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75830094,'Horus, o Dragão da Chama Negra LV4',replace(replace('O controle deste card com a face para cima não pode ser trocado. \r\nDurante a Fase Final, se este card destruiu um monstro em batalha neste turno: você pode enviar este card com a face para cima para o Cemitério; Invoque por Invocação-Especial 1 "Horus, o Dragão da Chama Negra LV6" da sua mão ou Deck.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75833426,'Pausa do Chá Magidoce','Quando um Card de Magia/Armadilha for ativado, se você não tiver nenhum monstro no seu Cemitério: Negue a ativação e, se isso acontecer, devolva-o para a mão e, depois, se você controlar um "Pudincesa Magidoce" com a face para cima, você pode destruir 1 card que seu oponente controla.','Destruir 1 card que seu oponente controla?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75840616,'Bujintei Susanowo',replace(replace('2 monstros "Bujin" de Nível 4	\r\nEste card pode atacar todos os monstros que seu oponente controla uma vez cada. \r\nUma vez por turno: você pode desassociar 1 Matéria Xyz deste card; busque 1 monstro "Bujin" do seu Deck e adicione-o à sua mão ou envie-o para o Cemitério. \r\nVocê só pode controlar 1 "Bujintei Susanowo".','\r',char(13)),'\n',char(10)),'Adicionar à mão','Adicionar um monstro à sua mão?','Enviar um monstro para o Cemitério','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75850803,'LaMoon','Uma feiticeira que tira seus poderes da paisagem lunar.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75874514,'Dragão da Estrela Reluzente',replace(replace('Durante a Fase Principal do seu oponente, se este card estiver na sua mão (Efeito Rápido): você pode escolher 1 Monstro Sincro Dragão no seu Cemitério; Invoque este card por Invocação-Especial e, se isso acontecer, Invoque esse monstro por Invocação-Especial mas negue seus efeitos e, depois, imediatamente depois que este efeito resolver, você pode Invocar por Invocação-Sincro 1 Monstro Sincro Dragão usando este card que você controla. \r\nVocê só pode usar este efeito de "Dragão da Estrela Reluzente" uma vez por turno. \r\nUm monstro Dragão que foi Invocado por Invocação-Sincro usando este card como matéria não pode ser destruído em batalha.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial da mão','O efeito de "Dragão da Estrela Reluzente" está sendo aplicado.','Invocação Sincro?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75878039,'Cavaleirostélite Deneb',replace(replace('Se este card for Invocado: você pode adicionar 1 monstro "Cavaleirost" do seu Deck à sua mão, exceto "Cavaleirostélite Deneb". \r\nVocê só pode usar este efeito de "Cavaleirostélite Deneb" uma vez por turno.','\r',char(13)),'\n',char(10)),'Procurar no Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75884822,'Ojama Pijama',replace(replace('Se um ou mais monstros "Dragão Armado" e/ou um ou mais Monstros de Fusão Máquina de LUZ que você controla seriam destruídos em batalha ou por um efeito de card, em vez disso, você pode banir 1 card "Ojama" da sua mão, com a face para cima no seu campo ou do seu Cemitério. \r\nVocê só pode usar cada um dos seguintes efeitos de "Ojama Pijama" uma vez por turno.\r\n● Durante a Fase Principal: você pode adicionar 1 card "Ojama" do seu Deck à sua mão e, depois, descartar 1 card.\r\n● Se este card for enviado para o Cemitério: você pode Invocar por Invocação-Especial tantos dos seus monstros "Ojama" banidos quanto possível.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75886890,'Esfera Vylon',replace(replace('Se este card for enviado da Zona de Cards de Monstro para o Cemitério: Você pode pagar 500 PV para escolher 1 monstro com a face para cima que você controla; equipe este card ao alvo. \r\nVocê pode enviar este Card de Equipamento ao Cemitério para escolher 1 Card de Magia de Equipamento no seu Cemitério; equipe o alvo ao monstro que este card estava equipado.','\r',char(13)),'\n',char(10)),'Equipar como Card de Equipamento','Escolha 1 Card de Magia de Equipamento para equipar','Escolha 1 Card de Magia de Equipamento','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75888208,'Ikelos, a Moura do Espelho Onírico',replace(replace('Se este card for Invocado por Invocação-Especial pelo efeito de um monstro "Espelho Onírico": você pode Invocar por Invocação-Especial 1 monstro "Espelho Onírico" da sua mão, exceto "Ikelos, a Moura do Espelho Onírico". \r\nDurante a Fase Principal ou de Batalha, se "Espelho Onírico da Alegria" estiver em uma Zona do Campo (Efeito Rápido): você pode oferecer este card como Tributo; Invoque por Invocação-Especial 1 "Ikelos, a Fadinha do Espelho Onírico" do seu Deck. \r\nVocê só pode usar cada efeito de "Ikelos, a Moura do Espelho Onírico" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75889523,'Marmota Arquidemônio da Maldade','Uma marmota aérea com asas e um chifre nefasto. Ataca atirando bolotas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75892194,'Dragão do Mecanismo Antigo',replace(replace('Não pode ser Invocado por Invocação-Especial. \r\nSe você não controlar nenhum monstro, ou se todos os monstros que você controla forem monstros Máquina de TERRA, você pode Invocar este card por Invocação-Normal sem oferecer Tributo. \r\nQuando seu oponente ativar um Card de Magia/Armadilha ou seus efeitos (Efeito Rápido): você pode enviar para o Cemitério, 1 monstro Máquina da sua mão ou do campo com a face para cima, ou 1 "Golem do Mecanismo Antigo" do seu Deck; negue o efeito. \r\nVocê só pode usar este efeito de "Dragão do Mecanismo Antigo" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Normal sem Tributo','Negue 1 Card de Magia/Armadilha','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75901113,'Cavaleiro do Dragão Blindagem',replace(replace('Você pode Invocar este card por Invocação-Ritual com "Ritual do Dragão Blindagem". \r\nNo começo da Etapa de Dano, se este card batalhar um monstro que foi Invocado por Invocação-Especial do Deck Adicional: você pode embaralhar esse monstro no Deck. \r\nVocê pode oferecer este card como Tributo; Invoque por Invocação-Especial 1 monstro Dragão de VENTO de Nível 5 ou mais da sua mão ou do Deck. \r\nVocê só pode usar cada efeito de "Cavaleiro do Dragão Blindagem" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75902998,'Buraco Armadilha de Espinhos','Quando um monstro do oponente que foi Invocado por Invocação-Normal ou Especial neste turno declarar um ataque: destrua o monstro atacante e, se isso acontecer, cause dano ao seu oponente igual à metade do ATK original desse monstro.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75906310,'Dragão Armado da Catapulta Canhão',replace(replace('"VWXYZ-Dragão Catapulta Canhão" + "Dragão Armado LV7"	\r\nPrimeiro deve ser Invocado por Invocação-Especial (do seu Deck Adicional), durante um Duelo em que você tenha Invocado os dois cards acima por Invocação-Especial, ao banir os cards acima do seu campo e/ou Cemitério. \r\n(Você não usa "Polimerização".) \r\nSeu oponente não pode ativar cards ou efeitos com o mesmo nome de qualquer card banido. \r\nUma vez por turno, durante o turno do seu oponente (Efeito Rápido): você pode banir, com a face para cima, 1 card do seu Deck ou Deck Adicional; bana todos os cards que seu oponente controla e no Cemitério dele.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75917088,'Princesa Pikeru',replace(replace('Este card não pode ser Invocado por Invocação-Normal ou Baixado. \r\nEste card não pode ser Invocado por Invocação-Especial, exceto com "Julgamento das Princesas". \r\nDurante sua Fase de Apoio, ganhe 800 PV para cada monstro que você controla.','\r',char(13)),'\n',char(10)),'Ganhar PV','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75922381,'Vermelho Spright',replace(replace('Se você controlar um monstro de Nível/Link 2, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Vermelho Spright" por Invocação-Especial uma vez por turno desta forma. \r\nQuando seu oponente ativar um efeito de monstro (Efeito Rápido): você pode oferecer como Tributo 1 outro monstro de Nível/Classe/Link 2; negue esse efeito e, depois, se você ofereceu como Tributo um monstro de Classe/Link 2 para ativar este efeito, você pode destruir esse monstro. \r\nVocê só pode usar este efeito de "Vermelho Spright" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Destruir aquele monstro?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75923050,'Super Robodama',replace(replace('"Robodama" + "Roboyarou"	\r\nVocê pode Invocar "Super Roboyarou" por Invocação-Especial ao devolver este card do campo para o Deck Adicional. \r\nVocê não pode usar este efeito durante o mesmo turno em que este monstro foi Invocado por Invocação-Especial. \r\nAlém disso, aumente o ATK deste monstro em 1000 pontos durante a Etapa de Dano, quando ele causar Dano Direto aos PV do oponente.','\r',char(13)),'\n',char(10)),'Aumentar ATK','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75926389,'Carga de Energia de A a Z',replace(replace('Quando seu oponente ativar um card ou efeito: compre cards igual ao número de Monstros de Fusão Máquina de LUZ de Nível 8 ou mais que você controla. \r\nDurante sua Fase de Apoio: você pode banir este card do seu Cemitério; embaralhe no Deck até 6 dos seus monstros Máquina de LUZ banidos, incluindo um monstro União. \r\nVocê só pode usar cada efeito de "Carga de Energia de A a Z" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75937826,'B.E.S. Núcleo Grande MK-2',replace(replace('Se você não controlar nenhum monstro, você pode Invocar este card por Invocação-Normal sem oferecer Tributo. \r\nSe este card for Invocado por Invocação-Especial: coloque 3 marcadores nele. \r\nNão pode ser destruído em batalha. \r\nNo final da Etapa de Dano, se este card batalhou: remova 1 marcador deste card ou, se você não puder, destrua este card.','\r',char(13)),'\n',char(10)),'Colocar um marcador','Remova Marcadores','Destruir','Invocar sem oferecer Tributo','','','','','','','','','','','','');
INSERT INTO texts VALUES(75944053,'Robô-secretário 003',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode Invocar por Invocação-Especial 1 monstro "Robô-secretário" do seu Deck, exceto "Robô-secretário 003". \r\nUma vez por turno (Efeito Rápido): você pode escolher 1 monstro "Robô-secretário" que você controla; até o final deste turno, ele ganha 500 de ATK/DEF para cada card "Robô-secretário" que você controla atualmente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75946257,'Médico Feiticeiro do Caos',replace(replace('VIRE: Selecione 1 Card de Monstro em qualquer Cemitério. \r\nRemova-o do Duelo.','\r',char(13)),'\n',char(10)),'Banir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75952542,'Mundo Vaylantz - Konig Wissen',replace(replace('Quando este card for ativado: coloque 1 Magia de Campo "Vaylantz" do seu Deck com a face para cima na Zona do Campo do seu oponente, exceto "Mundo Vaylantz - Konig Wissen". \r\nSe houver 2 cards nas Zonas do Campo: o duelista do turno pode escolher 1 Monstro de Efeito na Zona de Monstros Principal do oponente, na mesma coluna que um dos monstros que ele controla; ele coloca esse monstro do oponente com a face para cima como uma Magia Contínua na Zona de Magias & Armadilhas dele em sua mesma coluna. \r\n(Se a zona estiver ocupada, destrua o card que a estiver ocupando.) \r\nO duelista do turno só pode usar este efeito de "Mundo Vaylantz - Konig Wissen" uma vez por turno.','\r',char(13)),'\n',char(10)),'Escolha o monstro para colocar na Zona de Magia & Armadilha','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75953262,'Guerreiro Dai Grepher','O guerreiro que pode manipular dragões. Ninguém conhece o seu misterioso passado.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75956913,'Táticas Utópicas Gagaga',replace(replace('Monstros Xyz "Utopia" e "Utópico" que você controla cujo Atributo original seja LUZ não podem ser destruídos por efeitos de card e, além disso, seu oponente não pode escolhê-los como alvo de efeitos de card. \r\nVocê só pode usar cada um dos seguintes efeitos de "Táticas Utópicas Gagaga" uma vez por turno. \r\nVocê pode declarar um Nível de 1 a 12 e, depois, escolha 2 monstros com a face para cima que você controla, incluindo um monstro "Gagaga"; eles se tornam desse Nível. \r\nSe você Invocar por Invocação-Xyz um Monstro Xyz "Utopia" ou "Utópico" cujo Atributo original seja LUZ: você pode escolher 1 card que seu oponente controla; destrua-o.','\r',char(13)),'\n',char(10)),'','Alterar o Nível','Destruir','Escolha um Nível para declarar','','','','','','','','','','','','');
INSERT INTO texts VALUES(75967082,'Curto-Circuito',replace(replace('Ative somente se você controlar 3 ou mais monstros "Homem-Bateria". \r\nDestrua todos os cards que seu oponente controla.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75983808,'Caixa Mágica do Caos',replace(replace('Quando seu oponente ativar um card ou efeito que escolha como alvo um ou mais outros cards que você controla: devolva 1 dos seus cards alvo para a mão (se estiver com a face para baixo, revele-o) e, se isso acontecer, destrua 1 card no campo e, depois, você pode Invocar por Invocação-Especial 1 monstro da sua mão que mencione "Ritual da Luz e das Trevas" com um nome diferente que o do card devolvido para a mão, ignorando suas condições de Invocação. \r\nSe este card em posse do seu dono for destruído por um card do oponente: você pode Invocar por Invocação-Especial 1 Monstro de Ritual que mencione "Ritual da Luz e das Trevas" da sua mão ou do Deck.','\r',char(13)),'\n',char(10)),'Efeito de destruição','Invocação Especial','Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75987257,'Bandoleta',replace(replace('Quando um monstro do oponente declarar um ataque: escolha o monstro atacante; coloque o alvo em Posição de Defesa e, se isso acontecer, equipe este card nesse monstro. \r\nUma vez por turno, durante a Fase Principal ou a Fase de Batalha de qualquer duelista: você pode mudar a posição de batalha do monstro equipado.','\r',char(13)),'\n',char(10)),'Mudar a posição de batalha','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75988594,'Samurai Superpesado Mestre da Espada Musashi',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nQuando este card for Invocado por Invocação-Sincro: você pode escolher 1 monstro Máquina no seu Cemitério; adicione-o à sua mão e, além disso, se você tiver uma Magia/Armadilha no seu Cemitério, pelo resto deste turno, você não pode Invocá-lo por Invocação-Normal ou Especial, nem um monstro com o seu mesmo nome. \r\nEste card pode atacar enquanto estiver com a face para cima em Posição de Defesa. \r\nSe o fizer, use sua DEF para o cálculo de dano.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75991479,'Avião de Patrulha D.D.',replace(replace('Durante a Fase Final, se este card atualmente estiver banido e foi banido neste turno: você pode banir 1 card da sua mão, do campo ou do Cemitério e, se isso acontecer, Invoque este card por Invocação-Especial em Posição de Ataque. \r\nVocê só pode usar este efeito de "Avião de Patrulha D.D." uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75991898,'Dragão Lavalval',replace(replace('1 Regulador + 1+ monstros de FOGO não-Reguladores	\r\nVocê pode embaralhar no seu Deck Principal 2 monstros "Laval" do seu Cemitério e, depois, escolha 1 card que seu oponente controla; devolva-o para a mão.','\r',char(13)),'\n',char(10)),'Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76004142,'Explosão de Má Sorte',replace(replace('Escolha 1 monstro com a face para cima que seu oponente controla; sofra dano igual à metade do ATK dele e, depois, cause dano ao seu oponente igual ao dano que você sofreu. \r\nSe este card que você controla for destruído por um card do oponente e enviado para o seu Cemitério: cause 1000 de dano ao seu oponente. \r\nVocê só pode ativar 1 "Explosão de Má Sorte" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76029419,'D/D/D Zero Maxwell, o Rei da Supervisão',replace(replace('Escala de Pêndulo = 4\r\n[ Efeito de Pêndulo ]\r\nVocê pode escolher 1 monstro com a face para cima no campo; sua DEF se torna 0 até o final deste turno (mesmo que este card deixe o campo). \r\nVocê só pode usar este efeito de "D/D/D Zero Maxwell, o Rei da Supervisão" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nAntes do cálculo de dano, se este card atacar um monstro em Posição de Defesa do oponente: você pode mudar a DEF desse monstro do oponente para 0 até o final da Etapa de Dano. \r\nSe este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante. \r\nVocê não sofre dano de batalha das batalhas envolvendo este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76039636,'Escavador da Perdição',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao banir 2 monstros Inseto do seu Cemitério. \r\nSe este card causar dano de batalha ao seu oponente: envie o card do topo do Deck dele para o Cemitério.','\r',char(13)),'\n',char(10)),'Enviar o card do topo do Deck do seu oponente para o Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76045757,'Sacrifício Negro','Quando seu oponente ativar um card ou efeito que destruiria um ou mais cards no campo: negue o efeito e, depois, envie 1 monstro de TREVAS de Nível 3 ou menos do seu Deck para o seu Cemitério.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76052811,'Helpoemer',replace(replace('Não pode ser Invocado por Invocação-Especial do Cemitério. \r\nNo final da Fase de Batalha do seu oponente, se este card estiver no Cemitério porque foi destruído em batalha: faça com que o seu oponente descarte 1 card aleatório. \r\nEste card deve estar no Cemitério para ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Descartar 1 card','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76066541,'Dragão Hidróscopo',replace(replace('Quando este card for destruído em batalha e enviado para o Cemitério ou quando este card que você controla for destruído por um efeito de card do seu oponente e enviado para o seu Cemitério: você pode Invocar por Invocação-Especial 1 Monstro Pêndulo de TERRA do seu Deck em Posição de Defesa, mas destrua-o durante a Fase Final. \r\nVocê só pode usar este efeito de "Dragão Hidróscopo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76067258,'Número 66: Besouro Chave Mestra',replace(replace('2 monstros de TREVAS de Nível 4	\r\nUma vez por turno: você pode desassociar 1 Matéria Xyz deste card e, depois, escolher 1 card que você controla, exceto este card; enquanto este card estiver com a face para cima no campo, esse outro card não pode ser destruído por efeitos de card. \r\nSe este card com a face para cima no campo seria destruído, em vez disso, você pode enviar um dos seus alvos para o Cemitério.','\r',char(13)),'\n',char(10)),'Não pode ser destruído','Usar o efeito de "Número 66: Besouro Chave Mestra" em vez de ser destruído?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76072561,'Força Celeste - Ás = Zero',replace(replace('2 monstros "Força Celeste - Ás"	\r\nVocê só pode Invocar um ou mais "Força Celeste - Ás = Zero" por Invocação-Especial uma vez por turno. \r\nNão pode ser usado como Matéria Link. \r\nSe este card for Invocado por Invocação-Especial: você pode adicionar 1 Magia "Força Celeste" do seu Deck ou Cemitério à sua mão. \r\n(Efeito Rápido): você pode oferecer este card como Tributo; Invoque por Invocação-Especial 1 "Força Celeste - Ás - Raye" e 1 "Força Celeste - Ás - Roze" do seu Deck e/ou Cemitério e, depois, você pode destruir 1 card no campo. \r\nVocê só pode usar 1 efeito de "Força Celeste - Ás = Zero" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Buscar 1 Card de Magia','Invocação Especial','Destruir o card selecionado?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76075139,'Grão-Duque Gênese Vaylantz',replace(replace('Escala de Pêndulo = 10\r\n[ Efeito de Pêndulo ]\r\nVocê pode ativar 1 desses efeitos;\r\n● Invoque este card por Invocação-Especial na sua Zona de Monstros Principal em sua mesma coluna.\r\n● Mova 1 monstro na sua Zona de Monstros Principal para uma Zona de Monstros adjacente (horizontal).	\r\nVocê só pode usar este efeito de "Grão-Duque Gênese Vaylantz" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\n2 monstros "Vaylantz"	\r\nEste card com a face para baixo no Deck Adicional primeiro deve ser Invocado por Invocação-Fusão, ou por Invocação-Especial ao oferecer como Tributo 1 monstro "Vaylantz" de Nível 5 ou mais que não seja de Fusão na mesma coluna que a Zona de Monstros Adicional. \r\nSe este card for Invocado por Invocação-Especial: você pode escolher 1 Card de Monstro na Zona de Magias & Armadilhas do seu oponente; devolva-o para a mão e, se isso acontecer, cause dano ao seu oponente igual ao seu ATK e, depois, este card ganha ATK igual à metade do dano causado.','\r',char(13)),'\n',char(10)),'Invocação Especial','Mover a posição','Escolha o monstro a mover','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76075810,'Unidade Arremessa-Pedra','Ofereça como Tributo 1 monstro do Tipo Guerreiro no seu lado do campo para destruir 1 monstro com a face para cima no campo cuja DEF seja igual ou menor que o ATK deste monstro.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76076738,'Unhas de Dragão',replace(replace('Só pode ser equipado a um monstro de TREVAS. \r\nEle ganha 600 de ATK e, além disso, ele não pode ser destruído pelos efeitos de card do seu oponente. \r\nSe este card for enviado para o Cemitério porque o monstro equipado foi destruído em batalha e enviado para o Cemitério: você pode Invocar esse monstro por Invocação-Especial e, se isso acontecer, equipe este card a ele, mas bana este card quando ele deixar o campo. \r\nVocê só pode usar este efeito de "Unhas de Dragão" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76078185,'Fobos Covos Herético',replace(replace('2 monstros de Nível 4	\r\nVocê pode escolher 1 Monstro de Efeito que seu oponente controla; negue seus efeitos e, depois, se ele batalhou neste turno, você pode tomar o controle dele até a Fase Final. \r\nEste é um Efeito Rápido se este card tiver um monstro Ilusão como matéria. \r\nVocê só pode usar este efeito de "Fobos Covos Herético" uma vez por turno. \r\nSe este card batalhar um monstro, nenhum dos dois pode ser destruído nessa batalha.','\r',char(13)),'\n',char(10)),'Negar o efeito','Tomar controle?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76080032,'ZW - Unicórnio Lança',replace(replace('Você pode escolher 1 "Número C39: Raio Utopia" que você controla; equipe este card da sua mão no alvo. \r\nEle ganha 1900 de ATK. \r\nSe o monstro equipado batalhar um monstro do oponente, os efeitos do monstro do oponente são negados, apenas durante a Fase de Batalha. \r\nVocê só pode controlar 1 "ZW - Unicórnio Lança".','\r',char(13)),'\n',char(10)),'Equipar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76103404,'Anjo Petit Ciber',replace(replace('Se este card for Invocado: você pode adicionar 1 monstro "Ciber Anjo(a)" ou "Ritual Máquina de Anjo" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Anjo Petit Ciber" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76103675,'Faíscas','Inflija 200 pontos de dano aos Life Points do seu adversário.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76133574,'Zep, o Rubi dos Ghoti',replace(replace('Você pode banir este card da sua mão e, depois, escolha 1 monstro Peixe no seu Cemitério; bana-o. \r\nDurante o turno do seu oponente, se este card for banido: você pode Invocá-lo por Invocação-Especial. \r\nSe este card for Invocado por Invocação-Especial, você pode (exceto durante a Etapa de Dano): imediatamente depois que este efeito resolver, Invocar por Invocação-Sincro 1 Monstro Sincro Peixe usando este card que você controla. \r\nVocê só pode usar cada efeito de "Zep, o Rubi dos Ghoti" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76136345,'Pátio de Manobras Giratório',replace(replace('Se um ou mais monstros Máquina de TERRA de Nível 10 forem Invocados por Invocação-Normal ou Especial no seu campo (exceto durante a Etapa de Dano): você pode ativar este efeito; seu oponente não sofre dano de batalha pelo resto deste turno (mesmo que este card deixe o campo) e, além disso, você Invoca por Invocação-Especial 1 monstro Máquina de TERRA de Nível 4 com 1800 ou mais de ATK do seu Deck, e, se isso acontecer, ele se torna de Nível 10. \r\nVocê pode enviar 1 card da sua mão para o Cemitério; adicione 1 monstro Máquina de TERRA de Nível 10 do seu Deck à sua mão. \r\nVocê só pode usar 1 efeito de "Pátio de Manobras Giratório" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76137276,'Recuperação de Magias',replace(replace('Descarte 1 card e ative este card em corrente a um Card de Magia que você ativou. \r\nQuando esse Card de Magia for enviado para o Cemitério, devolva-o para a mão do seu dono.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76137614,'Desencantadora','Uma vez por turno: você pode escolher 1 Magia com a face para cima no campo; remova 1 Marcador de Magia de qualquer lugar do campo e, se isso acontecer, devolva o alvo para a mão.','Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76145142,'Longirsu, o Orcust Orquestrador',replace(replace('2+ Monstros de Efeito, incluindo um monstro "Orcust"	\r\nEste card linkado não pode ser destruído por efeitos de card. \r\nVocê pode escolher 2 dos seus monstros Máquina banidos; embaralhe-os no Deck e, depois, você pode enviar para o Cemitério 1 monstro linkado que seu oponente controla. \r\nEste card não pode atacar no turno em que você ativar este efeito. \r\nVocê só pode usar este efeito de "Longirsu, o Orcust Orquestrador" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Enviar 1 monstro do seu oponente para o Cemitério?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76145933,'Azul Spright',replace(replace('Se você controlar um monstro de Nível/Classe 2, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Azul Spright" por Invocação-Especial uma vez por turno desta forma. \r\nSe este card for Invocado por Invocação-Especial: você pode adicionar 1 monstro "Spright" do seu Deck à sua mão, exceto "Azul Spright". \r\nVocê só pode usar este efeito de "Azul Spright" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76184692,'Gigante Hitotsu-Me','Um gigante de um só olho com braços largos e poderosos. Tenha cuidado...','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76202610,'Darklon','Quando este card for Invocado por Invocação-Normal: você pode fazer com que todos os monstros com a face para cima que você atualmente controla ganhem 1 Nível e, além disso, eles se tornam das TREVAS (esses efeitos duram até a Fase Final).','Alterar Nível/Atributo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76203291,'Peixe Dourado Voador','Você pode oferecer como Tributo 1 outro monstro do Tipo Peixe e, depois, escolher 1 card no campo; destrua o alvo.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76209339,'Emergência Megálito',replace(replace('Você pode escolher 1 monstro "Megálito" no seu Cemitério; Invoque-o por Invocação-Especial em Posição de Defesa, mas coloque-o no fundo do Deck quando ele deixar o campo (mesmo que este card deixe o campo). \r\nVocê só pode usar este efeito de "Emergência Megálito" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76211194,'Morcego Medah','Um globo ocular demoníaco criado por um servo do mal, que usa bombas negras para explodir os inimigos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76213610,'Oficial da Perdição Samuel',replace(replace('2 monstros de Nível 6	\r\nDurante a Fase Principal (Efeito Rápido): você pode desassociar 1 matéria deste card e, depois, escolha 1 monstro Zumbi no seu Cemitério; Invoque-o por Invocação-Especial e, depois, você pode negar os efeitos de 1 monstro que seu oponente controla com ATK igual ou menor que o desse monstro. \r\nSe este card for enviado para o Cemitério: você pode escolher 1 monstro em qualquer Cemitério; embaralhe-o no Deck. \r\nVocê só pode usar cada efeito de "Oficial da Perdição Samuel" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Retornar ao Deck','Negar os efeitos daquele monstro?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76214441,'Força de Vida Conciliadora','Quando seu oponente ativar um efeito de card que causa dano, você pode descartar este card para negar sua ativação e destruí-lo.','Negar o efeito','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76218313,'Notável Espada da Destruição do Dragão',replace(replace('Você pode escolher 1 "Blader Notável" que você controla; equipe este monstro da sua mão ou do campo no alvo. \r\nEnquanto este card estiver equipado a um monstro, seu oponente não pode Invocar monstros do Deck Adicional por Invocação-Especial. \r\nEnquanto este card estiver equipado a um monstro: você pode Invocar este card equipado por Invocação-Especial. \r\nVocê só pode usar este efeito de "Notável Espada da Destruição do Dragão" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76218643,'Batan Preto',replace(replace('Se você controlar um monstro Regulador com a face para cima, este card não pode ser destruído em batalha. \r\nQuando um ou mais monstros Reguladores com a face para cima que você controla forem removidos do campo, ganhe 800 PV.','\r',char(13)),'\n',char(10)),'Ganhar PV','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76224717,'Zona de Progresso',replace(replace('Uma vez por turno, durante a Fase Final de qualquer turno no qual você tenha Invocado um ou mais monstros por Invocação-Tributo: você pode aplicar esses efeitos, em sequência, de acordo com o número de monstros que você ofereceu como Tributo para Invocações-Tributo neste turno.\r\n● 1 ou mais: Destrua 1 Card Baixado que seu oponente controla.\r\n● 2 ou mais: Compre 1 card.\r\n● 3 ou mais: Adicione 1 monstro do seu Cemitério à sua mão.','\r',char(13)),'\n',char(10)),'Destrua 1 card Baixado que seu oponente controla','Compre 1 card(s)','Adicione à sua mão 1 monstro do seu Cemitério','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76232340,'Sengenjin',replace(replace('Um selvagem imparável que carrega os Itens do Milênio.	\r\n\r\n(Este card deve ser sempre considerado como um card "Milênio".)','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76232522,'Feiticeiro de Recuperação',replace(replace('2 monstros Ciberso	\r\n(Efeito Rápido): você pode escolher 1 Monstro Link Ciberso no seu Cemitério que foi destruído neste turno; Invoque-o por Invocação-Especial, mas ele tem seus efeitos negados e, além disso, destrua-o durante a Fase Final. \r\nVocê só pode usar este efeito de "Feiticeiro de Recuperação" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76263644,'Dragoon do Destino Final',replace(replace('"HERÓI do Destino - Plasma" + "HERÓI do Destino - Dogma"	\r\nA Invocação-Fusão deste card só pode ser feita com as Matérias de Fusão acima. \r\nUma vez por turno: você pode escolher 1 monstro que seu oponente controla; destrua o alvo e, se ele estava com a face para cima, cause dano ao seu oponente igual ao ATK que ele tinha no campo. \r\nVocê não pode conduzir sua Fase de Batalha no turno em que ativar este efeito. \r\nUma vez por turno, durante sua Fase de Apoio, se este card estiver no seu Cemitério: você pode banir 1 card "HERÓI do Destino" do seu Cemitério; Invoque este card por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Destruir','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76290637,'Engenhoca Marionete Maquinix Fantasix',replace(replace('2 monstros de Nível 8	\r\nVocê pode desassociar 1 matéria deste card; adicione 1 Magia "Magia de Aumento de Classe" do seu Deck à sua mão e, além disso, você pode Invocar por Invocação-Normal 1 monstro Máquina durante sua Fase Principal neste turno, em adição à sua Invocação-Normal/Baixar (padrão) (você só pode se aproveitar deste efeito uma vez por turno). \r\nSe você Invocar um ou mais Monstros Xyz "Engenhoca Marionete" por Invocação-Especial (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial do seu Cemitério em qualquer campo em Posição de Defesa e, depois, você pode adicionar 1 Magia "Magia de Aumento de Classe" do seu Cemitério à sua mão. \r\nVocê só pode usar cada efeito de "Engenhoca Marionete Maquinix Fantasix" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão 1 Card de Magia "Magia de Aumento de Classe"','Invocar por Invocação Especial do Cemitério','Invocar pelo efeito de "Engenhoca Marionete Maquinix Fantasix"','Invocar por Invocação Especial para o seu Campo','Invocar por Invocação Especial para o Campo do seu oponente','Adicionar 1 Card de Magia "Magia de Aumento de Classe" do seu Cemitério à sua mão?','','','','','','','','','','');
INSERT INTO texts VALUES(76290638,'Engenhoca Marionete Maquinix Fantasix',replace(replace('2 monstros de Nível 8	\r\nVocê pode desassociar 1 matéria deste card; adicione 1 Magia "Magia de Aumento de Classe" do seu Deck à sua mão e, além disso, você pode Invocar por Invocação-Normal 1 monstro Máquina durante sua Fase Principal neste turno, em adição à sua Invocação-Normal/Baixar (padrão) (você só pode se aproveitar deste efeito uma vez por turno). \r\nSe você Invocar um ou mais Monstros Xyz "Engenhoca Marionete" por Invocação-Especial (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial do seu Cemitério em qualquer campo em Posição de Defesa e, depois, você pode adicionar 1 Magia "Magia de Aumento de Classe" do seu Cemitério à sua mão. \r\nVocê só pode usar cada efeito de "Engenhoca Marionete Maquinix Fantasix" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão 1 Card de Magia "Magia de Aumento de Classe"','Invocar por Invocação Especial do Cemitério','Invocar pelo efeito de "Engenhoca Marionete Maquinix Fantasix"','Invocar por Invocação Especial para o seu Campo','Invocar por Invocação Especial para o Campo do seu oponente','Adicionar 1 Card de Magia "Magia de Aumento de Classe" do seu Cemitério à sua mão?','','','','','','','','','','');
INSERT INTO texts VALUES(76297408,'Demolição de Alma','Se você controlar um monstro Demônio: você pode pagar 500 PV e, depois, cada duelista escolhe 1 monstro no Cemitério do seu oponente; bana os alvos.','Banir','Usar o efeito de "Demolição de Alma" agora?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76302448,'Dispersão Arcana',replace(replace('Lance uma moeda e aplique este efeito. \r\nSe "Barreira de Luz" estiver na sua Zona do Campo, em vez disso, você pode selecionar o efeito.\r\n● Cara: Invoque por Invocação-Especial 1 monstro "Força Arcana" de Nível 4 ou menos do seu Deck.\r\n● Coroa: Invoque por Invocação-Especial 1 monstro que tenha um efeito de lançar moeda do seu Cemitério.	\r\nVocê pode banir este card do seu Cemitério; adicione 1 card do seu Cemitério à sua mão que tenha um efeito de lançar moeda. \r\nVocê só pode usar 1 efeito de "Dispersão Arcana" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Adicionar do Cemitério à mão','Com a face para cima','Com a face para baixo','','','','','','','','','','','','');
INSERT INTO texts VALUES(76305638,'O Espírito da Rocha',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro deve ser Invocado por Invocação-Especial (da sua mão) ao banir 1 monstro de TERRA do seu Cemitério. \r\nGanha 300 de ATK apenas durante a Fase de Batalha do seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76321376,'Golem da Mina','Quando este card é enviado para o Cemitério como resultado de um combate, inflija 500 pontos de dano aos Life Points do seu adversário.','Causar dano aos PV','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76334960,'Invokação - "Cálice"',replace(replace('Se você tem um monstro "Aleister" no seu campo, Cemitério ou banimento: ative 1 desses efeitos;\r\n● Invoque por Invocação-Fusão 1 Monstro Fusão "Invokado" do seu Deck Adicional, ao banir 1 monstro da sua mão ou campo e 1 monstro do seu Deck.\r\n● Invoque por Invocação-Fusão 1 Monstro Fusão "Invokado" do seu Deck Adicional, ao banir 1 monstro que você controla e 1 monstro com a face para cima que seu oponente controla.	\r\nVocê só pode ativar 1 "Invokação - "Cálice"" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar','Invocar por Invocação-Fusão usando sua mão, campo e Deck','Invocar por Invocação-Fusão usando monstros nos dois campos','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76348260,'Mimir do Ascendente Nórdico','Uma vez por turno, no começo da sua Fase de Apoio, se você controlar um monstro "Nórdic" e este card estiver no seu Cemitério: você pode enviar 1 Magia da sua mão para o Cemitério; Invoque este card por Invocação-Especial.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76352503,'Changshi, a Espiridao',replace(replace('Durante sua Fase Principal: você pode enviar para o Cemitério 1 monstro Zumbi da sua mão ou do Deck. \r\nSe este card for banido: você pode banir 1 monstro Zumbi no seu Cemitério; Invoque este card por Invocação-Especial, mas coloque-o no fundo do Deck quando ele deixar o campo. \r\nVocê só pode usar cada efeito de "Changshi, a Espiridao" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76353872,'Pássaro Defcon',replace(replace('Você pode descartar 1 outro monstro Ciberso; Invoque este card por Invocação-Especial da sua mão. \r\nVocê só pode usar este efeito de "Pássaro Defcon" uma vez por turno. \r\nUma vez por turno, quando um monstro Ciberso seu for escolhido como alvo de um ataque: você pode fazer com que seu ATK/DEF se tornem o dobro do seu ATK original e, depois, você pode colocá-lo em Posição de Defesa. \r\nEsta mudança de ATK/DEF dura até o final da Etapa de Dano.','\r',char(13)),'\n',char(10)),'Invoque este card por Invocação Especial da sua mão','Dobrar ATK','Mudar para Posição de Defesa?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76359406,'Cristron Ametrix',replace(replace('1 Regulador + 1 ou mais monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro: você pode colocar em Posição de Defesa todos os monstros com a face para cima Invocados por Invocação-Especial que seu oponente controla. \r\nSe este card Invocado por Invocação-Sincro for destruído em batalha ou por um efeito de card: você pode escolher 1 monstro "Cristron" no seu Cemitério, exceto um Monstro Sincro; Invoque-o por Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76372778,'Evigishki Merrowgeist',replace(replace('2 monstros de Nível 4	\r\nDepois do cálculo de dano, se este card destruir um monstro do oponente em batalha: você pode desassociar 1 Matéria Xyz deste card; embaralhe o monstro destruído no Deck em vez de enviá-lo para o Cemitério.','\r',char(13)),'\n',char(10)),'Retornar ao Deck o monstro destruído em batalha','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76375976,'Mina Mística',replace(replace('Se seu oponente controlar mais monstros que você, seu oponente não pode ativar efeitos de monstro ou declarar um ataque. \r\nSe você controlar mais monstros que seu oponente, você não pode ativar efeitos de monstro ou declarar um ataque. \r\nUma vez por turno, durante a Fase Final, se os dois duelistas controlarem o mesmo número de monstros: destrua este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76382116,'Dovelgus, Chefe Generaidor do Ferro',replace(replace('Você só pode controlar 1 "Dovelgus, Chefe Generaidor do Ferro". \r\n(Efeito Rápido): você pode oferecer como Tributo qualquer número de monstros "Generaidor" e/ou monstros Máquina; Invoque por Invocação-Especial, da sua mão, em Posição de Defesa, exatamente esse número de monstros "Generaidor" e/ou monstros Máquina, todos com nomes diferentes uns dos outros e dos monstros oferecidos como Tributo. \r\nVocê só pode usar este efeito de "Dovelgus, Chefe Generaidor do Ferro" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76384284,'Cavalo de Troia, Besta Gladiadora',replace(replace('Invoque por Invocação-Especial 1 monstro "Besta Gladiadora" da sua mão no lado do campo do seu oponente. \r\nDepois, compre 1 card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76403456,'Barreira de Poder','Durante o cálculo de dano, quando você sofreria dano de batalha de um monstro atacante do oponente: em vez disso, envie 1 card do topo do seu Deck para o Cemitério para cada 500 de dano (arredondado para cima) que você sofreria.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76407432,'Contra Ataque','Quando um Card de Magia/Armadilha ou efeito de monstro for ativado enquanto você controlar um monstro "/Modo de Ataque": negue a ativação e, se isso acontecer, destrua esse card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76416959,'Guerreiros Antigos - Leal Guan Yun',replace(replace('Se somente seu oponente controlar um monstro: você pode Invocar este card por Invocação-Especial da sua mão. \r\nSeu oponente não pode escolher outros monstros "Guerreiros Antigos" que você controla como alvo de efeitos de card. \r\nSe seu oponente controlar mais monstros que você: você pode escolher 1 monstro que seu oponente controla; destrua-o. \r\nVocê só pode usar este efeito de "Guerreiros Antigos - Leal Guan Yun" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76419637,'CXyz Nave de Batalha Cerejeira',replace(replace('4 monstros de Nível 4	\r\nUma vez por turno, durante a Fase Final do seu oponente, se seu oponente tiver mais cards na mão que você: ele descarta 1 card. \r\nSe este card tiver "Cruzador de Batalha Cravina" como uma Matéria Xyz, ele ganha este efeito.\r\n● Você pode desassociar 1 Matéria Xyz deste card; cause 300 de dano ao seu oponente para cada card no campo.	\r\nVocê só pode usar este efeito de "CXyz Nave de Batalha Cerejeira" uma vez por turno.','\r',char(13)),'\n',char(10)),'Descartar 1 card','Causar dano','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76436988,'Gillagillanceiro',replace(replace('Se seu oponente controlar um monstro e você não controlar nenhum monstro, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nDurante cada Fase Final: você sofre 500 de dano. \r\nEste card deve estar no campo com a face para cima para que você possa ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Receba 500 pontos de dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76442347,'Pequeno Pinguim','Quando este card for enviado do campo para o Cemitério depois de ser virado com a face para cima: escolha 1 monstro "Pinguim" no seu Cemitério, exceto "Pequeno Pinguim"; Invoque o alvo por Invocação-Especial com a face para cima em Posição de Ataque ou com a face para baixo em Posição de Defesa.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76442616,'Elo do HERÓI','Se um monstro "HERÓI" estiver no campo: Invoque por Invocação-Especial 2 monstros "HERÓI do Elemento" de Nível 4 ou menos da sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76446915,'Mago do Disco','Este monstro esconde-se num disco e só aparece para executar um ataque.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76459806,'Foguete Vulcânico','Quando este card for Invocado: você pode adicionar 1 card "Acelerador de Explosão" do seu Deck ou Cemitério à sua mão.','Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76471944,'Samurai Superpesado Ninja Sarutobi',replace(replace('1 Regulador do Tipo Máquina + 1 ou mais monstros "Samurai Superpesado" não-Reguladores	\r\nEste card pode atacar enquanto estiver com a face para cima em Posição de Defesa. \r\nSe o fizer, use sua DEF para o cálculo de dano. \r\nUma vez por turno, durante o turno de qualquer duelista, se você não tiver Cards de Magia/Armadilha no seu Cemitério: você pode escolher 1 Card de Magia/Armadilha no campo; destrua-o e, se isso acontecer, cause 500 de dano ao seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76473843,'Pégaso da Majestade',replace(replace('Todos os monstros "Majespectro" no campo ganham 300 de ATK e DEF. \r\nVocê pode oferecer como Tributo 1 monstro de VENTO do Tipo Mago; Invoque por Invocação-Especial 1 monstro "Majespectro" de Nível 4 ou menos do seu Deck. \r\nVocê só pode usar este efeito de "Pégaso da Majestade" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76500786,'Poder Estelar!',replace(replace('Durante o cálculo de dano, se um Monstro Link seu batalhar um monstro do oponente: seu monstro ganha ATK igual à soma dos Níveis/Classes dos monstros para os quais ele apontar x 400, apenas durante o cálculo de dano. \r\nVocê só pode ativar 1 "Poder Estelar!" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76504386,'Número 39: Utopia, o Emissário da Luz',replace(replace('2 monstros de Nível 4	\r\nNão pode ser destruído por batalha, exceto com um monstro "Número". \r\n(Efeito Rápido): você pode desassociar 1 matéria deste card, então escolha 1 monstro que você controla; a primeira vez que ele seria destruído por batalha ou por efeito neste turno, ele não é destruído.\r\nQuando o segundo ataque deste turno é declarado: você pode fazer este card ganhar 2500 ATK, e se fizer, ele ganha este efeito.\r\n● Quando este card destrói um monstro por batalha e o envia para o Cemitério: você pode Invoca-lo para o seu campo por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Proteção contra destruição','Aumentar ATK','Invocação Especial','Efeito já ativado','','','','','','','','','','','','');
INSERT INTO texts VALUES(76504387,'Número 39: Utopia, o Emissário da Luz',replace(replace('2 monstros de Nível 4	\r\nNão pode ser destruído por batalha, exceto com um monstro "Número". \r\n(Efeito Rápido): você pode desassociar 1 matéria deste card, então escolha 1 monstro que você controla; a primeira vez que ele seria destruído por batalha ou por efeito neste turno, ele não é destruído.\r\nQuando o segundo ataque deste turno é declarado: você pode fazer este card ganhar 2500 ATK, e se fizer, ele ganha este efeito.\r\n● Quando este card destrói um monstro por batalha e o envia para o Cemitério: você pode Invoca-lo para o seu campo por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Proteção contra destruição','Aumentar ATK','Invocação Especial','Efeito já ativado','','','','','','','','','','','','');
INSERT INTO texts VALUES(76512652,'Krokodilus','Um crocodilo cruel de grande intelecto.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76515293,'Xing Zhen Hu',replace(replace('Escolha 2 Cards de Magia ou Armadilha Baixados no Campo para activar este card. \r\nEnquanto este card permanecer no Campo, os Cards de Magia ou Armadilha escolhidos não podem ser activados.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76520646,'Escuridão Infinita',replace(replace('Este card é considerado como um Monstro Normal enquanto estiver com a face para cima no campo ou no Cemitério. \r\nEnquanto este card estiver com a face para cima no campo, você pode Invocá-lo por Invocação-Normal para fazer com que ele seja considerado como um Monstro de Efeito com este efeito:\r\n● Quando este card declarar um ataque, você pode mudar a posição de batalha de 1 monstro com a face para cima que seu oponente controla.','\r',char(13)),'\n',char(10)),'Mudar a posição de batalha','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76524506,'Flora da Rosa do Jardim',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nVocê pode escolher 1 card na Zona do Campo; destrua-o e, depois, Invoque por Invocação-Especial no campo do seu controlador, 1 "Ficha de Rosa" (Planta/TREVAS/Nível 2/ATK 800/DEF 800) em Posição de Ataque e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto Monstros Sincro. \r\nVocê só pode usar este efeito de "Flora da Rosa do Jardim" uma vez por turno. \r\nUma vez por Corrente, durante a Fase Principal do seu oponente, você pode (Efeito Rápido): imediatamente depois que este efeito resolver, Invoque por Invocação-Sincro usando este card que você controla.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76524507,'Ficha de Rosa','Invocado por Especial com o efeito "Jardim Negro" ou um card relacionado.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76532077,'Areias Movediças Sem Fundo',replace(replace('No fim do turno do seu adversário, destrói o(s) monstro(s) no Campo com a face para cima com o maior ATK. \r\nDurante a sua própria Standby Phase, se você tiver 4 ou menos cards na sua mão, este card é destruído.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76539047,'Presas Envenenadas','Cada vez que um monstro do Tipo Besta inflige dano de combate aos Life Points do seu adversário, inflija 500 pontos de dano aos Life Points do seu adversário.','Causar dano aos PV','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76543119,'Engenhoca Marionete Des Truir',replace(replace('Uma vez enquanto estiver com a face para cima no campo: você pode escolher 1 monstro "Engenhoca Marionete" no campo; destrua-o. \r\nQuando este card for enviado do campo para o Cemitério: você pode Invocar por Invocação-Especial 1 ou 2 monstros "Engenhoca Marionete" da sua mão.','\r',char(13)),'\n',char(10)),'Destruir','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76547525,'Wivern Vermelha',replace(replace('1 Regulador + 1 ou mais monstros não-Reguladores	\r\nDurante o turno de qualquer duelista, se um monstro com ATK maior que o deste card Invocado por Invocação-Sincro estiver no campo: você pode destruir o 1 monstro com a face para cima no campo com o maior ATK (em caso de empate, você seleciona). \r\nEste efeito só pode ser usado uma vez enquanto este card estiver com a face para cima no campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76548531,'Terror Umbral Gorgônico',replace(replace('Você não pode Invocar por Invocação-Especial do seu Deck Adicional, exceto Monstros Xyz "Número".\r\nVocê só pode usar cada um dos seguintes efeitos de "Terror Umbral Gorgônico" uma vez por turno.\r\nSe você não controla monstros, ou todos os monstros que você controla são monstros "Terror Umbral": você pode Invocar por Invocação-Especial este card da sua mão, e se fizer, adicione 1 monstro "Terror Umbral" não-Rocha do seu Deck à sua mão.\r\nPode ser considerado como 2 matérias para a Invocação-Xyz de um Monstro Xyz "Número" que precise de 3 ou mais matérias.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76552147,'D.D.D. - Derby de uma Dimensão Diferente','Se você controlar um monstro com a face para cima que foi Invocado por Invocação-Ritual usando um Monstro Normal, ou foi Invocado por Invocação-Fusão, Sincro, Xyz ou Link usando um Monstro Normal como matéria: você pode escolher 1 card no campo; bana-o.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76573247,'Infiltrador Alienígena',replace(replace('Uma vez por turno, este card pode ser movido para uma Zona de Cards de Monstro adjacente (horizontal) não ocupada. \r\nSe nenhum Card de Monstro, Magia ou Armadilha no lado do campo do oponente estiver na mesma coluna deste card, ele pode atacar o oponente diretamente.','\r',char(13)),'\n',char(10)),'Mover para outra Zona','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76587747,'Ladrão do Tempo Inverso',replace(replace('Quando um Card de Magia/Armadilha for ativado enquanto você controlar um Monstro Xyz "Ladrão do Tempo": negue a ativação e, se isso acontecer, associe esse card a um Monstro Xyz "Ladrão do Tempo" que você controla como matéria. \r\nVocê só pode ativar 1 "Ladrão do Tempo Inverso" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76589546,'Dragão da Abundância',replace(replace('Quando um ou mais monstros no campo forem destruídos por um efeito de card (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão e, depois, se 2 ou mais monstros no campo foram destruídos por esse efeito de card, você pode Invocar por Invocação-Especial 1 "Ficha de Abundância" (Dragão/TREVAS/Nível 1/ATK 0/DEF 0). \r\nVocê só pode usar este efeito de "Dragão da Abundância" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Invocar uma Ficha por Invocação Especial?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76589547,'Ficha de Abundância','Invocada por Invocação-Especial com o efeito "Dragão da Abundância".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76589815,'Boxeador Obstinado Comissário Impostor',replace(replace('2 monstros de Nível 3	\r\nTodos os monstros que seu oponente controla devem atacar, se possível. \r\nEnquanto você controlar outro monstro "Boxeador Obstinado", os monstros do seu oponente não podem escolher este card como alvo de ataques. \r\nQuando um ataque for declarado envolvendo outro monstro "Boxeador Obstinado" que você controla: você pode desassociar 2 matérias deste card; olhe a mão do seu oponente e, depois, Baixe 1 Magia da mão dele no seu campo.','\r',char(13)),'\n',char(10)),'Revelar sua mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76593718,'Ganância na Jarra',replace(replace('VIRE: Aplique esses efeitos em sequência.\r\n● Escave qualquer número de cards do topo do seu Deck, até o número de cards que seu oponente controla e, se isso acontecer, adicione 1 deles à sua mão e, além disso, envie o resto para o Cemitério.\r\n● Envie monstros do seu Deck Adicional para o Cemitério, até o número de monstros que seu oponente controla que foram Invocados por Invocação-Especial do Deck Adicional.	\r\nVocê só pode usar este efeito de "Ganância na Jarra" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Escolha a quantidade de cards a revelar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76614003,'Funileiro das Trevas',replace(replace('Quando este card que você controla for enviado para o Cemitério, olhe o card do topo do seu Deck. \r\nDevolva esse card para o topo ou fundo do Deck.','\r',char(13)),'\n',char(10)),'Revelar o Deck','Colocar no topo do Deck','Retornar ao fundo do Deck','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76614340,'Cavaleiro-Gema Rubi',replace(replace('"Cavaleiro-Gema Granada" + 1 monstro "Cavaleiro-Gema"	\r\nPrimeiro deve ser Invocado por Invocação-Fusão com as Matérias de Fusão acima. \r\nUma vez por turno: você pode oferecer como Tributo 1 outro monstro "-Gema" com a face para cima; até o final deste turno, este card ganha ATK igual ao ATK que esse monstro oferecido como Tributo tinha no campo. \r\nSe este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76615300,'Hiita, a Canalizadora do Fogo',replace(replace('(Este card deve ser sempre considerado como um card "Encantador(a)".)	\r\nVocê pode descartar este card e 1 outro monstro de FOGO; adicione 1 monstro de FOGO do seu Deck à sua mão com ATK maior que o do outro monstro descartado e, além disso, você não pode ativar os efeitos de monstros que não sejam de FOGO pelo resto deste turno. \r\nQuando um monstro de FOGO seu for destruído em batalha: você pode Invocar este card por Invocação-Especial da sua mão. \r\nVocê só pode usar cada efeito de "Hiita, a Canalizadora do Fogo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76630812,'Dado Caveira Gracioso',replace(replace('Role um dado duas vezes e aplique esses efeitos, em sequência, pelo resto deste turno.\r\n● Monstros que você controla que mencionam "Mago do Tempo Sombrio" ganham ATK/DEF igual ao total x 200.\r\n● Monstros que seu oponente controla perdem ATK/DEF igual ao total x 200.	\r\nSe seu oponente Invoca um ou mais monstros por Invocação-Normal ou Especial enquanto este card está no seu Cemitério: você pode banir este card, então escolha 1 daqueles monstros; role um dado duas vezes, e se o total for 6 ou mais, destrua aquele monstro.','\r',char(13)),'\n',char(10)),'Ativar','Rolar um dado','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76634149,'Kairyu-Shin','Este dragão marinho, conhecido como Rei do Oceano, ataca seus inimigos com enormes maremotos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76636978,'Dragão da Poeira Estelar - Vítima do Santuário',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nQuando seu oponente ativar um card ou efeito em resposta a ativação do seu card ou efeito (Efeito Rápido): você pode oferecer como este card como Tributo; negue o efeito daquele oponente, e se fizer, destrua aquele card.\r\nSe um ou mais dos seus monstros foram oferecidos como Tribudo desta forma (Efeito Rápido): você pode banir este card do seu Cemitério; Invoque 1 Monstro Sincro "Poeira Estelar" do seu Deck Adicional por Invocação-Especial.\r\nVocê só pode usar cada efeito de "Dragão da Poeira Estelar - Vítima do Santuário" uma vez por turno, você também não pode ativa-los na mesma Corrente.','\r',char(13)),'\n',char(10)),'Negar a ativação','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76636979,'Dragão da Poeira Estelar - Vítima do Santuário',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nQuando seu oponente ativar um card ou efeito em resposta a ativação do seu card ou efeito (Efeito Rápido): você pode oferecer como este card como Tributo; negue o efeito daquele oponente, e se fizer, destrua aquele card.\r\nSe um ou mais dos seus monstros foram oferecidos como Tribudo desta forma (Efeito Rápido): você pode banir este card do seu Cemitério; Invoque 1 Monstro Sincro "Poeira Estelar" do seu Deck Adicional por Invocação-Especial.\r\nVocê só pode usar cada efeito de "Dragão da Poeira Estelar - Vítima do Santuário" uma vez por turno, você também não pode ativa-los na mesma Corrente.','\r',char(13)),'\n',char(10)),'Negar a ativação','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76641981,'TG1-EM1','Escolha 1 monstro que seu oponente controla e 1 monstro "T.G." que você controla; troque o controle dos dois monstros.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76647978,'Ultra Polimerização',replace(replace('Pague 2000 PV; Invoque por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional, usando 2 monstros que você controla como Matérias de Fusão. \r\nNenhum duelista pode ativar cards ou efeitos em resposta à ativação deste card. \r\nVocê pode banir este card do seu Cemitério e, depois, escolher 1 Monstro de Fusão que foi Invocado por Invocação-Fusão pelo efeito deste card; Invoque por Invocação-Especial do seu Cemitério todas as Matérias de Fusão usadas para sua Invocação-Fusão, mas mude o ATK/DEF delas para 0 e, além disso, elas tem seus efeitos negados.','\r',char(13)),'\n',char(10)),'Invocação Fusão','Invocar Materiais de Fusão por Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76650663,'Anulador, Aliado da Justiça','Se este card batalhar um monstro de LUZ, depois do cálculo de dano: negue os efeitos desse monstro (incluindo no Cemitério).','Negar efeitos','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76660178,'O Pescador, a Lenda do Mar',replace(replace('Se seu oponente ativar um efeito de monstro no campo, ou quando o monstro dele declara um ataque, e "Umi" ou outro card que menciona "Mago do Tempo Sombrio" além do "O Pescador, a Lenda do Mar" está no campo: você pode Invocar este card da sua mão por Invocação-Especial.\r\nSe este card for Invocado por Invocação-Especial: você pode escolher 1 monstro que seu oponente controla; destrua-o, também retorne este card no campo para a mão durante a Fase Final deste turno.\r\nVocê só pode usar cada um dos efeitos de "O Pescador, a Lenda do Mar" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76660409,'Volta do Pêndulo','Se você tiver 2 cards nas suas Zonas de Pêndulo: escolha 2 monstros no seu Cemitério, cada um deles com um Nível entre (não incluindo) a Escala de Pêndulo dos cards nas suas Zonas de Pêndulo; adicione-os à sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76666602,'O Dragão que Devora o Dogma',replace(replace('"Caído de Arbaz" + 1 monstro de LUZ ou de TREVAS + 1 Monstro de Efeito	\r\nEnquanto um monstro "Ecclesia" estiver no campo ou em qualquer Cemitério, este card ganha 500 de ATK e, além disso, ele não é afetado por outros efeitos de cards. \r\nVocê só pode usar cada um dos seguintes efeitos de "O Dragão que Devora o Dogma" uma vez por turno. \r\nSe este card for Invocado por Invocação-Especial: você pode embaralhar no Deck até 2 cards de quaisquer Cemitérios e/ou banimento. \r\nDurante a Fase Final, se este card estiver no Cemitério porque foi enviado para lá neste turno: você pode adicionar 1 card "Dogmatika" ou "Tri-Brigada" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Retornar ao Deck','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76672730,'Arquivos do Mundo Negro',replace(replace('Durante sua Fase Principal: você pode descartar 1 monstro "Mundo Negro" e, se isso acontecer, até o final deste turno, monstros "Mundo Negro" que você controla atualmente ganham ATK igual ao Nível que o monstro descartado tinha na mão x 100. \r\nSe um monstro cujo Tipo original seja Demônio for descartado da sua mão pelo efeito de um card "Mundo Negro" ou por um efeito de card do oponente, mesmo durante a Etapa de Dano: você pode descartar 1 card e, depois, compre 2 cards. \r\nVocê só pode usar cada efeito de "Arquivos do Mundo Negro" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76683171,'Lombriga Horrendo','Quando você Invocar por Invocação-Tributo um monstro "Lombriga" do Tipo Réptil ao oferecer este card como Tributo, você pode Invocar este card por Invocação-Especial do seu Cemitério no lado do campo do oponente, com a face para cima em Posição de Ataque.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76685519,'Altergeist Kidolga',replace(replace('2 monstros "Altergeist"	\r\nQuando outro monstro "Altergeist" que você controla causar dano de batalha ao seu oponente: você pode escolher 1 monstro no Cemitério dele; Invoque-o por Invocação-Especial em uma zona sua para a qual este card apontar, mas a cada turno, ele não pode atacar a não ser que este card já tenha declarado um ataque nesse turno. \r\nSe este card for destruído em batalha: você pode escolher 1 card "Altergeist" no seu Cemitério; adicione-o à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76704943,'Pergaminho de Dragão Yamatano','Um dragão conjurado a partir do mesmo pergaminho no qual estava representado.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76714458,'Feitiço da Dor','Quando seu oponente ativar um card ou efeito que causaria dano de efeito a você: em vez disso, seu oponente sofre o dano de efeito desse card ou efeito.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76721030,'Desgraça do Tirano',replace(replace('Ofereça 2 monstros como Tributo. \r\nEfeitos de Monstros de Efeito que são ativados na mão ou no campo não podem ser ativados.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76722334,'Conchápsula',replace(replace('Você só pode usar 1 dos seguintes efeitos de "Conchápsula" por turno e apenas uma vez por turno.\r\n● Se este card for oferecido como Tributo: você pode comprar 1 card.\r\n● Se este card for usado como matéria para uma Invocação-Fusão, Sincro ou Link: você pode comprar 1 card.\r\n● Se este card for desassociado de um Monstro Xyz para ativar um efeito desse monstro: você pode comprar 1 card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76725398,'Magatama de Mitsurugi',replace(replace('Durante a Fase Principal: ative 1 desses efeitos;\r\n● Ofereça como Tributo 1 monstro Réptil e, depois, escolha 1 card com a face para cima que seu oponente controla; destrua-o.\r\n● Invoque por Invocação-Ritual 1 Monstro de Ritual "Mitsurugi" da sua mão, ao oferecer como Tributo monstros que você controla cuja soma dos Níveis seja igual ou exceda seu Nível.	\r\nVocê só pode ativar 1 "Magatama de Mitsurugi" por turno.','\r',char(13)),'\n',char(10)),'Ativar','Destruir','Invocação Ritual','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76728962,'Dragão Revólver Pistoleiro',replace(replace('Se um ou mais monstros Máquina de TREVAS com a face para cima que você controla forem destruídos em batalha ou por um efeito de card: você pode Invocar este card por Invocação-Especial da sua mão. \r\nUma vez por turno, durante a Fase de Batalha (Efeito Rápido): você pode lançar uma moeda 3 vezes; destrua monstros com a face para cima no campo, até o número de caras e, depois, se o resultado foi 3 caras, compre 1 card. \r\nEste card não pode atacar no turno em que este efeito for ativado. \r\nSe este card for enviado para o Cemitério: você pode adicionar, do seu Deck à sua mão, 1 monstro de Nível 7 ou menos que tenha um efeito de lançar moeda.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76751255,'Recarregar Cavaleirardor',replace(replace('Revele qualquer número de Monstros Pêndulo da sua mão e embaralhe-os no Deck e, depois, compre cards igual ao número de cards que você embaralhou no Deck +1. \r\nPelo resto deste turno depois que este card resolver, você não pode comprar cards por efeitos de card. \r\nVocê só pode ativar 1 "Recarregar Cavaleirardor" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76754619,'Energia da Pirâmide',replace(replace('Você pode escolher e ativar 1 dos seguintes efeitos:\r\n● Aumentar o ATK de todos os monstros no seu Campo com a face para cima em 200 pontos até à End Phase.\r\n● Aumentar a DEF de todos os monstros no seu Campo com a face para cima em 500 pontos até à End Phase.','\r',char(13)),'\n',char(10)),'Aumentar ATK em 200','Aumente a DEF em 500','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76763417,'Ginasta Cibernético','Uma vez por turno: você pode descartar 1 card e, depois, escolha 1 monstro em Posição de Ataque que seu oponente controla; destrua o alvo.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76766706,'Semente do Caos',replace(replace('Se você controlar monstros tanto de LUZ como de TREVAS OU um monstro que tenha LUZ e TREVAS em seus Atributos: você pode escolher 1 dos seus monstros banidos de LUZ ou de TREVAS do Tipo Guerreiro; adicione-o à sua mão. \r\nVocê só pode ativar 1 "Semente do Caos" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76774528,'Dragão de Restolhos',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nUma vez por turno: você pode escolher 1 card que você controla e 1 card que seu oponente controla; destrua-os. \r\nQuando este card em sua posse for destruído por um card do seu oponente e enviado para o seu Cemitério: escolha 1 monstro "Restolhos" que não seja Sincro no seu Cemitério; Invoque o alvo por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Destruir','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76775123,'Robô Patrulha','Durante sua Fase de Apoio, você pode olhar 1 card com a face para baixo Baixado pelo seu oponente, desde que este card permaneça com a face para cima no campo.','Revelar um card Baixado','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76782778,'Dragãozela Enfarremei',replace(replace('Não pode ser destruído por efeitos de card enquanto você controlar um Monstro de Fusão. \r\nVocê só pode usar cada um dos seguintes efeitos de "Dragãozela Enfarremei" uma vez por turno.\r\n● (Efeito Rápido): você pode descartar este card; Invoque por Invocação-Especial 1 monstro "Dragãozela" de Nível 4 ou menos da sua mão.\r\n● No final da Fase de Batalha: você pode devolver este card para a mão e, se isso acontecer, Invoque por Invocação-Especial 1 monstro "Dragãozela" de Nível 2 da sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76792184,'Ritual de Magia Negra',replace(replace('Este card é usado para a Invocação-Ritual de "Mago do Caos das Trevas". \r\nVocê também deve oferecer como Tributo monstros da sua mão ou do campo cuja soma dos Níveis seja igual a 8 ou mais.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76794549,'Feiticeiro Astrógrafo',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nDurante sua Fase Principal: você pode destruir este card e, se isso acontecer, pegue 1 "Mago Observador das Estrelas" da sua mão ou do Deck e coloque-o na sua Zona de Pêndulo ou Invoque-o por Invocação-Especial. \r\nVocê só pode usar este efeito de "Feiticeiro Astrógrafo" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe um ou mais cards que você controla forem destruídos em batalha ou por um efeito de card: você pode Invocar este card por Invocação-Especial da sua mão e, depois, você pode selecionar 1 monstro no Cemitério, Deck Adicional ou que estiver banido, que tenha sido destruído neste turno, e adicionar 1 monstro com o mesmo nome do seu Deck à sua mão. \r\nVocê pode banir este card que você controla, mais 4 monstros da sua mão, do campo e/ou do Cemitério (1 de cada com "Dragão Pêndulo", "Dragão Xyz", "Dragão Sincro" e "Dragão Fusão" em seus nomes); Invoque por Invocação-Especial 1 "Rei Supremo Z-ARC" do seu Deck Adicional. \r\n(Isso é considerado uma Invocação-Fusão.)','\r',char(13)),'\n',char(10)),'Destruir este card','Colocar na Zona de Pêndulo','Invocação Especial','Invoque este card por Invocação Especial da sua mão','Adicionar à sua mão um monstro com o mesmo nome do monstro destruído?','Invoque "Rei Supremo Z-ARC" por Invocação Fusão','Escolha 1 "Mago Observador das Estrelas"','Escolha 1 monstro destruído neste turno','','','','','','','','');
INSERT INTO texts VALUES(76798740,'Investida Vendorror',replace(replace('Envie 1 monstro Zumbi da sua mão ou com a face para cima do seu campo para o Cemitério; Invoque por Invocação-Especial 1 monstro "Vendorror" do seu Deck. \r\nVocê só pode ativar 1 "Investida Vendorror" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76806714,'Juramento da Tartaruga',replace(replace('Este card é usado para a Invocação-Ritual de "Tartaruga Caranguejo". \r\nVocê também deve oferecer como Tributo monstros da sua mão ou do campo cuja soma dos Níveis seja igual a 8 mais.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76812113,'Lady Harpia','Este animal alado com forma humana, embora agrade aos olhos, é absolutamente letal em batalha.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76815942,'Lirilusc - Rouxinol Independente',replace(replace('"Lirilusc - Rouxinol Construído" + 1 monstro "Lirilusc"	\r\nSe este card for Invocado por Invocação-Fusão usando um Monstro Xyz no campo como Matéria de Fusão cujo nome original inclua "Lirilusc": você pode aumentar o Nível deste card pelo número de Matérias Xyz que esse(s) monstro(s) tinha(m). \r\nEste card ganha ATK igual ao seu próprio Nível x 500. \r\nNão é afetado por outros efeitos de cards. \r\nUma vez por turno: você pode causar dano ao seu oponente igual ao Nível deste card x 500.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76821171,'Duralume, a Consagração Pagã Vaalmônica',replace(replace('1 Monstro de Efeito	\r\nNão pode ser Invocado por Invocação-Link a não ser que você tenha 3 ou mais Marcadores de Ressonância em um ou mais Cards de Monstro Fada na sua Zona de Pêndulo. \r\nVocê só pode Invocar "Duralume, a Consagração Pagã Vaalmônica" por Invocação-Especial uma vez por turno. \r\nSe este card for Invocado por Invocação-Link: você pode escolher monstros que seu oponente controla, até o número de Marcadores de Ressonância na sua Zona de Pêndulo; destrua-os. \r\nVocê pode remover 3 Marcadores de Ressonância da sua Zona de Pêndulo; este card pode realizar até 3 ataques durante cada Fase de Batalha neste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76823930,'Oferenda Fomedeira',replace(replace('Durante sua Fase Principal: você pode pagar 1000 PV; você pode conduzir até 3 Invocações-Normal/Baixar neste turno, não apenas 1. \r\nDurante a Fase de Batalha do seu oponente: você pode pagar 500 PV; imediatamente depois que este efeito resolver, Invoque 1 monstro por Invocação-Normal. \r\nVocê só pode usar cada efeito de "Oferenda Fomedeira" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76830505,'Trator Brutal Infinisteira',replace(replace('Você pode oferecer como Tributo 1 monstro Máquina de TERRA; Invoque este card por Invocação-Especial da sua mão em Posição de Defesa. \r\nSe este card for Invocado por Invocação-Especial da mão, você pode: Invocar por Invocação-Especial 1 monstro "Infinisteira" do seu Deck em Posição de Defesa, exceto "Trator Brutal Infinisteira", mas negue seus efeitos e, além disso, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros Máquina de TERRA. \r\nVocê só pode usar cada efeito de "Trator Brutal Infinisteira" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76833149,'Melffy Mommy',replace(replace('2+ monstros Besta de Nível 2	\r\nUma vez por turno (Efeito Rápido): você pode associar 1 monstro Besta da sua mão ou do campo com a face para cima a este card como matéria. \r\nEste card ganha efeitos de acordo com o número de matérias associadas a ele.\r\n● 3+: Não pode ser destruído em batalha.\r\n● 4+: Você não sofre dano das batalhas envolvendo este card.\r\n● 5+: Quando um ataque for declarado envolvendo este card e um monstro em Posição de Ataque: você pode causar dano ao seu oponente igual ao ATK desse monstro em Posição de Ataque.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76840111,'Alma do Rei Celestial Supremo',replace(replace('Ofereça como Tributo 1 Monstro Pêndulo Mago com 2500 de ATK original; Invoque por Invocação-Fusão 1 "Rei Supremo Z-ARC" do seu Deck Adicional ao banir as Matérias de Fusão mencionadas nele da sua mão, do Deck, do Deck Adicional, do campo e/ou do Cemitério, mas negue seus efeitos a não ser que pelo menos 1 de cada dos seus monstros "Dragão Pêndulo", "Dragão Xyz", "Dragão Sincro" e "Dragão Fusão" estejam atualmente banidos. \r\nVocê só pode ativar 1 "Alma do Rei Celestial Supremo" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76848240,'Área da Não Agressão',replace(replace('Você pode activar este card apenas durante a sua Standby Phase. \r\nDescarte 1 card da sua mão. \r\nO seu adversário não pode Invocar, por Invocação-Normal, ou Invocação-Especial, nem Baixar durante o próximo turno do seu adversário.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76862289,'Dragão Yamata',replace(replace('Este card não pode ser Invocado por Invocação-Especial. \r\nEste card é devolvido para a mão do seu dono durante a Fase Final do turno em que for Invocado por Invocação-Normal ou virado com a face para cima. \r\nQuando este card causar dano de batalha ao seu oponente, compre cards até ter 5 cards na sua mão.','\r',char(13)),'\n',char(10)),'Retornar à mão','Comprar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76865611,'Lanternan Morfotrônica',replace(replace('● Enquanto estiver em Posição de Ataque: Qualquer dano de efeito que você sofreria de um efeito de card do oponente, em vez disso, é causado ao seu oponente.\r\n● Enquanto estiver em Posição de Defesa: Quando este card for destruído em batalha e enviado para o Cemitério, você não sofre Dano de Batalha neste turno.','\r',char(13)),'\n',char(10)),'O dano de batalha se torna 0','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76869711,'Konkon Rikka',replace(replace('Se você controlar um monstro "Rikka": você pode Baixar 1 Magia/Armadilha "Rikka" diretamente do seu Deck na sua Zona de Magias & Armadilhas e, além disso, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros Planta. \r\nVocê só pode usar este efeito de "Konkon Rikka" uma vez por turno. \r\nUma vez por turno, se você fosse oferecer como Tributo um monstro Planta que você controla para ativar um card ou efeito "Rikka", você pode oferecer como Tributo qualquer 1 monstro com a face para cima que seu oponente controla, mesmo que você não o controle.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76871889,'Noites Vendorror',replace(replace('Você pode descartar 1 card; adicione 1 monstro "Vendorror" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Noites Vendorror" uma vez por turno. \r\nQuando um monstro "Vendorror" seu destruir um monstro do oponente em batalha: você pode banir 1 monstro "Vendorror" do seu Cemitério; ele pode atacar um monstro do oponente novamente em seguida.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76891401,'Gishilnodon, Dragão Senhor do Mar',replace(replace('1 Regulador + 1 monstro não-Regulador de Nível 3	\r\nQuando um monstro de Nível 3 ou menos com a face para cima no campo for enviado para o Cemitério, o ATK deste card se torna 3000 até a Fase Final deste turno.','\r',char(13)),'\n',char(10)),'O ATK se torna 3000','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76895648,'Máquina Perigosa Tipo 6',replace(replace('Durante cada uma das suas Fases de Apoio: lance um dado de 6 faces e aplique o resultado.\r\n● 1: Descarte 1 card.\r\n● 2: Seu oponente descarta 1 card.\r\n● 3: Compre 1 card.\r\n● 4: Seu oponente compra 1 card.\r\n● 5: Destrua 1 monstro que seu oponente controla.\r\n● 6: Destrua este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76902476,'Besta Fantasma Mecha Tartaruga Rastreadora',replace(replace('O Nível deste card aumenta em um valor igual à soma dos Níveis de todas as "Fichas de Besta Fantasma Mecha" que você controla. \r\nEnquanto você controlar uma Ficha, este card não pode ser destruído em batalha ou por efeitos de card. \r\nA cada turno, a primeira "Ficha de Besta Fantasma Mecha" que você controla que seria destruída em batalha não é destruída.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76908448,'Cavaleiro-Gema Cristal','Um Cavaleiro-Gema de alta patente, que aperfeiçoou o uso dos poderes de cristal. Apesar de sua habilidade de subjugar a maioria dos oponentes, ele não quer mais se esforçar tanto, e opta por ser solidário com seus camaradas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76909279,'Touro Guerreiro Enfurecido','Se um monstro Besta, Besta-Guerreira ou Besta Alada seu atacar um monstro em Posição de Defesa, ele causa dano de batalha perfurante.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76913983,'Asanegra Armado',replace(replace('1 Regulador "Asanegra" + 1+ monstros não-Reguladores	\r\nSe este card atacar um monstro em Posição de Defesa, ele ganha 500 de ATK apenas durante a Etapa de Dano e, além disso, cause dano de batalha perfurante ao seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76922029,'Dom Zaloog',replace(replace('Quando este card causar dano de batalha ao seu oponente: você pode ativar 1 desses efeitos;\r\n● Descarte 1 card aleatório da mão dele.\r\n● Envie os 2 cards do topo do Deck dele para o Cemitério.','\r',char(13)),'\n',char(10)),'Ativar 1 efeito','Seu oponente descarta 1 card aleatório.','Envie os 2 cards do topo do Deck do seu oponente para o Cemitério.','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76925842,'Cavaleiro das Trevas Parshath',replace(replace('Se este card destruir um monstro do oponente em batalha: Você pode banir 1 monstro de TREVAS do seu Cemitério; compre 1 card. \r\nEste card ganha 100 de ATK para cada monstro de TREVAS no seu Cemitério.','\r',char(13)),'\n',char(10)),'Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76930964,'Ninja do Crepúsculo Getsuga, o Shogun',replace(replace('Você pode Invocar este card por Invocação-Tributo ao oferecer como Tributo 1 monstro "Ninja". \r\nSe este card estiver em Posição de Ataque: você pode escolher 2 monstros "Ninja" no seu Cemitério, exceto "Ninja do Crepúsculo Getsuga, o Shogun"; coloque este card em Posição de Defesa e, se isso acontecer, Invoque esses monstros por Invocação-Especial. \r\nVocê só pode usar este efeito de "Ninja do Crepúsculo Getsuga, o Shogun" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ofereça 1 monstro "Ninja" como Tributo para Invocar por Tributo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76937326,'Daigusto Laplampilica',replace(replace('1 Regulador + 1+ monstros "Gusto" não-Reguladores	\r\nVocê só pode Invocar "Daigusto Laplampilica" por Invocação-Especial uma vez por turno. \r\nSe este card for Invocado por Invocação-Sincro: você pode Invocar por Invocação-Especial 1 monstro "Gusto" da sua mão e 1 monstro "Gusto" do seu Deck, mas negue seus efeitos e, depois, imediatamente depois que este efeito resolver, Invoque por Invocação-Sincro 1 Monstro Sincro "Gusto" usando apenas esses 2 monstros e, além disso, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros de VENTO. \r\nSeu oponente não pode escolher outro Monstro Sincro "Gusto" que você controla como alvo de efeitos de card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76948970,'Mitsurugi no Miko, Wousu',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) ao oferecer como Tributo 1 outro monstro Réptil da sua mão e 1 monstro que seu oponente controla, mas você não pode Invocar por Invocação-Especial nem ativar efeitos de monstro pelo resto deste turno, exceto monstros Réptil. \r\nVocê só pode Invocar "Mitsurugi no Miko, Wousu" por Invocação-Especial uma vez por turno desta forma. \r\nSe este card for oferecido como Tributo: você pode descartar 1 card e, se isso acontecer, adicione este card à sua mão. \r\nVocê só pode usar este efeito de "Mitsurugi no Miko, Wousu" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Retornar para a mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76972801,'Gagagaguarda','Se você controlar 2 ou mais monstros "Gagaga": neste turno, monstros que você controla não podem ser destruídos em batalha ou por efeitos de card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76978105,'HERÓI Maligno Ginete Infernal',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 "Fusão Negra" do seu Deck ou Cemitério à sua mão. \r\nVocê pode banir este card e 4 outros monstros do seu Cemitério; Baixe 1 "Super Polimerização" do seu Deck e, além disso, você não pode Invocar por Invocação-Especial (exceto monstros "HERÓI"), mas pode Invocar por Invocação-Fusão monstros que devem ser Invocados por Invocação-Especial com "Fusão Negra", usando o efeito de outros cards. \r\nEsses efeitos duram até o final do turno do seu oponente. \r\nVocê só pode usar cada efeito de "HERÓI Maligno Ginete Infernal" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar "Fusão Negra" à mão','Baixar "Super Polimerização"','','O efeito de "HERÓI Maligno Ginete Infernal" está sendo aplicado.','','','','','','','','','','','','');
INSERT INTO texts VALUES(76981308,'Competição de Encarar Melffy',replace(replace('Você pode revelar 1 monstro Besta na sua mão; adicione 1 monstro "Melffy" com um nome diferente do seu Deck ou Cemitério à sua mão e coloque esse monstro revelado no fundo do Deck. \r\nVocê só pode usar este efeito de "Competição de Encarar Melffy" uma vez por turno. \r\nNo começo da Fase de Batalha do seu oponente: você pode revelar qualquer número de monstros "Melffy" na sua mão e mantê-los revelados apenas durante esta Fase de Batalha. \r\nOs monstros que seu oponente controla perdem ATK igual ao ATK e DEF combinados dos monstros revelados por este efeito.','\r',char(13)),'\n',char(10)),'','','Escolha 1 monstro para revelar','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76986005,'Ciberkirin','Você pode oferecer este card como Tributo para reduzir a 0 qualquer dano de efeito que você sofreria neste turno.','Não sofrer dano de efeito','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76990617,'Sonata, a Diva Melodiosa',replace(replace('Se você controlar um monstro "Melodiosa(o)", você pode Invocar este card por Invocação-Especial (da sua mão). \r\nEnquanto este card Invocado por Invocação-Especial estiver no campo, todos os monstros do Tipo Fada que você controla ganham 500 de ATK e DEF.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77007920,'Armadura Canhão Laser',replace(replace('Só pode ser equipado a um monstro Inseto. \r\nEle ganha 300 de ATK/DEF.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77013169,'Samurai Superpesado Espadachim',replace(replace('Quando este card for Invocado por Invocação-Normal ou Especial: você pode mudar a posição de batalha dele. \r\nSe um monstro "Samurai Superpesado" que você controla batalhar um monstro do oponente, depois do cálculo de dano: o ATK e DEF do monstro do oponente se tornam 0.','\r',char(13)),'\n',char(10)),'Mudar a posição de batalha','Alterar ATK/DEF','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77027445,'Poder de Kaishin',replace(replace('Só pode ser equipado a um monstro Aqua. \r\nEle ganha 300 de ATK/DEF.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77036039,'Mercenário de Ataque','Uma vez por turno: você pode embaralhar no Deck 1 "Ativar Modo de Ataque" da sua mão ou do Cemitério e, depois, escolha 1 Magia/Armadilha que seu oponente controla; destrua o alvo.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77044671,'Tartaruga Pirâmide','Quando este card for destruído em batalha e enviado para o Cemitério: você pode Invocar por Invocação-Especial 1 monstro Zumbi com 2000 ou menos de DEF do seu Deck.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77058170,'Receptor Underclock',replace(replace('2 Monstros de Efeito	\r\nUma vez por turno: você pode escolher 1 monstro com a face para cima para o qual este card apontar e 1 monstro com a face para cima que seu oponente controla; até o final deste turno, o monstro alvo do oponente perde ATK igual ao ATK do alvo para o qual este monstro apontar.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77060848,'Svartalf do Alfar Nórdico','Quando este card for Invocado por Invocação-Normal: você pode escolher 1 monstro "Nórdic" no seu Cemitério; adicione o alvo à sua mão.','Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77066768,'Scanner de Cards',replace(replace('Uma vez por turno: você pode declarar 1 tipo de card (Monstro, Magia ou Armadilha); os dois duelistas revelam o card do fundo dos seus Decks e, se era do tipo de card declarado, ele o adiciona à sua mão. \r\nCaso contrário, ele o coloca no topo do Deck dele. \r\nSe este card com a face para cima na Zona de Magias & Armadilhas do seu dono for destruído por um efeito de card do oponente: você pode fazer com que seu oponente coloque 1 card da mão dele no fundo do Deck.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77075360,'Velocista Sucata',replace(replace('1 Regulador "Sincron" + 1+ monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro: você pode Invocar por Invocação-Especial tantos Reguladores "Sincron" quanto possível com Níveis diferentes do seu Deck, em Posição de Defesa. \r\nVocê não pode Invocar por Invocação-Especial do Deck Adicional, exceto Monstros Sincro, no turno em que ativar este efeito. \r\nQuando um ataque for declarado envolvendo este card que foi Invocado por Invocação-Sincro neste turno e outro monstro: até o final deste turno, você pode fazer com que o ATK deste card se torne o dobro do seu ATK original. \r\nVocê só pode usar cada efeito de "Velocista Sucata" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77084837,'Inaba, o Coelho Branco',replace(replace('Este card não pode ser Invocado por Invocação-Especial. \r\nEste card é devolvido para a mão do seu dono durante a End Phase do turno em que é Invocado, por Invocação-Normal, ou é virado com a face para cima. \r\nEste monstro ataca os Life Points do seu adversário diretamente.','\r',char(13)),'\n',char(10)),'Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77087109,'Ressonador do Relógio','Uma vez por turno, este card com a face para cima em Posição de Defesa não pode ser destruído em batalha ou por efeitos de card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77092311,'Tsuchigumo, o Mayakashi Venenoso',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nVocê só pode controlar 1 "Tsuchigumo, o Mayakashi Venenoso". \r\nVocê só pode usar cada um desses efeitos de "Tsuchigumo, o Mayakashi Venenoso" uma vez por turno.\r\n● Se um Monstro Sincro em sua posse, cujo Nível original seja 7, for destruído em batalha ou por um efeito de card do oponente enquanto este card estiver no Cemitério: você pode banir 1 outro monstro Zumbi no seu Cemitério e, se isso acontecer, Invoque este card por Invocação-Especial.\r\n● Se este card for Invocado por Invocação-Especial do Cemitério: você pode fazer com que cada duelista envie os 3 cards do topo do seu Deck para o Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77098449,'Onda da Galáxia','Cada vez que você Invocar por Invocação-Xyz: Cause 500 de dano ao seu oponente.','Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77102944,'Utensilhor Lavandragão',replace(replace('1 monstro "Utensilhor"	\r\nNão pode ser usado como Matéria Link no turno em que for Invocado por Invocação-Link. \r\nNenhum duelista sofre qualquer dano de batalha dos ataques envolvendo este card. \r\nUma vez por turno, depois do cálculo de dano, se este card co-linkado batalhar um monstro do oponente: você pode banir o monstro do oponente. \r\nUma vez por turno, depois do cálculo de dano, se este monstro que não estiver co-linkado batalhar um monstro do oponente: você pode destruir esse monstro do oponente e, se isso acontecer, cause dano ao seu oponente igual ao ATK original dele.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77103950,'Planeta Primordial Perlereino',replace(replace('Quando este card for ativado: você pode adicionar 1 monstro "Lagrimentiara" ou 1 "Visas Starfrost" do seu Deck à sua mão. \r\nMonstros de Fusão e monstros "Lagrimentiara" que você controla ganham 500 de ATK. \r\nSe um ou mais monstros "Lagrimentiara" que você controla ou no seu Cemitério forem embaralhados no Deck ou Deck Adicional (exceto durante a Etapa de Dano): você pode escolher 1 card no campo; destrua-o. \r\nVocê só pode usar este efeito de "Planeta Primordial Perlereino" uma vez por turno. \r\nVocê só pode ativar 1 "Planeta Primordial Perlereino" por turno.','\r',char(13)),'\n',char(10)),'Adicionar 1 monstro do seu Deck à sua mão?','Destruir um card no Campo','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77116346,'Carga Dinonévoa',replace(replace('Quando este card for ativado: adicione 1 monstro "Dinonévoa" do seu Deck à sua mão. \r\nUma vez por turno, se um ou mais cards "Dinonévoa" forem adicionados do campo ao seu Deck Adicional com a face para cima: adicione 1 desses cards à sua mão. \r\nVocê só pode ativar 1 "Carga Dinonévoa" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77121851,'Mantícora das Trevas','Durante a Fase Final, se este card estiver no Cemitério porque foi enviado para lá neste turno: você pode enviar 1 monstro Besta, Besta-Guerreira ou Besta Alada da sua mão ou do campo com a face para cima para o Cemitério; Invoque este card por Invocação-Especial do seu Cemitério.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77124096,'Contato Negro',replace(replace('Ative 1 desses efeitos (mas você só pode usar cada efeito de "Contato Negro" uma vez por turno);\r\n● Invoque por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional que deve ser Invocado por Invocação-Especial com "Fusão Negra", ao embaralhar no Deck suas matérias do seu campo, Cemitério e/ou banimento. \r\n(Isso é considerado uma Invocação-Fusão com "Fusão Negra".)\r\n● Adicione 1 "Castelo do Rei Supremo" ou "Fusão Negra" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Ativar','Invocar por Invocação Fusão como se "Fusão Negra" tivesse sido usado','Adicionar à mão','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77133792,'Ímã de Conversão',replace(replace('Escolha até 3 monstros "Guerreiro Ímã" de Nível 4 ou menos no seu Cemitério; adicione-os à sua mão. \r\nDurante o turno de qualquer duelista, exceto no turno em que este card foi enviado para o Cemitério: você pode banir este card do seu Cemitério e, depois, escolha 1 dos seus monstros "Guerreiro Ímã" de Nível 4 ou menos banidos; Invoque-o por Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77135531,'Vanguarda do Dragão',replace(replace('Você pode enviar 1 monstro Dragão da sua mão para o Cemitério; este card ganha 300 de ATK. \r\nQuando este card que você controla for enviado para o seu Cemitério por um efeito de card do oponente: você pode escolher 1 Monstro Normal Dragão em qualquer Cemitério; Invoque o alvo por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Aumentar ATK','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77150143,'Briolâmina Zoodíaco',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode descartar 1 card "Zoodíaco(a)" e, se isso acontecer, compre 1 card. \r\nUm Monstro Xyz cujo Tipo original seja Besta-Guerreira e que tenha este card como Matéria Xyz ganha este efeito.\r\n● Se este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente.','\r',char(13)),'\n',char(10)),'Descarte 1 card "Zoodíaco(a)"; compre 1 card','Dano perfurante (Briolâmina Zoodíaco)','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77152542,'Asanegra - Harmattan, a Poeira',replace(replace('Se você controlar um monstro "Asanegra" que não seja "Asanegra - Harmattan, a Poeira", você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Asanegra - Harmattan, a Poeira" por Invocação-Especial uma vez por turno desta forma. \r\nQuando este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 outro monstro "Asanegra" que você controla; aumente o Nível deste card pelo Nível desse monstro.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77153811,'Djinn, o Praguejador de Rituais',replace(replace('Quando você Invocar um monstro por Invocação-Ritual, você pode banir este card do seu Cemitério como 1 dos monstros necessários para a Invocação-Ritual. \r\nEnquanto o monstro Invocado por Invocação-Ritual usando este card estiver com a face para cima no campo, os efeitos dos Monstros Sincro são negados.','\r',char(13)),'\n',char(10)),'O efeito de "Djinn, o Praguejador de Rituais" está sendo aplicado.','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77157846,'Sombra, o Obscuro',replace(replace('Escala de Pêndulo = 11\r\n[ Efeito de Pêndulo ]\r\nVocê não pode Invocar por Invocação-Pêndulo, exceto Monstros Pêndulo (este efeito não pode ser negado). \r\nSe um ou mais monstros com 1000 ou menos de ATK forem Invocados por Invocação-Especial (exceto durante a Etapa de Dano): você pode devolver este card para a mão. \r\nVocê só pode usar este efeito de "Sombra, o Obscuro" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe você tiver um card na sua Zona de Pêndulo e este card estiver na sua mão: você pode Invocar este card por Invocação-Especial. \r\nVocê pode pagar 1000 PV; destrua 1 Card de Monstro Pêndulo na sua mão ou no campo com a face para cima e, depois, você pode adicionar 1 Monstro Pêndulo do seu Deck ao seu Deck Adicional com a face para cima. \r\nVocê só pode usar cada efeito de "Sombra, o Obscuro" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Retornar para a mão','Invocação Especial','Destruir','Adicionar este card ao Deck Adicional?','Escolha o card para adicionar ao Deck Adicional','','','','','','','','','','');
INSERT INTO texts VALUES(77189532,'Foguette Codificador',replace(replace('Se este card seria usado para a Invocação-Link de um monstro "Callibre", você pode considerar este card como um Dragão. \r\nVocê só pode usar cada um dos seguintes efeitos de "Foguette Codificador" uma vez por turno. \r\nSe um monstro Ciberso que você controla seria usado como Matéria Link para um monstro "Codificar Transmissor", este card na sua mão também pode ser usado como matéria. \r\nSe este card que você controla seria usado como Matéria Link para um monstro "Callibre", 1 monstro de TREVAS na sua mão também pode ser usado como matéria.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77202120,'Sincron de Assalto',replace(replace('Durante sua Fase Principal: você pode Invocar este card por Invocação-Especial da sua mão e, depois, sofra 700 de dano e, além disso, enquanto ele estiver com a face para cima na Zona de Monstros, você não pode Invocar por Invocação-Especial do Deck Adicional, exceto Monstros Sincro. \r\nSe um ou mais Monstros Sincro Dragão com a face para cima que você controla forem oferecidos como Tributo ou banidos (exceto durante a Etapa de Dano): você pode banir este card do seu Cemitério e, depois, escolha 1 desses monstros; Invoque-o por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Sincron de Assalto" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77205367,'Número C96: Tempestade Negra',replace(replace('4 monstros de TREVAS de Nível 3	\r\nEste card não pode ser destruído em batalha e, além disso, todo dano de batalha que você sofrer de batalhas envolvendo este card também é causado ao seu oponente. \r\nSe este card tiver "Número 96: Névoa Obscura" como uma Matéria Xyz, ele ganha este efeito.\r\n● Uma vez por batalha, durante o turno de qualquer duelista, quando um ataque for declarado envolvendo este card e um monstro do oponente: você pode desassociar 1 Matéria Xyz deste card; o ATK do monstro do oponente se torna 0 e, se isso acontecer, este card ganha ATK igual ao ATK original do monstro do oponente.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77207191,'Berfomet','Quando este card for Invocado por Invocação-Normal ou Virar: você pode adicionar 1 "Gazelle, o Rei das Bestas Místicas" do seu Deck à sua mão.','Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77229910,'Campo de Força Morfotrônico',replace(replace('Negue a ativação de um Card de Magia ou Armadilha que destruiria um monstro "Morfotrônico(a)" com a face para cima que você controla e destrua-o. \r\nAdicione 1 card "Morfotrônico(a)" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77235086,'Ciber Anja Benten',replace(replace('Você pode Invocar este card por Invocação-Ritual com "Ritual Máquina de Anjo". \r\nSe este card destruir um monstro em batalha e enviá-lo para o Cemitério: cause dano ao seu oponente igual à DEF original desse monstro no Cemitério. \r\nSe este card for oferecido como Tributo: você pode adicionar 1 monstro Fada de LUZ do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77252217,'Inseto Motosserra','Se este card batalhou, no final da Etapa de Dano: seu oponente compra 1 card.','Seu oponente compra 1 card','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77297908,'Palco do Abismo - Teatro Fantástico',replace(replace('Você pode revelar 1 Monstro Pêndulo "Ator do Abismo" e 1 Magia "Script do Abismo" na sua mão; adicione 1 Magia "Script do Abismo" do seu Deck à sua mão, com um nome diferente que a Magia revelada. \r\nEnquanto você controlar um Monstro Pêndulo "Ator do Abismo" Invocado por Invocação-Pêndulo, qualquer efeito de monstro ativado pelo seu oponente se torna "Destrua 1 Magia/Armadilha Baixada que seu oponente controla". \r\nVocê só pode usar cada efeito de "Palco do Abismo - Teatro Fantástico" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77307161,'Trapestrela Florescente',replace(replace('1 monstro "Trapestrela" de Nível 2 ou menos	\r\nSe este card for Invocado por Invocação-Link: você pode fazer com que seu oponente compre 1 card. \r\nSe um monstro "Trapestrela" com a face para cima para o qual este card apontar for destruído em batalha ou por um efeito de card: você pode causar 200 de dano ao seu oponente para cada card na mão dele. \r\nVocê só pode usar este efeito de "Trapestrela Florescente" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77312273,'Concha do Caos',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial por um efeito de card. \r\nSe este card com a face para cima deixaria o campo, em vez disso, bana-o. \r\nVocê só pode usar cada um dos seguintes efeitos de "Concha do Caos" uma vez por turno. \r\nVocê pode banir 1 monstro de LUZ da sua mão ou do Cemitério; Invoque este card por Invocação-Especial da sua mão e, além disso, você não pode Invocar monstros por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto Monstros Sincro de LUZ ou de TREVAS. \r\nSe este card for Invocado por Invocação-Especial: você pode escolher 1 dos seus "Núcleo Feito de Caos" banidos; Invoque-o por Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77313225,'Rciela, a Alma Sinistra da Floresta Branca',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Especial: você pode enviar 1 Magia/Armadilha da sua mão ou do campo para o Cemitério; adicione 1 card "Floresta Branca" ou 1 monstro Mago de LUZ do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Rciela, a Alma Sinistra da Floresta Branca" uma vez por turno. \r\nMonstros Sincro Ilusão e Mago que você controla ganham 500 de ATK e, além disso, eles não podem ser destruídos pelos efeitos de card do seu oponente.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Aumentar ATK e obter proteção contra destruição','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77330185,'Sabre-XX Garsem',replace(replace('Ganha 200 de ATK para cada monstro "Sabre-X" que você controla. \r\nSe este card no campo for destruído por um efeito de card e enviado para o Cemitério: adicione 1 monstro "Sabre-X" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77334267,'Arsenal Zenmaioh de Corda',replace(replace('2 monstros de Nível 5	\r\nUma vez por turno: você pode desassociar 1 matéria deste card e, depois, escolha 2 cards Baixados no campo; destrua-os.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77336644,'Dragão Vermelho Arquidemônio/Modo de Ataque',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial com "Ativar Modo de Ataque". \r\nDepois do cálculo de dano, se este card atacou: destrua todos os outros monstros no campo. \r\nQuando este card no campo for destruído: você pode escolher 1 "Dragão Vermelho Arquidemônio" no seu Cemitério; Invoque o alvo por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Destruir','Invocação Especial','Invocar "Dragão Vermelho Arquidemônio" por Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77360173,'Ressonador de Sinkron',replace(replace('Se um Monstro Sincro estiver no campo, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Ressonador de Sinkron" por Invocação-Especial uma vez por turno desta forma. \r\nSe este card for enviado do campo para o Cemitério: você pode escolher 1 monstro "Ressonador" no seu Cemitério, exceto "Ressonador de Sinkron"; adicione-o à sua mão.','\r',char(13)),'\n',char(10)),'Invocação Especial','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77363314,'Dragão de Kristal','Uma vez por turno, durante sua Etapa de Batalha, se este card batalhou neste turno: você pode adicionar 1 monstro do Tipo Dragão de Nível 8 do seu Deck à sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77372241,'Flamvell Grunika','Se este card destruir um monstro em batalha e enviá-lo para o Cemitério: cause dano ao seu oponente igual ao Nível original do monstro destruído x 200.','Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77379481,'Samurai Sasuke nº 3','Quando este card causar dano de batalha ao seu oponente, seu oponente compra cards até que sua mão tenha 7 cards.','Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77384395,'Quebrazuzu',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno: você pode escolher 1 card na sua outra Zona de Pêndulo; até o final deste turno, a Escala de Pêndulo deste card se torna o Nível desse Card de Monstro Pêndulo e, além disso, você não pode Invocar por Invocação-Especial pelo resto deste turno, exceto por Invocação-Pêndulo.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nA Invocação-Pêndulo dos seus monstros não pode ser negada.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77387463,'Vulcão Dragni, o Rei Cúbico',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro deve ser Invocado por Invocação-Especial (da sua mão) ao enviar 2 monstros "Cúbico(a)" que você controla para o Cemitério. \r\nSe Invocado desta forma, este card ganha 1600 de ATK. \r\nSe este card for Invocado por Invocação-Especial da mão: cause 800 de dano ao seu oponente. \r\nNo final da Etapa de Dano, se este card batalhou: você pode escolher até 3 "Vijam, a Semente Cúbica" no seu Cemitério; envie este card para o Cemitério e, se isso acontecer, Invoque-os por Invocação-Especial e, depois, você pode adicionar 1 "Indiora Volt Mortal, o Imperador Cúbico" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Adicionar 1 "Indiora Volt Mortal, o Imperador Cúbico" à sua mão?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77392987,'T.G. Salamandra Foguete',replace(replace('Você pode oferecer como Tributo 1 monstro "T.G."; Invoque por Invocação-Especial 1 monstro "T.G." do seu Deck com um nome original diferente que o do monstro oferecido como Tributo. \r\nSe você controlar um monstro Máquina "T.G.": você pode escolher 1 monstro "T.G." de Nível 4 ou menos no seu Cemitério; Invoque-o por Invocação-Especial em Posição de Defesa, mas negue seus efeitos. \r\nVocê só pode usar cada efeito de "T.G. Salamandra Foguete" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial do Deck','Invocar por Invocação Especial do Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77402960,'Chamado Numeron','Se "Rede Numeron" estiver na sua Zona do Campo e você não controlar nenhum monstro: Invoque por Invocação-Especial até 4 Monstros Xyz "Portão Numeron" com nomes diferentes do seu Deck Adicional, mas bana-os durante a Fase Final e, além disso, você só pode Invocar por Invocação-Normal ou Especial uma vez pelo resto deste turno.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77406972,'Giltia, o Cavaleiro D. - Lança da Alma',replace(replace('Se você não controlar nenhum monstro, você pode Invocar este card por Invocação-Normal sem oferecer Tributo. \r\nQuando este card for Invocado por Invocação-Normal: você pode banir 1 monstro que seu oponente controla com ATK igual ou maior que o deste card. \r\nVocê pode descartar 1 card; adicione 1 dos seguintes monstros do seu Deck à sua mão.\r\n● Dragão de TREVAS de Nível 7\r\n● Máquina de TREVAS de Nível 6\r\n● Guerreiro de ÁGUA de Nível 5\r\nVocê só pode usar este efeito de "Giltia, o Cavaleiro D. - Lança da Alma" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Normal sem Tributo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77411244,'Dragonete do Banimento B',replace(replace('Uma vez por turno, você pode: escolher 1 monstro Máquina de LUZ que você controla; equipe este card no alvo, OU: desequipe este card e Invoque-o por Invocação-Especial. \r\nUm monstro equipado com este card não é afetado pelos efeitos de Magia do seu oponente e, além disso, se o monstro equipado seria destruído em batalha ou por um efeito de card, em vez disso, destrua este card. \r\nSe este card for enviado do campo para o Cemitério: você pode adicionar 1 monstro União do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Equipar','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77414722,'Bloqueador de Magia','Quando um Card de Magia for ativado: descarte 1 card; negue a ativação e, se isso acontecer, destrua-o.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77421977,'Sombra I.A.',replace(replace('Ative este card ao escolher 1 monstro "@Ignister" que você controla. \r\nEsse monstro ganha 800 de ATK e, além disso, todos os monstros que seu oponente controla devem atacar esse monstro que você controla, se possível. \r\nSe este card com a face para cima na Zona de Magias & Armadilhas do seu dono deixou o campo devido a um efeito do oponente e agora estiver no Cemitério ou banido: compre 1 card. \r\nVocê só pode usar este efeito de "Sombra I.A." uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77428945,'Terreno Dentado Tsuchinoko',replace(replace('Quando este card for Invocado por Invocação-Especial: coloque todos os outros monstros Invocados por Invocação-Especial no campo com a face para baixo em Posição de Defesa. \r\nVocê só pode usar o efeito de "Terreno Dentado Tsuchinoko" uma vez por turno.','\r',char(13)),'\n',char(10)),'Mudar para Posição de Defesa com a face para baixo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77432167,'Unificação do Deus Sol',replace(replace('Se você controlar um monstro cujo nome original seja "O Dragão Alado de Rá", você pode ativar este card no turno em que ele foi Baixado. \r\nDurante a Fase Principal: você pode pagar PV até restarem apenas 100; 1 "O Dragão Alado de Rá" Invocado por Invocação-Especial que você controla ganha ATK/DEF igual à quantidade de PV pagos (mesmo que este card deixe o campo). \r\nUma vez por turno: você pode oferecer como Tributo 1 "O Dragão Alado de Rá"; ganhe PV igual ao ATK dele no campo. \r\nVocê não pode ativar os dois efeitos deste card na mesma Corrente.','\r',char(13)),'\n',char(10)),'Aumentar ATK','Recuperar PV','Ativar aplicando o efeito de "Unificação do Deus Sol".','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77435268,'Verificador',replace(replace('Não pode ser Invocado por Invocação-Normal se você controlar um monstro. \r\nVocê pode oferecer este card como Tributo; Invoque por Invocação-Especial 1 monstro Máquina do seu Deck cujo ATK seja igual à sua própria DEF, mas devolva-o para a mão durante a Fase Final. \r\nVocê pode banir este card do seu Cemitério e descartar 1 card; Invoque por Invocação-Especial 1 "Ficha de Entulho de Ferro" (Máquina/TERRA/Nível 1/ATK 0/DEF 0), mas ela não pode ser usada como matéria para uma Invocação-Fusão, Sincro ou Link. \r\nVocê só pode usar cada efeito de "Verificador" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Invocação Especial','Invocar uma Ficha por Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77435269,'Ficha de Entulho de Ferro','Invocado por Invocação-Especial pelo efeito de "Checker".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77449773,'Cinet Varredura Cruzada','Ofereça como Tributo 1 monstro Ciberso e, depois, escolha 1 card no campo; destrua-o.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77454922,'Juramento da Baleia Fortaleza',replace(replace('Este card é usado para a Invocação-Ritual de "Baleia Fortaleza". \r\nVocê também deve oferecer como Tributo monstros da sua mão ou do campo cuja soma dos Níveis seja igual a 7 ou mais.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77456448,'Espada Destruidora de Magia',replace(replace('Ative 1 desses efeitos;\r\n● Destrói todas as Magias com a face para cima que seu oponente controla.\r\n● Escolha 1 monstro com a face para cima que seu oponente controla; mostre 1 "Ritual da Luz e das Trevas" da sua mão ou Cemitério, então altere o ATK do monstro para 0, também negue seus efeitos.	\r\nSe este card na posse de seu dono é destruído por um card do oponente: você pode destruir 1 card na mão do seu oponente (aleatoriamente) ou campo.\r\nVocê só pode ativar 1 "Espada Destruidora de Magia" por turno.','\r',char(13)),'\n',char(10)),'Ativar','Destruir todos os Cards de Magia com a face para cima que seu oponente controla','O ATK do monstro alvo se torna 0 e seus efeitos são negados','Destruir 1 card na mão ou no campo do seu oponente','Escolha aleatoriamente 1 card na mão do seu oponente para destruir','Escolha 1 card que o seu oponente controla para destruir','','','','','','','','','','');
INSERT INTO texts VALUES(77456781,'Kraken-Demônio','Uma lula gigante que arrasta seus inimigos para um túmulo aquático.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77462146,'Os Cavaleiros Fantasmas do Véu Sombrio',replace(replace('Escolha 1 monstro com a face para cima que você controla; ele ganha 300 de ATK/DEF. \r\nQuando um monstro do oponente declarar um ataque direto enquanto este card estiver no seu Cemitério: Invoque este card por Invocação-Especial em Posição de Defesa como um Monstro Normal (Guerreiro/TREVAS/Nível 4/ATK 0/DEF 300).	\r\n(Este card NÃO é considerado como uma Armadilha.) \r\nSe Invocado desta forma, bana este card quando ele deixar o campo.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial como Monstro Normal','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77482666,'Guerreiro Pantera Veloz',replace(replace('Não pode declarar ataque a menos que um ou mais monstros foram oferecidos como Tributo neste turno.\r\nDurante a Fase Principal (Efeito Rápido): você pode oferecer como Tributo 1 outro monstro da sua mão ou campo, então ative 1 desses efeitos (você só pode usar este efeito de "Guerreiro Pantera Veloz" uma vez por turno);\r\n● Invoque por Invocação-Especial 1 monstro que mencione "Mago do Tempo Sombrio" da sua mão ou Deck, exceto "Guerreiro Pantera Veloz".\r\n● Envie 1 Magia/Armadilha que mencione "Mago do Tempo Sombrio" do seu Deck para o Cemitério.','\r',char(13)),'\n',char(10)),'Ativar o efeito','','Invocação Especial','Enviar para o Cemitério','','','','','','','','','','','','');
INSERT INTO texts VALUES(77491079,'Lagarto Gale','VIRE: Escolha 1 monstro que seu oponente controla; devolva o alvo para a mão.','Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77498348,'Soldado do Lustro Negro - Enviado do Anoitecer do Crepúsculo',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao banir todos os monstros de LUZ ou todos os monstros de TREVAS do seu Cemitério, enquanto você tiver um mesmo número de cada um deles no seu Cemitério. \r\nEnquanto estiver com a face para cima no campo, este card também é do Atributo LUZ. \r\nQuando este card for Invocado por Invocação-Especial: você pode ativar o efeito apropriado, de acordo com o Atributo dos monstros banidos para a Invocação-Especial. \r\nVocê não pode conduzir sua Fase de Batalha no turno em que ativar este efeito.\r\n● LUZ: Escolha 1 monstro no campo; bana-o.\r\n● TREVAS: Até a Fase Final do seu oponente, bana, com a face para baixo, 1 card aleatório da mão do seu oponente.','\r',char(13)),'\n',char(10)),'Banir 1 monstro de LUZ','Banir 1 monstro de TREVAS','Banir','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77505534,'Jogos Sombrios Sinistros','Envie 1 card "Sombraneco" do seu Deck para o Cemitério e, depois, você pode colocar qualquer número de monstros "Sombraneco" com a face para baixo em Posição de Defesa que você controla, com a face para cima em Posição de Defesa.','Mudar um monstro "Sombraneco" em Posição de Defesa com a face para baixo para Posição de Defesa com a face para cima?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77506119,'Unicórnio do Trovão',replace(replace('1 Regulador do Tipo Besta + 1 ou mais monstros não-Reguladores	\r\nUma vez por turno, durante sua Fase Principal, você pode selecionar 1 monstro com a face para cima que seu oponente controla. \r\nEle perde 500 de ATK para cada monstro que você controla até a Fase Final. \r\nDurante o turno em que este efeito for ativado, nenhum outro monstro pode atacar, exceto este card.','\r',char(13)),'\n',char(10)),'Reduzir ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77511331,'Espírito do Caratê Kuro-Obi',replace(replace('Escala de Pêndulo = 9\r\n[ Efeito de Pêndulo ]\r\nSe um ou mais monstros forem Invocados por Invocação-Pêndulo: devolva este card da Zona de Pêndulo para a mão.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nQuando este card for Invocado por Invocação-Normal: você pode enviar para o Cemitério todas as Magias/Armadilhas que seu oponente controla na(s) mesma(s) coluna(s) que o(s) card(s) na(s) sua(s) \r\nZona(s) de Pêndulo. \r\nUma vez por turno, durante a Fase Final, se este card foi Invocado por Invocação-Normal ou virado com a face para cima neste turno: devolva este card para a mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77515704,'Descanso Dragãozela',replace(replace('Você pode escolher 1 monstro "Dragãozela" que você controla e, depois, ative 1 desses efeitos;\r\n● Devolva-o para a mão e, se isso acontecer, adicione 1 card "Dragãozela" do seu Deck à sua mão, exceto "Descanso Dragãozela".\r\n● Devolva-o para a mão e, se isso acontecer, devolva 1 Magia/Armadilha que seu oponente controla para a mão.	\r\nVocê só pode usar este efeito de "Descanso Dragãozela" uma vez por turno.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Retornar 1 Card de Magia/Armadilha para a mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77522571,'Meister Peladura',replace(replace('Escala de Pêndulo = 4\r\n[ Efeito de Pêndulo ]\r\nVocê pode oferecer como Tributo 1 monstro "Peladura", "Fofanimal" ou "Diabrete de" de Nível 4 ou menos; Invoque por Invocação-Especial do seu Deck, 1 monstro Demônio com o mesmo Nível, mas com um nome diferente. \r\nVocê só pode usar este efeito de "Meister Peladura" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nDurante sua Fase Principal: você pode Invocar por Invocação-Especial 1 monstro "Peladura", "Fofanimal" ou "Diabrete de" de Nível 4 ou menos do seu Deck e, além disso, você não pode Invocar monstros por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto Monstros de Fusão. \r\nVocê pode oferecer como Tributo 2 ou mais monstros Demônio; Invoque por Invocação-Especial 1 Monstro de Fusão "Peladura" do seu Deck Adicional, cujo Nível seja igual aos Níveis originais combinados desses monstros. \r\n(Isso é considerado uma Invocação-Fusão.) \r\nVocê só pode usar cada efeito de "Meister Peladura" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77527210,'Alma da Pureza e da Luz',replace(replace('Este card não pode ser Invocado, por Invocação-Normal, ou Baixado. \r\nEste card não pode ser Invocado a não ser por Invocação-Especial, removendo de jogo 2 monstros da LUZ no seu Cemitério. \r\nEnquanto este card permanecer no Campo com a face para cima, diminua o ATK de todos os monstros no Campo do seu adversário em 300 pontos durante a Battle Phase do seu adversário.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77538567,'Suborno Obscuro','Quando seu oponente ativar um Card de Magia/Armadilha: seu oponente compra 1 card e, além disso, negue a ativação da Magia/Armadilha e, se isso acontecer, destrua-a.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77539547,'Guerreiros Antigos - Gracioso Zhou Gong',replace(replace('Você pode escolher 1 Magia/Armadilha Contínua que você controla; envie-a para o Cemitério e, se isso acontecer, adicione 1 Magia/Armadilha "Guerreiros Antigos" do seu Deck à sua mão. \r\nSe outro efeito de um monstro "Guerreiros Antigos" seu for ativado (exceto durante a Etapa de Dano): você pode escolher 1 Monstro de Efeito que seu oponente controla; negue os efeitos dele até o final deste turno. \r\nVocê só pode usar cada efeito de "Guerreiros Antigos - Gracioso Zhou Gong" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Negar um monstro','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77542832,'Hordeum Maligno Heliotrope','.edadilaer sohnos sues ranrot massop euq arap oproc mu rop odnaisna ,oçA ed muedroH sod setnecenamer samla sad sotnemasnep so oãs sessE "!ranimretxE !racidarrE !ranimilE"','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77543769,'Despertar Verdadeiro de Centur-Ião',replace(replace('Quando um Card de Magia/Armadilha, ou efeito de monstro, for ativado: envie 1 Card de Monstro com a face para cima da sua Zona de Magias & Armadilhas para o Cemitério; negue a ativação e, se isso acontecer, destrua esse card. \r\nVocê só pode ativar 1 "Despertar Verdadeiro de Centur-Ião" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77558536,'Raiden, a Mão dos Luminosos',replace(replace('Durante sua Fase Principal: você pode enviar os 2 cards do topo do seu Deck para o Cemitério e, depois, se qualquer monstro "Luminoso(a)" foi enviado para o Cemitério por este efeito, este card ganha 200 de ATK até o final do turno do seu oponente. \r\nVocê só pode usar este efeito de "Raiden, a Mão dos Luminosos" uma vez por turno. \r\nUma vez por turno, durante sua Fase Final: envie os 2 cards do topo do seu Deck para o Cemitério.','\r',char(13)),'\n',char(10)),'Enviar para o Cemitério','Enviar para o Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77561728,'Perturbação Estratégica','Seu oponente embaralha toda a sua mão no Deck e, depois, compra o mesmo número de cards.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77565204,'Fusão Futura',replace(replace('Durante sua 1ª Fase de Apoio depois da ativação deste card: mostre 1 Monstro de Fusão no seu Deck Adicional e envie as Matérias de Fusão listadas nele do seu Deck Principal para o Cemitério. \r\nDurante sua 2ª Fase de Apoio depois da ativação deste card: Invoque por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional com o mesmo nome que o monstro que você mostrou e escolha-o como alvo deste card. \r\nQuando este card deixar o campo, destrua o alvo. \r\nQuando o alvo for destruído, destrua este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77568553,'Rastejador Ácido','Uma lagarta gigante que secreta uma névoa ácida que derrete qualquer coisa.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77571454,'Número 69: Símbolo Heráldico - Demolição de Matéria Escura',replace(replace('5 monstros de Nível 4	\r\nNão pode ser destruído em batalha ou por efeitos de card. \r\nUma vez por turno (Efeito Rápido): você pode desassociar 1 matéria deste card e, depois, escolha 1 monstro com a face para cima que seu oponente controla; o nome desse monstro se torna "Desconhecido". \r\nNegue quaisquer efeitos de "Desconhecido" ativados pelo seu oponente.','\r',char(13)),'\n',char(10)),'Alterar nome do card','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77571455,'Desconhecido','Desconhecido','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77573354,'Glicínias da Angústia de Ragnaraika',replace(replace('Invoque este card por Invocação-Especial como um Monstro Normal (Planta/TREVAS/Nível 4/ATK 1600/DEF 0) (este card ainda é considerado uma Armadilha) e, depois, se você controlar um Monstro Link "Ragnaraika", você pode banir até 2 cards do Cemitério do seu oponente. \r\nDurante a Fase Final, se este card estiver no seu Cemitério: você pode embaralhar no Deck 2 monstros Inseto, Planta e/ou Réptil do seu Cemitério e/ou banimento e, se isso acontecer, Baixe este card. \r\nVocê só pode usar este efeito de "Glicínias da Angústia de Ragnaraika" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Efeito de Baixar','Banir 1 card do Cemitério do seu oponente?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77581312,'Palhaço Mascarado','A dança mortífera deste guerreiro é executada com uma foice letal.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77584012,'Pseudo Espaço','Uma vez por turno: você pode banir 1 Card de Magia de Campo do seu Cemitério; até a Fase Final, o nome deste card se torna o nome original desse card e substitua este efeito pelos efeitos originais desse card.','Obter o efeito de uma Magia de Campo','Encerrar o efeito copiado','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77585513,'Jinzo',replace(replace('Os Cards de Armadilha, bem como seus efeitos no campo, não podem ser ativados. \r\nNegue todos os efeitos de Armadilha no campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77585514,'Jinzo',replace(replace('Os Cards de Armadilha, bem como seus efeitos no campo, não podem ser ativados. \r\nNegue todos os efeitos de Armadilha no campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77590412,'Torre Marionete',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode colocar este card em Posição de Defesa e, se isso acontecer, envie 1 monstro Guerreiro de TERRA do seu Deck para o seu Cemitério. \r\nMonstros que seu oponente controla que podem atacar devem atacar este card. \r\nUma vez por turno, quando este card for escolhido como alvo de um ataque: você pode escolher 1 monstro Guerreiro de TERRA de Nível 6 ou mais no seu Cemitério; envie este card do campo para o Cemitério e, se isso acontecer, Invoque esse monstro por Invocação-Especial e, depois, mude o alvo do ataque para ele.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77600660,'Imperador Psíquico','Quando este card for Invocado por Invocação-Normal ou Especial, ganhe 500 PV para cada monstro do Tipo Psíquico no seu Cemitério.','Ganhar PV','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77603950,'Fantasma Dewan','Um feiticeiro que pode paralisar um inimigo com uma simples maldição.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77608643,'HERÓI do Destino - Capitão Tenaz','Uma vez por turno, durante sua Fase de Apoio: Você pode escolher 1 monstro "HERÓI do Destino" no seu Cemitério que foi destruído em batalha desde a sua última Fase de Apoio, se você controlava este card com a face para cima quando o alvo foi destruído; Invoque o alvo por Invocação-Especial.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77610503,'Brisawntarilho e o Mar Apavorante',replace(replace('Quando seu oponente Invocaria um ou mais monstros por Invocação-Especial, enquanto você controlar um monstro com a face para cima Invocado por Invocação-Tributo e nenhum monstro Invocado por Invocação-Especial: negue a Invocação e, se isso acontecer, devolva esse(s) monstro(s) para a mão e, além disso, pelo resto deste turno, seu oponente não pode Invocar por Invocação-Especial e pode conduzir até 3 Invocações-Normal/Baixar neste turno, não apenas 1. \r\nVocê só pode ativar 1 "Brisawntarilho e o Mar Apavorante" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77610772,'Ib, a Sacerdotisa do Cálice Mundial',replace(replace('2 monstros com Tipos e Atributos diferentes	\r\nEste card linkado não pode ser destruído em batalha ou por efeitos de card. \r\nSeu oponente não pode escolher este card linkado como alvo de efeitos de card. \r\nSe um ou mais monstros para os quais este card apontar seriam destruídos por um efeito de card, em vez disso, você pode enviar este card para o Cemitério. \r\nSe este card for enviado do campo para o Cemitério: você pode Invocar por Invocação-Especial 1 monstro "Cálice Mundial" da sua mão.','\r',char(13)),'\n',char(10)),'Usar o efeito de "Ib, a Sacerdotisa do Cálice Mundial" em vez de ser destruído?','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77622396,'Armadilha de Inversão',replace(replace('Até a Fase Final, todos os efeitos de adicionar ou subtrair ATK ou DEF são invertidos. \r\n(Adições agora subtraem e subtrações agora adicionam. Multiplicações e divisões, incluindo efeitos de dobrar ou diminuir pela metade, não são afetados.)','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77625948,'Lâmina Cibersombria',replace(replace('Se este card for Invocado por Invocação-Normal: escolha 1 monstro Dragão de Nível 3 ou menos no seu Cemitério; equipe esse monstro Dragão a este card. \r\nGanha ATK igual ao ATK original do monstro equipado a ele por este efeito. \r\nEste card pode atacar diretamente. \r\nSe ele o fizer usando este efeito, seu ATK é diminuído pela metade apenas durante o cálculo de dano. \r\nSe este card seria destruído em batalha, em vez disso, destrua esse monstro equipado a ele.','\r',char(13)),'\n',char(10)),'Equipar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77631175,'Rei Arthur, Herói dos Quadrinhos',replace(replace('2 monstros de Nível 4 do Tipo Guerreiro	\r\nSe este card seria destruído em batalha, em vez disso, você pode desassociar 1 Matéria Xyz deste card. \r\nQuando isso acontecer: ele ganha 500 de ATK e, se isso acontecer, cause 500 de dano ao seu oponente.','\r',char(13)),'\n',char(10)),'Usar o efeito de "Rei Arthur, Herói dos Quadrinhos" em vez de ser destruído?','Aumentar ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77637979,'LANforrinco','2 monstros','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77642288,'Besta Gladiadora Secutor','Se este card foi Invocado por Invocação-Especial pelo efeito de um monstro "Besta Gladiadora", no final de qualquer Fase de Batalha na qual este card batalhou: Invoque por Invocação-Especial 2 monstros "Besta Gladiadora" do seu Deck, exceto "Besta Gladiadora Secutor".','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77656797,'Infernobre Cavaleiro Imperador Charles',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nSe um Card de Equipamento se tornar equipado a um monstro no campo, mesmo durante a Etapa de Dano: você pode destruir 1 card no campo. \r\nDurante a Fase Final: você pode equipar 1 Magia de Equipamento da sua mão ou do Cemitério a este card e, depois, você pode equipar 1 monstro Guerreiro de FOGO do seu Deck a este card como uma Magia de Equipamento que concede a ele 500 de ATK. \r\nVocê só pode usar cada efeito de "Infernobre Cavaleiro Imperador Charles" uma vez por turno.','\r',char(13)),'\n',char(10)),'Destrua 1 card no campo','Equipe este card com 1 Card de Equipamento','Equipar um monstro?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77672444,'Frenesi do Motor',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial, ou se um ou mais outros monstros Máquina forem Invocados por Invocação-Normal ou Especial no seu campo: você pode ativar este efeito; até o final do turno do seu oponente, esse(s) monstro(s) \r\nInvocado(s) por Invocação-Normal ou Especial ganha(m) \r\nATK igual à metade da(s) sua(s) \r\nDEF original(is) e, além disso, sua(s) posição(ões) de batalha não pode(m) ser mudada(s). \r\nSe este card Invocado por Invocação-Tributo for enviado para o Cemitério: você pode Invocar por Invocação-Especial 2 "Ficha de Motor" (Máquina/TERRA/Nível 1/ATK 200/DEF 200) em Posição de Ataque. \r\nVocê só pode usar cada efeito de "Frenesi do Motor" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77672445,'Ficha de Motor','Invocado por Especial com o efeito "Motor Demoníaco Ω".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77675029,'Exoirmã Karmael',replace(replace('2 monstros "Exoirmã" de Nível 4	\r\nSe este card for Invocado por Invocação-Xyz: você pode ativar este efeito; durante a Fase Final deste turno, Baixe 1 Magia/Armadilha "Exoirmã" do seu Deck, Cemitério ou banimento. \r\nQuando seu oponente ativar um efeito de monstro, ou um Card de Magia/Armadilha Normal (Efeito Rápido): você pode desassociar todas as matérias deste card e, se isso acontecer, o efeito ativado se torna "Adicione 1 card do Cemitério do seu oponente à mão dele". \r\nVocê só pode usar cada efeito de "Exoirmã Karmael" uma vez por turno.','\r',char(13)),'\n',char(10)),'Baixar Magia/Armadilha','Efeito de alterar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77679716,'Armadura Samurai Superpesado Quebra Almas',replace(replace('(Este card deve ser sempre considerado como um card "Samurai Superpesado Alma".)	\r\nVocê pode escolher 1 monstro "Samurai Superpesado" que você controla; equipe este monstro da sua mão ou do campo ao alvo. \r\nEle perde 1000 de DEF e, além disso, ele não pode ser destruído em batalha. \r\nSe este card estiver no seu Cemitério: você pode banir todos os "Armadura Samurai Superpesado Quebra Almas" do seu Cemitério e, depois, escolha 1 monstro "Samurai Superpesado" no campo cuja DEF atual seja menor que sua DEF original; cause dano ao seu oponente igual à diferença entre sua DEF atual e original.','\r',char(13)),'\n',char(10)),'Equipar','Dano de efeito','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77683371,'Conjurador Dimensional',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 "Dimensão Mágica" do seu Deck ou Cemitério à sua mão. \r\nSe este card for enviado da Zona de Monstros para o Cemitério: você pode comprar cards igual ao número de monstros Mago que você controla e, depois, coloque cards da sua mão no topo do seu Deck em qualquer ordem, igual ao número de cards que você comprou. \r\nVocê só pode usar cada efeito de "Conjurador Dimensional" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77693536,'Plenametalmorfose Alkahest',replace(replace('1 monstro "Metalmorfose" + 1 Monstro Normal	\r\nDeve ser Invocado por Invocação-Fusão. \r\nUma vez por turno, durante o turno do seu oponente (Efeito Rápido): você pode escolher 1 Monstro de Efeito no campo; equipe o alvo a este card. \r\nEste card ganha DEF igual ao ATK original combinado dos monstros equipados a ele por este efeito. \r\nVocê pode usar monstros que você controla equipados a este card que você controla como matéria para a Invocação-Fusão de Monstros de Fusão "Metalmorfose" que os listem como matérias.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77700347,'Defensor Necro',replace(replace('Durante sua Fase Principal, você pode remover de jogo este card do seu Cemitério para selecionar 1 monstro que você controla. \r\nAté a próxima Fase Final do seu oponente, esse monstro não pode ser destruído em batalha, e você não sofre Dano de Batalha de batalhas envolvendo ele.','\r',char(13)),'\n',char(10)),'Não pode ser destruído em batalha','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77710579,'Cerne Senhormek do Núcleo Infinito',replace(replace('Na primeira vez que este card seria destruído em batalha a cada turno, ele não é destruído. \r\nVocê só pode usar cada um dos seguintes efeitos de "Cerne Senhormek do Núcleo Infinito" uma vez por turno. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 Magia/Armadilha "Senhormek" do seu Deck à sua mão. \r\nSe este card for destruído por um efeito de card: você pode Invocar por Invocação-Especial 1 monstro "Senhormek Imperador" da sua mão ou do Deck com um Atributo diferente que o dos monstros que você controla, ignorando suas condições de Invocação e, além disso, pelo resto deste turno, você só pode declarar um ataque com 1 monstro.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77714963,'Yasha, o Mayakashi Esqueleto',replace(replace('Você pode descartar 1 outro monstro "Mayakashi"; Invoque este card por Invocação-Especial da sua mão. \r\nVocê só pode usar este efeito de "Yasha, o Mayakashi Esqueleto" uma vez por turno. \r\nVocê não pode Invocar monstros por Invocação-Especial do Deck Adicional, exceto monstros "Mayakashi".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77723643,'Dragão Sombraneco',replace(replace('VIRE: Você pode escolher 1 card que seu oponente controla; devolva-o para a mão.\r\nSe este card for enviado para o Cemitério por um efeito de card: você pode escolher 1 Magia/Armadilha no campo; destrua-a. \r\nVocê só pode usar 1 efeito de "Dragão Sombraneco" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Retornar à mão','Destruir Magias/Armadilhas','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77751766,'Sucesso nas Tarefas de Verão!',replace(replace('Ative este card ao colocar 5 Marcadores de Tarefa nele. \r\nSe um ou mais monstros forem Invocados por Invocação-Especial do Deck Adicional, ou se um ou mais cards forem enviados do Deck para o Cemitério, por um efeito de Magia/Armadilha: remova 1 Marcador de Tarefa deste card e, depois, se o número de Marcadores de Tarefa neste card agora for 0, destrua este card e, se isso acontecer, ganhe 4000 PV e, depois, Baixe 1 Armadilha "Tarefa" do seu Deck ou Cemitério e, depois, se você tiver 1 card ou menos no seu Deck, você vence o Duelo.','\r',char(13)),'\n',char(10)),'','Remova Marcadores','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77754169,'Robô "B" Super Blindado e Armado de Ferro Negro',replace(replace('Se você tiver 3 monstros Inseto com o mesmo nome no seu Cemitério: você pode escolher qualquer número deles; Invoque este card por Invocação-Especial da sua mão e, depois, equipe-os a este card. \r\nVocê pode enviar para o Cemitério 1 monstro equipado a este card pelo efeito deste card; destrua todos os monstros que seu oponente controla com ATK maior ou igual ao ATK do monstro enviado para o Cemitério. \r\nVocê só pode usar cada efeito de "Robô "B" Super Blindado e Armado de Ferro Negro" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77754944,'Ruína Generalizada','Quando um monstro do oponente declarar um ataque: destrua o 1 monstro em Posição de Ataque que seu oponente controla com o maior ATK (em caso de empate, você seleciona).','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77754945,'Ruína Generalizada','Quando um monstro do oponente declarar um ataque: destrua o 1 monstro em Posição de Ataque que seu oponente controla com o maior ATK (em caso de empate, você seleciona).','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77765207,'Juramento ao Emblemado',replace(replace('Ative 1 desses efeitos;\r\n● Coloque 1 monstro "Centur-Ião" do seu Deck na sua Zona de Magias & Armadilhas como uma Armadilha Contínua com a face para cima.	\r\nPelo resto deste turno, enquanto você controlar esse card, ou qualquer card com esse mesmo nome original, você não pode Invocar por Invocação-Especial do Deck Adicional, exceto monstros "Centur-Ião".\r\n● Baixe 1 Magia/Armadilha "Centur-Ião" diretamente do seu Deck.	\r\nVocê só pode ativar 1 "Juramento ao Emblemado" por turno.','\r',char(13)),'\n',char(10)),'Coloque o monstro com a face para cima','Baixar 1 Card de Magia/Armadilha','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77778835,'Festa Histérica',replace(replace('Ative este card ao descartar 1 card; Invoque por Invocação-Especial do seu Cemitério tantas cópias de "Lady Harpia" quanto possível. \r\nQuando este card com a face para cima deixar o campo, destrua esses monstros.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77783947,'Libertação Yang Zing',replace(replace('Todos os monstros que seu oponente controla devem atacar, se possível. \r\nDurante a Fase Principal ou Fase de Batalha de qualquer duelista: você pode enviar este card com a face para cima da sua Zona de Magias & Armadilhas para o Cemitério; imediatamente depois que este efeito resolver, Invoque 1 Monstro Sincro por Invocação-Sincro, usando 1 ou mais monstros "Yang Zing" que você controla como Matérias Sincro.','\r',char(13)),'\n',char(10)),'Invocação Sincro','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77797992,'Alpacaribou, Besta Mística da Floresta',replace(replace('● Enquanto estiver em Posição de Ataque: Monstros em Posição de Ataque do Tipo Besta Alada, Inseto e Planta que você controla não podem ser destruídos em batalha.\r\n● Enquanto estiver em Posição de Defesa: Monstros em Posição de Defesa do Tipo Besta Alada, Inseto e Planta que você controla não podem ser escolhidos como alvo ou destruídos por efeitos de card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77799846,'Dragão Tambor de Olhos Saltados',replace(replace('2 monstros de Nível 8 do Tipo Máquina	\r\nUma vez por turno: você pode desassociar 1 Matéria Xyz deste card; ele ganha 1000 de ATK até o final do próximo turno do seu oponente. \r\nSe este card for destruído enquanto tiver Matérias Xyz: você pode banir 1 monstro "Super Robô de Defesa" do seu Cemitério; Invoque este card por Invocação-Especial do seu Cemitério e, depois, você pode associar 1 monstro "Super Robô de Defesa" do seu Cemitério à este card como uma Matéria Xyz.','\r',char(13)),'\n',char(10)),'Aumentar ATK','Invocação Especial','Usar como Matéria Xyz 1 monstro no seu Cemitério cujo nome inclua "Super Robô de Defesa"?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77826734,'Reviver Pêndulo','Invoque por Invocação-Especial 1 Monstro Pêndulo com a face para cima do seu Deck Adicional ou 1 Monstro Pêndulo do seu Cemitério.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77827521,'Julgamento Infernal','Este demônio julga inimigos que estão trancados em caixões.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77832858,'Thestalos, o Monarca do Fogo Sombrio',replace(replace('Você pode Invocar este card por Invocação-Tributo ao oferecer como Tributo 1 monstro que seu oponente controla e 1 monstro Invocado por Invocação-Tributo que você controla. \r\nSe este card for Invocado por Invocação-Tributo: você pode banir 1 card aleatório da mão do seu oponente e, se isso acontecer, cause 1000 de dano ao seu oponente e, depois, se este card foi Invocado por Invocação-Tributo ao oferecer como Tributo um monstro Invocado por Invocação-Tributo de Nível 8 ou mais, você pode aplicar este efeito.\r\n● Bana 1 card no campo e, se era um Card de Monstro de FOGO ou TREVAS, cause dano ao seu oponente igual ao seu Nível original x 200.','\r',char(13)),'\n',char(10)),'Ofereça como Tributo 1 monstro que seu oponente controla e 1 dos seus monstros Invocados por Tributo para realizar uma Invocação Tributo','','Banir mais 1 card no campo?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77840540,'Casulo de Ultra Evolução',replace(replace('Ofereça como Tributo 1 monstro Inseto de qualquer campo equipado com um Card de Equipamento e, se isso acontecer, Invoque por Invocação-Especial 1 monstro Inseto do seu Deck, ignorando suas condições de Invocação. \r\nDurante sua Fase Principal: você pode banir este card do seu Cemitério e, depois, escolha 1 monstro Inseto no seu Cemitério; embaralhe-o no Deck e, depois, compre 1 card. \r\nVocê só pode usar este efeito de "Casulo de Ultra Evolução" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77841719,'Hordeum Maligno Coppelia',replace(replace('Não pode ser Invocado por Invocação-Especial. \r\nQuando este card deixar o campo devido ao card do seu oponente (seja em batalha ou por um efeito de card): você pode escolher 1 monstro com a face para cima que seu oponente controla; assuma o controle do alvo até sua próxima Fase Final.','\r',char(13)),'\n',char(10)),'Tomar controle','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77847678,'Esquema de Shien','Se um monstro "Seis Samurai" que você controla for destruído em batalha: Invoque por Invocação-Especial até 2 monstros "Seis Samurai" da sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77848740,'Pudimanincesa Magidoce',replace(replace('Se este card em sua posse for destruído por um card do oponente e enviado para o seu Cemitério: embaralhe este card no Deck. \r\nVocê só pode usar cada um dos seguintes efeitos de "Pudimanincesa Magidoce" uma vez por turno.\r\n● Se você não tiver monstros no seu Cemitério: você pode Invocar este card por Invocação-Especial da sua mão.\r\n● Se este card for Invocado por Invocação-Especial: você pode Invocar por Invocação-Especial 1 monstro "Magidoce" da sua mão ou do Deck, exceto "Pudimanincesa Magidoce" e, se isso acontecer, reduza o Nível dele em 1 e, além disso, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros "Magidoce".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77855162,'Entrainment Inclinado',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro: você pode Invocar por Invocação-Especial 1 Monstro Pêndulo de Nível 4 ou menos da sua mão ou com a face para cima do seu Deck Adicional. \r\nNo final da Etapa de Dano, quando este card ou Monstro Pêndulo seu batalhar um monstro do oponente, mas o monstro do oponente não foi destruído pela batalha: você pode destruir esse monstro do oponente. \r\nVocê só pode usar cada efeito de "Entrainment Inclinado" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77856460,'Ajudante Robo para Combate Subaquático',replace(replace('2 monstros Máquina	\r\nSe este card for Invocado por Invocação-Link: você pode escolher 1 monstro que seu oponente controla; destrua-o, e também este card, então você pode Invocar por Invocação-Especial 1 monstro Máquina não-ÁGUA com 1600 ou menos de ATK do seu Cemitério.\r\nSe este card for banido: você pode adicionar 1 monstro Máquina cujo ATK seja igual a sua DEF do seu Deck à sua mão.\r\nVocê só pode usar cada um dos efeitos de "Ajudante Robo para Combate Subaquático" uma vez por turno, você também não pode Invocar por Invocação-Especial no turno que ativar qualquer efeito deste card, exceto monstros Máquina.','\r',char(13)),'\n',char(10)),'Efeito de destruição','Efeito de busca','Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77859858,'Compra Destrutiva',replace(replace('Se qualquer duelista não tiver cards na sua mão no começo da Fase de Compra dele, ele pode comprar mais 1 card em adição à sua compra normal. \r\nO controlador deste card perde 700 PV durante a Fase Final dele. \r\n(Se tiver menos que 700, em vez disso, ele se torna 0.) \r\nQuando este card com a face para cima deixar o campo, cause 3000 de dano ao duelista que o controlava.','\r',char(13)),'\n',char(10)),'Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77864539,'Fábrica Senhormek','Quando um monstro "Senhormek" no campo for escolhido como alvo de um ataque: escolha 1 monstro "Exército Senhormek" no seu Cemitério; adicione o alvo à sua mão e, depois, destrua o alvo do ataque.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77876207,'Passagem Secreta para os Tesouros',replace(replace('Escolha 1 monstro no seu Campo com a face para cima com um ATK igual a 1000 pontos ou menos. \r\nDurante este turno, o monstro escolhido pode atacar os Life Points do seu adversário diretamente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77891946,'Vadis Exoirmã',replace(replace('Pague 800 PV; selecione 1 monstro "Exoirmã" do seu Deck e, depois, pegue 1 outro monstro "Exoirmã" do seu Deck que seja mencionado nesse monstro e Invoque os dois por Invocação-Especial, mas embaralhe-os no Deck durante a Fase Final e, além disso, pelo resto deste turno depois que este card resolver, você não pode Invocar monstros do Deck Adicional por Invocação-Especial, exceto monstros "Exoirmã". \r\nVocê só pode ativar 1 "Vadis Exoirmã" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77894049,'Alma Aniquiladora Rochas',replace(replace('2+ monstros "Alma Aniquiladora" de Nível 4	\r\nUma vez por turno, se um monstro "Alma Aniquiladora" batalhou neste turno, você também pode Invocar "Alma Aniquiladora Rochas" por Invocação-Xyz ao usar 1 monstro "Alma Aniquiladora" ou 1 "Rocha do Aniquilador" que você controla (transfira as matérias dele para este card). \r\nGanhe os seguintes efeitos, de acordo com os Atributos de suas matérias associadas.\r\n● TREVAS: Todos os monstros que seu oponente controla perdem 800 de ATK.\r\n● FOGO: Monstros "Alma Aniquiladora" que você controla ganham 1000 de ATK.\r\n● TERRA: Você pode desassociar 1 matéria deste card; destrua 1 card que seu oponente controla.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Xyz usando monstros "Alma Aniquiladora" ou "Rocha do Aniquilador" como matéria?','Destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77895328,'Genta, Zelador do Mundo Negro',replace(replace('Você só pode Invocar "Genta, Zelador do Mundo Negro" por Invocação-Especial uma vez por turno. \r\nVocê pode descartar este card para o Cemitério; adicione 1 "Os Portões do Mundo Negro" do seu Deck à sua mão. \r\nSe este card for banido e você controlar um card "Mundo Negro": você pode Invocar este card por Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77901552,'Dragão Hierático de Tefnuit',replace(replace('Se somente seu oponente controlar um monstro, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nNão pode atacar durante o turno em que foi Invocado por Invocação-Especial desta forma. \r\nQuando este card for oferecido como Tributo: Invoque por Invocação-Especial 1 Monstro Normal Dragão da sua mão, do Deck ou do Cemitério e torne seu ATK/DEF 0.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77910045,'Ábaco Fatal','Cada vez que um monstro é enviado do Campo para o Cemitério, inflija 500 pontos de dano por cada card aos Life Points do respectivo dono do Card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77913594,'Pax Exoirmã',replace(replace('Durante a Fase Principal: pague 800 PV; adicione 1 card "Exoirmã" do seu Deck à sua mão, exceto "Pax Exoirmã" e, depois, se você adicionou um monstro por este efeito, você pode Invocá-lo por Invocação-Especial se o outro monstro "Exoirmã" mencionado nele estiver no seu campo ou no seu Cemitério. \r\nVocê só pode ativar 1 "Pax Exoirmã" por turno.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Invocação Especial?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77936940,'Gernia','Uma vez por turno, durante sua próxima Fase de Apoio, depois que este card com a face para cima que você controla foi destruído por um efeito de card do oponente e enviado para o seu Cemitério: Invoque-o por Invocação-Especial do seu Cemitério.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77946022,'Tenyinfinidade',replace(replace('Quando este card for ativado: você pode adicionar 1 "Receptáculo para o Ciclo do Dragão" ou "Círculo do Dragão Celestial" do seu Deck à sua mão. \r\nVocê pode oferecer como Tributo 1 monstro Wyrm e, depois, escolha 1 monstro no campo; destrua-o. \r\nVocê só pode usar este efeito de "Tenyinfinidade" uma vez por turno. \r\nUma vez por turno, durante sua Fase Final: você pode enviar este card para o Cemitério e, se isso acontecer, coloque 1 "Perfeição Sem Falhas dos Tenyi" do seu Deck ou Cemitério, com a face para cima na sua Zona do Campo. \r\nVocê só pode ativar 1 "Tenyinfinidade" por turno.','\r',char(13)),'\n',char(10)),'Ativar','Destruir','Colocar com a face para cima','Adicionar este card à mão?','','','','','','','','','','','','');
INSERT INTO texts VALUES(77967790,'Dinolutador Rei T Wrextle',replace(replace('2+ monstros "Dinolutador"	\r\nSe este card batalhar, seu oponente não pode ativar Cards de Magia/Armadilha até o final da Etapa de Dano. \r\nOs monstros do seu oponente não podem escolher monstros como alvo de ataques, exceto este. \r\nNo começo da Fase de Batalha do seu oponente: você pode escolher 1 monstro em Posição de Ataque que seu oponente controla; nesta Fase de Batalha, seu oponente não pode atacar com outros monstros até que esse monstro tenha atacado e, se ele não declarar um ataque, destrua-o no final da Fase de Batalha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77972406,'Presas da Emboscada',replace(replace('Ative somente quando um monstro "Peçonha" com a face para cima que você controla for declarado como alvo de um ataque. \r\nNegue o ataque e encerre a Fase de Batalha. \r\nDepois, coloque 1 Marcador de Veneno sobre o monstro que atacou.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77994337,'Hallohallo',replace(replace('Escala de Pêndulo = 2\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno: você pode escolher 1 monstro com a face para cima no campo; lance um dado de seis faces e o Nível desse monstro se torna igual ao resultado até o final deste turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nHallo Hallo, cabeça oca,\r\nSem tripas, nem doce na boca.\r\nMarchando em busca de suas doçuras,\r\ne levando a vida com amarguras.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77998771,'Goblin Corvo','Um duende inteligente de nariz comprido e que não deve ser subestimado.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78004197,'Douraddo, Wu-Lorde do Mundo Negro','Se este card for descartado para o Cemitério por um efeito de card: se ele foi descartado da sua mão para o seu Cemitério por um efeito de card do oponente, você pode escolher até 2 cards que seu oponente controla; Invoque este card por Invocação-Especial e, depois, destrua esses alvos (se houver).','Invocação Especial','Destruir 1 card que seu oponente controla?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78009994,'Guarda Dragônica',replace(replace('Sempre que um monstro for Invocado por Invocação-Normal ou Baixado, coloque 1 Marcador Dragônico neste card. \r\nVocê pode enviar este card com a face para cima ao Cemitério para Invocar por Invocação-Especial 1 monstro do Tipo Dragão do seu Deck cujo Nível seja menor ou igual ao número de Marcadores Dragônicos neste card.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78010363,'Bruxa da Floresta Negra',replace(replace('Se este card for enviado do campo para o Cemitério: adicione 1 monstro com 1500 ou menos de DEF do seu Deck à sua mão, mas você não pode ativar cards, ou os efeitos de cards, com esse nome pelo resto deste turno. \r\nVocê só pode usar este efeito de "Bruxa da Floresta Negra" uma vez por turno.','\r',char(13)),'\n',char(10)),'Procurar no Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78021082,'Tecedora de Cauda de Fadas',replace(replace('1 monstro "Cauda de Fadas" + 1 monstro Mago	\r\nTodos os "Príncipe das Fadas" no campo se tornam monstros Mago. \r\nDurante sua Fase Principal: você pode Invocar por Invocação-Especial 1 monstro "Cauda de Fadas" do seu Deck ou banimento. \r\nVocê só pode usar este efeito de "Tecedora de Cauda de Fadas" uma vez por turno. \r\nSe você Invocar um monstro "Cauda de Fadas" que não seja de TERRA por Invocação-Normal ou Especial, enquanto este card estiver na sua Zona de Monstros (exceto durante a Etapa de Dano): você pode escolher 1 Monstro de Efeito que seu oponente controla; negue seus efeitos e, além disso, seu nome se torna "Príncipe das Fadas".','\r',char(13)),'\n',char(10)),'Invocação Especial','Alterar o nome do card','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78033100,'Dragão Hierático de Gebeb',replace(replace('Se este card destruir um monstro do oponente em batalha e enviá-lo para o Cemitério: Invoque por Invocação-Especial 1 Monstro Normal Dragão da sua mão, do Deck ou do Cemitério, e torne seu ATK/DEF 0. \r\nSe este card for oferecido como Tributo: Invoque por Invocação-Especial 1 Monstro Normal "Hierático" da sua mão, do Deck ou do Cemitério.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78053598,'Designador das Trevas',replace(replace('Declare o nome de 1 Card de Monstro. \r\nSe o card declarado estiver no Deck do seu adversário, adicione 1 desses cards à mão do seu adversário.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78058681,'Kewl Tune Sincro',replace(replace('Adicione 1 card "Kewl Tune" do seu Deck à sua mão, exceto "Kewl Tune Sincro" e, depois, imediatamente depois que este efeito resolver, você pode Invocar por Invocação-Sincro 1 Monstro Sincro Regulador. \r\nVocê não pode Invocar por Invocação-Especial pelo resto deste turno depois que este card resolver, exceto Reguladores. \r\nVocê pode ativar até 2 "Kewl Tune Sincro" por turno.','\r',char(13)),'\n',char(10)),'Ativar','Invocação Sincro?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78060096,'Salmão Rei do Terror','Um salmão temido, mestre do Mar das Trevas. As suas ovas são o melhor canapé do Mundo das Trevas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78063197,'Fusão do Renunciado',replace(replace('Invoque por Invocação-Fusão 1 Monstro de Fusão "Restrição do" do seu Deck Adicional, ao banir matérias da sua mão, do campo e/ou do Cemitério. \r\nDurante sua Fase Principal: você pode banir este card do seu Cemitério e, depois, escolha 1 Monstro de Efeito que seu oponente controla; equipe o alvo a um "Renunciado" ou Monstro de Fusão "Restrição do" que você controla, como se ele tivesse sido equipado pelo efeito desse monstro. \r\nVocê só pode usar cada efeito de "Fusão do Renunciado" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78077209,'Diabólica, a General Draconique',replace(replace('Se um ou mais monstros Demônio, exceto "Diabólica, a General Draconique", forem enviados para o seu Cemitério por um efeito de card (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial do seu Cemitério (se ele estava lá quando o monstro foi enviado) ou da mão (mesmo se ele não estava), mas bana-o quando ele deixar o campo. \r\nSe este card for enviado para o Cemitério por um efeito de card: você pode escolher 1 monstro Demônio no seu Cemitério, exceto "Diabólica, a General Draconique"; adicione-o à sua mão. \r\nVocê só pode usar 1 efeito de "Diabólica, a General Draconique" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78080961,'Reparador ESPIRÃO',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 card "APARATO ESPIRÃO" do seu Deck à sua mão. \r\nSe este card estiver no seu Cemitério e você controlar "Super Agente ESPIRÃO": você pode descartar 1 card; Invoque este card por Invocação-Especial, mas bana-o quando ele deixar o campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78082039,'Floresta Cerrada',replace(replace('Todos os monstros do Tipo Besta que você controla ganham 100 de ATK para cada monstro no seu Cemitério. \r\nCards de Magia de Campo não podem ser ativados. \r\nCards de Magia de Campo não podem ser ativados durante o turno em que este card for destruído.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78084378,'Quimera Diplexer',replace(replace('2 monstros Ciberso	\r\nUma vez por turno: você pode oferecer como Tributo 1 monstro Ciberso; Cards de Magia/Armadilha e seus efeitos, não podem ser ativados durante a Fase de Batalha deste turno. \r\nSe este card Invocado por Invocação-Fusão for enviado para o seu Cemitério: você pode escolher 1 "Cinet Fusão" e 1 monstro Ciberso no seu Cemitério, exceto este card; adicione-os à sua mão. \r\nVocê só pode usar este efeito de "Quimera Diplexer" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78098950,'Tsumuha-Kutsunagi, o Senhor das Espadas',replace(replace('Não pode ser Invocado por Invocação-Especial. \r\nVocê pode Invocar este card por Invocação-Tributo ao oferecer como Tributo 1 monstro Invocado por Invocação-Normal/Baixado. \r\nSe este card for Invocado por Invocação-Normal ou virado com a face para cima: ative este efeito; seu oponente pode enviar qualquer número de cards do campo dele para o Cemitério e, depois, cada duelista compra o mesmo número de cards que foram enviados para o Cemitério por este efeito. \r\nDurante a Fase Final do turno em que este efeito foi ativado, embaralhe no Deck todos os cards do campo, dos Cemitérios e que estiverem banidos. \r\nUma vez por turno, durante a Fase Final, se este card no campo foi Invocado por Invocação-Normal ou virado com a face para cima neste turno: devolva este card para a mão.','\r',char(13)),'\n',char(10)),'Ofereça 1 monstro Invocado por Invocação Normal como Tributo para uma Invocação Tributo','','Enviar 1 card no campo para o Cemitério?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78114463,'Acusação Solene',replace(replace('Você pode ativar este card no turno em que foi Baixado, ao revelar 1 outra Armadilha com a face para baixo que você controla. \r\nQuando um Card de Magia/Armadilha for ativado: você pode ativar 1 desses efeitos;\r\n● Pague 1500 PV; negue a ativação e, se isso acontecer, destrua-o e, se isso acontecer, nenhum duelista pode ativar cards, ou os efeitos de cards, com o mesmo nome original que o desse card destruído pelo resto deste turno.\r\n● Pague 3000 PV; negue a ativação e, se isso acontecer, bana-o e, depois, seu oponente bane todos os cards da mão e do Deck dele com o mesmo nome original que o desse card banido.','\r',char(13)),'\n',char(10)),'Ativar','Negar e destruir','Negar e banir','Ativar aplicando o efeito de "Acusação Solene".','','','','','','','','','','','','');
INSERT INTO texts VALUES(78121572,'Alquimista da Magia das Trevas','Uma vez por turno: você pode escolher 1 card com a face para cima que você controla sobre o qual você possa colocar um Marcador de Magia; coloque este card em Posição de Ataque que você controla com a face para cima em Posição de Defesa e, se isso acontecer, coloque 1 Marcador de Magia no alvo.','Mudar a posição de batalha','Escolha um card na qual colocar Marcadores de Magia','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78135071,'Exoirmã Kaspitrela',replace(replace('2 monstros de Nível 4	\r\nNão pode ser destruído em batalha com um monstro Invocado por Invocação-Especial do Cemitério. \r\nVocê só pode usar cada um dos seguintes efeitos de "Exoirmã Kaspitrela" uma vez por turno. \r\nSe este card for Invocado por Invocação-Xyz usando um monstro "Exoirmã" como matéria: nenhum duelista pode Invocar monstros por Invocação-Especial dos Cemitérios pelo resto deste turno. \r\nVocê pode desassociar 1 matéria deste card; adicione 1 monstro "Exoirmã" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78144171,'Armado Negro, o Dragão da Aniquilação',replace(replace('2+ monstros de Nível 7	\r\nUma vez por turno, se você tiver exatamente 5 monstros de TREVAS no seu Cemitério, você também pode Invocar por Invocação-Xyz "Armado Negro, o Dragão da Aniquilação" usando 1 monstro Dragão de TREVAS de Nível 5 ou mais que você controla como matéria. \r\nVocê pode desassociar 1 matéria deste card e, depois, escolha 1 card que seu oponente controla; destrua-o e, depois, bana 1 card do seu Cemitério e, além disso, este card não pode atacar pelo resto deste turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Xyz usando apenas 1 matéria?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78156759,'Zenmaines de Corda',replace(replace('2 monstros de Nível 3	\r\nSe este card com a face para cima no campo seria destruído, em vez disso, você pode desassociar 1 Matéria Xyz deste card. \r\nUma vez por turno, durante a Fase Final, se este efeito foi usado neste turno: escolha 1 card no campo; destrua-o.','\r',char(13)),'\n',char(10)),'Usar o efeito de "Zenmaines de Corda" em vez de ser destruído?','Destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78161361,'Diribravo','Uma vez por turno, quando um monstro Ciberso seu declarar um ataque: você pode descartar 1 monstro; até o final deste turno, esse monstro atacante ganha 600 de ATK.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78161960,'Rejeitar Renascimento','Quando um monstro do oponente declarar um ataque direto: encerre a Fase de Batalha e, depois, você pode Invocar por Invocação-Especial 1 Regulador e 1 Monstro Sincro do seu Cemitério, mas eles têm seus efeitos negados.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78184733,'Comandar Performance',replace(replace('Se você controlar um monstro "Camarartista": coloque em Posição de Defesa todos os monstros com a face para cima e em Posição de Ataque que seu oponente controla. \r\nOs monstros colocados em Posição de Defesa por este efeito não podem mudar suas posições de batalha até o final do próximo turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78193831,'Blader Notável','Ganha 500 de ATK para cada monstro Dragão que seu oponente controla ou no Cemitério dele.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78193832,'Blader Notável','Ganha 500 de ATK para cada monstro Dragão que seu oponente controla ou no Cemitério dele.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78193833,'Blader Notável','Ganha 500 de ATK para cada monstro Dragão que seu oponente controla ou no Cemitério dele.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78193834,'Blader Notável','Ganha 500 de ATK para cada monstro Dragão que seu oponente controla ou no Cemitério dele.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78199891,'Rivalidade Mikanko',replace(replace('Se você controlar um monstro "Mikanko": escolha 1 monstro com a face para cima no campo; equipe-o com 1 Magia de Equipamento do seu Deck que possa ser equipada a ele. \r\nSe uma ou mais Magias de Equipamento forem enviadas para o seu Cemitério, enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode banir este card e, depois, escolha 1 Magia de Equipamento no seu Cemitério; adicione-a à sua mão. \r\nVocê só pode usar cada efeito de "Rivalidade Mikanko" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Recuperar Card(s) de Magia de Equipamento','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78202553,'Stalagmo, o Behemoth Subterror',replace(replace('VIRE: Você pode descartar 1 monstro "Subterror" e, se isso acontecer, compre 2 cards. \r\nVocê só pode usar este efeito de "Stalagmo, o Behemoth Subterror" uma vez por turno.\r\nQuando um monstro com a face para cima que você controla for virado com a face para baixo, se você não controlar nenhum monstro com a face para cima: você pode Invocar este card por Invocação-Especial da sua mão em Posição de Defesa. \r\nUma vez por turno: você pode colocar este card com a face para baixo em Posição de Defesa.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78211862,'Aumento de Energia','Descarte 1 card e, depois, escolha 1 monstro com a face para cima no campo; o alvo ganha 1500 de ATK até o final deste turno.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78217065,'Explosão Final Evolutiva',replace(replace('Adicione 1 "Fusão Sobrecarregada" do seu Deck à sua mão. \r\nSe você Invocar um monstro por Invocação-Fusão neste turno com "Fusão Sobrecarregada", usando 6 ou mais monstros como matéria, esse monstro pode atacar um número de vezes a cada Fase de Batalha neste turno, até o número de monstros usados como suas Matérias de Fusão. \r\nPelo resto deste turno depois que este card resolver, você não pode Invocar monstros por Invocação-Especial, exceto com efeitos de Magia. \r\nVocê só pode ativar 1 "Explosão Final Evolutiva" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78225596,'Utensilhor Extensolvo',replace(replace('2 monstros "Utensilhor"	\r\nEste card linkado não pode ser escolhido como alvo dos efeitos de card do seu oponente ou dos ataques dos monstros dele. \r\nDurante o cálculo de dano, se um Monstro Link "Utensilhor" que você controla co-linkado a este card batalhar um monstro do oponente: seu monstro que estiver batalhando ganha ATK igual ao número de monstros co-linkados a este card x 1000, apenas durante o cálculo de dano. \r\nUma vez por turno, se um ou mais Monstros Link "Utensilhor" que você controla que não estiverem co-linkados a este card forem destruídos em batalha ou por um efeito de card: você pode comprar 1 card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78229193,'Golfinho de Aura Branca',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nUma vez por turno: você pode escolher 1 monstro com a face para cima que seu oponente controla; o ATK dele se torna metade do seu ATK original até o final deste turno. \r\nSe este card em sua posse for destruído por um card do oponente e enviado para o seu Cemitério: você pode banir 1 outro monstro de ÁGUA do seu Cemitério; Invoque este card por Invocação-Especial como um Regulador.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78231355,'Hospitalidade Dragãozela',replace(replace('Invoque por Invocação-Especial 1 monstro "Dragãozela" da sua mão ou do Cemitério em Posição de Defesa e, depois, você pode enviar 1 monstro "Dragãozela" com o mesmo Atributo, mas com um Nível diferente, do seu Deck para o Cemitério. \r\nVocê só pode ativar 1 "Hospitalidade Dragãozela" por turno.','\r',char(13)),'\n',char(10)),'Enviar monstros com Níveis diferentes do seu Deck para o Cemitério?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78231356,'Hospitalidade Dragãozela',replace(replace('Invoque por Invocação-Especial 1 monstro "Dragãozela" da sua mão ou do Cemitério em Posição de Defesa e, depois, você pode enviar 1 monstro "Dragãozela" com o mesmo Atributo, mas com um Nível diferente, do seu Deck para o Cemitério. \r\nVocê só pode ativar 1 "Hospitalidade Dragãozela" por turno.','\r',char(13)),'\n',char(10)),'Enviar monstros com Níveis diferentes do seu Deck para o Cemitério?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78243409,'A Coisa na Cratera','Quando este card for destruído e enviado do campo para o Cemitério, você pode Invocar por Invocação-Especial 1 monstro Piro da sua mão.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78266168,'Múmia do Machado Gigante',replace(replace('Você pode virar este card para Posição de Defesa com a face para baixo uma vez por turno durante a sua Main Phase. \r\nSe o ATK de um monstro que ataca este card em Posição de Defesa e com a face para baixo é inferior a DEF deste monstro, o monstro atacante é destruído.','\r',char(13)),'\n',char(10)),'Mudar para Posição de Defesa com a face para baixo','Destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78274190,'General Samurai Superpesado de Coral',replace(replace('Escala de Pêndulo = 8\r\n[ Efeito de Pêndulo ]\r\nEnquanto você tiver um ou mais Cards de Magia/Armadilha no seu Cemitério, a Escala de Pêndulo deste card se torna 4. \r\nUma vez por turno, quando um monstro "Samurai Superpesado" que você controla destruir um monstro do oponente em batalha: você pode ativar este efeito; esse monstro pode realizar um segundo ataque em seguida (mesmo que este card deixe o campo).\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe você não tiver nenhum Card de Magia/Armadilha no seu Cemitério: você pode oferecer como Tributo até 2 monstros "Samurai Superpesado"; compre esse número de cards. \r\nVocê só pode usar este efeito de "General Samurai Superpesado de Coral" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78275321,'Formiga de Fogo Ascator','Quando este card for destruído em batalha e enviado para o Cemitério: você pode escolher 1 monstro de Nível 5 no seu Cemitério; Invoque o alvo por Invocação-Especial, mas seus efeitos são negados e, além disso, envie-o para o Cemitério durante a Fase Final deste turno.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78293584,'Filia Diabell',replace(replace('Adicione 1 monstro "Diabell" de Nível 8 ou mais do seu Deck à sua mão ou, se somente seu oponente controlar um monstro, em vez disso, você pode Invocá-lo por Invocação-Especial. \r\nSe este card for banido: você pode fazer com que todos os monstros "Diabell" que você controla atualmente ganhem 500 de ATK. \r\nVocê só pode usar cada efeito de "Filia Diabell" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78310590,'Ator do Abismo - Doce Madonna',replace(replace('Escala de Pêndulo = 0\r\n[ Efeito de Pêndulo ]\r\nVocê pode pagar 1000 PV; adicione 1 Monstro Pêndulo "Ator do Abismo" do seu Deck à sua mão, exceto "Ator do Abismo - Doce Madonna" e, além disso, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto Monstros Pêndulo "Ator do Abismo" (mesmo que este card deixe o campo). \r\nVocê só pode usar este efeito de "Ator do Abismo - Doce Madonna" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nGanha 100 de ATK para cada Magia "Script do Abismo" no seu Cemitério. \r\nVocê só pode usar cada um dos seguintes efeitos de "Ator do Abismo - Doce Madonna" uma vez por turno.\r\n● Quando um Monstro Pêndulo que você controla for destruído em batalha: você pode Invocar este card por Invocação-Especial da sua mão.\r\n● Se um Card de Magia "Script do Abismo" ou seus efeitos forem ativados: você pode Invocar por Invocação-Especial 1 Monstro Pêndulo "Ator do Abismo" de Nível 4 ou menos do seu Deck, mas devolva-o para a mão durante a Fase Final.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78316184,'Ciber Anja Vrash',replace(replace('Você pode Invocar este card por Invocação-Ritual com "Ritual Máquina de Anjo". \r\nSe este card for Invocado por Invocação-Ritual: você pode destruir tantos monstros com a face para cima que seu oponente controla quanto possível que foram Invocados por Invocação-Especial do Deck Adicional e, se isso acontecer, para cada um, cause 1000 de dano ao seu oponente e, se isso acontecer, este card pode realizar um segundo ataque durante cada Fase de Batalha neste turno. \r\nUma vez por turno, durante o turno de qualquer duelista, quando um card ou efeito for ativado que destruiria um card no campo: você pode embaralhar no Deck 1 Monstro de Ritual do seu Cemitério; negue a ativação e, se isso acontecer, destrua esse card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78348934,'Karma do Soldado da Espada da Destruição',replace(replace('Escolha até 3 monstros do mesmo Tipo no Cemitério do seu oponente; bana-os e, se isso acontecer, até o final deste turno, 1 monstro "Blader Notável" ou 1 monstro "Espada da Destruição" que você controla ganha 500 de ATK e DEF para cada um desses monstros banidos. \r\nSe este card estiver no seu Cemitério: você pode descartar 1 card "Espada da Destruição"; adicione este card à sua mão. \r\nVocê só pode usar cada efeito de "Karma do Soldado da Espada da Destruição" uma vez por turno.','\r',char(13)),'\n',char(10)),'Continuar banindo monstros?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78349103,'Pacificador Autômato',replace(replace('Quando este card no campo for destruído e enviado para o Cemitério: você pode adicionar 1 monstro União do seu Deck à sua mão. \r\nUma vez por turno, você pode: escolher 1 monstro Máquina que você controla; equipe este card no alvo, OU: desequipe este card e Invoque-o por Invocação-Especial. \r\nSe o monstro equipado seria destruído em batalha ou por um efeito de card, em vez disso, destrua este card.','\r',char(13)),'\n',char(10)),'Tornar-se um Card de Equipamento','Invocação Especial','Adicionar à mão','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78355370,'Kuribohrn',replace(replace('No final da Fase de Batalha: você pode descartar este card e, depois, escolha 1 monstro no seu Cemitério que foi destruído em batalha e enviado para lá neste turno; Invoque-o por Invocação-Especial. \r\nQuando um monstro do oponente declarar um ataque: você pode banir este card do seu Cemitério e, depois, escolha qualquer número de monstros "Kuriboh" no seu Cemitério; Invoque-os por Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78358521,'Constelar Sombrero',replace(replace('Você só pode usar cada efeito de "Constelar Sombrero" uma vez por turno. \r\nEnquanto este card estiver no Cemitério, se ele foi enviado para lá neste turno, você pode Invocar por Invocação-Normal 1 monstro "Constelar" oferecendo 1 Tributo a menos que o normalmente exigido.\r\nVocê pode banir 1 monstro "Constelar" do seu Cemitério e, depois, escolher 1 monstro "Constelar" em seu Cemitério; adicione o alvo à sua mão e, além disso, este card ganha o seguinte efeito.\r\n● Neste turno: você pode ativar este efeito; Invoque por Invocação-Normal 1 monstro "Constelar".','\r',char(13)),'\n',char(10)),'Adicione à sua mão 1 monstro no seu Cemitério cujo nome contenha "Constelar"','Invoque 1 monstro cujo nome contenha "Constelar"','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78360952,'Sentinela Iluminado pelo Sol',replace(replace('Você pode Baixar este card da sua mão na sua Zona de Magias & Armadilhas como uma Magia. \r\nUma vez por turno, durante a Fase de Apoio do próximo turno depois que este card Baixado foi destruído e enviado para o Cemitério: você pode Invocar este card por Invocação-Especial e, depois, destrua todos os cards que seu oponente controla na coluna deste card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78362751,'Shirauo do Naviushi Gunkan',replace(replace('Se você controlar um "Shari do Naviushi Gunkan", ou um Monstro Xyz que tenha "Shari do Naviushi Gunkan" como matéria: você pode Invocar este card por Invocação-Especial da sua mão. \r\nDurante sua Fase Principal: você pode Invocar por Invocação-Especial 1 monstro "Gunkan" da sua mão, exceto "Shirauo do Naviushi Gunkan" e, depois, você pode pegar qualquer número de "Shari do Naviushi Gunkan" do seu Deck ou Cemitério e colocá-los no topo do seu Deck em qualquer ordem. \r\nVocê só pode usar cada efeito de "Shirauo do Naviushi Gunkan" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Colocar "Shari do Naviushi Gunkan" no topo do Deck?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78364470,'Constelar Pólux',replace(replace('Durante o turno em que este card for Invocado por Invocação-Normal, você pode Invocar por Invocação-Normal 1 monstro "Constelar" em adição à sua Invocação-Normal/Baixar padrão. \r\n(Você só pode se aproveitar deste efeito uma vez por turno.)','\r',char(13)),'\n',char(10)),'Invocar pelo efeito de "Constelar Pólux"','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78371393,'Yubel',replace(replace('Não pode ser destruído em batalha. \r\nVocê não sofre dano de batalha das batalhas envolvendo este card. \r\nAntes do cálculo de dano, se este card com a face para cima em Posição de Ataque for escolhido como alvo de um ataque: cause dano ao seu oponente igual ao ATK desse monstro atacante. \r\nUma vez por turno, durante sua Fase Final: ofereça 1 outro monstro como Tributo ou destrua este card. \r\nQuando este card for destruído, exceto por seu próprio efeito: seu dono pode Invocar por Invocação-Especial 1 "Yubel - Encarnação do Terror" da mão, do Deck ou do Cemitério dele.','\r',char(13)),'\n',char(10)),'Causar dano','Destruir','Escolher 1 monstro como Tributo?','Invocação Especial','','','','','','','','','','','','');
INSERT INTO texts VALUES(78387742,'Herói Falso','Invoque por Invocação-Especial 1 monstro "HERÓI do Elemento" da sua mão, mas ele não pode atacar e, além disso, devolva-o para a mão durante a Fase Final.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78391364,'Samurai Superpesado de Escamas',replace(replace('Se seu oponente controlar 2 ou mais monstros e você não controlar nenhum monstro, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 monstro "Samurai Superpesado" de Nível 4 ou menos no seu Cemitério, exceto "Samurai Superpesado de Escamas"; Invoque-o por Invocação-Especial em Posição de Defesa. \r\nVocê só pode usar este efeito de "Samurai Superpesado de Escamas" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Invoque por Invocação Especial um monstro do Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78394032,'Carcaça do Motor',replace(replace('Se este card for enviado do campo para o Cemitério: você pode Invocar por Invocação-Especial 1 "Ficha de Motor" (Máquina/TERRA/Nível 1/ATK 200/DEF 200) em Posição de Ataque. \r\nVocê só pode usar este efeito de "Carcaça do Motor" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78394033,'Ficha de Motor','Invocado por Especial com o efeito "Motor Demoníaco Ω".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78397661,'Ecclesia e o Dragão Negro',replace(replace('1 Regulador + 1+ não-Reguladores	\r\nDurante a Fase Principal (Efeito Rápido): você pode banir este card (até a Fase Final) e, se isso acontecer, Invoque por Invocação-Especial 1 "Caído de Arbaz" ou 1 monstro de Nível 4 ou menos que o mencione do seu Deck ou Cemitério. \r\nSe este card estiver no seu Cemitério: você pode escolher 1 Monstro de Fusão de Nível 8 no seu Cemitério ou banimento e 1 card no campo; embaralhe esses dois cards e este card no Deck. \r\nVocê só pode usar cada efeito de "Ecclesia e o Dragão Negro" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Retornar ao Deck','Banir até a Fase Final','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78402798,'Lagarto Noturno','Um guerreiro lagarto protegido por uma cobertura de escamas de esmeralda muito resistente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78420796,'Frenesi Dinomorfia',replace(replace('Durante a Fase Principal do seu oponente: pague metade dos seus PV; Invoque por Invocação-Fusão 1 Monstro de Fusão "Dinomorfia" do seu Deck Adicional, usando apenas 1 monstro do seu Deck e 1 monstro do seu Deck Adicional como Matéria de Fusão. \r\nQuando seu oponente ativar um card ou efeito, enquanto seus PV forem 2000 ou menos: você pode banir este card do seu Cemitério; neste turno, você não sofre dano de efeito dos efeitos de card do seu oponente. \r\nVocê só pode ativar 1 "Frenesi Dinomorfia" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78422252,'Sabre-XX Cavaleiro Fulelmo',replace(replace('Uma vez enquanto estiver com a face para cima no campo, quando um monstro do oponente declarar um ataque: você pode escolher o monstro atacante; negue o ataque. \r\nSe este card destruir em batalha um monstro do oponente em Posição de Defesa: você pode escolher 1 monstro "Sabre-X" de Nível 4 ou menos no seu Cemitério; Invoque-o por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Negar o ataque','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78423643,'Geedo de Três Cabeças','Um monstro noturno de três cabeças que é absolutamente implacável em combate.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78437364,'Gouki, O Grande Ogro',replace(replace('2+ monstros "Gouki"	\r\nTodos os monstros no campo perdem ATK igual à sua própria DEF original. \r\nSe este card seria destruído em batalha ou por um efeito de card, em vez disso, você pode destruir 1 dos seus monstros para o qual este card apontar.','\r',char(13)),'\n',char(10)),'Usar o efeito de "Gouki, O Grande Ogro" em vez de ser destruído?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78437365,'Gouki, O Grande Ogro',replace(replace('2+ monstros "Gouki"	\r\nTodos os monstros no campo perdem ATK igual à sua própria DEF original. \r\nSe este card seria destruído em batalha ou por um efeito de card, em vez disso, você pode destruir 1 dos seus monstros para o qual este card apontar.','\r',char(13)),'\n',char(10)),'Usar o efeito de "Gouki, O Grande Ogro" em vez de ser destruído?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78447174,'Utensilhor Trollmada',replace(replace('Se você controlar um monstro "Utensilhor": você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe outro "Utensilhor Trollmada" for Invocado por Invocação-Especial no seu campo enquanto você controlar este monstro (exceto durante a Etapa de Dano): você pode Invocar por Invocação-Especial 1 "Utensilhor Trollmada" do seu Deck. \r\nVocê só pode usar cada efeito de "Utensilhor Trollmada" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78449284,'Os Cavaleiros Fantasmas da Foice Malévola',replace(replace('2 monstros de TREVAS de Nível 3	\r\nVocê pode desassociar 1 matéria deste card; Invoque por Invocação-Especial 1 monstro "Os Cavaleiros Fantasmas" do seu Deck. \r\nSe você Invocar um monstro "Dragão Xyz" por Invocação-Xyz, enquanto este card estiver na sua Zona de Monstros (exceto durante a Etapa de Dano): você pode adicionar 1 Magia "Magia de Aumento de Classe" do seu Deck à sua mão. \r\nSe este card for destruído: você pode adicionar à sua mão 1 dos seus cards "Os Cavaleiros Fantasmas" banidos, exceto Monstros Xyz. \r\nVocê só pode usar cada efeito de "Os Cavaleiros Fantasmas da Foice Malévola" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Efeito de busca','Efeito de recuperação','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78474168,'Avanço Habilidoso',replace(replace('Escolha 1 Monstro de Efeito que seu oponente controla; negue os efeitos desse monstro com a face para cima que seu oponente controla até o final deste turno. \r\nDurante o seu turno, exceto no turno em que este card foi enviado para o Cemitério: você pode banir este card do seu Cemitério e, depois, escolha 1 Monstro de Efeito que seu oponente controla; negue os efeitos do alvo até o final deste turno.','\r',char(13)),'\n',char(10)),'Negar o efeito','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78486968,'Constelar Sheratan','Quando este card for Invocado por Invocação-Normal: você pode adicionar 1 monstro "Constelar" do seu Deck para a sua mão.','Procurar no Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78509901,'Lâmina Garoodia, a Besta Cúbica',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro deve ser Invocado por Invocação-Especial (da sua mão) ao enviar 2 monstros "Cúbico(a)" que você controla para o Cemitério. \r\nSe Invocado desta forma, este card ganha 2000 de ATK. \r\nEste card pode realizar um segundo ataque durante cada Fase de Batalha. \r\nQuando este card destruir um monstro em batalha: você pode escolher até 3 "Vijam, a Semente Cúbica" no seu Cemitério; envie este card para o Cemitério e, se isso acontecer, Invoque-os por Invocação-Especial e, depois, você pode adicionar 1 "Gundil Notável, o Behemoth Cúbico" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Adicionar 1 "Gundil Notável, o Behemoth Cúbico" à sua mão?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78512663,'Neos Magma, o HERÓI do Elemento',replace(replace('"Neos, o HERÓI do Elemento" + "Escaravelho de Chamas Neoespacial" + "Grande Toupeira Neoespacial"	\r\nPrimeiro deve ser Invocado por Invocação-Especial (do seu Deck Adicional) ao embaralhar os cards acima que você controla no Deck. \r\n(Você não usa "Polimerização".) \r\nEste card ganha 400 de ATK para cada card no campo. \r\nUma vez por turno, durante a Fase Final: embaralhe este card no Deck Adicional. \r\nSe este card for embaralhado no Deck Adicional desta forma: devolva todos os cards no campo para a mão.','\r',char(13)),'\n',char(10)),'Retornar ao Deck','Retornar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78527720,'Prinzessinha',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode Invocar por Invocação-Especial 1 "Carruagem de Abóbora" da sua mão ou do Deck e, depois, se "Castelo Dourado de Stromberg" estiver em uma Zona do Campo, você pode equipar a este card 1 "Sapatinhos de Cristal" do seu Deck. \r\nVocê só pode usar este efeito de "Prinzessinha" uma vez por turno. \r\nQuando este card causar dano de batalha ao seu oponente em um ataque direto: você pode escolher 1 "Sapatinhos de Cristal" equipado a este card e 1 monstro com a face para cima no campo; equipe esse "Sapatinhos de Cristal" no alvo.','\r',char(13)),'\n',char(10)),'','Equipar "Sapatinhos de Cristal"?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78534861,'Espantagarra Kashtira',replace(replace('Durante a Fase Principal (Efeito Rápido): você pode Invocar este card por Invocação-Especial da sua mão e, se isso acontecer, bana 1 card "Kashtira" ou "Espantagarra" da sua mão ou do Cemitério. \r\nVocê só pode usar este efeito de "Espantagarra Kashtira" uma vez por turno. \r\nEste card pode atacar enquanto estiver com a face para cima em Posição de Defesa. \r\nSe o fizer, use sua DEF para o cálculo de dano. \r\nSe um monstro "Kashtira" ou "Espantagarra" seu batalhar um monstro do oponente, os efeitos desse monstro do oponente são negados até o final deste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78540593,'Mariña, Princesa dos Girassóis',replace(replace('Se exatamente 1 outro monstro Planta que você controla (e nenhum outro card) for destruído em batalha ou por um efeito de card e enviado para o Cemitério: você pode escolher 1 card que seu oponente controla; destrua o alvo. \r\nEste card deve estar com a face para cima no campo para ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78543464,'Maldição Kuji-Kiri',replace(replace('Envie 1 monstro de Nível 9 da sua mão ou do campo com a face para cima para o Cemitério; compre 2 cards. \r\nVocê só pode ativar 1 "Maldição Kuji-Kiri" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78552773,'Supay','Quando este card for enviado do campo para o Cemitério por um efeito de card: você pode Invocar por Invocação-Especial 1 "Oráculo do Sol" do seu Deck e, se isso acontecer, dobre o ATK dele e, além disso, devolva-o para a mão durante a Fase Final deste turno.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78556320,'Vishwar Randi','Essa guerreira com uma insaciável sede de sangue serve às forças das trevas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78564023,'Asanegra - Etesian, as Duas Espadas','Se um monstro "Asanegra" que você controla batalhar um monstro do oponente e seu oponente ainda controlar esse monstro no final da Etapa de Dano: você pode enviar este card da sua mão para o Cemitério; cause 1000 de dano ao seu oponente.','Cause 1000 de dano ao seu oponente','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78574395,'Bexigas Maravilhosas',replace(replace('Uma vez por turno: você pode enviar qualquer número de cards da sua mão para o Cemitério; coloque 1 Marcador de Bexiga neste card para cada card enviado para o Cemitério. \r\nTodos os monstros que seu oponente controla perdem 300 de ATK para cada Marcador de Bexiga neste card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78577570,'Juramento da Espada Garma',replace(replace('Este card é usado na Invocação-Ritual de "Espada Garma". \r\nVocê também deve oferecer como Tributo monstros do campo ou da sua mão cuja soma dos Níveis seja igual a 7 ou mais.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78579058,'Levia-Dragoon - Daedalus',replace(replace('3 monstros ÁGUA	\r\nO nome deste card se torna "Umi" enquanto está na Zona de Monstros.\r\nVocê só pode usar cada um dos seguintes efeitos de "Levia-Dragoon - Daedalus" uma vez por turno.\r\nSe este card for Invocado por Invocação-Link: você pode Invocar por Invocação-Especial 1 monstro que mencione "Atlantis, a Cidade do Dragão" do seu Deck.\r\nDurante a Fase Principal (Efeito Rápido): você pode enviar 1 "Umi" com a face para cima que você controla para o Cemitério; descarte a mão do seu oponente, e se fizer, ele compra a mesma quantia de cards. \r\nNenhum jogador pode ativar cards ou efeitos em resposta a ativação deste efeito.','\r',char(13)),'\n',char(10)),'Aplicar como Link-2 para uma Invocação-Link (Levia-Dragoon - Daedalus)','Invocação Especial','Seu oponente descarta e compra','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78586116,'Adaptador de Energia',replace(replace('Depois da ativação, considere este card como um Card de Equipamento e equipe-o a 1 monstro "Morfotrônico(a)" com a face para cima que você controla. \r\nO monstro equipado não pode atacar. \r\nDepois, selecione 1 monstro com a face para cima no campo, exceto o monstro equipado. \r\nEle ganha ATK igual ao ATK do monstro equipado.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78598237,'Intonare Vaalmônica',replace(replace('Aplique 1 desses efeitos. \r\nA não ser que você tenha um card "Vaalmônica" na sua Zona de Pêndulo, seu oponente seleciona o efeito.\r\n● Ganhe 500 PV e, depois, se você tiver quaisquer monstros no seu Cemitério que possam ser Invocados por Invocação-Especial, seu oponente seleciona 1 para que você Invoque por Invocação-Especial no seu campo.\r\n● Sofra 500 de dano e, depois, você pode adicionar 1 monstro de Nível 4 do seu Cemitério à sua mão.	\r\nVocê só pode ativar 1 "Intonare Vaalmônica" por turno.','\r',char(13)),'\n',char(10)),'','Ganhe 500 PV','Receba 500 de dano','Adicionar à sua mão 1 monstro de Nível 4 do seu Cemitério?','','','','','','','','','','','','');
INSERT INTO texts VALUES(78610936,'Bis Xyz',replace(replace('Escolha 1 Monstro Xyz com a face para cima que seu oponente controla que tenha alguma matéria; desassocie todas as matérias dele e, se isso acontecer, devolva-o para o Deck Adicional e, depois, se houver um Card de Monstro no Cemitério entre essas matérias desassociadas, Invoque por Invocação-Especial tantos desses monstros quanto possível do Cemitério para o campo do seu oponente com a face para cima em Posição de Defesa. \r\nO Nível deles no campo é reduzido em 1. \r\nNenhum duelista pode ativar cards ou efeitos em resposta à ativação deste card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78613627,'Canguru Des','Se o ATK de um monstro que estiver atacando este monstro for menor que a DEF deste card, destrua o monstro atacante.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78621186,'Uivo do Guarda de Batalha','Quando um monstro Guerreiro que você controla for escolhido como alvo de um ataque ou de um efeito de monstro do oponente: escolha 1 monstro com a face para cima que seu oponente controla; cause dano ao seu oponente igual ao ATK original do monstro com a face para cima que você escolheu como alvo deste card e, se isso acontecer, devolva-o para a mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78625448,'Número 3: Portão Numeron Trini',replace(replace('3 monstros de Nível 1	\r\nNão pode ser destruído em batalha. \r\nNo final da Etapa de Dano, se este card batalhou um monstro do oponente: você pode desassociar 1 matéria deste card; até o final deste turno, dobre o ATK de todos os monstros "Numeron" que você controla atualmente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78625592,'Espadas Espirituais da Luz Reveladora',replace(replace('Uma vez por ataque, quando um monstro do oponente declarar um ataque: você pode pagar 1000 PV; negue o ataque. \r\nDurante o turno do seu oponente: você pode banir este card do seu Cemitério; neste turno, os monstros do seu oponente não podem atacar diretamente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78636495,'Guerreiro de Ardósia',replace(replace('VIRE: Este card ganha 500 de ATK e DEF.\r\nSe este card for destruído em batalha: o monstro que o destruiu perde 500 de ATK e DEF.','\r',char(13)),'\n',char(10)),'Aumentar ATK/DEF em 500','ATK/DEF reduzem em 500','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78637313,'Chamado das Trevas','Todos os monstros restaurados com "Reviver Monstro" são enviados ao Cemitério. "Reviver Monstro" também não pode ser usado enquanto este card permanecer no campo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78642798,'Ídolo dos Olhos Dourados',replace(replace('Uma vez por turno (Efeito Rápido): você pode ativar este efeito; olhe a mão do seu oponente e, além disso, o nome deste card se torna "Ídolo dos Mil Olhos" até a Fase Final. \r\nSe este card for banido ou enviado para o Cemitério devido a um efeito de card: você pode escolher 1 Monstro de Efeito que seu oponente controla; equipe esse Monstro de Efeito a 1 monstro "Restrição do" ou "Renunciado" que você controla que não possa ser Invocado por Invocação-Normal. \r\nEnquanto estiver equipado por este efeito, esse monstro ganha ATK igual ao ATK do monstro equipado. \r\nVocê só pode usar este efeito de "Ídolo dos Olhos Dourados" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78651105,'Rei das Bestas Bárbaros',replace(replace('Você pode Invocar este card por Invocação-Normal/Baixar sem oferecer Tributo, mas seu ATK original se torna 1900. \r\nVocê pode oferecer 3 monstros como Tributo para Invocar este card por Invocação-Tributo (mas não para Baixar). \r\nSe Invocado desta forma: destrua todos os cards que seu oponente controla.','\r',char(13)),'\n',char(10)),'Invocação Normal sem Tributo','Ofereça 3 monstros como Tributo para Invocar','Destruir todos os cards que seu oponente controla','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78658564,'Força de Ataque dos Goblins','Se este card atacar, ele é colocado em Posição de Defesa no final da Fase de Batalha e sua posição de batalha não pode ser mudada até a Fase Final do seu próximo turno.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78661338,'Dragão Fantástico Fantazmei',replace(replace('Se seu oponente Invocar um ou mais Monstros Link por Invocação-Especial (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão, compre cards igual ao número de Monstros Link que seu oponente controla +1 e, depois, embaralhe cards da sua mão no Deck igual ao número de Monstros Link que ele controla. \r\nQuando seu oponente ativar um card ou efeito que escolha como alvo um ou mais monstros que você controla (Efeito Rápido): você pode descartar 1 card; negue a ativação e, se isso acontecer, destrua-o. \r\nVocê só pode usar cada efeito de "Dragão Fantástico Fantazmei" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78661339,'Dragão Fantástico Fantazmei',replace(replace('Se seu oponente Invocar um ou mais Monstros Link por Invocação-Especial (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão, compre cards igual ao número de Monstros Link que seu oponente controla +1 e, depois, embaralhe cards da sua mão no Deck igual ao número de Monstros Link que ele controla. \r\nQuando seu oponente ativar um card ou efeito que escolha como alvo um ou mais monstros que você controla (Efeito Rápido): você pode descartar 1 card; negue a ativação e, se isso acontecer, destrua-o. \r\nVocê só pode usar cada efeito de "Dragão Fantástico Fantazmei" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78663366,'Hordeum Maligno Pássaro-trovão',replace(replace('Durante o turno de qualquer duelista, quando um card ou efeito for ativado (exceto durante a Etapa de Dano): você pode banir este card que você controla. \r\nDurante a próxima Fase de Apoio, volte este card banido pelo efeito deste card para o campo e, se isso acontecer, ele ganha 300 de ATK. \r\nVocê só pode usar este efeito de "Hordeum Maligno Pássaro-trovão" uma vez por turno.','\r',char(13)),'\n',char(10)),'Banir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78665705,'Cântico Antigo',replace(replace('Adicione 1 "O Dragão Alado de Rá" do seu Deck ou Cemitério à sua mão e, se isso acontecer, você pode Invocar 1 monstro por Invocação-Tributo durante sua Fase Principal deste turno, em adição à sua Invocação-Normal/Baixar (padrão). \r\n(Você só pode se aproveitar deste efeito uma vez por turno.) \r\nVocê pode banir este card do seu Cemitério: se você Invocar "O Dragão Alado de Rá" por Invocação-Tributo neste turno, seu ATK/DEF originais se tornam o ATK/DEF originais combinados dos monstros oferecidos como Tributo para sua Invocação. \r\nVocê só pode ativar 1 "Cântico Antigo" por turno.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Preparar para alterar ATK/DEF','Invocação por Tributo pelo efeito de "Cântico Antigo"','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78679226,'Silêncio Futuro',replace(replace('Adicione 1 monstro que mencione "Sarcófago Brilhante" do seu Deck à sua mão e, depois, se você ativou este card durante a Fase de Batalha enquanto você controlava "Sarcófago Brilhante" e um monstro que o mencione, cada duelista compra até ter 6 cards em sua mão. \r\nVocê só pode ativar 1 "Silêncio Futuro" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78693036,'Juraishin, o Deus Amaldiçoado do Trovão',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nSempre que seu oponente ativar um card ou efeito, ganhe 300 PV quando ele resolver. \r\nDurante o turno do seu oponente (Efeito Rápido): você pode pagar 1500 PV e oferecer este card como Tributo e, depois, ative 1 desses efeitos;\r\n● Destrua todos os monstros com a face para cima que seu oponente controla.\r\n● Destrua todas as Magias e Armadilhas com a face para cima que seu oponente controla.	\r\nVocê só pode usar este efeito de "Juraishin, o Deus Amaldiçoado do Trovão" uma vez por turno.','\r',char(13)),'\n',char(10)),'Efeito de destruição','Destruir 1 monstro','Destruir Magia/Armadilha','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78697395,'O Terceiro Sarcófago','Este card só pode ser colocado no campo pelo efeito de "O Primeiro Sarcófago".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78700060,'Cavaleiro Calibre da Condenação',replace(replace('Não pode ser Invocado por Invocação-Especial. \r\nSe um efeito de monstro for ativado (Efeito Rápido): ofereça este card com a face para cima como Tributo; negue a ativação e, se isso acontecer, destrua esse monstro.','\r',char(13)),'\n',char(10)),'Não pode ser Invocado por Invocação Especial','Negue a ativação de um efeito de monstro e destrua-o','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78706415,'Jarro de Fibra','VIRE: Cada duelista embaralha todos os cards da sua mãos, campo e Cemitério no Deck e, depois, compra 5 cards.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78710386,'Doca do Funk R.B.',replace(replace('Quando este card for ativado: adicione 1 card "R.B." do seu Deck à sua mão, exceto "Doca do Funk R.B.". \r\nSempre que um ou mais monstros que seu oponente controla forem destruídos em batalha ou por um efeito de card, ganhe 500 PV. \r\nSe um ou mais monstros "R.B." com a face para cima que você controla deixarem o campo devido a um efeito de card (exceto durante a Etapa de Dano): você pode Invocar por Invocação-Especial 1 monstro "R.B." do seu Deck. \r\nVocê só pode usar este efeito de "Doca do Funk R.B." uma vez por turno. \r\nVocê só pode ativar 1 "Doca do Funk R.B." por turno.','\r',char(13)),'\n',char(10)),'','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78734254,'Golfinho Marinho Neoespacial',replace(replace('O nome deste card também é considerado como "Golfinho Aqua Neoespacial". 	\r\nEste card não pode ser Invocado por Invocação-Especial, exceto com "NEX". \r\nUma vez por turno, você pode descartar 1 card para olhar a mão do seu oponente e selecionar 1 Card de Monstro nela. \r\nSe você controlar um monstro com um ATK maior ou igual ao do monstro escolhido, destrua o card escolhido e cause 500 de dano ao seu oponente.','\r',char(13)),'\n',char(10)),'Revelar a mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78744660,'Matriarca Arquidemônio',replace(replace('Escala de Pêndulo = 9\r\n[ Efeito de Pêndulo ]\r\nVocê pode escolher 1 Magia/Armadilha "Arquidemônio" no seu Cemitério ou banimento; destrua este card e, se isso acontecer, adicione o alvo à sua mão. \r\nVocê só pode usar este efeito de "Matriarca Arquidemônio" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nVocê pode Invocar este card por Invocação-Ritual com "Trono dos Arquidemônios". \r\nDeve ser Invocado por Invocação-Ritual. \r\nNão é afetado por outros efeitos de monstro enquanto estiver na Zona de Monstros Adicional. \r\nSe este card for Invocado por Invocação-Ritual: você pode destruir tantas Magias/Armadilhas que seu oponente controla quanto possível e, depois, se este card estiver na Zona de Monstros Adicional, você pode banir todas as Magias/Armadilhas do Cemitério do seu oponente. \r\nVocê só pode usar este efeito de "Matriarca Arquidemônio" uma vez por turno.','\r',char(13)),'\n',char(10)),'Efeito de recuperação','Efeito de destruição','Banir?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78748366,'Esmaecimento do Vácuo',replace(replace('Você pode descartar 1 card; adicione 1 Magia/Armadilha "Vácuo" do seu Deck à sua mão, exceto "Esmaecimento do Vácuo", e, além disso, você não pode Invocar por Invocação-Normal ou Especial pelo resto deste turno, exceto monstros "Infernoide". \r\nVocê só pode usar este efeito de "Esmaecimento do Vácuo" uma vez por turno. \r\nSe um monstro "Infernoide" que você controla batalhar um monstro do oponente, depois do cálculo de dano: você pode enviar este card para o Cemitério; bana esses monstros.','\r',char(13)),'\n',char(10)),'Procurar no Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78751195,'Doshin @Ignister',replace(replace('Se você controlar um monstro "@Ignister": você pode Invocar este card por Invocação-Especial da sua mão. \r\nVocê pode escolher 1 Monstro Link Ciberso no seu Cemitério; devolva-o para o Deck Adicional e, se isso acontecer, adicione 1 "Fusão Amorosa I.A." do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "Doshin @Ignister" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78765160,'Samsara do Estilo Shiranui',replace(replace('O nome deste card se torna "Síntese do Estilo Shiranui" enquanto ele estiver na Zona de Magias & Armadilhas. \r\nUma vez por turno: você pode ativar 1 desses efeitos.\r\n● Bana 1 monstro do Tipo Zumbi com a face para cima que você controla; você não sofre dano neste turno (mesmo que este card deixe o campo).\r\n● Escolha 2 dos seus monstros do Tipo Zumbi banidos com DEF 0; embaralhe os dois no Deck e, depois, compre 1 card.','\r',char(13)),'\n',char(10)),'Banir e fazer o dano se tornar 0','Reciclar e comprar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78778375,'Baleia Cruel Peladura',replace(replace('1 monstro "Diabrete de" + 1 monstro "Fofanimal"	\r\nSe este card for Invocado por Invocação-Fusão: você pode destruir 1 card no campo dos dois duelistas. \r\nUma vez por turno (Efeito Rápido): você pode escolher 1 Monstro de Fusão que você controla; envie 1 card "Peladura" do seu Deck ou Deck Adicional para o Cemitério, exceto "Baleia Cruel Peladura" e, se isso acontecer, até o final deste turno, o monstro alvo ganha ATK igual à metade do seu ATK original.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78780140,'Trent','Um guardião das florestas. Acredita-se que esta árvore sólida é imortal.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78783370,'O Barril por detrás da Porta','Quando um Card de Magia/Armadilha, ou efeito de monstro, for ativado que causaria dano a você: em vez disso, seu oponente sofre o dano.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78783557,'Veidos, o Dragão de Erupção da Extinção',replace(replace('Durante a Fase Principal, se este card estiver na sua mão (Efeito Rápido): você pode escolher 1 card em uma Zona do Campo; Invoque este card por Invocação-Especial no campo do seu oponente e, se isso acontecer, destrua esse card e, depois, você pode adicionar à sua mão ou Baixar 1 Armadilha Contínua "Cinzento(a)" do seu Deck. \r\nSe este card for enviado do campo do seu oponente para o seu Cemitério: você pode destruir todos os monstros no campo. \r\nVocê só pode usar cada efeito de "Veidos, o Dragão de Erupção da Extinção" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Destruir 1 monstro','Não fazer nada','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78785392,'Reunião de Flores',replace(replace('Invoque por Invocação-Especial 4 monstros "Flor Cardian" com 100 de ATK e nomes diferentes do seu Deck em Posição de Ataque, mas seus efeitos são negados e, além disso, eles não podem ser oferecidos como Tributo para uma Invocação-Tributo. \r\nVocê só pode ativar 1 "Reunião de Flores" por turno. \r\nVocê não pode Invocar outros monstros por Invocação-Normal ou Especial durante o turno em que ativar este card, exceto monstros "Flor Cardian".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78789356,'Aurora Ogdoádica',replace(replace('Ofereça como Tributo 1 monstro Réptil; para cada 2 Níveis que esse monstro oferecido como Tributo tinha no campo, Invoque por Invocação-Especial até 1 "Ficha de Ogdoádico" (Réptil/TREVAS/Nível 2/ATK 0/DEF 0). \r\nDurante sua Fase Principal: você pode banir este card do seu Cemitério e, depois, escolha 1 dos seus monstros Réptil banidos; embaralhe-o no Deck e, depois, você pode enviar 1 monstro Réptil do seu Deck para o Cemitério. \r\nVocê só pode usar cada efeito de "Aurora Ogdoádica" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Enviar 1 monstro Réptil do seu Deck para o Cemitério?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78789357,'Ficha de Ogdoádico','Invocado por Especial com o efeito "Chamado Ogdoádico".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78792195,'Mão dos Seis Samurai','Se você controlar outro monstro "Seis Samurai": você pode oferecer como Tributo 1 monstro "Seis Samurai" e, depois, escolher 1 monstro no campo; destrua o alvo.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78794994,'Símbolos do Devir',replace(replace('Envie 1 Monstro Normal que você controla para o Cemitério e, depois, escolha 1 monstro no Cemitério de qualquer duelista; Invoque-o por Invocação-Especial e, se isso acontecer, equipe este card a ele. \r\nQuando este card deixar o campo, destrua o monstro equipado.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78811937,'Escuridão Rastejante','Bana 2 monstros de TREVAS do seu Cemitério; adicione 1 monstro de TREVAS de Nível 4 do seu Deck à sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78835747,'Kaleidoscorpião Camarartista',replace(replace('Escala de Pêndulo = 4\r\n[ Efeito de Pêndulo ]\r\nTodos os monstros de LUZ que você controla ganham 300 de ATK.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nUma vez por turno: você pode escolher 1 monstro com a face para cima que você controla; neste turno, ele pode atacar todos os monstros Invocados por Invocação-Especial que seu oponente controla, uma vez cada.','\r',char(13)),'\n',char(10)),'Ataques múltiplos','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78836195,'Avaliação Espadalma',replace(replace('Escolha 1 monstro com a face para cima que você controla; bana até 5 cards "Espadalma" e/ou monstros Wyrm do seu Cemitério e, se isso acontecer, esse monstro ganha 300 de ATK para cada card banido desta forma. \r\nSe este card for banido: você pode Invocar por Invocação-Especial 1 "Ficha de Espadalma" (Wyrm/Regulador/ÁGUA/Nível 4/ATK 0/DEF 0). \r\nEnquanto essa Ficha estiver na Zona de Monstros, o duelista que a Invocou não pode Invocar monstros do Deck Adicional por Invocação-Especial, exceto Monstros Sincro. \r\nVocê só pode usar cada efeito de "Avaliação Espadalma" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78836196,'Ficha de Espadalma','Invocado por Especial com o efeito de um card "Espadalma".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78845026,'Regulagem de Ondas de Luz',replace(replace('Escolha 1 monstro de LUZ de Nível 4 que você controla. \r\nEle é considerado como um monstro Regulador enquanto estiver com a face para cima no campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78859567,'Pacote Link',replace(replace('Durante a Fase Principal 2: Invoque por Invocação-Especial qualquer número de monstros de Nível 2 ou menos com nomes diferentes da sua mão, do Deck e/ou do Cemitério em uma ou mais zonas suas para as quais um ou mais Monstros Link apontarem. \r\nVocê só pode ativar 1 "Pacote Link" por turno.','\r',char(13)),'\n',char(10)),'Continuar selecionando?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78861134,'Soldado do Fogo Negro #2','Um guerreiro que ganhou um poder imensurável do coração de um vulcão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78864369,'Revertir Alma','Devolva 1 Monstro com Efeito de Virar do seu Cemitério para o topo do seu Deck.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78868119,'Diva do Mar Profundo','Quando este card for Invocado por Invocação-Normal: você pode Invocar por Invocação-Especial 1 monstro Serpente Marinha de Nível 3 ou menos do seu Deck.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78868776,'Besta Gladiadora Laquari',replace(replace('Se este card foi Invocado por Invocação-Especial pelo efeito de um monstro "Besta Gladiadora", seu ATK original se torna 2100. \r\nNo final da Fase de Batalha, se este card batalhou: você pode embaralhá-lo no Deck; Invoque por Invocação-Especial 1 monstro "Besta Gladiadora" do seu Deck, exceto "Besta Gladiadora Laquari".','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78872731,'Florato Zoodíaco',replace(replace('Se este card for Invocado por Invocação-Normal: você pode enviar 1 card "Zoodíaco(a)" do seu Deck para o Cemitério. \r\nUm Monstro Xyz cujo Tipo original seja Besta-Guerreira e que tenha este card como Matéria Xyz ganha este efeito.\r\n● Uma vez por turno: você pode desassociar 1 Matéria Xyz deste card; Invoque por Invocação-Especial 1 "Florato Zoodíaco" da sua mão ou Deck.','\r',char(13)),'\n',char(10)),'Enviar 1 card "Zoodíaco(a)" do seu Deck para o Cemitério','Invoque "Florato Zoodíaco" por Invocação Especial (Florato Zoodíaco)','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78876707,'Nobre Cavaleiro Sagrado do Rei Custennin',replace(replace('2+ monstros "Nobre Cavaleiro" de Nível 4	\r\nVocê pode desassociar qualquer número de matérias deste card e, depois, escolher o mesmo número de cards que seu oponente controla; devolva-os para a mão. \r\nSe este card for destruído em batalha ou por um efeito de card e enviado para o Cemitério: você pode Invocar por Invocação-Especial 1 Monstro Xyz "Nobre Cavaleiro" do seu Deck Adicional, exceto "Nobre Cavaleiro Sagrado do Rei Custennin" e, se isso acontecer, associe este card do Cemitério a esse monstro como matéria. \r\n(Isso é considerado uma Invocação-Xyz.) \r\nVocê só pode usar cada efeito de "Nobre Cavaleiro Sagrado do Rei Custennin" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78888899,'Centur-Ião Emeth VI',replace(replace('Durante o turno do seu oponente, se este card estiver na sua mão ou no Cemitério (Efeito Rápido): você pode escolher 1 monstro "Centur-Ião" que você controla, exceto "Centur-Ião Emeth VI"; coloque-o na sua Zona de Magias & Armadilhas como uma Armadilha Contínua com a face para cima e, se isso acontecer, Invoque este card por Invocação-Especial e, além disso, você não pode Invocar "Centur-Ião Emeth VI" por Invocação-Especial pelo resto deste turno. \r\nDurante a Fase Principal, se este card for uma Armadilha Contínua: você pode Invocar este card por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Centur-Ião Emeth VI" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78905039,'Tricórnio, o Concerto Cacofônico',replace(replace('Se um ou mais monstros em sua posse forem destruídos em batalha ou por um efeito de card: você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe este card for enviado do campo para o Cemitério: você pode escolher 1 monstro no seu Cemitério com o mesmo Tipo e o mesmo Atributo de um monstro que você controla; adicione esse monstro à sua mão. \r\nVocê só pode usar cada efeito de "Tricórnio, o Concerto Cacofônico" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78910579,'Ciclo Aqua-espelhado','Escolha 1 monstro de ÁGUA que você controla e 2 monstros de ÁGUA no seu Cemitério; embaralhe o primeiro alvo no Deck e, se isso acontecer, adicione os segundos alvos à sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78910832,'Vic Viper Type-L',replace(replace('No começo da sua Fase de Batalha: você pode ativar 1 desses efeitos;\r\n● Invoque por Invocação-Especial 1 monstro Máquina da sua mão.\r\n● Envie 1 monstro Máquina de LUZ de Nível 4 ou menos do seu Deck para o Cemitério.	\r\nSe este card for destruído: você pode escolher 1 monstro Máquina de LUZ no seu Cemitério; Invoque-o por Invocação-Especial e, se você Invocou por Invocação-Especial um monstro com 1200 ou menos de ATK original, ele ganha 1200 de ATK. \r\nVocê só pode usar cada efeito de "Vic Viper Type-L" uma vez por turno.','\r',char(13)),'\n',char(10)),'Escolher um efeito','Invocação Especial','Invocação Especial','Enviar para o Cemitério','','','','','','','','','','','','');
INSERT INTO texts VALUES(78917791,'Xamã dos Tenyi',replace(replace('2 monstros Wyrm	\r\nVocê pode descartar 1 card e, depois, escolha 1 monstro Wyrm no seu Cemitério; Invoque-o por Invocação-Especial e, além disso, pelo resto deste turno, você não pode ativar os efeitos de monstros Invocados por Invocação-Especial do Deck Adicional, exceto monstros "Tenyi". \r\nQuando um ataque for declarado envolvendo um Monstro seu que não seja de Efeito com a face para cima: você pode escolher 1 card que seu oponente controla; destrua-o. \r\nVocê só pode usar cada efeito de "Xamã dos Tenyi" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Destruir 1 card','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78922939,'Servo Sucata','Se você controlar um monstro "Sucata", você pode Invocar este card por Invocação-Especial (da sua mão).','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78933589,'Caldo Primordial',replace(replace('Uma vez por turno, durante sua Fase Principal: Você pode embaralhar até 2 monstros "Evolssauro" da sua mão no Deck e, depois, comprar o mesmo número de cards. \r\nVocê só pode controlar 1 "Caldo Primordial" com a face para cima.','\r',char(13)),'\n',char(10)),'Trocar mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78936551,'Shafu, o Mayakashi com Rodas',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 monstro "Mayakashi" no seu Cemitério, exceto "Shafu, o Mayakashi com Rodas"; Invoque-o por Invocação-Especial em Posição de Defesa, mas negue seus efeitos. \r\nVocê só pode usar este efeito de "Shafu, o Mayakashi com Rodas" uma vez por turno. \r\nVocê não pode Invocar monstros por Invocação-Especial do Deck Adicional, exceto monstros "Mayakashi".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78942513,'Purusombraneco Éon','Escolha 1 monstro "Sombraneco" que você controla; envie 1 card "Sombraneco" da sua mão para o Cemitério e, se isso acontecer, o monstro alvo ganha 1000 de ATK/DEF, mas é colocado com a face para baixo em Posição de Defesa durante a Fase Final.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78949372,'Supercélula Majespectro',replace(replace('Enquanto você tiver um card "Majespectro" na sua Zona de Pêndulo, a ativação e os efeitos de outros cards "Majespectro" ativados no seu lado do campo não podem ser negados. \r\nUma vez por turno: você pode escolher 5 cards "Majespectro" no seu Cemitério; embaralhe os 5 no Deck e, depois, compre 1 card.','\r',char(13)),'\n',char(10)),'Recuperar do Cemitério','Ativar e aplicar o efeito','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78984772,'Dragão de Fogo de Duas Cabeças','Dois dragões fundidos num só graças aos efeitos do Big Bang.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78986941,'Ordem de Carga','Escolha 1 Monstro Normal que não seja uma Ficha que você controla; ofereça esse Monstro Normal como Tributo e, se isso acontecer, destrua 1 monstro que seu oponente controla.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78990927,'Megálito Phul',replace(replace('Você pode Invocar este card por Invocação-Ritual com um card "Megálito". \r\nSe este card for Invocado por Invocação-Ritual: você pode escolher 1 Monstro de Ritual no seu Cemitério; o Nível deste card se torna o Nível desse alvo e, depois, adicione o alvo à sua mão. \r\nDurante a Fase Principal (Efeito Rápido): você pode ativar este efeito; Invoque por Invocação-Ritual 1 Monstro de Ritual "Megálito" da sua mão ou do Deck ao oferecer monstros como Tributo da sua mão ou do campo cuja soma dos Níveis seja igual ou exceda o Nível do Monstro de Ritual. \r\nVocê só pode usar cada efeito de "Megálito Phul" uma vez por turno.','\r',char(13)),'\n',char(10)),'Alterar o Nível','Invocação Ritual','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79015062,'Conexão I.A.',replace(replace('Revele 1 monstro Ciberso na sua mão; aplique este efeito de acordo com o Atributo dele e, além disso, você não pode Invocar por Invocação-Especial pelo resto deste turno depois que este card resolver, exceto monstros Ciberso.\r\n● TREVAS: Invoque o monstro revelado por Invocação-Especial e, se isso acontecer, adicione 1 monstro Ciberso de Nível 4 ou menos que não seja de TREVAS do seu Deck à sua mão.\r\n● Outro: Embaralhe o monstro revelado no Deck e, se isso acontecer, adicione 1 monstro "@Ignister" com um Atributo diferente do seu Deck à sua mão.	\r\nVocê só pode ativar 1 "Conexão I.A." por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79016563,'Feiticeira Binária',replace(replace('2 monstros, exceto Fichas	\r\nGanha esses efeitos de acordo com o número de monstros co-linkados a este card.\r\n● 1+: Quando um monstro co-linkado a este card batalhar um monstro do seu oponente e causar dano de batalha a ele: você pode ganhar esse tanto de PV.\r\n● 2: Uma vez por turno (Efeito Rápido): você pode escolher 2 monstros com a face para cima que você controla; até o final deste turno, diminua pela metade o ATK de 1 monstro e, se isso acontecer, adicione esse ATK perdido ao outro monstro.','\r',char(13)),'\n',char(10)),'Recuperar PV','Aumentar ATK','Escolha 1 monstro cujo ATK se tornará metade','Escolha 1 monstro cujo ATK aumentará','','','','','','','','','','','','');
INSERT INTO texts VALUES(79059098,'Pandemônio dos Travesso-Guris',replace(replace('Durante a Fase Principal: Invoque por Invocação-Fusão 1 Monstro de Fusão "Travesso-Guris" do seu Deck Adicional, usando monstros da sua mão ou do campo como Matéria de Fusão. \r\nPelo resto deste turno depois que este card resolver, você não pode Invocar monstros por Invocação-Normal ou Especial, exceto monstros "Travesso-Guris".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79068663,'Barragem Sucata','Quando o monstro equipado destruir um monstro em batalha e enviá-lo para o Cemitério: cause dano ao seu oponente igual a metade do ATK do monstro destruído no Cemitério.','Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79072916,'Explosão Miutante',replace(replace('Só pode ser equipado a um monstro "Miutante" de Nível 8 ou mais que você controla. \r\nNo começo da Etapa de Dano, se o monstro equipado atacar um monstro Invocado por Invocação-Especial do oponente: você pode banir esse monstro do oponente. \r\nEnquanto este card estiver equipado a um monstro: você pode banir este card; envie o monstro ao qual este card estava equipado para o Cemitério e, se isso acontecer, Invoque por Invocação-Especial 1 monstro "Miutante" de Nível 8 com um Atributo original diferente da sua mão ou do Deck. \r\nVocê só pode usar este efeito de "Explosão Miutante" uma vez por turno.','\r',char(13)),'\n',char(10)),'Banir 1 monstro','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79080761,'Gigapedra Ômega',replace(replace('Este card não pode ser Invocado por Invocação-Normal ou Baixado. \r\nEste card só pode ser Invocado por Invocação-Especial ao remover de jogo 2 monstros de TERRA do seu Cemitério. \r\nQuando este card com a face para cima que você controla for enviado para o Cemitério por um efeito de card, destrua todos os Cards de Magia e Armadilha que seu oponente controla.','\r',char(13)),'\n',char(10)),'Destruir todos os Cards de Magia/Armadilha que seu oponente controla','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79086452,'Engenhoca Marionete Boneca de Porcelana',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) ao descartar 1 monstro "Engenhoca Marionete". \r\nVocê pode banir este card do seu Cemitério; seu oponente não pode escolher monstros "Engenhoca Marionete" que você controla como alvo de efeitos de card neste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79094383,'Etranho Críptico',replace(replace('Se este card estiver na sua mão ou no Cemitério: você pode escolher 1 Monstro Xyz "Críptico(a)" que você controla; associe este card a ele como uma Matéria Xyz. \r\nSe este card for enviado para o Cemitério: você pode adicionar 1 Card de Magia/Armadilha "Críptico(a)" do seu Deck à sua mão. \r\nVocê só pode usar 1 efeito de "Etranho Críptico" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Usar este card como Matéria Xyz','Adicionar 1 Card de Magia/Armadilha "Críptico(a)" à sua mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79106360,'Jarro da Metamorfose #2',replace(replace('VIRE: Embaralhe no Deck todos os monstros que estão no campo. \r\nDepois, cada duelista escava cards do topo do seu Deck, até escavar o mesmo número de monstros que embaralhou no seu respectivo Deck Principal. \r\nInvoque por Invocação-Especial todos os monstros escavados de Nível 4 ou menos com a face para baixo em Posição de Defesa e, além disso, envie os cards restantes para o Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79109599,'Rei do Pântano',replace(replace('Este card na sua mão, no campo ou no Cemitério pode ser usado como um substituto para qualquer 1 Matéria de Fusão cujo nome seja mencionado no Card de Monstro de Fusão, mas as outras matérias devem estar corretas. \r\nVocê pode descartar este card para o Cemitério; adicione 1 "Polimerização" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79126789,'Broww, Caçador do Mundo Negro','Se este card for descartado para o Cemitério por um efeito de card: compre 1 card, ou, se ele foi descartado da sua mão para o seu Cemitério por um efeito de card do oponente, em vez disso, compre 2 cards.','Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79130389,'Marincesa Anêmona Coral',replace(replace('2 monstros de ÁGUA	\r\nVocê pode escolher 1 monstro de ÁGUA com 1500 ou menos de ATK no seu Cemitério; Invoque-o por Invocação-Especial em uma zona sua para a qual este card apontar e, além disso, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros de ÁGUA. \r\nSe este card for enviado do campo para o Cemitério: você pode escolher 1 card "Marincesa" no seu Cemitério, exceto "Marincesa Anêmona Coral"; adicione-o à sua mão. \r\nVocê só pode usar cada efeito de "Marincesa Anêmona Coral" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79155167,'Explosão de Armadura','Escolha 1 card "Inzektor" com a face para cima que você controla e 2 cards com a face para cima que seu oponente controla; destrua-os.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79161790,'Inverter Universo','Troque o ATK e a DEF de todos os Monstros de Efeito com a face para cima no campo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79169622,'Fera Glacial Pinguim Polar',replace(replace('Se este card for Invocado por Invocação-Especial: você pode escolher 1 monstro que seu oponente controla; devolva-o para a mão. \r\nSe este card no campo for destruído em batalha ou por um efeito de card: você pode escolher 1 card que seu oponente controla; devolva-o para a mão. \r\nVocê só pode usar 1 efeito de "Fera Glacial Pinguim Polar" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79176962,'Striborg Ventástico',replace(replace('Monstros oferecidos como Tributo para a Invocação-Tributo deste card com a face para cima são devolvidos para a mão em vez de irem para o Cemitério. \r\nUma vez por turno: você pode descartar 1 card; devolva todos os cards que seu oponente controla na coluna deste card para a mão dele.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79178930,'Klock Karakuri',replace(replace('Só pode ser ativado quando um monstro "Karakuri" com a face para cima em Posição de Defesa for selecionado como alvo de um ataque. \r\nDestrua todos os monstros com a face para cima que seu oponente controla.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79182538,'Cão Doido das Trevas','Ele costumava ser um cão normal que brincava num parque, mas foi corrompido pelo poder das trevas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79185500,'Martelo de Ferro, o Gigante',replace(replace('Se você controlar "D.D. Andorinha Estelar Esper", "Besta-Guerreira Puma" e "Besta Fênix Gairuda", você pode Invocar este card por Invocação-Especial (da sua mão). \r\nEnquanto este card estiver com a face para cima no campo, ele não pode mudar sua posição de batalha. \r\nUma vez por turno: você pode escolher 1 monstro que você controla; ele pode atacar diretamente seu oponente neste turno.','\r',char(13)),'\n',char(10)),'Ataque direto','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79194594,'Síntese Miutante',replace(replace('2 monstros "Miutante" com Atributos diferentes	\r\nSe este card for Invocado por Invocação-Fusão: você pode escolher 1 card no campo; destrua-o. \r\nQuando seu oponente ativar um card ou efeito (Efeito Rápido): você pode ativar este efeito; pelo resto deste turno, este card com a face para cima não é afetado pelos efeitos de um card do oponente do mesmo tipo (Monstro, Magia ou Armadilha) que o desse card. \r\nSe este card Invocado por Invocação-Fusão que você controla for destruído por um card do oponente: você pode adicionar 1 dos seus cards "Miutante" banidos à sua mão. \r\nVocê só pode usar cada efeito de "Síntese Miutante" uma vez por turno.','\r',char(13)),'\n',char(10)),'Destruir 1 card','Não é afetado por efeitos','Adicionar à mão','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79205581,'Incursão Cancelada','Durante a Fase de Batalha, você pode enviar 1 card que você controla ao Cemitério, exceto este card, para encerrar a Fase de Batalha.','Encerrar a Fase de Batalha','Usar o efeito de "Incursão Cancelada" agora?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79206750,'Abis-desprezo',replace(replace('Escolha 1 monstro "Sirena" que você controla; ele ganha 1000 de ATK até a Fase Final. \r\nQuando este card Baixado for enviado para o Cemitério: escolha 1 monstro que seu oponente controla; envie o alvo para o Cemitério.','\r',char(13)),'\n',char(10)),'Enviar um monstro para o Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79206925,'Supernaturalista do Coveiro',replace(replace('2 monstros "do Coveiro"	\r\nGanha ATK/DEF igual aos Níveis originais combinados das matérias usadas para sua Invocação-Fusão x 100. \r\nEnquanto "Necro-Vale" estiver no campo, este card e qualquer card na sua Zona do Campo não podem ser destruídos por efeitos de card. \r\nDurante sua Fase Principal: você pode ativar este efeito; durante a Fase Final deste turno, adicione 1 monstro "do Coveiro" ou 1 card "Necro-Vale" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Supernaturalista do Coveiro" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79210531,'Cavaleirostrela Lyran',replace(replace('(Este card deve ser sempre considerado como um card "Constelar".)	\r\nSe um monstro "Cavaleirost" ou "Constelar" for Invocado por Invocação-Normal no seu campo, exceto "Cavaleirostrela Lyran" (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe este card for Invocado: você pode adicionar 1 Magia "Cavaleirost" do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "Cavaleirostrela Lyran" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79229522,'Dragão Fortaleza Quimeratech',replace(replace('"Dragão Cibernético" + 1+ monstros Máquina	\r\nNão pode ser usado como Matéria de Fusão. \r\nPrimeiro deve ser Invocado por Invocação-Especial (do seu Deck Adicional) ao enviar os cards acima de qualquer campo para o Cemitério. \r\nO ATK original deste card se torna 1000 x o número de matérias usadas para a sua Invocação-Especial.','\r',char(13)),'\n',char(10)),'Escolha 1 "Dragão Cibernético"','Escolha 1 ou mais monstros Máquina','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79234734,'Alma do Super Soldado',replace(replace('Você pode enviar 1 monstro "Soldado do Lustro Negro" (ou "Soldado do Brilho Negro - Enviado do Princípio") da sua mão para o Cemitério; até a próxima Fase Final do seu oponente, o ATK deste card se torna 3000 e o nome deste card se torna "Soldado do Lustro Negro". \r\nVocê pode banir este card do seu Cemitério; adicione 1 "Cavaleiro Principiante" ou "Cavaleiro do Anoitecer do Crepúsculo" do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "Alma do Super Soldado" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79266769,'Metal das Trevas, o Dragão do Aço Negro',replace(replace('2+ Monstros de Efeito com o mesmo Tipo e Atributo	\r\nVocê pode escolher 1 dos seus monstros que estiverem banidos ou no seu Cemitério; Invoque-o por Invocação-Especial em uma zona sua para a qual este card apontar, em Posição de Defesa, mas seus efeitos são negados e, além disso, você não pode Invocar Monstros Link por Invocação-Especial pelo resto deste turno e o monstro Invocado é colocado no fundo do Deck quando ele deixar o campo. \r\nVocê só pode usar este efeito de "Metal das Trevas, o Dragão do Aço Negro" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79279397,'D-Guriz','VIRE: Você pode Invocar por Invocação-Especial qualquer número de "D-Guriz" do seu Deck em Posição de Ataque e, depois, você sofre 1000 de dano para cada monstro Invocado por Invocação-Especial por este efeito.','Invocação Especial','Invocar por Invocação Especial?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79306385,'Oráculo do Arauto',replace(replace('Este card é usado para a Invocação-Ritual de "Arauto da Inevitabilidade". \r\nVocê também deve oferecer como Tributo monstros da sua mão ou do campo cuja soma dos Níveis seja igual a 12 ou mais. \r\nSeu oponente não pode ativar cards ou efeitos em resposta à ativação deste card.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79323590,'Corrente de Energia','Cada duelista deve pagar 500 PV por card para Invocar por Invocação-Normal, Invocação-Especial, Baixar ou ativar cards de sua respectiva mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79324191,'Livro da Arte Ninjitsu','Uma vez por turno: você pode enviar 1 monstro "Ninja" da sua mão para o Cemitério; Baixe 1 Magia/Armadilha "Ninjitsu" diretamente do seu Deck, exceto "Livro da Arte Ninjitsu".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79333300,'Miyabi - Arte Espiritual do Vento','Ofereça 1 monstro de VENTO como Tributo e, depois, escolha 1 card que seu oponente controla; coloque esse card do oponente no fundo do Deck.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79335209,'Ojama Negro','Ele é um dos membros do Trio Ojama. Dizem que ele sempre encontra uma forma de se intrometer quando não é convidado. Dizem também que quando os três se juntam, algo acontece.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79337169,'Guerreiro de Manoplas','Durante o turno de qualquer duelista: você pode oferecer este card como Tributo; os monstros do Tipo Guerreiro que você controla atualmente ganham 500 de ATK e DEF até o final da próxima Etapa de Dano que esses monstros atacarem ou forem atacados.','Aumentar ATK/DEF','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79339613,'Energia da Alma MÁX!!!',replace(replace('Se você controlar "Obelisco, o Atormentador" cujo Atributo original seja DIVINO na sua Zona de Monstros: ofereça como Tributo 2 outros monstros com a face para cima; destrua tantos monstros que seu oponente controla quanto possível e, se isso acontecer, cause 4000 de dano ao seu oponente. \r\nDurante a Fase Principal ou de Batalha: você pode banir este card do seu Cemitério; adicione 1 "Obelisco, o Atormentador" do seu Deck ou Cemitério à sua mão e, depois, imediatamente depois que este efeito resolver, você pode Invocar por Invocação-Normal 1 "Obelisco, o Atormentador". \r\nVocê só pode usar cada efeito de "Energia da Alma MÁX!!!" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79371769,'Armadilha da Lavadeira',replace(replace('Uma vez por Corrente, se um ou mais monstros forem Invocados por Invocação-Normal ou Especial no seu campo (exceto durante a Etapa de Dano): você pode enviar o card do topo do seu Deck para o Cemitério. \r\nSe este card for enviado do seu Deck para o Cemitério por um efeito de card: você pode escolher 1 card no seu Cemitério que foi enviado para lá neste turno, exceto "Armadilha da Lavadeira"; adicione-o à sua mão, mas até o final do seu próximo turno depois que este efeito resolver, você não pode ativar cards, ou os efeitos de cards, com o nome dele. \r\nVocê só pode usar este efeito de "Armadilha da Lavadeira" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79371897,'Reforço das Tropas do Exército',replace(replace('Quando um ataque for declarado envolvendo um monstro Guerreiro seu: você pode Invocar por Invocação-Especial 1 monstro Guerreiro de Nível 4 ou menos da sua mão. \r\nVocê só pode usar este efeito de "Reforço das Tropas do Exército" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79383919,'Retribuição do Olho Maligno',replace(replace('Quando um Card de Magia/Armadilha for ativado, enquanto você controlar um monstro "Olho Maligno": negue a ativação e, se isso acontecer, destrua-o. \r\nSe "Olho Maligno de Selene" estiver na sua Zona de Magias & Armadilhas, a ativação e efeito deste card não podem ser anulados. \r\nVocê só pode ativar 1 "Retribuição do Olho Maligno" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79387392,'Reator Limo',replace(replace('Durante sua Fase Principal: você pode ativar este efeito; Invoque por Invocação-Especial 2 "Ficha de Limo" (Aqua/ÁGUA/Nível 1/ATK 500/DEF 500) e, além disso, você não pode Invocar monstros por Invocação-Normal ou Especial pelo resto deste turno, exceto monstros Besta Divina. \r\nDurante a Fase de Batalha (Efeito Rápido): você pode oferecer este card como Tributo; Baixe 1 "Limo Reflete Metal" da sua mão, do Deck ou do Cemitério. \r\nEle pode ser ativado neste turno. \r\nVocê só pode usar cada efeito de "Reator Limo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Ativar aplicando o efeito de "Reator Limo".','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79387393,'Ficha de Limo','Invocado por Especial com o efeito "Máquina de Reprodução de Geleia" ou um card relacionado.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79400597,'Repouso do Olho Maligno',replace(replace('Quando você ativar este card: você pode banir 1 card "Olho Maligno" do seu Cemitério; compre 1 card. \r\nUma vez por turno, depois do cálculo de dano, se um monstro "Olho Maligno" seu equipado com "Olho Maligno de Selene" atacar um monstro do oponente: você pode banir esse monstro do oponente. \r\nSe este card na Zona de Magias & Armadilhas for destruído por um efeito de card: você pode escolher até 3 dos seus cards "Olho Maligno" banidos; devolva-os para o Cemitério. \r\nVocê só pode ativar 1 "Repouso do Olho Maligno" por turno.','\r',char(13)),'\n',char(10)),'Banir 1 card "Olho Maligno" do seu Cemitério para comprar 1 card?','Escolha o card a ser devolvido ao Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79402185,'Ligação - D2O',replace(replace('Ofereça como Tributo 2 "Duoterion" e 1 "Oxygeddon" da sua mão e/ou do campo; Invoque por Invocação-Especial 1 "Dragão de Água" ou "Aglomerado Dragão de Água" da sua mão, do Deck ou do Cemitério. \r\n(Essa é considerada uma Invocação-Especial com o efeito de "Ligação - H2O".) \r\nSe "Dragão de Água" ou "Aglomerado Dragão de Água" for enviado do campo para o seu Cemitério enquanto este card estiver no seu Cemitério: adicione este card à sua mão. \r\nVocê só pode usar este efeito de "Ligação - D2O" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79407975,'Dragão Negro Arco-Íris',replace(replace('(Este card deve ser sempre considerado como um card "Cristalino(a) Definitivo(a)".)	\r\nNão pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao banir 7 monstros de TREVAS com nomes diferentes do seu Cemitério. \r\nVocê pode banir todos os outros monstros de TREVAS do seu campo e Cemitério; este card ganha 500 de ATK para cada card banido desta forma.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79409334,'Estego Negro','Se este card em Posição de Ataque for escolhido como alvo de um ataque: coloque este card em Posição de Defesa.','Mudar para Posição de Defesa','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79415624,'Dragão da Vingança Olho de Cobra',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nDurante a Fase Principal (Efeito Rápido): você pode escolher 1 monstro com a face para cima no campo ou em qualquer Cemitério; coloque-o com a face para cima na Zona de Magias & Armadilhas do seu dono como uma Magia Contínua e, além disso, este card não pode usar este efeito no próximo turno. \r\nDurante a Fase de Batalha (Efeito Rápido): você pode escolher 1 monstro e 1 Magia Contínua no campo; destrua-os. \r\nVocê só pode usar cada efeito de "Dragão da Vingança Olho de Cobra" uma vez por turno.','\r',char(13)),'\n',char(10)),'Colocar na Zona de Magias/Armadilhas','Efeito de destruição','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79418153,'Arquidemônio Lanceiro','Uma vez por turno, quando um monstro seu declarar um ataque contra um monstro em Posição de Defesa do seu oponente: você pode ativar este efeito; durante essa batalha, se esse monstro atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente.','Dano de batalha perfurante','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79418928,'Beta, o Guerreiro Ímã Temporal',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 monstro "Guerreiro Ímã" de Nível 4 ou menos do seu Deck à sua mão, exceto "Beta, o Guerreiro Ímã Temporal". \r\nVocê só pode usar este efeito de "Beta, o Guerreiro Ímã Temporal" uma vez por turno. \r\nDurante o turno do seu oponente (Efeito Rápido): você pode oferecer este card como Tributo; Invoque por Invocação-Especial 1 monstro "Guerreiro Ímã" de Nível 4 do seu Deck.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79436874,'Foguete R.B. VALCan',replace(replace('Se você não controlar nenhum monstro com a face para cima, ou os únicos monstros com a face para cima que você controla forem monstros "R.B.", você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Foguete R.B. VALCan" por Invocação-Especial uma vez por turno desta forma. \r\nSe este card estiver linkado a um Monstro Link "R.B.": você pode pagar 1000 PV e, depois, escolha até 2 cards que seu oponente controla; destrua-os, e também este card e, se isso acontecer, cause 500 de dano ao seu oponente para cada card destruído. \r\nVocê só pode usar este efeito de "Foguete R.B. VALCan" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79441381,'Ninja do Crepúsculo Jogen',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nSe um monstro "Ninja" seu atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nVocê pode revelar 1 card "Ninjitsu" na sua mão; Invoque este card por Invocação-Especial da sua mão. \r\nSe este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79444933,'Ignis, O Espírito das Chamas','Você pode oferecer como Tributo 1 monstro de FOGO com a face para cima para causar 100 de dano ao seu oponente para cada monstro de FOGO no seu Cemitério.','Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79447365,'Máscara Toon','Se você controlar "Mundo Toon": escolha 1 monstro com a face para cima que seu oponente controla; Invoque por Invocação-Especial 1 monstro Toon da sua mão ou do Deck, cujo Nível seja menor ou igual ao Nível/Classe desse monstro, ignorando suas condições de Invocação.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79473793,'Dragão da Noite Branca',replace(replace('Durante o turno de qualquer duelista, quando um Card de Magia/Armadilha que escolher este card como alvo for ativado: negue a ativação e, se isso acontecer, destrua-o. \r\nQuando outro monstro com a face para cima que você controla for alvo de um ataque: você pode enviar 1 Card de Magia/Armadilha que você controla para o Cemitério; esse ataque agora escolhe este card como alvo.','\r',char(13)),'\n',char(10)),'Negar e destruir','Alterar o alvo do ataque','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79480466,'Bazoo, o Devorador de Almas',replace(replace('3 monstros de Nível 4	\r\nQualquer Matéria Xyz desassociada de um monstro é banida em vez de ir para o Cemitério. \r\nUma vez por Corrente, se um ou mais Cards de Monstro forem enviados para o Cemitério (exceto durante a Etapa de Dano): você pode desassociar 1 matéria deste card. \r\nSe a(s) última(s) matéria(s) for(em) desassociada(s) deste card (exceto durante a Etapa de Dano): você pode escolher 3 cards no(s) \r\nCemitério(s); associe-os a este card.','\r',char(13)),'\n',char(10)),'','Desassociar Matéria Xyz','Associar Matéria Xyz','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79491903,'Naga Reptiliana',replace(replace('Este card não pode ser destruído em batalha. \r\nO ATK de qualquer monstro que batalhar com este card se torna 0 no final dessa Fase de Batalha. \r\nDurante sua Fase Final, mude este card em Posição de Defesa com a face para cima no campo para Posição de Ataque com a face para cima.','\r',char(13)),'\n',char(10)),'O ATK se torna 0','Mudar para Posição de Ataque com a face para cima','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79509511,'Jornada das Galáxias',replace(replace('Invoque por Invocação-Especial 1 dos seus monstros de LUZ ou de TREVAS banidos. \r\nSe um ou mais Monstros Xyz com a face para cima que você controla forem banidos, enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode banir este card e, depois, escolha 1 desses monstros; Invoque-o por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Jornada das Galáxias" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Banir e Invocar por Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79514956,'Elegia, a Diva Melodiosa',replace(replace('Monstros "Melodiosa(o)" Invocados por Invocação-Especial que você controla não podem ser destruídos por efeitos de card. \r\nSe este card foi Invocado por Invocação-Especial, todos os monstros do Tipo Fada que você controla ganham 300 de ATK.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79519259,'Clériga com Asas da Noite',replace(replace('1 Regulador + 1+ não-Reguladores	\r\nSe este card for Invocado por Invocação-Especial: você pode Baixar 1 "Ativar Modo de Ataque" da sua mão, do Deck ou do Cemitério. \r\nEle pode ser ativado neste turno. \r\nVocê pode descartar 1 card; adicione à sua mão ou Invoque por Invocação-Especial 1 monstro do seu Deck que mencione "Ativar Modo de Ataque" e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto Monstros Sincro. \r\nVocê só pode usar cada efeito de "Clériga com Asas da Noite" uma vez por turno.','\r',char(13)),'\n',char(10)),'Baixar','Adicionar à mão','Ativar aplicando o efeito de "Clériga com Asas da Noite".','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79523365,'Flagelo Escarlate Vampiro',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode pagar 1000 PV e, depois, escolha 1 monstro "Vampiro(a)" no seu Cemitério, exceto "Flagelo Escarlate Vampiro"; Invoque-o por Invocação-Especial, mas ele não pode atacar neste turno. \r\nVocê só pode usar este efeito de "Flagelo Escarlate Vampiro" uma vez por turno. \r\nNo final da Fase de Batalha, se este card destruiu quaisquer monstros em batalha: você pode Invocá-los por Invocação-Especial dos Cemitérios no seu campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79531196,'Rosa de Cristal',replace(replace('Uma vez por turno: até a Fase Final, você pode enviar 1 monstro "Cavaleiro-Gema" ou "Melodiosa" da sua mão ou Deck para o Cemitério e, se isso acontecer, o nome deste card se torna o nome do monstro enviado. \r\nSe este card estiver no seu Cemitério: você pode banir 1 Monstro de Fusão do seu Cemitério; Invoque este card por Invocação-Especial em Posição de Defesa. \r\nVocê só pode usar este efeito de "Rosa de Cristal" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79538761,'Engrenagem de Motor a Corda',replace(replace('Uma vez por turno, você pode: escolher 1 monstro que você controla; equipe este card no alvo, OU: desequipe este card e Invoque-o por Invocação-Especial. \r\nUm monstro equipado com este card é considerado como um Regulador, ele ganha 500 de ATK/DEF e, além disso, se o monstro equipado seria destruído em batalha ou por um efeito de card, em vez disso, destrua este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79544790,'Renascimento Arrependido','Quando um monstro que você controla for destruído em batalha e enviado para o Cemitério: escolha esse monstro; Invoque-o por Invocação-Especial com a face para cima em Posição de Defesa, mas ele é destruído durante sua Fase Final.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79552283,'Choque Espantagarra',replace(replace('Uma vez por turno: você pode escolher 1 monstro "Espantagarra" ou "Visas Starfrost" que você controla; neste turno, ele pode atacar enquanto estiver com a face para cima em Posição de Defesa. \r\nSe o fizer, aplique seu ATK ou DEF (o que for maior) para o cálculo de dano. \r\nQuando seu oponente ativar um card ou efeito, enquanto você controlar um monstro "Espantagarra" na Zona de Monstros Adicional: você pode enviar este card com a face para cima para o Cemitério; negue o efeito. \r\nVocê só pode usar este efeito de "Choque Espantagarra" uma vez por turno.','\r',char(13)),'\n',char(10)),'Atacar em Posição de Defesa','Negue o efeito do seu oponente','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79555535,'Phoenix da Ignição',replace(replace('Todos os monstros "Cavaleirardor" no campo ganham 300 de ATK e DEF. \r\nUma vez por turno: você pode escolher 1 card "Cavaleirardor" que você controla; destrua-o e, se isso acontecer, adicione 1 card "Cavaleirardor" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79559912,'D/D/D César, o Alto Rei das Ondas',replace(replace('2 monstros Demônio de Nível 6	\r\nQuando um Card de Magia/Armadilha, ou efeito de monstro, for ativado que inclua um efeito que Invoque um ou mais monstro por Invocação-Especial (Efeito Rápido): você pode desassociar 1 matéria deste card; negue a ativação e, se isso acontecer, destrua esse card e, depois, você pode fazer com que este card e 1 outro monstro "D/D" que você controla ganhem 1800 de ATK até o final deste turno. \r\nSe este card for enviado do campo para o Cemitério: você pode adicionar 1 card "Pacto Obscuro" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Negar a ativação e destruir','Aumentar o ATK de um monstro?','Adicionar à sua mão 1 card "Pacto Obscuro" do seu Deck','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79561872,'Surpresa Alegre dos Melffys',replace(replace('1 monstro "Melffy" + 1 monstro Besta	\r\nSe este card for Invocado por Invocação-Fusão: você pode escolher um mesmo número de cards "Melffy" que você controla e cards que seu oponente controla; devolva-os para a mão. \r\nSe seu oponente Invocar um ou mais monstros por Invocação-Normal ou Especial (exceto durante a Etapa de Dano), ou se um monstro do oponente escolher este card como alvo de um ataque: você pode escolher 1 monstro Besta no seu Cemitério; reduza o Nível deste card em exatamente 2 e, se isso acontecer, Invoque o alvo por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Surpresa Alegre dos Melffys" uma vez por turno.','\r',char(13)),'\n',char(10)),'Retornar para a mão','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79569173,'Onda de Choque Sísmica',replace(replace('Destrua este card durante sua 3ª Fase de Apoio depois da ativação dele. \r\nAtive este card quando um monstro do Tipo Dinossauro com a face para cima que você controla for destruído e enviado para o Cemitério (exceto durante a Etapa de Dano): selecione 3 das Zonas de Magias & Armadilhas não utilizadas do seu oponente. \r\nEssas Zonas não podem ser utilizadas. \r\nSe este card destruir a si mesmo: você pode escolher 1 monstro do Tipo Dinossauro no seu Cemitério; adicione o alvo à sua mão.','\r',char(13)),'\n',char(10)),'Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79571449,'Caridade Graciosa','Compre 3 cards e, depois, descarte 2 cards.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79575620,'Lily, a Fada Enfermeira','Uma vez por batalha, durante o cálculo de dano, se este card batalhar (Efeito Rápido): você pode pagar 2000 PV; este card ganha 3000 de ATK apenas durante esse cálculo de dano.','Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79580323,'Besta Gladiadora Spartacus',replace(replace('Este card não pode ser Invocado por Invocação-Especial exceto pelo efeito de "Besta Gladiadora Hoplomus". \r\nQuando este card for Invocado por Invocação-Especial, adicione 1 Card de Magia de Equipamento "Besta Gladiadora" do seu Deck à sua mão. \r\nNo final da Fase de Batalha, se este card atacou ou foi atacado, você pode devolvê-lo para o Deck para Invocar por Invocação-Especial 1 monstro "Besta Gladiadora" do seu Deck, exceto "Besta Gladiadora Spartacus".','\r',char(13)),'\n',char(10)),'Procurar no Deck','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79582540,'Guerreiros Antigos - Don Ying Selvagem',replace(replace('Enquanto você controlar um monstro "Guerreiros Antigos" de Nível 7 ou mais, seu oponente deve pagar 400 PV para ativar um card ou efeito. \r\nVocê só pode usar cada um dos seguintes efeitos de "Guerreiros Antigos - Don Ying Selvagem" uma vez por turno. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 monstro "Guerreiros Antigos" de Nível 7 ou mais ou 1 Magia/Armadilha Contínua "Guerreiros Antigos" do seu Deck à sua mão. \r\nSe um monstro for enviado para o Cemitério do seu oponente (exceto durante a Etapa de Dano): você pode escolher 1 card no Cemitério do seu oponente; bana-o e, se isso acontecer, compre 1 card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79600447,'Explosão de Crânios Mementotlan',replace(replace('Enquanto você controlar um monstro "Memento", os monstros do seu oponente que podem atacar devem atacar o monstro "Memento" que você controla com o maior ATK (em caso de empate, ele seleciona). \r\nQuando seu oponente ativar um efeito de monstro no campo (exceto durante a Etapa de Dano): você pode escolher 1 "Mementoal Tecuhtlica - Criação Combinada" que você controla; ele perde exatamente 1000 de ATK/DEF e, se isso acontecer, negue esse efeito ativado. \r\nVocê só pode ativar este efeito de "Explosão de Crânios Mementotlan" uma vez por Corrente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79606837,'Arauto do Arco de Luz',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nQualquer monstro enviado da mão ou do Deck Principal para o Cemitério, em vez disso, é banido. \r\nQuando um Card de Magia/Armadilha, ou efeito de monstro, for ativado (Efeito Rápido): você pode oferecer este card como Tributo; negue a ativação e, se isso acontecer, destrua esse card. \r\nSe este card for enviado para o Cemitério: você pode adicionar 1 Monstro de Ritual ou 1 Magia de Ritual do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Negar e destruir','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79613121,'Mago do Caos das Trevas MÁX',replace(replace('Você pode Invocar este card por Invocação-Ritual com "Forma do Caos". \r\nSe este card for Invocado por Invocação-Especial: você pode oferecer 1 monstro como Tributo; seu oponente não pode ativar efeitos de monstro neste turno. \r\nQuando este card destruir um monstro do oponente em batalha: você pode escolher 1 Magia no seu Cemitério; adicione-a à sua mão. \r\nVocê só pode usar cada efeito de "Mago do Caos das Trevas MÁX" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79621896,'Origem do Arquidemônio',replace(replace('Se este card está na sua mão: você pode oferecer como Tributo 1 outro monstro "Arquidemônio" da sua mão ou campo; Invoque este card por Invocação-Especial.\r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode Invocar por Invocação-Especial 1 monstro Demônio de Nível 6 com 2500 de ATK da sua mão, Deck ou Cemitério.\r\nQuando seu oponente ativar um efeito de monstro e você controla "Caveira Invocada" (Efeito Rápido): você pode negar a ativação, e se fizer isso, destrua aquele card.\r\nVocê só pode usar cada um dos efeitos de "Origem do Arquidemônio" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar este card por Invocação Especial','Invocação Especial','Negar e destruir','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79625003,'Número S37: Aranha Tubarão',replace(replace('3 monstros de ÁGUA de Nível 5	\r\nVocê também pode Invocar este card por Invocação-Xyz ao usar "Número 37: Dragão Aranha Tubarão Trama da Esperança" que você controla (transfira as matérias dele para este card). \r\nUma vez por turno: você pode desassociar 1 matéria deste card e, depois, escolha 1 monstro que seu oponente controla; bana-o (até a próxima Fase de Apoio dele) e, se isso acontecer, quaisquer monstros que ele controlar atualmente perdem 1000 de ATK até o final deste turno. \r\nUma vez por turno, durante a Fase Final, se este card estiver no seu Cemitério porque este card Invocado por Invocação-Xyz foi destruído e enviado para lá neste turno: você pode Invocá-lo por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Xyz usando "Número 37: Dragão Aranha Tubarão Trama da Esperança" como matéria?','Banir','Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79627627,'Converpássaro',replace(replace('VIRE: Você pode Invocar por Invocação-Especial 1 monstro de Virar de Nível 5 ou mais do seu Deck com a face para baixo em Posição de Defesa, exceto "Converpássaro".\r\nDurante a Fase de Batalha, se este card estiver na sua mão (Efeito Rápido): você pode escolher 1 monstro com a face para baixo no campo; envie-o para o Cemitério e, se isso acontecer, Invoque este card por Invocação-Especial com a face para baixo em Posição de Defesa. \r\nVocê só pode usar cada efeito de "Converpássaro" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial do Deck','Invocar este card por Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79629370,'Dama da Luz da Lua','Uma feiticeira abençoada pela luz da lua com poderes além da compreensão mortal.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79636594,'Aranha Foliona',replace(replace('Seu oponente não pode escolher monstros do Tipo Inseto como alvo de ataques, exceto este. \r\nSe este card for Invocado por Invocação-Especial: você pode Invocar por Invocação-Especial 1 "Aranha Foliona" do seu Deck. \r\nVocê só pode usar este efeito de "Aranha Foliona" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79649195,'Armadura Rompida','Anule a activação de um Card de Magia de Equipamento e destrúa-o.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79656239,'Aromági-serafim Manjerona-Doce',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nEnquanto seus PV forem maiores que os do seu oponente, seu oponente não pode escolher monstros Planta que você controla como alvo de efeitos de card. \r\nVocê só pode usar cada um dos seguintes efeitos de "Aromági-serafim Manjerona-Doce" uma vez por turno.\r\n● Se este card for Invocado por Invocação-Sincro: você pode adicionar 1 "Ventos Húmidos", "Ventos Secos" ou "Ventos Abençoados" do seu Deck à sua mão.\r\n● Se você ganhar PV: escolha 1 card que seu oponente controla; destrua-o.','\r',char(13)),'\n',char(10)),'','','Destrua um card do seu oponente','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79663524,'Cigarra Oleosa',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode reduzir em 1 os Níveis de todos os monstros Inseto que você controla atualmente. \r\nSe a posição de batalha deste card for mudada: você pode Invocar por Invocação-Especial 1 "Cigarra Oleosa" da sua mão, do Deck ou do Cemitério. \r\nVocê só pode usar cada efeito de "Cigarra Oleosa" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79698395,'Reino do Perigo!',replace(replace('Seu oponente não pode escolher monstros "Perigo!" que você controla como alvo de efeitos de card durante o turno em que eles são Invocados por Invocação-Especial. \r\nUma vez por turno: você pode escolher 1 monstro "Perigo!" que você controla; enquanto você controlar esse monstro com a face para cima e este card com a face para cima, esse monstro pode atacar diretamente e, além disso, os monstros do seu oponente não podem escolhê-lo como alvo de ataques, mas isso não impede seu oponente de atacar você diretamente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79703905,'Nuviano - Altostratus',replace(replace('Não pode ser destruído em batalha. \r\nSe este card estiver com a face para cima em Posição de Defesa, destrua-o. \r\nSe este card for Invocado por Invocação-Normal: coloque 1 Marcador de Névoa nele para cada monstro "Nuviano" no campo. \r\nVocê pode remover 3 Marcadores de Névoa de qualquer parte do campo; descarte 1 card aleatório da mão do seu oponente.','\r',char(13)),'\n',char(10)),'Colocar um marcador','Descartar 1 card','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79707116,'Corrente Paralisante','Quando um ou mais cards forem enviados do Deck do seu oponente para o Cemitério por um efeito de card, cause 300 de dano ao seu oponente.','Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79718768,'Do Nada',replace(replace('Destrua este card se seu oponente ativar um card ou efeito que escolha como alvo um ou mais cards no Cemitério. \r\nQuando este card for destruído por este efeito e enviado ao Cemitério, seu oponente embaralha todos os cards do Cemitério dele no Deck.','\r',char(13)),'\n',char(10)),'Retornar ao Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79724755,'Duonigis Bacamartes Guitarristas',replace(replace('Se este card for Invocado por Invocação-Especial: você pode banir cards do topo do Deck do seu oponente igual ao número de monstros de ÁGUA que você controla. \r\nVocê pode escolher 1 monstro de ÁGUA de Nível 4 ou menos que você controla; aumente o Nível dele pelo seu Nível original. \r\nVocê pode banir este card do seu Cemitério; até o final deste turno, 1 monstro de ÁGUA no campo ganha 100 de ATK para cada monstro banido atualmente. \r\nVocê só pode usar cada efeito de "Duonigis Bacamartes Guitarristas" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79747096,'Número C1: Portão do Caos Numeron Sunya',replace(replace('4 monstros de Nível 2	\r\nVocê também pode Invocar este card por Invocação-Xyz ao usar "Número 1: Portão Numeron Ekam" que você controla como matéria. \r\n(Transfira as matérias dele para este card.) \r\nSe este card for Invocado por Invocação-Xyz: bana todos os monstros no campo. \r\nUma vez por turno, durante sua próxima Fase de Apoio depois que este card foi banido: você pode Invocar este card banido por Invocação-Especial e, depois, se "Rede Numeron" estiver na sua Zona do Campo, cause dano ao seu oponente igual ao ATK combinado de todos os Monstros Xyz banidos.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Xyz usando "Número 1: Portão Numeron Ekam" como matéria?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79755671,'Gulamel Caudraco',replace(replace('1 monstro "Caudraco" + 1 monstro na mão	\r\nQuando você ativar um card ou efeito "Caudraco" (Efeito Rápido): você pode escolher 1 card que seu oponente controla; destrua-o. \r\nSe 2 ou mais monstros forem enviados para o Cemitério ao mesmo tempo, enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar cada efeito de "Gulamel Caudraco" uma vez por turno.','\r',char(13)),'\n',char(10)),'Efeito de destruição','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79757784,'Tamtam, a Diva Melodiosa',replace(replace('Se este card for Invocado por Invocação-Especial enquanto você controlar um monstro "Melodiosa": você pode adicionar 1 "Polimerização" do seu Deck ou Cemitério à sua mão. \r\nSe este card for enviado para o Cemitério como uma Matéria de Fusão para uma Invocação-Fusão: você pode escolher 1 monstro "Melodiosa" que você controla; ele perde 500 de ATK e, se isso acontecer, cause 500 de dano ao seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79759367,'Noites Magidoce','Quando um efeito de monstro for ativado, se você não tiver nenhum monstro no seu Cemitério: negue a ativação e, depois, se você controlar "Pudincesa Magidoce", embaralhe 1 card aleatório da mão do seu oponente no Deck.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79759861,'Tributo aos Condenados','Descarte 1 card e, depois, escolha 1 monstro no campo; destrua-o.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79766336,'Armadilha da Escuridão','Se seus PV forem 3000 ou menos: pague 1000 PV e, depois, escolha 1 Armadilha Normal no seu Cemitério, exceto "Armadilha da Escuridão"; o efeito deste card se torna o efeito ativado do alvo e, depois, bana o alvo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79775821,'Levante Therion!',replace(replace('Escolha 1 monstro "Therion" no seu Cemitério; Invoque-o por Invocação-Especial e, depois, você pode equipar 1 monstro "Therion" da sua mão ou do Cemitério a ele. \r\nDurante a Fase Principal: você pode banir este card do seu Cemitério e, depois, escolha 2 monstros "Therion" (1 no seu campo e 1 no seu Cemitério); equipe esse monstro do seu Cemitério ao outro monstro que você controla. \r\nVocê só pode usar 1 efeito de "Levante Therion!" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Equipar um monstro?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79777187,'Barreira de Bolhas',replace(replace('Uma vez por turno, cada monstro "Camarartista" e "Camaramágico" que você controla não pode ser destruído em batalha ou por efeitos de card. \r\nVocê não sofre dano de batalha de ataques envolvendo monstros "Camarartista" e "Camaramágico" que você controla.','\r',char(13)),'\n',char(10)),'O efeito de "Barreira de Bolhas" já foi aplicado uma vez','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79783880,'Shiranui Espada Espectral Sombria',replace(replace('Você pode oferecer este card como Tributo e, depois, escolher 2 dos seus monstros Zumbi banidos, exceto "Shiranui Espada Espectral Sombria", incluindo um monstro "Shiranui"; Invoque-os por Invocação-Especial em Posição de Defesa, mas negue seus efeitos e, além disso, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros Zumbi. \r\nVocê só pode usar este efeito de "Shiranui Espada Espectral Sombria" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79785958,'Hordeum Maligno Castor',replace(replace('Durante o turno em que este card foi Invocado por Invocação-Normal, você pode Invocar por Invocação-Normal 1 monstro "Hordeum" em adição à sua Invocação-Normal/Baixar padrão. \r\n(Você só pode se aproveitar deste efeito uma vez por turno.)','\r',char(13)),'\n',char(10)),'Invocar pelo efeito de "Hordeum Maligno Castor"','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79791695,'CXyz Dragão da Esperança do Caos Barian',replace(replace('3+ monstros de Nível 7	\r\nVocê só pode Invocar por Invocação-Xyz este card usando 1 monstro "Número C" que você controla com um número entre "101" e "107" em seu nome (transfira suas matérias).\r\nGanha 1000 de ATK para cada matéria associada nele.\r\nEnquanto este card tem um monstro "Número C" como matéria, se oponente não pode adicionar cards do Deck à mão, exceto por compra-las.\r\nUma vez por turno: você pode desassociar 1 matéria deste caard; associe os 2 cards do topo do Deck do seu oponente neste card.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Xyz sobrepondo um monstro que você controla?','Associar Matéria Xyz','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79791696,'CXyz Dragão da Esperança do Caos Barian',replace(replace('3+ monstros de Nível 7	\r\nVocê só pode Invocar por Invocação-Xyz este card usando 1 monstro "Número C" que você controla com um número entre "101" e "107" em seu nome (transfira suas matérias).\r\nGanha 1000 de ATK para cada matéria associada nele.\r\nEnquanto este card tem um monstro "Número C" como matéria, se oponente não pode adicionar cards do Deck à mão, exceto por compra-las.\r\nUma vez por turno: você pode desassociar 1 matéria deste caard; associe os 2 cards do topo do Deck do seu oponente neste card.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Xyz sobrepondo um monstro que você controla?','Associar Matéria Xyz','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79791878,'Sarcófago Brilhante',replace(replace('Não pode ser destruído por efeitos de monstro. \r\nVocê só pode usar cada um dos seguintes efeitos de "Sarcófago Brilhante" uma vez por turno. \r\nDurante sua Fase Principal: você pode adicionar 1 card que mencione "Sarcófago Brilhante" do seu Deck à sua mão, exceto "Sarcófago Brilhante". \r\nSe seu oponente Invocar um ou mais monstros por Invocação-Especial do Cemitério (exceto durante a Etapa de Dano): você pode descartar 1 Magia e, depois, escolha 1 desses monstros; envie-o para o Cemitério.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Enviar para o Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79794767,'Amórfago da Ira',replace(replace('Escala de Pêndulo = 3\r\n[ Efeito de Pêndulo ]\r\nEnquanto você controlar um monstro "Amórfago", nenhum duelista pode oferecer monstros como Tributo, exceto monstros "Amórfago". \r\nUma vez por turno, durante sua Fase de Apoio, ofereça 1 monstro como Tributo ou destrua este card.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe este card for Invocado por Invocação-Pêndulo ou virado com a face para cima, nenhum duelista pode Invocar monstros do Deck Adicional por Invocação-Especial enquanto este card estiver no campo com a face para cima, exceto monstros "Amórfago".','\r',char(13)),'\n',char(10)),'Oferecer como Tributo 1 monstro que você controla?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79796561,'Soldado Sincro',replace(replace('Uma vez por turno, durante sua Fase Principal 1, você pode selecionar 1 Monstro Sincro com a face para cima que você controla. \r\nRemova esse Monstro Sincro com a face para cima que você controla de jogo e cause 600 de dano ao seu oponente. \r\nSe você usar este efeito, durante sua próxima Fase de Apoio o monstro removido de jogo é devolvido para o campo.','\r',char(13)),'\n',char(10)),'Banir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79798060,'Imortal Terrestre Ccarayhua',replace(replace('Só pode haver 1 monstro "Imortal Terrestre" no campo. \r\nSe não houver Magias de Campo com a face para cima no campo, destrua este card. \r\nOs monstros do seu oponente não podem escolher este card como alvo de ataques. \r\nEste card pode atacar diretamente seu oponente. \r\nSe este card for destruído por um efeito de card, exceto por seu próprio efeito: destrua todos os cards no campo.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79814787,'A Pedra Branca das Lendas','Se este card for enviado para o Cemitério: adicione 1 "Dragão Branco de Olhos Azuis" do seu Deck à sua mão.','Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79816536,'Arte do Invocador','Adicione 1 Monstro Normal de Nível 5 ou mais do seu Deck à sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79844764,'O Monarca Avança',replace(replace('Uma vez durante este turno, se você fosse oferecer um monstro como Tributo para uma Invocação-Tributo, você pode oferecer como Tributo 1 monstro que seu oponente controla mesmo que você não o controle. \r\nVocê só pode ativar 1 "O Monarca Avança" por turno. \r\nDurante o turno em que ativar este card, você não pode Invocar por Invocação-Especial do Deck Adicional.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79850798,'Expresso Foguete Flecha',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nVocê deve Invocá-lo por Invocação-Especial (da sua mão) ao não controlar nenhum card e não pode ser Invocado por Invocação-Especial de nenhuma outra forma. \r\nVocê não pode conduzir sua Fase de Batalha no turno que Invocar este card por Invocação-Especial. \r\nVocê não pode ativar cards ou efeitos, nem Baixar quaisquer cards. \r\nDurante cada uma das suas Fases de Apoio, destrua este card a não ser que você envie toda a sua mão para o Cemitério (mín.1).','\r',char(13)),'\n',char(10)),'Escolha um efeito','Enviar todos os cards da sua mão para o Cemitério?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79852326,'Zoma, o Espírito',replace(replace('Invoque este card por Invocação-Especial em Posição de Defesa como um Monstro de Efeito (Zumbi/TREVAS/Nível 4/ATK 1800/DEF 500).	\r\n(Este card ainda é considerado uma Armadilha.) \r\nSe este card Invocado desta forma for destruído em batalha: cause dano ao seu oponente igual ao ATK do monstro que o destruiu.','\r',char(13)),'\n',char(10)),'Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79853073,'Soldado Críptico','Se este card batalhar um monstro do Tipo Guerreiro, durante o cálculo de dano: este card ganha 2000 de ATK e DEF apenas durante esse cálculo de dano.','Aumentar ATK/DEF','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79856792,'Dragão Arco-Íris',replace(replace('(Este card deve ser sempre considerado como um card "Cristalino(a) Definitivo(a)".)	\r\nNão pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao ter 7 cards "Fera Cristalina" com nomes diferentes no seu campo e/ou Cemitério. \r\nEste card não pode ativar os seguintes efeitos no turno em que for Invocado por Invocação-Especial. \r\n(Efeito Rápido): você pode enviar para o Cemitério todos os monstros "Fera Cristalina" que você controla; este card ganha 1000 de ATK para cada monstro enviado para o Cemitério. \r\nVocê pode banir todos os monstros "Fera Cristalina" do seu Cemitério; embaralhe no Deck todos os cards no campo.','\r',char(13)),'\n',char(10)),'Aumentar ATK','Retornar todos os cards no campo para os Decks de seus donos','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79858629,'Exoirmã Irene',replace(replace('Você pode colocar 1 card "Exoirmã" da sua mão no fundo do Deck; compre 1 card e, depois, se você controlar "Exoirmã Sofia", você ganha 800 PV. \r\nSe seu oponente mover um ou mais cards para fora de qualquer Cemitério (exceto durante a Etapa de Dano): você pode Invocar por Invocação-Especial do seu Deck Adicional, 1 Monstro Xyz "Exoirmã" usando este card com a face para cima que você controla como matéria. \r\n(Isso é considerado uma Invocação-Xyz.) \r\nVocê só pode usar cada efeito de "Exoirmã Irene" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Invocação Xyz','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79859067,'Próxima Fase R.B.',replace(replace('Quando seu oponente ativar um efeito de monstro, enquanto você controlar um monstro "R.B.": destrua 1 monstro que você controla e, se isso acontecer, negue a ativação e, se isso acontecer, destrua esse card e, depois, ganhe 2000 PV. \r\nVocê só pode ativar 1 "Próxima Fase R.B." por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79861914,'Furacão Yosen',replace(replace('Ative este card ao pagar 800 PV. \r\nUma vez por turno, se um monstro "Yosenju" com a face para cima que você controla voltar para a mão (exceto durante a Etapa de Dano): você pode escolher 1 card que seu oponente controla; devolva-o para a mão. \r\nDurante sua Fase Final, exceto se este efeito foi ativado neste turno (e não foi negado), destrua este card.','\r',char(13)),'\n',char(10)),'Retornar para a mão','Destruir este card','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79864860,'Predaplanta Triphyoverutum',replace(replace('3 monstros de TREVAS no campo	\r\nGanha ATK igual à soma do ATK original de todos os outros monstros no campo com um Marcador de Predador. \r\nVocê só pode usar cada um dos seguintes efeitos de "Predaplanta Triphyoverutum" uma vez por turno.\r\n● Quando seu oponente Invocar um ou mais monstros por Invocação-Especial do Deck Adicional dele enquanto você controlar este card Invocado por Invocação-Fusão (Efeito Rápido): você pode negar a Invocação e, se isso acontecer, destrua esse(s) monstro(s).\r\n● Se seu oponente controlar um monstro com um ou mais Marcadores de Predador: você pode Invocar este card por Invocação-Especial do seu Cemitério em Posição de Defesa.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79867938,'Boxeador Obstinado com Proteção de Cabeça',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode enviar 1 monstro "Boxeador Obstinado" do seu Deck para o Cemitério. \r\nNa primeira vez que este card em Posição de Ataque seria destruído em batalha a cada turno, ele não é destruído.','\r',char(13)),'\n',char(10)),'Enviar para o Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79868386,'Punho do Destino',replace(replace('A ativação e o efeito deste card não podem ser negados. \r\nSe você controlar um monstro cujo nome original seja "Obelisco, o Atormentador": negue os efeitos de 1 Monstro de Efeito que seu oponente controla e, se isso acontecer, destrua-o e, se isso acontecer, pelo resto deste turno, os efeitos desse monstro são negados, assim como os efeitos ativados e os efeitos no campo de monstros com o mesmo nome original e, depois, se você ativou este card durante sua Fase Principal, você pode aplicar este efeito.\r\n● Destrua todas as Magias e Armadilhas que seu oponente controla.	\r\nVocê só pode ativar 1 "Punho do Destino" por turno.','\r',char(13)),'\n',char(10)),'Destruir todos os Cards de Magia/Armadilha que seu oponente controla?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79870141,'Besta Louca da Espada','Se este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79875176,'Soldado Canhão Toon',replace(replace('Não pode atacar no turno em que for Invocado. \r\nSe "Mundo Toon", no campo, for destruído, destrua este card. \r\nEnquanto você controlar "Mundo Toon" e seu oponente não controlar nenhum monstro Toon, este card pode atacar diretamente seu oponente. \r\nVocê pode oferecer 1 monstro como Tributo; cause 500 de dano ao seu oponente.','\r',char(13)),'\n',char(10)),'Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79875526,'Cibern de Acoplamento',replace(replace('Você pode escolher 1 monstro Dragão ou Máquina "Ciber" que você controla; equipe este card da sua mão ou do campo a ele. \r\nEnquanto este card for um Card de Equipamento, o monstro equipado ganha 600 de ATK. \r\nSe este card for enviado para o Cemitério enquanto estiver equipado a um monstro: você pode escolher 1 outro monstro Dragão ou Máquina "Ciber" no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê só pode usar este efeito de "Cibern de Acoplamento" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79890560,'Fada Fortuna Hu',replace(replace('Quando você comprar este card: você pode revelá-lo; Invoque-o por Invocação-Especial da sua mão. \r\nSe este card for Invocado por Invocação-Especial da mão: você pode escolher 1 dos seus monstros Mago banidos; adicione-o à sua mão. \r\nVocê só pode usar cada efeito de "Fada Fortuna Hu" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79905468,'Dragão-Guarda Promineses',replace(replace('Você pode enviar este card da sua mão ou do campo para o Cemitério e, depois, escolher 1 monstro Dragão que você controla; ele ganha 500 de ATK/DEF até o final do turno do seu oponente. \r\nSe um ou mais Monstros Normais forem enviados para o seu Cemitério, enquanto este card estiver no Cemitério (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar este efeito de "Dragão-Guarda Promineses" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79912449,'Rondó de Reflexo Mikanko',replace(replace('Só pode ser equipado a um monstro do oponente. \r\nEnquanto você controlar um monstro "Mikanko", tome o controle do monstro equipado. \r\nNenhum duelista pode ativar os efeitos do monstro equipado enquanto você o controlar. \r\nQuando este card deixar o campo, envie o monstro equipado para o Cemitério. \r\nVocê só pode controlar 1 "Rondó de Reflexo Mikanko". \r\nVocê só pode ativar 1 "Rondó de Reflexo Mikanko" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79922118,'Bolo de Gengibre',replace(replace('Durante a Fase de Apoio do seu oponente: você pode fazer com que tantos monstros quanto possível que ele controla ganhem 600 de ATK e, depois, destrua tantos monstros quanto possível que ele controla com 2500 ou mais de ATK e, se isso acontecer, ganhe PV igual ao número de monstros destruídos x 500. \r\n(O ganho de ATK permanece mesmo que este card deixe o campo.) \r\nVocê só pode usar este efeito de "Bolo de Gengibre" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79928401,'Victorica, a Anja da Bravura',replace(replace('Se este card for Invocado por Invocação-Especial: você pode Invocar por Invocação-Especial 1 monstro de LUZ de Nível 5 ou mais da sua mão, mas você perde PV igual ao seu ATK original e, além disso, seu ATK se torna o dobro até o final deste turno. \r\nSe este card na Zona de Monstros for destruído: você pode banir 1 outro monstro Fada do seu Cemitério; adicione 1 monstro Fada com o mesmo Nível que o desse monstro do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "Victorica, a Anja da Bravura" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79933029,'Purrelyly',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 card "Purrely" do seu Deck à sua mão, exceto uma Magia Rápida. \r\nVocê pode escolher 1 Magia Rápida "Purrely" no seu Cemitério; Invoque por Invocação-Especial 1 Monstro Xyz do seu Deck Adicional que mencione esse card, usando este card que você controla como matéria e, se isso acontecer, associe essa Magia ao monstro Invocado. \r\n(Isso é considerado uma Invocação-Xyz.) \r\nVocê só pode usar cada efeito de "Purrelyly" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79936051,'Fogo Cruzado do Norte',replace(replace('Se a soma dos Níveis dos monstros que você controla for 10 ou mais: adicione à sua mão ou Invoque por Invocação-Especial 1 monstro de Nível 10 da sua mão ou do Deck. \r\nSe a soma dos Níveis dos monstros que seu oponente controla for 10 ou mais: você pode banir este card e 1 monstro de Nível 10 do seu Cemitério e, depois, escolha 1 card que seu oponente controla; bana-o. \r\nVocê só pode usar 1 efeito de "Fogo Cruzado do Norte" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar','Banir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79965360,'Herança Amazoness',replace(replace('Só pode ser equipado a um monstro "Amazoness". \r\nNa primeira vez que o monstro equipado seria destruído em batalha a cada turno, ele não é destruído. \r\nDepois do cálculo de dano, se o monstro equipado atacou um monstro: destrua o monstro atacado.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79966218,'Princesa Dracaena, a Árvore Sedenta',replace(replace('Você pode enviar 1 monstro Planta de Nível 4 ou menos do seu Deck para o Cemitério, exceto "Princesa Dracaena, a Árvore Sedenta"; Invoque este card por Invocação-Especial da sua mão e, se isso acontecer, ele se torna do Nível desse monstro enviado. \r\nVocê pode banir 1 monstro Planta e este card do seu Cemitério; Invoque por Invocação-Especial 1 monstro Dragão da sua mão ou do Cemitério. \r\nVocê só pode usar cada efeito de "Princesa Dracaena, a Árvore Sedenta" uma vez por turno e, além disso, você não pode Invocar por Invocação-Especial no turno em que ativar qualquer um dos efeitos deste card, exceto monstros Dragão ou Planta.','\r',char(13)),'\n',char(10)),'Invocação Especial','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79967395,'Cobra-chicote-do-oeste Camarartista','Uma vez por turno, durante a Fase Principal de qualquer duelista: você pode escolher 1 monstro com a face para cima no campo; até o final deste turno, troque o ATK atual pela DEF atual dele.','Trocar ATK e DEF','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79968632,'Habilidade Secreta dos Seis Samurai',replace(replace('Envie 1 monstro que você controla para o Cemitério e, depois, escolha 1 dos seus monstros "Seis Samurai" banidos; Invoque-o por Invocação-Especial. \r\nVocê só pode ativar 1 "Habilidade Secreta dos Seis Samurai" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79972330,'Borbolespiã Papilionidae','Quando outro monstro que você controla causar dano de batalha ao seu oponente: escolha 1 monstro com a face para cima que seu oponente controla; ele perde ATK igual ao dano de batalha causado.','Reduzir ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79979666,'Homem Bolha, o HERÓI do Elemento',replace(replace('Se este for o único card na sua mão, você pode Invocá-lo por Invocação-Especial (da sua mão). \r\nQuando este card for Invocado: você pode comprar 2 cards. \r\nVocê não deve controlar nenhum outro card e não deve ter cards na sua mão para ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Invocação Especial','Comprar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79985120,'Ataqueraptor - Falcão Revolto - Ataque Aéreo',replace(replace('3 monstros Besta Alada de Nível 6	\r\nVocê também pode Invocar este card por Invocação-Xyz ao descartar 1 Magia "Magia de Aumento de Classe" e usar um Monstro Xyz "Ataqueraptor" de Classe 5 ou menos que você controla como matéria. \r\n(Transfira suas matérias para este card.) \r\nSe este card for Invocado por Invocação-Xyz: você pode escolher 1 monstro que seu oponente controla; destrua-o e, se ele estava com a face para cima, cause dano ao seu oponente igual ao ATK que ele tinha no campo. \r\nSe este card em sua posse for destruído por um card do oponente e enviado para o seu Cemitério: você pode Invocar por Invocação-Especial 1 "Ataqueraptor - Falcão Revolto" do seu Deck Adicional e, se isso acontecer, associe este card a ele como matéria.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Xyz usando como matéria um Monstro Xyz "Ataqueraptor" de Classe 5 ou menos?','Destrua 1 monstro do seu oponente','Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79997591,'Pasodoble',replace(replace('Quando um monstro do oponente declarar um ataque contra um monstro com a face para cima em Posição de Ataque que você controla: em vez disso, transforme o ataque do seu oponente em um ataque direto e cause dano ao seu oponente igual ao ATK do alvo do ataque que você controla. \r\nAlém disso, esse monstro que você controla pode atacar diretamente seu oponente durante seu próximo turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80015408,'Reverscimento Eneanave',replace(replace('Embaralhe qualquer número de Cards de Monstro "Eneanave" da sua mão e/ou do campo com a face para cima no Deck/Deck Adicional e, depois, compre cards igual ao número embaralhado. \r\nSe seu oponente Invocar um ou mais monstros por Invocação-Normal ou Especial, enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode banir este card e ativar 1 desses efeitos;\r\n● Invoque por Invocação-Especial 1 monstro "Eneanave" da sua mão com a face para baixo em Posição de Defesa.\r\n● Coloque 1 monstro "Eneanave" com a face para baixo em Posição de Defesa que você controla, com a face para cima em Posição de Defesa.	\r\nVocê só pode ativar 1 "Reverscimento Eneanave" por turno.','\r',char(13)),'\n',char(10)),'Ativar','Escolher um efeito','Invocação Especial','Mudar a posição de batalha','','','','','','','','','','','','');
INSERT INTO texts VALUES(80019195,'Cavaleiro Lendário Timaeus',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial com "Lenda do Coração". \r\nQuando este card for Invocado por Invocação-Especial: você pode escolher 1 Magia/Armadilha com a face para cima no campo; bana o alvo. \r\nQuando este card for escolhido como alvo de um ataque: você pode escolher 1 Magia no seu Cemitério; Baixe o alvo.','\r',char(13)),'\n',char(10)),'Banir','Baixar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80032567,'Jurrac Giganoto',replace(replace('1 Regulador + 1+ monstros Dinossauro não-Reguladores	\r\nMonstros "Jurrac" que você controla ganham 200 de ATK para cada monstro "Jurrac" no seu Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80033124,'Impacto Cibersombrio!','Invoque por Invocação-Fusão 1 "Dragão Cibersombrio" do seu Deck Adicional, ao embaralhar no Deck, como Matéria de Fusão, 1 de cada de "Chifre Cibersombrio", "Lâmina Cibersombria" e "Enquilha Cibersombria" da sua mão, do campo e/ou do Cemitério.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80036543,'Esperança de Fuga','Se os PV do seu oponente forem pelo menos 1000 a mais que os seus: pague 1000 PV; compre 1 card para cada 2000 pontos de diferença entre os seus PV e os do seu oponente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80040886,'Dragão Mech da Marinha',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Especial: você pode escolher cards com a face para cima que seu oponente controla, até o número de Reguladores no seu Cemitério; negue seus efeitos até o final deste turno. \r\nSe este card Invocado por Invocação-Sincro for destruído por um efeito de card e enviado para o Cemitério: você pode escolher 1 Regulador no seu Cemitério; adicione-o à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80044027,'Dança de Fogo Mikanko',replace(replace('Invoque por Invocação-Especial 1 monstro "Mikanko" da sua mão ou do Cemitério e, se isso acontecer, equipe-o com este card e, depois, você pode Invocar por Invocação-Especial 1 monstro do Cemitério do seu oponente no campo dele, mas negue seus efeitos. \r\nO monstro equipado não pode ser destruído por efeitos de card. \r\nVocê só pode ativar 1 "Dança de Fogo Mikanko" por turno.','\r',char(13)),'\n',char(10)),'','Invocar por Invocação Especial o monstro selecionado para o campo do seu oponente?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80045583,'Canhão do Mecanismo Antigo','Você pode oferecer este card como Tributo; cause 500 de dano ao oponente e, se isso acontecer, nenhum duelista pode ativar Cards de Armadilha durante a Fase de Batalha deste turno.','Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80054655,'Filhote Sônico da Encruzilhada',replace(replace('Se um ou mais Reguladores forem enviados para o seu Cemitério, mesmo durante a Etapa de Dano: você pode Invocar este card por Invocação-Especial do seu Cemitério (se ele estava lá quando o monstro foi enviado) ou da mão (mesmo se ele não estava), mas bana-o quando ele deixar o campo e, depois, se "Guerreiro Sucata" ou um monstro que o mencione (exceto este card) estiver no campo, você pode colocar todos os monstros que seu oponente controla com 1900 ou mais de ATK em Posição de Defesa e, além disso, pelo resto deste turno, você não pode Invocar por Invocação-Especial do Deck Adicional, exceto Monstros Sincro. \r\nVocê só pode usar este efeito de "Filhote Sônico da Encruzilhada" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Mudar a posição de batalha?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80071619,'Cajado do Pastor R.B.',replace(replace('2+ monstros, incluindo um monstro "R.B."	\r\nGanha 500 de ATK para cada monstro que você controla, exceto este card. \r\nVocê só pode usar cada um dos seguintes efeitos de "Cajado do Pastor R.B." uma vez por turno. \r\nDurante sua Fase Principal: você pode Baixar 1 Armadilha "R.B." do seu Deck ou Cemitério. \r\nDurante a Fase Principal do seu oponente (Efeito Rápido): você pode escolher 3 monstros "R.B." de Nível 3 ou mais no seu Cemitério; coloque 2 no fundo do Deck em qualquer ordem e, se isso acontecer, Invoque o outro por Invocação-Especial em Posição de Defesa.','\r',char(13)),'\n',char(10)),'Baixar uma Armadilha','Retornar ao Deck e Invocar por Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80071763,'Balter Sombrio, o Terrível',replace(replace('"Alma Negra Possuída" + "Sábio da Fronteira"	\r\nA Invocação Fusão deste monstro só pode ser conduzida com os Materiais de Fusão de Monstros descritos acima. \r\nQuando um Card de Magia Normal é ativado, anule o seu efeito pagando 1000 Life Points. \r\nOs efeitos de Monstros de Efeito que este monstro destrói como resultado de um combate, são anulados.','\r',char(13)),'\n',char(10)),'Negar efeitos','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80073414,'Chutador Axônico Absoluto',replace(replace('1 Monstro Sincro Psíquico + 1 Monstro Sincro	\r\nPrimeiro deve ser Invocado por Invocação-Fusão. \r\nNão pode ser destruído por efeitos de card. \r\nSe este card for Invocado por Invocação-Fusão: você pode pagar 2000 PV; bana todos os cards com a face para cima que seu oponente controla. \r\nSe este card estiver no seu Cemitério, exceto no turno em que foi enviado para lá: você pode bani-lo; Invoque por Invocação-Especial 1 Monstro de Fusão Psíquico de Nível 10 do seu Deck Adicional (isso é considerado uma Invocação-Fusão). \r\nVocê só pode usar este efeito de "Chutador Axônico Absoluto" uma vez por turno.','\r',char(13)),'\n',char(10)),'Banir','','Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80075749,'Bolhas Ilusórias',replace(replace('Você só pode ativar este card enquanto existir um card "Homem Bolha, o HERÓI do Elemento" com a face para cima no seu lado do campo. \r\nDurante este turno, você pode ativar 1 Card de Armadilha da sua mão.','\r',char(13)),'\n',char(10)),'Ativar aplicando o efeito de "Bolhas Ilusórias".','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80086070,'Ursártico Caçarola',replace(replace('Não pode ser Invocado por Invocação-Sincro. 	\r\nDeve ser Invocado por Invocação-Especial (do seu Deck Adicional) ao enviar 2 monstros que você controla com 7 Níveis de diferença para o Cemitério (1 Regulador de Nível 8 ou mais e 1 Monstro Sincro não-Regulador). \r\nSe este card for Invocado por Invocação-Especial: você pode escolher até 2 outros cards no campo; destrua-os. \r\nUma vez por turno, quando um card ou efeito for ativado que escolha como alvo um card "Ursártico(a)" que você controla (Efeito Rápido): você pode oferecer 1 monstro da sua mão ou do campo como Tributo; negue a ativação.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80088625,'Lâmina Binária',replace(replace('2 Monstros Normais	\r\nEste card ganha esses efeitos de acordo com o número de monstros co-linkados a este card.\r\n● 1+: Quando este card declarar um ataque contra um monstro do oponente: você pode ativar este efeito; este card pode realizar um segundo ataque durante cada Fase de Batalha neste turno e, além disso, se este card batalhar um monstro do oponente neste turno, esse monstro do oponente não pode ser destruído nessa batalha.\r\n● 2: Depois do cálculo de dano, se este card batalhou um monstro do oponente: você pode banir o monstro do oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80101899,'Truque de Sapateado',replace(replace('Bana 1 Armadilha Normal do seu Deck, exceto "Truque de Sapateado" e, se isso acontecer, Baixe 1 card com o mesmo nome diretamente do seu Deck. \r\nEle pode ser ativado neste turno. \r\nVocê só pode ativar 1 Card de Armadilha pelo resto deste turno depois que este card resolver. \r\nVocê só pode ativar 1 "Truque de Sapateado" por turno.','\r',char(13)),'\n',char(10)),'Ativar aplicando o efeito de "Truque de Sapateado".','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80101900,'Truque de Sapateado',replace(replace('Bana 1 Armadilha Normal do seu Deck, exceto "Truque de Sapateado" e, se isso acontecer, Baixe 1 card com o mesmo nome diretamente do seu Deck. \r\nEle pode ser ativado neste turno. \r\nVocê só pode ativar 1 Card de Armadilha pelo resto deste turno depois que este card resolver. \r\nVocê só pode ativar 1 "Truque de Sapateado" por turno.','\r',char(13)),'\n',char(10)),'Ativar aplicando o efeito de "Truque de Sapateado".','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80102359,'Psíquicoborgue Reforçado','Até duas vez por turno, você pode remover de jogo 1 monstro do Tipo Psíquico do seu Cemitério para fazer com que este card ganhe 500 de ATK.','Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80108118,'Sabre-X Urbellum',replace(replace('1 Regulador + 1+ não-Reguladores	\r\nQuando este card causar dano de batalha ao seu oponente, enquanto ele tiver 4 ou mais cards na mão dele: coloque 1 card aleatório da mão dele no topo do Deck.','\r',char(13)),'\n',char(10)),'Retornar ao Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80117527,'Número 11: Grande Olho',replace(replace('2 monstros de Nível 7	\r\nUma vez por turno: você pode desassociar 1 matéria deste card e, depois, escolha 1 monstro que seu oponente controla; tome o controle desse monstro. \r\nEste card não pode atacar no turno em que este efeito for ativado.','\r',char(13)),'\n',char(10)),'Tome o controle','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80141055,'Ursobloqueador',replace(replace('Durante o turno do seu oponente, os cards Baixados nas suas Zonas de Magias & Armadilhas não podem ser destruídos por efeitos de card. \r\nSe um ou mais cards Baixados na sua Zona de Magias & Armadilhas forem destruídos por um efeito de card do oponente: este card ganha 800 de ATK até o final deste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80141480,'Aranha Caçadora','Este monstro come tudo o que apanhar sua teia.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80143954,'Camuflagem Altergeist',replace(replace('Escolha 1 monstro "Altergeist" que você controla; equipe este card a ele. \r\nSeu oponente não pode escolhê-lo como alvo de ataques, mas isso não impede seu oponente de atacar você diretamente. \r\nNegue os efeitos dos monstros do oponente que ativam ao escolher o monstro equipado como alvo. \r\nSe um ou mais cards "Altergeist" que você controla seriam destruídos em batalha ou por um efeito de card, em vez disso, você pode banir este card do seu Cemitério.','\r',char(13)),'\n',char(10)),'Usar o efeito de "Camuflagem Altergeist" em vez de ser destruído?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80159717,'Cavaleiro Dragunidade - Tridente',replace(replace('1 Regulador Dragão + 1+ monstros Besta Alada não-Reguladores	\r\nUma vez por turno: você pode enviar até 3 cards que você controla para o Cemitério; olhe o Deck Adicional do seu oponente e, se isso acontecer, envie o mesmo número de cards dali para o Cemitério.','\r',char(13)),'\n',char(10)),'Verificar o Deck Adicional','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80161395,'Mystik Wok',replace(replace('Ofereça 1 monstro no seu Campo como Tributo. \r\nEscolha o ATK ou o DEF do monstro oferecido como Tributo e aumente os seus Life Points pelo mesmo valor.','\r',char(13)),'\n',char(10)),'Escolha o valor para ganhar','ATK do monstro','DEF do monstro','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80163754,'Bafo Explosivo','Ofereça como Tributo 1 monstro do Tipo Dragão; destrua todos os monstros com a face para cima no campo cuja DEF seja menor ou igual ao ATK que o monstro oferecido como Tributo tinha no campo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80168720,'A Escuridão se Aproxima',replace(replace('Descarte 2 cards da sua mão. \r\nSelecione 1 monstro com face para cima e coloque-o com a face para baixo em Posição de Defesa.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80170678,'EN - Engajar Neo Espaço',replace(replace('Envie para o Cemitério 1 monstro "Neoespacial" e 1 monstro "HERÓI do Elemento" (1 da sua mão e 1 do seu Deck); Invoque por Invocação-Especial 1 monstro "Neoespacial" ou 1 monstro "HERÓI do Elemento" de Nível 5 ou mais do seu Deck e, se isso acontecer, adicione 1 "Polimerização" do seu Deck ou Cemitério à sua mão. \r\nSe você Invocar "Neos, o HERÓI do Elemento" por Invocação-Especial por este efeito, ele ganha 1000 de ATK. \r\nVocê não pode Invocar monstros por Invocação-Especial do Deck Adicional, exceto Monstros de Fusão, no turno em que ativar este card. \r\nVocê só pode ativar 1 "EN - Engajar Neo Espaço" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80181649,'"Um Caso para K9"',replace(replace('Quando este card for ativado: você pode adicionar 1 monstro "K9" do seu Deck à sua mão. \r\nMonstros "K9" que você controla ganham 900 de ATK durante qualquer turno em que seu oponente tenha ativado um efeito de monstro na mão ou no Cemitério. \r\nSe este card na Zona de Magias & Armadilhas for destruído por um efeito de card: você pode Baixar 1 Magia Rápida "K9" do seu Deck ou Cemitério. \r\nVocê só pode usar este efeito de ""Um Caso para K9"" uma vez por turno. \r\nVocê só pode ativar 1 ""Um Caso para K9"" por turno.','\r',char(13)),'\n',char(10)),'Ativar','','Baixar','Adicionar este card à mão?','','','','','','','','','','','','');
INSERT INTO texts VALUES(80186010,'Destrossauro','Você pode descartar este card para o Cemitério; adicione 1 "Mundo Jurássico" do seu Deck à sua mão.','Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80190753,'Talaya, Princesa das Flores de Cereja',replace(replace('Ganha 100 de ATK para cada monstro Planta que você controla. \r\nOutros monstros Planta no campo não podem ser destruídos por efeitos de card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80193355,'Salvamento Dramático','Quando um card for ativado que escolha um monstro "Amazoness" no campo: devolva o monstro alvo para a mão e, se isso acontecer, Invoque por Invocação-Especial 1 outro monstro da sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80193356,'Salvamento Dramático','Quando um card for ativado que escolha um monstro "Amazoness" no campo: devolva o monstro alvo para a mão e, se isso acontecer, Invoque por Invocação-Especial 1 outro monstro da sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80196387,'Sino Rosa da Revelação',replace(replace('Adicione 1 monstro Planta com 2400 ou mais de ATK do seu Deck à sua mão. \r\nVocê pode banir este card do seu Cemitério; Invoque por Invocação-Especial 1 monstro Planta com 2400 ou mais de ATK da sua mão. \r\nVocê só pode usar 1 efeito de "Sino Rosa da Revelação" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80204957,'Fundos de Reserva Karakuri',replace(replace('Selecione 1 monstro "Karakuri" com a face para cima que você controla. \r\nAdicione 1 monstro "Karakuri" de Nível 4 ou menos do seu Deck à sua mão e mude a posição de batalha do monstro selecionado.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80208158,'D.D. Andorinha Estelar Esper',replace(replace('Só pode haver 1 "D.D. Andorinha Estelar Esper" no campo. \r\nSeu oponente não pode escolher outros monstros que você controla como alvo de efeitos ou ataques. \r\nQuando um monstro do oponentes declarar um ataque direto enquanto este card estiver em seu Cemitério: você pode Invocar este card por Invocação-Especial do seu Cemitério com a face para cima em Posição de Defesa. \r\nSe ele for Invocado desta forma, bana-o quando ele deixar o campo.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80208225,'Picada Caudraco',replace(replace('Escolha 1 monstro e/ou 1 Magia/Armadilha no Cemitério do seu oponente; bana-os e, depois, você pode colocar 1 card "Caudraco" do seu Cemitério ou banimento no fundo do seu Deck, exceto "Picada Caudraco" e, depois, compre 1 card. \r\nVocê só pode ativar 1 "Picada Caudraco" por turno.','\r',char(13)),'\n',char(10)),'Ativar','Recuperar e comprar 1 card?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80208323,'Besta Interplanetariapurpuraespinhosa',replace(replace('Quando um monstro que você controla for destruído em batalha e enviado para o Cemitério enquanto este card estiver no seu Cemitério: você pode Invocar este card por Invocação-Especial do seu Cemitério. \r\nSe ele for Invocado desta forma, bana este card quando ele deixar o campo. \r\nVocê só pode usar o efeito de "Besta Interplanetariapurpuraespinhosa" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80222045,'Breeze, o Eletrovor de Rkunas',replace(replace('Um cão misterioso que emite luz for um breve momento emitindo sua própria energia vital.\r\nApós presencia-lo, sua imagem cativante é gravada na sua mente e nunca te abandona.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80230510,'Sacrifício das Tumbas','Uma vez durante este turno, você pode Invocar por Invocação-Tributo um monstro que requer 2 Tributos ao banir 1 monstro de cada Cemitério, em vez dos Tributos e, além disso, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno.','Invocar por Invocação Tributo banindo monstros do Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80233946,'Tartaruga Gora','Enquanto este card permanecer no Campo com a face para cima, monstros com um ATK igual a 1900 ou superior não podem declarar um ataque.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80234301,'Prisman','Este monstro cristalino foca a luz para criar um laser letal.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80237445,'Artefato Mjollnir',replace(replace('Você pode Baixar este card da sua mão na sua Zona de Magias & Armadilhas como uma Magia. \r\nDurante o turno do seu oponente, se este card Baixado na Zona de Magias & Armadilhas for destruído e enviado para o seu Cemitério: Invoque-o por Invocação-Especial. \r\nSe este card for Invocado por Invocação-Especial durante o turno do seu oponente: escolha 1 monstro "Artefato" no seu Cemitério; Invoque-o por Invocação-Especial em Posição de Defesa e, além disso, você não pode Invocar monstros por Invocação-Especial até o final do próximo turno, exceto monstros "Artefato". \r\nVocê só pode usar este efeito de "Artefato Mjollnir" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80244114,'Fantasma da Poeira Estelar',replace(replace('Quando este card que você controla for destruído por um card do seu oponente (seja em batalha ou por efeito de card) e enviado para o seu Cemitério, você pode selecionar 1 "Dragão da Poeira Estelar" no seu Cemitério e Invocá-lo por Invocação-Especial com a face para cima em Posição de Defesa. \r\nVocê pode remover de jogo este card no Cemitério para selecionar 1 Monstro Sincro do Tipo Dragão com a face para cima que você controla. \r\nUma vez por turno, esse Monstro Sincro não pode ser destruído em batalha, mas cada vez que este efeito for aplicado, ele perde 800 de ATK e DEF no final da Etapa de Dano.','\r',char(13)),'\n',char(10)),'Invocação Especial','Não pode ser destruído em batalha','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80250185,'Dragão Autofoguette',replace(replace('Quando um efeito de Monstro Link for ativado que escolha como alvo este card com a face para cima no campo (Efeito Rápido): você pode destruir este card e, depois, envie para o Cemitério 1 Magia/Armadilha no campo. \r\nDurante a Fase Final, se este card estiver no Cemitério porque foi destruído no campo, em batalha ou por um efeito de card e enviado para lá neste turno: você pode Invocar por Invocação-Especial 1 monstro "Foguette" do seu Deck, exceto "Dragão Autofoguette". \r\nVocê só pode usar cada efeito de "Dragão Autofoguette" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80250319,'Alicercinza Limo Jr.',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode escolher 1 monstro "Alicercinza" no seu Cemitério; pelo resto deste turno, você não pode Invocar outros monstros por Invocação-Especial, exceto monstros de ÁGUA e, além disso, Invoque esse monstro por Invocação-Especial e, depois, você pode Invocar por Invocação-Especial da sua mão, 1 monstro do Tipo Aqua com o mesmo Nível que o monstro Invocado por Invocação-Especial pelo efeito deste card. \r\nQuando este card for destruído em batalha e enviado para o Cemitério: você pode Invocar por Invocação-Especial 1 monstro "Alicercinza" do seu Deck.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial do Cemitério','Invocar por Invocação Especial um monstro Aqua da sua mão?','Invocar por Invocação Especial do Deck','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80254726,'Finalização do Pássaro Negro',replace(replace('Quando um monstro que seu oponente controla ativar seu efeito: você pode enviar 1 monstro "Asanegra" com a face para cima que você controla para o Cemitério; negue a ativação e, se isso acontecer, destrua-o e, depois, você pode Invocar por Invocação-Especial 1 "Dragão de Asas Negras" do seu Deck Adicional. \r\nSe você controlar um Monstro Sincro "Asanegra" ou um "Dragão de Asas Negras", você pode ativar este card da sua mão.','\r',char(13)),'\n',char(10)),'Invocar "Dragão de Asas Negras" por Invocação Especial?','Ativar aplicando o efeito de "Finalização do Pássaro Negro".','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80275707,'Papagaio-do-mar Risonho',replace(replace('Se uma Magia/Armadilha com a face para cima estiver no campo: você pode Invocar este card por Invocação-Especial da sua mão. \r\nVocê pode oferecer como Tributo 1 monstro Besta Alada e, depois, escolha 1 Magia/Armadilha com a face para cima no campo; devolva esse card com a face para cima para a mão, mas pelo resto deste turno, você não pode ativar cards, ou os efeitos de cards, com o mesmo nome que esse card tinha quando foi devolvido à mão. \r\nEste é um Efeito Rápido se todos os monstros que você controla forem monstros Besta Alada (mín. 1). \r\nVocê só pode usar cada efeito de "Papagaio-do-mar Risonho" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80280737,'Ativar Modo de Ataque','Ofereça 1 Monstro Sincro como Tributo; Invoque por Invocação-Especial do seu Deck em Posição de Ataque, 1 monstro "/Modo de Ataque" cujo nome inclua o nome do monstro oferecido como Tributo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80280944,'Gigante Rex',replace(replace('Não pode atacar diretamente. \r\nSe este card for banido: você pode Invocar este card por Invocação-Especial e, se isso acontecer, este card ganha 200 de ATK para cada um dos seus monstros Dinossauro banidos. \r\nVocê só pode usar este efeito de "Gigante Rex" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80304126,'Valquíria do Mago','Monstros que seu oponente controla não podem escolher monstros do Tipo Mago com a face para cima como alvo de ataques, exceto este.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80312545,'Abertura dos Portões Espirituais',replace(replace('Quando este card for ativado: adicione 1 "Uria, o Senhor das Chamas Cortantes", "Hamon, o Senhor do Trovão Impactante" ou "Raviel, o Senhor dos Fantasmas", OU 1 monstro que mencione qualquer um desses cards, do seu Deck à sua mão. \r\nUma vez por turno: você pode descartar 1 card; Invoque por Invocação-Especial 1 monstro Demônio com 0 de ATK/DEF do seu Cemitério. \r\nUma vez por turno, se você controlar um monstro de Nível 10: você pode adicionar 1 Magia Contínua do seu Cemitério à sua mão. \r\nVocê só pode ativar 1 "Abertura dos Portões Espirituais" por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Recuperar do Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80316585,'Cyber Lady Harpia','(O nome deste card deve ser sempre considerado como "Lady Harpia".)','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80320877,'Destruição DoomZ',replace(replace('Escolha 1 Monstro Xyz "DoomZ" que você controla; equipe este card a ele com o seguinte efeito.\r\n● Cards não podem ser adicionados do Deck Principal à mão do seu oponente exceto ao serem comprados.	\r\nSe este card for destruído por um efeito de card: você pode escolher 1 monstro com a face para cima no campo; equipe 1 monstro "DoomZ" do seu Deck a ele como uma Magia de Equipamento. \r\nVocê só pode usar cada efeito de "Destruição DoomZ" uma vez por turno.','\r',char(13)),'\n',char(10)),'Equipar este card','Equipar do Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80321197,'Laminador Carmesim',replace(replace('1 Regulador + 1 ou mais monstros não-Reguladores	\r\nSe este card destruir um monstro do oponente em batalha e o enviar para o Cemitério: seu oponente não pode Invocar por Invocação-Normal ou Especial monstros de Nível 5 ou mais durante o próximo turno dele.','\r',char(13)),'\n',char(10)),'Restrição de Invocação','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80326401,'Desejos para Azul nos Olhos',replace(replace('Descarte 1 card; adicione 1 Regulador de LUZ de Nível 1 e 1 Magia/Armadilha que mencione "Dragão Branco de Olhos Azuis", do seu Deck à sua mão, exceto "Desejos para Azul nos Olhos". \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 "Dragão Branco de Olhos Azuis" que você controla; equipe 1 monstro "Olhos Azuis" do seu Deck Adicional a ele como uma Magia de Equipamento que concede a ele 400 de ATK. \r\nVocê só pode usar cada efeito de "Desejos para Azul nos Olhos" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Equipar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80335817,'Mago Destruidor do Tempo',replace(replace('Escala de Pêndulo = 2\r\n[ Efeito de Pêndulo ]\r\nA cada turno, o(s) primeiro(s) \r\nMonstro(s) \r\nPêndulo que você controla que seria(m) destruído(s) por um efeito de card do oponente, não é(são) destruído(s).\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nQuando este card for Invocado por Invocação-Pêndulo da mão (e nenhum outro card for Invocado por Invocação-Pêndulo ao mesmo tempo): você pode fazer com que o ATK deste card se torne o dobro do seu ATK original. \r\nUma vez por turno: você pode escolher 1 monstro no campo; até sua próxima Fase de Apoio, bana tanto ele como este card no campo.','\r',char(13)),'\n',char(10)),'Escolha o(s) card(s) a retornar para o campo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80344569,'Grande Toupeira Neoespacial','No começo da Etapa de Dano, se este card batalhar um monstro do oponente: você pode devolver o monstro do oponente e este card para a mão.','Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80352158,'Reverso do Ímã','Escolha 1 dos seus monstros Máquina ou Rocha que estiverem banidos ou no seu Cemitério, que não possam ser Invocados por Invocação-Normal/Baixados; Invoque-o por Invocação-Especial.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80367387,'Bergzak Koa''ki Meiru',replace(replace('Durante cada uma das suas Fases Finais, destrua este card a não ser que você envie 1 "Núcleo de Ferro de Koa''ki Meiru" da sua mão para o Cemitério ou revele 1 monstro do Tipo Guerreiro na sua mão. \r\nSe este card destruir um monstro do oponente em batalha, ele pode atacar mais uma vez, em sequência.','\r',char(13)),'\n',char(10)),'Escolha 1 "Núcleo de Ferro de Koa''ki Meiru" para enviar para o Cemitério','Revele 1 monstro Guerreiro ao seu oponente','Destruir "Bergzak Koa''ki Meiru"','Continuar atacando','','','','','','','','','','','','');
INSERT INTO texts VALUES(80368942,'Festa de Casulos','Invoque por Invocação-Especial 1 monstro "Crisálida" do seu Deck para cada monstro "Neoespacial" com um nome diferente no seu Cemitério.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80402389,'Santuário Verdejante','Quando um monstro Inseto com a face para cima for destruído em batalha ou por um efeito de card e enviado para o Cemitério: seu controlador pode adicionar 1 monstro Inseto com o mesmo Nível que o monstro destruído do seu Deck à sua mão.','Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80433039,'Brisawntarilho & Stru',replace(replace('Se este card com a face para cima deixaria o campo, em vez disso, bana-o. \r\nVocê só pode usar cada um dos seguintes efeitos de "Brisawntarilho & Stru" uma vez por turno e não pode Invocar por Invocação-Especial durante o turno em que ativar qualquer desses efeitos. \r\nSe este card for Invocado por Invocação-Normal: você pode escolher 1 card em qualquer Cemitério; bana-o e, depois, imediatamente depois que este efeito resolver, você pode Invocar 1 monstro Besta Alada por Invocação-Normal. \r\nSe um monstro Besta Alada for Invocado por Invocação-Normal no seu campo enquanto este card estiver banido: você pode adicionar este card à sua mão.','\r',char(13)),'\n',char(10)),'','Adicionar este card à sua mão','Invocar 1 monstro Besta Alada?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80441106,'Keldo','Se este card for destruído em batalha e enviado para o Cemitério: escolha 2 cards no Cemitério do seu oponente; embaralhe-os no Deck.','Retornar ao Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80447641,'Morcego, o Ninja da Floresta',replace(replace('Se um card com a face para cima estiver em uma Zona do Campo, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Morcego, o Ninja da Floresta" por Invocação-Especial uma vez por turno desta forma. \r\nSe este card for Invocado por Invocação-Normal ou Especial e "Prólogo do Conto de Fadas: Amanhecer da Jornada" estiver no seu campo ou Cemitério: você pode adicionar 1 monstro Besta de LUZ do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Morcego, o Ninja da Floresta" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80453041,'Assombração de Yubel',replace(replace('1 monstro "Yubel" + 1 monstro Demônio com 0 de ATK/DEF	\r\nDeve ser Invocado por Invocação-Especial (do seu Deck Adicional) ao embaralhar no Deck/Deck Adicional os cards acima da sua mão, do campo e/ou do Cemitério. \r\nNão pode ser usado como Matéria de Fusão. \r\nNão pode ser destruído em batalha e, além disso, você não sofre dano das batalhas envolvendo este card. \r\nQuando seu oponente ativar um efeito de monstro (Efeito Rápido): você pode oferecer este card como Tributo; o efeito ativado se torna "Seu oponente destrói 1 monstro "Yubel" na mão, no Deck ou no campo dele". \r\nVocê só pode usar este efeito de "Assombração de Yubel" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80457744,'Guerreiro do Impulso',replace(replace('Se você controlar um Regulador, você pode Invocar este card por Invocação-Especial (da sua mão) em Posição de Defesa. \r\nTodos os monstros Guerreiro que você controla ganham 300 de ATK.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80461466,'Grande Mamute do Mundo Inferior',replace(replace('Se este card for Invocado por Invocação-Especial e você controlar "Chamado dos Assombrados" ou um monstro Zumbi, exceto "Grande Mamute do Mundo Inferior": você pode escolher 1 card no campo; destrua-o. \r\nVocê só pode usar este efeito de "Grande Mamute do Mundo Inferior" uma vez por turno. \r\nUm Monstro Xyz Zumbi que tenha este card como matéria ganha este efeito.\r\n● Ganha 1000 de ATK.','\r',char(13)),'\n',char(10)),'Destruir','Aumentar ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80476891,'Poli-Criaquímica Hidragão',replace(replace('Este card é considerado um Monstro Normal enquanto estiver com a face para cima no campo ou no Cemitério. \r\nEnquanto este card for um Monstro Normal no campo, você pode Invocá-lo por Invocação-Normal para fazer com que ele se torne um Monstro de Efeito com esses efeitos.\r\n● Quando outro monstro Gêmeos for Invocado por Invocação-Normal: você pode fazer com que esse monstro ganhe 500 de ATK e DEF.\r\n● Se um ou mais monstros Gêmeos que você controla seriam destruídos por um efeito de card, em vez disso, você pode destruir 1 outro card que você controla.','\r',char(13)),'\n',char(10)),'Aumentar ATK/DEF','Destruir 1 card que você controla em vez disso?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80485722,'Caçador Vampiro','No começo da Etapa de Dano, se este card batalhar um monstro de TREVAS: destrua esse monstro.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80495985,'Tigre das Lâminas de Fóton',replace(replace('Quando este card for Invocado por Invocação-Normal ou Virar: você pode adicionar 1 "Tigre das Lâminas de Fóton" do seu Deck à sua mão. \r\nSe você não controlar outro "Tigre das Lâminas de Fóton", este card perde 800 de ATK.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80513550,'Rainha Dragoa dos Finais Trágicos',replace(replace('Não pode ser Invocado por Invocação-Normal ou Baixado. \r\nEste card só pode ser Invocado por Invocação-Especial enquanto você controlar 3 ou mais Cards de Magia Contínua com a face para cima. \r\nQuando este card atacante causar Dano de Batalha ao seu oponente, seu oponente seleciona e envia 1 card da mão dele ao Cemitério, e você compra 1 card. \r\nDurante sua Fase de Apoio, se este card estiver no seu Cemitério e tiver sido enviado para lá do campo, você pode enviar 1 Card de Magia Contínua com a face para cima que você controla ao Cemitério para Invocar este card por Invocação-Especial do Cemitério.','\r',char(13)),'\n',char(10)),'Comprar','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80516007,'Peixe Raro','"Fusionista" + "Sereia Fascinante"','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80529459,'Raptor de Restolhos',replace(replace('Você pode escolher 1 monstro que você controla; destrua-o e, além disso, durante sua Fase Principal neste turno, você pode Invocar por Invocação-Normal 1 monstro "Restolhos" em adição à sua Invocação-Normal/Baixar (padrão). \r\nSe este card for destruído pelo efeito de um card "Restolhos" e enviado para o seu Cemitério: você pode adicionar 1 "Fábrica de Restolhos" ou 1 monstro "Restolhos" não-Regulador do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "Raptor de Restolhos" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Invocar pelo efeito de "Raptor de Restolhos"','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80532587,'Entidade Anciã N''tss',replace(replace('1 Monstro Sincro + 1 Monstro Xyz	\r\nDeve ser Invocado por Invocação-Especial (do seu Deck Adicional) ao enviar os cards acima que você controla para o Cemitério. \r\nUma vez por turno: você pode Invocar por Invocação-Especial 1 monstro de Nível 4 da sua mão. \r\nSe este card for enviado para o Cemitério: você pode escolher 1 card no campo; destrua-o. \r\nVocê só pode Invocar um ou mais "Entidade Anciã N''tss" por Invocação-Especial uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80534031,'Fluxo de Virtude',replace(replace('Escolha 1 monstro Peixe, Serpente Marinha ou Aqua que você controla e 2 cards que seu oponente controla; destrua-os. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 monstro com a face para cima no campo; se for um monstro de ÁGUA, na próxima vez que ele seria destruído por um efeito de card neste turno, ele não é destruído. \r\nSe não for, ele se torna de ÁGUA. \r\nVocê só pode usar cada efeito de "Fluxo de Virtude" uma vez por turno.','\r',char(13)),'\n',char(10)),'Destruir','Alterar Atributo ou conceder proteção','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80538047,'Tufão Radiante Swen',replace(replace('Se você tiver "Tufão Espacial Místico" no seu Cemitério, ou seu oponente não controlar nenhuma Magia/Armadilha, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Tufão Radiante Swen" por Invocação-Especial uma vez por turno desta forma. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 Magia/Armadilha "Tufão Radiante" ou 1 "Tufão Espacial Místico" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Tufão Radiante Swen" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80538728,'Cavaleiro de Corda',replace(replace('Quando um monstro "de Corda" com a face para cima que você controla for escolhido como alvo de um ataque: Você pode negar o ataque. \r\nEste efeito só pode ser usado uma vez, enquanto este card estiver com a face para cima no campo.','\r',char(13)),'\n',char(10)),'Negar o ataque','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80549379,'Azagaia Dragunidade','Se este card com a face para cima for destruído enquanto estiver em uma Zona de Monstros, você pode equipá-lo a 1 monstro Besta Alada "Dragunidade" que você controla, em vez de enviá-lo para o Cemitério.','Usar o efeito de "Azagaia Dragunidade"?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80551022,'Limo Mimicarniçal',replace(replace('VIRE: Se for a Fase Principal: aplique esses efeitos em sequência.\r\n● Seu oponente pode Invocar por Invocação-Especial 1 monstro "Mimicarniçal" do Deck dele no campo dele.\r\n● Conceda o controle deste card ao seu oponente.	\r\nDurante sua Fase Principal: você pode Invocar este card por Invocação-Especial da sua mão no campo do seu oponente com a face para baixo em Posição de Defesa ou, se seu oponente controlar mais monstros que você, você pode Invocar este card por Invocação-Especial com a face para cima no seu campo. \r\nVocê só pode usar cada efeito de "Limo Mimicarniçal" uma vez por turno.','\r',char(13)),'\n',char(10)),'Efeito de Virar','Invocação Especial','Invocar por Invocação Especial do Deck?','Invocar por Invocação Especial para o seu Campo','Invocar por Invocação Especial para o Campo do seu oponente','','','','','','','','','','','');
INSERT INTO texts VALUES(80551130,'Rasante Milagroso',replace(replace('Escolha 1 dos seus monstros Fada banidos; Invoque-o por Invocação-Especial. \r\nQuando este card deixar o campo, destrua esse monstro. \r\nQuando esse monstro for destruído, destrua este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80555062,'Bujingi Warg','Enquanto este card estiver com a face para cima em Posição de Defesa, outros monstros "Bujin" que você controla não podem ser destruídos por efeitos de card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80555116,'Guardião de Naturia','Se seu oponente Invocar um monstro por Invocação-Normal: este card ganha 300 de ATK até o final deste turno.','Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80559548,'Velocidaroide Laminorangue',replace(replace('Não pode atacar no turno em que for Invocado por Invocação-Normal. \r\nUma vez por turno: você pode escolher 1 monstro com a face para cima no campo; coloque este card em Posição de Defesa e, se isso acontecer, o alvo perde 800 de ATK até o final deste turno.','\r',char(13)),'\n',char(10)),'Posição de Defesa','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80560728,'Milagre Dimensional',replace(replace('Ative este card ao escolher 1 monstro com a face para cima em Posição de Ataque que seu oponente controla. \r\nNo final da Etapa de Dano, quando ele atacar um monstro, mas o alvo do ataque não foi destruído pela batalha: você pode banir 1 monstro do seu Cemitério; ele deve atacar novamente em seguida. \r\nSe o monstro escolhido deixar o campo, destrua este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80565021,'Abertura e4 de Anjoléquia',replace(replace('Se seu oponente começar, você também pode ativar este card da sua mão durante a Fase de Apoio do primeiro turno dele. \r\nColoque 1 Magia de Campo "Anjoléquia" da sua mão, do Deck ou do Cemitério, no seu campo com a face para cima e, se isso acontecer, Invoque por Invocação-Especial 1 monstro "Anjoléquia" de Nível 2 ou 7 do seu Deck Adicional na Zona de Monstros Adicional e, se isso acontecer, coloque 1 monstro "Anjoléquia" do seu Deck Adicional na sua Zona de Magias & Armadilhas como uma Magia Contínua com a face para cima. \r\nAté o final do seu próximo turno depois que este card resolver, você não pode Invocar por Invocação-Especial do Deck Adicional, exceto Monstros Sincro.','\r',char(13)),'\n',char(10)),'Ativar','Ativar aplicando o efeito de "Abertura Angelechy ao e4".','O efeito de "Abertura Angelechy ao e4" está sendo aplicado.','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80566312,'Hino da Luz',replace(replace('Este card é usado para a Invocação-Ritual de "Saffira, a Rainha dos Dragões". \r\nVocê também deve oferecer como Tributo monstros da sua mão ou do campo cuja soma dos Níveis seja igual a 6 ou mais. \r\nSe um ou mais Monstros de Ritual que você controla seriam destruídos em batalha ou por um efeito de card, em vez disso, você pode banir este card do seu Cemitério.','\r',char(13)),'\n',char(10)),'Usar o efeito de "Hino da Luz" em vez de ser destruído?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80570228,'Monge Anarquista dos Seis Samurai',replace(replace('Se você controlar um monstro "Seis Samurai" que não seja "Monge Anarquista dos Seis Samurai", você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Monge Anarquista dos Seis Samurai" por Invocação-Especial uma vez por turno desta forma. \r\nVocê só pode usar cada um dos seguintes efeitos de "Monge Anarquista dos Seis Samurai" uma vez por turno. \r\nSe este card for enviado do campo para o Cemitério: você pode adicionar 1 Magia Rápida "Seis Samurai" do seu Deck à sua mão. \r\nUm monstro "Seis Samurai" que foi Invocado por Invocação-Sincro usando este card ganha este efeito.\r\n● O Nível de todos os monstros que seu oponente controla é reduzido em 1.','\r',char(13)),'\n',char(10)),'','Efeito de busca','','O efeito de "Monge Anarquista dos Seis Samurai" está sendo aplicado.','','','','','','','','','','','','');
INSERT INTO texts VALUES(80577258,'Tela do Clima Nevoso',replace(replace('Monstros de Efeito "do Clima" nas suas Zonas de Monstros Principais da coluna deste card e das colunas adjacentes a ela ganham este efeito.\r\n● Você pode banir este card (Efeito Rápido); adicione 1 card "do Clima" do seu Deck à sua mão e, além disso, você não pode adicionar cards do seu Deck à sua mão pelo resto deste turno, exceto ao comprá-las.	\r\nVocê só pode controlar 1 "Tela do Clima Nevoso".','\r',char(13)),'\n',char(10)),'Adicionar à sua mão 1 card "do Clima" do seu Deck (Tela do Clima Nevoso)','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80584548,'Pelotão de Balistas','Ofereça 1 monstro como Tributo e, depois, escolha 1 card que seu oponente controla; destrua-o.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80600490,'Kageningen','Ele uuusa uma forma física e uma forma de sombra pratacar. Um bixo difííícil de matar!','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80604091,'Oferenda Derradeira','Durante sua Fase Principal ou a Fase de Batalha do seu oponente: você pode pagar 500 PV; imediatamente depois que este efeito resolver, Invoque 1 monstro por Invocação-Normal/Baixar.','Invocação Normal','Usar o efeito?','Invocação Normal (com a face para cima)','Baixar (com a face para baixo)','','','','','','','','','','','','');
INSERT INTO texts VALUES(80604092,'Oferenda Derradeira','Durante sua Fase Principal ou a Fase de Batalha do seu oponente: você pode pagar 500 PV; imediatamente depois que este efeito resolver, Invoque 1 monstro por Invocação-Normal/Baixar.','Invocação Normal','Usar o efeito?','Invocação Normal (com a face para cima)','Baixar (com a face para baixo)','','','','','','','','','','','','');
INSERT INTO texts VALUES(80611581,'Brisawntarilho & Inguin',replace(replace('Se este card for Invocado por Invocação-Tributo: você pode adicionar 1 Magia/Armadilha "Brisawntarilho" do seu Deck à sua mão e, depois, imediatamente depois que este efeito resolver, você pode Invocar 1 monstro por Invocação-Normal. \r\nEnquanto este card Invocado por Invocação-Tributo estiver na Zona de Monstros, seu oponente não pode ativar os efeitos de monstros Invocados por Invocação-Especial que ele controla em Posição de Ataque. \r\nUma vez por batalha, durante o cálculo de dano, se este card batalhar um monstro do oponente (Efeito Rápido): você pode banir 1 card da sua mão; o ATK/DEF atuais desse monstro do oponente são diminuídos pela metade até o final deste turno.','\r',char(13)),'\n',char(10)),'','','Invocar 1 monstro?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80621253,'Mannadium Tórrido',replace(replace('Se você controlar um "Visas Starfrost" ou um monstro com 1500 de ATK/2100 de DEF, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Mannadium Tórrido" por Invocação-Especial uma vez por turno desta forma. \r\nSe este card for destruído em batalha ou por um efeito de card: você pode Invocar por Invocação-Especial 1 Regulador "Mannadium" do seu Deck. \r\nVocê só pode usar este efeito de "Mannadium Tórrido" uma vez por turno.','\r',char(13)),'\n',char(10)),'Se você controlar um monstro específico, você pode Invocar este card por Invocação Especial da sua mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80621422,'Emblema da Saquepatrollha',replace(replace('Só pode ser equipado a um monstro "Saquepatrollha". \r\nEle ganha 500 de ATK e, além disso, seu oponente não pode escolhê-lo como alvo de efeitos de card. \r\nVocê pode enviar este card equipado para o Cemitério; Invoque por Invocação-Especial 1 monstro "Saquepatrollha" do seu Deck Adicional com o mesmo Atributo que um monstro no campo ou no Cemitério e, depois, pegue o monstro que estava equipado com este card e equipe-o como uma Magia de Equipamento a esse monstro Invocado por Invocação-Especial com este efeito.\r\n● O monstro equipado ganha 500 de ATK.	\r\nVocê só pode usar este efeito de "Emblema da Saquepatrollha" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80627281,'Neve Marincesa',replace(replace('Se um ou mais Monstros Link "Marincesa" que você controla forem destruídos em batalha ou por um efeito de card: escolha 1 desses monstros; Invoque por Invocação-Especial 1 Monstro Link "Marincesa" do seu Deck Adicional com um Valor Link menor que o desse monstro. \r\n(Isso é considerado uma Invocação-Link.) \r\nEle não é afetado pelos efeitos de card do seu oponente enquanto você o controlar. \r\nVocê só pode ativar 1 "Neve Marincesa" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80630522,'Flor Cardian Paulownia',replace(replace('Enquanto você controlar um monstro "Flor Cardian" de Nível 11 ou menos: você pode Invocar este card por Invocação-Especial da sua mão e, além disso, você não pode Invocar monstros por Invocação-Normal ou Especial pelo resto deste turno, exceto monstros "Flor Cardian". \r\nQuando este card for alvo de um ataque: você pode negar o ataque, encerre a Fase de Batalha e, depois, compre 1 card.','\r',char(13)),'\n',char(10)),'Invocação Especial','Negar o ataque','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80635735,'Invokado Dee Anima',replace(replace('1 monstro "Aleister" + 1 monstro Invocado por Invocação-Especial do Deck Adicional	\r\nSe este card é Invocado por Invocação-Especial: você pode ativar 1 desses efeitos;\r\n● Destrói todos os monstros que seu oponente controla que foram Invocados por Invocação-Especial do Deck Adicional.\r\n● Destrói todas as Magias/Armadilhas que seu oponente controla.	\r\nQuando seu oponente ativa um efeito de card no Cemitério (Efeito Rápido): você pode banir este card; Invoque por Invocação-Especial 1 monstro "Aliester" do seu Deck, e se o fizer, negue aquele efeito.\r\nVocê só pode usar cada efeito de "Invokado Dee Anima" uma vez por turno.','\r',char(13)),'\n',char(10)),'Escolher um efeito','Invocar por Invocação-Especial e negar o efeito','Destruir 1 monstro','Destruir Magia/Armadilha','','','','','','','','','','','','');
INSERT INTO texts VALUES(80637190,'Aranha Espiã','Quando este card destruir um monstro em Posição de Defesa do oponente em batalha, você pode selecionar e Invocar por Invocação-Especial 1 monstro do Tipo Inseto de Nível 4 ou menos do seu Cemitério.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80651316,'Evolssauro Cerato',replace(replace('Quando este card for Invocado por Invocação-Especial pelo efeito de um monstro "Evoltil": Ele ganha 200 de ATK. \r\nSe este card foi Invocado por Invocação-Especial pelo efeito de um monstro "Evoltil", cada vez que este card destruir um monstro do oponente em batalha: Você pode adicionar 1 monstro "Evoltil" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80666118,'Incandescente Dragão Vermelho Arquidemônio',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nO nome deste card se torna "Dragão Vermelho Arquidemônio" enquanto estiver no campo ou no Cemitério. \r\nUma vez por turno: você pode destruir tantos outros Monstros de Efeito Invocados por Invocação-Especial no campo quanto possível com ATK igual ou menor que o deste card e, depois, cause 500 de dano ao seu oponente para cada monstro destruído.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80678380,'Comando da Divindade Serpente',replace(replace('Ative ao revelar 1 monstro "Peçonha" que esteja na sua mão para o seu oponente. \r\nNegue a ativação e o efeito de um Card de Magia do seu oponente e destrua aquele card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80681226,'Onda Psíquica',replace(replace('Se você controlar um monstro Máquina: envie 1 "Jinzo" da sua mão ou do Deck para o Cemitério; cause 600 de dano ao seu oponente. \r\nDurante sua Fase Principal, exceto no turno em que este card foi enviado para o Cemitério: você pode banir este card do seu Cemitério e, depois, escolha 1 monstro Máquina no seu Cemitério; envie 1 monstro "Jinzo" do seu Deck para o Cemitério e, se isso acontecer, adicione o monstro alvo à sua mão. \r\nVocê só pode usar este efeito de "Onda Psíquica" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80696379,'Dragão Explosão de Meteoros de Olhos Anômalos',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nQuando este card for Invocado por Invocação-Especial: você pode escolher 1 card na sua Zona de Pêndulo; Invoque-o por Invocação-Especial e, além disso, este card não pode atacar pelo resto deste turno. \r\nVocê só pode usar este efeito de "Dragão Explosão de Meteoros de Olhos Anômalos" uma vez por turno. \r\nSeu oponente não pode ativar efeitos de monstro durante a Fase de Batalha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80701178,'Diabretiço Talismandra',replace(replace('Você pode revelar 1 Monstro de Ritual da sua mão; Invoque por Invocação-Especial tanto este card da sua mão quanto 1 monstro "Diabretiço" do seu Deck, exceto "Diabretiço Talismandra". \r\nSe este card for Invocado por Invocação-Especial do Deck: você pode adicionar 1 Monstro de Ritual do seu Deck à sua mão. \r\nVocê só pode usar 1 efeito de "Diabretiço Talismandra" por turno e apenas uma vez por turno. \r\nVocê não pode Invocar monstros por Invocação-Especial do Deck Adicional.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80722024,'Festa dos Ossos Mementotlan',replace(replace('Destrua 1 monstro "Memento" na sua mão ou no campo com a face para cima, pegue 1 monstro "Memento" do seu Deck com um nome diferente e adicione-o à sua mão ou Invoque-o por Invocação-Especial em Posição de Defesa. \r\nDurante sua Fase Principal: você pode banir este card do seu Cemitério e, depois, escolha 1 monstro "Memento" que você controla; se ele atacar um monstro em Posição de Defesa neste turno, cause dano de batalha perfurante ao seu oponente. \r\nVocê só pode usar cada efeito de "Festa dos Ossos Mementotlan" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80723580,'Buraco Armadilha Gigante','Quando 2 ou mais monstros forem Invocados por Invocação-Especial ao mesmo tempo: destrua todos os monstros no campo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80727036,'Tubarão Negro Devorador de Homens','"Kamen do Mar" + "Gosma Horripilante" + "Amazona dos Mares"','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80727721,'Jurrac Aeolo','Você pode oferecer este card como Tributo e, depois, escolha 1 monstro "Jurrac" de Nível 4 ou menos no seu Cemitério, exceto "Jurrac Aeolo"; Invoque-o por Invocação-Especial.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80738884,'Alma Aniquiladora César da Calamidade',replace(replace('Quando um Card de Magia/Armadilha ou efeito de monstro do oponente for ativado que escolha como alvo um ou mais cards que você controla, enquanto você controlar um monstro "Alma Aniquiladora": negue a ativação e, se isso acontecer, destrua esse card e, depois, você pode causar dano ao seu oponente igual ao ATK de 1 monstro "Alma Aniquiladora" que você controla. \r\nVocê só pode ativar 1 "Alma Aniquiladora César da Calamidade" por turno.','\r',char(13)),'\n',char(10)),'','Causar dano ao seu oponente usando o monstro selecionado?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80741828,'Aprendiz de Bruxa','Enquanto este card permanecer no Campo com a face para a cima, aumente o ATK de todos os monstros das TREVAS em 500 pontos e diminua o ATK de todos os monstros da LUZ em 400 pontos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80744121,'HERÓI do Destino - Temeroso','Durante sua Fase de Apoio, se este card estiver no seu Cemitério porque foi destruído em batalha e enviado para lá desde sua última Fase de Apoio: escolha 1 monstro "HERÓI do Destino" no seu Cemitério, exceto "HERÓI do Destino - Temeroso"; Invoque o alvo por Invocação-Especial.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80749819,'Chamado dos Esquecidos',replace(replace('Quando este card for ativado: você pode Baixar até 3 "Chamado dos Assombrados" do seu Deck e/ou Cemitério e, se isso acontecer, até o final do turno do seu oponente, você não pode Invocar por Invocação-Especial, exceto monstros Zumbi ou monstros do Cemitério. \r\nUma vez por turno, se você ativar "Chamado dos Assombrados": você pode escolher 1 monstro que seu oponente controla; envie-o para o Cemitério. \r\nVocê só pode ativar 1 "Chamado dos Esquecidos" por turno.','\r',char(13)),'\n',char(10)),'Ativar','Enviar para o Cemitério','Baixar um card?','O efeito de "Chamado dos Esquecidos" está sendo aplicado.','','','','','','','','','','','','');
INSERT INTO texts VALUES(80758812,'Separação dos Gêmeos',replace(replace('Durante a Fase Principal: você pode descartar 1 card e, depois, ative 1 desses efeitos;\r\n● Invoque por Invocação-Especial 1 monstro Gêmeos do seu Deck como um Monstro de Efeito que ganha seus efeitos.\r\n● Ofereça como Tributo 1 monstro Gêmeos e, se isso acontecer, Invoque por Invocação-Especial 1 monstro Guerreiro de FOGO da sua mão ou do Deck.	\r\nDepois, se você ofereceu como Tributo um monstro Gêmeos que era considerado como um Monstro de Efeito e ganhou seus efeitos, você também pode destruir 1 card no campo.\r\nVocê só pode usar este efeito de "Separação dos Gêmeos" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial um monstro Gêmeos','Ofereça como Tributo e Invoque por Invocação Especial um monstro Guerreiro de FOGO','Destruir 1 card no campo?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80764541,'Número 44: Pégaso Celeste',replace(replace('2 monstros de Nível 4	\r\nUma vez por turno: você pode desassociar 1 Matéria Xyz deste card e, depois, escolher 1 monstro com a face para cima que seu oponente controla; destrua-o, a não ser que seu oponente pague 1000 PV para negar este efeito.','\r',char(13)),'\n',char(10)),'Destruir','Pagar 1000 PV para negar o efeito de "Número 44: Pégaso Celeste"?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80769747,'Serpente de Corrente de Ferro',replace(replace('Durante sua Fase Principal, você pode equipar este card a 1 monstro com a face para cima que seu oponente controla. \r\nEsse monstro perde 800 de ATK e DEF. \r\nQuando ele for destruído em batalha e enviado ao Cemitério, seu controlador envia cards igual ao seu Nível do topo do Deck dele para o Cemitério.','\r',char(13)),'\n',char(10)),'Equipar','Enviar do Deck para o Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80770678,'Espírito da Harpa','Um espírito que acalma a alma com a música da sua harpa celestial.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80773359,'Asanegra Agressor - Onimaru, o Trovão Divino',replace(replace('1 Regulador + 1 ou mais monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro usando um monstro "Asanegra" como Matéria, ele é considerado como um Regulador enquanto estiver com a face para cima no campo. \r\nEste card não pode ser destruído por efeitos de card. \r\nVocê pode escolher 1 monstro "Asanegra" no seu Cemitério; o Nível deste card se torna o mesmo que o desse monstro. \r\nVocê só pode usar este efeito de "Asanegra Agressor - Onimaru, o Trovão Divino" uma vez por Duelo. \r\nSe este card, que foi Invocado por Invocação-Sincro usando apenas Monstros Sincro, atacar, este card ganha 3000 de ATK, apenas durante a Etapa de Dano.','\r',char(13)),'\n',char(10)),'Alterar Nível','Invocar por Invocação Sincro usando apenas Monstros Sincro como matéria','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80776622,'DoSolfacorde Coolia',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nSeu oponente não pode ativar Cards de Magia/Armadilha ou efeitos de monstro quando um ou mais Monstros Pêndulo "Solfacorde" seus forem Invocados por Invocação-Pêndulo.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nVocê pode Invocar este card por Invocação-Especial (da sua mão) ao oferecer como Tributo 2 Monstros Pêndulo. \r\nVocê só pode usar cada um dos seguintes efeitos de "DoSolfacorde Coolia" uma vez por turno. \r\nVocê pode escolher 1 card com a face para cima que seu oponente controla, ou até 2 cards se você tiver uma Escala de Pêndulo ímpar na sua Zona de Pêndulo; negue seus efeitos até o final do turno do seu oponente. \r\nQuando um efeito de um monstro no campo com um ATK igual ou menor que a maior Escala de Pêndulo na sua Zona de Pêndulo x 300 for ativado (Efeito Rápido): você pode destruir esse monstro.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80794697,'Bufferlo de Chamas',replace(replace('Se este card com a face para cima deixar o campo: você pode descartar 1 monstro Ciberso e, se isso acontecer, compre 2 cards. \r\nVocê só pode usar este efeito de "Bufferlo de Chamas" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80796456,'Número 70: Pecado Malevolente',replace(replace('2 monstros de Nível 4	\r\nUma vez por turno: você pode desassociar 1 Matéria Xyz deste card e, depois, escolher 1 monstro que seu oponente controla; bana-o até a próxima Fase de Apoio do seu oponente. \r\nNo final da Etapa de Dano, se este card atacou: você pode fazer com que este card ganhe 300 de ATK e, se isso acontecer, aumente a Classe dele em 3.','\r',char(13)),'\n',char(10)),'Banir um monstro do oponente','Este card ganha ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80801743,'Câmara Abominável dos Desacorrentados',replace(replace('Invoque por Invocação-Especial 1 monstro "Desacorrentado(a)" da sua mão ou do Cemitério. \r\nSe este card Baixado for destruído por um efeito de card: você pode Invocar por Invocação-Especial 1 monstro "Desacorrentado(a)" do seu Deck. \r\nVocê só pode usar cada efeito de "Câmara Abominável dos Desacorrentados" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80802524,'Rompimento Fantardil','Quando exatamente 1 monstro "Fantardil" com a face para cima que você controla (e nenhum outro card) for destruído em batalha ou por um efeito de card do oponente e enviado para o seu Cemitério: escolha 2 monstros "Fantardil" no seu Cemitério com nomes diferentes que o do monstro destruído; Invoque-os por Invocação-Especial com a face para baixo em Posição de Defesa.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80811661,'Receita do Hambúrguer',replace(replace('Este card é usado para a Invocação-Ritual de "Hambúrguer Esfomeado". \r\nVocê também deve oferecer como Tributo monstros da sua mão ou do campo cuja soma dos Níveis seja igual a 6 ou mais.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80813021,'Torike','Apesar de ser fraco na defesa, os chifres afiados deste monstro lhe dão vantagem no ataque.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80825553,'Nuviano - Bola de Fumaça','Bolas de Fumaça são Nuvianos recém-nascidos. Elas têm medo de ficar sozinhas e preferem balançar-se pelo céu com seus amigos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80831552,'Dinolutador Valeonix',replace(replace('Se somente seu oponente controlar um monstro, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nEnquanto você controlar um monstro "Dinolutador" de Link-3 ou mais, monstros com a face para cima que você controla não são afetados pelos efeitos ativados dos monstros de Link-3 ou menos do seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80831721,'Sabatiel - A Pedra Filosofal',replace(replace('Se você tiver um monstro "Kuriboh Alado" no seu Cemitério: pague metade dos seus PV; adicione 1 Magia "Polimerização" ou Magia "Fusão" do seu Deck à sua mão. \r\nSe este card estiver no seu Cemitério: você pode banir 3 cópias de "Sabatiel - A Pedra Filosofal" do seu Cemitério e, depois, escolha 1 monstro no campo; até o final deste turno, ele ganha ATK igual ao ATK do monstro de maior ATK no campo (em caso de empate, você seleciona).','\r',char(13)),'\n',char(10)),'Adicionar à mão','Aumentar ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80839052,'Fornecedor Koa''ki Meiru',replace(replace('Se um monstro Rocha com a face para cima que você controla for enviado para o Cemitério (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe este card for Invocado por Invocação-Especial: você pode adicionar do seu Deck à sua mão, 1 "Núcleo de Ferro de Koa''ki Meiru" ou 1 card que mencione "Núcleo de Ferro de Koa''ki Meiru", exceto "Fornecedor Koa''ki Meiru". \r\nVocê só pode usar cada efeito de "Fornecedor Koa''ki Meiru" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80843006,'Mixousia, a Que Confunde',replace(replace('1 monstro Mago + 1 monstro não-Mago	\r\nVocê pode escolher 1 monstro com a face para cima no campo e declarar 1 Atributo; ele se torna desse Atributo. \r\nDurante a Fase Principal do seu oponente (Efeito Rápido): você pode Invocar por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional, ao banir este card que você controla e monstros do seu campo ou Cemitério como matéria. \r\nSe este card estiver no seu Cemitério: você pode declarar 1 Atributo; este card no Cemitério se torna desse Atributo até o final deste turno. \r\nVocê só pode usar cada efeito de "Mixousia, a Que Confunde" uma vez por turno.','\r',char(13)),'\n',char(10)),'Alterar o Atributo','Invocação Fusão','Alterar o Atributo','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80845034,'PROCURADA: Caçadora dos Despojos do Pecado',replace(replace('Adicione 1 monstro "Diabellstar" do seu Deck ou Cemitério à sua mão. \r\nDurante sua Fase Principal: você pode banir este card do seu Cemitério e, depois, escolha 1 das suas Magias/Armadilhas "Despojos do Pecado" que estiverem banidas ou no seu Cemitério, exceto "PROCURADA: Caçadora dos Despojos do Pecado"; coloque-a no fundo do Deck e, depois, compre 1 card. \r\nVocê só pode usar cada efeito de "PROCURADA: Caçadora dos Despojos do Pecado" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80863132,'Invalidez',replace(replace('Você pode activar este card quando um efeito de comprar card(s) é activado. \r\nAmbos os jogadores vêem os cards comprados pelo efeito e descartam todos eles para o Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80870883,'Dragão Metálico Pleno Negro de Olhos Vermelhos',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro deve ser Invocado por Invocação-Especial com "Metalmorfe Máximo" que foi ativado ao oferecer como Tributo um monstro Dragão de Nível 5 ou mais. \r\nVocê pode revelar este card na sua mão; Baixe 1 Armadilha "Metalmorfe" do seu Deck e, se isso acontecer, embaralhe este card no Deck. \r\nQuando seu oponente ativar um card ou efeito (Efeito Rápido): você pode negar a ativação e, depois, você pode causar dano ao seu oponente igual ao ATK original de 1 monstro em Posição de Ataque que seu oponente controla. \r\nVocê só pode usar cada efeito de "Dragão Metálico Pleno Negro de Olhos Vermelhos" uma vez por turno.','\r',char(13)),'\n',char(10)),'Baixar o Card Armadilha "Metalmorfe"','Negar a ativação','Causar dano novamente?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80885284,'Jiangshi Fantardil',replace(replace('Não pode ser Invocado por Invocação-Normal, a não ser que você controle um monstro "Fantardil". \r\nUma vez por turno: você pode colocar este card com a face para baixo em Posição de Defesa. \r\nQuando este card for virado com a face para cima: você pode adicionar do seu Deck à sua mão, 1 monstro "Fantardil" cujo Nível seja igual ou menor que o número de monstros "Fantardil" que você controla. \r\nVocê só pode usar este efeito de "Jiangshi Fantardil" uma vez por turno.','\r',char(13)),'\n',char(10)),'Mudar para Posição de Defesa com a face para baixo','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80885324,'Atacante Perseguidor',replace(replace('Se este card atacar um monstro com a face para baixo em Posição de Defesa, você pode destruir o monstro imediatamente com o efeito deste card sem virá-lo com a face para cima ou aplicar o cálculo de dano. \r\nSe isso acontecer, este card é colocado em Posição de Defesa no final da Fase de Batalha. \r\nA posição de batalha deste card não pode ser alterada até o final do seu próximo turno, exceto com um efeito de card.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80887714,'Tempestade da Galáxia','Escolha 1 Monstro Xyz com a face para cima no campo que não tenha Matérias Xyz; destrua o alvo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80887952,'Hélios Dismegisto',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) ao oferecer como Tributo 1 "Hélios - O Sol Primordial". \r\nO ATK/DEF deste card se torna o número de monstros banidos x 200. \r\nDurante a Fase Final, se este card estiver no Cemitério porque foi destruído em batalha e enviado para lá neste turno: você pode Invocar este card por Invocação-Especial e ele ganha 300 de ATK/DEF.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80889750,'Peladura de Lâminas - Dente',replace(replace('1 Monstro de Fusão "Peladura" + 1+ monstros "Fofanimal" e/ou "Diabrete de"	\r\nQuando este card for Invocado por Invocação-Fusão: você pode escolher 1 monstro "Peladura" no seu Cemitério; Invoque-o por Invocação-Especial. \r\nTodos os monstros "Peladura" que você controla ganham 400 de ATK. \r\nSe este card foi Invocado por Invocação-Fusão usando 3 ou mais Matérias de Fusão, ele não pode ser destruído em batalha ou por efeitos de card.','\r',char(13)),'\n',char(10)),'Não pode ser destruído em batalha ou por efeitos','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80893872,'Jardim do Pinguim Real',replace(replace('Quando este card for ativado: você pode adicionar 1 card "Pinguim" do seu Deck à sua mão, exceto "Jardim do Pinguim Real". \r\nUma vez por turno, durante sua Fase Principal: você pode diminuir em 1 o Nível de 1 monstro "Pinguim" na sua mão ou no campo com a face para cima (até o final deste turno) e, depois, descarte 1 card. \r\nVocê só pode ativar 1 "Jardim do Pinguim Real" por turno.','\r',char(13)),'\n',char(10)),'Adicionar "Pinguim" do seu Deck à sua mão?','','Escolha o card cujo Nível será reduzido','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80896940,'Alto Paladino Nirvana',replace(replace('Escala de Pêndulo = 8\r\n[ Efeito de Pêndulo ]\r\nSe um Monstro Pêndulo que você controla atacar, para essa batalha, ele não pode ser destruído em batalha e, além disso, você não sofre dano de batalha. \r\nNo final da Etapa de Dano, se um Monstro Pêndulo que você controla atacou: até o final deste turno, todos os monstros que seu oponente controla atualmente perdem ATK igual ao ATK do monstro atacante.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\n1 Regulador + 1+ Monstros Sincro não-Reguladores	\r\nPara a Invocação-Sincro deste card, você pode considerar 1 Monstro Pêndulo Invocado por Invocação-Pêndulo que você controla como um Regulador. \r\nSe este card for Invocado por Invocação-Sincro usando um Monstro Pêndulo Regulador Invocado por Invocação-Pêndulo: você pode escolher 1 card no seu Cemitério; adicione-o à sua mão. \r\nQuando este card destruir um monstro do oponente em batalha: você pode diminuir pela metade os PV do seu oponente. \r\nSe este card na Zona de Monstros for destruído em batalha ou por um efeito de card: você pode colocar este card na sua Zona de Pêndulo.','\r',char(13)),'\n',char(10)),'Invocação Sincro','Usar um Monstro Pêndulo Invocado por Invocação Pêndulo como Regulador para uma Invocação Sincro','Reduzir ATK','Adicionar à mão','Reduza à metade seus PV','Colocar este card na Zona de Pêndulo','','','','','','','','','','');
INSERT INTO texts VALUES(80908502,'Capitão Gold, o HERÓI do Elemento',replace(replace('Você pode descartar este card para o Cemitério; adicione 1 "Arranha-Céu" do seu Deck para sua mão. \r\nSe "Arranha-Céu" não estiver com a face para cima no campo, destrua este card.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80921533,'Mausoléu do Imperador',replace(replace('Durante a Fase Principal: o duelista do turno pode ativar esse(s) efeito(s).\r\n● Pague 1000 PV; imediatamente depois que este efeito resolver, Invoque por Invocação-Normal 1 monstro da sua mão que requer 1 Tributo, sem oferecer Tributo.\r\n● Pague 2000 PV; imediatamente depois que este efeito resolver, Invoque por Invocação-Normal 1 monstro da sua mão que requer 2 Tributos, sem oferecer Tributo. \r\n(Essa é sua uma Invocação-Normal/Baixar do turno em questão.)','\r',char(13)),'\n',char(10)),'Invocação Normal','Invocação Normal (com a face para cima)','Baixar (com a face para baixo)','Escolha os PV a pagar','','','','','','','','','','','','');
INSERT INTO texts VALUES(80925836,'Condenação Koa''ki Meiru',replace(replace('Durante cada uma das suas Fases Finais, destrua este card a não ser que você envie 1 "Núcleo de Ferro de Koa''ki Meiru" da sua mão para o Cemitério ou revele 1 monstro do Tipo Demônio da sua mão. \r\nNegue os efeitos dos monstros de LUZ ou TREVAS que forem ativados durante a Fase Principal.','\r',char(13)),'\n',char(10)),'Escolha 1 "Núcleo de Ferro de Koa''ki Meiru" para enviar para o Cemitério','Revele 1 monstro Demônio para o seu oponente','Destruir "Condenação Koa''ki Meiru"','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80949182,'Vespabatalha - Hama, o Arco Conquistador',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nSe este card foi Invocado por Invocação-Sincro usando um Monstro Sincro como matéria, ele pode realizar um segundo ataque durante cada Fase de Batalha. \r\nVocê só pode usar cada um dos seguintes efeitos de "Vespabatalha - Hama, o Arco Conquistador" uma vez por turno.\r\n● Quando este card causar dano de batalha ao seu oponente: você pode fazer com que todos os monstros que seu oponente controla atualmente percam 1000 de ATK/DEF.\r\n● No final da sua Fase de Batalha, se seu oponente não tiver sofrido nenhum dano de batalha nesta Fase: você pode causar 300 de dano ao seu oponente para cada monstro "Vespabatalha" no seu Cemitério.','\r',char(13)),'\n',char(10)),'Reduzir ATK/DEF','Cause dano ao seu oponente','Invocar por Invocação Sincro usando um Monstro Sincro como matéria','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80955168,'Armadilha da Tumba Emperial','Quando um ou mais monstros Zumbi forem Invocados por Invocação-Especial do Cemitério do seu oponente para o seu campo: escolha 2 cards no campo; destrua-os.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80959027,'Besta Mítica Bashilisco',replace(replace('Escala de Pêndulo = 4\r\n[ Efeito de Pêndulo ]\r\nSe você não tiver nenhum card na sua outra Zona de Pêndulo: você pode destruir este card e, se isso acontecer, embaralhe no seu Deck Principal 1 Monstro Pêndulo Mago com a face para cima no seu Deck Adicional, exceto "Besta Mítica Bashilisco" e, depois, compre 1 card. \r\nVocê só pode usar este efeito de "Besta Mítica Bashilisco" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSempre que um Card de Magia for ativado, coloque 1 Marcador de Magia neste card quando essa Magia resolver. \r\nVocê pode remover 3 Marcadores de Magia do seu campo; devolva 1 card "Besta Mítica" da sua Zona de Pêndulo ou com a face para cima no seu Deck Adicional para a mão. \r\nVocê só pode usar este efeito de "Besta Mítica Bashilisco" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80965043,'Mechamático Adição',replace(replace('Você pode escolher 1 monstro com a face para cima no campo; você não pode Invocar monstros por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto monstros Ciberso e, além disso, Invoque este card por Invocação-Especial da sua mão (mas ele não pode atacar neste turno) e, se isso acontecer, o monstro alvo ganha 1000 de ATK até o final deste turno. \r\nVocê só pode usar este efeito de "Mechamático Adição" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80978111,'"B" Voadora',replace(replace('Quando seu oponente Invocar um ou mais monstros por Invocação-Normal ou Especial (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão no campo do oponente em Posição de Defesa. \r\nO controlador deste card não pode Invocar por Invocação-Xyz.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80987696,'Máquina do Tempo','Quando um monstro for destruído em batalha e enviado para o Cemitério: Invoque esse monstro por Invocação-Especial no mesmo campo e na mesma posição de batalha em que ele estava quando foi destruído.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80993256,'Rei Ashura',replace(replace('3+ monstros de Nível 3	\r\nEnquanto este card tiver matéria, ele pode atacar um número de vezes a cada Fase de Batalha, até o número de matérias associadas a ele. \r\nNo começo da Etapa de Dano, se este card batalhar: ele ganha 200 de ATK. \r\nQuando outro efeito de monstro for ativado (Efeito Rápido): você pode desassociar 1 matéria deste card; negue a ativação e, se isso acontecer, destrua esse card. \r\nVocê só pode usar este efeito de "Rei Ashura" uma vez por turno.','\r',char(13)),'\n',char(10)),'Aumentar ATK','Negar a ativação e destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81000306,'Golpe com Força Total','Escolha 1 monstro com a face para cima que você controla; neste turno, ele não pode ser destruído em batalha, os duelistas não sofrem dano de batalha de seus ataques e se ele atacar um monstro do oponente, destrua esse monstro do oponente depois do cálculo de dano.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81003500,'Xamã Necroide, o HERÓI do Elemento',replace(replace('"Coração Selvagem, o HERÓI do Elemento" + "Necrosombra, o HERÓI do Elemento"	\r\nDeve ser Invocado por Invocação-Fusão. \r\nSe este card for Invocado por Invocação-Especial: escolha 1 monstro que seu oponente controla; destrua o alvo e, depois, Invoque por Invocação-Especial 1 monstro do Cemitério do seu oponente no campo dele.','\r',char(13)),'\n',char(10)),'Destruir e Invocar por Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81005500,'Ween, o Espírito das Gostosuras',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode ativar este efeito; se você ainda controlar este card com a face para cima, seu oponente seleciona 1 desses efeitos para que você aplique.\r\n● Este card ganha 800 de ATK para cada monstro Zumbi atualmente no seu Cemitério.\r\n● Cause 500 de dano ao seu oponente para cada monstro Zumbi no seu Cemitério.	\r\nSe este card for destruído em batalha ou por um efeito de card: você pode Invocar por Invocação-Especial no seu campo 1 monstro do Cemitério do seu oponente.\r\nVocê só pode usar cada efeito de "Ween, o Espírito das Gostosuras" uma vez por turno.','\r',char(13)),'\n',char(10)),'Aumentar ATK ou causar dano','Invocar por Invocação Especial 1 monstro do Cemitério do seu oponente para o seu campo','Aumentar ATK','Causar dano','','','','','','','','','','','','');
INSERT INTO texts VALUES(81019803,'Melffys Felizes',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Especial: você pode escolher 1 monstro com a face para cima no campo; devolva-o para a mão. \r\nSe seu oponente Invocar um ou mais monstros por Invocação-Normal ou Especial (exceto durante a Etapa de Dano), ou se um monstro do oponente escolher este card como alvo de um ataque: você pode devolver este card para o Deck Adicional e, depois, você pode Invocar por Invocação-Especial 1 Monstro Xyz "Melffy" do seu Deck Adicional. \r\nVocê só pode usar cada efeito de "Melffys Felizes" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Retornar este card ao Deck Adicional','Invocar por Invocação Especial do Deck Adicional?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81020140,'Disparador Vulcânico','Quando este card for destruído em batalha e enviado para o Cemitério: você pode colocar 1 monstro "Vulcânico(a)" do seu Deck no topo do seu Deck.','Adicionar à mão','Escolha o card para colocar no topo do Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81020646,'Dragão Ogro do Vácuo',replace(replace('1 Regulador de TREVAS + 1+ monstros não-Reguladores	\r\nUma vez por turno, quando seu oponente ativar um Card de Magia/Armadilha enquanto você não tiver cards na sua mão (Efeito Rápido): você pode negar a ativação e, se isso acontecer, destrua-o.','\r',char(13)),'\n',char(10)),'Negar a ativação e destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81028112,'Lutador Wattsíquico',replace(replace('Quando este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 card no Cemitério do seu oponente; coloque-o no topo ou no fundo do Deck dele. \r\nVocê só pode usar este efeito de "Lutador Wattsíquico" uma vez por turno.','\r',char(13)),'\n',char(10)),'Interferência no Cemitério','Topo do Deck','Fundo do Deck','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81034083,'Besta do Conhecimento Negro',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode adicionar 1 "Uria, o Senhor das Chamas Cortantes", "Hamon, o Senhor do Trovão Impactante" ou "Raviel, o Senhor dos Fantasmas", OU 1 card que mencione qualquer um desses cards, do seu Deck à sua mão, exceto "Besta do Conhecimento Negro". \r\nVocê só pode usar este efeito de "Besta do Conhecimento Negro" uma vez por turno. \r\nDurante sua Fase Principal, você pode Invocar por Invocação-Normal 1 monstro Demônio com 0 de ATK/DEF em adição à sua Invocação-Normal/Baixar (padrão). \r\n(Você só pode se aproveitar deste efeito uma vez por turno.)','\r',char(13)),'\n',char(10)),'','Invocar pelo efeito de "Besta do Conhecimento Negro"','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81035362,'Guerreiro Rino Demoníaco',replace(replace('Monstros Demônio que você controla, exceto "Guerreiro Rino Demoníaco", não podem ser destruídos em batalha ou por efeitos de card. \r\nSe este card for enviado para o Cemitério: você pode enviar 1 monstro Demônio do seu Deck para o Cemitério, exceto "Guerreiro Rino Demoníaco". \r\nVocê só pode usar este efeito de "Guerreiro Rino Demoníaco" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81038234,'Relato do Espelho Onírico',replace(replace('Se um monstro "Espelho Onírico" que você controla seria oferecido como Tributo para ativar seu próprio efeito, embaralhe-o no Deck em vez de enviá-lo para o Cemitério. \r\nDurante a Fase Principal: você pode enviar este card com a face para cima para o Cemitério; coloque 1 dos seus "Espelho Onírico da Alegria" ou "Espelho Onírico do Terror" que estiver banido ou no seu Cemitério, com a face para cima na sua Zona do Campo e, depois, você pode Invocar por Invocação-Especial 1 monstro da sua mão que liste especificamente em seu texto esse card que você colocou na Zona do Campo.','\r',char(13)),'\n',char(10)),'','Invocar por Invocação Especial um monstro da sua mão?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81055000,'Camarartista Guaxinim-Bananeira',replace(replace('Escala de Pêndulo = 3\r\n[ Efeito de Pêndulo ]\r\nVocê pode escolher 1 card "Camarartista" que você controla; devolva-o para a mão, mas pelo resto deste turno, você não pode ativar cards ou os efeitos de cards com o mesmo nome que o devolvido para a mão por este efeito (mesmo que este card deixe o campo). \r\nVocê só pode usar este efeito de "Camarartista Guaxinim-Bananeira" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nQuando este card for destruído em batalha: você pode escolher 1 card no campo; devolva-o para a mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81057455,'Missão de Captura Kaiju',replace(replace('Uma vez por turno, se houver menos de 3 Marcadores Kaiju neste card: você pode escolher 1 monstro "Kaiju" no campo; coloque-o com a face para baixo em Posição de Defesa e, depois, coloque 1 Marcador Kaiju neste card (máx. 3). \r\nSe este card em sua posse for destruído por um card do oponente e enviado para o seu Cemitério: você pode comprar 2 cards. \r\nVocê só pode usar este efeito de "Missão de Captura Kaiju" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81057959,'Humano Dragão','Dotado do poder dos dragões, este guerreiro empunha uma espada criada de uma garra de um dragão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81059524,'Des Volstgalph',replace(replace('Se este card destruir um monstro do oponente em batalha e enviá-lo para o Cemitério: cause 500 de dano ao seu oponente. \r\nSempre que um Card de Magia Normal ou Rápida resolver, este card ganha 200 de ATK até o final do turno em questão.','\r',char(13)),'\n',char(10)),'Causar dano aos PV','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81066751,'Castigo Divino','Quando um Card de Magia/Armadilha ou efeito de monstro for ativado, enquanto "O Santuário no Céu" estiver no campo: negue a ativação e, se isso acontecer, destrua-o.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81078880,'Live☆Gêmea Lil-la Travessa',replace(replace('Se você controlar um monstro "Ki-sikil", você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Live☆Gêmea Lil-la Travessa" por Invocação-Especial uma vez por turno desta forma. \r\nQuando qualquer duelista sofrer dano de uma batalha envolvendo um monstro "Evil★Gêmea": você pode banir este card do seu Cemitério e, depois, escolha 1 monstro com a face para cima que seu oponente controla; ele perde ATK igual a esse dano de batalha. \r\nVocê só pode usar este efeito de "Live☆Gêmea Lil-la Travessa" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81096431,'Tubarão Dragonete',replace(replace('Um Monstro Xyz "Dragonete Tubarão" que tenha este card como matéria ganha este efeito.\r\n● Uma vez por turno: você pode desassociar 2 matérias deste card e, depois, escolha 1 Magia/Armadilha no campo; associe-a a este card como matéria.	\r\nVocê só pode usar cada um dos seguintes efeitos de "Tubarão Dragonete" uma vez por turno. \r\nSe este card for adicionado à sua mão, exceto ao comprá-lo: você pode Invocar este card por Invocação-Especial. \r\nEste card pode ser considerado como 2 matérias para a Invocação-Xyz de um Monstro Xyz de ÁGUA que requeira 3 ou mais matérias.','\r',char(13)),'\n',char(10)),'Invocação Especial','','Associar Matéria Xyz (Tubarão Dragonete)','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81101309,'Trem Noturno Viajante Azul',replace(replace('Você pode descartar este card; adicione 1 "Acoplar Vagão" ou "Pátio de Manobras Giratório" do seu Deck ou Cemitério à sua mão. \r\nSe este card estiver no seu Cemitério: você pode escolher 1 outro monstro Máquina de TERRA no seu Cemitério; Invoque por Invocação-Especial tanto ele quanto este card e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto monstros Máquina. \r\nVocê só pode usar este efeito de "Trem Noturno Viajante Azul" uma vez por Duelo, e seu efeito anterior apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Efeito de busca','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81105204,'Asanegra - Kris, a Luz do Amanhecer',replace(replace('Se você controlar um monstro "Asanegra" que não seja "Asanegra - Kris, a Luz do Amanhecer", você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Asanegra - Kris, a Luz do Amanhecer" por Invocação-Especial uma vez por turno desta forma. \r\nNa primeira vez que este card no campo seria destruído por um efeito de Magia/Armadilha a cada turno, ele não é destruído.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81108658,'Ursártico Megabilis',replace(replace('Durante a Fase Principal (Efeito Rápido): você pode oferecer como Tributo 1 outro monstro de Nível 7 ou mais da sua mão; Invoque este card por Invocação-Especial da sua mão e, além disso, você não pode Invocar por Invocação-Especial pelo resto deste turno, exceto monstros com um Nível. \r\nSe este card for Invocado por Invocação-Especial enquanto você controlar outro monstro "Ursártico(a)": você pode escolher 1 card no Cemitério do seu oponente; bana-o. \r\nVocê só pode usar cada efeito de "Ursártico Megabilis" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81109178,'Fogos de Artifício',replace(replace('Durante o turno de qualquer duelista: você pode descartar este card; cause 1000 de dano ao seu oponente e, se isso acontecer, pule sua próxima Fase de Compra. \r\nVocê só pode usar este efeito de "Fogos de Artifício" uma vez por turno. \r\nSempre que seu oponente sofrer dano de efeito, coloque 1 marcador neste card. \r\nUma vez por turno, durante a Fase Final: remova todos os marcadores deste card que foram colocados por este efeito e, se isso acontecer, para cada uma, cause 300 de dano ao seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81119816,'Ventanimados Travesso-Guris',replace(replace('Se este card for enviado para o Cemitério como matéria para a Invocação-Fusão ou Link de um monstro "Travesso-Guris": você pode enviar 1 card "Travesso-Guris" do seu Deck para o Cemitério, exceto "Ventanimados Travesso-Guris" e, depois, você pode Invocar por Invocação-Especial 1 monstro "Travesso-Guris" da sua mão ou do Deck em Posição de Defesa, exceto "Ventanimados Travesso-Guris". \r\nVocê só pode usar este efeito de "Ventanimados Travesso-Guris" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81122844,'Porta-Aviões Zenmaity de Corda',replace(replace('2 monstros de Nível 3	\r\nUma vez por turno: você pode desassociar 1 Matéria Xyz deste card; Invoque por Invocação-Especial 1 monstro "de Corda" da sua mão ou do Deck. \r\nQuando um monstro "de Corda" com a face para cima no campo for destruído e enviado para o seu Cemitério (exceto durante a Etapa de Dano): você pode desassociar 1 Matéria Xyz deste card para escolher esse monstro; devolva o alvo para a mão.','\r',char(13)),'\n',char(10)),'Invocação Especial','Retornar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81128478,'Aramado do Covil',replace(replace('Remova de jogo 1 monstro do Tipo Inseto do seu Cemitério e selecione 1 monstro que seu oponente controla. \r\nDestrua o monstro selecionado.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81143465,'Trágicas Joias Gêmeas Entrelaçadas',replace(replace('Só pode ser equipado a um monstro que você controla que foi Invocado por Invocação-Especial do Deck Adicional. \r\nSe seu oponente Invocar um ou mais monstros por Invocação-Especial do Deck Adicional com ATK maior que o do monstro equipado (exceto durante a Etapa de Dano): você pode escolher 1 deles; destrua o monstro alvo, destrua o monstro equipado, e se você destruiu pelo menos um deles, você sofre dano igual ao ATK original combinado deles. \r\nDepois, cause dano ao seu oponente igual ao dano que você sofreu.','\r',char(13)),'\n',char(10)),'','Efeito de destruição','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81146288,'Rosária, a Anja Caída Imponente',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nVocê primeiro deve Invocá-lo por Invocação-Especial (da sua mão) ao banir 2 monstros do Tipo Planta de Nível 7 ou mais (1 da sua mão e 1 do seu Cemitério). \r\nUma vez por turno: até o final deste turno, você pode negar os efeitos de todos os outros cards com a face para cima atualmente no campo.','\r',char(13)),'\n',char(10)),'Negar o efeito','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81167171,'Espírito do Herói','Durante a Fase de Batalha, se um monstro "HERÓI do Elemento" que você controla tiver sido destruído em batalha neste turno: O Dano de Batalha de 1 dos monstros do oponente se torna 0.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81171949,'Sorte Grande 7',replace(replace('Quando este card for ativado: embaralhe este card do campo no Deck. \r\nQuando este card em sua posse for enviado para o seu Cemitério por um efeito de card do oponente: bana este card. \r\nSe 3 de seus "Sorte Grande 7" estiverem banidos atualmente e foram todos banidos por este efeito, você vence o Duelo.','\r',char(13)),'\n',char(10)),'Banir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81172176,'Demônio Comediante',replace(replace('Lance uma moeda e dê um palpite. \r\nSe você acertar, todos os cards no Cemitério do oponente são removidos de jogo imediatamente. \r\nSe você errar, envie um número de cards igual aos cards no Cemitério do oponente do seu Deck ao seu Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81172177,'Demônio Comediante',replace(replace('Lance uma moeda e dê um palpite. \r\nSe você acertar, todos os cards no Cemitério do oponente são removidos de jogo imediatamente. \r\nSe você errar, envie um número de cards igual aos cards no Cemitério do oponente do seu Deck ao seu Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81179446,'Lakarta','Ataca os inimigos cuspindo teias finas e pegajosas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81191584,'Pesadelo Recorrente','Escolha 2 monstros de TREVAS com DEF 0 no seu Cemitério; adicione esses alvos à sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81192859,'Pegada Selvagem Gagaku-P.U.N.K.',replace(replace('No começo da Etapa de Dano, se um monstro "P.U.N.K." seu batalhar um monstro do oponente: você pode destruir esse monstro do oponente. \r\nVocê só pode usar este efeito de "Pegada Selvagem Gagaku-P.U.N.K." uma vez por turno. \r\nSe este card na Zona de Magias & Armadilhas do seu dono for destruído por um efeito de card do oponente: você pode ativar este efeito; monstros "P.U.N.K." que você controla atualmente não podem ser destruídos em batalha neste turno.','\r',char(13)),'\n',char(10)),'','','O efeito de "Pegada Selvagem Gagaku-P.U.N.K." está sendo aplicado.','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81193865,'Super Chama Estridente',replace(replace('Só pode ser equipado a um Monstro de Fusão Máquina. \r\nSeu oponente não pode ativar cards ou efeitos durante sua Fase de Batalha. \r\nNo final da Etapa de Dano, se o monstro equipado atacou um monstro do oponente: você pode banir 1 monstro "Dragão Cibernético" do seu Cemitério; o monstro equipado pode atacar um monstro do oponente novamente em seguida. \r\nSeus outros monstros não podem atacar no turno em que você ativar este efeito.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81196066,'Perfume Dançarina Luzlunar',replace(replace('2 monstros "Luzlunar"	\r\nSe este card for Invocado por Invocação-Fusão: você pode adicionar 1 "Perfume Luz Lunar" do seu Deck à sua mão. \r\nVocê pode escolher 1 outro card "Luzlunar" que você controla; devolva-o para a mão/Deck Adicional e, depois, você pode Invocar por Invocação-Especial 1 monstro "Luzlunar" da sua mão. \r\nVocê pode banir este card do seu Cemitério; neste turno, todos os monstros que seu oponente controla perdem ATK igual à sua DEF original. \r\nVocê só pode usar cada efeito de "Perfume Dançarina Luzlunar" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Recuperar','Reduzir ATK','Invocação Especial?','','','','','','','','','','','','');
INSERT INTO texts VALUES(81197327,'Curandeiro a Vapor, o HERÓI do Elemento',replace(replace('"Burstinatrix, o HERÓI do Elemento" + "Homem Bolha, o HERÓI do Elemento"	\r\nDeve ser Invocado por Invocação-Fusão. \r\nSe este card destruir um monstro em batalha e enviá-lo para o Cemitério: ganhe PV igual ao ATK original desse monstro no Cemitério.','\r',char(13)),'\n',char(10)),'Ganhar PV','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81210420,'Cartolas Mágicas',replace(replace('Durante a Fase de Batalha do seu oponente: selecione 2 Magias/Armadilhas do seu Deck e 1 monstro na sua Zona de Monstros Principal. \r\nInvoque-os por Invocação-Especial como Monstros Normais (ATK 0/DEF 0) com a face para baixo em Posição de Defesa, Baixe o monstro selecionado se ele estiver com a face para cima e embaralhe-os no campo. \r\nOs 2 cards selecionados do seu Deck são destruídos no final da Fase de Batalha e não podem permanecer no campo, exceto durante esta Fase de Batalha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81218874,'Ondulações de Infestação','Pague 500 PV para escolher 1 monstro "Hordeum Ferro" de Nível 4 ou menos no seu Cemitério; Invoque-o por Invocação-Especial do Cemitério.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81223446,'Fusão Necro','Invoque por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional, ao banir do seu Cemitério, com a face para baixo, as Matérias de Fusão mencionadas nele, mas ele não pode atacar neste turno.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81231742,'Barreira Mágica da Feitiçaria',replace(replace('Todos os monstros que você controla ganham 300 de ATK, apenas durante o seu turno. \r\nTodos os monstros que você controla ganham 300 de DEF, apenas durante o turno do seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81237046,'Eneanave - Archa.TAIL',replace(replace('Escala de Pêndulo = 0\r\n[ Efeito de Pêndulo ]\r\nSempre que um ou mais monstros forem virados com a face para cima, coloque 1 Marcador de E.N. neste card. \r\nNo final da Fase de Batalha, se você tiver um card "Eneanave" na sua outra Zona de Pêndulo: você pode escolher 1 monstro que seu oponente controla com ATK menor que o deste card; destrua-o.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nDepois que este card foi virado com a face para cima, enquanto ele estiver na Zona de Monstros, sempre que um ou mais monstros forem enviados para o Cemitério do seu oponente, ele sofre 900 de dano. \r\nQuando seu oponente ativar um card ou efeito que destruiria um ou mais cards no campo (Efeito Rápido): você pode colocar este card que estiver com a face para baixo, com a face para cima em Posição de Defesa; Magias "Eneanave" e monstros que você controla não podem ser destruídos por efeitos de card pelo resto deste turno. \r\nVocê pode revelar este card na sua mão; Invoque por Invocação-Especial 1 monstro da sua mão com a face para baixo em Posição de Defesa. \r\nVocê não pode Invocar por Invocação-Especial no turno em que ativar este efeito, exceto com a face para baixo em Posição de Defesa.','\r',char(13)),'\n',char(10)),'Destruir','Invocação Especial','Conceder proteção','Já foi virado','','','','','','','','','','','','');
INSERT INTO texts VALUES(81254059,'Lombriga Rainha',replace(replace('Este card pode ser Invocado por Invocação-Tributo com a face para cima em Posição de Ataque ao oferecer como Tributo 1 monstro "Lombriga" do Tipo Réptil. \r\nUma vez por turno, você pode oferecer como Tributo 1 monstro "Lombriga" do Tipo Réptil para Invocar por Invocação-Especial 1 monstro "Lombriga" do Tipo Réptil do seu Deck com um Nível menor ou igual ao do monstro oferecido como Tributo.','\r',char(13)),'\n',char(10)),'Ofereça 1 monstro como Tributo para Invocar por Tributo','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81260679,'Ohime, a Mikanko Manifesta',replace(replace('Você pode Invocar este card por Invocação-Ritual com "Kagura Mikanko". \r\nNão pode ser destruído em batalha e, além disso, seu oponente sofre qualquer dano de batalha que você teria sofrido das batalhas envolvendo este card. \r\nVocê só pode usar cada um dos seguintes efeitos de "Ohime, a Mikanko Manifesta" uma vez por turno. \r\nVocê pode revelar este card na sua mão; adicione 1 card "Mikanko" do seu Deck à sua mão, exceto "Ohime, a Mikanko Manifesta" e, depois, descarte 1 card. \r\n(Efeito Rápido): você pode escolher 1 Magia de Equipamento no seu Cemitério; equipe-a em 1 monstro apropriado no campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81260680,'Ohime, a Mikanko Manifesta',replace(replace('Você pode Invocar este card por Invocação-Ritual com "Kagura Mikanko". \r\nNão pode ser destruído em batalha e, além disso, seu oponente sofre qualquer dano de batalha que você teria sofrido das batalhas envolvendo este card. \r\nVocê só pode usar cada um dos seguintes efeitos de "Ohime, a Mikanko Manifesta" uma vez por turno. \r\nVocê pode revelar este card na sua mão; adicione 1 card "Mikanko" do seu Deck à sua mão, exceto "Ohime, a Mikanko Manifesta" e, depois, descarte 1 card. \r\n(Efeito Rápido): você pode escolher 1 Magia de Equipamento no seu Cemitério; equipe-a em 1 monstro apropriado no campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81263643,'Mistruque Huldra',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode descartar 1 card; aplique o seguinte efeito, dependendo do tipo de card descartado.\r\n● Monstro: Adicione 1 Armadilha do seu Cemitério à sua mão.\r\n● Magia: Adicione 1 monstro do seu Cemitério à sua mão.\r\n● Armadilha: Adicione 1 Magia do seu Cemitério à sua mão.	\r\nVocê só pode usar este efeito de "Mistruque Huldra" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81269231,'Hidra do Mecanismo Antigo',replace(replace('No final da Etapa de Dano, quando este card que foi Invocado por Invocação-Tributo pelo Tributo de um monstro "Mecanismo Antigo" batalhar um monstro do oponente, mas o monstro do oponente não foi destruído em batalha: você pode banir o monstro do oponente. \r\nSe este card foi Invocado por Invocação-Tributo pelo Tributo de um monstro "Dispositivo", ele pode atacar todos os monstros que seu oponente controla, uma vez cada. \r\nSe um monstro "Mecanismo Antigo" que você controla atacar, seu oponente não pode ativar Cards de Magia/Armadilha e efeitos de monstro até o final da Etapa de Dano.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81275020,'Velocidaroide Terrorpião',replace(replace('Se você não controlar nenhum monstro, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nQuando este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 monstro "Velocidaroide" do seu Deck à sua mão, exceto "Velocidaroide Terrorpião". \r\nVocê só pode usar este efeito de "Velocidaroide Terrorpião" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81275309,'General Raiho da Barreira de Gelo','Quando um efeito de monstro do seu oponente for ativado no campo e resolver, ele deve descartar 1 card ou o efeito é negado (ele seleciona).','Descartar 1 card?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81278754,'Sapo Flip-Flop',replace(replace('Uma vez por turno, você pode virar este card com a face para baixo em Posição de Defesa. \r\nQuando este card for virado com a face para cima, você pode devolver monstros que seu oponente controla para a mão de seu dono até o número de monstros "Sapo" com a face para cima que você controla.','\r',char(13)),'\n',char(10)),'Mudar para Posição de Defesa com a face para baixo','Retornar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81306186,'Renovação do Mundo',replace(replace('Quando este card for ativado: bana 1 Monstro de Ritual do seu Deck. \r\nVocê pode enviar este card para o Cemitério e, depois, ativar 1 desses efeitos;\r\n● Ofereça como Tributo 1 monstro da sua mão ou do campo, ou embaralhe no Deck 1 Monstro de Ritual do seu Cemitério, cujo Nível seja igual ou exceda o Nível do monstro banido pelo efeito deste card e, depois, Invoque esse monstro por Invocação-Ritual.\r\n● Adicione à sua mão o monstro banido pelo efeito deste card.	\r\nVocê só pode usar 1 efeito de "Renovação do Mundo" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Ritual usando monstros banidos','Adicionar à sua mão um monstro banido','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81306586,'Pinguim Pesadelo',replace(replace('Quando este card é virado com a face para cima, devolva 1 card no Campo do seu adversário para a mão do seu dono. \r\nEnquanto este card permanecer no Campo com a face para cima, aumente o ATK de todos os monstros da ÁGUA no seu Campo em 200 pontos.','\r',char(13)),'\n',char(10)),'Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81321206,'Ursártico Mikbilis',replace(replace('Durante a Fase Principal (Efeito Rápido): você pode oferecer como Tributo 1 outro monstro de Nível 7 ou mais da sua mão; Invoque este card por Invocação-Especial da sua mão e, além disso, você não pode Invocar por Invocação-Especial pelo resto deste turno, exceto monstros com um Nível. \r\nSe este card for Invocado por Invocação-Especial: você pode Invocar por Invocação-Especial 1 monstro "Ursártico(a)" da sua mão, exceto "Ursártico Mikbilis". \r\nVocê só pode usar cada efeito de "Ursártico Mikbilis" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81325903,'Mago Amazoness','Escolha 1 monstro "Amazoness" que você controla e 1 monstro com a face para cima que seu oponente controla; troque o ATK original desses alvos até o final deste turno.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81330115,'Número 30: Gólem de Ácido da Destruição',replace(replace('2 monstros de Nível 3	\r\nDurante sua Fase de Apoio: desassocie 1 Matéria Xyz deste card ou sofra 2000 de dano. \r\nVocê não pode Invocar monstros por Invocação-Especial. \r\nEnquanto este card não tiver Matérias Xyz, ele não pode atacar.','\r',char(13)),'\n',char(10)),'Desassociar Matéria','Desassociar 1 Matéria Xyz?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81332143,'Amizade Yu-Jo',replace(replace('Ofereça um aperto de mão ao oponente. \r\nSe o aperto de mão for aceito, os PV de cada duelista se tornam metade dos PV combinados de ambos os duelistas. \r\nSe você tiver o card "Unidade" em sua mão e mostrá-lo ao oponente, ele deve aceitar o aperto de mão.','\r',char(13)),'\n',char(10)),'Aceitar aperto de mão','Recusar aperto de mão','Revelar "Unidade" ao seu oponente?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81336148,'Mestre das Espadas',replace(replace('Se um monstro do Tipo Guerreiro que você controla atacar um monstro do oponente, e o monstro do oponente não for destruído em batalha, no final da Etapa de Dano, você pode Invocar este card por Invocação-Especial da sua mão. \r\nDurante a batalha entre este card atacante e um monstro em Posição de Defesa cuja DEF seja menor que o ATK deste card, cause a diferença como Dano de Batalha ao seu oponente.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81344070,'Cabelos Dourados, a Mais Jovem Saquepatrollha',replace(replace('Você pode enviar 1 outro Card de Monstro "Saquepatrollha" da sua mão ou do campo com a face para cima para o Cemitério; Invoque este card por Invocação-Especial da sua mão. \r\nSe este card estiver no seu Cemitério: você pode descartar 1 card; Invoque este card por Invocação-Especial, mas você não pode Invocar por Invocação-Especial pelo resto deste turno, exceto monstros "Saquepatrollha". \r\nVocê só pode usar cada efeito de "Cabelos Dourados, a Mais Jovem Saquepatrollha" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81344637,'Basilius, o Familiar do Olho Maligno',replace(replace('Se você controlar um monstro "Olho Maligno", você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Basilius, o Familiar do Olho Maligno" por Invocação-Especial uma vez por turno desta forma. \r\nDurante sua Fase Principal: você pode enviar 1 Magia/Armadilha "Olho Maligno" do seu Deck para o Cemitério. \r\nVocê só pode usar este efeito de "Basilius, o Familiar do Olho Maligno" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81354330,'Invocadora do Pardal Vermelho','Quando este card que você controla for destruído em batalha por um monstro atacante do oponente e enviado para o seu Cemitério: você pode Invocar por Invocação-Especial 1 monstro do Tipo Guerreiro com 1500 ou menos de ATK do seu Deck em Posição de Ataque.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81380218,'Coro do Santuário','Aumente em 500 a DEF de todos os monstros em Posição de Defesa.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81383947,'Mágico Branco Pikeru','Durante sua Fase de Apoio: ganhe 400 PV para cada monstro que você controla.','Ganhar PV','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81384993,'Divisão Perniciosa','Escolha 1 monstro "Pernicioso(a)" no seu Cemitério; Invoque-o por Invocação-Especial, ignorando suas condições de Invocação, mas seus efeitos são negados e, além disso, bana-o durante a Fase Final.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81385346,'Destruição com os Pés','Se você controlar um monstro Dragão: escolha 1 Magia/Armadilha no campo; destrua o alvo e, se isso acontecer, cause 500 de dano ao seu controlador.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81386177,'Habitante das Profundezas','Esta é uma criatura marinha cuja ira outros monstros temem enfrentar.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81418467,'Dragão Imperial Primita',replace(replace('Não pode ser Invocado por Invocação-Normal, exceto ao oferecer como Tributo 1 Monstro Normal (mas pode ser Baixado Normalmente). \r\nDurante a Fase Principal do seu oponente (Efeito Rápido): você pode revelar este card na sua mão; imediatamente depois que este efeito resolver, Invoque por Invocação-Normal 1 monstro "Primita". \r\nVocê só pode usar este efeito de "Dragão Imperial Primita" uma vez por turno. \r\nSe este card for Invocado por Invocação-Tributo: você pode aplicar esses efeitos em sequência.\r\n● Negue os efeitos de todos os monstros com a face para cima que seu oponente controla atualmente.\r\n● Bana todos os monstros que seu oponente controla com o mesmo Tipo ou Atributo que o de um Monstro Normal no seu Cemitério.','\r',char(13)),'\n',char(10)),'Invocação Normal','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81426505,'Ataque dos Seis - Impacto Triplo',replace(replace('Se você controlar 3 ou mais monstros "Seis Samurai" com a face para cima, você pode ativar 1 desses efeitos:\r\n● Destrua todos os monstros com a face para cima que seu oponente controla.\r\n● Destrua todos os Cards de Magia/Armadilha com a face para cima que seu oponente controla.\r\n● Destrua todos os Cards de Magia/Armadilha Baixados que seu oponente controla.','\r',char(13)),'\n',char(10)),'Destrua todos os monstros com a face para cima que seu oponente controla','Destrua todos os Cards de Magia/Armadilha com a face para cima que seu oponente controla','Destrua todos os Cards de Magia/Armadilha Baixados que seu oponente controla','Ativar 1 efeito','','','','','','','','','','','','');
INSERT INTO texts VALUES(81434470,'Água-Viva de Mil Olhos',replace(replace('Este card não pode ser Invocado por Invocação-Normal ou Baixado. \r\nEste card não pode ser Invocado por Invocação-Especial, exceto ao oferecer como Tributo 1 "Guardador do Oceano". \r\nSeu oponente deve jogar com a mão dele revelada.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81439173,'Enterro Tolo','Envie 1 monstro do seu Deck para o Cemitério.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81439174,'Enterro Tolo','Envie 1 monstro do seu Deck para o Cemitério.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81439175,'Enterro Tolo','Envie 1 monstro do seu Deck para o Cemitério.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81443745,'Cerimônia de Selamento de Suiton','Uma vez por turno: você pode enviar 1 monstro de ÁGUA da sua mão para o Cemitério e, depois, escolha 1 card no Cemitério do seu oponente; bana o alvo.','Banir','Usar o efeito de "Cerimônia de Selamento de Suiton" agora?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81470373,'Asanegra - Simum, o Vento Venenoso',replace(replace('Se você não controlar nenhum monstro e tiver este card na sua mão: você pode banir 1 outro monstro "Asanegra" da sua mão; coloque 1 "Redemoinho Negro" do seu Deck, com a face para cima na sua Zona de Magias & Armadilhas e, depois, ou envie este card para o Cemitério ou, imediatamente depois que este efeito resolver, Invoque-o por Invocação-Normal sem oferecer Tributo. \r\nVocê não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto monstros de TREVAS. \r\nVocê só pode usar este efeito de "Asanegra - Simum, o Vento Venenoso" uma vez por turno. \r\nDurante a Fase Final, envie para o Cemitério o "Redemoinho Negro" colocado por este efeito e, se isso acontecer, sofra 1000 de dano.','\r',char(13)),'\n',char(10)),'','Invocar?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81471108,'ZW - Arauto do Tornado',replace(replace('Você pode escolher 1 monstro "Utopia" que você controla; equipe este monstro da sua mão ou do campo com a face para cima ao alvo. \r\nEle ganha 1300 de ATK. \r\nEnquanto este card estiver equipado a um monstro, seu oponente não pode escolher esse monstro como alvo de efeitos de card. \r\nSe um monstro equipado com este card seria destruído em batalha, em vez disso, destrua este card. \r\nVocê só pode controlar 1 "ZW - Arauto do Tornado" com a face para cima.','\r',char(13)),'\n',char(10)),'Equipar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81476402,'Perverso Dragão-Serpente da Noite',replace(replace('Você pode oferecer como Tributo 1 monstro de TREVAS da sua mão ou do campo; Invoque este card por Invocação-Especial da sua mão. \r\nVocê só pode usar este efeito de "Perverso Dragão-Serpente da Noite" uma vez por turno. \r\nQuando este card for destruído em batalha: você pode escolher 1 monstro que seu oponente controla; envie-o para o Cemitério e, depois, você pode Invocar este card por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Invocação Especial','Enviar para o Cemitério','Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81480460,'Dragão Revólver','Uma vez por turno: você pode escolher 1 monstro que seu oponente controla; lance uma moeda 3 vezes e destrua-o se pelo menos 2 resultados forem cara.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81481818,'Fofanimal de Retalhos',replace(replace('Este card também é considerado como um monstro "Peladura" enquanto estiver com a face para cima no campo. \r\nEste card no campo pode ser usado como um substituto para qualquer 1 Matéria de Fusão cujo nome esteja especificamente listado em um Monstro de Fusão "Peladura", mas a(s) outra(s) \r\nMatéria(s) de Fusão deve(m) estar correta(s).','\r',char(13)),'\n',char(10)),'Matéria de substituição','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81489939,'Nênia de Estígia','Reduza em 1 o Nível de todos os monstros que seu oponente controla.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81492226,'Jarro Antigo','Um jarro muito frágil que contém algo muito antigo e perigoso.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81497285,'Senhora Labrinto do Castelo Prateado',replace(replace('Enquanto você controlar um card Baixado, seu oponente não pode escolher este card como alvo de efeitos de card e, além disso, ele não pode ser destruído pelos efeitos de card do seu oponente. \r\nVocê só pode usar cada um dos seguintes efeitos de "Senhora Labrinto do Castelo Prateado" uma vez por turno. \r\nSe um card ou efeito "Labrinto" ou um Card de Armadilha Normal foi ativado neste turno, exceto "Senhora Labrinto do Castelo Prateado" (Efeito Rápido): você pode Invocar este card por Invocação-Especial da sua mão em Posição de Defesa. \r\nQuando um Card de Armadilha Normal for ativado (Efeito Rápido): você pode Baixar 1 Armadilha Normal com um nome diferente diretamente do seu Deck.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81497286,'Senhora Labrinto do Castelo Prateado',replace(replace('Enquanto você controlar um card Baixado, seu oponente não pode escolher este card como alvo de efeitos de card e, além disso, ele não pode ser destruído pelos efeitos de card do seu oponente. \r\nVocê só pode usar cada um dos seguintes efeitos de "Senhora Labrinto do Castelo Prateado" uma vez por turno. \r\nSe um card ou efeito "Labrinto" ou um Card de Armadilha Normal foi ativado neste turno, exceto "Senhora Labrinto do Castelo Prateado" (Efeito Rápido): você pode Invocar este card por Invocação-Especial da sua mão em Posição de Defesa. \r\nQuando um Card de Armadilha Normal for ativado (Efeito Rápido): você pode Baixar 1 Armadilha Normal com um nome diferente diretamente do seu Deck.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81510157,'Rouba Almas','Escolha 1 monstro com a face para cima que seu oponente controla; destrua o alvo e, depois, seu oponente ganha 1000 PV.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81519836,'Vernasílfide das Mudas de Neblina',replace(replace('Todos os monstros no campo perdem 600 de ATK, exceto monstros "Vernasílfide". \r\nVocê pode descartar este card e 1 monstro ou 1 card "Vernasílfide"; você não pode ativar efeitos de monstros que não sejam de TERRA pelo resto deste turno e, além disso, adicione 1 monstro Fada de TERRA do seu Deck à sua mão, exceto "Vernasílfide das Mudas de Neblina" e, depois, você pode Invocar por Invocação-Especial 1 monstro de TERRA do seu Cemitério. \r\nVocê só pode usar este efeito de "Vernasílfide das Mudas de Neblina" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial do Cemitério?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81522098,'Dragão Mimicarniçal',replace(replace('VIRE: Se for a Fase Principal: aplique esses efeitos em sequência.\r\n● Destrua todos os monstros com a face para cima que você controla, exceto monstros "Mimicarniçal".\r\n● Conceda o controle deste card ao seu oponente.	\r\nDurante sua Fase Principal: você pode Invocar este card por Invocação-Especial da sua mão no campo do seu oponente com a face para baixo em Posição de Defesa. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 Magia/Armadilha "Mimicarniçal" do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "Dragão Mimicarniçal" uma vez por turno.','\r',char(13)),'\n',char(10)),'Destruir e transferir o controle','Invocação Especial','Adicionar à mão','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81524756,'Crusadia Maximus',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) em Posição de Defesa em uma zona sua para a qual um Monstro Link apontar. \r\nVocê só pode Invocar "Crusadia Maximus" por Invocação-Especial uma vez por turno desta forma. \r\nVocê pode escolher 1 Monstro Link "Crusadia" que você controla; neste turno, se ele batalhar um monstro do oponente, qualquer dano de batalha que ele causar ao seu oponente é dobrado e, além disso, outros monstros que você controla não podem atacar. \r\nVocê só pode usar este efeito de "Crusadia Maximus" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81524977,'Canhão de Sementes',replace(replace('Cada vez que um ou mais monstros do Tipo Planta forem Invocados, coloque 1 Marcador de Planta neste card (máx. 5). \r\nVocê pode enviar este card ao Cemitério para causar 500 de dano ao seu oponente para cada Marcador de Planta nele.','\r',char(13)),'\n',char(10)),'Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81549048,'Rivalidade de Ryu-Ge',replace(replace('Invoque por Invocação-Especial 1 monstro "Ryu-Ge" da sua mão, do Deck ou do Cemitério, mas devolva-o para a mão durante a Fase Final. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 Magia Contínua "Ryu-Ge" no seu banimento, Cemitério ou campo; coloque-a no fundo do Deck e, depois, compre 1 card. \r\nVocê só pode usar cada efeito de "Rivalidade de Ryu-Ge" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Recuperar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81555617,'Ad Libitum de Despia',replace(replace('Durante sua Fase Principal: até o final do turno do oponente, você pode fazer com que todos os monstros atualmente no campo ganhem ATK igual ao seu próprio Nível x 100. \r\nSe este card na sua mão ou no campo for usado como Matéria de Fusão e enviado para o Cemitério ou banido: você pode escolher 1 dos seus monstros "Despia" ou Monstros de Fusão de Nível 8 ou mais, que estiverem banidos ou no seu Cemitério, exceto "Ad Libitum de Despia"; Invoque-o por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Ad Libitum de Despia" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81558967,'Valquíria-Vierte',replace(replace('Durante sua Fase Principal: você pode escavar cards do topo do seu Deck igual ao número de outros monstros "Valquíria-" que você controla e, se isso acontecer, adicione à sua mão 1 Magia/Armadilha Normal escavada e, além disso, envie os cards restantes para o Cemitério. \r\nCaso contrário, embaralhe todos os cards escavados no Deck. \r\nQuando este card for destruído em batalha e enviado para o Cemitério: você pode Invocar por Invocação-Especial 1 monstro "Valquíria-" do seu Deck. \r\nVocê só pode usar cada efeito de "Valquíria-Vierte" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81560239,'Ritual de Mitsurugi',replace(replace('Este card pode ser usado para Invocar por Invocação-Ritual qualquer Monstro de Ritual Réptil. \r\nAtive 1 desses efeitos (mas você só pode usar cada efeito de "Ritual de Mitsurugi" uma vez por turno);\r\n● Invoque por Invocação-Ritual 1 Monstro de Ritual Réptil do seu Deck, ao oferecer como Tributo monstros Réptil da sua mão ou do campo cuja soma dos Níveis seja igual ao Nível do Monstro de Ritual.\r\n● Invoque por Invocação-Ritual 1 Monstro de Ritual Réptil da sua mão, ao oferecer como Tributo até 2 monstros Réptil da sua mão, do Deck ou do campo, cuja soma dos Níveis seja igual ao Nível do Monstro de Ritual.','\r',char(13)),'\n',char(10)),'Ativar','Invocar por Invocação Ritual do Deck','Invocar por Invocação Ritual da mão','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81563416,'Fada da Fonte','Esta fada protege uma fonte de qualquer um que procure turvar suas águas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81566151,'Neos da Labareda, o HERÓI do Elemento',replace(replace('"Neos, o HERÓI do Elemento" + "Escaravelho de Chamas Neoespacial"	\r\nDeve primeiro ser Invocado por Invocação-Especial (do seu Deck Adicional) ao embaralhar os cards acima que você controla no Deck. \r\n(Você não usa "Polimerização"). \r\nEste card ganha 400 de ATK para cada Card de Magia/Armadilha no campo. \r\nDurante a Fase Final: Embaralhe este card no Deck Adicional.','\r',char(13)),'\n',char(10)),'Retornar ao Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81570454,'Infernobre Cavaleiro - Roland',replace(replace('(Efeito Rápido): você pode escolher 1 monstro com a face para cima que você controla; equipe este card da sua mão ao alvo como uma Magia de Equipamento que concede 500 de ATK a esse card. \r\nDurante a Fase Final, se este card estiver no Cemitério porque foi enviado para lá neste turno: você pode adicionar 1 monstro Guerreiro de FOGO, exceto "Infernobre Cavaleiro - Roland", ou 1 Magia de Equipamento do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "Infernobre Cavaleiro - Roland" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81571633,'D/D Ogro Orgulhoso',replace(replace('Escala de Pêndulo = 8\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno: você pode pagar 500 PV e, depois, escolher 1 monstro "D/D" que você controla; ele ganha 500 de ATK (mesmo que este card deixe o campo). \r\nA não ser que você tenha um card "D/D" na sua outra Zona de Pêndulo, a Escala de Pêndulo deste card se torna 5.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nQuando este card for Invocado por Invocação-Normal: você pode Invocar por Invocação-Especial 1 Monstro Pêndulo de TREVAS com a face para cima do seu Deck Adicional, mas ele tem seus efeitos negados e, além disso, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros "D/D".','\r',char(13)),'\n',char(10)),'Alterar ATK/DEF','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81587028,'Caixa de Amigos',replace(replace('Se este card for destruído e enviado para o Cemitério: você pode Invocar por Invocação-Especial do seu Deck, 2 Monstros Normais com 0 de ATK ou DEF e nomes diferentes em Posição de Defesa, mas eles não podem ser usados como Matéria Sincro e, além disso, eles são destruídos durante sua próxima Fase Final. \r\nVocê só pode usar este efeito de "Caixa de Amigos" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81599449,'Criaquímica Carbo Caranguejo',replace(replace('Este card é considerado um Monstro Normal enquanto estiver com a face para cima no campo ou no Cemitério. \r\nEnquanto este card for um Monstro Normal no campo, você pode Invocá-lo por Invocação-Normal para fazer com que ele se torne um Monstro de Efeito com este efeito.\r\n● Durante sua Fase Principal: você pode enviar 1 monstro Gêmeos do seu Deck para o Cemitério e, depois, adicionar 1 monstro Gêmeos do seu Deck à sua mão.	\r\nVocê só pode usar este efeito de "Criaquímica Carbo Caranguejo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81601517,'Contador de Gêmeos','Mude 1 monstro Gêmeos com a face para cima que você controla para Posição de Defesa com a face para baixo e negue a ativação de um Card de Magia do oponente e destrua-o.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81612598,'Metalmorfose Adamante','1 monstro "Metalmorfose" + 1 monstro com 2500 ou menos de ATK','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81613061,'Médium Caverguerra',replace(replace('Enquanto seu oponente controlar um monstro Invocado por Invocação-Especial e você controlar um monstro "Caverguerra" de Nível 7 ou mais, durante a Fase Principal 1, nenhum duelista pode ativar os efeitos de monstros no campo. \r\nDurante sua Fase Principal: você pode Baixar 1 Magia/Armadilha "Caverguerra" diretamente do seu Deck, exceto "Médium Caverguerra" e, além disso, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros Guerreiro. \r\nVocê só pode usar este efeito de "Médium Caverguerra" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81615450,'Ramificações Reptilianas',replace(replace('Envie 1 card da sua mão para o Cemitério e ative 2 desses efeitos, em sequência;\r\n● Adicione 1 monstro "Reptiliano(a)" do seu Deck à sua mão.\r\n● Adicione 1 Magia/Armadilha "Reptiliano(a)" do seu Deck à sua mão, exceto "Ramificações Reptilianas".\r\n● Mude o ATK de 1 monstro que seu oponente controla para 0.	\r\nVocê só pode ativar 1 "Ramificações Reptilianas" por turno.','\r',char(13)),'\n',char(10)),'Ativar o efeito escolhido','Adicionar à mão 1 monstro "Reptiliano(a)"','Procurar 1 Magia/Armadilha "Reptiliano(a)"','O ATK do monstro do seu oponente se torna 0','','','','','','','','','','','','');
INSERT INTO texts VALUES(81616639,'Zumbina','Se este card em posse do seu dono for destruído por um card do oponente: você pode escolher 1 monstro de Nível 4 ou menos no seu Cemitério, exceto "Zumbina"; Invoque-o por Invocação-Especial.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81618817,'Senhor de Zêmia','Uma entidade perversa que manipula os inimigos em direção a um caminho de destruição.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81650695,'Patrono do Poder DoomZ',replace(replace('Você não pode Invocar por Invocação-Especial do Deck Adicional, exceto Monstros Xyz. \r\nVocê só pode usar cada um dos seguintes efeitos de "Patrono do Poder DoomZ" uma vez por turno. \r\nVocê pode escolher 1 outro Monstro de Efeito que você controla; Invoque por Invocação-Especial do seu Deck Adicional, 1 Monstro Xyz "DoomZ" ou "Júpiter, o Patrono do Poder da Destruição", com a mesma Classe que o Nível desse monstro que você controla, ao usar esse monstro como matéria (isso é considerado uma Invocação-Xyz) e, se isso acontecer, equipe este card que você controla a ele como uma Magia de Equipamento. \r\nSe este card for destruído: você pode adicionar 1 card "DoomZ" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Invocação Xyz','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81661951,'Militum Dragunidade','Uma vez por turno: você pode escolher 1 card "Dragunidade" na sua Zona de Magias & Armadilhas; Invoque-o por Invocação-Especial.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81665333,'Bater em Retirada!','Devolva todos os monstros que você controla para a mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81670445,'Ladrão do Tempo Hacker',replace(replace('Durante o turno em que são Invocados por Invocação-Especial, os Monstros Xyz que você controla não podem ser destruídos pelos efeitos de card do seu oponente e, além disso, seu oponente não pode escolhê-los como alvo de efeitos de card. \r\nVocê pode escolher 1 Monstro Xyz com a face para cima que você controla; até o final deste turno, ele ganha 300 de ATK para cada matéria atualmente associada a ele e, se isso acontecer, e ele também tiver uma matéria da qual seu oponente seja dono, ele pode atacar diretamente neste turno (mesmo que este card deixe o campo). \r\nVocê só pode usar este efeito de "Ladrão do Tempo Hacker" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81674782,'Fissura Dimensional','Qualquer monstro enviado para o Cemitério, em vez disso, é banido.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81677154,'Tatsunootoshigo Mementotlan',replace(replace('Se você não controlar nenhum monstro com a face para cima, exceto monstros "Memento": você pode Invocar este card por Invocação-Especial da sua mão. \r\nDurante sua Fase Principal: você pode destruir 1 monstro "Memento" que você controla e enviar qualquer número de monstros "Memento" (com nomes diferentes) do seu Deck para o Cemitério, cuja soma dos Níveis seja igual ou menor que o Nível original do monstro destruído. \r\nVocê só pode usar cada efeito de "Tatsunootoshigo Mementotlan" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81684048,'Pumpking, o Rei dos Fantasmas do Túmulo',replace(replace('Você pode revelar este card na sua mão; Baixe 1 "Chamado dos Assombrados" do seu Deck ou Cemitério e, se isso acontecer, descarte 1 card. \r\nEsse card Baixado pode ser ativado neste turno. \r\nSe este card for Invocado por Invocação-Especial: você pode Invocar por Invocação-Especial 1 monstro Zumbi de Nível 6 do seu Deck, exceto com 1950 de ATK e, além disso, você não pode Invocar por Invocação-Especial da mão ou do Cemitério pelo resto deste turno, exceto monstros Zumbi. \r\nVocê só pode usar cada efeito de "Pumpking, o Rei dos Fantasmas do Túmulo" uma vez por turno.','\r',char(13)),'\n',char(10)),'Baixar','Invocação Especial','Ativar aplicando o efeito de "Pumpking, o Rei dos Fantasmas do Túmulo".','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81686058,'Bruxa Maléfica','Este monstro varre seus inimigos com súbitas rajadas de vento.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81696879,'Centur-Ião Chimerea',replace(replace('Quando seu oponente ativar um efeito de monstro como um Elo de Corrente 2 ou mais (Efeito Rápido): você pode fazer com que o efeito ativado se torne "Seu oponente coloca 1 monstro "Centur-Ião" do campo com a face para cima ou Cemitério dele na Zona de Magias & Armadilhas dele como uma Armadilha Contínua com a face para cima" e, além disso, você não pode Invocar "Centur-Ião Chimerea" por Invocação-Especial pelo resto deste turno. \r\nDurante a Fase Principal, se este card for uma Armadilha Contínua: você pode Invocar este card por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Centur-Ião Chimerea" uma vez por turno.','\r',char(13)),'\n',char(10)),'Efeito de alterar','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81743801,'Poderoso Dino Rei Rex',replace(replace('Se este card atacante destruir um monstro do oponente em batalha: ele pode realizar um segundo ataque durante esta Fase de Batalha. \r\nUma vez por turno, se você controlar este card que não foi Invocado neste turno: você pode escolher até 2 monstros que seu oponente controla; destrua-os.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81752019,'Flor Cardian Pinho',replace(replace('Se este card for Invocado por Invocação-Normal: compre 1 card, mostre-o e, depois, envie-o para o Cemitério a não ser que ele seja um monstro "Flor Cardian". \r\nVocê só pode usar este efeito de "Flor Cardian Pinho" uma vez por turno. \r\nSe este card for destruído em batalha e enviado para o Cemitério, ou se este card em sua posse for destruído por um efeito de card do seu oponente e enviado para o seu Cemitério: você pode comprar 1 card.','\r',char(13)),'\n',char(10)),'Compre 1 card e revele a ambos os jogadores','Compre 1 card(s)','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81755371,'Efígie das Trevas','Se você Invocar por Invocação-Tributo um Monstro Normal de TREVAS, você pode considerar este 1 monstro como 2 Tributos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81756619,'Morganita Canta-Desalento',replace(replace('Pelo resto deste Duelo, aplique os seguintes efeitos.\r\n● Você não pode ativar efeitos de monstro na mão.\r\n● Monstros que você controla podem realizar até 2 ataques contra monstros durante cada Fase de Batalha.\r\n● Se um monstro seu batalhar um monstro do oponente, qualquer dano de batalha que ele causar ao seu oponente é dobrado.	\r\nVocê pode banir este card do seu Cemitério; adicione 1 card "Morganita" do seu Deck à sua mão e, depois, coloque 1 card da sua mão no fundo do Deck.','\r',char(13)),'\n',char(10)),'Ativar','Adicionar à mão','O efeito de "Morganita Canta-Desalento" está sendo aplicado.','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81756897,'Ritual de Zera',replace(replace('Este card é usado na Invocação-Ritual de "Zera, o Mante". \r\nVocê também deve oferecer como Tributo monstros da sua mão ou do campo cuja soma dos Níveis seja igual a 8 ou mais.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81758313,'Dragão Myriaday',replace(replace('Uma vez por turno, durante a Fase Final: você pode pagar 100 PV; coloque 1 Marcador de Miríade neste card.\r\nUma vez por turno, durante sua Fase Principal: você pode colocar 1 Marcador de Miríade neste card para cada 1000 pontos de diferente entre seu PV e do seu oponente.\r\nGanha 10,000 de ATK/DEF enquanto ele tiver 10 ou mais Marcadores de Miríade.\r\nSe este card seria destruído por batalha ou efeito, em vez disso remova 1 Marcador de Miríade dele.','\r',char(13)),'\n',char(10)),'Colocar um marcador','Colocar um marcador','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81759748,'Aranha Sombria','Uma vez por turno, você pode aumentar o Nível de 1 monstro do Tipo Inseto com a face para cima que você controla em 2 até a Fase Final.','Aumentar o Nível','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81767888,'Espada do Marcado',replace(replace('Bana qualquer número de Magias/Armadilhas "Marcado" do seu Cemitério; Invoque por Invocação-Especial esse número de "Ficha de Lâmina Gélida" (Dragão/TREVAS/Nível 8/ATK 2500/DEF 2000). \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 dos seus monstros banidos que seja "Caído de Arbaz" ou que o mencione; adicione esse monstro à sua mão. \r\nVocê só pode usar 1 efeito de "Espada do Marcado" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81767889,'Ficha de Lâmina Gélida','Invocado por Especial com o efeito "Espada do Marcado".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81769387,'Utensilhor Ventileão',replace(replace('1 monstro "Utensilhor"	\r\nNão pode ser usado como Matéria Link no turno em que for Invocado por Invocação-Link. \r\nEste card pode atacar diretamente. \r\nUma vez por turno, durante o cálculo de dano, se um monstro seu batalhar um monstro do oponente, enquanto este card estiver co-linkado (Efeito Rápido): você pode transformar em 0 o ATK desse monstro do oponente, apenas durante esse cálculo de dano. \r\nUma vez por turno, durante o cálculo de dano, se este monstro que não estiver co-linkado batalhar um monstro do oponente (Efeito Rápido): você pode transformar em 0 o ATK desse monstro do oponente, apenas durante esse cálculo de dano.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81777047,'Faísca Reluzente','Aumente em 500 o ATK de todos os monstros de LUZ e diminua em 400 suas DEF.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81782101,'Ovo de Réptia',replace(replace('Não pode ser destruído em batalha. \r\nSe este card foi Invocado por Invocação-Normal, durante a Fase de Apoio do próximo turno do duelista que o Invocou: você pode oferecer este card como Tributo; Invoque por Invocação-Especial até 3 monstros Réptil e/ou Rocha de Nível 4 ou menos da sua mão e/ou do Deck, mas bana-os durante a Fase Final. \r\n(Se você Invocar 2 ou mais monstros por Invocação-Especial, eles devem ter o mesmo nome.) \r\nVocê só pode usar este efeito de "Ovo de Réptia" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81782376,'Escavar o Destino',replace(replace('Quando você sofrer dano de batalha: compre 1 card. \r\nSe este card sob o controle do seu dono for destruído por um efeito de card do oponente: você pode comprar cards igual ao número de "Escavar o Destino" no seu Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81788994,'Maldição da Prisão Sombria',replace(replace('Sempre que um ou mais monstros "Sombraneco" forem enviados para o Cemitério por um efeito de card, coloque 1 Marcador de Pedra Mágica neste card para cada monstro enviado. \r\nTodos os monstros que seu oponente controla perdem 100 de ATK para cada Marcador de Pedra Mágica neste card, apenas durante o turno do seu oponente. \r\nSempre que você for Invocar um Monstro de Fusão "Sombraneco" por Invocação-Fusão, você pode remover 3 Marcadores de Pedra Mágica deste card para usar 1 monstro apropriado com a face para cima que seu oponente controla como 1 das Matérias de Fusão.','\r',char(13)),'\n',char(10)),'Usar 1 monstro com a face para cima que seu oponente controla como Matéria de Fusão?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81791932,'Sibilar de Serpente',replace(replace('Ative apenas quando um monstro do Tipo Réptil que você controla for destruído. \r\nInvoque por Invocação-Especial 1 monstro do Tipo Réptil de Nível 4 ou menos do seu Deck.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81794107,'Canhão Lambda R.B.',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 monstro "R.B." no seu Cemitério, exceto "Canhão Lambda R.B."; adicione-o à sua mão. \r\nEnquanto este card estiver linkado a um Monstro Link "R.B.": você pode pagar 1200 PV; destrua este card e, se isso acontecer, olhe a mão do seu oponente e, depois, você pode Invocar por Invocação-Especial 1 monstro dela no campo dele, mas negue seus efeitos. \r\nVocê só pode usar cada efeito de "Canhão Lambda R.B." uma vez por turno.','\r',char(13)),'\n',char(10)),'Efeito de busca','Invocação Especial','Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81797573,'Alistamento de Anjoléquia',replace(replace('1 Regulador + 1 não-Regulador	\r\nVocê pode escolher 1 monstro do oponente na coluna adjacente a este card; bana-o e, depois, mude o controle deste card ao movê-lo para uma das Zonas de Monstros Principais do seu oponente nas colunas adjacentes a este card. \r\nSe o controle deste card com a face para cima mudar: devolva este card para o Deck Adicional e, depois, o dono deste card Invoca 1 monstro "Anjoléquia" por Invocação-Especial do Deck Adicional dele. \r\nVocê só pode usar cada efeito de "Alistamento de Anjoléquia" uma vez por turno.','\r',char(13)),'\n',char(10)),'Efeito de banimento','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81810441,'Cavaleirostelar Alfa',replace(replace('Só pode ser equipado a um monstro "Cavaleirost" que você controla. \r\nEle ganha 500 de ATK e DEF e, além disso, não pode ser afetado por efeitos de card do seu oponente. \r\nSe você controlar um monstro com a face para cima que não seja um monstro "Cavaleirost", destrua este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81816475,'Comedor de Sobreposição','Você pode banir este card do seu Cemitério; tome 1 Matéria Xyz de um monstro que seu oponente controla e associe-a a um Monstro Xyz que você controla como Matéria Xyz.','Tomar como matéria','Escolha um Monstro Xyz','Escolha a(s) Matéria(s) a transferir','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81820689,'O Espião Inexperiente','Escolha e veja 1 card na mão do seu adversário.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81823360,'Megalosmagador X','Com suas mandíbulas gigantes e uma armadura que abafa o som, a fosforescência deste predador primal é o único perdão que encontraram suas presas primitivas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81825063,'General Wayne da Barreira de Gelo',replace(replace('Magias e Armadilhas enviadas do campo para o Cemitério do seu oponente, em vez disso, são banidas. \r\nVocê só pode usar cada um dos seguintes efeitos de "General Wayne da Barreira de Gelo" uma vez por turno. \r\nSe seu oponente controlar um monstro e você controlar um monstro "Barreira de Gelo": você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 Magia/Armadilha "Barreira de Gelo" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81843628,'Lombriga Agulha','VIRE: Descarte 5 cards do topo do Deck do seu adversário para o Cemitério.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81846453,'Marchador Marcial de Metal',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro: você pode escolher 1 Regulador no seu Cemitério; Invoque-o por Invocação-Especial em Posição de Defesa, mas negue seus efeitos. \r\nVocê só pode usar este efeito de "Marchador Marcial de Metal" uma vez por turno. \r\nUm Monstro Sincro que usou este card como matéria é considerado como um Regulador enquanto estiver com a face para cima no campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81846636,'Cavaleiro-Gema Lazuli','Se este card for enviado para o Cemitério por um efeito de card: você pode escolher 1 Monstro Normal no seu Cemitério; adicione-o à sua mão.','Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81863068,'Escoteiro das Sombras de Hiro',replace(replace('VIRE: Seu oponente compra 3 cards. \r\nOs dois duelistas olham os cards. \r\nSe houver qualquer Card de Magia entre eles, descarte todos esses Cards de Magia para o Cemitério.','\r',char(13)),'\n',char(10)),'Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81866673,'HERÓI do Destino - Arremetedor',replace(replace('Uma vez por turno: você pode oferecer 1 outro monstro como Tributo; este card ganha 1000 de ATK até o final deste turno. \r\nSe este card atacar, coloque-o em Posição de Defesa no final da Fase de Batalha. \r\nUma vez, enquanto este card estiver no seu Cemitério, quando você comprar um monstro durante sua Fase de Compra: você pode revelá-lo; Invoque-o por Invocação-Especial. \r\nEste card deve estar no Cemitério para ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Aumentar ATK','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81873903,'Evoltil Westlo','VIRE: Invoque por Invocação-Especial 1 monstro "Evolssauro" do seu Deck.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81878201,'Abis-ferrão Triaina',replace(replace('Invoque por Invocação-Especial 1 monstro "Atlante" ou "Sirena" da sua mão ou do Cemitério e, se isso acontecer, equipe-o com este card. \r\nSe o monstro equipado seria destruído em batalha ou por um efeito de card, em vez disso, você pode enviar este card para o Cemitério. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha até 3 dos seus monstros Peixe, Serpente Marinha e/ou Aqua que estiverem banidos ou no seu Cemitério; embaralhe-os no Deck. \r\nVocê só pode usar este efeito de "Abis-ferrão Triaina" uma vez por turno. \r\nVocê só pode ativar 1 "Abis-ferrão Triaina" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81881839,'Dupla Exposição',replace(replace('Você pode escolher 2 monstros de Nível 6 ou menos com o mesmo nome no campo; o Nível deles é dobrado. \r\nNo começo da Fase de Batalha: você pode escolher 1 monstro "Críptico(a)" que você controla; selecione 1 outro monstro com a face para cima no campo e o nome dele se torna o nome desse monstro "Críptico(a)" até a Fase Final. \r\nVocê só pode usar cada efeito de "Dupla Exposição" uma vez por turno.','\r',char(13)),'\n',char(10)),'Dobre seu Nível','Alterar o nome do card','Escolha seu monstro "Críptico(a)"','Escolha o monstro cujo nome será alterado','','','','','','','','','','','','');
INSERT INTO texts VALUES(81896370,'Joe, Homem-Pássaro Veloz','Se você Invocar este card por Invocação-Tributo ao oferecer como Tributo um monstro de VENTO, devolva todos os Cards de Magia e Armadilha no campo à mão de seus donos.','Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81896771,'Wattfaisão',replace(replace('Este card pode atacar diretamente. \r\nSe este card causar dano de batalha ao seu oponente em um ataque direto: escolha 1 monstro com a face para cima no campo; bana-o até a Fase Final deste turno.','\r',char(13)),'\n',char(10)),'Banir temporariamente','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81907872,'Espectro Fantardil',replace(replace('Não pode ser Invocado por Invocação-Normal, a não ser que você controle um monstro "Fantardil". \r\nUma vez por turno: você pode colocar este card com a face para baixo em Posição de Defesa. \r\nQuando um monstro "Fantardil" for destruído por um efeito de card do oponente, ou em batalha com um monstro atacante dele, e enviado para o seu Cemitério: você pode Invocar este card por Invocação-Especial da sua mão com a face para baixo em Posição de Defesa e, se isso acontecer, compre 1 card.','\r',char(13)),'\n',char(10)),'Mudar para Posição de Defesa com a face para baixo','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81913510,'NEX',replace(replace('Envie 1 monstro "Neoespacial" com a face para cima que você controla para o Cemitério. \r\nInvoque por Invocação-Especial 1 monstro de Nível 4 com o mesmo nome do seu Deck Adicional.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81914447,'Dança Ogro Noh-P.U.N.K.',replace(replace('Uma vez por turno, quando seu oponente ativar um efeito de monstro (Efeito Rápido): até o final deste turno, você pode fazer com que este card ganhe ATK igual ao ATK original desse monstro do oponente. \r\nVocê só pode usar cada um dos seguintes efeitos de "Dança Ogro Noh-P.U.N.K." uma vez por turno. \r\nVocê pode oferecer como Tributo 1 monstro "P.U.N.K."; Invoque este card por Invocação-Especial da sua mão. \r\nVocê pode enviar este card da sua mão ou do campo para o Cemitério; adicione 1 monstro "P.U.N.K." do seu Deck à sua mão, exceto um monstro de Nível 8.','\r',char(13)),'\n',char(10)),'Invocar este card por Invocação Especial','Procurar no Deck','Aumentar ATK','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81916745,'Lycoris Lírioceifadora',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nSe um ou mais monstros forem enviados do campo para o Cemitério do seu oponente, enquanto este card estiver na sua Zona de Monstros, mesmo durante a Etapa de Dano: você pode ganhar PV igual ao ATK de 1 desses monstros no Cemitério dele. \r\nSe seu oponente sofrer dano de efeito, enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode banir este card; envie 1 monstro do campo para o Cemitério com ATK igual ou menor que a diferença entre seus PV e os do seu oponente. \r\nVocê só pode usar cada efeito de "Lycoris Lírioceifadora" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ganhar PV','Enviar para o Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81919143,'Esmaga Cérebro','Uma vez por turno, durante a Fase Final, se este card destruiu um monstro do oponente em batalha e o enviou para o Cemitério neste turno, enquanto você o controlava: você pode escolher 1 desses monstros destruídos no Cemitério; Invoque o alvo por Invocação-Especial.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81927732,'Ataqueraptor - Falcão Revolto',replace(replace('3 monstros do Tipo Besta Alada de Nível 6	\r\nVocê pode desassociar 1 Matéria Xyz deste card; neste turno, este card pode atacar todos os monstros que seu oponente controla, uma vez cada. \r\nNo começo da Etapa de Dano, se este card batalhar um monstro do oponente com a face para cima Invocado por Invocação-Especial: o ATK e DEF desse monstro se tornam 0. \r\nSe este card tiver um Monstro Xyz "Ataqueraptor" como Matéria Xyz, ele ganha este efeito.\r\n● Uma vez por turno: você pode escolher 1 monstro que seu oponente controla; destrua-o e, se isso acontecer, cause dano ao seu oponente igual à metade do ATK que esse monstro tinha no campo.','\r',char(13)),'\n',char(10)),'Ataques múltiplos','Destruir um monstro','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81933259,'Ritual de Espelho-Besta',replace(replace('Este card é usado na Invocação-Ritual de "Espelho do Demônio". \r\nVocê também deve oferecer como Tributo monstros do campo ou da sua mão cuja soma dos Níveis seja igual a 6 ou mais.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81945676,'Cetro Mementotlan',replace(replace('Durante a Fase Principal do seu oponente, se você controlar "Mementoal Tecuhtlica - Criação Combinada" (Efeito Rápido): você pode descartar este card e, depois, escolha 1 monstro com a face para cima que seu oponente controla; tome o controle dele até a Fase Final. \r\nDurante sua Fase Principal: você pode destruir 1 monstro "Memento" que você controla e, se isso acontecer, adicione 1 card "Memento" do seu Deck à sua mão, exceto "Cetro Mementotlan". \r\nVocê só pode usar cada efeito de "Cetro Mementotlan" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81945678,'Coringa Imprevisível',replace(replace('Durante a Fase Principal ou de Batalha: envie 1 Magia do seu Deck para o Cemitério que liste especificamente todos "O Cavaleiro da Rainha", "O Cavaleiro do Rei" e "O Cavaleiro do Valete"; este efeito se torna o efeito dessa Magia quando esse card for ativado. \r\nDurante a Fase Final, se este card estiver no seu Cemitério: você pode escolher 1 monstro Guerreiro de LUZ no seu Cemitério; embaralhe-o no Deck e, se isso acontecer, adicione este card à sua mão. \r\nVocê só pode usar cada efeito de "Coringa Imprevisível" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81951640,'Aparelho de Inicialização Não Autorizado',replace(replace('Uma vez por turno, você pode: escolher 1 monstro com a face para cima que você controla; equipe este card no alvo, OU: desequipe este card e Invoque-o por Invocação-Especial. \r\nSe o monstro equipado seria destruído em batalha ou por um efeito de card, em vez disso, destrua este card. \r\nSe este card for destruído e enviado para o Cemitério enquanto estiver equipado a um monstro: você pode Invocar este card por Invocação-Especial. \r\nVocê só pode usar este efeito de "Aparelho de Inicialização Não Autorizado" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81954378,'Foice da Morte - Ceiforror',replace(replace('Só pode ser equipado a "Guardião Ceiforror". \r\nEle ganha 500 de ATK para cada monstro que estiver em qualquer Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81962318,'Dragunidade Tribus','Quando este card for Invocado por Invocação-Normal ou Especial: você pode enviar 1 monstro Dragão de Nível 3 ou menos do seu Deck para o Cemitério.','Adicionar à mão e enviar para o Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81965543,'Desconfiança Paranoia',replace(replace('Tome o controle de todos os monstros do seu oponente na coluna deste card. \r\nSe este card Baixado sob o controle do seu dono deixou o campo devido a um efeito do oponente e agora estiver no Cemitério ou banido: você pode Invocar este card por Invocação-Especial como um Monstro de Efeito (Demônio/TREVAS/Nível 10/ATK 4000/DEF 4000) com o seguinte efeito (este card NÃO é considerado como uma Armadilha).\r\n● Não é afetado pelos efeitos de card do seu oponente ativados na mesma coluna.	\r\nVocê só pode ativar 1 "Desconfiança Paranoia" por turno.','\r',char(13)),'\n',char(10)),'Tomar controle','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81974607,'Asa Críptica',replace(replace('Se você controlar um monstro "Críptico(a)", você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê pode oferecer este card como Tributo; até o final deste turno, aumente em 4 o Nível de todos os monstros "Críptico(a)" que você controla.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81977953,'Tempestade no Deserto',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao banir 2 monstros de VENTO e 1 de TERRA do seu Cemitério. \r\nUma vez por turno: você pode descartar 1 card e, depois, escolha 1 Magia/Armadilha no campo; destrua-a.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81978611,'Confiança Xyz',replace(replace('Adicione 1 card "Xyz de Armadura" do seu Deck ou Cemitério à sua mão e, depois, você pode fazer com que até 2 monstros com a face para cima que você controla se tornem todos de Nível 3 ou todos de Nível 5, até o final deste turno. \r\nDurante sua Fase Principal, exceto no turno em que este card foi enviado para o Cemitério: você pode banir este card do seu Cemitério e, depois, escolha 1 Card de Monstro Xyz considerado como um Card de Equipamento na sua Zona de Magias & Armadilhas; Invoque-o por Invocação-Especial. \r\nVocê só pode ativar 1 "Confiança Xyz" por turno.','\r',char(13)),'\n',char(10)),'Adicionar à sua mão 1 card "Xyz de Armadura"','Invocar por Invocação Especial o Monstro Xyz que está sendo considerado como Card de Equipamento','Altere o Nível do monstro selecionado para 3','Altere o Nível do monstro selecionado para 5','Não alterar o Nível','Escolha o monstro cujo Nível será alterado','','','','','','','','','','');
INSERT INTO texts VALUES(81983656,'Domador Asanegra - Falcão Joe de Obsidiana',replace(replace('1 Regulador "Asanegra" + 1+ monstros "Asanegra" não-Reguladores	\r\nVocê pode escolher 1 monstro Besta Alada de Nível 5 ou mais no seu Cemitério; Invoque-o por Invocação-Especial. \r\nQuando seu oponente ativar um card ou efeito que só escolha este card como alvo, ou quando seu oponente escolher este card como alvo de um ataque (Efeito Rápido): você pode escolher 1 outro monstro "Asanegra" que você controla que seria um alvo apropriado; esse card/efeito/ataque agora escolhe o novo alvo. \r\nVocê só pode usar cada efeito de "Domador Asanegra - Falcão Joe de Obsidiana" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81985784,'Demônio Des Feral','VIRE: Escolha 1 card no seu Cemitério; embaralhe o alvo no Deck.','Retornar ao Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81992475,'Barbar, Malebranche do Abismo Ardente',replace(replace('Se você controlar um monstro que não seja um monstro "Abismo Ardente", destrua este card. \r\nVocê só pode usar 1 desses efeitos de "Barbar, Malebranche do Abismo Ardente" por turno e apenas uma vez por turno.\r\n● Se você não controlar nenhum Card de Magia/Armadilha: você pode Invocar este card por Invocação-Especial da sua mão.\r\n● Se este card for enviado para o Cemitério: você pode escolher até 3 cards "Abismo Ardente" no seu Cemitério, exceto "Barbar, Malebranche do Abismo Ardente"; bana-os e, se isso acontecer, cause 300 de dano ao seu oponente para cada um.','\r',char(13)),'\n',char(10)),'Invocação Especial','Dano de efeito','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81994591,'Núcleo de Diamantes de Koa''ki Meiru',replace(replace('Adicione 1 card "Koa''ki Meiru" do seu Deck à sua mão, exceto "Núcleo de Diamantes de Koa''ki Meiru". \r\nVocê pode banir este card do seu Cemitério; pelo restante deste turno, monstros "Koa''ki Meiru" que você controla não podem ser destruídos.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Impedir a destruição','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81997228,'Criado de Combate dos Travesso-Guris',replace(replace('"Lampanimados Travesso-Guris" + "Gotanimados Travesso-Guris" + "Ventanimados Travesso-Guris"	\r\nDeve ser Invocado por Invocação-Fusão. \r\n(Efeito Rápido): você pode oferecer este card como Tributo; destrua todos os monstros que seu oponente controla. \r\nSe este card em sua posse for enviado para o seu Cemitério por um card do seu oponente: você pode escolher 1 Monstro que não seja de Fusão no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê só pode usar este efeito de "Criado de Combate dos Travesso-Guris" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82003859,'Pedágio','Cada duelista deve pagar 500 PV para declarar um ataque.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82005435,'Dama Ninja Yae',replace(replace('Descarte 1 monstro do VENTO da sua mão para o Cemitério. \r\nDevolva todos os Cards de Magia e Armadilha no Campo do seu adversário para a sua mão dos seus donos.','\r',char(13)),'\n',char(10)),'Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82012319,'Golem de Restolhos','Uma vez por turno: você pode escolher 1 monstro "Restolhos" de Nível 4 ou menos no seu Cemitério; Invoque o alvo por Invocação-Especial no campo de qualquer duelista.','Invocação Especial','Invocar por Invocação Especial para o seu Campo','Invocar por Invocação Especial para o Campo do seu oponente','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82016179,'Caridade Silvestre',replace(replace('Compre 3 cards e, depois, se você tiver um card "Silvestre" na sua mão, revele 2 cards da sua mão, incluindo pelo menos 1 card "Silvestre" e, depois, coloque-os no topo do Deck em qualquer ordem. \r\nCaso contrário, revele toda sua mão e, depois, coloque-a no topo do seu Deck em qualquer ordem. \r\nVocê só pode ativar 1 "Caridade Silvestre" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82035781,'Besta Siamesa','Este card pode atacar duas vezes durante a mesma Fase de Batalha.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82041999,'Madame Aranha Joruri-P.U.N.K.',replace(replace('Você pode pagar 600 PV; adicione 1 Armadilha "P.U.N.K." do seu Deck à sua mão. \r\nQuando você ativar um card ou efeito "P.U.N.K." que escolha como alvo um card que seu oponente controla (exceto durante a Etapa de Dano) (Efeito Rápido): você pode escolher 1 monstro com a face para cima que seu oponente controla; o ATK dele é diminuído pela metade até o final deste turno. \r\nVocê só pode usar cada efeito de "Madame Aranha Joruri-P.U.N.K." uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82044279,'Dragão Sincro de Asas Transparentes',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nUma vez por turno, quando outro monstro de Nível 5 ou mais ativar seus efeitos no campo (Efeito Rápido): você pode negar a ativação e, se isso acontecer, destrua-o. \r\nUma vez por turno, quando um efeito de monstro for ativado que escolha como alvo 1 monstro de Nível 5 ou mais no campo (e nenhum outro card) (Efeito Rápido): você pode negar a ativação e, se isso acontecer, destrua-o. \r\nSe o efeito deste card destruir um monstro, até o final deste turno, este card ganha ATK igual ao ATK original do monstro destruído.','\r',char(13)),'\n',char(10)),'Negue a ativação do efeito de um monstro de Nível 5 ou mais e destrua-o','Negue a ativação de um efeito de monstro que escolha 1 monstro de Nível 5 ou mais como alvo e destrua-o','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82044280,'Dragão Sincro de Asas Transparentes',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nUma vez por turno, quando outro monstro de Nível 5 ou mais ativar seus efeitos no campo (Efeito Rápido): você pode negar a ativação e, se isso acontecer, destrua-o. \r\nUma vez por turno, quando um efeito de monstro for ativado que escolha como alvo 1 monstro de Nível 5 ou mais no campo (e nenhum outro card) (Efeito Rápido): você pode negar a ativação e, se isso acontecer, destrua-o. \r\nSe o efeito deste card destruir um monstro, até o final deste turno, este card ganha ATK igual ao ATK original do monstro destruído.','\r',char(13)),'\n',char(10)),'Negue a ativação do efeito de um monstro de Nível 5 ou mais e destrua-o','Negue a ativação de um efeito de monstro que escolha 1 monstro de Nível 5 ou mais como alvo e destrua-o','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82045034,'Os Cem Trovões do Dragão do Trovão',replace(replace('Escolha 1 monstro Trovão no seu Cemitério; Invoque-o por Invocação-Especial e, depois, você pode Invocar por Invocação-Especial tantos monstros com esse mesmo nome quanto possível do seu Cemitério. \r\nO monstro(s) \r\nInvocado(s) por Invocação-Especial por este efeito é(são) banido(s) quando deixar(em) o campo e, além disso, enquanto qualquer um deles estiver com a face para cima no campo, você não pode Invocar monstros por Invocação-Especial, exceto monstros Trovão. \r\nVocê só pode ativar 1 "Os Cem Trovões do Dragão do Trovão" por turno.','\r',char(13)),'\n',char(10)),'Invocar 1 monstro com o mesmo nome por Invocação Especial?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82050203,'Dotedotengu','Se este card, em sua posse, for enviado para o seu Cemitério por um efeito de card do oponente: você pode escolher 1 card que seu oponente controla; volte-o para a mão.','Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82052602,'Gagagavolta',replace(replace('Durante o turno em que um monstro "Gagaga" que você controla foi destruído em batalha e enviado para o Cemitério: Invoque por Invocação-Especial do seu Cemitério tantos monstros quanto possível que foram destruídos em batalha neste turno, com a face para cima em Posição de Defesa e, depois, sofra 600 de dano para cada monstro Invocado por Invocação-Especial por este efeito. \r\nVocê só pode ativar 1 "Gagagavolta" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82065276,'Herói Oscillo','Um guerreiro estranho de outra dimensão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82085295,'Diabretiço Pincelpluma',replace(replace('Você pode revelar 1 Monstro de Ritual na sua mão; Invoque por Invocação-Especial tanto este card da sua mão quanto 1 monstro "Diabretiço" do seu Deck, exceto "Diabretiço Pincelpluma". \r\nSe este card for Invocado por Invocação-Especial do Deck: você pode escolher 1 Monstro de Ritual no seu Cemitério; adicione-o à sua mão. \r\nVocê só pode usar 1 efeito de "Diabretiço Pincelpluma" por turno e apenas uma vez por turno. \r\nVocê não pode Invocar monstros por Invocação-Especial do Deck Adicional.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82085619,'Amizade Radiante','O pacificador entre os monstros.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82090807,'Caído de Argyros',replace(replace('Se um monstro de Nível/Classe/Link 2 estiver no campo, você pode Invocar este card por Invocação-Especial (da sua mão) em qualquer campo. \r\nVocê só pode Invocar "Caído de Argyros" por Invocação-Especial uma vez por turno desta forma. \r\nNenhum duelista pode ativar os efeitos de Monstros Link que apontarem para este card. \r\nDurante o turno do seu oponente (Efeito Rápido): você pode escolher 1 Monstro Xyz no campo; desassocie 1 ou 2 matérias dele. \r\nVocê só pode usar este efeito de "Caído de Argyros" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial para o seu campo','Invocar por Invocação Especial para o campo do seu oponente','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82099401,'Vidente de Cristal','VIRE: Escave os 2 cards do topo do seu Deck e, depois, adicione 1 deles à sua mão e, depois, coloque o outro no fundo do seu Deck.','Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82103466,'Serpente Divina Geh',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial por seu próprio efeito. \r\nSe um ou mais monstros que você controla forem destruídos por um ataque ou efeito de card do oponente: você pode pagar metade dos seus PV; Invoque este card por Invocação-Especial da sua mão. \r\nNão pode ser alvo de efeitos de card. \r\nSe este card atacar um monstro do oponente, apenas durante a Etapa de Dano, negue os efeitos desse monstro enquanto ele estiver com a face para cima no campo (mas os efeitos dele ainda podem ser ativados) e, além disso, o ATK dele se torna metade do seu ATK original. \r\nUma vez por batalha, se este card batalhar, durante o cálculo de dano (Efeito Rápido): você pode fazer com que o ATK deste card se torne igual ao maior ATK original no campo (em caso de empate, você seleciona).','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82105704,'Feliz Lembrança Purrely',replace(replace('Selecione 1 card no campo e, até o final do próximo turno, na primeira vez que ele seria destruído por um efeito de card, ele não é destruído. \r\nDepois de selecionar um card, você pode aplicar o seguinte efeito.\r\n● Descarte 1 card e, se isso acontecer, Invoque por Invocação-Especial do seu Deck 1 monstro "Purrely" de Nível 1.	\r\nUm Monstro Xyz "Purrely" que tenha este card como matéria ganha o seguinte efeito.\r\n● Este card pode atacar monstros um número de vezes a cada Fase de Batalha, até o número de "Feliz Lembrança Purrely" associados a ele +1.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial do Deck?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82108372,'Mudora','Ganha 200 de ATK para cada monstro Fada no seu Cemitério.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82112494,'Samurai Superpesado Prodígio Wakaushi',replace(replace('Escala de Pêndulo = 8\r\n[ Efeito de Pêndulo ]\r\nSe você não tiver Magias/Armadilhas no seu Cemitério: você pode colocar 1 Monstro Pêndulo "Samurai Superpesado" do seu Deck, exceto "Samurai Superpesado Prodígio Wakaushi", na sua outra Zona de Pêndulo e, depois, Invoque este card por Invocação-Especial. \r\nVocê só pode usar este efeito de "Samurai Superpesado Prodígio Wakaushi" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe você não tiver Magias/Armadilhas no seu Cemitério: você pode descartar 1 monstro; Invoque por Invocação-Especial 1 monstro "Samurai Superpesado" da sua mão ou do Deck em Posição de Defesa e, além disso, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros "Samurai Superpesado". \r\nSe este card for usado como Matéria Sincro e adicionado ao seu Deck Adicional com a face para cima: você pode colocar este card na sua Zona de Pêndulo. \r\nVocê só pode usar cada efeito de "Samurai Superpesado Prodígio Wakaushi" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82112775,'M.D.D. - Mestre de uma Dimensão Diferente','Uma vez por turno: você pode descartar 1 Magia e, depois, escolha 1 dos seus monstros banidos; Invoque o alvo por Invocação-Especial.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82114013,'Dragoons Marinhos de Draconia',replace(replace('Escala de Pêndulo = 7\r\n[ Efeito de Pêndulo ]\r\nQuando um monstro for destruído em batalha: você pode Invocar por Invocação-Especial 1 Monstro Normal da sua mão. Você só pode usar este efeito de "Dragoons Marinhos de Draconia" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nEspreitando-se silenciosamente das profundezas do mar, as tropas de elite de operação secreta da marinha do Império de Draconia travam uma batalha incessante contra o odiado Principado de Dinon nas margens opostas do oceano.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82116191,'Planta Carnívora Gigante','Este card ganha 200 de ATK cada vez que um monstro do Tipo Planta for enviado do campo para o Cemitério.','Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82119326,'Caudas da Cauda de Fadas',replace(replace('O monstro equipado ganha 1000 de ATK. \r\nUma vez por turno, durante sua Fase Principal: você pode Invocar por Invocação-Fusão 1 Monstro de Fusão Mago do seu Deck Adicional, usando monstros da sua mão, do campo e/ou "Príncipe das Fadas" que seu oponente controla como matéria. \r\nSe este card estiver no seu Cemitério: você pode equipar este card a 1 monstro "Cauda de Fadas" no campo e, depois, imediatamente depois que este efeito resolver, você pode Invocar por Invocação-Normal 1 monstro Mago com 1850 de ATK. \r\nVocê só pode usar este efeito de "Caudas da Cauda de Fadas" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Fusão','Efeito de Equipamento','Invocação Normal?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82128978,'Magigarota Livromante',replace(replace('Você pode revelar 1 Monstro de Ritual na sua mão: Invoque este card por Invocação-Especial da sua mão. \r\nDurante o turno do seu oponente (Efeito Rápido): você pode Invocar por Invocação-Ritual 1 Monstro de Ritual "Livromante" da sua mão, ao oferecer como Tributo monstros da sua mão ou do campo cuja soma dos Níveis seja igual ou exceda seu Nível. \r\nVocê só pode usar cada efeito de "Magigarota Livromante" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82134632,'Casa de Jogos Melffy','Desassocie qualquer número de matérias dos Monstros Xyz Besta que você controla e, depois, escolha até esse mesmo número de cards que seu oponente controla; devolva-os para a mão e, além disso, até o final deste turno, todos os Monstros Xyz Besta que você controla ganham 500 de ATK para cada matéria desassociada para ativar este card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82135803,'Desirae do Criademônio',replace(replace('"Gravador Criademônio" + 2 monstros Demônio de LUZ	\r\n(Efeito Rápido): até o final deste turno, você pode negar os efeitos de um número de cards com a face para cima no campo, até a soma do Valor Link dos Monstros Link equipados a este card. \r\nSe este card for enviado para o Cemitério: você pode embaralhar no Deck/Deck Adicional 1 outro monstro Demônio de LUZ do seu Cemitério e, depois, escolha 1 card no campo; envie-o para o Cemitério. \r\nVocê só pode usar cada efeito de "Desirae do Criademônio" uma vez por turno.','\r',char(13)),'\n',char(10)),'Negar o efeito','Enviar para o Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82140600,'Avalon','Escolha 5 monstros "Nobre Cavaleiro" no seu Cemitério, incluindo pelo menos 1 monstro "Artorigus" e pelo menos 1 monstro "Laundsallyn"; bana os alvos e, se isso acontecer, destrua todos os cards no campo.','Destruir todos os cards no Campo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82159583,'Companhia de Palhaços Biancaviso',replace(replace('Você pode Invocar este card por Invocação-Tributo com a face para cima ao oferecer como Tributo 1 Monstro de Ritual, de Fusão, Sincro, Xyz, Pêndulo ou Link. \r\nSe este card for Invocado por Invocação-Tributo: você pode ativar 1 desses efeitos (mas você só pode usar cada efeito de "Companhia de Palhaços Biancaviso" uma vez por turno);\r\n● Compre cards igual ao número de monstros oferecidos como Tributo.\r\n● Negue os efeitos de cards com a face para cima que seu oponente controla, igual ao número de monstros oferecidos como Tributo.	\r\nUma vez por turno, durante a Fase Principal do seu oponente, você pode (Efeito Rápido): imediatamente depois que este efeito resolver, Invocar 1 monstro por Invocação-Tributo.','\r',char(13)),'\n',char(10)),'Ofereça 1 monstro como Tributo para Invocar por Invocação Tributo','Escolher um efeito','Invocação Tributo','Comprar','Negar','','','','','','','','','','','');
INSERT INTO texts VALUES(82162616,'Galáxia Eterna',replace(replace('Se você controlar um monstro "Fóton" ou "Galáxia": escolha 1 Monstro Xyz que você controla; Invoque por Invocação-Especial do seu Deck Adicional, 1 Monstro Xyz "Fóton" ou "Galáxia" que seja 4 Classes maior que o alvo, usando o alvo como matéria. \r\n(Isso é considerado uma Invocação-Xyz. Transfira as matérias dele para o monstro Invocado.) \r\nVocê só pode ativar 1 "Galáxia Eterna" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82176812,'Hidrotartaruga, o Guerreiro Edificado','VIRE: Escolha 1 Card de Magia/Armadilha que seu oponente controla; destrua-o.','Destruir Magias/Armadilhas','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82184400,'Defensor do Abismo',replace(replace('2 monstros de ÁGUA	\r\nNão pode ser usado como Matéria Link no turno em que for Invocado por Invocação-Link. \r\nSe este card for Invocado por Invocação-Link: você pode Invocar por Invocação-Especial 1 monstro Peixe da sua mão em uma zona sua para a qual este card apontar. \r\nVocê pode escolher 1 outro monstro Peixe que você controla e 1 card que seu oponente controla; bana esses cards. \r\nVocê só pode usar cada efeito de "Defensor do Abismo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82190203,'Asas de Luz',replace(replace('Durante a Fase Principal: adicione 1 Monstro Pêndulo "Rei Supremo Dragão" ou "Rei Supremo Portal" do seu Deck à sua mão ou, se você controlar "Rei Supremo Z-ARC", em vez disso, você pode Invocá-lo por Invocação-Especial. \r\nVocê só pode ativar 1 "Asas de Luz" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82197831,'Esmagatanque Rinosabre Furioso',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nVocê pode descartar qualquer número de cards; este card ganha 700 de ATK para cada card descartado. \r\nNo final da Fase de Batalha, se este card batalhou: você pode enviar este card para o Cemitério; Invoque monstros por Invocação-Especial do seu Cemitério cuja soma dos Níveis seja igual a 7, exceto "Esmagatanque Rinosabre Furioso", mas seus efeitos são negados. \r\nVocê só pode usar cada efeito de "Esmagatanque Rinosabre Furioso" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82199284,'Falcão do Vale das Névoas','Não pode declarar um ataque a não ser que você devolva 1 card que você controla para a mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82213171,'Prometeu, Rei das Sombras','Se este card for Invocado por Invocação-Normal: bana 1 ou mais monstros de TREVAS no seu Cemitério e, se isso acontecer, até o final deste turno, este card ganha 400 de ATK para cada um.','Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82224646,'Sincron Camarartista de Olhos Anômalos',replace(replace('Escala de Pêndulo = 6\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno: você pode escolher 1 monstro "Camarartista" ou "Olhos Anômalos" que você controla; neste turno, esse monstro com a face para cima é considerado como um Regulador e, além disso, o Nível dele se torna 1 (mesmo que este card deixe o campo).\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe este card, Invocado por Invocação-Especial do Deck Adicional, for usado como Matéria Sincro, bana-o. \r\nQuando este card for Invocado por Invocação-Normal: você pode escolher 1 monstro "Camarartista" ou "Olhos Anômalos" de Nível 3 ou menos no seu Cemitério; Invoque-o por Invocação-Especial, mas ele tem seus efeitos negados. \r\nUma vez por turno: você pode escolher 1 card na sua Zona de Pêndulo; Invoque-o por Invocação-Especial, mas ele tem seus efeitos negados (se houver) e, se isso acontecer, imediatamente depois que este efeito resolver, Invoque por Invocação-Sincro 1 Monstro Sincro usando apenas esse monstro e este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82243738,'Anjo O1',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) ao revelar 1 monstro de Nível 7 ou mais da sua mão. \r\nVocê só pode Invocar "Anjo O1" por Invocação-Especial uma vez por turno desta forma. \r\nEnquanto você controlar este card Invocado por Invocação-Especial, você pode Invocar por Invocação-Tributo 1 monstro de Nível 7 ou mais em Posição de Ataque durante sua Fase Principal, em adição à sua Invocação-Normal/Baixar (padrão). \r\n(Você só pode se aproveitar deste efeito uma vez por turno.)','\r',char(13)),'\n',char(10)),'','Invocação por Tributo pelo efeito de "Anjo O1"','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82255872,'Saga dos Guerreiros Antigos - Caminho Valoroso',replace(replace('Se um ou mais monstros "Guerreiros Antigos" seriam destruídos em batalha, em vez disso, você pode enviar este card para o Cemitério. \r\nVocê só pode usar cada um dos seguintes efeitos de "Saga dos Guerreiros Antigos - Caminho Valoroso" uma vez por turno. \r\nSe seu oponente Invocar um ou mais monstros por Invocação-Especial (exceto durante a Etapa de Dano): você pode Invocar por Invocação-Especial 1 "Ficha de Guerreiros Antigos" (Besta-Guerreira/VENTO/Nível 1/ATK 500/DEF 500). \r\nQuando um card ou efeito for ativado que escolha como alvo um ou mais monstros "Guerreiros Antigos" no campo: você pode banir este card do seu Cemitério; negue a ativação.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82255873,'Ficha de Guerreiros Antigos','Invocado por Especial com o efeito "Saga dos Guerreiros Antigos - Caminho Valoroso".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82257671,'Gatchiri @Ignister',replace(replace('Na primeira vez que cada monstro Ciberso que você controla seria destruído por um efeito de card a cada turno, ele não é destruído. \r\nVocê só pode usar cada um dos seguintes efeitos de "Gatchiri @Ignister" uma vez por turno.\r\n● Você pode escolher 1 Monstro de Efeito Ciberso que você controla; negue seus efeitos e, se isso acontecer, Invoque este card por Invocação-Especial da sua mão.\r\n● Se este card for enviado do campo para o seu Cemitério: você pode escolher 1 monstro com a face para cima que você controla; o alvo não é afetado pelos efeitos de card do seu oponente até o final do turno do seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82257940,'Troca de Presentes','Os dois duelistas banem 1 card de seus Decks, com a face para baixo, e se isso acontecer, durante a Fase Final deste turno, os dois duelistas adicionam às suas mãos o card banido pelo seu oponente por este efeito.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82260502,'Hieraco-Esfinge','Enquanto este card permanecer no seu Campo com a face para cima, o seu adversário não pode escolher um monstro em Posição de Defesa com a face para baixo como alvo de um ataque.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82263578,'Depois da Tempestade','Se não houverem outros cards no campo: escolha 1 monstro de ÁGUA ou VENTO em seu Cemitério; adicione o alvo à sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82270047,'Espada de Luz de Kozmo',replace(replace('Só pode ser equipado a um monstro "Kozmo" do Tipo Psíquico. \r\nEle ganha 500 de ATK e DEF, pode realizar até 2 ataques contra monstros durante cada Fase de Batalha e, além disso, se ele atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente. \r\nSe este card for enviado do campo para o Cemitério: você pode pagar 800 PV; adicione este card à sua mão. \r\nVocê só pode usar este efeito de "Espada de Luz de Kozmo" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicione este card do Cemitério à sua mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82286798,'Akstra Kashtira',replace(replace('Se um ou mais Monstros Xyz "Kashtira" com a face para cima que você controla for destruído em batalha ou por um efeito de card: bana 1 "Visas Starfrost" da sua mão, do seu Deck ou da sua Zona de Monstros e, se isso acontecer, Invoque por Invocação-Especial 1 "Astraloud Perverso" do seu Deck Adicional, ignorando suas condições de Invocação. \r\nSe este card for banido: você pode escolher 1 dos seus "Visas Starfrost" banidos; adicione-o à sua mão. \r\nVocê só pode usar cada efeito de "Akstra Kashtira" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82293134,'Besta Heráldica Leão',replace(replace('Durante a Fase Final do turno em que este card foi Invocado por Invocação-Normal: destrua este card. \r\nQuando este card for enviado para o Cemitério: adicione 1 monstro "Besta Heráldica" do seu Deck à sua mão, exceto "Besta Heráldica Leão". \r\nVocê só pode usar este efeito de "Besta Heráldica Leão" uma vez por turno.','\r',char(13)),'\n',char(10)),'Destruir','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82301904,'Dragão Imperador do Caos - Enviado do Fim',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao banir 1 monstro de LUZ e 1 de TREVAS do seu Cemitério. \r\nUma vez por turno: você pode pagar 1000 PV; envie para o Cemitério tantos cards quanto possível das mãos e do campo dos dois duelistas e, depois, cause 300 de dano ao seu oponente para cada card enviado para o Cemitério do oponente por este efeito. \r\nVocê não pode ativar outros cards ou efeitos durante o turno em que ativar o efeito deste card.','\r',char(13)),'\n',char(10)),'Invocação Especial','Enviar para o Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82308875,'Número 7: Sorte Pura',replace(replace('3 monstros de Nível 7	\r\nVocê pode desassociar 1 Matéria Xyz deste card; lance um dado de 6 faces duas vezes e o ATK deste card se torna o maior dos dois resultados x 700 até a próxima Fase Final do seu oponente e, depois, se a soma dos resultados for exatamente 7, aplique 1 desses efeitos.\r\n● Envie todos os outros cards no campo para o Cemitério.\r\n● Invoque por Invocação-Especial 1 monstro da sua mão ou de qualquer Cemitério.\r\n● Compre 3 cards e, depois, descarte 2 cards.','\r',char(13)),'\n',char(10)),'Role um dado','Envie para o Cemitério todos os outros cards no campo','Invocar por Invocação Especial 1 monstro da sua mão ou Cemitério','Compre 3 cards e depois descarte 2 cards','','','','','','','','','','','','');
INSERT INTO texts VALUES(82315403,'Dragão Eterno Cibernético',replace(replace('1 monstro "Dragão Cibernético" + 2 monstros Máquina	\r\nSe você tiver um ou mais Monstros de Fusão Máquina no seu Cemitério, seu oponente não pode escolher este card como alvo de efeitos de card e, além disso, ele não pode ser destruído pelos efeitos de card do seu oponente. \r\nSe este card Invocado por Invocação-Fusão que você controla for enviado para o seu Cemitério por um card do oponente: você pode Invocar por Invocação-Especial 1 "Dragão Cibernético" da sua mão, do Deck ou do Cemitério. \r\nVocê pode banir este card do seu Cemitério; neste turno, seu oponente não pode escolher Monstros de Fusão que você controla como alvo de efeitos de card e, além disso, eles não podem ser destruídos pelos efeitos de card do seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82315772,'Besta Heráldica Centícora','Se você controlar 2 ou mais monstros "Besta Heráldica", você pode Invocar este card por Invocação-Especial (da sua mão).','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82319644,'Tlakalel, Sua Majestade Malevolente','Se este card for Invocado por Invocação-Tributo: você pode destruir qualquer número de monstros com a face para cima que seu oponente controla cujo ATK combinado seja menor ou igual ao ATK original do monstro oferecido como Tributo para a Invocação-Tributo deste card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82321037,'Verdadeiro Rei Bahrastos, o Fundurador',replace(replace('Se este card estiver na sua mão: você pode destruir 2 outros monstros na sua mão e/ou com a face para cima no seu campo, incluindo um monstro de ÁGUA e, se isso acontecer, Invoque este card por Invocação-Especial e, se isso acontecer, você pode banir até 2 Cards de Magia/Armadilha do campo e/ou Cemitério do seu oponente, se os dois monstros destruídos eram de ÁGUA. \r\nSe este card for destruído por um efeito de card: você pode Invocar por Invocação-Especial 1 monstro do Tipo Wyrm que não seja de ÁGUA do seu Deck em Posição de Defesa. \r\nVocê só pode usar cada efeito de "Verdadeiro Rei Bahrastos, o Fundurador" uma vez por turno.','\r',char(13)),'\n',char(10)),'Banir o Card de Magia/Armadilha selecionado?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82323997,'Dragão Vermelho Nova/Modo de Ataque',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial com "Ativar Modo de Ataque". \r\nQuando seu oponente ativar um card ou efeito (Efeito Rápido): você pode banir este card que você controla até a Fase Final; bana cards que seu oponente controla até o número de Reguladores no seu Cemitério. \r\nQuando um monstro do oponente declarar um ataque: você pode banir este card que você controla até a Fase Final; negue o ataque e, depois, encerre a Fase de Batalha. \r\nSe este card for destruído: você pode Invocar por Invocação-Especial 1 "Dragão Vermelho Nova" do seu Cemitério.','\r',char(13)),'\n',char(10)),'Banir','Negar o ataque','Invocação Especial','Banir até a Fase Final','','','','','','','','','','','','');
INSERT INTO texts VALUES(82324105,'Impulso Limite',replace(replace('Envie 2 cards da sua mão para o Cemitério; Invoque por Invocação-Especial 2 "Fichas de Alma" (Demônio/TREVAS/Nível 1/ATK 0/DEF 0). \r\nElas não podem ser oferecidas como Tributo, exceto para uma Invocação-Tributo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82324106,'Ficha de Alma','Invocado por Especial com o efeito "Impulso Limite". Esta Ficha não pode ser oferecida como Tributo, exceto para uma Invocação-Tributo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82324312,'Esquadrão de Reconhecimento Goblin',replace(replace('Quando este card atacar diretamente com sucesso, você pode olhar 1 card aleatório na mão do seu oponente. \r\nSe for um Card de Magia, envie-o para o Cemitério. \r\nSe este card atacar, ele é colocado em Posição de Defesa no final da Fase de Batalha. \r\nA posição de batalha deste card não pode ser alterada até o final do seu próximo turno, exceto com um efeito de card.','\r',char(13)),'\n',char(10)),'Revelar sua mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82340056,'Oferenda aos Imortais','Quando um monstro do seu oponente declarar um ataque direto enquanto você tiver 3000 ou menos PV: negue o ataque e, se isso acontecer, Invoque por Invocação-Especial 2 "Ficha Cerimonial" (Rocha/TERRA/Nível 1/ATK 0/DEF 0) e, se isso acontecer, adicione 1 card "Imortal Terrestre" do seu Deck à sua mão. "Ficha Cerimonial" não pode ser oferecido como Tributo, exceto para a Invocação-Tributo de um monstro "Imortal Terrestre" e não pode ser usado como Matéria Sincro.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82340057,'Ficha Cerimonial','Invocado por Especial com o efeito "Oferenda aos Imortais". Esta Ficha não pode ser oferecida como Tributo, exceto para uma Invocação-Tributo de um monstro "Imortal Terrestre", e não pode ser usada como Matéria Sincro.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82344137,'Phara, a Deusa Primordial',replace(replace('Você pode revelar este card e 1 Magia/Armadilha na sua mão; até o final do próximo turno, nenhum duelista pode ativar cards ou efeitos em resposta à ativação de cards, ou efeitos de cards, com o nome da Magia/Armadilha revelada. \r\nSe este card for enviado da mão ou do campo para o Cemitério por um efeito de Magia/Armadilha: você pode Invocar este card por Invocação-Especial. \r\nSe este card for Invocado por Invocação-Especial do Cemitério: você pode tomar o controle de 1 monstro que seu oponente controla com o maior ATK (em caso de empate, você seleciona). \r\nVocê só pode usar cada efeito de "Phara, a Deusa Primordial" uma vez por turno.','\r',char(13)),'\n',char(10)),'Revelar este card e 1 Magia/Armadilha na sua mão','Invocação Especial','Tome o controle','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82344138,'Phara, a Deusa Primordial',replace(replace('Você pode revelar este card e 1 Magia/Armadilha na sua mão; até o final do próximo turno, nenhum duelista pode ativar cards ou efeitos em resposta à ativação de cards, ou efeitos de cards, com o nome da Magia/Armadilha revelada. \r\nSe este card for enviado da mão ou do campo para o Cemitério por um efeito de Magia/Armadilha: você pode Invocar este card por Invocação-Especial. \r\nSe este card for Invocado por Invocação-Especial do Cemitério: você pode tomar o controle de 1 monstro que seu oponente controla com o maior ATK (em caso de empate, você seleciona). \r\nVocê só pode usar cada efeito de "Phara, a Deusa Primordial" uma vez por turno.','\r',char(13)),'\n',char(10)),'Revelar este card e 1 Magia/Armadilha na sua mão','Invocação Especial','Tome o controle','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82359538,'Eneanave - Aiza.LEON',replace(replace('Escala de Pêndulo = 0\r\n[ Efeito de Pêndulo ]\r\nSempre que um ou mais monstros forem virados com a face para cima, coloque 1 Marcador de E.N. neste card. \r\nNo final da Fase de Batalha, se você tiver um card "Eneanave" na sua outra Zona de Pêndulo: você pode escolher 1 monstro que seu oponente controla com ATK menor que o deste card; destrua-o.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nDepois que este card foi virado com a face para cima, enquanto ele estiver na Zona de Monstros, sempre que seu oponente adicionar um ou mais cards à mão dele por um efeito de card dele, ele sofre 900 de dano para cada card. \r\nQuando seu oponente ativar um card ou efeito em resposta à ativação de um dos seus cards ou efeitos (Efeito Rápido): você pode colocar este card que estiver com a face para baixo, com a face para cima em Posição de Defesa; devolva até 3 cards do campo para a mão. \r\nVocê pode revelar este card na sua mão; Invoque por Invocação-Especial 1 monstro da sua mão com a face para baixo em Posição de Defesa. \r\nVocê não pode Invocar por Invocação-Especial no turno em que ativar este efeito, exceto com a face para baixo em Posição de Defesa.','\r',char(13)),'\n',char(10)),'Destruir','Invocação Especial','Retornar à mão','Já foi virado','','','','','','','','','','','','');
INSERT INTO texts VALUES(82361206,'Tokkosho da Destruição de Fantasmas','Quando o monstro equipado causar Dano de Batalha ao seu oponente, você pode selecionar até 2 monstros no Cemitério do seu oponente e removê-los de jogo.','Banir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82361809,'Espantagarra Reichheart',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) em uma Zona de Monstros Principal sua, adjacente a um monstro "Espantagarra" que você controla ou na coluna dele. \r\nVocê só pode Invocar "Espantagarra Reichheart" por Invocação-Especial uma vez por turno desta forma. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 Magia/Armadilha "Espantagarra" do seu Deck à sua mão e, depois, se 3 ou mais monstros em Posição de Defesa estiverem no campo, você pode comprar 1 card. \r\nVocê só pode usar este efeito de "Espantagarra Reichheart" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Comprar 1 card?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82370493,'Predaplanta Diabousada',replace(replace('1 monstro "Predaplanta" + 1 monstro de Nível 1	\r\nPrimeiro deve ser Invocado por Invocação-Fusão, ou por Invocação-Especial (do seu Deck Adicional) ao oferecer como Tributo 1 monstro em qualquer campo com um Marcador de Predador e 1 monstro "Predaplanta" que você controla. \r\nDurante a Fase Principal, se este card foi Invocado por Invocação-Especial neste turno (Efeito Rápido): você pode escolher Magias/Armadilhas no campo, até o número de monstros com um Marcador de Predador; destrua-as. \r\nVocê só pode usar este efeito de "Predaplanta Diabousada" uma vez por turno.','\r',char(13)),'\n',char(10)),'Efeito de destruição','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82377606,'Deslimitador, Aliado da Justiça','Você pode oferecer este card como Tributo e, depois, escolha 1 monstro "Aliado da Justiça" que você controla; o ATK do alvo se torna o dobro do seu ATK original até o final deste turno.','Alterar o ATK original','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82382815,'Vigilância do Campeão','Se você controlar um Monstro Normal de Nível 7 ou mais, quando um monstro seria Invocado OU um Card de Magia/Armadilha for ativado: negue a Invocação ou ativação e, se isso acontecer, destrua esse card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82385847,'Dinolutador Pancratops',replace(replace('Se seu oponente controlar mais monstros que você, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Dinolutador Pancratops" por Invocação-Especial uma vez por turno desta forma. \r\n(Efeito Rápido): você pode oferecer 1 monstro "Dinolutador" como Tributo e, depois, escolha 1 card que seu oponente controla; destrua-o. \r\nVocê só pode usar este efeito de "Dinolutador Pancratops" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82386016,'Conduzir o Grande Rebanho',replace(replace('Se você controlar um monstro Besta, Besta-Guerreira ou Besta Alada: compre 1 card para cada um desses Tipos de Monstro que você controla. \r\nVocê não pode ativar outros Cards de Magia/Armadilha ou seus efeitos durante o turno em que ativar este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82404868,'Véu do Mago Negro','Pague 1000 PV; Invoque por Invocação-Especial 1 monstro de TREVAS do Tipo Mago da sua mão ou Cemitério.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82419869,'U.A. Ás Perfeito',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) ao devolver 1 monstro "U.A." que você controla para a mão, exceto "U.A. Ás Perfeito". \r\nVocê só pode Invocar "U.A. Ás Perfeito" por Invocação-Especial desta forma uma vez por turno. \r\nUma vez por turno, durante o turno do seu oponente, quando um card ou efeito for ativado: você pode descartar 1 card; negue a ativação e, se isso acontecer, destrua-o (este é um Efeito Rápido).','\r',char(13)),'\n',char(10)),'Negar e destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82422049,'Bênçãos de Gusto','Escolha 2 monstros "Gusto" no seu Cemitério, mais um terceiro monstro "Gusto" no seu Cemitério; embaralhe os 2 primeiros alvos no seu Deck e, depois, Invoque por Invocação-Especial o terceiro alvo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82428674,'Transbordamento Cibernético',replace(replace('Bana um ou mais "Dragão Cibernético" com Níveis diferentes da sua mão, do campo com a face para cima e/ou do Cemitério e, depois, destrua o mesmo número de cards que seu oponente controla. \r\nSe este card no campo for destruído por um efeito de card: adicione 1 Magia/Armadilha "Ciber" do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "Transbordamento Cibernético" uma vez por turno.','\r',char(13)),'\n',char(10)),'Continuar selecionando?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82432018,'Máscara da Brutalidade',replace(replace('O monstro equipado ganha 1000 de ATK e perde 1000 de DEF. \r\nUma vez por turno, durante sua Fase de Apoio, pague 1000 PV ou destrua este card.','\r',char(13)),'\n',char(10)),'Pagar 1000 PV?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82434071,'Peão Inférnico',replace(replace('Durante sua Fase de Compra, se você não tiver cards na sua mão, em vez de conduzir sua compra normal: você pode banir este card do seu Cemitério e, depois, ative 1 desses efeitos;\r\n● Coloque 1 card "Inférnico(a)" do seu Deck no topo do seu Deck.\r\n● Baixe 1 Magia/Armadilha "Vácuo" diretamente do seu Deck.','\r',char(13)),'\n',char(10)),'Ativar o efeito de "Peão Inférnico" em vez de comprar','Escolha 1 card "Inférnico/a" do seu Deck e coloque-o no topo do seu Deck','Baixar 1 Card de Magia/Armadilha "Vácuo" do seu Deck','Escolha o(s) card(s) para colocar no topo do Deck','','','','','','','','','','','','');
INSERT INTO texts VALUES(82452993,'Lobo Solitário',replace(replace('Você pode ativar este card apenas se existir apenas 1 monstro no seu Campo e se for "Chu-Suke, O Lutador Rato", "Monge Lutador" ou "Mestre Monge". \r\nEsse monstro não é destruído como resultado de um combate, e não é afetado por qualquer efeito dos monstros do seu adversário.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82458280,'Golem de Buraco Mágico',replace(replace('Uma vez por turno, você pode selecionar 1 monstro com a face para cima que você controla. \r\nSeu ATK é reduzido pela metade até a Fase Final, e ele pode atacar seu oponente diretamente neste turno. \r\nDurante o turno em que você ativar este efeito, apenas o monstro escolhido pode atacar.','\r',char(13)),'\n',char(10)),'Ataque direto','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82460246,'Planeta Pacífico Calarium',replace(replace('Quando este card for ativado: você pode adicionar 1 monstro "Mannadium" ou 1 "Visas Starfrost" do Deck à sua mão. \r\nMonstros de LUZ que você controla ganham 100 de ATK para cada Regulador que você controla e no seu Cemitério. \r\nSe um ou mais Reguladores com a face para cima que você controla forem destruídos em batalha ou por um efeito de card: você pode escolher 1 desses monstros; Invoque-o por Invocação-Especial. \r\nVocê só pode usar este efeito de "Planeta Pacífico Calarium" uma vez por turno. \r\nVocê só pode ativar 1 "Planeta Pacífico Calarium" por turno.','\r',char(13)),'\n',char(10)),'Adicionar 1 monstro do seu Deck à sua mão?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82466274,'Serziel, a Observadora do Olho Maligno',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode adicionar 1 card "Olho Maligno" do seu Deck à sua mão, exceto "Serziel, a Observadora do Olho Maligno". \r\nSe este card estiver equipado com "Olho Maligno de Selene" (Efeito Rápido): você pode escolher 1 monstro Invocado por Invocação-Especial que seu oponente controla; destrua-o. \r\nVocê só pode usar este efeito de "Serziel, a Observadora do Olho Maligno" uma vez por turno. \r\nUma vez por turno, durante a próxima Fase de Apoio depois que este efeito foi ativado: destrua 1 card que você controla.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Destruir 1 monstro que seu oponente controla','Destruir 1 card que você controla','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82482194,'Escorpião Milênio','Cada vez que este card destrói 1 monstro no Campo do seu adversário como resultado de um combate, e o envia para o Cemitério, aumente o ATK deste card em 500 pontos.','Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82489470,'A Espadalma Dourada',replace(replace('Quando um monstro declarar um ataque: você pode Invocar este card por Invocação-Especial da sua mão e, se isso acontecer, negue o ataque e, depois, se você controlar um Monstro de Fusão que mencione "Caído de Arbaz" como matéria, você pode destruir o monstro que declarou esse ataque. \r\nSe um monstro for banido com a face para cima (exceto durante a Etapa de Dano): você pode banir este card do seu campo ou do Cemitério; Invoque por Invocação-Especial 1 monstro Mago de LUZ da sua mão ou do Cemitério cujo ATK seja igual à sua própria DEF. \r\nVocê só pode usar este efeito de "A Espadalma Dourada" uma vez por turno.','\r',char(13)),'\n',char(10)),'Destruir o monstro atacante?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82496097,'Ladrão do Tempo Nave Bisel',replace(replace('(Efeito Rápido): você pode oferecer este card como Tributo e, depois, escolha 1 Monstro Xyz "Ladrão do Tempo" que você controla; associe 1 card do Cemitério do seu oponente a esse monstro como matéria. \r\nSe este card estiver no Cemitério: você pode desassociar 1 matéria de um Monstro Xyz que você controla; Invoque este card por Invocação-Especial, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar cada efeito de "Ladrão do Tempo Nave Bisel" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82498947,'Defensor da Barreira de Gelo','Enquanto você controlar outro monstro "Barreira de Gelo", os monstros que seu oponente controla não podem declarar ataques se o ATK deles for igual ou maior que a DEF deste card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82529174,'Raio de Esperança',replace(replace('Adicione 2 monstros da LUZ do seu Cemitério ao seu Deck. \r\nEm seguida, embaralhe o seu Deck.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82542267,'Carniçal Violador de Túmulos','Escolha até 2 Cards de Monstros do Cemitério do seu adversário e remova-os do jogo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82556058,'Motor Demoníaco Ω',replace(replace('Durante sua Fase Final: Invoque por Invocação-Especial 1 "Ficha de Motor" (Tipo Máquina/TERRA/Nível 1/ATK 200/DEF 200) em Posição de Ataque. \r\nUma vez por turno: você pode fazer com que este card ganhe 1000 de ATK até a Fase Final. \r\nDurante a Fase Final, se este efeito deste card foi usado: destrua este card.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial 1 "Ficha de Motor"','Aumentar ATK','Destruir "Motor Demoníaco Ω"','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82556059,'Ficha de Motor','Invocado por Especial com o efeito "Motor Demoníaco Ω".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82562802,'Garra Cibersombria',replace(replace('Se este card for enviado para o Cemitério enquanto estiver equipado a um monstro: você pode escolher 1 monstro "Cibersombrio(a)" no seu Cemitério; adicione-o à sua mão. \r\nVocê só pode usar cada um dos seguintes efeitos de "Garra Cibersombria" uma vez por turno.\r\n● Você pode descartar este card; adicione 1 Magia/Armadilha "Cibersombrio(a)" do seu Deck à sua mão.\r\n● Durante o cálculo de dano, se um monstro equipado com este card batalhar: você pode enviar 1 monstro do seu Deck Adicional para o Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82566662,'Dragão Taotie',replace(replace('2+ monstros Invocados por Invocação-Especial do Deck Adicional	\r\nEste card ganha efeitos de acordo com o tipo de card (Fusão/Sincro/Xyz) das matérias usadas para sua Invocação-Link.\r\n● Fusão: Seu oponente não pode ativar efeitos de monstro durante a Fase de Batalha.\r\n● Sincro: Seu oponente não pode ativar Cards e efeitos de Magia/Armadilha durante sua Fase Principal.\r\n● Xyz: Seu oponente não pode ativar os efeitos de cards no Cemitério durante sua Fase Principal ou Fase de Batalha.','\r',char(13)),'\n',char(10)),'Usar um Monstro Fusão como Matéria de Link','Usar um Monstro Sincro como Matéria de Link','Usar um Monstro Xyz como Matéria de Link','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82570174,'Dragion Bidente Sangenpai',replace(replace('1 Regulador Dragão + 1+ monstros Dragão não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro: você pode escolher 1 monstro Dragão de FOGO no seu Cemitério; Invoque-o por Invocação-Especial e, além disso, você não pode Invocar por Invocação-Especial pelo resto deste turno, exceto monstros Dragão. \r\nSe 3 ou mais ataques foram declarados neste turno (Efeito Rápido): você pode Invocar este card por Invocação-Especial do seu Cemitério e, depois, você pode destruir 1 Magia/Armadilha no campo. \r\nVocê só pode usar este efeito de "Dragion Bidente Sangenpai" uma vez por Duelo, e seus efeitos anteriores apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Invocar este card por Invocação Especial do Cemitério','Destruir 1 Magia/Armadilha no campo?','Você já usou o efeito (2) de "Dragion Bidente Sangenpai"','','','','','','','','','','','','');
INSERT INTO texts VALUES(82579942,'Madoor Raio de Luz',replace(replace('Se 3 ou mais dos seus monstro de LUZ estiverem banidos, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nUma vez por turno, este card não pode ser destruído em batalha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82593786,'Salvador do Bacon',replace(replace('Durante a Etapa de Batalha de qualquer duelista, enquanto um ataque estiver acontecendo: você pode banir este card do seu Cemitério; negue o ataque. \r\nVocê só pode usar o efeito de "Salvador do Bacon" uma vez por Duelo.','\r',char(13)),'\n',char(10)),'Negar o ataque','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82616239,'Pequeno Dragão de Água',replace(replace('(Este card deve ser sempre considerado como "Dragão de Água".)	\r\nVocê pode banir este card que você controla; Invoque por Invocação-Especial 3 monstros Dinossauro de Nível 5 ou menos (de ÁGUA ou de VENTO) do seu Deck em Posição de Defesa (mas seus efeitos são negados) e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto monstros Dinossauro ou Serpente Marinha. \r\nVocê só pode usar este efeito de "Pequeno Dragão de Água" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82627406,'Pequena Maga Kiwi',replace(replace('Durante o turno de qualquer duelista: você pode descartar este card; até o final deste turno, monstros "Pequena Maga" que você controla atualmente ganham 300 de ATK e DEF para cada monstro "Pequena Maga" com nomes diferentes no campo e nos Cemitérios. \r\nMonstros do Tipo Mago que você controla não podem ser destruídos por efeitos de card e seu oponente não pode escolhê-los como alvo de efeitos de card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82633039,'Castel, o Mosqueteiro Destruidor Celeste',replace(replace('2 monstros de Nível 4	\r\nVocê pode desassociar 1 matéria deste card e, depois, escolha 1 monstro com a face para cima no campo; coloque-o com a face para baixo em Posição de Defesa. \r\nVocê pode desassociar 2 matérias deste card e, depois, escolha 1 outro card com a face para cima no campo; embaralhe-o no Deck. \r\nVocê só pode usar 1 efeito de "Castel, o Mosqueteiro Destruidor Celeste" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Mudar para Posição de Defesa com a face para baixo','Retornar ao Deck do dono','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82633308,'Sobrecarga Psíquica','Escolha 3 monstros do Tipo Psíquico no seu Cemitério; embaralhe os 3 no Deck e, depois, compre 2 cards.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82639107,'Converter Contato','Se você não controlar nenhum monstro: envie 2 monstros "Neoespacial" (1 da sua mão e 1 do seu Deck) para o Cemitério e, depois, compre 2 cards.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82642348,'Kryuel',replace(replace('Quando este card é enviado para o Cemitério como resultado de um combate, lance uma moeda. \r\nSe você ganhar, destrua 1 monstro no Campo do seu adversário.','\r',char(13)),'\n',char(10)),'Jogar uma moeda','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82661461,'Valet Camarartista de Olhos Anômalos',replace(replace('Escala de Pêndulo = 8\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno, quando um monstro do oponente declarar um ataque: você pode fazer com que esse monstro do oponente perca 300 de ATK para cada Monstro Pêndulo com a face para cima no seu Deck Adicional.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode enviar 1 monstro "Camarartista" ou "Olhos Anômalos" do seu Deck para o Cemitério, exceto "Valet Camarartista de Olhos Anômalos" e, se isso acontecer, até o final deste turno, o Nível deste card se torna o mesmo que o desse monstro. \r\nVocê só pode usar este efeito de "Valet Camarartista de Olhos Anômalos" uma vez por turno. \r\nSe este card na Zona de Monstros for destruído: você pode colocar este card na sua Zona de Pêndulo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82661630,'Reino Ryu-Ge - Domínios Dino',replace(replace('Você só pode controlar 1 "Reino Ryu-Ge - Domínios Dino". \r\nMonstros "Ryu-Ge" que você controla ganham 300 de ATK. \r\nMonstros Pêndulo "Ryu-Ge", e monstros de Nível 10 ou mais cujo Tipo original seja Dinossauro, que você controla, ganham este efeito.\r\n● Uma vez por turno, quando um efeito de um monstro no campo com ATK menor que o deste card for ativado (Efeito Rápido): você pode colocar 1 Magia Contínua "Ryu-Ge" que você controla no fundo do Deck; negue a ativação.','\r',char(13)),'\n',char(10)),'','Negar a ativação (Reino Ryu-Ge - Domínios Dino)','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82670878,'Ogro da Tristeza Escarlate',replace(replace('Durante o turno do seu oponente, quando seu oponente declarar um segundo ataque direto durante a mesma Fase de Batalha, você pode Invocar este card por Invocação-Especial da sua mão. \r\nQuando fizer isso, o ATK e DEF deste card se tornam iguais ao ATK e DEF do primeiro monstro que atacou diretamente neste turno, se ele ainda estiver com a face para cima no campo. \r\nNo turno em que este card for Invocado por Invocação-Especial com este efeito, seu oponente não pode selecionar outros monstros além deste card como alvo de um ataque enquanto este card estiver com a face para cima no campo.','\r',char(13)),'\n',char(10)),'Invocação Especial','Alterar ATK/DEF','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82685480,'Fúria de Kairyu-Shin',replace(replace('Se "Umi" estiver no campo: escolha monstros que seu oponente controla, até o número de monstros de ÁGUA que você controla cujo Nível original seja 5 ou mais; destrua-os e, se isso acontecer, as zonas onde eles estavam não podem ser usadas até o final do próximo turno. \r\nVocê só pode ativar 1 "Fúria de Kairyu-Shin" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82692552,'Coralianektes, o Dragão Brilhante e Cintilante',replace(replace('Se este card é adicionado à sua mão, excepto por compra-lo: você pode revelar este card e 1 outro monstro ÁGUA na sua mão; Invoque-os por Invocação-Especial, também você não pode Invocar por Invocação-Especial pelo resto do turno, exceto monstros ÁGUA. \r\nVocê só pode usar este efeito de "Coralianektes, o Dragão Brilhante e Cintilante" uma vez por turno.\r\nEnquanto você controla "Umi", seu oponente não pode escolher Monstros Link ÁGUA que você controla com efeitos de cards.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82693042,'Esfera do Caos',replace(replace('Enquanto este card estiver com a face para cima no campo seu Atributo também é considerado como LUZ. \r\nUma vez por turno, este card não pode ser destruído em batalha. \r\nQuando este card for Invocado por Invocação-Tributo, você pode adicionar 1 monstro de Nível 3 do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82693917,'Senhora Fortuna do Vento',replace(replace('O ATK/DEF deste card se tornam seu Nível x 300. \r\nUma vez por turno, durante sua Fase de Apoio: aumente em 1 o Nível deste card (máx. 12). \r\nQuando este card for Invocado por Invocação-Normal: você pode destruir Magias/Armadilhas que seu oponente controla igual ao número de monstros "Senhora Fortuna" que você controla.','\r',char(13)),'\n',char(10)),'Aumentar o Nível','Destruir um Card de Magia/Armadilha','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82697249,'Número 59: Cozinheiro Tortuoso',replace(replace('2 monstros de Nível 4	\r\nEnquanto você não controlar nenhum outro card no campo, este card não é afetado por outros efeitos de card. \r\nUma vez por turno (Efeito Rápido): você pode desassociar 1 matéria deste card; destrua tantos outros cards que você controla quanto possível e, depois, até o final deste turno, este card ganha 300 de ATK para cada monstro destruído por este efeito e enviado para o Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82697428,'Bruxa Ginete, a HERÓI da Visão',replace(replace('Para Invocar este card por Invocação-Tributo com a face para cima, você pode oferecer como Tributo uma ou mais Armadilhas que você controla, assim como monstros. \r\nQuando este card for Invocado por Invocação-Normal: você pode destruir todas as Magias e Armadilhas que seu oponente controla. \r\nVocê não pode Invocar monstros por Invocação-Especial durante o turno em que você ativou este efeito, exceto monstros "HERÓI".','\r',char(13)),'\n',char(10)),'Invocação Tributo ao oferecer como Tributo um Card de Armadilha','Destrua todos os Cards de Magia/Armadilha que seu oponente controla','Continuar selecionando Cards de Armadilha para oferecer como Tributo?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82699999,'Live☆Gêmea Lil-la Doce',replace(replace('Quando seu oponente ativar um card ou efeito em resposta à ativação de um card ou efeito "Live☆Gêmea" seu (Efeito Rápido): você pode descartar este card; negue esse efeito do oponente. \r\nSe você controlar um monstro "Ki-sikil" e este card estiver no seu Cemitério: você pode Invocar este card por Invocação-Especial, mas enquanto ele estiver com a face para cima na Zona de Monstros, você não pode Invocar por Invocação-Especial do Deck Adicional, exceto monstros Demônio. \r\nVocê só pode usar cada efeito de "Live☆Gêmea Lil-la Doce" uma vez por turno.','\r',char(13)),'\n',char(10)),'Negar o efeito','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82705573,'Contra-explosão','Se um ou mais monstros de FOGO com a face para cima que você controla forem destruídos e enviados para o Cemitério: cause 500 de dano ao seu oponente.','Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82706696,'GMX - VELOX',replace(replace('1 monstro "GMX" + 1 monstro Dinossauro	\r\nSempre que seu oponente Invocar um ou mais monstros por Invocação-Normal ou Especial, ganhe 200 PV. \r\nDurante o turno do seu oponente (Efeito Rápido): você pode escolher 1 card que seu oponente controla; escave cards do topo do seu Deck até escavar um monstro "GMX" ou um monstro Dinossauro, perca 400 PV para cada card escavado, adicione esse monstro "GMX" ou Dinossauro à sua mão ou Invoque-o por Invocação-Especial e embaralhe o resto no Deck. \r\nAlém disso, depois, destrua o card alvo. \r\nVocê só pode usar este efeito de "GMX - VELOX" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Efeito de destruição','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82732705,'Drenar Habilidades',replace(replace('Ative este card ao pagar 1000 PV. \r\nNegue os efeitos de todos os monstros com a face para cima enquanto eles estiverem com a face para cima no campo (mas seus efeitos ainda podem ser ativados).','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82734805,'Infernoide Tierra',replace(replace('"Infernoide Onuncu" + "Infernoide Devyaty" + 1+ monstros "Infernoide"	\r\nQuando este card for Invocado por Invocação-Fusão, você pode: aplicar esses efeitos, em sequência, de acordo com o número de matérias com nomes diferentes usadas para a Invocação deste card;\r\n● 3+: Cada duelista envia 3 cards do seu Deck Adicional para o Cemitério.\r\n● 5+: Cada duelista envia os 3 cards do topo do seu Deck para o Cemitério.\r\n● 8+: Cada duelista devolve até 3 dos seus cards banidos para o Cemitério.\r\n● 10+: Cada duelista envia toda a sua mão para o Cemitério.','\r',char(13)),'\n',char(10)),'Envie 3 cards do Deck Adicional para o Cemitério','Enviar o(s) 3 card(s) do topo do seu Deck para o Cemitério','Retornar até 3 dos seus cards banidos para o Cemitério','Envie toda a sua mão para o Cemitério','','','','','','','','','','','','');
INSERT INTO texts VALUES(82735249,'Ensaio Geral',replace(replace('Sempre que um efeito de um card "Guerreiro Sinfônico" for ativado, coloque 1 Marcador Sinfônico neste card quando esse efeito resolver. \r\nVocê só pode usar cada um dos seguintes efeitos de "Ensaio Geral" uma vez por turno. \r\nVocê pode remover 3 Marcadores Sinfônicos do seu campo; adicione 1 monstro "Guerreiro Sinfônico" do seu Deck à sua mão. \r\nSe você Invocar um ou mais monstros "Guerreiro Sinfônico" por Invocação-Normal ou Especial (exceto durante a Etapa de Dano): você pode adicionar 1 "Sinfo Amplificardor" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82738008,'Marcado em Vermelho',replace(replace('Escolha 1 monstro "Despia" ou "Caído de Arbaz" no seu Cemitério; adicione-o à sua mão e, depois, você pode aplicar o seguinte efeito.\r\n● Invoque por Invocação-Fusão 1 Monstro de Fusão de Nível 8 ou mais do seu Deck Adicional, ao banir as Matérias de Fusão mencionadas nele da sua mão ou do campo, mas ele não pode atacar diretamente neste turno.	\r\nVocê só pode ativar 1 "Marcado em Vermelho" por turno.','\r',char(13)),'\n',char(10)),'Realizar uma Invocação Fusão?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82738277,'Armadilhatrix Louva-a-deus',replace(replace('Não é afetado pelos efeitos de Armadilhas Normais "Buraco". \r\nQuando este card for Invocado por Invocação-Normal: você pode adicionar 1 monstro "Armadilhatrix" do seu Deck à sua mão. \r\nUma vez por turno (Efeito Rápido): você pode escolher 1 Magia/Armadilha Baixada que você controla; devolva o alvo para a mão e, depois, você pode Baixar 1 Magia/Armadilha da sua mão.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Retornar para a mão','Baixar uma Magia/Armadilha?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82742611,'Serpente Saqueadora','Uma serpente com apenas um olho que causa calafrios nos inimigos e os fazem congelar imediatamente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82744076,'Goma Reguladora',replace(replace('Você pode escolher 1 monstro com a face para cima que você controla; esse monstro com a face para cima é considerado como um Regulador neste turno. \r\nVocê só pode usar este efeito de "Goma Reguladora" uma vez por turno. \r\nDurante o turno em que você ativar este efeito, você só pode atacar com Monstros Sincro. \r\nDurante o turno de qualquer duelista, quando um card ou efeito for ativado que escolha como alvo exatamente 1 Monstro Sincro que você controla (e nenhum outro card): você pode banir este card do seu Cemitério; negue a ativação.','\r',char(13)),'\n',char(10)),'Considerar como um Regulador','Negue a ativação do efeito','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82760689,'Nuvem da Sorte','Durante a Fase Final, se você Invocou 2 ou mais monstros "Nuviano" com o mesmo nome neste turno, compre 2 cards.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82768499,'Golpe da Chama Espiral',replace(replace('Ative 1 desses efeitos;\r\n● Se você controlar um card "Olhos Anômalos": escolha 1 card no campo; destrua-o.\r\n● Adicione à sua mão 1 monstro "Olhos Anômalos" de Nível 7 do seu Deck ou 1 Monstro Pêndulo "Olhos Anômalos" de Nível 7 com a face para cima do seu Deck Adicional.','\r',char(13)),'\n',char(10)),'Destruir 1 card','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82773292,'Senhora Obscura Saciada',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode pegar 2 monstros "Senhor(a) Obscuro(a)" com Níveis diferentes da sua mão ou do Deck, exceto "Senhora Obscura Saciada", Invocar por Invocação-Especial 1 deles no campo do seu oponente em Posição de Defesa e adicionar o outro à sua mão e, além disso, você não pode ativar efeitos de monstro pelo resto deste turno, exceto monstros Fada. \r\nVocê só pode usar este efeito de "Senhora Obscura Saciada" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82777208,'Gelojade Acti',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode enviar 1 monstro de ÁGUA da sua mão para o Cemitério; compre 1 card. \r\nSe um ou mais monstros de ÁGUA com a face para cima que você controla forem destruídos em batalha ou por um efeito de card, enquanto este card estiver no seu Cemitério: você pode banir este card; Invoque por Invocação-Especial 1 monstro "Gelojade" da sua mão ou do Cemitério, exceto "Gelojade Acti". \r\nVocê só pode usar cada efeito de "Gelojade Acti" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82782870,'Mitsurugi no Mikoto, Kusanagi',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial, ou se este card for oferecido como Tributo: você pode escolher 1 card "Mitsurugi" no seu Cemitério ou banimento, exceto "Mitsurugi no Mikoto, Kusanagi"; adicione-o à sua mão. \r\nSe um ou mais outros monstros Réptil que você controla seriam destruídos em batalha ou por um efeito de card, em vez disso, você pode oferecer este card como Tributo. \r\nVocê só pode usar cada efeito de "Mitsurugi no Mikoto, Kusanagi" uma vez por turno.','\r',char(13)),'\n',char(10)),'Recuperar','Substituição de destruição','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82791472,'Guerreiros Antigos - Rebelde Lu Feng',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao controlar o monstro "Guerreiros Antigos" de maior ATK no campo (mesmo se empatado). \r\nVocê só pode Invocar "Guerreiros Antigos - Rebelde Lu Feng" por Invocação-Especial uma vez por turno desta forma. \r\nUma vez por turno, durante a Fase Principal (Efeito Rápido): você pode destruir o 1 monstro com a face para cima que seu oponente controla com o maior ATK (em caso de empate, você seleciona) e, além disso, você não pode ativar efeitos de monstro no turno em que ativar este efeito, exceto os de monstros "Guerreiros Antigos". \r\nUma vez por turno, durante a Fase Final, se seu oponente controlar um monstro com o maior ATK no campo (mesmo que haja empate): conceda o controle deste card ao seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82818645,'Espírito de Pedra','Embora pareça débil, este monstro é um dos mais poderosos espíritos de rocha.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82821760,'B.E.S. Núcleo Grande MK-3',replace(replace('Se seu oponente controlar um monstro e você não controlar nenhum monstro, você pode Invocar este card por Invocação-Especial (da sua mão) em Posição de Defesa. \r\nSe este card for Invocado por Invocação-Normal ou Especial: coloque 3 marcadores neste card. \r\nNão pode ser destruído em batalha. \r\nNo final da Etapa de Dano, se este card batalhou: remova 1 marcador deste card. \r\nSe não puder, destrua-o. \r\nVocê pode banir este card do seu Cemitério; embaralhe todos os monstros "B.E.S." do seu Cemitério no Deck.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82828051,'Tremor de Terra','Coloque em Posição de Defesa todos os monstros com a face para cima no campo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82832464,'Despertar de Nephthys',replace(replace('Todos os monstros "Nephthys" que você controla ganham 300 de ATK. \r\nSe este card com a face para cima na Zona de Magias & Armadilhas for destruído por um efeito de card e enviado para o Cemitério: você pode Invocar por Invocação-Especial 1 monstro "Nephthys" da sua mão, do Deck ou do Cemitério, mas destrua-o durante a Fase Final. \r\nVocê só pode usar este efeito de "Despertar de Nephthys" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82841979,'Divindade Yamato',replace(replace('Este card não pode ser Invocado por Invocação-Normal ou Baixado. \r\nEste card não pode ser Invocado por Invocação-Especial, exceto ao remover de jogo 1 monstro Espírito do seu Cemitério. \r\nEste card é devolvido para a mão de seu dono durante a Fase Final do turno em que ele for Invocado por Invocação-Especial. \r\nSe este card destruir um monstro do oponente em batalha, você pode destruir 1 Card de Magia ou Armadilha que seu oponente controla.','\r',char(13)),'\n',char(10)),'Retornar à mão','Destruir Magias/Armadilhas','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82878489,'Palácio Brilhante',replace(replace('Equipe apenas em um monstro de LUZ. \r\nEle ganha 700 de ATK.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82886276,'Cinet Circuito',replace(replace('Escolha 1 Monstro Link "Firewall" que você controla; Invoque por Invocação-Especial qualquer número de monstros do seu Cemitério nas zonas de qualquer duelista linkadas a esse monstro. \r\nSe seus PV forem 2000 ou menos: você pode banir este card do seu Cemitério; devolva 1 Monstro Link "Firewall" do seu Cemitério para o seu Deck Adicional e, depois, você pode Invocar esse monstro por Invocação-Especial do seu Deck Adicional. \r\nVocê só pode usar cada efeito de "Cinet Circuito" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Invocar outro monstro por Invocação Especial?','','Invocar aquele monstro por Invocação Especial?','','','','','','','','','','','','');
INSERT INTO texts VALUES(82888408,'O Cerburrel Mitológico','Se este card for descartado para o Cemitério: Invoque-o por Invocação-Especial.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82896870,'Fofanimal Golfinho',replace(replace('Você pode escolher 1 "Vendedor de Brinquedos" no seu Cemitério; Baixe-o e, se isso acontecer, envie 1 monstro "Fofanimal" ou 1 "Diabrete de Lâminas Afiadas" do seu Deck para o Cemitério. \r\nSe este card for enviado para o Cemitério como Matéria de Fusão para uma Invocação-Fusão: você pode embaralhar no Deck, 1 das suas Magias "Fusão" ou "Polimerização" que estiverem banidas ou no seu Cemitério. \r\nVocê só pode usar cada efeito de "Fofanimal Golfinho" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82913020,'Constelar Caduceu',replace(replace('Se você controlar um monstro "Constelar", exceto "Constelar Caduceu": você pode Invocar este card por Invocação-Especial da sua mão. \r\nDurante sua Fase Principal: você pode adicionar 1 Magia/Armadilha "Constelar" do seu Deck à sua mão. \r\nVocê só pode usar cada um dos efeitos anteriores de "Constelar Caduceu" uma vez por turno. \r\nUm Monstro Xyz "Constelar" que tenha este card como matéria ganha este efeito.\r\n● Se este card batalhar um monstro de LUZ ou de TREVAS, antes do cálculo de dano: você pode banir esse monstro.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82933935,'Flor Mimicarniçal',replace(replace('VIRE: Se for a Fase Principal: aplique esses efeitos em sequência.\r\n● Seu oponente pode adicionar 1 monstro de Virar ou 1 card "Mimicarniçal" do Deck dele à mão dele.\r\n● Conceda o controle deste card ao seu oponente.	\r\nDurante sua Fase Principal: você pode Invocar este card por Invocação-Especial da sua mão no campo do seu oponente com a face para baixo em Posição de Defesa, ou se um monstro com a face para baixo estiver no campo, você pode Invocar este card por Invocação-Especial com a face para cima no seu campo. \r\nVocê só pode usar cada efeito de "Flor Mimicarniçal" uma vez por turno.','\r',char(13)),'\n',char(10)),'Efeito de Virar','Invocação Especial','Invocar por Invocação Especial para o seu Campo','Invocar por Invocação Especial para o Campo do seu oponente','Adicionar este card à mão?','','','','','','','','','','','');
INSERT INTO texts VALUES(82944432,'Ninja da Armadura de Lâminas',replace(replace('2 monstros de Nível 4 do Tipo Guerreiro	\r\nUma vez por turno: você pode desassociar 1 Matéria Xyz deste card para escolher 1 monstro "Ninja" que você controla; ele pode realizar um segundo ataque durante cada Fase de Batalha neste turno.','\r',char(13)),'\n',char(10)),'Atacar duas vezes','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82946847,'Petiteranodon','Se este card for destruído por um efeito de card e enviado para o Cemitério: Invoque por Invocação-Especial 1 monstro Dinossauro de Nível 4 ou mais do seu Deck, mas ele não pode atacar neste turno.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82956214,'Punição Dogmatika',replace(replace('Escolha 1 monstro com a face para cima que seu oponente controla; envie 1 monstro com ATK igual ou maior que o dele do seu Deck Adicional para o Cemitério e, se isso acontecer, destrua esse monstro. \r\nAté o final do seu próximo turno depois que este card resolver, você não pode Invocar por Invocação-Especial do Deck Adicional. \r\nVocê só pode ativar 1 "Punição Dogmatika" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82956492,'D/D/D d''Arc, o Rei Oráculo',replace(replace('2 monstros "D/D"	\r\nQualquer efeito que causaria dano a você, em vez disso, faz com que você ganhe esse tanto de PV.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82962242,'Vampira Vamp',replace(replace('Uma vez por turno, quando este card ou um monstro "Vampiro(a)" for Invocado por Invocação-Normal no seu campo: você pode escolher 1 monstro que seu oponente controla cujo ATK seja maior que o deste card; equipe-o a este card. \r\nGanha ATK igual ao ATK original combinado dos monstros equipados a ele por este efeito. \r\nSe este card for enviado para o Cemitério enquanto estiver equipado com um ou mais cards por este efeito: Invoque este card por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Equipar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82970905,'Urso Pai',replace(replace('Quando este card é destruído por batalha e enviado para o Cemitério: você pode Invocar por Invocação-Especial 1 monstro de Nível 4 com 1400 de ATK do seu Deck, ou se você tem 2 ou mais monstros de Nível 4 com 1400 de ATK no seu Cemitério, em vez disso você pode Invocar por Invocação-Especial 1 Monstro Normal.\r\nQuando seu oponente ativar um efeito de monstro e você controla um Monstro sem efeito com a face ara cima (Efeito Rápido): você pode banir este card do seu Cemitério; negue a ativação, e se fizer, destrua aquele monstro. \r\nVocê só pode usar este efeito de "Urso Pai" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Negar a ativação','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82971335,'Senhora Fortuna da Terra',replace(replace('O ATK/DEF deste card se tornam seu Nível x 400. \r\nUma vez por turno, durante sua Fase de Apoio: aumente em 1 o Nível deste card (máx. 12). \r\nSe o Nível deste card aumentar: cause 400 de dano ao seu oponente.','\r',char(13)),'\n',char(10)),'Aumentar o Nível','Causar dano','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82977464,'Espécime Força-S',replace(replace('Se seu oponente controlar um monstro: escolha 1 dos seus monstros "Força-S" que estiverem banidos ou no seu Cemitério; Invoque-o por Invocação-Especial no seu campo na mesma coluna que um monstro do oponente. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 monstro "Força-S" que você controla; mova o alvo para outra das suas Zonas de Monstros Principais. \r\nVocê só pode usar 1 efeito de "Espécime Força-S" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Escolha 1 monstro para mover','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82983267,'Salto da Purrely!?',replace(replace('Escolha 1 Monstro Xyz "Purrely" que você controla; Invoque por Invocação-Especial do seu Deck Adicional, 1 Monstro Xyz "Purrely" com uma Classe diferente, usando o alvo como matéria, mas devolva-o para o Deck Adicional durante a Fase Final do próximo turno. \r\n(Isso é considerado uma Invocação-Xyz. Transfira as matérias dele para o monstro Invocado.) \r\nVocê pode banir este card do seu Cemitério e, depois, escolha até 3 monstros "Purrely" no seu Cemitério; embaralhe-os no Deck. \r\nVocê só pode ativar 1 "Salto da Purrely!?" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82994509,'Cavalinha',replace(replace('Quando este card for destruído em batalha e enviado para o Cemitério, Invoque por Invocação-Especial 1 "Ficha de Cavalinha" (Tipo Planta/VENTO/Nível 1/ATK 0/DEF 0) no lado do campo do seu oponente em Posição de Defesa. \r\nQuando esta Ficha for destruída em batalha com um monstro do Tipo Planta, seu controlador envia 1 card da mão dele para o Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82994510,'Ficha de Cavalinha','Invocado por Especial com o efeito "Cavalinha". Quando esta Ficha for destruída em batalha por um monstro Tipo Planta, seu controlador enviará 1 card da mão dele ao Cemitério.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82997779,'Usurpação do Arquidemônio',replace(replace('Ative 1 desses efeitos;\r\n● Baixe 1 Armadilha "Arquidemônio" do seu Deck ou Cemitério.	\r\nEla pode ser ativada neste turno.\r\n● Invoque por Invocação-Ritual 1 Monstro de Ritual "Arquidemônio" da sua mão ou do Deck Adicional com a face para cima, ao oferecer monstros como Tributo da sua mão ou do campo cuja soma dos Níveis seja igual ou exceda seu Nível.	\r\nVocê só pode ativar 1 "Usurpação do Arquidemônio" por turno.','\r',char(13)),'\n',char(10)),'Baixar','Invocação Ritual','Ativar aplicando o efeito de "Usurpação do Arquidemônio".','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82999629,'Umiiruka','Aumente em 500 o ATK de todos os monstros de ÁGUA e diminua em 400 suas DEF.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83008724,'Captura do Dia do Naviushi Gunkan',replace(replace('Uma vez por turno: você pode revelar 1 "Shari do Naviushi Gunkan" na sua mão; coloque 1 marcador neste card e, se isso acontecer, revele 1 Monstro Xyz "Gunkan" do seu Deck Adicional, e seu oponente declara 1 nome de card de monstro "Gunkan", exceto "Shari do Naviushi Gunkan", que seja mencionado em qualquer Monstro Xyz "Gunkan" e, depois, você adiciona esse card declarado do seu Deck à sua mão. \r\nSe não puder adicionar, embaralhe este card no Deck. \r\nSe este card em posse do seu dono for destruído por um card do oponente: seu oponente paga exatamente 500 PV para cada marcador neste card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83011277,'Tomate Místico','Quando este card for destruído em batalha e enviado para o Cemitério: você pode Invocar por Invocação-Especial 1 monstro de TREVAS com 1500 ou menos de ATK do seu Deck, com a face para cima em Posição de Ataque.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83011278,'Tomate Místico','Quando este card for destruído em batalha e enviado para o Cemitério: você pode Invocar por Invocação-Especial 1 monstro de TREVAS com 1500 ou menos de ATK do seu Deck, com a face para cima em Posição de Ataque.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83021423,'Arqueiro Chachaka','Uma vez por turno: você pode escolher 1 Card de Magia/Armadilha no campo; destrua-o.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83027236,'Luz da Destruição','Quando um efeito de card do oponente enviar um ou mais cards do Deck dele ao Cemitério, envie os 3 cards do topo do Deck dele ao Cemitério.','Enviar do Deck para o Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83032858,'Sabrelemento Aina',replace(replace('Uma vez por turno: você pode enviar 1 monstro "Sabrelemento" da sua mão para o Cemitério e, depois, escolher 1 monstro "Sabrelemento" (exceto "Sabrelemento Aina") ou monstro "Senhor Elemental" (que tenha sido Invocado corretamente) no seu Cemitério; Invoque-o por Invocação-Especial, ignorando suas condições de Invocação. \r\nUma vez por turno, se este card estiver no Cemitério: você pode declarar 1 Atributo; este card no Cemitério se torna desse Atributo até o final deste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83035296,'Maginista Megístrico',replace(replace('Sempre que um Card de Magia for ativado, coloque 1 Marcador de Magia neste card quando essa Magia resolver. \r\nDurante a Fase Final: você pode remover 3 Marcadores de Magia deste card e, depois, escolher 1 das suas Magias banidas; adicione 1 card com o nome do alvo do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Maginista Megístrico" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83039608,'Abanc, o Mitológico',replace(replace('Se este card estiver no seu Cemitério: você pode descartar 1 monstro "Mitológico(a)" e, se isso acontecer, Invoque este card por Invocação-Especial, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar este efeito de "Abanc, o Mitológico" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83039729,'Grão-mestre dos Seis Samurai',replace(replace('Você só pode controlar 1 "Grão-mestre dos Seis Samurai". \r\nSe você controlar um monstro "Seis Samurai", você pode Invocar este card por Invocação-Especial (da sua mão). \r\nSe este card em sua posse for destruído por um efeito de card do oponente: escolha 1 monstro "Seis Samurai" no seu Cemitério; adicione o alvo à sua mão.','\r',char(13)),'\n',char(10)),'Recuperar do Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83048208,'Inseto Digital LEDizinha',replace(replace('Não pode ser usado como uma Matéria Xyz para uma Invocação-Xyz, exceto para a Invocação-Xyz de um monstro Inseto. \r\nUma vez por turno, quando este card com a face para cima for mudado de Posição de Ataque para Posição de Defesa: você pode adicionar 1 monstro do Tipo Inseto de Nível 3 do seu Deck à sua mão. \r\nUm Monstro Xyz que foi Invocado usando este card no campo como Matéria Xyz ganha este efeito.\r\n● Quando este card destruir um monstro em batalha, compre 1 card.','\r',char(13)),'\n',char(10)),'Procurar no Deck','O efeito de "Inseto Digital LEDizinha" está sendo aplicado.','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83054225,'Decolar!! Decolar!!',replace(replace('Se o número de monstros do seu oponente no campo for maior que o número dos seus monstros não-Fichas no campo: ofereça como Tributo qualquer número de "Fichas de Besta Fantasma Mecha"; Invoque por Invocação-Especial o mesmo número de monstros "Besta Fantasma Mecha" do seu Deck. \r\nEmbaralhe-os no Deck durante a Fase Final. \r\nVocê só pode ativar 1 "Decolar!! Decolar!!" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83061014,'Numen erat Testudo','Nenhum duelista pode Invocar por Invocação-Especial monstros com 1800 ou menos de ATK.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83094004,'Trifaderóbica',replace(replace('Uma vez por turno (Efeito Rápido): você pode escolher 1 monstro com a face para cima que seu oponente controla na coluna deste card; mova este card que você controla para outra das suas Zonas de Monstros Principais e, se isso acontecer, mova esse monstro do oponente para uma Zona de Monstros Principal dele na coluna deste card e, depois, coloque 1 Marcador de Queimadura nele. \r\n(Monstros com Marcadores de Queimadura perdem 200 de ATK/DEF para cada Marcador de Queimadura nele.)','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83102080,'Tornado Paralelo','Envie 1 outro Card de Magia/Armadilha que você controla para o Cemitério e, depois, escolha 1 card no campo; destrua-o.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83104731,'Golem do Mecanismo Antigo',replace(replace('Não pode ser Invocado por Invocação-Especial. \r\nSe este card atacar, seu oponente não pode ativar quaisquer Cards de Magia/Armadilha até o final da Etapa de Dano. \r\nSe este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83107873,'Águiadragão do Trovão',replace(replace('Você pode descartar este card; Invoque por Invocação-Especial 1 dos seus monstros "Dragão do Trovão" que estiverem banidos ou no seu Cemitério, exceto "Águiadragão do Trovão". \r\nSe este card for banido ou enviado do campo para o Cemitério: você pode embaralhar no Deck qualquer número de cards da sua mão e, depois, compre o mesmo número de cards. \r\nVocê só pode usar 1 efeito de "Águiadragão do Trovão" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83108603,'Pilar Nebuloso',replace(replace('Você pode Invocar por Invocação-Normal monstros "Chama Nebulosa" oferecendo 1 Tributo a menos. \r\nUma vez por turno: você pode escolher 1 Monstro Xyz com a face para cima que você controla; associe 1 monstro "Chama Nebulosa", da sua mão ou do seu lado do campo, a esse Monstro Xyz como uma Matéria Xyz.','\r',char(13)),'\n',char(10)),'Associar material','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83116692,'Psicopompo, o Portador da Perdição',replace(replace('Se este card for Invocado por Invocação-Especial: aplique este efeito, baseado em se seu oponente tem mais monstros ou mais Magias & Armadilhas no Cemitério dele. \r\n(Se ele tiver mais monstros, bana este card e, se isso acontecer, seu oponente bane 1 monstro do Cemitério dele. Se ele tiver mais Magias & Armadilhas, envie este card para o Cemitério e, se isso acontecer, seu oponente envia 1 monstro que ele controla para o Cemitério.) \r\nDurante a Fase Final do próximo turno depois que este card foi banido: você pode Invocar este card banido por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Psicopompo, o Portador da Perdição" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83121692,'Temporal, o HERÓI do Elemento',replace(replace('"Aviário, o HERÓI do Elemento" + "Sparkman, o HERÓI do Elemento" + "Homem Bolha, o HERÓI do Elemento"	\r\nDeve ser Invocado por Invocação-Fusão. \r\nVocê pode enviar 1 outro card que você controla para o Cemitério e, depois, escolha 1 monstro que você controla; enquanto este card estiver com a face para cima no campo, esse monstro não pode ser destruído em batalha.','\r',char(13)),'\n',char(10)),'Não pode ser destruído','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83133491,'Gravidade Zero','Mude a posição de batalha de todos os monstros com a face para cima no campo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83135907,'Goblin de Restolhos',replace(replace('Não pode ser destruído em batalha. \r\nNo final da Fase de Batalha, se este card com a face para cima em Posição de Defesa for escolhido como alvo de um ataque: destrua este card. \r\nSe este card for destruído pelo efeito de um card "Restolhos" e enviado para o Cemitério: você pode escolher 1 monstro "Restolhos" no seu Cemitério, exceto "Goblin de Restolhos"; adicione o alvo à sua mão.','\r',char(13)),'\n',char(10)),'Destruir este card','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83152482,'Portador da União',replace(replace('2 monstros com o mesmo Tipo ou Atributo	\r\nNão pode ser usado como Matéria Link no turno em que for Invocado por Invocação-Link. \r\nVocê pode escolher 1 monstro com a face para cima que você controla; equipe 1 monstro da sua mão ou do Deck a ele com seu mesmo Tipo ou Atributo original. \r\nO monstro equipado ganha 1000 de ATK. \r\nSe você o equipou com um card do Deck, pelo resto deste turno, você não pode Invocar monstros por Invocação-Especial com o nome desse Card de Equipamento. \r\nVocê só pode usar este efeito de "Portador da União" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83190280,'Tigresa Luzlunar',replace(replace('Escala de Pêndulo = 5\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno: você pode escolher 1 monstro "Luzlunar" no seu Cemitério; Invoque-o por Invocação-Especial, mas ele não pode atacar, seus efeitos são negados e, além disso, ele é destruído durante a Fase Final.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe este card no campo for destruído em batalha ou por um efeito de card: você pode escolher 1 monstro "Luzlunar" no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê só pode usar este efeito de "Tigresa Luzlunar" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83195035,'Retorno do Dragão da Tempestade',replace(replace('Escolha 1 monstro banido; Invoque-o por Invocação-Especial no seu campo, mas devolva-o para a mão durante a Fase Final. \r\nVocê só pode ativar 1 "Retorno do Dragão da Tempestade" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83199011,'Chamado Springans!',replace(replace('Escolha 1 monstro "Springans" ou "Caído de Arbaz" no seu Cemitério; Invoque-o por Invocação-Especial. \r\nDurante a Fase Principal, exceto no turno em que este card foi enviado para o Cemitério: você pode banir este card e 1 Monstro de Fusão no seu Cemitério e, depois, escolha 1 Monstro Xyz "Springans" que você controla; associe 1 Monstro de Fusão, que liste "Caído de Arbaz" como matéria, do seu Deck Adicional a esse monstro como matéria. \r\nVocê só pode usar cada efeito de "Chamado Springans!" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83203672,'Springans Branga',replace(replace('Se este card estiver na sua mão, no campo ou no Cemitério: você pode escolher 1 Monstro Xyz "Springans" que você controla; associe este card a ele como matéria. \r\nVocê pode banir este card e 1 monstro "Springans" com um nome diferente do seu Cemitério; adicione 1 card "Springans" do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "Springans Branga" uma vez por turno.','\r',char(13)),'\n',char(10)),'Associar Matéria Xyz','Procurar no Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83225447,'Poção de Estimulação',replace(replace('O monstro equipado ganha 700 de ATK. \r\nDurante cada uma das suas Fases de Apoio, o monstro equipado perde 200 de ATK.','\r',char(13)),'\n',char(10)),'Reduzir ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83228073,'Duas Mil Agulhas','Quando este card, em Posição de Defesa, é atacado e o ATK do monstro atacante é menor que o DEF deste card, depois do cálculo de dano destrúa o monstro atacante.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83232904,'Malabarismo da Companhia de Palhaços',replace(replace('Invoque por Invocação-Especial até 2 monstros "Companhia de Palhaços" do seu Deck e/ou Deck Adicional, ignorando suas condições de Invocação e, além disso, até o final do próximo turno depois que este card resolver, você não pode ativar os efeitos de monstros Invocados por Invocação-Especial do Deck ou Deck Adicional. \r\nDurante sua Fase Principal, se este card estiver no seu Cemitério, exceto no turno em que foi enviado para lá: você pode banir este card e oferecer como Tributo 1 monstro da sua mão ou do campo e, depois, escolha 1 card no campo; devolva-o para a mão. \r\nVocê só pode usar cada efeito de "Malabarismo da Companhia de Palhaços" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Retornar para a mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83235263,'Tyranno Infinito','O ATK original deste card é igual ao número dos seus monstros do Tipo Dinossauro banidos x 1000.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83236601,'Ataqueraptor - Lanius Tributo',replace(replace('Durante sua Fase Principal, se este card foi Invocado por Invocação-Normal ou Especial neste turno: você pode enviar 1 card "Ataqueraptor" do seu Deck para o Cemitério. \r\nDurante sua Fase Principal 2, se este card destruiu um monstro do oponente em batalha neste turno: você pode adicionar 1 Magia Rápida "Magia de Aumento de Classe" do seu Deck à sua mão e, além disso, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros "Ataqueraptor". \r\nVocê só pode usar cada efeito de "Ataqueraptor - Lanius Tributo" uma vez por turno.','\r',char(13)),'\n',char(10)),'Enviar para o Cemitério','Procurar no Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83239739,'Meister Ostra','Se este card for enviado do campo para o Cemitério, exceto quando destruído em batalha: Invoque por Invocação-Especial 1 "Ficha de Ostra" (Peixe/ÁGUA/Nível 1/ATK 0/DEF 0).','Invocar uma Ficha por Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83239740,'Ficha de Ostra','Invocado por Especial com o efeito "Meister Ostra".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83241722,'Re-Lançamento do Dado',replace(replace('Uma vez durante o restante deste turno, se qualquer duelista lançar um dado (ou dados), você pode fazer com que o(s) duelista(s) lance(m) novamente. \r\n(Você só pode se aproveitar deste efeito uma vez por turno.)','\r',char(13)),'\n',char(10)),'Rolar o dado novamente 1 vez?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83257450,'O Imparável Exodia Encarnado',replace(replace('5 monstros "O Proibido"	\r\nNão pode ser destruído por efeitos de card do oponente. \r\nUma vez por turno, se este card batalhar, durante o cálculo de dano: você pode fazer com que este card ganhe ATK igual aos seus PV. \r\nUma vez por turno, quando um Card de Magia/Armadilha ou seus efeitos forem ativados (Efeito Rápido): você pode negar essa ativação. \r\nUma vez por turno, durante a Fase Final: você pode Baixar 1 Magia/Armadilha "Exodd" ou "Obliterar!!!" do seu Deck. \r\nUma vez por turno, durante sua Fase de Apoio: perca 1000 PV.','\r',char(13)),'\n',char(10)),'Aumentar ATK','Negar o efeito','Baixar Magia/Armadilha','Perder PV','','','','','','','','','','','','');
INSERT INTO texts VALUES(83258273,'Zumbi Larápio','Se um monstro seu causar dano de batalha ao seu oponente: envie o card do topo do Deck dele para o Cemitério.','Enviar do Deck para o Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83266006,'Fantasma Encontra Garota - Um Manuscrito Mayakashi',replace(replace('Durante a Fase Principal: escolha 1 Monstro Sincro Zumbi que você controla; Invoque por Invocação-Especial 1 dos seus monstros Zumbi com o mesmo Atributo, que esteja banido ou no seu Cemitério, mas bana-o durante a Fase Final e, além disso, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno depois que este card resolver, exceto monstros Zumbi. \r\nVocê só pode ativar 1 "Fantasma Encontra Garota - Um Manuscrito Mayakashi" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83266092,'Túmulo do Organismo Super Antigo','Monstros de Nível 6 ou mais no campo, Invocados por Invocação-Especial, não podem declarar ataques, e os duelistas não podem ativar seus efeitos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83269557,'Valquíria Negra',replace(replace('Este card é considerado um Monstro Normal enquanto estiver com a face para cima no campo ou no Cemitério. \r\nEnquanto este card for um Monstro Normal no campo, você pode Invocá-lo por Invocação-Normal para fazer com que ele se torne um Monstro de Efeito com este efeito.\r\n● Uma vez, enquanto este card estiver com a face para cima no campo: você pode colocar 1 Marcador de Magia sobre ele.	\r\nEste card ganha 300 de ATK para cada Marcador de Magia sobre ele. \r\nVocê pode remover 1 Marcador de Magia deste card e, depois, escolher 1 monstro no campo; destrua o alvo.','\r',char(13)),'\n',char(10)),'Colocar Marcadores de Magia','Destrua 1 monstro no campo','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83272895,'Bachibachibachi',replace(replace('Um Monstro Xyz Invocado usando este card, no campo, como uma Matéria Xyz ganha este efeito.\r\n● Se este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente.','\r',char(13)),'\n',char(10)),'O efeito de "Bachibachibachi" está sendo aplicado.','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83274244,'Guerreiro Dododo',replace(replace('Você pode Invocar este card por Invocação-Normal sem oferecer Tributo, mas seu ATK original se torna 1800. \r\nSe este card atacar, até o final da Etapa de Dano, negue todos os efeitos de card que ativam no Cemitério do oponente.','\r',char(13)),'\n',char(10)),'Invocação Normal sem Tributo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83283063,'Shiranui Shogunsaga',replace(replace('1 Regulador do Tipo Zumbi + 1 ou mais monstros não-Reguladores do Tipo Zumbi	\r\nSe este card for Invocado por Invocação-Especial: você pode banir 1 monstro do Tipo Zumbi do seu Cemitério; até o final deste turno, este card ganha ATK igual ao ATK original do monstro banido. \r\nSe este card no campo for destruído em batalha ou por um efeito de card e enviado para o Cemitério: você pode escolher 1 dos seus monstros banidos do Tipo Zumbi com DEF 0; devolva-o para o Cemitério. \r\nVocê só pode Invocar um ou mais "Shiranui Shogunsaga" por Invocação-Especial uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83286340,'Caverguerra Fortia',replace(replace('Se um monstro Guerreiro de TERRA seu batalhar, depois do cálculo de dano: você pode adicionar 1 card "Caverguerra" do seu Deck à sua mão, exceto "Caverguerra Fortia" e, depois, todos os monstros "Caverguerra" que você controla atualmente ganham 200 de ATK até o final do turno do seu oponente. \r\nSe este card for enviado da sua Zona de Monstros para o seu Cemitério por um efeito de card do oponente: você pode Invocar por Invocação-Especial 1 monstro "Caverguerra" de Nível 5 ou mais da sua mão ou do Deck. \r\nVocê só pode usar cada efeito de "Caverguerra Fortia" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83289866,'Travessa Fazticeira',replace(replace('Na primeira vez que cada monstro "Fazticeira" que você controla seria destruído a cada turno, em batalha ou por um efeito de card, ele não é destruído. \r\nVocê só pode usar 1 dos seguintes efeitos de "Travessa Fazticeira" por turno e apenas uma vez por turno.\r\n● Se um monstro "Fazticeira" que você controla seria descartado para ativar um efeito, em vez isso, você pode enviar este card do seu campo para o Cemitério.\r\n● Durante sua Fase Final, se você controlar um monstro "Fazticeira", enquanto este card estiver no seu Cemitério: você pode colocar este card com a face para cima na sua Zona de Magias & Armadilhas.','\r',char(13)),'\n',char(10)),'Retornar ao Campo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83293307,'Receptor Krawler',replace(replace('VIRE: Você pode adicionar 1 monstro "Krawler" do seu Deck à sua mão.\r\nSe este card com a face para cima sob o controle do seu dono deixar o campo devido a um efeito de card do oponente: você pode Invocar por Invocação-Especial 2 monstros "Krawler" com nomes diferentes do seu Deck em Posição de Defesa com a face para baixo, exceto "Receptor Krawler". \r\nVocê só pode usar cada efeito de "Receptor Krawler" uma vez por turno.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Invoque 2 monstros por Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83293635,'Força do Sétimo','Durante a Fase de Batalha, se um ou mais monstros forem destruídos em batalha ou por um efeito de card: escolha 1 Monstro Xyz "Número" no seu Cemitério; Invoque por Invocação-Especial do seu Deck Adicional 1 monstro "Número C" com o mesmo Tipo mas 1 Classe maior e, se isso acontecer, associe esse monstro a ele como matéria e, depois, se você Invocar por Invocação-Especial um monstro "Número C" com um número entre "101" e "107" em seu nome, você pode adicionar 1 Magia/Armadilha "Sétimo" ou "de Barian", ou 1 Magia Rápida "Magia de Aumento de Classe", exceto "Força do Sétimo", do seu Deck à sua mão.','','Adicionar 1 carta do seu Deck à sua mão?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83295594,'Sincron de Vapor','Durante a Fase Principal do seu oponente, você pode (Efeito Rápido): imediatamente depois que este efeito resolver, Invoque por Invocação-Sincro usando este card que você controla.','Invocação Sincro','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83301414,'Feriado Fazticeira',replace(replace('Escolha 1 monstro "Fazticeira" no seu Cemitério; Invoque-o por Invocação-Especial. \r\nDurante sua Fase Final, se você controlar um monstro "Fazticeira", enquanto este card estiver no seu Cemitério: você pode adicionar este card à sua mão. \r\nVocê só pode usar 1 efeito de "Feriado Fazticeira" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83303851,'D/D/D Apocalipse, o Rei do Caos',replace(replace('Escala de Pêndulo = 4\r\n[ Efeito de Pêndulo ]\r\nVocê pode banir 2 monstros "D/D" do seu Cemitério; Invoque este card por Invocação-Especial da sua Zona de Pêndulo.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nDurante o turno do seu oponente, se este card estiver na sua mão ou no Cemitério: você pode escolher 2 Cards de Magia/Armadilha com a face para cima que você controla; você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros do Tipo Demônio e, além disso, destrua os cards escolhidos e, se isso acontecer, Invoque este card por Invocação-Especial (este é um Efeito Rápido). \r\nVocê só pode usar este efeito de "D/D/D Apocalipse, o Rei do Caos" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83308376,'Punição Espadalma',replace(replace('Se você controlar um Monstro Sincro: escolha 1 card no campo ou em qualquer Cemitério; bana-o. \r\nSe seu oponente controlar um Monstro de Ritual, Fusão, Sincro, Xyz ou Link: você pode banir 1 Monstro Sincro do seu Cemitério; adicione este card do Cemitério à sua mão. \r\nVocê só pode usar cada efeito de "Punição Espadalma" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83315222,'Boxeador Obstinado Promotor',replace(replace('Se seu oponente controlar um monstro: você pode Invocar este card por Invocação-Especial da sua mão. \r\nVocê pode oferecer este card como Tributo; Invoque por Invocação-Especial até 2 monstros "Boxeador Obstinado" com nomes diferentes do seu Deck, exceto "Boxeador Obstinado Promotor". \r\nVocê pode banir este card do seu Cemitério; aumente ou diminua em 1 os Níveis de todos os monstros "Boxeador Obstinado" que você controla atualmente. \r\nVocê só pode usar cada efeito de "Boxeador Obstinado Promotor" uma vez por turno e, além disso, você não pode Invocar monstros por Invocação-Especial durante o turno em que ativar qualquer um dos efeitos deste card, exceto monstros "Boxeador Obstinado".','\r',char(13)),'\n',char(10)),'','','','Aumentar o Nível','Reduzir o Nível','','','','','','','','','','','');
INSERT INTO texts VALUES(83319154,'Aniquilar Luz Retrógrada',replace(replace('Quando seu oponente ativar um efeito de monstro no campo, exceto monstros que foram Invocados neste turno: negue a ativação e, depois, você pode banir (com a face para baixo) todos os monstros com a face para cima que seu oponente controla, exceto monstros Invocados neste turno. \r\nSe este card Baixado sob o controle do seu dono for destruído por um efeito de card do oponente: você pode Baixar 1 Armadilha do seu Deck.','\r',char(13)),'\n',char(10)),'Ativar','Baixar','Banir o monstro?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83319610,'Zenmaiday',replace(replace('Uma vez por turno: você pode escolher 1 Monstro Xyz do Tipo Máquina que você controla; associe 1 monstro "de Corda" da sua mão ou campo a esse monstro como uma Matéria Xyz. \r\nVocê pode enviar este card com a face para cima do campo para o Cemitério e, depois, escolher 1 Monstro Xyz "de Corda" que você controla; Invoque por Invocação-Especial, do seu Deck Adicional, 1 monstro "de Corda" que seja 1 Classe superior que o alvo, ao usar o alvo como Matéria Xyz. \r\n(Esta Invocação-Especial é considerada uma Invocação-Xyz. Matérias Xyz associadas ao alvo também se tornam Matérias Xyz no monstro Invocado.) \r\nVocê não pode ativar esses efeitos durante a mesma Corrente.','\r',char(13)),'\n',char(10)),'Use um monstro "de Corda" como Matéria Xyz','Invoque por Invocação Especial um monstro "de Corda" de 1 Ranking maior','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83326048,'Barragem Dimensional',replace(replace('Declare 1 tipo de card de monstro (Ritual, Fusão, Sincro, Xyz ou Pêndulo); pelo resto deste turno, nenhum duelista pode Invocar monstros do tipo declarado por Invocação-Especial e, além disso, negue os efeitos de todos os monstros desse tipo enquanto eles estiverem no campo. \r\nVocê só pode ativar 1 "Barragem Dimensional" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83334932,'Samurai Superpesado Motocicleta',replace(replace('Se você não tiver Magias/Armadilhas no seu Cemitério: você pode descartar este card; adicione 1 monstro "Samurai Superpesado" do seu Deck à sua mão, exceto "Samurai Superpesado Motocicleta". \r\nVocê só pode usar este efeito de "Samurai Superpesado Motocicleta" uma vez por turno. \r\nUma vez por turno: você pode escolher 1 monstro Máquina que você controla; aumente seu Nível em 2.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83340560,'O Elenco Duplo do Grande Conjurador',replace(replace('2 Monstros que não sejam de Efeito	\r\nGanha ATK igual ao ATK original combinado de quaisquer Monstros de Ritual, de Fusão, Sincro, Xyz ou Link usados como Matéria de Fusão para este card. \r\nEste card pode atacar diretamente. \r\nSe este card for destruído em batalha ou por um efeito de card: você pode escolher 1 dos seus Monstros que não sejam de Efeito que estiverem banidos ou no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê só pode usar este efeito de "O Elenco Duplo do Grande Conjurador" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83347294,'Dragão Lancer de Olhos Anômalos',replace(replace('Se um Monstro Pêndulo que você controla for destruído em batalha ou por um efeito de card: você pode oferecer 1 monstro como Tributo; Invoque este card por Invocação-Especial da sua mão. \r\nSe este card atacar, seu oponente não pode ativar quaisquer Cards de Magia/Armadilha até o final da Etapa de Dano. \r\nSe um ou mais cards "Olhos Anômalos" que você controla seriam destruídos em batalha ou por um efeito de card, em vez disso, você pode destruir 1 card "Olhos Anômalos" na sua mão, Zona de Monstros ou Zona de Pêndulo.','\r',char(13)),'\n',char(10)),'Invoque este card por Invocação Especial da sua mão','Usar o efeito de "Dragão Lancer de Olhos Anômalos" em vez de ser destruído?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83370323,'Rasgadaomei',replace(replace('Este card não pode ser usado como um Monstro Matéria Sincro, exceto para a Invocação-Sincro de um Monstro Sincro do Tipo Guerreiro. \r\nSe o Monstro Sincro que usou este card como um Monstro Matéria Sincro atacar, seu oponente não pode ativar Cards de Armadilha até o final da Etapa de Dano.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83392426,'Bicular','Quando este card for destruído em batalha e enviado ao Cemitério, você pode Invocar por Invocação-Especial 1 "Unicular" da sua mão ou Deck.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83404468,'O Trabalho do Normal',replace(replace('Aplique esses efeitos em sequência, de acordo com o número de Monstros Normais com nomes diferentes no seu Cemitério (pule qualquer um que não se aplique).\r\n● 1+: Neste turno, Monstros Normais que você controla ganham 800 de ATK.\r\n● 2+: Negue os efeitos de 1 Monstro de Efeito no campo, até o final deste turno.\r\n● 3+: Neste turno, Monstros Normais que você controla não podem ser destruídos por efeitos de card.\r\n● 4+: Embaralhe no Deck 1 Monstro de Efeito no campo.\r\n● 5+: Adicione 1 "O Trabalho do Normal" do seu Deck à sua mão.	\r\nVocê só pode ativar 1 "O Trabalho do Normal" por turno.','\r',char(13)),'\n',char(10)),'Ativar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83407038,'Investida Amazoness',replace(replace('Uma vez por turno, durante a Fase de Batalha: você pode Invocar por Invocação-Especial 1 monstro "Amazoness" da sua mão e, se isso acontecer, ele ganha 500 de ATK até o final deste turno (mesmo que este card deixe o campo). \r\nDepois do cálculo de dano, se um monstro "Amazoness" seu batalhou um monstro do oponente enquanto este card já estava com a face para cima na sua Zona de Magias & Armadilhas: você pode banir esse monstro do oponente. \r\nSe este card no campo for destruído e enviado para o Cemitério: você pode escolher 1 monstro "Amazoness" no seu Cemitério; Invoque-o por Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83414006,'Envenenador, o HERÓI da Visão',replace(replace('Se você sofrer dano de batalha ou de efeito enquanto este card estiver no seu Cemitério: você pode colocar este card do seu Cemitério na sua Zona de Magias & Armadilhas como uma Armadilha Contínua com a face para cima. \r\nDurante a Fase Principal, se este card for considerado como uma Armadilha Contínua: você pode oferecer como Tributo 1 monstro "HERÓI"; Invoque este card por Invocação-Especial. \r\nSe este card for Invocado por Invocação-Especial da Zona de Magias & Armadilhas: você pode diminuir pela metade o ATK de 1 monstro com a face para cima no campo. \r\nVocê só pode usar cada efeito de "Envenenador, o HERÓI da Visão" uma vez por turno.','\r',char(13)),'\n',char(10)),'Baixar este card como um Card de Armadilha Contínua','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83438826,'Armas Nobres - Arfeudutyr',replace(replace('Você só pode controlar 1 "Armas Nobres - Arfeudutyr". \r\nSó pode ser equipado a um monstro do Tipo Guerreiro. \r\nUma vez por turno: você pode escolher 1 card Baixado que seu oponente controla; o monstro equipado perde exatamente 500 de ATK e, se isso acontecer, destrua o alvo. \r\n(Esta perda de ATK permanece mesmo que este card deixe o campo ou que o monstro não possa mais ser afetado por efeitos de card.) \r\nSe este card com a face para cima no campo for destruído e enviado para o Cemitério: você pode escolher 1 monstro "Nobre Cavaleiro" do Tipo Guerreiro que você controla; equipe este card ao alvo. \r\nVocê só pode usar este efeito de "Armas Nobres - Arfeudutyr" uma vez por turno.','\r',char(13)),'\n',char(10)),'Destruir Magias/Armadilhas','Equipar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83443619,'Cristron Estigraçado',replace(replace('Você pode escolher 1 card com a face para cima que você controla; você não pode Invocar monstros por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto Monstros Sincro do Tipo Máquina e, além disso, destrua esse card e, se isso acontecer, Invoque por Invocação-Especial do seu Deck 1 monstro Regulador "Cristron". \r\nVocê pode banir este card do seu Cemitério; adicione 1 Card de Magia/Armadilha "Cristron" do seu Deck à sua mão. \r\nVocê só pode usar 1 efeito de "Cristron Estigraçado" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83445539,'Ressonador das Trevas',replace(replace('Você pode revelar 1 "Dragão Vermelho Arquidemônio" no seu Deck Adicional; Invoque este card por Invocação-Especial da sua mão e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto Monstros Sincro. \r\nSe este card for Invocado por Invocação-Especial: você pode ativar este efeito; durante sua Fase Principal neste turno, você pode Invocar por Invocação-Normal 1 monstro "Ressonador", em adição à sua Invocação-Normal/Baixar (padrão) (você só pode se aproveitar deste efeito uma vez por turno). \r\nVocê pode escolher qualquer número de Reguladores que você controla; mude o Nível deles para 1. \r\nVocê só pode usar cada efeito de "Ressonador das Trevas" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Invocação Normal adicional','Alterar o Nível','Invocar pelo efeito de "Ressonador das Trevas"','','','','','','','','','','','','');
INSERT INTO texts VALUES(83446909,'Carregador de Homem-Bateria',replace(replace('Quando este card for Invocado por Invocação-Normal, você pode Invocar por Invocação-Especial 1 monstro "Homem-Bateria", exceto "Carregador de Homem-Bateria", da sua mão ou Deck. \r\nEste card ganha 300 de ATK e DEF para cada monstro do Tipo Trovão que você controla.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83461421,'Tempestade Pêndulo','Destrua tantos cards nas Zonas de Pêndulo quanto possível e, depois, você pode destruir 1 Magia/Armadilha que seu oponente controla.','Destruir 1 Card de Magia/Armadilha que seu oponente controla?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83464209,'Ovelha Mística nº 2','Uma ovelha monstruosa que usa a sua longa cauda para hipnotizar seus inimigos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83467607,'Reflexo da Natureza','Durante este turno, qualquer efeito ativado pelo seu oponente que causaria dano se torna um efeito que causa dano aos PV dele.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83477829,'Legado Mundial - "Armadura Mundial"',replace(replace('Quando um monstro for Invocado por Invocação-Virar: você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 card "Legado Mundial" do seu Deck à sua mão. \r\nSe este card Invocado por Invocação-Normal/Baixado estiver no campo (Efeito Rápido): você pode escolher 1 monstro do oponente com a face para cima que foi Invocado por Invocação-Especial do Deck Adicional; devolva tanto esse monstro e este card para a mão. \r\nVocê só pode usar cada efeito de "Legado Mundial - "Armadura Mundial"" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invoque este card por Invocação Especial da sua mão','Procurar no Deck','Retornar para a mão','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83488497,'Espantagarra Astra',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) em uma Zona de Monstros Principal sua, adjacente a um monstro "Espantagarra" que você controla ou na coluna dele. \r\nVocê só pode Invocar "Espantagarra Astra" por Invocação-Especial uma vez por turno desta forma. \r\nSeus monstros "Espantagarra" nas Zonas de Monstros Adicionais podem atacar um número de vezes a cada Fase de Batalha, até o número de monstros "Espantagarra" em Posição de Defesa que você controla com nomes diferentes.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83500096,'Sólido Aliado Genex','Uma vez por turno, você pode enviar 1 monstro "Genex" de ÁGUA com a face para cima que você controla ao Cemitério para comprar 2 cards.','Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83512285,'Hipergaláxia',replace(replace('Ofereça como Tributo 1 monstro com 2000 ou mais de ATK, exceto "Dragão de Fóton de Olhos das Galáxias" e, depois, escolha 1 monstro que seu oponente controla com 2000 ou mais de ATK; ofereça-o como Tributo e, se isso acontecer, Invoque por Invocação-Especial 1 "Dragão de Fóton de Olhos das Galáxias" da sua mão, do Deck ou do Cemitério. \r\nVocê só pode ativar 1 "Hipergaláxia" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83518674,'Perigo! Ogopogo!',replace(replace('Você pode revelar este card na sua mão; seu oponente seleciona aleatoriamente 1 card de toda a sua mão e, depois, você descarta o card selecionado. \r\nDepois, se o card descartado não era "Perigo! Ogopogo!", Invoque por Invocação-Especial 1 "Perigo! Ogopogo!" da sua mão e, se isso acontecer, compre 1 card. \r\nSe este card for descartado: você pode enviar 1 card "Perigo!" do seu Deck para o Cemitério, exceto "Perigo! Ogopogo!". \r\nVocê só pode usar este efeito de "Perigo! Ogopogo!" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83519853,'Inobre Cavaleiro do Alto Laundsallyn',replace(replace('1 Regulador + 1 ou mais monstros "Nobre Cavaleiro" não-Reguladores	\r\nQuando este card for Invocado por Invocação-Sincro: você pode equipar 1 Card de Magia de Equipamento "Armas Nobres" do seu Deck a este card. \r\nNo final da Fase de Batalha, se este card destruiu um monstro em batalha e o enviou para o Cemitério: você pode adicionar 1 card "Nobre Cavaleiro" ou "Armas Nobres" do seu Deck à sua mão. \r\nVocê só pode controlar 1 "Inobre Cavaleiro do Alto Laundsallyn".','\r',char(13)),'\n',char(10)),'Equipar','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83528184,'Noma, a Professora Assistente da GMX',replace(replace('Se este card for Invocado por Invocação-Especial por um efeito de monstro: você pode escolher 1 card cada do seu Cemitério e do Cemitério do seu oponente; coloque cada card no topo ou no fundo do Deck. \r\nSe um ou mais monstros forem Invocados por Invocação-Normal ou Especial no campo do seu oponente, enquanto este card estiver na sua Zona de Monstros (exceto durante a Etapa de Dano): você pode Invocar por Invocação-Fusão 1 Monstro de Fusão "GMX" do seu Deck Adicional, ao embaralhar no Deck suas matérias do seu campo, Cemitério e/ou banimento. \r\nVocê só pode usar cada efeito de "Noma, a Professora Assistente da GMX" uma vez por turno.','\r',char(13)),'\n',char(10)),'Retornar ao Deck','Invocação Fusão','Coloque no topo do Deck','Coloque no fundo do Deck','','','','','','','','','','','','');
INSERT INTO texts VALUES(83531441,'Dante, Viajante do Abismo Ardente',replace(replace('2 monstros de Nível 3	\r\nUma vez por turno: você pode desassociar 1 matéria deste card e selecionar um número de 1 a 3 e, depois, envie esse número de cards do topo do seu Deck para o Cemitério; até o final deste turno, este card ganha 500 de ATK para cada card enviado para o Cemitério desta forma. \r\nSe este card atacar, ele é colocado em Posição de Defesa no final da Fase de Batalha. \r\nSe este card for enviado para o Cemitério: você pode escolher 1 card "Abismo Ardente" no seu Cemitério, exceto este card; adicione-o à sua mão.','\r',char(13)),'\n',char(10)),'Alterar ATK/DEF','Recuperar cards','Escolha a quantidade de cards a enviar para o Cemitério','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83533296,'Investida Salamagrande',replace(replace('Ative 1 desses efeitos;\r\n● Escolha 3 dos seus monstros de FOGO que estiverem banidos e/ou no seu Cemitério; embaralhe 2 dos 3 no Deck e, se isso acontecer, Invoque por Invocação-Especial o monstro restante, mas pelo resto deste turno, seus efeitos são negados e, além disso, ele não pode atacar.\r\n● Se você controlar um ou mais Monstros de Ritual, de Fusão, Sincro, Xyz ou Link de FOGO cujo ATK atual seja diferente do seu ATK original: você pode escolher 1 card no campo; destrua-o.	\r\nVocê só pode ativar 1 "Investida Salamagrande" por turno.','\r',char(13)),'\n',char(10)),'Recuperar monstros banidos','Destruir um card no Campo','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83544697,'Contato com Gusto','Escolha 2 monstros "Gusto" no seu Cemitério e 1 card que seu oponente controla; embaralhe ambos os alvos do seu Cemitério no Deck e, depois, destrua o alvo do oponente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83546647,'Lobo em Pele de Cordeiro',replace(replace('Só pode ser ativado quando você sofrer Dano de Batalha de um ataque direto de um monstro do oponente. \r\nRevele 1 monstro de Nível 1 na sua mão. \r\nInvoque-o por Invocação-Especial da sua mão e 1 monstro com o mesmo nome do seu Deck.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83550869,'Ryko, Lutador Crepúsculo Luminoso',replace(replace('Se este card for Invocado por Invocação-Normal ou virado com a face para cima: você pode banir 1 monstro "Luminoso(a)" da sua mão ou do Cemitério; bana 1 card no campo. \r\nUma vez por turno, se o efeito de outro monstro "Luminoso(a)" seu for ativado: envie os 3 cards do topo do seu Deck para o Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83554231,'Recurância Salamagrande',replace(replace('Escolha 2 monstros "Salamagrande" com nomes diferentes no seu Cemitério; adicione-os à sua mão. \r\nSe este card Baixado for destruído por um efeito de card e enviado para o Cemitério: você pode adicionar 1 Magia/Armadilha "Salamagrande" do seu Deck à sua mão, exceto "Recurância Salamagrande". \r\nVocê só pode usar cada efeito de "Recurância Salamagrande" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83555666,'Anel da Destruição',replace(replace('Durante o turno do seu oponente: escolha 1 monstro com a face para cima que seu oponente controla cujo ATK seja menor ou igual que os PV dele; destrua esse monstro com a face para cima e, se isso acontecer, sofra dano igual ao ATK original dele e, depois, cause dano ao seu oponente igual ao dano que você sofreu. \r\nVocê só pode ativar 1 "Anel da Destruição" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83555667,'Anel da Destruição',replace(replace('Durante o turno do seu oponente: escolha 1 monstro com a face para cima que seu oponente controla cujo ATK seja menor ou igual que os PV dele; destrua esse monstro com a face para cima e, se isso acontecer, sofra dano igual ao ATK original dele e, depois, cause dano ao seu oponente igual ao dano que você sofreu. \r\nVocê só pode ativar 1 "Anel da Destruição" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83558891,'Chegada do Espantagarra',replace(replace('Escolha 1 monstro "Espantagarra" ou "Visas Starfrost" no seu Cemitério; Invoque-o por Invocação-Especial em Posição de Defesa. \r\nSe um ou mais Monstros Link "Espantagarra" que você controla seriam destruídos em batalha ou por um efeito de card, em vez disso, você pode banir este card do seu Cemitério. \r\nVocê só pode usar este efeito de "Chegada do Espantagarra" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83566725,'Os Cavaleiros Fantasmas de Soleret Condenado',replace(replace('Se você não controlar nenhum monstro, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Os Cavaleiros Fantasmas de Soleret Condenado" por Invocação-Especial uma vez por turno desta forma. \r\nVocê só pode usar cada um dos seguintes efeitos de "Os Cavaleiros Fantasmas de Soleret Condenado" uma vez por turno. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode Baixar 1 Magia/Armadilha "Os Cavaleiros Fantasmas" do seu Deck. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha até 2 monstros de TREVAS de Nível/Classe 3 que você controla; aumente o Nível/Classe deles em 1.','\r',char(13)),'\n',char(10)),'Invocação Especial','Baixar Magia/Armadilha','Aumentar Nível/Classe','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83575471,'Fera Cristalina Avançada Carbúnculo Rubi',replace(replace('Se "Trevas Avançadas" não estiver em uma Zona do Campo, envie este monstro para o Cemitério. \r\nSe este card com a face para cima for destruído em uma Zona de Monstros, em vez de enviá-lo para o Cemitério, você pode colocá-lo com a face para cima na sua Zona de Magias & Armadilhas como uma Magia Contínua. \r\nEnquanto este card for considerado como uma Magia Contínua: você pode Invocar este card por Invocação-Especial e, depois, você pode Invocar por Invocação-Especial tantos Cards de Monstro "Fera Cristalina Avançada" quanto possível das suas Zonas de Magias & Armadilhas. \r\nVocê só pode usar este efeito de "Fera Cristalina Avançada Carbúnculo Rubi" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial o máximo possível?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83584898,'Grilhões do Mundo das Trevas',replace(replace('O monstro equipado não pode atacar e, além disso, seu ATK e DEF se tornam 100. \r\nDurante cada uma das suas Fases de Apoio: Cause 500 de dano ao controlador do monstro equipado.','\r',char(13)),'\n',char(10)),'Receba 500 pontos de dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83589191,'Hackear Vida',replace(replace('Escolha 1 monstro com a face para cima no campo; qualquer dano que seu oponente sofrer neste turno é diminuído pela metade e, além disso, o ATK desse monstro se torna igual aos PV atuais do seu oponente até o final deste turno. \r\nDurante sua Fase Principal: você pode banir este card do seu Cemitério e, depois, escolha 1 monstro com a face para cima no campo; qualquer dano que seu oponente sofrer neste turno é diminuído pela metade e, além disso, o ATK desse monstro se torna igual aos seus PV atuais até o final deste turno. \r\nVocê só pode usar cada efeito de "Hackear Vida" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83602069,'Companheiro Espadachim de Landstar','Todos os monstros do Tipo Guerreiro que você controla ganham 400 de ATK.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83604828,'Nuviano - Nevoeiro Fantasma',replace(replace('Não pode ser Invocado por Invocação-Especial. \r\nNenhum duelista sofre dano de batalha dos ataques envolvendo este card. \r\nSe este card for destruído em batalha: distribua Marcadores de Névoa igual ao Nível do monstro que o destruiu entre monstros com a face para cima.','\r',char(13)),'\n',char(10)),'Colocar um marcador','Escolha o card no qual colocar "Marcador de Névoa"','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83610035,'Therion "Lírio" Borea',replace(replace('Você só pode usar cada um dos seguintes efeitos de "Therion "Lírio" Borea" uma vez por turno.\r\n● Você pode escolher 1 monstro "Therion" ou 1 monstro Planta no seu Cemitério; Invoque este card por Invocação-Especial da sua mão e, se isso acontecer, equipe esse monstro a este card.\r\n● Você pode enviar 1 card da sua mão ou do campo para o Cemitério; adicione 1 Magia/Armadilha "Therion" do seu Deck à sua mão.	\r\nUm monstro "Therion" equipado com este card ganha 700 de ATK e, além disso, ele pode ativar o 2º efeito listado acima como se fosse "Therion "Lírio" Borea".','\r',char(13)),'\n',char(10)),'','Procurar no Deck (Therion "Lírio" Borea)','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83626916,'D.D. Postal',replace(replace('Monstros que você controla ganham 300 de ATK para cada tipo de card (Monstro, Magia ou Armadilha) entre seus cards banidos. \r\nUma vez por turno, durante a Fase Principal: você pode banir 1 card da sua mão ou do Cemitério e, depois, você pode embaralhar 1 dos seus cards banidos no Deck. \r\nSe este card for banido: você pode colocá-lo com a face para cima no seu campo. \r\nVocê só pode usar este efeito de "D.D. Postal" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Banir','Colocar com a face para cima','Retornar o card para o Deck?','','','','','','','','','','','','');
INSERT INTO texts VALUES(83629030,'Dragão Cibernético Toon',replace(replace('Se seu oponente controlar um monstro e você não controlar nenhum monstro, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nNão pode atacar no turno em que for Invocado. \r\nEnquanto você controlar "Mundo Toon" e seu oponente não controlar nenhum monstro Toon, este card pode atacar diretamente seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83656563,'Máquina Fóssil Vagão Caveira',replace(replace('1 monstro Rocha no seu Cemitério + 1 monstro de Nível 5 ou 6	\r\nPrimeiro deve ser Invocado por Invocação-Especial com "Fusão Fóssil". \r\nEste card pode realizar até 2 ataques contra monstros durante cada Fase de Batalha. \r\nQuando este card destruir um monstro do oponente em batalha: você pode causar 800 de dano ao seu oponente. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 Magia/Armadilha no campo; destrua-a. \r\nVocê só pode usar este efeito de "Máquina Fóssil Vagão Caveira" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83670388,'Maldição Gelojade',replace(replace('Enquanto um monstro "Gelojade" e "Berço Enion, Cenote de Gelojade" estiverem no campo, seu oponente não pode ativar os efeitos de monstros que foram Invocados nesse turno. \r\nQuando um monstro for destruído em uma batalha envolvendo um monstro "Gelojade" seu: você pode escolher 1 desses monstros destruídos; cause dano ao seu oponente igual ao ATK original desse monstro. \r\nVocê só pode usar este efeito de "Maldição Gelojade" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83675475,'Festival dos Tokens','Quando uma ou mais Fichas forem Invocadas por Invocação-Especial: destrua tantas Fichas no campo quanto possível e, se isso acontecer, cause 300 de dano ao seu oponente para cada Ficha destruída.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83678433,'Demônio da Meia-Noite','Este monstro só aparece quando há uma oferenda à meia-noite.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83682209,'Espirata, o Pirata Fantasma',replace(replace('Se um ou mais monstros de ÁGUA com a face para cima que você controla, exceto "Espirata, o Pirata Fantasma", forem destruídos em batalha ou por um efeito de card, enquanto este card estiver no seu Cemitério: você pode Invocar este card por Invocação-Especial (mas bana-o quando ele deixar o campo) e, se isso acontecer, até o final do próximo turno, ele ganha 100 de ATK para cada monstro de ÁGUA no seu Cemitério. \r\nVocê só pode usar este efeito de "Espirata, o Pirata Fantasma" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83682725,'Rasteira com a Cauda','Escolha 1 monstro Dinossauro de Nível 5 ou mais que você controla; se esse monstro Dinossauro ainda estiver com a face para cima no campo, selecione até 2 monstros que seu oponente controla que tenham um Nível menor que o dele, ou que estejam com a face para baixo, e devolva os monstros selecionados para a mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83705073,'Valquíria-Erda',replace(replace('Você só pode controlar 1 "Valquíria-Erda". \r\nEnquanto você controlar este card, Invocado por Invocação-Especial pelo efeito de um card "Valquíria-", todos os monstros com a face para cima que seu oponente controla perdem 1000 de ATK. \r\nQualquer card destruído em batalha ou por um efeito de card que seria enviado para o Cemitério do seu oponente, em vez disso, é banido.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial pelo efeito de um card "Valquíria-"','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83711531,'Dragão Garras de Metal de Olhos Vermelhos',replace(replace('Você pode ativar Armadilhas "Metalmorfe" no turno em que foram Baixadas. \r\nVocê só pode usar cada um dos seguintes efeitos de "Dragão Garras de Metal de Olhos Vermelhos" uma vez por turno. \r\nVocê pode enviar 1 card com a face para baixo que você controla para o Cemitério; Invoque este card por Invocação-Especial da sua mão. \r\nSe este card for Invocado por Invocação-Normal ou Especial e você tiver "Metalmorfe Máximo" no seu campo ou Cemitério: você pode adicionar 1 Armadilha "Metalmorfe" do seu Deck ou Cemitério à sua mão.','\r',char(13)),'\n',char(10)),'Invocação Especial','Adicionar à mão','Ativar aplicando o efeito de "Dragão Garras de Metal de Olhos Vermelhos".','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83715234,'Atacar a Lua!','Uma vez por turno, quando a posição de batalha de um monstro Rocha que você controla for alterada: você pode escolher 1 Magia/Armadilha que seu oponente controla; destrua o alvo.','Destruir Magias/Armadilhas','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83723605,'Circulação Marincesa',replace(replace('Escolha 1 Monstro Link de ÁGUA que você controla; devolva-o para o Deck Adicional e, se isso acontecer, Invoque por Invocação-Especial 1 Monstro Link "Marincesa" do seu Deck Adicional com o mesmo Valor Link, mas um nome diferente, mas ele não pode atacar diretamente ou ser destruído em batalha neste turno. \r\n(Isso é considerado uma Invocação-Link.) \r\nSe você controlar um monstro "Marincesa" de Link-3 ou mais, você pode ativar este card da sua mão.','\r',char(13)),'\n',char(10)),'Ativar aplicando o efeito de "Circulação Marincesa".','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83725008,'Jenis, a Reparadora Luminosa','Durante a Fase Final, se um ou mais cards foram enviados do seu Deck para o Cemitério pelo efeito de um card "Luminoso(a)" neste turno: cause 500 de dano ao seu oponente e, se isso acontecer, ganhe 500 PV.','Causar dano/Ganhar PV','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83743222,'Arco da Deusa',replace(replace('Deve ser Invocado por Invocação-Especial com "A Garra de Hermos", usando um monstro Guerreiro. 	\r\nSe este card for Invocado por Invocação-Especial: escolha 1 outro monstro com a face para cima no campo; equipe este card a ele. \r\nEnquanto este card estiver equipado a um monstro por este efeito, negue o primeiro efeito ativado pelo seu oponente durante cada Fase de Batalha e, além disso, depois, o monstro equipado pode realizar um segundo ataque durante esta Fase de Batalha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83746708,'Poder de Mago','O monstro equipado ganha 500 de ATK/DEF para cada Magia/Armadilha que você controla.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83747250,'Vestes do Crepúsculo',replace(replace('Escolha 1 monstro com a face para cima que você controla; bana qualquer número de monstros "Luminoso(a)" no seu Cemitério e, se isso acontecer, até o final deste turno, esse monstro ganha 200 de ATK e DEF para cada monstro banido por este efeito. \r\nSe este card for enviado do Deck para o Cemitério pelo efeito de um monstro "Luminoso(a)": você pode ativar este efeito; neste turno, monstros "Luminoso(a)" que você controla não podem ser destruídos em batalha ou por efeitos de card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83755611,'Baxia, Brilho de Yang Zing',replace(replace('1 Regulador + 1+ monstros Wyrm não-Reguladores	\r\nQuando este card for Invocado por Invocação-Sincro: você pode escolher cards no campo, até o número de Atributos originais diferentes dentre os monstros Wyrm usados para a Invocação-Sincro deste card; embaralhe-os no Deck. \r\nUma vez por turno: você pode escolher 1 card que você controla e 1 monstro de Nível 4 ou menos no seu Cemitério; destrua esse card no campo e, se isso acontecer, Invoque por Invocação-Especial esse outro monstro do Cemitério.','\r',char(13)),'\n',char(10)),'Retornar ao Deck','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83764718,'Reviver Monstro','Escolha 1 monstro em qualquer Cemitério; Invoque-o por Invocação-Especial.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83764719,'Reviver Monstro','Escolha 1 monstro em qualquer Cemitério; Invoque-o por Invocação-Especial.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83764720,'Reviver Monstro','Escolha 1 monstro em qualquer Cemitério; Invoque-o por Invocação-Especial.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83764721,'Reviver Monstro','Escolha 1 monstro em qualquer Cemitério; Invoque-o por Invocação-Especial.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83764996,'Cavalheiro Ilusório','Vestindo roupas peculiares, este cavalheiro é bem instável. Às vezes ele salva pessoas, outras vezes comete crimes.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83778600,'Renascimento do Tolo','Escolha 1 monstro do Cemitério do seu oponente e Invoque-o por Invocação-Especial com a face para cima em Posição de Defesa no lado do campo do seu oponente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83793721,'Etoile Florida, a Magnificat Melodiosa',replace(replace('1 monstro "Maestra Melodiosa" + 2 monstros "Melodiosa(o)"	\r\n(Efeito Rápido): você pode banir (até a Fase Final) qualquer número de monstros "Melodiosa(o)" que você controla e, depois, você pode devolver para a mão até esse número de cards com a face para cima que seu oponente controla. \r\nVocê só pode usar este efeito de "Etoile Florida, a Magnificat Melodiosa" uma vez por turno. \r\nSe este card com a face para cima Invocado por Invocação-Fusão sob o controle do seu dono deixar o campo devido a um card do oponente: você pode Invocar por Invocação-Especial 1 monstro "Melodiosa(o)" do seu Deck ou Deck Adicional, exceto "Etoile Florida, a Magnificat Melodiosa".','\r',char(13)),'\n',char(10)),'Retornar para a mão?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83810690,'Sabre-X Wayne',replace(replace('1 Regulador + 1 ou mais monstros não Reguladores	\r\nQuando este card for Invocado por Invocação-Sincro, você pode Invocar por Invocação-Especial 1 monstro do Tipo Guerreiro de Nível 4 ou menos da sua mão.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83812099,'Trava Flint',replace(replace('Uma vez por turno: você pode escolher 1 "Flint" na Zona de Magias & Armadilhas; equipe-o a este card. \r\nDurante sua Fase Principal: você pode escolher 1 "Flint" equipado a este card e 1 monstro com a face para cima no campo, exceto este card; equipe esse "Flint" a esse monstro alvo. \r\nEste card só pode ser equipado com 1 "Flint". \r\nEnquanto equipado com "Flint", este card não é afetado pelo efeito de "Flint" e não pode ser destruído em batalha.','\r',char(13)),'\n',char(10)),'Equipar a este card','Transfira o Card de Equipamento','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83819309,'Brasas Esfriando',replace(replace('Se um duelista ganhar PV (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão. \r\nUma vez por turno, se um duelista ganhar PV enquanto este card estiver na Zona de Monstros (exceto durante a Etapa de Dano): você pode fazer com que 1 duelista ganhe 1000 PV.','\r',char(13)),'\n',char(10)),'','Fazer o oponente ganhar PV?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83827392,'Noir Expurrely',replace(replace('2 monstros de Nível 7	\r\nVocê também pode Invocar este card por Invocação-Xyz usando um monstro de Classe 2 que você controla com 5 ou mais matérias. \r\n(Transfira as matérias dele para este card.) \r\nEste card não é afetado pelos efeitos ativados do seu oponente enquanto tiver 5 ou mais matérias. \r\nVocê pode desassociar 2 matérias deste card e, depois, escolha 1 card que seu oponente controla ou no Cemitério dele; coloque-o no fundo do Deck. \r\nEste é um Efeito Rápido se este card tiver um monstro "Purrely" de Nível 1 como matéria.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Xyz sobrepondo seu monstro de Classe 2 com 5 ou mais matérias?','Retornar um card do oponente para o Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83828288,'Mamemaki','Escolha 1 monstro com a face para cima que seu oponente controla; descarte cards igual ao Nível desse monstro e, se isso acontecer, compre o mesmo número de cards que você descartou e, depois, devolva esse monstro para a mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83831356,'Karakuri Fugitivo',replace(replace('Selecione 1 monstro "Karakuri" com a face para cima no campo. \r\nAté a Fase Final, ele ganha 1000 de ATK, mas seus efeitos são negados.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83838727,'Dia do Sanduíche',replace(replace('Se você tiver um monstro no seu Cemitério: pague 200 PV; compre 1 card e revele-o e, depois, se for um monstro, aplique este efeito de acordo com o Atributo dele.\r\n● Um Atributo que não estiver no seu Cemitério: Compre 1 card.\r\n● Um Atributo no seu Cemitério: Descarte 1 card.	\r\nVocê só pode ativar 1 "Dia do Sanduíche" por turno.','\r',char(13)),'\n',char(10)),'Ativar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83866861,'Quimera Peladura',replace(replace('3 monstros "Peladura"	\r\nDeve ser Invocado por Invocação-Fusão e não pode ser Invocado por Invocação-Especial de nenhuma outra forma. \r\nSe este card batalhar, seu oponente não pode ativar cards ou efeitos até o final da Etapa de Dano. \r\nQuando este card destruir um monstro do oponente em batalha e enviá-lo para o Cemitério: você pode Invocar esse monstro por Invocação-Especial no seu campo, mas o ATK dele é diminuído pela metade. \r\nVocê só pode usar este efeito de "Quimera Peladura" uma vez por turno. \r\nEste card ganha 300 de ATK para cada monstro que você controla do qual seu oponente é dono.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83880087,'Escudo Asa de Luz',replace(replace('Quando o ataque de um monstro for negado: ative 1 desses efeitos;\r\n● Essa se torna a Fase Final deste turno.\r\n● Escolha 1 Monstro Xyz "Utopia" que você controla; o ATK dele se torna o dobro do seu ATK original até o final deste turno.	\r\nSe um Monstro Xyz "Utopia" que você controla iria desassociar exatamente 1 Matéria Xyz para ativar seu efeito, em vez disso, você pode banir este card do seu Cemitério.','\r',char(13)),'\n',char(10)),'Ir para a Fase Final deste turno','Dobre o ATK dele','Use o efeito de "Escudo Asa de Luz" em vez de desassociar Matéria','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83880473,'Espírito Caverguerra',replace(replace('Durante a Fase de Batalha: escolha 1 monstro "Caverguerra" no seu Cemitério e, depois, ative 1 desses efeitos;\r\n● Invoque o alvo por Invocação-Especial em Posição de Ataque, mas pelo resto deste turno, seus efeitos são negados e, além disso, ele não pode atacar diretamente.\r\n● Invoque o alvo por Invocação-Especial em Posição de Defesa e, além disso, na primeira vez que cada monstro "Caverguerra" que você controla seria destruído em batalha neste turno, ele não é destruído.	\r\nVocê só pode ativar 1 "Espírito Caverguerra" por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial em Posição de Ataque','Invocar por Invocação Especial em Posição de Defesa','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83887306,'Ataque de Dois Gumes','Escolha e destrua 2 monstros no seu Campo e 1 monstro no Campo do seu adversário.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83888009,'Renascimento dos Sétimos Imperadores',replace(replace('Ofereça como Tributo todos os Monstros Xyz que você controla e, depois, escolha 1 dos seus Monstros Xyz banidos; Invoque-o por Invocação-Especial e, depois, você pode associar seus Monstros Xyz "Número" que estiverem banidos e/ou no seu Cemitério a ele como matéria, que tenham um número entre "101" e "107" em seu nome, até o número de monstros oferecidos como Tributo para ativar este efeito +1. \r\nDurante a Fase Final do turno em que você ativou este card, cada duelista sofre 300 de dano para cada card na mão dele.','\r',char(13)),'\n',char(10)),'Sobrepor Matérias Xyz?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83903521,'Besta do Faraó','Se este card for enviado para o Cemitério para uma Invocação-Sincro: você pode escolher 1 monstro Zumbi de Nível 4 ou menos no seu Cemitério; Invoque o alvo por Invocação-Especial.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83928661,'Perigo! Péezas de Força!',replace(replace('Só pode ser equipado a um monstro "Perigo!". \r\nEle ganha 800 de ATK/DEF. \r\nEle não pode ser destruído por efeitos de card. \r\nEle pode realizar até 2 ataques contra monstros durante cada Fase de Batalha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83957459,'Rinotauro','Se 2 ou mais dos monstros do seu oponente forem destruídos em batalha com os seus monstros durante a mesma Fase de Batalha, este card pode realizar um segundo ataque durante essa Fase de Batalha.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83962752,'Pânico Sincro',replace(replace('Ative apenas se um ou mais Monstros Sincro com a face para cima que você controla forem destruídos em batalha ou por um efeito de card do oponente, ao escolher 1 deles; Invoque por Invocação-Especial 1 Regulador e 1 ou mais não-Reguladores do seu Cemitério, cuja soma dos Níveis seja igual ao do monstro alvo e, se isso acontecer, eles não podem ser destruídos em batalha ou por efeitos de card neste turno. \r\nNenhum duelista pode Invocar por Invocação-Sincro. \r\nDestrua este card durante sua 3ª Fase de Apoio depois da ativação.','\r',char(13)),'\n',char(10)),'Invocação Especial','Invocado por Invocação Especial pelo efeito de "Pânico Sincro"','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83965310,'HERÓI do Destino - Plasma',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao oferecer como Tributo 3 monstros. \r\nNegue os efeitos de monstros com a face para cima enquanto seu oponente os controlar. \r\nUma vez por turno: você pode escolher 1 monstro que seu oponente controla; equipe o alvo a este card (máx. 1). \r\nGanha ATK igual à metade do ATK original do monstro equipado a ele por este efeito.','\r',char(13)),'\n',char(10)),'Ofereça 3 monstros que você controla como Tributo para Invocar por Invocação Especial','Equipe a este card um monstro do oponente','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83965311,'HERÓI do Destino - Plasma',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao oferecer como Tributo 3 monstros. \r\nNegue os efeitos de monstros com a face para cima enquanto seu oponente os controlar. \r\nUma vez por turno: você pode escolher 1 monstro que seu oponente controla; equipe o alvo a este card (máx. 1). \r\nGanha ATK igual à metade do ATK original do monstro equipado a ele por este efeito.','\r',char(13)),'\n',char(10)),'Ofereça 3 monstros que você controla como Tributo para Invocar por Invocação Especial','Equipe a este card um monstro do oponente','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83968380,'Jarra da Ganância','Compre 1 card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83980492,'Dragongo',replace(replace('Escala de Pêndulo = 7\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nEste gongo abriga a alma de um dragão indomado. Ele plana pelos céus com um incrível rugido, recrutando para a batalha todos os que escutam seu grito de guerra.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83982270,'Nuviano - Nuvem de Veneno','Quando este card for destruído em batalha e enviado para o Cemitério, se ele estava com a face para cima no começo da Etapa de Dano: Destrua o monstro que o destruiu e, se isso acontecer, cause 800 de dano ao seu oponente.','Destrua e cause dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83986578,'Rei Tigre Wanghu',replace(replace('Se um ou mais monstros com 1400 ou menos de ATK forem Invocados por Invocação-Normal ou Especial enquanto você controlar este card: destrua esses monstros com 1400 ou menos de ATK. \r\nEste card deve estar com a face para cima no campo para ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83991690,'Buten','Durante sua Fase Principal: Você pode banir este card do Cemitério para escolher 1 monstro de LUZ do Tipo Fada de Nível 4 ou menos com a face para cima que você controla; ele é considerado como um monstro Regulador enquanto estiver com a face para cima no campo.','Considerar como Regulador','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83994433,'Dragão da Centelha de Poeira Estelar',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nUma vez por turno (Efeito Rápido): você pode escolher 1 card com a face para cima que você controla; uma vez durante este turno, ele não pode ser destruído em batalha ou por efeitos de card.','\r',char(13)),'\n',char(10)),'Não pode ser destruído','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83994646,'Ladybug de 4 Estrelas da Condenação','VIRE: Destrua todos os monstros de Nível 4 que seu oponente controla.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84012625,'Chama Cósmica',replace(replace('Escolha 1 Monstro Sincro "Poeira Estelar" que você controla; neste turno, se esse Monstro Sincro que você controla batalhar um monstro do oponente, embaralhe esse monstro do oponente no Deck no começo da Etapa de Dano. \r\nSe um Monstro Sincro "Poeira Estelar" que você controla seria oferecido como Tributo para ativar seu próprio efeito, em vez disso, você pode banir este card do seu Cemitério.','\r',char(13)),'\n',char(10)),'Escolha 1 card para oferecer como Tributo, ou para banir em vez disso','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84013237,'Número 39: Utopia',replace(replace('2 monstros de Nível 4	\r\nQuando um monstro declarar um ataque: você pode desassociar 1 matéria deste card; negue o ataque. \r\nSe este card for escolhido como alvo de um ataque enquanto não tiver matéria: destrua este card.','\r',char(13)),'\n',char(10)),'Negar o ataque','Autodestruir-se','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84013238,'Número 39: Utopia',replace(replace('2 monstros de Nível 4	\r\nQuando um monstro declarar um ataque: você pode desassociar 1 matéria deste card; negue o ataque. \r\nSe este card for escolhido como alvo de um ataque enquanto não tiver matéria: destrua este card.','\r',char(13)),'\n',char(10)),'Negar o ataque','Autodestruir-se','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84013239,'Número 39: Utopia',replace(replace('2 monstros de Nível 4	\r\nQuando um monstro declarar um ataque: você pode desassociar 1 matéria deste card; negue o ataque. \r\nSe este card for escolhido como alvo de um ataque enquanto não tiver matéria: destrua este card.','\r',char(13)),'\n',char(10)),'Negar o ataque','Autodestruir-se','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84013240,'Número 39: Utopia',replace(replace('2 monstros de Nível 4	\r\nQuando um monstro declarar um ataque: você pode desassociar 1 matéria deste card; negue o ataque. \r\nSe este card for escolhido como alvo de um ataque enquanto não tiver matéria: destrua este card.','\r',char(13)),'\n',char(10)),'Negar o ataque','Autodestruir-se','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84025439,'Rei Mech Super Quantal Grande Magnus',replace(replace('3 monstros de Nível 12	\r\nSe este card for enviado para o Cemitério: você pode Invocar por Invocação-Especial 3 Monstros Xyz "Besta Mech Super Quantal" com nomes diferentes do seu Cemitério. \r\nEste card ganha esses efeitos, de acordo com o número de matérias com nomes diferentes associadas a ele.\r\n● 2+: Uma vez por turno, durante a Fase Principal (Efeito Rápido): você pode desassociar 1 matéria deste card; embaralhe no Deck 1 card do campo.\r\n● 4+: Ele não é afetado por efeitos de card, exceto cards "Super Quant".\r\n● 6+: Seu oponente não pode adicionar cards do Deck à mão por efeitos de card.','\r',char(13)),'\n',char(10)),'Retornar ao Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84031359,'Senhor Obscuro Gulgolet',replace(replace('Você só pode Invocar um ou mais "Senhor Obscuro Gulgolet" por Invocação-Especial uma vez por turno. \r\nSe este card for Invocado por Invocação-Especial: você pode Invocar por Invocação-Especial 2 "Ficha de Senhor Obscuro" (Fada/TREVAS/Nível 6/ATK 0/DEF 0) e, além disso, você não pode Invocar por Invocação-Especial pelo resto deste turno, exceto monstros Fada. \r\nSe este card for enviado para o Cemitério: você pode adicionar 1 card "Senhor(a) Obscuro(a)", exceto "Senhor Obscuro Gulgolet", ou 1 Magia Rápida "Proibido(a)", do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Senhor Obscuro Gulgolet" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84031360,'Ficha de Senhor Obscuro','Invocado por Especial com o efeito "Senhor Obscuro Gulgolet".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84031736,'Final da Companhia de Palhaços',replace(replace('Se você controlar um monstro Invocado por Invocação-Tributo: descarte qualquer número de cards e, depois, escolha esse número de cards com a face para cima no campo; destrua-os. \r\nVocê pode banir este card do seu Cemitério e, oferecer como Tributo 1 Monstro de Ritual, de Fusão, Sincro, Xyz, Pêndulo ou Link da sua mão ou do campo; adicione 1 monstro "Companhia de Palhaços" com um Nível/Classe/Valor Link original diferente, do seu Deck ou Cemitério à sua mão. \r\nVocê só pode usar cada efeito de "Final da Companhia de Palhaços" uma vez por turno.','\r',char(13)),'\n',char(10)),'Efeito de destruição','Efeito de busca','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84040113,'Lamadragão Enlamaçado',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nEste card pode ser usado como um substituto para qualquer 1 Matéria de Fusão cujo nome esteja especificamente listado no Card de Monstro de Fusão, mas a(s) outra(s) \r\nMatéria(s) de Fusão deve(m) estar correta(s). \r\nDurante sua Fase Principal, se você controlar este card Invocado por Invocação-Sincro: você pode Invocar por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional, usando monstros que você controla como Matéria de Fusão, incluindo este card. \r\nVocê só pode usar este efeito de "Lamadragão Enlamaçado" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84046493,'Carne Fantasma',replace(replace('Escala de Pêndulo = 4\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno: você pode lançar um dado de seis faces. Até o final deste turno, aumente a Escala de Pêndulo deste card por esse número (máx. 10).\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nO Fantasma da Ceia de Natal.','\r',char(13)),'\n',char(10)),'Aumentar Escala Pêndulo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84054556,'Comando DoomZ "A.D.R.A.S.T.E.I.A"',replace(replace('Na primeira vez que o monstro equipado seria destruído em batalha a cada turno, ele não é destruído. \r\nVocê só pode usar cada um dos seguintes efeitos de "Comando DoomZ "A.D.R.A.S.T.E.I.A"" uma vez por turno. \r\nDurante sua Fase Principal: você pode destruir o monstro equipado e, se isso acontecer, Invoque por Invocação-Especial 1 monstro "DoomZ" em Posição de Defesa, exceto o monstro destruído, da sua mão, do Cemitério ou do banimento. \r\nSe este card estiver no seu Cemitério: você pode escolher 1 monstro com a face para cima que você controla; equipe-o com este card e, depois, sofra dano igual ao Nível/Classe do monstro equipado x 100.','\r',char(13)),'\n',char(10)),'Invocação Especial','Efeito de Equipamento','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84055227,'Dama do Macabro',replace(replace('Se este card destruir um monstro do oponente em batalha: coloque 1 Marcador de Magia nele. \r\nGanha 200 de ATK para cada Marcador de Magia nele.','\r',char(13)),'\n',char(10)),'Colocar um marcador','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84058253,'Dragão Enfurecido Quimeratech',replace(replace('2+ monstros "Dragão Cibernético"	\r\nA Invocação-Fusão deste card só pode ser feita com as Matérias de Fusão acima. \r\nQuando este card for Invocado por Invocação-Fusão: você pode escolher Magias/Armadilhas no campo, até o número de matérias usadas para sua Invocação-Fusão; destrua-as. \r\nUma vez por turno: você pode enviar até 2 monstros Máquina de LUZ do seu Deck para o Cemitério e, se isso acontecer, para cada monstro enviado para o Cemitério, este card ganha 1 ataque adicional durante cada Fase de Batalha neste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84079032,'Morcego Bettan',replace(replace('Até três vezes por turno, se seu oponente Invocar um ou mais monstros por Invocação-Normal ou Especial (exceto durante a Etapa de Dano): você pode escolher 1 deles; lance uma moeda e, se o resultado for cara, coloque-o com a face para cima em Posição de Ataque ou, se o resultado for coroa, coloque-o com a face para baixo em Posição de Defesa. \r\nUma vez por turno, se um ou mais outros monstros no campo forem virados com a face para cima, ou se um ou mais monstros com a face para cima forem colocados com a face para baixo em Posição de Defesa, mesmo durante a Etapa de Dano: você pode escolher 1 deles; coloque-o com a face para cima em Posição de Ataque ou com a face para baixo em Posição de Defesa.','\r',char(13)),'\n',char(10)),'Mudar a posição de batalha (Efeito ①)','Mudar a posição de batalha (Efeito ②)','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84080938,'A Donzela do Perdão','Ofereça como Tributo este card com a face para cima para devolver à sua mão 1 de seus monstros destruídos em batalha durante este turno.','Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84080939,'A Donzela do Perdão','Ofereça como Tributo este card com a face para cima para devolver à sua mão 1 de seus monstros destruídos em batalha durante este turno.','Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84103702,'Kanikabuto','Um caranguejo monstro com garras enormes capazes de triturar inimigos em pedacinhos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84117021,'Barreira Mágica',replace(replace('Ative 1 desses efeitos. \r\nSeu oponente não sofre mais dano neste turno.\r\n● Durante este turno, nenhuma Invocação de um monstro do Tipo Mago pode ser negada e quando um monstro do Tipo Mago for Invocado, seu oponente não pode ativar cards ou efeitos.\r\n● Escolha 1 monstro do Tipo Mago que você controla; se ele atacar neste turno, seu oponente não pode ativar cards ou efeitos até o final da Etapa de Dano.','\r',char(13)),'\n',char(10)),'Invocações de Magos não podem ser negadas e o oponente não pode responder.','Mago alvo: Oponente não pode ativar efeitos ao atacar.','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84121193,'Vírus Rompe-código Espadachim',replace(replace('2 Monstros de Efeito	\r\nQuando este card for Invocado por Invocação-Especial, se ele estiver co-linkado: você pode Invocar por Invocação-Especial 1 "Rompe-código Dia Zero" da sua mão, do Deck ou do Cemitério, em qualquer zona para a qual um Monstro Link apontar. \r\nDurante a Fase Final, se este card estiver no Cemitério porque foi destruído enquanto estava em sua posse por um card do oponente e enviado para lá neste turno: você pode Invocar este card por Invocação-Especial, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar cada efeito de "Vírus Rompe-código Espadachim" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84121302,'História da Origem Livromante',replace(replace('Quando este card for ativado: você pode Baixar 1 Magia/Armadilha "Livromante" diretamente do seu Deck, exceto "História da Origem Livromante". \r\nMonstros de Ritual "Livromante" que você controla ganham ATK igual ao seu próprio Nível x 100. \r\nSe um Monstro de Ritual for Invocado por Invocação-Ritual no seu campo (exceto durante a Etapa de Dano): você pode escolher 1 Magia/Armadilha que seu oponente controla; destrua-a. \r\nVocê só pode usar este efeito de "História da Origem Livromante" uma vez por turno. \r\nVocê só pode ativar 1 "História da Origem Livromante" por turno.','\r',char(13)),'\n',char(10)),'Baixar o card selecionado no campo?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84124261,'Número 39: Raízes da Utopia',replace(replace('2 monstros de Nível 1	\r\nQuando um monstro de qualquer duelista declarar um ataque: você pode desassociar 1 Matéria Xyz deste card; negue o ataque e, se você negou o ataque de um Monstro Xyz, este card ganha ATK igual à Classe desse monstro x 500.','\r',char(13)),'\n',char(10)),'Negar o ataque','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84125619,'Dai Descartável','Ofereça como Tributo 1 monstro Guerreiro e, depois, escolha 1 card no campo; destrua-o e, se isso acontecer, compre 1 card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84133008,'Olho Monstro','Você pode pagar 1000 PV; adicione 1 "Polimerização" do seu Cemitério à sua mão.','Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84136000,'O Túmulo da Ressurreição','Quando um monstro que você controla for destruído em batalha e enviado para o Cemitério: cada duelista escolhe 1 monstro no seu próprio Cemitério; cada duelista Invoca seu monstro por Invocação-Especial em Posição de Defesa, mas esses monstros não podem mudar sua posição de batalha.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84138874,'Inferno Vulcânico',replace(replace('Quando seu oponente ativar um efeito de monstro no campo: você pode banir 1 monstro Piro do seu Cemitério; cause 500 de dano ao seu oponente e, depois, se você baniu um monstro "Vulcânico(a)" para ativar este efeito, você pode negar o efeito. \r\nDurante a Fase Final do seu oponente: você pode escolher até 2 dos seus monstros "Vulcânico(a)" que estiverem banidos e/ou no seu Cemitério; coloque-os no fundo do seu Deck em qualquer ordem. \r\nVocê só pode usar cada efeito de "Inferno Vulcânico" uma vez por turno.','\r',char(13)),'\n',char(10)),'Cause dano ao seu oponente','Recuperar monstros do Cemitério/banidos','Negar o efeito ativado?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84171830,'Domínio dos Verdadeiros Monarcas',replace(replace('Enquanto você não tiver cards no seu Deck Adicional e você for o único duelista que controla um monstro Invocado por Invocação-Tributo, seu oponente não pode Invocar por Invocação-Especial do Deck Adicional. \r\nSe um monstro Invocado por Invocação-Tributo que você controla atacar um monstro do oponente, ele ganha 800 de ATK apenas durante o cálculo de dano. \r\nUma vez por turno: até o final deste turno, você pode reduzir em 2 o Nível de 1 monstro com 2800 de ATK/1000 de DEF na sua mão (mesmo depois que ele for Invocado/Baixado e mesmo que este card deixe o campo).','\r',char(13)),'\n',char(10)),'Reduzir o Nível','Escolha o monstro cujo Nível será reduzido','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84173492,'Guerreiro Indomável Lei Lei',replace(replace('Se este card atacar, ele é mudado para a Posição de Defesa no final da Battle Phase. \r\nA posição de batalha deste card não pode ser mudada até o final do seu próximo turno, exceto com um efeito de um card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84177693,'Jeral Radiante','Quando este card for enviado para o Cemitério (exceto se for destruído em batalha), ganhe 1000 PV se "O Santuário no Céu" estiver no campo.','Ganhar PV','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84192580,'Multelegante Purulia',replace(replace('Se você não controlar nenhum card (Efeito Rápido): você pode descartar este card; aplique esses efeitos neste turno.\r\n● Sempre que seu oponente Invocar um ou mais monstros por Invocação-Normal ou Especial da mão, imediatamente compre 1 card.\r\n● Uma vez, durante esta Fase Final, se o número de cards na sua mão for maior que o número de cards que seu oponente controla +6, você deve embaralhar aleatoriamente cards da sua mão no Deck até que o número na sua mão seja igual ao número que seu oponente controla +6.	\r\nVocê só pode ativar 1 outro efeito de monstro "Multelegante" no turno em que ativar este efeito.','\r',char(13)),'\n',char(10)),'Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84206435,'Medalhão da Barreira de Gelo','Adicione 1 monstro "Barreira de Gelo" do seu Deck à sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84206436,'Medalhão da Barreira de Gelo','Adicione 1 monstro "Barreira de Gelo" do seu Deck à sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84211599,'Pote da Prosperidade',replace(replace('Selecione e bana 3 ou 6 cards do seu Deck Adicional, com a face para baixo; pelo resto deste turno depois que este card resolver, qualquer dano que seu oponente sofrer é diminuído pela metade e, além disso, escave cards do topo do seu Deck igual ao número de cards banidos, adicione 1 card escavado à sua mão e coloque o resto no fundo do seu Deck em qualquer ordem. \r\nVocê só pode ativar 1 "Pote da Prosperidade" por turno. \r\nVocê não pode comprar cards por efeitos de card no turno em que ativar este card.','\r',char(13)),'\n',char(10)),'Ativar banindo 3 card(s)','Ativar banindo 6 card(s)','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84218527,'Rebobinar Senhora Fortuna',replace(replace('Escolha qualquer número dos seus monstros "Senhora Fortuna" banidos com nomes diferentes; Invoque-os por Invocação-Especial, mas embaralhe-os no Deck durante a Fase Final. \r\nVocê só pode ativar 1 "Rebobinar Senhora Fortuna" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84220251,'Renascimento Heráldico','Escolha 1 monstro "Besta Heráldica" no seu Cemitério; Invoque-o por Invocação-Especial.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84224627,'Gato Tubarão',replace(replace('2 monstros de Nível 2	\r\nEnquanto este card tiver uma matéria associada a ele que era originalmente de ÁGUA, ele não pode ser destruído em batalha. \r\nUma vez por turno (Efeito Rápido): você pode desassociar 1 matéria deste card e, depois, escolha 1 Monstro Xyz de Classe 4 ou menos que você controla; até o final deste turno, o ATK/DEF dele se tornam o dobro do ATK/DEF originais dele.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84243274,'VWXYZ-Dragão Catapulta Canhão',replace(replace('"VW-Catapulta Tigre" + "XYZ - Dragão Canhão"	\r\nPrimeiro deve ser Invocado por Invocação-Especial (do seu Deck Adicional) ao banir os cards acima que você controla. \r\nUma vez por turno: você pode escolher 1 card que seu oponente controla; bana o alvo. \r\nQuando este card declarar um ataque contra um monstro do oponente: você pode escolher o alvo do ataque como alvo; mude a posição de batalha do alvo do ataque. \r\n(Efeitos de Virar não são ativados.)','\r',char(13)),'\n',char(10)),'Banir','Mudar a posição de batalha','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84257639,'Dian Keto, Mestre da Cura','Aumente os seus Life Points em 1000 pontos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84257640,'Dian Keto, Mestre da Cura','Aumente os seus Life Points em 1000 pontos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84257883,'B.E.S. Núcleo de Canhão Explosivo',replace(replace('Se seu oponente controlar mais monstros que você, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "B.E.S. Núcleo de Canhão Explosivo" por Invocação-Especial uma vez por turno desta forma. \r\nSe este card for Invocado por Invocação-Normal ou Especial: coloque 3 marcadores neste card. \r\nNão pode ser destruído em batalha. \r\nNo final da Etapa de Dano, se este card batalhou: remova 1 marcador deste card. \r\nSe não puder, destrua-o.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84262395,'Libertação Terrestre','Quando um ou mais monstros de Nível 6 ou mais forem Invocados por Invocação-Normal ou Especial: ofereça como Tributo 1 monstro "Terrestre" de Nível 10; destrua tantos monstros que seu oponente controla quanto possível e, se isso acontecer, cause dano ao seu oponente igual ao ATK original combinado desse(s) monstro(s) destruído(s).','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84268896,'Artefato Caduceu',replace(replace('Você pode Baixar este card da sua mão na sua Zona de Magias & Armadilhas como um Card de Magia. \r\nDurante o turno do seu oponente, se este card Baixado na Zona de Magias & Armadilhas for destruído e enviado para o seu Cemitério: Invoque-o por Invocação-Especial. \r\nDurante o turno do seu oponente, sempre que um ou mais monstros "Artefato" forem Invocados por Invocação-Especial: compre 1 card. \r\nVocê deve controlar este card com a face para cima para ativar e resolver este efeito. \r\nVocê só pode controlar 1 "Artefato Caduceu".','\r',char(13)),'\n',char(10)),'Invocação Especial','Comprar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84271823,'Quebramino, o Desce-e-Apaga',replace(replace('2 monstros com Níveis diferentes	\r\nSe um monstro for Invocado por Invocação-Especial com a face para cima em uma zona para a qual este card apontar enquanto você controlar este monstro (exceto durante a Etapa de Dano): você pode declarar um Nível de 1 a 8; esse monstro se torna desse Nível até o final do turno. \r\nVocê pode escolher 2 monstros com o mesmo Nível (1 de cada campo); destrua-os. \r\nVocê só pode usar cada efeito de "Quebramino, o Desce-e-Apaga" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84274024,'Dimensão Pêndulo',replace(replace('Se você Invocar por Invocação-Especial quaisquer destes monstros usando um ou mais Monstros Pêndulo como matéria, enquanto este card estiver com a face para cima na sua Zona de Magias & Armadilhas: você pode ativar o efeito apropriado. \r\nVocê não pode aplicar esse mesmo efeito de "Dimensão Pêndulo" pelo resto deste turno (mesmo que este card deixe o campo).\r\n● Fusão: Invoque por Invocação-Especial 1 monstro do seu Deck com o mesmo Nível original que o desse Monstro de Fusão, em Posição de Defesa, mas negue seus efeitos.\r\n● Sincro: Adicione 1 "Polimerização" do seu Deck à sua mão.\r\n● Xyz: Pegue 1 Regulador do seu Deck com um Nível igual ou menor que a Classe desse Monstro Xyz, e adicione-o à sua mão ou Invoque-o por Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84281045,'Onda Vaylantz - Fase Mestre',replace(replace('Uma vez por turno, se um card na Zona de Monstros se mover para outra Zona de Monstros (exceto durante a Etapa de Dano): você pode ativar 1 desses efeitos;\r\n● Monstros "Vaylantz" de Nível 5 ou mais que você controla atualmente ganham 1200 de ATK até o final deste turno.\r\n● Envie este card com a face para cima da Zona de Magias & Armadilhas para o Cemitério e, depois, escolha 1 Monstro de Efeito na Zona de Monstros Principal do seu oponente; coloque esse monstro do oponente com a face para cima como uma Magia Contínua na Zona de Magias & Armadilhas dele em sua mesma coluna. \r\n(Se a zona estiver ocupada, destrua o card que a estiver ocupando.)','\r',char(13)),'\n',char(10)),'Aumentar ATK','Coloque um monstro do oponente como Card de Magia','Escolha o monstro para colocar na Zona de Magia & Armadilha','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84285623,'Haniwa','Uma figura feita de Terra que protege a tumba de um antigo governante.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84288367,'Aiwass, o Espírito Divino da Lei',replace(replace('Você pode banir este card da sua mão ou do campo; adicione 1 monstro "Aleister" do seu Deck à sua mão e, depois, se este efeito foi ativado no campo, imediatamente depois que este efeito resolver, você pode Invocar 1 monstro Mago por Invocação-Normal. \r\nSe um ou mais Monstros de Fusão com a face para cima que você controla forem enviados para o Cemitério, exceto em batalha, enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial e, depois, você pode Invocar por Invocação-Fusão 1 monstro "Invokado(a)" do seu Deck Adicional, usando monstros da sua mão ou do campo. \r\nVocê só pode usar cada efeito de "Aiwass, o Espírito Divino da Lei" uma vez por turno.','\r',char(13)),'\n',char(10)),'Efeito de busca','Invocação Especial','Invocação Normal?','Invocação Fusão?','','','','','','','','','','','','');
INSERT INTO texts VALUES(84290642,'Caçador Escondido','Você pode descartar 1 card e, depois, escolha 1 card no campo; lance um dado de seis faces e destrua o alvo a não ser que o resultado seja 1 ou 6.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84298614,'Renascimento Poderoso',replace(replace('Ative este card ao escolher 1 monstro de Nível 4 ou menos no seu Cemitério; Invoque o alvo por Invocação-Especial. \r\nAumente o Nível dele em 1 e o ATK/DEF em 100. \r\nQuando esse monstro for destruído, destrua este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84305651,'Rei Goyo',replace(replace('1 Regulador + 1 ou mais Monstros Sincro não-Reguladores	\r\nQuando este card declarar um ataque contra um monstro do oponente: até o final da Etapa de Dano, este card ganha 400 de ATK para cada Monstro Sincro de TERRA do Tipo Guerreiro que você controla. \r\nQuando este card destruir um monstro do oponente em batalha e enviá-lo para o Cemitério: você pode ativar 1 desses efeitos;\r\n● Invoque esse monstro por Invocação-Especial no seu lado do campo.\r\n● Tome o controle de 1 monstro com a face para cima que seu oponente controla.','\r',char(13)),'\n',char(10)),'Aumentar ATK','Invocação Especial','Tome o controle','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84313685,'Tesseract Vylon',replace(replace('Uma vez por turno, você pode: Escolher 1 monstro "Vylon" com a face para cima que você controla; equipe este card ao alvo, OU: Desequipe este card e Invoque-o por Invocação-Especial com a face para cima em Posição de Ataque. \r\nEnquanto estiver equipado por este efeito, se o monstro equipado destruir um monstro do oponente em batalha: Você pode escolher 1 monstro "Vylon" de Nível 4 ou menos no seu Cemitério; Invoque o alvo por Invocação-Especial. \r\n(Um monstro só pode ser equipado com 1 Monstro União por vez. Se o monstro equipado seria destruído, em vez disso, destrua este card.)','\r',char(13)),'\n',char(10)),'Tornar-se um Card de Equipamento','Invocação Especial','Invocar por Invocação Especial do Cemitério','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84327329,'Clayman, o HERÓI do Elemento','Um HERÓI do Elemento com um corpo de argila construído para durar. Ele protegerá seus colegas HERÓI do Elemento a qualquer custo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84330567,'Lagrimentiara Rulkallos',replace(replace('"Lagrimentiara Kitkallos" + 1 monstro "Lagrimentiara"	\r\nOutros monstros Aqua que você controla não podem ser destruídos em batalha. \r\nVocê só pode usar cada um dos seguintes efeitos de "Lagrimentiara Rulkallos" uma vez por turno. \r\nQuando seu oponente ativar um card ou efeito que inclua um efeito que Invoque um ou mais monstros por Invocação-Especial (Efeito Rápido): você pode negar a ativação e, se isso acontecer, destrua-o e, depois, envie para o Cemitério 1 card "Lagrimentiara" da sua mão ou do campo com a face para cima. \r\nSe este card Invocado por Invocação-Fusão for enviado para o Cemitério por um efeito de card: você pode Invocar este card por Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84332527,'Therion "Touro" Ain',replace(replace('Você só pode usar cada um dos seguintes efeitos de "Therion "Touro" Ain" uma vez por turno.\r\n● Você pode escolher 1 monstro "Therion" ou 1 monstro Guerreiro no seu Cemitério; Invoque este card por Invocação-Especial da sua mão e, se isso acontecer, equipe esse monstro a este card.\r\n● Você pode escolher 1 card "Therion" que você controla e 1 card que seu oponente controla; destrua-os.	\r\nUm monstro "Therion" equipado com este card ganha 700 de ATK e, além disso, ele pode ativar o 2º efeito listado acima como se fosse "Therion "Touro" Ain".','\r',char(13)),'\n',char(10)),'','Destruir cards em ambos os campos (Therion "Touro" Ain)','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84335863,'Claustro das Rosas Brancas',replace(replace('Se você não controlar nenhum monstro: você pode Invocar por Invocação-Especial 1 monstro "Dragão da Rosa" ou 1 monstro Planta da sua mão. \r\nVocê só pode usar este efeito de "Claustro das Rosas Brancas" uma vez por turno. \r\nDurante sua Fase de Compra, antes de comprar: você pode declarar 1 tipo de card (Monstro, Magia ou Armadilha); revele o card do topo do seu Deck e se for do tipo de card declarado, aplique este efeito pelo resto deste turno (mesmo que este card deixe o campo).\r\n● Monstros Sincro de Nível 7 ou mais que você controla ganham 1000 de ATK.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84339249,'Espírito Protetor Loagaeth',replace(replace('Se este card no campo for destruído em batalha ou por um efeito de card: você pode escolher 1 monstro no campo; ele não pode ser destruído em batalha neste turno. \r\nVocê só pode usar cada um dos seguintes efeitos de "Espírito Protetor Loagaeth" uma vez por turno. \r\nSe um efeito de um monstro Fada que você controla for ativado (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão. \r\nVocê pode escolher 1 card com a face para cima que seu oponente controla e 1 monstro em Posição de Ataque que você controla; bana esse card do oponente e, se isso acontecer, coloque seu monstro em Posição de Defesa.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84341431,'Arquidemônio Gigante',replace(replace('Se este card com a face para cima no campo seria destruído por um efeito de card, em vez disso, você pode pagar 500 Pontos de Vida. \r\nEste efeito só pode ser usado uma vez enquanto este card estiver com a face para cima no campo. \r\nSe este card for destruído por um efeito de card e enviado para o Cemitério: você pode Invocar por Invocação-Especial 1 monstro "Arquidemônio" da sua mão.','\r',char(13)),'\n',char(10)),'Usar o efeito de "Arquidemônio Gigante" em vez de ser destruído?','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84343351,'Sobredragão Sincro de Asas Transparentes Cristalinas',replace(replace('2+ Reguladores ou 1 Monstro Sincro Regulador + "Dragão Sincro de Asas Transparentes"	\r\nDeve ser Invocado por Invocação-Sincro. \r\nUma vez por turno, quando outro card, ou seus efeitos, for ativado (Efeito Rápido): você pode negar a ativação e, se isso acontecer, destrua esse card, e se você destruir um monstro, este card ganha ATK igual ao ATK original desse monstro, até o final deste turno. \r\nSe este card com a face para cima Invocado por Invocação-Sincro sob o controle do seu dono deixar o campo devido a um card do oponente: você pode Invocar por Invocação-Especial 1 monstro "Asas Transparentes" do seu Deck Adicional.','\r',char(13)),'\n',char(10)),'Negar e destruir','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84361420,'Martelo do Edge','Ofereça como Tributo 1 "Lâmina Afiada, o HERÓI do Elemento" para escolher 1 monstro que seu oponente controla; destrua o alvo e cause dano ao seu oponente igual ao ATK original do alvo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84366728,'Vanguarda do Imperador Subterrâneo',replace(replace('Se um ou mais monstros forem enviados da mão para o Cemitério, enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial, mas coloque-o no fundo do Deck quando ele deixar o campo. \r\nVocê só pode usar este efeito de "Vanguarda do Imperador Subterrâneo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84384943,'Pedra de Cabrera',replace(replace('Se este card for Invocado: você pode adicionar 1 "Triângulo O" do seu Deck à sua mão e, depois, se este card estiver em Posição de Ataque, coloque-o em Posição de Defesa. \r\nVocê só pode usar este efeito de "Pedra de Cabrera" uma vez por turno. \r\nSe este card for destruído em batalha ou por um efeito de card: sofra 1000 de dano.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84385264,'Licantropo',replace(replace('Você pode Invocar este card por Invocação-Ritual com o Card de Magia de Ritual "Magia de Síntese". \r\nQuando este card causar Dano de Batalha ao seu oponente, cause 200 de dano ao seu oponente para cada Monstro Normal no seu Cemitério.','\r',char(13)),'\n',char(10)),'Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84388461,'Zefrasabre, o Mestre da Espada de Necroz',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nVocê não pode Invocar monstros por Invocação-Pêndulo, exceto monstros "Necroz" e "Zefra". \r\nEste efeito não pode ser negado.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nVocê pode oferecer este card como Tributo da sua mão ou com a face para cima no seu lado do campo; ofereça como Tributo monstros da sua mão ou do campo e, depois, Invoque por Invocação-Ritual 1 Monstro de Ritual "Necroz" da sua mão cujo Nível seja exatamente igual à soma dos Níveis desses monstros. \r\nVocê só pode usar este efeito de "Zefrasabre, o Mestre da Espada de Necroz" uma vez por turno.','\r',char(13)),'\n',char(10)),'Colocar Escala Pêndulo','Invocação Ritual','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84389640,'Ataque dos Ratos Encurralados',replace(replace('Se um Monstro Normal de Nível 3 ou menos que você controla batalhar, durante a Etapa de Dano você pode pagar PV em múltiplos de 100. \r\nO ATK do monstro do oponente é reduzido pela quantidade de PV que você pagou até a Fase Final. \r\n(Você não pode pagar mais PV do que o ATK do monstro do oponente.)','\r',char(13)),'\n',char(10)),'Reduzir ATK','Escolha os PV a pagar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84397023,'Laboratório de Conversão de Níveis',replace(replace('Escolha 1 monstro na sua mão e revele-o ao seu adversário, e em seguida lance um dado de seis lados. \r\nSe o resultado for 1, envie o monstro escolhido para o Cemitério. \r\nSe o resultado for 2-6, o Nível do monstro escolhido torna-se igual ao resultado até à End Phase deste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84401683,'Guardião Gorgônico',replace(replace('2 monstros do Tipo Rocha de Nível 3	\r\nUma vez por turno, durante o turno de qualquer duelista: você pode desassociar 1 Matéria Xyz deste card e, depois, escolher 1 monstro com a face para cima que seu oponente controla; o ATK dele se torna 0 e, se isso acontecer, seus afeitos são negados. \r\nEsses efeitos duram até o final deste turno. \r\nUma vez por turno: você pode escolher 1 monstro no campo com ATK 0; destrua-o.','\r',char(13)),'\n',char(10)),'O ATK se torna 0','Destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84401954,'Grão Blitzclique',replace(replace('Você pode revelar este card na sua mão e, depois, escolha 1 Magia/Armadilha no campo; destrua-a e, se isso acontecer, Invoque por Invocação-Especial 1 monstro Trovão da sua mão e, além disso, pelo resto deste turno, você não pode Invocar Monstros de Efeito por Invocação-Especial, exceto da mão. \r\nSe um ou mais outros cards forem destruídos por um efeito de card, enquanto este card estiver na Zona de Monstros (exceto durante a Etapa de Dano): você pode adicionar 1 Magia "Blitzclique" ou 1 "Esconderijo no Céu, Coulomb" do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "Grão Blitzclique" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Efeito de busca','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84404797,'Jarra Resgatável',replace(replace('Você pode banir 1 Armadilha do seu Cemitério; adicione do seu Cemitério à sua mão, 1 Armadilha com um nome original diferente que o desse card banido. \r\nVocê só pode usar este efeito de "Jarra Resgatável" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84417082,'Número 91: Dragão Centelha de Trovão',replace(replace('3 monstros de Nível 4	\r\nUma vez por turno, você pode ativar 1 desses efeitos.\r\n● Desassocie 3 Matérias Xyz deste card; destrua todos os outros monstros com a face para cima no campo.\r\n● Desassocie 5 Matérias Xyz deste card; destrua todos os cards que seu oponente controla.','\r',char(13)),'\n',char(10)),'3: Destrua todos os monstros com a face para cima, exceto este card','5: Destrua todos os cards que seu oponente controla','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84425220,'Dragão Armado LV10 Branco',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial por seu próprio efeito. \r\nVocê pode banir monstros "Dragão Armado" do seu campo e/ou do Cemitério cuja soma dos Níveis seja igual a 10; Invoque este card por Invocação-Especial da sua mão e, depois, você pode adicionar 1 "Véu Branco" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Dragão Armado LV10 Branco" uma vez por turno. \r\nVocê não sofre dano de efeito. \r\nNo começo da Etapa de Dano, se este card atacar: você pode destruir 1 card no campo.','\r',char(13)),'\n',char(10)),'','','Adicionar "Véu Branco" do seu Deck à sua mão?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84428023,'Wattajuste',replace(replace('Só pode ser equipado a um monstro do Tipo Trovão de Nível 3 ou menos. \r\nEle ganha 800 de ATK e, além disso, seus efeitos são negados. \r\nSempre que ele causar dano de batalha ao seu oponente: compre 1 card.','\r',char(13)),'\n',char(10)),'Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84430165,'Corrente Marincesa',replace(replace('Quando um Monstro Link "Marincesa" que você controla destruir um monstro do oponente em batalha: cause dano ao seu oponente igual ao Valor Link desse monstro que você controla x 400 e, depois, se você destruiu um Monstro Link do oponente nessa batalha enquanto você controlava um monstro "Marincesa" de Link-2 ou mais, cause dano ao seu oponente igual ao Valor Link desse monstro destruído x 500. \r\nVocê só pode ativar 1 "Corrente Marincesa" por turno. \r\nSe você controlar um monstro "Marincesa" de Link-3 ou mais, você pode ativar este card da sua mão.','\r',char(13)),'\n',char(10)),'Ativar aplicando o efeito de "Corrente Marincesa".','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84430950,'Samurai Armado - Ben Kei','Em adição ao ataque normal, este card pode atacar tantas vezes quanto o número de Cards de Equipamento equipados a este card durante a mesma Battle Phase.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84433129,'Estrela de Ryzeal',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) ao desassociar 1 matéria de um monstro que você controla. \r\nSe Invocado desta forma, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto Monstros Xyz de Classe 4. \r\nVocê só pode Invocar "Estrela de Ryzeal" por Invocação-Especial uma vez por turno desta forma. \r\nSe este card for Invocado por Invocação-Especial: você pode Baixar 1 Magia/Armadilha "Ryzeal" do seu Deck. \r\nVocê só pode usar este efeito de "Estrela de Ryzeal" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84433295,'Mago Quinteto',replace(replace('5 monstros Mago	\r\nDeve ser Invocado por Invocação-Fusão. \r\nSe este card for Invocado por Invocação-Fusão usando 5 monstros Mago com nomes diferentes: você pode destruir todos os cards que seu oponente controla. \r\nEste card com a face para cima no campo não pode ser oferecido como Tributo, nem usado como Matéria de Fusão e, além disso, ele não pode ser destruído por efeitos de card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84442536,'Combate Alicercinza',replace(replace('Quando um Card de Magia/Armadilha ou um monstro de efeito que escolher como alvo exatamente 1 monstro "Alicercinza" que você controla (e nenhum outro card) for ativado: ative 1 desses efeitos;\r\n● Esse efeito ativado se torna "Destrua esse monstro".\r\n● Negue a ativação e, se isso acontecer, destrua esse card.','\r',char(13)),'\n',char(10)),'Esse efeito se torna: « Destrua esse monstro »','Negue essa ativação e destrua-o','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84451804,'Sapo Des','Quando este card é Invocado, por Invocação-Tributo, com sucesso, você pode Invocar, por Invocação-Especial, "Sapo Des" da sua mão ou Deck num número igual ao de "T.A.D.P.O.L.E."(s) no seu Cemitério.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84453939,'Ás Psíquico','Se este card na Zona de Monstros for oferecido como Tributo: você pode escolher 1 card no campo; destrua-o.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84462118,'Dragãomordida',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode Invocar por Invocação-Especial 1 monstro Inseto de Nível 4 ou menos da sua mão. \r\nVocê pode banir 1 monstro Inseto de Nível 4 ou menos da sua mão, do Cemitério ou do campo com a face para cima e, depois, escolha 1 monstro com a face para cima que você controla; até o final deste turno, aumente o Nível dele pelo Nível do monstro banido. \r\nVocê só pode usar cada efeito de "Dragãomordida" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84464389,'Dragão Flamafatal Callibregado',replace(replace('1 Monstro Link de TREVAS + 1 monstro de TREVAS	\r\nSe este card for Invocado por Invocação-Fusão: você pode adicionar 1 monstro "Foguette" do seu Deck à sua mão. \r\nVocê pode escolher 1 monstro de TREVAS que você controla; equipe-o com 1 Monstro Link de TREVAS do seu Cemitério ou banimento como uma Magia de Equipamento que concede a ele 500 de ATK. \r\nSe este card for enviado para o Cemitério como Matéria Link: você pode escolher 1 card no campo; destrua-o. \r\nVocê só pode usar cada efeito de "Dragão Flamafatal Callibregado" uma vez por turno.','\r',char(13)),'\n',char(10)),'Efeito de busca','Efeito de Equipamento','Efeito de destruição','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84472026,'Yeti Fantardil',replace(replace('Não pode ser Invocado por Invocação-Normal, exceto se você controlar um monstro "Fantardil". \r\nUma vez por turno: você pode colocar este card com a face para baixo em Posição de Defesa. \r\nQuando este card for virado com a face para cima: você pode escolher 1 monstro "Fantardil" no campo; neste turno, ele não pode ser destruído em batalha ou por efeitos de card.','\r',char(13)),'\n',char(10)),'Mudar para Posição de Defesa com a face para baixo','Não pode ser destruído','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84477320,'Phryxul Caudraco',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 monstro "Caudraco" no seu Cemitério, exceto "Phryxul Caudraco"; Invoque-o por Invocação-Especial e, depois, devolva 1 monstro que você controla para a mão. \r\nSe este card for enviado para o Cemitério como matéria para uma Invocação-Fusão: você pode Baixar 1 Magia/Armadilha "Caudraco" do seu Deck. \r\nVocê só pode usar cada efeito de "Phryxul Caudraco" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Baixar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84478195,'Estátua Barreira do Abismo','Nenhum duelista pode Invocar monstros por Invocação-Especial, exceto monstros de TREVAS.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84482694,'Heráldica Carregada',replace(replace('Ofereça 1 monstro como Tributo; Invoque por Invocação-Especial 2 monstros "Besta Heráldica" do seu Deck em Posição de Defesa e, além disso, você não pode Invocar monstros por Invocação-Especial do Deck Adicional pelo resto deste turno depois que este card resolver, exceto monstros Psíquico ou Máquina. \r\nVocê só pode ativar 1 "Heráldica Carregada" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84488827,'Caucastag Hordeum Ferro',replace(replace('Quando este card for Invocado por Invocação-Tributo ao oferecer como Tributo 2 monstros "Hordeum Ferro": Ative 1 destes efeitos.\r\n● Destrua todos os monstros no campo, exceto este card.\r\n● Destrua todos os Cards de Magia e Armadilha no campo.','\r',char(13)),'\n',char(10)),'Escolha 1 efeito para ativar','Destrua todos os monstros no campo, exceto este card.','Destrua todos os Cards de Magia/Armadilha no campo.','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84491298,'Vírus da Explosão Celular',replace(replace('Ative apenas quando um monstro do oponente com um ou mais Marcadores-A declarar um ataque. \r\nDestrua todos os monstros em Posição de Ataque que seu oponente controla.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84504242,'Portal Megálito',replace(replace('Na primeira vez que cada monstro Invocado por Invocação-Ritual seria destruído em batalha a cada turno, ele não é destruído. \r\nSe um monstro "Megálito" for Invocado por Invocação-Especial (exceto durante a Etapa de Dano): você pode escolher 1 Monstro de Ritual no seu Cemitério; adicione-o à sua mão. \r\nVocê só pode usar este efeito de "Portal Megálito" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84521924,'MaiorSolfacorde Coolia',replace(replace('2+ monstros, incluindo um Monstro Pêndulo	\r\nGanha 100 de ATK para cada Monstro Pêndulo com a face para cima no seu Deck Adicional. \r\nOs efeitos ativados dos Monstros Pêndulo para os quais este card apontar não podem ser negados. \r\nUma vez por turno, quando seu oponente ativar um card ou efeito (Efeito Rápido): você pode Invocar por Invocação-Especial 1 card "Solfacorde" com uma Escala de Pêndulo ímpar da sua Zona de Pêndulo em uma zona sua para a qual este card apontar e, se isso acontecer, negue a ativação e, depois, você pode adicionar 1 Monstro Pêndulo "Solfacorde" com uma Escala de Pêndulo par do seu Deck ao seu Deck Adicional com a face para cima.','\r',char(13)),'\n',char(10)),'','Colocar Monstros Pêndulo do seu Deck no seu Deck Adicional?','Escolha o Monstro Pêndulo para adicionar ao Deck Adicional','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84523092,'Fazticeira Haine',replace(replace('Seu oponente não pode escolher outros monstros Mago que você controla como alvo de efeitos de card. \r\n(Efeito Rápido): você pode descartar 1 Magia e, depois, escolha 1 card com a face para cima que seu oponente controla; destrua-o. \r\nVocê só pode usar este efeito de "Fazticeira Haine" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84530620,'Patrovão','Uma vez por turno: Você pode Invocar por Invocação-Normal 1 monstro de LUZ do Tipo Trovão de Nível 4 da sua mão, exceto "Patrovão", como uma Invocação-Normal adicional.','Invocar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84536654,'Mudar a Forma',replace(replace('Escolha 1 Monstro de Fusão "HERÓI" que você controla; devolva-o para o Deck Adicional e, depois, Invoque por Invocação-Especial do seu Deck Adicional, 1 monstro "HERÓI Mascarado" com o mesmo Nível que o Nível original desse monstro, mas com um nome diferente. \r\n(Esta Invocação-Especial é considerada uma Invocação-Especial com "Mudar a Máscara".)','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84539520,'Princesa Amazoness',replace(replace('O nome deste card se torna "Rainha Amazoness" enquanto ele estiver no campo ou no Cemitério. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 Magia/Armadilha "Amazoness" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Princesa Amazoness" uma vez por turno. \r\nQuando este card declarar um ataque: você pode enviar 1 outro card da sua mão ou do campo para o Cemitério; Invoque por Invocação-Especial 1 monstro "Amazoness" do seu Deck em Posição de Defesa, exceto "Princesa Amazoness".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84544192,'Sobremarcha do Dragão Arco-Íris Cristalino Definitivo',replace(replace('1 monstro "Cristalino(a) Definitivo(a)" + 7 monstros "Fera Cristalina"	\r\nDeve ser Invocado por Invocação-Especial (do seu Deck Adicional) durante um Duelo em que você Invocou um monstro "Cristalino(a) Definitivo(a)" por Invocação-Especial, ao banir os monstros acima do seu campo e/ou Cemitério. \r\nEnquanto 7 ou mais dos seus monstros "Fera Cristalina" com nomes diferentes estiverem banidos, este card ganha 7000 de ATK. \r\nSe este card não batalhou neste turno (Efeito Rápido): você pode oferecer este card como Tributo; embaralhe no Deck tantos cards no campo quanto possível e, se isso acontecer, Invoque por Invocação-Especial qualquer número dos seus monstros "Fera Cristalina" banidos.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84546257,'Marincesa Triângulo de Coral',replace(replace('2+ monstros "Marincesa"	\r\nVocê pode enviar 1 monstro de ÁGUA da sua mão para o seu Cemitério; adicione 1 Armadilha "Marincesa" do seu Deck à sua mão. \r\nSe somente seu oponente controlar um monstro: você pode banir este card do seu Cemitério; Invoque por Invocação-Especial Monstros Link de ÁGUA do seu Cemitério cuja soma dos Valores Link seja exatamente igual a 3. \r\nVocê só pode usar cada efeito de "Marincesa Triângulo de Coral" uma vez por turno. \r\nVocê não pode Invocar monstros por Invocação-Especial no turno em que ativar qualquer um dos efeitos deste card, exceto monstros de ÁGUA.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84550200,'Aborratador Sônico','VIRE: O seu adversário não pode activar Cards de Magia até ao final da End Phase do próximo turno.','Restrição de ativação','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84550369,'Shinbu Mikanko - Gêmeas Nobres',replace(replace('Envie 1 card "Mikanko" do seu Deck para o Cemitério, exceto "Shinbu Mikanko - Gêmeas Nobres" e, depois, você pode Baixar 1 Magia/Armadilha "Mikanko" do seu Deck, exceto "Shinbu Mikanko - Gêmeas Nobres". \r\nVocê não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno depois que este card resolver, exceto monstros "Mikanko". \r\nVocê pode banir este card do seu Cemitério e desassociar 1 matéria de um monstro que você controla; Invoque por Invocação-Especial 1 Monstro de Ritual "Mikanko" da sua mão ou do Deck. \r\nVocê só pode usar 1 efeito de "Shinbu Mikanko - Gêmeas Nobres" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar','Invocação Especial','Baixar um Card de Magia/Armadilha "Mikanko"?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84565800,'Cavaleiro Lendário Hermos',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial com "Lenda do Coração". \r\nQuando este card for Invocado por Invocação-Especial: você pode escolher 1 Magia/Armadilha com a face para cima no campo; bana o alvo. \r\nUma vez por turno, quando este card for alvo de um ataque: você pode escolher 1 Monstro de Efeito no seu Cemitério; até a Fase Final do seu próximo turno, o nome deste card se torna o nome original do alvo e substitua este efeito pelos efeitos originais do alvo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84569017,'Soldado Arpoador','Este card ganha 100 de ATK para cada um de seus monstros do Tipo Peixe, Serpente Marinha e Aqua banidos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84569886,'D/D/D Armagedom Púrpura, o Super Rei do Fim',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno, antes do cálculo de dano, se um Monstro de Fusão "D/D/D" seu batalhar um monstro do oponente: você pode fazer com que esse monstro do oponente perca 1000 de ATK até o final deste turno (mesmo que este card deixe o campo).\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\n2 monstros "D/D/D"	\r\nVocê pode escolher 1 monstro em Posição de Ataque que seu oponente controla; destrua-o e, se isso acontecer, cause dano ao seu oponente igual à metade do ATK original dele. \r\nVocê só pode usar este efeito de "D/D/D Armagedom Púrpura, o Super Rei do Fim" uma vez por turno. \r\nAntes do cálculo de dano, se um monstro do oponente batalhar: você pode fazer com que seu ATK se torne igual ao seu ATK original até o final da Etapa de Dano. \r\nSe este card na Zona de Monstros for destruído: você pode colocar este card na sua Zona de Pêndulo.','\r',char(13)),'\n',char(10)),'','Destrua 1 monstro do seu oponente','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84592800,'Vídeon Morfotrônico',replace(replace('● Enquanto estiver em Posição de Ataque: Este card ganha 800 de ATK para cada Card de Equipamento equipado a ele.\r\n● Enquanto estiver em Posição de Defesa: Este card ganha 800 de DEF para cada Card de Equipamento equipado a ele.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84613836,'Armadura de Ataque Sagaz','Durante sua Fase de Compra, sempre que você comprar um ou mais Cards de Monstro "Seis Samurai": Você pode revelá-lo; Invoque-o por Invocação-Especial.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84620194,'Girochin Kuwagata','Apesar do seu pequeno tamanho, este monstro tem umas mandíbulas capazes de partir metal em cacos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84631951,'Dinovatus Docus',replace(replace('Você só pode Invocar um ou mais "Dinovatus Docus" por Invocação-Especial uma vez por turno. \r\nSe você controlar 2 ou mais monstros Dinossauro: você pode Invocar este card por Invocação-Especial da sua mão. \r\nVocê pode oferecer como Tributo 1 monstro de Nível 4 ou menos; Invoque por Invocação-Especial 1 monstro Dinossauro do seu Deck que seja 2 Níveis maior ou menor que o monstro oferecido como Tributo tinha no campo, mas destrua-o durante a Fase Final. \r\nVocê só pode usar este efeito de "Dinovatus Docus" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial da mão','Invocar por Invocação Especial do Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84635192,'Tsuru-Puru-Purun',replace(replace('Se este card estiver na sua mão: você pode escolher 1 monstro de ÁGUA na sua Zona de Monstros Principal; destrua esse monstro que você controla e, se isso acontecer, Invoque este card por Invocação-Especial na zona em que esse monstro estava e, depois, você pode destruir todos os cards com a face para cima que seu oponente controla na coluna deste card. \r\nVocê só pode usar este efeito de "Tsuru-Puru-Purun" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Destruir um card do seu oponente?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84636823,'Cancelador de Magias',replace(replace('Cards de Magia e seus efeitos no campo não podem ser ativados. \r\nNegue todos os efeitos de Magia no campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84640866,'Buraco Armadilha da Rede','Quando seu oponente Invocar um ou mais monstros por Invocação-Especial do Deck Principal ou Cemitério: bana-os com a face para baixo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84650463,'Lamacento',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode enviar 1 "Lamacento" do seu Deck para o Cemitério. \r\nSe você tiver um total de 3 cópias de "Lamacento", sejam banidos e/ou no seu Cemitério (combinados): você pode banir este card do seu Cemitério e, depois, escolher 1 monstro Serpente Marinha de Nível 5 ou mais no seu Cemitério; Invoque o alvo por Invocação-Especial. \r\nVocê só pode usar este efeito "Lamacento" uma vez por turno.','\r',char(13)),'\n',char(10)),'Enviar para o Cemitério','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84653834,'Amplificador Extrassensorial',replace(replace('Todos os monstros do Tipo Psíquico com a face para cima que você controlava quando este card foi ativado ganham 300 de ATK para cada um dos seus monstros do Tipo Psíquico que estiverem removidos de jogo quando este card resolver. \r\nDurante a Fase Final, remova de jogo todos os monstros que foram aferados por este efeito.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84664085,'Guerreiro Satélite',replace(replace('1 Regulador + 1+ Monstros Sincro não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro: você pode escolher cards que seu oponente controla, até o número de Monstros Sincro no seu Cemitério; destrua-os e, se isso acontecer, este card ganha 1000 de ATK para cada card destruído. \r\nSe este card Invocado por Invocação-Sincro for destruído: você pode Invocar por Invocação-Especial até 3 Monstros Sincro "Guerreiro(a)", "Sincron" e/ou "Poeira Estelar" de Nível 8 ou menos com nomes diferentes do seu Cemitério. \r\nVocê só pode usar cada efeito de "Guerreiro Satélite" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84673417,'Jain, o General Crepúsculo Luminoso',replace(replace('Uma vez por turno: você pode banir 1 monstro "Luminoso(a)" da sua mão ou do Cemitério e, depois, escolher 1 monstro com a face para cima no campo; até o final deste turno, ele perde ATK e DEF igual ao Nível do monstro banido x 300. \r\nUma vez por turno, se o efeito de outro monstro "Luminoso(a)" seu for ativado: envie os 2 cards do topo do seu Deck para o Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84673574,'Eneágono QQ',replace(replace('Se este card estiver na sua mão ou no Cemitério: você pode revelar 1 monstro de Nível 9 da sua mão, exceto "Eneágono QQ"; Invoque por Invocação-Especial tanto este card quanto o monstro revelado, em Posição de Defesa e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno, exceto Monstros Xyz de Classe 9 ou mais. \r\nVocê só pode usar este efeito de "Eneágono QQ" uma vez por turno. \r\nUm Monstro Xyz de Classe 9 ou mais que tenha este card como matéria ganha este efeito.\r\n● Este card ganha 900 de ATK/DEF.','\r',char(13)),'\n',char(10)),'Invocação Especial','','O efeito de "Eneágono QQ" está sendo aplicado.','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84677654,'GRANDE Vitória!?',replace(replace('Declare um Nível de 1 a 12; cada duelista lança uma moeda e se os dois resultados forem Cara, os Níveis de todos os monstros com a face para cima que você controla atualmente se tornam o Nível declarado. \r\nSe os dois resultados forem Coroa, você perde Pontos de Vida igual ao Nível declarado x 500.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84686841,'Rei Nevoeiro','Um demônio que vive numa cegante cortina de fumo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84687358,'Dragão da Força do Espelho',replace(replace('Deve ser Invocado por Invocação-Especial com "A Presa de Critias", usando "Força do Espelho". 	\r\nQuando um ou mais monstros que você controla forem escolhidos como alvo de um ataque ou por um efeito de card do oponente (exceto durante a Etapa de Dano): você pode destruir todos os cards que seu oponente controla.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84693918,'Solfacorde Solfegia',replace(replace('Escala de Pêndulo = 9\r\n[ Efeito de Pêndulo ]\r\nQuando um efeito de monstro do seu oponente for ativado no campo e resolver, se você controlar um monstro "MaiorSolfacorde", você pode negar o efeito e, depois, destrua este card. \r\nVocê só pode usar este efeito de "Solfacorde Solfegia" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe você não controlar nenhum monstro, ou todos os monstros que você controlar forem monstros "Solfacorde": você pode Invocar este card por Invocação-Especial da sua mão. \r\nDurante sua Fase Principal: você pode ativar este efeito (você também pode oferecer este card como Tributo); Invoque por Invocação-Especial 1 monstro "Solfacorde" da sua mão, exceto "Solfacorde Solfegia", ou, se você ofereceu este card como Tributo quando ativou este efeito, em vez disso, você pode Invocar por Invocação-Especial do seu Deck Adicional com a face para cima ou Cemitério. \r\nVocê só pode usar cada efeito de "Solfacorde Solfegia" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Invocação Especial','Oferecer como Tributo para ativar?','Aplicar o efeito de "Solfacorde Solfegia" para negar?','','','','','','','','','','','','');
INSERT INTO texts VALUES(84696266,'Pato Sônico','Um pato que pode caminhar à velocidade do som. Por vezes, ele não consegue lidar com o seu incrível ritmo e perde o controle.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84731222,'Memórias de Esperança',replace(replace('Compre cards igual ao número de Monstros Xyz "Número" com nomes diferentes que você controla. \r\nVocê só pode ativar 1 "Memórias de Esperança" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84740193,'Rancheiro Surpreendente',replace(replace('Apenas pode equipar este card a um monstro com um ATK igual a 1000 ou menos. \r\nDurante o cálculo de dano, aumente o ATK do monstro equipado por este card em 2500 pontos, apenas quando o monstro do seu adversário que está a combater estiver em Posição de Ataque e o seu ATK for igual a 2500 ou mais OU quando o monstro do seu adversário que está a combater estiver em Posição de Defesa e o seu DEF for igual a 2500 ou mais.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84747429,'Aerorca','Uma vez por turno: você pode banir 1 monstro Peixe, Serpente Marinha ou Aqua da sua mão e, depois, escolha 1 card com a face para cima que seu oponente controla; destrua o alvo e, depois, bana este card até sua próxima Fase de Apoio.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84749824,'Aviso Solene','Quando um ou mais monstros seriam Invocados, OU quando um Card de Magia/Armadilha, ou efeito de monstro, for ativado que inclua um efeito que Invoque um ou mais monstros por Invocação-Especial: pague 2000 PV; negue a Invocação ou ativação e, se isso acontecer, destrua-o.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84749825,'Aviso Solene','Quando um ou mais monstros seriam Invocados, OU quando um Card de Magia/Armadilha, ou efeito de monstro, for ativado que inclua um efeito que Invoque um ou mais monstros por Invocação-Especial: pague 2000 PV; negue a Invocação ou ativação e, se isso acontecer, destrua-o.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84754430,'Mekk-Cavaleiro Avram','"Olha ISSO!"','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84755744,'Salamagrande Tigre',replace(replace('Você pode descartar 1 outro card "Salamagrande"; Invoque este card por Invocação-Especial da sua mão. \r\nVocê só pode usar este efeito de "Salamagrande Tigre" uma vez por turno. \r\nSe este card que você controla seria usado como Matéria Sincro para um monstro de FOGO, você pode considerá-lo como um não-Regulador. \r\nUma vez por turno: você pode aumentar ou diminuir o Nível deste card em 1.','\r',char(13)),'\n',char(10)),'','','Aumentar o Nível','Reduzir o Nível','','','','','','','','','','','','');
INSERT INTO texts VALUES(84764038,'Scarm, Malebranche do Abismo Ardente',replace(replace('Se você controlar um monstro que não seja um monstro "Abismo Ardente", destrua este card. \r\nVocê só pode usar 1 desses efeitos de "Scarm, Malebranche do Abismo Ardente" por turno e apenas uma vez por turno.\r\n● Se você não controlar nenhuma Magia/Armadilha: você pode Invocar este card por Invocação-Especial da sua mão.\r\n● Durante a Fase Final, se este card estiver no Cemitério porque foi enviado para lá neste turno: você pode adicionar 1 monstro Demônio de TREVAS de Nível 3 do seu Deck à sua mão, exceto "Scarm, Malebranche do Abismo Ardente".','\r',char(13)),'\n',char(10)),'Invocação Especial','Procurar no Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84766279,'Gulldos Daigusto',replace(replace('1 Regulador + 1 ou mais monstros "Gusto" não-Reguladores	\r\nUma vez por turno: Você pode embaralhar 2 monstros "Gusto" do seu Cemitério no Deck Principal para escolher 1 monstro com a face para cima que seu oponente controla; destrua esse alvo.','\r',char(13)),'\n',char(10)),'Destrua 1 monstro com a face para cima que seu oponente controla','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84769941,'Super Máquina de Guerra Anti-Kaiju Mecha Dogoran',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro deve ser Invocado por Invocação-Especial (da sua mão) enquanto seu oponente controlar um monstro "Kaiju". \r\nVocê só pode controlar 1 monstro "Kaiju". \r\nUma vez por turno: você pode remover 2 Marcadores Kaiju de qualquer parte do campo; equipe 1 monstro "Kaiju" da sua mão ou do Cemitério neste card. \r\nEste card ganha ATK igual ao ATK original combinado dos monstros "Kaiju" equipados a ele por este efeito.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84778110,'Pedra Penhasco',replace(replace('Se este card for Invocado por Invocação-Especial: você pode descartar 1 card e, se isso acontecer, envie 1 Monstro de Fusão "Fóssil" do seu Deck Adicional para o Cemitério. \r\nVocê pode enviar este card do campo para o Cemitério; cause 500 de dano ao seu oponente e, depois, se "Fusão Fóssil" estiver no seu Cemitério, você pode devolver para o seu Cemitério 1 dos seus cards banidos que seja "Fusão Fóssil" ou que o mencione. \r\nVocê só pode usar cada efeito de "Pedra Penhasco" uma vez por turno.','\r',char(13)),'\n',char(10)),'Enviar do Deck Adicional para o Cemitério','Retornar o card banido para o Cemitério','Retornar os cards banidos selecionados para o Cemitério?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84792926,'Discoliseu Therion',replace(replace('Quando este card for ativado: você pode adicionar 1 monstro "Therion" do seu Deck à sua mão. \r\nUma vez por turno, se um monstro seu seria destruído em batalha, em vez disso, você pode enviar 1 card "Therion" ou 1 "Motor Interminável Sistema Argyro" do seu Deck para o Cemitério. \r\nUma vez por turno, quando um monstro for destruído em batalha e enviado para o Cemitério: você pode escolher 1 monstro "Therion" no seu Cemitério; adicione-o à sua mão. \r\nVocê só pode ativar 1 "Discoliseu Therion" por turno.','\r',char(13)),'\n',char(10)),'Adicionar à sua mão 1 monstro "Therion" do seu Deck?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84794011,'Solidão','Esta besta-guerreira brande uma foice imensa que se alimenta das almas dos assassinados.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84797028,'Noite Mecânica',replace(replace('Todos os monstros com a face para cima no campo se tornam monstros Máquina. \r\nMonstros Máquina que você controla ganham 500 de ATK/DEF e, além disso, monstros Máquina que seu oponente controla perdem 500 de ATK/DEF. \r\nVocê pode banir este card do seu Cemitério e, depois, descarte 1 card; adicione 1 monstro Máquina de TERRA do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Noite Mecânica" uma vez por turno. \r\nVocê só pode ativar 1 "Noite Mecânica" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84808313,'Pílula de Grande Evolução',replace(replace('Depois da ativação deste card, ele permanece no campo, mas destrua-o durante a 3ª Fase Final do seu oponente. \r\nOfereça como Tributo 1 monstro do Tipo Dinossauro para ativar este card; enquanto este card estiver com a face para cima no campo, você pode Invocar por Invocação-Normal monstros do Tipo Dinossauro de Nível 5 ou mais sem oferecer Tributo.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Normal sem Tributo (efeito de "Pílula de Grande Evolução")','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84812868,'Coelha Branca Luzlunar',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode escolher 1 monstro "Luzlunar" no seu Cemitério, exceto "Coelha Branca Luzlunar"; Invoque-o por Invocação-Especial em Posição de Defesa. \r\nUma vez por turno: você pode escolher Cards de Magia/Armadilha que seu oponente controla, até o número de outros cards "Luzlunar" que você controla; devolva-os para a mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84813516,'Bola Trovão',replace(replace('No final da Etapa de Dano, se um monstro batalhou: você pode Invocar este card por Invocação-Especial da sua mão. \r\nVocê pode enviar para o Cemitério 1 Armadilha da sua mão ou que estiver Baixada no seu campo; destrua todos os outros monstros na coluna deste card. \r\nSe este card na Zona de Monstros for destruído em batalha ou por um efeito de card e enviado para o Cemitério: você pode escolher 1 card no seu Cemitério; lance um dado de seis faces e, se o resultado for 6, adicione o alvo à sua mão. \r\nVocê só pode usar cada efeito de "Bola Trovão" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84814897,'Kiryu',replace(replace('Uma vez por turno, durante a sua Main Phase, você pode equipar este card a "Lâmina Sombria" como um Card de Magia de Equipamento, OU separar o Equipamento e Invocar, por Invocação-Especial, este card em Posição de Ataque com a face para cima. \r\nQuando este card é equipado pelo efeito deste card, aumente o ATK/DEF do monstro equipado em 900 pontos, e se você oferecer este card como Tributo, o monstro equipado pode atacar diretamente os Life Points do seu adversário este turno. \r\n(1 monstro pode ser equipado apenas por 1 Monstro de Union de cada vez. Se o monstro equipado com este card é destruído como resultado de um combate, em vez disso destrúa este card.)','\r',char(13)),'\n',char(10)),'Equipar','Desequipar e Invocar por Invocação Especial (Posição de Ataque com a face para cima)','O monstro equipado pode atacar diretamente neste turno','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84815190,'Baronne de Fleur',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nUma vez por turno: você pode escolher 1 card no campo; destrua-o. \r\nUma vez enquanto estiver com a face para cima no campo, quando um card ou efeito for ativado (Efeito Rápido): você pode negar a ativação e, se isso acontecer, destrua esse card. \r\nVocê só pode usar o efeito anterior de "Baronne de Fleur" uma vez por turno. \r\nUma vez por turno, durante a Fase de Apoio: você pode escolher 1 monstro de Nível 9 ou menos no seu Cemitério; devolva este card para o Deck Adicional e, se isso acontecer, Invoque esse monstro por Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','','Efeito já ativado','','','','','','','','','','','','');
INSERT INTO texts VALUES(84816244,'Bolodata',replace(replace('Se este card for Invocado por Invocação-Especial: você pode Invocar por Invocação-Especial 1 "Ficha de Data Bolota" (Ciberso/TREVAS/Nível 1/ATK 0/DEF 0). \r\nVocê só pode usar este efeito de "Bolodata" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84816245,'Ficha de Data Bolota','Invocada por Invocação-Especial com o efeito "Bolodata".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84824601,'Dama Botânica','Quando este card for enviado do campo para o Cemitério, você pode adicionar 1 monstro do Tipo Planta com 1000 ou menos de DEF do seu Deck à sua mão.','Procurar no Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84824728,'Pantera Tesouro',replace(replace('VIRE: Você pode enviar 1 Monstro Normal do seu Deck para o Cemitério.\r\nSe um monstro com a face para baixo em Posição de Defesa estiver no campo e este card estiver na sua mão: você pode Invocar este card por Invocação-Especial. \r\nVocê pode escolher até 3 monstros com a face para baixo em Posição de Defesa no campo; coloque-os em Posição de Ataque e, depois, se você colocou 3 monstros em Posição de Ataque por este efeito, cause 900 de dano ao seu oponente. \r\nVocê só pode usar cada efeito de "Pantera Tesouro" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Mudar a posição de batalha','Enviar para o Cemitério','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84834865,'Kamakiri Voador #1','Quando este card for destruído em batalha e enviado para o Cemitério: você pode Invocar por Invocação-Especial 1 monstro de VENTO com 1500 ou menos de ATK do seu Deck, com a face para cima em Posição de Ataque.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84845628,'Pássaro do Paraíso Perdido',replace(replace('Este card ganha 100 de ATK e DEF para cada monstro Regulador no seu Cemitério. \r\nUma vez por turno: você pode enviar 1 monstro Regulador da sua mão para o Cemitério e, depois, escolher 1 monstro que seu oponente controla; tome o controle dele até a Fase Final.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84847656,'Eletrificador Telecinético','Se um ou mais monstros do Tipo Psíquico no campo seriam destruídos, em vez disso, você pode pagar 500 PV e destruir este card.','Usar o efeito de "Eletrificador Telecinético" em vez de ser destruído?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84851250,'Ventobruxa - Sino da Nevasca',replace(replace('Se você não controlar nenhum monstro ou se todos os monstros que você controla forem monstros "Ventobruxa", você pode Invocar este card por Invocação-Normal sem oferecer Tributo. \r\nDurante a Fase Principal do seu oponente, se você controlar um monstro "Ventobruxa" que não seja "Ventobruxa - Sino da Nevasca" (Efeito Rápido): você pode enviar este card da sua mão ou do campo para o Cemitério; cause 500 de dano ao seu oponente. \r\nVocê só pode usar este efeito de "Ventobruxa - Sino da Nevasca" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Normal sem Tributo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84869738,'Fúria Suprema',replace(replace('Se você controlar "Rei Supremo Z-ARC": destrua tantos monstros que você controla quanto possível, exceto "Rei Supremo Z-ARC" e, se isso acontecer, Invoque por Invocação-Especial até 4 monstros "Rei Supremo Dragão" com nomes diferentes da sua mão, do Deck, do Deck Adicional e/ou do Cemitério, ignorando suas condições de Invocação. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 Monstro Xyz "Rei Supremo Dragão" que você controla; associe 2 monstros "Rei Supremo Dragão" a ele como matérias, do seu Cemitério e/ou com a face para cima do seu Deck Adicional.','\r',char(13)),'\n',char(10)),'Invocar outro monstro por Invocação Especial?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84877802,'Escudo de Magnum',replace(replace('Só pode ser equipado em um monstro do Tipo Guerreiro. \r\nAplique o efeito a seguir, dependendo da posição de batalha dele.\r\n● Posição de Ataque: Ele ganha ATK igual à sua DEF original.\r\n● Posição de Defesa: Ele ganha DEF igual ao seu ATK original.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84899094,'Dragão-Guarda do Cálice Mundial',replace(replace('Quando um card ou efeito for ativado que escolha como alvo um monstro linkado seu (Efeito Rápido): você pode enviar este card da sua mão ou do campo para o Cemitério; negue a ativação e, se isso acontecer, destrua esse card. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 Monstro Normal no seu Cemitério; Invoque-o por Invocação-Especial em Posição de Defesa em uma zona sua para a qual um Monstro Link apontar. \r\nVocê só pode usar este efeito de "Dragão-Guarda do Cálice Mundial" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84900597,'Lamia',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 monstro Réptil de Nível 8 do seu Deck à sua mão. \r\nSe este card for banido: você pode escolher 1 monstro Réptil que você controla; até o final do próximo turno, ele não pode ser destruído por efeitos de card. \r\nVocê só pode usar cada efeito de "Lamia" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84903021,'Caverguerra Mammud',replace(replace('Se você não controlar nenhum monstro ou se todos os monstros que você controla forem monstros Guerreiro, você pode Invocar este card por Invocação-Normal sem oferecer Tributo. \r\nSe um monstro Guerreiro de TERRA seu batalhar, depois do cálculo de dano: você pode escolher 1 Magia/Armadilha que seu oponente controla; destrua-o e, depois, todos os monstros "Caverguerra" que você controla atualmente ganham 200 de ATK até o final do turno do seu oponente. \r\nVocê só pode usar este efeito de "Caverguerra Mammud" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Normal sem Tributo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84905691,'Abegulha de Naturia','Quando seu oponente Invocar um ou mais monstros por Invocação-Especial (Efeito Rápido): você pode oferecer como Tributo 1 outro monstro "Naturia" com a face para cima que você controla; destrua esse(s) monstro(s).','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84914462,'Dragonute do Machado','Se este card atacar, mude-o para a Posição de Defesa no final da Etapa de Dano.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84916669,'Doriado','Um espírito da floresta cuja força emerge das árvores e da vida selvagem.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84926738,'O Imortal do Trovão',replace(replace('VIRE: Aumente os seus Life Points em 3000 pontos. \r\nDepois disso, quando este card for enviado do Campo para o Cemitério você perde 5000 Life Points.','\r',char(13)),'\n',char(10)),'Ganhar PV','Perder PV','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84932271,'Lombriga Jetelikpse','VIRE: Quanto este card for destruído e enviado para o Cemitério neste turno: Invoque-o por Invocação-Especial do Cemitério com a face para cima em Posição de Defesa.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84941194,'Imseti, a Glória de Horus',replace(replace('Se você controlar "Sarcófago do Rei", você pode Invocar este card por Invocação-Especial (do seu Cemitério). \r\nVocê só pode Invocar "Imseti, a Glória de Horus" por Invocação-Especial uma vez por turno desta forma. \r\nVocê só pode usar cada um dos seguintes efeitos de "Imseti, a Glória de Horus" uma vez por turno. \r\nVocê pode enviar 2 cards da sua mão para o Cemitério, incluindo este card; adicione 1 "Sarcófago do Rei" do seu Deck à sua mão e, depois, você pode comprar 1 card. \r\nSe um ou mais outros cards que você controla deixarem o campo por um efeito de card do oponente, enquanto este card estiver na sua Zona de Monstros (exceto durante a Etapa de Dano): você pode enviar 1 card no campo para o Cemitério.','\r',char(13)),'\n',char(10)),'','','Comprar 1 card?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84962466,'Rebelião da Besta',replace(replace('Uma vez por turno, você pode remover de jogo 1 monstro do Tipo Besta ou do Tipo Besta-Guerreira com a face para cima que você controla para selecionar 1 outro monstro do Tipo Besta ou do Tipo Besta-Guerreira que você controla. \r\nO monstro selecionado ganha o ATK original do monstro removido de jogo por este efeito.','\r',char(13)),'\n',char(10)),'Usar o efeito de "Rebelião da Besta" agora?','Aumentar ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84965420,'Chuva de Meteoros Drytron',replace(replace('Quando seu oponente Invocar um ou mais monstros por Invocação-Normal ou Especial, enquanto você controlar um Monstro de Ritual: negue a Invocação e, se isso acontecer, embaralhe esse monstro no Deck. \r\nVocê só pode ativar 1 "Chuva de Meteoros Drytron" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84968490,'Ninho do Agulheto','Envie os 5 cards do topo do seu Deck para o Cemitério.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84970821,'Maldição das Trevas','Cada vez que um Card de Magia for ativado, imediatamente depois que ele resolver, o duelista que o ativou sofre 1000 de dano.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84976088,'Dragão de Segundo Plano',replace(replace('Se este card estiver no Cemitério e você não controlar nenhum card: você pode Invocar por Invocação-Especial tanto este card quanto 1 monstro Dragão de Nível 4 ou menos da sua mão, em Posição de Defesa, mas bana este card quando ele deixar o campo. \r\nVocê só pode usar este efeito de "Dragão de Segundo Plano" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84988419,'Diva Florescente, a Coral Melodiosa',replace(replace('1 monstro "Maestra Melodiosa" + 1 monstro "Melodiosa"	\r\nNão pode ser destruído em batalha ou por efeitos de card e, além disso, você não sofre dano de batalha dos ataques envolvendo este card. \r\nSe este card batalhar um monstro Invocado por Invocação-Especial, depois do cálculo de dano: você pode causar dano ao seu oponente igual à diferença entre o ATK original desse monstro do oponente e o deste card e, se isso acontecer, destrua esse monstro do oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84990171,'Soldado Feijão','Um guerreiro-planta que ataca com sementes e uma espada.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85004150,'Inseto Digital Rinobarramento',replace(replace('2 ou mais monstros de LUZ do Tipo Inseto de Nível 7	\r\nVocê também pode Invocar este card por Invocação-Xyz ao desassociar 2 Matérias Xyz de um Monstro Xyz do Tipo Inseto de Classe 5 ou 6 que você controla e, depois, usar esse Monstro Xyz como Matéria Xyz. \r\n(Matérias Xyz associadas a esse monstro também se tornam Matéria Xyz neste card.) \r\nSe este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente. \r\nUma vez por turno, durante o turno de qualquer duelista: você pode desassociar 1 Matéria Xyz deste card; destrua o(s) monstro(s) com a face para cima com a maior DEF que seu oponente controla (em caso de empate, todos).','\r',char(13)),'\n',char(10)),'Invocar por Invocação Xyz sobrepondo em cima de um Monstro Xyz?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85008676,'Gouki Octoestiramento',replace(replace('Se um monstro do seu oponente atacar, durante o cálculo de dano (Efeito Rápido): você pode descartar este card; o dano que você sofreria dessa batalha é diminuído pela metade. \r\nQuando seu oponente ativar um efeito que causaria dano a você (mesmo durante a Etapa de Dano) (Efeito Rápido): você pode descartar este card; o dano que você sofreria desse efeito é diminuído pela metade. \r\nSe este card for enviado do campo para o Cemitério: você pode adicionar 1 card "Gouki" do seu Deck à sua mão, exceto "Gouki Octoestiramento". \r\nVocê só pode usar este efeito de "Gouki Octoestiramento" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85028288,'Jurrac Titano',replace(replace('Não pode ser Invocado por Invocação-Especial. \r\nNão pode ser alvo de efeitos de Armadilha ou de monstro. \r\nUma vez por turno: você pode banir 1 monstro "Jurrac" com ATK de 1700 ou menos do seu Cemitério; este card ganha 1000 de ATK até a Fase Final.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85032782,'Sauge de Fleur',replace(replace('Você pode escolher 1 monstro que você controla e 1 card no campo; Invoque este card por Invocação-Especial da sua mão e, se isso acontecer, destrua-os. \r\nSe este card for enviado do campo para o seu Cemitério: você pode escolher 1 outro monstro no seu Cemitério; embaralhe-o no Deck e, depois, adicione 1 monstro Planta de Nível 1 do seu Deck ou Cemitério à sua mão. \r\nVocê só pode usar cada efeito de "Sauge de Fleur" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85034450,'Pachingo-Kart Velocidaroide','Uma vez por turno: você pode descartar 1 monstro do Tipo Máquina e, depois, escolher 1 monstro no campo; destrua-o.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85055821,'Carpiponica, Besta Mística da Floresta',replace(replace('Se este card for enviado da mão para o Cemitério: você pode escolher 2 outros monstros Besta, Besta-Guerreira, Besta Alada, Inseto e/ou Planta com Tipos diferentes no seu Cemitério; embaralhe-os no Deck e, se isso acontecer, Invoque este card por Invocação-Especial. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 monstro "Besta Mística da Floresta" ou 1 monstro "Espírito Místico da Floresta" do seu Deck à sua mão, exceto "Carpiponica, Besta Mística da Floresta". \r\nVocê só pode usar cada efeito de "Carpiponica, Besta Mística da Floresta" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85059922,'Mestre do Caos',replace(replace('"Mago Negro" + 1 Monstro de Ritual "Caos" ou "Soldado do Lustro Negro"	\r\nSe este card for Invocado por Invocação-Fusão: você pode escolher 1 monstro de LUZ ou de TREVAS no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê pode oferecer como Tributo 1 monstro de LUZ e 1 de TREVAS; bana todos os monstros que seu oponente controla. \r\nSe este card Invocado por Invocação-Fusão for destruído em batalha ou por um efeito de card: você pode escolher 1 Magia no seu Cemitério; adicione-a à sua mão. \r\nVocê só pode usar cada efeito de "Mestre do Caos" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85060248,'Protetor da Mente',replace(replace('O controlador deste card deve pagar 500 PV durante cada uma de suas Fases de Apoio. \r\nSe ele não puder, destrua este card. \r\nMonstros com 2000 ou menos de ATK não podem declarar um ataque, exceto monstros do Tipo Psíquico.','\r',char(13)),'\n',char(10)),'Pagar 500 PV para manter "Protetor da Mente"?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85065943,'Santa Azamina',replace(replace('2 monstros de Nível 6 ou mais (1 Fusão + 1 Sincro)	\r\nSeu oponente não pode escolher cards no campo, Cemitério ou banimento dele, ou este card no campo, como alvo de efeitos de card. \r\nSeu oponente sofre qualquer dano de batalha que você teria sofrido. \r\nSe este card foi Invocado por Invocação-Fusão neste turno (Efeito Rápido): você pode Invocar por Invocação-Especial 1 monstro "Azamina" de Nível 9 ou menos do seu Deck ou Deck Adicional. \r\nVocê só pode usar este efeito de "Santa Azamina" uma vez por turno.','\r',char(13)),'\n',char(10)),'Não pode ser alvo','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85066822,'Dragão de Água',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial com "Ligação - H2O". \r\nO ATK dos monstros de FOGO e monstros Piro no campo se torna 0. \r\nQuando este card for destruído e enviado para o Cemitério: você pode escolher 2 "Hydrogeddon" e 1 "Oxygeddon" no seu Cemitério; Invoque-os por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85080048,'Julgamento do Trovão','Quando um monstro do Tipo Trovão for Invocado no seu lado do campo (exceto durante a Etapa de Dano): Escolha 1 card que seu oponente controla; destrua esse alvo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85080444,'Artefato Égide',replace(replace('Você pode Baixar este card da sua mão na sua Zona de Magias & Armadilhas como um Card de Magia. \r\nDurante o turno do seu oponente, se este card Baixado na Zona de Magias & Armadilhas for destruído e enviado para o seu Cemitério: Invoque-o por Invocação-Especial. \r\nSe este card for Invocado por Invocação-Especial durante o turno do seu oponente: até o final deste turno, monstros "Artefato" que você controla não podem ser escolhidos como alvo ou destruídos por efeitos de card do seu oponente.','\r',char(13)),'\n',char(10)),'Invocação Especial','Não afetado','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85087012,'Soldado Card',replace(replace('Uma vez por turno: você pode selecionar um número de 1 a 3 e, depois, envie esse número de cards do topo do seu Deck para o Cemitério; até o final deste turno, este card ganha 500 de ATK para cada card enviado para o Cemitério desta forma. \r\nSe este card que você controla for destruído e enviado para o seu Cemitério: compre 1 card.','\r',char(13)),'\n',char(10)),'Aumentar ATK','Comprar','Escolha a quantidade de cards a enviar para o Cemitério','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85101097,'Corpo Companheiro Pudim Pútrido',replace(replace('Não pode ser usado como Matéria de Fusão, Sincro ou Xyz para uma Invocação. \r\nEnquanto este card estiver com a face para cima no campo, ele não pode ser oferecido como Tributo. \r\nDurante sua Fase Final: você pode escolher 1 card nas suas Zonas de Pêndulo; destrua-o e, se isso acontecer, conceda o controle deste card para o seu oponente. \r\nDurante cada uma das suas Fases de Apoio: sofra 300 de dano.','\r',char(13)),'\n',char(10)),'Transferir o controle','Dano de efeito','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85101228,'Rede Morfotrônica','Enquanto você controlar um monstro "Morfotrônico(a)" com a face para cima, todos os monstros de Nível 4 ou mais que seu oponente controla não podem declarar um ataque ou mudar suas posições de batalha.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85103922,'Artefato Moralltach',replace(replace('Você pode Baixar este card da sua mão na sua Zona de Magias & Armadilhas como uma Magia. \r\nDurante o turno do seu oponente, se este card Baixado na Zona de Magias & Armadilhas for destruído e enviado para o seu Cemitério: Invoque-o por Invocação-Especial. \r\nSe este card for Invocado por Invocação-Especial durante o turno do seu oponente: você pode destruir 1 card com a face para cima que seu oponente controla.','\r',char(13)),'\n',char(10)),'Invocação Especial','Destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85106525,'Fogueira',replace(replace('Adicione 1 monstro Piro de Nível 4 ou menos do seu Deck à sua mão. \r\nVocê só pode ativar 1 "Fogueira" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85115440,'Tourdiche Zoodíaco',replace(replace('2 monstros de Nível 4	\r\nUma vez por turno, você também pode Invocar "Tourdiche Zoodíaco" por Invocação-Xyz ao usar 1 monstro "Zoodíaco(a)" que você controla com um nome diferente como Matéria Xyz. \r\n(Se você usou um Monstro Xyz, quaisquer Matérias Xyz associadas a ele também se tornam Matérias Xyz neste card.) \r\nEste card ganha ATK e DEF igual ao ATK e DEF de todos os monstros "Zoodíaco(a)" associados a ele como Matérias. \r\nUma vez por turno: você pode desassociar 1 Matéria Xyz deste card; adicione do seu Deck à sua mão, 1 monstro do Tipo Besta-Guerreira que possa ser Invocado por Invocação-Normal/Baixado.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Xyz sobrepondo um monstro "Zoodíaco(a)"?','Adicionar à mão um monstro Besta-Guerreira','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85119159,'Onomatopreferência',replace(replace('Quando este card for ativado: você pode adicionar 1 card "Onomat" do seu Deck à sua mão, exceto "Onomatopreferência". \r\nVocê pode escolher 1 monstro "Zubaba", "Gagaga", "Gogogo" ou "Dododo" que você controla; todos os monstros que você controla atualmente se tornam do Nível desse monstro até o final deste turno (mesmo que este card deixe o campo). \r\nVocê só pode usar este efeito de "Onomatopreferência" uma vez por turno. \r\nVocê só pode ativar 1 "Onomatopreferência" por turno.','\r',char(13)),'\n',char(10)),'','Adicionar à sua mão 1 card "Onomat" do seu Deck?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85121942,'Número C105: Boxeador Obstinado Cometa Cestus',replace(replace('4 monstros de Nível 5	\r\nSe este card destruir um monstro do oponente em batalha e enviá-lo para o Cemitério: cause dano ao seu oponente igual à metade do ATK original do monstro destruído. \r\nSe este card tiver "Número 105: Boxeador Obstinado Estrela Cestus" como matéria, ele ganha este efeito.\r\n● Uma vez por turno: você pode desassociar 1 matéria deste card e, depois, escolha 1 monstro que seu oponente controla; destrua-o e, se você destruiu um monstro com a face para cima, cause dano ao seu oponente igual ao ATK que esse monstro tinha no campo.','\r',char(13)),'\n',char(10)),'Causar dano','Destrua e cause dano','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85123771,'Esquadrão de Queda Livre Goblin',replace(replace('Se este card for Invocado por Invocação-Especial da mão em Posição de Ataque: você pode escolher 1 Monstro de Efeito com a face para cima que seu oponente controla; coloque este card em Posição de Defesa e, além disso, negue os efeitos desse monstro enquanto este monstro estiver com a face para cima em Posição de Defesa. \r\nSe um ou mais monstros forem Invocados por Invocação-Especial no campo do seu oponente, enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode descartar 1 card; adicione este card à sua mão. \r\nVocê só pode usar cada efeito de "Esquadrão de Queda Livre Goblin" uma vez por turno.','\r',char(13)),'\n',char(10)),'Negar um monstro','Adicionar este card à sua mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85136114,'Depossuído Autômato',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 monstro "Autômata(o)" no seu Cemitério, exceto "Depossuído Autômato"; Invoque-o por Invocação-Especial em Posição de Defesa, mas ele não pode ativar seus efeitos neste turno. \r\nVocê pode escolher 1 outro monstro "Autômata(o)" que você controla e 1 Magia/Armadilha que seu oponente controla; devolva-os para a mão. \r\nVocê só pode usar cada efeito de "Depossuído Autômato" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85138716,'Coelho de Socorro',replace(replace('Não pode ser Invocado por Invocação-Especial do Deck. \r\nVocê pode banir este card que você controla; Invoque por Invocação-Especial 2 Monstros Normais de Nível 4 ou menos, com o mesmo nome, do seu Deck, mas destrua-os durante a Fase Final. \r\nVocê só pode usar este efeito de "Coelho de Socorro" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85138717,'Coelho de Socorro',replace(replace('Não pode ser Invocado por Invocação-Especial do Deck. \r\nVocê pode banir este card que você controla; Invoque por Invocação-Especial 2 Monstros Normais de Nível 4 ou menos, com o mesmo nome, do seu Deck, mas destrua-os durante a Fase Final. \r\nVocê só pode usar este efeito de "Coelho de Socorro" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85150300,'Caçador Ilegal de Espíritos',replace(replace('Uma vez por turno, durante a Fase de Apoio do seu oponente: você pode ativar 1 desses efeitos;\r\n● Coloque 1 monstro do seu Deck na sua Zona de Magias & Armadilhas como uma Magia Contínua com a face para cima.\r\n● Seu oponente pode Invocar por Invocação-Especial 1 Card de Monstro com menos ATK original que seus PV da sua Zona de Magias & Armadilhas no campo dele e, depois, ele paga PV igual ao ATK original desse Card de Monstro.	\r\nSe um ou mais Monstros de Efeito dos quais você é dono forem Invocados por Invocação-Especial no campo do seu oponente: você pode enviar este card com a face para cima da Zona de Magias & Armadilhas para o Cemitério; Invoque por Invocação-Especial 1 monstro de Nível 4 ou menos do seu Deck.','\r',char(13)),'\n',char(10)),'Escolha 1 efeito para ativar','Invocação Especial','Colocar um monstro','Invocar por Invocação Especial no campo do seu oponente','Invocar por Invocação Especial o monstro?','','','','','','','','','','','');
INSERT INTO texts VALUES(85154941,'Duque Arquidemônio',replace(replace('Ganha ATK igual ao seu Nível x 200. \r\nVocê só pode usar cada um dos seguintes efeitos de "Duque Arquidemônio" uma vez por turno. \r\nVocê pode escolher 1 monstro com a face para cima que você controla e que tenha um Nível; envie 1 monstro "Arquidemônio" do seu Deck para o Cemitério, exceto "Duque Arquidemônio" e, se isso acontecer, aumente o Nível desse monstro pelo Nível do monstro enviado. \r\nQuando um Monstro de Ritual seu for destruído em batalha enquanto este card estiver no seu Cemitério: você pode Invocar este card por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Enviar para o Cemitério','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85166216,'Estátua Elefante de Benção','Quando este card é enviado diretamente da sua mão para o Cemitério, pelo efeito de um card controlado pelo seu adversário, aumente os seus Life Points em 2000 pontos.','Ganhar PV','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85182315,'O Transgressor Deus da Ruína',replace(replace('A ativação deste card, ou seus efeitos, não pode ser negada, nem seus efeitos podem ser negados. \r\nInvoque por Invocação-Especial 1 "Obelisco, o Atormentador" da sua mão ou do Cemitério e, se isso acontecer, ele não é afetado pelos efeitos de card do seu oponente neste turno. \r\nSe você oferecer como Tributo 2 ou mais monstros que você controla ao mesmo tempo para ativar um card ou efeito seu, enquanto você controlar "Obelisco, o Atormentador": você pode banir este card do seu Cemitério; bana todos os monstros no Cemitério do seu oponente e, se isso acontecer, cause 500 de dano ao seu oponente para cada um. \r\nVocê só pode usar cada efeito de "O Transgressor Deus da Ruína" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','O efeito de "O Transgressor Deus da Ruína" está sendo aplicado.','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85215458,'Asanegra - Kalut, a Lua Sombria','Durante a Etapa de Dano, quando um monstro "Asanegra" seu batalhar (Efeito Rápido): você pode enviar este card da sua mão para o Cemitério; esse monstro ganha 1400 de ATK até o final deste turno.','Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85216896,'Zefra Metaltron',replace(replace('2+ monstros Invocados por Invocação-Especial do Deck Adicional	\r\nSe um ou mais monstros para o qual este card apontar, que foram Invocados por Invocação Especial do Deck Adicional, forem destruídos em batalha ou por um efeito de card do oponente: adicione à sua mão 1 monstro do seu Cemitério ou 1 Monstro Pêndulo com a face para cima no seu Deck Adicional. \r\nVocê pode escolher 1 monstro no campo de cada duelista que foi Invocado por Invocação-Especial do Deck Adicional, exceto este card; bana os dois até a Fase Final. \r\nVocê só pode usar cada efeito de "Zefra Metaltron" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85239662,'Fada Mística Elfuria','Uma vez por turno: você pode revelar 1 monstro de VENTO da sua mão; até a próxima Fase Final do seu oponente, nenhum duelista pode utilizar monstros de Nível diferente do monstro revelado como Matéria Xyz para Invocações-Xyz.','Restrição de Invocação','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85243784,'Linkruz',replace(replace('1 Monstro Link de Link-2 ou mais	\r\nSe este card for Invocado por Invocação-Link: você pode ativar este efeito; Invoque por Invocação-Especial até um número de "Fichas Link" (Ciberso/LUZ/Nível 1/ATK 0/DEF 0) igual ao Valor Link do monstro usado para a Invocação-Link deste card e, além disso, você não pode usar "Fichas Link" como Matéria Link pelo resto deste turno. \r\nVocê só pode usar este efeito de "Linkruz" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Escolha a quantidade de Fichas a Invocar por Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85243785,'Ficha Link','Invocado por Especial com o efeito "Link Devoto" ou um card relacionado.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85250352,'Acelerador de Explosão Vulcânico',replace(replace('Ative este card ao enviar para o Cemitério 1 "Acelerador de Explosão" da sua mão, do Deck ou do campo com a face para cima. \r\nVocê só pode controlar 1 "Acelerador de Explosão Vulcânico". \r\nUma vez por turno, durante sua Fase Principal: você pode Invocar por Invocação-Especial 1 monstro "Vulcânico(a)" da sua mão. \r\nUma vez por turno: você pode escolher 1 monstro com a face para cima que seu oponente controla; envie 1 monstro Piro de Nível 1 do seu Deck para o Cemitério e, se isso acontecer, destrua esse monstro.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial da mão','Destrua 1 monstro do seu oponente','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85252081,'Besta Mech Super Quantal Pulso Orca',replace(replace('2 monstros de Nível 3	\r\nNão pode atacar a não ser que tenha matéria. \r\nUma vez por turno: você pode desassociar 1 matéria deste card e, depois, escolha 1 Magia/Armadilha no campo; destrua-a. \r\nEste é um Efeito Rápido se este card tiver "Camada Azul Super Quantum" como matéria. \r\nUma vez por turno: você pode associar 1 monstro "Super Quantum" da sua mão ou do campo a este card.','\r',char(13)),'\n',char(10)),'Destruir Magias/Armadilhas','Associar material','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85255550,'Espadachim de uma Terra Distante','Se este card atacou um monstro do oponente, depois do cálculo de dano: destrua esse monstro durante a 5ª Fase Final depois do ataque.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85257384,'Os Cavaleiros Fantasmas do Véu da Ira',replace(replace('Se você tiver um monstro "Os Cavaleiros Fantasmas" no seu campo ou Cemitério, você pode ativar este card no turno em que foi Baixado. \r\nInvoque este card por Invocação-Especial em Posição de Defesa como um Monstro Normal (Guerreiro/TREVAS/Nível 3/ATK 0/DEF 300) (este card NÃO é considerado como uma Armadilha) e, depois, você pode colocar em Posição de Defesa 1 monstro em Posição de Ataque que seu oponente controla. \r\nVocê pode banir este card do seu Cemitério; imediatamente depois que este efeito resolver, Invoque por Invocação-Xyz 1 Monstro Xyz de TREVAS. \r\nVocê só pode usar cada efeito de "Os Cavaleiros Fantasmas do Véu da Ira" uma vez por turno.','\r',char(13)),'\n',char(10)),'Ativar aplicando o efeito de "Os Cavaleiros Fantasmas do Véu Ressentido".','Invocação Xyz','Mudar a posição de batalha?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85277313,'Sinais da Tistina',replace(replace('Ative este card ao escolher 1 monstro com a face para cima no campo; Invoque este card por Invocação-Especial como um Monstro de Efeito (Aqua/LUZ/Nível 10/ATK 0/DEF 0) com o seguinte efeito (este card ainda é considerado uma Armadilha).\r\n● Durante o turno do seu oponente, quando o alvo deixar o campo, destrua este card.	\r\nDurante o turno do seu oponente, quando este card deixar o campo, destrua o alvo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85289965,'Dragão Callibrespada',replace(replace('3+ Monstros de Efeito	\r\nNão pode ser destruído em batalha. \r\nUma vez por turno (Efeito Rápido): você pode escolher 1 monstro em Posição de Ataque; coloque-o em Posição de Defesa e, além disso, este card pode realizar um segundo ataque durante cada Fase de Batalha neste turno. \r\nSeu oponente não pode ativar cards ou efeitos em resposta à ativação deste efeito. \r\nUma vez por turno, quando este card declarar um ataque contra um monstro com a face para cima: você pode ativar este efeito; até o final deste turno, este card ganha ATK igual à metade do ATK atual desse monstro e, se isso acontecer, o ATK atual desse monstro é diminuído pela metade.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85289966,'Dragão Callibrespada',replace(replace('3+ Monstros de Efeito	\r\nNão pode ser destruído em batalha. \r\nUma vez por turno (Efeito Rápido): você pode escolher 1 monstro em Posição de Ataque; coloque-o em Posição de Defesa e, além disso, este card pode realizar um segundo ataque durante cada Fase de Batalha neste turno. \r\nSeu oponente não pode ativar cards ou efeitos em resposta à ativação deste efeito. \r\nUma vez por turno, quando este card declarar um ataque contra um monstro com a face para cima: você pode ativar este efeito; até o final deste turno, este card ganha ATK igual à metade do ATK atual desse monstro e, se isso acontecer, o ATK atual desse monstro é diminuído pela metade.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85306040,'Força de Ataque de Elite Goblin','Se este card atacar, ele é colocado em Posição de Defesa no final da Fase de Batalha e sua posição de batalha não pode mudar até o final do seu próximo turno.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85309439,'Radiação & Temperatura','O Sol e o Vento do Norte se unem para criar uma combinação devastadora de tufões e de calor.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85310252,'Condutor Dododo',replace(replace('Até duas vezes por turno, se este card foi Invocado por Invocação-Especial neste turno pelo efeito de um monstro "Dododo": você pode escolher 1 monstro "Dododo" que você controla e, depois, ativar 1 desses efeitos;\r\n● Aumente o Nível dele em 1.\r\n● Reduza o Nível dele em 1.','\r',char(13)),'\n',char(10)),'Alterar Nível','Aumentar o Nível em 1','Reduzir o Nível em 1','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85313220,'Lucius das Trevas LV4',replace(replace('Negue os efeitos dos monstros do seu oponente destruídos em batalha com este card. \r\nUma vez por turno, durante a Fase de Apoio do seu próximo turno depois que este card destruiu um monstro em batalha: você pode enviar este card para o Cemitério; Invoque por Invocação-Especial 1 "Lucius das Trevas LV6" da sua mão ou do Deck.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85314178,'Rainha Cosmos, a Rainha das Orações',replace(replace('Se um Card de Magia de Campo for ativado: você pode Invocar este card por Invocação-Especial da sua mão em Posição de Defesa. \r\nVocê pode escolher 1 card com a face para cima na Zona do Campo e, depois, ative o efeito apropriado, de acordo com qual duelista controlar esse card;\r\n● Você: Destrua-o e, se isso acontecer, adicione 1 Magia de Campo com um nome diferente do seu Deck à sua mão.\r\n● Seu oponente: Negue seus efeitos (até o final deste turno) e, se isso acontecer, adicione 1 Magia de Campo do seu Deck à sua mão.	\r\nVocê só pode usar cada efeito de "Rainha Cosmos, a Rainha das Orações" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85315450,'Tufão Radiante Fonix, a Grande Chama',replace(replace('Se um Card de Magia Rápida for ativado (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe um Card de Magia Rápida for ativado (exceto durante a Etapa de Dano): você pode escolher até 2 cards que seu oponente controla; embaralhe-os no Deck. \r\nSe "Tufão Espacial Místico" for ativado enquanto este card estiver no seu Cemitério: você pode Invocar este card por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Tufão Radiante Fonix, a Grande Chama" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Retornar ao Deck','Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85325774,'Investida ao Mundo Negro',replace(replace('Escolha 1 monstro Demônio de Nível 4 ou menos no seu Cemitério; Invoque-o por Invocação-Especial e, depois, descarte 1 monstro Demônio. \r\nVocê só pode ativar 1 "Investida ao Mundo Negro" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85326399,'Seadra Espinhosa','Usando os espinhos que brotam por todo seu corpo, esta criatura apunhala seus oponentes e inunda-os de eletricidade.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85327820,'Ritual da I.A.',replace(replace('Este card pode ser usado para Invocar qualquer Monstro de Ritual Ciberso por Invocação-Ritual. \r\nVocê também deve oferecer como Tributo monstros "@Ignister" da sua mão ou do campo cuja soma dos Níveis seja igual ou exceda o Nível do Monstro de Ritual que você estiver Invocando por Invocação-Ritual. \r\nSe você controlar um monstro "@Ignister" quando este efeito for ativado, você também pode usar um ou mais monstros "@Ignister" no seu Cemitério, banindo-os.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85346853,'Paladino do Dragão de Fóton',replace(replace('Você pode Invocar este card por Invocação-Ritual com "Ritual do Dragão Brilhante". \r\nVocê pode oferecer este card como Tributo; Invoque por Invocação-Especial 1 "Dragão de Fóton de Olhos das Galáxias" da sua mão ou Deck. \r\nQuando este card destruir um monstro do oponente em batalha e enviá-lo para o Cemitério: compre 1 card.','\r',char(13)),'\n',char(10)),'Invocação Especial','Comprar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85352446,'Atenção!','Escolha 1 monstro com a face para cima de Nível 5 ou menos que seu oponente controla; destrua todos os monstros com a face para cima no campo com um Nível diferente do Nível do monstro escolhido.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85359414,'Besta Congelada',replace(replace('Uma vez por turno, durante a sua Main Phase, você pode equipar este card a "Besta em Brasa" como um Card de Magia de Equipamento, OU separar o Equipamento e Invocar, por Invocação-Especial, este card em Posição de Ataque com a face para cima. \r\nQuando este card é equipado pelo efeito deste card, cada vez que o monstro equipado inflige dano de batalha ao seu adversário, destrúa 1 Card de Magia ou Armadilha no Campo com a face para baixo. \r\n(1 monstro pode ser equipado apenas por 1 Monstro de Union de cada vez. Se o monstro equipado com este card é destruído como resultado de um combate, em vez disso destrúa este card.)','\r',char(13)),'\n',char(10)),'Equipar','Invocação Especial','Destruir','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85360035,'Punhos dos Dois Avatares - Yuhi',replace(replace('Você pode escolher 1 monstro "Dois Avatares" que você controla; destrua-o e, se isso acontecer, adicione 1 Magia "Dois Avatares" do seu Deck à sua mão. \r\nSe um ou mais Monstros de Fusão "Dois Avatares" com a face para cima que você controla, que foram Invocados por Invocação-Fusão usando um Monstro de Efeito como matéria, forem destruídos em batalha ou por um efeito de card do oponente, enquanto este card estiver no seu Cemitério: você pode adicionar este card à sua mão. \r\nVocê só pode usar cada efeito de "Punhos dos Dois Avatares - Yuhi" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão um Card de Magia "Dois Avatares"','Adicionar este card à sua mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85374678,'Camada Verde Super Quantum',replace(replace('Quando este card for Invocado por Invocação-Normal ou Especial: você pode Invocar por Invocação-Especial 1 monstro "Super Quant" da sua mão. \r\nSe este card for enviado para o Cemitério: você pode descartar 1 card "Super Quant"; compre 1 card. \r\nVocê só pode usar cada efeito de "Camada Verde Super Quantum" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Comprar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85395151,'Liberar Lavagem Cerebral',replace(replace('Se um ou mais monstros forem oferecidos como Tributo da mão ou do campo (exceto durante a Etapa de Dano): escolha 1 monstro com a face para cima que seu oponente controla; aplique o seguinte efeito, dependendo de qual duelista é dono desse monstro com a face para cima.\r\n● Você: Tome o controle dele, mas devolva-o para a mão durante a Fase Final.\r\n● Seu oponente: Negue seus efeitos até o final deste turno.	\r\nVocê só pode ativar 1 "Liberar Lavagem Cerebral" por turno.','\r',char(13)),'\n',char(10)),'Ativar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85399281,'Anjo da Sabedoria da Colheita','Quando este card for destruído em batalha e enviado para o Cemitério: você pode escolher 1 Armadilha de Resposta no seu Cemitério; adicione-a à sua mão.','Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85401123,'Mokomoko',replace(replace('VIRE: Compre 1 card.\r\nDurante sua Fase Principal: você pode colocar este card com a face para baixo em Posição de Defesa.\r\nVocê só pode usar cada um dos efeitos anteriores de "Mokomoko" uma vez por turno. \r\nSe este card batalhar um monstro, nenhum dos dois pode ser destruído nessa batalha.','\r',char(13)),'\n',char(10)),'Mudar para Posição de Defesa com a face para baixo','Comprar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85407683,'Estrelas do Novo Mundo',replace(replace('Enquanto você controlar "Visas Starfrost", na primeira vez que cada monstro que você controla seria destruído em batalha a cada turno, ele não é destruído. \r\nDurante sua Fase Final, se você controlar "Visas Starfrost": você pode escolher 1 monstro no seu Cemitério; embaralhe-o no Deck ou, se você controlar um Monstro Sincro Regulador, em vez disso, você pode adicioná-lo à sua mão. \r\nVocê só pode usar este efeito de "Estrelas do Novo Mundo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85431040,'Espinhos Malignos','Você pode oferecer este card como Tributo; cause 300 de dano ao seu oponente e, se isso acontecer, você pode Invocar por Invocação-Especial até 2 "Espinhos Malignos" do seu Deck em Posição de Ataque, mas seus efeitos não podem ser ativados.','Causar dano','Invocar "Espinhos Malignos" por Invocação Especial?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85442146,'Mente do Dragão',replace(replace('Quando um Card de Magia/Armadilha, ou efeito de monstro, for ativado enquanto você controlar um monstro com 2500 de ATK ou DEF original: negue a ativação e, se isso acontecer, destrua esse card. \r\nSe este card estiver no seu Cemitério: você pode pagar 2500 PV; Baixe este card, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar cada efeito de "Mente do Dragão" uma vez por turno.','\r',char(13)),'\n',char(10)),'Negar e destruir','Baixar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85446833,'Zerozerocha','Seu oponente não pode escolher atacar monstros com a face para cima em Posição de Ataque com 0 de ATK.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85448931,'Sentinela dos Mares','Um guerreiro tritão que ataca impiedosamente aqueles que poluem os mares com sua presença.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85457355,'Stygi-Gel, o Rei Morfo',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 outro monstro com a face para cima no campo; pelo resto deste turno, você não pode Invocar monstros do Deck Adicional por Invocação-Especial, exceto Monstros Sincro e, além disso, mude o Nível deste card para o Nível do alvo e, se isso acontecer, ganhe PV igual ao Nível do alvo x 200. \r\nDurante sua Fase Principal: você pode Invocar por Invocação-Especial da sua mão 1 monstro Demônio com um Nível menor que o deste card. \r\nVocê só pode usar este efeito de "Stygi-Gel, o Rei Morfo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85463083,'Carniçal Fantardil',replace(replace('Não pode ser Invocado por Invocação-Normal, a não ser que você controle um monstro "Fantardil". \r\nUma vez por turno: você pode colocar este card com a face para baixo em Posição de Defesa. \r\nUma vez por turno, durante sua Fase Principal 1: você pode escolher 1 monstro "Fantardil" que você controla; até o final do próximo turno do seu oponente, o ATK desse monstro se torna igual ao ATK original combinado de todos os monstros "Fantardil" atualmente no campo mas, se isso acontecer, somente esse monstro pode atacar neste turno.','\r',char(13)),'\n',char(10)),'Mudar para Posição de Defesa com a face para baixo','Alterar ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85475641,'Vingador Inférnico','Quando um monstro que você controla, exceto "Vingador Inférnico", for destruído em batalha com um monstro do oponente e enviado para o Cemitério, enquanto você não tiver cards na sua mão e este card estiver no seu Cemitério: você pode Invocar este card por Invocação-Especial e, se isso acontecer, seu Nível se torna o Nível original do seu monstro destruído.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85482105,'Velocidaroide Batedaruma',replace(replace('Se este card estiver na sua mão: você pode enviar 1 card "Velocidaroide" do seu Deck para o Cemitério, exceto "Velocidaroide Batedaruma"; Invoque este card por Invocação-Especial e, além disso, você não pode Invocar por Invocação-Especial pelo resto deste turno, exceto monstros de VENTO. \r\nSe este card for enviado do campo para o Cemitério: você pode adicionar 1 Magia/Armadilha "Velocidaroide" do seu Deck à sua mão e, depois, se você controlar um monstro "Asas Transparentes", você pode destruir 1 monstro no campo. \r\nVocê só pode usar cada efeito de "Velocidaroide Batedaruma" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Adicionar à mão','Destruir aquele monstro?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85489096,'Invocador de Arsenal','VIRE: Adicione 1 card "Guardião" do seu Deck à sua mão, exceto "Guardião Celta", "Dragão Alado, Guardião da Fortaleza Nº1", "Dragão Alado, Guardião da Fortaleza Nº2", "Guardião do Labirinto", "O Guardião de Confiança" e "Guardião Nubian".','Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85497611,'Dragão Mago de Olhos Anômalos',replace(replace('Se este card estiver na sua mão: você pode oferecer como Tributo 1 monstro de TREVAS; envie para o Cemitério 1 "Dragão de Olhos Anômalos" da sua mão, do Deck ou do campo com a face para cima e, se isso acontecer, Invoque este card por Invocação-Especial. \r\nSe este card em sua posse for destruído por um card do oponente e enviado para o seu Cemitério: você pode Invocar por Invocação-Especial 1 monstro "Olhos Anômalos" do seu Deck ou Cemitério, exceto "Dragão Mago de Olhos Anômalos" e, depois, você pode adicionar 1 "Golpe da Chama Espiral" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Invocar este card por Invocação Especial','Invocar por Invocação Especial e adicionar à mão','Adicionar "Golpe da Chama Espiral" à sua mão?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85505315,'Louva-a-Deus Hordeum Ferro','Quando este card for Invocado por Invocação-Tributo ao oferecer como Tributo um monstro "Hordeum Ferro": Você pode pagar 1000 PV para escolher 1 monstro "Hordeum Ferro" no seu Cemitério; Invoque por Invocação-Especial esse alvo.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85507811,'Neos Brilhante, o HERÓI do Elemento',replace(replace('"Neos, o HERÓI do Elemento" + "Musgo Brilhante Neoespacial"	\r\nPrimeiro deve ser Invocado por Invocação-Especial (do seu Deck Adicional) ao embaralhar os cards acima que você controla no Deck (você não usa "Polimerização"). \r\nDurante a Fase Final: Embaralhe este card no Deck Adicional. \r\nUma vez por turno, durante sua Fase Principal 1: Você pode escolher 1 card com a face para cima que seu oponente controla; destrua o alvo e, depois, aplique o efeito de acordo com seu tipo.\r\n● Monstro: Este card não pode atacar neste turno.\r\n● Magia: Este card pode atacar diretamente seu oponente neste turno.\r\n● Armadilha: Coloque este card em Posição de Defesa.','\r',char(13)),'\n',char(10)),'Retornar ao Deck','Destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85519211,'Erupção do Campo de Minas',replace(replace('Inflija 1000 pontos de dano aos Life Points do seu adversário por cada "Golem da Mina" no seu Campo com a face para cima. \r\nEm seguida, destrua todos os "Golem da Mina" no seu Campo com a face para cima.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85520170,'Estátua Sagrada de Ferro-Velho',replace(replace('Escolha 1 dos seus Monstros Sincro Dragão de Nível 7 ou 8 que estiverem banidos ou no seu Cemitério; Invoque-o por Invocação-Especial, mas devolva-o para o Deck Adicional durante a Fase Final e, além disso, depois, Baixe este card com a face para baixo em vez de enviá-lo para o Cemitério. \r\nSe este card Baixado sob o controle do seu dono for destruído por um efeito de card do oponente: você pode Invocar por Invocação-Especial 1 "Dragão Carmesim" do seu Deck Adicional. \r\nVocê só pode usar cada efeito de "Estátua Sagrada de Ferro-Velho" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85520851,'Tyranno Supercondutor',replace(replace('Uma vez por turno: você pode oferecer 1 monstro como Tributo; cause 1000 de dano ao seu oponente. \r\nEste card não pode declarar um ataque no turno em que este efeito for ativado.','\r',char(13)),'\n',char(10)),'Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85523502,'Whisker Blitzclique',replace(replace('Durante o turno em que um ou mais cards foram destruídos por um efeito de card "Blitzclique" seu (Efeito Rápido): você pode revelar este card na sua mão; Invoque por Invocação-Especial até 3 monstros Trovão da sua mão e, depois, você pode destruir até esse número de cards no campo e, além disso, pelo resto deste turno, você não pode Invocar Monstros de Efeito por Invocação-Especial, exceto da mão. \r\nQuando um efeito de monstro for ativado, exceto na mão (Efeito Rápido): você pode devolver para a mão 1 outro monstro Trovão que você controla; negue a ativação e, se isso acontecer, destrua esse monstro. \r\nVocê só pode usar cada efeito de "Whisker Blitzclique" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Negar a ativação','Destruir o card?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85528209,'Samurai Superpesado Besta Kyubi',replace(replace('1 Regulador + 1 ou mais monstros "Samurai Superpesado" não-Reguladores	\r\nEste card pode atacar enquanto estiver com a face para cima em Posição de Defesa. \r\nSe o fizer, use sua DEF para o cálculo de dano. \r\nSe você não tiver nenhum Card de Magia/Armadilha no seu Cemitério, este card ganha 900 de DEF para cada monstro Invocado por Invocação-Especial que seu oponente controla.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85541675,'Anatomia Karakuri',replace(replace('Cada vez que a posição de batalha de um monstro "Karakuri" for alterada, coloque 1 Marcador de Karakuri neste card (máx. 2). \r\nVocê pode enviar este card do campo ao Cemitério para comprar 1 card para cada Marcador de Karakuri neste card.','\r',char(13)),'\n',char(10)),'Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85545073,'Urso Peladura',replace(replace('"Diabrete de Lâminas Afiadas" + "Fofanimal Urso"	\r\nQuando este card destruir um monstro do oponente em batalha e enviá-lo para o Cemitério: você pode equipar esse monstro a este card como um Card de Magia de Equipamento com este efeito.\r\n● O monstro equipado ganha 1000 de ATK.','\r',char(13)),'\n',char(10)),'Equipar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85551711,'Alto Mago de Ébano',replace(replace('2 monstros Mago de Nível 7	\r\nEnquanto este card tiver matéria, você pode ativar um Card de Magia Rápida ou um Card de Armadilha da sua mão durante o turno do seu oponente ao desassociar 1 matéria deste card na ativação. \r\nSe este card Invocado por Invocação-Xyz for destruído em batalha e enviado para o Cemitério, ou se este card Invocado por Invocação-Xyz que você controla for enviado para o seu Cemitério por um efeito de card do oponente: você pode Invocar por Invocação-Especial 1 monstro Mago de TREVAS da sua mão ou do Deck e, depois, você pode destruir 1 card no campo.','\r',char(13)),'\n',char(10)),'Destruir 1 card no campo?','','Ativar aplicando o efeito de "Alto Mago de Ébano".','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85555787,'Vírus Túmulo Sorridente',replace(replace('(Este card não é considerado como um card "Sorridente".)	\r\nOfereça como Tributo 1 monstro de TREVAS com 3000 ou menos de ATK; seu oponente destrói 1 card (ele seleciona) na mão ou no Deck dele para cada 500 de ATK que esse monstro tinha no campo. \r\nSe você ofereceu como Tributo um monstro com 2000 ou mais de ATK para ativar este card, olhe todos os cards que seu oponente comprar até o final do 3º turno dele depois que este card resolver, e destrua todos os monstros entre eles. \r\nCards destruídos e enviados para o Cemitério pelo efeito deste card não podem ativar seus próprios efeitos nesse mesmo turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85562745,'Quarto Escuro do Pesadelo',replace(replace('Cada vez que você inflige dano que não seja dano de batalha aos Life Points do seu adversário, inflija 300 pontos de dano aos Life Points do seu adversário. \r\nO efeito deste card não é aplicado ao efeito de "Quarto Escuro do Pesadelo".','\r',char(13)),'\n',char(10)),'Cause 300 de dano ao seu oponente','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85586937,'DESPERTAÇA! Earl',replace(replace('VIRE: Você pode enviar cards com a face para cima que seu oponente controla para o Cemitério, até o número de monstros de Virar que você controla.\r\nSe este card estiver na sua mão: você pode descartar 1 outro monstro de Virar e, se isso acontecer, Invoque este card por Invocação-Especial com a face para cima em Posição de Ataque ou com a face para baixo em Posição de Defesa. \r\nDurante sua Fase Final: você pode escolher 1 monstro de Virar no seu Cemitério; Invoque-o por Invocação-Especial com a face para baixo em Posição de Defesa. \r\nVocê só pode usar cada efeito de "DESPERTAÇA! Earl" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Enviar para o Cemitério','Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85590798,'Cerimônia de Cavalestrela',replace(replace('Durante sua Fase Principal: você pode revelar 1 monstro Fada de LUZ na sua mão e, se isso acontecer, adicione 1 monstro Dragão de LUZ de Nível 7 do seu Deck à sua mão e, depois, coloque esse monstro revelado no fundo do seu Deck. \r\nSe seu oponente ativar um card ou efeito: você pode Invocar por Invocação-Especial 1 monstro Dragão de LUZ de Nível 7 da sua mão. \r\nVocê só pode usar 1 efeito de "Cerimônia de Cavalestrela" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','Invocar por Invocação Especial da mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85602018,'Testamento',replace(replace('Quando um monstro é enviado do Campo para o Cemitério durante o turno em que este card é Activado, você pode escolher 1 monstro com ATK de 1500 ou menos do seu Deck e Invocá-lo por Invocação-Especial. \r\nEm seguida, embaralhe o seu Deck. \r\nVocê pode usar o efeito deste card apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Usar o efeito de "Testamento"?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85605684,'Dragão Furioso',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial com "Um Acordo com o Senhor das Trevas" e não pode ser Invocado por Invocação-Especial de nenhuma outra forma. \r\nEste card pode atacar todos os monstros que seu oponente controla uma vez cada. \r\nDurante cada uma das suas Fases Finais, este card perde 500 de ATK.','\r',char(13)),'\n',char(10)),'Reduzir ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85636437,'Beira do Ring','Se você tiver menos PV que seu oponente: escolha 1 monstro com a face para cima que seu oponente controla; cause dano ao seu oponente igual à metade do ATK original desse monstro e, além disso, pelo resto deste turno depois que este card resolver, seu oponente não sofre dano.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85638822,'Duelo no Domo Gouki',replace(replace('Quando este card for ativado: coloque 3 marcadores neste card. \r\nSe um monstro "Gouki" seu destruir um monstro do oponente em batalha: remova 1 marcador deste card. \r\nUma vez por turno, no final da Fase de Batalha, se o último desses marcadores foi removido desta forma: você pode Invocar por Invocação-Especial tantos monstros "Gouki" quanto possível com nomes diferentes da sua mão e/ou do Deck e, depois, coloque 3 marcadores neste card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85639257,'Aqua Madoor','Um mago das águas que cria uma barreira líquida para esmagar todos aqueles que se opuserem a ele.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85640370,'Na Pontongya da Língua',replace(replace('Quando seu oponente ativar um card ou efeito ao declarar exatamente 1 nome de card: negue o efeito e, depois, você pode adicionar 1 card declarado do seu Deck à sua mão. \r\nSe este card Baixado que você controla for destruído por um efeito de card do oponente: você pode escolher 1 monstro com a face para cima que seu oponente controla; ele perde 500 de ATK.','\r',char(13)),'\n',char(10)),'Negar o efeito','Reduzir ATK','Adicionar à mão?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85646474,'Nobre do Coveiro','Quando este card que você controla for destruído em uma batalha com um monstro atacante do oponente e enviado para o seu Cemitério: você pode Invocar por Invocação-Especial 1 monstro "do Coveiro" do seu Deck com a face para baixo em Posição de Defesa, exceto "Nobre do Coveiro".','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85651167,'Gearfried, o Cavaleiro de Ferro de Olhos Vermelhos',replace(replace('Uma vez por turno, se qualquer duelista equipar um ou mais Cards de Equipamento a este card: você pode destruir esses Cards de Equipamento e, depois, você pode destruir 1 Magia/Armadilha que seu oponente controla. \r\nUma vez por turno: você pode enviar 1 Card de Equipamento que você controla que estiver equipado a este card para o Cemitério e, depois, escolha 1 monstro "Olhos Vermelhos" de Nível 7 ou menos no seu Cemitério; Invoque-o por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Destruir Cards de Equipamento','Invocação Especial','Destruir 1 Card de Magia/Armadilha que seu oponente controla?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85668449,'Laboratório de Pesquisa Cerebral',replace(replace('Uma vez por turno, você pode Invocar por Invocação-Normal 1 monstro do Tipo Psíquico em adição à sua Invocação-Normal ou Baixar. \r\nSe tiver sucesso, coloque 1 Marcador Psíquico neste card. \r\nVocê também pode colocar 1 Marcador Psíquico neste card em vez de pagar PV para ativar o efeito de qualquer monstro do Tipo Psíquico que você controla. \r\nQuando este card for removido do campo, o controlador deste card sofre 1000 de dano para cada Marcador Psíquico nele.','\r',char(13)),'\n',char(10)),'Coloque 1 "Laboratório de Pesquisa Cerebral" em "Marcador de Psíquico"','Invocar pelo efeito de "Laboratório de Pesquisa Cerebral"','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85672957,'Atômico, o HERÓI Mascarado',replace(replace('Deve ser Invocado por Invocação-Especial com "Mudar a Máscara". 	\r\nNa primeira vez que este card seria destruído em batalha ou por um efeito de card a cada turno, ele não é destruído. \r\nVocê só pode usar cada um dos seguintes efeitos de "Atômico, o HERÓI Mascarado" uma vez por turno. \r\nSe este card for Invocado por Invocação-Especial: você pode escolher 1 monstro "HERÓI Mascarado" que não seja de FOGO no seu Cemitério ou banimento; Invoque-o por Invocação-Especial em Posição de Defesa, ignorando suas condições de Invocação. \r\nDurante sua Fase Final: você pode escolher 1 Magia Rápida "Mudar" no seu Cemitério; Baixe-a.','\r',char(13)),'\n',char(10)),'Invocação Especial','','Baixar','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85673903,'Fijialert Altergeist',replace(replace('Quando um Monstro Link "Altergeist" for Invocado por Invocação-Link no seu campo (exceto durante a Etapa de Dano): você pode escolher 1 outro Monstro Link no campo; Invoque este card por Invocação-Especial da sua mão em uma zona sua para a qual o alvo apontar e, além disso, pelo resto deste turno, esse monstro também é considerado como um monstro "Altergeist". \r\nVocê só pode usar este efeito de "Fijialert Altergeist" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85679527,'Cérebro Cosmos',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nPrimeiro deve ser Invocado por Invocação-Especial ao enviar 1 Monstro que não seja de Efeito da sua mão ou com a face para cima no campo para o Cemitério. \r\nEste card ganha ATK igual ao Nível do monstro enviado para o Cemitério desta forma x 200. \r\nVocê pode oferecer 1 Monstro de Efeito como Tributo; Invoque por Invocação-Especial 1 Monstro Normal da sua mão ou do Deck. \r\nVocê só pode usar este efeito de "Cérebro Cosmos" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85682655,'Malabarista de Corda',replace(replace('Depois do cálculo de dano, se este card batalhou um monstro do oponente: você pode destruir esse monstro do oponente. \r\nEste efeito só pode ser usado uma vez enquanto este card estiver com a face para cima no campo.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85684223,'Ceifeiro no Pesadelo',replace(replace('"Ceifeiro de Espíritos" + "Cavalo Pesadelo"	\r\nEste monstro não é destruído como resultado de um combate. \r\nQuando este card é designado como alvo de um efeito de um Card de Magia, Armadilha, ou Monstro de Efeito, destrúa este card. \r\nEste monstro pode atacar diretamente os Life Points do seu adversário mesmo que exista um monstro no Campo do seu adversário. \r\nQuando este card ataca diretamente os Life Points do seu adversário, com sucesso, o seu adversário descarta 1 card da sua própria mão aleatóriamente.','\r',char(13)),'\n',char(10)),'Descartar 1 card','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85687952,'Theia, o Ser Primitivo',replace(replace('Durante a Fase Principal (Efeito Rápido): você pode oferecer monstros como Tributo cuja soma dos Níveis seja igual a 11 ou mais; Invoque este card por Invocação-Especial da sua mão e, depois, se você não controlar nenhum outro monstro, você pode destruir 1 monstro no campo com o maior ATK (em caso de empate, você seleciona). \r\nVocê só pode usar este efeito de "Theia, o Ser Primitivo" uma vez por turno. \r\nNenhum duelista pode Invocar por Invocação-Normal e/ou Especial mais de 4 vezes por turno enquanto este card estiver com a face para cima na Zona de Monstros.','\r',char(13)),'\n',char(10)),'Invocação Especial','Destruir o monstro?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85692042,'Primechamático Alembertiano',replace(replace('2+ monstros de Nível 4	\r\nVocê pode oferecer 1 monstro como Tributo; Invoque por Invocação-Especial 1 monstro "Mechamático(a)" de Nível 4 da sua mão ou do Cemitério. \r\nSe este card for Invocado por Invocação-Xyz: você pode desassociar de 2 a 4 matérias deste card e, depois, ative o efeito apropriado;\r\n● 2: Adicione 1 card "Mechamático(a)" do seu Deck à sua mão.\r\n● 3: Adicione 1 monstro de Nível 4 do seu Deck à sua mão.\r\n● 4: Adicione 1 Magia/Armadilha do seu Deck à sua mão.	\r\nVocê só pode usar cada efeito de "Primechamático Alembertiano" uma vez por turno.','\r',char(13)),'\n',char(10)),'2: Adicionar à mão um card "Mechamático(a)"','3: Adicionar à mão um monstro de Nível 4','4: Adicionar à mão um Card de Magia/Armadilha','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85696777,'Condutora Harpia',replace(replace('2 monstros de VENTO	\r\nO nome deste card se torna "Lady Harpia" enquanto estiver no campo ou no Cemitério. \r\nVocê só pode usar cada um dos seguintes efeitos de "Condutora Harpia" uma vez por turno.\r\n● Se um ou mais monstros "Harpia" que você controla seriam destruídos em batalha ou por um efeito de card, em vez disso, você pode destruir 1 Magia/Armadilha que você controla.\r\n● Se outro monstro "Harpia" com a face para cima que você controla for devolvido à sua mão (exceto durante a Etapa de Dano): você pode escolher 1 monstro Invocado por Invocação-Especial que seu oponente controla; devolva-o para a mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85698115,'Terrores da Raiz Posterior',replace(replace('Escolha 1 monstro no Cemitério do seu oponente; Invoque-o por Invocação-Especial no campo do seu oponente e, depois, você pode banir 1 monstro que seu oponente controla e, depois, se seu oponente tiver um ou mais monstros banidos, devolva 1 deles para o Cemitério. \r\nVocê pode banir este card do seu Cemitério, exceto no turno em que ele foi enviado para lá e, depois, escolha 1 monstro de Nível 1 no seu Cemitério; embaralhe esse monstro no Deck e, depois, você pode Baixar 1 "Terrores da Raiz Inferior", "Terrores da Raiz Superior" ou "Terrores da Raiz Posterior" do seu Deck.','\r',char(13)),'\n',char(10)),'Banir o monstro selecionado?','Baixar do Deck?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85704698,'Re-dici-clar',replace(replace('Escolha 1 monstro Regulador "Velocidaroide" no seu Cemitério; Invoque-o por Invocação-Especial, mas seus efeitos são negados e, além disso, lance um dado de seis faces e, até o final deste turno, o Nível dele se torna o resultado. \r\nVocê pode banir este card do seu Cemitério; imediatamente depois que este efeito resolver, Invoque por Invocação-Sincro 1 Monstro Sincro de VENTO, usando monstros que você controla incluindo um monstro Regulador "Velocidaroide".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85705804,'Kurama','Um pássaro feroz que ataca dos céus com a sua cauda-chicote.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85709845,'Gamushara',replace(replace('Quando um monstro em Posição de Defesa que você controla for escolhido como alvo de um ataque: mude esse monstro em Posição de Defesa para Posição de Ataque com a face para cima. \r\nDepois, se o monstro atacante for destruído nessa batalha e enviado ao Cemitério: Cause dano ao seu oponente igual ao ATK original desse monstro no Cemitério.','\r',char(13)),'\n',char(10)),'Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85718645,'Delg, o Monarca Negro',replace(replace('Quando este card for Invocado por Invocação-Normal ou Especial: você pode escolher até 2 cards no Cemitério do seu oponente; bana o(s) alvo(s) e, depois, envie o mesmo número de cards do topo do Deck dele para o Cemitério. \r\nEste card não pode atacar durante o turno em que for Invocado por Invocação-Normal ou Especial.','\r',char(13)),'\n',char(10)),'Banir até 2 cards no Cemitério do seu oponente','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85742772,'União Gravítica','Monstros de Nível 4 ou mais não podem atacar.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85747929,'Dragão de Fóton das Galáxias',replace(replace('2 monstros de Nível 4	\r\nOutros monstros de LUZ que você controla ganham 500 de ATK. \r\nVocê só pode usar cada um dos seguintes efeitos de "Dragão de Fóton das Galáxias" uma vez por turno. \r\nVocê pode desassociar 1 matéria deste card; adicione 1 card "Fóton" ou "Galáxia" do seu Deck à sua mão, ou envie-o para o Cemitério. \r\nSe um ou mais monstros de LUZ forem Invocados por Invocação-Especial no seu campo (exceto durante a Etapa de Dano): você pode escolher 1 desses monstros; o Nível dele se torna 4 ou 8 até o final deste turno.','\r',char(13)),'\n',char(10)),'','Alterar o Nível','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85753549,'Mikazukinoyaiba, o Dragão Presa da Lua',replace(replace('Durante a Fase Final, se este card estiver na sua mão ou no Cemitério: você pode Invocá-lo por Invocação-Especial, mas coloque-o no fundo do Deck quando ele deixar o campo. \r\nVocê pode descartar 1 card; adicione 1 monstro Dragão de TREVAS de Nível 7 do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "Mikazukinoyaiba, o Dragão Presa da Lua" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85754829,'Lombriga Gulse',replace(replace('Sempre que um monstro com a face para baixo em Posição de Defesa for virado com a face para cima, coloque 1 Marcador de Lombriga neste card. \r\nEste card ganha 300 de ATK para cada Marcador de Lombriga nele.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85758066,'Espelho do Truque Mágico',replace(replace('Quando um monstro do oponente declarar um ataque: escolha 1 Magia no Cemitério do seu oponente; Baixe-a no seu campo. \r\nVocê pode banir este card do seu Cemitério e enviar para o Cemitério 1 "Reviver Monstro" da sua mão ou do campo com a face para baixo; Invoque por Invocação-Especial 1 "Obelisco, o Atormentador" do seu Cemitério em Posição de Defesa e, se você ativou este efeito durante o turno do seu oponente, todos os monstros que seu oponente controla que podem atacar devem atacar esse monstro com a face para cima, neste turno, enquanto você o controlar.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85763457,'Lamento do Legado Mundial',replace(replace('Quando seu oponente ativar um Card de Magia/Armadilha, ou efeito de monstro, enquanto você controlar um ou mais monstros co-linkados: negue a ativação e, se isso acontecer, destrua esse card. \r\nVocê só pode ativar 1 "Lamento do Legado Mundial" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85766789,'Dádiva Cristalina',replace(replace('Invoque por Invocação-Especial até 2 Cards de Monstro "Fera Cristalina" da sua Zona de Magias & Armadilhas e, se isso acontecer, ganhe PV igual ao ATK original combinado deles. \r\nSe um ou mais cards "Fera Cristalina" forem colocados na sua Zona de Magias & Armadilhas enquanto este card estiver no seu Cemitério, mesmo durante a Etapa de Dano: você pode banir este card; escave o card do topo do seu Deck e, se for um monstro "Fera Cristalina", adicione-o à sua mão ou Invoque-o por Invocação-Especial. \r\nCaso contrário, envie esse card para o Cemitério. \r\nVocê só pode usar este efeito de "Dádiva Cristalina" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85771019,'Senhor Obscuro Asmodeus',replace(replace('Não pode ser Invocado por Invocação-Especial do Deck ou Cemitério. \r\nUma vez por turno: você pode enviar 1 monstro do Tipo Fada do seu Deck para o Cemitério. \r\nSe este card que você controla for destruído e enviado para o seu Cemitério: Invoque por Invocação-Especial 1 "Ficha de Asmo" (Tipo Fada/TREVAS/Nível 5/ATK 1800/DEF 1300) e 1 "Ficha Deus" (Tipo Fada/TREVAS/Nível 3/ATK 1200/DEF 1200). "Ficha Asmo" não pode ser destruída por efeitos de card. "Ficha Deus" não pode ser destruída em batalha.','\r',char(13)),'\n',char(10)),'Enviar 1 monstro Fada para o Cemitério','Invocar uma Ficha por Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85771020,'Ficha de Asmo','Invocado por Especial com o efeito "Senhor Obscuro Asmodeus". Esta Ficha não pode ser destruída por efeitos de card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85771021,'Ficha Deus','Invocado por Especial com o efeito "Senhor Obscuro Asmodeus". Esta Ficha não pode ser destruída em batalha.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85775486,'Reiniciar','Embaralhe 1 monstro "Senhormek" da sua mão no Deck e, depois, escolha 1 card "Senhormek" no seu Cemitério; adicione o alvo à sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85787173,'Próxima Geração',replace(replace('Se você tiver menos PV que seu oponente: adicione à sua mão, ou Invoque por Invocação-Especial, 1 monstro "HERÓI do Elemento", monstro "Kuriboh" ou monstro "Neoespacial" do seu Deck ou Cemitério, com ATK igual ou menor que a diferença de PV e, além disso, pelo resto deste turno, você não pode ativar cards ou os efeitos de cards com o mesmo nome que o desse card. \r\nVocê só pode ativar 1 "Próxima Geração" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85800949,'Cavaleiro Lendário Critias',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial com "Lenda do Coração". \r\nQuando este card for Invocado por Invocação-Especial: você pode escolher 1 Magia/Armadilha com a face para cima no campo; bana o alvo. \r\nQuando este card for escolhido como alvo de um ataque: você pode escolher 1 Armadilha no seu Cemitério; Baixe o alvo. \r\nEle pode ser ativado neste turno.','\r',char(13)),'\n',char(10)),'','','Ativar aplicando o efeito de "Cavaleiro Lendário Critias".','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85802526,'Sereia Restauradora','Enquanto este card permanecer com a face para cima no seu lado do campo, aumente seus PV em 800 pontos durante cada uma de suas Fases de Apoio.','Ganhar PV','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85808813,'Fluxo do Tempo',replace(replace('Escolha 1 Monstro de Fusão "Fóssil" que você controla; ofereça-o como Tributo e, se isso acontecer, Invoque por Invocação-Especial 1 Monstro de Fusão "Fóssil" do seu Deck Adicional, cujo Nível original seja 2 a mais que o desse monstro. \r\n(Isso é considerado uma Invocação-Fusão com "Fusão Fóssil".) \r\nDurante sua Fase Principal, exceto no turno em que este card foi enviado para o Cemitério: você pode banir este card e 1 Monstro de Fusão "Fóssil" do seu Cemitério e, depois, escolha 1 Monstro de Fusão "Fóssil" no seu Cemitério; Invoque-o por Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85821180,'Delírio do Regulador','Descarte 1 monstro; Invoque por Invocação-Especial do seu Deck, 1 monstro Regulador com o mesmo Tipo e Atributo originais, mas 1 Nível maior que o monstro descartado tinha na mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85827713,'Noite Fantardil',replace(replace('Enquanto um monstro "Fantardil" estiver no campo, seu oponente não pode Invocar por Invocação-Virar. \r\nQuando este card em sua posse for destruído por um card do seu oponente e enviado para o seu Cemitério: seu oponente não pode declarar ataques pelo restante deste turno.','\r',char(13)),'\n',char(10)),'Não pode declarar um ataque','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85839825,'Energia Xyz','Desassocie 1 Matéria Xyz que você controla para escolher 1 monstro com a face para cima que seu oponente controla; destrua esse alvo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85840608,'Conector do Neo Espaço',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode Invocar por Invocação-Especial 1 monstro "Neoespacial" ou 1 "Neos, o HERÓI do Elemento" da sua mão ou do Deck em Posição de Defesa. \r\nVocê pode oferecer este card como Tributo e, depois, escolher 1 monstro "Neoespacial" ou 1 "Neos, o HERÓI do Elemento" no seu Cemitério; Invoque-o por Invocação-Especial em Posição de Defesa. \r\nVocê só pode usar cada efeito de "Conector do Neo Espaço" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85847157,'Prova de Pruflas',replace(replace('Se você não controlar nenhum monstro Invocado por Invocação-Especial: você pode Invocar este card por Invocação-Especial da sua mão e, além disso, você não pode Invocar outros monstros por Invocação-Especial pelo resto deste turno. \r\nVocê só pode usar este efeito de "Prova de Pruflas" uma vez por turno. \r\nSe este card for Invocado por Invocação-Normal ou Especial, você pode (exceto durante a Etapa de Dano): imediatamente depois que este efeito resolver, Invocar 1 monstro por Invocação-Tributo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85852291,'Martelo Mágico','Embaralhe qualquer número de cards da sua mão no Deck e, depois, compre esse mesmo número de cards.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85854214,'Regra do Herói II','Negue a ativação de um Monstro de Efeito, Card de Magia ou Armadilha que escolha como alvo um ou mais cards no Cemitério, e destrua-o.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85862791,'Lutando Sujo',replace(replace('Se um ou mais cards que você controla e um ou mais cards que seu oponente controla forem destruídos em batalha ou por um efeito de card ao mesmo tempo: cada duelista compra 2 cards. \r\nVocê só pode ativar 1 "Lutando Sujo" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85876417,'Mil Braços, Aliado da Justiça',replace(replace('Este card pode atacar todos os monstros de LUZ com a face para cima que seu oponente controla, uma vez cada. \r\nSe este card batalhar com um monstro que não seja de LUZ, destrua este card antes do cálculo de dano.','\r',char(13)),'\n',char(10)),'Destruir este card','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85888377,'Apophis, a Divindade do Pântano','Durante a Fase Principal: Invoque este card por Invocação-Especial como um Monstro Normal (Réptil/TERRA/Nível 6/ATK 2000/DEF 2200) (este card ainda é considerado uma Armadilha) e, depois, você pode negar os efeitos dos cards com a face para cima que seu oponente controla, até o número de outras Armadilhas Contínuas que você controla, até o final deste turno.','Negar um card do seu oponente?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85893201,'Ignição da Corrente','Uma vez por turno, se um ou mais monstros que seu oponente controla forem destruídos por efeitos de card do seu oponente (exceto durante a Etapa de Dano): você pode escolher 1 card no campo; destrua o alvo.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85899505,'Timaeus, o Dragão Mágico Unido',replace(replace('"Mago Negro" ou "Pequena Maga Negra" + 1 monstro Dragão ou Mago	\r\nDepois que este card for Invocado por Invocação-Especial, ele não é afetado por outros efeitos de cards até o final do seu próximo turno. \r\nVocê só pode usar cada um dos seguintes efeitos de "Timaeus, o Dragão Mágico Unido" uma vez por turno. \r\nSe este card batalhar, durante o cálculo de dano: você pode fazer com que este card ganhe 100 de ATK para cada Magia nos Cemitérios e banimento. \r\nDurante o turno do seu oponente (Efeito Rápido): você pode escolher 1 Magia/Armadilha no campo; destrua-a.','\r',char(13)),'\n',char(10)),'Aumentar ATK','Destruir','O efeito de "Timaeus, o Dragão Mágico Unido" está sendo aplicado.','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85908279,'Cócito, o Invokado',replace(replace('"Aleister, Aquele que Invoka" + 1 monstro de ÁGUA	\r\nNão pode ser destruído pelos efeitos de card do seu oponente. \r\nSeu oponente não pode escolher este card como alvo de efeitos de card. \r\nEste card pode atacar enquanto estiver com a face para cima em Posição de Defesa. \r\nSe o fizer, aplique seu ATK no cálculo de dano.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85909450,'Dragão Fantasmal de Estimação da Harpia',replace(replace('3 monstros de VENTO de Nível 4	\r\nOs efeitos deste card só podem ser aplicados/resolvidos enquanto ele tiver matérias. \r\nEste card pode atacar diretamente seu oponente. \r\nSeu oponente não pode escolher monstros "Harpia" como alvo de efeitos ou para ataques. \r\nDurante cada uma de suas Fases Finais: desassocie 1 matéria deste card.','\r',char(13)),'\n',char(10)),'Desassociar Matéria Xyz','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85914562,'Pesquisadora Adamancipador',replace(replace('Se você controlar um monstro Rocha, exceto "Pesquisadora Adamancipador": você pode Invocar este card por Invocação-Especial da sua mão. \r\nDurante sua Fase Principal: você pode escavar os 5 cards do topo do seu Deck e, se isso acontecer, você pode Invocar por Invocação-Especial 1 monstro Rocha não-Regulador escavado de Nível 4 ou menos e, além disso, coloque o resto no fundo do seu Deck em qualquer ordem. \r\nVocê só pode usar cada efeito de "Pesquisadora Adamancipador" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Invocar por Invocação Especial o monstro?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85936485,'Resistência Unida','As pessoas que se juntam para combater os seus opressores. Vem aí uma revolução.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85967160,'Aromágico Bergamota',replace(replace('Enquanto seus PV estiverem maiores que os do seu oponente, se um monstro do Tipo Planta que você controla atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente. \r\nUma vez por turno, se você ganhar PV: este card ganha 1000 de ATK e DEF até o final do turno do seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85969517,'Navio Saquepatrollha Jord',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nVocê pode declarar 1 Atributo; devolva este card para o Deck Adicional e, se isso acontecer, Invoque por Invocação-Especial 1 "Ficha de Saquepatrollha" (Demônio/Nível 4/ATK 0/DEF 0) com esse Atributo em Posição de Defesa no campo dos dois duelistas. \r\nVocê só pode usar este efeito de "Navio Saquepatrollha Jord" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\n1 Regulador + 1+ monstros não-Reguladores	\r\nSe seu oponente Invocar um ou mais monstros por Invocação-Especial (exceto durante a Etapa de Dano): você pode adicionar 1 card "Saquepatrollha" do seu Deck à sua mão e, depois, se este card estiver equipado com um card "Saquepatrollha", você pode Invocar por Invocação-Especial 1 monstro "Saquepatrollha" do seu Deck. \r\nVocê pode escolher 1 card "Saquepatrollha" no seu Cemitério; adicione-o à sua mão e, se isso acontecer, coloque este card na sua Zona de Pêndulo. \r\nVocê só pode usar cada efeito de "Navio Saquepatrollha Jord" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Adicione 1 card "Saquepatrollha" do seu Deck à sua mão','Invocar novamente 1 monstro "Saquepatrollha" do seu Deck por Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85969518,'Ficha de Saquepatrollha','Invocado por Especial com o efeito "Navio Saquepatrollha Jord".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85970321,'Yosenju Izna',replace(replace('Uma vez por turno, durante a Fase Final, se este card foi Invocado por Invocação-Normal neste turno: devolva-o para a mão. \r\nVocê só pode usar cada um dos seguintes efeitos de "Yosenju Izna" uma vez por turno.\r\n● Você pode descartar este card; neste turno, seu oponente não pode ativar cards ou efeitos quando um ou mais monstros "Yosenju" forem Invocados por Invocação-Normal ou Especial.\r\n● Se você controlar outro monstro "Yosenju": você pode comprar 1 card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85976588,'Fortuna de Elfnota',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) em sua Zona de Monstros Principal central. \r\nVocê só pode Invocar "Fortuna de Elfnota" por Invocação-Especial uma vez por turno desta forma. \r\nVocê só pode usar cada um dos seguintes efeitos de "Fortuna de Elfnota" uma vez por turno. \r\nDurante sua Fase Principal: você pode colocar 1 Armadilha Contínua "Elfnota" da sua mão ou do Deck com a face para cima no seu campo. \r\nDurante o turno do seu oponente (Efeito Rápido): você pode trocar as localizações deste card na sua Zona de Monstros Principal e o monstro na sua Zona de Monstros Principal central e, depois, você pode devolver 1 Magia/Armadilha com a face para cima no campo para a mão.','\r',char(13)),'\n',char(10)),'Baixar uma Armadilha','Trocar posições','Retornar uma Magia/Armadilha para a mão?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85991529,'Planeta Obscuro de Kozmo',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nVocê deve Invocá-lo por Invocação-Especial (da sua mão) ao banir monstros "Kozmo" da sua mão cuja soma dos Níveis seja igual a 10 ou mais e não pode ser Invocado por Invocação-Especial de nenhuma outra forma. \r\nNão pode ser escolhido como alvo de efeitos de card do oponente. \r\nDurante o turno de qualquer duelista, quando um Card de Magia for ativado: você pode banir 1 monstro "Kozmo" do seu Cemitério; negue a ativação e, se isso acontecer, destrua esse card. \r\nSe este card for destruído em batalha ou por um efeito de card e enviado para o Cemitério: você pode banir este card do seu Cemitério; adicione 1 monstro "Kozmo" de Nível 9 ou menos do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Negar a ativação e destruir','Adicionar à mão um monstro "Kozmo" do seu Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86013171,'Leão Medroso de Kozmo',replace(replace('Durante o turno de qualquer duelista: você pode banir este card; Invoque por Invocação-Especial 1 monstro "Kozmo" de Nível 3 ou mais da sua mão. \r\nVocê só pode usar este efeito de "Leão Medroso de Kozmo" uma vez por turno. \r\nUma vez por turno: você pode pagar 500 PV e, depois, escolher 3 dos seus monstros "Kozmo" banidos; devolva-os para o Cemitério e, se isso acontecer, cause 500 de dano ao seu oponente.','\r',char(13)),'\n',char(10)),'Invoque por Invocação Especial 1 monstro "Kozmo" da sua mão','Retornar ao Cemitério os monstros "Kozmo" banidos','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86016245,'Orgulho dos Fracos','Quando um monstro de Nível 2 ou menos que você controla destruir um monstro do oponente em batalha e enviá-lo ao Cemitério, se você não tiver cards na sua mão, compre 2 cards.','Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86028783,'Lady Guerreira Novata',replace(replace('Quando um ataque for declarado envolvendo um outro monstro Guerreiro seu e um monstro com a face para cima do oponente: você pode enviar este card da sua mão ou do campo para o Cemitério; até o final deste turno, esse monstro do oponente perde ATK igual ao seu ATK original. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 monstro Guerreiro de TERRA no seu Cemitério; adicione-o à sua mão. \r\nVocê só pode usar cada efeito de "Lady Guerreira Novata" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86038337,'Faisan, o Batedor Caçador da Floresta Profunda',replace(replace('2 monstros Guerreiro de TERRA	\r\nNão é afetado pelos efeitos ativados do seu oponente, apenas durante a Fase Principal. \r\nDurante a Fase de Batalha (Efeito Rápido): você pode oferecer como Tributo este card Invocado por Invocação-Fusão; Invoque por Invocação-Especial 2 monstros Guerreiro de TERRA do seu Cemitério, exceto "Faisan, o Batedor Caçador da Floresta Profunda" e, se isso acontecer, seus monstros Guerreiro de TERRA não podem ser destruídos em batalha pelo resto deste turno. \r\nVocê só pode usar este efeito de "Faisan, o Batedor Caçador da Floresta Profunda" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86039057,'Cavaleiro Tasuke',replace(replace('Quando um monstro do oponente declarar um ataque enquanto você não tiver cards na sua mão e este card estiver no seu Cemitério: você pode Invocar este card por Invocação-Especial do seu Cemitério e, depois, encerrar a Fase de Batalha. \r\nVocê só pode usar este efeito de "Cavaleiro Tasuke" uma vez por Duelo.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86049351,'Último Contragolpe',replace(replace('Quando um ataque for declarado envolvendo um monstro "Boxeador Obstinado" que você controla e um monstro do oponente: negue o ataque e, se isso acontecer, envie esse monstro que você controla para o Cemitério e, depois, 1 monstro "Boxeador Obstinado" que você controla (em Posição de Ataque, se você declarou o ataque) ganha ATK igual ao ATK original desse monstro do oponente e, além disso, prossiga para o cálculo de dano usando esses monstros. \r\nDepois, você sofre dano igual ao valor de ATK ganho por este efeito.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86060749,'Velocidade Zero','Quando um Card de Magia/Armadilha, ou efeito de monstro, for ativado que negue a Invocação OU a ativação de um Card de Magia/Armadilha: bana 3 cards do topo do seu Deck, com a face para baixo; negue a ativação e, se isso acontecer, embaralhe esse card no Deck.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86062400,'Vingador Xyz',replace(replace('Este card não é afetado pelos efeitos de Monstros Xyz. \r\nQuando este card for destruído em batalha com um Monstro Xyz e enviado para o Cemitério: ative 1 desses efeitos, dependendo da Classe do Monstro Xyz que destruiu este card;\r\n● Classe 3 ou menor: Seu oponente envia 1 card do Deck Adicional dele para o Cemitério.\r\n● Classe 4: Escolha 1 card no Deck Adicional do seu oponente e envie-o para o Cemitério.\r\n● Classe 5 ou mais: Seu oponente envia tantos cards do Deck Adicional dele para o Cemitério quantos forem possível, mas não mais que a Classe do Monstro Xyz.','\r',char(13)),'\n',char(10)),'Enviar do Deck Adicional para o Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86066372,'Acessocodificar Transmissor',replace(replace('2+ Monstros de Efeito	\r\nSeu oponente não pode ativar cards ou efeitos em resposta às ativações de efeitos deste card. \r\nSe este card for Invocado por Invocação-Link: você pode escolher 1 Monstro Link que foi usado como sua Matéria Link; este card ganha ATK igual ao Valor Link desse monstro x 1000. \r\nVocê pode banir 1 Monstro Link do seu campo ou Cemitério; destrua 1 card que seu oponente controla e, além disso, pelo resto deste turno, você não pode banir monstros com esse mesmo Atributo para ativar este efeito de "Acessocodificar Transmissor".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86066373,'Acessocodificar Transmissor',replace(replace('2+ Monstros de Efeito	\r\nSeu oponente não pode ativar cards ou efeitos em resposta às ativações de efeitos deste card. \r\nSe este card for Invocado por Invocação-Link: você pode escolher 1 Monstro Link que foi usado como sua Matéria Link; este card ganha ATK igual ao Valor Link desse monstro x 1000. \r\nVocê pode banir 1 Monstro Link do seu campo ou Cemitério; destrua 1 card que seu oponente controla e, além disso, pelo resto deste turno, você não pode banir monstros com esse mesmo Atributo para ativar este efeito de "Acessocodificar Transmissor".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86088138,'Ocubeam','Com uma aparência assustadora, esta criatura usa o seu grande olho e orelhas para acompanhar qualquer movimento.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86098176,'Lich de Ataque',replace(replace('Se este card que você controla seria usado como Matéria Sincro, você pode considerá-lo como um não-Regulador. \r\nVocê só pode usar cada um dos seguintes efeitos de "Lich de Ataque" uma vez por turno. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode Invocar por Invocação-Especial 1 monstro que mencione "Ativar Modo de Ataque", ou 1 monstro Zumbi de Nível 4 ou menos do seu Cemitério. \r\nSe este card for enviado para o Cemitério como Matéria Sincro: você pode adicionar 1 "Corte de Ataque" ou "Contra Ataque" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Invocação Especial','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86099788,'O Último Guerreiro de Outro Planeta',replace(replace('"Zombyra, o Negro" + "Maryokutai"	\r\nSe este card for Invocado por Invocação-Especial: destrua todos os outros monstros que você controla. \r\nNenhum duelista pode Invocar monstros.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86100785,'Devorador de Zona','Um monstro atacado por este card será destruído durante a Fase Final do 5º turno após o ataque.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86111442,'Sentinela da Tistina',replace(replace('Se este card estiver na sua mão ou no Cemitério e você controlar um monstro "Tistina" de LUZ: você pode Invocar este card por Invocação-Especial. \r\nVocê pode escolher 1 monstro "Tistina" ou 1 card com a face para baixo que você controla; destrua-o e, depois, adicione 1 card "Tistina" do seu Deck à sua mão. \r\nVocê só pode usar cada efeito de "Sentinela da Tistina" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86120751,'Aleister, Aquele que Invoka',replace(replace('(Efeito Rápido): você pode enviar este card da sua mão para o Cemitério e, depois, escolha 1 Monstro de Fusão que você controla; ele ganha 1000 de ATK/DEF até o final deste turno. \r\nSe este card for Invocado por Invocação-Normal ou virado com a face para cima: você pode adicionar 1 "Invokação" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86120752,'Aleister, Aquele que Invoka',replace(replace('(Efeito Rápido): você pode enviar este card da sua mão para o Cemitério e, depois, escolha 1 Monstro de Fusão que você controla; ele ganha 1000 de ATK/DEF até o final deste turno. \r\nSe este card for Invocado por Invocação-Normal ou virado com a face para cima: você pode adicionar 1 "Invokação" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86124104,'Demise, o Agente do Armagedom',replace(replace('Você pode Invocar este card por Invocação-Ritual com "Ciclo do Mundo". \r\nO nome deste card se torna "Demise, o Rei do Armagedom" enquanto estiver na mão ou no campo. \r\nSe este card for Invocado por Invocação-Ritual: destrua 1 monstro com a face para cima no campo. \r\nSe este card for enviado para o Cemitério: você pode escolher 1 Monstro de Ritual que você controla; enquanto ele estiver com a face para cima no seu campo, seu oponente não pode ativar cards ou efeitos em resposta à ativação dos efeitos dos seus Monstros de Ritual.','\r',char(13)),'\n',char(10)),'','','O efeito de "Demise, o Agente do Armagedom" está sendo aplicado.','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86132414,'Abismo das Bestas Sagradas',replace(replace('Você pode enviar 3 "Abismo das Bestas Sagradas" com a face para cima que você controla para o Cemitério, incluindo este card e, depois, escolha 1 monstro com a face para cima que seu oponente controla; coloque-o com a face para baixo em Posição de Defesa. \r\nVocê só pode usar cada um dos seguintes efeitos de "Abismo das Bestas Sagradas" uma vez por turno. \r\nDurante a Fase Principal: você pode colocar 2 "Abismo das Bestas Sagradas" da sua mão, do Deck e/ou do Cemitério, com a face para cima no seu campo. \r\nDurante a Fase Final do seu oponente, se este card estiver no seu Cemitério: você pode colocar este card no fundo do Deck.','\r',char(13)),'\n',char(10)),'Colocar com a face para cima','Mudar para Posição de Defesa com a face para baixo','Retornar ao Deck','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86133013,'Barreira de Resistência a Nível',replace(replace('Se um ou mais monstros que você controla forem destruídos em batalha ou por um efeito de card do oponente: escolha 1 desses monstros; Invoque por Invocação-Especial um ou mais monstros do seu Deck, em Posição de Defesa, de forma que o Nível combinado deles seja igual ao Nível desse monstro, mas negue seus efeitos. \r\nVocê só pode ativar 1 "Barreira de Resistência a Nível" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86137485,'Sargentos de Estígia',replace(replace('1 Regulador Demônio + 1+ monstros não-Reguladores	\r\nQuando este card destruir um monstro do oponente em batalha e enviá-lo para o Cemitério: você pode fazer com que este card ganhe 800 de ATK até o final da Fase de Batalha e, além disso, este card pode realizar um segundo ataque em seguida.','\r',char(13)),'\n',char(10)),'Continuar atacando','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86148577,'Dragão-Guarda Elpy',replace(replace('1 monstro Dragão de Nível 4 ou menos	\r\nVocê não pode Invocar monstros por Invocação-Especial, exceto monstros Dragão. \r\nDurante sua Fase Principal: você pode Invocar por Invocação-Especial 1 monstro Dragão da sua mão ou do Deck em uma zona sua para a qual 2 ou mais Monstros Link apontarem. \r\nVocê só pode usar este efeito de "Dragão-Guarda Elpy" uma vez por turno. \r\nVocê só pode Invocar um ou mais "Dragão-Guarda Elpy" por Invocação-Especial uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86154370,'Alta-Velocidaroide Piloto de Asas Transparentes',replace(replace('1 Regulador de VENTO + 1 Monstro Sincro não-Regulador de VENTO	\r\nUma vez por turno, durante sua Fase Principal: você pode lançar um dado de seis faces e embaralhar monstros de VENTO do seu Cemitério no seu Deck, até o resultado e, depois, você pode destruir cards que seu oponente controla até o número de embaralhados e, se isso acontecer, até o final deste turno, este card ganha 500 de ATK para cada card destruído por este efeito. \r\nDurante a Fase Principal do seu oponente (Efeito Rápido): você pode oferecer como Tributo este card Invocado por Invocação-Sincro; Invoque por Invocação-Especial do seu Deck Adicional até 2 Monstros Sincro de VENTO de Nível 7 com nomes diferentes um do outro.','\r',char(13)),'\n',char(10)),'Retornar para o Deck e destruir','Invocação Especial','Destruir 1 card que seu oponente controla?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86157908,'Unicórnio Camarartista de Olhos Anômalos',replace(replace('Escala de Pêndulo = 8\r\n[ Efeito de Pêndulo ]\r\nUma vez, enquanto este card estiver na sua Zona de Pêndulo, quando um monstro "Olhos Anômalos" seu declarar um ataque: você pode escolher 1 outro monstro "Camarartista" que você controla; até o final da Fase de Batalha, esse monstro atacante ganha ATK igual ao ATK original do monstro escolhido como alvo no campo (mesmo que este card deixe o campo).\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nQuando este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 monstro "Camarartista" no seu Cemitério; ganhe PV igual ao ATK dele.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86164529,'Aquadragão','"Dragão Fada" + "Amazona dos Mares" + "Devorador de Zona"','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86165817,'HERÓI Maligno Perdição Maliciosa',replace(replace('1 monstro "HERÓI Maligno" + 1 monstro de Nível 5 ou mais	\r\nDeve ser Invocado por Invocação-Especial com "Fusão Negra". \r\nNão pode ser destruído em batalha ou por efeitos de card. \r\nDurante sua Fase Principal: você pode destruir todos os monstros que seu oponente controla com ATK igual ou menor que o deste card e, além disso, este card ganha 200 de ATK para cada monstro destruído desta forma e, além disso, você não pode declarar um ataque pelo resto deste turno, exceto com monstros "HERÓI". \r\nVocê só pode usar este efeito de "HERÓI Maligno Perdição Maliciosa" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86170989,'Alfanjeβ',replace(replace('Se este card destruir um monstro do oponente em batalha: ative 1 desses efeitos.\r\n● Envie 1 monstro Máquina de LUZ com 1200 ou menos de ATK do seu Deck para o seu Cemitério.\r\n● Escolha 1 monstro Máquina de LUZ com 1200 ou menos de ATK no seu Cemitério; Invoque o alvo por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Ativar 1 efeito','Enviar um monstro do Deck para o Cemitério','Invoque por Invocação Especial um monstro do Cemitério','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86174055,'Pássaro Veloz','Quando este card for destruído em batalha e enviado ao Cemitério: Você pode escolher 2 monstros de Nível 2 no seu Cemitério; Invoque-os por Invocação-Especial, mas seus efeitos são negados.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86188410,'Coração Selvagem, o HERÓI do Elemento','Não é afetado por efeitos de Armadilha.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86196216,'Magia de Aumento de Classe Força Duplo do Destino',replace(replace('Escolha 1 Monstro Xyz "Ataqueraptor" no seu Cemitério que foi destruído em batalha e enviado para lá neste turno; Invoque-o por Invocação-Especial e, depois, Invoque por Invocação-Especial do seu Deck Adicional, 1 Monstro Xyz que tenha duas vezes a Classe desse monstro, usando-o como Matéria Xyz. \r\n(Esta Invocação-Especial é considerada uma Invocação-Xyz.)','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86197239,'Miragem Inférnica',replace(replace('Não pode ser Invocado por Invocação-Especial do Cemitério. \r\nSe você não tiver cards na sua mão: você pode oferecer este card como Tributo e, depois, escolha 2 monstros "Inférnico(a)" no seu Cemitério; Invoque-os por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86198326,'7 Completados',replace(replace('Ative este card ao escolher ATK ou DEF; só pode ser equipado a um monstro Máquina. \r\nEle ganha 700 de ATK ou DEF, dependendo da sua escolha.','\r',char(13)),'\n',char(10)),'Aumentar ATK em ７００','Aumente a DEF em ７００','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86209650,'Asmodaico Errante','Quando este card for destruído e enviado para o Cemitério em batalha, ambos os duelistas ganham 800 PV.','Ganhar PV','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86221741,'Ataqueraptor - Falcão Definitivo',replace(replace('3 monstros Besta Alada de Nível 10	\r\nNão é afetado por outros efeitos de cards. \r\nVocê pode desassociar 1 matéria deste card; pelo resto deste turno, todos os monstros que seu oponente controla perdem 1000 de ATK e, além disso, seu oponente não pode ativar cards ou efeitos. \r\nSe este card tiver um monstro "Ataqueraptor" como matéria, ele ganha este efeito.\r\n● Uma vez por turno, durante a Fase Final: você pode fazer com que todos os monstros que seu oponente controla percam 1000 de ATK e, além disso, se seu oponente não controlar monstros com a face para cima, cause 1000 de dano ao seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86223870,'Calibrador de Nível','Reduza o Nível de 1 monstro com a face para cima que você controla em até 2.','Reduzir o Nível em 1','Reduzir o Nível em 2','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86229493,'Alma do Umbral','Quando este card for destruído em batalha e enviado para o Cemitério, destrua todos os monstros com a face para baixo e os que não sejam de TREVAS.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86238081,'Dragão Furioso de Olhos Anômalos',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno, se você não tiver cards na sua outra Zona de Pêndulo: você pode colocar na sua Zona de Pêndulo 1 Monstro Pêndulo do seu Deck.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\n2 monstros Dragão de Nível 7	\r\nSe você puder Invocar por Invocação-Pêndulo de Nível 7, você pode Invocar este card com a face para cima no seu Deck Adicional por Invocação-Pêndulo. \r\nSe este card na Zona de Monstros for destruído: você pode colocá-lo na sua Zona de Pêndulo. \r\nSe este card for Invocado por Invocação-Xyz usando um Monstro Xyz como matéria, ele ganha esses efeitos.\r\n● Ele pode realizar um segundo ataque durante cada Fase de Batalha.\r\n● Uma vez por turno: você pode desassociar 1 matéria dele; destrua tantos cards que seu oponente controla quanto possível e, se isso acontecer, até o final deste turno, este card ganha 200 de ATK para cada um.','\r',char(13)),'\n',char(10)),'Colocar um Monstro Pêndulo do Deck','Destruir todos os cards que seu oponente controla','Colocar este card na Zona de Pêndulo','Invocar por Invocação Xyz usando um Monstro Xyz como matéria','','','','','','','','','','','','');
INSERT INTO texts VALUES(86239173,'Chifressauro',replace(replace('"Kaitoptera" + 1 monstro Dinossauro ou Dragão	\r\nEste card pode atacar diretamente no turno em que for Invocado por Invocação-Especial. \r\nVocê só pode usar cada um dos seguintes efeitos de "Chifressauro" uma vez por turno. \r\nSe este card for Invocado por Invocação-Fusão: você pode colocar 1 Magia de Campo do seu Deck ou Cemitério com a face para cima na sua Zona do Campo. \r\nDurante sua Fase Principal, você pode: imediatamente depois que este efeito resolver, Invocar por Invocação-Normal 1 monstro Dinossauro ou Dragão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86240887,'Blader Notável, o Soldado da Espada Destruidora de Dragões',replace(replace('1 "Blader Notável" + 1 monstro Dragão	\r\nDeve ser Invocado por Invocação-Fusão. \r\nNão pode atacar diretamente. \r\nGanha 1000 de ATK/DEF para cada monstro Dragão que seu oponente controla ou que estiver no Cemitério dele. \r\nColoque todos os monstros Dragão que seu oponente controla em Posição de Defesa e, além disso, monstros Dragão em posse do seu oponente não podem ativar seus efeitos. \r\nSe este card atacar um monstro em Posição de Defesa, cause dano de batalha perfurante.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86271510,'Darton, a Monstruosidade Mecânica','Uma vez por turno, durante sua Fase Principal: você pode verificar a diferença entre o ATK atual e original de cada monstro no campo, somar essas diferenças e fazer com que o ATK original deste monstro se torne esse valor combinado até o final do próximo turno do seu oponente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86274272,'Besta Espiritual Ulti-Apeleão',replace(replace('1 monstro "Domador da Besta Espiritual" + 1 monstro "Avatar da Besta Espiritual"	\r\nVocê deve Invocá-lo por Invocação-Especial (do seu Deck Adicional) ao banir os cards acima que você controla e não pode Invocá-lo por Invocação-Especial de nenhuma outra forma. \r\n(Você não usa "Polimerização".) \r\nSe este card atacar, ele não é afetado por outros efeitos de card até o final da Etapa de Dano. \r\nDurante o turno de qualquer duelista: você pode devolver este card que você controla para o Deck Adicional e, depois, escolher 2 dos seus monstros banidos (1 monstro "Domador da Besta Espiritual" e 1 monstro "Avatar da Besta Espiritual"); Invoque-os por Invocação-Especial em Posição de Defesa.','\r',char(13)),'\n',char(10)),'Invoque por Invocação Especial 1 monstro "Domador da Besta Espiritual" e 1 monstro "Avatar da Besta Espiritual"','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86277379,'Vedir Gusto',replace(replace('Se um monstro "Gusto" com a face para cima no campo for destruído em batalha ou enviado para o seu Cemitério: você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode enviar 1 monstro "Gusto" do seu Deck para o Cemitério e, depois, você pode Invocar por Invocação-Especial 1 monstro "Gusto" da sua mão. \r\nVocê só pode usar cada efeito de "Vedir Gusto" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86281779,'Soldado Dispositivo','Um guerreiro mecânico inoxidável nascido para a batalha.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86282581,'HERÓI Maligno Cavaleiro Mais Escuro',replace(replace('1 monstro Demônio + 1 monstro Guerreiro	\r\nDeve ser Invocado por Invocação-Especial com "Fusão Negra". \r\nMonstros que seu oponente controla perdem ATK igual à soma do ATK original das matérias usadas para a Invocação-Fusão deste card. \r\nPode realizar um segundo ataque durante cada Fase de Batalha. \r\nSe este card com a face para cima Invocado por Invocação-Especial sob o controle do seu dono deixar o campo devido a um card do oponente: você pode escolher 1 monstro Demônio ou Guerreiro no seu Cemitério; Invoque-o por Invocação-Especial em Posição de Defesa.','\r',char(13)),'\n',char(10)),'','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86289475,'Guerreiro Ímã Ômega Plus',replace(replace('Se este card estiver na sua mão ou no Cemitério: você pode destruir 1 outro monstro Rocha na sua mão ou no campo com a face para cima e, se isso acontecer, Invoque este card por Invocação-Especial, mas bana-o quando ele deixar o campo. \r\nQuando o efeito de um monstro de TERRA for ativado no campo (Efeito Rápido): você pode oferecer este card como Tributo e, depois, escolha 1 monstro com a face para cima no campo; coloque-o com a face para baixo em Posição de Defesa. \r\nVocê só pode usar cada efeito de "Guerreiro Ímã Ômega Plus" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Mudar a posição de batalha','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86304179,'Tempura da Sorte - EBI',replace(replace('Escala de Pêndulo = 8\r\n[ Efeito de Pêndulo ]\r\nVocê pode escolher 1 card na sua Zona de Pêndulo; lance uma moeda.\r\n● Cara: Invoque-o por Invocação-Especial.\r\n● Coroa: Destrua-o, mas perca PV igual à sua Escala de Pêndulo x 300.\r\nVocê só pode usar este efeito de "Tempura da Sorte - EBI" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nFomos ao EDO-FRONT, o que tem sido o assunto da cidade. O tamanho do Tempura aqui não é apenas grande, mas também tão maravilhosamente moldado que ganhou o apelido de "Tempura Dourado". As instalações de última geração e a atmosfera de outras culturas estão por todo o porto, mas também há um aroma suave e nostálgico no ar, e o estalo ocasional dos sons crepitantes levantará seu ânimo. Estivemos esperando ansiosamente por este cruzeiro por um ano, mas acho que 3 estrelas é o mais correto.','\r',char(13)),'\n',char(10)),'Jogar uma moeda','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86308219,'Formação Fênix da Lady Harpia',replace(replace('Se você controlar 3 ou mais "Lady Harpia" e/ou "Irmãs de Lady Harpia": escolha tantos monstros que seu oponente controla quanto possível, mas não mais que o total de "Lady Harpia" e "Irmãs de Lady Harpia" que você controla; destrua os alvos e, se isso acontecer, cause dano ao seu oponente igual ao maior ATK original entre esses monstros destruídos (em caso de empate, você seleciona). \r\nVocê não pode Invocar monstros por Invocação-Especial do Deck Principal ou do Deck Adicional, nem conduzir sua Fase de Batalha, no turno em que ativar este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86310763,'Radiância da Voz Sem Voz',replace(replace('Durante a Fase Principal: você pode ativar 1 desses efeitos;\r\n● Embaralhe no Deck 1 Monstro de Ritual (Guerreiro ou Dragão) de LUZ ou 1 Magia de Ritual da sua mão ou do Cemitério e, se isso acontecer, adicione à sua mão, ou Invoque por Invocação-Especial, 1 monstro "Voz Sem Voz" do seu Deck.\r\n● Escolha cards que seu oponente controla até o número de Monstros de Ritual (Guerreiro ou Dragão) de LUZ que você controla; destrua tanto este card quanto tantos dos cards alvo quanto possível.	\r\nVocê só pode usar o efeito de "Radiância da Voz Sem Voz" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar do Deck à mão ou Invocar por Invocação Especial','Destrua este card e 1 card do oponente','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86318356,'Sogen','Todos os monstros Guerreiro e Besta-Guerreira no campo ganham 200 de ATK/DEF.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86319972,'Invocação Gama',replace(replace('Bana 1 monstro "Aleister" ou 1 Monstro de Fusão do seu Cemitério; Invoque por Invocação-Especial 1 monstro "Invokado(a)" do seu Deck Adicional, ignorando suas condições de Invocação, mas bana-o durante a Fase Final. \r\nSe um monstro for banido com a face para cima, enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode banir este card e, depois, escolha 1 dos seus monstros "Invokado(a)" banidos; Invoque-o por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Invocação Gama" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86321248,'Quimera Gadjiltron do Mecanismo Antigo',replace(replace('Este card ganha os efeitos apropriados se você Invocá-lo por Invocação-Normal oferecendo como Tributo esses monstros.\r\n● Dispositivo Verde: Este card ganha 300 de ATK.\r\n● Dispositivo Vermelho: Se este card causar dano de batalha ao seu oponente em um ataque direto: cause 500 de dano ao seu oponente.\r\n● Dispositivo Amarelo: Se este card destruir um monstro do oponente em batalha: cause 700 de dano ao seu oponente.','\r',char(13)),'\n',char(10)),'Cause 500 de dano ao seu oponente','Cause 700 de dano ao seu oponente','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86325573,'Boxeador Obstinado de Bandagem Grande',replace(replace('Na primeira vez que este card seria destruído em batalha a cada turno, ele não é destruído. \r\nUma vez por turno: você pode escolher 1 dos seus monstros "Boxeador Obstinado" que estiverem banidos ou no seu Cemitério, que tenha um Nível; todos os monstros "Boxeador Obstinado" que você controla atualmente se tornam do Nível atual desse monstro.','\r',char(13)),'\n',char(10)),'Alterar Nível','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86325596,'Barão da Espada Demoníaca','Um aristocrata que empunha uma espada possuída por um demônio, que se alimenta dos fracos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86327225,'Shinato, Rei de um Plano Superior',replace(replace('Este card não pode ser Invocado a não ser por Invocação-Ritual com o Card de Magia de Ritual "Arca de Shinato". \r\nTambém deve oferecer como Tributo monstros cuja soma dos Níveis seja igual ou maior que 8, do Campo ou da sua mão. \r\nQuando este card destrói um monstro no Campo do seu adversário em Posição de Defesa como resultado de um cambate e o envia para o Cemitério, inflija dano aos Life Points do seu adversário igual ao ATK original do monstro destruído.','\r',char(13)),'\n',char(10)),'Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86331741,'Mago Gagagaga',replace(replace('2 monstros de Nível 4	\r\nVocê pode desassociar 1 matéria deste card e, depois, escolha 1 Monstro Xyz no seu Cemitério, exceto "Mago Gagagaga"; Invoque-o por Invocação-Especial, mas negue seus efeitos. \r\nVocê só pode usar este efeito de "Mago Gagagaga" uma vez por turno. \r\nUm Monstro Xyz "Futuro Utópico" que tenha este card como matéria ganha este efeito.\r\n● Durante sua Fase Principal: você pode desassociar 2 matérias deste card e, depois, escolha 1 Monstro Xyz que você controla; até o final deste turno, mude o ATK dele para 4000 e, além disso, negue seus efeitos.','\r',char(13)),'\n',char(10)),'','O ATK torna-se 4000 (Mago Gagagaga)','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86346363,'Recarregador de Tempo',replace(replace('Durante a Fase Principal, se um monstro no campo for virado com a face para cima: você pode Invocar este card por Invocação-Especial da sua mão e, depois, coloque 1 monstro com a face para cima no campo, com a face para baixo em Posição de Defesa. \r\nDurante a Fase Principal, se este card for virado com a face para cima: você pode escolher 1 monstro no seu Cemitério; Invoque-o por Invocação-Especial em Posição de Defesa e, depois, coloque 1 monstro com a face para cima no campo, com a face para baixo em Posição de Defesa. \r\nVocê só pode usar cada efeito de "Recarregador de Tempo" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar este card por Invocação Especial','Invoque por Invocação Especial um monstro do Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86346643,'Neos Arco-Íris',replace(replace('"Neos, o HERÓI do Elemento" + 1 monstro "Cristalino(a) Definitivo(a)"	\r\nDeve ser Invocado por Invocação-Fusão com as Matérias de Fusão acima. \r\nUma vez por turno: você pode ativar 1 desses efeitos.\r\n● Envie 1 monstro que você controla para o Cemitério; embaralhe todos os monstros que seu oponente controla no Deck.\r\n● Envie 1 Magia/Armadilha que você controla para o Cemitério; embaralhe todas as Magias e Armadilhas que seu oponente controla no Deck.\r\n● Envie 1 card do topo do seu Deck para o Cemitério; embaralhe todos os cards no Cemitério do seu oponente no Deck.','\r',char(13)),'\n',char(10)),'Ativar o efeito escolhido','Embaralhe no Deck todos os monstros que seu oponente controla','Embaralhe no Deck todos os Cards de Magia/Armadilha que seu oponente controla','Embaralhe no Deck todos os cards no Cemitério do seu oponente','','','','','','','','','','','','');
INSERT INTO texts VALUES(86361354,'Vírus de Choque Tribal','Uma vez por turno: você pode banir 1 monstro da sua mão; destrua todos os monstros com a face para cima no campo com o mesmo Tipo desse monstro.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86377375,'Ahrima, o Soberano Perverso',replace(replace('Você pode descartar este card; adicione 1 "Covil das Trevas" do seu Deck à sua mão. \r\nVocê pode oferecer como Tributo 1 monstro de TREVAS; compre 1 card, ou, se você ofereceu como Tributo um monstro de TREVAS que não seja este card para ativar este efeito, em vez disso, você pode adicionar 1 monstro de TREVAS com 2000 ou mais de DEF do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Ahrima, o Soberano Perverso" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Buscar no Deck em vez de comprar um card?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86379342,'Juramento da Tri-Brigada',replace(replace('Escolha 1 Monstro Link que você controla; Invoque por Invocação-Especial 1 monstro Besta, Besta-Guerreira ou Besta Alada com um Tipo diferente da sua mão ou do Cemitério. \r\nSe você controlar pelo menos 1 monstro de cada dentre Besta, Besta-Guerreira e Besta Alada: você pode banir este card do seu Cemitério e, depois, escolha 1 Magia/Armadilha com a face para cima que seu oponente controla; negue os efeitos dela até o final deste turno. \r\nVocê só pode usar 1 efeito de "Juramento da Tri-Brigada" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86395581,'Wynn, a Canalizadora do Vento',replace(replace('(Este card deve ser sempre considerado como um card "Encantador(a)".)	\r\nVocê pode descartar este card e 1 outro monstro de VENTO; adicione 1 monstro de VENTO com 1500 ou menos de DEF do seu Deck à sua mão, exceto "Wynn, a Canalizadora do Vento" e, além disso, você não pode ativar os efeitos de monstros que não sejam de VENTO pelo resto deste turno. \r\nQuando um monstro de VENTO seu for destruído em batalha: você pode Invocar este card por Invocação-Especial da sua mão. \r\nVocê só pode usar cada efeito de "Wynn, a Canalizadora do Vento" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86396750,'Avatar da Besta Espiritual Apeleão',replace(replace('Uma vez por turno, durante o turno de qualquer duelista: você pode banir 1 card "Besta Espiritual" do seu Cemitério; pelo resto deste turno, todos os monstros "Besta Espiritual" que você controla ganham 500 de ATK e DEF. \r\nVocê só pode Invocar "Avatar(es) da Besta Espiritual Apeleão" por Invocação-Especial uma vez por turno.','\r',char(13)),'\n',char(10)),'Aumentar ATK/DEF','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86401517,'Paladino do Dragão da Tempestade',replace(replace('Você pode Invocar este card por Invocação-Ritual com "Cinet Ritual". \r\nNo começo da Etapa de Dano, se este card atacar um monstro: você pode devolver esse monstro para a mão. \r\nVocê pode oferecer este card como Tributo; Invoque por Invocação-Especial 1 monstro Ciberso de Nível 5 ou mais da sua mão ou do Deck, mas ele não pode ativar seus efeitos neste turno. \r\nVocê só pode usar cada efeito de "Paladino do Dragão da Tempestade" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86421986,'Árvore Antiga da Iluminação','Esta árvore antiga usa seu vasto conhecimento para evitar os danos dos ataques inimigos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86442081,'Abismo Silencioso','Quando este card for destruído em batalha e enviado para o Cemitério, destrua todos os monstros com a face para baixo e os que não sejam de ÁGUA.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86445415,'Dispositivo Vermelho','Quando este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 "Dispositivo Amarelo" do seu Deck à sua mão.','Adicione 1 "Dispositivo Amarelo" à sua mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86449372,'Golpe TI.A.',replace(replace('Durante o cálculo de dano, se um monstro seu batalhar um monstro do oponente: o ATK do seu monstro que está batalhando se torna o ATK desse monstro do oponente, apenas durante o cálculo de dano e, além disso, no final da Etapa de Dano, o controlador de qualquer monstro destruído nessa batalha sofre dano igual ao ATK original desse monstro. \r\nSe um monstro "@Ignister" seu seria destruído em batalha, em vez disso, você pode banir este card do seu Cemitério. \r\nVocê só pode ativar 1 "Golpe TI.A." por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86466163,'Cavaleirostélite Capella',replace(replace('Se este card for Invocado: você pode aplicar o efeito abaixo pelo resto do turno. \r\nVocê só pode usar este efeito de "Cavaleirostélite Capella" uma vez por turno (mas se ele resolver, você pode aplicar o efeito diversas vezes).\r\n● Você pode considerar os monstros "Cavaleirost" de Nível 4 ou menos que você controla como de Nível 5 ao realizar uma Invocação-Xyz usando 3 ou mais monstros como Matéria Xyz.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86469231,'Mamba-negra',replace(replace('Se você controlar um monstro Réptil, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nVocê só pode Invocar "Mamba-negra" por Invocação-Especial uma vez por turno desta forma. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 monstro que seu oponente controla; envie 1 monstro Réptil do seu Deck para o Cemitério e, se isso acontecer, mude a posição de batalha do monstro alvo. \r\nVocê só pode usar este efeito de "Mamba-negra" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86474024,'Fronte Unida','Quando um Card de Armadilha for ativado enquanto você controlar 2 ou mais monstros com a face para cima com o mesmo Nível: Negue a ativação e destrua-o.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86483512,'Roshi do Mundo Virtual - Laolao',replace(replace('Se este card estiver na sua mão: você pode escolher 1 card "Mundo Virtual" que você controla; envie 1 card "Mundo Virtual" de um tipo diferente (Monstro, Magia, Armadilha) do seu Deck para o Cemitério e, se isso acontecer, Invoque este card por Invocação-Especial e, depois, você pode Invocar por Invocação-Especial 1 monstro "Mundo Virtual" do seu Cemitério em Posição de Defesa, com um nome diferente que o do card enviado para o Cemitério, mas negue seus efeitos. \r\nPelo resto deste turno, você só pode Invocar por Invocação-Especial monstros de Nível/Classe 3 ou mais. \r\nVocê só pode usar este efeito de "Roshi do Mundo Virtual - Laolao" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial da mão','Invocar por Invocação Especial 1 monstro do Cemitério?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86489182,'Simorgh, o Pássaro dos Antepassados',replace(replace('Este card é considerado como um Monstro Normal enquanto estiver na sua mão. \r\nVocê pode Invocar monstros de VENTO por Invocação-Tributo com 1 Tributo a menos. \r\nSe você Invocar este card por Invocação-Tributo ao oferecer como Tributo apenas monstros de VENTO: escolha até 2 cards que seu oponente controla; devolva-os para a mão.','\r',char(13)),'\n',char(10)),'Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86498013,'Treinador D. D.','Um pobre goblin que foi sugado para uma dimensão diferente. No entanto, ele dá o seu melhor no seu novo destino.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86509711,'Combinação dos Magos',replace(replace('Uma vez por turno, quando um card ou efeito for ativado (exceto durante a Etapa de Dano): você pode oferecer como Tributo 1 "Mago Negro" ou 1 "Pequena Maga Negra"; Invoque por Invocação-Especial 1 "Mago Negro" ou 1 "Pequena Maga Negra" da sua mão ou do Cemitério, com um nome diferente do monstro oferecido como Tributo e, se isso acontecer, negue esse efeito ativado. \r\nSe este card com a face para cima for enviado da Zona de Magias & Armadilhas para o Cemitério: você pode destruir 1 card no campo.','\r',char(13)),'\n',char(10)),'Ativar, mas não resolver o efeito','Ativar e aplicar o primeiro Efeito','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86516889,'Susto Fantardil','Escolha qualquer número de monstros com a face para baixo em Posição de Defesa que você controla; coloque-os com a face para cima em Posição de Defesa, conte o número de monstros "Fantardil" entre eles e, se isso acontecer, coloque com a face para baixo em Posição de Defesa (min. 1), até esse mesmo número de monstros que seu oponente controla e que estão com a face para cima.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86520461,'Guerreiro Fóssil Caveira de Ossos',replace(replace('1 monstro Rocha + 1 monstro de Nível 4 ou menos	\r\nPrimeiro deve ser Invocado por Invocação-Especial com "Fusão Fóssil". \r\nEste card pode realizar até 2 ataques contra monstros durante cada Fase de Batalha. \r\nVocê pode banir este card do seu Cemitério; adicione 1 "Fluxo do Tempo" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Guerreiro Fóssil Caveira de Ossos" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86527709,'Convite dos Insetos',replace(replace('Monstros com a face para cima que seu oponente controla que não foram Invocados neste turno se tornam Inseto. \r\nVocê só pode usar cada um dos seguintes efeitos de "Convite dos Insetos" uma vez por turno. \r\nVocê pode escolher 3 dos seus monstros Inseto banidos; embaralhe-os no Deck e, depois, compre 1 card. \r\nDurante a Fase Final, se este card estiver no Cemitério porque foi enviado para lá da mão neste turno: você pode colocar este card na sua Zona de Magias & Armadilhas com a face para cima.','\r',char(13)),'\n',char(10)),'Alterar o Tipo para Inseto','Recuperar','Colocar com a face para cima','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86532744,'Número S39: Utopia Primordial',replace(replace('3 monstros de LUZ de Nível 4	\r\nVocê também pode Invocar este card por Invocação-Xyz ao usar um "Número 39: Utopia" que você controla como Matéria Xyz. \r\n(Matérias Xyz associadas a esse monstro também se tornam Matérias Xyz neste card.) \r\nSe os PV do seu oponente forem pelo menos 3000 a mais que os seus: você pode desassociar 3 Matérias Xyz deste card e pagar PV até ter 10 restantes; destrua tantos monstros Invocados por Invocação-Especial que seu oponente controla quanto possível e, se isso acontecer, bana-os e, depois, cause 300 de dano ao seu oponente para cada monstro banido.','\r',char(13)),'\n',char(10)),'Destruir e banir','Invocar por Invocação Xyz usando "Número 39: Utopia" como matéria?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86541496,'Oferenda do Braço Esquerdo',replace(replace('Se você tiver 2 ou mais outros cards na sua mão: bana toda sua mão; adicione 1 Magia do seu Deck à sua mão. \r\nVocê não pode Baixar Magias/Armadilhas durante o turno em que ativar este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86547356,'Paranoia Inférnica',replace(replace('Ofereça 1 monstro de TREVAS como Tributo; Invoque por Invocação-Especial 1 monstro "Inférnico(a)" do seu Deck ou Cemitério com o mesmo Nível, mas um nome diferente, mas negue seus efeitos. \r\nDurante sua Fase Principal, exceto no turno em que este card foi enviado para o Cemitério: você pode banir este card do seu Cemitério e, depois, escolha 1 monstro "Inférnico(a)" no seu Cemitério; adicione-o à sua mão. \r\nVocê só pode ativar 1 "Paranoia Inférnica" por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86553594,'Discordância da Tistina',replace(replace('Ative 1 desses efeitos;\r\n● Se você controlar um monstro "Tistina": bana, com a face para baixo, 1 card do Cemitério do seu oponente.\r\n● Se você controlar um monstro "Tistina" Invocado por Invocação-Especial do Deck Adicional: bana, com a face para baixo, todos os cards do Cemitério do seu oponente.	\r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 monstro "Tistina" no seu Cemitério; adicione-o à sua mão. \r\nVocê só pode usar 1 efeito de "Discordância da Tistina" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Banir 1 card no Cemitério do seu oponente com a face para baixo','Banir com a face para baixo todos os cards no Cemitério do seu oponente','Recuperar do Cemitério','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86555018,'Métodos de Stonehenge',replace(replace('Quando um ou mais monstros "Cronomalia" com a face para cima que você controla forem destruídos em batalha ou por um efeito de card e enviado ao Cemitério: Invoque por Invocação-Especial 1 monstro "Cronomalia" de Nível 4 ou menos do seu Deck com a face para cima em Posição de Defesa. \r\nEle não pode mudar sua posição de batalha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86559484,'Rapierfurador-Xyz',replace(replace('Você pode banir 1 monstro do Tipo Dragão e 1 monstro do Tipo Wyrm do seu Cemitério; Invoque por Invocação-Especial 1 "Rapierfurador-Xyz" da sua mão ou Deck. \r\nSe este card for enviado do campo para o Cemitério: você pode causar 500 de dano ao seu oponente. \r\nVocê só pode usar cada efeito de "Rapierfurador-Xyz" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Causar dano','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86569121,'Melchid, a Besta de Quatro Faces','Este monstro tem quatro máscaras diferentes para quatro ataques diferentes.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86578200,'Acessório do Abismo - Vagão Selvagem',replace(replace('Na primeira vez em que cada monstro "Ator do Abismo" que você controla seria destruído em batalha a cada turno, ele não é destruído. \r\nUma vez por turno: você pode escolher 1 monstro "Ator do Abismo" que você controla; seu oponente não pode escolhê-lo como alvo de efeitos de card até o final do turno dele (mesmo que este card deixe o campo). \r\nSe este card Baixado sob o controle do seu dono for destruído por um efeito de card do oponente e você tiver um Monstro Pêndulo "Ator do Abismo" com a face para cima no Deck Adicional: você pode devolver todos os cards que seu oponente controla para a mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86585274,'Alta Sacerdotisa da Profecia',replace(replace('Você pode revelar 3 Magias "Livro de Magia" na sua mão; Invoque este card por Invocação-Especial da sua mão. \r\nUma vez por turno: você pode banir 1 Magia "Livro de Magia" da sua mão ou do Cemitério e, depois, escolher 1 card no campo; destrua o alvo.','\r',char(13)),'\n',char(10)),'Invocação Especial','Destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86605184,'Guardião Firewall',replace(replace('Se este card for enviado para o Cemitério como matéria para a Invocação-Link de um monstro Ciberso: você pode Invocar este card por Invocação-Especial, mas bana-o quando ele deixar o campo. \r\nQuando um ataque for declarado envolvendo um Monstro Link seu e um Monstro Link do oponente: você pode banir este card do seu Cemitério; negue o ataque e, se isso acontecer, até o final deste turno, o ATK original desse monstro do oponente se torna 0 e, além disso, ele não é afetado por outros efeitos de card, exceto seus próprios. \r\nVocê só pode usar cada efeito de "Guardião Firewall" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86605515,'Qardan, o Perspicaz',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode Baixar 1 Armadilha Contínua da sua mão ou do Cemitério. \r\nEla pode ser ativada neste turno. \r\nSe este card for enviado para o Cemitério: você pode ativar este efeito; Armadilhas com a face para cima que você controla não podem ser destruídos pelos efeitos de card do seu oponente até o final do próximo turno.','\r',char(13)),'\n',char(10)),'','','Ativar aplicando o efeito de "Qardan, o Perspicaz".','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86607583,'Limitar Código',replace(replace('Se você tiver qualquer Monstro Link Ciberso no seu Cemitério: coloque 1 marcador neste card para cada um desses monstros e, se isso acontecer, Invoque por Invocação-Especial 1 monstro "Codificar Transmissor" do seu Deck Adicional e equipe-o com este card. \r\nQuando este card deixar o campo, destrua o monstro equipado. \r\nUma vez por turno, durante sua Fase Final: remova 1 marcador deste card. \r\nSe você não puder, destrua-o. \r\nVocê só pode ativar "Limitar Código" uma vez por Duelo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86613346,'Cavalestrela Flamel',replace(replace('Quando um monstro do oponente declarar um ataque: você pode enviar para o Cemitério este card da sua mão ou do campo com a face para cima; Invoque por Invocação-Especial 1 monstro Dragão de LUZ de Nível 7 da sua mão. \r\n(Efeito Rápido): você pode banir este card do seu Cemitério e, depois, escolha 1 monstro Dragão de LUZ de Nível 7 que você controla ou no seu Cemitério; devolva-o à sua mão. \r\nVocê só pode usar 1 efeito de "Cavalestrela Flamel" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86643777,'Matriz de Insetos',replace(replace('Todos os monstros do Tipo Inseto que você controla ganham 300 de ATK e DEF. \r\nVocê pode escolher 1 Monstro Xyz do Tipo Inseto que você controla; associe 1 monstro do Tipo Inseto da sua mão a esse monstro como uma Matéria Xyz. \r\nVocê só pode usar este efeito de "Matriz de Insetos" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86652646,'Cão Caveira Marron','Um cão que se perdeu há 1000 anos. Ele ainda espera pelo regresso do seu dono.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86676862,'HERÓI Maligno Demônio Malicioso',replace(replace('"HERÓI Maligno Malicious Edge" + 1 monstro Demônio de Nível 6 ou mais	\r\nDeve ser Invocado por Invocação-Especial com "Fusão Negra". \r\nDurante a Fase de Batalha do seu oponente, todos os monstros que ele controla são colocados com a face para cima em Posição de Ataque e cada monstro que ele controla deve atacar este card, se possível.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86682165,'Gelojade Gymir Aegirine',replace(replace('1 Regulador de ÁGUA + 1+ monstros não-Reguladores	\r\n(Efeito Rápido): você pode ativar este efeito; neste turno, os monstros com a face para cima que você controla não podem ser destruídos, ou banidos, pelos efeitos de card do seu oponente. \r\nDepois, se você ativou este efeito em resposta à ativação de um card ou efeito do seu oponente, e seu oponente tiver um ou mais cards com esse nome no campo e/ou Cemitério dele, você pode banir esses cards. \r\nSe um ou mais cards forem banidos por um efeito de card do seu oponente, enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Gelojade Gymir Aegirine" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Banir um card com o mesmo nome do efeito que seu oponente ativou?','Invocar este card por Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86686671,'Usina de Reparos Cibernética',replace(replace('Se "Dragão Cibernético" estiver no seu Cemitério: você pode ativar 1 desses efeitos. \r\nSe você tiver 3 ou mais "Dragão Cibernético" no seu Cemitério na ativação deste card, você pode ativar os dois efeitos e resolvê-los em sequência. \r\nVocê só pode ativar 1 "Usina de Reparos Cibernética" por turno.\r\n● Adicione 1 monstro Máquina de LUZ do seu Deck à sua mão.\r\n● Escolha 1 monstro Máquina de LUZ no seu Cemitério; embaralhe o alvo no seu Deck.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Recuperar do Cemitério','Escolher ambos os jogadores','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86690572,'Redemoinho de Fogo Crescente',replace(replace('Quando um Card de Armadilha for ativado: Envie 1 monstro "Laval" da sua mão ao Cemitério; negue a ativação e destrua-o. \r\nSe este card estiver no Cemitério: Você pode banir 2 monstros de FOGO do seu Cemitério; adicione este card à sua mão.','\r',char(13)),'\n',char(10)),'Adicionar este card à sua mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86742443,'Ordem Real de Impostos',replace(replace('Ative apenas durante a Fase de Apoio do oponente. \r\nSelecione 1 card aleatório na mão do oponente e o veja. \r\nA menos que o card selecionado ou um card com o mesmo nome seja Invocado por Invocação-Normal ou ativado até o fim do seu próximo turno, cause 1000 de dano ao seu oponente. \r\nSe o card selecionado ou um card com o mesmo nome for Invocado por Invocação-Normal ou ativado até o fim do seu próximo turno, você sofre 1000 de dano.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86750474,'Trapestrela Bruxa Luvaraposa',replace(replace('2+ monstros Fada	\r\nSe este card for Invocado por Invocação-Especial: você pode causar 200 de dano ao seu oponente para cada card que ele controla. \r\nSe este card Invocado por Invocação-Link for destruído em batalha ou por um efeito: você pode Invocar por Invocação-Especial 1 monstro "Trapestrela" de Link-2 ou menos do seu Deck Adicional e, depois, cause 200 de dano ao seu oponente para cada card que ele controla. \r\nVocê só pode usar cada efeito de "Trapestrela Bruxa Luvaraposa" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86758746,'Artes Secretas Amazoness',replace(replace('Invoque por Invocação-Fusão 1 Monstro de Fusão "Amazoness" do seu Deck Adicional, usando monstros da sua mão ou do campo como Matéria de Fusão. \r\nDurante sua Fase Principal: você pode banir este card do seu Cemitério; uma vez, se você Invocar por Invocação-Fusão um Monstro de Fusão "Amazoness" neste turno, você também pode enviar 1 monstro "Amazoness" do seu Deck Adicional para o Cemitério como matéria. \r\nVocê só pode usar 1 efeito de "Artes Secretas Amazoness" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86758915,'Diabretiço de Criação',replace(replace('Este card pode ser usado para Invocar qualquer Monstro de Ritual por Invocação-Ritual. \r\nVocê também deve oferecer como Tributo monstros "Diabretiço" da sua mão ou do campo cuja soma dos Níveis seja igual ou exceda o Nível do Monstro de Ritual que você Invocar por Invocação-Ritual. \r\nSe este card estiver no seu Cemitério: você pode enviar para o Cemitério 1 card "Diabretiço" da sua mão ou com a face para cima no campo, exceto "Diabretiço de Criação"; Invoque por Invocação-Especial 1 monstro "Diabretiço" do seu Deck e, depois, adicione este card do Cemitério à sua mão. \r\nVocê só pode usar este efeito de "Diabretiço de Criação" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86762958,'Assistência★Nhamy!',replace(replace('Uma vez por turno, durante a Fase de Apoio: você pode ganhar 100 PV e, se isso acontecer, seu oponente paga 100 PV. \r\nVocê só pode usar 1 dos seguintes efeitos de "Assistência★Nhamy!" por turno e apenas uma vez por turno. \r\nDurante a Fase Principal ou a Fase de Batalha do seu oponente: você pode enviar 2 cards "Nhamy" com a face para cima que você controla para o Cemitério, incluindo este card; devolva 1 card no campo ou em qualquer Cemitério para a mão. \r\nVocê pode banir este card do seu Cemitério; envie 1 card "Nhamy" do seu Deck para o Cemitério, exceto "Assistência★Nhamy!".','\r',char(13)),'\n',char(10)),'Pontos de Vida','Retornar para a mão','Enviar para o Cemitério','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86767655,'Sra. Juíza',replace(replace('Se o efeito de um card do oponente for ativado, antes de resolver esse efeito, lance uma moeda duas vezes e se os resultados forem 2 Caras, negue o efeito. \r\nVocê só pode usar este efeito de "Sra. Juíza" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86778566,'Ataque Impenetrável',replace(replace('Durante a Fase de Batalha, ative 1 desses efeitos.\r\n● Escolha 1 monstro no campo; ele não pode ser destruído em batalha ou por efeitos de card durante esta Fase de Batalha.\r\n● Você não sofre dano de batalha durante esta Fase de Batalha.','\r',char(13)),'\n',char(10)),'O monstro selecionado não pode ser destruído por batalha ou por efeitos de cards','Durante esta Fase de Batalha, você recebe 0 de dano de batalha','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86780027,'Solidariedade','Se você tiver monstros de apenas 1 Tipo original em seu Cemitério, os monstros com a face para cima que você controla com esse mesmo Tipo ganham 800 de ATK.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86784733,'Sincron Ciberso',replace(replace('Uma vez por turno: você pode escolher 1 monstro de Nível 4 ou menos que você controla; até o final deste turno, aumente o Nível dele pelo Nível original dele. \r\nSe seu(s) monstro(s) na Zona de Monstros Adicional seria(m) destruído(s) em batalha ou por um efeito de card, em vez disso, você pode banir este card do seu Cemitério. \r\nVocê só pode usar este efeito de "Sincron Ciberso" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86801871,'Jarro de Cobras',replace(replace('VIRE: Invoque, por Invocação-Especial, 1 "Token de Serpente Venenosa" (Tipo Réptil/TERRA/Nível 3/ATK 1200/DEF 1200) no seu Campo. \r\nSe o "Token de Serpente Venenosa" for destruído como resultado de um combate, inflija 500 pontos de dano aos Life Points do seu adversário.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86801872,'Token de Serpente Venenosa','Invocado por Especial com o efeito "Jarro de Cobras". Quando esta Ficha for destruída em batalha, cause 500 de dano ao oponente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86804246,'Superpapa-Bugs',replace(replace('Não pode ser Invocado por Invocação-Normal ou Baixado. \r\nDeve primeiro ser Invocado por Invocação-Especial (da sua mão) com a face para cima em Posição de Defesa ao banir "Papa-Bugs X", "Papa-Bugs Y" e "Papa-Bugs Z" do seu Cemitério. \r\nTroque o ATK e DEF de todos os monstros com a face para cima em Posição de Ataque no campo. \r\nSó pode haver 1 "Superpapa-Bugs" com a face para cima no campo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86805855,'Lâmina das Trevas, o Cavaleiro Dragão',replace(replace('"Lâmina Sombria" + "Dragão Negro como Azeviche"	\r\nCada vez que este card inflige dano de batalha ao seu adversário, você pode escolher até 3 Cards de Monstro do Cemitério do seu adversário e removê-los de jogo.','\r',char(13)),'\n',char(10)),'Banir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86809440,'Masmorra Mimicarniçal',replace(replace('Monstros "Mimicarniçal" que você controla que não foram Invocados por Invocação-Normal ou Especial neste turno ganham ATK igual à sua DEF original. \r\nQualquer duelista que controlar um monstro com a face para baixo não pode Invocar monstros por Invocação-Normal, nem declarar um ataque com monstros que foram Invocados por Invocação-Especial neste turno. \r\nDurante sua Fase Principal: você pode adicionar 1 monstro "Mimicarniçal" do seu Deck ou Cemitério à sua mão. \r\nVocê só pode usar este efeito de "Masmorra Mimicarniçal" uma vez por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86821010,'Pausa Poderosa',replace(replace('Só pode ser ativado enquanto você controlar um "Dragão Ferramenteiro" com a face para cima. \r\nSelecione até 3 Cards de Equipamento no seu lado do campo e/ou no seu Cemitério e devolva-os para o Deck, e cause 500 de dano ao seu oponente para cada card devolvido.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86825114,'Trapestrela Jasmim-da-noite',replace(replace('Se este card for enviado para o Cemitério como uma Matéria Link para a Invocação-Link de um monstro "Trapestrela": você pode Invocar este card por Invocação-Especial, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar este efeito de "Trapestrela Jasmim-da-noite" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86825483,'Cinturão Constelar','A ativação dos efeitos de monstros de LUZ não pode ser negada.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86827882,'Relíquia Nórdica Megingjord','Escolha 1 monstro "Aesir" ou "Nórdic" que você controla; até o final desde turno, o ATK/DEF dele se tornam o dobro do seu ATK/DEF originais, mas ele não pode atacar diretamente seu oponente neste turno.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86840720,'Dyf Mitológico','Quando um ou mais monstros "Mitológico(a)" forem enviados da mão para o seu Cemitério (exceto durante a Etapa de Dano): você pode oferecer este card como Tributo e, depois, escolha 1 desses monstros; Invoque-o por Invocação-Especial.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86848580,'Besta Gélida Zerofyne',replace(replace('2 monstros do Tipo Besta Alada de Nível 4	\r\nUma vez por turno: você pode desassociar 1 Matéria Xyz deste card; negue os efeitos de todos os cards com a face para cima que seu oponente controla atualmente e, se isso acontecer, este card ganha 300 de ATK para cada card com a face para cima atualmente no campo, exceto este (esses efeitos se aplicam até sua próxima Fase de Apoio).','\r',char(13)),'\n',char(10)),'Negar o efeito','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86852702,'Reagrupamento Autômato',replace(replace('Ative 1 desses efeitos.\r\n● Descarte 1 card; adicione 2 monstros "Autômata(o)" com nomes diferentes um do outro do seu Deck à sua mão.\r\n● Descarte 1 card "Autômata(o)"; adicione 2 cards "Autômata(o)" com nomes diferentes um do outro do seu Deck à sua mão, exceto "Reagrupamento Autômato".	\r\nVocê só pode ativar 1 "Reagrupamento Autômato" por turno.','\r',char(13)),'\n',char(10)),'Adicionar à mão 1 monstro "Autômata(o)"','Adicione à sua mão 1 card "Autômata(o)"','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86868952,'Andorinha Bujingi',replace(replace('Durante sua Fase Principal 1: você pode enviar este card da sua mão para o Cemitério e, depois, escolher 1 monstro "Bujin" que você controla; ele pode realizar um segundo ataque durante cada Fase de Batalha neste turno. \r\nOutros monstros não podem atacar durante o turno em que você ativar este efeito.','\r',char(13)),'\n',char(10)),'Atacar duas vezes','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86871614,'Clonagem',replace(replace('Quando seu oponente Invocar por Invocação-Normal ou Virar um monstro que tenha Nível: escolha esse monstro com a face para cima; Invoque por Invocação-Especial 1 "Ficha de Clone", com o mesmo Tipo, Atributo, Nível, ATK e DEF originais do alvo. \r\nQuando o alvo for destruído e enviado para o Cemitério, destrua esta Ficha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86871615,'Ficha de Clone',replace(replace('Invocado por Especial com o efeito "Clonagem". \r\nQuando o monstro alvejado por "Clonagem" for destruído e enviado para o Cemitério, destrua esta Ficha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86885905,'Emulelfo Altergeist',replace(replace('Invoque este card por Invocação-Especial como um Monstro de Efeito (Mago/LUZ/Nível 4/ATK 1400/DEF 1800).	\r\n(Este card ainda é uma Armadilha.) \r\nSe Invocado desta forma, enquanto ele estiver na Zona de Monstros, outras Armadilhas "Altergeist" que você controla não podem ser destruídas por efeitos de card e, além disso, nenhum duelista pode escolhê-las como alvo de efeitos de card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86889202,'Cão de Guarda',replace(replace('Durante sua Fase Principal 2, se este card foi Invocado por Invocação-Normal neste turno: você pode enviar 1 Card de Magia da sua mão para o Cemitério; Baixe 1 Card de Magia Contínua diretamente do seu Deck. \r\nVocê só pode usar este efeito de "Cão de Guarda" uma vez por turno. \r\nVocê não pode Invocar por Invocação-Especial durante o turno em que ativar este efeito.','\r',char(13)),'\n',char(10)),'Procurar no Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86893702,'Gluttonia do Multiverso','Uma monstruosidade maciça e malévola, devoradora de diversas dimensões, que molda múltiplos domínios onde apenas os mais poderosos ousam habitar.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86915847,'Abelha Encouraçada','Uma vez por turno: Você pode escolher 1 monstro com a face para cima que seu oponente controla; reduza pela metade o ATK do alvo até a Fase Final.','Reduzir ATK/DEF pela metade','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86926989,'Supremacia Shiranui Destrezasaga',replace(replace('2+ monstros Zumbi	\r\nMonstros Sincro que você controla não podem ser destruídos por efeitos de card. \r\nMonstros de FOGO que você controla não podem ser destruídos em batalha. \r\nDurante o turno do seu oponente (Efeito Rápido): você pode escolher 1 dos seus Monstros Sincro Zumbi banidos; Invoque-o por Invocação-Especial em uma zona sua para a qual este card apontar. \r\nVocê só pode usar este efeito de "Supremacia Shiranui Destrezasaga" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86937530,'Cauda de Fadas - Luna',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode adicionar 1 monstro Mago com 1850 de ATK do seu Deck à sua mão. \r\nUma vez por turno (Efeito Rápido): você pode escolher 1 monstro com a face para cima que seu oponente controla; seu oponente pode enviar 1 card com o nome desse monstro do Deck ou Deck Adicional dele para o Cemitério para negar este efeito, caso contrário, devolva tanto este card como esse monstro para a mão.','\r',char(13)),'\n',char(10)),'Procurar no Deck','Retornar para a mão','Enviar um card com o mesmo nome para o Cemitério para negar este efeito?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86938484,'Sombraneco Construtor',replace(replace('2 monstros de Virar	\r\nDurante sua Fase Principal: você pode Invocar por Invocação-Fusão 1 Monstro de Fusão "Sombraneco" do seu Deck Adicional, usando monstros da sua mão ou do campo como Matéria de Fusão. \r\nSe este card estiver no seu Cemitério: você pode enviar 1 card "Sombraneco" da sua mão ou do campo com a face para cima para o Cemitério e, se isso acontecer, Invoque este card por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Sombraneco Construtor" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86943389,'Alta-Velocidaroide Enigma',replace(replace('1 Regulador + 1 ou mais monstros não-Reguladores	\r\nNo começo da Etapa de Dano, se este card batalhar um monstro Invocado por Invocação-Especial: até o final da Etapa de Dano, você pode fazer com que o ATK deste card se torne o dobro do seu ATK atual. \r\nUma vez por turno, durante a Fase Final, se este card estiver no Cemitério porque este card Invocado por Invocação-Sincro foi enviado para lá do campo neste turno: você pode escolher 1 monstro "Velocidaroide" no seu Cemitério, exceto "Alta-Velocidaroide Enigma"; adicione-o à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86952477,'Cavaleiro Cintilante','Este card é de Nível 4 enquanto estiver com a face para cima em Posição de Defesa.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86962245,'Salamagrande Raposar',replace(replace('Se você tiver 3 ou mais monstros "Salamagrande" no seu Cemitério: você pode enviar este card da sua mão para o Cemitério e, depois, escolher 1 Monstro Link "Salamagrande" no seu Cemitério e 1 card na Zona de Magias & Armadilhas do seu oponente; devolva o monstro alvo do seu Cemitério para o Deck Adicional e, se isso acontecer, destrua o card alvo no campo. \r\nSe um ou mais cards na Zona de Magias & Armadilhas do seu oponente forem destruídos e enviados para o Cemitério, enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial em Posição de Defesa. \r\nVocê só pode usar 1 efeito de "Salamagrande Raposar" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86976918,'Velocidaroide Ultrassabujo',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode enviar 1 card "Velocidaroide" do seu Deck para o Cemitério. \r\nDurante sua Fase Principal, exceto no turno em que este card foi enviado para o Cemitério: você pode banir este card do seu Cemitério e, depois, escolha 1 monstro "Velocidaroide" no seu Cemitério; embaralhe-o no Deck e, se isso acontecer, Invoque por Invocação-Especial 1 Monstro Sincro "Velocidaroide" do seu Deck Adicional com o mesmo Nível mas um nome diferente, mas negue seus efeitos. \r\nVocê só pode usar este efeito de "Velocidaroide Ultrassabujo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86988864,'Lacooda de 3 Corcovas','Ofereça 2 "Lacooda de 3 Corcovas" como Tributo, enquanto estiverem 3 "Lacooda de 3 Bossas" no seu Campo, para comprar 3 cards.','Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86993168,'Hacker Maluco',replace(replace('Se um ou mais monstros forem Invocados por Invocação-Especial no campo do seu oponente (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão. \r\nDurante a Fase Final: você pode banir este card que você controla; tome o controle de 1 monstro que seu oponente controla com o menor ATK (em caso de empate, você seleciona), mas enquanto ele estiver com a face para cima no seu campo, ele não pode ativar seus efeitos e, além disso, você não pode Invocar monstros por Invocação-Especial do Deck Adicional, exceto Monstros Link. \r\nVocê só pode usar cada efeito de "Hacker Maluco" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invoque este card por Invocação Especial da sua mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86997073,'Fortíssimo, a Fortaleza Móvel','Uma vez por turno: você pode Invocar por Invocação-Especial 1 monstro "Exército Senhormek" da sua mão.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86999951,'Deus de Cristal Tistina',replace(replace('Durante sua Fase Principal: você pode colocar tantos monstros que seu oponente controla quanto possível com a face para baixo em Posição de Defesa e, depois, você pode enviar para o Cemitério todos os cards com a face para cima que seu oponente controla. \r\nSe este card em posse do seu dono for destruído por um card do oponente: você pode colocar tantos monstros que seu oponente controla quanto possível com a face para baixo em Posição de Defesa e, depois, você pode enviar para o Cemitério todos os cards com a face para cima que seu oponente controla. \r\nVocê só pode usar cada efeito de "Deus de Cristal Tistina" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Enviar para o Cemitério todos os cards com a face para cima que seu oponente controla?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87003671,'Emília, Sacerdotisa Dançarina de Necroz',replace(replace('Se você Invocar por Invocação-Ritual exatamente 1 Monstro de Ritual "Necroz" com um efeito de card que requer o uso de monstros, este card que você controla pode ser usado como todo o Tributo. \r\nVocê só pode usar cada um dos seguintes efeitos de "Emília, Sacerdotisa Dançarina de Necroz" uma vez por turno. \r\nSe você tiver um monstro "Necroz" Guerreiro no seu campo ou Cemitério: você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 Monstro de Ritual "Necroz" ou 1 Magia "Necroz" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Invocação Especial','Adicionar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87008374,'ZW - Arco Fênix',replace(replace('Você pode escolher 1 "Número C39: Raio Utopia" com a face para cima que você controla; equipe este card da sua mão no alvo. \r\nEle ganha 1100 de ATK. \r\nQuando o monstro equipado destruir um monstro do oponente em batalha: Cause 1000 de dano ao seu oponente. \r\nVocê só pode controlar 1 "ZW - Arco Fênix" com a face para cima.','\r',char(13)),'\n',char(10)),'Equipar','Causar dano','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87010442,'Caçador de Legacia',replace(replace('Quando este card destrói um monstro em Posição de Defesa com a face para baixo, como resultado de um combate e o envia para o Cemitério, o seu adversário devolve 1 card da sua mão aleatóriamente para o seu respective Deck. \r\nEm seguida, embaralhe esse Deck.','\r',char(13)),'\n',char(10)),'Retornar ao Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87025064,'Choro de Prata',replace(replace('Escolha 1 Monstro Normal Dragão no seu Cemitério; Invoque o alvo por Invocação-Especial. \r\nVocê só pode ativar 1 "Choro de Prata" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87043568,'Espíritos Agressores',replace(replace('Depois da ativação, considere este card como um Card de Equipamento e equipe-o a um monstro que você controla. \r\nUma vez por turno, durante o ataque do monstro equipado, você pode enviar 1 monstro com 1000 ou menos de ATK da sua mão ao Cemitério durante a Etapa de Dano para fazer com que o monstro equipado ganhe o ATK do monstro enviado até a Fase Final.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87046457,'Linha da Devastação',replace(replace('Se um ou mais monstros do Tipo Planta forem Invocados por Invocação-Especial do Cemitério no seu lado do campo: eles ganham 1000 de ATK enquanto este card estiver com a face para cima no campo. \r\nDestrua este card durante sua 2ª Fase Final depois da ativação.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87047074,'Besta de Inzektor - Flechizekta',replace(replace('Equipe apenas em um monstro "Inzektor". \r\nEle ganha 500 de ATK. \r\nSeu oponente não pode ativar cards ou efeitos em resposta à ativação dos efeitos do monstro equipado.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87047161,'Tubarão Sereia','Quando este card for Invocado por Invocação-Normal: você pode adicionar 1 monstro do Tipo Peixe de Nível 3, 4 ou 5 do seu Deck à sua mão.','Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87052196,'Espírito Tenyi - Ashuna',replace(replace('Se você não controlar nenhum Monstro de Efeito: você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe você controlar um Monstro que não seja de Efeito com a face para cima: você pode banir este card da sua mão ou do Cemitério; Invoque por Invocação-Especial 1 monstro "Tenyi" do seu Deck, exceto "Espírito Tenyi - Ashuna" e, além disso, você não pode Invocar por Invocação-Especial pelo resto deste turno, exceto monstros Wyrm. \r\nVocê só pode usar cada efeito de "Espírito Tenyi - Ashuna" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invoque este card por Invocação Especial da sua mão','Invoque por Invocação Especial 1 monstro "Tenyi" do seu Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87054946,'Nephthys, a Chama Sagrada',replace(replace('2+ monstros, incluindo um Monstro de Ritual	\r\nEnquanto este card estiver na Zona de Monstros Adicional, os monstros que seu oponente controla não podem escolher monstros "Nephthys" nas Zonas de Monstros Principais como alvos de ataques. \r\nEste card ganha efeitos de acordo com o número de Monstros de Ritual usados para sua Invocação-Link.\r\n● 1+: Não pode ser destruído em batalha.\r\n● 2+: Não pode ser destruído por efeitos de card e, além disso, ele ganha 1200 de ATK.\r\n● 3: Nenhum duelista pode escolher este card como alvo de efeitos de card e, além disso, ele ganha mais 1200 de ATK.','\r',char(13)),'\n',char(10)),'1 ou mais monstros como matéria','2+ monstros como Matéria','3 monstros como matéria','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87074380,'Cidadela Autômata',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial por um efeito de card. \r\n(Efeito Rápido): você pode escolher 1 monstro Máquina que você controla; destrua esse monstro Máquina e todos os monstros que seu oponente controla com ATK menor ou igual que o dele. \r\nSe um ou mais monstros Máquina de TERRA com a face para cima que você controla, exceto "Cidadela Autômata", forem destruídos em batalha ou por um efeito de card enquanto este card estiver no seu Cemitério: você pode Invocar este card por Invocação-Especial. \r\nVocê só pode usar cada efeito de "Cidadela Autômata" uma vez por turno.','\r',char(13)),'\n',char(10)),'Destruir um monstro','Invocar este card por Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87091930,'Mente Inabalável do Raptor',replace(replace('(Este card deve ser sempre considerado como um card "Os Cavaleiros Fantasmas" e "Ataqueraptor".)	\r\nSe você Invocar por Invocação-Xyz usando um Monstro Xyz de TREVAS como matéria: você pode escolher 1 card no campo; destrua-o. \r\nSe este card com a face para cima na Zona de Magias & Armadilhas for destruído por um efeito de card: você pode Baixar 1 Magia "Magia de Aumento de Classe" diretamente do seu Deck ou Cemitério. \r\nVocê só pode usar cada efeito de "Mente Inabalável do Raptor" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87102774,'Joaninha Dourada','Durante sua Fase de Apoio: você pode revelar este card na sua mão e ele permanece revelado até o final deste turno; ganhe 500 PV.','Ganhar PV','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87106146,'Avariar Portal','Quando você sofrer dano de batalha: escolha 1 monstro em seu Cemitério com ATK menor ou igual ao dano que você sofreu; Invoque o alvo por Invocação-Especial.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87112784,'Banimento do Senhor Obscuro',replace(replace('Adicione 1 card "Senhor(a) Obscuro(a)" do seu Deck à sua mão, exceto "Banimento do Senhor Obscuro". \r\nVocê só pode ativar 1 "Banimento do Senhor Obscuro" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87116749,'Passeio Turístico Submareed',replace(replace('O primeiro Monstro Normal que você controla que seria destruído em batalha ou por um efeito de card a cada turno, não é destruído. \r\nSe você controlar um Monstro Normal: você pode Invocar este card por Invocação-Especial da sua mão. \r\nVocê só pode usar este efeito de "Passeio Turístico Submareed" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87116928,'Dragão Megafrota Quimeratech',replace(replace('1 monstro "Dragão Cibernético" + 1+ monstros na Zona de Monstros Adicional	\r\nNão pode ser usado como Matéria de Fusão. \r\nPrimeiro deve ser Invocado por Invocação-Especial (do seu Deck Adicional) ao enviar os cards acima de qualquer campo para o Cemitério. \r\nO ATK original deste card se torna 1200 x o número de matérias usadas para sua Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87116929,'Dragão Megafrota Quimeratech',replace(replace('1 monstro "Dragão Cibernético" + 1+ monstros na Zona de Monstros Adicional	\r\nNão pode ser usado como Matéria de Fusão. \r\nPrimeiro deve ser Invocado por Invocação-Especial (do seu Deck Adicional) ao enviar os cards acima de qualquer campo para o Cemitério. \r\nO ATK original deste card se torna 1200 x o número de matérias usadas para sua Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87118301,'Domador da Besta Espiritual Lara',replace(replace('Se este card for Invocado por Invocação-Normal: você pode escolher 1 monstro "Besta Espiritual" no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê só pode Invocar "Domador(es) da Besta Espiritual Lara" por Invocação-Especial uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87126721,'Multelegante Meowls',replace(replace('Se você não controlar nenhum card (Efeito Rápido): você pode descartar este card; aplique esses efeitos neste turno.\r\n● Sempre que seu oponente Invocar um ou mais monstros por Invocação-Especial de quaisquer Cemitérios ou banimentos, imediatamente compre 1 card.\r\n● Uma vez, durante esta Fase Final, se o número de cards na sua mão for maior que o número de cards que seu oponente controla +6, você deve embaralhar aleatoriamente cards da sua mão no Deck até que o número na sua mão seja igual ao número que seu oponente controla +6.	\r\nVocê só pode ativar 1 outro efeito de monstro "Multelegante" no turno em que ativar este efeito.','\r',char(13)),'\n',char(10)),'Comprar e retornar sua mão para o Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87148330,'Tétis, a Deusa da Luz',replace(replace('Quando você comprar um ou mais monstros Fada (exceto durante a Etapa de Dano): você pode revelar 1 desses monstros; compre 1 card. \r\nEste card deve estar com a face para cima no campo para ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87151205,'Wattaildragão',replace(replace('Capaz de lutar indefinidamente. Ele ataca ao envolver seu corpo em eletricidade e disparando contra seu oponente.\r\nIMPORTANTE: Capturar um "Wattaildragão" é proibido por Leis Antigas e é considerado uma ofensa de Nível 6, cuja pena mínima é o encarceramento por não menos que 2500 heliociclos.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87170768,'"B" Contato',replace(replace('Quando seu oponente Invocar um ou mais monstros por Invocação-Normal ou Especial (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão no campo do oponente em Posição de Defesa. \r\nO controlador deste card não pode Invocar por Invocação-Fusão, Sincro, Xyz ou Link a não ser que use este card como matéria.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87182127,'Howitzer do Mecanismo Antigo',replace(replace('2 monstros "Mecanismo Antigo"	\r\nNão é afetado por outros efeitos de cards. \r\nDurante sua Fase Principal: você pode causar 1000 de dano ao seu oponente. \r\nVocê só pode usar este efeito de "Howitzer do Mecanismo Antigo" uma vez por turno. \r\nSe este card for destruído em batalha e enviado para o Cemitério: você pode Invocar por Invocação-Especial 1 monstro "Mecanismo Antigo" do seu Deck, ignorando suas condições de Invocação.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87188910,'Crocodragão Voraz Arquetis',replace(replace('1 Regulador + 1+ não-Reguladores	\r\nGanha 500 de ATK/DEF para cada card na sua mão. \r\nVocê só pode usar cada um dos seguintes efeitos de "Crocodragão Voraz Arquetis" uma vez por turno. \r\nSe este card for Invocado por Invocação-Sincro: você pode comprar cards igual ao número de não-Reguladores usados para sua Invocação-Sincro. \r\n(Efeito Rápido): você pode descartar 2 cards e, depois, escolha 1 card no campo; destrua-o.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87209160,'Fraktall da Tri-Brigada',replace(replace('Você pode enviar este card da sua mão ou do campo para o Cemitério; envie 1 monstro Besta, Besta-Guerreira ou Besta Alada de Nível 3 ou menos do seu Deck para o Cemitério. \r\nVocê pode banir qualquer número de monstros Besta, Besta-Guerreira e/ou Besta Alada no seu Cemitério; Invoque por Invocação-Especial 1 Monstro Link Besta, Besta-Guerreira ou Besta Alada do seu Deck Adicional, com um Valor Link igual ao número de banidos e, além disso, você só pode usar monstros Besta, Besta-Guerreira e Besta Alada como Matéria Link pelo resto deste turno. \r\nVocê só pode usar cada efeito de "Fraktall da Tri-Brigada" uma vez por turno.','\r',char(13)),'\n',char(10)),'Enviar para o Cemitério','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87210505,'Título de Cavaleiro','Ofereça como Tributo 1 "Mago Negro" com a face para cima; Invoque por Invocação-Especial 1 "Cavaleiro Mago Negro" da sua mão, Deck ou Cemitério.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87240371,'Descida Bezoudado',replace(replace('Invoque por Invocação-Especial 1 "Ficha de Bezoudado" (Inseto/TERRA/Nível 3/ATK 1000/DEF 1000) e, depois, se você controlar um monstro Inseto com 3000 ou mais de ATK, você pode destruir 1 outra Magia/Armadilha no campo. \r\nVocê só pode ativar 1 "Descida Bezoudado" por turno.','\r',char(13)),'\n',char(10)),'Destruir um Card de Magia/Armadilha?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87240372,'Ficha de Bezoudado','Invocado por Especial com o efeito de um card "Bezoudado".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87246309,'Fofanimal Octópode',replace(replace('Quando este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 monstro "Fofanimal" ou "Diabrete de" no seu Cemitério; adicione-o à sua mão. \r\nSe este card for enviado para o Cemitério como uma Matéria de Fusão para uma Invocação-Fusão de um Monstro de Fusão "Peladura": você pode escolher até 2 dos seus monstros banidos; devolva-os para o Cemitério. \r\nVocê só pode usar cada efeito de "Fofanimal Octópode" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87255382,'Besta Heráldica Anfisbena',replace(replace('Você pode descartar 1 outro monstro "Besta Heráldica"; Invoque este card por Invocação-Especial da sua mão. \r\nUma vez por turno: você pode descartar 1 monstro "Besta Heráldica"; este card ganha 800 de ATK até o final deste turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Aumentar ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87257460,'Rainha Cativante LV3',replace(replace('Uma vez por turno: você pode escolher 1 monstro de Nível 3 ou menos que seu oponente controla; equipe o alvo a este card como uma Magia de Equipamento (máx. 1). \r\nSe este card seria destruído em batalha, em vez disso, destrua esse monstro equipado a ele. \r\nDurante sua Fase de Apoio: você pode enviar este card equipado com um monstro pelo efeito deste card para o Cemitério; Invoque por Invocação-Especial 1 "Rainha Cativante LV5" da sua mão ou do Deck.','\r',char(13)),'\n',char(10)),'Equipar','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87259077,'Guerreiro Relâmpago',replace(replace('1 Regulador + 1 ou mais monstros não-Reguladores	\r\nSe este card destruir um monstro do oponente em batalha e enviá-lo para o Cemitério: cause 300 de dano ao seu oponente para cada na mão do seu oponente.','\r',char(13)),'\n',char(10)),'Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87259933,'Conclave Cristalino',replace(replace('Uma vez por turno, se um ou mais monstros "Fera Cristalina" com a face para cima que você controla forem destruídos em batalha ou por um efeito de card: você pode Invocar por Invocação-Especial 1 monstro "Fera Cristalina" do seu Deck. \r\nVocê pode enviar este card com a face para cima do campo para o Cemitério e, depois, escolha 1 card "Fera Cristalina" que você controla e 1 card no campo; devolva-os para a mão. \r\nVocê não pode ativar esses efeitos na mesma Corrente.','\r',char(13)),'\n',char(10)),'Ativar, mas não resolver o efeito','Ativar e aplicar o segundo efeito','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87263576,'Dragão da Erupção',replace(replace('Se você controlar um monstro: você pode Invocar este card por Invocação-Especial da sua mão e, depois, destrua todos os outros monstros que você controla e, além disso, você não pode Invocar monstros por Invocação-Especial, exceto monstros de TREVAS, enquanto este card estiver com a face para cima na Zona de Monstros. \r\nUma vez por Corrente, durante a Fase Principal do seu oponente, você pode (Efeito Rápido): imediatamente depois que este efeito resolver, Invoque por Invocação-Link 1 Monstro Link Dragão usando matérias que você controla, incluindo este card. \r\nVocê só pode usar cada efeito de "Dragão da Erupção" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','O efeito de "Dragão da Erupção" está sendo aplicado.','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87288189,'Caius, o Mega Monarca',replace(replace('Você pode Invocar este card por Invocação-Tributo ao oferecer como Tributo 1 monstro Invocado por Invocação-Tributo. \r\nSe este card for Invocado por Invocação-Tributo: escolha 1 card no campo; bana-o e, se isso acontecer, cause 1000 de dano ao seu oponente e, depois, se for um Card de Monstro de TREVAS, bana todos os cards com esse nome da mão, do Deck Principal, do Deck Adicional e do Cemitério do duelista que o controlava. \r\nSe este card foi Invocado por Invocação-Tributo pelo Tributo de um monstro de TREVAS, adicione este efeito adicional.\r\n● Em vez disso, você pode escolher 2 cards.','\r',char(13)),'\n',char(10)),'Ofereça 1 monstro Invocado por Invocação Tributo como Tributo para uma Invocação Tributo','Banir 1 card','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87292536,'Sabre-XX Ragigura','Quando este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 monstro "Sabre-X" no seu Cemitério; adicione-o à sua mão.','Recuperar do Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87294988,'Chirubimé, Princesa das Folhas de Outono',replace(replace('Seu oponente não pode escolher monstros Planta com a face para cima como alvo de ataques, exceto este. \r\nSe este card em sua posse for enviado para o seu Cemitério por um card do seu oponente: você pode Invocar por Invocação-Especial 1 monstro Planta do seu Deck, exceto "Chirubimé, Princesa das Folhas de Outono".','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87303357,'Abismo Brilhante','Este monstro se utiliza tanto dos poderes da Luz como das Trevas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87313164,'É Tr!ta!','Quando um efeito de monstro for ativado: embaralhe 1 dos seus monstros Peixe, Serpente Marinha ou Aqua banidos no Deck Principal; negue a ativação e, se isso acontecer, destrua esse monstro.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87319876,'Guardião Fiel',replace(replace('Este card não pode ser usado como um Monstro-Matéria Sincro, exceto para a Invocação-Sincro de um Monstro Sincro de Nível 7 ou mais. \r\nUma vez por turno, esse Monstro Sincro não pode ser destruído em batalha. \r\nSempre que este efeito for aplicado, esse Monstro Sincro perde 400 de ATK e DEF no final da Etapa de Dano.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87321742,'Ataqueraptor - Lanius Estrangulador',replace(replace('Se você controlar um monstro de TREVAS: você pode Invocar este card por Invocação-Especial da sua mão e, além disso, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros de TREVAS. \r\nSe você controlar um Monstro Xyz com um Monstro Xyz de TREVAS como matéria: você pode escolher 1 monstro "Ataqueraptor" de Nível 4 ou menos no seu Cemitério; Invoque-o por Invocação-Especial, mas seus efeitos são negados. \r\nVocê só pode usar cada efeito de "Ataqueraptor - Lanius Estrangulador" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87322377,'Aranha Lançadora','Uma aranha mecânica com lança-foguetes capazes de realizar disparos aleatórios.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87322378,'Aranha Lançadora','Uma aranha mecânica com lança-foguetes capazes de realizar disparos aleatórios.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87327776,'Salamagrande Migaranhão',replace(replace('2 monstros de Nível 3	\r\nVocê pode desassociar 1 matéria deste card; Invoque por Invocação-Especial 1 monstro "Salamagrande" do seu Deck em Posição de Defesa e, além disso, você não pode ativar efeitos de monstro pelo resto deste turno, exceto monstros de FOGO. \r\nSe este card Invocado por Invocação-Xyz for enviado para o Cemitério como matéria para a Invocação-Link de um monstro "Salamagrande": você pode escolher 1 monstro no campo; devolva-o para a mão. \r\nVocê só pode usar cada efeito de "Salamagrande Migaranhão" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87340664,'Vagalume Atômico','O jogador que destruir este card no Campo com face para cima, como resultado de um combate, recebe 1000 pontos de dano.','Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87347365,'Golem de Renovação',replace(replace('O efeito de "Golem de Renovação" só pode ser usado uma vez por turno. \r\nQuando este card for enviado do seu Deck ao Cemitério: Ative 1 desses efeitos.\r\n● Invoque este card por Invocação-Especial do Cemitério.\r\n● Adicione este card do Cemitério à sua mão.','\r',char(13)),'\n',char(10)),'Ativar o efeito escolhido','Invocar este card por Invocação Especial','Adicionar este card à sua mão','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87350908,'Fatiador Mascarado','Se este card destruir um monstro do oponente em batalha, cause 2000 de dano ao seu oponente.','Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87390067,'Asanegra - Jetstream, o Céu Azul','Durante o cálculo de dano, você pode enviar este card da sua mão para o Cemitério para evitar que um monstro "Asanegra" que você controla seja destruído por esta batalha.','Não pode ser destruído em batalha','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87390798,'Script do Abismo - Fantasia Mágica',replace(replace('Escolha 1 monstro "Ator do Abismo" que você controla; neste turno, cada monstro que batalhar com ele, mas não for destruído, volta para a mão no final da Etapa de Dano. \r\nSe este card Baixado sob o controle do seu dono for destruído por um efeito de card do seu oponente e você tiver um Monstro Pêndulo "Ator do Abismo" com a face para cima no seu Deck Adicional: você pode escolher 1 card que seu oponente controla; coloque-o no topo do Deck.','\r',char(13)),'\n',char(10)),'O efeito de "Script do Abismo - Fantasia Mágica" está sendo aplicado no momento.','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87430304,'Cronomalia Moai','Se você controlar um monstro "Cronomalia", você pode Invocar este card por Invocação-Especial (da sua mão) em Posição de Defesa.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87430998,'Floresta','Todos os monstros Inseto, Besta, Planta e Besta-Guerreira no campo ganham 200 de ATK/DEF.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87451661,'Dragão Vermelho Arquidemônio com Cicatriz',replace(replace('1 Regulador + 1+ monstros não-Reguladores de TREVAS	\r\nO nome deste card se torna "Dragão Vermelho Arquidemônio" enquanto estiver no campo ou no Cemitério. \r\nSe este card for enviado da Zona de Monstros para o Cemitério: você pode Invocar por Invocação-Especial 1 "Dragão Vermelho Arquidemônio" do seu Deck Adicional (isso é considerado uma Invocação-Sincro) e, depois, se este card foi enviado para o Cemitério como matéria para um Monstro Sincro Dragão de TREVAS, você pode destruir todos os monstros em Posição de Ataque que seu oponente controla. \r\nVocê só pode usar este efeito de "Dragão Vermelho Arquidemônio com Cicatriz" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Destruir todos os monstros em Posição de Ataque que seu oponente controla?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87460579,'Flor Cardian Chama de Luz',replace(replace('1 Regulador + 4 monstros não-Reguladores	\r\nUma vez por turno, durante o turno de qualquer duelista, quando seu oponente ativar um Card de Magia/Armadilha: você pode negar a ativação e, se isso acontecer, destrua esse card. \r\nSe um monstro "Flor Cardian" que você controla batalhar um monstro do oponente, esse monstro do oponente tem seus efeitos negados, apenas durante a Fase de Batalha. \r\nSe este card com a face para cima Invocado por Invocação-Sincro for destruído em batalha, ou deixar o campo devido a um efeito de card do oponente enquanto for controlado por seu dono: você pode Invocar por Invocação-Especial 1 Monstro Sincro "Flor Cardian" do seu Deck Adicional, exceto "Flor Cardian Chama de Luz".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87462901,'Emissário da Casa de Cera',replace(replace('Quando um monstro do oponente declarar um ataque: você pode Invocar este card por Invocação-Especial da sua mão. \r\nVocê só pode usar este efeito de "Emissário da Casa de Cera" uma vez por turno. \r\nSe este card batalhar um monstro, nenhum dos dois pode ser destruído nessa batalha. \r\nNo final da Fase de Batalha do seu oponente: você pode ativar este efeito; até o começo da próxima Fase de Batalha do seu oponente, os monstros em Posição de Ataque que seu oponente controla atualmente não podem mudar suas posições de batalha, nem ser usados como matéria para uma Invocação-Fusão, Sincro, Xyz ou Link e, além disso, seus efeitos são negados.','\r',char(13)),'\n',char(10)),'Invocar este card por Invocação Especial','Negar o efeito','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87468732,'Relógio Arc',replace(replace('Escala de Pêndulo = 4\r\n[ Efeito de Pêndulo ]\r\nSe você não controlar nenhum monstro, ou apenas Monstros Pêndulo, aplique este efeito, de acordo com a Zona de Pêndulo deste card.\r\n● Esquerda: Reduza sua Escala de Pêndulo em 3.\r\n● Direita: Aumente sua Escala de Pêndulo em 4.	\r\nDurante a Fase de Apoio do seu oponente: você pode Invocar este card por Invocação-Especial.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nSe este card for Invocado por Invocação-Especial em uma zona que não seja a Zona de Monstros Principal central, destrua-o. \r\nNão pode ser destruído em batalha. \r\nUma vez por turno, durante a Fase Final do seu oponente: você pode escolher 1 card na sua Zona de Pêndulo; destrua-o e, se isso acontecer, coloque este card na sua Zona de Pêndulo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87473172,'Pássaro do Fogo','Enquanto este card permanecer no Campo com a face para cima, cada vez que um monstro(s) do Tipo Besta Alada no seu Campo é destruído, aumente o ATK deste card em 500 pontos.','Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87475570,'Mestre Cristalino',replace(replace('Escala de Pêndulo = 5\r\n[ Efeito de Pêndulo ]\r\nSeu oponente não pode escolher monstros "Cristalino(a) Definitivo(a)" ou cards "Fera Cristalina" que você controla como alvo de efeitos de card.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nVocê pode oferecer este card como Tributo; adicione 1 monstro "Cristalino(a) Definitivo(a)", monstro "Fera Cristalina", ou Magia/Armadilha "Cristalino(a)" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87481592,'Dogmatikacismo',replace(replace('Se o monstro equipado for um monstro "Dogmatika", ele ganha ATK igual ao seu Nível x 100. \r\nSe não, ele perde 200 de ATK para cada monstro "Dogmatika" que você controla. \r\nSe este card for enviado para o Cemitério devido ao monstro equipado ser destruído: você pode enviar 1 monstro do seu Deck Adicional para o Cemitério. \r\nVocê só pode usar este efeito de "Dogmatikacismo" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87483942,'Ninja Prateado Sênior',replace(replace('Quando este card for virado com a face para cima: Você pode Invocar por Invocação-Especial qualquer número de monstros "Ninja", exceto "Ninja Prateado Sênior", da sua mão e/ou Cemitério com a face para baixo em Posição de Defesa. \r\nSó pode haver 1 "Ninja Prateado Sénior" com a face para cima no campo.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87497553,'Testamento Crusadia',replace(replace('Ative 1 desses efeitos.\r\n● Neste turno, seu oponente não pode ativar cards ou efeitos em resposta à ativação dos efeitos dos seus monstros "Crusadia".\r\n● Depois do cálculo de dano, se um Monstro Link "Crusadia" seu destruir um monstro do oponente em batalha: compre cards igual ao Valor Link do seu monstro.	\r\nVocê só pode ativar 1 "Testamento Crusadia" por turno.','\r',char(13)),'\n',char(10)),'Não pode ser ativado em resposta','Comprar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87498729,'Caído da Tistina',replace(replace('Você pode enviar este card da sua mão ou do campo para o Cemitério; coloque 1 "Domínio Divino Baatistina" do seu Deck, com a face para cima na sua Zona do Campo. \r\nSe uma ou mais Magias/Armadilhas "Tistina" com a face para cima que você controla forem destruídas por um efeito de card do oponente, enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode banir este card; Invoque por Invocação-Especial 1 monstro "Tistina" de LUZ da sua mão, do Deck ou do Cemitério. \r\nVocê só pode usar cada efeito de "Caído da Tistina" uma vez por turno.','\r',char(13)),'\n',char(10)),'Colocar "Domínio Divino Baatistina"','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87511987,'Spikebot','Um soldado mecânico criado por um mago perverso. Ataca com as duas bolas de aço que tem ligadas aos seus braços.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87514539,'Ácaro Marionete','Você pode descartar este card para o Cemitério e, depois, escolha 1 monstro Zumbi ou Demônio que seu oponente controla; tome o controle do alvo até a Fase Final.','Tomar controle','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87523462,'Sábio Falcos Alado','Quando este card destruir em batalha um monstro do oponente com a face para cima e em Posição de Ataque e enviá-lo para o Cemitério dele: você pode colocar esse monstro no topo do Deck do seu oponente.','Retornar ao Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87526784,'Papa-Bugs X',replace(replace('Quando este card for Invocado por Invocação-Normal: Você pode Invocar por Invocação-Especial 1 "Papa-Bugs Z" do seu Deck. \r\nVocê deve controlar um "Papa-Bugs Y" com a face para cima para ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87532344,'Eterno Favorito',replace(replace('Uma vez por turno: você pode ativar 1 desses efeitos (mas você só pode usar cada efeito de "Eterno Favorito" uma vez por turno);\r\n● Invoque por Invocação-Especial 1 dos seus monstros "Yubel" que estiverem banidos ou no seu Cemitério.	\r\nNenhum duelista pode ativar cards ou efeitos quando esse monstro for Invocado por Invocação-Especial.\r\n● Se você controlar "Yubel": descarte 1 card e envie este card com a face para cima para o Cemitério; Invoque por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional, usando monstros de qualquer campo como matéria, incluindo um monstro "Yubel".','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial 1 monstro "Yubel"','Invocar por Invocação Fusão usando um monstro "Yubel"','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87535691,'Samurai Superpesado Tambor',replace(replace('Se este card no campo for destruído e enviado para o Cemitério: você pode escolher 1 monstro "Samurai Superpesado" no seu Cemitério, exceto "Samurai Superpesado Tambor"; Invoque-o por Invocação-Especial. \r\nVocê só pode usar este efeito de "Samurai Superpesado Tambor" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87557188,'O Místico Implacável','VIRE: Revele todos os cards com a face para baixo no campo (Efeitos de Virar não são ativados) e, depois, devolva-os às suas posições originais.','Revelar um card Baixado','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87564352,'Dragão de Fogo da Terra Negra','Um dragão que vive nas profundezas da escuridão. A sua grande vulnerabilidade é a sua fraca visão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87564935,'Soltite - Parasita de Metal',replace(replace('Uma vez por turno, você pode tanto: Escolha 1 monstro com a face para cima que você controla; equipe este card ao alvo, OU: Desequipe este card e Invoque-o por Invocação-Especial com a face para cima em Posição de Ataque. \r\nEnquanto estiver equipado por este efeito, o monstro equipado não pode ser escolhido como alvo ou destruído por efeitos de monstro do oponente. \r\n(Um monstro só pode ser equipado com 1 Monstro União por vez. Se o monstro equipado seria destruído em batalha, em vez disso, destrua este card.)','\r',char(13)),'\n',char(10)),'Equipar','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87567063,'Rebelião',replace(replace('Durante a Fase de Batalha de qualquer duelista: escolha 1 monstro que seu oponente controla; tome o controle dele até o final da Fase de Batalha e, além disso, outros monstros que você controla não podem atacar pelo resto deste turno. \r\nVocê só pode ativar 1 "Rebelião" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87571563,'Dragão-Guarda do Legado Mundial',replace(replace('Quando este card for ativado: você pode escolher 1 monstro Dragão de Nível 4 ou menos no seu Cemitério; adicione-o à sua mão ou Invoque-o por Invocação-Especial. \r\nUma vez por turno: você pode escolher 1 monstro Dragão que você controla; mova esse monstro que você controla para outra das suas Zonas de Monstros Principais. \r\nVocê só pode ativar 1 "Dragão-Guarda do Legado Mundial" por turno.','\r',char(13)),'\n',char(10)),'','Escolher como alvo 1 monstro Dragão no Cemitério?','Escolha 1 card para mover','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87588741,'Qliphort Cefalópodes',replace(replace('Escala de Pêndulo = 9\r\n[ Efeito de Pêndulo ]\r\nVocê não pode Invocar monstros por Invocação-Especial, exceto monstros "Qli". \r\nEste efeito não pode ser negado. \r\nTodos os monstros que seu oponente controla perdem 300 de ATK.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nVocê pode Invocar este card por Invocação-Normal sem oferecer Tributo. \r\nSe este card for Invocado por Invocação-Normal sem oferecer Tributo, ou se for Invocado por Invocação-Especial, o Nível dele se torna 4 e o ATK original dele se torna 1800. \r\nSe este card for Invocado por Invocação-Normal/Baixado, ele não é afetado por efeitos ativados de monstros cujo Nível/Classe original seja menor que o Nível atual deste card. \r\nQuando este card for Invocado por Invocação-Tributo pelo Tributo de um ou mais monstros "Qli": você pode ativar este efeito; se seu oponente tiver mais monstros no Cemitério dele do que você, você ganha PV igual à diferença x 300, e, se isso acontecer, cause o mesmo valor de dano ao seu oponente.','\r',char(13)),'\n',char(10)),'Invocação Normal sem Tributo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87602890,'Zaborg, o Mega Monarca',replace(replace('Você pode Invocar este card por Invocação-Tributo ao oferecer como Tributo 1 monstro Invocado por Invocação-Tributo. \r\nSe este card for Invocado por Invocação-Tributo: escolha 1 monstro no campo; destrua-o e, depois, se ele era um monstro de LUZ, os dois duelistas enviam tantos cards quanto possível do Deck Adicional deles para o Cemitério, mas não mais que o Nível/Classe original desse monstro destruído. \r\nSe este card foi Invocado por Invocação-Tributo pelo Tributo de um monstro de LUZ, adicione este efeito adicional.\r\n● Você seleciona os cards que seu oponente envia para o Cemitério.','\r',char(13)),'\n',char(10)),'Ofereça 1 monstro Invocado por Invocação Tributo como Tributo para uma Invocação Tributo','Destruir um monstro','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87607094,'Callibre Reinicializado',replace(replace('Quando seu oponente ativar um Card de Magia/Armadilha, enquanto você controlar um monstro "Foguette" ou "Callibre": negue a ativação e, se isso acontecer, Baixe esse card com a face para baixo no campo do seu oponente, mas ele não pode ser ativado neste turno. \r\nVocê pode ativar este card da sua mão ao pagar metade dos seus PV.','\r',char(13)),'\n',char(10)),'Ativar','Ativar aplicando o efeito de "Callibre Reinicializado".','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87608852,'Temperança da Profecia',replace(replace('Durante sua Fase Principal, se você ativou um Card de Magia "Livro de Magia" anteriormente neste turno: Você pode oferecer este card como Tributo; Invoque por Invocação-Especial 1 monstro de LUZ ou de TREVAS do Tipo Mago de Nível 5 ou mais do seu Deck. \r\nVocê não pode Invocar por Invocação-Especial outro monstro de Nível 5 ou mais durante o turno em que você ativar este efeito.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87609391,'Maça Definitiva do Raptor',replace(replace('Só pode ser equipado a um monstro "Ataqueraptor". \r\nEle ganha 1000 de ATK. \r\nQuando o monstro equipado for escolhido como alvo de um ataque por um monstro cujo ATK seja maior que o do monstro equipado: você pode adicionar 1 Card de Magia "Magia de Aumento de Classe" do seu Deck à sua mão e, se isso acontecer, você não sofre dano de batalha dessa batalha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87614611,'Vaso do Dragão Vermelho',replace(replace('Se você controlar um "Dragão Vermelho Arquidemônio": compre 2 cards. \r\nVocê não pode Invocar monstros por Invocação-Normal ou Especial no turno em que ativar este card e até o final do turno do seu oponente depois que este card for ativado.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87621407,'Dekoichi, a Locomotiva da Canção de Batalha','VIRE: Compre 1 card e, depois, compre 1 card adicional para cada "Bokoichi, o Vagão Assustador" com a face para cima que você controla.','Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87622767,'Ogro Final Psíquico','Se este card destruir um monstro do oponente em batalha, você pode pagar 800 PV para selecionar 1 monstro do Tipo Psíquico no seu Cemitério e adicioná-lo à sua mão.','Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87624166,'Floresta Anciã',replace(replace('Quando você ativar este card, mude quaisquer monstros em Posição de Defesa para Posição de Ataque com a face para cima. \r\nEfeitos de Virar não são ativados neste momento. \r\nSe um monstro atacar, destrua-o no final da Fase de Batalha desse turno.','\r',char(13)),'\n',char(10)),'Destruir o monstro atacante','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87639778,'Tempestade de Penas da Harpia',replace(replace('Se você controlar um monstro Besta Alada de VENTO: até o final deste turno, negue quaisquer efeitos de monstro que seu oponente ativar. \r\nSe você controlar um monstro "Harpia", você pode ativar este card da sua mão. \r\nSe este card na Zona de Magias & Armadilhas do seu dono for destruído por um efeito de card do oponente: você pode adicionar 1 "Espanador de Penas da Harpia" do seu Deck ou Cemitério à sua mão.','\r',char(13)),'\n',char(10)),'','Ativar aplicando o efeito de "Tempestade de Penas da Harpia".','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87640391,'Zereort Migratória',replace(replace('Se um Monstro Xyz de ÁGUA estiver no campo: você pode Invocar este card por Invocação-Especial da sua mão. \r\nDurante sua Fase Principal: você pode desassociar 1 matéria de um monstro que você controla e, depois, você pode Invocar por Invocação-Especial 1 monstro de ÁGUA de Nível 3 ou 4 da sua mão ou do Cemitério, mas seus efeitos são negados e, além disso, ele pode ser considerado como um monstro de Nível 5 neste turno, se for usado para a Invocação-Xyz de um monstro de ÁGUA. \r\nVocê só pode usar cada efeito de "Zereort Migratória" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial da mão','Invocar por Invocação Especial (efeitos negados)','Invocar um monstro por Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87649699,'Ambrosia de Naturia','Quando seu oponente comprar um ou mais cards (exceto durante a Fase de Compra ou Etapa de Dano): você pode enviar este card do campo para o Cemitério; compre 2 cards.','Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87669904,'Convite dos Dois Avatares',replace(replace('Descarte 1 card e, se isso acontecer, Invoque por Invocação-Especial tantas "Ficha do Espírito dos Dois Avatares" quanto possível (Guerreiro/LUZ/Nível 2/ATK 0/DEF 0) e, além disso, pelo resto deste turno, você não pode Invocar monstros do Deck Adicional por Invocação-Especial, exceto Monstros de Fusão, e todas as Fichas que você controla não podem ser oferecidas como Tributo e são destruídas durante a Fase Final. \r\nDepois de Invocar essa(s) \r\nFicha(s), você pode aplicar este efeito até duas vezes.\r\n● Invoque por Invocação-Fusão 1 Monstro de Fusão "Dois Avatares" do seu Deck Adicional, usando monstros da sua mão ou do campo como Matéria de Fusão.	\r\nVocê só pode ativar 1 "Convite dos Dois Avatares" por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Fusão?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87669905,'Ficha do Espírito dos Dois Avatares','Invocado por Especial com o efeito "Convite dos Dois Avatares" ou um card relacionado.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87676171,'Tistina, a Divindade que Desafia a Escuridão',replace(replace('2 monstros de Nível 10	\r\nSe este card for Invocado por Invocação-Especial: você pode enviar para o Cemitério todos os cards com a face para baixo que seu oponente controla. \r\nVocê só pode usar este efeito de "Tistina, a Divindade que Desafia a Escuridão" uma vez por turno. \r\nUma vez por turno, se este card tiver "Deus de Cristal Tistina" como matéria: você pode desassociar 1 matéria deste card; ele ganha 2000 de ATK até o final do turno do seu oponente. \r\nSe este card que você controla for destruído por um card do oponente enquanto ele tiver matéria: você pode Invocar por Invocação-Especial 1 monstro "Tistina" do seu Cemitério.','\r',char(13)),'\n',char(10)),'Enviar um card com a face para baixo para o Cemitério','Aumentar ATK','Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87685879,'Coala Marinho',replace(replace('Uma vez por turno: você pode escolher 1 monstro com a face para cima que seu oponente controla; até o final deste turno, mude o ATK do alvo para 0. \r\nVocê deve controlar outro monstro Besta para ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'ATK torna-se 0','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87742943,'Lagarta Potencializada',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode destruir 1 monstro que seu oponente controla com ATK menor que o deste card. \r\nVocê só pode usar este efeito de "Lagarta Potencializada" uma vez por turno. \r\nTodos os monstros que seu oponente controla devem atacar, se possível.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87746184,'Albion, o Dragão Marcado',replace(replace('"Caído de Arbaz" + 1 monstro de LUZ	\r\nSe este card for Invocado por Invocação-Fusão: você pode Invocar por Invocação-Fusão 1 Monstro de Fusão de Nível 8 ou menos do seu Deck Adicional, exceto "Albion, o Dragão Marcado", ao banir as Matérias de Fusão mencionadas nele da sua mão, do campo e/ou do Cemitério. \r\nDurante a Fase Final, se este card estiver no Cemitério porque foi enviado para lá neste turno: você pode adicionar à sua mão ou Baixar 1 Magia/Armadilha "Marcado" do seu Deck. \r\nVocê só pode usar cada efeito de "Albion, o Dragão Marcado" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87750925,'Disfarce, o Herói Imitador',replace(replace('Se você tiver uma Magia de Equipamento no seu campo ou Cemitério: você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 "Armas Nobres do Imitador Amaldiçoado" do seu Deck à sua mão. \r\nEnquanto este card estiver equipado com um Card de Equipamento: você pode escolher 1 monstro Guerreiro não-Regulador no campo com um Nível; o Nível deste card e, além disso, seu nome, se tornam os mesmos que o desse monstro até a Fase Final. \r\nVocê só pode usar cada efeito de "Disfarce, o Herói Imitador" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Adicionar à mão','Alterar o nome do card e o Nível','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87751584,'Dragão Metralhadora',replace(replace('"Dragão Revólver" + "Dragão Solta Fogo"	\r\nUma vez por turno: você pode lançar uma moeda 3 vezes e destruir tantos monstros no campo quanto for possível, mas não mais que o número de Caras.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87756343,'Larvae Moth','Este monstro não pode ser Invocado a não ser por Invocação-Especial oferecendo "Pequeno Moth" como Tributo no seu 2º turno depois do turno em que "Pequeno Moth" foi equipado com "Casulo de Evolução".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87758525,'Homem-Alado da Chama Brilhante, o HERÓI Favorito',replace(replace('1 Monstro de Fusão + 1 monstro com a face para cima no campo	\r\n(Este card deve ser sempre considerado como um card "HERÓI do Elemento".)	\r\nSe este card for Invocado por Invocação-Especial do Deck Adicional: você pode embaralhar no Deck 5 monstros do seu Cemitério e, depois, compre 2 cards e, se isso acontecer, este card ganha 1000 de ATK. \r\nVocê só pode usar este efeito de "Homem-Alado da Chama Brilhante, o HERÓI Favorito" uma vez por turno. \r\nSe este card destruir um monstro em batalha: cause dano ao seu oponente igual ao ATK original desse monstro.','\r',char(13)),'\n',char(10)),'Retornar ao Deck','Causar dano','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87758526,'Homem-Alado da Chama Brilhante, o HERÓI Favorito',replace(replace('1 Monstro de Fusão + 1 monstro com a face para cima no campo	\r\n(Este card deve ser sempre considerado como um card "HERÓI do Elemento".)	\r\nSe este card for Invocado por Invocação-Especial do Deck Adicional: você pode embaralhar no Deck 5 monstros do seu Cemitério e, depois, compre 2 cards e, se isso acontecer, este card ganha 1000 de ATK. \r\nVocê só pode usar este efeito de "Homem-Alado da Chama Brilhante, o HERÓI Favorito" uma vez por turno. \r\nSe este card destruir um monstro em batalha: cause dano ao seu oponente igual ao ATK original desse monstro.','\r',char(13)),'\n',char(10)),'Retornar ao Deck','Causar dano','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87765315,'Forja do Verdadeiro Draco','Se um monstro "Dracossassino", que não seja um Monstro Pêndulo, e um monstro "Dracosuserano" estiverem no campo: embaralhe no Deck tantos cards do campo quanto possível e, depois, você pode Invocar por Invocação-Especial 1 monstro "Dracossassino" ou "Dracosuserano" do seu Deck, ignorando suas condições de Invocação.','Invocar aquele monstro por Invocação Especial?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87769556,'Mão Direita do Mago','Negue o efeito do primeiro Card ou efeito de Magia do seu oponente que resolver a cada turno enquanto você controlar um monstro Mago e, se isso acontecer, ou se ele não teve efeito, destrua esse card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87772572,'Gato Quântico',replace(replace('Ative este card ao declarar 1 Tipo de Monstro e 1 Atributo; Invoque este card por Invocação-Especial como um Monstro Normal (Nível 4/ATK 0/DEF 2200) com esse Tipo e Atributo.	\r\n(Este card ainda é considerado uma Armadilha.)','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87774234,'Watapon','Se este card for adicionado do seu Deck à sua mão por um efeito de card: Você pode Invocar este card por Invocação-Especial.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87778106,'Recette de Poisson (Receita de Peixe)',replace(replace('Este card pode ser usado para a Invocação-Ritual de qualquer Monstro de Ritual "Nouvelles". \r\nVocê também deve oferecer como Tributo monstros da sua mão ou do campo cuja soma dos Níveis seja igual ou exceda o Nível do Monstro de Ritual que você Invocar por Invocação-Ritual. \r\nDepois, se você Invocou por Invocação-Ritual "Buerillabaisse de Nouvelles", você pode aplicar o seguinte efeito.\r\n● Adicione 1 Magia de Ritual "Receita" do seu Deck ou Cemitério à sua mão, exceto "Recette de Poisson (Receita de Peixe)".','\r',char(13)),'\n',char(10)),'Adicionar à sua mão 1 Magia Ritual "Receita"?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87796900,'Dragão Alado, Guardião da Fortaleza Nº1','Um dragão normalmente encontrado protegendo fortalezas das montanhas. O seu ataque característico é um mergulho arrebatador vindo do céu.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87798440,'Quebrador de Armadura',replace(replace('Uma vez por turno, você pode equipar este card a um monstro do Tipo Guerreiro que você controla, OU desequipá-lo e Invocar este card por Invocação-Especial com a face para cima em Posição de Ataque. \r\nEnquanto estiver equipado a um monstro por este efeito de card, cada vez que o monstro equipado causar Dano de Batalha ao seu oponente, destrua 1 card no campo. \r\n(1 monstro só pode ser equipado com 1 Monstro União por vez. Se o monstro equipado seria destruído em batalha, em vez disso, destrua este card.)','\r',char(13)),'\n',char(10)),'Equipar','Invocação Especial','Destruir','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87800375,'Até que as Armas Nobres sejam Necessárias Novamente',replace(replace('Escave cards do topo do seu Deck, igual ao número de Magias de Equipamento "Armas Nobres" que você controla e, se isso acontecer, adicione 1 deles à sua mão e, além disso, coloque os cards restantes no topo do seu Deck em qualquer ordem. \r\nVocê pode banir este card do seu Cemitério, exceto no turno em que este card foi enviado para o Cemitério; Invoque por Invocação-Especial do seu Deck, 1 monstro "Nobre Cavaleiro" com um nome diferente dos cards que você controla ou no seu Cemitério. \r\nVocê só pode usar este efeito de "Até que as Armas Nobres sejam Necessárias Novamente" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87804365,'Superfatorial Mechamático',replace(replace('Escolha até 3 monstros "Mechamático(a)" com nomes diferentes no seu Cemitério e, depois, ative 1 desses efeitos;\r\n● Invoque-os por Invocação-Especial, mas seus efeitos são negados e, depois, imediatamente depois que este efeito resolver, Invoque por Invocação-Sincro 1 Monstro Sincro "Mechamático(a)" usando apenas esses monstros, e embaralhe as matérias no Deck em vez de enviá-las para o Cemitério.\r\n● Invoque-os por Invocação-Especial, mas seus efeitos são negados e, depois, imediatamente depois que este efeito resolver, Invoque por Invocação-Xyz 1 Monstro Xyz "Mechamático(a)" usando apenas esses monstros.	\r\nVocê só pode ativar 1 "Superfatorial Mechamático" por turno.','\r',char(13)),'\n',char(10)),'Reviver e Invocar por Invocação Sincro','Reviver e Invocar por Invocação Xyz','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87804747,'Grande Inseto Definitivo',replace(replace('1 monstro Inseto de Nível 8 + 1 monstro Inseto de Nível 7	\r\nVocê só pode Invocar "Grande Inseto Definitivo" por Invocação-Especial uma vez por turno. \r\nPrimeiro deve ser Invocado por Invocação-Fusão, ou Invocado por Invocação-Especial do seu Deck Adicional ao oferecer como Tributo 1 monstro Inseto com 2000 ou mais de DEF equipado com um Card de Equipamento. \r\nNão pode ser destruído em batalha. \r\nUma vez por turno, durante a Fase de Batalha, se um card com a face para cima estiver em uma Zona do Campo (Efeito Rápido): você pode destruir todos os monstros que seu oponente controla.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87814728,'Guerreiro Ímã Sigma Minus',replace(replace('Uma vez por turno, quando um ataque for declarado envolvendo 2 monstros de TERRA: você pode negar o ataque. \r\nVocê só pode usar cada um dos seguintes efeitos de "Guerreiro Ímã Sigma Minus" uma vez por turno. \r\nVocê pode revelar este card na sua mão; Invoque por Invocação-Fusão 1 Monstro de Fusão do seu Deck Adicional, usando monstros Rocha da sua mão ou do campo, incluindo este card na sua mão. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode enviar 1 monstro "Guerreiro Ímã" de Nível 8 do seu Deck para o Cemitério.','\r',char(13)),'\n',char(10)),'Invocação Fusão','Enviar para o Cemitério','Negar o ataque','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87818869,'Magia de Hiper Aumento de Classe Força Ultimato',replace(replace('Escolha 1 Monstro Xyz de Classe 9 ou menor "Utopia" ou "Utópico" que você controla cujo Atributo original seja LUZ; Invoque por Invocação-Especial 1 Monstro Xyz de Classe 10 ou maior "Número" do seu Deck Adicional, usando aquele monstro que você controla (isso é considerado uma Invocação-Xyz, transfira suas matérias), e se fizer, associe este card a ele.\r\nUm Monstro Xyz "Número 99" que tiver este card como matéria ganha este efeito:\r\n● Uma vez por Corrente, quando seu oponente ativar um efeito de monstro durante a Fase de Batalha (Efeito Rápido): desassocie todas as matérias deste card, e se fizer, destrua todos os monstros que ele controla.','\r',char(13)),'\n',char(10)),'Ativar','Efeito de destruição (Magia de Hiper Aumento de Classe Força Ultimato)','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87819421,'Carregar Máscara','Escolha 1 monstro "HERÓI" e 1 Card de Magia Rápida "Mudar" no seu Cemitério; adicione-os à sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87835759,'Cavaleiro Dragão da Criação',replace(replace('Aumente o Nível deste card em 4, apenas durante o turno do seu oponente. \r\nQuando este card destruir um monstro do oponente em batalha e enviá-lo para o Cemitério: você pode enviar 1 monstro Dragão de Nível 7 ou 8 do seu Deck para o Cemitério. \r\nVocê pode enviar 1 card da sua mão para o Cemitério e, depois, escolha 1 monstro Dragão de Nível 7 ou 8 no seu Cemitério; envie este card para o Cemitério e, se isso acontecer, Invoque esse monstro por Invocação-Especial. \r\nVocê só pode usar este efeito de "Cavaleiro Dragão da Criação" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87836938,'Vanguarda Vylon','Quando este card for destruído por um efeito de card e enviado ao Cemitério: Você pode comprar 1 card para cada Card de Equipamento que estava equipado a este card.','Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87837090,'Kuibelt, o Dragão Lâmina',replace(replace('1 Regulador + 1+ monstros não-Reguladores	\r\nSe este card for Invocado por Invocação-Sincro: você pode escolher 1 card no campo; destrua-o. \r\nSe este card no campo for destruído: você pode escolher 1 monstro com a face para cima no campo; esse monstro não pode atacar até o final do turno do seu oponente. \r\nVocê só pode usar cada efeito de "Kuibelt, o Dragão Lâmina" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87844926,'Coleta de Almas',replace(replace('Você só pode controlar 1 "Coleta de Almas". \r\nSempre que seu oponente Invocar um ou mais monstros por Invocação-Especial, envie os 3 cards do topo do Deck do seu oponente para o Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87871125,'Salamagrande Lobo da Luz do Sol',replace(replace('2 Monstros de Efeito de FOGO	\r\nSe um ou mais monstros forem Invocados por Invocação-Normal ou Especial em uma ou mais zonas para as quais este card apontar (exceto durante a Etapa de Dano): você pode adicionar 1 monstro de FOGO do seu Cemitério à sua mão, mas pelo resto deste turno, você não pode Invocar por Invocação-Normal/Baixar ou por Invocação-Especial monstros com o nome do monstro adicionado. \r\nDurante sua Fase Principal, se você controlar este card que foi Invocado por Invocação-Link usando "Salamagrande Lobo da Luz do Sol" como matéria: você pode adicionar 1 Magia/Armadilha "Salamagrande" do seu Cemitério à sua mão. \r\nVocê só pode usar cada efeito de "Salamagrande Lobo da Luz do Sol" uma vez por turno.','\r',char(13)),'\n',char(10)),'Recuperar monstros do Cemitério','Recuperar Magias/Armadilhas do Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87880531,'Difusão em Movimento de Onda',replace(replace('(Este card não é considerado como um card "Fusão".)	\r\nSe seu oponente controlar um monstro: pague 1000 PV e, depois, escolha 1 monstro Mago de Nível 7 ou mais que você controla; neste turno, ele deve atacar cada monstro que seu oponente controla uma vez cada e, além disso, outros monstros que você controla não podem atacar. \r\nOs efeitos dos monstros destruídos por esses ataques não podem ativar e são negados.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87890143,'Força de Geração','Se você controlar um Monstro Xyz: adicione 1 card "Xyz" do seu Deck à sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87897777,'Marquês Enlouquecido Vaylantz',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nSe "Mundo Vaylantz - Konig Wissen" estiver em uma Zona do Campo ou se você controlar um monstro "Vaylantz" de FOGO: você pode Invocar este card por Invocação-Especial na sua Zona de Monstros Principal em sua mesma coluna. \r\nVocê só pode usar este efeito de "Marquês Enlouquecido Vaylantz" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nDurante sua Fase Principal: você pode lançar um dado de seis faces, escavar esse número de cards do topo do seu Deck (ou tantos quanto puder) e, se isso acontecer, você pode adicionar 1 card "Vaylantz" escavado à sua mão e, além disso, embaralhe o resto no Deck. \r\nSe este card na Zona de Monstros se mover para outra Zona de Monstros: você pode lançar um dado de seis faces, e se o resultado for 2, 3, 4 ou 5, Invoque por Invocação-Especial 1 Card de Monstro da sua Zona de Magias & Armadilhas na sua Zona de Monstros Principal em sua mesma coluna. \r\nVocê só pode usar cada efeito de "Marquês Enlouquecido Vaylantz" uma vez por turno.','\r',char(13)),'\n',char(10)),'Escolher 1 card para adicionar à mão?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87902575,'Visões do Futuro',replace(replace('Sempre que um monstro for Invocado por Invocação-Normal: escolha esse monstro; bana-o. \r\nDurante a próxima Fase de Apoio do duelista que controlava esse monstro: devolva-o para o campo com a face para cima em Posição de Ataque.','\r',char(13)),'\n',char(10)),'Banir','Retornar ao Campo','Escolha o(s) card(s) a retornar para o campo','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87910978,'Controle Cerebral','Pague 800 PV e, depois, escolha 1 monstro com a face para cima que seu oponente controla que possa ser Invocado por Invocação-Normal/Baixado; tome o controle do alvo até a Fase Final.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87911394,'Número C39: Raio Vitória Utopia',replace(replace('3 monstros de Nível 5	\r\nSe este card atacar, seu oponente não pode ativar quaisquer Cards de Magia/Armadilha até o final da Etapa de Dano. \r\nSe este card tiver um monstro "Utopia" como Matéria Xyz, ele ganha este efeito.\r\n● Quando este card declarar um ataque contra um monstro com a face para cima que seu oponente controla: você pode desassociar 1 Matéria Xyz deste card; negue os efeitos desse monstro com a face para cima do oponente e, além disso, este card ganha ATK igual ao ATK desse monstro do oponente.	\r\nEssas mudanças duram até o final deste turno.','\r',char(13)),'\n',char(10)),'Negar efeitos','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87917187,'Besta da Invocação Negra',replace(replace('Você pode oferecer este card como Tributo; Invoque por Invocação-Especial 1 "Uria, o Senhor das Chamas Cortantes", "Hamon, o Senhor do Trovão Impactante" ou "Raviel, o Senhor dos Fantasmas" da sua mão ou do Deck, ignorando suas condições de Invocação e, além disso, os monstros que você controla não podem atacar pelo resto deste turno. \r\nVocê só pode usar este efeito de "Besta da Invocação Negra" uma vez por turno. \r\nVocê pode banir este card do seu Cemitério; adicione 1 "Uria, o Senhor das Chamas Cortantes", "Hamon, o Senhor do Trovão Impactante" ou "Raviel, o Senhor dos Fantasmas" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87931906,'Fusão Luzlunar',replace(replace('Invoque por Invocação-Fusão 1 Monstro de Fusão "Luzlunar" do seu Deck Adicional, usando monstros da sua mão ou do campo como matéria. \r\nSe seu oponente controlar um monstro que foi Invocado por Invocação-Especial do Deck Adicional, você também pode usar 1 monstro "Luzlunar" no seu Deck ou Deck Adicional como matéria. \r\nVocê só pode ativar 1 "Fusão Luzlunar" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87955518,'Receita Especial do Chef',replace(replace('Quando um Card de Magia/Armadilha, ou efeito de monstro, for ativado enquanto você controlar um Monstro de Ritual "Nouvelles": negue a ativação e, depois, você pode destruir esse card se você controlar um monstro que foi Invocado por Invocação-Especial pelo efeito de um monstro "Nouvelles". \r\nSe você Invocar por Invocação-Especial "Hambúrguer Esfomeado": você pode banir este card do seu Cemitério; ofereça como Tributo tantos monstros que seu oponente controla quanto possível. \r\nVocê só pode usar cada efeito de "Receita Especial do Chef" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Ofereça como Tributo o máximo possível de monstros que seu oponente controla','Destruir essa card?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87973893,'Machado Inzektor - Falcozekta',replace(replace('Equipe apenas em um monstro "Inzektor". \r\nEle ganha 1000 de ATK. \r\nQuando o monstro equipado declarar um ataque, seu oponente não pode ativar Cards de Magia/Armadilha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87978805,'Carrapato Parasitário','O ATK e a DEF deste card equivalem ao número de fichas no campo x 500.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87979586,'Anjo Trompetista','Esta flor linda e feérica cria uma névoa delirante para manter os intrusos afastados das partes mais profundas da floresta, onde vivem as feras mais sagradas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87985506,'Recreação Arquidemônio',replace(replace('Invoque por Invocação-Especial 1 monstro "Arquidemônio" de Nível 7 ou menos da sua mão ou do Deck, ou se você tiver um Monstro de Ritual "Arquidemônio" no seu Deck Adicional com a face para cima, em vez disso, você pode Invocar por Invocação-Especial até 1 de cada de "Arquidemônio Real", "Duque Arquidemônio" e "Alteza Arquidemônio" da sua mão e/ou do Deck. \r\nVocê só pode ativar 1 "Recreação Arquidemônio" por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial até 3 monstros em vez disso?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87988305,'Espírito Negro da Malícia',replace(replace('Quando seu oponente ativar um card ou efeito (Efeito Rápido): você pode enviar este card da sua mão ou do campo para o Cemitério e, depois, escolha 1 monstro Demônio de Nível 8 no seu Cemitério; Invoque-o por Invocação-Especial, mas seus efeitos são negados. \r\nSe um ou mais monstros Demônio de Nível 8 forem enviados para o seu Cemitério enquanto este card estiver no seu Cemitério (exceto durante a Etapa de Dano): você pode adicionar este card à sua mão. \r\nVocê só pode usar cada efeito de "Espírito Negro da Malícia" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Adicionar este card à sua mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87990236,'Encantamento do Senhor Obscuro',replace(replace('Envie 1 monstro "Senhor(a) Obscuro(a)" da sua mão ou do campo com a face para cima para o Cemitério; até a Fase Final, tome o controle de 1 monstro com a face para cima que seu oponente controla. \r\nVocê só pode ativar 1 "Encantamento do Senhor Obscuro" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87997872,'Theinen, a Grande Esfinge',replace(replace('Este card não pode ser Invocado por Invocação-Normal ou Baixado. \r\nEste card não pode ser Invocado por Invocação-Especial, apenas pagando 500 PV quando ambos "Androesfinge" e "Esfinge Teleia" no seu lado do campo forem destruídos ao mesmo tempo; então você poderá Invocar por Invocação-Especial este monstro da sua mão ou Deck. \r\nQuando este card for Invocado por Invocação-Especial com sucesso, pague 500 PV para aumentar o ATK deste card em 3000 pontos até o fim da Fase Final.','\r',char(13)),'\n',char(10)),'Invocação Especial','Aumentar ATK','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88000953,'Rasterligre',replace(replace('2+ monstros, exceto Fichas	\r\nVocê pode escolher 1 Monstro Link em qualquer Cemitério; este card ganha ATK igual ao ATK desse alvo até o final deste turno. \r\nVocê pode oferecer como Tributo qualquer número de monstros seus para os quais este card apontar; destrua o mesmo número de cards no campo. \r\nVocê só pode usar cada efeito de "Rasterligre" uma vez por turno.','\r',char(13)),'\n',char(10)),'Aumentar ATK','Destruir 1 card','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88001391,'Zoma, o Espírito Terrestre',replace(replace('Invoque este card por Invocação-Especial como um Monstro de Efeito (Zumbi/TREVAS/Nível 4/ATK 1800/DEF 500) com o seguinte efeito (este card ainda é considerado uma Armadilha).\r\n● Todos os monstros que seu oponente controla que podem atacar devem atacar este card.	\r\nSe este card Invocado desta forma for destruído pelo ataque de um monstro do oponente: cause dano ao seu oponente (máx. 3000) igual ao dobro do ATK original do monstro atacante. \r\nVocê só pode usar cada efeito de "Zoma, o Espírito Terrestre" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88021907,'Primechamático Laplaciano',replace(replace('3 monstros de Nível 4	\r\nSe um ou mais cards "Mechamático(a)" que você controla seriam destruídos por um efeito de card, em vez disso, você pode desassociar 1 matéria deste card. \r\nSe este card for Invocado por Invocação-Xyz: você pode desassociar até 3 matérias dele e, depois, selecione esse número de efeitos (você não pode selecionar o mesmo efeito duas vezes e você os resolve na ordem listada, pulando quaisquer que não tenham sido selecionados);\r\n● Envie 1 card aleatório da mão do seu oponente para o Cemitério.\r\n● Envie 1 monstro que seu oponente controla para o Cemitério.\r\n● Envie 1 Magia/Armadilha que seu oponente controla para o Cemitério.	\r\nVocê só pode usar este efeito de "Primechamático Laplaciano" uma vez por turno.','\r',char(13)),'\n',char(10)),'Envie para o Cemitério 1 card aleatório da mão do seu oponente','Enviar para o Cemitério 1 monstro que seu oponente controla','Enviar para o Cemitério 1 Card de Magia/Armadilha que seu oponente controla','','Desassociar Matéria Xyz para ativar um efeito','','','','','','','','','','','');
INSERT INTO texts VALUES(88032368,'Segundo Reforço',replace(replace('Você pode oferecer este card como Tributo para selecionar 1 monstro com a face para cima em Posição de Ataque que você controla. \r\nO monstro selecionado ganha 1500 de ATK até a Fase Final.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88032456,'Sósia',replace(replace('Se você controlar "Mundo Toon" e um monstro Toon: escolha 1 card no Cemitério do seu oponente; se for um monstro, Invoque-o por Invocação-Especial no seu campo, ou se for uma Magia/Armadilha, Baixe-a no seu campo. \r\nVocê só pode ativar 1 "Sósia" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88033975,'Armades, Protetor das Fronteiras',replace(replace('1 Regulador + 1+ não-Reguladores	\r\nSe este card batalhar, seu oponente não pode ativar cards ou efeitos até o final da Etapa de Dano.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88039509,'Einroide',replace(replace('Se este card for destruído em batalha ou por um efeito de card: você pode enviar 2 monstros Máquina de Nível 4 ou menos do seu Deck para o Cemitério. \r\nVocê só pode usar este efeito de "Einroide" uma vez por turno.','\r',char(13)),'\n',char(10)),'Enviar para o Cemitério','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88069166,'Olho de Odin',replace(replace('Uma vez por turno, durante a Fase de Apoio de cada duelista: você pode escolher 1 monstro "Aesir" que você controla; negue seus efeitos até o final deste turno e, se isso acontecer, olhe todos os cards na mão do seu oponente e todos os cards Baixados que ele controla. \r\nSeu oponente não pode ativar cards ou efeitos em resposta à ativação deste efeito.','\r',char(13)),'\n',char(10)),'Revele a mão e os cards com a face para baixo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88069597,'Predapônico',replace(replace('Uma vez por turno: você pode Invocar por Invocação-Especial 1 monstro "Predaplanta" de Nível 4 ou menos da sua mão ou do Cemitério, mas negue seus efeitos (mesmo que este card deixe o campo). \r\nUma vez por turno, durante sua Fase de Apoio, pague 800 PV ou destrua este card.','\r',char(13)),'\n',char(10)),'Invoque por Invocação Especial 1 monstro "Predaplanta"','Pagar 800 PV?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88071625,'Netuno, o Tirano',replace(replace('Não pode ser Invocado por Invocação-Especial. \r\nVocê pode Invocar este card por Invocação-Tributo ao oferecer como Tributo 1 monstro. \r\nEste card ganha a soma do ATK e DEF originais do(s) monstro(s) oferecido(s) como Tributo para sua Invocação-Tributo. \r\nQuando este card for Invocado por Invocação-Tributo: Escolha 1 Monstro de Efeito no Cemitério que foi oferecido como Tributo para a Invocação-Tributo; o nome deste card se torna o nome do alvo, e este card ganha os efeitos do alvo.','\r',char(13)),'\n',char(10)),'Ofereça 1 monstro como Tributo para Invocar','Efeito de copiar','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88078306,'Armadilhatrix Genlisea',replace(replace('Não é afetado pelos efeitos de Armadilhas Normais "Buraco". \r\nVocê pode oferecer este card como Tributo; Baixe 2 Armadilhas Normais "Buraco" com nomes diferentes, 1 do seu Deck e 1 do seu Cemitério, mas bana-as quando elas deixarem o campo. \r\nVocê só pode usar este efeito de "Armadilhatrix Genlisea" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88083109,'Deslocamento Livromante',replace(replace('Escolha 1 monstro "Livromante" que você controla e 1 monstro que seu oponente controla; devolva seu monstro para a mão e, se isso acontecer, tome o controle desse monstro do oponente. \r\nSe seu monstro "Livromante" que você escolheu como alvo não era um Monstro de Ritual, o monstro que você tomou o controle volta para a mão durante a Fase Final. \r\nVocê só pode ativar 1 "Deslocamento Livromante" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88086137,'Cabos Rompidos','Quando um Card de Magia/Armadilha ou efeito de monstro for ativado na coluna deste card, enquanto este card estiver Baixado: negue a ativação e, se isso acontecer, destrua esse card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88089103,'O Cemitério na Quarta Dimensão','Adicione 2 monstros no seu Cemitério que têm "LV" ao seu Deck e embaralhe-o.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88093706,'Atualizar Bloqueador',replace(replace('2 monstros Ciberso de Nível 2 ou mais	\r\nUma vez por batalha, durante o cálculo de dano, se um monstro Ciberso seu batalhar (Efeito Rápido): você pode ativar este efeito; até o final da Etapa de Dano, negue todos os outros efeitos de card no campo, o cálculo de dano desta batalha usa o ATK/DEF originais de cada monstro e, além disso, se um monstro do oponente for destruído por esta batalha e enviado para o Cemitério, cause 1000 de dano ao seu oponente. \r\nSe este card for enviado para o Cemitério como Matéria Link: esse Monstro Link pode realizar um segundo ataque durante cada Fase de Batalha neste turno.','\r',char(13)),'\n',char(10)),'','','O efeito de "Atualizar Bloqueador" está sendo aplicado.','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88095331,'Evoltil Najasho','Se este card no campo for oferecido como Tributo: você pode Invocar por Invocação-Especial 1 monstro "Evolssauro" do seu Deck.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88106656,'Fireburst Livromante',replace(replace('Você pode Invocar este card por Invocação-Ritual com um card "Livromante". \r\nSe este card foi Invocado por Invocação-Ritual usando um ou mais monstros no campo, ele não pode ser destruído em batalha e, além disso, qualquer dano de batalha que ele causar ao seu oponente é dobrado. \r\nEste card pode realizar até 2 ataques contra monstros durante cada Fase de Batalha. \r\nQuando um monstro declarar um ataque: você pode banir 1 Monstro de Ritual "Livromante" do seu Cemitério; este card ganha 200 de ATK.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Ritual usando monstros no campo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88120966,'Número 15: Engenhoca Marionete Amolador Gigante',replace(replace('2 monstros de Nível 8	\r\nAté duas vezes por turno, durante sua Fase Principal 1: você pode desassociar 1 matéria deste card e, depois, escolha 1 monstro Invocado por Invocação-Especial que seu oponente controla; destrua-o e, depois, se ele era um Monstro Xyz, cause dano ao seu oponente igual ao ATK original dele.','\r',char(13)),'\n',char(10)),'Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88123329,'Avatar da Besta Espiritual Rampengu',replace(replace('Uma vez por turno, durante sua Fase Principal: você pode banir 1 monstro "Besta Espiritual" do seu Deck Adicional e enviar 1 monstro "Besta Espiritual" com o mesmo Tipo que o desse monstro do seu Deck para o Cemitério. \r\nVocê só pode Invocar por Invocação-Especial um ou mais "Avatar da Besta Espiritual Rampengu" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88124568,'Agente Duplo ESPIRÃO',replace(replace('Se você tiver um card "ESPIRÃO" no seu campo ou no seu Cemitério: você pode Invocar este card por Invocação-Especial da sua mão no campo do seu oponente em Posição de Defesa (mas ele não pode ser oferecido como Tributo, nem ser usado como matéria para uma Invocação-Fusão, Sincro, Xyz ou Link) e, depois, os dois duelistas revelam o card do topo dos seus Deck. \r\nVocê só pode usar este efeito de "Agente Duplo ESPIRÃO" uma vez por turno. \r\nTodos os monstros "ESPIRÃO" no campo ganham 500 de ATK e, além disso, "Super Agente ESPIRÃO" no campo pode atacar diretamente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88132637,'Lobo de Duas Cabeças','Enquanto você controlar outro monstro Demônio, negue os efeitos de monstros de Virar destruídos em batalha com este card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88139289,'Destruidor Psíquico Mk-II',replace(replace('1 Regulador Psíquico + 1+ monstros Psíquico não-Reguladores	\r\nVocê pode escolher 1 monstro banido; Invoque-o por Invocação-Especial no seu campo. \r\nDurante a Fase Principal (Efeito Rápido): você pode banir 1 monstro do seu Cemitério e, depois, escolha 1 outro monstro com a face para cima no campo; bana-o e, depois, ganhe PV igual ao ATK original desse monstro banido. \r\nVocê só pode usar 1 efeito de "Destruidor Psíquico Mk-II" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Banir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88170262,'Kewl Tune Remix',replace(replace('"Kewl Tune Mix" + 1+ Reguladores	\r\nGanha 1500 de ATK enquanto seu oponente tiver um Regulador no campo ou Cemitério dele. \r\nDurante o turno do seu oponente (Efeito Rápido): você pode oferecer este card como Tributo; selecione 2 Reguladores que não sejam Sincro no seu Cemitério, adicione 1 deles à sua mão e, se isso acontecer, Invoque o outro por Invocação-Especial e, depois, imediatamente depois que este efeito resolver, você pode Invocar 1 Monstro Sincro Regulador por Invocação-Sincro. \r\nVocê só pode usar este efeito de "Kewl Tune Remix" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Invocação Sincro?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88176533,'Devota de Nephthys',replace(replace('Você pode Invocar este card por Invocação-Ritual com "Renascimento de Nephthys". \r\nVocê só pode usar cada um dos seguintes efeitos de "Devota de Nephthys" uma vez por turno.\r\n● Se este card for Invocado por Invocação-Ritual: você pode ativar este efeito; Invoque por Invocação-Especial 1 monstro "Nephthys" do seu Deck e, além disso, durante a Fase Final deste turno, destrua este card.\r\n● Se este card estiver no Cemitério: você pode destruir 1 card "Nephthys" na sua mão e, se isso acontecer, Invoque este card por Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88177324,'Número 107: Dragão de Táquion de Olhos das Galáxias',replace(replace('2 monstros de Nível 8	\r\nUma vez por Fase de Batalha, no começo da sua Fase de Batalha: você pode desassociar 1 matéria deste card; negue os efeitos de todos os outros monstros com a face para cima atualmente no campo e, além disso, seu ATK/DEF se tornam seu ATK/DEF originais. \r\nDurante a Fase de Batalha, se você ativou este efeito neste turno, sempre que um efeito de card do oponente resolver, este card ganha 1000 de ATK até o final da Fase de Batalha e, além disso, ele pode realizar um segundo ataque durante cada Fase de Batalha neste turno.','\r',char(13)),'\n',char(10)),'Negar efeitos','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88177325,'Número 107: Dragão de Táquion de Olhos das Galáxias',replace(replace('2 monstros de Nível 8	\r\nUma vez por Fase de Batalha, no começo da sua Fase de Batalha: você pode desassociar 1 matéria deste card; negue os efeitos de todos os outros monstros com a face para cima atualmente no campo e, além disso, seu ATK/DEF se tornam seu ATK/DEF originais. \r\nDurante a Fase de Batalha, se você ativou este efeito neste turno, sempre que um efeito de card do oponente resolver, este card ganha 1000 de ATK até o final da Fase de Batalha e, além disso, ele pode realizar um segundo ataque durante cada Fase de Batalha neste turno.','\r',char(13)),'\n',char(10)),'Negar efeitos','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88190453,'Debulhador de Correntes','Este card pode realizar 1 ataque adicional durante a mesma Fase de Batalha para cada "Debulhador de Correntes" no seu Cemitério.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88190790,'Armadura de Assalto',replace(replace('Só pode ser equipado a um monstro do Tipo Guerreiro se for o único monstro que você controla. \r\nEle ganha 300 de ATK. \r\nDurante sua Fase Principal 1, você pode enviar este card equipado para o Cemitério para permitir que o monstro equipado ataque duas vezes durante cada Fase de Batalha neste turno.','\r',char(13)),'\n',char(10)),'Ataques múltiplos','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88197162,'Transição de Alma',replace(replace('Se você não controlar monstros Invocados por Invocação-Especial: ofereça como Tributo 1 monstro de Nível 4 com a face para cima Invocado por Invocação-Normal/Baixado; compre 2 cards. \r\nVocê só pode ativar 1 "Transição de Alma" por turno. \r\nVocê não pode Invocar monstros por Invocação-Especial no turno em que ativar este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88204302,'Recuperação Veloz',replace(replace('Escolha 1 monstro "Velocidaroide" no seu Cemitério; Invoque-o por Invocação-Especial. \r\nDurante sua Fase Principal, exceto no turno em que este card foi enviado para o Cemitério: você pode banir este card do seu Cemitério e, depois, escolha 1 monstro "Velocidaroide" no seu Cemitério; adicione-o à sua mão.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88205593,'Wattcobra',replace(replace('Este card pode atacar diretamente. \r\nSe este card causar dano de batalha ao seu oponente em um ataque direto: adicione 1 monstro "Watt" do seu Deck à sua mão.','\r',char(13)),'\n',char(10)),'Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88210105,'Nuviano Aerossol',replace(replace('Descarte 1 monstro "Nuviano" e, depois, escolha 1 monstro com a face para cima no campo; coloque Marcadores de Neblina no alvo igual ao seu próprio Nível. \r\nVocê pode banir este card e 1 monstro "Nuviano" do seu Cemitério; Invoque por Invocação-Especial 1 monstro "Nuviano" do seu Deck. \r\nVocê só pode usar 1 efeito de "Nuviano Aerossol" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88225269,'Cavaleiro-Gema Núcleo Oco',replace(replace('Você pode enviar 1 Monstro Normal "Cavaleiro-Gema" ou 1 "Fusão Cavaleiro-Gema" do seu Deck para o Cemitério; Invoque este card por Invocação-Especial da sua mão em Posição de Defesa. \r\nQuando seu oponente ativar um card ou efeito, enquanto você controlar um Monstro de Fusão "Cavaleiro-Gema" (Efeito Rápido): você pode banir 3 cards "Cavaleiro-Gema" do seu Cemitério, incluindo este card; negue o efeito e, depois, todos os monstros "Cavaleiro-Gema" que você controla atualmente ganham 1000 de ATK. \r\nVocê só pode usar cada efeito de "Cavaleiro-Gema Núcleo Oco" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Negar o efeito','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88232397,'Mago Marrom Habilidoso',replace(replace('Sempre que um Card de Magia for ativado, coloque 1 Marcador de Magia neste card quando essa Magia resolver (máx. 3). \r\nVocê pode remover 1 Marcador de Magia deste card e, depois, ative 1 desses efeitos;\r\n● Este card ganha 1500 de ATK e seu Nível aumenta em 1.\r\n● Adicione 1 monstro "Kuriboh" ou 1 "Multiplicação" do seu Deck ou Cemitério à sua mão.	\r\nVocê só pode usar este efeito de "Mago Marrom Habilidoso" uma vez por turno.','\r',char(13)),'\n',char(10)),'Aumentar o Nível e o ATK','Adicione à sua mão 1 monstro "Kuriboh" ou "Multiplicação"','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88234365,'Senhor Obscuro Tezcatlipoca',replace(replace('Se um ou mais monstros "Senhor(a) Obscuro(a)" que você controla seriam destruídos em batalha ou por um efeito de card, em vez disso, você pode descartar este card. \r\nDurante o turno de qualquer duelista: você pode pagar 1000 PV e, depois, escolher 1 Card de Magia/Armadilha "Senhor(a) Obscuro(a)" no seu Cemitério; aplique o efeito do alvo e, depois, embaralhe o alvo no Deck. \r\nVocê só pode usar este efeito de "Senhor Obscuro Tezcatlipoca" uma vez por turno. \r\nVocê só pode Invocar um ou mais "Senhor Obscuro Tezcatlipoca" por Invocação-Especial uma vez por turno.','\r',char(13)),'\n',char(10)),'Usar o efeito de "Senhor Obscuro Tezcatlipoca" em vez de ser destruído?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88234821,'Cavaleiro Dragunidade - Areadbhair',replace(replace('1 Regulador "Dragunidade" + 1+ monstros não-Reguladores	\r\nQuando seu oponente ativar um efeito de monstro (Efeito Rápido): você pode banir 1 monstro "Dragunidade" do seu Cemitério; negue a ativação e, se isso acontecer, bana esse card. \r\nSe este card destruir um monstro do oponente em batalha, depois do cálculo de dano: você pode banir esse monstro do oponente. \r\nSe este card Invocado por Invocação-Sincro sob o controle do seu dono for destruído por um card do oponente: você pode destruir todas as Magias e Armadilhas que seu oponente controla. \r\nVocê só pode usar cada efeito de "Cavaleiro Dragunidade - Areadbhair" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88236094,'Aparição de Aswan','Quando este card inflige dano de batalha aos Life Points do seu adversário, você pode devolver 1 Card de Armadilha do seu Cemitério para o topo do seu Deck.','Retornar ao Deck','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88240808,'Kycoo, o Destruidor de Fantasmas',replace(replace('Quando este card causar dano de batalha ao seu oponente: você pode escolher até 2 monstros no Cemitério dele; bana os alvos. \r\nSeu oponente não pode banir cards de qualquer Cemitério.','\r',char(13)),'\n',char(10)),'Banir 2 monstros do Cemitério do seu oponente','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88240999,'Necroz da Armadura Decisiva',replace(replace('Você pode Invocar este card por Invocação-Ritual com qualquer Magia de Ritual "Necroz". \r\nDeve ser Invocado por Invocação-Ritual, usando monstros, e você não pode usar monstros de Nível 10. \r\nVocê só pode usar cada um desses efeitos de "Necroz da Armadura Decisiva" uma vez por turno.\r\n● (Efeito Rápido): você pode descartar este card e, depois, escolha 1 monstro "Necroz" que você controla; ele ganha 1000 de ATK/DEF até o final deste turno.\r\n● Você pode escolher 1 card Baixado que seu oponente controla; destrua-o e, se isso acontecer, bana-o.','\r',char(13)),'\n',char(10)),'Aumentar ATK/DEF','Destruir e banir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88241506,'Donzela com Azul nos Olhos',replace(replace('Quando um card ou efeito for ativado que escolha este card como alvo (Efeito Rápido): você pode Invocar por Invocação-Especial 1 "Dragão Branco de Olhos Azuis" da sua mão, do Deck ou do Cemitério. \r\nQuando este card for escolhido como alvo de um ataque: você pode negar o ataque e, se isso acontecer, mude a posição de batalha deste card e, depois, você pode Invocar por Invocação-Especial 1 "Dragão Branco de Olhos Azuis" da sua mão, do Deck ou do Cemitério. \r\nVocê só pode usar 1 efeito de "Donzela com Azul nos Olhos" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Negar o ataque','Invocação Especial','Invocar "Dragão Branco de Olhos Azuis" por Invocação Especial?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88264978,'Dragão Metálico das Trevas de Olhos Vermelhos',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) ao banir 1 monstro Dragão com a face para cima que você controla. \r\nVocê só pode Invocar por Invocação-Especial "Dragão Metálico das Trevas de Olhos Vermelhos" uma vez por turno desta forma. \r\nDurante sua Fase Principal: você pode Invocar por Invocação-Especial 1 monstro Dragão da sua mão ou do Cemitério, exceto "Dragão Metálico das Trevas de Olhos Vermelhos". \r\nVocê só pode usar este efeito de "Dragão Metálico das Trevas de Olhos Vermelhos" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88264979,'Dragão Metálico das Trevas de Olhos Vermelhos',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) ao banir 1 monstro Dragão com a face para cima que você controla. \r\nVocê só pode Invocar por Invocação-Especial "Dragão Metálico das Trevas de Olhos Vermelhos" uma vez por turno desta forma. \r\nDurante sua Fase Principal: você pode Invocar por Invocação-Especial 1 monstro Dragão da sua mão ou do Cemitério, exceto "Dragão Metálico das Trevas de Olhos Vermelhos". \r\nVocê só pode usar este efeito de "Dragão Metálico das Trevas de Olhos Vermelhos" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88279736,'Goblin Larápio','Cada vez que 1 monstro no seu Campo infligir dano de batalha aos Life Points do seu adversário, o seu adversário descarta 1 card da sua mão aleatoriamente.','Seu oponente descarta 1 card aleatório','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88283496,'Gamr das Bestas Nórdicas','Se este card batalhar um monstro de Nível 4 ou menos, depois do cálculo de dano: você pode devolver esse monstro para a mão.','Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88284599,'Sauravis, o Sábio Dragão da Voz Sem Voz',replace(replace('Você pode Invocar este card por Invocação-Especial (da sua mão) ao embaralhar no Deck 2 Magias da sua mão e/ou do Cemitério, incluindo uma Magia de Ritual. \r\nVocê só pode Invocar "Sauravis, o Sábio Dragão da Voz Sem Voz" por Invocação-Especial uma vez por turno desta forma. \r\nQuando seu oponente ativar um card ou efeito (Efeito Rápido): você pode devolver este card do campo para a mão; Invoque por Invocação-Especial 1 Monstro de Ritual (Guerreiro ou Dragão) de LUZ da sua mão ou do Deck, mas embaralhe-o no Deck durante a Fase Final do próximo turno. \r\nVocê só pode usar este efeito de "Sauravis, o Sábio Dragão da Voz Sem Voz" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invoque por Invocação Especial um Monstro Ritual','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88289295,'Controle de Sincro',replace(replace('Só pode ser ativado se você não tiver nenhum Monstro Sincro no seu lado do campo ou no seu Cemitério. \r\nPague 1000 PV e selecione 1 Monstro Sincro com a face para cima que seu oponente controla. \r\nTome o controle do monstro selecionado até a Fase Final do seu turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88301393,'Infernoide Attondel',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão ou do Cemitério) ao banir 2 monstros "Infernoide" da sua mão ou do Cemitério enquanto a soma dos Níveis e Classes de todos os Monstros de Efeito que você controla for 8 ou menos. \r\nQuando este card destruir um monstro do oponente em batalha e enviá-lo para o Cemitério: você pode ativar este efeito; este card pode realizar um segundo ataque em seguida. \r\nUma vez por turno (Efeito Rápido): você pode oferecer 1 monstro como Tributo e, depois, escolha 1 card no Cemitério do seu oponente; bana-o.','\r',char(13)),'\n',char(10)),'Continuar atacando','Banir cards do Cemitério do seu oponente','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88301833,'Alma Ascendente','Uma vez por turno, quando um ou mais Monstros de Ritual forem Invocados por Invocação-Ritual: você pode escolher 1 monstro no seu Cemitério que foi oferecido como Tributo para a Invocação-Ritual; adicione o alvo à sua mão.','Retornar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88305705,'Dragão Pêndulo de Olhos Valentes',replace(replace('1 monstro "Dragão Pêndulo" + 1 monstro do Tipo Guerreiro	\r\nQuando este card for Invocado por Invocação-Fusão: você pode mudar o ATK de todos os monstros com a face para cima que seu oponente controla atualmente para 0 e, atém disso, pelo resto deste turno, outros monstros que você controla não podem atacar. \r\nNegue os efeitos ativados de monstros com ATK 0. \r\nNo final da Etapa de Dano, quando este card atacar um monstro do oponente, mas o monstro do oponente não foi destruído em batalha: você pode banir o monstro do oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88305978,'Asanegra - Calima, a Neblina','Durante a Fase de Batalha do seu oponente, se você não controlar nenhum monstro: você pode banir este card do Cemitério e, depois, escolher 1 Monstro Sincro no seu Cemitério; Invoque o alvo por Invocação-Especial, mas bana-o no final da Fase de Batalha (este é um Efeito Rápido).','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88307361,'Celacanto, o Superancião Rei das Profundezas do Mar',replace(replace('Uma vez por turno: você pode descartar 1 card; Invoque por Invocação-Especial tantos monstros Peixe de Nível 4 ou menos quanto possível do seu Deck, mas eles não podem declarar um ataque e seus efeitos são negados. \r\nQuando um card ou efeito for ativado que escolha como alvo este card no campo (Efeito Rápido): você pode oferecer como Tributo 1 outro monstro Peixe; negue esse efeito e, se isso acontecer, destrua esse card.','\r',char(13)),'\n',char(10)),'Invocação Especial','Negar seus efeitos e destruí-lo','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88316955,'Espinha Krawler',replace(replace('VIRE: Você pode escolher 1 monstro no campo; destrua esse monstro.\r\nSe este card com a face para cima sob o controle do seu dono deixar o campo devido a um efeito de card do oponente: você pode Invocar por Invocação-Especial 2 monstros "Krawler" com nomes diferentes do seu Deck em Posição de Defesa com a face para baixo, exceto "Espinha Krawler". \r\nVocê só pode usar cada efeito de "Espinha Krawler" uma vez por turno.','\r',char(13)),'\n',char(10)),'Destruir um monstro','Invoque 2 monstros por Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88332693,'Modo de Ataque Zero',replace(replace('Ofereça como Tributo 1 Monstro Sincro; Invoque por Invocação-Especial 1 monstro "/Modo de Ataque" da sua mão cujo nome inclua o nome do monstro oferecido como Tributo. \r\n(Essa é considerada uma Invocação-Especial com "Ativar Modo de Ataque".) \r\nDurante sua Fase Principal: você pode banir este card do seu Cemitério; Baixe 1 "Ativar Modo de Ataque" diretamente da sua mão ou do Deck. \r\nEle pode ser ativada neste turno. \r\nVocê só pode usar cada efeito de "Modo de Ataque Zero" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Ativar aplicando o efeito de "Modo de Ataque Zero".','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88341502,'Flecha de Ébano',replace(replace('Escolha 1 monstro com a face para cima que você controla. \r\nAté a Fase Final, ele perde 500 de ATK e durante a batalha entre esse monstro atacante e um monstro em Posição de Defesa cuja DEF for menor do que o ATK do monstro escolhido, cause a diferença como Dano de Batalha ao seu oponente. \r\nQuando o monstro escolhido destruir um monstro em batalha e enviá-lo para o Cemitério neste turno, cause dano ao seu oponente igual a DEF original do monstro destruído.','\r',char(13)),'\n',char(10)),'Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88346805,'Você Está Acabado',replace(replace('Se 10 ou mais cards e/ou efeitos foram ativados durante este turno: Invoque este card por Invocação-Especial como um Monstro de Efeito (Ciberso/TREVAS/Nível 10/ATK 3000/DEF 3000) (este card ainda é considerado uma Armadilha), mas Baixe-o na sua Zona de Magias & Armadilhas durante sua Fase Final. \r\nUma vez por turno, quando seu oponente ativar um card ou efeito, enquanto este card estiver na sua Zona de Monstros (Efeito Rápido): você pode destruir tantos cards que seu oponente controla quanto possível e, depois, Baixe este card na sua Zona de Magias & Armadilhas.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88358139,'Camarartista Cooprincesa','Quando você Invocar por Invocação-Normal ou Especial um ou mais monstros "Camarartista", exceto "Camarartista Cooprincesa" (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88361177,'Angusticlavii Dragunidade','Se este card atacar um monstro em Posição de Defesa enquanto estiver equipado com um monstro Dragão "Dragunidade", cause dano de batalha perfurante.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88369727,'Retorno Tolo','Escolha 1 card no Cemitério do seu oponente; embaralhe-o no Deck.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88392300,'Marionetista Wattcinético','(Efeito Rápido): você pode enviar este card da sua mão ou do campo para o Cemitério e, depois, escolher 1 monstro que seu oponente controla; mova o alvo para outra Zona de Monstros Principal dele.','Escolha 1 monstro para mover','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88406570,'Gouki, Ogro Destruidor',replace(replace('2+ monstros "Gouki"	\r\nNa primeira vez que cada monstro para o qual este card apontar seria destruído em batalha a cada turno, ele não é destruído. \r\nDurante sua Fase Principal: você pode ativar este efeito; você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros "Gouki" e, além disso, seu oponente Invoca 1 ou 2 monstros por Invocação-Especial do Cemitério dele e, depois, você Invoca por Invocação-Especial até esse número de monstros "Gouki" que não sejam Link do seu Cemitério em uma ou mais Zonas para as quais este card apontar. \r\nVocê só pode usar este efeito de "Gouki, Ogro Destruidor" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88409165,'Guerreiro Abissal','Uma vez por turno: Você pode descartar 1 monstro de ÁGUA para o Cemitério e, depois, escolha 1 monstro no Cemitério de qualquer duelista; devolva o alvo para o topo ou fundo do Deck.','Retornar ao Deck','Colocar no topo do Deck','Retornar ao fundo do Deck','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88412339,'Ator do Abismo - Figurantes',replace(replace('Escala de Pêndulo = 3\r\n[ Efeito de Pêndulo ]\r\nSe seu oponente controlar um monstro: você pode Invocar este card por Invocação-Especial da sua Zona de Pêndulo. \r\nVocê só pode usar este efeito de "Ator do Abismo - Figurantes" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nVocê pode oferecer este card como Tributo; coloque 1 Monstro Pêndulo "Ator do Abismo" do seu Deck na sua Zona de Pêndulo e, além disso, pelo resto deste turno, você não pode Invocar monstros por Invocação-Especial, exceto monstros "Ator do Abismo", nem ativar o Efeito Pêndulo de "Ator do Abismo - Figurantes". \r\nVocê só pode usar este efeito de "Ator do Abismo - Figurantes" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88413677,'Doyon @Ignister',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 monstro "@Ignister" no seu Cemitério; adicione-o à sua mão. \r\nSe este card for enviado para o Cemitério como matéria para a Invocação-Link de um monstro Ciberso: você pode escolher 1 Magia/Armadilha "I.A." no seu Cemitério; adicione-a à sua mão. \r\nVocê só pode usar cada efeito de "Doyon @Ignister" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88435542,'Olho de Fogo','Um olho mergulhado em chamas que bate as suas asas para criar rajadas de ar quente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88438982,'Lombriga Dimikles','VIRE: Este card ganha 300 de ATK e DEF.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88453933,'Dragãozela Servente',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode enviar 1 card "Dragãozela" do seu Deck para o Cemitério, exceto "Dragãozela Servente". \r\nNo começo da Fase de Batalha: você pode devolver este card para a mão e, se isso acontecer, Invoque por Invocação-Especial 1 monstro "Dragãozela" de Nível 8 da sua mão ou do Cemitério. \r\nVocê só pode usar cada efeito de "Dragãozela Servente" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88472456,'Zombyra, o Negro',replace(replace('Não pode atacar diretamente. \r\nSe este card destruir um monstro em batalha: este card perde 200 de ATK.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88477149,'Pilares Gêmeos de Gelo',replace(replace('Invoque por Invocação-Especial 2 "Ficha de Pilar de Gelo" (Aqua/ÁGUA/Nível 4/ATK 1900/DEF 1200) em Posição de Defesa e, além disso, você não pode Invocar por Invocação-Especial do Deck Adicional pelo resto deste turno depois que este card resolver. \r\nDurante sua Fase Principal: você pode banir este card do seu Cemitério; imediatamente depois que este efeito resolver, Invoque por Invocação-Normal 1 monstro de ÁGUA. \r\nVocê só pode usar cada efeito de "Pilares Gêmeos de Gelo" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar uma Ficha por Invocação Especial','Invocação Normal','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88477150,'Ficha de Pilar de Gelo','Invocado por Especial com o efeito "Pilares Gêmeos de Gelo".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88482761,'Batalha de Lance de Dados',replace(replace('Quando um monstro do oponente declarar um ataque: escolha 1 monstro "Velocidaroide" no seu Cemitério; bana tanto ele quanto 1 monstro Regulador "Velocidaroide" da sua mão e, se isso acontecer, Invoque por Invocação-Especial do seu Deck Adicional, 1 Monstro Sincro cujo Nível seja igual à soma dos Níveis originais desses 2 monstros. \r\nDurante a Etapa de Batalha do seu oponente: você pode banir este card do seu Cemitério e, depois, escolher 1 Monstro Sincro com a face para cima em Posição de Ataque em cada lado do campo; faça com que esse monstro com a face para cima em Posição de Ataque que seu oponente controla ataque esse monstro que você controla e realize o cálculo de dano.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88494120,'Espírito Indomável','Se você controlar apenas 1 monstro com a face para cima: escolha esse monstro; até o final deste turno, ele ganha ATK igual ao ATK do monstro de menor ATK que seu oponente controla atualmente (em caso de empate, você seleciona).','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88494899,'Médium da Barreira de Gelo',replace(replace('Se seu oponente controlar 4 ou mais cards que você, você pode Invocar este card por Invocação-Especial (da sua mão). \r\nSeu oponente só pode ativar 1 Card de Magia/Armadilha a cada turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88504133,'Magia de Aumento de Classe Força Cavaleiros Fantasmas',replace(replace('Durante a Fase Principal: bana 1 ou mais monstros de TREVAS do seu Cemitério e, depois, escolha 1 Monstro Xyz de TREVAS que você controla; Invoque por Invocação-Especial do seu Deck Adicional, 1 Monstro Xyz "Os Cavaleiros Fantasmas", "Ataqueraptor" ou "Dragão Xyz", cuja Classe seja igual à do monstro alvo que você controla + o número de monstros banidos, usando-o como matéria e, além disso, pelo resto deste turno depois que este card resolver, você não pode Invocar monstros do Deck Adicional por Invocação-Especial, exceto Monstros Xyz. \r\n(Isso é considerado uma Invocação-Xyz. Transfira as matérias dele para o monstro Invocado.) \r\nVocê só pode ativar 1 "Magia de Aumento de Classe Força Cavaleiros Fantasmas" por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Escolha a quantidade de monstros a banir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88513608,'Card do Sacrifício',replace(replace('Compre 2 cards se o ATK combinado de todos os seus monstros com a face para cima em Posição de Ataque (mínimo 2) for menor do que o ATK do monstro com a face para cima do seu oponente com o menor ATK. \r\nVocê não pode Invocar ou mudar a posição de batalha no turno em que você ativar este card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88540324,'Garra Salamagrande',replace(replace('Só pode ser equipado a um monstro "Salamagrande". \r\nO monstro equipado não pode ser destruído em batalha ou por efeitos de card e, se ele atacar um monstro em Posição de Defesa, cause dano de batalha perfurante ao seu oponente. \r\nSe o monstro equipado for um Monstro Link "Salamagrande" que você controla que foi Invocado por Invocação-Link usando um monstro com o mesmo nome como matéria, durante cada Fase de Batalha ele pode realizar ataques contra monstros até seu Valor Link. \r\nVocê só pode controlar 1 "Garra Salamagrande".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88544390,'Os Cavaleiros Fantasmas das Grevas Manchadas',replace(replace('Se um ou mais monstros "Os Cavaleiros Fantasmas" forem Invocados por Invocação-Especial no seu campo (exceto durante a Etapa de Dano): você pode Invocar este card por Invocação-Especial da sua mão e, depois, você pode aumentar em 1 o Nível deste card. \r\nVocê pode banir este card do seu Cemitério; Invoque por Invocação-Especial 1 monstro "Os Cavaleiros Fantasmas" da sua mão, exceto "Os Cavaleiros Fantasmas das Grevas Manchadas" e, depois, você pode aumentar seu Nível em 1. \r\nVocê só pode usar cada efeito de "Os Cavaleiros Fantasmas das Grevas Manchadas" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Aumentar o Nível deste monstro?','Aumentar o Nível?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88552992,'Cronomalia Jato Dourado','Uma vez por turno: você pode aumentar em 1 os Níveis de todos os monstros "Cronomalia" que você controla atualmente.','Aumentar o Nível','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88554436,'Alma Desacorrentada de Shyama',replace(replace('Você pode escolher 1 card que você controla; destrua-o e, depois, você pode destruir 1 Magia/Armadilha no campo. \r\nSe este card estiver no seu Cemitério: você pode escolher 1 monstro Demônio ou 1 card com a face para baixo que você controla; destrua-o e, se isso acontecer, Invoque este card por Invocação-Especial, mas coloque-o no fundo do Deck quando ele deixar o campo. \r\nVocê só pode usar cada efeito de "Alma Desacorrentada de Shyama" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Destruir 1 Card de Magia/Armadilha no campo?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88559132,'Guerreiro Torre','Você pode Invocar este card por Invocação-Especial (da sua mão) ao oferecer como Tributo 1 monstro do Tipo Guerreiro e, se isso acontecer, ele ganha ATK igual ao ATK original do monstro oferecido como Tributo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88570003,'Mago Negro, o Servo do Faraó',replace(replace('O nome deste card se torna "Mago Negro" enquanto estiver no campo ou no Cemitério.\r\nVocê só pode usar 1 dos seguintes efeitos de "Mago Negro, o Servo do Faraó" e somente uma vez por turno.\r\nVocê pode revelar 1 Magia na sua mão; Invoque este card por Invocação-Especial da sua mão, então você pode Baixar 1 Magia/Armadilha que menciona "Mago Negro" do seu Deck. \r\n(Efeito Rápido): você pode descartar 1 Magia; destrua todas as Magias e Armadilhas que seu oponente controla.','\r',char(13)),'\n',char(10)),'Invocação Especial','Destruir','Baixar?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88570004,'Mago Negro, o Servo do Faraó',replace(replace('O nome deste card se torna "Mago Negro" enquanto estiver no campo ou no Cemitério.\r\nVocê só pode usar 1 dos seguintes efeitos de "Mago Negro, o Servo do Faraó" e somente uma vez por turno.\r\nVocê pode revelar 1 Magia na sua mão; Invoque este card por Invocação-Especial da sua mão, então você pode Baixar 1 Magia/Armadilha que menciona "Mago Negro" do seu Deck. \r\n(Efeito Rápido): você pode descartar 1 Magia; destrua todas as Magias e Armadilhas que seu oponente controla.','\r',char(13)),'\n',char(10)),'Invocação Especial','Destruir','Baixar?','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88581108,'Verdadeiro Rei de Todas as Calamidades',replace(replace('2+ monstros de Nível 9	\r\nUma vez por turno (Efeito Rápido): você pode desassociar 1 matéria deste card e declarar 1 Atributo; neste turno, todos os monstros com a face para cima no campo se tornam desse Atributo e, além disso, todos os monstros em posse do seu oponente com esse Atributo não podem ativar seus efeitos ou atacar. \r\nOs monstros que seus monstros "Verdadeiro(a) Draco" e "Verdadeiro Rei" na sua mão destruiriam com seus efeitos podem ser selecionados do campo do seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88610708,'Escudo de Golpear',replace(replace('Só pode ser equipado a um monstro Invocado por Invocação-Normal/Baixado. \r\nEle ganha 1000 de ATK. \r\nVocê não sofre dano de batalha dos ataques que o envolvam.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88616795,'Livro de Magia da Sabedoria',replace(replace('Escolha 1 monstro Mago no campo e, depois, ative 1 desses efeitos;\r\n● Esse monstro com a face para cima não é afetado por outros efeitos de Magia neste turno.\r\n● Esse monstro com a face para cima não é afetado por efeitos de Armadilha neste turno.','\r',char(13)),'\n',char(10)),'Não é afetado por efeitos de Magias, exceto os deste card','Não é afetado por efeitos de Armadilhas','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88617904,'Promoção',replace(replace('Escolha 1 monstro Guerreiro de TERRA de Nível 3 ou menos que você controla; envie-o para o Cemitério e, se isso acontecer, Invoque por Invocação-Especial 1 monstro Guerreiro de TERRA de Nível 4 ou mais do seu Deck e, depois, se você controlar um monstro "Marionete" que originalmente era um Guerreiro de TERRA, esse monstro Invocado por Invocação-Especial ganha ATK/DEF igual ao número de cards atualmente no Cemitério do seu oponente x 100. \r\nVocê só pode ativar 1 "Promoção" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88619463,'Feiticeiro de Magia das Trevas',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao oferecer como Tributo 2 monstros do Tipo Mago de Nível 6 ou mais, e não pode ser Invocado por Invocação-Especial de nenhuma outra forma. \r\nDurante o turno de qualquer duelista, quando um Card de Armadilha for ativado: Você pode negar a ativação e, se isso acontecer, destrua-o. \r\nEste card deve estar com a face para cima no campo para ativar e resolver este efeito.','\r',char(13)),'\n',char(10)),'Negue a ativação de uma Armadilha e a destrua','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88643173,'Escorpião do Pesadelo','Uma criatura que gera pesadelos para assombrar um oponente. Ataca com quatro caudas venenosas.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88643579,'Dragão Final de Trevas',replace(replace('1 Regulador + 1+ monstros não-Reguladores de TREVAS	\r\nUma vez por turno: você pode escolher 1 monstro que seu oponente controla; este card perde exatamente 500 de ATK/DEF e, se isso acontecer, envie o alvo para o Cemitério.','\r',char(13)),'\n',char(10)),'Envie para o Cemitério 1 monstro que seu oponente controla.','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88650530,'Lombriga Apocalipse','VIRE: Escolha 1 Card de Magia/Armadilha no campo; destrua o alvo.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88654892,'Mutamorfose',replace(replace('Ofereça como Tributo 1 Monstro de Fusão ou Sincro; Invoque por Invocação-Especial 1 monstro do seu Deck com o mesmo Nível que o Nível original do monstro oferecido como Tributo, mas devolva-o para a mão durante a Fase Final. \r\nVocê só pode ativar 1 "Mutamorfose" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88667504,'Assalto Esmagador',replace(replace('Se um ou mais monstros Máquina de TERRA com a face para cima que você controla forem destruídos em batalha ou por um efeito de card: você pode escolher 1 card no campo; destrua-o. \r\nVocê pode banir este card do seu Cemitério; Baixe 1 "Extensão de Suporte" ou "Inversão do Sentido" do seu Deck ou Cemitério. \r\nVocê só pode usar cada efeito de "Assalto Esmagador" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88671720,'Bomba Negra','Quando este card for Invocado por Invocação-Normal: você pode escolher 1 monstro de TREVAS do Tipo Máquina de Nível 4 no seu Cemitério; Invoque o alvo por Invocação-Especial em Posição de Defesa, mas seus efeitos são negados.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88685329,'Pesadelo de Olho Negro',replace(replace('Uma vez por turno, se este card seria destruído em batalha, em vez disso, você pode banir 1 Armadilha do seu Cemitério. \r\nVocê pode banir até 3 Armadilhas do seu Cemitério; aplique este efeito, de acordo com o número banido.\r\n● 1: Compre 1 card e, depois, coloque 1 card da sua mão no topo do Deck.\r\n● 2: Compre 1 card.\r\n● 3: Compre 2 cards e, depois, descarte 1 card.	\r\nVocê só pode usar este efeito de "Pesadelo de Olho Negro" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88686573,'Lophii Ágil','Se este card for enviado da mão ou do Deck para o Cemitério: você pode Invocar por Invocação-Especial até 2 monstros "Ágil" de Nível 3 ou menos do seu Deck, exceto "Lophii Ágil".','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88693151,'Fusão Trapestrela',replace(replace('Invoque por Invocação-Fusão 1 Monstro de Fusão "Trapestrela" do seu Deck Adicional, usando monstros da sua mão ou do campo como Matéria de Fusão. \r\nVocê pode banir este card do seu Cemitério e, depois, escolher 1 monstro "Trapestrela" no seu Cemitério; adicione-o à sua mão, mas pelo resto deste turno, você não pode Invocar por Invocação-Normal/Baixar ou por Invocação-Especial monstros com esse nome.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88695895,'Culpa dos Despojos do Pecado',replace(replace('Se seu oponente Invocar um ou mais monstros por Invocação-Especial do Deck ou Deck Adicional e você controlar um Card de Monstro "Diabellstar" (exceto durante a Etapa de Dano): escolha 1 monstro que seu oponente controla; embaralhe-o no Deck. \r\nDurante a Etapa de Dano, quando um monstro "Diabellstar" seu batalhar um monstro do oponente: você pode banir este card do seu Cemitério; o ATK desse monstro do oponente é diminuído pela metade até o final deste turno. \r\nVocê só pode usar cada efeito de "Culpa dos Despojos do Pecado" uma vez por turno.','\r',char(13)),'\n',char(10)),'Retornar ao Deck','O ATK se torna metade','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88696724,'A Terra- Fusão Selada por Feitiço',replace(replace('Você pode substituir este card por qualquer 1 Monstro-Matéria para a Fusão. \r\nQuando faz isto, o(s) outro(s) \r\nMonstro-Matéria para a Fusão têm de ser o(s) correto(s). \r\nOfereça como Tributo Monstros-Matéria para a Fusão incluíndo este card no Campo para Invocar, por Invocação-Especial, 1 Monstro de Fusão da TERRA do seu Deck de Fusão.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88722973,'Paladino Majestro, o Dracossassino Ascendente',replace(replace('2 Monstros Pêndulo de Nível 4	\r\nQuando este card for Invocado por Invocação-Xyz: você pode adicionar 1 Monstro Pêndulo do seu Deck à sua mão durante a Fase Final deste turno. \r\nUma vez por turno: você pode desassociar 1 matéria deste card; Invoque por Invocação-Especial 1 Monstro Pêndulo "Dracossassino" com a face para cima do seu Deck Adicional, mas ele não pode ser usado como matéria para uma Invocação-Xyz.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88724332,'Dragolich da Noite',replace(replace('Coloque em Posição de Defesa todos os monstros que não forem do Tipo Wyrm que estiverem em Posição de Ataque e que foram Invocados por Invocação-Especial do Deck Principal ou Deck Adicional. \r\nTodos os monstros do Tipo Wyrm que foram Invocados por Invocação-Especial do Deck Principal ou Deck Adicional perdem DEF igual à sua DEF original.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88728507,'Feiticeiro Vampiro',replace(replace('Se este card em sua posse for enviado para o seu Cemitério por um card do seu oponente: você pode adicionar 1 monstro "Vampiro(a)" de TREVAS ou 1 Magia/Armadilha "Vampiro(a)" do seu Deck à sua mão. \r\nVocê pode banir este card do seu Cemitério; 1 monstro "Vampiro(a)" de TREVAS que você Invocar por Invocação-Normal neste turno pode ser Invocado sem oferecer Tributo.','\r',char(13)),'\n',char(10)),'Adicionar à mão','Reduzir o número de Tributos','Invocar por Invocação Normal sem Tributos (Feiticeiro Vampiro)','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88733579,'Inseto Broca','Quando este card causar dano de batalha ao seu oponente, você pode selecionar 1 card "Parasita Paracide" do seu Deck, embaralhar o Deck, e colocar "Parasita Paracide" no topo do seu Deck.','Adicionar à mão','Escolha o(s) card(s) para colocar no topo do Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88753594,'Dançarina de Lâminas Luzlunar',replace(replace('3 monstros "Luzlunar"	\r\nDeve ser Invocado por Invocação-Fusão. \r\nGanha 200 de ATK para cada monstro Besta-Guerreira que estiver banido ou nos Cemitérios. \r\nSeu oponente não pode escolher este card como alvo de efeitos de card. \r\nDurante sua Fase Principal, exceto no turno em que este card foi enviado para o Cemitério: você pode banir este card do seu Cemitério e, depois, escolha 1 Monstro de Fusão que você controla; ele ganha 3000 de ATK até o final deste turno. \r\nVocê só pode usar este efeito de "Dançarina de Lâminas Luzlunar" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88753985,'Fogo da Raposa',replace(replace('Durante a Fase Final, se este card foi destruído em batalha e enviado para o Cemitério neste turno e estava com a face para cima no começo da Etapa de Dano: Invoque este card por Invocação-Especial do Cemitério. \r\nEste card com a face para cima não pode ser oferecido como Tributo para uma Invocação-Tributo.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88754763,'CXyz Senhor Técnico Treinador Definitivo',replace(replace('4 monstros de Nível 9	\r\nEste card não pode ser alvo de efeitos de card. \r\nSe este card tiver um Monstro Xyz como uma Matéria Xyz, ele ganha este efeito.\r\n● Uma vez por turno: você pode desassociar 1 Matéria Xyz deste card; compre 1 card e revele-o e, depois, se esse card era um monstro, cause 800 de dano ao seu oponente.','\r',char(13)),'\n',char(10)),'Comprar','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88757791,'Mago do Olho-Dharma',replace(replace('Escala de Pêndulo = 2\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno: você pode revelar 1 Monstro Pêndulo da sua mão e, depois, escolher 1 card "Mago" nas suas Zonas de Pêndulo; até o final deste turno, a Escala de Pêndulo do alvo se torna a mesma que a do Monstro Pêndulo revelado (mesmo que este card deixe o campo).\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nEnquanto este card Invocado por Invocação-Pêndulo estiver no campo, Monstros Pêndulo "Mago" que você controla não podem ser destruídos por efeitos de card do seu oponente durante o turno em que este card foi Invocado por Invocação-Pêndulo.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88760522,'Evo-Diversidade',replace(replace('Adicione 1 monstro "Evoltil" ou "Evolssauro" do seu Deck à sua mão. \r\nVocê só pode ativar 1 "Evo-Diversidade" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88774734,'Dragão da Espiral Galáctica',replace(replace('Enquanto este card estiver na sua mão ou no Cemitério, se você controlar 2 ou mais monstros Dragão de LUZ e/ou de TREVAS: você pode Invocar este card por Invocação-Especial em Posição de Defesa, mas bana-o quando ele deixar o campo. \r\nDurante sua Fase Principal: você pode fazer com que todos os monstros que você controla atualmente se tornem de Nível 8 até o final deste turno. \r\nVocê só pode usar cada efeito de "Dragão da Espiral Galáctica" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88789641,'Barreira de Vida Mística','Descarte 1 card; você não sofre dano dos cards do seu oponente neste turno e, além disso, seus monstros não podem ser destruídos em batalha neste turno.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88819587,'Dragão Filhote','Muito mais que um filhote, este dragão é dotado de poderes ainda não revelados.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88820235,'Fênix Executor Radiante, o HERÓI do Elemento',replace(replace('"Fênix Executor, o HERÓI do Elemento" + "Sparkman, o HERÓI do Elemento"	\r\nDeve ser Invocado por Invocação-Fusão e não pode ser Invocado por Invocação-Especial de nenhuma outra forma. \r\nEste card ganha 300 de ATK para cada card "HERÓI do Elemento" no seu Cemitério. \r\nEste card não pode ser destruído em batalha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88836438,'Esmagadores Spright',replace(replace('Bana 1 card "Springans", "Therion" ou "Spright" da sua mão ou do Cemitério e, depois, ative 1 desses efeitos;\r\n● Invoque por Invocação-Especial 1 monstro "Springans" do seu Deck.\r\n● Invoque por Invocação-Especial 1 monstro "Therion" do seu Cemitério.\r\n● Bana 1 monstro de Nível/Classe/Link 2 que você controla e 1 card que seu oponente controla.	\r\nVocê só pode ativar 1 "Esmagadores Spright" por turno.','\r',char(13)),'\n',char(10)),'Invoque por Invocação Especial 1 monstro "Springans" do Deck','Invoque por Invocação Especial 1 monstro "Therion" do seu Cemitério','Banir 1 card que você controla e 1 card que seu oponente controla','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88845345,'Elephun','Quando este card for destruído em batalha e enviado ao Cemitério, você pode selecionar 1 dos seus monstros do Tipo Besta, Tipo Besta-Guerreira ou Tipo Besta Alada de Nível 3 ou menos que estiver removido de jogo e adicioná-lo à sua mão.','Adicionar à mão','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88851326,'Legado do Duelista',replace(replace('Quando seu monstro declarar um ataque: você pode escolher 1 Card de Magia/Armadilha que seu oponente controla; negue o ataque e, se isso acontecer, destrua esse card. \r\nCada duelista só pode Baixar 1 Card de Magia/Armadilha da sua mão por turno. \r\nMonstros não podem atacar no turno em que são Invocados por Invocação-Especial do Deck Adicional. \r\nDurante sua Fase de Compra, antes da compra: você pode adicionar 1 monstro do seu Cemitério à sua mão e, além disso, você não pode conduzir sua compra normal neste turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88875132,'Ferrovia Célere Pégaso Alado',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 monstro Máquina de TERRA no seu Cemitério, exceto "Ferrovia Célere Pégaso Alado"; Invoque-o por Invocação-Especial em Posição de Defesa, mas negue seus efeitos. \r\nVocê pode escolher 1 outro monstro com a face para cima que você controla; o Nível desse monstro se torna o deste card, ou o Nível deste card se torna o desse monstro. \r\nVocê não pode declarar ataques no turno em que ativar este efeito, exceto com Monstros Xyz. \r\nVocê só pode usar cada efeito de "Ferrovia Célere Pégaso Alado" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Escolha um monstro com o Nível alvo','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88875133,'Ferrovia Célere Pégaso Alado',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode escolher 1 monstro Máquina de TERRA no seu Cemitério, exceto "Ferrovia Célere Pégaso Alado"; Invoque-o por Invocação-Especial em Posição de Defesa, mas negue seus efeitos. \r\nVocê pode escolher 1 outro monstro com a face para cima que você controla; o Nível desse monstro se torna o deste card, ou o Nível deste card se torna o desse monstro. \r\nVocê não pode declarar ataques no turno em que ativar este efeito, exceto com Monstros Xyz. \r\nVocê só pode usar cada efeito de "Ferrovia Célere Pégaso Alado" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Escolha um monstro com o Nível alvo','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88890658,'Baelgrill de Nouvelles',replace(replace('Você pode Invocar este card por Invocação-Ritual com um card "Receita". \r\nSe este card for Invocado por Invocação-Especial: você pode negar os efeitos de todos os cards com a face para cima que seu oponente controla atualmente (até o final deste turno) e, depois, se este card foi Invocado por Invocação-Especial pelo efeito de um monstro "Nouvelles", você pode oferecer como Tributo tantos monstros que seu oponente controla quanto possível. \r\n(Efeito Rápido): você pode escolher 1 monstro em Posição de Ataque que seu oponente controla; ofereça-o como Tributo e, se isso acontecer, Invoque por Invocação-Especial 1 "Hambúrguer Esfomeado" da sua mão ou do Deck. \r\nVocê só pode usar cada efeito de "Baelgrill de Nouvelles" uma vez por turno.','\r',char(13)),'\n',char(10)),'Negue o card do seu oponente','Invocar por Invocação Especial da sua mão/Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88901771,'Mago Azul Habilidoso',replace(replace('Sempre que um Card de Magia for ativado, coloque 1 Marcador de Magia neste card quando essa Magia resolver (máx. 3). \r\nVocê pode oferecer como Tributo este card com 3 Marcadores de Magia nele; Invoque por Invocação-Especial 1 monstro "Gaia, o Cavaleiro Impetuoso" da sua mão, do Deck ou do Cemitério. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 card que você controla no qual possa colocar um Marcador de Magia; coloque 1 Marcador de Magia nele.','\r',char(13)),'\n',char(10)),'Colocar 1 Marcador de Magia','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88901994,'Estrondo Sincro',replace(replace('Escolha 1 Regulador ou 1 Monstro Sincro Dragão de Nível 7 ou 8 no seu Cemitério; Invoque-o por Invocação-Especial em Posição de Defesa e, além disso, pelo resto deste turno depois que este card resolver, você não pode Invocar por Invocação-Especial do Deck Adicional, exceto Monstros Sincro. \r\nSe um ou mais Monstros Sincro Dragão de Nível 7 ou 8 ou "Dragão Carmesim" que você controla seriam destruídos em batalha ou por um efeito de card, em vez disso, você pode banir este card do seu Cemitério. \r\nVocê só pode ativar 1 "Estrondo Sincro" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88917691,'Garota Gagagaga',replace(replace('2 monstros de Nível 4	\r\nSe este card tiver um card "Zubaba", "Gagaga", "Gogogo" ou "Dododo" como matéria: você pode desassociar 1 matéria deste card; adicione 1 card "Gagaga", "Onomat" ou "Xyz" do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Garota Gagagaga" uma vez por turno. \r\nUm Monstro Xyz "Futuro Utópico" que tenha este card como matéria ganha este efeito.\r\n● Se este card for Invocado por Invocação-Xyz: este card pode realizar um segundo ataque durante cada Fase de Batalha neste turno.','\r',char(13)),'\n',char(10)),'','Atacar duas vezes (Garota Gagagaga)','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88919365,'Hojo, o Guerreiro Vaylantz',replace(replace('Escala de Pêndulo = 1\r\n[ Efeito de Pêndulo ]\r\nSe "Mundo Vaylantz - Shinra Bansho" estiver em uma Zona do Campo ou se você controlar um monstro "Vaylantz" de ÁGUA: você pode Invocar este card por Invocação-Especial na sua Zona de Monstros Principal em sua mesma coluna. \r\nVocê só pode usar este efeito de "Hojo, o Guerreiro Vaylantz" uma vez por turno.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nVocê pode escolher 1 card com a face para cima em qualquer Zona de Magias & Armadilhas; devolva-o para a mão. \r\nSe este card na Zona de Monstros se mover para outra Zona de Monstros (exceto durante a Etapa de Dano): você pode Invocar por Invocação-Fusão 1 Monstro de Fusão "Vaylantz" do seu Deck Adicional, usando monstros da sua mão, do campo e/ou das Zonas de Pêndulo. \r\nVocê só pode usar cada efeito de "Hojo, o Guerreiro Vaylantz" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88923963,'Nobre Cavaleiro Iyvanne',replace(replace('Se uma Magia de Equipamento "Armas Nobres" se tornar equipada a este card: você pode Invocar por Invocação-Especial 1 "Ficha de Nobre Cavaleiro" (Guerreiro/LUZ/Nível 4/ATK 1000/DEF 1000) e, além disso, você não pode Invocar monstros por Invocação-Especial pelo resto deste turno, exceto monstros "Nobre Cavaleiro". \r\nVocê só pode usar este efeito de "Nobre Cavaleiro Iyvanne" uma vez por turno. \r\nEnquanto este card estiver equipado com uma Magia de Equipamento "Armas Nobres", todos os outros monstros "Nobre Cavaleiro" que você controla ganham 500 de ATK.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88923964,'Ficha de Nobre Cavaleiro','Invocada por Invocação-Especial com o efeito "Nobre Cavaleiro Iyvanne".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88926295,'Evigishki Neremanas',replace(replace('Você pode Invocar este card por Invocação-Ritual com qualquer Magia de Ritual "Gishki". \r\nSe este card for Invocado por Invocação-Ritual: você pode escolher 1 monstro de ÁGUA no seu Cemitério; Invoque-o por Invocação-Especial. \r\nNão pode ser destruído em batalha com um monstro Invocado por Invocação-Especial do Deck Adicional. \r\nUma vez por turno, quando seu oponente ativar um efeito de monstro (Efeito Rápido): você pode devolver 1 Monstro de Ritual "Gishki" que você controla para a mão e, se isso acontecer, negue a ativação e, se isso acontecer, embaralhe-o no Deck.','\r',char(13)),'\n',char(10)),'Invoque por Invocação Especial um monstro do Cemitério','Negar e retornar ao Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88928798,'Minas Guardiãs',replace(replace('Só pode ser ativado quando um card for ativado com um efeito que escolheria e destruiria 1 monstro que você controla. \r\nNegue o efeito e destrua esse card. \r\nDepois, cause 500 de dano ao seu oponente.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88931417,'Ogro Giratório',replace(replace('Você pode enviar qualquer número de cards Baixados da sua Zona de Magias & Armadilhas para o Cemitério; cause 800 de dano ao seu oponente para cada, seu oponente também não recebe dano de efeitos de monstros não-Demônio pelo resto deste turno. \r\nVocê só pode usar este efeito de "Ogro Giratório" uma vez por turno.\r\nUma vez por turno, quando este card for escolhido por um ataque: você pode causar 500 de dano ao seu oponente para cada monstro em Posição de Defesa dele, então encerre a Fase de Batalha.','\r',char(13)),'\n',char(10)),'Causar dano','Causar dano e encerrar a Fase de Batalha','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88935103,'Mago do Dragão Nobre',replace(replace('Escala de Pêndulo = 5\r\n[ Efeito de Pêndulo ]\r\nDestrua este card a não ser que você tenha um card "Mago" na sua outra Zona de Pêndulo.\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nNão pode ser usado como Matéria Sincro, exceto para a Invocação-Sincro de um Monstro Sincro Dragão. \r\nSe este card for usado como Matéria Sincro, coloque-o no fundo do Deck, a não ser que todas as outras Matérias Sincro sejam monstros "Olhos Anômalos". \r\nSe este card estiver na sua mão ou no Cemitério: você pode escolher 1 monstro "Olhos Anômalos" de Nível 7 ou mais que você controla; reduza o Nível dele em 3 e, se isso acontecer, Invoque este card por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Ativar na Zona de Pêndulo','Invocação Especial','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88940154,'Centopeia Bujingi',replace(replace('Se você controlar um monstro "Bujin" do Tipo Besta-Guerreira: você pode banir este card do seu Cemitério e, depois, escolher 1 Card de Magia/Armadilha que seu oponente controla; destrua o alvo. \r\nVocê só pode usar o efeito de "Centopeia Bujingi" uma vez por turno.','\r',char(13)),'\n',char(10)),'Destruir Magias/Armadilhas','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88942504,'Melomelodia, o Djinn das Trompas',replace(replace('2 monstros de Nível 3	\r\nUma vez por turno: você pode desassociar 1 Matéria Xyz deste card e, depois, escolher 1 Monstro Xyz "Djinn" que você controla; ele pode realizar um segundo ataque durante cada Fase de Batalha neste turno.','\r',char(13)),'\n',char(10)),'Ataques múltiplos','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88958576,'Queimador Laval','Se você tiver 3 ou mais monstros "Laval" com nomes diferentes no seu Cemitério, você pode Invocar este card por Invocação-Especial (da sua mão).','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88962829,'Voador Leve Bezoudado',replace(replace('Se este card for Invocado por Invocação-Normal ou Especial: você pode escolher 2 dos seus monstros "Bezoudado" com nomes diferentes, que estiverem banidos e/ou no seu Cemitério; adicione-os à sua mão, mas pelo resto deste turno, você não pode ativar os efeitos deles, ou os efeitos de cards com o nome deles. \r\nQuando um monstro do oponente declarar um ataque: você pode devolver este card para a mão e, se isso acontecer, negue o ataque. \r\nVocê só pode usar cada efeito de "Voador Leve Bezoudado" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88975532,'Lobo de Guerra Negro como Azeviche','Seu oponente não pode ativar Cards de Armadilha durante a Fase de Batalha.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88979991,'Ferroada Letal','Uma abelha enorme com uma força excepcional, particularmente perigosa em enxames.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88989706,'Grandioso Dezard',replace(replace('Quando este card destrói o número seguinte de monstros como resultado de um combate, este card obtém o(s) seguinte(s) efeito(s):\r\nUm: Anule a ativação e os efeitos de todos os Cards de Magia e de Armadilha que designam este card no Campo com a face para cima como alvo, e os destrói.\r\nDois: Você pode Invocar por Invocação-Especial 1 "Fushioh Richie" da sua mão ou do seu Deck oferecendo este card como Tributo durante a sua Main Phase.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88996322,'Besta Gladiadora Vespasio',replace(replace('No começo da Etapa de Dano, se um monstro "Besta Gladiadora" seu batalhar um monstro: você pode Invocar este card por Invocação-Especial da sua mão. \r\nVocê só pode usar este efeito de "Besta Gladiadora Vespasio" uma vez por turno. \r\nEnquanto você controlar este card Invocado por Invocação-Especial pelo efeito de um monstro "Besta Gladiadora", todos os monstros que você controla ganham 500 de ATK. \r\nNo final da Fase de Batalha, se este card batalhou: você pode embaralhar este card no Deck; Invoque por Invocação-Especial 1 monstro "Besta Gladiadora" do seu Deck, exceto "Besta Gladiadora Vespasio".','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89015998,'Caçador D.D.',replace(replace('(Efeito Rápido): você pode escolher 1 monstro com a face para cima que você controla; bana-o até a Fase Final do próximo turno. \r\nVocê só pode usar este efeito de "Caçador D.D." uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89016236,'Poeltis de Nouvelles',replace(replace('Você pode Invocar este card por Invocação-Ritual com um card "Receita". \r\nSe este card for Invocado por Invocação-Especial: você pode comprar 1 card. \r\nQuando um card ou efeito for ativado que escolha um monstro no campo como alvo, ou quando um monstro for alvo de um ataque (Efeito Rápido): você pode oferecer como Tributo 1 monstro "Nouvelles" que você controla e 1 monstro em Posição de Ataque em qualquer campo e, se isso acontecer, Invoque por Invocação-Especial 1 Monstro de Ritual "Nouvelles" de Nível 4 ou 5 da sua mão ou do Deck. \r\nVocê só pode usar cada efeito de "Poeltis de Nouvelles" uma vez por turno.','\r',char(13)),'\n',char(10)),'Compre 1 card(s)','Invocar por Invocação Especial da sua mão/Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89019964,'Alma Desacorrentada do Desastre',replace(replace('Ganha 300 de ATK para cada card "Desacorrentado(a)" no seu Cemitério. \r\nVocê só pode usar cada um dos seguintes efeitos de "Alma Desacorrentada do Desastre" uma vez por turno.\r\n● Você pode escolher 1 monstro com a face para cima que seu oponente controla; imediatamente depois que este efeito resolver, Invoque por Invocação-Link 1 Monstro Link de TREVAS usando apenas este card que você controla e esse monstro do oponente como matéria.\r\n● Se este card no campo for destruído em batalha ou por um efeito de card: você pode escolher 1 monstro "Desacorrentado(a)" no seu Cemitério, exceto "Alma Desacorrentada do Desastre"; Invoque-o por Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89023486,'Despojos do Pecado Original - Olho de Cobra',replace(replace('Envie para o Cemitério 1 outro card com a face para cima que você controla; Invoque por Invocação-Especial 1 monstro de FOGO de Nível 1 da sua mão ou do Deck. \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 1 monstro "Olho de Cobra" ou "Diabellstar" no seu Cemitério; adicione 1 monstro de FOGO de Nível 1 do seu Deck à sua mão e, depois, coloque o monstro alvo no fundo do Deck. \r\nVocê só pode usar 1 efeito de "Despojos do Pecado Original - Olho de Cobra" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89027418,'Troca do Impostor',replace(replace('Quando um efeito de monstro que foi ativado no campo do seu oponente ao escolher como alvo um ou mais cards no campo resolver, se qualquer desses alvos estava em uma coluna diferente da do monstro do oponente, ele pode banir 1 card do Cemitério dele. \r\nSe ele não o fez, negue o efeito ativado. \r\nVocê pode banir 1 monstro do seu Cemitério; Invoque por Invocação-Especial 1 "Ficha de Impostor" (Psíquico/TERRA/ATK 800/DEF 800) com o mesmo Nível que o desse monstro. \r\nVocê só pode usar este efeito de "Troca do Impostor" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Invocação Especial','Banir 1 card? (Troca do Impostor)','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89027419,'Ficha de Impostor','Invocado por Invocação-Especial pelo efeito de "Troca do Impostor".','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89040386,'Asanegra - Choque de Retorno','Quando um monstro do oponente declarar um ataque direto enquanto você tiver 5 ou mais monstros "Asanegra" no seu Cemitério: destrua todos os monstros que seu oponente controla.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89041555,'Explosão Causada por um Tributo','Quando um monstro do oponente que foi Invocado por Invocação-Tributo declarar um ataque: destrua tantos monstros com a face para cima em Posição de Ataque que ele controla quanto possível e, se isso acontecer, cause 1000 de dano ao seu oponente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89055154,'Poderosa Anja Valquíria',replace(replace('Se você negar a ativação de um Card de Magia/Armadilha ou efeito de monstro: adicione 1 monstro Fada de LUZ do seu Deck à sua mão. \r\nVocê só pode usar este efeito de "Poderosa Anja Valquíria" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89058026,'Onda EN',replace(replace('Se um monstro "HERÓI do Elemento" seu for usado como matéria para uma Invocação-Fusão e enviado para o Cemitério ou banido (exceto durante a Etapa de Dano): você pode Invocar por Invocação-Especial 1 monstro "Neoespacial" ou 1 "Neos, o HERÓI do Elemento" do seu Deck. \r\nSe um monstro "Neoespacial" ou "Neos, o HERÓI do Elemento" que você controla ou no seu Cemitério for embaralhado no seu Deck ou Deck Adicional (exceto durante a Etapa de Dano): você pode Invocar por Invocação-Especial 1 monstro "HERÓI do Elemento" do seu Cemitério. \r\nVocê só pode usar cada efeito de "Onda EN" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89086566,'Detonar','Destrua tantos "Kuriboh" e "Ficha de Kuriboh" que você controla quanto possível e, depois, destrua cards que seu oponente controla, até o número de cards destruídos por este efeito.','Destruir 1 card que seu oponente controla?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89086647,'Contagem de Pratos de Okiku',replace(replace('Uma vez por Corrente, quando seu oponente ativar um card ou efeito: você pode colocar Marcadores de Pratos neste card, igual ao número do Elo de Corrente deste efeito. \r\nAplique este efeito dependendo do número de Marcadores de Pratos neste card.\r\n● 9 ou menos: Seu oponente não pode escolher este card como alvo de efeitos de card e, além disso, ele não pode ser destruído pelos efeitos de card do seu oponente.\r\n● 10+: Envie este card para o Cemitério.	\r\nSe este card for enviado para o Cemitério por seu próprio efeito: você pode enviar os 10 cards do topo do seu Deck para o Cemitério.','\r',char(13)),'\n',char(10)),'Colocar um marcador','Enviar para o Cemitério','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89091579,'Inseto Básico','Geralmente encontrado em enxames, o habitat desse inseto é a floresta.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89091772,'Samurai Superpesado Magnético',replace(replace('Quando este card for Invocado por Invocação-Normal: você pode Invocar por Invocação-Especial 1 monstro "Samurai Superpesado" de Nível 4 ou menos da sua mão e, depois, coloque este card em Posição de Defesa. \r\nOs monstros que seu oponente controla não podem atacar nenhum monstro, exceto este.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89111398,'Espírito de Pó das Trevas',replace(replace('Não pode ser Invocado por Invocação-Especial. \r\nDurante a Fase Final do turno em que este card for Invocado por Invocação-Normal ou virado com a face para cima: devolva-o para a mão. \r\nQuando este card for Invocado por Invocação-Normal ou virado com a face para cima: destrua todos os outros monstros com a face para cima no campo.','\r',char(13)),'\n',char(10)),'Retornar à mão','Destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89112729,'Ciber Saurus',replace(replace('"Malabarista Explosivo" + "Rei Rex de Duas Cabeças"	\r\n\r\n(Este card não é considerado como um card "Ciber".)','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89113320,'Camarartista Mordiscotartaruga',replace(replace('Escala de Pêndulo = 3\r\n[ Efeito de Pêndulo ]\r\nUma vez por turno: você pode revelar 1 monstro "Camarartista" ou "Olhos Anômalos" na sua mão e, se isso acontecer, pelo resto deste turno, reduza em 1 o Nível dos monstros na sua mão com esse nome (mesmo depois que eles forem Invocados/Baixados e mesmo que este card deixe o campo).\r\n----------------------------------------\r\n[ Efeito de Monstro ]\r\nQuando este card for destruído em batalha: você pode destruir o monstro que o destruiu.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89127526,'Ressonador da Barreira','(Efeito Rápido): você pode enviar este card da sua mão para o Cemitério e, depois, escolha 1 Regulador que você controla; neste turno, ele não pode ser destruído em batalha e, além disso, você não sofre dano de batalha dos ataques que o envolvam.','Não pode ser destruído em batalha','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89132148,'Orbital de Fóton',replace(replace('Durante sua Fase Principal: você pode escolher 1 monstro "Fóton" ou "Galáxia" que você controla; equipe este monstro da sua mão ou do campo no alvo. \r\nEle ganha 500 de ATK e, além disso, ele não pode ser destruído em batalha. \r\nVocê pode enviar este Card de Equipamento para o Cemitério; adicione 1 monstro "Fóton" ou "Galáxia" do seu Deck à sua mão, exceto "Orbital de Fóton". \r\nVocê só pode usar este efeito de "Orbital de Fóton" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89172051,'Legatus Dragunidade',replace(replace('Se você controlar "Ravina de Dragões" ou um monstro "Dragunidade": você pode Invocar este card por Invocação-Especial da sua mão. \r\nSe um ou mais Cards de Monstro "Dragunidade" estiverem na sua Zona de Magias & Armadilhas: você pode escolher 1 Magia/Armadilha no campo; destrua-a. \r\nVocê só pode usar cada efeito de "Legatus Dragunidade" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89176044,'Predaprimitivo',replace(replace('Envie 1 card "Predap" do seu Deck para o Cemitério, exceto "Predaprimitivo"; adicione 1 Magia "Polimerização" ou Magia "Fusão" do seu Deck à sua mão e, além disso, você não pode Invocar por Invocação-Especial pelo resto deste turno depois que este card resolver, exceto monstros Planta ou Dragão. \r\nSe um ou mais monstros forem Invocados por Invocação-Especial no campo do seu oponente (exceto durante a Etapa de Dano): você pode banir este card do seu Cemitério e, depois, escolha 1 Monstro de Fusão que você controla; destrua-o. \r\nVocê só pode ativar 1 "Predaprimitivo" por turno.','\r',char(13)),'\n',char(10)),'Ativar','Destruir','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89181134,'Predaplanta Lagarto Orvalhinha',replace(replace('Monstros com um Marcador de Predador que você usar como Matérias de Fusão são considerados de TREVAS. \r\nDurante sua Fase Principal: você pode Invocar por Invocação-Fusão 1 Monstro de Fusão de TREVAS do seu Deck Adicional, usando este card no campo e monstros da sua mão, do campo e/ou monstros com um Marcador de Predador que seu oponente controla como Matéria de Fusão. \r\nVocê só pode usar este efeito de "Predaplanta Lagarto Orvalhinha" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89181369,'Brilho da Poeira Estelar',replace(replace('Selecione 1 Monstro Sincro do Tipo Dragão no seu Cemitério. \r\nRemova de jogo outros monstros no seu Cemitério cuja soma dos Níveis seja igual ao Nível do monstro selecionado e Invoque-o por Invocação-Especial do Cemitério.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89185742,'Relâmpago, Dragão Soberano dos Vendavais',replace(replace('Você pode descartar este card e 1 monstro Dragão ou de VENTO; Invoque por Invocação-Especial 1 "Temporal, Dragão Soberano das Tempestades" do seu Deck, mas ele não pode atacar neste turno. \r\nVocê só pode usar este efeito de "Relâmpago, Dragão Soberano dos Vendavais" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89189982,'Dragão Armado Metafis','Normalmente visível apesar de sua existência fantasmal.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89190953,'Destruição da Dimensão Fusão',replace(replace('Bana da sua mão, do campo e/ou do Cemitério, as Matérias de Fusão que estiverem listadas em um Monstro de Fusão "Fantasma" e, depois, Invoque por Invocação-Especial esse Monstro de Fusão do seu Deck Adicional, ignorando suas condições de Invocação. \r\nVocê não sofre dano de batalha dos ataques envolvendo o monstro Invocado por Invocação-Especial por este efeito. \r\nSe você controlar "Uria, o Senhor das Chamas Cortantes", "Hamon, o Senhor do Trovão Impactante" ou "Raviel, o Senhor dos Fantasmas", seu oponente não pode ativar cards ou efeitos em resposta à ativação deste card.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89194033,'Besta Mística de Serket',replace(replace('Se você não controlar "Templo dos Reis", destrua este card. \r\nBana quaisquer monstros destruídos em batalha com este card. \r\nSe este card destruir um monstro em batalha: ele ganha 500 de ATK.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89194103,'Kudabbi, o Mitológico',replace(replace('1 Regulador "Mitológico(a)" + 1+ monstros não-Reguladores	\r\nEste card ganha o seguinte efeito de acordo com o número de cards na sua mão.\r\n● 0: Não pode ser destruído em batalha ou por efeitos de card.\r\n● 3+: Uma vez por turno, durante a Fase Final: destrua este card.','\r',char(13)),'\n',char(10)),'Destruir este card','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89208725,'Metaverso','Pegue 1 Magia de Campo do seu Deck e ative-a ou adicione-a à sua mão.','Escolha 1 Card de Magia de Campo','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89211486,'Dr. Genex','Você pode oferecer como Tributo 1 "Controlador Genex" com a face para cima para selecionar e destruir 1 card no campo.','Destruir','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89222931,'Protótipo de Rei Máquina','Este card ganha 100 de ATK e DEF para cada monstro do Tipo Máquina no campo, exceto este card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89226534,'Renascimento do Enxame',replace(replace('Escolha 1 monstro "Vespabatalha" no seu Cemitério; Invoque-o por Invocação-Especial. \r\nVocê pode banir este card do seu Cemitério e, depois, escolher 1 monstro Inseto que você controla; até o final do próximo turno, ele não pode ser destruído em batalha ou por efeitos de card. \r\nVocê só pode usar este efeito de "Renascimento do Enxame" uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocação Especial','Proteção contra destruição','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89235196,'Guerreiro Mega-Um','Durante sua Fase Principal, você pode enviar 1 monstro de Nível 1, exceto este card, da sua mão para o Cemitério para Invocar por Invocação-Especial este card da sua mão.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89238128,'Acelerador Ciberso',replace(replace('2+ monstros, exceto Fichas	\r\nDurante a Fase de Batalha (Efeito Rápido): você pode escolher 1 monstro Ciberso para o qual este card apontar e ativar 1 desses efeitos;\r\n● Ele ganha 2000 de ATK até o final deste turno.\r\n● Ele pode realizar até 2 ataques contra monstros durante cada Fase de Batalha neste turno.	\r\nEste card não pode atacar no turno em que este efeito for ativado. \r\nVocê só pode usar este efeito de "Acelerador Ciberso" uma vez por turno.','\r',char(13)),'\n',char(10)),'Aumentar ATK','Ataques múltiplos','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89252153,'Necrosombra, o HERÓI do Elemento','Uma vez, enquanto este card estiver no Cemitério, você pode Invocar por Invocação-Normal 1 monstro "HERÓI do Elemento" de Nível 5 ou mais sem oferecer Tributo.','Invocar pelo efeito de "Necrosombra, o HERÓI do Elemento"','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89252157,'Amante das Rosas',replace(replace('Você pode banir este card do seu Cemitério; Invoque por Invocação-Especial 1 monstro Planta da sua mão e, se isso acontecer, ele não é afetado pelos efeitos de Armadilha do seu oponente neste turno. \r\nVocê só pode usar este efeito de "Amante das Rosas" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89258225,'Servo Alado','Ofereça este card com a face para cima como Tributo para escolher 1 monstro do Tipo Demônio e aumentar o seu ATK e DEF em 700 pontos enquanto permanecer com a face para cima no Campo.','Aumentar ATK/DEF','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89258906,'Asanegra - Brisa, o Zéfiro',replace(replace('Se este card for adicionado do seu Deck à sua mão por um efeito de card: você pode Invocar este card por Invocação-Especial da sua mão. \r\nNão pode ser usado como uma Matéria Sincro, exceto pela Invocação-Sincro de um monstro "Asanegra".','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89264428,'Grande Carro Ursártico',replace(replace('Uma vez por turno, se um monstro "Ursártico(a)" seu fosse oferecer um ou mais monstros como Tributo para ativar seu efeito, em vez disso, você pode banir 1 monstro "Ursártico(a)" de Nível 7 ou mais do seu Cemitério. \r\nSempre que um ou mais monstros forem Invocados por Invocação-Especial, coloque 1 marcador neste card. \r\nUma vez por turno, se um ou mais monstros forem Invocados por Invocação-Especial e um Monstro Sincro "Ursártico(a)" estiver no campo (exceto durante a Etapa de Dano): você pode remover todos os marcadores deste card (mín. 7) e, depois, escolha 1 monstro que seu oponente controla; tome o controle dele.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89272878,'Guardião do Labirinto','Um monstro que protege a entrada dos Mundos Baixos.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89310929,'Lorde Trovão do Vale das Névoas',replace(replace('1 Regulador + 1+ monstros "Vale das Névoas" não-Reguladores	\r\nUma vez por turno (Efeito Rápido): você pode escolher 1 outro card que você controla; devolva o alvo para a mão e, se isso acontecer, este card ganha 500 de ATK até o final deste turno.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89312388,'Prisma, o HERÓI do Elemento','Uma vez por turno: você pode revelar 1 Monstro de Fusão do seu Deck Adicional e, depois, envie 1 das Matérias de Fusão cujo nome seja mencionado nesse card do seu Deck para o Cemitério; até a Fase Final, o nome deste card se torna o nome desse monstro enviado.','Tornar do mesmo nome','Encerrar o efeito de “mesmo nome”','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89320376,'Peões do Legado Mundial',replace(replace('Você pode escolher 1 monstro com a face para baixo que você controla; coloque-o com a face para cima em Posição de Ataque ou Defesa. \r\nVocê pode embaralhar no Deck Principal 1 monstro "Krawler" do seu Cemitério e, depois, escolher 1 monstro com a face para cima que você controla; coloque-o com a face para baixo em Posição de Defesa. \r\nVocê só pode usar 1 efeito de "Peões do Legado Mundial" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Mude um monstro com a face para baixo para posição com a face para cima','Mude um monstro com a face para cima para posição com a face para baixo','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89326990,'Velocidaroide Garohajiki','Quando este card for Invocado por Invocação-Normal: você pode escolher 1 monstro Regulador no Cemitério de qualquer duelista; Invoque-o por Invocação-Especial no seu lado do campo e, se isso acontecer, imediatamente depois que este efeito resolver, Invoque por Invocação-Sincro 1 Monstro Sincro de VENTO, usando apenas esse monstro e este card.','Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89328238,'Equipe de Reforço',replace(replace('Compre cards igual ao número de cards que seu oponente controla e, depois, coloque cards da sua mão no fundo do Deck em qualquer ordem, igual ao número de cards que você comprou. \r\nDurante a Fase Final, se seu oponente controlar mais cards que você enquanto este card estiver no seu Cemitério: você pode Baixar este card, mas bana-o quando ele deixar o campo. \r\nVocê só pode usar 1 efeito de "Equipe de Reforço" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89333528,'Gaia Genex','Se este card no campo seria destruído em batalha ou por um efeito de card, em vez disso, você pode destruir 1 "Controlador Genex" que você controla.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89355716,'Tela do Clima Ensolarado',replace(replace('Monstros de Efeito "do Clima" nas suas Zonas de Monstros Principais da coluna deste card e das colunas adjacentes a ela ganham este efeito.\r\n● Você pode banir este card e, depois, escolher 1 monstro que você controla (Efeito Rápido); ofereça o alvo como Tributo e, se isso acontecer, Invoque por Invocação-Especial 1 monstro "do Clima" da sua mão ou do Cemitério, mas não com o mesmo nome que o monstro oferecido como Tributo tinha no campo.	\r\nVocê só pode controlar 1 "Tela do Clima Ensolarado".','\r',char(13)),'\n',char(10)),'Invoque por Invocação Especial 1 monstro "do Clima" (Tela do Clima Ensolarado)','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89357740,'Piloto da União',replace(replace('Uma vez por turno, você pode: escolher 1 Monstro de Efeito que você controla; equipe este card no alvo, OU: desequipe este card e Invoque-o por Invocação-Especial. \r\nSe o monstro equipado seria destruído em batalha ou por um efeito de card, em vez disso, destrua este card. \r\nVocê pode devolver à sua mão este card equipado a um monstro; equipe 1 monstro União banido apropriado a 1 monstro que você controla como uma Magia de Equipamento, como se tivesse sido equipado pelo efeito desse monstro União e, se isso acontecer, Invoque este card por Invocação-Especial da sua mão. \r\nVocê só pode usar este efeito de "Piloto da União" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','Retornar este card para a mão','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89362180,'Esqueletossauro',replace(replace('Este card é considerado um Monstro Normal enquanto estiver com a face para cima no campo ou no Cemitério. \r\nEnquanto este card for um Monstro Normal no campo, você pode Invocá-lo por Invocação-Normal para fazer com que ele se torne um Monstro de Efeito com esses efeitos.\r\n● Este card se torna de TERRA do Tipo Dinossauro.\r\n● Quando este card destruir um monstro do oponente em batalha e enviá-lo para o Cemitério: você pode Invocar esse monstro por Invocação-Especial no seu campo em Posição de Defesa e, se isso acontecer, ele se torna do Tipo Zumbi.','\r',char(13)),'\n',char(10)),'Invocação Especial','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89386122,'Clausolas, Aliado da Justiça','Um monstro poderoso do Vale das Névoas, e a arma definitiva criada a partir de Claiomh Solais. Seus ataques surpresa vindos das alturas confundem os invasores.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89392810,'Kewl Tune Reco',replace(replace('Se este card no campo seria usado como Matéria Sincro, 1 Regulador na sua mão pode ser usado como 1 das outras matérias. \r\nVocê só pode usar cada um dos seguintes efeitos de "Kewl Tune Reco" uma vez por turno. \r\nSe este card for Invocado por Invocação-Normal ou Especial: você pode adicionar 1 monstro "Kewl Tune" do seu Deck ou Cemitério à sua mão, exceto um monstro de Nível 3. \r\nSe este card for enviado para o Cemitério como Matéria Sincro: você pode escolher 1 Magia/Armadilha que seu oponente controla; destrua-a.','\r',char(13)),'\n',char(10)),'Efeito de busca','Efeito de destruição','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89397517,'Lenda do Coração',replace(replace('Pague 2000 PV e ofereça como Tributo 1 monstro Guerreiro; bana até 3 Magias "Dragão Lendário" com nomes diferentes da sua mão e/ou do Cemitério e, se isso acontecer, Invoque por Invocação-Especial o mesmo número de monstros "Cavaleiro Lendário" com nomes diferentes da sua mão, do Deck e/ou do Cemitério. \r\nVocê só pode ativar 1 "Lenda do Coração" por turno.','\r',char(13)),'\n',char(10)),'Continuar banindo?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89399912,'Temporal, Dragão Soberano das Tempestades',replace(replace('Você pode descartar este card e 1 monstro de VENTO para o Cemitério; adicione 1 monstro Dragão do seu Deck à sua mão. \r\nVocê pode banir um total de 2 monstros de VENTO e/ou Dragão da sua mão e/ou do Cemitério; Invoque este card por Invocação-Especial da sua mão ou do Cemitério. \r\nDurante a Fase Final do seu oponente, se você controlar este card Invocado por Invocação-Especial: devolva-o para a mão. \r\nSe este card for banido: você pode adicionar 1 monstro Dragão de VENTO do seu Deck à sua mão. \r\nVocê só pode usar 1 efeito de "Temporal, Dragão Soberano das Tempestades" por turno e apenas uma vez por turno.','\r',char(13)),'\n',char(10)),'Invocar por Invocação Especial da mão','Retornar à mão','Adicione à sua mão 1 monstro Dragão do seu Deck','Adicionar à mão','','','','','','','','','','','','');
INSERT INTO texts VALUES(89405199,'Ganância','Um jogador que compre card(s) pelo efeito de um card(s) recebe dano igual ao número de cards comprados pelo efeito do card x 500 pontos, no final da End Phase do turno.','Causar dano','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89423971,'Infernoide Patrulea',replace(replace('Não pode ser Invocado por Invocação-Normal/Baixado. \r\nDeve ser Invocado por Invocação-Especial (da sua mão) ao banir 1 monstro "Infernoide" da sua mão ou do Cemitério enquanto a soma dos Níveis e Classes de todos os Monstros de Efeito que você controla for 8 ou menos. \r\nUma vez por turno: você pode escolher 1 Magia/Armadilha no campo; destrua-a. \r\nEste card não pode atacar no turno em que este efeito for ativado. \r\nUma vez por turno do oponente (Efeito Rápido): você pode oferecer 1 monstro como Tributo e, depois, escolha 1 card no Cemitério do seu oponente; bana-o.','\r',char(13)),'\n',char(10)),'Destruir Magias/Armadilhas','Banir cards do Cemitério do seu oponente','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89448140,'Defesa dos Magos',replace(replace('Enquanto você controlar um monstro do Tipo Mago, qualquer dano que você sofrer é diminuído pela metade. \r\n(Você não pode diminuir o mesmo dano pela metade uma segunda vez desta forma.) \r\nSe este card for enviado do campo para o Cemitério: você pode escolher 1 monstro do Tipo Mago no seu Cemitério; Invoque-o por Invocação-Especial.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89450409,'Furacão da Dragunidade',replace(replace('Se somente seu oponente controlar um monstro: você pode Invocar por Invocação-Especial 1 Regulador "Dragunidade" e 1 monstro Besta Alada "Dragunidade" do seu Deck, mas negue seus efeitos e, depois, se seu oponente controlar um monstro que foi Invocado por Invocação-Especial do Deck Adicional, imediatamente depois que este efeito resolver, você pode Invocar 1 Monstro Sincro Dragão por Invocação-Sincro usando apenas monstros "Dragunidade" que você controla. \r\nPelo resto deste turno depois que este card resolver, você não pode Invocar monstros do Deck Adicional por Invocação-Especial, exceto monstros Dragão. \r\nVocê só pode ativar 1 "Furacão da Dragunidade" por turno.','\r',char(13)),'\n',char(10)),'','Invocação Sincro?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89462956,'Escolha do Carteador','Cada duelista embaralha seu Deck e, depois, cada duelista compra 1 card e, depois, cada duelista descarta 1 card.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89463537,'Necroz de Unicore',replace(replace('Você pode Invocar este card por Invocação-Ritual com qualquer Magia de Ritual "Necroz". \r\nDeve ser Invocado por Invocação-Ritual. \r\nVocê pode descartar este card e, depois, escolha 1 card "Necroz" no seu Cemitério, exceto "Necroz de Unicore"; adicione-o à sua mão. \r\nVocê só pode usar este efeito de "Necroz de Unicore" uma vez por turno. \r\nNegue os efeitos dos monstros com a face para cima no campo que foram Invocados por Invocação-Especial do Deck Adicional.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89474727,'Dragão da Centelha das Crônicas de Poeira Estelar',replace(replace('1 Monstro Sincro Regulador + 1+ Monstros Sincro não-Reguladores	\r\nDeve ser Invocado por Invocação-Sincro. \r\nUma vez por turno (Efeito Rápido): você pode banir 1 Monstro Sincro do seu Cemitério; este card não é afetado por outros efeitos de card pelo resto deste turno. \r\nSe este card em posse do seu dono for destruído por um card do oponente (em batalha ou por um efeito de card): você pode escolher 1 dos seus Monstros Sincro Dragão banidos; Invoque-o por Invocação-Especial.','\r',char(13)),'\n',char(10)),'Ativar o efeito de "Dragão da Centelha das Crônicas de Poeira Estelar"?','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89477759,'Número C1000: Numerounius',replace(replace('5 monstros de Nível 12	\r\nUma vez por turno (Efeito Rápido): você pode desassociar 1 matéria deste card; destrua 1 outro monstro no campo. \r\nNo final da Fase de Batalha: destrua tantos outros monstros no campo quanto possível (mín. 1) e, depois, você pode Invocar por Invocação-Especial no seu campo, em Posição de Defesa, 1 monstro do Cemitério do seu oponente. \r\nSe este card que você controla for destruído por um efeito de card do oponente enquanto tiver matéria e for enviado para o seu Cemitério: você pode Invocar por Invocação-Especial 1 "Número iC1000: Numerounius Numerounia" do seu Deck Adicional e, se isso acontecer, associe este card a ele como matéria.','\r',char(13)),'\n',char(10)),'Destrua 1 outro monstro no Campo','Destrua todos os outros monstros no Campo','','Invocar um monstro por Invocação Especial do Cemitério do seu oponente?','','','','','','','','','','','','');
INSERT INTO texts VALUES(89484053,'Salamagrande Toupeira',replace(replace('Durante sua Fase Principal, se você Invocou por Invocação-Link neste turno: você pode Invocar este card por Invocação-Especial da sua mão em uma zona sua para a qual um Monstro Link apontar. \r\nSe você não controlar nenhum monstro: você pode banir este card do seu Cemitério e, depois, escolher 5 cards "Salamagrande" no seu Cemitério; embaralhe-os no Deck e, depois, compre 2 cards. \r\nVocê só pode usar cada efeito de "Salamagrande Toupeira" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89493368,'Reator de Invocação ・FOGO',replace(replace('A primeira vez que um ou mais monstros forem Invocados no lado do campo do oponente em cada turno, cause 800 de dano ao seu oponente. \r\nDurante a Fase de Batalha do turno que este efeito foi ativado, você pode negar o ataque de 1 monstro que seu oponente controla. \r\nVocê pode enviar 1 "Reator de Armadilha・DO" com a face para cima, 1 "Reator de Magia・CÉU" com a face para cima e este card com a face para cima que você controla ao Cemitério para Invocar por Invocação-Especial 1 "Fortaleza Voadora FOGO DO CÉU" da sua mão, Deck ou Cemitério.','\r',char(13)),'\n',char(10)),'Causar dano','Negar o ataque','Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89494469,'Titã Negro do Terror','Diz-se que este demônio vive no mundo dos sonhos, uma vez que ataca seus inimigos durante o sono.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89516305,'Número 87: Rainha da Noite',replace(replace('3 monstros de Nível 8	\r\nUma vez por turno (Efeito Rápido): você pode desassociar 1 matéria deste card e, depois, ative 1 desses efeitos.\r\n● Escolha 1 Magia/Armadilha Baixada que seu oponente controla; enquanto este card estiver com a face para cima no campo, esse card Baixado não pode ser ativado.\r\n● Escolha 1 monstro Planta no campo; coloque o alvo com a face para baixo em Posição de Defesa.\r\n● Escolha 1 monstro com a face para cima no campo; o alvo ganha 300 de ATK.','\r',char(13)),'\n',char(10)),'Um Card de Magia/Armadilha Baixado não pode ser ativado','Mude 1 monstro Planta para Posição de Defesa com a face para baixo','Aumente o ATK de 1 monstro','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89521713,'Cachoassant Magidoce',replace(replace('Quando este card em sua posse for destruído por um card do oponente (seja em batalha ou por um efeito de card) e enviado ao seu Cemitério: Embaralhe este card no Deck. \r\nUma vez por turno: Você pode escolher 1 card "Magidoce" com a face para cima que você controla, exceto este card; devolva-o para a mão e, se isso acontecer, aumente o Nível deste card em 1 e o ATK em 300.','\r',char(13)),'\n',char(10)),'Retornar ao Deck','Retornar à mão','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89529919,'Rahz, Comandante-de-Campo','Quando este card for Invocado por Invocação-Normal ou Especial: Escolha 1 monstro do Tipo Guerreiro de Nível 4 ou menos do seu Deck, exceto "Rahz, Comandante-de-Campo", e coloque-o no topo do seu Deck.','Adicionar à mão','Escolha o(s) card(s) para colocar no topo do Deck','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89538537,'Sedabíquo Altergeist',replace(replace('(Efeito Rápido): você pode devolver 1 outro card "Altergeist" que você controla para a mão e, depois, escolha 1 card que seu oponente controla; devolva-o para a mão. \r\nSe este card for enviado do campo para o Cemitério: você pode escolher 1 Armadilha "Altergeist" no seu Cemitério; adicione esse card à sua mão. \r\nVocê só pode usar cada efeito de "Sedabíquo Altergeist" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89544521,'Jato Robô-secretário',replace(replace('1 Regulador + 1 ou mais monstros não-Reguladores	\r\nEste card ganha 500 de ATK e DEF para cada card "Robô-secretário" no campo. \r\nVocê só pode usar 1 dos seguintes efeitos de "Jato Robô-secretário" por turno e apenas uma vez por turno.\r\n● Você pode escolher 1 card "Robô-secretário" que você controla; destrua-o e, se isso acontecer, Invoque por Invocação-Especial 1 monstro "Robô-secretário" do seu Deck.\r\n● Você pode escolher 1 card "Robô-secretário" que você controla e 1 card com a face para cima no campo; destrua-os.','\r',char(13)),'\n',char(10)),'Invocação Especial','Destruir 1 card','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89547299,'Injetor do Poder','Uma vez por turno, você pode pagar 600 PV para fazer com que todos os monstros do Tipo Psíquico com a face para cima ganhem 500 de ATK durante este turno.','Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89552119,'Cavalo de Pepino',replace(replace('Este card na Zona de Monstros é enviado para o Cemitério, exceto durante a Fase de Batalha. \r\nNo começo da Fase de Batalha, se este card estiver no seu Cemitério: você pode enviar para o Cemitério 1 monstro Planta da sua mão ou do campo com a face para cima; Invoque este card por Invocação-Especial e, depois, você pode Invocar por Invocação-Especial no seu campo 1 monstro de qualquer Cemitério, mas envie esses monstros Invocados por Invocação-Especial para o Cemitério no final da Fase de Batalha. \r\nVocê só pode usar este efeito de "Cavalo de Pepino" uma vez por turno.','\r',char(13)),'\n',char(10)),'','Invocar por Invocação Especial 1 monstro?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89558090,'Prisioneiro das Trevas','Este monstro dobra a luz para esconder sua imagem dos olhos do oponente.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89558743,'Mundo Pequeno',replace(replace('Revele 1 monstro na sua mão, selecione 1 monstro do seu Deck que tenha exatamente 1 do mesmo Tipo, Atributo, Nível, ATK ou DEF e bana o monstro revelado da sua mão, com a face para baixo. \r\nDepois, adicione do Deck à sua mão, 1 monstro que tenha exatamente 1 do mesmo Tipo, Atributo, Nível, ATK ou DEF que o do monstro selecionado do seu Deck e bana o card selecionado do Deck, com a face para baixo. \r\nVocê só pode ativar 1 "Mundo Pequeno" por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89563150,'Efeito da Prata Brilhante',replace(replace('Ative apenas quando seu oponente ativar um Card de Armadilha que cause dano. \r\nNegue a ativação desse card e destrua-o e todos os Cards de Magia e Armadilha com a face para cima que seu oponente controla.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89567993,'Estagiária Amazoness',replace(replace('Monstros destruídos em batalha com este card são colocados no fundo do Deck em vez de irem para o Cemitério. \r\nSe este card destruir um monstro do oponente em batalha: ele ganha 200 de ATK.','\r',char(13)),'\n',char(10)),'Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89569453,'Buraco Armadilha do Banimento','Quando seu oponente Invocar um ou mais monstros com 1500 ou menos de ATK: bana, com a face para baixo, esse(s) monstro(s) com 1500 ou menos de ATK.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89571015,'Tempestade Críptica',replace(replace('Não pode atacar diretamente, nem atacar monstros na Zona de Monstros Adicional. \r\nNão é afetado por efeitos de monstro ativados na Zona de Monstros Adicional. \r\nNão pode ser destruído em batalha com monstros na Zona de Monstros Adicional.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89594399,'Coatl Reptiliana',replace(replace('Se você controlar um monstro Réptil de TREVAS: você pode Invocar este card por Invocação-Especial da sua mão e, depois, se seu oponente controlar quaisquer monstros com 0 de ATK, você pode Invocar por Invocação-Especial até esse mesmo número de monstros "Reptiliano(a)" da sua mão. \r\nVocê só pode usar este efeito de "Coatl Reptiliana" uma vez por turno. \r\nSe este card que você controla seria usado como Matéria Sincro para um monstro Réptil, você pode considerá-lo como um não-Regulador.','\r',char(13)),'\n',char(10)),'','Invocar por Invocação Especial mais monstros "Reptiliano(a)"?','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89604813,'Dragão Espírito Definitivo de Olhos Azuis',replace(replace('2+ Reguladores + 1 monstro "Olhos Azuis" não-Regulador	\r\nSeu oponente não pode banir cards do seu Cemitério. \r\nVocê só pode usar cada um dos seguintes efeitos de "Dragão Espírito Definitivo de Olhos Azuis" uma vez por turno. \r\nQuando um card ou efeito for ativado no campo (Efeito Rápido): você pode negar a ativação e, se isso acontecer, este card ganha 1000 de ATK até o final deste turno. \r\nSe este card for destruído em batalha ou por um efeito de card: você pode Invocar por Invocação-Especial 1 monstro Dragão de LUZ do seu Cemitério, exceto "Dragão Espírito Definitivo de Olhos Azuis".','\r',char(13)),'\n',char(10)),'Os cards no seu Cemitério não podem ser banidos pelo seu oponente','Negar a ativação','Invocação Especial','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89609515,'Phlogis Laval','Quando este card for enviado para o Cemitério: todos os monstros "Laval" que você controla atualmente ganham 300 de ATK.','Aumentar ATK','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89617515,'Peixe Folha Sem Vida',replace(replace('Quando este card for Invocado: você pode enviar 1 monstro Peixe do seu Deck para o Cemitério, exceto "Peixe Folha Sem Vida". \r\nVocê pode banir este card do seu Cemitério e, depois, escolha 3 monstros Peixe no seu Cemitério; embaralhe esses monstros no seu Deck e, depois, compre 1 card. \r\nVocê só pode usar cada efeito de "Peixe Folha Sem Vida" uma vez por turno.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89621922,'Escaravelho de Chamas Neoespacial','Ganha 400 de ATK para cada Magia/Armadilha que seu oponente controla.','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89628781,'Arte de Abrigo Ninjitsu',replace(replace('Ative este card ao escolher 1 monstro "Ninja" que você controla. \r\nEle não pode ser destruído em batalha.','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89631139,'Dragão Branco de Olhos Azuis','Este dragão lendário é uma poderosa máquina de destruição. Praticamente invencível, muito poucos enfrentaram esta magnífica criatura e viveram para contar a história.','','','','','','','','','','','','','','','','');
