INSERT INTO texts VALUES(89631146,'Dragão Branco de Olhos Azuis','Este dragão lendário é uma poderosa máquina de destruição. Praticamente invencível, muito poucos enfrentaram esta magnífica criatura e viveram para contar a história.','','','','','','','','','','','','','','','','');
